

namespace cpr.events {
	export interface CFetchEventOptions extends CEventOption {
		startRowIndex: number,
		rowCount: number,
		sortCondition: expression_string
	}

	export class CFetchEvent extends CEvent {
		constructor(type: string, options?: CFetchEventOptions) {
			super(type, options);
		}

		get startRowIndex(): number {
			return this._getOption("startRowIndex");
		}

		get rowCount(): number {
			return this._getOption("rowCount");
		}

		get sortCondition(): expression_string {
			return this._getOption("sortCondition");
		}
	}

}