namespace cpr {
	const log = logger("dep").log;
	const status = new class {
		depCollectingStack: _Dependency[][] = [];

		allSubscriptions: _DependencySubscription[] = [];
		identifiableSubscriptions: { [uuid: string]: _DependencySubscription } = {};
	};

	/**
	 * 디펜던시 구독 객체.
	 */
	class _DependencySubscription {
		_handler: DependencyHandler;
		_identifer?: string;
		_disposed: boolean = false;
		_healthChecker?: () => boolean

		constructor(id: string, handler: DependencyHandler);
		constructor(handler: DependencyHandler);
		constructor() {
			switch (arguments.length) {
				case 1: {
					this._handler = arguments[0];
					break;
				}
				case 2: {
					this._identifer = arguments[0];
					this._handler = arguments[1];
					break;
				}
			}
		}

		/**
		 * 구독의 유효성 체커를 등록 합니다.
		 * 디페던시 변경 통보시 유효성 테스트에 실패한 경우, 해당 구독은 취소된 것으로 간주합니다.
		 * @param checker 구독 유효성 평가 함수.
		 */
		_setHealthChecker(checker: () => boolean): void {
			this._healthChecker = checker;
		}

		/**
		 * 구독이 유효한지 확인 합니다.
		 * {@link _setHealthChecker}를 통해 지정된 구독 유효성 평가 함수가 사용됩니다.
		 */
		get _healthy(): boolean {
			if (this._healthChecker) {
				return this._healthChecker();
			} else {
				return true;
			}
		}

		/**
		 * 구독을 파기 합니다.
		 * 이미 파기된 구독의 경우 아무런 일도 하지 않습니다.
		 */
		_dispose(): void {
			if (this._disposed) {
				return;
			}
			this._disposed = true;
			let idx = status.allSubscriptions.indexOf(this);
			if (idx >= 0) {
				status.allSubscriptions.splice(idx, 1);
				let leftCount = status.allSubscriptions.length;
				log(`디펜던시 구독 해제, 구독 수: ${leftCount}`);

				if (leftCount === 0) {
					log("모든 디펜던시 구독이 해제되었습니다.");
				}
			}

		}
	}

	type DependencyHandler = (dep: _Dependency) => void;

	class _Dependency {
		_segments: string[];

		constructor(depExpression: string) {
			if (utils.Util.isNullOrEmpty(depExpression)) {
				throw new exceptions.IllegalArgumentException();
			}
			this._segments = depExpression.split("/");
		}

		/**
		 * 의존성 식별 ID를 얻습니다.
		 */
		get identifier(): string {
			return this._segments.join("/")
		}

		/**
		 * 해당 의존성아 다른 의존성을 포함하는지 여부를 얻습니다.
		 * 예를 들어 DataMap을 재 구성할 때 발생하는 의존성 변경은 DataMap의 특정 컬럼 값을 변경할 때 발생하는 의존성을 포함 합니다.
		 * 
		 * @param otherDependency  포함 여부를 확인할 다른 의존성.
		 * @returns 의존성의 포함 여부.
		 */
		contains(otherDependency: _Dependency): boolean {
			if (otherDependency._segments.length < this._segments.length) {
				return false;
			}

			return this._segments.every((each, idx) => each === otherDependency._segments[idx]);
		}

		/**
		 * 동일한 의존성인지 확인 합니다.
		 * @param otherDependency 동일성 여부를 확인할 다른 의존성.
		 * 
		 * @returns 의존성의 동일 여부.
		 */
		equals(otherDependency: _Dependency): boolean {
			if (otherDependency._segments.length !== this._segments.length) {
				return false;
			}

			return this._segments.every((each, idx) => {
				return each === otherDependency._segments[idx];
			});
		}
	}

	/**
	 * 현재 수집 중인 의존성 프레임을 얻습니다.
	 * 존재하지 않는 경우 null 이 반환 됩니다.
	 * 
	 * @returns 현재 수집 중인 의존성 프레임.
	 */
	function _getActiveDependencyCollection(): _Dependency[] {
		return status.depCollectingStack[status.depCollectingStack.length - 1];
	}

	function _collectDependency(dep: _Dependency) {
		let frame = _getActiveDependencyCollection();

		// 디펜던시 수집 중이 아닌 경우.
		if (!frame) {
			return;
		}

		// 이미 수집된 디펜던시인 경우.
		if (frame.some(it => it.equals(dep))) {
			return;
		}

		frame.push(dep);
	}

	/**
	 * 디펜던시가 사용 되었음을 선포 합니다.
	 * @param depExpression 디펜던시 표현식. 디펜던시 표현식은 '/'로 구분되는 문자열 입니다. 'aaa/bbb' 의존성은 'aaa/bbb/ccc'를 포함합니다.
	 * 예를 들어 'aaa/bbb/ccc' 의존성을 감시 중이라면 'aaa/bbb' 의존성 변경이 일어나도 'aaa/bbb/ccc' 의존성 또한 변경된 것으로 간주 합니다.
	 */
	export function _declareDependecy(depExpression: string): void;

	/**
	 * 디펜던시가 사용 되었음을 선포 합니다.
	 * @param dependency 디펜던시 객체.
	 */
	export function _declareDependecy(dependency: _Dependency): void;
	export function _declareDependecy(dependency: string | _Dependency): void {
		let depObj = typeof dependency == "string"
			? new _Dependency(dependency)
			: dependency;
		_collectDependency(depObj);
	}

	export interface _IDependencyCollectingOptions<T> {
		/**
		 * 구독 아이디. 구독 아이디를 지정한 경우 동일한 아이디의 구독이 만들어질 떄 이전 구독이 자동 취소됩니다.
		 */
		subscriptionId?: string;

		/**
		 * 디펜던시를 수집하며 실행할 작업.
		 */
		task: () => T;
		/**
		 * 작업 실행 이후 디펜던시 무효가 발생할 때 실행할 작업.
		 */
		onDepndencyInvalidation: () => void;

		/**
		 * 구독의 유효성을 검증하는 프리디케이트.
		 */
		healthChecker?: () => boolean
	}

	/**
	 * 디펜던시를 수집하며 특정 작업을 수행합니다.
	 * @param options 옵션
	 * @returns 해당 작업의 반환 값.
	 */
	export function _runWithCollectionDependency<T>(options: _IDependencyCollectingOptions<T>): T {
		status.depCollectingStack.push([]);
		try {
			return options.task();
		} finally {
			let collectedDependency = status.depCollectingStack.pop();
			collectedDependency = _.union(collectedDependency);

			if (utils.Util.isNullOrEmpty(collectedDependency) === false) {
				log(`디펜던시 수집됨: `, collectedDependency.map(it => it.identifier));
				let subscription: _DependencySubscription;
				if (options.subscriptionId) {
					subscription = _subscribeDependencyInvalidation(options.subscriptionId, (change) => {
						if (collectedDependency.some(e => change.contains(e))) {
							subscription._dispose();
							options.onDepndencyInvalidation();
						}
					});
				}
				else {
					subscription = _subscribeDependencyInvalidation((change) => {
						if (collectedDependency.some(e => change.contains(e))) {
							subscription._dispose();
							options.onDepndencyInvalidation();
						}
					});
				}

				if (options.healthChecker) {
					subscription._setHealthChecker(options.healthChecker);
				}
			}
		}
	}

	/**
	 * 디펜던시 무효를 선언합니다.
	 * @param depExpression 디펜던시 표현식.
	 */
	export function _fireDependecyInvalidation(depExpression: string): void;

	/**
	 * 디펜던시 무효를 선언합니다.
	 * @param dependency 디펜던시.
	 */
	export function _fireDependecyInvalidation(dependency: _Dependency): void;
	export function _fireDependecyInvalidation(dependency: string | _Dependency): void {
		let depObj = typeof dependency == "string"
			? new _Dependency(dependency)
			: dependency;

		let invalidSubscriptions: _DependencySubscription[] = [];

		// 구독자에게 의존성 변경 전파
		let subscriptions = status.allSubscriptions.slice(0);
		subscriptions.forEach(eachSubscription => {
			try {
				if (eachSubscription._healthy) {
					eachSubscription._handler(depObj);
				}
				// 무효 구독을 걸러 냄
				else {
					invalidSubscriptions.push(eachSubscription);
				}
			} catch (err) {
				console.error(err);
				invalidSubscriptions.push(eachSubscription);
			}
		});

		// 오류를 일으킨 구독자 제거
		invalidSubscriptions.forEach(eachSubscription => {
			let idx = status.allSubscriptions.indexOf(eachSubscription);
			if (idx >= 0) {
				status.allSubscriptions.splice(idx, 1);
			}
		});
	}

	/**
	 * 디펜던시 무효를 구독 합니다.
	 * @param handler 디펜던시 무효 핸들러.
	 */
	export function _subscribeDependencyInvalidation(handler: DependencyHandler): _DependencySubscription;

	/**
	 * 구독 ID를 사용하여 디펜던시 무효를 구독합니다. 동일한 구독 ID를 통해 구독이 일어나면 이전 구독은 파기 됩니다.ㄴ
	 * @param subscriptionIdentifier 구독 아이디.
	 * @param handler 구독 핸들러.
	 */
	export function _subscribeDependencyInvalidation(subscriptionIdentifier: string, handler: (dep: _Dependency) => void): _DependencySubscription;

	export function _subscribeDependencyInvalidation(): _DependencySubscription {
		switch (arguments.length) {
			case 1: {
				let subscription = new _DependencySubscription(arguments[0]);
				status.allSubscriptions.push(subscription);

				log(`디펜던시 구독 추가, 구독 수: ${status.allSubscriptions.length}`);
				return subscription;
			}

			case 2: {
				let id: string = arguments[0];
				let handler: DependencyHandler = arguments[1];

				let subscription = new _DependencySubscription(handler);

				status.identifiableSubscriptions[id]?._dispose();
				status.allSubscriptions.push(subscription);
				status.identifiableSubscriptions[id] = subscription;

				log(`디펜던시 구독 추가, 구독 수: ${status.allSubscriptions.length}`);
				return subscription;
			}
		}
	}
}