/// <reference path="BodyEventTarget.ts"/>

namespace cpr.events {
	/**
	 * @private
	 */
	export class AccessKeyHandler {
		private _listenerFunc: (e: CEvent) => void = (e: CEvent) => this._processEvent(e as CKeyboardEvent);

		constructor() {
		}

		public start(): void {
			BodyEventTarget.INSTANCE.addEventListener("keydown", this._listenerFunc);
		}

		private _processEvent(e: CKeyboardEvent): void {
			// alt + [0-9a-zA-Z]
			if (e.altKey !== true || e.ctrlKey === true || e.shiftKey === true || e.metaKey === true) {
				// altKey : Windows alt or OSX Option
				// ctrlKey : Ctrl
				// shiftKey : Shift
				// metaKey : Windows ⊞ or OSX Command
				return;
			}

			// Mac에서 Alt+Key 인경우 e.key에서 특수문자 값이 있음. keyCode는 정상적으로 나옴.
			let key: string = String.fromCharCode(e.keyCode);

			if (/^[0-9a-z-A-Z]$/g.test(key) === false) {
				return;
			}
			key = key.toLowerCase();

			let element: HTMLElement = document.querySelector("[data-hotkey='" + key + "']") as HTMLElement;
			if (!element) {
				return;
			}
			// check element
			let id: string = ufc.NodeUUIDMapper.INSTANCE._findClosestControlUUID(element);
			if (!id) {
				return;
			}

			let platform: core.Platform = core.Platform.INSTANCE;
			let ctrl = platform._lookupDrillDownByUUID(id) as controls.Control;

			// Grid 컨트롤은 AccessableUIControl을 상속받지 않아 instanceof 사용할 수 없음.
			if (!ctrl || _getProperty(ctrl, "accessKey", null) === null) {
				return;
			}

			e.stopPropagation();
			e.preventDefault();

			let accessableUICtrl: controls.AccessableUIControl = ctrl as controls.AccessableUIControl;
			if (accessableUICtrl.enabled == false) {
				return;
			}

			// check display hidden
			if (!element.offsetParent) {
				return;
			}
			// check visibility
			let computedStyle: CSSStyleDeclaration = window.getComputedStyle(element);
			if (computedStyle.visibility === "hidden") {
				return;
			}
			(ctrl as controls.AccessableUIControl)._focusByAccessKey();

		}
	}

	_registerPlatformInitTask(() => {
		new AccessKeyHandler().start();
	});
}