/// <reference path="./platform-utils.ts" />

namespace cpr {
	let _allowGlobalDragSelection = true;

	function _hookGlobalSelection() {
		if (_detectBrowser().mobile == false) {
			document.addEventListener("selectstart", (e: UIEvent) => {
				if (!_allowGlobalDragSelection) {
					e.preventDefault();
					return false;
				}
			});

			window.addEventListener("mouseup", (e: MouseEvent) => {
				_allowGlobalDragSelection = true;
			});
		}
	}

	/**
	 * 드래그를 통해 브라우저의 콘텐트를 선택하는 것을 허용할 지 여부를 지정합니다.
	 * @param allow 허용 여부.
	 */
	export function _setAllowGlobalSelection(allow: boolean) {
		_allowGlobalDragSelection = allow;
	}

	_hookGlobalSelection();
}