namespace cpr.controls {
	/**
 * @private
 */
	export class DropDownLinkedList extends AbstractDropDownList<TreeItem> {

		private _listArrowImage: string = "";
		private _values: string[] = [];
		private _binder: provider.TreeDataBinder;

		constructor(uicontrol: ICombobox, ns: string, binder: provider.TreeDataBinder) {
			super(uicontrol, ns);
			this._binder = binder;
		}
		get listArrowImage() {
			return this._listArrowImage;
		}

		set listArrowImage(src: string) {
			this._listArrowImage = src;
		}

		get values() {
			return this._values;
		}

		set values(values: string[]) {
			this._values = values;
		}

		_computeItemDisplayLabel(item: TreeItem): ufc.StyledString | string {
			return this._binder._computeItemDisplayLabel(item);
		}
		_getItemEnable(item: TreeItem): boolean {
			return this._binder.getItemEnable(item);
		}

		/**
		 * value를 가지고 호버되는 인덱스를 반환합니다.
		 * 중복 value를 허용하는 경우 사용하면 안됩니다. 중복 value를 사용하는 경우 {@link getHoverIndex}를 사용해야 합니다.
		 * @param value 
		 * @param defaultReturnValue 
		 * @returns 
		 */
		public getHoverIndexByValue(value: string, defaultReturnValue: number = -1): number {
			let result = defaultReturnValue;
			if (value == null) {
				return result;
			}
			let items = this.getItems();
			items.some((each: Item, idx: number) => {
				if (each.value == value) {
					result = idx;
					return true;
				}
				return false;
			})

			return result;
		}

		protected _createListItem(item: TreeItem, index: number): cpr.ufc.ElementShape {
			let children = [];
			let templateColumns = [];
			if (this._isShowIcon()) {
				//아이템의 icon
				let icon: cpr.ufc.ElementShape = {
					tag: "div",
					classNames: [ufc.Classes.ICON],
					style: {},
					children: []
				}
				if (item.icon) {
					icon.style["background-image"] = _quoteAsCSSURL(item.icon);
				}
				children.push(icon);
				templateColumns.push("auto");
				layouts.GridCSSBuilder._forCell()._withColumnStart(children.length)._commit(icon.style);
			}

			//아이템의 label
			let label: cpr.ufc.ElementShape = {
				tag: "div",
				style: {
					whiteSpace: "nowrap"
				},
				classNames: [ufc.Classes.TEXT],
				children: ufc.StyledString._asShape(this._computeItemDisplayLabel(item))
			}
			templateColumns.push("1fr");

			children.push(label);
			layouts.GridCSSBuilder._forCell()._withColumnStart(children.length)._withVerticalAlign(layouts.GridCellAlign.center)._commit(label.style);
			let hasChild: boolean = item._hasChild();
			let arrowClassNames: string[] = ["cl-linkedcombobox-arrow"];
			if (hasChild) {
				arrowClassNames.push(ufc.Classes.FOLDER);
			} else {
				arrowClassNames.push(ufc.Classes.LEAF);
			}

			//아이템의 arrow image
			let arrowimage: cpr.ufc.ElementShape = {
				tag: "div",
				classNames: arrowClassNames,
				style: {},
				children: ["&nbsp;"]
			}

			if (hasChild && this.listArrowImage != "") {
				arrowimage.style['background-image'] = _quoteAsCSSURL(this.listArrowImage);
			}
			children.push(arrowimage);
			templateColumns.push("auto");
			layouts.GridCSSBuilder._forCell()._withColumnStart(children.length)._commit(arrowimage.style);

			let shape: cpr.ufc.ElementShape = {
				tag: "div",
				classNames: [],
				styler: this.styler.item,
				key: item._getUUID(),
				bindContext: item.toExpressionContext(this._getUIControl()),
				style: {},
				attr: {
					"data-role": "option",
					role: "option",
					"data-id": item._getUUID(),
					"data-itemidx": String(index),
					"aria-selected": "false",
					id: this._getItemElementId(index)
				},
				children: children
			}
			let isItemEnabled = this._getItemEnable(item);

			cpr.ufc.ShapeUtil._setTooltipAttr(shape, { owner: this._getUIControl(), title: item.tooltip, id: item.value });
			cpr.ufc.ShapeUtil._setAriaDisabled(shape, isItemEnabled && !this._getUIControl().readOnly);
			let isSelectedItem = this._binder.isSelected(item);
			if (isSelectedItem) {
				// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/9166
				shape.attr['aria-selected'] = "true";
				shape.classNames.push(ufc.Classes.SELECTED);
			}
			if (index == this.hoveredIndex) {
				shape.classNames.push(ufc.Classes.HOVER);
			}
			if (isItemEnabled == false) {
				shape.classNames.push(ufc.Classes.DISABLED);
				delete shape.attr['tabindex'];
			}
			layouts.GridCSSBuilder._forLayout()._withTemplateColumns(templateColumns)._commit(shape.style);
			return shape;
		}

		protected _createDummyItem(label: string, value: string) {
			return new cpr.controls.TreeItem(label, value, "");
		}
	}

}