namespace cpr.data {
	/**
	 * Column.
	 * 데이터 컬럼.
	 */
	export class Column {
		private _dataSet: DataCollection;
		private _name: string;

		constructor(dataSet: DataCollection, name: string) {
			this._dataSet = dataSet;
			this._name = name;
		}

		/**
		 * 현재 Column의 컬럼명을 반환합니다.
		 * @return 현재 컬럼명
		 */
		public getName(): string {
			return this._name;
		}

		/**
		 * 현재 Column의 Header 객체를 반환합니다.
		 * @return 현재 Column의 Header 객체
		 */
		public getHeader(): header.Header {
			return this._dataSet.getHeader(this.getName());
		}

		//// userAttributes start ///
		/**
		 * 사용자 정의 속성을 지정합니다.
		 * @param key 지정할 속성명
		 * @param value 지정할 속성 값.
		 */
		public userAttr(key: string, value: string): void

		/**
		 * 사용자 정의 속성을 반환합니다.
		 * @param key 얻을 속성 이름.
		 * @return 사용자 정의 속성.
		 */
		public userAttr(key: string): string

		/**
		 * 한번에 여러 사용자 정의 속성을 지정합니다.
		 * @param values 사용자 정의 속성 키/값을 담은 JSON 객체.
		 */
		public userAttr(values: { [key: string]: string }): void

		/**
		 * 모든 사용자 정의 속성을 맵 형태로 얻습니다.
		 */
		public userAttr(): { [key: string]: string }

		/**
		 * 사용자 정의 속성을 반환합니다.
		 * @return 사용자 정의 속성.
		 */
		public userAttr(): any {
			let args = _toArray(arguments);
			let header: header.Header = this.getHeader();
			if (header) {
				return header.userAttr.apply(header, args);
			}
			return null;
		}

		/**
		 * 특정 속성 명의 사용자 정의 속성을 제거합니다.
		 * @param key 제거할 사용자 정의 속성 명.
		 */
		public removeUserAttr(key: string): void {
			let header: header.Header = this.getHeader();
			if (header) {
				header.removeUserAttr(key);
			}
		}

		/**
		 * 모든 사용자 정의 속성들을 삭제합니다.
		 */
		public removeAllUserAttr(): void {
			let header: header.Header = this.getHeader();
			if (header) {
				header.removeAllUserAttr();
			}
		}

		/**
		 * 모든 사용자 정의 속성 명을 반환합니다.
		 * @return 모든 사용자 정의 속성 명의 배열.
		 */
		public getUserAttrNames(): string[] {
			let header: header.Header = this.getHeader();
			if (header) {
				return header.getUserAttrNames();
			}
			return null;
		}
		//// userAttributes end ///

		/**
		 * 입력 받은 rowIndex에 해당되는 데이터를 반환합니다.
		 * @param rowIndex	값을 가져올 row의 row index
		 * @return 해당 데이터
		 */
		public getValue(rowIndex: number): any {
			return this._dataSet.getValue(rowIndex, this.getName());
		}

		/**
		 * 입력 받은 rowIndex에 해당되는 데이터를 수정합니다.
		 * @param rowIndex	수정할 row의 row index
		 * @param value		수정할 value 값
		 * @return 값 수정 성공 여부
		 */
		public setValue(rowIndex: number, value: any): boolean {
			return this._dataSet.setValue(rowIndex, this.getName(), value);
		}

		/**
		 * 입력 받은 rowIndex에 해당되는 데이터를 Row상태를 변경하지 않고, 값만 변경합니다.
		 * @param rowIndex	수정할 row의 row index
		 * @param value		수정할 value 값
		 * @return 값 수정 성공 여부
		 */
		public putValue(rowIndex: number, value: any): boolean {
			return this._dataSet.putValue(rowIndex, this.getName(), value);
		}

		/**
		 * 입력 받은 rowIndex에 해당되는 원본 데이터를 반환합니다.
		 * @param rowIndex	값을 가져올 row의 row index
		 * @return 해당 데이터
		 */
		public getOriginalValue(rowIndex: number): any {
			return this._dataSet.getOriginalValue(rowIndex, this.getName());
		}

		/**
		 * 현재 Column의 데이터를 array형태로 반환합니다.
		 * @return 현재 Column의 모든 데이터의 배열
		 */
		public getColumnData(): any[] {
			return this._dataSet.getColumnData(this.getName());
		}

		/**
		 * 입력 받은 rowIndex에 해당되는 데이터를 String형으로 반환합니다.
		 * @param rowIndex	값을 가져올 row의 row index
		 * @return 해당 데이터의 String형
		 */
		public getString(rowIndex: number): string {
			return this._dataSet.getString(rowIndex, this.getName());
		}

		/**
		 * 입력 받은 rowIndex에 해당되는 데이터를 Number형으로 반환합니다.<br>
		 * 값이 string형이어서 강제로 Number형으로 된경우 NaN이 반환된다.
		 * @param rowIndex	값을 가져올 row의 row index
		 * @return 해당 데이터의 Number형
		 */
		public getNumber(rowIndex: number): number {
			return this._dataSet.getNumber(rowIndex, this.getName());
		}

		/**
		 * 입력 받은 rowIndex에 해당되는 데이터를 Boolean형으로 반환합니다.
		 * @param rowIndex	값을 가져올 row의 row index
		 * @return 해당 데이터의 Boolean형
		 */
		public getBoolean(rowIndex: number): boolean {
			return this._dataSet.getBoolean(rowIndex, this.getName());
		}

		// 상태값과 attr 접근 메소드는 row 단위로 하기 때문에 따로 추가하지 않음.
	}
}