		private _adjustPosition() {
			let filterDlgElement: HTMLElement = this._getRenderer().getNamedNode("filterdlg");
			if (!filterDlgElement) {
				return;
			}
			this._computePosition();
			// this._settingPosition();

			//리스트박스가 window 외곽에 잘리는 체크
			let filterDlgRect: ClientRect | DOMRect = filterDlgElement.getBoundingClientRect();
			let filterDlgWidth: number = _getUnscaledClientValue(filterDlgRect.width);
			let filterDlgHeight: number = _getUnscaledClientValue(filterDlgRect.height);
			let windowWidth: number = Math.max(document.documentElement.clientWidth, window.innerWidth || 0);
			let windowHeight: number = Math.max(document.documentElement.clientHeight, window.innerHeight || 0);
			windowWidth = _getUnscaledClientValue(windowWidth);
			windowHeight = _getUnscaledClientValue(windowHeight);

			// 리스트가 window의 아래쪽에 잘리는지 체크
			let needChangingPos = this._openFilterPosition.top + filterDlgHeight > windowHeight;
			if (needChangingPos) {
				filterDlgElement.style.bottom = "0px";
				filterDlgElement.style.top = "auto";
			} else {
				filterDlgElement.style.top = this._openFilterPosition.top + "px";
				filterDlgElement.style.bottom = "auto";
			}

			let filterDialogPosition: FilterDialogPosition = this._grid.header.getColumn(this._openHeaderCellIndex).filterDialogPosition;
			if (filterDialogPosition == FilterDialogPosition.BottomRight) {
				// 리스트박스가 window의 왼쪽에 잘리는지 체크
				needChangingPos = this._openFilterPosition.right + filterDlgWidth > windowWidth;
				if (needChangingPos) {
					filterDlgElement.style.right = "auto";
					filterDlgElement.style.left = "0px";
				} else {
					filterDlgElement.style.right = this._openFilterPosition.right + "px";
					filterDlgElement.style.left = "auto";
				}
			} else { // left-bottom(def)
				// 리스트박스가 window의 오른쪽에 잘리는지 체크
				needChangingPos = this._openFilterPosition.left + filterDlgWidth > windowWidth;
				if (needChangingPos) {
					filterDlgElement.style.left = "auto";
					filterDlgElement.style.right = "0px";
				} else {
					filterDlgElement.style.left = this._openFilterPosition.left + "px";
					filterDlgElement.style.right = "auto";
				}
			}

			this._tobeDialogRect = {
				left: filterDlgElement.style.left,
				top: filterDlgElement.style.top,
				right: filterDlgElement.style.right,
				bottom: filterDlgElement.style.bottom,
				width: filterDlgElement.style.width,
				height: filterDlgElement.style.height
			};

		}

		private _mousedownHandler = (e: events.CMouseEvent) => { this._onmousedown(e); };
		private _onmousedown(e: events.CMouseEvent) {
			let target = <HTMLElement>e.target; // resize div
			if (target != null && target.getAttribute("data-role") != GRIDROLE.RESIZE_FIELD) {
				return;
			}
			let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(target);	// filterdlg
			domTraverser = domTraverser._parent('.cl-filterdlg');
			if (domTraverser == null) {
				return;
			}
			let dialog = domTraverser._getElement();
			for (let each of FilterDialog._resizableCSSList) {
				if (target.classList.contains(each)) {
					this._isResizing = true;
					e.stopPropagation();

					this._startDrag();

					this._currentDirection = this._directionType[each.substring(each.lastIndexOf("-") + 1, each.length)];
					this._dragStart.left = e._getUnscaledClientX();
					this._dragStart.top = e._getUnscaledClientY();
					dialog.classList.toggle("cl-unselectable");

					this._dialogRect.left = dialog.offsetLeft;
					this._dialogRect.top = dialog.offsetTop;
					this._dialogRect.height = dialog.offsetHeight;
					this._dialogRect.width = dialog.offsetWidth;
					break;
				}
			}
		}

		private _onmousemove(e: events.CMouseEvent) {
			let mouseButton = e.buttons ? e.buttons : e.which;
			if (mouseButton == 0) {
				this._onmouseup(e);
				return;
			}
			if (this._isResizing) {
				let isChanged: boolean = false;
				this._showDragOverlay();
				switch (this._currentDirection) {
					case this._directionType.e: {
						let moveX = e._getUnscaledClientX() - this._dragStart.left;
						if (this._dialogRect.width + moveX > this._resizeProp.minWidth) {
							this._tobeDialogRect.width = this._dialogRect.width + moveX + "px";
							isChanged = true;
						}
						break;
					}
					case this._directionType.s: {
						let moveY = e._getUnscaledClientY() - this._dragStart.top;
						if (this._dialogRect.height + moveY > this._resizeProp.minHeight) {
							this._tobeDialogRect.height = this._dialogRect.height + moveY + "px";
							isChanged = true;
						}
						break;
					}
					case this._directionType.se: {
						let moveX = e._getUnscaledClientX() - this._dragStart.left;
						let moveY = e._getUnscaledClientY() - this._dragStart.top;
						if (this._dialogRect.height + moveY > this._resizeProp.minHeight) {
							this._tobeDialogRect.height = this._dialogRect.height + moveY + "px";
							isChanged = true;
						}
						if (this._dialogRect.width + moveX > this._resizeProp.minWidth) {
							this._tobeDialogRect.width = this._dialogRect.width + moveX + "px";
							isChanged = true;
						}
						break;
					}
				}

				if (isChanged) {
					let filterdlgElement: HTMLElement = this._grid._getRenderer().getNamedNode("filterdlg");
					if (filterdlgElement != null) {
						filterdlgElement.style.left = this._tobeDialogRect.left;
						filterdlgElement.style.top = this._tobeDialogRect.top;
						filterdlgElement.style.width = this._tobeDialogRect.width;
						filterdlgElement.style.height = this._tobeDialogRect.height;

						let filterItemListRenderer = new FilterItemListRenderer(this._grid, this);
						this.redraw(filterItemListRenderer);
					}
				}

			}

		}

		private _onmouseup(e: events.CMouseEvent) {
			if (this._isResizing || this._isMoving) {
				this._isResizing = false;
				this._isMoving = false;
				let filterdlgElement: HTMLElement = this._grid._getRenderer().getNamedNode("filterdlg");
				filterdlgElement.classList.toggle("cl-unselectable");
			}
			this._endDrag();
		}

		private _startDrag() {
			cpr.events.BodyEventTarget.INSTANCE.addEventListener("mousemove", this._parentEventDispatcher);
			cpr.events.BodyEventTarget.INSTANCE.addEventListener("mouseup", this._parentEventDispatcher);
		}

		private _endDrag() {
			if (this._draggingOverlay) {
				document.body.removeChild(this._draggingOverlay);
				this._draggingOverlay = null;
			}
			cpr.events.BodyEventTarget.INSTANCE.removeEventListener("mousemove", this._parentEventDispatcher);
			cpr.events.BodyEventTarget.INSTANCE.removeEventListener("mouseup", this._parentEventDispatcher);
		}

		private _showDragOverlay() {
			if (!this._draggingOverlay) {
				this._draggingOverlay = document.createElement("div");
				this._draggingOverlay.style.position = "fixed";
				this._draggingOverlay.style.top = "0px";
				this._draggingOverlay.style.right = "0px";
				this._draggingOverlay.style.bottom = "0px";
				this._draggingOverlay.style.left = "0px";
				document.body.appendChild(this._draggingOverlay);
			}
		}

		public _redraw(): void {
			let renderer: ufc.ControlRenderer = this._grid._getRenderer();
			renderer.replace("filterdlg", this._createFilterDlgShape());
		}

		private _isSearched(): boolean {
			return (this._filterDlgFindValue.length > 0);
		}

