/// <reference path="./VisibleUIControl.ts"/>
/// <reference path="../core/Platform.ts"/>

namespace cpr.controls {
	let url = new utils.URL(location.href);
	let file = url.pathname.split("/").pop();
	let channelLog = cpr.utils.Logger.forTopic("channel")._createBindedLoggerFunction({
		prefixes: [location.hostname, file],
		updator: fn => channelLog = fn
	});

	function findRelatedEmbeddedPage(e: MessageEvent) {
		let source = e.source;
		let rootAppInstances = core.Platform.INSTANCE.getAllRunningAppInstances().filter(it => it.isRootAppInstance());
		let search = rootAppInstances.map(it => {
			return _createTreeStream(it.getContainer(), false, (it: UIControl) => {
				return _createTypeSwitch<UIControl[]>()
					.case(EmbeddedApp, it => {
						let appInstance = it.getEmbeddedAppInstance();
						if (appInstance?.state === core.AppInstanceState.RUNNING) {
							return appInstance.getContainer().getChildren();
						} else {
							return [];
						}
					})
					.case(Grid, it => [])
					.case(Container, (it) => {
						// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/7807
						// 플로팅된 컨트롤을 포함해서 검색 하도록 조치.
						if (it.isAppContainer) {
							return [
								...it.getChildren(),
								...it.getAppInstance().getFloatingControls()
							]
						}
						else {
							return it.getChildren();
						}
					})
					.run(it);
			}).filterByType(EmbeddedPage);
		}).reduce((p1, p2) => p1.concatWith(p2));

		let matchingPage = search?.find(it => it._getContentWindow() === source);
		return matchingPage;
	}

	(function () {
		window.addEventListener("message", (e: MessageEvent) => {
			channelLog("메시지 수신", e);
			// 핸드셰이크 메시지 수신 처리.
			if (protocols.PageChannel._isHandshakeMessageEvent(e)) {
				channelLog("eb6 연결 요청 수신", e);

				if (core.Platform.INSTANCE.getVersion() != e.data.version) {
					console.warn(`Page channel connection request came from different version: ${e.data.version} -> ${core.Platform.INSTANCE.getVersion()}`)
				}

				// 타겟 페이지 찾음.
				let targetPage = findRelatedEmbeddedPage(e);
				// 타겟 임베디드 페이지의 채널 구축
				targetPage?._makeClientChannel(e.data.port);
				if (targetPage) {
					channelLog("타겟 페이지 연결 함.")
				} else {
					channelLog("타겟 페이지 찾지 못함.")
				}
			}
		});
		channelLog("자식 페이지 접속 요청 리스닝 시작함.");
	})();

	const FRAME_NODE_NAME: string = "frame";

	/**
	 * 다른 웹페이지를 포함 할 수 있는 컨트롤. 웹 접근성을 위해 tooltip에 내용을 반드시 작성해주시기 바랍니다.
	 * 
	 * 
	 * @fires cpr.events.CEvent#load 페이지의 load가 완료되었을 때 호출되는 Event.
	 * 
	 */
	export class EmbeddedPage extends VisibleUIControl implements provider.ValueBindable {
		private static readonly _AVAILABLE_PROP: string[] = [
			"value", "text", "src", "frameName", "scrolling", "sandbox", "notSupportMessage", "referrerpolicy"
		];

		private _loaded: boolean = false;
		// iframe 내의 src는 설정할 때와 조회할 때 값이 달라질 수 있기 때문에 설정할 당시 src와 실제 값을 함께 저장함
		private _settledSrc: { src: string, resolvedSrc: string } = null;

		private _binder: provider.ValueBinder;
		private _tabIndex = 0;

		/**
		 * 임베디드 페이지 내부와 통신하기 위한 부모 측 채널.
		 */
		private _downstreamPageChannel: protocols.PageChannel;

		/**
		 * 임베디드 페이지를 생성합니다.
		 * @param id 임베디드 페이지의 id
		 */
		constructor(id?: string) {
			super(id);
			this._binder = new provider.ValueBinder(this);

			this._addBindableProperty("frameName", "embPgFrm-" + _generateUUID()).withSetterValidatorWithType(false, "string");
			this._addBindableProperty("scrolling", "auto").withSetterValidatorWithType(false, "string");
			this._addBindableProperty("sandbox", "all").withSetterValidatorWithType(false, "string");
			this._addBindableProperty("notSupportMessage", "").withSetterValidatorWithType(false, "string");
			this._addBindableProperty("referrerpolicy", "strict-origin-when-cross-origin").withSetterValidatorWithType(false, "string");
			// control initializing
			this._initControl();
		}

		/**
		 * EmbeddedPage에 표현할 컨텐츠를 Http Post 메소드로 요청할 수 있는 HttpPostMethod 객체를 생성하여 리턴합니다.
		 * @param actionUrl EmbeddedPage에 표현한 컨텐츠의 URL. 서버로 전송되는 최종 URL은 Submission의 URL 처리 규칙을 준수합니다.
		 */
		public getPostMethod(actionUrl: string): protocols.HttpPostMethod {
			let httpPostMethod: protocols.HttpPostMethod = new protocols.HttpPostMethod(actionUrl, this.frameName);
			httpPostMethod.addEventListener(events.SubmissionEventType.BEFORE, (e: events.CSubmissionEvent) => {
				let renderer: ufc.ControlRenderer = this._getRenderer();
				let frameTag: HTMLIFrameElement = renderer.getNamedNode(FRAME_NODE_NAME) as HTMLIFrameElement;
				this._loaded = false;
				frameTag.onload = (e: Event) => {
					this._onFrameLoad(e);
				};
			});
			return httpPostMethod;
		}

		protected _isConfigurableProperty(propName: string): boolean {
			if (EmbeddedPage._AVAILABLE_PROP.indexOf(propName) != -1) {
				return true;
			}
			return super._isConfigurableProperty(propName);
		}

		public get tabIndex(): number {
			return this._tabIndex;
		}

		public set tabIndex(tabIndex) {
			this._tabIndex = tabIndex;
			// redraw() 필요 없음. 이 탭 인덱스는 돔으로 노출되지 않음.
		}

		/*
		 * https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/7073
		 * 페이지가 로드되었고 페이지내 어댑터나 eXBuilder6 플랫폼과 연결된 상태에서만 포커서블 함.
		 */
		override _isFocusable(): boolean {
			// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/8194
			// 임베디드 페이지는 항상 포커스를 소유할 수 있도록 함.
			return true;
		}

		override focus(forward: boolean) {
			core.DeferredUpdateManager.INSTANCE._performFocusTask(() => {
				let iframe = this._getFrameNode();
				if (!iframe) {
					return;
				}
				// 어댑터가 연결되어 있는 경우.
				if (this._downstreamPageChannel && this._downstreamPageChannel._isConnected()) {
					iframe.contentWindow.focus();
					this._downstreamPageChannel._sendFocus(forward);
				}
				// CORS가 아닌 경우.
				else if (_isSameOriginIFrame(iframe)) {
					if (!_traverseHTMLFocus(iframe.contentDocument.body, forward)) {
						iframe.contentWindow.focus();
					}
				}
				// CORS인 경우 폴백.
				else {
					iframe.contentWindow.focus();
				}
			})
		}

		public _getFrameNode(): HTMLIFrameElement {
			let renderer = this._getRenderer();
			if (!renderer || !renderer.hasDrawn()) {
				return null
			}
			let frameNode = renderer.getNamedNode(FRAME_NODE_NAME) as HTMLIFrameElement;
			return frameNode;
		}

		/* Property Start */
		/// SimpleDataBindable Start ////////////////////////////////////////////

		/**
		 * @param prop 
		 * @param oldValue 
		 * @param newValue 
		 */
		_valueDidChange(prop: string, oldValue: any, newValue: any) {
			super._valueDidChange(prop, oldValue, newValue);
			this._binder._valueDidChange(prop, oldValue, newValue);
		}
		/**
		 * 컨트롤의 값을 설정합니다.
		 * @param value 컨트롤의 값.
		 */
		public set value(value: string) {
			this._binder.setValue(value);
		}

		/**
		 * 컨트롤의 값을 반환합니다.
		 * @return 컨트롤의 값.
		 */
		public get value(): string {
			return this._binder.getValue();
		}

		/**
		 * 컨트롤의 값을 설정합니다.
		 * @param value 컨트롤의 값
		 */
		public putValue(value: string) {
			this._binder.setValue(value, false);
		}

		/**
		 * 컨트롤에 보여지는 텍스트를 반환합니다.
		 * @return 화면에 보이는 텍스트.
		 */
		public get text(): string {
			return this._binder.getText();
		}

		/**
		 * 컨트롤에 보이는 텍스트를 설정합니다.
		 * @param text 화면에 보이는 텍스트.
		 */
		public set text(text: string) {
			this._binder.setText(text);
		}

		/// SimpleDataBindable End ////////////////////////////////////////////////
		/**
		 * Embedded page의 경로를 반환합니다.
		 * @return 경로.
		 */
		public get src(): string {
			return this.value;
		}

		/**
		 * Embedded page의 경로를 설정합니다.
		 * @param src 경로.
		 */
		public set src(src: string) {
			this.value = src;
		}

		/**
		 * iframe의 name 속성을 반환합니다.
		 * @return iframe의 name 속성.
		 */
		public get frameName(): string {
			return this._bindables.get("frameName");
		}

		/**
		 * iframe의 name 속성을 설정합니다.
		 * @param frameName iframe의 name 속성.
		 */
		public set frameName(frameName: string) {
			this._bindables.set("frameName", frameName);
		}

		/**
		 * HTTP Referer 헤더에 어떤 정보가 포함되어 전송되는지를 제어하는 속성을 반환합니다.
		 */
		public get referrerpolicy(): string {
			return this._bindables.get("referrerpolicy");
		}

		/**
		 * 
		 * HTTP Referer 헤더에 어떤 정보가 포함되어 전송되는지를 제어하는 속성을 설정합니다.
		 * Firefox, Safari에서는 일부 속성값 지원, IE는 지원하지 않는 속성입니다.
		 * [no-referrer] : Referer 헤더를 보내지 않습니다.<br>
		 * [no-referrer-when-downgrade] : HTTPS에서 HTTPS로 이동할 때는 Referer를 보내지만, HTTPS에서 HTTP로 이동할 때는 보내지 않습니다.(Firefox, Safari 미지원)<br>
		 * [origin] : Referer에 전체 URL이 아닌 도메인(origin)만 포함합니다.<br>
		 * [origin-when-cross-origin] : 같은 사이트로 요청할 때는 전체 URL을 보내고, 다른 사이트로 요청할 때는 도메인만 보냅니다.(Firefox, Safari 미지원)<br>
		 * [same-origin] : 같은 사이트로의 요청일 때만 Referer를 보내고, 외부 요청에는 보내지 않습니다.<br>
		 * [strict-origin] : 같은 프로토콜(HTTPS → HTTPS)로의 요청일 때만 Referer를 보내고, HTTPS에서 HTTP로 이동할 때는 보내지 않습니다.<br>
		 * [strict-origin-when-cross-origin] : 같은 사이트일 때는 전체 URL을 보내고, 다른 사이트일 때는 도메인만 보내며, HTTPS에서 HTTP로 이동할 때는 보내지 않습니다.<br>
		 * [unsafe-url] : 항상 전체 URL을 Referer로 보냅니다.(Firefox, Safari 미지원)
		 */
		public set referrerpolicy(referrerpolicy: string) {
			this._bindables.set("referrerpolicy", referrerpolicy);
		}

		/**
		 * page의 스크롤 상태를 반환합니다.
		 * @return 스크롤 상태.
		 */
		public get scrolling(): string {
			return this._bindables.get("scrolling");
		}
		/**
		 * page의 스크롤 상태를 설정합니다.<br>
		 * [yes] : 스크롤을 항상 설정합니다.<br>
		 * [no] : 스크롤을 설정하지 않습니다.<br>
		 * [auto] : 스크롤이 필요할 시 설정됩니다.<br>
		 * @param scrolling 스크롤 상태.
		 */
		public set scrolling(scrolling: string) {
			this._bindables.set("scrolling", scrolling);
		}

		/**
		 * sandbox 속성을 반환합니다.<br>
		 * 이 속성을 지정 할 시 Embedded page에 제한을 줍니다.<br>
		 * @return sandbox 속성.
		 */
		public get sandbox(): string {
			return this._bindables.get("sandbox");
		}
		/**
		 * sandbox 속성을 설정합니다.<br>
		 * 이 속성을 지정 할 시 Embedded page에 제한을 줍니다.<br>
		 * [allow-forms] : form 요소로 page 호출을 허용합니다.<br>
		 * [allow-pointer-lock] : Pointer Lock API 사용을 허용합니다.<br>
		 * [allow-popups] : 팝업을 허용합니다.<br>
		 * [allow-same-origin] : 같은 source(origin)만을 허용합니다.<br>
		 * [allow-scripts] : 스크립트 적용을 허용합니다.(팝업은 허용되지 않습니다.)<br>
		 * [allow-top-navigation] : top level의 page load를 허용합니다.<br>
		 * [allow-popups allow-scripts] : 팝업과 스크립트 적용을 허용합니다.(팝업이 스크립트를 포함하는 경우에 필요합니다.)<br>
		 * @param sandbox sandbox 속성.
		 */
		public set sandbox(sandbox: string) {
			this._bindables.set("sandbox", sandbox);
		}

		/**
		 * 브라우저가 Embedded Page(iframe)을 지원하지 않을 시 발생할 메세지를 반환합니다.
		 * @return 메세지.
		 */
		public get notSupportMessage(): string {
			return this._bindables.get("notSupportMessage");
		}
		/**
		 * 브라우저가 Embedded Page(iframe)을 지원하지 않을 시 발생할 메세지를 설정합니다.
		 * @param notSupportMessage 메세지.
		 */
		public set notSupportMessage(notSupportMessage: string) {
			this._bindables.set("notSupportMessage", notSupportMessage);
		}
		/* Property End */

		/**
		 * 해당 속성을 bind합니다.
		 * @param name bind할 속성 명.
		 */
		bind(name: string): cpr.bind.IBindFactory {
			// src -- value bind join
			if (name == "src") {
				return super.bind("value");
			}
			else {
				return super.bind(name);
			}
		}

		override _getType(): ControlType {
			return ControlType.EMBEDDEDPAGE;
		}

		protected _getStylerSpec(): UIControlStylerSpec { /* TODO abstract */
			return {
				root: {
					baseClass: "cl-embeddedpage"
				}
			};
		}

		/**
		 * Embedded Page를 그립니다(load).
		 */
		public override _afterDraw(firstDraw: boolean = false): void {
			super._afterDraw(firstDraw);
			let frameTag = this._getFrameNode();
			if (this._settledSrc === null) {
				// case 1
				if (this.src) {
					this._setFrameSrc(frameTag);
				}
			} else if (this._settledSrc.src != this.src) {
				// case 2
				this._setFrameSrc(frameTag);
			} else {
				// case 3
				let resolvedSrc: string = frameTag.src;
				if (this._settledSrc.resolvedSrc != resolvedSrc) {
					this._setFrameSrc(frameTag);
				}
			}
		}

		private _setFrameSrc(frameTag: HTMLIFrameElement): void {
			this._loaded = false;
			frameTag.onload = (e: Event) => {
				this._onFrameLoad(e);
			};
			frameTag.src = this.src;
			this._settledSrc = {
				src: this.src, resolvedSrc: frameTag.src
			};
		}

		public _createShape(): ufc.ControlShape {
			let iframeShape: ufc.ControlShape = {
				tag: "iframe",
				attr: {
					// frameborder: "0", // HTML5에서 style사용으로 대체. 웹표준 검사기에서 사용하지 않도록 권장.
					src: ""
				},
				nodename: FRAME_NODE_NAME,
				style: {
					position: "relative",
					height: "100%",
					width: "100%",
					border: "none",
					display: "block"
				},
				children: []
			};
			//auto가 기본값이므로 yse 또는 no인 경우에만 엘리먼트에 설정되도록 변경.(웹표준 검사기에서 문제로 기본값은 표시하지 않도록 함.)
			if (this.scrolling != "auto") {
				iframeShape.attr["scrolling"] = this.scrolling;
			}
			if (this.referrerpolicy != "strict-origin-when-cross-origin") {
				iframeShape.attr["referrerPolicy"] = this.referrerpolicy;
			}

			if (this.notSupportMessage) {
				iframeShape.children.push({
					tag: "p", // 웹표준 검사기에서 오류로 발견됨.
					children: [this.notSupportMessage]
				});
			}
			cpr.ufc.ShapeUtil._setTooltipAttr(iframeShape, { owner: this, title: this.tooltip });
			let sandboxEnabled: string = this.sandbox;
			if (sandboxEnabled != null && sandboxEnabled != "" && sandboxEnabled != "all") {
				iframeShape.attr["sandbox"] = sandboxEnabled;
			}
			let frmNm: string = this.frameName;
			if (frmNm) {
				iframeShape.attr["name"] = frmNm;
			}

			let shape: ufc.ControlShape = {
				tag: "div",
				attr: {
				},
				styler: "root",
				style: {
					boxSizing: "border-box"
				},
				children: [{
					tag: "div",
					style: {
						position: "relative",
						boxSizing: "border-box",
						width: "100%",
						height: "100%"
					},
					children: [iframeShape]
				}]
			};
			return shape;
		}

		/**
		 * Embedded page 내 전달할 property를 설정합니다.
		 * @param name property 명.
		 * @param value property 값.
		 */
		public setPageProperty(name: string, value: any): void {
			if (this._loaded == false) {
				throw new cpr.exceptions.IllegalStateException();
			}
			let frameContentWindow: Window = this._getContentWindow();
			frameContentWindow[name] = value;
			// TODO type safe
		}

		/**
		 * Embedded page의 property를 반환합니다.
		 * @param name property 명.
		 * @return string|number|object|undefined property 값.
		 */
		public getPageProperty(name: string): any {
			if (this._loaded == false) {
				throw new cpr.exceptions.IllegalStateException();
			}
			let frameContentWindow: Window = this._getContentWindow();
			let value: any = frameContentWindow[name];

			return value;
		}

		/**
		 * Embedded Page 내 수행할 method를 가지고 있는지 여부를 반환합니다.
		 * @param name method 명.
		 * @return method를 가지고 있는지 여부.
		 */
		public hasPageMethod(name: string): boolean {
			if (this._loaded == false) {
				throw new cpr.exceptions.IllegalStateException();
			}
			let frameContentWindow: Window = this._getContentWindow();
			let value: any = frameContentWindow[name];

			if (value && typeof value == "function") {
				return true;
			}

			return false;
		}

		/**
		 * Embedded Page의 해당 method를 호출합니다.
		 * @param name method 명.
		 * @param args method의 arguments.
		 * @return string|number|object|undefined 페이지의 함수에서 반환되는 값을 반환합니다. 함수가 없는 경우 또는 함수에 반환이 없는 경우에는 undefined를 반환합니다.
		 */
		public callPageMethod(name: string, ...args: any[]): any {
			if (this._loaded == false) {
				throw new cpr.exceptions.IllegalStateException();
			}

			let frameContentWindow: Window = this._getContentWindow();
			let func: any = frameContentWindow?.[name];
			if (typeof func == "function") {
				return (func as Function).apply(frameContentWindow, args);
			}
			return undefined;
		}

		/**
		 * 임베디드 페이지 내의 글로벌 함수를 호출합니다.
		 * @param fnName 호출할 함수 이름.
		 * @param args 인자 목록
		 * @param callType 호출 유형.
		 * @returns 함수의 실행 결과를 전달하는 프로미스 객체.
		 */
		public callClientFunction(fnName: string, args: any[] = [], callType = protocols.PageFunctionCallType.NORMAL): Promise<any> {
			if (!this._downstreamPageChannel) {
				throw new exceptions.IllegalStateException("The page is not loaded or it doesn't support page protocol.")
			}
			return this._downstreamPageChannel.callFunction(fnName, args, callType);
		}

		/**
		 * 컨트롤에 포함되어있는 객체들을 제거합니다.
		 */
		public dispose(): void {
			this._loaded = false;
			this._downstreamPageChannel?._dispose();
			this._downstreamPageChannel = null;
			super.dispose();
		}

		public _makeClientChannel(clientPort: MessagePort) {
			// 기존 채널 파기
			this._downstreamPageChannel?._dispose();
			let contentWindow = this._getContentWindow();

			// 임베디드 페이지 채널 작성.
			this._downstreamPageChannel = protocols.PageChannel._createDownSreamChannel(
				contentWindow,
				clientPort,
				{
					onFocus: (forward: boolean) => {
						if (forward) {
							this.focusNext();
						} else {
							this.focusPrevious();
						}
					},
					functionProvider: (name: string) => {
						return core.Platform.INSTANCE._getChannelFunction(name);
					}
				}
			);
		}

		/* Helper Methods */
		private _onFrameLoad(e: Event): void {
			// 로드 이벤트 디스패치
			this._loaded = true;
			let cevent: events.CEvent = events.wrap(e);
			this.dispatchEvent(cevent);
		}

		public _getContentWindow(): Window {
			return this._getFrameNode()?.contentWindow;
		}
		/* Helper Methods */

		_getAutoSizeAvailability() {
			return layouts.AutoSizeType.both;
		}

	}
}