namespace cpr.utils {
	export interface Size {
		/**
		 * 크기
		 */
		size: number;
		/**
		 * 크기의 단위
		 */
		unit: string;
	}

	/**
	 * @noinstance
	 */
	export class ParamUtil {

		static parseSize(sizeValue: number | string, defaultSize: number = -1): Size {
			let size: Size = {
				size: defaultSize,
				unit: "px"
			};

			if (sizeValue == null) {
				return size;
			} else if (typeof sizeValue == "number") {
				size.size = <number>sizeValue;
			} else {
				let sizeNum: RegExpExecArray = /[-]?[0-9.]+/i.exec(sizeValue);
				if (sizeNum != null && sizeNum.length > 0) {
					size.size = Number(sizeNum[0]);
				}

				let sizeUnit: RegExpExecArray = /[a-z]+|%/i.exec(sizeValue);
				if (sizeUnit != null && sizeUnit.length > 0) {
					size.unit = sizeUnit[0]
				}
			}

			return size;
		}

		static isNumber(value: number): boolean {
			if (typeof (value) == "number") {
				return true;
			}
			return false;
		}

		static isInRange(value: number, min: number, max: number): boolean {
			if (this.isNumber(value) == false
				|| this.isNumber(min) == false
				|| this.isNumber(max) == false) {
				return false;
			}
			if (value >= min && value <= max) {
				return true;
			}
			return false;
		}

		static isJSONString(jsonStr: string): boolean {
			if (typeof (jsonStr) != "string") {
				return false;
			}
			try {
				JSON.parse(jsonStr);
				return true;
			} catch (e) {
				return false;
			}
		}

		static isJSON(json: {}): boolean {
			if (typeof (json) != "object") {
				return false;
			}
			try {
				let jsonStr: string = JSON.stringify(json);
				return this.isJSONString(jsonStr);
			} catch (e) {
				return false;
			}
		}

		static toNumber(value: any): number {
			return typeof value == "number" ? value as number : parseInt(value);
		}

		static toBoolean(value: any): boolean {
			return (value == false) ? false : (value ? true : false);
		}

		static _matchArgs(
			args: any[],
			...schemes: (primitive_type | null | (abstract new (...args: any[]) => Object))[][]
		): boolean {
			return schemes.some(scheme => {
				if (args.length != scheme.length) {
					return false;
				}

				return args.every((value, idx) => {
					let expectedType = scheme[idx];
					if (typeof expectedType == "string") {
						return typeof value == expectedType;
					}
					else if (typeof expectedType === null) {
						return value === null;
					}
					else {
						return value instanceof expectedType;
					}
				});
			});
		};
	}
}