namespace cpr.bind {
	/**
	 * 프로퍼티 바인딩 기술자, 속성 델리게이트(PropertyDelegate)를 작성하는 데 사용됩니다.
	 * @nonapi
	 */
	export interface PropertyDelegateDescriptor {
		/** 게터 액세서 */
		get: () => any;

		/** 세터 액세서 */
		set?: (newValue: any) => void;

		/** 활성화 여부 계산 클로져 */
		isActive?: () => boolean;

		/** 가용성 계산 클로져 */
		_isAvailable: () => boolean;

		/** 폐기 절차 클로져 */
		dispose?: () => void;

		/** 사용자 공급 바인딩 정보 */
		bindInfo?: bind.BindInfo
	}

	/**
	 * 바인딩 된 속성 값을 대체 접근하는 델리게이트 구현.
	 * @nonapi
	 */
	export class PropertyDelegate {
		_descriptor: PropertyDelegateDescriptor;


		constructor();
		constructor(desc: PropertyDelegateDescriptor);
		constructor() {
			let args = _toArray(arguments);
			if (args[0]) {
				let desc = args[0] as PropertyDelegateDescriptor;
				this._descriptor = desc;
			}
		}

		get(): any {
			return this._descriptor.get();
		}

		set(newValue: any): void {
			this._descriptor.set?.call(null, newValue)
		}

		isActive(): boolean {
			return this._descriptor.isActive ? this._descriptor.isActive() : true;
		}

		_isAvailable(): boolean {
			return this._descriptor._isAvailable ? this._descriptor._isAvailable() : true;
		}

		dispose(): void {

		}

		getBindInfo(): bind.BindInfo {
			if (this._descriptor?.bindInfo) {
				return _shallowCopyObject(this._descriptor.bindInfo);
			} else {
				return null;
			}
		}

		static fromDescriptor(desc: PropertyDelegateDescriptor): PropertyDelegate {
			if (desc instanceof PropertyDelegate) {
				return desc;
			}
			else {
				return new PropertyDelegate(desc);
			}
		}
	}
}