namespace cpr.controls {
	let log = utils.Logger.forTopic("dnd")._createBindedLoggerFunction({
		updator: it => log = it
	});

	/**
	 * 드래그 앤드 드랍의 상황을 설명하는 객체입니다.
	 * @noinstance
	 */
	export class DropContext {
		protected _source: DragSource;
		protected _target: DropTarget;
		protected _targetElement: HTMLElement;
		private _pointerLocation: PointerLocation;
		private _cachedDelta: geometry.Dimension;


		/**
		 * 마우스 아래에 있는 아이템을 얻습니다.
		 */
		public targetItem: any;

		/**
		 * 마우스 아래에 있는 아이템과 드롭 문맥 사이의 관계를 얻습니다.
		 */
		public targetItemConstraint: ItemDropConstraint = ItemDropConstraint.OVER;

		constructor(original: DropContext);
		constructor(source: DragSource, target: DropTarget, pointerLocation: PointerLocation, targetElement: HTMLElement);
		constructor() {
			let args = _toArray(arguments);
			if (args[0] instanceof DragSource) {
				let source = args[0] as DragSource;
				let target = args[1] as DropTarget;
				let location = args[2] as PointerLocation;
				let targetElement = args[3] as HTMLElement;

				this._source = source;
				this._target = target;
				this._pointerLocation = location;
				this._targetElement = targetElement;
			}
			else if (args[0] instanceof DropContext) {
				let original = args[0] as DropContext;
				this._source = original._source;
				this._target = original._target;
				this._targetElement = original._targetElement;
				this._pointerLocation = original._pointerLocation;
			}
		}

		/**
		 * 드래그 소스 객체를 얻습니다.
		 */
		get source(): DragSource {
			return this._source;
		}

		/**
		 * 드롭 타겟 객체를 얻습니다.
		 */
		get target(): DropTarget {
			return this._target;
		}

		/**
		 * 현재 드롭 대상 컨트롤의 포인터 위치에 대한 targetObject 값을 얻습니다.
		 * 일반적으로 포인팅 지점의 세부 정보를 제공합니다.
		 */
		get targetObject(): any {
			return this._target.control._getTargetObject(this._targetElement);
		}

		/**
		 * 드래그 소스가 제공하는 데이터를 얻습니다.
		 */
		get data(): any {
			if (this._source) {
				return this._source._getData();
			} else {
				return null;
			}
		}

		/**
		 * 드래그 소스의 데이터 타입을 얻습니다.
		 */
		get dataType(): string {
			return this._source.dataType;
		}

		/**
		   * 드래그가 시작된 시점의 포인터 위치를 얻습니다.
		  * @since 1.0.2037
		   */
		get dragStartLocation(): geometry.Point {
			return this._source._getDragStartLocation().clientLocation;
		}

		/**
		 * 현재 마우스 포인터의 좌표를 얻습니다.
		 */
		get pointerLocation(): geometry.Point {
			return this._pointerLocation.clientLocation;
		}

		/**
		 * 총 드래그의 이동량을 얻습니다. 마우스 버튼이 눌려진 시점을 기준으로 합니다.
		 * @since 1.0.2037
		 */
		get dragDelta(): geometry.Dimension {
			if (this._cachedDelta) {
				return this._cachedDelta;
			}
			this._cachedDelta = this._pointerLocation.pageLocation.getDifference(this._source._getDragStartLocation().pageLocation);
			return this._cachedDelta;
		}

		/**
		 * 표시중인 커서를 얻습니다.
		 */
		get cursor(): css_cursor {
			return this._source._resolveCursor();
		}

		/**
		 * 현재 드랍 타겟으로 드래그 오버 될 때 사용할 커서를 지정합니다.
		 */
		set cursor(cursor: css_cursor) {
			this._source._setCursorForTarget(this._target, cursor);
		}

		public _getTargetElement(): HTMLElement {
			return this._targetElement;
		}

		/**
		 * Shift 키가 눌려있는지 여부를 얻습니다.
		 */
		public get shiftKey(): boolean {
			return this._source._getKeyStates().shiftKey;
		}

		/**
		 * Alt 키가 눌려 있는지 여부를 얻습니다.
		 */
		public get altKey(): boolean {
			return this._source._getKeyStates().altKey;
		}

		/**
		 * Control 키가 눌려 있는지 여부를 얻습니다.
		 */
		public get ctrlKey(): boolean {
			return this._source._getKeyStates().ctrlKey;
		}

		/**
		 * 메타 키가 눌려 있는지 여부를 얻습니다.
		 */
		public get metaKey(): boolean {
			return this._source._getKeyStates().metaKey;
		}
	}

	export enum ItemDropConstraint {
		OVER = "over",
		BEFORE = "before",
		AFTER = "after"
	};
}