///<reference path="./VisibleUIControl.ts"/>


namespace cpr.controls {
	export abstract class EnableUIControl extends VisibleUIControl {
		// enabled 여부의 캐시. 새로 그려질 때 마다 갱신됨.
		private _enabledCache: boolean = null;
		// readOnly 여부의 캐시. 새로 그려질 때 마다 갱신됨.
		private _readOnlyCache: boolean = null;
		// 커스텀스크롤 사용여부
		private _useCustomScroll: boolean = null;


		constructor(id?: string) {
			super(id);

			this._addBindableProperty("enabled", true).withSetterValidatorWithType(false, "boolean");
			this._addBindableProperty("readOnly", false).withSetterValidatorWithType(false, "boolean");
		}

		protected override _isConfigurableProperty(propName: string): boolean {
			if (propName == "enabled" || propName == "readOnly") {
				return true;
			}
			return super._isConfigurableProperty(propName);
		}

		/**
		 * 컨트롤의 활성화 여부를 설정합니다.
		 * @param enable 컨트롤의 활성화 여부.
		 */
		public set enabled(enable: boolean) {
			this._bindables.set("enabled", enable);
			if (this._isStateCacheEnabled() && this._enabledCache != enable) {
				this._enabledCache = null;
			}
		}

		/**
		 * 컨트롤의 활성화 여부를 반환합니다.
		 * @return 컨트롤의 활성화 여부.
		 */
		public get enabled(): boolean {
			return this._getParentFirstBindableBooleanProp("enabled", false);
		}

		/**
		 * 현재 그려진 상태에서 활성화 여부를 반환합니다.
		 * @return 현재 그려진 상태의 활성화 여부
		 */
		public _isEnabled(): boolean {
			if (this._isStateCacheEnabled()) {
				if (this._enabledCache == null) {
					this._enabledCache = this.enabled;
				}
				return this._enabledCache;
			}
			let value: boolean = this._bindables.get("enabled");
			if (value) {
				let parentCtrl: EnableUIControl = this.getVisualParentControl() as EnableUIControl;
				if (parentCtrl) {
					return parentCtrl._isEnabled(); // 상위 캐시 이용
				}
			}
			return value;
		}

		/**
		 * 수정이 불가능한 읽기 전용모드 적용 여부를 설정합니다.
		 * @param readonly 읽기 전용 모드 적용 여부.
		 */
		public set readOnly(readonly: boolean) {
			this._bindables.set("readOnly", readonly);
			if (this._isStateCacheEnabled() && this._readOnlyCache != readonly) {
				this._readOnlyCache = null;
			}
		}

		/**
		 * 수정이 불가능한 읽기 전용모드 적용 여부를 반환합니다.
		 * @return 읽기 전용 모드 적용 여부
		 */
		public get readOnly(): boolean {
			return this._getParentFirstBindableBooleanProp("readOnly", true);
		}

		/**
		 * 현재 그려진 상태에서 읽기전용 여부를 반환합니다.
		 * @return 현재 그려진 상태의 읽기전용 여부
		 */
		public _isReadOnly(): boolean {
			if (this._isStateCacheEnabled()) {
				if (this._readOnlyCache == null) {
					this._readOnlyCache = this.readOnly;
				}
				return this._readOnlyCache;
			}
			let value: boolean = this._bindables.get("readOnly");
			if (value == false) {
				let parentCtrl: EnableUIControl = this.getVisualParentControl() as EnableUIControl;
				if (parentCtrl) {
					return parentCtrl._isReadOnly(); // 상위 캐시 이용
				}
			}
			return value;
		}

		/**
		 * default.js에 정의된 커스텀스크롤바 사용여부를 리턴합니다.
		 * 기본값은 false 입니다.
		 * @return 커스텀스크롤바 사용여부
		 */
		public _isUseCustomScroll(): boolean {
			if (this._useCustomScroll === null) {
				let appConf: core.AppConfig = core.AppConfig.INSTANCE;

				// control별 설정을 먼저 조회
				let config: core.Config = this._getDefaultConfiguration();
				let jsonConfig: {} = config.toJSON();
				if (jsonConfig.hasOwnProperty("useCustomScrollbar")) {
					let useCustomScroll: boolean = jsonConfig["useCustomScrollbar"];
					if (useCustomScroll === true) {
						this._useCustomScroll = true;
					} else if (useCustomScroll === false) {
						this._useCustomScroll = false;
					}
				}
				// 다음 전역설정을 조회
				if (this._useCustomScroll === null) {
					let envConf: core.Config = appConf.getEnvConfig();
					if (envConf) {
						this._useCustomScroll = Boolean(envConf.getValue("useCustomScrollbar", false));
					} else {
						this._useCustomScroll = false;
					}
				}
			}
			return this._useCustomScroll;
		}

		public override _createControlShape(): ufc.ControlShape {
			// 새로 그릴때 마다 캐시 초기화
			this._readOnlyCache = null;
			this._enabledCache = null;

			return super._createControlShape();
		}

		/**
		 * UIControl이 readonly일 때 통과시킬 whitelist event type
		 */
		private static readonly _readonlyWhiteList: string[] = [
			"focus", "blur", "focusin", "focusout"
			, "select"
			, "mousedown", "mouseup", "mousemove", "mouseover", "mouseenter", "mouseleave", "click", "wheel", "dblclick"
			, "keydown", "keypress"
			, "load"];

		private static readonly _disabledWhiteList: string[] = [
			"unload", "load", "error", "wheel"
		];
		private static readonly _disabledTargetWhiteList: string[] = [
			"contextmenu"
		];
		/**
		 * UIControl의 상태 별로 이벤트의 활성화 여부를 체크.
		 * Concrete UIControl 내부 이벤트와 사용자 이벤트 전파에 공통적으로 적용됨.
		 * @param e 이벤트
		 */
		public override _checkControlStateForEvent(e: events.CEvent = null): boolean {
			if (super._checkControlStateForEvent(e) === false) {
				return false;
			}
			// DOM Event인 경우 컨트롤의 상태에 맞게 필터링
			if (ufc.EventAttacher._isTransientEvent(e.type)) {
				// 보여지고 활성화(enabled)된 컨트롤만 이벤트 실행
				if (e && this._isEnabled() == false && EnableUIControl._disabledWhiteList.indexOf(e.type) == -1) {
					if (EnableUIControl._disabledTargetWhiteList.indexOf(e.type) > -1) {
						e._prepareWithTarget(this);
					}
					return false;
				}
				if (e && this._isReadOnly() == true && EnableUIControl._readonlyWhiteList.indexOf(e.type) == -1) {
					return false;
				}
			}
			// CustomEvent인 경우 상태에 상관 없이 통과

			return true;
		}

		/**
		 * 해당 속성 값이 변동된 후에 수행되는 api입니다.
		 * @param name 속성 명
		 * @param oldValue 이전 속성 값.
		 * @param newValue 현재 속성 값.
		 */
		public override _valueDidChange(prop: string, oldValue: any, newValue: any): void {
			super._valueDidChange(prop, oldValue, newValue);

			switch (prop) {
				case "enabled": {
					this._enabledCache = null;
					this.redraw();
					break;
				}
				case "readOnly": {
					this._readOnlyCache = null;
					this.redraw();
					break;
				}
			}
		}

	}
}