namespace cpr.data.header {
	export class Headers {
		private _headerList: Header[];
		private _headerIndices: { [name: string]: number };

		constructor() {
			this._headerList = [];
			this._headerIndices = {};
		}

		/**
		 * 헤더들 모두 제거합니다.
		 * @param headerType 
		 */
		public clear(headerType: HeaderType = HeaderType.ALL) {
			if (headerType == HeaderType.ALL) {
				this._headerList = null;
				this._headerIndices = null;

				this._headerList = [];
				this._headerIndices = {};
			} else {
				let length: number = this._headerList.length;
				for (let idx = length - 1; idx >= 0; idx--) {
					if (this._headerList[idx].getColumnType() == headerType) {
						this._headerList.splice(idx, 1);
					}
				}

				this._headerIndices = null;
				this._headerIndices = {};
				length = this._headerList.length;
				for (let idx = 0; idx < length; idx++) {
					let name: string = this._headerList[idx].getName();
					this._headerIndices[name] = idx;
				}
			}
		}

		/**
		 * @private
		 * @param column 
		 */
		public _addHeader(column: Header): void {
			if (this._isExist(column.getName()) == false) {
				let index: number = this._headerList.length;
				this._headerList[index] = column;
				this._headerIndices[column.getName()] = index;
			}
		}

		/**
		 * @private
		 * @param columnName 
		 */
		public _deleteHeader(columnName: string): void {
			let index: number = this._headerIndices[columnName];
			if (index != -1) {
				this._headerList.splice(index, 1);

				this._headerIndices = null;
				this._headerIndices = {};
				length = this._headerList.length;
				for (let idx = 0; idx < length; idx++) {
					let name: string = this._headerList[idx].getName();
					this._headerIndices[name] = idx;
				}
			}
		}

		/**
		 * @private
		 * DataMap에서 서로 다른 상태인 컬럼의 컬럼명중복을 허용함
		 * (삭제상태의 column:A, 신규상태의 column:A)
		 */
		public _deleteHeaderFromIndex(columnIndex: number): void {
			let header: Header = this._headerList[columnIndex];
			if (header != null) {
				this._headerList.splice(columnIndex, 1);

				this._headerIndices = null;
				this._headerIndices = {};
				length = this._headerList.length;
				for (let idx = 0; idx < length; idx++) {
					let name: string = this._headerList[idx].getName();
					this._headerIndices[name] = idx;
				}
			}
		}

		/**
		 * @private
		 * @param columntype 
		 */
		public _getColumnNames(columntype: header.HeaderType = header.HeaderType.ALL): string[] {
			if (this._checkColumntype(columntype) == false) {
				return null;
			}
			let result = [];
			let headerLength = this._headerList.length;
			for (let i = 0; i < headerLength; i++) {
				if (columntype & this._headerList[i].getColumnType()) {
					result[result.length] = this._headerList[i].getName();
				}
			}
			return result;
		}

		/**
		 * @private
		 * @param columnName 
		 */
		public _isExist(columnName: string): boolean {
			return this._headerIndices.hasOwnProperty(columnName);
		}
		/**
		 * @private
		 * @param columnName 
		 */
		public _isDisplayHeader(columnName: string): boolean {
			let header: Header = this._getHeader(columnName);
			if (header != null && header._isDisplayHeader()) {
				return true;
			}
			return false;
		}

		/**
		 * @private
		 * @param columnName 
		 */
		public _getIndexFromName(columnName: string): number {
			// if (this._isExist(columnName)) { // 불필요한 반복적인 체크로직 제거
			// 	return this._headerIndices[columnName];
			// }
			// return -1;
			let idx: number = this._headerIndices[columnName];
			return idx >= 0 ? idx : -1;
		}

		/**
		 * @private
		 * @param columnIndex 
		 */
		public _getNameFromIndex(columnIndex: number): string {
			let header: header.Header = this._headerList[columnIndex];
			if (header == null) {
				return null;
			}
			return header.getName();
		}

		/**
		 * @private
		 * @param columntype 
		 */
		public _getHeaders(columntype: header.HeaderType = header.HeaderType.ALL): Header[] {
			if (this._checkColumntype(columntype) == false) {
				return [];
			}

			if (columntype == header.HeaderType.ALL) {
				return [].concat(this._headerList);

			} else {
				let result: Header[] = [];
				let columnLength: number = this._headerList.length;
				for (let i = 0; i < columnLength; i++) {
					if (columntype === this._headerList[i].getColumnType()) {
						result[result.length] = this._headerList[i];
					}
				}
				return result;
			}
		}
		/**
		 * @private
		 */
		public _getCount(): number {
			return this._headerList.length;
		}
		/**
		 * 
		 * @private
		 * @param columnName 
		 */
		public _getHeader(columnName: string): Header {
			let headerIndex: number = this._getIndexFromName(columnName);
			return this._getHeaderFromIndex(headerIndex);
		}

		/**
		 * @private
		 * @param columnIndex 
		 */
		public _getHeaderFromIndex(columnIndex: number): Header {
			if (columnIndex == -1) {
				return null;
			}
			return this._headerList[columnIndex];
		}

		private _checkColumntype(columntype: header.HeaderType): boolean {
			let headerTypes: string[] = Object.keys(header.HeaderType);
			let length: number = headerTypes.length;
			let result: boolean = false;
			for (let i = 0; i < length; i++) {
				if (columntype === header.HeaderType[headerTypes[i]]) {
					result = true;
					break;
				}
			}
			return result;
		}

	}
}