/// <reference path="../Submission.ts"/>


namespace cpr.protocols.request {

	/**
	 * @private
	 */
	export interface JSONRequestObject {
		reqObj?: any
		, param?: { [key: string]: string[] } /* parameters */
		, data?: { /* datamap, dataset */
			[key: string]:
			{ [key: string]: string | number | boolean } /* datamap */
			| { [key: string]: string | number | boolean }[] /* dataset */
		}
	}
	/**
	 * @private
	 */
	export class JSONRequestBuilder extends AbstractRequestBuilder {
		private static _assembleEncodedResult(encodingResult: EncodingResult): string {
			let key: string = encodingResult.key;
			let value: {} | string = encodingResult.content;
			let res: string = null;
			if (typeof value == "string") {
				if (key) {
					let jobj: {} = {};
					jobj[key] = value;
					res = JSON.stringify(jobj);
				} else {
					res = value;
				}
			} else if (value != null) {
				res = JSON.stringify(value);
			} else {
				res = "";
			}
			key = null;
			value = null;

			return res;
		}

		constructor() {
			super();
		}

		public getContentType(): string {
			return Submission.MEDIA_JSON;
		}

		protected _buildSpecific(submission: Submission): any {
			if (Submission._HASBODY_METHOD.indexOf(submission.method) === -1) {
				console.warn("Submission(\"" + submission.id + "\") method has been changed to POST. \"" + Submission.MEDIA_JSON + "\" media types can not use " + submission.method.toUpperCase() + " method. Available methods [" + Submission._HASBODY_METHOD.join(",").toUpperCase() + "]");
				submission.method = Submission.METHOD_POST;
			}

			// json request object
			let jsonobject: JSONRequestObject = null;
			let requestEncoderSpec: RequestEncoderSpec = submission._getRequestEncoder();

			if (requestEncoderSpec && requestEncoderSpec.encoder) {
				if (requestEncoderSpec.usingBuildData) {
					jsonobject = this._buildJsonRequestObject(submission);
				}

				let returnValue: Promise<EncodingResult> | EncodingResult = requestEncoderSpec.encoder(submission, jsonobject);
				if (returnValue instanceof Promise) {
					return returnValue.then((encodingResult: EncodingResult) => {
						let res: string = JSONRequestBuilder._assembleEncodedResult(encodingResult);
						if (encodingResult.contentType) {
							submission._setInstantContentType(encodingResult.contentType);
						}

						encodingResult = null;
						jsonobject = null;
						return res;
					});
				} else {
					let res: string = JSONRequestBuilder._assembleEncodedResult(returnValue);
					if (returnValue.contentType) {
						submission._setInstantContentType(returnValue.contentType);
					}

					returnValue = null;
					jsonobject = null;
					return res;
				}
			} else {
				jsonobject = this._buildJsonRequestObject(submission);

				let jsonstring: string = JSON.stringify(jsonobject);
				jsonobject = null;

				return jsonstring;
			}
		}

		public _buildJsonRequestObject(submission: Submission): JSONRequestObject {
			// json request object
			let jsonobject: JSONRequestObject = {};

			// check requestObject
			let requestObject: Object = submission.getRequestObject();
			if (requestObject != null) {
				jsonobject.reqObj = requestObject;
			}

			// parameter
			let parameterNames: string[] = submission.getParameterNames();
			if (parameterNames && parameterNames.length > 0) {
				jsonobject.param = {};
				parameterNames.forEach((name: string) => {
					let values: string[] = submission.getParameters(name);
					jsonobject.param[name] = values;
				});
			}

			// datamap/dataset - json 데이터는 데이터형에서 DataSet인지 DataMap 인지 구분할 수 있기 때문에 별도의 type 파라메터는 전송하지 않음.
			let requestDataCount: number = submission.getRequestDataCount();
			if (requestDataCount > 0) {
				jsonobject.data = {};
				for (let idx: number = 0; idx < requestDataCount; idx++) {
					let requestData: RequestData = submission.getRequestData(idx);
					let alias: string = this._getRequestAlias(requestData);
					if (requestData.data instanceof data.DataSet) {
						let dataSet: data.DataSet = requestData.data as data.DataSet;
						let dataDelimiter: string = null;
						if (alias) {
							dataDelimiter = alias;
						} else {
							dataDelimiter = super._createDataDelimiter();
						}

						jsonobject.data[dataDelimiter] = this._buildDataSet(submission, dataSet, requestData.payload);
					} else {
						let dataMap: data.DataMap = requestData.data as data.DataMap;
						let dataDelimiter: string = null;
						if (alias) {
							dataDelimiter = alias;
						} else {
							dataDelimiter = super._createDataDelimiter();
						}

						jsonobject.data[dataDelimiter] = this._buildDataMap(submission, dataMap);
					}
				}
			}

			return jsonobject;
		}

		private _buildDataSet(submission: Submission, dataSet: data.DataSet, payload: PayloadType): { [key: string]: string | number | boolean }[] {
			let rowDatas: { [key: string]: string | number | boolean }[] = [];
			this._loadPayload(submission, dataSet, payload, (rowdata: data.RowConfigInfo, additionalParam: { [key: string]: string }, stateText: string) => {
				let newRowData: { [key: string]: string | number | boolean } = _shallowCopyObject(rowdata);
				newRowData["sts"] = stateText;
				if (!data.DataUtil._hasDefaultPolicy()) {
					for (let key in newRowData) {
						if (newRowData[key] == null) {
							newRowData[key] = "";
						}
					}
				}

				this._applyAdditionalParam(newRowData, additionalParam);

				rowDatas.push(newRowData);
			});

			return rowDatas;
		}

		private _buildDataMap(submission: Submission, dataMap: data.DataMap): { [key: string]: string | number | boolean } {
			let dataMapData: { [key: string]: string | number | boolean } = {};

			let columnNames: string[] = dataMap.getColumnNames();
			columnNames.forEach((columnName: string) => {
				let value: (string | number | foundation.DecimalType) = dataMap.getValue(columnName);
				if (value instanceof foundation.DecimalType) {
					value = value.toString();
				}
				if (!data.DataUtil._hasDefaultPolicy()) {
					if (value == null) {
						value = "";
					}
				}
				dataMapData[columnName] = value;
			});

			this._applyAdditionalParam(dataMapData, submission._handleDataMap(dataMap));

			return dataMapData;
		}

		private _applyAdditionalParam(newRowData: { [key: string]: string | number | boolean }, additionalParam: { [key: string]: string }): void {
			if (additionalParam) {
				for (let key in additionalParam) {
					let value: string = additionalParam[key];
					if (value == null) {
						newRowData[key] = "";
					} else {
						newRowData[key] = value;
					}
				}
			}
		}

	}

}