/// <reference path="./ActiveScrollStrategy.ts"/>



namespace cpr.controls.gridpart.layout {

	/**
	 * @private
	 */
	export abstract class BufferedScrollStrategy extends ActiveScrollStrategy {
		private _startRenderRow: number = -1;
		private _vscrollbarEventOwner: boolean = false; // 가상스크롤바의 이벤트를 받은 이벤트 소유자 여부


		constructor(scrollPane: ScrollPane, context: GridContext) {
			super(scrollPane, context);
		}

		public _readyForRedraw(): void {
			super._readyForRedraw();
			this._setRenderStartRow(-1);
		}

		protected _init(): void {
			super._init();

			let renderstartrow: number = this._getRenderStartRow();
			if (renderstartrow != null && renderstartrow > -1) {
				return;
			}

			let startrowindex: number = this._context._getStartRowIndex(GRIDREGION.MIDDLE);
			this._setRenderStartRow(startrowindex);
		}

		private _setRenderStartRow(startRow: number): void {
			this._startRenderRow = startRow;
		}
		/**
		 * 그려진 시작 index.
		 */
		public _getRenderStartRow(): number {
			if (this._context._isWholeRenderingMode()) {
				return this._context._getStartRowIndex(this._scrollPane.location);
			} else {
				let contextStartRow: number = this._context._getStartRowIndex(this._scrollPane.location);
				if (this._startRenderRow != contextStartRow) {
					if (this._startRenderRow == -1 || this._startRenderRow < contextStartRow) {
						this._startRenderRow = contextStartRow;
					} else {
						let contentView: IGridPartArea = this._scrollPane.owner;
						if (contentView) {
							let contentHeight = contentView._getContentHeight();
							if (contentHeight <= this._getViewportHeight()) {
								this._startRenderRow = contextStartRow;
							}
						}
					}
				}

				return this._startRenderRow;
			}
		}

		/**
		 * 그려진 마지막 index.
		 */
		public _getRenderEndRow(): number {
			if (this._context._isWholeRenderingMode()) {
				return this._context._getEndRowIndex(this._scrollPane.location);
			} else {
				let renderStartRow: number = this._getRenderStartRow();
				let viewportHeight: number = this._getViewportHeight();

				return this._context._getRenderLastRowIndexInViewportHeight(this._scrollPane.location, renderStartRow, viewportHeight);
			}
		}

		/**
		 * 특정 로우로 이동할 때 Scroll 처리를 위한 EventListener.
		 * GridShape에서 pagedown, pageup 또는 GridAPI를 이용하여 특정 Row로 이동할 때 사용.
		 * @param e 
		 * @override
		 */
		public _onJumpPage(e: events.CUIEvent): void {
			// viewport의 높이가 0이거나 보여지지 않을 때(감춰졌을 때)는 jump를 동작시키지 않는다.
			// tab의 감춰진 tabitem에 grid가 숨겨졌을 때 오동작 발생.
			let viewportHeight: number = this._getViewportHeight();
			if (viewportHeight == 0) {
				return;
			}

			let startrowindex: number = this._context._getStartRowIndex(GRIDREGION.MIDDLE);
			let endrowindex: number = this._context._getEndRowIndex(GRIDREGION.MIDDLE);
			if (startrowindex == -1 || endrowindex == -1) {
				// 비활성화
				return;
			}

			let moveposition: {
				srcIndex: number, offset: number, jumpIndex: number, jumpedIndex: number, isDataRow: boolean
			} = e.content as {
				srcIndex: number, offset: number, jumpIndex: number, jumpedIndex: number, isDataRow: boolean
			};

			// jumpIndex를 기준으로 offset을 설정하여 스크롤의 방향을 다음 로직에 제공
			if (moveposition.jumpIndex >= 0) {
				moveposition.offset = this._getJumpDirection(moveposition.jumpIndex);
			}

			// 이동할 RowIndex
			let targetIndex: number = this._getTargetRowIndex(moveposition, startrowindex, endrowindex);
			if (targetIndex == -1) {
				return;
			}

			// targetIndex가 현재 viewport 내에 존재하는 rowIndex인 경우 스크롤 이동이 되지않도록 처리
			var viewportStartRowIndex: number = this._context._getRenderStartRowOverScrollTop(this._scrollPane.location, this.virtualscrolltop);
			let viewportEndRowIndex: number = this._context._getRenderLastRowIndexInViewportHeight(this._scrollPane.location, viewportStartRowIndex, viewportHeight);
			if (targetIndex >= viewportStartRowIndex && targetIndex < viewportEndRowIndex) {
				return;
			}


			let scrolltop: number = 0;
			if (targetIndex == 0 || targetIndex == startrowindex) {
				scrolltop = 0;
			} else {
				let maxScrollTop: number = this._getNewestMaxScrollTop(); // 이 이벤트가 들어오기 전에 행이 추가되었을 수 있기 때문에 최신 스크롤탑으로 연산
				if (targetIndex == endrowindex) {
					scrolltop = maxScrollTop;
				} else {
					if (moveposition.offset > 0) {
						// scroll down
						let firstRowIndex: number = this._context._getRenderStartRowIndexFromSelectableLastRowIndex(this._scrollPane.location, targetIndex, viewportHeight);
						scrolltop = this._context._getRangeHeight(startrowindex, firstRowIndex - 1, this._scrollPane.location);
					} else {
						// scroll up
						scrolltop = this._context._getRangeHeight(startrowindex, targetIndex - 1, this._scrollPane.location);
					}
					if (scrolltop < 0) {
						scrolltop = 0;
					} else if (scrolltop > maxScrollTop) {
						scrolltop = maxScrollTop;
					}
				}
			}

			let axis: events.ScrollAxis = this._adjustViewportScroll(e, scrolltop, this.viewportscrollleft);

			if (axis != null) {
				this._dispatchScrollEvent(e, axis); // grid scroll event
			}
		}

		// 이동할 RowIndex 계산 Func
		protected abstract _getTargetRowIndex(moveposition: { srcIndex: number, offset: number, jumpIndex: number, jumpedIndex: number, isDataRow: boolean }
			, startrowindex: number, endrowindex: number): number;


		protected _onViewportScroll(e: events.CUIEvent): void {
			// 세로 스크롤 처리 추가(걸쳐진 로우를 클릭했을 때 처리)
			let target: HTMLElement = <HTMLElement>e.target;
			let scrollTop: number = target.scrollTop;
			if (this._context._isWholeRenderingMode()) {
				if (this._settedScrollTop !== -1 && GridUtil._equalsApproximately(scrollTop, this._settedScrollTop)) {
					scrollTop = this.viewportscrolltop;
					this._settedScrollTop = -1;
				} else {
					scrollTop = scrollTop;
				}
			} else {
				scrollTop = this.viewportscrolltop + scrollTop;
			}

			let scrollLeft: number = target.scrollLeft;

			if (this._settedScrollLeft !== -1 && GridUtil._equalsApproximately(scrollLeft, this._settedScrollLeft)) {
				scrollLeft = this.viewportscrollleft;
				this._settedScrollLeft = -1;
			}

			let axis: events.ScrollAxis = this._adjustViewportScroll(e, scrollTop, scrollLeft);
			e.preventDefault();
			if (axis != null) {
				this._dispatchScrollEvent(e, axis); // grid scroll event
			}
		}

		public _setViewportScrollTop(e: events.CEvent, scrollTop: number): number { // 그리드 가상스크롤바의 스크롤 이벤트 발생시 뷰포트의 스크롤탑 조정
			// WIN7 Chrome의 경우 scrollTop에 소수점이 포함될 수 있어서 최대 스크롤일 경우 보정.
			// if (GridUtil._equalsApproximately(this.virtualscrolltop, scrollTop)) {
			if (this._context.disposed == true) {
				return;
			}
			if ((scrollTop == 0 && this.virtualscrolltop == 0) || (scrollTop != 0 && GridUtil._equalsApproximately(this.virtualscrolltop, scrollTop))) {
				return scrollTop;
			}
			let maxScrollTop: number = this._getRenderedMaxScrollTop();
			if (GridUtil._equalsApproximately(maxScrollTop, scrollTop)) {
				scrollTop = maxScrollTop;
			}

			this._moveFocusToGrid();

			this._scrollPane._postScrollTop(scrollTop, e);
			this.viewportscrolltop = scrollTop; // 스크롤바에서 이벤트가 발생했을 경우 scrollTop을 동기화 대상에서 제외
			this._vscrollbarEventOwner = true;

			this._dispatchScrollEvent(e, events.ScrollAxis.y); // grid scroll event

			return scrollTop;
		}

		/**
		 * ScrollBus에서의 스크롤 변경 통지 처리
		 * @override
		 * @param e 
		 */
		public _handleScrollTop(e: events.CScrollEvent): void {
			let scrollTop: number = e.scrollTop;

			if (this._context._isWholeRenderingMode()) {
				core.DeferredUpdateManager.INSTANCE._asyncExecBefore(() => {
					if (this._context == null || this._context.disposed == true) {
						return;
					}
					let scrollTop: number = this._scrollPane._getBusScollTop();
					this._settedScrollTop = scrollTop;
					if (this.viewportscrolltop !== scrollTop) {
						this._setViewportVScroll(scrollTop);
					}
					if (this.virtualscrolltop !== scrollTop) {
						this._setVScroll(scrollTop);
					}
				});
			} else {
				let reqIdx: { startIdx: number, endIdx: number } = this._getScrollDataIndex(scrollTop);

				let renderstartrow: number = this._getRenderStartRow();
				let renderendrow: number = (this._scrollPane.owner as GridDetail)._getRenderedEndRowIdx();

				let requiredrowstart: number = reqIdx.startIdx;
				let requiredrowend: number = reqIdx.endIdx;

				if (requiredrowstart != renderstartrow || requiredrowend != renderendrow) {
					this._setRenderStartRow(requiredrowstart);
				}

				if (this.virtualscrolltop !== scrollTop) { // redraw시 CustomScrollbar의 위치를 보전하기 위해 virtualscrolltop 설정
					this._setVScroll(scrollTop);
				}

				// shape deferred update
				// @experimental RELATED DataWindow
				let dataProvider: provider.GridDataProvider = this.grid.dataProvider;
				if (dataProvider._isWholeDataAccessable()) {
					this._selfRedraw();
				} else {
					let rowCnt: number = requiredrowend - requiredrowstart + 1;
					dataProvider._setFetchHandler(requiredrowstart, rowCnt, () => {
						this._setRenderStartRow(requiredrowstart);
						this._setVScroll(scrollTop);
						this._selfRedraw();
					});
				}
			}
		}
		public _handleScrollLeft(e: events.CScrollEvent): void {
			super._handleScrollLeft(e);
			if (this._context._isWholeRenderingMode() === false) {
				// shape deferred update
				this._selfRedraw();
			}
		}

		protected _syncScroll(): void {
			if (this._context == null || this._context.disposed == true) {
				return;
			}
			if (this._context._isWholeRenderingMode() !== true || this._settedScrollTop == -1) {
				let eventScrollTop: number = this._scrollPane._getBusScollTop();
				if (this._vscrollbarEventOwner) {
					this._vscrollbarEventOwner = false;
				} else {
					this._setViewportVScroll(eventScrollTop);
				}
				this._setVScroll(eventScrollTop);
			}
			if (this._settedScrollLeft == -1) {
				let eventScrollLeft: number = this._scrollPane._getBusScrollLeft();
				if (eventScrollLeft != -1) {
					this._setViewportHScroll(eventScrollLeft);
					this._setHScroll(eventScrollLeft);
				}
			}
		}

		/**
		 * Vertical Scroll 이벤트를 받아 viewport의 top 위치 변경
		 */
		protected _setVScroll(scrollTop: number): void {
			if (this._context._isWholeRenderingMode()) {
				super._setVScroll(scrollTop); // 항상 위로 고정 : 포커스에 의한 뷰포트의 스크롤 이동 방지
			} else {
				super._setVScroll(0); // 항상 위로 고정 : 포커스에 의한 뷰포트의 스크롤 이동 방지
			}

			this.virtualscrolltop = scrollTop;
		}

		/**
		 * 현재 화면을 기준으로 jump할 행의 방향을 제공
		 * @param targetIndex 
		 * @returns 
		 * -1 : scroll up
		 * 1 : scroll down
		 * 0 : no scroll movement 
		 */
		// 
		protected _getJumpDirection(targetIndex: number): number {
			let direction: number = 0;
			let viewportHeight: number = this._getViewportHeight();
			var viewportStartRowIndex: number = this._context._getRenderStartRowOverScrollTop(this._scrollPane.location, this.virtualscrolltop);
			let viewportEndRowIndex: number = this._context._getRenderLastRowIndexInViewportHeight(this._scrollPane.location, viewportStartRowIndex, viewportHeight);

			if (viewportEndRowIndex === -1) {
				direction = 1;
			} else {
				if (targetIndex <= viewportStartRowIndex) {
					direction = -1;
				} else if (targetIndex >= viewportEndRowIndex) {
					direction = 1;
				}
			}

			return direction;
		}
	}
}