namespace cpr.utils {
	export interface CellStyle {
		type: string, // string|number|formula
		rowindex: number,
		colindex: number,
		rowspan: number,
		colspan: number,
		style?: {
			[styleName: string]: string
		},
		autorowheight?: boolean,
		format?: string,
		formula?: string,
		// columnHandler key 
		cellIndex?: number,
		columnName?: string
	}

	export type CellData = (string | number | { value?: string | number, style?: { [styleName: string]: string }, rowspan?: number, colspan?: number });

	export interface RowGroup {
		region: controls.gridpart.VLOC_REGION,
		style?: CellStyle[],
		data: CellData[][]
	}

	/**
	 * 그리드 엑셀 익스포트 옵션
	 */
	export interface ExportOption {
		/**
		 * 셀 스타일을 Export시 제외할 지 여부. default true.
		 */
		exceptStyle?: boolean,
		/**
		 * 셀에 적용된 class의 스타일을 셀 스타일에 반영할지 여부. default false.<br>
		 * true로 설정시 class에 의해 적용되는 CSS 속성을 브라우저에서 측정하여 셀의 style에 병합하므로,
		 * class로만 스타일을 지정한 경우에도 별도의 매핑 없이 익스포트 결과에 스타일이 반영됩니다.<br>
		 * 바인딩 없이 지정한 class의 스타일은 행마다 달라지지 않으므로 인라인 스타일과 동일하게
		 * rowgroup의 공통 스타일에 반영됩니다.<br>
		 * 익스프레션 바인딩으로 class를 지정한 경우 해당 셀이 속한 행을 기준으로 평가되므로,
		 * 행마다 다른 class가 적용되는 경우에도 셀 단위로 스타일이 반영됩니다.<br>
		 * 셀에 배치한 컨트롤에 지정한 class는 컨트롤 요소를 기준으로 측정하므로,
		 * 컨트롤을 대상으로 하는 선택자(.cl-control.xxx 등)로 정의한 스타일도 렌더링과 같게 반영되며,
		 * 렌더링과 동일하게 컨트롤에 지정한 class가 셀에 지정한 class보다 우선합니다.<br>
		 * 인라인으로 지정한 스타일이 class 스타일보다 우선합니다.<br>
		 * 엑셀에서 표현할 수 없는 속성, :hover 등 상태에 따라 달라지는 스타일은 반영되지 않으며,
		 * 그리드가 화면에 렌더링되지 않은 상태에서는 측정이 불가능하여 반영되지 않습니다.<br>
		 * exceptStyle이 true인 경우 셀 스타일 자체를 반환하지 않으므로 해당 옵션은 무시됩니다.
		 */
		applyClassStyle?: boolean,
		/**
		 * 컨트롤에 보이는 그대로 반영할지 유무. default true. <br>
		 * true : 컨트롤에 보이는 그대로 익스포트 됩니다.<br>
		 * false : 데이터(데이터셋) 자체를 반환하며, 데이터타입이 number인 형우 해당 데이터 타입도 적용됩니다.
		 */
		applyFormat?: boolean,
		/**
		 * 엑셀로 익스포트시 엑셀의 format 기능을 사용할지 여부. default true.<br>
		 * useFormat=true를 적용되게 하기 위해서는 applyFormat이 true여야 합니다.
		 */
		useFormat?: boolean,
		/**
		 * 엑셀 익스포트시 suppress, mergedToIndexExpr에 의한 셀 병합을 반영할지 여부. default false.<br>
		 * applySuppress 설정시 rows 옵션을 지원되지 않습니다.
		 */
		applySuppress?: boolean,
		/**
		 * 엑셀 Export 시 헤더 부분을 틀고정할지 여부를 설정. default false.
		 */
		freezeHeader?: boolean,
		/**
		 * 불필요한 데이터를 제거할 지 여부. (ex. {}(empty json object)) default false. <br>
		 * 익스포트 데이터 전체 용량을 줄이는 데 도움이 됩니다.
		 */
		reduce?: boolean,
		/**
		 * @deprecated 2022.11.04. excludeCellIndex을 사용하시기 바랍니다.
		 */
		excludeCols?: number[],
		/**
		 * Export시 제외시킬 header cellIndex 배열. <br>
		 * excludeCellIndex 설정시 visible=false로 설정된 셀도 모두 포함합니다.
		 */
		excludeCellIndex?: number[],
		/**
		 * Export시 제외시킬 colIndex 배열. <br>
		 * excludeColIndex 설정시 visible=false로 설정된 셀도 모두 포함합니다.
		 */
		excludeColIndex?: number[],
		/**
		 * Export시킬 특정 row index 배열.
		 */
		rows?: number[],
		/**
		 * 엑셀 Export 시 행별 스타일 또는 데이터를 변경할 수 있는 핸들러.
		 */
		rowDataHandler?: (datas: CellData[], rowIndex: number) => void,
		/**
		 * 엑셀 Export 시 셀별 스타일 또는 포맷을 변경할 수 있는 핸들러.
		 */
		rowgroupStyleHandler?: (cellStyle: utils.CellStyle, region: controls.gridpart.VLOC_REGION, cellIndex: number, columnName: string) => void
	}

	export interface ExportData {
		/**
		 * 엑셀 export시 설정 정보. (암호, 출력용지방향)
		 * wrapLineBreak : 기본값 false. true로 설정된 경우 값에 개행문자가 있는 셀은 wrap 됩니다.
		 */
		metadata: { password: string, printPageOrientation: string, wrapLineBreak: boolean, [key: string]: (string | boolean) },
		/**
		 * 시트명.
		 */
		name: string,
		/**
		 * 컬럼과 로우의 틀고정 갯수.
		 */
		freezepane?: { colsplit: number, rowsplit: number },
		/**
		 * 컬럼 레이아웃 정보.
		 */
		cols: controls.gridpart.GridColumnConfig[],
		/**
		 * 행 정보.
		 */
		rowgroups: utils.RowGroup[]
	}


	export interface MultiSheetExportData {
		/**
		 * 엑셀 export시 설정 정보. (암호, 출력용지방향)
		 */
		metadata: { password: string, printPageOrientation: string, wrapLineBreak: boolean, [key: string]: (string | boolean) },
		/**
		 * 시트 정보.
		 */
		sheets: {
			/**
			 * 시트명.
			 */
			name: string,
			/**
			 * 컬럼과 로우의 틀고정 갯수.
			 */
			freezepane?: { colsplit: number, rowsplit: number },
			/**
			 * 컬럼 레이아웃 정보.
			 */
			cols: controls.gridpart.GridColumnConfig[],
			/**
			 * 행 정보.
			 */
			rowgroups: RowGroup[]
		}[]
	}

	/**
	 * @noinstance
	 */
	export class ExportUtil {
		private static instance: ExportUtil;


		static get INSTANCE() {
			if (ExportUtil.instance == null) {
				ExportUtil.instance = new ExportUtil();
			}
			return ExportUtil.instance;
		}

		/**
		 * 멀티 시트 익스포트시 여러 그리드의 데이터를 합쳐서 하나의 멀티 시트 익스포트 데이터로 반환합니다.
		 * @param exportDatas 그리드 데이터 배열.
		 * @return 여러 그리드 데이터가 합쳐진 하나의 익스포트 데이터.
		 */
		public static merge(exportDatas: utils.ExportData[]): utils.MultiSheetExportData {
			let sheets: {
				name: string,
				freezepane?: { colsplit: number, rowsplit: number },
				cols: controls.gridpart.GridColumnConfig[],
				rowgroups: utils.RowGroup[]
			}[] = [];
			exportDatas.forEach((exportData: utils.ExportData) => {
				sheets[sheets.length] = {
					name: exportData.name,
					cols: exportData.cols,
					freezepane: exportData["freezepane"],
					rowgroups: exportData.rowgroups
				};
			});

			return {
				metadata: { password: null, printPageOrientation: null, wrapLineBreak: false },
				sheets: sheets
			};
		}

		/**
		 * Grid 또는 DataSet의 Data를 JSON 형식으로 반환합니다.
		 * <br>
		 * @param control Grid 또는 DataSet
		 * @param exportOption Grid export 옵션.(Grid Only)<br>
		 * exceptStyle : Style을 Export시 제외할 지 여부. default true.<br>
		 * applyClassStyle : 셀에 적용된 class의 스타일을 셀 스타일에 반영할지 여부. default false. 익스프레션 바인딩으로 지정한 class는 해당 셀이 속한 행 기준으로 평가됩니다. exceptStyle이 true인 경우 무시됩니다.<br>
		 * applyFormat : Format이 적용된 그대로의 텍스트를 반환할 지 여부. default true. number 데이터 타입을 익스포트하기 위해서는 해당 옵션을 false로 주어야 합니다.<br>
		 * useFormat : 엑셀 파일 (xlsx, xls 등)으로 익스포트시 해당 파일의 format속성을 사용할지 여부. default true. <br>
		 * applySuppress : 엑셀 익스포트시 suppress, mergedToIndexExpr에 의한 셀 병합을 반영할지 여부. default false. <br>
		 *                 applySuppress 설정시 rows 옵션을 지원되지 않습니다.<br>
		 * excludeCols : Export시 제외시킬 header cellIndex 배열. 설정시 visible=false인 컬럼도 포함하여 설정해야 합니다.<br>
		 * rows : Export시킬 특정 row index 배열.<br>
		 * freezeHeader : Excel Export 시 그리드의 헤더 영역을 틀고정할지 여부. default false.<br>
		 * rowDataHandler(datas: CellData[], rowIndex: number) : 엑셀 Export 시 행별 스타일 또는 데이터를 변경할 수 있는 핸들러.<br>
		 * rowgroupStyleHandler(cellStyle: utils.CellStyle, region: VLOC_REGION, cellIndex: number, columnName: string) : 엑셀 Export 시 셀별 스타일 또는 포맷을 변경할 수 있는 핸들러.
		 * @return Export Data.<br>
		 * {
		 * 		metadata : {password: string, printPageOrientation: "PORTRAIT" | "LANDSCAPE", wrapLineBreak : true | false},<br>
		 * 		name? : string,<br>
		 * 		freezepane? : {colsplit: number, rowsplit: number},<br>
		 * 		cols: { width: string }[],<br>
		 * 		rowgroups: {<br>
		 * 		&emsp; region: string, // header, detail, footer, gheader, gfooter<br>
		 * 		&emsp; style?: {<br>
		 * 		&emsp;&emsp; type: string, // string|number<br>
		 * 		&emsp;&emsp; rowindex: number,<br>
		 * 		&emsp;&emsp; colIndex: number,<br>
		 * 		&emsp;&emsp; rowSpan: number,<br>
		 * 		&emsp;&emsp; colSpan: number,<br>
		 * 		&emsp;&emsp; style?: {<br>
		 * 		&emsp;&emsp;&emsp; [styleName: string]: (string | number)<br>
		 * 		&emsp;&emsp; }}[],<br>
		 * 		&emsp; data: (string | number)[][]<br>
		 * 		&emsp; }[]
		 * }
		 */
		public static getExportData(control: controls.Grid | data.DataCollection, exportOption?: ExportOption): ExportData {
			if (control instanceof controls.Grid) {
				return control.getExportData(exportOption);
			} else if (control instanceof data.DataCollection) {
				return ExportUtil.INSTANCE._getDataSetExportData(control, exportOption);
				// return control._getExportData();
			}
			return null;

		}

		private _getDataSetExportData(dataset: data.DataCollection, exportOption?: ExportOption): utils.ExportData {
			let columnCount: number = dataset.getColumnCount();
			let columnIndices: number[] = [];
			if (exportOption != null && exportOption.hasOwnProperty("excludeCols")) {
				for (let i = 0; i < columnCount; i++) {
					if (exportOption["excludeCols"].indexOf(i) == -1) {
						columnIndices[columnIndices.length] = i;
					}
				}
				columnCount = columnIndices.length;
			} else {
				for (let i = 0; i < columnCount; i++) {
					columnIndices[columnIndices.length] = i;
				}
			}

			let columnLayout: { width: string }[] = [];
			for (let i = 0; i < dataset.getColumnCount(); i++) {
				columnLayout[columnLayout.length] = { width: "100px" };
			}

			let excelViewRowIndex: number = 0;
			let rowgroups: utils.RowGroup[] = [];
			{ // header
				let headers: data.header.Header[] = dataset.getHeaders();
				let headerStyles: utils.CellStyle[] = [];
				let headerDatas: (string | number)[] = [];
				for (let i = 0; i < columnCount; i++) {
					let header: data.header.Header = headers[columnIndices[i]];
					headerStyles[i] = {
						type: "string",
						rowindex: 0,
						colindex: i,
						rowspan: 1,
						colspan: 1,
						columnName: header.getName()
					};
					headerDatas[i] = header.getName();
				}
				this._handleRowData(exportOption, excelViewRowIndex++, headerDatas);
				this._handleRowgroupStyle(exportOption, controls.gridpart.VLOC_REGION.HEADER, headerStyles);

				rowgroups[rowgroups.length] = {
					region: controls.gridpart.VLOC_REGION.HEADER,
					style: headerStyles,
					data: [headerDatas]
				};
			}
			let rowCount: number = dataset.getRowCount();
			if (rowCount > 0) { // detail
				let headers: data.header.Header[] = dataset.getHeaders();
				let detailStyles: utils.CellStyle[] = [];
				let detailDatas: (string | number)[][] = [];
				let rowData: (string | number)[] = null;

				if (exportOption != null && exportOption.hasOwnProperty("rows")) {
					let rowIndices: number[] = exportOption["rows"];
					let rowCount: number = rowIndices.length;
					for (let i = 0; i < rowCount; i++) {
						rowData = dataset._getRowValues(rowIndices[i], columnIndices);
						this._handleRowData(exportOption, excelViewRowIndex++, rowData);
						detailDatas[detailDatas.length] = rowData;
					}
				} else {
					for (let ri = 0; ri < rowCount; ri++) {
						rowData = dataset._getRowValues(ri, columnIndices);
						this._handleRowData(exportOption, excelViewRowIndex++, rowData);
						detailDatas[detailDatas.length] = rowData;
					}
				}

				for (let i = 0; i < columnCount; i++) {
					let header: data.header.Header = headers[columnIndices[i]];
					detailStyles[i] = {
						type: "string",
						rowindex: 0,
						colindex: i,
						rowspan: 1,
						colspan: 1,
						columnName: header.getName()

					};
					if ((header.getDataType() == data.tabledata.DataType.NUMBER || header.getDataType() == data.tabledata.DataType.DECIMAL) ||
						(header.getDataType() == data.tabledata.DataType.EXPRESSION && typeof (detailDatas[0][i]) == "number")) {
						detailStyles[i].type = "number";
					}
				}
				this._handleRowgroupStyle(exportOption, controls.gridpart.VLOC_REGION.DETAIL, detailStyles);
				rowgroups[rowgroups.length] = {
					region: controls.gridpart.VLOC_REGION.DETAIL,
					style: detailStyles,
					data: detailDatas
				};
			}

			let exportData: utils.ExportData = {
				metadata: { password: null, printPageOrientation: null, wrapLineBreak: false },
				name: null,
				cols: columnLayout,
				rowgroups: rowgroups
			};

			if (exportOption != null && exportOption.freezeHeader === true) {
				exportData["freezepane"] = { colsplit: 0, rowsplit: 1 };
			}

			return exportData;
		}

		private _handleRowData(exportOption: ExportOption, index: number, datas: utils.CellData[]): void {
			if (exportOption != null && exportOption.hasOwnProperty("rowDataHandler")) {
				exportOption.rowDataHandler(datas, index);
			}
		}

		private _handleRowgroupStyle(exportOption: ExportOption, region: controls.gridpart.VLOC_REGION, cellStyle: utils.CellStyle[]): void {
			if (exportOption != null && exportOption.hasOwnProperty("rowgroupStyleHandler")) {
				cellStyle.forEach((cellStyle: utils.CellStyle) => {
					exportOption.rowgroupStyleHandler(cellStyle, region, cellStyle.cellIndex, cellStyle.columnName);
					delete cellStyle.cellIndex;
					delete cellStyle.columnName;
				})
			}
		}


	}

}