

namespace cpr.foundation {


	/**
	 * @private
	 * InputBox 에서 사용하는 입력 문자열 필터 클래스.
	 * TODO InputBox와 하나로 합침
	 */
	export class InputFilter {

		private _regexpText: string;
		private _filterRegExp: RegExp;

		private _text: { value: string, ss: number, se: number };
		private _pasteData: { filteredText: string, text: string };
		private _pendingPasteEvent: events.CClipboardEvent;
		private _dropData: { beforeValue: string, filteredText: string, text: string };
		private _currentInputValue: string;
		// 전각/반각 regex참고. https://gist.github.com/terrancesnyder/1345094

		// private static readonly _TYPEMAP: { [type: number]: string } = {
		// 	[InputType.alphabetic]: "a-zA-Z", // imemode 일때 char가 여러 개가 들어올 수 있음
		// 	[InputType.numeric]: "0-9", // imemode 일때 char가 여러 개가 들어올 수 있음
		// 	[InputType.symbol]: "!\"#$%&'()*\\/;:<=>?@[\\\\\\]\\^_`{|}~'\\u20a9+/-", // imemode 일때 char가 여러 개가 들어올 수 있음
		// 	[InputType.space]: " " // imemode 일때 char가 여러 개가 들어올 수 있음
		// };
		// private static readonly _MODEMAP: { [mode: number]: string } = {
		// 	[InputMode.fullwidth]: "ァ-・ヽヾ゛゜ー\\uff01-\\uff60\\uffe0-\\uffe6", //전각 영문,숫자,기호, 카타카나
		// 	[InputMode.halfwidth]: "\\uff61-\\uff9f\\uffe8-\\uffee\\!\"#$%&'()*+,\\-./;:<=>?@[\\\\\\]\\^_`{|}~'\\a-zA-Z\\0-9+",//반각 카타카나,영문,숫자,기호,카타카나 기호 http://glyphwiki.org/wiki/Group:%E5%85%A8%E8%A7%92%E5%8D%8A%E8%A7%92
		// 	[InputMode.upper]: "A-Z",
		// 	[InputMode.lower]: "a-z"
		// };


		constructor() {
		}

		get filter(): string {
			return this._regexpText;
		}
		/**
		 * 입력시 문자를 필터한다.
		 */
		set filter(regexp: string) {
			this._regexpText = regexp;
			if (regexp != null && regexp != "") {
				this._filterRegExp = new RegExp(regexp);
			} else {
				this._filterRegExp = null;
			}
		}

		/**
		 * 이벤트에서 저장한 캐시 데이터를 삭제합니다.
		 */
		public invalidate() {
			this._pasteData = null;
			this._pendingPasteEvent = null;
			this._dropData = null;
		}

		public wrap(shape: ufc.ControlShape, inputValue: string): void {
			// shape redefine
			if (shape == null) {
				return;
			}

			if (shape["events"] == undefined || shape["events"] == null) {
				shape["events"] = {};
			}
			if (shape["attr"] == undefined || shape["attr"] == null) {
				shape["attr"] = {};
			}
			this._currentInputValue = inputValue;
			//키보드 이벤트 순서 keydown(입력된 value는 포함되지 않음.)->input(입력된 value가 포함되어 있음.)->(keypress or composition)-> keyup
			ufc.ShapeUtil.addEventHandler(shape, "input", (e) => this._oninput(e), true);
			ufc.ShapeUtil.addEventHandler(shape, "keydown", (e) => this._onkeydown(e), true);
			ufc.ShapeUtil.addEventHandler(shape, "beforeinput", (e) => this._onbeforeinput(e), true);
			ufc.ShapeUtil.addEventHandler(shape, "focus", (e) => this._onfocus(e), true);
			ufc.ShapeUtil.addEventHandler(shape, "blur", (e) => this._onblur(e), true);
			ufc.ShapeUtil.addEventHandler(shape, "paste", (e) => this._onpaste(e), true);
			ufc.ShapeUtil.addEventHandler(shape, "drop", (e) => this._ondrop(e), true);
		}

		private _onblur(e: FocusEvent) {
			this._text = null;
			this._currentInputValue = null;
		}

		private _onfocus(e: FocusEvent) {
			let input = <HTMLInputElement>e.target;
			this._text = { value: input.value, ss: input.selectionStart, se: input.selectionEnd };
			this._currentInputValue = input.value;
		}

		private _replaceNewLine(text: string, replace: string = " "): string {
			let isIE = _detectBrowser().name == "ie";
			if (isIE) {
				let findIndex = text.search(/\r\n|\n/);
				if (findIndex > -1) {
					text = text.substring(0, findIndex);
				}
			} else {
				let hasLastNewLine = /\r|\n/.test(text.charAt(text.length - 1));
				while (hasLastNewLine) {
					text = text.substring(0, text.length - 1);
					hasLastNewLine = /\r|\n/.test(text.charAt(text.length - 1));
				}
				text = text.replace(/\r\n|\n/g, replace);
			}
			return text;
		}

		private _onpaste(e: events.CClipboardEvent) {
			let clipboardData = e.clipboardData || window["clipboardData"];
			let pasteData = this._replaceNewLine(clipboardData.getData("Text") as string);

			let filteredText = this.filterText(pasteData);
			this._pasteData = { filteredText: filteredText, text: pasteData };
			// bubble 단계에서 외부 핸들러가 preventDefault()를 호출했는지 확인하기 위해 이벤트 참조 보존
			this._pendingPasteEvent = e;
		}

		private _ondrop(e: DragEvent) {
			let transferData = e.dataTransfer.getData("text");
			let input = e.currentTarget as HTMLInputElement;

			let isIE = _detectBrowser().name == "ie";
			if (isIE) {
				let findIndex = transferData.search(/\r\n|\n/);
				if (findIndex > -1) {
					transferData = transferData.substring(0, findIndex);
				}
			} else {
				let hasLastNewLine = /\r|\n/.test(transferData.charAt(transferData.length - 1));
				while (hasLastNewLine) {
					transferData = transferData.substring(0, transferData.length - 1);
					hasLastNewLine = /\r|\n/.test(transferData.charAt(transferData.length - 1));
				}
				transferData = transferData.replace(/\r\n|\n/g, " ");
			}

			let filteredText = this.filterText(transferData);

			this._dropData = { beforeValue: input.value, filteredText: filteredText, text: transferData };
			if (!this._text) { // 포커스가 없는 상태에서 드롭을 하면 focus 이벤트 보다 먼저 발생함.(IE)
				this._text = { value: input.value, ss: input.selectionStart, se: input.selectionEnd };
			}
		}
		/**
		 * 모바일에서 클립보드 붙여넣기 시 paste 이벤트가 발생하지 않고,
		 * beforeinput 하고 input 이벤트가 발생하거나 input 이벤트만 발생 합니다.
		 * @param e 
		 * @returns 
		 */
		private _checkClipboardPaste(e: events.CUIEvent) {
			if (!e.inputType) {
				return;
			}
			if (!_detectBrowser().mobile) {
				return;
			}
			let isClipboardPaste = e.inputType == "insertText" && e.data && e.data.length > 1;
			if (!isClipboardPaste) {
				return;
			}
			let input = <HTMLInputElement>e.target;
			if (e.type == "input") {
				let selectionStart = input.selectionStart;
				let oldSelectionStart = selectionStart - e.data.length;
				// input 이벤트에서 셀렉션된 텍스트는 이전 value를 기억하지 않으면 알 수 없어 현재 value를 설정한다.
				this._text = { value: this._currentInputValue ?? this._text?.value, ss: oldSelectionStart, se: oldSelectionStart };
			}
			if (!this._pasteData) {
				let filteredText = this.filterText(e.data);
				if (this._validInputData(filteredText)) {
					this._pasteData = { filteredText: filteredText, text: this._replaceNewLine(e.data) };
				}
			}

		}

		private _isPastePrevented(e: events.CClipboardEvent): boolean {
			return e.defaultPrevented
				|| (e.nativeEvent != null && e.nativeEvent.defaultPrevented);
		}

		/**
		 * IE10/11 issue page가 로드시 인풋에 placeholder, value에 ASCII 문자가 아닌 것(한 글,중 문,일본 어,유니코드)이 있으면 input 이벤트를 발생한다.
		 * https://connect.microsoft.com/IE/feedback/details/776510/oninput-event-fires-on-loading-the-page-when-input-value-is-non-ascii#details
		 * @param e 
		 */
		private _oninput(e: events.CUIEvent): void {
			let input = <HTMLInputElement>e.target;
			let insertInputTypes = ["insertCompositionText", "insertText", "insertFromPaste", "deleteContentBackward", "insertFromDrop"];
			let inputType = e["inputType"];
			// input 이벤트만 발생했을 시 이전 값을 기억하기 위한 방법
			setTimeout(() => {
				this._currentInputValue = input.value;
			})
			if (inputType != null && insertInputTypes.indexOf(inputType) == -1) {
				return;
			}

			// 외부 addEventListener에서 paste 이벤트에 preventDefault()를 호출한 경우 _pasteData 무효화
			// (capture 단계에서 설정된 _pasteData가 차단된 붙여넣기 이후 일반 입력에서 오동작하는 것을 방지)
			if (this._pasteData && this._pendingPasteEvent && this._isPastePrevented(this._pendingPasteEvent)) {
				this._pasteData = null;
			}
			this._pendingPasteEvent = null;

			this._checkClipboardPaste(e);
			if (!this._text) {
				return;
			}
			let value = input.value;
			let isDefaultPrevent = false;
			if (this._pasteData && this._pasteData.filteredText != this._pasteData.text) {
				// 붙여넣기
				let currentSelection = input.selectionStart;
				let startText = value.substring(0, currentSelection - this._pasteData.text.length);
				let endText = value.substring(currentSelection);
				value = startText + this._pasteData.filteredText;
				currentSelection = value.length;
				value += endText;
				input.value = value;
				input.setSelectionRange(currentSelection, currentSelection);
				isDefaultPrevent = this._pasteData.filteredText == "";
			} else if (this._dropData && this._dropData.filteredText != this._dropData.text) {
				// 드래그 앤 드롭
				let findIndex = value.lastIndexOf(this._dropData.text);
				if (findIndex > -1) {
					let ss = findIndex;
					let se = ss + this._dropData.text.length;
					value = utils.StringUtil.replaceRange(value, this._dropData.filteredText, ss, se);
					input.value = value;
					input.setSelectionRange(ss, se);
				}
				isDefaultPrevent = findIndex == -1;
			} else {
				// TODO: 필터가 독립적으로 동작하려면 한글 입력 시 조합 중 삭제되는 동작이 이전 값으로 설정되도록 해야 함. deleteContentBackward에 대한 동작을 TextEditor.oninput() 참고.
				// 일반 입력
				let isValidInputData: boolean = true;
				let startIdx = this._seachDifferentIndex(value, this._text.value);
				let lastIdx = this._searchDifferentLastIndex(value, this._text.value);
				let insertedText = value.substring(startIdx, lastIdx);
				let insertedTexts = insertedText.split("");
				insertedTexts.some((char: string) => {
					isValidInputData = this._isAccepted(char);
					return !isValidInputData;
				})

				if (!isValidInputData) {
					input.value = this._text.value;
					input.setSelectionRange(this._text.ss, this._text.se);
					isDefaultPrevent = true;
				}
			}
			this._pasteData = null;
			this._dropData = null;
			if (isDefaultPrevent) {
				e.preventDefault();
				e.stopPropagation();
			}
		}

		private _searchDifferentLastIndex(baseText: string, compareText: string) {
			let isExist = false;

			let oldIdx = compareText.length - 1;
			let newIdx = baseText.length - 1;
			let result = baseText.length;
			while (!isExist && oldIdx > -1) {
				let oldChar = compareText.charAt(oldIdx);
				let newChar = baseText.charAt(newIdx);
				if (oldChar == newChar) {
					result = newIdx;
				} else {
					isExist = true;
				}
				newIdx--;
				oldIdx--;
			}
			return result;
		}

		private _seachDifferentIndex(baseText: string, compareText: string) {
			let isExist = false;
			let oldIdx = 0;
			let oldLen = compareText.length;
			let newLen = baseText.length;
			let result = 0;
			while (!isExist && oldIdx < oldLen) {
				let oldChar = compareText.charAt(oldIdx);
				let newChar = baseText.charAt(oldIdx);
				if (oldChar != newChar) {
					result = oldIdx;
					isExist = true;
				}
				oldIdx++;
			}
			if (!isExist && oldLen < newLen) {
				result = oldLen;
			}
			return result;
		}

		/**
		 * IE11에서는 지원하지 않음.
		 * 
		 * @param e 
		 */
		private _onbeforeinput(e: events.CUIEvent) {
			let input = <HTMLInputElement>e.target;
			if (e.inputType.indexOf("delete") > -1) {
				return;
			}
			if (!this._text) {
				this._text = { value: input.value, ss: input.selectionStart, se: input.selectionEnd };
			}
			if (!e.cancelable) {
				return;
			}

			let insertInputTypes = ["insertCompositionText", "insertText", "insertFromPaste", "insertFromDrop"];
			if (insertInputTypes.indexOf(e.inputType) == -1) {
				return;
			}

			let filteredText = this.filterText(e.data);
			if (!this._validInputData(filteredText)) {
				this.invalidate();
				e.preventDefault();
			} else {
				this._checkClipboardPaste(e);
			}
		}

		private _validInputData(data: string) {
			if (!data) {
				return false;
			}

			let chars = data.split("");
			let validData: boolean = true;
			chars.some((char: string) => {
				if (!this._isAccepted(char)) {
					validData = false;
					return true;
				}
				return false;
			})
			return validData;
		}

		private _onkeydown(e: events.CKeyboardEvent) {
			let input = <HTMLInputElement>e.target;
			//IE11에서 전각문자입력 alt+= 했을때 keydown에서 값이 포함된 상태로 value가 설정되어 있어 무슨 값이 입력되었는지 알수가 없음.
			let keychar = e.key;
			let keycode = e.keyCode;
			if (keychar == null || keycode == null) {
				return;
			}
			let deleteKeys = ["Backspace", "Delete"];
			if (keycode == events.KeyCode.DELETE || keycode == events.KeyCode.BACKSPACE || deleteKeys.indexOf(keychar) > -1) {
				this._text = null;
				return;
			}

			if (this._text && input.value.length > this._text.value.length) {
				let isValidInputData: boolean = true;

				let value = input.value;
				let startIdx = this._seachDifferentIndex(value, this._text.value);
				let lastIdx = this._searchDifferentLastIndex(value, this._text.value);
				let insertedText = value.substring(startIdx, lastIdx);
				let insertedTexts = insertedText.split("");
				insertedTexts.some((char: string) => {
					isValidInputData = this._isAccepted(char);
					return !isValidInputData;
				})
				if (isValidInputData) {
					this._text = { value: input.value, ss: input.selectionStart, se: input.selectionEnd };
				}

			} else {
				this._text = { value: input.value, ss: input.selectionStart, se: input.selectionEnd };
			}

			if (e._getMod3Key() || e._getMod1Key()) {
				return;
			}

			if (keycode == events.KeyCode.IME_INPUT || keycode == 0 || keychar.length > 1) {
				return;
			}

			if (!this._validInputData(keychar)) {
				e.preventDefault();
			}
		}

		public filterText(text: string): string {
			if (text == null || text == "") {
				return text;
			}
			let newText: string[] = [];
			let textlength: number = text.length;
			for (let idx: number = 0; idx < textlength; idx++) {
				let char: string = text.charAt(idx);
				if (this._isAccepted(char)) {
					newText.push(char);
				}
			}
			return newText.join("");
		}

		private _isAccepted(char: string): boolean {
			if (this._filterRegExp == null) {
				return true;
			}

			return this._filterRegExp.test(char);

		}

	}
}