

namespace cpr.foundation {
	/**
	 * @private
	 */
	export enum ProcType {
		NONE = 0,
		DELETE_BACK = 1,
		DELETE_FRONT = 2,
		DELETE_RANGE = 3,
		INSERT = 4,
		REPLACE = 5
	}

	/**
	 * @private
	 */
	export interface Translation {
		pattern: RegExp, /* regular expression */
		optional?: boolean, /* allowed optional */
		output?: string /* lower case, upper case */
		secret?: boolean,
		placeholderChar?: string
	}

	/**
	 * @private
	 */
	export interface IFormatter {
		/**
		 * 일반 텍스트를 포맷팅합니다.
		 * @param text 
		 */
		transform(text: string): string;
		/**
		 * 포맷된 텍스트를 일반 텍스트롤 변환합니다.
		 * @param formattedText 
		 */
		reverseTransform(formattedText: string): string;
		/**
		 * 타입을 반환합니다.
		 */
		type: string;
	}

	type BindProperty = { value: any, get: () => any, set: (value: string) => void }
	type BindProperties = { [key: string]: BindProperty }

	/**
	 * @private
	 */
	export class BindableFormatter {
		private _bindProperties: BindProperties = {};
		private _propertyChange: { [key: string]: ((oldValue: any, newValue: any) => void)[] };

		protected _dispatchPropertyChange(name: string, oldValue: any, newValue: any) {
			if (oldValue === newValue) {
				return;
			}
			if (!this._hasPropertyChangeName(name)) {
				return;
			}
			this._propertyChange[name].forEach((each) => {
				each(oldValue, newValue)
			});
		}

		private _hasPropertyChangeName(name: string) {
			return this._propertyChange && this._propertyChange[name];
		}

		protected _getBindProperty(name: string): BindProperty {
			return this._bindProperties[name] ?? null;
		}

		public _bindProperty(name: string, getter: () => any, setter: (value: any) => void = () => { }) {
			if (!this._bindProperties[name]) {
				return;
			}
			this._bindProperties[name].get = getter;
			this._bindProperties[name].set = (value: any) => {
				let oldValue = getter();
				setter(value);
				this._dispatchPropertyChange(name, oldValue, getter());
			}
		}

		public _addPropertyChange(name: string, run: (oldValue: any, newValue: any) => void) {
			if (!this._getBindProperty(name)) {
				return;
			}
			if (!this._propertyChange) {
				this._propertyChange = {};
			}
			this._propertyChange[name] = [run];
		}

		public _removePropertyChange(name: string, run: (oldValue: any, newValue: any) => void) {
			if (!this._hasPropertyChangeName(name)) {
				return;
			}
			let index = this._propertyChange[name].indexOf(run);
			if (index > -1) {
				this._propertyChange[name].splice(index, 1);
			}
		}

		protected _addBindPropertyValue(name: string, value: any) {
			if (this._bindProperties[name]) {
				return;
			}
			this._bindProperties[name] = {
				value: value,
				get: () => { return this._bindProperties[name].value },
				set: (value: any) => {
					let oldValue = this._bindProperties[name].get();
					this._bindProperties[name].value = value;
					this._dispatchPropertyChange(name, oldValue, value);
				}
			}
		}

		protected _addBindProperty(name: string, getter: () => any, setter: (value: any) => boolean = () => { return false }) {
			if (this._bindProperties[name]) {
				return;
			}
			this._bindProperties[name] = {
				value: null,
				get: getter,
				set: (value: any) => {
					let oldValue = getter();
					setter(value);
					this._dispatchPropertyChange(name, oldValue, getter());
				}
			}
		}
	}

	/**
	 * @private
	 */
	export abstract class AbstractFormatter extends BindableFormatter implements IFormatter {
		static DEFAULT_PLACEHOLDER_CHAR: string = "_";
		static DEFAULT_ESCAPE_CHAR: string = "\\\\";

		constructor(format: string = "") {
			super();
			this._addBindPropertyValue("format", format);
		}

		public _getFormat() {
			return this._getBindProperty("format").get() ?? "";
		}
		public abstract get type(): string;
		public abstract _getPlaceholder(): string;

		protected abstract _applyFormat(): void;
		protected abstract _needUpdateFormat(): boolean;

		/**
		 * pos 위치에 문자를 추가한 후 Formatting하여 리턴
		 */
		public abstract _insert(text: string, keychars: string, pos: number): string;

		/**
		 * pos 위치에 문자를 교체 후 Formatting하여 리턴
		 */
		public abstract _replace(text: string, keychar: string, pos: number): string;

		/**
		 * pos 위치의 왼쪽 한 문자를 삭제한 후 Formatting하여 리턴한다.
		 */
		public abstract _deleteBack(text: string, pos: number): string;

		/**
		 * pos 위치의 오른쪽 한 문자를 삭제한 후 Formatting하여 리턴한다.
		 */
		public abstract _deleteFront(text: string, pos: number): string;

		/**
		 * Text의 spos와 epos 구간의 문자를 삭제한 후 Formatting하여 리턴한다.
		 */
		public abstract _deleteRange(text: string, spos: number, epos: number): string;

		/**
		 * Caret의 위치를 결정하여 리턴한다.
		 */
		public abstract _decideCaretPosition(oldText: string, newText: string, oldStPos: number, oldEdPos: number, procType: ProcType, keychar: string, strict: boolean): number;

		public abstract _mask(text: string): string;

		public abstract transform(text: string): string;
		public abstract reverseTransform(formattedText: string): string;

	}

}