/// <reference path="./AbstractMenu.ts" />

namespace cpr.controls.menu {
	/**
	 * @private
	 */
	export class SubMenuItemFocusEntry implements ItemFocusEntry {
		private _menu: IAccessibleMenu;
		private _selector: string;
		constructor(menu: IAccessibleMenu, value: string) {
			this._menu = menu;
			this._selector = this._menu._createFocusSelector(value);
		}

		public focus(forward: boolean): void {
			if (this._menu.disposed) {
				return;
			}
			this._menu._focusBySelector(this._selector);
		}

		public get selector() {
			return this._selector;
		}
	}

	/**
	 * @private
	 */
	export abstract class AbstractAccessibleMenu extends AbstractMenu {

		protected _getUIControl(): NavigationBar {
			return super._getUIControl() as NavigationBar
		}

		protected _focusImmediateBySelector(selector: string) {
			if (this.disposed) {
				return;
			}

			let node = this._getRenderer().getNamedNode(this.getRootNodeName());
			if (node) {
				let focusableEle = null;
				focusableEle = node.querySelector(selector) as HTMLElement;

				if (focusableEle) {
					focusableEle.focus();
				}
			}

			this._setTabFocusBySelector(selector);
		}

		protected _setTabFocusBySelector(selector: string) {
			let match = selector.match(/\[data-itemid='(.+)?'\]/i);
			let value = null;
			if (match && match.length == 2) {
				value = match[1] ?? "";
			}
			if (value == null) {
				return;
			}
			let item = this._getDataBinder().getItemByValue(value);
			if (item) {
				// this._setHoveredItem(item, true);
				let menuItemFocusEvent = new events.CItemEvent("menu-item-focus", { item: item });
				this.dispatchEvent("menu-item-focus", menuItemFocusEvent);
			}
		}

		public _focusBySelector(selector: string, immediate: boolean = false) {
			if (immediate) {
				this._focusImmediateBySelector(selector);
			} else {
				core.DeferredUpdateManager.INSTANCE._performFocusTask(() => {
					this._focusImmediateBySelector(selector);
				});
			}
		}

		/**
		 * 현재 활성화된 포커스 엔트리를 반환합니다.
		 * @returns 
		 */
		public _getActiveFocusEntry() {
			let activeElement = document.activeElement as HTMLElement;
			let findFocusEntry = null;
			if (!activeElement) {
				return findFocusEntry;
			}
			let rootElement = this._getRenderer().getRootNode();
			let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(activeElement)._closest("[data-role='menuitem']", rootElement);
			if (domTraverser == null) {
				return findFocusEntry;
			}
			let itemElement = domTraverser._getElement();
			let itemid = itemElement.getAttribute("data-itemid");
			if (itemid == null) {
				return findFocusEntry;
			}
			let selector = this._createFocusSelector(itemid);
			findFocusEntry = _.find(this._getFocusEntries(), (each) => {
				return each.selector == selector;
			});

			return findFocusEntry;
		}

		public _getFocusEntries() {
			let items = this.getItems();
			let hoveredItems = this._getHoveredItems();

			let collectFocusEntry = (children: MenuItem[], depth: number) => {
				children.forEach((each: MenuItem) => {
					if (this._getDataBinder().getItemEnable(each)) {
						focusEntries.push(new SubMenuItemFocusEntry(this, each.value));
					}
					if (hoveredItems[depth] && hoveredItems[depth].value == each.value) {
						collectFocusEntry(each.children as MenuItem[], ++depth);
					}
				})
			}

			let focusEntries: ItemFocusEntry[] = [];
			collectFocusEntry(items, 0);
			return focusEntries;
		}

		public _createFocusSelector(value: string) {
			return `[data-itemid='${value}'] a`
		}

	}
}