/// <reference path="../expression/ExpressionEngine.ts"/>
namespace cpr.foundation {
	Decimal.config({
		precision: 40,
		toExpPos: 30,
		toExpNeg: -10
	});

	/**
	 * 소수 데이터 타입.
	 */
	export class DecimalType {
		private _decimalData: decimal.Decimal;

		/**
		 * number를 이용해 소수 객체를 만듭니다.
		 * @param data 소수를 만들 숫자.
		 */
		constructor(data: number)

		/**
		 * 문자열을 이용하여 소수 객체를 만듭니다.
		 * @param data 소수를 나타내는 문자열.
		 */
		constructor(data: string)

		/**
		 * @param data 
		 * @private
		 */
		constructor(data: decimal.Decimal)
		constructor(data: number | string | decimal.Decimal) {
			this._decimalData = new Decimal(data);
		}

		/**
		 * @private
		 */
		public _getDecimal(): decimal.Decimal {
			return this._decimalData;
		}

		/**
		 * 더하기(+) 연산을 실행합니다.
		 * @param x 더하기 연산을 할 데이터.
		 * @return 연산 결과.
		 */
		public plus(x: number | string | DecimalType): DecimalType {
			let data: (number | string | decimal.Decimal);
			if (x instanceof DecimalType) {
				data = x._getDecimal();
			} else {
				data = x;
			}
			return new DecimalType(this._decimalData.plus(data));
		}

		/**
		 * 빼기(-) 연산을 실행합니다.
		 * @param x 빼기 연산을 할 데이터.
		 * @return 연산 결과.
		 */
		public minus(x: number | string | DecimalType): DecimalType {
			let data: (number | string | decimal.Decimal);
			if (x instanceof DecimalType) {
				data = x._getDecimal();
			} else {
				data = x;
			}
			return new DecimalType(this._decimalData.minus(data));
		}

		/**
		 * 곱하기(x) 연산을 실행합니다.
		 * @param x 곱하기 연산을 할 데이터.
		 * @return 연산 결과.
		 */
		public times(x: number | string | DecimalType): DecimalType {
			let data: (number | string | decimal.Decimal);
			if (x instanceof DecimalType) {
				data = x._getDecimal();
			} else {
				data = x;
			}
			return new DecimalType(this._decimalData.times(data));
		}

		/**
		 * 나누기(÷) 연산을 실행합니다.
		 * @param x 나누기 연산을 할 데이터.
		 * @return 연산 결과.
		 */
		public dividedBy(x: number | string | DecimalType): DecimalType {
			let data: (number | string | decimal.Decimal);
			if (x instanceof DecimalType) {
				data = x._getDecimal();
			} else {
				data = x;
			}
			let result: DecimalType;
			try {
				result = new DecimalType(this._decimalData.dividedBy(data));
			} catch (e) {
				console.error(e);
				result = new DecimalType(0);
			}
			return result;
		}

		/**
		 * 나머지(%) 연산을 실행합니다.
		 * @param x 나머지 연산을 할 데이터.
		 * @return 연산 결과.
		 */
		public remainder(x: number | string | DecimalType): DecimalType {
			let data: (number | string | decimal.Decimal);
			if (x instanceof DecimalType) {
				data = x._getDecimal();
			} else {
				data = x;
			}
			return new DecimalType(this._decimalData.modulo(data));
		}

		/**
		 * 값을 비교합니다.
		 * @param x 비교할 값.
		 * @return 비교 결과. <br>
		 * (1: 현재 값이 더 큽니다. / 0: 현재 값과 param 값이 같습니다 / -1: 현재 값이 더 작습니다. / NaN: 올바르지 않음 param이 입력되었습니다.)
		 */
		public compareTo(x: number | string | DecimalType): number {
			let data: (number | string | decimal.Decimal) = this._getDecimalData(x);
			if (data == null) {
				return NaN;
			}
			return this._decimalData.comparedTo(data);
		}

		/**
		 * 현재 decimal 값과 입력된 값이 같은지 비교합니다.
		 * @param x 비교할 값.
		 * @return 현재 decimal 값과 입력된 값이 같으면 true, 아니면 false.
		 */
		public equals(x: number | string | DecimalType): boolean {
			let data: (number | string | decimal.Decimal) = this._getDecimalData(x);
			if (data == null) {
				return false;
			}
			return this._decimalData.equals(data);
		}

		/**
		 * 
		 * @param x 
		 * @returns 
		 */
		private _getDecimalData(x: number | string | DecimalType): number | string | decimal.Decimal {
			let isDecimal = /^(\d+(\.\d*)?|\.\d+)(e[+-]?\d+)?$/i;
			if (typeof (x) == "string" && isDecimal.test(x) == false) {
				return null;
			}
			let data: (number | string | decimal.Decimal);
			if (x instanceof DecimalType) {
				data = x._getDecimal();
			} else {
				data = x;
			}
			return data;
		}

		/**
		 * 현재 decimal 값을 number형으로 반환합니다.
		 * @return 현재 decimal 값의 number형 데이터.
		 */
		public toNumber(): number {
			if (this._decimalData == null) {
				return null;
			}
			return this._decimalData.toNumber();
		}

		/**
		 * 현재 decimal 값을 string형으로 반환합니다.
		 * @return 현재 decimal 값의 string형 데이터.
		 */
		public toString(): string {
			if (this._decimalData == null) {
				return null;
			}
			//Decimal.config에서 지수표현 크기에 대해 설정할 수 있음.
			let data: string[] = this._decimalData.toString().split(/[eE]/);
			if (data.length == 1) {
				return data[0];
			}

			let num: string = data[0];
			let exponential: number = Number(data[1]);

			//양수일때 정수부에 0 삽입
			if (exponential > 0) {
				return this._decimalData.toFixed(0);
			};

			let part: string[] = num.split(".");
			exponential = Math.abs(exponential) + (part.length == 1 ? 0 : part[1].length); //소수부 갯수

			return this._decimalData.toFixed(exponential);
		}

		valueOf(): number {
			return this.toNumber();
		}

		/**
		 * numberValue를 DecimalType으로 반환합니다.
		 * @param numberValue 
		 * @throws Invalid argument 숫자 형식에 맞지 않는 문자열에 대해 오류 발생
		 */
		public static getDecimalType(numberValue: number): DecimalType;
		/**
		 * stringValue를 DecimalType으로 반환합니다.
		 * @param stringValue 
		 * @throws Invalid argument 숫자 형식에 맞지 않는 문자열에 대해 오류 발생
		 */
		public static getDecimalType(stringValue: string): DecimalType;

		public static getDecimalType(obj: any): DecimalType {
			if (obj instanceof DecimalType) {
				return obj;
			}
			if (typeof obj == "number" || typeof obj == "string") return new DecimalType(obj as any);
			return null;
		}
	}

	cpr.expression.ExpressionEngine.INSTANCE._registerOperator({
		type: DecimalType,
		operator: "+",
		allowedOperandTypes: ["number"],
		reducer(x, y) {
			let operandX: DecimalType = DecimalType.getDecimalType(x);
			let operandY: DecimalType = DecimalType.getDecimalType(y);
			let result = operandX.plus(operandY);
			return result;
		}
	});

	cpr.expression.ExpressionEngine.INSTANCE._registerOperator({
		type: DecimalType,
		operator: "-",
		allowedOperandTypes: ["number"],
		reducer(x, y) {
			let operandX: DecimalType = DecimalType.getDecimalType(x);
			let operandY: DecimalType = DecimalType.getDecimalType(y);
			let result = operandX.minus(operandY);
			return result;
		}
	});

	cpr.expression.ExpressionEngine.INSTANCE._registerOperator({
		type: DecimalType,
		operator: "*",
		allowedOperandTypes: ["number"],
		reducer(x, y) {
			let operandX: DecimalType = DecimalType.getDecimalType(x);
			let operandY: DecimalType = DecimalType.getDecimalType(y);
			let result = operandX.times(operandY);
			return result;
		}
	});

	cpr.expression.ExpressionEngine.INSTANCE._registerOperator({
		type: DecimalType,
		operator: "/",
		allowedOperandTypes: ["number"],
		reducer(x, y) {
			let operandX: DecimalType = DecimalType.getDecimalType(x);
			let operandY: DecimalType = DecimalType.getDecimalType(y);
			let result = operandX.dividedBy(operandY);
			return result;
		}
	});

	cpr.expression.ExpressionEngine.INSTANCE._registerOperator({
		type: DecimalType,
		operator: "==",
		allowedOperandTypes: ["number", "string"],
		reducer(x, y) {
			try {
				let operandX: DecimalType = DecimalType.getDecimalType(x);
				let operandY: DecimalType = DecimalType.getDecimalType(y);
				return (operandX.compareTo(operandY) == 0);
			} catch (e) {
				return false;
			}

		}
	});
}