namespace cpr.controls.item {

	/**
	 * @private
	 */
	export class ItemDataSource<ItemSetConfigType> {

		private _visibleRowState: data.tabledata.RowState = data.tabledata.RowState.UNCHANGED | data.tabledata.RowState.INSERTED | data.tabledata.RowState.UPDATED;

		// 아이템 셋 설정
		private _dataSet: data.DataCollection;
		private _itemSetConfig: ItemSetConfigType;

		// 선행 데이터 
		private _predefinedItems: any[] = [];

		private _onLoadItemSet: (e: events.CDataEvent) => void = null;
		private _owner: UIControl;

		constructor(owner: UIControl) {
			this._owner = owner;
		}

		/**
		 * 선행 아이템 배열을 반환합니다.
		 */
		public get predefinedItems(): any[] {
			return this._predefinedItems;
		}

		/**
		 * 선행 아이템 배열을 설정합니다.
		 * @param items 선행 아이템 배열
		 */
		public set predefinedItems(items: any[]) {
			this._predefinedItems = items;
		}

		/**
		 * 리스트 데이터에 바인딩된 데이터셋을 반환합니다.
		 * @return 데이터셋.
		 */
		get dataSet(): data.DataCollection {
			return this._dataSet;
		}

		/**
		 * 보여지는 행의 상태를 반환합니다.
		 * @returns 행 상태
		 */
		get visibleRowState(): data.tabledata.RowState {
			return this._visibleRowState;
		}

		/**
		 * 아이템 바인딩 설정을 반환합니다.
		 * @returns 아이템 바인딩 설정
		 */
		get itemBindingConfig(): ItemSetConfigType {
			return this._itemSetConfig;
		}

		/**
		 * 삭제된 행을 보일지 여부를 설정합니다.
		 * @param visible 보일지 여부
		 */
		public setVisibleDeletedItem(visible: Boolean) {
			if (visible) {
				this._visibleRowState = data.tabledata.RowState.UNCHANGED | data.tabledata.RowState.INSERTED | data.tabledata.RowState.UPDATED | data.tabledata.RowState.DELETED;
			} else {
				this._visibleRowState = data.tabledata.RowState.UNCHANGED | data.tabledata.RowState.INSERTED | data.tabledata.RowState.UPDATED;
			}
		}

		/**
		 * 삭제된 행을 보일지 여부를 반환합니다.
		 * @returns 보일지 여부
		 */
		public getVisibleDeletedItem(): boolean {
			return this._visibleRowState == (data.tabledata.RowState.UNCHANGED | data.tabledata.RowState.INSERTED | data.tabledata.RowState.UPDATED | data.tabledata.RowState.DELETED);
		}

		/**
		 * 아이템셋이 로드될 때 발생하는 이벤트를 반환합니다.
		 */
		public get onLoadItemSet() {
			return this._onLoadItemSet;
		}
		/**
		 * 아이템셋이 로드될 때 발생하는 이벤트를 설정합니다.
		 */
		public set onLoadItemSet(onLoadItemSet: (e: events.CDataEvent) => void) {
			this._onLoadItemSet = onLoadItemSet;
		}
		/**
		 * 데이터셋에 이벤트 설정하기 위한 속성
		 * @param e 
		 */
		private _onLoadDataSet = (e: events.CDataEvent) => {
			if (this.onLoadItemSet) {
				this.onLoadItemSet(e);
			}
		}

		/**
		 * 리스트 데이터의 dataset을 지정합니다.
		 * @param dataSet 바인딩할 데이터셋.
		 * @param config 연결할 아이템 설정.
		 */
		public setItemSet(dataSet: data.DataCollection, config: ItemSetConfigType) {
			this.setDataSet(dataSet);
			this._itemSetConfig = config;
		}
		/**
		 * 데이터셋을 설정합니다.
		 * @param dataSet 데이터셋
		 */
		public setDataSet(dataSet: data.DataCollection) {
			if (this._dataSet == dataSet) {
				return;
			}
			if (this._dataSet) {
				// 기존 데이터셋의 정리 작업을 수행합니다.
				this._dataSet._deleteAllCtrlAttr(this._owner);
				this._dataSet._removeInternalEventListener(events.DataEventType.LOAD, this._onLoadDataSet);
			}
			// 새로운 데이터셋을 설정합니다.
			this._dataSet = dataSet;
			if (!this._dataSet) {
				return;
			}
			// 변경된 데이터셋에 이벤트를 다시 설정합니다.
			this._dataSet._addInternalEventListener(events.DataEventType.LOAD, this._onLoadDataSet);
		}

		/**
		 * 리소스를 해제합니다.
		 */
		public dispose(): void {
			if (this._dataSet) {
				this._dataSet._deleteAllCtrlAttr(this._owner);
				this._dataSet._removeInternalEventListener(events.DataEventType.LOAD, this._onLoadDataSet);
			}
			this._itemSetConfig = null;
			this._dataSet = null;
			this._owner = null;
			this._predefinedItems = [];
			this._onLoadItemSet = null;
		}
	}
}