/// <reference path="./AbstractDropDownList.ts" />

namespace cpr.controls {
	/**
	 * @private
	 */
	export class DropDownList extends AbstractDropDownList<TreeItem> {

		private _itemExpressionEvaluator: item.ItemExpressionEvaluator;
		private _selectionManager: item.ItemSelectionManager<TreeItem>;

		constructor(uicontrol: ICombobox, ns: string, itemExpressionEvaluator: item.ItemExpressionEvaluator, selectionManager: item.ItemSelectionManager<TreeItem>) {
			super(uicontrol, ns);
			this._itemExpressionEvaluator = itemExpressionEvaluator;
			this._selectionManager = selectionManager;
		}

		_computeItemDisplayLabel(item: TreeItem): ufc.StyledString | string {
			return this._itemExpressionEvaluator.evaluateDisplayLabel(item);
		}
		_getItemEnable(item: TreeItem): boolean {
			return this._itemExpressionEvaluator.evaluateItemEnable(item);
		}

		protected _createListItem(item: TreeItem, index: number): cpr.ufc.ElementShape {

			let displayLabel = this._computeItemDisplayLabel(item);
			let attributes = {
				"data-role": "option",
				role: "option",
				"data-id": item._getUUID(),
				"data-itemidx": String(index),
				"aria-selected": "false",
				id: this._getItemElementId(index)
			};

			let children = [];
			let templateColumns = [];
			let isSelectedItem = this._selectionManager.isSelected(item);
			let isItemEnabled = this._getItemEnable(item);

			if (this.showCheckbox) {
				let checkbox: ufc.ElementShape = {
					tag: "div",
					classNames: ["cl-checkbox"],
					attr: {
						role: "checkbox",
						'aria-checked': isSelectedItem + ""
					},
					style: {}
				}
				children.push(checkbox);
				templateColumns.push("auto");

				cpr.ufc.ShapeUtil._setAriaDisabled(checkbox, isItemEnabled && !this._getUIControl().readOnly);
				if (isSelectedItem) {
					checkbox.classNames.push(ufc.Classes.CHECKED);
				}
				layouts.GridCSSBuilder._forCell()._withColumnStart(children.length)._withRowStart(1)._withVerticalAlign(layouts.GridCellAlign.center)._commit(checkbox.style);
			}

			if (this._isShowIcon()) {
				let icon: cpr.ufc.ElementShape = {
					tag: "div",
					classNames: [ufc.Classes.ICON],
					style: {},
					children: []
				}
				children.push(icon);
				templateColumns.push("auto");
				if (item.icon) {
					icon.style["background-image"] = _quoteAsCSSURL(item.icon);
				}
				layouts.GridCSSBuilder._forCell()._withColumnStart(children.length)._withRowStart(1)._commit(icon.style);
			}
			let textChildren = ufc.StyledString._isNullOrEmpty(displayLabel) ? ["&nbsp;"] : ufc.StyledString._asShape(displayLabel);
			let text: cpr.ufc.ElementShape = {
				tag: "div",
				classNames: [ufc.Classes.TEXT],
				style: {
					wordBreak: "break-all"
				},
				children: textChildren
			};
			children.push(text);
			templateColumns.push("1fr");
			layouts.GridCSSBuilder._forCell()._withColumnStart(children.length)._withRowStart(1)._withVerticalAlign(layouts.GridCellAlign.center)._commit(text.style);

			let shape: cpr.ufc.ElementShape = {
				tag: "div",
				classNames: [],
				styler: this.styler.item,
				key: item._getUUID(),
				// stylerBindContext: item.toExpressionContext(this._getUIControl()),
				bindContext: item.toExpressionContext(this._getUIControl()),
				attr: attributes,
				style: {},
				children: children
			}
			cpr.ufc.ShapeUtil._setTooltipAttr(shape, { owner: this._getUIControl(), title: item.tooltip, id: item.value });
			cpr.ufc.ShapeUtil._setAriaDisabled(shape, isItemEnabled && !this._getUIControl().readOnly);
			layouts.GridCSSBuilder._forLayout()._withTemplateColumns(templateColumns)._withTemplateRows("1fr")._commit(shape.style);

			if (isSelectedItem) {
				// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/9166
				shape.attr['aria-selected'] = "true"; // 센스리더는 role="listbox"에서 aria-selected는 default로 "true"상태로 출력. "선택됨"을 읽으려면 aria-checked 사용해야함.
				shape.classNames.push(ufc.Classes.SELECTED);
			}
			if (index == this.hoveredIndex) {
				shape.classNames.push(ufc.Classes.HOVER);
			}

			if (isItemEnabled == false) {
				shape.classNames.push(ufc.Classes.DISABLED);
			}
			return shape;
		}

		protected _createDummyItem(label: string, value: string) {
			return new cpr.controls.TreeItem(label, value, "");
		}

		public override dispose(): void {
			super.dispose();
			this._itemExpressionEvaluator = null;
			this._selectionManager = null;
		}
	}

	/**
 * 트리 리스트
 * @private
 */
	export class DropDownTreeList extends AbstractDropDownList<TreeItem> {
		private _rootItems: TreeItem[];
		private _requestFilter: boolean = false;
		private _itemIndent = 20;

		private _itemExpressionEvaluator: item.ItemExpressionEvaluator;
		private _selectionManager: item.ItemSelectionManager<TreeItem>;
		private _treeItemListView: item.ITreeItemListView;

		constructor(uicontrol: ICombobox, ns: string, itemExpressionEvaluator: item.ItemExpressionEvaluator, selectionManager: item.ItemSelectionManager<TreeItem>, treeItemListView: item.ITreeItemListView) {
			super(uicontrol, ns);
			this._itemExpressionEvaluator = itemExpressionEvaluator;
			this._selectionManager = selectionManager;
			this._treeItemListView = treeItemListView;
		}
		_computeItemDisplayLabel(item: TreeItem): ufc.StyledString | string {
			return this._itemExpressionEvaluator.evaluateDisplayLabel(item);
		}
		_getItemEnable(item: TreeItem): boolean {
			return this._itemExpressionEvaluator.evaluateItemEnable(item);
		}
		/**
		 * @override
		 */
		public filter(filter: string) {
			if (this._filterLabel != filter) {
				this._requestFilter = true;
			}
			super.filter(filter);

		}

		private _getViewItems() {
			let items = this._items;
			if (this._filterLabel) {
				items = this._filterItems();
			}
			return items;
		}

		private _toAllItemsArray(items: TreeItem[]) {
			let result = [];
			items.forEach((each: TreeItem) => {
				result[result.length] = each;

				if (each._hasChild()) {
					result = result.concat(this._toAllItemsArray(each.children));
				}
			});
			return result;
		}

		private _toExpandedItemArray(items: TreeItem[]) {
			let result = [];
			items.forEach((each: TreeItem) => {
				result[result.length] = each;

				if (each._hasChild() && each.expanded) {
					result = result.concat(this._toExpandedItemArray(each.children));
				}
			});
			return result;
		}

		/**
		 * @override
		 */
		public getItems(): TreeItem[] {
			if (this._cacheItems) {
				return this._cacheItems;
			}
			let items = this._getViewItems();
			this._cacheItems = this._toExpandedItemArray(items);
			return this._cacheItems;
		}

		/**
		 * @override
		 */
		public _createShape(): ufc.ElementShape {
			this._rootItems = this._getViewItems();
			return super._createShape();
		}

		/**
		 * @override
		 */
		protected _filterItems(): TreeItem[] {
			let result = this._treeFilterItems(this._items);
			this._requestFilter = false;
			return result;
		}

		private _treeFilterItems(rootItems: TreeItem[]) {
			if (!this._filterLabel) {
				return rootItems;
			}
			// let dataBinder = this._getDataBinder();

			let matchFunc: (item: TreeItem) => boolean = (item: TreeItem) => {
				let label: string = ufc.StyledString._asString(this._itemExpressionEvaluator.evaluateDisplayLabel(item)).toLowerCase();
				if (label.indexOf(this._filterLabel.toLowerCase()) > -1) {
					return true;
				}
				return false;
			}

			let treeFilteredItems = this._filterTreeItemExpr(null, rootItems, matchFunc);
			return treeFilteredItems;
		}

		private _filterTreeItemExpr(parent: TreeItem, items: TreeItem[], matchFunction: (item: TreeItem) => boolean): TreeItem[] {
			let result = [];
			items.forEach((each: TreeItem) => {
				let cloneItem = this._copyItem(each);
				if (each._hasChild()) {
					let children = this._filterTreeItemExpr(cloneItem, each.children, matchFunction);
					cloneItem._setChildren(children);
				}
				let hasChild = cloneItem._hasChild();
				if (this._requestFilter && hasChild) {
					cloneItem._setOpen(true);
				}
				let matchRs = matchFunction(each);
				if (matchRs || hasChild) {
					cloneItem._setParent(parent);
					result[result.length] = cloneItem;
				}
			});
			return result;
		}

		private _copyItem(item: TreeItem): TreeItem {
			return new controls.TreeItem(item._getDataAccessor());
		}

		private _isLastNode(item: TreeItem) {
			let children: TreeItem[];
			if (item.parentItem) {
				children = item.parentItem.children;
			} else {
				children = this._rootItems;
			}
			let lastItem = children[children.length - 1];
			if (!lastItem) { //rootItems가 없을때 오류 방지
				return false;
			}
			//필터된 아이템의 경우 객체 비교가 안되기 때문에 속성정보로 비교해야 한다.
			return lastItem._equalsUUID(item);
		}

		/**
		 * 
		 * @param item 
		 */
		private _isFirstNode(item: TreeItem) {
			let children: TreeItem[];
			if (item.parentItem) {
				children = item.parentItem.children;
			} else {
				children = this._rootItems;
			}
			let firstItem = children[0];
			if (!firstItem) {//rootItems가 없을때 오류 방지
				return false;
			}

			return firstItem._equalsUUID(item);
		}

		private _isExpanded(item: TreeItem): boolean {
			let open = this._treeItemListView.isExpanded(item);
			return open == null ? false : open;
		}

		private _setExpandedItem(item: TreeItem, expanded: boolean) {
			item._setOpen(expanded);
			this._invalidate();
			this._getUIControl().redraw();
		}

		protected _getComputedItemWidth(items: TreeItem[]): number {
			items = this._toAllItemsArray(items);
			return super._getComputedItemWidth(items);
		}

		protected _computeItemTextWidth(item: TreeItem, font: string) {
			let width = super._computeItemTextWidth(item, font);
			return width + (item.depth * this._itemIndent);
		}

		/**
		 * 
		 * @param label 
		 * @param value 
		 * @override
		 */
		protected _createDummyItem(label: string, value: string): TreeItem {
			return new cpr.controls.TreeItem(label, value, "");
		}

		private _createSelectionCheckbox(isSelected: boolean, isItemEnabled: boolean): cpr.ufc.ElementShape {

			let checkbox: ufc.ElementShape = {
				tag: "div",
				classNames: ["cl-checkbox"],
				attr: {
					role: "checkbox",
					"aria-checked": isSelected + ""
				},
				style: {},
				children: ["&nbsp;"]
			}
			cpr.ufc.ShapeUtil._setAriaDisabled(checkbox, isItemEnabled && !this._getUIControl().readOnly);

			if (isSelected) {
				checkbox.classNames.push(ufc.Classes.CHECKED);
			}
			return checkbox;
		}

		private _createExpandIcon(item: TreeItem): cpr.ufc.ElementShape {
			let style = {};

			if (item._hasChild()) {
				style['margin'] = "0px"; // Edge 44.18362.449.0 에서 필터 했다가 풀었을시 아이콘이 남아보이는 현상(돔을 갱신하는 행위를 하면 사라짐.)
			}
			return {
				tag: "div",
				attr: {
					"aria-hidden": "true"
				},
				classNames: ["cl-treeicon"],
				style: style,
				children: ["&nbsp;"]
			}
		}

		private _createLabelIcon(item: TreeItem): ufc.ElementShape {
			let icon: cpr.ufc.ElementShape = {
				tag: "div",
				classNames: [ufc.Classes.ICON],
				attr: {},
				style: {},
				children: ["&nbsp;"]
			}
			if (item.icon) {
				icon.style['background-image'] = _quoteAsCSSURL(item.icon);
				return icon;
			}

			return icon;
		}

		private _createLabelText(displayLabel: ufc.StyledString | string): ufc.ElementShape {

			//disabled 와 overflow:hidden 이 같이 있으면 IE에서 마우스 휠이 동작하지 않음.
			let label: ufc.ElementShape = {
				tag: "div",
				classNames: [ufc.Classes.TEXT],
				attr: {},
				style: {},
				children: ufc.StyledString._isNullOrEmpty(displayLabel) ? ["&nbsp;"] : ufc.StyledString._asShape(displayLabel)
			};
			return label;
		}

		private _createTreeLine(className: string): cpr.ufc.ElementShape {
			return {
				tag: "div",
				attr: {
					"aria-hidden": "true"
				},
				classNames: [className],
				style: {},
				children: ["&nbsp;"]
			}
		}

		private _findItemIndex(items: TreeItem[], item: TreeItem) {
			return _.findIndex(items, (each) => {
				return item.value == each.value && item.label == each.label && item.parentValue == each.parentValue;
			})
		}

		/**
		 * 
		 * @param item 
		 * @param index
		 * @override 
		 */
		protected _createListItem(item: TreeItem, index: number): ufc.ElementShape {
			let shapeChildren = [];
			let templeteColumns = [];
			let displayLabel = this._computeItemDisplayLabel(item);
			let isExpanded = this._isExpanded(item);
			let depth = item.depth;
			let isItemEnabled = this._getItemEnable(item);
			let isSelected = this._selectionManager.isSelected(item);
			let classNames = ["cl-treeitem"];
			let style = { overflow: "hidden" };
			let itemChildren = item.parentItem ? item.parentItem.children : [];
			let setsize = itemChildren.length;
			let grpidx = itemChildren.indexOf(item);

			// 아이템 shape
			let attrs = {
				"data-role": "option",
				role: "option",
				"data-id": item._getUUID(),
				"data-itemidx": index > -1 ? index + "" : "",
				"aria-level": (depth + 1) + "",
				"aria-setsize": setsize + "",
				"aria-posinset": (grpidx + 1) + "",
				"aria-selected": "false",
				id: this._getItemElementId(index)
			};

			let columnStart = 1;

			let isLast = this._isLastNode(item);
			if (isLast) {
				classNames.push(ufc.Classes.LAST);
			}

			if (item._isRootItem() && this._isFirstNode(item)) {
				classNames.push(ufc.Classes.FIRST);
			}
			classNames.push(`cl-level-${item.depth + 1}`);
			let setTreeLine = () => {
				let parent = item.parentItem;
				let rootItems = this._rootItems;

				let treeLines = [];
				let children = [];

				while (parent != null) {

					if (parent.parentItem) {
						children = parent.parentItem.children;
					} else {
						children = rootItems;
					}
					let index = this._findItemIndex(children, parent);
					if (children.length - 1 == index) {
						treeLines.push(this._createTreeLine("cl-empty"));
					} else {
						treeLines.push(this._createTreeLine("cl-line"));
					}
					parent = parent.parentItem;
				}

				treeLines.reverse().forEach((each: ufc.ElementShape) => {
					shapeChildren.push(each);
					layouts.GridCSSBuilder._forCell()._withColumnStart(columnStart++)._withRowStart(1)._commit(each.style);
					templeteColumns.push("auto");
				});

				let treeLine = this._createTreeLine("cl-treeicon-line");
				shapeChildren.push(treeLine);
				layouts.GridCSSBuilder._forCell()._withColumnStart(columnStart)._withRowStart(1)._commit(treeLine.style);
				// 확장 아이콘
				let expandIcon = this._createExpandIcon(item);
				shapeChildren.push(expandIcon);
				layouts.GridCSSBuilder._forCell()._withColumnStart(columnStart++)._withRowStart(1)._commit(expandIcon.style);
				templeteColumns.push("auto");
			}

			setTreeLine();

			//셀렉션 체크박스
			if (this.showCheckbox) {
				let selectionCheckbox = this._createSelectionCheckbox(isSelected, isItemEnabled);
				//체크박스 설정
				shapeChildren.push(selectionCheckbox);
				layouts.GridCSSBuilder._forCell()._withColumnStart(columnStart++)._withRowStart(1)._withVerticalAlign(layouts.GridCellAlign.center)._commit(selectionCheckbox.style);
				templeteColumns.push("auto");
			}

			// 텍스트 아이콘
			if (this._isShowIcon()) {
				let textIcon = this._createLabelIcon(item);
				shapeChildren.push(textIcon);
				layouts.GridCSSBuilder._forCell()._withColumnStart(columnStart++)._withRowStart(1)._withVerticalAlign(layouts.GridCellAlign.center)._commit(textIcon.style);
				templeteColumns.push("auto");
			}

			//텍스트
			let labelText = this._createLabelText(displayLabel);
			shapeChildren.push(labelText);
			layouts.GridCSSBuilder._forCell()._withColumnStart(columnStart++)._withRowStart(1)._withVerticalAlign(layouts.GridCellAlign.center)._commit(labelText.style);
			if (this._isFixedListWidth()) {
				templeteColumns.push("minmax(10px, 1fr)");
			} else {
				templeteColumns.push("minmax(min-content, 1fr)");
			}

			if (item._hasChild()) {
				if (isExpanded) {
					classNames.push(ufc.Classes.EXPANDED);
				} else {
					classNames.push(ufc.Classes.COLLAPSED);
				}
				attrs['aria-expanded'] = isExpanded + "";
				classNames.push(ufc.Classes.FOLDER);
			} else {
				classNames.push(ufc.Classes.LEAF);
			}

			//아이템 선택 표시
			if (isSelected) {
				// preventInput=false 인 경우 리스트에서 상하 방향키로 아이템의 label과 입력 상자의 텍스트를 읽는 문제 발생.
				attrs["aria-selected"] = "true";
				classNames.push(ufc.Classes.SELECTED);
			}

			let shape: ufc.ElementShape = {
				tag: "div",
				styler: "item",
				key: item._getUUID(),
				bindContext: item.toExpressionContext(this._getUIControl()),
				classNames: classNames,
				attr: attrs,
				style: style,
				children: shapeChildren
			};
			cpr.ufc.ShapeUtil._setTooltipAttr(shape, { owner: this._getUIControl(), title: item.tooltip, id: item.value });
			cpr.ufc.ShapeUtil._setAriaDisabled(shape, isItemEnabled && !this._getUIControl().readOnly);
			if (isItemEnabled == false) {
				shape.classNames.push(ufc.Classes.DISABLED);
			}
			if (index == this.hoveredIndex) {
				shape.classNames.push(ufc.Classes.HOVER);
			}
			layouts.GridCSSBuilder._forLayout()._withTemplateColumns(templeteColumns)._withTemplateRows("1fr")._commit(shape.style);

			return shape;
		}

		/**
		 * 
		 * @param keyCode 
		 * @param index 
		 * @param e 
		 * @override
		 */
		public keyNavigation(keyCode: number, index: number, e: KeyboardEvent) {
			super.keyNavigation(keyCode, index, e);

			if ((keyCode == events.KeyCode.LEFT || keyCode == events.KeyCode.RIGHT) == false) {
				return;
			}
			let input = e.target as HTMLInputElement;
			if (input.tagName.toLowerCase() == "input") { // preventInput일때 value를 가져오지 못하는 문제 
				let inputValue = input.value; // multiple일때 셀렉션에 따라 아이템 접기, 펼치기 동작 방지
				let delimiterLastIndex = inputValue.lastIndexOf(this._getUIControl().delimiter);
				if (keyCode == events.KeyCode.LEFT && input.selectionEnd <= delimiterLastIndex ||
					keyCode == events.KeyCode.RIGHT && input.selectionEnd < delimiterLastIndex + 1) {
					return;
				}
			}

			let item = this.getItems()[this.hoveredIndex];
			if (!item) {
				return;
			}
			if (this._getItemEnable(item) == false) {
				return;
			}
			switch (keyCode) {
				case events.KeyCode.LEFT:

					if (item._hasChild() && item.expanded) {
						this._setExpandedItem(item, false);
						e.preventDefault();
						e.stopPropagation();
					}
					break;
				case events.KeyCode.RIGHT:

					if (item._hasChild() && item.expanded == false) {
						this._setExpandedItem(item, true);

						e.preventDefault();
						e.stopPropagation();
					}
					break;

			}

		}//keyNavigation

		protected _onItemClick(e: { itemIdx: number, relativeTargetName: string, item: TreeItem, nativeEvent: MouseEvent, defaultPrevented: boolean }): void {

			if (e.relativeTargetName == "treeicon") {

				if (e.item._hasChild()) {

					if (e.item.expanded) {
						this._setExpandedItem(e.item, false);
					} else {
						this._setExpandedItem(e.item, true);
					}
					this._getUIControl().redraw();
					e.defaultPrevented = true;
				}
			}

			super._onItemClick(e);
		}

		public override dispose(): void {
			super.dispose();
			this._treeItemListView = null;
			this._itemExpressionEvaluator = null;
			this._selectionManager = null;
		}
	}
}