/// <reference path="../interfaces/IItemListView.ts"/>
/// <reference path="./AbstractItemListView.ts"/>

namespace cpr.controls.item {

	/**
	 * @private
	 */
	export class ItemListView<ItemType extends Item, ItemListType extends ItemList<ItemType, ItemSetConfig>, ItemFilterType extends ItemFilter> extends AbstractItemListView<ItemListType, ItemFilterType> implements IItemListView<ItemType> {

		private _itemValidatorType: ControlItemValidatorType;

		constructor(owner: UIControl, itemList: ItemListType, itemFilter: ItemFilterType) {
			super(owner, itemList, itemFilter);
			this._itemValidatorType = ControlItemValidatorType.item;
		}

		public setValidatorType(validatorType: ControlItemValidatorType): void {
			this._itemValidatorType = validatorType;
		}

		protected _getValidator(): IControlItemValidator<ItemType> {
			switch (this._itemValidatorType) {
				case ControlItemValidatorType.item:
					return new ControlItemValidator<ItemType>();
				case ControlItemValidatorType.treeItem:
					return new ControlTreeItemValidator() as unknown as IControlItemValidator<ItemType>;
				case ControlItemValidatorType.comboBoxItem:
					return new ComboBoxItemValidator() as unknown as IControlItemValidator<ItemType>;
				default:
					return new ControlItemValidator<ItemType>();
			}
		}

		/**
		 * 필터가 있는지 유무를 확인합니다.
		 */
		public hasFilter(): boolean {
			return this.filterExpression != null;
		}

		/**
		 * 필터 익스프레션 객체를 반환합니다.
		 * @return 필터 익스프레션 객체
		 */
		public get filterExpression(): cpr.expression.Expression {
			return this.itemFilter.filterExpression;
		}

		/**
		 * 필터 익스프레션 객체를 설정합니다.
		 * @param filterExpression 
		 */
		protected _setFilterExpression(filterExpression: cpr.expression.Expression): void {
			this.itemFilter.filterExpression = filterExpression;
			this.owner.redraw();
		}

		/**
		 * 필터 익스프레션 값을 반환합니다.
		 * @return 필터 익스프레션 값
		 */
		public get filter(): expression_string {
			if (this.filterExpression) {
				return this.filterExpression.src;
			}
			return null;
		}

		/**
		 * 리스트 데이터에 필터를 적용합니다.
		 * @param filterExpression 필터 조건 expression.
		 */
		public set filter(filterExpression: expression_string) {
			if (filterExpression) {
				this._setFilterExpression(new expression.Expression(filterExpression));
			} else {
				this._setFilterExpression(null);
			}
		}
		/**
		 * 적용된 필터를 제거합니다.
		 */
		public clearFilter(): void {
			if (this.filterExpression != null) {
				this._setFilterExpression(null);
			}
		}

		/**
		 * 필터속성을 반영한 아이템 목록을 반환합니다.
		 * 그리드에서 필터 속성이 행마다 달라 안전하게 행에서 캐시를 저장해야 합니다.
		 * @returns 
		 */
		@useCacheRealm("redraw-grid-row")
		public getVisibleItemsForRendering(): ItemType[] {
			let visibleItems = this.getVisibleItems();
			let multiple = this.owner["multiple"] ?? false;
			let delimiter = this.owner["delimiter"] ?? ",";
			this._getValidator().validateItems(visibleItems, { ownerId: this.owner.id, ownerType: this.owner.type, multiple: multiple, delimiter: delimiter });
			return visibleItems;
		}

		/**
		 * 필터속성을 반영한 아이템 목록을 반환합니다.
		 * @returns 
		 */
		public getVisibleItems(): ItemType[] {
			let items = this.itemList.getItems() as ItemType[];
			if (this.hasFilter()) {
				let bindCtx: bind.BindContext = this.owner.getBindContext();
				let appInstance = this.owner.getAppInstance();
				let filterFunc: (item: ItemType, key: number, context: ItemType[]) => boolean = this.filterExpression.asFilter();
				items = items.filter((item: ItemType, key: number, context: ItemType[]) => {
					item._ownerBindContext = bindCtx;
					item._expressionIDLookupProvider = appInstance;
					let filterRs: boolean = filterFunc(item, key, context);
					item._expressionIDLookupProvider = null;
					item._ownerBindContext = null;
					return filterRs;
				});
			}
			return items;
		}

		/**
		 * 리스트 데이터의 index를 반환합니다.
		 * 존재하지 않는 데이터의 경우 -1을 반환합니다.
		 * @param item 리스트 데이터의 정보.
		 * @return 해당하는 리스트 데이터의 Index
		 */
		public getIndex(item: ItemType): number {
			if (item == null) {
				return -1;
			}
			let items: ItemType[] = this.getVisibleItems();
			for (let idx: number = 0; idx < items.length; idx++) {
				if (items[idx]._equalsUUID(item)) {
					return idx;
				}
			}
			return -1;
		}

		/**
		 * 조건에 맞는 첫 번째 아이템을 찾습니다.
		 * @param findFunc 검색 조건 함수
		 * @returns 찾은 아이템 또는 null
		 */
		public findOne(findFunc: (it: ItemType, idx?: number) => boolean): ItemType {
			let result: ItemType = null;
			if (this.hasFilter()) {
				this.getVisibleItems().some((each: ItemType, index: number) => {
					if (findFunc(each, index) == true) {
						result = each;
						return true;
					}
					return false;
				});
				return result;
			}

			return this.itemList.findOne(findFunc) as ItemType;
		}

		/**
		 * Index에 해당되는 데이터를 반환합니다.
		 * @param idx 데이터의 index.
		 * @return 해당하는 아이템.
		 */
		public get(idx: number): ItemType {
			if (idx < 0) {
				return null;
			}

			let item = this.findOne((item: ItemType, index: number) => {
				return idx == index;
			});
			return item;
		}

		/**
		 * 해당 리스트 데이터를 가지고 있는지에 대한 여부를 반환합니다.
		 * @param item 확인할 리스트 데이터.
		 * @return 리스트 데이터를 가지고 있는지에 대한 여부.
		 */
		public has(item: ItemType): boolean {
			let result = this.findOne((it: ItemType) => {
				return it._equalsUUID(item);
			});
			return result != null;
		}

		/**
		 * label에 해당되는 리스트 데이터를 반환합니다.
		 * @param label 리스트 데이터의 label.
		 * @return 해당하는 리스트 데이터.
		 */
		public getByLabel(label: String): ItemType {
			return this.findOne((it: ItemType) => {
				return it.label == label;
			});
		}

		/**
		 * value에 해당하는 리스트 데이터를 반환합니다.
		 * @param value 가져오고자 하는 리스트 데이터의 value.
		 * @param useFilter 필터 적용 여부
		 * @return 해당하는 리스트 데이터.
		 */
		public getByValue(value: string): ItemType {
			let result = this.findOne((it: ItemType) => {
				return it.value == value;
			});
			return result;
		}

		/**
		 * UUID에 해당하는 리스트 데이터를 반환합니다.
		 * @param uuid 가져오고자 하는 리스트 데이터의 UUID.
		 * @returns 해당하는 리스트 데이터.
		 */
		public getByUUID(uuid: string): ItemType {
			let result = this.findOne((it: ItemType) => {
				return it._getUUID() == uuid;
			});
			return result;
		}

		/**
		 * 조건에 맞는 리스트 데이터 목록을 가져옵니다.
		 * <pre><code>
		 * dataProvider.find({label:"서울"});<br>
		 * </code></pre>
		 * @param condition 데이터를 찾을 조건.
		 * @return 조건에 맞는 리스트 데이터 목록.
		 * 
		 */
		public find(findFunc: (it: ItemType, idx?: number) => boolean): ItemType[] {
			return this.getVisibleItems().filter((each: ItemType, index: number) => {
				return findFunc(each, index) == true;
			});
		}

		/**
		 * value에 해당하는 리스트 데이터 배열을 반환합니다.
		 * @param value 가져오고자 하는 리스트 데이터의 value.
		 * @return 해당하는 리스트 데이터 배열.
		 * @deprecated value중복을 허용하지 않기 때문에 폐기됨.
		 */
		public getItemsByValue(value: string): ItemType[] {
			console.warn("Deprecation warning: use getItemByValue(value) to get item.");
			let result: ItemType[] = this.find((it: ItemType) => {
				return it.value == value;
			});
			return result;
		}

		/**
		 * 조건에 맞는 리스트 데이터를 가져옵니다.<br>
		 * 데이터가 2개 이상이라면 첫번째 데이터를 가져옵니다.
		 * <pre><code>
		 * dataProvider.findItem({value:"001"});<br>
		 * dataProvider.findItem({label:"서울"});<br>
		 * dataProvider.findItem({value:"001",label:"서울"});
		 * </code></pre>
		 * @param condition 데이터를 찾을 조건.
		 * @return 조건에 맞는 리스트 데이터.
		 */
		public findItem(condition: { [key: string]: any }): ItemType {
			return this.findOne((it: ItemType) => {
				return it._match(condition);
			});

		}

		/**
		 * 조건에 맞는 리스트 데이터 목록을 가져옵니다.
		 * <pre><code>
		 * dataProvider.findItems({label:"서울"});<br>
		 * </code></pre>
		 * @param condition 데이터를 찾을 조건.
		 * @return 조건에 맞는 리스트 데이터 목록.
		 * 
		 */
		public findItems(condition: { [key: string]: any }): ItemType[] {
			let result = this.find((it: ItemType) => {
				return it._match(condition);
			});
			return result;
		}

		/**
		 * 리스트 데이터의 개수를 반환합니다.
		 * @return 데이터의 개수.
		 */
		public size(): number {
			if (this.hasFilter()) {
				return this.getVisibleItems().length;
			}
			return this.itemList.size();
		}

		/**
		 * value 배열에 해당하는 아이템들을 찾습니다.
		 * @param values 찾을 value 배열
		 * @returns 찾은 아이템 배열
		 */
		public findItemByValues(values: string[]): ItemType[] {
			values = values.slice(0); // 복사
			let findItemMap = _createMap<string, ItemType>();

			let items = this.itemList.getCacheItems();
			let process: (item: ItemType) => void;
			if (this.hasFilter()) {
				let bindCtx: bind.BindContext = this.owner.getBindContext();
				let appInstance: core.AppInstance = this.owner.getAppInstance();
				let filterFunc: (item: ItemType) => boolean = this.filterExpression.asFilter();
				process = (item: ItemType) => {
					item._ownerBindContext = bindCtx;
					item._expressionIDLookupProvider = appInstance;
					let itemValue: string = item.value; // value호출은 성능에 영향을 미친다.
					let selectedValueIndex = values.indexOf(itemValue);
					if (selectedValueIndex > -1) {
						if (filterFunc(item)) {// 필터링된 아이템인 경우
							findItemMap.set(itemValue, item);
							values.splice(selectedValueIndex, 1); // 선택된 값은 제거한다.
						} else if (findItemMap.has(itemValue) == false) { // 필터링되지 않은 아이템인 경우
							// 선택된 값이지만 필터링되지 않은 아이템인 경우 표시하기 위해 선택된 아이템으로 추가한다.
							findItemMap.set(itemValue, item);
						};
					}
					item._expressionIDLookupProvider = null;
					item._ownerBindContext = null;
				}
			} else {
				process = (item: ItemType) => {
					let itemValue: string = item.value; // value호출은 성능에 영향을 미친다.
					let selectedValueIndex = values.indexOf(itemValue);
					if (selectedValueIndex > -1) {
						findItemMap.set(itemValue, item);
						values.splice(selectedValueIndex, 1); // 선택된 값은 제거한다.
					};
				}
			}

			items.some((each: ItemType) => {
				process(each);
				return values.length == 0; // 선택된 값이 없으면 중단
			});
			return CMap._valueStream(findItemMap).collect();
		}

	}
}