
namespace cpr.controls.gridpart.layout {

	/**
	 * @private
	 */
	export class ScrollPaneCluster {
		private _scrollPanes: {
			[key: string]: IScrollPane
		};
		private _scrollLeft: {
			[region: string]: number
		};
		private _scrollTop: {
			[location: string]: number
		};

		private _locs: string[] = [
			GRIDREGION.HEADER,
			GRIDREGION.TOP,
			GRIDREGION.MIDDLE,
			GRIDREGION.BOTTOM,
			GRIDREGION.FOOTER
		];

		private _regions: string[] = [
			GRIDREGION.LEFT,
			GRIDREGION.CENTER,
			GRIDREGION.RIGHT
		];


		constructor() {
			this._scrollPanes = {};
			this._scrollLeft = {};
			this._scrollTop = {};
		}

		public _init(): void { // ScrollPosition을 초기화 합니다.
			this._initScrollTop(0);
			this._initScrollLeft(0);
		}

		public _initScrollTop(scrollTop: number): void {
			_.keys(this._scrollTop).forEach((loc: string) => {
				this._scrollTop[loc] = scrollTop;
			});
		}
		public _initScrollLeft(scrollLeft: number): void {
			_.keys(this._scrollLeft).forEach((region: string) => {
				this._scrollLeft[region] = scrollLeft;
			});
		}
		public _initRegionScrollLeft(region: string, scrollLeft: number): void {
			this._scrollLeft[region] = scrollLeft;

			let scrollEvent: events.CScrollEvent = new events.CScrollEvent(events.ScrollEventType.SCROLL, {
				axis: events.ScrollAxis.x, scrollLeft: 0
			});
			this._propagateScrollLeft(region, scrollEvent);
		}

		public _getScrollTop(loc: string): number {
			return this._scrollTop[loc];
		}

		public _getScrollLeft(region: string): number {
			return this._scrollLeft[region];
		}
		public _getAllScrollLeft(): { [region: string]: number } {
			return _shallowCopyObject(this._scrollLeft);
		}

		public _clusterize(scrollPane: IScrollPane): void {
			let region: string = scrollPane.region;
			let loc: string = scrollPane.location;
			let key: string = this._getScrollPaneKey(region, loc);
			this._scrollPanes[key] = scrollPane;

			this._scrollLeft[region] = 0; // 초기값
			this._scrollTop[loc] = 0; // 초기값
		}

		public _diclusterize(scrollPane: IScrollPane): void {
			let region: string = scrollPane.region;
			let loc: string = scrollPane.location;
			let key: string = this._getScrollPaneKey(region, loc);
			if (this._scrollPanes[key] === scrollPane) {
				delete this._scrollPanes[key];
			}
		}

		public _postScroll(scrollPane: IScrollPane, scrollTop: number, scrollLeft: number, e: events.CEvent): events.ScrollAxis {
			let region: string = scrollPane.region;
			let loc: string = scrollPane.location;

			let scrollAxis: events.ScrollAxis = null;
			if (this._scrollLeft[region] === scrollLeft) {
				if (this._scrollTop[loc] === scrollTop) {
					return null;
				} else {
					scrollAxis = events.ScrollAxis.y;
				}
			} else if (this._scrollTop[loc] === scrollTop) {
				scrollAxis = events.ScrollAxis.x;
			} else {
				scrollAxis = events.ScrollAxis.both;
			}

			this._scrollLeft[region] = scrollLeft;
			this._scrollTop[loc] = scrollTop;

			let scrollEvent: events.CScrollEvent = new events.CScrollEvent(events.ScrollEventType.SCROLL, {
				axis: scrollAxis, scrollTop: scrollTop, scrollLeft: scrollLeft
			});
			scrollEvent.nativeEvent = e;

			this._propagateScrollLeft(region, scrollEvent);
			this._propagateScrollTop(loc, scrollEvent);

			core.NotificationCenter.INSTANCE.post(core.SystemTopics.SCROLL, scrollEvent, scrollPane);

			return scrollAxis;
		}

		public _postScrollLeft(scrollPane: IScrollPane, scrollLeft: number, e: events.CEvent): events.ScrollAxis {
			let region: string = scrollPane.region;

			if (this._scrollLeft[region] === scrollLeft) {
				return null;
			}
			this._scrollLeft[region] = scrollLeft;

			let scrollEvent: events.CScrollEvent = new events.CScrollEvent(events.ScrollEventType.SCROLL, {
				axis: events.ScrollAxis.x, scrollLeft: scrollLeft
			});
			scrollEvent.nativeEvent = e;

			this._propagateScrollLeft(region, scrollEvent);

			core.NotificationCenter.INSTANCE.post(core.SystemTopics.SCROLL, scrollEvent, scrollPane);

			return events.ScrollAxis.x;
		}
		private _propagateScrollLeft(region: string, scrollEvent: events.CScrollEvent): void {
			this._locs.forEach((locItem: string) => {
				let key: string = this._getScrollPaneKey(region, locItem);
				let scrollPane: IScrollPane = this._scrollPanes[key];
				if (scrollPane) {
					scrollPane._handleScrollLeft(scrollEvent);
				}
			});
		}

		public _postScrollTop(scrollPane: IScrollPane, scrollTop: number, e: events.CEvent): events.ScrollAxis {
			let loc: string = scrollPane.location;

			if (this._scrollTop[loc] === scrollTop) {
				return null;
			}
			this._scrollTop[loc] = scrollTop;

			let scrollEvent: events.CScrollEvent = new events.CScrollEvent(events.ScrollEventType.SCROLL, {
				axis: events.ScrollAxis.y, scrollTop: scrollTop
			});
			scrollEvent.nativeEvent = e;

			this._propagateScrollTop(loc, scrollEvent);

			core.NotificationCenter.INSTANCE.post(core.SystemTopics.SCROLL, scrollEvent, scrollPane);

			return events.ScrollAxis.y;
		}
		private _propagateScrollTop(loc: string, scrollEvent: events.CScrollEvent): void {
			this._regions.forEach((regionItem: string) => {
				let key: string = this._getScrollPaneKey(regionItem, loc);
				let scrollPane: IScrollPane = this._scrollPanes[key];
				if (scrollPane) {
					scrollPane._handleScrollTop(scrollEvent);
				}
			});
		}

		private _getScrollPaneKey(region: string, loc: string): string {
			return region + "-" + loc;
		}


	}

}