namespace cpr.controls.item {
	/**
	 * 아이템 배열로부터 key에 해당하는 값으로 맵을 생성합니다.
	 * 탐색 최적화를 위해 사용됩니다.
	 * key 기본값은 item의 UUID입니다.
	 * @param items 
	 * @param key 
	 * @returns 
	 */
	export function _createItemMap<ItemType extends Item>(items: ItemType[], key?: (item: ItemType) => string): CMap<string, ItemType> {
		let map = _createMap<string, ItemType>();
		if (!key) {
			key = (item: ItemType) => {
				return item._getUUID();
			};
		}
		items.forEach((each: ItemType) => {
			if (each == null) {
				return;
			}
			if (!map.has(key(each))) {
				map.set(key(each), each);
			}
		});
		return map;
	}

	/**
	 * sourceItems 배열에서 itemsToRemove 배열에 포함된 아이템들을 제거한 새로운 배열을 반환합니다.
	 * @param sourceItems 원본 아이템 배열
	 * @param itemsToRemove 제거할 아이템 배열
	 * @returns itemsToRemove에 포함되지 않은 아이템들로 구성된 새로운 배열
	 */
	export function _subtractItems<ItemType extends Item>(sourceItems: ItemType[], itemsToRemove: ItemType[]): ItemType[] {
		let sourceMap = _createItemMap<ItemType>(sourceItems);
		itemsToRemove.forEach((each: ItemType) => {
			sourceMap.delete(each._getUUID());
		});
		return CMap._valueStream(sourceMap).collect();
	}

	export function _createItemId(control: UIControl, item: Item) {
		return ufc.NodeUUIDMapper.INSTANCE._createPartialUUID(control, `${control.uuid}-${item._getUUID()}`);
	}
}
