/// <reference path="./MatrixRequestBuilder.ts"/>

namespace cpr.protocols.matrix {


	export class MatrixMultipartRequestBuilder extends MatrixRequestBuilder {
		private static _multipart_instance: MatrixMultipartRequestBuilder;

		public static get INSTANCE(): MatrixMultipartRequestBuilder {
			if (!MatrixMultipartRequestBuilder._multipart_instance) {
				MatrixMultipartRequestBuilder._multipart_instance = new MatrixMultipartRequestBuilder();
			}
			return MatrixMultipartRequestBuilder._multipart_instance;
		}


		constructor() {
			super();
		}

		public build(submission: MatrixSubmission): any {
			if (Submission._HASBODY_METHOD.indexOf(submission.method) === -1) {
				console.warn("Submission(\"" + submission.id + "\") method has been changed to POST. \"" + Submission.MEDIA_MULTIPART + "\" media types can not use " + submission.method.toUpperCase() + " method. Available methods [" + Submission._HASBODY_METHOD.join(",").toUpperCase() + "]");
				submission.method = Submission.METHOD_POST;
			}

			// Basic Support : Chrome 7.0, Edge (yes), Firefox 4.0, IE 10, Opera 12, Safari 5
			let formData: FormData = new FormData();

			// files
			let fileParamNames: string[] = submission.getFileParameterNames();
			fileParamNames.forEach((name: string) => {
				let values: File[] = submission.getFileParameters(name);
				values.forEach((value: File) => {
					if (value && value.name) {
						formData.append(name, value, value.name); // IE11
					} else {
						formData.append(name, value); // IE10
					}
				})
			});

			let dataModel: MatrixDataModel = submission._getProtocolDataModel() as MatrixDataModel;
			let dataPartName: string = dataModel._getDataPartName();

			// json request object
			let dataPart: any = super.build(submission);
			formData.append(dataPartName, dataPart);

			return formData;
		}

		public getContentType(): string {
			// multipart 인 경우 boundary 가 추가되어 자동으로 입력됨.
			return null;
		}
	}
}