namespace cpr {

	/**
	 * @private
	 * @noinstance
	 */
	class SystemLocaleManager {
		private _data: CMap<string, Locale>;

		constructor() {
			this._data = _createMap<string, Locale>();
			let data = core.PlatformLocales._getData();
			Object.keys(data).forEach(locale => {
				let eachData = data[locale];
				this._defineLocale(locale, eachData);
			})
		}

		private _ensureData(): CMap<string, Locale> {
			if (!this._data) {
				this._data = _createMap<string, Locale>();
			}
			return this._data;
		}

		/**
		 * 지역을 정의합니다. 이미 정의된 지역인 경우 경고 메시지를 출력합니다.
		 * @param locale 
		 * @param data 
		 * @returns 
		 */
		private _defineLocale(locale: string, data: DefinableLocaleData) {
			if (typeof data !== "object") {
				return;
			}
			if (this._ensureData().has(locale)) {
				return;
			}
			this._ensureData().set(locale, new Locale(locale, data));
		}

		/**
		 * 사용자가 설정한 locale data를 찾아 반환합니다. 없는 경우 현재 locale을 반환합니다.
		 * @param locale 
		 */
		public localeData(locale: string): Locale {
			let localeData = this._ensureData().get(locale);
			if (!localeData && SystemLocale._getAvailableLocales().indexOf(locale) > -1) {
				let definableLocaleData = SystemLocale._createSystemLocaleData(locale);
				if (definableLocaleData) {
					this._defineLocale(locale, definableLocaleData);
					localeData = this._ensureData().get(locale);
				}
			}
			return localeData;
		}

		/**
		 * locale을 확인하여 지원되는 locale인지 확인합니다.
		 * @param locale 
		 * @returns 
		 */
		public isSupportedLocale(locale: string): boolean {
			if (!locale) {
				return false;
			}
			return this._ensureData().has(locale) || SystemLocale._getAvailableLocales().indexOf(locale) > -1;
		}

	}

	/**
	 * @private
	 * @noinstance
	 */
	export class LocaleManager {
		private static _INSTANCE: LocaleManager;

		private _data: CMap<string, Locale>;
		private _parent: SystemLocaleManager;
		private _currentLocale: string;

		constructor() {
			this._parent = new SystemLocaleManager();
		}

		public static get INSTANCE() {
			if (!this._INSTANCE) {
				this._INSTANCE = new LocaleManager();
			}
			return this._INSTANCE;
		}

		private _ensureData(): CMap<string, Locale> {
			if (!this._data) {
				this._data = _createMap<string, Locale>();
			}
			return this._data;
		}

		/**
		 * 지역을 정의합니다. 이미 정의된 지역인 경우 경고 메시지를 출력합니다.
		 * @param locale 
		 * @param data 
		 * @returns 
		 */
		public defineLocale(locale: string, data: DefinableLocaleData) {
			if (typeof data !== "object") {
				return;
			}
			if (this._ensureData().has(locale)) {
				console.warn(`warning: locale(${locale}) is already defined.`);
				return;
			}

			this._ensureData().set(locale, new Locale(locale, data));
			cpr.core.NotificationCenter.INSTANCE.post(core.SystemTopics.LOCALE_DID_CHANGE, locale, this);
		}

		/**
		 * 지역을 업데이트합니다. 데이타가 null인 경우 해당 지역을 삭제합니다.
		 * @param locale 
		 * @param data 
		 * @returns 
		 */
		public updateLocale(locale: string, data: LocaleData) {
			let isChangedLocale = false;
			if (data == null) {
				if (this._ensureData().delete(locale)) {
					isChangedLocale = true;
				}
			} else {
				let localeData = this._ensureData().get(locale);
				if (localeData == null) {
					localeData = new Locale(locale, data);
					this._ensureData().set(locale, localeData);
				} else {
					localeData._update(data);
				}
				isChangedLocale = true;
			}

			if (isChangedLocale) {
				cpr.core.NotificationCenter.INSTANCE.post(core.SystemTopics.LOCALE_DID_CHANGE, locale, this);
			}
		}

		/**
		 * 현재 locale data를 반환합니다.
		 * @param locale 
		 * @returns 
		 */
		public localeData(): Locale;
		/**
		 * 사용자가 설정한 locale data를 찾아 반환합니다. 없는 경우 현재 locale을 반환합니다.
		 * @param locale 
		 */
		public localeData(locale: string): Locale;
		public localeData(locale?: string): Locale {
			locale = locale || this.current;
			return this._ensureData().get(locale);
		}

		/**
		 * 사용자 locale > 시스템 locale 순으로 찾아 반환합니다.
		 * 런타임에서는 이 메소드를 사용해야 합니다.
		 * @param locale 
		 * @returns 
		 */
		public _findLocaleData(locale?: string): Locale {
			locale = locale || this.current;
			return this.localeData(locale) || this._parent.localeData(locale);
		}

		/**
		 * 시스템 locale을 찾아 반환합니다.
		 * @param locale 
		 * @returns 
		 */
		public _getSystemLocaleData(locale: string): Locale {
			return this._parent.localeData(locale);
		}

		/**
		 * 사용자가 설정한 locale을 반환합니다.
		 * @returns 
		 */
		public locales(): string[] {
			return CMap._keyStream(this._ensureData()).collect();
		}

		/**
		 * 현재 locale을 반환합니다.
		 */
		public get current(): string {
			return this._currentLocale ?? this._detectBaseLocale();
		}

		/**
		 * 현재 locale을 설정합니다.
		 */
		public set current(locale: string) {
			if (this.isSupportedLocale(locale) === false) {
				return;
			}
			this._currentLocale = locale;
			if (!this._updateLanguage()) {
				cpr.core.NotificationCenter.INSTANCE.post(core.SystemTopics.LOCALE_DID_CHANGE, locale, this);
			}
		}

		/**
		 * 언어를 기준으로 기본 locale을 찾아 반환합니다.
		 * 지원되는 locale이 없는 경우 기본 locale을 반환합니다.
		 * @returns 
		 */
		private _detectBaseLocale() {
			let locale = SystemLocale._getValidLocale(I18N.INSTANCE.currentLanguage);
			if (this.isSupportedLocale(locale)) {
				return locale;
			}
			else {
				return SystemLocale._getDefaultLocale();
			}
		}

		/**
		 * 사용자 locale과 시스템 locale을 확인하여 지원되는 locale인지 확인합니다.
		 * @param locale 
		 * @returns 
		 */
		public isSupportedLocale(locale: string): boolean {
			if (!locale) {
				return false;
			}
			return this._ensureData().has(locale) || this._parent.isSupportedLocale(locale);
		}

		/**
		 * 언어를 갱신합니다. 현재 설정된 locale과 언어가 다른 경우에만 갱신합니다.
		 * @param locale
		 * @returns 
		 */
		private _updateLanguage(): boolean {
			let localeData = this._findLocaleData();
			let currentLanguage = I18N.INSTANCE.currentLanguage;
			let localeLanguage = currentLanguage;

			[localeData.identifier, localeData._getAltLocale().identifier].some((each) => {
				let split = each.split("-");
				for (let i = split.length; i > 0; i--) {
					let localeArray = [];
					for (let j = 0; j < i; j++) {
						localeArray.push(split[j]);
					}
					let locale = localeArray.join("-");
					if (I18N.INSTANCE.isSupportedLanguage(locale)) {
						localeLanguage = locale;
						break;
					}
				}
				return localeLanguage != currentLanguage;
			})

			if (currentLanguage != localeLanguage) {
				I18N.INSTANCE.currentLanguage = localeLanguage;
			}
			return currentLanguage != localeLanguage;
		}
	}

}