namespace cpr.utils {
	export interface StringifyOption {
		decimalFormat?: "string" | "number",
		mimeType?: string
	}
	/**
	 * @private
	 */
	export interface BlobBuilder {
		append(data: ArrayBuffer): void;
		append(data: Blob): void;
		append(data: string): void;
		getBlob(contentType: string): Blob;
	}

	/**
	 * @private
	 */
	export abstract class ExBlobBuilder {
		public static readonly DEFAULT_TYPE: string = "plain/text";
		// protected static readonly _blobType: { type: string } = { type: "plain/text" };
		// protected static readonly _maxBufSize: number = 256 * 1024;
		protected static readonly _maxBufSize: number = 128 * 1024; // encoder 지원시 메모리 효율성 고려 128 kb

		protected _type: { type: string } = { type: ExBlobBuilder.DEFAULT_TYPE };
		protected _encoder: (strData: string) => string = null;


		constructor(strEncoder: (strData: string) => string) {
			this._encoder = strEncoder;
		}

		public _setMimeType(mimeType: string): void {
			this._type = { type: mimeType }
		}

		public abstract _appendBlob(blob: Blob): void;
		public abstract _appendString(strData: string): void;
		public abstract _getBlob(): Blob;
		public abstract _dispose(): void;
	}

	/**
	 * @private
	 */
	export class StringBufferedBlobBuilder extends ExBlobBuilder {
		private _lob: Blob;
		private _strBuf: string[];
		private _bufSize: number;


		constructor(strEncoder: (strData: string) => string) {
			super(strEncoder);

			this._lob = null;
			this._strBuf = [];
			this._bufSize = 0;
		}

		public _appendBlob(blob: Blob): void {
			if (!blob) {
				return;
			}
			if (this._lob) {
				// this._lob = new Blob([this._lob, blob], ExBlobBuilder._blobType);
				this._lob = new Blob([this._lob, blob], this._type);
			} else {
				this._lob = blob;
			}
		}
		public _appendString(strData: string): void {
			if (strData == "") {
				return;
			}
			// if (this._encoder) {
			// 	strData = this._encoder(strData);
			// }
			this._strBuf[this._strBuf.length] = strData;
			this._bufSize += strData.length;
			if (this._bufSize >= ExBlobBuilder._maxBufSize) {
				this._moveToBlob();
			}
		}
		public _getBlob(): Blob {
			this._flush();

			let returnBlob: Blob = this._lob;

			this._lob = null;
			this._strBuf = null;
			this._bufSize = null;

			return returnBlob;
		}

		private _flush(): void {
			if (this._bufSize > 0) {
				this._moveToBlob();
			}
		}

		private _moveToBlob(): void {
			if (this._encoder) {
				let strData: string = this._strBuf.join("");
				strData = this._encoder(strData);
				if (this._lob) {
					// this._lob = new Blob([this._lob, new Blob([strData], ExBlobBuilder._blobType)], ExBlobBuilder._blobType);
					this._lob = new Blob([this._lob, new Blob([strData], this._type)], this._type);
				} else {
					// this._lob = new Blob([strData], ExBlobBuilder._blobType);
					this._lob = new Blob([strData], this._type);
				}
			} else {
				if (this._lob) {
					// this._lob = new Blob([this._lob, new Blob(this._strBuf, ExBlobBuilder._blobType)], ExBlobBuilder._blobType);
					this._lob = new Blob([this._lob, new Blob(this._strBuf, this._type)], this._type);
				} else {
					// this._lob = new Blob(this._strBuf, ExBlobBuilder._blobType);
					this._lob = new Blob(this._strBuf, this._type);
				}
			}
			this._strBuf.splice(0);
			this._bufSize = 0;
		}

		public _dispose(): void {
			this._lob = null;
			this._strBuf = null;
			this._bufSize = null;
		}
	}

	/**
	 * @private
	 */
	export class NativeBlobBuilder extends ExBlobBuilder {
		private _builder: BlobBuilder;
		private _strBuf: string[];
		private _bufSize: number;


		constructor(strEncoder: (strData: string) => string, builder: BlobBuilder) {
			super(strEncoder);
			this._builder = builder;

			this._strBuf = [];
			this._bufSize = 0;
		}

		public _appendBlob(blob: Blob): void {
			if (!blob) {
				return;
			}
			this._builder.append(blob);
		}

		public _appendString(strData: string): void {
			if (strData == "") {
				return;
			}
			// if (this._encoder) {
			// 	strData = this._encoder(strData);
			// }
			this._strBuf[this._strBuf.length] = strData;
			this._bufSize += strData.length;
			if (this._bufSize >= ExBlobBuilder._maxBufSize) {
				if (this._encoder) {
					this._builder.append(this._encoder(this._strBuf.join("")));
				} else {
					this._builder.append(this._strBuf.join(""));
				}
				this._strBuf.splice(0);
				this._bufSize = 0;
			}
		}
		public _getBlob(): Blob {
			if (this._bufSize > 0) {
				if (this._encoder) {
					this._builder.append(this._encoder(this._strBuf.join("")));
				} else {
					this._builder.append(this._strBuf.join(""));
				}
				this._strBuf.splice(0);
				this._bufSize = 0;
			}

			// let resultBlob: Blob = this._builder.getBlob(ExBlobBuilder._blobType.type);
			let resultBlob: Blob = this._builder.getBlob(this._type.type);

			this._strBuf = null;
			this._bufSize = null;
			this._builder = null;

			return resultBlob;
		}

		public _dispose(): void {
			this._builder = null;
			this._strBuf = null;
			this._bufSize = null;
		}
	}

	export class JSONBlob {
		private static readonly _rx_escapable: RegExp = /[\\"\u0000-\u001f\u007f-\u009f\u00ad\u0600-\u0604\u070f\u17b4\u17b5\u200c-\u200f\u2028-\u202f\u2060-\u206f\ufeff\ufff0-\uffff]/g;
		private static readonly _meta: { [key: string]: string } = {    // table of character substitutions
			"\b": "\\b",
			"\t": "\\t",
			"\n": "\\n",
			"\f": "\\f",
			"\r": "\\r",
			"\"": "\\\"",
			"\\": "\\\\"
		};
		private static readonly _stringTP: string = "string";
		private static readonly _numberTP: string = "number";
		private static readonly _booleanTP: string = "boolean";
		private static readonly _undefinedTP: string = "undefined";
		private static readonly _objectTP: string = "object";
		private static readonly _nullTP: string = "null";
		private static readonly _functionTP: string = "function";
		private static readonly _objectArrayTP: string = "[object Array]";
		private static readonly _commaTP: string = ",";
		private static readonly _colonTP: string = ":";

		private static readonly _openBracket: string = "[";
		private static readonly _closeBracket: string = "]";
		private static readonly _openBrace: string = "{";
		private static readonly _closeBrace: string = "}";
		private static readonly _doubleQuote: string = "\"";

		private _builder: ExBlobBuilder;
		private _stringifiOption: StringifyOption;


		constructor() {
		}

		private _quote(strData: string) {
			JSONBlob._rx_escapable.lastIndex = 0;

			return JSONBlob._rx_escapable.test(strData)
				? [JSONBlob._doubleQuote, strData.replace(JSONBlob._rx_escapable, (a: string) => {
					var c = JSONBlob._meta[a];
					return typeof c === JSONBlob._stringTP ? c : "\\u" + ("0000" + a.charCodeAt(0).toString(16)).slice(-4);
				}), JSONBlob._doubleQuote].join("")
				: [JSONBlob._doubleQuote, strData, JSONBlob._doubleQuote].join("");
		}

		private _str(key: string | number, holder: {}): void {
			let value: any = holder[key];

			if (value && typeof value === JSONBlob._objectTP && typeof value.toJSON === JSONBlob._functionTP) {
				value = value.toJSON(key);
			}

			switch (typeof value) {
				case JSONBlob._stringTP: // "string"
					this._builder._appendString(this._quote(value));
					return;
				case JSONBlob._numberTP: // "number"
					this._builder._appendString((isFinite(value)) ? String(value) : JSONBlob._nullTP);
					return;
				case JSONBlob._booleanTP: // "boolean"
					this._builder._appendString(String(value));
					return;
				case JSONBlob._undefinedTP: // "undefined"
					this._builder._appendString(JSONBlob._nullTP);
					return;
				case JSONBlob._objectTP: // "object"
					if (!value) {
						this._builder._appendString(JSONBlob._nullTP);
					} else if (Object.prototype.toString.apply(value) === JSONBlob._objectArrayTP) {
						this._builder._appendString(JSONBlob._openBracket);
						let length: number = value.length;
						for (let i: number = 0; i < length; i++) {
							if (i > 0) {
								this._builder._appendString(JSONBlob._commaTP);
							}
							this._str(i, value);
						}
						this._builder._appendString(JSONBlob._closeBracket);
					} else if (value instanceof foundation.DecimalType) {
						let stringValue: string = value.toString();
						if (this._stringifiOption.decimalFormat == "number") {
							this._builder._appendString(stringValue);
						} else {
							this._builder._appendString(this._quote(stringValue));
						}
					} else {
						this._builder._appendString(JSONBlob._openBrace);
						let first: boolean = true;
						for (let k in value) {
							if (Object.prototype.hasOwnProperty.call(value, k)) {
								if (first) {
									first = false;
								} else {
									this._builder._appendString(JSONBlob._commaTP);
								}
								this._builder._appendString(this._quote(k) + JSONBlob._colonTP);
								this._str(k, value);
							}
						}
						this._builder._appendString(JSONBlob._closeBrace);
					}
					return;
			}
		}

		public toBlob(value: {}, strEncoder: (strData: string) => string, op: StringifyOption = {}): Blob {
			"use strict";
			let nativeBuilder = window["BlobBuilder"] || window["MSBlobBuilder"] || window["MozBlobBuilder"] || window["WebKitBlobBuilder"];
			if (nativeBuilder) {
				this._builder = new NativeBlobBuilder(strEncoder, new nativeBuilder() as BlobBuilder);
			} else {
				this._builder = new StringBufferedBlobBuilder(strEncoder);
			}
			this._stringifiOption = _defaults(op, { decimalFormat: "string", mimeType: ExBlobBuilder.DEFAULT_TYPE });
			this._builder._setMimeType(this._stringifiOption.mimeType);

			this._str("", { "": value });

			let resultBlob: Blob = this._builder._getBlob();

			this._builder._dispose();
			this._builder = null;
			this._stringifiOption = null;

			return resultBlob;
		}

	}
}