namespace cpr.controls.menu {

	/**
	 * @private
	 */
	export interface MenuOwner extends AccessableUIControl {
		expandTrigger: string;
		listArrowImage: string;
		direction?: MenuDirectionType;
		selectionTarget?: MenuSelectionTargetType;
		barItemSpacing?: number;
		getChildren(): MenuItem[];
	}

	/**
	 * @private
	 */
	export enum MenuTimeoutEventType {
		mouseleave = "mouseleave"
	}

	/**
	 * @private
	 */
	export abstract class AbstractMenu implements IMenu {

		private _uicontrol: MenuOwner;
		private _binder: provider.MenuDataBinder;
		private _ns: string;
		private _listeners: { [key: string]: Function[] } = {};
		private _stylerName: { [name: string]: string, list: string, item: string };
		private _rootNodeName: string = "menubar";
		private _visible: boolean = true;
		protected _hoveredItem: MenuItem = null;
		protected _subMenuInfos: SubMenuInfo[] = [];

		private _items: MenuItem[];

		protected _viewportRect: geometry.Rectangle;

		constructor(uicontrol: MenuOwner, ns: string, binder: provider.MenuDataBinder, stylerName: { [name: string]: string, list: string, item: string }, rootNodeName?: string) {
			this._uicontrol = uicontrol;
			this._binder = binder;
			this._ns = ns;
			this._stylerName = stylerName;
			this._items = [];
			this._viewportRect = new geometry.Rectangle();
			if (rootNodeName) {
				this._rootNodeName = rootNodeName;
			}
		}

		protected _getMenuItemQuerySelector() {
			return "[data-role='menuitem']";
		}

		public init(): void {
			this._clearHoveredItem();
			this._removeAllSubMenuInfo();
		}

		public getType() {
			return "menu";
		}

		public getRootNodeName() {
			return this._rootNodeName;
		}

		public setRootNodeName(nodeName: string) {
			if (this._rootNodeName == nodeName) {
				return;
			}
			this._rootNodeName = nodeName;
		}

		public getVisible(): boolean {
			return this._visible;
		}

		public setVisible(visible: boolean) {
			this._visible = visible;
		}

		public cancelTimeoutEvent(name: string) {
			//override
		}

		public executeTimeoutEvent(name: string) {
			//override
		}

		/**
		 * 이벤트를 전달 합니다.
		 * @param e 이벤트(현재는 마우스 이벤트)
		 */
		public dispatchEvent(type: string, e?: Event): boolean {
			if (this.disposed) {
				return false;
			}
			let dispatchEvent = true;

			if (!this._listeners[type]) {
				return dispatchEvent;
			}

			this._listeners[type].forEach((each: Function) => {
				each(e);
			});
			if (e) {
				dispatchEvent = !e.defaultPrevented;
			}
			return dispatchEvent;
		}
		/**
		 * @param type 
		 * @param func 
		 */
		public addEventListener(type: string, func: Function) {
			if (!this._listeners[type]) {
				this._listeners[type] = [];
			}
			this._listeners[type].push(func);
		}
		/**
		 * @param type 
		 * @param func 
		 */
		public removeEventListener(type: string, func: (e: any) => any) {
			if (!this._listeners[type]) {
				return;
			}
			let idx = this._listeners[type].indexOf(func);
			if (idx > -1) {
				this._listeners[type].splice(idx, 1);
			}
		}

		public get disposed() {
			return this._uicontrol == null;
		}

		public dispose(): void {
			this._listeners = null;
			this._uicontrol = null;
			this._hoveredItem = null;
			this._items = null;
		}

		/**
		 * @param type 
		 */
		public removeAllEventListener(type: string) {
			if (!this._listeners[type]) {
				return;
			}
			this._listeners[type] = [];
		}

		protected _getDirection(): MenuDirectionType {
			if (this._uicontrol["direction"]) {
				return this._uicontrol.direction;
			}
			return MenuDirectionType.ltr;
		}
		protected _getExpandTrigger() {
			return this._uicontrol.expandTrigger;
		}

		protected _getListArrowImage() {
			return this._uicontrol.listArrowImage;
		}

		protected _getStartItemDepth() {
			return 1;
		}

		protected _getBarItemSpacing() {
			if (this._uicontrol["barItemSpacing"]) {
				return this._uicontrol["barItemSpacing"];
			}
			return 0;
		}

		public setItems(items: MenuItem[]) {
			this._items = items;
		}

		public getItems() {
			return this._items;
		}

		public _getMenuItemId(item: MenuItem) {
			return ufc.NodeUUIDMapper.INSTANCE._createPartialUUID(this._getUIControl(), item.value);
		}

		protected abstract _createShape(): cpr.ufc.ElementShape;

		public createShape(): cpr.ufc.ElementShape {
			return this._createShape();
		}

		public traverseHover(keyCode: number, current: MenuItem) {
			let result = null;
			switch (keyCode) {
				case events.KeyCode.DOWN:
					result = this._transferHoverForward(current);
					break;
				case events.KeyCode.UP:
					result = this._transferHoverBackward(current);
					break;
				case events.KeyCode.LEFT:
					if (this._getDirection() == MenuDirectionType.ltr) {
						result = this._transferHoverUpCycle(current);
					} else {
						result = this._transferHoverDownCycle(current);
					}
					break;
				case events.KeyCode.RIGHT:
					if (this._getDirection() == MenuDirectionType.ltr) {
						result = this._transferHoverDownCycle(current);
					} else {
						result = this._transferHoverUpCycle(current);
					}
					break;
			}
			return result;
		}

		protected _nextNavItem(item: MenuItem) {
			let parentItem = this._binder.getDataProvider().getParent(item);

			let children = this._binder.getDataProvider().getChildren(parentItem);
			let len = children.length;

			let index = _.findIndex(children, { value: item.value });
			let nextIndex = index + 1 > len - 1 ? 0 : index + 1;
			while (nextIndex != index) {
				if (this._getDataBinder().getItemEnable(children[nextIndex]) == false) {
					nextIndex = nextIndex + 1 > len - 1 ? 0 : nextIndex + 1;
				} else {
					break;
				}
			}
			return children[nextIndex];
		}

		protected _prevNavItem(item: MenuItem) {
			let parentItem = this._binder.getDataProvider().getParent(item);

			let children = this._binder.getDataProvider().getChildren(parentItem);

			let len = children.length;
			let index = _.findIndex(children, { value: item.value });
			let prevIndex = index - 1 < 0 ? len - 1 : index - 1;
			while (prevIndex != index) {
				if (this._getDataBinder().getItemEnable(children[prevIndex]) == false) {
					prevIndex = prevIndex - 1 < 0 ? len - 1 : prevIndex - 1
				} else {
					break;
				}
			}
			return children[prevIndex];
		}

		/**
		 * 선택 가능한 아이템 타입을 반환합니다.
		 * @returns 
		 */
		protected _getSelectionTargetType() {
			return this._uicontrol.selectionTarget ?? MenuSelectionTargetType.all
		}

		public _transferHoverForward(item: MenuItem) {
			let traversedHover = null;
			if (item == null || item.depth == 0) return traversedHover;
			traversedHover = this._nextNavItem(item);
			this.setHoveredItem(traversedHover, { updateScroll: true, expand: this._getSelectionTargetType() == MenuSelectionTargetType.all });
			return traversedHover;
		}

		public _transferHoverBackward(item: MenuItem) {
			let traversedHover = null;
			if (item == null || item.depth == 0) return traversedHover;
			traversedHover = this._prevNavItem(item);
			this.setHoveredItem(traversedHover, { updateScroll: true, expand: this._getSelectionTargetType() == MenuSelectionTargetType.all });
			return traversedHover;
		}

		public _transferHoverUpCycle(item: MenuItem) {
			return this._hoverUpCycle(item);
		}

		private _hoverUpCycle(item: MenuItem) {
			let traversedHover: MenuItem = null;
			if (item.depth < 2) {
				return traversedHover;
			}
			if (item._hasChild()) {
				if (item.expanded) {
					item._setOpen(false);
					this._getUIControl().redraw();
				}
			}
			traversedHover = item.parentItem;
			if (this._getDataBinder().getItemEnable(traversedHover)) {
				this.setHoveredItem(traversedHover, { updateScroll: true, expand: this._getSelectionTargetType() == MenuSelectionTargetType.all });
			} else {
				traversedHover = this._hoverUpCycle(traversedHover);
			}
			return traversedHover;
		}

		public _transferHoverDownCycle(item: MenuItem) {
			let traversedHover = null;
			if (item._hasChild()) {
				let children = this._getDataBinder().getChildren(item);
				let idx = 0;
				traversedHover = children[idx];
				if (!this._getDataBinder().getItemEnable(traversedHover)) {
					let traverseIndex = this._traverseItemIndex(true, idx, children, idx);
					if (traverseIndex == idx) {
						traversedHover = null;
					} else {
						traversedHover = children[traverseIndex];
					}
				}
				if (!item.expanded) {
					item._setOpen(true);
					this._getUIControl().redraw();
				}
				this.setHoveredItem(traversedHover, { updateScroll: true, expand: this._getSelectionTargetType() == MenuSelectionTargetType.all });
			}
			return traversedHover;
		}

		protected _traverseItemIndex(forward: boolean, currentIndex: number, items: MenuItem[], baseIndex: number) {
			let delta = forward ? 1 : -1;
			let nextIndex = currentIndex + delta;
			let item = items[nextIndex];
			if (!item) {
				return baseIndex;
			}
			if (!this._getDataBinder().getItemEnable(item)) {
				if (nextIndex == baseIndex) {
					return baseIndex
				} else {
					return this._traverseItemIndex(forward, nextIndex, items, baseIndex);
				}
			}
			return nextIndex;
		}
		public _getHoveredItems(): TreeItem[] {
			let result = [];
			let hoveredItem = this.getHoveredItem();
			if (!hoveredItem) {
				return result;
			}
			result.push(hoveredItem);
			let parentItem = hoveredItem.parentItem;
			let startDepth = this._getStartItemDepth();
			while (parentItem != null && parentItem.depth >= startDepth) {
				result.push(parentItem);
				parentItem = parentItem.parentItem;
			}
			result = result.reverse()
			return result;
		}

		protected abstract _updateScrollByHover(currentHover: MenuItem, beforeHover?: MenuItem);

		public _setFocusedItem(item: MenuItem) {
			this._updateScrollByHover(item, this._hoveredItem);
			this._hoveredItem = item;

			this._getUIControl().redraw();
		}

		/**
		 * _setHoveredItem을 override 하세요.
		 * @param item 
		 * @param options 
		 * @returns 
		 */
		public setHoveredItem(item: MenuItem, options: { updateScroll?: boolean, expand?: boolean } = {}) {
			if (this._hoveredItem == item) {
				return;
			}
			if (item?._equalsValue(this._hoveredItem)) {
				return;
			}
			this._setHoveredItem(item, options);
		}

		protected _setHoveredItem(item: MenuItem, options: { updateScroll?: boolean, expand?: boolean } = {}) {
			_defaults(options, { updateScroll: false, expand: true });
			if (options.updateScroll) {
				this._updateScrollByHover(item, this._hoveredItem);
			}
			if (item?.parentItem?.value != this._hoveredItem?.value && this._hoveredItem?._hasChild()) {
				this._hoveredItem._setOpen(false);
			}
			// 마지막 호버 아이템 설정
			this._hoveredItem = item;
			if (this._hoveredItem?._hasChild()) {
				this._hoveredItem._setOpen(options.expand);
			}

			this._getUIControl().redraw();
		}

		public getHoveredItem(): MenuItem {
			return this._hoveredItem;
		}

		protected _isHoveredItem(item: MenuItem) {
			let hoveredItems = this._getHoveredItems();
			let index = _.findIndex(hoveredItems, { value: item.value });
			if (index > -1) {
				return true;
			}
			return false;
		}

		protected _removeAllSubMenuInfo() {
			if (this._subMenuInfos && this._subMenuInfos.length == 0) {
				return;
			}
			this._subMenuInfos = [];
			this._uicontrol.redraw();
		}

		protected _clearHoveredItem() {
			if (this._hoveredItem == null) {
				return;
			}
			this._getHoveredItems().forEach((each: TreeItem) => {
				if (each._hasChild()) {
					each._setOpen(false);
				}
			})
			this._hoveredItem = null;
			this._uicontrol.redraw();
		}

		protected _isEnabled() {
			return this._uicontrol.enabled;
		}

		protected _getQName(name?: string) {
			return name ? this._ns + "-" + name : this._ns;
		}

		protected _getUIControl() {
			return this._uicontrol;
		}

		protected _getDataBinder() {
			return this._binder;
		}

		protected _getStylerName(name: string): string {
			return this._stylerName[name];
		}

		protected _getSelectedValues(): string[] {
			let selectedValues: string[] = [];
			if (this._getDataBinder().getValues().length > 0) {
				let findItem = this._binder.findTreeItem(this._getDataBinder().getValues()[0], this.getItems()) as MenuItem;
				while (findItem) {
					selectedValues.push(findItem.value);
					findItem = findItem.parentItem as MenuItem;
				}
			}
			return selectedValues;
		}

		protected _isHoverTrigger() {
			return ExpandTriggerType[this._getExpandTrigger()] == ExpandTriggerType.hover;
		}

		protected _getQClass(name: string) {
			return "cl-" + this._ns + "-" + name;
		}

		protected _getRenderer() {
			return this._uicontrol._getRenderer();
		}

		protected _convertIndexByParentItem(item: MenuItem) {
			return item.depth - 1;
		}

		protected _getSubMenuNodeName(index: number = 0) {
			return `${this.getRootNodeName()}-submenu-${index}`;
		}

		protected _getSubMenuNodeByIndex(idx: number = 0) {
			return this._getRenderer().getNamedNode(this._getSubMenuNodeName(idx));
		}

		protected _useBodyScroll(): boolean {
			return this._uicontrol.getAppInstance().getContainer()._useBodyScroll();
		}

		protected _initViewportRect() {
			this._viewportRect = _getVisualViewportRect();
		}

		protected _clearViewportRect() {
			this._viewportRect = new geometry.Rectangle();
		}

		/**
		 * 아이템의 너비를 계산합니다.
		 * @param rowElement 리스트의 로우 아이템
		 */
		protected _getComputedItemWidth(menuElement: HTMLElement, menuItemSelector: string) {
			let rowElement = menuElement.querySelector(menuItemSelector);
			if (!rowElement) {
				return 0;
			}
			let computedStyle = getComputedStyle(rowElement);
			let fontProps = ["fontStyle", "fontVariant", "fontWeight", "fontSize", "lineHeight", "fontFamily"];
			let font = "";
			let result = 0;
			for (let prop of fontProps) {
				if (prop == "lineHeight") {
					font += " / " + computedStyle[prop];
				} else {
					font += " " + computedStyle[prop];
				}
			}
			let parentValue = menuElement.getAttribute("data-parent");
			let children = [];
			if (parentValue == null) {
				children = this.getItems();
			} else {
				let parentItem: MenuItem = this._binder.findTreeItem(parentValue, this.getItems()) as MenuItem;
				children = parentItem.children;
			}
			let textMetrics = this._getMaxLengthByItemLabel(font, children as MenuItem[]);
			result += textMetrics.width + parseInt(computedStyle.paddingLeft) + parseInt(computedStyle.paddingRight);

			let len = rowElement.children.length;
			for (let i = 0; i < len; i++) {
				let each = rowElement.children[i];
				if (each.classList.contains("cl-sub")) {
					continue;
				}
				let eachStyle = getComputedStyle(each);
				if (each.classList.contains(ufc.Classes.TEXT) == false && each.classList.contains("cl-" + this._getQName() + "-list") == false) {
					result += eachStyle.width ? parseInt(eachStyle.width) : 0;
				}
				result += parseInt(eachStyle.paddingLeft);
				result += parseInt(eachStyle.paddingRight);
			}

			return Math.round(result);
		}

		protected _getItemByMenuElement(element: HTMLElement) {

			let parentValue = element.getAttribute("data-parent");
			let parentItem: MenuItem = this._binder.findTreeItem(parentValue, this.getItems()) as MenuItem;
			return parentItem;
		}

		protected _getItemByElement(element: HTMLElement): MenuItem {
			let item: MenuItem = null;
			let id: string = element.getAttribute("data-itemid");
			if (id != null) {
				item = this._binder.getDataProvider().getByValue(id) as MenuItem;
			}
			return item;
		}

		protected _onItemSelect(item: MenuItem, e: UIEvent, done?: (success: boolean) => void): boolean {
			let result = false;

			if (item == null || !this._binder.getItemEnable(item)) {
				return result;
			}

			if (this._uicontrol.readOnly == false) {
				let selectEvent = new cpr.events.CItemEvent("--internal-item-select", { item: item });
				this.dispatchEvent("--internal-item-select", selectEvent);
				if (this.disposed) {
					return;
				}
				result = this._getDataBinder().isSelected(item);
			}
			if (done) {
				core.DeferredUpdateManager.INSTANCE.asyncExec(() => {
					if (this.disposed) {
						return;
					}
					let itemClickEvent = new cpr.events.CItemEvent(events.ItemEventType.ITEMCLICK, {
						item: item
					});
					let nEvent = e;
					if (e.type == "keydown") {
						nEvent = new events.CMouseEvent("click");
					}
					itemClickEvent.nativeEvent = nEvent;
					if (done) {
						done(result);
					}
					this.dispatchEvent(events.ItemEventType.ITEMCLICK, itemClickEvent);
				});
			}
			return result;
		}

		protected _getParentItem(item: MenuItem) {
			let parentItem = this._getDataBinder().getDataProvider().getParent(item);
			return parentItem && parentItem.depth >= this._getStartItemDepth() ? parentItem : null;
		}

		protected _getGroupItemsByItem(item: MenuItem): MenuItem[] {
			let parentItem = this._getDataBinder().getDataProvider().getParent(item);
			return parentItem == null ? this._getDataBinder().getChildren() : parentItem.children as MenuItem[];
		}

		private _getMaxLengthByItemLabel(font: string, items: MenuItem[]): { width: number, text: string } {
			let text = "";
			let result = { width: 0, text: "" };
			let tmpWidth = 0;
			for (let item of items) {
				text = ufc.StyledString._asString(this._binder._computeItemDisplayLabel(item));
				tmpWidth = utils.StringUtil.measureText(text, font);
				tmpWidth += item.icon ? 20 : 0;
				if (tmpWidth > result.width) {
					result.width = tmpWidth;
					result.text = text;
				}
			}
			return result;
		}



	}//class

}//namespace