/// <reference path="./AbstractScrollStrategy.ts" />

namespace cpr.controls.gridpart.layout {


	/**
	 * @private
	 * GridDetail를 처리하기 위한 ScrollStrategy
	 * 커스텀 스크롤바 기능이 포함되었음.
	 */
	export class ActiveScrollStrategy extends AbstractScrollStrategy implements IGridScrollbarOwner {

		/* scroll state cache */
		private _virtualScrollTop: number = 0;
		private _virtualScrollLeft: number = 0;

		private _scrollbarAdapter: IScrollbarAdapter = null;

		constructor(scrollPane: ScrollPane, context: GridContext) {
			super(scrollPane, context);

			if (this._context.getGrid()._isUseCustomScroll()) {
				this._scrollbarAdapter = new ScrollbarCustomAdapter(this);
			} else {
				this._scrollbarAdapter = new ScrollbarNativeAdapter(this);
			}
		}

		/* 내부 사용 Properties start */
		get virtualscrolltop(): number {
			return this._virtualScrollTop;
		}
		set virtualscrolltop(scrollTop: number) {
			this._virtualScrollTop = scrollTop;
		}
		get virtualscrollleft(): number {
			return this._virtualScrollLeft;
		}
		set virtualscrollleft(scrollLeft: number) {
			this._virtualScrollLeft = scrollLeft;
		}
		/* 내부 사용 Properties end */

		/**
		 * @override
		 */
		public _getRenderedMaxScrollTop(): number {
			let viewHeight: number = this._getViewportHeight();
			let maxScrollTop: number = this._scrollbarAdapter._getContentHeight() - viewHeight; // scrollbarAdapter에는 그려질 때 사용된 contentHeight가 항상 저장됨
			maxScrollTop = maxScrollTop < 0 ? 0 : maxScrollTop;
			return maxScrollTop;
		}

		public _getRenderedMaxScrollLeft(): number {
			let viewWidth: number = this._getViewportWidth();
			let maxScrollLeft: number = this._scrollbarAdapter._getContentWidth() - viewWidth; // scrollbarAdapter에는 그려질 때 사용된 contentWidth가 항상 저장됨
			maxScrollLeft = maxScrollLeft < 0 ? 0 : maxScrollLeft;
			return maxScrollLeft;
		}

		public _getRenderStartRow(): number {
			return this._context._getStartRowIndex(this._scrollPane.location);
		}

		public _getRenderEndRow(): number {
			return this._context._getEndRowIndex(this._scrollPane.location);
		}

		public _readyForRedraw(): void {
			// scroll 초기화 
			// core.DeferredUpdateManager.INSTANCE.asyncExec로 초기화 할 경우
			// IE에서 시점의 문제로 scroll이 표시되지 않는 문제 때문에 scroll 초기화는 실시간으로 처리
			if (this._context.disposed == true) {
				return;
			}
			// DOM의 scroll 위치는 redraw 후 동기화할 때 처리하여 흰 화면이 나오지 않도록 한다
			this.viewportscrolltop = 0;
			this.virtualscrolltop = 0;
			this.viewportscrollleft = 0;
			this.virtualscrollleft = 0;

			this._settedScrollTop = -1;
			this._settedScrollLeft = -1;
		}

		public _initScrollTop(scrollTop: number): void {
			this._init();
			this._setViewportVScroll(scrollTop);
			this._setVScroll(scrollTop);

			// @experimental RELATED DataWindow
			let dataProvider: provider.GridDataProvider = this.grid.dataProvider;
			if (dataProvider._isWholeDataAccessable() == false) {
				let contentHeight: number = this._scrollPane.owner._getContentHeight();
				if (contentHeight > 1) {
					let reqIdx: { startIdx: number, endIdx: number } = this._getScrollDataIndex(scrollTop);
					let rowCnt: number = reqIdx.endIdx + 1;
					dataProvider._setFetchHandler(0, rowCnt, () => { });
				}
			}
		}
		public _initScrollLeft(scrollLeft: number): void {
			this._setViewportHScroll(scrollLeft);
			this._setHScroll(scrollLeft);
		}
		public _createScrollPane(): ufc.ElementShape {
			this._init();
			// 그려진 후 스크롤바가 생기거나 최대 높이가 변경될 수 있으므로 스크롤 위치는 그려진 후에 동기화 한다
			core.DeferredUpdateManager.INSTANCE.asyncExec(this._syncScrollFunc);

			let contentView: IGridPartArea = this._scrollPane.owner;
			let rowGroupChildren: ufc.ElementShapeContent[] = [];

			// scroll hidden이지만, mousewheel을 통해 스크롤링이 가능하게 하기 위해 생성하도록 함
			let scrollContainer: ufc.ElementShape = {
				tag: "div",
				attr: {
					"data-role": "scroll-container"
				},
				style: {
					"overflow": "hidden",
					position: "absolute",
					transform: "translate3d(0px, 0px, 0px)",
					left: "0px",
					top: "0px",
					right: "0px",
					bottom: "0px"
				},
				events: {
					scroll: (e: events.CUIEvent) => { this._onViewportScroll(e); }, // tab key에 의한 컨트롤 간의 스크롤 처리
					wheel: (e: events.CWheelEvent) => { this._onDOMWheel(e); },
					touchstart: (e: events.CTouchEvent) => { this._onTouchStart(e); },
					touchmove: (e: events.CTouchEvent) => { this._onTouchMove(e); },
					touchend: (e: events.CTouchEvent) => { this._onTouchEnd(e); }
				},
				nodename: "scr-" + this._scrollPane.region + "-" + this._scrollPane.location,
				children: []
			};

			if (this._scrollPane.region == GRIDREGION.CENTER && this._context._isReqVScroll() == true) {
				// mobile에서 touch로 scroll을 할 수 있도록 지원하기 위해 content 영역에 scroll을 만듬
				scrollContainer.style["right"] = this._scrollbarAdapter._getVScrollbarWidth() + "px"; // IE에서 Scrollbar 동작을 위한 영역 할당
			}

			if (this._context._isReqHScroll() == false && this._context._isReqVScroll() == false) {
				delete scrollContainer.style["transform"];
			}

			// 1. content 높이 계산
			let contentHeight: number = contentView._getContentHeight();
			contentHeight = this._convertCorrectContentHeight(contentHeight);
			let contentWidth: number = contentView._getContentWidth();
			this._scrollbarAdapter._setContentHeight(contentHeight);
			this._scrollbarAdapter._setContentWidth(contentWidth);

			// 2. content create 
			// 1에서 계산한 content 높이에 의해 2에서 그려질 행의 수, maxScrollTop을 가져오기 때문에 이 순서가 유지되어야 함.
			scrollContainer.children[0] = contentView._createShape();

			rowGroupChildren[rowGroupChildren.length] = scrollContainer;

			// resize, 행 추가로 인한 스크롤바 존재여부 변경 등과 같은 변경에도 스크롤바의 scroll position을 보전하기 위해 스크롤바가 보여지지 않는 상황에도 보이지 않는 div로 dom 영역을 제공함
			//--- vertical scrollbar
			if (this._scrollPane.region == GRIDREGION.CENTER) {
				let vScroll: ufc.ElementShape = null;
				if (this._context._isReqVScroll() == true) {
					// 그리드 리사이즈 시 vscrollbar의 상태를 보존하기 위해 vscrollbar와 blank의 순서 보장
					// 최신 scrollTop 값을 scrollbar 생성시 전달
					vScroll = this._scrollbarAdapter._createVScrollbar(this.virtualscrolltop, contentHeight);
				} else {
					vScroll = this._scrollbarAdapter._createDummyVScrollbar();
				}
				rowGroupChildren[rowGroupChildren.length] = vScroll;

				let vscrollBottom: string = null;
				if (this._scrollPane.location == GRIDREGION.MIDDLE) {
					if (this._context._isReqVScroll() == true && this._context._isReqHScroll() == true) {
						rowGroupChildren[rowGroupChildren.length] = {
							tag: "div",
							attr: {},
							classNames: [GridStyle.BLANK],
							nodename: this._scrollPane.location + "-blank",
							style: {
								position: "absolute",
								width: this._scrollbarAdapter._getVScrollbarWidth() + "px",
								height: this._scrollbarAdapter._getHScrollbarHeight() + "px",
								right: "0px",
								bottom: "0px"
							},
							children: []
						};
						vscrollBottom = this._scrollbarAdapter._getHScrollbarHeight() + "px";
					} else {
						rowGroupChildren[rowGroupChildren.length] = {
							tag: "div",
							attr: {},
							classNames: [GridStyle.BLANK],
							style: {
								display: "none",
								position: "absolute",
								width: "0px",
								height: "0px",
								right: "0px",
								bottom: "0px"
							},
							children: []
						};
						vscrollBottom = "0px";
					}

				} else {
					vscrollBottom = "0px";
				}

				vScroll.style["bottom"] = vscrollBottom;
			}
			//--- horizontal scrollbar
			if (this._scrollPane.location === GRIDREGION.MIDDLE) {
				let hscrollbar: ufc.ElementShape = null;
				if (this._context._isReqHScroll() == true) {
					hscrollbar = this._scrollbarAdapter._createHScrollbar(this.virtualscrollleft, contentWidth);
					if (this._scrollPane.region == GRIDREGION.CENTER && this._context._isReqVScroll() == true) {
						hscrollbar.style["right"] = this._scrollbarAdapter._getVScrollbarWidth() + "px";
					} else {
						hscrollbar.style["right"] = "0px";
					}

					scrollContainer.style["bottom"] = this._scrollbarAdapter._getHScrollbarHeight() + "px"; // IE에서 Scrollbar 동작을 위한 영역 할당
				} else {
					hscrollbar = this._scrollbarAdapter._createDummyHScrollbar();
				}

				rowGroupChildren[rowGroupChildren.length] = hscrollbar;
			}

			let shape: ufc.ElementShape = {
				tag: "div",
				attr: {
					"data-role": GRIDROLE.ROWGROUP,
					"data-loc": this._scrollPane.location
				},
				style: {
					position: "relative",
					display: "block",
					width: "100%",
					height: "100%"
				},
				nodename: this._scrollPane.nodename,
				children: rowGroupChildren
			};

			return shape;
		}

		/* EventHandler */
		protected _dispatchScrollEvent(e: events.CEvent, axis: events.ScrollAxis): void {
			this.context._dispatchScrollEvent(e, {
				axis: axis,
				scrollTop: this._scrollPane._getBusScollTop(),
				maxScrollTop: this._getRenderedMaxScrollTop(),
				scrollLeft: this._scrollPane._getBusScrollLeft(),
				maxScrollLeft: this._getRenderedMaxScrollLeft()
			});
		}

		/* DOM EventHandler start */

		protected _onViewportScroll(e: events.CUIEvent): void {
			// 세로 스크롤 처리 추가(걸쳐진 로우를 클릭했을 때 처리)
			let target: HTMLElement = <HTMLElement>e.target;
			let scrollTop: number = target.scrollTop;
			let scrollLeft: number = target.scrollLeft;

			if (this._context._isWholeRenderingMode() && this._settedScrollTop !== -1 && GridUtil._equalsApproximately(scrollTop, this._settedScrollTop)) { // TODO check
				scrollTop = this.viewportscrolltop;
				this._settedScrollTop = -1;
			}
			if (this._settedScrollLeft !== -1 && GridUtil._equalsApproximately(scrollLeft, this._settedScrollLeft)) {
				scrollLeft = this.viewportscrollleft;
				this._settedScrollLeft = -1;
			}

			let axis: events.ScrollAxis = this._adjustViewportScroll(e, scrollTop, scrollLeft);
			if (axis != null) {
				this._dispatchScrollEvent(e, axis); // grid scroll event
			}
		}

		/**
		 * IE 이외의 브라우저에서 발생하는 wheel event 처리.
		 * IE의 경우 addEventListener로만 동작하며, 현재 이 기능을 사용함.
		 * @override
		 */
		protected _onDOMWheel(e: events.CWheelEvent): void {
			if (e._isOccupied() == true) {
				return;
			}
			if (e._getMod1Key() === true) { // 확대/축소
				return;
			}
			if (e.target instanceof HTMLTextAreaElement) {
				return;
			}
			if (this._context._isReqVScroll() == false && this._context._isReqHScroll() == false) {
				return;
			}
			if (this.grid._isEnabled() == false) {
				return;
			}

			let eventDelta: { x: number, y: number } = internal.ScrollbarUtil._getScrollPaneWheelDelta(e);
			let delta: number = 0;
			let rowHeight: number = this.rowheight;
			// release-test-project#6885 : delta 가 기본 rowHeight 보다 클 경우 wheelrowcount 적용
			if (Math.abs(eventDelta.x) < rowHeight && Math.abs(eventDelta.y) < rowHeight) {
				let absDeltaX: number = Math.abs(eventDelta.x);
				let absDeltaY: number = Math.abs(eventDelta.y);
				delta = (absDeltaY != 0) ? absDeltaY : absDeltaX; //rowHeight;
			} else {
				let wheelRowCount: number = this._context.wheelRowCount;
				delta = rowHeight * wheelRowCount;
			}
			let deltaX: number = 0;
			let deltaY: number = 0;
			// IE를 제외한 모든 브라우저가 Shift + Wheel을 가로 스크롤로 사용함(IE에서는 wheel + shift를 히스토리 이동에 사용).
			if (e._getMod2Key()) {
				if (this.grid.hScroll != "hidden") {
					deltaX = eventDelta.x;
				}
			} else {
				// magicmouse 지원
				if (this.grid.hScroll != "hidden") {
					deltaX = eventDelta.x;
				}
				if (this.grid.vScroll != "hidden") {
					let offset: number = eventDelta.y == 0 ? 0 : (eventDelta.y > 0 ? 1 : -1);
					deltaY = delta * offset;
				}
			}

			let scrollLeft: number = this.viewportscrollleft + deltaX;
			let scrollTop: number = this.viewportscrolltop + deltaY;

			let axis: events.ScrollAxis = this._adjustScroll(e, scrollTop, scrollLeft);
			if (axis != null) {
				e.preventDefault();
				e.stopPropagation();
				e._setOccupied(true);

				this._dispatchScrollEvent(e, axis); // grid scroll event
			} else {
				if (this._context.getGrid().overscrollBehavior === OverscrollBehaviorType.NONE) {
					e.preventDefault();
					e._setOccupied(true);
				}
			}

		}

		protected _adjustScroll(e: events.CEvent, scrollTop: number, scrollLeft: number): events.ScrollAxis {
			scrollLeft = scrollLeft < 0 ? 0 : scrollLeft;
			scrollTop = scrollTop < 0 ? 0 : scrollTop;

			let moveScrollTop: boolean = false;
			let moveScrollLeft: boolean = false;

			// 세로 스크롤일 때 그리드 영역 안에 있는 컨트롤에서 포커스를 가지고 있으면 blur를 발생시킴.
			if (scrollTop != this.viewportscrolltop) {
				// scroll이 될 수 없는 조건 필터링
				let maxScrollTop: number = this._getRenderedMaxScrollTop();
				if (scrollTop > maxScrollTop) {
					scrollTop = maxScrollTop;
				}
				if (maxScrollTop == -1) {
					moveScrollTop = false;
					scrollTop = this.viewportscrolltop;
				} else if ((this.viewportscrolltop == maxScrollTop && scrollTop == maxScrollTop) ||
					(this.viewportscrolltop == 0 && scrollTop == 0)) {
					moveScrollTop = false;
					scrollTop = this.viewportscrolltop;
				} else {
					moveScrollTop = true;
				}
			}
			if (scrollLeft != this.viewportscrollleft) {
				// scroll이 될 수 없는 조건 필터링
				let maxScrollLeft: number = this._getRenderedMaxScrollLeft();
				if (scrollLeft > maxScrollLeft) {
					scrollLeft = maxScrollLeft;
				}
				if (maxScrollLeft == -1) {
					moveScrollLeft = false;
					maxScrollLeft = this.viewportscrollleft;
				} else if ((this.viewportscrollleft == maxScrollLeft && scrollLeft == maxScrollLeft) ||
					(this.viewportscrollleft == 0 && scrollLeft == 0)) {
					moveScrollLeft = false;
					maxScrollLeft = this.viewportscrollleft;
				} else {
					moveScrollLeft = true;
				}
			}

			if (moveScrollTop == false && moveScrollLeft == false) {
				return null;
			}

			this._moveFocusToGrid();

			this._adjustViewportScroll(e, scrollTop, scrollLeft);

			return moveScrollTop && moveScrollLeft ? events.ScrollAxis.both : (moveScrollTop ? events.ScrollAxis.y : events.ScrollAxis.x);
		}

		/* 전역 EventHandler */
		public _setViewportScrollTop(e: events.CEvent, scrollTop: number): number { // 그리드 가상스크롤바의 스크롤 이벤트 발생시 뷰포트의 스크롤탑 조정
			if (this._context.disposed == true) {
				return;
			}
			if (this._context.getGrid().isShowing() == false) {
				return;
			}
			// WIN7 Chrome의 경우 scrollTop에 소수점이 포함될 수 있어서 최대 스크롤일 경우 보정.
			// if (GridUtil._equalsApproximately(this.virtualscrolltop, scrollTop)) {
			if ((scrollTop == 0 && this.virtualscrolltop == 0) || (scrollTop != 0 && GridUtil._equalsApproximately(this.virtualscrolltop, scrollTop))) {
				return scrollTop;
			}
			let maxScrollTop: number = this._getRenderedMaxScrollTop();
			if (GridUtil._equalsApproximately(maxScrollTop, scrollTop)) {
				scrollTop = maxScrollTop;
			}

			this._moveFocusToGrid();

			this._scrollPane._postScrollTop(scrollTop, e);
			this.viewportscrolltop = scrollTop; // 스크롤바에서 이벤트가 발생했을 경우 scrollTop을 동기화 대상에서 제외

			this._dispatchScrollEvent(e, events.ScrollAxis.y); // grid scroll event

			return scrollTop;
		}

		public _setViewportScrollLeft(e: events.CEvent, scrollLeft: number): number { // 그리드 가상스크롤바의 스크롤 이벤트 발생시 뷰포트의 스크롤레프트 조정
			if (this._context.disposed == true) {
				return;
			}
			if (this._context.getGrid().isShowing() == false) {
				return;
			}
			if (this.virtualscrollleft == scrollLeft) {
				return scrollLeft;
			}
			this._scrollPane._postScrollLeft(scrollLeft, e);
			this.viewportscrollleft = scrollLeft; // 스크롤바에서 이벤트가 발생했을 경우 scrollLeft를 동기화 대상에서 제외
			this._dispatchScrollEvent(e, events.ScrollAxis.x); // grid scroll event

			return scrollLeft;
		}


		// ScrollBus에서의 스크롤 변경 통지 처리
		public _handleScrollTop(e: events.CScrollEvent): void {
			if (typeof e.scrollTop != "number") {
				return;
			}
			let scrollTop: number = e.scrollTop;
			this._settedScrollTop = scrollTop;
			if (this.viewportscrolltop !== scrollTop) {
				this._setViewportVScroll(scrollTop);
			}
			if (this.virtualscrolltop !== scrollTop) {
				this._setVScroll(scrollTop);
			}
		}

		public _handleScrollLeft(e: events.CScrollEvent): void {
			if (typeof e.scrollLeft != "number" || this.viewportscrollleft == e.scrollLeft) {
				return;
			}
			// scrollLeft 동작시 스크롤 이동을 redraw 시점과 일치화 시키기 위해 async로 동작시킴
			core.DeferredUpdateManager.INSTANCE._asyncExecBefore(() => {
				if (this._context == null || this._context.disposed == true) {
					return;
				}
				let scrollLeft: number = this._scrollPane._getBusScrollLeft();
				this._settedScrollLeft = scrollLeft;
				if (this.viewportscrollleft !== scrollLeft) {
					this._setViewportHScroll(scrollLeft);
				}
				if (this.virtualscrollleft !== scrollLeft) {
					this._setHScroll(scrollLeft);
				}
			});
		}

		/**
		 * Vertical Scroll 이벤트를 받아 viewport의 top 위치 변경
		 */
		protected _setVScroll(scrollTop: number): void {
			// viewport의 scrolltop 조정
			let gridRenderer: ufc.ControlRenderer = this._context.getGrid()._getRenderer();
			let viewportElement: HTMLElement = gridRenderer.getNamedNode("scr-" + this._scrollPane.region + "-" + this._scrollPane.location);
			if (viewportElement && viewportElement.scrollTop != scrollTop) {
				viewportElement.scrollTop = scrollTop;
			}
			this.virtualscrolltop = scrollTop;
		}

		/**
		 * Horizontal Scroll 이벤트를 받아 viewport의 left 위치 변경
		 */
		protected _setHScroll(scrollLeft: number): void {
			// viewport의 scrollleft 조정
			let gridRenderer: ufc.ControlRenderer = this._context.getGrid()._getRenderer();
			let viewportElement: HTMLElement = gridRenderer.getNamedNode("scr-" + this._scrollPane.region + "-" + this._scrollPane.location);
			if (viewportElement && viewportElement.scrollLeft != scrollLeft) {
				viewportElement.scrollLeft = scrollLeft;
			}
			this.virtualscrollleft = scrollLeft;
		}

		/**
		 * Viewport의 Scroll 이벤트를 받아 VerticalScrollBar의 Top 위치 변경
		 * @param e events.CScrollEvent
		 */
		protected _setViewportVScroll(scrollTop: number): void { // 가상스크롤바의 스크롤탑 조정
			if (this._context.disposed == true) {
				return;
			}
			this._scrollbarAdapter._setVScrollTop(scrollTop);
			this.viewportscrolltop = scrollTop;
		}

		/**
		 * Viewport의 Scroll 이벤트를 받아 HolizontalScrollBar의 Left 위치 변경
		 * @param e events.CScrollEvent
		 */
		protected _setViewportHScroll(scrollLeft: number): void { // 가상스크롤바의 스크롤레프트 조정
			if (this._context.disposed == true) {
				return;
			}
			this._scrollbarAdapter._setHScrollLeft(scrollLeft);
			this.viewportscrollleft = scrollLeft;
		}

		// protected _syncScrollFunc: Function = () => this._syncScroll();
		protected _syncScroll(): void {
			if (this._context == null || this._context.disposed == true) {
				return;
			}
			if (this._context._isWholeRenderingMode() !== true || this._settedScrollTop == -1) {
				let eventScrollTop: number = this._scrollPane._getBusScollTop();
				if (eventScrollTop != -1) {
					this._setViewportVScroll(eventScrollTop);
					this._setVScroll(eventScrollTop);
				}
			}
			if (this._settedScrollLeft == -1) {
				let eventScrollLeft: number = this._scrollPane._getBusScrollLeft();
				if (eventScrollLeft != -1) {
					this._setViewportHScroll(eventScrollLeft);
					this._setHScroll(eventScrollLeft);
				}
			}
		}
		/* DOM EventHandler end */

		protected _getScrollDataIndex(scrollTop: number): { startIdx: number, endIdx: number } {
			let viewportHeight: number = this._getViewportHeight();
			let reqStart: number = this._context._getRenderStartRowOverScrollTop(this._scrollPane.location, scrollTop);
			let reqEnd: number = this._context._getRenderLastRowIndexInViewportHeight(this._scrollPane.location, reqStart, viewportHeight);

			if (GridUtil._equalsApproximately(this._getRenderedMaxScrollTop(), scrollTop) == true) {
				let totalRowHeight: number = this._context._getRangeHeight(reqStart, reqEnd, this._scrollPane.location);
				if (viewportHeight < totalRowHeight) {
					reqStart += 1;
				}
			}

			return { startIdx: reqStart, endIdx: reqEnd };
		}

		public _getNewestMaxScrollTop(): number {
			// 컨텐츠 높이가 변경되지 않았으면 _getRenderedMaxScrollTop 를 리턴하고
			let contentHeight: number = this._context._getContentHeight(this._scrollPane.location);
			let renderedContentHeight: number = this._scrollbarAdapter._getContentHeight();
			if (contentHeight > 0 && contentHeight === renderedContentHeight) { // 컨텐트 높이에 변경이 없으면
				return this._getRenderedMaxScrollTop();
			}
			// 변경되었으면 최선 컨텐츠 높이를 계산하여 MaxScrollTop을 리턴
			let contentView: IGridPartArea = this._scrollPane.owner;
			contentHeight = contentView._getContentHeight();
			let newContentHeight: number = this._convertCorrectContentHeight(contentHeight);
			let viewportHeight: number = this._getViewportHeight();
			return newContentHeight > viewportHeight ? newContentHeight - viewportHeight : 0;
		}
		private _convertCorrectContentHeight(contentHeight: number): number {
			if (this._context._isWholeRenderingMode() == true) {
				return contentHeight;
			} else {
				// 스크롤바의 스크롤 이벤트를 지원하기 위해 contents의 크기를 늘려야 할지 체크
				let viewportHeight: number = this._getViewportHeight();
				if (contentHeight > viewportHeight) {
					let maxScrollTop: number = contentHeight - viewportHeight;
					maxScrollTop = maxScrollTop < 0 ? 0 : maxScrollTop;

					let reqStart: number = this._context._getRenderStartRowOverScrollTop(this._scrollPane.location, maxScrollTop);
					let reqEnd: number = this._context._getRenderLastRowIndexInViewportHeight(this._scrollPane.location, reqStart, viewportHeight);

					let totalRowHeight: number = this._context._getRangeHeight(reqStart, reqEnd, this._scrollPane.location);
					if (viewportHeight < totalRowHeight) {
						let firstRowHeight: number = this._context._getRangeHeight(reqStart, reqStart, this._scrollPane.location); // 마지막페이지 첫 행의 높이
						let appendHeight: number = firstRowHeight - (totalRowHeight - viewportHeight);

						return contentHeight + appendHeight;
					} else if (maxScrollTop < 10) {
						return contentHeight + (10 - maxScrollTop);
					}
				}
				return contentHeight;
			}

		}
		public _getNewestMaxScrollLeft(): number {
			let contentView: IGridPartArea = this._scrollPane.owner;
			let contentWidth: number = contentView._getContentWidth();
			let viewportWidth: number = this._getViewportWidth();
			return contentWidth > viewportWidth ? contentWidth - viewportWidth : 0;
		}

		// 현재 화면을 기준으로 jump할 행의 방향을 제공
		protected _getJumpDirection(targetIndex: number): number {
			let direction: number = 0;
			let gridDetail: GridDetail = this._scrollPane.owner as GridDetail;
			let renderedEndRowIdx: number = gridDetail._getRenderedEndRowIdx();

			if (renderedEndRowIdx === -1) {
				direction = 1;
			} else {
				let renderedStartRowIdx: number = gridDetail._getRenderedStartRowIdx();
				if (targetIndex < renderedStartRowIdx) {
					direction = -1;
				} else if (targetIndex >= renderedEndRowIdx) {
					direction = 1;
				} else {
					let centerRowIndex: number = renderedStartRowIdx + ((renderedEndRowIdx - renderedStartRowIdx) / 2);
					direction = targetIndex >= centerRowIndex ? 1 : -1;
				}
			}

			return direction;
		}

		// IGridScrollbarOwner interface
		public _getRenderer(): ufc.ControlRenderer {
			return this.grid._getRenderer();
		}
		public _getQNamePrefix(): string {
			let scrollPane: IScrollPane = this._getScrollPane();
			return "scr-" + scrollPane.region + "-" + scrollPane.location;
		}
		public _getNativeVScrollbarOverflowY(): string {
			return this._getScrollPane().region == GRIDREGION.CENTER ? this.grid.vScroll : "hidden";
		}
		public _getNativeHScrollbarOverflowX(): string {
			let context: GridContext = this.grid.context;
			return context.hScroll;
		}
		public _getAutofit(): string {
			return this.grid.autoFit;
		}
		public _isShowingVScrollbar(): boolean {
			let context: GridContext = this.grid.context;
			return this._getScrollPane().region == GRIDREGION.CENTER && context._isReqVScroll();
		}

		public _onJumpPage(e: events.CUIEvent): void {
			// viewport의 높이가 0이거나 보여지지 않을 때(감춰졌을 때)는 jump를 동작시키지 않는다.
			// tab의 감춰진 tabitem에 grid가 숨겨졌을 때 오동작 발생.
			let viewportHeight: number = this._getViewportHeight();
			if (viewportHeight == 0) {
				return;
			}

			let startrowindex: number = this._context._getStartRowIndex(this._scrollPane.location);
			let endrowindex: number = this._context._getEndRowIndex(this._scrollPane.location);
			let finalrowindex: number = this.grid.getContentRowCount() - 1;
			if (startrowindex == -1 || endrowindex == -1 || finalrowindex < 0) {
				// 비활성화
				return;
			}

			let moveposition: {
				srcIndex: number, offset: number, jumpIndex: number, jumpedIndex: number
			} = e.content as {
				srcIndex: number, offset: number, jumpIndex: number, jumpedIndex: number
			};

			let targetIndex: number = -1;
			if (moveposition.jumpIndex >= 0) {
				targetIndex = moveposition.jumpIndex;

				// jumpIndex를 기준으로 offset을 설정하여 스크롤의 방향을 다음 로직에 제공
				moveposition.offset = this._getJumpDirection(targetIndex);
			} else {
				targetIndex = moveposition.srcIndex + moveposition.offset;
			}

			if (targetIndex < 0) {
				targetIndex = 0;
			}
			if (targetIndex > finalrowindex) {
				targetIndex = finalrowindex;
			}
			moveposition.jumpedIndex = targetIndex;

			if (targetIndex < startrowindex || targetIndex > endrowindex) {
				return;
			}

			// 세로스크롤바의 현재 scrollTop을 가져옴
			let activeScrollTop: number = this._scrollbarAdapter._getActiveVScrollTop();
			if (activeScrollTop == -1) {
				return;
			}

			// 현재 보여진 페이지에 이동하고자 하는 RowIndex가 있을 경우 skip
			let reqIdx: { startIdx: number, endIdx: number } = this._getScrollDataIndex(activeScrollTop);
			if (targetIndex >= reqIdx.startIdx && targetIndex <= reqIdx.endIdx) {
				return;
			}

			let scrolltop: number = 0;
			if (targetIndex == startrowindex) {
				scrolltop = 0;
			} else {
				// 이 이벤트가 들어오기 전에 행이 추가되었을 수 있기 때문에 최신 스크롤탑으로 연산
				let maxScrollTop: number = this._getNewestMaxScrollTop();

				if (targetIndex == endrowindex) {
					scrolltop = maxScrollTop;
				} else {
					if (moveposition.offset > 0) {
						// down
						let firstRowIndex: number = this._context._getRenderStartRowIndexFromSelectableLastRowIndex(this._scrollPane.location, targetIndex, viewportHeight);
						scrolltop = this._context._getRangeHeight(startrowindex, firstRowIndex - 1, this._scrollPane.location);
					} else {
						// up
						scrolltop = this._context._getRangeHeight(startrowindex, targetIndex - 1, this._scrollPane.location);
					}
					if (scrolltop > maxScrollTop) {
						scrolltop = maxScrollTop;
					}
				}
			}

			let scrollAxis: events.ScrollAxis = this._adjustViewportScroll(e, scrolltop, this.viewportscrollleft);

			if (scrollAxis != null) {
				this._dispatchScrollEvent(e, scrollAxis); // grid scroll event
			}
		}
		public _setDecorator(gridPart: IGridPartArea): void {
			gridPart._setDecorator((shape: ufc.ControlShape) => {
				return this._decorateContentWindow(shape);
			});
		}
		protected _decorateContentWindow(contentShape: ufc.ControlShape): ufc.ControlShape {
			return contentShape;
		}

		public override _getVScrollbarWidth(): number {
			return this._scrollbarAdapter._getVScrollbarWidth();
		}

	}

}