/// <reference path="../controls/Control.ts"/>
/// <reference path="../expression/ExpressionEngine.ts"/>

namespace cpr.data {
	/**
	 * DataMap
	 * 데이터를 key, value로 가지고 있는 데이터 객체.
	 * 
	 * @fires cpr.events.CDataEvent#load build 메소드에 의해 데이터 구조가 재구성될 때 발생하는 이벤트.<br>
	 * 		최초 생성시에도 발생합니다.
	 * 
	 * @fires cpr.events.CDataEvent#update 데이터가 수정되는 경우 발생하는 이벤트.<br>
	 * 		발생 메소드 : setValue
	 * 		<pre>columnName: {string} 수정하려는 데이터의 컬럼명</pre>
	 * 		<pre>beforeValue: {any} 수정하려는 셀의 이전 값</pre>
	 * 		<pre>currentValue: {string} 현재값</pre>
	 * @fires cpr.events.CDataEvent#clear 데이터 정보를 제거하는 경우 발생하는 이벤트.<br>
	 * 		발생 메소드 : clear, (특정조건)build<br>
	 *  	build 메소드 사용 시 DataMap.alterColumnLayout="server" 일 때 이벤트가 발생합니다.
	 */
	export class DataMap extends controls.Control implements expression.EvaluationContext {
		private _headers: header.Headers;
		private _data: tabledata.RowData;
		private _attr: { [attrName: string]: string };

		/** 사용자 속성 */
		private _alterColumnLayout: ColumnLayout;
		private _info: string; // AutoCUD사용시 Table ID 등


		constructor(id: string) {
			super(id);

			this._headers = new header.Headers();
			// this._data = new tabledata.RowData(this);
			this._data = new tabledata.RowData();
			this._attr = {};

			this._alterColumnLayout = ColumnLayout.CLIENT;

			// control initializing
			this._initControl();
		}

		protected _getDefaultConfiguration(): core.Config {
			return core.AppConfig.INSTANCE.getDataConfig(this._getType());
		}

		protected _isConfigurableProperty(propName: string): boolean {
			if (["alterColumnLayout", "info"].indexOf(propName) != -1) {
				return true;
			}
			return super._isConfigurableProperty(propName);
		}

		override _getType(): controls.ControlType {
			return controls.ControlType.DATAMAP
		}

		/**
		 * build에 의해 데이터 구조가 재구성될 때 컬럼 구조 변경 기준을 설정합니다.<br>
		 * 올바르지 않은 값을 입력한 경우 기본값인 "client"로 설정됩니다.
		 * @param alterColumnLayout 컬럼 구조 변경 기준.<br>
		 * <변경기준 종류><br>
		 * [client] : 현재 컬럼 구조를 유지합니다.<br>
		 * [server] : 새로 입력받은 컬럼 데이터로 컬럼 구조를 변경합니다.<br>
		 * [merge] : 현재 컬럼 구조를 유지하며, 새로 입력받은 컬럼 데이터를 추가합니다.<br>
		 */
		set alterColumnLayout(alterColumnLayout: string) {
			if (alterColumnLayout != ColumnLayout.CLIENT && alterColumnLayout != ColumnLayout.SERVER && alterColumnLayout != ColumnLayout.MERGE) {
				alterColumnLayout = ColumnLayout.CLIENT;
			}
			this._alterColumnLayout = alterColumnLayout;
		}

		/**
		 * build에 의해 데이터 구조가 재구성될 때 컬럼 구조 변경 기준을 반환합니다.
		 * @return 컬럼 구조 변경 기준.<br>
		 * <변경기준 종류><br>
		 * [client] : 현재 컬럼 구조를 유지합니다.<br>
		 * [server] : 새로 입력받은 컬럼 데이터로 컬럼 구조를 변경합니다.<br>
		 * [merge] : 현재 컬럼 구조를 유지하며, 새로 입력받은 컬럼 데이터를 추가합니다.<br>
		 */
		get alterColumnLayout(): string {
			return this._alterColumnLayout as string;
		}

		/**
		 * 데이터맵 정보값을 설정합니다.
		 * @param info 설정할 정보값
		 */
		set info(info: string) {
			this._info = info;
		}

		/**
		 * 데이터맵 정보값을 반환합니다.
		 * @return 정보값.
		 */
		get info(): string {
			return this._info;
		}

		/**
		 * 데이터맵 속성, Column 정보, Row Data 정보를 세팅합니다.
		 * @param datamapInfo 데이터맵 정보.<br>
		 * 	{<br>
		 * 	&nbsp;	alterColumnLayout: string,	// build에 의해 데이터 전체 갱신시 column layout 변경 기준: "client" or "server" or "merge" <br>
		 * 	&nbsp;	info?: string,				// 데이터맵 정보. <br>
		 * 	&nbsp;	columns: {					// 컬럼 설정 정보. <br>
		 * 	&nbsp;&nbsp;		dataType: string,		// 데이터 타입. ("string" or "number" or "decimal" or "expression") <br>
		 * 	&nbsp;&nbsp;		name: string,			// 컬럼명. <br>
		 * 	&nbsp;&nbsp;		expression?: string,	// expression 식. (dataType="expression"일 때, expression식 설정) <br>
		 * 	&nbsp;&nbsp;		defaultValue?: string	// 기본 값. <br>
		 * 	&nbsp;	}[], <br>
		 * 	&nbsp;	data: {[columnName: string]: string | number} // 설정하고자 하는 데이터.<br>
		 * 	}
		 * 
		 * @example
		 * <code>
		 * datamap.parseData({
		 * 	alterColumnLayout: "client",
		 * 	info: "datamap_info",
		 * 	columns: [
		 * 		{ dataType: "string", name: "a", defaultValue: "a1" },
		 * 		{ dataType: "string", name: "b", defaultValue: "b1" },
		 * 		{ dataType: "string", name: "c", defaultValue: "c1" },
		 * 		{ dataType: "number", name: "d", defaultValue: 100 },
		 * 		{ dataType: "number", name: "e", defaultValue: 10 },
		 * 		{ dataType: "expression", name: "sum", expression: "d+e" }
		 * 	]
		 * });
		 * </code>
		 */
		public parseData(datamapInfo: DataMapConfigInfo): void {
			if (datamapInfo.alterColumnLayout) {
				this._alterColumnLayout = datamapInfo.alterColumnLayout;
			}
			if (datamapInfo.info) {
				this.info = datamapInfo.info;
			}
			this._createColumns(datamapInfo.columns, datamapInfo.data);
		}

		/**
		 * @private
		 */
		private _createColumns(colInfos: DataMapColumnConfigInfo[], datas: RowConfigInfo): void {
			if (colInfos == null) {
				return;
			}

			let columnCount: number = colInfos.length;
			let newColumn: header.Header;
			for (let i = 0; i < columnCount; i++) {
				let columnInfo: DataMapColumnConfigInfo = colInfos[i];
				let columnValue: any = datas ? datas[columnInfo.name] : columnInfo.defaultValue;
				if (columnInfo.dataType == "expression") {
					newColumn = new header.ExpressionHeader(columnInfo.name, columnInfo.expression);
				} else {
					newColumn = new header.DataHeader(columnInfo.name, columnInfo.dataType, columnInfo.defaultValue);
				}
				if (columnInfo.info != null) {
					newColumn.setInfo(columnInfo.info);
				}
				if (columnInfo.userAttr) {
					newColumn.userAttr(columnInfo.userAttr);
				}
				// DataMap에서는 display column에 대한 분리를 해주지 않음. (170421 hyeran)
				this._addColumn(newColumn, columnValue);
			}
		}

		/**
		 * json data를 통해 DataMap 구성합니다.
		 * 
		 * @param data	구성할 data.<br>
		 * {[columnName: string]: string | number}
		 * @return 추가된 column 수
		 */
		public build(data: RowConfigInfo): number {
			if (this._alterColumnLayout == ColumnLayout.SERVER) {
				// 기존 데이터 제거 후 새로 구성
				this._allClear();
			}

			/* column & data 추가하기
			- 현재 무조건 dataType: string으로 됨
			*/
			if (data != null && cpr.utils.ParamUtil.isJSON(data)) {
				if (this._alterColumnLayout == ColumnLayout.SERVER) {
					// 기존 데이터 제거 후 새로 구성
					let colNames: string[] = Object.keys(data);
					for (let colName of colNames) {
						let value: any = data[colName];
						this._addColumn(new header.DataHeader(colName, tabledata.DataType.STRING), value);
					}

				} else if (this._alterColumnLayout == ColumnLayout.MERGE) {
					// 기존 컬럼 정보는 그대로 둔 상태에서 새로운 컬럼 및 데이터 추가
					let colNames: string[] = _.union(this.getColumnNames(), Object.keys(data));
					for (let colName of colNames) {
						let value: any = data[colName];
						if (this.isExistColumn(colName)) {
							this._putValue(colName, value);
						} else {
							this._addColumn(new header.DataHeader(colName, tabledata.DataType.STRING), value);
						}
					}

				} else if (this._alterColumnLayout == ColumnLayout.CLIENT) {
					// 기존 컬럼 정보에 덮어쓰기
					let colNames: string[] = this.getColumnNames();
					for (let colName of colNames) {
						let value: any = data[colName];
						this._putValue(colName, value);
					}
				}
			}
			let dataEvent = new events.CDataEvent(events.DataEventType.LOAD);
			this.dispatchEvent(dataEvent);
			return this.getColumnCount();
		}

		/**
		 * 모든 데이터맵 정보를 제거합니다.
		 * (data, column정보 모두 제거)
		 */
		private _allClear(): void {
			this._headers.clear();
			this._data = null;
			// this._data = new tabledata.RowData(this);
			this._data = new tabledata.RowData();

			this.dispatchEvent(new events.CDataEvent(events.DataEventType._I_CLEAR)); // 내부 필수 처리
			this.dispatchEvent(new events.CDataEvent(events.DataEventType.CLEAR));
		}

		/**
		 * 데이터를 모두 제거합니다.<br>
		 * @param all 모든 정보를 제거할 지 유무.
		 * true: 속성, 컬럼정보, 데이터를 모두 제거합니다. 데이터의 경우 기본값("")으로 설정됩니다.
		 * false(default) : data가 모두 공백으로 설정됩니다.
		 */
		public clear(all: boolean = false): void {
			if (all === true) {
				this._init();
				this._allClear();
			} else {
				this._resetData(DataUtil._getDefaultValue());
				this.dispatchEvent(new events.CDataEvent(events.DataEventType._I_CLEAR)); // 내부 필수 처리
				this.dispatchEvent(new events.CDataEvent(events.DataEventType.CLEAR));
			}

		}

		private _init(): void {
			this.info = null;
			this.alterColumnLayout = ColumnLayout.CLIENT;

			this._initControl();
		}

		/**
		 * 데이터를 모두 초기 설정값(defaultValue)로 되돌립니다.
		 */
		public reset(): void {
			this._resetData();
		}

		/**
		 * @private
		 * 데이터를 입력한 default 값으로 재설정합니다.
		 * @param defaultValue 설정할 값.
		 */
		public _resetData(defaultValue?: (string | number)): void {
			this._data = null;
			// this._data = new tabledata.RowData(this);
			this._data = new tabledata.RowData();
			let colCount = this.getColumnCount();
			
			let hasDefaultValue: boolean = defaultValue !== undefined;
			if (defaultValue === null && DataUtil._getDefaultValue() !== null) {
				hasDefaultValue = false;
			}
			
			for (let i = 0; i < colCount; i++) {
				let header: header.Header = this._headers._getHeaderFromIndex(i);
				let headerDefaultValue: (string | number) = hasDefaultValue ? defaultValue : header._getDefaultValue();
				this._data._addData(header, headerDefaultValue);
			}
		}

		/**
		 * Column을 추가합니다.<br>
		 * Header정보에 추가되며, data가 있는 경우 row data에도 해당 column data가 추가됩니다.
		 * 
		 * @param column	추가하려는 Header 객체
		 * @param value	값 설정
		 * @return 컬럼 추가 성공 여부
		 */
		public addColumn(column: header.Header, value?: any): boolean {
			let result: boolean = this._addColumn(column, value);
			return result;
		}

		/**
		 * @private
		 * Column을 추가합니다.
		 * Header정보에 추가되며, data가 있는 경우 row data에도 해당 column data가 추가 된다.
		 * 
		 * @param column	추가하려는 Header 객체
		 * @param value	값 설정
		 * @return 컬럼 추가 성공 여부
		 */
		private _addColumn(column: header.Header, value?: any): boolean {
			if (this._validationCheckHeader(column) == false) {
				return false;
			}
			if (this.isExistColumn(column.getName())) {
				return false;
			}

			column._setColumnType(header.HeaderType.ORIGINAL_COLUMN);
			this._headers._addHeader(column);
			this._data._addData(column, value);

			return true;
		}

		/**
		 * Column을 삭제합니다.
		 * 
		 * @param columnName	삭제할 컬럼 명
		 * @return 컬럼 삭제 성공 여부
		 */
		public deleteColumn(columnName: column_name_string): boolean {
			if (columnName == null || columnName == "") {
				return false;
			}
			if (this.isExistColumn(columnName) == false) {
				return false;
			}

			let columnIndex: number = this._headers._getIndexFromName(columnName);
			this._headers._deleteHeaderFromIndex(columnIndex);
			this._data._deleteData(columnIndex);

			return true;
		}

		/**
		 * 컬럼명을 배열형식으로 반환합니다.
		 * 
		 * @return 컬럼명 배열
		 */
		public getColumnNames(): string[] {
			return this._headers._getColumnNames();
		}

		/**
		 * 컬럼 수를 반환합니다.
		 * 
		 * @return 컬럼 수
		 */
		public getColumnCount(): number {
			return this._headers._getCount();
		}

		/**
		 * 해당 컬럼명이 존재하는지 여부를 반환합니다.
		 * 
		 * @param columnName	검색할 컬럼명
		 * @return 해당 컬럼명이 존재하는지 여부
		 */
		public isExistColumn(columnName: string): boolean {
			return this._headers._isExist(columnName);
		}

		/**
		 * 해당 컬럼명을 통해 Header 객체를 반환합니다.
		 * 
		 * @param columnName	컬럼명
		 * @return 해당 컬럼명의 Header 객체
		 */
		public getHeader(columnName: string): header.Header {
			return this._headers._getHeader(columnName);
		}

		_getHeaderFromIndex(columnIndex: number): header.Header {
			return this._headers._getHeaderFromIndex(columnIndex);
		}

		/**
		 * Header들을 배열형태로 반환합니다.
		 * 
		 * @return Header 배열
		 */
		public getHeaders(): header.Header[] {
			return this._headers._getHeaders(header.HeaderType.ALL);
		}

		/**
		 * 현재 데이터맵의 데이터를 타겟 데이터셋으로 복사합니다. <br>
		 * 타겟 데이터셋의 존재하는 컬럼의 데이터만 복사됩니다.<br>
		 * 복사시 추가되는 데이터는 INSERTED 상태입니다.
		 * @param targetDataSet 복사 데이터가 들어갈 타겟 데이터셋.
		 * @param targetIndex 복사 데이터가 들어갈 row index.
		 * @param after targetIndex의 뒤에 삽입할지 여부.
		 */
		public copyToDataSet(targetDataSet: DataCollection, targetIndex?: number, after?: boolean): boolean {
			if (targetDataSet.type != controls.ControlType.DATASET && targetDataSet.type != controls.ControlType.DATAVIEW) {
				return false;
			}
			if (targetIndex == null || (utils.ParamUtil.isNumber(targetIndex) && targetIndex == 0 && targetDataSet.getRowCount() == 0)) {
				targetDataSet.addRowData(this.getDatas());
				return true;
			} else if (targetIndex >= 0 && targetIndex < targetDataSet.getRowCount()) {
				targetDataSet.insertRowData(targetIndex, after, this.getDatas());
				return true;
			}
			return false;
		}

		/**
		 * 현재 데이터맵의 데이터를 타겟 데이터맵으로 복사합니다. <br>
		 * 타겟 데이터셋의 존재하는 컬럼의 데이터만 복사됩니다.<br>
		 * @param targetDataMap 복사 데이터가 들어갈 타겟 데이터맵.
		 */
		public copyToDataMap(targetDataMap: DataMap): boolean {
			if (targetDataMap.type != controls.ControlType.DATAMAP) {
				return false;
			}
			let rowData: RowConfigInfo = this.getDatas()
			let columnNames: string[] = Object.keys(rowData);
			let length: number = columnNames.length;
			for (let i = 0; i < length; i++) {
				if (targetDataMap.isExistColumn(columnNames[i])) {
					targetDataMap.setValue(columnNames[i], rowData[columnNames[i]]);
				}
			}
			return true;
		}

		/**
		 * 입력 받은 columnName에 해당되는 데이터를 반환합니다.
		 * @param columnName	값을 가져오고자 하는 컬럼명
		 * @return 입력 받은 columnName의 데이터<br>
		 * 리턴 타입은 header dataType에 따라 정해집니다.<br>
		 * decimal type의 경우 <b>cpr.foundation.DecimalType</b>으로 반환합니다.<br> 
		 * decimal 객체에서 실제 값을 가져오기 위해서는 <b>toNumber()</b> 또는 <b>toString()</b>를 사용해야 합니다.<br>
		 * expression type의 경우 expression 실행 결과를 반환합니다.<br>
		 * 원하는 데이터 타입이 있는 경우 실행 결과가 해당 타입으로 반환되도록 표현식을 작성해야 합니다.<br>
		 * <br>
		 * 입력 받은 columnName의 <u>column이 존재 할 경우</u> <b>해당 값</b>을 반환합니다.<br>
		 * 입력 받은 columnName의 <u>column이 존재하지 않을 경우</u> <b>null</b>을 반환합니다.<br>
		 * 입력 받은 columnName의 <u>column에 값이 없을 경우</u> <b>""(빈 문자열)</b>을 반환합니다.(expression 제외)<br>
		 */
		public getValue(columnName: column_name_string): any {
			if (this._headers._isExist(columnName) == false) {
				throw new exceptions.IllegalArgumentException("Column named " + columnName + " is not found in DataMap : id " + this.id);
			}

			let value: any = null;
			let header: header.Header = this._headers._getHeader(columnName);
			if (header._isExpressionHeader()) { // expression header일 경우
				let exprHeader: header.ExpressionHeader = header as header.ExpressionHeader;
				let func: Function = exprHeader.getFunction();
				if (func != null) {
					value = func(this);
				}
			} else {
				let columnIndex: number = this._headers._getIndexFromName(columnName);
				if (header.getDataType() == tabledata.DataType.DECIMAL) { // decimal header일 경우
					value = this._data._getDecimal(header, columnIndex);
				} else {// 일반 header 일 경우
					value = this._data.getValue(columnIndex);
				}
			}
			return value;
		}

		/**
		 * 입력 받은 columnName에 해당되는 데이터를 수정합니다.
		 * 해당 columnName이 존재하지 않을 경우 IllegalArgumentException 이 throw 됩니다.
		 * @param columnName	수정할 column의 columnName
		 * @param value			수정할 value 값
		 */
		public setValue(columnName: column_name_string, value: any): void {
			if (this._headers._isExist(columnName) == false) {
				throw new exceptions.IllegalArgumentException("Column named " + columnName + " is not found in DataMap : id " + this.id);
			}

			let beforeValue: any = this.getValue(columnName);
			if (beforeValue !== value) {
				let preventDefault: boolean = this.dispatchEvent(new events.CDataEvent(cpr.events.DataEventType.BEFORE_UPDATE, {
					columnName: columnName,
					beforeValue: beforeValue,
					currentValue: value
				}));
				if (!preventDefault) {
					return;
				}

				let columnIndex: number = this._headers._getIndexFromName(columnName);
				let header: header.Header = this._getHeaderFromIndex(columnIndex);
				this._data.setValue(header, columnIndex, value);

				let dataEvent = new events.CDataEvent(cpr.events.DataEventType.UPDATE, {
					columnName: columnName,
					beforeValue: beforeValue,
					currentValue: value
				});
				this.dispatchEvent(dataEvent);
			}

		}

		/**
		 * 값 변경 관련 이벤트(before-update, update)를 발생시키지 않고, 원본 값과 현재 값을 모두 변경합니다.
		 * @param columnName 수정할 column의 columnName
		 * @param value 수정할 value 값
		 */
		public putValue(columnName: column_name_string, value: any): void {
			if (this._headers._isExist(columnName) == false) {
				throw new exceptions.IllegalArgumentException("Column named " + columnName + " is not found in DataMap : id " + this.id);
			}
			this._putValue(columnName, value);
		}

		/**
		 * @private
		 */
		private _putValue(columnName: column_name_string, value: any): void {
			let columnIndex = this._getColumnIndex(columnName);
			let header: header.Header = this._getHeaderFromIndex(columnIndex);
			// header._setDefaultValue(value);
			this._data._setOriginalValue(header, columnIndex, value);
			this._data.setValue(header, columnIndex, value);
		}

		/**
		 * 입력 받은 columnName에 해당되는 컬럼의 기본값을 설정합니다.<br>
		 * <br>
		 * 올바르지 않은 columnName을 입력시에는 IllegalArgumentException 이 throw 됩니다.<br>
		 * @param columnName	값을 가져올 column의 columnName.
		 * @param value	설정할 기본값.
		 */
		public setDefaultValue(columnName: column_name_string, value: (string | number)): void {
			if (this._headers._isExist(columnName) == false) {
				throw new exceptions.IllegalArgumentException("Column named " + columnName + " is not found in DataMap : id " + this.id);
			}
			let columnIndex = this._getColumnIndex(columnName);
			let header: header.Header = this._getHeaderFromIndex(columnIndex);
			header._setDefaultValue(value);
		}

		/**
		 * 입력 받은 columnName에 해당되는 컬럼의 기본값을 반환합니다.<br>
		 * <br>
		 * 올바르지 않은 columnName을 입력시에는 IllegalArgumentException 이 throw 됩니다.<br>
		 * @param columnName	값을 가져올 column의 columnName.
		 * @return 해당 기본값.
		 */
		public getDefaultValue(columnName: column_name_string): (string | number) {
			if (this._headers._isExist(columnName) == false) {
				throw new exceptions.IllegalArgumentException("Column named " + columnName + " is not found in DataMap : id " + this.id);
			}
			let columnIndex = this._getColumnIndex(columnName);
			let header: header.Header = this._getHeaderFromIndex(columnIndex);
			return header._getDefaultValue();
		}

		/**
		 * 입력 받은 columnName에 해당되는 원본 데이터를 반환합니다.<br>
		 * <br>
		 * 올바르지 않은 columnName을 입력시에는 IllegalArgumentException 이 throw 됩니다.<br>
		 * 입력 받은 columnName의 데이터가 없을 시 빈 문자열("")을 반환합니다.<br>
		 * 컬럼 데이터 타입이 expression인 경우 expression 실행 결과를 반환합니다.
		 * @param columnName	값을 가져올 column의 columnName.
		 * @return 해당 원본 데이터.
		 */
		public getOriginalValue(columnName: column_name_string): any {
			/* 최초 데이터 추적용으로 사용됩니다. parseData, build, puValue시에 갱신됩니다. */
			if (this._headers._isExist(columnName) == false) {
				throw new exceptions.IllegalArgumentException("Column named " + columnName + " is not found in DataMap : id " + this.id);
			}
			if (this.getHeader(columnName).getDataType() == tabledata.DataType.EXPRESSION) {
				return this.getValue(columnName);
			}

			let columnIndex: number = this._headers._getIndexFromName(columnName);
			return this._data._getOriginalValue(columnIndex);
		}

		/**
		 * 특정 속성을 설정합니다.
		 * @param attrName	지정할 속성명
		 * @param attrValue	지정할 속성값
		 */
		public setAttr(attrName: string, attrValue: string): void {
			this._attr[attrName] = attrValue;
		}

		/**
		 * 속성값을 반환합니다.
		 * @param attrName	가져올 속성명
		 * @return 입력 받은 속성명의 속성값
		 */
		public getAttr(attrName: string): string {
			return this._attr[attrName];
		}

		/**
		 * 모든 속성명의 배열을 반환합니다.
		 * @return 모든 속성명의 배열
		 */
		public getAttrNames(): string[] {
			return Object.keys(this._attr);
		}

		/**
		 * 모든 속성에 대한 json object를 반환합니다.
		 * @return { [attrName: string]: string } 모든 속성에 대한 key : value 형식의 json object
		 */
		public getAttrs(): { [attrName: string]: string } {
			return _shallowCopyObject(this._attr);
		}

		/**
		 * 입력 받은 columnName에 해당되는 데이터를 String형으로 반환합니다.
		 * 
		 * @param columnName	값을 가져올 column의 columnName
		 * @return 해당 데이터의 String형
		 */
		public getString(columnName: column_name_string): string {
			let value: any = this.getValue(columnName);
			return utils.Util.toString(value);
		}

		/**
		 * 입력 받은 columnName에 해당되는 데이터를 Number형으로 반환합니다.<br>
		 * 값이 string형이어서 강제로 Number형으로 된경우 NaN이 반환된다.
		 * 
		 * @param columnName	값을 가져올 column의 columnName
		 * @return 해당 데이터의 Number형
		 */
		public getNumber(columnName: column_name_string): number {
			let value: any = this.getValue(columnName);
			return utils.Util.toNumber(value);
		}

		/**
		 * 입력 받은 columnName에 해당되는 데이터를 Boolean형으로 반환합니다.
		 * 
		 * @param columnName	값을 가져올 column의 columnName
		 * @return 해당 데이터의 Boolean형
		 */
		public getBoolean(columnName: column_name_string): boolean {
			let value: any = this.getValue(columnName);
			return utils.Util.toBoolean(value);
		}

		/**
		 * 모든 컬럼에 대한 값을 json object로 반환합니다.
		 * 
		 * @return 해당 row index의 row data (key: columnName, value: 해당 value형태의 json object)<br>
		 * 	{[columnName: string]: string | number}
		 */
		public getDatas(): RowConfigInfo {
			let result: RowConfigInfo = {};
			let columnNames: string[] = this.getColumnNames();
			let columnLength: number = columnNames.length;
			for (let j = 0; j < columnLength; j++) {
				result[columnNames[j]] = this.getValue(columnNames[j]);
			}
			return result;
		}


		/**
		 * 입력받은 컬럼 정보에 해당하는 column index를 반환합니다.
		 * @param column	column index를 얻고자 하는 컬럼 정보 (컬럼명 또는 컬럼인덱스)
		 * @return 해당 컬럼 정보의 column index
		 */
		public _getColumnIndex(column: string): number {
			return this._headers._getIndexFromName(column);
		}

		private _validationCheckHeader(headerIns: header.Header): boolean {
			if (headerIns instanceof header.Header) {
				let columnName: string = headerIns.getName();
				if (typeof (columnName) == "string" && columnName != "") {
					return true;
				}
			}
			return false;
		}

		/**
		 * @private
		 * @param columnName 
		 */
		public _getDecimal(columnName: string): foundation.DecimalType {
			if (this.isExistColumn(columnName) == false) {
				throw new exceptions.IllegalArgumentException("Column named " + columnName + " is not found in DataMap : id " + this.id);
			}
			let columnIndex: number = this._getColumnIndex(columnName);
			let header: header.Header = this._getHeaderFromIndex(columnIndex);
			return this._data._getDecimal(header, columnIndex);
		}

		/**
		 * @private
		 */
		_getExpressionOnlyProperty(prop: string): any {
			if (this.isExistColumn(prop)) {
				return this.getValue(prop)
			} else {
				return undefined
			}
		}

	}
}