/// <reference path="./Layout.ts"/>
/// <reference path="../UIControl.ts"/>


namespace cpr.controls.layouts {

	export interface XYPosition {
		/**
		 * 대상 미디어 쿼리
		 */
		media: string;

		/**
		 * 너비
		 */
		width?: string;

		/**
		 * 높이
		 */
		height?: string;

		/**
		 * 상단 위치
		 */
		top?: string;

		/**
		 * 하단 위치
		 */
		bottom?: string;

		/**
		 * 좌측 위치
		 */
		left?: string;

		/**
		 * 우측 위치
		 */
		right?: string;

		/**
		 * 현재 스크린에서 숨김 여부.
		 */
		hidden?: boolean
	}

	/**
	 * 반응형 레이아웃의 레이아웃 컨스트레인트
	 */
	export interface ResponsiveXYLayoutConstraint extends Constraint {
		/**
		 * 화면 크기별 포지션 정보 배열.
		 */
		positions: XYPosition[];
	}

	const DEFAULT_CONSTRAINT: ResponsiveXYLayoutConstraint = { positions: [] };

	export class ResponsiveXYLayout extends AbstractXYLayout<ResponsiveXYLayoutConstraint> {
		private _targetMedia: string = null;
		private _targetMediaName: string = null;


		constructor() {
			super();
			this._initLayout();
		}

		protected override _getType(): LayoutType {
			return LayoutType.RESPONSEIVE_XY_LAYOUT;
		}

		protected _getLayoutShapeStyle() {
			let appinstance: core.AppInstance = this._owner.getAppInstance();
			// let targetMedia: string = appinstance.targetMedia;
			// this._targetMedia = targetMedia;
			this._targetMedia = appinstance.targetMedia;
			this._targetMediaName = appinstance.targetMediaName;

			return {
				position: "relative", // 패딩 적용을 위해 필요.
				left: "0px",
				top: "0px",
				right: "0px",
				bottom: "0px",
				width: "100%",
				height: "100%",
				boxSizing: "content-box",
				minHeight: "inherit",
				minWidth: "inherit",
				overflowX: this.scrollable ? "auto" : this._getOverflowXForNonScroll(),
				overflowY: this.scrollable ? "auto" : this._getOverflowYForNonScroll()
			}
		}

		private xyPositionToStyle(position: XYPosition): { [key: string]: string } {
			let result = _mergeObject(position);
			if (position.hidden) {
				result["display"] = "none";
			}
			delete result["hidden"];
			return result;
		}

		/** @override */
		public _doDecorateChild(context: LayoutDecorationContext<ResponsiveXYLayoutConstraint>): ufc.ControlShape {
			let constraint = context.constraint;
			let controlShape = context.controlShape;
			let xyPosition: XYPosition = this._getXYPosition(constraint);
			if (xyPosition) {
				controlShape.style = _mergeObject(controlShape.style, {
					position: "absolute"
				}, this._getAnimatingProperties(), this.xyPositionToStyle(xyPosition));
			}
			return controlShape;
		}

		protected applyConstraint(index: number, control: UIControl, controlRenderer: ufc.ControlRenderer): ufc.ControlRenderer {
			controlRenderer.addLayoutDecorator(this._createLayoutDecorator(control));
			return controlRenderer;
		}

		/**
		 * @param constraint
		 */
		protected _doUpdateControl(controls: UIControl[]): void {
			controls.forEach((control: UIControl) => {
				control._applyPiece(new ufc.CustomPieceRenderer((renderer: ufc.ControlRenderer) => {
					if (!renderer) {
						return;
					}
					let constraint: ResponsiveXYLayoutConstraint = (this._owner as Container).getConstraint(control) as ResponsiveXYLayoutConstraint; // 항상 최신 Constraints를 반영하도록
					let xyPosition: XYPosition = this._getXYPosition(constraint);

					let layoutStyles = _mergeObject(Layout.EMPTY_LAYOUT_STYLES, xyPosition);
					renderer.updateStyle(null, layoutStyles, true);
				}));
				this._fireChildResizeEvent(control);
			});
		}

		// helper methods
		private _getXYPosition(constraint: ResponsiveXYLayoutConstraint): XYPosition {
			if (!constraint) {
				return null;
			}
			let xyPositions: XYPosition[] = constraint.positions;
			if (!xyPositions) {
				return null;
			}

			if (this._targetMedia || this._targetMediaName) {
				let defaultPosition: XYPosition = null;
				for (let idx: number = 0; idx < xyPositions.length; idx++) {
					let media: string = xyPositions[idx].media;
					if (media == this._targetMedia || media == this._targetMediaName) {
						return _.omit(xyPositions[idx], "media");

					}
					if (media == "default") {
						defaultPosition = _.omit(xyPositions[idx], "media");
					}
				}
				return defaultPosition;
			} else {
				for (let idx: number = 0; idx < xyPositions.length; idx++) {
					let media: string = xyPositions[idx].media;
					if (media == "default") {
						return _.omit(xyPositions[idx], "media");
					}
				}
				return null;
			}
		}

		/** @override */
		protected _compareConstraint(a: ResponsiveXYLayoutConstraint, b: ResponsiveXYLayoutConstraint): boolean {
			if (a.positions.length !== b.positions.length) {
				return false;
			}
			let positionCount = a.positions.length;
			for (let idx = 0; idx < positionCount; idx++) {
				let pA = a.positions[idx];
				let pB = b.positions[idx];

				let eachEquality = pA.media == pB.media
					&& pA.top == pB.top
					&& pA.right == pB.right
					&& pA.bottom == pB.bottom
					&& pA.left == pB.left
					&& pA.width == pB.width
					&& pA.height == pB.height;

				if (!eachEquality) {
					return false;
				}
			}

			return true;
		}

		/** @override */
		public _compareConstraintOrder(a: UIControl, b: UIControl) {
			let boundsA = a.getActualRect();
			let boundsB = b.getActualRect();
			let gapY = boundsA.top - boundsB.top;
			if (gapY !== 0) {
				return gapY;
			}
			return boundsA.left - boundsB.left;
		}

		/** @override */
		public _getDefaultConstraint() {
			return DEFAULT_CONSTRAINT;
		}

		/** @override */
		public _getRenderedLayoutInfo(): RenderedLayoutInfo {
			return {
				layoutNodeName: LayoutConstants.NODE_NAME__LAYOUT,
				scrollingNodeName: LayoutConstants.NODE_NAME__LAYOUT,
				contentPaneNodeName: LayoutConstants.NODE_NAME__CONTENT_PANE,
				offsetIndexForChildren: 0
			}
		}

		public _getAutoSizeType(constraint: ResponsiveXYLayoutConstraint) {
			let xyPosition = this._getXYPosition(constraint);
			if (!xyPosition) {
				return AutoSizeType.none;
			}
			let hasAutoWidth = (xyPosition.width == null || xyPosition.width == "auto") && !(xyPosition.left && xyPosition.right);
			let hasAuthHeight = (xyPosition.height == null || xyPosition.height == "auto") && !(xyPosition.top && xyPosition.bottom);
			if (hasAuthHeight && hasAuthHeight) {
				return AutoSizeType.both;
			} else if (hasAutoWidth) {
				return AutoSizeType.width;
			} else if (hasAuthHeight) {
				return AutoSizeType.height;
			} else {
				return AutoSizeType.none;
			}
		}

	}
}