/// <reference path="../../../events/IEventTarget.ts"/>


namespace cpr.controls.gridpart.layout {

	/**
	 * @private
	 */
	export abstract class IScrollPane implements resources.IDisposable {
		private _region: string;
		private _loc: string;

		private _context: GridContext;
		private _contentView: IGridPartArea;
		private _scrollPaneCluster: ScrollPaneCluster;

		private _disposed: boolean = false;


		constructor(region: string, loc: string, context: GridContext, contentView: IGridPartArea, scrollPaneCluster: ScrollPaneCluster) {
			this._region = region;
			this._loc = loc;
			this._context = context;
			this._contentView = contentView;
			this._contentView._setScrollPane(this);

			scrollPaneCluster._clusterize(this);
			this._scrollPaneCluster = scrollPaneCluster;
		}

		get region(): string {
			return this._region;
		}
		get location(): string {
			return this._loc;
		}
		get owner(): IGridPartArea {
			return this._contentView;
		}
		get context(): GridContext {
			return this._context;
		}
		get nodename(): string {
			return "pane-" + this.region + "-" + this.location;
		}

		get disposed(): boolean {
			return this._disposed;
		}

		abstract createShape(): ufc.ControlShape;
		abstract _getViewportWidth(): number;
		abstract _getViewportHeight(): number;
		abstract _getMaxScrollTop(): number;
		abstract _getMaxScrollLeft(): number;

		// ScrollPaneCluster
		public _getBusScollTop(): number {
			if (this.disposed) {
				return -1;
			}
			return this._scrollPaneCluster._getScrollTop(this.location);
		}
		public _getBusScrollLeft(): number {
			if (this.disposed) {
				return -1;
			}
			return this._scrollPaneCluster._getScrollLeft(this.region);
		}
		public _postScroll(scrollTop: number, scrollLeft: number, e: events.CEvent): void {
			if (this.disposed) {
				return;
			}
			this._scrollPaneCluster._postScroll(this, scrollTop, scrollLeft, e);
		}
		public _postScrollLeft(scrollLeft: number, e: events.CEvent): void {
			if (this.disposed) {
				return;
			}
			this._scrollPaneCluster._postScrollLeft(this, scrollLeft, e);
		}
		public _postScrollTop(scrollTop: number, e: events.CEvent): void {
			if (this.disposed) {
				return;
			}
			this._scrollPaneCluster._postScrollTop(this, scrollTop, e);
		}
		abstract _handleScrollLeft(scrollEvent: events.CScrollEvent): void;
		abstract _handleScrollTop(scrollEvent: events.CScrollEvent): void;
		abstract _getRenderCellRange(): { start: number, end: number };
		abstract _getViewCellRange(): { start: number, end: number };
		abstract _getVScrollbarWidth(): number;

		public dispose(): void {
			if (this._scrollPaneCluster) {
				this._scrollPaneCluster._diclusterize(this);
			}
			this._region = null;
			this._loc = null;
			this._context = null;
			this._contentView = null;
			this._scrollPaneCluster = null;

			this._disposed = true;
		}
	}

	/**
	 * @private
	 * 브라우저에서 실제 스크롤을 사용했을 때는 레이아웃 계산이 일어나지 않고 바로 그리기로 넘어가서 태그양이 많아도 빨리 그려지는데 반해
	 * 스타일요소(style.top)을 변경하여 가상스크롤을 구현했을 때는 브라우저에서 레이아웃을 재계산하기 때문에 태그양이 많아지면 그만큼 느려짐.
	 * 이 문제를 해결하기 위해서는 실제 스크롤을 만들어 놓고 scrollTop을 조정하는 식의 가상스크롤 적용함.
	 */
	export class ScrollPane extends IScrollPane {
		private _scrollStrategy: ActiveScrollStrategy;


		constructor(region: string, loc: string, context: GridContext, contentView: IGridPartArea, scrollPaneCluster: ScrollPaneCluster) {
			super(region, loc, context, contentView, scrollPaneCluster);

			// ScrollStrategy
			if (GRIDREGION.MIDDLE == loc) {
				// middle
				if (context._isGrouping() == true) {
					this._scrollStrategy = new RowGroupBufferedScrollStrategy(this, context);
				} else {
					this._scrollStrategy = new RowBufferedScrollStrategy(this, context);
				}
			} else {
				// top, bottom
				this._scrollStrategy = new ActiveScrollStrategy(this, context);
			}

			this._scrollStrategy._setDecorator(contentView);
		}

		public _getViewportWidth(): number {
			return this._scrollStrategy._getViewportWidth();
		}
		public _getViewportHeight(): number {
			return this._scrollStrategy._getViewportHeight();
		}

		public _getViewportScrollTop(): number {
			return this._scrollStrategy.viewportscrolltop;
		}
		public _getViewportScrollLeft(): number {
			return this._scrollStrategy.viewportscrollleft;
		}

		public _getMaxScrollTop(): number {
			return this._scrollStrategy._getRenderedMaxScrollTop();
		}
		public _getMaxScrollLeft(): number {
			return this._scrollStrategy._getRenderedMaxScrollLeft();
		}

		public _getNewestMaxScrollTop(): number {
			return this._scrollStrategy._getNewestMaxScrollTop();
		}
		public _getNewestMaxScrollLeft(): number {
			return this._scrollStrategy._getNewestMaxScrollLeft();
		}

		public _getRenderStartRow(): number {
			return this._scrollStrategy._getRenderStartRow();
		}
		public _getRenderEndRow(): number {
			return this._scrollStrategy._getRenderEndRow();
		}

		public _readyForRedraw(): void {
			this._scrollStrategy._readyForRedraw();
		}
		public _initScrollTop(scrollTop: number): void {
			this._scrollStrategy._initScrollTop(scrollTop);
		}
		public _initScrollLeft(scrollLeft: number): void {
			this._scrollStrategy._initScrollLeft(scrollLeft);
		}

		/* createShape start */
		public createShape(): ufc.ControlShape {
			// 각 영역을 그릴 때 suppress 정보 갱신 체크
			this.context._resetSuppressInfoIfNeeded(false);

			let shape: ufc.ControlShape = this._scrollStrategy._createScrollPane();

			return shape;
		}
		/* createShape end */

		public _handleScrollLeft(scrollEvent: events.CScrollEvent): void {
			this._scrollStrategy._handleScrollLeft(scrollEvent);
		}
		public _handleScrollTop(scrollEvent: events.CScrollEvent): void {
			this._scrollStrategy._handleScrollTop(scrollEvent);
		}

		public _jumpPage(e: events.CUIEvent): void {
			this._scrollStrategy._onJumpPage(e);
		}

		public _jumpCellIndex(cellIndex: number): void {
			this._scrollStrategy._onJumpCellIndex(cellIndex);
		}
		public _jumpRowGroupCellIndex(groupCondition: string, vloc: string, cellIndex: number): void {
			this._scrollStrategy._onJumpRowGroupCellIndex(groupCondition, vloc, cellIndex);
		}

		public _getRenderCellRange(): { start: number, end: number } {
			// TODO 그룹핑 된 경우를 고려하여 한 번만 계산하도록 cell의 좌표계 범위가 아닌 좌표계 범위 내의 cell의 index를 리턴하는 방식으로 수정하여 성능을 개선할 수 있음.
			let wholeRenderingMode: boolean | string = this.context._getWholeRenderingMode();
			if (wholeRenderingMode !== false || this._scrollStrategy instanceof BufferedScrollStrategy === false) {
				// ActiveScrollStrategy // TODO 전략쪽으로 이동
				let cellRange: { start: number, end: number } = {
					start: 0, end: Number.MAX_VALUE
				};
				return cellRange;
			} else {
				return this._getViewCellRange();
			}
		}

		public _getViewCellRange(): { start: number, end: number } {
			let viewportWidth: number = this._getViewportWidth();
			let scrollLeft: number = this._getBusScrollLeft();
			scrollLeft = scrollLeft < 0 ? 0 : scrollLeft;

			let cellRange: { start: number, end: number } = {
				start: scrollLeft, end: scrollLeft + viewportWidth
			};
			return cellRange;
		}

		public _getVScrollbarWidth(): number {
			return this._scrollStrategy._getVScrollbarWidth();
		}
	}
}