/// <reference path="../i18n/i18n.ts" />


namespace cpr.expression {
	/**
	 * 표현식에서 사용할 수 있는 함수 모음입니다.
	 * 이 API들은 스크립트 호출로는 사용할 수 없고, 표현식 내에서만 호출 할 수 있습니다.
	 * 
	 * @noinstance
	 */
	export class BuiltInProperties {
		/**
		 * 현재 locale을 반환합니다.
		 * @returns 
		 */
		get currentLanguage() {
			return I18N.INSTANCE.currentLanguage;
		}
		/**
		 * 현재 언어에 맞는 key에 대한 message를 반환합니다.
		 * @param key 다국어 키
		 */
		i18n(key: string): string

		/**
		 * 현재 언어에 맞는 key에 대한 message를 반환합니다. 다국어에서 ${name}으로 지정된 문자열을 치환하여 출력합니다.
		 * @param key 다국어 키
		 * @param locals 다국어 변수 치환 값들
		 */
		i18n(key: string, locals: { [key: string]: string }): string
		i18n(key: string, valueOrLocals?: any) {
			return I18N.INSTANCE.message(key, valueOrLocals);
		}


		/**
		 * 넘버 타입으로 포매팅합니다.<br>
		 * 's': 음수 / 양수문자<br>
		 * '0': 숫자만(value가 없는 경우 0값이 표시)<br>
		 * '#': 소수점 기준으로 정수부 또는 소수부의 마지막에 있으면 무한으로 입력 가능하며, ","가 있는 경우 소수점에서 처음 찾은 위치의 자리수 만큼 반복해서 ","가 입력됩니다.<br>
		 * <pre><code>
		 * formatNumber("s#,##0.00", value)
		 * formatNumber("s#,##0", value)
		 * formatNumber("s#,##0.00", value, ",", ".")
		 * formatNumber("s#,##0", value, ",", ".")
		 * </code></pre>
		 * @param format 포맷
		 * @param num 포매팅할 숫자
		 * @param digitGroupSeparator 정수부 구분자
		 * @param decimalSeparator 소수부 구분자
		 * @return string
		 */
		formatNumber(format: string, num: number, digitGroupSeparator?: string, decimalSeparator?: string): string;

		/**
		 * 넘버 타입으로 포매팅합니다.<br>
		 * 's': 음수 / 양수문자<br>
		 * '0': 숫자만(value가 없는 경우 0값이 표시)<br>
		 * '#': 소수점 기준으로 정수부 또는 소수부의 마지막에 있으면 무한으로 입력 가능하며, ","가 있는 경우 소수점에서 처음 찾은 위치의 자리수 만큼 반복해서 ","가 입력됩니다.<br>
		 * <pre><code>
		 * formatNumber("s#,##0.00", value)
		 * formatNumber("s#,##0", value)
		 * formatNumber("s#,##0.00", value, ",", ".")
		 * formatNumber("s#,##0", value, ",", ".")
		 * </code></pre>
		 * @param format 포맷
		 * @param text 포매팅할 문자열
		 * @param digitGroupSeparator 정수부 구분자
		 * @param decimalSeparator 소수부 구분자
		 * @return string
		 */
		formatNumber(format: string, text: string, digitGroupSeparator?: string, decimalSeparator?: string): string;
		formatNumber(format: string, arg: number | string, digitGroupSeparator?: string, decimalSeparator?: string): string {
			if (arg && typeof arg != "string" && typeof arg != "number") {
				throw new cpr.exceptions.IllegalArgumentException();
			}
			if (typeof arg == "number") {
				arg = arg.toString();
			}
			return new foundation.NumberFormatter(format, { decimalSeparator: decimalSeparator, digitGroupSeparator: digitGroupSeparator }).transform(arg);
		}

		/**
		 * 텍스트 타입으로 포매팅합니다.<br>
		 * '?' 포맷 문자를 제공합니다. 예약된 문자를 사용하려면 '\\'(back slash)를 문자 앞에 작성해야 합니다.
		 * <pre><code>formatText("???-???", value)</code></pre>
		 * @param foramt 포맷
		 * @param text 포매팅할 문자열
		 * @return string
		 */
		formatText(format: string, text: string): string {
			return new foundation.TextFormatter(format).transform(text);
		}
		/**
		 * 날짜 타입으로 포매팅합니다.(parseFormat 기본 값: 'YYYYMMDDHHmmssSSS')<br>
		 * <pre><code>
		 * formatDate("YYYY-MM-DD", value)
		 * formatDate("YYYY-MM-DD", value, "YYYYMMDDHHmmssSSS")
		 * </code></pre><br>
		 * <b>format 종류</b><br>
		 * YYYY: 4자리 연도 -> 0001...9999<br>
		 * YY: 2자리 연도 -> 00...99<br>
		 * MM: 두자리 월 -> 01...12<br>
		 * M: 월 -> 1...12<br>
		 * DD: 두자리 날짜. 01...31<br>
		 * D: 날짜 1...31<br>
		 * MMM: 짧은 월 명 ->  Jan<br>
		 * MMMM: 월 명 -> January<br><br>
		 * ddd: 짧은 요일명 -> 월<br>
		 * dddd: 긴 요일 명 -> 월요일<br>
		 * h: 시간 -> 1...12<br>
		 * hh: 시간 -> 01...12<br>
		 * H: 시간 -> 0...23<br>
		 * HH: 시간 -> 00...23<br>
		 * m: 분 -> 0...59<br>
		 * mm: 분 -> 00... 59<br>
		 * s: 초 -> 0...59<br>
		 * ss: 초 -> 00...59<br>
		 * w: 해당 년의 주차-> 1 12<br>
		 * ww: 해당 년의 주차-> 01 05 12<br>
		 * A: AM PM<br>
		 * a: am pm
		 * @param format 포맷
		 * @param text 포매팅할 문자열
		 * @param parseFormat 텍스트 분석하는 포맷(기본값:'YYYYMMDDHHmmssSSS')
		 * @return string
		 */
		formatDate(format: string, text: string, parseFormat?: string): string;

		/**
		 * 날짜 타입으로 포매팅합니다.<br>
		 * <pre><code>
		 * formatDate("YYYY-MM-DD", date)
		 * </code></pre><br>
		 * <b>format 종류</b><br>
		 * YYYY: 4자리 연도 -> 0001...9999<br>
		 * YY: 2자리 연도 -> 00...99<br>
		 * MM: 두자리 월 -> 01...12<br>
		 * M: 월 -> 1...12<br>
		 * DD: 두자리 날짜. 01...31<br>
		 * D: 날짜 1...31<br>
		 * MMM: 짧은 월 명 ->  Jan<br>
		 * MMMM: 월 명 -> January<br><br>
		 * ddd: 짧은 요일명 -> 월<br>
		 * dddd: 긴 요일 명 -> 월요일<br>
		 * h: 시간 -> 1...12<br>
		 * hh: 시간 -> 01...12<br>
		 * H: 시간 -> 0...23<br>
		 * HH: 시간 -> 00...23<br>
		 * m: 분 -> 0...59<br>
		 * mm: 분 -> 00... 59<br>
		 * s: 초 -> 0...59<br>
		 * ss: 초 -> 00...59<br>
		 * w: 해당 년의 주차-> 1 12<br>
		 * ww: 해당 년의 주차-> 01 05 12<br>
		 * A: AM PM<br>
		 * a: am pm
		 * @param format 포맷
		 * @param date 포매팅할 Date객체
		 * @return string
		 */
		formatDate(format: string, date: Date): string;
		formatDate(format: string, arg: any, parseFormat?: string): string {
			if (arg instanceof Date) {
				return new foundation.DateFormatter(format).transform(arg);
			}
			return new foundation.DateFormatter(format, { parseFormat: parseFormat }).transform(arg);
		}
	}
}