namespace cpr {
	type Disposer = {
		dispose(): void
	};

	type Subscription<T> = {
		/** 해당 주제 이벤트 발생시 통지될 콜백 함수 */
		listener: (e: T) => any;

		/** 이벤트 통지 옵션 */
		options: SubscriptionOptions
	};

	type SubscriptionOptions = {
		/** 통보가 콜백될 때 this 문맥 */
		thisArg?: any,
		/** 해당 주제에 대해 1회만 통보 받을 것인지 여부 */
		once?: boolean
	};

	type EventEmitterOptions = {
		/**
		 * 해당 주제에 대한 첫 관심 리스너가 추가되었을 때 수행할 동작을 지시합니다.
		 */
		onFirstSubscription?: () => void,

		/**
		 * 해당 주제에 대한 관심 리스너가 모두 없어진 경우에 수행할 동작을 지시합니다.
		 */
		onEmptified?: () => void
	}

	class EventEmitter<T> {
		_subscriptions: Subscription<T>[] = [];
		_options: EventEmitterOptions;

		/**
		 * 구독자를 추가합니다.
		 */
		readonly subscribe: (listener: (e: T) => any, options?: SubscriptionOptions) => Disposer = this._subscribe.bind(this);

		constructor(options: EventEmitterOptions = {}) {
			this._options = options;
		}

		private _onEmptified() {
			this._options.onEmptified?.call(this);
		}

		/**
		 * 모든 구독자를 제거 합니다.
		 */
		public unsubscribeAll(): void {
			let hadListener = _isNullOrEmpty(this._subscriptions) === false;
			this._subscriptions = [];
			if (hadListener) {
				this._onEmptified();
			}
		}

		private _subscribe(listener: (e: T) => any, options: SubscriptionOptions = { once: false }): Disposer {
			let entry: Subscription<T> = {
				listener,
				options
			};

			this._subscriptions.push(entry);
			if (this._subscriptions.length === 1) {
				this._options.onFirstSubscription?.call(this);
			}

			return {
				dispose: () => {
					let idx = this._subscriptions.indexOf(entry);
					if (idx >= 0) {
						this._subscriptions.splice(idx, 1);
					}
					if (this._subscriptions.length === 0) {
						this._onEmptified();
					}
				}
			}
		}

		/**
		 * 구독자들에게 이벤트를 전파합니다.
		 * @param event 전파할 이벤트.
		 */
		fire(event: T): void {
			for (let each of this._subscriptions) {
				try {
					each.listener.call(each.options.thisArg, event);
				} catch (error) {
					console.error(error);
				}

			}
			this._subscriptions = this._subscriptions.filter(it => it.options.once === false);
		}
	}

	export function _createEmitter<Type>(options: EventEmitterOptions = {}): EventEmitter<Type> {
		return new EventEmitter<Type>(options);
	}
}