namespace cpr.data {
	/** 
	 * @private
	 */
	export class CUDRowInfo {

		private _insertRows: tabledata.RowData[];
		private _updateRows: tabledata.RowData[];
		private _deleteRows: tabledata.RowData[];

		constructor(dataTable: DataTable) {
			this._insertRows = [];
			this._updateRows = [];
			this._deleteRows = [];

			/* HIST:CHO00 RowStateChange */
			dataTable._addInternalEventListener(events.DataEventType._ROWSTATE_CHANGE, (e: events.CDataEvent) => {
				this._rowstateChange(e.beforeState, e.rowData as any);
			});
		}
		/**
		 * @private
		 */
		public _clear(): void {
			this._insertRows = null;
			this._updateRows = null;
			this._deleteRows = null;
			this._insertRows = [];
			this._updateRows = [];
			this._deleteRows = [];
		}
		/**
		 * @private
		 * @param rowState 
		 * @param row 
		 */
		public _addRow(rowState: tabledata.RowState, row: tabledata.RowData): void {
			if (rowState == tabledata.RowState.INSERTED) {
				this._addInsertRow(row);
			} else if (rowState == tabledata.RowState.UPDATED) {
				this._addUpdateRow(row);
			} else if (rowState == tabledata.RowState.DELETED) {
				this._addDeleteRow(row);
			}
		}
		private _addInsertRow(row: tabledata.RowData): void {
			this._insertRows[this._insertRows.length] = row;
		}
		private _addUpdateRow(row: tabledata.RowData): void {
			this._updateRows[this._updateRows.length] = row;
		}
		private _addDeleteRow(row: tabledata.RowData): void {
			this._deleteRows[this._deleteRows.length] = row;
		}

		/**
		 * @private
		 */
		public _getInsertRowCount(): number {
			return this._insertRows.length;
		}
		/**
		 * @private
		 */
		public _getUpdateRowCount(): number {
			return this._updateRows.length;
		}
		/**
		 * @private
		 */
		public _getDeleteRowCount(): number {
			return this._deleteRows.length;
		}
		/**
		 * @private
		 */
		public _getInsertRows(): tabledata.RowData[] {
			return this._insertRows;
		}
		/**
		 * @private
		 */
		public _getUpdateRows(): tabledata.RowData[] {
			return this._updateRows;
		}
		/**
		 * @private
		 */
		public _getDeleteRows(): tabledata.RowData[] {
			return this._deleteRows;
		}
		/**
		 * @private
		 * @param rowState 
		 * @param row 
		 */
		public _deleteRow(rowState: tabledata.RowState, row: tabledata.RowData): void {
			let rowIndex: number;
			if (rowState == tabledata.RowState.INSERTED) {
				rowIndex = this._insertRows.indexOf(row);
				this._insertRows.splice(rowIndex, 1);

			} else if (rowState == tabledata.RowState.UPDATED) {
				rowIndex = this._updateRows.indexOf(row);
				this._updateRows.splice(rowIndex, 1);

			} else if (rowState == tabledata.RowState.DELETED) {
				rowIndex = this._deleteRows.indexOf(row);
				this._deleteRows.splice(rowIndex, 1);

			}
		}

		/* HIST:CHO00 RowStateChange */
		private _rowstateChange(beforeState: tabledata.RowState, rowData: tabledata.RowData): void {
			let currentState: tabledata.RowState = rowData.state;
			// 기존에 상태 배열에서 제거
			this._deleteRow(beforeState, rowData);

			// 현재 상태 배열에 추가
			this._addRow(currentState, rowData);
		}

	}
}