		/**
		 * HTML Text Node 로 사용하기에 적합한 Text로 인코딩하여 결과를 리턴합니다.
		 * @param text 인코딩할 Text
		 * @returns 인코딩된 Text
		 */
		public static encodeForHTML(text: string): string {
			if (text) {
				let encodedText: string = HTMLEncoder._encode(HTMLEncoder._IMMUNE_HTML, text);
				return encodedText;
			}
			return "";
		}

		/**
		 * HTMLAttribute로 사용하기에 적합한 Text로 인코딩하여 결과를 리턴합니다.
		 * @param text 인코딩할 Text
		 * @returns 인코딩된 Text
		 */
		public static encodeForHTMLAttribute(text: string): string {
			if (text) {
				let encodedText: string = HTMLEncoder._encode(HTMLEncoder._IMMUNE_HTMLATTR, text);
				return encodedText;
			}
			return "";
		}

		static _encode(imuune: string[], text: string): string {
			let out: string[] = [];
			for (let i: number = 0; i < text.length; i++) {
				let ch: string = text.charAt(i);
				if (i + 1 < text.length && this._checkSurrogatePair(ch, text.charAt(i + 1))) {
					i++;
					out[out.length] = ch + text.charAt(i);
				} else {
					out[out.length] = HTMLEncoder._encodeCharacter(imuune, ch);
				}
			}
			return out.join("");
		}

		/**
		 * 이모지 문자를 나타내는 써로게잍트 페어를 체크합니다.
		 * @param ch1 
		 * @param ch2 
		 * @returns 
		 */
		static _checkSurrogatePair(ch1: string, ch2: string): boolean {
			// 써로게이트 조합으로 하이 써로게이트 /[\uD800-\uDBFF]/ ,로우 써로게이트 /[\uDC00-\uDFFF]/ 구분함.
			return /[\uD800-\uDBFF]/.test(ch1) && /[\uDC00-\uDFFF]/.test(ch2);
		}

		static _encodeCharacter(imuune: string[], ch: string): string {
			if (imuune.indexOf(ch) != -1) {
				return ch;
			}

			let cc: number = ch.charCodeAt(0);
			if ((cc <= 0x1f && ch != '\t' && ch != '\n' && ch != '\r') || (cc >= 0x7f && cc <= 0x9f) || ch == ' ') {
				return " ";
			}

			let entityName: string = HTMLEncoder._characterToEntityMap[String(cc)];
			if (entityName != null) {
				return entityName + ";";
			}

			return ch;
		}

