namespace cpr {
	/**
	 * @param str 
	 * @returns 
	 */
	export function _getSymbols(str: string): string[] {
		// IE RegularExpression u 옵션이 지원하지 않아 아래의 함수를 사용합니다.
		// 출처 : https://mathiasbynens.be/notes/javascript-unicode
		let index = 0;
		let length = str.length;
		let output = [];

		for (; index < length - 1; ++index) {
			let charCode = str.charCodeAt(index);
			if (charCode >= 0xD800 && charCode <= 0xDBFF) {
				charCode = str.charCodeAt(index + 1);
				if (charCode >= 0xDC00 && charCode <= 0xDFFF) {
					output.push(str.slice(index, index + 2));
					++index;

					if (index == str.length - 1) {
						return output;
					}
					continue;
				}
			}
			output.push(str.charAt(index));
		}
		output.push(str.charAt(index));
		return output;
	}

	/**
	 * 텍스트의 길이를 가져옵니다.
	 * @param lengthUnit 길이 유닛
	 * @param text 텍스트
	 * @param maxlength 최대 길이(옵션)
	 */
	export function _getByteLength(lengthUnit: "char" | "ascii" | "utf8", text: string, maxlength?: number): { byte: number, maxindex: number, inputMaxLength: number } {
		let byte: number = 0, // 최대 길이에 대한 텍스트 사이즈
			i: number = 0, code: any,
			maxindex: number = 0, // 텍스트가 최대 길이에 도달한 인덱스(길이)
			inputMaxLength: number = 0;// 인풋박스의 maxlength 사용될 값
		if (text.length == 0) {
			return { byte: byte, maxindex: maxindex, inputMaxLength: inputMaxLength };
		}

		let getInputLength = (char: string) => {
			if (_isIE()) {
				return 1;
			}
			return char.length;
		}

		// IE RegularExpression u 옵션이 지원하지 않습니다.
		// let arr: string[] = text.match(/[\u{0}-\u{10FFFF}]/gu);
		let arr: string[] = _getSymbols(text);

		if (lengthUnit == "ascii") {
			for (byte = 0, i = 0; i < arr.length; i++) {
				code = arr[i].charCodeAt(0);
				byte += code >> 7 ? 2 : 1;

				if (byte <= maxlength) {
					maxindex = i + 1;
					inputMaxLength += getInputLength(arr[i]);
				}
			}
		} else if (lengthUnit == "utf8") {
			// IE를 제외한 브라우저에서 TextEncoder를 사용하여 UTF-8의 length를 계산할 수 있음
			for (byte = 0, i = 0; i < arr.length; i++) {
				if (arr[i].charCodeAt(0) > 127) {
					try {
						code = '0x' + encodeURI(arr[i]).replace(/%/g, '');
					} catch (e) {
						if (e instanceof URIError) {
							code = arr[i].charCodeAt(0);
						} else {
							console.error(e);
						}
					}
				} else {
					code = arr[i].charCodeAt(0);
				}
				code > 0xFFFFFF ? byte += 4 : byte += code >> 11 ? 3 : code >> 7 ? 2 : 1;

				if (byte <= maxlength) {
					maxindex = i + 1;
					inputMaxLength += getInputLength(arr[i]);
				}
			};
		} else if (lengthUnit == "char") {
			byte = text.length;
			if (_isIE()) {
				//IE에서 maxlength 설정 시 텍스트 길이 측정 시 length가 아닌 1개의 문자로 체크(이모지 문자에서 차이 발생). 크롬의 경우 length 값으로 체크하여 maxlengh에 대한 구분이 필요하여 처리
				let tempLength = 0;
				arr.some((each: string) => {
					tempLength += each.length;
					if (tempLength > maxlength) {
						return true;
					}
					inputMaxLength++;
					return false;
				});
			} else {
				inputMaxLength = maxlength;
			}
			if (maxlength != null) {
				maxindex = maxlength;
			}
		}

		return { byte: byte, maxindex: maxindex, inputMaxLength: inputMaxLength };
	}
}