/// <reference path="./Layout.ts" />

namespace cpr.controls.layouts {
	/**
	 * 레이아웃 내에 추가될 자식될 특성에 대한 정보를 제공합니다.
	 */
	export interface OrderedInsertionReference {
		/**
		 * 삽입 인덱스
		 */
		index: number,

		/**
		 * 시각적으로 삽입 지점 이전에 위치하는 컨트롤
		 */
		previousSibiling: UIControl,

		/**
		 * 시각적으로 삽입 지점 이후에 위치하는 컨트롤
		 */
		nextSibiling: UIControl
	}

	/**
	 * 자식들의 순서가 레이아웃에 영향을 주는 레이아웃의 추상 정의 입니다.
	 */
	export abstract class OrderedLayout<T extends Constraint> extends Layout<T> {
		/** 
		 * 마우스 좌표(뷰포트 기준)을 이용하여 레이아웃 내에 자식 컨트롤을 추가하는 경우, 해당 지점에 대한 삽입 참조 정보를 얻습니다.
		 * @param location 포인터 위치(뷰포트 기준)
		 */
		public abstract getInsertionReference(location: geometry.Point): OrderedInsertionReference

		/**
		 * 평범하게 배치되어 있는 자식 컨트롤들을 시각적 순서대로 모두 얻습니다.
		 * 평범함이란 플로팅 상태가 아니며 숨겨지지 않는 경우를 의미합니다.
		 */
		protected _getOrderedChildren(): UIControl[] {
			let owner = this._getOwner();
			if (!owner || owner.disposed) {
				return [];
			}

			return owner.getChildren().filter(it => {
				return it.visible && !_isManualConstraint(owner.getConstraint(it));
			});
		}

		/**
		 * 보여지는 자식인지 여부를 반환합니다.
		 * @param control 
		 * @returns 
		 */
		_isVisibleLayoutChild(control: UIControl) {
			if (!control || control.disposed) {
				return false;
			}
			let constraint = this._owner.getConstraint(control);
			if (constraint == null) {
				return false;
			}
			if (_isManualConstraint(constraint)) {
				return false;
			}
			if (control instanceof VisibleUIControl && control.visible == false) {
				return false;
			}
			return true;
		}

		/**
		 * 첫 번째 보여지는 자식을 반환합니다.
		 * @returns 
		 */
		_getFirstVisibleLayoutChild(): UIControl {
			if (core.DeferredUpdateManager.INSTANCE._isRendering()) {
				return this._getFrameCache().get("first-visible-layout-child", () => {
					return _findFirst(this._owner.getChildren(), it => this._isVisibleLayoutChild(it))
				});
			}
			else {
				return _findFirst(this._owner.getChildren(), it => this._isVisibleLayoutChild(it))
			}
		}

		/**
		 * 마지막으로 보여지는 자식을 반환합니다.
		 * @returns 
		 */
		_getLastVisibleLayoutChild(): UIControl {
			if (core.DeferredUpdateManager.INSTANCE._isRendering()) {
				return this._getFrameCache().get("last-visible-layout-child", () => {
					return _findLast(this._owner.getChildren(), it => this._isVisibleLayoutChild(it))
				});
			}
			else {
				return _findLast(this._owner.getChildren(), it => this._isVisibleLayoutChild(it))
			}
		}

		/**
		 * 가장자리 판정이 달라진 자식을 다시 그립니다.
		 * @param control 다시 그릴 컨트롤.
		 * @param except 이미 다시 그려지는 것이 확정된 컨트롤. 중복 요청을 피하기 위해 제외합니다.
		 */
		private _redrawEdgeChild(control: UIControl, except: UIControl) {
			if (control == null || control === except || control.disposed) {
				return;
			}
			control.redraw();
		}

		/**
		 * @override
		 * 자식의 레이아웃 흐름 참여 여부가 바뀌면 첫/마지막 자식이 달라질 수 있으므로 판정이 달라진 자식들을 다시 그립니다.
		 *
		 * 가장자리 유틸리티 클래스(플로우 레이아웃의 cl-first/cl-last, 버티컬 레이아웃의 cl-first-row/cl-last-row)는
		 * 자식을 그리는 시점의 판정으로 부여되는데, 참여 여부가 바뀐 자식은 자기 자신만 다시 그려지므로
		 * 직전에 가장자리였던 형제에 클래스가 그대로 남는다. 자식 추가/삭제 경로의 _onOCPRFinish 와 같은
		 * 보정을 가시성 변경(release-test-project#10339)과 컨스트레인트 전환(release-test-project#11189)
		 * 경로에도 적용한다.
		 */
		_onChildLayoutParticipationChanged(child: UIControl, wasParticipating: boolean) {
			let owner = this._owner;
			if (!owner || owner.disposed || child == null || child.getParent() !== owner) {
				return;
			}

			// 참여 여부가 실제로 뒤집힌 경우에만 가장자리가 달라질 수 있다.
			// 플롯된 채로 가시성만 바뀐 경우처럼 양쪽 모두 비참여인 상황이 여기서 걸러진다.
			let isParticipating = this._isVisibleLayoutChild(child);
			if (wasParticipating === isParticipating) {
				return;
			}

			// 이 시점에는 변경이 이미 반영되어 있으므로, 변경 대상 자식의 참여 여부만 가정해 이전/현재 가장자리를 구한다.
			let children = owner.getChildren();
			let asParticipating = (assumption: boolean) => {
				return (it: UIControl) => {
					return it === child ? assumption : this._isVisibleLayoutChild(it);
				};
			};

			let oldFirstChild = _findFirst(children, asParticipating(wasParticipating));
			let newFirstChild = _findFirst(children, asParticipating(isParticipating));
			if (oldFirstChild !== newFirstChild) {
				this._redrawEdgeChild(oldFirstChild, child);
				this._redrawEdgeChild(newFirstChild, child);
			}

			let oldLastChild = _findLast(children, asParticipating(wasParticipating));
			let newLastChild = _findLast(children, asParticipating(isParticipating));
			if (oldLastChild !== newLastChild) {
				this._redrawEdgeChild(oldLastChild, child);
				this._redrawEdgeChild(newLastChild, child);
			}
		}

		_onOCPRInit(session: OCPRSession) {
			session._putData("old-first-child", this._getFirstVisibleLayoutChild());
			session._putData("old-last-child", this._getLastVisibleLayoutChild());
		}

		_onOCPRFinish(session: OCPRSession) {
			if (session._isRendered() === false) {
				return;
			}

			let oldFirstChild: UIControl = session._getData("old-first-child");
			let oldLastChild: UIControl = session._getData("old-last-child");

			let currentFirstChild = this._getFirstVisibleLayoutChild();
			let currentLastChild = this._getLastVisibleLayoutChild();

			if (oldFirstChild !== currentFirstChild) {
				session._requestRender(oldFirstChild);
				session._requestRender(currentFirstChild);
			}

			if (oldLastChild !== currentLastChild) {
				session._requestRender(oldLastChild);
				session._requestRender(currentLastChild);
			}
		}
	}
}