/**
 * 이 파일은 빌드 순서에서 가장 처음에 위치 합니다.
 */
namespace cpr {
	let _platformInitQueue: (() => void)[] = [];
	let _platformDidInitialized = false;

	/**
	 * 플랫폼이 초기화된 직후 수행할 작업을 예약합니다.
	 * 플랫폼이 이미 초기화 된 경우 즉시 실행 됩니다.
	 * @param task 예약할 작업.
	 */
	export function _registerPlatformInitTask(task: () => void) {
		if (_platformDidInitialized) {
			task();
		} else {
			_platformInitQueue.push(task);
		}
	}

	/**
	 * HTML 돔 파싱이 끝난 뒤 실행할 작업을 예약 합니다.
	 * 이미 완료된 경우 즉시 트리거 됩니다.
	 * @param task 예약할 작업.
	 */
	export function _onDomContentReady(task: () => void) {
		if (document.readyState == "complete") {
			task();
		}
		else {
			let callback = () => {
				document.removeEventListener("DOMContentLoaded", callback);
				task();
			};
			document.addEventListener("DOMContentLoaded", callback);
		}
	}

	/**
	 * 플랙폼 초기화시 {@link _registerPlatformInitTask}로 등록된 작업들을 실행.
	 */
	(() => {
		let platformInitialzation = () => {
			document.removeEventListener("eb-ready", platformInitialzation);
			_platformInitQueue.splice(0).forEach(task => {
				utils.tryCatch({
					do: task,
					catch: e => {
						console.error(e);
					}
				});
			});
			_platformDidInitialized = true;
		};

		document.addEventListener("eb-ready", platformInitialzation);
	})();

}