/// <reference path="./DOMEventWrapper.ts" />

namespace cpr.events {
	/**
	 * TreeCell 이벤트 유형
	 */
	export class TreeCellEventType {
		/**
		 * TreeCell 노드가 확장되기 전에 발생하는 이벤트.
		 */
		public static readonly NODE_OPEN: string = "node-open";
		/**
		 * TreeCell 노드가 닫히기 전에 발생하는 이벤트.
		 */
		public static readonly NODE_CLOSE: string = "node-close";
		/**
		 * TreeCell의 체크 박스를 체크되기 전에 발생하는 이벤트.
		 */
		public static readonly ITEM_CHECK: string = "item-check";
		/**
		 * TreeCell의 체크 박스를 체크 해제되기 전에 할때 이벤트.
		 */
		public static readonly ITEM_UNCHECK: string = "item-uncheck";
	}

	export interface CTreeCellEventOptions extends CEventOption {
		/**
		 * TreeCell 이벤트 유형
		 */
		type?: string;
	}

	/**
	 * TreeCell 내부 변경 시 발생하는 이벤트.
	 */
	export class CTreeCellEvent extends CEvent {

		constructor(type: string, options?: CTreeCellEventOptions) {
			super(type, options);
		}

		/**
		 * 이벤트가 발생한 행의 GridRowGroup을 반환합니다.
		 * @readonly
		 */
		get item(): cpr.controls.provider.GridRowGroup {
			return this._getOption("item");
		}


	}
}