/// <reference path="../expression/EvaluationContext.ts" />
namespace cpr.controls {
	/**
	 * 아이템 드래그 모드.
	 */
	export enum ItemDraggingMode {
		/**
		 * 아이템 드래그를 허용하지 않음.
		 */
		NONE = "none",

		/**
		 * 컨트롤 내에서만 드래그가 가능함.
		 */
		INTERNAL = "internal",

		/**
		 * 다른 컨트롤로도 드래그가 가능함.
		 */
		GLOBAL = "global"
	}

	/**
	 * Item.
	 * label, value를 갖는 아이템 클래스. 리스트, 콤보박스,체크박스 그룹, 라디오 버튼 등에서 사용됩니다.
	 */
	export class Item implements bind.BindablePropertiesOwner, expression.EvaluationContext {

		private _dataAccessor: ItemDataAccessor;
		/**
		 * item을 소유한 컨트롤의 바인드 컨텍스트(임시 변수)
		 */
		public _ownerBindContext: any;
		/**
		 * 앱속성을 가져오기 위한 룩업 프로바이더(임시 변수)
		 */
		public _expressionIDLookupProvider: expression._ILookupProvider_;

		/**
		 * 데이터셋에 바인딩된 아이템의 경우 Row를 반환합니다. 없는 경우 null을 반환합니다.
		 */
		public get row(): data.Row {
			return this._dataAccessor._getRow();
		}

		/**
		 * 아이템을 생성합니다.
		 * @param label 아이템의 display되는 text
		 * @param value 아이템의 값
		 */
		constructor(label: string, value: string);
		/**
		 * @private
		 * @param row 
		 * @param itemSetInfo 
		 */
		constructor(row: data.IDataRow, itemSetInfo: any);
		/**
		 * @private
		 * @param accessor 
		 */
		constructor(accessor: ItemDataAccessor);
		constructor(arg1: any, arg2?: any) {

			if (arg1 instanceof ItemDataAccessor) {
				this._dataAccessor = arg1;
			} else if (arg1 instanceof data.Row && arg2 != null) {
				this._dataAccessor = new DataRowItemAccessor(arg1, arg2);
			} else {
				this._dataAccessor = new PredefinedItemAccessor(this);

				this.label = arg1;
				this.value = arg2;
				this.icon = "";
				this.tooltip = null;
			}
		}

		/**
		 * 액세서를 반환합니다.
		 */
		public _getDataAccessor() {
			return this._dataAccessor;
		}

		/**
		 * item의 값을 반환합니다.
		 * @return item의 값
		 */
		get value(): string {
			let value = this._getDataAccessor().get("value");
			if (value != null) {
				value = utils.Util.toString(value);
			}
			return value;
		}

		/**
		 * item의 값을 설정합니다.
		 * @param newValue item의 값
		 */
		set value(newValue: string) {
			newValue = utils.Util.toString(newValue);
			this._getDataAccessor().set("value", newValue);
		}

		/**
		 * 아이템의 display되는 text를 반환합니다.
		 * @return display되는 text.
		 */
		get label(): string {
			let label = this._getDataAccessor().get("label");
			label = utils.Util.toString(label);
			return label;
		}

		/**
		 * 아이템의 display되는 text를 설정합니다.
		 * @param newLabel display되는 text.
		 */
		set label(newLabel: string) {
			newLabel = utils.Util.toString(newLabel);
			this._getDataAccessor().set("label", newLabel);
		}

		/**
		 * 아이템에 툴팁 값을 가져옵니다.
		 * @return tooltip text.
		 */
		get tooltip(): string {
			let tooltip = this._getDataAccessor().get("tooltip");
			return tooltip;
		}

		/**
		 * 아이템에 툴팁을 설정합니다.
		 * @param newTooltip tooltip text.
		 */
		set tooltip(newTooltip: string) {
			if (newTooltip != null) {
				newTooltip = utils.Util.toString(newTooltip);
			}
			this._getDataAccessor().set("tooltip", newTooltip);
		}

		/**
		 * 아이템을 나타내는 icon의 URL 얻습니다.
		 * @return 아이템을 나타내는 icon의 URL.
		 */
		get icon(): string {
			let icon = this._getDataAccessor().get("icon");
			icon = utils.Util.toString(icon);
			return icon;
		}

		/**
		 * 아이템을 나타내는 아이콘의 URL 지정합니다.
		 * @param newIcon 아이콘 URL.
		 */
		set icon(newIcon: string) {
			newIcon = utils.Util.toString(newIcon);
			this._getDataAccessor().set("icon", newIcon);
		}

		protected _matchCondition(key: string, value: any): boolean {
			switch (key) {
				case "value": {
					return this.value == value;
				}
				case "label": {
					return this.label == value;
				}
				case "icon": {
					return this.icon == value;
				}
				case "toolip": {
					return this.tooltip == value;
				}
				default: {
					return true;
				}
			}
		}

		public _match(condition: { [key: string]: string }): boolean {
			for (let key in condition) {
				if (this[key] === undefined) {
					return false;
				}
				if (this._matchCondition(key, condition[key]) === false) {
					return false;
				}
			}
			return true;
		}

		public _getEnabled(): boolean {
			let enabled = this._getDataAccessor().get("enabled");
			if (enabled == null) {
				return true;
			}
			return enabled;
		}

		public _setEnabled(enabled: boolean) {
			this._getDataAccessor().set("enabled", enabled);
		}

		/**
		 * 해당 속성을 bind합니다. 데이터셋의 아이템은 바인딩을 지원하지 않습니다.
		 * @param name bind할 속성 명.
		 */
		bind(name: string): bind.IBindFactory {
			return this._getDataAccessor().bind(name);
		}

		/**
		 * 해당 속성의 bind 여부를 반환합니다. 데이터셋의 아이템은 바인딩을 지원하지 않습니다.
		 * @param name 속성 명
		 */
		isBindable(name: string): boolean {
			return this._getDataAccessor().isBindable(name);
		}

		/**
		 * bind 문맥을 반환합니다.
		 * @return bind 문맥
		 */
		getBindContext(): bind.BindContext {
			return null;
		}

		_getExpressionDelegates(): any[] {
			if (this._ownerBindContext) {
				return [this.row, this._ownerBindContext]; // 아이템의 행부터 우선으로 검색하도록 함. 순서 변경 시 호환성 문제 발생.
			}
			return [this.row];
		}

		_getExpressionIDLookupProvider(): expression._ILookupProvider_ {
			return this._expressionIDLookupProvider ?? null;
		}

		/**
		 * UUID를 반환합니다. UUID가 없는 경우 새로 생성합니다.
		 * @returns 
		 */
		_getUUID(): string {
			return this._getDataAccessor()._getUUID();
		}

		/**
		 * 주어진 아이템을 입력으로 하는 익스프레션식을 실행하기 위한 입력 컨텍스트 객체를 만듭니다.
		 * @param control 소유 컨트롤. 이 값을 주지 않으면 익스프레션 내의 ID 셀렉터가 작동하지 않습니다.
		 */
		public toExpressionContext(control: controls.UIControl = null): bind.BindContext {
			return new bind.ItemContext(this, control)
		}

		/**
		 * 동일한 아이템 여부를 비교합니다. value 기반 비교입니다.
		 * dataset의 아이템은 새로 만들어지기 때문에 비교 API를 사용하는 것을 권장함.
		 * @param item 
		 * @returns 
		 */
		public _equalsValue(item: Item): boolean {
			//TODO _equalsUUID로 변경 검토
			if (item == null) {
				return false;
			}
			if (this == item) {
				return true;
			}
			return this._match({ value: item.value });
		}

		/**
		 * 아아이템이 동일한지 여부를 비교합니다. UUID기반 비교입니다.
		 * @param item 
		 * @returns 
		 */
		public _equalsUUID(item: Item): boolean {
			if (item == null) {
				return false;
			}
			if (this == item) {
				return true;
			}
			return this._getUUID() == item?._getUUID();
		}
	}


	/**
	 * 데이터셋의 컬럼과 바인딩하는 설정 속성.
	 */
	export interface ItemSetConfig {
		/**
		 * 아이템의 display되는 text.
		 */
		label: column_name_string,
		/**
		 * 아이템의 값.
		 */
		value: column_name_string,
		/**
		 * 아이템의 icon의 경로.
		 */
		icon?: column_name_string
		/**
		 * 아이템 설명 표시.
		 */
		tooltip?: column_name_string
	}

	/**
	 * Tree,LinkedCombobox,LinkedListbox의 아이템. label, value, parentValue를 가지며 옵션으로 icon을 제공하는 아이템. 계층 구조를 갖는 트리 컴포넌트에서 사용됩니다.
	 */
	export class TreeItem extends Item {
		protected _parent: any = null;
		protected _children: TreeItem[];

		/**
		 * 트리 아이템을 생성합니다.
		 * @param label 트리 아이템의 display되는 text.
		 * @param value 트리 아이템의 값.
		 * @param parentValue 아이템의 부모 아이템이 가진 값.
		 */
		constructor(label: string, value: string, parentValue: string);
		/**
		 * @private
		 * @param row 
		 * @param dataProvider 
		 */
		constructor(row: data.Row, dataProvider: any);
		/**
		 * @private
		 * @param accessor 
		 */
		constructor(accessor: ItemDataAccessor);
		constructor(arg1: any, arg2?: any, arg3?: any) {
			super(arg1, arg2);

			if (arg3 != null) {
				this.parentValue = arg3;
				this.checked = null;
			}

		}

		/**
		 * 부모의 값을 가져옵니다.
		 */
		get parentValue(): string {
			let parentValue = this._getDataAccessor().get("parentValue");
			if (parentValue != null) {
				parentValue = utils.Util.toString(parentValue);
			}
			return parentValue;
		}

		/**
		 * 부모의 값을 설정합니다.
		 */
		set parentValue(parentValue: string) {
			if (parentValue != null) {
				parentValue = utils.Util.toString(parentValue);
			}
			this._getDataAccessor().set("parentValue", parentValue);
		}

		/**
		 * 체크여부에 따라 true or false를 반환합니다.
		 */
		get checked(): boolean {
			let checkedValue = this._getDataAccessor().get("checked");
			return checkedValue === "true" || checkedValue === true;
		}

		/**
		 * 체크를 합니다.
		 */
		set checked(checked: boolean) {
			let checkedValue = null;
			if (checked != null) {
				checkedValue = utils.Util.toString(checked);
			}
			this._getDataAccessor().set("checked", checkedValue);
		}

		/**
		 * 부모의 아이템을 반환합니다.
		 */
		get parentItem(): TreeItem {
			return this._parent;
		}

		/**
		 * 자식 아이템들을 반환합니다.
		 */
		get children(): TreeItem[] {
			return this._children ?? [];
		}

		/**
		 * 아이템의 깊이의 값을 반환합니다.
		 */
		get depth(): number {
			let next: TreeItem = this;
			let count = 0;
			while (next._parent != null) {
				next = next._parent;
				count++;
			}

			return count;
		}

		/**
		 * 아이템이 확장 여부를 반환합니다.
		 */
		get expanded(): boolean {
			if (!this._hasChild()) {
				return false;
			}
			return this._getOpen();
		}

		/**
		 * 부모 아이템을 설정합니다.
		 * @param parent 
		 * @returns 
		 */
		public _setParent(parent: TreeItem | null) {
			if (this._parent == parent) {
				return;
			}
			this._parent = parent;
		}

		/**
		 * 원본 자식 아이템들을 설정합니다.
		 * @param children 
		 * @returns 
		 */
		public _setChildren(children: TreeItem[] | null) {
			if (this._children == children) {
				return;
			}
			this._children = children;
		}
		/**
		 * 원본 자식 아이템들을 반환합니다.
		 * @returns 
		 */
		public _getChildren(): TreeItem[] {
			return this._children;
		}

		/**
		 * 아이템이 열려있는지 여부 상태를 반환합니다.
		 */
		public _getOpen(): boolean {
			let openValue = this._getDataAccessor().get("open");
			return openValue === "true" || openValue === true;
		}

		/**
		 * 아이템이 열려있는지 여부 상태를 설정합니다.
		 */
		public _setOpen(open: boolean) {
			this._getDataAccessor().set("open", open);
		}

		/**
		 * 자식이 있는지 여부를 반환합니다.
		 * @returns 
		 */
		public _hasChild(): boolean {
			return this.children.length > 0
		}

		/**
		 * 열기/닫기를 토글합니다.
		 * @returns 
		 */
		public _toggle(): void {
			if (!this._hasChild()) {
				return;
			}
			let isExpanded = this.expanded;
			this._setOpen(!isExpanded);
		}

		/**
		 * 루트 아이템 여부를 반환합니다.
		 * @returns 
		 */
		public _isRootItem(): boolean {
			return this._parent == null;
		}

		protected _matchCondition(key: string, value: any) {
			if (super._matchCondition(key, value) === false) {
				return false;
			}
			switch (key) {

				case "checked": {
					return this.checked == value as boolean;
				}
				case "depth": {
					return this.depth == value as number;
				}
				case "parentValue": {
					return this.parentValue == value;
				}
				case "parentItem": {
					let parentItem = value as TreeItem;
					if (this.parentItem && parentItem) {
						return this.parentItem.value == parentItem.value && this.parentItem.label == parentItem.label && this.parentItem.parentValue == parentItem.parentValue
					}
					return this.parentItem == parentItem;
				}
				default: {
					return true;
				}
			}
		}

		/**
		 * value를 갖는 부모 아이템을 찾습니다. 있는 경우 true를 반환합니다.
		 * @param value 
		 */
		public hasAncestor(value: string): boolean {
			if (!this._parent) {
				return false;
			}
			if (this._parent.value == value) {
				return true;
			}
			return this._parent.hasAncestor(value);
		}

		override _equalsValue(item: TreeItem): boolean {
			if (item == null) {
				return false;
			}
			if (this == item) {
				return true;
			}
			return this._match({ value: item.value, parentValue: item.parentValue });
		}
	}

	/**
	 * @private
	 */
	export class TreeItemWrapper extends TreeItem {

		constructor(item: Item) {
			super(item._getDataAccessor());
		}

	}

	/**
	 * 데이터셋의 컬럼과 바인딩하는 설정 속성.
	 */
	export interface TreeItemSetConfig extends ItemSetConfig {
		/**
		 * 트리 아이템의 부모 아이템이 가진 값.
		 */
		parentValue: column_name_string
		/**
		 * 아이템 체크여부
		 */
		checked?: column_name_string
	}

	/**
	 * MenuItem. label, value, parentValue를 가지며 옵션으로 icon, accessKey를 제공하는 아이템. 계층 구조를 갖는 메뉴 컴포넌트에서 사용됩니다.
	 */
	export class MenuItem extends TreeItem {

		/**
		 * 메뉴아이템을 생성합니다.
		 * @param label 표시되는 텍스트
		 * @param value 식별하는 값
		 * @param parentValue 부모 식별 값
		 */
		constructor(label: string, value: string, parentValue: string);
		/**
		 * @private
		 * @param row 
		 * @param dataProvider 
		 */
		constructor(row: data.Row, dataProvider: any);
		/**
		 * @private
		 * @param itemAccessor 
		 */
		constructor(itemAccessor: ItemDataAccessor);
		constructor(arg1: any, arg2?: any, arg3?: any) {
			super(arg1, arg2, arg3);
			if (arg3 != null) {
				this.accessKey = null;
			}
		}

		protected _matchCondition(key: string, value: any) {
			if (super._matchCondition(key, value) === false) {
				return false;
			}
			switch (key) {
				case "accessKey": {
					return this.accessKey == value;
				}
				default:
					return true;
			}
		}

		/**
		 * 메뉴아이템에 접근하는 키를 반환합니다.
		 */
		public get accessKey() {
			let accessKey = this._getDataAccessor().get("accessKey");
			accessKey = utils.Util.toString(accessKey);
			return accessKey;
		}

		/**
		 * 메뉴아이템에 접근하는 키를 설정합니다.
		 * 반드시 단일 문자(영문자 또는 숫자)이어야 합니다.
		 */
		public set accessKey(newAccessKey: string) {
			newAccessKey = utils.Util.toString(newAccessKey);
			this._getDataAccessor().set("accessKey", newAccessKey);
		}

		/**
		 * 부모의 아이템을 반환합니다.
		 */
		get parentItem(): MenuItem {
			return this._parent;
		}

	}

	/**
	 * 데이터셋의 컬럼과 바인딩하는 설정 속성.
	 */
	export interface MenuItemSetConfig extends TreeItemSetConfig {
		/**
		 * 메뉴 아이템의 단축키를 지정하거나 가져올 수 있습니다.
		 */
		accessKey?: column_name_string
	}

	/**
	 * 데이터셋의 컬럼과 바인딩하는 설정 속성.
	 */
	export interface CalendarItemSetConfig extends ItemSetConfig {
		/**
		 * 시작 날짜가 표시되는 데이터셋의 컬럼이름
		 */
		start: column_name_string;
		/**
		 * 종료날짜 표시되는 데이터셋의 컬럼이름
		 */
		end: column_name_string;
		/**
		 * 문자열 데이터를 읽는 포맷
		 */
		parseFormat?: column_name_string;
	}

	/**
	 * CalendarItem. label, start, end를 가지고 value를 옵션으로 가지는 아이템.
	 */
	export class CalendarItem extends Item {

		/**
		 * 아이템을 생성합니다.
		 * @param label 아이템의 display되는 text
		 * @param start 아이템이 표시되는 날짜
		 * @param end  아이템이 표시되는 날짜
		 */
		constructor(label: string, start: Date, end: Date, value?: string);
		/**
		 * @private
		 * @param row 
		 * @param dataProvider 
		 */
		constructor(row: data.Row, dataProvider: any);
		/**
		 * @private
		 * @param accessor 
		 */
		constructor(accessor: ItemDataAccessor);
		constructor(arg1: any, arg2?: any, end?: any, value?: any) {
			if (typeof arg1 == "string") { // 선행데이터
				if (!value) {
					value = _generateUUID();
				}
				super(arg1, value);
				this.start = arg2;
				this.end = end;
			} else {
				super(arg1, arg2);
			}

			let dataAccessor = this._getDataAccessor();
			if (dataAccessor._getItemSetConfig() && (dataAccessor._getItemSetConfig() as CalendarItemSetConfig).value == null) {
				//바인딩되어 있으나 value 바인딩이 안되어 있는 경우 데이터셋의 로우 인덱스로 value를 설정한다.
				this.value = "i-ds" + dataAccessor._getRow().getIndex();
			}
		}

		/**
		 * 캘린더 아이템의 start 값을 반환합니다.
		 */
		public get start(): Date {
			let startValue = this._getDataAccessor().get("start");
			return this._convertDateFromFormat(startValue);
		}

		/**
		 * 캘린더 아이템의 start 값을 설정합니다.
		 */
		public set start(start: Date) {
			let startValue = this._convertFormatFromDate(start);
			this._getDataAccessor().set("start", startValue);
		}

		/**
		 * 캘린더 아이템의 end 값을 반환합니다.
		 */
		public get end(): Date {
			let endValue = this._getDataAccessor().get("end");
			return this._convertDateFromFormat(endValue)
		}

		/**
		 * 캘린더 아이템의 end 값을 설정합니다.
		 */
		public set end(end: Date) {
			let endValue = this._convertFormatFromDate(end);
			this._getDataAccessor().set("end", endValue);
		}

		private _convertDateFromFormat(formatDate: string) {
			if (formatDate == null) {
				return null;
			}
			let parseFormat = "YYYYMMDD";
			if (this._getDataAccessor()._getItemSetConfig()) {
				parseFormat = (this._getDataAccessor()._getItemSetConfig() as CalendarItemSetConfig).parseFormat;
			}
			let mm = moment(formatDate, parseFormat, true);
			return mm.isValid() ? mm.toDate() : null;
		}

		private _convertFormatFromDate(date: Date) {
			if (date == null) {
				return null;
			}
			let parseFormat = "YYYYMMDD";
			if (this._getDataAccessor()._getItemSetConfig()) {
				parseFormat = (this._getDataAccessor()._getItemSetConfig() as CalendarItemSetConfig).parseFormat;
			}
			let mm = moment(date);

			return mm.isValid() ? mm.format(parseFormat) : null;
		}

		protected _matchCondition(key: string, value: any) {
			if (super._matchCondition(key, value) === false) {
				return false;
			}
			switch (key) {
				case "start": {
					if (this.start && value instanceof Date) {
						return this.start.getTime() == value.getTime();
					}
					return this.start == value;
				}
				case "end": {
					if (this.end && value instanceof Date) {
						return this.end.getTime() == value.getTime();
					}
					return this.end == value;
				}
				case "range": {
					if (value instanceof utils.DateRange) {
						return this.range.start.getTime() == value.start.getTime() && this.range.end.getTime() == value.end.getTime();
					}
					return false;
				}
				default: {
					return true;
				}
			}
		}

		/**
		 * 시작 날짜와 마지막 날짜의 범위 객체를 반환합니다.
		 */
		get range(): utils.DateRange {
			return new utils.DateRange(this.start, this.end ? this.end : this.start)
		}

	}

	/**
	 * 이미지 맵의 영역의 형태 유형을 나타냅니다.
	 */
	export enum ImageAreaShapeType {
		/**
		 * 이미지맵 사각형 영역
		 */
		RECT = "rect",

		/**
		 * 이미지맵 폴리곤 영역
		 */
		POLYGON = "polygon",

		/**
		 * 이미지맵 폴리곤 영역의 구명칭.
		 * @deprecated polygon으로 개명되었습니다. 기존 산출물·데이터셋 값 호환용으로만 유지됩니다.
		 */
		POLY = "poly",

		/**
		 * 이미지맵 원 영역
		 */
		CIRCLE = "circle",

		/**
		 * 이미지맵 폴리라인 영역. 배관·배선 등 열린 경로의 시각적 표시 전용으로,
		 * 클릭이나 포커스 등 이벤트 대상이 되지 않습니다.
		 */
		POLYLINE = "polyline"
	}

	/**
	 * 데이터셋의 컬럼과 바인딩하는 설정 속성.
	 */
	export interface ImageAreaItemSetConfig extends ItemSetConfig {
		/**
		 * 영역 형식으로 사용할 데이터 컬럼 이름.
		 */
		shape: column_name_string;

		/**
		 * 영역의 좌표 표현식으로 사용할 데이터 컬럼 이름.
		 */
		coords: column_name_string;

		/**
		 * 점퍼 나열로 사용할 데이터 컬럼 이름. (polyline 형태 전용)
		 */
		jumpers?: column_name_string;

		/**
		 * 점퍼 반지름으로 사용할 데이터 컬럼 이름. (polyline 형태 전용)
		 */
		jumperRadius?: column_name_string;
	}

	/**
	 * 이미지 내 영역 아이템.
	 */
	export class ImageAreaItem extends Item {
		/**
		 * 새로운 영역을 작성합니다.
		 *
		 * @param label 레이블.
		 * @param value 고유 값.
		 * @param shape 영역의 형태.
		 * @param coords 영역의 좌표 표현식.
		 * @param jumpers 점퍼 나열. (polyline 형태 전용)
		 * @param jumperRadius 점퍼 반지름. (polyline 형태 전용, 기본 8)
		 */
		constructor(label: string, value: string, shape: ImageAreaShapeType, coords: string, jumpers?: string, jumperRadius?: number)
		/**
		 * @private
		 * @param row
		 * @param dataProvider
		 */
		constructor(row: data.Row, dataProvider: any);
		/**
		 * @private
		 * @param accessor
		 */
		constructor(accessor: ItemDataAccessor);
		constructor(arg1: any, arg2?: any, shape?: any, coords?: any, jumpers?: any, jumperRadius?: any) {
			super(arg1, arg2);
			if (typeof arg1 === "string") {
				this.shape = shape;
				this.coords = coords;
				if (jumpers != null) {
					this.jumpers = jumpers;
				}
				if (jumperRadius != null) {
					this.jumperRadius = jumperRadius;
				}
			}
		}

		/**
		 * 영역의 형태를 얻습니다.
		 */
		get shape(): ImageAreaShapeType {
			return this._getDataAccessor().get("shape");
		}

		/**
		 * 영역의 형태를 지정합니다.
		 */
		set shape(newShape: ImageAreaShapeType) {
			switch (newShape) {
				case "rect":
				case "polygon":
				case "poly":
				case "circle":
				case "polyline":
					this._getDataAccessor().set("shape", newShape);
					break;
				default:
					throw new exceptions.IllegalArgumentException("a shape value must be one of rect, polygon, circle, polyline");
			}
		}

		/**
		 * 영역의 좌표 표현식을 얻습니다.
		 */
		get coords(): string {
			let coords = this._getDataAccessor().get("coords");
			coords = utils.Util.toString(coords);
			return coords;
		}

		/**
		 * 영역의 좌표 표현식을 지정합니다.
		 */
		set coords(newCoords: string) {
			newCoords = utils.Util.toString(newCoords);
			this._getDataAccessor().set("coords", newCoords);
		}

		/**
		 * 도형 외곽선 경로에 삽입 된 반원 점퍼의 나열을 얻습니다.
		 */
		get jumpers(): string {
			let jumpers = this._getDataAccessor().get("jumpers");
			jumpers = utils.Util.toString(jumpers);
			return jumpers;
		}

		/**
		 * 도형 외곽선 경로에 삽입 된 반원 점퍼의 나열을 지정합니다.
		 * 공백으로 구분 된 "세그먼트:거리[:f]" 항목들입니다. (polyline 형태 전용)
		 */
		set jumpers(newJumpers: string) {
			newJumpers = utils.Util.toString(newJumpers);
			this._getDataAccessor().set("jumpers", newJumpers);
		}

		/**
		 * 점퍼 반원의 반지름을 얻습니다. 지정되지 않았으면 기본값 8입니다.
		 */
		get jumperRadius(): number {
			let radius = parseFloat(this._getDataAccessor().get("jumperRadius"));
			return isNaN(radius) ? 8 : radius;
		}

		/**
		 * 점퍼 반원의 반지름을 지정합니다. 영역 항목 단위로 적용 됩니다.
		 */
		set jumperRadius(newRadius: number) {
			this._getDataAccessor().set("jumperRadius", newRadius);
		}
	}

	/**
	 * @private
	 */
	export enum ItemDataSetCtrlProperty {
		enabled = "_enabled",
		open = "_open",
		checked = "checked"
	}

	/**
	 * @private
	 */
	abstract class ItemDataAccessor {

		public _getRow(): data.Row {
			return null;
		}

		abstract _getUUID(): string;

		public _getItemSetConfig(): any {
			return null;
		}

		abstract get(name: string): any;
		abstract set(name: string, value: any): void;

		abstract bind(name: string): bind.IBindFactory;
		abstract isBindable(name: string): boolean;

	}

	/**
	 * @private
	 */
	class PredefinedItemAccessor extends ItemDataAccessor {

		private _bindables: bind.BindableProperties;
		private _uuid: string;

		constructor(item: Item) {
			super();
			this._bindables = new bind.BindableProperties(item, {
				allowsDataColumnBind: false
			})

		}

		_getUUID(): string {
			if (!this._uuid) {
				this._uuid = _generateUUID();
			}
			return this._uuid;
		}

		get(name: string): string {
			if (this.isBindable(name) == false) {
				return null;
			}
			return this._bindables.get(name);
		}

		set(name: string, value: any) {
			if (this.isBindable(name) == false) {
				this._bindables.add(name, value);
			} else {
				this._bindables.set(name, value);
			}
		}

		bind(name: string): bind.IBindFactory {
			return this._bindables.bind(name);
		}

		isBindable(name: string): boolean {
			return this._bindables.isBindable(name);
		}

	}

	/**
	 * @private
	 */
	class DataRowItemAccessor extends ItemDataAccessor {

		private _row: data.Row;
		private _itemSetInfo: controls.item.ItemSetInfo;
		private _data: { [key: string]: any };

		constructor(row: data.Row, itemSetInfo: any) {
			super();
			this._row = row;
			this._itemSetInfo = itemSetInfo;
			this._initData();
		}

		private _initData() {
			this._data = {};
			let dataSet = this._getDataSet();
			let itemsSetConfig = this._getItemSetConfig() as {};
			for (let key in itemsSetConfig) {
				this._data[key] = dataSet.getValue(this._row.getIndex(), itemsSetConfig[key]);
			}
		}

		private _isDataSetCtrlProperty(name: string) {
			return name in ItemDataSetCtrlProperty;
		}

		public _getUUID(): string {
			let uuid = this._row._getRowData()._getAttr("item-uuid");
			if (!uuid) {
				uuid = _generateUUID();
				this._row._getRowData()._setAttr("item-uuid", uuid);
			}
			return uuid;
		}

		public _getRow(): data.Row {
			return this._row;
		}

		public _getItemSetConfig(): any {
			if (!this._itemSetInfo) {
				return null;
			}
			if (this._itemSetInfo.disposed) {
				this._itemSetInfo = null;
				return null;
			}
			return this._itemSetInfo.itemSetConfig;
		}

		private _getOwner(): Control {
			if (!this._itemSetInfo) {
				return null;
			}
			if (this._itemSetInfo.disposed) {
				this._itemSetInfo = null;
				return null;
			}
			return this._itemSetInfo.owner;
		}

		private _getDataSet(): data.DataCollection {
			if (!this._itemSetInfo) {
				return null;
			}
			if (this._itemSetInfo.disposed) {
				this._itemSetInfo = null;
				return null;
			}
			return this._itemSetInfo.dataSet;
		}

		public get(name: string) {
			let dataSet = this._getDataSet();
			if (dataSet) {
				let columnName = this._getItemSetConfig()[name];
				if (columnName) {
					this._data[name] = dataSet.getValue(this._row.getIndex(), columnName);
				} else if (this._isDataSetCtrlProperty(name)) {
					this._data[name] = dataSet._getCtrlAttr(this._getOwner(), this._row.getIndex(), ItemDataSetCtrlProperty[name]);
				}
			}
			return this._data[name] ?? null;
		}

		public set(name: string, value: any) {
			value = utils.Util.toString(value);
			this._data[name] = value;

			let dataSet = this._getDataSet();
			if (!dataSet) {
				return;
			}
			if (this._getItemSetConfig()[name]) {
				dataSet.setValue(this._row.getIndex(), this._getItemSetConfig()[name], value);
			} else if (this._isDataSetCtrlProperty(name)) {
				dataSet._setCtrlAttr(this._getOwner(), this._row.getIndex(), ItemDataSetCtrlProperty[name], value);
			}
		}

		bind(name: string): bind.IBindFactory {
			throw new exceptions.UnsupportedOperationException();
		}

		isBindable(name: string): boolean {
			return false;
		}
	}

}