

namespace cpr.protocols.response {
	/**
	 * @private
	 */
	export abstract class AbstractResponseParser<SubmissionType extends AbstractSubmission> implements ResponseParser {
		private static readonly _DATA_DELIMITER: string = "@d#";


		constructor() {
		}

		public load(submission: SubmissionType, xhr: XMLHttpRequest): void {
			if (submission instanceof Submission == false) {
				throw new exceptions.IllegalArgumentException("cpr.protocols.Submission");
			}
			this._loadSpecific(submission, xhr);
		}
		public abstract _abortLoading(submission: SubmissionType): void;

		public parse(submission: SubmissionType, xhr: XMLHttpRequest, doneHandler: () => void): void {
			if (submission instanceof Submission == false) {
				throw new exceptions.IllegalArgumentException("cpr.protocols.Submission");
			}
			this._parseSpecific(submission, xhr, doneHandler);
		}

		protected abstract _loadSpecific(submission: SubmissionType, xhr: XMLHttpRequest): void;
		protected abstract _parseSpecific(submission: SubmissionType, xhr: XMLHttpRequest, doneHandler: () => void): void;
		public abstract _parseData(submission: SubmissionType, stringData: {} | string, doneHandler: () => void): void;

		protected _getDataDelimiterName(): string {
			return AbstractResponseParser._DATA_DELIMITER;
		}

	}

}