

namespace cpr.events.resize {
	/**
	 * calc depth
	 * @param target
	 */
	function _getTargetDepth(target: HTMLElement): number {
		if (!target) {
			return -1;
		}
		let targetDepth: number = 0;
		for (let parent: HTMLElement = target; parent != null; parent = parent.parentElement) {
			targetDepth++;
		}
		return targetDepth;
	}

	/*
	 * Document has a resizeObservers slot that is a list of ResizeObservers in this document.
	 * It is initialized to empty.
	 */

	/**
	 * DOMRectReadOnly
	 */
	export interface ContentRect {
		left: number;
		top: number;
		right: number;
		bottom: number;
		width: number;
		height: number;
		x: number;
		y: number;
	}

	/**
	 * ResizeObserverEntry
	 */
	export class ResizeObserverEntry {
		private _target: HTMLElement;
		private _contentRect: ContentRect;

		/**
		 * The Element whose size has changed.
		 * @param target of type Element
		 */
		constructor(target: HTMLElement) {
			// 1. Let this be a new ResizeObserverEntry.
			// 2. Set this target slot to target.
			this._target = target;
			let boundingClientRect = this._target.getBoundingClientRect();
			if (typeof boundingClientRect["x"] === "number") {
				// 4. If target is an SVG element do these steps:
				// 4.1 Set this.contentRect.top and this.contentRect.left to 0.
				// 4.2 Set this.contentRect.width to target.bounding box.width.
				// 4.3 Set this.contentRect.height to target.bounding box.height.
				this._contentRect = {
					left: 0,
					top: 0,
					right: boundingClientRect["right"],
					bottom: boundingClientRect["bottom"],
					width: boundingClientRect["width"],
					height: boundingClientRect["height"],
					x: boundingClientRect["x"],
					y: boundingClientRect["y"]
				};
			} else {
				// 3. If target is not an SVG element do these steps:
				// 3.1 Set this.contentRect.width to target.content width.
				// 3.2 Set this.contentRect.height to target.content height.
				// 3.3 Set this.contentRect.top to target.padding top.
				// 3.4 Set this.contentRect.left to target.padding left.
				this._contentRect = {
					left: boundingClientRect["left"],
					top: boundingClientRect["top"],
					right: boundingClientRect["right"],
					bottom: boundingClientRect["bottom"],
					width: boundingClientRect["width"],
					height: boundingClientRect["height"],
					x: boundingClientRect["left"],
					y: boundingClientRect["top"]
				};
			}
		}

		/**
		 * The Element whose size has changed.
		 */
		public get target(): HTMLElement {
			return this._target;
		}

		/**
		 * Element's content rect when ResizeObserverCallback is invoked.
		 */
		public get contentRect(): ContentRect {
			return this._contentRect;
		}
	}

	export class ResizeObservation {
		private _target: HTMLElement;
		private _broadCastWidth: number;
		private _broadCastHeight: number;


		constructor(target: HTMLElement) {
			// 1. Let this be a new ResizeObservation object
			// 2. Set this internal target slot to target
			this._target = target;
			// 3. Set this broadcastWidth slot to 0.
			this._broadCastWidth = 0;
			// 4. Set this broadcastHeight slot to 0.
			this._broadCastHeight = 0;
		}

		/**
		 * The observed Element.
		 */
		public get target(): HTMLElement {
			return this._target;
		}

		/**
		 * Width of last broadcast content width.
		 */
		public get broadcastWidth(): number {
			return this._broadCastWidth;
		}

		public _setBroadcaseWidth(width: number): void {
			this._broadCastWidth = width;
		}

		/**
		 * Height of last broadcast content height.
		 */
		public get broadcastHeight(): number {
			return this._broadCastHeight;
		}

		public _setBroadcaseHeight(height: number): void {
			this._broadCastHeight = height;
		}

		public isActive(): boolean {
			// 1. If target is an HTML element do these steps:
			// 2. If target is an SVGGraphicsElement do these steps:
			let boundingClientRect = this._target.getBoundingClientRect();
			// 1.1 If target.content width != broadcastWidth return true.
			// 1.2 If target.content height != broadcastHeight return true.
			// 2.1 If target.bounding box width != broadcastWidth return true.
			// 2.2 If target.bounding box height != broadcastHeight return true.
			if (boundingClientRect["width"] != this._broadCastWidth
				|| boundingClientRect["height"] != this._broadCastHeight) {
				return true;
			}
			// 3. return false.
			return false;
		}

	}

	/**
	 * This callback delivers ResizeObserver's notifications.
	 * It is invoked by a broadcast active observations algorithm.
	 */
	export interface ResizeObserverCallback {
		(entries: ResizeObserverEntry[], observer: ResizeObserver): void;
	}

	export class ResizeObservers {
		public static readonly INSTANCE: ResizeObservers = new ResizeObservers();

		private _resizeListener: (e: events.CUIEvent) => void = (e) => this._onResize(e);
		private _resizeObservers: ResizeObserver[];


		constructor() {
			this._resizeObservers = [];
		}

		public addObserver(resizeObserver: ResizeObserver): void {
			if (this._resizeObservers.indexOf(resizeObserver) === -1) {
				this._resizeObservers[this._resizeObservers.length] = resizeObserver;

				if (this._resizeObservers.length == 1) {
					// add global event listener
					events.BodyEventTarget.INSTANCE.addEventListener("resize", this._resizeListener);
				}
			}
		}

		public removeObserver(resizeObserver: ResizeObserver): void {
			let idx: number = this._resizeObservers.indexOf(resizeObserver);
			if (idx > -1) {
				this._resizeObservers.splice(idx, 1);
			}
		}

		private _onResize(e: CUIEvent): void {
			core.NotificationCenter.INSTANCE.post(core.SystemTopics.RESIZE, e.target, this);
			this._doResize(e);
		}

		private _doResize(e: CUIEvent): number {
			let depth: number = 0;

			// 1. Let shallowestTargetDepth be ∞
			let shallowestTargetDepth: number = Number.MAX_VALUE;
			// 2. For each observer in document.resizeObservers run these steps:
			for (let idx: number = 0; idx < this._resizeObservers.length; idx++) {
				let resizeObserver: ResizeObserver = this._resizeObservers[idx];
				resizeObserver._gatherActiveObservation(depth);
				// 2.1 If observer.activeTargets slot is empty, continue.
				if (resizeObserver._hasActiveObservations() === true) {
					// 2.2 Let entries be an empty list of ResizeObserverEntryies.
					let entries: ResizeObserverEntry[] = [];
					let activeTargets: ResizeObservation[] = resizeObserver._getActiveTargets();

					// 2.3 For each observation in activeTargets perform these steps:
					for (let activeIdx: number = 0; activeIdx < activeTargets.length; activeIdx++) {
						let resizeObservation: ResizeObservation = activeTargets[activeIdx];
						// 2.3.1 Let entry be new ResizeObserverEntry(observation.target)
						let resizeObserverEntry: ResizeObserverEntry = new ResizeObserverEntry(resizeObservation.target);
						// 2.3.2 Add entry to entries
						entries[entries.length] = resizeObserverEntry;

						let contentRect: ContentRect = resizeObserverEntry.contentRect;
						// 2.3.3 Set observation.broadcastWidth to entry.contentRect.width.
						resizeObservation._setBroadcaseWidth(contentRect.width);
						// 2.3.4 Set observation.broadcastHeight to entry.contentRect.height.
						resizeObservation._setBroadcaseHeight(contentRect.height);
						// 2.3.5 Set targetDepth to the result of calculate depth for node for observation.target.
						let targetDepth: number = _getTargetDepth(resizeObservation.target);
						// 2.3.6 Set shallowestTargetDepth to targetDepth if targetDepth < shallowestTargetDepth
						if (targetDepth < shallowestTargetDepth) {
							shallowestTargetDepth = targetDepth;
						}
					}
					try {
						// 2.3.4 Invoke observer.callback with entries.
						resizeObserver.callback(entries, resizeObserver);
						// 2.3.5 Clear observer.activeTargets.
						resizeObserver._clearActiveTargets();
					} catch (e) {
						// Deliver Resize Loop Error
						// 1. Create a new ErrorEvent.
						// 2. Initialize event’s message slot to "ResizeObserver loop completed with undelivered notifications.".
						let errorEvt: ErrorEvent = new ErrorEvent("ResizeObserver loop completed with undelivered notifications.");
						// 3. Dispach the event to document’s window.
						window.dispatchEvent(errorEvt);
					}
				}
			}
			// 3. Return shallowestTargetDepth.
			return shallowestTargetDepth;
		}

	}

	export class ResizeObserver {
		/**
		 * 
		 */
		private _callback: ResizeObserverCallback;
		/**
		 * A list of ResizeObservations.
		 * It represents all Elements being observed.
		 */
		private _observationTargets: ResizeObservation[];
		/**
		 * A list of ResizeObservations.
		 * It represents all Elements whose size has changed since last observation broadcast that are eligible for broadcast.
		 */
		private _activeTargets: ResizeObservation[];
		/**
		 * A list of ResizeObservations.
		 * It represents all Elements whose size has changed since last observation broadcast that are **not** eligible for broadcast.
		 */
		private _skippedTargets: ResizeObservation[];

		private _connected: boolean = false;


		/**
		 * new ResizeObserver(callback)
		 */
		constructor(callback: ResizeObserverCallback) {
			// 1. Let this be a new ResizeObserver object.
			// 2. Set this internal callback slot to callback.
			// 3. Add this to Document's resizeObservers slot.
			this._callback = callback;
			this._observationTargets = [];
			this._activeTargets = [];
			this._skippedTargets = [];

			ResizeObservers.INSTANCE.addObserver(this);
			this._connected = true;
		}

		public get callback(): ResizeObserverCallback {
			return this._callback;
		}

		/**
		 * observe(target)
		 * Adds target to the list of observed elements.
		 * 1. If target is in observationTargets slot, return.
		 * 2. Let resizeObservation be new ResizeObservation(target).
		 * 3. Add the resizeObservation to the observationTargets slot.
		 * @param target observe(target)
		 */
		public observe(target: HTMLElement): void {
			// check for disconnected
			if (this._connected == false) {
				throw new exceptions.DisposeException();
			}

			for (let idx: number = 0; idx < this._observationTargets.length; idx++) {
				let resizeObservation: ResizeObservation = this._observationTargets[idx];
				if (resizeObservation.target === target) {
					return;
				}
			}
			let resizeObservation: ResizeObservation = new ResizeObservation(target);
			this._observationTargets[this._observationTargets.length] = resizeObservation;
		}

		/**
		 * unobserve(target)
		 * Removes target from the list of observed elements.
		 * 1. Let observation be ResizeObservation in observationTargets whose target slot is target.
		 * 2. If observation is not found, return.
		 * 3. Remove observation from observationTargets.
		 * @param target 
		 */
		public unobserve(target: HTMLElement): void {
			// check for disconnected
			if (this._connected == false) {
				throw new exceptions.DisposeException();
			}

			for (let idx: number = 0; idx < this._observationTargets.length; idx++) {
				let resizeObservation: ResizeObservation = this._observationTargets[idx];
				if (resizeObservation.target === target) {
					this._observationTargets.splice(idx, 1);
					return;
				}
			}
		}

		/**
		 * disconnect()
		 */
		public disconnect(): void {
			// 1) Clear the observationTargets list.
			// 2) Clear the activeTargets list.
			this._observationTargets = null;
			this._activeTargets = null;
			this._skippedTargets = null;

			ResizeObservers.INSTANCE.removeObserver(this);
			this._connected = false;
		}

		/**
		 * Gather active observations at depth.
		 * It computes all active observations for a document.
		 */
		public _gatherActiveObservation(depth: number): void {
			// To gather active observations at depth, run these steps:
			// 1. Let depth be the depth passed in.
			// 2. For each observer in resizeObservers run these steps:
			// 2.1 Clear observer’s activeTargets, and skippedTargets
			this._activeTargets = [];
			this._skippedTargets = [];
			// 2.2 For each observation in observer.observationTargets run this step:
			for (let idx: number = 0; idx < this._observationTargets.length; idx++) {
				let resizeObservation: ResizeObservation = this._observationTargets[idx];
				// 2.2.1 If observation.isActive() is true
				if (resizeObservation.isActive() === true) {
					// 2.2.1.1 Let targetDepth be result of calculate depth for node for observation.target.
					let targetDepth: number = _getTargetDepth(resizeObservation.target);
					if (targetDepth > depth) {
						// 2.2.1.2 If targetDepth is greater than depth then add observation to activeTargets.
						this._activeTargets[this._activeTargets.length] = resizeObservation;
					} else {
						// 2.2.1.3 Else add observation to skippedTargets.
						this._skippedTargets[this._activeTargets.length] = resizeObservation;
					}
				}
			}
		}

		public _getActiveTargets(): ResizeObservation[] {
			return this._activeTargets;
		}

		public _clearActiveTargets(): void {
			this._activeTargets = [];
			this._skippedTargets = [];
		}

		/**
		 * Has active observations
		 */
		public _hasActiveObservations(): boolean {
			return this._activeTargets.length > 0;
		}

	}
}