

namespace cpr.controls.internal {
	/**
	 * @private
	 */
	export interface IVirtualScrollPane {
		_isEnabled(): boolean; // TODO 필요성 여부 판단 필요
		_getViewportWidth(): number;
		_getViewportHeight(): number;
		_getContentWidth(): number;
		_getContentHeight(): number;
		_getQName(name: string): string;
		_setScrollTop(e: events.CUIEvent, scrollTop: number): number;
		_setScrollLeft(e: events.CUIEvent, scrollLeft: number): number;
		_checkResize(): void;
		_onMousedownScroll?(e: events.CMouseEvent): void;
		_getRenderer(): ufc.ControlRenderer;

	}

	export abstract class AbstractScrollPane {
		private _uicontrol: UIControl;


		constructor(uicontrol: UIControl) {
			this._uicontrol = uicontrol;
		}

		protected get uicontrol(): UIControl {
			return this._uicontrol;
		}

		protected _getOverscrollBehaviorType(): OverscrollBehaviorType {
			if (this._uicontrol instanceof Container) {
				return this._uicontrol.overscrollBehavior;
			}
			return OverscrollBehaviorType.AUTO;
		}

		protected _dispose(): void {
			this._uicontrol = null;
		}

	}

}