namespace cpr.vdom {
	/**
	 * 
	 * @private
	 * @param a 
	 * @param b 
	 * @returns 
	 */
	export function _handleThunk(a: VTreeElement, b?: VTreeElement) {
		let renderedA: VTreeElement = a
		let renderedB: VTreeElement = b

		if (_isThunk(b)) {
			renderedB = _renderThunk(b as Thunk, a as Thunk)
		}

		if (_isThunk(a)) {
			renderedA = _renderThunk(a as Thunk, null)
		}

		return {
			a: renderedA,
			b: renderedB
		}
	}

	function _renderThunk(thunk: Thunk, previous: Thunk) {
		let renderedThunk = thunk.vnode

		if (!renderedThunk) {
			renderedThunk = thunk.vnode = thunk.render(previous)
		}

		if (!(_isVNode(renderedThunk) ||
			_isVText(renderedThunk) ||
			_isWidget(renderedThunk))) {
			throw new Error("thunk did not return a valid node");
		}
		return renderedThunk
	}
}