	export interface ElSize {
		ow: number, // 바깥 넓이
		oh: number, // 바깥 높이
		iw: number, // 안쪽 넓이
		ih: number, // 안쪽 높이
		mh: number  // 최소 높이
	}

	/**
	 * @private
	 */
	export class GridUtil {
		/**
		 * 주어진 HTMLElement의 rowIndex와 cellIndex를 리턴한다.
		 * @param eventElement 
		 */
		public static _getCellPosition(eventElement: HTMLElement): gridpart.selection.CellPosition {
			let position: gridpart.selection.CellPosition = {
				rowIndex: -1, cellIndex: -1, vrowIndex: -1
			};

			if (eventElement == null) {
				return position;
			}
			let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(eventElement);
			domTraverser = domTraverser._closest(`[data-role="${GRIDROLE.COLUMN_HEADER}"], [data-role="${GRIDROLE.GRID_CELL}"], [data-role="${GRIDROLE.GRID_ROWGROUP_CELL}"], [data-role="${GRIDROLE.FOOTER_CELL}"]`);
			if (domTraverser == null) {
				return position;
			}
			let cellIndex: string = domTraverser._getAttribute("data-cellindex");
			if (cellIndex) {
				position.cellIndex = parseInt(cellIndex);
			}
			let cellRange: string = domTraverser._getAttribute("data-cellrange");
			if (cellRange) {
				let cellRanges: number[] = cellRange.split(",").map((cellIdx: string) => {
					return parseInt(cellIdx);
				});
				position.cellRange = cellRanges;
			}
			domTraverser = domTraverser._parent(`[role="${GRIDROLE.ROW}"]`);
			if (domTraverser == null) {
				return position;
			}
			let rowIndex: string = domTraverser._getAttribute("data-rowindex");
			if (rowIndex) {
				position.rowIndex = parseInt(rowIndex);
			}
			let vrowIndex: string = domTraverser._getAttribute("data-vrowindex");
			if (vrowIndex) {
				position.vrowIndex = parseInt(vrowIndex);
			}

			return position;
		}

		public static getCellStyle(cellProp: GridCellProp, defaultStyle: {} = {}): {} {
			let style = (cellProp.configuration) ? cellProp.configuration.style.css() : {};
			let cellStyle: {} = _assign(defaultStyle, style);
			return cellStyle;
		}

		// Grid가 redraw 될 때 마다 계산하여 재설정
		public static _createRegionColWidth(autofit: string, clientWidth: number, columnLayout: GridColumnProp[]): { contentWidth: number, layout: GridColumnProp[] } {
			let contentWidth: number = 0;
			let regionColumnProp: GridColumnProp[] = [];
			columnLayout.forEach((gridColInfo: GridColumnProp) => {
				if (gridColInfo.visible == false) {
					regionColumnProp[regionColumnProp.length] = { width: 0, autoFit: gridColInfo.autoFit, resizable: gridColInfo.resizable };
				} else {
					contentWidth += gridColInfo.width;
					regionColumnProp[regionColumnProp.length] = { width: gridColInfo.width, autoFit: gridColInfo.autoFit, resizable: gridColInfo.resizable };
				}
			});
			if (autofit && clientWidth > contentWidth) {
				let extraWidth: number = clientWidth - contentWidth;
				if (autofit == "all") {
					GridUtil._allocateExtraWidth(regionColumnProp, contentWidth, extraWidth);
				} else if (autofit != "none") {
					if (autofit.length > 0) {
						let autofitColWidth: number = 0;
						let autofitColWidths: { width: number }[] = [];
						regionColumnProp.forEach((column: GridColumnProp) => {
							if (column.autoFit == true) {
								autofitColWidths.push(column);
								autofitColWidth += column.width;
							}
						});
						GridUtil._allocateExtraWidth(autofitColWidths, autofitColWidth, extraWidth);
					}
				}
			}

			return {
				contentWidth: contentWidth,
				layout: regionColumnProp
			};
		}


		public static _allocateExtraWidth(autofitCols: { width: number }[], autofitContentWidth: number, extraWidth: number): void {
			let remainedExtraWidth: number = extraWidth;
			for (let colIdx: number = 0; remainedExtraWidth != 0 && colIdx < autofitCols.length; colIdx++) {
				let layout: { width: number } = autofitCols[colIdx];
				if (layout.width == 0) {
					continue;
				}
				let widthRatio: number = extraWidth * layout.width / autofitContentWidth;
				if ((extraWidth > 0 && remainedExtraWidth < widthRatio) || (extraWidth < 0 && remainedExtraWidth > widthRatio)) {
					widthRatio = remainedExtraWidth;
					remainedExtraWidth = 0;
				} else {
					remainedExtraWidth -= widthRatio;
				}
				layout.width += widthRatio;
			}
			if (remainedExtraWidth > 0 && autofitCols.length > 0) {
				for (let colIdx: number = autofitCols.length - 1; colIdx >= 0; colIdx--) {
					let layout: { width: number } = autofitCols[colIdx];
					if (layout && layout.width > 0) {
						layout.width += remainedExtraWidth;
						break;
					}
				}
			}
		}

		public static _createCellStyle(regionColWidth: { width: number }[],
			startCellProp: GridCellProp,
			endCellProp: GridCellProp,
			rowHeights: number[],
			isIncludeCellStyle: boolean = true): {
				style: { [key: string]: string },
				bound: { left: number, top: number, width: number, mergeCellWidth: number, height: number }
			} {

			let cellColIndex: number = startCellProp.constraint.regionColIndex;
			let cellColSpan: number = startCellProp.constraint.colSpan;
			cellColSpan = cellColSpan ? cellColSpan : 1;
			let cellRowIndex: number = startCellProp.constraint.rowIndex;
			let lastColIndex: number = endCellProp.constraint.regionColIndex;
			let lastColSpan: number = endCellProp.constraint.colSpan;
			lastColSpan = lastColSpan ? lastColSpan : 1;
			let cellRowSpan: number = startCellProp.constraint.rowSpan;
			cellRowSpan = cellRowSpan ? cellRowSpan : 1;

			let topPosition: number = 0;
			let leftPosition: number = 0;
			let cellWidth: number = 0;
			let mergeCellWidth: number = 0;
			let cellHeight: number = 0;

			for (let colIdx: number = 0; colIdx < cellColIndex; colIdx++) {
				let colLayout: { width: number } = regionColWidth[colIdx];
				if (colLayout) {
					leftPosition += colLayout.width;
				}
			}
			for (let colIdx: number = cellColIndex; colIdx < cellColIndex + cellColSpan; colIdx++) {
				let colLayout: { width: number } = regionColWidth[colIdx];
				if (colLayout) {
					cellWidth += colLayout.width;
				}
			}
			for (let colIdx: number = cellColIndex; colIdx < lastColIndex + lastColSpan; colIdx++) {
				let colLayout: { width: number } = regionColWidth[colIdx];
				if (colLayout) {
					mergeCellWidth += colLayout.width;
				}
			}
			for (let rowIdx: number = 0; rowIdx < cellRowIndex; rowIdx++) {
				let rowHeight: number = rowHeights[rowIdx];
				if (rowHeight > 0) {
					topPosition += rowHeight;
				}
			}
			for (let rowIdx: number = cellRowIndex; rowIdx < cellRowIndex + cellRowSpan; rowIdx++) {
				let rowHeight: number = rowHeights[rowIdx];
				if (rowHeight > 0) {
					cellHeight += rowHeight;
				}
			}

			let locationStyle: { [key: string]: string } = {
				overflow: "hidden"
				, position: "absolute"
				, top: topPosition + "px"
				, left: leftPosition + "px"
				, width: cellWidth + "px"
				, height: cellHeight + "px"
				, "box-sizing": "border-box"
				, display: "inline-block"
			};

			let cellStyle: { [key: string]: string } = null;
			if (isIncludeCellStyle) {
				cellStyle = GridUtil.getCellStyle(startCellProp, locationStyle);
			} else {
				cellStyle = locationStyle;
			}

			return {
				style: cellStyle,
				bound: { left: leftPosition, top: topPosition, width: cellWidth, height: cellHeight, mergeCellWidth: mergeCellWidth }
			};
		}

		public static _getRowStateCSSClasses(rowState: number): string[] {
			let rowClasses: string[] = [];
			switch (rowState) {
				case data.tabledata.RowState.INSERTED: {
					rowClasses.push(ufc.Classes.INSERTED);
					break;
				}
				case data.tabledata.RowState.UPDATED: {
					rowClasses.push(ufc.Classes.MODIFIED);
					break;
				}
				case data.tabledata.RowState.DELETED: {
					rowClasses.push(ufc.Classes.DELETED);
					break;
				}
				case data.tabledata.RowState.INSERTDELETED: {
					rowClasses.push(ufc.Classes.NULLIFIED);
					break;
				}
			}
			return rowClasses;
		}

		/**
		 * 병합 구간(viewRowIndex ~ cellSuppress.suppressLastIndex)에 포함된 행 중
		 * 선택된 행이 하나라도 있으면 true를 반환합니다.
		 * release-test-project#11126
		 */
		public static _isSelectedMergedCell(context: GridContext, viewRowIndex: number, cellSuppress: layout.SuppressCellInfo): boolean {
			let grid: Grid = context.getGrid();
			let isGrouping: boolean = context._isGrouping();
			let virtualRows: provider.VirtualRow[] = isGrouping ? grid._getVirtualRows() : null;
			let lastIndex: number = Math.max(cellSuppress.suppressLastIndex, viewRowIndex);
			let isRowUnit: boolean = (grid.selectionUnit == "row");

			for (let vi: number = viewRowIndex; vi <= lastIndex; vi++) {
				// 그룹핑된 경우 viewRowIndex는 virtual row index이므로 data row index로 변환한다.
				// (그룹행은 dsindex를 가지지 않으므로 자연스럽게 제외된다.)
				let dataRowIndex: number = vi;
				if (isGrouping) {
					let virtualRow: provider.VirtualRow = virtualRows ? virtualRows[vi] : null;
					if (virtualRow == null || !(virtualRow.dsindex >= 0)) {
						continue;
					}
					dataRowIndex = virtualRow.dsindex;
				}

				if (isRowUnit) {
					if (grid._isInstantSelectedRow(dataRowIndex)) {
						return true;
					}
				} else {
					for (let ci: number = cellSuppress.startCellIndex; ci <= cellSuppress.endCellIndex; ci++) {
						if (grid._isInstantSelectedCell(dataRowIndex, ci) || grid._isInstantSelectedColumn(ci)) {
							return true;
						}
					}
				}
			}

			return false;
		}

		public static _getRowGroupExprValue(colProp: GridFooterCellProp, rowgroup: provider.GridRowGroup): (string | number | ufc.StyledString) {
			let value: (string | number | ufc.StyledString) = null;

			if (colProp.configuration.expr) {
				let exprString: string = colProp.configuration.expr;
				if (exprString == null || exprString == "") {
					value = null;
				} else {
					let result: any = GridUtil._getRowGroupExprResult(exprString, rowgroup, colProp);

					if (result === undefined) {
						value = exprString;
					} else if (result instanceof foundation.DecimalType) {
						value = result.toNumber();
					} else {
						value = result;
					}
				}
			}

			return value;
		}

		public static _getRowGroupExprResult(expr: string | expression.Expression, rowgroup: provider.GridRowGroup, colProp: GridFooterCellProp): any {
			if (expr == null || expr == "" || expr == "\"\"" || expr == "''") {
				return "";
			}

			if (typeof (expr) == "string") {
				expr = new cpr.expression.Expression(expr);
			}
			if (expr == null) {
				return "";
			}
			let result: any;
			try {
				let delegates = null;
				if (colProp != null) {
					let context: GridContext = rowgroup.grid.context;
					let gridColumn = new cpr.controls.gridpart.GridRowGroupColumn(context, colProp);
					delegates = [gridColumn, rowgroup, rowgroup.grid, rowgroup.grid.dataSet];
				} else {
					delegates = [rowgroup, rowgroup.grid, rowgroup.grid.dataSet];
				}

				result = expr._evaluateInternal({
					_getExpressionDelegates(): any[] {
						return delegates;
					}
				});
			} catch (e) {
				utils.tryCatch({
					do: () => {
						result = (expr as cpr.expression.Expression)._evaluateInternal({
							_getExpressionDelegates(): any[] {
								return [rowgroup.grid, rowgroup.grid.dataSet];
							}
						});
					}
				});
			}
			return result;
		}

		public static _getDataExprResult(exprString: string, dataControl: data.DataCollection): (string | number | ufc.StyledString) {
			if (exprString == null || exprString == "") {
				return "";
			}
			let value: (string | number) = exprString;
			let expr: cpr.expression.Expression = new cpr.expression.Expression(exprString);
			try {
				let result: any = expr.evaluate(dataControl);
				if (result === undefined) {
					value = exprString;
				} else if (result instanceof foundation.DecimalType) {
					value = result.toNumber();
				} else {
					value = result;
				}
			} catch (e) {
				value = exprString;
			}
			return value;
		}

		public static _getInnerSize(element: HTMLElement): ElSize {
			let size: ElSize = {
				ow: 0, oh: 0, // outter width/height
				iw: 0, ih: 0, // innter width/height
				mh: 0 // min height
			};
			if (!element) {
				return size;
			}
			let height: number = element.clientHeight;
			let width: number = element.clientWidth;

			/**
			 * ComputedStyle의 width는 IE와 Chrome에서 리턴하는 값이 서로 달라(IE는 border와 padding을 뺀 사이즈, Chrome은 border가 포한됨 사이즈)
			 * BoundingClientRect에서 각각의 사이즈를 뺀 값을 innerSize로 계산함
			 */
			let cssStyle: CSSStyleDeclaration = window.getComputedStyle(element);
			size.oh = height
				+ utils.ParamUtil.parseSize(cssStyle.borderTopWidth, 0).size
				+ utils.ParamUtil.parseSize(cssStyle.borderBottomWidth, 0).size;

			size.ih = height
				- utils.ParamUtil.parseSize(cssStyle.paddingTop, 0).size
				- utils.ParamUtil.parseSize(cssStyle.paddingBottom, 0).size;

			size.ow = width
				+ utils.ParamUtil.parseSize(cssStyle.borderLeftWidth, 0).size
				+ utils.ParamUtil.parseSize(cssStyle.borderRightWidth, 0).size;
			size.iw = width
				- utils.ParamUtil.parseSize(cssStyle.paddingLeft, 0).size
				- utils.ParamUtil.parseSize(cssStyle.paddingRight, 0).size;

			size.mh = utils.ParamUtil.parseSize(cssStyle.minHeight, 0).size;

			return size;
		}

		public static _setControlPosition(controlShape: ufc.ControlShape, constraint: ControlConstraint) {
			let isBorderNone: boolean = true;
			if (!controlShape["style"]) {
				controlShape["style"] = {};
			}
			if (constraint) {
				let leftSpacingSize: utils.Size = utils.ParamUtil.parseSize(constraint.leftSpacing, 0);
				let rightSpacingSize: utils.Size = utils.ParamUtil.parseSize(constraint.rightSpacing, 0);
				let topSpacingSize: utils.Size = utils.ParamUtil.parseSize(constraint.topSpacing, 0);
				let bottomSpacingSize: utils.Size = utils.ParamUtil.parseSize(constraint.bottomSpacing, 0);
				let leftSpacing: string = leftSpacingSize.size + leftSpacingSize.unit;
				let rightSpacing: string = rightSpacingSize.size + rightSpacingSize.unit;
				let topSpacing: string = topSpacingSize.size + topSpacingSize.unit;
				let bottomSpacing: string = bottomSpacingSize.size + bottomSpacingSize.unit;
				if (constraint.horizontalAlign == "fill") {
					if (leftSpacing != "0px" || rightSpacing != "0px") {
						let width: string = "100%";
						if (leftSpacing != "0px") {
							controlShape.style["left"] = leftSpacing;
							width += " - " + leftSpacing;
						}
						if (rightSpacing != "0px") {
							width += " - " + rightSpacing;
						}
						if (width != "100%") {
							width = "calc(" + width + ")";
						}
						delete controlShape.style["min-width"];
						controlShape.style["width"] = width;
						isBorderNone = false;
					}
				} else {
					if (constraint.horizontalAlign == "center") {
						controlShape.style["left"] = "calc(50% - (" + constraint.width + " / 2))";
					} else if (constraint.horizontalAlign == "right") {
						if (rightSpacing != "0px") {
							controlShape.style["left"] = "calc(100% - " + constraint.width + " - " + rightSpacing + ")";
						} else {
							controlShape.style["left"] = "calc(100% - " + constraint.width + ")";
						}
					} else if (constraint.horizontalAlign == "left" && leftSpacing != "0px") {
						controlShape.style["left"] = leftSpacing;
					}
					delete controlShape.style["min-width"];
					controlShape.style["width"] = constraint.width;
					isBorderNone = false;
				}

				if (constraint.verticalAlign == "fill") {
					if (topSpacing != "0px" || bottomSpacing != "0px") {
						let height: string = "100%";
						if (topSpacing != "0px") {
							controlShape.style["top"] = topSpacing;
							height += " - " + topSpacing;
						}
						if (bottomSpacing != "0px") {
							height += " - " + bottomSpacing;
						}
						if (height != "100%") {
							height = "calc(" + height + ")";
						}
						delete controlShape.style["min-height"];
						controlShape.style["height"] = height;
						isBorderNone = false;
					}
				} else {
					if (constraint.verticalAlign == "center") {
						controlShape.style["top"] = "calc(50% - (" + constraint.height + " / 2))";
					} else if (constraint.verticalAlign == "bottom") {
						if (bottomSpacing != "0px") {
							controlShape.style["top"] = "calc(100% - " + constraint.height + " - " + bottomSpacing + ")";
						} else {
							controlShape.style["top"] = "calc(100% - " + constraint.height + ")";
						}
					} else if (constraint.verticalAlign == "top" && topSpacing != "0px") {
						controlShape.style["top"] = topSpacing;
					}
					delete controlShape.style["min-height"];
					controlShape.style["height"] = constraint.height;
					isBorderNone = false;
				}
			}

			if (isBorderNone) {
				controlShape.classNames.push("cl-border-none");
				controlShape.style["position"] = "relative";
			} else {
				controlShape.style["position"] = "absolute";
			}
		}

		public static _getControlSize(constraint: ControlConstraint): { width: string, height: string } {
			let result: { width: string, height: string } = { width: "100%", height: "100%" };
			if (constraint) {
				if (constraint.horizontalAlign != "fill") {
					result.width = constraint.width;
				}
				if (constraint.verticalAlign != "fill") {
					result.height = constraint.height;
				}
			}
			return result;
		}

		public static _isGridContainedElement(grid: Grid, element: HTMLElement): boolean {
			return grid._getRenderer()._getRenderedRootNode().contains(element);
		}

		/**
		 * 자동 높이 지원 컨트롤 식별
		 * @param control 
		 */
		public static _isAutoHeightSupportControl(control: UIControl): boolean {
			if (control == null
				|| control instanceof Output
				|| control instanceof TextArea
				|| control instanceof UDCBase
				|| control instanceof HTMLSnippet) {
				return true;
			}
			return false;
		}

		public static _isAutoCellWidthSupportControl(control: UIControl): boolean {
			if (control == null
				|| control instanceof Output
				|| control instanceof TextArea
				|| control instanceof UDCBase
				|| control instanceof HTMLSnippet
				|| control instanceof NumberEditor
				|| control instanceof SearchInput
				|| control instanceof DateInput
				|| control instanceof InputBox
				|| control instanceof MaskEditor
				|| control instanceof ComboBox
			) {
				return true;
			}
			return false;
		}

		public static _isContainedCell(cellBound: { left: number, top: number, width: number, mergeCellWidth: number, height: number },
			range: { start: number, end: number }): boolean {
			if (cellBound.left > range.end ||
				(cellBound.left + cellBound.mergeCellWidth) < range.start) {
				return false;
			}
			return true;
		}

		/**
		 * Window7 Chrome에서 가상 세로 스크롤 변경시 넘어오는 ScrollTop이 소수점을 포함하는 경우가 있어서
		 * 가상 세로 스크롤 이벤트 시 scrollTop을 기존 값과 근사치 이퀄 비교.
		 * Chrome에서 화면 배율을 90%, 125% 등 으로 했을 때(그 이하라도) 오차 범위가 이 이상 커질 경우 다른 방법 모색 필요(20190523)
		 * @param value1 비교값1
		 * @param value2 비교값2
		 */
		public static _equalsApproximately(value1: number, value2: number): boolean {
			return Math.floor(Math.abs(value1 - value2)) <= 1;
		}

		public static _normalizeGroupCondition(groupCondition: string): string {
			if (groupCondition == null) {
				return null;
			}
			let conds: string[] = groupCondition.split(",");
			conds = conds.map((item: string) => {
				return item.trim();
			});

			groupCondition = conds.join(",");

			return groupCondition;
		}

		// release-test-project#6872
		public static _setCellTitle(cellShape: ufc.ElementShape, cellProp: GridCellProp, viewRowIndex?: number): void {
			if (!cellShape || !cellProp) {
				return;
			}
			let cellIndex: number = cellProp.constraint.cellIndex;
			let id = null;
			if (cellProp.configuration instanceof config.GridHeaderCellConfigurator) {
				id = "hc-" + cellIndex;
			} else if (cellProp.configuration instanceof config.GridDetailCellConfigurator) {
				id = "dc-" + viewRowIndex + "-" + cellIndex;
			} else if (cellProp.configuration instanceof config.GridFooterCellConfigurator) {
				id = "fc-" + cellIndex;
			}
			ufc.ShapeUtil._setTooltipAttr(cellShape, { owner: cellProp.configuration._getGrid(), title: cellProp.configuration.tooltip, id: id });
		}

		public static _setRowGroupCellTitle(cellShape: ufc.ElementShape, colProp: GridFooterCellProp, rowgroup: provider.GridRowGroup, cellIndex: number, viewRowIndex?: number): void {
			if (!cellShape || !colProp) {
				return;
			}

			let configuration: config.GridCellConfigurator = colProp.configuration;
			if (!configuration) {
				return;
			}

			let tooltip: string = null;
			let tooltipBindInfo: bind.BindInfo = configuration.getBindInfo("tooltip");
			if (tooltipBindInfo) {
				if (tooltipBindInfo.type === "expression") {
					tooltip = utils.Util.toString(this._getRowGroupExprResult(tooltipBindInfo.expression, rowgroup, colProp));
				} else if (tooltipBindInfo.type === "datacolumn") {
					tooltip = utils.Util.toString(this._getRowGroupExprResult(tooltipBindInfo.columnName, rowgroup, colProp));
				} else {
					tooltip = configuration.tooltip;
				}
			} else {
				tooltip = configuration.tooltip;
			}

			let id = "rgc-" + viewRowIndex + "-" + cellIndex;
			ufc.ShapeUtil._setTooltipAttr(cellShape, { owner: configuration._getGrid(), title: tooltip, id: id });
		}

		public static _getFooterValue(context: GridContext, colProp: GridFooterCellProp): string | ufc.StyledString {
			let exprString = colProp.configuration.expr;
			if (exprString == null || exprString == "") {
				return "";
			}
			let text: string = exprString;
			let expr: cpr.expression.Expression = new cpr.expression.Expression(exprString);
			try {
				let grid: Grid = context.getGrid();
				let gridColumn = new cpr.controls.gridpart.GridFooterColumn(context, colProp);

				let result: any = expr._evaluateInternal({
					_getExpressionDelegates(): any[] {
						return [gridColumn, grid.dataProvider, grid, grid.dataSet];
					}
				});
				if (result === undefined) {
					text = exprString;
				} else if (result == null) {
					text = "";
				} else if (result instanceof foundation.DecimalType) {
					text = result.toString();
				} else {
					text = result;
				}
			} catch (e) {
				text = exprString;
			}
			return text;
		}

		/**
		 * studio(사용자) 기준
		 * (우선순위 : rowIndex, colIndex)
		 */
		public static _rowFirstSort(current: GridCellProp | GridCellConfig, next: GridCellProp | GridCellConfig): number {
			if (current.constraint.rowIndex == next.constraint.rowIndex) {
				return current.constraint.colIndex - next.constraint.colIndex;
			}
			return current.constraint.rowIndex - next.constraint.rowIndex;
		}
		/**
		 * runtime 기준 (내부 사용)
		 * (우선순위 : colIndex, rowIndex)
		 */
		public static _colFirstSort(current: GridCellProp | GridCellConfig, next: GridCellProp | GridCellConfig): number {
			if (current.constraint.colIndex == next.constraint.colIndex) {
				return current.constraint.rowIndex - next.constraint.rowIndex;
			}
			return current.constraint.colIndex - next.constraint.colIndex;
		}

		/**
		 * 셀의 aria-label 반환.
		 * 현재 div(role=gridcell)의 aria-label은 음성출력되지 않음.
		 */
		public static _getCellAriaLabel(grid: Grid
			, colProp: GridDetailCellProp
			, gridRow: provider.GridRow
			, ariaRowIndex: number
			, ariaColIndex: number
			, altText: string
			, altColumnName: string
			, isSelectedCell: boolean): string {

			let gridColumn: GridDetailColumn = grid.detail.getColumn(colProp.constraint.cellIndex);
			gridColumn._setAriaColIndex(ariaColIndex);
			gridColumn._setSupportIgnoreDefaultFieldLabel(true);
			let fieldLabel: string = "";
			if (gridColumn.control) {
				fieldLabel = "" + gridColumn.control.fieldLabel;
			}
			if (utils.Util.isNullOrEmpty(fieldLabel)) {
				fieldLabel = "" + colProp.configuration.fieldLabel;
			}
			gridColumn._setSupportIgnoreDefaultFieldLabel(false);
			if (gridColumn._isAriaLabelOnly()) {
				gridColumn._setAriaLabelOnly(false);
				return fieldLabel;
			}

			let labelString: string[] = [];

			if (isSelectedCell) {
				labelString[labelString.length] = "" + I18N.INSTANCE.message(core.PlatformTerms.SELECTED);
			}

			if (grid._isAriaLabelCellPosition()) {
				labelString[labelString.length] = "" + ariaRowIndex + I18N.INSTANCE.message(core.PlatformTerms.ROW);
				labelString[labelString.length] = "" + ariaColIndex + I18N.INSTANCE.message(core.PlatformTerms.COLUMN);
			}

			let control: GridUIControl = colProp.configuration.control;
			if (control) {
				if (utils.Util.isNullOrEmpty(control.fieldLabel) == false) {
					labelString[labelString.length] = "" + control.fieldLabel;
				} else {
					if (utils.Util.isNullOrEmpty(colProp.configuration.fieldLabel) == false) {
						labelString[labelString.length] = "" + colProp.configuration.fieldLabel;
					}
				}
				if (control.type == "image") {
					let alt: string = (control as Image).alt;
					if (alt && alt != "") {
						labelString[labelString.length] = alt;
					}
				} else if ((control.type == "checkbox" && (control as CheckBox).checked) || control.type != "checkbox") {
					let text: string | ufc.StyledString = altText == null ? control.text : altText;
					if (text && text != "") {
						labelString[labelString.length] = ufc.StyledString._asString(text);
					}
				}

			} else if (colProp.configuration.columnType == "rowindex") {
				let rowIndex: number = (gridRow != null) ? gridRow.getIndex() : 0;
				labelString[labelString.length] = cpr.I18N.INSTANCE.message(core.PlatformTerms.ROW_NUMBER) + " " + (rowIndex + grid.rowIndexerStartNum);
			} else if (colProp.configuration.columnType == "checkbox" || colProp.configuration.columnType == "radio") {
				let rowIndex: number = (gridRow != null) ? gridRow.getIndex() : 0;
				let checked: boolean = false;
				if (colProp.configuration.columnType == "checkbox") {
					checked = (gridRow != null) ? gridRow.rowChecked : false;
				} else if (colProp.configuration.columnType == "radio") {
					checked = (gridRow != null) ? gridRow.rowRadioSelected : false;
				}
				if (checked) {
					labelString[labelString.length] = "" + (rowIndex + grid.rowIndexerStartNum) + I18N.INSTANCE.message(core.PlatformTerms.ROW_CHECKED);
				} else {
					labelString[labelString.length] = "" + (rowIndex + grid.rowIndexerStartNum) + I18N.INSTANCE.message(core.PlatformTerms.ROW_CHECK);
				}
			} else {
				if (altText != null) {
					labelString[labelString.length] = altText;
				} else {
					if (utils.Util.isNullOrEmpty(colProp.configuration.fieldLabel) == false) {
						labelString[labelString.length] = "" + colProp.configuration.fieldLabel;
					}
					if (altColumnName != null) {
						labelString[labelString.length] = "" + gridRow.getValue(altColumnName);
					} else if (colProp.configuration.columnName != null) {
						labelString[labelString.length] = "" + gridRow.getValue(colProp.configuration.columnName);
					}
				}
			}
			return labelString.join(" ");
		}

		/**
		 * empty cell aria-label의 경우 사용자 지정 aria-label(fieldLabelOnly)이 설정된 경우
		 * 사용자 지정 aria-label에 컨트롤 값을 포함하여 empty cell의 aria-label로 지정합니다.
		 * (div(gridcell)의 label-label을 읽지 못하는 현상으로 인해 위와같이 처리)
		 */
		public static _getEmptyCellAriaLabel(grid: Grid
			, colProp: GridDetailCellProp
			, gridRow: provider.GridRow
			, ariaColIndex: number
			, altText: string
			, altColumnName: string): string {

			let labelString: string[] = [];
			let control: GridUIControl = colProp.configuration.control;

			let gridColumn: GridDetailColumn = grid.detail.getColumn(colProp.constraint.cellIndex);
			gridColumn._setAriaColIndex(ariaColIndex);
			gridColumn._setSupportIgnoreDefaultFieldLabel(true);
			let fieldLabel: string = null;
			if (gridColumn.control) {
				fieldLabel = "" + gridColumn.control.fieldLabel;
			}
			if (utils.Util.isNullOrEmpty(fieldLabel)) {
				fieldLabel = "" + colProp.configuration.fieldLabel;
			}
			gridColumn._setSupportIgnoreDefaultFieldLabel(false);
			if (gridColumn._isAriaLabelOnly()) {
				gridColumn._setAriaLabelOnly(false);
				if (!utils.Util.isNullOrEmpty(fieldLabel)) {
					labelString[labelString.length] = fieldLabel;
				}
			} else {
				if (control && utils.Util.isNullOrEmpty(control.fieldLabel) == false) {
					labelString[labelString.length] = "" + control.fieldLabel;
				} else {
					if (utils.Util.isNullOrEmpty(colProp.configuration.fieldLabel) == false) {
						labelString[labelString.length] = "" + colProp.configuration.fieldLabel;
					}
				}
			}

			if (control) {
				if (control.type == "image") {
					let alt: string = (control as Image).alt;
					if (alt && alt != "") {
						labelString[labelString.length] = alt;
					}
				} else if ((control.type == "checkbox" && (control as CheckBox).checked) || control.type != "checkbox") {
					let text: string | ufc.StyledString = altText == null ? control.text : altText;
					if (text && text != "") {
						labelString[labelString.length] = ufc.StyledString._asString(text);
					}
				}

			} else if (colProp.configuration.columnType == "rowindex") {
				let rowIndex: number = (gridRow != null) ? gridRow.getIndex() : 0;
				labelString[labelString.length] = cpr.I18N.INSTANCE.message(core.PlatformTerms.ROW_NUMBER) + " " + (rowIndex + grid.rowIndexerStartNum);

			} else if (colProp.configuration.columnType == "checkbox" || colProp.configuration.columnType == "radio") {
				let rowIndex: number = (gridRow != null) ? gridRow.getIndex() : 0;
				let checked: boolean = false;
				if (colProp.configuration.columnType == "checkbox") {
					checked = (gridRow != null) ? gridRow.rowChecked : false;
				} else if (colProp.configuration.columnType == "radio") {
					checked = (gridRow != null) ? gridRow.rowRadioSelected : false;
				}
				if (checked) {
					labelString[labelString.length] = "" + (rowIndex + grid.rowIndexerStartNum) + I18N.INSTANCE.message(core.PlatformTerms.ROW_CHECKED);
				} else {
					labelString[labelString.length] = "" + (rowIndex + grid.rowIndexerStartNum) + I18N.INSTANCE.message(core.PlatformTerms.ROW_CHECK);
				}

			} else { // default cell
				if (altText != null) {
					labelString[labelString.length] = altText;
				} else {
					// if (utils.Util.isNullOrEmpty(colProp.configuration.fieldLabel) == false) {
					// 	labelString[labelString.length] = "" + colProp.configuration.fieldLabel;
					// }
					if (altColumnName != null) {
						labelString[labelString.length] = "" + gridRow.getValue(altColumnName);
					} else if (colProp.configuration.columnName != null) {
						labelString[labelString.length] = "" + gridRow.getValue(colProp.configuration.columnName);
					}
				}
			}
			return labelString.join(" ");
		}

		public static _getCellControlEnabled(colProp: GridDetailCellProp): boolean {
			let control: GridUIControl = colProp.configuration.control;
			if (control?.enabled === false) {
				return false;
			} else {
				return true;
			}
		}
		public static _getCellControlReadOnly(colProp: GridDetailCellProp): boolean {
			let control: GridUIControl = colProp.configuration.control;
			if (control?.readOnly === true) {
				return true;
			} else {
				return false;
			}
		}

		/**
		 * 그리드의 웹 접근성 속성을 설정합니다.
		 * @param shape 
		 * @param propertyName 값을 지정할 ARIA 속성 명. "aria-" 접두어는 생략할 수 있습니다.
		 * @param propertyValue 지정할 속성 값. 
		 */
		public static _setAria(shape: ufc.ElementShape, propertyName: string, propertyValue: string): void {
			if (shape.hasOwnProperty("attr") == false) {
				shape.attr = {};
			}
			let attr: { [key: string]: string } = {};
			attr["aria-" + propertyName] = propertyValue;
			shape.attr = _assign(shape.attr, attr);
		}

		/**
		 * 컨트롤 shape에 styler와 bindContext를 지정합니다.
		 * @param shape 
		 * @param styler 
		 * @param bindContext 
		 */
		public static _applyControlStyler(shape: ufc.ElementShape, styler: UIControlStyler, bindContext: bind.BindContext): void {
			if (bindContext != null) {
				styler._setBindContext(bindContext);
			}
			shape.classNames = shape.classNames.concat(styler.getClasses());
			shape.style = _mergeObject(styler.css(), shape.style);
		}

		/**
		 * shape에 acessbility를 설정합니다.
		 * @param shape  
		 * @param control 
		 * @param aria 
		 * @param bindContext 
		 */
		public static _applyControlAccessbility(shape: ufc.ElementShape, control: UIControl, aria: string, bindContext: bind.BindContext): void {
			let resolvedAccessibility = control.accessibility[aria] as controls.Accessibility || control.accessibility;
			resolvedAccessibility._commitToShape({
				shape: shape,
				bindContext: bindContext
			})
		}

		/**
		 * display:table-cell인 div에 그려진 text shape을 반환합니다.
		 * @param text 그려질 text
		 * @param cellHeight cell 높이 (option.maxHeight)
		 * @param textStyle class와 css style
		 * @returns 
		 */
		public static _getTextShape(text: (string | ufc.StyledString), cellHeight: number, textStyle?: { classNames?: string[], style?: { [key: string]: string } }): ufc.ElementShape {
			let classNames: string[] = [];
			let style: { [key: string]: string } = {};
			if (textStyle != null) {
				classNames = (textStyle.classNames) ? textStyle.classNames : classNames;
				style = (textStyle.style) ? textStyle.style : style;
			}

			let shape: ufc.ElementShape = {
				tag: "div",
				classNames: [ufc.Classes.TEXT].concat(classNames),
				style: _mergeObject({
					width: "100%",
					display: "table-cell"
				}, style),
				children: ufc.StyledString._asShape(text)
			};
			if (cellHeight >= 0) {
				shape.style["height"] = "100%";
				shape.style["max-height"] = cellHeight + "px";
			}

			return shape;
		}

		public static _defaultMatcher: (targetData: string, filterText: string) => boolean = (label: string, filterText: string) => {
			if (label && label.indexOf(filterText) > -1) {
				return true;
			}
			return false;
		}

		/**
		 * 현재 뷰포트에서의 그리드 element 위치 정보
		 */
		public static _getContainerRect(grid: Grid, region: string, loc: string): geometry.Rectangle {
			let gridElement: HTMLElement = grid._getRenderer().getRootNode();
			let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(gridElement);
			domTraverser = domTraverser._child(`[data-role="${GRIDROLE.GROUP}"][data-region="${region}"]`);
			if (domTraverser == null) {
				return null;
			}
			domTraverser = domTraverser._child(`[data-role="${GRIDROLE.ROWGROUP}"][data-loc="${loc}"]`);
			if (domTraverser == null) {
				return null;
			}
			domTraverser = domTraverser._child(`[data-role='scroll-container']`);
			if (domTraverser == null) {
				return null;
			}
			let element = domTraverser._getElement();
			let rect: geometry.Rectangle = GridUtil._getUnsetZoomByClientRect(element);
			return rect;
		}

		public static _isLastContent(grid: Grid, renderStartRowIndex: number, renderEndRowIndex: number, region: string, loc: string): boolean {
			let context: GridContext = grid.context;
			let contentStartRowIndex: number = context._getStartRowIndex(loc);
			let contentEndRowIndex: number = context._getEndRowIndex(loc);
			let gridLayout: layout.GridControlLayout = grid.getLayout() as layout.GridControlLayout;
			let tablePane: gridpart.layout.TablePane = gridLayout._getTablePane(region);
			let scrollPane: gridpart.layout.ScrollPane = tablePane._getScrollPane(loc);
			if (scrollPane == null) {
				return false;
			}

			let scrollTop: number = scrollPane._getBusScollTop();
			let maxScrollTop: number = scrollPane._getMaxScrollTop();
			if (loc == GRIDREGION.MIDDLE
				&& renderStartRowIndex > 0
				&& contentEndRowIndex == renderEndRowIndex
				&& contentStartRowIndex < renderStartRowIndex
				&& scrollTop == maxScrollTop) { // 여백이 있는지 없는지 체크 필요
				grid._keepContentDataRowIndex();
				let totalRowHeight: number = 0;
				for (let rowIndex: number = renderStartRowIndex; rowIndex <= renderEndRowIndex; rowIndex++) {
					let gridRow: provider.GridRow = grid.getDataRow(rowIndex);
					if (gridRow) {
						grid._setContentDataRowIndex(rowIndex, -1); // row context 설정
						let rowHeights: number[] = context._getDataRowHeight(rowIndex, loc);
						let rowHeight: number = utils.Util.sum(rowHeights);
						totalRowHeight += rowHeight;
					}
				}
				grid._restoreContentDataRowIndex();

				let height: number = grid.context._getLocationHeight(loc);
				if (totalRowHeight < height) {
					return true;
				}
			}
			return false;
		}

		/**
		 * 해당 element의 zoom이 unset된 getBoundingClientRect를 반환합니다.
		 */
		public static _getUnsetZoomByClientRect(element: HTMLElement): geometry.Rectangle {
			return _getUnscaledClientRect(element);
		}
	}
