

namespace cpr.protocols.response {


	/**
	 * @private
	 */
	export class ResponseDecoderParser implements ResponseParser {
		private _responseDecoder: ResponseDecoder;
		private _submission: AbstractSubmission;
		private _doneHandler: () => void;


		constructor(responseDecoder: ResponseDecoder) {
			this._responseDecoder = responseDecoder;
		}

		public load(submission: AbstractSubmission, xhr: XMLHttpRequest): void {
			// do nothing
		}

		public _abortLoading(submission: AbstractSubmission): void {
			// do nothing
		}

		public _parseData(submission: AbstractSubmission, data: {} | string, doneHandler: () => void): void {
			throw new exceptions.UnsupportedOperationException("parseData");
		}

		public parse(submission: AbstractSubmission, xhr: XMLHttpRequest, doneHandler: () => void): void {
			this._submission = submission;
			this._doneHandler = doneHandler;

			let responseType: string = xhr.responseType;
			if (responseType == "blob") {
				let handler: BlobResponseHandler = new BlobResponseHandler((ev: ProgressEvent, stringData: string) => {
					this._doDecodeProcess(stringData);
				});
				handler._setParseErrorHandler((err: Error) => {
					this._submission._onError(err);
				});
				handler._setLoaderrorHandler((ev: ProgressEvent) => {
					this._submission._onProgressError(ev);
				});
				handler._load(xhr.response as Blob);
			} else {
				let stringData: string = xhr.responseText;
				this._doDecodeProcess(stringData);
			}
		}

		private _doDecodeProcess(stringData: string): void {
			let returnValue: Promise<DecodingResult> | DecodingResult = null;
			try {
				returnValue = this._responseDecoder(this._submission as Submission, stringData);
			} catch (err) {
				this._submission._onError(err);
				return;
			}
			if (returnValue instanceof Promise) {
				returnValue.then((decodingResult: DecodingResult) => {
					this._doParse(decodingResult);
				}).catch((err: Error) => {
					this._submission._onError(err);
				});
			} else {
				this._doParse(returnValue);
			}
		}

		private _doParse(decodingResult: DecodingResult): void {
			if (!decodingResult) {
				this._doneHandler();
				return;
			}
			let contentType: string = decodingResult.contentType;
			let content: {} | string = decodingResult.content;

			let dataModel: ProtocolDataModel = this._submission._getProtocolDataModel();
			let responseParser: ResponseParser = dataModel._getContentParser(contentType, "");

			if (responseParser) {
				responseParser._parseData(this._submission, content, this._doneHandler);
			}
		}

	}
}