

namespace cpr.controls.internal {

	/**
	 * @private
	 */
	export class NativeVScrollbar implements IVirtualVScrollbar {
		private _scrollPane: internal.IVirtualScrollPane;
		private _passiveScrollTop: number = -1;


		constructor(scrollPane: internal.IVirtualScrollPane) {
			this._scrollPane = scrollPane;
		}

		public _getWidth(): number {
			return ScrollbarUtil._getNativeScrollWidth();
		}

		public _getScrollTop(): number {
			let scrollElement: HTMLElement = this._scrollPane._getRenderer().getNamedNode(this._scrollPane._getQName("vscroll"));
			if (scrollElement) {
				return scrollElement.scrollTop;
			}
			return -1;
		}

		public _setScrollTop(scrollTop: number): void {
			let scrollElement: HTMLElement = this._scrollPane._getRenderer().getNamedNode(this._scrollPane._getQName("vscroll"));
			if (scrollElement && scrollElement.scrollTop != scrollTop) {
				scrollElement.scrollTop = scrollTop;
			}
			this._passiveScrollTop = scrollTop;
		}

		public _createScrollbar(contentScrollTop: number, contentHeight: number): ufc.ElementShape {
			// IE에서 스크롤을 제외한 viewport를 표시할 수 있는 1px이상이 없으면 스크롤 버튼이 동작하지 않음.
			let vScrollViewPort: ufc.ElementShape = {
				tag: "div",
				attr: {},
				style: {
					width: "1px",
					height: contentHeight + "px"
				},
				innerHTML: "&nbsp;"// mobile safari에서 불특정한 경우에 영역이 할당되지 못하는 문제 때문에 빈값을 넣어 줌
			};
			let vScrollPane: ufc.ElementShape = {
				tag: "div",
				attr: {},
				classNames: ScrollbarUtil._getScrollPaneClasses(),
				style: {
					"overflow-X": "hidden",
					"overflow-Y": "scroll",
					position: "relative",
					width: "100%",
					height: "100%"
				},
				nodename: this._scrollPane._getQName("vscroll"),
				mandatoryEvents: {
					scroll: _.throttle((e: events.CUIEvent) => { this._onVirtualVScroll(e); }, 50, { leading: false }) // throttling 적용
				},
				children: [vScrollViewPort]
			}
			if (_detectBrowser().name == "ie") {
				vScrollPane.attr["unselectable"] = "on"; // IE에서 글로벌로 표시했을때 스크롤 클릭시 초점이 스크롤로 이동되는 현상 방지. (CSS로는 방지가 안됨)
			}
			// IE에서 ScrollBar에 BackgroundColor를 설정했을 때 ScrollBar가 보이지 않아 relative로 감쌈.
			let vScroll: ufc.ElementShape = {
				tag: "div",
				attr: {},
				classNames: [controls.gridpart.GridStyle.BLANK, "cl-vscrollbar"],
				style: {
					"box-sizing": "border-box",
					"overflow": "hidden",
					position: "absolute",
					top: "0px",
					right: "0px",
					width: ScrollbarUtil._getNativeScrollWidth() + "px"
				},
				children: [vScrollPane]
			};
			return vScroll;
		}
		// event handlers
		private _onVirtualVScroll(e: events.CUIEvent): void {
			// Grid 내부에서 이벤트의 중앙 통제 필요. requestAnimationFrame를 사용한 빈도 조절 고려 필요.
			let target: HTMLElement = <HTMLElement>e.target;
			let scrollTop: number = target.scrollTop;

			// Chrome에서 화면 배율을 90%, 125% 등 으로 했을 때(그 이하라도) scrollposition이 소수점으로 넘어옴(20200213)
			if (this._passiveScrollTop === -1 || gridpart.GridUtil._equalsApproximately(this._passiveScrollTop, scrollTop) == false) {
				this._passiveScrollTop = -1;
				this._scrollPane._setScrollTop(e, scrollTop);
			}
		}
	}

}