/// <reference path="./AbstractXYLayout.ts"/>
/// <reference path="../UIControl.ts"/>


namespace cpr.controls.layouts {
	export interface XYLayoutConstraint extends Constraint {
		/**
		 * 너비
		 */
		width?: string;

		/**
		 * 높이
		 */
		height?: string;

		/**
		 * 컨테이너의 상단과 컨트롤 상단 사이의 거리
		 */
		top?: string;

		/**
		 * 컨테이너의 하단과 컨트롤 하단 사이의 거리
		 */
		bottom?: string;

		/**
		 * 컨테이너의 좌변과 컨트롤 좌변 사이의 거리
		 */
		left?: string;

		/**
		 * 컨테이너의 우변과 컨트롤의 우변 사이의 거리
		 */
		right?: string;
	}

	const DEFAULT_CONSTRAINT: XYLayoutConstraint = {};

	export class XYLayout extends AbstractXYLayout<XYLayoutConstraint> {


		constructor() {
			super();
			this._initLayout();
		}

		protected override _getType(): LayoutType {
			return LayoutType.XY_LAYOUT
		}

		/**
		 * rectangle 객체를 이용하여 XY 레이아웃의 컨스트레인트 객체를 만듭니다.
		 * @param rect 컨스트레인트 객체를 만들 사각형 정보 객체.
		 */
		public static createConstraintWithRect(rect: geometry.Rectangle): XYLayoutConstraint {
			return {
				left: `${rect.left}px`,
				top: `${rect.top}px`,
				width: `${rect.width}px`,
				height: `${rect.height}px`
			}
		}

		protected _getLayoutShapeStyle() {
			// let overflowX = this.scrollable ? "auto" : this._getOverflowXForNonScroll();
			// let overflowY = this.scrollable ? "auto" : this._getOverflowYForNonScroll();

			return {
				position: "relative", /* 패딩이 적용되려면 필요함. */
				left: "0px",
				top: "0px",
				right: "0px",
				bottom: "0px",
				width: "100%",
				height: "100%",
				minHeight: "inherit",
				minWidth: "inherit",
				boxSizing: "content-box",
				overflowX: this.scrollable ? "auto" : this._getOverflowXForNonScroll(),
				overflowY: this.scrollable ? "auto" : this._getOverflowYForNonScroll()
				// overflow: `${overflowX} ${overflowY}`
			}
		}


		/**
		 * @override
		 */
		public _doDecorateChild(context: LayoutDecorationContext<XYLayoutConstraint>): ufc.ControlShape {
			let constraint = context.constraint;
			let controlShape = context.controlShape;
			controlShape.style = _mergeObject(controlShape.style, {
				position: "absolute"
			}, this._getAnimatingProperties(), constraint);
			return controlShape;
		}

		protected applyConstraint(index: number, control: UIControl, controlRenderer: ufc.ControlRenderer): ufc.ControlRenderer {
			controlRenderer.addLayoutDecorator(this._createLayoutDecorator(control));
			return controlRenderer;
		}

		/**
		 * @param controls 
		 */
		protected _doUpdateControl(controls: UIControl[]): void {
			controls.forEach((control: UIControl) => {
				control._applyPiece(new ufc.CustomPieceRenderer((renderer: ufc.ControlRenderer) => {
					if (!renderer) {
						return;
					}

					let constraint: layouts.Constraint = (this._owner as Container).getConstraint(control); // 항상 최신 Constraints를 반영하도록
					let layoutStyles = _assign(
						{},
						Layout.EMPTY_LAYOUT_STYLES,
						this._normalizeConstraint(constraint)
					);

					if (renderer.updateStyle(null, layoutStyles, true)) {
						this._fireChildResizeEvent(control);
					}
				}));
			});
		}

		/**
		 * @override
		 */
		protected _compareConstraint(a: XYLayoutConstraint, b: XYLayoutConstraint): boolean {
			return a.top == b.top
				&& a.right == b.right
				&& a.bottom == b.bottom
				&& a.left == b.left
				&& a.width == b.width
				&& a.height == b.height;
		}


		/**
		 * @override
		 */
		public _compareConstraintOrder(a: UIControl, b: UIControl) {
			let boundsA = a.getActualRect();
			let boundsB = b.getActualRect();
			let gapY = boundsA.top - boundsB.top;
			if (gapY !== 0) {
				return gapY;
			}
			return boundsA.left - boundsB.left;
		}


		/**
		 * @override
		 */
		public _getDefaultConstraint() {
			return DEFAULT_CONSTRAINT;
		}

		/** @override */
		public _getRenderedLayoutInfo(): RenderedLayoutInfo {
			return {
				layoutNodeName: LayoutConstants.NODE_NAME__LAYOUT,
				scrollingNodeName: LayoutConstants.NODE_NAME__LAYOUT,
				contentPaneNodeName: LayoutConstants.NODE_NAME__CONTENT_PANE,
				offsetIndexForChildren: 0
			}
		}

		public _getAutoSizeType(constraint: XYLayoutConstraint) {
			if (_.isEmpty(constraint)) {
				return AutoSizeType.none;
			}

			let hasAutoWidth = (constraint.width == null || constraint.width == "auto") && !(constraint.left && constraint.right);
			let hasAuthHeight = (constraint.height == null || constraint.height == "auto") && !(constraint.top && constraint.bottom);
			if (hasAuthHeight && hasAuthHeight) {
				return AutoSizeType.both;
			} else if (hasAutoWidth) {
				return AutoSizeType.width;
			} else if (hasAuthHeight) {
				return AutoSizeType.height;
			} else {
				return AutoSizeType.none;
			}
		}

		protected override _normalizeConstraint(constraint: XYLayoutConstraint): XYLayoutConstraint {
			["top", "right", "bottom", "left", "width", "height"].filter(prop => {
				return typeof constraint?.[prop] == "number"
			}).forEach(prop => {
				constraint[prop] = `${constraint[prop]}px`
			});
			return constraint;
		}
	}
}