namespace cpr.data.header {
	export enum HeaderType {
		/**
		 * 원본 값과 현재 값을 따로 관리하고, 해당 컬럼의 값 변경시 행 상태에 영향을 끼칩니다.
		 */
		ORIGINAL_COLUMN = 0b01,
		/**
		 * 현재 값만 가지고 있고, 해당 컬럼의 값 변경시 행 상태에 영향을 끼치지 않습니다.<br>
		 * (현재 값만 가지고 있기 때문에 commit, revert 등의 작업이 수행되지 않습니다.)
		 */
		DISPLAY_COLUMN = 0b10,

		ALL = 0b11
	}


	export abstract class Header {
		protected _name: string;
		protected _datatype: tabledata.DataType;
		protected _columntype: HeaderType;
		protected _defaultValue: (string | number);
		protected _info: string;
		private _userAttributes: controls.internal.UserAttributes;


		/**
		 * 데이터셋의 헤더를 생성합니다.
		 * @param name 헤더명.
		 * @param datatype 데이터 타입. <br>
		 * 	cpr.data.tabledata.DataType.STRING = "string";<br>
		 * 	cpr.data.tabledata.DataType.NUMBER = "number";<br>
		 * 	cpr.data.tabledata.DataType.DECIMAL = "decimal";<br>
		 * 	cpr.data.tabledata.DataType.EXPRESSION = "expression";<br>
		 * @param columntype 해당 컬럼 타입 <br>
		 * 	cpr.data.header.HeaderType.ORIGINAL_COLUMN : 원본 값과 현재 값을 따로 관리하고, 해당 컬럼의 값 변경시 행 상태에 영향을 끼칩니다.<br>
		 * 	cpr.data.header.HeaderType.DISPLAY_COLUMN : 현재 값만 가지고 있고, 해당 컬럼의 값 변경시 행 상태에 영향을 끼치지 않습니다.<br>
		 * @param defaultValue 기본값.
		 */
		constructor(name: string, datatype: tabledata.DataType, columntype: HeaderType = HeaderType.ORIGINAL_COLUMN, defaultValue?: (string | number)) {
			this._name = name;
			let datatypeStr: string = utils.Util.toString(datatype).toLowerCase();
			this._datatype = datatypeStr;
			this._columntype = columntype;
			this._defaultValue = defaultValue;
		}

		/**
		 * 컬럼 타입을 설정합니다.
		 * @param columnType 컬럼 타입.
		 * 	cpr.data.header.HeaderType.ORIGINAL_COLUMN : 원본 값과 현재 값을 따로 관리하고, 해당 컬럼의 값 변경시 행 상태에 영향을 끼칩니다.<br>
		 * 	cpr.data.header.HeaderType.DISPLAY_COLUMN : 현재 값만 가지고 있고, 해당 컬럼의 값 변경시 행 상태에 영향을 끼치지 않습니다.<br>
		 * @deprecated 2018.11.05 API 통일화 작업. 사용자 제공 API 아님.
		 */
		set columnType(columnType: HeaderType) {
			this._columntype = columnType;
		}

		/**
		 * @private
		 * 컬럼 타입을 설정합니다.
		 * @param columnType 컬럼 타입.
		 * 	cpr.data.header.HeaderType.ORIGINAL_COLUMN : 원본 값과 현재 값을 따로 관리하고, 해당 컬럼의 값 변경시 행 상태에 영향을 끼칩니다.<br>
		 * 	cpr.data.header.HeaderType.DISPLAY_COLUMN : 현재 값만 가지고 있고, 해당 컬럼의 값 변경시 행 상태에 영향을 끼치지 않습니다.<br>
		 */
		public _setColumnType(columnType: HeaderType) {
			// ?? : 동적으로 column type을 바꾸는 것이 가능해야 될까? (181115)
			this._columntype = columnType;
		}

		/**
		 * 기본 값을 설정합니다.
		 * @param defaultValue
		 * @deprecated 2018.11.05 API 통일화 작업. 사용자 제공 API 아님.
		 */
		set defaultValue(defaultValue: (string | number)) {
			this._defaultValue = defaultValue;
		}

		/**
		 * @private
		 * 기본 값을 설정합니다.
		 * @param defaultValue
		 */
		public _setDefaultValue(defaultValue: (string | number)) {
			this._defaultValue = defaultValue;
		}

		/**
		 * @private
		 * 기본 값을 반환합니다.
		 */
		public _getDefaultValue(): (string | number) {
			return this._defaultValue;
		}

		/**
		 * 컬럼 정보값을 설정합니다.
		 * @param info 설정할 정보값
		 * @deprecated 2018.11.05 API 통일화 작업. {@link setInfo}를 사용하시기 바랍니다.
		 */
		set info(info: string) {
			this._info = info;
		}

		/**
		 * 컬럼 정보값을 설정합니다.
		 * @param info 설정할 정보값
		 */
		public setInfo(info: string) {
			this._info = info;
		}

		/**
		 * 컬럼 정보값을 반환합니다.
		 * @return 정보값.
		 * @deprecated 2018.11.05 API 통일화 작업. {@link getInfo}를 사용하시기 바랍니다.
		 */
		get info(): string {
			return this._info;
		}

		/**
		 * 컬럼 정보값을 반환합니다.
		 * @return 정보값.
		 */
		public getInfo(): string {
			return this._info;
		}

		/**
		 * 이름을 반환합니다.
		 * @readonly
		 */
		public getName(): string {
			return this._name;
		}

		/**
		 * 데이터 타입을 반환합니다.
		 * @return 데이터 타입. <br>
		 * 	cpr.data.tabledata.DataType.STRING = "string";<br>
		 * 	cpr.data.tabledata.DataType.NUMBER = "number";<br>
		 * 	cpr.data.tabledata.DataType.DECIMAL = "decimal";<br>
		 * 	cpr.data.tabledata.DataType.EXPRESSION = "expression";<br>
		 * @readonly
		 */
		public getDataType(): tabledata.DataType {
			return this._datatype;
		}

		/**
		 * 컬럼 타입을 반환합니다.
		 * @return 컬럼 타입 <br>
		 * 	cpr.data.header.HeaderType.ORIGINAL_COLUMN : 원본 값과 현재 값을 따로 관리하고, 해당 컬럼의 값 변경시 행 상태에 영향을 끼칩니다.<br>
		 * 	cpr.data.header.HeaderType.DISPLAY_COLUMN : 현재 값만 가지고 있고, 해당 컬럼의 값 변경시 행 상태에 영향을 끼치지 않습니다.<br>
		 * @readonly
		 */
		public getColumnType(): HeaderType {
			return this._columntype;
		}

		/**
		 * @private
		 */
		public _isDisplayHeader(): boolean {
			if (this._columntype == HeaderType.DISPLAY_COLUMN) {
				return true;
			}
			return false;
		}

		/**
		 * @private
		 */
		public _isExpressionHeader(): boolean {
			if (this.getDataType() == tabledata.DataType.EXPRESSION) {
				return true;
			}
			return false;
		}

		//// userAttributes start ///
		/**
		 * 사용자 정의 속성을 지정합니다.
		 * @param key 지정할 속성명
		 * @param value 지정할 속성 값.
		 */
		public userAttr(key: string, value: string);
		/**
		 * 사용자 정의 속성을 반환합니다.
		 * @param key 얻을 속성 이름.
		 * @return 사용자 정의 속성.
		 */
		public userAttr(key: string): string;
		/**
		 * 한번에 여러 사용자 정의 속성을 지정합니다.
		 * @param values 사용자 정의 속성 키/값을 담은 JSON 객체.
		 */
		public userAttr(values: { [key: string]: string });
		/**
		 * 모든 사용자 정의 속성을 맵 형태로 얻습니다.
		 */
		public userAttr(): { [key: string]: string };
		/**
		 * 사용자 정의 속성을 반환합니다.
		 * @return 사용자 정의 속성.
		 */
		public userAttr() {
			let args = _toArray(arguments);
			if (!this._userAttributes) {
				this._userAttributes = new controls.internal.UserAttributes();
			}
			return this._userAttributes.userAttr.apply(this._userAttributes, args);
		}

		/**
		 * 특정 속성 명의 사용자 정의 속성을 제거합니다.
		 * @param key 제거할 사용자 정의 속성 명.
		 */
		public removeUserAttr(key: string): void {
			if (this._userAttributes) {
				this._userAttributes.removeUserAttr(key);
			}
		}

		/**
		 * 모든 사용자 정의 속성들을 삭제합니다.
		 */
		public removeAllUserAttr(): void {
			if (this._userAttributes) {
				this._userAttributes.removeAllUserAttr();
			}
		}

		/**
		 * 모든 사용자 정의 속성 명을 반환합니다.
		 * @return 모든 사용자 정의 속성 명의 배열.
		 */
		public getUserAttrNames(): string[] {
			if (this._userAttributes) {
				return this._userAttributes.getUserAttrNames()
			} else {
				return [];
			}
		}
		//// userAttributes end ///

	}
}