namespace cpr.controls.navigation {

	/**
	 * @private
	 */
	export class FullMenu extends menu.AbstractMenu {
		private _maxWidth: number;
		private _beforeMouseoverItem: MenuItem = null;
		private _mouseLeaveTimer: utils.Timer;
		private _maxHeight: number;
		private _rootItemsWidth: number = 0;
		private _gridTemplateColumns = [];

		constructor(uicontrol: menu.MenuOwner, ns: string, binder: provider.MenuDataBinder, stylerName: { [name: string]: string, list: string, item: string }) {
			super(uicontrol, ns, binder, stylerName);
			this._mouseLeaveTimer = utils.Timer.create("fullmenu-mouseleave");
		}

		public init() {
			if (this._maxWidth != null) {
				this._maxWidth = null;
			}
			if (this._maxHeight != null) {
				this._maxHeight = null;
			}
			super.init();
			this.cancelTimeoutEvent(menu.MenuTimeoutEventType.mouseleave);
		}

		override getType() {
			return "fullmenu";
		}

		protected _createShape(): ufc.ElementShape {
			let cells = [];
			let rootItems = this.getItems();
			let groupWrapper: ufc.ElementShape = {
				tag: "div",
				classNames: [],
				style: {
				},
				children: [],
				nodename: "grid"
			}
			let templateColumns = [];
			this._gridTemplateColumns = [];
			let barItemSpacing = this._getBarItemSpacing();
			rootItems.forEach((each, index) => {
				for (let item of each.children) {
					let cell = {
						tag: "div",
						classNames: ["cl-navigationbar-category"],
						style: {},
						attr: { "data-itemid": item.value },
						children: [
							this._createCategoryContents(item as MenuItem)
						]
					}
					cells.push(cell);
				}

				let shape: cpr.ufc.ElementShape = {
					tag: "div",
					classNames: ["cl-navigationbar-group"],
					style: {
						display: "block",
						//margin: "0px",
						// padding: "0px",
						//overflow: "auto"
					},
					children: cells
				}
				let barItem = this._getRenderer().getNamedNode("baritem" + index);
				if (barItem) {
					let barItemWidth = barItem.offsetWidth;
					templateColumns.push(barItemWidth + "px");
					this._rootItemsWidth += barItemWidth;
				}
				layouts.GridCSSBuilder._forCell()._withColumnStart(templateColumns.length)._withRowStart(1)._commit(shape.style);
				groupWrapper.children.push(shape);

				if (barItemSpacing > 0 && index != rootItems.length - 1) {
					let spacingColumn: cpr.ufc.ElementShape = {
						tag: "div",
						classNames: ["cl-empty-area"],
						style: {}
					}
					this._rootItemsWidth += barItemSpacing;
					templateColumns.push(barItemSpacing + "px");
					layouts.GridCSSBuilder._forCell()._withColumnStart(templateColumns.length)._withRowStart(1)._commit(spacingColumn.style);
					groupWrapper.children.push(spacingColumn);
				}

				cells = [];
			});
			this._gridTemplateColumns = templateColumns;
			layouts.GridCSSBuilder._forLayout()._withTemplateColumns(templateColumns)._withTemplateRows("1fr")._commit(groupWrapper.style);

			let menuShape: ufc.ElementShape = {
				tag: "div",
				classNames: [],
				style: {
					overflow: "auto",
					"position": "relative"
				},
				attr: {
					role: "menu"
				},
				styler: this._getStylerName("list"),
				aria: this._getStylerName("list"),
				children: [groupWrapper],
				nodename: this._getSubMenuNodeName()
			};

			ufc.ShapeUtil.addEventHandler(menuShape, "click", (e: MouseEvent) => this._onClick(e), true);
			ufc.ShapeUtil.addEventHandler(menuShape, "mouseover", (e: MouseEvent) => this._onMenuMouseOver(e), true);
			ufc.ShapeUtil.addEventHandler(menuShape, "mouseout", (e: MouseEvent) => this._onMenuMouseOut(e), true);

			if (this._isHoverTrigger()) {
				ufc.ShapeUtil.addEventHandler(menuShape, "mouseleave", (e: MouseEvent) => this._onMenuMouseLeave(e), true);
				ufc.ShapeUtil.addEventHandler(menuShape, "mouseenter", (e: MouseEvent) => this._onMenuMouseEnter(e), true);
			}

			menuShape.children.push(_createTapLazyTask({
				task: () => {
					this._updateBounds();
				}
			}));

			if (this._maxHeight != null) {
				menuShape.style["max-height"] = this._maxHeight + "px";
			}
			return menuShape;
		}
		/**
		 * 그룹의 아이템 컨텐츠를 생성.
		 * @param categoryItem 
		 */
		private _createCategoryContents(item: MenuItem): cpr.ufc.ElementShape {

			let data = { index: 0 };

			let result = [];

			let itemWrap = this._createCategoryItemWrap(item, data, 0);
			result.push(itemWrap);

			// let table = {
			//  tag: "div",
			//  classNames: ["sub-items"],
			//  children: result
			// }
			return itemWrap;
		}
		/**
		 * 아이템과 서브아이템을 갖는 래퍼 생성.
		 * @param item 아이템
		 * @param data 아이템의 인덱스
		 * @param depth 아이템의 자식의 깊이
		 */
		private _createCategoryItemWrap(item: MenuItem, data: { index: number }, depth: number) {

			//아이템 값 중복 체크
			let menuItem = this._createCategoryItem(item, data, depth);
			data.index++;

			let children: cpr.ufc.ElementShape[] = [menuItem];
			let classNames = ["cl-navigationbar-listitem-wrapper"];
			if (item._hasChild()) {
				children.push(this._createCategorySubItems(item, data, depth + 1));
			}
			return {
				tag: "div",
				attr: { "data-itemlevel": depth + "" },
				style: { overflow: "hidden" },
				classNames: classNames,
				children: children
			};
		}

		/**
		 * 아이템의 자식 아이템 생성
		 * @param item 아이템
		 * @param data 아이템의 인덱스
		 * @param depth 아이템의 자식의 깊이
		 */
		private _createCategorySubItems(item: MenuItem, data: { index: number }, depth: number): cpr.ufc.ElementShape {
			let result = [];
			let items = item.children as MenuItem[];
			for (let item of items) {
				let itemWrap = this._createCategoryItemWrap(item, data, depth);
				result.push(itemWrap);

			}
			let shape = {
				tag: "div",
				classNames: ["sub-items", `cl-level-${item.depth + 1}`],
				attr: {
					"data-role": "menu",
					role: "menu"
				},
				children: result
			};
			ufc.ShapeUtil._setAriaDisabled(shape, this._isEnabled() && !this._getUIControl().readOnly);
			return shape;
		}

		/**
		 * 그룹 컨텐츠에 아이템을 생성.
		 * @param item 아이템
		 * @param data 아이템의 인덱스
		 * @param depth 아이템의 자식의 깊이
		 */
		private _createCategoryItem(item: MenuItem, data: { index: number }, depth: number): cpr.ufc.ElementShape {

			let children = [];
			let templateColumns = [];
			let iconCell = this._createIcon(item);

			children.push(iconCell);
			templateColumns.push("auto");
			layouts.GridCSSBuilder._forCell()._withColumnStart(children.length)._withRowStart(1)._commit(iconCell.style)

			let displayLabel = this._getDataBinder()._computeItemDisplayLabel(item);
			let textCell = this._createText(displayLabel);

			children.push(textCell);
			templateColumns.push("1fr");
			layouts.GridCSSBuilder._forCell()._withColumnStart(children.length)._withRowStart(1)._withVerticalAlign(layouts.GridCellAlign.center)._commit(textCell.style)

			let accesskeyCell = this._createAccessKey(item);

			children.push(accesskeyCell);
			templateColumns.push("auto");
			layouts.GridCSSBuilder._forCell()._withColumnStart(children.length)._withRowStart(1)._withVerticalAlign(layouts.GridCellAlign.center)._commit(accesskeyCell.style);

			let isItemEnabled = this._getDataBinder().getItemEnable(item);

			let itemElement: ufc.ElementShape = {
				tag: "div",
				classNames: [],
				style: {},
				styler: this._getStylerName("item"),
				bindContext: item.toExpressionContext(this._getUIControl()),
				aria: this._getStylerName("item"),
				attr: {
					"data-role": "menuitem",
					role: "menuitem",
					"data-itemid": item.value,
					"data-itemidx": data.index + "",
					"data-itemlevel": depth + "",
					"aria-label": cpr.ufc.ShapeUtil._getValidAriaLabelAttr(ufc.StyledString._asString(displayLabel)),
					id: this._getMenuItemId(item)
				},
				children: [iconCell, textCell, accesskeyCell]
			}

			layouts.GridCSSBuilder._forLayout()._withTemplateColumns(templateColumns)._withTemplateRows("1fr")._commit(itemElement.style);
			cpr.ufc.ShapeUtil._setTooltipAttr(itemElement, { owner: this._getUIControl(), title: item.tooltip, id: item.value });
			if (item.accessKey) {
				itemElement.attr["aria-keyshortcuts"] = item.accessKey;
			}
			if (item._hasChild()) {
				itemElement.classNames.push(ufc.Classes.FOLDER);
			} else {
				itemElement.classNames.push(ufc.Classes.LEAF);
			}

			if (this._getDataBinder().isSelected(item)) {
				itemElement.attr["aria-current"] = "page";
				itemElement.classNames.push(ufc.Classes.SELECTED);
			}
			ufc.ShapeUtil._setAriaDisabled(itemElement, isItemEnabled && this._isEnabled() && !this._getUIControl().readOnly);
			if (isItemEnabled && this._isEnabled()) {
				let hoveredItem = this.getHoveredItem();
				if (hoveredItem?._equalsValue(item)) {
					itemElement.classNames.push(ufc.Classes.HOVER);
				}
			} else {
				itemElement.classNames.push(ufc.Classes.DISABLED);
			}

			return itemElement;
		}

		protected _createArrowImage(item: MenuItem): ufc.ElementShape {
			let result: ufc.ElementShape;
			let listArrowImage = this._getListArrowImage();
			let arrow: cpr.ufc.ElementShape = {
				tag: "div",
				classNames: [this._getQClass("arrow")],
				style: {},
			}

			if (listArrowImage != "" && item._hasChild()) {
				arrow.style['background-image'] = _quoteAsCSSURL(listArrowImage);
			}
			result = {
				tag: "div",
				classNames: [this._getQClass("arrow-wrapper")],
				style: {},
				children: [arrow]
			}
			return result;
		}

		protected _createIcon(item: MenuItem) {
			let shape: ufc.ElementShape;
			let icon: cpr.ufc.ElementShape = {
				tag: "div",
				style: {},
				classNames: [this._getQClass("icon")],
				children: ["&nbsp;"]
			}
			if (item.icon != null && item.icon != "") {
				icon.style['background-image'] = _quoteAsCSSURL(item.icon);
			}
			shape = {
				tag: "div",
				classNames: [this._getQClass("icon-wrapper")],
				attr: { "aria-hidden": "true" },
				style: {},
				children: [icon]
			};
			return shape;
		}

		protected _createText(text: ufc.StyledString | string): ufc.ElementShape {
			let textShape: cpr.ufc.ElementShape = {
				tag: "div",
				attr: { "aria-hidden": "true" },
				classNames: [ufc.Classes.TEXT],
				style: {},
				children: ufc.StyledString._asShape(text)
			};
			return textShape;
		}

		protected _createAccessKey(item: MenuItem): ufc.ElementShape {

			return {
				tag: "div",
				classNames: [this._getQClass("accesskey-wrapper")],
				attr: { "aria-hidden": "true" },
				style: {},
				children: [{
					tag: "div",
					style: {},
					classNames: [this._getQClass("accesskey"), ufc.Classes.TEXT],
					children: [item.accessKey ? "(" + item.accessKey + ")" : ""]
				}]
			}

		}

		protected _updateScrollByHover(currentHover: MenuItem, beforeHover: MenuItem) {
			if (currentHover == null) {
				return;
			}
			if (beforeHover == null) {
				this._scrollDown(currentHover);
				return;
			}
			if (beforeHover.depth > currentHover.depth) {
				this._scrollUp(currentHover);
			} else if (beforeHover.depth < currentHover.depth) {
				this._scrollDown(currentHover);
			} else {
				let items = beforeHover.parentItem.children;
				let prevIdx = items.indexOf(beforeHover);
				let nextIdx = _.findIndex(items, (each) => {
					return each.value == currentHover.value;
				})
				if (prevIdx > nextIdx) {
					this._scrollUp(currentHover);
				} else {
					this._scrollDown(currentHover);
				}
			}

		}

		private _updateBounds() {
			let rootNode = this._getRenderer().getRootNode();
			let menuNode = this._getRenderer().getNamedNode(this._getSubMenuNodeName());
			let menuWrapNode = this._getRenderer().getNamedNode(this.getRootNodeName());
			if (!menuNode || !rootNode || !menuWrapNode) {
				return;
			}
			if (getComputedStyle(menuWrapNode).opacity == "0") {
				return;
			}

			let rootRect = _getOffsetRectFromViewport(rootNode);
			let menuWrapRect = _getOffsetRectFromViewport(menuWrapNode);
			let viewportRect = _getVisualViewportRect();
			let rootSpace = _getComputedSpaceInsets(rootNode, { horizontalMeasurePosition: "reverseBoth" });
			menuWrapRect.translate(1000, 1000);
			menuWrapRect.translate(rootRect.left, rootRect.top + rootRect.height);
			menuWrapRect.top = rootRect.bottom;
			menuWrapRect.left = menuWrapRect.left < 0 ? rootRect.left + Math.abs(menuWrapRect.left) : menuWrapRect.left;
			menuWrapRect.width = rootRect.width > viewportRect.width ? viewportRect.width : rootRect.width; // 메뉴 너비가 윈도우보다 크면 윈도우 너비로 설정
			// 메뉴의 높이가 자동높이이기 때문에 너비에 의해 정해지므로 먼저 너비를 설정함.
			this._getRenderer().updateStyle(this.getRootNodeName(), { "width": menuWrapRect.width + "px" }, true);
			menuWrapRect.height = menuWrapNode.offsetHeight;// 재계산한 DOM의 높이로 설정
			let originMenuWrapperRect = menuWrapRect.getCopy(); // 높이에 대해 변경점이 발생여부를 확인하기 위해 값 복사

			//가로 위치 정렬
			if (viewportRect.width < menuWrapRect.width) {// 윈도우 너비보다 메뉴아이템이 클 경우
				menuWrapRect.left = 0;
			} else if ((menuWrapRect.left + menuWrapRect.width) > viewportRect.right) { // 메뉴아이템이 오른쪽으로 넘어가 잘려보이는 경우
				let remainderValue = viewportRect.right - (menuWrapRect.left + menuWrapRect.width);
				menuWrapRect.left = Math.floor(menuWrapRect.left + remainderValue);
			}

			if (rootRect.width != menuWrapRect.width) {
				this._maxWidth = menuWrapRect.width;
			}
			//스크롤 유무에 따른 레이아웃 조정
			let hasHScroll = this._rootItemsWidth > rootSpace.right || this._rootItemsWidth > viewportRect.right;
			let gridTemplateColumns = this._gridTemplateColumns;
			let gridShape = this._getRenderer()._getNamedShape("grid");
			if (hasHScroll == false) {
				gridTemplateColumns.pop();
				gridTemplateColumns.push("1fr");
			}
			layouts.GridCSSBuilder._forLayout()._withTemplateColumns(gridTemplateColumns)._withTemplateRows("1fr")._commit(gridShape.style);
			this._getRenderer().updateStyle("grid", gridShape.style, true);
			this._rootItemsWidth = 0;
			//레이아웃 조정에 의해 정보 갱신 필요
			menuWrapRect.height = menuWrapNode.offsetHeight;
			let wrapperComputedStyle = getComputedStyle(menuWrapNode);
			let verticalMargin = hasHScroll ? 27 : 10;
			rootSpace.add(new geometry.Insets(-verticalMargin, 0, -verticalMargin, 0));
			let menuStyle = {};
			let classlist = [ufc.Classes.BOTTOM];
			let parentClassList = [ufc.Classes.OPENED_BOTTOM];

			let computedStyle = getComputedStyle(menuNode);

			let menuWrapMarginTop = _parseFloat(wrapperComputedStyle.marginTop);
			let menuWrapMarginBottom = _parseFloat(wrapperComputedStyle.marginBottom);
			let menuMarginTop = _parseFloat(computedStyle.marginTop);
			let menuMarginBottom = _parseFloat(computedStyle.marginBottom);

			let maxHeight = this._maxHeight;
			let menuWrapExpandedRect = menuWrapRect.getExpanded(new geometry.Insets(menuWrapMarginTop, 0, menuWrapMarginBottom, 0));

			// 세로 위치 정렬
			if (menuWrapExpandedRect.height > rootSpace.bottom && rootSpace.top > rootSpace.bottom) {
				maxHeight = rootSpace.top - (menuWrapMarginTop + menuWrapMarginBottom);
				menuWrapRect.height = rootSpace.top > menuWrapExpandedRect.height ? menuWrapRect.height : rootSpace.top;
				menuWrapRect.top = rootRect.top - menuWrapRect.height;
				menuStyle["height"] = "100%";
				classlist = [ufc.Classes.TOP];
				parentClassList = [ufc.Classes.OPENED_TOP];
			} else {
				maxHeight = rootSpace.bottom - (menuWrapMarginTop + menuWrapMarginBottom);
				if (this._useBodyScroll()) {
					if (viewportRect.top > menuWrapRect.top) {
						menuWrapRect.top = viewportRect.top;
					}
				} else {
					if (0 > menuWrapRect.top) {
						menuWrapRect.top = 0;
					}
				}
			}
			if (this._maxHeight != maxHeight) {
				this._maxHeight = maxHeight;
				menuStyle["max-height"] = (maxHeight - (menuMarginTop + menuMarginBottom)) + "px";
			}

			let constraint = {
				top: menuWrapRect.top,
				bottom: null,
				left: menuWrapRect.left,
				right: null,
				width: menuWrapRect.width,
				height: null
			};
			if (originMenuWrapperRect.height != menuWrapRect.height) {
				constraint.height = menuWrapRect.height > maxHeight ? maxHeight : menuWrapRect.height;
			}
			if (this.getVisible()) {
				this._getRenderer().updateStyle(this._getSubMenuNodeName(), menuStyle, true);
			}
			this._getRenderer().updateClass(this._getQName(), [], parentClassList);
			this._getRenderer().updateClass(this.getRootNodeName(), [ufc.Classes.BOTTOM], classlist);

			let menuWrapperStyle = _.mapObject(constraint, (val: number | null, key: string) => {
				if (val == null) {
					return "auto";
				}
				if (key == "left") {
					return val + "px";
				}
				return val + "px";
			})
			this._getRenderer().updateStyle(this.getRootNodeName(), menuWrapperStyle, true);
		}


		private _scrollUp(item: MenuItem) {
			if (item == null) {
				return;
			}
			let allMenuViewport = this._getRenderer().getNamedNode(this._getSubMenuNodeName());
			if (!allMenuViewport) {
				return;
			}
			let itemElement = <HTMLElement>allMenuViewport.querySelector('[data-itemid="' + item.value + '"] ');
			if (!itemElement) {
				return;
			}
			// 카테고리아이템이 리스트뷰포트의 높이보다 클 경우
			if (itemElement.classList.contains("cl-navigationbar-category") && itemElement.scrollHeight > allMenuViewport.clientHeight) {
				itemElement = <HTMLElement>allMenuViewport.querySelector('.cl-navigationbar-listitem[data-itemid="' + item.value + '"] ');
			}

			let itemOffsetTop = itemElement.offsetTop;
			let listMinOffsetTop = allMenuViewport.scrollTop;
			let listMaxOffsetTop = listMinOffsetTop + allMenuViewport.clientHeight;

			if (listMinOffsetTop >= itemOffsetTop || listMaxOffsetTop <= itemOffsetTop) {
				allMenuViewport.scrollTop = itemOffsetTop;
			}

			let itemOffsetLeft = itemElement.offsetLeft;
			let listMinOffsetLeft = allMenuViewport.scrollLeft;
			let listMaxOffsetLeft = listMinOffsetLeft + allMenuViewport.clientWidth;

			if (listMinOffsetLeft >= itemOffsetLeft || listMaxOffsetLeft <= itemOffsetLeft) {
				allMenuViewport.scrollLeft = itemOffsetLeft;
			}
		}

		private _scrollDown(item: MenuItem) {
			if (item == null) {
				return;
			}
			let allMenuViewport = this._getRenderer().getNamedNode(this._getSubMenuNodeName());
			if (!allMenuViewport) {
				return;
			}
			let itemElement = <HTMLElement>allMenuViewport.querySelector('[data-itemid="' + item.value + '"] ');
			if (!itemElement) {
				return;
			}
			// 카테고리아이템이 리스트뷰포트의 높이보다 클 경우
			if (itemElement.classList.contains("cl-navigationbar-category") && itemElement.scrollHeight > allMenuViewport.clientHeight) {
				itemElement = <HTMLElement>allMenuViewport.querySelector('.cl-navigationbar-listitem[data-itemid="' + item.value + '"] ');
			}
			let itemOffset = itemElement.offsetTop;
			let nextItemOffset = itemOffset + itemElement.scrollHeight;
			let listMinOffset = allMenuViewport.scrollTop;
			let listMaxOffset = listMinOffset + allMenuViewport.clientHeight;

			if (listMinOffset >= nextItemOffset || listMaxOffset <= nextItemOffset) {
				allMenuViewport.scrollTop = nextItemOffset - allMenuViewport.clientHeight;
			}

			let itemOffsetLeft = itemElement.offsetLeft;
			let listMinOffsetLeft = allMenuViewport.scrollLeft;
			let listMaxOffsetLeft = listMinOffsetLeft + allMenuViewport.clientWidth;

			if (listMinOffsetLeft >= itemOffsetLeft || listMaxOffsetLeft <= itemOffsetLeft) {
				allMenuViewport.scrollLeft = itemOffsetLeft;
			}
		}

		/**
		 * @override
		 * @param keyCode 
		 * @param current 
		 * @returns 
		 */
		public traverseHover(keyCode: number, current: MenuItem) {
			let result = null;
			switch (keyCode) {
				case events.KeyCode.DOWN:
					result = this._transferHoverDownCycle(current);
					break;
				case events.KeyCode.UP:
					let group = this._getGroupItemsByItem(current);
					let currentIdx = _.findIndex(group, { value: current.value });
					if (currentIdx == 0) {
						result = this._transferHoverUpCycle(current);
					} else {
						result = this._transferHoverBackward(current);
					}
					break;
				case events.KeyCode.LEFT:
				case events.KeyCode.RIGHT:
					result = this._moveListItem(current, keyCode);
					break;
			}
			return result;
		}

		public override _transferHoverBackward(item: MenuItem): MenuItem {
			return this._traverseHover(item, false);
		}

		public override _transferHoverDownCycle(item: MenuItem): MenuItem {
			return this._traverseHover(item, true);
		}

		public override _transferHoverUpCycle(item: MenuItem) {
			let parentItem = item.parentItem;
			if (this._getDataBinder().getItemEnable(parentItem) == false) {
				return this._transferHoverBackward(parentItem);
			}
			this.setHoveredItem(parentItem, { updateScroll: true });
			return parentItem;
		}

		/**
		 *  왼쪽, 오른쪽 리스트의 아이템으로 이동
		 */
		private _moveListItem(item: MenuItem, keyCode: number) {
			let moveIdx = keyCode == events.KeyCode.RIGHT ? 1 : -1;
			let getRootItems = (item) => {
				while (item.parentItem != null) {
					item = item.parentItem;
				}
				return item;
			}

			let rootItem = getRootItems(item);
			let rootItemsGroup = this._getGroupItemsByItem(rootItem);
			let rootItemIndex = _.findIndex(rootItemsGroup, { value: rootItem.value });

			let isRight = moveIdx == 1;
			if ((rootItemIndex == 0 && !isRight) || (rootItemIndex == rootItemsGroup.length - 1 && isRight)) {
				return null;
			}
			let nextRootItem = rootItemsGroup[rootItemIndex + moveIdx];

			if (!nextRootItem) {
				if (moveIdx == 1) {
					nextRootItem = rootItemsGroup[0];
				} else {
					nextRootItem = rootItemsGroup[rootItemsGroup.length + moveIdx];
				}
			}
			this.setHoveredItem(this._nextNavItem(nextRootItem), { updateScroll: true });
			return nextRootItem;
		}

		private _traverseHover(item: MenuItem, forward: boolean = true) {
			let rootItem = item;
			while (rootItem.parentItem != null) {
				rootItem = rootItem.parentItem;
			}
			let nextItem = null;

			if (forward == false && item == null) {
				return nextItem;
			}

			let items = _createTreeStream(rootItem, true, (each: MenuItem) => {
				return each.children;
			}).collect() as MenuItem[];

			let findIndex = forward ? -1 : items.length;
			if (item) {
				findIndex = _.findIndex(items, (each) => {
					return each.value == item.value;
				});
			}
			let len = items.length;
			let delta = forward ? 1 : -1;
			let i = findIndex + delta;
			while (len > i || i < 0) {
				if (this._getDataBinder().getItemEnable(items[i])) {
					nextItem = items[i];
					i = len;
				} else {
					i = i + delta;
				}
			}

			if (nextItem) {
				this.setHoveredItem(nextItem, { updateScroll: true });
			}
			return nextItem;
		}

		protected override _nextNavItem(rootItem: MenuItem) {
			let items = _createTreeStream(rootItem, false, (each: MenuItem) => {
				return each.children;
			}).collect() as MenuItem[];

			let nextItem = items.find((each) => {
				return this._getDataBinder().getItemEnable(each);
			})

			return nextItem;
		}

		protected _onClick(e: MouseEvent): void {
			e.stopPropagation();
			let rootElement: HTMLElement = <HTMLElement>e.currentTarget;
			let eventElement: HTMLElement = <HTMLElement>e.target;
			if (eventElement.classList.contains(this._getQClass("list"))) {
				return;
			}

			let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(eventElement)._closest(this._getMenuItemQuerySelector(), rootElement);
			if (domTraverser == null) {
				return;
			}

			let item: MenuItem = this._getItemByElement(domTraverser._getElement());
			if (!this._getDataBinder().getItemEnable(item)) {
				return;
			}
			let ignoreSelect = !this._isHoverTrigger() && item._hasChild();
			let itemSelected = false;
			if (!ignoreSelect) {
				itemSelected = this._onItemSelect(item, e);
			}

			let itemClickEvent = new cpr.events.CItemEvent(events.ItemEventType.ITEMCLICK, {
				item: item
			});
			itemClickEvent.nativeEvent = e;
			this.dispatchEvent(events.ItemEventType.ITEMCLICK, itemClickEvent);

			if (itemSelected) {
				let itemSelectedEvent = new cpr.events.CItemEvent("--internal-item-selected", {
					item: item
				})
				this.dispatchEvent("--internal-item-selected", itemSelectedEvent);
			}
		}

		/**
		 * expanderTrigger=[hover,click]에 item-mouseover 이벤트를 발생시킵니다.
		 * @param e 
		 * @returns 
		 */
		private _onMenuMouseOver(e: MouseEvent) {
			let rootElement = <HTMLElement>e.currentTarget;
			let eventElement = <HTMLElement>e.target;

			let domTravser = ufc._traverseFromElement(eventElement)._closest(this._getMenuItemQuerySelector(), rootElement);
			if (!domTravser) {
				return;
			}
			let item: MenuItem = this._getItemByElement(domTravser._getElement());
			if (!this._dispatchItemMouseover(item, e) || this._isHoverTrigger() == false) {
				return;
			}
			if (this._isHoveredItem(item) || this._getDataBinder().getItemEnable(item) == false) {
				return;
			}

			this.setHoveredItem(item);
		}

		private _onMenuMouseOut(e: MouseEvent) {
			let rootElement: HTMLElement = <HTMLElement>e.currentTarget;
			let eventElement: HTMLElement = <HTMLElement>e.target;

			let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(eventElement)._closest("[data-role='menuitem']", rootElement);
			if (domTraverser == null) {
				return;
			}
			let relatedDomTraverser = ufc._traverseFromElement(e.relatedTarget as HTMLElement)._closest("[data-role='menuitem']", rootElement);
			if (relatedDomTraverser == null || (relatedDomTraverser != null && domTraverser._getElement() != relatedDomTraverser._getElement())) {
				this._beforeMouseoverItem = null;
			}
		}

		private _dispatchItemMouseover(item: MenuItem, e: MouseEvent): boolean {
			if (this._beforeMouseoverItem?._equalsValue(item)) {
				return true;
			}
			if (this._getUIControl()._hasCustomEventListener("item-mouseover") == false) {
				return true;
			}
			this._beforeMouseoverItem = item;
			let itemMouseOverEvent = new events.CItemEvent("item-mouseover", { item: item });
			itemMouseOverEvent.nativeEvent = e;
			return this.dispatchEvent("item-mouseover", itemMouseOverEvent);
		}

		private _onMenuMouseLeave(e: MouseEvent) {
			e.stopPropagation();
			this.cancelTimeoutEvent(menu.MenuTimeoutEventType.mouseleave);
			this._mouseLeaveTimer.init(() => {
				this._mouseLeaveImmediately(e);
			}).schedule(300);
		}

		private _mouseLeaveImmediately(e?: MouseEvent) {
			this._beforeMouseoverItem = null;
			this._clearHoveredItem();
			this.dispatchEvent("menu-mouseleave", e);
		}

		private _onMenuMouseEnter(e: MouseEvent) {
			if (this._beforeMouseoverItem) {
				this._beforeMouseoverItem = null;
			}
			this.dispatchEvent("menu-mouseenter", e);
		}

		public cancelTimeoutEvent(name: menu.MenuTimeoutEventType) {
			if (name == menu.MenuTimeoutEventType.mouseleave) {
				this._mouseLeaveTimer.cancel();
			}
		}

		public executeTimeoutEvent(name: menu.MenuTimeoutEventType) {
			if (name == menu.MenuTimeoutEventType.mouseleave) {
				this._mouseLeaveTimer.scheduleRun();
			}
		}

		public dispose(): void {
			this._beforeMouseoverItem = null;
			if (this._mouseLeaveTimer) {
				this._mouseLeaveTimer.dispose();
				this._mouseLeaveTimer = null;
			}
			super.dispose();
		}

	}//class
}//namespace
