

namespace cpr.controls {

	/**
	 * UIControlShell
	 * Third-party widget을 끼워넣을 수 있는 컨트롤.
	 * 지원 eventType : init, load, dispose
	 * 
	 * @fires cpr.events.CUIEvent#init 쉘 컨트롤의 내용이 그려지기 전 초기화 하는 이벤트.
	 * 		최초 컨트롤이 생성될때는 content가 null입니다.
	 * 		<pre>content: {Element} 쉘의 엘리먼트</pre>
	 * 
	 * @fires cpr.events.CUIEvent#load 쉘이 그려진 후 내용을 작성하는 이벤트.
	 * 		<pre>content: {element} 쉘의 엘리먼트</pre>
	 */
	export class UIControlShell extends VisibleUIControl {
		private _registry: { [key: string]: any };
		private _tabIndex: number = -1;

		get tabIndex(): number {
			return this._tabIndex;
		}

		set tabIndex(newIndex: number) {
			this._tabIndex = newIndex;
		}

		constructor(id?: string) {
			super(id);
			this._registry = {};
			this._initControl();
		}

		protected _getStylerSpec(): UIControlStylerSpec {
			return {
				root: { baseClass: "cl-uicontrolshell" }
			};
		}

		/**
		 * 자동 크기 지원 타입을 얻습니다.
		 * 만일 both를 리턴했다면, css height, width 속성에 auto를 사용할 수 있음을 나타냅니다.
		 */
		public _getAutoSizeAvailability(): layouts.AutoSizeType {
			return layouts.AutoSizeType.both;
		}

		override _getType(): ControlType {
			return ControlType.UICONTROLSHELL
		}

		/**
		 * 쉘 컨트롤은 포커스를 가지지 못하는 컨트롤이므로 focusable 을 false로 주기 위해 _isFocusable 을 오버라이드합니다.
		 */
		override _isFocusable(): boolean {
			let contentNode = this.getContentNode();
			if (!contentNode) {
				return false;
			}

			let lookup = _createTreeStream(contentNode, false, (parent: HTMLElement) => {
				return _toArray(parent.children) as HTMLElement[];
			}).filter((it: HTMLElement) => it.tabIndex >= 0);

			return lookup.hasNext();
		}


		private _onKeyDown(e: events.CKeyboardEvent) {
			if (e.key != "Tab") {
				return;
			}

			let contentNode = this.getContentNode();
			if (_traverseHTMLFocus(contentNode, !e._getMod2Key())) {
				e.preventDefault();
				e.stopPropagation();
			}
		}

		public override focus(forward?: boolean): void {
			core.DeferredUpdateManager.INSTANCE._performFocusTask(() => {
				let contentNode = this.getContentNode();
				_traverseHTMLFocus(contentNode, forward);
			})
		}

		/**
		 * 사용자 component(라이브러리)를 등록합니다.
		 * @param key component 명.
		 * @param value component 값.
		 */
		public registerComponent(key: string, value: any): void {
			this._registry[key] = value;
		}

		/**
		 * 등록된 component(라이브러리)를 해지합니다.
		 * @param key component 명.
		 */
		public unregisterComponent(key: string): void {
			delete this._registry[key];
		}

		/**
		 * 사용자의 해당 component(라이브러리)를 반환합니다.
		 * @param key component 명.
		 * @return component.
		 */
		public getComponent(key: string): any {
			return this._registry[key];
		}

		/**
		 * 모든 component(라이브러리)를 반환합니다.
		 * @return 모든 component.
		 */
		public getAllComponents(): { [key: string]: any } {
			return this._registry;
		}

		private _createShapeForKeepContent(): ufc.ControlShape {
			// init
			let renderer: ufc.ControlRenderer = this._getRenderer();
			let oldWrapperTag: HTMLDivElement = renderer.getNamedNode("shell") as HTMLDivElement;

			let oldContents = (oldWrapperTag ? _toArray(oldWrapperTag.childNodes) : []) as Node[];

			let shape: ufc.ControlShape = {
				tag: "div",
				attr: {},
				nodename: "shell",
				eventTargets: [
					ufc.EventTargetType.UICONTROL
				],
				styler: "root",
				children: [_createTapLazyTask({
					task: () => {
						let renderer: ufc.ControlRenderer = this._getRenderer();
						let newWrapperTag: HTMLDivElement = renderer.getNamedNode("shell") as HTMLDivElement;

						// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/7675
						if (oldWrapperTag !== newWrapperTag) {
							while (newWrapperTag.firstChild) {
								newWrapperTag.removeChild(newWrapperTag.firstChild);
							}

							oldContents.forEach(it => {
								newWrapperTag.appendChild(it);
							});
						}
					}
				})]
			};
			cpr.ufc.ShapeUtil._setTooltipAttr(shape, { owner: this, title: this.tooltip });
			return shape;
		}

		public getContentNode(): HTMLElement {
			return this._getRenderer().getNamedNode("shell");
		}

		public _createShape(): ufc.ControlShape {
			if (this._isShowing() === false) {
				// 표시 중이지 않다면, 기존 콘텐츠 이용.
				return this._createShapeForKeepContent();
			}

			// init
			let renderer: ufc.ControlRenderer = this._getRenderer();
			let knownWrapperTag: HTMLDivElement = renderer.getNamedNode("shell") as HTMLDivElement;

			// InitEvent
			let event: events.CEvent = new events.CUIEvent("init", { content: knownWrapperTag });

			// 기존 컨텐트를 삭제할 것인지 여부.
			let shouldProcess: boolean = this.dispatchEvent(event);

			// 기존 태그가 존재함.
			if (knownWrapperTag && shouldProcess) {
				while (knownWrapperTag.firstChild) {
					knownWrapperTag.removeChild(knownWrapperTag.firstChild);
				}
			}

			let shape: ufc.ControlShape = {
				tag: "div",
				attr: {},
				nodename: "shell",
				eventTargets: [
					ufc.EventTargetType.UICONTROL,
				],
				styler: "root",
				events: {
					keydown: this._onKeyDown
				},
				children: [_createTapLazyTask({
					task: () => {
						// 로드 이벤트를 디스패치 해야 하는 경우.
						if (shouldProcess) {
							let renderer: ufc.ControlRenderer = this._getRenderer();
							let wrapperTag: HTMLDivElement = renderer.getNamedNode("shell") as HTMLDivElement;
							let event: events.CEvent = new events.CUIEvent("load", { content: wrapperTag });
							this.dispatchEvent(event);
						}

						// 로드 이벤트를 디스패치 하지 않는 경우, 이전 컨텐츠를 적용. 예: init 이벤트에서 preventDefault() 호출 등.
						else {
							let renderer: ufc.ControlRenderer = this._getRenderer();
							let wrapperTag: HTMLDivElement = renderer.getNamedNode("shell") as HTMLDivElement;
							if (wrapperTag !== knownWrapperTag) {
								while (wrapperTag.firstChild) {
									wrapperTag.removeChild(wrapperTag.firstChild);
								}
								if (knownWrapperTag) {
									while (knownWrapperTag.firstChild) {
										wrapperTag.appendChild(knownWrapperTag.firstChild);
									}
								}
							}
						}
					}
				})]
			};
			cpr.ufc.ShapeUtil._setTooltipAttr(shape, { owner: this, title: this.tooltip });
			return shape;
		}

		/**
		 * 컨트롤에 포함되어있는 객체들을 제거합니다.
		 */
		public dispose(): void {
			this._registry = null;
			super.dispose();
		}


	}
}