/// <reference path="./AccessibleHorizontalBar.ts" />
namespace cpr.controls.navigation {

	/**
	 * @private
	 */
	export class AccessibleMegaMenuBar extends AccessibleHorizontalBar implements IAccessibleNavigationBar {

		/**
		 * 내비게이션 바를 생성합니다.
		 * @param id 내비게이션 바의 id
		 */
		constructor(owner: NavigationBar, binder: provider.MenuDataBinder) {
			super(owner, binder);
		}

		/* shape */
		private _checkMenu() {
			if (_.size(this._menus) == 0) {
				return;
			}
			let rootItems = this._getRootItems(true);
			let menuKeys = [];
			rootItems.forEach((item) => {
				if (item._hasChild()) {
					menuKeys.push(item.value);
				}
			})
			let removeMenus: { [key: string]: menu.IAccessibleMenu } = _.omit(this._menus, menuKeys);
			for (let key in removeMenus) {
				this._menus[key].dispose();
				delete this._menus[key];
			}
		}

		/*
		 * engine에 사용되는 컨트롤의 shape 객체를 생성합니다. 이 함수는 engine에서 호출되는 함수입니다.
		 * 
		 */
		public _createShape(): cpr.ufc.ControlShape {
			// 메뉴타입먼저 체크
			this._checkMenu();

			let rootItems = this._getRootItems(true);
			let selectedValues = [];
			if (this._owner.values.length > 0) {
				let findItem = this._binder.findTreeItem(this._owner.values[0], rootItems) as MenuItem;
				while (findItem) {
					selectedValues.push(findItem.value);
					findItem = findItem.parentItem as MenuItem;
				}
			}

			let prevButton: ufc.ElementShape = this._owner._getRenderer()._getNamedShape(ufc.NodeNames.ITEMS_SCROLL_LEFT);
			if (!prevButton) {
				prevButton = {
					tag: "div",
					classNames: ["cl-navigationbar-prev"],
					style: {
						display: "none",
					},
					nodename: ufc.NodeNames.ITEMS_SCROLL_LEFT
				}
			}

			let bar = this._createBar(rootItems, selectedValues);
			let barWrapper = {
				tag: "div",
				style: {
					"overflow-y": "visible",
					"overflow-x": "hidden"
				},
				children: [bar],
				nodename: ufc.NodeNames.ITEMS_SCROLLER
			}

			let nextButton: ufc.ElementShape = this._owner._getRenderer()._getNamedShape(ufc.NodeNames.ITEMS_SCROLL_RIGHT);
			if (!nextButton) {
				nextButton = {
					tag: "div",
					classNames: ["cl-navigationbar-next"],
					style: {
						display: "none",
					},
					nodename: ufc.NodeNames.ITEMS_SCROLL_RIGHT
				}
			}

			let scrollableBarChildren = [];
			let scrollBarColumns = [];
			switch (this._owner.barScrollButtonPosition) {
				case NavigationBarScrollButtonPosition.none:
				case NavigationBarScrollButtonPosition.both: {
					prevButton.classNames.push("cl-position-both");
					nextButton.classNames.push("cl-position-both");
					scrollableBarChildren = [prevButton, barWrapper, nextButton];
					scrollBarColumns = ["auto", "1fr", "auto"];
					break;
				}
				case NavigationBarScrollButtonPosition.left: {
					prevButton.classNames.push("cl-position-left");
					nextButton.classNames.push("cl-position-left");
					scrollableBarChildren = [prevButton, nextButton, barWrapper];
					scrollBarColumns = ["auto", "auto", "1fr"];
					break;
				}
				case NavigationBarScrollButtonPosition.right: {
					prevButton.classNames.push("cl-position-right");
					nextButton.classNames.push("cl-position-right");
					scrollableBarChildren = [barWrapper, prevButton, nextButton];
					scrollBarColumns = ["1fr", "auto", "auto"];
					break;
				}
			}
			scrollableBarChildren.forEach((each: ufc.ElementShape, index) => {
				layouts.GridLayoutCSSBuilder._forCell()._withColumnStart(index + 1)._withRowStart(1)._commit(each.style);
			});

			let scrollableBar: cpr.ufc.ElementShape = {
				tag: "div",
				classNames: [ufc.Classes.UNSELECTABLE],
				attr: {},
				style: {
					height: "100%",
					width: "100%",
					"overflow-x": "hidden",
					"overflow-y": "visible"
				},
				children: scrollableBarChildren.concat([_createTapLazyTask({
					task: () => {
						this._checkScrollBtn()
					}
				})]),
				events: {
					wheel: (e: events.CWheelEvent) => { this._onwheel(e) }
				}
			}

			layouts.GridCSSBuilder._forLayout()._withTemplateColumns(scrollBarColumns)._withTemplateRows("1fr")._commit(scrollableBar.style);

			let shape: cpr.ufc.ControlShape = {
				tag: "nav",
				attr: {
					tabindex: "-1"
				},
				classNames: [],
				style: {
					"overflow": "visible"
				},
				styler: "root",
				aria: "root",
				eventTargets: [
					ufc.EventTargetType.UICONTROL,
					ufc.EventTargetType.DROPPABLE
				],
				events: {
					keydown: (e: events.CKeyboardEvent) => { this._onkeydown(e) },
					focus: (e: events.CFocusEvent) => { this._onfocus(e) },
					mousedown: (e: events.CMouseEvent) => { this._onmousedown(e) },
					touchstart: (e: events.CTouchEvent) => { this._ontouchstart(e) },
					mouseover: (e: events.CMouseEvent) => { this._onmouseover(e) },
					mouseout: (e: events.CMouseEvent) => { this._onmouseout(e) },
					click: (e: events.CMouseEvent) => { this._onclick(e) },
					resize: (e: events.CUIEvent) => { this._onResize(e) }
				},
				children: [scrollableBar],
				nodename: "navigationbar"
			}

			cpr.ufc.ShapeUtil._setAriaLabelAttr(shape.attr, this._owner._getFieldLabel());
			cpr.ufc.ShapeUtil._setTooltipAttr(shape, { owner: this._owner, title: this._owner.tooltip });

			if (this._getActiveMenu() != null) {
				shape.classNames.push(ufc.Classes.OPENED);
			}

			if (this._owner.expandTrigger == ExpandTriggerType.hover) {
				shape.events["mouseenter"] = (e: events.CMouseEvent) => { this._onmouseenter(e) };
				shape.events['mouseleave'] = (e: events.CMouseEvent) => { this._onmouseleave(e) };

			}

			if (!this._owner.enabled) {
				delete shape.attr['tabindex'];
			}
			let autoSizeType = this._owner._getAutoSizingTypeOfConstraint();
			if (this._owner.barItemWidths == NavigationBarItemWidths.equal && autoSizeType != layouts.AutoSizeType.both && autoSizeType != layouts.AutoSizeType.width) {
				barWrapper.style["overflow-x"] = "visible";
				scrollableBar.style["overflow-x"] = "visible";
				shape.classNames.push("cl-equalwidths");
			}
			return shape;
		}

		private _createPopupMenu(item: MenuItem, itemIndex: number): ufc.ElementShape {
			let openedItem = this._getOpenedItem();
			let isVisible = openedItem?._equalsValue(item) ?? false;
			if (!isVisible) {
				return null; // 성능 이슈로 표시되지 않는 것은 생성하지 않는 것으로 수정. 차후 렌더링 이후 아이템 갱신이 아니면 DOM 조작으로만 동작하도록 개선 필요.
			}
			let menu = this._getMenu(item.value);
			menu.setRootNodeName("menubar" + itemIndex);// nodename이 중복되면 마지막 노드가 이벤트 발생하는 문제로 이름을 다르게 설정.
			menu.setVisible(isVisible);
			let submenu = this._getMenuShape(menu, item.children as MenuItem[]);

			let shape: ufc.ElementShape = {
				tag: "div",
				classNames: ["cl-navigationbar-" + menu.getType(), ufc.Classes.BOTTOM],
				style: {
					position: "fixed",
					"z-index": "1",
					display: "none"
				},
				children: [submenu],
				nodename: menu.getRootNodeName(),
				events: {
				},
			};
			if (isVisible) {
				shape.classNames.push("cl-navigationbar-visible");
				delete shape.style["display"];

				let oldShape = this._owner._getRenderer()._getNamedShape(menu.getRootNodeName());
				if (oldShape != null) {
					if (oldShape.style["width"] != null) {
						shape.style["width"] = oldShape.style["width"];
					}
				} else {
					let domTraverser = ufc._traverseFromElement(this._owner._getRenderer().getRootNode());
					if (domTraverser) {
						shape.style["width"] = domTraverser._getElement().getBoundingClientRect().width + "px";
					}
				}
			}
			if (this._isHiddenMenu()) {
				shape.style["opacity"] = "0";
				shape.style["pointer-events"] = "none";
			}
			return shape;
		}

		private _createBar(items: MenuItem[], selectedValues: string[]): ufc.ElementShape {

			let itemShapes: cpr.ufc.ElementShape[] = [];

			items.forEach((each: MenuItem, index: number) => {

				if (index > 0 && this._owner.barItemSpacing) { // barItemSpacing
					let spacingShape = {
						tag: "li",
						style: {
							"min-width": this._owner.barItemSpacing + "px",
							width: this._owner.barItemSpacing + "px",
							display: "table-cell"
						},
						attr: {
							"aria-hidden": "true"
						}
					}
					itemShapes.push(spacingShape);
				}

				let item = this._createItem(each, selectedValues.indexOf(each.value) > -1, index);
				item.style["display"] = "table-cell";
				item.style["vertical-align"] = "middle";
				item.style["overflow"] = "visible";

				itemShapes.push(item);
			});

			let barShape: cpr.ufc.ElementShape = {
				tag: "ul",
				attr: {
					"data-menutype": this._owner.menuType
				},
				classNames: [],
				style: {
					display: "table",
					height: "100%"
				},
				nodename: ufc.NodeNames.ITEMS_PANE,
				styler: "bar",
				children: itemShapes
			}

			return barShape;
		}

		private _createItemText(item: MenuItem): cpr.ufc.ElementShape {
			let text = {
				tag: "div",
				style: {},
				classNames: ["cl-navigationbar-text", ufc.Classes.TEXT],
				attr: {},
				children: ufc.StyledString._asShape(this._binder._computeItemDisplayLabel(item))
			}
			return text;
		}

		private _createItemIcon(item: MenuItem): cpr.ufc.ElementShape {
			let iconShape: cpr.ufc.ElementShape = {
				tag: "div",
				style: {},
				classNames: ["cl-navigationbar-icon"],
				children: ["&nbsp;"]
			}
			iconShape.style['background-image'] = _quoteAsCSSURL(item.icon);
			return iconShape;
		}

		private _createItemAccessKey(item: MenuItem): ufc.ElementShape {
			return {
				tag: "div",
				classNames: ["cl-navigationbar-accesskey", ufc.Classes.TEXT],
				style: {},
				children: [item.accessKey ? "(" + item.accessKey + ")" : ""]
			}
		}
		private _createItemArrow(): ufc.ElementShape {
			let arrowIcon: cpr.ufc.ElementShape = {
				tag: "div",
				classNames: ["cl-navigationbar-arrow"],
				style: {},
				children: ["&nbsp;"]
			}
			if (this._owner.barArrowImage != "") {
				arrowIcon.style['background-image'] = _quoteAsCSSURL(this._owner.barArrowImage);
			}
			return arrowIcon;
		}

		private _createItem(item: MenuItem, isSelected: boolean, index: number): ufc.ElementShape {
			let contents: cpr.ufc.ElementShape[] = [];
			let isHoveredItem = this._isHoveredItem(item);
			let hasText = item.accessKey != "" || item.label != "";

			if (item.icon != null && item.icon != "") {
				let iconShape: cpr.ufc.ElementShape = this._createItemIcon(item);
				iconShape.style["height"] = "auto";
				layouts.FlexCSSBuilder._forCell()._withCellConstraint(0, 0, "auto")._withVerticalAlign(hasText ? layouts.FlexCellAlign.stretch : layouts.FlexCellAlign.baseline)._commit(iconShape.style);
				contents.push(iconShape);
			}

			let textShape: cpr.ufc.ElementShape = this._createItemText(item);
			layouts.FlexCellCSSBuilder._forCell()._withCellConstraint(1, 1, "auto")._withVerticalAlign(layouts.FlexCellAlign.baseline)._commit(textShape.style);
			contents.push(textShape);

			if (item.accessKey) {
				let accessKeyShape = this._createItemAccessKey(item);
				layouts.FlexCellCSSBuilder._forCell()._withCellConstraint(0, 0, "auto")._withVerticalAlign(layouts.FlexCellAlign.baseline)._commit(accessKeyShape.style);
				contents.push(accessKeyShape);
			}

			let hasChild = item._hasChild();
			let isOpened = this._isOpened(item);
			if (hasChild) {
				let arrowShape: cpr.ufc.ElementShape = this._createItemArrow();
				arrowShape.style["height"] = "auto";
				layouts.FlexCSSBuilder._forCell()._withCellConstraint(0, 0, "auto")._withVerticalAlign(hasText ? layouts.FlexCellAlign.stretch : layouts.FlexCellAlign.baseline)._commit(arrowShape.style);
				contents.push(arrowShape);
			}

			let content: cpr.ufc.ElementShape = {
				tag: "a",
				aria: "item",
				// ariaBindContext: item.toExpressionContext(this._owner),
				bindContext: item.toExpressionContext(this._owner),
				attr: {
					tabindex: "-1",
					role: "link"
				},
				style: {},
				classNames: ["cl-navigationbar-content"],
				children: contents
			};

			layouts.FlexCellCSSBuilder._forLayout()._withInlineFlex()._commit(content.style);

			let autoSizeType = this._owner._getAutoSizingTypeOfConstraint();
			if (this._owner.barItemWidths == NavigationBarItemWidths.equal && autoSizeType != layouts.AutoSizeType.both && autoSizeType != layouts.AutoSizeType.width) {
				content.style["width"] = "100%";
			}

			let itemShape: cpr.ufc.ElementShape = {
				tag: "li",
				styler: "item",
				style: {},
				// stylerBindContext: item.toExpressionContext(this._owner),
				bindContext: item.toExpressionContext(this._owner),
				classNames: [],
				attr: {
					"data-role": "menuitem",
					"data-itemid": item.value,
					"data-itemidx": index + "",
					id: this._getMenuItemId(item)
				},
				children: [content],
				nodename: this._getItemNodeName(index)
			}
			if (hasChild) {
				content.attr["aria-expanded"] = "false";
				let popupMenu = this._createPopupMenu(item, index);
				if (popupMenu) {
					itemShape.children.push(popupMenu);
				}
			}
			cpr.ufc.ShapeUtil._setTooltipAttr(itemShape, { owner: this._owner, title: item.tooltip, id: item.value });
			if (isSelected) {
				itemShape.attr["aria-current"] = "page";
				itemShape.classNames.push(ufc.Classes.SELECTED);
			}
			let isItemEnabled = this._owner.getItemEnable(item);
			cpr.ufc.ShapeUtil._setAriaDisabled(content, isItemEnabled && this._owner.enabled && !this._owner.readOnly);
			if (isItemEnabled && this._owner.enabled) {
				if (isHoveredItem) {
					itemShape.classNames.push(ufc.Classes.HOVER);
					if (hasChild && isOpened) {
						content.attr["aria-expanded"] = "true";
						itemShape.classNames.push("cl-navigationbar-visible");
					}
				}
			} else {
				itemShape.classNames.push(ufc.Classes.DISABLED);
				delete content.attr["tabindex"];
			}

			return itemShape;
		}

		/**
		 * 일반 메뉴에서 키 바인드
		 * @param e 
		 */
		protected override _navigateBar(e: events.CKeyboardEvent, item: MenuItem) {
			super._navigateBar(e, item);
			let hoveredItem = this._getHoveredItem();
			let menu: menu.IAccessibleMenu = null;
			if (this._isOpened(hoveredItem)) {
				menu = this._getActiveMenu();
			}

			let keyCode = e.keyCode;
			switch (keyCode) {
				case events.KeyCode.LEFT: {
					e.preventDefault();
					let traversedHover = null;
					if (item == null) {
						traversedHover = this._hoverBackward(item);
					} else if (item.depth > 0) {
						if (menu) {
							traversedHover = menu.traverseHover(keyCode, item);
							if (traversedHover) {
								let rootItem = this._getParent(traversedHover, (each) => {
									return each.depth == 0;
								});
								this._setHoveredItem(rootItem, { doInitSubMenu: true, nativeEvent: e });
							}
						}
						if (!traversedHover) {
							this._resetMenu();
							traversedHover = this._getHoveredItem();
						}
					} else {
						traversedHover = this._hoverBackward(item);
					}
					if (traversedHover) {
						if (traversedHover.depth == 0) {
							this._focusBySelector(NavigationBarItemFocusEntry.createSelector(traversedHover.value), { lazyItemFocus: false });
						} else {
							this._focusBySelector(menu._createFocusSelector(traversedHover.value), { lazyItemFocus: false });
						}
					}
					break;

				}
				case events.KeyCode.RIGHT: {
					e.preventDefault();
					let traversedHover = null;
					if (item == null) {
						traversedHover = this._hoverForward(item);
					} else if (item.depth > 0) {
						if (menu) {
							traversedHover = menu.traverseHover(keyCode, item);
							if (traversedHover) {
								let rootItem = this._getParent(traversedHover, (each) => {
									return each.depth == 0;
								})
								this._setHoveredItem(rootItem, { doInitSubMenu: true, nativeEvent: e });
							}
						}
						if (!traversedHover) {
							this._resetMenu();
							traversedHover = this._getHoveredItem();
						}
					} else {
						traversedHover = this._hoverForward(item);
					}
					if (traversedHover) {
						if (traversedHover.depth == 0) {
							this._focusBySelector(NavigationBarItemFocusEntry.createSelector(traversedHover.value), { lazyItemFocus: false });
						} else {
							this._focusBySelector(menu._createFocusSelector(traversedHover.value), { lazyItemFocus: false });
						}
						break;
					}
				}
				case events.KeyCode.UP:
					e.preventDefault();
					let traversedHover = null;
					if (item == null) break;
					if (item.depth > 0) {
						if (menu) {
							traversedHover = menu.traverseHover(keyCode, item);
						}
						if (!traversedHover) {
							this._resetMenu();
							traversedHover = this._getHoveredItem();
						}
					} else if (item._hasChild()) {
						if (menu) {
							traversedHover = menu._transferHoverBackward(item.children[0] as MenuItem);
						}
						if (!traversedHover) {
							traversedHover = this._hoverBackward(item);
						}
					} else {
						traversedHover = this._hoverBackward(item);
					}
					if (traversedHover) {
						if (traversedHover.depth == 0) {
							this._focusBySelector(NavigationBarItemFocusEntry.createSelector(traversedHover.value), { lazyItemFocus: false });
						} else {
							this._focusBySelector(menu._createFocusSelector(traversedHover.value), { lazyItemFocus: false });
						}
					}
					break;
				case events.KeyCode.DOWN: {
					e.preventDefault();
					let traversedHover = null;
					if (item == null) break;
					if (item.depth > 0) {
						if (menu) {
							traversedHover = menu.traverseHover(keyCode, item);
						}
						if (!traversedHover) {
							let rootItem = this._getParent(item, (each) => {
								return each.depth == 0;
							})
							traversedHover = this._hoverForward(rootItem);
						}
					} else if (item._hasChild()) {
						traversedHover = menu ? menu._transferHoverDownCycle(item) : null;
						if (!traversedHover) {
							traversedHover = this._hoverForward(item);
						}
					} else {
						traversedHover = this._hoverForward(item);
					}
					if (traversedHover) {
						if (traversedHover.depth == 0) {
							this._focusBySelector(NavigationBarItemFocusEntry.createSelector(traversedHover.value), { lazyItemFocus: false });
						} else {
							this._focusBySelector(menu._createFocusSelector(traversedHover.value), { lazyItemFocus: false });
						}
					}
					break;
				}
				case events.KeyCode.ENTER: {
					if (item == null) break;
					this._onItemSelect(item, e, (success: boolean) => {
						if (success) {
							if (this._close({ nativeEvent: e })) {
								if (item.parentItem != null) {
									this._focusBySelector(this._getFocusSelector(this._getTopParentItem(item)), { immediate: true, lazyItemFocus: false });
								}
								this._resetMenu();
							}
						}
					});
					break;
				}
				case events.KeyCode.ESC: {
					if (item == null) break;
					if (item.depth > 0) {
						let traversedHover = menu._transferHoverUpCycle(item);
						if (!traversedHover) {
							this._resetMenu();
							traversedHover = this._getParent(item, (each) => {
								return each.depth == 0;
							});
						}

						if (traversedHover) {
							if (traversedHover.depth == 0) {
								this._focusBySelector(NavigationBarItemFocusEntry.createSelector(traversedHover.value), { lazyItemFocus: false });
							} else {
								this._focusBySelector(menu._createFocusSelector(traversedHover.value), { lazyItemFocus: false });
							}
						}
					}
					break;
				}
			}

		}

		/* private method */
		/* event start */

		protected override _onmousedown(e: MouseEvent) {
			if (e.defaultPrevented) {
				if (!_isIE()) e.preventDefault();
				return;
			}
			let target: HTMLElement = <HTMLElement>e.target;
			let rootElement = e.currentTarget as HTMLElement;

			if (target.classList.contains("cl-navigationbar-bar") && !this._owner.focused) {
				this._owner._focusSelf();
				if (!_isIE()) e.preventDefault();
			} else {
				let submenu = this._getActiveMenu();
				if (submenu) {
					let submenuNode = this._owner._getRenderer().getNamedNode(submenu.getRootNodeName());
					if (submenuNode && submenuNode.contains(target)) {
						rootElement = submenuNode;
					}
				}
				let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(target)._closest("[data-role='menuitem']", rootElement);
				if (domTraverser) {
					let itemValue = domTraverser._getAttribute("data-itemid");
					let item = this._owner.getItemByValue(itemValue);
					if (this._owner.getItemEnable(item)) {
						let selector = null;
						if (item.parentItem) {
							selector = submenu ? submenu._createFocusSelector(domTraverser._getAttribute("data-itemid")) : "";
						} else {
							selector = NavigationBarItemFocusEntry.createSelector(domTraverser._getAttribute("data-itemid"));
						}
						this._focusBySelector(selector, { preventOpen: true, lazyItemFocus: false, useSameCheck: false });
					} else if (!this._owner.focused) {
						this._owner._focusSelf();
					}
				} else if (!this._owner.focused) {
					this._owner._focusSelf();
				}
				// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/9848
				if (!_isIE()) e.preventDefault();
			}

			if (this._owner.focused) {
				return;
			}
			if (!this._focusTrigger) this._focusTrigger = { type: "mousedown", forward: true };

		}

		protected override _onmouseover(e: MouseEvent) {
			let rootElement: HTMLElement = <HTMLElement>e.currentTarget;
			let eventElement: HTMLElement = <HTMLElement>e.target;

			this._onmouseenter(e);

			let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(eventElement)._closest("[data-role='menuitem']", rootElement);
			if (domTraverser == null) {
				return;
			}

			let item: MenuItem = this._getItemByElement(domTraverser._getElement());
			if (item == null) {
				throw new cpr.exceptions.CError("The item does not exist.");
			}

			let isSameItemMouseOver = this._beforeMouseoverItem?._equalsValue(item) ?? false;
			// dispatchItemMouseover에서 _beforeMouseoverItem 값 갱신
			if (!this._dispatchItemMouseover(item, e) || this._owner.expandTrigger == "click") {
				return;
			}
			if (this._owner.getItemEnable(item)) {
				if (!isSameItemMouseOver) {
					this._setOpen(item, { nativeEvent: e });
				}
				if (this._isHoveredItem(item) == false) {
					this._setHoveredItem(item, { doInitSubMenu: true, updateScroll: false, nativeEvent: e, preventOpen: true });
				}
			}
		}

		protected override _ontouchstart(e: events.CTouchEvent) {
			let touch = e.touches.length == 1 ? e.touches[0] : null;
			let target = e.target as HTMLElement;

			let submenu = this._getActiveMenu();
			if (submenu) {
				let submenuNode = this._owner._getRenderer().getNamedNode(submenu.getRootNodeName());
				if (submenuNode.contains(target)) {
					return;
				}
			}

			if (touch != null) {
				this._touchMoved = false;
			}
			this._startTouchEvent();
			//prevneDefault를 하면 마우스 이벤트가 발생하지 않는 대신 미세한 차이에도 touchmove가 발생함.
			let barContentNode = this._getBarContentNode();
			let scrollLeft = barContentNode.scrollLeft;
			this._touchRoller._touchStart(e, 0, scrollLeft);
		}

		protected override _onMenuMouseLeave(e: events.CMouseEvent) {
			let rootNode = this._owner._getRenderer().getRootNode();
			if (rootNode.contains(e.target as HTMLElement)) {
				return;
			}
		}

	}
}