namespace cpr.geometry {
	/**
	 * 상하좌우 여백을 추상화 하는 지오메트리 연산 객체.
	 */
	export class Insets implements Transposable {
		/**
		 * 위 기본값 0
		 */
		top: number = 0;
		/**
		 * 오른쪽 기본값 0
		 */
		right: number = 0;
		/**
		 * 아래 기본값 0
		 */
		bottom: number = 0;
		/**
		 * 왼쪽 기본값 0
		 */
		left: number = 0;

		/**
		 * 
		 * @param top 상단 여백
		 * @param right 우측 여백
		 * @param bottom 하단 여백
		 * @param left 좌측 여백
		 */
		constructor(top: number, right: number, bottom: number = undefined, left: number = undefined) {
			if (typeof bottom == "undefined") {
				bottom = top;
			}
			if (typeof left == "undefined") {
				left = right;
			}

			this.top = top;
			this.right = right;
			this.bottom = bottom;
			this.left = left;
		}

		/**
		 * 상단 및 하단의 여백의 합을 얻습니다.
		 */
		public get height() {
			return this.top + this.bottom;
		}

		/**
		 * 좌우 여백의 합을 얻습니다.
		 */
		public get width() {
			return this.left + this.right;
		}

		/**
		 * 여백을 추가합니다.
		 * @param other 추가할 다른 여백 객체.
		 */
		public add(other: Insets): Insets {
			this.top += other.top;
			this.right += other.right;
			this.bottom += other.bottom;
			this.left += other.left;
			return this;
		}

		/**
		 * 다른 여백이 추가된 사본 객체를 얻습니다.
		 * @param other 추가할 여백.
		 */
		public getAdded(other: Insets) {
			return this.getCopy().add(other);
		}

		/**
		 * x축과 y축을 반전 시킵니다.
		 */
		public transpose(): this {
			let temp = this.top;
			this.top = this.left;
			this.left = temp;

			temp = this.right;
			this.right = this.bottom;
			this.bottom = temp;

			return this;
		}

		/**
		 * x축과 y축이 반전된 사본을 얻습니다.
		 */
		public getTransposed(): Insets {
			return this.getCopy().transpose();
		}

		/**
		 * 사본 객체를 얻습니다.
		 */
		public getCopy(): Insets {
			return new Insets(this.top, this.right, this.bottom, this.left);
		}

		/**
		 * 상하좌우의 여백을 모두 반전시킵니다.
		 */
		public negate(): Insets {
			this.top *= -1;
			this.right *= -1;
			this.bottom *= -1;
			this.left *= -1;
			return this;
		}

		/**
		 * 모든 여백이 비어있는지 여부를 반환합니다.
		 */
		public isEmpty(): boolean {
			return this.top === 0 && this.right === 0 && this.bottom === 0 && this.left === 0;
		}
	}
}