/// <reference path="./IGridCellRenderer.ts"/>


namespace cpr.controls.gridpart.renderer {

	/**
	 * @private
	 */
	export class EmbeddedHeaderCellRendererFactory {
		private static _instance = new EmbeddedHeaderCellRendererFactory();

		public static _getRenderer(columntype: string): (grid: Grid, cellProp: GridHeaderCellProp) => ufc.ControlShape {
			let flyweight: (grid: Grid, cellProp: GridHeaderCellProp) => ufc.ControlShape = null;
			switch (columntype) {
				case "checkbox": {
					flyweight = EmbeddedHeaderCellRendererFactory._instance._renderCheckBox;
					break;
				}
			}
			return flyweight;
		}

		private _renderCheckBox(grid: Grid, cellProp: GridHeaderCellProp): ufc.ControlShape {
			let checked: string = grid._getHeaderChecked()
			let enabled: boolean = grid.isHeaderCheckColumnEnabled();
			let visible: boolean = grid._isHeaderCheckColumnVisibled();

			let nodename: string = "c" + cellProp.constraint.cellIndex;

			let iconShape: ufc.ElementShape = {
				tag: "div",
				classNames: [GridStyle.CHECKBOXICON],
				attr: {
					tabindex: "0",
					role: "checkbox",
					"data-role": "checkbox"
				},
				style: {
					// display: "block",
					// cursor: "pointer",
					"vertical-align": "inherit",
				}
			};
			GridUtil._setAria(iconShape, "checked", (checked == CHECKMODE.CHECKED || checked == CHECKMODE.PARTIAL_ALL_CHECKED) ? "true" : "false",);
			cpr.ufc.ShapeUtil._setAriaLabelAttr(iconShape.attr, cpr.I18N.INSTANCE.message(core.PlatformTerms.ALLROW_CHECK));
			let iconWraaper: ufc.ControlShape = {
				tag: "div",
				classNames: ["cl-icon-wrapper"],
				style: {
					display: "table-cell",
					"vertical-align": "inherit",
					"text-align": "inherit"
				},
				children: [iconShape],
			}
			let layout: ufc.ControlShape = {
				tag: "div",
				style: {
					display: "inline-table",
					height: "100%",
					"vertical-align": "inherit",
					"text-align": "inherit"
				},
				children: [iconWraaper]
			};

			let classNames: string[] = [GridStyle.CONTROL, GridStyle.CHECKBOX, EmbeddedCellRendererFactory._builtinClass, GridContext.CLS_CTRL_INHERIT];
			switch (checked) {
				case CHECKMODE.CHECKED: {
					classNames.push(ufc.Classes.CHECKED);
					break;
				}
				case CHECKMODE.PARTIAL_CHECKED:
				case CHECKMODE.PARTIAL_ALL_CHECKED:
				case CHECKMODE.PARTIAL_ALL_UNCHECKED: {
					classNames.push(ufc.Classes.PARTIALCHECKED);
					break;
				}
			}

			if (grid.enabled == false || enabled == false) {
				classNames.push(ufc.Classes.DISABLED);
			}
			cpr.ufc.ShapeUtil._setAriaDisabled(iconShape, grid.enabled);
			let shape: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: classNames,
				attr: {},
				style: {
					width: "100%",
					height: "100%"
				},
				events: {
					mousedown: (e: events.CMouseEvent) => {
						// e.stopPropagation();
					},
					click: (e: events.CMouseEvent) => {
						if (e && _getProperty(grid, "enabled", true) !== false && _getProperty(grid, "visible", true) !== false) {
							EmbeddedHeaderCellRendererFactory._instance._handlerCheckboxToggleCheck(e, grid, nodename, cellProp);
							// Grid click 이벤트 전파를 위해 해당코드를 주석처리합니다.
							// e.stopPropagation();
						}
					},
					keydown: (e: events.CKeyboardEvent) => {
						if (e && _getProperty(grid, "enabled", true) !== false && _getProperty(grid, "visible", true) !== false) {
							if (e.keyCode == events.KeyCode.SPACE) {
								EmbeddedHeaderCellRendererFactory._instance._handlerCheckboxToggleCheck(e, grid, nodename, cellProp);
								e.preventDefault();
							}
						}
					}
				},
				nodename: nodename,
				children: [layout]
			};

			if (visible == false) {
				shape.style["display"] = "none";
			}

			return shape;
		}
		private _handlerCheckboxToggleCheck(e: (events.CMouseEvent | events.CKeyboardEvent), grid: Grid, nodename: string, cellProp: GridHeaderCellProp): void {
			let beforeChecked: CHECKMODE = grid._getHeaderChecked();
			let enabled: boolean = grid.isHeaderCheckColumnEnabled();
			if (enabled == false) {
				return;
			}
			let checked: CHECKMODE = grid._toggleHeaderCheckBox(cellProp);

			if (beforeChecked == checked) {//enabled 설정으로 인해 checked 상태가 변경되지 않음.
				return;
			}

			let gridpart: IGridPart = new GridEmbeddedHeaderCell(grid, nodename, cellProp.constraint.cellIndex, (cellIndex: number) => {
				let shape: ufc.ElementShape = this._renderCheckBox(grid, cellProp);

				return shape;
			});
			grid._applyPiece(gridpart);

			// GRID Event Dispatch
			let eventType: string = null;
			if (checked == CHECKMODE.CHECKED || checked == CHECKMODE.PARTIAL_ALL_CHECKED) {
				eventType = events.GridEventType.HEADER_CHECK
			} else if (checked == CHECKMODE.UNCHECKED || checked == CHECKMODE.PARTIAL_ALL_UNCHECKED) {
				eventType = events.GridEventType.HEADER_UNCHECK;
			}
			if (eventType != null) {
				let eventObj: events.CGridEvent = new events.CGridEvent(eventType, {
					relativeTargetName: "header"
				});
				eventObj.nativeEvent = e;
				grid.dispatchEvent(eventObj);
			}

		}

	}


	/**
	 * @private
	 */
	export class EmbeddedHeaderCellRenderer extends AbstractGridCellRenderer {


		constructor(cellprop: GridCellProp, grid: Grid) {
			super(cellprop, grid);
		}

		private get headerprop(): GridHeaderCellProp {
			return this.prop as GridHeaderCellProp;
		}

		public static isAccept(headercellprop: GridHeaderCellProp): boolean {
			if (headercellprop && headercellprop.configuration.columnType && ["checkbox"].indexOf(headercellprop.configuration.columnType) != -1) {
				return true;
			}
			return false;
		}

		protected _init(): void {
		}

		public createCellShape(): ufc.ControlShape | ufc.ControlRenderer {

			let renderer: (grid: Grid, cellprop: GridCellProp) => ufc.ControlShape
				= EmbeddedHeaderCellRendererFactory._getRenderer(this.headerprop.configuration.columnType);

			let controlShape: ufc.ControlShape = renderer(this.grid, this.headerprop);

			return controlShape;
		}


	}

}