/// <reference path="../Submission.ts"/>


namespace cpr.protocols.request {
	/**
	 * @private
	 */
	export class URLEncodedRequestBuilder extends AbstractRequestBuilder {
		public static _assembleEncodingResult(submission: Submission, encodingResult: EncodingResult): string {
			let key: string = encodingResult.key;
			let value: {} | string = encodingResult.content;
			let stringValue: string = null;
			if (typeof value == "string") {
				stringValue = value;
			} else if (value != null) {
				stringValue = JSON.stringify(value);
			} else {
				stringValue = "";
			}

			let requestString: string = null;
			if (key) {
				requestString = URLEncodedRequestBuilder._encode(key) + "=" + stringValue; //URLEncodedRequestBuilder._encode(stringValue);
			} else {
				requestString = stringValue; //URLEncodedRequestBuilder._encode(stringValue);
			}

			// if (submission.method == Submission.METHOD_GET) {
			if (Submission._HASBODY_METHOD.indexOf(submission.method) === -1) {
				let actionURL: string = submission.getRequestActionUrl();
				if (actionURL.indexOf("?") > -1) {
					if (actionURL.substring(actionURL.length - 1) == "&") {
						actionURL += requestString;
					} else {
						actionURL += "&" + requestString;
					}
				} else {
					actionURL += "?" + requestString;
				}
				submission.setRequestActionUrl(actionURL);

				return null;
			}

			return requestString;
		}

		public static _setGetMethodParameter(submission: Submission, requestString: string): void {
			let actionURL: string = submission.getRequestActionUrl();
			if (actionURL.indexOf("?") > -1) {
				if (actionURL.substring(actionURL.length - 1) == "&") {
					actionURL += requestString;
				} else {
					actionURL += "&" + requestString;
				}
			} else {
				actionURL += "?" + requestString;
			}
			submission.setRequestActionUrl(actionURL);
		}

		public static _encode(name: string): string {
			if (name == null) {
				return "";
			}
			return encodeURIComponent(name);
		}


		constructor() {
			super();
		}

		public getContentType(): string {
			return Submission.MEDIA_URLENCODED;
		}

		protected _buildSpecific(submission: Submission): any {
			let requestString: string = null;

			let requestEncoderSpec: RequestEncoderSpec = submission._getRequestEncoder();
			if (requestEncoderSpec && requestEncoderSpec.encoder) {
				if (requestEncoderSpec.usingBuildData) {
					requestString = this._buildRequestString(submission);
				}

				let returnValue: Promise<EncodingResult> | EncodingResult = requestEncoderSpec.encoder(submission, requestString);
				if (returnValue instanceof Promise) {
					return returnValue.then((encodingResult: EncodingResult) => {
						if (Submission._HASBODY_METHOD.indexOf(submission.method) >= 0) {
							if (encodingResult.contentType) {
								submission._setInstantContentType(encodingResult.contentType);
							}
						}
						return URLEncodedRequestBuilder._assembleEncodingResult(submission, encodingResult);
					});
				} else {
					if (Submission._HASBODY_METHOD.indexOf(submission.method) >= 0) {
						if (returnValue.contentType) {
							submission._setInstantContentType(returnValue.contentType);
						}
					}
					return URLEncodedRequestBuilder._assembleEncodingResult(submission, returnValue);
				}
			} else {
				requestString = this._buildRequestString(submission);

				// get method 처리
				if (Submission._HASBODY_METHOD.indexOf(submission.method) == -1) {
					URLEncodedRequestBuilder._setGetMethodParameter(submission, requestString);
					return null;
				}

				return requestString;
			}
		}

		public _buildRequestString(submission: Submission): string {
			let requestString: string = "";

			// check requestObject
			let requestObject: Object = submission.getRequestObject();
			if (requestObject != null) {
				let jsonstring: string = JSON.stringify(requestObject);

				let pNm: string = URLEncodedRequestBuilder._encode(AbstractRequestBuilder.REQOBJ_PARAMNAME);
				requestString += pNm + "=" + URLEncodedRequestBuilder._encode(jsonstring) + "&";
			}

			// parameter
			let paramNames: string[] = submission.getParameterNames();
			paramNames.forEach((name: string) => {
				let encodedName: string = URLEncodedRequestBuilder._encode(name);
				let values: string[] = submission.getParameters(name);
				values.forEach((value: string) => {
					requestString += encodedName + "=" + URLEncodedRequestBuilder._encode(value) + "&";
				});
			});

			// datamap/dataset
			let requestDataCount: number = submission.getRequestDataCount();
			for (let idx: number = 0; idx < requestDataCount; idx++) {
				let requestData: RequestData = submission.getRequestData(idx);
				let alias: string = this._getRequestAlias(requestData);
				if (requestData.data instanceof data.DataSet) {
					let dataSet: data.DataSet = requestData.data as data.DataSet;
					requestString += this._buildDataSet(submission, dataSet, alias, requestData.payload);
				} else {
					let dataMap: data.DataMap = requestData.data as data.DataMap;
					requestString += this._buildDataMap(submission, dataMap, alias);
				}
			}

			let ampersandLastIndex: number = requestString.lastIndexOf("&");
			if (ampersandLastIndex == requestString.length - 1) {
				requestString = requestString.slice(0, ampersandLastIndex);
			}

			return requestString;
		}

		private _buildDataSet(submission: Submission, dataSet: data.DataSet, alias: string, payload: PayloadType): string {
			let dataDelimiter: string = super._createDataDelimiter();

			let requestString: string = "";
			this._loadPayload(submission, dataSet, payload, (rowdata: data.RowConfigInfo, additionalParam: { [key: string]: string }, stateText: string) => {
				for (let columnName in rowdata) {
					let name: string = URLEncodedRequestBuilder._encode(dataDelimiter + columnName);
					let value: string | number | boolean = rowdata[columnName];
					if (value == null) {
						value = "";
					}
					value = URLEncodedRequestBuilder._encode("" + value);
					requestString += name + "=" + value + "&";
				}

				requestString += this._applyAdditionalParam(additionalParam, dataDelimiter);

				let statName: string = dataDelimiter + "sts"; // TODO 공통화
				requestString += URLEncodedRequestBuilder._encode(statName) + "=" + URLEncodedRequestBuilder._encode(stateText) + "&";
			});

			requestString += URLEncodedRequestBuilder._encode(super._getDataDelimiterParamName()) + "=" + URLEncodedRequestBuilder._encode(dataDelimiter) + "&";
			if (alias) {
				requestString += URLEncodedRequestBuilder._encode(dataDelimiter) + "=" + URLEncodedRequestBuilder._encode(alias) + "&";
			}
			requestString += URLEncodedRequestBuilder._encode(dataDelimiter + "tp") + "=ds&"; // parameter group type

			return requestString;
		}

		private _buildDataMap(submission: Submission, dataMap: data.DataMap, alias: string): string {
			let requestString: string = "";
			let columnNames: string[] = dataMap.getColumnNames();
			let dataDelimiter: string = super._createDataDelimiter(); // DataMap 별로 생성
			columnNames.forEach((columnName: string) => {
				let name: string = URLEncodedRequestBuilder._encode(dataDelimiter + columnName);
				let value: string = dataMap.getString(columnName);
				if (value == null) {
					value = "";
				}
				value = URLEncodedRequestBuilder._encode(value);
				requestString += name + "=" + value + "&";
			});

			requestString += this._applyAdditionalParam(submission._handleDataMap(dataMap), dataDelimiter);

			requestString += URLEncodedRequestBuilder._encode(super._getDataDelimiterParamName()) + "=" + URLEncodedRequestBuilder._encode(dataDelimiter) + "&";
			if (alias) {
				requestString += URLEncodedRequestBuilder._encode(dataDelimiter) + "=" + URLEncodedRequestBuilder._encode(alias) + "&";
			}
			requestString += URLEncodedRequestBuilder._encode(dataDelimiter + "tp") + "=dm&"; // parameter group type

			return requestString;
		}

		private _applyAdditionalParam(additionalParam: { [key: string]: string }, dataDelimiter: string): string {
			if (additionalParam) {
				let strParams: string[] = [];
				for (let key in additionalParam) {
					let name: string = URLEncodedRequestBuilder._encode(dataDelimiter + key);
					let value: string = additionalParam[key];
					if (value == null) {
						value = "";
					}
					value = URLEncodedRequestBuilder._encode(value);

					strParams[strParams.length] = name;
					strParams[strParams.length] = "=";
					strParams[strParams.length] = value;
					strParams[strParams.length] = "&";
				}
				return strParams.join("");
			}
			return "";
		}
	}
}