namespace cpr {

	export interface ILocaleNumber {
		formatParts: ILocaleNumberFormatParts
	}

	export interface ILocaleNumberFormatParts {
		group: string
		decimal: string
	}

	/**
	 * @noinstance
	 */
	export class LocaleNumber extends SubLocale implements ILocaleNumber {
		private _formatParts: ILocaleNumberFormatParts;

		constructor(parent: LocalePropertyProvider) {
			super(parent);
			this._formatParts = new LocaleNumberFormatParts(this);
		}

		public get formatParts(): ILocaleNumberFormatParts {
			return this._formatParts;
		}
	}

	export class LocaleNumberFormatParts extends SubLocale implements ILocaleNumberFormatParts {
		public get group(): string {
			return this._getProperty(localeData => localeData.number?.formatParts?.group);
		}
		public get decimal(): string {
			return this._getProperty(localeData => localeData.number?.formatParts?.decimal);
		}
	}

}