/// <reference path="./Layout.ts"/>
/// <reference path="../UIControl.ts"/>


namespace cpr.controls.layouts {
	/**
	 * 
	 */
	export abstract class AbstractXYLayout<T extends Constraint> extends Layout<T> {

		constructor() {
			super();
		}

		protected _doCreateLayoutShape(): cpr.ufc.ControlShape {
			let childControls: UIControl[] = this._owner.getChildren();
			let layoutShape: ufc.ControlShape = {
				tag: "div",
				nodename: LayoutConstants.NODE_NAME__LAYOUT,
				attr: {
				},
				classNames: [ufc.Classes.LAYOUT],
				style: _mergeObject({
					position: "relative",
					left: "0px",
					top: "0px",
					right: "0px",
					bottom: "0px",
					boxSizing: "content-box"
				}, this._getLayoutShapeStyle()),
				events: { scroll: this._notifyScrollEvent.bind(this) },
				children: []
			};

			let contentPane: ufc.ElementShape = {
				tag: "div",
				nodename: LayoutConstants.NODE_NAME__CONTENT_PANE,
				classNames: [ufc.Classes.CONTENT_PANE],
				style: {
					position: "relative",
					left: "0px",
					top: "0px",
					width: "100%",
					height: "100%",
					boxSizing: "content-box"
				},
				children: this.applyLayoutShape(childControls)
			}
			layoutShape.children = [contentPane];

			if (this._owner.childCombinatorClass) {
				layoutShape.classNames.push(this._owner.childCombinatorClass);
				contentPane.classNames.push(this._owner.childCombinatorClass);
			}

			this._owner._hookLayout(LayoutConstants.NODE_NAME__CONTENT_PANE, contentPane);

			if (this.scrollable) {
				// shape.classNames = shape.classNames.concat(utils.Util._getScrollInfo().classNames);
				internal.ScrollbarUtil._markScrollableContentPane(layoutShape); // CustomScroll Enable
			}

			return layoutShape;
		}

		protected abstract _getLayoutShapeStyle(): any;

		protected abstract applyConstraint(index: number
			, control: UIControl, controlRenderer: ufc.ControlRenderer): ufc.ControlRenderer | ufc.ControlShape;

		protected applyLayoutShape(childControls: UIControl[]): (ufc.ControlRenderer | ufc.ControlShape)[] {
			let layoutShape: (ufc.ControlRenderer | ufc.ControlShape)[] = [];

			childControls.forEach((control: UIControl, index: number) => {
				if (control == null || control.disposed == true) {
					return;
				}
				let controlRenderer: ufc.ControlRenderer = control._getRenderer();
				if (controlRenderer == null) {
					return;
				}

				let controlShape: ufc.ControlRenderer | ufc.ControlShape = this.applyConstraint(index, control, controlRenderer);

				if (controlShape) {
					layoutShape.push(controlShape);
				}
			});

			return layoutShape;
		}

		protected _doUpdateControl(controls: UIControl[]): void {
			controls.forEach((control: UIControl) => {
				control.redraw();
			});
		}
	}

}