/// <reference path="./AbstractScrollStrategy.ts" />


namespace cpr.controls.gridpart.layout {


	/**
	 * @private
	 * GridHeader와 GridFooter를 처리하기 위한 ScrollStrategy
	 */
	export class PassiveScrollStrategy extends AbstractScrollStrategy {


		constructor(scrollPane: IScrollPane, context: GridContext) {
			super(scrollPane, context);
		}

		public _getRenderedMaxScrollTop(): number {
			return 0;
		}

		public _getRenderedMaxScrollLeft(): number {
			let viewWidth: number = this._getViewportWidth();
			let contentWidth: number = this._scrollPane.owner._getContentWidth();
			let maxScrollLeft: number = contentWidth - viewWidth;
			maxScrollLeft = maxScrollLeft < 0 ? 0 : maxScrollLeft;
			return maxScrollLeft;
		}

		public _readyForRedraw(): void {
			// scroll 초기화 
			// core.DeferredUpdateManager.INSTANCE.asyncExec로 초기화 할 경우
			// IE에서 시점의 문제로 scroll이 표시되지 않는 문제 때문에 scroll 초기화는 실시간으로 처리
			if (this.context.disposed == true) {
				return;
			}

			// DOM의 scroll 위치는 redraw 후 동기화할 때 처리하여 흰 화면이 나오지 않도록 한다
			this.viewportscrollleft = 0;
			this._settedScrollLeft = -1;

			// this._setHScroll(0);
		}

		public _initScrollTop(scrollTop: number): void {
		}
		public _initScrollLeft(scrollLeft: number): void {
			this._setHScroll(scrollLeft);
		}
		public _createScrollPane(): ufc.ControlShape {
			this._init();
			core.DeferredUpdateManager.INSTANCE.asyncExec(this._syncScrollFunc);

			let contentView: IGridPartArea = this._scrollPane.owner;
			let vscrollbarWidth: string = this._getVScrollWidth();
			let rowGroupChildren: ufc.ElementShapeContent[] = [];

			// scroll hidden이지만, mousewheel을 통해 스크롤링이 가능하게 하기 위해 생성하도록 함
			let scrollContainer: ufc.ControlShape = {
				tag: "div",
				attr: {
					"data-role": "scroll-container"
				},
				style: {
					"overflow": "hidden",
					position: "absolute",
					transform: "translate3d(0px, 0px, 0px)",
					left: "0px",
					top: "0px",
					right: "0px",
					bottom: "0px"
				},
				events: {
					scroll: (e: events.CUIEvent) => { this._onViewportScroll(e); }, // tab key에 의한 컨트롤 간의 스크롤 처리
					wheel: (e: events.CWheelEvent) => { this._onDOMWheel(e); },
					touchstart: (e: events.CTouchEvent) => { this._onTouchStart(e); },
					touchmove: (e: events.CTouchEvent) => { this._onTouchMove(e); },
					touchend: (e: events.CTouchEvent) => { this._onTouchEnd(e); }
				},
				nodename: "scr-" + this._scrollPane.region + "-" + this._scrollPane.location,
				children: []
			};

			if (this._scrollPane.region == GRIDREGION.CENTER && this.context._isReqVScroll() == true) {
				scrollContainer.style["right"] = vscrollbarWidth;
			}

			if (this.context._isReqHScroll() == false && this.context._isReqVScroll() == false) {
				delete scrollContainer.style["transform"];
			}

			scrollContainer.children[0] = contentView._createShape();

			rowGroupChildren[rowGroupChildren.length] = scrollContainer;

			// (2018-02-12) header, detail, footer에 스크롤이 생긴 나머지 영역에 스타일 제공을 위한 div를 생성.
			if (this._scrollPane.region == GRIDREGION.CENTER) {
				if (this.context._isReqVScroll() == true) {
					rowGroupChildren[rowGroupChildren.length] = {
						tag: "div",
						attr: {},
						classNames: [GridStyle.BLANK],
						nodename: this._scrollPane.location + "-blank",
						style: {
							position: "absolute",
							width: vscrollbarWidth,
							top: "0px",
							right: "0px",
							bottom: "0px"
						},
						children: []
					};
				} else {
					rowGroupChildren[rowGroupChildren.length] = {
						tag: "div",
						attr: {},
						classNames: [GridStyle.BLANK],
						style: {
							display: "none",
							position: "absolute",
							width: "0px",
							top: "0px",
							right: "0px",
							bottom: "0px"
						},
						children: []
					};
				}
			}

			let shape: ufc.ControlShape = {
				tag: "div",
				attr: {
					"data-role": GRIDROLE.ROWGROUP,
					"data-loc": this._scrollPane.location
				},
				style: {
					position: "relative",
					display: "block",
					width: "100%",
					height: "100%"
				},
				nodename: this._scrollPane.nodename,
				children: rowGroupChildren
			};

			return shape;
		}

		private _getVScrollWidth(): string {
			let vscrollWidth: number = -1;
			if (this.grid._isUseCustomScroll()) {
				let scrollbarInfo: internal.ScrollbarInfo = internal.ScrollbarUtil._getCustomScrollbarInfo();
				vscrollWidth = scrollbarInfo.vWidth;
			} else {
				vscrollWidth = internal.ScrollbarUtil._getNativeScrollWidth();
			}
			return vscrollWidth + "px";
		}

		/* EventHandler */
		protected _dispatchScrollEvent(e, axis: events.ScrollAxis): void { /////////////////////////////////////
			this._context._dispatchScrollEvent(e, {
				axis: events.ScrollAxis.x,
				scrollTop: 0,
				maxScrollTop: 0,
				scrollLeft: this._scrollPane._getBusScrollLeft(),
				maxScrollLeft: this._getRenderedMaxScrollLeft()
			});
		}

		protected _onViewportScroll(e: events.CUIEvent): void {
			// 가로 스크롤만 처리
			let target: HTMLElement = <HTMLElement>e.target;
			let scrollLeft: number = target.scrollLeft;

			if (this._settedScrollLeft !== -1 && GridUtil._equalsApproximately(scrollLeft, this._settedScrollLeft)) {
				scrollLeft = this.viewportscrollleft;
				this._settedScrollLeft = -1;
			}

			this._adjustViewportScroll(e, this.viewportscrolltop, scrollLeft);
		}

		protected _onDOMWheel(e: events.CWheelEvent): void {
			if (e._isOccupied() == true) {
				return;
			}
			if (e._getMod1Key() === true) { // 확대/축소
				return;
			}
			if (e.target instanceof HTMLTextAreaElement) {
				return;
			}
			if (this._context._isReqHScroll() == false) {
				return;
			}
			if (this._isEnabled() == false) {
				return;
			}

			if (e._getMod2Key()) {
				if (this.grid.hScroll != "hidden") {
					let eventDelta: { x: number, y: number } = internal.ScrollbarUtil._getScrollPaneWheelDelta(e);
					let axis: events.ScrollAxis = this._adjustScroll(e, this.viewportscrolltop, this.viewportscrollleft + eventDelta.x);
					if (axis != null) {
						e.preventDefault();
						e.stopPropagation();

						this._dispatchScrollEvent(e, events.ScrollAxis.x); // grid scroll event
					}
				}
			}
		}

		protected _adjustScroll(e: events.CEvent, scrollTop: number, scrollLeft: number): events.ScrollAxis {
			scrollLeft = scrollLeft < 0 ? 0 : scrollLeft;
			if (scrollLeft != this.viewportscrollleft) {
				let maxScrollLeft: number = this._getRenderedMaxScrollLeft();
				if (scrollLeft > maxScrollLeft) {
					scrollLeft = maxScrollLeft;
				}
				if (scrollLeft != this.viewportscrollleft) {
					this._moveFocusToGrid();
					this._adjustViewportScroll(e, scrollTop, scrollLeft);
					return events.ScrollAxis.x;
				}
			}
			return null;
		}

		public _handleScrollLeft(e: events.CScrollEvent): void { // TODO 확인필요
			if (typeof e.scrollLeft != "number" || this.viewportscrollleft == e.scrollLeft) {
				return;
			}
			// scrollLeft 동작시 스크롤 이동을 redraw 시점과 일치화 시키기 위해 async로 동작시킴
			core.DeferredUpdateManager.INSTANCE._asyncExecBefore(() => {
				_performIfAlive(this.grid, () => {
					let scrollLeft: number = this._scrollPane._getBusScrollLeft();
					this._settedScrollLeft = scrollLeft;
					this._setHScroll(scrollLeft);
				});
			});

			this._selfRedraw();
		}

		protected _setHScroll(scrollLeft: number): void {
			// viewport의 scrollleft 조정
			let gridRenderer: ufc.ControlRenderer = this.grid._getRenderer();
			let viewportElement: HTMLElement = gridRenderer.getNamedNode("scr-" + this._scrollPane.region + "-" + this._scrollPane.location);
			if (viewportElement && viewportElement.scrollLeft != scrollLeft) {
				viewportElement.scrollLeft = scrollLeft;
			}

			this.viewportscrollleft = scrollLeft;
		}

		protected _syncScroll(): void {
			if (this._context == null || this._context.disposed == true) {
				return;
			}
			if (this._settedScrollLeft == -1) {
				let eventScrollLeft: number = this._scrollPane._getBusScrollLeft();
				if (eventScrollLeft != -1) {
					this._setHScroll(eventScrollLeft);
				}
			}
		}
	}
}