		_makeSpecificDropContext(constraint: DropContext) {
			let targetElement = constraint._getTargetElement();
			if (targetElement) {
				let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(targetElement);
				if (domTraverser == null) {
					return;
				}

				let itemNode = domTraverser._closest("[data-region='colgroup']");
				if (itemNode == null) {
					return constraint;
				}

				let value = itemNode._getAttribute("data-value");
				let theItem = this.getItemByValue(value);
				if (theItem) {
					constraint.targetItem = theItem;
				}
			}

			return constraint;
		}

