namespace cpr.controls.gridpart.config {

	export class GridCellConfigurator {
		private _grid: Grid;
		private _constraint: ControlConstraint;
		private _cellStyler: GridStyler;
		private _control: GridUIControl;

		protected _bindables: bind.BindableProperties;
		private _formula: string = null;


		constructor(grid: Grid) {
			this._grid = grid;
			this._cellStyler = new GridStyler(grid);
			this._constraint = {};

			this._bindables = new bind.BindableProperties(grid);
			this._bindables.add("tooltip", null)
				.withGetterTransformer((text: string | number | foundation.DecimalType) => {
					return utils.Util.toString(text);
				})
				.withSetterValidatorWithType(false, "string");
			this._bindables.add("fieldLabel", "").withSetterValidatorWithType(false, "string");
		}

		/**
		 * @private
		 */
		protected get grid(): Grid {
			return this._grid;
		}
		public _getGrid() {
			return this.grid;
		}
		/**
		 * 바인딩 가능한 속성인지 확인합니다.
		 * @param name 확인할 속성.
		 */
		public isBindable(name: string): boolean {
			return this._bindables.isBindable(name);
		}

		/**
		 * 주어진 속성명에 대해 바인드 팩토리를 얻습니다.
		 * @param name 바인드 팩토리를 얻을 속성 명.
		 */
		public bind(name: string): bind.IBindFactory {
			return this._bindables.bind(name);
		}

		public unbind(name: string): void {
			this._bindables.unbind(name);
		}

		/**
		 * 바인드 속성 정보를 반환합니다.
		 * @param name bind된 속성 명.
		 * @return BindInfo 속성
		 */
		public getBindInfo(name: string): bind.BindInfo {
			let property = this._bindables.getBindableProperty(name);
			if (!property) {
				return null;
			}
			return property.getCurrentBindInfo();
		}

		/**
		 * 셀의 스타일 설정을 반환합니다.
		 * @return 셀의 스타일.
		 */
		get style(): GridStyler {
			return this._cellStyler;
		}

		/**
		 * 셀의 컨트롤을 설정합니다.
		 * @param control 셀에 배치할 컨트롤.
		 */
		set control(control: GridUIControl) {
			this._control = control;
		}

		/**
		 * 셀에 배치된 컨트롤을 반환합니다.
		 * @return 셀에 배치된 컨트롤.
		 */
		get control(): GridUIControl {
			return this._control;
		}

		/**
		 * 컨트롤 Constraints를 설정합니다.
		 * @param constraint 컨트롤 Constraints.
		 */
		set controlConstraint(constraint: ControlConstraint) {
			this._constraint = constraint;
		}

		/**
		 * 컨트롤 Constraints를 반환합니다.
		 * @return 컨트롤 Constraints.
		 */
		get controlConstraint(): ControlConstraint {
			return this._constraint;
		}

		// release-test-project#6872
		set tooltip(tooltip: string) {
			this._bindables.set("tooltip", tooltip);
		}

		// release-test-project#6872
		get tooltip(): string {
			return this._bindables.get("tooltip");
		}

		/**
		 * 엑셀 익스포트시 셀에 표현할 함수식을 설정합니다.<br/>
		 * 
		 * 지원 내장함수 : <br/>
		 * #C(number?) 설정된 셀인덱스 또는 현재 셀인덱스를 엑셀컬럼명으로 변환
		 * #R(number?) 설정된 행인덱스를 사용하거나 현재 행인덱스를 엑셀행인덱스로 변환
		 * @example
		 * SUM(#C(7)#R():#C(10)#R()) 
		 * 
		 * @param formula 셀에 표현할 함수식
		 */
		set formula(formula: string) {
			this._formula = formula;
		}

		/**
		 * 엑셀 익스포트시 셀에 표현할 함수식을 반환합니다.
		 * @return 셀에 표현할 함수식
		 */
		get formula(): string {
			return this._formula;
		}

		/**
		 * 셀의 논리적인 필드명을 설정합니다.<br>
		 * 셀에 배치된 컨트롤의 fieldLabel이 설정된 경우 컨트롤의 fieldLabel이 적용됩니다.
		 * @param 셀의 논리적인 필드명.
		 */
		set fieldLabel(fieldLabel: string) {
			this._bindables.set("fieldLabel", fieldLabel);
		}

		/**
		 * 셀의 논리적인 필드명을 반환합니다.
		 */
		get fieldLabel(): string {
			return this._bindables.get("fieldLabel");
		}

	}
}
