		/**
		 * 현재 row의 값을 설정합니다.
		 * @param rowData 설정할 row의 값.
		 * @param emitEvent 이벤트(before-update, update)를 발생시킬지 여부.
		 * @return 값 수정 성공 여부.
		 */
		public setRowData(rowData: data.RowConfigInfo, emitEvent: boolean = true): boolean {
			if (!rowData) {
				return false;
			}
			let rowState: data.tabledata.RowState = this.getState();
			if ((rowState & data.tabledata.RowState.DELETED) || (rowState & data.tabledata.RowState.INSERTDELETED)) {
				logger("error").log("[GridRow.setRowData] : DELETED상태이거나 INSERTDELETED상태인 row는 수정할 수 없습니다.");
				return false;
			}
			// 이전 값과 동일한 값으로 변경하고자 하는 경우 이벤트를 발생하지 않고 처리 중단. TODO DataSet or DataView를 통한 공통화
			let equals: boolean = true;
			let oldRowData: data.RowConfigInfo = this.getRowData(data.header.HeaderType.ORIGINAL_COLUMN);
			let colNames: string[] = Object.keys(rowData);
			for (let colIdx: number = 0; colIdx < colNames.length; colIdx++) {
				let key: string = colNames[colIdx];
				if (oldRowData.hasOwnProperty(key)) {
					let value: any = rowData[key];
					let oldValue: any = oldRowData[key];
					if (value instanceof foundation.DecimalType) {
						equals = value.equals(oldValue);
					} else {
						equals = (value === oldValue);
					}
					if (equals == false) {
						break;
					}

				}
			}
			if (equals) {
				return false;
			}

			if (emitEvent == true) {
				let preventDefault: boolean = this._grid.dispatchEvent(new events.CGridValueChangeEvent(events.GridEventType.BEFORE_UPDATE, {
					relativeTargetName: "detail",
					row: this,
					rowIndex: this.getIndex()
				}));
				if (!preventDefault) {
					return false;
				}
			}

			let result: boolean = this._row.setRowData(rowData);

			if (emitEvent == true) {
				this._grid.dispatchEvent(new events.CGridValueChangeEvent(events.GridEventType.UPDATE, {
					relativeTargetName: "detail",
					row: this,
					rowIndex: this.getIndex()
				}));
			}

			if (result == true) {
				this._grid.redraw();
			}
			return false;
		}

