		// TreeCell START ////////////////////////////////////////////////////////////////////

		/**
		 * 해당 행에 자식 행이 있는지 여부를 반환합니다.
		 * @return 자식 행이 있는지 여부.
		 */
		public isFolder(): boolean {
			if (this._isGrouping() == false) {
				return false;
			}
			let rowgroup: provider.GridRowGroup = this._getMatchedRowGroup();
			if (rowgroup != null) {
				let rows: (GridRow | GridRowGroup)[] = rowgroup._getRows();
				return (rows.length > 0) ? true : false;
			}
			return false;
		}

		/**
		 * @private
		 */
		private _isGrouping(): boolean {
			return this._grid.context._isGrouping();
		}

		/**
		 * @private
		 */
		private _getMatchedRowGroup(): provider.GridRowGroup {
			// TODO : 행그룹핑의 경우 virutalRows로 올바른 rowgroup을 반환받지 못함
			let rowIndex: number = this.getIndex();
			if (rowIndex < 0) {
				return null;
			}
			if (this._isGrouping() == false) {
				return null;
			}

			let virtualRows: provider.VirtualRow[] = this._grid.dataProvider._getVirtualRows();

			for (let startIdx: number = 0; startIdx < virtualRows.length; startIdx++) {
				let vRow: provider.VirtualRow = virtualRows[startIdx];
				if (vRow.dsindex > rowIndex) {
					return null;
				} else if (vRow.dsindex === rowIndex) {
					return vRow.pairgroup;
				}
			}
			return null;
		}

		/**
		 * @private
		 */
		public _setChecked(checked: boolean, isPropagate: boolean = true) {
			if (checked === true) {
				this._setCtrlAttr(GridCtrlAttribute.CHECKED, checked);
			} else {
				this._deleteCtrlAttr(GridCtrlAttribute.CHECKED);
			}

			if (isPropagate == true) {
				if (this._grid.context._isTreeGrid() == false && this.parent != null) {
					(this.parent as GridRowGroup)._resetGroupingChecked(true);
					this._grid.redraw();
				}
			}

		}

