/// <reference path="./AbstractItemListProvider.ts" />
namespace cpr.controls.item {

	/**
	 * @private
	 */
	export class ItemListProvider<ControlType extends UIControl, ItemType extends Item, ItemSetConfigType extends ItemSetConfig, FilterType extends ItemFilter>
		extends AbstractItemListProvider<ControlType, ItemType, ItemSetConfigType, FilterType>
		implements IItemListProvider<ItemType, ItemSetConfigType> {

		private _itemListView: ItemListView<ItemType, ItemList<ItemType, ItemSetConfigType>, FilterType>;

		constructor(owner: ControlType, itemAdapter: ItemListAdapter<ItemType>) {
			super(owner);
			let itemList = new ItemList<ItemType, ItemSetConfigType>(owner, this.getItemDataSource(), itemAdapter);
			this._itemListView = new ItemListView<ItemType, ItemList<ItemType, ItemSetConfigType>, FilterType>(owner, itemList, this._getItemFilter());
		}

		protected _createItemFilter(): FilterType {
			return new ItemFilter() as any;
		}

		/**
		 * 아이템 리스트 뷰를 반환합니다.
		 * @returns 아이템 리스트 뷰
		 */
		public getItemListView(): ItemListView<ItemType, ItemList<ItemType, ItemSetConfigType>, ItemFilter> {
			return this._itemListView;
		}

		/**
		 * 아이템 리스트를 반환합니다.
		 * @returns 아이템 리스트
		 */
		public getItemList(): ItemList<ItemType, ItemSetConfigType> {
			return this._itemListView.itemList;
		}

		/**
		 * 드롭다운타입에 따른 활성 아이템 리스트 뷰를 반환합니다.
		 * @returns 
		 */
		public getActiveItemListView(): IItemListView<ItemType> {
			return this._itemListView;
		}

		/**
		 * 드롭다운타입에 따른 활성 아이템 리스트를 반환합니다.
		 * @returns 
		 */
		public getActiveItemList(): IItemList<ItemType> {
			return this._itemListView.itemList;
		}
		/**
		 * 리소스를 해제합니다.
		 */
		public dispose(): void {
			this._itemListView?.dispose();
			this._itemListView = null;
			super.dispose();
		}
	}

}