///<reference path="./EnableUIControl.ts"/>

namespace cpr.controls {
	export abstract class AccessableUIControl extends EnableUIControl {
		private _accesskey: string = null;
		private _tabindex: number = 0;      /* HTML attribute= tabindex */ // Grid에서 접근하기 위해 protected로 변경


		constructor(id?: string) {
			super(id);
		}

		protected override _isConfigurableProperty(propName: string): boolean {
			if (propName == "accessKey" || propName == "tabIndex") {
				return true;
			}
			return super._isConfigurableProperty(propName);
		}

		/**
		 * 키보드 단축키 단일 문자(영문자 또는 숫자)를 설정합니다.<br>
		 * 단축키 실행은 윈도우은 [alt] + [단축키] 맥은 [option] + [단축키] 입니다.
		 * @param key 키보드의 단축키.
		 */
		set accessKey(key: string) {
			if (this._accesskey !== key) {
				this._accesskey = key;
				this.redraw();
			}
		}

		/**
		 * 키보드의 단축키 문자를 반환합니다.<br>
		 * @return 키보드의 단축키.
		 */
		get accessKey(): string {
			return this._accesskey;
		}

		/**
		 * Tab Key를 이용한 컨트롤 포커스 순서를 설정합니다.<br>
		 * HTML의 tabindex를 제어하기 위한 속성입니다.
		 * @param tabindex 컨트롤 포커스 순서.
		 */
		set tabIndex(tabindex: number) {
			if (typeof tabindex === "string") {
				tabindex = parseInt(tabindex);
			}
			let isAllowType = (typeof tabindex === "number" && !isNaN(tabindex)) || tabindex === null;
			if (!isAllowType) {
				return;
			}
			//AppInstance의 focusNext,focusPrevious에서 tabIndex의 타입이 number가 아니면 동작하지 않음.
			if (this._tabindex !== tabindex) {
				this._tabindex = tabindex;
				this.redraw();
			}
		}

		/**
		 * Tab Key를 이용한 컨트롤 포커스 순서를 반환합니다.<br>
		 * HTML의 tabindex를 제어하기 위한 속성입니다.
		 * @return 컨트롤 포커스 순서.
		 */
		get tabIndex(): number {
			return this._tabindex;
		}

		protected override _isFocusable(): boolean {
			return true;
		}

		/**
		 * accessKey를 통하여 포커스를 주는 동작 제어.
		 */
		public _focusByAccessKey() {
			this.focus();
		}

	}
}