namespace cpr.core {
	let instance: AutoDisposingQueue;

	/**
	 * @private
	 */
	export class AutoDisposingQueue {
		static get INSTANACE(): AutoDisposingQueue {
			if (!instance) {
				instance = new AutoDisposingQueue();
			}
			return instance;
		}

		private _scheduled = false;
		private _queue: controls.Control[] = [];

		/**
		 * 자동 디스포즈할 객체를 추가합니다.
		 * @param resource 자동 디스포즈할 객체.
		 */
		_scheduleDispose(resource: controls.Control) {
			if (!resource || resource.disposed) {
				return;
			}

			if (this._queue.indexOf(resource) !== -1) {
				return;
			}

			this._queue.push(resource);
			this._updateTimer();
		}

		/**
		 * 자동 디스포즈를 취소합니다.
		 * @param resource 파기를 취소할 리소스 객체.
		 */
		_cancelDispose(resource: controls.Control) {
			let index = this._queue.indexOf(resource);

			if (index === -1) {
				return;
			}

			this._queue.splice(index, 1);

			this._updateTimer();
		}

		private _updateTimer() {
			let needsSchedule = this._queue.length > 0;

			if (needsSchedule && !this._scheduled) {
				DeferredUpdateManager.INSTANCE._asyncExecBefore(this._doDispose.bind(this));
				this._scheduled = true;
			}

		}

		private _doDispose() {
			this._scheduled = false;

			_stream(this._queue)
				.filter(it => !it.disposed && it.getAppInstance() == null)
				.forEach(it => {
					it.dispose();
				});

			this._queue = [];
		}
	}
}