namespace cpr.controls.item {

	/**
	 * @private
	 */
	export class SelectionCore<ItemType extends Item> {

		private _itemListProvider: BaseItemListProvider<ItemType, ItemSetConfig>;
		private _selection: ItemType[] = [];
		private _itemExpressionEvaluator: ItemExpressionEvaluator;
		private _binder: provider.MultiValueBinder;
		private _filterCache: string = "";
		private _disposed: boolean = false;

		constructor(binder: provider.MultiValueBinder, itemListProvider: BaseItemListProvider<ItemType, ItemSetConfig>, itemExpressionEvaluator: ItemExpressionEvaluator) {
			this._itemListProvider = itemListProvider;
			this._itemExpressionEvaluator = itemExpressionEvaluator;
			this._binder = binder;
		}

		public _isMultiple(): boolean {
			if (this._isDisposed()) {
				return false;
			}
			return this._binder.getMultiple();
		}

		public _getDelimiter(): string {
			if (this._isDisposed()) {
				return ",";
			}
			return this._binder.getDelimiter();
		}
		public _getValue(): string {
			if (this._isDisposed()) {
				return null;
			}
			return this._binder.getValue();
		}
		public _getValues(): string[] {
			if (this._isDisposed()) {
				return [];
			}
			return this._binder.getValues();
		}
		public _setValue(value: string): void {
			if (this._isDisposed()) {
				return;
			}
			this._binder.setValue(value);
		}
		public _setValues(values: string[]): void {
			if (this._isDisposed()) {
				return;
			}
			this._binder.setValues(values);
		}

		/**
		 * 아이템 리스트 뷰를 반환합니다.
		 * @returns 아이템 리스트 뷰
		 */
		private _getItemListView() {
			if (this._isDisposed()) {
				return null;
			}
			return this._itemListProvider.getActiveItemListView();
		}

		private _dispatchEvent(event: cpr.events.CEvent): boolean {
			if (this._isDisposed()) {
				return true;
			}
			return this._binder.getOwner().dispatchEvent(event);
		}

		private _isDisposed(): boolean {
			return this._disposed;
		}

		private _isGridChild(): boolean {
			if (this._isDisposed()) {
				return false;
			}
			return this._binder.getOwner().getParent() instanceof cpr.controls.Grid;
		}
		/**
		 * 컨트롤을 다시 그립니다.
		 */
		private _redraw(): void {
			if (this._isDisposed()) {
				return;
			}
			this._binder.getOwner().redraw();
		}

		/**
		 * 해당되는 아이템을 선택합니다.<br>
		 * 선택된 아이템의 value는 컨트롤의 value로 지정됩니다.<br>
		 * 존재하지 않는 아이템인 경우 아이템 선택이 안 되고 해당 value가 지정되지 않습니다.<br>
		 * newSelection,oldSelection이 item[]를 반환합니다.
		 * @param item 선택하고자 하는 아이템.
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 */
		public select(item: ItemType, emitEvent: boolean = true): void {
			if (item == null) {
				return;
			}
			this._select(item, this._isMultiple(), emitEvent);
			this._redraw();
		}

		/**
		 * 해당되는 아이템을 선택합니다.<br>
		 * 선택된 아이템의 value는 컨트롤의 value로 지정됩니다.<br>
		 * 존재하지 않는 아이템인 경우 아이템 선택이 안 되고 해당 value가 지정되지 않습니다.
		 * @param obj 선택하고자 하는 아이템.
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 */
		public selectSingleItem(item: ItemType, emitEvent: boolean = true): void {
			if (item == null) {
				return;
			}
			this._selectSingle(item, emitEvent);
			this._redraw();
		}

		/**
		 * 아이템을 선택합니다.
		 * 이전의 선택된 아이템을 선택 해제한 뒤 해당하는 인덱스의 아이템들을 선택합니다.
		 * @param items 선택할 아이템 배열
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 */
		public selectItems(items: ItemType[], emitEvent: boolean = true): void {
			if (_isArray(items) == false) {
				return;
			}
			let oldSelection: ItemType[] = this.getSelection();
			let newSelection: ItemType[] = items;

			if (emitEvent !== false) {
				let selectionEvent = new cpr.events.CSelectionEvent(events.SelectionEventType.BEFORECHANGE
					, { oldSelection: oldSelection, newSelection: newSelection });

				let preventDefault = this._dispatchEvent(selectionEvent);
				if (!preventDefault) {
					return;
				}
			}

			this.setSelection(newSelection);

			if (emitEvent !== false) {
				let selectionEvent = new cpr.events.CSelectionEvent(events.SelectionEventType.CHANGE, {
					oldSelection: oldSelection,
					newSelection: this.getSelection()
				});

				this._dispatchEvent(selectionEvent);
			}
		}

		/**
		 * multiple 일 경우 선택이 계속 쌓인다. 아닌경우 선택을 지우고 선택한다.
		 * 링크드리스트박스, 링크드콤보박스에서 forceSelect 옵션을 사용한다.
		 * @private
		 * @nonapi
		 * @param item 
		 * @param multiple
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 */
		public _select(item: ItemType, multiple: boolean = false, emitEvent: boolean = true, forceSelect: boolean = false): boolean {
			let oldSelection: ItemType[] = this.getSelection();
			let newSelection: ItemType[] = [];

			let isSelectedItem = this.isSelected(item);

			if (multiple && !isSelectedItem) {
				newSelection = oldSelection.concat();
			}
			newSelection.push(item);

			let eventNewSelection = newSelection.concat();
			// 2026-01-09 TODO 이 이벤트에서만 newSelection에서 정렬을 사용하고 있어 개선 필요.
			// getSelection()시 index 순서로 item 나열.
			eventNewSelection.sort((a: ItemType, b: ItemType) => {
				return this._getItemListView().getIndex(a) > this._getItemListView().getIndex(b) ? 1 : -1;
			});

			let hasCleanSelect = multiple == false && oldSelection.length > 1;
			if (forceSelect == false) {
				//선택 유무 확인
				if (isSelectedItem && !hasCleanSelect) {
					return true;
				}
			}

			if (emitEvent !== false) {
				//before-selection event
				let selectionEvent = new cpr.events.CSelectionEvent(events.SelectionEventType.BEFORECHANGE
					, { oldSelection: oldSelection.slice(), newSelection: eventNewSelection });

				let preventDefault = this._dispatchEvent(selectionEvent);
				if (!preventDefault) {
					this._redraw();
					return false;
				}
			}

			//select
			this.setSelection(newSelection);

			if (this._isDisposed()) {
				return;
			}

			if (emitEvent !== false) {
				//selection event
				let selectionEvent = new cpr.events.CSelectionEvent(events.SelectionEventType.CHANGE, {
					oldSelection: oldSelection.slice(),
					newSelection: this.getSelection()
				});

				this._dispatchEvent(selectionEvent);
			}
			return true;
		}

		/**
		 * multiple 일 경우 선택이 계속 쌓인다. 아닌경우 선택을 지우고 선택한다.
		 * @private
		 * @nonapi
		 * @param item 
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 */
		private _selectSingle(item: ItemType, emitEvent: boolean = true, callback?: (items?: ItemType[]) => void): boolean {
			let oldSelection: ItemType = this.getSelectionFirst();
			let newSelection: ItemType = item;

			let isSelectedItem = this.isSelected(item);
			if (isSelectedItem) {
				return false;
			}

			if (emitEvent !== false) {
				//before-selection event
				let selectionEvent = new cpr.events.CSelectionEvent(events.SelectionEventType.BEFORECHANGE
					, { oldSelection: oldSelection, newSelection: newSelection });

				let preventDefault = this._dispatchEvent(selectionEvent);
				if (!preventDefault) {
					if (callback) {
						callback();
					}
					return false;
				}
			}

			this.setSelection([newSelection]);

			if (emitEvent !== false) {
				//selection event
				let selectionEvent = new cpr.events.CSelectionEvent(events.SelectionEventType.CHANGE, {
					oldSelection: oldSelection,
					newSelection: newSelection
				});

				if (callback) {
					callback();
				}
				this._dispatchEvent(selectionEvent);
			}
			return true;
		}

		/**
		 * 선택된 아이템들을 반환합니다.
		 * @return 선택된 아이템의 배열.
		 */
		public getSelection(): ItemType[] {
			let values = this._getValues();
			if (values.length === 0) {
				return [];
			}
			if (!this._checkSelectionCacheValidity()) {
				this.invalidateSelection();
			}
			let selectionValueText = this._selection.length === 0 ? null : this._selection.map((each) => each.value).join(this._getDelimiter());
			let valueText = values.join(this._getDelimiter());
			if (selectionValueText == valueText) {
				return this._selection;
			}
			//1. 아이템의 순서대로 values에 맞는 아이템을 찾아 배열을 반환한다. values의 순서와 다르게 반환됨.
			let selection = this._getItemListView().findItemByValues(values);
			let map = _createMap<any, any>();
			_stream(selection).forEach((each) => {
				if (each == null) {
					return;
				}
				if (map.has(each.value)) {
					// 중복 value 허용시 배열로 관리
					let items = [].push(map.get(each.value), each);
					map.set(each.value, items);
				} else {
					map.set(each.value, each);
				}
			});

			// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/10482
			// map에 비해 탐색 성능이 떨어지지만 중복 value 허용시 문제가 발생하여 수정.
			// let result = _stream(filteredItems).filter((each) => {
			// 	let idx = values.indexOf(each.value);
			// 	if (idx > -1) {
			// 		values.splice(idx, 1);
			// 		return true;
			// 	}
			// 	return false;
			// }).collect();

			//2. values 순서대로 정렬하여 result에 넣는다.
			let result: ItemType[] = [];
			values.forEach((eachValue) => {
				let item = map.get(eachValue) as ItemType | ItemType[];
				if (_isArray(item)) {
					// 중복 value인 경우 배열에서 하나씩 꺼내서 result에 넣는다.
					let removedItem = item.splice(0, 1)[0];
					if (removedItem) {
						result.push(removedItem);
					}
				} else if (item) {
					result.push(item);
				}
			});

			this._selection = result;
			this._filterCache = this._getItemListView().filter;
			return result;
		}

		/**
		 * 
		 * @param items 
		 */
		public setSelection(items: ItemType[]): void {
			let values: string[] = [];
			_stream(items).forEach((each: ItemType) => {
				values.push(each.value);
			});

			this._selection = items;
			this._filterCache = this._getItemListView().filter;
			this._setValues(values); // value-change에서 dispose 될 수 있어 마지막에 처리
		}

		public appendSelection(items: ItemType[]): void {
			let selection = this.getSelection();
			let selectionMap = _createItemMap<ItemType>(selection);
			let appendSelection: ItemType[] = [];
			let values: string[] = [];
			items.forEach((each: ItemType) => {
				if (!selectionMap.has(each._getUUID())) {
					appendSelection.push(each);
					values.push(each.value);
				}
			});
			if (appendSelection.length === 0) {
				return;
			}
			this._selection = selection.concat(appendSelection);
			this._filterCache = this._getItemListView().filter;
			this._setValues(this._getValues().concat(values)); // value-change에서 dispose 될 수 있어 마지막에 처리
		}

		private _checkSelectionCacheValidity(): boolean {
			if (this._isDisposed() || this._isGridChild()) {
				return false;
			}
			return this._filterCache == this._getItemListView().filter;
		}

		/**
		 * 선택 상태를 무효화합니다.
		 * 아이템 타입이 변경되는 경우 invalidateSelection를 호출하여 선택 상태를 무효화 해야 합니다.
		 */
		public invalidateSelection(): void {
			this._selection = [];
		}

		/**
		 * 선택된 리스트 데이터 배열 중 첫번째 데이터를 반환합니다.
		 * @return 첫번째 선택된 데이터.
		 */
		public getSelectionFirst(): ItemType {
			let selection = this.getSelection();
			if (selection.length === 0) {
				return null;
			}
			return selection[0];
		}

		/**
		 * 선택된 리스트 데이터 배열 중 마지막 데이터를 반환합니다.
		 * @return 마지막으로 선택된 데이터.
		 */
		public getSelectionLast(): ItemType {
			let selection = this.getSelection();
			if (selection.length === 0) {
				return null;
			}
			return selection[selection.length - 1];
		}

		/**
		 * 해당되는 아이템의 선택 여부를 반환합니다.
		 * @param obj 아이템
		 * @return 해당 아이템의 선택 여부.
		 */
		public isSelected(item: ItemType): boolean {
			let selection = this.getSelection();
			let findItem = _stream(selection).find((each) => {
				return each._equalsUUID(item);
			});
			return findItem != null;
		}

		/**
		 * value에 해당되는 아이템의 선택 여부를 반환합니다.
		 * @param value 아이템의 value.
		 * @return 해당 아이템의 선택 여부.
		 */
		public isSelectedByValue(value: string): boolean {
			if (this._isMultiple()) {
				return this._getValues().indexOf(value) !== -1;
			} else {
				return this._getValue() == value;
			}
		}

		/**
		 * 해당되는 아이템이 선택되었을 경우 그 아이템을 선택 해제합니다.<br>
		 * newSelection,oldSelection이 item[]를 반환합니다.
		 * @param item 아이템
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 */
		public removeSelection(item: ItemType, emitEvent: boolean = true): boolean {
			if (!item) {
				return false;
			}
			let result = this._removeSelection(item, emitEvent);
			if (result) {
				this._redraw();
			}
			return result;
		}

		/**
		 * 해당되는 아이템이 선택되었을 경우 그 아이템을 선택 해제합니다.
		 * @param item 아이템
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 */
		public removeSingleSelection(item: ItemType, emitEvent: boolean = true): void {
			if (!item) {
				return;
			}
			this._removeSingleSelection(item, emitEvent);
			this._redraw();
		}

		/**
		 * value에 해당되는 아이템이 선택되었을 경우 그 아이템을 선택 해제합니다.<br>
		 * newSelection,oldSelection이 item[]를 반환합니다.
		 * @param value 아이템의 value.
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 */
		public removeSelectionByValue(targetValue: string, emitEvent: boolean = true): void {
			let oldSelection: ItemType[] = this.getSelection();
			let newSelection: ItemType[] = oldSelection.concat();

			if (!this.isSelectedByValue(targetValue)) {
				return;
			}

			if (this._isMultiple()) {
				let index = _.findIndex(oldSelection, { value: targetValue });
				if (oldSelection.length > 0 && index != -1) {
					newSelection.splice(index, 1);
				} else {
					return;
				}
			} else {
				newSelection = [];
			}

			if (emitEvent !== false) {
				//before-selection event
				let selectionEvent = new cpr.events.CSelectionEvent(events.SelectionEventType.BEFORECHANGE
					, { oldSelection: oldSelection, newSelection: newSelection });
				let isContinue = this._dispatchEvent(selectionEvent);
				if (!isContinue) {
					return;
				}
			}

			this.setSelection(newSelection);

			if (this._isDisposed()) {
				return;
			}

			if (emitEvent !== false) {
				//selection event
				let selectionEvent = new cpr.events.CSelectionEvent(events.SelectionEventType.CHANGE, {
					oldSelection: oldSelection, newSelection: this.getSelection() // 이벤트를 통해 사용자가 selection을 변경할 수 있기 때문에 getSelection()을 해야한다.
				});
				this._dispatchEvent(selectionEvent);
			}
			this._redraw();
		}

		/**
		 * value에 해당되는 아이템이 선택되었을 경우 그 아이템을 선택 해제합니다.
		 * @param value 아이템의 value.
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 */
		public removeSingleSelectionByValue(value: string, emitEvent: boolean = true): void {
			let oldSelection: ItemType = this.getSelectionFirst();
			let newSelection: ItemType = oldSelection;

			if (!this.isSelectedByValue(value)) {
				return;
			}

			if (emitEvent !== false) {
				//before-selection event
				let selectionEvent = new cpr.events.CSelectionEvent(events.SelectionEventType.BEFORECHANGE
					, { oldSelection: oldSelection, newSelection: newSelection });

				let preventDefault = this._dispatchEvent(selectionEvent);
				if (!preventDefault) {
					return;
				}
			}

			//remove selection
			this.removeSelectionInternalByValue(value);

			if (emitEvent !== false) {
				//selection event
				let selectionEvent = new cpr.events.CSelectionEvent(events.SelectionEventType.CHANGE, {
					oldSelection: oldSelection, newSelection: this.getSelectionFirst()
				});

				this._dispatchEvent(selectionEvent);
			}
			this._redraw();
		}

		/**
		 * deleteSelection
		 * @param items 
		 */
		public removeSelectionInternal(items: ItemType[]): void {
			let selection = this.getSelection();
			let newSelection = _subtractItems<ItemType>(selection, items);
			this.setSelection(newSelection);
		}

		/**
		 * value에 해당하는 리스트 데이터를 선택 해제합니다.
		 * deleteSelectionByValue
		 * @param value 선택 해제하고자 하는 리스트 데이터의 value
		 */
		public removeSelectionInternalByValue(value: string): void {
			let selection = this.getSelection();
			let newSelection = _stream(selection).filter((each) => {
				return each.value !== value;
			}).collect();
			this.setSelection(newSelection);
		}

		/*
		 * removeSelection, deleteItemByValue에서만 사용
		 */
		private _removeSelection(item: ItemType, emitEvent: boolean = true): boolean {
			let oldSelection: ItemType[] = this.getSelection();
			let newSelection: ItemType[] = oldSelection.concat();

			if (!this.isSelected(item)) {
				return true;
			}

			if (this._isMultiple()) {
				newSelection = _subtractItems<ItemType>(newSelection, [item]);
				if (newSelection.length === oldSelection.length) {
					return true;
				}
			} else {
				newSelection = [];
			}

			if (emitEvent !== false) {
				//before-selection event
				let selectionEvent = new cpr.events.CSelectionEvent(events.SelectionEventType.BEFORECHANGE
					, { oldSelection: oldSelection.slice(), newSelection: newSelection.slice() });
				let isContinue = this._dispatchEvent(selectionEvent);
				if (!isContinue) {
					return false;
				}
			}

			this.setSelection(newSelection);

			if (this._isDisposed()) {
				return;
			}

			if (emitEvent !== false) {
				//selection event
				let selectionEvent = new cpr.events.CSelectionEvent(events.SelectionEventType.CHANGE, {
					oldSelection: oldSelection.slice(), newSelection: this.getSelection() // 이벤트를 통해 사용자가 selection을 변경할 수 있기 때문에 getSelection()을 해야한다.
				});
				this._dispatchEvent(selectionEvent);
			}
			return true;
		}

		public _removeSingleSelection(item: ItemType, emitEvent: boolean = true): boolean {
			let oldSelection: ItemType = this.getSelectionFirst();
			let newSelection: ItemType = oldSelection;

			if (!this.isSelectedByValue(item.value)) {
				return true;
			}

			if (emitEvent !== false) {
				//before-selection event
				let selectionEvent = new cpr.events.CSelectionEvent(events.SelectionEventType.BEFORECHANGE
					, { oldSelection: oldSelection, newSelection: newSelection });

				let preventDefault = this._dispatchEvent(selectionEvent);
				if (!preventDefault) {
					return false;
				}
			}

			//remove selection
			this.removeSelectionInternal([item]);

			if (emitEvent !== false) {
				//selection event
				let selectionEvent = new cpr.events.CSelectionEvent(events.SelectionEventType.CHANGE, {
					oldSelection: oldSelection, newSelection: this.getSelectionFirst()
				});

				this._dispatchEvent(selectionEvent);
			}
			return true;
		}

		/**
		 * 선택된 아이템을 모두 선택 해제합니다.
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 */
		public clearSelection(emitEvent: boolean = true): void {
			let oldSelection = this.getSelection();
			if (oldSelection.length == 0) {
				return;
			}

			if (emitEvent !== false) {
				//before-selection event
				let preventDefault = this._dispatchEvent(new cpr.events.CSelectionEvent(events.SelectionEventType.BEFORECHANGE
					, { oldSelection: oldSelection, newSelection: [] }));
				if (!preventDefault) {
					return;
				}
			}

			this.setSelection([]);

			if (emitEvent !== false) {
				//selection-event
				this._dispatchEvent(new cpr.events.CSelectionEvent(events.SelectionEventType.CHANGE, {
					oldSelection: oldSelection, newSelection: this.getSelection()
				}));
			}
			this._redraw();
		}

		public clearSingleSelection(emitEvent: boolean = true): void {
			let oldSelection = this.getSelectionFirst();
			if (oldSelection == null) {
				return;
			}

			if (emitEvent !== false) {
				//before-selection event
				let preventDefault = this._dispatchEvent(new cpr.events.CSelectionEvent(events.SelectionEventType.BEFORECHANGE
					, { oldSelection: oldSelection, newSelection: null }));
				if (!preventDefault) {
					return;
				}
			}

			//clear selection
			this.setSelection([]);

			if (emitEvent !== false) {
				//selection-event
				this._dispatchEvent(new cpr.events.CSelectionEvent(events.SelectionEventType.CHANGE, {
					oldSelection: oldSelection, newSelection: this.getSelectionFirst()
				}));
			}
			this._redraw();
		}

		/**
		 * 선택된 아이템의 화면에 보여지는 텍스트를 반환합니다.
		 * 다중 선택인 경우 선택된 아이템들의 레이블을 델리미터로 조인한 형태의 텍스트를 얻음.
		 * @return 화면에 보여지는 텍스트.
		 */
		public getText(): string {
			if (this._isDisposed()) {
				return "";
			}
			let selection: ItemType[] = this.getSelection();
			let result: string[] = [];
			for (let item of selection) {
				result.push(ufc.StyledString._asString(this._itemExpressionEvaluator.evaluateDisplayLabel(item)));
			}
			let text: string = result.join(this._getDelimiter());
			return text;
		}

		/**
		 * 선택된 아이템의 데이터셋 인덱스를 가져옵니다. 데이터셋의 아이템이 아닌경우 -1을 반환합니다.
		 */
		public getSelectedDataSetIndices(): number[] {
			let result = [];
			this.getSelection().forEach((each) => {
				if (each.row) {
					result.push(each.row.getIndex());
				} else {
					result.push(-1);
				}
			});
			return result;
		}

		/**
		 * 선택된 리스트 데이터의 개수를 반환합니다.
		 * @return 선택된 리스트 데이터의 개수.
		 */
		public size(): number {
			return this.getSelection().length;
		}

		/**
		 * 선택된 리스트 데이터 중 조건에 맞는 리스트 데이터를 찾습니다.
		 * @param name 리스트 데이터의 key 명
		 * @param expectedValue 리스트 데이터의 value.
		 * @return 조건에 맞는 리스트 데이터 목록.
		 */
		public findSelection(name: string, expectedValue: any): Item[] {
			return this.getSelection().filter((it: Item) => {
				return it[name] == expectedValue;
			})
		}

		/**
		 * 컨트롤에 포함되어있는 객체들을 제거합니다.
		 */
		public dispose(): void {
			this._itemListProvider = null;
			this._selection = [];
			this._itemExpressionEvaluator = null;
			this._binder = null;
			this._disposed = true;
		}

	}
}