namespace cpr.controls.item {

	/**
	 * @private
	 */
	export interface IControlItemValidator<ItemType> {
		validateItem(item: ItemType, info: ValidationContext, itemMap?: provider.ItemMap<ItemType>): void;
		validateItems(items: ItemType[], info: ValidationContext): void;
	}

	type ValidationContext = {
		ownerId: string,
		ownerType: string,
		multiple: boolean,
		delimiter: string
	}

	type ItemErrorInfo = {
		id: string,
		type: string,
		value: string,
		parentValue?: string,
		message: string
	}

	/**
	 * @private
	 */
	export enum ControlItemValidatorType {
		item,
		treeItem,
		comboBoxItem
	}

	/**
	 * 에러 메시지 상수
	 */
	const ERROR_MESSAGES = {
		DELIMITER_USED: "Delimiter is used.",
		DUPLICATE_VALUE: "The value of the item is duplicated.",
		SAME_VALUE_AND_PARENT: "value and parentValue are the same.",
		CROSS_REFERENCE: "cross reference.",
		NULL_VALUE: "The value of the item is null."
	} as const;

	/**
	 * @private
	 * 공통 검증 로직을 포함하는 베이스 클래스
	 */
	abstract class BaseItemValidator<ItemType extends Item> implements IControlItemValidator<ItemType> {
		protected _error: cpr.exceptions.CError;

		public abstract validateItem(item: ItemType, info: ValidationContext, itemMap?: provider.ItemMap<ItemType>): void;
		public abstract validateItems(items: ItemType[], info: ValidationContext): void;

		/**
		 * 아이템의 value에 delimiter가 포함된 경우 오류 메시지를 출력합니다.
		 * @param item 
		 * @param info 
		 */
		protected _checkDelimiterValue(item: Item, info: ValidationContext): void {
			let value = item.value ?? "";
			if (value.split(info.delimiter).length > 1) {
				this._throwException(this._createError(ERROR_MESSAGES.DELIMITER_USED, item, info));
			}
		}

		/**
		 * 아이템의 값이 null인지 확인합니다. null인 경우 경고 메시지를 출력합니다.
		 * @param item 
		 * @param info 
		 */
		protected _checkNullValue(item: Item, info: ValidationContext): void {
			if (item.value === null) {
				this._warning(this._createError(ERROR_MESSAGES.NULL_VALUE, item, info));
			}
		}

		protected _throwException(error: ItemErrorInfo): void {
			let parentValuePart = error.parentValue !== undefined ? `, parentValue: ${error.parentValue}` : '';
			let content = `controltype: ${error.type}, id: ${error.id}, value: ${error.value}${parentValuePart}`;
			let message = `${error.message}: [${content}]`;
			this._error = new cpr.exceptions.CError(message);
			throw this._error;
		}

		protected _warning(error: ItemErrorInfo): void {
			let parentValuePart = error.parentValue !== undefined ? `, parentValue: ${error.parentValue}` : '';
			let content = `controltype: ${error.type}, id: ${error.id}, value: ${error.value}${parentValuePart}`;
			let message = `${error.message}: [${content}]`;
			console.warn(message);
		}

		protected _createError(message: string, item: Item, info: ValidationContext, parentValue?: string): ItemErrorInfo {
			return {
				message: message,
				id: info.ownerId,
				type: info.ownerType,
				value: item.value,
				parentValue: parentValue
			};
		}

		protected _hasError(): boolean {
			return !!this._error;
		}
	}

	/**
	 * @private
	 */
	export class ControlItemValidator<ItemType extends Item> extends BaseItemValidator<ItemType> {
		private _map: provider.ItemMap<ItemType>;

		public validateItem(item: ItemType, info: ValidationContext, itemMap?: provider.ItemMap<ItemType>): void {
			if (this._hasError()) {
				return;
			}

			if (core.PolicyManager.INSTANCE._isConfigured(core.Policy.DATA_DEFAULT_VALUE_IS_NULL)) {
				this._checkNullValue(item, info);
			}

			let targetMap = itemMap ?? this._map;
			this._checkDuplicateValue(item, info, targetMap);

			if (info.multiple) {
				this._checkDelimiterValue(item, info);
			}

			if (this._map && !itemMap) {
				this._map.set(item.value, item);
			}
		}

		public validateItems(items: ItemType[], info: ValidationContext): void {
			this._map = new provider.ItemMap<ItemType>();
			_stream(items).forEach((item) => {
				this.validateItem(item, info);
			});
		}

		/**
		 * 아이템의 값이 중복되는지 확인합니다. 중복되는 경우 오류 메시지를 출력합니다.
		 * @param item 
		 * @param info 
		 * @param itemMap 
		 */
		protected _checkDuplicateValue(item: ItemType, info: ValidationContext, itemMap: provider.ItemMap<ItemType>): void {
			let existingItem = itemMap.get(item.value);
			if (existingItem) {
				this._throwException(this._createError(ERROR_MESSAGES.DUPLICATE_VALUE, item, info));
			}
		}
	}

	/**
	 * @private
	 */
	export class ComboBoxItemValidator<ItemType extends TreeItem> extends BaseItemValidator<ItemType> {

		public validateItem(item: ItemType, info: ValidationContext, itemMap?: provider.ItemMap<ItemType>): void {
			if (this._hasError()) {
				return;
			}

			if (core.PolicyManager.INSTANCE._isConfigured(core.Policy.DATA_DEFAULT_VALUE_IS_NULL)) {
				this._checkNullValue(item, info);
			}

			if (info.multiple) {
				this._checkDelimiterValue(item, info);
			}
		}

		public validateItems(items: ItemType[], info: ValidationContext): void {
			_stream(items).forEach((item) => {
				this.validateItem(item, info);
			});
		}
	}

	/**
	 * @private
	 */
	export class ControlTreeItemValidator<ItemType extends TreeItem> extends BaseItemValidator<ItemType> {
		private _map: provider.ItemMap<ItemType>;

		public validateItem(item: ItemType, info: ValidationContext, itemMap?: provider.ItemMap<ItemType>): void {
			if (this._hasError()) {
				return;
			}

			if (core.PolicyManager.INSTANCE._isConfigured(core.Policy.DATA_DEFAULT_VALUE_IS_NULL)) {
				this._checkNullValue(item, info);
			}

			let targetMap = itemMap ?? this._map;
			this._checkDuplicateValue(item, info, targetMap);

			if (info.multiple) {
				this._checkDelimiterValue(item, info);
			}

			this._checkParentValue(item, info);
			this._checkCrossReference(item, info, targetMap);

			if (this._map && !itemMap) {
				this._map.set(item.value, item);
			}
		}

		public validateItems(items: ItemType[], info: ValidationContext): void {
			this._map = new provider.ItemMap<ItemType>();
			_stream(items).forEach((item) => {
				this.validateItem(item, info);
			});
		}

		/**
		 * 아이템의 값이 중복되는지 확인합니다. 중복되는 경우 오류 메시지를 출력합니다.
		 * @param item 
		 * @param info 
		 * @param itemMap 
		 */
		private _checkDuplicateValue(item: ItemType, info: ValidationContext, itemMap: provider.ItemMap<ItemType>): void {
			let existingItem = itemMap.get(item.value);
			if (existingItem) {
				this._throwException(this._createError(ERROR_MESSAGES.DUPLICATE_VALUE, item, info, item.parentValue));
			}
		}

		/**
		 * 아이템의 값이 부모값과 동일한지 확인합니다. 동일한 경우 오류 메시지를 출력합니다.
		 * @param item 
		 * @param info 
		 */
		private _checkParentValue(item: ItemType, info: ValidationContext): void {
			if (item.value == item.parentValue) {
				this._throwException(this._createError(ERROR_MESSAGES.SAME_VALUE_AND_PARENT, item, info, item.parentValue));
			}
		}

		/**
		 * 아이템이 부모 아이템과 서로 참조하는지 확인합니다. 참조하는 경우 오류 메시지를 출력합니다.
		 * @param item 
		 * @param info 
		 * @param itemMap 
		 */
		private _checkCrossReference(item: ItemType, info: ValidationContext, itemMap: provider.ItemMap<ItemType>): void {
			let parentItem = itemMap.get(item.parentValue);
			if (parentItem && parentItem.value == item.parentValue && parentItem.parentValue == item.value) {
				this._throwException(this._createError(ERROR_MESSAGES.CROSS_REFERENCE, item, info, item.parentValue));
			}
		}
	}
}
