/// <reference path="./JSONRequestBuilder.ts"/>
/// <reference path="../../utils/JSONBlob.ts"/>


namespace cpr.protocols.request {

	export class JSONMassRequestBuilder extends JSONRequestBuilder {
		private static _jsonBlob: utils.JSONBlob = new utils.JSONBlob();
		private static _encoder: (data: string) => string = (data: string) => data;


		protected static _assembleEncodedResultBlob(encodingResult: EncodingResult): Blob {
			let key: string = encodingResult.key;
			let value: {} | string = encodingResult.content;
			let res: Blob = null;
			if (value == null || value == "" || typeof value == "string") {
				value = (value == null || value == "" ? "" : value);
				if (key) {
					let jobj: {} = {};
					jobj[key] = value;
					res = JSONMassRequestBuilder._jsonBlob.toBlob(jobj, JSONMassRequestBuilder._encoder, { decimalFormat: "number" });
					jobj = null;
				} else {
					res = JSONMassRequestBuilder._jsonBlob.toBlob(value, JSONMassRequestBuilder._encoder, { decimalFormat: "number" });
				}
			} else if (typeof value == "object") {
				res = JSONMassRequestBuilder._jsonBlob.toBlob(value, JSONMassRequestBuilder._encoder, { decimalFormat: "number" });
			}
			key = null;
			value = null;
			encodingResult = null;

			return res;
		}


		constructor() {
			super();
		}

		public getContentType(): string {
			return Submission.MEDIA_JSON_MASS;
		}

		protected _buildSpecific(submission: Submission): any {
			if (Submission._HASBODY_METHOD.indexOf(submission.method) === -1) {
				console.warn("Submission(\"" + submission.id + "\") method has been changed to POST. \"" + Submission.MEDIA_JSON + "\" media types can not use " + submission.method.toUpperCase() + " method. Available methods [" + Submission._HASBODY_METHOD.join(",").toUpperCase() + "]");
				submission.method = Submission.METHOD_POST;
			}

			// json request object
			let jsonobject: JSONRequestObject = null;
			let requestEncoderSpec: RequestEncoderSpec = submission._getRequestEncoder();

			if (requestEncoderSpec && requestEncoderSpec.encoder) {
				if (requestEncoderSpec.usingBuildData) {
					jsonobject = this._buildJsonRequestObject(submission);
				}

				let returnValue: Promise<EncodingResult> | EncodingResult = requestEncoderSpec.encoder(submission, jsonobject);
				if (returnValue instanceof Promise) {
					return returnValue.then((encodingResult: EncodingResult) => {
						let res: Blob = JSONMassRequestBuilder._assembleEncodedResultBlob(encodingResult);
						if (encodingResult.contentType) {
							submission._setInstantContentType(encodingResult.contentType);
						}

						encodingResult = null;
						jsonobject = null;
						return res;
					});
				} else {
					let res: Blob = JSONMassRequestBuilder._assembleEncodedResultBlob(returnValue);
					if (returnValue.contentType) {
						submission._setInstantContentType(returnValue.contentType);
					}

					returnValue = null;
					jsonobject = null;
					return res;
				}
			} else {
				jsonobject = this._buildJsonRequestObject(submission);
				let reqBlob: Blob = JSONMassRequestBuilder._jsonBlob.toBlob(jsonobject, JSONMassRequestBuilder._encoder, { decimalFormat: "number" });
				jsonobject = null;

				return reqBlob;
			}
		}

	}

}