/// <reference path="../ufc/ShapeEventAttacher.ts"/>
/// <reference path="../ufc/DOMTraverser.ts"/>


namespace cpr.events {
	let instance: EventBus = null;

	/**
	 * @noinstance
	 */
	export class EventBus {
		/**
		 * 이벤트 버스 싱글톤 인스턴스를 얻습니다.
		 */
		static get INSTANCE(): EventBus {
			if (instance == null) {
				instance = new EventBus();

				// Global Event Handler 생성
				let bodyEventTarget: BodyEventTarget = BodyEventTarget.INSTANCE;
				// window-scroll event를 RootApp의 컨테이너에 연결
				bodyEventTarget.addEventListener("scroll", instance._doWindowScroll.bind(instance));
			}
			return instance;
		}

		private _filterTable: EventTable;
		private _suspended: boolean = false;
		private _domSuspended: boolean = false; // DOM Event 차단 여부


		constructor() {
			this._filterTable = new EventTable();
		}

		/**
		 * 이벤트 필터를 추가합니다.
		 * @param type 필터를 추가할 이벤트 유형.
		 * @param filter 추가할 필터 함수.
		 */
		addFilter(type: string, filter: ((e: CEvent) => void)) {
			this._filterTable.addEventListener(type, filter);
		}

		/**
		 * 이벤트 필터를 제거합니다.
		 * @param type		필터를 제거할 이벤트 유형.
		 * @param filter	제거할 필터 함수.
		 */
		removeFilter(type: string, filter: (e: CEvent) => void) {
			this._filterTable.removeEventListener(type, filter);
		}

		/**
		 * 등록된 모든 이벤트 필터를 제거합니다.
		 */
		removeAllFilters() {
			this._filterTable.removeAllEventListeners();
		}

		_hasEventFilter(type: string): boolean {
			return this._filterTable._hasEventListener(type);
		}

		/**
		 * 특정 이벤트를 전달합니다.
		 * @param e 이벤트 객체
		 * @param target 이벤트 타겟
		 */
		_dispatchEvent(e: CEvent, target: IEventTarget): boolean {
			if (this._suspended == true) {
				return true;
			}
			e._prepareWithTarget(target);
			this._filterTable.dispatchEvent(e);
			if (!e.propagationStopped) {
				// TODO IEventTarget을 구현한 클래스면 모두 호출할 수 있도록
				// if (e.target instanceof cpr.controls.Control) {
				if (e.control instanceof cpr.controls.Control) {
					// let control = e.target as cpr.controls.Control;
					let control = e.control as cpr.controls.Control;
					control._processEvent(e);
				}
			}
			return !e.defaultPrevented;
		}

		public _isDOMSuspended(): boolean {
			return this._domSuspended;
		}

		public _createSilentFunction(func: Function): Function {
			return () => {
				this._suspended = true;
				try {
					return func();
				} finally {
					this._suspended = false;
				}
			}
		}

		/**
		 * 모든 이벤트 전파를 차단한 상태로 특정 함수를 실행하고 그 결과값을 얻습니다.
		 * @param func 실행할 함수.
		 * @return 전달한 함수의 실행 결과.
		 */
		public omitEvent(func: Function): any {
			let silentFunc: Function = this._createSilentFunction(func);
			return silentFunc();
		}

		public _omitDOMEvent(func: Function): any {
			return (() => {
				this._domSuspended = true;
				try {
					return func();
				} finally {
					this._domSuspended = false;
				}
			})();
		}

		// DOMEventHandler Delegator
		// RootApp Container Element를 기억
		private _browserEventHandlerMap: {
			[ctrlUUID: string]: {
				[eventType: string]: (e: CEvent) => void
			}
		} = {};
		// element의 targetUUID와 eventType 및 Handler 맵
		private _eventHandlerMap: {
			[targetUUID: string]: {
				[eventType: string]: (e: CEvent) => void
			}
		} = {};
		// UIControl의 UUID와 element의 targetUUID의 맵
		private _controlHandlerMap: {
			[ctrlUUID: string]: string[] /* targetUUID */
		} = {};
		// resize event 처리를 위해 
		// resize event handler를 가지는 targetUUID와 마지막 resize 후 element의 사이즈 맵
		private _sizeMap: {
			[targetUUID: string]: {
				width: number, height: number
			}
		} = {};

		public _clearControlHandler(ctrlUUID: string): void {
			if (!ctrlUUID) {
				return;
			}
			let targetUUID: string[] = this._controlHandlerMap[ctrlUUID];
			if (targetUUID) {
				targetUUID.forEach((uuid: string) => {
					delete this._eventHandlerMap[uuid];
					delete this._sizeMap[uuid]; // sizemap
				});
			}
			delete this._controlHandlerMap[ctrlUUID];
			delete this._browserEventHandlerMap[ctrlUUID];
		}

		public _removeControlShapeHandler(ctrlUUID: string, targetUUID: string, eventMap: { [eventType: string]: (e: events.CEvent) => void }): void {
			if (!ctrlUUID || !targetUUID) {
				return;
			}
			let targetUUIDs: string[] = this._controlHandlerMap[ctrlUUID];
			if (targetUUIDs) {
				let targetIdx: number = targetUUIDs.indexOf(targetUUID);
				if (targetIdx > -1) {
					let oldEventMap: { [eventType: string]: (e: events.CEvent) => void } = this._eventHandlerMap[targetUUID];
					if (eventMap === oldEventMap) {
						targetUUIDs.splice(targetIdx, 1);

						delete this._eventHandlerMap[targetUUID];
						delete this._sizeMap[targetUUID]; // sizemap

						// console.error("oldEventMap and newEventMap are matched, eventMape deleted : " + targetUUID);
					} else {
						// console.error("oldEventMap and newEventMap are unmatched : " + targetUUID + eventMap);
					}
				}
			}
		}

		public _setBrowserEventHandler(container: controls.Container, handlerMap: { [eventType: string]: (e: CEvent) => void }): void {
			this._browserEventHandlerMap[container.uuid] = handlerMap;
		}

		public _addEventHandlerMap(ctrlUUID: string, targetUUID: string, eventMap: { [eventType: string]: (e: CEvent) => void }): void {
			let targetUUIDs: string[] = this._controlHandlerMap[ctrlUUID];
			if (!targetUUIDs) {
				targetUUIDs = [];
				this._controlHandlerMap[ctrlUUID] = targetUUIDs;
			}
			if (targetUUIDs.indexOf(targetUUID) == -1) {
				targetUUIDs.push(targetUUID);
			}
			this._eventHandlerMap[targetUUID] = eventMap;

			// console.log("eventEventMap added: " + targetUUID);

			// resize event handler가 있는 경우 그려진 후 DOM의 변경 전 크기를 조회하여 저장.
			if (eventMap["resize"]) {
				if (!this._sizeMap[targetUUID]) {
					// TODO 전체 DOM을 다 찾아 사이즈를 계산해야 하기 때문에 비용이 비쌈
					let element: Element = document.querySelector("[" + ufc.ControlRenderer._ATTR_UUID + "='" + targetUUID + "']");
					if (element) {
						// 이전 그려진 DOM이 있으면 이전 크기를 설정
						let clientRect = element.getBoundingClientRect();
						this._sizeMap[targetUUID] = { width: clientRect.width, height: clientRect.height };
					} else {
						// 새로 그려지는 DOM은 resize 이벤트를 무조건 받아 처리하기 위해 초기 상태로 설정
						this._sizeMap[targetUUID] = { width: -1, height: -1 };
					}
				}
			}
		}

		public _getEventHandler(e: Event, targetuuid: string): (e: CEvent) => void {
			let eventHandler: { [eventType: string]: (e: CEvent) => void } = this._eventHandlerMap[targetuuid];
			if (eventHandler) {
				let eventType: string = e.type;
				let handler: (e: CEvent) => void = eventHandler[eventType];
				return handler;
			}
			return null;
		}

		public _getEventDelegator(): (e: Event) => void {
			return xbhandle;
		}


		/* resize event 처리 시작 */
		// EventBus에서 사용할 공용 ResizeObserver
		private _resizeObserver: resize.ResizeObserver = null;
		// ResizeObserver에서 resize event가 발생했을 때 호출하는 callback handler
		private _resizeObserverCallback: resize.ResizeObserverCallback = (entries: resize.ResizeObserverEntry[], observer: resize.ResizeObserver) => this._resizeCallback(entries, observer);

		public _observeResizeEvent(element: HTMLElement): void {
			let resizeObserver: resize.ResizeObserver = null;
			if (this._resizeObserver) {
				resizeObserver = this._resizeObserver;
			} else {
				resizeObserver = new resize.ResizeObserver(this._resizeObserverCallback);
				this._resizeObserver = resizeObserver;
			}
			resizeObserver.observe(element);
		}

		public _unobserveResizeEvent(element: HTMLElement): void {
			if (this._resizeObserver) {
				this._resizeObserver.unobserve(element);
			}
		}

		private _resizeCallback(entries: resize.ResizeObserverEntry[], observer: resize.ResizeObserver): void {
			if (!this._eventHandlerMap) {
				return;
			}
			for (let idx: number = 0; idx < entries.length; idx++) {
				let entry: resize.ResizeObserverEntry = entries[idx];
				this._resize(entry.target);
			}
		}

		public _resize(rootElement: HTMLElement): void {
			if (!rootElement) {
				return;
			}

			let evntType: string = "resize";
			let potentialEvntType: string = "-potential-resize-"; // 보이지 않는 HTMLElement에 잠재적인 resize 이벤트
			let targetUUIDs: string[] = _.keys(this._sizeMap);
			for (let idx: number = 0; idx < targetUUIDs.length; idx++) {
				let traverser: ufc.DOMTraverser = ufc._traverseFromElement(rootElement);

				let targetUUID: string = targetUUIDs[idx];
				traverser = traverser._find(`[${ufc.ControlRenderer._ATTR_UUID}='${targetUUID}']`);
				if (traverser) {
					let element: HTMLElement = traverser._getElement();
					traverser.dispose();

					let eventHandlers: { [eventType: string]: (e: CUIEvent) => void } = this._eventHandlerMap[targetUUID];
					if (!eventHandlers) {
						continue;
					}

					let beforeSize: { width: number, height: number } = this._sizeMap[targetUUID];
					let clientRect = element.getBoundingClientRect();

					if (clientRect.width == 0 && clientRect.height == 0 && clientRect.left == 0 && clientRect.right == 0) {
						// 숨겨진 컨트롤은 잠재리사이즈 이벤트를 발생
						let pResizeHandler: (e: CUIEvent) => void = eventHandlers[potentialEvntType];
						if (pResizeHandler) {
							let eventObj: CUIEvent = new CUIEvent(potentialEvntType);
							pResizeHandler(eventObj);
						}
						continue;
					}

					// eventhandler가 매핑된 실제 DOM의 사이즈가 변경되었을 때만 호출
					if (beforeSize.width != clientRect.width || beforeSize.height != clientRect.height) {
						let resizeHandler: (e: CUIEvent) => void = eventHandlers[evntType];
						let domSize: { width: number, height: number } = {
							width: clientRect.width, height: clientRect.height
						};
						if (resizeHandler) {
							let eventObj: CUIEvent = new CUIEvent(evntType, { content: domSize });
							resizeHandler(eventObj);
						}
						this._sizeMap[targetUUID] = domSize;
					}
				}
			}
		}
		/* resize event 처리 종료 */

		private _doWindowScroll(ev: events.CUIEvent): void {
			for (let ctrlUUID in this._browserEventHandlerMap) {
				let handlerMap: { [eventType: string]: (e: CEvent) => void } = this._browserEventHandlerMap[ctrlUUID];
				if (handlerMap) {
					let handler: (e: CEvent) => void = handlerMap["window-scroll"];
					if (handler) {
						handler(ev);
					}
				}
			}
		}
	}

	let monitorInstance: SerialEventProcessMonitor = null;
	export class SerialEventProcessMonitor {
		/**
		 * 이벤트 버스 싱글톤 인스턴스를 얻습니다.
		 */
		static get INSTANCE(): SerialEventProcessMonitor {
			if (monitorInstance == null) {
				monitorInstance = new SerialEventProcessMonitor();
			}
			return monitorInstance;
		}

		private _started: boolean;
		private _processingEvent: Event;

		constructor() {
			this._started = false;
		}

		public _startProcessing(e: Event): boolean {
			// TODO 적용시 문제점 체크 후 패치
			if (this._started === true) {
				return false;
			}
			this._started = true;
			this._processingEvent = e;
			return true;
		}

		public _endProcessing(e: Event): void {
			// TODO 적용시 문제점 체크 후 패치
			if (this._processingEvent === e) {
				this._started = false;
				this._processingEvent = null;
			}
		}
	}
}

/**
 * 전역 이벤트 핸들러
 * @param e DOM UIEvent
 */
function xbhandle(e: Event): void {
	if (!e) {
		return;
	}

	// DOM 이벤트 차단여부 체크
	if (cpr.events.EventBus.INSTANCE._isDOMSuspended()) {
		return;
	}

	// TODO 적용시 문제점 체크 후 패치
	// try {
	// 	// 다른 이벤트가 처리 중 인지 체크
	// 	if (cpr.events.SerialEventProcessMonitor.INSTANCE._startProcessing(e) === false) {
	// 		//다른 이벤트가 처리 중일 경우 이벤트 처리 중단
	// 		return;
	// 	}
	let eventTarget: Node = <Node>e.target;
	while (eventTarget != null && eventTarget.nodeType != Node.ELEMENT_NODE) {
		eventTarget = cpr._getParentElement(eventTarget); // SVG는 IE에서 parentElement를 지원하지 않음
		// eventTarget = eventTarget.parentElement;
	}
	if (!eventTarget) {
		return;
	}
	let target: HTMLElement = <HTMLElement>eventTarget;
	let targetElement: HTMLElement = <HTMLElement>eventTarget;

	let currentElement: HTMLElement = <HTMLElement>e.currentTarget;
	let eventWrapper: cpr.events.CEvent = cpr.events.wrap(e);
	let eventType: string = e.type;
	let istargetmatch: boolean = cpr.ufc.EventAttacher._isTargetMatch(eventType);
	while (targetElement) {
		targetElement = cpr.ufc.ControlRenderer.findElementHasTargetUUID(targetElement, currentElement);
		// Scroll Event의 경우 bubbling이 일어나고 InputElement의
		// 경우에도 발생할 수 있기 때문에 target과 handler가 일치해야만 처리하도록 막음.
		if (istargetmatch == true && target != targetElement) {
			return;
		}
		if (targetElement) {
			let targetuuid: string = cpr.ufc.ControlRenderer.getTargetUUID(targetElement);
			if (targetuuid) {
				let eventHandler: (e: cpr.events.CEvent) => void = cpr.events.EventBus.INSTANCE._getEventHandler(e, targetuuid);
				if (eventHandler) {
					eventWrapper.setCurrentTarget(targetElement);
					eventHandler(eventWrapper);
				}
			}
			if (eventWrapper.propagationStopped == true) {
				break;
			}
			targetElement = cpr._getParentElement(targetElement); // SVG는 IE에서 parentElement를 지원하지 않음
			// targetElement = targetElement.parentElement;
		}
	}
	// TODO 적용시 문제점 체크 후 패치
	// } finally {
	// 	cpr.events.SerialEventProcessMonitor.INSTANCE._endProcessing(e);
	// }
}