namespace cpr.events {
	/**
	 * Item 이벤트 유형
	 * @noinstance
	 */
	export class ItemEventType {
		/**
		 * 아이템 클릭시 발생하는 이벤트.
		 */
		public static readonly ITEMCLICK: string = "item-click";
		/**
		 * 아이템 클릭시 발생하는 이벤트.
		 */
		public static readonly ITEM_DBLCLICK: string = "item-dblclick";
		/**
		 * 탭 헤더 클릭시 발생하는 이벤트.
		 */
		public static readonly TABHEADER_CLICK: string = "tabheader-click";
		/**
		 * 탭 헤더 체크박스를 체크시 발생하는 이벤트.
		 */
		public static readonly TABHEADER_CHECK: string = "tabheader-check";
		/**
		 * 택 헤더 체크박스를 체크를 해제시 발생하는 이벤트.
		 */
		public static readonly TABHEADER_UNCHECK: string = "tabheader-uncheck";
		/**
		 * 아이템 체크를 했을때 발생하는 이벤트.
		 */
		public static readonly ITEM_CHECK: string = "item-check";
		/**
		 * 아이템 체크를 해제 했을때 발생하는 이벤트.
		 */
		public static readonly ITEM_UNCHECK: string = "item-uncheck";
	}

	/**
	 * Item 관련 이벤트에 대한 옵션.
	 */
	export interface CItemEventOptions extends CUIEventOptions {
		/**
		 * 이벤트가 발생한 Item.
		 */
		item: any;

		/**
		 * 이벤트가 발생한 아이템 내의 타겟명을 반환합니다.
		 * item, itemicon, text, badge, checkbox
		 */
		relativeTargetName?: string;
	}

	/**
	 * 아이템 내 변경 시 발생하는 이벤트.
	 */
	export class CItemEvent extends CMouseEvent {

		/**
		 * Item 이벤트를 생성합니다.
		 * @param type Item 이벤트 유형.
		 * @param options 이벤트에 대한 옵션.
		 */
		constructor(type: string, options: CItemEventOptions) {
			super(type, options);
		}
		/**
		 * 아이템을 반환합니다.
		 * @return 아이템
		 */
		public get item(): any {
			return this._getOption("item");
		}

		/**
		 * 이벤트가 발생한 아이템 내의 타겟명을 반환합니다.
		 * @readonly
		 */
		get relativeTargetName(): string {
			return this._getOption("relativeTargetName");
		}
	}

	export interface CItemAcceptEventOptions extends CItemEventOptions {
		itemConstraint: any
	}

	export class CItemAcceptEvent extends CItemEvent {
		private _constraint: any;
		constructor(type: string, options: CItemAcceptEventOptions) {
			super(type, options)
			this._constraint = options.itemConstraint;
		}

		public get itemConstraint(): any {
			return this._constraint;
		}
	}

	export interface TabItemConstraint {
		/**
		 * 탭 아이템을 추가할 인덱스
		 */
		index: number;
	}
}