// <reference path="../controls/Control.ts"/>

namespace cpr.core {
	let registry: { [key: string]: Module } = {}
	class DependencyRejection {

	}

	let scheduldDepCheckTask: number = -1;

	function scheduleFinalDependencyCheck() {
		if (scheduldDepCheckTask !== -1) {
			return
		}


		scheduldDepCheckTask = window.setTimeout(() => {
			let moduleNames = Object.keys(registry)
			moduleNames.map(it => {
				return registry[it]
			}).filter(it => {
				return it._resolved === false
			}).forEach(it => {
				let unresolvedDependencies = it._dependencies.filter(it => {
					return moduleNames.indexOf(it) === -1 || registry[it]._resolved === false
				});
				console.error(`Could not resolve dependencies of ${it._qualifiedName}: ${unresolvedDependencies.join(", ")}`);
			});
		})
	}

	function getUnresolvedModules(): Module[] {
		return Object.keys(registry).map(it => registry[it]).filter(it => {
			return it._resolved === false
		})
	}

	/**
	 * 모듈의 디펜던시 및 카테고리등의 특징을 기술하는 방법을 제공하는 객체.
	 */
	export class ModuleDescriber {
		private _module: Module

		constructor(module: Module) {
			this._module = module
		}

		/**
		 * 현재 선언중인 공통 모듈의 카테고리들을 지정합니다.
		 * @param categories 포함된 카테고리 목록
		 */
		category(...categories: string[]) {
			// 아무일도 안합니다. 컴파일러가 체크하기 위한 문법입니다.
		}

		/**
		  * 모듈이 갖는 의존성을 선언합니다.
		  * @param otherModule 현재 선언중인 모듈의 의존 모듈의 ID 목록
		  */
		depends(...otherModule: string[]) {
			otherModule.forEach(each => {
				if (this._module._dependencies.indexOf(each) === -1) {
					this._module._dependencies.push(each)
				}
			})
			if (this._module._canBeResolved() === false) {
				throw new DependencyRejection()
			}
		}
	}

	/**
	 * 모듈을 관리하는 클래스.
	 */
	export class Module {
		public _qualifiedName: string
		public _dependencies: string[] = [];
		public _resolved = false
		public _exports: (Module, any, ModuleDescriber) => void;

		/**
		 * 모듈을 정의 합니다.
		 * @param qualifiedName 경로 ex)folder.file
		 * @param exports exports, globals 파라미터를 전달하는 함수
		 */
		static define(qualifiedName: string, exports: (exports: Module, globals?: any, describer?: ModuleDescriber) => void) {
			if (qualifiedName == null || exports == null) {
				return
			}

			// 모듈의 중복 정의를 차단 함.
			if (registry[qualifiedName]) {
				return;
			}

			let newModule = new Module(qualifiedName)
			newModule._exports = exports;

			registry[qualifiedName] = newModule
			let describer = new ModuleDescriber(newModule)
			try {
				exports(newModule, window, describer)
				newModule._resolved = true;
			} catch (e) {
				if (e instanceof DependencyRejection) {
					newModule._resolved = false
					scheduleFinalDependencyCheck()
				} else {
					throw e;
				}
			}

			getUnresolvedModules().filter(it => it._canBeResolved()).forEach(it => {
				let describer = new ModuleDescriber(it)
				it._exports(it, window, describer)
				it._resolved = true
			})
		}

		/**
		 * 정의한 모듈을 불러옵니다.
		 * @param qualifiedName 식별 가능한 이름 ex) folder.file 
		 */
		static require(qualifiedName: string): Module {
			// 호환성.
			qualifiedName = qualifiedName.replace(/\./g, "/")
			let result = registry[qualifiedName]
			if (result && result._resolved === false) {
				return null
			}
			return result
		}

		/**
		 * 정의되어 있는지 여부를 반환합니다. 
		 * @param qname 식별 가능한 이름 ex) folder.file
		 */
		static isDefined(qname: string) {
			return registry[qname] != null
		}

		constructor(qualifiedName: string) {
			this._qualifiedName = qualifiedName
		}

		/**
		 * 해당 모듈의 모든 디펜던시가 만족되었는지 여부를 반환합니다.
		 */
		public _canBeResolved(): boolean {
			return this._dependencies.every(it => {
				return registry[it] != null && registry[it]._resolved
			});
		}
	}
}