/// <reference path="./IGridCellRenderer.ts"/>


namespace cpr.controls.gridpart.renderer {

	/**
	 * @private
	 */
	export class RowGroupCellRenderer extends AbstractGridCellRenderer {
		private _cellRenderer: (grid: Grid, uiControl: GridUIControl, data: (string | ufc.StyledString), option: IRenderOption) => ufc.ControlShape;


		constructor(cellprop: GridCellProp /* GridDetailCellProp */, grid: Grid) {
			super(cellprop, grid);
		}

		private get rowgroupProp(): GridFooterCellProp {
			return this.prop as GridFooterCellProp;
		}

		protected _init(): void {
			let uicontrol: GridUIControl = this.rowgroupProp.configuration.control;
			if (uicontrol == null) {
				this._cellRenderer = CellRendererFactory._getRenderer(uicontrol);
			}
		}

		public createCellShape(gridRow: provider.GridRow | provider.GridRowGroup, option: IRenderOption)
			: ufc.ControlShape | ufc.ControlRenderer {
			let uicontrol: GridUIControl = this.rowgroupProp.configuration.control;
			let rowgroup: provider.GridRowGroup = gridRow as provider.GridRowGroup;
			let colprop: GridFooterCellProp = this.rowgroupProp;
			let exprResult: string | number | ufc.StyledString = GridUtil._getRowGroupExprValue(colprop, rowgroup);
			exprResult = typeof (exprResult) == "number" ? "" + exprResult : exprResult;
			let exprResultStr: string = ufc.StyledString._asString(exprResult); // expr 결과값
			if (uicontrol && _isNullOrEmpty(colprop.configuration.expr) == false) {
				uicontrol.value = exprResultStr;
			}

			let controlShape: ufc.ControlShape = null;
			if (uicontrol) {
				controlShape = uicontrol._renderGridCellShape(this.grid, exprResult, option);
			} else { // default cell
				controlShape = this._cellRenderer(this.grid, uicontrol, exprResult, option);
			}

			// UIControl 공통 Shape 처리
			if (uicontrol) {
				let attr: { [key: string]: string } = {};

				controlShape.attr = _mergeObject(controlShape.attr, attr);
				// classnames
				controlShape.classNames = _uniq((controlShape.classNames || []).concat(uicontrol.style.getClasses()).concat(GridContext.CLS_CTRL_INHERIT));
				if (uicontrol instanceof EnableUIControl && uicontrol.readOnly === true) {
					controlShape.classNames.push(ufc.Classes.READONLY);
				}
				if (uicontrol instanceof EnableUIControl && uicontrol.enabled === false) {
					controlShape.classNames.push(ufc.Classes.DISABLED);
				}
				// style
				let verticalAlign: string = this.rowgroupProp.constraint["verticalAlign"];
				if (option.height > -1 && verticalAlign == "fill") {
					let maxHeight: number = (option.hideborder === true) ? option.height : GridContext._getCellMaxHeight(option.height);
					controlShape.style = _mergeObject(uicontrol.style.css(), controlShape.style, {
						"max-height": maxHeight + "px",
						width: "100%"
					});
				} else {
					controlShape.style = _mergeObject(uicontrol.style.css(), controlShape.style, {
						width: "100%"
					});
				}
				if (uicontrol.visible == false) {
					controlShape.style["display"] = "none";
				}

				controlShape.style["width"] = "100%";
				GridUtil._setControlPosition(controlShape, this.rowgroupProp.configuration.controlConstraint);
				ufc.ShapeUtil._setTooltipAttr(controlShape, { owner: uicontrol, title: uicontrol.tooltip, id: "rgc-" + option.vrowIndex + "-" + option.cellIndex });
			}

			return controlShape;
		}

	}
}