/// <reference path="./CustomAbstractScrollbar.ts" />


namespace cpr.controls.internal {
	interface CyclicReport {
		appId: string,
		stack: core.App[]
	};

	export function _checkCyclic(context: EmbeddedApp): boolean {
		// 다이얼로그라면 부모 문맥을 무시함.
		if (context instanceof Dialog) {
			return false
		}

		function getContextParent(appInstance: core.AppInstance) {
			if (!appInstance) {
				return null;
			}
			let host = appInstance.getHost();

			// 다이얼로그라면 부모를 더 이상 탐색할 필요가 없음.
			if (host instanceof Dialog) {
				return null;
			}

			return appInstance.getHostAppInstance();
		}

		// 리포트 작성
		let report: CyclicReport = {
			appId: context.app.id,
			stack: []
		};

		let finger = context.getAppInstance();
		while (finger) {
			report.stack.unshift(finger.app);
			finger = getContextParent(finger);
		}

		// 사이클릭 없음.
		if (report.stack.indexOf(context.app) === -1) {
			return
		}

		report.stack.push(context.app);
		context.app = createCyclicReportApp(report);
	}

	/**
	 * 사이클릭 리포트 앱을 만듭니다.
	 */
	function createCyclicReportApp(report: CyclicReport): core.App {
		return new core.App(cpr._generateUUID(), {
			onCreate(app, exports) {
				// 충돌된 앱의 ID를 가리키는 앱 속성
				app.setAppProperty("appId", report.appId, false);

				let container = app.getContainer();
				container.style.css({
					"width": "100%",
					"height": "100%",
					"top": "0px",
					"bottom": "0px",
					"border": "solid 1px red"
				});

				let layout = new cpr.controls.layouts.FormLayout();
				layout.verticalMargin = layout.horizontalMargin = "5";
				layout.setColumns(["1fr"]);
				layout.setRows(["25px", "1fr"]);
				container.setLayout(layout);

				// 타이틀
				let titleOutput = new cpr.controls.Output();
				titleOutput.bind("value").toExpression('@appId + " has cycled references."');
				titleOutput.style.css({
					"color": "white",
					"background": "red",
					"text-align": "center"
				});
				container.addChild(titleOutput, {
					rowIndex: 0,
					colIndex: 0
				});

				let tree = new cpr.controls.Tree();
				report.stack.forEach((it, idx) => {
					let parent = idx === 0 ? "root" : `${idx - 1}`
					tree.addItem(new TreeItem(it.id, `${idx}`, parent))
				});
				let itemStyler = tree.style["item"] as UIControlStyler;
				itemStyler.bind("color").toExpression(`label == @appId ? "red" : "auto"`);

				tree.expandAllItems();
				container.addChild(tree, {
					rowIndex: 1,
					colIndex: 0
				});
			}
		});

	}
}