namespace cpr.geometry {
	/**
	 * 크기에 대한 인터페이스
	 */
	export interface Size {
		/**
		 * 너비
		 */
		width: number
		/**
		 * 높이
		 */
		height: number
	}

	/**
	 * 평면 좌표계상의 너비와 높이를 추상화 하는 지오메트리 연산 객체 입니다.
	 */
	export class Dimension implements Size, Transposable {
		/**
		 * 너비 기본값 0
		 */
		width: number = 0;
		/**
		 * 높이 기본값 0
		 */
		height: number = 0;

		/**
		 * 새 넓이 객체를 만듭니다.
		 * @param width 너비.
		 * @param height 높이.
		 */
		constructor(width: number, height: number) {
			this.width = width;
			this.height = height;
		}

		/**
		 * 면적을 얻습니다.
		 */
		public get area(): number {
			return this.width * this.height;
		}

		/**
		 * 사본 객체를 얻습니다.
		 */
		public getCopy(): Dimension {
			return new Dimension(this.width, this.height);
		}

		/**
		 * 이 Dimension의 너비와 높이를 부정합니다.
		 */
		public negate(): Dimension {
			this.width *= -1;
			this.height *= -1;
			return this;
		}

		/**
		 * 음수 값으로 새 차원을 만들고 반환합니다.
		 */
		public getNegated(): Dimension {
			return this.getCopy().negate();
		}

		/**
		 * 영역을 확장 합니다.
		 * @param dimension 확장할 너비.
		 */
		public add(dimension: Dimension): Dimension;

		/**
		 * 영역을 확장합니다.
		 * @param point 확장할 영역의 가로 너비 값일 x, y로 가진 포인트 객체.
		 */
		public add(point: Point): Dimension;

		/**
		 * 영역을 확장합니다.
		 * @param width 확장할 너비.
		 * @param height 확장할 높이.
		 */
		public add(width: number, height: number): Dimension;
		public add() {
			let args = _toArray(arguments);
			let widthToAdd = Number.NaN;
			let heightToAdd = Number.NaN;

			switch (args.length) {
				case 1: {
					let firstArg = args[0];
					if (firstArg instanceof Point) {
						widthToAdd = firstArg.x;
						heightToAdd = firstArg.y;
					}
					else if (firstArg instanceof Dimension) {
						widthToAdd = firstArg.width;
						heightToAdd = firstArg.height;
					}
					break;
				}
				case 2: {
					if (typeof args[0] == "number" && typeof args[1] == "number") {
						widthToAdd = args[0];
						heightToAdd = args[1];
					}
					break;
				}
			}

			if (isNaN(widthToAdd) || isNaN(heightToAdd)) {
				throw new exceptions.IllegalArgumentException();
			}
			this.width += widthToAdd;
			this.height += heightToAdd;
			return this;
		}

		/**
		 * 크기를 추가하여 확장합니다.
		 * @param dimension 
		 * @deprecated {@link add}를 사용하시기 바랍니다.
		 */
		public addByDimension(dimension: Dimension) {
			return this.add(dimension.width, dimension.height);
		}

		/**
		 * 포인트 객체를 추가하여 크기를 확장합니다.
		 * @param point 
		 * @deprecated {@link add}를 사용하시기 바랍니다.
		 */
		public addByPoint(point: Point) {
			return this.add(point.x, point.y);
		}

		/**
		 * 주어진 크기 만큼 영역이 확장된 사본 객체를 얻습니다.
		 * @param dimension 확장할 크기.
		 */
		public getAdded(dimension: Dimension): Dimension;

		/**
		 * 주어진 크기 만큼 영역이 확장된 사본 객체를 얻습니다.
		 * @param dimension 확장할 크기.
		 */
		public getAdded(dimension: Point): Dimension;

		/**
		 * 주어진 크기 만큼 영역이 확장된 사본 객체를 얻습니다.
		 * @param width 확장할 너비.
		 * @param height 확장할 높이.
		 */
		public getAdded(width: number, height: number): Dimension;
		public getAdded() {
			let args = _toArray(arguments);
			let copy = this.getCopy();
			copy.add.apply(copy, args);
			return copy;
		}

		/**
		 * 크기가 확장된 새로운 객체를 반환합니다.
		 * @param dimension 
		 * @deprecated {@link getAdded}를 사용하시기 바랍니다.
		 */
		public getAddedByDimension(dimension: Dimension) {
			return this.getCopy().addByDimension(dimension);
		}

		/**
		 * 크기가 확장된 새로운 객체를 반환합니다.
		 * @param point 
		 * @deprecated {@link getAdded}를 사용하시기 바랍니다.
		 */
		public getAddByPoint(point: Point) {
			return this.getCopy().addByPoint(point);
		}

		/**
		 * 동일성을 비교합니다.
		 * @param obj 비교할 대상 객체.
		 * @param tolerance 허용 오차.
		 */
		public equals(obj: any, tolerance = 0) {
			if (obj instanceof Dimension) {
				if (tolerance <= 0) {
					return this.width == obj.width && this.height == obj.height;
				} else {
					return Math.abs(this.width - obj.width) <= tolerance
						&& Math.abs(this.height - obj.height) <= tolerance;
				}

			} else {
				return false;
			}
		}

		public isEmpty(): boolean {
			return this.width === 0 || this.height === 0;
		}

		public transpose(): this {
			let temp = this.width;
			this.width = this.height;
			this.height = temp;
			return this;
		}
	}
}