/// <reference path="./provider/DataBindable.ts" />
/// <reference path="./TextInput.ts" />
namespace cpr.controls {
	/**
	 * text의 길이의 기본 단위.
	 * @private
	 */
	export enum TextLengthUnit {
		/**
		 * 문자를 기준으로 text의 길이를 측정합니다.
		 */
		char,
		/**
		 * UTF-8 기준으로 text의 byte size를 측정합니다.
		 */
		utf8,
		/**
		 * ascii 기준으로 text의 byte size를 측정합니다.
		 */
		ascii
	}

	/**
	 * 가상키보드를 표시하는 자판의 배열 타입
	 */
	export enum InputMode {
		/**
		 * 가상 키보드를 표시하지 않습니다.
		 */
		none = "none",
		/**
		 * 사용자의 현재 로케일에 맞는 표준 키보드를 표시합니다.
		 */
		text = "text",
		/**
		 * decimal 입력에 최적화된 키보드를 표시합니다.
		 */
		decimal = "decimal",
		/**
		 * 숫자 입력에 최적화된 키보드를 표시합니다.
		 */
		numeric = "numeric",
		/**
		 * 전화번호 입력에 최적화된 키보드를 표시합니다.
		 */
		tel = "tel",
		/**
		 * 검색어 입력에 최적화된 키보드를 표시합니다.
		*/
		search = "search",
		/**
		 * 이메일 입력에 최적화된 키보드를 표시합니다.
		 */
		email = "email",
		/**
		 * URL 입력에 최적화된 키보드를 표시합니다.
		 */
		url = "url"
	}

	/**
	 * IE, FireFox 브라우저에서 한영 변환 설정을 반환합니다.
	 */
	export enum ImeMode {
		/**
		 * ime 설정에 대해 아무것도 설정 하지않습니다.
		 */
		auto = "auto",
		/**
		 * 기본 값으로 한글을 입력받습니다.
		 */
		active = "active",
		/**
		 * 기본 값으로 영문을 입력받습니다.
		 */
		inactive = "inactive",
		/**
		 * 영문만을 입력받습니다.
		 */
		disabled = "disabled"
	}

	/**
	 * @private
	 */
	export enum SelectionState {
		NONE, INIT, API
	}

	interface TextEditorMaxLengthDelegate {
		onBeforePaste?: () => void
		onMaxlength?: () => void
		onAfterPaste?: (text: string) => void
		transformDropTextHandler?: (text: string) => string
		transformPasteTextHandler?: (text: string) => string
		computeDisplayText?: (text: string) => string
	}

	/**
	 * @private
	 */
	export class TextEditorMaxLength {
		private _dropData: foundation.InputObject = null;
		private _dragData: foundation.InputObject = null;
		private _maxLength: number = -1;
		private _lengthUnit: string = "char";
		private _beforeInput: foundation.InputObject = null;;
		private _pasteInfo: { value: string, ss: number, se: number };
		private _owner: UIControl;
		private _delegate: TextEditorMaxLengthDelegate;

		constructor(owner: UIControl, delegate?: TextEditorMaxLengthDelegate) {
			this._owner = owner;
			this._delegate = delegate;
		}

		private _onmaxlength() {
			this._delegate?.onMaxlength?.();
		};

		private _transformDropText(text: string) {
			return this._delegate?.transformDropTextHandler?.(text) ?? text;
		}

		private _transformPasteText(text: string) {
			return this._delegate?.transformPasteTextHandler?.(text) ?? text;
		}

		private _getMaxLength() {
			return this._owner["maxLength"] ?? this._maxLength;
		}

		private _getLengthUnit() {
			return this._owner["lengthUnit"] ?? this._lengthUnit;
		}

		private _getReadOnly() {
			return this._owner["readOnly"] ?? false;
		}

		private _computeDisplayText(text: string) {
			return this._delegate?.computeDisplayText?.(text) ?? text;
		}

		/**
		 * 입력상자 셰이프에 이벤트를 적용합니다. 옵션은 owner에 동일한 속성이 있는 경우 사용하고 없는 경우 option을 설정해주어야 합니다.
		 * @param inputShape 
		 * @param options 
		 * @returns 
		 */
		public apply(inputShape: ufc.ElementShape, options?: { maxLength: number, lengthUnit: string }) {
			if (inputShape == null) {
				return;
			}

			if (inputShape["events"] == undefined || inputShape["events"] == null) {
				inputShape["events"] = {};
			}

			if (this._getReadOnly()) {
				return;
			}
			if (options) {
				this._maxLength = options.maxLength;
				this._lengthUnit = options.lengthUnit;
			}

			if (this._getMaxLength() > -1) {
				ufc.ShapeUtil.addEventHandler(inputShape, "paste", (e) => this._onpaste(e), true);
				ufc.ShapeUtil.addEventHandler(inputShape, "blur", (e) => this._onblur(e), true);
			}
			ufc.ShapeUtil.addEventHandler(inputShape, "keydown", (e) => this._onkeydown(e), true);
			ufc.ShapeUtil.addEventHandler(inputShape, "beforeinput", (e) => this._onbeforeinput(e), true);
			ufc.ShapeUtil.addEventHandler(inputShape, "input", (e) => this._oninput(e), true);
			ufc.ShapeUtil.addEventHandler(inputShape, "drop", (e) => this._ondrop(e), true);
			ufc.ShapeUtil.addEventHandler(inputShape, "dragstart", (e) => this._ondragstart(e), true);
			ufc.ShapeUtil.addEventHandler(inputShape, "dragend", (e) => this._ondragend(e), true);
		}

		private _onkeydown(e: events.CKeyboardEvent): void {
			let input = <HTMLInputElement>e.target;
			this._beforeInput = null;
			input.removeAttribute("maxlength");
			if (e.defaultPrevented) {
				return;
			}
			let keychar = e.key;
			if (keychar == null) {
				return;
			}

			let ss = input.selectionStart;
			let se = input.selectionEnd;

			this._beforeInput = new foundation.InputObject(input.value, ss, se, foundation.InputLocation.keydown);
			if (e.keyCode == events.KeyCode.IME_INPUT) {
				this._beforeInput = new foundation.InputObject(input.value, ss, se, foundation.InputLocation.keydownIME);
			}
			let data = _getByteLength(this._getLengthUnit(), input.value, this._getMaxLength());
			let maxLength = this._getMaxLength();
			if (maxLength > 0 && data.byte >= maxLength) {
				let skipCode = [events.KeyCode.UP, events.KeyCode.DOWN, events.KeyCode.TAB,
				events.KeyCode.CTRL, events.KeyCode.META, events.KeyCode.ALT, events.KeyCode.SHIFT, events.KeyCode.CAPSLOCK,
				events.KeyCode.DELETE, events.KeyCode.BACKSPACE, events.KeyCode.RIGHT, events.KeyCode.LEFT, events.KeyCode.ESC,
				events.KeyCode.PAGEDOWN, events.KeyCode.PAGEUP, events.KeyCode.HOME, events.KeyCode.END, events.KeyCode.ENTER, events.KeyCode.IME_INPUT];

				if (skipCode.indexOf(e.keyCode) == -1 && e._getMod1Key() !== true && se == ss) {
					this._onmaxlength();
				}
				input.setAttribute("maxlength", data.inputMaxLength + "");
			}

		}
		/**
		 * 안드로이드에서 paste나 auto complete로 입력된 경우를 체크합니다.
		 * TODO: insertText로 e.data의 길이가 2개 이상인 경우 IME조합도 될 수 있어(ios) 정확한 구분방법은 아닙니다. 모바일 전용 클래스를 만들어 input 이벤트에서 모든 처리를 하는 것을 검토해야 합니다.
		 * @param e 
		 * @returns 
		 */
		private _isAndroidClipboardPaste(e: events.CUIEvent): boolean {
			if (!e.inputType || _detectBrowser().isAndroid == false) {
				return false;
			}
			return e.data && e.data.length > 1 && e.inputType == "insertText";
		}

		/**
		 * IE 동작 안함. keydown에서 처리해야함. Safari에서는 beforeinput>input>keydown 순서로 이벤트가 동작함.
		 * @param e 
		 */
		private _onbeforeinput(e: events.CUIEvent) {
			let isWindows11IME = utils.Util.detectBrowser().os.indexOf("Windows") > -1 && (this._beforeInput && (this._beforeInput.from == foundation.InputLocation.keydownIME || this._beforeInput.from == foundation.InputLocation.copy) && !e.data);
			if (isWindows11IME) {
				return;
			}
			let input = <HTMLInputElement>e.target;
			if (this._beforeInput) {
				let isAndroidClipboardPaste = this._isAndroidClipboardPaste(e) && this._beforeInput.from == foundation.InputLocation.keydownIME;
				if (isAndroidClipboardPaste) {
					this._pasteEvent(input, e.data, e);
				}
				this._beforeInput.setData("beforeinputData", e.data)
				return;
			}
			let ss = input.selectionStart;
			let se = input.selectionEnd;

			this._beforeInput = new foundation.InputObject(input.value, ss, se, foundation.InputLocation.beforeinput);
			this._beforeInput.setData("beforeinputData", e.data);
		}

		private _oninput(e: events.CUIEvent): void {
			if (e.defaultPrevented) {
				return;
			}
			let inputType = e.inputType;
			let input: HTMLInputElement = <HTMLInputElement>e.target;
			let isWindowsIMEComposition = utils.Util.detectBrowser().os.indexOf("Windows") > -1 &&
				inputType == "deleteContentBackward" && this._beforeInput?.from == foundation.InputLocation.keydownIME && this._beforeInput.getData("beforeinputData") == null;
			if (isWindowsIMEComposition) {
				input.value = this._beforeInput.text;
				return;
			}
			if (this._dragData) {
				// 자신에게 드래드하고 드롭한 경우 드래그 이벤트가 먼저 발생함.
				this._dragData = null;
				return;
			}
			if (this._pasteInfo) {
				if (input.value != this._pasteInfo.value) {
					input.value = this._pasteInfo.value;
					input.setSelectionRange(this._pasteInfo.ss, this._pasteInfo.se);
				}
				this._pasteInfo = null;
				return;
			}

			this._checkMaxLength(e, input);//maxlength 체크 및 input 엘리먼트 값 변경.
			if ("insertFromDrop" == inputType || this._dropData) {
				this._dropData = null;
			}
		}

		private _checkMaxLength(e: events.CUIEvent, input: HTMLInputElement) {
			let maxlength = this._getMaxLength();
			if (0 > maxlength) { // maxLength가 -1이면 length 체크를 하지 않는다.
				return;
			}
			let value: string = this._computeDisplayText(input.value);
			let dropTransferText = this._dropData ? this._dropData.getData("transfer") : null;
			if (dropTransferText) {
				value = value != input.value ? value + dropTransferText : value;
			}
			let inputType: string = e.inputType;

			let data = _getByteLength(this._getLengthUnit(), value, maxlength);
			let checkLength = data.byte;
			let suggestLength = data.maxindex;
			let inputMaxLength = data.inputMaxLength;

			//조합형이 아닌 문자는 maxlength에 채워지면 포커스 이동이 가능하도록 한다.
			let isAsciiCharacters = /^[!-~\s]+$/.test(value);
			let isMaxLength = isAsciiCharacters ? maxlength <= checkLength : maxlength < checkLength;
			if (isMaxLength == false) {
				return; //maxlength를 넘지 않으면 동작하지 않음.
			}

			if (this._beforeInput) {
				let inputLength = value.length - this._beforeInput.text.length;
				let isSelected = this._beforeInput.selectionStart != this._beforeInput.selectionEnd;
				let beforeInputByteLength = _getByteLength(this._getLengthUnit(), this._beforeInput.text, maxlength);
				let isDelete = inputLength < 0 && isSelected == false;
				if (isDelete) { // maxlength 넘었을때 삭제는 무시한다.
					return;
				}
				if (inputLength <= 0 && isSelected && maxlength <= beforeInputByteLength.byte) {
					// maxlength를 넘은 값이 있을때 셀렉션으로 값을 입력하는 조건
					let replacedText = "";
					if (inputLength == 0) {
						replacedText = value.substring(this._beforeInput.selectionStart, this._beforeInput.selectionEnd);
					}
					let isRedoOrUndo: boolean = inputType == "historyUndo" || inputType == "historyRedo";
					if (inputType != "insertFromDrop" && !isRedoOrUndo && this._dropData == null) {
						input.value = utils.StringUtil.replaceRange(this._beforeInput.text, replacedText, this._beforeInput.selectionStart, this._beforeInput.selectionEnd);
						input.setSelectionRange(input.selectionStart, input.selectionEnd);
					}
				} else {
					let selectionRange: { start: number, end: number } = null;

					if (this._dropData) {
						selectionRange = { start: this._beforeInput.selectionEnd, end: input.selectionEnd };
						let searchRange = value.substring(0, selectionRange.start < selectionRange.end ? selectionRange.end : value.length);
						let findIndex = searchRange.lastIndexOf(dropTransferText);
						if (findIndex > -1) {
							selectionRange.start = findIndex;
							selectionRange.end = selectionRange.start + dropTransferText.length;
						}

					} else if ((isAsciiCharacters && this._beforeInput.text.length < maxlength) == false) {
						selectionRange = { start: this._beforeInput.selectionEnd, end: input.selectionEnd };
						let beforeInputData = this._beforeInput.getData("beforeinputData");
						if (beforeInputData != null && inputType == "insertCompositionText" && beforeInputData.length == 1) {
							// CompositionText 입력시 selection은 일반적으로 뒤로 위치하는데 특정 버전에서 앞에 위치하는 경우 보정하기 위한 처리. Chrome 70
							if (value.charAt(selectionRange.end - 1) != beforeInputData) {
								selectionRange.end += 1;
								selectionRange.start += 1;
							}
						}
					}

					if (selectionRange) {
						if (selectionRange.start < selectionRange.end) { //IE에서 한글입력시 셀렉션이 되어서 ss와se가 값이 달라 se를 사용한다.
							let selectedValue = value.substring(selectionRange.start, selectionRange.end);
							let unselectedValue = value.substring(0, selectionRange.start) + value.substring(selectionRange.end);
							let textArray = _getSymbols(selectedValue);
							let stringBuffer = new utils.StringBuffer();
							stringBuffer.append(textArray);
							while (stringBuffer.length > 0) {
								value = unselectedValue.substring(0, selectionRange.start) + stringBuffer.toString() + unselectedValue.substring(selectionRange.start);
								let tempValueData = _getByteLength(this._getLengthUnit(), value, maxlength);
								if (this._getMaxLength() >= tempValueData.byte) {
									break;
								}
								stringBuffer.deleteCharAt(stringBuffer.length - 1);
								if (stringBuffer.length == 0) {
									value = unselectedValue;
								}
							}
						} else {
							value = this._getTextByLength(value, suggestLength);
						}
						if (_isIE() && this._dropData) { // IE에서 드롭시 input이벤트에서 값이 반영되지 않음.
							setTimeout(() => {
								input.value = value;
								input.setSelectionRange(selectionRange.start, selectionRange.start);
							});
						} else {
							input.value = value;
							input.setSelectionRange(selectionRange.start, selectionRange.start);
						}
					} else {
						// keydown, drop, paste 이벤트 영향을 안받아 maxlength가 적용되지 않는 경우
						input.value = this._getTextByLength(value, suggestLength);
						input.setAttribute("maxlength", inputMaxLength + "");
					}
				}

				if (input.value == this._beforeInput.text) {
					e.stopPropagation();
				}
			} else {
				// keydown, drop, paste 이벤트 영향을 안받아 maxlength가 적용되지 않는 경우
				input.value = this._getTextByLength(value, suggestLength);
				input.setAttribute("maxlength", inputMaxLength + "");
			}
			//IME 텍스트가 다음 컨트롤에 입력되는 현상
			setTimeout(() => {
				this._onmaxlength();
			})
		}

		private _getTextByLength(text: string, length: number): string {
			let symbols = _getSymbols(text);
			return symbols.slice(0, length).join("");
		}

		private _pasteEvent(input: HTMLInputElement, pasteValue: string, e: ClipboardEvent) {
			if (this._getMaxLength() < 0) {
				return;
			}
			let value = input.value;
			let data = _getByteLength(this._getLengthUnit(), value, this._getMaxLength());
			let checkLength = data.byte;
			let ss = input.selectionStart;
			let se = input.selectionEnd;

			this._delegate?.onBeforePaste?.();

			if (ss == se && (this._getMaxLength() == 0 || this._getMaxLength() <= checkLength)) {
				e.preventDefault();
				let inputEvent = new events.CKeyboardEvent("input");
				inputEvent.nativeEvent = e;
				this._owner.dispatchEvent(inputEvent);
				this._onmaxlength();
				return;
			}

			let transformText = this._transformPasteText(pasteValue);
			let isFiltered = transformText != pasteValue;

			if (ss != se) {
				value = utils.StringUtil.replaceRange(value, "", ss, se);
			}

			let textArray = _getSymbols(transformText);
			let len = textArray.length;
			let isPasteOverflow = false;
			let stringBuffer = new utils.StringBuffer();
			stringBuffer.append(_getSymbols(value));
			let tempValueData: { byte: number, maxindex: number, inputMaxLength: number };
			for (let i = 0; i < len; i++) {
				stringBuffer.insert(textArray[i], stringBuffer.getIndexBySelection(ss) + i);
				tempValueData = _getByteLength(this._getLengthUnit(), stringBuffer.toString(), this._getMaxLength());
				let tempLength = tempValueData.byte;

				if (this._getMaxLength() < tempLength) {
					isPasteOverflow = true;
					break;
				}
				if (this._getMaxLength() == tempLength) {
					isPasteOverflow = true;
				}
				value = stringBuffer.toString();
			}

			if (isFiltered) {
				e.preventDefault();
			} else {
				input.setAttribute("maxlength", tempValueData.inputMaxLength + "");
				this._pasteInfo = { value: value, ss: ss, se: ss };
			}
			window.setTimeout(() => {
				if (isFiltered) {
					input.value = value;
					input.setSelectionRange(ss, ss);
					let inputEvent = new events.CKeyboardEvent("input");
					inputEvent.nativeEvent = e;
					this._owner.dispatchEvent(inputEvent);
				}
				input.removeAttribute("maxlength");

				this._delegate?.onAfterPaste?.(value);

				this._pasteInfo = null;
				if (isPasteOverflow) {
					this._onmaxlength();
				}
			});

		}

		private _onpaste(e: ClipboardEvent) {
			let clipboardData = e.clipboardData || window["clipboardData"];
			if (!clipboardData) {
				e.preventDefault();
				return;
			}
			this._pasteEvent(<HTMLInputElement>e.target, clipboardData.getData("text"), e);
		}
		private _ondragend(e: DragEvent) {
			if (this._dragData) {
				this._dragData = null;
			}
		}

		private _ondragstart(e: DragEvent) {
			let input = <HTMLInputElement>e.target;
			this._dragData = new foundation.InputObject(input.value, input.selectionStart, input.selectionEnd, foundation.InputLocation.drag);
		}
		private _ondrop(e: DragEvent) {
			let transferData = e.dataTransfer.getData("text");
			if (!transferData) {
				e.preventDefault();
				return;
			}

			let input = <HTMLInputElement>e.target;
			this._dropData = new foundation.InputObject(input.value, input.selectionStart, input.selectionEnd, foundation.InputLocation.drop);
			this._dropData.setData("transfer", this._transformDropText(transferData));
			if (this._getMaxLength() < 0) {
				return;
			}

			let value = this._computeDisplayText(input.value);
			let data = _getByteLength(this._getLengthUnit(), value, this._getMaxLength());
			let checkLength = data.byte;
			input.removeAttribute("maxlength");
			if ((this._getMaxLength() == 0 || this._getMaxLength() <= checkLength && this._owner.focused == false)) {
				e.preventDefault();
				return;
			}
			let canSelectionDrop = value == input.value;
			let ss = canSelectionDrop ? input.selectionStart : value.length;
			let se = canSelectionDrop ? input.selectionEnd : value.length;

			this._beforeInput = new foundation.InputObject(value, ss, se, foundation.InputLocation.drop);

			if (this._getMaxLength() <= checkLength) {
				input.setAttribute("maxlength", this._getMaxLength() + "");
			}
		}

		private _onblur(e: events.CUIEvent) {
			if (this._owner.getParent() instanceof cpr.controls.Grid) {
				let input = <HTMLInputElement>e.target;
				if (this._getMaxLength() > 0) {
					input.removeAttribute("maxlength");
				}
			}
		}

		public dispose() {
			this._owner = null;
		}
	}

	/**
	 * 인풋 계열 컴포넌트의 상위 클래스
	 */
	export abstract class TextEditor extends TextInput {

		protected _defaultSelection: { start: number, end: number, state: SelectionState } = { start: 0, end: 0, state: SelectionState.INIT };

		private _inputState = { compositionend: false }

		/**
		 * Control의 상태에 따라 Control의 Default Event Handler를 실행할 지 여부를 결정합니다.
		 * @param e 이벤트
		 * @return 컨트롤의 Event Handler 실행 여부.
		 */
		public confirmEvent(e: events.CEvent): boolean {
			if (super.confirmEvent(e) === false) {
				return false;
			}
			if (!e.nativeEvent) {
				return true;
			}
			//_checkControlStateForEvent은 shape내에 설정한 이벤트와 사용자 이벤트 등록 개수에 따라 호출이 2번 될 수 있음.
			let browser = utils.Util.detectBrowser();
			if (browser.name === "ie") {
				let allowLocales = ["ko", "ko-KR"]; //한글에서만 keyup이 두번 발생하는 버그. 일본어,중국어 IME에서는 정상 동작.
				//IE11 한글('ㄱ')입력 중에 엔터 입력 keydown->compositionend->compositionstart->keydown->keyup->keyup
				//IE11 한글('ㄱ')입력 중에 한글('ㄱ') 입력 keydown->compositionend->compositionstart->compositionupdate->input->keyup
				//IE11 전각문자 입력 keydown->compositionend->compositionstart->input->keyup
				if (e.type === "compositionstart" && allowLocales.indexOf(e.nativeEvent["locale"]) > -1) {
					this._inputState.compositionend = false; // 한글입력 후 전각 문자 입력 했을시 'ㄱ'->'１'
				} else if (e.type === "compositionupdate" && allowLocales.indexOf(e.nativeEvent["locale"]) > -1) {
					this._inputState.compositionend = false; // 한글 입력 후 한글 입력 했을시 'ㄱ'->'ㄱ'
				} else if (e.type === "compositionend" && allowLocales.indexOf(e.nativeEvent["locale"]) > -1) {
					if (/[ㄱ-힣]/.test(e["data"])) { //한글에서만 keyup과 keydown이 두번 발생하기 때문에 제한을 둔다.
						this._inputState.compositionend = true;
					}
				} else if (e.type === "blur") {
					this._inputState.compositionend = false;
				} else if (e.type === "keyup" && allowLocales.indexOf(e.nativeEvent["locale"]) > -1 && this._inputState.compositionend) {
					this._inputState.compositionend = false;
					if (browser.versionNumber == 11) {
						return false;//IE11 keyup 이벤트는 같은 키코드 두번 발생 버그. 크롬은 229와 키코드 발생.
					}
				}

			}

			return true;
		}

		/**
		 * mousedown 이벤트가 포함되어 있습니다. 같이 포함하여 사용하기 바랍니다.
		 */
		override _createTextEditor(): cpr.ufc.ControlShape {
			let shape = super._createTextEditor();
			shape.events["mousedown"] = this._onInputMousedown;
			return shape;
		}

		protected _onInputMousedown(e: MouseEvent) {
			this._defaultSelection.state = SelectionState.NONE;
		}

		/**
		 * 인풋상자의 선택 영역을 설정합니다.
		 * @param selectionStart 선택 영역 시작
		 * @param selectionEnd 선택 영역 끝
		 */
		public setSelectionRange(selectionStart: number, selectionEnd: number): void {
			let inputDom: HTMLInputElement = this._getRenderer().getNamedNode("text") as HTMLInputElement;
			if (inputDom == null) {
				return;
			}
			if (selectionStart < 0 || selectionEnd < 0) {
				throw new exceptions.IllegalArgumentException('selectionStart and selectionEnd must be greater or equals than 0.');
			}
			if (selectionStart > selectionEnd || selectionStart > inputDom.value.length) {
				selectionStart = selectionEnd;
			}
			super._focusImmediately();
			core.DeferredUpdateManager.INSTANCE._performFocusTask(() => {
				inputDom.setSelectionRange(selectionStart, selectionEnd);
			})
		}

		/**
		 * 인풋상자의 선택 영역 정보를 얻습니다.
		 * @returns 선택 영역
		 */
		public getSelectedRange(): { start: number, end: number } {
			let inputDom: HTMLInputElement = this._getRenderer().getNamedNode("text") as HTMLInputElement;

			let startIdx = inputDom.selectionStart;
			let endIdx = inputDom.selectionEnd;
			if (this.focused == false && this._defaultSelection.state == SelectionState.NONE) {
				startIdx = this._defaultSelection.start > startIdx ? this._defaultSelection.start : startIdx;
				endIdx = this._defaultSelection.end > endIdx ? this._defaultSelection.end : endIdx;
			}

			return {
				start: startIdx, end: endIdx
			};
		}

		/**
		 * 인풋상자의 선택 범위에 문자열을 교체하거나 삽입합니다.
		 * @param replacement 교체 또는 삽입할 문자열
		 * @param start 교체할 범위의 시작
		 * @param end 교체할 범위의 끝
		 */
		public setRangeText(replacement: string, start: number, end: number): void;
		/**
		 * 인풋상자의 선택 범위에 문자열을 교체하거나 삽입합니다.
		 * @param replacement 교체 또는 삽입할 문자열
		 * @param range 교체할 문자열 범위
		 */
		public setRangeText(replacement: string, range: { start: number, end: number }): void;
		public setRangeText(...args): void {
			let inputDom: HTMLInputElement = this._getRenderer().getNamedNode("text") as HTMLInputElement;
			if (inputDom == null) {
				return;
			}
			let value = inputDom.value;
			let textLength = value.length;
			let startIdx = inputDom.selectionStart;
			let endIdx = inputDom.selectionEnd;
			switch (args.length) {
				case 1: {
					let replacement = args[0] as string;
					if (typeof (replacement) != "string") {
						throw new exceptions.IllegalArgumentException('A replacement must be string.');
					}
					this._setSelectionText(startIdx, endIdx, value, replacement);
					break;
				}
				case 2: {
					let replacement = args[0] as string;
					let range = args[1] as { start: number, end: number };
					let start = range.start;
					let end = range.end;
					if (start < 0 || end < 0) {
						throw new exceptions.IllegalArgumentException('start and end must be greater or equals than 0.');
					}
					if (start > end) {
						throw new exceptions.IllegalArgumentException(`The provided start value ${range.start} is larger than the provided end value ${range.end}.`);
					}
					startIdx = textLength < start ? textLength : start;
					endIdx = textLength < end ? textLength : end;
					this._setSelectionText(startIdx, endIdx, value, replacement);
					break;
				}
				case 3: {
					let [replacement, start, end] = [args[0] as string, args[1] as number, args[2] as number];
					if (start < 0 || end < 0) {
						throw new exceptions.IllegalArgumentException('start and end must be greater or equals than 0.');
					}
					if (start > end) {
						throw new exceptions.IllegalArgumentException(`The provided start value ${start} is larger than the provided end value ${end}.`);
					}
					startIdx = textLength < start ? textLength : start;
					endIdx = textLength < end ? textLength : end;
					this._setSelectionText(startIdx, endIdx, value, replacement);
					break;
				}
				default: {
					throw new exceptions.IllegalArgumentException();
				}
			}
			inputDom.setSelectionRange(startIdx, endIdx);
			this._defaultSelection = { start: startIdx, end: endIdx, state: SelectionState.API }
			core.DeferredUpdateManager.INSTANCE._performFocusTask(() => {
				super._focusImmediately();
			})
		}

		/**
		 * 인풋상자의 선택 범위에 해당되는 텍스트를 반환합니다.
		 * @param range 선택 범위
		 */
		public getRangedText(range: { start: number, end: number }): string;
		/**
		 * 입력한 선택 범위에 해당되는 텍스트를 반환합니다.
		 * @param start 선택 범위 시작
		 * @param end 선택 범위 끝
		 */
		public getRangedText(start: number, end: number): string;
		public getRangedText(...args): string {
			let value = this._getDisplayText();

			let start = 0;
			let end = value.length - 1;
			if (this.focused == false && this._defaultSelection.state == SelectionState.NONE) {
				start = this._defaultSelection.start > start ? this._defaultSelection.start : start;
				end = this._defaultSelection.end > end ? this._defaultSelection.end : end;
			}

			let rangedText = "";
			switch (args.length) {
				case 1: {
					let range: { start: number, end: number } = args[0];
					rangedText = value.substring(range.start, range.end);
				}
					break;
				case 2: {
					let [startIdx, endIdx] = [args[0] as number, args[1] as number];
					rangedText = value.substring(startIdx, endIdx);
				}
					break;
				default:
					throw new exceptions.IllegalArgumentException();
			}
			return rangedText;
		}

		/**
		 * 설정한 선택 영역에 입력된 텍스트를 교체 또는 삽입하고 포커스가 이동됩니다.<br>
		 * <pre><code>
		 * editor.setSelection({start: 0, end: 8, text: "inputbox"});
		 * </code></pre>
		 * @param selection 선택 영역, 삽입 또는 교체할 텍스트
		 * @deprecated {@link setSelectionRange}, {@link setRangeText} API를 사용하시기 바립니다.2024.07.13 사용하지 않는 API입니다.
		 */
		public setSelection(selection: { start?: number, end?: number, text?: string }): void {
			let inputDom: HTMLInputElement = this._getRenderer().getNamedNode("text") as HTMLInputElement;
			if (inputDom == null) {
				return;
			}
			selection = _defaults(selection, { start: -1, end: -1, text: null });
			if (typeof (selection.start) != "number" || typeof (selection.end) != "number") {
				throw new exceptions.IllegalArgumentException();
			}
			let value = inputDom.value;
			let textLength = value.length;
			let startIdx: number, endIdx: number;
			let start = selection.start;
			let end = selection.end;
			let text = selection.text;
			if (start !== -1) {
				if (end !== -1) {
					startIdx = textLength < start ? textLength : start;
					endIdx = textLength < end ? textLength : end;
					if (text) {
						this._setSelectionText(start, end, value, text);
					}
				} else {
					throw new exceptions.IllegalArgumentException();
				}
			} else if (text) {
				if (end !== -1) {
					throw new exceptions.IllegalArgumentException();
				}
				startIdx = inputDom.selectionStart;
				endIdx = inputDom.selectionEnd;
				this._setSelectionText(inputDom.selectionStart, inputDom.selectionEnd, value, text);
			}

			inputDom.setSelectionRange(startIdx, endIdx); // safari에서 selectionStart또는 End를 변경 했을시 DOM으로 포커스 이벤트가 발생하여 setSelectionRange로 변경. 2018-09-19
			this._defaultSelection = { start: startIdx, end: endIdx, state: SelectionState.API };//safari가 DOM에 selection 변경했을때 focus 이벤트가 즉시 발생하여 DOM.selection 이전에 값을 설정. 2018-09-19
			core.DeferredUpdateManager.INSTANCE._performFocusTask(() => {
				super._focusImmediately();
			})
		}

		/**
		 * 선택 영역(start, end, text)을 반환합니다.<br>
		 * 선택 영역은 시작 위치, 종료 위치, 선택할 텍스트를 가진 정보를 나타냅니다.
		 * @return 선택 영역(start, end, text)의 정보.
		 * @deprecated {@link getSelectedRange}, {@link getRangedText} API를 사용하시기 바랍니다.
		 */
		public getSelection(): { start: number, end: number, text: string } {
			let inputDom: HTMLInputElement = this._getRenderer().getNamedNode("text") as HTMLInputElement;
			let value = this._getDisplayText();
			if (this.focused) {
				value = inputDom.value;
			}

			let start = inputDom.selectionStart;
			let end = inputDom.selectionEnd;
			if (this.focused == false && this._defaultSelection.state == SelectionState.NONE) {
				start = this._defaultSelection.start > start ? this._defaultSelection.start : start;
				end = this._defaultSelection.end > end ? this._defaultSelection.end : end;
			}
			let selectedText = value.substring(start, end);
			let result = { start: start, end: end, text: selectedText };

			return result;
		}

		protected _setSelectionText(start: number, end: number, text: string, insertText: string): void {
			let firstText = text.substr(0, start);
			let endText = text.substr(end, text.length);
			this._setValue(firstText + insertText + endText);
		}

		/**
		 * case 1 autoSelect = true일때 탭 또는 마우스로 포커스 줬을때 select 한다.
		 * case 2 focus()로 받는 것은 셀렉션이 유지된다.
		 * case 3 autoSelect = false일때 탭 또는 마우스로 포커스 줬을때 blur되었을때번째로 이동한다.
		 * @param input 
		 */
		protected _checkAutoSelect(input: HTMLInputElement | HTMLTextAreaElement, autoSelect: boolean) {
			if (input == null) {
				return;
			}
			let selection = this._getDefaultSelection();
			if (autoSelect && this._defaultSelection.state == SelectionState.INIT) {
				this._defaultSelection.state = SelectionState.NONE;
			}
			if (this._defaultSelection.state == SelectionState.INIT || this._defaultSelection.state == SelectionState.API) {
				if (input.selectionStart != selection.start || input.selectionEnd != selection.end) {
					input.setSelectionRange(selection.start, selection.end);
				}
			} else {
				if (autoSelect) {
					input.select();
				} else if (input.selectionEnd - input.selectionStart > 0) {
					input.setSelectionRange(selection.start, selection.end);
				} else if (this._useForceSelection()) {
					input.setSelectionRange(selection.start, selection.end);
				}
			}
		}

		protected _useForceSelection() {
			return false;
		}

		protected _getDefaultSelection() {
			let value = this._getValue();
			if (value != "" && this._defaultSelection.state == SelectionState.INIT) {
				this._defaultSelection.start = value.length;
				this._defaultSelection.end = value.length;
			}
			return { start: this._defaultSelection.start, end: this._defaultSelection.end }
		}

	}

}