/// <reference path="./IGridCellRenderer.ts"/>


namespace cpr.controls.gridpart.renderer {


	/**
	 * @private
	 */
	export class EmbeddedCellRendererFactory {
		private static _instance = new EmbeddedCellRendererFactory();
		public static _builtinClass: string = "cl-builtin";


		public static _isAccept(detailcellprop: GridDetailCellProp): boolean {
			if (detailcellprop && detailcellprop.configuration.columnType && ["rowindex", "checkbox", "radio"].indexOf(detailcellprop.configuration.columnType) != -1) {
				return true;
			}
			return false;
		}

		public static _getRenderer(columntype: string): (grid: Grid, rowIndex: number, cellProp: GridDetailCellProp, option: IRenderOption) => ufc.ControlShape {
			let flyweight: (grid: Grid, rowIndex: number, cellProp: GridDetailCellProp, option: IRenderOption) => ufc.ControlShape = null;
			switch (columntype) {
				case "rowindex": {
					flyweight = EmbeddedCellRendererFactory._instance._renderRowIndex;
					break;
				}
				case "checkbox": {
					flyweight = EmbeddedCellRendererFactory._instance._renderCheckBox;
					break;
				}
				case "radio": {
					flyweight = EmbeddedCellRendererFactory._instance._renderRadio;
					break;
				}
				default: {
					flyweight = null;
				}
			}
			return flyweight;
		}

		private _renderRowIndex(grid: Grid, rowIndex: number, cellProp: GridDetailCellProp, option: IRenderOption): ufc.ControlShape {
			let cellVisible: boolean = cellProp.configuration.visible;
			let value: string = (rowIndex === -1) ? "" : "" + (rowIndex + grid.rowIndexerStartNum);
			let controlShape: ufc.ControlShape = CellRendererFactory._getRawTextCellShape(value, option);
			if (controlShape.classNames == null) {
				controlShape.classNames = [];
			}
			controlShape.classNames.push("cl-rowindex");
			controlShape.classNames.push(EmbeddedCellRendererFactory._builtinClass);

			if (cellVisible === false) {
				controlShape.style["display"] = "none";
			}
			return controlShape;
		}

		private _renderCheckBox(grid: Grid, rowIndex: number, cellProp: GridDetailCellProp, option: IRenderOption): ufc.ControlShape {
			// let checkRowIndices: number[] = grid.getCheckRowIndices();
			let gridRow: provider.GridRow = grid.getRow(rowIndex);
			let checked: boolean = (gridRow != null) ? gridRow.rowChecked : false;
			let rowEnabled: boolean = (gridRow != null) ? gridRow.rowCheckEnabled : true;
			let rowVisible: boolean = (gridRow != null) ? gridRow.rowCheckVisible : true;
			let cellEnabled: boolean = cellProp.configuration.enabled;
			let cellVisible: boolean = cellProp.configuration.visible;
			let nodename: string = "r" + rowIndex + ".c" + cellProp.constraint.cellIndex;

			let iconShape: ufc.ElementShape = {
				tag: "div",
				classNames: [GridStyle.CHECKBOXICON],
				attr: {
					tabindex: "0",
					role: "checkbox",
					"data-role": "checkbox",
					// "aria-label": ariaLabel
				},
				style: {
					"vertical-align": "inherit",
					// cursor: "pointer"
				}
			};
			cpr.ufc.ShapeUtil._setAriaDisabled(iconShape, grid.enabled && rowEnabled && cellEnabled);
			GridUtil._setAria(iconShape, "checked", (checked) ? "true" : "false");
			if (utils.Util.isNullOrEmpty(option.ariaLabel) == false) {
				cpr.ufc.ShapeUtil._setAriaLabelAttr(iconShape.attr, option.ariaLabel);
			}

			let iconWrapper: ufc.ElementShape = {
				tag: "div",
				classNames: ["cl-icon-wrapper"],
				style: {
					display: "table-cell",
					"vertical-align": "inherit",
					"text-align": "inherit"
				},
				children: [iconShape]
			};
			let layout: ufc.ElementShape = {
				tag: "div",
				style: {
					display: "inline-table",
					height: "100%",
					"vertical-align": "inherit",
					"text-align": "inherit"
				},
				children: [iconWrapper]
			};

			let classNames: string[] = [GridStyle.CONTROL, GridStyle.CHECKBOX, EmbeddedCellRendererFactory._builtinClass, GridContext.CLS_CTRL_INHERIT];
			if (checked) {
				classNames.push(ufc.Classes.CHECKED);
			}
			if (grid.enabled == false || rowEnabled == false || cellEnabled == false) {
				classNames.push(ufc.Classes.DISABLED);
			}

			let shape: cpr.ufc.ControlShape = {
				tag: "div",
				attr: {
					// tabindex: "0"
				},
				classNames: classNames,
				style: {
					maxHeight: option.maxHeight + "px",
					height: "100%",
					width: "100%"
				},
				events: {
					mousedown: (e: events.CMouseEvent) => {
						// e.stopPropagation();
					},
					click: (e: events.CMouseEvent) => {
						if (e && _getProperty(grid, "enabled", true) !== false && _getProperty(grid, "visible", true) !== false) {
							EmbeddedCellRendererFactory._instance._handlerCheckboxToggleCheck(e, grid, nodename, rowIndex, cellProp, option);
							// Grid cell-click 이벤트 전파를 위해 해당코드를 주석처리합니다. (181101)
							// e.stopPropagation();
						}
					},
					keydown: (e: events.CKeyboardEvent) => {
						if (e && _getProperty(grid, "enabled", true) !== false && _getProperty(grid, "visible", true) !== false) {
							if (e.keyCode == events.KeyCode.SPACE) {
								EmbeddedCellRendererFactory._instance._handlerCheckboxToggleCheck(e, grid, nodename, rowIndex, cellProp, option);
							}
						}
					}
				},
				nodename: nodename,
				children: [layout]
			};
			if (rowVisible == false || cellVisible === false) {
				shape.style["display"] = "none";
			}

			return shape;
		}

		private _renderRadio(grid: Grid, rowIndex: number, cellProp: GridDetailCellProp, option: IRenderOption): ufc.ControlShape {
			// let checkRowIndices: number[] = grid.getCheckRowIndices();
			let gridRow: provider.GridRow = grid.getRow(rowIndex);
			let checked: boolean = (gridRow != null) ? gridRow.rowRadioSelected : false;
			let rowEnabled: boolean = (gridRow != null) ? gridRow.rowRadioEnabled : true;
			let rowVisible: boolean = (gridRow != null) ? gridRow.rowRadioVisible : true;
			let cellEnabled: boolean = cellProp.configuration.enabled;
			let cellVisible: boolean = cellProp.configuration.visible;
			let nodename: string = "r" + rowIndex + ".c" + cellProp.constraint.cellIndex;

			// let ariaLabel: string[] = [];
			// if (grid._isAriaLabelCellPosition()) {
			// 	ariaLabel[ariaLabel.length] = "" + option.ariaRowIndex + I18N.INSTANCE.message(core.PlatformTerms.ROW);
			// 	ariaLabel[ariaLabel.length] = "" + option.ariaColIndex + I18N.INSTANCE.message(core.PlatformTerms.COLUMN);
			// }
			// if (checked) {
			// 	ariaLabel[ariaLabel.length] = "" + (rowIndex + grid.rowIndexerStartNum) + I18N.INSTANCE.message(core.PlatformTerms.ROW_CHECKED);
			// } else {
			// 	ariaLabel[ariaLabel.length] = "" + (rowIndex + grid.rowIndexerStartNum) + I18N.INSTANCE.message(core.PlatformTerms.ROW_CHECK);
			// }
			// let ariaLabel: string = GridUtil._getAriaLabel(grid, cellProp, gridRow, option.ariaRowIndex, option.ariaColIndex, null, null);

			let iconShape: ufc.ElementShape = {
				tag: "div",
				classNames: [GridStyle.RADIOBUTTONICON],
				attr: {
					tabindex: "0",
					role: "radio",
					"data-role": "radio"
					// "aria-label": ariaLabel
				},
				style: {
					// display: "block",
					"vertical-align": "inherit",
					// cursor: "pointer"
				}
			};
			cpr.ufc.ShapeUtil._setAriaDisabled(iconShape, grid.enabled && rowEnabled && cellEnabled);
			GridUtil._setAria(iconShape, "checked", (checked) ? "true" : "false");
			if (utils.Util.isNullOrEmpty(option.ariaLabel) == false) {
				cpr.ufc.ShapeUtil._setAriaLabelAttr(iconShape.attr, option.ariaLabel);
			}

			let iconWraaper: ufc.ElementShape = {
				tag: "div",
				classNames: ["cl-icon-wrapper"],
				style: {
					display: "table-cell",
					"vertical-align": "inherit",
					"text-align": "inherit"
				},
				children: [iconShape],
			};
			let layout: ufc.ElementShape = {
				tag: "div",
				style: {
					display: "inline-table",
					height: "100%",
					"vertical-align": "inherit",
					"text-align": "inherit"
				},
				children: [iconWraaper]
			};

			let itemClassNames: string[] = [GridStyle.RADIOBUTTONITEM];
			if (checked) {
				itemClassNames.push(ufc.Classes.SELECTED);
			}
			let radioItem: ufc.ElementShape = {
				tag: "div",
				classNames: itemClassNames,
				style: {
					height: "100%",
					width: "100%"
				},
				children: [layout]
			};

			let classNames: string[] = [GridStyle.CONTROL, GridStyle.RADIOBUTTON, EmbeddedCellRendererFactory._builtinClass, GridContext.CLS_CTRL_INHERIT];
			if (grid.enabled == false || rowEnabled == false || cellEnabled == false) {
				classNames.push(ufc.Classes.DISABLED);
			}

			let shape: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: classNames,
				attr: {
					// tabindex: "0"
				},
				style: {
					maxHeight: option.maxHeight + "px",
					height: "100%",
					width: "100%"
				},
				events: {
					mousedown: (e: events.CMouseEvent) => {
						// e.stopPropagation();
					},
					click: (e: events.CMouseEvent) => {
						if (e && _getProperty(grid, "enabled", true) !== false && _getProperty(grid, "visible", true) !== false) {
							EmbeddedCellRendererFactory._instance._handlerRadioToggleCheck(e, grid, nodename, rowIndex, cellProp, option);
							// Grid cell-click 이벤트 전파를 위해 해당코드를 주석처리합니다. (181101)
							// e.stopPropagation();
						}
					},
					keydown: (e: events.CKeyboardEvent) => {
						if (e && _getProperty(grid, "enabled", true) !== false && _getProperty(grid, "visible", true) !== false) {
							if (e.keyCode == events.KeyCode.SPACE) {
								EmbeddedCellRendererFactory._instance._handlerRadioToggleCheck(e, grid, nodename, rowIndex, cellProp, option);
							}
						}
					}
				},
				nodename: nodename,
				children: [radioItem]
			};
			if (rowVisible == false || cellVisible === false) {
				shape.style["display"] = "none";
			}

			return shape;
		}

		private _handlerCheckboxToggleCheck(e: (events.CMouseEvent | events.CKeyboardEvent), grid: Grid, nodename: string, rowIndex: number, cellProp: GridDetailCellProp, option: IRenderOption): void {
			let enabled: boolean = grid.isEnabledTypedCell("checkbox", rowIndex);
			if (enabled == false) {
				return;
			}

			grid._keepContentDataRowIndex();
			grid._setContentDataRowIndex(rowIndex, -1);
			let cellEnabled: boolean = cellProp.configuration.enabled;
			grid._restoreContentDataRowIndex();
			if (cellEnabled === false) {
				return;
			}

			let checked: boolean = grid._toggleCheckRowIndex(rowIndex);

			let details: gridpart.GridDetail[] = grid._getContainDetails([rowIndex], false);
			details.forEach(item => grid._applyPiece(item));

			// GRID Event Dispatch
			let eventObj: events.CGridEvent = new events.CGridEvent(checked ? events.GridEventType.ROW_CHECK : events.GridEventType.ROW_UNCHECK, {
				relativeTargetName: "detail",
				row: grid.dataProvider.getRow(rowIndex),
				rowIndex: rowIndex
			});
			eventObj.nativeEvent = e;
			grid.dispatchEvent(eventObj);
		}

		private _handlerRadioToggleCheck(e: (events.CMouseEvent | events.CKeyboardEvent), grid: Grid, nodename: string, rowIndex: number, cellProp: GridDetailCellProp, option: IRenderOption): void {
			let enabled: boolean = grid.isEnabledTypedCell("radio", rowIndex);
			if (enabled == false) {
				return;
			}

			grid._keepContentDataRowIndex();
			grid._setContentDataRowIndex(rowIndex, -1);
			let cellEnabled: boolean = cellProp.configuration.enabled;
			grid._restoreContentDataRowIndex();
			if (cellEnabled === false) {
				return;
			}

			let beforeSelected: boolean = grid.isRadioSelected(rowIndex);
			grid.selectRadio(rowIndex);

			if (beforeSelected == false) {
				let details: gridpart.GridDetail[] = grid._getContainDetails([rowIndex], false);
				details.forEach(item => grid._applyPiece(item));
			}
		}

	}


	/**
	 * @private
	 */
	export class EmbeddedCellRenderer extends AbstractGridCellRenderer {
		private _cellRenderer: (grid: Grid, rowindex: number, cellprop: GridCellProp, option: IRenderOption) => ufc.ControlShape;


		public static _isAccept(detailcellprop: GridDetailCellProp): boolean {
			return EmbeddedCellRendererFactory._isAccept(detailcellprop);
		}

		constructor(cellprop: GridCellProp /* GridDetailCellProp */, grid: Grid) {
			super(cellprop, grid);
		}

		protected _init(): void {
			this._cellRenderer = EmbeddedCellRendererFactory._getRenderer((this.prop as GridDetailCellProp).configuration.columnType);
		}

		public createCellShape(gridData: provider.GridRow | provider.GridRowGroup, option: IRenderOption): ufc.ControlShape {
			let gridRow: provider.GridRow = gridData as provider.GridRow;

			let controlShape: ufc.ControlShape = this._cellRenderer(this.grid, gridRow.getIndex(), this.prop, option);

			return controlShape;
		}
	}
}