/// <reference path="./AccessableUIControl.ts" />
/// <reference path="./provider/DataBindable.ts"/>

namespace cpr.controls {
	/**
	 * 아이콘 위치의 값
	 */
	export enum IconAlign {
		/**
		 * 아이콘을 왼쪽으로 표시합니다.
		 */
		left = "left",
		/**
		 * 아이콘을 오른쪽으로 표시합니다.
		 */
		right = "right",
		/**
		 * 아이콘을 위쪽으로 표시합니다.
		 */
		top = "top",
		/**
		 * 아이콘을 아래쪽으로 표시합니다.
		 */
		bottom = "bottom"
	}

	/**
	 * Checkbox
	 * 박스 내의 선택되거나 선택되지 않은 상태를 토글하면서 체크를 표현하는 컨트롤.
	 * 
	 * @firesgroup mouse
	 * @firesgroup contextmenu
	 * @firesgroup bindcontext
	 * @firesgroup keyboard
	 * @firesgroup focus
	 * @firesgroup drop
	 * 
	 * @fires cpr.events.CValueChangeEvent#before-value-change CheckBox의 value를 변경하여 변경된 값이 저장되기 전에 발생하는 이벤트.
	 * 		다음 이벤트로 value-change가 발생합니다.
	 * 		<pre>oldValue: {string} 이전 값</pre>
	 * 		<pre>newValue: {string} 현재 값</pre>
	 * 
	 * @fires cpr.events.CValueChangeEvent#value-change CheckBox의 value를 변경하여 변경된 값이 저장된 후에 발생하는 이벤트.
	 * 		<pre>oldValue: {string} 이전 값</pre>
	 * 		<pre>newValue: {string} 현재 값</pre>
	 */
	export class CheckBox extends AccessableUIControl implements provider.ValueBindable, gridpart.IGridParticipant {
		private static readonly _AVAILABLE_PROP: string[] = [
			"falseValue", "trueValue", "text", "value", "iconAlign", "fixedWidth", "hideIcon", "clickRegion"
		];

		private _binder: provider.ValueBinder;
		private _fixedWidth: boolean;
		private _preventFocus: boolean = false;
		private _clickRegion: ClickRegion = ClickRegion.TEXT_FIELD;

		/**
		 * 체크박스를 생성합니다.
		 * @param id 체크박스의 id
		 */
		constructor(id?: string) {
			super(id);
			this._binder = new provider.ValueBinder(this);
			this._fixedWidth = false;

			this._addBindableProperty("hideIcon", false).withSetterValidatorWithType(false, "boolean");
			this._addBindableProperty("iconAlign", "left").withSetterValidatorWithType(false, "string");
			this._addBindableProperty("text", "")
				.withSetterTransformer(it => {
					if (it == null) {
						return null;
					} else if (typeof it === "string") {
						return it;
					} else {
						return String(it);
					}
				})
				.withGetterTransformer(it => {
					if (it == null) {
						return null;
					} else if (it instanceof ufc.StyledString) {
						return it;
					} else {
						return String(it);
					}
				})
			this._addBindableProperty("trueValue", "true")
				.withSetterTransformer(it => {
					if (it == null) {
						return null;
					} else if (typeof it === "string") {
						return it;
					} else {
						return String(it);
					}
				})
				.withGetterTransformer(it => {
					if (it == null) {
						return null;
					} else {
						return String(it)
					}
				})

			this._addBindableProperty("falseValue", "")
				.withSetterTransformer(it => {
					if (it == null) {
						return null;
					} else if (typeof it === "string") {
						return it;
					} else {
						return String(it);
					}
				})
				.withGetterTransformer(it => {
					if (it == null) {
						return null;
					} else {
						return String(it)
					}
				})

			// 사용자 click 이벤트에서 preventDefault를 통해 기본동작을 막기 위하여 _addInternalEventListener로 이벤트 추가
			this._addInternalEventListener("click", this._onClick);

			// control initializing
			this._initControl();
		}

		public override _getType(): ControlType {
			return ControlType.CHECKBOX;
		}
		public override _getLabelableType(): LabelableType {
			return LabelableType.div;
		}

		protected override _getStylerSpec(): UIControlStylerSpec {
			return {
				root: { baseClass: "cl-checkbox" },
				field: { baseClass: "cl-checkbox-field" },
				icon: { baseClass: "cl-checkbox-icon" }
			};
		}

		protected override _isConfigurableProperty(propName: string): boolean {
			if (CheckBox._AVAILABLE_PROP.indexOf(propName) != -1) {
				return true;
			}
			return super._isConfigurableProperty(propName);
		}

		/**
		 * 자동 크기 지원 타입을 얻습니다.
		 * 만일 both를 리턴했다면, css height, width 속성에 auto를 사용할 수 있음을 나타냅니다.
		 */
		public _getAutoSizeAvailability(): layouts.AutoSizeType {
			return layouts.AutoSizeType.both;
		}

		public _convertGridPasteText(text: string): string {
			if (text != null && (text == this.trueValue || text == this.falseValue)) {
				return text;
			}
			return null;
		}
		public _getGridViewingText(): string {
			return this.value;
		}
		public _renderGridCellShape(grid: Grid, data: (string | ufc.StyledString), option: gridpart.renderer.IRenderOption): ufc.ControlShape {
			let checked: boolean = this.checked;

			let checkboxShape: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: ["cl-control", "cl-checkbox"],
				attr: {},
				style: { overflow: "hidden" }
			};
			if (option.maxHeight >= 0) {
				checkboxShape.style["height"] = option.maxHeight + "px";
			}
			if (checked) {
				checkboxShape.classNames.push(ufc.Classes.CHECKED);
			}
			if (this.hideIcon == true) {
				checkboxShape.classNames.push("cl-iconalign-none");
			} else if (this.iconAlign == IconAlign.right) {
				checkboxShape.classNames.push("cl-iconalign-right");
			} else if (this.iconAlign == IconAlign.top) {
				checkboxShape.classNames.push("cl-iconalign-top");
			} else if (this.iconAlign == IconAlign.bottom) {
				checkboxShape.classNames.push("cl-iconalign-bottom");
			}
			if (this.fixedWidth == true) {
				checkboxShape.classNames.push("cl-fixedWidth");
			}

			// hidetext 처리
			if (option.hidetext == false) {
				let layout: ufc.ElementShape = {
					tag: "div",
					classNames: ["cl-checkbox-field"],
					attr: {
						"data-region": "field"
					},
					style: {
						display: "inline-table",
						"vertical-align": "inherit",
						"text-align": "inherit"
					},
					children: []
				};
				if (this.fixedWidth == true) {
					layout.style["width"] = "100%"
					layout.style["table-layout"] = "fixed";
				}
				gridpart.GridUtil._applyControlStyler(layout, this.style["field"], null);// icon styler apply point

				if (this.hideIcon == false) { // createInput start
					let iconShape: cpr.ufc.ElementShape = {
						tag: "div",
						classNames: ["cl-checkbox-icon"],
						attr: {
							role: "checkbox",
							// hidefocus: "false",
							tabindex: "0",
							"data-role": "checkbox"
						},
						style: {
							"vertical-align": "inherit"
						},
						children: []
					};
					// FIXME : 검토 필요 (#9064)
					if (this.fieldLabel != null && this.fieldLabel != "") {
						cpr.ufc.ShapeUtil._setAriaLabelAttr(iconShape.attr, this.fieldLabel);
					} else if (this.text != null && this.text != "") {
						cpr.ufc.ShapeUtil._setAriaLabelAttr(iconShape.attr, this.text);
					}
					gridpart.GridUtil._applyControlStyler(iconShape, this.style["icon"], null);// icon styler apply point
					if (!this.enabled) {
						delete iconShape.attr['tabindex'];
					}
					cpr.ufc.ShapeUtil._setAriaDisabled(iconShape, this.enabled && !this.readOnly);
					gridpart.GridUtil._setAria(iconShape, "checked", (checked) ? "true" : "false");

					let iconWrapperShape: ufc.ElementShape = {
						tag: "div",
						classNames: ["cl-icon-wrapper"],
						style: {
							display: "table-cell"
						},
						children: [iconShape]
					}

					if (this.iconAlign == IconAlign.top || this.iconAlign == IconAlign.bottom) {
						iconShape.style["display"] = "inline-block";
						let wrapperShape: ufc.ElementShape = {
							tag: "div",
							style: {
								display: "table-row",
								"vertical-align": "inherit"
							},
							children: [iconWrapperShape]
						}
						iconWrapperShape = wrapperShape;
					}

					layout.children.push(iconWrapperShape);
				} // createInput end

				let text: string | ufc.StyledString = this._getText();
				if (text instanceof ufc.StyledString || (typeof (text) == "string" && text != null && text != "")) { // createLabel start
					let textShape: (string | ufc.ElementShape)[] = ufc.StyledString._asShape(this._getText());
					let labelShape: ufc.ElementShape = {
						tag: "div",
						classNames: [ufc.Classes.UNSELECTABLE, ufc.Classes.TEXT],
						attr: {
							"data-role": "text"
						},
						style: {
							display: "table-cell",
							"vertical-align": "inherit"
						},
						children: textShape
					}

					if (this.hideIcon == true) {
						labelShape.attr["role"] = "checkbox";
						// labelShape.attr["hidefocus"] = "false";
						labelShape.attr["data-role"] = "checkbox";
						gridpart.GridUtil._setAria(labelShape, "checked", (checked) ? "true" : "false");
						// FIXME : 검토 필요 (#9064)
						if (this.fieldLabel != null && this.fieldLabel != "") {
							cpr.ufc.ShapeUtil._setAriaLabelAttr(labelShape.attr, this.fieldLabel);
						} else if (this.text != null && this.text != "") {
							cpr.ufc.ShapeUtil._setAriaLabelAttr(labelShape.attr, this.text);
						}
						if (this.enabled) {
							labelShape.attr["tabindex"] = "0";
						}
						cpr.ufc.ShapeUtil._setAriaDisabled(labelShape, this.enabled && !this.readOnly);
					}

					if (this.iconAlign == IconAlign.top || this.iconAlign == IconAlign.bottom) {
						let labelWrapperShape: ufc.ElementShape = {
							tag: "div",
							style: {
								display: "table-row",
								"vertical-align": "inherit"
							},
							children: [labelShape],
						}
						labelShape = labelWrapperShape;
					}

					layout.children.push(labelShape);
				} // createLabel end

				if (this.iconAlign == IconAlign.right || this.iconAlign == IconAlign.bottom) {
					layout.children.reverse();
				}

				let layoutWrapper: ufc.ElementShape = {
					tag: "div",
					style: {
						display: "table",
						width: "100%",
						height: "100%",
						"vertical-align": "inherit",
						"text-align": "inherit"
					},
					children: [{
						tag: "div",
						style: {
							display: "table-cell",
							"vertical-align": "inherit",
							"text-align": "inherit"
						},
						children: [layout]
					}]
				};

				checkboxShape.children = [layoutWrapper];
			}

			return checkboxShape;
		}

		public override _valueDidChange(name: string, oldValue: any, newValue: any) {
			super._valueDidChange(name, oldValue, newValue);
			this._binder._valueDidChange(name, oldValue, newValue);
			switch (name) {
				case "falseValue": {
					if (this.checked == false && oldValue == "")
						this.value = newValue;
				}
				case "hideIcon":
				case "iconAlign":
				case "trueValue":
				case "text": {
					this.redraw();
					break;
				}
			}
		}

		// property 

		protected override _isEditable(): boolean {
			return (this.isAvailableBinding("value") == true);
		}

		/// SimpleDataBindable Start ////////////////////////////////////////////
		/**
		 * 컨트롤의 값을 설정하고, value-change 이벤트가 발생됩니다.
		 * @param value 컨트롤의 값.
		 */
		public set value(value: string) {
			this._binder.setValue(value);
		}

		/**
		 * 컨트롤의 값을 반환합니다.
		 * @return 컨트롤의 값.
		 */
		public get value(): string {
			return this._binder.getValue();
		}

		/**
		 * 컨트롤의 값을 설정합니다.
		 * @param value 컨트롤의 값.
		 */
		public putValue(value: string) {
			this._binder.setValue(value, false);
		}

		/**
		 * checkbox의 텍스트를 반환합니다.
		 * @return 텍스트.
		 */
		get text(): string {
			return ufc.StyledString._asString(this._getText());
		}
		public _getText(): string | ufc.StyledString {
			return this._bindables.get("text");
		}

		/**
		 * checkbox의 텍스트를 설정합니다.
		 * @param newValue 텍스트.
		 */
		set text(newValue: string) {
			this._bindables.set("text", newValue);
			this.redraw()
		}

		/// SimpleDataBindable End ////////////////////////////////////////////////

		/**
		 * check 표시의 상태를 반환합니다.
		 * @return check 표시의 상태.
		 */
		get checked(): boolean {
			return this.trueValue == this.value;
		}

		/**
		 * check 상태를 설정합니다.
		 * @param checked check 표시의 상태.
		 */
		set checked(checked: boolean) {
			if (checked) {
				this.value = this.trueValue;
			} else
				this.value = this.falseValue;

			this.redraw();
		}

		/**
		 * checked 상태가 false 일 경우 가지는 값을 반환합니다.
		 * @return checked 상태가 false일 경우 가지는 값.
		 */
		get falseValue(): string {
			return this._bindables.get("falseValue");
		}

		/**
		 * checked 상태가 false 일 경우 가지는 값을 설정합니다.
		 * @param value checked 상태가 false일 경우 가지는 값.
		 */
		set falseValue(value: string) {
			this._bindables.set("falseValue", value);
		}

		/**
		 * checked 상태가 true 일 경우 가지는 값을 반환합니다.
		 * @return checked 상태가 true일 경우 가지는 값.
		 */
		get trueValue(): string {
			return this._bindables.get("trueValue");
		}

		/**
		 * checked 상태가 true 일 경우 가지는 값을 설정합니다.
		 * @param value checked 상태가 true 경우 가지는 값.
		 */
		set trueValue(value: string) {
			this._bindables.set("trueValue", value);
		}

		/**
		 * 아이콘의 정렬 위치를 반환합니다.
		 * @return 아이콘의 정렬 위치
		 */
		get iconAlign(): IconAlign {
			return this._bindables.get("iconAlign");
		}

		/**
		 * 아이콘의 정렬 위치를 설정합니다.
		 * @param iconAlign 아이콘의 정렬 위치
		 */
		set iconAlign(iconAlign: IconAlign) {
			this._bindables.set("iconAlign", iconAlign);
			this.redraw();
		}

		/**
		 * 아이템의 넓이를 고정할지를 여부를 반환합니다.
		 * @return 아이템의 넓이를 고정할지를 여부. 혹은 고정 너비 상수.
		 */
		get fixedWidth(): boolean {
			return this._fixedWidth;
		}

		/**
		 * 아이템의 넓이를 고정할지를 여부를 설정합니다.
		 * ellipsis 스타일을 적용하기 위해서는 fixedWidth 속성을 true로 설정해야 합니다.
		 * 고정 너비로 설정한 경우 아이콘을 제외한 텍스트 영역만 정렬됩니다. (text-align)
		 * @param fixedwidth 아이템의 넓이를 고정할지를 여부.
		 */
		set fixedWidth(fixedwidth: boolean) {
			this._fixedWidth = fixedwidth;
			this.redraw();
		}

		/**
		 * 아이콘을 숨길지 여부를 반환합니다.
		 * @return 아이콘을 숨길지 여부.
		 */
		get hideIcon(): boolean {
			return this._bindables.get("hideIcon");
		}

		/**
		 * 아이콘을 숨길지 여부를 설정합니다.
		 * @param hideIcon 아이콘을 숨길지 여부.
		 */
		set hideIcon(hideIcon: boolean) {
			this._bindables.set("hideIcon", hideIcon);
			this.redraw();
		}

		/**
		 * 체크가 가능한 영역을 반환합니다.
		 * @return 선택 시 체크 가능한 영역.
		 */
		get clickRegion(): ClickRegion {
			return this._clickRegion;
		}

		/**
		 * 체크가 가능한 영역을 설정합니다.
		 * @param clickRegion 선택 시 체크 가능한 영역.
		 */
		set clickRegion(clickRegion: ClickRegion) {
			this._clickRegion = clickRegion;
		}

		public override _focusByAccessKey() {
			this.focus();

			if (this.readOnly == true || this.enabled == false) {
				return;
			}
			this.toggle();
		}

		public override _isFocusable(): boolean {
			if (this.hideIcon && utils.Util.isNullOrEmpty(this.text)) {
				return false;
			}
			return true;
		}

		// shape
		public override _createShape(): ufc.ControlShape {
			let fieldShape: ufc.ElementShape = {
				tag: "div",
				styler: "field",
				attr: {
					"data-region": "field"
				},
				style: {
					display: "inline-table",
					"vertical-align": "inherit",
					"text-align": "inherit"
				},
				children: []
			};

			if (this.hideIcon == false) {
				fieldShape.children.push(this._createInput());
			}
			let text: string | ufc.StyledString = this._getText();
			if (text instanceof ufc.StyledString || (typeof (text) == "string" && text != null && text != "")) {
				fieldShape.children.push(this._createLabel());
			}

			if (this.iconAlign == IconAlign.right || this.iconAlign == IconAlign.bottom) {
				fieldShape.children.reverse();
			}

			if (this.fixedWidth == true) {
				fieldShape.style["width"] = "100%"
				fieldShape.style["table-layout"] = "fixed";
			}

			// vertical-align을 위한 div
			let layoutWrapper: ufc.ElementShape = {
				tag: "div",
				attr: {},
				style: {
					display: "table",
					width: "100%",
					height: "100%",
					"vertical-align": "inherit",
					"text-align": "inherit"
				},
				children: [{
					tag: "div",
					style: {
						display: "table-cell",
						height: "100%",
						"vertical-align": "inherit",
						"text-align": "inherit"
					},
					children: [fieldShape]
				}]
			};

			let shape: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: [],
				styler: "root",
				attr: {
					// tabindex: "-1" // 웹 접근성 상 체크박스 내 아이콘에 포커스가 바로 이동되어야 하므로 외곽 tabindex 제거
				},
				style: {
					overflow: "hidden"
				},
				eventTargets: [
					ufc.EventTargetType.UICONTROL,
					ufc.EventTargetType.DROPPABLE
				],
				events: {
					keydown: this._onKeydown,
					mousedown: this._onMousedown
				},
				children: [layoutWrapper]
			};

			if (this.checked) {
				shape.classNames.push(ufc.Classes.CHECKED);
			}

			// cpr.ufc.ShapeUtil._setAriaLabelAttr(shape.attr, this.fieldLabel);
			cpr.ufc.ShapeUtil._setTooltipAttr(shape, { owner: this, title: this.tooltip });
			if (this.hideIcon == true) {
				shape.classNames.push("cl-iconalign-none");
			} else if (this.iconAlign == IconAlign.right) {
				shape.classNames.push("cl-iconalign-right");
			} else if (this.iconAlign == IconAlign.top) {
				shape.classNames.push("cl-iconalign-top");
			} else if (this.iconAlign == IconAlign.bottom) {
				shape.classNames.push("cl-iconalign-bottom");
			}
			if (this.fixedWidth == true) {
				shape.classNames.push("cl-fixedWidth");
			}

			if (this.clickRegion == ClickRegion.ITEM) {
				shape.classNames.push("cl-clickregion-item");
			} else {
				shape.classNames.push("cl-clickregion-textfield");
			}

			return shape;
		}

		//checkbox 생성
		private _createInput(): cpr.ufc.ElementShape {
			let iconShape: cpr.ufc.ElementShape = {
				tag: "div",
				styler: "icon",
				classNames: [],
				attr: {
					role: "checkbox",
					// hidefocus: "false",
					tabindex: "0",
					"data-role": "checkbox",
					"aria-checked": (this.checked) ? "true" : "false"
				},
				style: {
					"vertical-align": "inherit"
				}
			};
			if (!this.enabled) {
				delete iconShape.attr['tabindex'];
			}
			cpr.ufc.ShapeUtil._setAriaDisabled(iconShape, this.enabled && !this.readOnly);
			let fieldLabel = this._getFieldLabel();
			// FIXME : 검토 필요 (#9064)
			if (fieldLabel != null && fieldLabel != "") {
				cpr.ufc.ShapeUtil._setAriaLabelAttr(iconShape.attr, fieldLabel);
			} else if (this.text != null && this.text != "") {
				cpr.ufc.ShapeUtil._setAriaLabelAttr(iconShape.attr, this.text);
			}

			let iconWrapperShape: ufc.ElementShape = {
				tag: "div",
				classNames: ["cl-icon-wrapper"],
				style: {
					display: "table-cell"
				},
				children: [iconShape]
			}

			if (this.hideIcon == false && (this.iconAlign == IconAlign.top || this.iconAlign == IconAlign.bottom)) {
				iconShape.style["display"] = "inline-block";
				let wrapperShape: ufc.ElementShape = {
					tag: "div",
					style: {
						display: "table-row",
						"vertical-align": "inherit"
					},
					children: [iconWrapperShape]
				}
				iconWrapperShape = wrapperShape;
			}

			return iconWrapperShape;
		}

		private _createLabel(): ufc.ElementShape {
			let text: (string | ufc.ElementShape)[] = ufc.StyledString._asShape(this._getText());
			let labelShape: ufc.ElementShape = {
				tag: "div",
				classNames: [ufc.Classes.UNSELECTABLE, ufc.Classes.TEXT],
				attr: {
					"data-role": "text"
				},
				style: {
					display: "table-cell",
					"vertical-align": "inherit"
				},
				children: text
			};
			if (this.hideIcon == true) {
				labelShape.attr["role"] = "checkbox";
				// labelShape.attr["hidefocus"] = "false";
				labelShape.attr["data-role"] = "checkbox";
				labelShape.attr["aria-checked"] = (this.checked) ? "true" : "false";
				// FIXME : 검토 필요 (#9064)
				let fieldLabel = this._getFieldLabel();
				if (fieldLabel != null && fieldLabel != "") {
					cpr.ufc.ShapeUtil._setAriaLabelAttr(labelShape.attr, fieldLabel);
				} else if (this.text != null && this.text != "") {
					cpr.ufc.ShapeUtil._setAriaLabelAttr(labelShape.attr, this.text);
				}
				if (this.enabled) {
					labelShape.attr["tabindex"] = "0";
				}
				cpr.ufc.ShapeUtil._setAriaDisabled(labelShape, this.enabled && !this.readOnly);
			}

			if (this.hideIcon == false && (this.iconAlign == IconAlign.top || this.iconAlign == IconAlign.bottom)) {
				let labelWrapperShape: ufc.ElementShape = {
					tag: "div",
					style: {
						display: "table-row",
						"vertical-align": "inherit"
					},
					children: [labelShape],
				}
				labelShape = labelWrapperShape;
			}

			return labelShape;
		}

		//////////////////////////////////////////////////////////////////////////////////////////////////
		// 이벤트 /////////////////////////////////////////////////////////////////////////////////////////
		//////////////////////////////////////////////////////////////////////////////////////////////////

		private _onKeydown(e: events.CKeyboardEvent): void {
			if (this.readOnly == true || this.enabled == false) {
				return;
			}
			if (this.getParent() instanceof cpr.controls.Grid && e._getMod1Key()) {
				return;
			}
			let keyCode: number = e.keyCode;

			if (keyCode == events.KeyCode.SPACE) {
				this.toggle();
				e.preventDefault();
			}
		}

		private _onMousedown(e: events.CMouseEvent): void {
			this._preventFocus = e.defaultPrevented;
		}

		//컨트롤의 변화 시 checked 상태 저장
		private _onClick(e: events.CEvent): void {
			if (!this.enabled || this.readOnly) {
				return;
			}
			let rootElement: HTMLElement = e.currentTarget as HTMLElement;
			let eventTarget: HTMLElement = e.target as HTMLElement;
			if (eventTarget == null) {
				return;
			}

			if (this._preventFocus == false) {
				let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(rootElement);
				domTraverser = domTraverser._child("[data-role='checkbox']");
				if (domTraverser != null) {
					domTraverser._focus().dispose();
				}
			}

			if (this.getParent() instanceof cpr.controls.Grid) {
				this.toggle();
			} else {
				let fieldDomTraverser: ufc.DOMTraverser = ufc._traverseFromElement(eventTarget);
				fieldDomTraverser = fieldDomTraverser._closest('[data-role="checkbox"], [data-role="text"]');
				if (fieldDomTraverser == null && this._clickRegion == ClickRegion.TEXT_FIELD) {
					return;
				}
				this.toggle();
			}
		}

		public _exportValue(): string | number {
			return (this.value != null) ? "" + this.value : "";
		}

		//////////////////////////////////////////////////////////////////////////////////////////////////
		// API ///////////////////////////////////////////////////////////////////////////////////////////
		//////////////////////////////////////////////////////////////////////////////////////////////////

		/**
		 * checkbox의 checked 값을 반대의 값으로 전환하여 반환합니다.<br>
		 * 두가지 밖에 없는 상황에서 반대의 값으로 설정합니다.
		 * @return 전환된 checked 값.
		 */
		public toggle(): boolean {
			let newValue = !this.checked;
			this.checked = newValue;
			return newValue;
		}
	}
}