

namespace cpr.controls.gridpart.renderer {
	/**
	 * @private
	 */
	export class GridRowGroupRenderer {
		private _context: GridContext;
		private _layout: GridRowGroupBandConfig;


		constructor(context: GridContext, layout: GridRowGroupBandConfig) {
			this._context = context;
			this._layout = layout;
		}

		@hostCacheRealm("redraw-grid-row")
		public _createShape(gridRowGroup: provider.GridRowGroup, rowIndex: number,
			cellPositionRange: { start: number, end: number }, regionColWidth: { width: number }[],
			grouptype: string, rowHeight: number, rowTopPosition: number,
			suppressModel: layout.SuppressCellInfo[], isMergedSuppress: boolean, shapeKeyIdx: number): ufc.ElementShape[] {

			let grid: Grid = this._context.getGrid();
			let visibleColIndices: number[] = grid.getColIndicesByVisible(true);
			let collapseIndex: number = -1;
			let conditions: { [key: string]: string } = gridRowGroup._getOption("conditions");
			let groupCondition: string = null;
			if (this._context.collapsible == true && grouptype == "gheader" && conditions != null) {
				groupCondition = Object.keys(conditions).join(",");
				collapseIndex = this._context._getCollapseIndex(groupCondition);
			}
			let classNames: string[] = [GridStyle.ROW];
			let styler: string = null;
			if (grouptype == "gheader") {
				classNames.push("cl-rowgroup-header");
				styler = "gheader";
			} else if (grouptype == "gfooter") {
				classNames.push("cl-rowgroup-footer");
				styler = "gfooter";
			}
			if (rowIndex == 0) {
				classNames.push(ufc.Classes.FIRST_ROW);
			}
			if (rowIndex == grid.getContentRowCount() - 1) {
				classNames.push(ufc.Classes.LAST_ROW);
			}

			let rowShape: ufc.ElementShape = {
				tag: "div",
				styler: styler,
				// stylerBindContext: new bind.GridEmbeddedContext(this._context.getGrid(), gridRowGroup.startRowIndex, rowIndex),
				bindContext: new bind.GridEmbeddedContext(this._context.getGrid(), gridRowGroup.startRowIndex, rowIndex),
				attr: {
					role: GRIDROLE.ROW,
					"data-vrowindex": "" + rowIndex,
					"data-region": grouptype
				},
				key: "ri" + shapeKeyIdx,
				classNames: _.union(classNames, [GridContext.CLS_CELL_INHERIT], this._layout.bandStyler.getClasses()),
				style: _defaults({
					position: "absolute",
					top: rowTopPosition + "px",
					left: "0",
					height: rowHeight + "px",
					width: "100%"
				}, this._layout.bandStyler.css()),
				children: []
			};
			if (groupCondition != null) {
				rowShape.attr["data-groupcondition"] = groupCondition;
			}
			GridUtil._setAria(rowShape, "rowindex", utils.Util.toString(rowIndex + grid.header.getRowHeights().length + 1));

			let heights: number[] = [];
			this._layout.rows.forEach((rowInfo: { rowIndex: number, height: number }) => {
				heights.push(rowInfo.height);
			});

			this._layout.cellProp.forEach((colProp: GridFooterCellProp) => {
				let cellLayout: { visible: boolean, colSpan: number } = this._context._getVisibleColumn(colProp);
				if (cellLayout.visible == false) {
					return;
				}

				let cellIndex: number = colProp.constraint.cellIndex;
				let cellSuppress: layout.SuppressCellInfo = suppressModel ? suppressModel[cellIndex] : null;
				let isEmptyCell: boolean = isMergedSuppress && cellSuppress != null && cellSuppress.isRepeated == true;

				let cellBounds: { style: { [key: string]: string }, bound: { left: number, top: number, width: number, mergeCellWidth: number, height: number } }
					= GridUtil._createCellStyle(regionColWidth, colProp, colProp, heights, (isEmptyCell ? false : true));
				if (GridUtil._isContainedCell(cellBounds.bound, cellPositionRange) === false) {
					return;
				}

				let cellShape: ufc.ElementShape = null;
				if (cellSuppress == null || (cellSuppress.isFirst == true && cellSuppress.isLast == true)) { // 일반 컬럼
					cellShape = this._createCell(colProp, cellBounds.style, gridRowGroup, rowIndex, cellIndex, collapseIndex);
					// GridUtil._setRowGroupCellTitle(cellShape, colProp, gridRowGroup, cellIndex, rowIndex); // TOOLTIP
					// this._setAriaExpanded(cellShape, gridRowGroup, grouptype);

				} else if (!isMergedSuppress) { // suppress (suppressedCellType=split)
					cellShape = this._createSuppressCell(colProp, cellBounds.style, gridRowGroup, rowIndex, cellIndex, collapseIndex, cellSuppress);
					// GridUtil._setRowGroupCellTitle(cellShape, colProp, gridRowGroup, cellIndex, rowIndex); // TOOLTIP
					// this._setAriaExpanded(cellShape, gridRowGroup, grouptype);

				} else { // suppress (suppressedCellType=merged)

					/* MERGED CELL */
					if (cellSuppress.isFirst == true) {
						let colHeight: number = cellSuppress.mergedCellHeight;

						// release-test-project#11126 병합 구간에 선택된 행이 포함되어 있는지 여부.
						// 병합 구간은 컬럼마다 다르므로 행이 아닌 병합 셀에 부여한다.
						let isSelectedMerged: boolean = GridUtil._isSelectedMergedCell(this._context, rowIndex, cellSuppress);

						let mergedCellShape: ufc.ElementShape = {
							tag: "div",
							attr: {},
							style: _mergeObject(cellBounds.style, { "height": colHeight + "px" }),
							classNames: GridRowGroupRenderer._createMergedCellClasses(colProp, cellSuppress, isSelectedMerged),
							children: []
						};

						let maxColHeight: number = GridContext._getCellMaxHeight(colHeight);
						let option: renderer.IRenderOption = {
							height: colHeight,
							maxHeight: maxColHeight,
							// text: null,
							// value: null,
							altColumnName: null,
							hidetext: cellSuppress.isFirst ? (cellSuppress.hasEditRow == true && cellSuppress.editable == true) : true,
							isFirst: cellSuppress.isFirst,
							vrowIndex: rowIndex,
							cellIndex: cellIndex
						};
						let cellRenderer: renderer.IGridCellRenderer = colProp.cellRenderer;
						let controlShape: ufc.ControlShape | ufc.ControlRenderer = cellRenderer.createCellShape(gridRowGroup, option);
						mergedCellShape.children.push(controlShape);
						rowShape.children.push(mergedCellShape);


					} else {
						let hiddenCellShape: ufc.ElementShape = {
							tag: "div",
							attr: {},
							style: _mergeObject(cellBounds.style, { visibility: "hidden", "height": "0px" }),
							children: []
						};
						rowShape.children.push(hiddenCellShape);
					}

					/* EMPTY CELL */
					if (cellSuppress.isFirst) { // mergedcell의 첫번째 empty셀
						cellBounds = GridUtil._createCellStyle(regionColWidth, colProp, colProp, heights, false);
					}
					cellShape = {
						tag: "div",
						attr: {
							role: GRIDROLE.GRID_CELL,
							"data-role": GRIDROLE.GRID_ROWGROUP_CELL,
							"data-cellindex": utils.Util.toString(cellIndex)
						},
						style: cellBounds.style,
						children: []
					};
					if (this._context.getGrid().isEditing() == false) { // 편집모드일 때는 그룹행에 포커스 가지 않도록 
						cellShape.attr["tabindex"] = "-1";
					}
					// GridUtil._setRowGroupCellTitle(cellShape, colProp, gridRowGroup, cellIndex, rowIndex); // TOOLTIP
					// this._setAriaExpanded(cellShape, gridRowGroup, grouptype);
					// rowShape.children.push(cellShape);
				}

				// aria-expanded
				this._setAriaExpanded(cellShape, gridRowGroup, grouptype);

				{ // aria-colspan, aria-rowspan
					let cellConst: GridCellConstraint = colProp.constraint;
					if (cellConst.colSpan > 1) {
						GridUtil._setAria(cellShape, "colspan", utils.Util.toString(cellConst.colSpan));
					}
					if (cellConst.rowSpan > 1) {
						GridUtil._setAria(cellShape, "rowspan", utils.Util.toString(cellConst.rowSpan));
					}
				}

				// TOOLTIP
				GridUtil._setRowGroupCellTitle(cellShape, colProp, gridRowGroup, cellIndex, rowIndex);

				// cl-first-column, cl-last-column
				let isFirstColumn: boolean = colProp.constraint.colIndex == visibleColIndices[0];
				let isLastColumn: boolean = colProp.constraint.colIndex + colProp.constraint.colSpan - 1 == visibleColIndices[visibleColIndices.length - 1];
				if (isFirstColumn || isLastColumn) {
					if (cellShape.classNames == null) {
						cellShape.classNames = [];
					}
					if (isFirstColumn) {
						cellShape.classNames.push(ufc.Classes.FIRST_COLUMN);
					}
					if (isLastColumn) {
						cellShape.classNames.push(ufc.Classes.LAST_COLUMN);
					}
				}
				rowShape.children.push(cellShape);
			});

			return [rowShape];
		}

		/**
		 * 일반 셀 생성
		 */
		private _createCell(colProp: GridFooterCellProp, style: { [key: string]: string }, gridRowGroup: provider.GridRowGroup, viewRowIndex: number, cellIndex: number, collapseIndex: number): ufc.ElementShape {
			let cellShape: ufc.ControlShape = {
				tag: "div",
				classNames: [GridStyle.CELL, GridContext.CLS_CELL_INHERIT].concat((colProp.configuration) ? colProp.configuration.style.getClasses() : []),
				attr: {
					role: GRIDROLE.GRID_CELL,
					"data-role": GRIDROLE.GRID_ROWGROUP_CELL,
					"data-cellindex": utils.Util.toString(cellIndex)
				},
				style: style,
				children: []
			};
			if (this._context.getGrid().isEditing() == false) { // 편집모드일 때는 그룹행에 포커스 가지 않도록 
				cellShape.attr["tabindex"] = "-1";
			}

			{ // fieldLabel
				let labelString: string[] = [];
				let expr: string | number | ufc.StyledString = GridUtil._getRowGroupExprValue(colProp, gridRowGroup);
				expr = typeof (expr) == "number" ? "" + expr : expr;
				let exprStr: string = ufc.StyledString._asString(expr);
				if (colProp.configuration.control != null) {
					if (colProp.configuration.expr != null && colProp.configuration.expr != "") {
						colProp.configuration.control.value = exprStr;
					}
					exprStr = colProp.configuration.control.value;
				}
				if (utils.Util.isNullOrEmpty(colProp.configuration.control?.fieldLabel) == false) {
					labelString[labelString.length] = "" + colProp.configuration.control.fieldLabel;
				} else if (utils.Util.isNullOrEmpty(colProp.configuration.fieldLabel) == false) {
					labelString[labelString.length] = "" + colProp.configuration.fieldLabel;
				}
				labelString[labelString.length] = exprStr;
				ufc.ShapeUtil._setAriaLabelAttr(cellShape.attr, labelString.join(" "));
			}


			let cellHeight: utils.Size = utils.ParamUtil.parseSize(cellShape.style["height"]);
			let colHeight: number = cellHeight.size;
			let maxColHeight: number = GridContext._getCellMaxHeight(colHeight);

			let option: renderer.IRenderOption = {
				height: colHeight,
				maxHeight: maxColHeight,
				// text: null,
				// value: null,
				altColumnName: null,
				hidetext: false,
				editingrow: false,
				vrowIndex: viewRowIndex,
				cellIndex: cellIndex
			};
			let cellRenderer: renderer.IGridCellRenderer = colProp.cellRenderer;
			let controlShape: ufc.ControlShape = cellRenderer.createCellShape(gridRowGroup, option) as ufc.ControlShape;

			// [우정 : 20171023] : 셀에 컨트롤이 배치된 경우 불필요한 container 제거
			if (colProp.configuration.control) {
				cellShape.children[cellShape.children.length] = controlShape;
			} else {
				let container: ufc.ElementShape = {
					tag: "div",
					classNames: [GridContext.CLS_CELL_INHERIT],
					style: {
						height: maxColHeight + "px" // 내부 컨트롤에 높이를 지정하기 위해 필요. (2017.9.27)
					},
					children: []
				};
				cellShape.children[cellShape.children.length] = container;

				if (collapseIndex == colProp.constraint.cellIndex) {
					// expander가 존재하는 경우 table-layout:fixed 스타일 제거
					if (controlShape.style["table-layout"] == "fixed") {
						delete controlShape.style["table-layout"];
					}
					container.children.push(this._createExpandButton(gridRowGroup, colHeight));
					container.children.push({
						tag: "div",
						style: {
							display: "inline-block",
							width: "auto",
							height: maxColHeight + "px" // 내부 컨트롤에 높이를 지정하기 위해 필요. (2017.9.27)
						},
						classNames: [GridContext.CLS_CELL_INHERIT],
						children: [controlShape]
					});
				} else {
					container.children.push(controlShape);
				}
			}
			return cellShape;
		}

		/**
		 * suppress 셀 생성
		 */
		private _createSuppressCell(colProp: GridFooterCellProp, style: { [key: string]: string },
			gridRowGroup: provider.GridRowGroup, viewRowIndex: number, cellIndex: number,
			collapseIndex: number, cellSuppress: layout.SuppressCellInfo): ufc.ElementShape {
			let cellShape: ufc.ControlShape = {
				tag: "div",
				classNames: ["cl-grid-cell", GridContext.CLS_CELL_INHERIT].concat((colProp.configuration) ? colProp.configuration.style.getClasses() : []),
				attr: {
					role: GRIDROLE.GRID_CELL,
					"data-role": GRIDROLE.GRID_ROWGROUP_CELL,
					"data-cellindex": utils.Util.toString(cellIndex)
				},
				style: style,
				children: []
			};
			if (this._context.getGrid().isEditing() == false) { // 편집모드일 때는 그룹행에 포커스 가지 않도록 
				cellShape.attr["tabindex"] = "-1";
			}

			if (cellSuppress.isLast === false) {
				cellShape.style["border-bottom"] = "none";
			}
			if (cellSuppress.isRepeated) {
				cellShape.style["border-top"] = "none";
			}
			let cellHeight: utils.Size = utils.ParamUtil.parseSize(cellShape.style["height"]);
			let colHeight: number = cellHeight.size;
			let maxColHeight: number = -1;
			if (cellSuppress.isFirst || cellSuppress.isRepeated) {
				maxColHeight = colHeight;
			} else {
				maxColHeight = GridContext._getCellMaxHeight(colHeight);
			}

			let cellRenderer: renderer.IGridCellRenderer = colProp.cellRenderer;
			let option: renderer.IRenderOption = {
				height: colHeight,
				maxHeight: maxColHeight,
				// text: null,
				// value: null,
				altColumnName: null,
				editingrow: false,
				hidetext: cellSuppress.isRepeated,
				hideborder: !cellSuppress.isLast,
				isFirst: cellSuppress.isFirst,
				vrowIndex: viewRowIndex,
				cellIndex: cellIndex
			};
			let controlShape: ufc.ControlShape | ufc.ControlRenderer = cellRenderer.createCellShape(gridRowGroup, option);

			// [우정 : 20171023] : 셀에 컨트롤이 배치된 경우 불필요한 container 제거
			if (colProp.configuration.control) {
				(controlShape as ufc.ControlShape).style["width"] = "100%";
				GridUtil._setControlPosition(controlShape as ufc.ControlShape, colProp.configuration.controlConstraint);
				cellShape.children[cellShape.children.length] = controlShape;
			} else {
				let container: ufc.ElementShape = {
					tag: "div",
					classNames: [GridContext.CLS_CELL_INHERIT],
					style: {
						height: maxColHeight + "px" // 내부 컨트롤에 높이를 지정하기 위해 필요. (2017.9.27)
					},
					children: []
				};
				cellShape.children[cellShape.children.length] = container;

				if (collapseIndex == colProp.constraint.cellIndex) {
					container.children.push(this._createExpandButton(gridRowGroup, colHeight));
					container.children.push({
						tag: "div",
						style: {
							display: "inline-block",
							width: "auto",
							height: maxColHeight + "px" // 내부 컨트롤에 높이를 지정하기 위해 필요. (2017.9.27)
						},
						classNames: [GridContext.CLS_CELL_INHERIT],
						children: [controlShape]
					});
				} else {
					container.children.push(controlShape);
				}
			}
			return cellShape;
		}

		private _createExpandButton(gridRowGroup: provider.GridRowGroup, colHeight: number): ufc.ControlShape {
			let expandButton: ufc.ControlShape = {
				tag: "div",
				attr: {
					"data-role": GRIDROLE.EXPANDER
				},
				classNames: [GridContext.CLS_CELL_INHERIT, "cl-expander"],
				style: {
					height: GridContext._getCellMaxHeight(colHeight) + "px" // 내부 컨트롤에 높이를 지정하기 위해 필요. (2017.9.27)
				}
			}
			if (gridRowGroup.expanded) {
				expandButton.classNames.push("cl-expanded");
			} else {
				expandButton.classNames.push("cl-collapsed");
			}
			return expandButton;
		}

		private static _createMergedCellClasses(colProp: GridCellProp, cellSuppress: layout.SuppressCellInfo, isSelectedMerged: boolean): string[] {
			let cellClasses: string[] = [GridStyle.CELL, GridContext.CLS_CELL_INHERIT, ufc.Classes.MERGED];
			cellClasses[cellClasses.length] = (cellSuppress.hasEditRow) ? ufc.Classes.EDITING : ufc.Classes.VIEWING;

			if (cellSuppress.suppressRowCount > 1) {
				cellClasses[cellClasses.length] = ufc.Classes.MULTIPLE;
			}
			// release-test-project#11126 병합 구간에 선택된 행이 있는 경우의 스타일 지정용
			if (isSelectedMerged) {
				cellClasses[cellClasses.length] = ufc.Classes.SELECTED_MERGED;
			}

			if (colProp.configuration) {
				cellClasses = _.union(cellClasses, colProp.configuration.style.getClasses());
			}

			return cellClasses;
		}

		private _setAriaExpanded(cellShape: ufc.ElementShape, gridRowGroup: provider.GridRowGroup, grouptype: string): void {
			if (this._context.getGrid().collapsible == false || grouptype == "gfooter") {
				return;
			}

			cellShape.attr["role"] = "gridcell"; // 임시
			if (gridRowGroup.expanded) {
				GridUtil._setAria(cellShape, "expanded", "true");
			} else {
				GridUtil._setAria(cellShape, "expanded", "false");
			}
		}

	}
}