/// <reference path="./provider/DataBindable.ts" />
/// <reference path="./AccessableUIControl.ts" />

namespace cpr.controls {

	/**
	 * @private
	 */
	export class TextInputFocusEntry implements FocusEntry {
		private _textInput: TextInput;
		private _selector: string;
		constructor(textInput: TextInput, selector: string) {
			this._textInput = textInput;
			this._selector = selector;
		}

		focus(forward: boolean): void {
			this._textInput._focusBySelector(this._selector);
		}
		focusImmediately(forward: boolean = true) {
			this._textInput._focusBySelector(this._selector, true);
		}
	}
	/**
	 * 텍스트입력상자의 기본 클래스.
	 * TextEditor의 상위 클래스.
	 */
	export abstract class TextInput extends AccessableUIControl implements provider.ValueBindable, gridpart.IGridParticipant {
		private static readonly TEXTBOX_AVAILABLE_PROP: string[] = [
			"value", "text"
		];

		protected _binder: provider.InputValueBinder;
		private _editingText: string = null;
		private _oldValue: string;
		private _isUpdatingValue: boolean = false;
		private _textEditorType: string = "input";
		private _textFocusEntry = new TextInputFocusEntry(this, `.${"cl-text"}`);
		private _internalProps: { [key: string]: any };

		/**
		 * 인풋 계열 컴포넌트의 상위 클래스를 생성합니다.
		 * @param id 텍스트 에디터의 id
		 */
		constructor(id?: string) {
			super(id);
			this._binder = new provider.InputValueBinder(this);
		}
		override _getLabelableType(): LabelableType {
			return this._textEditorType == "input" ? LabelableType.input : LabelableType.textarea;
		}
		public _convertGridPasteText(text: string): string {
			return text;
		}
		public _getGridViewingText(): string {
			return this.text;
		}
		public _renderGridCellShape(grid: Grid, data: (string | ufc.StyledString), option: gridpart.renderer.IRenderOption): ufc.ControlShape {
			return null;
		}
		public _computeDisplayText(): string | ufc.StyledString {
			return this._transformDisplayText(this._getValue());
		}

		protected _isConfigurableProperty(propName: string): boolean {
			if (TextInput.TEXTBOX_AVAILABLE_PROP.indexOf(propName) != -1) {
				return true;
			}
			return super._isConfigurableProperty(propName);
		}

		protected _setInternalProperty(name: string, value: any) {
			if (!this._internalProps) {
				this._internalProps = {};
			}
			this._internalProps[name] = value;
		}

		protected _getInternalProperty(name: string) {
			if (!this._internalProps) {
				return undefined;
			}
			return this._internalProps[name];
		}

		protected _setConfigureProperty(name: string, value: any): void {
			if (this._isConfigurableProperty(name)) {
				if (this._getInternalProperty(name) != undefined) {
					this._setInternalProperty(name, value);
				} else {
					this[name] = value;
				}
			}
		}

		protected _getLabel(defaultLabel: string, exp?: expression_string): string {
			if (exp) {
				let expr = new expression.Expression(exp);
				// 표현식 결과는 StyledString(sstr) 처럼 문자열이 아닐 수 있다. 이 값은 aria-label 로만 쓰이므로
				// 여기서 문자열로 확정하지 않으면 렌더링 시점에 빈 값이나 [object Object] 가 된다.
				// release-test-project#10122
				return ufc.StyledString._asString(expr.evaluate({
					_getExpressionDelegates: () => {
						return [
							this, this.getBindContext()
						]
					}
				}));
			}
			return defaultLabel;
		}

		protected _getText(): string {
			return this._binder.getText();
		}

		/**
		 * 컨트롤 내부에서 사용가능한 유효한 값으로 변환하여 반환합니다.
		 * 입력상자는 항상 문자열을 반환합니다.
		 * @returns 
		 */
		public _getValue(): string {
			return this.value ?? "";
		}
		/**
		 * 컨트롤 내부에서 사용가능한 유효한 값으로 변환하여 설정합니다.
		 * @param value 
		 */
		public _setValue(value: string) {
			this.value = value;
		}

		protected _setTextEditorType(type: string) {
			this._textEditorType = type;
		}

		/**
		 * @param prop 
		 * @param oldValue 
		 * @param newValue 
		 */
		_valueDidChange(prop: string, oldValue: any, newValue: any) {
			super._valueDidChange(prop, oldValue, newValue);
			this._binder._valueDidChange(prop, oldValue, newValue);
		}


		/**
		 * Control의 상태에 따라 Control의 Default Event Handler를 실행할 지 여부를 결정합니다.
		 * @param e 이벤트
		 * @return 컨트롤의 Event Handler 실행 여부.
		 */
		public confirmEvent(e: events.CEvent): boolean {
			if (super.confirmEvent(e) === false) {
				return false;
			}
			if (!e.nativeEvent) {
				return true;
			}
			//_checkControlStateForEvent은 shape내에 설정한 이벤트와 사용자 이벤트 등록 개수에 따라 호출이 2번 될 수 있음.
			let browser = _detectBrowser();
			if (browser.name === "edge") {
				if (e.type === "input" && e["data"] === null) {
					let input = e.target as HTMLInputElement;
					if (input.value.indexOf("\t") > -1) {
						let ss = input.selectionStart;
						let se = input.selectionEnd;
						input.value = this._getDisplayText();
						input.setSelectionRange(ss, se);
						return false;
					}
				}
			}

			return true;
		}

		/**
		 * InputDom의 value를 즉시 변경합니다.
		 * @param value 
		 */
		protected _updateInputValue(): void {
			if (this.disposed) {
				return;
			}
			let inputDom = <HTMLInputElement>this._getRenderer().getNamedNode("text");
			if (!inputDom) {
				return;
			}
			let text = this._getDisplayText();
			if (inputDom.value != text) {
				// safari는 value값을 변경했을때 커서가 끝으로 이동하지 않음.
				// input.value 했을시 Chrome에서는 커서가 맨 앞으로 이동. setAttribute("value",newValue) DOM속성에 값이 표시됨.
				inputDom.value = text;
			}
		}
		protected _startUpdateValue() {
			this._isUpdatingValue = true;
		}
		protected _endUpdateValue() {
			this._isUpdatingValue = false;
		}
		protected _canUpdateValue() {
			return this._isUpdatingValue == false;
		}

		/**
		 * Shape의 Input Tag의 Value 값으로 설정할 값을 리턴한다.
		 * 설정할 값은 Input Tag가 편집 중인지 여부에 따라 편집 중인 값 또는
		 * 컨트롤 value에 기반한 값이 될 수 있다.
		 * Shape내에서 사용하지 않는 경우 {@link _getDisplayText}를 사용하시기 바랍니다.
		 */
		protected _getInputTagValue(): string {
			if (this._hasEditingText()) {
				return this._editingText;
			}
			return this._getDisplayText();
		}

		protected _hasEditingText(): boolean {
			return this._editingText != null;
		}

		protected _initEditingText() {
			this._editingText = null;
		}

		protected _getDisplayText(): string {
			return ufc.StyledString._asString(this._computeDisplayText());
		};


		protected _transformDisplayText(value: string): string | ufc.StyledString {
			return value;
		}

		protected _isEditable(): boolean {
			return (this.isAvailableBinding("value") == true);
		}

		protected _checkValueChange(oldValue: string, newValue: string) {
			return oldValue != newValue;
		}

		/// SimpleDataBindable Start ////////////////////////////////////////////
		/**
		 * 컨트롤의 값을 설정하고, value-change이벤트가 발생됩니다.
		 * @param value 컨트롤의 값.
		 */
		public set value(value: string) {
			this._startUpdateValue();
			this._binder.setValue(value, true);
			this._updateInputValue();
			this._endUpdateValue();
		}

		/**
		 * 컨트롤의 값을 반환합니다.
		 * @return 컨트롤의 값.
		 */
		public get value(): string {
			return this._binder.getValue();
		}

		/**
		 * 컨트롤의 값을 설정합니다.
		 * @param value 컨트롤의 값.
		 */
		public putValue(value: string) {
			this._startUpdateValue();
			this._binder.setValue(value, false);
			this._updateInputValue();
			this._endUpdateValue();
		}

		/**
		 * 컨트롤에 보여지는 텍스트를 반환합니다.
		 * @return 화면에 보이는 텍스트.
		 */
		public get text(): string {
			return this._getText();
		}

		/**
		 * 컨트롤에 보이는 텍스트를 설정합니다.
		 * @param 화면에 보이는 텍스트.
		 */
		public set text(text: string) {
			this._binder.setText(text);
		}

		/// SimpleDataBindable End ////////////////////////////////////////////////
		/**
		 * 인풋에서 보여지는 HTML Element의 value를 가져옵니다.
		 * @return display되는 text.
		 */
		get displayingText(): string {
			return this.displayText;
		}
		/**
		 * 인풋에서 보여지는 HTML Element의 value를 가져옵니다.
		 * @return display되는 text.
		 * @deprecated {@link displayingText}을 사용하시기 바랍니다.
		 */
		get displayText(): string {
			return this._getDisplayingText();
		}

		protected _getDisplayingText(): string {
			let input = this._getRenderer().getNamedNode("text") as HTMLInputElement;
			if (!input) {
				return this.text ?? "";
			}
			return input.value;
		}

		public _beforeDraw() {
			super._beforeDraw();
			if (this._oldValue != this.value) {
				//바인딩된 값 체크. 입력중에 값이 변경되고 redraw 하게 되면 설정한 value로 변경되어야 한다.
				this._oldValue = this.value;
				this._editingText = null;
			} else if (this._getRenderer().hasDrawn()) {
				try {
					let activeElement = this._getActiveElement(); //IE의 IFrame에서 도큐먼트가 생성되지 않았을때 에러가 발생.

					if (activeElement) {
						let ndid = this._getRenderer()._getNamedNodeUUID("text");
						let attr = activeElement.getAttribute(ufc.ControlRenderer._ATTR_UUID);
						if (ndid === attr) {
							this._editingText = (<HTMLInputElement>activeElement).value;
						} else {
							this._editingText = null;
						}
					} else {
						this._editingText = null;
					}
				} catch (e) {
					this._editingText = null;
				}
			}
		}

		override _getLabelableElementId(): string {
			return ufc.NodeUUIDMapper.INSTANCE._createPartialUUID(this, "text");
		}

		protected _getActiveElement() {
			return document.activeElement;
		}

		/**
		 * mousedown 이벤트가 포함되어 있습니다. 같이 포함하여 사용하기 바랍니다.
		 */
		protected _createTextEditor(): cpr.ufc.ControlShape {
			let attributes = this._textEditorType == "textarea" ? {} : { type: "text" };
			attributes['id'] = this._getLabelableElementId();
			let shape: ufc.ElementShape;
			if (this._textEditorType == "textarea") {
				shape = {
					tag: "textarea",
					classNames: [ufc.Classes.TEXT],
					attr: attributes,
					style: {
						resize: "none",//chrome 상의 resize 고정
						background: "transparent",
						display: "block"
					},
					events: {
						// mousedown: this._onInputMousedown
					},
					eventTargets: [ufc.EventTargetType.INPUT_SELECT, ufc.EventTargetType.INPUT_CLIPBOARD],
					nodename: "text"
				}
			} else {
				shape = {
					tag: "input",
					classNames: [ufc.Classes.TEXT],
					attr: attributes,
					style: {
						display: "block"
					},
					events: {
						// mousedown: this._onInputMousedown
					},
					eventTargets: [ufc.EventTargetType.INPUT_SELECT, ufc.EventTargetType.INPUT_CLIPBOARD],
					nodename: "text"
				}
			}
			cpr.ufc.ShapeUtil._setAriaLabelAttr(shape.attr, this._getFieldLabel());
			cpr.ufc.ShapeUtil._setTooltipAttr(shape, { owner: this, title: this.tooltip });
			return shape;
		}

		protected _createPlaceholder(placeholder: string, show: boolean) {
			let cell: ufc.ControlShape = {
				tag: "div",
				classNames: [ufc.Classes.TEXT, ufc.Classes.PLACEHOLDER, ufc.Classes.UNSELECTABLE],
				style: {
					overflow: "hidden",
					height: "auto",
					width: "auto"
				},
				attr: {},
				children: [placeholder]
			}
			layouts.GridCSSBuilder._forCell()._withColumnStart(1)._withRowStart(1)._withVerticalAlign(layouts.GridCellAlign.center)._commit(cell.style);
			let shape: ufc.ControlShape = {
				tag: "div",
				classNames: [],
				style: {
					overflow: "hidden",
					top: "0px",
					right: "0px",
					bottom: "0px",
					left: "0px",
					height: "100%",
					position: "absolute",
					padding: "inherit",
					cursor: "text",
					"pointer-events": "none"
				},
				attr: {
					"data-role": "placeholder"
				},
				children: [cell],
				nodename: "placeholder"
			}
			layouts.GridCSSBuilder._forLayout()._withTemplateColumns("1fr")._withTemplateRows("1fr")._commit(shape.style);
			if (this.enabled == false) {
				shape.style["cursor"] = "default";
			}
			if (show == false) {
				shape.style["display"] = "none";
			}
			return shape;
		}

		protected _showPlaceholder() {
			if (this._getDisplayText().length > 0) {
				return;
			}
			let elem = this._getPlaceholderNode();
			if (elem) {
				let browserInfo = _detectBrowser();
				let useOldGridSpec =
					(browserInfo.name == "ie" && 10 <= browserInfo.versionNumber && browserInfo.versionNumber <= 11)
					|| browserInfo.name == "edge";
				if (useOldGridSpec) {
					this._getRenderer().updateStyle("placeholder", { display: "-ms-grid" }, true);
				} else {
					this._getRenderer().updateStyle("placeholder", { display: "grid" }, true);
				}
			}
		}

		protected _getPlaceholderNode() {
			if (this.disposed) {
				return null;
			}
			let node = this._getRenderer().getNamedNode("placeholder");
			return node;
		}

		protected _hidePlaceholder() {
			let elem = this._getPlaceholderNode();
			if (elem) {
				this._getRenderer().updateStyle("placeholder", { display: "none" }, true);
			}
		}

		public _getFocusEntries(): FocusEntry[] {
			return [this._textFocusEntry];
		}

		public _getActiveFocusEntry(): FocusEntry {
			let activeElement = document.activeElement as HTMLElement;
			if (!activeElement) {
				return null;
			}

			let classList = activeElement.classList;
			let activeFocusEntry = null;
			if (classList.contains("cl-text")) {
				activeFocusEntry = this._textFocusEntry;
			}

			return activeFocusEntry;
		}

		override _focusPrevious(includeEntry: boolean = false) {
			if (includeEntry) {
				new TextInputFocusRing(this, this._getActiveFocusEntry())._focusPrevious();
			} else {
				super._focusPrevious(includeEntry);
			}
		}

		override _focusNext(includeEntry: boolean = false) {
			if (includeEntry) {
				new TextInputFocusRing(this, this._getActiveFocusEntry())._focusNext();
			} else {
				super._focusNext(includeEntry);
			}
		}

		public _focusBySelector(selector: string, immediate: boolean = false) {
			if (immediate) {
				this._focusImmediateBySelector(selector);
			} else {
				core.DeferredUpdateManager.INSTANCE._performFocusTask(() => {
					this._focusImmediateBySelector(selector);
				});
			}
		}

		private _focusImmediateBySelector(selector: string) {
			if (this.disposed == false && this.focusable) {
				let node = this._getRenderer().getRootNode();
				if (node) {
					let focusible = node.querySelector(selector) as HTMLElement;
					if (focusible) {
						focusible.focus();
					}
				}
			}
		}

		public _exportValue(): string | number {
			let ctrlText = (this.text === undefined) ? this.value : this.text;

			// 기본 >> text
			return (ctrlText != null) ? "" + ctrlText : "";
		}
	}
}