namespace cpr.controls.calendar {

	/**
	* @private
	*/
	export class AbstractCalendarProperties {
		/**
		 * 날짜를 표시하는 형식
		 */
		public format: string;
		public minDate: Date;
		public maxDate: Date;
		/**
		 * 명시적으로 지정된 기본 날짜. 지정된 적이 없으면 null이며,
		 * 이 경우 AbstractCalendar가 사용 시점마다 오늘 날짜를 계산해 사용한다.
		 * release-test-project#11154
		 */
		public defaultDate: Date = null;
		public current: moment.Moment;
		public displayCurrent: moment.Moment;
		public footerFormat: string = "LL";
		public weekdays: string = CalendarWeekdayNameType.min;
		public months: string = CalendarMonthNameType.min;
		public showWeekNumber: boolean = false;
		public fixedWeekCount: boolean = true;
		public headerVisible: boolean = true;
		public footerVisible: boolean = true;
		public selectionType: CalendarSelectionType = CalendarSelectionType.single;
		public showAnniversary: boolean = false
		public enabledDateExp: expression_string = null
		public showOtherMonths: boolean = true;
		public showCurrent: boolean = true;
		public headerButtons: CalendarHeaderButtonType[] = [CalendarHeaderButtonType.prevYear, CalendarHeaderButtonType.prev, CalendarHeaderButtonType.title, CalendarHeaderButtonType.next, CalendarHeaderButtonType.nextYear];
		public tabFocus: CalendarTabFocus = CalendarTabFocus.body;
		public dateDisplayExp: expression_string;
		public shiftKeyValue: string;
		public anniversaries: Anniversary[] = [];
		public delimiter: string = ",";

		constructor(defaultProperty: {
			format: string,
			current: moment.Moment,
			minDate: Date,
			maxDate: Date
		}) {
			this.format = defaultProperty.format;
			this.current = defaultProperty.current;
			this.displayCurrent = defaultProperty.current.clone();
			this.minDate = new Date(1900, 0, 1, 0, 0, 0);
			this.maxDate = new Date(9999, 11, 31, 23, 59, 59);
		}

		/**
		 * 기본 날짜가 지정되지 않았을 때 사용할 오늘 날짜를 만든다.
		 * 이전에는 이 값을 생성자에서 한 번만 계산해 화면 로드 시점의 날짜에 고정됐다.
		 * 시각을 01:00:00으로 맞추는 것은 시간까지 포함한 형식에서 선택 값의 기본 시각으로
		 * 쓰이던 기존 동작을 그대로 유지하기 위함이다. release-test-project#11154
		 */
		public static _createTodayDate(): Date {
			let today = new Date();
			today.setHours(1, 0, 0);
			return today;
		}
	}
}
