	/**
	 * addColumn시 사용하는 인터페이스
	 */
	export interface IGridColumnLayoutConfig {
		/**
		 * 컬럼 레이아웃
		 */
		columnLayout: GridColumnConfig[],
		/**
		 * 헤더 정보
		 */
		header: GridHeaderCellConfig[],
		/**
		 * 디테일 정보
		 */
		detail: GridDetailCellConfig[],
		/**
		 * 푸터 정보
		 */
		footer?: GridFooterCellConfig[],
		/**
		 * 행그룹 정보
		 */
		rowGroup?: {
			/** 그룹 조건 */
			groupCondition: expression_string,
			/** 그룹 헤더 정보 */
			gheader?: GridGroupHeaderCellConfig[],
			/** 그룹 푸터 정보 */
			gfooter?: GridFooterCellConfig[]
		}[]
	}

