		public addColumn(column: gridpart.IGridColumnLayoutConfig, baseColIndex: number): void {

			let runtimeColumn: {
				columnLayout: GridColumnConfig[],
				header: GridHeaderCellProp[],
				detail: GridDetailCellProp[],
				footer?: GridFooterCellProp[],
				rowGroup?: {
					groupCondition: string,
					gheader?: GridFooterCellProp[],
					gfooter?: GridFooterCellProp[]
				}[]
			} = {
				columnLayout: column.columnLayout,
				header: this._runtimeConfig._getCellProp("header", this._grid, column.header, baseColIndex) as GridHeaderCellProp[],
				detail: this._runtimeConfig._getCellProp("detail", this._grid, column.detail, baseColIndex) as GridDetailCellProp[]
			};

			if (column.hasOwnProperty("footer")) {
				runtimeColumn.footer = this._runtimeConfig._getCellProp("footer", this._grid, column.footer, baseColIndex) as GridFooterCellProp[];
			}
			if (column.hasOwnProperty("rowGroup")) {
				runtimeColumn.rowGroup = [];
				column.rowGroup.forEach((rowGroupConfig: { groupCondition: string, gheader?: GridGroupHeaderCellConfig[], gfooter?: GridFooterCellConfig[] }) => {
					let rowGroup: { groupCondition: string, gheader?: GridFooterCellProp[], gfooter?: GridFooterCellProp[] } = {
						groupCondition: rowGroupConfig.groupCondition
					};
					if (rowGroupConfig.hasOwnProperty("gheader")) {
						rowGroup.gheader = this._runtimeConfig._getCellProp("footer", this._grid, rowGroupConfig.gheader, baseColIndex) as GridFooterCellProp[];
					}
					if (rowGroupConfig.hasOwnProperty("gfooter")) {
						rowGroup.gfooter = this._runtimeConfig._getCellProp("footer", this._grid, rowGroupConfig.gfooter, baseColIndex) as GridFooterCellProp[];
					}
					runtimeColumn.rowGroup.push(rowGroup);
				})
			}

			this._runtimeConfig._addColumn(runtimeColumn);
		}

