		public adjustRowSplit(): void {
			if (this.topSplit > 0 && this.topSplit < this._grid.rowCount) {
				this._setEnablePart(GRIDREGION.TOP, true);
			} else {
				this._setEnablePart(GRIDREGION.TOP, false);
			}
			if (this.bottomSplit > 0 && this.bottomSplit < this._grid.rowCount) {
				this._setEnablePart(GRIDREGION.BOTTOM, true);
			} else {
				this._setEnablePart(GRIDREGION.BOTTOM, false);
			}

			this._clearContentHeight();
		}

		public _getStartRowIndex(location: string): number {
			let enabled: boolean = this.isEnabledPart(location);
			if (enabled == true) {
				switch (location) {
					case GRIDREGION.TOP: {
						return 0;
					}
					case GRIDREGION.MIDDLE: {
						let topenabled: boolean = this.isEnabledPart(GRIDREGION.TOP);
						if (topenabled == true) {
							return this.topSplit;
						} else {
							return 0;
						}
					}
					case GRIDREGION.BOTTOM: {
						let gridRowCount: number = this._grid.getContentRowCount();
						return gridRowCount - this.bottomSplit;
					}
				}
			} else {
				return -1;
			}
		}

		public _getEndRowIndex(location: string): number {
			let enabled: boolean = this.isEnabledPart(location);
			if (enabled == true) {
				let gridRowCount: number = this._grid.getContentRowCount();
				switch (location) {
					case GRIDREGION.TOP: {
						return this.topSplit - 1;
					}
					case GRIDREGION.MIDDLE: {
						let bottomenabled: boolean = this.isEnabledPart(GRIDREGION.BOTTOM);
						if (bottomenabled == true) {
							return gridRowCount - this.bottomSplit - 1;
						} else {
							return gridRowCount - 1;
						}
					}
					case GRIDREGION.BOTTOM: {
						return gridRowCount - 1;
					}
				}
			} else {
				return -1;
			}
		}

