		/* helper methods */
		private _setDefault(): void {
			// GridInfo로 아래 Data 생성
			if (this._runtimeConfig._getLeftSplit() > 0) {
				this._setEnablePart(GRIDREGION.LEFT, true);
			} else {
				this._setEnablePart(GRIDREGION.LEFT, false);
			}
			this._setEnablePart(GRIDREGION.CENTER, true);
			if (this._runtimeConfig._getRightSplit() > 0) {
				this._setEnablePart(GRIDREGION.RIGHT, true);
			} else {
				this._setEnablePart(GRIDREGION.RIGHT, false);
			}

			this._setEnablePart(GRIDREGION.TOP, false);
			this._setEnablePart(GRIDREGION.MIDDLE, true); /* middle 영역은 나머지 영역 전체를 차지함 */
			this._setEnablePart(GRIDREGION.BOTTOM, false);

			if (this.getFooter() != null && this.getFooter().visible !== false) {
				this._setEnablePart(GRIDREGION.FOOTER, true);
			} else {
				this._setEnablePart(GRIDREGION.FOOTER, false);
			}
		}

