		public _isTreeGrid(): boolean {
			let detailCellProps: GridDetailCellProp[] = this._getDetailCellProps();
			let hasTreeCell: boolean = detailCellProps.some((item: GridDetailCellProp) => {
				let uicontrol: GridUIControl = item.configuration.control;
				if (uicontrol && uicontrol instanceof renderer.TreeCell) {
					return true;
				}
				return false;
			});

			return hasTreeCell;
		}
		public _getTreeCell(): renderer.TreeCell {
			let detailCellProps: GridDetailCellProp[] = this._getDetailCellProps();
			for (let idx: number = 0; idx < detailCellProps.length; idx++) {
				let item: GridDetailCellProp = detailCellProps[idx];
				let uicontrol: GridUIControl = item.configuration.control;
				if (uicontrol && uicontrol instanceof renderer.TreeCell) {
					return uicontrol;
				}
			}

			return null;
		}

		/**
		 * 전체검색하여 editrow 찾는 refresh
		 */
		public _refreshEditingRowIndex(isFullSearch: boolean): void {
			if (this._editingRowIndex == -1) {
				return;
			}

			let beforeEditingRowIndex: number = this._editingRowIndex;
			this._editingRowIndex = -1;
			this._editingRowCtrAttr = null;

			let editingRowInfo: { index: number, rowCtrlAttr: data.tabledata.RowCtrlAttr } = this.getGrid().dataProvider._getEditingRowInfo((isFullSearch) ? null : beforeEditingRowIndex);
			this._editingRowIndex = editingRowInfo.index;
			this._editingRowCtrAttr = editingRowInfo.rowCtrlAttr;

			// DataSet 변경에 의해 편집행의 인덱스가 변경되었을 때 GridEmbeddedContext의 Index와 동기화 처리
			if (beforeEditingRowIndex !== editingRowInfo.index) {
				this._grid._setContentDataRowIndex(this._editingRowIndex, -1);
			}
		}

