		private _getCellText(cellProp: GridDetailCellProp, gridRow: provider.GridRow): string | ufc.StyledString {
			let colValue: (string | ufc.StyledString) = null;
			let control: UIControl = null;
			if (cellProp.configuration) {
				control = cellProp.configuration.control;
			}
			if (control != null) {
				if (control instanceof Output || control instanceof ComboBox || control instanceof NumberEditor) {
					colValue = control._computeDisplayText();
				} else {
					if (control["getText"]) { // UDC 도 허용
						colValue = control["getText"]();
					} else if (control["text"]) {
						colValue = control["text"];
					} else if (control["value"]) {
						colValue = control["value"];
					}
				}
			} else if (cellProp.configuration) {
				let colName: string = cellProp.configuration.columnName;
				if (colName) {
					let value: (string | number | foundation.DecimalType | ufc.StyledString) = gridRow.getValue(colName);
					if (value == null) {
						colValue = null;
					} else if (value instanceof ufc.StyledString) {
						colValue = value;
					} else if (value instanceof foundation.DecimalType) {
						colValue = value.toString();
					} else {
						colValue = String(value);
					}
				} else if (cellProp.configuration.columnType == "rowindex") {
					let rowIndex: number = gridRow.getIndex();
					colValue = String(rowIndex + this._grid.rowIndexerStartNum);
				}
			}
			return colValue;
		}
