		/**
		 * startrowIndex부터 endrowIndex까지의 높이.
		 * startrowIndex, endrowIndex를 포함.
		 */
		public _getRangeHeight(startrowIndex: number, endrowIndex: number, location: string): number {
			let result: number = 0;
			let virtualRows: provider.VirtualRow[] = this._grid._getVirtualRows();
			if (this._hasAutoHeightColumn() === false) {
				if (virtualRows && virtualRows.length != 0) {
					if (startrowIndex != -1 && endrowIndex != -1) {
						for (let idx: number = startrowIndex; idx <= endrowIndex; idx++) {
							result += this._getVirtualRowHeight(virtualRows[idx]);
						}
					}
				} else {
					let rowHeight: number = this._getDesignDetailRowHeight();
					if (this._hasCustomRowHeight) {
						for (let idx: number = startrowIndex; idx <= endrowIndex; idx++) {
							let gridRow: provider.GridRow = this._grid.getRow(idx);
							let tmpHeight: number[] = this._getCustomRowHeightAttr(gridRow);
							if (tmpHeight != null) {
								result += utils.Util.sum(tmpHeight);
							} else {
								result += rowHeight;
							}
						}
					} else {
						let rowCount: number = endrowIndex - startrowIndex + 1; // row가 0 base이기 때문에 +1 해준다.
						result = rowHeight * rowCount;
					}
				}
				return result;
			}

			let designRowHeights: number[] = this._getDesignDetailRowHeights();
			let detailCellProps: GridDetailCellProp[] = this._getVisibleDetailCells();

			this._grid._keepContentDataRowIndex();
			let reqRowHeightAdjust: boolean = this._isReqRowHeightAdjust();

			if (virtualRows) {
				if (startrowIndex != -1 && endrowIndex != -1) {
					for (let idx: number = startrowIndex; idx <= endrowIndex; idx++) {
						let vrow: provider.VirtualRow = virtualRows[idx];
						if (vrow.dsindex >= 0) {
							this._grid._setContentDataRowIndex(vrow.dsindex, idx);
							let maxRowHeight: number[] = this._getGridRowHeightCache(detailCellProps, vrow.rowdata as provider.GridRow, designRowHeights, location, reqRowHeightAdjust);
							result += utils.Util.sum(maxRowHeight);
						} else {
							result += utils.Util.sum(vrow.rowheights);
						}
					}
				}
			} else {
				for (let idx: number = startrowIndex; idx <= endrowIndex; idx++) {
					let gridRow: provider.GridRow = this._grid.getDataRow(idx);
					this._grid._setContentDataRowIndex(idx, -1);
					let maxRowHeight: number[] = this._getGridRowHeightCache(detailCellProps, gridRow, designRowHeights, location, reqRowHeightAdjust);
					result += utils.Util.sum(maxRowHeight);
				}
			}
			this._grid._restoreContentDataRowIndex();

			return result;
		}

