		public _resetSuppressInfoIfNeeded(isAll: boolean): void {
			if (this._suppressResetLocs.length > 0) {
				let locs: string[] = this._suppressResetLocs.splice(0);
				let gridLocs: string[] = [GRIDREGION.TOP, GRIDREGION.MIDDLE, GRIDREGION.BOTTOM];
				locs = _.intersection(gridLocs, locs);
				if (locs == null || locs.length == 0) {
					return;
				}

				for (let idx: number = 0; idx < locs.length; idx++) {
					let loc: string = locs[idx];

					this._suppressInfo[loc] = this._getSuppressModel(loc, isAll);
				}
			}
		}

		public _getSuppressModel(loc: string, isAll: boolean): gridpart.layout.SuppressRowProp[] {
			if (this.isEnabledPart(loc) == false) {
				// 활성 구역 체크
				return [];
			}

			let rowCount: number = this.detailRowCount;
			let detailCellProps: GridDetailCellProp[] = this._getVisibleDetailCells();
			let mergeCellProps: GridDetailCellProp[] = [];
			let suppressCellProps: GridDetailCellProp[] = [];
			let hiddenSuppressCellProps: GridDetailCellProp[] = [];
			{ // visible suppress cell 
				detailCellProps.forEach((cellProp: GridDetailCellProp) => {
					if (cellProp.configuration.control?.type != "treecell"
						|| (cellProp.configuration.control?.type == "treecell" && (cellProp.configuration.control as renderer.TreeCell)?.showCheckbox == false)) {
						if (cellProp.configuration._isMergeableCell()) { // mergeToIndexExpr이 있거나
							mergeCellProps[mergeCellProps.length] = cellProp;
							suppressCellProps[suppressCellProps.length] = cellProp;

						} else if ((rowCount == 1 || cellProp.constraint.rowSpan == rowCount) && // suppress 관련 설정이 있거나
							(cellProp.configuration._isSuppressibleCell())) {
							suppressCellProps[suppressCellProps.length] = cellProp;
						}
					}
				});
			}
			if (suppressCellProps.length == 0) {
				// suppressible cell이 없는 경우
				return [];
			}
			{ // invisible suppress cell 
				let hiddenDetailCellProps: GridDetailCellProp[] = this._getVisibleDetailCells(false);
				hiddenDetailCellProps.forEach((cellProp: GridDetailCellProp) => {
					if ((rowCount == 1 || cellProp.constraint.rowSpan == rowCount) && // suppress 관련 설정이 있거나
						(cellProp.configuration._isSuppressibleCell())) {
						hiddenSuppressCellProps[hiddenSuppressCellProps.length] = cellProp;
					}
				});
			}

			let renderStartRowIndex: number = -1;
			let renderEndRowIndex: number = -1;
			if (isAll == true) {
				let rowCount: number = this._grid.getContentRowCount();
				if (rowCount > 0) {
					renderStartRowIndex = 0;
					renderEndRowIndex = rowCount - 1;
				}
			} else {
				let gridLeftDetail: GridDetail = this._grid._getGridDetail(GRIDREGION.LEFT, loc);
				let gridCenterDetail: GridDetail = this._grid._getGridDetail(GRIDREGION.CENTER, loc);
				let gridRightDetail: GridDetail = this._grid._getGridDetail(GRIDREGION.RIGHT, loc);
				let gridDetail: GridDetail = (gridCenterDetail != null) ? gridCenterDetail : ((gridLeftDetail != null) ? gridLeftDetail : gridRightDetail);
				if (gridDetail == null) {
					return [];
				}
				renderStartRowIndex = gridDetail._getRenderStartRowIndex();
				renderEndRowIndex = gridDetail._getRenderEndRowIndex();
			}

			if (renderStartRowIndex == -1 || renderEndRowIndex == -1) {
				return [];
			}

			let isLastContent: boolean = GridUtil._isLastContent(this._grid, renderStartRowIndex, renderEndRowIndex, GRIDREGION.CENTER, loc);
			if (isLastContent) {
				renderStartRowIndex--;
			}

			return layout.SuppressModelGenerator._genSuppressInfo(detailCellProps, mergeCellProps, suppressCellProps, hiddenSuppressCellProps, renderStartRowIndex, renderEndRowIndex, loc, this);
		}

		public _getSuppressCellInfo(loc: string, viewRowIndex: number): layout.SuppressCellInfo[] {
			if (this._suppressInfo[loc] == null) {
				return null;
			}
			if (this._suppressInfo[loc][viewRowIndex] == null) {
				return null;
			}

			return this._suppressInfo[loc][viewRowIndex].data;
		}

