namespace cpr.core {
	interface TooltipOptions {
		/** 툴팁에 화살표 표시 여부 */
		// arrow: boolean;
		/** 커서 위치에 표시되는 옵션 */
		// followCursor: boolean;
		/** 열리는 시간 */
		enterDelay: number;
		/** 닫히는 시간 */
		leaveDelay: number;
	}

	enum DataTooltipType {
		label = "aria-label",
		desc = "aria-describedby"
	}

	/**
	 * 툴팁매니저에서 사용하는 파라미터 인터페이스
	 */
	export interface TooltipOwner {
		/**
		 * 출력될 툴팁 텍스트
		 */
		tooltip: string;
		/**
		 * 툴팁을 소유한 컨트롤
		 */
		owner: any;
	}

	/**
	 * 툴팁매니저가 지원하지 않는 툴팁 소유자 타입
	 * 해당 소유자가 등록되어도 툴팁 매니저에서는 동작하지 않습니다.
	 */
	enum UnsupportTooltipOwnerType {
		/** 임베디드페이지 */
		EMBEDDEDPAGE = "embeddedpage",
		/** HTML 객체 */
		HTMLOBJECT = "htmlobject",
		/** 알림 */
		NOTIFIER = "notifier"
	}

	interface TooltipInfo {
		owner: controls.UIControl;
		render: (tooltipOwner: TooltipOwner) => controls.UIControl;
	}

	enum TooltipManagerTimer {
		open = "open",
		close = "close"
	}

	/**
	 * 커스텀 툴팁을 관리하는 매니저
	 */
	export class TooltipManager {
		private _registerControls: CMap<string, TooltipInfo>;
		private _tooltipOptions: TooltipOptions;
		// timer
		private _openTimer: utils.Timer;
		private _closeTimer: utils.Timer;
		//uicontrol
		private _tooltipArea: controls.TooltipArea;
		//events state
		private _initializedEvent: boolean = false;
		private _isDragging: boolean = false;
		private _isActivatedMousemove: boolean = false;
		//current tooltip info
		private _currentTooltipOwnerUUID: string;
		private _currentTitle: string;
		private _currentTitleElement: HTMLElement;
		//drag check
		private _dragPosition: geometry.Point;
		private _requestShowFrom: string; //반복되는 요청에서 마지막에 실행하기 위한 정보
		private _renderDefaultTooltip: (tooltipOwner: TooltipOwner) => controls.UIControl = null;

		constructor() {
			this._registerControls = _createMap<string, TooltipInfo>();
			this._tooltipOptions = {
				// arrow: false,
				// followCursor: true,
				enterDelay: 500,
				leaveDelay: 0
			}

		}

		/**
		 * 커스컴 툴팁 활성화 여부를 반환합니다.
		 * @returns 
		 */
		public _isCustomTooltipEnabled(control: controls.UIControl): boolean {
			let browserInfo = Platform.INSTANCE.browserInfo;
			if (browserInfo.isAndroid || browserInfo.isIOS) {
				return false;
			}
			if (this._isSupportedOwner(control) == false) {
				return false;
			}
			// iOS 또는 안드로이드에서는 툴팁이 표시되지 않기 때문에 커스텀 스크롤이 지원되지 않는다.
			if (this._renderDefaultTooltip != null) {
				return true;
			}
			return this._registerControls.get(control.uuid) != null;
		}

		private _getTimer(name: TooltipManagerTimer) {
			switch (name) {
				case TooltipManagerTimer.open: {
					if (!this._openTimer) {
						this._openTimer = utils.Timer.create(TooltipManagerTimer.open);
					}
					return this._openTimer;
				}
				case TooltipManagerTimer.close: {
					if (!this._closeTimer) {
						this._closeTimer = utils.Timer.create(TooltipManagerTimer.close);
					}
					return this._closeTimer;
				}
			}
		}

		private _getTooltipInfo(uuid: control_render_root_node_id) {
			let result: TooltipInfo = uuid ? this._registerControls.get(uuid) : null;
			if (!result && this._renderDefaultTooltip) {
				let control = this._lookupByUUID(uuid);
				if (control) {
					result = {
						owner: control,
						render: this._renderDefaultTooltip
					}
				}
			}
			return result;
		}

		/**
		 * 기본 툴팁 렌더를 설정합니다. 모든 컨트롤의 툴팁이 이 API에서 설정된 툴팁을 기본으로 표시합니다.
		 * @param tooltipRender 툴팁 컨텐츠를 표시하는 UI를 반환하는 함수
		 * @returns 
		 */
		public setDefaultTooltip(tooltipRender: (tooltipOwner: TooltipOwner) => controls.UIControl) {
			if (this._renderDefaultTooltip == tooltipRender) {
				return;
			}
			let oldDefaultTooltip = this._renderDefaultTooltip;
			this._renderDefaultTooltip = tooltipRender;
			let needRedraw = (oldDefaultTooltip == null && this._renderDefaultTooltip != null) || (oldDefaultTooltip != null && this._renderDefaultTooltip == null);
			if (needRedraw) {
				if (core.DeferredUpdateManager.INSTANCE._isRendering()) {
					core.DeferredUpdateManager.INSTANCE.asyncExec(() => {
						this._redrawRootApp();
					})
				} else {
					this._redrawRootApp();
				}
			}
			if (this._registerControls.size == 0) {
				if (this._renderDefaultTooltip == null) {
					this._removeEventListeners();
					this._removeTooltipAside();
				} else {
					this._setEventListeners();
					this._setTooltipAside();
				}
			}
		}

		private _setTooltipAside() {
			let rootApps = this._getRootAppInstances();
			if (rootApps.length == 0) {
				return;
			}
			if (!this._tooltipArea) {
				this._tooltipArea = new controls.TooltipArea();
			}
			rootApps.forEach((app: AppInstance) => {
				app.getContainer()._addGlobalAsideControl(this._tooltipArea);
			});
		}

		private _removeTooltipAside() {
			if (!this._tooltipArea) {
				return;
			}
			let rootApps = this._getRootAppInstances();
			rootApps.forEach((app: AppInstance) => {
				app.getContainer()._removeGlobalAsideControl(this._tooltipArea);
			});
			if (!this._tooltipArea.disposed) {
				this._tooltipArea.dispose();
			}

			this._tooltipArea = null;
		}

		/**
		 * 커스텀 툴팁을 표시할 컨트롤을 등록합니다.
		 * @param control 툴팁이 표시될 컨트롤
		 * @param tooltipRender 툴팁 컨텐츠를 표시하는 UI를 반환하는 함수
		 */
		public registerTooltip(control: cpr.controls.UIControl, tooltipRender: (tooltipOwner: TooltipOwner) => controls.UIControl) {
			let oldSize = this._registerControls.size;
			this._registerControls.set(control.uuid, {
				"owner": control,
				"render": tooltipRender
			});
			control.redraw();
			control._addInternalEventListener("dispose", this._disposeRegisteredControl);
			if (this._renderDefaultTooltip == null && oldSize == 0 && oldSize < this._registerControls.size) {
				this._setEventListeners();
				this._setTooltipAside();
			}
		}

		/**
		 * 등록된 컨트롤을 해제합니다.
		 * @param control 등록한 컨트롤
		 */
		public unregisterTooltip(control: controls.UIControl) {
			this._registerControls.delete(control.uuid);
			if (!control.disposed) {
				control.redraw();
			}
			if (this._currentTooltipOwnerUUID == control.uuid) {
				this._close(true);
			}
			control._removeInternalEventListener("dispose", this._disposeRegisteredControl);
			if (this._renderDefaultTooltip == null && this._registerControls.size == 0) {
				this._removeEventListeners();
				this._removeTooltipAside();
			}
		}

		private _dragStart(e: events.CMouseEvent) {
			if (this._isDragging) {
				this._dragEnd();
			}
			this._dragPosition = new geometry.Point(e.pageX, e.pageY);
			events.BodyEventTarget.INSTANCE._addCaptureEventListener("mouseup", this._bodyEventDispatcher);
			this._setMousemoveListener();
		}

		private _dragEnd() {
			this._isDragging = false;
			this._dragPosition = null;
			events.BodyEventTarget.INSTANCE._removeCaptureEventListener("mouseup", this._bodyEventDispatcher);
			this._removeMousemoveListener();
		}

		private _setEventListeners() {
			if (this._initializedEvent) {
				return;
			}
			events.BodyEventTarget.INSTANCE._addCaptureEventListener("mouseover", this._bodyEventDispatcher);
			events.BodyEventTarget.INSTANCE._addCaptureEventListener("mouseout", this._bodyEventDispatcher);
			events.BodyEventTarget.INSTANCE._addCaptureEventListener("mousedown", this._bodyEventDispatcher);
			events.BodyEventTarget.INSTANCE._addCaptureEventListener("keydown", this._bodyEventDispatcher);
			events.BodyEventTarget.INSTANCE._addCaptureEventListener("wheel", this._bodyEventDispatcher);
			this._initializedEvent = true;
		}

		private _removeEventListeners() {
			events.BodyEventTarget.INSTANCE._removeCaptureEventListener("mouseover", this._bodyEventDispatcher);
			events.BodyEventTarget.INSTANCE._removeCaptureEventListener("mouseout", this._bodyEventDispatcher);
			events.BodyEventTarget.INSTANCE._removeCaptureEventListener("mousedown", this._bodyEventDispatcher);
			events.BodyEventTarget.INSTANCE._removeCaptureEventListener("keydown", this._bodyEventDispatcher);
			events.BodyEventTarget.INSTANCE._removeCaptureEventListener("wheel", this._bodyEventDispatcher);
			this._initializedEvent = false;
		}

		private _setMousemoveListener() {
			if (this._isActivatedMousemove) {
				return;
			}
			events.BodyEventTarget.INSTANCE._addCaptureEventListener("mousemove", this._bodyEventDispatcher);
		}

		private _removeMousemoveListener() {
			if (this._isDragging) {
				return;
			}
			events.BodyEventTarget.INSTANCE._removeCaptureEventListener("mousemove", this._bodyEventDispatcher);
			this._isActivatedMousemove = false;
		}

		private _canRenderTooltip() {
			if (!this._tooltipArea) {
				return false;
			}
			if (this._tooltipArea.disposed) {
				return false;
			}
			let rootApps = this._getRootAppInstances();
			if (rootApps.length == 0) {
				return false;
			}
			return true;
		}

		private _bodyEventDispatcher = (e: events.CEvent) => {
			if (this._canRenderTooltip()) {
				switch (e.type) {
					case "mouseover":
						this._onmouseover(e as events.CMouseEvent);
						break;
					case "mousemove":
						this._onmousemove(e as events.CMouseEvent);
						break;
					case "mouseout":
						this._onmouseout(e as events.CMouseEvent);
						break;
					case "mousedown":
						this._onmousedown(e as events.CMouseEvent);
						break;
					case "mouseup":
						this._onmouseup(e as events.CMouseEvent);
						break;
					case "keydown":
						this._onkeydown(e as events.CKeyboardEvent);
						break;
					case "wheel":
						this._onwheel(e as events.CWheelEvent);
						break;
				}
			} else {
				// 루트 앱이 dispose되었 때 이벤트가 살아 있음.
				this._close(true);
				this._registerControls.clear();
				this._removeEventListeners();
				this._removeTooltipAside();
			}
		}

		/**
		 * 휠 동작 시 툴팁이 표시되지 않도록 하기 위해 wheel 사용
		 * @param e 
		 */
		private _onwheel(e: events.CWheelEvent) {
			if (this._requestShowFrom) {
				// 툴팁이 표시되려고 할때 휠 동작이 시작되면 휠이 끝난 후 툴팁이 표시되도록 수정.
				let tooltipInfo = this._getTooltipInfo(this._currentTooltipOwnerUUID);
				this._requestShowFrom = e.type;
				this._show(tooltipInfo, new geometry.Point(e.pageX, e.pageY));
			} else {
				this._hidden();
			}
		}
		/**
		 * 기능키 또는 키보드 동작에 따른 툴팁 액션을 정의 하기 위해 사용
		 * @param e 
		 */
		private _onkeydown(e: events.CKeyboardEvent) {
			if (e.keyCode == events.KeyCode.ESC) {
				this._hidden();
			}
		}
		/**
		 * 1.버튼 사용시 툴팁이 표시되지 않도록 하기 위해 mousedown 사용
		 * 2.드래그 동작 중에 툴팁이 표시되지 않기 위해 드래그 구현
		 * @param e 
		 */
		private _onmousedown(e: events.CMouseEvent) {
			//툴팁이 닫혀야 합니다.
			this._hidden();
			this._dragStart(e);
		}

		/**
		 * 1.버튼 사용시 툴팁이 표시되지 않도록 하기 위해 mouseup 사용
		 * 2.드래그 동작 중에 툴팁이 표시되지 않기 위해 드래그 구현
		 * @param e 
		 */
		private _onmouseup(e: events.CMouseEvent) {
			//드래그가 끝나면 툴팁을 연다
			if (this._isDragging) {
				if (this._isOpened()) {
					let tooltipInfo = this._getTooltipInfo(this._currentTooltipOwnerUUID);
					this._updateTitle(tooltipInfo);
					this._requestShowFrom = e.type
					this._show(tooltipInfo, new geometry.Point(e.pageX, e.pageY));
				} else {
					this._open(e);
				}
			} else {
				this._hidden();
			}
			this._dragEnd();
		}

		/**
		 * 툴팁이 열리는 동작을 mouseover 사용
		 * @param e 
		 */
		private _onmouseover(e: events.CMouseEvent) {
			let target = e.target as HTMLElement;
			let titleElement = this._findTitleElement(target);
			let ctrlNodeID: control_render_root_node_id = this._getControlUUID(titleElement);
			let tooltipInfo = this._getTooltipInfo(ctrlNodeID);

			if (!tooltipInfo || this._isSupportedOwner(tooltipInfo.owner) == false) {
				this._close();
				return;
			}

			if (titleElement != this._currentTitleElement) {
				this._close(true);
			}

			if (this._isOpened()) {
				this._updateTitle(tooltipInfo);
				this._requestShowFrom = e.type;
				this._setMousemoveListener();
				this._show(tooltipInfo, new geometry.Point(e.pageX, e.pageY));
			} else {
				let title = this._getTitleByElement(titleElement);

				if (this._render(tooltipInfo.render, { tooltip: title, owner: tooltipInfo.owner })) {
					this._currentTitle = title;
					this._currentTitleElement = titleElement

					this._currentTooltipOwnerUUID = ctrlNodeID;
					this._setMousemoveListener();
					this._requestShowFrom = e.type;
					this._show(tooltipInfo, new geometry.Point(e.pageX, e.pageY));
				}
			}

			// 드래그 중에는 툴팁을 열지 않는다.
			if (this._isDragging) {
				this._hidden();
			}
		}

		/**
		 * 1.mouseover로 접근 시 툴팁이 over된 위치가 아닌 마우스가 마지막에 멈춘 위치에서 표시될 수 있도록 mousemove 사용
		 * 2.드래그 상태 동작 구현을 위해 mousemove 사용
		 * @param e 
		 */
		private _onmousemove(e: events.CMouseEvent) {
			if (this._dragPosition) { // mousedown에서 dragStart호출
				let mouseButton = e.buttons ?? e.which;
				let pressLeftButton = mouseButton == 1;
				if (pressLeftButton) {
					if (this._isDragging) {
						// start IE가 슬라이더에서 드래그 중 멈추면 브라우저 툴팁이 표시되는 현상
						if (this._isOpened()) {
							core.DeferredUpdateManager.INSTANCE.asyncExec(() => {
								if (this._isChangedTitle()) {
									let tooltipInfo = this._getTooltipInfo(this._currentTooltipOwnerUUID);
									this._updateTitle(tooltipInfo);
								}
							})
						}// end IE가 슬라이더에서 드래그 중 멈추면 브라우저 툴팁이 표시되는 현상
					} else if (this._dragPosition.equals(new geometry.Point(e.pageX, e.pageY)) == false) {
						this._isDragging = true;
					}
				} else {
					if (this._isDragging) {
						this._dragEnd();
					}
				}
			} else { // mouseover에서 open을 지연하기 위해 mousemove동작
				// mouseover된 이후 툴팁이 표시되기 전에 움직이면 마우스 포인터가 멈추는 곳에서 툴팁이 표시되도록 mousemove 이벤트를 사용.
				let tooltipInfo = this._getTooltipInfo(this._currentTooltipOwnerUUID);
				this._show(tooltipInfo, new geometry.Point(e.pageX, e.pageY));
			}
		}

		/**
		 * 툴팁이 닫히는 동작을 mouseout 사용
		 * @param e 
		 */
		private _onmouseout(e: events.CMouseEvent) {
			this._close(true);
			if (e.relatedTarget) {
				let target = e.relatedTarget;
				e._setTarget(target);
				this._open(e);
				// 툴팁을 닫습니다.
				this._hidden();
			}

		}

		/**
		 * 등록된 컨트롤이 dispose될때 툴팁에 등록된 정보가 있으면 삭제하기 위한 이벤트 함수
		 * @param e 
		 */
		private _disposeRegisteredControl = (e: events.CEvent) => {
			let uicontrol = e.control as controls.UIControl;
			Platform.INSTANCE.tooltipManager.unregisterTooltip(uicontrol);
		}

		/**
		 * 현재 표시되는 툴팁의 title 속성 값이 변경 여부 반환
		 * @returns 
		 */
		private _isChangedTitle() {
			if (this._isOpened() == false) {
				return false;
			}
			let title = this._getTitleByElement(this._currentTitleElement);
			if (title != "") { //null도 변경된 값. 변경 노드 정보 변경에 따라 툴팁이 제거 될 수 있음.
				return title != this._currentTitle;
			}
			return false;
		}
		private _getRootAppInstances() {
			let rootApps = core.Platform.INSTANCE.getAllRunningAppInstances().filter(it => {
				return it.isUDCInstance() === false && it.isRootAppInstance();
			});
			return rootApps;
		}

		private _redrawRootApp() {
			let rootApps = this._getRootAppInstances();
			rootApps.forEach((each: AppInstance) => {
				each.getContainer().redraw();
			});
		}

		private _lookupByUUID(uuid: string, condition?: (lookup: controls.UIControl) => boolean) {
			let rootApps = this._getRootAppInstances();
			if (!condition) {
				condition = (lookup: controls.UIControl) => lookup != null
			}
			let control = null;
			appLoop: for (let eachRootApp of rootApps) {
				control = eachRootApp._lookupDrillDownByUUID(uuid) as controls.Grid;
				if (condition(control)) break appLoop;
			}
			return control;
		}

		/**
		 * 그리드 셀에서 그리드UUID를 찾아 컨트롤 객체를 반환합니다.
		 * @param gridCellElement 
		 * @returns 
		 */
		private _getGridControl(gridCellElement: HTMLElement) {
			let gridUUID = ufc.NodeUUIDMapper.INSTANCE._findClosestControlUUID(gridCellElement);
			let grid: controls.Grid = this._lookupByUUID(gridUUID, (control) => {
				return control && control instanceof controls.Grid;
			})
			return grid;
		}

		/**
		 * 그리드 셀에 위치하는 컨트롤을 반환합니다.
		 * @param grid 
		 * @param gridCellElement 
		 * @returns 
		 */
		private _getGridCellControl(grid: controls.Grid, gridCellElement: HTMLElement): controls.UIControl {
			let dataRole = gridCellElement.getAttribute("data-role");
			let control: controls.UIControl = null;
			let cellInfo: { rowIndex: number, cellIndex: number, vrowIndex?: number, cellRange?: number[], region?: string } = {
				rowIndex: -1, cellIndex: -1, vrowIndex: -1
			};
			let cellIndex: string = gridCellElement.getAttribute("data-cellindex");
			if (cellIndex) {
				cellInfo.cellIndex = parseInt(cellIndex);
			}
			let cellRange: string = gridCellElement.getAttribute("data-cellrange");
			if (cellRange) {
				let cellRanges: number[] = cellRange.split(",").map((cellIdx: string) => {
					return parseInt(cellIdx);
				});
				cellInfo.cellRange = cellRanges;
			}
			let domTraverser = ufc._traverseFromElement(gridCellElement)._parent(`[role="${controls.GRIDROLE.ROW}"]`);
			if (domTraverser) {
				let rowIndex: string = domTraverser._getAttribute("data-rowindex");
				if (rowIndex) {
					cellInfo.rowIndex = parseInt(rowIndex);
				}
				let vrowIndex: string = domTraverser._getAttribute("data-vrowindex");
				if (vrowIndex) {
					cellInfo.vrowIndex = parseInt(vrowIndex);
				}
				let region: string = domTraverser._getAttribute("data-region");
				if (region) {
					cellInfo.region = region;
				}
			}

			switch (dataRole) {
				case controls.GRIDROLE.COLUMN_HEADER: {
					if (cellInfo.cellIndex != -1) {
						control = grid.header.getColumn(cellInfo.cellIndex).control
					}
					break;
				}
				case controls.GRIDROLE.GRID_CELL: {
					if (cellInfo.cellIndex != -1 && cellInfo.rowIndex != -1) {
						control = grid.detail.getColumn(cellInfo.cellIndex).control;
					}
					break;
				}
				case controls.GRIDROLE.GRID_ROWGROUP_CELL: {
					if (cellInfo.cellIndex != -1 && cellInfo.vrowIndex != -1) {
						let gridRowGroup: controls.provider.GridRowGroup = grid.getContentRow(cellInfo.vrowIndex) as controls.provider.GridRowGroup;
						let gridRowGroupBand: controls.gridpart.GridRowGroupBand = grid.getRowGroup(gridRowGroup.groupCondition, cellInfo.region as ("gheader" | "gfooter"));
						control = gridRowGroupBand.getControl(cellInfo.cellIndex);
					}
					break;
				}
				case controls.GRIDROLE.FOOTER_CELL: {
					if (cellInfo.cellIndex != -1) {
						control = grid.footer.getColumn(cellInfo.cellIndex).control;
					}
					break;
				}
			}
			return control;
		}

		/**
		 * target에 인접한 컨트롤의 UUID를 반환합니다.
		 * @param target 
		 * @returns 
		 */
		private _getControlUUID(target: HTMLElement): control_uuid {
			if (!target) {
				return null;
			}

			let uuid: control_uuid = null;
			let gridCellElement = this._findGridCellElement(target);
			if (gridCellElement != null) {
				let grid = this._getGridControl(gridCellElement);
				if (gridCellElement == target) {
					uuid = grid.uuid;
				} else {
					let gridCellControl = this._getGridCellControl(grid, gridCellElement);
					if (gridCellControl) {
						uuid = gridCellControl.uuid;
					} else {
						uuid = grid.uuid;
					}
				}
			} else {
				uuid = ufc.NodeUUIDMapper.INSTANCE._findClosestControlUUID(target);
			}

			return uuid;
		}

		/**
		 * 툴팁을 툴팁 영역에 위치와 크기를 계산하기 위해 먼저 렌더링합니다.
		 * @param render 
		 * @param tooltipOwner 
		 * @returns 
		 */
		private _render(render: (tooltipOwner: TooltipOwner) => controls.UIControl, tooltipOwner: TooltipOwner) {
			let tooltip = render(tooltipOwner);
			if (!tooltip) {
				return false;
			}
			this._tooltipArea._setTooltip(tooltip);
			this._tooltipArea._updateTooltipStyle({
				top: "0px",
				left: "0px",
				height: "auto",
				width: "auto"
			});
			return true;
		}

		/**
		 * 툴팁 영역에 툴팁이 설정되어 있으면 툴팁이 열려 있는 상태여부를 반환합니다.
		 * @returns 
		 */
		private _isOpened() {
			if (!this._tooltipArea) {
				return false;
			}
			return this._tooltipArea._getTooltip() != null;
		}

		/**
		 * 툴팁이 화면에 표시되는 상태여부를 반환합니다.
		 * @returns 
		 */
		private _isShowing() {
			if (!this._tooltipArea) {
				return false;
			}
			return this._tooltipArea._isShowingTooltip();
		}

		/**
		 * 그리드 셀 엘리먼트를 찾습니다.
		 * @param target 
		 * @returns 
		 */
		private _findGridCellElement(target: HTMLElement): HTMLElement {
			let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(target);
			domTraverser = domTraverser._closest(`[data-role="${controls.GRIDROLE.COLUMN_HEADER}"], [data-role="${controls.GRIDROLE.GRID_CELL}"], [data-role="${controls.GRIDROLE.GRID_ROWGROUP_CELL}"], [data-role="${controls.GRIDROLE.FOOTER_CELL}"]`);
			return domTraverser?._getElement();
		}

		/**
		 * 툴팁이 표시될 위치와 크기를 계산하여 css style로 반환합니다.
		 * @param point 
		 * @returns 
		 */
		private _calculateBoundsStyle(point: geometry.Point): { [key: string]: string } {
			if (this._isOpened() == false) {
				return;
			}

			let tooltipBounds = this._tooltipArea._getTootipUnscaledActualRect();
			tooltipBounds.x = point.x;
			tooltipBounds.y = point.y;
			tooltipBounds.translate(10, 15); // 브라우저 툴팁과 유사한 위치
			let container = this._tooltipArea.getParent();
			let useBodyScroll = container._useBodyScroll();
			let viewportRect: geometry.Rectangle = container.getViewPortRect();
			if (!useBodyScroll) {
				viewportRect.x = 0;
				viewportRect.y = 0;
			}
			let overflowWidth = false;
			let overflowHeight = false;
			if (viewportRect.width < tooltipBounds.width) {
				tooltipBounds.width = viewportRect.width;
				this._tooltipArea._getRenderer().updateStyle("tooltip", {
					"max-width": `${tooltipBounds.width}px`
				}, true);
				tooltipBounds.height = this._tooltipArea._getTootipUnscaledActualRect().height;
				overflowWidth = true;
			}

			if (viewportRect.height < tooltipBounds.height) {
				tooltipBounds.height = viewportRect.height;
				overflowHeight = true;
			}
			if (viewportRect.right < tooltipBounds.right) {
				tooltipBounds.x = tooltipBounds.left - (tooltipBounds.right - viewportRect.right);
			}
			if (viewportRect.bottom < tooltipBounds.bottom) {
				tooltipBounds.y = tooltipBounds.top - (tooltipBounds.bottom - viewportRect.bottom);
			}
			let style = {
				left: "0px",
				top: "0px",
				width: "auto",
				height: "auto",
				transform: `translate(${Math.round(tooltipBounds.left)}px, ${Math.round(tooltipBounds.top)}px)`
			}
			if (overflowWidth) style['max-width'] = `${tooltipBounds.width}px`;
			if (overflowHeight) style['max-height'] = `${tooltipBounds.height}px`;

			return style;
		}

		/**
		 * 현재 툴팁을 열려 있는 상태는 유지하고 숨깁니다.
		 * @returns 
		 */
		private _hidden() {
			if (!this._isOpened()) {
				return;
			}
			this._tooltipArea._updateTooltipStyle({
				top: "0px",
				left: "0px",
				height: "auto",
				width: "auto"
			});
			this._getTimer(TooltipManagerTimer.open).cancel();
			this._removeMousemoveListener();
			this._tooltipArea._hiddenTooltip();
		}

		/**
		 * title 속성을 갖는 엘리먼트를 찾습니다.
		 * @param target 
		 * @param root 
		 * @param rootClassNames 
		 * @returns 
		 */
		private _findTitleElement(target: HTMLElement): HTMLElement {
			let domTraverser = ufc._traverseFromElement(target as HTMLElement);
			return domTraverser._closest('[title], [data-tooltip]')?._getElement();
		}

		/**
		 * title속성이나 태그에서 텍스트를 반환합니다.
		 * @param element 
		 * @returns 
		 */
		private _getTitleByElement(element: HTMLElement): string {
			let tooltipRef = element.getAttribute("data-tooltip");
			if (!tooltipRef) {
				return null;
			}
			let attrName = DataTooltipType[tooltipRef];
			if (attrName == DataTooltipType.label) {
				return element.getAttribute(attrName);
			} else if (attrName == DataTooltipType.desc) {
				let id = element.getAttribute(attrName);
				if (!id) {
					return null;
				}
				let ele = document.getElementById(id);
				return ele?.textContent;
			}
			return null;
		}

		/**
		 * 지원되는 컨트롤인지 반환합니다.
		 * @param owner 
		 * @returns 
		 */
		private _isSupportedOwner(owner: controls.UIControl): boolean {
			if (_.values(UnsupportTooltipOwnerType).indexOf(owner.type as any) > -1) {
				return false;
			}
			return true;
		}

		/**
		 * 툴팁을 엽니다.
		 * @param e 
		 */
		private _open(e: events.CMouseEvent): void {
			let target = e.target as HTMLElement;
			let titleElement = this._findTitleElement(target);
			let uuid: string = this._getControlUUID(titleElement);
			let tooltipInfo = this._getTooltipInfo(uuid);
			if (!tooltipInfo || this._isSupportedOwner(tooltipInfo.owner) == false) {
				this._close();
				return;
			}
			if (!this._isOpened()) {

				let title = this._getTitleByElement(titleElement);
				if (this._render(tooltipInfo.render, { tooltip: title, owner: tooltipInfo.owner })) {
					this._currentTitle = title;
					this._currentTitleElement = titleElement;

					this._currentTooltipOwnerUUID = uuid;
					this._setMousemoveListener();
				}
			}
			if (this._isOpened() && !this._isShowing()) {
				this._requestShowFrom = e.type;
				this._show(tooltipInfo, new geometry.Point(e.pageX, e.pageY));
			}
		}

		/**
		 * hidden 된 툴팁을 보이도록 합니다.
		 * @param tooltipInfo 
		 * @param point 
		 * @returns 
		 */
		private _show(tooltipInfo: TooltipInfo, point: geometry.Point): void {
			if (!this._isOpened()) {
				return;
			}
			let openTimer = this._getTimer(TooltipManagerTimer.open);
			openTimer.init((timer) => {
				if (!this._isOpened() && tooltipInfo.owner.disposed) {
					return;
				}
				_workUnscale((zoom) => {
					point = point.scale(1 / zoom);
				})

				let boundsStyle = this._calculateBoundsStyle(point);
				this._tooltipArea._updateTooltipStyle(boundsStyle);
				// 애니메이션 동작이 필요한 경우 표시될때 클래스 추가.
				// this._tooltipArea.updateTooltipClasses(["cl-animation"]);
				this._tooltipArea._showTooltip();
				this._removeMousemoveListener();
				this._requestShowFrom = null;
			}).schedule(this._tooltipOptions.enterDelay);
		}

		/**
		 * 현재 열려있는 툴팁의 타이틀을 업데이트합니다.
		 * @param tooltipInfo 
		 * @returns 
		 */
		private _updateTitle(tooltipInfo: TooltipInfo): void {
			if (!this._isOpened()) {
				return;
			}
			if (this._currentTitleElement && this._currentTitle) {
				let title = this._getTitleByElement(this._currentTitleElement);
				if (title && this._currentTitle != title) {
					if (this._render(tooltipInfo.render, { tooltip: title, owner: tooltipInfo.owner })) {
						this._currentTitle = title;
					}
				}
			}
		}

		/**
		 * open된 툴팁을 닫습니다.
		 * @param immediate 
		 * @returns 
		 */
		private _close(immediate: boolean = false): void {
			if (!this._isOpened()) {
				return;
			}
			// 그리드인 경우 다른 셀인지 체크 추가.
			let closeTimer = this._getTimer(TooltipManagerTimer.close);
			closeTimer.init(() => {
				this._tooltipArea._clearTooltip();
				this._clearTooltip();
			}).schedule(this._tooltipOptions.leaveDelay);

			if (immediate) {
				closeTimer.scheduleRun();
			}
		}
		/**
		 * 현재 열려 있는 툴팁 정보를 제거합니다.
		 */
		private _clearTooltip() {
			this._currentTitle = null;
			this._currentTitleElement = null;
			this._currentTooltipOwnerUUID = null;
			this._requestShowFrom = null;
			this._getTimer(TooltipManagerTimer.open).cancel();
			this._removeMousemoveListener();
		}

	}
}