/// <reference path="./HorizontalBar.ts" />
namespace cpr.controls.navigation {

	/**
	 * @private
	 */
	export class FullMenuBar extends HorizontalBar implements INavigationBar {

		/**
		 * 내비게이션 바를 생성합니다.
		 * @param id 내비게이션 바의 id
		 */
		constructor(owner: NavigationBar, binder: provider.MenuDataBinder) {
			super(owner, binder);

		}

		/* shape */
		protected override _createPopupMenu(): ufc.ElementShape {
			let popupMenu = super._createPopupMenu();
			if (popupMenu == null) {
				return null;
			}

			let menu = this._getActiveMenu();

			let oldGlobalShape = this._owner._getRenderer()._getNamedShape(menu.getRootNodeName());
			if (oldGlobalShape != null) {
				if (oldGlobalShape.style["width"] != null) {
					popupMenu.style["width"] = oldGlobalShape.style["width"];
				}
			} else {
				let domTraverser = ufc._traverseFromElement(this._owner._getRenderer().getRootNode());
				if (domTraverser) {
					popupMenu.style["width"] = domTraverser._getElement().offsetWidth + "px";
				}
			}

			return popupMenu;
		}

		protected override _getMenuItems(): MenuItem[] {
			let doOpenItem = this._getOpenedItem();
			if (doOpenItem == null || !this._isOpened(doOpenItem)) {
				return [];
			}
			return this._getRootItems();
		}

		protected override _getHover() {
			let menu = this._getActiveMenu();
			let hover = null;
			if (menu) {
				hover = menu.getHoveredItem();
			}
			let isOpenedMenuHover = hover && this._getOpenedItem() != null;
			if (!isOpenedMenuHover) {
				return this._getHoveredItem();
			}
			return hover;
		}
		/**
		 * 일반 메뉴에서 키 바인드
		 * @param e 
		 */
		protected _navigateBar(e: events.CKeyboardEvent, item: MenuItem) {
			super._navigateBar(e, item);

			let menu = null;
			if (this._getOpenedItem() != null) {
				menu = this._getActiveMenu();
			}
			let keyCode = e.keyCode;
			switch (keyCode) {
				case events.KeyCode.LEFT:
					e.preventDefault();
					if (item == null) {
						this._hoverBackward(item);
					} else if (item.depth > 0) {
						let traversedHover = menu ? menu.traverseHover(keyCode, item) : null;

						if (!traversedHover) {

							let rootItem = this._getParent(item, (each) => {
								return each.depth == 0;
							})
							this._hoverBackward(rootItem, { loop: false, nativeEvent: e });
						} else {
							this._setHoveredItem(traversedHover, { doInitSubMenu: false, nativeEvent: e });
						}
					} else {
						this._hoverBackward(item, { doInitSubMenu: false, nativeEvent: e });
						if (menu) {
							menu._setHoveredItem(null);
						}
					}
					break;
				case events.KeyCode.RIGHT: {
					e.preventDefault();
					if (item == null) {
						this._hoverForward(item);
					} else if (item.depth > 0) {
						let traversedHover = menu ? menu.traverseHover(keyCode, item) : null;
						if (!traversedHover) {

							let rootItem = this._getParent(item, (each) => {
								return each.depth == 0;
							})
							this._hoverForward(rootItem, { loop: false, nativeEvent: e });

						} else {
							this._setHoveredItem(traversedHover, { doInitSubMenu: false, nativeEvent: e });
						}
					} else {
						this._hoverForward(item, { doInitSubMenu: false, nativeEvent: e });
						if (menu) {
							menu._setHoveredItem(null);
						}
					}
					break;

				}
				case events.KeyCode.UP:
					e.preventDefault();
					if (item == null) break;

					if (item.depth > 0) {
						let traversedHover = menu ? menu.traverseHover(keyCode, item) : null;
						if (!traversedHover) {
							this._traverseTabKey(false, item, e);
						}
					} else if (item._hasChild()) {
						let traversedHover = menu ? menu._transferHoverBackward(item) : null;
						if (!traversedHover) {
							this._traverseTabKey(false, item, e);
						}
					} else {
						this._traverseTabKey(false, item, e);
					}
					break;
				case events.KeyCode.DOWN: {
					e.preventDefault();
					if (item == null) break;

					if (item.depth > 0) {
						let traversedHover = menu ? menu.traverseHover(keyCode, item) : null;
						if (!traversedHover) {
							this._traverseTabKey(true, item, e);
						}

					} else if (item._hasChild()) {
						let traversedHover = menu ? menu._transferHoverDownCycle(item) : null;
						if (!traversedHover) {
							this._traverseTabKey(true, item, e);
						}
					} else {
						this._hoverForward(item);
					}
					break;
				}
				case events.KeyCode.TAB: {
					if (this._owner.tabTraversal == false) {
						return;
					}

					if (this._traverseTabKey(!e._getMod2Key(), item, e)) {
						e.preventDefault();
						return;
					}
					break;
				}
			}

		}

		/* private method */
		/* event start */
		private _traverseTabKey(forward: boolean, item: MenuItem, nativeEvent: events.CKeyboardEvent) {
			if (forward == false && item == null) {
				return false;
			}

			let root = new cpr.controls.MenuItem("", "@root", "");
			root._setChildren(this._getRootItems());
			root._setOpen(true);
			let items = [];
			let enabledRootItem = root.children.find((each: MenuItem) => {
				return this._owner.getItemEnable(each) == true;
			})
			if (!enabledRootItem) {
				return false;
			}

			let isOpened = this._getOpenedItem() != null;
			items = _createTreeStream(root, false, (each: MenuItem) => {
				if ((each.value != "@root" && each.parentItem == null) && isOpened == false) {
					return [];
				}
				return each.children;
			}).collect() as MenuItem[];

			let findIndex = forward ? -1 : items.length;
			if (item) {
				findIndex = _.findIndex(items, (each) => {
					return each.value == item.value;
				});
			}
			let len = items.length;
			let delta = forward ? 1 : -1;
			let i = findIndex + delta;
			let nextItem = null;
			while (len > i || i < 0) {
				if (this._owner.getItemEnable(items[i])) {
					nextItem = items[i];
					i = len;
				} else {
					i = i + delta;
				}
			}

			if (!nextItem) {
				return false;
			}

			this._setHover(nextItem, { doInitSubMenu: nextItem.depth == 0, nativeEvent: nativeEvent });
			return true;
		}

		/**
		 * expanderTrigger=[hover,click]에 item-mouseover 이벤트를 발생시킵니다.
		 * @param e 
		 * @returns 
		 */
		protected override _onmouseover(e: MouseEvent) {
			let rootElement: HTMLElement = <HTMLElement>e.currentTarget;
			let eventElement: HTMLElement = <HTMLElement>e.target;

			let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(eventElement)._closest("[data-role='menuitem']", rootElement);
			if (domTraverser == null) {
				return;
			}

			let item: MenuItem = this._getItemByElement(domTraverser._getElement());
			if (item == null) {
				throw new cpr.exceptions.CError("The item does not exist.");
			}
			let isSameItemMouseOver = this._beforeMouseoverItem?._equalsValue(item) ?? false;
			// dispatchItemMouseover에서 _beforeMouseoverItem 값 갱신
			if (!this._dispatchItemMouseover(item, e) || this._owner.expandTrigger == "click") {
				return;
			}

			if (this._owner.getItemEnable(item)) {
				if (!isSameItemMouseOver) {
					this._setOpen(item, { nativeEvent: e });
				}

				if (this._isHoveredItem(item) == false) {
					let hoveredBarItem = this._getHoveredItem();
					let hoveredMenuItem = null;
					if (hoveredBarItem) {
						let menu = this._getActiveMenu();
						if (menu) {
							hoveredMenuItem = menu.getHoveredItem();
						}
					}
					let hasHover = hoveredBarItem != null || hoveredMenuItem != null;
					this._setHoveredItem(item, { doInitSubMenu: !hasHover, updateScroll: false, nativeEvent: e, preventOpen: true });
				}
			}
		}

		protected override _onMenuItemMouseOver(e: events.CItemEvent) {
			this._owner.dispatchEvent(e);
			let rootItem = this._getParent(e.item, (each) => {
				return each.parentItem == null;
			})
			this._setHoveredItem(rootItem, { doInitSubMenu: false, updateScroll: false, nativeEvent: e });
		}

	}
}