

namespace cpr.controls.internal {
	/**
	 * @private
	 */
	export class VirtualHScrollbar implements IVirtualHScrollbar {
		private _hscrollbar: IVirtualHScrollbar;


		constructor(scrollPane: internal.IVirtualScrollPane) {
			this._hscrollbar = new CustomHScrollbar(scrollPane);
		}

		public _getHeight(): number {
			return this._hscrollbar._getHeight();
		}

		public _getScrollLeft(): number {
			return this._hscrollbar._getScrollLeft();
		}

		public _setScrollLeft(scrollLeft: number): void {
			this._hscrollbar._setScrollLeft(scrollLeft);
		}

		public _createScrollbar(contentScrollLeft: number, contentWidth: number): ufc.ElementShape {
			return this._hscrollbar._createScrollbar(contentScrollLeft, contentWidth);
		}
	}
}