namespace cpr {
	/**
	 * 확대 수준에 따라 스크롤 값이 소수점으로 설정됩니다.
	 * 최대 스크롤 계산식인 clientWidth와 scrollWidth는 정수로만 출력되어 오차가 발생하여 범위를 2로 정함.
	 * 아이템 단위로 이동되는 스크롤 동작에서 사용하세요. 
	 * 사용용도: 스크롤 끝 여부에 맞추어 커스텀 스크롤 버튼의 상태 변경
	 * @param scrollElement 
	 * @param scrollPaneElement 
	 * @param scrollX 
	 * @returns 
	 */
	export function _testScrollMaxX(scrollElement: HTMLElement): boolean {
		let tolterance = 2; // setZoom(1.2)했을 시 scrollLeft와의 차이가 2정도 발생.
		let isAtScrollEnd = Math.abs(scrollElement.scrollLeft - (scrollElement.scrollWidth - scrollElement.clientWidth)) <= tolterance;
		return isAtScrollEnd;
	}

	/**
	 * 가로 스크롤의 최대 크기를 반환합니다.
	 * 최대 스크롤 계산식인 scrollWidth - clientWidth는 정수로만 출력되어 오차 범위가 작습니다.
	 * @param scrollElement 
	 * @param scrollPaneElement 
	 * @returns 
	 */
	export function _getScrollMaxX(scrollElement: HTMLElement): number {
		return Math.round(scrollElement.scrollWidth - scrollElement.clientWidth);
	}

	/**
	 * 확대 수준에 따라 스크롤 값이 소수점으로 설정됩니다.
	 * 최대 스크롤 계산식인 clientHeight와 scrollHeight는 정수로만 출력되어 오차가 발생하여 범위를 2로 정함.
	 * 아이템 단위로 이동되는 스크롤 동작에서 사용하세요. 
	 * 사용용도: 스크롤 끝 여부에 맞추어 커스텀 스크롤 버튼의 상태 변경
	 * @param scrollElement 
	 * @param scrollPaneElement 
	 * @param scrollX 
	 * @returns 
	 */
	export function _testScrollMaxY(scrollElement: HTMLElement): boolean {
		let tolterance = 2; // setZoom(1.2)했을 시 scrollTop와의 차이가 2정도 발생.
		let isAtScrollEnd = Math.abs(scrollElement.scrollTop - (scrollElement.scrollHeight - scrollElement.clientHeight)) <= tolterance;
		return isAtScrollEnd;
	}

	/**
	 * 세로 스크롤의 최대 크기를 반환합니다.
	 * 최대 스크롤 계산식인 scrollHeight - clientHeight는 정수로만 출력되어 오차 범위가 작습니다.
	 * @param scrollElement 
	 * @param scrollPaneElement 
	 * @returns 
	 */
	export function _getScrollMaxY(scrollElement: HTMLElement): number {
		return Math.round(scrollElement.scrollHeight - scrollElement.clientHeight);
	}

	type ScrollIntoViewOptions = {
		verticalAlign?: "start" | "center" | "end" | "nearest",
		horizontalAlign?: "start" | "center" | "end" | "nearest"
	};

	/**
	 * 뷰 포트 내부에 있는 엘리먼트를 스크롤합니다.
	 * IE에서는 scrollIntoView()가 지원되지 않기 때문에 직접 구현합니다.
	 * @param scrollElement 
	 * @param scrollPaneElement 
	 * @param scrollIntoViewOptions 
	 */
	export function _scrollIntoView(scrollElement: HTMLElement, scrollPaneElement: HTMLElement, scrollIntoViewOptions?: ScrollIntoViewOptions): void {
		let verticalOption: any = scrollIntoViewOptions?.verticalAlign ?? "start";
		let horizontalOption: any = scrollIntoViewOptions?.horizontalAlign ?? "nearest";

		if (_isIE()) {
			switch (verticalOption) {
				case "start":
					scrollPaneElement.scrollTop = Math.max(0, scrollElement.offsetTop);
					break;
				case "center":
					scrollPaneElement.scrollTop = Math.max(0, scrollElement.offsetTop - (scrollPaneElement.clientHeight / 2) + (scrollElement.clientHeight / 2));
					break;
				case "end":
					scrollPaneElement.scrollTop = Math.max(0, scrollElement.offsetTop - scrollPaneElement.clientHeight + scrollElement.clientHeight);
					break;
				case "nearest":
					if (scrollPaneElement.scrollTop < scrollElement.offsetTop &&
						(scrollElement.offsetTop + scrollElement.clientHeight) - scrollPaneElement.scrollTop < scrollPaneElement.clientHeight) {
						break;
					}
					if (scrollPaneElement.scrollTop < scrollElement.offsetTop) {
						scrollPaneElement.scrollTop = Math.max(0, scrollElement.offsetTop - scrollPaneElement.clientHeight + scrollElement.clientHeight);
					} else {
						scrollPaneElement.scrollTop = Math.max(0, scrollElement.offsetTop);
					}
					break;
			}
			switch (horizontalOption) {
				case "start":
					scrollPaneElement.scrollLeft = Math.max(0, scrollElement.offsetLeft);
					break;
				case "center":
					scrollPaneElement.scrollLeft = Math.max(0, scrollElement.offsetLeft - (scrollPaneElement.clientWidth / 2) + (scrollElement.clientWidth / 2));
					break;
				case "end":
					scrollPaneElement.scrollLeft = Math.max(0, scrollElement.offsetLeft - scrollPaneElement.clientWidth + scrollElement.clientWidth);
					break;
				case "nearest":
					if (scrollPaneElement.scrollLeft < scrollElement.offsetLeft &&
						(scrollElement.offsetLeft + scrollElement.clientWidth) - scrollPaneElement.scrollLeft < scrollPaneElement.clientWidth) {
						break;
					}
					if (scrollPaneElement.scrollLeft < scrollElement.offsetLeft) {
						scrollPaneElement.scrollLeft = Math.max(0, scrollElement.offsetLeft - scrollPaneElement.clientWidth + scrollElement.clientWidth);
					} else {
						scrollPaneElement.scrollLeft = Math.max(0, scrollElement.offsetLeft);
					}
					break;
			}
		} else {
			scrollElement.scrollIntoView({
				block: verticalOption,
				inline: horizontalOption
			});
		}
	}
}