// /// <reference path="./CEvent.ts"/>

/// <reference path="./DOMEventWrapper.ts" />


namespace cpr.events {
	/**
	 * 속성이 바뀔 시 발생하는 이벤트.
	 */
	export class CPropertyChangeEvent extends CEvent {
		private _property: string
		private _oldValue: any
		private _newValue: any

		/**
		 * 속성 변경 이벤트를 생성합니다.
		 * @param property 속성 명.
		 * @param oldValue 이전 속성의 값
		 * @param newValue 변경된 속성의 값.
		 */
		constructor(property: string, oldValue: any, newValue: any) {
			super("property-change")
			this._property = property
			this._oldValue = oldValue
			this._newValue = newValue
		}

		/**
		 * 속성 이름을 반환합니다.
		 * @return 속성명.
		 */
		public get property(): string {
			return this._property;
		}

		/**
		 * 이전 값을 반환합니다.
		 * @return 이전 값.
		 */
		public get oldValue(): any {
			return this._oldValue
		}

		/**
		 * 새로운 값을 반환합니다.
		 * @return 새로운 값.
		 */
		public get newValue(): any {
			return this._newValue
		}
	}
}