/// <reference path="./BrowserInfo.ts" />

namespace cpr.utils {


	/**
	 * 일반 유틸리티 함수들을 제공합니다.
	 * @noinstance
	 */
	export class Util {

		/**
		 * 다양한 값을 string으로 변경하여 변환합니다. null인 경우 empty string으로 반환합니다.
		 * @param value 
		 */
		static toString(value: any): string {
			if (value == null) {
				return "";
			} else if (typeof value == "string") {
				return value;
			} else if (value instanceof foundation.DecimalType) {
				return (value as foundation.DecimalType).toString();
			}
			return String(value);
		}

		/**
		 * 다양한 값을 number로 변경하여 변환합니다. 변환이 안돼는 값은 NaN으로 반환합니다.
		 * @param value 
		 */
		static toNumber(value: any): number {
			if (typeof (value) == "string") {
				value = value.replace(/,/g, "");
			}
			return Number(value);
		}

		/**
		 * 다양한 값을 boolean으로 변경하여 반환합니다. 숫자 0은 false 입니다. 객체는 true입니다. empty string은 false 입니다.
		 * @param value 
		 */
		static toBoolean(value: any): boolean {
			return Boolean(value);
		}

		/**
		 * NodeList, FileList, 문자열 등을 배열로 변환합니다.
		 * @param values 
		 */
		static toArray(values: any): any[] {
			return _toArray(values);
		}

		/**
		 * 주어진 배열이나 문자열이 null이거나 비어있는지 여부를 반환합니다.
		 * @param value 문자열 혹은 배열.
		 */
		static isNullOrEmpty(value: any): boolean {
			return _isNullOrEmpty(value);
		}

		/**
		 * 주어진 숫자나 문자열이 정수인지 여부를 반환합니다.
		 * @param value 숫자 혹은 문자열.
		 */
		static isIntegerLike(value: any): boolean {
			const num = Number(value);
			return !isNaN(num) && Util.isInteger(num);
		}

		/**
		 * 주어진 숫자가 정수인지 여부를 반환합니다.
		 * IE에서 Number.isInteger 지원하지 않음.
		 * @param value 숫자.
		 * @returns 숫자인지 여부.
		 */
		static isInteger(value: any): boolean {
			if (!Number.isInteger) {
				return typeof value === "number" &&
					isFinite(value) &&
					Math.floor(value) === value;
			} else {
				return Number.isInteger(value);
			}
		}

		/**
		 * 배열에서 맵핑 함수를 사용한 결과값이 가장 작은 요소를 찾습니다.
		 * @param array 배열
		 * @param mapper 맵핑 함수.
		 */
		public static minBy<T>(array: T[], mapper: (e: T) => number): T {
			var mappedValues = array.map(mapper);
			let minValue = Math.min.apply(Math, mappedValues);
			return array[mappedValues.indexOf(minValue)];
		}

		/**
		 * 배열에서 맵핑 함수를 사용한 결과값이 가장 큰 요소를 찾습니다.
		 * @param array 배열
		 * @param mapper 맵핑 함수.
		 */
		public static maxBy<T>(array: T[], mapper: (e: T) => number): T {
			var mappedValues = array.map(mapper);
			let maxValue = Math.max.apply(Math, mappedValues);
			return array[mappedValues.indexOf(maxValue)];
		}

		/**
		 * number 배열의 합을 구합니다.
		 * @param values number 배열.
		 */
		public static sum(values: number[]): number {
			let value: number = 0;
			for (let idx: number = 0; idx < values.length; idx++) {
				value += values[idx];
			}
			return value;
		}

		/**
		 * 템플릿을 이용하여 문자열을 생성합니다.
		 * 
		 * @param template 템플릿 표현식 "${변수}" 형식의 변수들을 포함할 수 있는 문자열입니다.
		 * @param locals 변수의 값을 공급할 객체입니다.
		 */
		public static template(template: string, locals: any) {
			let compiledTemplate = StringUtil.compileTemplate(template)
			return compiledTemplate(locals)
		}

		/**
		 * 브라우저 정보 객체를 얻습니다.
		 */
		public static detectBrowser(): utils.BrowserInfo {
			return _detectBrowser();
		}

		/**
		 * 패키지 용도로 사용할 JSON 객체를 확보합니다.
		 * @param packageName 패키지 명.
		 */
		public static ensurePackage(packageName: string): any {
			let finger = window;
			packageName.split(".").forEach(function (seg) {
				finger[seg] = finger[seg] || {};
				finger = finger[seg];
			});
			return finger;
		}

		/**
		 * 최소 값 및 최대 값을 이용하여 입력 값을 클램프 합니다.
		 * @param value 입력 값.
		 * @param min 최소 값. 입력 값이 이 값보다 작으면 이 값이 리턴됩니다.
		 * @param max 최대 값. 입력 값이 이 값보다 크면 이 값이 리턴됩니다.
		 */
		public static clamp(value: number, min: number, max: number) {
			return Math.min(Math.max(min, value), max);
		}

		/**
		 * 해당 속성 기술자가 쓰기 가능한 속성인지 확인합니다.
		 * @param descriptor 속성 기술자.
		 * @returns 쓰기가 허용되어 있는지 여부.
		 */
		public static _isUserWritableProperty(descriptor: PropertyDescriptor): boolean {
			if (!descriptor) {
				return false;
			}

			return typeof descriptor.set == "function" || descriptor.writable;
		}

		/**
		 * 현재 값에서 숫자값만 추출하여 반환합니다.
		 * @param text 
		 */
		public static _getNumberText(text: string): string {
			// CHECK 필요
			if (text == null) {
				return null;
			}
			let numberText: string = text.replace(/[^\-0-9]/g, "");
			if (numberText.length > 2) {
				let firstValue: string = numberText.substring(0, 1); // '-' or number
				let remainderValue: string = numberText.substring(1, numberText.length);
				remainderValue = remainderValue.replace(/[^0-9]/g, "");
				return firstValue + remainderValue;
			} else {
				if (numberText == "-") {
					return numberText + "0"; // -0
				} else {
					return numberText;
				}
			}

		}
	}
}

