/// <reference path="../../utils/StringUtil.ts"/>
/// <reference path="../Submission.ts"/>
/// <reference path="./URLEncodedRequestBuilder.ts"/>


namespace cpr.protocols.request {
	/**
	 * @private
	 */
	export class FormRequestBuilder extends URLEncodedRequestBuilder {
		private static readonly _framewrappername: string = "framewrp_" + _generateUUID(); // div / iframe
		private static readonly _framename: string = "frame_" + _generateUUID(); // iframe
		private static readonly _formname: string = "form_" + _generateUUID(); // form


		constructor() {
			super();
		}

		public getContentType(): string {
			return Submission.MEDIA_URLENCODED;
		}

		protected _buildSpecific(submission: Submission): any {
			this._init();

			let formTag: HTMLFormElement = this._getFormElement();
			// method
			formTag.method = submission.method;
			formTag.action = submission.getRequestActionUrl();
			formTag.enctype = this.getContentType();

			let browserInfo: utils.BrowserInfo = core.Platform.INSTANCE.browserInfo;
			if (browserInfo.mobile) {
				formTag.target = "_blank";
			} else {
				formTag.target = FormRequestBuilder._framename;
			}

			let requestMediaType: string = submission.mediaType;
			let requestEncoderSpec: RequestEncoderSpec = submission._getRequestEncoder();

			if (requestEncoderSpec && requestEncoderSpec.encoder) {
				let requestData: string | JSONRequestObject = null;

				if (requestEncoderSpec.usingBuildData) {
					switch (requestMediaType) {
						case Submission.MEDIA_URLENCODED:
						case Submission.MEDIA_URLENCODED_MASS: {
							let requestBuilder: URLEncodedRequestBuilder = new URLEncodedRequestBuilder();
							requestData = requestBuilder._buildRequestString(submission);
							break;
						}
						case Submission.MEDIA_URLENCODED_SIMPLE: {
							let requestBuilder: URLEncodedSimpleRequestBuilder = new URLEncodedSimpleRequestBuilder();
							requestData = requestBuilder._buildRequestString(submission);
							break;
						}
						case Submission.MEDIA_JSON: {
							let requestBuilder: JSONRequestBuilder = new JSONRequestBuilder();
							requestData = requestBuilder._buildJsonRequestObject(submission);
							break;
						}
						case Submission.MEDIA_MULTIPART:
						case Submission.MEDIA_MULTIPART_JSON:
						case Submission.MEDIA_MULTIPART_SIMPLE:
							throw new exceptions.IllegalStateException("filedownload responseType is not support multipart request");
						default: {
							let requestBuilder: URLEncodedRequestBuilder = new URLEncodedRequestBuilder();
							requestData = requestBuilder._buildRequestString(submission);
						}
					}
				}
				let returnValue: Promise<EncodingResult> | EncodingResult = requestEncoderSpec.encoder(submission, requestData);
				if (returnValue instanceof Promise) {
					return returnValue.then((encodingResult: EncodingResult) => {
						this._assembleEncodedData(formTag, encodingResult);
						return formTag;
					});
				} else {
					this._assembleEncodedData(formTag, returnValue);
					return formTag;
				}
			} else {
				// 파일업로드 지원 불가

				if (requestMediaType == Submission.MEDIA_JSON) {
					let requestBuilder: JSONRequestBuilder = new JSONRequestBuilder();
					let requestData: JSONRequestObject = requestBuilder._buildJsonRequestObject(submission);
					let requestString: string = JSON.stringify(requestData);
					this._addParameter(formTag, MultipartJSONRequestBuilder.JSONREQOBJ_PARAMNAME, [requestString]);
				} else {
					switch (requestMediaType) {
						case Submission.MEDIA_MULTIPART_JSON:
						case Submission.MEDIA_MULTIPART:
						case Submission.MEDIA_MULTIPART:
							throw new exceptions.IllegalStateException("filedownload responseType is not support multipart request");
						default: {
							let isSimple: boolean = requestMediaType == Submission.MEDIA_URLENCODED_SIMPLE;
							this._buildFormFieldRequest(submission, formTag, isSimple);
						}
					}
				}

				return formTag;
			}
		}

		//----------- helper methods
		private _init(): void {
			let browserInfo: utils.BrowserInfo = core.Platform.INSTANCE.browserInfo;
			if (browserInfo.mobile == false) {
				let frame: HTMLIFrameElement = document.getElementById(FormRequestBuilder._framename) as HTMLIFrameElement;
				if (!frame) {
					let framewrapper: HTMLDivElement = document.createElement("div") as HTMLDivElement;
					framewrapper.id = FormRequestBuilder._framewrappername;
					framewrapper.setAttribute("name", FormRequestBuilder._framewrappername);
					framewrapper.innerHTML = "<iframe id='" + FormRequestBuilder._framename + "' name='" + FormRequestBuilder._framename + "' style='display:none'></iframe>";

					document.body.appendChild(framewrapper);
				}
			}
		}

		private _getFormElement(): HTMLFormElement {
			let form: HTMLFormElement = document.getElementById(FormRequestBuilder._formname) as HTMLFormElement;
			if (!form) {
				form = document.createElement("form") as HTMLFormElement;
				form.id = FormRequestBuilder._formname;
				form.setAttribute("name", FormRequestBuilder._formname);
				form.setAttribute("accept-charset", "utf-8");
				document.body.appendChild(form);
			}

			return form;
		}

		private _assembleEncodedData(formTag: HTMLFormElement, encodingResult: EncodingResult): void {
			let key: string = encodingResult.key;
			let value: {} | string = encodingResult.content;

			if (key == null && utils.ParamUtil.isJSON(value)) {
				let keys: string[] = Object.keys(value);
				keys.forEach((k: string) => {
					let v: any = value[k];
					let jsonstring: string = FormRequestBuilder._getJsonString(v);
					this._addParameter(formTag, k, [jsonstring]);
				});
			} else {
				let jsonstring: string = FormRequestBuilder._getJsonString(value);
				this._addParameter(formTag, key, [jsonstring]);
			}
		}

		private _addParameter(formTag: HTMLFormElement, name: string, values: string[]): void {
			values.forEach((value: string) => {
				let inputTag: HTMLInputElement = document.createElement("input") as HTMLInputElement;
				inputTag.type = "hidden";
				inputTag.name = name;
				inputTag.value = value;
				formTag.appendChild(inputTag);
			});
		}

		private _buildFormFieldRequest(submission: Submission, formTag: HTMLFormElement, isSimple: boolean): void {
			// check requestObject
			let requestObject: Object = submission.getRequestObject();
			if (requestObject != null) {
				let jsonstring: string = JSON.stringify(requestObject);
				this._addParameter(formTag, AbstractRequestBuilder.REQOBJ_PARAMNAME, [jsonstring]);
			}

			// parameter
			let paramNames: string[] = submission.getParameterNames();
			paramNames.forEach((name: string) => {
				this._addParameter(formTag, name, submission.getParameters(name));
			});

			// 파일업로드 지원 불가

			// datamap/dataset
			let requestDataCount: number = submission.getRequestDataCount();
			for (let idx: number = 0; idx < requestDataCount; idx++) {
				let requestData: RequestData = submission.getRequestData(idx);
				let alias: string = this._getRequestAlias(requestData);
				if (requestData.data instanceof data.DataSet) {
					let dataSet: data.DataSet = requestData.data as data.DataSet;
					this._buildDataSetFormField(formTag, submission, dataSet, alias, requestData.payload, isSimple);
				} else {
					let dataMap: data.DataMap = requestData.data as data.DataMap;
					this._buildDataMapFormField(formTag, submission, dataMap, alias, isSimple);
				}
			}
		}

		private _buildDataSetFormField(formTag: HTMLFormElement, submission: Submission, dataSet: data.DataSet, alias: string, payload: PayloadType, isSimple: boolean): void {
			let dataDelimiter: string = super._createDataDelimiter();

			this._loadPayload(submission, dataSet, payload, (rowdata: data.RowConfigInfo, additionalParam: { [key: string]: string }, stateText: string) => {
				for (let columnName in rowdata) {
					let name: string = isSimple ? columnName : dataDelimiter + columnName;
					let value: string | number | boolean = rowdata[columnName];
					if (value == null) {
						value = "";
					}
					this._addParameter(formTag, name, ["" + value]);
				}

				this._applyFormAdditionalParam(formTag, additionalParam, dataDelimiter, isSimple);

				if (!isSimple) {
					let statName: string = dataDelimiter + "sts"; // TODO 공통화
					this._addParameter(formTag, statName, [stateText]);
				}
			});

			if (!isSimple) {
				this._addParameter(formTag, super._getDataDelimiterParamName(), [dataDelimiter]);
				if (alias) {
					this._addParameter(formTag, dataDelimiter, [alias]);
				}
				this._addParameter(formTag, dataDelimiter + "tp", ["ds"]); // parameter group type
			}
		}

		private _buildDataMapFormField(formTag: HTMLFormElement, submission: Submission, dataMap: data.DataMap, alias: string, isSimple: boolean): void {
			let columnNames: string[] = dataMap.getColumnNames();
			let dataDelimiter: string = super._createDataDelimiter(); // DataMap 별로 생성
			columnNames.forEach((columnName: string) => {
				let name: string = isSimple ? columnName : dataDelimiter + columnName;
				let value: string = dataMap.getString(columnName);
				if (value == null) {
					value = "";
				}
				this._addParameter(formTag, name, ["" + value]);
			});

			this._applyFormAdditionalParam(formTag, submission._handleDataMap(dataMap), dataDelimiter, isSimple);

			if (!isSimple) {
				this._addParameter(formTag, super._getDataDelimiterParamName(), [dataDelimiter]);

				if (alias) {
					this._addParameter(formTag, dataDelimiter, [alias]);
				}
				this._addParameter(formTag, dataDelimiter + "tp", ["dm"]); // parameter group type
			}
		}

		private _applyFormAdditionalParam(formTag: HTMLFormElement, additionalParam: { [key: string]: string }, dataDelimiter: string, isSimple: boolean): void {
			if (additionalParam) {
				for (let key in additionalParam) {
					let name: string = isSimple ? key : dataDelimiter + key;
					let value: string = additionalParam[key];
					if (value == null) {
						value = "";
					}
					this._addParameter(formTag, name, [value]);
				}
			}
		}

	}
}

