/// <reference path="./IGridCellRenderer.ts"/>


namespace cpr.controls.gridpart.renderer {

	/**
	 * @private
	 */
	export class EmbeddedGroupHeaderCellRendererFactory {
		private static _instance = new EmbeddedGroupHeaderCellRendererFactory();

		public static _getRenderer(columntype: string): (grid: Grid, gridRowGroup: provider.GridRowGroup, cellProp: GridGroupHeaderCellProp, option: IRenderOption) => ufc.ControlShape {
			let flyweight: (grid: Grid, gridRowGroup: provider.GridRowGroup, cellProp: GridGroupHeaderCellProp, option: IRenderOption) => ufc.ControlShape = null;
			switch (columntype) {
				case "checkbox": {
					flyweight = EmbeddedGroupHeaderCellRendererFactory._instance._renderCheckBox;
					break;
				}
			}
			return flyweight;
		}

		private _renderCheckBox(grid: Grid, gridRowGroup: provider.GridRowGroup, cellProp: GridGroupHeaderCellProp, option: IRenderOption): ufc.ControlShape {
			let checkedState: CHECKMODE = (gridRowGroup != null) ? gridRowGroup._getCheckedState() : CHECKMODE.UNCHECKED;
			let checked: boolean = (checkedState == CHECKMODE.CHECKED || checkedState == CHECKMODE.PARTIAL_ALL_CHECKED) ? true : false;
			let enabled: boolean = gridRowGroup._isEnabledCheckbox();
			let visible: boolean = gridRowGroup._isVisibleCheckbox();

			let iconShape: ufc.ElementShape = {
				tag: "div",
				classNames: [GridStyle.CHECKBOXICON],
				attr: {
					tabindex: "0",
					role: "checkbox",
					"data-role": "checkbox"
				},
				style: {
					// display: "block",
					"vertical-align": "inherit",
					// cursor: "pointer"
				}
			}
			GridUtil._setAria(iconShape, "checked", (checked) ? "true" : "false");

			let iconWrapper: ufc.ElementShape = {
				tag: "div",
				classNames: ["cl-icon-wrapper"],
				style: {
					display: "table-cell",
					"vertical-align": "inherit",
					"text-align": "inherit"
				},
				children: [iconShape]
			}
			let layout: ufc.ElementShape = {
				tag: "div",
				style: {
					display: "inline-table",
					height: "100%",
					"vertical-align": "inherit",
					"text-align": "inherit"
				},
				children: [iconWrapper]
			};

			let classNames: string[] = [GridStyle.CONTROL, GridStyle.CHECKBOX, EmbeddedCellRendererFactory._builtinClass, GridContext.CLS_CTRL_INHERIT];
			switch (checkedState) {
				case CHECKMODE.CHECKED: {
					classNames.push(ufc.Classes.CHECKED);
					break;
				}
				case CHECKMODE.PARTIAL_CHECKED:
				case CHECKMODE.PARTIAL_ALL_CHECKED:
				case CHECKMODE.PARTIAL_ALL_UNCHECKED: {
					classNames.push(ufc.Classes.PARTIALCHECKED);
					break;
				}
			}

			if (grid.enabled == false || enabled == false) {
				classNames.push(ufc.Classes.DISABLED);
			}
			let shape: cpr.ufc.ControlShape = {
				tag: "div",
				attr: {},
				classNames: classNames,
				style: {
					maxHeight: option.maxHeight + "px",
					height: "100%",
					width: "100%"
				},
				events: {
					click: (e: events.CMouseEvent) => {
						if (e && grid.enabled === true && grid.visible === true) {
							EmbeddedGroupHeaderCellRendererFactory._instance._handlerCheckboxToggleCheck(e, grid, null, gridRowGroup, cellProp, option);
						}
					},
					keydown: (e: events.CKeyboardEvent) => {
						if (e && grid.enabled === true && grid.visible === true) {
							if (e.keyCode == events.KeyCode.SPACE) {
								EmbeddedGroupHeaderCellRendererFactory._instance._handlerCheckboxToggleCheck(e, grid, null, gridRowGroup, cellProp, option);
							}
						}
					}

				},
				children: [layout]
			};

			if (visible == false) {
				shape.style["display"] = "none";
			}

			return shape;
		}

		private _handlerCheckboxToggleCheck(e: (events.CMouseEvent | events.CKeyboardEvent), grid: Grid, nodename: string, gridRowGroup: provider.GridRowGroup, cellProp: GridGroupHeaderCellProp, option: IRenderOption): void {
			if (gridRowGroup == null) {
				return;
			}
			if (gridRowGroup._isEnabledCheckbox() == false) {
				return;
			}
			let checkedState: CHECKMODE = gridRowGroup._getCheckedState();
			let checked: boolean = (checkedState == CHECKMODE.CHECKED || checkedState == CHECKMODE.PARTIAL_ALL_CHECKED) ? true : false;
			gridRowGroup._setGroupingChecked(cellProp, !checked, true);
		}
	}


	/**
	 * @private
	 */
	export class EmbeddedGroupHeaderCellRenderer extends AbstractGridCellRenderer {


		constructor(cellprop: GridCellProp, grid: Grid) {
			super(cellprop, grid);
		}

		private get headerprop(): GridGroupHeaderCellProp {
			return this.prop as GridGroupHeaderCellProp;
		}

		public static isAccept(headercellprop: GridGroupHeaderCellProp): boolean {
			if (headercellprop && headercellprop.configuration.columnType == "checkbox") {
				return true;
			}
			return false;
		}

		protected _init(): void {
		}

		public createCellShape(gridRowGroup: provider.GridRowGroup, option: IRenderOption): ufc.ControlShape | ufc.ControlRenderer {

			let renderer: (grid: Grid, gridRowGroup: provider.GridRowGroup, cellProp: GridGroupHeaderCellProp, option: IRenderOption) => ufc.ControlShape
				= EmbeddedGroupHeaderCellRendererFactory._getRenderer(this.headerprop.configuration.columnType);

			let controlShape: ufc.ControlShape = renderer(this.grid, gridRowGroup, this.headerprop, option);

			return controlShape;
		}


	}

}