namespace cpr {
	function _redraw(target: any) {
		_resolveUIControl(target)?.redraw();
	}

	function _resolveUIControl(ctx: any): controls.UIControl {
		if (ctx instanceof controls.layouts.Layout) {
			return ctx._getOwner();
		}
		else if (ctx instanceof controls.UIControl) {
			return ctx;
		} else {
			return null;
		}
	}

	/**
	 * 이 데코레이터가 부착된 메소드는 다음과 같은 동작을 같게 됩니다.
	 * 
	 * 메소드가 실행되는 동안 수집된 의존성과 연관된 변경이 일어나면, redraw()가 자동으로 호출되도록 합니다.
	 * UIControl 및 Layout에서만 사용할 수 있습니다.
	 * 
	 * @private
	 */
	export function autoRedraw(): MethodDecorator {
		return function (target: any, property: string, descriptor: PropertyDescriptor) {
			const originFunction = descriptor.value as (...args: any[]) => any;

			descriptor.value = function (this: controls.UIControl | controls.layouts.Layout<any>, ...args: any[]) {
				let me = _resolveUIControl(this);

				return _runWithCollectionDependency({
					subscriptionId: `${me.uuid}.${property}.redraw`,
					task: () => {
						return originFunction.apply(this, args);
					},

					onDepndencyInvalidation: () => {
						_redraw(this);
					},

					healthChecker: () => {
						return me && !me.disposed;
					}
				});
			}
		}

	}
}