		/**
		 * 포커스 및 preventInput 상태에 따라 textDisplayExp 변환을 적용한다.
		 * @param value 원본 텍스트
		 * @returns 변환된 텍스트
		 */
		protected _transformDisplayText(value: string | ufc.StyledString): string | ufc.StyledString {
			if (this.placeholder != "" && value == "") {
				return value;
			}
			if (!this.preventInput) {
				if (this.textDisplayExp && (!this.focused || this.readOnly)) {
					return ufc.StyledString._asString(this._computeTextBoxDisplayText(value));
				}
				return ufc.StyledString._asString(value);
			}
			if (this.textDisplayExp) {
				return this._computeTextBoxDisplayText(value);
			}
			return value;
		}

		/**
		 * textDisplayExp를 이용해 입력상자에 표시될 텍스트를 계산한다.
		 * @param value 원본 텍스트
		 * @returns Expression 평가 결과
		 */
		private _computeTextBoxDisplayText(value: string | ufc.StyledString): ufc.StyledString | string {
			let expr = new cpr.expression.Expression(this.textDisplayExp);
			let result: any;
			try {
				let that = this;
				// 표현식의 text는 평문 문자열로 넘긴다. StyledString을 그대로 넘기면 문자열을 다루는
				// 표현식 함수(formatText, i18n, 앱 메소드 등)와 문자열 메소드(text.substr 등)가 모두 실패하고, 아래 catch가 그 예외를 삼켜 원본 값으로 조용히 되돌아간다.
				// 다른 입력 컨트롤의 displayExp도 모두 평문 문자열을 넘긴다.
				let edo = new cpr.expression.ExpressionDelegateObject(this.type, "textDisplayExp", { text: ufc.StyledString._asString(value) });
				edo.setUnsupportedProperty("displayingText", "");
				let altProperty = edo.createObject();
				result = expr._evaluateInternal({
					_getExpressionDelegates(): any[] {
						return [altProperty, that, that.getBindContext()];
					}
				});
			} catch (e) {
				result = value;
			}
			return result;
		}

		/**
		 * 선택된 아이템들을 이용해 입력상자에 표시될 텍스트를 계산한다.
		 * @returns
		 */
		public _computeDisplayText(): string | ufc.StyledString {
			let selection = this.getSelection();
			let useLastDelimiter = this.multiple && this.preventInput == false;
			let space = this.preventInput ? this.delimiter + " " : this.delimiter;

			let result = selection.length > 0 ? selection.map((each) => {
				return new ufc.StyledString(this._itemExpressionEvaluator.evaluateDisplayLabel(each) as string);
			}).reduce((result: ufc.StyledString, value: ufc.StyledString) => {
				result.append(space);
				return result.append(value);
			}) : null;
			if (useLastDelimiter && result) {
				result.append(this.delimiter);
			}
			return this._transformDisplayText(result ?? "");
		}

		public _exportValue(): string | number {
			let ctrlText = (this.text === undefined) ? this.value : this.text;

			// 기본 >> text
			return (ctrlText != null) ? "" + ctrlText : "";
		}

		/* ListDataBindable End *********************************************************/
		public override _isUseCustomScroll(): boolean {
			// 모바일 브라우저에서는 무조건 가상스크롤바를 쓰도록 함(ios safari, android chrome이 가상스크롤바를 지원하지 않음)
			if (internal.ScrollbarUtil._isMobileBrowser()) {
				return true;
			}

			return super._isUseCustomScroll();
		}

