namespace cpr.protocols {
	export interface RequestBuilder {
		build(submission: AbstractSubmission): any;
		getContentType(): string;
	}
	export interface RequestBuilderFactory {
		getRequestBuilder(submission: AbstractSubmission): RequestBuilder;
	}

	export interface ResponseParser {
		/**
		 * XMLHttpRequest의 응답데이터의 부분을 추가 수신하였을 때 호출되는 함수
		 * @param submission 
		 * @param xhr 
		 */
		load(submission: AbstractSubmission, xhr: XMLHttpRequest): void;
		/**
		 * 예약된 데이터 로딩 작업을 취소 합니다.
		 */
		_abortLoading(submission: AbstractSubmission): void;

		/**
		 * XMLHttpRequest의 모든 응답데이터가 수신하였을 때 호출되는 함수
		 * @param submission 
		 * @param xhr 
		 * @param doneHandler 
		 */
		parse(submission: AbstractSubmission, xhr: XMLHttpRequest, doneHandler: () => void): void;

		/**
		 * ResponseDecoder에 의해 Decoding된 응답데이터의 데이터화를 지원하기 위한 함수
		 * @param submission 
		 * @param stringData 
		 * @param doneHandler 
		 */
		_parseData(submission: AbstractSubmission, stringData: {} | string, doneHandler: () => void): void;
	}
	export interface ResponseParserFactory {
		getResponseParser(xhr: XMLHttpRequest, forceContentType: string, defaultContentType: string): ResponseParser;
		_getContentParser(forceContentType: string, defaultContentType: string): ResponseParser;
	}

	export interface EncodingResult {
		/**
		 * 서버로 전송할 데이터의 key.
		 * key값이 null인 경우 key값이 필요한 요청포맷을 무시하고 리턴된 content만 서버로 전송합니다.
		 */
		key: string,
		/**
		 * 서버로 전송할 데이터.
		 */
		content: {} | string | Blob,
		/**
		 * 서버로 전송할 ContentType 정의.
		 */
		contentType?: string
	}
	export interface RequestEncoder {
		(submission: AbstractSubmission, data: {} | string | Blob): Promise<EncodingResult> | EncodingResult;
	}
	export interface DecodingResult {
		/**
		 * 서브미션에 전달할 데이터.
		 */
		content: {} | string,
		/**
		 * 서브미션에서 처리할 contentType 정의.
		 */
		contentType: string
	}
	export interface ResponseDecoder {
		(submission: AbstractSubmission, data: string): Promise<DecodingResult> | DecodingResult;
	}

	/**
	 * @private
	 */
	export class ProtocolDataModel implements RequestBuilderFactory, ResponseParserFactory {
		public static readonly _BLOB_READ_BUF: number = 524288; // 512 kb

		private _requestData: RequestData[];
		private _responseData: ResponseData[];
		protected _requestBuilderFactory: request.DefaultRequestBuilderFactory;
		protected _responseParserFactory: response.DefaultResponseParserFactory;


		constructor() {
			this._requestData = [];
			this._responseData = [];
			this._requestBuilderFactory = request.DefaultRequestBuilderFactory.INSTANCE;
			this._responseParserFactory = response.DefaultResponseParserFactory.INSTANCE;
		}

		public _addRequestData(reqData: data.DataMap): void;
		public _addRequestData(reqData: data.DataMap, alias: string): void;
		public _addRequestData(reqData: data.DataSet): void;
		public _addRequestData(reqData: data.DataSet, payloadType: PayloadType): void;
		public _addRequestData(reqData: data.DataSet, alias: string): void;
		public _addRequestData(reqData: data.DataSet, alias: string, payloadType?: PayloadType): void;
		public _addRequestData(): void {
			let args = _toArray(arguments);
			let reqData: data.DataMap | data.DataSet = args[0] as (data.DataMap | data.DataSet);
			if (!reqData) {
				throw new cpr.exceptions.IllegalArgumentException("reqData must be not null");
			}
			let alias: string = null;
			let payloadType: PayloadType = null;
			if (reqData instanceof data.DataMap) {
				switch (args.length) {
					case 2: {
						alias = args[1] as string;
						break;
					}
				}
			} else if (reqData instanceof data.DataSet) {
				switch (args.length) {
					case 2: {
						let payload = args[1];
						if (payload != null) {
							if (typeof payload == "string") {
								payloadType = PayloadType[payload as string];
								if (!payloadType) {
									// alias
									alias = payload;
								}
							} else if (typeof payload == "number") {
								payloadType = payload as PayloadType;
							} else {
								throw new cpr.exceptions.IllegalArgumentException("second parameter : " + payload);
							}
						}
						break;
					}
					case 3: {
						alias = args[1] as string;
						let payload = args[2];
						if (payload != null && typeof payload == "string") {
							payloadType = PayloadType[payload as string];
						} else if (payload != null && typeof payload == "number") {
							payloadType = payload as PayloadType;
						}
						break;
					}
				}
				if (payloadType == null) {
					payloadType = PayloadType.modified;
				}
			} else {
				throw new cpr.exceptions.IllegalArgumentException("reqData must be DataMap or DataSet");
			}
			let requestData: RequestData = {
				data: reqData,
				alias: alias,
				payload: payloadType
			};
			this._requestData.push(requestData);
		}

		public _getRequestDataCount(): number {
			return this._requestData.length;
		}

		public _getRequestData(index: number | string): RequestData {
			if (typeof index == "number") {
				return this._requestData[index];

			} else {
				let dataId: string = index as string;
				for (let idx: number = 0; idx < this._requestData.length; idx++) {
					let reqData: RequestData = this._requestData[idx];
					if ((reqData.alias && reqData.alias == dataId) || reqData.data.id == dataId) {
						return reqData;
					}
				}
				return null;
			}
		}

		public _removeRequestData(index: number | string): void {
			let idx = -1;
			if (typeof index == "number") {
				idx = index;
			} else {
				let dataId: string = index as string;
				this._requestData.some((reqData: RequestData, index: number) => {
					if ((reqData.alias && reqData.alias == dataId) || reqData.data.id == dataId) {
						idx = index;
						return true;
					}
				});
			}
			if (idx > -1) {
				this._requestData.splice(idx, 1);
			}
		}
		public _removeAllRequestData(): void {
			if (this._requestData.length > 0) {
				this._requestData.splice(0, this._requestData.length);
			}
		}

		public _addResponseData(data: data.DataSet | data.DataMap, isadd: boolean, alias: string = null): void {
			if (data == null) {
				throw new cpr.exceptions.IllegalArgumentException("data");
			}
			let responseData: ResponseData = {
				data: data, isadd: isadd, alias: alias
			};
			this._responseData.push(responseData);
		}

		public _getResponseDataCount(): number {
			return this._responseData.length;
		}

		public _getResponseData(index: number | string): ResponseData {
			if (typeof index === "number") {
				return this._responseData[index];
			} else {
				let dataId: string = index as string;
				if (dataId == Submission.METADATA_KEY) {
					return {
						data: { success: true },
						isadd: false,
						alias: null
					};
				}
				for (let idx: number = 0; idx < this._responseData.length; idx++) {
					let resData: ResponseData = this._responseData[idx];
					if ((resData.alias && resData.alias == dataId) || resData.data.id == dataId) {
						return resData;
					}
				}
				return null;
			}
		}

		public _removeResponseData(index: number | string) {
			let idx = -1;
			if (typeof index == "number") {
				idx = index;
			} else {
				let dataId: string = index as string;
				this._responseData.some((resData: ResponseData, index: number) => {
					if ((resData.alias && resData.alias == dataId) || resData.data.id == dataId) {
						idx = index;
						return true;
					}
				});
			}
			if (idx > -1) {
				this._responseData.splice(idx, 1);
			}
		}

		public _getResponseDatas(alias: string): ResponseData[] {
			let resDatas: ResponseData[] = [];
			if (alias == Submission.METADATA_KEY) {
				resDatas[resDatas.length] = {
					data: { success: true },
					isadd: false,
					alias: null
				};
			} else {
				for (let idx: number = 0; idx < this._responseData.length; idx++) {
					let resData: ResponseData = this._responseData[idx];
					let resAlias: string = resData.alias;
					if (resAlias == null || resAlias == "") {
						resAlias = resData.data.id;
					}
					if (resAlias == alias) {
						resDatas[resDatas.length] = resData;
					}
				}
			}
			return resDatas;
		}

		public _removeAllResponseData(): void {
			if (this._responseData.length > 0) {
				this._responseData.splice(0, this._responseData.length);
			}
		}

		public getRequestBuilder(submission: AbstractSubmission): RequestBuilder {
			return this._requestBuilderFactory.getRequestBuilder(submission);
		}

		public getResponseParser(xhr: XMLHttpRequest, forceContentType: string, defaultContentType: string): ResponseParser {
			return this._responseParserFactory.getResponseParser(xhr, forceContentType, defaultContentType);
		}

		public _getContentParser(forceContentType: string, defaultContentType: string): ResponseParser {
			return this._responseParserFactory._getContentParser(forceContentType, defaultContentType);
		}

	}
}