/// <reference path="./CustomAbstractScrollbar.ts" />


namespace cpr.controls.internal {
	/**
	 * @private
	 */
	export class CustomVScrollbar extends CustomAbstractScrollbar implements IVirtualVScrollbar {
		// content state
		private _maxThumbTop: number;
		private _maxContentTop: number;
		private _scrollTop: number;

		// Scrollbar의 scrolltop과 viewport의 scrolltop 간의 비율
		private _trackViewRatio: number = 1;

		// mousemove state
		private _vscrollMouseMoveStart: boolean = false;
		private _startY: number = 0;

		// touch state
		private _thumbTouchStarted: boolean = false;
		private _thumbTouchStartY: number = -1;

		private _timer: number = null;
		private _holding: boolean = false;
		private _holdHandler;
		private _trackStartY: number = 0;


		constructor(scrollPane: IVirtualScrollPane) {
			super(scrollPane);
			this._scrollTop = 0;
		}

		public _getWidth(): number {
			return ScrollbarUtil._getCustomScrollbarInfo().vWidth;
		}

		public _setScrollTop(scrollTop: number): void {
			this._scrollTop = scrollTop;
			if (this._trackViewRatio === -1) {
				// visible = false 일 때
				return;
			}
			let thumbTop: number = this._convToScrollbarTop(scrollTop);
			let newThumbTop: number = this._checkVerticalScrollbarRange(thumbTop);
			this._updateStyle("custom-vscroll-thumb", { top: newThumbTop + "px" });
			if (thumbTop != newThumbTop) {
				this._scrollTop = this._convToContentScrollTop(newThumbTop);
				this._syncToPaneScrollTop();
			}
		}

		public _getScrollTop(): number {
			return this._scrollTop;
		}

		public _createScrollbar(contentScrollTop: number, contentHeight: number): ufc.ElementShape {
			let arrowUp: ufc.ElementShape = {
				tag: "div",
				classNames: ["cl-arrow-up"],
				attr: {
				},
				style: {
				},
				mandatoryEvents: {
					mousedown: (e: events.CMouseEvent) => this._onBtnScrollUp(e),
					mouseleave: (e: events.CMouseEvent) => this._onMouseLeaveHoldTarget(e),
					mouseenter: (e: events.CMouseEvent) => this._onMouseEnterHoldTarget(e)
				},
				children: []
			};
			let track: ufc.ElementShape = this._createTrackShape(contentScrollTop, contentHeight);
			let arrowDown: ufc.ElementShape = {
				tag: "div",
				classNames: ["cl-arrow-down"],
				attr: {
				},
				style: {
				},
				mandatoryEvents: {
					mousedown: (e: events.CMouseEvent) => this._onBtnScrollDown(e),
					mouseleave: (e: events.CMouseEvent) => this._onMouseLeaveHoldTarget(e),
					mouseenter: (e: events.CMouseEvent) => this._onMouseEnterHoldTarget(e)
				},
				children: []
			};
			let shape: ufc.ElementShape = {
				tag: "div",
				nodename: this._getQName("custom-vscroll"),
				classNames: ["cl-vscrollbar", "cl-unselectable"],
				attr: {
				},
				style: {
				},
				mandatoryEvents: {
					wheel: (e: events.CWheelEvent) => this._onWheel(e),
					mousedown: (e: events.CMouseEvent) => {
						if (this._getScrollPane()._onMousedownScroll) {
							this._getScrollPane()._onMousedownScroll(e);
						}
					}
				},
				children: [arrowUp, track, arrowDown]
			};
			return shape;
		}
		private _createTrackShape(contentScrollTop: number, contentHeight: number): ufc.ElementShape {
			let track: ufc.ElementShape = {
				tag: "div",
				nodename: this._getQName("custom-vscroll-track"),
				classNames: ["cl-track"],
				attr: {
				},
				style: {
				},
				mandatoryEvents: {
					mousedown: (e: events.CMouseEvent) => this._onVerticalTrackDown(e),
					mouseenter: (e: events.CMouseEvent) => this._onMouseEnterHoldTarget(e),
					mouseleave: (e: events.CMouseEvent) => this._onMouseLeaveHoldTarget(e),
					mousemove: (e: events.CMouseEvent) => this._onMouseMoveHoldTarget(e)
				},
				children: [
					_createDrawLazyTask({
						nodename: this._getQName("custom-vscroll-thumb"),
						task: () => {
							let thumbShape: ufc.ElementShape = null;

							let trackHeight: number = this._getTrackHeight();
							if (trackHeight === 0) {
								// visible = false 일 때
								thumbShape = {
									tag: "div",
									nodename: this._getQName("custom-vscroll-thumb"),
									classNames: ["cl-thumb"],
									attr: {},
									style: {},
									children: []
								};
								this._maxThumbTop = 0;
								this._maxContentTop = 0;
								this._trackViewRatio = -1;
								this._scrollTop = contentScrollTop;
							} else {
								let scrollPane: IVirtualScrollPane = this._getScrollPane();
								let viewportHeight: number = scrollPane._getViewportHeight();

								let viewableRatio: number = viewportHeight / contentHeight;
								let thumbHeight: number = viewableRatio * trackHeight;
								if (thumbHeight > trackHeight) {
									thumbHeight = trackHeight;
								} else if (thumbHeight < this.minThumbSize) {
									thumbHeight = this.minThumbSize;
								}

								this._maxThumbTop = trackHeight - thumbHeight;
								this._maxContentTop = contentHeight - viewportHeight;
								if (this._maxContentTop === 0) {
									this._trackViewRatio = 0;
								} else {
									this._trackViewRatio = this._maxThumbTop / this._maxContentTop;
								}

								this._scrollTop = contentScrollTop;
								let thumbTop: number = this._convToScrollbarTop(contentScrollTop);
								let newThumbTop: number = this._checkVerticalScrollbarRange(thumbTop);
								if (thumbTop != newThumbTop) {
									thumbTop = newThumbTop;
									contentScrollTop = this._convToContentScrollTop(newThumbTop);
									this._scrollTop = contentScrollTop;
									this._syncToPaneScrollTop();
								}

								thumbShape = {
									tag: "div",
									nodename: this._getQName("custom-vscroll-thumb"),
									classNames: ["cl-thumb"],
									attr: {
									},
									style: {
										top: thumbTop + "px",
										height: thumbHeight + "px"
									},
									mandatoryEvents: {
										mousedown: (e: events.CMouseEvent) => this._onVerticalThumbMouseDown(e),
										touchstart: (e: events.CTouchEvent) => this._onVerticalThumbTouchStart(e)
									},
									children: []
								};
								if (thumbHeight == trackHeight) {
									this._updateCSS("custom-vscroll", ["cl-noscrollable"], {}, true);
								}
							}

							return thumbShape;
						}
					})
				]
			};
			return track;
		}

		// event handler
		private _onVerticalThumbMouseDown(e: events.CMouseEvent): void {
			if (this._checkPressedLeftButton(e) == false) {
				return;
			}
			if (this._getScrollPane()._isEnabled() == false) {
				return;
			}
			this._getScrollPane()._checkResize();

			this._vscrollMouseMoveStart = true;
			this._startY = e._getUnscaledClientY();
			this._dragStartThumb();
			// e.stopPropagation(); // track에 전파 막음
		}
		private _onVerticalThumbMouseMove(e: events.CMouseEvent): void {
			if (this._vscrollMouseMoveStart == false || this._checkPressedLeftButton(e) == false) {
				this._dragEndThumb();
				return;
			}
			if (this._getScrollPane()._isEnabled() == false) {
				return;
			}

			// 타 이벤트 핸들러에서 커스텀스크롤바의 마우스무브 이벤트에 영향을 받지 않도록 이벤트 전파를 막음. ex) DragSource
			e.stopPropagation();
			e.stopImmediatePropagation();

			let deltaY: number = e._getUnscaledClientY() - this._startY;
			if (deltaY == 0) {
				return;
			}
			this._startY = e._getUnscaledClientY();
			this._scrollThumbVertical(e, deltaY);
		}
		private _onVerticalThumbMouseUp(e: events.CMouseEvent): void {
			this._dragEndThumb();
		}
		private _onWheel(e: events.CWheelEvent): void { // wheel은 가로/세로 같이 사용
			if (e.ctrlKey === true) { // 확대/축소
				return;
			}
			this._getScrollPane()._checkResize();

			let deltaY: number = e.deltaY;

			if (deltaY == 0 || e.shiftKey) {
				return;
			}
			// 콘텐트 위에서 굴렸을 때와 같은 규칙으로 이동량을 계산한다.
			deltaY = ScrollbarUtil._toWheelOffset(deltaY, this._getScrollPane()._getViewportHeight());

			if (this._scrollContentVertical(e, deltaY)) {
				e.preventDefault();
				e.stopPropagation();
			}
		}
		private _onBtnScrollUp(e: events.CMouseEvent): void {
			if (this._checkPressedLeftButton(e) == false) {
				return;
			}
			if (this._getScrollPane()._isEnabled() == false) {
				return;
			}

			this._getScrollPane()._checkResize();

			let offset: number = ScrollbarUtil._getIntSize(this._getScrollPane()._getViewportHeight() * 0.2);
			this._holdStart(() => {
				this._repeat(null, () => {
					if (this._holding) {
						this._scrollContentVertical(e, -offset);
					}
				})
			});
		}
		private _onBtnScrollDown(e: events.CMouseEvent): void {
			if (this._checkPressedLeftButton(e) == false) {
				return;
			}
			if (this._getScrollPane()._isEnabled() == false) {
				return;
			}

			this._getScrollPane()._checkResize();

			let offset: number = ScrollbarUtil._getIntSize(this._getScrollPane()._getViewportHeight() * 0.2);
			this._holdStart(() => {
				this._repeat(null, () => {
					if (this._holding) {
						this._scrollContentVertical(e, offset);
					}
				})
			});
		}
		private _onVerticalTrackDown(e: events.CMouseEvent): void {
			if (this._checkPressedLeftButton(e) == false) {
				return;
			}
			if (this._getScrollPane()._isEnabled() == false) {
				return;
			}

			let trackNode: HTMLElement = this._getNamedNode("custom-vscroll-track");
			if (e.target !== trackNode) {
				return;
			}
			this._getScrollPane()._checkResize();

			this._trackStartY = e._getUnscaledClientY();
			let offset: number = ScrollbarUtil._getIntSize(this._getScrollPane()._getViewportHeight() * 0.8);

			let thumbNode: HTMLElement = this._getNamedNode("custom-vscroll-thumb");
			if (thumbNode == null) {
				return;
			}
			let isScrollDown: boolean = this._trackStartY > thumbNode.getBoundingClientRect().top;
			this._holdStart(() => {
				this._repeat(null, () => {
					let thumbRect = thumbNode.getBoundingClientRect();
					if (isScrollDown && this._trackStartY > thumbRect.top + thumbRect.height) {
						this._scrollContentVertical(e, offset);
					} else if (!isScrollDown && this._trackStartY < thumbRect.top) {
						this._scrollContentVertical(e, -offset);
					}
				})
			});
		}
		private _onVerticalThumbTouchStart(e: events.CTouchEvent): void {
			if (this._getScrollPane()._isEnabled() == false) {
				return;
			}

			this._getScrollPane()._checkResize();

			this._thumbTouchStarted = true;

			var touch: Touch = e.changedTouches[0];
			this._thumbTouchStartY = touch.clientY;
			this._dragStartThumb();
		}

		private _onVerticalThumbTouchMove(e: events.CTouchEvent): void {
			if (this._thumbTouchStarted == false) {
				return;
			}
			if (e.touches.length !== 1) {
				return;
			}
			if (this._getScrollPane()._isEnabled() == false) {
				return;
			}

			e.preventDefault();
			e.stopPropagation();

			let touch: Touch = e.changedTouches[0];
			let offset: number = touch.clientY - this._thumbTouchStartY;
			if (offset == 0) {
				return;
			}
			this._thumbTouchStartY = touch.clientY;
			this._scrollThumbVertical(e, offset);
		}

		private _onVerticalThumbTouchEnd(e: events.CTouchEvent): void {
			this._thumbTouchStarted = false;
			this._thumbTouchStartY = -1;
		}
		private _dragEventDispatcher = (e: any) => {
			if (this._vscrollMouseMoveStart || this._thumbTouchStarted) {
				if (e.type == "mouseup") {
					this._onVerticalThumbMouseUp(e);
				} else if (e.type == "touchend") {
					this._onVerticalThumbTouchEnd(e);
				} else if (e.type == "mousemove") {
					this._onVerticalThumbMouseMove(e);
				} else if (e.type == "touchmove") {
					this._onVerticalThumbTouchMove(e);
				}
			} else {
				if (e.type == "mouseup" || e.type == "touchend") {
					this._onMouseUpHoldTarget(e);
				}
			}
		}
		private _onMouseUpHoldTarget(e: MouseEvent) {
			if (!this._holding) {
				return;
			}
			this._holding = false;
			window.clearTimeout(this._timer);
			this._timer = null;
			this._holdEnd();
		}
		private _onMouseMoveHoldTarget(e: events.CMouseEvent) {
			if (this._checkPressedLeftButton(e) == false) {
				this._holdEnd();
				return;
			}
			if (this._holding) {
				this._trackStartY = e._getUnscaledClientY();
			}
		}
		private _onMouseEnterHoldTarget(e: events.CMouseEvent) {
			if (this._holding && this._timer == null) {
				if (this._holdHandler) this._holdHandler();
			}
		}
		private _onMouseLeaveHoldTarget(e: events.CMouseEvent) {
			if (this._holding && this._timer) {
				window.clearTimeout(this._timer);
				this._timer = null;
			}
		}

		// helper
		private _syncToPaneScrollTop(): void {
			let deferredUpdateManager: core.DeferredUpdateManager = core.DeferredUpdateManager.INSTANCE;
			if (deferredUpdateManager._isRendering()) {
				deferredUpdateManager.asyncExec(this._paneScrollTopSetter);
			} else {
				this._setPaneScrollTop();
			}
		}
		private _paneScrollTopSetter: () => void = () => this._setPaneScrollTop();
		private _setPaneScrollTop(): void {
			this._getScrollPane()._setScrollTop(null, this._scrollTop);
		}

		private _scrollContentVertical(e: events.CUIEvent, offset: number): boolean { // 컨텐트 스크롤탑의 변위를 이용해 컨텐트 스크롤탑과 세로스크롤바의 Thumb의 위치 변경
			let scrollTop: number = this._getScrollTop() + offset;
			if (scrollTop < 0) {
				scrollTop = 0;
			} else if (scrollTop > this._maxContentTop) {
				scrollTop = this._maxContentTop;
			}
			scrollTop = this._getScrollPane()._setScrollTop(e, scrollTop);
			if (scrollTop == -1 || scrollTop == this._getScrollTop()) {
				return false;
			}
			this._setScrollTop(scrollTop);
			return true;
		}
		private _getTrackHeight(): number {
			let trackNode: HTMLElement = this._getNamedNode("custom-vscroll-track");
			return trackNode.clientHeight;

			// let viewHeight: number = this._getScrollPane()._getViewportHeight();
			// let scrollbarInfo: ScrollbarInfo = ScrollbarUtil._getCustomScrollbarInfo();
			// return viewHeight - scrollbarInfo.vBtnHeight;
		}
		private _scrollThumbVertical(e: events.CUIEvent, offset: number): boolean { // 컨텐트 스크롤탑의 변위를 이용해 컨텐트 스크롤탑과 세로스크롤바의 Thumb의 위치 변경
			let contentOffset: number = this._convToContentScrollTop(offset);
			let moved: boolean = this._scrollContentVertical(e, contentOffset);
			return moved;
		}
		private _convToScrollbarTop(viewportScrollTop: number): number { // 컨텐트 스크롤탑을 세로스크롤바의 Thumb 위치로 변환
			if (viewportScrollTop == 0) {
				return viewportScrollTop;
			}
			let trackTop: number = viewportScrollTop * this._trackViewRatio;
			return trackTop;
		}
		private _convToContentScrollTop(thumbTop: number): number { // 세로스크롤바의 Thumb 위치를 컨텐트 스크롤탑으로 변환
			let viewTop: number = 1 / this._trackViewRatio * thumbTop;
			return viewTop;
		}
		private _checkVerticalScrollbarRange(trackTop: number): number { // 세로스크롤바의 스크롤탑 레인지 계산
			if (trackTop <= 0) {
				return 0;
			}
			if (trackTop > this._maxThumbTop) {
				trackTop = this._maxThumbTop;
			}
			return trackTop;
		}
		private _dragStartThumb() {
			this._holdStart();
			cpr.events.BodyEventTarget.INSTANCE._addCaptureEventListener("mousemove", this._dragEventDispatcher);
			cpr.events.BodyEventTarget.INSTANCE._addCaptureEventListener("touchmove", this._dragEventDispatcher);
		}
		private _dragEndThumb() {
			this._holdEnd();
			this._vscrollMouseMoveStart = false;
			cpr.events.BodyEventTarget.INSTANCE._removeCaptureEventListener("mousemove", this._dragEventDispatcher);
			cpr.events.BodyEventTarget.INSTANCE._removeCaptureEventListener("touchmove", this._dragEventDispatcher);
		}
		private _holdEnd() {
			this._holding = false;
			this._holdHandler = null;
			this._trackStartY = 0;
			cpr.events.BodyEventTarget.INSTANCE._removeCaptureEventListener("mouseup", this._dragEventDispatcher);
			cpr.events.BodyEventTarget.INSTANCE._removeCaptureEventListener("touchend", this._dragEventDispatcher);
		}
		private _holdStart(handler?: Function) {
			this._holding = true;
			if (handler) {
				this._holdHandler = handler
				handler();
			}
			cpr.events.BodyEventTarget.INSTANCE._addCaptureEventListener("mouseup", this._dragEventDispatcher);
			cpr.events.BodyEventTarget.INSTANCE._addCaptureEventListener("touchend", this._dragEventDispatcher);
		}
		private _repeat(delay: number, handler, option?: any) {
			delay = delay || 500;
			window.clearTimeout(this._timer);
			this._timer = this._delay(() => {
				this._repeat(40, handler);
			}, delay);
			handler(option);
		}
		private _delay(handler, delay: number = 0) {
			return window.setTimeout(handler, delay);
		}
		private _checkPressedLeftButton(e: events.CMouseEvent) {
			let buttons = e.buttons ? e.buttons : e.which;
			return buttons == 1;
		}
	}
}