namespace cpr {
	const _browserInfo = _createBrowserInfo();

	export function _detectBrowser(): utils.BrowserInfo {
		return _browserInfo;
	}

	export function _isIE() {
		return _detectBrowser().name == "ie"
	}

	export function _isSamsungBrowser() {
		return navigator.userAgent.indexOf("SamsungBrowser") > -1;
	}

	function _createBrowserInfo(): utils.BrowserInfo {
		let browserInfo = browserDetect() as utils.BrowserInfo;
		browserInfo.os = browserInfo.os || "unknown";
		browserInfo.isAndroid = browserInfo.os.indexOf("Android") > -1;
		browserInfo.isIOS = browserInfo.os.indexOf("iOS") > -1;

		let ua = navigator.userAgent.toLowerCase();
		if (!browserInfo.name) {
			if (ua.indexOf("safari") !== -1) {
				browserInfo.name = "safari"
			}
		}
		//https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/10591
		if (browserInfo.isAndroid) {
			// 안드로이드에는 사파리 브라우저가 존재하지 않음.
			if (browserInfo.name == "safari" && ua.indexOf("chrome") > -1) {
				let match = ua.match(/chrome\/([\d.]+)/);
				var version = match ? match[1] : "0";
				browserInfo.version = version;
				browserInfo.versionNumber = parseInt(version.split(".")[0]);
				browserInfo.name = "chrome";
			}
		}
		// TODO: 아이폰 어플의 navigator 정보에 version이 포함되지 않아 version을 사용하는 컨트롤에 문제를 발생할 수 있음.
		// 아이폰 어플 Mozilla/5.0 (iPhone; CPU iPhone OS 14_0_1 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/15E148 telehealth
		// 아이폰 사파리 Mozilla/5.0 (iPhone; CPU iPhone OS 13_4 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/13.1 Mobile/15E148 Safari/604.1
		// 아이패드 Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_4) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/13.1.1 Safari/605.1.15
		// 아이패드 웹사이트 요청 끔 Mozilla/5.0 (iPad; CPU OS 13_5_1 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/13.1.1 Mobile/15E148 Safari/604.1
		(() => {
			let passive = false;
			const options = Object.defineProperty({}, 'passive', {
				get() { passive = true; },
			});

			const noop = () => { };
			window.addEventListener('testPassiveEventSupport', noop, options);
			window.removeEventListener('testPassiveEventSupport', noop, options);
			browserInfo.supportsPassiveEvent = passive;
		})();

		let isAppleDevice = browserInfo.name == "safari" || browserInfo.os == "OS X";
		if (browserInfo.mobile && isAppleDevice && browserInfo.isAndroid == false) {
			browserInfo.os = "iOS";
		}


		return browserInfo;
	}
}