/// <reference path="./AbstractMask.ts" />
/// <reference path="./NumberFormatter.ts" />

namespace cpr.foundation {

	/**
	 * @private
	 * 넘버마스크의 입력값은 /+-\.[0-9]/ 만 입력 받음.
	 * IE, FireFox에서 ime-mode를 설정하여 입력상자에 영문 또는 숫자만 입력이 가능하도록 되어 있어.
	 * Chrome, Safari에 집중하여 처리하면 된다.
	 */
	export class DefaultNumberMask extends AbstractMask {

		protected _formatter: NumberFormatter;

		constructor(owner: ValueOwner, handlers: { decimalSeparator: () => string, digitGroupSeparator: () => string, format: () => string }) {
			super(owner);
			this._formatter = new NumberFormatter();
			this._formatter._bindProperty("format", handlers.format);
			this._formatter._bindProperty("digitGroupSeparator", handlers.digitGroupSeparator);
			this._formatter._bindProperty("decimalSeparator", handlers.decimalSeparator);
		}

		public getFormatter(): NumberFormatter {
			return this._formatter;
		}

		public getDisplayText(value: string): string {
			let formattedData: string = null;
			if (value == null || value == "") {
				formattedData = this._formatter._getPlaceholder();
			} else {
				formattedData = this._formatter.transform(value);
			}
			return formattedData;
		}

		protected _transformInputValue(value: string): string {
			return this._formatter.reverseTransform(value);
		}

		protected _pasteEvent(input: HTMLInputElement, pasteValue: string, inputValue: string, e: ClipboardEvent) {
			inputValue = this._formatter.reverseTransform(inputValue); // mask to data
			input.value = inputValue;
		}

		protected _cutEvent(input: HTMLInputElement, e: ClipboardEvent) {
			// no implement
		}

		protected _inputEvent(input: HTMLInputElement, e: events.CUIEvent) {
			//삼성 브라우저는 키보드의 클립보드 버튼으로 붙여넣기 시 keydown, beforeinput이 발생하지 않아
			//beforeinput에서 붙여넣기를 처리할 수 없습니다. 입력이 끝난 값을 input 이벤트에서 정제합니다.
			this._checkClipboardPasteOnInput(input, e);
		}

		protected _isNotAllowChar(char: string) {
			return /[^-+\.0-9]+/.test(char);
		}

		/**
		 * 문자를 삽입하는 입력 유형인지 여부를 반환합니다.
		 * 드롭(insertFromDrop)은 붙여넣기와 처리 방법이 달라 제외합니다.
		 * @param inputType 입력 유형
		 */
		protected _isInsertInputType(inputType: string): boolean {
			return !!inputType && inputType.indexOf("insert") == 0 && inputType != "insertFromDrop";
		}

		/**
		 * 안드로이드에서 여러 문자가 한번에 입력되었는지 여부를 반환합니다.
		 * 입력 문자는 숫자, 부호, 소수점으로 제한되어 있어 이 경우는 클립보드 붙여넣기로 간주합니다.
		 * @param data 입력 데이터
		 */
		protected _isAndroidMultipleInput(data: string): boolean {
			return !!data && data.length > 1 && _detectBrowser().isAndroid;
		}

		/**
		 * 넘버에디터는 inputmode가 숫자 키패드로 설정되어 있어 키보드에 따라 클립보드 붙여넣기의 inputType이
		 * insertText가 아닌 값(insertCompositionText, insertFromPaste, insertReplacementText)으로 전달됩니다.
		 * 붙여넣기로 판단하지 못하면 허용하지 않는 문자(_isNotAllowChar)로 입력 자체가 차단되므로
		 * 입력 유형을 특정하지 않고 문자를 삽입하는 입력 전체를 대상으로 한다.
		 */
		protected override _isAndroidClipboardPaste(e: events.CUIEvent): boolean {
			if (!_detectBrowser().isAndroid || this._isDropping()) {
				return false;
			}
			// 안드로이드는 클립보드 붙여넣기가 IME 입력으로 전달되어 inputType이 없는 경우가 있어
			// inputType이 있는 경우에만 삽입 유형인지 확인한다. 삭제는 데이터가 없어 아래에서 걸러진다.
			if (e.inputType && this._isInsertInputType(e.inputType) == false) {
				return false;
			}
			return this._isAndroidMultipleInput(this._getPastedData(e));
		}

		/**
		 * beforeinput 처리를 시작하기 전에 이전 입력 정보를 정리하고 안드로이드 클립보드 붙여넣기를 처리합니다.
		 * @param input 인풋 엘리먼트
		 * @param e beforeinput 이벤트
		 * @returns 붙여넣기로 처리하여 이후 입력 처리가 필요 없는 경우 true
		 */
		protected _checkClipboardPasteOnBeforeInput(input: HTMLInputElement, e: events.CUIEvent): boolean {
			// 삼성 브라우저는 클립보드 붙여넣기 시 keydown이 발생하지 않아 이전 붙여넣기의 입력 정보가 남는다.
			this._resetAppliedInput(input);

			// 안드로이드의 클립보드 붙여넣기는 여러 문자가 한번에 입력되어 입력 검증(1개 문자 기준)으로 처리할 수 없다.
			// 값이 있는 상태에서 붙여넣기를 하면 앞선 이벤트(deleteContentBackward)에서 입력이 처리되므로 처리 여부보다 먼저 확인해야 한다.
			if (this._checkAndroidClipboardPaste(input, e) == false) {
				return false;
			}
			e.preventDefault();
			return true;
		}

		/**
		 * @param input 인풋 엘리먼트
		 * @param e input 이벤트
		 * @returns 붙여넣기로 처리한 경우 true
		 */
		protected _checkClipboardPasteOnInput(input: HTMLInputElement, e: events.CUIEvent): boolean {
			if (this._isAndroidClipboardPaste(e) == false) {
				return false;
			}
			if (!this._input) { // keydown이 발생하지 않아 입력 정보가 없는 경우
				this._input = new InputObject(this._currentInputValue ?? input.value, input.selectionStart, input.selectionEnd, InputLocation.input);
			}
			// 붙여넣기가 이미 적용된 값이므로 허용하는 문자만 남도록 정제한다.
			let text = this._transformInputValue(input.value);
			this._input.processed({ text: text, ss: text.length, se: text.length });
			this._input.apply(input, () => { this._currentInputValue = input.value; });
			return true;
		}

		/**
		 * 허용하지 않는 문자가 입력된 경우 입력 전 값으로 복원합니다.
		 * @param e beforeinput 이벤트
		 */
		protected _checkNotAllowChar(e: events.CUIEvent) {
			if (e.data && this._isNotAllowChar(e.data)) {
				this._input.processed(this._input.before);
			}
		}

		protected _beforeinputEvent(input: HTMLInputElement, e: events.CUIEvent) {
			if (this._checkClipboardPasteOnBeforeInput(input, e)) {
				return;
			}
			if (this._input.isProcessed()) {
				return;
			}
			this._checkNotAllowChar(e);
		}

		protected _keydownEvent(input: HTMLInputElement, e: KeyboardEvent, keychar: string) {
			if ((e.keyCode == events.KeyCode.BACKSPACE || e.keyCode == events.KeyCode.DELETE || /[-+\d\.]/.test(keychar)) == false) {
				e.preventDefault();
			}
		}

		protected _keydownEventIMEProcess(input: HTMLInputElement, e: KeyboardEvent) {
			if (_detectBrowser().isAndroid) {
				// 안드로이드는 클립보드 붙여넣기도 IME 입력(Unidentified)으로 발생하여 차단하지 않는다.
				// 허용하지 않는 문자는 beforeinput, input 이벤트에서 처리된다.
				return;
			}
			let IMEKeys = ["Unidentified", "Process"];
			if (IMEKeys.indexOf(e.key) > -1) {
				e.preventDefault();
			}
		}

		protected _focusEvent(input: HTMLInputElement, e: FocusEvent) {
			let getDisplayText = (value: string) => {
				return value ? this._formatter.reverseTransform(value) : "";
			}
			let isGridContains = this._owner.getParent() instanceof cpr.controls.Grid;
			if (isGridContains == false) {
				core.DeferredUpdateManager.INSTANCE.asyncExec(() => {
					let displayText: string = getDisplayText(NumberMask.parseDecimalValue(this._owner._getValue()));
					// input value와 displaytext가 같을 경우 값을 변경하지 않음.
					if (input.value == displayText) {
						return;
					}
					//IE에서 포커스시 셀렉션을 0으로 가져와서 위치가 바뀌는 문제. 포커스 이후 셀렉션 정보조회 가능함.
					let ss = input.selectionStart;
					let se = input.selectionEnd;
					input.value = displayText;
					if (this._owner.focused) {
						input.setSelectionRange(ss, se);
					}
				});
			} else {
				let displayText: string = getDisplayText(NumberMask.parseDecimalValue(this._owner._getValue()));
				// input value와 displaytext가 같을 경우 값을 변경하지 않음.
				if (input.value == displayText) {
					return;
				}
				input.value = displayText;
			}
		}

		protected _blurEvent(input: HTMLInputElement, e: UIEvent) {
			let data: string = this._formatter.reverseTransform(input.value); // mask to data
			let displayText: string = this._formatter._mask(data); // data to format
			if (input.value == displayText) {
				return;
			}
			let ss = input.selectionStart;
			let se = input.selectionEnd;
			input.value = displayText;
			if (_detectBrowser().isAndroid) {//안드로이드에서는 입력시 실시간 마스크가 안되어 blur시 값이 변경된다.
				input.setSelectionRange(ss, se);
			}
		}
	}

	/**
	 * @private
	 */
	export class NumberMask extends DefaultNumberMask {

		/**
		 * 값을 Decimal타입으로 해석하여 반환합니다. 해석 할 수 없는 경우 파라미터 값을 반환합니다.
		 * @param value 
		 * @returns 
		 */
		static parseDecimalValue(value: string): string {
			let decimalValue = value;
			let sign = "";
			if (decimalValue && decimalValue.indexOf("+") == 0) {
				decimalValue = decimalValue.replace("+", "");
				sign = "+";
			}
			let result: string;
			try {
				let decimalType = new foundation.DecimalType(decimalValue);
				result = sign + decimalType.toString();
			} catch (e) {
				result = value;
			}
			return result;
		}

		override _transformInputValue(value: string): string {
			return this._formatter.transform(value);
		}

		override _pasteEvent(input: HTMLInputElement, pasteValue: string, inputValue: string, e: ClipboardEvent) {
			inputValue = this._formatter._convertDefaultFormat(inputValue); // mask to data
			let displayText: string = this._formatter._mask(inputValue); // data to mask
			input.value = displayText;
		}

		override _cutEvent(input: HTMLInputElement, e: ClipboardEvent) {
			// no implement
		}

		override _keydownEventIMEProcess(input: HTMLInputElement, e: KeyboardEvent): void {
			if (_detectBrowser().name == "ie") {
				super._keydownEventIMEProcess(input, e);
			}
		}

		/**
		 * 안드로이드에서 여러 문자가 한번에 입력되면 클립보드 붙여넣기이므로 1개 문자 기준의 입력 검증을 하지 않습니다.
		 * 붙여넣기로 처리하지 못한 경우에도 입력이 차단되지 않고 input 이벤트에서 마스크로 정제됩니다.
		 * @param e beforeinput 이벤트
		 */
		protected override _checkNotAllowChar(e: events.CUIEvent) {
			if (this._isAndroidMultipleInput(e.data)) {
				return;
			}
			super._checkNotAllowChar(e);
		}

		override _inputEvent(input: HTMLInputElement, e: events.CUIEvent) {
			let inputType = e["inputType"];
			let data = this._getPastedData(e);
			//IE11에서 placeholder 설정하면은 input이벤트가 발생한다.
			if (!data) {
				return;
			}

			if (inputType != null && this._isInsertInputType(inputType) == false) {
				return;
			}

			if (!this._input) {
				// 삼성 브라우저는 키보드의 클립보드 버튼으로 붙여넣기 시 keydown이 발생하지 않아 입력 정보가 없다.
				this._input = new InputObject(this._currentInputValue ?? input.value, input.selectionStart, input.selectionEnd, InputLocation.input);
			}

			if (this._input.isProcessed() == false) {
				let keychars = data;
				let text = input.value;
				let formattedValue = this._formatter._mask(this._formatter._convertDefaultFormat(text));
				let ss = input.selectionStart;
				ss = this._formatter._decideCaretPosition(text, formattedValue, ss, ss, ProcType.INSERT, keychars, false);
				this._input.processed({ text: formattedValue, ss: ss, se: ss });
			}
			this._input.apply(input, () => { this._currentInputValue = input.value; });

		}

		override _beforeinputEvent(input: HTMLInputElement, e: events.CUIEvent) {
			if (this._checkClipboardPasteOnBeforeInput(input, e)) {
				return;
			}
			if (this._input.isProcessed()) {
				return;
			}
			let ss = input.selectionStart;
			let data = e.data;

			if (this._isIgnoreInputType(e.inputType)) {
				return;
			}
			// 안드로이드에서 여러 문자가 한번에 입력되면 클립보드 붙여넣기이므로 삽입 가능 여부(1개 문자 기준)로 판단하지 않는다.
			let restoreInput = e.inputType == "deleteContentBackward"
				|| (!this._isAndroidMultipleInput(data) && data && !this._formatter._canInsert(input.value, data, ss));
			if (restoreInput) {
				this._input.processed(this._input.before);
			}

			if (this._input.isProcessed() == false) {
				this._checkNotAllowChar(e);
			}

			let preventDefault = this._input.isProcessed() && this._input.isChanged() == false;
			if (e.cancelable && preventDefault) {
				e.preventDefault();
			}
		}

		override _keydownEvent(input: HTMLInputElement, e: KeyboardEvent, keychar: string) {
			let keycode: number = e.keyCode;
			let inputValue: string = input.value;
			let ss: number = input.selectionStart;
			let se: number = input.selectionEnd;

			let displayText: string = inputValue;
			let caret: number = ss;
			let procType: ProcType;

			// processing backspace & del
			switch (keycode) {
				case events.KeyCode.BACKSPACE: {
					if (ss == se) {
						displayText = this._formatter._deleteBack(displayText, ss);
						procType = ProcType.DELETE_BACK;
					} else {
						displayText = this._formatter._deleteRange(displayText, ss, se);
						procType = ProcType.DELETE_RANGE;
					}
					break;
				}
				case events.KeyCode.DELETE: {
					if (ss == se) {
						displayText = this._formatter._deleteFront(displayText, ss);
						procType = ProcType.DELETE_FRONT;
					} else {
						displayText = this._formatter._deleteRange(displayText, ss, se);
						procType = ProcType.DELETE_RANGE;
					}
					break;
				}
				default: { // character insert
					if (this._isNotAllowChar(keychar)) {
						this._input.processed(this._input.before);
						return;
					}
					// processing option char & text creation
					if (ss != se) {
						displayText = utils.StringUtil.deleteStr(displayText, ss, se);
					}
					displayText = this._formatter._insert(displayText, keychar, ss);
					procType = ProcType.INSERT;
				}
			}

			// calculate caret position
			caret = this._formatter._decideCaretPosition(inputValue, displayText, ss, se, procType, keychar, true);

			this._input.processed({ text: displayText, ss: caret, se: caret });
		}

		override _focusEvent(input: HTMLInputElement, e: FocusEvent) {
			let computeDisplayText = (value: string) => {
				let displayText: string
				if (_isExponential(Number(value))) {
					let decimalValue = NumberMask.parseDecimalValue(value);
					displayText = this._formatter._mask(decimalValue);
				} else {
					displayText = this._formatter._mask(value);
				}
				return displayText;
			}
			let isGridContains = this._owner.getParent() instanceof cpr.controls.Grid;
			if (isGridContains == false) {
				core.DeferredUpdateManager.INSTANCE.asyncExec(() => {
					let displayText: string = computeDisplayText(this._owner._getValue());

					// input value와 displaytext가 같을 경우 값을 변경하지 않음.
					if (input.value == displayText) {
						return;
					}
					//IE에서 포커스시 셀렉션을 0으로 가져와서 위치가 바뀌는 문제. 포커스 이후 셀렉션 정보조회 가능함.
					let ss = input.selectionStart;
					let se = input.selectionEnd;
					input.value = displayText;
					if (this._owner.focused) {
						input.setSelectionRange(ss, se);
					}
				});
			} else {
				let displayText: string = computeDisplayText(this._owner._getValue());
				// input value와 displaytext가 같을 경우 값을 변경하지 않음.
				if (input.value == displayText) {
					return;
				}
				input.value = displayText;
			}
		}

	}

}