		public override _beforeDraw(): void {
			super._beforeDraw();
			let locale = SystemLocale._getValidLocale(this.locale);
			let localeData = LocaleManager.INSTANCE._findLocaleData(locale);
			let firstDayOfWeek = this.firstDayOfWeek == -1 ? null : this.firstDayOfWeek;
			if (localeData) {
				let mergeLocaleData = firstDayOfWeek == null ? {} : { firstDayOfWeek: firstDayOfWeek };
				let momentLocaleData = localeData.dateTime._convertMomentLocaleData(mergeLocaleData);
				_defineMomentLocale(_getControlLocale(this), momentLocaleData);
			}
		}

		public override _afterDraw(firstDraw: boolean = false): void {
			super._afterDraw(firstDraw);
			_deleteMomentLocale(_getControlLocale(this));
		}

		/* shape */
		public _createShape(): cpr.ufc.ControlShape {
			let classNames: string[] = [];
			if (this._calendar instanceof calendar.DayCalendar) {
				this._calendar._setEvents(this._createEventDatas());
			}
			let field: cpr.ufc.ControlShape = this._calendar._createShape();
			switch (this.currentCalendarType) {
				case CalendarType.year: classNames.push("cl-calendar-year"); break;
				case CalendarType.yearmonth: classNames.push("cl-calendar-month"); break;
				case CalendarType.yearmonthdate: classNames.push("cl-calendar-day"); break;
			}

			if (this.showAnniversary) {
				classNames.push("cl-anniversaries");
			}
			let shape: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: classNames,
				attr: {
					tabindex: "-1"
				},
				style: { overflow: "hidden" },
				styler: "root",
				aria: "root",
				events: {
					resize: this._onResize
				},
				eventTargets: [
					ufc.EventTargetType.UICONTROL,
					ufc.EventTargetType.DROPPABLE
				],
				children: [field]
			}
			cpr.ufc.ShapeUtil._setAriaDisabled(shape, this.enabled);
			cpr.ufc.ShapeUtil._setTooltipAttr(shape, { owner: this, title: this.tooltip });
			this._calendar.wrap(shape);
			return shape;
		}

		private _createEventDatas(): { itemContext: any, title: string, tooltip: string, id: string, range: utils.DateRange }[] {
			let items = this._binder.getItems();
			let result = [];
			if (items.length > 0) {
				items.forEach((item: CalendarItem) => {
					let eventData = { itemContext: null, title: item.label, tooltip: item.tooltip ? item.tooltip : item.label, id: item.value, range: null }
					if (item.start && item.end) {
						let dateRange = new utils.DateRange(item.start, item.end);
						if (moment(dateRange.start).isAfter(dateRange.end)) {
							console.error(`eventdata.${item.value}`, `The item's start date must be greater than or equal to its end date.: [controlType: ${this.type}, id: ${this.id ?? null}, value: ${item.value}]`);
						} else {
							eventData.range = dateRange;
							eventData.itemContext = item.toExpressionContext(this);
							result[result.length] = eventData;
						}
					} else if (item.start) {
						let dateRange = new utils.DateRange(item.start, item.start);
						eventData.range = dateRange;
						eventData.itemContext = item.toExpressionContext(this);
						result[result.length] = eventData;
					}
				})
			}
			return result;
		}

		/**event method */
		private _onHeaderClick(e: MouseEvent) {
			let oldCalendarType = this.currentCalendarType;
			this._navigateUp();
			if (this.disposed) {
				return;
			}
			let currentCalendarType = this.currentCalendarType;

			if (oldCalendarType == currentCalendarType && this.focused == false) {
				return;
			}
			// 캘린더 타입이 변경되고 focus가 되어 있는 경우
			// 헤더 클릭으로 상위 캘린더 변경되었을 때 노드 변경으로 포커스가 사라지는 현상 수정.
			if (currentCalendarType == CalendarType.year) {
				this._calendar._focusBySelector(`.${calendar.CalendarFocusableClassName.current}`);
			} else if (currentCalendarType == CalendarType.yearmonth) {
				if (this._calendar._isTypeChangeable()) {
					this._calendar._focusBySelector(`.${calendar.CalendarFocusableClassName.title}`);
				} else {
					this._calendar._focusBySelector(`.${calendar.CalendarFocusableClassName.current}`);
				}
			}
		}

		private _onFooterClick(e: MouseEvent) {
			this._applyCalendar(this._calendar);
			if (this.focused) {
				this._calendar._focusBySelector(`.${calendar.CalendarFocusableClassName.current}`);
			}
		}

		private _onDateClick(e: events.CDateEvent) {
			let currentCalendarType = this.currentCalendarType;
			if (currentCalendarType == this._getComputedCalendarType()) {
				this.dispatchEvent(e);
			}
			this._navigateDown();
			if (this.disposed) {
				return;
			}
			if (this.focused) {
				this._calendar._focusBySelector(`.${calendar.CalendarFocusableClassName.current}`);
			}
		}

		private _onCalendarChange(e: events.CValueChangeEvent) {
			this.value = e.newValue;
			if (this.disposed) {
				return;
			}
			this._applyCalendar(null);
		}

		private _onCalendarItemClick(e: events.CItemEvent) {
			if (e.relativeTargetName == "item") {
				if (e.item.id) {
					let item = this._binder.getItemByValue(e.item.id);
					this._onSelectItem(item, e.ctrlKey)
					let itemEvent = new cpr.events.CItemEvent(cpr.events.ItemEventType.ITEMCLICK, { relativeTargetName: "item", item: item });
					itemEvent.nativeEvent = e.nativeEvent;
					this.dispatchEvent(itemEvent);
				}
			} else if (e.relativeTargetName == "anniversary") {
				if (this._binder.getSelection().length > 0) {
					this._binder.clearSelection();
				}
				this.dispatchEvent(e);
			}
		}

		private _onSelectItem(item: CalendarItem, multiple: boolean = false) {
			let newSelection = this._binder.getSelection().concat();
			let oldSelection = this._binder.getSelection().concat();
			if (multiple) {
				let findItem = _.find(newSelection, (each) => {
					return each.value == item.value;
				});
				if (findItem) {
					newSelection.splice(newSelection.indexOf(findItem), 1);
				} else {
					newSelection.push(item);
				}
			} else {
				newSelection = [item];
			}
			let beforeEvent = new cpr.events.CSelectionEvent(events.SelectionEventType.BEFORE_ITEM_CHANGE, { oldSelection: oldSelection, newSelection: newSelection });
			if (!this.dispatchEvent(beforeEvent)) {
				return;
			}
			if (this.disposed) {
				return;
			}
			this._binder.setSelection(newSelection);

			let event = new cpr.events.CSelectionEvent(events.SelectionEventType.ITEM_CHANGE, { oldSelection: oldSelection, newSelection: newSelection });
			this.dispatchEvent(event)
			this.redraw();
		}

