		override _focusPrevious(includeEntry?: boolean) {
			if (includeEntry) {
				let activeFocusEntry = this._calendar._getActiveFocusEntry();
				if (activeFocusEntry == null) {
					super._focusPrevious(includeEntry);
				} else {
					new CalendarFocusRing(this, activeFocusEntry)._focusPrevious();
				}
			} else {
				super._focusPrevious(includeEntry);
			}
		}

		override _focusNext(includeEntry?: boolean) {
			if (includeEntry) {
				let activeFocusEntry = this._calendar._getActiveFocusEntry();
				new CalendarFocusRing(this, activeFocusEntry)._focusNext();
			} else {
				super._focusNext(includeEntry);
			}
		}

