		private _createCalendar(type: CalendarType, calendar?: calendar.AbstractCalendar, option: { focusable?: boolean, useHeaderFormat?: boolean, useFooterFormat?: boolean } = {}) {
			option = _defaults(option, { focusable: true });
			let cal: calendar.AbstractCalendar = null;
			switch (type) {
				case CalendarType.year:
					cal = new controls.calendar.YearCalendar(this, calendar, option);
					break;
				case CalendarType.yearmonth:
					cal = new controls.calendar.MonthCalendar(this, calendar, option);
					break;
				case CalendarType.yearmonthdate:
					cal = new controls.calendar.DayCalendar(this, calendar, option);
					cal.addEventListener(events.ItemEventType.ITEMCLICK, (e: events.CItemEvent) => { this._onCalendarItemClick(e); });
					cal.addEventListener("more-click", (e: events.CItemEvent) => { this._onCalendarMoreClick(e); });
					// cal.addEventListener(events.SelectionEventType.BEFORE_ITEM_CHANGE, (e: events.CSelectionEvent) => { this._onItemBeforeSelectionChange(e) });
					// cal.addEventListener(events.SelectionEventType.ITEM_CHANGE, (e: events.CSelectionEvent) => { this._onItemSelectionChange(e) });
					break;
			}
			cal._bindProperty("datePosition", () => { return this.datePosition }, (value) => { this.datePosition = value });
			cal.addEventListener("header-click", (e: MouseEvent) => { this._onHeaderClick(e); });
			cal.addEventListener("footer-click", (e: MouseEvent) => { this._onFooterClick(e); });
			cal.addEventListener("date-click", (e: events.CDateEvent) => { this._onDateClick(e); });
			cal.addEventListener("change", (e: events.CValueChangeEvent) => { this._onCalendarChange(e); });
			return cal;
		}

		private _navigateUp(emitEvent: boolean = true) {
			if (this.disposed) {
				return;
			}
			let calendarType = this._getComputedCalendarType();
			if (calendarType == CalendarType.year || calendar.CalendarTypeNumber[this.currentCalendarType] >= calendar.CalendarTypeNumber[this.maxCalendarType]) {
				return;
			}
			let current = this.current;

			if (emitEvent) {
				let preventDefault = this.dispatchEvent(new cpr.events.CDateEvent(events.DateEventType.BEFORENAVIGATE, { date: current }));
				if (!preventDefault) {
					return;
				}
			}
			if (this._calendar instanceof calendar.MonthCalendar) {
				this._calendar = this._createCalendar(CalendarType.year, this._calendar, { focusable: true, useHeaderFormat: false, useFooterFormat: false });

			} else if (this._calendar instanceof calendar.DayCalendar) {
				this._calendar = this._createCalendar(CalendarType.yearmonth, this._calendar, { focusable: true, useHeaderFormat: false, useFooterFormat: false });
			}

			if (emitEvent) {
				this.dispatchEvent(new cpr.events.CDateEvent(events.DateEventType.NAVIGATE, { date: current }));
			}
			this.redraw();
		}

		private _navigateDown(emitEvent: boolean = true) {
			let current = null;
			if (this.disposed) {
				return;
			}
			let calendarType = this._getComputedCalendarType();
			if (this.currentCalendarType == calendarType) {
				return;
			}
			current = this.current;
			if (emitEvent) {
				let preventDefault = this.dispatchEvent(new cpr.events.CDateEvent(events.DateEventType.BEFORENAVIGATE, { date: current }));
				if (!preventDefault) {
					return;
				}
			}

			calendarType = this._getComputedCalendarType();
			if (this._calendar instanceof calendar.YearCalendar) {
				if (calendarType != CalendarType.yearmonth) {
					this._calendar = this._createCalendar(CalendarType.yearmonth, this._calendar, { focusable: true, useHeaderFormat: false, useFooterFormat: false });
				} else {
					this._calendar = this._createCalendar(CalendarType.yearmonth, this._calendar);
				}
			} else if (this._calendar instanceof calendar.MonthCalendar) {
				if (calendarType != CalendarType.yearmonthdate) {
					this._calendar = this._createCalendar(CalendarType.yearmonthdate, this._calendar, { focusable: true, useHeaderFormat: false, useFooterFormat: false });
				} else {
					this._calendar = this._createCalendar(CalendarType.yearmonthdate, this._calendar);
				}
			}
			if (emitEvent) {
				this.dispatchEvent(new cpr.events.CDateEvent(events.DateEventType.NAVIGATE, { date: current }));
			}
			this.redraw();
		}

		private _applyCalendar(calendar: calendar.AbstractCalendar, option: { focusable?: boolean, useHeaderFormat?: boolean, useFooterFormat?: boolean } = {}) {
			let calendarType = this._getComputedCalendarType();
			switch (calendarType) {
				case CalendarType.year:
					if (this._calendar instanceof controls.calendar.YearCalendar == false) {
						this._calendar = this._createCalendar(CalendarType.year, calendar, option);
					}
					break;
				case CalendarType.yearmonth:
					if (this._calendar instanceof controls.calendar.MonthCalendar == false) {
						this._calendar = this._createCalendar(CalendarType.yearmonth, calendar, option);
					}
					break;
				case CalendarType.yearmonthdate:
					if (this._calendar instanceof controls.calendar.DayCalendar == false) {
						this._calendar = this._createCalendar(CalendarType.yearmonthdate, calendar, option);
					}
					break;
			}
			this.redraw();
		}

		private _onResize(e: events.CUIEvent) {
			if (this._calendar instanceof controls.calendar.DayCalendar) {
				this._calendar._onResize(e);
			}
		}

		override focus(forward: boolean = true): void {
			if (forward == false) {
				new CalendarFocusRing(this)._focusLast();
			} else {
				super.focus(forward);
			}
		}

