		/**
		 * 날짜에 해당되는 아이템들을 반환합니다.
		 * @param date 년월일의 정보가 있는 Date객체
		 */
		public getItemsByDate(date: Date): controls.CalendarItem[] {
			let result = [];
			let items = this._binder.getItems();
			if (items.length > 0) {
				items.forEach((item: CalendarItem) => {
					let dateRange = null;
					let eventData = { itemContext: null, title: item.label, id: item.value, range: null }
					if (item.start && item.end) {
						dateRange = new utils.DateRange(item.start, item.end);
					} else if (item.start) {
						dateRange = new utils.DateRange(item.start, item.start);
					}
					eventData.range = dateRange;
					eventData.itemContext = item.toExpressionContext(this);
					if (eventData.range.contains(date, "day")) {
						result[result.length] = item;
					}
				})
			}
			return result;
		}

