		/**
		 * 해당 아이템을 펼칩니다. 펼쳐있는 상태라면 동작하지 않습니다.
		 * @param item 펼쳐질 아이템
		 * @param emitEvent 이벤트(node-open)를 발생시킬지 여부.
		 */
		public expandItem(item: TreeItem, emitEvent: boolean = true): void {
			if (item == null || this._hasChild(item) == false || this.isExpanded(item)) {
				return;
			}

			if (emitEvent == true) {
				let expandEvent: cpr.events.CItemEvent = new cpr.events.CItemEvent("node-open", { item: item });
				let preventDefault = this.dispatchEvent(expandEvent);
				if (!preventDefault) {
					return;
				}
			}
			this._binder.setExpanded(item, true);
			this.redraw();
			this._treeDrawRequest.cancel(TreeDrawRequest.REQUEST_NAME.AUTO_OPEN);
		}

		/** 
		 * 트리아이템이 expanded 되어 있는지 여부를 반환합니다.
		 * @return 트리 아이템이 expanded 되어 있는지 여부.
		 */
		public isExpanded(item: TreeItem): boolean {
			let open = this._binder.isExpanded(item);
			return open == null ? false : open;
		}

		/**
		 * 해당 아이템을 접습니다. 접혀 있는 상태이면 동작하지 않습니다.
		 * @param item 접혀질 아이템
		 * @param emitEvent 이벤트(node-close)를 발생시킬지 여부
		 */
		public collapseItem(item: TreeItem, emitEvent: boolean = true): void {
			if (item == null || this._hasChild(item) == false || this.isExpanded(item) == false) {
				return;
			}

			if (emitEvent) {
				let expandEvent: cpr.events.CItemEvent = new cpr.events.CItemEvent("node-close", { item: item });
				let preventDefault = this.dispatchEvent(expandEvent);
				if (!preventDefault) {
					return;
				}
			}
			this._binder.setExpanded(item, false);
			this.redraw();
			this._treeDrawRequest.cancel(TreeDrawRequest.REQUEST_NAME.AUTO_OPEN);

		}

		/**
		 * 모든 아이템을 펼칩니다.<br/>
		 * 해당 아이템의 하위 아이템을 포함한 모든 아이템을 펼칩니다.<br/>
		 * 해당 아이템이 없을 경우 tree의 모든 아이템이 펼쳐집니다.<br/>
		 * <pre><code>
		 * control.expandAllItems(item); //아이템의 자식 모두 펼치기
		 * or
		 * control.expandAllItems(); //전체 펼치기
		 * </code></pre>
		 * @param root 부모 아이템
		 * @param options 이벤트(node-open)를 발생시킬지 여부와 루트 아이템도 포함하여 펼쳐질지 여부를 설정
		 */
		public expandAllItems(root: TreeItem = null, options?: { includeRoot?: boolean, emitEvent?: boolean }): void {
			options = _defaults({}, options, { includeRoot: true, emitEvent: true });
			if (options.emitEvent) {
				let preventDefault = this.dispatchEvent(new cpr.events.CItemEvent("node-open", {
					item: root == null ? new TreeItem(null, this._binder.getDataProvider().rootValue, null) : root
				}));
				if (!preventDefault) {
					return;
				}
			}

			let rootItem: TreeItem;
			if (root) {
				let findItem = this._binder.findItem({ value: root.value });
				if (findItem) {
					rootItem = options.includeRoot ? { children: [findItem] } as TreeItem : findItem;
				}
			} else {
				rootItem = { children: this._getRootItems(true) } as TreeItem;
			}
			_createTreeStream(rootItem, false, (each: TreeItem) => {
				return each.children;
			}).filter((each: TreeItem) => {
				return each._hasChild();
			}).forEach((each: TreeItem) => {
				this._binder.setExpanded(each, true);
			})
			this.redraw();
			this._treeDrawRequest.cancel(TreeDrawRequest.REQUEST_NAME.AUTO_OPEN);
		}

		/**
		 * 모든 아이템을 접습니다.<br/>
		 * 해당 아이템의 하위 아이템을 포함한 모든 아이템을 접습니다.<br/>
		 * 해당 아이템이 없을 경우 tree의 모든 아이템을 접습니다.<br/>
		 * <pre><code>
		 * control.collapseAllItems(item); // 아이템의 자식 모두 접기
		 * or
		 * control.collapseAllItems(); // 전체 접기
		 * </code></pre>
		 * @param root 부모 아이템
		 * @param options 이벤트(node-close)를 발생시킬지 여부와 루트 아이템도 포함하여 접힐지 여부를 설정
		 */
		public collapseAllItems(root: TreeItem = null, options?: { includeRoot?: boolean, emitEvent?: boolean }): void {
			options = _.defaults({}, options, { includeRoot: false, emitEvent: true });
			if (options.emitEvent) {
				let preventDefault = this.dispatchEvent(new cpr.events.CItemEvent("node-close", {
					item: root == null ? new TreeItem(null, this._binder.getDataProvider().rootValue, null) : root
				}));
				if (!preventDefault) {
					return;
				}
			}
			if (root) {
				let findItem = this._binder.findItem({ value: root.value });
				if (findItem) {
					let rootItem = options.includeRoot ? { children: [findItem] } as TreeItem : findItem;
					_createTreeStream(rootItem, false, (each: TreeItem) => {
						return each.children;
					}).filter((each: TreeItem) => {
						return each._hasChild();
					}).forEach((each: TreeItem) => {
						this._binder.setExpanded(each, false);
					});
				}
			} else {
				this._binder._collapseAllItems();
			}

			this.redraw();
			this._treeDrawRequest.cancel(TreeDrawRequest.REQUEST_NAME.AUTO_OPEN);
		}

		/**
		 * 해당 아이템의 expand 상태를 전환합니다.
		 * @param item 전환될 아이템
		 * @param emitEvent 이벤트(node-open, node-close)를 발생시킬지 여부
		 */
		public toggle(item: TreeItem, emitEvent: boolean = true): void {
			if (item == null || this._hasChild(item) == false) {
				return;
			}
			let expanded = !this.isExpanded(item);
			if (emitEvent) {
				let eventName = expanded ? "node-open" : "node-close";
				let expandEvent: cpr.events.CItemEvent = new cpr.events.CItemEvent(eventName, { item: item });
				let preventDefault = this.dispatchEvent(expandEvent);
				if (!preventDefault) {
					return;
				}
			}
			this._binder.setExpanded(item, expanded);
			this.redraw();
			this._treeDrawRequest.cancel(TreeDrawRequest.REQUEST_NAME.AUTO_OPEN);
		}

		/**
		 * 아이템을 찾아 스크롤을 위치합니다.
		 * 스크롤 존재 시 해당 아이템을 기준으로 스크롤이 이동합니다.
		 * @param item 포커스할 아이템.
		 * @deprecated 기능과 동작이 달라 제거됩니다. {@link revealItem}을 사용하시기 바랍니다.
		 */
		public focusItem(item: TreeItem): void {
			this.revealItem(item);
		}

		/**
		 * 아이템을 찾아 스크롤을 위치합니다.
		 * 스크롤 존재 시 해당 아이템을 기준으로 스크롤이 이동합니다.
		 * @param item 리빌할 아이템.
		 */
		public revealItem(item: TreeItem, verticalAlign?: ScrollIntoViewAlignType): void {
			if (item == null) {
				throw new cpr.exceptions.IllegalArgumentException();
			}

			this._revealItem = item; // 접혀 있는 아이템을 펼치기 위한 변수
			if (this.useVirtualScroll == false) {
				cpr.core.DeferredUpdateManager.INSTANCE.asyncExec(() => {
					if (this.disposed) {
						return;
					}
					let viewport = this._getRenderer().getNamedNode("viewport");
					let domTraverser = ufc._traverseFromElement(viewport)._child('[data-itemid="' + item.value + '"]');

					if (!domTraverser) {
						return;
					}
					let li = domTraverser._getElement();
					_scrollIntoView(li, viewport, { verticalAlign: verticalAlign });
				});

			} else {
				cpr.core.DeferredUpdateManager.INSTANCE.asyncExec(() => {
					let index = -1;
					this._visibleItems.some((each: TreeItem, idx: number) => {
						if (each.value == item.value) {
							index = idx;
							return true;
						}
					});
					if (index == -1) {
						return;
					}
					this._getVirtualScroll().scrollIntoView(index, { verticalAlign: verticalAlign });
				});
			}
			this.redraw();
		}

