
namespace cpr.controls.navigation {

	/**
	 * @private
	 */
	export abstract class AbstractHorizontalBar {
		protected _beforeMouseoverItem: MenuItem = null;
		private _hiddenMenuMouseLeaved: boolean = false;
		private _focusItemTimer: utils.Timer;

		private _mouseLeaveTimer: utils.Timer;
		protected _hoveredItem: MenuItem = null;
		protected _openedItem: MenuItem = null;
		protected _touchMoved: boolean;
		protected _focusTrigger: { type: string, forward: boolean };
		protected _owner: NavigationBar;
		protected _binder: provider.MenuDataBinder;
		protected _rootItems: MenuItem[];
		protected _touchRoller: internal.TouchRoller = internal.newTouchRoller();

		private _touchEventDispatcher = (e: any) => {

			switch (e.type) {
				case "touchmove":
					this._ontouchmove(e);
					break;
				case "touchend":
					this._ontouchend(e);
					break;
			}
		}

		constructor(owner: NavigationBar, binder: provider.MenuDataBinder) {
			this._owner = owner;
			this._binder = binder;
			this._focusItemTimer = utils.Timer.create("navigationbar-focusitem");
			this._mouseLeaveTimer = utils.Timer.create("navigationbar-mouseleave");

		}

		//method
		public _getFocusedItem(): MenuItem {
			return this._getHover();
		}

		public _getTopParentItem(childItem: MenuItem) {
			if (!childItem) {
				return childItem;
			}
			let rootItem = childItem;
			while (rootItem.parentItem != null) {
				rootItem = rootItem.parentItem;
			}
			return rootItem;
		}

		public _focusItem(item: MenuItem) {
			this._setHover(item);
			this._focusItemTimer.init(() => {
				let activeFocusItem = this._getHover();
				if (item?._equalsValue(activeFocusItem)) {
					return;
				}
				this._setHover(item);
			}).schedule();
		}

		public abstract _setFocusedItem(item: MenuItem, options: { preventScroll: boolean });

		public _isHiddenMenu() {
			if (this._owner._getRenderer().hasDrawn() == false) {
				return false;
			}
			let parent = this._owner.getParent();
			let child: UIControl = this._owner;
			let rect = this._owner.getActualRect();
			let parentRect = parent.getActualRect();
			if (parent.isAppContainer && parent.getAppInstance().isRootAppInstance()) {
				return rect.bottom < 0 || rect.top - parentRect.height > 0;
			} else {
				while (parent != null) {
					if (rect.top + rect.height < parentRect.top) {
						break;
					}
					if (rect.top > parentRect.bottom) {
						break;
					}
					child = parent;
					parent = parent.getParent();
					if (parent) {
						let childConstraint = parent.getConstraint(child);
						if (layouts._isManualConstraint(childConstraint) && childConstraint.styles["position"] == "fixed") {
							break;
						}
						parentRect = parent.getActualRect();
					}
				}
				return rect.top + rect.height < 0 || rect.top + rect.height < parentRect.top || rect.top > parentRect.bottom;
			}
		}

		public _getOpenedItem(): MenuItem {
			return this._openedItem;
		}

		/**
		 * 아이템이 열려있는지 여부
		 * @param item 
		 * @returns 
		 */
		public _isOpened(item: MenuItem): boolean {
			return this._openedItem?._equalsValue(item) ?? false;
		}

		protected _setOpen(item: MenuItem, options: { emitEvent?: boolean, nativeEvent?: Event } = {}) {
			if (this._isOpened(item)) {
				return;
			}
			_defaults(options, { emitEvent: true, nativeEvent: null });
			this._close(options);
			this._open(item, options);
		}

		public _open(item: MenuItem, options: { emitEvent?: boolean, nativeEvent?: Event } = {}): boolean {
			if (this.disposed || !item || item._hasChild() == false) {
				return false;
			}
			_defaults(options, { emitEvent: true, nativeEvent: null });
			if (options.emitEvent == true) {
				let expandEvent: cpr.events.CItemEvent = new cpr.events.CItemEvent("menu-open", { item: item });

				let canDispatchEvent = this._owner.dispatchEvent(expandEvent);
				if (!canDispatchEvent) {
					return false;
				}
			}

			this._openedItem = item;
			this._owner.redraw();
			return true;
		}

		public _close(options: { emitEvent?: boolean, nativeEvent?: Event } = {}) {
			if (this.disposed || !this._openedItem) {
				return false;
			}
			_defaults(options, { emitEvent: true, nativeEvent: null });
			if (options.emitEvent) {
				let expandEvent: cpr.events.CItemEvent = new cpr.events.CItemEvent("menu-close", { item: this._openedItem });

				let preventDefault = this._owner.dispatchEvent(expandEvent);
				if (!preventDefault) {
					return false;
				}
			}
			this._openedItem = null;
			this._owner.redraw();
			return true;
		}

		public _revealItem(item: MenuItem): void {
			this._updateScrollByHover(item, this._hoveredItem);
		}

		protected _getRootItems(newCreate: boolean = false) {
			if (!this._rootItems || newCreate) {
				this._rootItems = this._binder.getViewItems();
			}
			return this._rootItems;
		}

		protected abstract _resetMenu();
		protected abstract _clearMenu();

		protected abstract _getHover();
		protected abstract _setHover(item: MenuItem, options?: {});

		protected _getBarContentNode() {
			return this._owner._getRenderer().getNamedNode(ufc.NodeNames.ITEMS_SCROLLER);
		}

		private _getMaxContentLeft() {
			let barContentNode = this._getBarContentNode();
			return barContentNode.scrollWidth - barContentNode.clientWidth;
		}

		private _getScrollLeft() {
			let barContentNode = this._getBarContentNode();
			return barContentNode.scrollLeft;
		}

		private _setScrollLeft(e: events.CUIEvent, scrollLeft: number): number {
			if (scrollLeft < 0) {
				scrollLeft = 0;
			} else if (scrollLeft > this._getMaxContentLeft()) {
				scrollLeft = this._getMaxContentLeft();
			}
			this._checkScrollBtn();
			if (this._getScrollLeft() == scrollLeft) {
				return -1;
			}

			this._resetMenu();
			this._clearHoveredItem();

			let barContentNode = this._getBarContentNode();
			barContentNode.scrollLeft = scrollLeft;

			return scrollLeft;
		}

		private _setHScrollbarLeft(e: events.CUIEvent, scrollLeft: number): boolean {
			let movedScrollLeft: number = this._setScrollLeft(e, scrollLeft);
			if (movedScrollLeft == -1) {
				return false;
			}
			return true;
		}

		protected _getMenuItemId(item: MenuItem) {
			return ufc.NodeUUIDMapper.INSTANCE._createPartialUUID(this._owner, item.value);
		}

		protected _getItemNodeName(index: number) {
			return "baritem" + index;
		}

		protected _getParent(item: MenuItem, condition: (item: MenuItem) => boolean) {
			if (!item) {
				return null;
			}
			if (!condition) {
				return item.parentItem;
			}

			let parentItem = item.parentItem;
			while (parentItem != null && condition(parentItem) == false) {
				parentItem = parentItem.parentItem;
			}
			return parentItem;
		}

		protected _updateScrollByHover(currentHover: MenuItem, beforeHover: MenuItem) {
			if (currentHover == null) {
				return;
			}
			let children = this._getRootItems();
			let beforeIdx = -1;
			let findIdx = _.findIndex(children, { value: currentHover.value });
			if (beforeHover) {
				beforeIdx = _.findIndex(children, { value: beforeHover.value });
			}
			if (findIdx > beforeIdx) {
				this._scrollLeft(findIdx);
			} else {
				this._scrollRight(findIdx);
			}
		}

		private _getItemNodeByIndex(index: number, rootNode: HTMLElement) {
			if (!rootNode) {
				return null;
			}
			let itemElement = <HTMLElement>rootNode.querySelector('.cl-navigationbar-item[data-itemidx="' + index + '"] ');
			return itemElement
		}

		protected _clearHoveredItem(options: { closeMenu?: boolean } = {}) {
			if (this._hoveredItem == null) {
				return;
			}
			_defaults(options, { closeMenu: true });
			if (options.closeMenu && this._isOpened(this._hoveredItem)) {
				this._close();
			}
			this._hoveredItem = null;
			this._owner.redraw();
		}

		protected _getHoveredItem(): MenuItem {
			return this._hoveredItem;
		}

		/**
		 * 내비게이션바에서의 호버 아이템을 설정합니다.
		 * @param item 
		 * @returns 
		 */
		protected _setHoveredItem(item: MenuItem, options: { preventOpen?: boolean, nativeEvent?: Event, doInitSubMenu?: boolean, updateScroll?: boolean, useSameCheck?: boolean } = {}) {
			_defaults(options, { doInitSubMenu: true, updateScroll: true, useSameCheck: true, nativeEvent: null, preventOpen: false });

			if (options.updateScroll) {
				this._updateScrollByHover(item, this._hoveredItem);
			}
			let isSameItem = item?._equalsValue(this._hoveredItem) ?? false;

			if (!isSameItem && !options.preventOpen) {
				if (item && item._hasChild()) {
					if (!this._isOpened(item)) {
						this._close({ nativeEvent: options.nativeEvent });
						this._open(item, { nativeEvent: options.nativeEvent });
					}
				} else {
					if (this._isOpened(this._hoveredItem)) {
						this._close();
					}
				}

			}

			if (options.useSameCheck && isSameItem) {
				return;
			}
			this._hoveredItem = item;
			if (options.doInitSubMenu) {
				this._resetMenu();
			}
			this._owner.redraw();
		}

		protected _isHoveredItem(item: MenuItem) {
			return this._hoveredItem?._equalsValue(item) ?? false;
		}

		private _scrollRight(index: number): boolean {
			let wrapperNode = this._owner._getRenderer().getNamedNode(ufc.NodeNames.ITEMS_SCROLLER);
			let itemElement = this._getItemNodeByIndex(index, wrapperNode);
			if (!itemElement) {
				return false;
			}
			let columnOffset = itemElement.offsetLeft;

			let viewMinOffset = wrapperNode.scrollLeft;
			let viewMaxOffset = viewMinOffset + wrapperNode.clientWidth;

			if (viewMinOffset >= columnOffset || viewMaxOffset <= columnOffset) {
				wrapperNode.scrollLeft = Math.floor(columnOffset / itemElement.scrollWidth) * itemElement.scrollWidth;
			}
			return false;
		}

		private _scrollLeft(index: number): boolean {
			let barWrapperNode = this._owner._getRenderer().getNamedNode(ufc.NodeNames.ITEMS_SCROLLER);

			let itemElement = this._getItemNodeByIndex(index, barWrapperNode);
			if (!itemElement) {
				return false;
			}
			let columnOffset = itemElement.offsetLeft;
			let nextRowOffset = columnOffset + itemElement.scrollWidth;
			let viewMinOffset = barWrapperNode.scrollLeft;
			let viewMaxOffset = viewMinOffset + barWrapperNode.clientWidth;

			if (viewMinOffset >= nextRowOffset || viewMaxOffset <= nextRowOffset) {
				barWrapperNode.scrollLeft = nextRowOffset - barWrapperNode.clientWidth;
			}

			return false;
		}

		protected _checkScrollBtn() {
			let scrollerNode = this._owner._getRenderer().getNamedNode(ufc.NodeNames.ITEMS_SCROLLER);
			let browserName = _detectBrowser().name;
			if (this._owner.barScrollButtonPosition == NavigationBarScrollButtonPosition.none) {
				this._owner._getRenderer().updateStyle(ufc.NodeNames.ITEMS_SCROLL_LEFT, { display: "none" }, true);
				this._owner._getRenderer().updateStyle(ufc.NodeNames.ITEMS_SCROLL_RIGHT, { display: "none" }, true);
			} else if (scrollerNode) {
				let scrollWidth = scrollerNode.scrollWidth;
				if (browserName == "ie") {
					scrollWidth = scrollWidth - 1;
				}
				if (scrollWidth > scrollerNode.clientWidth) {
					this._owner._getRenderer().updateStyle(ufc.NodeNames.ITEMS_SCROLL_LEFT, { display: "block" }, true);
					this._owner._getRenderer().updateStyle(ufc.NodeNames.ITEMS_SCROLL_RIGHT, { display: "block" }, true);
					if (scrollerNode.scrollLeft == 0) {
						this._owner._getRenderer().updateClass(ufc.NodeNames.ITEMS_SCROLL_LEFT, [], [ufc.Classes.DISABLED]);
						this._owner._getRenderer().updateClass(ufc.NodeNames.ITEMS_SCROLL_RIGHT, [ufc.Classes.DISABLED], []);
					} else if (_testScrollMaxX(scrollerNode)) {
						this._owner._getRenderer().updateClass(ufc.NodeNames.ITEMS_SCROLL_LEFT, [ufc.Classes.DISABLED], []);
						this._owner._getRenderer().updateClass(ufc.NodeNames.ITEMS_SCROLL_RIGHT, [], [ufc.Classes.DISABLED]);
					} else {
						this._owner._getRenderer().updateClass(ufc.NodeNames.ITEMS_SCROLL_LEFT, [ufc.Classes.DISABLED], []);
						this._owner._getRenderer().updateClass(ufc.NodeNames.ITEMS_SCROLL_RIGHT, [ufc.Classes.DISABLED], []);
					}
				} else {
					this._owner._getRenderer().updateStyle(ufc.NodeNames.ITEMS_SCROLL_LEFT, { display: "none" }, true);
					this._owner._getRenderer().updateStyle(ufc.NodeNames.ITEMS_SCROLL_RIGHT, { display: "none" }, true);
				}
			}
		}

		//events
		private _cancelTimeoutEvent(name: string) {
			if (name == "mouseleave") {
				this._mouseLeaveTimer.cancel();
			}
		}

		private _executeTimeoutEvent(name: string) {
			if (name == "mouseleave") {
				this._mouseLeaveTimer.scheduleRun();
			}
		}

		private _mouseLeaveImmediately(e?: MouseEvent) {
			this._beforeMouseoverItem = null;
			this._clearHoveredItem();
		}

		protected _onkeydown(e: events.CKeyboardEvent) {
			this._executeTimeoutEvent("mouseleave");
			this._navigateBar(e, this._getHover());
		}
		protected abstract _getActiveMenu(): menu.IMenu;

		public abstract _onfocus(e: events.CFocusEvent);

		public _checkControlStateForEvent(e: events.CEvent = null): boolean {
			return true;
		}

		public _onblur(e: events.CFocusEvent) {
			this._focusItemTimer.cancel();
		}

		protected _onmousedown(e: MouseEvent) {
			let target: HTMLElement = <HTMLElement>e.target;

			if (target.classList.contains("cl-navigationbar-bar") && !this._owner.focused) {
				this._owner._focusSelf();
				e.preventDefault();
			}

			if (this._owner.focused) {
				return;
			}
			if (!this._focusTrigger) this._focusTrigger = { type: "mousedown", forward: true };
		}

		protected _onmouseover(e: MouseEvent) {

			let rootElement: HTMLElement = <HTMLElement>e.currentTarget;
			let eventElement: HTMLElement = <HTMLElement>e.target;

			let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(eventElement)._closest("[data-role='menuitem']", rootElement);
			if (domTraverser == null) {
				return;
			}

			let item: MenuItem = this._getItemByElement(domTraverser._getElement());
			if (item == null) {
				throw new cpr.exceptions.CError("The item does not exist.");
			}
			let isSameItemMouseOver = this._beforeMouseoverItem && this._beforeMouseoverItem.value == item.value;
			// dispatchItemMouseover에서 _beforeMouseoverItem 값 갱신
			if (!this._dispatchItemMouseover(item, e) || this._owner.expandTrigger == "click") {
				return;
			}

			if (this._owner.getItemEnable(item)) {
				if (!isSameItemMouseOver) {
					this._setOpen(item, { nativeEvent: e });
				}
				if (this._isHoveredItem(item) == false) {
					this._setHoveredItem(item, { doInitSubMenu: true, updateScroll: false, nativeEvent: e, preventOpen: true });
				}
			}

		}

		protected _onMenuHiddenMouseLeave(e: events.CMouseEvent) {
			this._hiddenMenuMouseLeaved = true;
		}

		protected _onMenuMouseEnter(e: events.CMouseEvent) {
			this._cancelTimeoutEvent("mouseleave");
		}

		protected abstract _onMenuItemSelect(e: events.CUIEvent);
		protected abstract _onMenuItemClick(e: events.CItemEvent);
		protected abstract _onMenuItemSelected(e: events.CUIEvent);

		protected _onMenuItemMouseOver(e: events.CItemEvent) {
			this._owner.dispatchEvent(e);
		}

		protected _onMenuMouseLeave(e: events.CMouseEvent) {
			this._clearHoveredItem();
		}


		protected _onclick(e: MouseEvent | TouchEvent): void {
			let rootElement: HTMLElement = <HTMLElement>e.currentTarget;
			let eventElement: HTMLElement = <HTMLElement>e.target;

			if (eventElement.classList.contains("cl-navigationbar-next") || eventElement.classList.contains("cl-navigationbar-prev")) {
				let wrapperNode = this._owner._getRenderer().getNamedNode(ufc.NodeNames.ITEMS_SCROLLER);
				if (wrapperNode) {
					let nextBtn = eventElement.classList.contains("cl-navigationbar-next");
					this._onClickScrollBtn(wrapperNode, nextBtn);
				}
				return;
			}

			let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(eventElement)._closest("[data-role='menuitem']", rootElement);
			if (domTraverser == null) {
				return;
			}

			let item: MenuItem = this._getItemByElement(domTraverser._getElement());
			if (item == null) {
				throw new cpr.exceptions.CError("The item does not exist.");
			}
			if (!this._owner.getItemEnable(item)) {
				return;
			}

			if (e.type == "touchend") {
				this._onMenuBarClickInMobile(item, e as TouchEvent);
			} else {
				this._onMenuBarClickInPC(item, e as MouseEvent);
			}

		}

		private _onMenuBarClickInMobile(item: MenuItem, e: TouchEvent) {
			let isHoveredItem = this._isHoveredItem(item);
			let isOpened = this._isOpened(item);
			if (item._hasChild()) {
				if (isHoveredItem) {
					if (isOpened) {
						let isSuccess = this._onItemSelect(item, e);
						if (isSuccess) {
							this._close({ nativeEvent: e });
						}
					} else {
						this._setOpen(item);
					}
				} else {
					this._setHoveredItem(item, { doInitSubMenu: true, updateScroll: false, nativeEvent: e, preventOpen: true });
					this._setOpen(item);
				}
			} else {
				if (!isHoveredItem) {
					this._setHoveredItem(item, { doInitSubMenu: true, updateScroll: false, nativeEvent: e, preventOpen: true });
				}
				this._onItemSelect(item, e);
				this._close({ nativeEvent: e });
			}

			let itemClickEvent = new cpr.events.CItemEvent(events.ItemEventType.ITEMCLICK, {
				item: item
			});
			itemClickEvent.nativeEvent = e;
			this._dispatchEvent(itemClickEvent);
		}

		private _onMenuBarClickInPC(item: MenuItem, e: MouseEvent) {

			this._setHoveredItem(item, { doInitSubMenu: true, updateScroll: true, nativeEvent: e, preventOpen: true });

			let ignoreSelect = this._owner.expandTrigger == ExpandTriggerType[ExpandTriggerType.click] && item._hasChild();
			if (!ignoreSelect) { // 이전 동작 유지- 수정 예정
				this._onItemSelect(item, e);
				if (this.disposed) {
					return;
				}
				this._close({ nativeEvent: e });
			} else {
				this._setOpen(item);
			}

			let itemClickEvent = new cpr.events.CItemEvent(events.ItemEventType.ITEMCLICK, {
				item: item
			});
			itemClickEvent.nativeEvent = e;
			this._dispatchEvent(itemClickEvent);

		}

		/**
		 * 스크롤 버튼 클릭
		 * @param barWrapper 스크롤을 포함하는 노드
		 * @param next 다음으로 이동할지 여부
		 */
		private _onClickScrollBtn(barWrapper: HTMLElement, next: boolean) {
			let itemElement: HTMLElement = barWrapper.querySelector(".cl-navigationbar-item");
			let columnWidth = 0;
			if (itemElement) {
				columnWidth = itemElement.getBoundingClientRect().width;
			}
			let scrollLeft = barWrapper.scrollLeft;
			if (next) {
				barWrapper.scrollLeft = barWrapper.scrollLeft + columnWidth;
			} else {
				barWrapper.scrollLeft = barWrapper.scrollLeft - columnWidth;
			}
			if (barWrapper.scrollLeft != scrollLeft) {
				this._resetMenu();
				this._close();
			}
			this._checkScrollBtn();
		}

		protected _onmouseleave(e: MouseEvent) {
			let rootElement: HTMLElement = <HTMLElement>e.currentTarget;
			let eventElement: HTMLElement = <HTMLElement>e.target;
			let relatedTarget = <HTMLElement>e.relatedTarget;
			if (this._hiddenMenuMouseLeaved) {
				this._hiddenMenuMouseLeaved = false;
				return;
			}
			if (rootElement != eventElement) {
				return;
			}
			if (relatedTarget && (relatedTarget.classList.contains("cl-navigationbar-list") || relatedTarget.classList.contains("cl-navigationbar-category"))) {
				return;
			}
			this._cancelTimeoutEvent("mouseleave");
			this._mouseLeaveTimer.init(() => {
				this._mouseLeaveImmediately(e)
			}).schedule(300);
		}

		protected _onmouseout(e: events.CMouseEvent) {
			let rootElement: HTMLElement = <HTMLElement>e.currentTarget;
			let eventElement: HTMLElement = <HTMLElement>e.target;

			let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(eventElement)._closest("[data-role='menuitem']", rootElement);
			if (domTraverser == null) {
				return;
			}
			let relatedDomTraverser = ufc._traverseFromElement(e.relatedTarget as HTMLElement)._closest("[data-role='menuitem']", rootElement);
			if (relatedDomTraverser == null || (relatedDomTraverser != null && domTraverser._getElement() != relatedDomTraverser._getElement())) {
				this._beforeMouseoverItem = null;
			}
		}

		protected _startTouchEvent() {
			if (core.Platform.INSTANCE.browserInfo.supportsPassiveEvent) {
				document.body.addEventListener("touchmove", this._touchEventDispatcher, { passive: false });
			} else {
				document.body.addEventListener("touchmove", this._touchEventDispatcher);
			}
			cpr.events.BodyEventTarget.INSTANCE.addEventListener("touchend", this._touchEventDispatcher);
		}

		protected _ontouchstart(e: events.CTouchEvent) {
			let touch = e.touches.length == 1 ? e.touches[0] : null;
			if (touch != null) {
				this._touchMoved = false;
			}
			this._startTouchEvent();
			//prevneDefault를 하면 마우스 이벤트가 발생하지 않는 대신 미세한 차이에도 touchmove가 발생함.
			let barContentNode = this._getBarContentNode();
			let scrollLeft = barContentNode.scrollLeft;
			this._touchRoller._touchStart(e, 0, scrollLeft);
		}

		private _ontouchmove(e: events.CTouchEvent) {
			let touch = e.touches.length == 1 ? e.touches[0] : null;
			if (touch != null) {
				this._touchMoved = true;
			}

			this._touchRoller._touchMove(e, (scrollTop: number, scrollLeft: number): boolean => {

				let movedX: boolean = scrollLeft !== -1 ? this._setHScrollbarLeft(e, scrollLeft) : false;
				return movedX;
			});
		}

		private _ontouchend(e: events.CTouchEvent & events.CEvent) {
			let rootNode = this._getBarContentNode();
			let nodeScrollLeft = rootNode.scrollLeft;
			this._touchRoller._touchEnd(e, 0, nodeScrollLeft,
				(scrollTop: number, scrollLeft: number): boolean => {
					let movedX: boolean = scrollLeft !== -1 ? this._setHScrollbarLeft(e, scrollLeft) : false;
					return movedX;
				}
			);
			this._endTouchEvent();

			if (e.cancelable) e.preventDefault();// 마우스 이벤트 방지
			// 터치가 하나일때만 동작해야한다.
			if (e.touches.length > 0 || e.changedTouches.length != 1) {
				return;
			}

			if (this._touchMoved == false) {
				if (this._owner.focused == false) {
					if (!this._focusTrigger) this._focusTrigger = { type: "touchend", forward: true };
					this._owner._focusImmediately();
				}
				core.DeferredUpdateManager.INSTANCE.asyncExec(() => { // 포커스 이벤트 다음에 menu-open 이벤트 발생하기 위해 비동기 코드 사용
					this._onclick(e);
				})
			}
		}

		private _endTouchEvent() {
			document.body.removeEventListener("touchmove", this._touchEventDispatcher);
			cpr.events.BodyEventTarget.INSTANCE.removeEventListener("touchend", this._touchEventDispatcher);
		}

		protected _onwheel(e: events.CWheelEvent) {
			if (e._getMod1Key() === true) { // 확대/축소
				return;
			}
			let delta: { x: number, y: number } = internal.ScrollbarUtil._getScrollPaneWheelDelta(e)
			if (delta == null) {
				return;
			}
			let barWrapperNode = this._owner._getRenderer().getNamedNode(ufc.NodeNames.ITEMS_SCROLLER);
			let scrollLeft = barWrapperNode.scrollLeft;
			if (delta.x != 0) {
				barWrapperNode.scrollLeft = scrollLeft + delta.x;
			}

			if (barWrapperNode.scrollLeft != scrollLeft) {
				this._resetMenu();
				this._close({ nativeEvent: e });

				this._checkScrollBtn();
				e.stopPropagation();
				e.preventDefault();
			}
		}

		protected _dispatchItemMouseover(item: MenuItem, e: MouseEvent): boolean {
			if (this._beforeMouseoverItem && this._beforeMouseoverItem.value == item.value) {
				return true;
			}
			this._beforeMouseoverItem = item;
			if (this._owner._hasCustomEventListener("item-mouseover") == false) {
				return true;
			}
			let itemMouseOverEvent = new events.CItemEvent("item-mouseover", { item: item });
			itemMouseOverEvent.nativeEvent = e;
			return this._owner.dispatchEvent(itemMouseOverEvent);
		}

		/**
		 * 
		 * @param includeEntry 
		 * @returns 포커스 설정 성공 여부
		 */
		public abstract _focusPrevious(includeEntry?: boolean): boolean;
		/**
		 * 
		 * @param includeEntry 
		 * @returns 포커스 설정 성공 여부
		 */
		public abstract _focusNext(includeEntry?: boolean): boolean;

		private _findItemByAccessKey(accessKey: string): MenuItem {
			let items = this._getRootItems();

			let rootItem = { children: items } as any as MenuItem;
			let result = _createTreeStream(rootItem, false, (each: MenuItem) => {
				return this._owner.getItemEnable(each) ? each.children : [];
			}).find((each: MenuItem) => {
				return each.accessKey && each.accessKey.toUpperCase() == accessKey.toUpperCase();
			}) as MenuItem

			return result;
		}

		protected _hoverForward(item: MenuItem, options: { loop?: boolean, doInitSubMenu?: boolean, nativeEvent?: Event } = {}): MenuItem {
			_defaults(options, { doInitSubMenu: true, loop: true, nativeEvent: null });
			let children = this._getRootItems();
			let len = children.length;
			if (len == 0) {
				return;
			}
			let startIndex = item != null ? _.findIndex(children, { value: item.value }) : -1;
			let getNextIndex = (index: number) => {
				if (options.loop) {
					return index + 1 < len ? index + 1 : 0
				} else {
					return index + 1;
				}
			}
			let nextIndex = getNextIndex(startIndex);
			if (this._owner.getItemEnable(children[nextIndex]) == false) {
				startIndex = nextIndex;
				nextIndex = getNextIndex(nextIndex);
				while (startIndex != nextIndex && nextIndex < len) {
					if (this._owner.getItemEnable(children[nextIndex]) == false) {
						nextIndex = getNextIndex(nextIndex);
					} else {
						break;
					}
				}
			}
			let nextItem = null;
			if (startIndex != nextIndex && nextIndex < len) {
				nextItem = children[nextIndex];
			}

			if (nextItem) {
				this._setHoveredItem(nextItem, { doInitSubMenu: options.doInitSubMenu, nativeEvent: options.nativeEvent });
			}
			return nextItem;
		}

		protected _hoverBackward(item: MenuItem, options: { loop?: boolean, doInitSubMenu?: boolean, nativeEvent?: Event } = {}): MenuItem {
			_defaults(options, { loop: true, doInitSubMenu: true, nativeEvent: null });
			let children = this._getRootItems();
			let len = children.length;
			if (len == 0) {
				return;
			}
			let startIndex = item != null ? _.findIndex(children, { value: item.value }) : -1;
			if (startIndex == -1) {
				startIndex = len;
			}
			let getNextIndex = (index: number) => {
				if (options.loop) {
					return index - 1 >= 0 ? index - 1 : len - 1;
				} else {
					return index - 1;
				}
			}
			let nextIndex = getNextIndex(startIndex);
			if (this._owner.getItemEnable(children[nextIndex]) == false) {
				startIndex = nextIndex;
				nextIndex = getNextIndex(nextIndex);
				while (startIndex != nextIndex && nextIndex > -1) {
					if (this._owner.getItemEnable(children[nextIndex]) == false) {
						nextIndex = getNextIndex(nextIndex);
					} else {
						break;
					}
				}
			}
			let nextItem = null;
			if (startIndex != nextIndex && nextIndex > -1) {
				nextItem = children[nextIndex];
			}

			if (nextItem) {
				this._setHoveredItem(nextItem, { doInitSubMenu: options.doInitSubMenu, nativeEvent: options.nativeEvent });
			}
			return nextItem;
		}

		/**
		 * 브라우저 뷰포트 리사이즈 이벤트
		 * @param e 
		 * @returns 
		 */
		public _onWindowResize(e: events.CUIEvent) {
			if (!this._owner._isShowing()) {
				return;
			}
			if (this._getOpenedItem() != null) {
				this._owner.redraw();
			}
		}

		/**
		 * 컨트롤 리사이즈 감지 이벤트
		 * @param e 
		 * @returns 
		 */
		public _onResize(e: events.CUIEvent) {
			if (!this._owner._isShowing()) {
				return;
			}
			this._checkScrollBtn();
		}

		public _onScroll(e: events.CScrollEvent) {
			if (this._getOpenedItem() == null) {
				return;
			}
			this._owner.redraw();
		}

		protected _getItemByElement(element: HTMLElement): MenuItem {
			let item: MenuItem = null;
			let id: string = element.getAttribute("data-itemid");
			if (id != null) {
				item = this._binder.getDataProvider().getByValue(id) as MenuItem;
			}
			return item;
		}

		protected _onItemSelect(item: MenuItem, e: UIEvent, done?: (success: boolean) => void): boolean {
			if (item == null || !this._owner.getItemEnable(item) || this._owner.readOnly) {
				return true;
			}
			let result = this._binder._select(item, this._binder.getMultiple());

			if (done) {
				core.DeferredUpdateManager.INSTANCE.asyncExec(() => {
					if (this.disposed) {
						return;
					}
					let itemClickEvent = new cpr.events.CItemEvent(events.ItemEventType.ITEMCLICK, {
						item: item
					});
					let nEvent = e;
					if (e.type == "keydown") {
						nEvent = new events.CMouseEvent("click");
					}
					itemClickEvent.nativeEvent = nEvent;
					this._dispatchEvent(itemClickEvent);
					if (this.disposed) {
						return;
					}
					done(result);
				});
			}
			return result;
		}
		/**
		 * 일반 메뉴에서 키 바인드
		 * @param e 
		 */
		protected _navigateBar(e: events.CKeyboardEvent, item: MenuItem) {
			let keyCode = e.keyCode;
			switch (keyCode) {

				default: {
					let findItem = this._findItemByAccessKey(e.key);
					if (findItem == null) {
						return;
					}
					this._onAccessKey(findItem, e);
				}
			}

		}

		protected abstract _onAccessKey(item: MenuItem, e: events.CKeyboardEvent);

		/**
		 * 컨트롤에 포커스를 지정합니다.
		 */
		public abstract focus(forward: boolean): boolean;

		/**
		 * 컨트롤의 포함하는 객체들을 제거합니다.
		 */
		public dispose(): void {
			this._clearMenu();

			if (this._binder) {
				this._binder = null;
			}
			if (this._mouseLeaveTimer) {
				this._mouseLeaveTimer.dispose();
				this._mouseLeaveTimer = null;
			}
			if (this._focusItemTimer) {
				this._focusItemTimer.dispose();
				this._focusItemTimer = null;
			}
			this._rootItems = null;
			this._hoveredItem = null;
			this._beforeMouseoverItem = null;
			this._owner = null;

		}

		private _dispatchEvent(e: events.CEvent) {
			if (!this._owner) {
				return;
			}
			return this._owner.dispatchEvent(e);
		}

		public get disposed(): boolean {
			return this._owner ? this._owner.disposed : true;
		}
	}
}