namespace cpr.bind {
	/**
	 * @nonapi
	 */
	export interface SetterGuard {
		/** 
		 * setter로 전달된 값을 벨리데이트 하는 함수, <code>null</code> 리턴시 valid한 값임을 나타냄. 그 외의 경우 에러 메시지를 리턴 함.
		 */
		validator?: (value: any) => string
		transformer?: (value: any) => any

		/**
		 * setter의 값이 잘못되었을 경우, 크리티컬하게 취급할 것인지의 여부. false라면, setter의 값을 단순히 무시함. 그 외의 경우, 익셉션을 일으킴.
		 */
		isStrong?: boolean
	}

	/**
	 * 바인딩 유형
	 */
	export enum BindType {
		EXPRESSION = "expression",
		DATAMAP = "datamap",
		DATASET = "dataset",
		DATACOLUMN = "datacolumn",
		APP_PROPERTY = "appproperty",
		LANGUAGE = "language"
	}

	/**
	 * 바인딩된 정보를 담고 있는 객체입니다.
	 */
	export interface BindInfo {
		/**
		 * 바인딩의 유형. 다음 중 하나의 값입니다.<br>
		 * expression, datamap, dataset, datacolumn, appproperty, language
		 */
		type: BindType

		/**
		 * 데이터 맵 또는 데이터 셋 바인딩인 경우, 해당 데이터 컨트롤의 ID 입니다.
		 */
		srcId?: string;

		/**
		 * 데이터 셋 바인딩인 경우, 행 인덱스를 가리킵니다.
		 */
		rowIndex?: number;

		/**
		 * 데이터 셋, 데이터 맵, 데이터 컬럼 바인딩인 경우, 컬럼 이름을 가리킵니다.
		 */
		columnName?: string;

		/**
		 * 언어 바인딩인 경우, 언어 키 패스를 가리킵니다.
		 */
		keyPath?: string;

		/**
		 * 익스프레션 바인딩인 경우, 표현식을 나타냅니다.
		 */
		expression?: string;

		/**
		 * 앱 속성 바인딩인 경우, 앱 속성명을 가리킵니다.
		 */
		property?: string;
	}

	/**
	 * 하나의 바인딩 가능한 속성을 추상화 하는 개체입니다.
	 * 
	 * @nonapi
	 */
	export class BindableProperty {
		private _parent: BindableProperties;
		private _name: string;
		private _defaultDelegate: SimpleDelegate;
		private _delegate: PropertyDelegate;

		private _setterGuard: SetterGuard;
		private _getterGuard: (newValue: any) => any;

		/** 현재 값을 얻고 있는 중인지를 나타내는 플래그 */
		private _getting: boolean = false;

		constructor(parent: BindableProperties, name: string, initialValue: any) {
			this._parent = parent;
			this._name = name;
			this._defaultDelegate = new SimpleDelegate(initialValue);
		}

		public get name(): string {
			return this._name;
		}

		/**
		 * 활성 속성 델리게이트를 얻습니다. 실질적인 get/set을 처리하게 될 객체입니다.
		 */
		private getActiveDelegate(): PropertyDelegate {
			if (this._delegate && this._delegate.isActive()) {
				return this._delegate;
			}
			else {
				return this._defaultDelegate;
			}
		}

		public getDelegate(): PropertyDelegate {
			return this._delegate;
		}

		/**
		 * 속성의 값을 얻습니다.
		 * @return string|number|object 속성에 지정된 값
		 */
		public get(): any {
			let result: any = null;
			try {
				if (this._getting) {
					if (this._parent && this._parent.owner instanceof controls.Control) {
						console.error(`${this._parent.owner._getDebugIdentifier()}@${this._name} 속성을 계산 하는 동안 재귀 호출이 발생했습니다.`);
					} else {
						console.error(`${this._name} 속성을 계산하는 동안 재귀 호출이 발생했습니다.`);
					}
					result = expression.ERROR_VALUE;
				}
				else {
					this._getting = true;
					result = this.getActiveDelegate().get();
				}
			} finally {
				this._getting = false;
			}

			if (this._getterGuard) {
				return this._getterGuard(result);
			} else {
				return result;
			}
		}

		/**
		 * 속성의 값을 지정합니다.
		 * @param newValue 새로운 값.
		 */
		public set(newValue: any): void {
			if (this._setterGuard && this._setterGuard.transformer) {
				newValue = this._setterGuard.transformer(newValue);
			}

			if (this._setterGuard && this._setterGuard.validator) {
				let status = this._setterGuard.validator(newValue);
				if (status != null) {
					if (this._setterGuard.isStrong) {
						throw new cpr.exceptions.IllegalArgumentException(status);
					} else {
						return;
					}
				}
			}
			this.getActiveDelegate().set(newValue);
		}

		/**
		 * 속성 델리게이트를 추가합니다.
		 * 
		 * @param delegate 속성 접근 델리게이트 구현.
		 */
		public setDelegate(delegate: PropertyDelegate): void {
			let oldValue = this.get();

			let oldInfo = this._delegate?.getBindInfo();
			this._delegate?.dispose();

			this._delegate = delegate;
			let newValue = this.get();

			// 바인딩 변경 정보 디스패치.
			if (this._parent?.owner?._bindDidChange) {
				this._parent.owner._bindDidChange(this._name, oldInfo, this._delegate.getBindInfo());
			}

			// 값 변경 정보 디스패치
			if (this._parent?.owner?._valueDidChange && oldValue != newValue) {
				this._parent.owner._valueDidChange(this._name, oldValue, newValue);
			}
		}

		/**
		 * 델리게이트를 제거합니다.
		 */
		public removeDelegate(): void {
			if (!this._delegate) {
				return;
			}
			let oldInfo = this.getCurrentBindInfo();
			let oldValue = this.get();

			this._delegate.dispose();
			delete this._delegate;

			if (this._parent?.owner?._bindDidChange) {
				this._parent.owner._bindDidChange(this._name, oldInfo, null);
			}

			// 값 변경 정보 디스패치
			if (this._parent?.owner?._valueDidChange) {
				let newValue = this.get();
				if (oldValue != newValue) {
					this._parent.owner._valueDidChange(this._name, oldValue, newValue);
				}
			}
		}

		/**
		 * 세터 함수의 오동작을 방지할 가드를 지정합니다.
		 * @param guard 세터 함수의 오동작을 방지할 가드
		 */
		public setSetterGuard(guard: SetterGuard): void {
			this._setterGuard = guard;
		}

		/**
		 * 
		 * @param guard 게터 값을 변환할 기회를 갖는 가드 함수.
		 */
		public setGetterGuard(guard: (newValue: any) => any): void {
			this._getterGuard = guard;
		}

		/**
		 * 게터 값을 변환할 기회를 갖는 가드 함수를 얻습니다.
		 */
		public getGetterGuard() {
			return this._getterGuard;
		}

		/**
		 * 세터 함수의 오동작을 방지할 가드를 얻습니다.
		 */
		public getSetterGuard() {
			return this._setterGuard;
		}

		/**
		 * 현재 지정된 델리게이트로부터 바인딩 정보를 얻습니다.
		 */
		public getCurrentBindInfo(): BindInfo {
			let delegate = this.getDelegate();
			return delegate ? delegate.getBindInfo() : null;
		}

		public _isAvailable(): boolean {
			let delegate = this.getActiveDelegate();
			if (delegate) {
				return delegate._isAvailable();
			}
			return false;
		}

		/**
		 * 델리게이트를 디스포즈 합니다.
		 */
		public dispose(): void {
			this._delegate?.dispose();
			delete this._delegate;
		}
	}
}