namespace cpr.controls {
	/**
	 * 마우스 또는 터치등의 포인팅 디바이스의 위치를 나타냅니다.
	 */
	export class PointerLocation {
		private _pageLocation: geometry.Point
		private _clientLocation: geometry.Point

		/**
		 * 다른 포인터 로케이션을 이용하여 사본을 만듭니다.
		 * @param original 원본 포인터 로케이션.
		 */
		constructor(original: PointerLocation);

		/**
		 * UI이벤트로 부터 포인터 로케이션 객체를 만듭니다.
		 * @param event 마우스 이벤트 혹은 터치 이벤트.
		 */
		constructor(event: UIEvent);

		constructor(touch: Touch);

		/**
		 * UI이벤트로 부터 포인터 로케이션 객체를 만듭니다.
		 * @param event 마우스 이벤트 혹은 터치 이벤트.
		 */
		constructor(event: events.CUIEvent);

		constructor(clientLocation: geometry.Point, pageLocation: geometry.Point);

		constructor() {
			let args = _toArray(arguments);
			switch (args.length) {
				case 1: {
					let source = args[0];

					if (source instanceof UIEvent || source instanceof events.CUIEvent) {
						this._pageLocation = geometry.Point.fromEvent(source, geometry.LocationCooridnate.page);
						this._clientLocation = geometry.Point.fromEvent(source, geometry.LocationCooridnate.client);
					}

					else if (source instanceof PointerLocation) {
						this._pageLocation = source._pageLocation.getCopy();
						this._clientLocation = source._clientLocation.getCopy();
					}
					else {
						throw new exceptions.IllegalArgumentException();
					}
					break;
				}
				case 2: {
					if (args[0] instanceof geometry.Point && args[1] instanceof geometry.Point) {
						this._clientLocation = args[0];
						this._pageLocation = args[1];
					} else {
						throw new exceptions.IllegalArgumentException();
					}
					break;
				}

				default: {
					throw new exceptions.IllegalArgumentException();
				}
			}
		}

		/**
		 * 사본을 얻습니다.
		 */
		public getCopy(): PointerLocation {
			return new PointerLocation(this);
		}

		/**
		 * 클라이언트 뷰 포트상의 좌표를 얻습니다.
		 */
		public get clientLocation(): geometry.Point { return this._clientLocation; }

		/**
		 * 페이지 좌표계 상의 좌표를 얻습니다.
		 */
		public get pageLocation(): geometry.Point { return this._pageLocation; }

		/**
		 * 동일성을 검사합니다.
		 * @param obj 비교할 다른 포인터 로케이션.
		 */
		public equals(obj: any): boolean {
			if (obj instanceof PointerLocation) {
				return this._pageLocation.equals(obj._pageLocation) && this._clientLocation.equals(obj._clientLocation);
			} else {
				return false;
			}
		}
	}
}