		private static readonly _AVAILABLE_PROP: string[] = [
			"maxNotifyCount", "scope",
			"delay", "icon", "animation", "close",
			"successDelay", "successIcon", "successAnimation", "successClose",
			"infoDelay", "infoIcon", "infoAnimation", "infoClose",
			"warningDelay", "warningIcon", "warningAnimation", "warningClose",
			"dangerDelay", "dangerIcon", "dangerAnimation", "dangerClose"];

		/**
		 * 컨트롤 노출 여부를 감시하는 주기(ms).
		 * setInterval에 delay를 지정하지 않으면 ~4ms로 클램프되어 조상 체인 순회가 초당 수백 회 발생한다.
		 * https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/11129
		 */
		private static readonly _SHOWING_WATCH_INTERVAL: number = 200;

		private _contents: Content[] = [];
		private _keyindex: number = 0;
		private _notifierBounds = { x: 0, y: 0, w: "", h: "" };
		private _beforeShowing: boolean;
		/** 노출 여부 감시 타이머. content 단위가 아닌 컨트롤 단위로 하나만 운용한다. */
		private _showingTimer: number = null;
		private _restoreFocusControl: UIControl;

		/* 사용자 Properties */
		private _maxNotifyCount: number = 5;
		private _scope: NotifierScope = NotifierScope.SYSTEM;

		private _notifiers: {
			type: NotifierType,
			info: NotifierInfo
		}[] = [];

		constructor(id?: string) {
			super(id);
			this._init();
			this._initBindableProperty();

			// control initializing
			this._initControl();
		}

		override _getType(): ControlType {
			return ControlType.NOTIFIER;
		}

		private _init() {
			let notifierTypes: NotifierType[] = [NotifierType.default, NotifierType.success, NotifierType.info, NotifierType.warning, NotifierType.danger];
			notifierTypes.forEach((notifierType: NotifierType) => {
				this._notifiers.push({
					type: notifierType,
					info: {
						delay: 5000,
						animation: "fadein",
						close: false
					}
				});
			})
		}

		private _initBindableProperty(): void {
			this._addBindableProperty("icon", null).withSetterValidatorWithType(false, "string");
			this._addBindableProperty("successIcon", null).withSetterValidatorWithType(false, "string");
			this._addBindableProperty("infoIcon", null).withSetterValidatorWithType(false, "string");
			this._addBindableProperty("warningIcon", null).withSetterValidatorWithType(false, "string");
			this._addBindableProperty("dangerIcon", null).withSetterValidatorWithType(false, "string");
		}

		protected _getStylerSpec(): UIControlStylerSpec {
			return {
				root: { baseClass: "cl-notifier" },
				item: { baseClass: "cl-notifier-item" }
			};
		}

		protected _isConfigurableProperty(propName: string): boolean {
			if (Notifier._AVAILABLE_PROP.indexOf(propName) != -1) {
				return true;
			}
			return super._isConfigurableProperty(propName);
		}

