

namespace cpr.data.tabledata {

	/**
	 * @private
	 */
	export class RowData {
		// private _parent: (DataTable | DataMap);
		/*
		 * [x : original_data], [x + 1 : current_data]
		 */
		private _datas: any[];

		private _cellCnt: number;

		private _attr: { [attrName: string]: string };
		private _controlAttr: { [controlUUID: string]: RowCtrlAttr };
		private _state: RowState;

		/**
		 * 행의 아이디. 이 값은 {@link _getRowId()}가 트리거될 때 확정 됩니다.
		 */
		private _rowId: string;

		/**
		 * 부모행에 대한 다차원 배열체를 구성하는 한 행인 경우, 부모행을 가리키는 식별자.
		 */
		private _category: string;

		constructor() { //(parent: (DataTable | DataMap)) {
			// this._parent = parent;

			this._datas = [];
			this._cellCnt = 0;

			this._state = RowState.UNCHANGED;
		}

		get state(): RowState {
			return this._state;
		}

		/**
		 * RowData 상태 변경시에는 DataUtil._setState()를 사용하시기 바랍니다.
		 */
		set state(state: RowState) {
			this._state = state;
		}

		/**
		 * @return number 추가된 columnIndex 반환
		 */
		public _addData(header: header.Header, defaultValue: any = null): number {
			// 초기 세팅되는 행의 경우에만 초기값이 없는 경우 또는 null에 한해서 빈 문자열("")으로 처리됨. (기존 유지)
			// let initValue: any = (defaultValue == null) ? "" : DataUtil._convertValue(header, defaultValue);
			let initValue: any = (defaultValue == null) ? DataUtil._getDefaultValue() : DataUtil._convertValue(header, defaultValue);
			let cellIdx: number = this._cellCnt;

			this._setAllValue(cellIdx, initValue);

			this._cellCnt++;

			return cellIdx;
		}

		public _deleteData(columnIndex: number): void {
			if (columnIndex < 0 || columnIndex >= this._cellCnt) {
				return;
			}
			this._deleteCell(columnIndex);
			this._cellCnt--;
		}

		public setValue(header: header.Header, columnIndex: number, value: any): void {
			let currentValue: any = DataUtil._convertValue(header, value);

			this._setCValue(columnIndex, currentValue, header.getColumnType());
		}

		/**
		 * ※ 원본데이터 수정은 제공하지 않음!!!
		 * 해당 메소드는 DataMap의 commit과 build에서 사용함!!!
		 * => 17.04.14 putValue에서 사용함.
		 */
		public _setOriginalValue(header: header.Header, columnIndex: number, value: any): void {
			let currentValue: any = DataUtil._convertValue(header, value);

			this._setOValue(columnIndex, currentValue);
		}

		public getValue(columnIndex: number): any {
			return this._getCValue(columnIndex);
		}

		public _getOriginalValue(columnIndex: number): any {
			return this._getOValue(columnIndex);
		}

		public _getDecimal(header: header.Header, columnIndex: number): foundation.DecimalType {
			let datatype: DataType = null;
			if (header) {
				datatype = header.getDataType();
			}
			if (datatype == DataType.DECIMAL || datatype == DataType.NUMBER) { // TODO 공통화
				let value: any = this.getValue(columnIndex);
				if (value != null && value !== "" && isNaN(value) == false) {
					return new foundation.DecimalType(value);
				}
				return value;
			}
			return null;
		}

		public _getOriginalDecimal(header: header.Header, columnIndex: number): foundation.DecimalType {
			let datatype: DataType = null;
			if (header) {
				datatype = header.getDataType();
			}
			if (datatype == DataType.DECIMAL || datatype == DataType.NUMBER) { // TODO 공통화
				let value: any = this._getOriginalValue(columnIndex);
				if (value != null && value != "") {
					return new foundation.DecimalType(value);
				}
			}
			return null;
		}

		public _commit(): void {
			// this._setState(RowState.UNCHANGED);

			let columnLength: number = this._cellCnt;
			for (let idx: number = 0; idx < columnLength; idx++) {
				this._CToO(idx);
			}
		}

		public _revert(): void {
			// this._setState(RowState.UNCHANGED);

			let columnLength: number = this._cellCnt;
			for (let idx: number = 0; idx < columnLength; idx++) {
				this._OToC(idx);
			}
		}

		/**
		 * 행 상태 변경에 따른 후처리.
		 * UNCHANGED상태로 변경시 이전 값을 commit과 같이 처리해 주어야 함.
		 * @param beforeState 
		 * @param currentState 
		 */
		public _afterStateChange(beforeState: tabledata.RowState, currentState: tabledata.RowState): void {
			if (beforeState != tabledata.RowState.UNCHANGED &&
				currentState == tabledata.RowState.UNCHANGED) {
				let columnLength: number = this._cellCnt;
				for (let idx: number = 0; idx < columnLength; idx++) {
					this._CToO(idx);
				}
			}
		}

		/**
		 * 현재 row의 상태값을 문자형으로 반환한다.
		 * @return 현재 row의 상태값 문자 
		 */
		public getStateString(): string {
			return DataUtil._getStateString(this._state, false);
		}


		/* Attribute */
		public _getAttr(attrName: string): string {
			if (this._attr) {
				return this._attr[attrName];
			}
			return null;
		}

		public _setAttr(attrName: string, attrValue: string): void {
			if (!this._attr) {
				this._attr = {};
			}
			this._attr[attrName] = attrValue;
		}

		public _getAttrNames(): string[] {
			if (this._attr) {
				return Object.keys(this._attr);
			}
			return [];
		}

		public _getAttrs(): { [attrName: string]: string } {
			if (this._attr) {
				return _shallowCopyObject(this._attr);
			}
			return {};
		}

		/* Control Attribute */
		public _getCtrlAttr(control: controls.Control, attrName: string): any {
			if (this._controlAttr) {
				if (this._controlAttr.hasOwnProperty(control.uuid) == false) {
					return null;
				}
				return this._controlAttr[control.uuid]._getCtrlAttr(attrName);
			}
			return null;
		}

		public _setCtrlAttr(control: controls.Control, attrName: string, attrValue: any): void {
			if (!this._controlAttr) {
				this._controlAttr = {};
			}
			if (this._controlAttr.hasOwnProperty(control.uuid) == false) {
				this._controlAttr[control.uuid] = new RowCtrlAttr();
			}
			this._controlAttr[control.uuid]._setCtrlAttr(attrName, attrValue);
		}

		public _deleteCtrlAttr(control: controls.Control, attrName: string): void {
			if (this._controlAttr) {
				if (this._controlAttr.hasOwnProperty(control.uuid) == false) {
					return;
				}
				this._controlAttr[control.uuid]._deleteCtrlAttr(attrName);
			}
		}

		public _deleteAllCtrlAttr(control: controls.Control): void {
			if (this._controlAttr) {
				if (this._controlAttr.hasOwnProperty(control.uuid) == true) {
					delete this._controlAttr[control.uuid];
				}
			}
		}

		public _getCtrlAttrNames(control: controls.Control): string[] {
			if (this._controlAttr) {
				if (this._controlAttr.hasOwnProperty(control.uuid) == false) {
					return null;
				}
				return this._controlAttr[control.uuid]._getCtrlAttrNames();
			}
			return [];
		}

		public _getCtrlAttrs(control: controls.Control): { [attrName: string]: string } {
			if (this._controlAttr) {
				if (this._controlAttr.hasOwnProperty(control.uuid) == false) {
					return null;
				}
				return this._controlAttr[control.uuid]._getCtrlAttrs();
			}
			return null;
		}

		public _getRowCtrlAttr(control: controls.Control): RowCtrlAttr {
			if (this._controlAttr) {
				return this._controlAttr[control.uuid];
			}
			return null;
		}


		/* Algorithm */
		private _ToRealIdx(colIdx: number): number {
			return colIdx * 2;
		}
		private _deleteCell(colIdx: number): void {
			let realIdx: number = this._ToRealIdx(colIdx);
			this._datas.splice(realIdx, 2);
		}
		private _getOValue(colIdx: number): any {
			let realIdx: number = colIdx * 2;
			return this._datas[realIdx];
		}
		private _getCValue(colIdx: number): any {
			let realIdx: number = colIdx * 2;
			return this._datas[realIdx + 1];
		}
		private _setAllValue(colIdx: number, value: any): void {
			let realIdx: number = this._ToRealIdx(colIdx);
			this._datas[realIdx] = value; // original
			this._datas[realIdx + 1] = value; // current
		}
		private _setOValue(colIdx: number, value: any): void {
			let realIdx: number = this._ToRealIdx(colIdx);
			this._datas[realIdx] = value; // original
		}
		private _setCValue(colIdx: number, value: any, headerType: header.HeaderType): void {
			let realIdx: number = this._ToRealIdx(colIdx);
			this._datas[realIdx + 1] = value; // current
			if (headerType == header.HeaderType.DISPLAY_COLUMN) {
				this._datas[realIdx] = value; // original
			}
		}
		private _OToC(colIdx: number): void {
			let realIdx: number = this._ToRealIdx(colIdx);
			this._datas[realIdx + 1] = this._datas[realIdx];
		}
		private _CToO(colIdx: number): void {
			let realIdx: number = this._ToRealIdx(colIdx);
			this._datas[realIdx] = this._datas[realIdx + 1];
		}

		// Linked DataSet
		public _setRowId(rowId: string): void {
			this._rowId = rowId;
		}

		public _getRowId(): string {
			return this._rowId;
		}

		/**
		 * 부모행 식별자를 지정합니다.
		 * @param category 부모 행의 식별자
		 */
		public _setCategory(category: string): void {
			this._category = category;
		}

		/**
		 * 부모행 식별자를 얻습니다.
		 * @returns 부모행 식별자
		 */
		public _getCategory(): string {
			return this._category;
		}
	}
}