/// <reference path="./AbstractItemList.ts"/>

namespace cpr.controls.item {

	/**
	 * 
	 * @private
	 */
	export class ItemList<ItemType extends Item, ItemSetConfigType extends ItemSetConfig> extends AbstractItemList<ItemType, ItemSetConfigType> implements IItemList<ItemType> {

		private _itemValidatorType: ControlItemValidatorType;
		/**
		 * value, label로 구성된 리스트 형태 데이터 관리자를 생성합니다.
		 * @param owner 다중 선택을 할 수 있는 value를 가진 컨트롤
		 */
		constructor(owner: any, itemDataSource: ItemDataSource<ItemSetConfigType>, itemadapter: ItemListAdapter<ItemType>) {
			super(owner, itemDataSource, itemadapter);
			this._itemValidatorType = ControlItemValidatorType.item;
		}

		public setValidatorType(validatorType: ControlItemValidatorType): void {
			this._itemValidatorType = validatorType;
		}

		protected _getValidator(): IControlItemValidator<ItemType> {
			switch (this._itemValidatorType) {
				case ControlItemValidatorType.item:
					return new ControlItemValidator<ItemType>();
				case ControlItemValidatorType.treeItem:
					return new ControlTreeItemValidator() as unknown as IControlItemValidator<ItemType>;
				case ControlItemValidatorType.comboBoxItem:
					return new ComboBoxItemValidator() as unknown as IControlItemValidator<ItemType>;
				default:
					return new ControlItemValidator<ItemType>();
			}
		}

		/**
		 * 아이템을 데이터셋에 추가합니다.
		 * @param item 
		 * @returns 
		 */
		public addRowItem(item: ItemType) {
			if (!this.dataSet) {
				return;
			}
			let row = this.dataSet.addRow();
			this._updateRow(item, row);
		}

		/**
		 * 리스트 데이터의 개수를 반환합니다.
		 * @return 데이터의 개수.
		 */
		public size(): number {
			return this.predefinedItems.length + (this.dataSet ? this.dataSet.getRowStatedCount(this.visibleRowState) : 0);
		}

		/**
		 * Index에 해당되는 데이터를 반환합니다.
		 * @param index 데이터의 index.
		 * @return 해당하는 아이템.
		 */
		public get(index: number): ItemType {
			if (index < 0) {
				return null;
			}

			let item = this.findOne((item: ItemType, itemIndex: number) => {
				// 문자열 숫자로 설정하는 경우도 있어 == 사용
				return index == itemIndex;
			});
			return item;
		}

		/**
		 * 캐시된 아이템 목록을 반환합니다.
		 * getItems()와 동일하지만, 캐시를 사용하여 성능을 향상시킵니다.
		 * @returns 
		 */
		@useCacheRealm("redraw")
		public getCacheItems(): ItemType[] {
			return this.getItems();
		}

		/**
		 * 필터 속성이 반영되지 않은 아이템 목록을 반환합니다.
		 * @returns 
		 */
		public getItems(): ItemType[] {
			let items: ItemType[] = this.predefinedItems.slice(0);
			if (this.dataSet != null) {
				let rowIndices: number[] = this.dataSet.getRowStatedIndices(this.visibleRowState);
				rowIndices.forEach((rowIndex: number) => {
					let row: data.IDataRow = this.dataSet.getRow(rowIndex);
					let item: ItemType = this._convertRowToItem(row);
					items[items.length] = item;
				});
			}

			return items;
		}
		/**
		 * 아이템의 활성화 상태를 설정합니다.
		 * @param item 설정할 아이템
		 * @param enabled 활성화 여부
		 */
		public setItemEnable(item: ItemType, enabled: boolean) {
			if (!this._checkItem(item)) {
				return;
			}
			this.setItemAttribute(item, ItemDataSetCtrlProperty.enabled, enabled);
			this.owner.redraw();
		}

		/**
		 * 아이템에 속성을 지정합니다.
		 * @param item 
		 * @param key 
		 * @param value 
		 */
		public setItemAttribute(item: ItemType, key: string, value: any): boolean {
			let success = false;
			if (!item.row) {
				success = this.predefinedItems.some((each: ItemType) => {//선행 데이터 체크 저장
					if (each._equalsUUID(item)) {
						this._setPredefinedItemProperty(each, key, value);
						return true;
					}
					return false;
				});
			} else {
				if (this.dataSet != null) {
					let row: data.IDataRow = item.row._getDataSet() === this.dataSet ? item.row : this.dataSet.findFirstRow(`${this.itemSetConfig.value} == ${JSON.stringify(item.value)}`);
					if (this.itemSetConfig[key] && row) { //데이터셋에 체크 저장
						row.setValue(this.itemSetConfig[key], value.toString());
						success = true;
					} else if (row) {
						this.dataSet._setCtrlAttr(this.owner, row.getIndex(), key, value);
						success = true;
					}
				}
			}

			return success;
		}

		/**
		 * 아이템에 지정된 속성을 가져옵니다.
		 * @param item 
		 * @param key 
		 */
		public getItemAttribute(item: ItemType, key: string): any {
			let result = null;
			if (!item.row) {
				this.predefinedItems.some((each: ItemType) => {//선행 데이터 체크 저장
					if (each._equalsUUID(item)) {
						result = this._getPredefinedItemProperty(each, key);
						return true;
					}
					return false;
				});
			} else {
				if (this.dataSet != null) {
					let row: data.IDataRow = this.dataSet === item.row._getDataSet() ? item.row : this.dataSet.findFirstRow(`${this.itemSetConfig.value} == ${JSON.stringify(item.value)}`);
					if (this.itemSetConfig[key] && row) { //데이터셋에 체크 저장
						result = row.getValue(this.itemSetConfig[key]);
					} else if (row) {
						result = this.dataSet._getCtrlAttr(this.owner, row.getIndex(), key);
					}
				}
			}

			return result;
		}

		public findOne(findFunc: (it: ItemType, idx?: number) => boolean): ItemType {
			let result: ItemType = null;

			let index: number;
			for (index = 0; index < this.predefinedItems.length; index++) {
				let item: ItemType = this.predefinedItems[index];
				if (findFunc(item, index) == true) {
					return item;
				}
			}

			if (this.dataSet != null) {
				let rowIndices: number[] = this.dataSet.getRowStatedIndices(this.visibleRowState);
				// rowIndex는 데이터셋의 물리 행 인덱스이므로 아이템의 순번(order)으로 인덱스를 계산해야 한다.
				rowIndices.some((rowIndex: number, order: number) => {
					let row: data.IDataRow = this.dataSet.getRow(rowIndex);
					let item: ItemType = this._convertRowToItem(row);
					if (findFunc(item, index + order) == true) {
						result = item;
						return true;
					}
					return false;
				});
			}
			return result;
		}

		public find(findFunc: (it: ItemType, idx?: number) => boolean): ItemType[] {
			let result: ItemType[] = [];
			let index: number;
			for (index = 0; index < this.predefinedItems.length; index++) {
				let item: ItemType = this.predefinedItems[index];
				if (findFunc(item, index) == true) {
					result[result.length] = item;
				}
			}
			if (this.dataSet != null) {
				let rowIndices: number[] = this.dataSet.getRowStatedIndices(this.visibleRowState);
				// findOne과 동일하게 물리 행 인덱스가 아닌 아이템의 순번(order)을 사용한다.
				rowIndices.forEach((rowIndex: number, order: number) => {
					let row: data.IDataRow = this.dataSet.getRow(rowIndex);
					let item: ItemType = this._convertRowToItem(row);
					if (findFunc(item, index + order) == true) {
						result[result.length] = item;
					}
				});
			}
			return result;
		}

		/**
		 * 해당 리스트 데이터를 가지고 있는지에 대한 여부를 반환합니다.
		 * @param item 확인할 리스트 데이터.
		 * @return 리스트 데이터를 가지고 있는지에 대한 여부.
		 */
		public has(item: ItemType): boolean {
			let result = this.findOne((it: ItemType) => {
				return it._equalsUUID(item);
			});
			return result != null;
		}

		/**
		 * 아이템을 기준 아이템의 앞 또는 뒤에 삽입합니다.
		 * @param item 삽입할 아이템
		 * @param offset 기준 아이템
		 * @param after true면 뒤에, false면 앞에 삽입
		 */
		private _insert(item: ItemType, offset: ItemType, after: boolean): void {
			//이미 존재하는 아이템이면 삽입하지 않음
			let items = this.getItems();
			let map: CMap<string, ItemType> = _stream(items).toMap((each) => each._getUUID());
			if (map.has(item._getUUID())) {
				return;
			}

			let idx: number = -1;
			this.predefinedItems.some((each: ItemType, index: number) => {
				if (each._equalsUUID(offset)) {
					idx = index;
					return true;
				}
				return false;
			});

			if (idx == -1) {
				let rowIndices: number[] = this.dataSet.getRowStatedIndices(this.visibleRowState);
				let updated: boolean = rowIndices.some((rowIndex: number) => {
					let row: data.IDataRow = this.dataSet.getRow(rowIndex);
					let dataSetItem: ItemType = this._convertRowToItem(row);
					if (offset._equalsUUID(dataSetItem)) {
						let newRow: data.IDataRow = this.dataSet.insertRow(rowIndex, after);
						this._updateRow(item, newRow);
						return true;
					}
					return false;
				});
				if (updated == false) {
					throw new cpr.exceptions.IllegalStateException();
				}
			} else {
				this.predefinedItems.splice(idx + (after ? 1 : 0), 0, item);
			}
		}

		/**
		 * 기준되는 아이템 전에 해당 아이템을 삽입합니다.
		 * @param item 삽입하고자 하는 아이템.
		 * @param offset 기준되는 아이템.
		 */
		public insertBefore(item: ItemType, offset: ItemType): void {
			this._insert(item, offset, false);
			this.owner.redraw();
		}

		/**
		 * 기준되는 아이템 후에 해당 아이템을 삽입합니다.
		 * @param item 삽입하고자 하는 아이템.
		 * @param offset 기준되는 아이템.
		 */
		public insertAfter(item: ItemType, offset: ItemType): void {
			this._insert(item, offset, true);
			this.owner.redraw();
		}

		/**
		 * 선행 데이터를 설정합니다.
		 * @param items 설정할 리스트 데이터 배열
		 */
		public setPredefinedItems(items: ItemType[]): void {
			if (items == null) {
				return;
			}

			this._setPredefinedItems(items);
			this.owner.redraw();
		}

		/**
		 * value에 해당하는 리스트 데이터를 반환합니다.
		 * @param value 가져오고자 하는 리스트 데이터의 value.
		 * @param useFilter 필터 적용 여부
		 * @return 해당하는 리스트 데이터.
		 */
		public getByValue(value: string): ItemType {
			let result = this.findOne((it: ItemType) => {
				return it.value == value;
			});
			return result;
		}

		/**
		 * 아이템의 value로 데이터셋의 인덱스를 반환합니다. 
		 * @param value 
		 */
		public getDataSetIndexByValue(value: string): number {
			let result = -1;
			if (this.dataSet != null) {
				let rowIndices: number[] = this.dataSet.getRowStatedIndices(this.visibleRowState);
				rowIndices.some((rowIndex: number) => {
					let row: data.IDataRow = this.dataSet.getRow(rowIndex);
					if (row.getValue(this.itemSetConfig.value) == value) {
						result = row.getIndex();
						return true;
					}
					return false;
				});
			}
			return result;
		}

		/**
		 * 아이템으로 데이터셋의 인덱스를 반환합니다.
		 * @param item 
		 */
		public getDataSetIndex(item: ItemType): number {
			if (item.row) {
				return item.row.getIndex();
			}
			return -1;
		}

		/**
		 * 아이템을 모두 삭제합니다.
		 */
		public deleteAllItems() {
			this._setPredefinedItems([]);
			if (this.dataSet) {
				let rowIndices: number[] = this.dataSet.getRowStatedIndices(this.visibleRowState);
				rowIndices.forEach((rowIndex: number) => {
					this.dataSet.deleteRow(rowIndex);
				});
			}
		}

		/**
		 * 해당 index의 리스트 데이터를 삭제합니다.
		 * @param item 삭제하고자 하는 리스트 데이터의 item.
		 */
		public deleteItem(item: ItemType): void {
			if (item.row) {
				this.dataSet.deleteRow(item.row.getIndex());
			} else {
				let findIdx = -1;
				this.predefinedItems.some((each: ItemType, eachIdx) => {
					if (each._equalsUUID(item)) {
						findIdx = eachIdx;
						return true;
					}
				});
				this.predefinedItems.splice(findIdx, 1);
			}
		}

		/**
		 * value에 해당하는 리스트 데이터를 삭제합니다.
		 * @param value 삭제하고자 하는 리스트 데이터의 value
		 */
		public deleteItemByValue(value: string): void {
			let item = this.getByValue(value);
			if (item == null) {
				return;
			}
			this.deleteItem(item);
		}

		/**
		 * 해당 index의 리스트 데이터를 수정합니다.
		 * @param idx 수정하고자 하는 리스트 데이터의 index.
		 * @param sourceItem 수정된 리스트 데이터.
		 */
		public update(targetItem: ItemType, sourceItem: ItemType): void {
			if (!targetItem) {
				throw new cpr.exceptions.IllegalArgumentException();
			}
			let success = false;
			this.predefinedItems.some((each: ItemType) => {//선행 데이터 체크 저장
				if (each._equalsValue(targetItem)) {
					this._updateItem(sourceItem, each);
					success = true;
					return true;
				}
				return false;
			});
			if (success) {
				return;
			}

			if (this.itemSetConfig) {//데이터셋에 체크 저장
				let row: data.IDataRow = this.dataSet.findFirstRow(`${this.itemSetConfig.value} == ${JSON.stringify(targetItem.value)}`);
				if (row) {
					this._updateRow(sourceItem, row);
				}
			}
		}

		/**
		 * 리스트 데이터의 소스 아이템을 타겟 아이템으로 이동합니다.
		 * @param targetItem 이동하고자 하는 Item.
		 * @param sourceItem 현재 리스트 데이터의 Item.
		 */
		public moveItem(targetItem: ItemType, sourceItem: ItemType, after: boolean = true): void {
			if ((targetItem == null || sourceItem == null) || sourceItem._equalsValue(targetItem)) {
				throw new exceptions.IllegalArgumentException();
			}

			let itemInfo = { source: { has: false, idx: -1 }, target: { has: false, idx: -1 } };
			this.predefinedItems.forEach((each: ItemType, idx: number) => {
				if (each._equalsValue(sourceItem)) {
					itemInfo.source.has = true;
					itemInfo.source.idx = idx;
				} else if (each._equalsValue(targetItem)) {
					itemInfo.target.has = true;
					itemInfo.target.idx = idx;
				}
			});
			let success = false;
			if (itemInfo.source.has && itemInfo.target.has) {
				if (after && itemInfo.target.idx < itemInfo.source.idx) {
					itemInfo.target.idx += 1;
				} else if (after == false && itemInfo.target.idx > itemInfo.source.idx) {
					itemInfo.target.idx = itemInfo.target.idx - 1 >= 0 ? itemInfo.target.idx - 1 : itemInfo.target.idx;
				}
				let srcItem: ItemType = this.predefinedItems[itemInfo.source.idx];
				this.predefinedItems.splice(itemInfo.source.idx, 1);
				this.predefinedItems.splice(itemInfo.target.idx, 0, srcItem);
				success = true;
			} else if (this.itemSetConfig) {//데이터셋에 체크 저장
				let sourceRow: data.IDataRow = this.dataSet.findFirstRow(`${this.itemSetConfig.value} == ${JSON.stringify(sourceItem.value)}`);
				let targetRow: data.IDataRow = this.dataSet.findFirstRow(`${this.itemSetConfig.value} == ${JSON.stringify(targetItem.value)}`);
				if (sourceRow && targetRow) {
					this.dataSet.moveRowIndex(sourceRow.getIndex(), targetRow.getIndex(), after);
					success = true;
				}
			}
			if (success == false) {
				console.warn("can not cross move Item repository. dataset->predefinedItem or predefinedItem->dataset");
			}
		}

		public dispose() {
			super.dispose();
			this._setPredefinedItems(null);
		}

	}

}