namespace cpr.foundation {

	/**
	 * 데이트인풋의 마스크 포매터
	 * @private
	 */
	export class DateMaskFormat {

		static ALLOW_FORMAT_PATTERN = "(Y{4}|Y{2}|Y)|(M{2}|M)|(D{2}|D)|(H{2}|H)|(d{4}|d{3}|d{2})|(h{2}|h)|(k{2}|k)|(m{2}|m)|(s{2}|s)|a|A|(S{3}|S{2}|S)";
		static SEPARATOR_PATTERN = "[^YMDHdhkmsaAS]";

		private _pattern: string;

		constructor(pattern: string) {
			this._pattern = pattern;
		}

		/**
		 * 새 패턴을 적용합니다.
		 * @param pattern 
		 */
		public applyPattern(pattern: string) {
			this._pattern = pattern;
		}

		/**
		 * moment 객체를 받아 설정된 패턴으로 텍스트를 반환합니다.
		 * @param obj
		 */
		public format(obj: moment.Moment): string;

		/**
		 * Date 객체를 받아 설정된 패턴으로 텍스트를 반환합니다.
		 * @param obj 
		 */
		public format(obj: Date, locale?: string): string;
		public format(obj: any, locale?: string): string {
			if (!obj) {
				return "";
			}

			let result = this._pattern;
			let formats = this._pattern.match(new RegExp(DateMaskFormat.ALLOW_FORMAT_PATTERN, "g")) ?? [];
			let mm: moment.Moment = moment(obj);

			if (mm.isValid() == false) {
				return "";
			}
			if (locale) {
				mm.locale(locale);
			}
			formats.forEach((each: string) => {
				if (/[aA]/.test(each)) {
					result = result.replace(/([^a-zA-Z\d])[aA]/, "$1" + mm.format(each));
					return;
				}
				result = result.replace(each, mm.format(each));
			});

			return result;
		}

		/**
		 * 패턴 형식에 맞는 날짜 텍스트를 해석하여 Date 객체를 반환합니다.
		 * @param text 
		 * @returns 
		 */
		public parse(text: string): Date {
			return moment(text, this._pattern).toDate();
		}

	}
}