		/**
		 * 자동 크기 지원 타입을 얻습니다.
		 * 만일 both를 리턴했다면, css height, width 속성에 auto를 사용할 수 있음을 나타냅니다.
		 */
		public _getAutoSizeAvailability(): layouts.AutoSizeType {
			return layouts.AutoSizeType.none;
		}

		/**
		 * 자동 세로크기를 지원하는지 여부를 얻습니다.
		 * css height 속성으로 "auto"를 사용할 수 있는지를 나타냅니다.
		 */
		public _supportsAutoHeight(): boolean {
			let type = this._getAutoSizeAvailability()
			switch (type) {
				case layouts.AutoSizeType.both:
				case layouts.AutoSizeType.height:
					return true;
				default:
					return false;
			}
		}

		/**
		 * 자동 가로크기를 지원하는지 여부를 얻습니다.
		 * css width 속성으로 "auto"를 사용할 수 있는지를 나타냅니다.
		 */
		public _supportsAutoWidth(): boolean {
			let type = this._getAutoSizeAvailability()
			switch (type) {
				case layouts.AutoSizeType.both:
				case layouts.AutoSizeType.width:
					return true;
				default:
					return false;
			}
		}

		/**
		 * measure-size 이벤트 핸들러를 이용하여, 크기를 계산합니다.
		 * 스스로 계산이 가능한 경우, 이 메서드를 오버라이드 해야 합니다.
		 * 리턴 값이 -1인 경우, 해당 값은 계산할 수 없음을 나타냅니다.
		 */
		public _measureSize(): geometry.Size {
			let event = this._dispatchEventIfNeeded("measure-size", () => {
				event = new events.CMeasureSizeEvent();
				return event;
			});

			if (event instanceof events.CMeasureSizeEvent) {
				return {
					width: event.width,
					height: event.height
				}
			}
			else {
				return {
					width: -1,
					height: -1
				}
			}
		}

		/**
		 * 해당 컨트롤이 앱 인스턴스나, 특정 컨테이너를 통해 플로팅 되어있는지 여부를 반환합니다.
		 */
		public isFloated(): boolean {
			if (!this._parent) {
				return false;
			}

			// 앱 인스턴스를 통해 플로팅 된 경우.
			if (this._parent._isAsideChild(this)) {
				return true;
			}

			// 컨테이너에 플로팅 된 경우.
			let constraint = this._parent.getConstraint(this);
			if (layouts._isManualConstraint(constraint)) {
				return true;
			}

			return false;
		}

		/**
		 * 이 컨트롤이 매뉴얼 컨스트레인트를 가지고 있는 경우(앱이나 컨테이너에 플로팅되어 있는 경우),
		 * 적용중인 위치 및 크기 관련 CSS 속성을 얻습니다.
		 * 플로팅 중이 아니라면 빈 객체가 리턴 됩니다.
		 * 
		 * @returns 위치 및 크기 관련 CSS 속성.
		 */
		private _resolveManualConstraintedPositionalCSSProperties(): { [key: string]: string } {
			if (this.isFloated() == false) {
				return {};
			}
			let parent = this.getParent();
			let resolvePositionalProperties = (constraint: layouts.ManualConstraint) => {
				let positionalProps = ["top", "right", "bottom", "left", "width", "height"];
				let result: { [key: string]: string } = {};
				for (let prop of positionalProps) {
					result[prop] = constraint.styles?.[prop] || this.style.css(prop);
				}
				return result;
			}

			if (parent._isAsideChild(this)) {
				let constraint = parent._getAsideControlConstraint(this);
				return resolvePositionalProperties(constraint);
			} else {
				let constraint = this.getParent().getConstraint(this);
				if (layouts._isManualConstraint(constraint)) {
					return resolvePositionalProperties(constraint)
				} else {
					return {}
				}
			}
		}

		/**
		 * 컨트롤의 컨스트레인트에 지정된 AutoSizeType을 얻습니다.
		 */
		public _getAutoSizingTypeOfConstraint(): layouts.AutoSizeType {
			let parent = this.getParent();
			if (!parent) {
				return layouts.AutoSizeType.none;
			}

			if (parent instanceof TabFolder) {
				if (this === parent.headerControl) {
					return layouts.AutoSizeType.none;
				}
				else {
					return parent._getAutoSizingTypeOfConstraint();
				}
			} else if (parent instanceof Accordion) {
				return parent._getAutoSizingTypeOfConstraint();
			}

			// 플로팅 된 컨트롤인 경우.
			if (this.isFloated()) {
				// 레이아웃 특성에 의해 자동 크기 여부를 확인할 수 없는 경우
				// 매뉴얼 컨스트레인트 및 현재 CSS 특성을 통해 추론 할 수 있도록 위치/크기 속성 세트를 얻어 추론 함.
				if (this._supportsAutoHeight() || this._supportsAutoWidth()) {
					let constraint = this._resolveManualConstraintedPositionalCSSProperties();
					let top = constraint.top || "";
					let right = constraint.right || "";
					let bottom = constraint.bottom || "";
					let left = constraint.left || "";
					let width = constraint.width || "";
					let height = constraint.height || "";

					let hasWidth = isExplictConstant(width);
					if (isExplictConstant(left) && isExplictConstant(right)) {
						hasWidth = true;
					}

					let hasHeight = isExplictConstant(height);
					if (isExplictConstant(top) && isExplictConstant(bottom)) {
						hasHeight = true;
					}

					if (hasWidth && hasHeight) {
						return layouts.AutoSizeType.none;
					}

					else if (!hasWidth && !hasHeight) {
						return layouts.AutoSizeType.both;
					}
					else if (hasWidth) {
						return layouts.AutoSizeType.height;
					}
					else {
						return layouts.AutoSizeType.width;
					}
				} else {
					return layouts.AutoSizeType.none;
				}
			}

			let layout = parent.getLayout();
			if (!layout) {
				return layouts.AutoSizeType.none;
			}

			let constraint = parent.getConstraint(this);
			return layout._getAutoSizeType(constraint)

		}

		/**
		 * 다음 틱에 하위 노드들을 향해, 크기 변경 사실을 통보합니다.
		 * 만약 크기가 변경되지 않았다면, 통보하지 않습니다.
		 */
		public _fireResizeEvent(): void {
			if (this.disposed || this._fireResizeScheduled) {
				return;
			}
			this._fireResizeScheduled = true;

			// 이벤트 버스에서 resize 계산을 위해 돔 크기 계산하는 것 보다 나중에 실행되어야 함.
			core.DeferredUpdateManager.INSTANCE._asyncExecLast(() => {
				this._fireResizeScheduled = false;
				if (this.disposed) {
					return;
				}
				let renderer: ufc.ControlRenderer = this._getRenderer();
				if (renderer) {
					let rootNode: HTMLElement = renderer.getRootNode();
					if (rootNode) {
						events.EventBus.INSTANCE._resize(rootNode);
					}
				}
			});
		}

