		protected _ensureAriaRefRequest() {
			if (!this._ariaRefRequest) {
				this._ariaRefRequest = { idSet: _createSet(), exposed: false };
			}
			return this._ariaRefRequest;
		}

		/**
		 * 오버라이드 해서 컨트롤에 따라 ARIA 참조 요청을 허용할지 여부를 결정합니다.
		 * @param ref 
		 * @returns 
		 */
		protected _allowAriaRefRequest(ref: { [key: string]: any }): boolean {
			if (!ref) {
				return false;
			}
			return true;
		}

		public _requestAriaRef(requestInfo: { uuid: string, message: string }, ref?: { [key: string]: any }): void {
			if (!this._allowAriaRefRequest(ref)) {
				return;
			}
			let ariaRefRequest = this._ensureAriaRefRequest();
			switch (requestInfo.message) {
				case AriaRequestType.EXPOSE_REF:
					ariaRefRequest.idSet.add(requestInfo.uuid);
					break;
				case AriaRequestType.UNEXPOSE_REF:
					ariaRefRequest.idSet.delete(requestInfo.uuid);
					break;
			}
			let prevExposed = ariaRefRequest.exposed;
			let exposed = ariaRefRequest.idSet.size > 0;

			if (prevExposed !== exposed) {
				this.redraw();
			}
			ariaRefRequest.exposed = exposed;
		}

