/// <reference path="../utils/Logger.ts" />
namespace cpr.protocols {
	const _DEFAULT_TARGET_ORIGIN = "default";
	var _DOMAIN_REG: CMap<string, string>;

	function _getDomainReg() {
		if (!_DOMAIN_REG) {
			_DOMAIN_REG = _performWith(_createMap(), map => {
				map.set(_DEFAULT_TARGET_ORIGIN, '\u002a');
			});
		}
		return _DOMAIN_REG;
	}

	function _getDefaultTargetOrigin() {
		return _getDomainReg().get(_DEFAULT_TARGET_ORIGIN);
	}

	let url = new utils.URL(location.href);
	let file = url.pathname.split("/").pop();
	let log = cpr.utils.Logger.forTopic("channel")._createBindedLoggerFunction({
		prefixes: [location.hostname, file],
		updator: fn => log = fn
	});

	/**
	 * @private
	 */
	export enum EPMessageType {
		HANDSHAKE = "handshake",
		TRAVERSE_FOCUS = "traverse-focus",
		CALL_FUNCTION = "call",
		CALL_RESULT = "result",
		CLOSE = "close"
	}

	/**
	 * 페이지 함수의 호출 유형.
	 */
	export enum PageFunctionCallType {
		/**
		 * 페이지가 제공하는 함수의 반환 값이 일반적인 return 구문을 통해 반환되는 경우를 가리킵니다.
		 * 해당 함수가 프로미스를 반환하는 경우에도 이 유형의 호출 형식을 사용하십시오.
		 */
		NORMAL = "normal",

		/**
		 * 페이지가 제공하는 함수의 반환 값이 콜백 함수를 통해 반환되는 경우를 가리킵니다.
		 */
		RESULT_FIRST_CALLBACK = "result-first-callback",

		/**
		 * 페이지가 제공하는 함수의 반환 값이 콜백 함수의 두 번째 호출 인자를 통해 반환되는 경우를 가리킵니다.
		 */
		ERROR_FIRST_CALLBACK = "error-first-callback",
	}

	/**
	 * @private
	 */
	export type EPMHandshake = {
		__type__: EPMessageType.HANDSHAKE
		port: MessagePort
		version: string
	}

	/**
	 * @private
	 */
	export type EPMFocusTraverse = {
		__type__: EPMessageType.TRAVERSE_FOCUS
		forward: boolean;
	}

	/**
	 * @private
	 */
	export type EPMCallFunction = {
		__type__: EPMessageType.CALL_FUNCTION,

		/**
		 * 호출 함수 이름.
		 */
		fnName: string,

		/**
		 * 호출 인자.
		 */
		args?: any[],

		/** 호출 식별자 */
		callId: string,

		/**
		 * 호출 유형.
		 */
		callType: PageFunctionCallType
	}

	/**
	 * @private
	 */
	export type EPMCallResult = {
		__type__: EPMessageType.CALL_RESULT,
		/**
		 * 호출 처리중 발생한 에러
		 */
		error?: any,

		/**
		 * 호출 결과
		 */
		result?: any,

		/**
		 * 호출 식별자
		 */
		callId: string
	}

	export type EPMClose = {
		__type__: EPMessageType.CLOSE
	}

	/**
	 * @private
	 */
	export type EPMessage = EPMCallFunction | EPMCallResult | EPMHandshake | EPMFocusTraverse | EPMClose;

	/**
	 * @private
	 */
	export interface PageChannelOptions {
		/**
		 * 해당 채널 건너편에서 포커스를 전달 해 올 때의 동작을 처리할 핸들러.
		 */
		onFocus?: (forward: boolean) => void

		/**
		 * 원격 호출 함수 공급자.
		 */
		functionProvider?: (name: string) => Function
	}

	interface HandshakeMessageEvent extends MessageEvent {
		data: EPMHandshake
	}

	/**
	 * 팝업 윈도우 또는 임베디드 페이지 사이의 함수 호출을 지원하는 통신 채널.
	 * @noinstance
	 * @experimental
	 */
	export class PageChannel {
		_waitingCalls: {
			callId: string,
			future: utils.Future<any>
		}[] = [];

		_targetWindow: Window;
		_port: utils.Future<MessagePort>;
		_disposed = false;
		_options: PageChannelOptions;
		_closeRequested = false;

		static _isHandshakeMessageEvent(e: MessageEvent): e is HandshakeMessageEvent {
			return e.data?.["__type__"] == EPMessageType.HANDSHAKE;
		}

		/**
		 * 부모 윈도우와 연결하는 페이지 채널을 작성합니다.
		 * 
		 * @param parentWindow 송수신 대상 윈도우.
		 * @param options 채널 옵션.
		 * @returns 페이지 채널.
		 * @private 이 함수는 프라이빗이지만 어댑터에서 호출 할 때 난독화의 영향을 덜 받게 하기 위해 _로 시작하지 않음.
		 */
		public static createUpstreamChannel(parentWindow: Window, options: PageChannelOptions = {}): PageChannel {
			let channel = new MessageChannel();

			// 채널 연결 패킷 전송
			let handshake: protocols.EPMHandshake = {
				__type__: protocols.EPMessageType.HANDSHAKE,
				port: channel.port2,
				version: core.PlatformVersionInfo.getVersion()
			};

			parentWindow.postMessage(handshake, _getDefaultTargetOrigin(), [channel.port2]);
			let result = new PageChannel(parentWindow, channel.port1, options);
			log("호스트에 접속 요청 보냄.")
			return result;
		}

		/**
		 * 다운 스트림 채널을 작성합니다.
		 * @param targetWindow 송수신 대상 윈도우.
		 * @param port 자식 윈도우가 전송해온 메시지 포트 혹은 퓨처.
		 * @param options 채널 옵션.
		 * @returns 페이지 채널.
		 */
		public static _createDownSreamChannel(targetWindow: Window, port: MessagePort | utils.Future<MessagePort>, options: PageChannelOptions = {}) {
			return new PageChannel(targetWindow, port, options);
		}

		private constructor(targetWindow: Window, port: MessagePort | utils.Future<MessagePort>, options: PageChannelOptions = {}) {
			this._targetWindow = targetWindow;
			if (port instanceof MessagePort) {
				this._port = utils.CompletableFuture.createCompletedFuture(port);
			}
			else {
				this._port = port as utils.Future<MessagePort>;
			}
			this._options = options;
			this._port.asPromise().then(port => {
				port.onmessage = this._onMessage.bind(this);
			})
		}

		private _scheduleMessageSending(msg: EPMessage) {
			this._port.asPromise().then(it => {
				log(`메시지 전송`, msg)
				it.postMessage(msg);
			});
		}

		/**
		 * 이 채널을 통해 통신 중인 타겟 윈도우를 얻습니다.
		 */
		public get targetWindow(): Window {
			return this._targetWindow;
		}

		/**
		 * 채널 연결 여부를 얻습니다.
		 * @returns 채널이 연결 여부.
		 */
		public _isConnected(): boolean {
			return this._port.isDone() && !this._port.isCompletedExceptionally() && !this._disposed && !this._closeRequested;
		}

		private _onMessage(e: MessageEvent) {
			let message = e.data as protocols.EPMessage
			log(`메시지 수신`, message);

			switch (message.__type__) {
				case protocols.EPMessageType.TRAVERSE_FOCUS: {
					this._options?.onFocus?.call(window, message.forward);
					break;
				}

				case protocols.EPMessageType.CALL_RESULT:
					this._processCallResult(message);
					break;

				case protocols.EPMessageType.CALL_FUNCTION:
					this._executeRequestedRPC(message);
					break;

				case protocols.EPMessageType.CLOSE: {
					log("채널 종료 메시지를 수신했습니다.")
					this._dispose();
					break;
				}

				default: {
					throw new exceptions.IllegalArgumentException(e.data);
				}
			}
		}

		/**
		 * 채널 건너편에 존재하는 웹 브라우저로 포커스를 위임합니다.
		 * @param forward 포커스 전달 방향.
		 * @private 이 메서드는 PlatformAdapter 및 EmbeddedPage 에서만 사용됩니다.
		 */
		public _sendFocus(forward: boolean): void {
			let message: EPMFocusTraverse = {
				__type__: EPMessageType.TRAVERSE_FOCUS,
				forward: forward
			};
			this._scheduleMessageSending(message);
		}

		/**
		 * 채널을 건너편에 있는 함수를 호출합니다.
		 * @param fnName 함수 이름.
		 * @param args 인자 배열
		 * @param callType 호출 유형.
		 * @returns 호출 결과에 대한 프로미스 객체.
		 */
		public callFunction(fnName: string, args: any[] = [], callType: PageFunctionCallType = PageFunctionCallType.NORMAL): Promise<any> {
			if (this._disposed) {
				return Promise.reject(new exceptions.IllegalStateException("The connection was closed."))
			}

			let future = new utils.CompletableFuture<void>();
			let message: EPMCallFunction = {
				__type__: EPMessageType.CALL_FUNCTION,
				callType: callType,
				fnName: fnName,
				args: args,
				callId: _generateUUID()
			}

			this._waitingCalls.push({
				callId: message.callId,
				future: future
			});

			this._scheduleMessageSending(message);
			return future.asPromise();
		}

		/**
		 * 요청된 함수 이름을 바탕으로 실제 실행될 함수를 얻습니다.
		 * @param fnName 함수 이름.
		 * @returns 실제 실행될 함수.
		 */
		private _resolveRequestedFunction(fnName: string): Function {
			return this._options?.functionProvider?.call(this, fnName) ?? window[fnName];
		}

		/**
		 * 채널을 통해 요청된 함수 호출 요청을 처리하고 결과를 통보합니다.
		 * @param call 호출 요청 명세.
		 * @returns 호출 결과 프로미스.
		 */
		private _executeRequestedRPC(call: EPMCallFunction): void {
			let fn = this._resolveRequestedFunction(call.fnName);

			// 존재하지 않는 함수인 경우.
			if (typeof fn != "function") {
				let response: EPMCallResult = {
					__type__: EPMessageType.CALL_RESULT,
					callId: call.callId,
					error: `The function "${call.fnName} was not found."`,
					result: undefined
				};
				this._scheduleMessageSending(response);
				return;
			}

			// 호출 방식에 따라 프로미스 유형 결정
			let promise = this._promisifyFuncitonCall(fn, call.args, call.callType);

			promise.then(result => {
				let response: EPMCallResult = {
					__type__: EPMessageType.CALL_RESULT,
					callId: call.callId,
					error: null,
					result: result
				};
				this._scheduleMessageSending(response);
			}).catch(err => {
				let response: EPMCallResult = {
					__type__: EPMessageType.CALL_RESULT,
					callId: call.callId,
					error: err,
					result: undefined
				};
				this._scheduleMessageSending(response);
			});
		}

		/**
		 * 함수 호출을 프로미스화 합니다.
		 * @param fn 피호출 함수.
		 * @param args 호출 인자.
		 * @param callType 피호출 함수의 결과가 전달되는 방식.
		 * @returns 함수 호출 결과에 대한 프로미스.
		 */
		private _promisifyFuncitonCall(fn: Function, args: any[], callType: PageFunctionCallType): Promise<any> {
			let copyOfArgs = (args || []).slice();

			switch (callType) {
				case PageFunctionCallType.NORMAL:
					let result = fn.apply(window, copyOfArgs)
					if (result instanceof Promise) {
						return result;
					} else {
						return Promise.resolve(result);
					}

				case PageFunctionCallType.ERROR_FIRST_CALLBACK:
					return new Promise((resolve, reject) => {
						copyOfArgs.push((err: any, result: any) => {
							if (err) {
								reject(err);
							} else {
								resolve(result);
							}
						});
						fn.apply(window, copyOfArgs);
					});


				case PageFunctionCallType.RESULT_FIRST_CALLBACK:
					return new Promise((resolve, reject) => {
						copyOfArgs.push((result: any, err: any) => {
							if (err) {
								reject(err);
							} else {
								resolve(result);
							}
						});
						fn.apply(window, copyOfArgs);
					});
			}
		}

		/**
		 * 이 채널을 통해 요청했던 RPC 호출에 대한 결과가 도착한 경우 이를 처리합니다.
		 * @param result 호출 결과 메시지.
		 */
		private _processCallResult(result: EPMCallResult): void {
			if (this._disposed) {
				return;
			}

			// 호출자 찾음.
			let idx = this._waitingCalls.findIndex(it => it.callId == result.callId);
			if (idx !== -1) {
				let matching = this._waitingCalls.splice(idx, 1)[0];
				if (result.error == null) {
					// 성공 처리
					matching.future.complete(result.result);
				} else {
					// 실패 처리
					matching.future.completeExceptionally(result.error);
				}
			}
		}

		/**
		 * 채널을 닫고 채널 연결 종료 요청을 보냅니다.
		 */
		public close(): void {
			if (this._closeRequested || this._disposed) {
				return;
			}
			this._closeRequested = true;
			this._scheduleMessageSending({
				__type__: EPMessageType.CLOSE
			});
		}


		/**
		 * @returns 채널을 파기합니다.
		 */
		public _dispose(): void {
			if (this._disposed) {
				return;
			}

			this._disposed = true;
			this._waitingCalls = [];
			delete this._port?.["onmessage"];

			log("채널 파기됨.")
		}
	}
}
