

namespace cpr.protocols {
	/**
	 * 서브미션이 전송할 데이터를 행 단위로 가공할 수 있도록,
	 * {@link Submission.setDataRowHandler}로 등록한 핸들러에 전달되는 행 객체입니다.
	 *
	 * DataSet의 행은 {@link DataSetRow}가 전달되며,
	 * <code>handleDataMap</code>을 <code>true</code>로 등록한 경우 DataMap도 같은 인터페이스로 전달됩니다.
	 * 전송 중인 행의 값·상태·컬럼 정보를 조회할 수 있습니다.
	 */
	export interface RowUnit {
		/**
		 * 데이터셋 정보값을 반환합니다.
		 * @return 데이터셋 정보값.
		 * @deprecated {@link getInfo}를 사용하시기 바랍니다.
		 */
		getDataSetInfo(): string;

		/**
		 * 데이터 객체(DataSet, DataMap)의 info 정보를 반환합니다.
		 */
		getInfo(): string;

		/**
		 * 이 행이 속한 데이터 객체(DataSet, DataView, DataMap)를 반환합니다.
		 * 하나의 서브미션에 여러 데이터 객체가 등록된 경우, 전송 중인 행의 출처를 식별하는데 사용합니다.
		 * <pre><code>
		 * submission.setDataRowHandler(function(rowdata) {
		 *   var dataControl = rowdata.getDataControl();
		 *   if (dataControl.id === "dataset1") {
		 *     return { "tableId": "TB_USER" };
		 *   }
		 *   return null;
		 * }, true);
		 * </code></pre>
		 * @return 이 행이 속한 데이터 객체.
		 */
		getDataControl(): cpr.data.DataCollection | cpr.data.DataMap;

		/**
		 * 컬럼명을 배열형식으로 반환합니다.
		 * @param columnType	반환할 컬럼의 HeaderType.<br>
		 * cpr.data.header.HeaderType.ALL(defalut) : 모든 컬럼.<br>
		 * cpr.data.header.HeaderType.ORIGINAL_COLUMN : 원본 값과 현재 값을 따로 관리하고, 해당 컬럼의 값 변경시 행 상태에 영향을 끼칩니다.<br>
		 * cpr.data.header.HeaderType.DISPLAY_COLUMN : 현재 값만 가지고 있고, 해당 컬럼의 값 변경시 행 상태에 영향을 끼치지 않습니다.<br>
		 * @returns 컬럼명 배열.
		 */
		getColumnNames(columnType?: cpr.data.header.HeaderType): string[];

		/**
		 * 입력 받은 컬럼명에 해당하는 컬럼 정보값을 반환합니다.
		 * @param colName 컬럼명.
		 * @return 컬럼 정보값.
		 */
		getColumnInfo(colName: string): string;

		/**
		 * 입력 받은 컬럼명에 해당하는 값을 반환합니다.
		 * @param colName	값을 가져올 column의 columnName
		 * @return 해당 데이터
		 */
		getValue(colName: string): any;

		/**
		 * 입력 받은 컬럼명에 해당되는 원본 데이터를 반환합니다.
		 * @param colName	값을 가져올 column의 columnName
		 * @return 해당 데이터
		 */
		getOriginalValue(colName: string): any;

		/**
		 * 입력 받은 컬럼명에 해당되는 컬럼의 데이터 타입을 반환합니다.
		 * @param colName 데이터 타입을 가져올 컬럼명.
		 * @return 데이터 타입. <br>
		 * 	cpr.data.tabledata.DataType.STRING = "string";<br>
		 * 	cpr.data.tabledata.DataType.NUMBER = "number";<br>
		 * 	cpr.data.tabledata.DataType.DATE = "date";<br>
		 * 	cpr.data.tabledata.DataType.DECIMAL = "decimal";<br>
		 * 	cpr.data.tabledata.DataType.EXPRESSION = "expression";<br>
		 * @readonly
		 */
		getDataType(colName: string): cpr.data.tabledata.DataType;

		/**
		 * 현재 row의 상태값을 반환합니다.
		 * @return 현재 row의 상태값.<br>
		 * state 종류:<br>
		 * cpr.data.tabledata.RowState.UNCHANGED : 변경되지 않은 상태.<br>
		 * cpr.data.tabledata.RowState.INSERTED : 행이 신규로 추가된 상태.<br>
		 * cpr.data.tabledata.RowState.UPDATED : 행이 수정된 상태.<br>
		 * cpr.data.tabledata.RowState.DELETED : 행이 삭제된 상태.<br>
		 * cpr.data.tabledata.RowState.INSERTDELETED : 행이 추가되었다가 삭제된 상태.
		 * @deprecated {@link getStateString}를 사용하시기 바랍니다.
		 */
		getState(): string;

		/**
		 * 현재 row의 상태값을 문자형으로 반환합니다.
		 * @param isAbbreviation 축양형 표현 여부.
		 * @return 현재 row의 상태값 문자.<br>
		 * 	변경되지 않은 상태 : "UC", "UNCHANGED"<br>
		 * 	행이 신규로 추가된 상태 :  "I", "INSERTED"<br>
		 * 	행이 수정된 상태 :  "U", "UPDATED"<br>
		 * 	행이 삭제된 상태 :  "D" , "DELETED"<br>
		 * 	행이 추가되었다가 삭제된 상태 : "ID", "INSERTDELETED"
		 */
		getStateString(isAbbreviation?: boolean): string;

		/**
		 * 현재 row의 특정 속성값을 반환합니다.
		 * @param attrName	가져올 속성명
		 * @return 해당 속성값
		 */
		getAttr(attrName: string): string;
	}

	/**
	 * 데이터셋의 행 정보를 제공하는 클래스입니다.
	 *
	 * {@link Submission.setDataRowHandler}로 핸들러를 등록하면 DataSet 전송 시 행마다 이 객체가 전달됩니다.
	 * 전송 중인 행의 값·상태·컬럼 정보를 조회할 수 있으며, 원본 데이터를 수정하지 않습니다.
	 * <pre><code>
	 * submission.setDataRowHandler(function(rowdata) {
	 *   var additionalData = {};
	 *   additionalData['param'] = rowdata.getValue("columnName");
	 *   return additionalData;
	 * });
	 * </code></pre>
	 */
	export class DataSetRow implements RowUnit {
		private _dataColl: data.DataSet;
		private _rowData: data.tabledata.RowData;
		private _colNmMap: { [key: string]: number };


		constructor(dataColl: data.DataSet, rowData: data.tabledata.RowData, colNmMap: { [key: string]: number }) {
			this._dataColl = dataColl;
			this._rowData = rowData;
			this._colNmMap = colNmMap;
		}

		/**
		 * 데이터셋 정보값을 반환합니다.
		 * @return 데이터셋 정보값.
		 * @deprecated {@link getInfo}를 사용하시기 바랍니다.
		 */
		public getDataSetInfo(): string {
			return this.getInfo();
		}

		/**
		 * 데이터 객체(DataSet, DataMap)의 info 정보를 반환합니다.
		 */
		public getInfo(): string {
			return this._dataColl.info;
		}

		/**
		 * 이 행이 속한 데이터 객체(DataSet, DataView)를 반환합니다.
		 * 하나의 서브미션에 여러 데이터 객체가 등록된 경우, 전송 중인 행의 출처를 식별하는데 사용합니다.
		 * <pre><code>
		 * submission.setDataRowHandler(function(rowdata) {
		 *   var dataControl = rowdata.getDataControl();
		 *   if (dataControl.id === "dataset1") {
		 *     return { "tableId": "TB_USER" };
		 *   }
		 *   return null;
		 * }, true);
		 * </code></pre>
		 * @return 이 행이 속한 데이터 객체.
		 */
		public getDataControl(): data.DataCollection {
			return this._dataColl;
		}

		/**
		 * 컬럼명을 배열형식으로 반환합니다.
		 * @param columnType	반환할 컬럼의 HeaderType.<br>
		 * cpr.data.header.HeaderType.ALL(defalut) : 모든 컬럼.<br>
		 * cpr.data.header.HeaderType.ORIGINAL_COLUMN : 원본 값과 현재 값을 따로 관리하고, 해당 컬럼의 값 변경시 행 상태에 영향을 끼칩니다.<br>
		 * cpr.data.header.HeaderType.DISPLAY_COLUMN : 현재 값만 가지고 있고, 해당 컬럼의 값 변경시 행 상태에 영향을 끼치지 않습니다.<br>
		 * @returns 컬럼명 배열.
		 */
		public getColumnNames(columnType: data.header.HeaderType = data.header.HeaderType.ALL): string[] {
			return this._dataColl.getColumnNames(columnType);
		}

		/**
		 * 입력 받은 컬럼명에 해당하는 컬럼 정보값을 반환합니다.
		 * @param colName 컬럼명.
		 * @return 컬럼 정보값.
		 */
		public getColumnInfo(colName: string): string {
			let headerInfo: string = null;
			let header: data.header.Header = this._dataColl.getHeader(colName);
			if (header) {
				headerInfo = header.getInfo();
			}
			return headerInfo;
		}

		/**
		 * 입력 받은 컬럼명에 해당하는 값을 반환합니다.
		 * @param colName	값을 가져올 column의 columnName
		 * @return 해당 데이터
		 */
		public getValue(colName: string): any {
			let colIdx: number = this._colNmMap[colName];
			if (colIdx >= 0) {
				return this._rowData.getValue(colIdx);
			}
			return null;
		}

		/**
		 * 입력 받은 컬럼명에 해당되는 원본 데이터를 반환합니다.
		 * @param colName	값을 가져올 column의 columnName
		 * @return 해당 데이터
		 */
		public getOriginalValue(colName: string): any {
			let colIdx: number = this._colNmMap[colName];
			if (colIdx >= 0) {
				return this._rowData._getOriginalValue(colIdx);
			}
			return null;
		}

		/**
		 * 입력 받은 컬럼명에 해당되는 컬럼의 데이터 타입을 반환합니다.
		 * @param colName 데이터 타입을 가져올 컬럼명.
		 * @return 데이터 타입. <br>
		 * 	cpr.data.tabledata.DataType.STRING = "string";<br>
		 * 	cpr.data.tabledata.DataType.NUMBER = "number";<br>
		 * 	cpr.data.tabledata.DataType.DATE = "date";<br>
		 * 	cpr.data.tabledata.DataType.DECIMAL = "decimal";<br>
		 * 	cpr.data.tabledata.DataType.EXPRESSION = "expression";<br>
		 * @readonly
		 */
		public getDataType(colName: string): data.tabledata.DataType {
			let dataType: data.tabledata.DataType = null;
			let header: data.header.Header = this._dataColl.getHeader(colName);
			if (header) {
				dataType = header.getDataType();
			}
			return dataType;
		}

		/**
		 * 현재 row의 상태값을 반환합니다.
		 * @return 현재 row의 상태값.<br>
		 * state 종류:<br>
		 * cpr.data.tabledata.RowState.UNCHANGED : 변경되지 않은 상태.<br>
		 * cpr.data.tabledata.RowState.INSERTED : 행이 신규로 추가된 상태.<br>
		 * cpr.data.tabledata.RowState.UPDATED : 행이 수정된 상태.<br>
		 * cpr.data.tabledata.RowState.DELETED : 행이 삭제된 상태.<br>
		 * cpr.data.tabledata.RowState.INSERTDELETED : 행이 추가되었다가 삭제된 상태.
		 * @deprecated {@link getStateString}를 사용하시기 바랍니다.
		 */
		public getState(): string {
			return this._rowData.getStateString();
		}

		/**
		 * 현재 row의 상태값을 문자형으로 반환합니다.
		 * @param isAbbreviation 축양형 표현 여부.
		 * @return 현재 row의 상태값 문자.<br>
		 * 	변경되지 않은 상태 : "UC", "UNCHANGED"<br>
		 * 	행이 신규로 추가된 상태 :  "I", "INSERTED"<br>
		 * 	행이 수정된 상태 :  "U", "UPDATED"<br>
		 * 	행이 삭제된 상태 :  "D" , "DELETED"<br>
		 * 	행이 추가되었다가 삭제된 상태 : "ID", "INSERTDELETED"
		 */
		public getStateString(isAbbreviation: boolean = true): string {
			return data.DataUtil._getStateString(this._rowData.state, isAbbreviation);
		}

		/**
		 * 현재 row의 특정 속성값을 반환합니다.
		 * @param attrName	가져올 속성명
		 * @return 해당 속성값
		 */
		public getAttr(attrName: string): string {
			return this._rowData._getAttr(attrName);
		}

	}


	/**
	 * 데이터맵의 행 정보를 제공하는 클래스입니다.
	 *
	 * {@link Submission.setDataRowHandler}를 <code>handleDataMap</code>을 <code>true</code>로 등록하면
	 * DataMap 전송 시 이 객체가 핸들러에 전달됩니다.
	 * @private
	 */
	export class DataMapRow implements RowUnit {
		private _dataMap: data.DataMap;


		constructor(dataMap: data.DataMap) {
			this._dataMap = dataMap;
		}

		/**
		 * 데이터셋 정보값을 반환합니다.
		 * @return 데이터셋 정보값.
		 * @deprecated {@link getInfo}를 사용하시기 바랍니다.
		 */
		public getDataSetInfo(): string {
			return this.getInfo();
		}

		/**
		 * 데이터 객체(DataSet, DataMap)의 info 정보를 반환합니다.
		 */
		public getInfo(): string {
			return this._dataMap.info;
		}

		/**
		 * 이 행이 속한 데이터 객체(DataMap)를 반환합니다.
		 * 하나의 서브미션에 여러 데이터 객체가 등록된 경우, 전송 중인 행의 출처를 식별하는데 사용합니다.
		 * <pre><code>
		 * submission.setDataRowHandler(function(rowdata) {
		 *   var dataControl = rowdata.getDataControl();
		 *   if (dataControl.id === "datamap1") {
		 *     return { "tableId": "TB_USER" };
		 *   }
		 *   return null;
		 * }, true);
		 * </code></pre>
		 * @return 이 행이 속한 데이터 객체.
		 */
		public getDataControl(): data.DataMap {
			return this._dataMap;
		}

		/**
		 * 컬럼명을 배열형식으로 반환합니다.
		 * @param columnType	반환할 컬럼의 HeaderType.<br>
		 * cpr.data.header.HeaderType.ALL(defalut) : 모든 컬럼.<br>
		 * cpr.data.header.HeaderType.ORIGINAL_COLUMN : 원본 값과 현재 값을 따로 관리하고, 해당 컬럼의 값 변경시 행 상태에 영향을 끼칩니다.<br>
		 * cpr.data.header.HeaderType.DISPLAY_COLUMN : 현재 값만 가지고 있고, 해당 컬럼의 값 변경시 행 상태에 영향을 끼치지 않습니다.<br>
		 * @returns 컬럼명 배열. DataMap의 컬럼은 모두 ORIGINAL_COLUMN이므로 DISPLAY_COLUMN만 요청하면 빈 배열입니다.
		 */
		public getColumnNames(columnType: data.header.HeaderType = data.header.HeaderType.ALL): string[] {
			if ((columnType & data.header.HeaderType.ORIGINAL_COLUMN) === 0) {
				return [];
			}
			return this._dataMap.getColumnNames();
		}

		/**
		 * 입력 받은 컬럼명에 해당하는 컬럼 정보값을 반환합니다.
		 * @param colName 컬럼명.
		 * @return 컬럼 정보값.
		 */
		public getColumnInfo(colName: string): string {
			let headerInfo: string = null;
			let header: data.header.Header = this._dataMap.getHeader(colName);
			if (header) {
				headerInfo = header.getInfo();
			}
			return headerInfo;
		}

		/**
		 * 입력 받은 컬럼명에 해당하는 값을 반환합니다.
		 * @param colName	값을 가져올 column의 columnName
		 * @return 해당 데이터
		 */
		public getValue(colName: string): any {
			return this._dataMap.getValue(colName);
		}

		/**
		 * 입력 받은 컬럼명에 해당되는 원본 데이터를 반환합니다.
		 * @param colName	값을 가져올 column의 columnName
		 * @return 해당 데이터
		 */
		public getOriginalValue(colName: string): any {
			return this._dataMap.getOriginalValue(colName);
		}

		/**
		 * 입력 받은 컬럼명에 해당되는 컬럼의 데이터 타입을 반환합니다.
		 * @param colName 데이터 타입을 가져올 컬럼명.
		 * @return 데이터 타입. <br>
		 * 	cpr.data.tabledata.DataType.STRING = "string";<br>
		 * 	cpr.data.tabledata.DataType.NUMBER = "number";<br>
		 * 	cpr.data.tabledata.DataType.DATE = "date";<br>
		 * 	cpr.data.tabledata.DataType.DECIMAL = "decimal";<br>
		 * 	cpr.data.tabledata.DataType.EXPRESSION = "expression";<br>
		 * @readonly
		 */
		public getDataType(colName: string): data.tabledata.DataType {
			let dataType: data.tabledata.DataType = null;
			let header: data.header.Header = this._dataMap.getHeader(colName);
			if (header) {
				dataType = header.getDataType();
			}
			return dataType;
		}

		/**
		 * 현재 row의 상태값을 반환합니다.
		 * @return 현재 row의 상태값.<br>
		 * state 종류:<br>
		 * cpr.data.tabledata.RowState.UNCHANGED : 변경되지 않은 상태.<br>
		 * cpr.data.tabledata.RowState.INSERTED : 행이 신규로 추가된 상태.<br>
		 * cpr.data.tabledata.RowState.UPDATED : 행이 수정된 상태.<br>
		 * cpr.data.tabledata.RowState.DELETED : 행이 삭제된 상태.<br>
		 * cpr.data.tabledata.RowState.INSERTDELETED : 행이 추가되었다가 삭제된 상태.
		 * @deprecated {@link getStateString}를 사용하시기 바랍니다.
		 */
		public getState(): string {
			return cpr.data.DataUtil._getStateString(cpr.data.tabledata.RowState.EMPTIED, false);
		}

		/**
		 * 현재 row의 상태값을 문자형으로 반환합니다.
		 * @param isAbbreviation 축양형 표현 여부.
		 * @return 현재 row의 상태값 문자.<br>
		 * 	변경되지 않은 상태 : "UC", "UNCHANGED"<br>
		 * 	행이 신규로 추가된 상태 :  "I", "INSERTED"<br>
		 * 	행이 수정된 상태 :  "U", "UPDATED"<br>
		 * 	행이 삭제된 상태 :  "D" , "DELETED"<br>
		 * 	행이 추가되었다가 삭제된 상태 : "ID", "INSERTDELETED"
		 */
		public getStateString(isAbbreviation: boolean = true): string {
			return cpr.data.DataUtil._getStateString(cpr.data.tabledata.RowState.EMPTIED, isAbbreviation);
		}

		/**
		 * 현재 row의 특정 속성값을 반환합니다.
		 * @param attrName	가져올 속성명
		 * @return 해당 속성값
		 */
		public getAttr(attrName: string): string {
			return this._dataMap.getAttr(attrName);
		}

	}


}