namespace cpr.foundation {
	/**
	 * @private
	 */
	export interface FontInfo {
		"font-family": string,
		"font-size": string,
		"font-style": string,
		"font-variant": string,
		"font-weight": string,
		"line-height": string
	}

	/**
	 * @private
	 */
	export class FontManager {
		private static _managers: { [key: string]: FontManager } = {};

		public static getManager(fontInfo: FontInfo): FontManager {
			if (!fontInfo) {
				return null;
			}
			let fontStyle: string = FontManager._createFontInfoKey(fontInfo);
			let fontManager: FontManager = FontManager._managers[fontStyle];
			if (!fontManager) {
				fontManager = new FontManager(fontStyle);
				FontManager._managers[fontStyle] = fontManager;
			}

			return fontManager;
		}

		private static _createFontInfoKey(fontInfo: FontInfo): string {
			let fontStyle: string = "";
			let temp: string = null;

			temp = fontInfo["font-style"];
			if (temp && temp != "normal") {
				fontStyle += temp + " ";
			}
			temp = fontInfo["font-variant"];
			if (temp && temp != "normal") {
				fontStyle += temp + " ";
			}
			temp = fontInfo["font-weight"];
			if (temp && temp != "400") {
				fontStyle += temp + " ";
			}
			temp = fontInfo["font-size"];
			if (temp) {
				fontStyle += temp + " ";
			}
			temp = fontInfo["font-family"];
			if (temp) {
				fontStyle += temp;
			}
			temp = fontInfo["line-height"];
			if (temp && temp != "normal") {
				fontStyle += ";" + temp;
			}

			return fontStyle.trim();
		}


		private _fontStyle: string;
		private _height: number;


		private constructor(fontStyle: string) {
			this._fontStyle = fontStyle;
			this._init(fontStyle);
		}

		private _init(fontStyle: string): void {
			let chkNode: HTMLDivElement = document.createElement("div");
			chkNode.style.position = "absolute";
			chkNode.style.top = "0px";
			chkNode.style.left = "0px";
			chkNode.style.height = "auto";
			chkNode.style.width = "auto";
			chkNode.style.visibility = "hidden";

			let fontLine: string[] = fontStyle.split(";");
			chkNode.style.font = fontLine[0];
			if (fontLine.length == 2 && fontLine[1]) {
				chkNode.style.lineHeight = fontLine[1];
			}

			chkNode = document.body.appendChild(chkNode);
			let offset: number = chkNode.clientHeight;
			chkNode.textContent = "한"; // firefox의 경우 한글과 영문의 글자 높이가 다름.
			this._height = chkNode.clientHeight - offset;

			document.body.removeChild(chkNode);
		}

		public get font(): string {
			return this._fontStyle;
		}

		public get height(): number {
			return this._height;
		}

	}
}