namespace cpr.controls.gridpart.renderer {
	/**
	 * @private
	 */
	export interface IRenderOption {
		height: number,
		maxHeight: number,
		// text: string, // suppress, mergeToExprIndex 사용시 text 값
		// value: string, // suppress, mergeToExprIndex 사용시 value값 (checkbox용)
		altColumnName: string,
		editingrow?: boolean,
		hidetext: boolean,
		hideborder?: boolean,
		// ariaRowIndex?: number, // embedded checkbox,radio에서 사용 (웹 접근성)
		// ariaColIndex?: number, // embedded checkbox,radio에서 사용 (웹 접근성)
		ariaLabel?: string, // button aria-label에서 사용 (웹 접근성)
		isFirst?: boolean, // suppress 사용시 border-top style 적용에 사용
		// mergedLastIndex?: number // treecell에서 merge된 마지막 인덱스
		isLast?: boolean, // treecell이 merge된 상태에서 형제노드가 없는 마지막노드인지 여부
		isGhost?: boolean // ghost노드에 그려질 컨트롤인지 여부 (자동높이계산용)
		vrowIndex: number, // 컨트롤 tooltipManager사용시 key 값에서 사용
		cellIndex: number // 컨트롤 tooltipManager사용시 key 값에서 사용
	}

	/**
	 * @private
	 */
	export interface IGridCellRenderer {
		createCellShape(gridRow: provider.GridRow | provider.GridRowGroup, option: IRenderOption)
			: ufc.ControlShape | ufc.ControlRenderer;
	}

	/**
	 * @private
	 */
	export abstract class AbstractGridCellRenderer implements IGridCellRenderer {
		private _cellprop: GridCellProp;
		private _grid: Grid;


		constructor(cellprop: GridCellProp, grid: Grid) {
			this._cellprop = cellprop;
			this._grid = grid;
			this._init();
		}

		protected get prop(): GridCellProp {
			return this._cellprop;
		}
		protected get grid(): Grid {
			return this._grid;
		}

		protected abstract _init(): void;
		public abstract createCellShape(gridRow: provider.GridRow | provider.GridRowGroup, option: IRenderOption)
			: ufc.ControlShape | ufc.ControlRenderer;

	}

}