/// <reference path="./layout/ScrollPane.ts"/>
/// <reference path="./IGridPart.ts"/>


namespace cpr.controls.gridpart {

	/**
	 * @private
	 */
	export class GridFooter extends AbstractGridPart {


		constructor(context: GridContext, region: string, bandLayout: GridRegionLayout) {
			super(region, GRIDREGION.FOOTER, context, bandLayout);
		}

		public _getContentHeight(): number {
			return this._layout.rowHeight;
		}

		/* Shape */
		protected _doCreateShape(): ufc.ControlShape {
			let context: GridContext = this._getContext();
			let grid: Grid = context.getGrid();
			let bindContext: bind.GridEmbeddedContext = grid.getBindContext() as bind.GridEmbeddedContext;
			let autoFit: string = context._getRegionAutoFit(this.region); //context.autoFit;
			let clientWidth: number = this._scrollPane._getViewportWidth();
			let regionColWidth: { contentWidth: number, layout: { width: number }[] } = GridUtil._createRegionColWidth(autoFit, clientWidth, this._layout.columnLayout);
			let footerHeight: number = this._getContentHeight();

			let heights: number[] = [];
			this._layout.rows.forEach((rowInfo: { rowIndex: number, height: number }) => {
				heights.push(rowInfo.height);
			});

			// footer
			let footerShape: ufc.ElementShape = {
				tag: "div",
				attr: {},
				classNames: [GridContext.CLS_CELL_INHERIT],
				style: {
					position: "relative",
					border: "0"
				},
				children: []
			}
			footerShape.style["height"] = footerHeight + "px";
			if (autoFit !== "none" && clientWidth > regionColWidth.contentWidth) {
				footerShape.style["width"] = clientWidth + "px";
			} else {
				footerShape.style["width"] = regionColWidth.contentWidth + "px";
			}

			let rowShape: ufc.ElementShape = {
				tag: "div",
				classNames: [GridStyle.ROW],
				attr: {
					role: GRIDROLE.ROW
				},
				style: {
					position: "absolute",
					top: "0px",
					left: "0px",
					width: "100%",
					height: footerHeight + "px"
				},
				children: []
			};
			GridUtil._setAria(rowShape, "rowindex", "1");
			footerShape.children[0] = rowShape;

			// let ariaColCount: number = 1;
			let cellPositionRange: { start: number, end: number } = (this._scrollPane as layout.ScrollPane)._getRenderCellRange();
			let visibleColIndices: number[] = grid.getColIndicesByVisible(true);

			this._layout.cellProp.forEach((colProp: GridFooterCellProp) => {
				let cellLayout: { visible: boolean, colSpan: number } = this._getContext()._getVisibleColumn(colProp);
				if (cellLayout.visible == false) {
					return;
				}

				let regionColWidth: { contentWidth: number, layout: { width: number }[] } = GridUtil._createRegionColWidth(autoFit, clientWidth, this._layout.columnLayout);
				let realCellStyles: { style: { [key: string]: string }, bound: { left: number, top: number, width: number, mergeCellWidth: number, height: number } }
					= GridUtil._createCellStyle(regionColWidth.layout, colProp, colProp, heights, true);
				if (GridUtil._isContainedCell(realCellStyles.bound, cellPositionRange) === false) {
					return;
				}

				let beforeFooterCellIndex: number = bindContext._getFooterCellIndex();
				bindContext._setFooterCellIndex(colProp.constraint.cellIndex);
				let cellShape: ufc.ControlShape = {
					tag: "div",
					attr: {
						role: GRIDROLE.GRID_CELL,
						"data-role": GRIDROLE.FOOTER_CELL,
						// "aria-colindex": "" + (ariaColCount++),
						"data-cellindex": "" + colProp.constraint.cellIndex
					},
					classNames: _.union([GridStyle.CELL, GridContext.CLS_CELL_INHERIT]
						, (colProp.configuration) ? colProp.configuration.style.getClasses() : []),
					style: GridUtil._createCellStyle(regionColWidth.layout, colProp, colProp, heights).style,
					children: []
				};
				if (context.getGrid().isEditing() == false) { // 편집모드일 때는 그룹행에 포커스 가지 않도록 
					cellShape.attr["tabindex"] = "-1";
				}
				cpr.ufc.ShapeUtil._setAriaState(cellShape, { enabled: grid.enabled, readOnly: grid.readOnly });
				{ // aria-colspan, aria-rowspan
					let cellConst: GridCellConstraint = colProp.constraint;
					if (cellConst.colSpan > 1) {
						GridUtil._setAria(cellShape, "colspan", utils.Util.toString(cellConst.colSpan));
					}
					if (cellConst.rowSpan > 1) {
						GridUtil._setAria(cellShape, "rowspan", utils.Util.toString(cellConst.rowSpan));
					}
				}
				{ // fieldLabel
					let labelString: string[] = [];
					let expr: string | ufc.StyledString = this._getExpr(colProp);
					let exprStr: string = ufc.StyledString._asString(expr);
					if (colProp.configuration.control != null) {
						if (colProp.configuration.expr != null && colProp.configuration.expr != "") {
							colProp.configuration.control.value = exprStr;
						}
						expr = colProp.configuration.control.value;
					}
					if (utils.Util.isNullOrEmpty(colProp.configuration.control?.fieldLabel) == false) {
						labelString[labelString.length] = "" + colProp.configuration.control.fieldLabel;
					} else if (utils.Util.isNullOrEmpty(colProp.configuration.fieldLabel) == false) {
						labelString[labelString.length] = "" + colProp.configuration.fieldLabel;
					}
					labelString[labelString.length] = exprStr;
					ufc.ShapeUtil._setAriaLabelAttr(cellShape.attr, labelString.join(" "));
				}

				let isFirstColumn: boolean = colProp.constraint.colIndex == visibleColIndices[0];
				let isLastColumn: boolean = colProp.constraint.colIndex + colProp.constraint.colSpan - 1 == visibleColIndices[visibleColIndices.length - 1];
				if (isFirstColumn || isLastColumn) {
					if (cellShape.classNames == null) {
						cellShape.classNames = [];
					}
					if (isFirstColumn) {
						cellShape.classNames.push(ufc.Classes.FIRST_COLUMN);
					}
					if (isLastColumn) {
						cellShape.classNames.push(ufc.Classes.LAST_COLUMN);
					}
				}
				rowShape.children.push(cellShape);

				let cellHeight: utils.Size = utils.ParamUtil.parseSize(cellShape.style["height"]);
				let colHeight: number = cellHeight.size;
				let maxColHeight: number = GridContext._getCellMaxHeight(colHeight);
				if (colHeight == 0) {
					cellShape.style["display"] = "none";
				}

				cellShape.children[cellShape.children.length] = this._createContainer(colProp, maxColHeight);

				// TOOLTIP
				GridUtil._setCellTitle(cellShape, colProp);
				bindContext._setFooterCellIndex(beforeFooterCellIndex);
			});

			// div
			let shape: ufc.ControlShape = {
				tag: "div",
				nodename: "footer" + this.region + this.loc, // split 되었을 때 중복남
				style: {
					display: "inline-block",
					position: "relative",
					"min-width": "100%"
				},
				children: [footerShape]
			};

			return shape;
		}

		private _createContainer(colProp: GridFooterCellProp, maxColHeight: number): ufc.ControlShape {
			let container: ufc.ElementShape = {
				tag: "div",
				attr: {},
				classNames: [GridContext.CLS_CELL_INHERIT],
				style: {
					overflow: "hidden",
					position: "relative",
					height: maxColHeight + "px" // 내부 컨트롤에 높이를 지정하기 위해 필요. (2017.9.27)
				},
				children: []
			};

			let controlRenderer: (ufc.ControlRenderer | ufc.ControlShape) = null;
			let expr: string | ufc.StyledString = this._getExpr(colProp);
			let exprStr: string = ufc.StyledString._asString(expr);
			if (colProp.configuration.control != null) {
				// UI컨트롤이 설정된 경우
				colProp.configuration.control.style.css({
					width: "100%",
					height: "100%"
				});
				if (colProp.configuration.expr != null && colProp.configuration.expr != "") {
					colProp.configuration.control.value = exprStr;
				}
				controlRenderer = colProp.configuration.control._getRenderer();

				controlRenderer.addDecorator("grid-cell-decorator", (controlShape: ufc.ControlShape) => {
					controlShape.classNames = _uniq(controlShape.classNames.concat(GridContext.CLS_CTRL_INHERIT));
					GridUtil._setControlPosition(controlShape, colProp.configuration.controlConstraint);
					return controlShape;
				});
			} else {
				// 단순 Text로 설정된 경우
				let style = (colProp.configuration) ? colProp.configuration.style.css() : {};
				let textWrapper: ufc.ControlShape = {
					tag: "div",
					classNames: [GridStyle.CONTROL, GridStyle.DEFAULTCELL, GridContext.CLS_CELL_INHERIT],
					style: _mergeObject(style, {
						height: maxColHeight + "px"
					}),
					children: [{
						tag: "div",
						classNames: [GridContext.CLS_CELL_INHERIT],
						style: {
							display: "table",
							width: "100%",
							height: "100%"
						},
						children: [{
							tag: "div",
							classNames: [ufc.Classes.TEXT, GridContext.CLS_CELL_INHERIT],
							style: {
								display: "table-cell"
							},
							children: ufc.StyledString._asShape(expr)
						}]
					}]
				};
				controlRenderer = textWrapper;
			}
			container.children.push(controlRenderer);

			return container;

		}

		private _getExpr(colProp: GridFooterCellProp): string | ufc.StyledString {
			let text: string | ufc.StyledString = null;

			if (colProp.configuration.expr != null) {
				text = GridUtil._getFooterValue(this._getContext(), colProp);
			}
			return text;
		}

	}
}