/// <reference path="../exceptions/exceptions.ts"/>


namespace cpr.events {
	/**
	 * FileUpload 이벤트 유형.
	 */
	export class FileUploadEventType {
		/**
		 * 파일을 추가 시 파일의 크기가 최대 일 경우 발생하는 이벤트.<br>
		 * 추가할 파일이 최대 크기보다 큰 경우 발생합니다.<br>
		 * 추가된 파일들이 최대 크기보다 큰 경우 발생합니다.
		 */
		public static readonly MAXSIZE_EXCEED: string = "maxsize-exceed";
		/**
		 * 파일을 추가 할 때 파일의 개수가 최대 일 경우 발생하는 이벤트.
		 */
		public static readonly MAXCOUNT_EXCEED: string = "maxcount-exceed";
		/**
		 * 파일 추가 시 파일의 확장자와 기존에 등록된 확장자의 유형이 다를 경우 발생하는 이벤트.
		 */
		public static readonly EXTENSION_VIOLATE: string = "extension-violate";
		/**
		 * 파일을 추가 하기전에 발생하는 이벤트입니다. event.preventDefault()를 하면 파일을 추가하지 않습니다.
		 */
		public static readonly ADD_BEFORE_FILE: string = "add-before-file";
		/**
		 * 파일을 추가 후 발생하는 이벤트입니다.
		 */
		public static readonly ADD_FILE: string = "add-file";
		/**
		 * 파일을 삭제 하기 전에 발생하는 이벤트 입니다. event.preventDefault()를 하면 파일을 삭제하지 않습니다.
		 */
		public static readonly REMOVE_BEFORE_FILE: string = "remove-before-file";
		/**
		 * 파일을 삭제 후 발생하는 이벤트입니다.
		 */
		public static readonly REMOVE_FILE: string = "remove-file";
	}

	/**
	 * FileUpload 이벤트에 대한 옵션
	 */
	export interface CFileUploadEventOptions {
		/**
		 * FileUpload 이벤트의 파일.
		 */
		files?: File[];
	}

	/**
	 * UploadedFile 이벤트에 대한 옵션
	 */
	export interface CUploadedFileEventOptions {
		/**
		 * FileUpload 이벤트의 파일.
		 */
		uploadedFile?: controls.UploadedFile;
	}

	/**
	 * 파일 업로드 컨트롤에서 발생하는 이벤트.
	 */
	export class CFileUploadEvent extends CEvent {


		/**
		 * 파일들을 반환합니다.
		 */
		get files(): File[] {
			return this._getOption("files");
		}

	}

	/**
	 * 파일업로드에서 업로드된 파일에 대한 이벤트.
	 */
	export class CUploadedFileEvent extends CEvent {

		get uploadedFile(): controls.UploadedFile {
			return this._getOption("uploadedFile");
		}
	}
}