namespace cpr.controls.item {
	type MultiValueUIControl = UIControl & provider.MultiValueBindable;

	/**
	 * @private
	 */
	export abstract class AbstractItemList<ItemType extends Item, ItemSetConfigType> implements cpr.core.UniversallyUniqueIdentifier, ItemSetInfo {
		private _uuid: string = _generateUUID();
		private _owner: MultiValueUIControl;
		private _itemDataSource: ItemDataSource<ItemSetConfigType> = null;
		private _isDisposed: boolean = false;
		private _adapter: ItemListAdapter<ItemType>;

		constructor(owner: any, itemConfig: ItemDataSource<ItemSetConfigType>, adapter: ItemListAdapter<ItemType>) {
			this._itemDataSource = itemConfig;
			this._owner = owner;
			this._adapter = adapter;
		}

		/**
		 * 이 리스트의 소유자 컨트롤을 반환합니다.
		 */
		public get owner(): MultiValueUIControl {
			return this._owner;
		}
		/**
		 * realmCache용 UUID를 반환합니다.
		 */
		public get uuid(): string {
			return this._uuid;
		}
		/**
		 * 리스트 데이터에 바인딩된 데이터셋을 반환합니다.
		 * @return 데이터셋.
		 */
		get dataSet(): data.DataCollection {
			return this._itemDataSource.dataSet;
		}

		/**
		 * 아이템셋 설정을 반환합니다.
		 */
		get itemSetConfig(): ItemSetConfigType {
			return this._itemDataSource.itemBindingConfig;
		}

		/**
		 * 해당 리스트가 dispose 되었는지 여부를 반환합니다.
		 */
		get disposed(): boolean {
			return this._isDisposed;
		}

		/**
		 * 보이는 아이템의 행 상태를 반환합니다.
		 */
		get visibleRowState(): data.tabledata.RowState {
			return this._itemDataSource.visibleRowState;
		}

		/**
		 * 선행 아이템 배열을 반환합니다.
		 */
		public get predefinedItems(): ItemType[] {
			return this._itemDataSource.predefinedItems;
		}

		/**
		 * 선행 아이템 배열을 설정합니다.
		 * @param items 선행 아이템 배열
		 */
		protected _setPredefinedItems(items: ItemType[]): void {
			this._itemDataSource.predefinedItems = items;
		}

		/**
		 * 아이템 어댑터를 반환합니다.
		 * @returns
		 */
		public get itemAdapter(): ItemListAdapter<ItemType> {
			return this._adapter;
		}

		/**
		 * 리스트 데이터의 dataset을 지정합니다.
		 * @param dataSet 바인딩할 데이터셋.
		 * @param config 연결할 아이템 설정.
		 */
		public setItemSet(dataSet: data.DataCollection, config: ItemSetConfigType) {
			this._itemDataSource.setItemSet(dataSet, config);
		}

		/**
		 * 아이템셋이 로드될 때 발생하는 이벤트를 반환합니다.
		 */
		public get onLoadItemSet() {
			return this._itemDataSource.onLoadItemSet;
		}
		/**
		 * 아이템셋이 로드될 때 발생하는 이벤트를 설정합니다.
		 */
		public set onLoadItemSet(onLoadItemSet: (e: events.CDataEvent) => void) {
			this._itemDataSource.onLoadItemSet = onLoadItemSet;
		}

		/**
		 * 삭제된 아이템을 보이게 할지 여부를 설정합니다.
		 * @param visible 
		 */
		public setVisibleDeletedItem(visible: boolean) {
			this._itemDataSource.setVisibleDeletedItem(visible);
		}

		/**
		 * 삭제된 아이템을 보이게 할지 여부를 반환합니다.
		 * @returns 
		 */
		public getVisibleDeletedItem(): boolean {
			return this._itemDataSource.getVisibleDeletedItem();
		}

		/**
		 * 아이템을 추가합니다.<br>
		 * 콤보박스, 리스트,라디오버튼,체크박스그룹과 같은 value,label은 cpr.controls.Item입니다.
		 * 트리,링크드리스트박스, 링크드콤보박스 같은 아이템은 cpr.controls.TreeItem입니다.
		 * 메뉴,내비게이션바 같은 아이템은 cpr.controls.MenuItem 입니다.
		 * <pre><code>
		 * //combobox,list,radiobutton,checkboxgroup
		 * control.addItem(new cpr.controls.Item("label","value"));
		 * //tree,linkedcombobox,linkedlistbox
		 * control.addItem(new cpr.controls.TreeItem("label","value","parentValue"));
		 * //menu,navigationbar
		 * control.addItem(new cpr.controls.MenuItem("label","value","parentValue"));
		 * </code></pre><br>
		 * @param item 아이템의 정보.
		 */
		public addPredefinedItem(item: ItemType): void {
			if (item == null) {
				throw new cpr.exceptions.IllegalArgumentException();
			}
			//이미 존재하는 아이템이면 추가하지 않음
			let map: CMap<string, ItemType> = _stream(this.predefinedItems).toMap((each) => each._getUUID());
			if (map.has(item._getUUID())) {
				return;
			}
			this.predefinedItems.push(item);
			this.owner.redraw();
		}

		/**
		 * 선행 아이템의 속성을 설정합니다.
		 * @param item 
		 * @param key 
		 * @param value 
		 */
		protected _setPredefinedItemProperty(item: Item, key: string, value: any) {
			if (key == ItemDataSetCtrlProperty.enabled) {
				item._setEnabled(value)
			} else if (item[key] !== undefined) {
				item[key] = value;
			}
		}

		/**
		 * 선행 아이템의 속성을 반환합니다.
		 * @param item 
		 * @param key 
		 * @returns 
		 */
		protected _getPredefinedItemProperty(item: ItemType, key: string) {
			if (key == ItemDataSetCtrlProperty.enabled) {
				return item._getEnabled()
			} else if (item[key] !== undefined) {
				return item[key];
			}
			return null;
		}

		// 서브클래스는 반드시 오버라이드 해야 함.
		/**
		 * 아이템을 업데이트합니다.
		 * @param source 
		 * @param destination 
		 */
		protected _updateItem(source: ItemType, destination: ItemType): void {
			this._adapter.updateItem(source, destination);
		}

		/**
		 * 행 데이터를 아이템으로 변환합니다.
		 * @param row 
		 * @returns 
		 */
		protected _convertRowToItem(row: data.IDataRow): ItemType {
			return this._adapter.convertRowToItem(row, this);
		}

		/**
		 * 아이템의 정보를 행 데이터에 업데이트합니다.
		 * @param source 
		 * @param row 
		 */
		protected _updateRow(source: ItemType, row: data.IDataRow): void {
			this._adapter.updateRow(source, row, this);
		}

		/**
		 * 아이템을 검사합니다.
		 * @param item 
		 * @returns 
		 */
		protected _checkItem(item: ItemType): boolean {
			if (this._adapter.checkItem(item) == false) {
				return false;
			}
			if (item.value === undefined || item.label === undefined) {
				return false;
			}
			return true;
		}

		/**
		 * 리소스를 해제합니다.
		 */
		public dispose(): void {
			this._itemDataSource = null;
			this._owner = null;
			this._isDisposed = true;
		}
	}
}