namespace cpr.controls.item {

	/**
	 * Item Expression 평가를 담당하는 클래스
	 * badgeExp, enabledItemExp 등의 Expression을 평가합니다.
	 * @private
	 */
	export class ItemExpressionEvaluator {
		private _owner: UIControl;
		private _badgeExp: string = "";
		private _enabledItemExp: string = "";
		private _displayExp: string = "";

		/**
		 * Expression 평가자를 생성합니다.
		 * @param owner 소유한 컨트롤
		 */
		constructor(owner: UIControl) {
			this._owner = owner;
		}

		/**
		 * 소유한 컨트롤을 반환합니다.
		 */
		public get owner(): UIControl {
			return this._owner;
		}
		/**
		 * 화면에 보여지는 텍스트의 Expression을 반환합니다.
		 * @return 화면에 보여지는 텍스트의 Expression.
		 */
		public get displayExp(): string {
			return this._displayExp;
		}

		/**
		 * 화면에 보여지는 텍스트의 Expression을 반환합니다.<br>
		 * Expression에 제공되는 값은 label, value 입니다.
		 * <pre><code>control.displayExp = 'label+"["+value+"]"'</code></pre>
		 * @param expr 화면에 보여지는 텍스트의 Expression.
		 */
		public set displayExp(value: string) {
			if (this._displayExp == value) {
				return;
			}
			this._displayExp = value;
			this.owner.redraw();
		}
		/**
		 * 화면에 보여지는 뱃지의 Expression을 반환합니다.
		 * @return 화면에 보여지는 텍스트의 Expression.
		 */
		public get badgeExp(): expression_string {
			return this._badgeExp;
		}

		/**
		 * 화면에 보여지는 뱃지의 Expression을 설정합니다.<br>
		 * Expression에 제공되는 값은 label, value 입니다.
		 * <pre><code>control.badgeExp = 'label+"["+value+"]"'</code></pre>
		 * @param expr 화면에 보여지는 텍스트의 Expression.
		 */
		public set badgeExp(expr: expression_string) {
			if (this._badgeExp != expr) {
				this._badgeExp = expr;
				this.owner.redraw();
			}
		}

		/**
		 * 아이템의 enabled 익스프레션 값을 반환합니다.
		 */
		public get enabledItemExp(): expression_string {
			return this._enabledItemExp;
		}

		/**
		 * 아이템의 enabled를 item에 바인드된 데이터셋의 컬럼이나 label,value의 값으로 설정할 수 있습니다.
		 * ex) label != 'label1'
		 */
		public set enabledItemExp(expr: expression_string) {
			if (this._enabledItemExp != expr) {
				this._enabledItemExp = expr;
				this.owner.redraw();
			}
		}

		/**
		 * 아이템의 뱃지가 표시되는 값을 반환합니다.
		 * @param item 아이템
		 * @return 뱃지 표시 값
		 */
		public evaluateBadge(item: Item): string | ufc.StyledString {
			if (item == null || this._badgeExp == "") {
				return "";
			}

			let expr = new cpr.expression.Expression(this._badgeExp);
			let result = null;
			try {
				let that = this;
				result = expr._evaluateInternal({
					_getExpressionDelegates(): any[] {
						return [item.toExpressionContext(that.owner), that.owner.getBindContext()];
					}
				});
			} catch (e) {
				result = "";
			}
			return result;
		}

		/**
		 * 특정 아이템의 활성화 여부를 반환합니다.
		 * @param item 아이템.
		 * @return 아이템의 활성화 여부.
		 */
		public evaluateItemEnable(item: Item): boolean {
			if (item == null) {
				return true;
			}

			let isEnabled = item._getEnabled();
			if (this._enabledItemExp && isEnabled) {
				let expr = new cpr.expression.Expression(this._enabledItemExp);
				try {
					let that = this;
					isEnabled = expr._evaluateInternal({
						_getExpressionDelegates(): any[] {
							return [item.toExpressionContext(that.owner), that.owner.getBindContext()];
						}
					});
				} catch (e) {
					isEnabled = true;
				}
			}

			return isEnabled;
		}

		/**
		 * @param item 
		 */
		public evaluateDisplayLabel(item: Item): ufc.StyledString | string {
			if (item == null) {
				return "";
			}
			if (this.displayExp == "") {
				return item.label;
			}
			let expr = new cpr.expression.Expression(this.displayExp);
			let result = null;
			try {
				let that = this;
				result = expr._evaluateInternal({
					_getExpressionDelegates(): any[] {
						return [item.toExpressionContext(that.owner), that.owner.getBindContext()];
					}
				});
			} catch (e) {
				result = item.label;
			}
			return result;
		}

		/**
		 * 리소스를 해제합니다.
		 */
		public dispose(): void {
			this._owner = null;
		}
	}
}