/// <reference path="DOMEventWrapper.ts" />

namespace cpr.events {
	/**
	 * 앱 이벤트 생성 옵션
	 */
	export interface CAppEventOptions extends CEventOption {
		/**
		 * 이벤트가 상위 앱으로 전파될 것인지 여부. 생략시 <code>false</code>로 취급 됩니다.
		 */
		bubbles: boolean

		/**
		 * 앱 이벤트가 발생하게 된 원인 이벤트.
		 */
		cause?: events.CEvent
	}

	/**
	 * 부모 앱인스턴스를 통해 전파될 수 있는 이벤트를 만들 때 사용하는 클래스입니다.
	 */
	export class CAppEvent extends CEvent {
		private _bubbles: boolean = false;

		/**
		 * 새 앱 이벤트를 만듭니다.
		 * @param type 타입.
		 * @param options 앱 이벤트 옵션.
		 */
		constructor(type: string, options?: CAppEventOptions) {
			super(type, options);
			this._bubbles = options?.bubbles ?? false;
			this.nativeEvent = options?.cause?.nativeEvent;
		}

		protected override _getDefaultEventOptions(): { [key: string]: any; } {
			return _assign(super._getDefaultEventOptions(), { bubbles: false });
		}

		override get bubbles() {
			return this._bubbles;
		}

		/**
		 * 이벤트를 발송한 앱 인스턴스를 얻습니다.
		 */
		public get appIntance(): core.AppInstance {
			let control = this.control;
			if (control instanceof core.AppInstance) {
				return control;
			} else {
				return null;
			}
		}

		/**
		 * 최초 이벤트를 발송한 앱 인스턴스를 얻습니다.
		 */
		public get targetAppInstance(): core.AppInstance {
			let target = this.targetControl;
			if (target instanceof core.AppInstance) {
				return target;
			} else {
				return null;
			}
		}

		/**
		 * 최초 이벤트를 발송한 앱인스턴스를 실행중인 UDC 컨트롤 또는 임베디드 앱을 얻습니다.
		 */
		public get targetHostControl(): controls.EmbeddedApp {
			return this.targetAppInstance?.getHost();
		}
	}
}