/// <reference path="./ListDataProvider.ts"/>


namespace cpr.controls.provider {

	/**
	 * @private
	 */
	export class TreeItemChecker extends ItemChecker {
		constructor(info: { ownerId: string, ownerType: string, multiple: boolean, delimiter: string }) {
			super(info);
		}

		protected override _createError(message: string, item: TreeItem) {
			return { message: message, id: this._info.ownerId, type: this._info.ownerType, value: item.value, parentValue: item.parentValue }
		}

		protected _checkParentValue(item: TreeItem, immediately: boolean = true) {
			if (this._hasError()) {
				return;
			}
			if (item.value == item.parentValue) {
				this._error = this._createError("value and parentValue are the same.", item);
				if (immediately) {
					this._exception()
				}
			}
		}

		protected _checkCrossReference(item: TreeItem, checkItemMap: ItemMap<TreeItem>, immediately: boolean = true) {
			if (this._hasError()) {
				return;
			}
			let parentItem = checkItemMap.get(item.parentValue);
			if (parentItem && parentItem.value == item.parentValue && parentItem.parentValue == item.value) {
				this._error = this._createError("cross reference.", item);
				if (immediately) {
					this._exception()
				}
			}
		}

		public check(item: TreeItem, checkedItemMap: ItemMap<TreeItem>, immediately: boolean = true): void {
			super.check(item, checkedItemMap, immediately);
			this._checkParentValue(item, immediately);
			this._checkCrossReference(item, checkedItemMap, immediately);
		}
	}
	/**
	 * value, label, prentValue로 구성된 트리 형태의 데이터를 관리하는 상위 클래스.
	 * @private
	 */
	export abstract class AbstractTreeDataProvider<ItemType extends TreeItem, ConfigType extends TreeItemSetConfig, ControlType extends UIControl & MultiValueBindable> extends AbstractListDataProvider<ItemType, ConfigType, UIControl & MultiValueBindable> {
		private _rootValue: string = "";

		private _treeFilterExpression: cpr.expression.Expression;
		/**
		 * value, label, parentValue로 구성된 트리 형태의 데이터를 가진 컨트롤을 생성합니다.
		 * @param owner 다중 선택을 할 수 있는 value를 가진 컨트롤.
		 */
		constructor(owner: ControlType) {
			super(owner);
		}

		/**
		 * 최상위 value를 반환합니다.
		 * @return 최상위 value.
		 */
		get rootValue(): string {
			return this._rootValue;
		}

		/**
		 * 최상위 value를 설정합니다.
		 * @param rootValue 최상위 value.
		 */
		set rootValue(rootValue: string) {
			this._rootValue = rootValue;
		}

		/**
		 * 해당 트리 데이터의 상위(부모) 데이터를 반환합니다.
		 * @param item 트리 데이터.
		 * @return 상위 트리 데이터.
		 */
		public getParent(item: ItemType): ItemType {
			if (item == null) {
				return null;
			}
			let parentValue: string = item.parentValue;
			return this.getByValue(parentValue);
		}

		/**
		 * 해당 트리 데이터의 모든 하위(자식) 데이터를 반환합니다.
		 * @param item 트리 데이터.
		 * @return 하위 트리 데이터의 배열.
		 */
		public getChildren(item?: ItemType): ItemType[] {
			if (item == null) {
				return this.getTreeItems();
			}
			//이전에 value 기반으로 아이템을 가져와서 유지해야함. 다른 컨트롤의 아이템을 받았을때 value만 맞으면 동작함. 2020-10-08
			let findItem = this.findTreeItem((each: ItemType) => each.value == item.value, this.getTreeItems());
			if (findItem) {
				return findItem.children as ItemType[];
			}
			return [];
		}

		/**
		 * 모든 아이템들을 닫습니다.
		 */
		public collapseAllItems() {
			this._predefinedItems.forEach((item: ItemType) => {
				if (item.expanded) {
					item._setOpen(false);
				}
			});

			if (this._dataSet) {
				let rowIndices: number[] = this._dataSet.getRowStatedIndices(this._visibleRowState);
				rowIndices.forEach((rowIndex: number) => {
					if (this._dataSet._getCtrlAttr(this.owner, rowIndex, ItemDataSetCtrlProperty.open)) {
						this._dataSet._setCtrlAttr(this.owner, rowIndex, ItemDataSetCtrlProperty.open, false);
					}
				});
			}
		}

		public getTreeFilter(): expression_string {
			if (this._treeFilterExpression) {
				return this._treeFilterExpression.src;
			}
			return null;
		}

		public setTreeFilter(filterExpression: expression_string) {

			if (filterExpression) {
				this._treeFilterExpression = new expression.Expression(filterExpression);
			} else {
				this._treeFilterExpression = null;
			}
		}

		public findTreeItem(condition: (item: ItemType) => boolean, items: ItemType[]): ItemType {
			if (items == null) {
				return null;
			}

			let result = _createTreeStream({ children: items } as any as ItemType, false, (each: ItemType) => {
				return each.children;
			}).find((each: ItemType) => {
				return condition(each);
			}) as ItemType;

			return result;
		}

		protected _setPredefinedItemProperty(item: ItemType, key: string, value: any) {
			if (key == ItemDataSetCtrlProperty.open) {
				item._setOpen(value);
			}
			super._setPredefinedItemProperty(item, key, value);
		}

		protected _getPredefinedItemProperty(item: ItemType, key: string) {
			if (key == ItemDataSetCtrlProperty.open) {
				return item._getOpen();
			}
			return super._getPredefinedItemProperty(item, key);
		}

		/**
		 * 해당 트리 데이터가 상위(부모) 데이터를 가졌는 지 여부를 반환합니다.
		 * @param item 트리 데이터.
		 * @return 상위 데이터 보유 여부.
		 */
		public hasParent(item: ItemType): boolean {
			return this.getParent(item) != null;
		}

		/**
		 * 해당 트리 데이터가 하위(자식) 데이터를 가졌는 지 여부를 반환합니다.
		 * @param item 트리 데이터.
		 * @return 하위 데이터 보유 여부.
		 */
		public hasChild(item: Item): boolean {
			let findChild = this._findOne((it: ItemType) => {
				return it.parentValue == item.value;
			});
			return findChild != null;
		}

		/**
		 * 해당 트리 데이터의 하위 데이터를 포함하여 선택 해제합니다.
		 * @param item 선택 해제하려는 트리 데이터.
		 */
		public deepRemoveSelection(item: ItemType): void {
			this.deepRemoveSelectionByValue(item.value);
		}

		/**
		 * value에 해당하는 트리 데이터의 하위 데이터를 포함하여 선택 해제합니다.
		 * @param value 선택 해제하려는 트리 데이터의 value.
		 */
		public deepRemoveSelectionByValue(value: string): void {
			this.deepRemoveSelectionByParentValue(value);
			let currentValues = this.castedOwner.values;
			let exstingIndex = currentValues.indexOf(value);
			if (exstingIndex !== -1) {
				currentValues.splice(exstingIndex, 1);
				this.castedOwner.values = currentValues;
			}
		}

		/**
		 * 해당 트리 데이터의 하위 데이터를 선택 해제합니다.
		 * @param item 트리 데이터.
		 */
		public deepRemoveSelectionByParent(item: ItemType): void {
			this.deepRemoveSelectionByParentValue(item.parentValue);
		}

		/**
		 * parentValue에 해당하는 트리 데이터의 하위 데이터를 선택 해제합니다.
		 * @param parentValue 트리 데이터의 parentValue.
		 */
		public deepRemoveSelectionByParentValue(parentValue: string): void {
			let items: ItemType[] = this.findSelection("parentValue", parentValue) as ItemType[];
			if (items == null || items.length == 0) {
				return;
			}
			for (let i: number = 0; i < items.length; i++) {
				this.deepRemoveSelection(items[i]);
			}
		}

		public isExpanded(item: ItemType): boolean {
			let attr = this.getItemAttribute(item, ItemDataSetCtrlProperty.open);
			return typeof attr == "boolean" ? attr : attr == "true";
		}

		public setExpanded(item: ItemType, state: boolean) {
			this.setItemAttribute(item, ItemDataSetCtrlProperty.open, state);
		}

		/**
		 * 체크박스를 체크하거나 해제합니다.
		 * @param sourceItem 
		 * @param state 
		 */
		public setChecked(sourceItem: ItemType, state: boolean): boolean {
			return this.setItemAttribute(sourceItem, ItemDataSetCtrlProperty.checked, state);
		}

		public getCheckedItems() {
			return this._find((it: ItemType) => {
				return it.checked;
			});
		}

		public setCheckedItems(checkedItems: ItemType[]) {
			let checkedItemMap = _stream(checkedItems).toMap((each) => each.value);

			this._predefinedItems.forEach((each) => {
				if (checkedItemMap.has(each.value)) {
					each.checked = true;
				} else {
					each.checked = false;
				}
			});
			if (this._dataSet != null) {
				let rowIndices: number[] = this._dataSet.getRowStatedIndices(this._visibleRowState);
				rowIndices.forEach((rowIndex: number) => {
					let row: data.IDataRow = this._dataSet.getRow(rowIndex);
					let value = utils.Util.toString(row.getValue(this.itemSetConfig.value));
					let hasChecked = checkedItemMap.has(value);
					if (this.itemSetConfig.checked) {
						let checked = row.getValue(this.itemSetConfig.checked);
						if (hasChecked) {
							row.setValue(this.itemSetConfig.checked, "true");
						} else if (checked == "true") {
							row.setValue(this.itemSetConfig.checked, "false");
						}
					} else {
						if (hasChecked) {
							this._dataSet._setCtrlAttr(this.owner, row.getIndex(), ItemDataSetCtrlProperty.checked, true);
						} else {
							this._dataSet._deleteCtrlAttr(this.owner, row.getIndex(), ItemDataSetCtrlProperty.checked);
						}
					}
				});
			}

		}

		/**
		 * 
		 * @param source 
		 * @param destination 
		 * @override
		 */
		protected _updateItem(source: ItemType, destination: ItemType) {
			super._updateItem(source, destination);
			destination.parentValue = source.parentValue;
		}

		/**
		 * 적용된 필터를 제거합니다.
		 * @override
		 */
		clearFilter(): void {
			if (this._treeFilterExpression) {
				this._treeFilterExpression = null;
			}
			super.clearFilter();

		}

		/**
		 * 필터가 있는지 유무를 확안합니다.
		 * @override
		 */
		protected _hasFilter() {
			return super._hasFilter() || this._treeFilterExpression != null;
		}

		/**
		 * render에서 사용할 아이템조회. 아이템의 중복을 체크한다.
		 * 즉시 오류 발생이 false인 경우 _validateItems를 통해 다음에 오류를 발생 할 수 있다.
		 * @private
		 * @param immediatelyException 즉이 오류를 발생할지 여부
		 * @override
		 */
		public getViewItems(immediatelyException: boolean = true) {
			let hasFilter = this._hasFilter();
			let itemInfo = this._getItemInfo(hasFilter == false, immediatelyException);
			let rootItems: ItemType[] = itemInfo.rootItems;

			if (this._filterExpression) {
				let items: ItemType[] = itemInfo.items;
				rootItems = this._filterItems(items, rootItems, true, immediatelyException).rootItems;
			}

			if (this._treeFilterExpression) {
				rootItems = this._treeFilterItems(rootItems, true, immediatelyException);
			}
			return rootItems;
		}

		public getTreeItems() {
			return this.getViewItems(false);
		}

		private _filterItems(items: ItemType[], rootItems: ItemType[], useException: boolean = false, immediatelyException: boolean = false) {
			if (!this._filterExpression) {
				return { items: items, rootItems: rootItems };
			}
			let valueKeyMap = new ItemMap<ItemType>();
			if (useException) {
				if (!this._treeFilterExpression) {
					let treeItemChecker = new TreeItemChecker({
						ownerId: this.castedOwner.id, ownerType: this.castedOwner.type, multiple: this.castedOwner.multiple, delimiter: this.castedOwner.delimiter
					});
					valueKeyMap.setterValidator = (item, itemMap) => {
						treeItemChecker.check(item, itemMap, immediatelyException);
					};
				}
			}

			let filterItems = [];
			let bindCtx: bind.BindContext = this.owner.getBindContext();
			let filterFunc: (item: ItemType, key: number, context: ItemType[]) => boolean = this._filterExpression.asFilter();
			let appInstance = this.owner.getAppInstance();
			items.forEach((item: ItemType, key: number, context: ItemType[]) => {
				item._ownerBindContext = bindCtx;
				item._expressionIDLookupProvider = appInstance;

				let filterResult: boolean = filterFunc(item, key, context);
				if (filterResult) {
					let newItem = this._copyItem(item);
					valueKeyMap.set(newItem.value, newItem);
					filterItems[filterItems.length] = newItem;
				}
				item._expressionIDLookupProvider = null;
				item._ownerBindContext = null;
			});
			rootItems = this._createTreeStructure(valueKeyMap, filterItems);
			valueKeyMap = null;
			return { items: filterItems, rootItems: rootItems }
		}

		private _treeFilterItems(rootItems: ItemType[], useException: boolean = false, immediatelyException: boolean = false) {
			if (!this._treeFilterExpression) {
				return rootItems;
			}
			let checkedItemMap: ItemMap<ItemType>;
			if (useException) {
				checkedItemMap = new ItemMap<ItemType>();
				let treeItemChecker = new TreeItemChecker({
					ownerId: this.castedOwner.id, ownerType: this.castedOwner.type, multiple: this.castedOwner.multiple, delimiter: this.castedOwner.delimiter
				});
				checkedItemMap.setterValidator = (item, itemMap) => {
					treeItemChecker.check(item, itemMap, immediatelyException);
				};
			}

			let bindCtx: bind.BindContext = this.owner.getBindContext();
			let filterFunc: (item: ItemType, key: number, context: ItemType[]) => boolean = this._treeFilterExpression.asFilter();
			let appInstance = this.owner.getAppInstance();

			let treeFilteredItems = this._filterTreeItemExpr(null, rootItems, filterFunc, { bindContext: bindCtx, lookupProvider: appInstance, itemMap: checkedItemMap });

			return treeFilteredItems;
		}

		private _filterTreeItemExpr(parent: ItemType, items: ItemType[], filterFunction: (item: ItemType, key: number, context: ItemType[]) => boolean,
			info: { bindContext: bind.BindContext, lookupProvider: core.AppInstance, itemMap?: ItemMap<ItemType> }) {

			let result = [];
			items.forEach((each: ItemType, index: number, context: ItemType[]) => {
				let newItem = this._copyItem(each);
				if (each._hasChild()) {
					let children = this._filterTreeItemExpr(newItem, each.children as ItemType[], filterFunction, info) as ItemType[];
					newItem._setChildren(children);
				}

				each._ownerBindContext = info.bindContext;
				each._expressionIDLookupProvider = info.lookupProvider;
				let filterRs: boolean = filterFunction(each, index, context);
				each._expressionIDLookupProvider = null;
				each._ownerBindContext = null;
				if (filterRs || newItem._hasChild()) {
					if (info.itemMap) {
						info.itemMap.set(newItem.value, newItem);
					}
					newItem._setParent(parent);
					result[result.length] = newItem;
				}
			})
			return result;
		}

		/**
		 * 조건에 맞는 아이템 하나를 찾습니다.
		 * @param findFunc 
		 * @param useFilter
		 * @override 
		 */
		protected _findOne(findFunc: (it: ItemType, idx?: number) => boolean, useFilter: boolean = true): ItemType {
			let result: ItemType = null;
			let items: ItemType[] = this._hasFilter() && useFilter ? this.getFilteredItems() : this.getAllItems();
			items.some((each: ItemType, index: number) => {
				if (findFunc(each, index) == true) {
					result = each;
					return true;
				}
				return false;
			});
			return result;
		}

		/**
		 * 선택된 아이템들을 찾습니다.
		 * @override
		 */
		protected _findSelectionItem(): ItemType[] {
			let valueSet = _createSet<string>(this.castedOwner.values);
			let findItems = this._find((it: ItemType) => {
				return valueSet.has(it.value);
			}, false);
			return findItems;
		}

		/**
		 * 조건에 맞는 아이템들을 찾습니다.
		 * @param findFunc 
		 * @param useFilter
		 * @override 
		 */
		protected override _find(findFunc: (it: ItemType, idx?: number) => boolean, useFilter: boolean = true): ItemType[] {
			let items: ItemType[] = this._hasFilter() && useFilter ? this.getFilteredItems() : this.getAllItems();
			return items.filter((each: ItemType, index: number) => {
				return findFunc(each, index) == true;
			});
		}

		/**
		 * 트리의 아이템들을 배열로 변경합니다.
		 * @param rootItems 
		 */
		public toItemArray(rootItems: ItemType[]): ItemType[] {
			let result: ItemType[] = [];
			rootItems.forEach((each: ItemType) => {
				result.push(each);

				if (each._hasChild()) {
					result = result.concat(this.toItemArray(each.children as ItemType[]));
				}
			});
			return result;
		}

		/**
		 * 리스트 데이터 목록을 가져옵니다.
		 * Filter가 적용된 경우 Filtering 된 List를 가져옵니다.
		 * @return 리스트 데이터 목록.
		 * @override
		 */
		protected override _getItems(useFilter: boolean = true): ItemType[] {
			let itemInfo = this._getItemInfo();
			let items: ItemType[] = itemInfo.items;
			let rootItems = itemInfo.rootItems;

			if (this._filterExpression && useFilter) {
				let filterInfo = this._filterItems(items, rootItems)
				rootItems = filterInfo.rootItems;
				items = filterInfo.items;
			}

			if (this._treeFilterExpression && useFilter) {
				rootItems = this._treeFilterItems(rootItems);
				items = this.toItemArray(rootItems);
			}

			return items;
		}

		private _getItemInfo(useException: boolean = false, immediatelyException: boolean = false): { items: ItemType[], rootItems: ItemType[] } {
			let checkedItemMap = new ItemMap<ItemType>();
			let processItemData: (item: ItemType) => void = (item: ItemType) => {
				checkedItemMap.set(item.value, item);
			}
			if (useException) {
				let treeItemChecker = new TreeItemChecker({
					ownerId: this.castedOwner.id, ownerType: this.castedOwner.type,
					delimiter: this.castedOwner.delimiter,
					multiple: this.castedOwner.multiple
				})
				processItemData = (item: ItemType) => {
					treeItemChecker.check(item, checkedItemMap, immediatelyException);
					checkedItemMap.set(item.value, item);
				}
			}
			let items: ItemType[] = [];
			this._predefinedItems.forEach((item: ItemType) => {
				item._setParent(null);// 선행데이터 객체를 참조 하고 있어 부모,자식을 삭제해야함.
				item._setChildren(null);
				processItemData(item);
				items[items.length] = item;
			});
			if (this._dataSet != null) {
				let rowIndices: number[] = this._dataSet.getRowStatedIndices(this._visibleRowState);
				rowIndices.forEach((rowIndex: number) => {
					let row: data.IDataRow = this._dataSet.getRow(rowIndex);
					let item: ItemType = this._convertRowToItem(row);
					processItemData(item);
					items[items.length] = item;
				});
			}

			let rootItems = this._createTreeStructure(checkedItemMap, items);
			checkedItemMap = null;
			return { items: items, rootItems: rootItems };
		}

		private _createTreeStructure(valueKeyMap: ItemMap<ItemType>, items: ItemType[]) {

			let rootItems = [];
			for (let currentItem of items) {
				//부모 자식간에 노드 연결
				let parentValue = currentItem.parentValue;
				let parentItem = valueKeyMap.get(parentValue);
				if (parentItem && parentValue != currentItem.value) {
					if (parentItem._getChildren() == null) {
						parentItem._setChildren([]);
					}
					currentItem._setParent(parentItem);
					parentItem._getChildren()[parentItem.children.length] = currentItem;
				} else {
					rootItems[rootItems.length] = currentItem;
				}
			}
			return rootItems;
		}

		/**
		 * 아이템의 정보를 복사합니다.
		 * @param item 
		 * @override
		 */
		protected abstract _copyItem(item: ItemType): ItemType
	}

	/**
	 * key, value, prentValue로 구성된 트리 형태의 데이터를 관리하는 상위 클래스.
	 * @private
	 */
	export class TreeDataProvider extends AbstractTreeDataProvider<TreeItem, TreeItemSetConfig, any> {

		protected _copyItem(item: TreeItem): TreeItem {
			return new TreeItem(item._getDataAccessor());
		}

		/**
		 * 아이템과 연결된 데이터셋의 로우에 아이템 정보를 반영합니다.
		 * @param source 
		 * @param row 
		 */
		protected updateRow(source: TreeItem, row: data.Row) {
			row.setValue(this.itemSetConfig.label, source.label);
			row.setValue(this.itemSetConfig.value, source.value);
			if (this.itemSetConfig.parentValue) {
				row.setValue(this.itemSetConfig.parentValue, source.parentValue);
			}
			if (this.itemSetConfig.icon) {
				row.setValue(this.itemSetConfig.icon, source.icon);
			}
			if (this.itemSetConfig.tooltip) {
				row.setValue(this.itemSetConfig.tooltip, source.tooltip);
			}
			if (this.itemSetConfig.checked) {
				row.setValue(this.itemSetConfig.checked, source.checked);
			}
		}

		/**
		 * 데이터셋의 로우를 아이템으로 변환합니다.
		 * @param row 
		 */
		protected convertRowToItem(row: data.Row): TreeItem {

			let treeItem = new TreeItem(row, this);

			return treeItem;

		}

	}

}