namespace cpr.protocols.matrix {


	/**
	 * @private
	 * MatrixSubmission은 RequestEncoder를 stringEncoder 형태로 사용하고 있어서 컨텐츠 변경에 대해 지원 불가.
	 */
	export class MatrixRequestBuilder implements RequestBuilder {
		private static _instance: MatrixRequestBuilder;

		public static get INSTANCE(): MatrixRequestBuilder {
			if (!MatrixRequestBuilder._instance) {
				MatrixRequestBuilder._instance = new MatrixRequestBuilder();
			}
			return MatrixRequestBuilder._instance;
		}


		constructor() {
		}

		public build(submission: AbstractSubmission): any {
			if (submission instanceof MatrixSubmission == false) {
				throw new exceptions.IllegalArgumentException("cpr.protocols.MatrixSubmission");
			}

			let result: any = this._buildSpecific(submission as MatrixSubmission);

			return result;
		}

		public getContentType(): string {
			return Submission.MEDIA_JSON;
		}

		private _buildSpecific(submission: MatrixSubmission): any {
			// json request object
			let jsonobject: {} = this._buildJsonRequestObject(submission);

			// CustomRequestData
			let customRequestDatas: CustomRequestData[] = submission.getAllRequestDatas();
			if (customRequestDatas && customRequestDatas.length > 0) {
				if (jsonobject == null) {
					jsonobject = {};
				}
				for (let idx: number = 0; idx < customRequestDatas.length; idx++) {
					let customData: CustomRequestData = customRequestDatas[idx];
					if (customData) {
						this._buildCustomData(jsonobject, customData);
					}
				}
			}

			if (jsonobject == null) {
				return null;
			}

			if (Submission._HASBODY_METHOD.indexOf(submission.method) === -1) {
				console.warn("Submission(\"" + submission.id + "\") method has been changed to POST. \""
					+ Submission.MEDIA_JSON + "\" media types can not use "
					+ submission.method.toUpperCase() + " method. Available methods [" + Submission._HASBODY_METHOD.join(",").toUpperCase() + "]");

				submission.method = Submission.METHOD_POST;
			}

			let strEncoder: (strData: string) => string = null;
			let encoderSpec: RequestEncoderSpec = submission._getRequestEncoder();
			if (encoderSpec && encoderSpec.encoder) {
				strEncoder = (strData: string) => {
					let encodingResult: EncodingResult = encoderSpec.encoder(submission, strData) as EncodingResult;
					return encodingResult.content as string;
				};
			}

			let jsonBlob: utils.JSONBlob = new utils.JSONBlob();
			let reqBlob: Blob = jsonBlob.toBlob(jsonobject, strEncoder, { decimalFormat: "number", mimeType: "application/json" });

			return reqBlob;
		}

		private _buildJsonRequestObject(submission: MatrixSubmission): {} | {}[] {
			let matrixDataModel: MatrixDataModel = submission._getProtocolDataModel() as MatrixDataModel;
			let requestModel: RequestMetaModel = matrixDataModel._getRequestMatrix();

			let jsonobject: {} | {}[] = null;

			if (requestModel) {
				// jsonobject = {};
				if (requestModel.format === "array") {
					jsonobject = [];
				} else {
					jsonobject = {};
				}

				let reqMetaModelData: number | string | RequestDataModel = requestModel.data;
				if (reqMetaModelData) {
					let childModel: RequestDataModel = reqMetaModelData as RequestDataModel;

					let dataContext: MatrixDataContext = null;
					let dataControl = requestModel.dataControl as (data.DataCollection | data.DataMap);
					if (dataControl) {
						dataContext = new MatrixDataContext(dataControl);
					}
					if (requestModel.format === "array") {
						let jsonarray: {}[] = jsonobject as {}[];

						if (dataControl instanceof data.DataMap) {
							let mapDataContext: MatrixDataContext = new MatrixDataContext(dataControl);
							let childObject: {} = {};
							jsonarray[jsonarray.length] = childObject;

							for (let childAttName in childModel) {
								let childAttSchema: RequestMetaModel = childModel[childAttName];
								this._buildAttribute(submission, childObject, childAttName, childAttSchema, mapDataContext);
							}

						} else {
							let payload: PayloadType = requestModel.payload === "all" ? PayloadType.all : PayloadType.modified; // elease-test-project#4066 payload 지원
							let availableStates: data.tabledata.RowState[] = this._getAvailableStates(payload);

							let colNmIdx: { [key: string]: number } = this._getDataSetOriginalColumnIdx(dataControl);

							dataControl.getUnfilteredRowDatas((dataRow: data.DataRow) => {
								let state: data.tabledata.RowState = dataRow.getState();
								if (availableStates.indexOf(state) == -1) {
									return false;
								}
								let rowDataContext: MatrixDataContext = new MatrixDataContext(dataRow);
								let additionalParam: { [key: string]: string } = submission._handleDataRow(dataControl as data.DataSet, dataRow._getRowData(), colNmIdx);

								let childObject: {} = {};
								jsonarray[jsonarray.length] = childObject;

								for (let childAttName in childModel) {
									let childAttSchema: RequestMetaModel = childModel[childAttName];
									this._buildAttribute(submission, childObject, childAttName, childAttSchema, rowDataContext);
								}

								this._applyAdditionalParam(childObject, additionalParam);

								return false;
							});
						}
					} else {
						for (let childAttName in childModel) {
							let childAttSchema: RequestMetaModel = childModel[childAttName];
							this._buildAttribute(submission, jsonobject, childAttName, childAttSchema, dataContext);
						}
					}
				}
			}

			return jsonobject;
		}

		private _buildAttribute(submission: MatrixSubmission, container: {}, attName: string, attSchema: RequestMetaModel, dataContext: MatrixDataContext): void {
			let format: MetaModelFormat = attSchema.format;
			let dataControl = attSchema.dataControl as (data.DataCollection | data.DataMap);
			let path: string = attSchema.path;
			let reqMetaModelData: number | string | RequestDataModel = attSchema.data;

			switch (format) {
				case "simple": {
					if (dataControl && path) {
						// "useYn": { "format": "simple", "dataControl": dm2, "path": "@useYn" }
						let localDataContext: MatrixDataContext = new MatrixDataContext(dataControl);
						container[attName] = localDataContext._getValue(path);
					} else if (path) {
						// "type" : { "format": "simple", "path": "@type" }
						let value: any = "";
						if (dataContext) {
							value = dataContext._getValue(path);
						}
						container[attName] = value;
					} else {
						// "id"   : { "format": "simple", "data": "PU000002" }
						let dataType: string = typeof reqMetaModelData;
						if (dataType == "number" || dataType == "string") {
							container[attName] = reqMetaModelData;
						}
					}
					break;
				}
				case "object": {
					let childObject: {} = {};
					container[attName] = childObject;

					let childModel: RequestDataModel = reqMetaModelData as RequestDataModel;
					let childDataContext: MatrixDataContext = dataContext;
					if (dataControl) {
						//"productItemCodeType": {"format": "object", "dataControl": dm2,
						//  "data": {
						//    "type": {"format": "simple", "path": "@type"},
						//    "description": {"format": "simple", "path": "@description"}
						//  }
						//}
						if (dataControl instanceof data.DataMap) {
							childDataContext = new MatrixDataContext(dataControl);

							if (reqMetaModelData) {
								let additionalParam: { [key: string]: string } = submission._handleDataMap(dataControl as data.DataMap);

								for (let childAttName in childModel) {
									let childAttSchema: RequestMetaModel = childModel[childAttName];
									this._buildAttribute(submission, childObject, childAttName, childAttSchema, childDataContext);
								}

								this._applyAdditionalParam(childObject, additionalParam);
							}
						} else {
							// dataSet
							let dataSet: data.DataCollection = dataControl as data.DataCollection;
							let linked: boolean = attSchema.linked;

							let payload: PayloadType = attSchema.payload === "all" ? PayloadType.all : PayloadType.modified; // elease-test-project#4066 payload 지원
							let availableStates: data.tabledata.RowState[] = this._getAvailableStates(payload);

							// link에 의한 filtering bind(#FIXME 현재는 DataCollection -> DataCollection 만 지원)
							let oldBindedRowId: string = null;
							if (linked === true && dataContext) {
								oldBindedRowId = dataSet.getBindedParentRowId();
								let parentRow: data.IDataRow = dataContext._getRowContext();
								if (parentRow) {
									dataSet._bindParentRow(parentRow, false);
								}
							}

							let colNmIdx: { [key: string]: number } = this._getDataSetOriginalColumnIdx(dataSet);

							let catched: boolean = false;
							dataSet.getUnfilteredRowDatas((dataRow: data.DataRow) => {
								if (catched) {
									return false;
								}
								let state: data.tabledata.RowState = dataRow.getState();
								if (availableStates.indexOf(state) == -1) {
									return false;
								}

								catched = true;
								let rowDataContext: MatrixDataContext = new MatrixDataContext(dataRow);

								let additionalParam: { [key: string]: string } = submission._handleDataRow(dataSet as data.DataSet, dataRow._getRowData(), colNmIdx);

								for (let childAttName in childModel) {
									let childAttSchema: RequestMetaModel = childModel[childAttName];
									this._buildAttribute(submission, childObject, childAttName, childAttSchema, rowDataContext);
								}

								this._applyAdditionalParam(childObject, additionalParam);

								return false;
							});

							// link에 의한 filtering unbind(#FIXME 현재는 DataCollection -> DataCollection 만 지원)
							if (linked === true && dataContext) {
								dataSet._bindParentRowId(oldBindedRowId, false);
							}
						}
					} else {
						//"period": {"format": "object",
						//  "data": {
						//    "startDate": {"format": "simple", "path": "@startDate"},
						//    "endDate": {"format": "simple", "path": "@endDate"}
						//  }
						//}
						if (reqMetaModelData) {
							for (let childAttName in childModel) {
								let childAttSchema: RequestMetaModel = childModel[childAttName];
								this._buildAttribute(submission, childObject, childAttName, childAttSchema, childDataContext);
							}
						}
					}
					break;
				}
				case "array": {
					let childArray: {}[] = [];
					container[attName] = childArray;

					let childModel: RequestDataModel = reqMetaModelData as RequestDataModel;
					let dataSet: data.DataCollection = dataControl as data.DataCollection;
					if (dataSet) { // TODO DataMap 도 지원해야 함
						let linked: boolean = attSchema.linked;

						let payload: PayloadType = attSchema.payload === "all" ? PayloadType.all : PayloadType.modified; // elease-test-project#4066 payload 지원
						let availableStates: data.tabledata.RowState[] = this._getAvailableStates(payload);

						// link에 의한 filtering bind(#FIXME 현재는 DataCollection -> DataCollection 만 지원)
						let oldBindedRowId: string = null;
						if (linked === true && dataContext) {
							oldBindedRowId = dataSet.getBindedParentRowId();
							let parentRow: data.IDataRow = dataContext._getRowContext();
							if (parentRow) {
								dataSet._bindParentRow(parentRow, false);
							}
						}
						// TODO 상수 Array 지원(추가 스펙이 필요)

						let colNmIdx: { [key: string]: number } = this._getDataSetOriginalColumnIdx(dataSet);

						dataSet.getUnfilteredRowDatas((dataRow: data.DataRow) => {
							let state: data.tabledata.RowState = dataRow.getState();
							if (availableStates.indexOf(state) == -1) {
								return false;
							}

							let rowDataContext: MatrixDataContext = new MatrixDataContext(dataRow);

							let additionalParam: { [key: string]: string } = submission._handleDataRow(dataSet as data.DataSet, dataRow._getRowData(), colNmIdx);

							let childObject: {} = {};
							childArray[childArray.length] = childObject;

							for (let childAttName in childModel) {
								let childAttSchema: RequestMetaModel = childModel[childAttName];
								this._buildAttribute(submission, childObject, childAttName, childAttSchema, rowDataContext);
							}

							this._applyAdditionalParam(childObject, additionalParam);

							return false;
						});

						// link에 의한 filtering unbind(#FIXME 현재는 DataCollection -> DataCollection 만 지원)
						if (linked === true && dataContext) {
							dataSet._bindParentRowId(oldBindedRowId, false);
						}
					}
					break;
				}
			}
		}

		private _buildCustomData(jsonobject: {}, customData: CustomRequestData): void {
			this._setTargetValue(jsonobject, customData.path, customData.data);
		}
		private _setTargetValue(targetObject: {}, itemPath: string, value: string | number | {}): void {
			if (!itemPath) return undefined;

			// 점 표기법과 대괄호 표기법을 모두 '.' 기준으로 통일
			const normalizedPath = itemPath
				.replace(/\[(\d+)\]/g, '.$1')         // 숫자 인덱스 [0] => .0
				.replace(/\["([^"]+)"\]/g, '.$1')     // ["key"] => .key
				.replace(/\['([^']+)'\]/g, '.$1')     // ['key'] => .key
				.replace(/^\./, '');                  // 처음에 .이 붙는 경우 제거

			const keys = normalizedPath.split('.');

			let current: any = targetObject;
			let length: number = keys.length;
			for (let i: number = 0; i <= (length - 1); i++) {
				let key: string = keys[i];
				if (i == length - 1) {
					current[key] = value;
				} else {
					current = current[key];
				}
			}
		}

		private _getAvailableStates(payload: PayloadType): data.tabledata.RowState[] {
			let availableStates: data.tabledata.RowState[] = [
				data.tabledata.RowState.INSERTED,
				data.tabledata.RowState.UPDATED,
				data.tabledata.RowState.DELETED
			];
			if (payload === PayloadType.all) {
				availableStates[availableStates.length] = data.tabledata.RowState.UNCHANGED;
			}
			return availableStates;
		}

		private _getDataSetOriginalColumnIdx(dataSet: data.DataCollection): { [key: string]: number } {
			let columnNames: string[] = dataSet.getColumnNames(data.header.HeaderType.ORIGINAL_COLUMN);
			let colNmIdx: { [key: string]: number } = {};
			columnNames.forEach((colNm: string, index: number, names: string[]) => {
				let colIdx: number = dataSet._getColumnIndex(colNm);
				colNmIdx[colNm] = colIdx;
			});

			return colNmIdx;
		}

		private _applyAdditionalParam(childObject: {}, additionalParam: { [key: string]: string }): void {
			if (additionalParam) {
				for (let key in additionalParam) {
					let value: string = additionalParam[key];
					if (value == null) {
						childObject[key] = "";
					} else {
						childObject[key] = value;
					}
				}
			}
		}

	}

}