

namespace cpr.controls.internal {
	/**
	 * @private
	 */
	export class VirtualVScrollbar implements IVirtualVScrollbar {
		private _vscrollbar: IVirtualVScrollbar;


		constructor(scrollPane: internal.IVirtualScrollPane) {
			this._vscrollbar = new CustomVScrollbar(scrollPane);
		}

		public _getWidth(): number {
			return this._vscrollbar._getWidth();
		}

		public _getScrollTop(): number {
			return this._vscrollbar._getScrollTop();
		}

		public _setScrollTop(scrollTop: number): void {
			this._vscrollbar._setScrollTop(scrollTop);
		}

		public _createScrollbar(contentScrollTop: number, contentHeight: number): ufc.ElementShape {
			return this._vscrollbar._createScrollbar(contentScrollTop, contentHeight);
		}
	}
}