namespace cpr {
	/**
	 * 지역에 대한 데이타 설정입니다.
	 * @private
	*/
	export interface LocaleData {
		dateTime?: ILocaleDateTime
		dateMaskLabel?: ILocaleDateMaskLabel
		// https://developer.apple.com/design/human-interface-guidelines/right-to-left
		// rtl:boolean
		number?: ILocaleNumber
	}

	/**
	 * 지역 정보를 정의 할 때 사용하는 인터페이스입니다.
	 * @private
	 */
	export interface DefinableLocaleData extends LocaleData {
		/**
		 * 부모 locale을 설정합니다. 정의되지 않은 속성들은 부모 locale에서 참조합니다.
		 * 
		 * ex) "en-custom" locale의 부모 locale은 "en-US" 입니다.
		 */
		parentLocale?: string
	}

	/**
	 * @private
	 */
	export interface LocalePropertyProvider {
		_getProperty(getter: (localeData: LocaleData) => any): any;
		_delegateLocale(delegate: (locale: string) => any): any;
	}

	/**
	 * 지역 정보를 관리합니다.
	 * @noinstance
	 * @private
	 */
	export class Locale implements LocaleData, LocalePropertyProvider {

		private _data: DefinableLocaleData;
		private _identifier: string;
		private _dateTime: LocaleDateTime;
		private _dateMaskLabel: LocaleDateMaskLabel;
		private _numberFormat: LocaleNumber;

		/**
		 * @private
		 * @param locale 
		 * @param data 
		 */
		constructor(locale: string, data: DefinableLocaleData) {
			this._data = data;
			this._identifier = locale;
			this._dateTime = new LocaleDateTime(this);
			this._dateMaskLabel = new LocaleDateMaskLabel(this);
			this._numberFormat = new LocaleNumber(this);
		}

		public get identifier(): string {
			return this._identifier;
		}

		public get dateTime(): LocaleDateTime {
			return this._dateTime;
		}

		public get dateMaskLabel(): LocaleDateMaskLabel {
			return this._dateMaskLabel;
		}

		public get number(): LocaleNumber {
			return this._numberFormat;
		}

		public _update(data: LocaleData) {
			this._data = this._mergeLocaleData(this._data, data);
		}

		public _delegateLocale(delegate: (locale: string) => any): any {
			return delegate(this.identifier) ?? this._getAltLocale()?._delegateLocale(delegate);
		}

		public _getProperty(getter: (localeData: LocaleData) => any): any {
			return getter(this._data) ?? this._getAltLocale()?._getProperty(getter);
		}

		private _mergeLocaleData(target: LocaleData, source: LocaleData) {
			for (const key in source) {
				if (key == "parentLocale") {
					continue;
				}
				if (typeof source[key] == "object") {
					if (target[key] == null) {
						target[key] = {};
					}
					this._mergeLocaleData(target[key], source[key]);
				}
				else {
					target[key] = source[key];
				}
			}
			return target;
		}

		/**
		 * 로케일 매니저 및 시스템에서 parentLocale 이름으로 찾아 반환합니다.
		 * parentLocale이 없는 경우 현재 로케일 이름으로 시스템 Locale을 찾아 반환합니다.
		 * 시스템 locale이 없는 경우 기본 locale 이름으로 Locale을 반환합니다.
		 */
		public _getAltLocale(): Locale {
			if (this._data.parentLocale) {
				return LocaleManager.INSTANCE._findLocaleData(this._data.parentLocale);
			}
			return LocaleManager.INSTANCE._getSystemLocaleData(this.identifier) ?? LocaleManager.INSTANCE._findLocaleData(SystemLocale._getDefaultLocale());
		}

	}

	/**
	 * @noinstance
	 * @private
	 */
	export class SubLocale implements LocalePropertyProvider {
		protected _parent: LocalePropertyProvider;
		constructor(parent: LocalePropertyProvider) {
			this._parent = parent;
		}

		public _getProperty(getter: (localeData: LocaleData) => any): any {
			return this._parent._getProperty(getter);
		}
		public _delegateLocale(delegate: (locale: string) => any): any {
			return this._parent._delegateLocale(delegate);
		}
	}
}