// 내부 개발자 전용 플랫폼 관련 유틸리티를 함수들을 이곳에 위치 하십시오.

namespace cpr {

	/**
	 * 주어진 좌표(페이지 기준)에 존재하는 모든 Element를 얻습니다. 가장 위에 표시되는 순서로 반환 합니다.
	 */
	export function _elementsFromPoint(x: number, y: number): HTMLElement[] {
		if (document["msElementsFromPoint"]) {
			let nodeList = document["msElementsFromPoint"](x, y) as NodeList;
			if (!nodeList) {
				return [];
			} else {
				return _toArray(nodeList) as HTMLElement[];
			}
		} else {
			return (document.elementsFromPoint(x, y) || []) as HTMLElement[];
		}
	}

	/**
	 * 주어진 좌표(페이지 기준)에 존재하는 모든 컨트롤들을 얻습니다. 가장 위에 표시되는 순서로 반환 합니다.
	 */
	export function _controlsFromPoint(x: number, y: number, app?: core.AppInstance) {
		let rootApps = app ? [app] : core.Platform.INSTANCE.getAllRunningAppInstances().filter(it => {
			return it.isUDCInstance() === false && it.isRootAppInstance();
		});

		let elements = _elementsFromPoint(x, y);
		let result: controls.UIControl[] = [];
		elements.forEach(it => {
			let controlUUID = ufc.NodeUUIDMapper.INSTANCE._findClosestControlUUID(it);
			if (!controlUUID) {
				return;
			}

			let control: controls.Control = null;
			appLoop: for (let eachRootApp of rootApps) {
				control = eachRootApp._lookupDrillDownByUUID(controlUUID) as controls.Control;
				if (control) {
					break appLoop;
				}
			}

			if (control instanceof controls.UIControl && result[result.length - 1] !== control) {
				result[result.length] = control;
			}
		});
		return result;
	}

	export function _isDataControl(control: controls.Control, includeProtocols = true) {
		if (control instanceof data.DataCollection) {
			return true;
		}
		if (control instanceof data.DataMap) {
			return true;
		}
		if (includeProtocols && control instanceof protocols.AbstractSubmission) {
			return true;
		}

		return false;
	}

	/**
	 * @returns 런타임이 스튜디오 내부 미리보기 탭 내에서 실행중인지 여부
	 */
	export function _isExBuilderPreviewEditor() {
		return !!window["___syslog"];
	}

	/**
	 * @returns 콘솔에 스타일을 적용할 수 있는지 여부
	 */
	export function _canUseStylizedConsole() {
		switch (_detectBrowser().name) {
			case "ie":
			case "edge": {
				return false;
			}
			default: {
				return !_isExBuilderPreviewEditor();
			}
		}
	}

	export function _isTouchEvent(e: UIEvent): e is TouchEvent | events.CTouchEvent {
		// 데스크탑 사파리에는 터치 이벤트 클래스 자체가 존재하지 않으므로 먼저 체크해야 합니다.
		return e instanceof events.CTouchEvent || (typeof TouchEvent == "function" && e instanceof TouchEvent);
	}

	export function _getCoords(elem: any): { top: number, left: number, right: number, bottom: number } {
		let rect: geometry.Rectangle = _getUnscaledClientRect(geometry.Rectangle.clientBoundsOf(elem));

		let body = document.body;
		let docEl = document.documentElement;

		let scrollTop = _getUnscaledViewportScroll(window.pageYOffset || docEl.scrollTop || body.scrollTop);
		let scrollLeft = _getUnscaledViewportScroll(window.pageXOffset || docEl.scrollLeft || body.scrollLeft);

		let clientTop = docEl.clientTop || body.clientTop || 0;
		let clientLeft = docEl.clientLeft || body.clientLeft || 0;
		let clientWidth = docEl.clientWidth || body.clientWidth || 0;
		let clientHeight = docEl.clientHeight || body.clientHeight || 0;

		let top = rect.top + scrollTop - clientTop;
		let left = rect.left + scrollLeft - clientLeft;
		let right = clientWidth - rect.right;
		let bottom = clientHeight - rect.bottom;

		return { top: Math.round(top), left: Math.round(left), right: Math.round(right), bottom: Math.round(bottom) };
	}

	export function _isAlive<T extends resources.IDisposable>(obj: T): boolean {
		return obj != null && !obj.disposed;
	}

	export function _performIfAlive<T extends resources.IDisposable>(obj: T, handler: (obj: T) => void): void {
		if (_isAlive(obj))
			handler(obj);
	}

	export function _evaluateIfAlive<T extends resources.IDisposable, R>(obj: T, fallback: R, handler: (obj: T) => R): R {
		return _isAlive(obj)
			? handler(obj)
			: fallback;
	}

}