namespace cpr.expression {
	let log = utils.Logger.forTopic("expression")._createBindedLoggerFunction({
		updator: it => log = it
	});

	export interface _ILookupProvider_ {
		lookup(id: string): core.Identifiable;
		readonly targetMediaName: string;
	}

	/**
	 * 표현식 평가 오류를 가리키는 값 상수.
	 * @private
	 */
	export const ERROR_VALUE = new String("ERROR");
	const MAX_CACHE_SIZE = 50;

	function _isErrorValue(value: any) {
		return value === ERROR_VALUE;
	}

	let INSTANCE: ExpressionEngine;

	/**
	 * @private
	 */
	let _builtInOperators: { [key: string]: (a: any, b: any) => any } = {
	}

	/**
	 * 
	 * @private
	 * @param operator 
	 */
	function getBuiltInOperator(operator: string): (a: any, b: any) => any {
		if (!_builtInOperators[operator]) {
			_builtInOperators[operator] = new Function("a", "b", `return a ${operator} b;`) as (a: any, b: any) => any;
		}
		return _builtInOperators[operator]
	}


	class _Compilation {
		private varCounter = 1;
		private variables: string[];
		private src: string;
		private engine: ExpressionEngine;
		private compileStack: { [key: string]: string }[] = []

		constructor(engine: ExpressionEngine, src: string) {
			this.engine = engine;
			this.src = src ? src.trim() : null;

			this.varCounter = 1;
			this.variables = [];
		}

		run(): CompiledExpressionFunction | CompiledExpressionFunction[] {
			let result: CompiledExpressionFunction[] = [];
			utils.tryCatch({
				do: () => {
					let asts = cpr.core.ParseKit.expression.parse(this.src);

					let indenter = (it: string) => `\t${it}`;

					asts.forEach((it: any) => {
						this.beginCompile();
						let expression = this.compileAST(it)
						let codes = [
							"self = self || {};",
							"var __engine = cpr.expression.ExpressionEngine.INSTANCE;",
							"var __getProperty = __engine.getProperty.bind(__engine);",
							"var __op = __engine.applyOperator.bind(__engine);",
							"var __func = null;"
						]
							.concat(this.variables)
							.concat([
								`var result = ${expression};`,
								`return result;`
							]);

						let eachFunction = new Function("self", codes.map(indenter).join("\n")) as CompiledExpressionFunction;
						eachFunction.sortHint = it.sortHint ? it.sortHint.toLowerCase() : "asc";
						result.push(eachFunction);
						this.endCompile();
					});
				},

				catch: (e: any) => {
					if (e.location) {
						console.error(`The expression has syntax an error(line: ${e.location.start.line}, col:${e.location.start.column}), ${e.message}`)
					} else {
						console.error(`The expression has syntax an error, ${e.message}`)
					}

					if (e.location && _canUseStylizedConsole()) {
						let decoratedSrc = this.src.substring(0, e.location.start.offset) + "%c" + this.src.substring(e.location.start.offset, e.location.end.offset) + "%c" + this.src.substring(e.location.end.offset);
						console.log(decoratedSrc, "text-decoration: underline; color:red;", "");
					} else {
						console.log(this.src);
					}

					result[0] = () => {
						return this.src;
					};
					result[0].syntaxError = e;
				},

				_report: true,
				_context: exceptions.ErrorContext.EXPRESSION
			})

			return result.length > 1 ? result : result[0];
		}

		private beginCompile() {
			this.varCounter = 1;
			this.variables = [];
		}

		private endCompile() {
			this.varCounter = 1;
			this.variables = [];
		}


		private lookUpIdentifier(id: string) {
			if (this.compileStack.length > 0) {
				let frameValue = this.compileStack[this.compileStack.length - 1][id];
				if (frameValue !== undefined) {
					return frameValue
				}
			}
			let func = this.engine.getFunction(id);
			if (func !== undefined) {
				return `__engine.getFunction("${id}")`;
			}
			let constant = this.engine.getConstant(id);
			if (constant !== undefined) {
				return `__engine.getConstant("${id}")`;
			}

			return undefined;
		}

		private compileAST(ast: any): string {
			if (ast.nested) {
				return `(${this.doCompileAST(ast)})`
			} else {
				return this.doCompileAST(ast);
			}
		}

		private pushVar(value: string): string {
			let varName = `v${this.varCounter++}`;
			this.variables.push(`var ${varName} = ${value};`);
			return varName;
		}

		private doCompileAST(ast: any): string {
			switch (ast.type) {
				case "Literal": {
					if (typeof ast.value == "string") {
						return ast.value;
					}
					else {
						return `${ast.value}`;
					}
				}

				// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/5900
				case "ArrayExpression": {
					let comps = ast.components as any[];
					return "[" + comps.map(it => {
						return this.doCompileAST(it)
					}).join(", ") + "]";
				}

				// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/5900
				case "JSONExpression": {
					return "{" + ast.properties.map(it => {
						return `${JSON.stringify(it.name)}: ${this.doCompileAST(it.value)}`
					}).join(", ") + "}";
				}

				case "LogicalExpression":
				case "BinaryExpression": {
					switch (ast.operator) {
						case "*=": {
							let left = this.pushVar(`String(${this.compileAST(ast.left)} || "")`);
							let right = this.pushVar(`String(${this.compileAST(ast.right)} || "")`);
							return `(${left}.indexOf(${right}) !== -1)`;
						}

						case "^=": {
							let left = this.pushVar(`String(${this.compileAST(ast.left)} || "")`);
							let right = this.pushVar(`String(${this.compileAST(ast.right)} || "")`);
							return `(${left}.indexOf(${right}) === 0)`;
						}

						case "$=": {
							let left = this.pushVar(`String(${this.compileAST(ast.left)} || "")`);
							let right = this.pushVar(`String(${this.compileAST(ast.right)} || "")`);
							return `(${left}.substr(-${right}.length) == ${right})`;
						}

						default: {
							return `__op("${ast.operator}", ${this.compileAST(ast.left)}, ${this.compileAST(ast.right)})`;
						}
					}
				}

				case "Identifier": {
					let lookup = this.lookUpIdentifier(ast.name);
					if (lookup !== undefined) {
						return lookup;
					} else {
						return `__getProperty(self, "${ast.name}")`;
					}
				}

				case "CallExpression": {
					let args = ast.arguments.map((it: any) => this.compileAST(it));
					let func: string = this.compileAST(ast.callee);
					return `((__func = ${func}) ? __func(${args.join(", ")}) : null)`;
				}

				case "UnaryExpression": {
					if (ast.prefix) {
						return `${ast.operator}${this.compileAST(ast.argument)}`;
					} else {
						return `${this.compileAST(ast.argument)}${ast.operator}`;
					}
				}

				case "MemberExpression": {
					return `__getProperty(${this.compileAST(ast.object)}, "${ast.property}")`;
				}

				case "ThisExpression": {
					return "self";
				}

				case "ConditionalExpression": {
					return `${this.compileAST(ast.test)} ? ${this.compileAST(ast.consequent)} : ${this.compileAST(ast.alternate)}`
				}

				case "SwitchExpression": {
					if (ast.input) {
						this.compileStack.push({
							"it": "input",
							"self": "input"
						})
					}

					let ifStatements: string[] = []

					ast.cases.forEach((each: any, idx: number) => {
						let conditions: any[] = each.conditions
						let compiledConditions: string[] =
							conditions.map(it => {
								if (it.type == "CaseCondition") {
									return `(input == ${this.compileAST(it.condition)})`
								} else {
									return `(${this.compileAST(it.condition)})`
								}
							})
						let checkExp = idx === 0 ? "if" : "else if"
						ifStatements = ifStatements.concat([
							`${checkExp} (${compiledConditions.join(" || ")}) {`,
							`return ${this.compileAST(each.value)}`,
							`}`
						])
					})

					if (ast.fallback) {
						if (ifStatements.length === 0) {
							ifStatements = ifStatements.concat([
								`return ${this.compileAST(ast.fallback.value)};`
							])
						}
						else {
							ifStatements = ifStatements.concat([
								`else {`,
								`return ${this.compileAST(ast.fallback)};`,
								`}`
							])
						}
					}

					var result: string[] = []
					result.push(`(function(){`)
					if (ast.input) {
						result.push(`var input = ${this.compileAST(ast.input)};`)
					} else {
						result.push(`var input = undefined;`)
					}

					result = result.concat(ifStatements)
					result.push(`})()`)
					if (ast.input) {
						this.compileStack.pop();
					}

					return result.join("")
				}

				default: {
					console.log(ast.type, ast);
				}
			}
		}
	}

	class OperatorOverload {
		private _subjecType: abstract new (...args: any[]) => Object;
		private _allowedOperandTypes: (string | (abstract new (...args: any[]) => Object))[];
		private _reducer: (a: any, b: any) => any;

		constructor(
			subjecType: abstract new (...args: any[]) => Object,
			allowedOperandTypes: (string | (abstract new (...args: any[]) => Object))[],
			reducer: (a: any, b: any) => any
		) {
			this._subjecType = subjecType;
			this._allowedOperandTypes = allowedOperandTypes;
			this._reducer = reducer;
		}

		canHandle(...operands: any[]) {
			return operands.every(operand => {
				if (operand instanceof this._subjecType) {
					return true;
				}
				return this._allowedOperandTypes.some(expected => {
					if (typeof expected == "string") {
						return typeof operand == expected;
					}
					else if (expected === null) {
						return operand === null;
					}
					else {
						return operand instanceof expected;
					}
				});
			});
		}

		reduce(a: any, b: any): any {
			return this._reducer(a, b);
		}
	}

	/**
	 * 표현식을 컴파일하는 클래스.
	 * 
	 * <pre><code class="js"> //single expression
	 * var fn = cpr.expression.ExpressionEngine.INSTANCE.compile("a + b")
	 * fn({ a: 1, b: 4 })
	 * 
	 * //multiple expression
	 * var fns = cpr.expression.ExpressionEngine.INSTANCE.compile("a + b, a - b")
	 * fns[0]({ a: 1, b: 4 });
	 * fns[1]({ a: 1, b: 4 });
	 * </code></pre>
	 * 
	 * @noinstance
	 */
	export class ExpressionEngine {
		/**
		 * ExpressionEngine Single Tone Object
		 */
		static get INSTANCE(): ExpressionEngine {
			if (!INSTANCE) {
				INSTANCE = new ExpressionEngine();
			}
			return INSTANCE;
		}

		private _operatorOverloadMap: CMap<
			abstract new (...args: any[]) => Object,
			{ [key: string]: OperatorOverload }
		>;

		private _builtInConstantMap: { [key: string]: Function };
		private _builtInFunctionMap: { [key: string]: Function };
		private _constantMap: { [key: string]: Function };
		private _functionMap: { [key: string]: Function };

		private _cache: LimitedCache<string, Function | Function[]> = _createLimitedCache(50, src => {
			return new _Compilation(this, src).run();
		});

		/**
		 * @private
		 */
		constructor() {
			this._operatorOverloadMap = _createMap();
			this._builtInConstantMap = {};
			this._builtInFunctionMap = {};
			this._constantMap = {};
			this._functionMap = {};

			this._publishBuiltInProperties(Math, Math);
			this._registerBuiltInFunction("parseInt", function (input: string) {
				return parseInt(input)
			});

			this._registerBuiltInFunction("parseFloat", function (input: string) {
				return parseFloat(input)
			});


			this._registerBuiltInFunction("Boolean", function (input: any) {
				return Boolean(input)
			});

			this._registerBuiltInFunction("Number", function (input: any) {
				return Number(input)
			});

			this._registerBuiltInFunction("String", function (input: any) {
				return String(input)
			});

			this._registerBuiltInConstant("NaN", NaN)
			this._registerBuiltInConstant("Infinity", Infinity)
			this._registerBuiltInFunction("isNaN", function (input: any) {
				return isNaN(input)
			});
			this._registerBuiltInFunction("isFinite", function (input: any) {
				return isFinite(input)
			});
			this._registerBuiltInFunction("encodeURI", encodeURI);
			this._registerBuiltInFunction("encodeURIComponent", encodeURIComponent);
			this._registerBuiltInFunction("decodeURI", decodeURI);
			this._registerBuiltInFunction("decodeURIComponent", decodeURIComponent);
			this._publishBuiltInProperties(BuiltInProperties.prototype, new BuiltInProperties());
		}

		/**
		 * 상수를 등록합니다.
		 */
		public registerConstant(name: string, value: any) {
			this._constantMap[name] = value;
		}

		/**
		 * 함수를 등록합니다.
		 */
		public registerFunction(name: string, fn: any) {
			this._functionMap[name] = fn;
		}

		private _publishBuiltInProperties(typeObject: Object, obj: Object) {
			Object.getOwnPropertyNames(typeObject).forEach(name => {
				if (name == "constructor") {
					return;
				}
				let descriptor = Object.getOwnPropertyDescriptor(typeObject, name);
				let value = descriptor.value;
				if (typeof value == "function") {
					this._registerBuiltInFunction(name, value);
				} else if (descriptor.get !== undefined) {
					this._registerBuiltInConstant(name, () => obj[name]);
				} else {
					this._registerBuiltInConstant(name, obj[name]);
				}
			});
		}
		/**
		 * @private
		 * 빌트인 상수를 등록합니다.
		 */
		public _registerBuiltInConstant(name: string, value: any) {
			if (typeof value == "function") {
				Object.defineProperty(this._builtInConstantMap, name, {
					get() {
						return value();
					},
				});
			} else {
				this._builtInConstantMap[name] = value;
			}
		}
		/**
		 * @private
		 * 빌트인 내장 함수를 등록합니다.
		 */
		public _registerBuiltInFunction(name: string, fn: any) {
			this._builtInFunctionMap[name] = fn;
		}

		/**
		 * 상수의 값을 얻습니다.
		 */
		public getConstant(name: string) {
			let userDefinedConstant = this._constantMap[name]
			if (userDefinedConstant !== undefined) {
				return userDefinedConstant
			}
			else {
				return this._builtInConstantMap[name]
			}
		}

		/**
		 * 등록된 함수를 얻습니다.
		 */
		public getFunction(name: string) {
			let userDefinedFunction = this._functionMap[name]
			if (userDefinedFunction !== undefined) {
				return userDefinedFunction
			}
			else {
				return this._builtInFunctionMap[name]
			}
		}
		/**
		 * 등록된 모든 연산자의 해제합니다.
		 */
		public unreigisterAllOperators() {
			this._operatorOverloadMap.clear();
		}
		private _getComputedProperty(obj: any, property: string): any {
			if (_isErrorValue(obj) || _isErrorValue(property)) {
				return ERROR_VALUE;
			}
			if (obj === undefined || obj === null) {
				return undefined;
			}
			if (property == null) {
				return null;
			}
			let result = undefined;

			let context = obj as EvaluationContext;
			if (context._getExpressionOnlyProperty instanceof Function) {
				result = context._getExpressionOnlyProperty(property);
				if (result !== undefined) {
					return result;
				}
			}

			// ID 셀렉터 및 앱속성 처리
			if (property.indexOf("#") === 0 || property.indexOf("@") === 0) {
				let lookupProvider: _ILookupProvider_ = null;
				if (obj instanceof controls.layouts.Layout) {
					lookupProvider = obj._getOwner()?.getAppInstance();
				}
				if (obj instanceof controls.Control) {
					lookupProvider = obj.getAppInstance();
				}
				if (context["_getExpressionIDLookupProvider"] instanceof Function) {
					lookupProvider = context._getExpressionIDLookupProvider();
				}
				if (lookupProvider) {
					let propertyName: string = property.substring(1);
					if (property.indexOf("#") === 0) { // ID 셀렉터 처리

						result = lookupProvider.lookup(propertyName);

					} else if (lookupProvider instanceof core.AppInstance) { // 앱 속성 처리.
						result = lookupProvider.getAppProperty(propertyName)
						if (result === undefined) {
							// 속성이 없으면 undefined가 반환되어야 다음 단계로 진행되기 때문에 속성이 없을때 null을 반환하지 않도록 해야한다.
							result = lookupProvider._getModuleProperty(propertyName);
						}
						if (!result && lookupProvider.hasAppMethod(propertyName)) {
							result = function () {
								let args = _toArray(arguments);
								return (lookupProvider as core.AppInstance).applyAppMethod(propertyName, args);
							};
						}
					}
				}

				if (result !== undefined) {
					return result;
				}
			}

			// 속성 / 메소드 처리
			let propertyValue: any = obj[property];
			if (propertyValue !== undefined) {
				if (propertyValue instanceof Function) {
					let providesFunctions: boolean = true;
					if (context["_publishMethodsToExpression"] instanceof Function) {
						providesFunctions = context._publishMethodsToExpression();
					}
					if (providesFunctions) {
						result = propertyValue.bind(obj);
					}
				} else {
					let providesProperties: boolean = true;
					if (context["_publishPropertiesToExpression"] instanceof Function) {
						providesProperties = context._publishPropertiesToExpression()
					}
					if (providesProperties) {
						result = propertyValue;
					}
				}
				if (result !== undefined) {
					return result;
				}
			}

			if (context._getExpressionDelegates instanceof Function) {
				let delegates: any[] = context._getExpressionDelegates();
				if (delegates && delegates.length > 0) {
					for (var each of delegates) {
						if (each == null) {
							continue;
						}
						let eachValue = this._getComputedProperty(each, property);
						if (eachValue !== undefined) {
							result = eachValue;
							break;
						}
					}
				}
			}

			if (result === undefined && property === "self") {
				return obj;
			}
			return result;
		}

		/**
		 * 익스프레션 엔진에 등록된 액세서를 이용하여, 주어진 객체의 속성을 얻습니다.
		 * @param obj 객체
		 * @param property 속성 이름
		 */
		public getProperty(obj: any, property: string) {
			let result = this._getComputedProperty(obj, property);
			if (utils.Logger.forTopic("expression").isActivated()) {
				// 유효하지 않은 속성에 대해 확인은 성능에 부담이 될 수 있지만, 디버깅 편의성을 위해 로그를 추가.
				if (result === undefined) {
					let appInstance: core.AppInstance = null;
					let isControl = obj instanceof controls.Control;
					let isLayout = obj instanceof controls.layouts.Layout;
					if (isLayout) {
						appInstance = obj._getOwner()?.getAppInstance();
					} else if (isControl) {
						appInstance = obj.getAppInstance();
					}
					if (appInstance != null || (isControl == false && isLayout == false)) {
						log(`Property not found: ${property}`);
					}
				}
			}
			return result;
		}
		/**
		 * 표현식을 컴파일하여 일반 자바 스크립트 함수로 만듭니다.
		 * <pre><code>
		 * var fn = cpr.expression.ExpressionEngine.INSTANCE.compile("min + max") 
		 * fn(numberEditor)
		 * </code></pre>
		 * @param src 컴파일할 소스
		 */
		public compile(src: expression_string): Function | Function[] {
			return this._cache.get(src);
		}

		/**
		 * 연산자 오버로딩을 등록합니다. 연산자 오버로딩은 현재 2항 연산자(Binary Expression)만 지원합니다.
		 * @param type 연산자를 오버로딩할 객체의 타입
		 * @param operator 오버로딩할 연산자
		 * @param reducer 연산을 수행할 리듀서 함수. 리듀서 함수는 2개의 인자를 받으며, 최소 둘 중 하나가 주어진 <code>type</code>의 객체입니다.
		 */
		public registerOperator(type: Function, operator: string, reducer: (a: any, b: any) => any) {
			this._registerOperator({
				type: type as (abstract new (...args: any[]) => Object),
				operator: operator,
				reducer: reducer,
				allowedOperandTypes: ["number", "object", "boolean", "string"]
			});
		}



		/**
		 * 연산자 오버로딩을 등록합니다. 연산자 오버로딩은 현재 2항 연산자(Binary Expression)만 지원합니다.
		 */
		public _registerOperator(options: {
			/** 연산 대상 주제 타입 */
			type: abstract new (...args: any[]) => Object,
			/** 연산자 */
			operator: string,
			/** 연산 구현 */
			reducer: (a: any, b: any) => any,
			/** 피연산자에 허용되는 타입 목록. */
			allowedOperandTypes?: (primitive_type | null | (abstract new (...args: any[]) => Object))[]
		}) {
			options = _assign({
				allowedOperandTypes: ["number", "object", "boolean", "string"]
			}, options)

			let entries = this._operatorOverloadMap.get(options.type)
			if (!entries) {
				entries = {};
				this._operatorOverloadMap.set(options.type, entries)
			}
			entries[options.operator] = new OperatorOverload(
				options.type,
				options.allowedOperandTypes,
				options.reducer
			);
		}

		/**
		 * 익스프레션 엔진에 등록된 오퍼레이터를 적용합니다.
		 * @param operator 오퍼레이터 기호
		 * @param operandA 오퍼레이터 앞의 값
		 * @param operandB 오퍼레이터 뒤의 값
		 */
		public applyOperator(operator: string, operandA: any, operandB: any): any {
			if (_isErrorValue(operandA) || _isErrorValue(operandB)) {
				return ERROR_VALUE;
			}

			let overload = this._findOperatorOverload(operator, operandA, operandB);
			if (overload) {
				return overload.reduce(operandA, operandB)
			} else {
				return getBuiltInOperator(operator)(operandA, operandB);
			}
		}

		private _findOperatorOverload(operator: string, operandA: any, operandB: any): OperatorOverload {
			let result: OperatorOverload = null;

			// 리듀서 검색
			[operandA, operandB].filter(it => {
				return typeof it == "object" && it !== null;
			}).some(obj => {
				let entry = this._operatorOverloadMap.get(obj.constructor);
				let overload = entry?.[operator];
				if (overload && overload.canHandle(operandA, operandB)) {
					result = overload;
					return true;
				} else {
					return false;
				}
			});

			return result;
		}
	}
}