

namespace cpr.protocols.response {
	/**
	 * @private
	 */
	export class DefaultResponseParserFactory implements ResponseParserFactory {
		private static _instance: DefaultResponseParserFactory;

		public static get INSTANCE(): DefaultResponseParserFactory {
			if (!DefaultResponseParserFactory._instance) {
				DefaultResponseParserFactory._instance = new DefaultResponseParserFactory();
			}
			return DefaultResponseParserFactory._instance;
		}

		private _JSON_PARSER: JSONResponseParser = new JSONResponseParser();
		private _SCRIPT_PARSER: ScriptResponseParser = new ScriptResponseParser();
		private _TSV_PARSER: TSVResponseParser = new TSVResponseParser();
		private _TSV_BLOB_PARSER: TSVBlobResponseParser = new TSVBlobResponseParser();
		private _DOWNLOAD_PARSER: FileDownloadParser = new FileDownloadParser();


		constructor() {
		}

		public _getScriptParser(): ScriptResponseParser {
			return this._SCRIPT_PARSER;
		}

		public _getDownloadParser(): FileDownloadParser {
			return this._DOWNLOAD_PARSER;
		}

		public _getContentType(xhr: XMLHttpRequest): string {
			let contentType: string = null;
			let disposition: string = xhr.getResponseHeader('Content-Disposition');
			if (disposition && disposition.indexOf('attachment') !== -1) {
				contentType = disposition; /* filedownload */
			} else {
				contentType = xhr.getResponseHeader("Content-Type");
			}

			if (contentType) {
				// to lower case
				contentType = contentType.toLowerCase();

				// parameter 제거
				if (contentType.indexOf(";") > -1) {
					contentType = contentType.substring(0, contentType.indexOf(";"));
				}
				contentType = contentType.trim();
			}

			return contentType;
		}

		public _isFileDownloadResponse(xhr: XMLHttpRequest): boolean {
			let contentType: string = this._getContentType(xhr);
			return contentType == "attachment";
		}

		public getResponseParser(xhr: XMLHttpRequest, forceContentType: string, defaultContentType: string): ResponseParser {
			forceContentType = forceContentType ? forceContentType : this._getContentType(xhr);
			if ((forceContentType == null || forceContentType == "") && defaultContentType) {
				forceContentType = defaultContentType;
			}
			let responseType: string = xhr.responseType;
			let responseParser: ResponseParser = this._getContentParser(forceContentType, responseType);

			return responseParser;
		}
		// public getResponseParser(xhr: XMLHttpRequest, forceContentType: string, defaultContentType: string): ResponseParser {
		// 	forceContentType = forceContentType ? forceContentType : this._getContentType(xhr);
		// 	let responseType: string = xhr.responseType;
		// 	let responseParser: ResponseParser = this._getContentParser(forceContentType, responseType);

		// 	if (responseParser == null && defaultContentType) {
		// 		responseParser = this._getContentParser(defaultContentType, responseType);
		// 	}

		// 	return responseParser;
		// }

		public _getContentParser(contentType: string, responseType: string): ResponseParser {
			let responseParser: ResponseParser = null;
			if (contentType) {
				switch (contentType) {
					case "none": {
						break;
					}
					case Submission.MEDIA_JSON: {
						responseParser = this._JSON_PARSER;
						break;
					}
					case Submission.MEDIA_SCRIPT: {
						responseParser = this._SCRIPT_PARSER;
						break;
					}
					case Submission.MEDIA_TSV: {
						if (responseType && responseType.toLowerCase() == "blob") {
							responseParser = this._TSV_BLOB_PARSER;
						} else {
							responseParser = this._TSV_PARSER;
						}
						break;
					}
					case "attachment": {
						responseParser = this._DOWNLOAD_PARSER;
						break;
					}
					default: {
						responseParser = null;
					}
				}
				return responseParser;

			}

			return responseParser;
		}

	}
}