

namespace cpr.foundation {


	/**
	 * 비동기적으로 처리되는 작업들을 순서대로 처리하는 방법을 제공하는 컴포넌트입니다.
	 */
	export class Workflow {
		private _app: core.AppInstance;
		private _promise: Promise<any>;
		private _report: { id: string, start: number, end: number, time: number, success: boolean }[];
		private _idSeq: number;
		private _debug: boolean;


		constructor(app: core.AppInstance, debug: boolean = false) {
			this._app = app;
			this._idSeq = 1;
			this._report = [];
			this._debug = debug;
		}

		/**
		 * 다음으로 함수를 실행합니다.
		 * <pre><code>
		 * var workflow = new cpr.foundation.Workflow(app);
		 * workflow.exec(function() {
		 *   ... CODE ...
		 * });
		 * </code></pre>
		 * @param func 다음 실행할 함수
		 * @param id 실행할 작업의 명칭(로그 기록을 위해 사용)
		 */
		public exec(func: (value: any) => any, id?: string): Workflow {
			if (func == null) {
				throw new exceptions.IllegalArgumentException("Function is null.");
			}
			if (!id) {
				id = "func-" + this._idSeq++;
			}
			func = this._wrapFunction(id, func);
			this._promise = this._getPromise().then(func);

			return this;
		}

		/**
		 * 다음으로 Submission을 실행합니다.
		 * Submission의 ID가 여러 개 전달되면 병렬로 수행됩니다.
		 * <pre><code>
		 * var workflow = new cpr.foundation.Workflow(app);
		 * workflow.send("submain", "subsub", ...);
		 * </code></pre>
		 * @param submissionIds 다음으로 실행할 Submission의 ID들
		 */
		public send(...submissionIds: (string | protocols.Submission)[]): Workflow {
			this._promise = this._getPromise().then(() => {
				return Promise.all((() => {
					let promises: Promise<any>[] = [];

					submissionIds.forEach((submissionId: string | protocols.Submission) => {
						let submission: protocols.Submission = null;
						if (submissionId instanceof protocols.Submission) {
							submission = submissionId as protocols.Submission;
						} else {
							submission = this._app.lookup(submissionId as string) as protocols.Submission;
						}
						if (submission == null) {
							throw new exceptions.IllegalArgumentException("Submission ID(" + submissionId + ") not found.");
						}
						let func: (resolve: (value: events.CSubmissionEvent) => void, reject: (value: events.CSubmissionEvent) => void) => void = this._wrapSubmission(submission);

						promises[promises.length] = new Promise<any>(func);
					});

					return promises;
				})());
			});

			return this;
		}

		/**
		 * 에러를 처리할 함수를 지정합니다.
		 * <pre><code>
		 * var workflow = new cpr.foundation.Workflow(app);
		 * workflow.exec(...).send(...).err(function(error) {
		 *   console.error(error);
		 * });
		 * </code></pre>
		 * @param func 에러를 처리할 함수
		 */
		public err(func: (error: any) => any): Workflow {
			if (func == null) {
				throw new exceptions.IllegalArgumentException("Function is null.");
			}
			func = this._wrapFunction("errorHandle", func);
			this._promise = this._getPromise().catch(func);

			return this;
		}

		/**
		 * Workflow 실행결과 레포트를 반환합니다.
		 * workflow 호출이 완료되는 시점에는 workflow의 실행이 끝나지 않을 수 있기 때문에
		 * getReport 호출은 workflow의 exec 함수를 통해 호출하는 것이 안전합니다.
		 * <pre><code>
		 * var workflow = new cpr.foundation.Workflow(app);
		 * workflow.exec(...).send(...).exec(...).error(...)
		 * .exec(function() {
		 *   console.log(JSON.stringify(workflow.getReport()));
		 * });
		 * </code></pre>
		 */
		public getReport(): { id: string, start: number, end: number, time: number, success: boolean }[] {
			return this._report;
		}

		private _getPromise(): Promise<any> {
			if (this._promise == null) {
				this._promise = Promise.resolve();
			}

			return this._promise;
		}

		private _logJob(jobId: string, startTime: number, endTime: number, success: boolean): void {
			this._report[this._report.length] = { id: jobId, start: startTime, end: endTime, time: (endTime - startTime), success: success };
		}

		private _wrapFunction(id: string, func: (value: any) => any): (value: any) => any {
			if (this._debug) {
				return (value: any) => {
					let start: number = new Date().getTime();

					try {
						let rtnValue: any = func(value);

						this._logJob(id, start, new Date().getTime(), true);

						return rtnValue;
					} catch (e) {
						this._logJob(id, start, new Date().getTime(), false);
						throw e;
					}
				}
			} else {
				return (value: any) => {
					let rtnValue: any = func(value);
					return rtnValue;
				}
			}
		}

		private _wrapSubmission(submission: protocols.Submission): (resolve: (value: events.CSubmissionEvent) => void, reject: (value: events.CSubmissionEvent) => void) => void {
			if (this._debug) {
				var thenable = (resolve: (value: events.CSubmissionEvent) => void, reject: (value: events.CSubmissionEvent) => void) => {
					let start: number = new Date().getTime();

					submission.addEventListenerOnce("submit-success", (e: events.CSubmissionEvent) => {
						this._logJob("submit-" + submission.id, start, new Date().getTime(), true);
						resolve(e);
					});
					submission.addEventListenerOnce("submit-error", (e: events.CSubmissionEvent) => {
						this._logJob("submit-" + submission.id, start, new Date().getTime(), false);
						reject(e);
					});

					submission.send();
				}
				return thenable;
			} else {
				var thenable = (resolve: (value: events.CSubmissionEvent) => void, reject: (value: events.CSubmissionEvent) => void) => {
					submission.addEventListenerOnce("submit-success", (e: events.CSubmissionEvent) => {
						resolve(e);
					});
					submission.addEventListenerOnce("submit-error", (e: events.CSubmissionEvent) => {
						reject(e);
					});

					submission.send();
				}
				return thenable;
			}
		}

	}
}