namespace cpr {

	type ParameterAssertionContext<Type extends object> = {
		[Prop in keyof Type]: _ShouldContext;
	}

	export function _checkParameters<T extends object>(input: T, assertionCode: (ctx: ParameterAssertionContext<T>) => void) {
		let context: ParameterAssertionContext<T> = {} as any;

		Object.keys(input).forEach(key => {
			context[key] = new _ShouldContext(key, input[key]);
		});
		try {
			assertionCode(context);
		} catch (error) {
			let wrapException = _wrapAsInvalidAPICallException(error, context);
			throw wrapException;
		}
	}

	export type AssertFailedError = {
		_isAssertFailedError: true
		orignError: exceptions.CError;
	};

	export function _isUserError(e: any): e is exceptions.InvalidAPICallException {
		return e instanceof exceptions.InvalidAPICallException;
	}

	export function _wrapAsInvalidAPICallException(reason: exceptions.CError, callContext: object): exceptions.InvalidAPICallException {
		return new exceptions.InvalidAPICallException(reason, callContext);
	}

	class _ShouldContext {
		_name: string;
		_value: any;

		constructor(name: string, value: any) {
			this._name = name;
			this._value = value;
		}

		beNotNull(allowsUndefined = false) {
			let condition = allowsUndefined
				? this._value === null
				: this._value == null;

			if (condition) {
				throw new exceptions.IllegalArgumentException(`${this._name} could not be null.`);
			}
		}

		beTypeOf(...allowedTypes: primitive_type[]) {
			if (allowedTypes.indexOf(typeof this._value) === -1) {
				if (allowedTypes.length === 1) {
					throw new exceptions.IllegalArgumentException(`${this._name} must be ${allowedTypes[0]}.`);
				} else {
					throw new exceptions.IllegalArgumentException(`${this._name} must be one of ${allowedTypes.join(", ")}.`);
				}

			}
		}

		beInstanceOf<T>(constructor: ConstructorOf<T>, className?: string) {
			className ??= constructor.name;
			if (this._value instanceof constructor === false) {
				throw new exceptions.IllegalArgumentException(`${this._name} should be an instnce of ${className}.`);
			}
		}
	}

	export function _logUserError(e: exceptions.InvalidAPICallException): void {
		let contents = _formatUserError(e);
		let obj = {};
		Object.keys(e.callContext).forEach(k => {
			obj[k] = (e.callContext[k] as _ShouldContext)._value;
		});

		console.log(`%c${contents}`, "color:red;", obj);
	}

	function _formatUserError(e: exceptions.InvalidAPICallException): string {
		let stack = exceptions._parseErrorStack(e.cause);

		// TODO 런타임이 cleopatra.js 가 아닌 이름으로 공급될 가능성이 있는지 확인 필요.
		let firstUserStack = stack.findIndex(it => it.fileName && it.fileName.indexOf("cleopatra.js") === -1);
		let lines = _stream(stack).drop(firstUserStack).map(it => it.source).collect();
		lines[0] = `${lines[0]} <--`;
		if (!_isNullOrEmpty(e.cause.message)) {
			lines = [
				`InvaildAPICallError: ${e.cause.message}`,
				`Given arguments: %o`,
				...lines
			];
		}
		return lines.join("\n");
	}


	export class Sample {
		add(a: number, b: number = 4) {
			_checkParameters({ a, b }, ctx => {
				ctx.a.beTypeOf("number");
				ctx.b.beTypeOf("number");

			});

			return a + b;
		}

		add2(a: number, b: number = 4) {
			_checkParameters({ a, b }, ctx => {
				throw new Error("그냥 니가 잘못헀어.");
			});

			return a + b;
		}
	}
}
