// /// <reference path="./CEvent.ts"/>
/// <reference path="../exceptions/exceptions.ts"/>

/// <reference path="./DOMEventWrapper.ts" />


namespace cpr.events {
	/**
	 * select 이벤트 유형
	 */
	export class SelectionEventType {
		/**
		 * Item을 선택하여 선택된 값이 저장되기 전에 발생하는 이벤트.<br>
		 * 다음 이벤트로 selection-change를 발생합니다.
		 */
		public static readonly BEFORECHANGE: string = "before-selection-change";
		/**
		 * Item을 선택하여 선택된 값이 저장된 후에 발생하는 이벤트.
		 */
		public static readonly CHANGE: string = "selection-change";
		/**
		 * Item을 선택하여 선택된 값이 저장되기 전에 발생하는 이벤트.<br>
		 * 다음 이벤트로 selection-change를 발생합니다.
		 */
		public static readonly BEFORE_ITEM_CHANGE: string = "before-item-selection-change";
		/**
		 * Item을 선택하여 선택된 값이 저장된 후에 발생하는 이벤트.
		 */
		public static readonly ITEM_CHANGE: string = "item-selection-change";
	}

	/**
	 * select 이벤트에 대한 옵션
	 */
	export interface CSelectionEventOptions extends CEventOption {
		/**
		 * 이전에 선택된 아이템의 배열.
		 */
		oldSelection: any;
		/**
		 * 새로 선택된 아이템의 배열.
		 */
		newSelection: any;
	}

	/**
	 * item을 select 할 시 발생하는 이벤트.
	 */
	export class CSelectionEvent extends CEvent {

		constructor(options: CSelectionEventOptions)
		/**
		 * select 이벤트를 생성합니다.
		 * @param type 이벤트 유형
		 * @param options 이벤트에 대한 옵션
		 */
		constructor(type: string, options: CSelectionEventOptions)

		/**
		 * 'selection-change' 유형의 이벤트를 생성합니다.
		 * @param options 이벤트 옵션.
		 */
		constructor(options: CSelectionEventOptions)

		constructor() {
			switch (arguments.length) {
				case 1: {
					super(SelectionEventType.CHANGE, arguments[0]);
					break;
				}
				case 2: {
					super(arguments[0], arguments[1]);
					break;
				}
				default: {
					throw new cpr.exceptions.IllegalArgumentException();
				}
			}
		}

		/**
		 * 이전 셀렉션을 반환합니다.
		 * @return 이전에 선택된 아이템의 배열.
		 */
		get oldSelection(): any {
			return this._getOption("oldSelection");
		}

		/**
		 * 새로운 셀렉션을 반환합니다.
		 * @return 새롭게 선택된 아이템의 배열.
		 */
		get newSelection(): any {
			return this._getOption("newSelection");
		}
	}
}