namespace cpr.foundation {
	export class CharRange {
		private _offset: number
		private _length: number

		constructor(offset: number, length: number) {
			this._offset = offset;
			this._length = length;
			if (length < 0) {
				throw new exceptions.IllegalArgumentException(`Length must be greator or equals to 0`);
			}
		}

		/** 시작 인덱스 */
		get offset() { return this._offset; }

		/** 길이 */
		get length() { return this._length; }

		/** 끝 인덱스(종료 문자 인덱스 다음) */
		get end() {
			return this.offset + this.length;
		}

		/** 종료 문자의 인덱스 */
		get stop() {
			return this.offset + this.length - 1;
		}

		/**
		 * 다른 레인지와의 충돌 여부를 얻습니다.
		 * @param other 검사 대상 레인지.
		 * @returns 충돌 여부.
		 */
		intersects(other: CharRange) {
			if (this.stop < other.offset || other.stop < this.offset) {
				return false;
			}
			else {
				return true;
			}
		}

		getIntersection(other: CharRange): CharRange {
			if (this.intersects(other) === false) {
				return null;
			}

			let offset = Math.max(this.offset, other.offset);
			let length = Math.min(this.end - offset, other.end - offset);
			return new CharRange(offset, length);
		}

		contains(other: CharRange) {
			return this.offset <= other.offset && other.stop <= this.stop;
		}
	}
}