/// <reference path="../../layouts/Layout.ts"/>


namespace cpr.controls.gridpart.layout {

	/**
	 * 그리드 내에 포함된 컨트롤의 컨스트레인트
	 */
	export interface GridControlLayoutConstraint extends layouts.Constraint {
		/**
		 * 그리드 영역. (header, detail, footer)
		 */
		region: string;
		/**
		 * 셀 인덱스.
		 */
		cellIndex: number;
		/**
		 * 셀 내 세로 정렬 방법
		 */
		verticalAlign?: layouts.FormVerticalAlign;
		/**
		 * 셀 내 가로 정렬 방법
		 */
		horizontalAlign?: layouts.FormHorizontalAlign;
		/**
		 * 가로 크기. 가로 정렬방법이 가득 채우기인 경우 무시 됩니다.
		 */
		width?: number;
		/**
		 * 세로 크기. 세로 정렬 방법이 가득 채우기인 경우 무시 됩니다.
		 */
		height?: number;
		/**
		 * 상단 여백
		 */
		topSpacing?: number;
		/**
		 * 우측 여백
		 */
		rightSpacing?: number;
		/**
		 * 하단 여백
		 */
		bottomSpacing?: number;
		/**
		 * 좌측 여백
		 */
		leftSpacing?: number;
	}

	/**
	 * @private
	 */
	export class GridControlLayout extends layouts.Layout<GridControlLayoutConstraint> {
		private _context: GridContext;
		private _grid: Grid;

		private _gridRowManager: GridRowManager;

		private _scrollPaneCluster: ScrollPaneCluster;

		private _leftTablePane: TablePane;
		private _centerTablePane: TablePane;
		private _rightTablePane: TablePane;

		private _tempAutoSizeType: layouts.AutoSizeType; // 그려지는 한틱에서만 유효한 AutoSizeType;

		// Grid 각 영역별 넓이 및 높이, width는 region, height는 location으로 관리
		private _dimension: { [key: string]: number } = {};


		constructor(context: GridContext) {
			super();
			this._context = context;
			this._grid = context.getGrid();

			this._gridRowManager = new GridRowManager(context);
		}

		protected _getType(): layouts.LayoutType {
			return layouts.LayoutType.GRIDCONTROL_LAYOUT;
		}

		protected _doUpdateControl(controls: UIControl[]): void {
			controls?.forEach(it => it.redraw());
		}

		public _getTablePane(region: string): TablePane {
			switch (region) {
				case GRIDREGION.LEFT:
					return this._leftTablePane;
				case GRIDREGION.CENTER:
					return this._centerTablePane;
				case GRIDREGION.RIGHT:
					return this._rightTablePane;
			}
			return null;
		}

		public _getSizeComputableCellStyles(): { [key: number]: CellContentProp } {
			return this._gridRowManager._getSizeComputableCellStyles();
		}
		public _getAutoRowHeightCellStyles(): { [key: number]: CellContentProp } {
			return this._gridRowManager._getAutoRowHeightCellStyles();
		}
		public _getRowHeightCacheKey(): string {
			return this._gridRowManager._getRowHeightCacheKey();
		}

		public _addGhostRowClasses(rowClassNames: string[]): void {
			this._gridRowManager._addGhostRowClasses(rowClassNames);
		}

		public _getCellWidthChecker(cellIndex: number, control: UIControl): CellWidthChecker {
			return this._gridRowManager._getCellWidthChecker(cellIndex, control);
		}

		public _getHeaderCellWidth(cellIndex: number, control: UIControl, text: string | ufc.StyledString): number {
			return this._gridRowManager._getGhostCellWidth(cellIndex, control, text, GRIDREGION.HEADER);
		}

		public _getFooterCellWidth(cellIndex: number, control: UIControl, text: string | ufc.StyledString): number {
			return this._gridRowManager._getGhostCellWidth(cellIndex, control, text, GRIDREGION.FOOTER);
		}

		public _getTextContentHeight(cellIndex: number, textContent: string): number {
			return this._gridRowManager._getTextContentHeight(cellIndex, textContent);
		}

		public _getHTMLContentHeight(cellIndex: number, htmlText: string): number {
			return this._gridRowManager._getHTMLContentHeight(cellIndex, htmlText);
		}

		public _getStyledStringContentHeight(cellIndex: number, styledString: (string | ufc.StyledString)): number {
			return this._gridRowManager._getStyledStringContentHeight(cellIndex, styledString);
		}

		public _removeGhostRowClasses(rowClassNames: string[]): void {
			this._gridRowManager._removeGhostRowClasses(rowClassNames);
		}

		/**
		 * Container가 초기화 될 때 호출되는 GridLayout 초기화
		 * @param layoutInfo
		 */
		public _resetGridLayout(): void {
			let layoutInfo: {} = this._grid._getTableInfo();
			this._scrollPaneCluster = new ScrollPaneCluster();

			// create tablepanes
			[GRIDREGION.LEFT, GRIDREGION.CENTER, GRIDREGION.RIGHT].forEach((region: string) => {
				let tablePane: TablePane = null;
				switch (region) {
					case GRIDREGION.LEFT:
						tablePane = new TablePane(GRIDREGION.LEFT, this._context);
						this._leftTablePane = tablePane;
						break;
					case GRIDREGION.CENTER:
						tablePane = new TablePane(GRIDREGION.CENTER, this._context);
						this._centerTablePane = tablePane;
						break;
					case GRIDREGION.RIGHT:
						tablePane = new TablePane(GRIDREGION.RIGHT, this._context);
						this._rightTablePane = tablePane;
						break;
				}

				// tablePane 초기화
				let tableInfos: { band: AbstractGridPart, constraints: GridBandConstraint }[] = layoutInfo[region];
				tablePane._init(tableInfos, this._scrollPaneCluster);
			});

			this._resetRowManager();
		}

		public _getScrollPaneCluster(): ScrollPaneCluster {
			return this._scrollPaneCluster;
		}

		public _jumpRowIndex(targetRowIndex: number): number {
			// offset -1은 의미를 가지므로 0으로 설정
			return this._callJumpPage(-1, 0, targetRowIndex, true);
		}

		public _jumpViewRowIndex(targetRowIndex: number): number {
			// offset -1은 의미를 가지므로 0으로 설정
			return this._callJumpPage(-1, 0, targetRowIndex, false);
		}

		public _jumpPage(srcIndex: number, offset: number): number {
			return this._callJumpPage(srcIndex, offset, -1, true);
		}

		private _callJumpPage(srcIndex: number, offset: number, jumpIndex: number, isDataRow: boolean): number {
			if (this._grid._getRenderer() == null || this._grid._getRenderer().hasDrawn() == false) {
				return -1;
			}
			let eventContent: {
				srcIndex: number
				, offset: number
				, jumpIndex: number
				, jumpedIndex: number
				, isDataRow: boolean
			} = {
				srcIndex: srcIndex
				, offset: offset
				, jumpIndex: jumpIndex
				, jumpedIndex: -1
				, isDataRow: isDataRow
			};
			let movePageEvent: events.CUIEvent = new events.CUIEvent("jumppage", { content: eventContent });

			// event handler가 조인되어 있기 때문에 center에 호출하면 연결된 모든 tablepane에 호출됨.
			if (this._centerTablePane) {
				this._centerTablePane._jumpPage(movePageEvent);
			}

			return eventContent.jumpedIndex;
		}

		public _jumpCellIndex(cellIndex: number): void {
			// TODO grid scroll event check(가로스크롤 이벤트와 세로스크롤 이벤트가 한번에 dispatch 되어야 함)
			if (this._leftTablePane) {
				this._leftTablePane._jumpCellIndex(cellIndex);
			}
			if (this._centerTablePane) {
				this._centerTablePane._jumpCellIndex(cellIndex);
			}
			if (this._rightTablePane) {
				this._rightTablePane._jumpCellIndex(cellIndex);
			}
		}

		public _jumpRowGroupCell(groupCondition: string, vloc: string, cellIndex: number): void {
			// TODO grid scroll event check(가로스크롤 이벤트와 세로스크롤 이벤트가 한번에 dispatch 되어야 함)
			if (this._leftTablePane) {
				this._leftTablePane._jumpRowGroupCell(groupCondition, vloc, cellIndex);
			}
			if (this._centerTablePane) {
				this._centerTablePane._jumpRowGroupCell(groupCondition, vloc, cellIndex);
			}
			if (this._rightTablePane) {
				this._rightTablePane._jumpRowGroupCell(groupCondition, vloc, cellIndex);
			}
		}

		public _jumpHeaderCell(headerCellIndex: number): void {
			if (this._leftTablePane) {
				this._leftTablePane._jumpHeaderCell(headerCellIndex);
			}
			if (this._centerTablePane) {
				this._centerTablePane._jumpHeaderCell(headerCellIndex);
			}
			if (this._rightTablePane) {
				this._rightTablePane._jumpHeaderCell(headerCellIndex);
			}
		}

		public _jumpFooterCell(footerCellIndex: number): void {
			if (this._leftTablePane) {
				this._leftTablePane._jumpFooterCell(footerCellIndex);
			}
			if (this._centerTablePane) {
				this._centerTablePane._jumpFooterCell(footerCellIndex);
			}
			if (this._rightTablePane) {
				this._rightTablePane._jumpFooterCell(footerCellIndex);
			}
		}

		public _readyForRedraw(): void { // 그리드의 각 영역의 크기와 스크롤 정보를 초기화합니다.
			this._scrollPaneCluster._init();

			// 그리드 각 영역의 스크롤정보를 초기화합니다.
			[this._leftTablePane, this._centerTablePane, this._rightTablePane].forEach((tabPane: TablePane) => {
				if (tabPane && tabPane._hasContent() == true) {
					tabPane._readyForRedraw();
				}
			});
		}
		public _initScrollTop(scrollTop: number): void {
			[this._leftTablePane, this._centerTablePane, this._rightTablePane].forEach((tabPane: TablePane) => {
				if (tabPane && tabPane._hasContent() == true) {
					tabPane._initScrollTop(scrollTop);
				}
			});
			this._scrollPaneCluster._initScrollTop(scrollTop);
		}
		public _initScrollLeft(scrollLeft: number): void {
			[this._leftTablePane, this._centerTablePane, this._rightTablePane].forEach((tabPane: TablePane) => {
				if (tabPane && tabPane._hasContent() == true) {
					tabPane._initScrollLeft(scrollLeft);
				}
			});
			this._scrollPaneCluster._initScrollLeft(scrollLeft);
		}
		public _initRegionScrollLeft(region: string, scrollLeft: number): void {
			switch (region) {
				case GRIDREGION.LEFT: {
					this._leftTablePane._initScrollLeft(scrollLeft);
					break;
				}
				case GRIDREGION.CENTER: {
					this._centerTablePane._initScrollLeft(scrollLeft);
					break;
				}
				case GRIDREGION.RIGHT: {
					this._rightTablePane._initScrollLeft(scrollLeft);
					break;
				}
			}
		}

		private _computeLayoutStyle(): boolean {
			// layout dimension 설정
			let renderer: ufc.ControlRenderer = this._grid._getRenderer();
			let rootNode: HTMLElement = renderer.getRootNode();
			let rootSize: ElSize = GridUtil._getInnerSize(rootNode);

			let headerSize: ElSize = { ow: 0, oh: 0, iw: 0, ih: 0, mh: 0 };
			let topSize: ElSize = { ow: 0, oh: 0, iw: 0, ih: 0, mh: 0 };
			let middleSize: ElSize = { ow: 0, oh: 0, iw: 0, ih: 0, mh: 0 };
			let bottomSize: ElSize = { ow: 0, oh: 0, iw: 0, ih: 0, mh: 0 };
			let footerSize: ElSize = { ow: 0, oh: 0, iw: 0, ih: 0, mh: 0 };

			// width
			{
				let centerMidd: HTMLElement = renderer.getNamedNode(GRIDREGION.CENTER + "-" + GRIDREGION.MIDDLE);
				middleSize = GridUtil._getInnerSize(centerMidd);

				this._setRegionWidth(GRIDREGION.CENTER, GRIDREGION.MIDDLE, middleSize.iw);
			}
			if (this._context.isEnabledPart(GRIDREGION.LEFT)) {
				let leftMidd: HTMLElement = renderer.getNamedNode(GRIDREGION.LEFT + "-" + GRIDREGION.MIDDLE);
				let leftMiddSize: ElSize = GridUtil._getInnerSize(leftMidd);

				this._setRegionWidth(GRIDREGION.LEFT, GRIDREGION.MIDDLE, leftMiddSize.iw);

				if (middleSize.ih == 0 && leftMiddSize.ih != 0) {
					middleSize.ih = leftMiddSize.ih;
				}
			}
			if (this._context.isEnabledPart(GRIDREGION.RIGHT)) {
				let rightMidd: HTMLElement = renderer.getNamedNode(GRIDREGION.RIGHT + "-" + GRIDREGION.MIDDLE);
				let rightMiddSize: ElSize = GridUtil._getInnerSize(rightMidd);

				this._setRegionWidth(GRIDREGION.RIGHT, GRIDREGION.MIDDLE, rightMiddSize.iw);

				if (middleSize.ih == 0 && rightMiddSize.ih != 0) {
					middleSize.ih = rightMiddSize.ih;
				}
			}
			// height
			{
				// header
				let centHeader: HTMLElement = renderer.getNamedNode(GRIDREGION.CENTER + "-" + GRIDREGION.HEADER);
				let centHdSize: ElSize = GridUtil._getInnerSize(centHeader);
				headerSize = centHdSize;

				this._setEnabledLocationRegionWidth(GRIDREGION.LEFT, GRIDREGION.HEADER, renderer);
				this._setRegionWidth(GRIDREGION.CENTER, GRIDREGION.HEADER, centHdSize.iw);
				this._setEnabledLocationRegionWidth(GRIDREGION.RIGHT, GRIDREGION.HEADER, renderer);
			}
			if (this._context.isEnabledPart(GRIDREGION.TOP)) {
				let centTop: HTMLElement = renderer.getNamedNode(GRIDREGION.CENTER + "-" + GRIDREGION.TOP);
				let centTopSize: ElSize = GridUtil._getInnerSize(centTop);

				this._setLocationHeight(GRIDREGION.TOP, centTopSize.ih);
				topSize = centTopSize;

				this._setEnabledLocationRegionWidth(GRIDREGION.LEFT, GRIDREGION.TOP, renderer);
				this._setRegionWidth(GRIDREGION.CENTER, GRIDREGION.TOP, centTopSize.iw);
				this._setEnabledLocationRegionWidth(GRIDREGION.RIGHT, GRIDREGION.TOP, renderer);
			}
			if (this._context.isEnabledPart(GRIDREGION.BOTTOM)) {
				let centBttm: HTMLElement = renderer.getNamedNode(GRIDREGION.CENTER + "-" + GRIDREGION.BOTTOM);
				let centBttmSize: ElSize = GridUtil._getInnerSize(centBttm);

				this._setLocationHeight(GRIDREGION.BOTTOM, centBttmSize.ih);
				bottomSize = centBttmSize;

				this._setEnabledLocationRegionWidth(GRIDREGION.LEFT, GRIDREGION.BOTTOM, renderer);
				this._setRegionWidth(GRIDREGION.CENTER, GRIDREGION.BOTTOM, centBttmSize.iw);
				this._setEnabledLocationRegionWidth(GRIDREGION.RIGHT, GRIDREGION.BOTTOM, renderer);
			}
			if (this._context.isEnabledPart(GRIDREGION.FOOTER)) {
				// footer
				let centFooter: HTMLElement = renderer.getNamedNode(GRIDREGION.CENTER + "-" + GRIDREGION.FOOTER);
				let centFooterSize: ElSize = GridUtil._getInnerSize(centFooter);
				footerSize = centFooterSize;

				this._setEnabledLocationRegionWidth(GRIDREGION.LEFT, GRIDREGION.FOOTER, renderer);
				this._setRegionWidth(GRIDREGION.CENTER, GRIDREGION.FOOTER, centFooterSize.iw);
				this._setEnabledLocationRegionWidth(GRIDREGION.RIGHT, GRIDREGION.FOOTER, renderer);
			}
			// cell style 계산
			this._gridRowManager._computeCellStyle();

			let gridHeight: number = rootSize.oh;
			let gridWidth: number = rootSize.ow;

			// resize에 따른 그리드 크기 변경여부를 체크하기 위해 그려질 때 마다 그리드 크기 정보를 저장함
			this._setRegionWidth(GRIDREGION.GRID, GRIDREGION.GRID, gridWidth);
			this._setLocationHeight(GRIDREGION.GRID, gridHeight);

			this._context._clearContentHeight(); // Grid 전체 redraw 시 컨텐트높이 재계산

			let autoSizeType: layouts.AutoSizeType = this._tempAutoSizeType;
			// 그리드가 autoHeight를 지원하면서 autoRowHeight를 지원할 경우 그리드의 높이를 계산하여 컨트롤의 크기를 조정함.
			if ((autoSizeType == layouts.AutoSizeType.both || autoSizeType == layouts.AutoSizeType.height)) {
				let resizeHFunc: Function = function (part: AbstractGridPart, size: ElSize, height: number = -1) {
					let gap: number = size.oh - size.ih; // border or padding
					if (height === -1) {
						if (!part) {
							return size;
						}
						let ctntH: number = part._getContentHeight();
						size.oh = gap + ctntH;
						size.ih = ctntH;
					} else {
						size.oh = height;
						size.ih = height - gap;
					}
				}
				// header
				let gridHeader: GridHeader = this._grid._getGridHeader(GRIDREGION.CENTER);
				if (!gridHeader) {
					gridHeader = this._grid._getGridHeader(GRIDREGION.LEFT);
					if (!gridHeader) {
						gridHeader = this._grid._getGridHeader(GRIDREGION.RIGHT);
					}
				}
				if (gridHeader) {
					resizeHFunc(gridHeader, headerSize, gridHeader._getContentHeight());
				}

				// Top
				if (this._context.isEnabledPart(GRIDREGION.TOP)) {
					let gridTop: GridDetail = this._grid._getGridDetail(GRIDREGION.CENTER, GRIDREGION.TOP) ||
						this._grid._getGridDetail(GRIDREGION.LEFT, GRIDREGION.TOP) ||
						this._grid._getGridDetail(GRIDREGION.RIGHT, GRIDREGION.TOP);

					resizeHFunc(gridTop, topSize, this._context.topSplitHeight);
				}
				// Middle
				let gridMiddle: GridDetail = this._grid._getGridDetail(GRIDREGION.CENTER, GRIDREGION.MIDDLE) ||
					this._grid._getGridDetail(GRIDREGION.LEFT, GRIDREGION.MIDDLE) ||
					this._grid._getGridDetail(GRIDREGION.RIGHT, GRIDREGION.MIDDLE);

				resizeHFunc(gridMiddle, middleSize);

				if (middleSize.ih == 0) {
					// 데이터가 없을 때 한 줄의 디자인 높이 만큼 그려줌.
					let designDetailRowHeight: number = this._context._getDesignDetailRowHeight();
					middleSize.ih = designDetailRowHeight;
					middleSize.oh = middleSize.oh + designDetailRowHeight;
				}
				// Bottom
				if (this._context.isEnabledPart(GRIDREGION.BOTTOM)) {
					let gridBottom: GridDetail = this._grid._getGridDetail(GRIDREGION.CENTER, GRIDREGION.BOTTOM) ||
						this._grid._getGridDetail(GRIDREGION.LEFT, GRIDREGION.BOTTOM) ||
						this._grid._getGridDetail(GRIDREGION.RIGHT, GRIDREGION.BOTTOM);

					resizeHFunc(gridBottom, bottomSize, this._context.bottomSplitHeight);
				}
				// Footer
				if (this._context.isEnabledPart(GRIDREGION.FOOTER)) {
					let gridFooter: GridFooter = this._grid._getGridFooter(GRIDREGION.CENTER) ||
						this._grid._getGridFooter(GRIDREGION.LEFT) ||
						this._grid._getGridFooter(GRIDREGION.RIGHT);

					resizeHFunc(gridFooter, footerSize, gridFooter._getContentHeight());
				}

				gridHeight = rootSize.oh - rootSize.ih + headerSize.oh + topSize.oh + middleSize.oh + bottomSize.oh + footerSize.oh;
				if (autoSizeType == layouts.AutoSizeType.height) {
					let measuredHScroll: { contentWidth: number, layoutWidth: number, scroll: boolean } = this._context._measureHScroll("hidden");
					if (measuredHScroll.scroll === true) {
						let scrollHeight: number = this._context._getHScrollbarHeight();
						middleSize.oh += scrollHeight;
						middleSize.ih += scrollHeight;
						gridHeight += scrollHeight;
					}
				}

				// 레이아웃쪽에 min-height가 설정된 경우
				let container: Container = this._grid.getParent();
				let layout: layouts.Layout<any> = container.getLayout();
				if (layout instanceof layouts.FormLayout) {
					let constraint: layouts.FormConstraint = container.getConstraint(this._grid) as layouts.FormConstraint;
					rootSize.mh = layout.getRowMinHeight(constraint.rowIndex);
				} else if (layout instanceof layouts.VerticalLayout || layout instanceof layouts.FlowLayout) {
					let constraint: layouts.Constraint = container.getConstraint(this._grid);
					rootSize.mh = constraint["minHeight"];
				}

				if (gridHeight < rootSize.mh) { // min height 처리
					gridHeight = rootSize.mh;
					// 그리드 최종 높이가 달라짐에 따라 middle height 갱신 (showExtraRow에서 필요)
					let middleOh: number = gridHeight - (rootSize.oh - rootSize.ih + headerSize.oh + topSize.oh + bottomSize.oh + footerSize.oh);
					resizeHFunc(gridMiddle, middleSize, middleOh);
				}
				// 그리드 높이 고정
				this._grid._getRenderer().updateStyle(ufc.ControlRenderer._NODE_NAME__CONTROL_ROOT, { "min-height": gridHeight + "px" }, true);

				let newSize: ElSize = GridUtil._getInnerSize(rootNode);
				let newGridWidth: number = newSize.ow;
				if (Math.abs(newGridWidth - gridWidth) > 1) {
					return true;
				}
			}

			this._setLocationHeight(GRIDREGION.MIDDLE, middleSize.ih);

			// layout resize
			let layoutWidth: number = gridWidth - (rootSize.ow - rootSize.iw);
			let layoutHeight: number = gridHeight - (rootSize.oh - rootSize.ih);
			renderer.updateStyle("layout", {
				width: layoutWidth + "px"
				, height: "100%"
				, "min-height": layoutHeight + "px"
			}, true);

			// scroll 필요여부 리셋
			this._context._resetReqScroll();

			return false;
		}

		private _setEnabledLocationRegionWidth(region: string, location: string, renderer: ufc.ControlRenderer): void {
			if (this._context.isEnabledPart(region)) {
				let partDOM: HTMLElement = renderer.getNamedNode(region + "-" + location);
				let partDOMSize: ElSize = GridUtil._getInnerSize(partDOM);
				this._setRegionWidth(region, location, partDOMSize.iw);
			}
		}

		protected _doCreateLayoutShape(): cpr.ufc.ElementShape {
			this._clearDimension();

			// layout outline
			let layoutShape: ufc.ElementShape = {
				tag: "div",
				nodename: "layout",
				classNames: [],
				attr: {},
				style: {
					boxSizing: "border-box",
					display: "block",
					height: "100%",
					position: "relative",
					overflow: "hidden"
				},
				children: []
			};

			layoutShape.children.push(_createDrawLazyTask({
				nodename: "layoutrendered",
				task: () => {
					let repeat: boolean = this._computeLayoutStyle();
					if (repeat) { // 그려지는 과정에 컨테이너에 스크롤이 생길 경우 다시 그림
						this._computeLayoutStyle();
					}
					return { tag: "div", style: { display: "none" } };
				}
			}));

			let contentShape: ufc.ElementShape = {
				tag: "div",
				classNames: [],
				attr: {},
				events: {},
				style: {
					boxSizing: "border-box",
					display: "block",
					position: "absolute",
					top: "0",
					left: "0",
					right: "0",
					bottom: "0",
					overflow: "hidden"
				},
				children: this._createTablePanes()
			};
			layoutShape.children[layoutShape.children.length] = contentShape;

			layoutShape.children.push(this._gridRowManager._createShape());

			// nodatamessage
			let noDataMessage: string | ufc.StyledString = this._grid._getDisplayNoDataMessage();
			if (this._grid.getRowCount() == 0 && (noDataMessage instanceof ufc.StyledString || (typeof (noDataMessage) == "string" && noDataMessage != null && noDataMessage != ""))) {
				layoutShape.children[layoutShape.children.length] = _createDrawLazyTask({
					nodename: "nodatamsg",
					task: () => {
						let msgTop: number = this._context._getDesignHeaderRowHeight();
						let msgBottom: number = this._context.isEnabledPart(GRIDREGION.BOTTOM) === true ? this._context.bottomSplitHeight : 0;
						msgBottom += this._context.isEnabledPart(GRIDREGION.FOOTER) === true ? this._context._getDesignFooterRowHeight() : 0;

						if (this._context._isReqHScroll() === true) {
							msgBottom += this._context._getHScrollbarHeight();
						}

						return {
							tag: "div",
							style: {
								boxSizing: "border-box",
								display: "block",
								position: "absolute",
								top: msgTop + "px",
								left: "0",
								right: "0",
								bottom: msgBottom + "px",
								overflow: "hidden"
							},
							children: [{
								tag: "div",
								attr: {},
								classNames: [GridStyle.NODATAMSGWRAPPER],
								style: {
									width: "100%",
									height: "100%",
									display: "table"
								},
								children: [{
									tag: "div",
									attr: {},
									classNames: [GridStyle.NODATAMSG],
									style: {
										width: "100%",
										height: "100%",
										display: "table-cell"
									},
									children: ufc.StyledString._asShape(noDataMessage)
								}]
							}]
						};
					}
				});
			}

			// resize bar
			let resizeBar: ufc.ElementShape = {
				tag: "div",
				nodename: "resizebar",
				style: {
					display: "inline-block",
					width: "1px",
					position: "absolute",
					top: "0",
					bottom: "0",
					left: "-10px",
					border: "1px dashed #A4A4A4"
				}
			};
			layoutShape.children.push(resizeBar);

			// AutoHeight가 적용되었을 때 이전 그려진 Layout Shape에 min-height를 _computeLayoutStyle 하기 전까지 보전해 준다.-autoSize 적용 시 에러
			this._tempAutoSizeType = this._grid._getAutoSizingTypeOfConstraint();
			if ((this._tempAutoSizeType == layouts.AutoSizeType.both || this._tempAutoSizeType == layouts.AutoSizeType.height)) {
				let renderer: ufc.ControlRenderer = this._grid._getRenderer();
				if (renderer.hasDrawn()) {
					let oldLayoutShape: ufc.ElementShape = renderer._getNamedShape("layout");
					if (oldLayoutShape) {
						let oldMinHeight: string = oldLayoutShape.style["min-height"];
						if (oldMinHeight) {
							layoutShape.style["min-height"] = oldMinHeight;
						}
					}
				}
			}

			return layoutShape;
		}

		private _createTablePanes(): ufc.ElementShape[] {
			let tablePane: ufc.ElementShape[] = [];
			let leftPosition: number = 0;
			if (this._leftTablePane._hasContent()) {
				if (this._context.leftSplitWidth >= 0) {
					leftPosition = this._context.leftSplitWidth;
				} else {
					leftPosition = this._leftTablePane._getWidth();
				}
				this._leftTablePane.position = {
					top: "0",
					bottom: "0",
					left: "0",
					width: leftPosition + "px"
				};
				tablePane.push(this._leftTablePane.createShape());
				this._context._setEnablePart(GRIDREGION.LEFT, true);
			} else {
				this._context._setEnablePart(GRIDREGION.LEFT, false);
			}
			let rightPosition: number = 0;
			if (this._rightTablePane._hasContent()) {
				if (this._context.rightSplitWidth >= 0) {
					rightPosition = this._context.rightSplitWidth;
				} else {
					rightPosition = this._rightTablePane._getWidth();
				}
				this._rightTablePane.position = {
					top: "0",
					bottom: "0",
					right: "0",
					width: rightPosition + "px"
				};
			}
			this._centerTablePane.position = {
				top: "0",
				bottom: "0",
				left: leftPosition + "px",
				right: rightPosition + "px"
			};
			tablePane.push(this._centerTablePane.createShape());

			if (rightPosition > 0) { // Tag 순서를 맞춤
				tablePane.push(this._rightTablePane.createShape());
				this._context._setEnablePart(GRIDREGION.RIGHT, true);
			} else {
				this._context._setEnablePart(GRIDREGION.RIGHT, false);
			}
			return tablePane;
		}

		public _getTempAutoSizeType(): layouts.AutoSizeType {
			return this._tempAutoSizeType;
		}

		// for dimension
		/**
		 * Region별 너비(inner width)는 Location 별로 설정된 border, padding의 사이즈에 따라 달라질 수 있기 때문에
		 * inner width는 location까지 식별하여 처리함.
		 * @param region 
		 * @param location 
		 * @param width 
		 */
		private _setRegionWidth(region: string, location: string, width: number): void {
			if (region) {
				this._dimension[region + ":" + location] = width;
			}
		}
		public _getRegionWidth(region: string, location: string): number {
			if (region) {
				let width: number = this._dimension[region + ":" + location];
				if (width > -1) {
					return width;
				}
			}
			return -1;
		}
		private _setLocationHeight(location: GRIDREGION, height: number): void {
			if (location) {
				this._dimension[utils.Util.toString(location)] = height;
			}
		}
		public _getLocationHeight(location: GRIDREGION): number {
			if (location) {
				let height: number = this._dimension[utils.Util.toString(location)];
				if (height > -1) {
					return height;
				}
			}
			return -1;
		}
		private _clearDimension(): void {
			this._dimension = null;
			this._dimension = {};
		}

		public _resetRowManager(): void {
			this._gridRowManager._resetLayout();
		}

		/* OVERRIDE */
		protected _compareConstraint(a: GridControlLayoutConstraint, b: GridControlLayoutConstraint): boolean {
			if (a == null || b == null) {
				return false;
			}

			return a.region == b.region && a.cellIndex == b.cellIndex;
		}

		/** @override */
		protected _doDecorateChild(context: cpr.controls.layouts.LayoutDecorationContext<GridControlLayoutConstraint>): ufc.ControlShape {
			throw new exceptions.UnsupportedOperationException();
		}

		/** @override */
		public _getDefaultConstraint(): GridControlLayoutConstraint {
			throw new exceptions.UnsupportedOperationException();
		}

		/** @override */
		public _getContentPaneNodeName(): string {
			throw new exceptions.UnsupportedOperationException();
		}

		/** @override */
		public _getRenderedLayoutInfo() {
			return null;
		}

		/** @override */
		public _reveal(child: UIControl, duration = 0, timingFunction = animation.TimingFunction.EASE_IN_OUT) {
			if (!this._owner) {
				return;
			}
			if (this._owner.getChildren().indexOf(child) === -1) {
				return;
			}

			let constraint: GridControlLayoutConstraint = this._owner.getConstraint(child) as GridControlLayoutConstraint;
			if (constraint.region == GRIDREGION.HEADER) {
				this._jumpHeaderCell(constraint.cellIndex);
			} else if (constraint.region == GRIDREGION.FOOTER) {
				this._jumpFooterCell(constraint.cellIndex);
			}
		}
	}

}