// 원본 소스: https://github.com/Matt-Esch/virtual-dom/blob/master/vnode/vnode.js
//

namespace cpr.vdom {
	/**
	 * 일반적인 DOM Element에 대한 버추얼 구현.
	 * @private
	 */
	export class VNode {
		public namespace: string;
		public tagName: string;

		public properties: VDomProperties;
		public children: VTreeElement[];

		/**
		 * 버추얼 돔이 노드를 식별하기 위한 키
		 */
		public key: string;

		public count: number;
		public hasWidgets: boolean;
		public hasThunks: boolean;
		public hooks: { [key: string]: VHook };
		public descendantHooks: boolean;

		public readonly type: "VirtualNode" = "VirtualNode";

		constructor(tagName: string, properties?: VDomProperties, children?: VTreeElement[], key?: string, namespace?: string) {
			this.tagName = tagName;
			this.properties = properties ?? {};
			this.children = children ?? [];
			this.key = key ?? undefined;
			this.namespace = namespace ?? null;

			let count = children ? children.length : 0;
			let descendants = 0;
			let hasWidgets = false;
			let hasThunks = false;
			let descendantHooks = false;
			let hooks: { [key: string]: any };

			for (let propName in properties) {
				if (properties.hasOwnProperty(propName)) {
					let property = properties[propName]
					if (_isHook(property) && property.unhook) {
						if (!hooks) {
							hooks = {}
						}

						hooks[propName] = property
					}
				}
			}

			for (let i = 0; i < count; i++) {
				let child = children[i];
				if (_isVNode(child)) {
					descendants += child.count || 0
					if (!hasWidgets && child.hasWidgets) {
						hasWidgets = true
					}

					if (!hasThunks && child.hasThunks) {
						hasThunks = true
					}

					if (!descendantHooks && (child.hooks || child.descendantHooks)) {
						descendantHooks = true
					}
				} else if (!hasWidgets && _isWidget(child)) {
					if (typeof child.destroy === "function") {
						hasWidgets = true
					}
				} else if (!hasThunks && _isThunk(child)) {
					hasThunks = true;
				}
			}

			this.count = count + descendants;
			this.hasWidgets = hasWidgets;
			this.hasThunks = hasThunks;
			this.hooks = hooks;
			this.descendantHooks = descendantHooks;
		}
	}
}


