namespace cpr {
	function _createNativeSpreadConcatFunction() {
		return new Function(`
			var a = arguments;
			switch (a.length) {
				case 0: return [];
				case 1: return [...a[0]];
				case 2: return [...a[0], ...a[1]];
				case 3: return [...a[0], ...a[1], ...a[2]];
				case 4: return [...a[0], ...a[1], ...a[2], ...a[3]];
				case 5: return [...a[0], ...a[1], ...a[2], ...a[3], ...a[4]];
				case 6: return [...a[0], ...a[1], ...a[2], ...a[3], ...a[4], ...a[5]];
				case 7: return [...a[0], ...a[1], ...a[2], ...a[3], ...a[4], ...a[5], ...a[6]];
				default: return Array.prototype.slice.call(a).reduce(function (a, b) { return [...a, ...b] });
			}
		`) as (...sources: any[][]) => any[];
	}


	export const _concatArray: <T>(...arrs: T[][]) => T[] = _ECMA._spreadOperator
		? _createNativeSpreadConcatFunction()
		: <T>(...arrs: T[][]) => arrs.reduce((a, b) => a.concat(b), []);

	/**
	 * 배열로 부터 일치하는 첫 객체를 제거 합니다.
	 * @param array 배열.
	 * @param objToRemove 제거할 객체. 
	 * @returns 제거 여부.
	 */
	export function _removeFromArray<T>(array: T[], objToRemove: T): boolean {
		if (!array) {
			return false;
		}

		let idx = array.indexOf(objToRemove);
		if (idx >= 0) {
			array.splice(idx, 1);
			return true;
		}
		else {
			return false;
		}
	}

	/**
	 * 배열 객체 인지 여부 확인
	 * @param obj 
	 * @returns 
	 */
	export function _isArray(obj: any): obj is Array<any> {
		return Array.isArray(obj);
	}

	export function _uniq<T>(array: T[]): T[] {
		// https://medium.com/@jakubsynowiec/unique-array-values-in-javascript-7c932682766c
		if (_ECMA._iterable) {
			return Array.from(new Set(array));
		}
		else {
			return _stream(array)
				.uniquify()
				.collect();
		}
	}

	/**
	* 배열에서 조건을 만족하는 첫 번째 요소를 찾습니다.
	* @param array 배열.
	* @param predicate 
	*/
	export function _findFirst<T>(array: T[], predicate: (e: T) => boolean) {
		if (!array) {
			return null;
		}
		for (let idx = 0; idx < array.length; idx++) {
			let each = array[idx];
			if (predicate(each)) {
				return each;
			}
		}
		return null;
	}

	/**
	 * 배열에서 조건을 만족하는 마지막 요소를 찾습니다.
	 * @param array 
	 * @param predicate 
	 */
	export function _findLast<T>(array: T[], predicate: (e: T) => boolean) {
		if (!array) {
			return null;
		}
		for (let idx = array.length - 1; idx >= 0; idx--) {
			let each = array[idx];
			if (predicate(each)) {
				return each;
			}
		}
		return null;
	}


	/**
	 * {@link NodeList}, {@link HTMLCollection} 및 {@link FileList} 등을 배열로 변환 합니다.
	 * @param nodeList 변환할 노드 리스트
	 */
	export function _toArray<E extends object>(nodeList: NodeListLike<E>): E[];

	/**
	 * 함수 파라미터들을 배열로 변환 합니다.
	 * @param arg 변환할 {@link IArguments}.
	 */
	export function _toArray(arg: IArguments): any[];
	export function _toArray(input: any): any[] {
		let result: any[];
		return (result = []).push.apply(result, input), result;
	}

	/**
	 * 배열의 얕은 사본을 만듭니다.
	 * @param array 복제할 배열. 
	 * @returns 배열 사본.
	 */
	export function _shallowCopyArray<T>(array: T[]): T[] {
		let result: any[];
		return (result = []).push.apply(result, array), result;
	}
}