/// <reference path="./ItemsAccessibility.ts" />

namespace cpr.controls {

	/**
	 * TabFolder의 접근성을 관리하는 클래스
	 * tablist (root), tab, tabpanel의 3단계 구조를 제공합니다.
	 * @noinstance
	 */
	export class TabFolderAccessibility extends Accessibility {

		public static _getSpec(): AriaSpec {
			return { root: { role: "tablist" }, tab: { role: "tab" }, tabpanel: { role: "tabpanel" } };
		}

		protected override _createAccessibility(name: string, spec: AriaSet): Accessibility {
			switch (name) {
				case "tab":
				case "tabpanel":
					let a11y = new ItemsAccessibility(this._getOwner(), { root: spec });
					a11y._setName(name);
					return a11y;
				default:
					return super._createAccessibility(name, spec);
			}
		}

		/**
		 * 모든 tab 항목에 대한 기본 접근성 설정을 반환합니다.
		 * forItem()을 통해 개별 아이템별 설정이 가능합니다.
		 * @returns tab 역할에 대한 ItemsAccessibility
		 */
		public get tab(): ItemsAccessibility {
			return this._getSubAccessibility("tab") as ItemsAccessibility;
		}

		/**
		 * 모든 tabpanel에 대한 기본 접근성 설정을 반환합니다.
		 * forItem()을 통해 개별 아이템별 설정이 가능합니다.
		 * @returns tabpanel 역할에 대한 ItemAccessibility
		 */
		public get tabpanel(): ItemsAccessibility {
			return this._getSubAccessibility("tabpanel") as ItemsAccessibility;
		}

		/**
		 * 특정 TabItem이 제거될 때 호출되어 캐시를 정리합니다.
		 * @param item 제거될 TabItem
		 */
		public _removeTabItem(item: TabItem): void {
			this.tab._removeItemAccessibility(item);
			this.tabpanel._removeItemAccessibility(item);
		}

		/**
		 * 모든 TabItem의 Accessibility 캐시를 제거합니다.
		 */
		public _clearAllItems(): void {
			this.tab._clearItemAccessibilities();
			this.tabpanel._clearItemAccessibilities();
		}
	}
}