
namespace cpr.foundation {
	/**
	 * @private
	 */
	export class DateFormatter extends BindableFormatter implements IFormatter {

		// local
		private _localFormat: string;
		private _localOriginFormat: string;

		constructor(format: string = "", options: { parseFormat?: string, locale?: string } = {}) {
			super()
			this._addBindPropertyValue("format", format);
			this._addBindPropertyValue("parseFormat", options.parseFormat ?? "YYYYMMDDHHmmssSSS");
			this._addBindPropertyValue("locale", options.locale ?? "");
		}

		public get type(): string {
			return "date";
		}

		private _getFormat(): string {
			return this._getBindProperty("format").get() ?? "";
		}

		private _getParseFormat() {
			return this._getBindProperty("parseFormat").get() ?? "";
		}

		private _getLocale() {
			let locale = this._getBindProperty("locale").get() ?? "";
			if (!locale) {
				return cpr.I18N.INSTANCE.currentLanguage ?? cpr.I18N.INSTANCE.getBrowserLanguage();
			}
			return locale;
		}

		private _getLocalFormat() {
			if (this._needUpdateFormat()) {
				this._applyFormat();
			}
			return this._localFormat;
		}

		private _needUpdateFormat(): boolean {
			return this._localOriginFormat != this._getFormat();
		}

		private _applyFormat(): void {
			this._localOriginFormat = this._getFormat();
			let ignoreFormatRegexp = /([xXgGEe])/gi;
			this._localFormat = this._getFormat().replace(ignoreFormatRegexp, "[$1]");
		}

		public transform(text: string): string;
		public transform(date: Date): string;
		public transform(arg: any): string {
			if (!this._getLocalFormat()) {
				return arg?.toString();
			}
			let mm: moment.Moment = null;
			if (arg instanceof Date) {
				mm = _createMoment(() => moment(arg), this._getLocale());
			} else {
				mm = _createMoment(() => moment(arg, this._getParseFormat()), this._getLocale());
			}
			if (!mm.isValid()) {
				return "";
			}
			return mm.format(this._getLocalFormat());
		}

		public reverseTransform(formattedText: string): string {
			let mm = _createMoment(() => moment(formattedText, this._getParseFormat()), this._getLocale());
			if (!mm.isValid()) {
				return "";
			}
			return mm.format(this._getLocalFormat());
		}

	}
}