namespace cpr.vdom {
	export type CreateOptions = {
		document?: HTMLDocument;
		warn?: boolean;
	};

	/**
	 * 옵션을 설정하고 엘리먼트를 생성합니다.
	 * @param vnode 
	 * @param opts 
	 * @private
	 */
	export function create(vnode: VTreeElement, opts?: CreateOptions): Element {
		let doc = opts ? opts.document || document : document;
		let warn: any = opts ? opts.warn : null;

		let virtualNode = (_handleThunk(vnode).a) as VTreeElement;

		if (_isWidget(virtualNode)) {
			return virtualNode.init()
		} else if (_isVText(virtualNode)) {
			return doc.createTextNode(virtualNode.text) as any
		} else if (!_isVNode(virtualNode)) {
			if (warn) {
				warn("Item is not a valid virtual dom node", virtualNode)
			}
			return null
		}

		let node: Element = (virtualNode.namespace === null) ?
			doc.createElement(virtualNode.tagName) :
			doc.createElementNS(virtualNode.namespace, virtualNode.tagName);

		let props = virtualNode.properties;
		_applyProperties(node, props);

		let children = virtualNode.children;

		for (let i = 0; i < children.length; i++) {
			let childNode = create(children[i], opts);
			if (childNode) {
				node.appendChild(childNode);
			}
		}

		return node;
	}

	//patch.js
	type RenderOption = {
		/** 패치 함수 */
		patch?: typeof _patchRecursive;
		/** 렌더링 함수 */
		render?: typeof create;
		document?: HTMLDocument
	};

	/**
	 * 엘리먼트에 수정된 내용들을 적용합니다. 부모 노드부터 자식 노드를 탐색하여 패치합니다.
	 * @param rootNode 
	 * @param patches 
	 * @private
	 */
	export function patch(rootNode: Element, patches: VPatches, renderOptions: RenderOption = {}): Element {
		renderOptions.patch = renderOptions.patch && renderOptions.patch !== patch
			? renderOptions.patch
			: _patchRecursive
			;

		renderOptions.render = renderOptions.render ?? create;
		return renderOptions.patch(rootNode, patches, renderOptions) as Element;
	}

	function _patchRecursive(rootNode: Node, patches: VPatches, renderOptions: RenderOption): Node {
		let indices = _patchIndices(patches)

		if (indices.length === 0) {
			return rootNode
		}

		let index = _domIndex(rootNode, patches.a, indices)
		let ownerDocument = rootNode.ownerDocument

		if (!renderOptions.document && ownerDocument !== document) {
			renderOptions.document = ownerDocument
		}

		for (let i = 0; i < indices.length; i++) {
			let nodeIndex = indices[i];
			rootNode = _applyPatches(rootNode,
				index[nodeIndex],
				patches[nodeIndex],
				renderOptions)
		}

		return rootNode
	}

	function _applyPatches(rootNode: Node, domNode: Node, patchList: any, renderOptions: RenderOption): Node {
		if (!domNode) {
			return rootNode
		}

		let newNode: Node;

		if (_isArray(patchList)) {
			for (let i = 0; i < patchList.length; i++) {
				newNode = _applyPatch(patchList[i], domNode, renderOptions)

				if (domNode === rootNode) {
					rootNode = newNode
				}
			}
		} else {
			newNode = _applyPatch(patchList as VPatch, domNode, renderOptions);

			if (domNode === rootNode) {
				rootNode = newNode
			}
		}

		return rootNode;
	}

	function _patchIndices(patches: VPatches) {
		let indices = []

		for (let key in patches) {
			if (key !== "a") {
				indices.push(Number(key));
			}
		}

		return indices
	}

	//patch-op.js
	type MoveChildrenType = {
		inserts: { key: string, to: number }[]
		removes: { key: number, from: string }[]
	};

	function _applyPatch(vpatch: VPatch, domNode: Node, renderOptions: RenderOption): Node {
		let type = vpatch.type
		let vNode = vpatch.vNode
		let patch = vpatch.patch

		switch (type) {
			case VPatchType.REMOVE:
				return _removeNode(domNode, vNode)
			case VPatchType.INSERT:
				return _insertNode(domNode, patch, renderOptions)
			case VPatchType.VTEXT:
				return _stringPatch(domNode, vNode as VText, patch, renderOptions)
			case VPatchType.WIDGET:
				return _widgetPatch(domNode, vNode as Widget, patch, renderOptions)
			case VPatchType.VNODE:
				return _vNodePatch(domNode, vNode as VNode, patch, renderOptions)
			case VPatchType.ORDER:
				_reorderChildren(domNode, patch)
				return domNode
			case VPatchType.PROPS:
				_applyProperties(domNode, patch, (vNode as VNode).properties)
				return domNode
			case VPatchType.THUNK:
				return _replaceRoot(domNode, renderOptions.patch(domNode, patch, renderOptions))
			default:
				return domNode
		}
	}

	function _removeNode(domNode: Node, vNode: VTreeElement) {
		let parentNode = domNode.parentNode

		if (parentNode) {
			parentNode.removeChild(domNode)
		}

		_destroyWidget(domNode, vNode as Widget);

		return null
	}

	function _insertNode(parentNode: Node, vNode: VNode, renderOptions: RenderOption) {
		let newNode = renderOptions.render(vNode, renderOptions)

		if (parentNode) {
			parentNode.appendChild(newNode)
		}

		return parentNode
	}

	function _stringPatch(domNode: Node, leftVNode: VText, vText: VText, renderOptions: RenderOption): Node {
		let newNode: Node

		if (domNode.nodeType === Node.TEXT_NODE) {
			(domNode as Text).replaceData(0, (domNode as Text).length, vText.text)
			newNode = domNode;
		} else {
			let parentNode = domNode.parentNode
			newNode = renderOptions.render(vText, renderOptions)

			if (parentNode && newNode !== domNode) {
				parentNode.replaceChild(newNode, domNode)
			}
		}

		return newNode
	}

	function _widgetPatch(domNode: Node, leftVNode: Widget, widget: Widget, renderOptions: RenderOption) {
		let updating = _updateWidget(leftVNode, widget);
		let newNode: Element

		if (updating) {
			newNode = widget.update(leftVNode, domNode) || domNode
		} else {
			newNode = renderOptions.render(widget, renderOptions)
		}

		let parentNode = domNode.parentNode

		if (parentNode && newNode !== domNode) {
			parentNode.replaceChild(newNode, domNode)
		}

		if (!updating) {
			_destroyWidget(domNode, leftVNode)
		}

		return newNode
	}

	function _vNodePatch(domNode: Node, leftVNode: VNode, vNode: VNode, renderOptions: RenderOption) {
		let parentNode = domNode.parentNode
		let newNode = renderOptions.render(vNode, renderOptions)

		if (parentNode && newNode !== domNode) {
			parentNode.replaceChild(newNode, domNode);
		}

		return newNode;
	}

	function _destroyWidget(domNode: Node, w: Widget) {
		if (_isWidget(w)) {
			w.destroy?.(domNode as Element);
		}
	}

	function _reorderChildren(domNode: Node, moves: MoveChildrenType) {
		let childNodes = domNode.childNodes;
		let keyMap = {};
		let node: Node;
		let remove: { key: number, from: string };
		let insert: { key: string, to: number };

		for (let i = 0; i < moves.removes.length; i++) {
			remove = moves.removes[i];
			node = childNodes[remove.from];
			if (remove.key) {
				keyMap[remove.key] = node;
			}
			domNode.removeChild(node);
		}

		let length = childNodes.length;
		for (let j = 0; j < moves.inserts.length; j++) {
			insert = moves.inserts[j];
			node = keyMap[insert.key];
			// this is the weirdest bug i've ever seen in webkit
			domNode.insertBefore(node, insert.to >= length++ ? null : childNodes[insert.to]);
		}
	}

	function _replaceRoot(oldRoot: Node, newRoot: Node): Node {
		if (oldRoot && newRoot && oldRoot !== newRoot && oldRoot.parentNode) {
			oldRoot.parentNode.replaceChild(newRoot, oldRoot);
		}

		return newRoot;
	}

	//dom-index.js
	function _domIndex(rootNode: Node, tree: VTreeElement, indices: number[], nodes?: {}) {
		if (!indices || indices.length === 0) {
			return {}
		} else {
			indices.sort(_ascending)
			return _recurse(rootNode, tree, indices, nodes, 0)
		}
	}

	function _recurse(rootNode: Node, tree: VTreeElement, indices: number[], nodes: {} = {}, rootIndex: number) {
		if (rootNode) {
			if (_indexInRange(indices, rootIndex, rootIndex)) {
				nodes[rootIndex] = rootNode
			}
			let vChildren = (tree as VNode).children
			if (vChildren) {
				let childNodes = rootNode.childNodes;
				for (let i = 0; i < (tree as VNode).children.length; i++) {
					rootIndex += 1;

					let vChild: VTreeElement = vChildren[i] || {} as VTreeElement;
					let nextIndex = rootIndex + ((vChild as VNode).count || 0)

					// skip recursion down the tree if there are no nodes down here
					if (_indexInRange(indices, rootIndex, nextIndex)) {
						_recurse(childNodes[i], vChild, indices, nodes, rootIndex)
					}

					rootIndex = nextIndex
				}
			}
		}
		return nodes
	}

	/**
	 * Binary search for an index in the interval [left, right]
	 * @param indices 
	 * @param left 
	 * @param right 
	 * @returns 
	 */
	function _indexInRange(indices: number[], left: number, right: number) {
		if (indices.length === 0) {
			return false
		}

		let minIndex: number = 0;
		let maxIndex: number = indices.length - 1;
		let currentIndex: number;
		let currentItem: number;

		while (minIndex <= maxIndex) {
			currentIndex = ((maxIndex + minIndex) / 2) >> 0
			currentItem = indices[currentIndex]

			if (minIndex === maxIndex) {
				return currentItem >= left && currentItem <= right
			} else if (currentItem < left) {
				minIndex = currentIndex + 1
			} else if (currentItem > right) {
				maxIndex = currentIndex - 1
			} else {
				return true;
			}
		}

		return false;
	}

	/**
	 * 오름차순
	 * @param a 
	 * @param b 
	 * @returns 
	 */
	function _ascending(a: number, b: number) {
		return a > b ? 1 : -1
	}

	//update-widget.js
	function _updateWidget(a: any, b: any) {
		if (_isWidget(a) && _isWidget(b)) {
			if ("name" in a && "name" in b) {
				return a.id === b.id;
			} else {
				return a.init === b.init
			}
		}

		return false
	}

	//apply-properties.js
	function _applyProperties(node: Node, props: { [key: string]: any }, previous?: { [key: string]: any }) {
		for (let propName in props) {
			let propValue = props[propName];

			if (propValue === undefined) {
				_removeProperty(node, propName, propValue, previous);
			} else if (_isHook(propValue)) {
				_removeProperty(node, propName, propValue, previous)
				if (propValue.hook) {
					propValue.hook(node,
						propName,
						previous ? previous[propName] : undefined)
				}
			} else {
				if (_isIndividualObject(propValue)) {
					_patchObject(node, props, previous, propName, propValue);
				} else {
					node[propName] = propValue
				}
			}
		}
	}

	function _removeProperty(node: Node, propName: string, propValue: any, previous: { [key: string]: any }) {
		if (previous) {
			let previousValue = previous[propName]

			if (!_isHook(previousValue)) {
				if (propName === "attributes") {
					for (let attrName in previousValue) {
						(node as Element).removeAttribute(attrName)
					}
				} else if (propName === "style") {
					for (let i in previousValue) {
						(node as HTMLElement).style[i] = ""
					}
				} else if (typeof previousValue === "string") {
					node[propName] = ""
				} else {
					node[propName] = null
				}
			} else if (previousValue.unhook) {
				previousValue.unhook(node, propName, propValue)
			}
		}
	}

	function _patchObject(node: Node, props: { [key: string]: any }, previous: { [key: string]: any }, propName: string, propValue: any) {
		let previousValue = previous ? previous[propName] : undefined

		// Set attributes
		if (propName === "attributes") {

			for (let attrName in propValue) {
				let attrValue = propValue[attrName]
				if (attrValue === undefined) {
					(node as Element).removeAttribute(attrName)
				} else {
					(node as Element).setAttribute(attrName, attrValue)
				}
			}

			return
		}

		if (previousValue && _isIndividualObject(previousValue) &&
			_getPrototype(previousValue) !== _getPrototype(propValue)) {
			node[propName] = propValue
			return
		}

		if (!_isIndividualObject(node[propName])) {
			node[propName] = {}
		}

		let replacer = propName === "style" ? "" : undefined

		for (let k in propValue) {
			let value = propValue[k]
			node[propName][k] = (value === undefined) ? replacer : value
		}
	}

	function _getPrototype(value: any): object {
		return Object.getPrototypeOf(value);
	}
}