/// <reference path="./Header.ts"/>
namespace cpr.data.header {
	export class ExpressionHeader extends Header {
		private _expression: string;
		private _function: Function;

		constructor(name: string, expr: string = "") {
			super(name, tabledata.DataType.EXPRESSION);
			this._function = null;
			this.setExpression(expr);
		}

		/**
		 * 익스프레션 문자열을 반환합니다.
		 * @return expression 식.
		 */
		public getExpression(): expression_string {
			return this._expression;
		}

		/**
		 * 익스프레션을 문자열을 설정합니다.
		 * @param expr expression 식.
		 */
		public setExpression(expr: expression_string): void {
			this._expression = expr;
			if (expr != null && expr != "") {
				this._function = expression.ExpressionEngine.INSTANCE.compile(expr) as Function;
			}
		}
		/**
		 * 익스프레션 결과 함수를 반환합니다.
		 * @return expression 함수.
		 */
		public getFunction(): Function {
			return this._function;
		}

	}
}