namespace cpr.controls.gridpart {

	/**
	 * 그리드 셀에 적용된 CSS class를 익스포트 데이터에 담을 수 있는 CSS 속성 맵으로 해석합니다.<br>
	 * <br>
	 * 익스포트 데이터는 CSS class를 그대로 전달할 수 없고 속성 맵만 반영할 수 있으므로,
	 * class에 의해 실제로 적용되는 속성 값을 브라우저에서 직접 측정하여 얻습니다.<br>
	 * 측정은 그리드 안쪽에 배치한 화면 밖 셀 요소(프로브)에 class를 적용한 뒤 계산 스타일을 읽는 방식이며,
	 * class가 없는 상태의 계산 스타일과 비교하여 <b>해당 class에 의해 달라진 속성만</b> 추출합니다.
	 * 프로브를 그리드 안쪽에 두는 이유는 테마나 하위 선택자에 의한 규칙이 그리드 바깥에서는 적용되지 않기 때문입니다.<br>
	 * <br>
	 * 셀에 배치된 컨트롤에 지정된 class는 셀 프로브 안에 재현한 컨트롤 프로브 요소에서 측정합니다.
	 * 컨트롤 class 스타일은 셀이 아닌 컨트롤 요소를 대상으로 하는 선택자(.cl-control.xxx 등)로
	 * 정의되는 경우가 많아, 셀 요소에 class를 적용해서는 렌더링과 같은 결과를 얻을 수 없기 때문입니다.<br>
	 * <br>
	 * 측정 결과는 class 조합 단위로 캐시되므로 행 수가 많아도 측정 횟수는 화면에서 사용된 class 조합 수를 넘지 않습니다.<br>
	 * <br>
	 * 다음은 해석 대상이 아닙니다.
	 * <ul>
	 * <li>엑셀에서 표현할 수 없는 속성(gradient, box-shadow 등)</li>
	 * <li>:hover 등 상태에 따라 달라지는 스타일</li>
	 * <li>밴드(header/detail/footer)별 하위 선택자에 의해 덮어써지는 규칙</li>
	 * </ul>
	 * @private
	 */
	export class GridClassStyleResolver {

		/**
		 * 익스포트 데이터에 반영할 CSS 속성.
		 */
		private static readonly _TARGET_PROPERTIES: string[] = [
			"color",
			"background-color",
			"font-family",
			"font-size",
			"font-weight",
			"font-style",
			"text-align",
			"vertical-align",
			"text-decoration",
			"border-top-width", "border-top-style", "border-top-color",
			"border-right-width", "border-right-style", "border-right-color",
			"border-bottom-width", "border-bottom-style", "border-bottom-color",
			"border-left-width", "border-left-style", "border-left-color"
		];

		/**
		 * 셀이 기본으로 가지는 class를 반환합니다. 기준 스타일 측정에 사용합니다.<br>
		 * 번들 내 선언 순서에 영향을 받지 않도록 정적 필드가 아닌 메소드로 제공합니다.
		 */
		private static _getBaseClasses(): string[] {
			return [GridStyle.CELL, GridContext.CLS_CELL_INHERIT];
		}

		private _grid: Grid;
		/**
		 * class 조합별 해석 결과 캐시.
		 */
		private _cache: { [classKey: string]: { [styleName: string]: string } } = {};
		/**
		 * 컨트롤 class 조합별 해석 결과 캐시.
		 */
		private _controlCache: { [classKey: string]: { [styleName: string]: string } } = {};
		/**
		 * class가 적용되지 않은 상태의 계산 스타일.
		 */
		private _baseStyle: { [styleName: string]: string } = null;
		private _probeRow: HTMLElement = null;
		private _probeCell: HTMLElement = null;
		/**
		 * 셀에 배치된 컨트롤의 class 측정에 사용하는 프로브 요소. 셀 프로브의 자식으로 재현합니다.
		 */
		private _probeControl: HTMLElement = null;
		/**
		 * 그리드가 렌더링되지 않아 측정이 불가능한 상태인지 여부.
		 */
		private _unavailable: boolean = false;

		constructor(grid: Grid) {
			this._grid = grid;
		}

		/**
		 * 주어진 class에 의해 적용되는 CSS 속성을 반환합니다.
		 * @param classes 셀에 적용된 class 명.
		 * @return CSS 속성 맵. 적용된 class가 없거나 측정할 수 없는 경우 빈 객체를 반환합니다.
		 */
		public _resolve(classes: string[]): { [styleName: string]: string } {
			if (classes == null || classes.length == 0) {
				return {};
			}

			let cacheKey: string = classes.join(" ");
			if (this._cache.hasOwnProperty(cacheKey)) {
				return this._cache[cacheKey];
			}

			let result: { [styleName: string]: string } = {};
			if (this._prepare() == true) {
				let baseStyle: { [styleName: string]: string } = this._getBaseStyle();
				let classStyle: { [styleName: string]: string } = this._measure(GridClassStyleResolver._getBaseClasses().concat(classes));
				result = GridClassStyleResolver._extractChangedProperties(baseStyle, classStyle);
			}

			this._cache[cacheKey] = result;
			return result;
		}

		/**
		 * 셀에 배치된 컨트롤에 지정된 class에 의해 적용되는 CSS 속성을 반환합니다.<br>
		 * 셀 프로브 안에 컨트롤의 기본 class를 가진 프로브 요소를 재현하여 측정하므로,
		 * 컨트롤 요소를 대상으로 하는 선택자(.cl-control.xxx 등)로 정의된 규칙도 렌더링과 같게 해석됩니다.<br>
		 * 셀에 지정된 class에 의해 컨트롤이 상속받는 값이 달라질 수 있으므로,
		 * 셀 프로브에 셀 class를 적용한 상태를 기준으로 측정합니다.
		 * @param controlBaseClasses 컨트롤이 렌더링될 때 기본으로 가지는 class 명. (cl-control, 타입 class 등)
		 * @param classes 컨트롤에 지정된 class 명.
		 * @param cellClasses 컨트롤이 배치된 셀에 지정된 class 명.
		 * @return CSS 속성 맵. 적용된 class가 없거나 측정할 수 없는 경우 빈 객체를 반환합니다.
		 */
		public _resolveControl(controlBaseClasses: string[], classes: string[], cellClasses: string[]): { [styleName: string]: string } {
			if (classes == null || classes.length == 0) {
				return {};
			}
			if (cellClasses == null) {
				cellClasses = [];
			}

			let cacheKey: string = controlBaseClasses.join(" ") + "|" + cellClasses.join(" ") + "|" + classes.join(" ");
			if (this._controlCache.hasOwnProperty(cacheKey)) {
				return this._controlCache[cacheKey];
			}

			let result: { [styleName: string]: string } = {};
			if (this._prepare() == true) {
				this._probeCell.className = GridClassStyleResolver._getBaseClasses().concat(cellClasses).join(" ");
				let baseStyle: { [styleName: string]: string } = this._measureControl(controlBaseClasses);
				let classStyle: { [styleName: string]: string } = this._measureControl(controlBaseClasses.concat(classes));
				result = GridClassStyleResolver._extractChangedProperties(baseStyle, classStyle);
			}

			this._controlCache[cacheKey] = result;
			return result;
		}

		/**
		 * 기준 계산 스타일과 class 적용 후 계산 스타일을 비교하여 class에 의해 달라진 속성만 추출합니다.
		 * @param baseStyle class가 적용되지 않은 상태의 계산 스타일.
		 * @param classStyle class가 적용된 상태의 계산 스타일.
		 */
		private static _extractChangedProperties(baseStyle: { [styleName: string]: string }, classStyle: { [styleName: string]: string }): { [styleName: string]: string } {
			let result: { [styleName: string]: string } = {};
			GridClassStyleResolver._TARGET_PROPERTIES.forEach((property: string) => {
				let value: string = classStyle[property];
				// class에 의해 달라진 속성만 반영합니다.
				if (value == null || value === "" || value === baseStyle[property]) {
					return;
				}
				// 보이지 않는 테두리의 색/두께는 반영하지 않습니다.
				// (color 변경시 currentColor를 따라 border-color 계산 값이 함께 달라지는 경우가 이에 해당합니다)
				let borderSide: RegExpMatchArray = property.match(/^border-(top|right|bottom|left)-(color|width)$/);
				if (borderSide != null) {
					let sideStyle: string = classStyle["border-" + borderSide[1] + "-style"];
					if (sideStyle == null || sideStyle === "" || sideStyle === "none") {
						return;
					}
				}
				let normalized: string = GridClassStyleResolver._normalize(property, value);
				if (normalized != null) {
					result[property] = normalized;
				}
			});
			return result;
		}

		/**
		 * 측정에 사용할 프로브 요소를 준비합니다.
		 * @return 측정 가능 여부.
		 */
		private _prepare(): boolean {
			if (this._unavailable == true) {
				return false;
			}
			// 익스포트 도중 사용자 핸들러(rowDataHandler 등)에서 그리드를 다시 그리면 프로브가 제거될 수 있습니다.
			// 문서에서 분리된 요소는 CSS 규칙의 적용 대상이 아니므로 그대로 측정하면 기준 스타일과 비교시
			// 초기값이 class 스타일인 것처럼 반영되므로, 매번 연결 상태를 확인합니다.
			if (this._probeCell != null && GridClassStyleResolver._isAttached(this._probeRow) == true) {
				return true;
			}

			let rootElement: HTMLElement = null;
			let traverser: ufc.DOMTraverser = ufc._traverseFromControl(this._grid);
			if (traverser != null) {
				rootElement = traverser._getElement() as HTMLElement;
				traverser.dispose();
			}
			if (rootElement == null || GridClassStyleResolver._isAttached(rootElement) == false) {
				// 그리드가 화면에 렌더링되지 않은 상태에서는 계산 스타일을 얻을 수 없습니다.
				this._unavailable = true;
				console.warn("applyClassStyle: 그리드가 화면에 렌더링되어 있지 않아 class에 지정된 스타일을 계산할 수 없습니다. "
					+ "class로 지정한 스타일은 익스포트 결과에 반영되지 않습니다.(\"" + this._grid.id + "\")");
				return false;
			}

			if (this._probeRow == null) {
				this._probeRow = this._createProbeRow();
				this._probeCell = document.createElement("div");
				this._probeRow.appendChild(this._probeCell);
				this._probeControl = document.createElement("div");
				this._probeCell.appendChild(this._probeControl);
			}
			rootElement.appendChild(this._probeRow);
			return true;
		}

		/**
		 * 측정에 사용할 프로브 행 요소를 생성합니다.
		 */
		private _createProbeRow(): HTMLElement {
			let probeRow: HTMLElement = document.createElement("div");
			probeRow.className = GridStyle.ROW;
			// 화면에 보이지 않으면서 계산 스타일은 얻을 수 있도록 화면 밖에 배치합니다. (display:none인 경우 계산 스타일을 얻을 수 없음)
			probeRow.style.position = "absolute";
			probeRow.style.top = "-10000px";
			probeRow.style.left = "-10000px";
			probeRow.style.width = "0";
			probeRow.style.height = "0";
			probeRow.style.overflow = "hidden";
			probeRow.setAttribute("aria-hidden", "true");
			return probeRow;
		}

		/**
		 * 주어진 요소가 문서에 연결되어 있는지 여부를 반환합니다.
		 * @param element 확인할 요소.
		 */
		private static _isAttached(element: HTMLElement): boolean {
			if (element == null || document.body == null) {
				return false;
			}
			return document.body.contains(element);
		}

		/**
		 * class가 적용되지 않은 상태의 계산 스타일을 반환합니다.
		 */
		private _getBaseStyle(): { [styleName: string]: string } {
			if (this._baseStyle == null) {
				this._baseStyle = this._measure(GridClassStyleResolver._getBaseClasses());
			}
			return this._baseStyle;
		}

		/**
		 * 프로브에 주어진 class를 적용하고 대상 속성의 계산 스타일을 반환합니다.
		 * @param classes 프로브에 적용할 class 명.
		 */
		private _measure(classes: string[]): { [styleName: string]: string } {
			this._probeCell.className = classes.join(" ");
			return GridClassStyleResolver._readComputedStyle(this._probeCell);
		}

		/**
		 * 컨트롤 프로브에 주어진 class를 적용하고 대상 속성의 계산 스타일을 반환합니다.
		 * @param classes 컨트롤 프로브에 적용할 class 명.
		 */
		private _measureControl(classes: string[]): { [styleName: string]: string } {
			this._probeControl.className = classes.join(" ");
			return GridClassStyleResolver._readComputedStyle(this._probeControl);
		}

		/**
		 * 주어진 요소에서 대상 속성의 계산 스타일을 읽어 반환합니다.
		 * @param element 계산 스타일을 읽을 요소.
		 */
		private static _readComputedStyle(element: HTMLElement): { [styleName: string]: string } {
			let result: { [styleName: string]: string } = {};

			let computedStyle: CSSStyleDeclaration = window.getComputedStyle(element);
			if (computedStyle == null) {
				return result;
			}
			GridClassStyleResolver._TARGET_PROPERTIES.forEach((property: string) => {
				result[property] = computedStyle.getPropertyValue(property);
			});
			return result;
		}

		/**
		 * 계산 스타일 값을 익스포트 데이터에서 사용할 수 있는 형태로 변환합니다.
		 * @param property CSS 속성명.
		 * @param value 계산 스타일 값.
		 * @return 변환된 값. 반영할 필요가 없는 경우 null.
		 */
		private static _normalize(property: string, value: string): string {
			switch (property) {
				case "text-decoration": {
					return GridClassStyleResolver._normalizeTextDecoration(value);
				}
				case "font-family": {
					return GridClassStyleResolver._normalizeFontFamily(value);
				}
				case "font-weight": {
					// 엑셀은 굵기 단계를 표현할 수 없으므로 bold 여부로만 반영합니다.
					let numericWeight: number = parseInt(value, 10);
					if (isNaN(numericWeight) == false) {
						return (numericWeight >= 600) ? "bold" : "normal";
					}
					return (value == "bold" || value == "bolder") ? "bold" : "normal";
				}
				case "font-style": {
					// 엑셀은 oblique를 표현할 수 없으므로 italic으로 반영합니다.
					return (value == "normal") ? "normal" : "italic";
				}
				case "text-align": {
					// 계산 스타일에서 반환하는 논리적 정렬 값을 물리적 정렬 값으로 변환합니다.
					if (value == "start") {
						return "left";
					}
					if (value == "end") {
						return "right";
					}
					return value;
				}
			}
			if (property.indexOf("color") != -1) {
				return GridClassStyleResolver._normalizeColor(value);
			}
			return value;
		}

		/**
		 * 계산 스타일의 색상 값을 16진 표기로 변환합니다.<br>
		 * 계산 스타일은 색상을 rgb()/rgba() 형태로 반환하므로 인라인 스타일과 표기를 맞춥니다.
		 * @param value 색상 값.
		 * @return 16진 표기 색상. 투명한 색인 경우 null.
		 */
		private static _normalizeColor(value: string): string {
			if (value == null) {
				return null;
			}
			let color: string = value.replace(/\s/g, "");
			if (color == "" || color == "transparent") {
				return null;
			}

			let matched: RegExpMatchArray = color.match(/^rgba?\((\d+),(\d+),(\d+)(?:,([\d.]+))?\)$/);
			if (matched == null) {
				return value;
			}
			// 알파 값은 엑셀에서 표현할 수 없으므로, 완전히 투명한 경우에만 반영하지 않습니다.
			if (matched[4] != null && parseFloat(matched[4]) == 0) {
				return null;
			}
			let hex: string = "#";
			for (let i = 1; i <= 3; i++) {
				let channel: string = Number(matched[i]).toString(16);
				hex += (channel.length < 2) ? "0" + channel : channel;
			}
			return hex;
		}

		/**
		 * 계산 스타일의 폰트 목록에서 첫 번째 폰트명만 반환합니다.
		 * @param value 폰트 값.
		 */
		private static _normalizeFontFamily(value: string): string {
			if (value == null || value == "") {
				return null;
			}
			// 엑셀은 대체 폰트 목록을 지원하지 않으므로 첫 번째 폰트만 사용합니다.
			let fontName: string = value.split(",")[0].replace(/["']/g, "").replace(/^\s+|\s+$/g, "");
			return (fontName == "") ? null : fontName;
		}

		/**
		 * 계산 스타일의 text-decoration 값에서 라인 종류만 반환합니다.<br>
		 * 브라우저에 따라 "underline solid rgb(0, 0, 0)"과 같이 축약 속성 전체가 반환되므로 라인 종류만 추출합니다.
		 * @param value text-decoration 값.
		 */
		private static _normalizeTextDecoration(value: string): string {
			if (value == null || value == "") {
				return null;
			}
			let matched: RegExpMatchArray = value.match(/(underline|line-through|overline)/);
			return (matched != null) ? matched[1] : null;
		}

		/**
		 * 측정에 사용한 프로브 요소와 캐시를 정리합니다.
		 */
		public _dispose(): void {
			if (this._probeRow != null && this._probeRow.parentNode != null) {
				this._probeRow.parentNode.removeChild(this._probeRow);
			}
			this._probeRow = null;
			this._probeCell = null;
			this._probeControl = null;
			this._baseStyle = null;
			this._cache = {};
			this._controlCache = {};
			this._unavailable = false;
		}
	}
}
