/// <reference path="./Expression.ts"/>


namespace cpr.expression {
	/**
	 * cpr.expression.ComposedExpression에서 사용.
	 */
	export enum ComposeOperator {
		/**
		 * and 연산자
		 */
		AND,
		/**
		 * or 연산자
		 */
		OR
	}
	/**
	 * 복합적인 표현식을 사용하는 클래스.
	 */
	export class ComposedExpression extends Expression {
		private _operator: ComposeOperator;
		private _expressions: Expression[];

		/**
		 * 생성자. 비교 연산자와 비교할 표현식 배열을 입력합니다.
		 * @param operator 
		 * @param expressions 
		 */
		constructor(operator: ComposeOperator, expressions: Expression[]) {
			super(null);
			this._operator = operator;
			this._expressions = expressions;
		}

		override evaluateFirst(self?: any): any {
			return this.asFilter()(self) == true
		}

		override evaluateAll(self?: any): any[] {
			return [this.evaluateFirst(self)];
		}
		override evaluate(self?: any): any {
			return this.evaluateFirst(self);
		}

		public override and(...expressions: Expression[]): ComposedExpression {
			if (this._operator == ComposeOperator.AND) {
				return new ComposedExpression(ComposeOperator.AND, this._expressions.concat(expressions));
			}
			else {
				return super.and(...expressions);
			}
		}

		public override _and(...expressions: (Expression | Function)[]): ComposedExpression {
			if (this._operator == ComposeOperator.AND) {
				return new ComposedExpression(ComposeOperator.AND, _concatArray(this._expressions, expressions.map(_asExpression)));
			}
			else {
				return super._and(...expressions);
			}
		}

		public override or(...expressions: Expression[]): ComposedExpression {
			if (this._operator == ComposeOperator.OR) {
				return new ComposedExpression(ComposeOperator.OR, this._expressions.concat(expressions));
			}
			else {
				return super.or(...expressions);
			}
		}

		public override _or(...expressions: (Expression | Function)[]): ComposedExpression {
			if (this._operator == ComposeOperator.OR) {
				return new ComposedExpression(ComposeOperator.OR, _concatArray(this._expressions, expressions.map(_asExpression)));
			}
			else {
				return super._or(...expressions);
			}
		}

		/**
		 * 익스프레션을 mapper로 반환합니다.
		 */
		public override asMapper(): (e: any) => any {
			return (ctx: any) => {
				switch (this._operator) {
					case ComposeOperator.AND:
						return this._expressions.every(eachExp => eachExp.evaluateFirst(ctx));

					case ComposeOperator.OR:
						return this._expressions.some(eachExp => eachExp.evaluateFirst(ctx));
				}
			};
		}

		/**
		 * 익스프레션을 필터로 반환합니다.
		 */
		public override asFilter(): (e: any) => boolean {
			return (ctx: any) => {
				switch (this._operator) {
					case ComposeOperator.AND:
						return this._expressions.every(eachExp => eachExp.evaluateFirst(ctx));

					case ComposeOperator.OR:
						return this._expressions.some(eachExp => eachExp.evaluateFirst(ctx));
				}
			};
		}

		/**
		 * 익스프레션 값을 비교합니다.
		 */
		public override asComparator(): (a: any, b: any) => number {
			return (a, b): number => {
				switch (this._operator) {
					case ComposeOperator.AND: {
						for (let eachExp of this._expressions) {
							let eachResult = eachExp.asComparator()(a, b);
							if (eachResult !== 0) {
								return eachResult;
							}
						}
						return 0;
					}

					case ComposeOperator.OR: {
						let result = Number.MAX_VALUE;
						for (let eachExp of this._expressions) {
							let eachResult = eachExp.asComparator()(a, b);
							result = Math.min(eachResult, result);
						}
						return result;
					}
				}
			}
		}
	}
}