namespace cpr {
	/**
	 * 날짜 입력에 대한 지역 정보입니다.
	 * @private
	 */
	export interface ILocaleDateMaskLabel {
		/**
		 * 년도
		 */
		year: string
		/**
		 * 월
		 */
		month: string
		/**
		 * 일
		 */
		dayOfMonth: string
		/**
		 * 요일
		 */
		dayOfWeek: string
		/**
		 * 시간
		 */
		hour: string
		/**
		 * 분
		 */
		minute: string
		/**
		 * 초
		 */
		second: string
		/**
		 * 밀리초
		 */
		millisecond: string
		/**
		 * 오전/오후 대문자
		 */
		meridiemUppercase: string
		/**
		 * 오전/오후 소문자
		 */
		meridiemLowercase: string
	}

	/**
	 * @noinstance
	 * @private
	 */
	export class LocaleDateMaskLabel extends SubLocale implements ILocaleDateMaskLabel {

		public get year(): string {
			return this._getProperty(localeData => localeData.dateMaskLabel?.year);
		}
		public get month(): string {
			return this._getProperty(localeData => localeData.dateMaskLabel?.month);
		}
		public get dayOfMonth(): string {
			return this._getProperty(localeData => localeData.dateMaskLabel?.dayOfMonth);
		}
		public get dayOfWeek(): string {
			return this._getProperty(localeData => localeData.dateMaskLabel?.dayOfWeek);
		}
		public get hour(): string {
			return this._getProperty(localeData => localeData.dateMaskLabel?.hour);
		}
		public get minute(): string {
			return this._getProperty(localeData => localeData.dateMaskLabel?.minute);
		}
		public get second(): string {
			return this._getProperty(localeData => localeData.dateMaskLabel?.second);
		}
		public get millisecond(): string {
			return this._getProperty(localeData => localeData.dateMaskLabel?.millisecond);
		}
		public get meridiemUppercase(): string {
			return this._getProperty(localeData => localeData.dateMaskLabel?.meridiemUppercase);
		}
		public get meridiemLowercase(): string {
			return this._getProperty(localeData => localeData.dateMaskLabel?.meridiemLowercase);
		}

	}

}