/// <reference path="../events/DOMEventWrapper.ts"/>
/// <reference path="./AbstractDateMask.ts"/>
namespace cpr.foundation {

	/**
	 * @private
	 */
	class MaskSelection {

		private _start: number;
		private _end: number;
		private _text: string = "";
		public prevSelection: MaskSelection;
		public nextSelection: MaskSelection;
		public format: string;

		constructor(format: string, start: number, text: string) {
			this.format = format;
			this._start = start;
			this.setText(text);
		}

		public get start() {
			return this._start;
		}

		public get end() {
			return this._end;
		}

		public getRootSelection(): MaskSelection {
			if (!this.prevSelection) {
				return this;
			}
			return this.prevSelection.getRootSelection();
		}

		public contains(pos: number): boolean {
			return this._start <= pos && this._end > pos;
		}

		public setText(text: string) {
			let oldLen = this._text.length;
			let newLen = text.length;
			this._text = text;
			this._end = this._start + this._text.length;

			let next = this.nextSelection;
			let insertLen = newLen - oldLen;
			while (next != null) {
				next._setStart(next.start + insertLen);
				next = next.nextSelection;
			}
		}

		public getText(): string {
			return this._text;
		}

		private _setStart(start: number) {
			this._start = start;
			this._end = this._start + this._text.length;
		}

		public findMaskByFormat(format: string): MaskSelection {
			if (this.format == format) {
				return this;
			}
			if (this.nextSelection) {
				return this.nextSelection.findMaskByFormat(format);
			}
			return null;
		}

		public findMaskBySelectionStart(pos: number, closest: boolean = true): MaskSelection {
			let isFind = closest ? (pos < this._end || this.nextSelection == null) : this.contains(pos);
			if (isFind) {
				return this;
			}
			if (this.nextSelection) {
				return this.nextSelection.findMaskBySelectionStart(pos, closest);
			}
			return null;
		}

		public iterate(callback: (each: MaskSelection) => void) {
			callback(this);
			if (this.nextSelection) {
				this.nextSelection.iterate(callback);
			}
		}

	}

	/** 
	 * @private
	 */
	export class DateSegmentMask extends AbstractDateMask {
		static SKIPCODE: number[] = [
			events.KeyCode.TAB,
			events.KeyCode.ENTER,
			events.KeyCode.SHIFT,
			events.KeyCode.CTRL,
			events.KeyCode.ALT,
			events.KeyCode.PAUSE,
			events.KeyCode.CAPSLOCK,
			events.KeyCode.IME, // 한/영
			events.KeyCode.END,
			events.KeyCode.HOME,
			events.KeyCode.META, // win(left)
			events.KeyCode.NUMLOCK,
			events.KeyCode.SCROLLLOC,
			events.KeyCode.ESC,
		];

		/**
		 * 포맷 유형에 따라 regexp를 작성해야 합니다. 
		 * separator,format에 추가된 포맷 한글자를 넣어야 합니다.
		 */
		private static dateRegExp = {
			YYYY: /^[0-9]{4}$/, YY: /^[0-9]{2}$/, Y: /^[0-9]{4}$/,
			MM: /^0[1-9]|1[0-2]$/, M: /^([1-9]|1[0-2])$/,
			DD: /^(0[1-9]|[1-2][0-9]|3[0-1])$/, D: /^([1-9]|[1-2][0-9]|3[0-1])$/,
			HH: /^0[0-9]|1[0-9]|2[0-3]$/, H: /^([0-9]|1[0-9]|2[0-3])$/,
			hh: /^0[1-9]|1[0-2]$/, h: /^[1-9]|1[0-2]$/,
			kk: /^0[1-9]|1[0-9]|2[0-4]$/, k: /^([1-9]|1[0-9]|2[0-4])$/,
			mm: /^0[1-9]|[0-5][0-9]$/, m: /^[0-9]|[1-5][0-9]$/,
			ss: /^0[0-9]|[0-5][0-9]$/, s: /^0[0-9]|[1-5][0-9]$/,
			SSS: /^[0-9]{3}$/, SS: /^[0-9]{2}$/, S: /^[0-9]$/,
		};

		private static FORMAT_LENGTH = {
			YYYY: 4, YY: 2,
			MM: 2, M: 2,
			DD: 2, D: 2,
			HH: 2, hh: 2, kk: 2,
			mm: 2,
			ss: 2,
			SSS: 3, SS: 2, S: 1
		};

		private _maskOwner: DateMaskOwner;
		private _activateEvents: string[];
		private _input: InputObject;
		private _useFocusSelection: boolean = true;

		private _selection: { start: number, end: number } = { start: 0, end: 0 };

		private _mouseDownFlag: boolean = false; //마우스 다운으로 포커스를 받았을때 확인하기 위한 플래그
		private _isFirstAutoSelect: boolean = false; // 처음 오토 셀렉트 실행 여부

		private _listeners: { [key: string]: Function[] } = {};
		private _rootSelection: MaskSelection;

		// 속성
		private _format: () => string = () => { return "" };
		private _displayFormat: () => string = () => { return "" };
		private _getInputElement: () => HTMLInputElement = () => { return null };
		private _localFormat: string;
		public spinning: boolean = false;
		/**
		 * 이번 입력으로 autoSkip을 실행해도 되는지 여부. release-test-project#11071
		 */
		private _autoSkipAllowed: boolean = false;
		/**
		 * 이미 완성된 값을 편집하는 중인지 여부.
		 *
		 * 세그먼트 방식은 세그먼트에 입력을 시작하면 그 세그먼트를 먼저 비우므로, 두 번째 키부터는
		 * 값이 미완성으로 보인다. 그래서 키 하나가 아니라 편집이 끝날 때까지 상태를 유지한다.
		 * 포커스 진입·이탈, 값 재설정, 전체 선택 입력으로 해제된다. release-test-project#11071
		 */
		private _editingCompletedValue: boolean = false;

		constructor(owner: controls.DateInput, delegate: DateMaskDelegate) {
			super();
			this._maskOwner = owner;
			this._activateEvents = ["keydown", "mouseup", "mousedown"];
			this._initSelectionToken("datemask-selection");
			this._format = delegate.format;
			this._displayFormat = delegate.displayFormat;
			this._getInputElement = delegate.getInputElement;
		}

		protected get _owner(): DateMaskOwner {
			return this._maskOwner;
		}

		/**
		 * 스핀 동작 반복 여부를 반환합니다.
		 */
		public get spinLoop(): boolean {
			return this._spinLoop;
		}
		/**
		 * 스핀 동작 반복 여부를 설정합니다.
		 */
		public set spinLoop(loop: boolean) {
			this._owner.spinLoop = loop;
		}

		/**
		 * 마스크 포맷을 반환합니다.
		 */
		public get format(): string {
			return this._format();
		}

		private _getMaskFormat(): string {
			return this._displayFormat();
		}

		public get disposed() {
			return this._maskOwner == null;
		}

		/**
		 * 마스크 내부에서 사용하는 포맷.
		 */
		public get localFormat() {
			if (this._needUpdateFormat()) {
				this._applyFormat();
			}
			return this._localFormat;
		}

		private _needUpdateFormat() {
			return this._localFormat != this.format;
		}

		private _applyFormat() {
			this._localFormat = this.format;
			this._initSelection(this._localFormat);
		}

		private _initSelection(format: string) {
			this._rootSelection = this._parseFormat(format, (format, displays) => {
				return this._checkDisplayText(displays[format.charAt(0)]) ?? "";
			});
		}

		private _getRootSelection() {
			if (this._needUpdateFormat()) {
				this._applyFormat();
			}
			return this._rootSelection;
		}

		/**
		 * 세이프에 마스크에 필요한 이벤트를 설정합니다.
		 * @param shape 
		 */
		public wrap(shape: ufc.ControlShape): void {
			// shape redefine

			if (shape["events"] == undefined || shape["events"] == null) {
				shape["events"] = {};
			}
			if (this._readOnly) {
				return;
			}
			if (this._activateEvents.indexOf("keydown") > -1) {
				ufc.ShapeUtil.addEventHandler(shape, "keydown", (e) => this._onkeydown(e), true);
				ufc.ShapeUtil.addEventHandler(shape, "input", (e) => this._onInput(e), true);
				ufc.ShapeUtil.addEventHandler(shape, "beforeinput", (e) => this._onbeforeinput(e), true);
			}

			if (this._activateEvents.indexOf("mouseup") > -1) {
				ufc.ShapeUtil.addEventHandler(shape, "mouseup", (e) => this._onmouseup(e), true);
			}
			if (this._activateEvents.indexOf("mousedown") > -1) {
				ufc.ShapeUtil.addEventHandler(shape, "mousedown", (e) => this._onmousedown(e), true);
			}

			ufc.ShapeUtil.addEventHandler(shape, "focus", (e) => this._onfocus(e), true);
			// 브라우저에 따라 blur 또는 focusout 한쪽만 오는 경우가 있어 양쪽에 등록한다(IE는 blur가 다음 틱에 비동기로 발생).
			// 둘 다 발생하는 브라우저에서는 핸들러가 두 번 실행되므로, 입력 보정은 _onblur 안에서 한 번만 수행한다. release-test-project#11149
			ufc.ShapeUtil.addEventHandler(shape, "blur", (e) => this._onblur(e), true);
			ufc.ShapeUtil.addEventHandler(shape, "focusout", (e) => this._onblur(e), true);
			ufc.ShapeUtil.addEventHandler(shape, "paste", (e) => this._onpaste(e), true);
			ufc.ShapeUtil.addEventHandler(shape, "drop", (e) => this._ondrop(e), true);

		}

		/**
		 * 이벤트를 활성화합니다.
		 * @param eventName 
		 */
		public activateEvent(eventName: string) {
			this._activateEvents.push(eventName);
			this._activateEvents = _uniq(this._activateEvents);
		}
		/**
		 * 이벤트를 비활성화 합니다.
		 * @param eventName 
		 */
		public deactivateEvent(eventName: string) {
			let index = this._activateEvents.indexOf(eventName);
			this._activateEvents.splice(index, 1);
		}
		/**
		 * 포커스 셀렉션 동작 제어
		 * @param use 
		 */
		public useFocusSelection(use: boolean) {
			this._useFocusSelection = use;
		}
		/**
		 * 마우스 다운으로 포커스를 받았을때 확인하기 위한 플래그
		 */
		public mousedown() {
			this._mouseDownFlag = true;
		}

		public _deselect() {
			let input = this._getInputElement();
			if (input) {
				let ss = input.selectionStart;
				let se = input.selectionEnd;
				if (ss != se) {
					input.setSelectionRange(se, se);
				}
			}
		}

		public formatDiaplay(date: Date): string;
		public formatDiaplay(moment: moment.Moment): string;
		public formatDiaplay(obj: any): string {
			let mergeLocaleData: ILocaleDateTime = {};
			let meridiems = this.getMeridiems(this._locale);
			if (meridiems) {
				mergeLocaleData["meridiem"] = { am: meridiems[0], pm: meridiems[1] };
			}

			let mm: moment.Moment = _createMoment(() => {
				return moment(obj);
			}, this._locale, mergeLocaleData);

			return new DateMaskFormat(this._getMaskFormat()).format(mm);
		}

		private _adjustInputValue(input: HTMLInputElement) {
			let ss: number = input.selectionStart;
			let se: number = input.selectionEnd;
			let selectionCount = 0;
			this._getRootSelection().iterate(() => {
				selectionCount++;
			});
			if (ss == 0 && se == input.value.length && selectionCount > 1) {
				return;
			}

			let newValue: string = input.value;
			let currentMaskSelection = this._getRootSelection().findMaskBySelectionStart(ss);
			// 요일 마스크가 포함된 경우
			if (this._isDayOfWeekFormat(this.format, true)) {
				//요일 마스크가 중간에 있는 경우 파싱하기 위해 요일을 제외한 마스크로 모멘트를 생성하여 요일 텍스트 변경
				let validValue = "";
				let basicFormat = "";
				this._getRootSelection().iterate((each) => {
					if (!this._isDayOfWeekFormat(each.format)) {
						validValue += each.getText();
						basicFormat += each.format;
					}
				})
				let mm = this._createMomentForMask(validValue, basicFormat);
				this._getRootSelection().iterate((each) => {
					if (this._isDayOfWeekFormat(each.format)) {
						let dayOfweekFormat = mm.format(each.format);
						each.setText(dayOfweekFormat == "Invalid date" ? this.defaultText(each.format) : dayOfweekFormat);
					}
				});
			}
			let currentText = this._checkMaskValueWithPadding(currentMaskSelection.format, currentMaskSelection.getText());
			currentMaskSelection.setText(currentText);

			newValue = this._applyText();

			if (input.value != newValue) {
				input.value = newValue;
			}
		}

		private _onpaste(e: ClipboardEvent) {
			e.preventDefault();
			let inputTag: HTMLInputElement = e.target as HTMLInputElement;
			let clipboardData = e.clipboardData || window["clipboardData"];
			if (!clipboardData) {
				return;
			}
			let pasteValue = clipboardData.getData("text") as string;
			pasteValue = this._extractNumberText(pasteValue);
			if (!pasteValue) {
				return;
			}
			let ss = inputTag.selectionStart;
			let se = inputTag.selectionEnd;
			let isSelected = ss != se;
			if (isSelected == false) {
				return;
			}
			let inputValue = inputTag.value;
			this._input = new InputObject(inputValue, ss, se, InputLocation.paste);
			let result: string = null;

			if (ss == 0 && se == inputValue.length) {
				let mm = this._createMomentForMask(pasteValue, this.localFormat);
				if (mm.isValid()) {
					this._reset(mm);
					// 전체 선택 상태의 붙여넣기는 편집이 아니라 새 값 입력이므로 autoSkip을 허용한다. release-test-project#11071
					this._editingCompletedValue = false;
					this._autoSkipAllowed = true;
					result = this._applyText();
					ss = 0;
					se = result.length;
				}
			} else {
				let data = { keychar: pasteValue, ss: ss, se: se, text: inputValue };
				this._insert(data);
				result = data.text;
				ss = data.ss;
				se = data.se;
			}
			this._input.processed({ text: result, ss: ss, se: se });
			if (result) {
				inputTag.value = result;
				inputTag.setSelectionRange(ss, se);
				this._dispatchEvent("paste", e);
			}
		}

		/**
		 * 텍스트에서 숫자만 추출합니다.
		 * @param text 
		 * @returns 
		 */
		private _extractNumberText(text: string) {
			let matched = text.match(/\d+/g);
			if (!matched) {
				return null;
			}
			return matched.join("");
		}

		private _ondrop(e: DragEvent) {
			let transferData = e.dataTransfer.getData("text");
			if (!transferData) {
				e.preventDefault();
				return;
			}
			if (this._focused) {
				e.preventDefault();
				return;
			}
			let input = e.target as HTMLInputElement;
			let extractNumberText = this._extractNumberText(transferData);
			if (!extractNumberText) {
				e.preventDefault();
				return;
			}
			this._input = new InputObject(input.value, input.selectionStart, input.selectionEnd, InputLocation.drop);
			this._input.setData("transfer", transferData);

			this._dispatchEvent("drop", e);
		}

		private _onblur(e: FocusEvent) {
			let input = <HTMLInputElement>e.target;
			// blur와 focusout 양쪽에 등록되어 있어 한 번의 포커스 이탈에 두 번 실행될 수 있다.
			// 입력 보정은 먼저 도착한 이벤트에서 한 번만 수행한다. release-test-project#11149
			if (this._shouldAdjustOnBlur()) {
				this._adjustInputValue(input);
			}
			this.spinning = false;
			this._mouseDownFlag = false;
			this._autoSkipAllowed = false;
			this._editingCompletedValue = false;
		}

		private _onfocus(e: FocusEvent) {
			this._resetBlurAdjust();
			this._autoSkipAllowed = false;
			this._editingCompletedValue = false;
			if (this.spinning || this._input && this._input.from == InputLocation.drop) {
				return;
			}
			let input = <HTMLInputElement>e.target;
			let ownerValue = this._owner._getValue();

			if (ownerValue == "" || (ownerValue != "" && ownerValue && input.value == "")) {
				input.value = this.defaultText();
			}
			if (this._mouseDownFlag) {
				if (this._autoSelect) {
					this._isFirstAutoSelect = true;
				} else {
					this._isFirstAutoSelect = false;
					return;
				}
			}

			let ss: number, se: number;
			if (this._autoSelect) {
				ss = 0;
				se = input.value.length;
			} else {
				let sel = this._getDefaultSelection(this._defaultSelection);
				ss = sel.start;
				se = sel.end;
			}

			this._selection.start = ss;
			this._selection.end = se;
			if (this._useFocusSelection) {
				this._setInputSelection(input, ss, se);
			}

		}

		public initMask(input: HTMLInputElement) {
			this._resetBlurAdjust();
			if (this._owner._getValue() == "") {
				input.value = this.defaultText();
			}
			if (this._mouseDownFlag) {
				if (this._autoSelect) {
					this._isFirstAutoSelect = true;
				} else {
					this._isFirstAutoSelect = false;
				}
			}
		}

		/**
		 * 마스크포맷이 자릿수가 고정된 포맷문자로만 이루어져 있는지 여부 
		 * @returns
		 */
		public _isFixedLengthFormat(): boolean {
			// 자릿수가 고정되어있지 않은 포맷
			let unfixedLengthFormats = ["D", "M", "m", "h", "H", "s", "k"];
			let maskFormats = this.format.match(this._getAllowFormatRegExp());
			if (!maskFormats) {
				return true;
			}
			let isFixedLengthFormat = maskFormats.every(maskFormat => {
				return unfixedLengthFormats.indexOf(maskFormat) == -1;
			})

			return isFixedLengthFormat;
		}

		/**
		 * 텍스트가 완성된 날짜인지 여부를 반환합니다.
		 *
		 * 판정 포맷은 autoSkip 판정(DateInput._canAutoSkip)과 동일하게 지금 편집 중인 포맷을 사용합니다.
		 * 마스크를 사용하면 mask, 사용하지 않으면 value의 format이 됩니다. release-test-project#11071
		 * @param text 판정할 텍스트
		 * @returns 완성된 날짜인지 여부
		 */
		public _isCompletedText(text: string): boolean {
			if (!text) {
				return false;
			}
			let maskFormat = this.format;
			if (this._isDayOfWeekFormat(maskFormat, true)) {
				text = this._excludeDayofWeekText(text);
				maskFormat = this._excludeDayofWeekFormat(maskFormat);
			}
			return this._createMomentForMask(text, maskFormat, true).isValid();
		}

		/**
		 * 이번 입력으로 autoSkip을 실행해도 되는지 여부를 반환합니다.
		 * 이미 완성된 값을 편집하는 중이면 false를 반환합니다. release-test-project#11071
		 * @returns autoSkip 허용 여부
		 */
		public isAutoSkipValid(): boolean {
			return this._autoSkipAllowed;
		}

		public isSingleInputSegmentFormat(): boolean {
			let formats = this.format.match(this._getAllowFormatRegExp()) ?? [];
			let inputFormats = formats.filter((format) => {
				return !/^(d+|[aA])$/.test(format);
			});
			return inputFormats.length == 1;
		}

		private _onmouseup(e: events.CMouseEvent) {
			if (!this._focused) {
				return;
			}
			let input = <HTMLInputElement>e.target;
			this._mouseDownFlag = false;
			//FireFox에서 전체 selection되어 있는 경우 마우스 포인터로 셀렉션위치를 이동하는 동작이 있음.
			e.preventDefault();
			if (this._isFirstAutoSelect) {
				this._isFirstAutoSelect = false;
				if (this._autoSelect) {
					this._setInputSelection(input, this._selection.start, this._selection.end, true);
					return;
				}
			}

			let oldSs: number = this._selection.start;
			let oldSe: number = this._selection.end;
			let ss: number = input.selectionStart;
			let se: number = input.selectionEnd;

			if (ss != oldSs || se != oldSe) {
				let newValue: string = input.value;
				let oldMaskSelection = this._getRootSelection().findMaskBySelectionStart(oldSs);

				let currentMask: string = oldMaskSelection.format;
				let currentText: string;
				if (oldSs == oldSe || (oldSs == 0 && oldSe == newValue.length)) {
					oldSs = oldMaskSelection.start;
					oldSe = oldMaskSelection.end;
				}
				currentText = this._checkMaskValueWithPadding(currentMask, oldMaskSelection.getText());
				oldMaskSelection.setText(currentText);
				newValue = this._applyText();

				if (input.value != newValue) {
					let buffer = newValue.length - input.value.length;
					if (ss > oldSs && buffer > 0) {
						ss += buffer;
					}
					input.value = newValue;
				}
			}

			let currentMaskSelection = this._getRootSelection().findMaskBySelectionStart(ss);
			ss = currentMaskSelection.start;
			se = currentMaskSelection.end;

			this._setInputSelection(input, ss, se, true);

		}

		private _onmousedown(e: MouseEvent) {
			let input = e.target as HTMLInputElement;
			this._mouseDownFlag = true;

			if (!this._focused && !this._autoSelect) {
				// 브라우저 기본 동작이 캐럿을 놓은 뒤에 읽어야 하므로 렌더링 후로 미룬다.
				core.DeferredUpdateManager.INSTANCE.asyncExec(() => {
					this._selection.start = input.selectionStart;
					this._selection.end = input.selectionEnd;
				});
			} else if (this._focused) {
				this._selection.start = input.selectionStart;
				this._selection.end = input.selectionEnd;
			}

		}

		//IE에서 placeholder가 초기 설정되어 있는 경우 input이벤트가 실행되는 버그가 있음. 2019-07-19
		private _onInput(e: KeyboardEvent) {
			let input: HTMLInputElement = e.target as HTMLInputElement;

			if (this._input?.from == InputLocation.drop) {
				let value = input.value;
				let len = this._input.before.text.length;
				let startIndex = -1;
				for (let i = 0; i < len; i++) {
					let char = this._input.before.text.charAt(i);
					if (value.charAt(i) != char) {
						startIndex = i;
						break;
					}
				}
				if (startIndex == -1) {
					startIndex = len;
				}

				let dropValue = this._extractNumberText(this._input.getData("transfer"));
				let data = { keychar: dropValue, ss: startIndex, se: startIndex, text: this._input.before.text }
				this._insert(data);
				this._input.processed({ text: data.text, ss: data.ss, se: data.se });
				input.value = this._input.text;
				this._setInputSelection(input, this._input.selectionStart, this._input.selectionEnd, true);

			} else if (this._input) {
				input.value = this._input.text;
				// 텍스트를 대입하면 캐럿이 끝으로 가므로 바로 되돌린다. input 이벤트 시점에는 브라우저 기본 동작이
				// 끝나 있어 미룰 이유가 없고, 다음 프레임으로 미루면 그 사이에 도착한 키가 끝 캐럿 기준으로 처리되어
				// 마지막 세그먼트에 들어간다. 레거시 엣지는 _setInputSelection이 알아서 미룬다. release-test-project#11222
				this._setInputSelection(input, this._input.selectionStart, this._input.selectionEnd);
			}
		}

		private _onbeforeinput(e: cpr.events.CUIEvent) {
			if (this._input && (this._input.isProcessed() || this._input.from == InputLocation.drop)) {
				return;
			}

			let input = <HTMLInputElement>e.target;
			let char = e.data;
			if (!this._input) {
				this._input = new InputObject(input.value, input.selectionStart, input.selectionEnd);
			}
			let data = {
				keychar: char,
				ss: input.selectionStart,
				se: input.selectionEnd,
				text: input.value
			}

			this._insert(data);
			this._input.processed({ text: data.text, ss: data.ss, se: data.se });
			if (e.cancelable) {
				if (this._input.isChanged()) {
					this._input.apply(input);
				}
				e.preventDefault();
				return;
			}

		}

		private _onkeydown(e: events.CKeyboardEvent) {
			let keycode = e.keyCode;
			this._input = null;
			if (e.ctrlKey) { // metaKey는 맥의 커맨드키, 윈도우는 윈도우키
				if (!e._getMod2Key()) {
					if (keycode == events.KeyCode.Z) { //윈도우 undo
						e.preventDefault();
					} else if (keycode == events.KeyCode.Y) { //윈도우 redo
						e.preventDefault();
					}
				}
				return;
			} else if (e.metaKey) {
				let isMacOS = _detectBrowser().os.indexOf("OS X") > -1;
				if (isMacOS) {
					if (!e._getMod2Key() && keycode == events.KeyCode.Z) {//맥OS undo
						e.preventDefault();
					} else if (e._getMod2Key() && keycode == events.KeyCode.Z) {//맥OS redo
						e.preventDefault();
					}
				}
				return;
			} else if (e._getMod3Key()) {
				return;
			}

			let input = <HTMLInputElement>e.target;
			let ss = input.selectionStart;
			let se = input.selectionEnd;
			this._input = new InputObject(input.value, ss, se, InputLocation.keydown);

			if (keycode == events.KeyCode.TAB) {
				input.setSelectionRange(ss, ss);
				return;
			} else if (keycode == events.KeyCode.ENTER) {
				this._adjustInputValue(input);
				return;
			} else if (keycode == events.KeyCode.UP || keycode == events.KeyCode.DOWN) {
				// 방향키 위/아래에 의한 스핀은 DateInput 루트의 keydown 핸들러에서 _spinByKeydown()으로
				// 처리한다. 사용자 keydown 이벤트에서 preventDefault()를 호출한 경우 스핀이 동작하지
				// 않아야 하기 때문이다. release-test-project#11141
				return;
			} else if (DateSegmentMask.SKIPCODE.indexOf(keycode) > -1 || (keycode >= 112 && keycode <= 123)) {
				return;
			} else if (AbstractMask.BLOCKCODE.indexOf(keycode) > -1) {
				if (this._owner && this._owner.getParent() instanceof cpr.controls.Grid) {
					return;
				}
				e.preventDefault();
				return;
			}

			if (keycode == events.KeyCode.IME_INPUT) {
				return;
			}
			let isPressedModifierKeys = e._getMod1Key() || e._getMod2Key() || e._getMod3Key(); // 그리드에서 사용되는 ctrl 키는 혼합 사용 불가.
			if (isPressedModifierKeys) {
				return;
			}
			let data = {
				keychar: e.key,
				ss: ss,
				se: se,
				text: input.value
			}
			if (/[\d]/.test(data.keychar)) {
				this._insert(data);
			} else {
				this._keyboardAction(data, e);
			}

			if (keycode == events.KeyCode.LEFT || keycode == events.KeyCode.RIGHT) {
				let pos = keycode == events.KeyCode.LEFT ? data.ss + 1 : data.se - 1;

				if (input.value != data.text) {
					input.value = data.text;
				}
				input.setSelectionRange(pos, pos);
				this._setInputSelection(input, data.ss, data.se, true);
			} else {
				if (input.selectionStart == data.ss || (keycode == events.KeyCode.DOWN || keycode == events.KeyCode.UP)) {
					e.preventDefault();
					if (input.value != data.text) {
						input.value = data.text;
					}
					// 동시 키 또는 키가 길게 눌려지는 경우 selection이 마지막에 설정되어 마지막에 값이 입력되는 현상으로 타이머를 설정하지 않음.
					input.setSelectionRange(data.ss, data.se);
					this._dispatchEvent("input", e);
				} else {
					this._input.processed({ text: data.text, ss: data.ss, se: data.se })
					// Edge 브라우저의 keydown이벤트에서 setSelectionRange를 하는 경우 input 이벤트가 발생하지 않음. 순수 HTML에서는 정상 동작함.
				}
			}
		}

		/**
		 * 방향키 위/아래에 의한 세그먼트 스핀을 수행합니다.
		 *
		 * 입력 엘리먼트가 아닌 DateInput 루트에서 호출됩니다. 루트의 keydown 핸들러는 사용자
		 * 이벤트 다음에 실행되므로, 사용자가 keydown에서 preventDefault()를 호출하면 이 메서드가
		 * 호출되지 않아 스핀이 동작하지 않습니다. release-test-project#11141
		 *
		 * @param e 키보드 이벤트
		 * @return 스핀을 처리한 경우 true
		 */
		public _spinByKeydown(e: events.CKeyboardEvent): boolean {
			if (this._readOnly || this._owner.isOpened()) {
				return false;
			}
			let keycode = e.keyCode;
			if (keycode != events.KeyCode.UP && keycode != events.KeyCode.DOWN) {
				return false;
			}
			// 제어키 조합은 기본 동작 허용. 그리드에서 사용되는 ctrl 키는 혼합 사용 불가.
			if (e.ctrlKey || e.metaKey || e._getMod1Key() || e._getMod2Key() || e._getMod3Key()) {
				return false;
			}

			let input = <HTMLInputElement>e.target;
			let ss = input.selectionStart;
			let se = input.selectionEnd;
			this._input = new InputObject(input.value, ss, se, InputLocation.keydown);

			let data = {
				keychar: e.key,
				ss: ss,
				se: se,
				text: input.value
			}
			this._keyboardAction(data, e);

			e.preventDefault();
			if (input.value != data.text) {
				input.value = data.text;
			}
			// 동시 키 또는 키가 길게 눌려지는 경우 selection이 마지막에 설정되어 마지막에 값이 입력되는 현상으로 타이머를 설정하지 않음.
			input.setSelectionRange(data.ss, data.se);
			this._dispatchEvent("input", e);
			return true;
		}

		private _keyboardAction(data: { keychar: string, ss: number, se: number, text: string }, e: KeyboardEvent) {
			let keyCode = e.keyCode;
			let oldSS = data.ss;
			let oldSE = data.se;

			if ((data.ss == 0 && data.se == data.text.length)) { // 전체 선택되어 있는 경우 디폴트 셀렉션으로 변경
				let sel = this._getDefaultSelection(this._defaultSelection);
				data.ss = sel.start;
				data.se = sel.end;
			}
			let currentMaskSelection = this._getRootSelection().findMaskBySelectionStart(data.ss);
			let currentText: string;

			// 2. 키 입력 체크
			switch (keyCode) {
				case events.KeyCode.LEFT:
				case events.KeyCode.RIGHT:
					currentText = this._checkMaskValueWithPadding(currentMaskSelection.format, currentMaskSelection.getText());
					currentMaskSelection.setText(currentText);
					data.text = this._applyText();
					let nextSelection = keyCode == events.KeyCode.RIGHT ? currentMaskSelection.nextSelection : currentMaskSelection.prevSelection;
					if (nextSelection) {
						data.ss = nextSelection.start;
						data.se = nextSelection.end;
					} else {
						data.ss = currentMaskSelection.start;
						data.se = currentMaskSelection.end;
					}
					break;

				case events.KeyCode.UP:
				case events.KeyCode.DOWN:
					e.stopPropagation();
					let editInfo = this._editValue(keyCode == events.KeyCode.UP, currentMaskSelection, this.spinLoop);
					data.text = editInfo.value;
					data.se = editInfo.se;
					data.ss = editInfo.ss;

					break;
				case events.KeyCode.DELETE:
				case events.KeyCode.BACKSPACE:
					if (oldSS == 0 && oldSE == data.text.length) { //전체 셀렉트된 경우에는 기본 셀렉션으로 설정한다

						this._reset();
						data.text = this._applyText();
						let sel = this._getDefaultSelection(this._defaultSelection);
						data.ss = sel.start;
						data.se = sel.end;
						break;
					}

					let displayText = this._checkDisplayText(this.getDisplays(this._locale)[currentMaskSelection.format.charAt(0)]);
					currentText = this._checkMaskValueWithPadding(currentMaskSelection.format, currentMaskSelection.getText());

					if (displayText == currentText) { // 디스플레이 텍스트와 같은 경우 다음 셀렉션으로 이동한다
						let isDeleteKey: boolean = e.keyCode == events.KeyCode.DELETE;

						currentMaskSelection.setText(currentText);
						data.text = this._applyText();

						let nextSelection = isDeleteKey ? currentMaskSelection.nextSelection : currentMaskSelection.prevSelection;
						if (nextSelection) {
							data.ss = nextSelection.start;
							data.se = nextSelection.end;
						} else {
							data.ss = currentMaskSelection.start;
							data.se = currentMaskSelection.end;
						}

					} else {
						currentMaskSelection.setText(displayText);
						data.text = this._applyText();
						data.se = currentMaskSelection.end;
					}

					break;
			} // switch

		}

		private _getAllowFormatRegExp() {
			return new RegExp(DateMaskFormat.ALLOW_FORMAT_PATTERN, "g");
		}

		private _getFormatByDefaultSelection(defaultSelection: string): string {
			let formats = this.localFormat.match(this._getAllowFormatRegExp()) ?? [];
			return this._getFormatByDefaultDateSelection(defaultSelection, formats);
		}

		public _getDefaultSelection(defaultSelection: string): MaskSelection {

			let sel = this._getRootSelection();
			let format = this._getFormatByDefaultSelection(defaultSelection);
			if (format) {
				sel = this._getRootSelection().findMaskByFormat(format);
			}
			return sel;
		}

		/**
		 * 마스크를 날짜 또는 초기값으로 재설정 합니다.
		 * @param mm 
		 */
		public _reset(date: Date): void
		public _reset(mm: moment.Moment): void
		public _reset(): void
		public _reset(obj?: any): void {
			this._autoSkipAllowed = false;
			this._editingCompletedValue = false;
			let mm: moment.Moment = obj;
			if (mm instanceof Date) {
				mm = this._createMomentForMask(mm);
			}
			if (mm && mm.isValid()) {
				this._getRootSelection().iterate((each: MaskSelection) => {
					each.setText(mm.format(each.format));
				})
			} else {
				if (this._needUpdateFormat()) {
					this._applyFormat();
				} else {
					this._initSelection(this.localFormat);
				}
			}
		}

		public _excludeDayofWeekText(inputText: string): string {
			let locale = this._locale;
			let defaultText = this.getDisplays(locale)["d"];

			let excludeText = inputText.replace(defaultText, "").trim();
			let weekdays = [
				"월요일", "화요일", "수요일", "목요일", "금요일", "토요일", "일요일",
				"월", "화", "수", "목", "금", "토", "일"
			];
			if (locale == "en") {
				weekdays = [
					"Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday",
					"Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun",
					"Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"
				];
			}

			for (let dayofWeek of weekdays) {
				if (defaultText)
					if (excludeText.indexOf(dayofWeek) > -1) {
						excludeText = excludeText.replace(dayofWeek, "").trim();
						break;
					}
			}
			return excludeText;
		}

		public _excludeDayofWeekFormat(mask: string): string {
			let excludeMaskFormat = "";
			let dayOfWeekFormats = ["dddd", "ddd", "dd"];
			for (const dayOfWeek of dayOfWeekFormats) {
				if (mask.indexOf(dayOfWeek) > -1) {
					excludeMaskFormat = mask.replace(dayOfWeek, "").trim();
					break;
				}
			}
			return excludeMaskFormat;
		}

		private _insert(data: { keychar: string, ss: number, se: number, text: string }) {
			let oldSS = data.ss;
			let oldSE = data.se;
			let oldText = data.text;

			let formats = this.localFormat.match(this._getAllowFormatRegExp()) ?? [];
			let currentText: string;
			let currentMaskSelection = this._rootSelection.findMaskBySelectionStart(data.ss);
			let currentMask: string = currentMaskSelection.format;
			if (this._isDayOfWeekFormat(currentMask)) return;
			if (data.ss == data.se || (data.ss == 0 && data.se == data.text.length)) {
				data.ss = currentMaskSelection.start;
				data.se = currentMaskSelection.end;
			}
			let display = this.getDisplays(this._locale);
			let regex = /[\d]/;
			// 3. 입력된 값 체크
			if (regex.test(data.keychar) && /[aA]/.test(currentMask) == false) {
				if (oldSS == 0 && oldSE == oldText.length && formats.length > 1) {

					this._reset();
					currentMaskSelection = this._rootSelection.findMaskByFormat(currentMask);
					data.text = this._applyText();
					data.ss = currentMaskSelection.start;
					data.se = currentMaskSelection.end;
					//전체 셀렉트 했을때 삭제. 드래그한 셀렉션에도 삭제가 가능하도록 수정 필요?
				}
				// 이미 완성된 값을 편집하는 중에는 autoSkip을 실행하지 않는다. release-test-project#11071
				// 전체 선택 입력은 위에서 버퍼가 초기화되므로 편집이 아닌 새 값 입력으로 판정된다.
				// 세그먼트가 하나인 포맷은 입력을 시작하면 세그먼트가 비워져 값 전체를 새로 입력하는 것이므로 편집으로 보지 않는다.
				if (this.isSingleInputSegmentFormat()) {
					this._editingCompletedValue = false;
				} else if (this._isCompletedText(data.text)) {
					this._editingCompletedValue = true;
				}
				this._autoSkipAllowed = !this._editingCompletedValue;
				currentText = currentMaskSelection.getText();
				//default 마스크 text인지 체크하고, 년인 경우 기본 패딩값을 지정한다.
				if (currentText == this._checkDisplayText(display[currentMask.charAt(0)]) || this._canMoveCaret(currentMask, currentText)) {
					currentMaskSelection.setText("");
					currentText = currentMaskSelection.getText();
				}

				//마스크 값이 유효한지 체크
				currentText = this._checkMaskValue(currentText + data.keychar, currentMask);
				currentMaskSelection.setText(currentText);

				data.text = this._applyText();
				data.se = currentMaskSelection.end;

				let canMoveCaret = this._canMoveCaret(currentMask, currentMaskSelection.getText());
				if (canMoveCaret) {
					currentText = this._checkMaskValueWithPadding(currentMask, currentText);
					currentMaskSelection.setText(currentText);
					if (currentMaskSelection.nextSelection) {
						data.ss = currentMaskSelection.nextSelection.start;
						data.se = currentMaskSelection.nextSelection.end;
					}
					data.text = this._applyText();
				}

			}
		}

		/**
		 * 다음 셀렉션으로 넘어가도 되는지 체크한다.
		 * @param currentMask 
		 * @param value 
		 * @returns 
		 */
		private _canMoveCaret(currentMask: string, value: string) {
			let result = false;
			let fillCheckRegExp = {
				M: /^(0[1-9]|1[0-2])$/,
				D: /^(0[1-9]|[1-2][0-9]|3[0-1])$/,
				H: /^(0[0-9]|1[0-9]|2[0-3])$/,
				h: /^0[1-9]|1[0-2]$/,
				k: /^(0[1-9]|1[0-9]|2[0-4])$/,
				m: /^[0-5][0-9]$/,
				s: /^[0-5][0-9]$/,
				S: /^[0-9]{3}$/
			};
			let checkRegExp = fillCheckRegExp[currentMask] ?? DateSegmentMask.dateRegExp[currentMask];
			if (!checkRegExp) {
				return result;
			}

			if (checkRegExp.test(value)) {
				result = true;
			}

			return result;
		}

		private _checkMaskValue(maskedValue: string, currentMask: string) {
			let regex = DateSegmentMask.dateRegExp[currentMask];
			if (!regex || /[\d]+/.test(maskedValue) == false) {
				return maskedValue;
			}
			maskedValue = maskedValue.length > DateSegmentMask.FORMAT_LENGTH[currentMask] ? maskedValue.substring(maskedValue.length - DateSegmentMask.FORMAT_LENGTH[currentMask], maskedValue.length) : maskedValue;
			let ignoreMask = ["Y", "S"];
			//년도는 무시
			if (ignoreMask.indexOf(currentMask.charAt(0)) == -1 && regex.test(maskedValue) == false) {
				maskedValue = maskedValue.substring(maskedValue.length / 2, maskedValue.length);
			}

			return maskedValue;
		}

		private _checkMaskValueWithPadding(currentMask: string, maskedValue: string): string {
			let regex = DateSegmentMask.dateRegExp[currentMask];
			if (!regex || /[\d]+/.test(maskedValue) == false) {
				return maskedValue;
			}
			//유효한 날짜 체크
			maskedValue = this._checkMaskValue(maskedValue, currentMask);
			//마스크 포맷에 따른 0값 추가
			maskedValue = this._addPadding(maskedValue, currentMask);
			//값이 0인경우 가이드하는 텍스트로 변환
			maskedValue = this._checkZeroNumber(maskedValue, currentMask);
			return maskedValue;
		}

		private _checkZeroNumber(value: string, mask: string): string {
			let ignoreMask = ["YYYY", "YY", "HH", "H", "hh", "h", "kk", "k", "mm", "m", "ss", "s", "S", "SS", "SSS"];
			let checkZero = /^[0]+$/;
			if (checkZero.test(value) && ignoreMask.indexOf(mask) == -1) {

				let displayText = this._checkDisplayText(this.getDisplays(this._locale)[mask.charAt(0)]);
				value = displayText ? displayText : mask;

			}
			return value;
		}

		private _addPadding(value: string, mask: string): string {

			let pad = {
				YYYY: "0000", YY: "00",
				MM: "00",
				DD: "00",
				HH: "00", hh: "00", kk: "00",
				mm: "00",
				ss: "00",
				SSS: "000", SS: "00"
			};

			if (pad[mask]) {
				value = pad[mask] + value;
				value = value.substring(value.length - DateSegmentMask.FORMAT_LENGTH[mask], value.length);
			}
			return value;
		}

		/**
		 * 날짜 텍스트를 해석하여 셀렉션 정보를 반환합니다.
		 * @param format 마스크 포맷
		 * @returns 
		 */
		private _parseFormat(format: string, defaultText: (format: string, displays: {}) => string): MaskSelection {
			let formats = format.match(this._getAllowFormatRegExp());
			if (!formats) {
				return new MaskSelection("", 0, "");
			}
			let currentSelection: MaskSelection = null;
			let lastIndex = 0;
			formats.forEach((each: string) => {
				let rangedText = format.substring(lastIndex);
				let index = rangedText.indexOf(each);
				if (currentSelection) {
					let nextSelection = new MaskSelection(each, lastIndex + index, each);
					currentSelection.nextSelection = nextSelection;
					nextSelection.prevSelection = currentSelection;

					currentSelection = nextSelection;
				} else {
					currentSelection = new MaskSelection(each, lastIndex + index, each);
				}
				lastIndex += index + each.length;
			});
			let rootSelection = currentSelection;
			if (currentSelection) {
				rootSelection = currentSelection.getRootSelection();
			}
			let displays = this.getDisplays(this._locale);
			rootSelection.iterate((each) => {
				each.setText(defaultText(each.format, displays));
			});
			return rootSelection;
		}

		private _applyText(maskSelection?: MaskSelection, selectionFormat?: string): string {
			let result = [];
			let regexp = new RegExp(`${DateMaskFormat.ALLOW_FORMAT_PATTERN}|${DateMaskFormat.SEPARATOR_PATTERN}`, "g");
			if (!maskSelection) {
				maskSelection = this._rootSelection;
			}
			if (!selectionFormat) {
				selectionFormat = this.localFormat;
			}
			let formats = (selectionFormat.match(regexp) ?? []) as Array<any>; // 모든 포맷과 구분자를 배열로 분리

			maskSelection.iterate((each) => {
				let index = formats.indexOf(each.format);
				formats[index] = "";
				result[index] = each.getText();
			});
			_defaults(result, formats);//result 인덱스 중에 값이 없는 것들을 formats로 채움
			return result.join("");
		}
		/**
		 * 마스크에서 기본 표시 텍스트를 반환합니다.
		 * @returns 
		 */
		public defaultText(format?: string): string {
			let display = this.getDisplays(this._locale);
			let regexp = new RegExp(`${DateMaskFormat.ALLOW_FORMAT_PATTERN}|${DateMaskFormat.SEPARATOR_PATTERN}`, "g");
			if (!format) {
				format = this.localFormat;
			}
			let formats = format.match(regexp) ?? []; // 모든 포맷과 구분자를 배열로 분리
			formats.forEach((each: string, idx: number) => {
				let text = display[each.charAt(0)];
				if (text) {
					formats[idx] = this._checkDisplayText(text);
				}
			});
			return formats.join("");
		}

		private _getMomentManipulateKeys() {
			return {
				"YYYY": "years", "YY": "years", "Y": "years",
				"MM": "months", "M": "months",
				"DD": "days", "D": "days",
				"dddd": "days", "ddd": "days", "dd": "days",
				"HH": "hours", "H": "hours", "hh": "hours", "h": "hours", "kk": "hours", "k": "hours",
				"mm": "minutes", "m": "minutes",
				"ss": "seconds", "s": "seconds",
				"SSS": "ms", "SS": "ms", "S": "ms"
			};
		}

		private _getMomentGetSetKeys() {
			let result = this._getMomentManipulateKeys();
			result.DD = "dates";
			result.D = "dates";
			return result;
		}

		public _isDayOfWeekFormat(format: string, includeFormat: boolean = false): boolean {
			if (includeFormat) {
				return /[dd]/.test(format);
			}
			return this._getMaskKey(format) == "dddd";
		}



		/**
		 * 다음 날짜 값이 유효한지 체크하여 올바른 값으로 반환합니다.
		 * @param originDateNum fallback value
		 * @param nextDateNum 반영할 값
		 * @param dateValue 
		 * @param mask 
		 * @param format 
		 * @returns 
		 */
		private _checkDate(originDateNum: number, nextDateNum: number, currentMaskSelection: MaskSelection): number {
			if (isNaN(nextDateNum)) {
				return nextDateNum;
			}

			let dateFormat = this._getMaskKey(currentMaskSelection.format);
			let checkDateProp = {
				"YYYY": { max: 9999, min: 1 },
				"YY": { max: 99, min: 0 },
				"MM": { max: 12, min: 1 },
				"DD": { max: 31, min: 1 },
				"dddd": { max: 31, min: 1 },
				"HH": { max: 23, min: 0 },
				"hh": { max: 12, min: 1 },
				"kk": { max: 24, min: 1 },
				"mm": { max: 59, min: 0 },
				"ss": { max: 59, min: 0 },
				"S": { max: 9, min: 0 },
				"SS": { max: 99, min: 0 },
				"SSS": { max: 999, min: 0 }
			}
			let prop = checkDateProp[dateFormat];
			if (!prop) {
				return originDateNum;
			}
			if (dateFormat == "DD" || dateFormat == "dddd") {
				let mm = this.getMaskMoment();
				if (mm.isValid()) {
					prop = { max: mm.daysInMonth(), min: 1 }
				}
			}

			if (nextDateNum > prop.max) {
				nextDateNum = prop.min;
			} else if (nextDateNum < prop.min) {
				nextDateNum = prop.max;
			} else {
				nextDateNum = Math.max(Math.min(nextDateNum, prop.max), prop.min);
			}
			return nextDateNum;
		}

		private _getMaskKey(mask: string) {
			let key = "";
			if (/^Y$/.test(mask) || /^YYYY$/.test(mask)) {
				key = "YYYY";
			} else if (/^YY$/.test(mask)) {
				key = "YY";

			} else if (/^[M]+$/.test(mask)) {
				key = "MM";
			} else if (/^[D]+$/.test(mask)) {
				key = "DD";
			} else if (/^[d]+$/.test(mask)) {
				key = "dddd";
			} else if (/^[H]+$/.test(mask)) {
				key = "HH";
			} else if (/^[h]+$/.test(mask)) {
				key = "hh";
			} else if (/^[k]+$/.test(mask)) {
				key = "kk";
			} else if (/^[m]+$/.test(mask)) {
				key = "mm";
			} else if (/^[s]+$/.test(mask)) {
				key = "ss";
			} else if ("S" == mask) {
				key = "S";
			} else if ("SS" == mask) {
				key = "SS";
			} else if ("SSS" == mask) {
				key = "SSS";
			}
			return key;
		}

		private _editValue(increment: boolean, currentMaskSelection: MaskSelection, isSpinLoop: boolean) {

			let mm = this.getMaskMoment(true);
			let currentMask = currentMaskSelection.format;
			let owner = this._owner;

			if (!isSpinLoop && mm.isValid()) {

				let momentKeyList = this._getMomentManipulateKeys();
				let momentKey = momentKeyList[currentMask];

				if (momentKey) {
					let defaultVal = { "SS": 10, "S": 100 };
					let count = defaultVal[currentMask] ? defaultVal[currentMask] : 1;
					if (increment) {
						let incrementMoment = mm.clone().add(count, momentKey);
						if (!incrementMoment.isAfter(owner.maxDate)) {
							mm = incrementMoment;
						}
					} else {
						let decrementMoment = mm.clone().subtract(count, momentKey);
						if (!decrementMoment.isBefore(owner.minDate)) {
							mm = decrementMoment;
						}
					}
					this._reset(mm);
				}

			} else {
				let currentText = currentMaskSelection.getText();
				let numberValue = parseInt(currentText);
				let delta = increment ? 1 : -1;
				let stringValue = "";
				if (this._isDayOfWeekFormat(currentMask)) {
					let date = mm.date();
					if (mm.isValid() == false) { //값이 완성되지 않은 상태에서 상/하향키 이동 시
						let dateString = "";
						let format = "";
						this._rootSelection.iterate((each) => {
							if (each.format != currentMask) {
								dateString += each.getText();
								format += each.format;
							}
						})
						let tempMm = this._createMomentForMask(dateString, format);
						stringValue = tempMm.format(currentMask);
						date = tempMm.date();
					}
					numberValue = this._checkDate(date, date + delta, currentMaskSelection);
				} else {
					numberValue = this._checkDate(numberValue, numberValue + delta, currentMaskSelection); // 편집하는 값 증가 또는 감소
					stringValue = String(numberValue);
				}
				if (mm.isValid()) { // 날짜가 있는 경우 날짜 기준으로 유효성 검사한다
					if (currentMask == "MM") {
						mm.set(this._getMomentGetSetKeys()[currentMask], numberValue - 1);
					} else if (currentMask == "YY") {
						let year = mm.format("YYYY");
						let nextYear = parseInt(year.substring(0, 2) + "00") + numberValue;
						mm.set(this._getMomentGetSetKeys()[currentMask], nextYear);
					} else if (this._isDayOfWeekFormat(currentMask)) {
						mm.set(this._getMomentGetSetKeys().DD, numberValue);
						this._reset(mm);
						stringValue = mm.format(currentMask);
					} else {
						mm.set(this._getMomentGetSetKeys()[currentMask], numberValue);
					}
					if (mm.isAfter(owner.maxDate) || mm.isBefore(owner.minDate)) {
						stringValue = String(parseInt(currentText));
					}
				}

				if (isNaN(numberValue) && /[aA]/.test(currentMask) == false) {
					//날짜, 시간 초기값으로 변경
					mm = this._createMomentForMask(this._defaultDate);

					if (moment(owner.minDate).isSameOrBefore(owner.maxDate)) {
						if (mm.isAfter(owner.maxDate)) {
							mm = this._createMomentForMask(owner.maxDate);
						} else if (mm.isBefore(owner.minDate)) {
							mm = this._createMomentForMask(owner.minDate);
						}
					} else {
						mm = null;
					}

					this._reset(mm);

				} else if (/[aA]/.test(currentMask)) {
					//오전/오후 값 변경
					let meridiem = this.getMeridiems(this._locale);
					let index = meridiem.indexOf(currentText);
					let text = meridiem[index == -1 ? 0 : Math.abs(index - 1)];
					if (currentMask == "A") {
						text = text.toLocaleUpperCase();
					}
					currentMaskSelection.setText(text);

				} else {
					// 요일포맷이 아닌 포맷 셀렉션에서 스핀동작하는 경우
					if (!this._isDayOfWeekFormat(currentMask) && this._isDayOfWeekFormat(this.format, true) && mm.isValid()) {
						this._getRootSelection().iterate((each) => {
							if (this._isDayOfWeekFormat(each.format)) {
								mm.set(each.format, mm.day());
							}
						})
						this._reset(mm);
					}
					//날짜 시간 값 변경
					currentText = this._checkMaskValueWithPadding(currentMask, stringValue);
					currentMaskSelection.setText(currentText);
				}

			}

			return { value: this._applyText(), ss: currentMaskSelection.start, se: currentMaskSelection.end };
		}

		public spin(up: boolean, allSelected: boolean, selectionStart: number, defaultSelection?: string): { value: string, ss: number, se: number } {
			let currentMaskSelection = this._rootSelection.findMaskBySelectionStart(selectionStart);

			if (allSelected) { // 전체 선택
				let format = this._getFormatByDefaultSelection(defaultSelection ? defaultSelection : this._defaultSelection);
				if (format) {
					currentMaskSelection = this._rootSelection.findMaskByFormat(format);
				}
			}

			let editInfo = this._editValue(up, currentMaskSelection, this.spinLoop);

			return { value: editInfo.value, ss: editInfo.ss, se: editInfo.se };
		}

		public getMaskMoment(strict: boolean = false): moment.Moment {
			let collectedMaskText = [];
			this._getRootSelection().iterate((each) => {
				if (!this._isDayOfWeekFormat(each.format)) {
					collectedMaskText[collectedMaskText.length] = each.getText();
				}
			});

			let separatedMaskText = collectedMaskText.join("/");
			let formats = this.localFormat.match(this._getAllowFormatRegExp()).filter((format) => {
				return !this._isDayOfWeekFormat(format);
			}) ?? [];
			let format = formats.join("/");
			return this._createMomentForMask(separatedMaskText, format, strict);
		}

		/**
		 * value에 사용되는 값은 고정된 locale을 사용합니다.
		 * @param originValue 
		 * @param originValueFormat 
		 * @returns 
		 */
		public mergeMaskValue(originValue: string, originValueFormat: string): moment.Moment {
			// #3174 이슈
			let maskValueMoment: moment.Moment = this.getMaskMoment(true);
			if (maskValueMoment.isValid() == false) {
				return null;
			} else if (!originValue) {
				return maskValueMoment;
			}

			let formats = this.localFormat.match(this._getAllowFormatRegExp());
			let mmGet = this._getMomentGetSetKeys();
			let result = {};
			if (formats) {
				formats.forEach((fm: string) => {
					if (mmGet[fm]) {
						result[fm] = maskValueMoment.get(mmGet[fm]);
					}
				});
			}

			let originValueMoment = this._createMomentForValue(originValue, originValueFormat);
			let valueMoment = originValueMoment.isValid() ? originValueMoment : maskValueMoment;

			for (let each in result) {
				valueMoment.set(mmGet[each], result[each]);
			}

			return valueMoment;
		}

		/**
		 * 이벤트를 전달 합니다.
		 * @param e 이벤트(현재는 마우스 이벤트)
		 */
		private _dispatchEvent(type: string, e?: Event): boolean {
			let dispatchEvent = true;

			if (!this._listeners[type]) {
				return dispatchEvent;
			}

			this._listeners[type].forEach((each: Function) => {
				each(e);
			});
			if (e) {
				dispatchEvent = !e.defaultPrevented;
			}
			return dispatchEvent;
		}

		/**
		 * @private
		 * @param type 
		 * @param func 
		 */
		public addEventListener(type: string, func: Function) {
			if (!this._listeners[type]) {
				this._listeners[type] = [];
			}
			this._listeners[type].push(func);
		}

		/**
		 * @private
		 * @param type 
		 * @param func 
		 */
		public removeEventListener(type, func) {
			if (!this._listeners[type]) {
				return;
			}
			let idx = this._listeners[type].indexOf(func);
			if (idx > -1) {
				this._listeners[type].splice(idx, 1);
			}
		}

		/**
		 * @private
		 * @param type 
		 */
		public removeAllEventListener(type) {
			if (!this._listeners[type]) {
				return;
			}
			this._listeners[type] = [];
		}

		/**
		 * @private
		 */
		public dispose() {
			this._listeners = null;
			this._maskOwner = null;
			this._rootSelection = null;
		}

	}

}
