		public override _getRowValues(rowIndex: number, columnIndices: number[]): (string | number)[] {
			if (utils.ParamUtil.isInRange(rowIndex, 0, (this.getRowCount() - 1)) == false) {
				return null;
			}
			let result: (string | number)[] = [];
			let rowData: tabledata.RowData = this._viewTable._getRowData(rowIndex);
			let colCnt: number = columnIndices.length;
			for (let i: number = 0; i < colCnt; i++) {
				let colIdx: number = columnIndices[i];
				let dataHeader: header.Header = this._getHeaderFromIndex(colIdx);
				let value: any = null;
				if (dataHeader._isExpressionHeader()) {
					let exprHeader: header.ExpressionHeader = dataHeader as header.ExpressionHeader;
					let func: Function = exprHeader.getFunction();
					if (func != null) {
						value = func(new Row(this, rowIndex));
					}
				} else {
					value = rowData.getValue(colIdx);
					if (value != null && value instanceof foundation.DecimalType) {
						value = (value as foundation.DecimalType).toNumber();
					}
				}

				result[result.length] = value;
			}

			return result;
		}

