		public override revert(): void {
			this._dataTable._revert();

			// viewTable에서 제거된 후에 이벤트 디스패치를 하기 위해 dataTable이 아닌 dataView에 추가함.
			// dataTable로 이동
			// this.dispatchEvent(new events.CDataEvent(events.DataEventType._REVERT));
		}

		public override revertRow(rowIndex: number): void {
			if (utils.ParamUtil.isInRange(rowIndex, 0, (this.getRowCount() - 1)) == false) {
				return;
			}
			/*
			존재하는 하나의 Row를 복원하고 싶은 경우
			사용자가 입력 받은 rowIndex의 경우 view기준 index 이므로
			INSERTED, UPDATED, UNCHANGED 상태의 row만 접근이 가능하다.
			=> (16/12/08) 모든 상태의 view에 존재할 수 있다. 사용자가 필터링에 의해 걸러짐.
			UNCHANGED 상태도 revertRow 할수 있도록 할것! (수정 후 setState로 상태만 UNCHANGED로 바꾼경우 originalValue와 currentValue가 다를 수 있음.)
			*/
			let rowState: tabledata.RowState = this._getRowState(rowIndex);
			let rowData: tabledata.RowData = this._viewTable._getRowData(rowIndex);
			let orgRowIndex: number = this._dataTable._indexOf(rowData);

			if (rowState == tabledata.RowState.INSERTED || rowState == tabledata.RowState.INSERTDELETED) {
				// viewTable에서 제거만 함. (rowData에 대한 값/상태 변경은 하지 않음.)
				this._viewTable._realDeleteRow(rowIndex);
			}

			this._dataTable._revertRow(orgRowIndex); // dataTable에서 이벤트 처리 하기위해서 viewTable 제거와 dataTable 제거 순서 변경

			// viewTable에서 제거된 후에 이벤트 디스패치를 하기 위해 dataTable이 아닌 dataView에 추가함.
			// this.dispatchEvent(new events.CDataEvent(events.DataEventType._REVERT_ROW));
		}

		public override setRowState(rowIndex: number, state: tabledata.RowState): void {
			let row: IDataRow = this.getRow(rowIndex);
			if (row) {
				let beforeState: tabledata.RowState = row.getState();
				row.setState(state);

				this.dispatchEvent(new events.CDataEvent(events.DataEventType._UPDATE_STATE, {
					beforeState: beforeState,
					currentState: state
				}));
			}
		}

