		public override setRowStateRanged(state: tabledata.RowState, startIndex: number = 0, endIndex: number = (this.getRowCount() - 1)): void {
			// TODO : state 예외처리 필요
			if (utils.ParamUtil.isInRange(startIndex, 0, this.getRowCount() - 1) == false) {
				return;
			}
			if (utils.ParamUtil.isInRange(endIndex, 0, this.getRowCount() - 1) == false) {
				return;
			}

			this._viewTable._setRowStateRanged(state, startIndex, endIndex);

			this.dispatchEvent(new events.CDataEvent(events.DataEventType._UPDATE_STATE, {
				currentState: state,
			}));
		}

