		public override getRowDatasByState(state: tabledata.RowState, columnType: header.HeaderType = header.HeaderType.ALL): { [key: number]: RowConfigInfo[] } {
			// FIXME : performance
			if (state == null) {
				return null;
			}

			let result: { [state: number]: RowConfigInfo[] } = {};
			let rowIndicesByState: { [state: number]: number[] } = this.getRowIndicesByState(state);
			let states: string[] = Object.keys(rowIndicesByState);
			let stateLength: number = states.length;
			for (let i = 0; i < stateLength; i++) {
				let rowIndices: number[] = rowIndicesByState[states[i]];
				let rowCount = rowIndices.length;
				result[states[i]] = [];
				for (let j = 0; j < rowCount; j++) {
					result[states[i]].push(this.getRowData(rowIndices[j], columnType));
				}
			}
			return result;
		}

		public override isModified(): boolean {
			let parentRowId: string = this.getBindedParentRowId();
			if (parentRowId == null) {
				return this._dataTable._isModified();

			} else {
				let result: boolean = false;
				let cudRowInfo: CUDRowInfo = this._dataTable.cudRowInfo;
				let BindedPRowId: string = this.getBindedParentRowId();
				{
					let insertedRows: tabledata.RowData[] = cudRowInfo._getInsertRows();
					let rowCount: number = insertedRows.length;
					for (let i = 0; i < rowCount; i++) {
						if (BindedPRowId == insertedRows[i]._getCategory()) {
							result = true;
							break;
						}
					}
				}
				if (result == false) {
					let updatedRows: tabledata.RowData[] = cudRowInfo._getUpdateRows();
					let rowCount: number = updatedRows.length;
					for (let i = 0; i < rowCount; i++) {
						if (BindedPRowId == updatedRows[i]._getCategory()) {
							result = true;
							break;
						}
					}
				}
				if (result == false) {
					let deletedRows: tabledata.RowData[] = cudRowInfo._getDeleteRows();
					let rowCount: number = deletedRows.length;
					for (let i = 0; i < rowCount; i++) {
						if (BindedPRowId == deletedRows[i]._getCategory()) {
							result = true;
							break;
						}
					}
				}
				return result;
			}

		}

		public override _isDeletedRow(rowIndex: number): boolean {
			if (utils.ParamUtil.isInRange(rowIndex, 0, this.getRowCount() - 1) == false) {
				return;
			}
			let rowState: tabledata.RowState = this._getRowState(rowIndex);
			if (rowState == tabledata.RowState.DELETED || rowState == tabledata.RowState.INSERTDELETED) {
				return true;
			}
			return false;
		}

