		public override findAllRowExpr(condition: expression.Expression, startIndex: number = 0, endIndex: number = (this.getRowCount() - 1)): IDataRow[] {
			let viewRows: IDataRow[] = [];
			if (condition instanceof expression.Expression == false) {
				throw new exceptions.IllegalArgumentException("condition must be an Expression object");
			}
			if (utils.ParamUtil.isInRange(startIndex, 0, this.getRowCount() - 1) == false) {
				return viewRows;
			}
			if (utils.ParamUtil.isInRange(endIndex, 0, this.getRowCount() - 1) == false) {
				return viewRows;
			}

			for (let i = startIndex; i <= endIndex; i++) {
				viewRows[viewRows.length] = new Row(this, i);
			}

			viewRows = viewRows.filter(condition.asFilter());

			return viewRows;
		}

