		public override getSum(columnName: column_name_string): foundation.DecimalType {
			/**
			 * 컬럼이 존재 하지 않는 경우 : DecimalType(0) (20181029 변경)
			 * 계산할 행이 없는 경우 : DecimalType(0)
			 */
			let func: (row: IDataRow) => (number | decimal.Decimal) = null;

			if (this.isExistColumn(columnName)) {
				let header: header.Header = this._dataTable.getHeader(columnName);
				if (header._isExpressionHeader()) { // expression header일 경우
					let exprHeader: header.ExpressionHeader = header as header.ExpressionHeader;
					let exprFunc: Function = exprHeader.getFunction();
					if (exprFunc != null) {
						func = (row: IDataRow) => {
							let value = exprFunc(row);
							return utils.Util.toNumber(value);
						}
					}
				} else {
					if (header.getDataType() == tabledata.DataType.DECIMAL) { // decimal header일 경우
						func = (row: IDataRow) => {
							let value: foundation.DecimalType = row._getDecimal(columnName);
							return (value == null) ? 0 : value._getDecimal();
						}
					} else { // number, string header일 경우
						func = (row: IDataRow) => {
							let value: number = row.getNumber(columnName);
							return (isNaN(value)) ? 0 : value;
						}
					}
				}

			} else {
				let exprFunc: Function = cpr.expression.ExpressionEngine.INSTANCE.compile(columnName) as Function;
				func = (row: IDataRow) => {
					let funcValue = exprFunc(row);
					return Number(funcValue);
				}
			}

			let sum: decimal.Decimal = new Decimal(0);
			let value: (number | decimal.Decimal);
			let rowLength: number = this.getRowCount();
			for (let i = 0; i < rowLength; i++) {
				value = func(this.getRow(i));
				sum = sum.plus(value);
			}

			return new foundation.DecimalType(sum);
		}

		/**
		 * DataView 통계함수에서 사용할 내부 함수
		 * @param rowIndex 
		 * @param columnName 
		 * @returns 
		 */
		public _getNumber(rowIndex: number, columnName: column_name_string): number {

			let value: (string | number | foundation.DecimalType) = null;
			let header: header.Header = this._dataTable.getHeader(columnName);
			if (header._isExpressionHeader()) { // expression header일 경우
				let exprHeader: header.ExpressionHeader = header as header.ExpressionHeader;
				let func: Function = exprHeader.getFunction();
				if (func != null) {
					value = func(this.getRow(rowIndex));
				}
			} else {
				let columnIndex: number = this._dataTable._getColumnIndex(columnName);
				if (header.getDataType() == tabledata.DataType.DECIMAL) { // decimal header일 경우
					value = this._viewTable._getDecimal(rowIndex, columnIndex);
				} else {// 일반 header 일 경우
					value = this._viewTable._getValue(rowIndex, columnIndex);
				}

			}
			return utils.Util.toNumber(value);
		}

