		public override getOriginalSum(columnName: column_name_string): foundation.DecimalType {
			let rows: tabledata.RowData[] = this._getBindedAllRow();
			let columnIndex: number = this._getColumnIndex(columnName);
			let isExprColumn: boolean = (this.getHeader(columnName).getDataType() == tabledata.DataType.EXPRESSION);
			let func: Function = expression.ExpressionEngine.INSTANCE.compile(columnName) as Function;
			let sum: foundation.DecimalType = new foundation.DecimalType(0);
			let rowLength: number = rows.length;

			if (isExprColumn) { // expression column의 경우 현재 데이터기준.
				for (let i = 0; i < rowLength; i++) {
					let row: tabledata.RowData = rows[i];
					if ((row.state & tabledata.RowState.INSERTED) ||
						(row.state & tabledata.RowState.INSERTDELETED)) {
						continue;
					}
					let value: (string | number | foundation.DecimalType) = func(new DataRow(this._parentDataSet, row));
					let numberValue: number = Number(value);
					if (isNaN(numberValue) == false) {
						value = (value == "" || value == null) ? numberValue : value;
						sum = sum.plus(value);
					}
				}
			} else {
				for (let i = 0; i < rowLength; i++) {
					let row: tabledata.RowData = rows[i];
					if ((row.state & tabledata.RowState.INSERTED) ||
						(row.state & tabledata.RowState.INSERTDELETED)) {
						continue;
					}
					let value: (string | number | foundation.DecimalType) = rows[i]._getOriginalValue(columnIndex);
					let numberValue: number = Number(value);
					if (isNaN(numberValue) == false) {
						value = (value == "" || value == null) ? numberValue : value;
						sum = sum.plus(value);
					}
				}
			}

			return sum;
		}

		public override getOriginalAvg(columnName: column_name_string): foundation.DecimalType {
			let rows: tabledata.RowData[] = this._getBindedAllRow();
			let sum: foundation.DecimalType = this.getOriginalSum(columnName);
			let orgRows: tabledata.RowData[] = rows.filter((row: tabledata.RowData) => {
				let state: tabledata.RowState = row.state;
				return !((state & tabledata.RowState.INSERTED) || (state & tabledata.RowState.INSERTDELETED));
			});
			return sum.dividedBy(orgRows.length);
		}

