		public override _getDecimal(rowIndex: number = -1, columnName: column_name_string): foundation.DecimalType {
			if (rowIndex < 0 || rowIndex >= this.getRowCount()) {
				return null;
			}
			if (this.isExistColumn(columnName) == false) {
				return null;
			}
			let columnIndex: number = this._dataTable._getColumnIndex(columnName);
			return this._viewTable._getDecimal(rowIndex, columnIndex);
		}

