namespace cpr.controls.gridpart {
	let log = utils.Logger.forTopic("gridband")._createBindedLoggerFunction({
		updator: it => log = it
	});


	export abstract class GridBand {
		private _context: GridContext;
		private _bandType: string; /* header, detail, footer, gheader, gfooter */

		constructor(context: GridContext, bandType: string) {
			this._context = context;
			this._bandType = bandType;
		}

		/**
		 * 해당 Band의 셀 수를 반환합니다.
		 */
		public get cellCount(): number {
			return (this._getBand().cellProp) ? this._getBand().cellProp.length : 0;
		}

		public _getContext(): GridContext {
			return this._context;
		}

		public _getBandType(): string {
			return this._bandType;
		}

		public _getCellProps(): GridCellProp[] {
			return this._getBand().cellProp;
		}

		/**
		 * 해당 영역의 행 인덱스별 높이를 반환합니다.<br>
		 * 단위는 px입니다.
		 * @param rowIndex 행 인덱스.
		 * @return 입력받은 행 인덱스의 높이.
		 */
		public getRowHeight(rowIndex: number): number {
			let band: GridBandConfig = this._getBand();
			if (band == null) {
				return 0;
			}
			if (utils.ParamUtil.isInRange(rowIndex, 0, band.rows.length - 1) == false) {
				return 0;
			}

			let rows: { rowIndex: number, height: number }[] = band.rows;
			let rowHeight: number = 0;
			rows.forEach((row: { rowIndex: number, height: number }) => {
				if (row.rowIndex == rowIndex) {
					rowHeight = row.height;
				}
			});
			return rowHeight;
		}

		/**
		 * 해당 영역의 행 높이를 반환합니다.<br>
		 * 디자인 시점의 행 높이입니다.<br>
		 * 단위는 px입니다.<br>
		 * 
		 * @return 행 높이 배열.
		 */
		public getRowHeights(): { height: number }[] {
			let band: GridBandConfig = this._getBand();
			if (band == null) {
				return null;
			}

			let rows: { rowIndex: number, height: number }[] = band.rows;
			return rows.map((row: { rowIndex: number, height: number }) => {
				return { height: row.height };
			})
		}

		public _getTotalRowHeight(): number {
			let band: GridBandConfig = this._getBand();
			if (band == null) {
				return 0;
			}

			let height: number = 0;
			let rows: { rowIndex: number, height: number }[] = band.rows;
			let rowCount: number = rows.length;
			for (let i = 0; i < rowCount; i++) {
				height += rows[i].height;
			}
			return height;
		}

		/**
		 * 특정 셀에 존재하는 컨트롤을 반환합니다.
		 * @param cellIndex 셀 인덱스.
		 * @return 입력받은 셀 인덱스에 존재하는 컨트롤.
		 */
		public getControl(cellIndex: number): UIControl {
			return this.getColumn(cellIndex)?.control;
		}

		/**
		 * 해당 영역의 행 높이를 변경합니다.
		 * @param heights 설정한 높이 배열. (ex. [30])
		 */
		public setRowHeights(heights: number[]): void {
			let context: GridContext = this._getContext();
			let grid: Grid = context.getGrid();
			let rowHeight: number = 0;
			heights.forEach((height: number) => rowHeight += height);

			context._setRowHeight(this._getBandType(), heights);
			grid._setRowHeight(this._getBandType(), rowHeight);
			if (context._isGrouping()) {
				grid._needRowGroupReset();
			} else {
				context._clearContentHeight();
			}
			grid.redraw();

		}

		/**
		 * cellIndex 배열을 반환합니다.
		 * @return cellIndex 배열.
		 */
		public getCellIndices(): number[] {
			let cellProps: GridCellProp[] = this._getBand().cellProp;
			cellProps.sort(GridUtil._rowFirstSort);

			let result: number[] = [];
			cellProps.forEach((cell: GridCellProp) => {
				result[result.length] = cell.constraint.cellIndex;
			});
			return result;

		}

		protected abstract _getBand(): GridBandConfig;
		public abstract getColumn(cellIndex: number): GridColumn;
		public abstract getColumnByColIndex(colIndex: number, colSpan: number): GridColumn[];
	}


	/**
	 * @noinstance
	 */
	export class GridHeaderBand extends GridBand {

		/**
		 * @private
		 */
		constructor(context: GridContext) {
			super(context, GRIDREGION.HEADER);
		}

		protected _getBand(): GridHeaderBandConfig {
			return this._getContext().getHeader();
		}

		/**
		 * 특정 셀을 반환합니다.
		 * @param cellIndex 셀 인덱스.
		 * @return 입력받은 셀 인덱스의 셀.
		 */
		public getColumn(cellIndex: number): GridHeaderColumn {
			let cellProps: GridHeaderCellProp[] = this._getBand().cellProp;
			let gridColumn: GridHeaderColumn = null;
			cellProps.some((cell: GridHeaderCellProp) => {
				if (cell.constraint.cellIndex == cellIndex) {
					gridColumn = new GridHeaderColumn(this._getContext(), cell);
					return true;
				}
			});
			return gridColumn;
		}

		/**
		 * 해당 정보에 맞는 GridColumn 배열을 반환합니다.
		 * @param colIndex 찾고자 하는 컬럼의 colIndex.
		 * @param colSpan 찾고자 하는 컬럼의 colSpan.
		 * @return 해당 정보에 맞는 GridColumn 배열.
		 */
		public getColumnByColIndex(colIndex: number, colSpan: number): GridHeaderColumn[] {
			let cellProps: GridHeaderCellProp[] = [].concat(this._getBand().cellProp);
			let resultColumns: GridHeaderColumn[] = [];
			cellProps.forEach((cellProp: GridHeaderCellProp) => {
				if (cellProp.constraint.colIndex == colIndex && cellProp.constraint.colSpan == colSpan) {
					resultColumns[resultColumns.length] = new GridHeaderColumn(this._getContext(), cellProp);
				}
			});
			return resultColumns;
		}

		/**
		 * 특정 columnName과 바인딩 되어있는 GridDetailColumn 배열을 반환합니다.
		 * @param columnName detail에 바인딩 되어 있는 columnName.
		 * @return 입력받은 columnName의 GridDetailColumn 배열.
		 * @deprecated 2019.01.21 detail에서만 제공되는 기능입니다.
		 */
		public getColumnByName(columnName: string): GridDetailColumn[] { return null; }

		/**
		 * 특정 셀에 컨트롤이 존재하는 경우 해당 컨트롤의 특정 속성 값을 반환합니다.
		 * @param attrName 속성명.
		 * @return 속성값.
		 */
		public getControlAttr(cellIndex: number, attrName: string): any {
			let column: GridHeaderColumn = this.getColumn(cellIndex);
			if (column != null) {
				return column.getControlAttr(attrName);
			}
			return null;
		}

		/**
		 * 헤더영역에 적용된 sort 정보를 반환합니다.
		 * @return sort 정보.
		 */
		public getSort(): { cellIndex: number, asc: boolean }[] {
			let gridSortConditions: { colNm: string, asc: boolean }[] = this._getContext().getGrid()._getGridSort();
			var cellIndices: number[] = this.getCellIndices();
			let cellCount: number = cellIndices.length;
			let sortCondition: { cellIndex: number, asc: boolean }[] = [];
			gridSortConditions.forEach((sortInfo: { colNm: string, asc: boolean }) => {
				for (let i = 0; i < cellCount; i++) {
					if (sortInfo.colNm == this.getColumn(cellIndices[i]).targetColumnName) {
						sortCondition[sortCondition.length] = { cellIndex: cellIndices[i], asc: sortInfo.asc };
						break;
					}
				}
			});
			return sortCondition;
		}

		/**
		 * 헤더영역에 적용된 sort condition을 반환합니다.
		 * @return sort condition.
		 */
		public getSortCondition(): string {
			return this._getContext().getGrid()._createMultiSortCondition();
		}

		/**
		 * 그리드 헤더의 sort를 사용하는 것과 동일하게 그리드가 정렬되도록 합니다.<br>
		 * 그리드 헤더의 정렬 스타일이 적용됩니다.<br>
		 * 데이터셋의 sort와는 별개로 관리됩니다.
		 * 
		 * @param sortInfos sort 조건. <br>
		 * 					cellIndex : 헤더 셀 인덱스.<br>
		 * 					asc : 정렬 오름차순/내림차순. (true/false)
		 * 					emptyValueSort : 정렬시 빈 값이 대한 처리 (emptyString, nullLast)
		 * @example
		 * <code>grid.header.sort([{cellIndex: 1, asc: true}, {cellIndex: 2, asc: false}])</code><br>
		 */
		public sort(sortInfos: { cellIndex: number, asc: boolean, emptyValueSort?: string }[]): void {
			if (sortInfos == null || sortInfos.length == 0) {
				this.clearSort();
				return;
			}
			let grid: Grid = this._getContext().getGrid();
			grid._clearMultiSort(null, false);

			sortInfos.forEach((sortInfo: { cellIndex: number, asc: boolean, emptyValueSort: string }) => {
				let column: GridHeaderColumn = this.getColumn(sortInfo.cellIndex);
				if (column.targetColumnName != null) {
					grid._addMultiSortCondition(column.targetColumnName, sortInfo.asc, sortInfo.emptyValueSort);
				}
			})
			grid._sortMulti();
		}

		/**
		 * 그리드 헤더영역의 정렬을 모두 제거합니다.
		 */
		public clearSort(): void {
			this._getContext().getGrid()._clearMultiSort();
		}

		/**
		 * 그리드 헤더영역에 적용된 filter 정보를 반환합니다.
		 * @return filter 정보.
		 */
		public getFilter(): { cellIndex: number, values: string[] }[] {
			let gridFilterConditions: data.GridFilterCondition[] = this._getContext().getGrid()._getGridFilterCondition();
			var cellIndices: number[] = this.getCellIndices();
			let cellCount: number = cellIndices.length;
			let filterCondition: { cellIndex: number, values: string[] }[] = [];
			gridFilterConditions.forEach((filterInfo: data.GridFilterCondition) => {
				for (let i = 0; i < cellCount; i++) {
					if (filterInfo.colNm == this.getColumn(cellIndices[i]).targetColumnName
						&& filterInfo.valueSet.has(provider.GridDataProvider.FILTER_ALL) == false) {
						filterCondition[filterCondition.length] = { cellIndex: cellIndices[i], values: _stream(filterInfo.valueSet).collect() };
						break;
					}
				}
			});
			return filterCondition;
		}

		/**
		 * 그리드 헤더의 filter를 사용하는 것과 동일하게 그리드가 필터링되도록 합니다.<br>
		 * 그리드 헤더의 필터 스타일이 적용됩니다.<br>
		 * 데이터셋의 filter와는 별개로 관리됩니다.<br>
		 * 그리드 필터에 의해 보이지 않는 value에 대해서는 <br>
		 * header filter를 통해 filter 체크 변경을 할 수 없습니다.
		 * @param filterInfos filter 조건. <br>
		 * 					cellIndex : 헤더 셀 인덱스.<br>
		 * 					values : 필터링할 값.
		 * 
		 * @example
		 * <code>grid.header.filter([{cellIndex: 1, values: ["A, B"]}])</code><br>
		 * => cellIndex가 1인 헤더 셀의 값이 "A"와 "B"인 행만 필터링 합니다.<br>
		 * (값을 비교하는 데이터셋 컬럼은 헤더 셀의 targetColumnName 입니다.)
		 */
		public filter(filterInfos: { cellIndex: number, values: (string | number)[] }[]): void {
			if (filterInfos == null || filterInfos.length == 0) {
				this.clearFilter();
				return;
			}
			let grid: Grid = this._getContext().getGrid();
			grid._clearFilterDialog(false);

			filterInfos.forEach((filterInfo: { cellIndex: number, values: (string | number)[] }) => {
				filterInfo.values = filterInfo.values.map((value: (string | number)) => {
					return (typeof value == "number") ? "" + value : value;
				});
				let column: GridHeaderColumn = this.getColumn(filterInfo.cellIndex);
				if (column.targetColumnName != null) {
					grid._addGridFilterCondition(column.targetColumnName, filterInfo.values as string[]);
				}
			})

			let filterConditions: data.GridFilterCondition[] = grid.dataProvider._getFilterCondition();
			grid._setFilterDialog(filterConditions);
		}

		/**
		 * 그리드 헤더영역의 필터를 모두 제거합니다.
		 */
		public clearFilter(): void {
			let grid: Grid = this._getContext().getGrid();
			grid._clearFilterDialog();
		}
	}

	/**
	 * @noinstance
	 */
	export class GridDetailBand extends GridBand {

		/**
		 * @private
		 */
		constructor(context: GridContext) {
			super(context, GRIDREGION.DETAIL);
		}

		protected _getBand(): GridDetailBandConfig {
			return this._getContext().getDetail();
		}

		/**
		 * 특정 columnName과 바인딩 되어있는 GridDetailColumn 배열을 반환합니다.<br>
		 * detail에서만 제공되는 기능입니다.
		 * @param columnName detail에 바인딩 되어 있는 columnName.
		 * @return 입력받은 columnName의 GridDetailColumn 배열.
		 */
		public getColumnByName(columnName: string): GridDetailColumn[] {
			// cellIndex를 studio(사용자)기준으로 맞추기 위해 정렬 (우선순위 : rowIndex, colIndex)
			let sortCells: GridDetailCellProp[] = [].concat(this._getBand().cellProp);
			sortCells.sort(GridUtil._rowFirstSort);

			let result: GridDetailColumn[] = [];
			sortCells.forEach((cell: GridDetailCellProp, index: number) => {
				if (cell.configuration.columnName == columnName) {
					result[result.length] = new GridDetailColumn(this._getContext(), sortCells[index]);
				}
			});

			return result;
		}

		/**
		 * 특정 셀을 반환합니다.
		 * @param cellIndex 셀 인덱스.
		 * @return 입력 받은 셀 인덱스의 셀.
		 */
		public override getColumn(cellIndex: number): GridDetailColumn {
			let cellProps: GridDetailCellProp[] = this._getBand().cellProp;
			let gridColumn: GridDetailColumn = null;
			cellProps.some((cell: GridDetailCellProp) => {
				if (cell.constraint.cellIndex == cellIndex) {
					gridColumn = new GridDetailColumn(this._getContext(), cell);

					return true;
				}
			});
			return gridColumn;
		}

		/**
		 * 특정 셀에 존재하는 컨트롤을 반환합니다.<br>
		 * 특정 셀이 조건부 컨트롤인 경우, conditionalId를 입력해야 합니다.
		 * @param cellIndex 셀 인덱스.
		 * @param conditionalId 조건부 id. (experimental)
		 * @return 입력 받은 셀 인덱스에 존재하는 컨트롤.
		 */
		public override getControl(cellIndex: number, conditionalId?: string): GridUIControl {
			return this.getColumn(cellIndex)?.getControl(conditionalId);
		}


		/**
		 * 해당 정보에 맞는 GridColumn 배열을 반환합니다.
		 * @param colIndex 찾고자 하는 컬럼의 colIndex.
		 * @param colSpan 찾고자 하는 컬럼의 colSpan.
		 * @return 해당 정보에 맞는 GridColumn 배열.
		 */
		public getColumnByColIndex(colIndex: number, colSpan: number): GridDetailColumn[] {
			let cellProps: GridDetailCellProp[] = [].concat(this._getBand().cellProp);
			let resultColumns: GridDetailColumn[] = [];
			cellProps.forEach((cellProp: GridDetailCellProp) => {
				if (cellProp.constraint.colIndex == colIndex && cellProp.constraint.colSpan == colSpan) {
					resultColumns[resultColumns.length] = new GridDetailColumn(this._getContext(), cellProp);
				}
			});
			return resultColumns;
		}

		/**
		 * 특정 셀에 컨트롤이 존재하는 경우 특정 행에 있는 컨트롤의 특정 속성 값을 반환합니다.
		 * @param rowIndex 속성 값을 알고자 하는 행 인덱스.
		 * @param attrName 속성명.
		 * @return 속성값.
		 */
		public getControlAttr(rowIndex: number, cellIndex: number, attrName: string): any {
			let column: GridDetailColumn = this.getColumn(cellIndex);
			if (column != null) {
				return column.getControlAttr(rowIndex, attrName);
			}
			return null;
		}
	}

	/**
	 * @noinstance
	 */
	export class GridFooterBand extends GridBand {

		/**
		 * @private
		 */
		constructor(context: GridContext) {
			super(context, GRIDREGION.FOOTER);
		}

		protected _getBand(): GridFooterBandConfig {
			return this._getContext().getFooter();
		}

		/**
		 * 해당 밴드의 visible을 설정합니다.<br>
		 * footer만 동작합니다.
		 */
		public set visible(visible: boolean) {
			let band: GridFooterBandConfig = this._getBand();
			if (!band) {
				return;
			}
			if (band.visible == visible) {
				return;
			}
			band.visible = visible;
			let context: GridContext = this._getContext();
			if (context.disposed) {
				return;
			}
			context._setEnablePart(this._getBandType(), visible);
			let grid: Grid = context.getGrid();
			grid._recreateGridTableInfo();
			let gridLayout: layout.GridControlLayout = grid.getLayout() as layout.GridControlLayout;
			gridLayout._resetGridLayout();
			gridLayout._readyForRedraw();
			grid.redraw();
		}

		/**
		 * 해당 밴드의 visible 값을 반환합니다.<br>
		 * footer만 동작합니다.
		 */
		public get visible(): boolean {
			let band: GridFooterBandConfig = this._getBand();
			if (band) {
				return band.visible;
			}
			return undefined;
		}

		/**
		 * 특정 셀을 반환합니다.
		 * @param cellIndex 셀 인덱스.
		 * @return 입력받은 셀 인덱스의 셀.
		 */
		public getColumn(cellIndex: number): GridFooterColumn {
			let cellProps: GridFooterCellProp[] = this._getBand().cellProp;
			let gridColumn: GridFooterColumn = null;
			cellProps.some((cell: GridFooterCellProp) => {
				if (cell.constraint.cellIndex == cellIndex) {
					gridColumn = new GridFooterColumn(this._getContext(), cell);
					return true;
				}
			});
			return gridColumn;
		}

		/**
		 * 해당 정보에 맞는 GridColumn 배열을 반환합니다.
		 * @param colIndex 찾고자 하는 컬럼의 colIndex.
		 * @param colSpan 찾고자 하는 컬럼의 colSpan.
		 * @return 해당 정보에 맞는 GridColumn 배열.
		 */
		public getColumnByColIndex(colIndex: number, colSpan: number): GridFooterColumn[] {
			let cellProps: GridFooterCellProp[] = [].concat(this._getBand().cellProp);
			let resultColumns: GridFooterColumn[] = [];
			cellProps.forEach((cellProp: GridFooterCellProp) => {
				if (cellProp.constraint.colIndex == colIndex && cellProp.constraint.colSpan == colSpan) {
					resultColumns[resultColumns.length] = new GridFooterColumn(this._getContext(), cellProp);
				}
			});
			return resultColumns;
		}

		/**
		 * @private
		 * @param datas 
		 */
		public _setData(datas: string[]): void {
			let band: GridFooterBandConfig = this._getBand();
			let cellCount: number = band.cellProp.length;
			let gridColumn: GridFooterColumn;

			for (let i = 0; i < cellCount; i++) {
				if (i >= datas.length) {
					break;
				}
				gridColumn = null;
				gridColumn = new GridFooterColumn(this._getContext(), band.cellProp[i]);
				gridColumn.setExpr(datas[i]);
			}
		}

		/**
		 * @private
		 */
		public _getData(): string[] {
			let result: string[] = [];
			let band: GridFooterBandConfig = this._getBand();
			let sortCells: GridFooterCellProp[] = [].concat(band.cellProp);
			let cellCount: number = sortCells.length;

			// cellIndex를 studio(사용자)기준으로 맞추기 위해 정렬 (우선순위 : rowIndex, colIndex)
			sortCells.sort(GridUtil._rowFirstSort);

			let grid: Grid = this._getContext().getGrid();
			let dataCollection: data.DataCollection = grid.dataSet;
			for (let i = 0; i < cellCount; i++) {
				let gridColumn: GridFooterColumn = new GridFooterColumn(this._getContext(), sortCells[i]);

				let value: (string | number | ufc.StyledString) = GridUtil._getDataExprResult(gridColumn.getExpr(), dataCollection);
				result[result.length] = (value instanceof ufc.StyledString) ? ufc.StyledString._asString(value) : utils.Util.toString(value);
			}

			return result;
		}

		/**
		 * 특정 columnName과 바인딩 되어있는 GridDetailColumn 배열을 반환합니다.
		 * @param columnName detail에 바인딩 되어 있는 columnName.
		 * @return 입력받은 columnName의 GridDetailColumn 배열.
		 * @deprecated 2019.01.21 detail에서만 제공되는 기능입니다.
		 */
		public getColumnByName(columnName: string): GridDetailColumn[] { return null; }

		/**
		 * 특정 셀에 컨트롤이 존재하는 경우 해당 컨트롤의 특정 속성 값을 반환합니다.
		 * @param attrName 속성명.
		 * @return 속성값.
		 */
		public getControlAttr(cellIndex: number, attrName: string): any {
			let column: GridFooterColumn = this.getColumn(cellIndex);
			if (column != null) {
				return column.getControlAttr(attrName);
			}
			return null;
		}
	}

}
