/// <reference path="./UIControl.ts" />

namespace cpr.controls {
	/**
	 * HTMLObject의 파라미터 클래스
	 */
	interface Param {
		/**
		 * 파라미터 명.
		 */
		name: string,
		/**
		 * 파라미터의 값.
		 */
		value: string
	}
	/**
	 * HTMLObject
	 * 웹페이지 내부에 외부 리소스나 외부 문서를 포함하는 요소를 표현하는 객체 컨트롤.
	 * 외부 리소스는 오디오, 비디오, Java applets, ActiveX, flash 등을 포함합니다. 
	 * PDF를 출력하는 경우 웹접근성을 위해 다운로드 링크를 함께 제공해야 합니다.
	 */
	export class HTMLObject extends VisibleUIControl {
		private static readonly _AVAILABLE_PROP: string[] = [
			"classId", "codeBase", "data", "mediaType", "notSupportMessage"
		];

		private _attributes: { [key: string]: string };
		private _parameter: Param[];
		private _classID: string;
		private _codebase: string;
		private _mediatype: string;
		private _data: string;

		/**
		 * HTMLObject를 생성합니다.
		 * @param id htmlObject의 id
		 */
		constructor(id?: string) {
			super(id);
			this._attributes = { id: this.uuid };
			this._parameter = [];
			this._addBindableProperty("notSupportMessage", "").withSetterValidatorWithType(false, "string");

			// control initializing
			this._initControl();
		}

		protected _isConfigurableProperty(propName: string): boolean {
			if (HTMLObject._AVAILABLE_PROP.indexOf(propName) != -1) {
				return true;
			}
			return super._isConfigurableProperty(propName);
		}

		/* Shape */
		protected _getStylerSpec(): UIControlStylerSpec {
			return {
				root: { baseClass: "cl-htmlobject" },
			};
		}

		/* control's type overriding */
		override _getType(): ControlType {
			return ControlType.HTMLOBJECT;
		}

		/**
		 * 자동 크기 지원 타입을 얻습니다.
		 * 만일 both를 리턴했다면, css height, width 속성에 auto를 사용할 수 있음을 나타냅니다.
		 */
		public _getAutoSizeAvailability(): layouts.AutoSizeType {
			return layouts.AutoSizeType.both;
		}

		/**
		 * HTML오브젝트는 포커스를 받지 못함.
		 */
		protected _isFocusable(): boolean {
			return false;
		}

		/**
		 * @param name 
		 * @param oldValue 
		 * @param newValue 
		 */
		_valueDidChange(name: string, oldValue: any, newValue: any) {
			super._valueDidChange(name, oldValue, newValue);
			switch (name) {
				case "notSupportMessage": {
					this.redraw();
					break;
				}
			}
		}
		/* property */
		/**
		 * 실행할 Object의 URL을 반환합니다.
		 * @return 실행할 Object의 URL.
		 */
		get classId(): string {
			return this._classID;
		}

		/**
		 * 실행한 Object의 URL을 설정합니다.<br>
		 * 관련 속성 : [data] data속성과 같이 또는 대신해서 사용 될 수 있습니다.
		 * @param id 실행할 Object의 URL.
		 */
		set classId(id: string) {
			this._classID = id;
			this.setAttr("classid", id);
		}

		/**
		 * 삽입할 Object의 기본 경로 URL을 반환합니다.
		 * @return 삽입할 Object의 기본 경로 URL.
		 */
		get codeBase(): string {
			return this._codebase;
		}

		/**
		 * 삽입할 Object의 기본 경로 URL을 설정합니다.
		 * @param code 삽입할 Object의 기본 경로 URL.
		 */
		set codeBase(code: string) {
			this._codebase = code;
			this.setAttr("codebase", code);
		}

		/**
		 * 삽입할 외부 리소스의 URL을 반환합니다.
		 * @return 삽입할 외부 리소스의 URL.
		 */
		get data(): string {
			return this._data;
		}

		/**
		 * 삽입할 외부 리소스의 URL을 설정합니다.<br>
		 * 관련 속성 : [type] type 속성과 더불어 최소 하나 이상은 정의되어야만 합니다.
		 * @param 삽입할 외부 리소스의 URL.
		 */
		set data(data: string) {
			if (this._data != data) {
				this._getRenderer().delete("object");
			}
			this._data = data;
			this.setAttr("data", data);

		}

		/**
		 * data 속성에서 media 데이터의 타입을 반환합니다.
		 * @return data 속성에서 media 데이터의 타입.
		 */
		get mediaType(): string {
			return this._mediatype;
		}

		/**
		 * data 속성에서 media 데이터의 타입을 설정합니다.<br>
		 * MIME 타입으로 설정합니다.
		 * @param data 속성에서 media 데이터의 타입.
		 */
		set mediaType(type: string) {
			this._mediatype = type;
			this.setAttr("type", type);
		}

		/**
		 * 브라우저 플러그인 객체를 리턴합니다.
		 * @return HTMLObject|null 
		 */
		get object(): any {
			//TODO: 다시 그리는 과정에서 DOMElement의 속성이 변경될수 있음. 사용자에게 제공해야 될지 여부 다시 확인 필요. 2017-12-06 문영동
			let renderer: ufc.ControlRenderer = this._getRenderer();
			let objectTag = renderer.getNamedNode("object");
			if (objectTag) {
				//ActiveX의 메소드를 호출하기 위해 오브젝트 태그 객체
				if (objectTag["object"]) {
					return objectTag["object"];
				}
				return objectTag;
			}
			return null;
		}

		/**
		 * data속성의 값을 통해 데이터를 가져오 못 했을때 표시되는 메시지를 가져옵니다. 
		 */
		get notSupportMessage(): string {
			return this._bindables.get("notSupportMessage");
		}

		/**
		 * data속성의 값을 통해 데이터를 가져오 못 했을때 표시되는 메시지를 설정합니다. 
		 */
		set notSupportMessage(message: string) {
			this._bindables.set("notSupportMessage", message);
		}

		/* shape */
		public _createShape(): cpr.ufc.ControlShape {
			let classNames: string[] = [];
			let children = [].concat(this._createParam());
			if (this.data && this.notSupportMessage) {
				let message: cpr.ufc.ControlShape = {
					tag: "div",
					classNames: [ufc.Classes.TEXT],
					children: [this.notSupportMessage]
				};
				children.push(message);
			}
			let obj: cpr.ufc.ControlShape = {
				tag: "object",
				style: {
					width: "100%",
					height: "100%",
					display: "block"
				},
				attr: this._attributes,
				nodename: "object",
				eventTargets: [ufc.EventTargetType.HTMLOBJECT],
				children: children
			}

			let shape: cpr.ufc.ControlShape = {
				classNames: classNames,
				tag: "div",
				attr: {},
				styler: "root",
				eventTargets: [],
				style: {
					position: "relative"
				},
				children: [obj]
			}
			cpr.ufc.ShapeUtil._setTooltipAttr(shape, { owner: this, title: this.tooltip });
			return shape;
		}

		private _createParam(): cpr.ufc.ControlShape[] {
			let paramShape: cpr.ufc.ControlShape[] = [];
			for (let i = 0; i < this._parameter.length; i++) {
				let param: cpr.ufc.ControlShape = {
					tag: "param",
					attr: {
						name: this._parameter[i]['name'],
						value: this._parameter[i]['value']
					}
				}
				paramShape.push(param);
			}
			return paramShape;
		}

		/* public method */
		/**
		 * 해당하는 속성값을 반환합니다.
		 * @param name 속성의 이름.
		 * @return 속성의 값
		 */
		public getAttr(name: string): string {
			let value = this._attributes[name];
			if (!value) {
				return null;
			}
			return value;
		}

		/**
		 * 해당하는 속성값을 설정합니다.
		 * @param name 속성의 이름.
		 * @param value 속성의 값.
		 */
		public setAttr(name: string, value: string): void {
			this._attributes[name] = value;
			this.redraw();
		}

		/**
		 * 속성 값을 삭제 합니다.
		 * @param name 속성의 이름.
		 */
		public removeAttr(name: string): void {
			if (this._attributes[name] != null) {
				this.redraw();
			}
			if (name == "data") {
				this._attributes[name] = "";
			} else {
				this._attributes[name] = null;
				delete this._attributes[name];
			}
		}

		/**
		 * 해당하는 파라미터 값을 반환합니다.
		 * @param name 파라미터의 이름.
		 * @return 파라미터 값.
		 */
		public getParam(name: string): string {
			let value = null;
			for (let i = 0; i < this._parameter.length; i++) {
				if (this._parameter[i]['name'] === name)
					value = this._parameter[i]['value'];
			}
			return value;
		}

		/**
		 * 해당하는 파라미터 값을 설정합니다.
		 * @param name 파라미터의 이름.
		 * @param value 파라미터 값.
		 */
		public setParam(name: string, value: string): void {
			if (this.getParam(name) == null || this.getParam(name) == "") {
				this._parameter.push({ name: name, value: value });
			} else {
				for (let i = 0; i < this._parameter.length; i++) {
					if (this._parameter[i]['name'] === name) {
						this._parameter[i]['value'] = value;
					}
				}
			}
			this.redraw();
		}

		/**
		 * 해당하는 파라미터를 삭제합니다.
		 * @param name 삭제할 파라미터 이름.
		 */
		public removeParam(name: string): void {
			let param: Param = { name: name, value: this.getParam(name) };
			if (param['name'] == null) {
				return;
			}
			for (let i = 0; i < this._parameter.length; i++) {
				if (this._parameter[i]['name'] === param['name']) {
					this._parameter.splice(i, 1);
				}
			}
			this.redraw();
		}
	}
}