/// <reference path="./AbstractHorizontalBar.ts" />
namespace cpr.controls.navigation {
	/**
	 * @private
	 */
	export class AccessibleHorizontalBar extends AbstractHorizontalBar {

		private _isAppliedTransformStyle: boolean = false;
		protected _menus: { [key: string]: menu.IAccessibleMenu } = {};

		public get isAppliedTransformStyle() {
			return this._isAppliedTransformStyle;
		}

		protected _createMenu(): menu.IAccessibleMenu {
			let menu: menu.IAccessibleMenu = null;
			switch (this._owner.menuType) {
				case NavigationBarMenuType.accessiblemegamenu: {
					menu = new cpr.controls.navigation.AccessibleMegaMenu(this._owner, "navigationbar", this._binder, { list: "list", item: "listitem" });
					break;
				}
			}

			if (menu) {
				menu.addEventListener("--internal-item-select", (e: events.CItemEvent) => { this._onMenuItemSelect(e) });
				menu.addEventListener(events.ItemEventType.ITEMCLICK, (e: events.CItemEvent) => { this._onMenuItemClick(e) });
				menu.addEventListener("--internal-item-selected", (e: events.CItemEvent) => { this._onMenuItemSelected(e) });
				menu.addEventListener("item-mouseover", (e: events.CItemEvent) => { this._onMenuItemMouseOver(e) })
				menu.addEventListener("menu-item-focus", (e: events.CItemEvent) => { this._onMenuItemFocus(e) })
				menu.addEventListener("menu-mouseleave", (e: events.CMouseEvent) => { this._onMenuMouseLeave(e) });
				menu.addEventListener("menu-mouseenter", (e: events.CMouseEvent) => { this._onMenuMouseEnter(e) });
				menu.addEventListener("menu-hidden-mouseleave", (e: events.CMouseEvent) => { this._onMenuHiddenMouseLeave(e) });
			}
			return menu;
		};

		/**
		 * 컨트롤에 포커스를 지정합니다.
		 */
		public focus(forward: boolean = true): boolean {
			let ring = new NavigationBarFocusRing(this._owner);
			let result = false;
			if (this._owner.tabTraversal) {
				result = forward ? ring._focusFirst() : ring._focusLast();
			} else {
				result = ring._focusFirst();
			}
			return result;
		}

		protected _onAccessKey(item: MenuItem, e: events.CKeyboardEvent) {
			this._onItemSelect(item, e, (success: boolean) => {
				let rootItem = this._getTopParentItem(item);
				if (success) {
					if (this._close({ nativeEvent: e })) {
						this._focusBySelector(this._getFocusSelector(rootItem), { immediate: true, preventOpen: true, lazyItemFocus: true });
					} else if (this._isOpened(rootItem)) {
						this._focusBySelector(this._getFocusSelector(item), { immediate: true, preventOpen: true, lazyItemFocus: true });
					}
				}
			});
		}

		public _onfocus(e: FocusEvent) {
			if (!this._focusTrigger) {
				this._focusTrigger = { type: "keyboard", forward: true }
			}
			if (this._focusTrigger.type == "mousedown" || this._focusTrigger.type == "touchend" || this._focusTrigger.type == "self") {
				return;
			}

			let target = e.target as HTMLElement;
			let currentTarget = e.currentTarget as HTMLElement;
			if (target.tagName.toUpperCase() == "A") {
				let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(target)._closest("[data-role='menuitem']", currentTarget);
				if (domTraverser == null) {
					return;
				}
				let item = this._getItemByElement(domTraverser._getElement());
				let focusTriggerType = this._focusTrigger.type;
				core.DeferredUpdateManager.INSTANCE.asyncExec(() => {
					if (this.disposed) {
						return;
					}
					this._setHover(item, { useSameCheck: true, nativeEvent: e, preventOpen: focusTriggerType == "select" });
				})
			} else {
				this._owner._focusSelf();
			}
			this._focusTrigger = null;
		}

		protected _getMenuShape(menu: menu.IAccessibleMenu, children: MenuItem[]) {
			menu.setItems(children);
			return menu.createShape();
		}

		private _checkAppliedTransformStyle(ele: HTMLElement) {
			let parent = ele.parentElement;
			let computedStyle = null;
			while (parent != null) {
				computedStyle = window.getComputedStyle(parent);
				if (computedStyle.transform != "none") {
					return true;
				}
				parent = parent.parentElement;
			}
			return false;
		}

		/**
		 * 내비게이션바에서의 호버 아이템을 설정합니다.
		 * @param item 
		 * @returns 
		 */
		protected override _setHoveredItem(item: MenuItem, options: { doInitSubMenu?: boolean, updateScroll?: boolean, useSameCheck?: boolean, nativeEvent?: Event, preventOpen?: boolean } = {}) {
			_defaults(options, { doInitSubMenu: true, updateScroll: true, useSameCheck: true, nativeEvent: null, preventOpen: false });

			if (options.updateScroll) {
				this._updateScrollByHover(item, this._hoveredItem);
			}
			let isSameItem = item?._equalsValue(this._hoveredItem) ?? false;
			if (!isSameItem) {

				let rootNode = this._owner._getRenderer().getRootNode();
				this._isAppliedTransformStyle = this._checkAppliedTransformStyle(rootNode);

				if (!options.preventOpen) {
					if (item && item._hasChild()) {
						if (!this._isOpened(item)) {
							this._close({ nativeEvent: options.nativeEvent });
							this._open(item, { nativeEvent: options.nativeEvent });
						}
					} else {
						if (this._isOpened(this._hoveredItem)) {
							this._close({ nativeEvent: options.nativeEvent });
						}
					}
				}
			}

			if (options.useSameCheck && isSameItem) {
				return;
			}
			this._hoveredItem = item;
			if (options.doInitSubMenu) {
				this._resetMenu();
			}
			this._owner.redraw();
		}

		public _setFocusedItem(item: MenuItem, options: { preventScroll: boolean } = { preventScroll: false }) {
			let topParentItem = this._getTopParentItem(item);
			if (options.preventScroll === false) {
				this._updateScrollByHover(topParentItem, this._hoveredItem);
			}
			this._hoveredItem = topParentItem;
			this._setOpen(topParentItem, { emitEvent: false });
			let menu = this._getActiveMenu();
			if (menu) {
				if (item && item.depth > 0) {
					menu.init();
					menu._setFocusedItem(item);
				} else {
					menu.init();
				}
			}
			this._owner.redraw();
		}

		protected _getHover() {
			let menu = this._getActiveMenu();
			let hover = null;
			if (menu) {
				hover = menu.getHoveredItem();
			}
			let isOpenedMenuHover = hover && this._isOpened(this._getHoveredItem());
			if (!isOpenedMenuHover) {
				return this._getHoveredItem();
			}
			return hover;
		}

		protected _setHover(item: MenuItem, options: { useSameCheck?: boolean, nativeEvent?: Event, preventOpen?: boolean } = {}) {
			_defaults(options, { useSameCheck: false, nativeEvent: null, preventOpen: false });
			if (item == null || item.depth == 0) {

				if (item) {
					let rootNode = this._owner._getRenderer().getRootNode();
					this._isAppliedTransformStyle = this._checkAppliedTransformStyle(rootNode);
				}

				this._setHoveredItem(item, { useSameCheck: options.useSameCheck, nativeEvent: options.nativeEvent, preventOpen: options.preventOpen });
			} else {
				let rootItem = this._getParent(item, (each) => {
					return each.depth == 0;
				});
				this._setHoveredItem(rootItem, { doInitSubMenu: true, nativeEvent: options.nativeEvent });

				let menu = this._getMenu(rootItem.value);
				if (menu) {
					menu.setHoveredItem(item, { updateScroll: true });
				}
			}
		}

		protected _getActiveMenu(): menu.IAccessibleMenu {
			let itemValue = null;
			let openedItem = this._getOpenedItem();
			if (openedItem) {
				itemValue = openedItem.value;
			} else {
				return null;
			}
			return this._getMenu(itemValue);

		}

		protected _resetMenu() {
			for (let key in this._menus) {
				this._menus[key].init();
			}
		}

		protected _clearMenu() {
			for (let key in this._menus) {
				this._menus[key].dispose();
			}
			this._menus = {};
		}

		/**
		 * 초점이 해제되었을 때 이벤트.
		 * blur > focus 이벤트 순서로 발생한다. relatedTarget는 document.activeElement로 확인한다.
		 * @param e 
		 */
		public override  _onblur(e: events.CFocusEvent) {
			super._onblur(e);
			let relatedTarget: HTMLElement = e.nativeEvent["relatedTarget"] as HTMLElement || document.activeElement as HTMLElement;
			let isOwnedElement = false;

			this._focusTrigger = null;
			if (relatedTarget && relatedTarget != e.target) { // 브라우저에서 다른 윈도우 선택시 자신에게 blur가 발생한다.
				let submenu = this._getActiveMenu();
				let menuRootNode = submenu ? this._owner._getRenderer().getNamedNode(submenu.getRootNodeName()) : null;
				let rootNode = this._owner._getRenderer().getRootNode();
				if (rootNode == relatedTarget) {
					this._focusTrigger = { type: "self", forward: true };
				}
				if (rootNode && menuRootNode) {
					isOwnedElement = rootNode.contains(relatedTarget) || menuRootNode.contains(relatedTarget);
				}
			}
			if (!isOwnedElement) {
				this._close({ nativeEvent: e });
				this._clearHoveredItem({ closeMenu: false });
				this._resetMenu();
			}
		}

		protected _getMenu(itemValue: string) {
			let menu: menu.IAccessibleMenu = null;

			if (!this._menus[itemValue]) {
				let rootItems = this._getRootItems();
				let findItem = _.find(rootItems, (item: TreeItem) => {
					return item._match({ value: itemValue });
				})
				if (findItem) {
					this._menus[itemValue] = this._createMenu();
				}
			}
			menu = this._menus[itemValue] ?? null;

			return menu;
		}

		protected _onMenuItemSelect(e: events.CItemEvent) {
			let item: MenuItem = e.item;
			this._binder._select(item, this._binder.getMultiple());
		}
		protected _onMenuItemClick(e: events.CItemEvent) {
			this._owner.dispatchEvent(e);
		}
		protected _onMenuItemSelected(e: events.CItemEvent) {
			let item = e.item;
			if (this._close({ nativeEvent: e })) {
				this._focusBySelector(this._getFocusSelector(this._getTopParentItem(item)), { immediate: true, useSameCheck: false, lazyItemFocus: false });
			}
		}

		protected _onMenuItemFocus(e: events.CItemEvent) {
			let item = e.item;
			this._setHover(item, { useSameCheck: true });
		}

		protected _onmouseenter(e: MouseEvent) {
			let submenu = this._getActiveMenu();
			if (!submenu) {
				return;
			}
			submenu.cancelTimeoutEvent(controls.menu.MenuTimeoutEventType.mouseleave);
			if (this._owner.expandTrigger == "hover") {
				submenu.setHoveredItem(null);
			}
		}

		private _focusImmediateBySelector(selector: string, options: { preventOpen?: boolean, useSameCheck?: boolean, lazyItemFocus?: boolean } = {}) {
			if (this._owner.disposed) {
				return;
			}

			let node = this._owner._getRenderer().getRootNode();
			if (node) {
				let focusableEle = null;
				focusableEle = node.querySelector(selector) as HTMLElement;

				if (focusableEle) {
					focusableEle.focus();
				}
			}
			if (options.lazyItemFocus) {
				core.DeferredUpdateManager.INSTANCE.asyncExec(() => {
					if (this.disposed) {
						return;
					}
					this._setTabFocusBySelector(selector, options);
				})
			} else {
				this._setTabFocusBySelector(selector, options);
			}
		}

		private _setTabFocusBySelector(selector: string, options: { preventOpen?: boolean, useSameCheck?: boolean } = {}) {
			let match = selector.match(/\[data-itemid='(.+)?'\]/i);
			let value = null;
			if (match && match.length == 2) {
				value = match[1] ?? "";
			}
			if (value == null) {
				return;
			}
			let item = this._owner.getItemByValue(value);
			if (item && this._owner.getItemEnable(item)) {
				this._setHover(item, { useSameCheck: options.useSameCheck, preventOpen: options.preventOpen });
			}
		}

		public _getFocusSelector(item: MenuItem) {
			if (item == null) {
				return "";
			}
			if (item.parentItem == null) {
				return NavigationBarItemFocusEntry.createSelector(item.value);
			} else {
				let menu = this._getActiveMenu();
				if (menu) {
					return menu._createFocusSelector(item.value);
				}
			}
			return "";
		}

		public _focusBySelector(selector: string, options: { immediate?: boolean, preventOpen?: boolean, useSameCheck?: boolean, lazyItemFocus?: boolean } = {}) {
			_defaults(options, { immediate: false, preventOpen: false, useSameCheck: true, lazyItemFocus: true });
			if (options.immediate) {
				this._focusImmediateBySelector(selector, options);
			} else {
				core.DeferredUpdateManager.INSTANCE._performFocusTask(() => {
					this._focusImmediateBySelector(selector, options);
				});
			}
		}

		public _getFocusEntries(): ItemFocusEntry[] {
			let rootItems = this._getRootItems();

			let focusEntries: ItemFocusEntry[] = [];
			rootItems.forEach((each: MenuItem) => {
				if (this._owner.getItemEnable(each)) {
					focusEntries.push(new NavigationBarItemFocusEntry(this._owner, NavigationBarItemFocusEntry.createSelector(each.value)));
				}
				if (this._isOpened(each)) {
					let menu = this._getMenu(each.value);
					if (menu) {
						focusEntries = focusEntries.concat(menu._getFocusEntries());
					}
				}
			})
			return focusEntries;
		}

		/**
		 * 
		 * @param includeEntry 
		 * @returns 포커스 설정 성공 여부
		 */
		public _focusPrevious(includeEntry?: boolean): boolean {
			if (!this._owner.tabTraversal) {
				return false;
			}
			let activeFocusEntry = this._getActiveFocusEntry();
			if (!activeFocusEntry) {
				let menu = this._getActiveMenu();
				if (menu) {
					activeFocusEntry = menu._getActiveFocusEntry();
				}
			}
			let focusRing = new NavigationBarFocusRing(this._owner, activeFocusEntry);
			if (activeFocusEntry == null) {
				return false;
			} else {
				return focusRing._focusPrevious();
			}
		}

		public _focusNext(includeEntry?: boolean): boolean {
			if (!this._owner.tabTraversal) {
				return false;
			}
			let activeFocusEntry = this._getActiveFocusEntry();
			if (!activeFocusEntry) {
				let menu = this._getActiveMenu();
				if (menu) {
					activeFocusEntry = menu._getActiveFocusEntry();
				}
			}
			let focusRing = new NavigationBarFocusRing(this._owner, activeFocusEntry);
			if (activeFocusEntry == null) {
				return focusRing._focusFirst()
			} else {
				return focusRing._focusNext();
			}

		}

		private _getActiveFocusEntry() {
			let activeElement = document.activeElement as HTMLElement;
			let findFocusEntry = null;
			if (!activeElement) {
				return findFocusEntry;
			}
			let rootElement = this._owner._getRenderer().getRootNode();
			let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(activeElement)._closest("[data-role='menuitem']", rootElement);
			if (domTraverser == null) {
				return findFocusEntry;
			}
			let itemElement = domTraverser._getElement();
			let itemid = itemElement.getAttribute("data-itemid");
			if (itemid == null) {
				return findFocusEntry;
			}
			let selector = NavigationBarItemFocusEntry.createSelector(itemid);
			findFocusEntry = _.find(this._getFocusEntries(), (each) => {
				return each.selector == selector;
			});

			return findFocusEntry;
		}

	}
}