
///<reference path="./provider/DataBindable.ts"/>
///<reference path="./EnableUIControl.ts"/>
namespace cpr.controls {
	/**
	 * Progress
	 * 작업의 진행 상태를 시각적으로 표현하는 컨트롤.
	 * 
	 * @firesgroup mouse
	 * @firesgroup contextmenu
	 * @firesgroup bindcontext
	 * @firesgroup keyboard
	 * @firesgroup drop
	 * 
	 * 
	 * @fires cpr.events.CValueChangeEvent#before-value-change 값이 변경 되기 전에 발생하는 이벤트.
	 * 		다음 이벤트로 value-change가 발생합니다.
	 * 		<pre>oldValue: {string} 이전 값</pre>
	 * 		<pre>newValue: {string} 현재 값</pre>
	 * 
	 * @fires cpr.events.CValueChangeEvent#value-change 값이 변경된 후 발생하는 이벤트.
	 * 		<pre>oldValue: {string} 이전 값</pre>
	 * 		<pre>newValue: {string} 현재 값</pre>
	 * 
	 * @fires cpr.events.CValueChangeEvent#complete 값이 최댓값을 넘으면 발생하는 이벤트.
	 * 		<pre>oldValue: {string} 이전 값</pre>
	 * 		<pre>newValue: {string} 현재 값</pre>
	 */
	export class Progress extends EnableUIControl implements provider.ValueBindable, gridpart.IGridParticipant {
		private static readonly _AVAILABLE_PROP: string[] = [
			"value", "text", "numberValue", "max", "notSupportMessage", "showText", "displayExp"
		];

		private _min: number = 0;// 최소 값
		private _binder: provider.ValueBinder;
		private _showText: boolean = false;
		private _displayExp: expression_string;
		/**
		 * 프로그레스를 생성합니다.
		 * @param id 프로그레스의 id
		 */
		constructor(id?: string) {
			super(id);
			this._binder = new provider.ValueBinder(this);
			// this.tabIndex = -1;

			this._addBindableProperty("max", 100).withSetterValidatorWithType(false, "number");

			this._binder.setValue("0", false);
			// control initializing
			this._initControl();
		}

		protected _isConfigurableProperty(propName: string): boolean {
			if (Progress._AVAILABLE_PROP.indexOf(propName) != -1) {
				return true;
			}
			return super._isConfigurableProperty(propName);
		}

		/* Shape */
		protected _getStylerSpec(): UIControlStylerSpec {
			return {
				root: { baseClass: "cl-progress" },
				bar: { baseClass: "cl-progress-bar" }
			};
		}
		/**
		 * 자동 크기 지원 타입을 얻습니다.
		 * 만일 both를 리턴했다면, css height, width 속성에 auto를 사용할 수 있음을 나타냅니다.
		 */
		override _getAutoSizeAvailability(): layouts.AutoSizeType {
			return layouts.AutoSizeType.both;
		}

		public _convertGridPasteText(text: string): string {
			return text;
		}

		public _getGridViewingText(): string {
			let text: string = this.text;
			let value: string = this.value;
			text = (text != null) ? text : ((value != null) ? value : "");
			return text;
		}

		public _renderGridCellShape(grid: Grid, data: (string | ufc.StyledString), option: gridpart.renderer.IRenderOption): ufc.ControlShape {
			// TODO 개별 UIControl에서 Shape을 그리기에 필요한 정보는 public으로 접근할 수 있도록 표준화 필요

			let shape: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: ["cl-control", "cl-progress"],
				attr: {
					tabindex: "-1",
					role: "img"
				},
				style: {
					position: "relative",
					height: option.maxHeight + "px"
				},
				children: []
			};
			cpr.ufc.ShapeUtil._setAriaLabelAttr(shape.attr, this.fieldLabel);

			let width: number = this._calcWidth();
			let partShape: cpr.ufc.ElementShape = { // part
				tag: "div",
				classNames: ["cl-progress-bar"],
				style: {
					width: width + "%"
				}
			}
			gridpart.GridUtil._applyControlStyler(partShape, this.style["bar"], null);		//apply styler

			layouts.GridCSSBuilder._forCell()._withColumnStart(1)._withRowStart(1)._commit(partShape.style);

			let wrapShape: cpr.ufc.ElementShape = {
				tag: "div",
				classNames: [],
				attr: {},
				style: {
					width: "100%",
					height: "100%"
				},
				children: [partShape]
			}
			layouts.GridCSSBuilder._forLayout()._withTemplateColumns("1fr")._withTemplateRows("1fr")._commit(wrapShape.style);

			if (this.showText) {
				let textShape: cpr.ufc.ElementShape = {
					tag: "div",
					classNames: [ufc.Classes.TEXT],
					attr: {},
					style: {},
					children: ufc.StyledString._asShape(this._computeDisplayText())
				};
				layouts.GridCSSBuilder._forCell()._withColumnStart(1)._withRowStart(1)._withVerticalAlign(layouts.GridCellAlign.center)._commit(textShape.style);

				wrapShape.children.push(textShape);
			}
			shape.children.push(wrapShape);

			return shape;
		}

		/* control's type overriding */
		override _getType(): ControlType {
			return ControlType.PROGRESS;
		}
		override _getLabelableType(): LabelableType {
			return LabelableType.div;
		}

		/**
		 * 프로그래스 컨트롤은 포커스를 가지지 못하는 컨트롤이므로 focusable 을 false로 주기 위해 _isFocusable 을 오버라이드합니다.
		 */
		protected _isFocusable(): boolean {
			return false;
		}

		/**
		 * @param propertyName 
		 * @param oldValue 
		 * @param newValue 
		 */
		_valueDidChange(propertyName: string, oldValue: any, newValue: any) {
			super._valueDidChange(propertyName, oldValue, newValue)
			this._binder._valueDidChange(propertyName, oldValue, newValue);

			switch (propertyName) {
				case "value": {
					let canComplete = isNaN(parseInt(oldValue)) || parseInt(oldValue) < this.max;
					if (this.max <= parseInt(newValue) && canComplete) {
						let completeEvent = new cpr.events.CValueChangeEvent("complete", { oldValue: oldValue, newValue: newValue });
						this.dispatchEvent(completeEvent);
					}
					break;
				}
				case "max": {
					this.redraw();
					break;
				}
			}
		}

		/// SimpleDataBindable Start ////////////////////////////////////////////
		/**
		 * 컨트롤의 값을 설정하고, value-change이벤트가 발생됩니다.
		 * @param value 컨트롤의 값.
		 */
		public set value(value: string) {
			this._binder.setValue(value);
		}

		/**
		 * 컨트롤의 값을 반환합니다.
		 * @return 컨트롤의 값.
		 */
		public get value(): string {
			return this._binder.getValue();
		}

		/**
		 * 컨트롤의 값을 설정합니다.
		 * @param value 컨트롤의 값.
		 */
		public putValue(value: string) {
			this._binder.setValue(value, false);
		}

		/**
		 * 컨트롤에 보여지는 텍스트를 반환합니다.
		 * @return 화면에 보이는 텍스트.
		 */
		public get text(): string {
			return ufc.StyledString._asString(this._computeDisplayText());
		}

		/**
		 * 컨트롤에 보이는 텍스트를 설정합니다.
		 * @param 화면에 보이는 텍스트.
		 */
		public set text(text: string) {
			this._binder.setText(text);
		}

		/// SimpleDataBindable End ////////////////////////////////////////////////

		/**
		 * 프로그레스의 값을 숫자 형식으로 얻습니다.
		 * @return 컨트롤에 저장되는 값.
		 */
		get numberValue(): number {
			return parseFloat(this.value || "" + this._min);
		}

		/**
		 * 프로그레스의 값을 숫자 형식으로 지정합니다.
		 * @param value 컨트롤에 저장되는 값.
		 */
		set numberValue(value: number) {
			if (typeof value != "number" || (value > this.max || value < this._min))
				return;
			this.value = "" + value;
			this.redraw();
		}

		/**
		 * 최댓값을 반환합니다.
		 * @return 최댓값.
		 */
		get max(): number {
			return this._bindables.get("max");
		}

		/**
		 * 최댓값을 설정합니다.
		 * @param value 최댓값.
		 */
		set max(value: number) {
			this._bindables.set("max", value);
		}

		/**
		 * 텍스트 표시여부를 반환합니다.
		 * @return 텍스트 표시여부.
		 */
		get showText(): boolean {
			return this._showText;
		}

		/**
		 * 텍스트 표시여부를 설정합니다.
		 * @param show 텍스트 표시여부.
		 */
		set showText(show: boolean) {
			this._showText = show;
			this.redraw();
		}


		/**
		 * 표시할 텍스트에 대한 표현식을 반환합니다.
		 * @return 표현식
		 */
		get displayExp(): expression_string {
			return this._displayExp;
		}

		/**
		 * 표시할 텍스트에 대한 표현식을 설정합니다.
		 * @param exp 표현식.
		 */
		set displayExp(exp: expression_string) {
			this._displayExp = exp;
			this.redraw();
		}

		/**
		 * 진행도를 표현하는 비율을 반환합니다.
		 * @readonly
		 * @return 비율 
		 */
		get progressRatio(): number {
			let ratio: number = this._checkNumberValueRange(this.numberValue) / this.max;
			return Number(ratio.toFixed(2));
		}

		public _computeDisplayText(): ufc.StyledString | string {
			let resultText = this._binder.getText();
			if (!this.showText) {
				return resultText;
			}
			if (this.displayExp) {
				let expr = new cpr.expression.Expression(this.displayExp);
				let textValue = this.value ? this.value : utils.Util.toString(this._min)

				try {
					let that = this;
					resultText = expr._evaluateInternal({
						_getExpressionOnlyProperty(name: string): any {
							switch (name) {
								case "self": {
									return that;
								}
								default: return undefined;
							}
						},
						_getExpressionDelegates(): any[] {
							return [{ text: textValue }, that, that.getBindContext()];
						}
					});
				} catch (e) {
					resultText = textValue;
				}
			}
			return resultText;
		}

		/* shape */
		public _createShape(): cpr.ufc.ControlShape {
			let computedDisplayText: string | ufc.StyledString = this._computeDisplayText();
			let shape: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: [],
				attr: {
					role: "progressbar",
					tabindex: "-1",
					"aria-valuenow": this.value,
					"aria-valuemin": "0",
					"aria-valuemax": this.max + ""

				},
				style: {
					position: "relative",
					overflow: "hidden"
				},
				styler: "root",
				events: {},
				eventTargets: [
					ufc.EventTargetType.UICONTROL,
					ufc.EventTargetType.DROPPABLE
				],
				children: []
			}
			let bar = this._createBar();
			if (this.showText) {
				shape.attr["aria-valuetext"] = ufc.StyledString._asString(computedDisplayText);
				bar.children.push(this._createText(computedDisplayText));
			}
			shape.children.push(bar);
			cpr.ufc.ShapeUtil._setAriaLabelAttr(shape.attr, this._getFieldLabel());
			cpr.ufc.ShapeUtil._setTooltipAttr(shape, { owner: this, title: this.tooltip });

			return shape;
		}

		private _createBar(): cpr.ufc.ElementShape {
			let width: number = this._calcWidth();

			let part: cpr.ufc.ElementShape = {
				tag: "div",
				classNames: [],
				styler: "bar",
				style: {
					width: width + "%"
				}
			}

			layouts.GridCSSBuilder._forCell()._withColumnStart(1)._withRowStart(1)._commit(part.style);

			let wrap: cpr.ufc.ElementShape = {
				tag: "div",
				classNames: [],
				attr: {},
				style: {
					width: "100%",
					height: "100%",
					overflow: "hidden"
				},
				children: [part]
			}

			layouts.GridCSSBuilder._forLayout()._withTemplateColumns("1fr")._withTemplateRows("1fr")._commit(wrap.style);
			return wrap;
		}

		private _createText(computedDisplayText: string | ufc.StyledString): cpr.ufc.ElementShape {
			let textShape: cpr.ufc.ElementShape = {
				tag: "div",
				classNames: [ufc.Classes.TEXT],
				attr: {},
				style: {
					overflow: "hidden"
				},
				children: ufc.StyledString._asShape(computedDisplayText)
			};

			layouts.GridCSSBuilder._forCell()._withColumnStart(1)._withRowStart(1)._withVerticalAlign(layouts.GridCellAlign.center)._commit(textShape.style);

			return textShape;
		}

		/* private method */
		private _checkNumberValueRange(num: number): number {
			if (isNaN(num)) {
				return this._min;
			}
			num = Math.max(this._min, Math.min(this.max, num));
			return num;
		}

		// private _getText(): string {
		// 	let text: string;
		// 	if (!this.showText) {
		// 		return this._binder.getText();
		// 	}
		// 	if (this.displayExp) {
		// 		text = this._getDisplayExpText();
		// 	} else {
		// 		let number: number = this.progressRatio * 100;
		// 		text = Math.round(number) + "%";
		// 	}
		// 	return text;
		// }

		public _calcWidth(): number {
			let numberValue = this._checkNumberValueRange(this.numberValue);
			let width: number = ((numberValue - this._min) / (this.max - this._min)) * 100;			//% 비율로 변경
			return width;
		}

		public _exportValue(): string | number {
			let ctrlText = (this.text === undefined) ? this.value : this.text;

			// 기본 >> text
			return (ctrlText != null) ? "" + ctrlText : "";
		}
	}
}