namespace cpr.vdom {

	/**
	 * @private
	 * @param a 
	 * @param b 
	 * @returns 
	 */
	export function diff(a: VNode, b: VNode): VPatches {
		let patch = { a: a }
		walk(a, b, patch, 0)
		return patch
	}

	function walk(a: VTreeElement, b: VTreeElement, patch: VPatches, index: number) {
		if (a === b) {
			return;
		}

		let apply = patch[index];
		let applyClear = false;

		if (_isThunk(a) || _isThunk(b)) {
			_thunks(a, b, patch, index);
		}
		else if (b == null) {
			// If a is a widget we will add a remove patch for it
			// Otherwise any child widgets/hooks must be destroyed.
			// This prevents adding two remove patches for a widget.
			if (!_isWidget(a)) {
				clearState(a, patch, index)
				apply = patch[index]
			}
			apply = _appendPatch(apply, new VPatch(VPatchType.REMOVE, a as VNode, b));
		}
		else if (_isVNode(b)) {
			let vNodeB = b as VNode;
			if (_isVNode(a)) {
				let vNodeA = a as VNode;
				if (vNodeA.tagName === vNodeB.tagName &&
					vNodeA.namespace === vNodeB.namespace &&
					vNodeA.key === vNodeB.key) {
					let propsPatch = diffProps(vNodeA.properties, vNodeB.properties)
					if (propsPatch) {
						apply = _appendPatch(apply,
							new VPatch(VPatchType.PROPS, vNodeA, propsPatch))
					}
					apply = diffChildren(vNodeA, vNodeB, patch, apply, index)
				} else {
					apply = _appendPatch(apply, new VPatch(VPatchType.VNODE, vNodeA, vNodeB))
					applyClear = true
				}
			} else {
				apply = _appendPatch(apply, new VPatch(VPatchType.VNODE, a, vNodeB))
				applyClear = true
			}
		}
		else if (_isVText(b)) {
			if (!_isVText(a)) {
				apply = _appendPatch(apply, new VPatch(VPatchType.VTEXT, a, b))
				applyClear = true
			} else if (a.text !== b.text) {
				apply = _appendPatch(apply, new VPatch(VPatchType.VTEXT, a, b))
			}
		}
		else if (_isWidget(b)) {
			if (!_isWidget(a)) {
				applyClear = true
			}

			apply = _appendPatch(apply, new VPatch(VPatchType.WIDGET, a as VNode, b))
		}

		if (apply) {
			patch[index] = apply;
		}

		if (applyClear) {
			clearState(a, patch, index);
		}
	}

	/**
	 * VNode를 비교합니다.
	 * @param a 
	 * @param b 
	 * @param patch 
	 * @param apply 
	 * @param index 
	 * @returns 
	 */
	function diffChildren(a: VNode, b: VNode, patch: VPatches, apply, index: number) {
		let aChildren = a.children
		let orderedSet = _reorder(aChildren, b.children)
		let bChildren = orderedSet.children

		let aLen = aChildren.length
		let bLen = bChildren.length
		let len = aLen > bLen ? aLen : bLen

		for (let i = 0; i < len; i++) {
			let leftNode = aChildren[i]
			let rightNode = bChildren[i]
			index += 1

			if (!leftNode) {
				if (rightNode) {
					// Excess nodes in b need to be added
					apply = _appendPatch(apply,
						new VPatch(VPatchType.INSERT, null, rightNode))
				}
			} else {
				walk(leftNode, rightNode, patch, index)
			}

			if (_isVNode(leftNode) && (leftNode as VNode).count) {
				index += (leftNode as VNode).count
			}
		}

		if (orderedSet.moves) {
			// Reorder nodes last
			apply = _appendPatch(apply, new VPatch(
				VPatchType.ORDER,
				a,
				orderedSet.moves
			))
		}

		return apply
	}
	function clearState(vNode, patch, index) {
		// TODO: Make this a single walk, not two
		_unhook(vNode, patch, index)
		_destroyWidgets(vNode, patch, index)
	}

	// Patch records for all destroyed widgets must be added because we need
	// a DOM node reference for the destroy function
	function _destroyWidgets(vNode: VNode, patch: VPatches, index: number) {
		if (_isWidget(vNode)) {
			if (typeof vNode["destroy"] === "function") {
				patch[index] = _appendPatch(
					patch[index],
					new VPatch(VPatchType.REMOVE, vNode, null)
				)
			}
		} else if (_isVNode(vNode) && (vNode.hasWidgets || vNode.hasThunks)) {
			let children = vNode.children
			let len = children.length
			for (let i = 0; i < len; i++) {
				let child = children[i]
				index += 1

				_destroyWidgets(child as VNode, patch, index)

				if (_isVNode(child) && (child as VNode).count) {
					index += (child as VNode).count
				}
			}
		} else if (_isThunk(vNode)) {
			_thunks(vNode, null, patch, index)
		}
	}

	// Create a sub-patch for thunks
	function _thunks(a: VTreeElement, b: VTreeElement, patch: VPatches, index: number) {
		let nodes = _handleThunk(a, b)
		let thunkPatch = diff(nodes.a as VNode, nodes.b as VNode)
		if (_hasPatches(thunkPatch)) {
			patch[index] = new VPatch(VPatchType.THUNK, null, thunkPatch)
		}
	}

	function _hasPatches(patch: VPatches) {
		for (let index in patch) {
			if (index !== "a") {
				return true
			}
		}

		return false
	}

	// Execute hooks when two nodes are identical
	function _unhook(vNode: VTreeElement, patch: VPatches, index: number) {
		if (_isVNode(vNode)) {
			vNode = vNode as VNode;
			if (vNode.hooks) {
				patch[index] = _appendPatch(
					patch[index],
					new VPatch(
						VPatchType.PROPS,
						vNode,
						_undefinedKeys(vNode.hooks)
					)
				)
			}

			if (vNode.descendantHooks || vNode.hasThunks) {
				let children = vNode.children
				let len = children.length
				for (let i = 0; i < len; i++) {
					let child = children[i];
					index += 1

					_unhook(child, patch, index)

					if (_isVNode(child) && (child as VNode).count) {
						index += (child as VNode).count
					}
				}
			}
		} else if (_isThunk(vNode)) {
			_thunks(vNode, null, patch, index)
		}
	}

	function _undefinedKeys(obj: {}) {
		let result = {}

		for (let key in obj) {
			result[key] = undefined
		}

		return result
	}

	// List diff, naive left to right reordering
	function _reorder(aChildren: VTreeElement[], bChildren: VTreeElement[]) {
		// O(M) time, O(M) memory
		let bChildIndex = _keyIndex(bChildren)
		let bKeys = bChildIndex.keys;
		let bFree = bChildIndex.free;

		if (bFree.length === bChildren.length) {
			return {
				children: bChildren,
				moves: null
			}
		}

		// O(N) time, O(N) memory
		let aChildIndex = _keyIndex(aChildren)
		let aKeys = aChildIndex.keys
		let aFree = aChildIndex.free

		if (aFree.length === aChildren.length) {
			return {
				children: bChildren,
				moves: null
			}
		}

		// O(MAX(N, M)) memory
		let newChildren = []

		let freeIndex = 0
		let freeCount = bFree.length
		let deletedItems = 0

		// Iterate through a and match a node in b
		// O(N) time,
		for (let i = 0; i < aChildren.length; i++) {
			let aItem = aChildren[i] as VNode
			let itemIndex: number

			if (aItem.key) {
				if (bKeys.hasOwnProperty(aItem.key)) {
					// Match up the old keys
					itemIndex = bKeys[aItem.key]
					newChildren.push(bChildren[itemIndex])

				} else {
					// Remove old keyed items
					itemIndex = i - deletedItems++
					newChildren.push(null)
				}
			} else {
				// Match the item in a with the next free item in b
				if (freeIndex < freeCount) {
					itemIndex = bFree[freeIndex++]
					newChildren.push(bChildren[itemIndex])
				} else {
					// There are no free items in b to match with
					// the free items in a, so the extra free nodes
					// are deleted.
					itemIndex = i - deletedItems++
					newChildren.push(null)
				}
			}
		}

		let lastFreeIndex = freeIndex >= bFree.length ? bChildren.length : bFree[freeIndex];

		// Iterate through b and append any new keys
		// O(M) time
		for (let j = 0; j < bChildren.length; j++) {
			let newItem = bChildren[j] as VNode;

			if (newItem.key) {
				if (!aKeys.hasOwnProperty(newItem.key)) {
					// Add any new keyed items
					// We are adding new items to the end and then sorting them
					// in place. In future we should insert new items in place.
					newChildren.push(newItem)
				}
			} else if (j >= lastFreeIndex) {
				// Add any leftover non-keyed items
				newChildren.push(newItem)
			}
		}

		let simulate = newChildren.slice() as VTreeElement[]
		let simulateIndex = 0
		let removes = []
		let inserts = []
		let simulateItem

		for (let k = 0; k < bChildren.length;) {
			let wantedItem = bChildren[k] as VNode;
			simulateItem = simulate[simulateIndex] as VNode;

			// remove items
			while (simulateItem === null && simulate.length) {
				removes.push(_remove(simulate, simulateIndex, null))
				simulateItem = simulate[simulateIndex]
			}

			if (!simulateItem || simulateItem.key !== wantedItem.key) {
				// if we need a key in this position...
				if (wantedItem.key) {
					if (simulateItem && simulateItem.key) {
						// if an insert doesn't put this key in place, it needs to move
						if (bKeys[simulateItem.key] !== k + 1) {
							removes.push(_remove(simulate, simulateIndex, simulateItem.key))
							simulateItem = simulate[simulateIndex]
							// if the remove didn't put the wanted item in place, we need to insert it
							if (!simulateItem || simulateItem.key !== wantedItem.key) {
								inserts.push({ key: wantedItem.key, to: k })
							}
							// items are matching, so skip ahead
							else {
								simulateIndex++
							}
						}
						else {
							inserts.push({ key: wantedItem.key, to: k })
						}
					}
					else {
						inserts.push({ key: wantedItem.key, to: k })
					}
					k++
				}
				// a key in simulate has no matching wanted key, remove it
				else if (simulateItem && simulateItem.key) {
					removes.push(_remove(simulate, simulateIndex, simulateItem.key))
				}
			}
			else {
				simulateIndex++
				k++
			}
		}

		// remove all the remaining nodes from simulate
		while (simulateIndex < simulate.length) {
			simulateItem = simulate[simulateIndex]
			removes.push(_remove(simulate, simulateIndex, simulateItem && simulateItem.key))
		}

		// If the only moves we have are deletes then we can just
		// let the delete patch remove these items.
		if (removes.length === deletedItems && !inserts.length) {
			return {
				children: newChildren,
				moves: null
			}
		}

		return {
			children: newChildren,
			moves: {
				removes: removes,
				inserts: inserts
			}
		}
	}

	function _remove(arr: VTreeElement[], index: number, key: string) {
		arr.splice(index, 1)

		return {
			from: index,
			key: key
		}
	}

	function _keyIndex(children: VTreeElement[]) {
		let keys: { [hashkey: string]: number } = {};
		let free: number[] = [];
		let length = children.length

		for (let i = 0; i < length; i++) {
			let child = children[i]

			if ((child as VNode).key) {
				keys[(child as VNode).key] = i
			} else {
				free.push(i)
			}
		}

		return {
			keys: keys,     // {키 : 인덱스}
			free: free      // 키가 없는 요소들의 인덱스 배열
		}
	}

	function _appendPatch(apply: VPatch | VPatch[], patch: VPatch): VPatch | VPatch[] {
		if (apply) {
			if (_isArray(apply)) {
				(apply as VPatch[]).push(patch);
			} else {
				apply = [apply as VPatch, patch];
			}

			return apply;
		} else {
			return patch;
		}
	}

	function diffProps(a: VDomProperties, b: VDomProperties): VPatches {
		let diff: VPatches;

		for (let aKey in a) {
			if (!(aKey in b)) {
				diff = diff || {} as VPatches
				diff[aKey] = undefined
			}

			let aValue = a[aKey]
			let bValue = b[aKey]

			if (aValue === bValue) {
				continue
			} else if (_isIndividualObject(aValue) && _isIndividualObject(bValue)) {
				if (Object.getPrototypeOf(bValue) !== Object.getPrototypeOf(aValue)) {
					diff = diff || {} as VPatches
					diff[aKey] = bValue
				} else if (_isHook(bValue)) {
					diff = diff || {} as VPatches
					diff[aKey] = bValue
				} else {
					let objectDiff = diffProps(aValue, bValue)
					if (objectDiff) {
						diff = diff || {} as VPatches
						diff[aKey] = objectDiff
					}
				}
			} else {
				diff = diff || {} as VPatches
				diff[aKey] = bValue
			}
		}

		for (let bKey in b) {
			if (!(bKey in a)) {
				diff = diff || {} as VPatches
				diff[bKey] = b[bKey]
			}
		}

		return diff
	}
}