/// <reference path="./DOMEventWrapper.ts" />


namespace cpr.events {
	/**
	 * submission 이벤트 유형.
	 */
	export class SubmissionEventType {
		/**
		 * 통신을 시작하기전에 발생하는 이벤트.
		 */
		public static readonly BEFORE: string = "before-submit";

		/**
		 * XMLHttpRequest가 open된 후 send 함수가 호출되기 직전에 발생하는 이벤트.
		 * 타솔루션과 연동을 위해 제공되는 이벤트로
		 * Submission.xhr을 획득하여 헤더를 추가하는 것 이외에 다른 작업은 오동작을 발생시킬 수 있어 주의가 필요합니다.
		 */
		public static readonly BEFORE_SEND: string = "before-send";

		/**
		 * 서버로 부터 에러로 분류되는 HTTP상태 코드를 전송받았을 때 발생하는 이벤트.
		 * 상태코드가 200이 아니면 서버의 응답처리를 중단하고 submit-error 이벤트가 발생하나
		 * error-status 이벤트 핸들러에서 e.preventDefault()를 호출하면
		 * 서버의 응답데이터를 모두 처리한 후 submit-error 이벤트가 발생합니다.
		 */
		public static readonly ERROR_STATUS: string = "error-status";

		/**
		 * 서버로 부터 데이터를 모두 전송받았을 때 발생하는 이벤트.
		 */
		public static readonly RECEIVE: string = "receive";

		/**
		 * 서버로 부터 받은 응답데이터를 JSONObject로 파싱을 성공했을 때 발생하는 이벤트.
		 * 응답 프로토콜이 json일 때만 발생합니다.
		 */
		public static readonly RECEIVE_JSON: string = "receive-json";

		/**
		 * 통신이 성공하면 발생하는 이벤트.
		 */
		public static readonly SUCCESS: string = "submit-success";

		/**
		 * 통신 중 문제가 생기면 발생하는 이벤트.
		 */
		public static readonly ERROR: string = "submit-error";

		/**
		 * 응답처리가 모두 종료되면 발생하는 이벤트.
		 */
		public static readonly DONE: string = "submit-done";

		/**
		 * 응답 데이터컨트롤에 데이터가 부분적으로 적재되었을 때 발생하는 이벤트.
		 * submit-progress는 데이터 적재여부와 상관없이 호출되는 반면 submit-load-progress는
		 * 부분적재가 가능한 응답프로토콜에서 데이터의 부분적재가 일어났을 때 발생.
		 */
		public static readonly LOAD_PROGRESS: string = "submit-load-progress";

		/**
		 * multipart/form-data 일 때 서버로 일정 크기의 데이터를 전송했을 때 발생하는 이벤트.
		 */
		public static readonly UPLOAD_PROGRESS: string = "submit-upload-progress";

		/**
		 * Submission이 종료되기 전 정기적으로 호출되는 이벤트.
		 */
		public static readonly PROGRESS: string = "submit-progress";

		/**
		 * 통신 중 Timeout이 발생했을 때 호출되는 이벤트
		 */
		public static readonly TIMEOUT: string = "submit-timeout";
	}

	/**
	 * 서브미션에서 발생하는 이벤트.
	 */
	export class CSubmissionEvent extends CEvent {

		/**
		 * "submit-error" 이벤트의 원인 error 객체.
		 * "submit-error" 이벤트의 발생 원인이 Error에 의한 경우 발생한 Error 객체를 리턴합니다.
		 */
		public get cause(): Error {
			return this._getOption("cause");
		}

		/**
		 * "submit-error" 이벤트의 원인 메시지.
		 * "submit-error" 이벤트의 발생 원인에 대한 내용을 리턴합니다.
		 */
		public get message(): string {
			return this._getOption("message");
		}

		/**
		 * 이벤트 객체를 통해 전달되는 객체.
		 */
		get content(): any {
			return this._getOption("content");
		}

		/**
		 * 업로드 또는 다운로드 된 콘텐츠의 크기.
		 * submit-progress 또는 submit-upload-progress 유형의 서브미션 이벤트 인 경우에만 제공됩니다.
		 * 서버가 크기 정보를 제공하지 않는 경우 -1이 리턴됩니다.
		 */
		public get loaded(): number {
			let nEvent: Event = this.nativeEvent;
			if (nEvent && nEvent instanceof ProgressEvent) {
				return (nEvent as ProgressEvent).loaded;
			} else {
				let loaded: number = this._getOption("loaded");
				if (loaded != null && typeof loaded == "number") {
					return loaded;
				}
			}
			return -1;
		}

		/**
		 * 업로드 또는 다운로드해야 할 총 콘텐츠의 크기.
		 * submit-progress 또는 submit-upload-progress 유형의 서브미션 이벤트 인 경우에만 제공됩니다.
		 * 서버가 크기 정보를 제공하지 않는 경우 -1이 리턴됩니다.
		 */
		public get total(): number {
			let nEvent: Event = this.nativeEvent;
			if (nEvent && nEvent instanceof ProgressEvent) {
				return (nEvent as ProgressEvent).total;
			} else {
				let total: number = this._getOption("total");
				if (total != null && typeof total == "number") {
					return total;
				}
			}
			return -1;
		}

	}

}