/// <reference path="../controls/Control.ts"/>

namespace cpr.protocols {
	/**
	 * 서브미션의 통신 상태.
	 */
	export enum SubmissionProcess {
		/**
		 * 서브미션이 대기 중인 상태.
		 */
		IDLE,
		/**
		 * 서브미션을 전송하는 상태.
		 */
		SENDING,
		/**
		 * 서브미션 전송이 완료된 상태.
		 */
		DONE
	}

	/**
	 * response 유형.
	 */
	export enum ResponseType {
		/**
		 * 일반적인 길이가 정해진 데이터의 buffer.
		 */
		arraybuffer,
		/**
		 * 이미지나 사운드 파일과 같은 raw data.
		 */
		blob,
		/**
		 * &lt;body&gt;, &lt;table&gt; 같은 웹페이지를 load 할 수 있는 Dom tree.
		 */
		document,
		/**
		 * json 객체(javascript object).
		 */
		json,
		/**
		 * String, DomString.
		 */
		text,
		/**
		 * 서버에서 받을 수 있는 파일.
		 */
		filedownload,
		/**
		 * 서버에서 받아 실행할 스크립트.
		 */
		javascript
		// text/tab-separated-values
	}

	/**
	 * DataSet 요청 데이터 필터 조건 설정값.
	 * 변경된 데이터만 전송할지 전체 데이터를 전송할지를 결정한다.
	 */
	export enum PayloadType {
		/** 변경된 데이터만 전송(기본값) */
		modified,
		/** 전체 데이터를 전송 */
		all
	}

	/**
	 * 서브미션을 통해 서버로 전달할 정보를 담고 있는 객체입니다.
	 */
	export interface RequestData {
		/**
		 * 서브미션을 통해 전달할 Data 컴포넌트 객체입니다.
		 */
		data: data.DataSet | data.DataMap,
		/**
		 * 서버로 전달할 데이터를 매핑할 별칭입니다.
		 */
		alias: string,
		/**
		 * data 객체가 DataSet인 경우 서버로 전송할 데이터의 상태가 정의됩니다.
		 * @see PayloadType
		 */
		payload: PayloadType
		// autocud?: {}
	}

	/**
	 * 서브미션을 통해 서버로 부터 전달받은 데이터로 갱신할 Data 컴포넌트의 정보를 담고 있는 객체입니다.
	 */
	export interface ResponseData {
		/**
		 * 서브미션을 통해 갱신 할 Data 컴포넌트 객체입니다.
		 */
		data: data.DataSet | data.DataMap | any,
		/**
		 * 기존 데이터를 유지한 상태로 추가할지 기존 데이터를 전달받은 데이터로 교체할지 여부를 결정합니다.
		 */
		isadd: boolean,
		/**
		 * 서버로 부터 전달받은 데이터를 매핑할 별칭입니다.
		 */
		alias: string
	}

	export interface RequestEncoderSpec {
		encoder: RequestEncoder,
		usingBuildData: boolean
	}

	export abstract class AbstractSubmission extends controls.Control {
		/**
		 * @private
		 */
		public static readonly _METHOD_POST: string = "post";
		/**
		 * @private
		 */
		public static readonly _METHOD_GET: string = "get";
		/**
		 * @private
		 */
		public static readonly _METHOD_DELETE: string = "delete";
		/**
		 * @private
		 */
		public static readonly _METHOD_HEAD: string = "head";
		/**
		 * @private
		 */
		public static readonly _METHOD_OPTIONS: string = "options";
		/**
		 * @private
		 */
		public static readonly _METHOD_PATCH: string = "patch";
		/**
		 * @private
		 */
		public static readonly _METHOD_PUT: string = "put";
		/**
		 * @private
		 */
		public static readonly _MEDIA_URLENCODED: string = "application/x-www-form-urlencoded";
		/**
		 * @private
		 */
		public static readonly _MEDIA_URLENCODED_SIMPLE: string = "application/x-www-form-urlencoded;simple";
		/**
		 * @private
		 */
		public static readonly _MEDIA_URLENCODED_MASS: string = "application/x-www-form-urlencoded;massdata";
		/**
		 * @private
		 */
		public static readonly _MEDIA_JSON: string = "application/json";
		/**
		 * @private
		 */
		public static readonly _MEDIA_JSON_MASS: string = "application/json;massdata";
		/**
		 * @private
		 */
		public static readonly _MEDIA_SCRIPT: string = "application/javascript";
		/**
		 * @private
		 */
		public static readonly _MEDIA_MULTIPART_JSON: string = "multipart/form-data;encoding=json";
		/**
		 * @private
		 */
		public static readonly _MEDIA_MULTIPART: string = "multipart/form-data";
		/**
		 * @private
		 */
		public static readonly _MEDIA_MULTIPART_SIMPLE: string = "multipart/form-data;simple";
		/**
		 * @private
		 */
		public static readonly _MEDIA_TSV: string = "text/tab-separated-values"; // http://www.rfc-editor.org/rfc/rfc4180.txt

		private static readonly _HTTPMETHOD: string[] = [
			AbstractSubmission._METHOD_POST,
			AbstractSubmission._METHOD_GET,
			AbstractSubmission._METHOD_DELETE,
			AbstractSubmission._METHOD_HEAD,
			AbstractSubmission._METHOD_OPTIONS,
			AbstractSubmission._METHOD_PATCH,
			AbstractSubmission._METHOD_PUT
		];
		private static readonly _MEDIATYPE: string[] = [
			AbstractSubmission._MEDIA_URLENCODED,
			AbstractSubmission._MEDIA_URLENCODED_MASS,
			AbstractSubmission._MEDIA_URLENCODED_SIMPLE,
			AbstractSubmission._MEDIA_JSON,
			AbstractSubmission._MEDIA_JSON_MASS,
			AbstractSubmission._MEDIA_MULTIPART_JSON,
			AbstractSubmission._MEDIA_MULTIPART,
			AbstractSubmission._MEDIA_MULTIPART_SIMPLE
		];

		private static readonly _AVAILABLE_PROP: string[] = [
			"contextPath", "action", "async", "withCredentials", "method", "mediaType", "responseType", "timeout"
		];


		// private _action: string = null;
		/**
		 * get method 처리를 위한 instant url
		 */
		private _reqActUrl: string = null;
		private _async: boolean = true;
		private _withCredentials: boolean = false;
		// private _method: string = AbstractSubmission._METHOD_POST;
		private _mediatype: string = AbstractSubmission._MEDIA_URLENCODED;
		private _encoding: string = "utf-8";
		private _timeout: number = 0;
		private _success: boolean = true;
		private _error: any = null;
		private _errorEvent: events.CSubmissionEvent = null;

		protected _responseType: ResponseType = ResponseType.text;
		protected _status: SubmissionProcess = SubmissionProcess.IDLE;
		protected _xhr: XMLHttpRequest;
		private _ctx: {} = null;

		private _headers: {};

		protected _promiseSupport: PromiseSupport;
		protected _protocolDataModel: ProtocolDataModel;

		// private _requestEncoder: RequestEncoder;
		private _requestEncoder: RequestEncoderSpec;
		private _responseDecoder: ResponseDecoder;

		// DataSet Row를 이용하여 추가적인 요청데이터를 생성하기 위한 Handler
		private _dataRowHandler: (rowdata: RowUnit) => { [key: string]: string } = null;
		private _isHandleDataMap: boolean = false;

		private _instantContentType: string = null; // RequestEncoder에 의해 인코딩된 결과 데이터의 ContentType을 임의로 지정할 수 있도록 지원(xml 프로토콜 지원)


		constructor(id?: string) {
			super(id);
			this._headers = {};
			this._promiseSupport = new PromiseSupport(this);

			this._addBindableProperty("contextPath", "").withSetterValidatorWithType(false, "string");
			this._addBindableProperty("action", "").withSetterValidatorWithType(false, "string");
			this._addBindableProperty("method", AbstractSubmission._METHOD_POST).withSetterValidatorWithType(false, "string");
		}

		protected _getDefaultConfiguration(): core.Config {
			return core.AppConfig.INSTANCE.getProtocolConfig(this._getType());
		}

		protected _isConfigurableProperty(propName: string): boolean {
			if (AbstractSubmission._AVAILABLE_PROP.indexOf(propName) != -1) {
				return true;
			}
			return super._isConfigurableProperty(propName);
		}

		// property start
		/**
		 * 별도로 설정된 서버 URL 중 ContextPath를 리턴합니다.
		 * @return ContextPath.
		 */
		public get contextPath(): string {
			return this._bindables.get("contextPath");
		}

		/**
		 * 설정된 서버 URL 중 ContextPath를 설정합니다.
		 * @param contextPath ContextPath.
		 */
		public set contextPath(contextPath: string) {
			this._bindables.set("contextPath", contextPath);
		}

		/**
		 * Data를 전송할 url을 반환합니다.
		 * @return 전송할 url.
		 */
		public get action(): string {
			// return this._action;
			return this._bindables.get("action");
		}

		/**
		 * Data를 전송할 url을 지정합니다. ex) "/action_data.do"
		 * @param action 전송할 url.
		 */
		public set action(action: string) {
			// this._action = action;
			this._bindables.set("action", action);
		}

		/**
		 * 서브미션 요청이 완료될 때 마다 초기화되는 서버로 요청할 전체 URL 정보를 반환합니다.
		 * 결과 값이 null인 경우 Submission이 send될 때 환경변수(default.js의 protocol.submission)에 설정된 contextPath 값과
		 * Submission에 설정된 action 값이 합쳐진 URL로 자동설정됩니다.
		 * @see #setRequestActionUrl
		 * @return 서버로 전송할 전체 URL.
		 */
		public getRequestActionUrl(): string {
			return this._reqActUrl;
		}
		/**
		 * 서브미션 요청이 완료될 때 마다 초기화되는 서버로 요청할 전체 URL 정보를 설정합니다.
		 * 설정 값이 null인 경우 Submission이 send될 때 환경변수(default.js의 protocol.submission)에 설정된 contextPath 값과
		 * Submission에 설정된 action 값이 합쳐진 URL로 자동설정됩니다.
		 * 설정 값이 null이 아닌 경우 Submission이 send될 때 설정된 URL을 이용하여 서버와 통신합니다.
		 * 설정된 URL은 서브미션 요청이 완료될 때 마다 null로 초기화됩니다.
		 * <pre><code>
		 * var submission = app.lookup("sub_main");
		 * submission.setRequestActionUrl("http://test.exbuilder.co.kr/" + submission.action);
		 * submission.send();
		 * </code></pre>
		 * @see #getRequestActionUrl
		 * @see #action
		 * @param action 서버로 요청할 전체 URL.
		 */
		public setRequestActionUrl(action: string): void {
			this._reqActUrl = action;
		}

		/**
		 * 비동기 여부의 값을 반환합니다.
		 * @return 비동기 여부.
		 */
		public get async(): boolean {
			return this._async;
		}

		/**
		 * 비동기 여부의 값을 지정합니다.
		 * @param async 비동기 여부.
		 */
		public set async(async: boolean) {
			this._async = async;
		}

		/**
		 * Cross Domain 요청시 자격증명 정보의 전송 여부를 반환합니다.
		 * @return Cross Domain 요청시 자격증명 정보의 전송 여부.
		 */
		public get withCredentials(): boolean {
			return this._withCredentials;
		}

		/**
		 * Cross Domain 요청시 자격증명 정보의 전송 여부를 지정합니다.
		 * @param withCredentials Cross Domain 요청시 자격증명 정보의 전송 여부.
		 */
		public set withCredentials(withCredentials: boolean) {
			this._withCredentials = withCredentials;
		}

		/**
		 * 지정된 http request method의 값을 반환합니다.
		 * @return request method.
		 */
		public get method(): string {
			// return this._method;
			return this._bindables.get("method");
		}

		/**
		 * http request method의 값을 지정합니다.
		 * @param method request method.
		 */
		public set method(method: string) {
			method = method.toLowerCase();
			if (AbstractSubmission._HTTPMETHOD.indexOf(method) == -1) {
				return;
			}
			// this._method = method;
			this._bindables.set("method", method);
		}

		/**
		 * http에 content-type의 media-type의 값을 반환합니다.
		 * @return media-type.
		 */
		public get mediaType(): string {
			return this._getMediaType();
		}

		public _getMediaType(): string {
			return this._mediatype;
		}

		/**
		 * http에 content-type의 media-type의 값을 지정합니다.
		 * @param mediatype media-type.
		 */
		public set mediaType(mediatype: string) {
			this._setMediaType(mediatype);
		}

		public _setMediaType(mediatype: string) {
			mediatype = mediatype.toLowerCase();
			if (AbstractSubmission._MEDIATYPE.indexOf(mediatype) == -1) {
				return;
			}
			this._mediatype = mediatype;
		}

		/**
		 * http에 content-type의 문자 인코딩 값을 반환합니다.
		 * @return 문자 인코딩 값.
		 */
		public get encoding(): string {
			return this._encoding;
		}

		/**
		 * 서브미션의 통신 상태 값을 반환합니다.
		 * 서브미션은 세 가지의 상태(IDLE, SENDING, DONE)를 가질 수 있습니다.
		 * @return 통신 상태 값.
		 */
		public get status(): string {
			return SubmissionProcess[this._status];
		}

		/**
		 * 서브미션에 지정된 response data type을 반환합니다.
		 * @return response data type.
		 */
		public get responseType(): string {
			return this._getResponseType();
		}

		public _getResponseType(): string {
			return ResponseType[this._responseType];
		}

		/**
		 * 서브미션에 지정된 response data type을 지정합니다.
		 * @param responsetype response data type.
		 */
		public set responseType(responsetype: string) {
			this._setResponseType(responsetype);
		}

		public _setResponseType(responsetype: string) {
			if (typeof responsetype === "number") {
				if (cpr.protocols.ResponseType[responsetype]) {
					this._responseType = responsetype;
					return;
				}
			} else if (typeof responsetype === "string") {
				if (cpr.protocols.ResponseType.hasOwnProperty(responsetype)) {
					this._responseType = ResponseType[responsetype];
				}
				return;
			}
			throw new exceptions.IllegalArgumentException("Unsupported responseType : " + responsetype);
		}

		/**
		 * HTTPRequest로 전송할 데이터를 DataSet의 Row별로 가공할 수 있는 Handler를 등록합니다.
		 * <pre><code>
		 * submission.setDataRowHandler(function(rowdata) {
		 *   var additionalData = {};
		 *   var columnValue = rowdata.getValue("columnName");
		 *   additionalData['param'] = columnValue;
		 * return additionalData;
		 * });
		 * </code></pre>
		 * @param dataRowHandler DataSet의 개별 Row의 Handler.
		 */
		protected _setDataRowHandler(dataRowHandler: (rowdata: RowUnit) => { [key: string]: string }, handleDataMap: boolean = false): void {
			this._dataRowHandler = dataRowHandler;
			this._isHandleDataMap = handleDataMap;
		}

		/**
		 * @private
		 * @param rowData
		 */
		public _handleDataRow(dataColl: data.DataSet, rowData: data.tabledata.RowData, colNmMap: { [key: string]: number }): { [key: string]: string } {
			if (this._dataRowHandler) {
				return this._dataRowHandler(new DataSetRow(dataColl, rowData, colNmMap));
			}
			return null;
		}

		public _handleDataMap(dataMap: data.DataMap): { [key: string]: string } {
			if (this._dataRowHandler && this._isHandleDataMap === true) {
				return this._dataRowHandler(new DataMapRow(dataMap));
			}
			return null;
		}

		/**
		 * 통신에 사용되는 XMLHttpRequest 객체를 반환합니다.
		 * @return XMLHttpRequest.
		 */
		public get xhr(): XMLHttpRequest {
			return this._xhr;
		}

		/**
		 * 지정된 시간을 초과하면 중단되며 timeout이벤트가 발생합니다. 입력되는 값은 ms(Millisecond)로 받습니다.
		 * @param timeout timeout 이벤트가 발생할 ms(Millisecond) 기준의 시간.
		 */
		public set timeout(timeout: number) {
			this._timeout = timeout;
		}

		/**
		 * 서브미션의 timeout 값을 반환합니다.
		 * @return timeout 이벤트가 발생할 시간.
		 */
		public get timeout(): number {
			return this._timeout;
		}
		// property end

		/**
		 * 통신을 중단합니다.
		 */
		public abort(): void {
			if (this._status == SubmissionProcess.SENDING) {
				this.xhr.abort();
				this._done();
			}
		}

		/**
		 * request header의 값을 지정합니다.
		 * @param name 헤더의 이름
		 * @param value 헤더의 값
		 */
		public setHeader(name: string, value: string): void {
			if (name == null) {
				throw new cpr.exceptions.IllegalArgumentException("header name");
			}
			value = (value == null ? "" : value);

			name = name.toLowerCase();
			this._headers[name] = value;
		}

		/**
		 * request header의 값을 반환합니다.
		 * @param name 헤더의 이름.
		 * @return header의 값.
		 */
		public getHeader(name: string): string {
			if (name == null) {
				return null;
			}
			name = name.toLowerCase();
			return this._headers[name];
		}

		/**
		 * 지정된 request header들의 이름들을 반환합니다.
		 * @return header 명의 배열.
		 */
		public getHeaderNames(): string[] {
			let names: string[] = [];
			for (let name in this._headers) {
				names.push(name);
			}
			return names;
		}
		/**
		 * 지정한 이름의 헤더를 제거합니다.
		 * @param name 헤더의 이름
		 * @return 제거한 헤더의 값.
		 */
		public removeHeader(name: string): string {
			if (name == null) {
				return null;
			}
			name = name.toLowerCase();
			let headerValue: string = this._headers[name];
			delete this._headers[name];
			return headerValue;
		}

		/**
		 * 지정된 헤더를 전부 제거합니다.
		 */
		public removeAllHeader(): void {
			this._headers = {};
		}

		/**
		 * 서브미션의 성공여부를 반환합니다.
		 * @return 성공 : true, 실패 : false
		 */
		public isSuccess(): boolean {
			return this._success;
		}

		protected _setSuccess(success: boolean, error: any): void {
			this._success = success;
			this._error = error;
		}

		/**
		 * 서버로 전송하는 데이터를 별도의 형식으로 Encoding할 수 있는 함수를 등록합니다.
		 * @param requestEncoder (submission:cpr.protocols.Submission, data:{}|string) => Promise<{key:string, content:{}|string}> | {key:string, content:{}|string} 형식의 callback handler
		 * @param usingBuildData RequestEncoder 동작을 위해 빌드된 요청데이터가 필요한지 여부.
		 */
		public setRequestEncoder(requestEncoder: RequestEncoder, usingBuildData: boolean = true): void {
			this._requestEncoder = {
				encoder: requestEncoder,
				usingBuildData: usingBuildData
			};
		}
		public _getRequestEncoder(): RequestEncoderSpec {
			return this._requestEncoder;
		}

		public _setInstantContentType(instantContentType: string): void {
			this._instantContentType = instantContentType;
		}

		/**
		 * 서버로 부터 전송받은 eXBuilder6에서 지원하지 않는 형식의 데이터를 eXBuilder6에서 지원하는 형식으로 변환하거나 자체적으로 처리할 수 있는 Decoding 함수를 등록합니다.
		 * ResponseDecoder가 등록된 Submission은 "submit-load-progress" 이벤트를 발생시키지 않습니다.
		 * @param responseDecoder (submission:cpr.protocols.Submission, data:string) => Promise<{contentType:string, content:{}|string}> | {contentType:string, content:{}|string} 형식의 callback handler
		 */
		public setResponseDecoder(responseDecoder: ResponseDecoder): void {
			this._responseDecoder = responseDecoder;
		}
		public _getResponseDecoder(): ResponseDecoder {
			return this._responseDecoder;
		}

		/**
		 * @private
		 * Submission의 처리상태를 리턴한다.
		 */
		public _getContext(): {} {
			return this._ctx;
		}
		/**
		 * @private
		 * Submission의 처리상태를 보전한다.
		 */
		public _setContext(ctx: {}) {
			this._ctx = ctx;
		}

		public _getProtocolDataModel(): ProtocolDataModel {
			return this._protocolDataModel;
		}

		/**
		 * 데이터를 전송합니다. 이미 동일한 서브미션으로 전송 중인 경우 실행되지 않습니다.
		 */
		public send(): Promise<events.CSubmissionEvent> {
			return new Promise<events.CSubmissionEvent>(this._promiseSupport._getPromiseCallback());
		}

		/**
		 * 데이터를 전송합니다. 이미 동일한 서브미션으로 전송 중인 경우 실행되지 않습니다.
		 * @private
		 */
		public _doSend(): void {
			if (this._status !== SubmissionProcess.IDLE) {
				// Error Log
				throw new exceptions.IllegalStateException("Submission Already Sended");
			}
			// dispatch submission before event
			let submissionEvent: events.CSubmissionEvent = this._createSubmitEvent(events.SubmissionEventType.BEFORE);
			let continous: boolean = this.dispatchEvent(submissionEvent);
			if (continous == false) {
				return;
			}
			if (!this.action) {
				throw new exceptions.CError("a action property must be specified");
			}
			if (!this.getRequestActionUrl()) {
				if (/^[a-z0-9]/i.test(this.action) == true && /^http/i.test(this.action) == false && this.contextPath) {
					this.setRequestActionUrl(this.contextPath + this.action);
				} else {
					this.setRequestActionUrl(this.action);
				}
			}

			this._clearSubmissionStatusData();

			let requestBuilder: RequestBuilder = this._protocolDataModel.getRequestBuilder(this);
			let requestData: any = requestBuilder.build(this);
			if (requestData && requestData instanceof Promise) {
				let requestBuildPromise: Promise<any> = requestData as Promise<any>;
				requestBuildPromise.then((encodedData: any) => {
					this._sendRequest(requestBuilder, encodedData);
				}).catch((ev: Error) => {
					this._onError(ev);
				});
			} else {
				try {
					this._sendRequest(requestBuilder, requestData);
				} catch (err) {
					this._onError(err);
				}
			}
		}

		private _sendRequest(requestBuilder: RequestBuilder, requestData: any): void {
			this._status = SubmissionProcess.SENDING;

			/* filedownload 처리 */
			if (this._responseType == ResponseType.filedownload) {
				let formElement: HTMLFormElement = requestData as HTMLFormElement;
				formElement.submit();

				// clear
				formElement.reset();
				let parentElement: HTMLElement = formElement.parentElement;
				parentElement.removeChild(formElement);
				formElement = null;

				// submit done
				this._done();

				return;
			}

			let xhr: XMLHttpRequest = this._createXMLHttpRequest();
			xhr.open(this.method.toUpperCase(), this.getRequestActionUrl(), this.async);
			// synchronous 일때는 timeout은 에러(InvalidAccessError) 발생(IE는 TimeoutError를 발생시키나 Chrome은 설정이 허용되지 않음)
			// : https://xhr.spec.whatwg.org/#the-timeout-attribute
			if (this.timeout > 0 && this.async === true) {
				xhr.timeout = this.timeout;
				xhr.ontimeout = this._onTimeout.bind(this);
			}

			// Note: Starting with Gecko 11.0 (Firefox 11.0 / Thunderbird 11.0 / SeaMonkey 2.8), as well as WebKit build 528, 
			// these browsers no longer let you use the responseType attribute when performing synchronous requests.
			// Attempting to do so throws an NS_ERROR_DOM_INVALID_ACCESS_ERR exception.
			// This change has been proposed to the W3C for standardization.
			if (this.async == true) {
				switch (this._responseType) {
					case ResponseType.text:
						{
							break;
						}
					case ResponseType.arraybuffer:
						{
							xhr.responseType = "blob";
							break;
						}
					case ResponseType.blob:
						{
							xhr.responseType = "blob";
							break;
						}
					case ResponseType.document:
						{
							break;
						}
					case ResponseType.json:
						{
							break;
						}
					default:
						{
						}
				}
			}

			//header
			xhr.setRequestHeader("X-Requested-With", "XMLHttpRequest");
			let headerNames: string[] = this.getHeaderNames();
			for (let idx: number = 0; idx < headerNames.length; idx++) {
				let headerName: string = headerNames[idx];
				let headerValue: string = this.getHeader(headerName);
				// HTTP 응답분할(Improper Neutralization of CRLF Sequence in HTTP Headers, HTTP Request Splitting) 방지
				if (headerValue) {
					headerValue = headerValue.replace(/[\n\r]/g, " ");
				}
				xhr.setRequestHeader(headerName, headerValue);
			}

			let contentType: string = null;
			if (this._instantContentType) {
				contentType = this._instantContentType;
				this._instantContentType = null;
			} else {
				contentType = requestBuilder.getContentType();
			}
			if (contentType) {
				xhr.setRequestHeader("Content-Type", contentType + "; charset=" + this.encoding);
			}

			if (xhr["upload"]) {
				if (xhr.upload["addEventListener"]) {
					xhr.upload.addEventListener("progress", this._onUploadProgress.bind(this));
				}
			}

			xhr.onprogress = this._onProgress.bind(this);

			// [우정 : 20171027] TODO exception handle(abort & done) on network error
			xhr.onerror = this._onProgressError.bind(this);

			// withCredentials
			if (this._withCredentials == true) {
				xhr.withCredentials = this._withCredentials;
			}

			this._xhr = xhr;

			let submissionEvent: events.CSubmissionEvent = this._createSubmitEvent(events.SubmissionEventType.BEFORE_SEND);
			try {
				this.dispatchEvent(submissionEvent);
			} catch (e) {
				this._onError(e);
				return;
			}

			if (this.async == true) {
				if (this._getResponseDecoder()) {
					xhr.onreadystatechange = this._responseDecoderCallback.bind(this);
				} else {
					xhr.onreadystatechange = this._responseCallback.bind(this);
				}

				xhr.send(requestData);
			} else {
				xhr.send(requestData);

				if (this._getResponseDecoder()) {
					this._responseDecoderCallback();
				} else {
					this._responseCallback();
				}
			}
		}

		/**
		 * 객체에 담긴 정보를 파기하고, 객체도 삭제합니다.
		 */
		public dispose(): void {
			if (this._status == SubmissionProcess.SENDING) {
				if (this._xhr) {
					utils.tryCatch({
						do: () => {
							this._xhr.abort();
						}
					});
				}
				this._setSuccess(false, new exceptions.CancelationException("Submission is disposed"));
				this._done();
			}
			this._ctx = null;
			this._error = null;

			this._removeXMLHttpRequest();
			super.dispose();
		}

		/* helper methods */
		private _responseParser: ResponseParser;
		private _responseCallback(): void {
			if (!this._xhr || this.disposed) {
				return;
			}
			let state: number = this._xhr.readyState;
			switch (state) {
				case XMLHttpRequest.UNSENT: // unsent
				case XMLHttpRequest.OPENED: { // opened
					return;
				}
				case XMLHttpRequest.HEADERS_RECEIVED: {
					let status: number = this._xhr.status;
					// [우정 : 20171027]
					if (status == 200) {
						// success
						this._responseParser = this._getResponseParser();
					} else {
						// fail
						let statusText: string = this._xhr.statusText;
						let submissionEvent: events.CSubmissionEvent = this._createSubmitEvent(events.SubmissionEventType.ERROR_STATUS, { cause: status, message: statusText });
						let processContinue: boolean = this.dispatchEvent(submissionEvent);
						if (processContinue) {
							this._onError(new exceptions.IllegalStateException("status code " + status));
						}
					}
					return;
				}
				case XMLHttpRequest.LOADING: {
					try {
						if (this._responseParser) {
							this._responseParser.load(this, this._xhr);
						}
					} catch (err) {
						// fail
						this._onError(err);
					}
					return;
				}
				case XMLHttpRequest.DONE: {
					// [우정 : 20171027]
					this._status = SubmissionProcess.DONE;
					let status: number = this._xhr.status;
					let statusText: string = this._xhr.statusText;
					if (status >= 100) {
						let processContinue: boolean = true;

						try {
							let receiveEvent: events.CSubmissionEvent = this._createSubmitEvent(events.SubmissionEventType.RECEIVE);
							processContinue = this.dispatchEvent(receiveEvent);
						} catch (err) {
							// fail
							this._onError(err);
							return;
						}

						if (processContinue == true) {
							if (!this._responseParser) {
								this._responseParser = this._getResponseParser();
							}
							let doneHandler = () => {
								try {
									let submissionEvent: events.CSubmissionEvent = null;
									if (status >= 200 && status < 400 && this.isSuccess() == true) {
										// success
										submissionEvent = this._createSubmitEvent(events.SubmissionEventType.SUCCESS);
									} else {
										// fail
										submissionEvent = this._createSubmitEvent(events.SubmissionEventType.ERROR, { cause: status, message: statusText });
										this._errorEvent = submissionEvent;
									}

									this.dispatchEvent(submissionEvent);
								} finally {
									this._done();
								}
							}
							if (this._responseParser) {
								this._responseParser.parse(this, this._xhr, doneHandler);
							} else {
								doneHandler();
							}
						} else {
							if (this._responseParser) {
								this._responseParser._abortLoading(this);
							}

							this._done();
						}
					}
				}
			}
		}

		private _responseDecoderCallback(): void {
			if (!this._xhr || this.disposed) {
				return;
			}
			let state: number = this._xhr.readyState;
			switch (state) {
				case XMLHttpRequest.UNSENT: // unsent
				case XMLHttpRequest.OPENED: { // opened
					return;
				}
				case XMLHttpRequest.HEADERS_RECEIVED: {
					let status: number = this._xhr.status;
					if (status !== 200) {
						// fail
						let statusText: string = this._xhr.statusText;
						let submissionEvent: events.CSubmissionEvent = this._createSubmitEvent(events.SubmissionEventType.ERROR_STATUS, { cause: status, message: statusText });
						let processContinue: boolean = this.dispatchEvent(submissionEvent);
						if (processContinue) {
							this._onError(new exceptions.IllegalStateException("status code " + status));
						}
					}
					return;
				}
				case XMLHttpRequest.LOADING: {
					return;
				}
				case XMLHttpRequest.DONE: {
					this._status = SubmissionProcess.DONE;
					let status: number = this._xhr.status;
					if (status >= 100) {
						let processContinue: boolean = true;

						try {
							let receiveEvent: events.CSubmissionEvent = this._createSubmitEvent(events.SubmissionEventType.RECEIVE);
							processContinue = this.dispatchEvent(receiveEvent);
						} catch (err) {
							// fail
							this._onError(err);
							return;
						}

						if (processContinue == true) {
							let statusText: string = this._xhr.statusText;
							let doneHandler = () => {
								try {
									let submissionEvent: events.CSubmissionEvent = null;
									if (status >= 200 && status < 400 && this.isSuccess() == true) {
										// success
										submissionEvent = this._createSubmitEvent(events.SubmissionEventType.SUCCESS);
									} else {
										// fail
										submissionEvent = this._createSubmitEvent(events.SubmissionEventType.ERROR, { cause: status, message: statusText });
									}

									this.dispatchEvent(submissionEvent);
								} finally {
									this._done();
								}
							}

							// 파일다운로드는 개별 처리
							let isFileDownload: boolean = response.DefaultResponseParserFactory.INSTANCE._isFileDownloadResponse(this._xhr);
							if (isFileDownload) {
								let responseParser: ResponseParser = this._getResponseParser();
								responseParser.parse(this, this._xhr, doneHandler);
								return;
							}

							let responseDecoder: ResponseDecoder = this._getResponseDecoder();
							let responseParser: ResponseParser = new response.ResponseDecoderParser(responseDecoder);
							responseParser.parse(this, this._xhr, doneHandler);
						} else {
							this._done();
						}
					}
				}
			}
		}

		protected abstract _getResponseParser(): ResponseParser;

		private _clearSubmissionStatusData(): void {
			this._error = null;
			this._errorEvent = null;
			this._clearSubmissionStatus();
		}
		protected abstract _clearSubmissionStatus(): void;
		protected abstract clearAllInstantParameters(): void;

		private _done(): void {
			// submission done evnet
			try {
				this._status = SubmissionProcess.DONE;
				let submissionEvent: events.CSubmissionEvent = this._createSubmitEvent(events.SubmissionEventType.DONE);
				this.dispatchEvent(submissionEvent);
			} finally {
				this.setRequestActionUrl(null);
				this._setContext(null);
				this._status = SubmissionProcess.IDLE;

				if (this._promiseSupport._isKeptSend()) {
					this._promiseSupport._process();
				} else {
					this._removeXMLHttpRequest();
					this.clearAllInstantParameters();
				}
			}
		}

		private _onUploadProgress(e: ProgressEvent): void {
			let submissionEvent: events.CSubmissionEvent = this._createSubmitEvent(events.SubmissionEventType.UPLOAD_PROGRESS);
			submissionEvent.nativeEvent = e;
			this.dispatchEvent(submissionEvent);
		}

		private _onProgress(e: ProgressEvent): void {
			// load된 데이터가 있을 경우에만 이벤트를 발생시킴
			if (e && e.loaded > 0) {
				let submissionEvent: events.CSubmissionEvent = this._createSubmitEvent(events.SubmissionEventType.PROGRESS);
				submissionEvent.nativeEvent = e;
				this.dispatchEvent(submissionEvent);
			}
		}

		_onLoadProgress(total: number, loaded: number): void {
			let submissionEvent: events.CSubmissionEvent = this._createSubmitEvent(events.SubmissionEventType.LOAD_PROGRESS,
				{ "total": total, "loaded": loaded });
			this.dispatchEvent(submissionEvent);
		}

		_onProgressError(e: ProgressEvent): void {
			this._setSuccess(false, e);
			try {
				let submissionEvent: events.CSubmissionEvent = this._createSubmitEvent(events.SubmissionEventType.ERROR, { cause: e, message: "The fetch failed" });
				submissionEvent.nativeEvent = e;
				this._errorEvent = submissionEvent;

				this.dispatchEvent(submissionEvent);
			} finally {
				this._done();
				core.Platform.INSTANCE._reportError(exceptions.ErrorContext.SUBMISSION, e);
			}
		}

		_onError(err: Error): void {
			this._setSuccess(false, err);
			// logging
			if (err) {
				utils.logError(err);
			}
			try {
				let submissionEvent: events.CSubmissionEvent = this._createSubmitEvent(events.SubmissionEventType.ERROR, { cause: err, message: err.message });
				this._errorEvent = submissionEvent;

				this.dispatchEvent(submissionEvent);
			} finally {
				this._done();
			}
		}

		_getLastError(): any {
			return this._error;
		}
		_getLastErrorEvent(): events.CSubmissionEvent {
			return this._errorEvent;
		}

		private _onTimeout(e: ProgressEvent): void {
			this._setSuccess(false, e);
			try {
				let submissionEvent: events.CSubmissionEvent = this._createSubmitEvent(events.SubmissionEventType.TIMEOUT);
				submissionEvent.nativeEvent = e;
				this._errorEvent = submissionEvent;

				this.dispatchEvent(submissionEvent);
			} finally {
				this._done();
			}
		}

		_createSubmitEvent(type: string, options: {} = {}): events.CSubmissionEvent {
			let submissionEvent: events.CSubmissionEvent = new events.CSubmissionEvent(type, options);
			submissionEvent._prepareWithTarget(this);

			return submissionEvent;
		}

		/**
		 * XMLHttpRequest를 생성하여 반환합니다.
		 */
		private _createXMLHttpRequest(): XMLHttpRequest {
			if (this._xhr) {
				return this._xhr;
			}
			let req: XMLHttpRequest = null;
			if (XMLHttpRequest) {//모질라, 사파리, Edge 등 그외 브라우저, ...
				req = new XMLHttpRequest();
			} else if (ActiveXObject) { //IE8 이상
				try {
					req = new ActiveXObject("Msxml2.XMLHTTP");
				}
				catch (e) {
					try {
						req = new ActiveXObject("Microsoft.XMLHTTP");
					}
					catch (e) {
						throw new Error(`Could not create XMLHttpReqeust object.`);
					}
				}
			}
			return req;
		}

		private _removeXMLHttpRequest(): void {
			this._xhr = null;
		}

	}

	/**
	 * @private
	 */
	export class PromiseSupport {

		private _submission: AbstractSubmission;
		private _resolve: (value?: events.CSubmissionEvent) => void;
		private _reject: (error?: any) => void;
		private _keptSend: boolean;
		private _promiseCallback = (resolve: (value?: events.CSubmissionEvent) => void, reject: (error?: any) => void) => this._callback(resolve, reject);


		constructor(submission: AbstractSubmission) {
			this._submission = submission;
			this._keptSend = false;
		}

		public _getPromiseCallback(): (resolve: (value?: events.CSubmissionEvent) => void, reject: (error?: any) => void) => void {
			return this._promiseCallback;
		}

		private _callback(resolve: (value?: events.CSubmissionEvent) => void, reject: (error?: any) => void): void {
			this._keptSend = true;
			this._resolve = resolve;
			this._reject = reject;
			if (this._submission.status != SubmissionProcess[SubmissionProcess.DONE]) { // <-- FIXME: 이게 머하는 짓인지 체크
				this._process();
			}
		}

		public _isKeptSend(): boolean {
			return this._keptSend;
		}

		public _process(): void {
			if (this._keptSend == false) {
				return;
			}
			this._keptSend = false;
			let supportInstance: PromiseSupport = this;
			this._submission.addEventListenerOnce("submit-done", (e: events.CSubmissionEvent) => {
				if (this._submission.isSuccess()) {
					utils.tryCatch({
						do() {
							supportInstance._resolve(e);
						},
						catch(err) {
							supportInstance._reject(err);
						},
						_report: true,
						_context: exceptions.ErrorContext.PROMISE
					});
				} else {
					let lastError: any = this._submission._getLastError();
					if (lastError && lastError instanceof exceptions.CancelationException) {
						this._reject(lastError);
					} else {
						let errorEvent: events.CSubmissionEvent = this._submission._getLastErrorEvent();
						if (errorEvent) {
							if (errorEvent.defaultPrevented) {
								return;
							}
						} else {
							errorEvent = new events.CSubmissionEvent(events.SubmissionEventType.ERROR, { cause: lastError });
							errorEvent._prepareWithTarget(this._submission);
						}

						this._reject(errorEvent);
					}
				}
			});
			try {
				this._submission._doSend();
			} catch (e) {
				utils.logError(e);
				let errorEvent: events.CSubmissionEvent = new events.CSubmissionEvent(events.SubmissionEventType.ERROR, { cause: e });
				errorEvent._prepareWithTarget(this._submission);

				this._reject(errorEvent);

				core.Platform.INSTANCE._reportError(exceptions.ErrorContext.SUBMISSION, e);
			}
		}

	}
}