		/**
		 * @override 그리드에서 탭 이동시 이전과 다음에 따라 동작 할 수 있도록 제공
		 * @param forward 
		 */
		public override _focusImmediately(forward: boolean = true): void {
			if (this.disposed === true || this.focusable === false) {
				return;
			}

			let rootElement: HTMLElement = this._getRenderer().getRootNode();
			let domTraverser: ufc.DOMTraverser = null;
			let targetElement: HTMLElement = null;
			let items: Item[] = this.getItems();
			if (forward == true) {
				for (let i = 0; i < items.length; i++) {
					if (this.getItemEnable(items[i]) == true) {
						domTraverser = ufc._traverseFromElement(rootElement);
						domTraverser = domTraverser._child("[data-role='checkbox'][data-value='" + items[i].value + "']");
						if (domTraverser != null) {
							targetElement = domTraverser._getElement();
							domTraverser.dispose();
							break;
						}
					}
				}
			} else {
				for (let i = (items.length - 1); i >= 0; i--) {
					if (this.getItemEnable(items[i]) == true) {
						domTraverser = ufc._traverseFromElement(rootElement);
						domTraverser = domTraverser._child("[data-role='checkbox'][data-value='" + items[i].value + "']");
						if (domTraverser != null) {
							targetElement = domTraverser._getElement();
							domTraverser.dispose();
							break;
						}
					}
				}
			}

			if (targetElement) {
				targetElement.focus();
			}
		}

