/// <reference path="./DataProvider.ts"/>

namespace cpr.controls.provider {

	/**
	 * value, label로 구성된 리스트 형태의 데이터를 관리하는 상위 클래스.
	 * @private
	 */
	export abstract class AbstractCalendarDataProvider<
		ItemType extends CalendarItem,
		ConfigType extends CalendarItemSetConfig, ControlType extends UIControl & MultiValueBindable> extends AbstractListDataProvider<ItemType, ConfigType, UIControl & MultiValueBindable> {

		private _selection: ItemType[] = [];

		/**
		 * value, label, parentValue로 구성된 트리 형태의 데이터를 가진 컨트롤을 생성합니다.
		 * @param owner 다중 선택을 할 수 있는 value를 가진 컨트롤.
		 */
		constructor(owner: ControlType) {
			super(owner);
		}

		/**
		 * 선택된 리스트 데이터 배열을 반환합니다.
		 * @return 선택된 리스트 데이터 배열.
		 */
		getSelection(): ItemType[] {
			return this._selection;
		}

		/**
		 * 선택된 리스트 데이터 배열 중 첫번째 데이터를 반환합니다.
		 * @return 첫번째 선택된 데이터.
		 */
		getSelectionFirst() {
			return this._selection[0] ? this._selection[0] : null;
		}

		/**
		 * 선택된 리스트 데이터 배열 중 마지막 데이터를 반환합니다.
		 * @return 마지막으로 선택된 데이터.
		 */
		getSelectionLast() {
			return this._selection[this._selection.length - 1] ? this._selection[this._selection.length - 1] : null;
		}

		/**
		 * 선택된 리스트 데이터의 개수를 반환합니다.
		 * @return 선택된 리스트 데이터의 개수.
		 */
		getSelectionSize() {
			return this._selection.length;
		}

		protected hasValidItemSetConfig(): boolean {
			return this.itemSetConfig != null
				&& this._dataSet != null
				&& this.itemSetConfig.label != null
				&& this.itemSetConfig.start != null
				&& this.itemSetConfig.end != null;
		}

		/**
		 * 선택된 리스트 데이터를 모두 선택 해제 합니다.
		 */
		clearSelection() {
			this._selection = [];
		}

		setSelection(selection: ItemType[]) {
			this._selection = selection;
		}

		/**
		 * 해당 리스트 데이터의 선택 여부를 반환합니다.
		 * @param item 선택 여부를 확인할 리스트 데이터.
		 * @return 선택 여부.
		 */
		isSelected(item: ItemType): boolean {
			let find = _.find(this._selection, (each) => {
				return item.value == each.value
			});
			return find != null;
		}

		/**
		 * 해당 리스트 데이터를 선택합니다.
		 * @param item 선택할 리스트 데이터.
		 * @return 선택 성공 여부.
		 */
		select(item: ItemType, multiple: boolean = false): boolean {
			if (item == null) {
				return false;
			}
			if (multiple === true) {
				let hasItem: boolean = this.getSelection().some((each: ItemType) => {
					return each.value == item.value
				});
				if (hasItem) {
					return false;
				}
				this._selection.push(item);

				return true;
			} else {
				this._selection = [item];
				return true;
			}
		}

		/**
		 * 해당 리스트 데이터 배열을 선택합니다.
		 * @param items 선택할 리스트 아이템의 배열.
		 */
		selectItems(items: ItemType[], multiple: boolean = false): void {
			if (!items) {
				return;
			}
			if (multiple) {
				this._selection = this._selection.concat(items);
			} else {
				this._selection = items;
			}
			this.owner.redraw();
		}

		/**
		 * 조건에 맞는 리스트 데이터 목록을 가져옵니다.
		 * <pre><code>
		 * control.findItems(function(item){
		 *  return moment(item.start).isSame(moment("2020-06-30"));
		 * });
		 * </code></pre>
		 * @param condition 데이터를 찾을 조건.
		 * @return 조건에 맞는 리스트 데이터 목록.
		 * 
		 */
		findItems(condition: any): ItemType[] {
			let result = this._find((it: ItemType) => {
				return condition(it)
			});
			return result;
		}

		/**
		 * 조건에 맞는 리스트 데이터를 가져옵니다.<br>
		 * 데이터가 2개 이상이라면 첫번째 데이터를 가져옵니다.
		 * <pre><code>
		 * control.findItem(function(item){
		 *  return moment(item.start).isSame(moment("2020-06-30"));
		 * });
		 * </code></pre>
		 * @param condition 데이터를 찾을 조건.
		 * @return 조건에 맞는 리스트 데이터.
		 */
		findItem(condition: any): ItemType {
			return this._findOne((it: ItemType) => {
				return condition(it)
			});
		}

		protected _deselectItems(items: ItemType[]) {
			this._selection = this._selection.filter((item: ItemType) => {
				let result = items.some((each: ItemType) => {
					return item.value == each.value;
				})
				return !result;
			})
		}
	}

	/**
	 * value, label,start,end로 구성된 리스트 형태의 데이터를 관리하는 클래스.
	 * @private
	 */
	export class CalendarDataProvider extends AbstractCalendarDataProvider<CalendarItem, CalendarItemSetConfig, any> {

		protected updateRow(source: CalendarItem, row: data.Row) {
			row.setValue(this.itemSetConfig.label, source.label);
			row.setValue(this.itemSetConfig.value, source.value);
			row.setValue(this.itemSetConfig.start, source.start);
			row.setValue(this.itemSetConfig.end, source.end);
			if (this.itemSetConfig.icon) {
				row.setValue(this.itemSetConfig.icon, source.icon);
			}
			if (this.itemSetConfig.tooltip) {
				row.setValue(this.itemSetConfig.tooltip, source.tooltip);
			}
		}

		protected convertRowToItem(row: data.Row): CalendarItem {
			let item = new CalendarItem(row, this);
			return item;
		}

	}
}