namespace cpr {
	export type StringInternPool = {
		/**
		 * 주어진 문자열이 풀 내부에 존재할 경우 풀 내부의 문자열을 반환하고 그 외의 경우 주어진 문자열을 반환합니다.
		 * @param text 풀을 통해 인턴을 시도할 문자열.
		 */
		_intern(text: string): string;
	} & resources.IDisposable;

	/**
	 * 문자열 인턴 풀을 만듭니다.
	 * 
	 * 이 풀은 주어진 문자열이 풀 내부에 존재할 경우 풀 내부의 문자열을 반환하고 그 외의 경우 주어진 문자열을 반환합니다.
	 * 자주 사용된 문자열은 더 오래 풀 내부에 보존됩니다.
	 * 
	 * 계산 결과에 의해 텍스트가 합성되어 만들어지고 그들이 중복될 가능성이 있는 경우, 이 풀을 통해 메모리 중복을 피할 수 있습니다.
	 * 
	 * @param capacity 풀이 관리하는 최대 텍스트 수.
	 * @returns 새로운 문자열 인턴 풀.
	 */
	export function _createStringInternPool(capacity: number): StringInternPool {
		return new StringInternPoolImpl(capacity);
	}

	type InterningEntry = {
		/** 인턴된 텍스트 */
		_text: string,

		/** 참조 회수 */
		_usage: number
	}

	/**
	 * @private
	 */
	class StringInternPoolImpl implements StringInternPool {
		private _capacity: number;
		private _cache: CMap<string, InterningEntry> = _createMap();
		private _disposed: boolean = false;

		/**
		 * @param capacity 인턴풀이 보관할 최대 문자열의 개수
		 */
		constructor(capacity: number) {
			this._capacity = capacity;
		}

		public _intern(text: string): string {
			if (!text) {
				return text;
			}

			// 캐시에 존재하는 경우.
			let existingEntry = this._cache.get(text);
			if (existingEntry) {
				return existingEntry._usage++, existingEntry._text;
			}

			// 추가할 공간이 없으면 usage가 가장 작은 항목 하나를 삭제 한다.
			if (this._cache.size === this._capacity + 1) {
				let entryToRemove = CMap._entryStream(this._cache)
					.minBy(it => it.value._usage, 1);
				this._cache.delete(entryToRemove.key);
			}

			this._cache.set(text, { _text: text, _usage: 1 });
			return text;
		}

		public _clear(): void {
			this._cache.clear();
		}

		public dispose(): void {
			this._capacity = null;
			this._cache = null;
			this._disposed = true;
		}

		public get disposed(): boolean {
			return this._disposed;
		}
	}
}