namespace cpr.core {
	export interface UniversallyUniqueIdentifier {
		readonly uuid: string
	}

	/**
	 * ID및 UUID를 통해 식별이 가능한 객체를 추상화하는 인터페이스.
	 */
	export interface Identifiable extends UniversallyUniqueIdentifier {
		readonly id: string
	}

	/**
	 * @internal
	 */
	export namespace Identifiable {
		export function _isIdentifiable(obj: object): obj is Identifiable {
			return obj instanceof cpr.controls.Control
				|| obj instanceof cpr.core.AppInstance
				|| obj instanceof cpr.core.App;
		}
	}
}