/// <reference path="./ItemListView.ts"/>

namespace cpr.controls.item {
	/**
	 * @private
	 */
	export class TreeItemListView extends ItemListView<TreeItem, TreeItemList, TreeItemFilter> implements IItemListView<TreeItem> {

		constructor(owner: UIControl, treeItemList: TreeItemList, itemFilter: TreeItemFilter) {
			super(owner, treeItemList, itemFilter);
			this.setValidatorType(ControlItemValidatorType.treeItem);
		}

		/**
		 * 필터가 있는지 유무를 확인합니다.
		 */
		public hasFilter(): boolean {
			return super.hasFilter() || this.treeFilterExpression != null;
		}

		public get treeFilter(): expression_string {
			if (this.treeFilterExpression) {
				return this.treeFilterExpression.src;
			}
			return null;
		}

		public set treeFilter(filterExpression: expression_string) {
			if (filterExpression) {
				this._setTreeFilterExpression(new expression.Expression(filterExpression));
			} else {
				this._setTreeFilterExpression(null);
			}
		}

		public get treeFilterExpression(): cpr.expression.Expression {
			return this.itemFilter.treeFilterExpression;
		}

		protected _setTreeFilterExpression(filterExpression: cpr.expression.Expression): void {
			this.itemFilter.treeFilterExpression = filterExpression;
			this.owner.redraw();
		}

		/**
		 * 적용된 필터를 제거합니다.
		 */
		public override clearFilter(): void {
			if (this.treeFilterExpression != null) {
				this._setTreeFilterExpression(null);
			}
			super.clearFilter();
		}

		/// ITreeItemListView 구현 부분

		/**
		 * 트리의 아이템들을 트리 구조로 반환합니다.
		 * @returns 
		 */
		@useCacheRealm("redraw-grid-row")
		public getVisibleItemsAsTree(): TreeItem[] {
			let hasFilter = this.hasFilter();
			let itemInfo = this.itemList._getItemInfo(hasFilter == false, false);
			let rootItems: TreeItem[] = itemInfo.rootItems;

			if (this.filter) {
				rootItems = this._filterItems(itemInfo.items, rootItems, true, false).rootItems;
			}

			if (this.treeFilterExpression) {
				rootItems = this._treeFilterItems(rootItems, true, false);
			}
			return rootItems;
		}

		/**
		 * 트로 구조로 반환합니다. 
		 * 유효성 검사를 수행합니다.
		 * 그리드에서 필터 속성이 행마다 달라 안전하게 행에서 캐시를 저장해야 합니다.
		 * @returns
		 */
		public getVisibleItemsForRendering(): TreeItem[] {
			let hasFilter = this.hasFilter();
			let itemInfo = this.itemList._getItemInfo(hasFilter == false, true);
			let rootItems: TreeItem[] = itemInfo.rootItems;

			if (this.filter) {
				rootItems = this._filterItems(itemInfo.items, rootItems, true, true).rootItems;
			}

			if (this.treeFilterExpression) {
				rootItems = this._treeFilterItems(rootItems, true, true);
			}
			return rootItems;
		}

		/**
		 * 리스트 형태로 반환합니다.
		 * @returns 
		 */
		@useCacheRealm("redraw-grid-row")
		public getVisibleItems(): TreeItem[] {
			let hasFilter = this.hasFilter();
			let itemInfo = this.itemList._getItemInfo(hasFilter == false, false);
			let items: TreeItem[] = itemInfo.items;
			let rootItems: TreeItem[] = itemInfo.rootItems;

			if (this.filter) {
				let filterInfo = this._filterItems(items, rootItems, true, false);
				rootItems = filterInfo.rootItems;
				items = filterInfo.items;
			}

			if (this.treeFilterExpression) {
				rootItems = this._treeFilterItems(rootItems, true, false);
				items = this._toItemArray(rootItems);
			}
			return items;
		}

		public findOne(findFunc: (it: TreeItem, idx?: number) => boolean): TreeItem {
			let result: TreeItem = null;
			let items: TreeItem[] = this.getVisibleItems();
			items.some((each: TreeItem, index: number) => {
				if (findFunc(each, index) == true) {
					result = each;
					return true;
				}
				return false;
			});
			return result;
		}

		/// ITreeItemListView 구현 부분 끝

		/**
		 * 트리에서 특정 value를 가진 아이템을 찾습니다.
		 * @param findValue 찾을 value
		 * @param items 검색할 아이템 배열
		 * @returns 찾은 아이템 또는 null
		 */
		public findTreeByValue(findValue: string, items: TreeItem[]): TreeItem {
			if (items == null) {
				return null;
			}

			let result = _createTreeStream({ children: items } as any as TreeItem, false, (each: TreeItem) => {
				return each.children;
			}).find((each: TreeItem) => {
				return each.value == findValue;
			}) as TreeItem;
			return result;
		}
		/**
		 * 모든 아이템들을 닫습니다.
		 */
		public collapseAllItems() {
			this.itemList.predefinedItems.forEach((item: TreeItem) => {
				if (item.expanded) {
					item._setOpen(false);
				}
			});

			if (this.itemList.dataSet) {
				let rowIndices: number[] = this.itemList.dataSet.getRowStatedIndices(this.itemList.visibleRowState);
				rowIndices.forEach((rowIndex: number) => {
					if (this.itemList.dataSet._getCtrlAttr(this.owner, rowIndex, ItemDataSetCtrlProperty.open)) {
						this.itemList.dataSet._setCtrlAttr(this.owner, rowIndex, ItemDataSetCtrlProperty.open, false);
					}
				});
			}
		}

		public isExpanded(item: TreeItem): boolean {
			let attr = this.itemList.getItemAttribute(item, ItemDataSetCtrlProperty.open);
			return typeof attr == "boolean" ? attr : attr == "true";
		}

		/**
		 * 아이템의 확장/축소 상태를 설정합니다.
		 * @param item 설정할 아이템
		 * @param state 확장 상태
		 */
		public setExpanded(item: TreeItem, state: boolean) {
			this.itemList.setItemAttribute(item, ItemDataSetCtrlProperty.open, state);
		}
		/**
		 * 체크박스를 체크하거나 해제합니다.
		 * @param sourceItem 
		 * @param state 
		 */
		public setChecked(sourceItem: TreeItem, state: boolean): boolean {
			return this.itemList.setItemAttribute(sourceItem, ItemDataSetCtrlProperty.checked, state);
		}

		/**
		 * 체크된 모든 아이템들을 반환합니다.
		 * @returns 체크된 아이템 배열
		 */
		public getCheckedItems() {
			return this.find((it: TreeItem) => {
				return it.checked;
			});
		}
		/**
		 * 체크된 아이템들을 설정합니다.
		 * @param checkedItems 체크할 아이템 배열
		 */
		public setCheckedItems(checkedItems: TreeItem[]) {
			let checkedItemMap = _stream(checkedItems).toMap((each) => each.value);

			this.itemList.predefinedItems.forEach((each) => {
				if (checkedItemMap.has(each.value)) {
					each.checked = true;
				} else {
					each.checked = false;
				}
			});
			if (this.itemList.dataSet != null) {
				let rowIndices: number[] = this.itemList.dataSet.getRowStatedIndices(this.itemList.visibleRowState);
				rowIndices.forEach((rowIndex: number) => {
					let row: data.IDataRow = this.itemList.dataSet.getRow(rowIndex);
					let value = utils.Util.toString(row.getValue(this.itemList.itemSetConfig.value));
					let hasChecked = checkedItemMap.has(value);
					if (this.itemList.itemSetConfig.checked) {
						let checked = row.getValue(this.itemList.itemSetConfig.checked);
						if (hasChecked) {
							row.setValue(this.itemList.itemSetConfig.checked, "true");
						} else if (checked == "true") {
							row.setValue(this.itemList.itemSetConfig.checked, "false");
						}
					} else {
						if (hasChecked) {
							this.itemList.dataSet._setCtrlAttr(this.owner, row.getIndex(), ItemDataSetCtrlProperty.checked, true);
						} else {
							this.itemList.dataSet._deleteCtrlAttr(this.owner, row.getIndex(), ItemDataSetCtrlProperty.checked);
						}
					}
				});
			}

		}

		/**
		 * 해당 트리 데이터의 모든 하위(자식) 데이터를 반환합니다.
		 * @param item 트리 데이터.
		 * @return 하위 트리 데이터의 배열.
		 */
		public getChildren(item?: TreeItem): TreeItem[] {
			if (item == null) {
				return this.getVisibleItemsAsTree();
			}
			//이전에 value 기반으로 아이템을 가져와서 유지해야함. 다른 컨트롤의 아이템을 받았을때 value만 맞으면 동작함. 2020-10-08
			let findItem = this.findTreeByValue(item.value, this.getVisibleItemsAsTree());
			if (findItem) {
				return findItem.children;
			}
			return [];
		}

		/**
		 * 필터를 적용하여 아이템들을 필터링합니다.
		 * @param items 전체 아이템 배열
		 * @param rootItems 최상위 아이템 배열
		 * @param useException 예외 사용 여부
		 * @param immediatelyException 즉시 예외 발생 여부
		 * @returns 필터링된 아이템과 최상위 아이템
		 */
		private _filterItems(items: TreeItem[], rootItems: TreeItem[], useException: boolean = false, immediatelyException: boolean = false) {
			if (!this.filter) {
				return { items: items, rootItems: rootItems };
			}
			let valueKeyMap = new provider.ItemMap<TreeItem>();
			if (useException) {
				if (!this.treeFilterExpression) {
					let treeItemChecker = new provider.TreeItemChecker({
						ownerId: this.itemList.owner.id, ownerType: this.itemList.owner.type, multiple: this.itemList.owner.multiple, delimiter: this.itemList.owner.delimiter
					});
					valueKeyMap.setterValidator = (item, itemMap) => {
						treeItemChecker.check(item, itemMap, immediatelyException);
					};
				}
			}

			let filterItems = [];
			let bindCtx: bind.BindContext = this.owner.getBindContext();
			let filterFunc: (item: TreeItem, key: number, context: TreeItem[]) => boolean = this.filterExpression.asFilter();
			let appInstance = this.owner.getAppInstance();
			items.forEach((item: TreeItem, key: number, context: TreeItem[]) => {
				item._ownerBindContext = bindCtx;
				item._expressionIDLookupProvider = appInstance;

				let filterResult: boolean = filterFunc(item, key, context);
				if (filterResult) {
					let newItem = this._copyItem(item);
					valueKeyMap.set(newItem.value, newItem);
					filterItems[filterItems.length] = newItem;
				}
				item._expressionIDLookupProvider = null;
				item._ownerBindContext = null;
			});
			rootItems = this.itemList._createTreeStructure(valueKeyMap, filterItems);
			valueKeyMap = null;
			return { items: filterItems, rootItems: rootItems }
		}

		/**
		 * 트리 필터를 적용하여 아이템들을 필터링합니다.
		 * @param rootItems 최상위 아이템 배열
		 * @param useException 예외 사용 여부
		 * @param immediatelyException 즉시 예외 발생 여부
		 * @returns 필터링된 최상위 아이템 배열
		 */
		private _treeFilterItems(rootItems: TreeItem[], useException: boolean = false, immediatelyException: boolean = false) {
			if (!this.treeFilterExpression) {
				return rootItems;
			}
			let checkedItemMap: provider.ItemMap<TreeItem>;
			if (useException) {
				checkedItemMap = new provider.ItemMap<TreeItem>();
				let treeItemChecker = new provider.TreeItemChecker({
					ownerId: this.itemList.owner.id, ownerType: this.itemList.owner.type, multiple: this.itemList.owner.multiple, delimiter: this.itemList.owner.delimiter
				});
				checkedItemMap.setterValidator = (item, itemMap) => {
					treeItemChecker.check(item, itemMap, immediatelyException);
				};
			}

			let bindCtx: bind.BindContext = this.owner.getBindContext();
			let filterFunc: (item: TreeItem, key: number, context: TreeItem[]) => boolean = this.treeFilterExpression.asFilter();
			let appInstance = this.owner.getAppInstance();

			let treeFilteredItems = this._filterTreeItemExpr(null, rootItems, filterFunc, { bindContext: bindCtx, lookupProvider: appInstance, itemMap: checkedItemMap });

			return treeFilteredItems;
		}

		/**
		 * Expression을 사용하여 트리 아이템들을 재귀적으로 필터링합니다.
		 * @param parent 부모 아이템
		 * @param items 필터링할 아이템 배열
		 * @param filterFunction 필터 함수
		 * @param info 바인딩 컨텍스트 및 룩업 프로바이더 정보
		 * @returns 필터링된 아이템 배열
		 */
		private _filterTreeItemExpr(parent: TreeItem, items: TreeItem[], filterFunction: (item: TreeItem, key: number, context: TreeItem[]) => boolean,
			info: { bindContext: bind.BindContext, lookupProvider: core.AppInstance, itemMap?: provider.ItemMap<TreeItem> }) {

			let result = [];
			items.forEach((each: TreeItem, index: number, context: TreeItem[]) => {
				let newItem = this._copyItem(each);
				if (each._hasChild()) {
					let children = this._filterTreeItemExpr(newItem, each.children as TreeItem[], filterFunction, info) as TreeItem[];
					newItem._setChildren(children);
				}

				each._ownerBindContext = info.bindContext;
				each._expressionIDLookupProvider = info.lookupProvider;
				let filterRs: boolean = filterFunction(each, index, context);
				each._expressionIDLookupProvider = null;
				each._ownerBindContext = null;
				if (filterRs || newItem._hasChild()) {
					if (info.itemMap) {
						info.itemMap.set(newItem.value, newItem);
					}
					newItem._setParent(parent);
					result[result.length] = newItem;
				}
			})
			return result;
		}

		/**
		 * _findItemSelection에서 이름 변경
		 * @param values 
		 * @returns 
		 */
		public findItemByValues(values: string[]): TreeItem[] {
			let valueSet = _createSet<string>(values);
			let findItems = this.itemList.find((it: TreeItem) => {
				return valueSet.has(it.value);
			});
			return findItems;
		}

		/**
		 * 조건에 맞는 모든 아이템을 찾습니다.
		 * @param findFunc 검색 조건 함수
		 * @returns 찾은 아이템 배열
		 */
		public find(findFunc: (it: TreeItem, idx?: number) => boolean): TreeItem[] {
			if (this.hasFilter()) {
				let items: TreeItem[] = this.getVisibleItems();
				return items.filter((each: TreeItem, index: number) => {
					return findFunc(each, index) == true;
				});
			}
			return this.itemList.find(findFunc);
		}

		/**
		 * 트리의 아이템들을 배열로 변경합니다.
		 * @param rootItems 
		 */
		private _toItemArray(rootItems: TreeItem[]): TreeItem[] {
			let result: TreeItem[] = [];
			rootItems.forEach((each: TreeItem) => {
				result.push(each);

				if (each._hasChild()) {
					result = result.concat(this._toItemArray(each.children as TreeItem[]));
				}
			});
			return result;
		}

		/**
		 * 아이템을 복사합니다.
		 * @param item 복사할 아이템
		 * @returns 복사된 아이템
		 */
		private _copyItem(item: TreeItem): TreeItem {
			return this.itemList.itemAdapter.copyItem(item);
		}

	}
}