namespace cpr.controls.gridpart {
	/**
	 * @private
	 */
	export class ClipboardUtil {

		/**
		 * 클립보드 이벤트를 받아 2차원 배열로 변환
		 * @param e 
		 * @returns 
		 */
		public static _getClipboardData(e: events.CEvent): string[][] {
			let pasteMatrix: string[][] = null;

			if (window["clipboardData"] && window["clipboardData"].getData) {
				// IE11 전용 클립보드 접근 방식
				let plainText: string = window["clipboardData"].getData("Text");
				if (plainText != null) {
					pasteMatrix = this._parseClipboardText(plainText);
				}

			} else if (e.clipboardData && e.clipboardData.getData) {
				// 표준 Clipboard API (Chrome, Firefox, Edge, etc.)
				let clipboardData: DataTransfer = e.clipboardData || window["clipboardData"];
				if (clipboardData) {
					let htmlData = clipboardData.getData("text/html");
					if (htmlData && htmlData.includes("<table")) {
						pasteMatrix = this._parseClipboardHTML(htmlData);

					} else {
						let plainText: string = clipboardData.getData("text/plain");
						if (plainText != null && plainText != "") {
							pasteMatrix = this._parseClipboardText(plainText);
						} else {
							pasteMatrix = null;
						}
					}
				}
			}
			return pasteMatrix;
		}

		/**
		 * HTML 데이터에서 테이블을 파싱하여 이중 배열로 반환합니다.
		 * @param htmlData 
		 * @returns 
		 */
		private static _parseClipboardHTML(htmlData: string): string[][] {
			let pasteMatrix: string[][] = null;
			// Excel 데이터: HTML 테이블이 포함되어 있음
			const parser = new DOMParser();
			const doc = parser.parseFromString(htmlData, "text/html");
			const table = doc.querySelector("table");
			if (table) {
				let rows = table.querySelectorAll("tr");
				pasteMatrix = [];

				// <BR>만 \n으로 변환하고, 소스상 줄바꿈/공백은 정리합니다.
				const getCleanText = (element: HTMLElement, preserveWhitespace: boolean = false): string => {
					let text = "";
					element.childNodes.forEach((node) => {
						if (node.nodeType === Node.ELEMENT_NODE) {
							const el = node as HTMLElement;
							if (el.tagName === "BR") {
								text += "\n"; // <BR> 태그는 실제 줄바꿈으로 인정
							} else if (el.tagName === "SPAN") {
								text += getCleanText(el, true); // <SPAN> 내부는 공백 유지
							} else {
								text += getCleanText(el); // 그 외 하위 요소 재귀 탐색
							}
						} else if (node.nodeType === Node.TEXT_NODE) {
							let content = node.textContent
								.replace(/[ \t]*[\r\n]+[ \t]*/g, " "); // 줄바꿈 전후 공백 → 공백 하나
							if (!preserveWhitespace) {
								content = content.replace(/^[ \t]+|[ \t]+$/g, ""); // 앞뒤 공백 제거
							}
							text += content;
						}
					});
					return text;
				};


				rows.forEach((row, rowIndex) => {
					let cells = row.querySelectorAll("td, th");
					if (!pasteMatrix[rowIndex]) {
						pasteMatrix[rowIndex] = [];
					}

					let colIdx = 0;
					cells.forEach((cell: HTMLElement) => {
						// 현재 행에서 아직 채워지지 않은 가장 빠른 인덱스를 찾습니다. (이전 행의 rowspan 등으로 점유된 위치 고려)
						while (pasteMatrix[rowIndex][colIdx] !== undefined) {
							colIdx++;
						}

						const text = getCleanText(cell);
						const rowspan = parseInt(cell.getAttribute("rowspan") || "1", 10);
						const colspan = parseInt(cell.getAttribute("colspan") || "1", 10);

						// 병합된 모든 셀 위치에 값을 할당합니다. (첫 셀은 실제 데이터, 나머지는 빈 값)
						for (let r = 0; r < rowspan; r++) {
							const tr = rowIndex + r;
							if (!pasteMatrix[tr]) {
								pasteMatrix[tr] = [];
							}
							for (let c = 0; c < colspan; c++) {
								const tc = colIdx + c;
								// 이미 다른 rowspan에 의해 채워져있을 가능성(잘못된 HTML 등)을 고려하여 비어있는 경우에만 할당
								if (pasteMatrix[tr][tc] === undefined) {
									pasteMatrix[tr][tc] = (r === 0 && c === 0) ? text : "";
								}
							}
						}
						colIdx += colspan;
					});
				});

				// 행 간의 길이를 맞추고 undefined(배열 홀)를 빈 문자열("")로 보정합니다.
				for (let r = 0; r < pasteMatrix.length; r++) {
					const row = pasteMatrix[r];
					for (let c = 0; c < row.length; c++) {
						if (row[c] === undefined) {
							row[c] = "";
						}
					}
				}
			}

			return pasteMatrix;
		}

		/**
		 * 탭(\t)/개행(\r\n|\n|\r) 구분 텍스트를 이중 배열로 파싱합니다.
		 */
		private static _parseClipboardText(text: string): string[][] {
			var rows = [];
			var currentRow = [];
			var currentCell = '';
			var inQuotes = false; // 현재 따옴표 내부에 있는지 여부

			for (var i = 0; i < text.length; i++) {
				var char = text.charAt(i);
				var nextChar = text.charAt(i + 1);

				// 1. 쌍따옴표 처리 (이스케이프 및 시작/끝)
				if (char === '"') {
					if (inQuotes && nextChar === '"') {
						// 쌍따옴표가 두 번 연속되면 실제 데이터인 따옴표(")로 처리
						currentCell += '"';
						i++; // 다음 따옴표 건너뜀
					} else {
						// 따옴표 상태 반전 (열기/닫기)
						inQuotes = !inQuotes;
					}
					continue;
				}

				// 2. 탭(열 구분) 처리
				if (char === '\t' && !inQuotes) {
					currentRow.push(currentCell);
					currentCell = '';
					continue;
				}

				// 3. 줄바꿈(행 구분) 처리
				if ((char === '\r' || char === '\n') && !inQuotes) {
					// \r\n 처리
					if (char === '\r' && nextChar === '\n') {
						i++;
					}
					currentRow.push(currentCell);
					rows.push(currentRow);
					currentRow = [];
					currentCell = '';
					continue;
				}

				// 4. 일반 문자 추가
				currentCell += char;
			}

			// 마지막에 남은 데이터 처리
			if (currentCell !== '' || currentRow.length > 0) {
				currentRow.push(currentCell);
				rows.push(currentRow);
			}

			return rows;
		}
	}
}