namespace cpr.controls.calendar {
	/**
	 * 기념일 객체.
	 */
	export interface Anniversary {
		/**
		 * 캘린더의 format에 맞는 기념일 날짜.
		 */
		date: string;
		/**
		 * 기념일 설명합니다.
		 * 툴팁으로 표시됩니다.
		 */
		label?: string;
		/**
		 * 기념일에 대한 스타일 클래스 설정. 
		 * @deprecated {@link className}을 사용하시기 바랍니다.
		 */
		class?: string;
		/**
		 * 기념일에 대한 스타일 클래스 설정.
		 */
		className?: string;
		/**
		 * 달력에서 날짜를 선택 불가능 여부.
		 */
		unselectable?: boolean;

		/**
		 * @private
		 */
		id?: string;
	}

	/**
	 * 모든 데이트인풋의 캘린더에 기념일을 추가합니다.
	 * 정해진 format에 맞춘 기념일 날짜를 추가합니다.<br/>
	 * 기념일 날짜는 문자열로 추가할 수 있습니다.<br/>
	 * 와일드 카드("*")를 적용하여 날짜를 작성 시 매년, 매월, 매일로 적용됩니다.<br/>
	 * <pre><code>
	 * cpr.controls.Calendar.addAnniversary("*1006");//매년 10월 6일
	 * </code></pre>
	 * @param anny 기념일. 날짜 문자열.
	 * @param format 기념일 날짜 형식. YYYY, MM, DD를 지원합니다.
	 */
	export function addAnniversary(anny: string, format?: string): void;
	/**
	 * 모든 데이트인풋의 캘린더에 기념일을 추가합니다.
	 * 정해진 format에 맞춘 기념일 날짜를 추가합니다.<br/>
	 * 기념일 날짜는 {date, label, className, unselectable}로 구성된 객체로 추가할 수 있습니다.<br/>
	 * 와일드 카드("*")를 적용하여 날짜를 작성 시 매년, 매월, 매일로 적용됩니다.<br/>
	 * <pre><code>
	 * cpr.controls.Calendar.addAnniversary({date:"20121006",label:"holiday",className:"holiday",unselectable:false});
	 * </code></pre>
	 * @param anny 기념일. {date, label, className, unselectable}로 구성된 객체.
	 * @param format 기념일 날짜 형식. YYYY, MM, DD를 지원합니다.
	 */
	export function addAnniversary(anny: Anniversary, format?: string): void;
	/**
	 * 모든 데이트인풋의 캘린더에 기념일을 추가합니다.
	 * 정해진 format에 맞춘 기념일 날짜를 추가합니다.<br/>
	 * 기념일 날짜는 문자열 또는 {date, label, className, unselectable}로 구성된 객체를 배열에 넣어 추가할 수 있습니다.<br/>
	 * 와일드 카드("*")를 적용하여 날짜를 작성 시 매년, 매월, 매일로 적용됩니다.<br/>
	 * <pre><code>
	 * cpr.controls.Calendar.addAnniversary(["20121006",{date:"20121106",label:"holiday",className:"holiday",unselectable:false}]);
	 * </code></pre>
	 * @param anny 기념일. {date, label, className, unselectable}로 구성된 객체 또는 날짜 문자열의 배열.
	 * @param format 기념일 날짜 형식. YYYY, MM, DD를 지원합니다.
	 */
	export function addAnniversary(anny: (string | Anniversary)[], format?: string): void;
	export function addAnniversary(anny: any, format: string = "YYYYMMDD") {
		cpr.controls.Calendar.addAnniversary(anny, format);
	}
}