///<reference path="./Classes.ts"/>

namespace cpr.ufc {
	/**
	 * CSS 속성 선언 문들의 배열을 join 합니다.
	 * 결과값을 HTML 노드의 style값으로 지정하려면, {@link utils.HTMLEncoder.encodeForHTMLAttribute}와 함께 사용 하십시오.
	 * @param cssPropDeclaration 속성 선언 구문 배열.
	 * @returns ;로 합쳐진 문자열.
	 */
	export function _joinCSSArray(cssPropDeclaration: string[]): string {
		if (cssPropDeclaration && cssPropDeclaration.length > 0) {
			let cssString: string = cssPropDeclaration.join(";") + ";";
			return cssString;
		}
		return "";
	}

	/**
	 * {@link CSSStyleDeclaration} 형태의 JSON 객체를 바탕으로 HTML노드의 style 속성에 지정할 수 있는 단일 문자열 값 형태로 변환 합니다.
	 * @param style 스타일 정의 객체.
	 * @returns HTML노드의 style 속성에 지정될 수 있는 값.
	 * 결과값을 HTML 노드의 style값으로 지정하려면, {@link utils.HTMLEncoder.encodeForHTMLAttribute}와 함께 사용 하십시오.
	 */
	export function _createCSSText(style: { [key: string]: string }): string {
		let shapeStyles: string[] = _createCSSArray(style);
		return _joinCSSArray(shapeStyles);
	}

	/**
	 * {@link CSSStyleDeclaration} 형태의 JSON 객체를 바탕으로 CSS 속성 선언 배열로 변환합니다.
	 * 변환된 속성 선언문의 속성명은 대시 구분 규칙으로 변경됩니다. `borderColor` -> `border-color`
	 * @param style 스타일 정의 객체.
	 * @returns 속성 선언 구문들의 배열.
	 */
	export function _createCSSArray(style: { [key: string]: string }): string[] {
		let normalStyle: { [key: string]: string } = {};
		for (let styleName in style) {
			let normalStyleName = _camelToDash(styleName);
			normalStyle[normalStyleName] = style[styleName];
		}
		let shapeStyles: string[] = [];
		for (let styleName in normalStyle) {
			shapeStyles[shapeStyles.length] = styleName + ":" + normalStyle[styleName];
		}

		shapeStyles = shapeStyles.sort();
		return shapeStyles;
	}

	/**
	 * HTML노드의 style 애트리뷰트 값 형태의 텍스트를 각 속성 선언 배열로 변환합니다.
	 * @param cssString 변환할 텍스트.
	 * @returns 속성 선언문 배열.
	 */
	function _splitCSSText(cssString: string): string[] {
		if (cssString == null) {
			return [];
		}
		return cssString.replace(/[;]$/g, "").split(";");
	}

	/**
	 * @private
	 */
	export class ShapeUtil {
		static readonly _MAX_TITLE_LENG: number = 256;
		static readonly _MAX_ARIALABEL_LENG: number = 256;

		static _getErrorShape(e: Error): ElementShape {
			let message = e && e.message ? e.message : "";
			return {
				tag: "div",
				classNames: ["cl-unavailable"],
				style: {},
				attr: { title: message },
				children: [{
					tag: "span",
					classNames: [Classes.TEXT],
					style: {},
					children: [message]
				}]
			}
		}

		static addEventHandler(shape: ElementShape, event: string, handler: Function, first: boolean = false): void {
			if (shape.hasOwnProperty("events") == false) {
				shape.events = {};
			}
			ShapeUtil._addEventHandler(shape.events, event, handler, first);
		}

		static addMandatoryEventHandler(shape: ElementShape, event: string, handler: Function, first: boolean = false): void {
			if (shape.hasOwnProperty("mandatoryEvents") == false) {
				shape.mandatoryEvents = {};
			}
			ShapeUtil._addEventHandler(shape.mandatoryEvents, event, handler, first);
		}

		private static _addEventHandler(handlerMap: { [key: string]: (string | string[] | Function | Function[]) }, event: string, handler: Function, first: boolean): void {
			if (handlerMap[event] == undefined || handlerMap[event] == null) {
				handlerMap[event] = [handler];
			} else if (_isArray(handlerMap[event]) == false) {
				let handlers = [];
				if (first === true) {
					handlers.push(handler);
					handlers.push(handlerMap[event]);
				} else {
					handlers.push(handlerMap[event]);
					handlers.push(handler);
				}
				handlerMap[event] = handlers;
			} else {
				if (first === true) {
					(handlerMap[event] as Function[]).splice(0, 0, handler);
				} else {
					(handlerMap[event] as Function[]).push(handler);
				}
			}
		}

		static mixShapeNStyler(controlShape: ElementShape, styler: controls.UIControlStyler, control: core.DrawableControl): { classNames: string[], cssText: string[] } {
			let result: { classNames: css_class_string[], cssText: string[] } = { classNames: [], cssText: [] };
			let style: { [key: string]: string } = {};

			if (styler) {
				if (controlShape.bindContext) {
					styler._setBindContext(controlShape.bindContext)
				}

				let media: string = null;
				let appInstance = control.getAppInstance();
				if (appInstance) {
					media = appInstance.targetMedia;
				}

				result.classNames = result.classNames.concat(
					styler.getBaseClassName(),
					controlShape.classNames || [],
					styler.getClasses()
				);

				style = _assign(style, styler.css());
				if (media) {
					let mediaClasses: string[] = styler.getMediaClasses(media) || [];
					result.classNames = result.classNames.concat(mediaClasses);

					let mediaStyle: {} = styler.mediaCss(media) || {};
					style = _assign(style, mediaStyle);
				}
				style = _assign(style, controlShape.style);

				styler._setBindContext(null);
			}
			// 스타일러가 없는 경우
			else {
				result.classNames = result.classNames.concat(controlShape.classNames || []);
				style = _assign(style, controlShape.style);
			}

			result.classNames = _uniq(result.classNames);
			result.cssText = _createCSSArray(style);

			return result;
		}

		static _applyStyle(nodeShape: ElementShape, nodeEle: HTMLElement, cssArray: string[], stringPool: StringInternPool): boolean {
			let oldCssText: string = nodeShape.shapeCssText;
			let oldCssArray: string[] = _splitCSSText(oldCssText);
			if (_.isEqual(oldCssArray, cssArray) === false) {
				let cssText = stringPool._intern(_joinCSSArray(cssArray));
				nodeShape.shapeCssText = cssText;
				nodeEle.style.cssText = cssText;

				return true;
			}
			return false;
		}

		static _applyClassNames(nodeShape: ElementShape, nodeEle: HTMLElement, classNames: string[]): boolean {
			if (_.isEqual(nodeShape.shapeClassNames, classNames) === false) {
				nodeShape.shapeClassNames = classNames;
				nodeEle.className = classNames.join(" ");

				return true;
			}
			return false;
		}

		static _setTooltipAttr(shape: ufc.ElementShape, info: { owner: controls.UIControl, title: string, id?: string }) {
			let title = info.title;
			if (core.Platform.INSTANCE.tooltipManager._isCustomTooltipEnabled(info.owner)) {
				if (!shape.attr) {
					shape.attr = {};
				}
				if (title != null) {
					title = "" + title;
				}
				if (title == "") {
					return;
				}
				if (shape.namespace && shape.namespace.indexOf("svg") > -1) {
					shape.attr["data-tooltip"] = "label";
					shape.attr["aria-label"] = title;
				} else {
					shape.attr["data-tooltip"] = "desc";
					let partUUID = NodeUUIDMapper.INSTANCE._createPartialUUID(info.owner, info.id ? info.id.replace(/\s/g, "_") + "-tooltip" : "tooltip");
					shape.attr["aria-describedby"] = partUUID;
					if (shape.tag && ["input", "textarea", "img", "iframe"].indexOf(shape.tag.toLocaleLowerCase()) > -1) {
						return;
					}
					if (!shape.children) {
						shape.children = [];
					}
					shape.children.push({
						namespace: shape.namespace,
						tag: "div",
						classNames: [],
						attr: {
							id: partUUID,
							role: "tooltip"
						},
						style: {
							display: "none",
							position: "absolute"
						},
						children: [title]
					})
				}
			} else if (shape.namespace && shape.namespace.indexOf("svg") > -1) {
				if (!shape.children) {
					shape.children = [];
				}
				shape.children.push({
					namespace: shape.namespace,
					tag: "title",
					children: [title]
				})
			} else {
				if (!shape.attr) {
					shape.attr = {};
				}
				ShapeUtil._setTitleAttr(shape.attr, title);
			}
		}

		static _setTitleAttr(attr: { [key: string]: string }, title: string): void {
			if (title != null) {
				title = "" + title;
			}
			title = ShapeUtil._getValidTitleAttr(title);
			if (title == "") {
				return;
			}
			attr["title"] = title;
		}

		static _getValidTitleAttr(title: string): string {
			return ShapeUtil._getValidLimitedLengAttrValue(title, ShapeUtil._MAX_TITLE_LENG);
		}

		static _setAriaLabelAttr(attr: { [key: string]: string }, ariaLabel: string): void {
			if (ariaLabel != null) {
				ariaLabel = "" + ariaLabel;
			}
			ariaLabel = ShapeUtil._getValidAriaLabelAttr(ariaLabel);
			if (ariaLabel == "") {
				return;
			}
			attr["aria-label"] = ariaLabel;
		}

		static _getValidAriaLabelAttr(ariaLabel: string): string {
			return ShapeUtil._getValidLimitedLengAttrValue(ariaLabel, ShapeUtil._MAX_ARIALABEL_LENG);
		}

		static _getValidLimitedLengAttrValue(text: string, limit: number): string {
			if (text == null || text == "") {
				return "";
			}
			if (text.length > limit) {
				text = text.substring(0, limit);
			}
			return text;
		}

		/**
		 * aria-disabled를 설정해야 하는 요소에 ElementShape과 enabeld 속성값을 가지는 객체를 넘겨 ElementShape에 aria-disabeld 속성을 지정합니다.
		 * @param controlShape aria-disabled를 설정해야 하는 요소에 ElementShape
		 * @param enabled enabeld 속성값
		 */
		static _setAriaDisabled(controlShape: ElementShape, enabled: boolean): void {
			if (enabled === false) {
				controlShape.attr = _assign(controlShape.attr, { "aria-disabled": "true" });
			}
		}

		static _setAriaState(shape: ElementShape, state: { enabled: boolean, readOnly: boolean }): void {
			if (state.enabled === false) {
				shape.attr = _assign(shape.attr, { "aria-disabled": "true" });
			}
			if (state.readOnly === true) {
				shape.attr = _assign(shape.attr, { "aria-readonly": "true" });
			}
		}

		/**
		 * 엘리먼트 상태를 지원하는 태그에 속성과 관련된 추가 설정을 합니다.
		 * disabled: [button, select, input, textarea, fieldset, optgroup, option]
		 * readonly: [input, textarea]
		 * @param shape 
		 * @param state 
		 */
		static _setInputElementState(shape: ElementShape, state: { enabled: boolean, readOnly: boolean }) {
			if (state.enabled === false) {
				shape.attr = _assign(shape.attr, { disabled: "" });
				delete shape.attr["tabindex"];
				// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/9149
				shape.style = _assign(shape.style, { "pointer-events": "none" });
			}
			if (state.readOnly === true) {
				shape.attr = _assign(shape.attr, { readonly: "" });
			}
		}
	}
}