namespace cpr.controls.internal {

	/**
	 * @private
	 */
	export class UserAttributes implements UserAttributesOwner {
		private _data: CMap<string, string>;

		public userAttr(): any {
			let args = _toArray(arguments);
			switch (args.length) {
				case 0: {
					return this._data
						? CMap._toJSON(this._data)
						: {};
				}
				case 1: {
					if (typeof args[0] == "string") {
						let key = args[0] as string;
						return this._data?.get(key) ?? "";
					}
					else if (typeof args[0] == "object") {
						let obj = args[0] as object;
						Object.getOwnPropertyNames(obj).forEach(key => {
							let value = obj[key];

							if (typeof value != "string") {
								new exceptions.IllegalArgumentException(`Given value for key "${key}" is not a String.`);
							}
							else {
								this._ensureData().set(key, value);
							}
						});
					}
					else {
						throw new exceptions.IllegalArgumentException();
					}
					break;
				}
				case 2: {
					let key: string = args[0] as string;
					let value: string = args[1] as string;
					if (typeof key != "string" || typeof value != "string") {
						throw new exceptions.IllegalArgumentException("A value must be a String.");
					}
					this._ensureData().set(key, value);
					break;
				}
			}
		}

		/**
		 * 특정 속성 명의 사용자 정의 속성을 제거합니다.
		 * @param key 제거할 사용자 정의 속성 명.
		 */
		public removeUserAttr(key: string): void {
			this._data?.delete(key);
		}

		/**
		 * 모든 사용자 정의 속성들을 삭제합니다.
		 */
		public removeAllUserAttr(): void {
			this._data?.clear();
		}

		/**
		 * 모든 사용자 정의 속성 명을 반환합니다.
		 * @return 모든 사용자 정의 속성 명의 배열.
		 */
		public getUserAttrNames(): string[] {
			return this._data
				? CMap._keyStream(this._data).collect()
				: [];
		}

		private _ensureData(): CMap<string, string> {
			if (!this._data) {
				this._data = _createMap();
			}
			return this._data;
		}
		/* user attributes end */
	}
}