namespace cpr {

	export function _defineMomentLocale(locale: string, data: {}) {
		moment.updateLocale(locale, null);
		moment.defineLocale(locale, data);
	}

	export function _getControlLocale(control: cpr.controls.UIControl) {
		return control.type + "-" + control.uuid;
	}

	export function _deleteMomentLocale(locale: string) {
		moment.updateLocale(locale, null);
	}

	export function _createMoment(momentConstructor: () => moment.Moment, locale?: string, mergeLocaleData?: ILocaleDateTime) {
		if (!locale) {
			return momentConstructor();
		}
		locale = SystemLocale._getValidLocale(locale);
		let localeData = LocaleManager.INSTANCE._findLocaleData(locale);
		let momentLocaleData = localeData.dateTime._convertMomentLocaleData(mergeLocaleData);
		let customLocale = locale + "-custom";
		_defineMomentLocale(customLocale, momentLocaleData);
		let mm = momentConstructor().locale(customLocale);
		_deleteMomentLocale(customLocale);
		return mm;
	}

	export function _getAvailableMomentLocale(locale: string): string {
		let momentLocales = moment.locales();
		let lowerCaseLocale = locale.toLowerCase().replace(/_/, "-");
		if (_.contains(momentLocales, lowerCaseLocale)) {
			return lowerCaseLocale;
		}
		let lang = lowerCaseLocale.split("-")[0];
		if (_.contains(momentLocales, lang)) {
			return lang;
		}
		return null;
	}

}