
namespace cpr.events {
	let focusLosingUUID: string;
	let focusGainingUUID: string;

	document.addEventListener("focusin", (e: FocusEvent) => {
		focusLosingUUID = null;
		let relatedTarget: HTMLElement = e.relatedTarget as HTMLElement;
		if (relatedTarget) {
			focusLosingUUID = ufc.NodeUUIDMapper.INSTANCE._findClosestControlUUID(relatedTarget);
		}
	}, true);

	document.addEventListener("focusout", (e: FocusEvent) => {
		focusGainingUUID = null;
		let relatedTarget: HTMLElement = e.relatedTarget as HTMLElement;
		if (relatedTarget) {
			focusGainingUUID = ufc.NodeUUIDMapper.INSTANCE._findClosestControlUUID(relatedTarget);
		}
	}, true);

	/**
	 * @private
	 */
	export class FocusTracker {
		public static get focusLosingUUID(): string {
			return focusLosingUUID;
		}

		public static get focusGainingUUID(): string {
			return focusGainingUUID;
		}
	}
}