namespace cpr.ufc {
	// FIXME 호환성을 유지하며 아래 내용 변경 필요.
	const _CONTROL_NODE_ID_PREFIX = "uuid-";

	let _UUID_ADDER = _randomInt(255, 1024);
	let _UUID_SHIFT = _randomInt(2, 8);
	let _mapperInstance: NodeUUIDMapper;

	/**
	 * 주어진 메소드가 상태관리가 필요한 메소드인지 여부를 반환 합니다.
	 * @param method 
	 * @returns 
	 */
	function _isStatefulMethod(method: UUIDGenMethod): boolean {
		switch (method) {
			case UUIDGenMethod.DEPTH:
			case UUIDGenMethod.DEPTH_SHORT:
				return true;

			case UUIDGenMethod.SECURE:
			case UUIDGenMethod.INSECURE:
				return false;

			default:
				return false;
		}
	}

	export type NodeUUID = {
		/** 베이스 노드 uuid */
		base: node_uuid,

		/**
		 * `베이스/p/파트ID` 형태의 파트 UUID인 경우, `파트ID` 값.
		 */
		partIdentifier: node_uuid,

		/**
		 * 글로벌 레이어에서 컨트롤 영역의 루트 노드를 위한 UUID인지 여부.
		 * `베이스/g` 형태.
		 */
		global: boolean,

		/**
		 * 주어진 uuid가 컨트롤 노드 ID값용 uuid인지 여부.
		 * `cid-베이스` 형태.
		 */
		controlNodeID: boolean
	};

	export function _parseNodeUUID(uuid: node_uuid): NodeUUID {
		if (!uuid) {
			return null;
		}

		let controlNodeID = false;
		let [base, subType, subIdentifier] = uuid.split("/");

		[controlNodeID, base] = base.startsWith(_CONTROL_NODE_ID_PREFIX)
			? [true, base.substr(_CONTROL_NODE_ID_PREFIX.length)]
			: [false, base]
			;

		return {
			base,
			partIdentifier: subType == "p" ? subIdentifier : undefined,
			global: subType == "g",
			controlNodeID
		};
	}

	/**
	 * @deprecated
	 */
	export enum HtmlIdGenMethod {
		/**
		 * 컨트롤의 부모 계층 구조및 자식 순서에 따라 ID를 생성합니다.
		 */
		DEPTH = "depth",

		/**
		 * 컨트롤의 부모 계층 구조및 자식 순서에 따라 ID를 생성합니다. 가능한 경우 더 짧은 길이로 나타냅니다.
		 */
		DEPTH_SHORT = "depth-short"
	}

	/**
	 * 컨트롤이 렌더링된 후 해당 HTML 노드의 ID를 생성하는 방법.
	 */
	export enum UUIDGenMethod {
		/**
		 * HTML노드들의 ID와 컨트롤사이의 연관성을 추정하기 어렵도록 합니다.
		 * 적절한 성능을 유지하며 HTML노드의 구조분석을 통한 앱 변조를 어렵게 합니다.
		 */
		SECURE = "secure",

		/**
		 * HTML노드들의 ID로 컨트롤의 UUID를 사용합니다.
		 * HTML노드 구조 분석을 통한 앱 내부 상태 접근에 취약할 수 있습니다. 가급적 {@link SECURE}를 사용하십시오.
		 */
		INSECURE = "insecure",

		/**
		 * 컨트롤의 부모 계층 구조및 자식 순서에 따라 ID를 생성합니다.
		 */
		DEPTH = "depth",

		/**
		 * 컨트롤의 부모 계층 구조및 자식 순서에 따라 ID를 생성합니다. 가능한 경우 더 짧은 길이로 나타냅니다.
		 */
		DEPTH_SHORT = "depth-short"
	}

	/**
	 * @private
	 */
	export class NodeUUIDMapper {
		public static get INSTANCE(): NodeUUIDMapper {
			if (!_mapperInstance) {
				_mapperInstance = new NodeUUIDMapper();
			}
			return _mapperInstance;
		}

		private _uuidGenMethod: UUIDGenMethod = null;

		/**
		 * 컨트롤 uuid : 노드 uuid 맵.
		 * 역참조 맵을 얻으려면 {@link CBiMap.inversed} 사용.
		 */
		private _uuidMap: CBiMap<control_uuid, node_uuid> = _createBiMap();

		/**
		 * 컨트롤이 렌더링 된 이후 해당 루트 노드에 부여될 ID를 얻습니다.
		 * @see _getGlobalControlNodeID
		 */
		public _getControlNodeID(control: controls.UIControl): control_render_root_node_id {
			let domUUID: string = this._convertToNodeUUID(control);

			// FIXME 이 프리픽스는 대체 왜 필요한가?
			return _CONTROL_NODE_ID_PREFIX + domUUID;
		}

		public _findClosestControlUUID(traverser: DOMTraverser): control_uuid;
		public _findClosestControlUUID(element: HTMLElement): control_uuid;
		public _findClosestControlUUID(source: any): control_uuid {
			let uuid: node_uuid = null;

			let traverser = _createTypeSwitch<DOMTraverser>()
				.case(HTMLElement, it => ufc._traverseFromElement(it))
				.case(SVGElement, it => ufc._traverseFromElement(it))
				.default(it => DOMTraverser._isDOMTraverser(it) ? it : null)
				.run(source);

			let controlElement = traverser?._closest(".cl-control");
			if (!controlElement) {
				return null;
			}

			// 다이얼로그가 모달인 경우 루트노드가 아니어서 UUID가 없기 때문에 다이얼로그를 못 찾는 문제가 발생하여 임의로 루트 노드를 설정함.
			// FIXME 좀 더 일반화된 접근법으로 처리가 필요하지 않을까?
			// FIXME 다이얼로그의 모달 오버레이도 레이아웃 데코레이터를 통해 처리하면 좋을것 같다.
			if (controlElement._getElement().classList.contains("cl-dialog")) {
				if (controlElement._getAttribute("id") == null) {
					controlElement._setElement(traverser._getElement().parentElement);
				}
			}

			// 데코레이터를 통해 래핑된 경우, 컨트롤 노드 자체는 ID가 없으므로 _ATTR_UUID를 사용
			uuid = controlElement._getAttribute("id") ?? controlElement._getAttribute(ControlRenderer._ATTR_UUID);

			uuid = _parseNodeUUID(uuid)?.base;

			if (!uuid) {
				return null;
			}

			let controlUUID = this._convertToControlUUID(uuid);
			return controlUUID;
		}

		/**
		 * 해당 컨트롤과 연관된 UUID 매핑을 제거합니다.
		 * @param control 매핑을 제거할 컨트롤.
		 */
		public _disposeControlUUID(control: controls.UIControl): void {
			if (!control) {
				return;
			}

			if (_isStatefulMethod(this._getUUIDGenMethod())) {
				this._uuidMap.delete(control.uuid);
			}
		}

		/**
		 * UIControl의 특정 구성요소의 uuid를 생성
		 * @param control 요소를 포함하는 UIControl
		 * @param partIdentifier 컨트롤 내에서 유일한 식별자
		 */
		public _createPartialUUID(control: controls.UIControl, partIdentifier?: string): string {
			partIdentifier ??= _generateUUID();
			let domUUID: string = this._convertToNodeUUID(control);
			return `${domUUID}/p/${partIdentifier}`;
		}

		/**
		 * UI컨트롤이 글로벌 레이어 노드에 렌더링될 루트 노드의 ID를 얻습니다.
		 * @see _getControlNodeID
		 */
		public _getGlobalControlNodeID(control: controls.UIControl): string {
			let domUUID: string = this._convertToNodeUUID(control);
			return `${domUUID}/g`
		}

		/// private ///
		/**
		 * 노드 UUID 생성 방법을 얻습니다.
		 */
		private _getUUIDGenMethod(): UUIDGenMethod {
			if (this._uuidGenMethod == null) {
				this._uuidGenMethod = this._resolveConfigureUUIDGenMethod();
			}

			return this._uuidGenMethod;
		}

		private _resolveConfigureUUIDGenMethod(): UUIDGenMethod {
			let appConf: core.AppConfig = core.AppConfig.INSTANCE;
			let envJson = appConf.getEnvConfig()?.toJSON();
			if (!envJson) {
				return UUIDGenMethod.SECURE;
			}

			// 명시적으로 uuidGenMethod가 지정된 경우.
			if ("uuidGenMethod" in envJson) {
				let explicitMethod = envJson.uuidGenMethod;
				if (_isOneOfEnumValue(explicitMethod, UUIDGenMethod)) {
					return explicitMethod as UUIDGenMethod;
				} else {
					return UUIDGenMethod.SECURE;
				}
			}
			// 과거 버전 호환성을 위하여 디프리케이트 된 useControlUUIDasHTMLId 가지 지정된 경우.
			else if ("useControlUUIDasHTMLId" in envJson) {
				// 컨트롤 UUID를 사용하도록 지정된 경우.
				if (envJson.useControlUUIDasHTMLId) {
					return UUIDGenMethod.INSECURE;
				}

				// 컨트롤 UUID를 사용하지 않도록 명시 지정된 경우.
				else {
					let methodExp = "htmlIdGenMethod" in envJson
						? envJson.htmlIdGenMethod
						: HtmlIdGenMethod.DEPTH
						;

					switch (methodExp) {
						case HtmlIdGenMethod.DEPTH_SHORT:
							return UUIDGenMethod.DEPTH_SHORT;

						default:
							return UUIDGenMethod.DEPTH;
					}
				}
			}
			// 명시적 지정이 없는 경우
			else {
				return UUIDGenMethod.SECURE;
			}
		}

		/**
		 * 컨트롤의 노드 UUID를 얻습니다.
		 * 
		 * @param control 노드 UUID를 얻을 컨트롤.
		 */
		private _convertToNodeUUID(control: controls.UIControl): node_uuid {
			let domUUID: node_uuid = null;
			let controlUUID: control_uuid = control.uuid;

			switch (this._getUUIDGenMethod()) {
				case UUIDGenMethod.INSECURE:
					domUUID = controlUUID;
					break;

				case UUIDGenMethod.SECURE:
					let origin = parseInt(controlUUID, 36);
					domUUID = ((origin << _UUID_SHIFT) + _UUID_ADDER).toString(36);
					break;

				case UUIDGenMethod.DEPTH:
				case UUIDGenMethod.DEPTH_SHORT:
					if (this._uuidMap.has(controlUUID)) {
						domUUID = this._uuidMap.get(controlUUID);
					}
					else {
						domUUID = this._createNodeUUID(control);
						this._uuidMap.set(controlUUID, domUUID);
					}
			}

			return domUUID;
		}

		/**
		 * 노드 UUID로 부터 매핑된 컨트롤의 UUID를 얻습니다.
		 * 
		 * @param domUUID 컨트롤 UUID와 매핑된 노드 UUID. 파트 UUID 및 글로벌 UUID, 컨트롤 엘리먼트 id 값을 사용하지 마십시오.
		 * @returns 매핑된 컨트롤의 UUID
		 */
		public _convertToControlUUID(domUUID: node_uuid): control_uuid {
			let controlUUID: string = null;

			// FIXME 아래 조건문이 수행되는 케이스를 제거해야 합니다.
			if (domUUID.indexOf(_CONTROL_NODE_ID_PREFIX) === 0) {
				domUUID = domUUID.substr(_CONTROL_NODE_ID_PREFIX.length);
			}

			switch (this._getUUIDGenMethod()) {
				case UUIDGenMethod.INSECURE:
					controlUUID = domUUID;
					break;

				case UUIDGenMethod.SECURE: {
					let encrypted = parseInt(domUUID, 36);

					controlUUID = ((encrypted - _UUID_ADDER) >> _UUID_SHIFT).toString(36);
					break;
				}

				case UUIDGenMethod.DEPTH:
				case UUIDGenMethod.DEPTH_SHORT: {
					controlUUID = this._uuidMap.inversed.get(domUUID);
				}
			}

			return controlUUID;
		}

		/**
		 * 새 노드 UUID를 생성합니다. 
		 * 이 메서드는 {@link _convertToNodeUUID}에서만 호출되어야 합니다.
		 * 
		 * @param control 노드 UUID를 생성할 컨트롤.
		 */
		private _createNodeUUID(control: controls.UIControl): node_uuid {
			switch (this._uuidGenMethod) {
				case UUIDGenMethod.DEPTH_SHORT:
					return _createDepthMinNodeUUID(control, uuid => this._uuidMap.inversed.has(uuid));

				case UUIDGenMethod.DEPTH:
					return _createDepthNodeUUID(control, uuid => this._uuidMap.inversed.has(uuid));

				case UUIDGenMethod.INSECURE:
				case UUIDGenMethod.SECURE:
					throw new exceptions.IllegalStateException();
			}
		}
	}
}