// CSS 트랜지션에 의한 리사이즈를 파악하고 전파하는 구현 입니다.
// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/9842
namespace cpr.events.resize {
	_registerPlatformInitTask(() => {
		window.addEventListener("transitionend", _onTransitionEnd);
	});

	function _isRelatedWithResize(e: TransitionEvent): boolean {
		switch (e.propertyName) {
			case "top":
			case "right":
			case "bottom":
			case "left":
			case "width":
			case "height":
				return true;
			default:
				return false;
		}
	}

	function _onTransitionEnd(e: TransitionEvent): void {
		if (!_isRelatedWithResize(e)) {
			return;
		}

		let node = e.target as HTMLElement;
		let uuid = ufc.NodeUUIDMapper.INSTANCE._findClosestControlUUID(node);
		if (!uuid) {
			return;
		}

		let control = _stream(core.Platform.INSTANCE.getAllRunningAppInstances())
			.map(app => app._lookupDrillDownByUUID(uuid))
			.filterByType(controls.UIControl)
			.head();

		if (!control) {
			return;
		}

		core.DeferredUpdateManager.INSTANCE._deferExec(`resize-of-${uuid}`, () => {
			if (control.disposed === false) {
				control._fireResizeEvent();
			}
		});
	}
}