/// <reference path="./ItemListProvider.ts"/>

namespace cpr.controls.item {
	/**
	 * @private
	 */
	export class TreeItemListProvider<ControlType extends UIControl, ItemType extends TreeItem, ItemSetConfigType extends TreeItemSetConfig>
		extends AbstractItemListProvider<ControlType, ItemType, ItemSetConfigType, TreeItemFilter>
		implements ITreeItemListProvider {

		private _treeItemListView: TreeItemListView;

		constructor(owner: ControlType, itemAdapter: ItemListAdapter<ItemType>) {
			super(owner);
			let treeItemList = new TreeItemList(owner, this.getItemDataSource(), itemAdapter);
			this._treeItemListView = new TreeItemListView(owner, treeItemList, this._getItemFilter());
		}
		protected _createItemFilter(): TreeItemFilter {
			return new TreeItemFilter() as any;
		}
		public getTreeItemList(): TreeItemList {
			return this._treeItemListView.itemList;
		}
		public getTreeItemListView(): TreeItemListView {
			return this._treeItemListView;
		}
		public getActiveItemListView(): IItemListView<ItemType> {
			return this._treeItemListView as unknown as IItemListView<ItemType>;
		}
		public getActiveItemList(): IItemList<ItemType> {
			return this._treeItemListView.itemList as unknown as IItemList<ItemType>;
		}

		public dispose(): void {
			this._treeItemListView?.dispose();
			this._treeItemListView = null;
			super.dispose();
		}
	}
}