	/**
	 * @param value 
	 * @returns 
	 * @private
	 */
	export function _isPixelValue(value: string) {
		switch (typeof value) {
			case "string": return value.match(/^(-?(\d+|\.\d+|\d+\.\d+))\s*px$/g);
			default: return false;
		}
	}

