namespace cpr.core {

	/**
	 * @private
	 */
	export enum Policy {
		DATA_DEFAULT_VALUE_IS_NULL = "i10919"
	}

	/**
	 * Policy 설정을 위한 인터페이스
	 */
	export interface PolicyOptions {
		/**
		 * [정책 i10919] 데이터 객체의 기본값 설정 정책<br>
		 * <br>
		 * 데이터 객체의 기본값을 빈 문자열("") 대신 null로 관리하기 위한 설정입니다.<br>
		 * 반환값이 <b>true</b>일 경우 <b>null</b>을 기본값으로 사용하며, 미설정 시 빈 문자열("")이 기본값으로 유지됩니다.<br>
		 * <br>
		 * <b>[반환 값]</b><br>
		 * {boolean} 데이터셋의 기본값을 null로 설정할지 여부. (true: null, false: "")
		 * @example
		 * 데이터셋의 기본 값을 빈 문자열 대신 null로 설정하는 예제
		 * cpr.core.PolicyManager.INSTANCE.configure({
		 *     "i10919": function() {
		 *          return true;
		 *     }
		 * });
		 */
		"i10919"?: () => boolean;
	}
}