namespace cpr.utils {

	/**
	 * DateRange에서 날짜 범위의 기준 설정하는 옵션 값
	 */
	export enum DateRangeTarget {
		/**
		 * "year"
		 */
		year = "year",
		/**
		 * "month"
		 */
		month = "month",
		/**
		 * "day"
		 */
		day = "day"
	}

	/**
	 * 날짜의 범위에서 계산
	 */
	export class DateRange {

		private _startDate: moment.Moment;
		private _endDate: moment.Moment;

		constructor(startDate: Date, endDate: Date, isMultiple: boolean = false) {
			this._startDate = moment(startDate);
			this._endDate = moment(endDate);

			if (isMultiple) {
				if (this._startDate.isAfter(this._endDate)) {
					let temp = this._startDate;
					this._startDate = this._endDate;
					this._endDate = temp;
				}
			}
		}

		/**
		 * 시작 날짜 객체를 반환합니다.
		 */
		get start(): Date {
			return this._startDate.toDate();
		}

		/**
		 * 마지막 날짜 객체를 반환합니다.
		 */
		get end(): Date {
			return this._endDate.toDate();
		}

		/**
		 * 객체를 복제합니다.
		 */
		public clone(): DateRange {
			return new DateRange(this._startDate.clone() as any, this._endDate.clone() as any);
		}

		private _getFormattedDate(format: string = "YYYY-MM-DD", type: string = "days"): string[] {
			let pos = this._startDate.clone();
			let result = [];
			if ((pos.isValid() && this._endDate.isValid()) == false) {
				return result;
			}
			while (pos.isAfter(this._endDate) == false) {
				result.push(pos.format(format));
				pos.add(1, type);
			}
			return result;
		}

		private _getDate(type: string = "days"): Date[] {
			let pos = this._startDate.clone();
			let result = [];
			while (pos.isAfter(this._endDate) == false) {
				result.push(pos.toDate());
				pos.add(1, type);
			}
			return result;
		}

		/**
		 * range 안에 날짜가 포함되는지 여부를 반환합니다.<br>
		 * year인 경우 범위에 날짜의 년도가 포함되는지 확인합니다.<br>
		 * month인 경우 범위에 날짜의 년,월이 포함되는지 확인합니다.<br>
		 * day인 경우 범위에 날짜의 년,월,일이 포합되는지 확인합니다.
		 * @param date 날짜 객체.
		 * @param target "year","month","day"중에 하나만 선택하여 포함여부 방법 설정.
		 */
		public contains(date: Date, target?: DateRangeTarget): boolean
		public contains(date: any, target: DateRangeTarget = DateRangeTarget.day): boolean {
			return this._startDate.isSameOrBefore(date, target) && this._endDate.isSameOrAfter(date, target);
		}

		/**
		 * 시작 날짜 여부를 반환합니다.<br>
		 * year인 경우 범위의 시작 날짜가 년도와 같은지 비교합니다.<br>
		 * month인 경우 범위의 시작 날짜가 년,월이 같은지 비교합니다.<br>
		 * day인 경우 범위의 시작 날짜가 년,월,일이 같은지 비교합니다.
		 * @param date 
		 * @param target optional ["year","month","day"] 중에 하나만 선택하여 비교 방법 설정.
		 */
		public isStart(date: Date, target?: DateRangeTarget): boolean
		public isStart(date: moment.Moment | string | number | Date, target: DateRangeTarget = DateRangeTarget.day): boolean {
			return this._startDate.isSame(date, target);
		}

		/**
		 * 입력한 날짜가 범위의 마지막 날짜인지 여부를 반환합니다.<br>
		 * year인 경우 범위의 마지막 날짜가 년도와 같은지 비교합니다.<br>
		 * month인 경우 범위의 마지막 날짜가 년,월이 같은지 비교합니다.<br>
		 * day인 경우 범위의 마지막 날짜가 년,월,일이 같은지 비교합니다.
		 * @param date 
		 * @param target optional ["year","month","day"] 중에 하나만 선택하여 비교 방법 설정.
		 */
		public isEnd(date: Date, target?: DateRangeTarget): boolean
		public isEnd(date: moment.Moment | string | number | Date, target: DateRangeTarget = DateRangeTarget.day): boolean {
			return this._endDate.isSame(date, target);
		}
		/**
		 * 시작날짜와 마지막 날짜 사이의 길이를 반환합니다.<br>
		 * year인 경우 start와 end를 millisecond로 차이를 계산하여 년도를 반환<br>
		 * month인 경우 start와 end를 millisecond로 차이를 계산하여 월을 반환<br>
		 * day인 경우 start와 end를 millisecond로 차이를 계산하여 일을 반환
		 * @param target 길이 계산 형식.['year','month','day']
		 */
		public length(target: DateRangeTarget = DateRangeTarget.day): number {
			let convertTarget = this._convertDateRangeTarget(target);
			return Math.abs(this._startDate.diff(this._endDate, convertTarget)) + 1
		}

		private _convertDateRangeTarget(target: DateRangeTarget): string {
			switch (target) {
				case "year": {
					return "years";
				}
				case "month": {
					return "months";
				}
				case "day": {
					return "days";
				}
			}
			return null;
		}

		/**
		 * 범위 안에 날짜 문자열을 반환합니다. type에 따라 반환되는 날짜가 개수가 달라집니다.
		 * type이 "months"인 경우 ["2018-08-01","2018-09-01", ...]<br>
		 * type이 "days"인 경우 ["2018-08-01","2018-08-02", ...]<br>
		 * type이 "years"인 경우 ["2018-08-01","2019-08-01", ...]<br>
		 * @param format 반환하는 문자열의 포맷을 설정합니다.
		 * @param target "days", "months", "years"
		 */
		public extractDateString(format: string = "YYYY-MM-DD", target: DateRangeTarget = DateRangeTarget.day): string[] {
			let convertTarget = this._convertDateRangeTarget(target);
			return this._getFormattedDate(format, convertTarget);
		}

		/**
		 * 범위 안에 Date 객체를 반환합니다. type에 따라 반환되는 날짜 개수가 달라집니다.
		 * type이 "months"인 경우 [Date("2018-08-01"),Date("2018-09-01"), ...]<br>
		 * type이 "days"인 경우 [Date("2018-08-01"),Date("2018-08-02"), ...]<br>
		 * type이 "years"인 경우 [Date("2018-08-01"),Date("2019-08-01"), ...]<br>
		 * @param target "days","months","years"
		 */
		public extractDate(target: DateRangeTarget = DateRangeTarget.day): Date[] {
			let convertTarget = this._convertDateRangeTarget(target);
			return this._getDate(convertTarget);
		}

	}
}