

namespace cpr.controls.provider {

	/**
	 * @private
	 */
	export abstract class DataProvider<ControlType extends UIControl & ValueBindable> implements cpr.core.UniversallyUniqueIdentifier {
		private _owner: ControlType
		private _uuid: string = null;

		constructor(owner: ControlType) {
			this._owner = owner
			this._uuid = _generateUUID();
		}

		get owner(): ControlType {
			return this._owner
		}

		public get uuid(): string {
			return this._uuid;
		}

	}

}