/// <reference path="../utils/Logger.ts"/>

namespace cpr.bind {
	let log = utils.Logger.forTopic("bind")._createBindedLoggerFunction({
		updator: it => log = it
	});

	/**
	 * 바인딩 제약사항 기술 객체
	 * @nonapi
	 */
	export interface BindRestriction {
		/** 데이터컬럼 바인딩 허용 여부, 생략시 true */
		allowsDataColumnBind?: boolean

		/** 데이터맵 바인딩 허용 여부, 생략시 true */
		allowsDataMapBind?: boolean

		/** 데이터셋 바인딩 허용 여부, 생략시 true */
		allowsDataSetBind?: boolean

		/** 앱속성 바인딩 허용 여부, 생략시 true */
		allowsAppPropertyBind?: boolean

		/** 언어 바인딩 허용 여부, 생략시 true */
		allowsLanguageBind?: boolean

		/** 표현식 바인딩 허용 여부, 생략시 true */
		allowsExpressionBind?: boolean

		/** 사전 정의된 바인딩 가능 속성 이름 대신 모든 유형의 속성명에 대한 바인딩을 구성할 수 있도록 허용하는지 여부. 생략시 false */
		allowsAnyProperty?: boolean
	}

	/** 바인딩 기본 제약사항 */
	const _DEFAULT_BIND_PERMISSION: BindRestriction = {
		allowsDataColumnBind: true,
		allowsDataMapBind: true,
		allowsDataSetBind: true,
		allowsAppPropertyBind: true,
		allowsLanguageBind: true,
		allowsExpressionBind: true,
		allowsAnyProperty: false
	};

	/**
	 * 바인딩된 속성들을 관리하는 매니저 입니다.
	 * 
	 * @nonapi
	 */
	export class BindableProperties {
		/** 속성들의 소유주 */
		private _owner: cpr.bind.BindablePropertiesOwner;

		/** 바인딩 가능한 속성 맵. */
		private _properties: CMap<string, BindableProperty> = _createMap();

		/** 바인딩 권한 기술자 */
		private _permissions: BindRestriction;

		/** 무한 반복을 막기위해 속성이 지정되고 있는 도중의 속성명들을 기술하는 락 */
		private _locks: string[] = [];

		/**
		 * @param owner 속성들의 소유자.
		 * @param permissions 바인딩 제약 사항.
		 */
		constructor(owner: cpr.bind.BindablePropertiesOwner, permissions?: BindRestriction) {
			this._owner = owner;
			this._permissions = _mergeObject(_DEFAULT_BIND_PERMISSION, permissions);
		}

		public get owner(): BindablePropertiesOwner {
			return this._owner;
		}

		/**
		 * 바인딩 가능한 속성을 추가합니다.
		 * @param property 추가할 속성.
		 * @param initialValue 초기 값.
		 */
		public add(property: string, initialValue: any): IBindedPropertyFactory {
			if (utils.Util.isNullOrEmpty(property)) {
				throw new cpr.exceptions.IllegalArgumentException();
			}

			let bindedProperty = this._properties.get(property);
			if (bindedProperty) {
				throw new cpr.exceptions.IllegalArgumentException(`${property}는 이미 바인딩 가능한 속성으로 정의되어있습니다.`);
			} else {
				this._properties.set(property, new BindableProperty(this, property, initialValue));
			}
			return new BindedPropertyFactoryImpl(this._properties.get(property));
		}

		/**
		 * 바인딩 가능한 속성인지 확인합니다.
		 * @param name 확인할 속성.
		 */
		public isBindable(name: string): boolean {
			if (utils.Util.isNullOrEmpty(name) || typeof name != "string") {
				return false;
			}

			return this._permissions.allowsAnyProperty || this._properties.has(name);
		}

		/**
		 * 바인딩된 모든 속성들의 값을 얻습니다.
		 * @return 바인딩된 속성들의 키/값 JSON 객체.
		 */
		public resolveAll(): { [key: string]: any } {
			let result: { [key: string]: any } = {};
			this._properties.forEach((value, key) => {
				result[key] = this.get(key);
			});
			return result;
		}

		/**
		 * 주어진 속성이 바인딩 되어있는지 여부를 얻습니다.
		 * @param name 바인딩 여부를 확인할 속성명.
		 * @returns 바인딩 여부.
		 */
		public isBinded(name: string): boolean {
			return this._properties.get(name)?.getDelegate() != null;
		}

		/**
		 * 속성값을 얻습니다. 바인딩 정보중 활성화된 델리게이트를 찾아 위임됩니다.
		 * @param name 얻을 속성 값.
		 * @return string|number|object 속성의 값
		 */
		public get(name: string): any {
			if (!this.isBindable(name)) {
				throw new cpr.exceptions.IllegalArgumentException();
			}
			return this._properties.get(name).get();
		}

		/**
		 * 속성 값을 지정합니다. 바인딩 정보중, 활성화된 델리게이트를 통해 위임됩니다.
		 * 값이 변경된 경우 소유자의 valueWillChange 및 valueDidChage가 호출 됩니다.
		 * 
		 * @param name 값을 지정할 속성.
		 * @param newValue string|number|object 새로운 값.
		 * @param context 속성세트 소유자의 _valueDidChange() 의 마지막 인자로 전달될 추가 정보.
		 */
		public set(name: string, newValue: any, context?: any): boolean {
			if (!this.isBindable(name)) {
				throw new cpr.exceptions.IllegalArgumentException();
			}

			if (this._locks.indexOf(name) !== -1) {
				log(`이미 %j의 ${name} 속성을 지정하는 중이어서 기각합니다.`, this._owner);
				return;
			}
			this._locks.push(name);

			utils.tryCatch({
				do: () => {
					let oldValue = this.get(name);
					//"" == 0 비교를 할경우 true로 되어 연산자 변경.
					if (oldValue === newValue) {
						return false;
					}

					this._properties.get(name).set(newValue);

					if (this._owner && this._owner._valueDidChange) {
						this._owner._valueDidChange(name, oldValue, newValue, context);
					}
				},
				finally: () => {
					let index = this._locks.indexOf(name);
					this._locks.splice(index, 1);
				}
			})


			return true;
		}

		/**
		 * 특정 속성에 대해 바인딩 정보를 담은 BindableProperty 객체를 얻습니다.
		 * @param name 정보를 얻을 속성 명.
		 */
		public getBindableProperty(name: string): BindableProperty {
			return this._properties.get(name);
		}

		/**
		 * 특정 속성에 대해 바인딩 정보를 담은 BindableProperty 객체를 얻습니다.
		 * 정의되지 않은 경우, 새로 작성합니다.
		 * 
		 * @param name 정보를 얻을 속성 명.
		 */
		public ensureBindableProperty(name: string): BindableProperty {
			if (!this._properties.has(name)) {
				this.add(name, null);
			}
			return this._properties.get(name);
		}

		/**
		 * 주어진 속성명에 대해 바인드 팩토리를 얻습니다.
		 * @param name 바인드 팩토리를 얻을 속성 명.
		 */
		public bind(name: string): BindFactory {
			return new BindFactory(this, name, this._permissions);
		}

		/**
		 * 바인딩을 해제합니다.
		 * @param name 바인딩을 해제할 속성명.
		 */
		public unbind(name: string): void {
			if (this.isBinded(name) == false) {
				return;
			}

			this._properties.get(name).removeDelegate();
		}

		/**
		 * 바인딩을 해제하고, 바인딩 가능 속성을 일반 속성으로 전환합니다.
		 * @param name 바인딩을 해제하고 일반 속성으로 전환할 속성.
		 */
		public destroy(name: string): void {
			if (this.isBinded(name)) {
				this._properties.get(name).removeDelegate();
			}
			this._properties.delete(name);
		}

		public dispose(): void {
			this._properties.clear();
		}

		public internalBind(name: string): InternalBindFactory {
			if (!this.isBindable(name)) {
				throw new cpr.exceptions.IllegalArgumentException();
			}
			return new InternalBindFactory(this, name);
		}

		/**
		 * 바인딩 가능한 모든 속성 명을 얻습니다.
		 */
		public _getAllBindablePropertyNames(): string[] {
			return CMap._keyStream(this._properties).collect();
		}
	}
}