///<reference path="./AbstractCalendar.ts" />

namespace cpr.controls.calendar {
	/**
	 * 월 기준의 달력.
	 */
	export class MonthCalendar extends AbstractCalendar {

		constructor(owner: any, calendar: AbstractCalendar = null, option: { focusable?: boolean, useHeaderFormat?: boolean } = {}) {
			super(owner);
			this._setFocusable(option.focusable);
			option = _defaults(option, {
				useHeaderFormat: true, focusable: false
			});
			this._useHeaderFormat = option.useHeaderFormat;
			if (calendar) {
				this._setProperties(calendar._getProperties());
			} else {
				this._resetFocus();
			}
		}

		protected _getType() {
			return CalendarType.yearmonth;
		}

		public _getFocusEntries() {
			let result = [];
			if (this.headerVisible) {
				let currentMoment = this._getDisplayCurrent();
				let activeEntry = this._getActiveFocusEntry();
				this.headerButtons.forEach((each) => {
					switch (each) {
						case CalendarHeaderButtonType.prev:
							if (currentMoment.isSameOrBefore(this.minDate, "year") == false || activeEntry == this._prevFocusEntry)
								result.push(this._prevFocusEntry);
							break;
						case CalendarHeaderButtonType.title:
							if (this._isTypeChangeable()) {
								result.push(this._titleFocusEntry);
							}
							break;
						case CalendarHeaderButtonType.next:
							if (currentMoment.isSameOrAfter(this.maxDate, "year") == false || activeEntry == this._nextFocusEntry)
								result.push(this._nextFocusEntry);
							break;
					}
				})
			}
			result.push(this._currentFocusEntry);
			// 화면에 표시된 날짜를 기준으로 판정한다. release-test-project#11154
			let renderedDefaultDate = this._getRenderedDefaultDate();
			let footerMm = moment(renderedDefaultDate);
			let footerDisabled = footerMm.isSameOrAfter(this.maxDate) || footerMm.isSameOrBefore(this.minDate) || this._checkDisabledDateExp(renderedDefaultDate)
			if (this.footerVisible && footerDisabled == false) {
				result.push(this._footerFocusEntry);
			}
			return result;
		}

		/** 
		 * 키보드 Tab키로 이동할 수 있는 영역들을 반환합니다.
		 **/
		protected _getTabFocusList(): CalendarTabFocus[] {
			let currentMoment = this._getDisplayCurrent();
			let tabFocusList: any[] = [CalendarTabFocus.body, CalendarTabFocus.footer];
			if (this._hasHeaderTabFocus()) {
				tabFocusList = this.headerButtons.concat(tabFocusList);
				if (tabFocusList.indexOf(CalendarTabFocus.prev) > -1 && currentMoment.isSameOrBefore(this.minDate, "year")) {
					tabFocusList.splice(tabFocusList.indexOf(CalendarTabFocus.prev), 1);
				}
				if (tabFocusList.indexOf(CalendarTabFocus.next) > -1 && currentMoment.isSameOrAfter(this.maxDate, "year")) {
					tabFocusList.splice(tabFocusList.indexOf(CalendarTabFocus.next), 1);
				}
				// 월 캘린더에서는 nextYear, prevYear 버튼을 지원하지 않으므로 제거
				if (tabFocusList.indexOf(CalendarHeaderButtonType.nextYear) > -1) {
					tabFocusList.splice(tabFocusList.indexOf(CalendarHeaderButtonType.nextYear), 1);
				}
				if (tabFocusList.indexOf(CalendarHeaderButtonType.prevYear) > -1) {
					tabFocusList.splice(tabFocusList.indexOf(CalendarHeaderButtonType.prevYear), 1);
				}
				// 타입 변경 불가 시 title 버튼 제거
				if (tabFocusList.indexOf(CalendarHeaderButtonType.title) > -1 && !this._isTypeChangeable()) {
					tabFocusList.splice(tabFocusList.indexOf(CalendarHeaderButtonType.title), 1);
				}

			}
			// 화면에 표시된 날짜를 기준으로 판정한다. release-test-project#11154
			let renderedDefaultDate = this._getRenderedDefaultDate();
			let footerMm = moment(renderedDefaultDate);
			let footerDisabled = footerMm.isSameOrAfter(this.maxDate) || footerMm.isSameOrBefore(this.minDate) || this._checkDisabledDateExp(renderedDefaultDate)
			if (this.footerVisible == false || footerDisabled) {
				tabFocusList.splice(tabFocusList.indexOf(CalendarTabFocus.footer));
			}

			return tabFocusList;
		};

		protected _getDateElement(target: HTMLElement, root: HTMLElement): HTMLElement {
			let domTraverser = ufc._traverseFromElement(target);
			domTraverser = domTraverser._closest(".cl-calendar-content-month", root);
			return domTraverser ? domTraverser._getElement() : null;
		}

		protected _createBodyContents() {

			let tablefield: cpr.ufc.ControlShape = {
				tag: "div",
				attr: {},
				classNames: [],
				styler: "content",
				style: {},
				children: this._createTableBody()
			}
			let templateColumns = ["1fr", "1fr", "1fr", "1fr"];
			let templateRows = ["1fr", "1fr", "1fr"];
			layouts.GridCSSBuilder._forLayout()._withTemplateColumns(templateColumns)._withTemplateRows(templateRows)._commit(tablefield.style);
			return tablefield;
		}

		protected _createHeaderContents(): cpr.ufc.ControlShape[] {
			let fields: cpr.ufc.ControlShape[] = [];
			let mm = moment(this._getDisplayCurrent());
			let tabFocus = this._getTabFocus();
			this.headerButtons.forEach((each: CalendarHeaderButtonType) => {
				switch (each) {
					case CalendarHeaderButtonType.prev: {
						let prevButton = this._createPrevButton();
						cpr.ufc.ShapeUtil._setAriaLabelAttr(prevButton.attr, cpr.I18N.INSTANCE.message(core.PlatformTerms.CALENDAR_DAY_BEFORE));
						if (mm.isSameOrBefore(this.minDate, "year")) {
							prevButton.classNames.push(ufc.Classes.DISABLED);
						} else if (tabFocus == CalendarTabFocus.prev) {
							this._setActiveElementId(this._getElementId("left-btn"));
							prevButton.classNames.push(ufc.Classes.HOVER);
						}
						fields.push(prevButton);
						layouts.GridCSSBuilder._forCell()._withColumnStart(fields.length)._withRowStart(1)._withVerticalAlign(layouts.GridCellAlign.center)._commit(prevButton.style);
						break;
					}
					case CalendarHeaderButtonType.title: {
						let titleButton = this._createTitleButton();
						let isTypeChangeable = this._isTypeChangeable();
						if (tabFocus == CalendarTabFocus.title && isTypeChangeable) {
							this._setActiveElementId(this._getElementId("center-btn"));
							titleButton.classNames.push(ufc.Classes.HOVER);
						} else if (isTypeChangeable == false) {
							titleButton.classNames.push(ufc.Classes.DISABLED);
						}
						fields.push(titleButton);
						layouts.GridCSSBuilder._forCell()._withColumnStart(fields.length)._withRowStart(1)._withVerticalAlign(layouts.GridCellAlign.center)._commit(titleButton.style);
						break;
					}
					case CalendarHeaderButtonType.next: {
						let nextButton = this._createNextButton();
						cpr.ufc.ShapeUtil._setAriaLabelAttr(nextButton.attr, cpr.I18N.INSTANCE.message(core.PlatformTerms.CALENDAR_DAY_AFTER));
						if (mm.isSameOrAfter(this.maxDate, "year")) {
							nextButton.classNames.push(ufc.Classes.DISABLED);
						} else if (tabFocus == CalendarTabFocus.next) {
							this._setActiveElementId(this._getElementId("right-btn"));
							nextButton.classNames.push(ufc.Classes.HOVER);
						}
						fields.push(nextButton);
						layouts.GridCSSBuilder._forCell()._withColumnStart(fields.length)._withRowStart(1)._withVerticalAlign(layouts.GridCellAlign.center)._commit(nextButton.style);
						break;
					}
				}
			});
			return fields;
		}

		private _getDisplayMonths(viewDate: moment.Moment): string {
			let months = this._getMonthNames();
			let result: string;
			let locale = this._getMomentLocale();
			switch (months) {
				case CalendarMonthNameType.normal:
					result = viewDate.locale(locale).format("MMMM");
					break;
				case CalendarMonthNameType.short:
					result = viewDate.locale(locale).format("MMM");
					break;
				case CalendarMonthNameType.min:
				default:
					result = viewDate.locale(locale).format("M");
					break;
			}
			return result;

		}

		private _createTableBody(): cpr.ufc.ElementShape[] {

			let table: cpr.ufc.ElementShape[] = [];
			let tableRow: cpr.ufc.ElementShape[] = [];

			let viewMonth: number = 0;
			let displayCurrent = this._getDisplayCurrent();
			let renderedDefaultDate = this._getRenderedDefaultDate();
			let locale = this._getMomentLocale();
			let mm: moment.Moment = moment(displayCurrent).locale(locale).startOf('month');

			let values = this._getValues();
			let dateRange: utils.DateRange;
			let isEnabled = this.owner.enabled;
			if (CalendarSelectionType.single == this.selectionType) {
				if (values.length > 1) values.splice(1, Number.MAX_VALUE);//1개의 값만 표시되도록 나머지 값은 제거.
			} else if (this._isRangeSelection() && values.length > 1) {
				values.splice(2, Number.MAX_VALUE);//2개의 값만 표시되도록 나머지 값은 제거.
				dateRange = new utils.DateRange(moment(values[0], this._getFormat(), locale) as any, moment(values[1], this._getFormat(), locale) as any);
			}

			let valueDates = [];
			for (let each of values) {
				valueDates.push(moment(each, this._getFormat(), locale).format("YYYYMM"));
			}

			for (let rowIdx: number = 1; rowIdx <= 3; rowIdx++) {

				for (let colIdx: number = 1; colIdx <= 4; colIdx++) {
					mm.month(viewMonth);
					let text: ufc.ElementShape = {
						tag: "div",
						classNames: [ufc.Classes.TEXT],
						children: ufc.StyledString._asShape(this._getDisplayDateText(mm.toDate())),
						style: {
							position: "relative"
						}
					}

					let textCellBuilder = layouts.GridCSSBuilder._forCell()._withColumnStart(1)._withRowStart(1);
					this._setDatePosition(text.style, textCellBuilder);
					textCellBuilder._commit(text.style);

					let dateDetail: ufc.ControlShape = {
						tag: "div",
						classNames: [],
						style: {
							height: "100%"
						},
						children: [text]
					}
					layouts.GridCSSBuilder._forLayout()._withTemplateRows("1fr")._withTemplateColumns("1fr")._commit(dateDetail.style);
					let calendarDate = new controls.CalendarDate();
					calendarDate._init(this.owner, mm.toDate());
					calendarDate.text = this._getDateText(mm.toDate());
					calendarDate.currentCalendarType = this._getType();
					let td: cpr.ufc.ControlShape = {
						tag: "div",
						classNames: [this._getDateClass()],
						attr: {
							role: "button",
							id: this._getElementId("month-" + viewMonth),
							"aria-label": mm.format("MMMM, YYYY"),
							"data-value": (viewMonth + 1) + ""
						},
						styler: "date",
						bindContext: new bind.CalendarDateContext(calendarDate, this.owner),
						style: {
							position: "relative"
						},
						children: [dateDetail]
					}

					if (rowIdx == 1) {
						td.classNames.push(ufc.Classes.FIRST_ROW);
					} else if (rowIdx == 3) {
						td.classNames.push(ufc.Classes.LAST_ROW);
					}
					td.classNames.push(rowIdx % 2 == 1 ? ufc.Classes.ODD_ROW : ufc.Classes.EVEN_ROW);

					if (colIdx == 1) {
						td.classNames.push(ufc.Classes.FIRST_COLUMN);
					} else if (colIdx == 4) {
						td.classNames.push(ufc.Classes.LAST_COLUMN);
					}
					td.classNames.push(colIdx % 2 == 1 ? ufc.Classes.ODD_COLUMN : ufc.Classes.EVEN_COLUMN);

					tableRow.push(td);
					layouts.GridCSSBuilder._forCell()._withRowStart(rowIdx)._withColumnStart(tableRow.length)._commit(td.style);

					let formattedDate = mm.format("YYYYMM");
					let findIndex = valueDates.indexOf(formattedDate);
					if (findIndex > -1) {
						td.classNames.push(ufc.Classes.SELECTED);
						td.attr["aria-label"] = cpr.I18N.INSTANCE.message(core.PlatformTerms.SELECTED) + ": " + mm.format("MMMM, YYYY")
					} else if (dateRange && dateRange.contains(mm as any)) {
						td.classNames.push("cl-range-selected");
					}
					if (displayCurrent.year() == renderedDefaultDate.getFullYear() && viewMonth == (renderedDefaultDate.getMonth())) {
						td.classNames.push("cl-calendar-defaultdate");
					}

					// range에 시작과 끝의 퍼블리싱 포인트
					if (this._isRangeSelection() && valueDates.length > 1) {
						if (dateRange.isStart(mm.toDate(), utils.DateRangeTarget.month)) {
							td.classNames.push("cl-range-start");
						}
						if (dateRange.isEnd(mm.toDate(), utils.DateRangeTarget.month)) {
							td.classNames.push("cl-range-end");
						}
					}
					if (mm.isSame(moment(), "month")) {
						td.attr["aria-current"] = "date";
					}
					let isCurrentDate = viewMonth == (displayCurrent.month());
					this._setFocusableElement(td, isCurrentDate ? "currentButton" : "data" + td.attr["data-value"]);
					if (isCurrentDate && this._getCurrent()) {
						td.attr["data-current"] = "true";

						if (this._getTabFocus() == CalendarTabFocus.body) {
							this._setActiveElementId(this._getElementId("month-" + viewMonth));
							if (this.showCurrent) {
								td.classNames.push("cl-calendar-current");
							}
						}
					}
					let isDisabledDate = this._containsRangeDate(mm, "month") == false || (this._isSelectable() && this._checkDisabledDateExp(mm.toDate()));
					if (isDisabledDate) {
						td.classNames.push(ufc.Classes.DISABLED);
					}
					cpr.ufc.ShapeUtil._setAriaDisabled(td, !isDisabledDate && isEnabled && !this.owner.readOnly);
					viewMonth++;
				}
				table = table.concat(tableRow);
				tableRow = [];
			}

			return table;
		}

		protected _getDateClass() {
			return "cl-calendar-content-month";
		}

		protected _getDateText(date: Date) {
			return this._getDisplayMonths(moment(date));
		}

		protected _getDefaultHeaderFormat() {
			return "YYYY";
		}

		protected _getDateRangeValues(dateRange: utils.DateRange) {
			return dateRange.extractDateString(this._getFormat(), utils.DateRangeTarget.month).join(this._getDelimiter());
		}

		protected _findClosestEnabledDate(mm: moment.Moment, unitOfTime: string, forward: boolean, moveCount: number, currentLoopCount: number) {
			let clone = mm.clone();
			if (currentLoopCount == 365) {
				return null;
			}
			// week, month단위로 변경 시 활성화된 날짜가 아닌 경우 활성화된 마지막 날짜 또는 첫날짜로 이동
			if (clone.isSameOrBefore(this.minDate)) {
				forward = true;
			}
			if (clone.isSameOrAfter(this.maxDate)) {
				forward = false;
			}
			return this._navigateDate(mm, unitOfTime, forward, moveCount, currentLoopCount);
		}

		protected _getTargetObject(targetElement: HTMLElement, rootElement: HTMLElement, storedTargetObject: events.CalendarTargetObject): events.CalendarTargetObject {
			let targetObject: events.CalendarTargetObject = { relativeTargetName: "" };
			if (targetElement.classList.contains("cl-calendar-header-prev")) {
				targetObject.relativeTargetName = "prev";
			} else if (targetElement.classList.contains("cl-calendar-header-next")) {
				targetObject.relativeTargetName = "next";
			} else if (targetElement.classList.contains("cl-calendar-header-text")) {
				targetObject.relativeTargetName = "title";
			} else if (targetElement.classList.contains("cl-calendar-footer-text")) {
				targetObject.relativeTargetName = "footer";
			} else if (storedTargetObject) {
				return storedTargetObject;
			} else if (this._getDateElement(targetElement, rootElement)) {
				targetObject.relativeTargetName = "date";
			}
			return targetObject;
		}

		protected _keyNavigation(e: KeyboardEvent, newDate: moment.Moment) {
			let navigateDate = null;
			switch (e.keyCode) {
				case events.KeyCode.LEFT:
					navigateDate = this._navigateDate(newDate, 'months', false);
					break;
				case events.KeyCode.RIGHT:
					navigateDate = this._navigateDate(newDate, 'months', true);
					break;
				case events.KeyCode.UP:
					navigateDate = this._navigateDate(newDate, 'months', false, 4);
					break;
				case events.KeyCode.DOWN:
					navigateDate = this._navigateDate(newDate, 'months', true, 4);
					break;
				case events.KeyCode.PAGEDOWN:
					navigateDate = this._navigateDate(newDate, 'months', true, 12);
					break;
				case events.KeyCode.PAGEUP:
					navigateDate = this._navigateDate(newDate, 'months', false, 12);
					break;
			}
			if (navigateDate) {
				newDate.set({ year: navigateDate.year(), month: navigateDate.month(), date: navigateDate.date() })
			}
		}

		protected _next(date: moment.Moment) {
			date.add(1, "years");
		}

		protected _prev(date: moment.Moment) {
			date.subtract(1, "years");
		}

		protected _setCurrentBySelectedValue(num: number) {
			if (!this._getCurrent()) {
				this._setCurrent(this._getDisplayCurrent());
			}
			this._getCurrent().month(num - 1);
		}

		protected _containsMinMaxDate(date: moment.Moment): boolean {
			return this._containsRangeDate(date, "month");
		}

		protected _isNavigate(date: moment.Moment): boolean {
			let displayCurrent = this._getDisplayCurrent();
			return displayCurrent.isAfter(date, "year") || displayCurrent.isBefore(date, "year");
		}

	} //MonthCalendar
} // namespace