		/**
		 * 확대 값을 반환합니다.
		 */
		public getZoom(): number {
			return this._zoom;
		}
		/**
		 * 0.8~1.5의 확대 값을 설정할 수 있습니다. 
		 * 페이지에 줌 기능이 필요한 경우에만 사용하시기 바랍니다.
		 * IE, Edge Legacy는 2024 zoom공식지원 브라우저에 해당되지 않아 정상적으로 지원되지 않습니다.
		 * @param scale 0.8-1.5
		 */
		public setZoom(scale: number) {
			if (typeof scale != "number") {
				throw new exceptions.IllegalArgumentException();
			}
			scale = cpr.utils.Util.clamp(scale, 0.8, 1.5);
			if (this._zoom == scale) {
				return;
			}
			this._zoom = scale;
			document.body.style.zoom = this._zoom.toString();// IE는 zoom이 공식 지원이 아니기 때문에 글로벌 영역(absolute,fixed)이 적용되지 않으나 scale을 설정하면 적용됨.

			if (this._zoom != 1) {
				document.body.classList.add("cl-zoom");

			} else {
				document.body.classList.remove("cl-zoom");
			}
			this._setZoomStyle(this._createZoomCSS());
			controls.internal.ScrollbarUtil._invalidate();
			cpr.events.EventBus.INSTANCE._resize(document.body);
		}

		private _createZoomCSS(): string {
			let result = "";
			if (_isIE()) {
				let percentage = 100 / this._zoom;
				let bodyZoomCSSText = []
				let negatizeZoom = 1 / this._zoom;
				if (this._zoom > 1) {
					bodyZoomCSSText.push(`width: ${percentage}%;`);
					bodyZoomCSSText.push(`height: ${percentage}%;`);
					bodyZoomCSSText.push(`min-height: ${percentage}%;`);
				}
				result = `body.cl-zoom .cl-navigationbar [style*='position: fixed'], body.cl-zoom .cl-aside > [style*='position: fixed'], body.cl-zoom .cl-global-aside > [style*='position: fixed'] {
	zoom: ${this._zoom.toString()};
}
body.cl-zoom [style*='position: fixed'][style*='bottom: 0px'][style*='right: 0px']{
	width: ${negatizeZoom * 100}%;
	height: ${negatizeZoom * 100}%;
}
body.cl-zoom {
	transform: scale(1);
	${bodyZoomCSSText.join("\n\t")}
}`
			}
			return result;
		}
		private _setZoomStyle(cssText: string) {
			if (!cssText) {
				return;
			}
			if (!this._zoomStyleNode) {
				this._zoomStyleNode = document.createElement("style");
				this._zoomStyleNode.setAttribute("data-role", "zoom-style");
			}
			this._zoomStyleNode.innerHTML = cssText;
			if (!this._zoomStyleNode.parentNode) {
				document.head.appendChild(this._zoomStyleNode);
			}
		}

