		/**
		 * 사용자 정의 쿼리 : 앱UUID[]
		 */
		private _appQueryUsageMap: { [userQuery: string]: string[] } = {};

		private _getAppsForMediaQuery(userQuery: string, ensure = false): string[] {
			let appUUIDs: string[] = this._appQueryUsageMap[userQuery];

			if (ensure && !appUUIDs) {
				appUUIDs = [];
				this._appQueryUsageMap[userQuery] = appUUIDs;
			}

			return appUUIDs;
		}

		/**
		 * 정규화 미디어 쿼리 : 사용자 미디어 쿼리[]
		 */
		private _mediaQueryMap: { [normalizedQuery: string]: string[] } = {};

		/**
		 * 정규화된 쿼리를 이용해 이로 매핑된 사용자 쿼리들을 얻습니다.
		 * @param normalizedQuery 정규화된 미디어 쿼리.
		 * @param ensure 반환 목록이 없을 때 새로 만들지 여부.
		 * @returns 정규화된 쿼리에 매핑된 사용자 쿼리 목록.
		 */
		private _getUserQueriesList(normalizedQuery: string, ensure = false): string[] {
			let userQueries: string[] = this._mediaQueryMap[normalizedQuery];

			if (ensure && !userQueries) {
				userQueries = [];
				this._mediaQueryMap[normalizedQuery] = userQueries;
			}

			return userQueries;
		}

		/**
		 * 등록된 media query들 중 app instance가 갖는 media query를 반환합니다.
		 * @param appInstance app.
		 * @param mediaQuery media query.
		 * @return 해당하는 media query.
		 * @deprecated 이 API는 실수로 노출된 API 이며 엔진 내부에서만 사용되어야 합니다.
		 */
		supportMedia(appInstance: AppInstance, mediaQuery: string[]): string {
			return this._supportMedia(appInstance, mediaQuery);
		}

		/**
		 * 등록된 media query들 중 app instance가 갖는 media query를 반환합니다.
		 * @param appInstance app.
		 * @param mediaQuery media query.
		 * @return 해당하는 media query.
		 */
		_supportMedia(appInstance: AppInstance, mediaQuery: string[]): string {
			let appUUID: string = appInstance.uuid;
			let matchedMedia: string = null;
			for (let idx: number = 0; idx < mediaQuery.length; idx++) {
				let mql: MediaQueryList = window.matchMedia(mediaQuery[idx]);
				let normalizedQuery: string = mql.media;

				let userQueries: string[] = this._getUserQueriesList(normalizedQuery, true);
				if (userQueries.indexOf(mediaQuery[idx]) === -1) {
					// 처음 보는 노멀라이즈 쿼리 인 경우
					if (utils.Util.isNullOrEmpty(userQueries)) {
						mql.addListener(this._onMQLChange);
					}
					userQueries.push(mediaQuery[idx]);
				}

				let apps: string[] = this._getAppsForMediaQuery(mediaQuery[idx], true);
				if (apps.indexOf(appUUID) == -1) {
					apps.push(appUUID);
				}

				if (mql.matches == true) {
					matchedMedia = mediaQuery[idx];
				}
			}
			return matchedMedia;
		}

		/**
		 * 앱 인스턴스가 사용중인 사용자 미디어 쿼리를 모두 정리합니다.
		 * @param appInstance 사용자 미디어 쿼리를 정리할 앱 인스턴스.
		 */
		public _releaseAppMedia(appInstance: AppInstance): void {
			let appUUID: string = appInstance.uuid;

			/** 모든 사용자 미디어 쿼리들 */
			let userQueries: string[] = Object.keys(this._appQueryUsageMap);

			/** 모든 정규화된 미디어 쿼리들 */
			let normalizedQueries: string[] = Object.keys(this._mediaQueryMap);

			userQueries.forEach(euQuery => {
				let appList = this._getAppsForMediaQuery(euQuery);
				if (!_removeFromArray(appList, appUUID)) {
					return
				}

				// 해당 사용자 미디어 쿼리를 사용하던 마지막 앱이 중단된 경우.
				if (utils.Util.isNullOrEmpty(appList)) {
					// 앱 목록 제거
					delete this._appQueryUsageMap[euQuery];

					// 노멀라이즈 맵에서 유저 쿼리들 제거
					normalizedQueries.forEach(enQuery => {
						let userQueries: string[] = this._getUserQueriesList(enQuery);
						if (_removeFromArray(userQueries, euQuery)) {
							if (userQueries.length == 0) {
								delete this._mediaQueryMap[enQuery];
							}
						}
					});
				}
			});
		}

		/**
		 * 미디어 쿼리 리스트 변경 이벤트가 발생할 때 콜백
		 * @param ev 미디어 쿼리 변경 이벤트.
		 */
		private _onMQLChange(ev: MediaQueryListEvent): void {
			if (ev.matches == false) {
				return;
			}
			let platform: Platform = Platform.INSTANCE;

			let normalizedQuery: string = ev.media;
			let userQueries = this._getUserQueriesList(normalizedQuery);

			if (utils.Util.isNullOrEmpty(userQueries)) {
				let mql: MediaQueryList = ev.target as MediaQueryList;
				if (mql && mql["removeListener"]) {
					mql.removeListener(platform._onMQLChange);
				}
				if (platform._mediaQueryMap[normalizedQuery]) {
					delete platform._mediaQueryMap[normalizedQuery];
				}
				return;
			}

			userQueries.forEach((userQuery: string) => {
				let appinstances: string[] = platform._appQueryUsageMap[userQuery];
				if (appinstances == null || appinstances.length == 0) {
					// TODO remove this userdefinedquery at _mediaQueryMap
					return;
				}
				appinstances.forEach((uuid: string) => {
					let appInstance = platform.lookupByUUID(uuid) as AppInstance;
					if (appInstance) {
						appInstance._setTargetMedia(userQuery);
					} else {
						// TODO appinstanceuuid at _mediaQueryAppInstance
					}
				});
			});
		}

		public _performInit() {
			if (this._initialized) {
				return;
			}
			this._initialized = true;

			let readyEvent = document.createEvent("Event");
			readyEvent.initEvent("eb-ready", true, true);

			document.dispatchEvent(readyEvent);
		}

