namespace cpr.controls.internal {
	let log = utils.Logger.forTopic("ndnd")._createBindedLoggerFunction({
		updator: it => log = it
	});

	export interface DropTargetOptions {
		/**
		 * 드래그 오버 되어 Idle 이벤트를 일으킬 시간. (단위: 초)
		 */
		idleTime: number;

		/**
		 * 드래그 오버 되어 최초 Idle 이벤트가 일어난 뒤, Idle 이벤트가 반복되기 까지의 시간. (단위: 초)
		 */
		idleRepeatTime: number;
	}

	export interface NodeDropTargetDelegate {
		options?: DropTargetOptions;

		/**
		 * 특정 드래그 소스를 처리할 것인지 여부를 반환해야 합니다.
		 * 구현을 생략한 경우, source의 dataType 이 "default" 인 경우에만 작동하게 됩니다.
		 * false를 리턴하면, 해당 드래그 소스를 무시하게 됩니다.
		 * @param source 드래그 소스
		 */
		isImportant?(source: NodeDragSource): boolean;

		/**
		 * 드래그 소스가 드롭 타겟 컨트롤 위에 진입 했을 때 호출 됩니다.
		 * 필요한 경우 드랍 타겟 피드백을 표시하십시오.
		 */
		onDragEnter?(context: NodeDropContext): void;

		/**
		 * 드래그 소스가 드롭 타겟 컨트롤 위에서 이동 했을 때 호출 됩니다.
		 * 필요한 경우 드랍 타겟 피드백을 업데이트 하십시오.
		 */
		onDragMove?(context: NodeDropContext): void;

		/**
		 * 드래그 소스가 드롭 타겟 컨트롤을 벗어났을 때 호출 됩니다.
		 * 필요한 경우, 드랍 타겟 피드백을 제거하십시오.
		 */
		onDragLeave?(context: NodeDropContext): void;

		/**
		 * 드래그 앤 드랍 도중 드랍 타겟에 마우스 포인터가 일정 시간이상 머문 경우 콜백 됩니다.
		 * @param context 드랍 컨텍스트.
		 * @param repeating 반복적으로 호출 된 것인지 여부.
		 */
		onDragIdle?(context: NodeDropContext, repeating: boolean): void;

		/**
		 * 드래그 소스가 드랍 타겟 컨트롤 위에 드랍 되었을 때 호출 됩니다.
		 * false 를 리턴하면 드래그 앤 드랍 동작이 취소 되며, DragSource의 delegate의 onDragCancel()이 호출 됩니다.
		 */
		onDrop?(context: NodeDropContext): boolean;
	}

	/**
	 * 컨트롤 위로 드랍을 가능하게 하고, 드랍 동작을 기술할 수 있게 해 주는 객체입니다.
	 */
	export class NodeDropTarget {
		public static ATTR__DROP_TARGET_ID = "data-ndtid";

		private _targetShape: ufc.ElementShape;
		private _delegate: NodeDropTargetDelegate;
		private _disposed = false;

		private _knownSource: NodeDragSource;
		private _knownLocation: PointerLocation;

		private _idleTimerID: number = -1;
		private _idleTime = 0.5;
		private _idleRepeatTime = 0.3;
		private _repeatingDragIdle = false;
		private _id: string;

		private static _DROP_TARGETS: NodeDropTarget[] = [];

		constructor(targetShape: ufc.ElementShape, delegate: NodeDropTargetDelegate) {
			this._id = _generateUUID();
			this._targetShape = targetShape;
			this._delegate = delegate;
			this._onDragIdle = this._onDragIdle.bind(this);

			this._targetShape.attr = _assign(this._targetShape.attr || {}, {
				[NodeDropTarget.ATTR__DROP_TARGET_ID]: this._id
			});

			if (delegate && delegate.options) {
				let options = delegate.options;
				if (typeof options.idleTime == "number") {
					this._idleTime = options.idleTime;
				}
				if (typeof options.idleRepeatTime == "number") {
					this._idleRepeatTime = options.idleRepeatTime;
				}
			}

			NodeDropTarget._DROP_TARGETS[NodeDropTarget._DROP_TARGETS.length] = this;
		}


		public static _getAllDropTargets() {
			return NodeDropTarget._DROP_TARGETS;
		}

		public _performDragEnter(source: NodeDragSource, location: PointerLocation): void {
			log("드롭 타겟 - 드래그 엔터", this);
			this._knownSource = source;
			if (this._delegate && this._delegate.onDragEnter) {
				this._safeRun(() => {
					this._delegate.onDragEnter(this._createContextWithLocation(location));
				});
			}
		}

		public _performDragMove(source: NodeDragSource, location: PointerLocation) {
			let changed = !location.equals(this._knownLocation);
			this._knownLocation = location;
			if (this._delegate && this._delegate.onDragMove) {
				this._safeRun(() => {
					this._delegate.onDragMove(this._createContextWithLocation(location));
				});
			}
			if (changed) {
				this._rescheduleIdleTime(this._idleTime);
			}
		}

		public _performDragLeave(source: NodeDragSource, location: PointerLocation) {
			log("드롭 타겟 - 드래그 리브", this);
			if (this._delegate && this._delegate.onDragLeave) {
				this._safeRun(() => {
					this._delegate.onDragLeave(this._createContextWithLocation(location));
				});
			}
			this._cancelIdleTimer();
			this._knownLocation = null;
			this._knownSource = null;
		}

		public _performDrop(source: NodeDragSource, location: PointerLocation): boolean {
			log("드롭 타겟 - 드랍");
			let processed = false;
			if (this._delegate && this._delegate.onDrop) {
				let dropResult = undefined;
				this._safeRun(() => {
					let dropContext: NodeDropContext = this._createContextWithLocation(location);
					dropResult = this._delegate.onDrop(dropContext);

				});
				processed = dropResult || dropResult === undefined;
			}
			this._cancelIdleTimer();
			this._knownSource = null;
			this._knownLocation = null;
			return processed;
		}

		private _onDragIdle() {
			log(`드랍 타겟 아이들, 반복: ${this._repeatingDragIdle}`);
			this._idleTimerID = -1;
			if (this._knownLocation && this._delegate && this._delegate.onDragIdle) {
				let constraint = this._createContextWithLocation(this._knownLocation);
				this._safeRun(() => {
					this._delegate.onDragIdle(constraint, this._repeatingDragIdle);
				});
			}
			this._rescheduleIdleTime(this._idleRepeatTime);
			this._repeatingDragIdle = true;
		}

		private _cancelIdleTimer() {
			if (this._idleTimerID >= 0) {
				window.clearTimeout(this._idleTimerID);
				this._idleTimerID = -1;
			}
		}

		private _rescheduleIdleTime(time: number) {
			this._cancelIdleTimer();
			this._repeatingDragIdle = false;
			this._idleTimerID = window.setTimeout(this._onDragIdle, time * 1000);
		}

		private _createContextWithLocation(location: PointerLocation) {
			let constraint = new NodeDropContext(this._knownSource, this, location);
			return constraint;
		}

		public _accepts(source: NodeDragSource) {
			let isImportant = true;
			if (this._delegate && this._delegate.isImportant) {
				this._safeRun(() => {
					isImportant = this._delegate.isImportant(source);
				});
			} else {
				isImportant = source.dataType == DragSource._DEFAULT_DATA_TYPE;
			}
			return isImportant;
		}

		/**
		 * 드롭 타겟을 파기 시킵니다.
		 */
		public dispose(): void {
			if (this._disposed) {
				return;
			}

			this._cancelIdleTimer();
			this._knownSource = null;
			this._knownLocation = null;

			this._disposed = true;
			let index = NodeDropTarget._DROP_TARGETS.indexOf(this);
			if (index >= 0) {
				NodeDropTarget._DROP_TARGETS.splice(index, 1);
			}
		}

		/**
		 * 드랍 타겟 컨트롤을 얻습니다.
		 */
		public get targetShape(): ufc.ElementShape {
			return this._targetShape;
		}

		public get id(): string {
			return this._id;
		}

		/**
		 * onDragIdle()을 호출하기 까지의 마우스 포인터 대기시간을 얻습니다. (단위: 초)
		 */
		public get idleTime(): number {
			return this._idleTime;
		}

		/**
		 * onDragIdle()을 호출하기 까지의 마우스 포인터 대기시간을 지정합니다. (단위: 초)
		 */
		public set idleTime(newTime: number) {
			this._idleTime = newTime;
		}

		/**
		 * onDragIdle()이 반복 호출되기 까지의 마우스 포인터 대기시간을 얻습니다. (단위: 초)
		 */
		public get idleRepeatTime(): number {
			return this._idleRepeatTime;
		}

		/**
		 * onDragIdle()이 반복 호출되기 까지의 마우스 포인터 대기시간을 지정합니다. (단위: 초)
		 */
		public set idleRepeatTime(newTime: number) {
			this._idleRepeatTime = newTime;
		}

		private _safeRun(task: () => void) {
			utils.tryCatch({
				do: () => {
					task();
				},
				_report: true,
				_context: exceptions.ErrorContext.EVENT_LISTENER
			});
		}
	}
}