/// <reference path="./IEventTarget.ts"/>

namespace cpr.events {
	class ListenerInfo {
		public listener: (CEvent) => void;
		public once: boolean;

		constructor(listener: (CEvent) => void, once: boolean) {
			this.listener = listener;
			this.once = once;
		}
	}

	/**
	 * 이벤트 시스템 내부에서 이벤트를 디스패치하기 위한 용도로 사용되는 테이블 입니다.
	 * @private
	 */
	export class EventTable implements IEventTarget {
		/**
		 * 이벤트 유형별 리스너 배열을 담는 맵입니다.
		 */
		private _eventMap: { [key: string]: ListenerInfo[] };

		/**
		 * 주어진 이벤트 타입에 대해 이벤트 리스너 배열을 얻습니다. 존재하지 않는 경우 null 이 리턴됩니다.
		 * @param options.type 이벤트 리스너 배열을 얻을 이벤트 유형.
		 * @param options.ensure 해당 유형에 대해 이벤트 리스너 배열이 존재하지 않는 경우, 새로 만들 것인지 여부.
		 */
		private _getEventListeners(options: { type: string, ensure: boolean }): ListenerInfo[] {
			if (!this._eventMap && !options.ensure) {
				return null
			}

			if (!this._eventMap && options.ensure) {
				this._eventMap = {}
			}

			let resultTable = this._eventMap[options.type] || null;
			if (resultTable == null && options.ensure) {
				this._eventMap[options.type] = resultTable = [];
			}

			return resultTable;
		}

		_hasEventListener(type: string): boolean {
			let listeners: ListenerInfo[] = this._getEventListeners({ type: type, ensure: false });
			return listeners != null && listeners.length > 0;
		}

		/**
		 * 지정된 타입의 리스너들을 삭제합니다.
		 * @param type 
		 */
		removeEventListeners(type: string) {
			if (this._eventMap) {
				delete this._eventMap[type];
			}
		}

		/**
		 * 모든 이벤트 리스너들을 삭제합니다.
		 */
		removeAllEventListeners() {
			this._eventMap = {};
		}

		/**
		 * 이벤트 리스너를 추가합니다.
		 * @param type 이벤트 타입
		 * @param listener 이벤트 객체를 파라미터로 받는 함수
		 */
		addEventListener(type: string, listener: (e: CEvent) => void): void {
			let typedListenerInfos = this._getEventListeners({
				type: type,
				ensure: true
			});

			let index = _.findIndex(typedListenerInfos, (it: ListenerInfo) => {
				return it.listener === listener;
			})

			// 동일한 event listener는 한 번만 추가된다.
			if (index === -1) {
				typedListenerInfos.push(new ListenerInfo(listener, false));
			}
		}


		addEventListenerOnce(type: string, listener: (e: CEvent) => void): void {
			let typedListenerInfos = this._getEventListeners({
				type: type,
				ensure: true
			});

			let index = _.findIndex(typedListenerInfos, (it: ListenerInfo) => {
				return it.listener === listener;
			})

			// 동일한 event listener는 한 번만 추가된다.
			if (index === -1) {
				typedListenerInfos.push(new ListenerInfo(listener, true))
			}
		}

		/**
		 * 이벤트 타입과 등록된 리스너를 찾아 삭제합니다.
		 * @param type 
		 * @param listener 
		 */
		removeEventListener(type: string, listener: (e: CEvent) => void): void {
			let typedTable = this._getEventListeners({ type: type, ensure: false }) || [];

			let index = _.findIndex(typedTable, (it: ListenerInfo) => {
				return it.listener == listener;
			})

			if (index >= 0) {
				typedTable.splice(index, 1);
			}
		}

		/**
		 * 이벤트를 호출합니다.
		 * @param e 이벤트 타입을 갖는 객체
		 */
		dispatchEvent(e: CEvent): boolean {
			let typedTable = this._getEventListeners({ type: e.type, ensure: false }) || [];
			let clonedTypedTable = typedTable.concat([]);
			let dispatching = (eachInfo) => {
				cpr.utils.tryCatch({
					do: () => {
						let rtnValue: boolean = eachInfo.listener.call(e.control, e);
						if (e.defaultPrevented == false && rtnValue != null && rtnValue === false) {
							e.preventDefault();
						}
					},
					_report: true,
					_context: exceptions.ErrorContext.EVENT_LISTENER
				});
				return e.immediatePropagationStopped;
			};
			dispatching["displayName"] = `Dispatch ${e.type} event`;

			clonedTypedTable.some(dispatching);

			clonedTypedTable.filter(it => it.once).forEach(onceInfo => {
				this.removeEventListener(e.type, onceInfo.listener)
			})

			return !e.defaultPrevented;
		}
	}
}