namespace cpr.controls.item {
	/**
	 * @private
	 */
	export abstract class AbstractItemListView<ItemListType extends ItemList<Item, ItemSetConfig>, ItemFilterType> {
		private _uuid: string = _generateUUID();
		private _itemList: ItemListType;
		private _owner: UIControl;
		private _itemFilter: ItemFilterType;

		constructor(owner: UIControl, itemList: ItemListType, itemFilter: ItemFilterType) {
			this._owner = owner;
			this._itemList = itemList;
			this._itemFilter = itemFilter;
		}

		/**
		 * realmCache용 UUID를 반환합니다.
		 */
		public get uuid(): string {
			return this._uuid;
		}

		/**
		 * 이 뷰의 소유자 컨트롤을 반환합니다.
		 */
		public get owner(): UIControl {
			return this._owner;
		}

		/**
		 * 이 뷰가 참조하는 아이템 리스트를 반환합니다.
		 */
		public get itemList(): ItemListType {
			return this._itemList;
		}

		/**
		 * 이 뷰가 참조하는 아이템 필터를 반환합니다.
		 */
		public get itemFilter(): ItemFilterType {
			return this._itemFilter;
		}

		/**
		 * 해당 뷰가 dispose 되었는지 여부를 반환합니다.
		 */
		public get disposed(): boolean {
			return this._itemList == null || this._owner == null;
		}

		/**
		 * 해당 뷰를 dispose 합니다.
		 */
		public dispose(): void {
			this._itemList = null;
			this._itemFilter = null;
			this._owner = null;
		}
	}
}