
namespace cpr.controls.gridpart.rowgroup {
	/**
	 * RowGroup의 header 또는 footer의 가시성 여부를 판단하여 리턴.
	 * @param rowgroupband GridRowGroupConfig
	 * @param section GRIDREGION
	 * @param rowgroup provider.GridRowGroup
	 */
	function _isVisibleRowGroupSection(rowgroupband: GridRowGroupConfig, section: string, rowgroup: provider.GridRowGroup): boolean {
		if (rowgroupband != null && rowgroupband[section] != null) {
			let visible: boolean = true;
			if (rowgroupband.activate == false) {
				visible = false;
			} else if (rowgroupband[section].visibleExpr) {
				visible = GridUtil._getRowGroupExprResult(rowgroupband[section].visibleExpr, rowgroup, null) as boolean;
			}
			return visible;
		}
		return false;
	}

	/**
	 * 완성된 GridRowGroup으로 TreeCell의 선택상태를 초기화 한다.
	 * @param isShowingTreeCell 
	 * @param checkedRowGroups 
	 * @returns 
	 */
	function _initTreeCellCheckedState(isShowingTreeCell: boolean, checkedRowGroups: provider.GridRowGroup[], checkType: renderer.TreeCellCheckType) {
		if (isShowingTreeCell === false || checkedRowGroups == null || checkedRowGroups.length === 0) {
			return;
		}

		for (let idx: number = 0; idx < checkedRowGroups.length; idx++) {
			let gridRowGroup: provider.GridRowGroup = checkedRowGroups[idx];
			gridRowGroup?._initChecked(checkType, true);
		}
	}

	function _setBeforeState(beforeGroupState: GroupState[], rowgroup: provider.GridRowGroup, parentColumnNames: string[], parentConditionValues: { [columnName: string]: string }, columnNames: string[], conditionValues: { [columnName: string]: string }, initExpanded): void {
		let expand: boolean = initExpanded;
		let enabledCheckbox: boolean = true;
		let visibleCheckbox: boolean = true;
		beforeGroupState.some((beforeGroupInfo: GroupState) => {
			if (beforeGroupInfo.p_conditionKeys == parentColumnNames.join(",")) {
				let pMatch: boolean = true;
				parentColumnNames.some((columnName: string) => {
					if (beforeGroupInfo.p_conditions[columnName] != parentConditionValues[columnName]) {
						pMatch = false;
						return true;
					}
					return false;
				});
				if (pMatch) {
					if (beforeGroupInfo.conditionKeys == columnNames.join(",")) {
						let match: boolean = true;
						columnNames.some((columnName: string) => {
							if (beforeGroupInfo.conditions[columnName] != conditionValues[columnName]) {
								match = false;
								return true;
							}
							return false;
						});
						if (match) {
							let sameSection: boolean = (beforeGroupInfo.start == rowgroup.startRowIndex && beforeGroupInfo.end == rowgroup.endRowIndex);
							if (sameSection) {
								expand = beforeGroupInfo.expanded;
								enabledCheckbox = beforeGroupInfo.enabled_checkbox;
								visibleCheckbox = beforeGroupInfo.visible_checkbox;
								return true;
							}
						}
					}
				}
			}
		});
		rowgroup._setExpanded(expand);
		rowgroup._setEnabledCheckbox(enabledCheckbox);
		rowgroup._setVisibleCheckbox(visibleCheckbox);
	}

	interface GroupState {
		conditionKeys: string,
		conditions: { [columnName: string]: string },
		p_conditionKeys: string,
		p_conditions: { [columnName: string]: string },
		expanded: boolean,
		enabled_checkbox: boolean,
		visible_checkbox: boolean,
		start: number,
		end: number
	}

	/**
	 * @private
	 */
	export interface RowGroupBuilder {
		buildRowGroup(grid: Grid): void;
		buildVirtualRow(grid: Grid): void;
	}

	/**
	 * @private
	 */
	export class GridRowGroupBuilder implements RowGroupBuilder {
		private _context: GridContext;
		private _conditions: string[];


		constructor(context: GridContext, conditions: string[]) {
			this._context = context;
			this._conditions = conditions;
		}

		public buildRowGroup(grid: Grid): void {
			let dataProvider: provider.GridDataProvider = grid.dataProvider;

			let rowGroups: provider.GridRowGroup[] = dataProvider._getRowGroups();
			let beforeGroupState: GroupState[] = this._getGroupState(rowGroups);
			if (rowGroups && rowGroups.length > 0) {
				rowGroups.splice(0);
			}

			dataProvider._setRowGroups(null);
			dataProvider._setVirtualRows(null);

			this._setSubGroup(grid, dataProvider, dataProvider, this._conditions, 0, beforeGroupState);


			this.buildVirtualRow(grid);
		}

		public buildVirtualRow(grid: Grid): void {
			let dataProvider: provider.GridDataProvider = grid.dataProvider;
			let virtualRows: provider.VirtualRow[] = dataProvider._getVirtualRows();
			if (virtualRows && virtualRows.length > 0) {
				virtualRows.splice(0);
			} else {
				virtualRows = [];
				dataProvider._setVirtualRows(virtualRows);
			}

			let rowgroups: provider.GridRowGroup[] = dataProvider._getRowGroups();
			if (!rowgroups) {
				return;
			}

			let detailRowHeights: number[] = this._context._getDesignDetailRowHeights();
			let rowGroupBands: GridRowGroupConfig[] = this._context.getRowGroup();
			let visibleDsIndex: number = 0;
			rowgroups.forEach(rowgroup => {
				visibleDsIndex = this._travelRowgroup(virtualRows, rowgroup, rowGroupBands, detailRowHeights, visibleDsIndex);
			});
		}

		///////////////////////// private row group /////////////////////////
		private _setSubGroup(grid: Grid
			, dataProvider: provider.GridDataProvider
			, parent: (provider.GridDataProvider | provider.GridRowGroup)
			, conditions: string[], depth: number
			, beforeGroupState: GroupState[]): void {

			// FIXME : 정리필요
			let rowgroups: provider.GridRowGroup[] = [];
			let startrowindex: number;
			let endrowindex: number;
			let rowgroup: provider.GridRowGroup;
			if (parent instanceof provider.GridRowGroup) {
				startrowindex = parent.startRowIndex;
				endrowindex = parent.endRowIndex;
			} else {
				startrowindex = 0;
				endrowindex = parent.getRowCount() - 1;
			}

			if (conditions[depth] == null) {
				// grouping 설정을 하지 않은 경우
				if (endrowindex != -1) {
					rowgroup = new provider.GridRowGroup(grid, grid.dataSet, null
						, parent instanceof provider.GridDataProvider ? null : parent
						, {});
					for (let i = startrowindex, localIndex = 0; i <= endrowindex; i++, localIndex++) {
						let row: provider.GridRow = dataProvider.getRow(i);
						row._setLocalIndex(localIndex);
						rowgroup._addRow(row, false);
					}
					rowgroup._resetGroupingChecked(false);
					rowgroup._setLocalIndex(rowgroups.length);
					rowgroups[rowgroups.length] = rowgroup;
				}
			} else {
				let beforeValues: { [columnName: string]: any } = {};
				let currentValues: { [columnName: string]: any } = {};
				let nextValues: { [columnName: string]: any } = {};
				let columnNames: string[] = conditions[depth].split(",");
				let initExpanded: boolean = false;
				if (this._context.collapsible == false || (this._context.collapsible == true && this._context._getStartCollapse(conditions[depth]) == false)) {
					initExpanded = true;
				}
				let parentColumnNames: string[] = [];
				for (let i = 0; i < depth; i++) {
					if (conditions[i] != null && conditions[i] != "") {
						parentColumnNames = parentColumnNames.concat(conditions[i].split(","));
					}
				}
				parentColumnNames = _uniq(parentColumnNames);
				let localIndex: number = 0;
				for (let i = startrowindex; i <= endrowindex; i++) {
					let conditionValues: { [columnName: string]: string } = {};
					let parentConditionValues: { [columnName: string]: string } = {};
					let isGroupStart: boolean = false;
					let isGroupEnd: boolean = false;

					parentColumnNames.forEach((columnName: string) => {
						parentConditionValues[columnName] = dataProvider.getValue(i, columnName);
					});
					columnNames.forEach((columnName: string) => {
						nextValues[columnName] = (i + 1 <= endrowindex) ? dataProvider.getValue(i + 1, columnName) : undefined;
						currentValues[columnName] = (currentValues[columnName] === undefined) ? dataProvider.getValue(i, columnName) : currentValues[columnName];
						conditionValues[columnName] = currentValues[columnName];
						if (nextValues[columnName] instanceof foundation.DecimalType) {
							nextValues[columnName] = nextValues[columnName].toNumber();
						}
						if (currentValues[columnName] instanceof foundation.DecimalType) {
							currentValues[columnName] = currentValues[columnName].toNumber();
						}
						let beforeValue = beforeValues[columnName];
						let currentValue = currentValues[columnName];
						let nextValue = nextValues[columnName];
						if (beforeValue != currentValue) {
							isGroupStart = true;
						}
						if (currentValue != nextValue) {
							isGroupEnd = true;
						}
						beforeValues[columnName] = currentValues[columnName];
						currentValues[columnName] = nextValues[columnName];
					});
					if (i == startrowindex) { isGroupStart = true; }
					if (i == endrowindex) { isGroupEnd = true; }

					if (isGroupStart) {
						rowgroup = null;
						rowgroup = new provider.GridRowGroup(grid, grid.dataSet, null,
							parent instanceof provider.GridDataProvider ? null : parent,
							{
								conditions: conditionValues,
								parentConditions: parentConditionValues
							});
					}

					let row: provider.GridRow = dataProvider.getRow(i);
					row._setLocalIndex(localIndex++);
					rowgroup._addRow(row, false);

					if (isGroupEnd) {
						if (rowgroup) {
							rowgroup._resetGroupingChecked(false);
							rowgroup._setLocalIndex(rowgroups.length);
							_setBeforeState(beforeGroupState, rowgroup, parentColumnNames, parentConditionValues, columnNames, conditionValues, initExpanded);
							rowgroups[rowgroups.length] = rowgroup;
							localIndex = 0;
						}
					}
				}
			}

			parent._setRowGroups(rowgroups);
			depth += 1;
			if (depth < conditions.length) {
				rowgroups.forEach((childRowGroup: provider.GridRowGroup) => {
					this._setSubGroup(grid, dataProvider, childRowGroup, conditions, depth, beforeGroupState);
				});
			}
		}

		public static _getConditions(rowgroup: provider.GridRowGroup): { [columnName: string]: string } {
			let option: { [key: string]: any } = rowgroup.option;
			return option["conditions"];
		}

		public static _getParentConditions(rowgroup: provider.GridRowGroup): { [columnName: string]: string } {
			let option: { [key: string]: any } = rowgroup.option;
			return option["parentConditions"];
		}

		public static _getConditionKeys(rowgroup: provider.GridRowGroup): string {
			return GridRowGroupBuilder._getKeys(GridRowGroupBuilder._getConditions(rowgroup));
		}

		public static _getParentConditionKeys(rowgroup: provider.GridRowGroup): string {
			return GridRowGroupBuilder._getKeys(GridRowGroupBuilder._getParentConditions(rowgroup));
		}

		public static _getKeys(conditions: {}): string {
			if (conditions && typeof conditions === "object") {
				let keys: string[] = Object.keys(conditions);
				return keys.join(",");
			}
			return null;
		}

		private _travelRowgroup(virtualRows: provider.VirtualRow[], rowgroup: provider.GridRowGroup, rowGroupBands: GridRowGroupConfig[], detailRowHeights: number[], visibleDsIndex: number): number {
			let groupCondition: string = GridRowGroupBuilder._getConditionKeys(rowgroup);
			let rowgroupband: GridRowGroupConfig = this._searchRowGroupBand(groupCondition, rowGroupBands);

			if (_isVisibleRowGroupSection(rowgroupband, GRIDREGION.GHEADER, rowgroup)) {
				virtualRows[virtualRows.length] = {
					type: provider.VROWTYPE.GHEADER,
					condition: groupCondition,
					rowheights: this._getRowHeights(rowgroupband[GRIDREGION.GHEADER].rows),
					rowdata: rowgroup
				};
			}
			if (rowgroup.expanded == false) {
				return visibleDsIndex;
			}

			let grouprows: (provider.GridRow | provider.GridRowGroup)[] = rowgroup._getRows();
			if (grouprows) {
				grouprows.forEach((grouprow: (provider.GridRow | provider.GridRowGroup)) => {
					if (grouprow instanceof provider.GridRow) {
						virtualRows[virtualRows.length] = {
							type: provider.VROWTYPE.GRIDROW,
							dsindex: (<provider.GridRow>grouprow).getIndex(),
							visibledsindex: visibleDsIndex++,
							rowheights: detailRowHeights,
							pairgroup: rowgroup,
							rowdata: grouprow
						};
					} else {
						visibleDsIndex = this._travelRowgroup(virtualRows, grouprow as provider.GridRowGroup, rowGroupBands, detailRowHeights, visibleDsIndex);
					}
				});
			}

			if (_isVisibleRowGroupSection(rowgroupband, GRIDREGION.GFOOTER, rowgroup)) {
				virtualRows[virtualRows.length] = {
					type: provider.VROWTYPE.GFOOTER,
					condition: groupCondition,
					rowheights: this._getRowHeights(rowgroupband[GRIDREGION.GFOOTER].rows),
					rowdata: rowgroup
				};
			}
			return visibleDsIndex;
		}

		private _searchRowGroupBand(groupCondition: string, rowGroupBands: GridRowGroupConfig[]): GridRowGroupConfig {
			let result: GridRowGroupConfig = null;
			rowGroupBands.some((rowgroup) => {
				if (groupCondition == rowgroup.groupCondition) {
					result = rowgroup;
					return true;
				}
			});
			return result;
		}

		private _getRowHeights(rows: { rowindex: number, height: number }[]): number[] {
			let rowHeight: number[] = [];
			rows.forEach((rowInfo: { rowindex: number, height: number }) => {
				rowHeight[rowHeight.length] = rowInfo.height;
			});
			return rowHeight;
		}

		private _getGroupState(rowGroups: provider.GridRowGroup[]): GroupState[] {
			let result: GroupState[] = [];

			if (rowGroups == null
				|| rowGroups.length == 0
				|| (rowGroups[0] && rowGroups[0] instanceof provider.GridRow)) {
				return result;
			}

			rowGroups.forEach((rowGroup: provider.GridRowGroup) => {
				let conditionKeys: string = GridRowGroupBuilder._getConditionKeys(rowGroup);
				let parentConditionKeys: string = GridRowGroupBuilder._getParentConditionKeys(rowGroup);
				// let initExpanded: boolean = this._context._getStartCollapse(conditionKeys) == false;
				// if (rowGroup.expanded != initExpanded) {
				result[result.length] = {
					conditionKeys: conditionKeys,
					conditions: GridRowGroupBuilder._getConditions(rowGroup),
					p_conditionKeys: parentConditionKeys,
					p_conditions: GridRowGroupBuilder._getParentConditions(rowGroup),
					expanded: rowGroup.expanded,
					enabled_checkbox: rowGroup._isEnabledCheckbox(),
					visible_checkbox: rowGroup._isVisibleCheckbox(),
					start: rowGroup.startRowIndex,
					end: rowGroup.endRowIndex
				};
				// }

				result = result.concat(this._getGroupState(rowGroup._getRows() as provider.GridRowGroup[]));
			});
			return result;

		}
	}

	/**
	 * @private
	 */
	export class TreeRowGroupBuilder implements RowGroupBuilder {
		private _context: GridContext;
		private _treeCell: renderer.TreeCell;

		private _levelColNm: string;
		private _levelExp: expression.Expression;
		private _showCheckbox: boolean = false;

		private _checkedRowGroups: provider.GridRowGroup[];


		constructor(context: GridContext, treeCell: renderer.TreeCell) {
			this._context = context;
			this._treeCell = treeCell;
		}

		public static _setExpandSts(grid: Grid, gridRow: provider.GridRow, rowGroup: provider.GridRowGroup): void {
			if (!grid || !gridRow) {
				return;
			}
			gridRow._setExpandSts(String(rowGroup.expanded));
		}

		public static _setCheckedSts(grid: Grid, gridRow: provider.GridRow, checked: boolean): void {
			if (!grid || !gridRow) {
				return;
			}
			gridRow._setTreeCellCheckedSts(String(checked));
		}

		public static _getCheckedSts(grid: Grid, gridRow: provider.GridRow): boolean {
			if (!grid || !gridRow) {
				return;
			}
			return (gridRow._getTreeCellCheckedSts() == "true") ? true : false;
		}

		public buildRowGroup(grid: Grid): void {
			this._checkedRowGroups = [];

			let dataProvider: provider.GridDataProvider = grid.dataProvider;
			let validTreeCell: boolean = this._setTreeCellInfo();
			if (validTreeCell === false) {
				this._checkedRowGroups = null;
				return;
			}

			dataProvider._setRowGroups(null);
			dataProvider._setVirtualRows(null);

			let startCollapseLevel: number = this._treeCell.startCollapseLevel;
			if (startCollapseLevel == null) {
				startCollapseLevel = -1;
			}

			this._setSubGroup(grid, dataProvider, dataProvider, 0, Number(this._treeCell.startLevel), startCollapseLevel); /* level은 1 부터 시작 */
			this.buildVirtualRow(grid);

			// treecell checked initalize
			_initTreeCellCheckedState(this._showCheckbox, this._checkedRowGroups, this._treeCell.checkType);
			this._checkedRowGroups = null;
		}

		public buildVirtualRow(grid: Grid): void {
			let dataProvider: provider.GridDataProvider = grid.dataProvider;
			let virtualRows: provider.VirtualRow[] = dataProvider._getVirtualRows();
			if (virtualRows && virtualRows.length > 0) {
				virtualRows.splice(0);
			} else {
				virtualRows = [];
				dataProvider._setVirtualRows(virtualRows);
			}

			let rowgroups: provider.GridRowGroup[] = dataProvider._getRowGroups();
			if (!rowgroups) {
				return;
			}

			let detailRowHeights: number[] = this._context._getDesignDetailRowHeights();
			let visibleDsIndex: number = 0;
			rowgroups.forEach((gridRowGroup: provider.GridRowGroup) => {
				visibleDsIndex = this._travelRowgroup(virtualRows, gridRowGroup, detailRowHeights, visibleDsIndex);
			});
		}

		private _travelRowgroup(virtualRows: provider.VirtualRow[], gridRowGroup: provider.GridRowGroup, detailRowHeights: number[], visibleDsIndex: number): number {
			let gridRow: provider.GridRow = gridRowGroup.target;
			virtualRows[virtualRows.length] = {
				type: provider.VROWTYPE.GRIDROW,
				dsindex: gridRow.getIndex(),
				visibledsindex: visibleDsIndex++,
				rowheights: detailRowHeights,
				pairgroup: gridRowGroup,
				rowdata: gridRow
			};

			let rows: (provider.GridRow | provider.GridRowGroup)[] = gridRowGroup._getRows();
			if (rows != null) {
				rows.forEach((row: (provider.GridRow | provider.GridRowGroup)) => {
					if (gridRowGroup.expanded === true) {
						visibleDsIndex = this._travelRowgroup(virtualRows, row as provider.GridRowGroup, detailRowHeights, visibleDsIndex);
					}
				});
			}
			return visibleDsIndex;
		}

		// private methods
		private _setTreeCellInfo(): boolean {
			this._levelColNm = null;
			this._levelExp = null;
			this._showCheckbox = false;

			if (!this._treeCell) {
				return false;
			}

			this._showCheckbox = this._treeCell.showCheckbox;

			let levelInfo: bind.BindInfo = this._treeCell.getBindInfo("level");
			if (!levelInfo) {
				return true; // 상수인 경우
			}
			let levelColNm: string = levelInfo.columnName;
			if (levelColNm) {
				let dataSet: data.DataCollection = this._context.getGrid().dataSet;
				if (dataSet && dataSet.isExistColumn(levelColNm) == false) {
					return true;
				}
				this._levelColNm = levelColNm;
				return true;
			}
			let expression: string = levelInfo.expression;
			if (expression) {
				this._levelExp = new cpr.expression.Expression(expression);
				return true;
			}

			return false;
		}

		private _setSubGroup(grid: Grid
			, dataProvider: provider.GridDataProvider
			, parent: (provider.GridDataProvider | provider.GridRowGroup)
			, startIndex: number
			, level: number
			, startCollapseLevel: number): number {

			let rowgroups: provider.GridRowGroup[] = [];
			let maxRowIdx: number = dataProvider.getRowCount();
			for (; startIndex < maxRowIdx;) {
				let gridRow: provider.GridRow = dataProvider.getRow(startIndex);
				let currentLevel: (string | number) = null;
				if (this._levelColNm) {
					let value: (string | number | foundation.DecimalType | ufc.StyledString) = gridRow.getValue(this._levelColNm);
					if (value instanceof ufc.StyledString) {
						throw new exceptions.IllegalArgumentException("Illegal TreeCell level value(StyledString). TreeCell level column value must be number.");
					} else if (value instanceof foundation.DecimalType) {
						currentLevel = value.toString();
					} else {
						currentLevel = value;
					}
				} else if (this._levelExp) {
					currentLevel = this._levelExp._evaluateInternal({
						_getExpressionDelegates(): any[] {
							return [gridRow, grid, grid.dataSet];
						}
					});
				} else {
					currentLevel = this._treeCell.level;
				}
				let iCurLvl: number = Number(currentLevel);
				if (isNaN(iCurLvl)) {
					throw new exceptions.IllegalArgumentException("Illegal TreeCell level value(" + currentLevel + "). TreeCell level column value must be number.");
				}
				if (iCurLvl < Number(this._treeCell.startLevel)) {
					iCurLvl = Number(this._treeCell.startLevel);
				}
				if (level > iCurLvl) {
					break;
				} else {
					// 접음 펼침 속성을 DataSet Row의 속성으로 관리.
					let rowgroup: provider.GridRowGroup = new provider.GridRowGroup(grid, grid.dataSet, gridRow,
						parent instanceof provider.GridDataProvider ? null : parent,
						{ level: currentLevel });
					gridRow._setLocalIndex(gridRow.getIndex());
					rowgroup._setLocalIndex(gridRow.getIndex());
					rowgroups[rowgroups.length] = rowgroup;

					let expand: string = gridRow._getExpandSts();
					let expanded: boolean = true;
					if (expand) {
						expanded = (expand == "false" ? false : true);
					} else if (startCollapseLevel != -1 && level >= startCollapseLevel) {
						expanded = false;
					}

					rowgroup._setExpanded(expanded);

					if (this._showCheckbox === true) {
						let gridrow: provider.GridRow = rowgroup.target;
						if (gridrow) {
							let checkedState: boolean = TreeRowGroupBuilder._getCheckedSts(grid, gridrow);
							if (checkedState) {
								this._checkedRowGroups[this._checkedRowGroups.length] = rowgroup;
							}
						}
					}

					startIndex++;
					startIndex = this._setSubGroup(grid, dataProvider, rowgroup, startIndex, iCurLvl + 1, startCollapseLevel);
				}
			}

			parent._setRowGroups(rowgroups);

			return startIndex;
		}
	}

	/**
	 * @private
	 */
	export class GroupedTreeCellBuilder implements RowGroupBuilder {
		private _context: GridContext;
		private _conditions: string[];
		private _treeCell: renderer.TreeCell;

		private _treeCellLevelColNm: string;
		private _treeCellLevelExp: expression.Expression;
		private _treeCellShowCheckbox: boolean = false;

		private _checkedRowGroups: provider.GridRowGroup[];

		private _previousNode: provider.GridRowGroup = null;


		constructor(context: GridContext, conditions: string[], treeCell: renderer.TreeCell) {
			this._context = context;
			this._conditions = conditions;
			this._treeCell = treeCell;
		}

		public buildRowGroup(grid: Grid): void {
			this._checkedRowGroups = [];

			let dataProvider: provider.GridDataProvider = grid.dataProvider;
			let validTreeCell: boolean = this._setTreeCellInfo();
			if (validTreeCell === false) {
				this._checkedRowGroups = null;
				return; /// Valid 하지 않을 때 Grouping으로만 동작하게 함?
			}
			let rowGroups: provider.GridRowGroup[] = dataProvider._getRowGroups();

			let beforeGroupState: GroupState[] = this._getGroupState(rowGroups);

			if (rowGroups && rowGroups.length > 0) {
				rowGroups.splice(0);
			}
			dataProvider._setRowGroups(null);
			dataProvider._setVirtualRows(null);

			let startCollapseLevel: number = this._treeCell.startCollapseLevel;
			if (startCollapseLevel == null) {
				startCollapseLevel = -1;
			}

			this._setSubGroup(grid, dataProvider, dataProvider, this._conditions, 0, beforeGroupState, startCollapseLevel);
			this._previousNode = null;

			this.buildVirtualRow(grid);

			// treecell checked initalize
			_initTreeCellCheckedState(this._treeCellShowCheckbox, this._checkedRowGroups, this._treeCell.checkType);
			this._checkedRowGroups = null;
		}

		public buildVirtualRow(grid: Grid): void {
			let dataProvider: provider.GridDataProvider = grid.dataProvider;
			let virtualRows: provider.VirtualRow[] = dataProvider._getVirtualRows();
			if (virtualRows && virtualRows.length > 0) {
				virtualRows.splice(0);
			} else {
				virtualRows = [];
				dataProvider._setVirtualRows(virtualRows);
			}

			let rowgroups: provider.GridRowGroup[] = dataProvider._getRowGroups();
			if (!rowgroups) {
				return;
			}

			let detailRowHeights: number[] = this._context._getDesignDetailRowHeights();
			let rowGroupBands: GridRowGroupConfig[] = this._context.getRowGroup();
			let visibleDsIndex: number = 0;
			for (let idx: number = 0; idx < rowgroups.length; idx++) {
				let rowGroup: provider.GridRowGroup = rowgroups[idx];
				visibleDsIndex = this._travelRowgroup(virtualRows, rowGroup, rowGroupBands, detailRowHeights, visibleDsIndex);
			}
		}


		private _travelRowgroup(virtualRows: provider.VirtualRow[], rowgroup: provider.GridRowGroup, rowGroupBands: GridRowGroupConfig[], detailRowHeights: number[], visibleDsIndex: number): number {
			let groupCondition: string = GridRowGroupBuilder._getConditionKeys(rowgroup);
			let rowgroupband: GridRowGroupConfig = this._searchRowGroupBand(groupCondition, rowGroupBands);

			if (_isVisibleRowGroupSection(rowgroupband, GRIDREGION.GHEADER, rowgroup)) {
				virtualRows[virtualRows.length] = {
					type: provider.VROWTYPE.GHEADER,
					condition: groupCondition,
					rowheights: this._getRowHeights(rowgroupband[GRIDREGION.GHEADER].rows),
					rowdata: rowgroup
				};
			}
			if (rowgroup.expanded == false) {
				return visibleDsIndex;
			}

			let grouprows: (provider.GridRow | provider.GridRowGroup)[] = rowgroup._getRows();
			if (grouprows && grouprows.length > 0) {
				let firstGroupRow: provider.GridRowGroup = grouprows[0] as provider.GridRowGroup;
				if (firstGroupRow.target) { // TreeCellRowGroup
					// TreeCell Node는 leaf GroupingRoowGroup에만 존제하기 때문에 자체적인 looping이 가능
					let travelTreeCellRowGroup = (grs: (provider.GridRow | provider.GridRowGroup)[]) => {
						for (let idx: number = 0; idx < grs.length; idx++) {
							let grouprow: provider.GridRowGroup = grs[idx] as provider.GridRowGroup;
							let gridRow: provider.GridRow = grouprow.target;
							virtualRows[virtualRows.length] = {
								type: provider.VROWTYPE.GRIDROW,
								dsindex: gridRow.getIndex(),
								visibledsindex: visibleDsIndex++,
								rowheights: detailRowHeights,
								pairgroup: grouprow,
								rowdata: gridRow
							};
							if (grouprow.expanded === true) {
								let childRows: (provider.GridRow | provider.GridRowGroup)[] = grouprow._getRows();
								travelTreeCellRowGroup(childRows);
							}
						}
					};
					travelTreeCellRowGroup(grouprows);
				} else { // GroupingRowGroup
					for (let idx: number = 0; idx < grouprows.length; idx++) {
						let grouprow: provider.GridRowGroup = grouprows[idx] as provider.GridRowGroup;
						visibleDsIndex = this._travelRowgroup(virtualRows, grouprow, rowGroupBands, detailRowHeights, visibleDsIndex);
					}
				}
			}

			if (_isVisibleRowGroupSection(rowgroupband, GRIDREGION.GFOOTER, rowgroup)) {
				virtualRows[virtualRows.length] = {
					type: provider.VROWTYPE.GFOOTER,
					condition: groupCondition,
					rowheights: this._getRowHeights(rowgroupband[GRIDREGION.GFOOTER].rows),
					rowdata: rowgroup
				};
			}
			return visibleDsIndex;
		}

		private _getRowHeights(rows: { rowindex: number, height: number }[]): number[] {
			let rowHeight: number[] = [];
			rows.forEach((rowInfo: { rowindex: number, height: number }) => {
				rowHeight[rowHeight.length] = rowInfo.height;
			});
			return rowHeight;
		}

		private _searchRowGroupBand(groupCondition: string, rowGroupBands: GridRowGroupConfig[]): GridRowGroupConfig {
			let result: GridRowGroupConfig = null;
			rowGroupBands.some((rowgroup: GridRowGroupConfig) => {
				if (groupCondition == rowgroup.groupCondition) {
					result = rowgroup;
					return true;
				}
				return false;
			});
			return result;
		}

		private _setSubGroup(grid: Grid
			, dataProvider: provider.GridDataProvider
			, parent: (provider.GridDataProvider | provider.GridRowGroup)
			, conditions: string[]
			, depth: number
			, beforeGroupState: GroupState[]
			, startTreeCollapseLevel: number): void {

			let rowgroups: provider.GridRowGroup[] = [];
			let startrowindex: number;
			let endrowindex: number;
			let rowgroup: provider.GridRowGroup;
			if (parent instanceof provider.GridRowGroup) {
				startrowindex = parent.startRowIndex;
				endrowindex = parent.endRowIndex;
			} else {
				startrowindex = 0;
				endrowindex = parent.getRowCount() - 1;
			}

			if (conditions[depth] == null) {
				// grouping을 설정하지 않은 경우
				rowgroup = new provider.GridRowGroup(grid, grid.dataSet, null
					, parent instanceof provider.GridDataProvider ? null : parent
					, {});
				this._previousNode = rowgroup;
				for (let i = startrowindex, localIndex = 0; i <= endrowindex; i++, localIndex++) {
					let row: provider.GridRow = dataProvider.getRow(i);
					row._setLocalIndex(localIndex);
					this._wrapTreeCellRowGroup(dataProvider.getRow(i), grid, startTreeCollapseLevel);
				}
				rowgroup._setLocalIndex(rowgroups.length);
				rowgroups[rowgroups.length] = rowgroup;
			} else {
				let beforeValues: { [columnName: string]: any } = {};
				let currentValues: { [columnName: string]: any } = {};
				let nextValues: { [columnName: string]: any } = {};
				let columnNames: string[] = conditions[depth].split(",");
				let initExpanded: boolean = false;
				if (this._context.collapsible == false ||
					(this._context.collapsible == true && this._context._getStartCollapse(conditions[depth]) == false)) {
					initExpanded = true;
				}
				let parentColumnNames: string[] = [];
				for (let i = 0; i < depth; i++) {
					if (conditions[i] != null && conditions[i] != "") {
						parentColumnNames = parentColumnNames.concat(conditions[i].split(","));
					}
				}
				parentColumnNames = _uniq(parentColumnNames);
				let localIndex: number = 0
				for (let i = startrowindex; i <= endrowindex; i++) {
					let conditionValues: { [columnName: string]: string } = {};
					let parentConditionValues: { [columnName: string]: string } = {};
					let isGroupStart: boolean = false;
					let isGroupEnd: boolean = false;

					parentColumnNames.forEach((columnName: string) => {
						parentConditionValues[columnName] = dataProvider.getValue(i, columnName);
					});
					columnNames.forEach((columnName: string) => {
						nextValues[columnName] = (i + 1 <= endrowindex) ? dataProvider.getValue(i + 1, columnName) : undefined;
						currentValues[columnName] = (currentValues[columnName] === undefined) ? dataProvider.getValue(i, columnName) : currentValues[columnName];
						conditionValues[columnName] = currentValues[columnName];
						if (nextValues[columnName] instanceof foundation.DecimalType) {
							nextValues[columnName] = nextValues[columnName].toNumber();
						}
						if (currentValues[columnName] instanceof foundation.DecimalType) {
							currentValues[columnName] = currentValues[columnName].toNumber();
						}
						let beforeValue = beforeValues[columnName];
						let currentValue = currentValues[columnName];
						let nextValue = nextValues[columnName];
						if (beforeValue != currentValue) {
							isGroupStart = true;
						}
						if (currentValue != nextValue) {
							isGroupEnd = true;
						}
						beforeValues[columnName] = currentValues[columnName];
						currentValues[columnName] = nextValues[columnName];
					});
					if (i == startrowindex) { isGroupStart = true; }
					if (i == endrowindex) { isGroupEnd = true; }

					if (isGroupStart) {
						rowgroup = null;
						rowgroup = new provider.GridRowGroup(grid, grid.dataSet, null
							, parent instanceof provider.GridDataProvider ? null : parent
							, {
								conditions: conditionValues
								, parentConditions: parentConditionValues
							});
						this._previousNode = rowgroup;
					}

					let row: provider.GridRow = dataProvider.getRow(i);
					row._setLocalIndex(localIndex++);
					if (depth == conditions.length - 1) {
						this._wrapTreeCellRowGroup(row, grid, startTreeCollapseLevel);
					} else {
						// grouping 된 rowgroup의 endindex를 가져오기 위함
						// 아래 코드에서 결국 삭제됨
						rowgroup._addRow(row, true);
					}

					if (isGroupEnd) {
						if (rowgroup) {
							rowgroup._setLocalIndex(rowgroups.length);
							_setBeforeState(beforeGroupState, rowgroup, parentColumnNames, parentConditionValues, columnNames, conditionValues, initExpanded);
							rowgroups[rowgroups.length] = rowgroup;
							localIndex = 0;
						}
					}
				}
			}

			parent._setRowGroups(rowgroups);
			depth += 1;
			if (depth < conditions.length) {
				rowgroups.forEach((childRowGroup: provider.GridRowGroup) => {
					this._setSubGroup(grid, dataProvider, childRowGroup, conditions, depth, beforeGroupState, startTreeCollapseLevel);
				});
			}
		}

		private _wrapTreeCellRowGroup(gridRow: provider.GridRow, grid: Grid, startCollapseLevel: number): void {
			if (!gridRow) {
				return;
			}
			let currentLevel: (string | number) = null;
			if (this._treeCellLevelColNm) {
				let value: (string | number | foundation.DecimalType | ufc.StyledString) = gridRow.getValue(this._treeCellLevelColNm);
				if (value instanceof ufc.StyledString) {
					throw new exceptions.IllegalArgumentException("Illegal TreeCell level value(StyledString. " + currentLevel + "). TreeCell level column value must be number.");
				} else if (value instanceof foundation.DecimalType) {
					currentLevel = value.toString();
				} else {
					currentLevel = value;
				}
			} else if (this._treeCellLevelExp) {
				currentLevel = this._treeCellLevelExp._evaluateInternal({
					_getExpressionDelegates(): any[] {
						return [gridRow, grid, grid.dataSet]
					}
				});
			} else {
				currentLevel = this._treeCell.level;
			}
			let iCurLvl: number = Number(currentLevel);
			if (isNaN(iCurLvl)) {
				throw new exceptions.IllegalArgumentException("Illegal TreeCell level value(" + currentLevel + "). TreeCell level column value must be number.");
			} else if (iCurLvl < Number(this._treeCell.startLevel)) {
				currentLevel = this._treeCell.startLevel;
				iCurLvl = Number(this._treeCell.startLevel);
			}

			let parentRowGroup: provider.GridRowGroup = this._previousNode;
			while (true) {
				let prevLvl: string = parentRowGroup._getOption("level");
				if (parentRowGroup.target && prevLvl) { // TreeCell Node
					let iPrevLvl: number = Number(prevLvl);
					if (iPrevLvl < iCurLvl) {
						// Parent RowGroup
						break;
					} else {
						// go Parent
						parentRowGroup = parentRowGroup.parent;
					}
				} else {
					// Grouping Row
					break;
				}
			}
			let rowGroup: provider.GridRowGroup = new provider.GridRowGroup(grid, grid.dataSet, gridRow,
				parentRowGroup instanceof provider.GridDataProvider ? null : parentRowGroup,
				{
					level: currentLevel
					, rowIndex: gridRow.getIndex() // TODO remove
				});
			let expand: string = gridRow._getExpandSts();
			let expanded: boolean = true;
			if (expand) {
				expanded = (expand == "false" ? false : true);
			} else if (startCollapseLevel != -1 && iCurLvl >= startCollapseLevel) {
				expanded = false;
			}

			rowGroup._setExpanded(expanded);
			parentRowGroup._addRow(rowGroup, true);

			this._previousNode = rowGroup;

			// treecell checked
			if (this._treeCellShowCheckbox === true && rowGroup.target) {
				let checkedState: boolean = TreeRowGroupBuilder._getCheckedSts(grid, rowGroup.target);
				if (checkedState === true) {
					this._checkedRowGroups[this._checkedRowGroups.length] = rowGroup;
				}
			}
		}

		private _getGroupState(rowGroups: provider.GridRowGroup[]): GroupState[] {
			let result: GroupState[] = [];

			if (rowGroups == null
				|| rowGroups.length == 0
				|| (rowGroups[0] && rowGroups[0] instanceof provider.GridRow)) {
				return result;
			}

			for (let idx: number = 0; idx < rowGroups.length; idx++) {
				let rowGroup: provider.GridRowGroup = rowGroups[idx];
				let conditionKeys: string = GridRowGroupBuilder._getConditionKeys(rowGroup);
				if (conditionKeys == null) {
					continue;
				}
				let parentConditionKeys: string = GridRowGroupBuilder._getParentConditionKeys(rowGroup);
				// let initExpanded: boolean = this._context._getStartCollapse(conditionKeys) == false;
				// if (rowGroup.expanded != initExpanded) {
				result[result.length] = {
					conditionKeys: conditionKeys,
					conditions: GridRowGroupBuilder._getConditions(rowGroup),
					p_conditionKeys: parentConditionKeys,
					p_conditions: GridRowGroupBuilder._getParentConditions(rowGroup),
					expanded: rowGroup.expanded,
					enabled_checkbox: rowGroup._isEnabledCheckbox(),
					visible_checkbox: rowGroup._isVisibleCheckbox(),
					start: rowGroup.startRowIndex,
					end: rowGroup.endRowIndex
				};
				// }

				result = result.concat(this._getGroupState(rowGroup._getRows() as provider.GridRowGroup[]));
			}
			return result;
		}

		private _setTreeCellInfo(): boolean {
			this._treeCellLevelColNm = null;
			this._treeCellLevelExp = null;
			this._treeCellShowCheckbox = false;

			if (!this._treeCell) {
				return false;
			}

			this._treeCellShowCheckbox = this._treeCell.showCheckbox;

			let levelInfo: bind.BindInfo = this._treeCell.getBindInfo("level");
			if (!levelInfo) {
				return true; // 상수인 경우
			}
			let levelColNm: string = levelInfo.columnName;
			if (levelColNm) {
				let dataSet: data.DataCollection = this._context.getGrid().dataSet;
				if (dataSet && dataSet.isExistColumn(levelColNm) == false) {
					return true;
				}
				this._treeCellLevelColNm = levelColNm;
				return true;
			}
			let expText: string = levelInfo.expression;
			if (expText) {
				this._treeCellLevelExp = new expression.Expression(expText);
				return true;
			}
			return false;
		}

	}

	/**
	 * @private
	 */
	export class RowGroupBuilderFactory {
		public static _createRowGroupBuilder(context: GridContext, groupConditions: string[], detailCellProps: GridDetailCellProp[]): RowGroupBuilder {
			// check teecell
			let treeCell: renderer.TreeCell = null;
			let hasTreeCell: boolean = detailCellProps.some((item: GridDetailCellProp) => {
				let uicontrol: GridUIControl = item.configuration.control;
				if (uicontrol && uicontrol instanceof renderer.TreeCell) {
					treeCell = uicontrol as renderer.TreeCell;
					return true;
				}
				return false;
			});

			if (groupConditions != null && hasTreeCell === true) {
				// group + tree builder
				return new GroupedTreeCellBuilder(context, groupConditions, treeCell);
			} else if (groupConditions != null) {
				// group builder
				return new GridRowGroupBuilder(context, groupConditions);
			} else if (hasTreeCell === true) {
				// tree builder
				return new TreeRowGroupBuilder(context, treeCell);
			}

			return null;
		}

	}
}