/// <reference path="./TreeDataProvider.ts"/>


namespace cpr.controls.provider {
	/**
	 * value, label, parentValue, icon, accessKey로 구성된 메뉴 형태의 데이터를 관리하는 상위 클래스.
	 * @private
	 */
	export class MenuDataProvider extends AbstractTreeDataProvider<MenuItem, MenuItemSetConfig, any> {

		protected _copyItem(item: MenuItem): MenuItem {
			return new MenuItem(item._getDataAccessor());
		}

		protected updateRow(source: MenuItem, row: data.Row) {
			row.setValue(this.itemSetConfig.label, source.label)
			row.setValue(this.itemSetConfig.value, source.value)
			if (this.itemSetConfig.parentValue) {
				row.setValue(this.itemSetConfig.parentValue, source.parentValue);
			}
			if (this.itemSetConfig.icon) {
				row.setValue(this.itemSetConfig.icon, source.icon);
			}
			if (this.itemSetConfig.tooltip) {
				row.setValue(this.itemSetConfig.tooltip, source.tooltip);
			}
			if (this.itemSetConfig.accessKey) {
				row.setValue(this.itemSetConfig.accessKey, source.accessKey)
			}
		}

		protected convertRowToItem(row: data.Row): MenuItem {

			let menuItem = new MenuItem(row, this);
			return menuItem;
		}
	}
}