/// <reference path="./HorizontalBar.ts" />
namespace cpr.controls.navigation {

	/**
	 * @private
	 */
	export class MegaMenuBar extends HorizontalBar implements INavigationBar {

		/**
		 * 내비게이션 바를 생성합니다.
		 * @param id 내비게이션 바의 id
		 */
		constructor(owner: NavigationBar, binder: provider.MenuDataBinder) {
			super(owner, binder);

		}

		/* shape */
		protected override _createPopupMenu(): ufc.ElementShape {

			let popupMenu = super._createPopupMenu();
			if (popupMenu == null) {
				return null;
			}
			let menu = this._getActiveMenu();

			let oldGlobalShape = this._owner._getRenderer()._getNamedShape(menu.getRootNodeName());
			if (oldGlobalShape != null) {
				if (oldGlobalShape.style["width"] != null) {
					popupMenu.style["width"] = oldGlobalShape.style["width"];
				}
			} else {
				let domTraverser = ufc._traverseFromElement(this._owner._getRenderer().getRootNode());
				if (domTraverser) {
					popupMenu.style["width"] = domTraverser._getElement().offsetWidth + "px";
				}
			}

			return popupMenu;
		}

		/**
		 * 일반 메뉴에서 키 바인드
		 * @param e 
		 */
		protected _navigateBar(e: events.CKeyboardEvent, item: MenuItem) {
			super._navigateBar(e, item);
			let hoveredItem = this._getHoveredItem();
			let menu = null;
			if (this._isOpened(hoveredItem)) {
				menu = this._getActiveMenu();
			}
			let keyCode = e.keyCode;
			switch (keyCode) {
				case events.KeyCode.LEFT:
					e.preventDefault();
					if (item == null) {
						this._hoverBackward(item);
					} else if (item.depth > 0) {

						let traversedHover = menu ? menu.traverseHover(keyCode, item) : null;

						if (!traversedHover) {
							this._resetMenu();
						} else {
							let rootItem = this._getParent(traversedHover, (each) => {
								return each.depth == 0;
							});
							this._setHoveredItem(rootItem, { doInitSubMenu: true, nativeEvent: e });
						}
					} else {
						this._hoverBackward(item);
					}
					break;
				case events.KeyCode.RIGHT: {
					e.preventDefault();
					if (item == null) {
						this._hoverForward(item);
					} else if (item.depth > 0) {
						let traversedHover = menu ? menu.traverseHover(keyCode, item) : null;
						if (!traversedHover) {
							this._resetMenu();
						} else {
							let rootItem = this._getParent(traversedHover, (each) => {
								return each.depth == 0;
							})
							this._setHoveredItem(rootItem, { doInitSubMenu: true, nativeEvent: e });
						}
					} else {
						this._hoverForward(item);
					}
					break;

				}
				case events.KeyCode.UP:
					e.preventDefault();
					if (item == null) break;

					if (item.depth > 0) {
						let traversedHover = menu ? menu.traverseHover(keyCode, item) : null;
						if (!traversedHover) {
							this._resetMenu();
						}
					} else if (item._hasChild()) {
						let traversedHover = menu ? menu._transferHoverBackward(item.children[0] as MenuItem) : null;
						if (!traversedHover) {
							this._hoverBackward(item);
						}
					} else {
						this._hoverBackward(item);
					}
					break;
				case events.KeyCode.DOWN: {
					e.preventDefault();
					if (item == null) break;

					if (item.depth > 0) {
						let traversedHover = menu ? menu.traverseHover(keyCode, item) : null;
						if (!traversedHover) {
							let rootItem = this._getParent(item, (each) => {
								return each.depth == 0;
							})
							this._hoverForward(rootItem);
						}

					} else if (item._hasChild()) {
						let traversedHover = menu ? menu._transferHoverDownCycle(item) : null;
						if (!traversedHover) {
							this._hoverForward(item);
						}
					} else {
						this._hoverForward(item);
					}
					break;
				}
				case events.KeyCode.TAB: {
					if (this._owner.tabTraversal == false) {
						return;
					}

					if (this._traverseTabKey(!e._getMod2Key(), item, e)) {
						e.preventDefault();
						return;
					}
					break;
				}
			}
		}

		/* private method */
		/* event start */
		private _traverseTabKey(forward: boolean, item: MenuItem, nativeEvent: events.CKeyboardEvent) {
			if (forward == false && item == null) {
				return false;
			}

			let root = new cpr.controls.MenuItem("", "@root", "");
			root._setChildren(this._getRootItems());
			root._setOpen(true);

			let items = [];
			let isOpened = this._getOpenedItem() != null;
			if (isOpened) {
				items = _createTreeStream(root, false, (each: MenuItem) => {
					if ((each.value != "@root" && each.parentItem == null) && (this._isOpened(each) == false || this._owner.getItemEnable(each) == false)) {
						return [];
					}
					return each.children;
				}).collect() as MenuItem[];
			} else {
				items = this._rootItems;
			}

			let findIndex = forward ? -1 : items.length;
			if (item) {
				findIndex = _.findIndex(items, (each) => {
					return each.value == item.value;
				});
			}
			let len = items.length;
			let delta = forward ? 1 : -1;
			let i = findIndex + delta;
			let nextItem = null;
			while (len > i || i < 0) {
				if (this._owner.getItemEnable(items[i])) {
					nextItem = items[i];
					i = len;
				} else {
					i = i + delta;
				}
			}

			if (!nextItem) {
				return false;
			}

			this._setHover(nextItem, { nativeEvent: nativeEvent });
			return true;
		}

	}
}