namespace cpr.controls.gridpart.layout {


	export class ScrollbarCustomAdapter implements IScrollbarAdapter, internal.IVirtualScrollPane {
		private _scrollStrategy: IGridScrollbarOwner;

		private _virtualVScrollbar: internal.VirtualVScrollbar;
		private _virtualHScrollbar: internal.VirtualHScrollbar;

		private _contentWidth: number = -1;
		private _contentHeight: number = -1;


		constructor(scrollStrategy: IGridScrollbarOwner) {
			this._scrollStrategy = scrollStrategy;

			this._virtualHScrollbar = new internal.VirtualHScrollbar(this);
			this._virtualVScrollbar = new internal.VirtualVScrollbar(this);
		}

		public _isEnabled(): boolean {
			return this._scrollStrategy._isEnabled();
		}

		public _setContentWidth(width: number): void {
			this._contentWidth = width;
		}

		public _getContentWidth(): number {
			return this._contentWidth;
		}

		public _setContentHeight(height: number): void {
			this._contentHeight = height;
		}

		public _getContentHeight(): number {
			return this._contentHeight;
		}

		public _getQName(name: string): string {
			return this._scrollStrategy._getQNamePrefix() + "-" + name;
		}

		public _checkResize(): void {
			// DO NOTHING~!
		}

		public _setScrollTop(e: events.CUIEvent, scrollTop: number): number {
			return this._scrollStrategy._setViewportScrollTop(e, scrollTop);
		}
		public _setScrollLeft(e: events.CUIEvent, scrollLeft: number): number {
			return this._scrollStrategy._setViewportScrollLeft(e, scrollLeft);
		}

		_getRenderer(): ufc.ControlRenderer {
			return this._scrollStrategy._getRenderer();
		}

		public _getActiveVScrollTop(): number {
			return this._scrollStrategy.virtualscrolltop;
		}

		public _getVScrollbarWidth(): number {
			return this._virtualVScrollbar._getWidth();
		}

		public _getHScrollbarHeight(): number {
			return this._virtualHScrollbar._getHeight();
		}

		public _createVScrollbar(scrollTop: number, contentHeight: number): ufc.ElementShape {
			return this._virtualVScrollbar._createScrollbar(scrollTop, contentHeight);
		}

		public _createDummyVScrollbar(): ufc.ElementShape {
			return {
				tag: "div",
				attr: {},
				classNames: [GridStyle.BLANK],
				style: {
					display: "none",
					position: "absolute",
					bottom: "0px",
					left: "0px",
					right: "0px",
					height: "0px"
				},
				children: []
			};
		}

		public _createHScrollbar(scrollLeft: number, contentWidth: number): ufc.ElementShape {
			return this._virtualHScrollbar._createScrollbar(scrollLeft, contentWidth);
		}

		public _createDummyHScrollbar(): ufc.ElementShape {
			return {
				tag: "div",
				attr: {},
				classNames: [GridStyle.BLANK],
				style: {
					display: "none",
					position: "absolute",
					bottom: "0px",
					left: "0px",
					right: "0px",
					height: "0px"
				},
				children: []
			};
		}

		public _setVScrollTop(scrollTop: number): void {
			this._virtualVScrollbar._setScrollTop(scrollTop);
		}

		public _setHScrollLeft(scrollLeft: number): void {
			this._virtualHScrollbar._setScrollLeft(scrollLeft);
		}

		public _getViewportWidth(): number {
			return this._scrollStrategy._getViewportWidth();
		}

		public _getViewportHeight(): number {
			return this._scrollStrategy._getViewportHeight();
		}

	}
}