// 내부 개발자 전용 범용 유틸리티를 함수들을 이곳에 위치 하십시오.
namespace cpr {
	/**
	 * 주어진 문맥을 입력으로하는 함수를 호출 후, 원래 문맥을 반환 합니다.
	 * 
	 * @param context 문맥.
	 * @param task 해당 문맥을 입력으로 하는 작업 함수.
	 * @returns 주어졌던 문맥.
	 */
	export function _tap<T>(context: T, task: (input: T) => void): T {
		task(context);
		return context;
	}

	export function _performWith<T>(context: T, task: (context: T) => void): T {
		task(context);
		return context;
	}

	export function _evaluateWith<T, R>(context: T, task: (context: T) => R): R {
		return task(context);
	}

	export function _isNullOrEmpty(value: any): boolean {
		switch (typeof value) {
			case "undefined":
				return true;

			case "string":
				return value.length === 0;

			case "object":
				if (value == null) {
					return true;
				}
				// ArrayLike
				else if ("length" in value && value.length === 0) {
					return true;
				}

				// DimensionLike
				else if (_stream(["width", "height"]).forall(it => it in value)
					&& _stream(["width", "height"]).exists(it => value[it] === 0)) {
					return true;
				}

				// 자체 isEmpty() 함수 구현	
				else if (typeof value.isEmpty == "function") {
					return value.isEmpty();
				}

				else {
					return false;
				}

			default:
				return false;


		}
	}

	export function _isNull(obj: any): obj is null | undefined {
		return obj == null;
	}

	export function _areEquals<T>(obj1: T, obj2: T): boolean {
		if (obj1 == obj2) {
			return true;
		}
		if (obj1 == null || obj2 == null) {
			return false;
		}
		if (typeof obj1["equals"] == "function") {
			return obj1["equals"](obj2) === true;
		} else {
			return false;
		}
	}

	/**
	 * 주어진 파일 경로를 CSS 스타일 url() 형식으로 쿼트합니다.
	 * @param path 파일
	 * @returns 주어진 파일에 대한 url 표현식.
	 */
	export function _quoteAsCSSURL(path: string) {
		return `url('${path.replace("'", "\\'")}')`;
	}

	export function _isOneOfEnumValue<T>(value: T, enumerator: { [key: string]: T }): boolean {
		return Object.keys(enumerator).some(key => enumerator[key] === value);
	};


	export function _randomInt(min: number, max: number): number {
		return Math.floor(Math.random() * (max - min + 1)) + min;
	}
}