namespace cpr.events {


	/**
	 * @private
	 */
	export class AndroidResizeHandler {
		private static INSTANCE: AndroidResizeHandler;


		public static _getInstance(): AndroidResizeHandler {
			if (!AndroidResizeHandler.INSTANCE) {
				AndroidResizeHandler.INSTANCE = new AndroidResizeHandler();
			}
			return AndroidResizeHandler.INSTANCE;
		}


		private _orientation: number; // 0 or 90
		private _landscapeHeight: number = 0;
		private _portraitHeight: number = 0;
		private _lastHeight: number;
		private _keyboardOpened: boolean = false;


		constructor() {
			this._checkWindowSize(true);
			this._fixBodySize();
		}

		public _isKeyboardOpened(): boolean {
			return this._keyboardOpened;
		}

		private _checkWindowSize(force: boolean): boolean {
			let h: number = window.innerHeight;
			let changed: boolean = false;

			if (this._isLandscape()) {
				if (force || this._landscapeHeight < h) {
					this._landscapeHeight = h;
					changed = true;
				}
			} else {
				if (force || this._portraitHeight < h) {
					this._portraitHeight = h;
					changed = true;
				}
			}
			this._lastHeight = h;

			return changed;
		}

		private _isLandscape(): boolean {
			let orientation: string = (screen.orientation || {}).type || screen["mozOrientation"] || screen["msOrientation"];
			if (orientation) {
				switch (orientation) {
					case "landscape-primary":
					case "landscape-secondary":
						this._orientation = 90;
						return true;
					default:
						this._orientation = 0;
						return false;
				}
			}
			let orient: number = window.orientation as number;
			if (orient === -90 || orient === 90) {
				this._orientation = 90;
				return true;
			}

			this._orientation = 0;
			return false;
		}

		private _fixBodySize(): void {
			let h: number = 0;
			if (this._orientation === 0) {
				h = this._portraitHeight;
			} else {
				h = this._landscapeHeight;
			}

			document.body.style.minHeight = h + "px";
		}

		private _checkKeyboardStateChange(): boolean {
			let keyboardOpened: boolean = this._keyboardOpened;
			let h: number = window.innerHeight;
			if (this._orientation === 0) {
				if (h < this._portraitHeight) {
					keyboardOpened = true;
				} else {
					keyboardOpened = false;
				}
			} else {
				if (h < this._landscapeHeight) {
					keyboardOpened = true;
				} else {
					keyboardOpened = false;
				}
			}
			if (this._keyboardOpened != keyboardOpened) {
				this._keyboardOpened = keyboardOpened;
				return true;
			}
			return false;
		}

		public _getResizeHandler(): (e: Event) => void {
			return this._handle.bind(this);
		}

		private _handle(e: Event): void {
			if (e.type !== "resize") {
				return;
			}
			let beforeHeight: number = this._lastHeight;
			let beforeOrientation: number = this._orientation;
			let changed: boolean = this._checkWindowSize(false);
			if (changed || beforeOrientation != this._orientation) {
				this._fixBodySize();
				BodyEventTarget.INSTANCE._processEvent(e);
			} else {
				let keyboardStateChanged: boolean = this._checkKeyboardStateChange();
				if (keyboardStateChanged || beforeHeight != this._lastHeight) {
					if (this._keyboardOpened) {
						let inputFieldActived: boolean = false;
						let activeElement: HTMLElement = document.activeElement as HTMLElement;
						if (activeElement) {
							let tagName: string = activeElement.tagName.toLowerCase();
							inputFieldActived = tagName == "input" || tagName == "textarea";
						}
						if (inputFieldActived) {
							let eventType: string = this._keyboardOpened ? core.SystemTopics.KEYBOARD_OPEN : core.SystemTopics.KEYBOARD_CLOSE;
							let eventWrapper: cpr.events.CEvent = cpr.events.wrap(e);
							core.NotificationCenter.INSTANCE.post(eventType, eventWrapper, this);
						} else {
							// 실제 창크기가 줄어든 경우
							this._checkWindowSize(true);
							this._fixBodySize();
							BodyEventTarget.INSTANCE._processEvent(e);
						}
					} else {
						let eventType: string = this._keyboardOpened ? core.SystemTopics.KEYBOARD_OPEN : core.SystemTopics.KEYBOARD_CLOSE;
						let eventWrapper: cpr.events.CEvent = cpr.events.wrap(e);
						core.NotificationCenter.INSTANCE.post(eventType, eventWrapper, this);
					}
				}
			}
		}
	}
}