namespace cpr.controls.gridpart.config {

	type column_type_string = "normal" | "checkbox";

	export class GridHeaderCellConfigurator extends GridCellConfigurator {
		private _columnType: column_type_string = "normal";

		private _visible: boolean = true;
		private _sortColumnName: column_name_string = null;
		private _sortable: boolean = false;
		private _filterable: boolean = false;
		private _targetColumnName: column_name_string = null;
		private _emptyValueSort: EMPTYVALUESORT = null;
		private _sortKeyExpression: expression_string = null;
		private _filterDialogPosition: FilterDialogPosition = null;


		constructor(grid: Grid) {
			super(grid);

			this._bindables.add("text", null).withSetterValidatorWithType(false, "string");
			this._bindables.add("filterDialogTitle", null).withSetterValidatorWithType(false, "string");
		}

		/**
		 * 기본 컬럼일 경우 column의 종류를 설정합니다.<br>
		 * header : "checkbox", "normal"
		 * @param columnType 컬럼의 종류.
		 */
		set columnType(columnType: column_type_string) {
			this._columnType = columnType;
		}

		/**
		 * 기본 컬럼일 경우 column의 종류를 반환합니다.<br>
		 * header : "rowindex", "checkbox", "normal"
		 * @return 컬럼의 종류.
		 */
		get columnType(): column_type_string {
			return this._columnType;
		}

		/**
		 * 헤더에 보여질 문자열을 설정합니다.
		 * @param text 헤더에 보여질 문자열.
		 */
		set text(text: string) {
			this._bindables.set("text", text);
		}

		/**
		 * 헤더에 보여질 문자열을 반환합니다.
		 * @return 헤더에 보여질 문자열.
		 */
		get text(): string | ufc.StyledString {
			return this._bindables.get("text");
		}

		/**
		 * 해당 셀 클릭시 정렬할 데이터셋 컬럼명을 설정합니다.
		 * 헤더셀의 소트관련 다른 설정인 targetColumnName과 sortable 속성과 양립할 수 없습니다.
		 * 둘다 설정된 경우 targetColumnName과 sortable 속성이 적용됩니다.
		 * @param sortColumnName 정렬할 데이터셋 컬럼명.
		 */
		set sortColumnName(sortColumnName: column_name_string) {
			this._sortColumnName = sortColumnName;
		}

		/**
		 * 해당 셀 클릭시 정렬 설정한 데이터셋 컬럼명을 반환합니다.
		 * 헤더셀의 소트관련 다른 설정인 targetColumnName과 sortable 속성과 양립할 수 없습니다.
		 * 둘다 설정된 경우 targetColumnName과 sortable 속성이 적용됩니다.
		 * @return 정렬 설정한 데이터셋 컬럼명.
		 */
		get sortColumnName(): column_name_string {
			return this._sortColumnName;
		}

		/**
		 * 해당 헤더 셀이 위치한 컬럼 전체의 visible을 설정합니다.
		 * @param visible 해당 셀의 visible 설정.
		 */
		set visible(visible: boolean) {
			this._visible = visible;
		}

		/**
		 * 해당 헤더 셀이 위치한 컬럼 전체의 visible 설정값을 반환합니다.
		 * @return 해당 셀의 visible 설정.
		 */
		get visible(): boolean {
			return this._visible;
		}

		/* 상명대 요구사항 20180602 */
		/**
		 * 해당 셀의 filterable, sortable 사용시 해당 기능의 타겟 데이터셋 컬럼명을 설정합니다.
		 * @param targetColumnName 타겟 데이터셋 컬럼명.
		 */
		set targetColumnName(targetColumnName: column_name_string) {
			this._targetColumnName = targetColumnName;
			if (targetColumnName != null) {
				this.grid.dataProvider._addFilterCondition(targetColumnName, [provider.GridDataProvider.FILTER_ALL]);
			}
		}

		/**
		 * 해당 셀의 filterable, sortable 사용시 해당 기능의 타겟 데이터셋 컬럼명 설정값을 반환합니다.
		 * @return 타겟 데이터셋 컬럼명.
		 */
		get targetColumnName(): column_name_string {
			return this._targetColumnName;
		}

		/**
		 * 해당 셀에 targetColumnName으로 지정된 컬럼 값을 통한 다중 정렬 기능을 사용할지 여부를 설정합니다.
		 * 헤더셀의 소트관련 다른 설정인 sortColumnName 속성과 양립할 수 없습니다.
		 * targetColumnName이 지정되고 sortable이 true로 설정된 헤더셀에 sortColumnName이 지정된 경우 targetColumnName과 sortable 속성이 적용됩니다.
		 * @param sortable 다중 정렬 기능 설정값.
		 */
		set sortable(sortable: boolean) {
			this._sortable = sortable;
		}

		/**
		 * 해당 셀에서 다중 정렬 기능 설정값을 반환합니다.
		 * @return 다중 정렬 기능 설정값.
		 */
		get sortable(): boolean {
			return this._sortable;
		}

		/**
		 * 해당 셀에 targetColumnName으로 지정된 컬럼 값을 통한 다중 필터 기능을 사용할지 여부를 설정합니다.
		 * @param filterable 다중 필터 기능 설정값.
		 */
		set filterable(filterable: boolean) {
			this._filterable = filterable;
		}

		/**
		 * 해당 셀에 targetColumnName으로 지정된 컬럼 값을 통한 다중 필터 기능 설정값을 반환합니다.
		 * @return 다중 필터 기능 설정값.
		 */
		get filterable(): boolean {
			return this._filterable;
		}
		/* 상명대 요구사항 20180602 */

		/**
		 * filterable 속성 사용시 filter dialog의 title을 설정합니다.
		 * @param filterDialogTitle 설정할 filter dialog의 title.
		 */
		set filterDialogTitle(filterDialogTitle: string) {
			this._bindables.set("filterDialogTitle", filterDialogTitle);
		}

		/**
		 * filterable 속성 사용시 filter dialog의 title 값을 반환합니다.
		 * @return 설정한 filter dialog의 title.
		 */
		get filterDialogTitle(): string {
			return this._bindables.get("filterDialogTitle");
		}

		/**
		 * filterable 속성 사용시 filter dialog의 위치를 설정합니다.
		 * @param filterDialogPosition 설정할 filter dialog의 위치.
		 * @see FilterDialogPosition
		 */
		set filterDialogPosition(filterDialogPosition: FilterDialogPosition) {
			this._filterDialogPosition = filterDialogPosition;
		}

		/**
		 * filterable 속성 사용시 filter dialog의 위치를 반환합니다.
		 * @return 설정한 filter dialog의 위치.
		 * @see FilterDialogPosition
		 */
		get filterDialogPosition(): FilterDialogPosition {
			return this._filterDialogPosition;
		}

		/**
		 * 헤더 정렬 사용(sortable=true)시 빈 값에 대한 처리를 설정합니다.
		 * @param 정렬시 빈 값이 대한 처리
		 */
		set emptyValueSort(emptyValueSort: EMPTYVALUESORT) {
			this._emptyValueSort = emptyValueSort;
		}

		/**
		 * 헤더 정렬 사용(sortable=true)시 빈 값에 대한 처리를 반환합니다.
		 * @return 정렬시 빈 값이 대한 처리
		 */
		get emptyValueSort(): EMPTYVALUESORT {
			return this._emptyValueSort;
		}

		/**
		 * 헤더 정렬 사용(sortable=true)시 정렬될 기준을 표현식으로 설정합니다.
		 * ex. targetColumnName이 column1인 컬럼에서 column2 기준으로 정렬하고 싶을 때,'column2'로 설정.
		 * @param sortKeyExpression 정렬될 값의 표현식.
		 */
		set sortKeyExpression(sortValueExpression: expression_string) {
			this._sortKeyExpression = sortValueExpression;
		}

		/**
		 * 헤더 정렬 사용(sortable=true)시 정렬될 기준 표현식을 반환합니다.
		 * @return sortKeyExpression 정렬될 값의 표현식.
		 */
		get sortKeyExpression(): expression_string {
			return this._sortKeyExpression;
		}



	}
}
