namespace cpr.controls.gridpart.config {

	export class GridFooterCellConfigurator extends GridCellConfigurator {
		private _expr: expression_string;

		constructor(grid: Grid) {
			super(grid);
		}

		/**
		 * 셀에 나타낼 expression 식을 설정합니다.
		 * @param expr 셀에 나타낼 expression 식.
		 */
		set expr(expr: expression_string) {
			this._expr = expr;
		}

		/**
		 * 셀에 나타낸 expression 식을 반환합니다.
		 * @return 셀에 나타낸 expression 식.
		 */
		get expr(): expression_string {
			return this._expr;
		}


	}
}