/// <reference path="../../provider/GridDataProvider.ts"/>


namespace cpr.controls.gridpart.layout {


	/**
	 * @private
	 */
	export class RowGroupBufferedScrollStrategy extends BufferedScrollStrategy {

		constructor(scrollPane: ScrollPane, context: GridContext) {
			super(scrollPane, context);
		}

		/**
		 * moveposition.jumpedIndex 설정
		 * @param moveposition 
		 * @param startrowindex 
		 * @param endrowindex 
		 */
		protected _getTargetRowIndex(moveposition: { srcIndex: number, offset: number, jumpIndex: number, jumpedIndex: number, isDataRow: boolean }
			, startrowindex: number, endrowindex: number): number {

			let virtualRows: provider.VirtualRow[] = this.grid._getVirtualRows();

			let jumpVIdx: number = -1; // 이동할 VirtualRow의 인덱스
			if (moveposition.isDataRow == false) {
				// 데이터행 기준으로 이동하지 않는 경우
				if (startrowindex <= moveposition.jumpIndex && moveposition.jumpIndex <= endrowindex) {
					jumpVIdx = moveposition.jumpIndex;
				}
			} else if (moveposition.jumpIndex > -1) {
				// 인덱스를 지정해서 이동하는 경우 DataSet의 인덱스를 VirtualRow Index로 변환
				moveposition.jumpedIndex = moveposition.jumpIndex;
				for (let index: number = startrowindex; index <= endrowindex; index++) {
					let virtualRow: provider.VirtualRow = virtualRows[index];
					if (virtualRow.dsindex == moveposition.jumpIndex) {
						jumpVIdx = index;
						break;
					}
				}
			} else {
				// offset으로 이동하는 경우 이동가능한 realrow의 VirtualRow Index를 찾음
				let currentRowIndex: number = moveposition.srcIndex;

				// srcIndex는 DataSet의 Index이므로 VirtualRow의 Index로 변환
				let currentVIdx: number = -1;
				let firstRealRowIdx: number = -1;
				for (let index: number = startrowindex; index <= endrowindex; index++) {
					let virtualRow: provider.VirtualRow = virtualRows[index];
					if (firstRealRowIdx == -1 && virtualRow.type == provider.VROWTYPE.GRIDROW) {
						firstRealRowIdx = index;
					}
					if (virtualRow.dsindex == currentRowIndex) {
						currentVIdx = index;
						break;
					}
				}
				if (currentVIdx == -1) {
					moveposition.jumpedIndex = firstRealRowIdx;
					return -1;
				}
				if (moveposition.offset < 0) { // 위로
					outter: for (let idx: number = currentVIdx, cnt: number = 0; idx >= startrowindex && cnt >= moveposition.offset; idx-- , cnt--) {
						let virtualRow: provider.VirtualRow = virtualRows[idx];
						if (virtualRow.rowdata instanceof provider.GridRow) {
							jumpVIdx = idx;
							moveposition.jumpedIndex = virtualRow.dsindex;
						} else if (cnt == moveposition.offset) {
							for (; idx >= startrowindex; idx--) {
								virtualRow = virtualRows[idx];
								if (virtualRow.rowdata instanceof provider.GridRow) {
									jumpVIdx = idx;
									moveposition.jumpedIndex = virtualRow.dsindex;
									break outter;
								}
							}
						}
					}
				} else { // 아래로
					outter: for (let idx: number = currentVIdx, cnt: number = 0; idx <= endrowindex && cnt <= moveposition.offset; idx++ , cnt++) {
						let virtualRow: provider.VirtualRow = virtualRows[idx];
						if (virtualRow.rowdata instanceof provider.GridRow) {
							jumpVIdx = idx;
							moveposition.jumpedIndex = virtualRow.dsindex;
						} else if (cnt == moveposition.offset) {
							for (; idx <= endrowindex; idx++) {
								virtualRow = virtualRows[idx];
								if (virtualRow.rowdata instanceof provider.GridRow) {
									jumpVIdx = idx;
									moveposition.jumpedIndex = virtualRow.dsindex;
									break outter;
								}
							}
						}
					}
				}
				if (currentVIdx == -1 || jumpVIdx == -1) {
					moveposition.jumpedIndex = firstRealRowIdx;
					return -1;
				}
			}
			return jumpVIdx;
		}
	}
}