/// <reference path="./DataProvider.ts"/>

namespace cpr.controls.provider {

	/**
	 * ObjectMap이 IE에서 성능에 영향이 있어 탐색이 더 빠른 오브젝트를 사용.(#6508)
	 * @private
	 */
	export class ItemMap<ValueType> {
		private _map: CMap<string, ValueType>;
		private _validator: (item: ValueType, itemMap: ItemMap<ValueType>) => void
		private _prototypeObject = null;

		constructor() {
			this._map = _createMap<string, ValueType>();
			this._prototypeObject = Object.getPrototypeOf({});
		}
		public get setterValidator() {
			return this._validator;
		}
		public set setterValidator(validator: (item: ValueType, itemMap: ItemMap<ValueType>) => void) {
			this._validator = validator;
		}
		private _convertAvailableKey(key: string) {
			if (this._prototypeObject[key]) {
				return key + "@"
			}
			return key;
		}
		public get(key: string) {
			key = this._convertAvailableKey(key);
			return this._map.get(key);
		}
		public set(key: string, value: ValueType) {
			key = this._convertAvailableKey(key);
			if (this._validator) this._validator(value, this);
			this._map.set(key, value);
		}
		public remove(key: string) {
			key = this._convertAvailableKey(key);
			this._map.delete(key);
		}
		public removeAll() {
			this._map.clear();
		}
	}

	/**
	 * @private
	 */
	export class ItemChecker {

		protected _info: { ownerId: string, ownerType: string, multiple: boolean, delimiter: string };
		protected _error: { id: string, type: string, value: string, parentValue?: string, message: string };

		constructor(info: { ownerId: string, ownerType: string, multiple: boolean, delimiter: string }) {
			this._info = info;
		}
		protected _hasError() {
			return this._error != null;
		}

		protected _warning(error: { id: string, type: string, value: string, parentValue?: string, message: string }) {
			let parentValuePart = error.parentValue !== undefined ? `, parentValue: ${error.parentValue}` : '';
			let content = `controltype: ${error.type}, id: ${error.id}, value: ${error.value}${parentValuePart}`;
			let message = `${error.message}: [${content}]`;
			console.warn(message);
		}

		protected _exception() {
			if (!this._hasError()) {
				return;
			}
			let content = `controltype: ${this._error.type}, id: ${this._error.id}, value: ${this._error.value}`;
			if (this._error.parentValue != null) content += ", parentValue: " + this._error.parentValue;
			let message = this._error.message + ": [" + content + "]";
			throw new cpr.exceptions.CError(message);
		}

		protected _createError(message: string, item: Item) {
			return { message: message, id: this._info.ownerId, type: this._info.ownerType, value: item.value }
		}

		/**
		 * 아이템의 값이 중복되는지 확인합니다.
		 * @param item 
		 * @param checkItemMap 
		 * @param immediately 
		 * @returns 
		 */
		protected _checkConflictValue(item: Item, checkItemMap: ItemMap<Item>, immediately: boolean = true) {
			if (this._hasError()) {
				return;
			}
			if (checkItemMap.get(item.value)) {
				this._error = this._createError("The value of the item is duplicated.", item);
				if (immediately) {
					this._exception();
				}
			}
		}

		/**
		 * 아이템이 null인 경우 경고 메시지를 출력합니다.
		 * @param item 
		 * @param immediately 
		 */
		protected _checkNullValue(item: Item, immediately: boolean = true): void {
			if (item.value === null) {
				if (immediately) {
					this._warning(this._createError("The value of the item is null.", item));
				}
			}
		}

		/**
		 * 아이템의 value에 delimiter가 포함된 경우 오류 메시지를 출력합니다.
		 * @param item 
		 * @param immediately 
		 * @returns 
		 */
		protected _checkDelimiterValue(item: Item, immediately: boolean = true) {
			if (this._hasError()) {
				return;
			}
			let value = item.value ?? "";
			if (value.split(this._info.delimiter).length > 1) {
				this._error = this._createError("Delimiter is used.", item);
				if (immediately) {
					this._exception();
				}
			}
		}

		public check(item: Item, checkedItemMap: ItemMap<Item>, immediately: boolean = true) {

			if (core.PolicyManager.INSTANCE._isConfigured(core.Policy.DATA_DEFAULT_VALUE_IS_NULL)) {
				this._checkNullValue(item, immediately);
			}
			this._checkConflictValue(item, checkedItemMap, immediately);
			if (this._info.multiple) {
				this._checkDelimiterValue(item, immediately);
			}
		}
	}
	/**
	 * value, label로 구성된 리스트 형태의 데이터를 관리하는 상위 클래스.
	 * @private
	 */
	export abstract class AbstractListDataProvider<
		ItemType extends controls.Item,
		ConfigType extends ItemSetConfig,
		ControlType extends UIControl & MultiValueBindable
	> extends DataProvider<ControlType> implements controls.item.ItemSetInfo {

		protected _visibleRowState: data.tabledata.RowState = data.tabledata.RowState.UNCHANGED | data.tabledata.RowState.INSERTED | data.tabledata.RowState.UPDATED;

		// 선행 데이터 
		protected _predefinedItems: ItemType[] = [];

		// 아이템 셋 설정
		protected _dataSet: data.DataCollection;
		private _itemSetConfig: ConfigType;

		// 필터
		protected _filterExpression: cpr.expression.Expression;

		private _isDisposed: boolean = false;
		private _onLoadItemSet: (e: events.CDataEvent) => void = null;
		/**
		 * value, label로 구성된 리스트 형태 데이터 관리자를 생성합니다.
		 * @param owner 다중 선택을 할 수 있는 value를 가진 컨트롤
		 */
		constructor(owner: ControlType) {
			super(owner);
		}

		/**
		 * 아이템셋이 로드될 때 발생하는 이벤트를 반환합니다.
		 */
		public get onLoadItemSet() {
			return this._onLoadItemSet;
		}
		/**
		 * 아이템셋이 로드될 때 발생하는 이벤트를 설정합니다.
		 */
		public set onLoadItemSet(onLoadItemSet: (e: events.CDataEvent) => void) {
			this._onLoadItemSet = onLoadItemSet;
		}

		/**
		 * 데이터셋에 이벤트 설정하기 위한 속성
		 * @param e 
		 */
		private _onLoadDataSet = (e: events.CDataEvent) => {
			if (this.onLoadItemSet) {
				this.onLoadItemSet(e);
			}
		}

		/**
		 * 필터 익스프레션 값을 반환합니다.
		 */
		get filter(): expression_string {
			if (this._filterExpression) {
				return this._filterExpression.src;
			}
			return null;
		}

		/**
		 * 리스트 데이터에 필터를 적용합니다.
		 * @param filterExpression 필터 조건 expression.
		 */
		set filter(filterExpression: expression_string) {
			if (filterExpression) {
				this._filterExpression = new expression.Expression(filterExpression);
			} else {
				this._filterExpression = null;
			}
		}

		/**
		 * 적용된 필터를 제거합니다.
		 */
		clearFilter(): void {
			if (this._filterExpression != null) {
				this._filterExpression = null;
			}
		}

		protected get castedOwner(): ControlType {
			return this.owner as ControlType;
		}

		/**
		 * 리스트 데이터에 바인딩된 데이터셋을 반환합니다.
		 * @return 데이터셋.
		 */
		get dataSet(): data.DataCollection {
			return this._dataSet;
		}

		/**
		 * 리스트 데이터의 을 반환합니다.
		 * @return 아이템셋
		 */
		get itemSetConfig(): ConfigType {
			return this._itemSetConfig;
		}

		get disposed(): boolean {
			return this._isDisposed
		}

		setVisibleDeletedItem(visible: Boolean) {
			if (visible) {
				this._visibleRowState = data.tabledata.RowState.UNCHANGED | data.tabledata.RowState.INSERTED | data.tabledata.RowState.UPDATED | data.tabledata.RowState.DELETED;
			} else {
				this._visibleRowState = data.tabledata.RowState.UNCHANGED | data.tabledata.RowState.INSERTED | data.tabledata.RowState.UPDATED;
			}
		}

		getVisibleDeletedItem(): boolean {
			return this._visibleRowState == (data.tabledata.RowState.UNCHANGED | data.tabledata.RowState.INSERTED | data.tabledata.RowState.UPDATED | data.tabledata.RowState.DELETED);
		}

		protected hasValidItemSetConfig(): boolean {
			return this._itemSetConfig != null
				&& this._dataSet != null
				&& this._itemSetConfig.label != null
				&& this._itemSetConfig.value != null;
		}

		/**
		 * 리스트 데이터의 dataset을 지정합니다.
		 * @param dataSet 바인딩할 데이터셋.
		 * @param config 연결할 아이템 설정.
		 */
		setItemSet(dataSet: data.DataCollection, config: ConfigType) {
			if (this._dataSet != null && this._dataSet != dataSet) {
				this._dataSet._deleteAllCtrlAttr(this.owner);
				this._dataSet._removeInternalEventListener(events.DataEventType.LOAD, this._onLoadDataSet);
			}
			this._dataSet = dataSet;
			this._itemSetConfig = config;
			this._init();
		}
		private _init() {
			this._dataSet._addInternalEventListener(events.DataEventType.LOAD, this._onLoadDataSet);
		}
		/**
		 * 리스트 데이터를 추가합니다. add를 통한 리스트 데이터 추가는 항상 선행데이터로 추가됩니다.
		 * @param item 추가할 아이템.
		 */
		add(item: ItemType): void {
			if (item == null) {
				throw new cpr.exceptions.IllegalArgumentException();
			}

			this.concretize(item);
			this._predefinedItems.push(item);
		}

		protected concretize(item: ItemType): void {

		}

		/**
		 * 필터가 있는지 유무를 확인합니다.
		 */
		protected _hasFilter(): boolean {
			return this._filterExpression != null;
		}
		/**
		 * 리스트 데이터의 개수를 반환합니다.
		 * @return 데이터의 개수.
		 */
		size(): number {
			if (this._hasFilter()) {
				return this.getFilteredItems().length;
			}
			return this._predefinedItems.length + (this.dataSet ? this.dataSet.getRowStatedCount(this._visibleRowState) : 0);
		}

		/**
		 * Index에 해당되는 데이터를 반환합니다.
		 * @param idx 데이터의 index.
		 * @return 해당하는 아이템.
		 */
		get(idx: number): ItemType {
			if (idx < 0) {
				return null;
			}

			let item = this._findOne((item: ItemType, index: number) => {
				return idx == index;
			});
			return item;
		}

		/**
		 * 필터 속성이 반영되지 않은 아이템 목록을 반환합니다.
		 * @returns 
		 */
		@useCacheRealm("redraw")
		public getAllItems(): ItemType[] {
			return this._getItems(false);
		}

		/**
		 * 필터속성을 반영한 아이템 목록을 반환합니다.
		 * 그리드에서 필터 속성이 행마다 달라 안전하게 행에서 캐시를 저장해야 합니다.
		 * @returns 
		 */
		@useCacheRealm("redraw-grid-row")
		public getFilteredItems(): ItemType[] {
			return this._getItems(true);
		}

		/**
		 * 리스트 데이터 목록을 가져옵니다.
		 * Filter가 적용된 경우 Filtering 된 List를 가져옵니다.
		 * @return 리스트 데이터 목록.
		 */
		protected _getItems(useFilter: boolean = true): ItemType[] {
			let items: ItemType[] = this._predefinedItems.slice(0);
			if (this._dataSet != null) {
				let rowIndices: number[] = this._dataSet.getRowStatedIndices(this._visibleRowState);
				rowIndices.forEach((rowIndex: number) => {
					let row: data.IDataRow = this._dataSet.getRow(rowIndex);
					let item: ItemType = this._convertRowToItem(row);
					items[items.length] = item;
				});
			}

			if (this._hasFilter() && useFilter) {
				let bindCtx: bind.BindContext = this.owner.getBindContext();
				let appInstance = this.owner.getAppInstance();
				let filterFunc: (item: ItemType, key: number, context: ItemType[]) => boolean = this._filterExpression.asFilter();
				items = items.filter((item: ItemType, key: number, context: ItemType[]) => {
					item._ownerBindContext = bindCtx;
					item._expressionIDLookupProvider = appInstance;
					let filterRs: boolean = filterFunc(item, key, context);
					item._expressionIDLookupProvider = null;
					item._ownerBindContext = null;
					return filterRs;
				});
			}
			return items;
		}

		/**
		 * render에서 사용할 아이템조회. 아이템의 중복을 체크한다.
		 * 즉시 오류 발생이 false인 경우 _validateItems를 통해 다음에 오류를 발생 할 수 있다.
		 * @private
		 * @param immediatelyException 즉시 오류를 발생할지 여부
		 */
		public getViewItems(immediatelyException: boolean = true) {
			let items: ItemType[] = [];

			let itemChecker = new ItemChecker({ ownerId: this.castedOwner.id, ownerType: this.castedOwner.type, multiple: this.castedOwner.multiple, delimiter: this.castedOwner.delimiter });
			let valueCollector = new ItemMap<ItemType>();
			valueCollector.setterValidator = (item, itemMap) => {
				itemChecker.check(item, itemMap, immediatelyException);
			};
			let hasFilter = this._hasFilter();
			this._predefinedItems.forEach((each: ItemType) => {
				items[items.length] = each;
				if (!hasFilter) {
					valueCollector.set(each.value, each);
				}
			});
			if (this._dataSet != null) {
				let rowIndices: number[] = this._dataSet.getRowStatedIndices(this._visibleRowState);
				rowIndices.forEach((rowIndex: number) => {
					let row: data.IDataRow = this._dataSet.getRow(rowIndex);
					let item: ItemType = this._convertRowToItem(row);
					items[items.length] = item;
					if (!hasFilter) {
						valueCollector.set(item.value, item);
					}
				});
			}

			if (hasFilter) {
				let bindCtx: bind.BindContext = this.owner.getBindContext();
				let appInstance: core.AppInstance = this.owner.getAppInstance();
				let filterFunc: (item: ItemType, key: number, context: ItemType[]) => boolean = this._filterExpression.asFilter();
				items = items.filter((item: ItemType, key: number, context: ItemType[]) => {
					item._ownerBindContext = bindCtx;
					item._expressionIDLookupProvider = appInstance;
					let filterResult: boolean = filterFunc(item, key, context);
					if (filterResult) {
						valueCollector.set(item.value, item);
					}
					item._expressionIDLookupProvider = null;
					item._ownerBindContext = null;
					return filterResult;
				});
			}
			return items;
		}

		/**
		 * 조건에 맞는 리스트 데이터 목록을 가져옵니다.
		 * <pre><code>
		 * dataProvider.findItems({label:"서울"});<br>
		 * </code></pre>
		 * @param condition 데이터를 찾을 조건.
		 * @return 조건에 맞는 리스트 데이터 목록.
		 * 
		 */
		findItems(condition: { [key: string]: any }): ItemType[] {
			let result = this._find((it: ItemType) => {
				return it._match(condition);
			});
			return result;
		}

		/**
		 * 조건에 맞는 리스트 데이터를 가져옵니다.<br>
		 * 데이터가 2개 이상이라면 첫번째 데이터를 가져옵니다.
		 * <pre><code>
		 * dataProvider.findItem({value:"001"});<br>
		 * dataProvider.findItem({label:"서울"});<br>
		 * dataProvider.findItem({value:"001",label:"서울"});
		 * </code></pre>
		 * @param condition 데이터를 찾을 조건.
		 * @return 조건에 맞는 리스트 데이터.
		 */
		findItem(condition: { [key: string]: any }): ItemType {
			return this._findOne((it: ItemType) => {
				return it._match(condition);
			});

		}

		setItemEnable(item: ItemType, enabled: boolean) {
			this.setItemAttribute(item, ItemDataSetCtrlProperty.enabled, enabled);
		}

		protected _setPredefinedItemProperty(item: ItemType, key: string, value: any) {
			if (key == ItemDataSetCtrlProperty.enabled) {
				item._setEnabled(value)
			} else if (item[key] !== undefined) {
				item[key] = value;
			}
		}

		protected _getPredefinedItemProperty(item: ItemType, key: string) {
			if (key == ItemDataSetCtrlProperty.enabled) {
				return item._getEnabled()
			} else if (item[key] !== undefined) {
				return item[key];
			}
			return null;
		}

		/**
		 * 아이템에 속성을 지정합니다.
		 * @param item 
		 * @param key 
		 * @param value 
		 */
		protected setItemAttribute(item: ItemType, key: string, value: any): boolean {
			let success = false;
			if (!item.row) {
				success = this._predefinedItems.some((each: ItemType) => {//선행 데이터 체크 저장
					if (each.value == item.value) {
						this._setPredefinedItemProperty(each, key, value);
						return true;
					}
					return false;
				});
			} else {
				if (this._dataSet != null) {
					let row: data.IDataRow = item.row._getDataSet() === this._dataSet ? item.row : this._dataSet.findFirstRow(`${this.itemSetConfig.value} == ${JSON.stringify(item.value)}`);
					if (this.itemSetConfig[key] && row) { //데이터셋에 체크 저장
						row.setValue(this.itemSetConfig[key], value.toString());
						success = true;
					} else if (row) {
						this._dataSet._setCtrlAttr(this.owner, row.getIndex(), key, value);
						success = true;
					}
				}
			}

			return success;
		}

		/**
		 * 아이템에 지정된 속성을 가져옵니다.
		 * @param item 
		 * @param key 
		 */
		protected getItemAttribute(item: ItemType, key: string): any {
			let result = null;
			if (!item.row) {
				this._predefinedItems.some((each: ItemType) => {//선행 데이터 체크 저장
					if (each.value == item.value) {
						result = this._getPredefinedItemProperty(each, key);
						return true;
					}
					return false;
				});
			} else {
				if (this._dataSet != null) {
					let row: data.IDataRow = this._dataSet === item.row._getDataSet() ? item.row : this._dataSet.findFirstRow(`${this.itemSetConfig.value} == ${JSON.stringify(item.value)}`);
					if (this.itemSetConfig[key] && row) { //데이터셋에 체크 저장
						result = row.getValue(this.itemSetConfig[key]);
					} else if (row) {
						result = this._dataSet._getCtrlAttr(this.owner, row.getIndex(), key);
					}
				}
			}

			return result;
		}

		protected _findOne(findFunc: (it: ItemType, idx?: number) => boolean, useFilter: boolean = true): ItemType {
			let result: ItemType = null;
			if (this._hasFilter() && useFilter) {
				this.getFilteredItems().some((each: ItemType, index: number) => {
					if (findFunc(each, index) == true) {
						result = each;
						return true;
					}
					return false;
				});
				return result;
			}

			let index: number;
			for (index = 0; index < this._predefinedItems.length; index++) {
				let item: ItemType = this._predefinedItems[index];
				if (findFunc(item, index) == true) {
					return item;
				}
			}

			if (this._dataSet != null) {
				let rowIndices: number[] = this._dataSet.getRowStatedIndices(this._visibleRowState);
				rowIndices.some((rowIndex: number, order: number) => {
					let row: data.IDataRow = this._dataSet.getRow(rowIndex);
					let item: ItemType = this._convertRowToItem(row);
					if (findFunc(item, index + order) == true) {
						result = item;
						return true;
					}
					return false;
				});
			}
			return result;
		}

		protected _find(findFunc: (it: ItemType, idx?: number) => boolean, useFilter: boolean = true): ItemType[] {

			if (this._hasFilter() && useFilter) {
				return this.getFilteredItems().filter((each: ItemType, index: number) => {
					return findFunc(each, index) == true;
				});
			}
			let result: ItemType[] = [];
			let index: number;
			for (index = 0; index < this._predefinedItems.length; index++) {
				let item: ItemType = this._predefinedItems[index];
				if (findFunc(item, index) == true) {
					result[result.length] = item;
				}
			}
			if (this._dataSet != null) {
				let rowIndices: number[] = this._dataSet.getRowStatedIndices(this._visibleRowState);
				rowIndices.forEach((rowIndex: number, order: number) => {
					let row: data.IDataRow = this._dataSet.getRow(rowIndex);
					let item: ItemType = this._convertRowToItem(row);
					if (findFunc(item, index + order) == true) {
						result[result.length] = item;
					}
				});
			}
			return result;
		}

		/**
		 * 선택된 리스트 데이터를 모두 선택 해제 합니다.
		 */
		clearSelection() {
			this.owner.value = null;
		}

		protected _findSelectionItem(): ItemType[] {
			let selectedValues: string[] = this.castedOwner.values;
			let findItemMap = _createMap<string, ItemType>();

			let items = this.getAllItems();
			let process: (item: ItemType) => void;
			if (this._hasFilter()) {
				let bindCtx: bind.BindContext = this.owner.getBindContext();
				let appInstance: core.AppInstance = this.owner.getAppInstance();
				let filterFunc: (item: ItemType) => boolean = this._filterExpression.asFilter();
				process = (item: ItemType) => {
					item._ownerBindContext = bindCtx;
					item._expressionIDLookupProvider = appInstance;
					let itemValue: string = item.value; // value호출은 성능에 영향을 미친다.
					let selectedValueIndex = selectedValues.indexOf(itemValue);
					if (selectedValueIndex > -1) {
						if (filterFunc(item)) {// 필터링된 아이템인 경우
							findItemMap.set(itemValue, item);
							selectedValues.splice(selectedValueIndex, 1); // 선택된 값은 제거한다.
						} else if (findItemMap.has(itemValue) == false) { // 필터링되지 않은 아이템인 경우
							// 선택된 값이지만 필터링되지 않은 아이템인 경우 표시하기 위해 선택된 아이템으로 추가한다.
							findItemMap.set(itemValue, item);
						};
					}
					item._expressionIDLookupProvider = null;
					item._ownerBindContext = null;
				}
			} else {
				process = (item: ItemType) => {
					let itemValue: string = item.value; // value호출은 성능에 영향을 미친다.
					let selectedValueIndex = selectedValues.indexOf(itemValue);
					if (selectedValueIndex > -1) {
						findItemMap.set(itemValue, item);
						selectedValues.splice(selectedValueIndex, 1); // 선택된 값은 제거한다.
					};
				}
			}

			items.some((each: ItemType) => {
				process(each);
				return selectedValues.length == 0; // 선택된 값이 없으면 중단
			});
			return CMap._valueStream(findItemMap).collect();
		}

		/**
		 * 선택된 리스트 데이터 배열을 반환합니다.
		 * @return 선택된 리스트 데이터 배열.
		 */
		getSelection(): ItemType[] {
			let selectedValues: string[] = this.castedOwner.values;
			if (selectedValues.length === 0) {
				return [];
			}
			//1. 아이템의 순서대로 values에 맞는 아이템을 찾아 배열을 반환한다. values의 순서와 다르게 반환됨.
			let findItems = this._findSelectionItem();
			let map = _stream(findItems).toMap((item) => item.value);
			let result = [];
			//2. values 순서대로 정렬하여 result에 넣는다.
			selectedValues.forEach((value, index) => {
				let item = map.get(value);
				if (item) {
					result[index] = item;
				}
			});
			//3. [item,undefined, item] 인 경우 undefined를 제거하여 result에 넣는다.
			result = result.filter(function (item) {
				return item != null;
			});
			return result;

		}

		/**
		 * 선택된 리스트 데이터의 개수를 반환합니다.
		 * @return 선택된 리스트 데이터의 개수.
		 */
		getSelectionSize(): number {
			return this.getSelection().length;
		}

		/**
		 * 해당 리스트 데이터를 가지고 있는지에 대한 여부를 반환합니다.
		 * @param item 확인할 리스트 데이터.
		 * @return 리스트 데이터를 가지고 있는지에 대한 여부.
		 */
		has(item: ItemType): boolean {
			let result = this._findOne((it: ItemType) => {
				return it.value == item.value;
			}, false);
			return result != null;
		}

		private _insert(item: ItemType, offset: ItemType, after: boolean): void {
			let idx: number = -1;
			this._predefinedItems.some((each: ItemType, index: number) => {
				if (each.value == offset.value) {
					idx = index;
					return true;
				}
				return false;
			});

			if (idx == -1) {
				let rowIndices: number[] = this._dataSet.getRowStatedIndices(this._visibleRowState);
				let updated: boolean = rowIndices.some((rowIndex: number) => {
					let row: data.IDataRow = this._dataSet.getRow(rowIndex);
					let dataSetItem: ItemType = this._convertRowToItem(row);
					if (offset.value == dataSetItem.value) {
						let newRow: data.IDataRow = this._dataSet.insertRow(rowIndex, after);
						this.updateRow(item, newRow);
						return true;
					}
					return false;
				});
				if (updated == false) {
					throw new cpr.exceptions.IllegalStateException();
				}
			} else {
				this._predefinedItems.splice(idx + (after ? 1 : 0), 0, item);
			}
		}

		public addRow(item: ItemType) {
			if (!this._dataSet) {
				return;
			}
			let row = this._dataSet.addRow();
			this.updateRow(item, row);
		}

		/**
		 * 기준이 되는 데이터 전에 해당 리스트 데이터를 추가합니다.
		 * @param item 추가할 리스트 데이터.
		 * @param offset 기준이 되는 리스트 데이터.
		 */
		insertBefore(item: ItemType, offset: ItemType): void {
			this._insert(item, offset, false);
		}

		/**
		 * 기준이 되는 데이터 이후에 해당 리스트 데이터를 추가합니다.
		 * @param item 추가할 리스트 데이터.
		 * @param offset 기준이 되는 리스트 데이터.
		 */
		insertAfter(item: ItemType, offset: ItemType): void {
			this._insert(item, offset, true);
		}

		/**
		 * 선행 데이터를 설정합니다.
		 * @param items 설정할 리스트 데이터 배열
		 */
		setPredefinedItems(items: ItemType[]): void {
			if (items == null) {
				items = [];
			}

			this._predefinedItems = items;
		}

		/**
		 * 해당 리스트 데이터를 선택합니다.
		 * @param item 선택할 리스트 데이터.
		 * @return 선택 성공 여부.
		 */
		select(item: ItemType, multiple: boolean = false): boolean {
			if (item == null) {
				return false;
			}
			if (multiple === true) {
				let values: string[] = [];
				let hasItem: boolean = false;
				this.getSelection().forEach((each: ItemType) => {
					if (each.value == item.value) {
						hasItem = true;
					}
					values.push(each.value);
				});
				if (hasItem) {
					return false;
				}
				values.push(item.value);
				this.castedOwner.values = values;
				return true;
			} else {
				this.owner.value = item.value;
				return true;
			}
		}

		/**
		 * 해당 리스트 데이터 배열을 선택합니다.
		 * @param items 선택할 리스트 아이템의 배열.
		 */
		selectItems(items: ItemType[], multiple: boolean = false): void {
			let itemValues = [];
			items.forEach((it: ItemType) => {
				if (it) {
					itemValues.push(it.value);
				}
			})
			if (multiple) {
				itemValues = this.castedOwner.values.concat(itemValues);
			}
			this.castedOwner.values = itemValues;
		}

		/**
		 * 해당 리스트 데이터의 선택 여부를 반환합니다.
		 * @param item 선택 여부를 확인할 리스트 데이터.
		 * @return 선택 여부.
		 */
		isSelected(item: ItemType): boolean {
			if (item == null || item.value == null) {
				return false;
			}
			return this.castedOwner.values.indexOf(item.value) !== -1;
		}

		/**
		 * 선택된 리스트 데이터 배열 중 첫번째 데이터를 반환합니다.
		 * @return 첫번째 선택된 데이터.
		 */
		getSelectionFirst(): ItemType {
			let firstValue = this.castedOwner.values[0];
			if (firstValue == null) {
				return null;
			}
			let result = this._findOne((it: ItemType) => {
				return it.value == firstValue;
			}, false);
			return result;
		}

		/**
		 * 선택된 리스트 데이터 배열 중 마지막 데이터를 반환합니다.
		 * @return 마지막으로 선택된 데이터.
		 */
		getSelectionLast(): ItemType {
			let values = this.castedOwner.values;
			if (values.length === 0) {
				return null;
			}
			let lastValue = values[values.length - 1];
			let result = this._findOne((it: ItemType) => {
				return it.value == lastValue;
			}, false);
			return result;
		}



		/**
		 * value에 해당하는 리스트 데이터를 선택합니다.
		 * @param value 선택하고자 하는 리스트 데이터의 value
		 */
		selectByValue(value: string, multiple: boolean = false): boolean {
			let itemType: ItemType = this._findOne((it: ItemType) => {
				return it.value == value;
			});
			if (itemType) {
				return this.select(itemType, multiple);
			}
			return false;
		}

		/**
		 * value에 해당되는 리스트 데이터가 선택되었는 지에 대한 여부를 반환합니다.
		 * @param value 선택되었는지 확인하고자 하는 리스트 데이터의 value.
		 * @return 선택되었는지에 대한 여부.
		 */
		isSelectedByValue(value: string): boolean {
			if (this.castedOwner.multiple) {
				return this.castedOwner.values.indexOf(value) !== -1;
			} else {
				return this.castedOwner.value == value;
			}
		}

		/**
		 * index에 해당하는 리스트 데이터를 선택 해제합니다.
		 * @param idx 선택 해제하고자 하는 리스트 데이터의 index.
		 * @deprecated 내부에서 아이템 위주로 사용하게 변경되어 {@link deleteSelection}를 사용하시기 바랍니다.
		 */
		deleteSelectionByIndex(idx: number): void {
			if (idx < 0 || idx >= this.size()) {
				return;
			}

			let item = this.get(idx);
			if (item) {
				this._deselectItems([item]);
			}
		}

		/**
		 * 해당하는 리스트 데이터를 선택 해제합니다.
		 * @param item 선택 해제하고자 하는 리스트 데이터.
		 */
		deleteSelection(items: ItemType[]): void {
			this._deselectItems(items);
		}

		protected _deselectItems(items: ItemType[]) {
			let result = [];
			let map = _stream(items).toMap((item) => item.value);
			this.castedOwner.values.forEach((each) => {
				if (!map.has(each)) {
					result.push(each);
				}
			});
			this.castedOwner.values = result;
		}

		/**
		 * value에 해당하는 리스트 데이터를 선택 해제합니다.
		 * @param value 선택 해제하고자 하는 리스트 데이터의 value
		 */
		deleteSelectionByValue(value: string): void {
			let itemValues: string[] = [value];

			itemValues = _.difference(this.castedOwner.values, itemValues);
			this.castedOwner.values = itemValues;
		}

		/**
		 * label에 해당되는 리스트 데이터를 반환합니다.
		 * @param label 리스트 데이터의 label.
		 * @return 해당하는 리스트 데이터.
		 */
		getByLabel(label: String): ItemType {
			return this._findOne((it: ItemType) => {
				return it.label == label;
			});
		}

		/**
		 * UUID에 해당되는 리스트 데이터를 반환합니다.
		 * @param uuid 리스트 데이터의 UUID.
		 * @param useFilter 필터 적용 여부
		 * @return 해당하는 리스트 데이터.
		 */
		getByUUID(uuid: string, useFilter: boolean = true): ItemType {
			return this._findOne((it: ItemType) => {
				return it._getUUID() == uuid;
			}, useFilter);
		}

		/**
		 * value에 해당하는 리스트 데이터를 반환합니다.
		 * @param value 가져오고자 하는 리스트 데이터의 value.
		 * @param useFilter 필터 적용 여부
		 * @return 해당하는 리스트 데이터.
		 */
		getByValue(value: string, useFilter: boolean = true): ItemType {
			let result = this._findOne((it: ItemType) => {
				return it.value == value;
			}, useFilter);
			return result;
		}

		/**
		 * value에 해당하는 리스트 데이터 배열을 반환합니다.
		 * @param value 가져오고자 하는 리스트 데이터의 value.
		 * @return 해당하는 리스트 데이터 배열.
		 * @deprecated value중복을 허용하지 않기 때문에 폐기됨.
		 */
		getItemsByValue(value: string): ItemType[] {
			let result: ItemType[] = this._find((it: ItemType) => {
				return it.value == value;
			});
			return result;
		}

		/**
		 * 리스트 데이터의 index를 반환합니다.
		 * 존재하지 않는 데이터의 경우 -1을 반환합니다.
		 * @param item 리스트 데이터의 정보.
		 * @return 해당하는 리스트 데이터의 Index
		 */
		getIndex(item: ItemType): number {
			if (item == null) {
				return -1;
			}
			let items: ItemType[] = this.getFilteredItems();
			for (let idx: number = 0; idx < items.length; idx++) {
				if (items[idx].value == item.value) {
					return idx;
				}
			}

			return -1;
		}

		/**
		 * 선택된 아이템의 인덱스를 가져옵니다.
		 */
		public getSelectedIndices(): number[] {
			let result = [];
			this.getSelection().forEach((each) => {
				result.push(this.getIndex(each));
			});
			return result;
		}

		/**
		 * 선택된 아이템의 데이터셋 인덱스를 가져옵니다. 데이터셋의 아이템이 아닌경우 -1을 반환합니다.
		 */
		public getSelectedDataSetIndices(): number[] {
			let result = [];
			this.getSelection().forEach((each) => {
				if (each.row) {
					result.push(each.row.getIndex());
				} else {
					result.push(-1);
				}
			});
			return result;
		}

		/**
		 * 아이템의 value로 데이터셋의 인덱스를 반환합니다. 
		 * @param value 
		 */
		public getDataSetIndexByValue(value: string): number {
			let result = -1;
			if (this._dataSet != null) {
				let rowIndices: number[] = this._dataSet.getRowStatedIndices(this._visibleRowState);
				rowIndices.some((rowIndex: number) => {
					let row: data.IDataRow = this._dataSet.getRow(rowIndex);
					if (row.getValue(this.itemSetConfig.value) == value) {
						result = row.getIndex();
						return true;
					}
					return false;
				});
			}
			return result;
		}

		/**
		 * 아이템으로 데이터셋의 인덱스를 반환합니다.
		 * @param item 
		 */
		public getDataSetIndex(item: ItemType): number {
			if (item.row) {
				return item.row.getIndex();
			}
			return -1;
		}

		protected _convertDataSetIndex(idx: number): number {
			idx = idx - this._predefinedItems.length;
			if (idx < 0) {
				return -1;
			}
			let dataSetIndices: number[] = this._dataSet.getRowStatedIndices(this._visibleRowState);
			if (idx >= dataSetIndices.length) {
				return -1;
			}
			return dataSetIndices[idx];
		}

		/**
		 * 아이템을 모두 삭제합니다.
		 */
		deleteAllItems() {
			this._predefinedItems = [];
			if (this._dataSet) {
				let rowIndices: number[] = this._dataSet.getRowStatedIndices(this._visibleRowState);
				rowIndices.forEach((rowIndex: number) => {
					this._dataSet.deleteRow(rowIndex);
				});
			}
		}

		/**
		 * 해당 index의 리스트 데이터를 삭제합니다.
		 * @param item 삭제하고자 하는 리스트 데이터의 item.
		 */
		deleteItem(item: ItemType): void {
			if (item.row) {
				this._dataSet.deleteRow(item.row.getIndex());
			} else {
				let findIdx = -1;
				this._predefinedItems.some(function (each: ItemType, eachIdx) {
					if (each.value == item.value) {
						findIdx = eachIdx;
						return true;
					}
				});
				this._predefinedItems.splice(findIdx, 1);
			}

		}

		/**
		 * value에 해당하는 리스트 데이터를 삭제합니다.
		 * @param value 삭제하고자 하는 리스트 데이터의 value
		 */
		deleteItemByValue(value: string): void {
			let item = this.getByValue(value, false);
			if (item == null) {
				return;
			}
			this.deleteItem(item);
		}

		/**
		 * 해당 index의 리스트 데이터를 수정합니다.
		 * @param idx 수정하고자 하는 리스트 데이터의 index.
		 * @param sourceItem 수정된 리스트 데이터.
		 */
		update(targetItem: ItemType, sourceItem: ItemType): void {
			if (!targetItem) {
				throw new cpr.exceptions.IllegalArgumentException();
			}
			let success = false;
			this._predefinedItems.some((each: ItemType) => {//선행 데이터 체크 저장
				if (each.value == targetItem.value) {
					this._updateItem(sourceItem, each);
					success = true;
					return true;
				}
				return false;
			});
			if (success) {
				return;
			}

			if (this.itemSetConfig) {//데이터셋에 체크 저장
				let row: data.IDataRow = this._dataSet.findFirstRow(`${this.itemSetConfig.value} == ${JSON.stringify(targetItem.value)}`);
				if (row) {
					this.updateRow(sourceItem, row);
				}
			}
		}

		/**
		 * 리스트 데이터의 소스 아이템을 타겟 아이템으로 이동합니다.
		 * @param targetItem 이동하고자 하는 Item.
		 * @param sourceItem 현재 리스트 데이터의 Item.
		 */
		moveItem(targetItem: ItemType, sourceItem: ItemType, after: boolean = true): void {
			if ((targetItem == null || sourceItem == null) || sourceItem.value == targetItem.value) {
				throw new exceptions.IllegalArgumentException();
			}

			let itemInfo = { source: { has: false, idx: -1 }, target: { has: false, idx: -1 } };
			this._predefinedItems.forEach((each: ItemType, idx: number) => {
				if (each.value == sourceItem.value) {
					itemInfo.source.has = true;
					itemInfo.source.idx = idx;
				} else if (each.value == targetItem.value) {
					itemInfo.target.has = true;
					itemInfo.target.idx = idx;
				}
			});
			let success = false;
			if (itemInfo.source.has && itemInfo.target.has) {
				if (after && itemInfo.target.idx < itemInfo.source.idx) {
					itemInfo.target.idx += 1;
				} else if (after == false && itemInfo.target.idx > itemInfo.source.idx) {
					itemInfo.target.idx = itemInfo.target.idx - 1 >= 0 ? itemInfo.target.idx - 1 : itemInfo.target.idx;
				}
				let srcItem: ItemType = this._predefinedItems[itemInfo.source.idx];
				this._predefinedItems.splice(itemInfo.source.idx, 1);
				this._predefinedItems.splice(itemInfo.target.idx, 0, srcItem);
				success = true;
			} else if (this.itemSetConfig) {//데이터셋에 체크 저장
				let sourceRow: data.IDataRow = this._dataSet.findFirstRow(`${this.itemSetConfig.value} == ${JSON.stringify(sourceItem.value)}`);
				let targetRow: data.IDataRow = this._dataSet.findFirstRow(`${this.itemSetConfig.value} == ${JSON.stringify(targetItem.value)}`);
				if (sourceRow && targetRow) {
					this._dataSet.moveRowIndex(sourceRow.getIndex(), targetRow.getIndex(), after);
					success = true;
				}
			}
			if (success == false) {
				console.warn("can not cross move Item repository. dataset->predefinedItem or predefinedItem->dataset");
			}
		}

		/**
		 * 선택된 리스트 데이터 중 조건에 맞는 리스트 데이터를 찾습니다.
		 * @param name 리스트 데이터의 key 명
		 * @param expectedValue 리스트 데이터의 value.
		 * @return 조건에 맞는 리스트 데이터 목록.
		 */
		findSelection(name: string, expectedValue: any): ItemType[] {
			return this.getSelection().filter((it: ItemType) => {
				return it[name] == expectedValue;
			})
		}

		/**
		 * @private
		 */
		dispose() {
			if (this._dataSet) {
				this._dataSet._deleteAllCtrlAttr(this.owner);
				this._dataSet._removeInternalEventListener(events.DataEventType.LOAD, this._onLoadDataSet);
			}
			this._dataSet = null;
			this._predefinedItems = null;
			this._itemSetConfig = null;
			this._isDisposed = true;
		}


		// 서브클래스는 반드시 오버라이드 해야 함.
		protected _updateItem(source: ItemType, destination: ItemType): void {
			destination.label = source.label;
			destination.value = source.value;
		}

		protected _convertRowToItem(row: data.IDataRow): ItemType {
			let result = this.convertRowToItem(row);
			// result._row = row;
			return result;
		}

		protected abstract convertRowToItem(row: data.IDataRow): ItemType;
		protected abstract updateRow(source: ItemType, row: data.IDataRow): void;
	}


	/**
	 * value, label로 구성된 리스트 형태의 데이터를 관리하는 클래스.
	 * @private
	 */
	export class ListDataProvider extends AbstractListDataProvider<Item, ItemSetConfig, any> {
		protected convertRowToItem(row: data.Row): Item {
			let item = new Item(row, this);
			return item;
		}

		protected updateRow(source: Item, row: data.Row): void {
			row.setValue(this.itemSetConfig.label, source.label);
			row.setValue(this.itemSetConfig.value, source.value);
			if (this.itemSetConfig.icon) {
				row.setValue(this.itemSetConfig.icon, source.icon);
			}
			if (this.itemSetConfig.tooltip) {
				row.setValue(this.itemSetConfig.tooltip, source.tooltip);
			}
		}

	}
}