/// <reference path="./DOMEventWrapper.ts" />


namespace cpr.events {
	/**
	 * value 변경에 대한 이벤트 유형
	 * @noinstance
	 */
	export class ValueChangeEventType {
		/**
		 * value를 변경하여 변경된 값이 저장되기 전에 발생하는 이벤트.<br>
		 * 다음 이벤트로 value-change 이벤트가 발생합니다.
		 */
		public static readonly BEFORECHANGE: string = "before-value-change";
		/**
		 * value를 변경하여 변경된 값이 저장된 후에 발생하는 이벤트.
		 */
		public static readonly CHANGE: string = "value-change";

		/**
		 * 바인드컨텍스트를 가지고 있는 컨트롤에서 바인드컨텍스트를 이용해 값이 변경되기 전에 발생하는 이벤트.<br/>
		 * 다음 이벤트로 context-value-change 이벤트가 발생합니다.
		 */
		public static readonly BEFORECONTEXTVALUECHANGE: string = "before-context-value-change";
		/**
		 * 바인드컨텍스트를 가지고 있는 컨트롤에서 바인드컨텍스트를 이용해 값이 변경된 후에 발생하는 이벤트.<br/>
		 */
		public static readonly CONTEXTVALUECHANGE: string = "context-value-change";
	}

	/**
	 * value 변경 이벤트에 대한 옵션.
	 */
	export interface CValueChangeEventOptions extends CEventOption {
		/**
		 * 이전 값.
		 */
		oldValue?: string;
		/**
		 * 새로운 값.
		 */
		newValue?: string;
		/**
		 * 바인드컨텍스트.
		 * cpr.bind.DataBindContext
		 */
		context?: bind.DataBindContext;
		/**
		 * 바인드컨텍스트를 통해 변경하려고 하는 컬럼명.
		 */
		columnName?: string;

	}

	/**
	 * value가 바뀔 시 발생하는 이벤트.
	 */
	export class CValueChangeEvent extends CUIEvent {

		/** 
		 * 이전 값을 반환합니다.
		 * @return 이전 값.
		 */
		get oldValue(): string {
			return this._getOption("oldValue");

		}

		/**
		 * 새로운 값을 반환합니다.
		 * @return 새로운 값.
		 */
		get newValue(): string {
			return this._getOption("newValue");
		}

		/**
		 * 
		 */
		get context(): bind.DataBindContext {
			return this._getOption("context");
		}

		/**
		 * 바인드컨텍스트를 통해 변경하려고 하는 컬럼명.
		 */
		get columnName(): string {
			return this._getOption("columnName");
		}
	}

}