
namespace cpr.controls.internal {
	let log = utils.Logger.forTopic("ndnd")._createBindedLoggerFunction({
		updator: it => log = it
	});

	class KeyStates {
		public ctrlKey: boolean = false;
		public shiftKey: boolean = false;
		public altKey: boolean = false;
		public metaKey: boolean = false;

		constructor(e?: UIEvent) {
			if (e instanceof MouseEvent) {
				this.ctrlKey = e.ctrlKey;
				this.shiftKey = e.shiftKey;
				this.altKey = e.altKey;
				this.metaKey = e.metaKey;
			}
		}
	}

	export interface NodeDragSourceOptions {
		/**
		 * 데이터 타입
		 */
		dataType: string;

		/**
		 * 드롭 타겟들을 무시할 것인지 여부. 이를 true로 지정하면 DragSource 스탠드 얼론 모드로 작동하며, 드롭 타겟들과 상호작용하지 않습니다.
		 */
		ignoreDropTargets: boolean;

		/**
		 * 드래그가 시작되기 까지의 드래그 양. 이보다 적은 양이 드래그 된 경우, 드래그가 시작된 것으로 인정되지 않습니다. 
		 * 클릭등의 동작과 드래그를 구분하려면 이 값을 일반적으로 클릭하는 동안 드래그 되는 양 보다 큰 값으로 지정하십시오.
		 */
		threadhold: number;
	}

	export interface NodeDragSourceDelegate {
		options?: NodeDragSourceOptions;

		/**
		 * 드래그가 일어나기 직전에 콜백됩니다.
		 * 마우스 다운이나 터치가 일어나는 시점에 cancel() 할수 있는 기회로서 제공됩니다.
		 * @param context 
		 */
		onBeforeDragStart?(context: NodeDragContext): void;

		/**
		 * 드래그양이 임계치를 넘어 드래그 동작이 시작될 때 콜백 됩니다.
		 */
		onDragStart?(context: NodeDragContext): void;

		/**
		 * 드래그가 일어날 때 마다 콜백 됩니다.
		 */
		onDragMove?(context: NodeDragContext): void;

		/**
		 * 드래그가 완료될 때 콜백 됩니다.
		 */
		onDragEnd?(context: NodeDragContext): void;

		/**
		 * 드래그가 취소되었을 때 콜백 됩니다.
		 * cancel()을 호출하거나 드롭 타겟에서 취소를 요청한 경우 발생합니다.
		 */
		onDragCancel?(context: NodeDragContext): void;
	}

	export class NodeDragSource {
		public static _DEFAULT_DATA_TYPE = "default";

		private _disposed = false;
		private _sourceShape: ufc.ElementShape;
		private _threadhold: number = 10;

		private _dragStartLocation: PointerLocation;
		private _delegate: NodeDragSourceDelegate;
		private _lastPointerLocation: PointerLocation;
		private _data: any;
		private _dataType: string = NodeDragSource._DEFAULT_DATA_TYPE;
		private _exceedThreadHold = false;
		private _activeDropTarget: NodeDropTarget = null;
		private _overlay: HTMLDivElement;
		private _explictCursor: string;
		private _cursorMap: CMap<NodeDropTarget, string> = _createMap();
		private _capturedCursor: string;
		private _knownCursor: string;
		private _dragContext: NodeDragContext;
		private _knownKeyStates: KeyStates;
		private _ignoreDropTargets = false;
		private _ignoreMouseEvents = false;

		/**
		 * 드래그 소스 객체를 만듭니다.
		 * 
		 * @param sourceShape 드래그 될 컨트롤
		 * @param delegate 드래그 동작을 기술하는 델리게이트
		 */
		constructor(sourceShape: ufc.ElementShape, delegate: NodeDragSourceDelegate) {
			this._onMouseDown = this._onMouseDown.bind(this);
			this._onMouseMove = this._onMouseMove.bind(this);
			this._onMouseUp = this._onMouseUp.bind(this);

			this._onScroll = this._onScroll.bind(this);

			this._clickPreventer = this._clickPreventer.bind(this);

			this._delegate = delegate;
			this._sourceShape = sourceShape;

			if (this._delegate && this._delegate.options) {
				let options = this._delegate.options;
				if (typeof options.dataType == "string") {
					this._dataType = options.dataType;
				}
				if (typeof options.threadhold == "number") {
					this._threadhold = options.threadhold;
				}
				if (typeof options.ignoreDropTargets == "boolean") {
					this._ignoreDropTargets = options.ignoreDropTargets;
				}
			}

			this.sourceShape.attr = _assign(this.sourceShape.attr || {}, {

			});
			ufc.ShapeUtil.addEventHandler(this._sourceShape, "mousedown", this._onMouseDown, true);
		}

		/**
		 * 무시할 드래그 양을 얻습니다.
		 */
		get threadhold() {
			return this._threadhold;
		}

		/**
		 * 무시할 드래그 양을 지정합니다. 이 보다 더 드래그 한 경우에만 드래그 세션이 시작됩니다.
		 */
		set threadhold(threadhold: number) {
			this._threadhold = threadhold;
		}

		private _clickPreventer(e: MouseEvent) {
			if (this._exceedThreadHold) {
				log(`드래그 소스 컨트롤의 클릭 이벤트가 차단 되었습니다.`);
				e.stopPropagation();
				e.preventDefault();
			}
		}

		public _resolveCursor() {
			if (this._activeDropTarget) {
				let dropTargetCursor = this._cursorMap.get(this._activeDropTarget);
				if (dropTargetCursor) {
					return dropTargetCursor;
				}
			}
			return this._explictCursor || this._capturedCursor;
		}

		private _captureCursor(element: HTMLElement) {
			if (element instanceof HTMLElement) {
				this._capturedCursor = getComputedStyle(element).cursor;
				log(`커서 캡춰: ${this._capturedCursor}`);
			}
		}

		private _updateCursor() {
			if (!this._isOverlayShowing()) {
				return;
			}
			let newCursor = this._resolveCursor();
			if (this._knownCursor == newCursor) {
				return;
			}

			this._overlay.style.cursor = newCursor;
		}

		public _setCursorForTarget(target: NodeDropTarget, cursor: string) {
			let oldCursor = this._cursorMap.get(target);
			if (oldCursor != cursor) {
				this._cursorMap.set(target, cursor);
				this._updateCursor();
			}
		}

		private _onMouseDown(e: events.CMouseEvent) {
			if (this._ignoreMouseEvents) {
				return;
			}
			log("드래그 소스 마우스 다운");

			this._captureCursor(e.target as HTMLElement);
			if (this._setupDragStart(new PointerLocation(e))) {
				events.BodyEventTarget.INSTANCE._addCaptureEventListener("mousemove", this._onMouseMove);
				events.BodyEventTarget.INSTANCE.addEventListener("mouseup", this._onMouseUp);
				e.stopPropagation();
			}
		}

		private _setupDragStart(location: PointerLocation): boolean {
			this._dragStartLocation = location;
			this._lastPointerLocation = location.getCopy();
			this._dragContext = new NodeDragContext(this);

			window.addEventListener("click", this._clickPreventer, true);
			events.EventBus.INSTANCE.addFilter("scroll", this._onScroll);

			if (this._delegate && this._delegate.onBeforeDragStart) {
				this._delegate.onBeforeDragStart(this._dragContext);
			}

			// onBeforeDragStart에서 cancel() 된 경우.
			if (this._dragContext) {
				_setAllowGlobalSelection(false);
				return true;
			} else {
				return false;
			}
		}


		private _onExceedThreadhold(e: UIEvent) {
			this._knownKeyStates = new KeyStates(e);
			this._showOverlay();
			this._updateCursor();

			if (this._delegate && this._delegate.onDragStart) {
				this._safeRun(() => {
					this._delegate.onDragStart(this._dragContext);
				});
			}
			log("드래그 소스 스레드홀드 돌파, 드래그 시작");
		}

		private _processDragMove(e: UIEvent) {
			let currentPosition = new PointerLocation(e);
			this._lastPointerLocation = currentPosition;

			// 스레드 홀드를 돌파 못한 경우.
			if (!this._exceedThreadHold) {
				this._exceedThreadHold = currentPosition.pageLocation.getDistance(this._dragStartLocation.pageLocation) >= this.threadhold

				// 첫 쓰레드 홀드 돌파 케이스
				if (this._exceedThreadHold) {
					this._onExceedThreadhold(e);
				}
			}

			if (this._exceedThreadHold) {
				this._knownKeyStates = new KeyStates(e);
				if (this._delegate && this._delegate.onDragMove) {
					this._safeRun(() => {
						this._delegate.onDragMove(this._dragContext);
					});
				}

				let activeTarget = this._updateDropTarget(currentPosition);
				if (activeTarget) {
					activeTarget._performDragMove(this, currentPosition);
				}
			}
			this._updateCursor();
		}

		private _onMouseMove(e: events.CMouseEvent) {
			if (this._ignoreMouseEvents) {
				return;
			}
			this._processDragMove(e);

			e.stopPropagation();
			e.preventDefault();

			return false;
		}

		private _processDragFinish(currentPosition: PointerLocation) {
			this._lastPointerLocation = currentPosition;

			if (!this._exceedThreadHold) {
				window.removeEventListener("click", this._clickPreventer, true);
			}
			else {
				let processed = true;
				if (this._activeDropTarget) {
					processed = this._activeDropTarget._performDrop(this, currentPosition);
				}
				if (processed) {
					if (this._delegate && this._delegate.onDragEnd) {
						this._safeRun(() => {
							this._delegate.onDragEnd(this._dragContext);
						});
					}
				} else {
					if (this._delegate && this._delegate.onDragCancel) {
						this._safeRun(() => {
							this._delegate.onDragCancel(this._dragContext);
						});
					}
				}

				setTimeout(() => {
					window.removeEventListener("click", this._clickPreventer, true);
				}, 10);
			}
			this._finalize();
			this._hideOverlay();
			_setAllowGlobalSelection(true);
		}

		private _onMouseUp(e: events.CMouseEvent) {
			if (this._ignoreMouseEvents) {
				return;
			}
			log("드래그 소스 마우스 업");
			let currentPosition = new PointerLocation(e);
			this._processDragFinish(currentPosition);
		}

		/**
		 * 드래그 소스 및 타겟의 델리게이트의 드래그 무브 콜백 호출
		 */
		private _triggerDragMove() {
			if (!this._isDragging()) {
				return;
			}

			// 현재 스크롤 상태로 포인터 위치를 업데이트 함.
			// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/5674
			let scroller = (document.scrollingElement || document.documentElement);
			let currentScrollTop = scroller.scrollTop;
			let currentScrollLeft = scroller.scrollLeft;
			this._lastPointerLocation = new PointerLocation(
				this._lastPointerLocation.clientLocation,
				this._lastPointerLocation.clientLocation.getTranslated(currentScrollLeft, currentScrollTop)
			);

			if (this._delegate && this._delegate.onDragMove) {
				this._safeRun(() => {
					this._delegate.onDragMove(this._dragContext);
				});
			}

			let activeTarget = this._updateDropTarget(this._lastPointerLocation);
			if (activeTarget) {
				activeTarget._performDragMove(this, this._lastPointerLocation)
			}
		}

		private _onScroll() {
			log("스크롤이 일어나 드래그 무브를 다시 트리거 합니다.")
			requestAnimationFrame(() => {
				this._triggerDragMove();
			});
		}

		private _computeDropTargets(location: PointerLocation): NodeDropTarget[] {
			if (this._ignoreDropTargets) {
				return [];
			}
			if (!location) {
				return [];
			}

			// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/5674
			// 클라이언트 좌표계로 검색.
			let allDropTargets = NodeDropTarget._getAllDropTargets();
			let elements = _elementsFromPoint(location.clientLocation.x, location.clientLocation.y).filter(it => {
				return it.hasAttribute(NodeDropTarget.ATTR__DROP_TARGET_ID);
			});

			return elements.map(it => {
				const elementId = it.getAttribute(NodeDropTarget.ATTR__DROP_TARGET_ID);
				return _findFirst(allDropTargets, e => e.id == elementId);
			}).filter(it => it != null);
		}

		private _updateDropTarget(location: PointerLocation): NodeDropTarget {
			let nominatedTargets = this._computeDropTargets(location);

			let oldDropTarget = this._activeDropTarget;
			let newDropTarget = _findFirst(nominatedTargets, e => {
				if (e === oldDropTarget) {
					return true;
				} else {
					return e._accepts(this)
				}
			});
			if (oldDropTarget === newDropTarget) {
				return oldDropTarget;
			}

			if (oldDropTarget) {
				oldDropTarget._performDragLeave(this, location);
			}
			if (newDropTarget) {
				newDropTarget._performDragEnter(this, location);
			}
			this._activeDropTarget = newDropTarget;
			return this._activeDropTarget;
		}

		private _finalize() {
			events.BodyEventTarget.INSTANCE._removeCaptureEventListener("mousemove", this._onMouseMove);
			events.BodyEventTarget.INSTANCE.removeEventListener("mouseup", this._onMouseUp);

			events.EventBus.INSTANCE.removeFilter("scroll", this._onScroll);

			this._activeDropTarget = null;
			this._dragContext = null;
			this._cursorMap.clear();
			this._lastPointerLocation = null;
			this._capturedCursor = null;
			this._exceedThreadHold = false;
			this._dragStartLocation = null;
			this._data = null;
			this._knownKeyStates = null;
			this._ignoreMouseEvents = false;
		}

		/**
		 * 드래그 소스를 파기 합니다.
		 * 파기된 드래그 소스는 재활용 될 수 없습니다.
		 */
		public dispose() {
			if (this._disposed) {
				return;
			}

			if (this._dragStartLocation) {
				this._cancel();
				this._disposed = true;
			} else {
				this._finalize();
				this._disposed = true;
				window.removeEventListener("click", this._clickPreventer, true);
			}
		}

		/**
		 * 드래그 동작을 취소합니다.
		 */
		public _cancel(): void {
			if (!this._dragStartLocation) {
				return;
			}
			window.removeEventListener("click", this._clickPreventer, true);
			if (this._delegate && this._delegate.onDragCancel) {
				this._safeRun(() => {
					this._delegate.onDragCancel(this._dragContext);
				});
			}
			this._finalize();
			this._hideOverlay();
		}

		private _isOverlayShowing() {
			return this._overlay != null;
		}

		private _showOverlay(): HTMLDivElement {
			if (this._isOverlayShowing()) {
				return;
			}
			if (this._overlay == null) {
				this._overlay = this._createOverlay();
			}

			document.body.appendChild(this._overlay);

			return this._overlay;
		}

		private _hideOverlay() {
			if (!this._isOverlayShowing()) {
				return;
			}
			document.body.removeChild(this._overlay);
			this._overlay = null;
		}

		private _createOverlay(): HTMLDivElement {
			let result = document.createElement("div");
			result.className = ufc.Classes.UNSELECTABLE;
			result.style.position = "fixed";
			result.style.top = "0px";
			result.style.right = "0px";
			result.style.bottom = "0px";
			result.style.left = "0px";
			return result;
		}

		private _isDragging(): boolean {
			return this._dragStartLocation != null && this._exceedThreadHold;
		}

		public _getDragStartLocation(): PointerLocation {
			return this._dragStartLocation;
		}

		/**
		 * 드래그 소스의 파기 여부를 얻습니다.
		 */
		get disposed(): boolean {
			return this._disposed;
		}

		/**
		 * 드래그 소스의 데이터를 얻습니다.
		 */
		public _getData(): any {
			return this._data;
		}

		/**
		 * 드래그 소스에 데이터를 지정합니다.
		 */
		public _setData(newData: any) {
			this._data = newData;
		}

		/**
		 * 드래그 소스 컨트롤을 얻습니다.
		 */
		get sourceShape() {
			return this._sourceShape;
		}

		/**
		 * 드롭 타겟들을 무시할 것인지 여부를 얻습니다.
		 */
		get ignoreDropTargets(): boolean {
			return this._ignoreDropTargets;
		}

		/**
		 * 드롭 타겟들을 무시할 것인지 여부를 지정합니다.
		 */
		set ignoreDropTargets(ignore: boolean) {
			if (this._ignoreDropTargets != ignore) {
				this._ignoreDropTargets = ignore;
				this._updateDropTarget(this._lastPointerLocation);
			}
		}

		/**
		 * 드래그 소스의 유형을 얻습니다.
		 */
		get dataType(): string {
			return this._dataType;
		}

		/**
		 * 드래그 소스의 유형을 지정합니다. 드롭 타겟이 소스의 유형을 구분하는데 사용됩니다.
		 * 기본 값은 "default" 입니다.
		 */
		set dataType(newType: string) {
			if (this.dataType == newType) {
				return;
			}

			this._dataType = newType;
			if (this._lastPointerLocation) {
				this._updateDropTarget(this._lastPointerLocation);
			}
		}

		public _getPointerLocation(): PointerLocation {
			return this._lastPointerLocation;
		}

		public _setExplictCursor(cursor: string) {
			if (this._explictCursor != cursor) {
				this._explictCursor = cursor;
				this._updateCursor();
			}
		}

		public _getActiveDropTarget(): NodeDropTarget {
			return this._activeDropTarget;
		}

		public _getKeyStates(): KeyStates {
			return this._knownKeyStates;
		}

		private _safeRun(task: () => void) {
			utils.tryCatch({
				do: () => {
					task();
				},
				_report: true,
				_context: exceptions.ErrorContext.EVENT_LISTENER
			});
		}
	}
}