namespace cpr.controls {

	/**
	 * 개별 아이템에 대한 접근성 설정을 지원하는 Accessibility 클래스
	 * @noinstance
	 */
	export class ItemAccessibility extends Accessibility {
		private _item: Item;

		constructor(owner: UIControl, spec: AriaSpec, item: Item) {
			super(owner, spec);
			this._item = item;
		}

		protected override _createAriaRef(): { [key: string]: any } {
			return { item: this._item, name: this._getName() };
		}

		public dispose(): void {
			this._item = null;
			super.dispose();
		}
	}
}