namespace cpr {
	let _ES2015_COLLECTION = typeof Map == "function" && typeof Set == "function";
	let _ES2015_ITERABLE = _ES2015_COLLECTION && typeof Map.prototype.values == "function";
	let _ES2019_FROM_ENTRIES = typeof Object.fromEntries == "function";
	let _ES2015_ASSIGN = typeof Object.assign == "function";
	let _ES2015_OBJECT_SPREAD = (() => {
		try {
			new Function('({...{a:1}})');
			return true;
		} catch (e) {
			return false;
		}
	})();
	let _ES2015_ARRAY_SPREAD = (() => {
		try {
			new Function('[...[1,2,3]]');
			return true;
		} catch (e) {
			return false;
		}
	})();

	export const _ECMA = {
		/** 네이티브 Map 및 Set의 사용 가능 여부 */
		get _collection() { return _ES2015_COLLECTION; },
		/** ES2015의 Iterable을 사용할 수 있는지 여부 */
		get _iterable() { return _ES2015_ITERABLE; },
		/** Object.fromEntries 사용 가능 여부 */
		get _fromEntries() { return _ES2019_FROM_ENTRIES; },

		get _assign() { return _ES2015_ASSIGN; },
		/** ES2015 Spread 연산자를 사용할 수 있는지 여부 */
		get _spreadOperator() { return _ES2015_OBJECT_SPREAD && _ES2015_ARRAY_SPREAD; },


		_forceUseES5Only: () => {
			// IE 환경 에뮬레이션
			[_ES2015_COLLECTION, _ES2015_ITERABLE, _ES2019_FROM_ENTRIES, _ES2015_ASSIGN] = [false, false, false, false];
			let logger = utils.Logger.forTopic("ecma");
			logger.log(`강제로 ES5 컬렉션 API만 사용하도록 에뮬레이션 되었습니다.`);
		}
	};
}