namespace cpr.controls.item {
	/**
	 * @private
	 */
	export class ItemController<ItemType extends Item, ItemSetConfigType extends ItemSetConfig,
		ItemListProviderType extends ItemListProvider<UIControl, ItemType, ItemSetConfigType, ItemFilter>>
		implements IItemListView<ItemType>, IItemList<ItemType>, IItemController<ItemType> {

		private _selectionManager: ItemSelectionManager<ItemType>;
		private _binder: provider.MultiValueBinder;
		private _owner: UIControl;
		private _itemListProvider: ItemListProviderType;

		constructor(owner: UIControl, binder: provider.MultiValueBinder, selectionManager: ItemSelectionManager<ItemType>, itemListProvider: ItemListProviderType) {
			this._owner = owner;
			this._binder = binder;
			this._itemListProvider = itemListProvider;
			this._selectionManager = selectionManager;
		}

		protected _getItemListProvider(): ItemListProviderType {
			return this._itemListProvider;
		}

		public get selectionManager(): ItemSelectionManager<ItemType> {
			return this._selectionManager;
		}

		public getItemSetConfig(): ItemSetConfigType {
			return this._itemListProvider.getItemDataSource().itemBindingConfig;
		}
		public setItemSet(dataSet: data.DataCollection, config: ItemSetConfigType): void {
			this._itemListProvider.getItemDataSource().setItemSet(dataSet, config);
		}
		/**
		 * 데이터셋을 반환합니다.
		 * @returns 
		 */
		public getDataSet(): data.DataCollection {
			return this._itemListProvider.getItemDataSource().dataSet;
		}

		protected _getActiveItemListView(): IItemListView<ItemType> {
			return this._itemListProvider.getActiveItemListView() as IItemListView<ItemType>;
		}

		protected _getActiveItemList(): IItemList<ItemType> {
			return this._itemListProvider.getActiveItemList() as IItemList<ItemType>;
		}

		/// IItemController 전용 메소드 시작
		/**
		 * 아이템 또는 인덱스에 해당되는 아이템을 선택합니다.
		 * @param item 
		 * @param emitEvent 
		 */
		public selectItem(item: ItemType | number, emitEvent: boolean = true): void {
			if (item instanceof Item) {
				this._selectionManager.selectItem(item as ItemType, emitEvent);
			} else {
				// 2026-01-07 문자열 숫자로 설정하는 경우도 있어 아이템이 아닌 경우 인덱스로 처리.
				this.selectItemByIndex(item, emitEvent);
			}
		}
		/**
		 * 인덱스에 해당되는 아이템을 선택합니다.
		 * @param index 
		 * @param emitEvent 
		 */
		public selectItemByIndex(index: number, emitEvent: boolean = true): void {
			let item = this._getActiveItemListView().get(index);
			this._selectionManager.selectItem(item, emitEvent);
		}

		/**
		 * Label에 해당되는 아이템을 선택합니다.<br>
		 * 선택된 아이템의 value는 컨트롤의 value로 지정됩니다.<br>
		 * 존재하지 않는 아이템인 경우 아이템 선택이 안 되고 해당 value가 지정되지 않습니다.<br>
		 * newSelection,oldSelection이 item[]를 반환합니다.
		 * @param label 아이템의 label.
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 */
		public selectItemByLabel(label: string, emitEvent: boolean = true): void {
			let item = this._getActiveItemListView().getByLabel(label);
			this._selectionManager.selectItem(item, emitEvent);
		}

		/**
		 * value에 해당되는 아이템을 선택합니다.<br>
		 * value로 아이템을 선택하고 value를 지정합니다.<br>
		 * 존재하지 않는 아이템인 경우 아이템 선택이 안 되고 value가 지정되지 않습니다.<br>
		 * newSelection,oldSelection이 item[]를 반환합니다.
		 * @param value 아이템의 value.
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 */
		public selectItemByValue(value: string, emitEvent: boolean = true): void {
			let item: ItemType = this._getActiveItemListView().getByValue(value);
			this._selectionManager.selectItem(item, emitEvent);
		}

		/**
		 * 인덱스에 해당되는 아이템을 선택합니다.
		 * @param index 
		 * @param emitEvent 
		 */
		public selectSingleItemByIndex(index: number, emitEvent: boolean = true): void {
			let item = this._getActiveItemListView().get(index);
			this._selectionManager.selectSingleItem(item, emitEvent);
		}

		/**
		 * Label에 해당되는 아이템을 선택합니다.<br>
		 * 선택된 아이템의 value는 컨트롤의 value로 지정됩니다.<br>
		 * 존재하지 않는 아이템인 경우 아이템 선택이 안 되고 해당 value가 지정되지 않습니다.
		 * @param label 아이템의 label.
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 */
		public selectSingleItemByLabel(label: string, emitEvent: boolean = true): void {
			let item = this._getActiveItemListView().getByLabel(label);
			this._selectionManager.selectSingleItem(item, emitEvent);
		}

		/**
		 * value에 해당되는 아이템을 선택합니다.<br>
		 * value로 아이템을 선택하고 value를 지정합니다.<br>
		 * 존재하지 않는 아이템인 경우 아이템 선택이 안 되고 value가 지정되지 않습니다.
		 * @param value 아이템의 value.
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 */
		public selectSingleItemByValue(value: string, emitEvent: boolean = true): void {
			let item: ItemType = this._getActiveItemListView().getByValue(value);
			this._selectionManager.selectSingleItem(item, emitEvent);
		}

		/**
		 * 아이템 또는 인덱스에 해당되는 아이템 배열을 선택합니다.
		 * @param items 
		 * @param emitEvent 
		 * @returns 
		 */
		public selectItems(items: ItemType[] | number[], emitEvent: boolean = true): void {
			if (_isArray(items) == false) {
				return;
			}
			if (items[items.length - 1] instanceof Item) {
				this._selectionManager.selectItems(items as ItemType[], emitEvent);
			} else {
				this.selectIndices(items as number[], emitEvent);
			}
		}

		/**
		 * 선택할 아이템의 인덱스 배열을 선택합니다.
		 * @param indices 선택할 아이템의 인덱스 배열
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 * @returns 
		 */
		public selectIndices(indices: number[], emitEvent: boolean = true): void {
			if (_isArray(indices) == false) {
				return;
			}
			let items: ItemType[] = [];
			indices.forEach((index: number) => {
				items.push(this._getActiveItemListView().get(index));
			});
			this._selectionManager.selectItems(items, emitEvent);
		}

		/**
		 * 아이템 또는 인덱스에 해당되는 아이템의 선택 여부를 반환합니다.
		 * @param item 
		 * @returns 
		 */
		public isSelected(item: ItemType | number): boolean {
			if (item instanceof Item) {
				return this._selectionManager.isSelected(item as ItemType);
			} else {
				return this.isSelectedByIndex(item);
			}
		}

		/**
		 * 해당되는 인덱스의 아이템의 선택 여부를 반환합니다.
		 * @param index 
		 * @returns 
		 */
		public isSelectedByIndex(index: number): boolean {
			let item = this._getActiveItemListView().get(index);
			return this._selectionManager.isSelected(item);
		}

		/**
		 * 아이템 또는 인덱스에 해당되는 아이템의 선택을 해제합니다.
		 * @param item 
		 * @param emitEvent 
		 */
		public removeSelection(item: ItemType | number, emitEvent: boolean = true): void {
			if (item instanceof Item) {
				this._selectionManager.removeSelection(item as ItemType, emitEvent);
			} else {
				// 2026-01-07 문자열 숫자로 설정하는 경우도 있어 아이템이 아닌 경우 인덱스로 처리.
				this.removeSelectionByIndex(item, emitEvent);
			}
		}

		/**
		 * 선택된 아이템 중 하나를 선택 해제합니다.
		 * @param index 
		 * @param emitEvent 
		 */
		public removeSelectionByIndex(index: number, emitEvent: boolean = true): void {
			let item = this._getActiveItemListView().get(index);
			this._selectionManager.removeSelection(item, emitEvent);
		}

		/**
		 * 선택된 아이템 중 하나를 선택 해제합니다.
		 * @param index 
		 * @param emitEvent 
		 */
		public removeSingleSelectionByIndex(index: number, emitEvent: boolean = true): void {
			let item = this._getActiveItemListView().get(index);
			this._selectionManager.removeSingleSelection(item, emitEvent);
		}

		/**
		 * 선택된 아이템의 인덱스를 가져옵니다.
		 */
		public getSelectedIndices(): number[] {
			let result = [];
			this._selectionManager.getSelection().forEach((each) => {
				result.push(this._getActiveItemListView().getIndex(each));
			});
			return result;
		}

		/**
		 * 아이템 또는 인덱스에 해당되는 아이템을 삭제합니다.
		 * 해당되는 아이템을 삭제합니다. 선행아이템, 데이터셋의 행 등도 함께 삭제됩니다.
		 * @param item 
		 */
		public delete(item: number | ItemType): void {
			if (item instanceof Item) {
				this.deleteItem(item as ItemType);
			} else {
				this.deleteItemByIndex(item as any);
			}
		}

		/**
		 * 해당되는 아이템을 삭제합니다. 선행아이템, 데이터셋의 행 등도 함께 삭제됩니다.
		 * @param item 아이템
		 */
		public deleteItem(item: ItemType): void {
			this._selectionManager.deleteSelection([item]);
			this._getActiveItemList().deleteItem(item);
			this._owner.redraw();
		}

		/**
		 * 해당되는 인덱스의 아이템을 삭제합니다.
		 * @param index 
		 * @returns 
		 */
		public deleteItemByIndex(index: number): void {
			let item = this._getActiveItemListView().get(index);
			if (item == null) {
				return;
			}
			this._selectionManager.deleteSelection([item]);
			this._getActiveItemList().deleteItem(item);
			this._owner.redraw();
		}

		/**
		 * value에 해당되는 아이템을 삭제합니다.
		 * @param value 아이템의 value
		 */
		public deleteItemByValue(value: string): void {
			this._selectionManager.deleteSelectionByValue(value);
			this._getActiveItemList().deleteItemByValue(value);
			this._owner.redraw();
		}

		/**
		 * 모든 아이템을 삭제한다.
		 */
		public deleteAllItems(): void {
			this._binder.setValue(null);
			this._getActiveItemList().deleteAllItems();
			this._owner.redraw();
		}

		/**
		 * 아이템의 value에 해당하는 인덱스를 가져옵니다.
		 * @param value 아이템의 value
		 * @return 해당하는 아이템의 index.
		 */
		public getIndexByValue(value: string): number {
			let item = this._getActiveItemListView().getByValue(value);
			return this._getActiveItemListView().getIndex(item);
		}
		/// IItemController 전용 메소드 끝

		/// IItemList 전용 메소드 시작
		public addPredefinedItem(item: ItemType): void {
			this._getActiveItemList().addPredefinedItem(item);
		}
		public addRowItem(item: ItemType): void {
			this._getActiveItemList().addRowItem(item);
		}
		public setItemEnable(item: ItemType, enabled: boolean): void {
			this._getActiveItemList().setItemEnable(item, enabled);
		}
		public setItemAttribute(item: ItemType, key: string, value: any): boolean {
			return this._getActiveItemList().setItemAttribute(item, key, value);
		}
		public getItemAttribute(item: ItemType, key: string) {
			return this._getActiveItemList().getItemAttribute(item, key);
		}
		public insertBefore(item: ItemType, offset: ItemType): void {
			this._getActiveItemList().insertBefore(item, offset);
		}
		public insertAfter(item: ItemType, offset: ItemType): void {
			this._getActiveItemList().insertAfter(item, offset);
		}
		public setPredefinedItems(items: ItemType[]): void {
			this._getActiveItemList().setPredefinedItems(items);
		}
		public getDataSetIndexByValue(value: string): number {
			return this._getActiveItemList().getDataSetIndexByValue(value);
		}
		public getDataSetIndex(item: ItemType): number {
			return this._getActiveItemList().getDataSetIndex(item);
		}

		public update(targetItem: ItemType, sourceItem: ItemType): void {
			this._getActiveItemList().update(targetItem, sourceItem);
		}
		public moveItem(targetItem: ItemType, sourceItem: ItemType, after: boolean = true): void {
			this._getActiveItemList().moveItem(targetItem, sourceItem, after);
		}

		/// IItemListView 전용 메소드 시작
		get filterExpression(): expression.Expression {
			return this._getActiveItemListView().filterExpression;
		}

		public get disposed(): boolean {
			return this._owner == null;
		}

		public hasFilter(): boolean {
			return this._getActiveItemListView().hasFilter();
		}
		public get filter(): expression_string<() => void> {
			return this._getActiveItemListView().filter;
		}
		public set filter(filterExpression: expression_string<() => void>) {
			this._getActiveItemListView().filter = filterExpression;
		}
		clearFilter(): void {
			this._getActiveItemListView().clearFilter();
		}
		getIndex(item: ItemType): number {
			return this._getActiveItemListView().getIndex(item);
		}
		findOne(findFunc: (it: ItemType, idx?: number) => boolean): ItemType {
			return this._getActiveItemListView().findOne(findFunc);
		}
		get(idx: number): ItemType {
			return this._getActiveItemListView().get(idx);
		}
		has(item: ItemType): boolean {
			return this._getActiveItemListView().has(item);
		}
		getByLabel(label: String): ItemType {
			return this._getActiveItemListView().getByLabel(label);
		}
		getByValue(value: string): ItemType {
			return this._getActiveItemListView().getByValue(value);
		}
		getByUUID(uuid: string): ItemType {
			return this._getActiveItemListView().getByUUID(uuid);
		}
		find(findFunc: (it: ItemType, idx?: number) => boolean): ItemType[] {
			return this._getActiveItemListView().find(findFunc);
		}
		getItemsByValue(value: string): ItemType[] {
			return this._getActiveItemListView().getItemsByValue(value);
		}
		findItem(condition: { [key: string]: any; }): ItemType {
			return this._getActiveItemListView().findItem(condition);
		}
		findItems(condition: { [key: string]: any; }): ItemType[] {
			return this._getActiveItemListView().findItems(condition);
		}
		size(): number {
			return this._getActiveItemListView().size();
		}
		findItemByValues(values: string[]): ItemType[] {
			return this._getActiveItemListView().findItemByValues(values);
		}

		getItems(): ItemType[] {
			return this._getActiveItemList().getItems();
		}

		/**
		 * 필터속성을 반영한 아이템 목록을 반환합니다.
		 * @returns 
		 */
		getVisibleItems(): ItemType[] {
			return this._getActiveItemListView().getVisibleItems();
		}
		/**
		 * 렌더링 시 사용됩니다. 필터속성을 반영한 아이템 목록을 유효한 아이템인지 검증 후 반환합니다.
		 * @returns 
		 */
		getVisibleItemsForRendering(): ItemType[] {
			return this._getActiveItemListView().getVisibleItemsForRendering();
		}
		/// IItemListView 전용 메소드 끝

		/**
		 * 해당 컨트롤을 dispose 처리합니다.
		 */
		public dispose(): void {
			this._owner = null;
			this._itemListProvider?.dispose();
			this._itemListProvider = null;
			this._binder = null;
			this._selectionManager = null;
		}
	}
}