namespace cpr.controls.internal {


	/**
	 * @private
	 */
	export interface Scroller {
		(scrollTop: number, scrollLeft: number): boolean;
	}

	/**
	 * @private
	 */
	export interface TouchRoller {
		_touchStart(e: events.CTouchEvent, scrollTop: number, scollLeft: number): void;
		_touchMove(e: events.CTouchEvent, scroller: Scroller): void;
		_touchEnd(e: events.CTouchEvent, scrollTop: number, scrollLeft: number, scroller: Scroller): void;
	}

	/**
	 * @private
	 * @returns 
	 */
	export function newTouchRoller(): TouchRoller {
		return new MagicNumberBasedTouchRoller();
	}

	/**
	 * @private
	 */
	export class MagicNumberBasedTouchRoller implements TouchRoller {
		private _touchStarted: boolean = false;
		private _touchUpdateTime: number;
		private _touchVelocity: geometry.Point;
		private _touchFirst: geometry.Point;
		private _touchLast: geometry.Point;
		private _touchStartScrollTop: number;
		private _touchStartScrollLeft: number;
		private _touchAnimationStop: boolean = true;
		private _allowTouchRoller: boolean;
		private _rafId: number = 0;


		constructor() {

		}

		public _touchStart(e: events.CTouchEvent, scrollTop: number, scollLeft: number): void {
			if (this._rafId) {
				window.cancelAnimationFrame(this._rafId);
				this._rafId = 0;
			}
			let touch: Touch = e.touches.item(0);

			this._touchUpdateTime = Date.now();
			this._touchVelocity = new geometry.Point(0, 0);
			this._touchFirst = geometry.Point.fromTouch(touch, geometry.LocationCooridnate.client);
			this._touchLast = this._touchFirst.getCopy();

			this._touchStartScrollTop = scrollTop;
			this._touchStartScrollLeft = scollLeft;

			this._touchStarted = true;
			this._touchAnimationStop = true;
			this._allowTouchRoller = null;
		}

		public _touchMove(e: events.CTouchEvent, scroller: Scroller): void {
			if (this._touchStarted === false) {
				return;
			}

			var touch: Touch = e.touches.item(0);

			let now: number = Date.now();

			let position: geometry.Point = geometry.Point.fromTouch(touch, geometry.LocationCooridnate.client);
			let delta: geometry.Point = new geometry.Point(
				-(position.x - this._touchLast.x),
				-(position.y - this._touchLast.y)
			);

			let duration: number = (now - this._touchUpdateTime) || 16;
			let velX: number = delta.x / duration * 16;
			let velY: number = delta.y / duration * 16;

			this._touchVelocity.x = velX * 0.9 + this._touchVelocity.x * 0.1;
			this._touchVelocity.y = velY * 0.9 + this._touchVelocity.y * 0.1;

			this._touchUpdateTime = now;
			this._touchLast = position;

			let newScrollTop: number = -1;
			if (this._touchStartScrollTop !== -1) {
				let offsetTop: number = -(this._touchLast.y - this._touchFirst.y);
				newScrollTop = this._touchStartScrollTop + offsetTop;
			}
			let newScrollLeft: number = -1;
			if (this._touchStartScrollLeft !== -1) {
				let offsetLeft: number = -(this._touchLast.x - this._touchFirst.x);
				newScrollLeft = this._touchStartScrollLeft + offsetLeft;
			}

			if (this._allowTouchRoller === false) {
				return;
			}

			let moved: boolean = scroller(newScrollTop, newScrollLeft);

			if (this._allowTouchRoller == null) {
				this._allowTouchRoller = moved;
			}
			// if (moved === true) {
			if (this._allowTouchRoller === true) {
				// Ignored attempt to cancel a touchmove event with cancelable=false, for example because scrolling is in progress and cannot be interrupted.
				e.preventDefault();
				// e.stopPropagation();
			}
		}

		public _touchEnd(e: events.CTouchEvent, scrollTop: number, scrollLeft: number, scroller: Scroller): void {
			if (this._touchStarted === false) {
				return;
			}
			this._touchStarted = false;
			this._touchAnimationStop = false;
			// e.preventDefault(); // FIXME : 무조건 preventDefault 하면 click 이벤트 등이 발생하지 않음!!!

			if (this._allowTouchRoller == false) {
				return;
			}
			if (scroller == null) {
				return;
			}

			let touch: Touch = e.changedTouches ? e.changedTouches.item(0) : null;
			if (!touch && e.touches) {
				touch = e.touches.item(0);
			}

			let touchLast = this._touchLast;
			if (touch) {
				touchLast = geometry.Point.fromTouch(touch, geometry.LocationCooridnate.client);
			}

			// 터치 이동 중 자바스크립트 지연(Jank)으로 스크롤 위치가 실제 손가락 위치를 따라잡지 못했을 경우를 대비해,
			// 터치 끝 시점의 스크롤 시작 위치를 누적된 실제 드래그 오프셋 좌표로 보정하여 플릭 시 역행(원복)을 방지한다.
			if (scrollTop !== -1 && this._touchStartScrollTop !== -1) {
				let offsetTop: number = -(touchLast.y - this._touchFirst.y);
				scrollTop = this._touchStartScrollTop + offsetTop;
			}
			if (scrollLeft !== -1 && this._touchStartScrollLeft !== -1) {
				let offsetLeft: number = -(touchLast.x - this._touchFirst.x);
				scrollLeft = this._touchStartScrollLeft + offsetLeft;
			}

			let velY: number = this._touchVelocity.y;
			let velX: number = this._touchVelocity.x;
			if (scrollTop === -1) {
				velY = 0;
			}
			if (scrollLeft === -1) {
				velX = 0;
			}

			let __this__ = this;
			(function fn() {
				if (__this__._touchAnimationStop || (Math.abs(velX) < 1 && Math.abs(velY) < 1)) {
					return;
				}
				let previousTime: number = Date.now();
				__this__._rafId = window.requestAnimationFrame(function () {
					if (__this__._touchAnimationStop) {
						return;
					}
					let elapsed: number = (Date.now() - previousTime) || 16;
					let factor: number = Math.pow(0.9, elapsed / 16);
					if (scrollTop !== -1) {
						velY *= factor;
						scrollTop += velY;
					}
					if (scrollLeft !== -1) {
						velX *= factor;
						scrollLeft += velX;
					}

					scroller(scrollTop, scrollLeft);

					fn();
				});
			})();
		}

	}

}



