

namespace cpr.controls.internal {
	/**
	 * @private
	 */
	export interface ScrollbarInfo {
		vWidth: number;
		vBtnHeight: number;
		hHeight: number;
		hBtnWidth: number;
	}

	const browserInfo = browserDetect();
	if (!browserInfo.name) {
		if (navigator.userAgent.indexOf("Safari") !== -1) {
			browserInfo.name = "safari"
		}
	}
	var iOS = browserInfo.mobile && browserInfo.name == "safari"

	/**
	 * @private
	 */
	export class ScrollbarUtil {
		private static _customScrollbarInfo: ScrollbarInfo = null;

		private static _nativeScrollWidth: number = null;
		private static _nativeVirtualScrollWidth: number = null;
		private static _initialized: boolean = false;

		private static _scrollpaneClasses: string[] = [];

		private static readonly _DEFAULT_SCROLL_WIDTH: number = 5;
		private static readonly _SCROLLPANE_MARK_CLASS: string = "cl-scrollable";
		private static readonly _DEFAULT_WHEEL_DELTA: number = 100;
		/** line-height를 확정할 수 없을 때 사용할 한 줄 높이. */
		private static readonly _DEFAULT_LINE_HEIGHT: number = 22.05;
		/** 휠 한 번에 이동할 수 있는 뷰포트 대비 최대 비율. 브라우저(Firefox)가 사용하는 값과 동일. */
		private static readonly _WHEEL_VIEWPORT_LIMIT_RATIO: number = 0.9;

		/**
		 * 스크롤바 정보를 가져올 때 재계산하도록 초기화합니다.
		 */
		public static _invalidate() {
			this._initialized = false;
		}

		public static _getIntSize(size: number): number {
			return Math.ceil(size);
		}

		public static _isMobileBrowser(): boolean {
			if (ScrollbarUtil._initialized == false) {
				ScrollbarUtil._initScrollbarInfo();
			}
			return ScrollbarUtil._isTouchScrollbar();
		}

		public static _getCustomScrollbarInfo(): ScrollbarInfo {
			if (ScrollbarUtil._initialized == false) {
				ScrollbarUtil._initScrollbarInfo();
			}
			return ScrollbarUtil._customScrollbarInfo;
		}

		public static _getScrollPaneClasses(): string[] {
			return _.union([], ScrollbarUtil._scrollpaneClasses);
		}

		public static _getNativeScrollWidth(): number {
			return ScrollbarUtil._nativeVirtualScrollWidth;
		}

		public static _getWheelDelta(delta: number): number {
			if (delta === 0) {
				return delta;
			} else if (delta > 0) {
				return ScrollbarUtil._DEFAULT_WHEEL_DELTA;
			}
			return ScrollbarUtil._DEFAULT_WHEEL_DELTA * -1;
		}

		public static _getScrollPaneWheelDelta(e: WheelEvent): { x: number, y: number } {
			if (!e) {
				return null;
			}
			let deltaX: number = e.deltaX;
			let deltaY: number = e.deltaY;
			if (deltaX === 0 && deltaY === 0) {
				return { x: deltaX, y: deltaY };
			}
			if (e.shiftKey && deltaX === 0) {
				deltaX = deltaY;
				deltaY = 0;
			}
			switch (e.deltaMode) {
				case WheelEvent.DOM_DELTA_PIXEL:
					break;
				case WheelEvent.DOM_DELTA_LINE: {
					// 줄 단위로 전달되는 경우(IE, Firefox) 대상 요소의 실제 한 줄 높이로 환산한다.
					let lineHeight: number = ScrollbarUtil._getLineHeight(e.target);
					deltaX *= lineHeight;
					deltaY *= lineHeight;
					break;
				}
				case WheelEvent.DOM_DELTA_PAGE:
					deltaX = ScrollbarUtil._getWheelDelta(deltaX);
					deltaY = ScrollbarUtil._getWheelDelta(deltaY);
					break;
			}
			return {
				x: deltaX, y: deltaY
			};
		}

		/**
		 * 요소의 한 줄 높이를 얻습니다. line-height를 확정할 수 없으면 기본값을 사용합니다.
		 */
		public static _getLineHeight(target: EventTarget): number {
			let node: Node = target as Node;
			if (!node || node.nodeType !== 1) { // Node.ELEMENT_NODE
				return ScrollbarUtil._DEFAULT_LINE_HEIGHT;
			}
			let style: CSSStyleDeclaration = window.getComputedStyle(node as Element);
			if (!style) {
				return ScrollbarUtil._DEFAULT_LINE_HEIGHT;
			}
			let lineHeight: number = parseFloat(style.lineHeight);
			if (!isNaN(lineHeight) && lineHeight > 0) {
				return lineHeight;
			}
			// line-height가 normal인 경우 폰트 크기로 근사한다.
			let fontSize: number = parseFloat(style.fontSize);
			if (!isNaN(fontSize) && fontSize > 0) {
				return fontSize * 1.2;
			}
			return ScrollbarUtil._DEFAULT_LINE_HEIGHT;
		}

		/**
		 * 브라우저가 전달한 델타를 실제 이동량으로 변환합니다.
		 * 델타를 그대로 사용하되, 뷰포트보다 크면 화면에 한 번도 나타나지 않고 지나가는 영역이
		 * 생기므로 상한을 둡니다. 상한 비율은 브라우저(Firefox)가 사용하는 값과 동일합니다.
		 * @param delta 픽셀로 환산된 델타
		 * @param viewportSize 뷰포트 크기(세로면 높이, 가로면 너비)
		 */
		public static _toWheelOffset(delta: number, viewportSize: number): number {
			if (delta === 0 || !(viewportSize > 0)) {
				return delta;
			}
			let limit: number = viewportSize * ScrollbarUtil._WHEEL_VIEWPORT_LIMIT_RATIO;
			if (Math.abs(delta) <= limit) {
				return delta;
			}
			return delta > 0 ? limit : -limit;
		}


		public static _markScrollableContentPane(contentPane: ufc.ElementShape): void {
			contentPane.classNames = _.union([], contentPane.classNames, ScrollbarUtil._scrollpaneClasses, [ScrollbarUtil._SCROLLPANE_MARK_CLASS]);
		}

		public static _isMarkedScrollableContentPane(contentPane: ufc.ElementShape): boolean {
			if (!contentPane) {
				return false;
			}
			if (contentPane.classNames) {
				let scrollbarClassIdx: number = contentPane.classNames.indexOf(ScrollbarUtil._SCROLLPANE_MARK_CLASS);
				if (scrollbarClassIdx === -1) {
					return false;
				}
				contentPane.classNames = _.without(contentPane.classNames, ScrollbarUtil._SCROLLPANE_MARK_CLASS);
				return true;
			}
			return false;
		}

		private static _initScrollbarInfo(): void {
			ScrollbarUtil._checkNativeScrollbar();

			let scrollPaneClasses: string[] = ["cl-scrollbar"];

			if (ScrollbarUtil._isTouchScrollbar()) {
				scrollPaneClasses[scrollPaneClasses.length] = "cl-touchdevice";
				if (iOS) {
					scrollPaneClasses[scrollPaneClasses.length] = "cl-ios"
				}
			}

			// custom scrollbar
			let scrollbarInfo: ScrollbarInfo = {
				vWidth: 0,
				vBtnHeight: 0,
				hHeight: 0,
				hBtnWidth: 0
			};

			let outer: HTMLDivElement = document.createElement("div");
			outer.style.visibility = "hidden";
			outer.style.position = "relative";
			outer.style.width = "100px";
			outer.style.height = "100px";
			outer.style["msOverflowStyle"] = "scrollbar"; // needed for WinJS apps

			document.body.appendChild(outer);

			outer.innerHTML = '<div class="cl-vscrollbar cl-unselectable"><div class="cl-arrow-up">▲</div><div class="cl-track"><div class="cl-thumb" style="top: 0px; height: 10px;"></div></div><div class="cl-arrow-down">▼</div></div>'
				+ '<div class="cl-hscrollbar cl-unselectable"><div class="cl-arrow-left">◀</div><div class="cl-track"><div class="cl-thumb" style="left: 0px; width: 10px;"></div></div><div class="cl-arrow-right">▶</div></div>';

			ScrollbarUtil._setVScrollbarInfo(outer.querySelector(".cl-vscrollbar"), scrollbarInfo);
			ScrollbarUtil._setHScrollbarInfo(outer.querySelector(".cl-hscrollbar"), scrollbarInfo);

			// remove divs
			outer.parentNode.removeChild(outer);

			ScrollbarUtil._customScrollbarInfo = scrollbarInfo;
			ScrollbarUtil._scrollpaneClasses = scrollPaneClasses;
			ScrollbarUtil._initialized = true;
		}

		private static _checkNativeScrollbar(): void {
			let outer: HTMLDivElement = document.createElement("div");
			outer.style.visibility = "hidden";
			outer.style.width = "100px";
			outer.style["msOverflowStyle"] = "scrollbar"; // needed for WinJS apps

			document.body.appendChild(outer);

			let widthNoScroll: number = outer.offsetWidth;
			// force scrollbars
			outer.style.overflow = "scroll";

			// add innerdiv
			let inner: HTMLDivElement = document.createElement("div");
			inner.style.width = "100%";
			outer.appendChild(inner);

			let widthWithScroll: number = inner.offsetWidth;

			// remove divs
			outer.parentNode.removeChild(outer);

			let scrollWidth: number = (widthNoScroll - widthWithScroll);
			ScrollbarUtil._nativeScrollWidth = scrollWidth;
			if (scrollWidth > 0) {
				ScrollbarUtil._nativeVirtualScrollWidth = scrollWidth + 1;
			} else {
				ScrollbarUtil._nativeVirtualScrollWidth = ScrollbarUtil._DEFAULT_SCROLL_WIDTH;
			}
		}

		private static _setVScrollbarInfo(scrollNode: HTMLElement, scrollbarInfo: ScrollbarInfo): void {
			let cssStyle: CSSStyleDeclaration = window.getComputedStyle(scrollNode);
			let scrollbarHeight: number = scrollNode.clientHeight
				+ utils.ParamUtil.parseSize(cssStyle.borderTopWidth, 0).size
				+ utils.ParamUtil.parseSize(cssStyle.borderBottomWidth, 0).size;

			let scrollbarWidth: number = scrollNode.clientWidth
				+ utils.ParamUtil.parseSize(cssStyle.borderLeftWidth, 0).size
				+ utils.ParamUtil.parseSize(cssStyle.borderRightWidth, 0).size;

			let trackNode: HTMLElement = scrollNode.querySelector(".cl-track");
			let trackCssStyle: CSSStyleDeclaration = window.getComputedStyle(scrollNode);
			let trackHeight: number = trackNode.clientHeight
				+ utils.ParamUtil.parseSize(trackCssStyle.borderTopWidth, 0).size
				+ utils.ParamUtil.parseSize(trackCssStyle.borderBottomWidth, 0).size;

			scrollbarInfo.vWidth = scrollbarWidth;
			scrollbarInfo.vBtnHeight = scrollbarHeight - trackHeight;
		}

		private static _setHScrollbarInfo(scrollNode: HTMLElement, scrollbarInfo: ScrollbarInfo): void {
			let cssStyle: CSSStyleDeclaration = window.getComputedStyle(scrollNode);
			let scrollbarHeight: number = scrollNode.clientHeight
				+ utils.ParamUtil.parseSize(cssStyle.borderTopWidth, 0).size
				+ utils.ParamUtil.parseSize(cssStyle.borderBottomWidth, 0).size;

			let scrollbarWidth: number = scrollNode.clientWidth
				+ utils.ParamUtil.parseSize(cssStyle.borderLeftWidth, 0).size
				+ utils.ParamUtil.parseSize(cssStyle.borderRightWidth, 0).size;

			let trackNode: HTMLElement = scrollNode.querySelector(".cl-track");
			let trackCssStyle: CSSStyleDeclaration = window.getComputedStyle(scrollNode);
			let trackWidth: number = trackNode.clientWidth
				+ utils.ParamUtil.parseSize(trackCssStyle.borderLeftWidth, 0).size
				+ utils.ParamUtil.parseSize(trackCssStyle.borderRightWidth, 0).size;

			scrollbarInfo.hHeight = scrollbarHeight;
			scrollbarInfo.hBtnWidth = scrollbarWidth - trackWidth;
		}

		private static _isTouchScrollbar(): boolean {
			return ScrollbarUtil._nativeScrollWidth === 0;
		}

	}

}