		/**
		 * 데이터셋 정보값을 설정합니다.
		 * @param info 설정할 정보값
		 */
		set info(info: string) {
			this._info = info;
		}

		/**
		 * 데이터셋 정보값을 반환합니다.
		 * @return 정보값.
		 */
