namespace cpr.ufc {
	/**
	 * @private
	 */
	class CustomHook implements vdom.VHook {
		private _hooker: (node: Element, propertyName: string, previousValue: any) => any;
		private _unhooker: (node: Element, propertyName: string, nextValue: any) => any;

		constructor(hooker: (node: Element, propertyName: string, previousValue: any) => any,
			unhooker?: (node: Element, propertyName: string, nextValue: any) => any) {
			this._hooker = hooker;
			this._unhooker = unhooker;
		}
		public hook(node: Element, propertyName: string, previousValue: any): any {
			if (this._hooker) {
				return this._hooker(node, propertyName, previousValue);
			}
		}
		public unhook(node: Element, propertyName: string, nextValue: any): any {
			if (this._unhooker) {
				return this._unhooker(node, propertyName, nextValue);
			}
		}
	}

	/**
	 * UIShape으로 VirtualDOM에 접근하여 브라우저에 HTMLElement 생성하거나 수정하는 class.
	 * 객체 생성 불가. 상속 및 Overriding 불가.
	 * 현재는 DOMRenderer를 통해서만 사용 가능.
	 * 
	 * @private
	 */
	export class VDOMRendering {
		/**
		 * UIShape의 인스턴스를 vitualDOM.VNode로 전환.
		 * 
		 * @param shape virtualDOM.VNode로 변환 할 UIShape의 인스턴스. Nullable.
		 * @return virtualDOM.VNode 변환된 VNode 객체. UIShape이 null일 경우 null을 리턴.
		 */
		private static copyAttr(shape: UIShape, vdomShape: vdom.VDomProperties): void {
			let attrNms: string[] = Object.keys(shape);
			let attrLength: number = attrNms.length;
			for (let idx: number = 0; idx < attrLength; idx++) {
				let attrNm: string = attrNms[idx];
				let attrValue: any = shape[attrNm];

				switch (attrNm) {
					case "classNames": {
						let classNames: string = null;
						// attach className
						if (typeof attrValue == "string") {
							classNames = attrValue;
							// vdomShape.className = attrValue as string;
						} else if (_isArray(attrValue)) {
							classNames = (attrValue as string[]).join(" ");
							// vdomShape.className = (attrValue as string[]).join(" ");
						}
						// else {
						// 	classNames = "";
						// }
						if (classNames) {
							if (shape.namespace === "http://www.w3.org/2000/svg") {
								let classNamesHook: CustomHook = new CustomHook((node: Element, propertyName: string, previousValue: any) => {
									node.setAttribute("class", classNames);
								});
								vdomShape.className = classNamesHook;
							} else {
								vdomShape.className = classNames;
							}
						}

						break;
					}
					case "attr": {
						// attach attributes
						vdomShape.attributes = attrValue;

						break;
					}
					case "value": {
						// attach value for INPUT ELEMENT
						// vdomShape.value = attrValue;
						// input tag에서 shape의 비교만으로는 사용자 입력에 의해 변경된 값을 되돌릴 수 없으므로 hook으로 처리
						let valuehooker: CustomHook = new CustomHook(
							(node: Element, propertyName: string, previousValue: any) => {
								if (!attrValue) {
									attrValue = "";
								}
								if (node["value"] != attrValue) {
									//input에 value를 설정하면 selection이 마지막으로 위치하기 때문에 값이 다를때만 처리(Safari에서만 발생)
									node["value"] = attrValue;
								}
							}
						);
						vdomShape["value"] = valuehooker;
						break;
					}
					case "oldvalue": {
						// attach old value for INPUT ELEMENT
						// VirtualDOM의 patch에서 Hook은 이전 값이 없을 경우 오동작하는 문제가 있음
						let oldvaluehooker: CustomHook = new CustomHook(
							(node: Element, propertyName: string, previousValue: any) => { }
						);
						vdomShape["value"] = oldvaluehooker;
						break;
					}
					case "style": {
						// attach style
						vdomShape.style = attrValue;
						break;
					}
					case "key": {
						// attach key
						vdomShape["key"] = attrValue;
						break;
					}
					case "events": {
						// attach event listeners
						// focusin, focusout 등 브라우저에 따라 addEventListener로만 동작하는 EventListener를 VirtualDom에서 지원하지 않아
						// VirtualDom에서는 Element.onfocusin = handler 방식으로 처리함
						let hookHandler: {
							[key: string]: {
								capturing: boolean, handler: (e: Event) => void
							}
						} = {};
						for (let eventName in attrValue) {
							let eventHandler: {
								capturing: boolean, handler: (e: Event) => void
							} = attrValue[eventName];

							if (EventAttacher._mustAddEventListener(eventName) == true || eventHandler.capturing === true) {
								hookHandler[eventName] = eventHandler;
							} else {
								vdomShape["on" + eventName] = eventHandler.handler;
							}
						}
						if (Object.keys(hookHandler).length > 0) {
							let eventhooker: CustomHook = new CustomHook(
								(node: Element, propertyName: string, previousValue: any) => {
									for (let eventName in hookHandler) {
										let eventHandler: {
											capturing: boolean, handler: (e: Event) => void
										} = hookHandler[eventName];

										node.addEventListener(eventName, eventHandler.handler, eventHandler.capturing);
									}
								}
							);
							vdomShape["eventhook"] = eventhooker;
						}
						break;
					}
				}
			}
		}

		private static serializeShape(shape: UIShape): vdom.VNode {
			if (shape == null) {
				return null;
			}

			let vdomShape: vdom.VDomProperties = {};
			VDOMRendering.copyAttr(shape, vdomShape);

			let tree: {
				uishape: UIShape
				, vdomShape: vdom.VDomProperties
				, vdomChild: vdom.VTreeElement[]
			}[] = [{
				uishape: shape, vdomShape: vdomShape, vdomChild: []
			}];

			let resultVNode: vdom.VNode = null;

			let depth: number = 0;
			let treeNode: { uishape: UIShape, vdomShape: vdom.VDomProperties, vdomChild: vdom.VTreeElement[] } = tree[depth];

			depthLoop: while (true) {
				let uishape: UIShape = treeNode.uishape;
				let vdomShape: vdom.VDomProperties = treeNode.vdomShape;
				let vdomChild: vdom.VTreeElement[] = treeNode.vdomChild;

				if (uishape.innerHTML) {
					// TODO Encoding CHECK
					vdomShape["innerHTML"] = uishape.innerHTML;
				} else {
					let shapeChildren: (string | UIShape)[] = uishape["children"];
					if (shapeChildren && shapeChildren.length > 0) {
						for (let childIdx: number = 0; childIdx < shapeChildren.length;) {
							let child: string | UIShape = shapeChildren.splice(0, 1)[0];
							if (typeof child === "string") {
								if (utils.StringUtil.isCharRefText(child) == true) {
									vdomShape["innerHTML"] = utils.StringUtil._encodeMinimizeForHTML(child);
								} else {
									vdomChild.push(new vdom.VText(<string>child));
								}
							} else {
								let childShape: UIShape = <UIShape>child;
								let childVdomShape: vdom.VDomProperties = {};
								let childVdomChild: vdom.VTreeElement[] = [];

								VDOMRendering.copyAttr(childShape, childVdomShape);

								depth++;
								tree[depth] = {
									uishape: childShape, vdomShape: childVdomShape, vdomChild: childVdomChild
								};
								treeNode = tree[depth];

								continue depthLoop;
							}
						}
					}
				}

				// let vdomNode: virtualdom.VNode = virtualdom.h(uishape.tag, vdomShape, vdomChild);
				// let tagName: string = uishape.tag.toUpperCase();
				let tagName: string = uishape.tag;
				let key: string;
				// support keys
				if (vdomShape.hasOwnProperty('key')) {
					key = vdomShape.key;
					vdomShape.key = undefined;
				}
				let vdomNode: vdom.VNode = new vdom.VNode(tagName, vdomShape, vdomChild, key);

				// namespace
				if (uishape.namespace) {
					vdomNode.namespace = uishape.namespace;
				}

				if (depth == 0) {
					resultVNode = vdomNode;
					break depthLoop;
				} else {
					depth--;
					treeNode = tree[depth];
					treeNode.vdomChild.push(vdomNode);
				}
			}

			return resultVNode;

		}

		/**
		 * VirtualDOM을 이용하여 브라우저의 HTMLElement를 갱신.
		 * 
		 * @param rootId 갱신할 HTMLElement를 포함하고 있는 Parent Element의 ID. 값이 없을 경우 HTML Body를 Parent Element로 처리한다. Nullable.
		 * @param newShape 갱신할 새로운 UIShape. NotNull.
		 * @param oldShape 만약 이전에 브라우저 DOM에 생성했던 Shape이 있을 경우 이전 Shape 객체. 이 값이 있을 경우 이 값을 기준으로 변경된 내용만 적용한다. Nullable.
		 * @returns 렌더링 성공 여부
		 */
		public static draw(rootId: string, newShape: UIShape, oldShape: UIShape = null, parentUUID: string = null): boolean {
			let rootNode: HTMLElement = null;
			if (rootId != null) {
				rootNode = document.getElementById(rootId);
			}

			return VDOMRendering.drawElement(rootNode, newShape, oldShape, parentUUID);
		}

		public static drawElement(rootNode: HTMLElement, newShape: UIShape, oldShape: UIShape, parentUUID: string = null): boolean {
			let vdomShape: vdom.VNode = VDOMRendering.serializeShape(newShape);

			if (rootNode) {
				if (oldShape == null) {
					let node = vdom.create(vdomShape) as HTMLElement;

					let parentElement: HTMLElement = rootNode.parentElement;
					parentElement.insertBefore(node, rootNode);
					parentElement.removeChild(rootNode);

					return true;
				} else {
					let vdomOldShape: vdom.VNode = VDOMRendering.serializeShape(oldShape);
					let patches: vdom.VPatches = vdom.diff(vdomOldShape, vdomShape);

					// patch 과정 중 발생하는 DOM 이벤트를 차단함
					// (Chrome의 경우 focus가 있는 Element가 replaceChild에 의해 교체될 때 blur 이벤트가 발생해 Grid 편집행 처리에 오류 발생)
					events.EventBus.INSTANCE._omitDOMEvent(() => {
						vdom.patch(rootNode, patches);
					});

					return true;
				}
			} else {
				if (oldShape) {
					logger("error").log("node not found");
					return false;
				}
				if (vdomShape) {
					let node = vdom.create(vdomShape) as HTMLElement;
					if (node) {
						let parentNode: HTMLElement = null;
						if (parentUUID) {
							parentNode = document.getElementById(parentUUID);
						}
						if (parentNode) {
							parentNode.appendChild(node);
						} else {
							document.body.appendChild(node);
						}
					}
				}
			}

			return true;
		}
	}
}