/// <reference path="./OrderedLayout.ts"/>
/// <reference path="../UIControl.ts"/>


namespace cpr.controls.layouts {
	/**
	 * 
	 */
	export enum FlowLayoutHorizontalAlign {
		left = "left",
		center = "center",
		right = "right"
	}

	/**
	 * 
	 */
	export enum FlowLayoutVerticalAlign {
		top = "top",
		middle = "middle",
		bottom = "bottom"
	}

	export interface FlowLayoutConstraint extends Constraint {
		/**
		 * 자동 너비를 사용하지 않는 경우 사용할 너비
		 */
		width: string

		/**
		 * 자동 높이를 사용하지 않는 경우 사용할 높이
		 */
		height: string

		/**
		 * 자동 너비 적용시 사용할 최소 너비
		 */
		minWidth?: number

		/**
		 * 자동 높이 적용시 사용할 최소 높이
		 */
		minHeight?: number


		/**
		 * 자동 크기 규칙을 얻거나 지정합니다.
		 * <ul>
		 * <li>"none" - 자동 크기를 사용하지 않습니다.</li>
		 * <li>"both" - 가로 세로 모두 자동 크기를 사용합니다.</li>
		 * <li>"width" - 너비만 자동 크기를 사용합니다.</li>
		 * <li>"height" - 높이만 자동 크기를 사용합니다.</li>
		 * </ul>
		 */
		autoSize?: AutoSizeType,
		allowNewLine?: boolean
	}

	const DEFAULT_CONSTRAINT: FlowLayoutConstraint = {
		width: "150px",
		height: "25px",
		minWidth: 0,
		minHeight: 0,
		autoSize: AutoSizeType.none,
		allowNewLine: true
	}

	interface LineInfo {
		bounds: geometry.Rectangle,
		segments: UIControl[]
	}

	/**
	 * 자식들을 차례로 옆으로 배치하며 공간이 부족한 경우 줄을 바꿔 계속해 배치해 나가는 레이아웃.
	 */
	export class FlowLayout extends OrderedLayout<FlowLayoutConstraint> {
		/**
		 * 새 플로 레이아웃을 만듭니다.
		 */
		constructor() {
			super();

			this._bindables.add("horizontalSpacing", 5).withNumberGetterTransformer(0);
			this._bindables.add("verticalSpacing", 5).withNumberGetterTransformer(0);

			["topMargin", "rightMargin", "bottomMargin", "leftMargin"]
				.forEach(prop => this._bindables.add(prop, 0).withNumberGetterTransformer(0));
			this._bindables.add("maxContentHeight", -1).withNumberGetterTransformer(0);
			this._bindables.add("maxContentWidth", -1).withNumberGetterTransformer(0);

			this._bindables.add("horizontalAlign", FlowLayoutHorizontalAlign.left)
				.withGetterTransformer(e => {
					return _isOneOfEnumValue(e, FlowLayoutHorizontalAlign)
						? e
						: FlowLayoutHorizontalAlign.left;
				});

			this._bindables.add("verticalAlign", FlowLayoutVerticalAlign.top)
				.withGetterTransformer(e => {
					return _isOneOfEnumValue(e, FlowLayoutVerticalAlign)
						? e
						: FlowLayoutVerticalAlign.top;
				});

			this._bindables.add("lineWrap", true)
				.withBooleanGetterTransformer(false);

			this._initLayout();
		}

		protected override _getType(): LayoutType {
			return LayoutType.FLOW_LAYOUT;
		}

		/**
		 * 컨트롤 사이의 간격을 얻습니다.
		 * @deprecated {@link horizontalSpacing}, {@link verticalSpacing}을 사용하시기 바랍니다.
		 */
		public get spacing(): number {
			return this.horizontalSpacing;
		}

		/**
		 * 컨트롤 사이의 간격을 지정합니다.
		 * @deprecated {@link horizontalSpacing}, {@link verticalSpacing}을 사용하시기 바랍니다.
		 */
		public set spacing(spacing: number) {
			if (this.horizontalSpacing === spacing && this.verticalSpacing === spacing) {
				return;
			}
			this.horizontalSpacing = this.verticalSpacing = spacing;
			if (this._owner) {
				this._owner.redraw();
			}
		}

		/**
		 * 컨트롤 사이의 가로 간격을 얻습니다.
		 */
		public get horizontalSpacing(): number {
			return this._bindables.get("horizontalSpacing");
		}

		/**
		 * 컨트롤 사이의 가로 간격을 지정합니다.
		 */
		public set horizontalSpacing(spacing: number) {
			this._bindables.set("horizontalSpacing", spacing);
		}

		/**
		 * 줄바꿈이 일어난 경우 적용되는 세로 간격을 얻습니다.
		 */
		public get verticalSpacing(): number {
			return this._bindables.get("verticalSpacing");
		}

		/**
		 * 줄바꿈이 일어난 경우 적용되는 세로 간격을 지정합니다.
		 */
		public set verticalSpacing(spacing: number) {
			this._bindables.set("verticalSpacing", spacing);
		}

		/**
		 * 가로 정렬 방법을 얻습니다.
		 */
		public get horizontalAlign(): FlowLayoutHorizontalAlign {
			return this._bindables.get("horizontalAlign");
		}

		/**
		 * 가로 정렬 방법을 지정합니다. "left", "center", "right" 중 하나를 선택할 수 있습니다.
		 */
		public set horizontalAlign(newAlign: FlowLayoutHorizontalAlign) {
			this._bindables.set("horizontalAlign", newAlign);
		}

		/**
		 * 한 줄 내의 세로 정렬 방법을 얻습니다.
		 */
		public get verticalAlign(): FlowLayoutVerticalAlign {
			return this._bindables.get("verticalAlign");
		}

		/**
		 * 한 줄 내에서 세로 정렬 방법을 지정합니다. "top", "middle", "bottom" 중 하나를 지정할 수 있습니다.
		 */
		public set verticalAlign(newAlign: FlowLayoutVerticalAlign) {
			this._bindables.set("verticalAlign", newAlign);
		}

		/**
		 * 줄바꿈 허용 여부를 얻습니다.
		 */
		public get lineWrap(): boolean {
			return this._bindables.get("lineWrap");
		}

		/**
		 * 줄바꿈 허용 여부를 지정합니다.
		 */
		public set lineWrap(newWrap: boolean) {
			this._bindables.set("lineWrap", newWrap);
		}

		/**
		 * 컨텐트의 최대 너비를 얻습니다. 음수 인 경우 제약이 없는 것으로 간주합니다.
		 */
		public get maxContentWidth() {
			return this._bindables.get("maxContentWidth");
		}

		/**
		 * 컨텐트의 최대 너비를 지정합니다. 레이아웃을 소유한 컨테이너가 자동 너비를 사용하는 경우에만 적용 됩니다. 음수인 경우 제약이 없는 것으로 간주합니다.
		 */
		public set maxContentWidth(newMaxWidth: number) {
			this._bindables.set("maxContentWidth", this.maxContentWidth);
		}

		/**
		 * 컨텐트의 최대 높이를 얻습니다. 음수 인 경우 제약이 없는 것으로 간주합니다.
		 */
		public get maxContentHeight() {
			return this._bindables.get("maxContentHeight");
		}

		/**
		 * 컨텐트의 최대 높이를 지정합니다. 레이아웃을 소유한 컨테이너가 자동 높이를 사용하는 경우에만 적용 됩니다. 음수인 경우 제약이 없는 것으로 간주합니다.
		 */
		public set maxContentHeight(newMaxHeight: number) {
			this._bindables.set("maxContentHeight", this.maxContentHeight);
		}

		private _redraw() {
			if (this._owner) {
				this._owner.redraw();
			}
		}

		/**
		 * 가로 여백을 지정합니다.
		 * 왼쪽과 오른쪽 모두에 적용됩니다.
		 */
		public set horizontalMargin(horizontalMargin: number) {
			this.leftMargin = horizontalMargin;
			this.rightMargin = horizontalMargin;
		}

		/**
		 * 가로 여백을 얻습니다. 왼쪽 여백과 오른쪽 여백의 평균 값이 반환 됩니다.
		 * @deprecated {@link leftMargin}과 {@link rightMargin}을 사용하시기 바랍니다.
		 */
		public get horizontalMargin() {
			return (this.leftMargin + this.rightMargin) / 2;
		}

		/**
		 * 왼쪽 여백을 지정합니다.
		 */
		public set leftMargin(leftMargin: number) {
			this._bindables.set("leftMargin", leftMargin);
		}

		/**
		 * 왼쪽 여백을 얻습니다.
		 */
		public get leftMargin(): number {
			return this._bindables.get("leftMargin");
		}

		/**
		 * 오른쪽 여백을 지정합니다.
		 */
		public set rightMargin(rightMargin: number) {
			this._bindables.set("rightMargin", rightMargin);
		}

		/**
		 * 오른쪽 여백을 얻습니다.
		 */
		public get rightMargin(): number {
			return this._bindables.get("rightMargin");
		}

		/**
		 * 세로 여백을 지정합니다. 상단과 하단에 모두 적용됩니다.
		 */
		public set verticalMargin(verticalMargin: number) {
			this.topMargin = verticalMargin;
			this.bottomMargin = verticalMargin;
		}

		/**
		 * 세로 여백을 얻습니다. 상단과 하단의 평균 여백 값이 반환 됩니다.
		 * @deprecated {@link topMargin}과 {@link bottomMargin}을 사용하시기 바랍니다.
		 */
		public get verticalMargin() {
			return (this.topMargin + this.bottomMargin) / 2;
		}

		/**
		 * 상단 여백을 지정합니다.
		 */
		public set topMargin(topMargin: number) {
			this._bindables.set("topMargin", topMargin);
		}

		/**
		 * 상단 여백을 얻습니다.
		 */
		public get topMargin(): number {
			return this._bindables.get("topMargin");
		}

		/**
		 * 하단 여백을 지정합니다.
		 */
		public set bottomMargin(bottomMargin: number) {
			this._bindables.set("bottomMargin", bottomMargin);
		}

		/**
		 * 하단 여백을 얻습니다.
		 */
		public get bottomMargin(): number {
			return this._bindables.get("bottomMargin");
		}

		private _computeOverflowY() {
			if (!this.scrollable) {
				return this._getOverflowYForNonScroll();
			}
			if (this._ownerHasAutoHeight()) {
				if (this.maxContentHeight >= 0) {
					return "auto";
				} else {
					return this._getOverflowYForNonScroll();
				}
			}
			else {
				return "auto";
			}
		}

		private _computeOverflowX() {
			if (!this.scrollable) {
				return this._getOverflowXForNonScroll();
			}
			if (this._ownerHasAutoWidth()) {
				if (this.maxContentWidth >= 0) {
					return "auto";
				} else {
					return this._getOverflowXForNonScroll();
				}
			}
			else {
				return "auto";
			}
		}

		private _computePaddings(): geometry.Insets {
			let paddings: geometry.Insets;

			if (this.scrollable) {
				let horizontalHalfSpacing = Math.floor(this.horizontalSpacing / 2);
				let verticalHalfSpacing = Math.floor(this.verticalSpacing / 2);

				paddings = new geometry.Insets(
					Math.max(this.topMargin - verticalHalfSpacing, 0),
					Math.max(this.rightMargin - horizontalHalfSpacing, 0),
					Math.max(this.bottomMargin - verticalHalfSpacing, 0),
					Math.max(this.leftMargin - horizontalHalfSpacing, 0)
				);
			}
			else {
				paddings = new geometry.Insets(
					this.topMargin,
					this.rightMargin,
					this.bottomMargin,
					this.leftMargin
				)
			}

			return paddings;
		}

		protected _doCreateLayoutShape(): cpr.ufc.ControlShape {
			let paddings = this._computePaddings();

			let childControls: UIControl[] = this._owner.getChildren();

			let contentPane: ufc.ElementShape = {
				tag: "div",
				nodename: LayoutConstants.NODE_NAME__CONTENT_PANE,
				attr: {
				},
				classNames: [ufc.Classes.CONTENT_PANE],
				style: {
					textAlign: this.horizontalAlign,
					padding: `0px ${paddings.right}px 0px ${paddings.left}px`,
					height: "100%"
				},
				children: []
			};
			if (this._owner.childCombinatorClass) {
				contentPane.classNames.push(this._owner.childCombinatorClass);
			}

			let overflowX = this._computeOverflowX();
			let overflowY = this._computeOverflowY();

			let layoutShape: ufc.ControlShape = {
				tag: "div",
				nodename: LayoutConstants.NODE_NAME__LAYOUT,
				attr: {
				},
				classNames: [ufc.Classes.LAYOUT],
				style: _mergeObject({
					position: "relative",
					overflowX: overflowX,
					overflowY: overflowY,
					whiteSpace: this.lineWrap ? "normal" : "nowrap"
				}),
				events: { scroll: this._notifyScrollEvent.bind(this) },
				children: [contentPane]
			};
			if (this._owner.childCombinatorClass) {
				layoutShape.classNames.push(this._owner.childCombinatorClass);
			}

			// 레이아웃 높이 공간 확보
			if (this._ownerHasAutoHeight()) {
				if (this.maxContentHeight >= 0) {
					layoutShape.style.maxHeight = `${this.maxContentHeight}px`;
				}
			}
			else {
				// 자동 높이 아님.
				layoutShape.style.height = "100%";
			}

			// 레이아웃 너비 공간 확보
			if (this._ownerHasAutoWidth()) {
				if (this.maxContentWidth >= 0) {
					layoutShape.style.maxWidth = `${this.maxContentWidth}px`;
				}
			}

			// 스크롤러블 처리
			if (!this.scrollable) {
				layoutShape.style.margin = `-${this.verticalSpacing}px 0px 0px -${this.horizontalSpacing}px`;
				layoutShape.style.height = `calc(100% + ${this.verticalSpacing}px)`;
				contentPane.style.height = `calc(100% - ${this.verticalSpacing}px)`;
			}

			// 상단 여백 확보
			if (paddings.top > 0) {
				contentPane.children.push({
					"tag": "div",
					classNames: [ufc.Classes.MARGIN, ufc.Classes.MARGIN_TOP],
					attr: {
						"data-role": "margin"
					},
					style: {
						height: `${paddings.top}px`,
						margin: "0px"
					}
				});
			}

			contentPane.children = contentPane.children.concat(this._applyLayoutShape(childControls))

			// 하단 여백 확보
			if (paddings.bottom > 0) {
				contentPane.children.push({
					"tag": "div",
					classNames: [ufc.Classes.MARGIN, ufc.Classes.MARGIN_BOTTOM],
					attr: {
						"data-role": "margin"
					},
					style: {
						height: `${paddings.bottom}px`,
						margin: "0px"
					}
				});
			}


			if (this._owner._useBodyScroll()) {
				layoutShape.style.height = "auto";
				layoutShape.style.overflowX = "visible";
				layoutShape.style.overflowY = "visible";
				contentPane.style.height = "auto";
			}

			// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/6450
			// 바디스크롤인 경우 마크하지 않아야 합니다.
			if (this.scrollable) {
				internal.ScrollbarUtil._markScrollableContentPane(layoutShape); // CustomScroll Enable
			}

			this._owner._hookLayout(LayoutConstants.NODE_NAME__CONTENT_PANE, contentPane);
			return layoutShape;
		}

		private _applyLayoutShape(childControls: UIControl[]): (ufc.ControlRenderer | ufc.ControlShape | ufc.ElementShape)[] {
			let layoutShape: (ufc.ControlRenderer | ufc.ControlShape)[] = [];

			childControls.forEach((control: UIControl, index: number) => {
				if (control == null || control.disposed == true) {
					return;
				}
				let controlRenderer: ufc.ControlRenderer = control._getRenderer();
				if (controlRenderer == null) {
					return;
				}

				let controlShape: ufc.ControlRenderer | ufc.ControlShape = this.applyConstraint(index, control, controlRenderer);
				if (controlShape) {
					let constraint = this._getOwner().getConstraint(control) as FlowLayoutConstraint;
					constraint = _mergeObject(this._getDefaultConstraint(), constraint);

					if (layoutShape.length > 0 && _isManualConstraint(constraint) === false && constraint.allowNewLine === false) {
						this._appendNonLineBreakable(layoutShape, controlShape);
					}
					else {
						layoutShape.push(controlShape);
					}
				}
			});

			return layoutShape;
		}

		private _appendNonLineBreakable(targetList: (ufc.ControlRenderer | ufc.ControlShape)[], nonLineBreakable: ufc.ElementShape | ufc.ControlRenderer) {
			let target = _.last(targetList);
			let previous: ufc.ElementShape = null;
			if (target instanceof ufc.ControlRenderer || target.attr?.["data-role"] != "nowrap-container") {
				targetList.pop();
				previous = {
					tag: "div",
					classNames: this._owner.childCombinatorClass ? [this._owner.childCombinatorClass] : [],
					style: {
						display: "inline-block",
						whiteSpace: "nowrap",
						// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/7762
						verticalAlign: this.verticalAlign
					},
					attr: {
						"data-role": "nowrap-container"
					},
					children: [target]
				};

				targetList.push(previous);
			} else {
				previous = target as ufc.ElementShape;
			}
			previous.children.push(nonLineBreakable);
		}

		_doDecorateChild(context: LayoutDecorationContext<FlowLayoutConstraint>): ufc.ControlShape {
			let controlShape = context.controlShape;
			let control = context.childControl;
			let constraint = context.constraint;

			let psudoClasses: string[] = [];
			if (this._getFirstVisibleLayoutChild() === context.childControl) {
				psudoClasses.push(ufc.Classes.FIRST);
			}
			if (this._getLastVisibleLayoutChild() === context.childControl) {
				psudoClasses.push(ufc.Classes.LAST);
			}

			controlShape.classNames = (controlShape.classNames || []).concat(psudoClasses);

			if (control instanceof cpr.controls.Image) {
				controlShape.style = _mergeObject(controlShape.style, {
					"display": "inline-block",
					"position": "relative"
				});
			}

			let wrapperStyles: { [key: string]: string } = {
				position: "relative",
				display: "inline-block",
				verticalAlign: this.verticalAlign
			};

			function processMinHeight(hasAutoWidth: boolean) {
				if (constraint.minHeight <= 0) {
					return;
				}
				let minHeight = constraint.minHeight;

				// 명시적 높이를 가진 경우.
				if (_isPixelValue(wrapperStyles["height"])) {
					// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/6515
					minHeight = Math.max(minHeight, parseFloat(wrapperStyles["height"]));
					delete wrapperStyles["height"];
				}

				GridCSSBuilder._forLayout()
					._withInlineGrid()
					// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/6516
					// 가로가 100% 초과하지 못하는 문제 수정.
					// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/6546
					// 6516 수정에 의해 가로로 예기치 않게 늘어나는 문제 확인하여 수정.
					._withTemplateColumns(hasAutoWidth ? 'minmax(min-content, 1fr)' : "1fr")
					._withTemplateRows(`minmax(${constraint.minHeight}px, 1fr)`)
					._commit(wrapperStyles);
			}

			function processMinWidth() {
				if (constraint.minWidth <= 0) {
					return;
				}
				wrapperStyles.minWidth = `${constraint.minWidth}px`;
			}

			switch (constraint.autoSize) {
				case AutoSizeType.both: {
					let size = this._computeAutoSize(control, constraint.width, constraint.height);
					wrapperStyles.width = size.width;
					wrapperStyles.height = size.height;
					processMinWidth();
					processMinHeight(true);
					break;
				}
				case AutoSizeType.width: {
					let size = this._computeAutoSize(control, constraint.width, constraint.height);
					wrapperStyles.width = size.width;
					wrapperStyles.height = constraint.height;
					processMinWidth();
					break;
				}
				case AutoSizeType.height: {
					let size = this._computeAutoSize(control, constraint.width, constraint.height);
					wrapperStyles.width = constraint.width;
					wrapperStyles.height = size.height;
					processMinHeight(false);
					break;
				}

				default: {
					wrapperStyles.width = constraint.width;
					wrapperStyles.height = constraint.height;
				}
			}
			controlShape.style = _mergeObject(controlShape.style, {
				width: "100%",
				height: "100%"
			});

			if (this.scrollable) {
				wrapperStyles.margin = `${this.verticalSpacing / 2}px  ${this.horizontalSpacing / 2}px`;
			}
			else {
				wrapperStyles.margin = `${this.verticalSpacing}px 0px 0px ${this.horizontalSpacing}px`;
			}

			return this.wrap(controlShape, {
				tag: "div",
				key: control.uuid,
				classNames: psudoClasses,
				style: _assign(wrapperStyles, this._getAnimatingProperties())
			});

		}

		protected applyConstraint(index: number, control: UIControl, controlRenderer: ufc.ControlRenderer): ufc.ControlRenderer {
			controlRenderer.addLayoutDecorator(this._createLayoutDecorator(control));
			return controlRenderer;
		}

		/**
		 * @override
		 */
		public _getSupportedAutoSizeMode() {
			return AutoSizeType.both;
		}

		/**
		 * @override
		 */
		public _getAutoSizeType(constraint: FlowLayoutConstraint) {
			if (!constraint) {
				return AutoSizeType.none;
			}
			return constraint.autoSize || AutoSizeType.none;
		}

		/**
		 * @param controls
		 */
		protected _doUpdateControl(controls: UIControl[]): void {
			controls.forEach((control: UIControl) => {
				control.redraw();
			});
		}

		protected _compareConstraint(a: FlowLayoutConstraint, b: FlowLayoutConstraint): boolean {
			return a.autoSize == b.autoSize
				&& a.width == b.width
				&& a.height == b.height;
		}

		public _supportsBodyScroll(): boolean {
			return true;
		}

		public _applyBodyScrollToContainerShape(shape: ufc.ControlShape) {
			_assign(shape.style, {
				height: "auto",
				minHeight: "100%"
			});
		}

		/** @override */
		protected _getDefaultConstraint() {
			return DEFAULT_CONSTRAINT;
		}

		/** @override */
		public _getRenderedLayoutInfo(): RenderedLayoutInfo {
			return {
				layoutNodeName: LayoutConstants.NODE_NAME__LAYOUT,
				scrollingNodeName: LayoutConstants.NODE_NAME__LAYOUT,
				contentPaneNodeName: LayoutConstants.NODE_NAME__CONTENT_PANE,
				offsetIndexForChildren: this._computePaddings().top > 0 ? 1 : 0
			}
		}

		public getInsertionReference(location: geometry.Point): OrderedInsertionReference {
			let orderedChildren = this._getOrderedChildren();

			if (utils.Util.isNullOrEmpty(orderedChildren)) {
				return {
					index: 0,
					previousSibiling: null,
					nextSibiling: null
				};
			}

			let allChildren = this._getOwner().getChildren();

			// 줄 모델 구성.
			let lines: LineInfo[] = [];
			orderedChildren.forEach(eachControl => {
				let eachBounds = eachControl.getActualRect();
				let currentLine = _.last(lines);
				if (!currentLine || eachBounds.left < currentLine.bounds.right) {
					lines.push({
						bounds: eachBounds.getCopy(),
						segments: [eachControl]
					})
				}
				else {
					currentLine.bounds.union(eachBounds);
					currentLine.segments.push(eachControl);
				}
			});

			// 가장 가까운 줄 찾기
			let closestLine = utils.Util.minBy(lines, it => {
				if (it.bounds.containsPoint(location)) {
					return 0;
				}
				else {
					return Math.min(
						Math.abs(it.bounds.y - location.y),
						Math.abs(it.bounds.bottom - location.y)
					);
				}

			});
			let nextSibiling = closestLine.segments.find(it => {
				return it.getActualRect().center.x > location.x;
			});

			// 줄 내에 다음 자식이 없다면 다음 줄에서 찾음.
			if (!nextSibiling) {
				nextSibiling = orderedChildren[orderedChildren.indexOf(_.last(closestLine.segments)) + 1];
			}

			let orderedIndex = nextSibiling ? orderedChildren.indexOf(nextSibiling) : orderedChildren.length;
			let insertIndex = nextSibiling ? allChildren.indexOf(nextSibiling) : allChildren.length;
			return {
				index: insertIndex,
				previousSibiling: orderedIndex > 0 ? orderedChildren[orderedIndex - 1] : null,
				nextSibiling: nextSibiling
			};


		}

		public _shouldOCPRParticipateChild(child: UIControl, constraint: any, isAdd: boolean) {
			if (_isManualConstraint(constraint)) {
				return true;
			}

			if (constraint.allowNewLine === false) {
				return false;
			}

			// 줄바꿈을 허용하지 않는 요소가 존재할 경우 최적화 렌더링 불능.
			let owner = this._getOwner();
			if (owner._getChildrenInfo().values().some(it => {
				return !_isManualConstraint(it) && (it as FlowLayoutConstraint).allowNewLine === false;
			})) {
				return false;
			}

			return true;
		}

		protected override _normalizeConstraint(constraint: FlowLayoutConstraint): FlowLayoutConstraint {
			["width", "height"].filter(prop => {
				return typeof constraint?.[prop] == "number"
			}).forEach(prop => {
				constraint[prop] = `${constraint[prop]}px`
			});
			return constraint;
		}
	}
}