/// <reference path="./UIControl.ts" />
/// <reference path="./TextEditor.ts" />


namespace cpr.controls {

	/**
	 * @private
	 */
	enum SearchInputClassName {
		search = "cl-searchinput-search",
		clear = "cl-searchinput-clear"
	}
	/**
	 * SearchInput
	 * 인풋박스와 검색버튼이 결합된 컨트롤
	 * 검색데이터를 입력할 수 있습니다.
	 * 
	 * @firesgroup mouse
	 * @firesgroup contextmenu
	 * @firesgroup bindcontext
	 * @firesgroup keyboard
	 * @firesgroup focus
	 * @firesgroup drop
	 * @firesgroup input
	 * 
	 * 
	 * @fires cpr.events.CValueChangeEvent#before-value-change Searchinput의 value를 변경하여 변경된 값이 저장되기 전에 발생하는 이벤트.
	 * 		다음 이벤트로 value-change가 발생합니다.
	 * 		<pre>oldValue: {string} 이전 값</pre>
	 * 		<pre>newValue: {string} 현재 값</pre>
	 * 
	 * @fires cpr.events.CValueChangeEvent#value-change Searchinput의 value를 변경하여 변경된 값이 저장된 후에 발생하는 이벤트.
	 * 		<pre>oldValue: {string} 이전 값</pre>
	 * 		<pre>newValue: {string} 현재 값</pre>
	 * 
	 * @fires cpr.events.CMouseEvent#search Searchinput의 enter키 또는 검색버튼을 클릭하여 인풋의 값이 Search될때 발생하는 이벤트
	 * 
	 * 
	 * @fires cpr.events.CMouseEvent#clear Searchinput에서 esc키 또는 클리어버튼을 클릭하여 인풋의 값이 Clear될때 발생하는 이벤트
	 */

	export class SearchInput extends TextEditor {

		private static readonly _AVAILABLE_PROP: string[] = [
			"placeholder", "autoSelect", "autocomplete", "searchButtonImage", "clearButtonImage", "hideClearButton",
			"hideSearchButton", "imeMode", "searchPosition", "buttonFocusable", "preventInput", "inputFilter",
			"clearLabelExp", "searchLabelExp", "maxLength", "autoSkip", "lengthUnit", "inputMode", "displayExp"
		];

		private _autoselect: boolean = false;
		private _inputFilter: foundation.InputFilter;
		private _imemode: ImeMode; /* auto, active, inactive, disabled */
		private _inputMode: InputMode;

		private _dropData: { text: string, isSelf: boolean, isIE: boolean } = null;
		private _isDeleteByDrag: boolean = false;

		private _buttonFocusable: boolean = false;
		private _autoskip: boolean = false;
		private _lengthunit: TextLengthUnit = 0; /* char, utf8, ascii */
		private _maxlength: number = -1;
		private _textEditorMaxLength: TextEditorMaxLength;
		private _displayExp: expression_string;

		private _searchBtnFocusEntry = new TextInputFocusEntry(this, `.${SearchInputClassName.search}`);
		private _clearBtnFocusEntry = new TextInputFocusEntry(this, `.${SearchInputClassName.clear}`);
		private _requestRestoreFocus: boolean = false;

		/**
		 * 서치 인풋을 생성합니다.
		 * @param id 서치 인풋의 id
		 */
		constructor(id?: string) {
			super(id);

			//bindable
			this._addBindableProperty("placeholder", "").withSetterValidatorWithType(false, "string");
			this._addBindableProperty("autocomplete", "").withSetterValidatorWithType(false, "string");
			this._addBindableProperty("displayExp", "").withSetterValidatorWithType(false, "string");
			this._addBindableProperty("searchButtonImage", "").withSetterValidatorWithType(false, "string", true).withStringGetterTransformer("");
			this._addBindableProperty("clearButtonImage", "").withSetterValidatorWithType(false, "string", true).withStringGetterTransformer("");
			this._addBindableProperty("searchPosition", "right").withSetterValidatorWithType(false, "string");
			this._addBindableProperty("hideClearButton", false).withSetterValidatorWithType(false, "boolean");
			this._addBindableProperty("hideSearchButton", false).withSetterValidatorWithType(false, "boolean");
			this._addBindableProperty("preventInput", false).withSetterValidatorWithType(false, "boolean");

			// defaults.js에서 사용하는 속성
			this._setInternalProperty("clearLabelExp", "");
			this._setInternalProperty("searchLabelExp", "");

			this._inputFilter = new foundation.InputFilter();
			this._imemode = ImeMode.auto;

			this._textEditorMaxLength = new TextEditorMaxLength(this, {
				onMaxlength: () => {
					if (this.autoSkip && this.focused) {
						this.focusNext();
					}
				},
				onBeforePaste: () => {
					this._inputFilter.invalidate();
				},
				onAfterPaste: (text: string) => {
					this._updateClearButton(text);
				},
				transformDropTextHandler: (text: string) => {
					return this._inputFilter.filterText(text);
				},
				transformPasteTextHandler: (text: string) => {
					return this._inputFilter.filterText(text);
				},
				computeDisplayText: (text: string) => {
					return this._computeDisplayingValue(text);
				}
			});
			// control initializing
			this._initControl();
		}

		/**
		 * 컨트롤의 value가 변경된 내용을 기준으로 포맷이 된 text를 반환합니다.
		 * @return display되는 text.
		 */
		protected override _getText(): string {
			let value = this._getValue();
			if (this.displayExp) {
				value = ufc.StyledString._asString(this._computeDisplayExpText(value));
			}
			return value;
		}

		protected override _transformDisplayText(value: string): string | ufc.StyledString {
			if (this.placeholder != "" && value == "") {
				return value;
			}
			if (!this.preventInput) {
				if (this.displayExp && (!this.focused || this.readOnly)) {
					return ufc.StyledString._asString(this._computeDisplayExpText(value));
				}
				return ufc.StyledString._asString(value);
			}
			if (this.displayExp) {
				return this._computeDisplayExpText(value);
			}
			return value;
		}

		protected _isConfigurableProperty(propName: string): boolean {
			if (SearchInput._AVAILABLE_PROP.indexOf(propName) != -1) {
				return true;
			}
			return super._isConfigurableProperty(propName);
		}

		/* Shape */
		protected _getStylerSpec(): UIControlStylerSpec {
			return {
				root: { baseClass: "cl-searchinput" },
				search: { baseClass: "cl-searchinput-search" },
				clear: { baseClass: "cl-searchinput-clear" },
			};
		}

		/**
		 * 자동 크기 지원 타입을 얻습니다.
		 * 만일 both를 리턴했다면, css height, width 속성에 auto를 사용할 수 있음을 나타냅니다.
		 */
		public _getAutoSizeAvailability(): layouts.AutoSizeType {
			return layouts.AutoSizeType.both;
		}

		/* control's type overriding */
		override _getType(): ControlType {
			return ControlType.SEARCHINPUT;
		}
		override _getLabelableType(): LabelableType {
			return this.preventInput ? LabelableType.div : super._getLabelableType();
		}
		/**
		 * @param name 
		 * @param oldValue 
		 * @param newValue 
		 */
		_valueDidChange(name: string, oldValue: any, newValue: any) {
			super._valueDidChange(name, oldValue, newValue);
			switch (name) {
				case "placeholder":
				case "autocomplete":
				case "hideClearButton":
				case "hideSearchButton":
				case "searchPosition":
				case "clearButtonImage":
				case "searchButtonImage": {
					this.redraw();
					break;
				}
				case "preventInput": {
					this._requestRestoreFocus = true;
					this.redraw();
					break;
				}
			}
		}

		/* property */
		/**
		 * 설명 또는 예상된 값에 대한 문구(힌트)를 반환합니다.
		 * @return 설명 또는 예상된 값에 대한 문구.
		 */
		get placeholder(): string {
			return this._bindables.get("placeholder");
		}

		/**
		 * 설명 또는 예상된 값에 대한 문구(힌트)를 설정합니다.
		 * @param placeholder 설명 또는 예상된 값에 대한 문구.
		 */
		set placeholder(placeholder: string) {
			this._bindables.set("placeholder", placeholder);
		}

		/**
		 * 입력 문자에 대한 regexp를 가져옵니다.
		 * @return 정규식 regexp.
		 */
		get inputFilter(): expression_string {
			return this._inputFilter.filter;
		}

		/**
		 * 입력 문자에 대한 regexp를 지정합니다.
		 * @param regexp 정규식 소문자:[a-z]|대문자:[A-Z]|숫자:[0-9]
		 */
		set inputFilter(regexp: expression_string) {
			this._inputFilter.filter = regexp;
			this.redraw();
		}

		/**
		 * inputbox의 입력된 값(문자열)의 길이를 반환합니다.
		 * @return 입력된 값의 길이.
		 */
		get length(): number {
			return this.displayingText.length;
		}

		/**
		 * IE, FireFox 브라우저에서 한영 변환 설정을 반환합니다.
		 * @return 한영 변환 설정
		 */
		get imeMode(): ImeMode {
			return this._imemode;
		}

		/**
		 * IE, FireFox 브라우저에서 키보드 IME에 대한 한영 변환 설정. CSS의 ime-mode속성을 사용합니다. 지원하는 브라우저 버전에 따라 지원이 안될 수 있으니 MDN문서를 확인하시기 바랍니다. <br>
		 * [auto] : 현재 inputbox의 ime 설정에 대해 아무것도 하지않습니다.<br>
		 * [active] : 기본 값으로 한글을 입력받습니다. <br>
		 * [inactive] : 기본 값으로 영문을 입력받습니다.<br>
		 * [disabled] : 영문만을 입력받습니다.
		 * @param imemode 
		 */
		set imeMode(imemode: ImeMode) {
			if (typeof imemode == "string") {
				imemode = imemode.toLowerCase() as any;
			}
			if (!ImeMode[imemode]) {
				imemode = null;
			}
			if (this._imemode == imemode) {
				return;
			}
			this._imemode = imemode;
			this.redraw();
		}

		/**
		 * 브라우저에서 가상키보드를 표시하는 자판의 배열 타입을 반환합니다.
		 */
		get inputMode(): InputMode {
			return this._inputMode;
		}

		/**
		 * 브라우저에서 가상키보드를 표시하는 자판의 배열 타입을 설정합니다.
		 */
		set inputMode(inputMode: InputMode) {
			if (this._inputMode == inputMode) {
				return;
			}
			this._inputMode = inputMode;
			this.redraw();
		}

		/**
		 * 포커스 될 시 편집 영역의 데이터 전체 선택 여부를 반환합니다.
		 * @return 포커스 될 시 편집 영역의 데이터 전체 선택 여부.
		 */
		get autoSelect(): boolean {
			return this._autoselect;
		}

		/**
		 * 포커스 될 시 편집 영역의 데이터 전체 선택 여부를 설정합니다.
		 * @param autoselect 포커스 될 시 편집 영역의 데이터 전체 선택 여부.
		 */
		set autoSelect(autoselect: boolean) {
			this._autoselect = autoselect;
			if (autoselect === true) {
				this._defaultSelection.state = SelectionState.NONE;
			}
			this.redraw();
		}

		/**
		 * 브라우저의 자동완성 기능 설정값을 반환합니다.
		 */
		get autocomplete() {
			return this._bindables.get("autocomplete");
		}

		/**
		 * 브라우저의 자동완성 기능 설정 값을 설정합니다. 기본값은 빈 값입니다.
		 */
		set autocomplete(value: string) {
			this._bindables.set("autocomplete", value);
		}

		/**
		 * search버튼의 이미지를 반환합니다.
		 * @return search버튼 이미지.
		 */
		get searchButtonImage(): string {
			return this._bindables.get("searchButtonImage");
		}
		/**
		 * search버튼의 이미지를 설정합니다.
		 * @param src search버튼 이미지.
		 */
		set searchButtonImage(src: string) {
			this._bindables.set("searchButtonImage", src);
		}

		/**
		 * clear버튼 이미지를 반환합니다.
		 * @return clear버튼 이미지.
		 */
		get clearButtonImage(): string {
			return this._bindables.get("clearButtonImage");
		}
		/**
		 * clear버튼 이미지를 설정합니다.
		 * @param src clear버튼 이미지.
		 */
		set clearButtonImage(src: string) {
			this._bindables.set("clearButtonImage", src);
		}

		/**
		 * search버튼의 숨김여부를 반환합니다
		 * @return search버튼 숨김여부
		 */
		get hideSearchButton() {
			return this._bindables.get("hideSearchButton");
		}
		/**
		 * search버튼의 숨김여부를 설정합니다.
		 * @param hideSearchButton search버튼 숨김여부설정.
		 */
		set hideSearchButton(hideSearchButton: boolean) {
			this._bindables.set("hideSearchButton", hideSearchButton)
		}

		/**
		 * clear버튼의 숨김여부를 반환합니다
		 * @return clear버튼 숨김여부
		 */
		get hideClearButton() {
			return this._bindables.get("hideClearButton");
		}

		/**
		 * clear버튼의 숨김여부를 설정합니다.
		 * @param hideClearButton clear버튼 숨김여부설정.
		 */
		set hideClearButton(hideClearButton: boolean) {
			this._bindables.set("hideClearButton", hideClearButton)
		}

		/**
		 * search버튼의 위치(인풋박스의 왼쪽 또는 오른쪽)를 반환합니다
		 * @return search버튼의 위치
		 */
		get searchPosition() {
			return this._bindables.get("searchPosition");
		}
		/**
		 * search버튼의 위치(인풋박스의 왼쪽 또는 오른쪽)를 설정합니다.
		 * @param position search버튼의 위치
		 */
		set searchPosition(position: "left" | "right") {
			this._bindables.set("searchPosition", position);
		}

		/**
		 * 버튼에 포커스를 설정값을 반환합니다.
		 * @return 버튼 포커스 여부
		 */
		get buttonFocusable() {
			return this._buttonFocusable;
		}
		/**
		 * 버튼에 포커스를 설정합니다.
		 * @param focusable 버튼 포커스 여부
		 */
		set buttonFocusable(focusable: boolean) {
			this._buttonFocusable = focusable;
			this.redraw();
		}

		/**
		 * inputbox를 통한 입력 방지 여부를 반환합니다.
		 */
		get preventInput(): boolean {
			return this._bindables.get("preventInput");
		}

		/**
		 * inputbox를 통한 입력 방지 여부를 설정합니다.
		 */
		set preventInput(prevent: boolean) {
			this._bindables.set("preventInput", prevent);
		}

		/**
		 * 입력이 가능한 최대 문자 수를 반환합니다.
		 * @return 입력이 가능한 최대 문자 수.
		 */
		get maxLength(): number {
			return this._maxlength;
		}

		/**
		 * 입력이 가능한 최대 문자 수를 설정합니다.
		 * @param length 입력이 가능한 최대 문자 수.
		 */
		set maxLength(length: number) {
			if (typeof length != "number") {
				return;
			}
			this._maxlength = length;
			this.redraw();
		}

		/**
		 * 입력된 문자열이 maxlength에 채워지거나 Enter를 눌러 값이 변경 되었을 때 다음 컨트롤로 포커스 이동 여부를 반환합니다.
		 * @return 다음 컨트롤로 포커스 이동 여부.
		 */
		get autoSkip(): boolean {
			return this._autoskip;
		}

		/**
		 * 입력된 문자열이 maxlength에 채워지거나 Enter를 눌러 값이 변경 되었을 때 다음 컨트롤로 포커스 이동 여부를 설정합니다.
		 * 이 기능은 키보드의 영문,숫자,기호에 한하여 정상 동작합니다.
		 * 관련 속성 : [maxLength] maxLength속성이 존재 할 시 해당 속성이 동작합니다.
		 * @param skip 다음 컨트롤로 포커스 이동 여부.
		 */
		set autoSkip(skip: boolean) {
			this._autoskip = skip;
		}

		/**
		 * 편집 영역의 전체 문자열 길이의 단위를 반환합니다.
		 * @return 전체 문자열 길이의 단위.
		 */
		get lengthUnit(): string {
			return TextLengthUnit[this._lengthunit];
		}

		/**
		 * 편집 영역의 전체 문자열 길이의 단위를 설정합니다.
		 * [char] : 문자의 길이.
		 * [utf8] : utf8 기준의 문자 byte size.
		 * [ascii] : ascii 기준의 문자 byte size.
		 * @param unit 전체 문자열 길이의 단위.
		 */
		set lengthUnit(unit: string) {
			if (typeof unit == "string") {
				unit = unit.toLowerCase();
			}
			let lengthUnit = TextLengthUnit[unit];
			if (typeof lengthUnit != "number") {
				return;
			}
			this._lengthunit = lengthUnit;
			this.redraw();
		}

		/**
		 * 포커스 상태가 아닐때 보여지는 텍스트에 대한 Expression을 반환합니다.
		 * @return 화면에 보여지는 텍스트의 Expression.
		 */
		get displayExp(): expression_string {
			return this._displayExp;
		}

		/**
		 * 포커스 상태가 아닐때 보여지는 텍스트에 대한 Expression을 설정합니다. <br>
		 * @param expr 화면에 보여지는 텍스트의 Expression.
		 */
		set displayExp(expr: expression_string) {
			if (this._displayExp == expr) {
				return;
			}

			this._displayExp = expr;
			this.redraw();
		}

		/**
		 * 인풋에서 보여지는 HTML Element의 value를 가져옵니다.
		 * {@link displayExp}에서 지원되지 않는 속성입니다.
		 * @return 표시중인 text.
		 */
		get displayingText(): string {
			return this.displayText;
		}

		/**
		 * 인풋에서 보여지는 HTML Element의 value를 가져옵니다.
		 * {@link displayExp}에서 지원되지 않는 속성입니다.
		 * @return display되는 text.
		 * @deprecated {@link displayingText}를 사용하시기 바랍니다.
		 */
		get displayText(): string {
			let input = this._getRenderer().getNamedNode("text") as HTMLInputElement;
			if (!input) {
				return this.text ?? "";
			}
			if (this.preventInput) {
				if (this._getValue() == "" && this.placeholder) {
					return ufc.StyledString._asString(this._transformDisplayText(""));
				}// textContent: 요소 안에 모든 텍스트를 그대로 가져옴. display:none인 요소도 가져옴
				return input.innerText; //innerText: 사용자가 보이는 것 기준으로 텍스트를 반환
			}
			return input.value;
		}

		private _computeDisplayExpText(value: string): ufc.StyledString | string {
			let expr = new cpr.expression.Expression(this.displayExp);
			let result: any;
			try {
				let that = this;
				let edo = new cpr.expression.ExpressionDelegateObject(this.type, "displayExp", { text: value });
				edo.setUnsupportedProperty("displayText", "");
				edo.setUnsupportedProperty("displayingText", "");
				let altProperty = edo.createObject();
				result = expr._evaluateInternal({
					_getExpressionDelegates(): any[] {
						return [altProperty, that, that.getBindContext()];
					}
				});
			} catch (e) {
				result = value;
			}
			return result;
		}

		private _computeDisplayingValue(text: string): string {
			if (!this.focused && this.displayExp) {
				return this._getValue();
			}
			return text;
		}

		/**
		 * Search 이벤트를 발생합니다.<br>
		 * search 이벤트에 해당하는 eventlistener의 함수를 수행합니다.
		 */
		public search(): void {
			this._onSearch();
		}

		/**
		* 서치인풋의 value를 빈 값으로 설정합니다. <br>
		* clear 이벤트를 발생합니다.
		* @param emitEvent clear이벤트를 발생시킬지 여부
		*/
		public clear(emitEvent: boolean = true): void {
			this._clear(emitEvent);
		}

		public dispose(): void {
			if (this._textEditorMaxLength) {
				this._textEditorMaxLength.dispose();
				this._textEditorMaxLength = null;
			}
			super.dispose();
		}

		public override _afterDraw(firstDraw: boolean = false): void {
			super._afterDraw(firstDraw);
			this._restoreFocus();
		}

		/* shape */
		public _createShape(): cpr.ufc.ControlShape {
			//css class
			let classNames: string[] = [];
			let templateColumns: string[] = [];
			let input: ufc.ElementShape = this.preventInput ? this._createText() : this._createInput();
			let isLeftPosition = this.searchPosition == "left" && this.hideSearchButton == false;
			/* shape */
			let div: cpr.ufc.ElementShape = {
				tag: "div",
				style: {
					width: "100%",
					height: "100%",

				},
				children: [input]
			}
			let columnIndex = isLeftPosition ? 2 : div.children.length;
			templateColumns[columnIndex - 1] = "1fr";
			layouts.GridCSSBuilder._forCell()._withVerticalAlign(layouts.GridCellAlign.center)._withColumnStart(columnIndex)._withRowStart(1)._commit(input.style)

			if (this.hideClearButton == false) {
				let clearButton = this._createClear();
				div.children.push(clearButton);
				columnIndex = isLeftPosition ? 3 : div.children.length;
				templateColumns[columnIndex - 1] = "auto";
				layouts.GridCSSBuilder._forCell()._withVerticalAlign(layouts.GridCellAlign.center)._withColumnStart(columnIndex)._withRowStart(1)._commit(clearButton.style);
			}

			if (this.hideSearchButton == false) {
				let searchButton = this._createSearch();
				div.children.push(searchButton);
				columnIndex = isLeftPosition ? 1 : div.children.length;
				templateColumns[columnIndex - 1] = "auto";
				layouts.GridCSSBuilder._forCell()._withVerticalAlign(layouts.GridCellAlign.center)._withColumnStart(columnIndex)._withRowStart(1)._commit(searchButton.style);
			}

			layouts.GridCSSBuilder._forLayout()._withVerticalAlign(layouts.GridLayoutAlign.center)._withTemplateColumns(templateColumns)._withTemplateRows("1fr")._commit(div.style);
			//div
			let shape: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: classNames,
				attr: {
					role: "search"
				},
				styler: "root",
				style: {
					overflow: "hidden"
				},
				eventTargets: [
					ufc.EventTargetType.UICONTROL,
					ufc.EventTargetType.INPUT,
					ufc.EventTargetType.DROPPABLE
				],
				nodename: "searchinput",
				events: {
					focus: this._onFocus,
					mousedown: this._onMousedown,
					click: this._onClick,
					keydown: this._onKeyDown,
					blur: this._onBlur
				},
				children: [div]
			};

			cpr.ufc.ShapeUtil._setTooltipAttr(shape, { owner: this, title: this.tooltip });
			return shape;
		}

		/**
		 * 렌더링 중 포커스 가능한 엘리먼트가 변경되는 경우 포커스가 해제된다. 런타임에서 이벤트 전파를 방지하기 때문에 blur가 발생하지 않아 focused 정보가 갱신되지 않는다.
		 * 따라서 엘리먼트 변경이 일어나도 포커스 유지를 위해 렌더링 후 포커스를 복원해주는 작업이 필요하다.
		 * confirmEvent에서 focus 이벤트를 받지만 이전과 focused 값이 동일하여 동작하지 않는다.
		 * @returns 
		 */
		private _restoreFocus(): void {
			if (this._requestRestoreFocus === false) {
				return;
			}
			this._requestRestoreFocus = false;
			if (!this.focused || this.disposed) {
				return;
			}
			let activeElement = document.activeElement as HTMLElement;
			let rootNode = this._getRenderer().getRootNode();
			// 포커스 상태인데도 불구하고 포커스가 없는경우 강제 포커스
			if ((rootNode && !rootNode.contains(activeElement)) || activeElement?.getAttribute("tabindex") == null) {
				super._focusImmediately();
			}
		}

		private _createText(): cpr.ufc.ControlShape {
			let displayText = this._computeDisplayText();
			let textShape: cpr.ufc.ElementShape = {
				tag: "div",
				classNames: [],
				attr: {},
				style: {
					overflow: "hidden"
				},
				events: {},
				eventTargets: [],
				nodename: "text",
				children: displayText ? ufc.StyledString._asShape(displayText) : ["&nbsp;"]
			}
			layouts.FlexCSSBuilder._forCell()._withVerticalAlign(layouts.FlexCellAlign.center)._commit(textShape.style);
			if (!displayText && this.placeholder) {
				textShape.classNames.push(ufc.Classes.PLACEHOLDER);
				textShape.children = [this.placeholder];
			}
			let shape: cpr.ufc.ElementShape = {
				tag: "div",
				classNames: [ufc.Classes.TEXT, ufc.Classes.PREVENT_INPUT, ufc.Classes.UNSELECTABLE],
				attr: {
					tabindex: "0",
					role: "searchbox"
				},
				aria: "root",
				style: {},
				events: {},
				children: [textShape]
			}
			layouts.FlexCSSBuilder._forLayout()._commit(shape.style);
			if (this.readOnly) {
				ufc.ShapeUtil._setAriaState(shape, { enabled: true, readOnly: true })
			} else {
				ufc.ShapeUtil._setAriaDisabled(shape, this.enabled);
			}
			cpr.ufc.ShapeUtil._setAriaLabelAttr(shape.attr, this._getFieldLabel());
			cpr.ufc.ShapeUtil._setTooltipAttr(shape, { owner: this, title: this.tooltip });
			return shape;
		}

		private _createInput(): cpr.ufc.ControlShape {
			let input = super._createTextEditor();
			let value = this._getInputTagValue();
			let children = [];
			input.style["width"] = "100%";
			input.style["height"] = "100%";
			// 글자 영역이 0px가 되면 한글 입력 시 음절이 확정될 때마다 커서가 맨 앞으로 이동해
			// 입력 순서가 반전된다. 좌우 여백 2px씩을 제외하고 글자 영역 1px을 확보한다.
			input.style["minWidth"] = "5px";
			input.attr["tabindex"] = "0";
			input.attr["role"] = "searchbox";
			input.aria = "root";

			_assign(input.events, {
				blur: this._onInputBlur,
				input: this._onInput,
				drop: this._onDrop,
				dragstart: this._onDragstart,
				dragend: this._onDragend,
				change: this._onChange,
				keydown: this._onInputKeyDown
			});
			this._textEditorMaxLength.apply(input);
			cpr.ufc.ShapeUtil._setAriaLabelAttr(input.attr, this._getFieldLabel());
			cpr.ufc.ShapeUtil._setTooltipAttr(input, { owner: this, title: this.tooltip });
			cpr.ufc.ShapeUtil._setAriaState(input, { enabled: this.enabled, readOnly: this.readOnly });
			cpr.ufc.ShapeUtil._setInputElementState(input, { enabled: this.enabled, readOnly: this.readOnly });


			if (this.imeMode && this.imeMode != ImeMode.auto) {
				input.style['imeMode'] = this.imeMode;
			}

			if (this.inputMode && this.inputMode != InputMode.text) {
				input.attr["inputmode"] = this.inputMode;
			}

			if (this.autocomplete) {
				input.attr['autocomplete'] = this.autocomplete;
			}

			if (this._inputFilter) {
				this._inputFilter.wrap(input, value);
				let isAscii = /\[([\x00-\x7F]-[\x00-\x7F])+\]/g.test(this.inputFilter);
				if (isAscii) {
					input.style['imeMode'] = "disabled";
				}
			}

			input.value = value;
			children.push(input);
			if (this.placeholder) {
				let inputValue = this._getInputTagValue();
				let showPlaceholder = (this._isFocusedInputBox() == false || this.readOnly) && value.length == 0 && (inputValue == null || inputValue == "");
				children.push(this._createPlaceholder(this.placeholder, showPlaceholder));
			}

			let div: cpr.ufc.ControlShape = {
				tag: "div",
				style: {
					height: "100%",
					width: "100%",
					position: "relative",
					// input이 잘려 커서가 보이지 않는 것을 막기 위해 wrapper에도 같은 하한을 둔다.
					minWidth: "5px"
				},
				children: children
			}

			return div;
		}

		/**
		 * Search버튼 생성
		 */
		private _createSearch(): cpr.ufc.ControlShape {
			let button: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: [this.searchPosition === "right" ? "cl-right" : "cl-left"],
				styler: "search",
				attr: {
					role: "button",
					"aria-hidden": "true",
					"aria-label": this._getLabel(cpr.I18N.INSTANCE.message(core.PlatformTerms.SEARCH), this._getInternalProperty("searchLabelExp"))
				},
				style: {
					height: "100%"
				},
				nodename: "search",
				events: {}
			}

			cpr.ufc.ShapeUtil._setAriaDisabled(button, this.enabled);

			if (this.searchButtonImage != "") {
				button.style['background-image'] = _quoteAsCSSURL(this.searchButtonImage);
			}

			if (!this.hideSearchButton && this.buttonFocusable && this.enabled) {
				delete button.attr["aria-hidden"];
				button.events['keydown'] = this._onBtnSearchKeydown;
				button.attr['tabindex'] = "0";
			}

			if (this.readOnly) {
				button.events = {};
			}
			if (this.hideSearchButton) {
				button.style["display"] = "none";
			}

			return button;
		}


		/**
		 * Clear버튼 생성
		 */
		private _createClear(): cpr.ufc.ControlShape {
			let button: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: [],
				styler: "clear",
				attr: {
					role: "button",
					"aria-hidden": "true",
					"aria-label": this._getLabel(cpr.I18N.INSTANCE.message(core.PlatformTerms.CLEAR), this._getInternalProperty("clearLabelExp"))
				},
				style: {
					display: "block",
					height: "100%"
				},
				nodename: "clear",
				events: {}
			}
			cpr.ufc.ShapeUtil._setAriaDisabled(button, this.enabled && !this.readOnly);
			let isVisibleClearButton = this.hideClearButton == false && this._getInputTagValue().length > 0 && this.readOnly == false && this.enabled;
			if (isVisibleClearButton == false) {
				button.style["display"] = "none";
			}

			if (this.enabled) {
				if (this.buttonFocusable) {
					delete button.attr["aria-hidden"];
					button.events["keydown"] = this._onBtnClearKeydown
					button.attr['tabindex'] = "0";
				} else {
					button.attr['tabindex'] = "-1";
				}
			}

			if (this.clearButtonImage != "") {
				button.style['background-image'] = _quoteAsCSSURL(this.clearButtonImage);
			}

			return button;
		}

		/* private method  */
		private _isFocusedInputBox() {
			if (this.disposed) {
				return false;
			}
			let input = this._getRenderer().getNamedNode("text");
			try {
				return input === document.activeElement;
			} catch (e) {
				return false;
			}
		}

		/**
		 * IE10/11 issue page가 로드시 인풋에 placeholder, value에 ASCII 문자가 아닌 것(한 글,중 문,일본 어,유니코드)이 있으면 input 이벤트를 발생한다.
		 * https://connect.microsoft.com/IE/feedback/details/776510/oninput-event-fires-on-loading-the-page-when-input-value-is-non-ascii#details
		 */
		/* event start */
		private _onMousedown(e: MouseEvent): void {
			let target: HTMLElement = e.target as HTMLElement;
			if (e.defaultPrevented) {
				return;
			}
			let currentTarget = e.currentTarget as HTMLElement;
			// let domTraverser = ufc._traverserFromElement(target);
			// domTraverser = domTraverser.child("." + ufc.Classes.PLACEHOLDER);
			// if (domTraverser || target.classList.contains(ufc.Classes.PLACEHOLDER)) {
			// 	e.preventDefault();
			// 	this.focus();
			// } else if (target == e.currentTarget) {
			// 	e.preventDefault();
			// 	this.focus();
			// }
			// if (target.classList.contains("cl-searchinput-clear") || target.classList.contains("cl-searchinput-search")) {
			// 	//인풋에 포커스를 준다.
			// 	if (!this.focused) {
			// 		this._focusImmediately();
			// 	}
			// 	//인풋의 포커스가 빠지지않게 한다.
			// 	e.preventDefault();
			// }
			// 마우스의 타겟이 컨트롤의 기본 포커스 요소가 아니면 포커스를 설정하지 못하도록 막고 기본 포커스로 설정해야 한다.
			let focusableElement: Element = null; // 기본포커스 엘리먼트 focus() API참고.
			let domTraverser = ufc._traverseFromElement(currentTarget)._find('[tabindex]');
			if (domTraverser) {
				focusableElement = domTraverser._getElement();
			}
			if (focusableElement != target) {
				e.preventDefault();
				if (this.buttonFocusable) {
					if (this.focused == false) {
						super._focusImmediately();
					}
				} else {
					if (focusableElement != document.activeElement) {
						super._focusImmediately();
					}
				}
			}
		}

		private _onClick(e: events.CMouseEvent) {
			if (e.defaultPrevented) {
				return;
			}
			let target = <HTMLElement>e.target;
			if (target == null) {
				return;
			}
			if (target.classList.contains("cl-searchinput-clear")) {
				this._onClearButtonClick(e);
			}
			if (target.classList.contains("cl-searchinput-search")) {
				this._onSearch(e);
			}

		}

		private _onDragend(e: DragEvent) {
			let input = <HTMLInputElement>e.target;
			window.setTimeout(() => {
				if (!this._isDeleteByDrag) {
					return;
				}
				this._isDeleteByDrag = false;
				if (this.focused) {
					return;
				}
				if (this._checkValueChange(this._getValue(), input.value)) {
					this._setValue(input.value);
				}
			});
		}

		private _onDragstart(e: DragEvent) {
			this._isDeleteByDrag = true;
		}

		private _onDrop(e: DragEvent) {
			let transferData = e.dataTransfer.getData("text");
			if (!transferData) {
				e.preventDefault();
				return;
			}

			this._dropData = { text: this._inputFilter.filterText(transferData), isSelf: this.focused, isIE: _detectBrowser().name == "ie" };
		}


		private _onInput(e: KeyboardEvent): void {
			if (e.defaultPrevented) {
				return;
			}
			let input: HTMLInputElement = <HTMLInputElement>e.target;

			if (this._dropData && this._dropData.isSelf && this._dropData.isIE && input.selectionStart == input.selectionEnd) {
				//IE에서 자신에게 드래그하고 드롭 했을때 이벤트가 2번 발생한다.
				return;
			}
			let value = input.value;
			let inputType = e["inputType"];
			if ("insertFromDrop" == inputType || this._dropData) {

				if (this._checkValueChange(this._getValue(), value)) {
					this._setValue(value);
				}
				this._dropData = null;
			} else if ("deleteByDrag" == inputType || this._isDeleteByDrag) {

				if (this._checkValueChange(this._getValue(), value)) {
					this._setValue(value);
				}
				this._isDeleteByDrag = false;
			}

			this._updateClearButton(input.value);
		}

		private _onKeyDown(e: events.CKeyboardEvent) {
			if (e.defaultPrevented) {
				return;
			}
			let keyCode = e.keyCode;
			let target = e.target as HTMLElement;
			switch (keyCode) {
				case events.KeyCode.ENTER:
					//search이벤트 생성
					let searchEvent = new cpr.events.CEvent("search");
					searchEvent.nativeEvent = e;

					this.dispatchEvent(searchEvent);
					let isGrid = this.getParent() instanceof cpr.controls.Grid;
					if (isGrid) {
						e.preventDefault();
					}
					break;
				case events.KeyCode.ESC:
					if (target.classList.contains(ufc.Classes.TEXT) == false) {
						break;
					}
					this._clearTextByESC(e);
					//IE에서 esc입력 시 이전 값으로 되돌아가는 것을 방지
					e.preventDefault();
					break;
				case events.KeyCode.TAB:
					// 그리드에서 컨트롤 내에서 탭이동 제어를 위해 preventDefault()가 필요하여 키보드 이벤트 사용
					if (this.buttonFocusable == false) {
						break;
					}
					if (e._getMod2Key()) {
						this._focusPrevious(true);
						e.preventDefault();
					} else {
						this._focusNext(true);
						e.preventDefault();
					}
					break;
			}
		}

		/**
		 * 컨트롤에 포커스를 지정합니다.
		 */
		override focus(forward: boolean = true) {
			if (forward) {
				super.focus();
			} else {
				new TextInputFocusRing(this)._focusLast();
			}
		}

		override _convertGridPasteText(text: string): string {
			if (text == "") {
				return text;
			}
			let value = text;
			value = this._inputFilter.filterText(value);
			if (this.maxLength > -1) {
				let data = _getByteLength(this.lengthUnit as any, value, this.maxLength);
				if (data.byte >= this.maxLength) {
					let symbols = _getSymbols(value);
					value = symbols.slice(0, data.maxindex).join("");
				}
			}
			return value.length > 0 ? value : null;
		}

		public _getGridViewingText(): string {
			let text: string = this.text;
			if (typeof (text) == "string" && text.indexOf('\n') != -1) {
				text = text.replace('\n', '');
			}
			return text;
		}

		public _renderGridCellShape(grid: Grid, data: (string | ufc.StyledString), option: gridpart.renderer.IRenderOption): ufc.ControlShape {
			let searchInput: SearchInput = this as SearchInput;
			let templateColumns: string[] = [];
			let isLeftPosition = grid.viewingMode == ViewingMode.BUTTON && searchInput.searchPosition == "left" && searchInput.hideSearchButton == false;

			let classNames = ["cl-control", "cl-searchinput"];

			let searchInputShape: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: classNames,
				style: {
					overflow: "hidden"
					// display: "table", // grid에서 vertical-align 지원을 위해 추가 (180720 hyeran)
					// "table-layout": "fixed"
				},
				children: []
			};
			if (option.maxHeight >= 0) {
				searchInputShape.style["height"] = option.maxHeight + "px";
			}

			if (option.hidetext == false) {
				let controlGroup: cpr.ufc.ControlShape = {
					tag: "div",
					style: {
						width: "100%",
						height: "100%",
						"vertical-align": "inherit",
						"text-align": "inherit"
					},
					children: []
				}
				let textClassNames: string[] = [];
				if (searchInput.preventInput) {
					textClassNames.push(ufc.Classes.PREVENT_INPUT, ufc.Classes.UNSELECTABLE);
				}
				let textStyle: { classNames?: string[], style?: { [key: string]: string } } = { classNames: textClassNames, style: { "line-height": "normal" } };
				let text: string = searchInput.text;
				let inputText: string = text;
				if (typeof (inputText) == "string" && inputText.indexOf('\n') != -1) {
					inputText = inputText.replace('\n', '');
				}
				let showPlaceholder = searchInput.placeholder && (inputText == "" || (searchInput.displayExp && searchInput._computeDisplayingValue(inputText) == ""));
				if (showPlaceholder) {
					inputText = searchInput.placeholder;
					textStyle.classNames.push(ufc.Classes.PLACEHOLDER);
				}
				let columnIndex = isLeftPosition ? 2 : 1;
				let textWrap: ufc.ElementShape = gridpart.renderer.CellRendererFactory._getGridCellTextShape(inputText, option.maxHeight, textStyle);
				layouts.GridCSSBuilder._forCell()._withColumnStart(columnIndex)._withRowStart(1)._commit(textWrap.style);

				controlGroup.children = [textWrap];
				templateColumns[columnIndex - 1] = "minmax(min-content, 1fr)";

				if (grid.viewingMode == ViewingMode.BUTTON && searchInput.hideSearchButton == false) {
					let buttonShape: cpr.ufc.ControlShape = {
						tag: "div",
						classNames: ["cl-searchinput-search", searchInput.searchPosition === "right" ? "cl-right" : "cl-left"],
						attr: {
							role: "button"
						},
						style: {
							height: "100%"
						},
					}
					cpr.ufc.ShapeUtil._setAriaDisabled(buttonShape, searchInput.enabled);
					cpr.ufc.ShapeUtil._setAriaLabelAttr(buttonShape.attr, cpr.I18N.INSTANCE.message(core.PlatformTerms.SEARCH));
					gridpart.GridUtil._applyControlStyler(buttonShape, searchInput.style["search"], null);		//apply styler

					if (searchInput.searchButtonImage != "") {
						buttonShape.style['background-image'] = _quoteAsCSSURL(searchInput.searchButtonImage);
					}
					controlGroup.children.push(buttonShape);
					columnIndex = isLeftPosition ? 1 : controlGroup.children.length;
					templateColumns[columnIndex - 1] = "auto";
					layouts.GridCSSBuilder._forCell()._withColumnStart(columnIndex)._withVerticalAlign(layouts.GridCellAlign.center)._withRowStart(1)._commit(buttonShape.style);
				}

				layouts.GridCSSBuilder._forLayout()._withVerticalAlign(layouts.GridLayoutAlign.center)._withTemplateColumns(templateColumns)._withTemplateRows("1fr")._commit(controlGroup.style);
				searchInputShape.children = [controlGroup];
			}

			return searchInputShape;
		}

		/**
		 * @override 그리드에서 탭 이동시 이전과 다음에 따라 동작 할 수 있도록 제공
		 * @param forward 
		 */
		public override _focusImmediately(forward: boolean = true): void {
			let focusEntries = this._getFocusEntries() as TextInputFocusEntry[];
			if (forward) {
				focusEntries[0].focusImmediately();
			} else {
				focusEntries[focusEntries.length - 1].focusImmediately();
			}
		}


		private _onBtnSearchKeydown(e: events.CKeyboardEvent) {
			let keyCode = e.keyCode;

			if (keyCode == events.KeyCode.SPACE || keyCode == events.KeyCode.ENTER) {
				this._onSearch(e);
				e.preventDefault();
			}

		}

		private _onBtnClearKeydown(e: events.CKeyboardEvent) {
			if (this.readOnly) {
				return;
			}
			let keyCode = e.keyCode;

			if (keyCode == events.KeyCode.SPACE || keyCode == events.KeyCode.ENTER) {
				e.preventDefault();
				//clear이벤트 생성
				this._clear(true, e);
				if (this.disposed) {
					return;
				}
				if (this._getValue() != "") {
					return;
				}
				let input = this._getRenderer().getNamedNode("text") as HTMLInputElement
				input.value = "";
				let inputEvent = new events.CKeyboardEvent("input");
				inputEvent._setTarget(input);
				this.dispatchEvent(inputEvent);
				this._focusPrevious(true);
			}
		}

		private _onInputKeyDown(e: events.CKeyboardEvent) {
			if (this.readOnly) {
				return;
			}
			let input = <HTMLInputElement>e.target;
			let keyCode = e.keyCode;
			// value변경 
			// search이벤트는 root의 keydown이벤트에서 처리 
			if (keyCode == events.KeyCode.ENTER) {
				if (this._canUpdateValue()) {
					let newValue = input.value;
					let oldValue = this._getValue();
					if (this._checkValueChange(oldValue, newValue)) {
						this._setValue(newValue);
						if (this.disposed) {
							return;
						}
						if (this.autoSkip) {
							this.focusNext();
						}
					}
				}
			}
		}

		private _isHiddenClearButton() {
			let clearNode = this._getRenderer().getNamedNode("clear");
			if (!clearNode) {
				return true;
			}
			return clearNode.style.display == "none";
		}

		private _clearTextByESC(e: events.CKeyboardEvent) {
			if (this.readOnly || this._isHiddenClearButton()) {
				return;
			}
			let clearEvent = new cpr.events.CEvent("clear");
			clearEvent.nativeEvent = e;

			// dispatchEvent시 컨트롤 dispose를 체크함. dispose시 false
			let preventDefault = this.dispatchEvent(clearEvent);
			if (!preventDefault) {
				return;
			}
			if (this.preventInput) {
				this._setValue("");
			} else {
				let input = e.target as HTMLInputElement;
				input.value = "";
				this._updateClearButton(input.value);
				input.setSelectionRange(0, 0);

				let inputEvent = new events.CKeyboardEvent("input");
				inputEvent.nativeEvent = e;
				this.dispatchEvent(inputEvent);
			}
		}

		private _onClearButtonClick(e: events.CMouseEvent) {
			if (this.readOnly) {
				return;
			}
			let clearEvent = new cpr.events.CEvent("clear");
			clearEvent.nativeEvent = e;

			// dispatchEvent시 컨트롤 dispose를 체크함. dispose시 false
			let preventDefault = this.dispatchEvent(clearEvent);
			if (!preventDefault) {
				return;
			}
			if (this.focused == false || this.preventInput) { // 컨트롤에 포커스가 없을때 클릭(mousedown에서 preventDefault)
				if (document.activeElement === e.target) {
					super._focusImmediately();
				}
				this._setValue("");
			} else {
				let input = <HTMLInputElement>this._getRenderer().getNamedNode("text");
				if (document.activeElement !== input) {//buttonFocusable 일때 클리어 버튼에 포커스 있는 경우
					this._setValue("");
					super._focusImmediately();
				} else {
					input.value = "";
					this._updateClearButton(input.value);
					input.setSelectionRange(0, 0);
				}

				let inputEvent = new events.CKeyboardEvent("input");
				inputEvent._setTarget(input);
				inputEvent.nativeEvent = e;
				this.dispatchEvent(inputEvent);
			}
		}

		/**
		 * search시 발생
		 * @param e 
		 */
		private _onSearch(e?: events.CEvent): void {
			if (this._canUpdateValue() && this.preventInput == false) {
				let input = <HTMLInputElement>this._getRenderer().getNamedNode("text");

				// displayExp가 적용된 input.value로 값을 비교하여 항상 값이 변경되는 문제가 발생하여 포커스 여부 체크 추가
				let newValue = this._isFocusedInputBox() ? input.value : this._getValue();
				if (this._checkValueChange(this._getValue(), newValue)) {
					this._setValue(newValue);
				}
			}

			//search이벤트 생성
			let searchEvent = new cpr.events.CEvent("search");

			if (e) {
				searchEvent.nativeEvent = e;
			}
			this.dispatchEvent(searchEvent);
		}

		private _onFocus(e: FocusEvent) {
			if (this.preventInput) {
				return;
			}
			let input = <HTMLInputElement>this._getRenderer().getNamedNode("text");
			if (!input) {
				return;
			}
			let isGridContains = this.getParent() instanceof cpr.controls.Grid;
			let displayText = this._getDisplayText();
			if (this.displayExp) {
				let isIE = _detectBrowser().name === "ie";
				let start = isIE ? input.selectionStart : 0;
				let end = isIE ? input.selectionEnd : 0;
				let valueChanged = false;
				if (isGridContains == false) {
					if (this.focused && this.readOnly == false && input.value != displayText) {
						input.value = displayText;
						valueChanged = true;
					}
				} else {
					// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/10554
					// displayExp가 없는 경우 undo시 input value가 변경되지 않도록 함.
					if (input.value != displayText) {
						input.value = displayText;
						valueChanged = true;
					}
				}

				if (valueChanged && isIE && document.activeElement === input) {
					input.setSelectionRange(start, end);
				}
			}
			this._setInputFocus(input);
		}

		private _setInputFocus(input: HTMLInputElement) {
			// 셀렉션 및 placeholder 제어는 인풋박스에 포커스있는 경우에만 체크
			if (document.activeElement !== input) {
				return;
			}
			if (this.readOnly == false) {
				this._hidePlaceholder();
			}

			let isGrid = this.getParent() instanceof cpr.controls.Grid;
			let preventAutoSelect = isGrid && this.autoSelect == false && this._defaultSelection.state != SelectionState.API;
			if (preventAutoSelect) {
				this._defaultSelection.state = SelectionState.NONE;
			}

			let selectionAction = () => {
				if (document.activeElement !== input) {
					return;
				}

				if (!preventAutoSelect) {
					this._checkAutoSelect(input, this.autoSelect);
				}

				this._defaultSelection.state = SelectionState.NONE;
			};

			let isEdgeLegacy = _detectBrowser().name === "edge";

			if (isEdgeLegacy) {
				cpr.core.DeferredUpdateManager.INSTANCE.asyncExec(selectionAction);
			} else {
				selectionAction();
			}
		}

		private _onBlur(e: FocusEvent): void {
			if (this.displayExp && this.buttonFocusable) {
				this.redraw();
			}
		}

		private _onInputBlur(e: FocusEvent) {
			let input: HTMLInputElement = e.target as HTMLInputElement;
			if (this._defaultSelection) {
				this._defaultSelection.start = input.selectionStart;
				this._defaultSelection.end = input.selectionEnd;
			}

			if (this._canUpdateValue()) {
				let newValue = input.value;
				if (this._checkValueChange(this._getValue(), newValue)) {
					this._setValue(newValue);
				}
				if (this.disposed) {
					return;
				}
				this._showPlaceholder();
			}
			this.redraw(); // displayExp 적용
		}

		private _onChange(e: events.CUIEvent) {
			let input = e.target as HTMLInputElement;
			if (input.value.length > 0) {
				this._hidePlaceholder();
			}
		}
		/* event end */

		private _clear(emitEvent: boolean, e: Event = null) {
			if (emitEvent) {
				//clear이벤트 생성
				let clearEvent = new cpr.events.CEvent("clear");
				if (e) {
					clearEvent.nativeEvent = e;
				}
				let preventDefault = this.dispatchEvent(clearEvent);
				if (!preventDefault) {
					return;
				}
			}
			this._setValue("");
		}

		protected _getActiveElement() {
			if (this.focused == false) {
				return super._getActiveElement();
			}
			let focusElement = document.activeElement;
			let clearBtn = this._getRenderer().getNamedNode("clear");
			let searchBtn = this._getRenderer().getNamedNode("search");
			if (focusElement === clearBtn || focusElement === searchBtn) {
				let input = this._getRenderer().getNamedNode("text");
				focusElement = input;
			}
			return focusElement;
		}

		/**
		 * 인풋의 값에 따라 클리어 버튼을 표시하거나 숨깁니다.
		 */
		private _updateClearButton(text: string) {
			// 항상 숨김 상태일 경우 return
			if (this.hideClearButton) {
				return;
			}
			let isEmptyText = text.length == 0;
			if (isEmptyText) {
				this._getRenderer().updateStyle("clear", { display: "none" }, true);
			} else {
				this._getRenderer().updateStyle("clear", { display: "block" }, true);
			}
		}

		override _getFocusEntries(): FocusEntry[] {
			let renderer = this._getRenderer();
			let focusEntries = super._getFocusEntries();
			if (this.buttonFocusable == false) {
				return focusEntries;
			}
			let clearBtn = renderer.getNamedNode("clear");
			let searchBtn = renderer.getNamedNode("search");

			if (clearBtn && !this._isHiddenClearButton()) focusEntries.push(this._clearBtnFocusEntry);
			if (searchBtn) {
				if (this.searchPosition == "left") {
					focusEntries.splice(0, 0, this._searchBtnFocusEntry);
				} else {
					focusEntries.push(this._searchBtnFocusEntry);
				}
			}
			return focusEntries;
		}

		override _getActiveFocusEntry(): FocusEntry {
			let activeElement = document.activeElement as HTMLElement;
			if (!activeElement) {
				return null;
			}
			let classList = activeElement.classList;
			if (classList.contains(SearchInputClassName.clear)) {
				return this._clearBtnFocusEntry;
			} else if (classList.contains(SearchInputClassName.search)) {
				return this._searchBtnFocusEntry;
			} else {
				return super._getActiveFocusEntry();
			}
		}


	}


}