
/// <reference path="./UIControl.ts" />
/// <reference path="./TextEditor.ts" />

namespace cpr.controls {
	/**
	 * textarea
	 * 여러 줄의 텍스트를 입력 할 수 있는 컨트롤.
	 * 
	 * @firesgroup mouse
	 * @firesgroup contextmenu
	 * @firesgroup bindcontext
	 * @firesgroup keyboard
	 * @firesgroup focus
	 * @firesgroup drop
	 * @firesgroup input
	 * 
	 * 
	 * @fires cpr.events.CValueChangeEvent#before-value-change 변경된 value가 저장되기 전에 발생하는 이벤트.
	 * 		다음 이벤트로 value-change가 발생합니다.
	 * 		<pre>oldValue: {string} 이전 값</pre>
	 * 		<pre>newValue: {string} 변경될 값</pre>
	 * 
	 * @fires cpr.events.CValueChangeEvent#value-change 변경된 value가 저장된 후에 발생하는 이벤트.
	 * 		<pre>oldValue: {string} 이전 값</pre>
	 * 		<pre>newValue: {string} 변경된 값</pre>
	 */
	export class TextArea extends TextEditor {
		private static readonly _AVAILABLE_PROP: string[] = [
			"placeholder", "maxLength", "autoSelect", "lengthUnit", "imeMode", "autoSkip",
			"spellCheck"
		];

		private _maxlength: number = -1;
		private _autoselect: boolean = false;
		private _lengthunit: TextLengthUnit = 0; /* char, utf8, ascii */
		private _imemode: ImeMode; /* active, inactive, disabled */
		private _autoskip: boolean = false;
		private _scroll: internal.ControlScrollPane | internal.NativeScrollPane;
		private _spellCheck: boolean = true;
		private _dropData: { text: string, isSelf: boolean, isIE: boolean } = null;
		private _isDeleteByDrag: boolean = false;
		private _textEditorMaxLength: TextEditorMaxLength;

		/**
		 * 텍스트에리어를 생성합니다.
		 * @param id 텍스트에리어의 id
		 */
		constructor(id?: string) {
			super(id);
			this._imemode = ImeMode.auto;
			this._defaultSelection.state = SelectionState.NONE;
			this._addBindableProperty("placeholder", "").withSetterValidatorWithType(false, "string");
			if (this._isUseCustomScroll()) {
				this._scroll = new internal.ControlScrollPane(this, "text");
			} else {
				this._scroll = new internal.NativeScrollPane(this, "text");
			}
			this._setTextEditorType("textarea");
			this._textEditorMaxLength = new TextEditorMaxLength(this, {
				onMaxlength: () => {
					if (this.autoSkip && this.focused) {
						this.focusNext();
					}
				}
			});
			// control initializing
			this._initControl();
		}

		protected _isConfigurableProperty(propName: string): boolean {
			if (TextArea._AVAILABLE_PROP.indexOf(propName) != -1) {
				return true;
			}
			return super._isConfigurableProperty(propName);
		}

		/* Shape */
		protected _getStylerSpec(): UIControlStylerSpec {
			return {
				root: { baseClass: "cl-textarea" }
			};
		}

		/**
		 * 자동 크기 지원 타입을 얻습니다.
		 * 만일 both를 리턴했다면, css height, width 속성에 auto를 사용할 수 있음을 나타냅니다.
		 */
		override _getAutoSizeAvailability(): layouts.AutoSizeType {
			return layouts.AutoSizeType.both;
		}

		/* control's type overriding */
		override _getType(): ControlType {
			return ControlType.TEXTAREA;
		}

		/**
		 * @param name 
		 * @param oldValue 
		 * @param newValue 
		 */
		_valueDidChange(name: string, oldValue: any, newValue: any) {
			super._valueDidChange(name, oldValue, newValue);
			switch (name) {
				case "placeholder": {
					this.redraw();
					break;
				}
			}
		}

		public override _convertGridPasteText(text: string): string {
			if (text == "") {
				return text;
			}
			let value = text;
			if (this.maxLength > -1) {
				let data = _getByteLength(this.lengthUnit as any, value, this.maxLength);
				if (data.byte >= this.maxLength) {
					let symbols = _getSymbols(value);
					value = symbols.slice(0, data.maxindex).join("");
				}
			}
			return value.length == 0 ? null : value;
		}

		public _getGridViewingText(): string {
			return this.text;
		}

		public _renderGridCellShape(grid: Grid, data: (string | ufc.StyledString), option: gridpart.renderer.IRenderOption): ufc.ControlShape {
			let textarea: TextArea = this as TextArea;

			let textareaShape: ufc.ControlShape = {
				tag: "div",
				classNames: ["cl-control", "cl-textarea"],
				style: {
					overflow: "hidden"
					// height: option.maxHeight + "px"
				},
				children: []
			};
			if (option.maxHeight >= 0) {
				textareaShape.style["height"] = option.maxHeight + "px";
			}

			if (option.hidetext == false) {
				let classNames: string[] = [ufc.Classes.TEXT];
				let text: string = textarea.value;
				if (text == "" && textarea.placeholder) {
					text = textarea.placeholder;
					classNames.push(ufc.Classes.PLACEHOLDER);
				}
				let textShape: ufc.ElementShape = {
					tag: "div",
					classNames: classNames,
					style: {
						resize: "none",//chrome 상의 resize 고정
						background: "transparent",
						margin: "0"
					},
					children: [text]
				};
				if (option.height === -1) {
					textShape.style["overflow"] = "visible";
				}

				textareaShape.children = [textShape];
			}

			return textareaShape;
		}

		/* property */
		/**
		 * 설명 또는 예상된 값에 대한 문구(힌트)를 반환합니다.
		 * @return 설명 또는 예상된 값에 대한 문구.
		 */
		get placeholder(): string {
			return this._bindables.get("placeholder");
		}

		/**
		 * 설명 또는 예상된 값에 대한 문구(힌트)를 설정합니다.
		 * @param placeholder 설명 또는 예상된 값에 대한 문구.
		 */
		set placeholder(placeholder: string) {
			this._bindables.set("placeholder", placeholder);
		}

		/**
		 * 입력이 가능한 최대 문자 수를 반환합니다..
		 * @return 입력이 가능한 최대 문자 수.
		 */
		get maxLength(): number {
			return this._maxlength;
		}

		/**
		 * 입력이 가능한 최대 문자 수를 설정합니다.
		 * 관련 속성 : [lengthUnit] lengthUnit 속성 기준으로 설정됩니다.
		 * @param maxlength 입력이 가능한 최대 문자 수.
		 */
		set maxLength(maxlength: number) {
			if (typeof maxlength != "number") {
				return;
			}
			this._maxlength = maxlength;
			this.redraw();
		}

		/**
		 * 포커스 될 시 편집 영역의 데이터 전체 선택 여부를 반환합니다.
		 * @return 포커스 될 시 데이터 전체 선택 여부.
		 */
		get autoSelect(): boolean {
			return this._autoselect;
		}

		/**
		 * 포커스 될 시 편집 영역의 데이터 전체 선택 여부를 설정합니다.
		 * @param autoselect 포커스 될 시 데이터 전체 선택 여부
		 */
		set autoSelect(autoselect: boolean) {
			this._autoselect = autoselect;
			if (autoselect === true) {
				this._defaultSelection.state = SelectionState.NONE;
			}
			this.redraw();
		}

		/**
		 * 편집 영역의 전체 문자열 길이의 단위를 반환합니다.
		 * @return 전체 문자열 길이의 단위.
		 */
		get lengthUnit(): string {
			return TextLengthUnit[this._lengthunit];
		}

		/**
		 * 편집 영역의 전체 문자열 길이의 단위를 설정합니다.
		 * [char] : 문자의 길이.
		 * [utf8] : utf8 기준의 문자 byte size.
		 * [ascii] : ascii 기준의 문자 byte size.
		 * @param unit 전체 문자열 길이의 단위.
		 */
		set lengthUnit(unit: string) {
			if (typeof unit == "string") {
				unit = unit.toLowerCase();
			}
			let lengthUnit = TextLengthUnit[unit];
			if (typeof lengthUnit != "number") {
				return;
			}
			this._lengthunit = lengthUnit;
			this.redraw();
		}

		/**
		 * Textarea의 입력된 값(문자열)의 길이를 반환합니다.
		 * @return 입력된 값의 길이.
		 */
		get length(): number {
			let length = 0;
			if (!this.lengthUnit)
				return length;

			let textarealengthunit: TextLengthUnit = TextLengthUnit[this.lengthUnit];
			switch (textarealengthunit) {
				case TextLengthUnit.utf8:
				case TextLengthUnit.ascii:
				case TextLengthUnit.char: {
					length = _getByteLength(this.lengthUnit as any, this.displayingText).byte;
					break;
				}

			}
			return length;
		}

		/**
		 * IE, FireFox 브라우저에서 한영 변환 설정을 반환합니다.
		 * @return 한영 변환 설정
		 */
		get imeMode(): ImeMode {
			return this._imemode;
		}

		/**
		 * IE, FireFox 브라우저에서 키보드 IME에 대한 한영 변환 설정. CSS의 ime-mode속성을 사용합니다. 지원하는 브라우저 버전에 따라 지원이 안될 수 있으니 MDN문서를 확인하시기 바랍니다. <br>
		 * [auto] : 현재 inputbox의 ime 설정에 대해 아무것도 하지않음.
		 * [active] : 기본 값으로 한글을 입력받습니다. <br>
		 * [inactive] : 기본 값으로 영문을 입력받습니다.<br>
		 * [disabled] : 영문만을 입력받습니다.
		 * @param imemode 
		 */
		set imeMode(imemode: ImeMode) {
			if (typeof imemode == "string") {
				imemode = imemode.toLowerCase() as any;
			}
			if (!ImeMode[imemode]) {
				imemode = null;
			}
			if (this._imemode == imemode) {
				return;
			}
			this._imemode = imemode;
			this.redraw();
		}

		/**
		 * 입력된 문자열의 길이가 maxLength 도달했을 경우 다음 컨트롤로 포커스 이동 여부를 반환 합니다.
		 * @return 다음 컨트롤로 포커스 이동 여부.
		 */
		get autoSkip() {
			return this._autoskip;
		}

		/**
		 * 입력된 문자열의 길이가 maxLength 도달했을 경우 다음 컨트롤로 포커스 이동 여부를 설정합니다.
		 * 이 기능은 키보드의 영문,숫자,기호에 한하여 정상 동작합니다.
		 * 관련 속성 : [maxLength] maxLength 속성이 존재 할 시 해당 속성이 동작합니다.
		 * @param skip 다음 컨트롤로 포커스 이동 여부.
		 */
		set autoSkip(skip: boolean) {
			this._autoskip = skip;
			this.redraw();
		}

		/**
		 * 영문 철자법과 문법 검사하는 기능에 대한 설정값을 반환합니다.
		 */
		get spellCheck() {
			return this._spellCheck;
		}

		/**
		 * 브라우저에서 영문 철자법과 문법을 검사하는 기능을 설정합니다.
		 */
		set spellCheck(check: boolean) {
			this._spellCheck = check;
		}

		/* shpae */
		public _createShape(): cpr.ufc.ControlShape {
			let value = this._getInputTagValue();
			let children = [];
			if (this.placeholder) {
				children.push(this._createPlaceholder(this.placeholder, (this.focused == false || this.readOnly) && value.length == 0));
			}

			let textarea = this._createTextArea(value);
			children.push(textarea);

			let wrapper: ufc.ControlShape = {
				tag: "div",
				classNames: ["cl-textarea-wrap"],
				style: {
					height: "100%",
					position: "relative"
				},
				children: children

			}
			let shape: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: [],
				attr: {
				},
				styler: "root",
				style: {
					overflow: "hidden"
				},
				events: {
					focus: this._onFocus,
					mousedown: this._onMousedown
				},
				eventTargets: [
					ufc.EventTargetType.UICONTROL,
					ufc.EventTargetType.INPUT,
					ufc.EventTargetType.DROPPABLE
				],
				children: [wrapper]
			}

			cpr.ufc.ShapeUtil._setTooltipAttr(shape, { owner: this, title: this.tooltip });

			if (this._isUseCustomScroll()) {
				(this._scroll as internal.ControlScrollPane).createScrollbar(wrapper.children, textarea, wrapper.children.length, wrapper);
			} else {
				(this._scroll as internal.NativeScrollPane).createScrollbar(wrapper, null, textarea, -1);
			}

			return shape;
		}

		private _createTextArea(value: string) {
			let textarea = this._createTextEditor();

			textarea.attr["spellcheck"] = this.spellCheck ? "true" : "false";
			textarea.attr["tabindex"] = "0";
			_assign(textarea.events, {
				blur: this._onBlur,
				input: this._onInput,
				dragstart: this._onDragstart,
				drop: this._onDrop,
				dragend: this._onDragend
			});
			this._textEditorMaxLength.apply(textarea);
			cpr.ufc.ShapeUtil._setAriaState(textarea, { enabled: this.enabled, readOnly: this.readOnly });
			cpr.ufc.ShapeUtil._setInputElementState(textarea, { enabled: this.enabled, readOnly: this.readOnly });
			textarea.value = value;

			if (this.imeMode) {
				textarea.style['imeMode'] = this.imeMode;
			}
			return textarea;
		}

		protected _createPlaceholder(placeholder: string, show: boolean) {
			let shape: ufc.ControlShape = {
				tag: "div",
				classNames: [ufc.Classes.TEXT, ufc.Classes.PLACEHOLDER, ufc.Classes.UNSELECTABLE],
				style: {
					left: "0px",
					top: "0px",
					right: "0px",
					bottom: "0px",
					position: "absolute",
					"overflow-x": "hidden",
					"overflow-y": "auto",
					"word-break": "break-all",
					display: show ? "block" : "none",
					padding: "inherit",
					cursor: "text",
					"pointer-events": "none"
				},
				attr: {},
				children: [placeholder],
				nodename: "placeholder"
			}
			if (this.enabled == false) {
				shape.style["cursor"] = "default";
			}
			return shape;
		}

		protected _showPlaceholder() {
			if (this._getDisplayText().length > 0) {
				return;
			}
			let elem = this._getPlaceholderNode();
			if (elem) {
				this._getRenderer().updateStyle("placeholder", { display: "block" }, true);
			}
		}

		protected _getPlaceholderNode() {
			let rootNode = this._getRenderer().getRootNode();
			let domTraverser = ufc._traverseFromElement(rootNode);
			domTraverser = domTraverser._child("." + ufc.Classes.PLACEHOLDER);
			return domTraverser ? domTraverser._getElement() : null;
		}

		public override _getActiveFocusEntry(): FocusEntry {
			let activeFocusEntry = super._getActiveFocusEntry();
			return activeFocusEntry ?? this._getFocusEntries()[0];
		}

		/* private method */

		/* event start */

		private _onMousedown(e: MouseEvent): void {
			let target: HTMLElement = e.target as HTMLElement;
			if (e.defaultPrevented) {
				return;
			}
			if (target.classList.contains(ufc.Classes.PLACEHOLDER)) {
				e.preventDefault();
				this._focusImmediately();

			} else if (target == e.currentTarget) {
				e.preventDefault();
				this._focusImmediately();

			}
		}

		/**
		 * 이벤트 순서 textEditorMaxLength._oninput -> inputbox._onInput -> 사용자 이벤트
		 * @param e 
		 */
		private _onInput(e: events.CUIEvent): void {
			let textarea: HTMLTextAreaElement = <HTMLTextAreaElement>e.target;

			let inputType = e.inputType;
			if ("insertFromDrop" == inputType || this._dropData) {
				let newValue = textarea.value;
				if (this._checkValueChange(this._getValue(), newValue)) {
					this._setValue(newValue);
				}

				this._dropData = null;
			} else if ("deleteByDrag" == inputType || this._isDeleteByDrag) {
				let newValue = textarea.value;
				if (this._checkValueChange(this._getValue(), newValue)) {
					this._setValue(newValue);
				}

				this._isDeleteByDrag = false;
			}
		}

		private _onDragend(e: DragEvent) {
			let input = <HTMLInputElement>e.target;
			window.setTimeout(() => {
				if (!this._isDeleteByDrag) {
					return;
				}
				this._isDeleteByDrag = false;
				if (this.focused) {
					return;
				}
				if (this._checkValueChange(this._getValue(), input.value)) {
					this._setValue(input.value);
				}
			});
		}

		private _onDragstart(e: DragEvent) {
			this._isDeleteByDrag = true;
		}

		/**
		 * 이벤트 순서 textEditorMaxLength._ondrop -> input._ondrop-> 사용자이벤트
		 * @param e 
		 * @returns 
		 */
		private _onDrop(e: DragEvent) {
			let transferData = e.dataTransfer.getData("text");
			if (!transferData) {
				e.preventDefault();
				return;
			}

			this._dropData = { text: transferData, isSelf: this.focused, isIE: _detectBrowser().name == "ie" };
		}

		private _onFocus(e: FocusEvent): void {
			let textarea: HTMLTextAreaElement = <HTMLTextAreaElement>this._getRenderer().getNamedNode("text");
			if (!textarea) {
				return;
			}
			this._setInputFocus(textarea);
		}

		private _setInputFocus(textarea: HTMLTextAreaElement) {
			// 셀렉션 및 placeholder 제어는 텍스트에리어 포커스있는 경우에만 체크
			if (document.activeElement !== textarea) {
				return;
			}
			if (this.readOnly == false) {
				this._hidePlaceholder();
			}
			let isGrid = this.getParent() instanceof cpr.controls.Grid;
			let preventAutoSelect = isGrid && this.autoSelect == false && this._defaultSelection.state != SelectionState.API;
			if (preventAutoSelect) {
				this._defaultSelection.state = SelectionState.NONE;
			}

			let selectionAction = () => {
				if (document.activeElement !== textarea) {
					return;
				}

				if (!preventAutoSelect) {
					this._checkAutoSelect(textarea, this.autoSelect);
				}

				this._defaultSelection.state = SelectionState.NONE;
			};

			let isEdgeLegacy = _detectBrowser().name === "edge";

			if (isEdgeLegacy) {
				cpr.core.DeferredUpdateManager.INSTANCE.asyncExec(selectionAction);
			} else {
				selectionAction();
			}
		}

		private _onBlur(e: FocusEvent) {
			let input: HTMLInputElement = e.target as HTMLInputElement;
			if (this._defaultSelection) {
				this._defaultSelection.start = input.selectionStart;
				this._defaultSelection.end = input.selectionEnd;
			}
			let newValue = input.value;
			if (this._checkValueChange(this._getValue(), newValue)) {
				this._setValue(newValue);
			}
			if (this.disposed) {
				return;
			}
			this._showPlaceholder();
		}


		/* evnet end */

		/* public method */
		public dispose(): void {
			if (this._scroll) {
				this._scroll.dispose();
				this._scroll = null;
			}
			super.dispose();
		}
		/**
		 * 스크롤을 마지막 아래로 이동합니다.
		 */
		public scrollToBottom(): void {
			cpr.core.DeferredUpdateManager.INSTANCE.asyncExec(() => {
				if (this.disposed) {
					return;
				}
				let textarea = <HTMLTextAreaElement>this._getRenderer().getNamedNode("text");
				if (textarea) {
					textarea.scrollTop = textarea.scrollHeight;
				}
			});
		}

		/**
		 * 스크롤을 처음으로 이동합니다.
		 */
		public scrollToTop(): void {
			cpr.core.DeferredUpdateManager.INSTANCE.asyncExec(() => {
				if (this.disposed) {
					return;
				}
				let textarea = <HTMLTextAreaElement>this._getRenderer().getNamedNode("text");
				if (textarea && textarea.scrollTop != 0) {
					textarea.scrollTop = 0;
				}
			});
		}

	} //textarea
}