namespace cpr.controls {

	/**
	 * @private
	 */
	export interface IDropDownList {
		hoveredIndex: number;
		_isOpened: boolean;
		showCheckbox: boolean;
		_addEventListener(type: string, func: Function);
		_getListElementId(): string;
		_getItemElementId(index: number): string;
		_checkWindowResize(): void;
		clearFilter(): void;
		_getListboxNode(): HTMLElement;
		init(): void;
		_invalidate(): void;
		filter(filter: string): void;
		getItems(): any[];
		setItems(items: any[]): void
		_createShape(): cpr.ufc.ElementShape;
		keyNavigation(keyCode: number, index: number, e: KeyboardEvent): void;
		hover(index: number): void;
		/**
		 * 아이템을 가지고 호버되는 인덱스를 반환합니다.
		 * 중복 value를 허용하는 경우 사용해야 합니다.
		 * @param item 
		 */
		getHoverIndex(item: Item): number;
		dispose(): void;
	}

	/**
	 * @private
	 */
	export interface ICombobox extends EnableUIControl {
		fixedListWidth: boolean;
		showIcon: boolean;
		maxVisibleItems: number;
		selectionViewIndex?: number;
		delimiter: string;
	}

	/**
	 * 리스트박스
	 * @private
	 */
	export abstract class AbstractDropDownList<ItemType extends Item> implements internal.IVirtualScrollPane, IDropDownList {

		private _viewHeight: number = 0;
		private _contentHeight: number = 0;
		private _maxContentTop: number = 0;
		private _rowHeight: number = 30;

		private _styleMaxHeight: number;
		private _ns: string;

		private _hoveredIndex: number = 0;// 호버되는 아이템 번호
		public styler: { list: string, item: string } = { list: "list", item: "item" };

		protected _filterLabel: string;

		private _uicontrol: ICombobox;
		private _vscrollbar: internal.IVirtualVScrollbar;

		private _startRowIndex: number = 0;
		private _endRowIndex: number = 0;

		protected _cacheItems: ItemType[] = null;
		protected _cacheItemMaxWidth: number = null;
		protected _items: ItemType[] = [];

		private _vScrollTop: number = 0;

		private _showCheckbox: boolean = false;
		private _beforeMaxVisibleItems: number = 0;

		private _requestScroll: boolean = true;// open되어 있는 상태에서 리스트박스 필터링시 스크롤 하기 위한 플래그

		private _listeners: { [key: string]: Function[] } = {};
		private _initVScroll: boolean = false;// 리스트 높이가 동적으로 변경될때 스크롤을 숨긴 후 표시하기 위한 플래그

		public _isOpened: boolean = false;
		private _openTimer: utils.Timer;

		/**
		 * 
		 * @param uicontrol 부모의 컨트롤
		 * @param ns uicontrol의 nodename
		 * @param binder uicontrol의 ListDataBinder
		 */
		constructor(uicontrol: ICombobox, ns: string) {
			this._uicontrol = uicontrol;
			this._ns = ns;
			if (this._uicontrol._isUseCustomScroll()) {
				this._vscrollbar = new internal.VirtualVScrollbar(this);
			} else {
				this._vscrollbar = new internal.NativeVScrollbar(this);
			}
			this._openTimer = utils.Timer.create("dropdownlist-open", () => {
				this._isOpened = true;
			})
		}

		protected _getUIControl() {
			return this._uicontrol;
		}

		protected _isDisposed() {
			return this._uicontrol == null;
		}

		get namespace() {
			return this._ns;
		}
		set namespace(ns: string) {
			this._ns = ns;
		}

		protected _isFixedListWidth(): boolean {
			return this._uicontrol.fixedListWidth;
		}

		protected _isShowIcon(): boolean {
			return this._uicontrol.showIcon;
		}

		get showCheckbox() {
			return this._showCheckbox;
		}

		set showCheckbox(show: boolean) {
			this._showCheckbox = show;
		}

		protected _getMaxVisibleItems(): number {
			return this._uicontrol.maxVisibleItems;
		}

		protected _getSelectionViewIndex(): number {
			return this._uicontrol.selectionViewIndex ?? 0;
		}

		public _setNameSpace(ns: string) {
			this._ns = ns;
		}

		public _getListElementId() {
			return ufc.NodeUUIDMapper.INSTANCE._createPartialUUID(this._getUIControl(), "lb");
		}

		public _getItemElementId(index: number) {
			return ufc.NodeUUIDMapper.INSTANCE._createPartialUUID(this._getUIControl(), "i" + index);
		}

		public get hoveredIndex() {
			return this._hoveredIndex;
		}

		public getHoverIndex(item: Item, defaultReturnValue: number = -1): number {
			let result = defaultReturnValue;
			if (item == null) {
				return result;
			}
			let items = this.getItems();
			items.some((each: Item, idx: number) => {
				if (each._equalsUUID(item)) {
					result = idx;
					return true;
				}
				return false;
			})

			return result;
		}

		public hover(index: number, focus: boolean = true) {
			this._hoveredIndex = index;
			if (focus) {
				this._requestScroll = true;
				this._vScrollTop = 0;
			}
		}

		public filter(filter: string) {
			this._filterLabel = filter;
			this._cacheItems = null;
			this._cacheItemMaxWidth = null;
		}

		public init() {
			this._vScrollTop = 0;
			this._hoveredIndex = 0;
			this._requestScroll = true;
			this._initVScroll = false;
			this._isOpened = false;
			this._openTimer.cancel();
		}

		public dispose() {
			this._listeners = null;
			this._uicontrol = null;
			this._vscrollbar = null;
			this._cacheItems = null;
			this._cacheItemMaxWidth = null;
			this._items = null;
			if (this._openTimer) {
				this._openTimer.dispose();
				this._openTimer = null;
			}
		}

		public clearFilter() {
			this._filterLabel = null;
			this._cacheItems = null;
			this._cacheItemMaxWidth = null;
		}

		public setItems(items: ItemType[]) {
			this._items = items;
			this._cacheItems = null;
			this._cacheItemMaxWidth = null;
		}

		public getItems(): ItemType[] {
			if (this._cacheItems) {
				return this._cacheItems;
			}

			if (this._filterLabel) {
				this._cacheItems = this._filterItems();
			} else {
				this._cacheItems = this._items;
			}

			return this._cacheItems;
		}

		public _invalidate() {
			this._cacheItems = null;
			this._requestScroll = true;
			this._vScrollTop = 0;
		}

		protected abstract _computeItemDisplayLabel(item: ItemType): ufc.StyledString | string;
		protected abstract _getItemEnable(item: ItemType): boolean;

		protected _filterItems() {
			let result = this._items.filter((item: ItemType) => {
				// 대소문자 관계 없이 검색 할 수 있도록 수정 17.11.22 배소영
				let label: string = ufc.StyledString._asString(this._computeItemDisplayLabel(item)).toLowerCase();
				if (label.indexOf(this._filterLabel.toLowerCase()) > -1) {
					return true;
				}
				return false;
			});
			return result;
		}
		/**
		 * 이벤트를 전달 합니다.
		 * @param e 이벤트(현재는 마우스 이벤트)
		 */
		public dispatchEvent(type: string, e?: Event): void {
			if (this._isDisposed()) {
				return;
			}
			if (!this._listeners[type]) {
				return;
			}
			this._listeners[type].forEach((each: Function) => {
				each(e);
			});
		}
		/**
		 * @param type 
		 * @param func 
		 */
		public _addEventListener(type: string, func: Function) {
			if (!this._listeners[type]) {
				this._listeners[type] = [];
			}
			this._listeners[type].push(func);
		}
		/**
		 * @param type 
		 * @param func 
		 */
		public _removeEventListener(type, func) {
			if (!this._listeners[type]) {
				return;
			}
			let idx = this._listeners[type].indexOf(func);
			if (idx > -1) {
				this._listeners[type].splice(idx, 1);
			}
		}
		/**
		 * @param type 
		 */
		public _removeAllEventListener(type) {
			if (!this._listeners[type]) {
				return;
			}
			this._listeners[type] = [];
		}
		private _setContentHeight(height: number) {
			if (this._contentHeight == height) {
				return;
			}
			this._contentHeight = height;
		}

		private _getComboboxNode() {
			return this._getRenderer().getNamedNode(this._ns);
		}

		public _getListboxNode() {
			return this._getRenderer().getNamedNode(this._getQName("listbox"));
		}

		public _getDummyItemNode() {
			return this._getRenderer().getNamedNode(this._getQName("dummy-item"));
		}

		private _checkMaxVisibleItems() {
			if (this._beforeMaxVisibleItems == this._getMaxVisibleItems()) {
				return;
			}
			this._beforeMaxVisibleItems = this._getMaxVisibleItems();
			this._styleMaxHeight = null;
		}

		public _createShape(): ufc.ElementShape {

			this._checkMaxVisibleItems();
			let classNames = ["cl-control", ufc.Classes.POPUP, ufc.Classes.BOTTOM];

			let shape: cpr.ufc.ElementShape = {
				tag: "div",
				classNames: classNames,
				styler: this.styler.list,
				style: {
					verticalAlign: "top",
					position: "absolute", // fixed로 변경 했을시 ios에서 버티컬 레이아웃에 키보드가 표시되어 있는 상태이면 정상적인 위치값을 표시 할 수 없음. 2020-03-26
					left: "0px",
					top: "0px"
				},
				attr: {
					role: "listbox",
					tabindex: "-1"
				},
				nodename: this._getQName("listbox"),
				eventTargets: [ufc.EventTargetType.UICONTROL],
				events: {
					mousedown: this._onListMouseDown,
					wheel: this._onListWheel
				},
				children: [this._createScrollPane()]
			};
			ufc.ShapeUtil._setAriaDisabled(shape, this._isEnabled() && !this._getUIControl().readOnly);

			if (this.showCheckbox) {
				shape.classNames.push("cl-multi-select");
			}

			return shape;
		}

		private _getScrollWidth() {
			if (this._getContentHeight() <= this._getViewportHeight()) {
				return 0;
			}
			let scrollWidth = 0;
			if (this._uicontrol._isUseCustomScroll()) {
				scrollWidth = internal.ScrollbarUtil._getCustomScrollbarInfo().vWidth;
			} else {
				scrollWidth = internal.ScrollbarUtil._getNativeScrollWidth();
			}
			return scrollWidth
		}

		private setMaxHeight(height: number) {
			this._viewHeight = height - (height % this._getRowHeight());
			this._maxContentTop = this._getContentHeight() - this._viewHeight
			let range = this._calculateRange(this._getScrollTop());
			this._endRowIndex = range.end;
			this._startRowIndex = range.start;
			this._updateStyle("rcontent", { maxHeight: this._viewHeight + "px" });
		}

		private _createScrollPane() {
			let items = this.getItems();
			let rcontent: cpr.ufc.ElementShape = {
				tag: "div",
				classNames: this._uicontrol._isUseCustomScroll() ? ["cl-viewport", "cl-customscrollbar"] : ["cl-viewport"],
				style: {
					position: "relative",
					overflow: "hidden",
					width: `calc(100% - 0px)`
				},
				nodename: this._getQName("rcontent"),
				children: [this._createDummyList(), this._createList()]
			}
			if (this._styleMaxHeight) {
				rcontent.style["max-height"] = this._styleMaxHeight + "px";
			}
			let vScrollShape: ufc.ElementShape = this._getRenderer()._getNamedShape(this._getQName("custom-vscroll"));
			let updateScroll = this._getContentHeight() != (this._getRowHeight() * items.length);//스크롤바 길이가 갱신되는 경우 새로 생성하도록 한다.
			if (!vScrollShape || updateScroll || !this._initVScroll) {
				vScrollShape = { // vertical scrollbar
					tag: "div"
					, nodename: this._getQName("custom-vscroll")
					, style: { display: "none" }
				};
				this._initVScroll = true;
			}
			let wrap: cpr.ufc.ElementShape = {
				tag: "div",
				classNames: [ufc.Classes.UNSELECTABLE],
				attr: {},
				style: {
					height: "100%",
					width: "100%",
					position: "relative"
				},
				events: {
					focus: this._preventListFocus,
					focusin: this._preventListFocus
				},
				children: [rcontent, vScrollShape, _createTapLazyTask({
					task: () => {
						this._setup();
						this._updateMaxContentHeight();
						this._updateContent();
						this._updateBounds();
						this._updateScroll();
						// 최종으로 열렸는지 확인하는 값
						this._openTimer.cancel().schedule(300);
					}
				})]
			}
			ufc.ShapeUtil.addEventHandler(rcontent, "click", (e: MouseEvent) => this._onListClick(e), true);
			if (!this._uicontrol.readOnly) {
				ufc.ShapeUtil.addEventHandler(rcontent, "wheel", (e) => this._onWheel(e), true);
				ufc.ShapeUtil.addEventHandler(rcontent, "touchmove", (e) => this._onTouchMove(e), true);
				ufc.ShapeUtil.addEventHandler(rcontent, "touchstart", (e) => this._onTouchStart(e), true);
				ufc.ShapeUtil.addEventHandler(rcontent, "touchend", (e) => this._onTouchEnd(e), true);
			}

			return wrap;
		}

		private _setup() {
			this._updateDummyContent({ item: this._createDummyItem("dummy", "_dummy"), index: 0 });
			let content = this._getContentNode();
			let element = this._getDummyItemNode();
			//셀렉터에서 찾은 엘리먼트가 생성되지 않는 경우가 있음.
			if (element) {
				// 줌된 크기는 getBoundingClientRect 원래 크기는 offsetHeight
				let rowHeight = Math.ceil(element.offsetHeight) || parseInt(window.getComputedStyle(element).height);
				if (this._rowHeight != rowHeight) {
					this._rowHeight = rowHeight;
				}
			}

			if (this._styleMaxHeight == null) {
				if (this._getMaxVisibleItems() > 0) {
					this._styleMaxHeight = this._rowHeight * this._getMaxVisibleItems();
					this._updateStyle("rcontent", { maxHeight: this._styleMaxHeight + "px" });
				} else {
					let style = getComputedStyle(content);
					let styleMaxHeight = parseInt(style.maxHeight);
					if (!isNaN(styleMaxHeight)) {
						this._styleMaxHeight = styleMaxHeight;
					}
				}
			}

			let rowCount = this.getItems().length;
			this._setContentHeight(rowCount * this._rowHeight);
			this._viewHeight = this._calculateViewportHeight(this._getContentHeight());
			this._maxContentTop = this._getContentHeight() - this._viewHeight;

			let range = this._calculateRange(this._getScrollTop());
			this._endRowIndex = range.end;
			this._startRowIndex = range.start;
			this._updateDummyContent();
		}

		private _calculateViewportHeight(virtualHeight: number) {
			let vh = virtualHeight;
			if (this._styleMaxHeight < virtualHeight) {
				vh = Math.floor(this._styleMaxHeight / this._rowHeight) * this._rowHeight;
			}
			return vh;
		}

		protected abstract _createDummyItem(label: string, value: string): ItemType
		protected abstract _createListItem(item: ItemType, index: number): cpr.ufc.ElementShape

		private _createDummyList(dummy?: { item: ItemType, index: number }) {

			if (dummy) {
				let itemShape = this._createListItem(dummy.item, dummy.index);
				itemShape.nodename = this._getQName("dummy-item");
				return {
					classNames: [ufc.Classes.UNSELECTABLE],
					attr: {
						role: "listbox"
					},
					style: {
						position: "fixed",
						visibility: "hidden",
						left: "0px",
						top: `-${this._rowHeight}px`,
						"pointer-events": "none"
					},
					tag: "div",
					nodename: this._getQName("listbox-dummy-content"),
					children: [itemShape]
				};
			}

			return {
				classNames: [],
				attr: {},
				style: {
					position: "relative",
					display: "none"
				},
				tag: "div",
				nodename: this._getQName("listbox-dummy-content"),
				children: []
			};

		}

		private _createList(drawItem: boolean = false): cpr.ufc.ElementShape {
			// item list box
			let itemShapes: cpr.ufc.ElementShape[] = [];

			if (drawItem) {
				let size: number = this._endRowIndex;
				let i = this._startRowIndex;
				let items = this.getItems();

				for (; i < size; i++) {
					let item = items[i];
					let listItemShape = this._createListItem(item, i);
					itemShapes.push(listItemShape);
				}
			}

			let list: cpr.ufc.ElementShape = {
				classNames: [ufc.Classes.UNSELECTABLE],
				attr: {
					id: this._getListElementId(),
					role: "listbox"
				},
				style: {
					position: "relative"
				},
				tag: "div",
				nodename: this._getQName("listbox-content"),
				children: itemShapes
			};
			ufc.ShapeUtil._setAriaDisabled(list, this._isEnabled() && !this._getUIControl().readOnly);
			return list;
		}

		private _updateMaxContentHeight() {
			let rootNode = this._getComboboxNode();
			let listboxNode = this._getListboxNode();
			if (!rootNode) {
				return;
			}
			let listboxComputedStyle = window.getComputedStyle(listboxNode);
			let contentHeight = this._getContentHeight();
			let maxHeight = this._getMaxHeight();
			let currentHeight = contentHeight > maxHeight ? maxHeight : contentHeight;
			let rootSpace = _getComputedSpaceInsets(rootNode, {
				verticalMargin: 5 + _parseFloat(listboxComputedStyle.marginBottom) + _parseFloat(listboxComputedStyle.marginTop)
					+ _parseFloat(listboxComputedStyle.paddingTop) + _parseFloat(listboxComputedStyle.paddingBottom)
			});

			if (currentHeight > rootSpace.bottom && rootSpace.top > rootSpace.bottom) {
				if (maxHeight > rootSpace.top) {
					this.setMaxHeight(rootSpace.top);
				}
			} else {
				if (maxHeight > rootSpace.bottom) {
					this.setMaxHeight(rootSpace.bottom);
				}
			}
		}

		private _updateBounds() {
			let listboxNode = this._getListboxNode();
			let rootNode = this._getComboboxNode();
			if (!rootNode) {
				return;
			}
			let rootRect = _getOffsetRectFromViewport(rootNode, false);
			let viewportRect = _getVisualViewportRect();
			let constraint = {
				top: rootRect.top + rootRect.height,
				bottom: null,
				left: rootRect.left,
				right: null,
				width: rootRect.width,
				height: null
			}
			let useBodyScroll = this._useBodyScroll();
			let workVerticalPosition: () => void;
			let rootClassList = [ufc.Classes.OPENED_BOTTOM];
			let rootSpace = _getComputedSpaceInsets(rootNode, { verticalMargin: 5, horizontalMeasurePosition: "reverseBoth", leftOverflow: "altViewport" });
			// 실제 리스트박스 크기와 위치
			let listboxRect = _getUnscaledClientRect(listboxNode);
			let listboxComputedStyle = window.getComputedStyle(listboxNode);

			// margin 값이 포함된 rect
			let listboxExpandedRect = listboxRect.getExpanded(new geometry.Insets(_parseFloat(listboxComputedStyle.marginTop), 0, _parseFloat(listboxComputedStyle.marginBottom), 0));

			// 애니메이션이 있을 경우 rect의 높이가 0이 될 수 있어 height를 계산할 수 없으므로, getComputedStyle로 높이를 가져온다.
			let listboxExpandedHeight = listboxExpandedRect.height || parseInt(listboxComputedStyle.height);
			if (listboxExpandedHeight > rootSpace.bottom && rootSpace.top > rootSpace.bottom) {
				constraint.top = null;
				let classList = [ufc.Classes.TOP];
				rootClassList = [ufc.Classes.OPENED_TOP];

				this._getRenderer().updateClass(this._getQName("listbox"), [ufc.Classes.BOTTOM], classList);
				listboxRect = _getUnscaledClientRect(listboxNode);
				//margin 값이 포함된 rect
				listboxExpandedRect = listboxRect.getExpanded(new geometry.Insets(_parseFloat(listboxComputedStyle.marginTop), 0, _parseFloat(listboxComputedStyle.marginBottom), 0));
				listboxExpandedHeight = listboxExpandedRect.height || parseInt(listboxComputedStyle.height);
				workVerticalPosition = () => {
					constraint.top = rootRect.top - listboxExpandedHeight;
					constraint.height = listboxExpandedHeight;
				}
			} else {
				workVerticalPosition = () => {
					let listboxTop = constraint.top;
					if (useBodyScroll) {
						let minTop = viewportRect.top;
						if (minTop > listboxTop) {
							constraint.top = minTop;
						}
					} else {
						if (0 > listboxTop) {
							constraint.top = 0;
						}
					}
				}
			}

			this._getRenderer().updateClass(this.namespace, [], rootClassList); // combobox

			let maxSpace = Math.max(rootSpace.bottom, rootSpace.top);
			if (listboxExpandedHeight > maxSpace) {
				constraint.height = maxSpace;
			}
			workVerticalPosition();

			if (this._isFixedListWidth() == false) {
				let listMinWidth = this._computedListMinWidth(listboxNode) + this._getScrollWidth();
				if (rootRect.width < listMinWidth) {
					constraint.width = listMinWidth;
				}
			}

			let listWidth = constraint.width;
			if (viewportRect.width > listWidth) {
				let padding = + controls.internal.ScrollbarUtil._getNativeScrollWidth(); //detecting overflow value.
				// 콤보박스 기준 오른쪽 , 왼쪽 여백 비교
				if (listWidth + padding > rootSpace.right && rootSpace.left > rootSpace.right) {
					if (rootSpace.left < listWidth) {
						let pos = (rootRect.left + listWidth) - viewportRect.right;
						constraint.left = rootRect.left - pos;
					} else {
						let pos = (rootSpace.left + viewportRect.left) - listWidth;
						constraint.left = pos > viewportRect.left ? pos : viewportRect.left;
					}
				} else {
					let listboxLeft = constraint.left;
					if (useBodyScroll) {
						let minLeft = viewportRect.left;
						if (minLeft > listboxLeft) {
							constraint.left = minLeft;
						} else if (listWidth > rootSpace.right) {
							let pos = (rootRect.left + listWidth) - viewportRect.right;
							constraint.left = rootRect.left - pos;
						}
					} else {
						if (viewportRect.left > listboxLeft) {
							constraint.left = viewportRect.left;
						} else if (listWidth > rootSpace.right) {
							let pos = (rootRect.left + listWidth) - viewportRect.right;
							constraint.left = rootRect.left - pos;
						}
					}
				}
			} else {
				constraint.left = viewportRect.left;
				constraint.width = viewportRect.width;
			}

			let style = _.mapObject(constraint, (val: number | null, key: string) => {
				if (val == null) {
					return "auto";
				}
				return val + "px";
			})
			this._updateStyle("listbox", style);
		}

		protected _computedListMinWidth(listNode: HTMLElement) {
			let computedStyle = getComputedStyle(listNode);
			let listPadding = parseInt(computedStyle.paddingLeft) || 0;
			listPadding += parseInt(computedStyle.paddingRight) || 0;
			if (!this._cacheItemMaxWidth) {
				this._cacheItemMaxWidth = this._getComputedItemWidth(this.getItems());
			}
			let adjustWidth = 2;
			return this._cacheItemMaxWidth + listPadding + adjustWidth;
		}

		private _updateScroll() {

			let scrollWidth = this._getScrollWidth();
			this._updateStyle("rcontent", { width: `calc(100% - ${scrollWidth}px)` });
			if (this._getMaxContentTop() <= 0) {
				return;
			}
			let vScrollShape = this._vscrollbar._createScrollbar(this._getScrollTop(), this._getContentHeight());
			this._replace("custom-vscroll", vScrollShape);

			if (this._requestScroll) {
				let selectionViewIndex = this._getSelectionViewIndex();
				let scrollIndex = this.hoveredIndex;
				if (selectionViewIndex > 0) {
					scrollIndex = selectionViewIndex < scrollIndex ? scrollIndex - selectionViewIndex : 0;
				}
				this.scrollByIndex(scrollIndex);//rowheight의 값을 변경한다.
				this._requestScroll = false;
			}
		}

		private _updateContent() {
			this._replace("listbox-content", this._createList(true));
		}

		private _updateDummyContent(dummy?: { item: ItemType, index: number }) {
			this._replace("listbox-dummy-content", this._createDummyList(dummy))
		}

		protected _computeItemTextWidth(item: ItemType, font: string) {
			let text = ufc.StyledString._asString(this._computeItemDisplayLabel(item));
			let textWidth = utils.StringUtil.measureText(text, font);
			return textWidth;
		}

		protected _getComputedItemWidth(items: ItemType[]): number {
			this._updateDummyContent({ item: this._createDummyItem("dummy", "_dummy"), index: 0 });
			let itemWidth = 0;
			let maxTextWidth = 0;
			let getItemFont = () => {
				let computedStyle = getComputedStyle(this._getDummyItemNode());
				let fontProps = ["fontStyle", "fontVariant", "fontWeight", "fontSize", "lineHeight", "fontFamily"];
				let font = "";
				for (let prop of fontProps) {
					if (prop == "lineHeight") {
						font += " / " + computedStyle[prop];
					} else {
						font += " " + computedStyle[prop];
					}
				}
				return font;
			}
			let font = getItemFont();
			items.forEach((each: ItemType, idx: number) => {
				let textWidth = this._computeItemTextWidth(each, font); // 텍스트 길이로 비교하기에는 영문과 한글의 너비 차이가 있어 같은 개수라도 다름.
				if (textWidth <= maxTextWidth) {
					return;
				}
				maxTextWidth = textWidth;
				this._replace("listbox-dummy-content", this._createDummyList({ item: each, index: idx }));
				let node = this._getDummyItemNode();
				if (node) {
					let style = getComputedStyle(node);
					let marginRight = parseInt(style.marginRight) || 0;
					let marginLeft = parseInt(style.marginLeft) || 0;
					let paddingLeft = parseInt(style.paddingLeft) || 0;
					let paddingRight = parseInt(style.paddingRight) || 0;
					let nodeWidth = node.offsetWidth + marginLeft + marginRight + paddingLeft + paddingRight;
					itemWidth = itemWidth < nodeWidth ? nodeWidth : itemWidth;
				}
			})
			this._updateDummyContent();
			return itemWidth;
		}

		private _onListWheel(e: WheelEvent) {
			let ele = <HTMLElement>e.target;
			if (ele.classList.contains("cl-scrollbar") == false) {
				e.preventDefault();
				e.stopPropagation();
				return;
			}
			let maxScrollHeight = ele.scrollHeight - ele.clientHeight;
			if ((ele.scrollTop >= maxScrollHeight && e.deltaY > 0) || (ele.scrollTop <= 0 && e.deltaY < 0)) {
				e.preventDefault();
				e.stopPropagation();
			}
		}

		public keyNavigation(keyCode: number, index: number, e: KeyboardEvent) {

			//move hover item - keyup
			if (keyCode == events.KeyCode.UP) {

				if (index - 1 > -1) {
					this._hoveredIndex = index - 1;
					if (this.scrollUp(index) == false) {
						// this._updateContent(); // 부모 콤보박스 웹접근성 정보 갱신이 필요하여 redraw사용
					}
					this._uicontrol.redraw();
				}
				e.preventDefault();
				e.stopPropagation();
			}

			//move hover-item - pageup
			if (keyCode == events.KeyCode.PAGEUP) {
				//pageup
				let pageSize = (this._getViewportHeight() / this._getRowHeight());
				let count = pageSize - 1;
				let moveIndex = 0;
				if (index - count > 0) {
					moveIndex = index - count;
				} else {
					moveIndex = 0;
				}
				if (this.hoveredIndex != moveIndex) {
					this._hoveredIndex = moveIndex;
					if (this.scrollPageUp(index) == false) {
						// this._updateContent(); // 부모 콤보박스 웹접근성 정보 갱신이 필요하여 redraw사용
					}
					this._uicontrol.redraw();
				}

				e.preventDefault();
				e.stopPropagation();
			}

			//move hover-item - pagedown
			if (keyCode == events.KeyCode.PAGEDOWN) {
				//pagedown
				let pageSize = (this._getViewportHeight() / this._getRowHeight());
				let count = pageSize - 1;
				let size = this.getItems().length;
				let moveIndex = 0;
				if (index + count < size) {
					moveIndex = index + count;
				} else {
					moveIndex = size - 1;
				}
				if (this.hoveredIndex != moveIndex) {
					this._hoveredIndex = moveIndex;
					if (this.scrollPageDown(index) == false) {
						// this._updateContent(); // 부모 콤보박스 웹접근성 정보 갱신이 필요하여 redraw사용
					}
					this._uicontrol.redraw();
				}
				e.stopPropagation();
				e.preventDefault();
			}
			//move hover-item - keydown
			if (keyCode == events.KeyCode.DOWN) {

				if (this.getItems().length > index + 1) {
					this._hoveredIndex = index + 1;
					if (this.scrollDown(index) == false) {
						// this._updateContent(); // 부모 콤보박스 웹접근성 정보 갱신이 필요하여 redraw사용
					}
					this._uicontrol.redraw();

				}
				e.preventDefault();
				e.stopPropagation();
			}
		}

		private _renderView(scrollTop: number) {
			let range = this._calculateRange(scrollTop);
			let oldStart = this._startRowIndex;
			let oldEnd = this._endRowIndex;

			this._startRowIndex = range.start;
			this._endRowIndex = range.end;
			if ((oldStart != this._startRowIndex || oldEnd != this._endRowIndex)) {
				this._updateContent();
			}
		}

		private _calculateRange(scrollTop: number) {
			let rowHeight = this._getRowHeight();
			let y = Math.ceil(scrollTop);
			let buffer = 0; //영역 밖에 추가로 생성할 크기.
			let top = Math.floor((y - buffer) / rowHeight);
			let bottom = Math.floor(top + (this._getViewportHeight() / rowHeight));

			let result = { start: 0, end: 0 };
			result.start = Math.max(0, top);
			result.end = Math.min(this._getContentHeight() / rowHeight, bottom);
			return result;
		}

		_isEnabled(): boolean {
			return this._uicontrol.enabled;
		}

		_getViewportWidth(): number {
			return 0;
		}

		_getViewportHeight(): number {
			return this._viewHeight;
		}

		_getContentWidth(): number {
			return 0;
		}

		_getContentHeight(): number {
			return this._contentHeight;
		}

		_getQName(name: string): string {
			return this._ns + "-" + name;
		}

		_setScrollTop(e: events.CUIEvent, scrollTop: number): number {
			if (scrollTop < 0) {
				scrollTop = 0;
			} else if (scrollTop > this._getMaxContentTop()) {
				scrollTop = this._getMaxContentTop();
			}
			if (this._getScrollTop() == scrollTop) {
				return -1;
			}
			this._renderView(scrollTop);
			this._vScrollTop = scrollTop;

			return scrollTop;
		}

		_getScrollTop(): number {
			return this._vScrollTop;
		}

		_setScrollLeft(e: events.CUIEvent, scrollLeft: number): number {
			return -1;
		}

		_checkResize(): void {

		}

		_getRenderer(): ufc.ControlRenderer {
			return this._uicontrol._getRenderer();
		}

		_checkWindowResize(): void {
			this._requestScroll = true;
			this._initVScroll = false;
		}

		private _useBodyScroll(): boolean {
			return this._uicontrol.getAppInstance().getRootAppInstance().getContainer()._useBodyScroll()
		}

		private _getRowHeight(): number {
			return this._rowHeight;
		}

		private _getMaxContentTop(): number {
			return this._maxContentTop;
		}

		private _getMaxHeight() {
			return this._styleMaxHeight;
		}

		private _getContentNode() {
			return this._getRenderer().getNamedNode(this._getQName("rcontent"));
		}

		private _setVScrollbarTopOffset(e: events.CUIEvent, offset: number) {
			let scrollTop: number = this._vScrollTop;
			scrollTop += offset;
			return this._setVScrollbarTop(e, scrollTop);
		}

		private _setVScrollbarTop(e: events.CUIEvent, scrollTop: number): boolean {
			let movedScrollTop: number = this._setScrollTop(e, scrollTop);
			if (movedScrollTop == -1) {
				return false;
			}
			this._vscrollbar._setScrollTop(movedScrollTop);
			return true;
		}

		private _getPageSize() {
			return this._getViewportHeight() / this._getRowHeight();
		}

		private _replace(nodename: string, shape: ufc.ElementShape) {
			this._getRenderer().replace(this._getQName(nodename), shape);
		}

		private _updateStyle(nodename: string, style: {}) {
			this._getRenderer().updateStyle(this._getQName(nodename), style, true);
		}

		protected _getItemQuerySelector() {
			return "[data-role='option']";
		}

		//events
		private _onListClick(e: MouseEvent) {
			let rootElement: HTMLElement = <HTMLElement>e.currentTarget;
			let eventElement: HTMLElement = <HTMLElement>e.target;
			let domTraverser = ufc._traverseFromElement(eventElement)._closest(this._getItemQuerySelector(), rootElement);
			if (domTraverser == null) {
				return;
			}

			let value: string = domTraverser._getAttribute('data-id');
			let item = _stream(this.getItems()).find((each: ItemType) => {
				return each._getUUID() == value;
			});

			if (this._getItemEnable(item) === false) {
				return;
			}

			let index: number = parseInt(domTraverser._getAttribute("data-itemidx"));

			let targetName = this._extractTargetName(eventElement);
			this._onItemClick({ itemIdx: index, relativeTargetName: targetName, item: item, nativeEvent: e, defaultPrevented: false });

		}

		protected _onItemClick(e: { itemIdx: number, relativeTargetName: string, item: ItemType, nativeEvent: MouseEvent, defaultPrevented: boolean }): void {
			this._hoveredIndex = e.itemIdx;

			if (e.defaultPrevented) {
				return;
			}
			let itemClickEvent = new cpr.events.CItemEvent(events.ItemEventType.ITEMCLICK, {
				item: e.item,
				relativeTargetName: e.relativeTargetName
			})
			itemClickEvent['nativeEvent'] = e.nativeEvent;
			this.dispatchEvent("item-click", itemClickEvent);
		}

		private _extractTargetName(element: HTMLElement) {
			if (!element) {
				return "";
			}
			let checkClassList = ["cl-treeicon", ufc.Classes.ICON, ufc.Classes.TEXT, "cl-checkbox"];
			let pos = "";
			checkClassList.some((each) => {
				if (element.classList.contains(each)) {
					pos = each;
					return true;
				}
				return false;
			});
			let targetName = pos.substring(pos.lastIndexOf("-") + 1, pos.length);
			return targetName;
		}

		private _onListMouseDown(e: MouseEvent): void {
			// IE 버전. 11.0.9600.18837, 11.0.9600.18838, 11.726.
			// IE 환경에서 list 내부 스크롤에 mousedown을 이용하여 스크롤을 이동하는 경우 blur 이벤트가 발생하는 문제 발생.
			// IE 버전 11.64.16299.0 이후에서는 발견되지 않음.
			// 위의 문제를 focusin을 추가하여 제어 함. 2017-12-1
			e.preventDefault();
		}

		/**
		 * List 영역의 포커스를 방지한다.
		 * @param e CFocusEvent
		 */
		private _preventListFocus(e: events.CFocusEvent): void {
			//IE11 특정버전에서 발생하는 오류
			e.preventDefault();
			e.stopPropagation();
		}

		/**
		 * content에 wheel 이벤트로 스크롤 위치에 보여질 아이템이 달라지면 redraw 한다.
		 * @param e 
		 */
		private _onWheel(e: events.CWheelEvent) {
			if (e.ctrlKey === true) { // 확대/축소
				return;
			}
			let eventDelta: { x: number, y: number } = internal.ScrollbarUtil._getScrollPaneWheelDelta(e);
			if (eventDelta == null) {
				return;
			}

			let delta: number = 0;
			let rowHeight: number = this._getRowHeight();

			let wheelRowCount = this._uicontrol["wheelRowCount"] == undefined ? 1 : this._uicontrol["wheelRowCount"];
			if (wheelRowCount == 0) {
				delta = 0;
			} else {
				if (Math.abs(eventDelta.y) < rowHeight) {
					delta = rowHeight;
				} else {
					delta = rowHeight * wheelRowCount;
				}
			}
			let offset: number = eventDelta.y == 0 ? 0 : (eventDelta.y > 0 ? 1 : -1);
			let deltaY: number = delta * offset;
			let moved: boolean = false;
			if (this._vscrollbar && deltaY != 0) {
				moved = this._setVScrollbarTopOffset(e, deltaY) || moved;
			}

			if (moved) {
				e.preventDefault();
				e.stopPropagation();
			}
		}

		private _touchRoller: internal.TouchRoller = internal.newTouchRoller();

		private _onTouchStart(e: events.CTouchEvent) {
			this._touchRoller._touchStart(e,
				this._maxContentTop > 0 ? this._vscrollbar._getScrollTop() : -1,
				0
			);
		}

		private _onTouchMove(e: events.CTouchEvent): void {
			this._touchRoller._touchMove(e, (scrollTop: number, scrollLeft: number): boolean => {
				let movedY: boolean = scrollTop !== -1 ? this._setVScrollbarTop(e, scrollTop) : false;
				return movedY;
			});
			e.stopPropagation();
			e.preventDefault();
		}

		private _onTouchEnd(e: events.CTouchEvent) {
			this._touchRoller._touchEnd(e,
				this._maxContentTop > 0 ? this._vscrollbar._getScrollTop() : -1, 0,
				(scrollTop: number, scrollLeft: number): boolean => {
					let movedY: boolean = scrollTop !== -1 ? this._setVScrollbarTop(e, scrollTop) : false;
					return movedY;
				}
			);
		}

		//API
		public scrollByIndex(index: number) {

			if (index == null || index < 0) {
				return;
			}

			let maxScrollTop = this._getMaxContentTop(); // 최대 scrolltop
			let rowHeight = this._getRowHeight();
			let moveOffset = rowHeight * index; // 이동할 위치
			if (maxScrollTop < 0) {
				return;
			}
			let scrollTop = moveOffset > maxScrollTop ? maxScrollTop : moveOffset;

			if (scrollTop < 0) {
				scrollTop = 0;
			}
			let movedScrollTop = this._setScrollTop(null, scrollTop);
			this._vscrollbar._setScrollTop(movedScrollTop == -1 ? scrollTop : movedScrollTop);
			return true;

		}

		/**
		 * 스크롤을 위로 올린다.
		 * @param baseRowIndex 행의 시작위치
		 * @param count 행이 이동할 크기
		 * @param viewport 스크롤을 갖는 HTMLElement
		 */
		public scrollUp(baseRowIndex: number = 0, count: number = 1): boolean {
			let scrollTop = this._getScrollTop();

			if (scrollTop == null) {
				return false;
			}
			let rowHeight = this._getRowHeight();
			let viewportHeight = this._getViewportHeight();
			let rowOffsetTop = baseRowIndex * rowHeight;
			let prevRowOffset = rowOffsetTop == 0 ? 0 : rowOffsetTop - (rowHeight * count);

			let viewOffsetMin = scrollTop;
			let viewOffsetMax = scrollTop + viewportHeight;

			if ((viewOffsetMin > prevRowOffset && viewOffsetMin - viewportHeight <= prevRowOffset)) {//다음 뷰포트로 이동
				scrollTop = scrollTop - (viewOffsetMin - prevRowOffset);
			} else if (viewOffsetMin > prevRowOffset || viewOffsetMax <= prevRowOffset) {// 알수 없응 위치에서 이동
				scrollTop = prevRowOffset;
			}
			if (scrollTop < 0) {
				scrollTop = 0;
			}
			let movedScrollTop = this._setScrollTop(null, scrollTop);
			if (movedScrollTop == -1) {
				return false;
			}
			this._vscrollbar._setScrollTop(movedScrollTop);
			return true;
		}

		/**
		 * 스크롤을 영역 안의 행의 크기만큼 이동한다.
		 * @param baseRowIndex 행의 시작위치
		 */
		public scrollPageUp(baseRowIndex: number = 0): boolean {
			return this.scrollUp(baseRowIndex, this._getPageSize() - 1);
		}

		/**
		 * 스크롤을 아래로 이동한다.
		 * @param baseRowIndex 행의 시작위치
		 * @param count 행이 이동할 크기
		 * @param viewport 스크롤을 갖는 HTMLElement
		 */
		public scrollDown(baseRowIndex: number = 0, count: number = 2): boolean {
			let scrollTop = this._getScrollTop();

			if (scrollTop == null) {
				return false;
			}
			let viewportHeight = this._getViewportHeight();
			let rowHeight = this._getRowHeight();
			let rowOffsetTop = baseRowIndex * rowHeight;
			let nextRowOffset = rowOffsetTop + (rowHeight * count);

			let viewOffsetMin = scrollTop;
			let viewOffsetMax = scrollTop + viewportHeight;

			if ((viewOffsetMax < nextRowOffset && viewOffsetMax + viewportHeight >= nextRowOffset)) {//다음 뷰 영역으로 이동 할때
				scrollTop = scrollTop + (nextRowOffset - viewOffsetMax);

			} else if (viewOffsetMin >= nextRowOffset || viewOffsetMax < nextRowOffset) { //알수 없는 위치에서 이동할때
				scrollTop = nextRowOffset - viewportHeight;
			}

			if (scrollTop < 0) {
				scrollTop = 0;
			}
			let movedScrollTop = this._setScrollTop(null, scrollTop);
			if (movedScrollTop == -1) {
				return false;
			}
			this._vscrollbar._setScrollTop(movedScrollTop);
			return true;

		}

		/**
		 * 스크롤을 영역 안의 행의 크기만큼 이동한다.
		 * @param baseRowIndex 행의 시작 위치
		 */
		public scrollPageDown(baseRowIndex: number): boolean {
			return this.scrollDown(baseRowIndex, this._getPageSize());
		}
	}


}
