/**
 * 제어 구문 작성을 돕는 유틸리티 모음.
 */
namespace cpr {
	/**
	 * 새로운 타입 스위치를 작성합니다.
	 * @private
	 * @returns 새로운 타입 스위치
	 */
	export function _createTypeSwitch<Output>() {
		return new TypeSwitch<Output>();
	}

	interface PrimitiveTypeMap {
		"string": string,
		"number": number,
		"boolean": boolean
	}

	class CaseClause<Output> {
		_constructor: Function;
		_primitiveTypeName: keyof PrimitiveTypeMap;

		_producer: (input: any) => Output;

		constructor(primitiveType: keyof PrimitiveTypeMap, producer: (input: any) => Output);
		constructor(constructor: Function, producer: (input: any) => Output);
		constructor(type: keyof PrimitiveTypeMap | Function, producer: (input: any) => Output) {
			switch (typeof type) {
				// IE의 경우 브라우저 내장 객체 클래스가 object 타입으로 잡힌다.
				case "object":
				case "function":
					this._constructor = type;
					break;
				case "string":
					this._primitiveTypeName = type;
					break;
				default:
					throw new exceptions.IllegalArgumentException();
			}
			this._producer = producer;
		}

		get primitive() {
			return this._primitiveTypeName != null;
		}

		matches(input: any) {
			if (this.primitive) {
				return typeof input == this._primitiveTypeName;
			} else {
				return input instanceof this._constructor;
			}
		}

		produce(input: any): Output {
			return this._producer(input);
		}

		compare(other: CaseClause<Output>): number {
			let a = this;
			let b = other;

			// 둘다 프리미티브 타입인 경우.
			if (a.primitive && b.primitive) {
				return a._primitiveTypeName.localeCompare(b._primitiveTypeName);
			}

			// a가 프리미티브 타입인 경우.
			else if (a.primitive && !b.primitive) {
				return -1;
			}

			// b가 프리미티브 타입인 경우.
			else if (!a.primitive && b.primitive) {
				return 1;
			}

			let constructorA = a._constructor;
			let constructorB = b._constructor;


			if (constructorA.prototype instanceof constructorB) {
				return -1;
			} else if (constructorB.prototype instanceof constructorA) {
				return 1;
			} else {
				return 0;
			}
		}
	}

	/**
	 * @private
	 */
	export class TypeSwitch<Output> {
		private _cases: CaseClause<Output>[] = [];
		private _defaultProducer: (input: any) => Output;
		private _needsSort: boolean = true;

		private _sortIfNeeded(): void {
			if (!this._needsSort) {
				return;
			}
			this._cases = this._cases.sort((a, b) => a.compare(b));
			this._needsSort = false;
		}

		/**
		 * 프리미티브 타입인 경우의 처리 함수를 등록합니다.
		 * @param type 처리할 프리미티브 타입.
		 * @param producer 해당 타입으로부터 결과를 생성하는 프로듀서 함수.
		 */
		case<K extends keyof PrimitiveTypeMap>(type: K, producer: (input: PrimitiveTypeMap[K]) => Output): TypeSwitch<Output>;

		/**
		 * 객체 타입인 경우에 대한 처리 함수를 등록합니다.
		 * @param type 처리할 타입의 생성자.
		 * @param producer 해당 타입으로부터 결과를 생성하는 프로듀서 함수.
		 */
		case<C>(type: ConstructorOf<C>, producer: (input: C) => Output): TypeSwitch<Output>

		case<C>(type: any, producer: (input: C) => Output): TypeSwitch<Output> {
			this._cases.push(new CaseClause(type, producer));
			this._needsSort = true;
			return this;
		}

		/**
		 * 어떤 케이스에도 매칭되지 않았을 때 결과를 생성하는 프로듀서 함수를 등록합니다.
		 * @param producer 어떤 케이스에도 매칭되지 않았을 때 결과를 생성하는 프로듀서 함수.
		 */
		default(producer: (e: any) => Output): TypeSwitch<Output> {
			this._defaultProducer = producer;
			return this;
		}

		/**
		 * 입력 객체로 부터 타입 스위치를 실행합니다.
		 * 입력된 타입에 대해 여러 타입 케이스가 등록되어 있는 경우 더 구체적인 타입 케이스(자식 클래스)로 처리됩니다.
		 * @param input 입력 객체.
		 * @returns 입력 객체의 타입에 매칭된 케이스 프로듀서의 처리 결과.
		 */
		run(input: any): Output {
			this._sortIfNeeded();

			let matching = this._cases.find(e => e.matches(input));
			if (matching) {
				return matching.produce(input);
			} else {
				return this._defaultProducer?.call(this, input);
			}
		}
	}
}
