namespace cpr {
	type ProxyDescriptor<T extends object>
		= { [property in keyof T]?: PropertyDescriptor; }
		& { [otherProperty: string]: PropertyDescriptor; }
		& ThisType<T>;

	export function _createProxy<T extends object>(source: T, descriptors: ProxyDescriptor<T>): T {
		let result = Object.create(source, descriptors);
		return result as T;
	}
}