namespace cpr.controls.item {
	/**
	 * @private
	 */
	export class TreeItemList extends ItemList<TreeItem, TreeItemSetConfig> {

		private _rootValue: string = "";

		constructor(owner: any, itemConfig: ItemDataSource<TreeItemSetConfig>, itemListAdapter: ItemListAdapter<TreeItem> = treeItemAdapter) {
			super(owner, itemConfig, itemListAdapter);
			this.setValidatorType(ControlItemValidatorType.treeItem);
		}

		/**
		 * 최상위 value를 반환합니다.
		 * @return 최상위 value.
		 */
		get rootValue(): string {
			return this._rootValue;
		}

		/**
		 * 최상위 value를 설정합니다.
		 * @param rootValue 최상위 value.
		 */
		set rootValue(rootValue: string) {
			this._rootValue = rootValue;
		}

		/**
		 * 해당 트리 데이터의 상위(부모) 데이터를 반환합니다.
		 * @param item 트리 데이터.
		 * @return 상위 트리 데이터.
		 */
		public getParent(item: TreeItem): TreeItem {
			if (item == null) {
				return null;
			}
			let parentValue: string = item.parentValue;
			return this.getByValue(parentValue);
		}

		protected override _getPredefinedItemProperty(item: TreeItem, key: string) {
			if (key == ItemDataSetCtrlProperty.open) {
				return item._getOpen();
			}
			return super._getPredefinedItemProperty(item, key);
		}

		protected override _setPredefinedItemProperty(item: TreeItem, key: string, value: any) {
			if (key == ItemDataSetCtrlProperty.open) {
				item._setOpen(value);
			}
			super._setPredefinedItemProperty(item, key, value);
		}
		/**
		 * 해당 트리 데이터가 상위(부모) 데이터를 가졌는 지 여부를 반환합니다.
		 * @param item 트리 데이터.
		 * @return 상위 데이터 보유 여부.
		 */
		public hasParent(item: TreeItem): boolean {
			return this.getParent(item) != null;
		}

		/**
		 * 해당 트리 데이터가 하위(자식) 데이터를 가졌는 지 여부를 반환합니다.
		 * @param item 트리 데이터.
		 * @return 하위 데이터 보유 여부.
		 */
		public hasChild(item: TreeItem): boolean {
			let findChild = this.findOne((it: TreeItem) => {
				return it.parentValue == item.value;
			});
			return findChild != null;
		}

		/**
		 * 최상위 아이템들을 반환합니다.
		 * @returns 최상위 아이템 배열
		 */
		public getRootItems(): TreeItem[] {
			let itemInfo = this._getItemInfo();
			let rootItems = itemInfo.rootItems;
			return rootItems;
		}

		/// ItemList 구현 부분

		/**
		 * 아이템들을 반환합니다.
		 * @returns 
		 */
		public override getItems(): TreeItem[] {
			let itemInfo = this._getItemInfo();
			let items: TreeItem[] = itemInfo.items;
			return items;
		}

		public override findOne(findFunc: (it: TreeItem, idx?: number) => boolean): TreeItem {
			let result: TreeItem = null;
			let items: TreeItem[] = this.getCacheItems();
			items.some((each: TreeItem, index: number) => {
				if (findFunc(each, index) == true) {
					result = each;
					return true;
				}
				return false;
			});
			return result;
		}

		public override find(findFunc: (it: TreeItem, idx?: number) => boolean): TreeItem[] {
			let items: TreeItem[] = this.getCacheItems();
			return items.filter((each: TreeItem, index: number) => {
				return findFunc(each, index) == true;
			});
		}

		/// ItemList 구현 부분 끝

		/**
		 * 트리 구조를 생성합니다.
		 * @param valueKeyMap 아이템 value 맵
		 * @param items 아이템 배열
		 * @returns 최상위 아이템 배열
		 */
		public _createTreeStructure(valueKeyMap: provider.ItemMap<TreeItem>, items: TreeItem[]) {

			let rootItems = [];
			for (let currentItem of items) {
				//부모 자식간에 노드 연결
				let parentValue = currentItem.parentValue;
				let parentItem = valueKeyMap.get(parentValue);
				if (parentItem && parentValue != currentItem.value) {
					if (parentItem._getChildren() == null) {
						parentItem._setChildren([]);
					}
					currentItem._setParent(parentItem);
					parentItem._getChildren()[parentItem.children.length] = currentItem;
				} else {
					rootItems[rootItems.length] = currentItem;
				}
			}
			return rootItems;
		}

		/**
		 * 아이템 정보를 가져옵니다.
		 * @param useException 예외 사용 여부
		 * @param immediatelyException 즉시 예외 발생 여부
		 * @returns 아이템과 최상위 아이템 정보
		 */
		public _getItemInfo(useException: boolean = false, immediatelyException: boolean = false): { items: TreeItem[], rootItems: TreeItem[] } {
			let checkedItemMap = new provider.ItemMap<TreeItem>();
			let processItemData: (item: TreeItem) => void = (item: TreeItem) => {
				checkedItemMap.set(item.value, item);
			}
			if (useException && immediatelyException) {
				let validator = this._getValidator();

				processItemData = (item: TreeItem) => {
					validator.validateItem(item, {
						ownerId: this.owner.id,
						ownerType: this.owner.type,
						delimiter: this.owner.delimiter,
						multiple: this.owner.multiple
					}, checkedItemMap);
					checkedItemMap.set(item.value, item);
				}
			}

			let items: TreeItem[] = [];
			this.predefinedItems.forEach((item: TreeItem) => {
				item._setParent(null);// 선행데이터 객체를 참조 하고 있어 부모,자식을 삭제해야함.
				item._setChildren(null);
				processItemData(item);
				items[items.length] = item;
			});
			if (this.dataSet != null) {
				let rowIndices: number[] = this.dataSet.getRowStatedIndices(this.visibleRowState);
				rowIndices.forEach((rowIndex: number) => {
					let row: data.IDataRow = this.dataSet.getRow(rowIndex);
					let item: TreeItem = this._convertRowToItem(row);
					processItemData(item);
					items[items.length] = item;
				});
			}

			let rootItems = this._createTreeStructure(checkedItemMap, items);
			checkedItemMap = null;
			return { items: items, rootItems: rootItems };
		}

	}
}