

namespace cpr.foundation {
	/**
	 * @private
	 */
	export class LazyBigDecimal {
		private _sign: string = "";
		private _intnum: string = ""; // 정수부
		private _fraction: string = ""; // 소수부
		private _hasDot: boolean = false;


		constructor(wholenumber: string, intscale: number, fracscale: number) {
			this._init(wholenumber, intscale, fracscale);
		}

		public getSign(): string {
			return this._sign;
		}

		public getIntNum(): string {
			return this._intnum;
		}

		get hasDot(): boolean {
			return this._hasDot;
		}

		public getFraction(): string {
			return this._fraction;
		}

		public getNumber(): string {
			return this._sign + this._intnum + ("" == this._fraction ? "" : "." + this._fraction);
		}

		private _init(wholenumber: string, intscale: number, fracscale: number): void {
			if (wholenumber == null || wholenumber.length == 0) {
				return;
			}
			let dotindex: number = wholenumber.indexOf(".");
			if (dotindex > -1) {
				this._parseIntNum(wholenumber.substring(0, dotindex), intscale);
				this._parseFraction(wholenumber.substring(dotindex + 1), fracscale);
				this._hasDot = true;
			} else {
				this._parseIntNum(wholenumber, intscale);
			}
		}

		private _parseIntNum(intnum: string, intscale: number): void {
			if (this._isExponential(Number(intnum))) {
				if (intnum.indexOf("+") == 0) {
					intnum = intnum.replace("+", "");
				}
				intnum = this._convertExponentialToString(new Decimal(intnum));
			}
			let sign: string = "";
			let intnumber: string[] = [];
			for (let i: number = 0; i < intnum.length; i++) {
				let intchar: string = intnum.charAt(i);
				if (intnumber.length == 0) {
					if (/[+-]/.test(intchar)) {
						sign = intchar;
					}
				}
				if (/\d/.test(intchar)) {
					intnumber.push(intchar);
				}
			}
			this._sign = sign;
			let integernum: string = intnumber.join("");
			if (integernum.length > intscale) {
				integernum = integernum.substring(integernum.length - intscale, integernum.length);
			}
			integernum = integernum.replace(/^[0]+/, "0");
			integernum = integernum.replace(/^([0]+)([0^\d])/, "$2");
			this._intnum = integernum;
		}

		private _parseFraction(fraction: string, fracscale): void {
			let frac: string[] = [];
			let fracLen = fraction.length - 1;
			for (let i: number = 0; i < fracscale; i++) {
				if (fracLen < i) {
					break;
				}
				let fracchar: string = fraction.charAt(i);
				if (/\d/.test(fracchar)) {
					frac.push(fracchar);
				}
			}
			let fracnum: string = frac.join("");
			if (fracnum.length > fracscale) {
				fracnum = fracnum.substring(fracnum.length - fracscale, fracnum.length);
			}
			this._fraction = fracnum;
		}

		/**
		 * 지수 표현식 값인지 여부를 확인한다.
		 * @param value 
		 * @returns 
		 */
		private _isExponential(value: number) {
			if (typeof value !== "number") {
				return false;
			}
			return /[eE]/.test(Number(value).toString());
		}

		/**
		 * 현재 decimal 값을 string형으로 반환합니다.
		 * @return 현재 decimal 값의 string형 데이터.
		 */
		private _convertExponentialToString(decimalData: decimal.Decimal): string {
			if (decimalData == null) {
				return null;
			}
			//Decimal.config에서 지수표현 크기에 대해 설정할 수 있음.
			let data: string[] = decimalData.toString().split(/[eE]/);
			if (data.length == 1) {
				return data[0];
			}

			let num: string = data[0];
			let exponential: number = Number(data[1]);

			//양수일때 정수부에 0 삽입
			if (exponential > 0) {
				return decimalData.toFixed(0);
			};

			let part: string[] = num.split(".");
			exponential = Math.abs(exponential) + (part.length == 1 ? 0 : part[1].length); //소수부 갯수

			return decimalData.toFixed(exponential);
		}
	}
}