"use strict"

namespace cpr.protocols.stream {

	/**
	 * @private
	 */
	export class UTF8Stream {
		private _rawData: Uint8Array;
		private _length: number;
		private _idx: number;
		private _lastCharLength: number = 0;


		constructor(vInput: ArrayBuffer) {
			/* the input argument is an arrayBuffer: the buffer will be shared. */
			this._rawData = new Uint8Array(vInput);
			this._length = this._rawData.length;
			this._idx = 0;
		}

		/* CONSTRUCTOR'S METHODS */
		private _loadUTF8CharCode(aChars, nIdx: number) {
			/* The ISO 10646 view of UTF-8 considers valid codepoints encoded by 1-6 bytes, 
			 * while the Unicode view of UTF-8 in 2003 has limited them to 1-4 bytes in order to 
			 * match UTF-16's codepoints. In front of a 5/6-byte sequence StringView tries to 
			 * encode it in any case.
			 */
			let nLen = aChars.length, nPart = aChars[nIdx];
			return nPart > 251 && nPart < 254 && nIdx + 5 < nLen ?
      /* (nPart - 252 << 30) may be not safe in ECMAScript! So...: */
      /* six bytes */ (nPart - 252) * 1073741824 + (aChars[nIdx + 1] - 128 << 24) + (aChars[nIdx + 2] - 128 << 18) + (aChars[nIdx + 3] - 128 << 12) + (aChars[nIdx + 4] - 128 << 6) + aChars[nIdx + 5] - 128
				: nPart > 247 && nPart < 252 && nIdx + 4 < nLen ?
      /* five bytes */ (nPart - 248 << 24) + (aChars[nIdx + 1] - 128 << 18) + (aChars[nIdx + 2] - 128 << 12) + (aChars[nIdx + 3] - 128 << 6) + aChars[nIdx + 4] - 128
					: nPart > 239 && nPart < 248 && nIdx + 3 < nLen ?
      /* four bytes */(nPart - 240 << 18) + (aChars[nIdx + 1] - 128 << 12) + (aChars[nIdx + 2] - 128 << 6) + aChars[nIdx + 3] - 128
						: nPart > 223 && nPart < 240 && nIdx + 2 < nLen ?
      /* three bytes */ (nPart - 224 << 12) + (aChars[nIdx + 1] - 128 << 6) + aChars[nIdx + 2] - 128
							: nPart > 191 && nPart < 224 && nIdx + 1 < nLen ?
      /* two bytes */ (nPart - 192 << 6) + aChars[nIdx + 1] - 128
								:
      /* one byte */ nPart;

		}

		private _getUTF8CharLength(nChar) {
			return nChar < 0x80 ? 1 : nChar < 0x800 ? 2 : nChar < 0x10000 ? 3 : nChar < 0x200000 ? 4 : nChar < 0x4000000 ? 5 : 6;
		}

		/* INSTANCES' METHODS */
		public _makeIndex(nChrLength?: number, nStartFrom?: number) {
			let aTarget = this._rawData, nChrEnd, nRawLength = aTarget.length,
				nStartIdx = nStartFrom || 0, nIdxEnd = nStartIdx, nStopAtChr = isNaN(nChrLength) ? Infinity : nChrLength;

			if (nChrLength + 1 > aTarget.length) {
				throw new RangeError("UTF8StringView.prototype.makeIndex - The offset can\'t be major than the length of the array - 1.");
			}

			for (nChrEnd = 0; nIdxEnd < nRawLength && nChrEnd < nStopAtChr; nChrEnd++) {
				let nPart = aTarget[nIdxEnd];
				nIdxEnd += nPart > 251 && nPart < 254 && nIdxEnd + 5 < nRawLength ? 6
					: nPart > 247 && nPart < 252 && nIdxEnd + 4 < nRawLength ? 5
						: nPart > 239 && nPart < 248 && nIdxEnd + 3 < nRawLength ? 4
							: nPart > 223 && nPart < 240 && nIdxEnd + 2 < nRawLength ? 3
								: nPart > 191 && nPart < 224 && nIdxEnd + 1 < nRawLength ? 2
									: 1;
			}

			if (nChrLength) { return nIdxEnd; }

			return nChrEnd;
		}

		public _getNext(): string {
			if (this._isEnd()) {
				return undefined;
			}
			let charCode: number = this._loadUTF8CharCode(this._rawData, this._idx);
			this._lastCharLength = this._getUTF8CharLength(charCode);
			this._idx += this._lastCharLength;
			let ch: string = String.fromCharCode(charCode);

			return ch;
		}

		public _getCurrent(): string {
			let curIdx: number = 0;
			if (this._idx > 0) {
				curIdx = this._idx - this._lastCharLength;
			}
			let charCode: number = this._loadUTF8CharCode(this._rawData, curIdx);
			let ch: string = String.fromCharCode(charCode);
			return ch;
		}

		public _getPreviousIndex(): number {
			return this._idx - this._lastCharLength;
		}

		public _toPrevious(): void {
			this._idx -= this._lastCharLength;
			this._lastCharLength = 0;
		}

		public _getLength(): number {
			return this._length;
		}

		public _isEnd(): boolean {
			return this._idx >= this._length;
		}

		public _close(): void {
			this._rawData = null;
			this._length = null;
			this._idx = null;
			this._lastCharLength = null;
		}

	}

}