/// <reference path="ResourceLoader.ts"/>
/// <reference path="../geometry/Dimension.ts"/>
namespace cpr.core {
	let log = utils.Logger.forTopic("app")._createBindedLoggerFunction({
		updator: it => log = it
	});

	/**
	 * 앱의 로드 및 초기화 과정에 개입할 수 있는 인터페이스 입니다.
	 */
	export interface AppHook {
		/**
		 * 앱의 로드 요청을 만들 때, 추가 리소스 요청을 포함시킬 수 있습니다.
		 * @param appId 로드할 앱의 ID.
		 * @param loader 리소스 로더.
		 */
		onLoad?(appId: String, loader: ResourceLoader): void;

		/**
		 * 앱 인스턴스가 시작되기 직전에 추가 리소스를 요청할 수 있습니다.
		 * @param app 실행될 앱 인스턴스.
		 * @param loader 리소스 로더.
		 */
		onPrepare?(app: AppInstance, loader: ResourceLoader): void;

		/**
		 * 앱 인스턴스의 모든 구성요소가 만들어진 직후의 동작을 개인화 할 수 있습니다.
		 * @param app 실행될 앱 인스턴스.
		 * @param exports 실행될 앱의 출판 인터페이스. (앱 속성 및 앱 메소드)
		 */
		onCreate?(app: AppInstance, exports: any): void;
	}

	/**
	 * 앱의 인스턴스를 구성하는 델리게이트 입니다.
	 */
	export interface AppDelegate {
		/**
		 * 앱 인스턴스를 만들고 시작하기전에 로드해야 하는 자원들을 기술하는 함수입니다.
		 */
		onPrepare?: (loader: ResourceLoader) => void;

		/**
		 * 앱 인스턴스를 생성하는 방법을 기술하는 함수입니다.
		 */
		onCreate: (app: AppInstance, exports: any) => void;
	}

	const APP_HOOKS: AppHook[] = [];

	/**
	 * 선호크기 없음을 나타내는 내부 변수
	 * @private
	 */
	export var NO_PREFERRED_SIZE = new geometry.Dimension(-1, -1);

	/**
	 * 앱 인스턴스를 만드는 방법을 정의하는 방법을 정의하는 클래스.
	 */
	export class App implements Identifiable, bind.BindablePropertiesOwner {
		/**
		 * https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/7960
		 * 앱 인스턴스의 아이디가 중복되지 않도록 생성 카운트를 세는 필드.
		 */
		private _instanceCount = 0;
		public _delegate: AppDelegate;
		private _id: string;
		private _uuid: string;
		private _focuscyclic: boolean = false;
		private _bindables: bind.BindableProperties;

		// private _parentApp: App;
		private _instances: AppInstance[];
		private _defaultProperties: { [key: string]: any } = {};

		// 앱 캐시를 사용하지 않을 때, 마지막 앱 인스턴스 제거 후, 정리 작업 예약 여부.
		private _isUnloadScheduled = false;

		private _preferredSize: geometry.Dimension = new geometry.Dimension(-1, -1);

		/**
		 * defaults.js 파일에 설정된 "appcache" 설정 값을 리턴합니다.
		 * 기본 값은 true 입니다.
		 */
		public static allowedAppCache(): boolean {
			let appConf: AppConfig = AppConfig.INSTANCE;
			let envConfig: Config = appConf.getEnvConfig();
			let appcache: string | boolean | number = envConfig.getValue("appcache");
			if ((typeof appcache === "string" && appcache === "false")
				|| (typeof appcache === "boolean" && appcache === false)) {
				return false;
			}
			return true;
		}

		/**
		 * 새 앱을 만듭니다.
		 * @param appId 앱의 아이디.
		 * @param delegate 앱의 라이프 사이클을 관리하는 위임자.
		 */
		constructor(appId: string, delegate: AppDelegate);

		/**
		 * 새 앱을 만듭니다.
		 * @param delegate 앱의 라이프 사이클을 관리하는 위임자.
		 */
		constructor(delegate: AppDelegate);
		constructor(idOrDelegate: string | AppDelegate, delegate?: AppDelegate) {
			this._uuid = _generateUUID();
			this._bindables = new bind.BindableProperties(this);
			this._bindables.add("title", "").withSetterValidatorWithType(false, "string");

			let actualId: string;
			let actualDelegate: AppDelegate;

			if (typeof idOrDelegate == "string") {
				actualId = idOrDelegate as string;
				actualDelegate = delegate;
			}
			else {
				actualId = null;
				actualDelegate = idOrDelegate as AppDelegate;
			}

			actualDelegate = _assign({
				onCreate(app: App) {
					throw new exceptions.UnsupportedOperationException("onCreate 는 반드시 작성되어야 합니다.");
				},
				onLoad() { },
			}, actualDelegate);

			this._delegate = actualDelegate;
			this._id = actualId;
			this._instances = [];
		}

		/* Property Start */
		/**
		 * 앱의 아이디
		 */
		get id(): string {
			return this._id;
		}
		/**
		 * 앱의 유니크 아이디
		 */
		get uuid(): string {
			return this._uuid;
		}
		/**
		 * 마지막 포커스에서 처음으로 돌아갈지 여부.
		 * @return
		 */
		get focuscyclic(): boolean {
			return this._focuscyclic;
		}
		/**
		 * 마지막 포커스에서 처음으로 돌아갈지 여부를 설정합니다.
		 * @param focuscyclic
		 */
		set focuscyclic(focuscyclic: boolean) {
			this._focuscyclic = focuscyclic;
		}
		/* Property End */

		/**
		 * 새로운 앱 인스턴스를 만듭니다.
		 */
		createNewInstance(): AppInstance {
			let instance = new AppInstance(this, `${this.id}$${++this._instanceCount}`);
			this._instances.push(instance);
			return instance;
		}

		/**
		 * 이 앱의 실행 인스턴스들을 반환합니다.
		 */
		public getInstances(): AppInstance[] {
			return this._instances;
		}

		/**
		 * 앱 인스턴스 종료를 통보 합니다.
		 * 앱 캐시를 사용하지 않는 경우, 해당 앱 인스턴스가 유일한 실행중인 앱 인스턴스라면 관련 자원이 해지됩니다.
		 * 
		 * @param instance 종료를 통보할 앱 인스턴스.
		 */
		public _removeInstance(instance: AppInstance) {
			let idx = this._instances.indexOf(instance);
			if (idx === -1) {
				return;
			}

			this._instances.splice(idx, 1);

			if (
				// 앱 캐시를 사용하지 않고
				App.allowedAppCache() === false &&
				// 앱 언로딩이 아직 예약되지 않았고
				this._isUnloadScheduled === false &&
				// 실행중인 앱 인스턴스가 더 이상 존재하지 않는다면
				utils.Util.isNullOrEmpty(this._instances)
			) {
				this._scheduleUnload();
				log(`${this.id}의 마지막 앱 인스턴스가 종료되었기 때문에, 언로드를 예약 합니다.`)
			}
		}

		private _scheduleUnload() {
			if (this._isUnloadScheduled) {
				return;
			}
			this._isUnloadScheduled = true;
			DeferredUpdateManager.INSTANCE.asyncExec(() => {
				if (utils.Util.isNullOrEmpty(this._instances)) {
					this.unload();
				}
			});
		}

		/**
		 * 로드 된 앱을 찾습니다. 로드되지 않은 경우, <code>null</code>를 반환합니다.
		 * @param appID 찾을 앱의 ID(URI)
		 */
		public static peek(appID: app_id_string): App {
			let peek = Platform.INSTANCE.lookup(appID);
			if (peek instanceof App) {
				return peek;
			} else {
				return null;
			}
		}

		/**
		 * 앱을 로드 합니다.
		 * @param appURI 앱의 아이디.
		 * @param doneHandler 앱이 로드 완료시 수행되는 콜백. 로드된 앱이 파라미터로 전달됩니다.
		 */
		public static load(appURI: app_id_string, doneHandler?: (loadedApp: core.App) => void): Promise<core.App> {
			if (doneHandler && typeof doneHandler != "function") {
				throw new exceptions.IllegalArgumentException();
			}

			let appURL: utils.URL = new utils.URL(appURI);
			let appID: string = appURL.pathname;

			return new Promise<core.App>((resolve, reject) => {
				function done(app: core.App) {
					if (doneHandler) {
						utils.tryCatch({
							do: () => {
								doneHandler(app);
							},
							_report: true,
							_context: exceptions.ErrorContext.PROMISE
						});

					}
					resolve(app);
				}

				let existingApp: App = App.peek(appID);

				// 앱 캐시를 사용하지 않고, 이미 로드된 앱이 존재하지만 실행중인 앱 인스턴스는 없는 경우, 기존 앱을 무시합니다.
				if (App.allowedAppCache() === false && existingApp && existingApp.hasInstances() === false) {
					existingApp = null;
				}

				if (existingApp == null) {
					let loader = new ResourceLoader();
					loader.addApp(appURI);
					APP_HOOKS.filter(it => it.onLoad instanceof Function).forEach(it => {
						it.onLoad(appID, loader);
					});

					loader.load()
						.then(() => {
							let app = Platform.INSTANCE.lookup(appID) as App;
							done(app || null);
						}).catch((e) => {
							let app = Platform.INSTANCE.lookup(appID) as App;
							done(app || null);
						});
				} else if (existingApp instanceof App) {
					done(existingApp);
				} else {
					reject(new cpr.exceptions.IllegalArgumentException(`${appID} is not an ID for an App.`));
				}
			});
		}

		/**
		 * 속성에 바인드 합니다.
		 * @param name 속성의 이름
		 */
		public bind(name: string): bind.IBindFactory {
			return this._bindables.bind(name);
		}

		/**
		 * 바인딩 가능한 속성인지 확인합니다.
		 * @param name 속성 명
		 * @return 확인 여부.
		 */
		isBindable(name: string): boolean {
			return this._bindables.isBindable(name)
		}

		/**
		 * 해당 속성을 unbind합니다.
		 * @param name unbind할 속성 명.
		 */
		public unbind(name: string) {
			this._bindables.unbind(name);
		}

		/**
		 * 컨트롤의 바인드 속성 정보를 반환합니다.
		 * @param name bind된 속성 명.
		 * @return BindInfo 속성
		 */
		public getBindInfo(name: string): bind.BindInfo {
			let property = this._bindables.getBindableProperty(name);
			if (!property) {
				return null;
			}
			return property.getCurrentBindInfo();
		}

		/**
		 * 앱의 타이틀을 가져옵니다.
		 */
		public get title(): string {
			return this._bindables.get("title");
		}

		/**
		 * 앱의 타이틀을 설정합니다.
		 */
		public set title(newTitle: string) {
			this._bindables.set("title", newTitle);
		}

		/**
		 * 바인드 문맥을 가져옵니다. 
		 * 앱은 바인드 문맥을 지원하지 않으므로 null을 반환합니다.
		 * @private
		 */
		public getBindContext(): bind.BindContext {
			return null;
		}

		/**
		 * 이 앱이 UDC를 위한 앱인지 여부를 반환 합니다.
		 */
		public _isUDC(): boolean {
			return this.id && this.id.indexOf("udc/") === 0;
		}

		/**
		 * 해당 앱의 인스턴스가 존재하는지 여부를 반환합니다.
		 */
		public hasInstances(): boolean {
			return this._instances != null && this._instances.length > 0;
		}

		public _getDefaultProperties() {
			return this._defaultProperties;
		}

		/**
		 * 앱이 실행될 때 필요한 최소 크기 정보를 얻습니다.
		 */
		public getPreferredSize(): geometry.Dimension {
			return this._preferredSize === NO_PREFERRED_SIZE ? null : this._preferredSize;
		}

		/**
		 * 앱 인스턴스 작동에 필요한 최소 크기를 지정합니다.
		 * @param width 최소 너비. 음수의 경우 제약 없음을 나타냅니다.
		 * @param height 최소 높이. 음수의 경우 제약 없음을 나타냅니다.
		 */
		public setPreferredSize(width: number, height: number): void;

		/**
		 * 앱 인스턴스 작동에 필요한 최소 크기를 지정합니다.
		 * @param size 최소 크기
		 */
		public setPreferredSize(size: geometry.Dimension): void;
		public setPreferredSize() {
			let args = _toArray(arguments);
			let newPreferredSize: geometry.Dimension;
			switch (args.length) {
				case 1: {
					let head = args[0];
					if (head == null) {
						newPreferredSize = NO_PREFERRED_SIZE;
					}
					else if (head instanceof geometry.Dimension) {
						newPreferredSize = head.getCopy();
					}
					break;
				}

				case 2: {
					let first = args[0];
					let second = args[1];
					if (typeof first == "number" && typeof second == "number") {
						newPreferredSize = new geometry.Dimension(first, second);
					}
					break;
				}
			}
			if (newPreferredSize == null) {
				throw new exceptions.IllegalArgumentException();
			}

			if (_areEquals(this._preferredSize, newPreferredSize)) {
				return;
			}

			this._preferredSize = newPreferredSize;
		}

		/**
		 * 앱을 언로드 합니다. 실행 중인 인스턴스가 있는 경우, 작동하지 않고 예외가 발생합니다.
		 */
		public unload() {
			let instances = this.getInstances();
			if (instances && instances.length > 0) {
				throw new cpr.exceptions.IllegalStateException("Can't unload app since there are one or more running app instances.")
			}
			Platform.INSTANCE.unregister(this);
			let scriptElement = ResourceLoader._findAppScriptNode(this);
			if (scriptElement) {
				scriptElement.parentElement.removeChild(scriptElement);
			}
			log(`${this.id}가 언로드 되었습니다.`);
		}

		/**
		 * 앱의 로드 및 초기화 과정을 개인화 할 수 있는 훅을 추가합니다.
		 * @param hook 추가할 앱 훅.
		 */
		public static addHook(hook: AppHook) {
			let existingIndex = APP_HOOKS.indexOf(hook);
			if (existingIndex === -1) {
				APP_HOOKS[APP_HOOKS.length] = hook;
			}
		}

		/**
		 * 앱 훅을 제거합니다.
		 * @param hook 제거할 앱 훅.
		 */
		public static removeHook(hook: AppHook) {
			let existingIndex = APP_HOOKS.indexOf(hook);
			if (existingIndex !== -1) {
				APP_HOOKS.splice(existingIndex, 1)
			}
		}

		public static _getPrepareHooks(): ((app: AppInstance, loader: ResourceLoader) => void)[] {
			return APP_HOOKS.filter(it => it.onPrepare instanceof Function)
				.map(it => it.onPrepare);
		}

		public static _getCreateHooks(): ((app: AppInstance, exports: any) => void)[] {
			return APP_HOOKS.filter(it => it.onCreate instanceof Function)
				.map(it => it.onCreate);
		}

	}
}