namespace cpr.vdom {
	/**
	 * 패치의 유형.
	 * 이 타입은 const enum 이므로 런타임에서는 사라지며, 사용자 API로 출판되지 않습니다.
	 */
	export const enum VPatchType {
		NONE, VTEXT, VNODE, WIDGET, PROPS, ORDER, INSERT, REMOVE, THUNK
	}

	/**
	 * @private
	 */
	export class VPatch {
		public type: VPatchType;
		public vNode: VTreeElement;
		public patch: any;

		constructor(type: VPatchType, vNode: VTreeElement, patch: any) {
			this.type = type;
			this.vNode = vNode;
			this.patch = patch;
		}
	}

	export type VPatches = {
		[index: number]: VPatch | VPatch[];
		a: VNode;
	};
}