/// <reference path="../utils/Util.ts" />
/// <reference path="../core/Platform.ts" />
namespace cpr.exceptions {
	/**
	 * 에러의 발생 문맥
	 */
	export enum ErrorContext {
		/**
		 * 오류가 문맥을 특정할 수 없는 경우를 가리킵니다.
		 */
		UNKNOWN = "unknown",
		/**
		 * 사용자 이벤트 리스너가 오류를 일으킨 경우를 나타냅니다.
		 */
		EVENT_LISTENER = "event-listener",

		/**
		 * 컨트롤 렌더링에 실패한 경우를 가리킵니다. 일반적으로 잘못된 설정에서 비롯합니다.
		 */
		RENDERING_FAIL = "rendering-fail",

		/**
		 * 디퍼드 업데이트 매니저에 async()로 예약된 함수가 오류를 일으킨 경우를 가리킵니다.
		 */
		DEFERRED_TASK = "deferred-task",

		/**
		 * 노티피케이션 구독 함수가 오류를 일으킨 경우를 가리킵니다.
		 */
		NOTIFICATION_SUBSCRIBER = "notification-subscriber",

		/**
		 * 익스프레션 실행 도중의 일어난 오류를 가리킵니다.
		 */
		EXPRESSION = "expression",

		/**
		 * 프로미스 then() 구문으로 연결된 함수의 오류를 가리킵니다.
		 */
		PROMISE = "promise",

		/**
		 * 서브미션 처리중에 발생한 에러를 가리킵니다.
		 */
		SUBMISSION = "submission"
	}

	export interface TryCatchOptions {
		do: () => void;
		catch?: (e: any) => void;
		finally?: () => void;
		_report?: boolean;
		_context?: ErrorContext
	}

	/**
	 * 에러 보고 객체입니다.
	 */
	export interface ErrorReport {
		/**
		 * 에러를 감지한 문맥.
		 */
		context: ErrorContext

		/**
		 * 에러 메시지.
		 */
		message: String,

		/**
		 * 전달된 예외 객체.
		 */
		error: any;

		/**
		 * 스택 정보.
		 * 모든 유형의 에러 및 브라우저에서 제공되는 것은 아니며, 브라우저 마다 형식의 차이가 있을 수 있습니다.
		 * 제공되지 않는 경우, <code>null</code>을 반환합니다.
		 */
		stack?: string[],

		/**
		 * 에러가 발생한 시각을 가리킵니다. 이 시각은 클라이언트에 의존적입니다.
		 */
		timestamp: Date
	}

	/**
	 * 에러 리포트를 생성합니다.
	 * @param context 에러 발생 문맥.
	 * @param e 에러 객체.
	 * @private
	 */
	export function _createErrorReport(context: exceptions.ErrorContext, e: any): ErrorReport {
		return {
			context: context,
			message: e ? e.message : null,
			error: e,
			stack: e["stack"] ? (e["stack"] as string).split(/[\r\n]/).map(it => it.trim()) : null,
			timestamp: new Date()
		}
	}
}

namespace cpr.utils {
	const browserName = cpr._detectBrowser().name;
	const isChrome = browserName == "chrome";
	const isSafari = browserName == "safari";
	const isIE = ["ie", "edge"].indexOf(browserName) !== -1;

	interface ErrorLike {
		stack: string,
		message: string
	}

	/**
	 * 단일화된 try-catch 구문을 작성합니다.
	 * 특정 브라우저에서 일반 try-catch 문에 비해 더 빠르게 작동하는데 도움이 될 수 있습니다.
	 * @param options 
	 */
	export function tryCatch(options: exceptions.TryCatchOptions) {
		options = _assign({
			catch(e: any) {
				// 에러로깅
				logError(e);
			},
			finally() { },
			_report: false,
			_kind: exceptions.ErrorContext.UNKNOWN
		}, options);
		try {
			options.do();
		}
		catch (e) {
			options.catch(e);
			if (options._report) {
				core.Platform.INSTANCE._reportError(options._context, e);
			}
		}
		finally {
			options.finally();
		}
	}

	function _formatErrorStack(e: ErrorLike) {
		if (!e.message && !e.stack) {
			return e;
		}

		if (!e.stack) {
			return e.message || e.constructor.name;
		}

		let prefix = "";
		if (e instanceof Error) {
			// 크롬의 경우 자동 포메팅에 의해 컬럼 정보를 날려 먹기 때문에 변형 출력
			if (!isIE) {
				if (isChrome) {
					prefix = " "
				} else if (isSafari && e.message) {
					prefix = e.message + "\n";
				}
			}
		} else {
			prefix = e.message + "\n";
		}

		return prefix + e.stack;
	}

	/**
	 * 로그 수준
	 */
	export enum LogSeverity {
		/**
		 * 오류 
		 */
		ERROR = "error",

		/**
		 * 경고
		 */
		WARN = "warn",

		/**
		 * 정보
		 */
		INFO = "info"
	}

	/**
	 * 오류 로그를 남깁니다.
	 * @param e 오류 객체
	 * @param severity 오류의 수준
	 */
	export function logError(e: any, severity: LogSeverity = LogSeverity.ERROR) {
		if (_isUserError(e)) {
			_logUserError(e);
			return;
		}
		let objToPrint = _formatErrorStack(e as ErrorLike);

		switch (severity) {
			case LogSeverity.ERROR: {
				if (_canUseStylizedConsole()) {
					console.log(`%c${objToPrint}`, "color: red;");
				}
				else {
					console.error(objToPrint);
				}

				break;
			}

			case LogSeverity.WARN: {
				console.warn(objToPrint);
				break;
			}

			case LogSeverity.INFO: {
				console.info(objToPrint);
				break;
			}
		}

	}

	// Error#stack 의 최대 길이 제한 해제.
	// 크롬의 경우 기본 값이 10
	Error["stackTraceLimit"] = 100;

	_registerPlatformInitTask(() => {
		window.onerror = (message, source, line, col, error) => {
			let actualError: Error = null;
			if (error instanceof Error) {
				actualError = error;
			} else if (message instanceof Error) {
				actualError = message as Error;
			} else if (message && message instanceof ErrorEvent || message["error"] instanceof Error) {
				actualError = message["error"] as Error;
			}
			if (actualError) {
				logError(actualError);
				core.Platform.INSTANCE._reportError(exceptions.ErrorContext.UNKNOWN, actualError);
			}
		}

		window.onunhandledrejection = (e: PromiseRejectionEvent) => {
			if (e.reason) {
				let reason = e.reason;
				// reason이 CancelationException 인 경우 의도적으로 중단한 것으로 보고 log를 skip 함.
				if (reason instanceof exceptions.CancelationException) {
					e.preventDefault();
					return false;
				}

				// 서브미션 이벤트 리젝션의 경우, 별도 로그가 표시되므로 무시.
				else if (reason instanceof events.CSubmissionEvent) {
					// logError(reason.cause, LogSeverity.INFO);
					e.preventDefault();
					return false;
				}

				else {
					logError(e.reason, LogSeverity.WARN);
					core.Platform.INSTANCE._reportError(exceptions.ErrorContext.PROMISE, e["reason"]);
					e.preventDefault();
					return false;
				}
			} else {
				return true;
			}
		}
	});
}