namespace cpr.core {
	/**
	 * 계층 구조를 갖는 키 패스를 바탕으로 값을 지정하거나 얻을 수 있는 설정 객체.
	 */
	export class Config {
		private _config: {};

		constructor() {
		}

		protected _initConfig(config: {} = {}): void {
			this._config = config;
		}

		/**
		 * 설정된 값 중 전달된 경로 하위의 설정을 조회하여 리턴한다.
		 * 만약 경로의 값이 Map 형태가 아닌 값일 경우 선택된 값만 가지는 Config 객체를 리턴한다.
		 * 
		 * @param path 조회할 값의 경로, "."으로 구분하여 계층적으로 경로를 기술한다. 예) linkedlistbox.className
		 * @return path로 넘겨 받은 경로 하위의 설정에 접근할 수 있는 새로운 Config 객체 리턴
		 * @see cpr.core.Config
		 */
		public getConfig(path: string): Config {
			let configObj: {} = this._searchSubConfig(path);
			let subConfig: Config = new Config();
			subConfig._initConfig(configObj);

			return subConfig;
		}

		/**
		 * 설정된 값 중 전달된 경로 하위의 설정 값을 조회하여 리턴한다.
		 * 만약 경로의 값이 Map 형태인 경우 string 타입으로 casting 하여 리턴한다.
		 * 
		 * @param path 조회할 값의 경로, "."으로 구분하여 계층적으로 경로를 기술한다. 예) linkedlistbox.className
		 * @param alt 설정 값.
		 * @return path로 넘겨 받은 경로의 설정 값 리턴
		 */
		public getValue(path: string, alt: string | boolean | number = null): string {
			return this._searchValue(path, alt);
		}

		/**
		 * 설정된 값 중 전달된 경로 하위의 값을 설정합니다.
		 * @param path 조회할 값의 경로, "."으로 구분하여 계층적으로 경로를 기술한다.예) linkedlistbox.className
		 * @param value 설정 할 값.
		 */
		public setValue(path: string, value: string | boolean | number): void {
			let configObj: {} = this._config;
			let paths: string[] = path.split(".");
			for (let i: number = 0; i < paths.length; i++) {
				if (paths[i] == "") {
					continue;
				}
				if (i == paths.length - 1) {
					configObj[paths[i]] = value;
					return;
				}
				let obj: {} | string = configObj[paths[i]];
				if (obj == null) {
					obj = {};
					configObj[paths[i]] = obj;
				}
				configObj = obj;
			}
		}

		/**
		 * App의 설정 값을 JSON 형태로 전환하여 반환합니다.
		 * @return JSON 형태의 설정 값.
		 */
		public toJSON(): {} {
			return _deepCopyObject(this._config);
		}

		/* helper methods */
		private _searchSubConfig(path: string): {} {
			let configObj: {} = this._config;
			let paths: string[] = path.split(".");
			for (let i: number = 0; i < paths.length; i++) {
				if (paths[i] == "") {
					continue;
				}
				let obj: {} | string | boolean | number = configObj[paths[i]];
				if (obj == null) {
					obj = {};
					configObj[paths[i]] = obj;
					configObj = obj as {};
				} else if (typeof obj === "object") {
					configObj = obj as {};
				} else {
					let newObj: {} = {};
					newObj[paths[i]] = obj;
					return newObj;
				}
			}

			return configObj;
		}

		private _searchValue(path: string, alt: string | boolean | number): string {
			let configObj: {} = this._config;
			if (!configObj) {
				return alt as string;
			}
			let paths: string[] = path.split(".");
			for (let i: number = 0; i < paths.length; i++) {
				if (paths[i] == "") {
					continue;
				}
				configObj = configObj[paths[i]];
				if (configObj == null) {
					return alt as string;
				}
			}

			return configObj as string;
		}

	}

	/**
	 * Control별 기본 값 및 공통 정의된 상수 값을 조회할 수 있는 클래스.<br/>
	 * Usage:<br/>
	 * <pre><code>
	 * let config: cpr.core.Config = cpr.core.AppConfig.INSTANCE.getControlConfig("linkedlistbox");
	 * let headerHeight: string = config.getValue("headerHeight", "20px");
	 * let space: string = config.getValue("space", "20px");
	 * let direction: string = config.getValue("direction", "right");
	 * ...
	 * </code></pre>
	 */
	export class AppConfig extends Config {
		private static _instance: AppConfig;

		private readonly _GLOBALNAME: string = "CPR_DEFAULTS";

		private readonly _LAYOUTS_NODE: string = "layouts";
		private readonly _CONTROLS_NODE: string = "controls";
		private readonly _PROTOCOL_NODE: string = "protocol";
		private readonly _DATA_NODE: string = "data";
		private readonly _ENV_NODE: string = "environment";
		private readonly _VARIABLE_NODE: string = "variables";

		/**
		 * Singletone 객체
		 */
		static get INSTANCE() {
			if (AppConfig._instance == null) {
				AppConfig._instance = new AppConfig();
			}
			return AppConfig._instance;
		}

		// singleton test start (only test)
		private _chkVar: number; // singleton test
		/**
		 * @private
		 */
		set chkVar(chkVar: number) {
			this._chkVar = chkVar;
		}
		/**
		 * @private
		 */
		get chkVar() {
			return this._chkVar;
		}
		// singleton test end (only test)


		/**
		 * 별도의 객체생성은 할 수 없고 Singleton 으로 만 접근 가능.
		 * 
		 * @see cpr.core.DefaultVars#INSTANCE
		 */
		constructor() {
			super();
			if (AppConfig._instance != null) {
				return AppConfig._instance;
			}
			this._init();
		}

		/**
		 * 설정 중 controls 하위에 설정된 값을 조회한다.
		 * 
		 * @param path 조회할 값의 경로, "."으로 구분하여 계층적으로 경로를 기술한다. 예) linkedlistbox.className
		 * @return path로 넘겨 받은 경로 하위의 설정에 접근할 수 있는 새로운 Config 객체 리턴
		 * @see cpr.core.Config
		 */
		public getControlConfig(path: string = ""): Config {
			return this.getConfig(this._concatPath(this._CONTROLS_NODE, path));
		}
		/**
		 * control의 속성,스타일 등 값을 지정합니다.
		 * @param name 속성의 이름
		 * @param value 속성의 값
		 */
		public setControlValue(name: string, value: string): void {
			this.setValue(this._concatPath(this._CONTROLS_NODE, name), value);
		}

		/**
		 * 설정 중 layouts 하위에 설정된 값을 조회한다.
		 * 
		 * @param path 조회할 값의 경로, "."으로 구분하여 계층적으로 경로를 기술한다. 예) verticallayout.scrollable
		 * @return path로 넘겨 받은 경로 하위의 설정에 접근할 수 있는 새로운 Config 객체 리턴
		 * @see cpr.core.Config
		 */
		public getLayoutConfig(path = ""): Config {
			return this.getConfig(this._concatPath(this._LAYOUTS_NODE, path))
		}

		/**
		  * layouts 하위에 값을 지정합니다.
		  * @param keyPath 속성 경로 표현식.
		  * @param value 속성의 값.
		  */
		public setLayoutValue(keyPath: string, value: any): void {
			this.setValue(this._concatPath(this._LAYOUTS_NODE, keyPath), value);
		}

		/**
		 * 설정 중 protocol 하위에 설정된 값을 조회한다.
		 * 
		 * @param path 조회할 값의 경로, "."으로 구분하여 계층적으로 경로를 기술한다. 예) linkedlistbox.className
		 * @return path로 넘겨 받은 경로 하위의 설정에 접근할 수 있는 새로운 Config 객체 리턴
		 * @see cpr.core.Config
		 */
		public getProtocolConfig(path: string = ""): Config {
			return this.getConfig(this._concatPath(this._PROTOCOL_NODE, path));
		}

		/**
		 * protocol 하위에 값을 지정합니다.
		 * @param name 속성의 이름.
		 * @param value 속성의 값.
		 */
		public setProtocolValue(name: string, value: string): void {
			this.setValue(this._concatPath(this._PROTOCOL_NODE, name), value);
		}

		/**
		 * 설정 중 data 하위에 설정된 값을 조회한다.
		 * 
		 * @param path 조회할 값의 경로, "."으로 구분하여 계층적으로 경로를 기술한다. 예) linkedlistbox.className
		 * @return path로 넘겨 받은 경로 하위의 설정에 접근할 수 있는 새로운 Config 객체 리턴
		 * @see cpr.core.Config
		 */
		public getDataConfig(path: string = ""): Config {
			return this.getConfig(this._concatPath(this._DATA_NODE, path));
		}
		/**
		 * data 하위에 값을 설정합니다.
		 * @param name 속성의 이름
		 * @param value 속성의 값
		 */
		public setDataValue(name: string, value: string): void {
			this.setValue(this._concatPath(this._DATA_NODE, name), value);
		}

		/**
		 * 설정 중 environment 하위에 설정된 값을 조회한다.
		 * 
		 * @param path 조회할 값의 경로 또는 속성명. 사용가능한 속성명은 {@link EnvConfigScheme}을 참조 하십시오.
		 * @return path로 넘겨 받은 경로 하위의 설정에 접근할 수 있는 새로운 Config 객체 리턴
		 * @see cpr.core.Config
		 */
		public getEnvConfig(path: string = ""): Config {
			return this.getConfig(this._concatPath(this._ENV_NODE, path));
		}

		/**
		 * enviroment 하위에 값을 설정합니다.
		 * @param name 속성의 이름. 사용가능한 속성명은 {@link EnvConfigScheme}을 참조 하십시오.
		 * @param value 속성의 값.
		 */
		public setEnvValue(name: string, value: string): void {
			this.setValue(this._concatPath(this._ENV_NODE, name), value);
		}

		/**
		 * 설정 중 variables 하위에 설정된 값을 조회한다.
		 * 
		 * @param path 조회할 값의 경로, "."으로 구분하여 계층적으로 경로를 기술한다. 예) linkedlistbox.className
		 * @return path로 넘겨 받은 경로 하위의 설정에 접근할 수 있는 새로운 Config 객체 리턴
		 * @see cpr.core.Config
		 */
		public getVarConfig(path: string = ""): Config {
			return this.getConfig(this._concatPath(this._VARIABLE_NODE, path));
		}

		/**
		 * variables 하위에 값을 설정합니다.
		 * @param name 속성의 이름.
		 * @param value 속성의 값.
		 */
		public setVarValue(name: string, value: string): void {
			this.setValue(this._concatPath(this._VARIABLE_NODE, name), value);
		}

		/* helper methods */
		private _init(): void {
			if (typeof window[this._GLOBALNAME] == "undefined") {
				this._initConfig({});
			} else {
				this._initConfig(window[this._GLOBALNAME]);

				window[this._GLOBALNAME] = undefined;

				utils.tryCatch({
					do: () => {
						delete window[this._GLOBALNAME];
					}
				})
			}
		}

		private _concatPath(parentPath: string, subPath: string): string {
			return parentPath + "." + subPath;
		}

	}

	export interface EnvConfigScheme {
		/**
		 * 가능한 경우 최상위 그룹에서 브라우저 기본 스크롤 기능을 사용하도록 합니다.
		 * 기본값은 <code>true</code> 입니다. 
		 * 브라우저 기본 뷰포트 스크롤 대신 DIV 엘리먼트 내 스크롤 동작을 사용하기 위해 <code>false</code>로 지정할 수 있습니다.
		 */
		preferNativeScroll: boolean;

		/**
		 * 브라우저 및 운영체제 기본 스크롤바 대신 커스텀 스크롤 바를 사용합니다.
		 * 스크롤바의 모양을 통제할 수 있지만 성능에 영향을 줄 수 있습니다.
		 * 기본값은 <code>false</code> 입니다.
		 */
		useCustomScrollbar: boolean;

		/**
		 * 이미 로드된 앱을 캐시할 것인지 여부를 지정합니다.
		 * 기본값은 <code>true</code>입니다.
		 */
		appcache: boolean;

		/**
		 * I18n을 통해 메시지를 쿼리할 때 해당 값이 존재하지 않는다면 메시지 대신 키를 표시할 것인지 여부를 지정합니다.
		 * 기본값은 <code>false</code> 입니다.
		 */
		useKeyInsteadOfNullI18NMessage: boolean;

		/**
		 * 컨트롤을 나타내는 DOM 노드를 생성할 때 노드의 ID로 컨트롤의 UUID를 이용 할 것인지 여부를 지정합니다.
		 * 기본값은 <code>true</code>입니다.
		 * @deprecated {@link useControlUUIDasHTMLId} 및 {@link htmlIdGenMethod} 대신 하나의 통합된 {@link uuidGenMethod} 속성을 사용하십시오.
		 */
		useControlUUIDasHTMLId: boolean;

		/**
		 * {@link useControlUUIDasHTMLId}가 <code>false</code>로 지정된 경우, ID 생성 방법을 별도로 지정합니다.
		 * @deprecated
		 */
		htmlIdGenMethod: ufc.HtmlIdGenMethod

		/**
		 * 컨트롤들이 렌더링된 HTML 노드들의 ID를 생성하는 방식을 결정합니다.
		 * 기본값은 SECURE 입니다.
		 * 이 값이 지정되면 {@link useControlUUIDasHTMLId} 및 {@link htmlIdGenMethod} 보다 우선 합니다.
		 */
		uuidGenMethod: ufc.UUIDGenMethod
	}
}