namespace cpr.utils {
	let instance: FileDialog;
	/**
	 * 파일 다이얼로그
	 * @private
	 */
	export class FileDialog {

		private _elementId: string;
		private _onChangeFileHandler: (files: File[]) => void

		public static get INSTANCE() {
			if (!instance) {
				instance = new FileDialog();
			}
			return instance;
		}

		private _onChangeFile(e: Event) {
			let input = e.target as HTMLInputElement;
			this._onChangeFileHandler(_toArray(input.files));

			core.DeferredUpdateManager.INSTANCE.asyncExec(() => {
				input.type = "text";
				input.value = ""; // type이 file일때 IE10에서는 동작하지 않음. 
				input.type = "file";
			});
		}

		/**
		 * 파일다이얼로그를 엽니다.
		 * @param option 
		 * @param handler 
		 */
		public open(option: { multiple?: boolean, accept?: string } = {}, handler: (files: File[]) => void) {
			let fileElement: HTMLInputElement = null;
			if (!this._elementId) {
				this._elementId = `uuid-${_generateUUID()}`;
				fileElement = document.createElement("input");
				fileElement.type = "file";
				fileElement.style.display = "none";
				fileElement.id = this._elementId;
				fileElement.addEventListener("change", (e: Event) => { this._onChangeFile(e) })
				document.body.appendChild(fileElement);
			} else {
				fileElement = document.getElementById(this._elementId) as HTMLInputElement;
			}

			if (!fileElement) {
				return;
			}

			_defaults(option, { multiple: false, accept: "" });

			for (let key in option) {
				switch (key) {
					case "accept": {// 웹표준 검사기(https://validator.w3.org/)에서 이 속성이 빈 값인 경우 오류로 표시함.
						if (!option[key]) {
							fileElement.removeAttribute(key); // 이 속성은 값이 없는 경우를 설정하려면 속성을 삭제해야 DOM에서 제거된다.
							break;
						}
					}
					default:
						fileElement[key] = option[key];
				}
			}
			this._onChangeFileHandler = handler;
			fileElement.click();
		}
	}
}