/// <reference path="./ItemListProvider.ts"/>

namespace cpr.controls.item {
	/**
	 * @private
	 */
	export class ComboBoxItemListProvider extends ItemListProvider<ComboBox, TreeItem, TreeItemSetConfig, TreeItemFilter> implements ITreeItemListProvider {
		private _treeItemListView: TreeItemListView;

		/**
		 * ComboBox용 아이템 리스트 프로바이더를 생성합니다.
		 * @param owner 소유자 ComboBox 컨트롤
		 */
		constructor(owner: ComboBox, itemAdapter: ItemListAdapter<TreeItem>) {
			super(owner, itemAdapter);
			this.getItemListView().setValidatorType(ControlItemValidatorType.comboBoxItem);
			let treeItemList = new TreeItemList(owner, this.getItemDataSource(), itemAdapter);
			this._treeItemListView = new TreeItemListView(owner, treeItemList, this._getItemFilter());
		}

		/**
		 * 콤보박스의 드롭다운 타입을 반환합니다.
		 * @returns 드롭다운 타입
		 */
		private _getDropDownType(): ComboBoxDropDownType {
			return this._getOwner().dropDownType;
		}

		/**
		 * 트리 아이템 리스트 뷰를 반환합니다.
		 * @returns 
		 */
		public getTreeItemListView(): TreeItemListView {
			return this._treeItemListView;
		}

		/**
		 * 트리 아이템 리스트를 반환합니다.
		 * @returns 
		 */
		public getTreeItemList(): TreeItemList {
			return this._treeItemListView.itemList;
		}
		/**
		 * 드롭다운타입에 따른 활성 아이템 리스트 뷰를 반환합니다.
		 * @returns 
		 */
		public getActiveItemListView(): IItemListView<TreeItem> {
			if (this._getDropDownType() === "tree") {
				return this.getTreeItemListView();
			} else {
				return this.getItemListView();
			}
		}
		/**
		 * 드롭다운타입에 따른 활성 아이템 리스트를 반환합니다.
		 * @returns 
		 */
		public getActiveItemList(): IItemList<TreeItem> {
			if (this._getDropDownType() === "tree") {
				return this.getTreeItemList();
			} else {
				return this.getItemList();
			}
		}
		/**
		 * 리소스를 해제합니다.
		 */
		public dispose(): void {
			this._treeItemListView?.dispose();
			this._treeItemListView = null;
			super.dispose();
		}
	}
}
