namespace cpr.exceptions {
	const CHROME_IE_STACK_REGEXP = /^\s*at .*(\S+:\d+|\(native\))/m;
	const SAFARI_NATIVE_CODE_REGEXP = /^(eval@)?(\[native code])?$/;

	type Location = [uri: string, line: string | undefined, column: string | undefined];
	export type StackFrame = {
		functionName?: string,
		fileName?: string,
		lineNumber?: string,
		columnNumber?: string,
		source?: string
	};

	/**
	 * Given an Error object, extract the most information from it.
	 *
	 * @param {Error} error object
	 * @return {Array} of StackFrames
	 */
	export function _parseErrorStack(error: Error): StackFrame[] {
		if (error.stack && error.stack.match(CHROME_IE_STACK_REGEXP)) {
			return _parseV8OrIE(error);
		} else if (error.stack) {
			return _parseFFOrSafari(error);
		} else {
			throw new Error('Cannot parse given Error object');
		}
	}

	// Separate line and column numbers from a string of the form: (URI:Line:Column)
	function _extractLocation(urlLike: string): Location {
		// Fail-fast but return locations like "(native)"
		if (urlLike.indexOf(':') === -1) {
			return [urlLike, undefined, undefined];
		}

		let regExp = /(.+?)(?::(\d+))?(?::(\d+))?$/;
		let parts = regExp.exec(urlLike.replace(/[()]/g, ''));
		return [parts[1], parts[2] || undefined, parts[3] || undefined];
	}

	function _parseV8OrIE(error: Error): StackFrame[] {
		let filtered = error.stack.split('\n').filter(function (line) {
			return !!line.match(CHROME_IE_STACK_REGEXP);
		});

		return filtered.map(line => {
			if (line.indexOf('(eval ') > -1) {
				// Throw away eval information until we implement stacktrace.js/stackframe#8
				line = line.replace(/eval code/g, 'eval').replace(/(\(eval at [^()]*)|(,.*$)/g, '');
			}
			let sanitizedLine = line.replace(/^\s+/, '').replace(/\(eval code/g, '(').replace(/^.*?\s+/, '');

			// capture and preseve the parenthesized location "(/foo/my bar.js:12:87)" in
			// case it has spaces in it, as the string is split on \s+ later on
			let location = sanitizedLine.match(/ (\(.+\)$)/);

			// remove the parenthesized location from the line, if it was matched
			sanitizedLine = location ? sanitizedLine.replace(location[0], '') : sanitizedLine;

			// if a location was matched, pass it to extractLocation() otherwise pass all sanitizedLine
			// because this line doesn't have function name
			let locationParts = _extractLocation(location ? location[1] : sanitizedLine);
			let functionName = location && sanitizedLine || undefined;
			let fileName = ['eval', '<anonymous>'].indexOf(locationParts[0]) > -1 ? undefined : locationParts[0];

			return {
				functionName: functionName,
				fileName: fileName,
				lineNumber: locationParts[1],
				columnNumber: locationParts[2],
				source: line
			};
		});
	}

	function _parseFFOrSafari(error: Error): StackFrame[] {
		let filtered = error.stack.split('\n').filter(function (line) {
			return !line.match(SAFARI_NATIVE_CODE_REGEXP);
		});

		return filtered.map(line => {
			// Throw away eval information until we implement stacktrace.js/stackframe#8
			if (line.indexOf(' > eval') > -1) {
				line = line.replace(/ line (\d+)(?: > eval line \d+)* > eval:\d+:\d+/g, ':$1');
			}

			if (line.indexOf('@') === -1 && line.indexOf(':') === -1) {
				// Safari eval frames only have function names and nothing else
				return {
					functionName: line
				};
			} else {
				let functionNameRegex = /((.*".+"[^@]*)?[^@]*)(?:@)/;
				let matches = line.match(functionNameRegex);
				let functionName = matches && matches[1] ? matches[1] : undefined;
				let locationParts = _extractLocation(line.replace(functionNameRegex, ''));

				return {
					functionName: functionName,
					fileName: locationParts[0],
					lineNumber: locationParts[1],
					columnNumber: locationParts[2],
					source: line
				};
			}
		});
	}
}