/// <reference path="./GridBand.ts"/>

namespace cpr.controls.gridpart {
	/**
	 * @noinstance
	 */
	export class GridRowGroupBand extends GridBand {
		private _groupBy: string;

		/**
		 * @private
		 */
		constructor(context: GridContext, bandType: string, groupBy: string) {
			super(context, bandType);
			this._groupBy = groupBy;
		}

		/**
		 * 컨트롤의 스타일 설정을 반환합니다.
		 * <a href="cpr.controls.UIControl.html#style">cpr.data.UIControl.style</a>참고
		 */
		get style(): GridStyler {
			return this._getBand().bandStyler;
		}

		protected _getBand(): GridRowGroupBandConfig {
			let rowgroups: GridRowGroupConfig[] = this._getContext().getRowGroup();
			if (rowgroups == null || rowgroups.length == 0) {
				return null;
			}
			let band: GridRowGroupBandConfig = null;
			rowgroups.some((rgConfig: GridRowGroupConfig) => {
				if (this._groupBy == rgConfig.groupCondition) {
					band = rgConfig[this._getBandType()];
					return true;
				}
			});
			return band;
		}

		/**
		 * 특정 셀을 반환합니다.
		 * @param cellIndex 셀 인덱스.
		 * @return 입력받은 셀 인덱스의 셀.
		 */
		public getColumn(cellIndex: number): GridRowGroupColumn {
			let gridColumn: GridRowGroupColumn = null;
			let cellProps: GridFooterCellProp[] = this._getBand().cellProp;
			cellProps.some((cell: GridFooterCellProp) => {
				if (cell.constraint.cellIndex == cellIndex) {
					gridColumn = new GridRowGroupColumn(this._getContext(), cell);
					return true;
				}
			});
			return gridColumn;
		}

		/**
		 * 해당 정보에 맞는 GridColumn 배열을 반환합니다.
		 * @param colIndex 찾고자 하는 컬럼의 colIndex.
		 * @param colSpan 찾고자 하는 컬럼의 colSpan.
		 * @return 해당 정보에 맞는 GridColumn 배열.
		 */
		public getColumnByColIndex(colIndex: number, colSpan: number): GridRowGroupColumn[] {
			let cellProps: GridFooterCellProp[] = [].concat(this._getBand().cellProp);
			let resultColumns: GridRowGroupColumn[] = [];
			cellProps.forEach((cellProp: GridFooterCellProp) => {
				if (cellProp.constraint.colIndex == colIndex && cellProp.constraint.colSpan == colSpan) {
					resultColumns[resultColumns.length] = new GridRowGroupColumn(this._getContext(), cellProp);
				}
			});
			return resultColumns;
		}

		public setRowHeights(heights: number[]): void {
			let grid: Grid = this._getContext().getGrid();
			let bandConfig: GridBandConfig = this._getBand();
			if (bandConfig.rows.length != heights.length) {
				return;
			}

			bandConfig.rows.forEach((row: { rowIndex: number, height: number }, index: number) => {
				row.height = heights[index];
			})
			grid._needRowGroupReset();
			grid.redraw();
		}

	}
}