/// <reference path="../utils/StringUtil.ts" />

namespace cpr.protocols {
	/**
	 * Http POST 메소드를 이용하여 서버에 컨텐츠를 요청할 수 있는 클래스입니다.
	 * 서버로 전송되는 최종 URL은 Submission의 URL 처리 규칙을 준수합니다.<br/>
	 * @example
	 * window.open("about:blank", "_popup", "height=300,left=100,top=100,width=350,location=no,menubar=no,resizable=no,scrollbars=yes,status=yes,titlebar=no,toolbar=no");
	 * var postMethod = new cpr.protocols.HttpPostMethod("jsp/sample.jsp", "_popup"); // default.js에 protocol/submission/contextPath 가 설정된 경우 URL 앞에 설정된 값이 추가됩니다.
	 * postMethod.addParameter("name", "홍길동");
	 * postMethod.addParameter("age", "27");
	 * postMethod.addParameter("address", "서울 영등포");
	 * postMethod.addParameter("country", "한국");
	 * postMethod.submit();
	 * postMethod.dispose();
	 * 
	 * @fires cpr.events.CSubmissionEvent#before-submit 서버로 메시지를 전송하기 전에 발생합니다.
	 * 
	 * @fires cpr.events.CSubmissionEvent#submit-done 서버로 메시지를 전송한 후 발생합니다.
	 * 
	 * @fires cpr.events.CEvent#dispose HttpPostMethod가 dispose 되기 직전 발생합니다. 
	 */
	export class HttpPostMethod implements resources.IDisposable, events.IEventTarget {
		private static readonly _formname: string = "form_" + _generateUUID(); // form

		private _eventTable: cpr.events.EventTable;

		private _isDisposed: boolean = false;
		private _actionUrl: string;
		private _target: string;

		private _param: cpr.utils.EntrySet<string>;


		/**
		 * HTTP Post 메소드로 서버에 컨텐츠를 요청할 HttpPostMethod 객체를 생성합니다.
		 * @param actionUrl 호출할 서버의 URL. actionUrl이 0-9a-z 로 시작하고 http로 시작하지 않을 때 default.js protocol/submission/contextPath 가 설정된 경우 actionUrl 앞에 설정된 값이 추가됩니다.
		 * @param target 결과를 출력할 target의 이름으로 팝업 윈도우의 이름이거나 iframe 요소인 경우 현재 브라우저에 출력된 화면에서 유일한 이름이어야 합니다.
		 */
		constructor(actionUrl: string, target: string) {
			this._actionUrl = actionUrl;
			this._target = target;

			this._param = new cpr.utils.EntrySet<string>();
			this._eventTable = new events.EventTable();
		}

		/**
		 * 컨트롤의 제거 여부를 반환합니다.
		 * @return 컨트롤의 제거 여부.
		 */
		public get disposed(): boolean {
			return this._isDisposed;
		}

		/**
		 * 컨트롤에 포함되어있는 객체들을 제거합니다.
		 */
		public dispose(): void {
			if (this._isDisposed) {
				return;
			}

			let disposeEvent = new cpr.events.CEvent("dispose");
			this.dispatchEvent(disposeEvent);

			if (this._eventTable) {
				this._eventTable.removeAllEventListeners();
				this._eventTable = null;
			}

			this._actionUrl = null;
			this._target = null;
			this._param = null;

			this._isDisposed = true;
		}

		/**
		 * 전송시 추가로 전달되는 파라미터를 추가합니다.
		 * @param name 파라미터의 이름
		 * @param value 파라미터의 값
		 */
		public addParameter(name: string, value: string): void {
			this._checkDisposed();
			if (name == null || name == "") {
				throw new cpr.exceptions.IllegalArgumentException("param name");
			}
			value = (value == null ? "" : value);
			this._param.push({
				key: name,
				value: value
			});
		}

		/**
		 * 전송시 추가로 전달되는 파라미터를 설정합니다.
		 * @param name 파라미터의 이름
		 * @param value 파라미터의 값들
		 */
		public setParameters(name: string, value: string[] | string): void {
			this._checkDisposed();
			if (name == null || name == "") {
				throw new cpr.exceptions.IllegalArgumentException("param name");
			}
			this._param.remove(name);
			if (_isArray(value)) {
				(value as string[]).forEach((val: string) => {
					val = (val == null ? "" : val);
					this.addParameter(name, val);
				});
			} else {
				value = (value == null ? "" : value);
				this.addParameter(name, value as string);
			}
		}

		/**
		 * 파라미터의 값들을 반환합니다.
		 * @param name 파라미터의 이름
		 * @return 파라미터 배열.
		 */
		public getParameters(name: string): string[] {
			this._checkDisposed();
			if (name == null || name == "") {
				return [];
			}
			let values: string[] = this._param.getValues(name);
			return values == null ? [] : values;
		}

		/**
		 * 파라미터의 이름들을 반환합니다.
		 * @return 파라미터 명의 배열.
		 */
		public getParameterNames(): string[] {
			this._checkDisposed();
			return this._param.getKeys();
		}

		/**
		 * 파라미터의 이름에 해당되는 값들을 모두 삭제합니다.
		 * @param name 파라미터의 이름
		 * @return 제거된 파라미터 값의 배열.
		 */
		public removeParameters(name: string): string[] {
			this._checkDisposed();
			if (name == null || name == "") {
				return;
			}
			let values: string[] = this.getParameters(name);
			this._param.remove(name);
			return values;
		}

		/**
		 * 파라미터를 전부 제거합니다.
		 */
		public removeAllParameters(): void {
			this._checkDisposed();
			this._param.clear();
		}

		// cpr.events.IEventTarget begin
		/**
		 * 컨트롤에 EventType 별 Listener를 추가합니다.<br>
		 * 컨트롤에 특정 Event가 발생했을 때 처리하는 Listener를 추가합니다.
		 * <pre><code>var button = new cpr.controls.Button("btn01");
		 * button.addEventListener("click", function(e) {
		 * 	// event code...
		 * });
		 * </code></pre>
		 * 
		 * @param type 이벤트 타입.
		 * @param listener 이벤트 리스너.
		 */
		addEventListener(type: string, listener: (e: cpr.events.CEvent) => void): void {
			this._checkDisposed();
			this._eventTable.addEventListener(type, listener);
		}

		/**
		 * 컨트롤에 EventType 별 Listener를 제거합니다.<br>
		 * <pre><code>control.removeEventListener('click', listener);</code></pre>
		 * @param type 이벤트 타입.
		 * @param listener 이벤트 리스너.
		 */
		removeEventListener(type: string, listener: (e: cpr.events.CEvent) => void): void {
			this._checkDisposed();
			this._eventTable.removeEventListener(type, listener);
		}

		/**
		 * 컨트롤의 모든 이벤트 Listener를 제거합니다.
		 */
		removeAllEventListeners(): void {
			this._checkDisposed();
			this._eventTable.removeAllEventListeners();
		}

		/**
		 * 특정 이벤트를 전달합니다.
		 * @param e 이벤트
		 * @return 이벤트 전달 성공 여부.
		 */
		dispatchEvent(e: events.CEvent): boolean {
			this._checkDisposed();
			let processContinue: boolean = events.EventBus.INSTANCE._dispatchEvent(e, this);
			// 이벤트 핸들러 동작 중 Control이 dispose 되었을 때 다음 처리를 중단한다.
			if (processContinue == true && this.disposed == true) {
				processContinue = false;
			}
			if (processContinue) {
				processContinue = this._eventTable.dispatchEvent(e);
			}
			return processContinue;
		}
		// cpr.events.IEventTarget end

		/**
		 * 서버로 HTTP 요청을 전송합니다.
		 */
		public submit(): void {
			this._checkDisposed();
			let submissionEvent: events.CSubmissionEvent = new cpr.events.CSubmissionEvent(events.SubmissionEventType.BEFORE);
			submissionEvent._prepareWithTarget(this);
			let processContinue: boolean = this.dispatchEvent(submissionEvent);
			if (processContinue == false) {
				return;
			}

			let formTag: HTMLFormElement = this._getFormElement();
			let paramNames: string[] = this.getParameterNames();
			paramNames.forEach((name: string) => {
				let values: string[] = this.getParameters(name);
				this._addParameter(formTag, name, values);
			});

			formTag.submit();

			// clear
			let parentElement: HTMLElement = formTag.parentElement;
			parentElement.removeChild(formTag);
			formTag = null;

			submissionEvent = new cpr.events.CSubmissionEvent(events.SubmissionEventType.DONE);
			submissionEvent._prepareWithTarget(this);
			this.dispatchEvent(submissionEvent);
		}

		private _getFormElement(): HTMLFormElement {
			let formTag: HTMLFormElement = document.getElementById(HttpPostMethod._formname) as HTMLFormElement;
			if (!formTag) {
				formTag = document.createElement("form") as HTMLFormElement;
				formTag.id = HttpPostMethod._formname;
				formTag.method = "post";
				formTag.enctype = Submission.MEDIA_URLENCODED;
				formTag.setAttribute("name", HttpPostMethod._formname);
				formTag.setAttribute("accept-charset", "utf-8");

				document.body.appendChild(formTag);
			}

			// 상대경로일 때 submission의 context를 이용
			let actionUrl: string = this._actionUrl;
			if (/^[a-z0-9]/i.test(actionUrl) == true && /^http/i.test(actionUrl) == false) {
				let config: core.Config = core.AppConfig.INSTANCE.getProtocolConfig("submission");
				if (config) {
					let contextPath: string = config.getValue("contextPath");
					if (contextPath) {
						actionUrl = contextPath + actionUrl;
					}
				}
			}

			formTag.action = actionUrl;
			formTag.target = this._target;

			return formTag;
		}

		private _addParameter(formTag: HTMLFormElement, name: string, values: string[]): void {
			values.forEach((value: string) => {
				let inputTag: HTMLInputElement = document.createElement("input") as HTMLInputElement;
				inputTag.type = "hidden";
				inputTag.name = name;
				inputTag.value = value;
				formTag.appendChild(inputTag);
			});
		}

		private _checkDisposed(): void {
			if (this.disposed) {
				throw new exceptions.DisposeException();
			}
		}

	}
}