namespace cpr.utils {
	export class JSONParser {
		public static readonly _nfirstChars: string = '-0123456789.';
		public static readonly _nchars: string = '-0123456789.eE';

		private _str: string;
		private _strLength: number;
		private _idx: number;


		constructor() {
		}

		public parse(str: string): {} {
			this._str = str;
			this._strLength = str.length;
			this._idx = 0;

			let res: any = this._parseValue();

			this._str = null;
			this._strLength = null;
			this._idx = null;

			return res;
		}

		private _isWhiteSpace(c: string): boolean {
			return c == ' ' || c == '\r' || c == '\n' || c == '\t';
		}

		private _skipWhiteSpace(): void {
			while (this._idx < this._strLength && this._isWhiteSpace(this._str.charAt(this._idx))) {
				this._idx++;
			}
		}

		private _parseValue(): any {
			this._skipWhiteSpace();
			if (this._idx == this._strLength) {
				return null;
			}
			let c: string = this._str.charAt(this._idx);
			if (c === '{') return this._parseObject();
			else if (c === '[') return this._parseArray();
			else if (c === '\"') return this._parseString('\"');
			else if (c === '\'') return this._parseString('\'');
			else if (JSONParser._nfirstChars.indexOf(c) != -1) return this._parseNumber();
			else if (c === 't') return this._parseLiteral('true', true);
			else if (c === 'f') return this._parseLiteral('false', false);
			else if (c === 'n') return this._parseLiteral('null', null);
			else if (c === 'N') return this._parseLiteral('NaN', NaN);
			else if (c === 'u') return this._parseLiteral('undefined', undefined);
			throw "Invalid JSON";
		}

		private _parseLiteral(literal: string, value: any): any {
			if (literal.length > this._strLength - this._idx) {
				throw "Expecting " + literal;
			}
			for (let i: number = 0; i < literal.length; i++) {
				if (literal.charAt(i) != this._str.charAt(this._idx++)) {
					throw "Expecting" + literal;
				}
			}
			return value;
		}

		private _parseNumber(): Number | string {
			let startIndex: number = this._idx;
			while (JSONParser._nchars.indexOf(this._str.charAt(this._idx)) != -1) {
				let cha: string = this._str.charAt(this._idx);
				this._idx++;
				if (cha === 'e' || cha === 'E') {
					cha = this._str.charAt(this._idx);
					if (cha === '-' || cha === '+') {
						this._idx++;
					}
				}
			}
			let numberValue: string = this._str.substring(startIndex, this._idx);
			if (numberValue.length <= 15) {
				return Number(numberValue);
			} else {
				return numberValue; // support decimal type
			}
		}

		private _parseString(quote: string): string {
			this._idx++;
			let c: string;
			var s: string[] = [];
			while ((c = this._str.charAt(this._idx)) != quote) {
				if (c === '\\') {
					this._idx++;
					c = this._str.charAt(this._idx);
					if (c == 'r') s[s.length] = '\r';
					else if (c == 'n') s[s.length] = '\n';
					else if (c == 't') s[s.length] = '\t';
					else if (c == 'f') s[s.length] = '\f';
					// Note escaped unicode not handled
					else s[s.length] = c;
				} else s[s.length] = c;
				this._idx++;
			}
			this._idx++;
			let res: string = s.join("");
			s = null;
			return res;
		}

		private _parseObject(): {} {
			this._idx++;
			this._skipWhiteSpace();
			if (this._str.charAt(this._idx) === '}') {
				this._idx++;
				return {};
			}
			let o: {} = {};
			let c: string;
			while (true) {
				let name: string = this._parseValue() as string;
				this._skipWhiteSpace();
				c = this._str.charAt(this._idx);
				if (c !== ':') throw "Expecting :";
				this._idx++;
				this._skipWhiteSpace();
				let value: any = this._parseValue();
				this._skipWhiteSpace();
				o[name] = value;
				c = this._str.charAt(this._idx);
				if (c === ',') {
					this._idx++;
					this._skipWhiteSpace();
				} else break;
			}
			if (c !== '}') {
				throw "Expecting }" + this._str.substring(this._idx);
			}
			this._idx++;
			return o;
		}

		private _parseArray(): any[] {
			this._idx++;
			this._skipWhiteSpace();
			if (this._str.charAt(this._idx) === ']') {
				this._idx++;
				return [];
			}
			let a: any[] = [];
			let c: string;

			while (true) {
				let value: any = this._parseValue();
				a[a.length] = value;
				this._skipWhiteSpace();
				c = this._str.charAt(this._idx);
				if (c === ',') {
					this._idx++;
					this._skipWhiteSpace();
				} else break;
			}
			if (c !== ']') {
				throw "Expecting ] ";
			}
			this._idx++;
			return a;
		}

	}
}