/// <reference path="./layouts/VerticalLayout.ts" />
/// <reference path="./layouts/FlowLayout.ts" />
/// <reference path="./layouts/XYLayout.ts" />
/// <reference path="./layouts/ResponsiveXYLayout.ts" />
/// <reference path="./layouts/FormLayout.ts" />
/// <reference path="./Container.ts" />


namespace cpr.controls {
	let log = utils.Logger.forTopic("ocpr")._createBindedLoggerFunction({
		updator: it => log = it
	});

	interface ModificationRequest {
		index: number;
		child: UIControl;
		constraint?: any;
	}

	/**
	 * 그룹의 자식 추가 삭제를 빠르게 처리하는 피스 렌더러가 렌더링을 진행하는 동안 레이아웃과 통신하기 위한 프로토콜 객체.
	 * @private
	 */
	export interface OCPRSession {
		/**
		 * 데이터 맵을 얻음.
		 */
		_getAllData(): { [key: string]: any };
		_getData<T>(key: string): T;
		_putData(key: string, value: any): void;

		/**
		 * 특정 컨트롤에 대한 draw()를 요청.
		 * 최적화 렌더링이 수행되기전이나 기각된 상태에서 호출하면 예외가 발생 함.
		 * 피스 렌더링 도중 이미 처리되었거나, 그룹에 포함되지 않은 요소인 경우 기각 됨.
		 * @param control 
		 */
		_requestRender(control: UIControl): void;

		/**
		 * 피스렌더러를 통한 렌더링 여부를 반환.
		 * false 반환시 최적화 렌더링 대신 일반 렌더링이 작동한 경우.
		 */
		_isRendered(): boolean;
	}
	/**
	 * @private
	 */
	export class OCPRSessionImpl implements OCPRSession {
		_parent: OptimizedChildrenPieceRender;
		_data: { [key: string]: any };
		_rendered: boolean;
		_drawnControls: { [key: string]: boolean };

		constructor(pieceRenderer: OptimizedChildrenPieceRender) {
			this._parent = pieceRenderer;
			this._data = {};
			this._rendered = false;
			this._drawnControls = {};
		}

		public _getAllData() {
			return this._data;
		}

		public _isRendered(): boolean {
			return this._rendered;
		}

		public _putData(key: string, value: any) {
			this._data[key] = value;
		}

		public _getData<T>(key: string): T {
			return this._data[key] as T;
		}

		public _requestRender(control: UIControl) {
			if (!this._rendered) {
				throw new exceptions.IllegalStateException("최적화 렌더링이 이뤄진 이후에만 호출 가능합니다.");
			}

			if (!control || control.disposed) {
				return;
			}

			if (this._drawnControls[control.uuid] || this._parent._shouldAcceptDrawRequest(control)) {
				log("후처리 렌더링 요청 기각 됨.");
				return;
			}

			control._getRenderer().draw();
			log(`후처리 렌더링 수락: ${control.uuid}`);
			this._drawnControls[control.uuid] = true;
		}

		/**
		 * 최적화 렌더링 됨을 마크
		 */
		public _markRendered() {
			this._rendered = true;
		}

		public _reset() {
			this._data = {};
			this._rendered = false;
			this._drawnControls = {};
		}
	}

	/**
	 * 특정 컨테이너에 자식 컨트롤을 추가하거나 삭제한 경우의 컨테이너 전체를 새로 그리지 않고 최적화 렌더링을 수행하는 피스 렌더러.
	 * @private
	 */
	export class OptimizedChildrenPieceRender implements ufc.PieceRenderer {
		/**
		 * 소유 컨테이너.
		 */
		private _container: Container;

		/**
		 * 자식 추가 요청
		 */
		private _insertRequests: ModificationRequest[] = [];

		/**
		 * 자식 삭제 요청.
		 */
		private _deleteRequests: ModificationRequest[] = [];

		private _targetLayout: layouts.Layout<any>;
		private _session = new OCPRSessionImpl(this);
		private _redrawScheduled = false;

		/**
		 * 요청된 자식 컨트롤들의 UUID들에 대해 true가 지정되는 룩업 맵.
		 */
		private _modificationFlags: { [key: string]: boolean } = {};
		private _participatiblity: boolean = undefined;

		constructor(container: Container) {
			this._container = container;
		}

		/**
		 * 최적화 피스 렌더러의 상태를 모두 제거.
		 */
		private _reset() {
			this._insertRequests = [];
			this._deleteRequests = [];
			this._modificationFlags = {};
			this._session._reset();
		}

		/**
		 * 특정 자식에 대한 그리기 요청이 이 최적화 렌더러에 의해 필요한 동작인지 여부를 판단.
		 * @param child 
		 */
		public _shouldAcceptDrawRequest(child: UIControl) {
			if (!child || child.disposed || child.getParent() !== this._container) {
				return false
			}
			return this._modificationFlags[child.uuid];
		}

		/**
		 * 피스 렌더링 취소 시점의 콜백 (부모 그룹이 직접 그려짐.)
		 */
		_clear() {
			log(`${this._container.uuid}에 대한 자식 피스 렌더링이 취소 됨.`);

			// 레이아웃에 최적화 렌더링 취소 통보.
			if (this._targetLayout._onOCPRFinish) {
				this._targetLayout._onOCPRFinish(this._session);
			}
			this._reset();
		}

		_contains(other: ufc.PieceRenderer): boolean {
			return other instanceof OptimizedChildrenPieceRender && other._container === this._container;
		}

		_hasPart(other: core.Drawable): boolean {
			return this._insertRequests.some(it => {
				return it.child._containsDrawble(other);
			});
		}

		_render(renderer: ufc.ControlRenderer): void {
			log(`${this._container.uuid}에 대한 자식 피스 렌더링 시작`);
			if (this._targetLayout._onOCPRAboutRender) {
				this._targetLayout._onOCPRAboutRender(this._session);
			}

			this._redrawScheduled = false;

			let layout = this._targetLayout;
			let info = layout._getRenderedLayoutInfo();

			let parentRenderer = this._container._getRenderer();
			let contentPaneNode = parentRenderer.getNamedNode(info.contentPaneNodeName);

			// 삭제된 컨트롤 처리.
			this._deleteRequests.forEach(it => {
				if (it.child.disposed) {
					return;
				}
				let childRenderer = it.child._getRenderer();
				if (childRenderer.disposed || childRenderer.hasDrawn() === false) {
					return;
				}
				let childRootNode = childRenderer._getRenderedRootNode();
				if (childRootNode && childRootNode.parentElement == contentPaneNode) {
					contentPaneNode.removeChild(childRootNode);
				}
			});
			log(`${this._deleteRequests.length}개의 삭제 요청 처리.`)

			// 추가될 컨트롤들의 연속 구간 세그멘테이션 처리 
			let segmentations: ModificationRequest[][] = [];
			let lastKnownReq: ModificationRequest = null;
			let currentSegmentation = null;

			// 삭제된 것들을 걸러내고 인덱스 순서로 정렬.
			let sortedRequest = this._insertRequests.filter(it => {
				return it.child.getParent() == this._container;
			}).sort((a, b) => {
				return a.index - b.index;
			});
			sortedRequest.forEach(it => {
				// 연속된 요청인지 여부.
				let isContinuos = lastKnownReq != null && lastKnownReq.index + 1 == it.index;
				if (isContinuos) {
					currentSegmentation[currentSegmentation.length] = it;
				}
				else {
					currentSegmentation = [it];
					segmentations[segmentations.length] = currentSegmentation;
				}
				lastKnownReq = it;
			});

			log(`${this._insertRequests.length}개의 추가 요청이 ${segmentations.length}개로 세그먼트화 됨.`);
			segmentations.forEach(eachSeg => {
				let childRenderers = eachSeg.map(it => {
					let renderer = it.child._getRenderer();
					// 레이아웃 데코레이션.
					renderer.addLayoutDecorator(layout._createLayoutDecorator(it.child));
					return renderer;
				});
				renderer.insert(info.contentPaneNodeName, eachSeg[0].index + info.offsetIndexForChildren, childRenderers);
			});

			// 레이아웃에 최적화 렌더링 결과 통보.
			this._session._markRendered();
			if (layout._onOCPRFinish) {
				layout._onOCPRFinish(this._session);
			}

			this._reset();
			log(`${this._container.uuid}에 대한 자식 피스 렌더링 종료`);
		}

		/**
		 * 자식 컨트롤 추가 렌더링을 요청합니다.
		 * 최적화 수행 가능 여부가 반환 됩니다.
		 * 
		 * @param index 추가할 인덱스.
		 * @param child 추가잘 자식 컨트롤.
		 * @param constraint 컨스트레인트.
		 */
		public _insert(index: number, child: UIControl, constraint: any): boolean {
			if (!this._canParticipate(child, constraint, true)) {
				return false;
			}
			this._scheduleInsert({
				child: child,
				index: index,
				constraint: constraint
			});
			return true;
		}

		/**
		 * 자식 컨트롤 삭제를 요청합니다.
		 * 최적화 수행 가능 여부가 반환 됩니다.
		 * 
		 * @param child 삭제할 자식.
		 * @param index 삭제 시점의 자식의 인덱스.
		 */
		public _delete(child: UIControl, index: number): boolean {
			if (!this._canParticipate(child, this._container.getConstraint(child), false)) {
				return false;
			}
			this._schduleDelete({
				child: child,
				index: index,
				constraint: null
			})
			return true;
		}

		/**
		 * 최적화 렌더링 수행 가능 여부를 계산합니다.
		 */
		private _computeParticipatibility(): boolean {
			if (this._container == null || this._container.disposed) {
				return false;
			}

			// 혹시 모를 탭 폴더 및 기타 컨테이너의 오동작 방지.
			if (this._container.constructor != Container) {
				return false;
			}

			// 그려진 적이 없다면 피스 렌더러를 통한 최적화가 불필요!
			if (!this._container._getRenderer().hasDrawn()) {
				return false;
			}

			return true;
		}

		/**
		 * 주어진 자식 컨트롤 수정에 대해 최적화 랜더링 가능 여부 반환.
		 */
		private _canParticipate(child: UIControl, constraint: any, isAdd: boolean): boolean {
			if (this._participatiblity === undefined || this._participatiblity === null) {
				this._participatiblity = this._computeParticipatibility();
			}

			if (this._participatiblity === false) {
				return false;
			}

			// 요청이 중첩된 자식 컨트롤이 있으면 최적화 포기.
			if (this._modificationFlags[child.uuid]) {
				log(`중복된 자식 수정으로 최적화 랜더링을 포기함.`)
				this._participatiblity = false;
				return false;
			}

			let layout = this._container.getLayout();
			return layout._shouldOCPRParticipateChild(child, constraint, isAdd);
		}

		/**
		 * 자식 추가를 스케쥴 함.
		 * @param req 
		 */
		private _scheduleInsert(req: ModificationRequest) {
			this._insertRequests.filter(it => {
				return it.index >= req.index
			}).forEach(it => {
				it.index += 1;
			});

			this._insertRequests[this._insertRequests.length] = req;
			this._modificationFlags[req.child.uuid] = true;
			this._scheduleRedrawIfNeeded()
		}

		/**
		 * 자식 삭제를 스케쥴 함.
		 * @param req 
		 */
		private _schduleDelete(req: ModificationRequest) {
			this._insertRequests.filter(it => {
				return it.index >= req.index
			}).forEach(it => {
				it.index -= 1;
			});

			this._deleteRequests[this._deleteRequests.length] = req;
			this._modificationFlags[req.child.uuid] = true;
			this._scheduleRedrawIfNeeded()
		}

		/**
		 * 필요한 경우, 최적화 피스 렌더러를 예약 함.
		 * 레이아웃이 최적화 렌더링 세션에 관련된 API를 구현했다면 관련 콜백이 전달 됩니다.
		 */
		private _scheduleRedrawIfNeeded() {
			if (!this._redrawScheduled) {
				this._container._applyPiece(this);

				// 이 시점에 레이아웃이 확정 됨, 추후 레이아웃이 변경된다면, 피스렌더러 자체가 기각된다.
				this._targetLayout = this._container.getLayout();

				if (this._targetLayout._onOCPRInit) {
					// 레이아웃에게 최적화 렌더링이 수행되려 함을 알림.
					this._targetLayout._onOCPRInit(this._session);
				}

				this._redrawScheduled = true;
			}
		}
	}
}