/// <reference path="../../data/tabledata/RowState.ts"/>


namespace cpr.protocols.request {
	/**
	 * @private
	 */
	export abstract class AbstractRequestBuilder implements RequestBuilder {
		/**
		 * JSONRequestObject를 서버로 전송할 때 Parameter 기반 프로토콜에서 사용할 ParameterName.
		 * 서버와 연동하기 위한 인터페이스로 변경 불가.
		 */
		public static readonly REQOBJ_PARAMNAME: string = "_JSONOBJ_";

		private _dataSeq: number;
		private _dataDelimiter: string[];

		public static _getJsonString(value: {} | string): string {
			let jsonstring: string = null;
			if (typeof value == "string") {
				jsonstring = value;
			} else if (value != null) {
				jsonstring = JSON.stringify(value);
			} else {
				jsonstring = "";
			}
			return jsonstring;
		}

		constructor() {
			this._submitInit();
		}

		public build(submission: AbstractSubmission): any {
			if (submission instanceof Submission == false) {
				throw new exceptions.IllegalArgumentException("cpr.protocols.Submission");
			}

			let result: any = this._buildSpecific(submission as Submission);

			this._submitInit();

			return result;
		}

		public abstract getContentType(): string;
		protected abstract _buildSpecific(submission: Submission): any;

		protected _createDataDelimiter(): string {
			let dataDelimiter: string = "@d" + (this._dataSeq++) + "#";
			this._dataDelimiter.push(dataDelimiter);

			return dataDelimiter;
		}

		// protected _getDataDelimiters(): string[] {
		// 	return [].concat(this._dataDelimiter);
		// }

		protected _getDataDelimiterParamName(): string {
			return "@d#";
		}

		protected _convertRowState(rowState: data.tabledata.RowState): string {
			switch (rowState) {
				case data.tabledata.RowState.INSERTED: {
					return "i";
				}
				case data.tabledata.RowState.DELETED: {
					return "d";
				}
				case data.tabledata.RowState.UPDATED: {
					return "u";
				}
				case data.tabledata.RowState.INSERTDELETED:
				case data.tabledata.RowState.UNCHANGED:
				default: {
					return null;
				}
			}
		}

		protected _getRequestAlias(requestData: RequestData): string {
			let alias: string = requestData.alias;
			if (alias == null || alias == "") {
				alias = requestData.data.id;
			}
			return alias;
		}

		protected _loadPayload(submission: Submission, dataSet: data.DataSet, payload: PayloadType, rowHandler: (rowdata: data.RowConfigInfo, additionalParam: { [key: string]: string }, stateText: string) => void): void {
			let dataSetRowData: { [state: number]: data.tabledata.RowData[] } = null;
			let rowStates: data.tabledata.RowState[] = null;

			let columnNames: string[] = dataSet.getColumnNames(data.header.HeaderType.ORIGINAL_COLUMN);
			let colNmIdx: { [key: string]: number } = {};
			columnNames.forEach((colNm: string, index: number, names: string[]) => {
				let colIdx: number = dataSet._getColumnIndex(colNm);
				colNmIdx[colNm] = colIdx;
			});

			if (payload == PayloadType.all) {

				let rowDatas: cpr.data.tabledata.RowData[] = dataSet._getUnfilteredAllRowDatas();
				for (let rowidx: number = 0; rowidx < rowDatas.length; rowidx++) {
					let rowData: data.tabledata.RowData = rowDatas[rowidx];
					let stateText: string = this._convertRowState(rowData.state);

					let additionalParam: { [key: string]: string } = submission._handleDataRow(dataSet, rowData, colNmIdx);

					let rowConfigInfo: data.RowConfigInfo = this._convertToRowConfigInfo(colNmIdx, rowData);
					rowHandler(rowConfigInfo, additionalParam, stateText);
				}

			} else {
				/* default modified */
				dataSetRowData = dataSet._getUnfilteredRowDatas(data.tabledata.RowState.MODIFIED);
				rowStates = [
					data.tabledata.RowState.INSERTED,
					data.tabledata.RowState.UPDATED,
					data.tabledata.RowState.DELETED
				];
				if (dataSetRowData == null) {
					return;
				}

				rowStates.forEach((rowState: data.tabledata.RowState) => {
					let rowDatas: data.tabledata.RowData[] = dataSetRowData[rowState];
					if (rowDatas == null || rowDatas.length == 0) {
						return;
					}
					let stateText: string = this._convertRowState(rowState);
					for (let rowidx: number = 0; rowidx < rowDatas.length; rowidx++) {
						let rowData: data.tabledata.RowData = rowDatas[rowidx];

						let additionalParam: { [key: string]: string } = submission._handleDataRow(dataSet, rowData, colNmIdx);

						let rowConfigInfo: data.RowConfigInfo = this._convertToRowConfigInfo(colNmIdx, rowData);
						rowHandler(rowConfigInfo, additionalParam, stateText);
					}
				});
			}
		}

		private _convertToRowConfigInfo(colNmIdx: { [key: string]: number }, rowData: data.tabledata.RowData): data.RowConfigInfo {
			let resultRowData: data.RowConfigInfo = {};
			for (let colNm in colNmIdx) {
				let colIdx: number = colNmIdx[colNm];
				resultRowData[colNm] = rowData.getValue(colIdx);
			}

			return resultRowData;
		}

		private _submitInit(): void {
			this._dataSeq = 1;
			if (this._dataDelimiter) {
				this._dataDelimiter.splice(0, this._dataDelimiter.length);
			} else {
				this._dataDelimiter = [];
			}
		}


	}

}