namespace cpr.controls.provider {
	/**
	 * @private
	 */
	export class ImageAreaDataBinder extends AbstractListDataBinder<ImageAreaItem, ImageAreaItemSetConfig, ImageAreaDataProvider> {
		constructor(image: controls.Image) {
			super(image);
		}

		protected _createDataProvider(): ImageAreaDataProvider {
			return new ImageAreaDataProvider(this.getOwner() as controls.Image)
		}

		// 이미지 컨트롤은 아이템에 의해 값이 결정 되지 않으므로 false 반환.
		_shouldConfigureBindablePropertiesOfOwner() {
			return false;
		}
	}
}