/// <reference path="./layout/ScrollPane.ts"/>
/// <reference path="./IGridPart.ts"/>
/// <reference path="./../ControlType.ts"/>


namespace cpr.controls.gridpart {

	/**
	 * @private
	 */
	export class GridHeader extends AbstractGridPart {
		private static readonly _DRAGGABLE_CONTROL_TYPE: string[] = [ControlType.INPUTBOX, ControlType.COMBOBOX, ControlType.DATEINPUT, ControlType.FILEINPUT, ControlType.MASKEDITOR, ControlType.NUMBEREDITOR, ControlType.SEARCHINPUT, ControlType.TEXTAREA];

		constructor(context: GridContext, region: string, bandLayout: GridRegionLayout) {
			super(region, GRIDREGION.HEADER, context, bandLayout);
		}

		public _getContentHeight(): number {
			return this._layout.rowHeight;
		}

		/* Shape */
		protected _doCreateShape(): ufc.ControlShape {
			let context: GridContext = this._getContext();
			let grid: Grid = context.getGrid();
			let bindContext: bind.GridEmbeddedContext = grid.getBindContext() as bind.GridEmbeddedContext;
			let autoFit: string = context._getRegionAutoFit(this.region); //context.autoFit;
			let clientWidth: number = this._scrollPane._getViewportWidth();
			let regionColWidth: { contentWidth: number, layout: { width: number }[] } = GridUtil._createRegionColWidth(autoFit, clientWidth, this._layout.columnLayout);
			{
				let colWidthLayout: { width: number }[] = regionColWidth.layout;
				let columnLayout: GridColumnProp[] = this._layout.columnLayout;
				for (let i: number = 0; i < colWidthLayout.length; i++) {
					columnLayout[i].renderedWidth = colWidthLayout[i].width;
				}
			}
			let headerHeight: number = this._getContentHeight();

			let heights: number[] = [];
			this._layout.rows.forEach((rowInfo: { rowIndex: number, height: number }) => {
				heights.push(rowInfo.height);
			});

			// header
			let headerShape: ufc.ElementShape = {
				tag: "div",
				attr: {},
				classNames: [GridContext.CLS_CELL_INHERIT],
				style: {
					position: "relative",
					border: "0"
				},
				children: []
			};
			headerShape.style["height"] = headerHeight + "px";
			if (autoFit !== "none" && clientWidth > regionColWidth.contentWidth) {
				headerShape.style["width"] = clientWidth + "px";
			} else {
				headerShape.style["width"] = regionColWidth.contentWidth + "px";
			}


			heights.forEach((rowHeight: number, idx: number) => {
				let rowShape: ufc.ElementShape = {
					tag: "div",
					classNames: [GridStyle.ROW],
					attr: {
						role: GRIDROLE.ROW
					},
					style: {
						// position: "absolute",
						// top: "0px",
						// left: "0px",
						overflow: "visible",
						width: "100%",
						height: rowHeight + "px"
					},
					children: []
				};
				GridUtil._setAria(rowShape, "rowindex", utils.Util.toString(idx + 1));
				headerShape.children[idx] = rowShape;
			});


			// let ariaColCount: number = 1;
			let cellPositionRange: { start: number, end: number } = (this._scrollPane as layout.ScrollPane)._getRenderCellRange();
			let visibleColIndices: number[] = grid.getColIndicesByVisible(true);

			this._layout.cellProp.forEach((colProp: GridHeaderCellProp) => {

				// visible에 상관없이 text 값을 지정하기 위함. (181018 hyeran)
				let text: string | ufc.StyledString = this._getText(colProp);
				let textStr: string = ufc.StyledString._asString(text);
				if (colProp.configuration.control != null) {
					if ((colProp.configuration.text != null && colProp.configuration.text != "") ||
						(colProp.configuration.getBindInfo("text") != null)) {
						colProp.configuration.control.value = textStr;
						text = colProp.configuration.control.value;
					}
				}

				let cellLayout: { visible: boolean, colSpan: number } = context._getVisibleColumn(colProp);
				if (cellLayout.visible == false) {
					return;
				}

				let regionColWidth: { contentWidth: number, layout: { width: number }[] } = GridUtil._createRegionColWidth(autoFit, clientWidth, this._layout.columnLayout);
				let realCellStyles: { style: { [key: string]: string }, bound: { left: number, top: number, width: number, mergeCellWidth: number, height: number } }
					= GridUtil._createCellStyle(regionColWidth.layout, colProp, colProp, heights, true);
				if (GridUtil._isContainedCell(realCellStyles.bound, cellPositionRange) === false) {
					return;
				}

				let beforeHeaderCellIndex: number = bindContext._getHeaderCellIndex();
				bindContext._setHeaderCellIndex(colProp.constraint.cellIndex);
				let cellConfiguration: config.GridHeaderCellConfigurator = colProp.configuration;
				let cellShape: ufc.ElementShape = {
					tag: "div",
					attr: {
						role: GRIDROLE.COLUMN_HEADER,
						"data-role": GRIDROLE.COLUMN_HEADER,
						// "aria-colindex": "" + (ariaColCount++),
						"data-cellindex": "" + colProp.constraint.cellIndex,
						tabindex: "-1"
					},
					classNames: _.union([GridStyle.CELL, GridContext.CLS_CELL_INHERIT]
						, (cellConfiguration) ? cellConfiguration.style.getClasses() : []),
					style: GridUtil._createCellStyle(regionColWidth.layout, colProp, colProp, heights).style,
					children: []
				};
				cpr.ufc.ShapeUtil._setAriaState(cellShape, { enabled: grid.enabled, readOnly: grid.readOnly });
				GridUtil._setAria(cellShape, "sort", "none");
				{ // aria-colspan, aria-rowspan
					let cellConst: GridCellConstraint = colProp.constraint;
					if (cellConst.colSpan > 1) {
						GridUtil._setAria(cellShape, "colspan", utils.Util.toString(cellConst.colSpan));
					}
					if (cellConst.rowSpan > 1) {
						GridUtil._setAria(cellShape, "rowspan", utils.Util.toString(cellConst.rowSpan));
					}
				}
				{ // fieldLabel
					let labelString: string[] = [];
					if (utils.Util.isNullOrEmpty(colProp.configuration.control?.fieldLabel) == false) {
						labelString[labelString.length] = "" + colProp.configuration.control.fieldLabel;
					} else if (utils.Util.isNullOrEmpty(colProp.configuration.fieldLabel) == false) {
						labelString[labelString.length] = "" + colProp.configuration.fieldLabel;
					}
					labelString[labelString.length] = textStr;
					ufc.ShapeUtil._setAriaLabelAttr(cellShape.attr, labelString.join(" "));
				}

				let isFirstColumn: boolean = colProp.constraint.colIndex == visibleColIndices[0];
				let isLastColumn: boolean = colProp.constraint.colIndex + colProp.constraint.colSpan - 1 == visibleColIndices[visibleColIndices.length - 1];
				if (isFirstColumn || isLastColumn) {
					if (cellShape.classNames == null) {
						cellShape.classNames = [];
					}
					if (isFirstColumn) {
						cellShape.classNames.push(ufc.Classes.FIRST_COLUMN);
					}
					if (isLastColumn) {
						cellShape.classNames.push(ufc.Classes.LAST_COLUMN);
					}
				}


				// rowShape.children.push(cell);
				(headerShape.children[colProp.constraint.rowIndex] as ufc.ElementShape).children.push(cellShape);

				let cellHeight: utils.Size = utils.ParamUtil.parseSize(cellShape.style["height"]);
				let colHeight: number = cellHeight.size;
				let maxColHeight: number = GridContext._getCellMaxHeight(colHeight);
				if (colHeight == 0) {
					cellShape.style["display"] = "none";
				}

				// sortable column 일때
				if (cellConfiguration.sortColumnName != null && (cellConfiguration.targetColumnName == null || cellConfiguration.sortable == false)) {
					cellShape.attr["data-sortindex"] = cellConfiguration.sortColumnName.toString();
					cellShape.children[cellShape.children.length] = this._createSortableDiv(colProp, cellShape, colHeight);
				}

				let headerCell: ufc.ElementShape = {
					tag: "div",
					attr: {},
					classNames: [GridContext.CLS_CELL_INHERIT],
					style: {
						overflow: "hidden",
						height: maxColHeight + "px" // 내부 컨트롤에 높이를 지정하기 위해 필요. (2017.9.27)
					},
					children: []
				};

				/* 상명대 요구사항 20180602 start */
				if (cellConfiguration.targetColumnName != null) {
					let targetColumnName: string = cellConfiguration.targetColumnName.toString(); // DB 컬럼명을 그대로 노출하는 것은 좋지 않음
					cellShape.attr["data-target"] = targetColumnName;

					// filterable
					if (cellConfiguration.filterable === true) {
						cellShape.children[cellShape.children.length] = {
							tag: "div",
							attr: {
								"data-role": GRIDROLE.FILTER_BUTTON
							},
							classNames: grid._isFiltered(targetColumnName) === true ? ["cl-filter", "cl-filtered"] : ["cl-filter"],
							style: {
								float: "right",
								height: maxColHeight + "px"
							}
						}
					}

					// sortable
					if (cellConfiguration.sortable === true) {
						headerCell.classNames[headerCell.classNames.length] = "cl-sortable-cell";
						headerCell.attr["data-role"] = GRIDROLE.SORTABLE_CELL;

						let sortInfo: { colNm: string, asc: boolean, idx: number } = grid._getMultiSortInfo(targetColumnName);
						let sortSeq: string = "";
						if (sortInfo != null) {
							let sortOrder: string = null;
							sortSeq = (sortInfo.idx + 1) + "";
							if (sortInfo.asc === true) {
								sortOrder = "cl-sort-asc";
								GridUtil._setAria(cellShape, "sort", "ascending");
							} else {
								sortOrder = "cl-sort-desc";
								GridUtil._setAria(cellShape, "sort", "descending");
							}
							headerCell.classNames[headerCell.classNames.length] = sortOrder;
						}

						// 싱글소트가 적용되어 있을 때(조건이 하나일 때) 순번을 숨김 처리
						let sortCondition: { colNm: string, asc: boolean }[] = grid._getGridSort();
						if (sortCondition.length == 1) {
							sortSeq = "";
						}
						let sortIcon = {
							tag: "div",
							attr: {},
							classNames: ["cl-sort-icon"],
							style: { height: "50%" }
						};
						GridUtil._setAria(sortIcon, "hidden", "true");
						let sortSequence = {
							tag: "div",
							attr: {},
							classNames: ["cl-sort-seq"],
							style: { height: "50%" },
							children: [sortSeq]
						}
						GridUtil._setAria(sortSequence, "hidden", "true");

						headerCell.children[headerCell.children.length] = {
							tag: "div",
							attr: {},
							classNames: ["cl-sort"],
							style: {
								float: "right",
								height: maxColHeight + "px",
								"white-space": "pre"
							},
							children: [sortIcon, sortSequence]
						};
					}
				}
				/* 상명대 요구사항 20180602 end */

				headerCell.children[headerCell.children.length] = this._createContainer(colProp, maxColHeight);
				cellShape.children[cellShape.children.length] = headerCell;

				// resizable 처리
				if (this._getContext().columnMovable == true || this._getContext()._isResizable(colProp.constraint.cellIndex) == true) {
					cellShape.children[cellShape.children.length] = this._createResizableDiv(colProp);
				}

				// TOOLTIP
				GridUtil._setCellTitle(cellShape, colProp);
				bindContext._setHeaderCellIndex(beforeHeaderCellIndex);
			});

			// div
			let shape: ufc.ControlShape = {
				tag: "div",
				nodename: "header" + this.region + this.loc, // split 되었을 때 중복남
				style: {
					display: "inline-block",
					position: "relative",
					"min-width": "100%"
				},
				children: [headerShape]
			};

			return shape;
		}

		private _createContainer(colProp: GridHeaderCellProp, maxColHeight: number): ufc.ControlShape {
			let container: ufc.ElementShape = {
				tag: "div",
				attr: {},
				classNames: [GridContext.CLS_CELL_INHERIT],
				style: {
					overflow: "hidden",
					position: "relative",
					height: maxColHeight + "px" // 내부 컨트롤에 높이를 지정하기 위해 필요. (2017.9.27)
				},
				children: []
			};

			if (this._getContext().columnMovable == true) {
				if (GridHeader._DRAGGABLE_CONTROL_TYPE.indexOf(colProp.configuration.control?.type) == -1) {
					container.style["cursor"] = "pointer";
					container.attr["draggable"] = "true";
					container.classNames[container.classNames.length] = ufc.Classes.DRAGGABLE;
				}
			}

			let controlRenderer: (ufc.ControlRenderer | ufc.ControlShape) = null;
			if (colProp.hasOwnProperty("cellRenderer")) {
				controlRenderer = colProp.cellRenderer.createCellShape();

			} else if (colProp.configuration.control != null) {
				// UI컨트롤이 설정된 경우
				colProp.configuration.control.style.css({
					width: "100%",
					height: "100%"
				});
				controlRenderer = colProp.configuration.control._getRenderer();

				controlRenderer.addDecorator("grid-cell-decorator", (controlShape: ufc.ControlShape) => {
					controlShape.classNames = _uniq(controlShape.classNames.concat(GridContext.CLS_CTRL_INHERIT));
					GridUtil._setControlPosition(controlShape, colProp.configuration.controlConstraint);
					return controlShape;
				});
			} else {
				// 단순 Text로 설정된 경우
				let text: string | ufc.StyledString = this._getText(colProp);
				let textWrapper: ufc.ControlShape = {
					tag: "div",
					classNames: [GridStyle.CONTROL, GridStyle.DEFAULTCELL, GridContext.CLS_CELL_INHERIT],
					style: {
						height: maxColHeight + "px"
					},
					children: [{
						tag: "div",
						classNames: [GridContext.CLS_CELL_INHERIT],
						style: {
							display: "table",
							width: "100%",
							height: "100%"
						},
						children: [{
							tag: "div",
							classNames: [ufc.Classes.TEXT, GridContext.CLS_CELL_INHERIT],
							style: {
								display: "table-cell"
							},
							children: ufc.StyledString._asShape(text)
						}]
					}]
				};
				// TH의 text-align이 적용될 수 있도록 inline-block으로 설정
				controlRenderer = textWrapper;
			}
			container.children.push(controlRenderer);

			return container;
		}

		private _createSortableDiv(colProp: GridHeaderCellProp, cell: ufc.ElementShape, colHeight: number): ufc.ControlShape {
			let grid: Grid = this._getContext().getGrid();
			let sortStr: string = grid.getSort();
			let sorts: string[] = sortStr.split(',');
			let descending: string = null;
			let cellConfiguration: config.GridHeaderCellConfigurator = colProp.configuration;
			sorts.some((sort: string) => {
				let sortInfo: string[] = sort.split(' ');
				let sortColumn: string = sortInfo[0];
				let ascending: string = sortInfo[1];
				let nullLastSortCondition = grid._getSortCondition(cellConfiguration.sortColumnName, EMPTYVALUESORT.NULL_LAST);
				let emptyStringSortCondition = grid._getSortCondition(cellConfiguration.sortColumnName, EMPTYVALUESORT.EMPTY_STRING);

				if (sortColumn == cellConfiguration.sortColumnName || sortColumn == nullLastSortCondition || sortColumn == emptyStringSortCondition) {
					descending = (ascending) ? ascending : "asc";
					return true;
				}
			});
			let classNames: string[] = ["cl-sort"];
			if (descending == null) {
				classNames.push("cl-sortable");
				GridUtil._setAria(cell, "sort", "none");
			} else if (descending.toLowerCase() == "desc") {
				classNames.push("cl-sort-desc");
				GridUtil._setAria(cell, "sort", "descending");
			} else {
				classNames.push("cl-sort-asc");
				GridUtil._setAria(cell, "sort", "ascending");

			}

			let sortImg: ufc.ControlShape = {
				tag: "div",
				attr: {},
				classNames: classNames,
				style: {
					float: "right",
					height: GridContext._getCellMaxHeight(colHeight) + "px"
				}
			}

			return sortImg;
		}

		/**
		 * Grid Column이 resizable 할때 resizable 가능한 영역을 추가합니다.
		 * @param colProp 
		 */
		private _createResizableDiv(colProp: GridHeaderCellProp): ufc.ControlShape {
			let optionArea: ufc.ElementShape = {
				tag: "div",
				classNames: [],
				attr: {
					"data-resize": colProp.constraint.cellIndex + "", // columnMovable시 필요한 정보
				},
				style: {
					position: "absolute",
					top: "0",
					bottom: "0",
					right: "0",
					width: "5px", // container 영역 고정을 위해 고정값을 지정함.
					"border-width": "0",
					"touch-action": "none"
				},
			};
			if (this._getContext()._isResizable(colProp.constraint.cellIndex) == true) {
				optionArea.style["cursor"] = "col-resize";
				optionArea.classNames[optionArea.classNames.length] = ufc.Classes.DROPPABLE;
			}
			return optionArea;
		}

		/**
		 * cell text를 반환합니다.
		 * @param colProp 
		 */
		private _getText(colProp: GridHeaderCellProp): string | ufc.StyledString {
			if (!colProp.configuration) {
				return null;
			}

			let text: string | ufc.StyledString = null;
			let context: GridContext = this._getContext();
			let grid: Grid = context.getGrid();
			let bindContext: bind.GridEmbeddedContext = grid.getBindContext() as bind.GridEmbeddedContext;
			if (bindContext) {
				let beforeHeaderCellIndex: number = bindContext._getHeaderCellIndex();
				bindContext._setHeaderCellIndex(colProp.constraint.cellIndex);
				text = (colProp.configuration.text != null) ? colProp.configuration.text : "";
				bindContext._setHeaderCellIndex(beforeHeaderCellIndex);
			}

			return text;
		}

		/**
		 * header의 visible=true 상태인 총 width를 반환합니다.
		 * (px 단위)
		 */
		public _getWidth(): number {
			let width: number = 0;
			let length: number = this._layout.columnLayout.length;
			for (let i = 0; i < length; i++) {
				if (this._layout.columnLayout[i].visible == true) {
					let columnWidth: number = this._layout.columnLayout[i].width;
					width += columnWidth;
				}
			}
			return width;
		}

		public _getClientWidth(): number {
			return this._scrollPane._getViewportWidth();
		}

	}
}