namespace cpr.controls.gridpart.layout {


	export class ScrollbarNativeAdapter implements IScrollbarAdapter {
		private _scrollStrategy: IGridScrollbarOwner;

		private _contentWidth: number = -1;
		private _contentHeight: number = -1;

		private _passiveScrollTop: number = -1;
		private _passiveScrollLeft: number = -1;


		constructor(scrollStrategy: IGridScrollbarOwner) {
			this._scrollStrategy = scrollStrategy;
		}

		public _getActiveVScrollTop(): number {
			let renderer: ufc.ControlRenderer = this._scrollStrategy._getRenderer();
			let scrollElement: HTMLElement = renderer.getNamedNode(this._getQName("vscroll"));
			if (!scrollElement) {
				return -1;
			}
			return scrollElement.scrollTop;
		}

		public _getVScrollbarWidth(): number {
			return internal.ScrollbarUtil._getNativeScrollWidth();
		}

		public _getHScrollbarHeight(): number {
			return internal.ScrollbarUtil._getNativeScrollWidth();
		}

		public _setContentHeight(height: number): void {
			this._contentHeight = height;
		}

		public _getContentHeight(): number {
			return this._contentHeight;
		}

		public _setContentWidth(width: number): void {
			this._contentWidth = width;
		}

		public _getContentWidth(): number {
			return this._contentWidth;
		}

		public _createVScrollbar(scrollTop: number, contentHeight: number): ufc.ElementShape {
			let vScrollViewPort: ufc.ElementShape = {
				tag: "div",
				attr: {},
				style: {
					width: "1px",
					height: contentHeight + "px"
				}
			};

			// IE에서 ScrollBar에 BackgroundColor를 설정했을 때 ScrollBar가 보이지 않아 relative로 감쌈.
			// let scrollbarInfo: internal.ScrollbarInfo = internal.ScrollbarUtil._getScrollbarInfo();
			let vScroll: ufc.ElementShape = {
				tag: "div",
				attr: {},
				classNames: [GridStyle.BLANK],
				style: {
					"box-sizing": "border-box",
					"overflow": "hidden",
					position: "absolute",
					top: "0px",
					right: "0px",
					bottom: "0px",
					width: this._getVScrollbarWidth() + "px"
				},
				children: [{
					tag: "div",
					attr: {},
					classNames: internal.ScrollbarUtil._getScrollPaneClasses(),
					style: {
						"overflow-X": "hidden",
						"overflow-Y": this._scrollStrategy._getNativeVScrollbarOverflowY(),
						position: "relative",
						width: "100%",
						height: "100%"
					},
					nodename: this._getQName("vscroll"),
					events: {
						scroll: _.throttle((e: events.CUIEvent) => { this._onVirtualVScroll(e); }, 50, { leading: false }) // throttling 적용
					},
					children: [vScrollViewPort]
				}]
			};

			if (this._scrollStrategy._isEnabled() == false) {
				// disabled시 기본 scroll event를 막기 위한 막.
				vScroll.children.push({
					tag: "div",
					attr: {},
					style: {
						position: "absolute",
						left: "0px",
						top: "0px",
						width: "100%",
						height: "100%"
					}
				});
			}

			return vScroll;
		}

		public _createDummyVScrollbar(): ufc.ElementShape {
			return {
				tag: "div",
				attr: {},
				classNames: [GridStyle.BLANK],
				style: {
					display: "none",
					position: "absolute",
					top: "0px",
					right: "0px",
					bottom: "0px",
					width: "0px"
				},
				children: []
			};
		}

		public _createHScrollbar(scrollLeft: number, contentWidth: number): ufc.ElementShape {
			let contentWidthStr: string = "";
			if (this._scrollStrategy._getAutofit() == "none") {
				contentWidthStr = contentWidth + "px";
			} else {
				let viewportWidth: number = this._scrollStrategy._getViewportWidth();
				if (contentWidth < viewportWidth) {
					contentWidthStr = "100%";
				} else {
					contentWidthStr = contentWidth + "px";
				}
			}
			let hScrollViewPort: ufc.ElementShape = {
				tag: "div",
				attr: {},
				style: {
					width: contentWidthStr,
					height: "1px"
				}
			};

			// IE에서 ScrollBar에 BackgroundColor를 설정했을 때 ScrollBar가 보이지 않아 relative로 감쌈.
			// let scrollbarInfo: internal.ScrollbarInfo = internal.ScrollbarUtil._getScrollbarInfo();
			let hScroll: ufc.ElementShape = {
				tag: "div",
				attr: {},
				classNames: [GridStyle.BLANK],
				style: {
					"box-sizing": "border-box",
					"overflow-X": "hidden",
					"overflow-Y": "hidden",
					position: "absolute",
					bottom: "0px",
					left: "0px",
					right: this._scrollStrategy._isShowingVScrollbar() ? this._getVScrollbarWidth() + "px" : "0px",
					height: this._getHScrollbarHeight() + "px"
				},
				children: [{
					tag: "div",
					attr: {},
					nodename: this._getQName("hscroll"),
					classNames: internal.ScrollbarUtil._getScrollPaneClasses(),
					style: {
						"box-sizing": "content-box",
						"overflow-X": this._scrollStrategy._getNativeHScrollbarOverflowX(),
						"overflow-Y": "hidden",
						position: "relative",
						width: "100%",
						height: "100%"
					},
					events: {
						scroll: _.throttle((e: events.CUIEvent) => { this._onVirtualHScroll(e); }, 50, { leading: false }) // throttling 적용
					},
					children: [hScrollViewPort]
				}]
			};

			if (this._scrollStrategy._isEnabled() == false) {
				// disabled시 기본 scroll event를 막기 위한 막.
				hScroll.children.push({
					tag: "div",
					attr: {},
					style: {
						position: "absolute",
						left: "0px",
						top: "0px",
						width: "100%",
						height: "100%"
					}
				});
			}

			return hScroll;
		}

		public _createDummyHScrollbar(): ufc.ElementShape {
			return {
				tag: "div",
				attr: {},
				classNames: [GridStyle.BLANK],
				style: {
					display: "none",
					position: "absolute",
					bottom: "0px",
					left: "0px",
					right: "0px",
					height: "0px"
				},
				children: []
			};
		}


		/**
		 * 브라우저의 vertical event listener
		 */
		private _onVirtualVScroll(e: events.CUIEvent): void {
			// Grid 내부에서 이벤트의 중앙 통제 필요. requestAnimationFrame를 사용한 빈도 조절 고려 필요.
			let target: HTMLElement = <HTMLElement>e.target;
			let scrollTop: number = target.scrollTop;

			if (this._passiveScrollTop === -1 || GridUtil._equalsApproximately(this._passiveScrollTop, scrollTop) == false) {
				this._passiveScrollTop = -1;
				this._scrollStrategy._setViewportScrollTop(e, scrollTop);
			}
		}

		/**
		 * 브라우저의 horizontal event listener
		 */
		private _onVirtualHScroll(e: events.CUIEvent): void {
			let target: HTMLElement = <HTMLElement>e.target;
			let scrollLeft: number = target.scrollLeft;

			if (this._passiveScrollLeft === -1 || GridUtil._equalsApproximately(this._passiveScrollLeft, scrollLeft) == false) {
				this._passiveScrollLeft = -1;
				this._scrollStrategy._setViewportScrollLeft(e, scrollLeft);
			}
		}

		public _setVScrollTop(scrollTop: number): void {
			// 가상스크롤의 scrolltop 조정
			let gridRenderer: ufc.ControlRenderer = this._scrollStrategy._getRenderer();
			let vScrollElement: HTMLElement = gridRenderer.getNamedNode(this._getQName("vscroll"));
			if (vScrollElement) {
				vScrollElement.scrollTop = scrollTop;
			}
			this._passiveScrollTop = scrollTop;
		}

		public _setHScrollLeft(scrollLeft: number): void {
			// 가상스크롤의 scrollleft 조정
			let gridRenderer: ufc.ControlRenderer = this._scrollStrategy._getRenderer();
			let hScrollElement: HTMLElement = gridRenderer.getNamedNode(this._getQName("hscroll"));
			if (hScrollElement) {
				hScrollElement.scrollLeft = scrollLeft;
			}
			this._passiveScrollLeft = scrollLeft;
		}

		private _getQName(name: string): string {
			return this._scrollStrategy._getQNamePrefix() + "-" + name;
		}

	}
}