	export enum ViewingMode {
		/**
		 * 값이 텍스트로 보여지는 컨트롤의 경우 텍스트만 표현되고, <br>
		 * 값이 이미지나 아이콘으로 표현되는 경우 컨트롤 형태 그대로 표현됩니다. <br>
		 * (텍스트만 표현되는 컨트롤 : 아웃풋, 인풋 박스, 서치 인풋, 넘버 에디터, 데이트 인풋, 마스크 에디터, 파일 인풋, 콤보박스, 텍스트에리어) <br>
		 * (컨트롤 형태 그대로 표현 되는 컨트롤 : HTML스니펫, 라디오버튼, 버튼, 슬라이더, 이미지, 체크박스, 체크박스그룹, 트리셀, 프로그레스)
		 */
		LITE = "lite",
		/**
		 * 일부 컨트롤의 버튼이 뷰잉모드에서 표현됩니다. <br>
		 * (서치 인풋, 데이트 인풋, 콤보박스) <br>
		 * 그 외 컨트롤은 lite 방식을 따릅니다.
		 */
		BUTTON = "button"
	}

	export enum TabMode {
		/**
		 * 전체 셀을 tab으로 이동할 수 있습니다. (기본셀, Output 모두 포함) <br>
		 * visible=false인 컨트롤이 배치된 셀은 이동되지 않습니다.
		 */
		ALL = "all",
		/**
		 * 편집가능한 컨트롤로만 tab 이동이 됩니다. (tab 이동 불가 컨트롤 예시 : Output, Input(disabled))
		 */
		EDITABLE = "editable",
		/**
		 * 포커스 가능한 컨트롤로만 tab 이동이 됩니다. (tabIndex의 영향을 받습니다.)
		 */
		FOCUSABLE = "focusable",
		/**
		 * tab이동을 지원하지 않습니다.
		 */
		NONE = "none"
	}

	export interface GridCellInfo {
		region: GRIDREGION,     // 그리드의 영역정보 : header, middle(top ∪ middle ∪ bottom), footer, gheader, gfooter
		dsRowIndex: number,     // DataSet의 행인덱스
		cellIndex: number,      // 그리드 디자인 셀인덱스 
		rowIndex: number,       // 그리드 디자인 행인덱스
		colIndex: number,       // 그리드 디자인 컬럼인덱스
		rowSpan: number,        // 그리드 디자인 rowSpan
		colSpan: number,        // 그리드 디자인 colSpan
		columnType: string,     // normal, rowindex, checkbox
		columnName: string,     // dataset 컬럼명
		value: string | number, // dataset value
		text: string,           // 화면에 보여지는 텍스트
		ctrl: UIControl         // 데이터가 바인딩 된 UIControl
	}

