		/**
		 * 그리드 초기 속성 및 디자인 정보를 세팅합니다.<br>
		 * 이전에 연결된 컨트롤은 제거되므로 재사용이 불가합니다.
		 * @param gridInfo 그리드 구성 정보.
		 * 
		 * @example
		 * <code>
		 * this.init({
		 * 	dataSet: dataset,
		 * 	// hScroll: "auto",			// 가로 스크롤 스타일을 설정= "auto" or "scroll" or "hidden"
		 * 	// vScroll: "auto",			// 세로 스크롤 스타일을 설정= "auto" or "scroll" or "hidden"
		 * 	// wheelRowCount: 5,		//wheel로 한번에 스크롤하는 로우수
		 * 	columns: [ // column별 width값.
		 * 		{ width: "30px" }, { width: "30px" }, { width: "30px" }
		 * 	],
		 * 	header: { // header 영역 구성 정보.
		 * 		rows: 
		 * 			[{height:"30px"},{height:"20px"}],	// header row별 높이. 여러 줄일 경우 콤마(,)를 사용하여 나타냅니다.[단위 : px]
		 * 		cells: [ // header 영역 내부의 cell 구성 정보.
		 * 			// rowIndex: 해당 cell이 위치할 row index. (0 base)
		 * 			// colIndex: 해당 cell이 위차할 column index. (0 base)
		 * 			// rowSpan: 해당 cell이 세로로 병합될 row 수. (default : 1)
		 * 			// colSpan: 해당 cell이 가로로 병합될 column 수. (default: 1)
		 * 			// text: (Optional) 해당 header cell에 보여질 텍스트.
		 * 			// sortcolumnName: (Optional) 해당 header cell 클릭시 정렬시킬 dataset column name.
		 * 			// visible: (Optional) 해당 header cell이 위치한 컬럼 전체의 visible 설정. (default: true)
		 * 			{ 
		 * 				constraint : {  rowIndex: 0, colIndex: 0, rowSpan: 2, colSpan: 1 }, 
		 * 				configurator : function(cell){
		 * 					cell.text = "A";
		 * 					cell.sortColumnName = "a";
		 * 					cell.visible = false;
		 * 				}
		 * 			},{
		 * 				constraint : {  rowIndex: 0, colIndex: 1, rowSpan: 1, colSpan: 2 }, 
		 * 				configurator : function(cell){
		 * 					cell.text = "B + C";
		 * 					cell.visible = true;
		 * 				}
		 * 			},{
		 * 				constraint : {  rowIndex: 1, colIndex: 1, rowSpan: 1, colSpan: 1 }, 
		 * 				configurator : function(cell){
		 * 					cell.text = "B";
		 * 					cell.sortColumnName = "b";
		 * 					cell.visible = true;
		 * 				}
		 * 			},{
		 * 				constraint : {  rowIndex: 1, colIndex: 2, rowSpan: 1, colSpan: 1 }, 
		 * 				configurator : function(cell){
		 * 					cell.text = "C";
		 * 					cell.sortColumnName = "c";
		 * 					cell.visible = true;
		 * 				}
		 * 			}
		 * 		]
		 * 	},
		 * 	detail: {			// detail 영역 구성 정보.
		 * 		rows: [{height:"20px"}],	// detail row별 높이. 여러 줄일 경우 콤마(,)를 사용하여 나타냅니다.[단위 : px]
		 * 		cells: [			// detail 영역 내부의 cell 구성 정보.
		 * 			// columnName: (Optional) 해당 detail cell에 연결될 dataset column name.
		 * 			// suppressible: (Optional) 바로 직전 로우의 값과 일치하는 셀은 텍스트를 숨김. (셀 병합 효과 제공) (default: false)
		 * 			// suppressref: (Optional) suppressible (셀 텍스트 숨김) 효과에 영향을 줄 다른 컬럼 설정.
		 * 			// control: (Optional) 해당 detail cell에 위치시킬 UIControl.
		 * 			{
		 * 				constraint : {  rowIndex: 0, colIndex: 0, rowSpan: 1, colSpan: 1 }, 
		 * 				configurator : function(cell){
		 * 					cell.columnName = "a";
		 * 					cell.suppressible = "true";
		 * 				}
		 * 			},{
		 * 				constraint : {  rowIndex: 0, colIndex: 1, rowSpan: 1, colSpan: 1 }, 
		 * 				configurator : function(cell){
		 * 					cell.columnName = "b";
		 * 					cell.suppressible = "true";
		 * 					cell.suppressref = 0;
		 * 				}
		 * 			},{
		 * 				constraint : {  rowIndex: 0, colIndex: 2, rowSpan: 1, colSpan: 1 }, 
		 * 				configurator : function(cell){
		 * 					cell.columnName = "c";
		 * 					cell.control = new cpr.controls.InputBox(); 
		 * 				}
		 * 			}
		 * 		]
		 * 	},
		 * 	footer: {			// (Optional) footer 영역 구성 정보.
		 * 		rows: [{height:"20px"}],	// footer row별 높이. 여러 줄일 경우 콤마(,)를 사용하여 나타냅니다.[단위 : px]
		 * 		cells: [			// footer 영역 내부의 cell 구성 정보.
		 * 			// expr: (Optional) 해당 footer cell에 보여질 텍스트 또는 expression식.
		 * 			{
		 * 				constraint : {  rowIndex: 0, colIndex: 0, rowSpan: 1, colSpan: 1 }, 
		 * 				configurator : function(cell){
		 * 					cell.expr = "footer_a";
		 * 				}
		 * 			},{
		 * 				constraint : {  rowIndex: 0, colIndex: 1, rowSpan: 1, colSpan: 1 }, 
		 * 				configurator : function(cell){
		 * 					cell.expr = "footer_b";
		 * 				}
		 * 			},{
		 * 				constraint : {  rowIndex: 0, colIndex: 2, rowSpan: 1, colSpan: 1 }, 
		 * 				configurator : function(cell){
		 * 					cell.expr = "getSum('c')";
		 * 				}
		 * 			}
		 * 		]
		 * 	}
		 * });
		 * </code>
		 */
		public init(gridInfo: gridpart.GridConfig): void {
			if (gridInfo.dataSet == null) {
				gridInfo.dataSet = new data.DataSet(null);
			}

			// bypass
			this._dataProvider._setDataControl(gridInfo.dataSet);
			this.dataProvider._clearStatisticCache();

			// 그리드에 포함된 컨트롤의 컬럼 바인딩을 Grid에서 Context 수준으로 관리하기 위해 GridEmbededContext를 설정.
			this.setBindContext(new bind.GridEmbeddedContext(this));

			this.removeAllChildren(true);
			this._context.init(gridInfo); // RowGroup Reset이 포함됨
			let propNames: string[] = _.keys(gridInfo);
			let propIndex: number = propNames.indexOf('noDataMessage');
			if (propIndex != -1) {
				this.noDataMessage = gridInfo['noDataMessage'];
			}

			if (this.showDeletedRow === false && this._dataProvider != null) {
				if (this.showDeletedRow === false) {
					let deletedState: number = cpr.data.tabledata.RowState.DELETED;
					let insertdeletedState: number = cpr.data.tabledata.RowState.INSERTDELETED;
					let deleteRowCondition: string = "getState() != " + deletedState + " && getState() != " + insertdeletedState;
					this._dataProvider._setShowDeletedRowFilter(new expression.Expression(deleteRowCondition));
				} else {
					this._dataProvider._setShowDeletedRowFilter(null);
				}
			}

			this._recreateGridTableInfo();
			this._resetSelector();
			this._gridControlLayout._resetGridLayout();
		}

		/**
		 * 그리드 초기 설정 정보를 반환합니다.
		 * @returns 그리드 초기 설정 정보. grid.init()에 해당되는 정보입니다.
		 */
		public getInitConfig(): gridpart.GridConfig {
			return this._context.getInitConfig();
		}

		/**
		 * 그리드에 포함된 컨트롤의 컬럼 바인딩을 Grid에서 Context 수준으로 제어하기 위해 DataRowContext를 설정.
		 * @param rowIndex 
		 */
		public _setContentDataRowIndex(rowIndex: number, contentIndex: number): void {
			let bindContext: bind.GridEmbeddedContext = this.getBindContext() as bind.GridEmbeddedContext;
			if (bindContext) {
				bindContext._setRowIndex(rowIndex, contentIndex);
			}
		}
		public _keepContentDataRowIndex(): void {
			let bindContext: bind.GridEmbeddedContext = this.getBindContext() as bind.GridEmbeddedContext;
			if (bindContext) {
				bindContext._keepIndex();
			}
		}
		public _restoreContentDataRowIndex(): void {
			let bindContext: bind.GridEmbeddedContext = this.getBindContext() as bind.GridEmbeddedContext;
			if (bindContext) {
				bindContext._restoreIndex();
			}
		}
		private _getContentDataRowIndex(): number {
			let bindContext: bind.GridEmbeddedContext = this.getBindContext() as bind.GridEmbeddedContext;
			if (bindContext) {
				return bindContext.rowIndex;
			}
			return -1;
		}
		private _getKeepRowIndex(): number {
			let bindContext: bind.GridEmbeddedContext = this.getBindContext() as bind.GridEmbeddedContext;
			if (bindContext) {
				return bindContext._getKeepRowIndex();
			}
			return null;
		}

