		public _select(oldSelection: number[] | gridpart.selection.CellPosition[], selection: number[] | gridpart.selection.CellPosition[],
			isEditing: boolean, editRowIndex: number, emitEvent: boolean): void {

			let selectionUnit: string = this.selectionUnit;
			switch (selectionUnit) {
				case "row": {
					this._gridSelector._selectRows(selection as number[]);
					break;
				}
				case "cell": {
					this._gridSelector._selectCells(selection as gridpart.selection.CellPosition[]);
					break;
				}
				case "column": {
					this._gridSelector._selectColumns(selection as number[]);
					break;
				}
			}

			if (isEditing == true) {
				let isDeletedRow: boolean = this._dataProvider._isDeletedRow(editRowIndex);
				if (isDeletedRow) {
					this._setEditRowIndex(-1, true);
				} else {
					this._setEditRowIndex(editRowIndex, true);
				}
			}

			if (emitEvent !== false) {
				let newSelection: number[] | gridpart.selection.CellPosition[] = this.getSelectedIndices();
				if (_.isEqual(oldSelection, newSelection) == false) {
					this.dispatchEvent(new events.CSelectionEvent(events.SelectionEventType.CHANGE, {
						oldSelection: oldSelection,
						newSelection: newSelection
					}));
				}
			}

			// DataWindow에서 필요한 Row를 채워넣은 후 rendering을 지원하기 위해 select할 때 무조건 redraw 하는 부분은 개선되어야 함. GridEventController와 연합되어 동작하는 부분.
			this._getAllDetails().forEach(item => this._applyPiece(item));
		}


		public _startSelection(dataRowIndex: number, cellIndex: number): void {
			let details: gridpart.GridDetail[] = null;
			if (this.selectionUnit == "column") {
				details = this._getAllDetails();
			} else {
				let rows: number[] = [dataRowIndex].concat(this._getSelectedIndices());
				details = this._getContainDetails(rows, false);
			}

			this._gridSelector._startSelection(dataRowIndex, cellIndex);

			details.forEach(item => this._applyPiece(item));
		}

		/**
		 * 현재 행/열/셀을 선택중인 상태인지 반환합니다.
		 * @returns 선택중인지 여부.
		 */
		public isSelectionStarted(): boolean {
			return this._gridSelector._isSelectionStarted();
		}

		public _addSelection(rowIndex: number, cellIndex: number): boolean {
			let details: gridpart.GridDetail[] = null;
			if (this.selectionUnit == "column") {
				details = this._getAllDetails();
			} else {
				let rows: number[] = [rowIndex].concat(this._getSelectedIndices());
				details = this._getContainDetails(rows, false);
			}

			let beforeSelection: number[] | gridpart.selection.CellPosition[] = this.getSelectedIndices();

			this._gridSelector._addSelection({
				rowIndex: rowIndex,
				cellIndex: cellIndex
			});

			let afterSelection: number[] | gridpart.selection.CellPosition[] = this.getSelectedIndices();

			// selection-change
			this.dispatchEvent(new events.CSelectionEvent(events.SelectionEventType.CHANGE, {
				oldSelection: beforeSelection,
				newSelection: afterSelection
			}));

			details.forEach(item => this._applyPiece(item));

			return true;
		}

		/**
		 * 가장 가까운 선택 포인트를 찾아서 그 포인트와 현재 포지션까지 전체 선택
		 * @param rowindex
		 * @param cellIndex 
		 */
		public _selectRange(rowIndex: number, cellIndex: number, isEditing: boolean = false, editRowIndex: number = -1): boolean {
			let details: gridpart.GridDetail[] = null;
			if (this.selectionUnit == "column") {
				details = this._getAllDetails();
			} else {
				let rows: number[] = [rowIndex].concat(this._getSelectedIndices());
				details = this._getContainDetails(rows, true);
			}

			let oldSelection: number[] | gridpart.selection.CellPosition[] = this.getSelectedIndices();

			this._gridSelector._selectRange({
				rowIndex: rowIndex,
				cellIndex: cellIndex
			});

			if (isEditing == true) {
				this._setEditRowIndex(editRowIndex, true);
			}

			// selection-change
			let newSelection: number[] | gridpart.selection.CellPosition[] = this.getSelectedIndices();
			if (_.isEqual(oldSelection, newSelection) == false) {
				this.dispatchEvent(new events.CSelectionEvent(events.SelectionEventType.CHANGE, {
					oldSelection: oldSelection,
					newSelection: newSelection
				}));
			}

			details.forEach(item => this._applyPiece(item));

			return true;
		}

