		/**
		 * @private
		 * olumntype이 checkbox인 checkbox의 check를 모두 해제합니다.
		 * @param force false 일 경우 비활성화 또는 invisible 된 check 해제 상태로 변경되지 않음.
		 */
		private _clearAllCheck(hCellProp: gridpart.GridHeaderCellProp, force: boolean = true): void {
			this._resetRealDeletedRowIfNeeded();
			this._resetDeletedRowIfNeeded();

			let detailCellProp: gridpart.GridDetailCellProp = null;
			if (hCellProp != null) {
				let detailCellIndices: number[] = this.getDetailCellIndices(hCellProp.constraint.cellIndex);
				let detailColumn: gridpart.GridDetailColumn = (detailCellIndices.length == 1) ? this.detail.getColumn(detailCellIndices[0]) : null;
				detailCellProp = (detailColumn?.columnType == "checkbox") ? detailColumn.cellProp : null;
			}

			let length: number = this.rowCount;
			let isPartial: boolean = false;
			let isChange: boolean = false;
			this._keepContentDataRowIndex();
			for (let i = 0; i < length; i++) {
				this._setContentDataRowIndex(i, -1);
				let gridRow: provider.GridRow = this._dataProvider.getRow(i);
				let cellEnabled: boolean = detailCellProp?.configuration.enabled ?? true;
				let cellVisible: boolean = detailCellProp?.configuration.visible ?? true;
				if (force == false && (gridRow.rowCheckEnabled == false || gridRow.rowCheckVisible == false || cellEnabled === false || cellVisible === false)) {
					if (gridRow.rowChecked == true) {
						isPartial = true;
					}
					continue;
				}

				gridRow._setChecked(false);
				isChange = true;
			}
			this._restoreContentDataRowIndex();

			if (isChange == false) {
				return;
			}

			this._checkHeader = isPartial == true ? CHECKMODE.PARTIAL_ALL_UNCHECKED : CHECKMODE.UNCHECKED;
			this.redraw();
		}

