		/**
		 * @private
		 * columnType="check"인 체크박스가 활성화 상태인 모든 행이 checked 상태인지 반환합니다.
		 * @return 활성화 상태인 모든 행이 checked 상태일 때 true
		 */
		public _getPartialCheckState(startRowIndex: number, endRowIndex: number): string {
			this._resetRealDeletedRowIfNeeded();
			this._resetDeletedRowIfNeeded();

			let enabledRowIndices: number[] = [];
			let checkedRowIndices: number[] = [];
			for (let i = startRowIndex; i <= endRowIndex; i++) {
				let gridRow: provider.GridRow = this._dataProvider.getRow(i);
				let rowIndex: number = gridRow.getIndex();

				if (gridRow.rowCheckEnabled) {
					enabledRowIndices.push(rowIndex);
				}

				if (gridRow.rowChecked) {
					checkedRowIndices.push(rowIndex);
				}
			}

			let differenceRowIndices: number[] = _.difference(enabledRowIndices, checkedRowIndices);

			let state: string = CHECKMODE.PARTIAL_CHECKED;
			if (differenceRowIndices.length == 0) {
				state = CHECKMODE.PARTIAL_ALL_CHECKED;
			} else if (_.isEqual(differenceRowIndices, enabledRowIndices)) {
				state = CHECKMODE.PARTIAL_ALL_UNCHECKED;
			}

			return state;
		}

		/**
		 * 그리드의 특정 행의 트리셀 체크박스를 체크 또는 해제 합니다.
		 * @param rowIndex 설정할 row index.
		 * @param checked 설정할 check 값.
		 * @param checkMode 체크 모드. <br>
		 * [single]: 설정한 행의 체크상태만 변경<br>
		 * [auto]: 트리셀에 적용된 checkType에 맞춰 체크상태 변경
		 */
		public setTreeCheckIndex(rowIndex: number, checked: boolean, checkMode: gridpart.renderer.TreeCellCheckMode = gridpart.renderer.TreeCellCheckMode.SINGLE): void {
			if (typeof (checked) != "boolean") {
				throw new exceptions.IllegalArgumentException(checked);
			}

			this._resetRealDeletedRowIfNeeded();
			this._resetDeletedRowIfNeeded();

			if (this.context._isTreeGrid() == false) {
				return null;
			}


			let rowGroup: provider.GridRowGroup = this.getGridRowGroup(rowIndex);
			if (!rowGroup) {
				return;
			}

			let treeCell: gridpart.renderer.TreeCell = this._context._getTreeCell();
			if (checkMode == gridpart.renderer.TreeCellCheckMode.AUTO) {
				let treeCell: gridpart.renderer.TreeCell = this._context._getTreeCell();
				rowGroup._setAutoCheckedOfTreeCell(checked, treeCell.checkType);
			} else {
				rowGroup._setCheckedOfTreeCell(treeCell.checkType, checked, false);
			}

		}

		/**
		 * 현재 트리셀의 체크박스에 체크 되어있는 행 인덱스를 반환합니다.<br>
		 * 그리드에 트리셀이 존재하지 않는 경우 null을 반환합니다.
		 * @param isAll 트리셀 접기 상태와 무관한 전체 행의 체크된 인덱스를 반환받을 지 유무.
		 * @return 현재 트리셀에 체크 되어있는 row index 배열.
		 */
		public getTreeCheckIndices(isAll: boolean = false): number[] {
			this._resetRealDeletedRowIfNeeded();
			this._resetDeletedRowIfNeeded();

			if (this.context._isTreeGrid() == false) {
				return null;
			}

			let checkedRowIndices: number[] = [];
			if (isAll === true) {
				let rowgroups: provider.GridRowGroup[] = this.dataProvider._getRowGroups();
				if (!rowgroups) {
					return null;
				}

				rowgroups.forEach((gridRowGroup: provider.GridRowGroup) => {
					this._travelRowgroup(checkedRowIndices, gridRowGroup);
				});
			} else {
				let virtualRows: provider.VirtualRow[] = this._getVirtualRows();
				let length: number = virtualRows.length;
				for (let i = 0; i < length; i++) {
					let vrow: provider.VirtualRow = virtualRows[i];
					if (vrow.pairgroup?._getCheckedState() == CHECKMODE.CHECKED) {
						checkedRowIndices[checkedRowIndices.length] = i;
					}
				}
			}

			return checkedRowIndices;
		}

		private _travelRowgroup(checkedRowIndices: number[], gridRowGroup: provider.GridRowGroup) {
			let gridRow: provider.GridRow = gridRowGroup.target;
			if (gridRowGroup._getCheckedState() == CHECKMODE.CHECKED) {
				checkedRowIndices[checkedRowIndices.length] = gridRow.getIndex();
			}


			let rows: (provider.GridRow | provider.GridRowGroup)[] = gridRowGroup._getRows();
			if (rows != null) {
				rows.forEach((row: (provider.GridRow | provider.GridRowGroup)) => {
					this._travelRowgroup(checkedRowIndices, row as provider.GridRowGroup);
				});
			}
		}

