		/**
		 * 특정 row의 columnType=radio를 선택합니다.
		 * @param rowIndex 설정할 row index.
		 * @param emitEvent 이벤트(row-radio-selected)를 발생시킬지 여부.
		 */
		public selectRadio(rowIndex: number, emitEvent: boolean = true): void {
			this._resetRealDeletedRowIfNeeded();
			this._resetDeletedRowIfNeeded();

			let beforeSelected: boolean = this.isRadioSelected(rowIndex);

			let gridRow: provider.GridRow = this._dataProvider.getRow(rowIndex);
			if (gridRow == null) {
				return;
			}
			if (beforeSelected == false) {
				let redrawRowIndices: number[] = [rowIndex];
				let beforeSelectedIndex: number = this.getRadioSelection();
				let beforeGridRow: provider.GridRow = this._dataProvider.getRow(beforeSelectedIndex);
				if (beforeGridRow != null) {
					beforeGridRow._setSelectRadio(false);
					redrawRowIndices.push(beforeSelectedIndex);
				}

				this.removeRadioSelection();
				gridRow._setSelectRadio(true);

				if (emitEvent == true) {
					this.dispatchEvent(new events.CGridEvent(events.GridEventType.ROW_RADIO_SELECTED, {
						relativeTargetName: "detail",
						row: this.dataProvider.getRow(rowIndex),
						rowIndex: rowIndex
					}));
				}
				let details: gridpart.GridDetail[] = this._getContainDetails(redrawRowIndices, false);
				details.forEach(item => this._applyPiece(item));
			}
		}

		/**
		 * 현재 columnType=radio이 선택되어 있는 row index를 반환합니다.
		 * @return 현재 columnType=radio이 선택되어 있는 row index.
		 */
		public getRadioSelection(): number {
			this._resetRealDeletedRowIfNeeded();
			this._resetDeletedRowIfNeeded();

			let radioSelectedIndex: number = -1;
			let length: number = this.rowCount;
			for (let i = 0; i < length; i++) {
				let gridRow: provider.GridRow = this._dataProvider.getRow(i);
				if (gridRow.rowRadioSelected === true) {
					radioSelectedIndex = i;
					break;
				}
			}
			return radioSelectedIndex;
		}

