		/**
		 * 특정 Row 전체의 데이터를 변경합니다.
		 * @param rowIndex 변경하고자 하는 row index.
		 * @param rowdata 변경하고자 하는 row data. (ex. { [columnName: string]: string })
		 * @param emitEvent 이벤트(before-update, update)를 발생시킬지 여부.
		 * @return 값 수정 성공 여부.
		 */
		public updateRow(rowIndex: number, rowdata: { [columnName: string]: string }, emitEvent: boolean = true): boolean {
			this._resetRealDeletedRowIfNeeded();
			this._resetDeletedRowIfNeeded();

			rowIndex = utils.ParamUtil.toNumber(rowIndex);
			if (rowIndex < 0 || rowIndex >= this.getRowCount()) {
				return false;
			}

			let rowState: data.tabledata.RowState = this.getRowState(rowIndex);
			if ((rowState & data.tabledata.RowState.DELETED) || (rowState & data.tabledata.RowState.INSERTDELETED)) {
				logger("error").log("[Grid.updateRow] : DELETED상태이거나 INSERTDELETED상태인 row는 수정할 수 없습니다.");
				return false;
			}

			if (emitEvent == true) {
				let preventDefault: boolean = this._context.getGrid().dispatchEvent(new events.CGridValueChangeEvent(events.GridEventType.BEFORE_UPDATE, {
					relativeTargetName: "detail",
					row: this.getRow(rowIndex),
					rowIndex: rowIndex
				}));
				if (!preventDefault) {
					return false;
				}
			}

			let result: boolean = this._dataProvider._updateRow(rowIndex, rowdata);

			if (emitEvent == true) {
				this.dispatchEvent(new events.CGridValueChangeEvent(events.GridEventType.UPDATE, {
					relativeTargetName: "detail",
					row: this.getRow(rowIndex),
					rowIndex: rowIndex
				}));
			}

			if (result == true) {
				this.redraw();
			}
			return result;
		}

		/**
		 * 특정 Row를 삭제합니다.
		 * @param rowIndex 삭제하고자 하는 row index 또는 index의 배열.
		 * @param emitEvent 이벤트(before-delete, delete)를 발생시킬지 여부.
		 */
		public deleteRow(rowIndex: number | number[], emitEvent: boolean = true): void {
			let delIdx: number[] = null;
			if (_isArray(rowIndex)) {
				delIdx = rowIndex as number[];
			} else {
				delIdx = [rowIndex as number];
			}

			// 현재 편집중인 상태에 대한 체크
			let editingRow: number = this._context.editingRowIndex;
			if (editingRow !== -1 && delIdx.indexOf(editingRow) != -1) {
				let success: boolean = true;
				if (this.showDeletedRow == true) {
					success = this._fireBeforeEditRowChangeEvent(-1, true);
					if (success) {
						this._setEditRowIndex(-1, true);
					}
				} else {
					success = this.setEditRowIndex(-1, true);
				}
				if (success == false) {
					return;
				}
			}

			delIdx = _stream(delIdx)
				.uniquify()
				.sortBy((a, b) => b - a)
				.collect();

			delIdx.forEach((rowIdx: number) => {
				if (rowIdx == -1) {
					return;
				}

				rowIdx = utils.ParamUtil.toNumber(rowIdx);

				if (emitEvent == true) {
					let preventDefault: boolean = this.dispatchEvent(new events.CGridEvent(events.GridEventType.BEFORE_DELETE, {
						relativeTargetName: "detail",
						row: this.getRow(rowIdx),
						rowIndex: rowIdx
					}));
					if (!preventDefault) {
						return null;
					}
				}

				this._dataProvider._deleteRow(rowIdx);

				if (emitEvent == true) {
					this.dispatchEvent(new events.CGridEvent(events.GridEventType.DELETE, {
						relativeTargetName: "detail"
					}));
				}
			});
		}

		/**
		 * 특정 row index의 상태를 반환합니다.
		 * @param rowIndex 상태를 알고자 하는 row index.
		 * @return 해당 row index의 상태값.<br>
		 * state 종류:<br>
		 * cpr.data.tabledata.RowState.UNCHANGED : 변경되지 않은 상태.<br>
		 * cpr.data.tabledata.RowState.INSERTED : 행이 신규로 추가된 상태.<br>
		 * cpr.data.tabledata.RowState.UPDATED : 행이 수정된 상태.<br>
		 * cpr.data.tabledata.RowState.DELETED : 행이 삭제된 상태.<br>
		 * cpr.data.tabledata.RowState.INSERTDELETED : 행이 추가되었다가 삭제된 상태.
		 */
		public getRowState(rowIndex: number): cpr.data.tabledata.RowState {
			this._resetRealDeletedRowIfNeeded();
			this._resetDeletedRowIfNeeded();

			return this._dataProvider.getRowState(rowIndex);
		}

		/**
		 * 특정 row index의 상태를 변경합니다.
		 * @param rowIndex 변경하고자 하는 row index.
		 * @param state 변경하고자 하는 state 값. <br>
		 * state 종류:<br>
		 * cpr.data.tabledata.RowState.UNCHANGED : 변경되지 않은 상태.<br>
		 * cpr.data.tabledata.RowState.INSERTED : 행이 신규로 추가된 상태.<br>
		 * cpr.data.tabledata.RowState.UPDATED : 행이 수정된 상태.<br>
		 * cpr.data.tabledata.RowState.DELETED : 행이 삭제된 상태.<br>
		 * cpr.data.tabledata.RowState.INSERTDELETED : 행이 추가되었다가 삭제된 상태.<br>
		 * 
		 * @example
		 * <code>grid.setRowState(1, cpr.data.tabledata.RowState.UPDATED)</code><br>
		 *  => 1번째 row의 상태를 UPDATED상태로 변경합니다.
		 */
		public setRowState(rowIndex: number, state: cpr.data.tabledata.RowState): void {
			this._resetRealDeletedRowIfNeeded();
			this._resetDeletedRowIfNeeded();

			rowIndex = utils.ParamUtil.toNumber(rowIndex);
			let before: cpr.data.tabledata.RowState = this.getRowState(rowIndex);

			this._dataProvider._setRowState(rowIndex, state);
			if (before != state) {
				let details: gridpart.GridDetail[] = this._getContainDetails([rowIndex], false);

				details.forEach(item => this._applyPiece(item));
			}
		}

