		/**
		 * 설정된 Grid정보를 초기화합니다.<br>
		 * 데이터 관련 정보는 초기화 되지 않습니다.
		 */
		public resetGrid(): void {
			this._gridControlLayout._readyForRedraw();

			// 그리드 기본값으로 초기화
			this._context._resetProperty();
			// 프로젝트 공통으로 세팅
			{ // initProperty
				// this._initControl()은 accessbility, properties, style 모두 초기화하여 properties만 초기화 하도록 수정
				let config: core.Config = this._getDefaultConfiguration();
				if (config) {
					this._configureProperties(config);
				}
			}
			// 그리드 사용자 최초설정으로 세팅
			this._context._reset();
			this._clearMultiSort();
			this._clearFilterDialog();

			this._recreateGridTableInfo();
			this._needRowGroupReset();
			this._clearStatisticCacheForRedraw();

			this._gridControlLayout._resetGridLayout();

			this.redraw();
		}

		/**
		 * 그리드 내에서 변경된 모든 데이터를 복구합니다.
		 */
		public revertData(): void {
			this._resetRealDeletedRowIfNeeded();
			this._resetDeletedRowIfNeeded();
			this._resetInsertedRowIfNeeded();

			if (this.selectionUnit != "column") {
				let isContinue: boolean = this._migrateSelection([data.tabledata.RowState.INSERTED, data.tabledata.RowState.INSERTDELETED]);
				if (isContinue == false) {
					return;
				}
			}

			this._dataProvider._revertData();
			this.redraw();
		}

		/**
		 * 그리드 내에서 변경된 특정 행의 데이터를 복구합니다.
		 * @param rowIndex 원복하고 싶은 row index
		 */
		public revertRowData(rowIndex: number): void {
			this._resetRealDeletedRowIfNeeded();
			this._resetDeletedRowIfNeeded();
			this._resetInsertedRowIfNeeded();

			if (this.selectionUnit != "column") {
				let selectedIndices: number[] | gridpart.selection.CellPosition[] = this.getSelectedIndices();
				if (selectedIndices.length > 0) {
					let tobeSelection: number[] | gridpart.selection.CellPosition[] = [].concat(selectedIndices);
					let selectionIndex: number = -1;
					if (typeof (tobeSelection[tobeSelection.length - 1]) == "number") {
						selectionIndex = (tobeSelection as number[]).indexOf(rowIndex);
					} else {
						(tobeSelection as gridpart.selection.CellPosition[]).some((selection: gridpart.selection.CellPosition, index: number) => {
							if (selection.rowIndex == rowIndex) {
								selectionIndex = index;
								return true;
							}
							return false;
						});
					}
					if (selectionIndex != -1) {
						let rowState: data.tabledata.RowState = this.getRowState(rowIndex);
						let editRowIndex: number = this._context.editingRowIndex;
						if (rowState == data.tabledata.RowState.INSERTED || rowState == data.tabledata.RowState.INSERTDELETED) {
							tobeSelection.splice(selectionIndex, 1);
							if (rowIndex == editRowIndex) {
								editRowIndex = -1;
							}
							let isContinue: boolean = true;
							if (_.isEqual(selectedIndices, tobeSelection) == false) {
								if (tobeSelection.length == 0) {
									isContinue = this._fireBeforeChangeEvent(tobeSelection, -1, true);
									if (isContinue) {
										this._clearSelection(selectedIndices);
									}
								} else {
									isContinue = this._fireBeforeChangeEvent(tobeSelection, editRowIndex, true);
									if (isContinue) {
										this._setSelection(selectedIndices, tobeSelection, editRowIndex);
									}
								}
							}
							if (isContinue == false) {
								return;
							}
						}
					}
				}
			}

			// insert 상태인 로우를 revert 할 때 처리시 컨텐트 상태 초기화
			let rowState: data.tabledata.RowState = this._dataProvider.getRowState(rowIndex);
			if (rowState === data.tabledata.RowState.INSERTED) {
				this._needDeletedRowReset();
				this._needInsertedRowReset();
			}

			this._dataProvider._revertRowData(rowIndex);
			this.redraw();
		}

		/**
		 * 현재 그리드의 변경된 모든 데이터를 원본 데이터로 기억되도록 해줍니다.
		 */
		public commitData(): void {
			this._resetRealDeletedRowIfNeeded();
			this._resetDeletedRowIfNeeded();
			this._resetInsertedRowIfNeeded();

			if (this.selectionUnit != "column") {
				let isContinue: boolean = this._migrateSelection([data.tabledata.RowState.DELETED, data.tabledata.RowState.INSERTDELETED]);
				if (isContinue == false) {
					return;
				}
			}

			this._dataProvider._commitData();
			this.redraw();

		}

		// 엑셀 익스포트 API start //////////////////////////////////////////////////////////////////////////////
		/**
		 * Grid의 Data를 JSON 형식으로 반환합니다.
		 * <br>
		 * @param option Grid에 설정된 Style을 Export시 제외할 지 여부. default true.<br>
		 * 또는 export 옵션. <br>
		 * exceptStyle : Style을 Export시 제외할 지 여부. default true.<br>
		 * applyFormat : Format이 적용된 그대로의 텍스트를 반환할 지 여부. default true. number 데이터 타입을 익스포트하기 위해서는 해당 옵션을 false로 주어야 합니다.<br>
		 * useFormat : 엑셀 파일 (xlsx, xls 등)으로 익스포트시 해당 파일의 format속성을 사용할지 여부. default true. <br>
		 * applySuppress : 엑셀 익스포트시 suppress, mergedToIndexExpr에 의한 셀 병합을 반영할지 여부. default false. <br>
		 *                 applySuppress 설정시 rows 옵션을 지원되지 않습니다.<br>
		 * freezeHeader : Excel Export 시 그리드의 헤더 영역을 틀고정할지 여부. default false.<br>
		 * reduce : 불필요한 데이터를 제거할 지 여부. (ex. {}(empty json object)) default false.<br>
		 * excludeCellIndex : Export시 제외시킬 header cellIndex 배열. excludeCols 설정시 visible=false로 설정된 셀도 모두 포함합니다.<br>
		 * excludeColIndex : Export시 제외시킬 colIndex 배열. excludeCols 설정시 visible=false로 설정된 셀도 모두 포함합니다.<br>
		 * rows : Export시킬 특정 row index 배열.<br>
		 * rowDataHandler(datas: CellData[], rowIndex: number) : 엑셀 Export 시 행별 스타일 또는 데이터를 변경할 수 있는 핸들러.<br>
		 * rowgroupStyleHandler(cellStyle: utils.CellStyle, region: gridpart.VLOC_REGION, cellIndex: number, columnName: string) : 엑셀 Export 시 셀별 스타일 또는 포맷을 변경할 수 있는 핸들러.
		 * @return Grid의 Data.<br>
		 * {
		 * 		metadata : {password: string, printPageOrientation: "PORTRAIT" | "LANDSCAPE", wrapLineBreak : true | false},<br>
		 * 		name? : string,<br>
		 * 		freezepane? : {colsplit: number, rowsplit: number},<br>
		 * 		cols: { width: string }[],<br>
		 * 		rowgroups: {<br>
		 * 		&emsp; region: string, // header, detail, footer, gheader, gfooter<br>
		 * 		&emsp; style?: {<br>
		 * 		&emsp;&emsp; type: string, // string|number<br>
		 * 		&emsp;&emsp; rowindex: number,<br>
		 * 		&emsp;&emsp; colIndex: number,<br>
		 * 		&emsp;&emsp; rowSpan: number,<br>
		 * 		&emsp;&emsp; colSpan: number,<br>
		 * 		&emsp;&emsp; style?: {<br>
		 * 		&emsp;&emsp;&emsp; [styleName: string]: (string | number)<br>
		 * 		&emsp;&emsp; }}[],<br>
		 * 		&emsp; data: (string | number)[][]<br>
		 * 		&emsp; }[]
		 * }
		 * 
		 * @description
		 * 1. applyFormat=false로 설정시
		 * useFormat에 상관 없이 숫자타입으로 나와야하는 데이터에 대해서 모두 숫자형으로 반환됩니다.
		 *  - numbereditor, output(dataType=number)의 컨트롤이 배치된 경우.
		 *  - detail : 바인딩된 데이터셋 컬럼의 데이터타입이 number 또는 decimal인 경우
		 *  - detail 외 : formula 타입이 아니고, 숫자 데이터인 경우
		 * 
		 * 2. applyFormat=true & useFormat=true로 설정시
		 * numbereditor, output(dataType=number)의 컨트롤이 배치된 경우 대하여
		 * 숫자타입에 해당 포맷을 적용하여 반환합니다.
		 * (엑셀 포맷을 사용하고자 할 때 이렇게 설정해 주시기 바랍니다.)
		 * 
		 * 3. applyFormat=true & useFormat=false로 설정시
		 * 컨트롤에 보여지는 그대로 텍스트를 문자형으로 반환합니다.
		 * 
		 */
		public getExportData(option?: utils.ExportOption | boolean): utils.ExportData {
			if (this._gridExportUtil == null) {
				this._gridExportUtil = new gridpart.GridExportUtil(this);
			}
			return this._gridExportUtil._getData(option);
		}

