		/**
		 * 특정 셀이 브라우저 뷰 포트상에서 표시중인 바운즈를 얻습니다.
		 * @param region 바운즈를 얻을 셀이 위치하는 region. (ex. header, detail, footer, rowgroup)
		 * @param rowIndex 바운즈를 얻을 셀이 위치하는 row index. header, footer일 때는 null을 입력해주시기 바랍니다.
		 * @param cellIndex 바운즈를 얻을 셀의 cellIndex.
		 * @returns 
		 */
		public getCellBounds(region: string, rowIndex: number, cellIndex: number): geometry.Rectangle {

			let domTraverser: ufc.DOMTraverser = this._getCellElement(region, rowIndex, cellIndex);
			if (domTraverser == null) {
				return null;
			}

			let cellElement: HTMLElement = domTraverser._getElement();
			let rect: geometry.Rectangle = gridpart.GridUtil._getUnsetZoomByClientRect(cellElement);
			return rect;
		}

		/**
		 * 
		 * @param region 
		 * @param rowIndex 
		 * @param cellIndex 
		 * @returns 
		 */
		private _getCellElement(region: string, rowIndex: number, cellIndex: number, rowType: RowIndexType = RowIndexType.DATA): ufc.DOMTraverser {
			let regions: GRIDTARGET[] = [GRIDTARGET.HEADER, GRIDTARGET.DETAIL, GRIDTARGET.FOOTER, GRIDTARGET.ROWGROUP];
			if (regions.indexOf(region) == -1) {
				return null;
			}

			let rootNode: HTMLElement = this._getRenderer().getRootNode();
			let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(rootNode);
			if (region == GRIDTARGET.HEADER) {
				domTraverser = domTraverser._child(`[data-role="${GRIDROLE.COLUMN_HEADER}"][data-cellindex="${cellIndex}"]`);
			} else if (region == GRIDTARGET.FOOTER) {
				domTraverser = domTraverser._child(`[data-role="${GRIDROLE.FOOTER_CELL}"][data-cellindex="${cellIndex}"]`);
			} else if (region == GRIDTARGET.DETAIL) {
				let attrName = (rowType === RowIndexType.VIEW) ? "data-vrowindex" : "data-rowindex";
				let selector = `[role="${GRIDROLE.ROW}"][${attrName}="${rowIndex}"]`;
				let children: NodeList = domTraverser._children(selector);
				if (children) {
					for (var i = 0; i < children.length; i++) {
						let childTraverser: ufc.DOMTraverser = ufc._traverseFromElement(children[i] as HTMLElement);
						childTraverser = childTraverser._child(`[data-role="${GRIDROLE.GRID_CELL}"][data-cellindex="${cellIndex}"]`);
						if (childTraverser) {
							domTraverser = childTraverser;
							break;
						}
					}
				}
			} else if (region == GRIDTARGET.ROWGROUP) {
				let children: NodeList = domTraverser._children(`[role="${GRIDROLE.ROW}"][data-vrowindex="${rowIndex}"]`);
				if (children) {
					for (var i = 0; i < children.length; i++) {
						let childTraverser: ufc.DOMTraverser = ufc._traverseFromElement(children[i] as HTMLElement);
						childTraverser = childTraverser._child(`[data-role="${GRIDROLE.GRID_ROWGROUP_CELL}"][data-cellindex="${cellIndex}"]`);
						if (childTraverser) {
							domTraverser = childTraverser;
							break;
						}
					}
				}
			}

			return domTraverser;
		}

