		public override _createShape(): ufc.ControlShape {
			[GRIDREGION.TOP, GRIDREGION.MIDDLE, GRIDREGION.BOTTOM].forEach((loc: string) => { // 값이 변경되었거나 DataSet이 리로드 되었을 때 처리(Group이 갱신될 때와 생명주기가 일치하는지 여부 체크)
				this._context._needSuppressInfoReset(loc);
			});

			// this._clearStatisticCacheForRedraw();
			this._resetTemporalPropertiesIfNeeded();

			let gridRowCount: number = 0;
			if (this._context.getHeader() && this._context.getHeader().cellProp.length != 0) {
				gridRowCount += 1;
			}
			gridRowCount += this.getContentRowCount();
			if (this._context.isEnabledPart(GRIDREGION.FOOTER)) {
				gridRowCount += 1;
			}
			let gridColCount: number = this._context._getVisibleHeaderCells().length;
			if (gridColCount == 0) {
				gridColCount = this._context._getVisibleDetailCells().length;
			}

			// 그리드의 부모영역이 readonly된 경우
			if (this.isEditing() && this.readOnly == true) {
				this._setEditRowIndex(-1, true);
			}

			let gridShape: ufc.ControlShape = {
				tag: "div",
				styler: "root",
				attr: {
					role: "grid",
					tabindex: "-1"
				},
				style: { overflow: "hidden" },
				classNames: [],
				events: {
					"resize": this._onResize
				},
				nodename: this.type,
				eventTargets: [
					// Grid에서 내부적으로 사용하기 위해 draggable과 mouse 이벤트 추가
					ufc.EventTargetType.UICONTROL,
					ufc.EventTargetType.DROPPABLE,
					ufc.EventTargetType.DRAGGABLE,
					ufc.EventTargetType.MOUSE
				],
				children: [this.getLayout()._createLayoutShape()]
			};

			cpr.ufc.ShapeUtil._setAriaState(gridShape, { enabled: this.enabled, readOnly: this.readOnly });

			if (gridColCount > 0) {
				gridpart.GridUtil._setAria(gridShape, "colcount", "" + gridColCount);
			}
			if (gridRowCount > 0) {
				gridpart.GridUtil._setAria(gridShape, "rowcount", "" + gridRowCount);
			}

			cpr.ufc.ShapeUtil._setAriaLabelAttr(gridShape.attr, this._getFieldLabel());
			cpr.ufc.ShapeUtil._setTooltipAttr(gridShape, { owner: this, title: this.tooltip });

			// check filter open
			if (this._filterDialog && this._filterDialog._isOpen()) {
				gridShape.global = this._filterDialog._createShape();
			}

			if (this.context.isEnabledPart(GRIDREGION.LEFT)) {
				gridShape.classNames.push("cl-leftsplit");
			}
			if (this.context.isEnabledPart(GRIDREGION.RIGHT)) {
				gridShape.classNames.push("cl-rightsplit");
			}

			if (this.getRowCount() == 0) {
				gridShape.classNames.push("cl-empty");
			}

			if (this._gridDataVisible === true) {
				let griddataId: string = ufc.NodeUUIDMapper.INSTANCE._createPartialUUID(this, "griddata");
				gridShape.children[gridShape.children.length] = {
					tag: "div",
					style: {
						display: "none"
					},
					attr: {
						id: griddataId
					}
				};
				core.DeferredUpdateManager.INSTANCE.asyncExec(() => {
					let expData: utils.ExportData = this.getExportData({
						exceptStyle: true, applyFormat: true, useFormat: false, applySuppress: false
					});
					let tsvData: string = gridpart.GridExportUtil._convertToTSV(expData);
					expData = null;

					let dataContainer: HTMLElement = document.getElementById(griddataId);
					let textNode: Text = document.createTextNode(tsvData);
					dataContainer.appendChild(textNode);

					tsvData = null;
					textNode = null;
					dataContainer = null;
				});
			}

			return gridShape;
		}

