		/**
		 * 그리드의 자동 크기 지원 타입을 리턴합니다.
		 * 그리드는 자동 높이만 지원하고 css height 속성에 auto를 사용할 수 있음을 나타냅니다.
		 */
		public override _getAutoSizeAvailability(): layouts.AutoSizeType {
			return layouts.AutoSizeType.both;
		}

		public _measureSize(): geometry.Size {
			let size: geometry.Size = super._measureSize();
			// TODO 정해진 크기에 의해 스크롤이 생겨야 하는 경우에 대한 처리
			if (size.width == -1) {
				size.width = this._context._getMeasureGridWidth() + 2 /* border size */;
			}
			if (size.height == -1) {
				// 그리드가 autoHeight를 지원하면서 autoRowHeight를 지원할 경우 그리드의 높이는 그리면서 처리.
				if (this._context._hasAutoHeightColumn() === false) {
					size.height = this._context._getMeasureGridHeight() + 2 /* border size */;
				}
			}

			return size;
		}

