		private _onResize(e: UIEvent): void {
			let renderer: ufc.ControlRenderer = this._getRenderer();
			let rootNode: HTMLElement = renderer.getRootNode();
			if (rootNode) {
				// 그리드의 넓이가 변경되었을 경우에만 RowHeightCache를 초기화 함. #3737 #3739 #3740 #4407
				let rootSize: gridpart.ElSize = gridpart.GridUtil._getInnerSize(rootNode);
				if (rootSize.ow !== this._context._getRegionWidth(GRIDREGION.GRID, GRIDREGION.GRID)) {
					this._needClearRowHeightCache();
				}
			}
			this._onWindowResize();

			let container: Container = this.getParent();
			if (container) {
				container._applyChildSizeChanging(this);
			}

			this.redraw();
		}

		private _onWindowResize(): void {
			if (this._filterDialog && this._filterDialog._isOpen()) {
				this._filterDialog._close();
			}
		}

		private _onKeyboardOpen(): void {
			if (this._filterDialog && this._filterDialog._isOpen()) {
				this._filterDialog._redraw();
			}
		}

		private _onKeyboardClose(): void {
			if (this._filterDialog && this._filterDialog._isOpen()) {
				this._filterDialog._computePosition();
				// this._filterDialog._settingPosition();

				this._filterDialog._redraw();
			}
		}

