		/**
		 * 컨트롤의 Constraints를 변경합니다.<br>
		 * Parameter의 Constraints가 포함한 항목만 변경됩니다.<br>
		 * region(그리드 영역), cellIndex(셀 인덱스)는 변경할 수 없습니다.
		 * @param child 대상 컨트롤
		 * @param overridingConstraint 변경할 Constraints. (region, cellIndex 속성은 변경 불가)
		 * @return 변경 성공여부
		 */
		public override updateConstraint(child: UIControl, overridingConstraint: gridpart.layout.GridControlLayoutConstraint): boolean {
			let column: gridpart.GridColumn = this._getColumnByControl(child);
			if (column == null) {
				return false;
			}

			let change: boolean = false;
			let oldConstraint: gridpart.ControlConstraint = null;
			if (column._isConditionalControl()) {
				let conditionalId: string = (column as gridpart.GridDetailColumn)._getConditionalId(child as gridpart.GridUIControl);
				oldConstraint = (column as gridpart.GridDetailColumn)._getConditionalControlConstraint(conditionalId);
			} else {
				oldConstraint = column.cellProp.configuration.controlConstraint;
			}
			let keys: string[] = Object.keys(overridingConstraint);
			keys.forEach((key: string) => {
				if (Grid._VALID_CONSTRAINT_PROP.indexOf(key) != -1) {
					let newProp = overridingConstraint[key];
					if (["width", "height"].indexOf(key) != -1) {
						let size: utils.Size = utils.ParamUtil.parseSize(overridingConstraint[key]);
						newProp = size.size + size.unit;
					} else if (["topSpacing", "rightSpacing", "bottomSpacing", "leftSpacing"].indexOf(key) != -1) {
						let size: utils.Size = utils.ParamUtil.parseSize(overridingConstraint[key]);
						newProp = size.size;
					}
					if (oldConstraint[key] != newProp) {
						oldConstraint[key] = newProp;
						change = true;
					}
				}
			})

			if (!change) {
				return false;
			}

			this.redraw();
			return true;
		}

		/**
		 * 컨트롤의 Constraints를 교체합니다.<br>
		 * 기존 Constraints가 Parameter의 Constraints로 교체됩니다.<br>
		 * region(그리드 영역), cellIndex(셀 인덱스)는 변경할 수 없습니다.
		 * @param child 대상 컨트롤
		 * @param newConstraint 변경할 Constraints. (region, cellIndex 속성은 변경 불가)
		 * @return 변경 성공여부
		 */
		public override replaceConstraint(child: UIControl, newConstraint: gridpart.layout.GridControlLayoutConstraint): boolean {
			let column: gridpart.GridColumn = this._getColumnByControl(child);
			if (column == null) {
				return false;
			}

			let oldConstraint: gridpart.ControlConstraint = null;
			if (column._isConditionalControl()) {
				let conditionalId: string = (column as gridpart.GridDetailColumn)._getConditionalId(child as gridpart.GridUIControl);
				oldConstraint = (column as gridpart.GridDetailColumn)._getConditionalControlConstraint(conditionalId);
			} else {
				oldConstraint = column.cellProp.configuration.controlConstraint;
			}
			let controlType: string = column.controlType;
			Grid._VALID_CONSTRAINT_PROP.forEach((key: string) => {
				if (key != "region" && key != "cellIndex") {
					let propValue = null;
					if (newConstraint.hasOwnProperty(key)) {
						propValue = newConstraint[key];
					} else {
						propValue = this.context._getControlDefaultConstraint(controlType, key);
					}
					if (["width", "height", "topSpacing", "rightSpacing", "bottomSpacing", "leftSpacing"].indexOf(key) != -1) {
						let size: utils.Size = utils.ParamUtil.parseSize(newConstraint[key]);
						let unit: string = size.unit ?? "px";
						propValue = size.size + unit;
					}
					oldConstraint[key] = propValue;
				}
			});

			this.redraw();
			return true;
		}

		/**
		 * 해당 컨트롤의 제약 조건을 반환합니다.
		 * @param child 반환하고자 하는 컨트롤.
		 * @return {gridpart.layout.GridControlLayoutConstraint} 해당하는 제약조건.
		 */
		public override getConstraint(child: UIControl): gridpart.layout.GridControlLayoutConstraint {
			if (this._context == null) {
				return null;
			}
			let constraint = super.getConstraint(child) as gridpart.layout.GridControlLayoutConstraint;
			let column: gridpart.GridColumn = this._getColumnByControl(child);
			if (column == null) {
				return null;
			}

			let cellConstraint: gridpart.ControlConstraint = null;
			if (column._isConditionalControl()) {
				let conditionalId: string = (column as gridpart.GridDetailColumn)._getConditionalId(child as gridpart.GridUIControl);
				cellConstraint = (column as gridpart.GridDetailColumn)._getConditionalControlConstraint(conditionalId);
			} else {
				cellConstraint = column.cellProp.configuration.controlConstraint;
			}
			let keys: string[] = Object.keys(cellConstraint);
			let ctrlLayoutConstraint: gridpart.layout.GridControlLayoutConstraint = {
				region: constraint["region"],
				cellIndex: constraint["cellIndex"]
			};

			keys.forEach((key: string) => {
				if (Grid._VALID_CONSTRAINT_PROP.indexOf(key) != -1) {
					let constraint = cellConstraint[key];
					if (["topSpacing", "rightSpacing", "bottomSpacing", "leftSpacing"].indexOf(key) != -1) {
						let size: utils.Size = utils.ParamUtil.parseSize(constraint);
						constraint = size.size + "px";
					}
					ctrlLayoutConstraint[key] = constraint;
				}
			})

			return ctrlLayoutConstraint;
		}

		private _getColumnByControl(control: UIControl): gridpart.GridColumn {
			let constraint = super.getConstraint(control) as gridpart.layout.GridControlLayoutConstraint;
			if (constraint == null) {
				return null;
			}
			let region: string = constraint["region"];
			let cellIndex: number = constraint["cellIndex"];
			let column: gridpart.GridColumn = null;
			switch (region) {
				case GRIDREGION.HEADER: {
					column = this.header.getColumn(cellIndex);
					break;
				}
				case GRIDREGION.DETAIL: {
					column = this.detail.getColumn(cellIndex);
					break;
				}
				case GRIDREGION.FOOTER: {
					column = this.footer.getColumn(cellIndex);
					break;
				}
				case GRIDREGION.GHEADER:
				case GRIDREGION.GFOOTER: {
					let rowgroup = this.getRowGroup(constraint[Grid._GROUP_CONDITION_], region as "gheader" | "gfooter");
					if (rowgroup) {
						column = rowgroup.getColumn(cellIndex);
					}
					break;
				}
			}
			return column;
		}

