		// TabKey를 이용한 포커스 이동을 위한 컨트롤 목록을 조회한다.
		public override _getShowingChildren(): UIControl[] {
			if (this.visible == false) {
				return [];
			}
			let ctrls: UIControl[] = [];
			let regions: string[] = [GRIDREGION.HEADER, GRIDREGION.FOOTER];
			let tabMode: string = this.tabMode;
			if (this.isEditing() && tabMode != "none") {
				regions[regions.length] = GRIDREGION.DETAIL;
			}
			let childrenInfo = this._getChildrenInfo();
			childrenInfo.forEach((ctrl: UIControl, constraint: layouts.Constraint, index: number) => {
				if (ctrl && constraint) {
					let region: string = constraint["region"];
					if (region && regions.indexOf(region) != -1) {
						ctrls[ctrls.length] = ctrl;
					}
				}
			});

			return ctrls;
		}

