		public _performScroll(scrollPaneCluster: gridpart.layout.ScrollPaneCluster, scrollPane: gridpart.layout.ScrollPane, left: number, top: number, changedX: boolean, changedY: boolean): void {
			let axis: events.ScrollAxis = null;
			if (changedX && changedY) {
				axis = scrollPaneCluster._postScroll(scrollPane, top, left, null);
			} else if (changedY) {
				axis = scrollPaneCluster._postScrollTop(scrollPane, top, null);
			} else if (changedX) {
				axis = scrollPaneCluster._postScrollLeft(scrollPane, left, null);
			} else {
				return;
			}

			if (axis !== null) {
				this._context._dispatchScrollEvent(null, {
					axis: axis,
					scrollTop: scrollPaneCluster._getScrollTop(scrollPane.location),
					maxScrollTop: scrollPane._getMaxScrollTop(),
					scrollLeft: scrollPaneCluster._getScrollLeft(scrollPane.region),
					maxScrollLeft: scrollPane._getMaxScrollLeft()
				});
			}
		}

		/**
		 * 그리드에 스크롤이 포함된 경우, 해당 위치로 스크롤합니다.
		 * @param left 스크롤 할 x 좌표. (-1로 설정시 top으로 전달한 y좌표만 설정됩니다.)
		 * @param top 스크롤 할 y 좌표. (-1로 설정시 left으로 전달한 x좌표만 설정됩니다.)
		 * @param duration 스크롤 애니메이션의 길이. 단위는 초입니다.
		 * @param timingFunction 애니메이션을 사용할 경우에 적용될 타이밍 함수.
		 */
		public override scrollTo(left: number, top: number, duration = 0, timingFunction = animation.TimingFunction.EASE_IN_OUT): void {
			let layout: gridpart.layout.GridControlLayout = this.getLayout() as gridpart.layout.GridControlLayout;
			let tablePane: gridpart.layout.TablePane = layout._getTablePane(GRIDREGION.CENTER);
			let scrollPane: gridpart.layout.ScrollPane = tablePane._getScrollPane(GRIDREGION.MIDDLE);
			let scrollPaneCluster: gridpart.layout.ScrollPaneCluster = layout._getScrollPaneCluster();

			if (this._scrollAnimator) {
				this._scrollAnimator.stop();
				this._scrollAnimator = null;
			}

			let scrollLeftStart = scrollPaneCluster._getScrollLeft(scrollPane.region);
			let scrollTopStart = scrollPaneCluster._getScrollTop(scrollPane.location);

			if (left == -1) left = scrollLeftStart;
			if (top == -1) top = scrollTopStart;

			left = utils.Util.clamp(left, 0, scrollPane._getMaxScrollLeft());
			top = utils.Util.clamp(top, 0, scrollPane._getMaxScrollTop());

			if (duration > 0) {
				if (left === scrollLeftStart && top === scrollTopStart) {
					return;
				}

				let gapX = left - scrollLeftStart;
				let gapY = top - scrollTopStart;

				this._scrollAnimator = new animation.Animator(duration, timingFunction);
				this._scrollAnimator.addTask((m: number) => {
					if (this.disposed) {
						this._scrollAnimator.stop();
						return;
					}
					let newX = scrollLeftStart + gapX * m;
					let newY = scrollTopStart + gapY * m;
					this._performScroll(scrollPaneCluster, scrollPane, newX, newY, gapX !== 0, gapY !== 0);
				});
				this._scrollAnimator.run();
				return;
			}

			this._performScroll(scrollPaneCluster, scrollPane, left, top, left !== scrollLeftStart, top !== scrollTopStart);
		}

		/**
		 * 
		 * @param deltaX 가로스크롤을 현재 기준(0)으로 부터 이동시킬 상대 값. (0로 설정시 y좌표만 설정됩니다.)
		 * @param deltaY 세로스크롤을 현재 기준(0)으로 부터 이동시킬 상대 값. (0로 설정시 x좌표만 설정됩니다.)
		 */
		public _scrollByRelative(deltaX: number, deltaY: number, region: string, loc: string): void {
			let layout: gridpart.layout.GridControlLayout = this.getLayout() as gridpart.layout.GridControlLayout;
			let tablePane: gridpart.layout.TablePane = layout._getTablePane(region);
			let scrollPane: gridpart.layout.ScrollPane = tablePane._getScrollPane(loc);
			let maxLeft: number = scrollPane._getMaxScrollLeft();
			let maxTop: number = scrollPane._getMaxScrollTop();
			let left: number = scrollPane._getViewportScrollLeft() + deltaX;
			let top: number = scrollPane._getViewportScrollTop() + deltaY;
			if (maxLeft == 0) { deltaX = 0; }
			if (maxTop == 0) { deltaY = 0; }

			if (left > maxLeft) {
				left = maxLeft;
			} else if (left < 0) {
				left = 0;
			}
			if (top > maxTop) {
				top = maxTop;
			} else if (top < 0) {
				top = 0;
			}

			let scrollPaneCluster: gridpart.layout.ScrollPaneCluster = layout._getScrollPaneCluster();
			this._performScroll(scrollPaneCluster, scrollPane, left, top, deltaX !== 0, deltaY !== 0);
		}

