		public _setFilterDialog(filterConditions: data.GridFilterCondition[]): void {
			if (this._context.editingRowIndex != -1 && filterConditions?.length != 0) {
				let editingRow: provider.GridRow = this._dataProvider.getRow(this._context.editingRowIndex);

				let isFilteredRow = false;
				_stream(filterConditions)
					.find((condition: data.GridFilterCondition) => {
						if (condition.valueSet.has(editingRow.getString(condition.colNm)) == false) {
							isFilteredRow = true;
							return true;
						}
					});

				let isContinue: boolean = true;
				if (isFilteredRow) {
					isContinue = this.setEditRowIndex(-1, true);
				}
				if (isContinue == false) {
					return;
				}
			}

			this._dataProvider._setGridFilter(filterConditions);

			// selection 갱신을 위해 완전삭제행과 삭제행 갱신
			this._resetRealDeletedRowIfNeeded();
			this._resetDeletedRowIfNeeded();
			this._refreshSelectionIfNeeded();
		}

