		/**
		 * 헤더 필터 팝업시 필터 정보 설정
		 * 
		 * <ListDataBindable 계열 (콤보박스 등) label로 보이기 기능추가 사항>
		 * 헤더 셀 영역의 포함되는 모든 디테일 셀 중 targetColumnName으로 바인딩된 셀의 컨트롤을 찾는다.
		 * 만약 targetColumnName으로 바인딩된 컨트롤이 여러 개인 경우 아이템셋 계열 컨트롤에 우선순위를 둔다.
		 * 
		 * @param headerCellIndex 
		 * @param targetColumn 
		 * @param dombound 
		 */
		public _openFilterDialog(headerCellIndex: number, targetColumn: string/*, dombound: { left: number, top: number }*/): void { // GridEventController
			if (!this._filterDialog) {
				return;
			}
			let openFilterCol: string = targetColumn;
			let openFilterControl: gridpart.GridUIControl = null;
			let filterDlgTitle: string = null;
			let backupFilterCondition: data.GridFilterCondition[] = null;

			// 필터 조건에 맞는 컨트롤 찾기
			let detailCellIndices: number[] = this.getDetailCellIndices(headerCellIndex);
			detailCellIndices.sort().some((detailCellIndex: number) => {
				let dColumn: gridpart.GridDetailColumn = this.detail.getColumn(detailCellIndex);
				if (dColumn.columnName == targetColumn) {
					let control: gridpart.GridUIControl = dColumn.control as gridpart.GridUIControl;
					if (control) {
						openFilterControl = control;
						return true;
					}
				}
				return false;
			});

			let headerColumn: gridpart.GridHeaderColumn = this.header.getColumn(headerCellIndex) as gridpart.GridHeaderColumn;
			let bindContext: bind.GridEmbeddedContext = this.getBindContext() as bind.GridEmbeddedContext;
			if (headerColumn != null && headerColumn && bindContext) {
				let beforeHeaderCellIndex: number = bindContext._getHeaderCellIndex();
				bindContext._setHeaderCellIndex(headerCellIndex);
				filterDlgTitle = headerColumn.filterDialogTitle;
				bindContext._setHeaderCellIndex(beforeHeaderCellIndex);
			}
			if (filterDlgTitle === null || filterDlgTitle === "") {
				let i18n: I18N = I18N.INSTANCE;
				filterDlgTitle = i18n.message(core.PlatformTerms.FILTER_CONFIG); // 필터설정
			} else {
				filterDlgTitle = utils.Util.toString(filterDlgTitle);
			}

			backupFilterCondition = this._dataProvider._getFilterCondition(false);

			this._filterDialog._open(headerCellIndex, openFilterCol, openFilterControl, filterDlgTitle, backupFilterCondition);

			this.redraw();
		}

		/**
		 * 필터 팝업을 오픈합니다.<br/>
		 * cell index의 targetColumn은 반드시 설정되어 있어야합니다.<br/>
		 * cell index의 filterable 값과 상관없이 필터 팝업을 오픈합니다.
		 * @param headerCellIndex 필터 팝업의 대상 cell index.
		 */
		public openFilterDialog(headerCellIndex: number): void {
			let header: gridpart.GridHeaderColumn = this.header.getColumn(headerCellIndex);
			if (header == null || header.visible == false) {
				return;
			}

			let targetColumnName: string = header.targetColumnName;
			if (targetColumnName == null) {
				return;
			}
			cpr.core.DeferredUpdateManager.INSTANCE.asyncExec(() => {
				this._jumpHeaderCell(headerCellIndex);
				this._openFilterDialog(headerCellIndex, targetColumnName);
			});
		}

