		// header checkebox sync
		private _needSyncHeaderCheckBox(): void {
			if (this._neededSyncHeaderCheckBox === true) {
				return;
			}
			// check exists header checkbox
			let hasHeaderCheckBox: boolean = false;
			let headerCellProps: gridpart.GridHeaderCellProp[] = this._context._getHeaderCellProps();
			for (let i = 0; i < headerCellProps.length; i++) {
				let headerCellProp: gridpart.GridHeaderCellProp = headerCellProps[i];
				if (headerCellProp?.configuration?.columnType == "checkbox") {
					hasHeaderCheckBox = true;
					break;
				}
			}
			if (hasHeaderCheckBox === true) {
				this._neededSyncHeaderCheckBox = true;
				this._getAllHeaders().forEach(item => this._applyPiece(item));
			}
		}
		private _syncHeaderCheckBoxIfNeeded(): void {
			if (this._neededSyncHeaderCheckBox === true) {
				let rowCount = this.rowCount;
				if (rowCount == 0) {
					this._checkHeader = CHECKMODE.UNCHECKED;
				} else {
					let checkRowCount: number = this.getCheckRowIndices().length;
					if (checkRowCount == 0) {
						this._checkHeader = CHECKMODE.UNCHECKED;
					} else if (checkRowCount == rowCount) {
						this._checkHeader = CHECKMODE.CHECKED;
					} else { // checkRowCount < rowCount
						this._checkHeader = this._getPartialCheckState(0, this.rowCount - 1);
					}
				}
			}
			this._neededSyncHeaderCheckBox = false;
		}

