		// selection handle
		private _needRefreshSelection(): void {
			this._neededSelectionRefresh = true;
		}
		private _refreshSelectionIfNeeded(): void {
			if (this._neededSelectionRefresh == true) {
				this._refreshSelection();
			}
		}
		private _refreshSelection(): void {
			if (this._gridSelector._isSelectionStarted() || this._gridSelector._isSelectionPaused()) {
				// mouseup이 일어나기 전에 refreshSelection이 일어나는 경우 이전 selection을 commit하지 않도록 함.
				// mousedown → value-change에서 sort → refreshSelection
				this._gridSelector._endSelection(false);
			}

			let beforeSelection: number[] | gridpart.selection.CellPosition[] = this._gridSelector._getSelectedIndices();

			this._gridSelector._refreshSelection();
			this._neededSelectionRefresh = false;

			let afterSelection: number[] | gridpart.selection.CellPosition[] = this._gridSelector._getSelectedIndices();
			if (_.isEqual(beforeSelection, afterSelection) == false) {
				this.dispatchEvent(new events.CGridEvent(events.GridEventType._SELECTION_REFRESH));

				if (afterSelection.length == 0) {
					this.dispatchEvent(new events.CGridSelectionEvent(events.GridEventType.SELECTION_DISPOSE, {
						oldSelection: beforeSelection,
						newSelection: afterSelection
					}));
				}
			}
			this._context._refreshEditingRowIndex(false);
		}

