		public _isRequiredEditRowChange(rowIndex: number): boolean {
			if ((this._isReadOnly() === true && rowIndex != -1) || this._context.editingRowIndex === rowIndex) {
				return false;
			}
			if (rowIndex != -1) {
				let state: data.tabledata.RowState = this.getRowState(rowIndex);
				if (state == data.tabledata.RowState.DELETED ||
					state == data.tabledata.RowState.INSERTDELETED) {
					return false;
				}
			}
			return true;
		}
		public _fireBeforeSelectionChangeEvent(oldSelection: (number[] | gridpart.selection.CellPosition[]),
			newSelection: (number[] | gridpart.selection.CellPosition[])): boolean {
			if (this.selectionMulti == "none" || _.isEqual(oldSelection, newSelection)) {
				return true;
			}
			let beforeSelectionEvent: events.CSelectionEvent = new events.CSelectionEvent(
				events.SelectionEventType.BEFORECHANGE,
				{ oldSelection: oldSelection, newSelection: newSelection });

			let isContinue: boolean = this.dispatchEvent(beforeSelectionEvent);

			return isContinue;
		}
		public _fireBeforeEditRowChangeEvent(newEditRowIndex: number, isCommit: boolean): boolean {
			let beforeEditRowChangeEvent: events.CGridSelectionEvent = new events.CGridSelectionEvent(
				events.GridEventType.BEFORE_EDITROW_CHANGE,
				{
					relativeTargetName: "detail",
					oldSelection: this.getRow(this._context.editingRowIndex),
					newSelection: newEditRowIndex == -1 ? null : this.getRow(newEditRowIndex),
					isCommit: isCommit
				});

			let isContinue: boolean = this.dispatchEvent(beforeEditRowChangeEvent);

			return isContinue;
		}
		public _fireBeforeChangeEvent(newSelection: (number[] | gridpart.selection.CellPosition[]),
			newEditRowIndex: number, isCommit: boolean): boolean {

			let oldSelection: (number[] | gridpart.selection.CellPosition[]) = this.getSelectedIndices();
			let isContinue: boolean = this._fireBeforeSelectionChangeEvent(oldSelection, newSelection);
			if (isContinue && (this.isEditing() || this.clickMode == "edit")) {
				let editRowIndex: number = this._context.editingRowIndex;
				if (editRowIndex != newEditRowIndex) {
					isContinue = this._fireBeforeEditRowChangeEvent(newEditRowIndex, isCommit);
				}
			}

			return isContinue;
		}

		private _migrateSelection(exceptStates: data.tabledata.RowState[]): boolean {
			let selectedIndices: number[] | gridpart.selection.CellPosition[] = this.getSelectedIndices();
			if (selectedIndices.length > 0) {
				let tobeSelection: number[] | gridpart.selection.CellPosition[] = [].concat(selectedIndices);
				for (let i = (tobeSelection.length - 1); i >= 0; i--) {
					let rowIndex: number = (this.selectionUnit == "row") ? (tobeSelection[i] as number) : (tobeSelection[i] as gridpart.selection.CellPosition).rowIndex;
					let gridRow: provider.GridRow = this.getRow(rowIndex);
					let rowState: data.tabledata.RowState = gridRow.getState();
					if (exceptStates.indexOf(rowState) != -1) {
						tobeSelection.splice(i, 1);
					}
				}
				let isContinue: boolean = true;
				if (_.isEqual(selectedIndices, tobeSelection) == false) {
					if (tobeSelection.length == 0) {
						isContinue = this._fireBeforeChangeEvent(tobeSelection, -1, true);
						if (isContinue) {
							this._clearSelection(selectedIndices);
						}
					} else {
						// 편집행이 사라지는 경우 마지막 선택행을 편집행으로 설정
						let editRowIndex: number = this._context.editingRowIndex;
						let tobeSelectionRowIndices: number[] = [];
						if (typeof (tobeSelection[tobeSelection.length - 1]) == "number") {
							tobeSelectionRowIndices = tobeSelection as number[];
						} else {
							tobeSelectionRowIndices = (tobeSelection as gridpart.selection.CellPosition[]).map((selection: gridpart.selection.CellPosition) => {
								return selection.rowIndex;
							});
						}
						if (tobeSelectionRowIndices.indexOf(editRowIndex) == -1) {
							editRowIndex = -1; //tobeSelectionRowIndices[tobeSelectionRowIndices.length - 1];
						}
						isContinue = this._fireBeforeChangeEvent(tobeSelection, editRowIndex, true);
						if (isContinue) {
							this._setSelection(selectedIndices, tobeSelection, editRowIndex);
						}
					}
				}
				return isContinue;
			}
			return true;
		}

		/**
		 * @private
		 */
		public _getSortCondition(columnName: string, emptyValueSort: string): string {
			let sortCondition: string = null;
			if (emptyValueSort == null) {
				emptyValueSort = this._sort_emptyValueSort;
			}
			if (emptyValueSort == EMPTYVALUESORT.NULL_LAST) {
				sortCondition = "(" + columnName + "===\"\"?null:" + columnName + ")"; // 공백 있으면 안됨. asc, desc 구분어려워짐
			} else if (emptyValueSort == EMPTYVALUESORT.EMPTY_STRING) {
				sortCondition = "(" + columnName + "===null?\"\":" + columnName + ")"; // 공백 있으면 안됨. asc, desc 구분어려워짐
				// sortCondition = columnName;
			}
			return sortCondition;
		}

		public _setRowHeight(bandType: string, rowHeight: number): void {
			this._setRowHeightByRegion(GRIDREGION.LEFT, bandType, rowHeight); // left
			this._setRowHeightByRegion(GRIDREGION.CENTER, bandType, rowHeight); // center
			this._setRowHeightByRegion(GRIDREGION.RIGHT, bandType, rowHeight); // right
		}

		private _setRowHeightByRegion(region: string, bandType: string, rowHeight: number): void {
			let tableInfo: { band: gridpart.AbstractGridPart, constraints: GridBandConstraint }[] = this._getTableInfo()[region];
			if (tableInfo == null) {
				return;
			}
			let length: number = tableInfo.length;
			for (let i = 0; i < length; i++) {
				if (tableInfo[i].constraints.vloc == bandType) {
					tableInfo[i].band._setContentHeight(rowHeight);
				}
			}
		}

