namespace cpr {
	/**
	 * 바디에서 엘리먼트의 위치와 크기를 반환합니다.
	 * @param ele 
	 * @param useRound 
	 * @returns 
	 */
	export function _getOffsetRectFromViewport(ele: HTMLElement, useRound: boolean = true): geometry.Rectangle {
		let rect: geometry.Rectangle = _getUnscaledClientRect(ele);

		rect.top += _getUnscaledViewportScroll(window.pageYOffset || document.documentElement.scrollTop);
		rect.left += _getUnscaledViewportScroll(window.pageXOffset || document.documentElement.scrollLeft);

		if (useRound) {
			rect.width = Math.round(rect.width);
			rect.height = Math.round(rect.height);
			rect.top = Math.round(rect.top);
			rect.left = Math.round(rect.left);
		}
		return rect;
	}

	/**
	 * 도큐먼트의 세로 스크롤 값을 반환합니다.
	 * @param scaled 
	 * @returns 
	 */
	export function _getViewportScrollTop(scaled: boolean = true) {
		let scrollTop = window.pageYOffset || document.documentElement.scrollTop || 0;
		if (scaled) {
			return _getUnscaledViewportScroll(scrollTop);
		}
		return scrollTop;
	}

	/**
	 * 도큐먼트의 가로 스크롤 값을 반환합니다.
	 * @param scaled 
	 * @returns 
	 */
	export function _getViewportScrollLeft(scaled: boolean = true) {
		let scrollLeft = window.pageXOffset || document.documentElement.scrollLeft || 0;
		if (scaled) {
			return _getUnscaledViewportScroll(scrollLeft);
		}
		return scrollLeft;
	}

	/**
	 * 모바일 또는 PC브라우저의 뷰포트의 크기를 반환합니다. 
	 * 모바일의 경우 document.documentElement의 크기보다 큰 경우가 발생하는데 visualViewport에서 확인하도록 도와줍니다.
	 * @param scaled 
	 * @returns 
	 */
	export function _getVisualViewportRect(scaled: boolean = false): geometry.Rectangle {
		let rect: geometry.Rectangle = new geometry.Rectangle();
		let isMobile = utils.Util.detectBrowser().mobile;
		if (scaled) {
			if (isMobile && window.visualViewport) { // visualViewport는 documentElement의 크기를 반환합니다.
				rect.height = window.visualViewport.height;
				rect.width = window.visualViewport.width;
			} else {
				rect = geometry.Rectangle.clientBoundsOf(document.body);
			}
			rect.top = _getViewportScrollTop(false);
			rect.left = _getViewportScrollLeft(false);
		} else {
			if (isMobile && window.visualViewport) {
				let zoom = _getZoom();
				rect.width = window.visualViewport.width * (1 / zoom);
				rect.height = window.visualViewport.height * (1 / zoom);
			} else {
				rect = _getUnscaledClientRect(document.body);
			}
			rect.top = _getViewportScrollTop(true);
			rect.left = _getViewportScrollLeft(true);
		}
		return rect;
	}
	type ViewportMeasurePositionType = "both" | "center" | "reverseBoth";

	type ViewportOverflowType = "altViewport" | "normal";

	type ViewportSpaceOptions = {
		/**
		 * 세로 방향에서 측정 위치를 설정합니다.
		 */
		verticalMeasurePosition?: ViewportMeasurePositionType
		/**
		 * 가로 방향에서 측정 위치를 설정합니다.
		 */
		horizontalMeasurePosition?: ViewportMeasurePositionType
		/**
		 * 왼쪽 방향에서 뷰포트의 값 보다 큰 경우 뷰포트로 대체할지 여부를 설정합니다.
		 */
		leftOverflow?: ViewportOverflowType
		/**
		 * 위쪽 방향에서 뷰포트의 값 보다 큰 경우 뷰포트로 대체할지 여부를 설정합니다.
		 */
		topOverflow?: ViewportOverflowType
		/**
		 * 오른쪽 방향에서 뷰포트의 값 보다 큰 경우 뷰포트로 대체할지 여부를 설정합니다.
		 */
		rightOverflow?: ViewportOverflowType
		/**
		 * 아래쪽 방향에서 뷰포트의 값 보다 큰 경우 뷰포트로 대체할지 여부를 설정합니다.
		 */
		bottomOverflow?: ViewportOverflowType
		/**
		 * viewport의 세로 여백 값
		 */
		verticalMargin?: number
		/**
		 * viewport의 가로 여백 값
		 */
		horizontalMargin?: number

		/**
		 * 가로 위치의 공간을 측정을 정의합니다.
		 * @param type 
		 * @param rect 
		 * @param viewportRect 
		 * @returns 
		 */
		customHorizontalMeasurePosition?: (type: "left" | "right", rect: geometry.Rectangle, viewportRect: geometry.Rectangle) => number

		/**
		 * 세로 위치의 공간을 측정을 정의합니다.
		 * @param type 
		 * @param rect 
		 * @param viewportRect 
		 * @returns 
		 */
		customVerticalMeasurePosition?: (type: "top" | "bottom", rect: geometry.Rectangle, viewportRect: geometry.Rectangle) => number

		/**
		 * 방향에 따라 뷰포트를 넘어갔을 때 조건을 조정합니다.
		 * @param type 
		 * @param result 기본 결과
		 * @param rect 타겟의 도큐먼트 스크롤을 포함한 위치와 크기
		 * @param viewportRect 뷰포트의 도큐먼트 스크롤을 포함한 위치와 크기
		 * @returns 
		 */
		overflowConditionHandler?: (type: "top" | "bottom" | "left" | "right", result: boolean, rect: geometry.Rectangle, viewportRect: geometry.Rectangle) => boolean
	}

	function _overflowCondition(type: "top" | "bottom" | "left" | "right", spaceInsets: geometry.Insets, targetRect: geometry.Rectangle, viewportRect: geometry.Rectangle, customConditionHandler: (type, result, rect, viewportRect) => boolean): boolean {
		let result = false;

		switch (type) {
			case "top": {
				result = spaceInsets.top - viewportRect.height > 0;
				break;
			}
			case "bottom": {
				result = spaceInsets.bottom - viewportRect.height > 0;
				break;
			}
			case "left": {
				result = spaceInsets.left - viewportRect.width > 0;
				break;
			}
			case "right": {
				result = spaceInsets.right - viewportRect.width > 0;
				break;
			}
		}
		if (customConditionHandler) {
			result = customConditionHandler(type, result, targetRect, viewportRect) ?? false;
		}
		return result;
	}

	/**
	 * 엘리먼트와 뷰포트의 4방향 거리를 계산합니다.
	 * @param target 
	 * @param options 
	 * @returns 
	 */
	export function _getComputedSpaceInsets(target: HTMLElement, options?: ViewportSpaceOptions): geometry.Insets {
		options = _defaults({}, options,
			{
				verticalMeasurePosition: "both",
				horizontalMeasurePosition: "both",
				leftOverflow: "normal",
				rightOverflow: "normal",
				topOverflow: "normal",
				bottomOverflow: "normal",
				horizontalMargin: 0,
				verticalMargin: 0,
				customHorizontalMeasurePositoin: null,
				customVertivalMeasurePositoin: null,
				overflowConditionHandler: null
			} as ViewportSpaceOptions
		);

		let rect = _getOffsetRectFromViewport(target);
		let viewportRect = _getVisualViewportRect();
		let result = new geometry.Insets(0, 0, 0, 0);

		viewportRect.shrink(options.horizontalMargin, options.verticalMargin);
		if (options.customVerticalMeasurePosition) {
			result.top = options.customVerticalMeasurePosition("top", rect, viewportRect);
			result.bottom = options.customVerticalMeasurePosition("bottom", rect, viewportRect);
		} else {
			switch (options.verticalMeasurePosition) {
				case "both": {
					result.top = rect.top - viewportRect.top;
					result.bottom = viewportRect.bottom - rect.bottom;
					break;
				}
				case "center": {
					result.top = rect.center.y - viewportRect.top;
					result.bottom = viewportRect.bottom - rect.center.y;
					break;
				}
				case "reverseBoth": {
					result.top = rect.bottom - viewportRect.top;
					result.bottom = viewportRect.bottom - rect.top;
					break;
				}
			}
		}
		if (options.topOverflow == "altViewport" && _overflowCondition("top", result, rect, viewportRect, options.overflowConditionHandler)) {
			result.top = viewportRect.height;
		}
		if (options.bottomOverflow == "altViewport" && _overflowCondition("bottom", result, rect, viewportRect, options.overflowConditionHandler)) {
			result.bottom = viewportRect.height;
		}
		if (options.customHorizontalMeasurePosition) {
			result.left = options.customHorizontalMeasurePosition("left", rect, viewportRect);
			result.right = options.customHorizontalMeasurePosition("right", rect, viewportRect);
		} else {
			switch (options.horizontalMeasurePosition) {
				case "both": {
					result.left = rect.left - viewportRect.left;
					result.right = viewportRect.right - rect.right;
					break;
				}
				case "center": {
					result.left = rect.center.x - viewportRect.left;
					result.right = viewportRect.right - rect.center.x;
					break;
				}
				case "reverseBoth": {
					result.left = rect.right - viewportRect.left;
					result.right = viewportRect.right - rect.left;
					break;
				}
			}
		}
		if (options.leftOverflow == "altViewport" && _overflowCondition("left", result, rect, viewportRect, options.overflowConditionHandler)) {
			result.left = viewportRect.width;
		}
		if (options.rightOverflow == "altViewport" && _overflowCondition("right", result, rect, viewportRect, options.overflowConditionHandler)) {
			result.right = viewportRect.width;
		}
		return result;
	}

	/**
	 * 숫자가 포함된 텍스트를 숫자로 변환합니다.
	 * @param text 
	 * @returns 
	 */
	export function _parseFloat(text: string, fallback: number = 0): number {
		try {
			return parseFloat(text);
		} catch (e) {
			return fallback;
		}
	}

	/**
	 * DrawLazyTask 생성 메서드.
	 * @param obj 
	 * @returns 
	 */
	export function _createDrawLazyTask(obj: { nodename: string; task: () => ufc.ElementShape; owner?: core.DrawableControl }): ufc.DrawLazyTask {
		return new ufc.DrawLazyTask(obj.nodename, obj.task, obj?.owner);
	}

	/**
	 * TapLazyTask 생성 메서드.
	 * @param obj 
	 * @returns 
	 */
	export function _createTapLazyTask(obj: { task: () => void }): ufc.TapLazyTask {
		return new ufc.TapLazyTask(obj.task);
	}

}