namespace cpr {
	const _NO_VALUE_: any = new Object();

	type PreResolve<T> = {
		present: boolean
		value: T
		consumed: boolean
	};

	function _isUnconsumed(info: PreResolve<any>): boolean {
		return info && info.consumed === false;
	}

	function _consume<T>(info: PreResolve<T>): T {
		info.consumed = true;
		return info.value;
	}

	export type FilterNullOptions = {
		keepNull: boolean
		keepUndefined: boolean
	}

	export type ElementOf<T> =
		T extends (infer Item)[]
		? Item
		: T extends Stream<infer Item>
		? Item
		: any;

	interface SearchFrame<T> {
		sibilings: T[]
		index: number
	}

	export type JoinOptions<T> = {
		before?: string,
		separator: string,
		after?: string,
		stringify?: (element: T) => string
	}

	/**
	 * @internal
	 */
	export abstract class Stream<T> {
		abstract hasNext(): boolean;
		abstract next(): T;

		forEach(iteratee: (each: T) => void): void {
			while (this.hasNext()) {
				iteratee(this.next());
			}
		}

		find(predicate: (e: T) => boolean): T {
			while (this.hasNext()) {
				let next = this.next();
				if (predicate(next)) {
					return next;
				}
			}
			return null;
		}

		last(): T {
			let result: T = null;
			while (this.hasNext())
				result = this.next();

			return result;
		}

		drop(count: number): Stream<T> {
			while (count-- > 0 && this.hasNext()) {
				this.next();
			}
			return this;
		}

		/**
		 * 처음으로 참이 나올때까지 거짓은 모두 버리고, 참 이후에 거짓이 나오면 중단되는 스트림을 반환합니다.
		 * @param predicate 
		 * @returns 
		 */
		dropWhile(predicate: (element: T) => boolean): Stream<T> {
			let origin = this;
			let head = origin.find(it => !predicate(it));
			if (head) {
				return new ConcattedStream(_stream([new ArrayStream([head]), this]))
			}
			else {
				return new EmptyStream();
			}
		}

		exists(predicate: (e: T) => boolean): boolean {
			while (this.hasNext()) {
				let next = this.next();
				if (predicate(next)) {
					return true;
				}
			}
			return false;
		}

		forall(predicate: (e: T) => boolean): boolean {
			while (this.hasNext()) {
				let next = this.next();
				if (!predicate(next)) {
					return false;
				}
			}
			return true;
		}

		flatten<R = ElementOf<T>>(): Stream<R> {
			let casted = this as Stream<R[] | Stream<R>>;
			return new ConcattedStream(casted.map(it => {
				if (it instanceof Stream) {
					return it;
				}
				else {
					return _stream(it as R[]);
				}
			}));
		}

		filterNull(options?: FilterNullOptions): Stream<T> {
			options = _assign({
				keepNull: false,
				keepUndefined: false
			}, options);

			return new FilteredStream(this, it => {
				if (it === null) {
					return options.keepNull;
				} else if (it === undefined) {
					return options.keepUndefined;
				} else {
					return true;
				}
			});
		}

		filterNullOrEmpty(options?: FilterNullOptions): Stream<T> {
			return new FilteredStream(this, it => _isNullOrEmpty(it) === false);
		}

		filter<TypeHint extends T = T>(predicate: (e: T) => boolean): Stream<TypeHint> {
			return new FilteredStream(this, predicate) as any as Stream<TypeHint>;
		}

		reject(predicate: (e: T) => boolean): Stream<T> {
			return new FilteredStream(this, e => !predicate(e));
		}

		reverse(): Stream<T> {
			return new ArrayStream(this.collect().reverse());
		}

		/**
		 * 스트림의 요소들을 특정 타입으로 필터링 합니다.
		 * @param type 필터링 할 타입.
		 * @returns 해당 타입 스트림.
		 */
		filterByType<C extends T>(type: ConstructorOf<C>): Stream<C> {
			return new FilteredStream(this, e => {
				return e instanceof type;
			}) as any as Stream<C>;
		}

		/**
		 * 스트림의 요소들을 특정 타입으로 캐스팅 합니다.
		 * 캐스팅과 동시에 실제로 타입이 따라 필터링 하려면 {@link filterByType}을 사용하십시오.
		 * @param type 캐스팅할 타입.
		 * @returns 타입이 캐스팅 된 스트림.
		 */
		castAs<CastType>(type: ConstructorOf<CastType>): Stream<CastType> {
			return this as unknown as Stream<CastType>;
		}

		/**
		 * 스트림의 요소들을 변조하여 공급하는 스트림을 얻습니다.
		 * @param mapper 요소를 변조할 때 호출되는 매핑 함수.
		 * @returns 변조된 스트림.
		 */
		map<R>(mapper: (input: T) => R): Stream<R> {
			return new TransformingStream(this, mapper);
		}

		join(separator: string): string;
		join(options: JoinOptions<T>): string;
		join(param: JoinOptions<T> | string) {
			param = typeof param == "string"
				? { stringify: it => "" + it, separator: param }
				: { stringify: it => "" + it, ...param }
				;

			let segments = this.map(it => param.stringify(it)).collect();
			let result = segments.join(param.separator);
			if (param.before != null) {
				result = param.before + result;
			}
			if (param.after != null) {
				result = result + param.after;
			}
			return result;
		}

		/**
		 * 스트림의 요소를 수집하여 배열화 하고 정렬을 적용 합니다.
		 * @param comparator 비교 함수.
		 */
		sortBy(comparator: (a: T, b: T) => number): Stream<T>;
		/**
		 * 스트림의 요소를 수집하여 배열화 하고 정렬을 적용 합니다.
		 * @param keepOriginIndex 비교 결과가 동일한 경우 원본에서의 순서를 기준으로 할 것인지 여부.
		 * @param comparator 비교 함수.
		 */
		sortBy(keepOriginIndex: boolean, comparator: (a: T, b: T) => number): Stream<T>;
		sortBy(): Stream<any> {
			let keepOriginIndex: boolean;
			let comparator: (a: T, b: T) => number;

			let args = _toArray(arguments);
			switch (args.length) {
				case 2:
					[keepOriginIndex, comparator] = [args[0], args[1]];
					break;
				case 1:
					[keepOriginIndex, comparator] = [false, args[0]];
					break;

				default:
					throw new exceptions.IllegalArgumentException();
			}

			let array = this.collect();

			if (keepOriginIndex) {
				array.sort((a, b) => {
					let result = comparator(a, b);
					if (result !== 0) {
						return result;
					} else {
						return array.indexOf(a) - array.indexOf(b);
					}
				});
			} else {
				array.sort(comparator);
			}

			return new ArrayStream(array);
		}


		sort(): Stream<T> {
			let array = this.collect();
			array.sort();
			return new ArrayStream(array);
		}

		/**
		 * 가장 첫 항목을 반환 합니다. 항목이 존재하지 않는다면 <code>null</code>가 반환 됩니다.
		 * @returns  첫 항목.
		 */
		head(): T {
			if (this.hasNext()) {
				return this.next();
			}
			else {
				return null;
			}
		}

		concatWith(...others: Stream<T>[]): Stream<T> {
			return new ConcattedStream(_stream([this, ...others]));
		}

		/**
		 * 처음으로부터 최대 개수만큼만 항목을 제공하는 이 이터레이터 대한 뷰를 반환합니다.
		 * @param count 반환해야 하는 최대 요소의 개수.
		 * @returns 개수가 제한된 이터레이터. <code>null<code>을 반환 하지 않음.
		 */
		take(count: number): Stream<T> {
			if (count < 0) {
				throw new exceptions.IllegalArgumentException(`count must be 0 or greator but was ${count}.`);
			}
			if (count === 0) {
				return new EmptyStream<T>();
			}

			let originStream = this;
			let remaining = count;

			return new (class extends Stream<T> {
				hasNext(): boolean {
					if (remaining <= 0) {
						return false;
					}
					return originStream.hasNext();
				}
				next(): T {
					let result = originStream.next();
					remaining--;
					return result;
				}
			})();
		}

		/**
		 * 순서대로 정렬되어 있을때 조건에 만족 하지 않으면 중단됩니다. 참인 값들만 포함된 스트림을 반환합니다.
		 * @param predicate 
		 * @returns 
		 */
		takeWhile(predicate: (element: T) => boolean): Stream<T> {
			let originStream = this;
			let nextInfo: PreResolve<T>;

			let resolveNext: () => PreResolve<T> = () => {
				if (_isUnconsumed(nextInfo)) {
					return nextInfo;
				}

				if (originStream.hasNext()) {
					let next = originStream.next();
					if (predicate(next)) {
						nextInfo = {
							value: next,
							present: true,
							consumed: false
						};
						return nextInfo;
					}
				}

				nextInfo = {
					present: false,
					value: null,
					consumed: false
				};

				return nextInfo;
			};

			let consumeNext: () => T = () => {
				let info = resolveNext();
				if (info.present === false) {
					throw new exceptions.NoMoreElementException();
				}
				return _consume(info);
			};

			return new (class extends Stream<T> {
				hasNext(): boolean {
					return resolveNext().present;
				}
				next(): T {
					return consumeNext();
				}
			})();
		}

		/**
		 * 요소들이 한 번씩만 포함된 유니크 스트림을 얻습니다.
		 */
		uniquify(): Stream<T> {
			let knownItems = _createSet<T>();
			return this.filter(it => {
				if (knownItems.has(it)) {
					return false;
				}
				knownItems.add(it);
				return true;
			});
		}

		/**
		 * 주어진 식별자 공급자를 이용하여 요소들이 한 번씩만 포함된 스트림을 얻습니다.
		 * @param identityPredicate 식별자 공급자.
		 */
		uniquifyBy<K>(identityPredicate: (e: T) => K): Stream<T> {
			let knownItems = _createSet<K>();
			return this.filter(it => {
				let key = identityPredicate(it);
				if (knownItems.has(key)) {
					return false;
				}
				knownItems.add(key);
				return true;
			});
		}

		/**
		 * 주어진 키 공급자를 이용하여 요소의 키를 얻고 요소를 값으로 하는 {@link CMap}으로 변환 합니다.
		 * 만일 여러 요소가 동일한 키를 공급한 경우 마지막 요소가 우선하게 됩니다.
		 * 
		 * @param keyProvider 키 공급자.
		 * @returns 맵.
		 */
		toMap<K>(keyProvider: (element: T) => K): CMap<K, T>;

		/**
		 * 주어진 키 공급자를 이용하여 요소의 키를 얻고 요소를 값으로 하는 {@link CMap}으로 변환 합니다.
		 * @param keyProvider 키 공급자.
		 * @param valueProvider 값 공급자.
		 * @returns 맵.
		 */
		toMap<K, R>(keyProvider: (element: T) => K, valueProvider?: (element: T) => R): CMap<K, R> {
			let result = _createMap<any, any>();
			this.forEach(it => {
				let key = keyProvider(it);
				result.set(key, valueProvider?.(it) ?? it);
			});

			return result;
		}

		toJSON(keyProvider: (element: T) => string): { [key: string]: T };
		toJSON(keyProvider: (element: T) => string, valueProvider?: (element: T) => any): { [key: string]: any } {
			let result = {};
			this.forEach(e => {
				result[keyProvider(e)] = valueProvider?.(e) ?? e;
			});
			return result;
		}

		/**
		 * 주어진 키 공급자를 이용하여 그루핑 합니다.
		 * @param keyProvider 키 공급자.
		 * @returns 같은 키를 가지는 요소들의 배열을 값으로 하는 맵.
		 */
		groupBy<K>(keyProvider: (element: T) => K): CMap<K, T[]> {
			let result = _createMap<K, T[]>();

			this.forEach(it => {
				let key = keyProvider(it);
				if (result.has(key)) {
					result.get(key).push(it);
				} else {
					result.set(key, [it]);
				}
			});

			return result;
		}

		/**
		 * 스트림의 요소들을 리듀스 합니다.
		 * @param emptyValue 빈 스트림일 경우 반환할 값.
		 * @param reducer 리듀스 함수.
		 * @returns 리듀스 된 값.
		 */
		reduce(emptyValue: T = null, reducer: (a: T, b: T) => T): T {
			let arr = this.collect();
			return arr.length > 0
				? arr.reduce(reducer)
				: emptyValue;
		}

		/**
		 * 초기값을 이용하여 리듀스 합니다.
		 * @param initialValue 최초 리듀스의 좌항값으로 사용될 초기 값.
		 * @param reducer 리듀스 함수.
		 * @returns 리듀스 된 값.
		 */
		reduceWithInitial(initialValue: T, reducer: (a: T, b: T) => T): T {
			let arr = this.collect();
			return arr.reduce(reducer, initialValue);
		}

		/**
		 * 평가값이 최소인 요소를 찾습니다.
		 * @param predicate 요소 평가 함수.
		 * @param minBounds 최소 경계 값. 만일 이 값을 반환하는 요소가 발견되면 더 이상 최소 값을 찾지 않습니다.
		 * @returns 평가 결과가 최소 값인 요소.
		 */
		minBy(predicate: (e: T) => number, minBounds?: number): T {
			let result: T = undefined;
			let currentMinValue: number = Number.MAX_VALUE;

			while (this.hasNext()) {
				let eachElement = this.next();
				let eachValue = predicate(eachElement);

				if (eachValue === minBounds) {
					result = eachElement;
					break;
				}

				if (eachValue < currentMinValue) {
					currentMinValue = eachValue;
					result = eachElement;
				}
			}

			return result;
		}

		/**
		 * 평가값이 최대인 요소를 찾습니다.
		 * @param predicate 요소 평가 함수.
		 * @param maxBounds 최대 경계 값. 만일 이 값을 반환하는 요소가 발견되면 더 이상 최대 값을 찾지 않습니다.
		 * @returns 평가 결과가 최대 값인 요소.
		 */
		maxBy(predicate: (e: T) => number, maxBounds?: number): T {
			let result: T = undefined;
			let currentMaxValue: number = Number.MIN_VALUE;

			while (this.hasNext()) {
				let eachElement = this.next();
				let eachValue = predicate(eachElement);
				if (eachValue === maxBounds) {
					result = eachElement;
					break;
				}
				if (eachValue > currentMaxValue) {
					currentMaxValue = eachValue;
					result = eachElement;
				}
			}
			return result;
		}
		/**
		 * 스트림 내에서 가장 작은 값을 얻습니다.
		 * 스트림은 종료됩니다.
		 * 
		 * @returns 스트림 내에서 가장 작은 값.
		 */
		min(): T {
			let arr = this.collect();
			arr.sort();
			return arr[0];
		}

		/**
		 * 스트림 내에서 가장 큰 값을 얻습니다.
		 * 스트림은 종료됩니다.
		 * 
		 * @returns 스트림 내에서 가장 큰 값.
		 */
		max(): T {
			let arr = this.collect();
			arr.sort();
			return arr[arr.length - 1];
		}

		/**
		 * 스트림의 모든 요소를 수집하여 배열로 반환 합니다.
		 * 이 스트림은 종료 됩니다.
		 */
		collect(): T[] {
			let result: T[] = [];
			this.forEach(it => result.push(it));
			return result;
		}

		/**
		 * 스트림에서 요소가 소비될 때 마다 관측할 수 있는 스트림을 만듭니다.
		 * @param tapper 관측 함수.
		 * @returns 관측 함수가 연결된 스트림.
		 */
		tap(tapper: (e: T) => void): Stream<T> {
			return new TappingStream(this, tapper);
		}

		/**
		 * @deprecated {@link collect}를 대신 사용하십시오.
		 */
		toArray(): T[] {
			return this.collect();
		}
	}

	/**
	 * @internal
	 */
	class ConcattedStream<R> extends Stream<R> {
		_terminalStream: Stream<R>;
		_streamStream: Stream<Stream<R>>;
		_currentStream: Stream<R>;

		constructor(streamStream: Stream<Stream<R>>) {
			super();
			this._streamStream = streamStream;
			this._terminalStream = new EmptyStream();
		}

		private _resolveActiveStream() {
			if (this._currentStream) {
				if (this._currentStream === this._terminalStream || this._currentStream.hasNext()) {
					return this._currentStream;
				}
			}

			if (this._streamStream.hasNext()) {
				this._currentStream = this._streamStream.next();
			} else {
				this._currentStream = this._terminalStream;
			}

			return this._resolveActiveStream();
		}

		hasNext(): boolean {
			return this._resolveActiveStream().hasNext();
		}

		next(): R {
			return this._resolveActiveStream().next();
		}
	}

	class NodeListLikeStream<T> extends Stream<T> {
		_list: NodeListLike<T>;
		_current = 0;

		constructor(list: NodeListLike<T>) {
			super();
			this._list = list;
			this._current = 0;
		}

		hasNext(): boolean {
			return this._current < this._list.length;
		}

		next(): T {
			return this._list[this._current++];
		}
	}


	/**
	 * @internal
	 */
	class ArrayStream<T> extends Stream<T> {
		private _array: T[];
		private _index: number;

		constructor(array: T[]) {
			super();
			this._array = array;
			this._index = 0;
		}

		hasNext(): boolean {
			return this._index < this._array.length;
		}

		next(): T {
			if (this._index >= this._array.length) {
				throw new exceptions.NoMoreElementException();
			}
			return this._array[this._index++]
		}

		override collect(): T[] {
			if (this._index === 0) {
				this._index = this._array.length;
				return this._array;
			}
			else {
				let result = this._array.slice(this._index);
				this._index = this._array.length;
				return result;
			}
		}
	}

	/**
	 * 최신 브라우저의 이터레이터 심볼을 이용한 스트림.
	 * Set를 변환 없이 곧바로 스트림화 할 수 있음. 
	 * 
	 * @internal
	 */
	class IterableStream<T> extends Stream<T> {
		_iterator: globalThis.Iterator<T>
		_next: IteratorResult<T, T>;

		/**
		 * 새 이터레이터를 만듭니다.
		 * @param iterable ES 스펙 상의 이터러블 객체. 만약 이터레이터 심볼을 갖지 않았거나, 이터러블 자체가 존재하지 않는 경우 빈 이터레이터가 만들어 집니다.
		 */
		constructor(iterable: Iterable<T>) {
			super();

			if (typeof iterable?.[Symbol.iterator] != "function") {
				iterable = [];
			}

			this._iterator = iterable[Symbol.iterator]();
			this._next = this._iterator.next();
		}

		hasNext(): boolean {
			return this._next.done === false;
		}

		next(): T {
			if (!this.hasNext()) {
				throw new exceptions.NoMoreElementException();
			}
			else {
				let result = this._next.value;
				this._next = this._iterator.next();
				return result;
			}
		}
	}

	class TreeWalkingStream<T> extends Stream<T> {
		private _options: TreeWalkingOption<T>;
		private _current: T;
		private _nextInfo: PreResolve<T>;
		private _parentCache: CMap<T, T>;
		private _childrenCache: CMap<T, T[]>;

		constructor(offset: T, options: TreeWalkingOption<T>) {
			super();
			this._current = offset;
			this._childrenCache = _createMap();
			this._parentCache = _createMap();
			this._options = options;

			if (options.includeOffset) {
				this._nextInfo = {
					value: this._current,
					consumed: false,
					present: true
				}
			}
		}

		private _getParent(node: T): T {
			if (node == null) {
				return null;
			}
			if (this._parentCache.has(node)) {
				let cached = this._parentCache.get(node);
				return cached === _NO_VALUE_ ? null : cached;
			}
			let parent = this._options.getParent(node);
			this._parentCache.set(node, parent ?? _NO_VALUE_);

			return parent;
		}

		private _getChildren(node: T): T[] {
			if (node == null) {
				return null;
			}
			if (this._childrenCache.has(node)) {
				let cached = this._childrenCache.get(node);
				return cached === _NO_VALUE_ ? [] : cached;
			}
			let children = this._options.getChildren(node);
			this._childrenCache.set(node, _isNullOrEmpty(children) ? _NO_VALUE_ : children);
			if (children) {
				_stream(children).forEach(child => {
					this._parentCache.set(child, node);
				});
			}

			return children ?? [];
		}

		private _getLastLeaf(node: T) {
			let children = this._getChildren(node)
			if (_isNullOrEmpty(children)) {
				return node;
			}
			return this._getLastLeaf(_.last(children));
		}

		private _walkForward(): T {
			let firstChild = this._getChildren(this._current)[0];
			if (firstChild) {
				return firstChild;
			}

			let offset = this._current;
			let parent: T = null;
			let result: T = null;

			while ((parent = this._getParent(offset)) != null && result == null) {
				let sibilings = this._getChildren(parent);
				let idx = sibilings.indexOf(offset);
				if (sibilings[idx + 1]) {
					return sibilings[idx + 1];
				} else {
					offset = parent;
				}
			}

			return null;
		}

		private _walkBackward(): T {
			let parent = this._getParent(this._current);
			if (!parent) {
				return null;
			}

			let children = this._getChildren(parent);
			let idx = children.indexOf(this._current);
			if (idx === 0) {
				return parent;
			}
			else {
				return this._getLastLeaf(children[idx - 1]);
			}
		}

		private _resolveNext(): PreResolve<T> {
			// 이미 계산되었고 소비되지 않은 경우 기존 값 사용.
			if (_isUnconsumed(this._nextInfo)) {
				return this._nextInfo;
			}

			let next = this._options.direction == "forward"
				? this._walkForward()
				: this._walkBackward();

			this._nextInfo = {
				present: next != null, value: next, consumed: false
			};

			return this._nextInfo;
		}

		private _consumeNext(): T {
			let info = this._resolveNext();
			if (info.present === false) {
				throw new exceptions.NoMoreElementException();
			}
			return _consume(info);
		}

		hasNext(): boolean {
			return this._resolveNext().present;
		}

		next(): T {
			this._current = this._consumeNext();
			return this._current;
		}
	}

	class TreeStream<T> extends Stream<T> {
		private _includeRoot: boolean;
		private _root: T;
		private _childStreamProvider: (element: T) => (Stream<T> | T[]);
		private _streamStack: CStack<Stream<T>> = null;

		constructor(root: T, includeRoot: boolean, childProvider: (element: T) => (Stream<T> | T[])) {
			super();
			this._root = root;
			this._includeRoot = includeRoot;
			this._childStreamProvider = childProvider;
		}

		_getChildStream(element: T): Stream<T> {
			let children = this._childStreamProvider(element);
			if (children instanceof Stream) {
				return children;
			} else {
				return _stream(children);
			}
		}

		override hasNext(): boolean {
			// 루트 매핑인 경우.
			if (this._streamStack == null && !this._includeRoot) {
				let nextStream = this._getChildStream(this._root);
				this._streamStack = _createStack();
				this._streamStack.push(nextStream);
				return nextStream.hasNext();
			}
			else {
				return this._streamStack === null || !this._streamStack.isEmpty() && this._streamStack.peek().hasNext();
			}
		}

		override next(): T {
			// 루트 매핑인 경우.
			if (this._streamStack === null) {
				this._streamStack = _createStack();
				this._streamStack.push(this._getChildStream(this._root));
				if (this._includeRoot) {
					return this._root;
				}
			}

			let currentStream = this._streamStack.peek();
			let result = currentStream.next();

			let iterator = this._getChildStream(result);
			if (iterator.hasNext()) {
				this._streamStack.push(iterator);
			}
			else {
				while (this._streamStack.isEmpty() === false && this._streamStack.peek().hasNext() === false) {
					this._streamStack.pop();
				}
			}

			return result;
		}
	}

	/**
	 * @internal
	 */
	class FilteredStream<T> extends Stream<T> {
		private _origin: Stream<T>;
		private _nextInfo: PreResolve<T>;
		private _predicate: (each: T) => boolean

		constructor(origin: Stream<T>, predicate: (each: T) => boolean) {
			super();
			this._origin = origin;
			this._predicate = predicate;
		}

		private _resolveNext(): PreResolve<T> {
			// 이미 계산되었고 소비되지 않은 경우 기존 값 사용.
			if (_isUnconsumed(this._nextInfo)) {
				return this._nextInfo;
			}

			Searching: while (this._origin.hasNext()) {
				let next = this._origin.next();
				if (this._predicate(next)) {
					this._nextInfo = {
						present: true, value: next, consumed: false
					};
					return this._nextInfo;
				}
			}

			this._nextInfo = {
				present: false, value: null, consumed: false
			};

			return this._nextInfo;
		}

		private _consumeNext(): T {
			let info = this._resolveNext();
			if (info.present === false) {
				throw new exceptions.NoMoreElementException();
			}
			return _consume(info);
		}

		hasNext(): boolean {
			return this._resolveNext().present;
		}

		next(): T {
			return this._consumeNext();
		}
	}

	/**
	 * @internal
	 */
	class TransformingStream<I, O> extends Stream<O> {
		private _origin: Stream<I>
		private _transform: (input: I) => O;

		constructor(input: Stream<I>, transform: (input: I) => O) {
			super();
			this._origin = input;
			this._transform = transform;
		}

		hasNext(): boolean {
			return this._origin.hasNext();
		}

		next(): O {
			let next = this._origin.next();
			return this._transform(next);
		}
	}

	/**
	 * @internal
	 */
	class TappingStream<R> extends Stream<R> {
		private _origin: Stream<R>
		private _tapper: (input: R) => void;

		constructor(input: Stream<R>, tapper: (input: R) => void) {
			super();
			this._origin = input;
			this._tapper = tapper;
		}

		override hasNext(): boolean {
			return this._origin.hasNext();
		}

		override next(): R {
			let next = this._origin.next();
			this._tapper(next);
			return next;
		}
	}

	/**
	 * @internal
	 */
	class DynamicStream<T> extends Stream<T> {
		private _knownValue: T;
		private _includeOffset: boolean;
		private _nextProducer: (current: T) => T;
		private _nextInfo: PreResolve<T>;

		constructor(offset: T, includeOffset: boolean, nextProvider: (prev: T) => T) {
			super();
			this._knownValue = offset;
			this._includeOffset = includeOffset;
			this._nextProducer = nextProvider;
			if (this._includeOffset) {
				this._nextInfo = {
					value: offset,
					consumed: false,
					present: true
				};
			}
		}

		private _resolveNext(): PreResolve<T> {
			if (_isUnconsumed(this._nextInfo)) {
				return this._nextInfo;
			}

			let next = this._nextProducer(this._knownValue);
			this._nextInfo = {
				value: next,
				consumed: false,
				present: next !== null && next !== undefined
			}

			return this._nextInfo;
		}

		private _consumeNext(): T {
			let info = this._resolveNext();
			if (info.present === false) {
				throw new exceptions.NoMoreElementException();
			}
			let result = _consume(info);
			return result;
		}

		override hasNext(): boolean {
			return this._resolveNext().present;
		}

		override next(): T {
			return this._knownValue = this._consumeNext();
		}
	}

	/**
	 * @internal
	 */
	class EmptyStream<T> extends Stream<T> {
		override hasNext(): boolean {
			return false;
		}
		override next(): T {
			return null;
		}
	}

	/**
	 * @internal
	 */
	class SingleStreamStream<T> extends Stream<T> {
		private _element: T;
		private _consumed = false;

		constructor(element: T) {
			super();
			this._element = element;
		}

		hasNext(): boolean {
			return !this._consumed;
		}

		next(): T {
			if (!this._consumed) {
				this._consumed = true;
				return this._element;
			} else {
				return null;
			}
		}
	}

	export function _createTreeStream<T extends R, R>(root: T, includeRoot: boolean, childrenProvider: (e: R) => R[] | Stream<R>): Stream<R> {
		return new TreeStream(root, includeRoot, childrenProvider)
	}

	export type TreeWalking<R> = {
		/**
		 * 노드의 자식을 얻는 함수.
		 */
		getChildren: (e: R) => R[]

		/**
		 * 노드의 부모 노드를 얻는 방법.
		 * null 을 리턴한 경우 루트 노드임을 나타냅니다.
		 */
		getParent: (e: R) => R
	}

	export type TreeWalkingOption<R> = TreeWalking<R> & {
		/**
		 * 트리의 탐색 방향
		 */
		direction?: "forward" | "backward"

		/**
		 * 기준 노드를 스트림에 포함할지 여부
		 */
		includeOffset: boolean
	};

	/**
	 * 주어진 노드로 부터 트리 노드를 순회하는 Walk 스트림을 만듭니다.
	 * @param offsetNode 탐색을 시작할 노드
	 * @param options 탐색 옵션
	 */
	export function _createTreeWalkStream<T extends R, R>(offsetNode: T, options: TreeWalkingOption<R>): Stream<R> {
		return new TreeWalkingStream(offsetNode, { direction: "forward", ...options });
	}

	/**
	 * {@link NodeList}, {@link HTMLCollection} 및 {@link FileList} 등으로 부터 스트림을 엽니다.
	 */
	export function _stream<T extends object>(nodeList: NodeListLike<T>): Stream<T>;
	/**
	 * 배열을 스트림 형태로 변환 합니다.
	 */
	export function _stream<T>(array: T[]): Stream<T>;
	/**
	 * {@link CSet}의 요소들을 스트림 형태로 얻습니다.
	 */
	export function _stream<T>(set: CSet<T>): Stream<T>;

	export function _stream<Key, Value>(map: CMap<Key, Value>): Stream<CMap.Entry<Key, Value>>;

	/**
	 * ES2015.iterable을 지원하는 객체의 요소들을 스트림 형태로 얻습니다.
	 */
	export function _stream<T>(iterable: Iterable<T>): Stream<T>;
	export function _stream(iterable: any): Stream<any> {
		if (iterable == null) {
			return new EmptyStream();
		}
		else if (NodeListLike._isNodeListLike(iterable)) {
			return new NodeListLikeStream(iterable);
		}
		// 이터러블이 지원되는 경우 입력은 배열이거나, 이터러블이거나, 네이티브 Set이 되며 이 경우 모두 이터러블 하다.
		else if (_ECMA._iterable && iterable[Symbol.iterator]) {
			return new IterableStream(iterable);
		}
		// 배열이지만 이터러블 지원이 되지 않는 경우.
		else if (iterable instanceof Array) {
			return new ArrayStream(iterable);
		}
		else if (CSet._isCSet(iterable)) {
			let result = new Array(iterable.size);
			let idx = 0;
			iterable.forEach(v => result[idx++] = v);
			return new ArrayStream(result);
		}
		else {
			throw new exceptions.IllegalArgumentException();
		}
	}

	/**
	 * 동적으로 다음항목을 계산하는 스트림을 생성 합니다.
	 * @param offset 스트림의 시작 객체.
	 * @param includeOffst 시작 객체의 포함 여부.
	 * @param nextProvider 현재 객체로 부터 다음 객체를 반환하는 클로져. null 또는 undefined를 반환한 경우 스트림의 끝으로 취급 됩니다.
	 * @returns 스트림.
	 */
	export function _createDynamicStream<T extends R, R>(offset: T, includeOffst: boolean, nextProvider: (e: R) => R): Stream<R> {
		return new DynamicStream(offset, includeOffst, nextProvider);
	}

	export function _concatStream<T>(...streams: (Stream<T> | T[])[]): Stream<T> {
		let streamOfStreams = _stream(streams)
			.map(it => {
				return it instanceof Stream
					? it
					: _stream(it);
			});

		return new ConcattedStream(streamOfStreams);
	}
}


