namespace cpr.controls.gridpart.config {

	export class GridGroupHeaderCellConfigurator extends GridFooterCellConfigurator {
		private _columnType: string = "normal";

		constructor(grid: Grid) {
			super(grid);
		}

		/**
		 * 기본 컬럼일 경우 column의 종류를 설정합니다.<br>
		 * group header cell : "checkbox", "normal"
		 * @param columnType 컬럼의 종류.
		 */
		set columnType(columnType: string) {
			this._columnType = columnType;
		}

		/**
		 * 기본 컬럼일 경우 column의 종류를 반환합니다.<br>
		 * group header cell : "checkbox", "normal"
		 * @return 컬럼의 종류.
		 */
		get columnType(): string {
			return this._columnType;
		}

	}
}