/// <reference path="./PropertyDelegate.ts"/>

namespace cpr.bind {
	/**
	 * @nonapi
	 */
	export class DataColumnDelegate extends PropertyDelegate {
		private _owner: bind.BindablePropertiesOwner
		private _columnName: string

		constructor(owner: bind.BindablePropertiesOwner, columnName: string) {
			super()

			this._owner = owner;
			this._columnName = columnName;
		}

		private _getDataBindContext(): DataBindContext {
			let context = this._owner.getBindContext();
			if (context instanceof bind.DataBindContext) {
				return context;
			}

			if (context && context._cloneWithExpressionDelegate instanceof Function) {
				let delegates = (context as expression.EvaluationContext)._getExpressionDelegates();
				return _(delegates).find(it => it instanceof bind.DataBindContext);
			}

			return null;
		}

		/**
		 * 데이타셋 또는 데이타맵 컬럼의 값을 가져옵니다.
		 * @return string|number|null
		 */
		override get(): any {
			let ctx: DataBindContext = this._getDataBindContext();
			if (ctx) {
				return ctx._get(this._columnName);
			}
			return null;
		}

		/**
		 * 데이타셋 또는 데이타맵의 컬럼에 값을 지정합니다.
		 * @param newValue 컬럼 타입에 맞는 값
		 */
		override set(newValue: any): void {
			let ctx: DataBindContext = this._getDataBindContext();
			if (ctx) {
				ctx._set(this._columnName, newValue);
			}
		}

		/**
		 * 컬럼이 지정되어 활성화 되어 있는지 여부를 반환합니다.
		 */
		override isActive(): boolean {
			let ctx: DataBindContext = this._getDataBindContext();
			if (ctx) {
				return this._columnName != null;
			}
			return false;
		}

		override _isAvailable(): boolean {
			let ctx: DataBindContext = this._getDataBindContext();
			if (ctx) {
				return ctx._isAvailable();
			}
			return false;
		}

		override dispose(): void {
			this._owner = null;
		}

		override getBindInfo(): BindInfo {
			return {
				type: BindType.DATACOLUMN,
				columnName: this._columnName
			};
		}
	}
}