/// <reference path="./BufferedScrollStrategy.ts"/>


namespace cpr.controls.gridpart.layout {


	/**
	 * @private
	 */
	export class RowBufferedScrollStrategy extends BufferedScrollStrategy {

		constructor(scrollPane: ScrollPane, context: GridContext) {
			super(scrollPane, context);
		}

		/**
		 * moveposition.jumpedIndex(DataSet RowIndex)를 설정하고 이동할 rowIndex()를 리턴
		 * @param moveposition 
		 * @param startrowindex 
		 * @param endrowindex 
		 */
		protected _getTargetRowIndex(moveposition: { srcIndex: number, offset: number, jumpIndex: number, jumpedIndex: number }
			, startrowindex: number, endrowindex: number): number {

			let targetIndex: number = -1;
			if (moveposition.jumpIndex >= 0) {
				targetIndex = moveposition.jumpIndex;
			} else {
				targetIndex = moveposition.srcIndex + moveposition.offset;
			}

			if (targetIndex < 0) {
				targetIndex = 0;
			}
			let finalrowindex: number = this.grid.getContentRowCount() - 1;
			if (targetIndex > finalrowindex) {
				targetIndex = finalrowindex;
			}

			if (targetIndex < startrowindex || targetIndex > endrowindex) {
				moveposition.jumpedIndex = -1; // moveposition.jumpedIndex 설정
				return -1;
			}

			moveposition.jumpedIndex = targetIndex; // moveposition.jumpedIndex 설정

			return targetIndex;
		}
	}
}