/// <reference path="../../provider/DataBinder.ts" />
/// <reference path="../ItemExpressionEvaluator.ts" />

namespace cpr.controls.item {

	/**
	 * @private
	 */
	export class ItemSelectionManager<ItemType extends Item> {

		private _core: SelectionCore<ItemType>;

		constructor(binder: provider.MultiValueBinder, itemListProvider: BaseItemListProvider<ItemType, any>, itemExpressionEvaluator: ItemExpressionEvaluator) {
			this._core = new SelectionCore<ItemType>(binder, itemListProvider, itemExpressionEvaluator);
		}

		/**
		 * 선택 상태를 무효화합니다.
		 */
		public invalidateSelection(): void {
			this._core.invalidateSelection();
		}

		/**
		 * 해당되는 아이템을 선택합니다.<br>
		 * 선택된 아이템의 value는 컨트롤의 value로 지정됩니다.<br>
		 * 존재하지 않는 아이템인 경우 아이템 선택이 안 되고 해당 value가 지정되지 않습니다.<br>
		 * newSelection,oldSelection이 item[]를 반환합니다.
		 * @param item 선택하고자 하는 아이템.
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 */
		public selectItem(item: ItemType, emitEvent: boolean = true): void {
			this._core.select(item, emitEvent);
		}

		/**
		 * 해당되는 아이템을 선택합니다.<br>
		 * 선택된 아이템의 value는 컨트롤의 value로 지정됩니다.<br>
		 * 존재하지 않는 아이템인 경우 아이템 선택이 안 되고 해당 value가 지정되지 않습니다.
		 * @param obj 선택하고자 하는 아이템.
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 */
		public selectSingleItem(item: ItemType, emitEvent: boolean = true): void {
			this._core.selectSingleItem(item, emitEvent);
		}

		/**
		 * 선택할 아이템 배열을 선택합니다.
		 * 이전의 선택된 아이템을 선택 해제한 뒤 해당하는 인덱스의 아이템들을 선택합니다.
		 * @param items 선택할 아이템 배열
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 */
		public selectItems(items: ItemType[], emitEvent: boolean = true): void {
			if (_isArray(items) == false) {
				return;
			}
			this._core.selectItems(items, emitEvent);
		}

		/**
		 * multiple 일 경우 선택이 계속 쌓인다. 아닌경우 선택을 지우고 선택한다.
		 * @private
		 * @nonapi
		 * @param item 
		 * @param multiple
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 */
		public _select(item: ItemType, multiple: boolean = false, emitEvent: boolean = true, forceSelect: boolean = false): boolean {
			return this._core._select(item, multiple, emitEvent, forceSelect);
		}

		/**
		 * 선택된 아이템들을 반환합니다.
		 * @return 선택된 아이템의 배열.
		 */
		public getSelection(): ItemType[] {
			return this._core.getSelection();
		}

		/**
		 * 선택된 아이템들을 설정합니다.
		 * @param items 설정할 아이템 배열
		 */
		public setSelection(items: ItemType[]): void {
			this._core.setSelection(items);
		}

		/**
		 * 선택된 리스트 데이터 배열 중 첫번째 데이터를 반환합니다.
		 * @return 첫번째 선택된 데이터.
		 */
		public getSelectionFirst(): ItemType {
			return this._core.getSelectionFirst();
		}

		/**
		 * 선택된 리스트 데이터 배열 중 마지막 데이터를 반환합니다.
		 * @return 마지막으로 선택된 데이터.
		 */
		public getSelectionLast(): ItemType {
			return this._core.getSelectionLast();
		}

		/**
		 * 해당되는 아이템의 선택 여부를 반환합니다.
		 * @param obj 아이템
		 * @return 해당 아이템의 선택 여부.
		 */
		public isSelected(item: ItemType): boolean {
			return this._core.isSelected(item);
		}

		/**
		 * value에 해당되는 아이템의 선택 여부를 반환합니다.
		 * @param value 아이템의 value.
		 * @return 해당 아이템의 선택 여부.
		 */
		public isSelectedByValue(value: string): boolean {
			return this._core.isSelectedByValue(value);
		}

		/**
		 * 해당되는 아이템이 선택되었을 경우 그 아이템을 선택 해제합니다.
		 * @param item 아이템
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 */
		public removeSelection(item: ItemType, emitEvent: boolean = true): boolean {
			return this._core.removeSelection(item, emitEvent);
		}

		/**
		 * 해당되는 아이템이 선택되었을 경우 그 아이템을 선택 해제합니다.
		 * @param item 아이템
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 */
		public removeSingleSelection(item: ItemType, emitEvent: boolean = true): void {
			this._core.removeSingleSelection(item, emitEvent);
		}

		/**
		 * value에 해당되는 아이템이 선택되었을 경우 그 아이템을 선택 해제합니다.
		 * @param value 아이템의 value.
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 */
		public removeSelectionByValue(value: string, emitEvent: boolean = true): void {
			this._core.removeSelectionByValue(value, emitEvent);
		}

		/**
		 * value에 해당하는 리스트 데이터를 선택 해제합니다.
		 * @param value 선택 해제하고자 하는 리스트 데이터의 value
		 */
		public deleteSelectionByValue(value: string): void {
			this._core.removeSelectionInternalByValue(value);
		}

		/**
		 * value에 해당되는 아이템이 선택되었을 경우 그 아이템을 선택 해제합니다.
		 * @param value 아이템의 value.
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 */
		public removeSingleSelectionByValue(value: string, emitEvent: boolean = true): void {
			this._core.removeSingleSelectionByValue(value, emitEvent);
		}

		/**
		 * 선택된 아이템들을 삭제합니다.
		 * @param items 삭제할 아이템 배열
		 */
		public deleteSelection(items: ItemType[]): void {
			this._core.removeSelectionInternal(items);
		}

		/**
		 * 단일 선택 아이템을 제거합니다.
		 * @param item 제거할 아이템
		 * @param emitEvent 이벤트 발생 여부
		 * @returns 제거 성공 여부
		 * @private
		 */
		public _removeSingleSelection(item: ItemType, emitEvent: boolean = true): boolean {
			return this._core._removeSingleSelection(item, emitEvent);
		}

		/**
		 * 선택된 아이템을 모두 선택 해제합니다.
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 */
		public clearSelection(emitEvent: boolean = true): void {
			this._core.clearSelection(emitEvent);
		}

		/**
		 * 단일 선택을 모두 해제합니다.
		 * @param emitEvent 이벤트 발생 여부
		 */
		public clearSingleSelection(emitEvent: boolean = true): void {
			this._core.clearSingleSelection(emitEvent);
		}

		/**
		 * 선택된 아이템의 화면에 보여지는 텍스트를 반환합니다.
		 * 다중 선택인 경우 선택된 아이템들의 레이블을 델리미터로 조인한 형태의 텍스트를 얻음.
		 * @return 화면에 보여지는 텍스트.
		 */
		public getText(): string {
			return this._core.getText();
		}

		/**
		 * 선택된 아이템의 데이터셋 인덱스를 가져옵니다. 데이터셋의 아이템이 아닌경우 -1을 반환합니다.
		 */
		public getSelectedDataSetIndices(): number[] {
			return this._core.getSelectedDataSetIndices();
		}

		/**
		 * 선택된 아이템의 개수를 반환합니다.
		 * @returns 선택된 아이템 개수
		 */
		public getSelectionSize(): number {
			return this._core.size();
		}

		/// 트리 전용 메소드 추가 부분 시작
		/**
		 * 해당 트리 데이터의 하위 데이터를 포함하여 선택 해제합니다.
		 * @param item 선택 해제하려는 트리 데이터.
		 */
		public deepRemoveSelection(item: ItemType): void {
			if (!(item instanceof TreeItem)) {
				return;
			}
			this.deepRemoveSelectionByValue(item.value);
		}

		/**
		 * value에 해당하는 트리 데이터의 하위 데이터를 포함하여 선택 해제합니다.
		 * @param value 선택 해제하려는 트리 데이터의 value.
		 */
		public deepRemoveSelectionByValue(value: string): void {
			this.deepRemoveSelectionByParentValue(value);
			let currentValues = this._core._getValues();
			let existingIndex = currentValues.indexOf(value);
			if (existingIndex !== -1) {
				currentValues.splice(existingIndex, 1);
				this._core._setValues(currentValues);
			}
		}

		/**
		 * 해당 트리 데이터의 하위 데이터를 선택 해제합니다.
		 * @param item 트리 데이터.
		 */
		public deepRemoveSelectionByParent(item: ItemType): void {
			if (!(item instanceof TreeItem)) {
				return;
			}
			this.deepRemoveSelectionByParentValue((item as any).parentValue);
		}

		/**
		 * parentValue에 해당하는 트리 데이터의 하위 데이터를 선택 해제합니다.
		 * @param parentValue 트리 데이터의 parentValue.
		 */
		public deepRemoveSelectionByParentValue(parentValue: string): void {
			let items: ItemType[] = this.findSelection("parentValue", parentValue);
			if (items == null || items.length == 0) {
				return;
			}
			for (let i: number = 0; i < items.length; i++) {
				this.deepRemoveSelection(items[i]);
			}
		}
		/**
		 * 선택된 리스트 데이터 중 조건에 맞는 리스트 데이터를 찾습니다.
		 * @param name 리스트 데이터의 key 명
		 * @param expectedValue 리스트 데이터의 value.
		 * @return 조건에 맞는 리스트 데이터 목록.
		 */
		public findSelection(name: string, expectedValue: any): ItemType[] {
			let selection = this._core.getSelection();
			return selection.filter((it: ItemType) => {
				return it[name] == expectedValue;
			})
		}
		/// 트리 전용 메소드 추가 부분 끝

		/**
		 * 컨트롤에 포함되어있는 객체들을 제거합니다.
		 */
		public dispose(): void {
			this._core?.dispose();
			this._core = null;
		}
	}

}