/// <reference path="./media/Media.ts"/>
namespace cpr.controls {

	/**
	 * Audio
	 * 영상(MP4, WebM, Ogg) 출력이 가능한 Audio 컨트롤.
	 * 
	 * @firesgroup contextmenu
	 * @firesgroup bindcontext
	 * 
	 * @fires cpr.events.CValueChangeEvent#before-value-change Audio의 value 또는 src가 변경된 값이 저장되기 전에 발생하는 이벤트.
	 * 다음 이벤트로 value-change가 발생합니다.
	 * 
	 * <pre>oldValue: {string} 이전 값</pre>
	 * <pre>newValue: {string} 변경될 값</pre>
	 * 
	 * @fires cpr.events.CValueChangeEvent#value-change Audio의 value 또는 src를 변경하여 변경된 값이 저장된 후에 발생하는 이벤트.
	 * 
	 * <pre>oldValue: {string} 이전 값</pre>
	 * <pre>newValue: {string} 변경된 값</pre>
	 * 
	 */
	export class Audio extends media.Media {
		protected static readonly _AVAILABLE_PROP: string[] = [
			"src"
		];

		/**
		 * 오디오를 생성합니다.
		 * @param id 오디오의 id
		 */
		constructor(id?: string) {
			super(id);

			// control initializing
			this._initControl();
		}

		protected _isConfigurableProperty(propName: string): boolean {
			if (Audio._AVAILABLE_PROP.indexOf(propName) != -1) {
				return true;
			}
			return super._isConfigurableProperty(propName);
		}

		override _getType(): controls.ControlType {
			return ControlType.AUDIO
		}

		protected _getStylerSpec(): UIControlStylerSpec {
			return {
				root: { baseClass: "cl-audio" }
			};
		}

		/**
		 * 소스의 경로 값을 반환합니다. 
		 * @return 소스의 경로 값.
		 */
		get src(): string {
			return this.value;
		}
		/**
		 * 소스의 경로 값을 설정합니다. 모든 브라우저는 MP3를 지원합니다.
		 * @param value 소스 경로 값.
		 */
		set src(value: string) {
			this.value = value;
		}

		//preload 속성은 IE를 제외한 브라우저들만 지원

		public _createShape(): ufc.ControlShape {

			let mediaShape = super._createShape();
			mediaShape.tag = "audio";
			let children = [mediaShape];
			if (!this.enabled) {
				let overlay: ufc.ControlShape = {
					tag: "div",
					classNames: ["cl-overlay"],
					style: {
						position: "absolute",
						left: "0px",
						top: "0px",
						bottom: "0px",
						right: "0px"
					}
				}
				children.push(overlay);
			}
			let shape = {
				tag: "div",
				styler: "root",
				style: {
					overflow: "hidden"
				},
				children: children,
				attr: {},
				eventTargets: [
					ufc.EventTargetType.UICONTROL,
					ufc.EventTargetType.DROPPABLE
				]
			};
			cpr.ufc.ShapeUtil._setTooltipAttr(shape, { owner: this, title: this.tooltip });

			return shape;
		}

	}
}