namespace cpr.controls {
	/**
	 * 컨트롤의 추상 클래스
	 */
	export abstract class Control implements core.Identifiable, resources.IDisposable, events.IEventTarget, bind.BindablePropertiesOwner, controls.UserAttributesOwner, expression.EvaluationContext {
		private _id: control_id = null;
		private _uuid: control_uuid = null;

		private _eventTable: cpr.events.EventTable;
		private _internalEventTable: events.EventTable;
		private _deactivatedEventList: string[];
		private _userAttributes = new internal.UserAttributes();

		private _isDisposed = false;
		private _appInstance: cpr.core.AppInstance;
		private _userData: CMap<string, any> = null;

		protected _bindables: cpr.bind.BindableProperties;

		/**
		 * 이벤트 객체에 컨트롤이 속한 Context 관련 부가정보를 생성하여 반환하는 Provider.
		 */
		private _relatedTargetObjectProvider: (e: events.CEvent) => any;


		constructor(id?: string) {
			this._id = id;
			this._uuid = _generateUUID();

			this._eventTable = new events.EventTable();
			this._internalEventTable = new events.EventTable();
			this._deactivatedEventList = [];

			this._bindables = new cpr.bind.BindableProperties(this);
		}

		protected _initControl(): void {
			let config: core.Config = this._getDefaultConfiguration();
			if (config) {
				this._applyConfig(config);
			}
		}

		protected _applyConfig(config: core.Config): void {
			this._configureProperties(config);
		}

		/**
		 * 기본 설정 객체로 부터 컨트롤들의 속성들의 초기값을 지정합니다.
		 * @param config 기본 값을 담은 설정 객체.
		 */
		protected _configureProperties(config: core.Config): void {
			let jsonConfig: {} = config.toJSON();
			for (let propName in jsonConfig) {
				this._setConfigureProperty(propName, jsonConfig[propName]);
			}
		}

		protected _setConfigureProperty(name: string, value: any) {
			if (this._isConfigurableProperty(name)) {
				this[name] = value;
			}
		}

		/** 
		 * 기본 설정 객체를 얻습니다.
		 * 각 컨트롤들은 이 메소드를 오버라이드 하여 적절한 설정 객체를 반환 하여야 합니다.
		 */
		protected abstract _getDefaultConfiguration(): core.Config;

		/**
		 * 주어진 속성이 기본 값 설정을 지원하는 지 여부를 얻습니다.
		 * @param propName 기본값 설정 가능 여부를 확인할 속성 명.
		 * @returns 기본값 설정 가능 여부.
		 */
		protected _isConfigurableProperty(propName: string): boolean {
			return false; // negative check
		}

		/* Property Start */
		/**
		 * 컨트롤의 고유 ID를 반환합니다.
		 * @return 컨트롤의 고유 ID.
		 */
		get uuid(): string {
			return this._uuid;
		}

		/**
		 * 컨트롤의 ID를 반환합니다.
		 * @return 컨트롤의 ID.
		 */
		get id(): string {
			return this._id;
		}

		/**
		 * Control을 구분할 수 있는 Control 고유의 Type의 시그니쳐 문자열을 반환합니다.
		 * 가용 상수값들은 {@link cpr.controls.ControlType}을 참고 하십시오.
		 * UDC 컨트롤들의 경우 각각 고유의 type 명칭이 반환 됩니다. 예: udc.MyUDC
		 */
		get type(): ControlType {
			return this._getType();
		}

		/**
		 * 컨트롤의 제거 여부를 반환합니다.
		 * @return 컨트롤의 제거 여부.
		 */
		public get disposed(): boolean {
			return this._isDisposed;
		}
		/* Property End */

		/* binder start */

		public _getBindables(): cpr.bind.BindableProperties {
			return this._bindables
		}

		/**
		 * 해당 속성을 bind합니다.
		 * @param propertyName bind할 속성 명.
		 * @return bind한 종류를 보여주는 Factory.
		 */
		public bind(propertyName: bindable_property_name): cpr.bind.IBindFactory {
			return this._bindables.bind(propertyName)
		}

		/**
		 * 해당 속성을 unbind합니다.
		 * @param propertyName unbind할 속성 명.
		 */
		public unbind(propertyName: bindable_property_name) {
			this._bindables.unbind(propertyName);
		}

		/**
		 * 컨트롤의 바인드 속성 정보를 반환합니다.
		 * @param propertyName bind된 속성 명.
		 * @return BindInfo 속성
		 */
		public getBindInfo(propertyName: bindable_property_name): bind.BindInfo {
			let property = this._bindables.getBindableProperty(propertyName);
			if (!property) {
				return null;
			}
			return property.getCurrentBindInfo();
		}

		/**
		 * 질의된 속성이 바인딩 가능 하며, 유효한 값을 얻을 수 있도록 바인딩이 구성되어 있는지 여부를 반환합니다.
		 * 바인딩이 구성되지 않고 단순 값이 지정된 경우에도 유효값을 얻을 수 있도록 구성된 것으로 취급됩니다.
		 * 
		 * 예를 들어 DataSet에 존재하지 않는 행인덱스에 대한 바인딩 등이 유효하지 않은 바인딩 입니다.
		 * @param propertyName 바인딩의 유효성 여부를 체크할 속성 명.
		 */
		public isAvailableBinding(propertyName: bindable_property_name): boolean {
			let bindedProperty: bind.BindableProperty = this._bindables.getBindableProperty(propertyName);
			if (!bindedProperty) {
				return false;
			}
			let isActive: boolean = (bindedProperty.getDelegate() != null) ? bindedProperty.getDelegate().isActive() : true;
			return isActive && bindedProperty._isAvailable();
		}

		/**
		 * 사용자 정의 속성을 반환합니다.
		 * @return 사용자 정의 속성.
		 * @deprecated {@link userAttr}을 사용하시기 바랍니다.
		 */
		public userattr(): any {
			let args = _toArray(arguments);
			return this._userAttributes.userAttr.apply(this._userAttributes, args)
		}

		/**
		 * 사용자 정의 속성을 지정합니다.
		 * @param key 지정할 속성명
		 * @param value 지정할 속성 값.
		 */
		public userAttr(key: string, value: string): void

		/**
		 * 사용자 정의 속성을 반환합니다.
		 * @param key 얻을 속성 이름.
		 * @return 사용자 정의 속성.
		 */
		public userAttr(key: string): string

		/**
		 * 한번에 여러 사용자 정의 속성을 지정합니다.
		 * @param values 사용자 정의 속성 키/값을 담은 JSON 객체.
		 */
		public userAttr(values: { [key: string]: string }): void

		/**
		 * 모든 사용자 정의 속성을 맵 형태로 얻습니다.
		 */
		public userAttr(): { [key: string]: string }

		/**
		 * 사용자 정의 속성을 반환합니다.
		 * @return 사용자 정의 속성.
		 */
		public userAttr() {
			let args = _toArray(arguments);
			return this._userAttributes.userAttr.apply(this._userAttributes, args)
		}

		/**
		 * 사용자 정의 데이터를 지정합니다. 사용자 정의 속성과 달리 문자열 외에도 임의의 타입을 사용할 수 있습니다.
		 * 컨트롤이 dispose 되면 모든 사용자 정의 데이터는 제거 됩니다.
		 * @param key 지정할 데이터의 키.
		 * @param value 지정할 데이터.
		 */
		public userData(key: string, value: any): void;

		/**
		 * 사용자 정의 데이터를 얻습니다
		 * @param key 얻을 데이터의 키.
		 */
		public userData(key: string): any;

		/**
		 * 복수의 사용자 정의 데이터를 지정합니다.
		 * @param override 사용자 정의 데이터를 담은 JSON 객체.
		 */
		public userData(override: { [key: string]: any }): void;

		/**
		 * 모든 사용자 정의 데이터를 얻습니다.
		 */
		public userData(): { [key: string]: any };
		public userData(): any {
			let args: any[] = _toArray(arguments);
			switch (args.length) {
				case 0:
					return this._userData
						? CMap._toJSON(this._userData)
						: {}
						;

				case 1:
					if (typeof args[0] == "string") {
						return this._userData
							? this._userData.get(args[0])
							: undefined;
					} else if (typeof args[0] == "object") {
						if (!this._userData) {
							this._userData = _createMap();
						}

						Object.keys(args[0]).forEach(key => {
							let value = args[0][key];
							if (value === null || value === undefined) {
								this._userData.delete(key);
							} else {
								this._userData.set(key, value);
							}
						});
						return undefined;
					}

					else {
						throw new exceptions.IllegalArgumentException();
					}


				case 2:
					if (typeof args[0] != "string") {
						throw new exceptions.IllegalArgumentException();
					}
					let value = args[1];

					if (this._userData && value === null || value === undefined) {
						this._userData.delete(args[0]);
					} else {
						if (!this._userData) {
							this._userData = _createMap();
						}
						this._userData.set(args[0], value);
					}
					return;

				default: throw new exceptions.IllegalArgumentException();
			}
		}

		/**
		 * 특정 속성 명의 사용자 정의 속성을 제거합니다.
		 * @param key 제거할 사용자 정의 속성 명.
		 */
		public removeUserAttr(key: string): void {
			this._userAttributes.removeUserAttr(key)
		}

		/**
		 * 모든 사용자 정의 속성들을 삭제합니다.
		 */
		public removeAllUserAttr(): void {
			this._userAttributes.removeAllUserAttr()
		}

		/**
		 * 모든 사용자 정의 속성 명을 반환합니다.
		 * @return 모든 사용자 정의 속성 명의 배열.
		 */
		public getUserAttrNames(): string[] {
			return this._userAttributes.getUserAttrNames();
		}
		/* user attributes end */


		/* Abstract or callback methods */
		public abstract _getType(): cpr.controls.ControlType; // TODO abstract methods


		protected _getDeactivatedEventList(): string[] {
			return this._deactivatedEventList;
		}

		// FIXME 아무도 안씀.
		/**
		 * 이벤트 객체에 컨트롤이 속한 Context 관련 부가정보를 설정할 수 있는 Appender를 설정.
		 * @param appender
		 */
		_setRelatedTargetObjectProvider(provider: (e: events.CEvent) => any): void {
			this._relatedTargetObjectProvider = provider;
		}

		/**
		 * Event 객체에 추가 정보를 설정할 수 있도록 지원.
		 * @param evt 
		 */
		protected _setRelatedTargetObject(evt: events.CEvent): void {
			if (this._relatedTargetObjectProvider) {
				evt._setReletedTargetObjectProvider(this._relatedTargetObjectProvider);
			}
		}

		// 이벤트 구현

		// FIXME 대부분 컨트롤이 이 계약을 무시하고 있음. -- 지율
		/**
		 * 특정 이벤트의 활성화 여부를 설정합니다.
		 * @private
		 * @param eventType 이벤트 타입.
		 * @param activate 활성화 여부.
		 */
		setEventActivation(eventType: string, activate: boolean): void {
			let eventIdx: number = this._deactivatedEventList.indexOf(eventType);
			if (activate) {
				if (eventIdx > -1) {
					this._deactivatedEventList.splice(eventIdx, 1);
				}
			} else {
				if (eventIdx == -1) {
					this._deactivatedEventList.push(eventType);
				}
			}
		}


		/**
		 * 컨트롤에 EventType 별 Listener를 추가합니다.<br>
		 * 컨트롤에 특정 Event가 발생했을 때 처리하는 Listener를 추가합니다.
		 * <pre><code>var button = new cpr.controls.Button("btn01");
		 * button.addEventListener("click", function(e) {
		 * 	// event code...
		 * });
		 * </code></pre>
		 * 
		 * @param type 이벤트 타입.
		 * @param listener 이벤트 리스너.
		 */
		addEventListener(type: string, listener: (e: cpr.events.CEvent) => void): void {
			this._eventTable.addEventListener(type, listener);
		}

		/**
		 * 컨트롤에 EventType 별 한 번만 실행할 Listener를 추가합니다.<br>
		 * 컨트롤에 특정 Event가 발생했을 때 처리하는 Listener를 추가합니다.
		 * 추가된 Listener는 한번 실행된 후 자동으로 삭제됩니다.
		 * 추가된 Listener는 객체가 변경되므로 Listener 삭제 시
		 * addEventListenerOnce 호출 후 리턴되는 객체로 삭제가 가능합니다.
		 * <pre><code>var button = new cpr.controls.Button("btn01");
		 * button.addEventListenerOnce("click", function(e) {
		 * 	// event code...
		 * });
		 * </code></pre>
		 * 
		 * @param type 이벤트 타입.
		 * @param listener 이벤트 리스너.
		 * @return 변경된 Listener 객체.
		 */
		addEventListenerOnce(type: string, listener: (e: cpr.events.CEvent) => void): (e: cpr.events.CEvent) => void {
			this._eventTable.addEventListenerOnce(type, listener)
			return listener
		}

		/**
		 * 컨트롤에 EventType 별 Listener를 제거합니다.<br>
		 * <pre><code>control.removeEventListener('click', listener);</code></pre>
		 * @param type 이벤트 타입.
		 * @param listener 이벤트 리스너.
		 */
		removeEventListener(type: string, listener: (e: cpr.events.CEvent) => void): void {
			this._eventTable.removeEventListener(type, listener);
		}

		/**
		 * 컨트롤에 EventType의 모든 Listener 들을 제거합니다.<br>
		 * <pre><code>control.removeEventListeners('click');</code></pre>
		 * @param type 이벤트 타입.
		 */
		removeEventListeners(type: string): void {
			this._eventTable.removeEventListeners(type);
		}

		/**
		 * 컨트롤의 모든 이벤트 Listener를 제거합니다.
		 */
		removeAllEventListeners(): void {
			this._eventTable.removeAllEventListeners();
		}

		/**
		 * @param type 
		 * @param listener 
		 */
		_addInternalEventListener(type: string, listener: (e: events.CEvent) => void): void {
			this._internalEventTable.addEventListener(type, listener);
		}

		/**
		 * @param type 
		 * @param listener 
		 */
		_removeInternalEventListener(type: string, listener: (e: events.CEvent) => void): void {
			this._internalEventTable.removeEventListener(type, listener);
		}

		_removeAllInternalEventListeners(): void {
			this._internalEventTable.removeAllEventListeners();
		}

		/**
		 * 특정 이벤트를 전달합니다.
		 * @param e 이벤트
		 * @return 이벤트 전달 성공 여부.
		 */
		dispatchEvent(e: events.CEvent): boolean {
			if (this._deactivatedEventList.indexOf(e.type) > -1) {
				// event deactivated
				return false;
			}

			// Event 객체에 추가 정보를 설정할 수 있도록 지원
			this._setRelatedTargetObject(e);

			// FIXME: 이벤트 버스의 스코프가 단일 할 것인지 추가 검토 필요. --이지율
			let processContinue: boolean = events.EventBus.INSTANCE._dispatchEvent(e, this);
			// 이벤트 핸들러 동작 중 Control이 dispose 되었을 때 다음 처리를 중단한다.
			if (processContinue == true && this.disposed == true) {
				processContinue = false;
			}
			return processContinue;
		}

		/**
		 * 이벤트 리스너가 존재하는 경우에만 이벤트를 디스패치 합니다.
		 * @param type 디스패치할 이벤트 타입.
		 * @param eventFactory 이벤트 팩토리
		 */
		_dispatchEventIfNeeded(type: string, eventFactory: () => events.CEvent): events.CEvent {
			if (this._eventTable._hasEventListener(type) ||
				events.EventBus.INSTANCE._hasEventFilter(type)) {
				let e = eventFactory();
				this.dispatchEvent(e);
				return e;
			} else {
				return null
			}

		}

		/**
		 * 특정 이벤트를 수행합니다.
		 * @param e 이벤트
		 */
		_processEvent(e: cpr.events.CEvent): void {
			if ((this.disposed === false || e.type == "dispose") && this._eventTable.dispatchEvent(e)) {
				this._performDefault(e);
			}
		}

		/**
		 * 기본 이벤트를 수행합니다.
		 * @param e 이벤트
		 */
		_performDefault(e: cpr.events.CEvent): void {
			// internal event dispatch
			if ((this.disposed === false || e.type == "dispose")) {
				this._internalEventTable.dispatchEvent(e);
			}
		}

		/**
		 * 등록된 이벤트 리스너가 있는지 여부를 검사.
		 * @param type 체크할 이벤트 타입
		 */
		public _hasCustomEventListener(type: string): boolean {
			return this._eventTable._hasEventListener(type);
		}
		// 이벤트 구현 끝.

		/**
		 * 컨트롤이 앱인스턴스로 부터 고립상태를 계속 유지할 경우, 다음 틱에서 dispose()를 자동으로 실행하도록 등록합니다.
		 */
		_autoDispose(): void {
			if (this._isDisposed) {
				return;
			}

			core.AutoDisposingQueue.INSTANACE._scheduleDispose(this);
		}

		/**
		 * 컨트롤에 포함되어있는 객체들을 제거합니다.
		 */
		dispose(): void {
			if (this._isDisposed) {
				return;
			}

			if (this.getAppInstance()) {
				this.getAppInstance().unregister(this)
			}

			this._isDisposed = true;

			core.NotificationCenter.INSTANCE.unsubcribeAllTopic(this);
			let disposeEvent = new cpr.events.CEvent("dispose");
			this.dispatchEvent(disposeEvent);

			// this.removeAllAttribute();
			this.removeAllUserAttr();
			this.removeAllEventListeners();
			this._removeAllInternalEventListeners();

			// Bindables에 대한 메모리 해제
			this._bindables.dispose();
			this._bindables = null;
			this._userData = null;

			this._relatedTargetObjectProvider = null;

			// 마지막에 상태 변경
			// this._isDisposed = true;

			logger("control").log(`${this.type} ${this.uuid} was disposed`);
		}

		/**
		 * 컨트롤이 소속되어 있는 앱 인스턴스를 반환합니다.
		 * @return 컨트롤이 소속된 앱 인스턴스.
		 */
		getAppInstance(): core.AppInstance {
			return this._appInstance;
		}

		/**
		 * @param appInstance 
		 */
		_setAppInstance(appInstance: core.AppInstance) {
			if (this.getAppInstance() == appInstance) {
				return;
			}

			let oldAppInstance = this._appInstance;

			this._appInstance = appInstance;

			if (this._appInstance) {
				this._onAdapt(this._appInstance);
			} else {
				this._onOrphan(oldAppInstance);
			}

		}

		/**
		 * 특정 앱 인스턴스에 소속될 때 콜백됩니다.
		 * @param appInstance 현재 컨트롤을 포함하게 된 앱 인스턴스.
		 */
		_onAdapt(appInstance: core.AppInstance) {
			if (appInstance == null) {
				return;
			}
			appInstance.register(this);
			core.NotificationCenter.INSTANCE.post(core.SystemTopics.ADAPT, this, this);
		}

		/**
		 * 특정 앱 인스턴스로 부터 고립될 때 콜백 됩니다.
		 * @param oldAppInstance 고립되기전 이 컨트롤과 연결되어 있던 앱 인스턴스.
		 */
		_onOrphan(oldAppInstance: core.AppInstance) {
			if (oldAppInstance == null) {
				return;
			}
			oldAppInstance.unregister(this);
			core.NotificationCenter.INSTANCE.post(core.SystemTopics.ORPHAN, this, this);
		}

		/**
		 * 바인딩 가능한 속성인지 확인합니다.
		 * @param propertyName 속성 명
		 * @return 확인 여부.
		 */
		isBindable(propertyName: bindable_property_name): boolean {
			return this._bindables.isBindable(propertyName)
		}

		/**
		 * 해당 속성 값이 변동된 후에 수행되는 api입니다.
		 * @param name 속성 명
		 * @param oldValue 이전 속성 값.
		 * @param newValue 현재 속성 값.
		 */
		_valueDidChange(name: string, oldValue: any, newValue: any) {

		}

		/**
		 * bind 문맥을 반환합니다.
		 * @return bind 문맥
		 */
		getBindContext(): bind.BindContext {
			return null
		}

		/**
		 * @nonapi
		 * 바인드 가능한 속성을 추가합니다.
		 * @param name 속성 이름.
		 * @param initialValue 초기 값.
		 */
		_addBindableProperty(name: string, initialValue: any): bind.IBindedPropertyFactory {
			return this._bindables.add(name, initialValue)
		}

		_overwriteBindableProperty(name: string, initialValue: any): bind.IBindedPropertyFactory {
			if (this._bindables.isBindable(name)) {
				this._bindables.destroy(name);
			} else {
				throw new cpr.exceptions.IllegalArgumentException(`${name}은 기존에 바인드 되어 있지 않으므로 오버라이트 할 수 없습니다.`);
			}
			return this._addBindableProperty(name, initialValue);
		}

		_getExpressionIDLookupProvider() {
			return this.getAppInstance()
		}

		_getDebugIdentifier(): string {
			let appId: string = null;
			let appInstance = this.getAppInstance();
			if (appInstance) {
				appId = appInstance.app.id;
			}
			let result = "";
			if (appId) {
				result += `app://${appId}.clx/`
			}
			result += this.type;
			if (this.id) {
				result += `#${this.id}`
			}
			return result;
		}
	}
}