/// <reference path="../../utils/Util.ts"/>
namespace cpr.controls.layouts {
	let browserInfo = _detectBrowser();
	let useOldFlexSpec = browserInfo.name == "ie" && browserInfo.versionNumber < 11;

	/**
	* @private
	*/
	export abstract class FlexCSSBuilder {
		public static _forLayout() {
			return new FlexLayoutCSSBuilder();
		}

		public static _forCell() {
			return new FlexCellCSSBuilder();
		}

		public abstract _commit(output: { [key: string]: string }): void;

		public _commitToShape(shape: ufc.ElementShape) {
			shape.style = shape.style || {};
			this._commit(shape.style)
		};

		public _commitToRenderer(renderer: ufc.ControlRenderer, decoratorName: string = "layout") {
			renderer.addDecorator(decoratorName, shape => {
				this._commitToShape(shape);
				return shape;
			});
		}
	}

	/**
	 * @private
	 */
	export class FlexLayoutCSSBuilder extends FlexCSSBuilder {
		private _useInline = false;
		private _verticalAlign: FlexCellAlign = null;
		private _horizontalAlign: FlexCellAlign = null;
		private _direction: FlexDirection = null;

		public _withInlineFlex(useInline = true) {
			this._useInline = useInline;
			return this;
		}

		public _withHorizontalAlign(horizontalAlign: FlexCellAlign) {
			this._horizontalAlign = horizontalAlign;
			return this;
		}

		public _withVerticalAlign(verticalAlign: FlexCellAlign) {
			this._verticalAlign = verticalAlign;
			return this;
		}

		public _withDirection(direction: FlexDirection) {
			this._direction = direction;
			return this;
		}

		public _commit(output: { [key: string]: string }) {
			if (useOldFlexSpec) {
				if (this._useInline) {
					output["display"] = "-ms-inline-flexbox";
				} else {
					output["display"] = "-ms-flexbox";
				}
				if (this._verticalAlign != null) {
					output["-ms-flex-align"] = this._verticalAlign;
				}
				if (this._horizontalAlign != null) {
					output["-ms-flex-pack"] = this._horizontalAlign;
				}
				if (this._direction) {
					output["-ms-flex-direction"] = this._direction;
				}
			}
			else {
				if (this._useInline) {
					output["display"] = "inline-flex";
				} else {
					output["display"] = "flex";
				}
				let altProperties = { start: "flex-start", end: "flex-end" };
				if (this._verticalAlign != null) {
					let verticalAlign = altProperties[this._verticalAlign];
					output["align-items"] = verticalAlign ?? this._verticalAlign;
				}
				if (this._horizontalAlign != null) {
					let horizontalAlign = altProperties[this._horizontalAlign];
					output["justify-content"] = horizontalAlign ?? this._horizontalAlign;
				}
				if (this._direction) {
					output["flex-direction"] = this._direction;
				}
			}
		}

	}

	/**
	 * @private
	 */
	export enum FlexCellAlign {
		stretch = "stretch",
		start = "start",
		end = "end",
		center = "center",
		baseline = "baseline"
	}

	/**
	 * @private
	 */
	export enum FlexDirection {
		column = "column",
		row = "row",
		columnReverse = "column-reverse",
		rowReverse = "row-reverse"
	}

	/**
	 * @private
	 */
	export class FlexCellCSSBuilder extends FlexCSSBuilder {
		private _grow: number = 0;
		private _shrink: number = 1;
		private _basis: "auto" | string = "auto";
		private _verticalAlign: FlexCellAlign = FlexCellAlign.stretch;
		private _horizontalAlign: FlexCellAlign = FlexCellAlign.stretch;
		private _needsExplicitStretch = false;
		private _order: number = 0;

		public _withCellConstraint(grow: number, shrink: number, basis: "auto" | string) {
			this._grow = grow;
			this._shrink = shrink;
			this._basis = basis;
			return this;
		}

		public _withHorizontalAlign(horizontalAlign: FlexCellAlign) {
			this._horizontalAlign = horizontalAlign;
			return this;
		}

		public _withVerticalAlign(verticalAlign: FlexCellAlign) {
			this._verticalAlign = verticalAlign
			return this;
		}

		public _withGrow(grow: number) {
			this._grow = grow;
			return this;
		}

		public _withShrink(shrink: number) {
			this._shrink = shrink;
			return this;
		}

		public _withOrder(order: number) {
			this._order = order;
			return this;
		}

		/**
		 * 일반적인 경우, 셀의 얼라인 타입이 strech 인 경우 생략해도 되지만, 이미지등의 노드의 경우 명시적 지정이 필요한 경우가 있음.
		 * @param needsExplicitStretch 셀의 얼라인 타입이 strech인 경우에도 명시적으로 지정할 것인지 여부.
		 */
		public _withExplicitStrech(needsExplicitStretch: boolean): FlexCellCSSBuilder {
			this._needsExplicitStretch = needsExplicitStretch;
			return this;
		}

		public _commit(output: { [key: string]: string }) {
			if (useOldFlexSpec) {
				output["-ms-flex-positive"] = `${this._grow}`;
				output["-ms-flex-negative"] = `${this._shrink}`;
				output["-ms-flex-preferred-size"] = `${this._basis}`;

				if (this._needsExplicitStretch || this._verticalAlign != FlexCellAlign.stretch) {
					output["-ms-flex-item-align"] = this._verticalAlign;
				}
				if (this._order != 0) {
					output["-ms-flex-order"] = `${this._order}`;
				}
			}
			else {
				output["flex-grow"] = `${this._grow}`;
				output["flex-shrink"] = `${this._shrink}`;
				output["flex-basis"] = `${this._basis}`;
				let altProperties = { start: "flex-start", end: "flex-end" };
				if (this._needsExplicitStretch || this._verticalAlign != FlexCellAlign.stretch) {
					let verticalAlign = altProperties[this._verticalAlign];
					output["align-self"] = verticalAlign ?? this._verticalAlign;
				}
				if (this._needsExplicitStretch || this._horizontalAlign != FlexCellAlign.stretch) {
					let horizontalAlign = altProperties[this._horizontalAlign];
					output["justify-self"] = horizontalAlign ?? this._horizontalAlign;
				}
				if (this._order != 0) {
					output["flex-order"] = `${this._order}`;
				}

			}
		}
	}


}