		private _onItemClick(e: MouseEvent) {
			let rootEle = <HTMLElement>e.currentTarget;
			let eventTarget = <HTMLElement>e.target;
			let domTraverser = ufc._traverseFromElement(eventTarget);
			domTraverser = domTraverser._closest(".cl-calendar-item", rootEle);
			if (domTraverser) {
				let itemValue = domTraverser._getAttribute("data-itemid");
				if (itemValue) {
					let item = null;
					this._events.some((each) => {
						if (each.id == itemValue) {
							item = each;
							return true;
						}
					});

					// this._selectItem(item, e.ctrlKey);
					if (this._selectedAnniversary) {
						this._selectedAnniversary = null;
					}
					let itemEvent = new cpr.events.CItemEvent(cpr.events.ItemEventType.ITEMCLICK, { relativeTargetName: "item", item: item });
					itemEvent.nativeEvent = e;
					this._owner.dispatchEvent(events.ItemEventType.ITEMCLICK, itemEvent);
				}
			}
		}

		private _onAnniversaryClick(e: MouseEvent) {
			let rootEle = <HTMLElement>e.currentTarget;
			let eventTarget = <HTMLElement>e.target;
			let domTraverser = ufc._traverseFromElement(eventTarget);
			domTraverser = domTraverser._closest(".cl-anniversary", rootEle);
			if (domTraverser) {
				let itemValue = domTraverser._getAttribute("data-anniversary");
				if (itemValue) {
					let date = domTraverser._getAttribute("data-date");
					let anny = this._owner.getAnniversariesWithGlobal(moment(date, "YYYY-MM-DD").toDate());
					let item = null;
					anny.some((each) => {
						if (each.label == itemValue) {
							item = each;
							return true;
						}
						return false;
					});

					this._selectAnniversary(item);
					let itemEvent = new cpr.events.CItemEvent(events.ItemEventType.ITEMCLICK, { relativeTargetName: "anniversary", item: item });
					itemEvent._setTargetObject({ date: moment(domTraverser._getAttribute("data-date"), "YYYY-MM-DD").toDate() });
					itemEvent.nativeEvent = e;
					this._owner.dispatchEvent(events.ItemEventType.ITEMCLICK, itemEvent);
				}
			}
		}

		public _onclick(e: MouseEvent) {
			let eventElement: HTMLElement = <HTMLElement>e.target;
			let rootEle: HTMLElement = <HTMLElement>e.currentTarget;
			if (eventElement == null) {
				return;
			}
			let domTraverser = ufc._traverseFromElement(eventElement);
			domTraverser = domTraverser._closest(".cl-calendar-item", rootEle);
			if (domTraverser && domTraverser._getElement().classList.contains(ufc.Classes.DISABLED) == false) {
				this._onItemClick(e);

			}

			domTraverser = ufc._traverseFromElement(eventElement);
			domTraverser = domTraverser._closest(".cl-anniversary", rootEle);
			if (domTraverser && domTraverser._getElement().classList.contains(ufc.Classes.DISABLED) == false) {
				this._onAnniversaryClick(e);
			}

			domTraverser = ufc._traverseFromElement(eventElement);
			domTraverser = domTraverser._closest(".cl-calendar-more", rootEle);
			if (domTraverser && domTraverser._getElement().classList.contains(ufc.Classes.DISABLED) == false) {
				this._onCalendarMoreClick(e);
			}
		}

		public _onResize(e: events.CUIEvent) {
			if (this._isAutoHeight()) {
				return;
			}
			if (this._owner.showAnniversary || this._owner.showItem) {
				if (this._checkContentSpace()) {
					this._cache.forEach((each) => {
						this._renderDetailRow(each.index, each.detailInfo);
					})
				}
			}
		}

		private _onmousedown(e: events.CMouseEvent) {
			if (this._owner.owner.focused) {
				e.preventDefault();
			}
		}

		private _getNamedNode(name: string) {
			return this._owner.owner._getRenderer().getNamedNode(name);
		}

		private _getQualifierName(name: string) {
			return "day-" + name;
		}
