/// <reference path="./provider/DataBindable.ts"/>
/// <reference path="./AccessableUIControl.ts"/>

namespace cpr.controls {

	type ARIA_BUTTON_TYPE = "button" | "link";

	/**
	 * 아이콘 위치의 값
	 */
	export enum ButtonIconAlign {
		/**
		 * 아이콘을 왼쪽으로 표시합니다.
		 */
		left = "left",
		/**
		 * 아이콘을 오른쪽으로 표시합니다.
		 */
		right = "right",
		/**
		 * 아이콘을 위로 표시합니다.
		 */
		top = "top",
		/**
		 * 아이콘을 아래쪽으로 표시합니다.
		 */
		bottom = "bottom"
	}

	/**
	 * button
	 * 마우스 클릭이 가능한 버튼 컨트롤.
	 * 
	 * @firesgroup mouse
	 * @firesgroup contextmenu
	 * @firesgroup bindcontext
	 * @firesgroup keyboard
	 * @firesgroup focus
	 * @firesgroup drop
	 * 
	 * @fires cpr.events.CValueChangeEvent#before-value-change Button의 value를 변경하여 변경된 값이 저장되기 전에 발생하는 이벤트.
	 * 		다음 이벤트로 value-change가 발생합니다.
	 * 		<pre>oldValue: {string} 이전 값</pre>
	 * 		<pre>newValue: {string] 현재 값</pre>
	 * 
	 * @fires cpr.events.CValueChangeEvent#value-change Button의 value를 변경하여 변경된 값이 저장된 후에 발생하는 이벤트.
	 * 		<pre>oldValue: {string} 이전 값</pre>
	 * 		<pre>newValue: {string} 현재 값</pre>
	 */
	export class Button extends AccessableUIControl implements provider.ValueBindable, gridpart.IGridParticipant {
		private static readonly _AVAILABLE_PROP: string[] = [
			"value", "displayExp", "text", "icon", "iconAlign", "ariaButtonType"
		];

		//TODO: 버튼의 기본 backgroud를 변경했을때 IE,FireFox만 마우스로 누르는 효과가 나타남.
		private _binder: provider.ValueBinder;
		private _displayExpObj: expression.Expression;

		/**
		 * 새 버튼을 만듭니다.
		 * @param id 버튼의 ID.
		 */
		constructor(id?: string) {
			super(id);
			this._binder = new provider.ValueBinder(this);

			this._addBindableProperty("icon", "").withSetterValidatorWithType(false, "string", true).withStringGetterTransformer("");
			this._addBindableProperty("iconAlign", "left").withSetterValidatorWithType(false, "string");
			this._addBindableProperty("displayExp", "").withSetterValidatorWithType(false, "string");

			// control initializing
			this._initControl();
		}

		protected _isConfigurableProperty(propName: string): boolean {
			if (Button._AVAILABLE_PROP.indexOf(propName) != -1) {
				return true;
			}
			return super._isConfigurableProperty(propName);
		}

		// Shape 
		protected _getStylerSpec(): UIControlStylerSpec {
			return {
				root: { baseClass: "cl-button" },
				icon: { baseClass: ufc.Classes.ICON }
			};
		}

		protected override _getAccessibilitySpec(): AriaSpec {
			return {
				root: { role: "button" }
			}
		}

		override _getType(): ControlType {
			return ControlType.BUTTON
		}
		override _getLabelableType(): LabelableType {
			return LabelableType.div;
		}

		private _softDeactivationTimeoutID: number = undefined
		private _isSoftActivated: boolean = false

		/// SimpleDataBindable Start ////////////////////////////////////////////
		/**
		 * 컨트롤의 값을 설정하고, value-change 이벤트를 발생합니다.
		 * @param value 컨트롤의 값.
		 */
		public set value(value: string) {
			this._binder.setValue(value);
		}

		/**
		 * 컨트롤의 값을 반환합니다.
		 * @return 컨트롤의 값.
		 */
		public get value(): string {
			return this._binder.getValue();
		}

		/**
		 * 컨트롤의 값을 설정합니다.
		 * @param value 컨트롤의 값.
		 */
		public putValue(value: string) {
			this._binder.setValue(value, false);
		}

		/**
		 * 컨트롤에 보여지는 텍스트를 반환합니다.
		 * @return 화면에 보이는 텍스트.
		 */
		public get text(): string {
			return ufc.StyledString._asString(this._computeDisplayText());
		}

		/**
		 * 컨트롤에 보이는 텍스트를 설정합니다.
		 * @param 화면에 보이는 텍스트.
		 */
		public set text(text: string) {
			this._binder.setText(text);
		}

		/**
		 * 버튼의 역할을 값을 반환합니다.
		 */
		public get ariaButtonType(): ARIA_BUTTON_TYPE {
			return this.accessibility.aria("role") as ARIA_BUTTON_TYPE;
		}

		/**
		 * 버튼의 역할을 설정합니다. 스크린리더에서 영향을 줍니다.
		 */
		public set ariaButtonType(role: ARIA_BUTTON_TYPE) {
			let oldRole = this.accessibility.aria("role");
			this.accessibility.aria("role", role);
			if (oldRole != this.accessibility.aria("role")) {
				this.redraw();
			}
		}

		/**
		 * @param name 
		 * @param oldValue 
		 * @param newValue 
		 */
		_valueDidChange(name: string, oldValue: any, newValue: any) {
			super._valueDidChange(name, oldValue, newValue);
			this._binder._valueDidChange(name, oldValue, newValue);
			switch (name) {
				case "icon":
				case "displayExp":
				case "iconAlign": {
					this.redraw();
					break;
				}
			}
		}
		/// SimpleDataBindable End ////////////////////////////////////////////////

		public _focusByAccessKey() {
			this._focusImmediately();
			this._dispatchClickEventWithSoftActivation(new events.CMouseEvent('click'));
		}

		/**
		 * 아이콘의 경로를 반환합니다.
		 */
		get icon() {
			return this._bindables.get("icon");
		}
		/**
		 * 아이콘의 경로를 설정합니다.
		 */
		set icon(path: string) {
			this._bindables.set("icon", path);
		}

		/**
		 * 아이콘의 정렬 위치를 반환합니다.
		 */
		get iconAlign(): ButtonIconAlign {
			return this._bindables.get("iconAlign");
		}

		/**
		 * 아이콘의 정렬 위치를 설정합니다.
		 */
		set iconAlign(value: ButtonIconAlign) {
			this._bindables.set("iconAlign", value);
		}

		/**
		 * 화면에 보여지는 텍스트의 Expression을 반환합니다.
		 * @return 화면에 보여지는 텍스트의 Expression.
		 */
		get displayExp(): expression_string {
			return this._bindables.get("displayExp");
		}

		/**
		 * 화면에 보여지는 텍스트의 Expression을 설정합니다.
		 * @param expr 화면에 보여지는 텍스트의 Expression.
		 */
		set displayExp(newValue: expression_string) {
			this._bindables.set("displayExp", newValue);
		}

		// Shape 
		public _createShape(): cpr.ufc.ElementShape {
			let contents = this._createContents();

			// 버튼 태그를 사용했을때 액티브엑스에서 동작하지 않는 문제로 버튼태그 제거.
			// 크롬에서 버튼이 absolute right,left,top,bottom 을 모두 주었을때 문제로 button tag를 사용하지 않음.
			// 전체 컨트롤의 accesskey 동작을 맞추기 위해 button tag 사용함.
			// 크롬에서의 absolute 문제는 button tag를 div tag로 감싸서 해결. 2017.12.20 배소영
			let rootShape: ufc.ElementShape = {
				tag: "div",
				attr: {
					tabindex: "0"
				},
				aria: "root",
				classNames: [ufc.Classes.UNSELECTABLE],
				events: {
					selectstart: this._preventSelectStart,
					keydown: this._onKeyDown,
					mousedown: this._onMouseDown,
					mouseup: this._onMouseUp,
					mouseout: this._onMouseUp
				},
				style: {
					"line-height": "100%"
				},
				eventTargets: [
					ufc.EventTargetType.UICONTROL,
					ufc.EventTargetType.DROPPABLE
				],
				styler: "root",
				children: [contents]
			}
			cpr.ufc.ShapeUtil._setAriaDisabled(rootShape, this.enabled);
			cpr.ufc.ShapeUtil._setTooltipAttr(rootShape, { owner: this, title: this.tooltip });
			let lineHeight = this.style.css("line-height");
			if (lineHeight) {
				delete rootShape.style["line-height"];
			}

			if (this._isSoftActivated) {
				rootShape.classNames.push(ufc.Classes.ACTIVATED)
			}
			if (this.icon) {
				rootShape.classNames.push("cl-icon-align-" + this.iconAlign);
			}
			if (this.enabled == false) {
				delete rootShape.attr['tabindex'];
			}
			return rootShape;
		}

		private _createContents(): ufc.ElementShape {
			let button: ufc.ElementShape = {
				tag: "div",
				nodename: "button",
				classNames: ["cl-text-wrapper"],
				attr: {},
				style: {
					outline: "none",
					textDecoration: "inherit",
					background: "transparent",
					textShadow: "inherit",
					border: "none",
					font: "inherit",
					color: "inherit",
					"text-align": "inherit",
					cursor: "inherit",
					height: "100%",
					width: "100%",
					padding: "0px"
				},
				events: {},
				children: this.icon ? [this._createIcon(), this._createText()] : [this._createText()]
			};

			let flexLayoutBuilder = layouts.FlexCSSBuilder._forLayout()._withInlineFlex()._withVerticalAlign(layouts.FlexCellAlign.center)._withHorizontalAlign(layouts.FlexCellAlign.center);
			if (this.icon) {
				button.style["width"] = "auto";
				switch (this.iconAlign) {
					case ButtonIconAlign.bottom: {
						flexLayoutBuilder._withDirection(layouts.FlexDirection.columnReverse);
						break;
					}
					case ButtonIconAlign.right: {
						flexLayoutBuilder._withDirection(layouts.FlexDirection.rowReverse);
						break;
					}
					case ButtonIconAlign.top: {
						flexLayoutBuilder._withDirection(layouts.FlexDirection.column);
						break;
					}
				}
			}
			flexLayoutBuilder._commit(button.style);
			return button;
		}

		private _getDisplayExpObj() {
			let src = this.displayExp;

			if (utils.Util.isNullOrEmpty(src)) {
				return null;
			}

			if (this._displayExpObj && this._displayExpObj?.src == src) {
				return this._displayExpObj;
			}

			this._displayExpObj = new cpr.expression.Expression(src);
			return this._displayExpObj;
		}

		public _computeDisplayText(): string | ufc.StyledString {
			let expression = this._getDisplayExpObj();
			if (!expression) {
				return this.value;
			}

			return expression.evaluate({
				_getExpressionDelegates: () => {
					return [
						{ text: this.value },
						this,
						this.getBindContext()
					]
				}
			});
		}

		public _exportValue(): string | number {
			let ctrlText = (this.text === undefined) ? this.value : this.text;

			// 기본 >> text
			return (ctrlText != null) ? "" + ctrlText : "";
		}

		private _createText(): ufc.ElementShape {
			let attrs = {};
			let classNames = [ufc.Classes.TEXT];
			if (this.enabled == false) {
				classNames.push(ufc.Classes.DISABLED);
			}

			let text: ufc.ElementShape = {
				tag: "div",
				classNames: classNames,
				attr: attrs,
				style: {
					background: "transparent",
					textShadow: "inherit",
					border: "none",
					font: "inherit",
					color: "inherit",
					"text-align": "inherit",
					cursor: "inherit",
					height: "auto",
					width: "100%",
					padding: "0px"

				},
				children: ufc.StyledString._asShape(this._computeDisplayText())
			}
			if (this.icon) {
				text.style["width"] = "auto";
			}
			return text;
		}

		private _createIcon(): ufc.ElementShape {
			let icon: ufc.ElementShape = {
				tag: "div",
				classNames: [ufc.Classes.ICON],
				styler: "icon",
				attr: {},
				style: {

				},
				children: []
			}

			let iconBackgroundImage = this.style["icon"].css("background-image");
			if (!iconBackgroundImage && this.icon != "") {
				icon.style['background-image'] = _quoteAsCSSURL(this.icon);
			}
			return icon;
		}

		public _setSoftActivated(active: boolean) {
			if (this._softDeactivationTimeoutID) {
				window.clearTimeout(this._softDeactivationTimeoutID)
				delete this._softDeactivationTimeoutID
			}
			if (this._isSoftActivated == active) {
				return
			}
			this._isSoftActivated = active
			this.redraw()
		}

		public _preventSelectStart(e: UIEvent): void {
			e.preventDefault();
		}

		private _dispatchClickEventWithSoftActivation(e: events.CMouseEvent) {
			// 가짜 :active 효과
			this._setSoftActivated(true)
			this.redraw()

			core.DeferredUpdateManager.INSTANCE.asyncExec(() => {
				requestAnimationFrame(() => {
					this._forceDispatchEvent(e)
					this._setSoftActivated(false)
				})
			})
		}

		public _onKeyDown(e: KeyboardEvent) {
			if (e.defaultPrevented) {
				return;
			}
			switch (e.keyCode) {
				case 13: case 32: {
					let event = new cpr.events.CMouseEvent('click')
					this._dispatchClickEventWithSoftActivation(event)

					// 기본동작 차단.
					e.preventDefault()
					break;
				}
			}
		}

		public _onMouseDown(e: MouseEvent) {
			this._setSoftActivated(true);
		}

		public _onMouseUp(e: MouseEvent) {
			if (!this._isSoftActivated) {
				return
			}
			window.setTimeout(() => {
				this._setSoftActivated(false)
			})
		}


		// public method 

		/**
		 * button의 클릭 이벤트를 발생합니다.<br>
		 * default 이벤트 또는 click 이벤트에 해당하는 eventlistener의 함수를 수행합니다.
		 */
		public click(): void {
			this.dispatchEvent(new cpr.events.CMouseEvent('click'));
		}

		public _getAutoSizeAvailability(): layouts.AutoSizeType {
			return layouts.AutoSizeType.both;
		}

		public _convertGridPasteText(text: string): string {
			return text;
		}

		public _getGridViewingText(): string {
			return this.text;
		}

		public _renderGridCellShape(grid: Grid, data: (string | ufc.StyledString), option: gridpart.renderer.IRenderOption): ufc.ControlShape {
			// 크롬에서 버튼이 absolute right,left,top,bottom 을 모두 주었을때 문제로 button tag를 사용하지 않음.
			// 전체 컨트롤의 accesskey 동작을 맞추기 위해 button tag 사용함.
			// 크롬에서의 absolute 문제는 button tag를 div tag로 감싸서 해결. 2017.12.20 배소영
			let wrapperShape: ufc.ControlShape = {
				tag: "div",
				attr: {
					tabindex: "0"
				},
				classNames: ["cl-control", "cl-button", ufc.Classes.UNSELECTABLE],
				style: {
					lineHeight: "100%"
				}
			};
			if (option.maxHeight >= 0) {
				wrapperShape.style["height"] = option.maxHeight + "px";
			}
			cpr.ufc.ShapeUtil._setAriaDisabled(wrapperShape, this.enabled && !this.readOnly);
			gridpart.GridUtil._applyControlAccessbility(wrapperShape, this, "root", null);		//apply accessbility
			if (utils.Util.isNullOrEmpty(option.ariaLabel) == false) {
				cpr.ufc.ShapeUtil._setAriaLabelAttr(wrapperShape.attr, option.ariaLabel);
			}
			let children: ufc.ElementShape[] = [];
			if (this.icon) { // createIcon
				let iconShape: ufc.ElementShape = {
					tag: "div",
					classNames: [ufc.Classes.ICON],
					styler: "icon",
					attr: {},
					style: this.style["icon"].css(),
					children: []
				}

				let iconBackgroundImage = this.style["icon"].css("background-image");
				if (!iconBackgroundImage && this.icon != "") {
					iconShape.style['background-image'] = _quoteAsCSSURL(this.icon);
				}
				cpr.controls.gridpart.GridUtil._applyControlStyler(iconShape, this.style["icon"], null);		//apply styler
				children.push(iconShape);
			}

			// createText
			let text: string | ufc.StyledString = null;
			if (option.hidetext) {
				text = "";
			} else {
				text = this._computeDisplayText();
			}
			let textShape: ufc.ElementShape = {
				tag: "div",
				attr: {},
				classNames: [ufc.Classes.TEXT],
				style: {
					background: "transparent",
					textShadow: "inherit",
					border: "none",
					font: "inherit",
					color: "inherit",
					"text-align": "inherit",
					cursor: "inherit",
					height: "auto",
					width: "100%",
					padding: "0px"
				},
				children: ufc.StyledString._asShape(text)
			};
			children.push(textShape);

			let buttonShape: ufc.ElementShape = {
				tag: "div",
				nodename: "button",
				classNames: ["cl-text-wrapper"],
				attr: {},
				style: {
					// outline: "none",
					textDecoration: "inherit",
					background: "transparent",
					textShadow: "inherit",
					// border: "none",
					font: "inherit",
					color: "inherit",
					"text-align": "inherit",
					cursor: "inherit",
					height: "100%",
					width: "100%",
					padding: "0px"
				},
				// aria: "root",
				children: children
			};
			if (this.enabled == false) {
				textShape.classNames.push(ufc.Classes.DISABLED);
			}

			let browserInfo = _detectBrowser();
			if (browserInfo.name == "ie" && browserInfo.versionNumber < 11) {
				buttonShape.style["display"] = "-ms-inline-flexbox";
				buttonShape.style["-ms-flex-align"] = "center";
				buttonShape.style["-ms-flex-pack"] = "center";
			} else {
				buttonShape.style["display"] = "inline-flex";
				buttonShape.style["align-items"] = "center";
				buttonShape.style["justify-content"] = "center";
			}

			if (this.icon) {
				textShape.style["width"] = "auto";
				buttonShape.style["width"] = "auto";
				wrapperShape.classNames.push("cl-icon-align-" + this.iconAlign);
				switch (this.iconAlign) {
					case ButtonIconAlign.bottom: {
						buttonShape.style["flex-direction"] = "column-reverse";
						break;
					}
					case ButtonIconAlign.right: {
						buttonShape.style["flex-direction"] = "row-reverse";
						break;
					}
					case ButtonIconAlign.top: {
						buttonShape.style["flex-direction"] = "column";
						break;
					}
				}
			}
			wrapperShape.children = [buttonShape];

			return wrapperShape;
		}

		override dispose(): void {
			super.dispose();
		}

	}
}