/// <reference path="./Accessibility.ts" />

namespace cpr.controls {
	/**
	 * 개별 아이템별 접근성 설정을 지원하는 Accessibility 클래스
	 * @noinstance
	 */
	export class ItemsAccessibility extends Accessibility {
		private _itemAccessibilities: CMap<string, Accessibility>;

		constructor(owner: UIControl, spec: AriaSpec) {
			super(owner, spec);
			this._itemAccessibilities = _createMap<string, Accessibility>();
		}

		public _forUUID(itemUUID: string): Accessibility {
			let cachedAccessibility = this._itemAccessibilities.get(itemUUID);
			if (cachedAccessibility) {
				return cachedAccessibility;
			}
			return null;
		}

		/**
		 * 특정 아이템을 위한 Accessibility 인스턴스를 복제합니다.
		 * 현재 AriaSet을 기본값으로 사용하는 새 인스턴스를 생성합니다.
		 * @returns 복제된 Accessibility 인스턴스
		 */
		private _createItemAccessibility(item: Item): Accessibility {
			// 현재 AriaSet을 복사하여 새 spec 생성
			let clonedAriaSet = _mergeObject({}, this._getAriaSet());
			let newSpec: AriaSpec = {
				root: clonedAriaSet
			};
			let itemAccessibility = new ItemAccessibility(this._getOwner(), newSpec, item);
			itemAccessibility._setName(this._getName());
			return itemAccessibility;
		}

		public _hasItemAccessibility(itemUUID: string): boolean {
			return this._itemAccessibilities.has(itemUUID);
		}

		/**
		 * 특정 아이템에 대한 Accessibility 인스턴스를 반환합니다.
		 * 캐시되어 있지 않으면 새로 생성하고 캐시합니다.
		 * @param item 접근성을 설정할 아이템
		 * @returns 해당 아이템의 Accessibility 인스턴스
		 */
		public forItem(item: Item | TabItem): Accessibility {
			let itemUUID = item._getUUID();
			let cachedAccessibility = this._itemAccessibilities.get(itemUUID);

			if (cachedAccessibility) {
				return cachedAccessibility;
			}

			// 기본 spec을 복제하여 새 Accessibility 생성
			let itemAccessibility = this._createItemAccessibility(item as Item);
			this._itemAccessibilities.set(itemUUID, itemAccessibility);

			return itemAccessibility;
		}

		/**
		 * 특정 아이템의 Accessibility 캐시를 제거합니다.
		 * @param item 캐시를 제거할 아이템
		 */
		public _removeItemAccessibility(item: Item | TabItem): void {
			this._itemAccessibilities.delete(item._getUUID());
		}

		/**
		 * 모든 아이템 Accessibility 캐시를 제거합니다.
		 */
		public _clearItemAccessibilities(): void {
			this._itemAccessibilities.clear();
		}

		public dispose(): void {
			this._itemAccessibilities.forEach((each) => {
				each.dispose();
			});
			this._itemAccessibilities.clear();
			super.dispose();
		}
	}
}