/// <reference path="./layout/ScrollPane.ts"/>
/// <reference path="./IGridPart.ts"/>


namespace cpr.controls.gridpart {

	/**
	 * @private
	 */
	export class GridDetail extends AbstractGridPart {
		private _gridRow: renderer.GridRowRenderer;
		private _gridRowGroup: GridRowGroupRendererConfig;

		/**
		 * GridDetail에 의해 실제 그려진 마지막 로우인덱스
		 */
		private _renderedEndRowIdx: number = -1;
		private _isLastContent: boolean = false;


		constructor(context: GridContext
			, gridRow: renderer.GridRowRenderer
			, gridRowGroup: GridRowGroupRendererConfig
			, region: string
			, vloc: string
			, bandLayout: GridRegionLayout) {

			super(region, vloc, context, bandLayout);
			this._gridRow = gridRow;
			this._gridRowGroup = gridRowGroup;
		}

		public _getContentHeight(): number {
			let gridContext: GridContext = this._getContext();
			let contentHeight: number = gridContext._getContentHeight(this.loc);
			if (contentHeight == -1) {
				let startRowIndex: number = this.getStartRowIndex();
				let endRowIndex: number = this.getEndRowIndex();
				if (startRowIndex >= 0 && endRowIndex >= 0 && endRowIndex >= startRowIndex) {
					contentHeight = gridContext._getRangeHeight(startRowIndex, endRowIndex, this.loc);
				} else {
					contentHeight = 0;
				}
				if (contentHeight == 0) {
					contentHeight = 1; // ContentHeight가 0일 때 브라우저에서 영역을 제공하지 않는 문제가 있음(IE, Chrome 공통)
				}
				gridContext._setContentHeight(this.loc, contentHeight);
			}
			return contentHeight;
		}

		/**
		 * GridDetail에서 그릴 수 있는 DataSet의 시작 Row Index.
		 */
		public getStartRowIndex(): number {
			return this._getContext()._getStartRowIndex(this.loc);
		}

		/**
		 * GridDetail에서 그릴 수 있는 DataSet의 마지막 Row Index.
		 */
		public getEndRowIndex(): number {
			return this._getContext()._getEndRowIndex(this.loc);
		}

		/**
		 * 실제 그려진 시작행의 인덱스.
		 */
		public _getRenderedStartRowIdx(): number {
			let renderStartRowIndex: number = this._getRenderStartRowIndex();
			let renderEndRowIndex: number = this._getRenderEndRowIndex();

			this._isLastContent = GridUtil._isLastContent(this._getContext().getGrid(), renderStartRowIndex, renderEndRowIndex, this.region, this.loc);
			if (this._isLastContent) {
				renderStartRowIndex--;
			}
			return renderStartRowIndex;
		}

		/**
		 * 실제 그려진 마지막행의 인덱스.
		 */
		public _getRenderedEndRowIdx(): number {
			return this._renderedEndRowIdx;
		}

		/**
		 * GridDetail에서 이번 이벤트에 그릴/그려진 DataSet의 시작 Row Index.
		 * 스크롤 기준 renderStartRow
		 */
		public _getRenderStartRowIndex(): number {
			return (this._scrollPane as layout.ScrollPane)._getRenderStartRow();
		}

		public _getRenderEndRowIndex(): number {
			return (this._scrollPane as layout.ScrollPane)._getRenderEndRow();
		}

		/* Shape */
		protected _doCreateShape(): ufc.ControlShape {
			let context: GridContext = this._getContext();
			let grid: Grid = context.getGrid();
			let autoFit: string = context._getRegionAutoFit(this.region);
			let clientWidth: number = this._scrollPane._getViewportWidth();
			let regionColWidth: { contentWidth: number, layout: { width: number }[] } = GridUtil._createRegionColWidth(autoFit, clientWidth, this._layout.columnLayout);

			// rows
			let rows: ufc.ElementShape[] = [];
			let cellPositionRange: { start: number, end: number } = (this._scrollPane as layout.ScrollPane)._getRenderCellRange();
			this._renderedEndRowIdx = -1; // RenderedEndRowIdx 초기화
			if (context._isGrouping()) {
				rows = this._createRowGroups(cellPositionRange, regionColWidth.layout);
			} else {
				rows = this._createRows(cellPositionRange, regionColWidth.layout);
			}

			let detailShape: ufc.ElementShape = {
				tag: "div",
				attr: {},
				classNames: [GridContext.CLS_CELL_INHERIT],
				style: {
					position: "relative",
					border: "0"
				},
				children: []
			};
			detailShape.style["height"] = this._getViewingContentHeight() + "px";

			if (autoFit !== "none" && clientWidth > regionColWidth.contentWidth) {
				detailShape.style["width"] = clientWidth + "px";
			} else {
				detailShape.style["width"] = regionColWidth.contentWidth + "px";
			}

			// mouse hover
			if (context._getHoveredLocation() != null && context._getHoveredLocation() == this.loc) {
				let hoveredElIndex: number = context._getHoveredElementIndex();
				if (hoveredElIndex < rows.length) {
					let hoveredRow: ufc.ElementShape = rows[hoveredElIndex];
					let classNames: string[] = hoveredRow.classNames;
					classNames.push(ufc.Classes.HOVER);

					hoveredRow.nodename = "hover-" + this.region; // 이벤트에 의해 Hover Class를 Shape에서 제거할 수 있도록 하기 위해 이름 부여
					context._setHoveredLocation(this.loc, hoveredElIndex, hoveredRow.attr["data-rowindex"], hoveredRow.attr["data-vrowindex"]);
				}
			}
			detailShape.children = rows;

			// div
			let shape: ufc.ControlShape = {
				tag: "div",
				attr: {},
				style: {
					transform: "translate3d(0px, 0px, 0px)",
					position: "relative",
					"min-width": "100%"
				},
				nodename: "detail" + this.region + this.loc, // split 되었을 때 중복남
				children: [detailShape]
			};

			if (context._isReqHScroll() == false && context._isReqVScroll() == false) {
				delete shape.style["transform"];
			}

			if (this._isLastContent == true) {
				let startrowIndex: number = this._getRenderStartRowIndex();
				let endrowIndex: number = this._getRenderEndRowIndex();
				let viewportHeight: number = context._getViewportHeight(this.loc);
				let blankHeight: number = context._getBlankTopPosition(this.loc, startrowIndex, endrowIndex, viewportHeight);
				shape.style["top"] = "-" + blankHeight + "px";
			}
			return shape;
		}

		// helper methods
		private _createRows(cellPositionRange: { start: number, end: number }, regionColWidth: { width: number }[]): ufc.ElementShape[] {
			let gridContext: GridContext = this._getContext();
			let grid: Grid = gridContext.getGrid();

			let startrowIndex: number = this._getRenderedStartRowIdx();
			let endrowIndex: number = this._getRenderEndRowIndex();
			let editRowIndex: number = gridContext.editingRowIndex;
			let rows: ufc.ElementShape[] = [];
			let rowTopPosition: number = 0;

			grid._setContentDataRowIndex(editRowIndex, -1);
			grid._keepContentDataRowIndex();

			let shapeKeyIdx: number = 1;
			for (let rowIndex: number = startrowIndex; rowIndex <= endrowIndex; rowIndex++) {
				let gridRow: provider.GridRow = grid.getDataRow(rowIndex);
				if (gridRow) {
					grid._setContentDataRowIndex(rowIndex, -1); // row context 설정

					let rowHeights: number[] = gridContext._getDataRowHeight(rowIndex, this.loc);
					let rowHeight: number = utils.Util.sum(rowHeights);
					let suppressModel: layout.SuppressCellInfo[] = gridContext._getSuppressCellInfo(this.loc, rowIndex);
					let rowShapes: ufc.ElementShape[] = this._gridRow._createShape(gridRow, rowIndex, cellPositionRange, regionColWidth, rowHeight, rowHeights, rowTopPosition, suppressModel, shapeKeyIdx);

					this._addAll(rows, rowShapes);
					this._renderedEndRowIdx = rowIndex;

					rowTopPosition += rowHeight;

					shapeKeyIdx++;
				}
			}
			grid._restoreContentDataRowIndex();

			let ghostRows: ufc.ElementShape[] = this._createExtraRows(endrowIndex + 1, rowTopPosition, regionColWidth, shapeKeyIdx);
			if (ghostRows != null && ghostRows.length != 0) {
				this._addAll(rows, ghostRows);
			}

			return rows;
		}

		private _createRowGroups(cellPositionRange: { start: number, end: number }, regionColWidth: { width: number }[]): ufc.ElementShape[] {
			let gridContext: GridContext = this._getContext();
			let grid: Grid = gridContext.getGrid();
			let virtualRows: provider.VirtualRow[] = grid._getVirtualRows();

			let startrowIndex: number = this._getRenderedStartRowIdx();
			let endrowIndex: number = this._getRenderEndRowIndex();
			let editRowIndex: number = gridContext.editingRowIndex;
			let rows: ufc.ElementShape[] = [];
			let rowTopPosition: number = 0;
			let isMergedSuppress: boolean = (grid.suppressedCellType == "merged");


			grid._setContentDataRowIndex(editRowIndex, -1);
			grid._keepContentDataRowIndex();

			let shapeKeyIdx: number = 1;
			let lastVisibleDsIndex: number = -1;
			for (let rowIndex: number = startrowIndex; rowIndex <= endrowIndex; rowIndex++) {
				let virtualRow: provider.VirtualRow = virtualRows[rowIndex];
				if (virtualRow == null) {
					continue;
				}
				let rowdata: provider.GridRow | provider.GridRowGroup = virtualRow.rowdata;
				if (rowdata == null) {
					continue;
				}

				if (virtualRow.dsindex >= 0) {
					grid._setContentDataRowIndex(virtualRow.dsindex, rowIndex); // row context 설정
					lastVisibleDsIndex = virtualRow.visibledsindex;
				} else {
					grid._setContentDataRowIndex(-1, rowIndex); // row context 설정
				}

				let rowShapes: ufc.ElementShape[] = null;
				let rowHeight: number = -1;
				let suppressModel: layout.SuppressCellInfo[] = gridContext._getSuppressCellInfo(this.loc, rowIndex);
				if (virtualRow.type == provider.VROWTYPE.GRIDROW) {
					let rowHeights: number[] = gridContext._getDataRowHeight(virtualRow.dsindex, this.loc);
					rowHeight = utils.Util.sum(rowHeights);

					rowShapes = this._gridRow._createShape(rowdata as provider.GridRow, rowIndex, cellPositionRange, regionColWidth, rowHeight, rowHeights, rowTopPosition, suppressModel, shapeKeyIdx);
				} else if (virtualRow.type == provider.VROWTYPE.GFOOTER || virtualRow.type == provider.VROWTYPE.GHEADER) {
					rowHeight = utils.Util.sum(virtualRow.rowheights);

					let region: string = null;
					if (virtualRow.type == provider.VROWTYPE.GFOOTER) {
						region = GRIDREGION.GFOOTER;
					} else {
						region = GRIDREGION.GHEADER;
					}
					let gridRowGroup: provider.GridRowGroup = rowdata as provider.GridRowGroup;
					let groupCondition: string = rowgroup.GridRowGroupBuilder._getConditionKeys(gridRowGroup);
					if (this._gridRowGroup != null && this._gridRowGroup[groupCondition] != null && this._gridRowGroup[groupCondition][region] != null) {
						rowShapes = this._gridRowGroup[groupCondition][region]._createShape(gridRowGroup, rowIndex, cellPositionRange, regionColWidth, region, rowHeight, rowTopPosition, suppressModel, isMergedSuppress, shapeKeyIdx);
					}
				}
				if (rowShapes) {
					this._addAll(rows, rowShapes);

					shapeKeyIdx++;

					rowTopPosition += rowHeight;
					this._renderedEndRowIdx = rowIndex; // 그려진 마지막 Row의 Index(VirtualRow Index)
				}
			}
			grid._restoreContentDataRowIndex();

			let ghostRows: ufc.ElementShape[] = this._createExtraRows(lastVisibleDsIndex + 1, rowTopPosition, regionColWidth, shapeKeyIdx);
			if (ghostRows != null && ghostRows.length != 0) {
				this._addAll(rows, ghostRows);
			}

			return rows;
		}

		private _createExtraRows(startRowIndex: number, rowTopPosition: number, regionColWidth: { width: number }[], shapeKeyIdx: number): ufc.ElementShape[] {
			let showExtraRow: ShowExtraRow = this._getContext().showExtraRow;
			if (showExtraRow !== ShowExtraRow.PLAIN && showExtraRow !== ShowExtraRow.STRUCTURED) {
				return null;
			}

			let gridContext: GridContext = this._getContext();
			let contentHeight: number = this._getContentHeight();
			let layoutHeight: number = gridContext._getLocationHeight(this.loc);
			if (contentHeight >= layoutHeight) {
				return null;
			}

			let rows: ufc.ElementShape[] = [];
			let rowIndex: number = startRowIndex;
			let blankHeight: number = layoutHeight - contentHeight;
			let designRowHeights: number[] = gridContext._getDesignDetailRowHeights();
			let rowHeihgt: number = utils.Util.sum(designRowHeights);
			let length: number = Math.ceil(blankHeight / rowHeihgt);
			for (let i = 0; i < length; i++, rowIndex++) {
				let rowClasses: string[] = [GridStyle.ROW, "cl-extra-row"];
				rowClasses.push(rowIndex % 2 == 0 ? ufc.Classes.ODD_ROW : ufc.Classes.EVEN_ROW);
				let rowShape: ufc.ElementShape = {
					tag: "div",
					attr: {},
					classNames: rowClasses,
					style: {
						position: "absolute",
						top: rowTopPosition + "px",
						left: "0",
						width: "100%",
						height: rowHeihgt + "px",
					},
					children: []
				};

				if (showExtraRow === ShowExtraRow.STRUCTURED) {
					rowShape.styler = "row";

					this._layout.cellProp.forEach((colProp: GridDetailCellProp) => {
						let cellLayout: { visible: boolean, colSpan: number } = gridContext._getVisibleColumn(colProp);
						if (cellLayout.visible === false) return;

						let realCellStyles: { style: { [key: string]: string }, bound: { left: number, top: number, width: number, mergeCellWidth: number, height: number } }
							= GridUtil._createCellStyle(regionColWidth, colProp, colProp, designRowHeights, true);

						let classNames: string[] = [GridStyle.CELL, GridContext.CLS_CELL_INHERIT];
						if (colProp.configuration && colProp.configuration.style) {
							let cellConfigClasses: string[] = colProp.configuration.style.getClasses();
							if (cellConfigClasses && cellConfigClasses.length > 0) {
								classNames = classNames.concat(cellConfigClasses);
							}
						}

						let cellShape: ufc.ElementShape = {
							tag: "div",
							attr: {},
							classNames: classNames,
							style: realCellStyles.style,
							children: []
						};
						rowShape.children.push(cellShape);
					});
				} else {
					let leftPosition: number = 0;
					regionColWidth.forEach((colInfo: { width: number }) => {
						if (colInfo.width == 0) {
							return;
						}
						let cellShape: ufc.ElementShape = {
							tag: "div",
							attr: {},
							classNames: [GridStyle.CELL],
							style: {
								overflow: "hidden"
								, position: "absolute"
								, top: "0px"
								, left: leftPosition + "px"
								, width: colInfo.width + "px"
								, height: rowHeihgt + "px"
								, "box-sizing": "border-box"
								, display: "inline-block"
							},
							children: []
						};
						leftPosition += colInfo.width;
						rowShape.children.push(cellShape);
					});
				}

				rowShape.key = "ri" + shapeKeyIdx;
				rows[rows.length] = rowShape;
				rowTopPosition += rowHeihgt;

				shapeKeyIdx++;
			}

			return rows;

		}

		private _getViewingContentHeight(): number {
			let contentHeight: number = -1;
			let context: GridContext = this._getContext();

			if (context._isWholeRenderingMode()) {
				contentHeight = this._getContentHeight();

			} else {
				if (context._isGrouping()) {
					let grid = context.getGrid();
					let virtualRows: provider.VirtualRow[] = grid._getVirtualRows();
					let startrowIndex: number = this._getRenderStartRowIndex();
					let endrowIndex: number = this._getRenderEndRowIndex();
					let editRowIndex: number = context.editingRowIndex;

					grid._setContentDataRowIndex(editRowIndex, -1);
					grid._keepContentDataRowIndex();

					for (let rowIndex: number = startrowIndex; rowIndex <= endrowIndex; rowIndex++) {
						let virtualRow: provider.VirtualRow = virtualRows[rowIndex];
						if (virtualRow == null) {
							continue;
						}

						let rowdata: provider.GridRow | provider.GridRowGroup = virtualRow.rowdata;
						if (rowdata == null) {
							continue;
						}

						if (virtualRow.dsindex >= 0) {
							grid._setContentDataRowIndex(virtualRow.dsindex, rowIndex); // row context 설정
						} else {
							grid._setContentDataRowIndex(-1, rowIndex); // row context 설정
						}

						let rowHeight: number = -1;
						if (virtualRow.type == provider.VROWTYPE.GRIDROW) {
							let rowHeights: number[] = context._getDataRowHeight(virtualRow.dsindex, this.loc);
							rowHeight = utils.Util.sum(rowHeights);
						} else if (virtualRow.type == provider.VROWTYPE.GFOOTER || virtualRow.type == provider.VROWTYPE.GHEADER) {
							rowHeight = utils.Util.sum(virtualRow.rowheights);
						}
						contentHeight += rowHeight;
					}
					grid._restoreContentDataRowIndex();

				} else {
					let startrowIndex: number = this._getRenderedStartRowIdx();
					let endrowIndex: number = this._getRenderedEndRowIdx();
					for (let rowIndex: number = startrowIndex; rowIndex <= endrowIndex; rowIndex++) {
						let rowHeights: number[] = context._getDataRowHeight(rowIndex, this.loc);
						contentHeight += utils.Util.sum(rowHeights);
					}
				}
			}
			if (contentHeight <= 0) {
				contentHeight = 1;
			}

			return contentHeight;
		}

		private _addAll(arr1: any[], arr2: any[]): void {
			for (let idx: number = 0; idx < arr2.length; idx++) {
				arr1[arr1.length] = arr2[idx];
			}
		}


	}
}