

namespace cpr.controls.internal {
	let log = utils.Logger.forTopic("virtualscrollpane")._createBindedLoggerFunction({
		updator: it => log = it
	});

	/**
	 * FIXME: VirtualScrollPane & NativeScrollPane
	 * - NativeScrollPane OverscrollBehaviorType.AUTO 일때도 상위 컨테이너가 VirtualScrollPane 또는 Grid 일 수 있음을 고려하여
	 *   occupied 처리 로직 구현
	 * - UDC < Grid < Group < Group 테스트
	 */

	/**
	 * @private
	 */
	export class VirtualScrollPane extends AbstractScrollPane implements IVirtualScrollPane, resources.IDisposable {
		private _ns: string;
		private _parentNodeName: string;

		private _viewWidth: number;
		private _viewHeight: number;
		private _contentWidth: number;
		private _contentHeight: number;

		private _maxContentTop: number;
		private _maxContentLeft: number;

		private _reqCheckVScroll: boolean = true;
		private _reqCheckHScroll: boolean = true;

		//scrollbar
		private _vscrollbar: VirtualVScrollbar;
		private _hscrollbar: VirtualHScrollbar;

		// touch state
		private _touchRoller: internal.TouchRoller = internal.newTouchRoller();

		// event handler
		private _touchStartHandler = (e: events.CTouchEvent) => this._onContentTouchStart(e);
		private _touchMoveHandler = (e: events.CTouchEvent) => this._onContentTouchMove(e);
		private _touchEndHandler = (e: events.CTouchEvent) => this._onContentTouchEnd(e);

		private _wheelHandler = (e: events.CWheelEvent) => this._onWheel(e);
		private _resizeHandler = (e: events.CWheelEvent) => this._onResize(e); // 상위 요소의 크기가 변경되었을 때 호출됨
		private _contentPaneScrollHandler = (e: events.CUIEvent) => this._onContentPaneScroll(e);
		private _childSizeChangedHandler = (e: events.CUIEvent) => this._onResize(e); // 하위 요소의 크기가 변경되었을 때 호출됨

		private _resizeComputeScrollbarHandler = () => this._computeScrollbar();

		private _disposed: boolean = false;


		constructor(uicontrol: UIControl, ns: string, parentNodeName: string) {
			super(uicontrol);

			this._ns = ns;
			this._parentNodeName = parentNodeName;

			this._vscrollbar = new VirtualVScrollbar(this);
			this._hscrollbar = new VirtualHScrollbar(this);
		}

		public get disposed() {
			return this._disposed;
		}

		public dispose(): void {
			if (this._disposed) {
				return;
			}
			// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/6414
			this.uicontrol?.removeEventListener("-child-size-changed-", this._childSizeChangedHandler);

			super._dispose();

			this._vscrollbar = null;
			this._hscrollbar = null;

			this._touchStartHandler = null;
			this._touchMoveHandler = null;
			this._touchEndHandler = null;
			this._wheelHandler = null;
			this._resizeHandler = null;
			this._contentPaneScrollHandler = null;
			this._childSizeChangedHandler = null;
			this._resizeComputeScrollbarHandler = null;

			this._disposed = true;
		}

		public _setParentNodeName(parentNodeName: string): void {
			this._parentNodeName = parentNodeName;
		}

		public _isEnabled(): boolean {
			if (this.uicontrol instanceof EnableUIControl) {
				return (this.uicontrol as EnableUIControl).enabled;
			}
			return true;
		}
		public _getViewportWidth(): number {
			return this._viewWidth;
		}
		public _getViewportHeight(): number {
			return this._viewHeight;
		}
		public _getContentWidth(): number {
			return this._contentWidth;
		}
		public _getContentHeight(): number {
			return this._contentHeight;
		}
		public _getQName(name: string): string {
			return this._ns + "-" + name;
		}
		public _setScrollTop(e: events.CUIEvent, scrollTop: number): number {
			let containerNode: HTMLElement = this._getContainerNode();
			let currentScrollTop: number = containerNode.scrollTop;
			if (scrollTop < 0) {
				scrollTop = 0;
			} else if (scrollTop > this._getMaxContentTop()) {
				scrollTop = this._getMaxContentTop();
			}
			if (currentScrollTop == scrollTop) {
				return -1;
			}
			containerNode.scrollTop = scrollTop;
			if (containerNode.scrollTop == currentScrollTop) {
				log("containerNode.scrollTop == currentScrollTop");
				return -1;
			}
			return containerNode.scrollTop;
		}
		public _setScrollLeft(e: events.CUIEvent, scrollLeft: number): number {
			let containerNode: HTMLElement = this._getContainerNode();
			let currentScrollLeft: number = containerNode.scrollLeft;
			if (scrollLeft < 0) {
				scrollLeft = 0;
			} else if (scrollLeft > this._getMaxContentLeft()) {
				scrollLeft = this._getMaxContentLeft();
			}
			if (currentScrollLeft == scrollLeft) {
				return -1;
			}
			containerNode.scrollLeft = scrollLeft;
			if (containerNode.scrollLeft == currentScrollLeft) {
				log("containerNode.scrollLeft == currentScrollLeft");
				return -1;
			}
			return containerNode.scrollLeft;
		}
		public _getRenderer(): ufc.ControlRenderer {
			return this.uicontrol._getRenderer();
		}
		/**
		 * 컨텐츠 및 스크롤페인의 크기 변경을 체크하여 변경된 경우 스크롤바를 새로 그림.
		 */
		public _checkResize(): void {
			let container: HTMLElement = this._getContainerNode();
			let containerRect: ClientRect | DOMRect = container.getBoundingClientRect();
			let containerHeight: number = ScrollbarUtil._getIntSize(containerRect.height);
			let containerWidth: number = ScrollbarUtil._getIntSize(containerRect.width);
			let containerScrollHeight: number = container.scrollHeight;
			let containerScrollWidth: number = container.scrollWidth;
			if (this._viewHeight !== containerHeight
				|| this._viewWidth !== containerWidth
				|| this._contentHeight !== containerScrollHeight
				|| this._contentWidth !== containerScrollWidth) {
				this._computeScrollbar();
			}
		}

		public createScrollbar(
			parentShape: ufc.ElementShape,
			sibilings: ufc.ElementShapeContent[],
			scrollingShape: ufc.ElementShape, idx: number): ufc.ElementShape {

			ufc.ShapeUtil.addMandatoryEventHandler(scrollingShape, "touchstart", this._touchStartHandler);
			ufc.ShapeUtil.addMandatoryEventHandler(scrollingShape, "touchmove", this._touchMoveHandler);
			ufc.ShapeUtil.addMandatoryEventHandler(scrollingShape, "touchend", this._touchEndHandler);
			ufc.ShapeUtil.addMandatoryEventHandler(scrollingShape, "wheel", this._wheelHandler);
			ufc.ShapeUtil.addMandatoryEventHandler(scrollingShape, "resize", this._resizeHandler);
			ufc.ShapeUtil.addMandatoryEventHandler(scrollingShape, "scroll", this._contentPaneScrollHandler);
			this.uicontrol.addEventListener("-child-size-changed-", this._childSizeChangedHandler); // eventTable에 등록되고 호출되는 이벤트.

			let autoSizeConstraints: layouts.AutoSizeType = this.uicontrol._getAutoSizingTypeOfConstraint();
			let autoSizeAbility: layouts.AutoSizeType = this.uicontrol._getAutoSizeAvailability();

			let reqCheckVScroll: boolean = true;
			let reqCheckHScroll: boolean = true;

			switch (autoSizeAbility) {
				case layouts.AutoSizeType.none: {
					reqCheckVScroll = true;
					reqCheckHScroll = true;
					break;
				}
				case layouts.AutoSizeType.both: {
					reqCheckVScroll = autoSizeConstraints == layouts.AutoSizeType.none || autoSizeConstraints == layouts.AutoSizeType.width;
					reqCheckHScroll = autoSizeConstraints == layouts.AutoSizeType.none || autoSizeConstraints == layouts.AutoSizeType.height;
					break;
				}
				case layouts.AutoSizeType.height: {
					reqCheckVScroll = autoSizeConstraints == layouts.AutoSizeType.none || autoSizeConstraints == layouts.AutoSizeType.width;
					reqCheckHScroll = true;
					break;
				}
				case layouts.AutoSizeType.width: {
					reqCheckVScroll = true;
					reqCheckHScroll = autoSizeConstraints == layouts.AutoSizeType.none || autoSizeConstraints == layouts.AutoSizeType.height;
					break;
				}
			}
			if (this.uicontrol instanceof controls.Container && (reqCheckVScroll == false || reqCheckHScroll == false)) {
				let layout: controls.layouts.Layout<any> = (this.uicontrol as controls.Container).getLayout();
				let maxContentWidth: number = layout["maxContentWidth"];
				let maxContentHeight: number = layout["maxContentHeight"];
				if (reqCheckVScroll == false && typeof maxContentHeight == "number" && maxContentHeight != -1) {
					reqCheckVScroll = true;
				}
				if (reqCheckHScroll == false && typeof maxContentWidth == "number" && maxContentWidth != -1) {
					reqCheckHScroll = true;
				}
			}

			/**
			 * https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/5861
			 * preferred-size 컨셉을 지원하기 위해, 버티컬 레이아웃의 경우 가로 스크롤을 무시하는 대신
			 * 원본 레이아웃이 만든 쉐이프 모델을 이용해 스크롤바 계산 여부를 결정하도록 변경합니다.
			 */
			let givenOverflowX = scrollingShape.style?.overflowX ?? scrollingShape.style?.["overflow-x"] ?? scrollingShape.style?.overflow;
			let givenOverflowY = scrollingShape.style?.overflowY ?? scrollingShape.style?.["overflow-y"] ?? scrollingShape.style?.overflow;

			if (givenOverflowX == "hidden") {
				reqCheckHScroll = false;
			}
			if (givenOverflowY == "hidden") {
				reqCheckVScroll = false;
			}

			this._reqCheckVScroll = reqCheckVScroll;
			this._reqCheckHScroll = reqCheckHScroll;

			if (this._reqCheckVScroll || this._reqCheckHScroll) {
				scrollingShape.style = _assign({},
					_.omit(scrollingShape.style, ["overflow", "overflowX", "overflowY", "overflow-x", "overflow-y"]),
					{ overflow: "hidden", "overflow-y": "hidden" });

				// 이전에 그려진 적이 있는 경우 이전 가상스크롤바 관련 클래스를 보전하여 컨테이너 안에 포함된 컨트롤의 resize 이벤트 처리를 가능하게 한다
				let customScrollClasses: string[] = ["cl-customscrollbar"];
				let oldShape: ufc.ElementShape = this._getRenderer()._getNamedShape(this._ns);
				if (oldShape != null) {
					let oldClassNames: string[] = oldShape.classNames;
					if (oldClassNames != null && oldClassNames.length > 0) {
						if (oldClassNames.indexOf("cl-with-vscrollbar") !== -1) {
							customScrollClasses[customScrollClasses.length] = "cl-with-vscrollbar";
						}
						if (oldClassNames.indexOf("cl-with-hscrollbar") !== -1) {
							customScrollClasses[customScrollClasses.length] = "cl-with-hscrollbar";
						}
					}
				}

				scrollingShape.classNames = _.union([], scrollingShape.classNames, customScrollClasses);

				// parentshape의 padding-right, padding-bottom을 이전 값으로 보전
				{
					let parentOldShape: ufc.ElementShape = this._getRenderer()._getNamedShape(this._parentNodeName);
					if (parentOldShape != null) {
						let oldPaddingRight: string = parentOldShape.style["padding-right"];
						let oldPaddingBottom: string = parentOldShape.style["padding-bottom"];
						if (oldPaddingRight != null && oldPaddingRight != "") {
							parentShape.style["padding-right"] = oldPaddingRight;
						} else {
							delete parentShape.style["padding-right"];
						}
						if (oldPaddingBottom != null && oldPaddingBottom != "") {
							parentShape.style["padding-bottom"] = oldPaddingBottom;
						} else {
							delete parentShape.style["padding-bottom"];
						}
					}
				}
			}

			// 이전 Shape을 보전해야 thumb의 이동 이벤트 상태를 보전할 수 있음(IE : event.buttons ==> 0으로 설정되는 문제)
			let vScrollShape: ufc.ElementShape = this._getRenderer()._getNamedShape(this._getQName("custom-vscroll"));
			if (!vScrollShape) {
				vScrollShape = { // vertical scrollbar
					tag: "div"
					, nodename: this._getQName("custom-vscroll")
					, style: { display: "none" }
				};
			}
			let hScrollShape: ufc.ElementShape = this._getRenderer()._getNamedShape(this._getQName("custom-hscroll"));
			if (!hScrollShape) {
				hScrollShape = { // horizontal scrollbar
					tag: "div"
					, nodename: this._getQName("custom-hscroll")
					, style: { display: "none" }
				};
			}
			sibilings.splice(idx, 1, scrollingShape,
				_createTapLazyTask({
					task: () => {
						this._computeScrollbar();
					}
				}),
				vScrollShape, // vertical scrollbar
				hScrollShape // horizontal scrollbar
			);

			return scrollingShape;
		}
		private _computeScrollbar(): void {
			if (this.disposed || this._getRenderer() == null || this._getRenderer().hasDrawn() == false) {
				return;
			}
			let reqVScroll: boolean = false;
			let reqHScroll: boolean = false;
			let contentScrollLeft: number = -1;
			let contentScrollTop: number = -1;
			let contentNode: HTMLElement = null;
			if (this._reqCheckVScroll === false && this._reqCheckHScroll === false) {
				reqVScroll = false;
				reqHScroll = false;

				this._viewHeight = -1;
				this._viewWidth = -1;
				this._contentHeight = -1;
				this._contentWidth = -1;
			} else {
				contentNode = this._getContainerNode();

				if (this._reqCheckVScroll === true) {
					let viewHeight: number = contentNode.clientHeight;
					let contentHeight: number = contentNode.scrollHeight;

					this._viewHeight = viewHeight;
					this._contentHeight = contentHeight;
					// IE에서 스크롤이 표시되려면 2px 이상이 차이나야 하는 이슈가 있어, 2px 이상 차이나는 경우에만 스크롤이 필요한 것으로 판단하도록 보정
					reqVScroll = _isIE() ? (this._contentHeight - this._viewHeight) > 2 : (this._contentHeight - this._viewHeight) > 0;
					contentScrollTop = contentNode.scrollTop;
				} else {
					this._viewHeight = -1;
					this._contentHeight = -1;

					reqVScroll = false;
				}
				if (this._reqCheckHScroll === true) {
					let viewWidth: number = contentNode.clientWidth;
					let contentWidth: number = contentNode.scrollWidth;

					this._viewWidth = viewWidth;
					this._contentWidth = contentWidth;
					// IE에서 스크롤이 표시되려면 2px 이상이 차이나야 하는 이슈가 있어, 2px 이상 차이나는 경우에만 스크롤이 필요한 것으로 판단하도록 보정
					reqHScroll = _isIE() ? (this._contentWidth - this._viewWidth) > 2 : (this._contentWidth - this._viewWidth) > 0;
					contentScrollLeft = contentNode.scrollLeft;
				} else {
					this._viewWidth = -1;
					this._contentWidth = -1;

					reqHScroll = false;
				}

				// 추가 보정
				if (reqVScroll != reqHScroll) {
					if (reqVScroll == false && this._reqCheckVScroll == true) {
						reqVScroll = _isIE() ? (this._contentHeight - this._viewHeight) > 1 : (this._contentHeight - this._viewHeight) > 0;
					} else if (reqHScroll == false && this._reqCheckHScroll == true) {
						reqHScroll = _isIE() ? (this._contentWidth - this._viewWidth) > 1 : (this._contentWidth - this._viewWidth) > 0;
					}
				}
			}

			let parentOldShape: ufc.ElementShape = this._getRenderer()._getNamedShape(this._parentNodeName);
			let scrollClassNames: string[] = [];
			let parentNodeStyle: { [key: string]: string } = _mergeObject(parentOldShape.style);
			let parentNodeClasses: string[] = _.union([], parentOldShape.classNames);
			if (this._reqCheckVScroll || this._reqCheckHScroll) {
				let scrollbarInfo: ScrollbarInfo = ScrollbarUtil._getCustomScrollbarInfo();
				if (reqVScroll || reqHScroll) {
					let parentNode: HTMLElement = this._getRenderer().getNamedNode(this._parentNodeName);
					let rect: DOMRect = parentNode.getBoundingClientRect();
					let parentWidth: number = rect.width;
					let parentHeight: number = rect.height;

					if (reqVScroll && parentWidth > scrollbarInfo.vWidth + 2) { /* padding + border(2) */
						scrollClassNames[scrollClassNames.length] = "cl-with-vscrollbar";
						parentNodeStyle["padding-right"] = scrollbarInfo.vWidth + "px";
					} else {
						delete parentNodeStyle["padding-right"];
						reqVScroll = false;
					}
					if (reqHScroll && parentHeight > scrollbarInfo.hHeight + 2) { /* padding + border(2) */
						scrollClassNames[scrollClassNames.length] = "cl-with-hscrollbar";
						parentNodeStyle["padding-bottom"] = scrollbarInfo.hHeight + "px";
					} else {
						delete parentNodeStyle["padding-bottom"];
						reqHScroll = false;
					}
				} else {
					delete parentNodeStyle["padding-right"];
					delete parentNodeStyle["padding-bottom"];
				}
			}

			let oldClassNames: string[] = this._updateClass(this._ns, ["cl-with-vscrollbar", "cl-with-hscrollbar"], scrollClassNames);
			this._getRenderer().updateCSS(this._parentNodeName, parentNodeClasses, parentNodeStyle, false);

			// 스타일 변경 후 높이/넓이를 새로 가져옴
			if (reqVScroll || reqHScroll) {
				this._viewWidth = contentNode.clientWidth;
				this._viewHeight = contentNode.clientHeight;
			}

			this._maxContentLeft = this._contentWidth - this._viewWidth;
			if (this._maxContentLeft < 0) {
				this._maxContentLeft = 0;
			}
			this._maxContentTop = this._contentHeight - this._viewHeight;
			if (this._maxContentTop < 0) {
				this._maxContentTop = 0;
			}

			let vscrollbarShape: ufc.ElementShape = null;
			if (reqVScroll) {
				vscrollbarShape = this._vscrollbar._createScrollbar(contentScrollTop, this._contentHeight);
				if (reqHScroll) {
					vscrollbarShape.classNames = _.union([], vscrollbarShape.classNames, ["cl-with-hscrollbar"]);
				}
			} else {
				vscrollbarShape = {
					tag: "div"
					, nodename: this._getQName("custom-vscroll")
					, style: { display: "none" }
				};
			}
			this._replace("custom-vscroll", vscrollbarShape);

			let hscrollbarShape: ufc.ElementShape = null;
			if (reqHScroll) {
				hscrollbarShape = this._hscrollbar._createScrollbar(contentScrollLeft, this._contentWidth);
				if (reqVScroll) {
					hscrollbarShape.classNames = _.union([], hscrollbarShape.classNames, ["cl-with-vscrollbar"]);
				}
			} else {
				hscrollbarShape = {
					tag: "div"
					, nodename: this._getQName("custom-hscroll")
					, style: { display: "none" }
				};
			}
			this._replace("custom-hscroll", hscrollbarShape);

			let classChanged: boolean = ["cl-with-hscrollbar", "cl-with-vscrollbar"].some((item: string) => {
				let oldIdx: number = oldClassNames.indexOf(item);
				let newIdx: number = scrollClassNames.indexOf(item);
				if (!((oldIdx === -1 && newIdx === -1) || (oldIdx >= 0 && newIdx >= 0))) {
					return true;
				}

				return false;
			});
			if (classChanged) {
				// 스크롤바 생성에 의한 돔 크기 변경 전파
				this.uicontrol._fireResizeEvent();
			}
		}

		// event handlers
		private _onWheel(e: events.CWheelEvent): void { // wheel은 가로/세로 같이 사용
			if (e.ctrlKey === true) { // 확대/축소
				return;
			}

			if (e.defaultPrevented === true || e._isOccupied() === true) {
				return;
			}

			this._checkResize();
			let delta: { x: number, y: number } = ScrollbarUtil._getScrollPaneWheelDelta(e);
			if (delta == null) {
				return;
			}
			// 델타를 그대로 사용하되, 뷰포트를 넘지 않도록 상한을 둔다.
			let moved: boolean = false;
			if (e.shiftKey) {
				if (this._hscrollbar) {
					moved = this._setHScrollbarLeftOffset(e, ScrollbarUtil._toWheelOffset(delta.x, this._getViewportWidth()));
				}
			} else {
				if (this._hscrollbar && delta.x != 0) {
					moved = this._setHScrollbarLeftOffset(e, ScrollbarUtil._toWheelOffset(delta.x, this._getViewportWidth()));
				}
				if (this._vscrollbar && delta.y != 0) {
					moved = this._setVScrollbarTopOffset(e, ScrollbarUtil._toWheelOffset(delta.y, this._getViewportHeight())) || moved;
				}
			}
			if (moved) {
				e.preventDefault();
			} else {
				let overscrollBehavior: OverscrollBehaviorType = this._getOverscrollBehaviorType();
				switch (overscrollBehavior) {
					case OverscrollBehaviorType.NONE: {
						e.preventDefault();
						e._setOccupied(true);
						break;
					}
				}
			}
		}

		private _onContentTouchStart(e: events.CTouchEvent): void {
			this._checkResize();

			this._touchRoller._touchStart(e,
				this._maxContentTop > 0 ? this._vscrollbar._getScrollTop() : -1,
				this._maxContentLeft > 0 ? this._hscrollbar._getScrollLeft() : -1
			);
		}
		private _onContentTouchMove(e: events.CTouchEvent): void {
			if (e.defaultPrevented === true || e._isOccupied() === true) {
				return;
			}

			let moved: boolean = false;

			this._touchRoller._touchMove(e, (scrollTop: number, scrollLeft: number): boolean => {
				let movedY: boolean = scrollTop !== -1 ? this._setVScrollbarTop(e, scrollTop) : false;
				let movedX: boolean = scrollLeft !== -1 ? this._setHScrollbarLeft(e, scrollLeft) : false;

				moved = movedX || movedY;

				return moved;
			});

			if (moved === false) {
				// TODO overscrollBehavior 속성 설정을 NativeScrollPane 처럼 수정
				let overscrollBehavior: OverscrollBehaviorType = this._getOverscrollBehaviorType();
				switch (overscrollBehavior) {
					case OverscrollBehaviorType.NONE: {
						e.preventDefault();
						e._setOccupied(true);
						break;
					}
				}
			} else {
				e._setOccupied(true);
			}
		}
		private _onContentTouchEnd(e: events.CTouchEvent): void {
			this._touchRoller._touchEnd(e,
				this._maxContentTop > 0 ? this._vscrollbar._getScrollTop() : -1,
				this._maxContentLeft > 0 ? this._hscrollbar._getScrollLeft() : -1,
				(scrollTop: number, scrollLeft: number): boolean => {
					let movedY: boolean = scrollTop !== -1 ? this._setVScrollbarTop(e, scrollTop) : false;
					let movedX: boolean = scrollLeft !== -1 ? this._setHScrollbarLeft(e, scrollLeft) : false;

					return movedX || movedY;
				}
			);
		}

		private _onResize(e: events.CUIEvent): void {
			if (this.disposed) {
				return;
			}
			core.DeferredUpdateManager.INSTANCE._asyncExecLast(this._resizeComputeScrollbarHandler);
		}

		private _onContentPaneScroll(e: events.CUIEvent): void {
			let target: HTMLElement = <HTMLElement>e.target;
			if (this._vscrollbar) {
				let scrollTop: number = target.scrollTop;
				this._vscrollbar._setScrollTop(scrollTop);
			}
			if (this._hscrollbar) {
				let scrollLeft: number = target.scrollLeft;
				this._hscrollbar._setScrollLeft(scrollLeft);
			}
		}

		// helper methods
		private _setVScrollbarTopOffset(e: events.CUIEvent, offset: number): boolean {
			let containerNode: HTMLElement = this._getContainerNode();
			let scrollTop: number = containerNode.scrollTop;
			scrollTop += offset;

			return this._setVScrollbarTop(e, scrollTop);
		}
		private _setVScrollbarTop(e: events.CUIEvent, scrollTop: number): boolean {
			let movedScrollTop: number = this._setScrollTop(e, scrollTop);
			if (movedScrollTop == -1) {
				return false;
			}
			this._vscrollbar._setScrollTop(movedScrollTop);
			return true;
		}

		private _setHScrollbarLeftOffset(e: events.CUIEvent, offset: number): boolean {
			let containerNode: HTMLElement = this._getContainerNode();
			let scrollLeft: number = containerNode.scrollLeft;
			scrollLeft += offset;
			return this._setHScrollbarLeft(e, scrollLeft);
		}
		private _setHScrollbarLeft(e: events.CUIEvent, scrollLeft: number): boolean {
			let movedScrollLeft: number = this._setScrollLeft(e, scrollLeft);
			if (movedScrollLeft == -1) {
				return false;
			}
			this._hscrollbar._setScrollLeft(movedScrollLeft);
			return true;
		}

		private _getContainerNode(): HTMLElement {
			return this._getRenderer().getNamedNode(this._ns);
		}
		private _getMaxContentTop(): number {
			return this._maxContentTop;
		}
		private _getMaxContentLeft(): number {
			return this._maxContentLeft;
		}
		private _replace(name: string, newShape: ufc.ElementShape): void {
			this._getRenderer().replace(this._getQName(name), newShape);
		}
		private _updateClass(name: string, removal: string[], additional: string[]): string[] {
			return this._getRenderer().updateClass(name, removal, additional);
		}

	}
}