/// <reference path="../../utils/Util.ts"/>
namespace cpr.controls.layouts {
	let browserInfo = _detectBrowser();
	let useOldGridSpec =
		(browserInfo.name == "ie" && 10 <= browserInfo.versionNumber && browserInfo.versionNumber <= 11)
		|| browserInfo.name == "edge";

	/**
	 * @private
	 */
	export abstract class GridCSSBuilder {
		public static _forLayout(transposed: boolean = false) {
			let builder = new GridLayoutCSSBuilder();
			return transposed
				? builder.transpose()
				: builder;
		}

		public static _forCell(transposed: boolean = false) {
			let builder = new GridCellCSSBuilder();
			return transposed
				? builder.transpose()
				: builder;
		}

		public static _wrapAsContentPane(paneStyle: { [key: string]: string }, wrapperStyle: { [key: string]: string }) {
			if (useOldGridSpec) {
				GridCSSBuilder._forLayout()
					._withTemplateColumns("minmax(min-content, 1fr)")
					._withTemplateRows("minmax(min-content, 1fr)")
					._commit(wrapperStyle);
			} else {
				paneStyle["width"] = "100%";
				paneStyle["height"] = "100%";
				paneStyle["min-width"] = "min-content";
				paneStyle["min-height"] = "min-content";
			}
		}

		public static _wrapAsContentPaneWithShapes(paneShape: ufc.ElementShape, scrollingShape: ufc.ElementShape) {
			paneShape.style = paneShape.style || {};
			scrollingShape.style = scrollingShape.style || {};
			GridCSSBuilder._wrapAsContentPane(paneShape.style, scrollingShape.style);
		}

		protected _transposed: boolean = false;

		public transpose(): this {
			this._transposed = !this._transposed;
			return this;
		}

		public abstract _commit(output: { [key: string]: string }): void;

		public _commitToShape(shape: ufc.ElementShape) {
			shape.style = shape.style || {};
			this._commit(shape.style)
		};

		public _commitToRenderer(renderer: ufc.ControlRenderer, decoratorName: string = "layout") {
			renderer.addDecorator(decoratorName, shape => {
				this._commitToShape(shape);
				return shape;
			});
		}
	}

	/**
	 * @private
	 */
	export class GridLayoutCSSBuilder extends GridCSSBuilder {
		private _columns: string = "1fr";
		private _rows: string = "1fr";
		private _useInline = false;
		private _verticalAlign: GridLayoutAlign = GridLayoutAlign.stretch;
		public _withInlineGrid(useInline = true) {
			this._useInline = useInline;
			return this;
		}

		public _withRepeatedTemplateColumns(template: string, howMany: number, before: string[] = null, after: string[] = null, separator: string = null) {
			let templates: string[] = [];
			if (before) {
				before.forEach(it => templates.push(it));
			}
			for (let idx = 0; idx < howMany; idx++) {
				if (separator && idx > 0) {
					templates[templates.length] = separator;
				}
				templates[templates.length] = template;
			}
			if (after) {
				after.forEach(it => templates.push(it));
			}
			return this._withTemplateColumns(templates);
		}

		public _withTemplateColumns(templateColumns: string | string[]) {
			let value: string;
			if (typeof templateColumns == "string") {
				value = templateColumns;
			} else {
				value = templateColumns.join(" ")
			}
			this._columns = value;
			return this;
		}

		public _withRepeatedTemplateRows(template: string, howMany: number) {
			let templates: string[] = [];
			for (let idx = 0; idx < howMany; idx++) {
				templates[templates.length] = template;
			}
			return this._withTemplateRows(templates);
		}

		public _withTemplateRows(templateRows: string | string[]) {
			let value: string;
			if (typeof templateRows == "string") {
				value = templateRows;
			} else {
				value = templateRows.join(" ")
			}
			this._rows = value;
			return this;
		}

		public _withVerticalAlign(verticalAlign: GridLayoutAlign) {
			this._verticalAlign = verticalAlign
			return this;
		}

		public _commit(output: { [key: string]: string }) {
			let [columns, rows] = !this._transposed
				? [this._columns, this._rows]
				: [this._rows, this._columns];

			if (useOldGridSpec) {
				if (this._useInline) {
					output["display"] = "-ms-inline-grid";
				} else {
					output["display"] = "-ms-grid";
				}
				output["-ms-grid-columns"] = columns;
				output["-ms-grid-rows"] = rows;
			}
			else {
				if (this._useInline) {
					output["display"] = "inline-grid";
				} else {
					output["display"] = "grid";
				}

				if (this._verticalAlign != GridLayoutAlign.stretch) {
					output["align-content"] = this._verticalAlign;
				}
				output["grid-template-columns"] = columns;
				output["grid-template-rows"] = rows;
			}
		}

		public _commitAsContentPane(paneStyle: { [key: string]: string }, wrapperStyle: { [key: string]: string }) {
			this._commit(paneStyle);
			GridCSSBuilder._wrapAsContentPane(paneStyle, wrapperStyle);

		}

		public _commitAsContentPaneToShape(paneShape: ufc.ElementShape, scrollingShape: ufc.ElementShape) {
			this._commitToShape(paneShape);
			GridCSSBuilder._wrapAsContentPaneWithShapes(paneShape, scrollingShape);
		}
	}
	export enum GridCellAlign {
		stretch = "stretch",
		start = "start",
		end = "end",
		center = "center",
		baseline = "baseline"
	}

	export enum GridLayoutAlign {
		stretch = "stretch",
		start = "start",
		end = "end",
		center = "center",
		baseline = "baseline"
	}
	/**
	 * @private
	 */
	export class GridCellCSSBuilder extends GridCSSBuilder {
		private _columnStart: number = 1;
		private _columnSpan: number = 1;
		private _rowStart: number = 1;
		private _rowSpan: number = 1;
		private _horizontalAlign: GridCellAlign = GridCellAlign.stretch;
		private _verticalAlign: GridCellAlign = GridCellAlign.stretch;
		private _needsExplicitStretch = false;

		public _withCellConstraint(columnStart: number, rowStart: number, colSpan: number = 1, rowSpan: number = 1) {
			this._columnStart = columnStart;
			this._columnSpan = colSpan;
			this._rowStart = rowStart;
			this._rowSpan = rowSpan;
			return this;
		}

		public _withHorizoltalAlign(horizontalAlign: GridCellAlign) {
			this._horizontalAlign = horizontalAlign;
			return this;
		}

		public _withVerticalAlign(verticalAlign: GridCellAlign) {
			this._verticalAlign = verticalAlign
			return this;
		}

		public _withColumnStart(columnStart: number) {
			this._columnStart = columnStart;
			return this;
		}

		public _withColumnSpan(columnSpan: number) {
			this._columnSpan = columnSpan;
			return this;
		}

		public _withColumnConstraint(columnStart: number, columnSpan: number = 1) {
			this._columnStart = columnStart;
			this._columnSpan = columnSpan;
			return this;
		}

		public _withRowStart(rowStart: number) {
			this._rowStart = rowStart;
			return this;
		}

		public _withRowSpan(rowSpan: number) {
			this._rowSpan = rowSpan;
			return this
		}

		public _widthRowCosntraint(rowStart: number, rowSpan: number = 1) {
			this._rowStart = rowStart;
			this._rowSpan = rowSpan;
			return this;
		}

		public _translate(columnDelta: number, rowDelta: number): GridCellCSSBuilder {
			this._rowStart += rowDelta;
			this._columnStart += columnDelta;
			return this;
		}

		public _expand(colSpanDelta: number, rowSpanDelta: number): GridCellCSSBuilder {
			this._rowSpan += rowSpanDelta;
			this._columnSpan += colSpanDelta;
			return this;
		}

		/**
		 * 일반적인 경우, 셀의 얼라인 타입이 strech 인 경우 생략해도 되지만, 이미지등의 노드의 경우 명시적 지정이 필요한 경우가 있음.
		 * @param needsExplicitStretch 셀의 얼라인 타입이 strech인 경우에도 명시적으로 지정할 것인지 여부.
		 */
		public _withExplicitStrech(needsExplicitStretch: boolean): GridCellCSSBuilder {
			this._needsExplicitStretch = needsExplicitStretch;
			return this;
		}

		public _commit(output: { [key: string]: string }) {
			let [columnStart, columnSpan, rowStart, rowSpan, horizontalAlign, verticalAlign] = !this._transposed
				? [this._columnStart, this._columnSpan, this._rowStart, this._rowSpan, this._horizontalAlign, this._verticalAlign]
				: [this._rowStart, this._rowSpan, this._columnStart, this._columnSpan, this._verticalAlign, this._horizontalAlign]
				;

			if (useOldGridSpec) {
				output["-ms-grid-column"] = `${columnStart}`;
				output["-ms-grid-column-span"] = `${columnSpan}`;
				output["-ms-grid-row"] = `${rowStart}`;
				output["-ms-grid-row-span"] = `${rowSpan}`;

				if (this._needsExplicitStretch || horizontalAlign != GridCellAlign.stretch) {
					output["-ms-grid-column-align"] = horizontalAlign;
				}
				if (this._needsExplicitStretch || verticalAlign != GridCellAlign.stretch) {
					output["-ms-grid-row-align"] = verticalAlign;
				}
			}
			else {
				output["grid-column"] = `${columnStart} / span ${columnSpan}`
				output["grid-row"] = `${rowStart} / span ${rowSpan}`

				if (this._needsExplicitStretch || horizontalAlign != GridCellAlign.stretch) {
					output["justify-self"] = horizontalAlign;
				}
				if (this._needsExplicitStretch || verticalAlign != GridCellAlign.stretch) {
					output["align-self"] = verticalAlign;
				}
			}
		}
	}

}
