/// <reference path="./UIControl.ts"/>
namespace cpr.controls {
	/**
	 * UDCBase
	 * UDC Control을 상속 받는 컨트롤.
	 * @noinstance
	 */
	export class UDCBase extends EmbeddedApp implements gridpart.IGridParticipant {
		private _typeName: string

		/**
		 * @param typeName UDC 컨트롤의 타입 명.
		 * @param app UDC 컨트롤을 구성하는 앱.
		 * @param id 컨트롤의 ID.
		 * @private
		 */
		constructor(typeName: string, app: core.App, id?: string) {
			super(id, app);

			this._typeName = typeName;
			// UDC의 앱속성 초기화를 위해 _initControl은 AppInstance가 생성된 후에 호출되어야 하므로 _embeddedAppWillInit에서 호출.
			this._ensureAppRunning(); // 앱을 생성하고 init 이벤트 발생.
		}

		public override _embeddedAppWillInit(embeddedAppInstance: core.AppInstance): void {
			super._embeddedAppWillInit(embeddedAppInstance);

			// 모듈 함수를 확장.
			let module = embeddedAppInstance.getModule();
			if (module) {
				_assign(this, module);
			}
			this._initControl();
		}

		get type(): ControlType {
			return this._typeName as any as ControlType;
		}

		override _getType(): ControlType {
			return ControlType.UDC;
		}

		/**
		 * 해당 속성을 bind합니다.
		 * @param name bind할 속성 명.
		 */
		bind(name: string): cpr.bind.IBindFactory {
			let localAppInstance = this.getEmbeddedAppInstance();
			if (localAppInstance.isBindableAppProperty(name)) {
				return localAppInstance.bindAppProperty(name);
			} else {
				return super.bind(name);
			}
		}

		/**
		 * 해당 속성을 unbind합니다.
		 * @param name unbind할 속성 명.
		 */
		unbind(name: string): void {
			let localAppInstance = this.getEmbeddedAppInstance();
			if (localAppInstance.isBindableAppProperty(name)) {
				localAppInstance.unbindAppProperty(name);
			} else {
				super.unbind(name);
			}
		}

		/**
		 * 컨트롤의 바인드 속성 정보를 반환합니다.
		 * @param name bind된 속성 명.
		 * @return BindInfo 속성
		 */
		getBindInfo(name: string): bind.BindInfo {
			let localAppInstance = this.getEmbeddedAppInstance();
			if (localAppInstance.isBindableAppProperty(name)) {
				return localAppInstance.getAppPropertyBindInfo(name);
			} else {
				return super.getBindInfo(name);
			}
		}

		/**
		 * 해당 속성의 bind 여부를 반환합니다.
		 * @param name 속성 명
		 */
		isBindable(name: string): boolean {
			return this.getEmbeddedAppInstance().isBindableAppProperty(name);
		}

		public _convertGridPasteText(text: string): string {
			return text;
		}

		public _getGridViewingText(): string {
			let displayText: string = "";
			if (this["getText"]) {
				displayText = this["getText"]();
			} else if (this["value"]) {
				displayText = this["value"];
			}
			return displayText;
		}

		public _renderGridCellShape(grid: Grid, data: (string | ufc.StyledString), option: gridpart.renderer.IRenderOption): ufc.ControlShape {
			let udcShape: ufc.ControlShape = {
				tag: "div",
				classNames: ["cl-control", gridpart.GridStyle.DEFAULTCELL], //그리드 내 UDC에 cl-default-cell 클래스 추가 (기존과 호환성 작업) (release-test-project#3788)
				style: {},
				children: []
			};
			if (this.getEmbeddedAppInstance().getContainer().getLayout().scrollable !== false) {
				udcShape.style["overflow"] = "auto"
			}

			if (option.maxHeight >= 0) {
				udcShape.style["height"] = option.maxHeight + "px";
			}

			let text: string = null;

			if (option.hidetext == false) {
				text = this._getGridViewingText();
				if (text == null) {
					text = (data == null) ? "" : ufc.StyledString._asString(data);
				}
			}
			if (text == null) {
				text = "";
			}

			let shape: ufc.ElementShape = {
				tag: "div",
				classNames: [],
				style: {
					display: "table",
					width: "100%",
					"vertical-align": "inherit",
					"text-align": "inherit"
				},
				children: [gridpart.renderer.CellRendererFactory._getTextShape(text, option.maxHeight)]
			};
			if (option.maxHeight >= 0) {
				shape.style["height"] = "100%";
				shape.style["max-height"] = option.maxHeight + "px";
			}
			udcShape.children.push(shape);

			return udcShape;
		}

		public _exportValue(): string | number {
			return null;
		}
	}
}