
/**
 * Grid내 UIControl의 viewing mode shape을 생성하는 flyweight function factory.
 */
namespace cpr.controls.gridpart.renderer {
	/**
	 * @private
	 * 
	 * #9795이슈에 의해 CellRendererFactory 코드들이 IGridParticipant에 맞춰 각 컨트롤로 이관됨.(20240807)
	 */
	export class CellRendererFactory {
		private static _instance = new CellRendererFactory();

		public static readonly HTML_CONTENT: string = "html-content";

		public static _getDisplayText(grid: Grid, uiControl: GridUIControl): string {
			return uiControl._getGridViewingText();
		}

		public static _getRenderer(uiControl: GridUIControl): (grid: Grid, uiControl: GridUIControl, data: (string | ufc.StyledString), option: IRenderOption) => ufc.ControlShape {
			let flyweight: (grid: Grid, uiControl: GridUIControl, data: (string | ufc.StyledString), option: IRenderOption) => ufc.ControlShape = null;
			if (uiControl == null) {
				flyweight = CellRendererFactory._instance._renderDefault;
			}
			return flyweight;
		}

		private _renderDefault(grid: Grid, uiControl: GridUIControl, data: (string | ufc.StyledString), option: IRenderOption): ufc.ControlShape {

			let text: (string | ufc.StyledString) = null;
			if (option.hidetext == false) {
				// text = option.text;
				// if (text == null) {
				if (uiControl) {
					if (uiControl["getText"]) {
						text = uiControl["getText"]();
					} else if (uiControl["text"]) {
						text = uiControl["text"];
					} else if (uiControl["value"]) {
						text = uiControl["value"];
					}
				}
				if (text == null) {
					text = (data == null) ? "" : data;
				}
				// }
			}
			if (text == null) {
				text = "";
			}

			let shape: ufc.ElementShape = CellRendererFactory._getRawTextCellShape(text, option);

			return shape;
		}


		public static _getRawTextCellShape(rawText: (string | ufc.StyledString), option: IRenderOption): ufc.ElementShape {
			let shape: ufc.ElementShape = {
				tag: "div",
				classNames: [GridStyle.CONTROL, GridStyle.DEFAULTCELL],
				style: {
					width: "100%",
					display: "table",
					"table-layout": "fixed"
				},
				children: [CellRendererFactory._getTextShape(rawText, option.maxHeight)]
			};
			if (option.maxHeight >= 0) {
				shape.style["height"] = "100%";
				shape.style["max-height"] = option.maxHeight + "px";
			}

			return shape;
		}

		/**
		 * display:table-cell인 div에 그려진 text shape을 반환합니다.
		 * @param text 그려질 text
		 * @param cellHeight cell 높이 (option.maxHeight)
		 * @param textStyle class와 css style
		 * @returns 
		 */
		public static _getTextShape(text: (string | ufc.StyledString), cellHeight: number, textStyle?: { classNames?: string[], style?: { [key: string]: string } }): ufc.ElementShape {
			let classNames: string[] = [];
			let style: { [key: string]: string } = {};
			if (textStyle != null) {
				classNames = (textStyle.classNames) ? textStyle.classNames : classNames;
				style = (textStyle.style) ? textStyle.style : style;
			}

			let shape: ufc.ElementShape = {
				tag: "div",
				classNames: [ufc.Classes.TEXT].concat(classNames),
				style: _mergeObject({
					width: "100%",
					display: "table-cell"
				}, style),
				children: ufc.StyledString._asShape(text)
			};
			if (cellHeight >= 0) {
				shape.style["height"] = "100%";
				shape.style["max-height"] = cellHeight + "px";
			}

			return shape;
		}

		/**
		 * display:grid인 div에 그려진 text shape을 반환합니다.
		 * @param text 그려질 text
		 * @param cellHeight cell 높이 (option.maxHeight)
		 * @param textStyle class와 css style
		 * @returns 
		 */
		public static _getGridCellTextShape(text: (string | ufc.StyledString), cellHeight: number, textStyle?: { classNames?: string[], style?: { [key: string]: string } }): ufc.ElementShape {
			let classNames: string[] = [];
			let style: { [key: string]: string } = {};
			if (textStyle != null) {
				classNames = (textStyle.classNames) ? textStyle.classNames : classNames;
				style = (textStyle.style) ? textStyle.style : style;
			}

			let textShape: cpr.ufc.ControlShape = {
				tag: "div",
				attr: {},
				style: {
					overflow: "hidden",
					textOverflow: "inherit"
				},
				events: {},
				children: ufc.StyledString._asShape(text)
			}

			layouts.GridCSSBuilder._forCell()._withVerticalAlign(layouts.GridCellAlign.center)._withColumnStart(1)._withRowStart(1)._commit(textShape.style);

			let wrap: ufc.ElementShape = {
				tag: "div",
				classNames: [ufc.Classes.TEXT].concat(classNames),
				style: _mergeObject({
					width: "100%",
					height: "100%",
					overflow: "hidden"
				}, style),
				attr: {},
				nodename: "text",
				children: [textShape]
			};
			if (cellHeight >= 0) {
				wrap.style["max-height"] = cellHeight + "px";
			}
			layouts.GridCSSBuilder._forLayout()._withTemplateColumns("1fr")._withTemplateRows("1fr")._commit(wrap.style);
			return wrap;
		}
	}
}