/// <reference path="./IDataRow.ts"/>
namespace cpr.data {
	/**
	 * Row.
	 * 데이터 로우.
	 */
	export class Row extends IDataRow implements expression.EvaluationContext {
		private _index: number;


		constructor(dataSet: DataCollection, index: number) {
			super(dataSet);

			this._index = index;
		}

		_getRowData(): tabledata.RowData {
			return this._getDataSet()._getRowData(this._index);
		}

		/**
		 * 현재 Row의 index를 반환합니다.
		 * @return 현재 row index
		 */
		public getIndex(): number {
			return this._index;
		}

		/**
		 * 입력 받은 컬럼명에 해당하는 값을 반환합니다.
		 * @param columnName	값을 가져올 column의 columnName
		 * @return 해당 데이터
		 */
		public getValue(columnName: string): any {
			return this._getDataSet().getValue(this.getIndex(), columnName);
		}

		/**
		 * 입력 받은 columnName에 해당되는 데이터를 수정합니다.
		 * @param columnName	수정할 column의 columnName
		 * @return 값 수정 성공 여부
		 */
		public setValue(columnName: string, value: any): boolean {
			return this._getDataSet().setValue(this.getIndex(), columnName, value);
		}

		/**
		 * 현재 row의 상태값을 변경합니다.
		 * @param rowIndex	변경할 row Index
		 * @param state		변경할 상태값<br>
		 * state 종류:<br>
		 * cpr.data.tabledata.RowState.UNCHANGED : 변경되지 않은 상태.<br>
		 * cpr.data.tabledata.RowState.INSERTED : 행이 신규로 추가된 상태.<br>
		 * cpr.data.tabledata.RowState.UPDATED : 행이 수정된 상태.<br>
		 * cpr.data.tabledata.RowState.DELETED : 행이 삭제된 상태.<br>
		 * cpr.data.tabledata.RowState.INSERTDELETED : 행이 추가되었다가 삭제된 상태.
		 */
		public setState(state: tabledata.RowState): void {
			this._getDataSet()._setRowState(this.getIndex(), state);
		}

		/**
		 * 현재 row의 row data를 { columnName : value } 형식으로 반환합니다.
		 * @return 현재 row의 row data (key: columnName, value: 해당 value형태의 json object).<br>
		 * 	{[columnName: string]: string | number}
		 */
		public getRowData(columntype: header.HeaderType = header.HeaderType.ALL): RowConfigInfo {
			return this._getDataSet().getRowData(this.getIndex(), columntype);
		}

		/**
		 * { columnName : value } 형식의 데이터를 받아 현재 row의 데이터를 전체 변경합니다.
		 * @param rowData		수정할 row data { columnName : value, ... } 형식.<br>
		 * 	{[columnName: string]: string | number}
		 */
		public setRowData(rowData: RowConfigInfo): boolean {
			return this._getDataSet().updateRow(this.getIndex(), rowData);
		}


		/**
		 * @private
		 */
		_getExpressionOnlyProperty(prop: string) {
			// TODO _getExpressionOnlyProperty 와 같이 반복적으로 호출되는 함수의 경우
			// 반복되는 체크로직을 제거하고 다형성을 이용하여 한번에 처리될 수 있도록 개선 필요.

			// 1. prop의 컬럼이 존재할 경우
			let header: header.Header = this._getHeader(prop);
			if (!header) {
				return undefined;
			}
			let columnDataType: tabledata.DataType = header.getDataType();

			// 정렬/필터시 Decimal 비교와 일반 String(getValue사용시 String 반환) 비교에 차이가 없어서 제거함. (180201 hyeran)
			// if (columnDataType == tabledata.DataType.DECIMAL) {
			// 	// 1.1 Decimal 컬럼인 경우 => decimal 객체 반환
			// 	return this._rowdata._getDecimal(columnIndex);
			// } else 
			if (columnDataType == tabledata.DataType.EXPRESSION) {
				// 1.2 Expression 컬럼인 경우 => 해당 컬럼 값 반환
				if (header._isExpressionHeader()) { // expression header일 경우
					let exprHeader: header.ExpressionHeader = header as header.ExpressionHeader;
					let func: Function = exprHeader.getFunction();
					if (func != null) {
						return func(this);
					}
				}

			} else {
				// 1.3 일반 컬럼인 경우 => 해당 컬럼 값 반환
				let value: any = this.getValue(prop);
				if (columnDataType == tabledata.DataType.NUMBER && value != "" && typeof (value) != "number") {
					value = utils.Util.toNumber(value);
				}
				return value;
			}

		}

	}
}