namespace cpr.controls.internal {
	interface ScrollState {
		scrollTop: number, scrollLeft: number, maxScrollTop: number, maxScrollLeft: number
	}


	/**
	 * NativeScrollbar를 사용할 때 컨테이너가 포함하는 ChildControl의 크기가 변경되어 발생하는 -child-size-changed- 이벤트를 처리하기 위한 가상의 ScrollPane.
	 * @private
	 */
	export class NativeScrollPane extends AbstractScrollPane implements resources.IDisposable {
		private _disposed: boolean = false;

		// event handler
		private _resizeComputeScrollbarHandler = () => this._computeScrollbar();

		// TODO Touch 및 Wheel 정상동작 확인 필요
		private _touchStartHandler = (e: events.CTouchEvent) => this._onContentTouchStart(e);
		private _touchMoveHandler = (e: events.CTouchEvent) => this._onContentTouchMove(e);
		private _touchEndHandler = (e: events.CTouchEvent) => this._onContentTouchEnd(e);
		private _wheelHandler = (e: events.CWheelEvent) => this._onWheel(e);

		private _overscrollBehaviorType: OverscrollBehaviorType;
		private _scrollingNodeName: string;
		private _supportPointerEvents: boolean = false;

		private _vScrollbarAppearance: boolean = null;


		constructor(uicontrol: UIControl, scrollingNodeName: string) {
			super(uicontrol);
			this._scrollingNodeName = scrollingNodeName;
		}

		public get disposed() {
			return this._disposed;
		}

		public dispose(): void {
			if (this._disposed) {
				return;
			}
			// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/6414
			this.uicontrol?.removeEventListener("-child-size-changed-", this._resizeComputeScrollbarHandler);

			super._dispose();

			this._disposed = true;
		}

		public createScrollbar(
			parentShape: ufc.ElementShape,
			sibilings: ufc.ElementShapeContent[],
			scrollingShape: ufc.ElementShape, idx: number): ufc.ElementShape {

			this._overscrollBehaviorType = this._getOverscrollBehaviorType();
			ufc.ShapeUtil.addMandatoryEventHandler(scrollingShape, "touchstart", this._touchStartHandler);
			ufc.ShapeUtil.addMandatoryEventHandler(scrollingShape, "touchmove", this._touchMoveHandler);
			ufc.ShapeUtil.addMandatoryEventHandler(scrollingShape, "touchend", this._touchEndHandler);
			let isDisabledPointer = scrollingShape.style["pointer-events"] == "none" && scrollingShape.attr["disabled"] != null;
			if (parentShape && isDisabledPointer) {
				ufc.ShapeUtil.addMandatoryEventHandler(parentShape, "wheel", this._wheelHandler);
				this._supportPointerEvents = true;
			} else {
				ufc.ShapeUtil.addMandatoryEventHandler(scrollingShape, "wheel", this._wheelHandler);
				this._supportPointerEvents = false;
			}

			if (this.uicontrol instanceof Container) { // 리사이즈 하위전파는 Container만 처리
				ufc.ShapeUtil.addMandatoryEventHandler(scrollingShape, "resize", this._resizeComputeScrollbarHandler);

				this.uicontrol.addEventListener("-child-size-changed-", this._resizeComputeScrollbarHandler); // eventTable에 등록되고 호출되는 이벤트.

				core.DeferredUpdateManager.INSTANCE._asyncExecLast(this._resizeComputeScrollbarHandler); // 스크롤바 존재 유무 체크
			}

			return scrollingShape;
		}

		public _getRenderer(): ufc.ControlRenderer {
			return this.uicontrol?._getRenderer();
		}


		/* event handler methods */
		private _computeScrollbar(): void {
			if (this.disposed || this._getRenderer() == null || this._getRenderer().hasDrawn() == false) {
				return;
			}
			let scrollingNode: HTMLElement = this._getScrollingNode();

			if (scrollingNode != null) {
				// IE에서 Pixel 오차로 인해 VirtualScrollPane과 스크롤 필요여부를 일치시킴
				let vScrollbarAppearance: boolean = (scrollingNode.scrollHeight - scrollingNode.clientHeight) > 2;
				let scrollbarChanged: boolean = false;

				if (this._vScrollbarAppearance === null) {
					this._vScrollbarAppearance = vScrollbarAppearance;
					scrollbarChanged = false;
				} else {
					if (this._vScrollbarAppearance !== vScrollbarAppearance) {
						scrollbarChanged = true;
						this._vScrollbarAppearance = vScrollbarAppearance;
					} else {
						scrollbarChanged = false;
					}
				}

				if (scrollbarChanged) {
					// 스크롤바 생성에 의한 돔 크기 변경 전파
					this.uicontrol._fireResizeEvent();
				}
			}
		}

		/* OverscrollBehavior 관련 */
		// TODO 코드 리펙토링...
		private _touchRoller: internal.TouchRoller = internal.newTouchRoller();
		private _touchMoved: boolean;
		private _onContentTouchStart(e: events.CTouchEvent): void {
			let state: ScrollState = this._getScrollState();
			this._touchMoved = null;
			this._touchRoller._touchStart(e,
				state.maxScrollTop > 0 ? state.scrollTop : -1,
				state.maxScrollLeft > 0 ? state.scrollLeft : -1
			);
		}
		private _onContentTouchMove(e: events.CTouchEvent): void {
			if (e.defaultPrevented === true || e._isOccupied() === true) {
				return;
			}

			if (this._touchMoved === true) {
				e._setOccupied(true);
				return;
			}

			if (this._touchMoved === null) {
				let state: ScrollState = this._getScrollState();
				this._touchRoller._touchMove(e, (scrollTop: number, scrollLeft: number): boolean => {
					let movedY: boolean = scrollTop !== -1
						&& scrollTop !== state.scrollTop
						&& scrollTop >= 0
						&& scrollTop <= state.maxScrollTop ? true : false;
					let movedX: boolean = scrollLeft !== -1
						&& scrollLeft !== state.scrollLeft
						&& scrollLeft >= 0
						&& scrollLeft <= state.maxScrollLeft ? true : false;

					let moved: boolean = movedY || movedX;

					if (moved === true) {
						// 가로 세로가 같이 움직였을 때 많이 움직인 쪽이 스크롤 끝에 닿아있는 상태일 경우 자체 처리는 캔슬됨.
						let offsetY: number = Math.abs(scrollTop - state.scrollTop);
						let offsetX: number = Math.abs(scrollLeft - state.scrollLeft);

						let moveCancel: boolean = false;
						if (offsetY > offsetX) {
							if ((state.scrollTop == state.maxScrollTop && scrollTop > state.maxScrollTop) ||
								(state.scrollTop == 0 && scrollTop < 0)
							) {
								moveCancel = true;
							}
						} else if (offsetY < offsetX) {
							if ((state.scrollLeft == state.maxScrollLeft && scrollLeft > state.maxScrollLeft) ||
								(state.scrollLeft == 0 && scrollLeft < 0)
							) {
								moveCancel = true;
							}
						}

						if (moveCancel === false) {
							// 상위로 전파하지 않음
							if (this._touchMoved == null) {
								this._touchMoved = true;
							}
						} else {
							// 자체 처리 캔슬되고 상위전파
							if (this._touchMoved == null) {
								this._touchMoved = false;
							}
						}
					} else if (this._touchMoved == null) {
						this._touchMoved = false;
					}

					return false;
				});
			}

			if (this._touchMoved) {
				e._setOccupied(true);
			} else if (this._overscrollBehaviorType === OverscrollBehaviorType.NONE) {
				e.preventDefault();
				e._setOccupied(true);
			}
		}
		private _onContentTouchEnd(e: events.CTouchEvent): void {
			this._touchRoller._touchEnd(e, -1, -1, null);
		}
		private _onWheel(e: events.CWheelEvent): void {
			// TODO IE에서 ShiftWheel 동작 여부 확인 필요
			if (e.ctrlKey === true) { // 확대/축소
				return;
			}

			if (e.defaultPrevented === true || e._isOccupied() === true) {
				return;
			}

			let state: ScrollState = this._getScrollState();
			let delta: { x: number, y: number } = ScrollbarUtil._getScrollPaneWheelDelta(e);

			let movable: boolean = false;

			if (delta.y > 0 && state.scrollTop < state.maxScrollTop) {
				movable = true;
			} else if (delta.y < 0 && state.scrollTop > 0) {
				movable = true;
			}

			if (movable === false) {
				if (delta.x > 0 && state.scrollLeft < state.maxScrollLeft) {
					movable = true;
				} else if (delta.x < 0 && state.scrollLeft > 0) {
					movable = true;
				}
			}

			if (movable === true) {
				e._setOccupied(true);
				if (this._supportPointerEvents) {
					let scrollingNode = this._getScrollingNode();
					scrollingNode.scrollTop = scrollingNode.scrollTop + delta.y;
					scrollingNode.scrollLeft = scrollingNode.scrollLeft + delta.x;
					e.preventDefault();
				}
			} else if (this._overscrollBehaviorType === OverscrollBehaviorType.NONE) {
				e.preventDefault();
				e._setOccupied(true);
			}

		}


		/* helper methods */
		private _getScrollState(): ScrollState {
			let scrollInfo: ScrollState = {
				scrollTop: -1, scrollLeft: -1, maxScrollTop: -1, maxScrollLeft: -1
			};
			if (this.disposed || this._getRenderer() == null || this._getRenderer().hasDrawn() === false) {
				return scrollInfo;
			}
			let scrollingNode: HTMLElement = this._getScrollingNode();

			if (scrollingNode != null) {
				scrollInfo.maxScrollTop = scrollingNode.scrollHeight - scrollingNode.clientHeight;
				scrollInfo.maxScrollLeft = scrollingNode.scrollWidth - scrollingNode.clientWidth;
				scrollInfo.scrollTop = scrollingNode.scrollTop;
				scrollInfo.scrollLeft = scrollingNode.scrollLeft;
			}

			return scrollInfo;
		}

		private _getScrollingNode(): HTMLElement {
			let scrollingNode: HTMLElement = null;

			if (this.uicontrol instanceof Container) {
				let container: controls.Container = this.uicontrol as controls.Container;
				scrollingNode = container.getLayout()._getActualScrollingNode();
			} else {
				let renderer: ufc.ControlRenderer = this.uicontrol._getRenderer();
				scrollingNode = renderer.getNamedNode(this._scrollingNodeName);
			}

			return scrollingNode;
		}

	}
}