namespace cpr.utils {

	enum TimerState {
		RUNNING = "running",
		WAITING = "waiting",
		NONE = "none"
	}
	/**
	 * @private
	 */
	export class Timer {
		static RUNNING = TimerState.RUNNING
		static WAITING = TimerState.WAITING
		static NONE = TimerState.NONE

		private _name: string = "";
		private _timeoutId = null;
		private _runnable: (timer: Timer) => void = null;
		private _state: TimerState = Timer.NONE;
		private _intervalCount: number = 0;
		private _isDisposed: boolean = false;
		public data: any;

		constructor(name: string, runnable: () => void = () => { }, data: any = null) {
			this._name = name;
			this._runnable = runnable;
			this.data = data
		}

		/**
		 * Timer을 생성합니다.
		 * @param name 이름
		 * @param runnable 실행할 함수
		 * @returns 
		 */
		static create(name: string, runnable: () => void = () => { }, data: any = null) {
			return new Timer(name, runnable, data);
		}

		public get intervalCount() {
			return this._intervalCount;
		}

		/**
		 * Timer.RUNNING - timer가 실행중이 경우
		 * Timer.WAITING - timer가 실행을 기다리는 경우
		 * Timer.NONE - 모든 케이스에 해당되지 않을때
		 * @returns 
		 */
		public getState() {
			return this._state;
		}

		/**
		 * 초기화 합니다. schedule 중이거나 interval 중인 경우 취소하고 초기화합니다.
		 * @param runnable 
		 * @param data timer의 data를 설정합니다. 기본은 null로 설정됩니다.
		 */
		public init(runnable: (timer: Timer) => void, data: any = null): Timer {
			this.cancel();
			this._runnable = runnable
			this.data = data;
			return this
		}

		/**
		 * Timer을 예약합니다. 호출한 시점에서 다음 틱에서 호출됩니다. 딜레이가 있는 경우 시간을 경과한 후 호출 됩니다.
		 * 예약 중에 다시 예약 하려면 cancel을 한 후에 schedule을 호출해야 합니다.
		 * @param delay 
		 * @param data timer의 data를 설정합니다. 파라미터를 설정하지 않는 경우 data를 유지 합니다. 
		 */
		public schedule(delay: number = 0, data?: any): Timer {
			if (this._state == TimerState.WAITING) {
				return this;
			}
			if (typeof data != "undefined") this.data = data
			this._state = TimerState.WAITING
			this._timeoutId = window.setTimeout(() => {
				this._state = TimerState.RUNNING
				this._timeoutId = null;
				this._runnable(this);
				this._state = TimerState.NONE
			}, delay)
			return this
		}

		/**
		 * 
		 * @param delay 
		 * @param data 
		 */
		public interval(delay: number, data?: null | any): Timer
		/**
		 * 
		 * @param delayFunc 인터벌 카운트 0부터 시작하는 값을 제공합니다.
		 * @param data timer의 data를 설정합니다. 파라미터를 설정하지 않는 경우 data를 유지 합니다. 
		 */
		public interval(delayFunc: (intervalCount: number) => number, data?: null | any): Timer
		public interval(delay: any = 0, data?: null | any): Timer {
			if (typeof data != "undefined") this.data = data
			return this._interval(delay)
		}

		private _interval(delay: any): Timer {
			if (this._state == TimerState.WAITING) {
				return this;
			}
			if (this._isDisposed == false) {
				this._timeoutId = window.setTimeout(() => {
					this._state = TimerState.RUNNING
					this._timeoutId = null;
					this._runnable(this);
					this._interval(delay);
				}, isNaN(delay) == false ? delay : delay(this._intervalCount++))
			}
			return this
		}

		/**
		 * Timer의 이름을 반환합니다.
		 * @returns 
		 */
		public getName() {
			return this._name;
		}

		/**
		 * schedule을 취소 합니다.
		 * @returns 
		 */
		public cancel(): Timer {
			if (this._timeoutId != null) {
				clearTimeout(this._timeoutId);
			}
			this._timeoutId = null;
			this._intervalCount = 0;
			this._state = TimerState.NONE
			return this
		}

		/**
		 * Timer를 dispose상태로 변경합니다.
		 * @returns 
		 */
		public dispose() {
			this.cancel();
			this._isDisposed = true;
		}

		/**
		 * Timer을 실행합니다.
		 * 이 메소드는 schedule을 즉시 실행합니다. schedule이 안되어 있거나 실행 중인 상태에서는 동작하지 않습니다.
		 * @param data timer의 data를 설정합니다. 파라미터를 설정하지 않는 경우 data를 유지 합니다. 
		 */
		public scheduleRun(data?: any): Timer {
			if (this.getState() != Timer.WAITING) {
				return this;
			}
			this.cancel();
			if (typeof data != "undefined") this.data = data;
			this._runnable(this);
			return this
		}

		/**
		 * Timer에 설정한 동작을 실행합니다.
		 * @param data timer의 data를 설정합니다. 파라미터를 설정하지 않는 경우 data를 유지 합니다. 
		 */
		public run(data?: any): Timer {
			if (typeof data != "undefined") this.data = data;
			this._runnable(this);
			return this
		}

	}
}