/// <reference path="../Submission.ts"/>


namespace cpr.protocols.request {
	/**
	 * @private
	 */
	export class URLEncodedMassRequestBuilder extends AbstractRequestBuilder {
		private static readonly _blobType: string = "plain/text";
		private static readonly _blobSize: number = 256 * 1024; // 256 kb


		constructor() {
			super();
		}

		public getContentType(): string {
			return Submission.MEDIA_URLENCODED;
		}

		protected _buildSpecific(submission: Submission): any {
			if (Submission._HASBODY_METHOD.indexOf(submission.method) === -1) {
				console.warn("Submission(\"" + submission.id + "\") method has been changed to POST. \""
					+ Submission.MEDIA_URLENCODED + "\" media types can not use " + submission.method.toUpperCase()
					+ " method. Available methods [" + Submission._HASBODY_METHOD.join(",").toUpperCase() + "]");

				submission.method = Submission.METHOD_POST;
			}

			let requestEncoderSpec: RequestEncoderSpec = submission._getRequestEncoder();
			if (requestEncoderSpec && requestEncoderSpec.encoder) {
				let requestData: Blob = null;

				if (requestEncoderSpec.usingBuildData) {
					requestData = this._buildRequest(submission);
				}

				let returnValue: Promise<EncodingResult> | EncodingResult = requestEncoderSpec.encoder(submission, requestData);
				if (returnValue instanceof Promise) {
					return returnValue.then((encodingResult: EncodingResult) => {
						if (encodingResult.contentType) {
							submission._setInstantContentType(encodingResult.contentType);
						}
						return encodingResult.content;
					});
				} else {
					if (returnValue.contentType) {
						submission._setInstantContentType(returnValue.contentType);
					}
					return returnValue.content;
				}
			} else {
				return this._buildRequest(submission);
			}
		}

		private _buildRequest(submission: Submission): Blob {
			let lobs: (string | Blob)[] = [];

			// check requestObject
			let requestObject: Object = submission.getRequestObject();
			if (requestObject != null) {
				let jsonBlob: utils.JSONBlob = new utils.JSONBlob();
				let pNm: string = URLEncodedRequestBuilder._encode(AbstractRequestBuilder.REQOBJ_PARAMNAME);
				lobs[lobs.length] = new Blob([pNm + "=", jsonBlob.toBlob(requestObject, URLEncodedRequestBuilder._encode), "&"],
					{ type: URLEncodedMassRequestBuilder._blobType });
				pNm = null;
				requestObject = null;
			}

			// parameter
			let paramString: string = this._getParameterString(submission);

			if (paramString.length > 0) {
				lobs[lobs.length] = new Blob([paramString], { type: URLEncodedMassRequestBuilder._blobType });
			}
			paramString = null;

			// datamap/dataset
			let requestDataCount: number = submission.getRequestDataCount();
			for (let idx: number = 0; idx < requestDataCount; idx++) {
				let requestData: RequestData = submission.getRequestData(idx);
				let alias: string = this._getRequestAlias(requestData);
				if (requestData.data instanceof data.DataSet) {
					let dataSet: data.DataSet = requestData.data as data.DataSet;
					let dsLobs: (string | Blob)[] = this._buildDataSet(submission, dataSet, alias, requestData.payload);
					lobs = lobs.concat(dsLobs);
				} else {
					let dataMap: data.DataMap = requestData.data as data.DataMap;
					lobs[lobs.length] = this._buildDataMap(submission, dataMap, alias);
				}
			}

			return new Blob(lobs, { type: URLEncodedMassRequestBuilder._blobType });
		}

		private _getParameterString(submission: Submission): string {
			let paramString: string[] = [];
			let paramNames: string[] = submission.getParameterNames();
			for (let idx: number = 0; idx < paramNames.length; idx++) {
				let name: string = paramNames[idx];
				let encodedName: string = URLEncodedRequestBuilder._encode(name);
				let values: string[] = submission.getParameters(name);

				for (let vidx: number = 0; vidx < values.length; vidx++) {
					paramString[paramString.length] = encodedName + "=" + URLEncodedRequestBuilder._encode(values[vidx]) + "&";
				}
			}
			return paramString.join("");
		}

		private _buildDataSet(submission: Submission, dataSet: data.DataSet, alias: string, payload: PayloadType): (string | Blob)[] {
			let dsLobs: (string | Blob)[] = [];
			let dataDelimiter: string = super._createDataDelimiter();

			let reqBuffer: string[] = [];
			let strLeng: number = 0;
			this._loadPayload(submission, dataSet, payload, (rowdata: data.RowConfigInfo, additionalParam: { [key: string]: string }, stateText: string) => {
				for (let columnName in rowdata) {
					let name: string = URLEncodedRequestBuilder._encode(dataDelimiter + columnName);
					let value: string | number | boolean = rowdata[columnName];
					if (value == null) {
						value = "";
					}
					value = URLEncodedRequestBuilder._encode("" + value);
					let strUnit = name + "=" + value + "&";
					reqBuffer[reqBuffer.length] = strUnit;
					strLeng += strUnit.length;
				}

				let strParam: string = this._applyAdditionalParam(additionalParam, dataDelimiter);
				if (strParam.length > 0) {
					reqBuffer[reqBuffer.length] = strParam;
					strLeng += strParam.length;
				}

				let statName: string = dataDelimiter + "sts"; // TODO 공통화
				reqBuffer[reqBuffer.length] = URLEncodedRequestBuilder._encode(statName);
				reqBuffer[reqBuffer.length] = "=";
				reqBuffer[reqBuffer.length] = URLEncodedRequestBuilder._encode(stateText) + "&";
				if (strLeng >= URLEncodedMassRequestBuilder._blobSize) {
					dsLobs[dsLobs.length] = new Blob(reqBuffer, { type: URLEncodedMassRequestBuilder._blobType });
					strLeng = 0;
					reqBuffer.splice(0, reqBuffer.length);
				}
			});

			if (strLeng > 0) {
				dsLobs[dsLobs.length] = reqBuffer.join("");
			}
			reqBuffer = null;

			dsLobs[dsLobs.length] = URLEncodedRequestBuilder._encode(super._getDataDelimiterParamName()) + "=" + URLEncodedRequestBuilder._encode(dataDelimiter) + "&";
			if (alias) {
				dsLobs[dsLobs.length] = URLEncodedRequestBuilder._encode(dataDelimiter) + "=" + URLEncodedRequestBuilder._encode(alias) + "&";
			}
			dsLobs[dsLobs.length] = URLEncodedRequestBuilder._encode(dataDelimiter + "tp") + "=ds&"; // parameter group type

			return dsLobs;
		}

		private _buildDataMap(submission: Submission, dataMap: data.DataMap, alias: string): Blob {
			let requestString: string = "";
			let columnNames: string[] = dataMap.getColumnNames();
			let dataDelimiter: string = super._createDataDelimiter(); // DataMap 별로 생성
			columnNames.forEach((columnName: string) => {
				let name: string = URLEncodedRequestBuilder._encode(dataDelimiter + columnName);
				let value: string = dataMap.getString(columnName);
				if (value == null) {
					value = "";
				}
				value = URLEncodedRequestBuilder._encode(value);
				requestString += name + "=" + value + "&";
			});

			requestString += this._applyAdditionalParam(submission._handleDataMap(dataMap), dataDelimiter);

			requestString += URLEncodedRequestBuilder._encode(super._getDataDelimiterParamName()) + "=" + URLEncodedRequestBuilder._encode(dataDelimiter) + "&";
			if (alias) {
				requestString += URLEncodedRequestBuilder._encode(dataDelimiter) + "=" + URLEncodedRequestBuilder._encode(alias) + "&";
			}
			requestString += URLEncodedRequestBuilder._encode(dataDelimiter + "tp") + "=dm&"; // parameter group type

			return new Blob([requestString], { type: URLEncodedMassRequestBuilder._blobType });
		}

		private _applyAdditionalParam(additionalParam: { [key: string]: string }, dataDelimiter: string): string {
			if (additionalParam) {
				let strParam: string[] = [];
				for (let key in additionalParam) {
					let name: string = URLEncodedRequestBuilder._encode(dataDelimiter + key);
					let value: string = additionalParam[key];
					if (value == null) {
						value = "";
					}
					value = URLEncodedRequestBuilder._encode(value);
					strParam[strParam.length] = name;
					strParam[strParam.length] = "=";
					strParam[strParam.length] = value;
					strParam[strParam.length] = "&";
				}

				return strParam.join("");
			}
			return "";
		}
	}
}