	enum Scrollability {
		UNKNOWN,
		SCROLLABLE,
		UNSCROLLABLE
	}

	interface ItemPaneScrollInfo {
		horizontalScrollability: Scrollability
		leftScrollability: Scrollability
		rightScrollability: Scrollability
	}

