	function isFocusableItem(item: TabItem) {
		if (!item) {
			return false;
		}
		return item.enabled && item.visible;
	}

	class TabItemFocusEntry implements FocusEntry {
		private _tabFolder: TabFolder;
		private _selector: string;
		constructor(folder: TabFolder, selector: string) {
			this._tabFolder = folder;
			this._selector = selector;
		}

		focus(forward: boolean) {
			let focusedItem = this._tabFolder._getFocusedTabItem() || this._tabFolder.getSelectedTabItem();
			let targetItem = isFocusableItem(focusedItem) ? focusedItem : this._tabFolder.getTabItems().find(it => isFocusableItem(it));
			if (targetItem) {
				targetItem._focus(this._selector);
			}
		}
	}

