// /// <reference path="./CEvent.ts"/>

/// <reference path="./DOMEventWrapper.ts" />


namespace cpr.events {
	/**
	 * 스크롤 이벤트 유형.
	 */
	export class ScrollEventType {
		public static readonly SCROLL: string = "scroll";
	}

	/**
	 * 스크롤 이벤트의 종류.
	 */
	export enum ScrollAxis {
		/**
		 * "x"
		 */
		x = "x",
		/**
		 * "y"
		 */
		y = "y",
		/**
		 * "both"
		 */
		both = "both"
	}

	/**
	 * 스크롤 이벤트 옵션.
	 */
	export interface CScrollEventOptions extends CEventOption {
		/**
		 * 스크롤 이벤트의 종류.
		 * 상/하, 좌/우
		 */
		axis: ScrollAxis,
		/**
		 * 세로 스크롤의 위치 값.
		 */
		scrollTop?: number;
		/**
		 * 최대 세로 스크롤의 위치 값.
		 */
		maxScrollTop?: number;
		/**
		 * 가로 스크롤의 위치 값.
		 */
		scrollLeft?: number;
		/**
		 * 최대 가로 스크롤의 위치 값.
		 */
		maxScrollLeft?: number;
	}


	/**
	 * 스크롤 변화 시 발생하는 이벤트
	 */
	export class CScrollEvent extends CEvent {

		/**
		 * 스크롤 이벤트를 생성합니다.
		 * @param type 스크롤 이벤트의 유형.
		 * @param options 스크롤 이벤트 옵션.
		 */
		constructor(type: string, options: CScrollEventOptions) {
			super(type, options);
		}

		/**
		 * 스크롤이 발생한 방향이 세로 방향인지 가로 방향인지 또는 대각선 방향인지 여부를 반환합니다.
		 */
		public get axis(): ScrollAxis {
			return this._getOption("axis");
		}

		/**
		 * 세로 스크롤의 위치 값을 반환합니다.
		 * @return 세로 스크롤의 위치 값.
		 */
		public get scrollTop(): number {
			return this._getOption("scrollTop");
		}

		/**
		 * 최대 세로 스크롤의 값을 반환합니다.
		 * @return 최대 세로 스크롤의 위치 값.
		 */
		public get maxScrollTop(): number {
			return this._getOption("maxScrollTop");
		}

		/**
		 * 가로 스크롤의 위치 값을 반환합니다.
		 * @return 가로 스크롤의 위치 값.
		 */
		get scrollLeft(): number {
			return this._getOption("scrollLeft");
		}

		/**
		 * 최대 가로 스크롤의 값을 반환합니다.
		 * @return 최대 가로 스크롤의 위치 값.
		 */
		public get maxScrollLeft(): number {
			return this._getOption("maxScrollLeft");
		}


	}
}