		/**
		 * 트리 그리드의 체크 상태를 갱신합니다.
		 * 실 체크상태(rowdata)를 가져와 보여지는 체크상태(GridRowGroup#_setCheckState)를 갱신합니다.
		 * @private
		 */
		private _resetTreeCellChecked(checkType: gridpart.renderer.TreeCellCheckType): void {
			let checked: boolean = this._getTreeCellChecked();

			// INDEPENDENT
			if (checkType == gridpart.renderer.TreeCellCheckType.INDEPENDENT) {
				let checkedState: CHECKMODE = (checked == false) ? CHECKMODE.UNCHECKED : CHECKMODE.CHECKED;
				this._setCheckedState(checkedState); // 보여지는 체크상태 변경
				return;
			}
			// HYBRID
			else if (checkType == gridpart.renderer.TreeCellCheckType.HYBRID) {
				if (checked) {
					this._setCheckedState(CHECKMODE.CHECKED); // 보여지는 체크상태 변경
				} else {
					let checkState: string = CHECKMODE.UNCHECKED;
					let rows: (GridRow | GridRowGroup)[] = this._getRows();
					if (rows.length > 0) {
						rows.some((row: (GridRow | GridRowGroup)) => {
							if (row instanceof GridRowGroup) {
								let childChecked: CHECKMODE = row._getCheckedState();
								if (childChecked == CHECKMODE.CHECKED || childChecked == CHECKMODE.PARTIAL_CHECKED) {
									checkState = CHECKMODE.PARTIAL_CHECKED;
									return true;
								}
							}
						});
					}
					this._setCheckedState(checkState); // 보여지는 체크상태 변경
				}
				this.parent?._resetTreeCellChecked(checkType);
			}
			// CASCADE
			else {
				let checkState: string = CHECKMODE.UNCHECKED;
				let rows: (GridRow | GridRowGroup)[] = this._getRows();
				if (rows.length > 0) {
					let checkCount: number = 0;
					rows.forEach((row: (GridRow | GridRowGroup)) => {
						if (row instanceof GridRowGroup) {
							let childChecked: CHECKMODE = row._getCheckedState();
							if (childChecked == CHECKMODE.CHECKED || childChecked == CHECKMODE.PARTIAL_CHECKED) {
								if (childChecked == CHECKMODE.CHECKED) {
									checkCount++;
								}
								checkState = CHECKMODE.PARTIAL_CHECKED;
							}
						}
					});
					if (rows.length == checkCount) {
						checkState = CHECKMODE.CHECKED;
					}
				} else {
					checkState = (checked == false) ? CHECKMODE.UNCHECKED : CHECKMODE.CHECKED;
				}
				this._setCheckedState(checkState); // 보여지는 체크상태 변경
				this.parent?._resetTreeCellChecked(checkType);
			}

		}

		/**
		 * 행그룹 그리드의 체크 상태를 설정합니다.
		 * @param checked 체크 상태.
		 * @param cascade 체크상태 하위전파 여부.
		 * @private
		 */
		public _setGroupingChecked(cellProp: gridpart.GridGroupHeaderCellProp, checked: boolean, cascade: boolean = true): void {
			if (cascade) {
				let detailCellProp: gridpart.GridDetailCellProp = null;
				if (cellProp != null) {
					let detailCellIndices: number[] = this.grid.context._getDetailCellIndicesFromCellProp(cellProp);
					let detailColumn: gridpart.GridDetailColumn = (detailCellIndices.length == 1) ? this.grid.detail.getColumn(detailCellIndices[0]) : null;
					detailCellProp = (detailColumn?.columnType == "checkbox") ? detailColumn.cellProp : null;
				}

				this._cascadeGroupingChildCheck(detailCellProp, checked);
			}
			this._parent?._resetGroupingChecked(true);
			this._grid.redraw();
		}

		/**
		 * 행그룹 그리드의 체크 상태를 설정합니다. (하위 전파)
		 * @param checked 체크 상태.
		 * @private
		 */
		private _cascadeGroupingChildCheck(detailCellProp: gridpart.GridDetailCellProp, checked: boolean): void {
			// this._checkedState = (checked == false) ? CHECKMODE.UNCHECKED : CHECKMODE.CHECKED;

			let rows: (GridRow | GridRowGroup)[] = this._getRows();
			this.grid._keepContentDataRowIndex();
			rows.forEach((row: (GridRow | GridRowGroup)) => {
				if (row instanceof GridRowGroup) {
					row._cascadeGroupingChildCheck(detailCellProp, checked);
				} else if ((row.rowCheckEnabled == true && row.rowCheckVisible == true)) {
					this.grid._setContentDataRowIndex(row.getIndex(), -1);
					let cellEnabled: boolean = detailCellProp?.configuration.enabled ?? true;
					let cellVisible: boolean = detailCellProp?.configuration.visible ?? true;
					if (cellEnabled === true && cellVisible === true) {
						this._grid._setCheckRowIndex(row.getIndex(), checked);
					}
				}
			});
			this.grid._restoreContentDataRowIndex();
			this._resetGroupingChecked(false);

		}

		/**
		 * 행그룹 그리드의 체크 상태를 설정합니다. (상위 전파)
		 * @param isPropagate 부모로 재귀호출 여부.
		 * @private
		 */
		public _resetGroupingChecked(isPropagate: boolean): void {
			let checkState: CHECKMODE = null;
			let rows: (GridRow | GridRowGroup)[] = this._getRows();
			if (rows.length > 0) {
				let length: number = rows.length;
				for (let i = 0; i < length; i++) {
					let row = rows[i];
					let childChecked: CHECKMODE = null;
					if (row instanceof GridRowGroup) {
						childChecked = row._getCheckedState();
					} else {
						childChecked = (row._getRowChecked()) ? CHECKMODE.CHECKED : CHECKMODE.UNCHECKED;
					}
					if (checkState == null) {
						checkState = childChecked;
					} else if (checkState != childChecked || checkState == CHECKMODE.PARTIAL_CHECKED) {
						checkState = CHECKMODE.PARTIAL_CHECKED;
						break;
					}
				}
			}
			if (checkState == CHECKMODE.PARTIAL_CHECKED) {
				let partialCheckState: string = this.grid._getPartialCheckState(this.startRowIndex, this.endRowIndex);
				checkState = partialCheckState;
			}

			if (this._getCheckedState() !== checkState) {
				this._setCheckedState(checkState);
				if (isPropagate) {
					this.parent?._resetGroupingChecked(isPropagate);
				}
			}
		}

