		public getSum(columnName: column_name_string): foundation.DecimalType {
			let statisticsName: string = "[" + this.startRowIndex + "~" + this.endRowIndex + "]getSum('" + columnName + "')";
			if (this._dataProvider._getStatisticCache(statisticsName) != null) {
				return this._dataProvider._getStatisticCache(statisticsName) as foundation.DecimalType;
			}
			let func: Function = cpr.expression.ExpressionEngine.INSTANCE.compile(columnName) as Function;
			let sum: foundation.DecimalType = new foundation.DecimalType(0);
			let recursiveSum: (row: GridRow | GridRowGroup) => void = (row: GridRow | GridRowGroup) => {
				if (row instanceof GridRow) {
					let value: (string | number | foundation.DecimalType) = func(row as GridRow);
					let numberValue: number = Number(value);
					if (isNaN(numberValue) == false) {
						value = (value == "" || value == null) ? numberValue : value;
						sum = sum.plus(value);
					}

				} else {
					let gridRowGroup: GridRowGroup = row as GridRowGroup;
					let childRows: (GridRow | GridRowGroup)[] = gridRowGroup._getRows();
					let self: GridRow = gridRowGroup.target;
					if (self) {
						let value: (string | number | foundation.DecimalType) = func(self);
						let numberValue: number = Number(value);
						if (isNaN(numberValue) == false) {
							value = (value == "" || value == null) ? numberValue : value;
							sum = sum.plus(value);
						}
					}
					if (childRows && childRows.length > 0) {
						childRows.forEach(recursiveSum);
					}
				}
			};
			recursiveSum(this);

			this._dataProvider._setStatisticCache(statisticsName, sum);
			return sum;
		}

