		/* helper method */
		/**
		 * @private
		 */
		public _isExistColumn(columnName: string): boolean {
			return this._dataControl.isExistColumn(columnName);
		}

		/**
		 * @private
		 * 현재 view 데이터 기준으로 입력 받은 조건에 맞는 Row 객체 배열을 반환한다.
		 * 
		 * @param condition		조건식
		 * @return 입력 받은 조건에 맞는 Row 객체 배열
		 */
		private _getFilterRows(condition: expression.Expression): data.Row[] {
			let viewRows: data.Row[] = [];
			let startIndex: number = this.startRowIndex;
			let endIndex: number = this.endRowIndex;
			for (let i = startIndex; i <= endIndex; i++) {
				viewRows[viewRows.length] = new data.Row(this._dataControl, i);
			}
			return viewRows.filter(condition.asFilter());
		}

		/**
		 * 행 그룹을 접습니다.
		 * @param deep 하위 depth의 행 그룹까지 접을지 여부.
		 */
		public collapse(deep: boolean = false): void {
			if (deep == true) {
				let rows: (GridRow | GridRowGroup)[] = this._getRows();
				rows.forEach((row: (GridRow | GridRowGroup)) => {
					if (row instanceof GridRowGroup) {
						row.collapse(deep);
					}
				})
				this.expanded = false;
			} else {
				this.expanded = false;
			}
		}

		/**
		 * 행 그룹을 펼칩니다.
		 * @param deep 하위 depth의 행 그룹까지 펼칠지 여부.
		 */
		public expand(deep: boolean = false): void {
			if (deep == true) {
				let rows: (GridRow | GridRowGroup)[] = this._getRows();
				rows.forEach((row: (GridRow | GridRowGroup)) => {
					if (row instanceof GridRowGroup) {
						row.expand(deep);
					}
				})
				this.expanded = true;
			} else {
				this.expanded = true;
			}
		}

		/**
		 * @private
		 */
		_getExpressionOnlyProperty(prop: string) {
			if (prop == "localIndex") {
				return this.getLocalIndex();
			} else if (this._isExistColumn(prop)) {
				let startrowindex: number = this.startRowIndex;
				return this.getValue(startrowindex, prop);
			} else {
				return undefined;
			}
		}

		/**
		 * @private
		 */
		_getExpressionIDLookupProvider() {
			return this._grid.getAppInstance();
		}

		/**
		 * @private
		 */
		_getExpressionDelegates(): any[] {
			let delegates: any[] = [];
			if (this._grid) {
				delegates[delegates.length] = this._grid;
				if (this._grid.dataProvider) {
					delegates[delegates.length] = this._grid.dataProvider;
				}
				if (this._grid.dataSet) {
					delegates[delegates.length] = this._grid.dataSet;
				}
			}
			return delegates;
		}

