namespace cpr {
	const NO_VALUE = new Object();
	const _caches: _RealmCache[] = [];


	function _pushNewCache(subject: string): void {
		_caches.push(new _RealmCache(subject));
	}

	function _popCache() {
		_caches.pop();
	}

	class _RealmCache {
		private _data: CMap<string, any>;
		private _subject: string;

		constructor(subject: string) {
			this._subject = subject;
			this._data = _createMap();
		}

		_matches(subject: string): boolean {
			return this._subject == subject || subject == null;
		}

		/**
		 * 캐시된 값을 질의 합니다. 캐시된 결과가 없다면 {@link NO_VALUE}가 반환됩니다. 
		 * null 또는 undefined가 반환되었다면 그 값이 캐시된 것입니다.
		 * 
		 * @param key 캐시 질의 키.
		 * @returns 캐시된 값.
		 */
		_get(key: string) {
			return this._data.has(key)
				? this._data.get(key)
				: NO_VALUE;
		}

		_set(key: string, data: any) {
			this._data.set(key, data);
		}
	}

	/**
	 * 현재 렐름 캐시에 질의된 키의 값이 있는 경우 해당 값을 반환하고, 그 외의 경우 평가함수를 실행하여 그 결과를 캐시한 후 반환 합니다.
	 * {@link _runWithRealmCache} 문맥 내에서 코드가 실행된 경우에만 캐시 매커니즘이 작동 합니다.
	 *
	 * @param key 렐름 캐시에 사용할 고유 키.
	 * @param evaluateFunc 평가 함수.
	 * @returns 캐시된 값 또는 평가된 값.
	 * 
	 * @see _runWithRealmCache
	 */
	export function _tryRealmCache<T>(subjects: string[], key: string, evaluateFunc: () => T): T {
		let realmCache = _getActiveRealmCache(subjects);

		// 렐름 캐시가 없는 경우
		if (!realmCache) {
			return evaluateFunc();
		}

		let result = realmCache._get(key);
		if (result === NO_VALUE) {
			result = evaluateFunc();
			realmCache._set(key, result);
		}
		return result;
	}

	function _getActiveRealmCache(subjects: string[]): _RealmCache {
		for (let idx = _caches.length - 1; idx >= 0; idx--) {
			let eachCacheStack = _caches[idx];
			if (subjects.some(e => eachCacheStack._matches(e))) {
				return eachCacheStack;
			}
		}
		return null;
	}

	/**
	 * 랠름 캐시를 하나 선포하고 특정 코드를 실행합니다.
	 * 코드 내에서 {@link _tryRealmCache}를 사용할 수 있게 됩니다.
	 * 
	 * @param task 실행할 작업.
	 * @returns 작업의 결과.
	 */
	export function _runWithRealmCache<T>(subject: string, task: () => T): T {
		let needsNewStack = _caches.some(it => it._matches(subject)) === false;
		if (needsNewStack) {
			_pushNewCache(subject);
			try {
				return task();
			} finally {
				_popCache();
			}
		} else {
			return task();
		}

	}
}
