
namespace cpr.controls.media {
	/**
	 * 오디오 / 비디오와 컴포넌트에 자막 출력시 사용되는 아이템.
	 * 
	 */
	export class TextTrack {

		private _kind: string = "subtitles";
		private _label: string;
		private _src: string;
		private _srclang: string;

		/**
		 * 트랙을 생성합니다. 
		 * @param src 트랙의 source. 웹 서버를 통한 소스만 가능합니다. 
		 * @param label 자막의 label
		 */
		constructor(src: string, label?: string) {
			this._src = src;
			if (label) {
				this._label = label;
			}
		}

		/**
		 * 텍스트 자막이 사용되는 방법에 대해 반환합니다.
		 * @return 자막이 사용되는 방법.
		 */
		get kind(): string {
			return this._kind;
		}
		/**
		 * 텍스트 자막의 사용되는 방법에 대해 설정합니다.<br>
		 * 기본 값은 'subtitles'입니다. 
		 * [captions] : 오디오의 번역 및 번역을 제공합니다.
		 * [chapters] : 챕터 제목은 사용자가 미디어 리소스를 탐색 할 때 사용하기위한 것입니다.
		 * [descriptions] : 비디오 컨텐츠의 텍스트 설명
		 * [metadata] : 자막이 스크립트에 의해 사용됩니다. 사용자에게 보여지지 않습니다.
		 * [subtitles] : 비디오의 언어 영상에 다른 언어 표시
		 * @param value 자막이 사용되는 방법.
		 */
		set kind(value: string) {
			this._kind = value;
		}

		/**
		 * 자막의 주소를 반환합니다. 웹 서버를 통한 소스만 가능합니다. 
		 * IE는 서버에서 전송 받을때 content-type이 text/vtt로 표시되어야 정상 동작합니다. 서버의 MIME type을 확인해주시기 바랍니다.
		 * @return 자막의 주소.
		 */
		get src(): string {
			return this._src;
		}
		/**
		 * 자막의 주소를 설정합니다. (Ex .vtt 파일).<br>
		 * 이 속성은 반드시 정의되어야만 하고 유효한 URL이어야만 합니다.
		 * @param value 자막의 주소.
		 */
		set src(value: string) {
			this._src = value;
		}

		/**
		 * 자막 텍스트 데이터의 언어를 반환합니다.
		 * (Ex. en, ja, ja-JP)
		 * @return 자막 텍스트 데이터의 언어.
		 */
		get srcLang(): string {
			return this._srclang;
		}
		/**
		 * 자막 텍스트 데이터의 언어를 설정합니다.<br>
		 * 이 속성의 값은 유효한 BCP 47 언어 태그여야 합니다.<br>
		 * 관련 속성: [kind] 속성 값이 subtitles로 설정되었을 경우, srcLang 속성은 반드시 정의되어야 합니다.
		 * (Ex. en, ja, ja-JP)
		 * @param value 자막 텍스트 데이터의 언어.
		 */
		set srcLang(value: string) {
			this._srclang = value;
		}

		/**
		 * 브라우저가 사용가능한 자막 텍스트를 나열할 때 사용자가 읽을 수 있는 자막 텍스트의 제목을 반환합니다.
		 * @return 자막 텍스트의 제목.
		 */
		get label(): string {
			return this._label;
		}
		/**
		 * 브라우저가 사용 가능한 자막 텍스트를 나열할떄 사용되는 사용자가 읽을수 있는 자막 텍스트의 제목을 설정합니다.
		 * @param value 자막 텍스트의 제목.
		 */
		set label(value: string) {
			this._label = value;
		}

	}
}