/// <reference path="./AbstractSubmission.ts" />

namespace cpr.protocols {
	/**
	 * MatrixSubmission.
	 * 서버와 통신하기 위한 컨트롤.
	 * 
	 * @fires cpr.events.CSubmissionEvent#before-submit 통신을 시작하기 전에 발생합니다.
	 * 
	 * @fires cpr.events.CSubmissionEvent#before-send XMLHttpRequest가 open된 후 send 함수가 호출되기 직전에 발생합니다.
	 * 
	 * @fires cpr.events.CSubmissionEvent#error-status 서버로 부터 에러로 분류되는 HTTP상태 코드를 전송받았을 때 발생합니다.
	 * 
	 * @fires cpr.events.CSubmissionEvent#receive 서버로부터 데이터를 모두 전송 받았을 때 발생합니다.
	 * 
	 * @fires cpr.events.CSubmissionEvent#receive-json 응답 프로토콜이 json일 때 서버로 부터 받은 JSON 문자열을 JSONObject로 파싱에 성공했을 때 발생합니다.
	 * 
	 * @fires cpr.events.CSubmissionEvent#submit-load-progress 서버로 부터 수신된 데이터가 응답 데이터컨트롤에 부분적으로 적재되었을 때 발생합니다.
	 * 
	 * @fires cpr.events.CSubmissionEvent#submit-upload-progress multipart/form-data 일 때 서버로 일정 크기의 데이터를 전송했을 때 발생합니다.
	 * 
	 * @fires cpr.events.CSubmissionEvent#submit-progress 서버로부터 일정 크기의 데이터를 전송 받았을때 발생합니다. Async로 동작할 때만 사용할 수 있고 하나의 응답에 대해 여러 번 발생 할 수 있습니다.
	 * 
	 * @fires cpr.events.CSubmissionEvent#submit-success 서버로부터 데이터를 모두 전송 받고, 서브미션의 응답데이터의 데이터셋, 데이터맵에 처리가 끝난 후에 발생합니다.
	 * 
	 * @fires cpr.events.CSubmissionEvent#submit-error 통신에 오류 발생시 호출됩니다.
	 * 
	 * @fires cpr.events.CSubmissionEvent#submit-done 통신 오류 또는 성공 여부에 상관없이 마지막에 항상 발생합니다.
	 * 
	 * @fires cpr.events.CSubmissionEvent#submit-timeout 통신 중 Timeout이 발생했을 때 호출되는 이벤트입니다. Async로 동작할 때만 사용할 수 있습니다.
	 * 
	 * 
	 */
	export class MatrixSubmission extends AbstractSubmission {


		constructor(id?: string) {
			super(id);

			// control initializing
			this._initControl();
		}

		override _getType(): controls.ControlType {
			return controls.ControlType.MATRIXSUBMISSION;
		}

		/* Encoder/Decoder */
		/**
		 * 서버로 전송하는 데이터를 별도의 형식으로 Encoding할 수 있는 함수를 등록합니다.<br>
		 * 매트릭스 서브미션의 requestEncoder로는 비동기함수를 설정할 수 없습니다.
		 * @param requestEncoder (submission:cpr.protocols.MatrixSubmission, data:string) => {key:string, content:{}|string} 형식의 callback handler
		 */
		public setRequestEncoder(requestEncoder: (submission: MatrixSubmission, data: string) => { key: string, content: string }): void {
			super.setRequestEncoder(requestEncoder);
		}

		/**
		 * 서버로 부터 전송받은 eXBuilder6에서 지원하지 않는 형식의 데이터를 eXBuilder6에서 지원하는 형식으로 변환하거나 자체적으로 처리할 수 있는 Decoding 함수를 등록합니다.
		 * @param responseDecoder (submission:cpr.protocols.MatrixSubmission, data:string) => {contentType:string, content:string} 형식의 callback handler
		 */
		public setResponseDecoder(decoder: (submission: MatrixSubmission, data: string) => { contentType: string, content: string }): void {
			super.setResponseDecoder(decoder);
		}

		/*
		 * <======================================== ProtocolDataModel ========================================>
		 */

		/**
		 * 매트릭스 서브미션에 요청을 만들고 응답을 해석하는 방법을 기술하는 모델을 지정합니다.
		 * @param matrixDefinition 매트릭스 정의 모델.
		 */
		public setMatrix(matrixDefinition: matrix.Matrix): void {
			this.setProtocolDataModel(new matrix.MatrixDataModel(matrixDefinition));
		}

		/**
		 * 매트릭스 서브미션의 요청 작성 및 응답 해석 방법이 기술된 모델을 얻습니다.
		 * 반환 값은 사본으로 이를 수정하여도 서브미션은 영향 받지 않습니다.
		 * @returns 매트릭스 정의 모델 사본.
		 */
		public getMatrix(): matrix.Matrix {
			if (this._protocolDataModel instanceof matrix.MatrixDataModel) {
				return _deepCopy(
					this._protocolDataModel._getMatrix(),
					// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/9592
					// 일반 JSON만 복제하도록 함
					node => node.constructor === Object
				);
			}
			else {
				return null;
			}
		}

		/**
		 * 매트릭스 데이터 모델을 지정합니다.
		 * @param dataModel 매트릭스 데이터 모델
		 * 
		 * @deprecated {@link setMatrix}를 대신 사용 하십시오.
		 */
		// @private 이었지만 컴파일러가 이를 사용했었기 때문에 과거 코드 호환성 유지를 위해 남겨 둠.
		public setProtocolDataModel(dataModel: matrix.MatrixDataModel) {
			this._protocolDataModel = dataModel;
		}

		/**
		 * @private
		 * @returns cpr.protocols.ProtocolDataModel
		 */
		public _getProtocolDataModel(): ProtocolDataModel {
			return this._protocolDataModel;
		}

		/**
		 * MatrixSubmission에 사용자 요청 데이터를 설정합니다.
		 * @param path 설정할 요청 매트릭스 경로
		 * @param data 설정할 데이터
		 */
		public addRequestData(path: string, data: string | number | {}): void {
			if (this._protocolDataModel) {
				(this._protocolDataModel as matrix.MatrixDataModel)._addCustomRequestData(path, data);
			}
		}

		/**
		 * MatrixSubmission에 추가된 모든 사용자 요청 데이터를 반환합니다.
		 */
		public getAllRequestDatas(): matrix.CustomRequestData[] {
			if (this._protocolDataModel) {
				return (this._protocolDataModel as matrix.MatrixDataModel)._getAllCustomRequestDatas();
			}
			return null;
		}

		/**
		 * MatrixSubmission에 추가된 사용자 요청 데이터를 모두 삭제합니다.
		 */
		public removeAllRequestDatas(): void {
			if (this._protocolDataModel) {
				(this._protocolDataModel as matrix.MatrixDataModel)._removeAllCustomRequestDatas();
			}
		}

		/* 멀티파트 지원 시작 */
		/**
		 * Multipart로 전송될 때 데이터가 전송될 파트의 이름을 설정한다.
		 * 설정되지 않으면 기본적으로 _JSONREQUESTOBJ_ 값이 사용된다.
		 * @param name 데이터파트의 파라미터 이름
		 */
		public setDataPartName(name: string): void {
			if (this._protocolDataModel) {
				(this._protocolDataModel as matrix.MatrixDataModel)._setDataPartName(name);
			}
		}

		/**
		 * @deprecated 매트릭스 서브미션의 페이로드를 동적으로 변경하려면 {@link setMatrix} 및 {@link getMatrix}를 사용하십시오.
		 */
		public setDataRowHandler(dataRowHandler: (rowdata: RowUnit) => { [key: string]: string }, handleDataMap: boolean = false): void {
			this._setDataRowHandler(dataRowHandler, handleDataMap);
		}

		/**
		 * Multipart로 요청을 전송할지 여부를 설정한다.
		 * 기본 값은 false이며 첨부된 파일이 있으면 기본값에 관계없이 Multipart로 서버로 전송된다.
		 * true로 설정되면 첨부파일의 유무에 관계없이 Multipart로 서버로 전송된다.
		 * @param multipartRequest Multipart 요청 여부
		 */
		public setMultipartrequest(multipartRequest: boolean): void {
			if (this._protocolDataModel) {
				(this._protocolDataModel as matrix.MatrixDataModel)._setMultipartRequest(multipartRequest);
			}
		}

		/**
		 * Matrix 요청데이터에 파일 파트를 추가합니다.
		 * @param name 파일파트 파라미터 이름
		 * @param file 파일 객체
		 */
		public addFileParameter(name: string, file: File): void {
			if (name == null || name == "") {
				throw new cpr.exceptions.IllegalArgumentException("param name");
			}
			if (this._protocolDataModel) {
				(this._protocolDataModel as matrix.MatrixDataModel)._addFileParameter(name, file);
			}
		}

		/**
		 * Matrix 요청데이터에 파일 파트를 추가합니다. 하나 또는 여러 파일을 추가할 수 있습니다.
		 * @param name 파일파트 파라미터 이름
		 * @param value 파일 객체
		 */
		public setFileParameters(name: string, value: File[] | File): void {
			if (name == null || name == "") {
				throw new cpr.exceptions.IllegalArgumentException("param name");
			}
			if (this._protocolDataModel) {
				(this._protocolDataModel as matrix.MatrixDataModel)._removeFileParameters(name);
				if (_isArray(value) == true) {
					(value as File[]).forEach((val: File) => {
						(this._protocolDataModel as matrix.MatrixDataModel)._addFileParameter(name, val);
					})
				} else {
					(this._protocolDataModel as matrix.MatrixDataModel)._addFileParameter(name, value as File);
				}
			}
		}

		/**
		 * 파라미터명의 파일을 반환합니다.
		 * @param name 파라미터의 이름
		 * @return 파일 배열
		 */
		public getFileParameters(name: string): File[] {
			if (this._protocolDataModel) {
				return (this._protocolDataModel as matrix.MatrixDataModel)._getFileParameters(name);
			}
			return [];
		}

		/**
		 * 파일로 등록된 파라미터의 이름들을 반환합니다.
		 * @returns 파일 명의 배열.
		 */
		public getFileParameterNames(): string[] {
			if (this._protocolDataModel) {
				return (this._protocolDataModel as matrix.MatrixDataModel)._getFileParameterNames();
			}
			return [];
		}

		/**
		 * 파일로 등록된 파라미터를 제거합니다.
		 * @param name 파라미터의 이름
		 * @return 파일 배열.
		 */
		public removeFileParameters(name: string): File[] {
			if (this._protocolDataModel) {
				return (this._protocolDataModel as matrix.MatrixDataModel)._removeFileParameters(name);
			}
			return [];
		}

		/**
		 * 파일로 등록된 파라미터들을 전부 제거합니다.
		 */
		public removeAllFileParameters(): void {
			if (this._protocolDataModel) {
				(this._protocolDataModel as matrix.MatrixDataModel)._removeAllFileParameters();
			}
		}
		/* 멀티파트 지원 끝 */



		protected _getResponseParser(): ResponseParser {
			return this._protocolDataModel.getResponseParser(this.xhr, null, null);
		}

		protected _clearSubmissionStatus(): void {
			this._setSuccess(true, null);
		}

		/**
		 * MatrixSubmission에 추가된 사용자 요청 데이터를 모두 삭제합니다.
		 */
		public clearAllInstantParameters(): void {
			this.removeAllRequestDatas();
			this.removeAllFileParameters();
		}

		/* Helper Methods */
		/**
		 * MatrixSubmission의 응답모델을 기준으로 넘겨받은 DataCollection이 참조(linked) 관계에 있는 상위 DataCollection 목록을 반환합니다.
		 * 넘겨받은 DataCollection이 응답모델에 여러 곳에 존재할 때 처음 만나는 객체를 기준으로 반환합니다.
		 * @param leaf 참조관계의 상위 DataCollection 목록을 조회할 DataCollection 객체.
		 */
		public getResponseLinkedHierarchy(leaf: data.DataCollection): data.DataCollection[] {
			let matrixDataModel: matrix.MatrixDataModel = this._getProtocolDataModel() as matrix.MatrixDataModel;
			if (!matrixDataModel) {
				return [];
			}

			let responseModel: matrix.ResponseMetaModel = matrixDataModel._getResponseMatrix();

			let colls: { linked: boolean, dataCtrl: (data.DataCollection | data.DataMap) }[] = [];
			this._findResponseLinkedHierarchy(leaf, responseModel, colls);

			let resultArr: data.DataCollection[] = [];

			while (true) {
				let item: { linked: boolean, dataCtrl: (data.DataCollection | data.DataMap) } = colls.pop();
				if (item == null || item.dataCtrl instanceof data.DataCollection == false) {
					break;
				}
				resultArr.unshift(item.dataCtrl as data.DataCollection);
				if (item.linked == false) {
					break;
				}
			}

			return resultArr;
		}

		private _findResponseLinkedHierarchy(leaf: data.DataCollection, responseModel: matrix.ResponseMetaModel, colls: { linked: boolean, dataCtrl: (data.DataCollection | data.DataMap) }[]): boolean {
			let dataControl = responseModel.dataControl as (data.DataCollection | data.DataMap);
			// linked 속성에 의한 참조 관계를 별도로 저장하여 leaf에서 parent로 가면서 linked가 끊어지는 지점까지 보전해야 함.
			let linked: boolean = responseModel.linked === true ? true : false;

			if (dataControl) {
				if (dataControl === leaf) {
					return true;
				}
				colls[colls.length] = { linked: linked, dataCtrl: dataControl };
			}

			let dataModel: number | string | matrix.ResponseDataModel = responseModel.data;
			if (dataModel) {
				let format: matrix.MetaModelFormat = responseModel.format;

				if (format == "object" || format == "array") {
					let childModel: matrix.ResponseDataModel = dataModel as matrix.ResponseDataModel;
					for (let attName in childModel) {
						let attSchema: matrix.ResponseMetaModel = childModel[attName];
						let finded: boolean = this._findResponseLinkedHierarchy(leaf, attSchema, colls);
						if (finded) {
							return true;
						}
					}
				}
			}
			if (dataControl) {
				colls.splice(colls.length - 1, 1);
			}
			return false;
		}

		/* AbstractSubmission methods overriding */

		/**
		 * 서브미션에 지정된 response data type을 반환합니다.
		 * @return response data type.
		 * @unsupported
		 */
		public override get responseType(): string {
			return this._getResponseType();
		}

		/**
		 * 서브미션에 지정된 response data type을 지정합니다.
		 * @param responsetype response data type.
		 * @unsupported
		 */
		public override set responseType(responsetype: string) {
			this._setResponseType(responsetype);
		}

		/**
		 * http에 content-type의 media-type의 값을 반환합니다.
		 * @return media-type.
		 * @unsupported
		 */
		public get mediaType(): string {
			return this._getMediaType();
		}

		/**
		 * http에 content-type의 media-type의 값을 지정합니다.
		 * @param mediatype media-type.
		 * @unsupported
		 */
		public set mediaType(mediatype: string) {
			this._setMediaType(mediatype);
		}

	}
}