namespace cpr.ufc {
	/**
	 * 특정 노드로부터 돔 트래버징을 시작합니다.
	 * @param element 돔 트래버징을 시작할 노드.
	 * @returns 돔 트래버저.
	 */
	export function _traverseFromElement(element: HTMLElement | SVGElement): DOMTraverser {
		return new _DOMTraverserImpl(element);
	}

	/**
	 * 특정 컨트롤의 렌더링 루트 노드로 부터 돔 트래버징을 시작합니다.
	 * @param control 대상 컨트롤.
	 * @param global 해당 컨트롤의 글로벌 영역 노드에서 탐색할 것인지 여부.
	 * @returns 돔 트래버저.
	 */
	export function _traverseFromControl(control: controls.UIControl, global = false): DOMTraverser {
		let nodeId = global
			? NodeUUIDMapper.INSTANCE._getGlobalControlNodeID(control)
			: NodeUUIDMapper.INSTANCE._getControlNodeID(control)
			;
		return new _DOMTraverserImpl(document.getElementById(nodeId));
	}

	export interface DOMTraverser {
		/**
		 * DOM 여행의 시작 HTMLElement를 변경하는 메소드.
		 * 
		 * @param element 여행을 시작할 HTMLElement. NotNull.
		 * @return element가 교체된 자기 자신을 리턴함.
		 */
		_setElement(element: HTMLElement): this;

		/**
		 * 주어진 Selector에 조건에 만족하는 본 Element를 포함한 가장 가까운 Parent Element를 찾는다.
		 * 
		 * @param selector 찾을 HTMLElement의 조건식. NotNull.
		 * @param root 부모 Element 검색 시 최대로 올라갈 수 있는 부모 Element. 없을 경우 최상위 Element(보통 html tag) 까지 검색한다. Nullable.
		 * @return 조건식을 만족하는 Element를 찾았을 경우 찾은 Element를 DOMTraverser의 시작 Element로 설정하고 자기 자신을 리턴. 찾지 못한 경우 null을 리턴. 
		 */
		_closest(selector: string, bounds?: HTMLElement): this;

		/**
		 * 주어진 Selector에 조건에 만족하는 가장 가까운 Parent Element를 찾는다.
		 * 
		 * @param selector 찾을 HTMLElement의 조건식. NotNull.
		 * @param root 부모 Element 검색 시 최대로 올라갈 수 있는 부모 Element. 없을 경우 최상위 Element(보통 html tag) 까지 검색. Nullable.
		 * @return 조건식을 만족하는 Element를 찾았을 경우 찾은 Element를 DOMTraverser의 시작 Element로 설정하고 자기 자신을 리턴. 찾지 못한 경우 null을 리턴. 
		 */
		_parent(selector?: string, bounds?: HTMLElement): this;

		/**
		 * 조건식을 만족하는 자신을 포함한 가장 가까운 자식 Element를 검색.
		 * 
		 * @param selector 찾을 HTMLElement의 조건식. NotNull.
		 * @return 조건식을 만족하는 Element를 찾았을 경우 찾은 Element를 DOMTraverser의 시작 Element로 설정하고 자기 자신을 리턴. 찾지 못한 경우 null을 리턴.
		 */
		_find(selector: string): this;

		/**
		 * 조건식을 만족하는 가장 가까운 자식 Element를 검색.
		 * 
		 * @param selector 찾을 HTMLElement의 조건식. NotNull.
		 * @return 조건식을 만족하는 Element를 찾았을 경우 찾은 Element를 DOMTraverser의 시작 Element로 설정하고 자기 자신을 리턴. 찾지 못한 경우 null을 리턴.
		 */
		_child(selector: string): this;


		/**
		 * 조건식을 만족하는 모든 자식 Element를 검색.
		 * 
		 * @param selector 찾을 HTMLElement의 조건식. NotNull.
		 * @return 조건식을 만족하는 모든 Element를 찾아 NodeList로 리턴.
		 */
		_children(selector: string): NodeList;

		_index(selector: string): number;

		/**
		 * DOMTraverser에 설정된 Element와 동일 수준의 이전 순서 Element를 검색.
		 * 
		 * @param selector 찾을 HTMLElement의 조건식. NotNull.
		 * @return 조건식을 만족하는 Element를 찾았을 경우 찾은 Element를 DOMTraverser의 시작 Element로 설정하고 자기 자신을 리턴. 찾지 못한 경우 null을 리턴.
		 */
		_previous(selector: string): this;

		/**
		 * DOMTraverser에 설정된 Element와 동일 수준의 다음 순서 Element를 검색.
		 * 
		 * @param selector 찾을 HTMLElement의 조건식. NotNull.
		 * @return 조건식을 만족하는 Element를 찾았을 경우 찾은 Element를 DOMTraverser의 시작 Element로 설정하고 자기 자신을 리턴. 찾지 못한 경우 null을 리턴함.
		 */
		_next(selector: string): this;

		/**
		 * 현재 선택된 HTMLElement에 Focus를 부여.
		 * HTMLElement의 focus() 메소드 호출.
		 * @return 자기 자신을 리턴함.
		 */
		_focus(options?: { preventScroll?: boolean }): this;

		/**
		 * 현재 선택된 HTMLElement에 attribute를 조회.
		 * HTMLElement의 getAttribute(...) 메소드 호출.
		 * 
		 * @param name 설정될 attribute의 name. NotNull.
		 * @return attribute의 value 또는 null.
		 */
		_getAttribute(name: string): string;

		/**
		 * 현재 선택된 Element를 리턴.
		 * 
		 * @return HTMLElement
		 */
		_getElement(): HTMLElement;

		/**
		 * DOMTraverser 인스턴스의 자원을 해제함.
		 * 참조하고 있는 HTMLElement의 참조 해제.
		 * @deprecated 불필요 함.
		 */
		dispose(): void;

		/**
		 * 현재 설정된 HTMLElement가 사용가능한지 여부를 검사하여 boolean 값으로 리턴.
		 * 
		 * @return HTMLElement가 존재할경우 true, 존재하지 않을 경우 false 리턴.
		 */
		_isAvailable(): boolean;
	}

	export namespace DOMTraverser {
		export function _isDOMTraverser(obj: object): obj is DOMTraverser {
			return obj instanceof _DOMTraverserImpl;
		}
	}

	/**
	 * HTML DOM Tree를 selector를 이용해 돌아다니는 Class.
	 * 클라이언트는 DOMTraverser 인스턴스를 생성하고 다양한 Selector 상/하위 Element에 접근.
	 * 상속 및 Overriding 불가.
	 * 
	 * DOMTraverser는 선택된 HTMLElement의 상/하 및 순서상 앞/뒤의 HTMLElement를 검색하기 위해 CSS Selector를 사용.
	 * CSS Selector는 DOMTraverser의 Instance에 selector라는 Parameter로 각 메소드 호출 시 사용.
	 * <ul>
	 * <li>CSS Selector 의 예)
	 * <ul>
	 * <li>DIV Element 검색 : "div"</li>
	 * <li>Element의 Class가 className인 Element 검색 : ".className"</li>
	 * <li>data-code Attribute를 가진 Element 검색 : "[data-code]"</li>
	 * <li>data-code Attribute의 값이 111 인 Element 검색 : "[data-code='111']"</li>
	 * </ul>
	 * </li>
	 * </ul>
	 * 
	 * @private
	 */
	class _DOMTraverserImpl implements DOMTraverser {
		private _element: HTMLElement | SVGElement;

		/**
		 * DOMTraverser 인스턴스를 생성하는 생성자.
		 * 
		 * @param element 여행을 시작할 HTMLElement. NotNull.
		 */
		constructor(element: HTMLElement | SVGElement) {
			this._element = element;
		}

		public _setElement(element: HTMLElement): this {
			this._element = element;

			return this;
		}

		public _closest(selector: string, root: HTMLElement = null): this {
			if (!this._isAvailable()) {
				return null;
			}

			for (let element: HTMLElement = this._element as HTMLElement;
				element != null;
				element = _getParentElement(element)) { // SVG는 IE에서 parentElement를 지원하지 않음
				// element = element.parentElement) {

				if (_matchesSelector(element, selector)) {
					this._element = element;
					return this;
				}

				if (root != null && element === root) {
					return null;
				}
			}
			return null;
		}

		public _parent(selector: string = null, root: HTMLElement = null): this {
			if (!this._isAvailable()) {
				return null;
			}

			if (selector == null) {
				this._element = _getParentElement(this._element);// SVG는 IE에서 parentElement를 지원하지 않음
				// this._element = this._element.parentElement;
				return this;
			}

			for (let element: HTMLElement = _getParentElement(this._element); // SVG는 IE에서 parentElement를 지원하지 않음
				element != null;
				element = _getParentElement(element)) {

				if (root != null && element === root) {
					return null;
				}

				if (_matchesSelector(element, selector)) {
					this._element = element;
					return this;
				}
			}

			return null;
		}

		public _find(selector: string): this {
			if (!this._isAvailable()) {
				return null;
			}

			return _matchesSelector(this._element, selector)
				? this
				: this._child(selector);
		}

		public _child(selector: string): this {
			if (!this._isAvailable()) {
				return null;
			}

			let element: HTMLElement = this._element.querySelector(selector) as HTMLElement;
			if (element) {
				this._element = element;
				return this;
			} else {
				return null;
			}
		}


		public _children(selector: string): NodeList {
			if (!this._isAvailable()) {
				return null;
			}

			let elements: NodeList = this._element.querySelectorAll(selector);
			return elements;
		}

		public _index(selector: string): number {
			if (!this._isAvailable()) {
				return -1;
			}

			let parent: HTMLElement = _getParentElement(this._element);

			let children: NodeList = new _DOMTraverserImpl(parent)._children(selector);
			let child: HTMLElement;
			for (let i = 0; i < children.length; i++) {
				child = <HTMLElement>children[i];
				if (this._element == child) {
					return i;
				}
			}
			return - 1;

		}

		public _previous(selector: string): this {
			if (!this._isAvailable()) {
				return null;
			}

			for (let element: HTMLElement = this._element.previousElementSibling as HTMLElement;
				element != null;
				element = element.previousElementSibling as HTMLElement) {

				if (_matchesSelector(element, selector)) {
					this._element = element as HTMLElement;
					return this;
				}
			}

			return null;
		}


		public _next(selector: string): this {
			if (!this._isAvailable()) {
				return null;
			}

			for (let element: HTMLElement = this._element.nextElementSibling as HTMLElement;
				element != null;
				element = element.nextElementSibling as HTMLElement) {

				if (_matchesSelector(element, selector)) {
					this._element = element as HTMLElement;
					return this;
				}
			}

			return null;
		}

		/**
		 * 현재 선택된 HTMLElement에 Focus를 부여.
		 * HTMLElement의 focus() 메소드 호출.
		 * @return 자기 자신을 리턴함.
		 */
		public _focus(options?: { preventScroll?: boolean }): this {
			if (!this._isAvailable()) {
				return null;
			}

			if (options && options.preventScroll) {
				if (this._element["setActive"]) { // IE
					this._element["setActive"]();
				} else {
					this._element.focus({ preventScroll: options.preventScroll });
				}
			} else {
				this._element.focus();
			}

			return this;
		}

		/**
		 * 현재 선택된 HTMLElement에 attribute를 조회.
		 * HTMLElement의 getAttribute(...) 메소드 호출.
		 * 
		 * @param name 설정될 attribute의 name. NotNull.
		 * @return attribute의 value 또는 null.
		 */
		public _getAttribute(name: string): string {
			if (!this._isAvailable()) {
				return null;
			}

			return this._element.getAttribute(name);
		}

		/**
		 * 현재 선택된 Element를 리턴.
		 * 
		 * @return HTMLElement
		 */
		public _getElement(): HTMLElement {
			return this._element as HTMLElement;
		}

		/**
		 * DOMTraverser 인스턴스의 자원을 해제함.
		 * 참조하고 있는 HTMLElement의 참조 해제.
		 * @deprecated 불필요 함.
		 */
		public dispose(): void {
			this._element = null;
		}

		/**
		 * 현재 설정된 HTMLElement가 사용가능한지 여부를 검사하여 boolean 값으로 리턴.
		 * 
		 * @return HTMLElement가 존재할경우 true, 존재하지 않을 경우 false 리턴.
		 */
		public _isAvailable(): boolean {
			return (this._element === undefined || this._element == null) == false;
		}
	}
}