/// <reference path="../../protocols/ProtocolDataModel.ts" />

namespace cpr.protocols.matrix {
	/**
	 * @private
	 */
	export class MatrixDataContext {
		private _dataControl: data.DataCollection | data.IDataRow | data.DataMap;

		constructor(dataControl: data.DataCollection | data.IDataRow | data.DataMap) {
			this._dataControl = dataControl;
		}

		public _getRowContext(): data.IDataRow {
			if (this._dataControl instanceof data.IDataRow) {
				return this._dataControl;
			} else {
				return null;
			}
		}

		public _getValue(path: string): any {
			if (!path || !this._dataControl) {
				return "";
			}

			let pos: { rowIndex: number, columnName: string } = this._parsePath(path);
			if (!pos) {
				return "";
			}
			if (pos.rowIndex != null && this._dataControl instanceof data.DataCollection) {
				let dataSet: data.DataCollection = this._dataControl as data.DataCollection;

				let columnHeader: data.header.Header = dataSet.getHeader(pos.columnName);
				let dataType: data.tabledata.DataType = columnHeader.getDataType();
				if (dataType === data.tabledata.DataType.DECIMAL) {
					return dataSet._getDecimal(pos.rowIndex, pos.columnName); // decimal
				} else {
					return dataSet.getValue(pos.rowIndex, pos.columnName); // number or string
				}
			}
			if (this._dataControl instanceof data.DataMap) {
				let dataMap: data.DataMap = this._dataControl as data.DataMap;
				let columnHeader: data.header.Header = dataMap.getHeader(pos.columnName);
				let dataType: data.tabledata.DataType = columnHeader.getDataType();
				if (dataType === data.tabledata.DataType.DECIMAL) {
					return dataMap._getDecimal(pos.columnName); // decimal
				} else {
					return dataMap.getValue(pos.columnName); // number or string
				}
			}
			if (this._dataControl instanceof data.IDataRow) {
				let dataRow: data.IDataRow = this._dataControl as data.IDataRow;
				let dataCollection: data.DataCollection = dataRow._getDataSet();
				let columnHeader: data.header.Header = dataCollection.getHeader(pos.columnName);
				let dataType: data.tabledata.DataType = columnHeader.getDataType();
				if (dataType === data.tabledata.DataType.DECIMAL) {
					let decimalData: foundation.DecimalType = dataRow._getDecimal(pos.columnName);
					if (decimalData == null) {
						return "";
					}
					return dataRow._getDecimal(pos.columnName);
				} else {
					return dataRow.getValue(pos.columnName);
				}
			}
			// TODO dataControl이 DataSet인데 rowIndex가 없는 경우 linked 처리
		}

		public _setValue(path: string, value: any): void {
			if (!path || !this._dataControl) {
				return;
			}
			let pos: { rowIndex: number, columnName: string } = this._parsePath(path);
			if (!pos) {
				return;
			}
			if (pos.rowIndex != null && this._dataControl instanceof data.DataCollection) {
				let dataSet: data.DataCollection = this._dataControl as data.DataCollection;
				dataSet.putValue(pos.rowIndex, pos.columnName, value);
			}
			if (this._dataControl instanceof data.DataMap) {
				let dataMap: data.DataMap = this._dataControl as data.DataMap;
				dataMap.putValue(pos.columnName, value);
			}
			if (this._dataControl instanceof data.IDataRow) {
				let dataRow: data.Row = this._dataControl as data.Row;
				dataRow.putValue(pos.columnName, value);
			}
			// TODO dataControl이 DataSet인데 rowIndex가 없는 경우 linked 처리
		}

		private _parsePath(path: string): { rowIndex: number, columnName: string } {
			if (!path || !this._dataControl) {
				return null;
			}
			var regexp = /^(\[([0-9]+)\])?@(.*)$/; // 2, 3 번 사용
			let matcher: RegExpExecArray = regexp.exec(path);
			let rowIndex: string = matcher[2];
			let columnName: string = matcher[3];
			if (!columnName) {
				return null;
			}

			return {
				rowIndex: rowIndex == null ? null : utils.Util.toNumber(rowIndex)
				, columnName: columnName
			}
		}
	}
}