/// <reference path="./URL.ts" />

namespace cpr.utils {
	let registry: { [key: string]: Logger } = {};

	type LogFunction = (...args: any[]) => void;

	type BindedLogFunctionInfo = {
		updator: (newLogFn: LogFunction) => void,
		bindedPrefixes: any[]
	}

	/**
	 * 로거 객체.
	 * @noinstance
	 */
	export class Logger {
		private _topic: string;
		private _activated: boolean;
		private _bindedLogFunctions: BindedLogFunctionInfo[] = [];
		private _actualLogger: { owner: any, fn: Function };

		/**
		 * 특정 주제에 대한 로거 객체를 얻습니다.
		 * @param topic 주제.
		 */
		static forTopic(topic: string) {
			if (typeof topic != "string") {
				throw new exceptions.IllegalArgumentException();
			}

			topic = topic.trim();
			if (!registry[topic]) {
				registry[topic] = new Logger(topic);
			}

			return registry[topic];
		}

		/**
		 * 
		 * @param topic 로그 토픽.
		 * @private
		 */
		constructor(topic: string) {
			this._topic = topic;
			this._updateLogFunction();
		}

		_updateLogFunction() {
			this._actualLogger = {
				owner: this,
				fn: function () { }
			}
			if (this.isActivated()) {
				if (window["___syslog"]) {
					this._actualLogger = {
						owner: window,
						fn: window["___syslog"]
					};
				} else if (console && console.log) {
					this._actualLogger = {
						owner: console,
						fn: console.log
					}
				}
			}

			this.log = this._buildLogFunction();

			// 변경된 로거 디스패치
			this._bindedLogFunctions.forEach(info => {
				info.updator(this._buildLogFunction());
			});
		}

		_buildLogFunction(...prefixes: any[]): LogFunction {
			return this._actualLogger.fn.bind(this._actualLogger.owner, this._topic, ...prefixes);
		}

		/**
		 * 로그를 작성합니다.
		 * @param args 로그 메시지
		 */
		log(...args: any[]): void { }

		/**
		 * 로거를 강제로 활성화 합니다.
		 */
		activate() {
			if (this.isActivated()) {
				return;
			}
			this._activated = true;
			this._updateLogFunction();
		}

		/**
		 * 로거를 강제로 비활성화 합니다.
		 */
		deactivate() {
			if (!this.isActivated()) {
				return;
			}
			this._activated = false;
			this._updateLogFunction();
		}

		/**
		 * 로거의 활성화 여부를 얻습니다.
		 */
		isActivated() {
			if (this._activated === undefined) {
				let url = new utils.URL(location.href);
				let topicExp = (url.query["x-debug"] || "") as string;
				let topics = topicExp.split(/[\s,]+/g);
				this._activated = topics.indexOf(this._topic) !== -1 || topics.indexOf("all") !== -1;
			}
			return this._activated;
		}

		_createBindedLoggerFunction(options: {
			prefixes?: any[],
			updator: (logFn: LogFunction) => void
		}): LogFunction {
			let prefixes = options.prefixes || [];
			this._bindedLogFunctions.push({
				updator: options.updator,
				bindedPrefixes: prefixes
			});
			return this._buildLogFunction(...prefixes);
		}

	}
}

/**
 * 로거 객체를 얻습니다.
 * 
 * @param topic 로깅 주제.
 * 
 * 아래 구문은 url의 쿼리중 x-debug 배열 값에 `test` 또는 `all` 이 포함된 경우만 출력됩니다.
 *  
 * 예: http://test.com/?x-debug=test 
 * ```
 * logger("test").log("Hello World");
 * ```
 */
function logger(topic: string = "default") {
	return cpr.utils.Logger.forTopic(topic);
}