	/** 
	 * 아이템을 기준으로 익스프레션을 수행할 수 있는 문맥.
	 * @private
	 */
	export class ItemContext extends cpr.bind.DataBindContext implements expression.EvaluationContext {
		private _item: cpr.controls.Item;
		private _control?: controls.UIControl;
		private _delegate: any;

		constructor(item: cpr.controls.Item, control: controls.UIControl = null) {
			super();
			this._item = item;
			this._control = control;
		}

		_get(columnName: string) {
			if (!this._item || !this._item.row) {
				return null;
			}
			let dataControl = this._item.row._getDataSet();
			if (!dataControl) {
				return null
			}

			if (dataControl.isExistColumn(columnName)) {
				return this._item.row.getValue(columnName);
			} else {
				return null;
			}
		}

		_setValue(columnName: string, newValue: any) {
			if (!this._item || !this._item.row) {
				return;
			}
			let dataControl = this._item.row._getDataSet();
			if (!dataControl) {
				return;
			}

			if (dataControl.isExistColumn(columnName)) {
				this._item.row.setValue(columnName, newValue);
			}
		}

		_getExpressionOnlyProperty(name: string) {
			switch (name) {
				case "self": {
					if (this._delegate) {
						return this._delegate;
					}
				}
				default: return undefined;
			}
		}

		_getExpressionDelegates(): any[] {
			if (this._delegate) {
				return [this._item, this._control, this._delegate];
			}
			else {
				return [this._item, this._control];
			}
		}

		_getExpressionIDLookupProvider() {
			if (this._control) {
				return this._control.getAppInstance();
			} else {
				return undefined;
			}
		}

		override _cloneWithExpressionDelegate(delegate: any) {
			let result = new ItemContext(this._item, this._control);
			result._delegate = delegate;

			return result;
		}

		_isAvailable(): boolean {
			return this.disposed === false && this._item != null;
		}

		/**
		 * 아이템 문맥 바인딩을 해제합니다.
		 * @private
		 */
		public dispose(): void {
			this._delegate = null;
			this._item = null;
			this._control = null;

			super.dispose();
		}
	}
