
namespace cpr.controls.gridpart {

	/**
	 * 익스포트 옵션인 rowgroupStyleHandler의 parameter.
	 */
	export enum VLOC_REGION {
		HEADER = "header",
		DETAIL = "detail",
		FOOTER = "footer",
		GHEADER = "gheader",
		GFOOTER = "gfooter"
	}

	/**
	 * 그리드 익스포트를 지원하는 Util.
	 * <br>
	 * <applyFormat Option><br>
	 * Export시 포맷을 적용시킬 지 여부. default true. <br>
	 * applyFormat=true이고 컨트롤이 있으면, 컨트롤의 포맷이 지정됩니다.<br>
	 * UDC : 해당 UDC의 getText() 값이 지정됩니다. (없으면 value값 대체)<br>
	 * DateInput, MaskEditor, Output(dataType=string, dataType=date) : 해당 컨트롤의 text 값. (포맷이 포함된 값이 나옵니다.)<br>
	 * NumberEditor, Output(dataType=number) : 해당 컨트롤의 값이 number형으로 지정되어 반환되며, format이 서식으로 지정됩니다.<br>
	 * 
	 * applyFormat=false이거나 지정된 컨트롤이 없는 경우 연결된 데이터셋의 값이 지정됩니다.<br>
	 * 연결된 데이터셋의 데이터타입이 decimalType이거나 number타입인 경우 number형 데이터로 지정됩니다.<br>
	 * (number 데이터 타입을 익스포트하기 위해서는 해당 옵션을 false로 주어야 합니다.)
	 * 
	 * [applyFormat=true](default)
	 * 1. 값 : 컨트롤 text > 연결된 columnName의 값
	 * 2. 데이터타입과 포맷 
	 * 		- [useFormat=true](default) : 넘버에디터, 아웃풋(number)의 경우 포맷이 따로 format 속성으로 적용된 후 number형 데이터 반환. (ex. 값 : 1234 / format: "#,###")
	 * 		- [useFormat=false] : 컨트롤의 포맷이 지정된 데이터(string) 반환. (ex. "1,234")
	 * 
	 * [applyFormat=false]
	 * 1. 값 : 컨트롤 value > 연결된 columnName의 값
	 * 2. 데이터타입
	 * 		- 컨트롤 value로 적용된 경우 : 넘버에디터, 아웃풋(number)은 number형 데이터 반환. 나머지는 string형 데이터 반환.
	 * 		- 데이터셋 값으로 적용된 경우 : 데이터타입에 맞게 반환. (string → string / number,decimal → number / expression → 결과값에 따라 적용)
	 * @private
	 */
	export class GridExportUtil {
		private _grid: Grid;

		private _rowIndex: number;
		private _visibleColumnLayout: GridColumnProp[];
		private _headerColumns: { style: utils.CellStyle[], cellProps: GridHeaderCellProp[] };
		private _detailColumns: { style: utils.CellStyle[], cellProps: GridDetailCellProp[] };
		private _footerColumns: { style: utils.CellStyle[], cellProps: GridFooterCellProp[] };

		private _rowGroupColumns: {
			[condition: string]: {
				gheader?: { style: utils.CellStyle[], cellProps: GridFooterCellProp[] },
				gfooter?: { style: utils.CellStyle[], cellProps: GridFooterCellProp[] }
			}
		};
		private _suppressInfo: {
			[loc: string]: {
				rowHeight: number[],
				data: layout.SuppressCellInfo[]
			}[]
		} = {};

		private _exportOption: utils.ExportOption;
		/**
		 * applyClassStyle 옵션 사용시 class 스타일 해석에 사용합니다.
		 */
		private _classStyleResolver: GridClassStyleResolver;


		constructor(grid: Grid) {
			this._grid = grid;
		}


		/**
		 * 멀티 시트 익스포트시 여러 그리드의 데이터를 합쳐서 하나의 멀티 시트 익스포트 데이터로 반환합니다.
		 * @param exportDatas 그리드 데이터 배열.
		 * @return 여러 그리드 데이터가 합쳐진 하나의 익스포트 데이터.
		 */
		public static merge(exportDatas: utils.ExportData[]): utils.MultiSheetExportData {
			let sheets: {
				name: string,
				freezepane?: { colsplit: number, rowsplit: number },
				cols: GridColumnConfig[],
				rowgroups: utils.RowGroup[]
			}[] = [];
			exportDatas.forEach((exportData: utils.ExportData) => {
				sheets[sheets.length] = {
					name: exportData.name,
					cols: exportData.cols,
					freezepane: exportData["freezepane"],
					rowgroups: exportData.rowgroups
				};
			});

			return {
				metadata: { password: null, printPageOrientation: null, wrapLineBreak: false },
				sheets: sheets
			};
		}

		public static _convertToTSV(exportData: utils.ExportData): string {
			if (!exportData) {
				return "";
			}
			let txtData: string[] = [];
			let rowGroups: utils.RowGroup[] = exportData.rowgroups;
			for (let idx: number = 0; idx < rowGroups.length; idx++) {
				let rowGroup: utils.RowGroup = rowGroups[idx];
				let rowDatas: utils.CellData[][] = rowGroup.data;

				for (let jdx: number = 0; jdx < rowDatas.length; jdx++) {
					let rowData: utils.CellData[] = rowDatas[jdx];
					let firstCell: boolean = true;
					for (let kdx: number = 0; kdx < rowData.length; kdx++) {
						if (firstCell === true) {
							firstCell = false;
						} else {
							txtData[txtData.length] = "\t";
						}
						let cell: utils.CellData = rowData[kdx];

						if (cell["value"]) {
							txtData[txtData.length] = GridExportUtil._encodeTSV(utils.Util.toString(cell["value"]));
						} else {
							txtData[txtData.length] = GridExportUtil._encodeTSV(utils.Util.toString(cell));
						}
					}
					txtData[txtData.length] = "\n";
				}
			}

			return txtData.join("");
		}

		private static _encodeTSV(str: string): string {
			if (str == null) {
				return "";
			}
			let encoded: string = "";
			let leng: number = str.length;
			let ch = '\0';
			for (let idx: number = 0; idx < leng; idx++) {
				ch = str.charAt(idx);
				if (ch == '\t' || ch == '\n' || ch == '\r' || ch == '\b' || ch == '\\') {
					encoded += '\\'; // escape character
					if (ch == '\t') {
						encoded += 't';
					} else if (ch == '\n') {
						encoded += 'n';
					} else if (ch == '\r') {
						encoded += 'r';
					} else if (ch == '\b') {
						encoded += 'b';
					} else {
						encoded += '\\';
					}
				} else {
					encoded += ch;
				}
			}

			return encoded;
		}

		private _clear(): void {
			// 이전 익스포트에서 사용한 프로브 요소가 남아있지 않도록 정리합니다.
			this._disposeClassStyleResolver();

			this._rowIndex = 0;
			this._visibleColumnLayout = null;
			this._headerColumns = null;
			this._detailColumns = null;
			this._footerColumns = null;
			this._rowGroupColumns = null;
			this._exportOption = null;

			this._visibleColumnLayout = [];
			this._headerColumns = { style: [], cellProps: [] };
			this._detailColumns = { style: [], cellProps: [] };
			this._footerColumns = { style: [], cellProps: [] };
			this._rowGroupColumns = {};
		}

		private _setOptions(option: utils.ExportOption) {
			this._exportOption = { exceptStyle: true, applyFormat: true, useFormat: true, freezeHeader: false, applySuppress: false, reduce: false, applyClassStyle: false };
			if (option.hasOwnProperty("exceptStyle")) {
				this._exportOption.exceptStyle = option["exceptStyle"];
			}
			if (option.hasOwnProperty("applyClassStyle")) {
				this._exportOption.applyClassStyle = option["applyClassStyle"];
			}
			if (option.hasOwnProperty("applyFormat")) {
				this._exportOption.applyFormat = option["applyFormat"];
			}
			if (option.hasOwnProperty("useFormat")) {
				this._exportOption.useFormat = option["useFormat"];
			}
			if (option.hasOwnProperty("freezeHeader")) {
				this._exportOption.freezeHeader = option["freezeHeader"];
			}
			if (option.hasOwnProperty("applySuppress")) {
				this._exportOption.applySuppress = option["applySuppress"];
			}
			if (option.hasOwnProperty("reduce")) {
				this._exportOption.reduce = option["reduce"];
			}

			if (option.hasOwnProperty("rowDataHandler")) {
				this._exportOption.rowDataHandler = option["rowDataHandler"];
			}
			if (option.hasOwnProperty("rowgroupStyleHandler")) {
				this._exportOption.rowgroupStyleHandler = option["rowgroupStyleHandler"];
			}
			if (option.hasOwnProperty("excludeCellIndex") || option.hasOwnProperty("excludeCols")) {
				this._exportOption.excludeCellIndex = _.union(option["excludeCellIndex"], option["excludeCols"]);
			}
			if (option.hasOwnProperty("excludeColIndex")) {
				this._exportOption.excludeColIndex = option["excludeColIndex"];
			}

			if (this._exportOption.applySuppress == true) {
				this._initSuppressModel();
			} else {
				if (option.hasOwnProperty("rows")) {
					this._exportOption.rows = option["rows"];
				}
			}
		}

		private _init(option: utils.ExportOption) {
			this._clear();
			this._setOptions(option);
			let context: GridContext = this._grid.context;

			/* column info */
			let invisibleColIndices: number[] = [];
			let columnLayout: GridColumnProp[] = [];
			let leftLayout: GridRegionLayout = context.getHeaderLayout(GRIDREGION.LEFT);
			let centerLayout: GridRegionLayout = context.getHeaderLayout(GRIDREGION.CENTER);
			let rightLayout: GridRegionLayout = context.getHeaderLayout(GRIDREGION.RIGHT);
			if (leftLayout != null) {
				columnLayout = columnLayout.concat(leftLayout.columnLayout);
			}
			if (centerLayout != null) {
				columnLayout = columnLayout.concat(centerLayout.columnLayout);
			}
			if (rightLayout != null) {
				columnLayout = columnLayout.concat(rightLayout.columnLayout);
			}

			if (this._exportOption.hasOwnProperty("excludeCellIndex") || this._exportOption.hasOwnProperty("excludeColIndex")) {
				if (this._exportOption.hasOwnProperty("excludeCellIndex")) {
					let excludeCellIndices: number[] = this._exportOption.excludeCellIndex;
					invisibleColIndices = _.union(invisibleColIndices, this._getInvisibleIndices(excludeCellIndices));
				}
				if (this._exportOption.hasOwnProperty("excludeColIndex")) {
					invisibleColIndices = _.union(invisibleColIndices, this._exportOption.excludeColIndex);
				}
				columnLayout.forEach((columnConfig: GridColumnProp, index: number) => {
					if (invisibleColIndices.indexOf(index) == -1) {
						this._visibleColumnLayout.push({ width: columnConfig.width });
					}
				});
			} else {
				columnLayout.forEach((columnConfig: GridColumnProp, index: number) => {
					if (columnConfig["visible"] != false) {
						this._visibleColumnLayout.push({ width: columnConfig.width });
					} else {
						invisibleColIndices[invisibleColIndices.length] = index;
					}
				});
			}
			invisibleColIndices = invisibleColIndices.sort(function (a, b) {
				return a - b;
			});

			if (context.getHeader() != null) { // header
				this._setBandStyle(context.getHeader(), invisibleColIndices, this._exportOption, this._headerColumns);
			}

			if (context.getDetail() != null) { // detail
				this._setBandStyle(context.getDetail(), invisibleColIndices, this._exportOption, this._detailColumns, true);
			}

			if (context.getFooter() != null) { // footer
				this._setBandStyle(context.getFooter(), invisibleColIndices, this._exportOption, this._footerColumns);
			}

			let rowGroups: { [groupCondition: string]: { gheader?: GridRowGroupBandConfig, gfooter?: GridRowGroupBandConfig } } = this._getGridRowGroups();
			if (rowGroups != null) {
				let keys: string[] = Object.keys(rowGroups);
				keys.forEach((key: string) => {
					let rowGroup: { gheader?: GridRowGroupBandConfig, gfooter?: GridRowGroupBandConfig } = rowGroups[key];
					this._rowGroupColumns[key] = {};
					if (rowGroup.gheader != null) {
						this._rowGroupColumns[key]["gheader"] = { style: [], cellProps: [] };
						this._setGroupingRowStyle(rowGroup.gheader, invisibleColIndices, this._exportOption, this._rowGroupColumns[key]["gheader"]);
					}
					if (rowGroup.gfooter != null) {
						this._rowGroupColumns[key]["gfooter"] = { style: [], cellProps: [] };
						this._setGroupingRowStyle(rowGroup.gfooter, invisibleColIndices, this._exportOption, this._rowGroupColumns[key]["gfooter"]);
					}
				});
			}
		}

		private _setBandStyle(bandConfig: (GridHeaderBandConfig | GridDetailBandConfig | GridFooterBandConfig),
			invisibleIndices: number[],
			option: utils.ExportOption,
			settingObject: { style: utils.CellStyle[], cellProps: GridCellProp[] },
			isDetail?: boolean): void {

			let dataControl: data.DataCollection = this._grid.dataSet;
			let cellProps: GridCellProp[] = bandConfig.cellProp;
			let cellCount: number = cellProps.length;
			if (cellCount == 0) {
				return;
			}
			// 정렬 우선순위 : rowIndex, colIndex
			cellProps.sort(GridUtil._rowFirstSort);

			let autoRowHeight: string = "none"
			let checkCellIndex: number[] = [];
			if (isDetail === true) {
				autoRowHeight = this._grid.autoRowHeight;
				if (autoRowHeight != "none" && autoRowHeight != "all") {
					autoRowHeight.split(",").forEach((cellIndex: string) => {
						checkCellIndex[checkCellIndex.length] = Number(cellIndex);
					});
				}
			}


			for (let cellIdx = (cellCount - 1); cellIdx >= 0; cellIdx--) {
				let cellProp: GridCellProp = cellProps[cellIdx]; //bandConfig.getColumn(cellIdx);
				let colIndex: number = Number(cellProp.constraint.colIndex);
				let colSpan: number = Number(cellProp.constraint.colSpan);
				let control: GridUIControl = cellProp.configuration.control;

				for (let ci = (invisibleIndices.length - 1); ci >= 0; ci--) {
					if (colIndex <= invisibleIndices[ci] && (colIndex + colSpan - 1) >= invisibleIndices[ci]) {
						if (colIndex == invisibleIndices[ci]) {
							colSpan -= 1;
							if (colSpan == 0) {
								// colSpan이 1이고, 해당 컬럼이 invisible 인 경우
								break;
							}
						} else {
							colSpan -= 1;
						}
					} else if (colIndex > invisibleIndices[ci]) {
						colIndex -= 1;
					}
				}

				if (colSpan > 0) {
					var cellType: string = "string";
					if (isDetail && (cellProp.configuration as config.GridDetailCellConfigurator).columnType == "rowindex") {
						cellType = "number";
					} else if (option.applyFormat == false) {
						// detail : 바인딩된 데이터셋 컬럼의 데이터타입 기준
						// footer : expression result값 데이터형 기준
						// header : text는 무조건 string형 (현재 number형 설정 못함.)
						if (cellProp.configuration instanceof config.GridDetailCellConfigurator) {
							let header: data.header.Header = this._grid.dataSet.getHeader(cellProp.configuration["columnName"]);
							if (header != null &&
								(header.getDataType() == data.tabledata.DataType.NUMBER || header.getDataType() == data.tabledata.DataType.DECIMAL)) {
								cellType = "number";
							}
						} else if (cellProp.configuration instanceof config.GridFooterCellConfigurator) {
							if (cellProp.configuration.expr) {
								let result: (string | number | ufc.StyledString) = GridUtil._getDataExprResult(cellProp.configuration.expr, dataControl);
								let cellValue: (string | number) = (result instanceof ufc.StyledString) ? ufc.StyledString._asString(result) : result;
								// 컨트롤의 text는 무조건 string이기 때문에 처리에서 제외
								if (typeof (cellValue) == "number") {
									cellType = "number";
								}
							}
						}
					}

					let cellInfo: utils.CellStyle = {
						type: cellType,
						rowindex: cellProp.constraint.rowIndex,
						rowspan: cellProp.constraint.rowSpan,
						colindex: colIndex,
						colspan: colSpan,
						cellIndex: cellProp.constraint.cellIndex
					};

					if (isDetail && (cellProp.configuration as config.GridDetailCellConfigurator).columnName != null) {
						cellInfo["columnName"] = (cellProp.configuration as config.GridDetailCellConfigurator).columnName;
					}

					// 스타일을 포함하는 경우 (exceptStyle==false)
					if (option.exceptStyle == false) {
						// 바인딩되지 않은 class의 스타일은 행마다 달라지지 않으므로 셀별 스타일 대신 공통 스타일에 담습니다.
						// 인라인 스타일을 class 스타일 뒤에 병합하여 렌더링과 동일하게 인라인이 우선합니다.
						let classStyles = this._getStaticClassStyles(cellProp.configuration);
						let style = _mergeObject(classStyles.cell, cellProp.configuration.style._getCSS(false));
						if (control) {
							let controlStyle = (control.type == "button") ? { "text-align": "center" } : {}; // button 기본 정렬 추가
							style = _mergeObject(controlStyle, classStyles.cell, cellProp.configuration.style._getCSS(false),
								classStyles.control, control.style._getCSS(false));
						}
						cellInfo.style = style;
					}

					// 데이터타입만 지정하는 경우 (applyFormat==false)
					// 포맷을 지정하는 경우 (applyFormat==true, useFormat==true)
					if (option.applyFormat == false) {
						if (control != null && (control.type == "numbereditor" || (control.type == "output" && (control as Output).dataType == "number"))) {
							cellInfo.type = "number";
						}
					} else if (option.applyFormat == true && option.useFormat == true) {
						if (control != null && (control.type == "numbereditor" || (control.type == "output" && (control as Output).dataType == "number"))) {
							cellInfo.format = control["format"];
							cellInfo.type = "number";
						}
					}

					// 자동높이를 지원하는 경우
					if (autoRowHeight == "all" || checkCellIndex.indexOf(cellProp.constraint.cellIndex) != -1) {
						cellInfo.autorowheight = true;
					}

					// formula를 설정한 경우
					if (utils.Util.isNullOrEmpty(cellProp.configuration.formula) == false) {
						cellInfo.type = "formula";
						cellInfo.formula = cellProp.configuration.formula;
					}

					settingObject.style.splice(0, 0, cellInfo);
					settingObject.cellProps.splice(0, 0, cellProp);
					cellInfo = null;
				}
			}
		}

		public _getData(option?: boolean | utils.ExportOption): utils.ExportData {
			let exportOption: utils.ExportOption = null;
			if (option == null) {
				exportOption = {};
			} else if (typeof (option) == "boolean") {
				exportOption = { exceptStyle: option };
			} else {
				exportOption = option;
			}

			this._grid._keepContentDataRowIndex();

			this._init(exportOption);

			let context: GridContext = this._grid.context;
			let rowgroups: utils.RowGroup[] = [];

			/* rowgroups */
			if (context.getHeader() != null) { // header
				rowgroups.push(this._createHeader());
			}

			if (context.getDetail() != null) { // detail
				// 전체 행 suppress 결과 세팅하기
				this._grid._keepContentDataRowIndex(); // grouping 정보가 footer에 영향을 미치지 않도록 내부 설정이 필요함.
				if (context._isGrouping() == true && this._exportOption.rows == null) {
					rowgroups = rowgroups.concat(this._createGroupingDetail());
				} else {
					rowgroups.push(this._createDetail());
				}
				this._grid._restoreContentDataRowIndex();
			}

			if (context.getFooter() != null) { // footer
				rowgroups.push(this._createFooter());
			}

			let exportData: utils.ExportData = {
				metadata: { password: null, printPageOrientation: null, wrapLineBreak: false },
				name: null,
				cols: this._visibleColumnLayout.map((it: GridColumnProp) => { return { "width": it.width + "px" } }),
				rowgroups: rowgroups
			};

			if (exportOption.freezeHeader === true) {
				let headerConfig: GridHeaderBandConfig = context.getHeader();
				if (headerConfig) {
					let headerRows: {
						rowIndex: number;
						height: number;
					}[] = headerConfig.rows;
					if (headerRows) {
						exportData["freezepane"] = { colsplit: 0, rowsplit: headerRows.length };
					}
				}
			}

			this._grid._restoreContentDataRowIndex();
			this._disposeClassStyleResolver();

			return exportData;
		}

		public _forEachOfGridCells(func: (cellInfos: GridCellInfo[]) => void): void {
			this._grid._keepContentDataRowIndex();
			utils.tryCatch({
				do: () => this._doForEachOfGridCells(func),
				finally: () => this._grid._restoreContentDataRowIndex()
			});
		}
		private _doForEachOfGridCells(func: (cellInfos: GridCellInfo[]) => void): void {
			this._init({ useFormat: false });
			let context: GridContext = this._grid.context;
			let dataset: data.DataCollection = this._grid.dataSet;
			let cellInfos: GridCellInfo[] = [];

			// header
			if (context.getHeader() != null) {
				this._headerColumns.cellProps.forEach((cellProp: GridHeaderCellProp) => {
					let gridCellInfo: GridCellInfo = this._newLayoutProp(cellProp);
					gridCellInfo.region = GRIDREGION.HEADER;
					gridCellInfo.dsRowIndex = -1;
					gridCellInfo.columnType = cellProp.configuration.columnType;
					gridCellInfo.columnName = cellProp.configuration.targetColumnName;
					gridCellInfo.ctrl = cellProp.configuration.control;
					gridCellInfo.value = ufc.StyledString._asString(cellProp.configuration.text);
					if (gridCellInfo.ctrl) {
						gridCellInfo.text = utils.Util.toString(this._getControlText(gridCellInfo.ctrl as GridUIControl, null, gridCellInfo.value));
					} else {
						gridCellInfo.text = gridCellInfo.value;
					}
					cellInfos[cellInfos.length] = gridCellInfo;
				});
				func(cellInfos);
				cellInfos.splice(0);
			}
			// detail
			if (context.getDetail() != null) {
				if (context._isGrouping()) {
					let virtualRows: provider.VirtualRow[] = this._grid._getVirtualRows();
					let rowGroupConfigs: { [groupCondition: string]: { gheader?: GridRowGroupBandConfig, gfooter?: GridRowGroupBandConfig } } = this._getGridRowGroups();

					let rowCount: number = virtualRows.length;
					for (let rowIndex: number = 0; rowIndex < rowCount; rowIndex++) {
						let virtualRow: provider.VirtualRow = virtualRows[rowIndex];
						switch (virtualRow.type) {
							case provider.VROWTYPE.GHEADER: {
								this._forEachOfGroupRowCells(GRIDREGION.GHEADER, virtualRow, rowIndex, rowGroupConfigs[virtualRow.condition].gheader, cellInfos);
								break;
							}
							case provider.VROWTYPE.GFOOTER: {
								this._forEachOfGroupRowCells(GRIDREGION.GFOOTER, virtualRow, rowIndex, rowGroupConfigs[virtualRow.condition].gfooter, cellInfos);
								break;
							}
							default: {
								let gridRow: provider.GridRow = virtualRow.rowdata as provider.GridRow;
								this._forEachOfDetailRowCells(gridRow.getIndex(), cellInfos);
							}
						}
						func(cellInfos);
						cellInfos.splice(0);
					}

				} else {
					let rowCount: number = this._grid.rowCount;
					for (let rowIndex: number = 0; rowIndex < rowCount; rowIndex++) {
						this._forEachOfDetailRowCells(rowIndex, cellInfos);
						func(cellInfos);
						cellInfos.splice(0);
					}
				}
			}
			// footer
			if (context.getFooter() != null) {
				this._footerColumns.cellProps.forEach((cellProp: GridFooterCellProp) => {
					let gridCellInfo: GridCellInfo = this._newLayoutProp(cellProp);
					gridCellInfo.region = GRIDREGION.FOOTER;
					gridCellInfo.dsRowIndex = -1;
					gridCellInfo.columnType = null;
					gridCellInfo.columnName = null;
					gridCellInfo.ctrl = cellProp.configuration.control;
					let result: (string | number | ufc.StyledString) = GridUtil._getDataExprResult(cellProp.configuration.expr, dataset);
					result = (result instanceof ufc.StyledString) ? ufc.StyledString._asString(result) : result;
					gridCellInfo.value = (cellProp.configuration.expr != null) ? result : "";
					if (gridCellInfo.ctrl) {
						gridCellInfo.text = utils.Util.toString(this._getControlText(gridCellInfo.ctrl as GridUIControl, null, gridCellInfo.value));
					} else {
						gridCellInfo.text = utils.Util.toString(gridCellInfo.value);
					}
					cellInfos[cellInfos.length] = gridCellInfo;
				});
				func(cellInfos);
				cellInfos.splice(0);
			}
		}
		private _newLayoutProp(cellProp: GridCellProp): GridCellInfo {
			let gridCellInfo: GridCellInfo = {
				region: null, dsRowIndex: null,
				cellIndex: null, rowIndex: null, colIndex: null, rowSpan: null, colSpan: null,
				columnType: null, columnName: null, value: null, text: null, ctrl: null
			};
			gridCellInfo.cellIndex = cellProp.constraint.cellIndex;
			gridCellInfo.rowIndex = cellProp.constraint.rowIndex;
			gridCellInfo.colIndex = cellProp.constraint.colIndex;
			gridCellInfo.rowSpan = cellProp.constraint.rowSpan;
			gridCellInfo.colSpan = cellProp.constraint.colSpan;

			return gridCellInfo;
		}
		private _forEachOfDetailRowCells(rowIndex: number, cellInfos: GridCellInfo[]): void {
			this._grid._setContentDataRowIndex(rowIndex, -1);

			this._detailColumns.cellProps.forEach((cellProp: GridDetailCellProp) => {
				let gridCellInfo: GridCellInfo = this._newLayoutProp(cellProp);
				gridCellInfo.region = GRIDREGION.MIDDLE;
				gridCellInfo.dsRowIndex = rowIndex;
				gridCellInfo.columnType = cellProp.configuration.columnType;
				gridCellInfo.columnName = cellProp.configuration.columnName;
				gridCellInfo.ctrl = cellProp.configuration.control;

				switch (gridCellInfo.columnType) {
					case "rowindex": {
						gridCellInfo.value = rowIndex + 1;
						gridCellInfo.text = utils.Util.toString(gridCellInfo.value);
						break;
					}
					case "checkbox": {
						gridCellInfo.value = this._grid.isCheckedRow(rowIndex) ? "Y" : "N";
						gridCellInfo.text = gridCellInfo.value;
						break;
					}
					case "radio": {
						gridCellInfo.value = this._grid.isRadioSelected(rowIndex) ? "Y" : "N";
						gridCellInfo.text = gridCellInfo.value;
						break;
					}
					default: {
						if (gridCellInfo.columnName) {
							gridCellInfo.value = this._grid.dataProvider.getValue(rowIndex, gridCellInfo.columnName);
						} else {
							gridCellInfo.value = null;
						}
						if (gridCellInfo.ctrl) {
							gridCellInfo.text = utils.Util.toString(this._getControlText(gridCellInfo.ctrl as GridUIControl, null, gridCellInfo.value));
						} else {
							gridCellInfo.text = utils.Util.toString(gridCellInfo.value);
						}
					}
				}
				cellInfos[cellInfos.length] = gridCellInfo;
			});
		}
		private _forEachOfGroupRowCells(region: GRIDREGION, virtualRow: provider.VirtualRow, rowIndex: number, rowGroupConfig: GridRowGroupBandConfig, cellInfos: GridCellInfo[]): void {
			rowGroupConfig.cellProp.sort(GridUtil._rowFirstSort);

			if (virtualRow.dsindex >= 0) {
				this._grid._setContentDataRowIndex(virtualRow.dsindex, -1);
			} else {
				this._grid._setContentDataRowIndex(-1, rowIndex);
			}

			rowGroupConfig.cellProp.forEach((cellProp: GridFooterCellProp) => {
				let gridCellInfo: GridCellInfo = this._newLayoutProp(cellProp);
				gridCellInfo.region = region;
				gridCellInfo.dsRowIndex = -1;
				gridCellInfo.columnType = null;
				gridCellInfo.columnName = null;
				gridCellInfo.ctrl = cellProp.configuration.control;
				let result: (string | number | ufc.StyledString) = GridUtil._getRowGroupExprValue(cellProp, virtualRow.rowdata as provider.GridRowGroup);
				gridCellInfo.value = (result instanceof ufc.StyledString) ? ufc.StyledString._asString(result) : result;
				if (gridCellInfo.ctrl) {
					gridCellInfo.text = utils.Util.toString(this._getControlText(gridCellInfo.ctrl as GridUIControl, null, gridCellInfo.value));
				} else {
					gridCellInfo.text = utils.Util.toString(gridCellInfo.value);
				}

				cellInfos[cellInfos.length] = gridCellInfo;
			});
		}

		/**
		 * header영역의 style과 data 정보를 생성하여 반환합니다.
		 */
		private _createHeader(): utils.RowGroup {
			let datas: utils.CellData[] = [];
			this._headerColumns.cellProps.forEach((cellProp: GridHeaderCellProp, index: number) => {
				let cellValue: (string | number) = null;
				let applyFormat: boolean = this._exportOption.applyFormat;
				let cellText: string = ufc.StyledString._asString(cellProp.configuration.text);
				if (cellProp.configuration.control) {
					if (applyFormat == true) {
						cellValue = this._getControlText(cellProp.configuration.control, null, cellText);
					} else {
						cellValue = this._getControlValue(cellProp.configuration.control, null, cellText);
					}

				} else {
					cellValue = (cellText != null) ? cellText : "";
					// header text의 경우 무조건 string형으로 반환되기 때문에 number형으로 형변환 필요
					if (applyFormat == false && cellValue != "" && isNaN(Number(cellValue)) == false) {
						cellValue = Number(cellValue);
						// formula가 적용된 경우 formula 우선
						if (this._headerColumns.style[index].type != "formula") {
							this._headerColumns.style[index].type = "number";
						}
					}
				}

				if (this._exportOption.exceptStyle == true) {
					datas[datas.length] = cellValue;
				} else {
					let classStyle: { [styleName: string]: string } = this._getClassStyle(this._headerColumns.cellProps[index].configuration);
					let cellStyle: { [styleName: string]: string } = this._headerColumns.cellProps[index].configuration.style._getCSS(true);
					let controlStyle: { [styleName: string]: string } = {};
					if (this._headerColumns.cellProps[index].configuration.control) {
						controlStyle = this._headerColumns.cellProps[index].configuration.control.style._getCSS(true);
					}
					// 인라인으로 지정한 스타일이 class 스타일보다 우선합니다.
					datas[datas.length] = { value: cellValue, style: _mergeObject(classStyle, cellStyle, controlStyle) };
				}
			});

			this._handleRowData(datas);
			this._handleRowgroupStyle(VLOC_REGION.HEADER, this._headerColumns.style);

			return {
				region: VLOC_REGION.HEADER,
				style: this._headerColumns.style,
				data: [datas]
			};
		}

		/**
		 * detail영역의 style과 data 정보를 생성하여 반환합니다.
		 * (row grouping을 사용하지 않았을 경우 사용합니다.)
		 */
		private _createDetail(): utils.RowGroup {
			let detailDatas: utils.CellData[][] = [];
			let rowData: utils.CellData[] = null;

			// detail 영역 정보 가져오기
			let tableInfos: {} = this._grid._getTableInfo();
			let tableInfo: { band: gridpart.AbstractGridPart, constraints: GridBandConstraint }[] = null;
			if (tableInfos[GRIDREGION.CENTER] && tableInfos[GRIDREGION.CENTER].length > 0) {
				tableInfo = tableInfos[GRIDREGION.CENTER];
			} else if (tableInfos[GRIDREGION.LEFT] && tableInfos[GRIDREGION.LEFT].length > 0) {
				tableInfo = tableInfos[GRIDREGION.LEFT];
			} else if (tableInfos[GRIDREGION.RIGHT] && tableInfos[GRIDREGION.RIGHT].length > 0) {
				tableInfo = tableInfos[GRIDREGION.RIGHT];
			}
			if (tableInfo == null) {
				return null;
			}
			let middleStartRowIndex: number = -1;
			let middleEndRowIndex: number = -1;
			tableInfo.forEach((region: { band: gridpart.AbstractGridPart, constraints: GridBandConstraint }) => {
				if (region.band instanceof GridDetail && region.band.loc == GRIDREGION.MIDDLE) {
					middleStartRowIndex = region.band.getStartRowIndex();
					middleEndRowIndex = region.band.getEndRowIndex();
				}
			});


			if (this._exportOption.rows != null) {
				let rowIndices: number[] = this._exportOption.rows;
				let rowCount: number = rowIndices.length;
				let loc: string = null;
				for (let i = 0; i < rowCount; i++) {
					if (i < middleStartRowIndex) {
						loc = GRIDREGION.TOP;
					} else if (middleEndRowIndex < i) {
						loc = GRIDREGION.BOTTOM;
					} else {
						loc = GRIDREGION.MIDDLE;
					}

					let suppressCellInfo: layout.SuppressCellInfo[] = this._getSuppressCellInfo(loc, i);

					rowData = this._getRowData(this._detailColumns.cellProps, rowIndices[i], suppressCellInfo);
					this._handleRowData(rowData);
					detailDatas[detailDatas.length] = rowData;
				}

			} else {
				let rowCount: number = this._grid.rowCount;
				let loc: string = null;
				for (let ri = 0; ri < rowCount; ri++) {
					if (ri < middleStartRowIndex) {
						loc = GRIDREGION.TOP;
					} else if (middleEndRowIndex < ri) {
						loc = GRIDREGION.BOTTOM;
					} else {
						loc = GRIDREGION.MIDDLE;
					}

					let suppressCellInfo: layout.SuppressCellInfo[] = this._getSuppressCellInfo(loc, ri);

					rowData = this._getRowData(this._detailColumns.cellProps, ri, suppressCellInfo);
					this._handleRowData(rowData);
					detailDatas[detailDatas.length] = rowData;
				}
			}

			this._handleRowgroupStyle(VLOC_REGION.DETAIL, this._detailColumns.style);

			return {
				region: VLOC_REGION.DETAIL,
				style: this._detailColumns.style,
				data: detailDatas
			};
		}

		/**
		 * detail영역의 style과 data 정보를 생성하여 반환합니다.
		 * (row grouping을 사용하였을 경우 사용합니다.)
		 */
		private _createGroupingDetail(): utils.RowGroup[] {
			let result: utils.RowGroup[] = [];
			let virtualRows: provider.VirtualRow[] = this._grid._getVirtualRows();

			let rowCount: number = virtualRows.length;
			let rowDatas: utils.CellData[][] = [];
			let beforeVRow: { vrowtype: provider.VROWTYPE, condition?: string } = null;
			let loc: string = null;
			let tableInfos: {} = this._grid._getTableInfo();
			let tableInfo: { band: gridpart.AbstractGridPart, constraints: GridBandConstraint }[] = null;
			if (tableInfos[GRIDREGION.CENTER] && tableInfos[GRIDREGION.CENTER].length > 0) {
				tableInfo = tableInfos[GRIDREGION.CENTER];
			} else if (tableInfos[GRIDREGION.LEFT] && tableInfos[GRIDREGION.LEFT].length > 0) {
				tableInfo = tableInfos[GRIDREGION.LEFT];
			} else if (tableInfos[GRIDREGION.RIGHT] && tableInfos[GRIDREGION.RIGHT].length > 0) {
				tableInfo = tableInfos[GRIDREGION.RIGHT];
			}
			if (tableInfo == null) {
				return null;
			}
			let middleStartRowIndex: number = -1;
			let middleEndRowIndex: number = -1;
			tableInfo.forEach((region: { band: gridpart.AbstractGridPart, constraints: GridBandConstraint }) => {
				if (region.band instanceof GridDetail && region.band.loc == GRIDREGION.MIDDLE) {
					middleStartRowIndex = region.band.getStartRowIndex();
					middleEndRowIndex = region.band.getEndRowIndex();
				}
			});


			for (let ri = 0; ri < rowCount; ri++) {
				let virtualRow: provider.VirtualRow = virtualRows[ri];
				let bandType: VLOC_REGION = null;

				if (virtualRow.type == provider.VROWTYPE.GFOOTER) {
					bandType = VLOC_REGION.GFOOTER;
				} else if (virtualRow.type == provider.VROWTYPE.GHEADER) {
					bandType = VLOC_REGION.GHEADER;
				} else {
					bandType = VLOC_REGION.DETAIL;
				}
				if (ri < middleStartRowIndex) {
					loc = GRIDREGION.TOP;
				} else if (middleEndRowIndex < ri) {
					loc = GRIDREGION.BOTTOM;
				} else {
					loc = GRIDREGION.MIDDLE;
				}

				if (beforeVRow != null && (beforeVRow.vrowtype != virtualRow.type || beforeVRow.condition != virtualRow.condition)) {
					let beforeRow: provider.VirtualRow = virtualRows[ri - 1];
					let beforeRowBandType: VLOC_REGION = VLOC_REGION.DETAIL;
					if (beforeRow.type == provider.VROWTYPE.GFOOTER) {
						beforeRowBandType = VLOC_REGION.GFOOTER;
					} else if (beforeRow.type == provider.VROWTYPE.GHEADER) {
						beforeRowBandType = VLOC_REGION.GHEADER;
					}

					let rowgroupStyle: utils.CellStyle[] = null;
					switch (beforeVRow.vrowtype) {
						case provider.VROWTYPE.GRIDROW: {
							rowgroupStyle = this._detailColumns.style;
							break;
						}
						case provider.VROWTYPE.GFOOTER:
						case provider.VROWTYPE.GHEADER: {
							rowgroupStyle = this._rowGroupColumns[beforeRow.condition][beforeRowBandType].style;
							break;
						}
					}
					this._handleRowgroupStyle(beforeRowBandType, rowgroupStyle);
					result.push({
						region: beforeRowBandType,
						style: rowgroupStyle,
						data: rowDatas
					});

					rowDatas = null;
					rowDatas = [];
				}

				let rowData: utils.CellData[] = null;
				let suppressCellInfo: layout.SuppressCellInfo[] = this._getSuppressCellInfo(loc, ri);
				switch (virtualRow.type) {
					case provider.VROWTYPE.GRIDROW: {
						let gridRow: provider.GridRow = virtualRow.rowdata as provider.GridRow;
						rowData = this._getRowData(this._detailColumns.cellProps, gridRow.getIndex(), suppressCellInfo);

						this._handleRowData(rowData);

						rowDatas[rowDatas.length] = rowData;

						break;
					}
					case provider.VROWTYPE.GFOOTER:
					case provider.VROWTYPE.GHEADER: {
						rowData = this._getGroupingRowData(virtualRow, ri, this._rowGroupColumns[virtualRow.condition][bandType], suppressCellInfo);

						this._handleRowData(rowData);

						rowDatas[rowDatas.length] = rowData;

						break;
					}
				}

				if (ri == (rowCount - 1)) {
					let rowgroupStyle: utils.CellStyle[] = null;
					switch (virtualRow.type) {
						case provider.VROWTYPE.GRIDROW: {
							rowgroupStyle = this._detailColumns.style;
							break;
						}
						case provider.VROWTYPE.GFOOTER:
						case provider.VROWTYPE.GHEADER: {
							rowgroupStyle = this._rowGroupColumns[virtualRow.condition][bandType].style;
							break;
						}
					}

					this._handleRowgroupStyle(bandType, rowgroupStyle);
					result.push({
						region: bandType,
						style: rowgroupStyle,
						data: rowDatas
					});
				}

				beforeVRow = { vrowtype: virtualRow.type, condition: virtualRow.condition };
			}
			return result;
		}

		/**
		 * footer영역의 style과 data 정보를 생성하여 반환합니다.
		 */
		private _createFooter(): utils.RowGroup {
			let dataset: data.DataCollection = this._grid.dataSet;
			let datas: utils.CellData[] = [];
			this._footerColumns.cellProps.forEach((cellProp: GridFooterCellProp, index: number) => {
				let cellValue: (string | number) = null;
				let applyFormat: boolean = this._exportOption.applyFormat;
				let exprResult: (string | number | ufc.StyledString) = (cellProp.configuration.expr != null) ? GridUtil._getDataExprResult(cellProp.configuration.expr, dataset) : "";
				exprResult = (exprResult instanceof ufc.StyledString) ? ufc.StyledString._asString(exprResult) : exprResult;
				if (cellProp.configuration.control) {
					if (applyFormat == true) {
						cellValue = this._getControlText(cellProp.configuration.control, null, exprResult);
					} else {
						cellValue = this._getControlValue(cellProp.configuration.control, null, exprResult);
					}
				} else {
					cellValue = exprResult;
					if (applyFormat == true) {
						cellValue = "" + cellValue;
					} else if (typeof (cellValue) == "number") {
						// formula가 적용된 경우 formula 우선
						if (this._footerColumns.style[index].type != "formula") {
							this._footerColumns.style[index].type = "number";
						}
					}
				}

				if (this._exportOption.exceptStyle == true) {
					datas[datas.length] = cellValue;
				} else {
					let classStyle: { [styleName: string]: string } = this._getClassStyle(this._footerColumns.cellProps[index].configuration);
					let cellStyle: { [styleName: string]: string } = this._footerColumns.cellProps[index].configuration.style._getCSS(true);
					let controlStyle: { [styleName: string]: string } = {};
					if (this._footerColumns.cellProps[index].configuration.control) {
						controlStyle = this._footerColumns.cellProps[index].configuration.control.style._getCSS(true);
					}
					// 인라인으로 지정한 스타일이 class 스타일보다 우선합니다.
					datas[datas.length] = { value: cellValue, style: _mergeObject(classStyle, cellStyle, controlStyle) };
				}
			});

			this._handleRowData(datas);
			this._handleRowgroupStyle(VLOC_REGION.FOOTER, this._footerColumns.style);

			return {
				region: VLOC_REGION.FOOTER,
				style: this._footerColumns.style,
				data: [datas]
			};
		}

		/**
		 * detail 영역의 row data를 배열로 반환합니다.
		 * @param grid 
		 * @param cellProps 
		 * @param rowIndex 
		 * @param checkRowIndices 
		 */
		private _getRowData(cellProps: GridDetailCellProp[], rowIndex: number, suppressCellInfo: layout.SuppressCellInfo[]): utils.CellData[] {
			let detailCellCount: number = cellProps.length;
			let rowData: utils.CellData[] = [];
			let bindContext: bind.GridEmbeddedContext = this._grid.getBindContext() as bind.GridEmbeddedContext;

			this._grid._setContentDataRowIndex(rowIndex, -1);

			for (let ci = 0; ci < detailCellCount; ci++) {
				let exportCellIndex: number = rowData.length;
				let cellIndex: number = cellProps[ci].constraint.cellIndex;
				let columnName: string = cellProps[ci].configuration.columnName;
				let control: GridUIControl = this._grid.detail.getColumn(cellIndex)?.control;
				let mergedColumnName: string = null;
				let mergedValue: string = null;

				bindContext._setDetailCellIndex(cellProps[ci].constraint.cellIndex);

				if (this._exportOption.applySuppress == true
					&& cellProps[ci].configuration._isMergeableCell() && cellProps[ci].configuration.mergedColumnName != null
					&& suppressCellInfo && suppressCellInfo[cellIndex]
					&& suppressCellInfo[cellIndex].startCellIndex < suppressCellInfo[cellIndex].endCellIndex) {
					mergedColumnName = cellProps[ci].configuration.mergedColumnName;
					mergedValue = suppressCellInfo[cellIndex].text;
				}
				let cellValue: (string | number) = this._getCellData({
					rowIndex: rowIndex,
					columnName: columnName,
					columnType: cellProps[ci].configuration.columnType,
					control: control,//cellProps[ci].configuration.control,
					index: ci,
					mergedColumnName: mergedColumnName,
					mergedValue: mergedValue
				});

				if (this._exportOption.exceptStyle != true || this._exportOption.applySuppress == true) {
					let cellData: { value?: number | string, style?: { [styleName: string]: string }, rowspan?: number, colspan?: number, isEmptyCell?: boolean } = { value: cellValue };

					if (this._exportOption.exceptStyle != true) {
						let classStyle: { [styleName: string]: string } = this._getClassStyle(this._detailColumns.cellProps[exportCellIndex].configuration);
						let cellStyle: { [styleName: string]: string } = this._detailColumns.cellProps[exportCellIndex].configuration.style._getCSS(true);
						let controlStyle: { [styleName: string]: string } = {};
						if (this._detailColumns.cellProps[exportCellIndex].configuration.control) {
							controlStyle = this._detailColumns.cellProps[exportCellIndex].configuration.control.style._getCSS(true);
						}
						// 인라인으로 지정한 스타일이 class 스타일보다 우선합니다.
						cellData.style = _mergeObject(classStyle, cellStyle, controlStyle);
					}
					if (this._exportOption.applySuppress == true && suppressCellInfo) {

						let cellSuppress: layout.SuppressCellInfo = suppressCellInfo[cellIndex];
						if (cellSuppress != null) { // suppress cell 인지 유무
							let isEmptyCell: boolean = (cellSuppress != null && cellSuppress.isRepeated);
							isEmptyCell = (isEmptyCell == false && cellSuppress != null && cellSuppress.isFirstMergedCell == false ? true : isEmptyCell);
							if (isEmptyCell) { // empty cell
								cellData.isEmptyCell = true;
							} else { // merge cell
								let cellColSpan: number = 0;
								for (let i = 0; i < this._detailColumns.cellProps.length; i++) {
									let cellIndex: number = this._detailColumns.cellProps[i].constraint.cellIndex;
									if (cellSuppress.startCellIndex <= cellIndex && cellIndex <= cellSuppress.endCellIndex) {
										cellColSpan += this._detailColumns.style[i].colspan;
									}
								}
								// for (let i = cellSuppress.startCellIndex; i <= cellSuppress.endCellIndex; i++) {
								// 	cellColSpan += this._detailColumns.style[i].colspan;
								// }
								cellData.colspan = cellColSpan;
								cellData.rowspan = cellSuppress.suppressRowCount * cellProps[ci].constraint.rowSpan;
							}

						}
					}

					if (this._exportOption.applySuppress == true && cellData?.isEmptyCell === true) {
						rowData[exportCellIndex] = {};
					} else {
						if (this._exportOption.reduce == true && (_.isEmpty(cellData.style) && utils.Util.isNullOrEmpty(cellData.colspan) && utils.Util.isNullOrEmpty(cellData.rowspan))) {
							rowData[exportCellIndex] = cellValue;
						} else {
							rowData[exportCellIndex] = cellData;
						}
					}

				} else {
					rowData[exportCellIndex] = cellValue;
				}

				bindContext._setDetailCellIndex(-1);
			}

			return rowData;
		}

		private _getCellData(cellInfo: { rowIndex: number, columnName: string, columnType: string, control: GridUIControl, index: number, mergedColumnName: string, mergedValue: string }): string | number {
			if (cellInfo.columnType == "rowindex") {
				return cellInfo.rowIndex + this._grid.rowIndexerStartNum;
			} else if (cellInfo.columnType == "checkbox") {
				// TODO check상태의 값을 어떻게 리턴해야 할까.
				return this._grid.isCheckedRow(cellInfo.rowIndex) ? "Y" : "N";
			} else if (cellInfo.columnType == "radio") {
				return this._grid.isRadioSelected(cellInfo.rowIndex) ? "Y" : "N";
			} else {
				let applyFormat: boolean = this._exportOption.applyFormat;
				if (cellInfo.control) {
					if (applyFormat == true) {
						if (cellInfo.control.type != "checkbox" && cellInfo.mergedValue != null) {
							return cellInfo.mergedValue;
						} else {
							return this._getControlText(cellInfo.control, { rowIndex: cellInfo.rowIndex, columnName: cellInfo.columnName });
						}
					} else {
						return this._getControlValue(cellInfo.control, { rowIndex: cellInfo.rowIndex, columnName: cellInfo.columnName, mergedColumnName: cellInfo.mergedColumnName });
					}
				} else if (cellInfo.columnName != null) {
					let columnName: string = cellInfo.columnName;
					if (cellInfo != null && cellInfo.mergedColumnName != null && cellInfo.columnName != cellInfo.mergedColumnName) {
						columnName = cellInfo.mergedColumnName;
					}
					let value: any = this._grid.dataProvider.getValue(cellInfo.rowIndex, columnName);
					let resultValue: (string | number) = (value instanceof ufc.StyledString) ? ufc.StyledString._asString(value) : value;
					let header: data.header.Header = this._grid.dataProvider._getHeader(columnName);
					if (header != null) {
						if (header.getDataType() == data.tabledata.DataType.DECIMAL) {
							if (value != null) {
								if (value instanceof cpr.foundation.DecimalType) {
									resultValue = (applyFormat == true) ? value.toString() : value.toNumber();
								} else {
									resultValue = value;
								}
							}
						} else if (header.getDataType() == data.tabledata.DataType.EXPRESSION) {
							if (value instanceof cpr.foundation.DecimalType) {
								resultValue = value.toNumber();
								if (applyFormat == false && cellInfo.rowIndex == 0) {
									this._detailColumns.style[cellInfo.index].type = "number";
								}
							} else if (typeof (value) == "number") {
								resultValue = value;
								if (applyFormat == false && cellInfo.rowIndex == 0) {
									this._detailColumns.style[cellInfo.index].type = "number";
								}
							}
						}
					}
					if (resultValue == null) {
						resultValue = "";
					}
					if (applyFormat == true) {
						resultValue = "" + resultValue;
					}
					return resultValue;
				}
				return "";
			}
		}

		/**
		 * detail영역의 grouping row data를 배열로 반환합니다.
		 * @param virtualRow 
		 * @param contentIndex 
		 * @param rowGroupConfig 
		 */
		private _getGroupingRowData(virtualRow: provider.VirtualRow, contentIndex: number, rowGroupColumns: { style: utils.CellStyle[], cellProps: GridFooterCellProp[] }, suppressCellInfo: layout.SuppressCellInfo[]): utils.CellData[] {
			let rowData: utils.CellData[] = [];

			if (virtualRow.dsindex >= 0) {
				this._grid._setContentDataRowIndex(virtualRow.dsindex, -1);
			} else {
				this._grid._setContentDataRowIndex(-1, contentIndex); // row context 설정
			}

			let invisibleCount: number = 0;
			rowGroupColumns.cellProps.forEach((cellProp: GridFooterCellProp, index: number) => {
				let cellValue: (string | number) = null;
				let applyFormat: boolean = this._exportOption.applyFormat;
				let exprResult: (string | number | ufc.StyledString) = (cellProp.configuration.expr != null) ? GridUtil._getRowGroupExprValue(cellProp, virtualRow.rowdata as provider.GridRowGroup) : null;
				exprResult = (exprResult instanceof ufc.StyledString) ? ufc.StyledString._asString(exprResult) : exprResult;
				let control = cellProp.configuration.control;
				// TODO check _getFormatValue 를 사용하지 않은 이유는[2019/08/29]?
				if (control) {
					if (applyFormat == true) {
						cellValue = this._getControlText(cellProp.configuration.control, null, exprResult);
					} else {
						cellValue = this._getControlValue(cellProp.configuration.control, null, exprResult);
					}

				} else {
					cellValue = (exprResult == null) ? "" : exprResult;

					// grouping text의 경우 무조건 string형으로 반환되기 때문에 number형으로 형변환 필요
					if (applyFormat == false && cellValue != "" && isNaN(Number(cellValue)) == false) {
						cellValue = Number(cellValue);
						// formula가 적용된 경우 formula 우선
						if (rowGroupColumns.style[index - invisibleCount].type != "formula") {
							rowGroupColumns.style[index - invisibleCount].type = "number";
						}
					}
				}

				let exportCellIndex: number = rowData.length;
				if (this._exportOption.exceptStyle != true || this._exportOption.applySuppress == true) {
					let cellData: { value?: number | string, style?: { [styleName: string]: string }, rowspan?: number, colspan?: number } = { value: cellValue };

					if (this._exportOption.exceptStyle != true) {
						let classStyle: { [styleName: string]: string } = this._getClassStyle(cellProp.configuration);
						let cellStyle: { [styleName: string]: string } = cellProp.configuration.style._getCSS(true);
						let controlStyle: { [styleName: string]: string } = {};
						if (cellProp.configuration.control) {
							controlStyle = cellProp.configuration.control.style._getCSS(true);
						}
						// 인라인으로 지정한 스타일이 class 스타일보다 우선합니다.
						cellData.style = _mergeObject(classStyle, cellStyle, controlStyle);
					}
					if (this._exportOption.applySuppress == true && suppressCellInfo) {
						let cellIndex: number = cellProp.constraint.cellIndex;
						let cellSuppress: layout.SuppressCellInfo = suppressCellInfo[cellIndex];
						if (cellSuppress != null) { // suppress cell 인지 유무
							let isEmptyCell: boolean = (cellSuppress != null && cellSuppress.isRepeated);
							isEmptyCell = (isEmptyCell == false && cellSuppress != null && cellSuppress.isFirstMergedCell == false ? true : isEmptyCell);
							if (isEmptyCell) { // empty cell
								cellData = {};
							} else { // merge cell
								let cellColSpan: number = 0;
								for (let i = 0; i < this._detailColumns.cellProps.length; i++) {
									let cellIndex: number = this._detailColumns.cellProps[i].constraint.cellIndex;
									if (cellSuppress.startCellIndex <= cellIndex && cellIndex <= cellSuppress.endCellIndex) {
										cellColSpan += this._detailColumns.style[i].colspan;
									}
								}
								// for (let i = cellSuppress.startCellIndex; i <= cellSuppress.endCellIndex; i++) {
								// 	cellColSpan += this._detailColumns.style[i].colspan;
								// }
								cellData.colspan = cellColSpan;
								cellData.rowspan = cellSuppress.suppressRowCount * cellProp.constraint.rowSpan;
							}

						}

					}
					rowData[exportCellIndex] = cellData;
				} else {
					rowData[exportCellIndex] = cellValue;
				}
			});

			return rowData;
		}

		private _setGroupingRowStyle(rowGroupConfig: GridRowGroupBandConfig,
			invisibleIndices: number[],
			option: utils.ExportOption,
			settingObject: { style: utils.CellStyle[], cellProps: GridCellProp[] }): void {

			let rowGroupCellProps: GridFooterCellProp[] = rowGroupConfig.cellProp;
			let cellCount: number = rowGroupCellProps.length;
			if (cellCount == 0) {
				return;
			}

			rowGroupConfig.cellProp.sort(GridUtil._rowFirstSort);

			let gridRowGroup: provider.GridRowGroup = this._grid.getGridRowGroup(0);
			for (let cellIdx = (cellCount - 1); cellIdx >= 0; cellIdx--) {
				let cellProp: GridFooterCellProp = rowGroupCellProps[cellIdx];
				let colIndex: number = Number(cellProp.constraint.colIndex);
				let colSpan: number = Number(cellProp.constraint.colSpan);

				for (let ci = (invisibleIndices.length - 1); ci >= 0; ci--) {
					if (colIndex <= invisibleIndices[ci] && (colIndex + colSpan - 1) >= invisibleIndices[ci]) {
						if (colIndex == invisibleIndices[ci]) {
							colSpan -= 1;
							if (colSpan == 0) {
								// colSpan이 1이고, 해당 컬럼이 invisible 인 경우
								break;
							}
						} else {
							colSpan -= 1;
						}
					} else if (colIndex > invisibleIndices[ci]) {
						colIndex -= 1;
					}
				}

				if (colSpan > 0) {
					var cellType: string = "string";
					if (option.applyFormat == false) {

						let cellRenderer: renderer.RowGroupCellRenderer = cellProp.cellRenderer as renderer.RowGroupCellRenderer;
						if (gridRowGroup != null && cellRenderer != null) {
							let cellValue: (string | number | ufc.StyledString) = GridUtil._getRowGroupExprValue(cellProp, gridRowGroup);
							// 컨트롤의 text는 무조건 string이기 때문에 처리에서 제외
							if (typeof (cellValue) == "number") {
								cellType = "number";
							}
						}
					}

					let cellInfo: utils.CellStyle = {
						type: cellType,
						rowindex: cellProp.constraint.rowIndex,
						rowspan: cellProp.constraint.rowSpan,
						colindex: colIndex,
						colspan: colSpan,
						cellIndex: cellProp.constraint.cellIndex
					}

					// 스타일을 포함하는 경우 (exceptStyle==false)
					if (option.exceptStyle == false) {
						// 바인딩되지 않은 class의 스타일은 행마다 달라지지 않으므로 셀별 스타일 대신 공통 스타일에 담습니다.
						// 인라인 스타일을 class 스타일 뒤에 병합하여 렌더링과 동일하게 인라인이 우선합니다.
						let classStyles = this._getStaticClassStyles(cellProp.configuration);
						let style = _mergeObject(classStyles.cell, cellProp.configuration.style._getCSS(false));
						if (cellProp.configuration.control) {
							style = _mergeObject(classStyles.cell, cellProp.configuration.style._getCSS(false),
								classStyles.control, cellProp.configuration.control.style._getCSS(false));
						}
						cellInfo.style = style;
					}

					// 데이터타입만 지정하는 경우 (applyFormat==false)
					// 포맷을 지정하는 경우 (applyFormat==true, useFormat==true)
					if (option.applyFormat == false) {
						let control: GridUIControl = cellProp.configuration.control;
						if (control != null && (control.type == "numbereditor" || (control.type == "output" && (control as Output).dataType == "number"))) {
							cellInfo.type = "number";
						}
					} else if (option.applyFormat == true && option.useFormat == true) {
						let control: GridUIControl = cellProp.configuration.control;
						if (control != null && (control.type == "numbereditor" || (control.type == "output" && (control as Output).dataType == "number"))) {
							cellInfo.format = control["format"];
							cellInfo.type = "number";
						}
					}

					// formula를 설정한 경우
					if (utils.Util.isNullOrEmpty(cellProp.configuration.formula) == false) {
						cellInfo.type = "formula";
						cellInfo.formula = cellProp.configuration.formula;
					}

					settingObject.style.splice(0, 0, cellInfo);
					settingObject.cellProps.splice(0, 0, cellProp);
					cellInfo = null;
				}
			}

			/* runtime cellProp 정렬 (우선순위 : colIndex, rowIndex) */
			// rowGroupConfig.cellProp.sort(GridUtil._colFirstSort);
		}

		private _getGridRowGroups(): { [groupCondition: string]: { gheader?: GridRowGroupBandConfig, gfooter?: GridRowGroupBandConfig } } {
			if (this._grid.context._isGrouping() == false) {
				return null;
			}

			let gridRowGroups: GridRowGroupConfig[] = this._grid.context.getRowGroup();
			if (gridRowGroups == null || gridRowGroups.length == 0) {
				return null;
			}

			let result: {
				[groupCondition: string]: {
					gheader?: GridRowGroupBandConfig, gfooter?: GridRowGroupBandConfig
				}
			} = {};
			gridRowGroups.forEach((gridRowGroup: GridRowGroupConfig) => {
				result[gridRowGroup.groupCondition] = {};
				if (gridRowGroup.gheader) {
					result[gridRowGroup.groupCondition]["gheader"] = gridRowGroup.gheader;
				}
				if (gridRowGroup.gfooter) {
					result[gridRowGroup.groupCondition]["gfooter"] = gridRowGroup.gfooter;
				}
			});
			return result;
		}

		/**
		 * applyFormat=true시 컨트롤 값 반환
		 * @param ctrl 
		 * @param cellInfo 
		 * @param exprResult header의 text, footer의 expr
		 */
		private _getControlText(ctrl: GridUIControl, cellInfo?: { rowIndex: number, columnName: string }, exprResult?: string | number): string | number {
			let text: string | number = null;
			if (ctrl) {
				let ctrltype: string = ctrl.type;
				let isUdc: boolean = (ctrl instanceof UDCBase) ? true : false;
				if (isUdc) { // UDC 처리 (applyFormat=false 와 동일)
					if (ctrl["getText"] != null) {
						text = ctrl["getText"]();
					} else if (cellInfo != undefined) {
						let value: any = this._grid.dataProvider.getValue(cellInfo.rowIndex, cellInfo.columnName);
						let resultValue: (string | number) = (value instanceof foundation.DecimalType) ? value.toNumber() : value;
						value = (resultValue != null) ? "" + resultValue : "";
					} else {
						text = (ctrl["value"] != null) ? "" + ctrl["value"] : "";
					}
				} else { // 기본 컨트롤
					if (_isNullOrEmpty(exprResult) == false) {
						ctrl["value"] = "" + exprResult;
					}
					text = ctrl._exportValue(this._exportOption.useFormat);
				}
			}
			return text;
		}

		/**
		 * applyFormat=false시 컨트롤 값 반환
		 * @param ctrl 
		 * @param cellInfo 
		 * @param exprResult header의 text, footer의 expr
		 */
		private _getControlValue(ctrl: GridUIControl, cellInfo?: { rowIndex: number, columnName: string, mergedColumnName: string }, exprResult?: string | number): string | number {
			let value: string | number = null;
			if (ctrl) {
				let ctrltype: string = ctrl.type;
				let isUdc: boolean = (ctrl instanceof UDCBase) ? true : false;
				if (isUdc) { // UDC 처리 (applyFormat=true 와 동일)
					if (ctrl["getText"] != null) {
						value = ctrl["getText"]();
					} else if (cellInfo != undefined) {
						let value: any = this._grid.dataProvider.getValue(cellInfo.rowIndex, cellInfo.columnName);
						let resultValue: (string | number) = (value instanceof foundation.DecimalType) ? value.toNumber() : value;
						value = (resultValue != null) ? "" + resultValue : "";
					} else {
						value = (ctrl["value"] != null) ? "" + ctrl["value"] : "";
					}
				} else { // 기본 컨트롤
					if (_isNullOrEmpty(exprResult) == false) {
						ctrl["value"] = "" + exprResult;
					}

					// 기본 >> value
					let ctrlValue: string = ctrl["value"];
					if (cellInfo != null) {
						let bindInfo: bind.BindInfo = ctrl.getBindInfo("value");
						if (bindInfo && bindInfo.type == "datacolumn" && bindInfo.columnName != cellInfo.mergedColumnName) {
							let dsValue: any = this._grid.dataProvider.getValue(cellInfo.rowIndex, cellInfo.mergedColumnName); // decimal 처리 필요
							let header: data.header.Header = this._grid.dataProvider._getHeader(cellInfo.columnName);
							if (header != null && header.getDataType() == data.tabledata.DataType.DECIMAL || header.getDataType() == data.tabledata.DataType.EXPRESSION) {
								if (dsValue != null && dsValue instanceof cpr.foundation.DecimalType) {
									dsValue = dsValue.toNumber();
								}
							}
							if (dsValue == null) {
								dsValue = "";
							}
						}
					}
					value = (ctrlValue != null) ? "" + ctrlValue : "";

					if (ctrltype == "htmlsnippet") {
						let exportValue: string = (ctrl as HTMLSnippet).exportValue;
						if (exportValue != null) {
							value = exportValue;
						}
					} else if (ctrltype == "numbereditor" || (ctrltype == "output" && (ctrl as Output).dataType == "number")) {
						// 넘버에디터, 아웃풋(number) >> value 
						// applyFormat=false 인 경우 userFormat에 상관없이 넘버에디터, 아웃풋(number)의 경우 number형으로 반환
						if (ctrlValue != null && ctrlValue != "") {
							let numberValue: number = Number(ctrlValue);
							if (isNaN(numberValue) == false) {
								value = numberValue;
							}
						}
					}
				}
			}
			return value;
		}

		private _getInvisibleIndices(excludeCellIndices: number[]): number[] {
			let context: GridContext = this._grid.context;

			let invisibleIndices: number[] = [];
			let headerCellProps: GridHeaderCellProp[] = [].concat(context._getHeaderCellProps());

			// header cellProp를 studio(사용자)기준으로 맞추기 위해 정렬 (우선순위 : rowIndex, colIndex)
			headerCellProps.sort(GridUtil._rowFirstSort);

			headerCellProps.forEach((cellProp: GridHeaderCellProp, index: number) => {
				if (excludeCellIndices.indexOf(cellProp.constraint.cellIndex) != -1) {
					for (let ci = cellProp.constraint.colIndex; ci < cellProp.constraint.colIndex + cellProp.constraint.colSpan; ci++) {
						invisibleIndices[invisibleIndices.length] = ci;
					}
				}
			});

			invisibleIndices = _stream(invisibleIndices)
				.uniquify()
				.sortBy((a, b) => a - b)
				.collect();

			return invisibleIndices;
		}

		/**
		 * class 스타일 해석에 사용한 자원을 정리합니다.
		 */
		private _disposeClassStyleResolver(): void {
			if (this._classStyleResolver != null) {
				this._classStyleResolver._dispose();
				this._classStyleResolver = null;
			}
		}

		/**
		 * 바인딩된 class에 의해 셀별로 달라지는 CSS 속성을 반환합니다.<br>
		 * 익스프레션 바인딩으로 지정한 class는 호출 시점에 설정되어 있는 행 컨텍스트를 기준으로 평가되므로,
		 * 행별로 다른 class가 적용되는 경우에도 해당 셀에 실제로 적용된 class 기준으로 해석됩니다.<br>
		 * 바인딩되지 않은 class의 스타일은 행마다 달라지지 않으므로 여기가 아니라
		 * 밴드 공통 스타일({@link _getStaticClassStyles})로 전달됩니다.<br>
		 * 셀에 컨트롤이 배치된 경우 컨트롤에 지정된 class는 컨트롤 프로브에서 별도로 측정하며,
		 * 렌더링과 동일하게 컨트롤에 지정한 class가 셀에 지정한 class보다 우선하도록 병합합니다.<br>
		 * 선택/편집 등 화면 상태에 의해 부여되는 class와,
		 * 공통 스타일 중 렌더링에서 class 스타일보다 우선하는 속성(정적 인라인 등)은 제외합니다.<br>
		 * applyClassStyle 옵션을 사용하지 않은 경우 빈 객체를 반환합니다.
		 * @param configuration class 스타일을 얻을 셀의 설정.
		 * @return class에 의해 적용되는 CSS 속성.
		 */
		private _getClassStyle(configuration: config.GridCellConfigurator): { [styleName: string]: string } {
			if (this._exportOption.applyClassStyle != true || configuration == null) {
				return {};
			}

			let control: GridUIControl = configuration.control;
			let cellBinded: boolean = configuration.style.getClassBindInfo() != null;
			let controlBinded: boolean = (control != null && control.style.getClassBindInfo() != null);
			if (cellBinded == false && controlBinded == false) {
				// 바인딩된 class가 없으면 class 스타일이 행마다 달라지지 않으므로 밴드 공통 스타일로만 전달합니다.
				return {};
			}
			if (this._classStyleResolver == null) {
				this._classStyleResolver = new GridClassStyleResolver(this._grid);
			}

			let cellClasses: string[] = configuration.style.getClasses();
			let controlStaticStyle: { [styleName: string]: string } = (control != null) ? control.style._getCSS(false) : null;

			// 셀별 스타일은 밴드 공통 스타일보다 우선 적용되므로, 공통 스타일에 담기는 값 중
			// 렌더링에서 class 스타일보다 우선하는 것(정적 인라인 스타일, 컨트롤의 바인딩되지 않은
			// class 스타일)이 지정한 속성은 셀별 스타일에서 제외해 공통 스타일 값이 그대로 적용되게 합니다.
			let cellClassStyle: { [styleName: string]: string } = {};
			if (cellBinded == true) {
				cellClassStyle = this._classStyleResolver._resolve(cellClasses);
				let commonStyle: { [styleName: string]: string } = _mergeObject(configuration.style._getCSS(false), controlStaticStyle);
				if (control != null && controlBinded == false) {
					commonStyle = _mergeObject(commonStyle, this._classStyleResolver._resolveControl(
						GridExportUtil._getControlBaseClasses(control),
						control.style._getCustomClasses(), []));
				}
				cellClassStyle = GridExportUtil._excludeCommonStyledProperties(cellClassStyle, commonStyle);
			}

			let controlClassStyle: { [styleName: string]: string } = {};
			if (controlBinded == true) {
				controlClassStyle = this._classStyleResolver._resolveControl(
					GridExportUtil._getControlBaseClasses(control),
					control.style._getCustomClasses(),
					cellClasses);
				// 컨트롤 class보다 우선하는 것은 컨트롤의 정적 인라인 스타일뿐입니다.
				controlClassStyle = GridExportUtil._excludeCommonStyledProperties(controlClassStyle, controlStaticStyle);
			}
			return _mergeObject(cellClassStyle, controlClassStyle);
		}

		/**
		 * 바인딩되지 않은 class에 의해 적용되는 CSS 속성을 반환합니다. 밴드 공통 스타일에 담는 용도입니다.<br>
		 * 행마다 달라지지 않으므로 셀별 스타일에 반복해서 담지 않고, 정적 인라인 스타일처럼 공통 스타일로
		 * 한 번만 전달합니다. 인라인 스타일보다 앞에 병합하여 렌더링과 동일하게 인라인이 우선하게 합니다.<br>
		 * 바인딩된 class는 행 컨텍스트가 필요하므로 셀별 스타일({@link _getClassStyle})에서 해석합니다.<br>
		 * applyClassStyle 옵션을 사용하지 않은 경우 빈 객체를 반환합니다.
		 * @param configuration class 스타일을 얻을 셀의 설정.
		 * @return 셀과 셀에 배치된 컨트롤 각각의 class에 의해 적용되는 CSS 속성.
		 */
		private _getStaticClassStyles(configuration: config.GridCellConfigurator): { cell: { [styleName: string]: string }, control: { [styleName: string]: string } } {
			let result = { cell: {} as { [styleName: string]: string }, control: {} as { [styleName: string]: string } };
			if (this._exportOption.applyClassStyle != true || configuration == null) {
				return result;
			}
			if (this._classStyleResolver == null) {
				this._classStyleResolver = new GridClassStyleResolver(this._grid);
			}

			let cellBinded: boolean = configuration.style.getClassBindInfo() != null;
			if (cellBinded == false) {
				result.cell = this._classStyleResolver._resolve(configuration.style.getClasses());
			}
			let control: GridUIControl = configuration.control;
			if (control != null && control.style.getClassBindInfo() == null) {
				result.control = this._classStyleResolver._resolveControl(
					GridExportUtil._getControlBaseClasses(control),
					control.style._getCustomClasses(),
					// 셀 class가 바인딩된 경우 행마다 달라지므로 셀 class가 없는 상태를 기준으로 측정합니다.
					cellBinded ? [] : configuration.style.getClasses());
			}
			return result;
		}

		/**
		 * class 스타일에서 밴드 공통 스타일이 지정한 속성을 제외한 결과를 반환합니다.<br>
		 * 인라인 스타일은 border-top과 같은 축약 속성으로 지정될 수 있으므로,
		 * 속성 명이 같은 경우 외에 축약 속성이 포괄하는 세부 속성도 함께 제외합니다.
		 * @param classStyle class에 의해 적용되는 CSS 속성.
		 * @param commonStyle 밴드 공통 스타일로 전달되는 CSS 속성 중 class 스타일보다 우선하는 속성.
		 */
		private static _excludeCommonStyledProperties(classStyle: { [styleName: string]: string },
			commonStyle: { [styleName: string]: string }): { [styleName: string]: string } {
			if (commonStyle == null || _.isEmpty(commonStyle) || _.isEmpty(classStyle)) {
				return classStyle;
			}
			let commonNames: string[] = Object.keys(commonStyle);
			let result: { [styleName: string]: string } = {};
			Object.keys(classStyle).forEach((property: string) => {
				let covered: boolean = commonNames.some((commonName: string) => {
					if (commonName == property || property.indexOf(commonName + "-") == 0) {
						return true;
					}
					// border-width/style/color 축약 속성은 네 방향의 세부 속성을 포괄합니다.
					let matched: RegExpMatchArray = commonName.match(/^border-(width|style|color)$/);
					return matched != null && new RegExp("^border-(top|right|bottom|left)-" + matched[1] + "$").test(property);
				});
				if (covered == false) {
					result[property] = classStyle[property];
				}
			});
			return result;
		}

		/**
		 * 셀에 배치된 컨트롤이 렌더링될 때 기본으로 가지는 class를 반환합니다. 컨트롤 class 스타일 측정의 기준입니다.<br>
		 * 타입 class(cl-output 등)는 각 컨트롤 셸의 "cl-" + 타입 명명 규칙을 따릅니다.
		 * @param control 셀에 배치된 컨트롤.
		 */
		private static _getControlBaseClasses(control: GridUIControl): string[] {
			return [GridStyle.CONTROL, "cl-" + control.type, GridContext.CLS_CTRL_INHERIT];
		}

		private _handleRowData(datas: utils.CellData[]): void {
			if (this._exportOption.rowDataHandler) {
				this._exportOption.rowDataHandler(datas, this._rowIndex);
			}
			this._rowIndex++;
		}
		private _handleRowgroupStyle(region: VLOC_REGION, cellStyle: utils.CellStyle[]): void {
			if (this._exportOption.rowgroupStyleHandler) {
				cellStyle.forEach((cellStyle: utils.CellStyle) => {
					this._exportOption.rowgroupStyleHandler(cellStyle, region, cellStyle.cellIndex, cellStyle.columnName);
					// delete cellStyle.cellIndex; 
					// delete cellStyle.columnName;
				})
			}
		}

		private _initSuppressModel(): void {
			let gridLocs: string[] = [GRIDREGION.TOP, GRIDREGION.MIDDLE, GRIDREGION.BOTTOM];

			for (let idx: number = 0; idx < gridLocs.length; idx++) {
				let loc: string = gridLocs[idx];

				this._suppressInfo[loc] = null;
				this._suppressInfo[loc] = [];

				this._initSuppressModelForLoc(loc);
			}
		}

		private _initSuppressModelForLoc(loc: string): void {
			let context: GridContext = this._grid.context;
			if (context.isEnabledPart(loc) == false) {
				// 활성 구역 체크
				return;
			}

			let rowCount: number = context.detailRowCount;
			let detailCellProps: GridDetailCellProp[] = null;
			let excludeCellIndices: number[] = [];
			if (this._exportOption.hasOwnProperty("excludeCellIndex") || this._exportOption.hasOwnProperty("excludeColIndex")) {
				detailCellProps = context._getDetailCellProps();
				let excludeColIndices: number[] = [];

				if (this._exportOption.hasOwnProperty("excludeCellIndex")) {
					let excludeColIndicesByCell: number[] = this._getInvisibleIndices(this._exportOption.excludeCellIndex);
					excludeColIndices = _.union(excludeColIndices, excludeColIndicesByCell);
				}
				if (this._exportOption.hasOwnProperty("excludeColIndex")) {
					excludeColIndices = _.union(excludeColIndices, this._exportOption.excludeColIndex);
				}

				for (let i = 0; i < detailCellProps.length; i++) {
					let detailCellProp: GridDetailCellProp = detailCellProps[i];
					let startColIndex: number = detailCellProp.constraint.colIndex;
					let endColIndex: number = (detailCellProp.constraint.colSpan != null) ? startColIndex + detailCellProp.constraint.colSpan - 1 : startColIndex;
					let isExcluded: boolean = true;
					for (let j = startColIndex; j <= endColIndex; j++) {
						if (excludeColIndices.indexOf(j) == -1) {
							isExcluded = false;
							break;
						}
					}
					if (isExcluded) {
						excludeCellIndices[excludeCellIndices.length] = detailCellProp.constraint.cellIndex;
					}
				}

			} else {
				detailCellProps = context._getVisibleDetailCells();
			}

			let mergeCellProps: GridDetailCellProp[] = [];
			let suppressCellProps: GridDetailCellProp[] = [];
			let hiddenSuppressCellProps: GridDetailCellProp[] = [];
			let excludeDetailCellProps: GridDetailCellProp[] = [];
			{ // visible suppress cell 
				detailCellProps.forEach((cellProp: GridDetailCellProp) => {
					if (cellProp.configuration._isMergeableCell()) { // mergeToIndexExpr이 있거나
						if (excludeCellIndices.indexOf(cellProp.constraint.cellIndex) != -1) {
							excludeDetailCellProps[excludeDetailCellProps.length] = cellProp;
						} else {
							mergeCellProps[mergeCellProps.length] = cellProp;
							suppressCellProps[suppressCellProps.length] = cellProp;
						}


					} else if ((rowCount == 1 || cellProp.constraint.rowSpan == rowCount) && // suppress 관련 설정이 있거나
						(cellProp.configuration._isSuppressibleCell())) {
						if (excludeCellIndices.indexOf(cellProp.constraint.cellIndex) != -1) {
							excludeDetailCellProps[excludeDetailCellProps.length] = cellProp;
						} else {
							suppressCellProps[suppressCellProps.length] = cellProp;
						}
					}
				});
			}
			if (suppressCellProps.length == 0) {
				// suppressible cell이 없는 경우
				return;
			}
			{ // invisible suppress cell 
				let hiddenDetailCellProps: GridDetailCellProp[] = context._getVisibleDetailCells(false);
				hiddenDetailCellProps.forEach((cellProp: GridDetailCellProp) => {
					if ((rowCount == 1 || cellProp.constraint.rowSpan == rowCount) && // suppress 관련 설정이 있거나
						(cellProp.configuration._isSuppressibleCell())) {
						hiddenSuppressCellProps[hiddenSuppressCellProps.length] = cellProp;
					}
				});
				hiddenDetailCellProps = hiddenDetailCellProps.concat(excludeDetailCellProps);
			}

			let startRowIndex: number = -1;
			let endRowIndex: number = -1;
			let contentRowCount: number = this._grid.getContentRowCount();
			if (contentRowCount > 0) {
				startRowIndex = 0;
				endRowIndex = contentRowCount - 1;
			}

			if (startRowIndex == -1 || endRowIndex == -1) {
				return;
			}

			this._suppressInfo[loc] = layout.SuppressModelGenerator._genSuppressInfo(detailCellProps, mergeCellProps, suppressCellProps, hiddenSuppressCellProps, startRowIndex, endRowIndex, loc, context);

		}

		private _getSuppressCellInfo(loc: string, rowIndex: number): layout.SuppressCellInfo[] {
			if (this._suppressInfo[loc] == null) {
				return null;
			}
			if (this._suppressInfo[loc][rowIndex] == null) {
				return null;
			}

			return this._suppressInfo[loc][rowIndex].data;
		}
	}

}