/// <reference path="./AccessableUIControl.ts"/>
/// <reference path="./provider/DataBindable.ts" />

namespace cpr.controls {

	/**
	 * @private
	 */
	enum FileInputClassName {
		clear = "cl-fileinput-clear",
		text = "cl-text"
	}

	/**
	 * @private
	 */
	export class FileInputFocusEntry implements FocusEntry {
		private _fileInput: FileInput;
		private _selector: string;
		constructor(fileInput: FileInput, selector: string) {
			this._fileInput = fileInput;
			this._selector = selector;
		}

		focus(forward: boolean): void {
			this._fileInput._focusBySelector(this._selector);
		}

		focusImmediately(forward: boolean = true) {
			this._fileInput._focusBySelector(this._selector, true);
		}
	}
	/**
	 * FileInput
	 * 사용자가 파일을 선택할 수있게 해주는 컨트롤.
	 * accept속성을 사용하여 컨트롤이 선택할 수 있는 파일 유형을 정의할 수 있습니다.
	 * 
	 * @firesgroup mouse
	 * @firesgroup contextmenu
	 * @firesgroup bindcontext
	 * @firesgroup keyboard
	 * @firesgroup focus
	 * 
	 * 
	 * @fires cpr.events.CValueChangeEvent#before-value-change FileInput의 value를 변경된 값이 저장되기 전에 발생하는 이벤트.
	 * 다음 이벤트로 value-change를 발생합니다. 다음 동작을 preventDefault로 방지 할 수 있습니다.
	 * <pre>oldValue: {string} 이전 값</pre>
	 * <pre>newValue: {string} 변경될 값</pre>
	 * 
	 * @fires cpr.events.CValueChangeEvent#value-change FileInput의 value의 변경된 값이 저장된 후에 발생하는 이벤트.
	 * <pre>oldValue: {string} 이전 값</pre>
	 * <pre>newValue: {string} 변경된 값</pre>
	 * 
	 * @fires cpr.events.CFileUploadEvent#maxsize-exceed 파일을 추가 시 파일의 크기가 최대 일 경우 발생하는 이벤트.
	 * 추가할 파일이 최대 크기보다 큰 경우 발생합니다.
	 * 추가된 파일들의 합계가 최대 크기보다 큰 경우 발생합니다.
	 * <pre>files: {File[]} 추가가 안된 파일들</pre>
	 * 
	 * @fires cpr.events.CMouseEvent#clear FileInput의 클리어버튼을 클릭하여 값이 Clear될때 발생하는 이벤트
	 */
	export class FileInput extends AccessableUIControl implements provider.MultiValueBindable, gridpart.IGridParticipant {
		private static readonly _AVAILABLE_PROP: string[] = [
			"value", "multiple", "values", "delimiter", "placeholder", "droppableFile",
			"acceptFile", "limitFileSize", "limitFileSizeUnit", "limitSizePerFile", "limitSizePerFileUnit",
			"showClearButton", "clearButtonImage", "buttonFocusable", "clearLabelExp"
		];

		private _files: File[] = [];
		private _droppableFile: boolean = true;
		private _binder: provider.MultiValueBinder;
		private _buttonFocusable: boolean = false;

		private _clearBtnFocusEntry = new FileInputFocusEntry(this, `.${FileInputClassName.clear}`);
		private _textFocusEntry = new FileInputFocusEntry(this, `.${FileInputClassName.text}`);

		private _internalProps: { [key: string]: any };

		/**
		 * 파일 인풋을 생성합니다.
		 * @param id 파일 인풋의 id
		 */
		constructor(id?: string) {
			super(id);
			this._binder = new provider.MultiValueBinder(this);

			this._addBindableProperty("placeholder", "").withSetterValidatorWithType(false, "string"); //----------------> placeholder
			this._addBindableProperty("limitFileSize", -1).withSetterValidatorWithType(false, "number");
			this._addBindableProperty("limitFileSizeUnit", "kb").withSetterValidatorWithType(false, "string");
			this._addBindableProperty("limitSizePerFile", -1).withSetterValidatorWithType(false, "number");
			this._addBindableProperty("limitSizePerFileUnit", "kb").withSetterValidatorWithType(false, "string");
			this._addBindableProperty("acceptFile", "").withSetterValidatorWithType(false, "string");
			this._addBindableProperty("showClearButton", false).withSetterValidatorWithType(false, "boolean");
			this._addBindableProperty("clearButtonImage", "").withSetterValidatorWithType(false, "string", true).withStringGetterTransformer("");

			// defaults.js에서 사용하는 속성
			this._setInternalProperty("clearLabelExp", "");
			// control initializing
			this._initControl();
		}

		protected _isConfigurableProperty(propName: string): boolean {
			if (FileInput._AVAILABLE_PROP.indexOf(propName) != -1) {
				return true;
			}
			return super._isConfigurableProperty(propName);
		}

		protected _setInternalProperty(name: string, value: any) {
			if (!this._internalProps) {
				this._internalProps = {};
			}
			this._internalProps[name] = value;
		}

		protected _getInternalProperty(name: string) {
			if (!this._internalProps) {
				return undefined;
			}
			return this._internalProps[name];
		}

		protected _setConfigureProperty(name: string, value: any): void {
			if (this._isConfigurableProperty(name)) {
				if (this._getInternalProperty(name) != undefined) {
					this._setInternalProperty(name, value);
				} else {
					this[name] = value;
				}
			}
		}

		protected _getLabel(defaultLabel: string, exp?: expression_string): string {
			if (exp) {
				let expr = new expression.Expression(exp);
				// 표현식 결과는 StyledString(sstr) 처럼 문자열이 아닐 수 있다. 이 값은 aria-label 로만 쓰이므로
				// 여기서 문자열로 확정하지 않으면 렌더링 시점에 빈 값이나 [object Object] 가 된다.
				// release-test-project#10122
				return ufc.StyledString._asString(expr.evaluate({
					_getExpressionDelegates: () => {
						return [
							this, this.getBindContext()
						]
					}
				}));
			}
			return defaultLabel;
		}

		/**
		 * @param name 
		 * @param oldValue 
		 * @param newValue 
		 */
		_valueDidChange(name: string, oldValue: any, newValue: any) {
			super._valueDidChange(name, oldValue, newValue);
			this._binder._valueDidChange(name, oldValue, newValue);
			switch (name) {
				case "limitFileSizeUnit":
				case "limitFileSize":
				case "limitSizePerFile":
				case "limitSizePerFileUnit":
				case "acceptFile":
				case "placeholder":
				case "showClearButton":
				case "clearButtonImage":
					{
						this.redraw();
						break;
					}
			}
		}

		/**
		 * 자동 크기 지원 타입을 얻습니다.
		 * 만일 both를 리턴했다면, css height, width 속성에 auto를 사용할 수 있음을 나타냅니다.
		 */
		public _getAutoSizeAvailability(): layouts.AutoSizeType {
			return layouts.AutoSizeType.both;
		}

		public _convertGridPasteText(text: string): string {
			return null;
		}

		public _getGridViewingText(): string {
			return this.value;
		}

		public _renderGridCellShape(grid: Grid, data: (string | ufc.StyledString), option: gridpart.renderer.IRenderOption): ufc.ControlShape {
			let fileInputShape: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: ["cl-control", "cl-fileinput"],
				attr: { role: "button" },
				style: {
					"text-align": "inherit",
				},
				children: []
			};
			cpr.ufc.ShapeUtil._setAriaDisabled(fileInputShape, this.enabled && !this.readOnly);
			if (option.maxHeight >= 0) {
				fileInputShape.style["height"] = option.maxHeight + "px";
			}

			if (option.hidetext == false) {
				let textStyle: { classNames?: string[] } = {};
				let text: string = this.value;
				if (text == "" && this.placeholder) {
					text = this.placeholder;
					textStyle["classNames"] = [ufc.Classes.PLACEHOLDER];
				}
				let textWrap: ufc.ElementShape = gridpart.renderer.CellRendererFactory._getGridCellTextShape(text, option.maxHeight, textStyle);
				layouts.GridCSSBuilder._forCell()._withColumnStart(1)._withRowStart(1)._commit(textWrap.style);
				fileInputShape.children = [textWrap];
			}
			layouts.GridCSSBuilder._forLayout()._withVerticalAlign(layouts.GridLayoutAlign.center)._withTemplateRows("1fr")._withTemplateColumns("1fr")._commit(fileInputShape.style);
			return fileInputShape;
		}

		/* control's type overriding */
		override _getType(): ControlType {
			return ControlType.FILEINPUT;
		}
		override _getLabelableType(): LabelableType {
			return LabelableType.div;
		}

		/**
		 * 컨트롤에 포커스를 지정합니다.
		 */
		override focus(forward: boolean = true) {
			if (forward == false && this.buttonFocusable && this.focusable && this.disposed == false) {
				let domTraverser: ufc.DOMTraverser = ufc._traverseFromControl(this);
				if (domTraverser) {
					let nodeList = domTraverser._children('[tabindex]');
					if (!nodeList) {
						return;
					}
					let nodeArray = _toArray(nodeList) as HTMLElement[];
					let nextNode = _.filter(nodeArray.reverse(), function (node) {
						return node.style.display != "none";
					})[0];
					if (nextNode) {
						nextNode.focus();
					}
				}
				return;
			}
			super.focus();
		}

		/* Shape */
		protected _getStylerSpec(): UIControlStylerSpec {
			return {
				root: { baseClass: "cl-fileinput" },
				clear: { baseClass: "cl-fileinput-clear" }
			};
		}

		protected _isEditable(): boolean {
			return (this.isAvailableBinding("value") == true);
		}

		/// MultiValueBindable Start ////////////////////////////////////////////

		/**
		 * 컨트롤의 값을 설정하고, value-change이벤트가 발생됩니다.
		 * @param value 컨트롤의 값.
		 */
		public set value(value: string) {
			this._binder.setValue(value);
		}

		/**
		 * 컨트롤의 값을 반환합니다.
		 * @return 컨트롤의 값.
		 */
		public get value(): string {
			return this._binder.getValue();
		}

		/**
		 * 컨트롤의 값을 설정합니다.
		 * @param value 컨트롤의 값.
		 */
		public putValue(value: string) {
			this._binder.setValue(value, false);
		}

		/**
		 * 다중 선택 시 컨트롤에 저장되는 값의 배열을 설정합니다.
		 * @param values 컨트롤에 저장되는 값의 배열.
		 */
		public putValues(values: string[]) {
			this._binder.setValues(values, false);
		}

		/**
		 * 아이템의 다중 선택 여부를 반환합니다.
		 * @return 아이템의 다중 선택 여부.
		 */
		public get multiple() {
			return this._binder.getMultiple();
		}

		/**
		 * 아이템의 다중 선택 여부를 설정합니다.
		 * @param newMultiple 아이템의 다중 선택 여부.
		 */
		public set multiple(multiple: boolean) {
			this._binder.setMultiple(multiple);
		}

		/**
		 * 다중 선택 시 컨트롤에 저장되는 값의 배열을 반환합니다.
		 * @return 컨트롤에 저장되는 값의 배열.
		 */
		public get values(): string[] {
			return this._binder.getValues();
		}

		/**
		 * 다중 선택 시 컨트롤에 저장되는 값의 배열을 설정합니다.
		 * @param 컨트롤에 저장되는 값의 배열.
		 */
		public set values(values: string[]) {
			this._binder.setValues(values);
		}

		/**
		 * 다중 선택된 값을 지정하거나 가져올 때의 구분자를 반환합니다.
		 * @return 구분자.
		 */
		public get delimiter(): string {
			return this._binder.getDelimiter();
		}

		/**
		 * 다중선택된 값을 지정하거나 가져올 때의 구분자를 설정합니다.
		 * @param delimiter 구분자.
		 */
		public set delimiter(delimiter: string) {
			this._binder.setDelimiter(delimiter);
		}

		/// MultiValueBindable End ////////////////////////////////////////////////

		/**
		 * 파일 선택 전에 보여지는 텍스트를 반환합니다.
		 * @return 파일 선택 전에 보여지는 텍스트.
		 */
		get placeholder(): string {
			return this._bindables.get("placeholder");
		}

		/**
		 * 파일 선택 전에 보여지는 텍스트를 설정합니다.
		 * @param text 파일 선택 전에 보여지는 텍스트.
		 */
		set placeholder(text: string) {
			this._bindables.set("placeholder", text);
		}

		/**
		 * drop 이벤트를 통해 파일을 선택할 수 있는지에 대한 여부를 반환합니다.
		 * @return drop 이벤트를 통한 파일 선택 여부.
		 */
		get droppableFile(): boolean {
			return this._droppableFile;
		}

		/**
		 * drop 이벤트를 통해 파일을 선택할 수 있는지에 대한 여부를 설정합니다.
		 * @param droppable drop 이벤트를 통한 파일 선택 여부.
		 */
		set droppableFile(droppable: boolean) {
			this._droppableFile = droppable;
		}

		/**
		 * 선택된 파일을 반환합니다. 다중 선택된 파일은 첫번째를 반환합니다.
		 * @return 선택된 파일.
		 */
		get file(): File {

			return this._files.length > 0 ? this.files[0] : null;
		}

		/**
		 * 파일을 선택합니다.
		 * @param file 선택할 파일.
		 */
		set file(file: File) {

			this._setFiles([file]);
			this.redraw();
		}

		/**
		 * 선택된 파일들을 배열로 반환합니다.
		 * @return 다중 선택된 파일의 배열.
		 */
		get files(): File[] {
			return this._files;
		}

		/**
		 * 다중 선택된 파일을 배열로 지정합니다.
		 * @param files 다중 선택할 파일의 배열.
		 */
		set files(files: File[]) {
			this._setFiles(files);
			this.redraw();
		}

		/**
		 * 파일 열기 창에서 보여줄 파일 확장자를 반환합니다. 
		 * @return 확장명 또는 적용되는 파일의 형식.
		 */
		get acceptFile(): string {
			return this._bindables.get("acceptFile");
		}

		/**
		 * 파일 열기 창에서 보여줄 파일 확장자를 설정합니다.
		 * HTML5의 accept 형식과 동일합니다.
		 * @param acceptFile 확장명 또는 적용되는 파일의 형식.
		 */
		set acceptFile(acceptFile: string) {
			this._bindables.set("acceptFile", acceptFile);
		}

		/**
		 * 선택할 수 있는 파일의 최대 데이터 크기를 반환합니다.
		 * @return 선택할 수 있는 파일의 최대 데이터 크기.
		 */
		get limitFileSize(): string {
			return this._bindables.get("limitFileSize") + this._bindables.get("limitFileSizeUnit");
		}

		/**
		 * 선택할 수 있는 파일의 최대 데이터 크기를 제한합니다.
		 * @param size 선택할 수 있는 파일들의 최대 데이터 크기. Ex) "10kb"
		 */
		set limitFileSize(size: string) {
			let fileSize: cpr.utils.Size = utils.ParamUtil.parseSize(size);
			this._bindables.set("limitFileSize", fileSize.size);
			this.limitFileSizeUnit = fileSize.unit;
			// this._bindables.set("limitFileSizeUnit", fileSize.unit);
		}

		/**
		 * 선택할 수 있는 파일의 최대 크기를 제한할 단위를 반환합니다.
		 * 기본 값은 kb 입니다.
		 * @return 파일 크기 제한 단위.
		 */
		get limitFileSizeUnit(): string {
			return this._bindables.get("limitFileSizeUnit");
		}

		/**
		 * 선택할 수 있는 파일의 최대 크기를 제한할 단위를 설정합니다.
		 * @param 파일 크기 제한 단위.(byte, kb, mg, gb)
		 */
		set limitFileSizeUnit(unit: string) {
			if (!unit) {
				return;
			}
			unit = unit.toLowerCase();
			let sizeUnit: FileUnitType = FileUnitType[unit];
			if (sizeUnit == null) {
				return;
			}
			this._bindables.set("limitFileSizeUnit", unit);
		}

		/**
		 * 업로드 할 수 있는 파일당 최대 데이터 크기을 제한합니다.
		 * @param size 업로드 할 수 있는 파일당 최대 데이터 크기. Ex) "10kb" 
		 */
		set limitSizePerFile(size: string) {
			let fileSize: cpr.utils.Size = utils.ParamUtil.parseSize(size);
			this._bindables.set("limitSizePerFile", fileSize.size);
			this.limitSizePerFileUnit = fileSize.unit;
		}

		/**
		 * 업로드 할 수 있는 파일당 최대 데이터 크기를 반환합니다.
		 * @return 업로드 할 수 있는 파일당 최대 데이터 크기.
		 */
		get limitSizePerFile(): string {
			return this._bindables.get("limitSizePerFile") + this._bindables.get("limitSizePerFileUnit");
		}

		/**
		 * 선택할 수 있는 개별 파일의 최대 크기를 제한할 단위를 설정합니다.
		 * @param 개별 파일 크기 제한 단위.(byte, kb, mg, gb)
		 */
		set limitSizePerFileUnit(unit: string) {
			if (!unit) {
				return;
			}
			unit = unit.toLowerCase();
			let sizeUnit: FileUnitType = FileUnitType[unit];
			if (sizeUnit == null) {
				return;
			}
			this._bindables.set("limitSizePerFileUnit", unit);
		}

		/**
		 * 선택할 수 있는 개별 파일의 최대 크기를 제한할 단위를 반환합니다.
		 * 기본 값은 kb 입니다.
		 * @return 개별 파일 크기 제한 단위.
		 */
		get limitSizePerFileUnit(): string {
			return this._bindables.get("limitSizePerFileUnit");
		}

		/**
		 * clear버튼 이미지를 반환합니다.
		 * @return clear버튼 이미지.
		 */
		get clearButtonImage(): string {
			return this._bindables.get("clearButtonImage");
		}
		/**
		 * clear버튼 이미지를 설정합니다.
		 * @param src clear버튼 이미지.
		 */
		set clearButtonImage(src: string) {
			this._bindables.set("clearButtonImage", src);
		}

		/**
		 * clear버튼의 표시여부를 반환합니다
		 * @return clear버튼 표시여부
		 */
		get showClearButton() {
			return this._bindables.get("showClearButton");
		}

		/**
		 * clear버튼의 표시여부를 설정합니다.
		 * @param showClearButton clear버튼 표시여부설정.
		 */
		set showClearButton(showClearButton: boolean) {
			this._bindables.set("showClearButton", showClearButton)
		}

		/**
		 * 버튼에 포커스를 설정값을 반환합니다.
		 * @return 버튼 포커스 여부
		 */
		get buttonFocusable() {
			return this._buttonFocusable;
		}

		/**
		 * 버튼에 포커스를 설정합니다.
		 * @param focusable 버튼 포커스 여부
		 */
		set buttonFocusable(focusable: boolean) {
			this._buttonFocusable = focusable;
			this.redraw();
		}

		public _createShape(): cpr.ufc.ControlShape {
			let displayText = this._getDisplayText();
			let placeholderClassNames: string[] = [];
			if (displayText.length == 0) {
				displayText = this.placeholder;
				placeholderClassNames = [ufc.Classes.PLACEHOLDER]
			}
			let templateColumns = [];

			let textShape: ufc.ElementShape = {
				tag: "div",
				attr: {},
				style: {
					overflow: "hidden",
					textOverflow: "inherit",
				},
				children: [displayText]
			}
			layouts.GridCSSBuilder._forCell()._withColumnStart(1)._withRowStart(1)._withVerticalAlign(layouts.GridCellAlign.center)._commit(textShape.style);
			let textWrap: ufc.ControlShape = {
				tag: "div",
				classNames: [ufc.Classes.TEXT, ufc.Classes.UNSELECTABLE].concat(placeholderClassNames),
				attr: {
					tabindex: "0",
					role: "button",
					"aria-haspopup": "true"
				},
				style: {},
				children: [textShape]
			};
			layouts.GridCSSBuilder._forLayout()._withVerticalAlign(layouts.GridLayoutAlign.center)._withTemplateColumns("1fr")._withTemplateRows("1fr")._commit(textWrap.style);
			cpr.ufc.ShapeUtil._setAriaLabelAttr(textWrap.attr, this._getFieldLabel());
			cpr.ufc.ShapeUtil._setTooltipAttr(textWrap, { owner: this, title: this.tooltip });
			cpr.ufc.ShapeUtil._setAriaDisabled(textWrap, this.enabled && !this.readOnly);
			layouts.GridCSSBuilder._forCell()._withColumnStart(1)._withRowStart(1)._commit(textWrap.style);
			templateColumns.push("1fr");

			let grid: ufc.ControlShape = {
				tag: "div",
				style: {
					height: "100%"
				},
				children: [textWrap]
			};

			if (this.showClearButton) {
				let clearBtn = this.createClear();
				grid.children.push(clearBtn);
				layouts.GridCSSBuilder._forCell()._withColumnStart(2)._withRowStart(1)._withVerticalAlign(layouts.GridCellAlign.center)._commit(clearBtn.style);
				templateColumns.push("auto");
			}
			layouts.GridCSSBuilder._forLayout()._withVerticalAlign(layouts.GridLayoutAlign.center)._withTemplateColumns(templateColumns)._withTemplateRows("1fr")._commit(grid.style);

			let shape: ufc.ControlShape = {
				tag: "div",
				styler: "root",
				attr: {},
				children: [grid],
				events: {
					click: this._onclick, // shape event에서는 readonly일때 전파를 방지 한다.
					keydown: this._onkeydown,
					dragover: this._ondragover,
					mousedown: this._onmousedown,
					drop: this._ondrop
				},
				//스펙상 사용자에게 drop을 제공하지 않음.
				eventTargets: [
					ufc.EventTargetType.UICONTROL,
					ufc.EventTargetType.DROPPABLE
				]
			};
			cpr.ufc.ShapeUtil._setTooltipAttr(shape, { owner: this, title: this.tooltip });
			if (this.enabled == false) {
				delete textShape.attr['tabindex'];
			}

			if (this.readOnly == true) {
				shape.events = {};
			}
			return shape;
		}

		/**
		 * Clear버튼 생성
		 */
		private createClear(): cpr.ufc.ControlShape {
			let button: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: ["cl-fileinput-clear"],
				styler: "clear",
				attr: {
					role: "button",
					"aria-hidden": "true",
					"aria-label": this._getLabel(cpr.I18N.INSTANCE.message(core.PlatformTerms.CLEAR), this._getInternalProperty("clearLabelExp"))
				},
				style: {
					height: "100%"
				},
				nodename: "clear",
				events: {}
			}

			if (this.clearButtonImage != "") {
				button.style['background-image'] = _quoteAsCSSURL(this.clearButtonImage);
			}

			if (this.enabled) {
				if (this.readOnly) {
					button.events = {};
				} else {
					if (this.buttonFocusable) {
						delete button.attr["aria-hidden"];
						button.attr['tabindex'] = "0";// IE에서 포커스 아웃라인이 -1이면 표시되지 않음.
						button.events["keydown"] = this._onBtnClearKeydown;
					}
				}
			}
			cpr.ufc.ShapeUtil._setAriaDisabled(button, this.enabled && !this.readOnly);

			let displayText = this._getDisplayText();
			let isVisibleClearButton = this.showClearButton && displayText.length > 0 && this.readOnly == false && this.enabled;
			if (isVisibleClearButton == false) {
				button.style["display"] = "none";
			}

			return button;
		}

		private _isHiddenClearButton() {
			let clearNode = this._getRenderer().getNamedNode("clear");
			if (!clearNode) {
				return true;
			}
			return clearNode.style.display == "none";
		}

		/* event start */
		private _onkeydown(e: events.CKeyboardEvent) {
			if (e.defaultPrevented) {
				return;
			}
			let target = e.target as HTMLElement;
			switch (e.keyCode) {
				case events.KeyCode.ESC:
					if (target.classList.contains(ufc.Classes.TEXT) == false || this.showClearButton == false) {
						break;
					}
					this._clearTextByESC(e);
					e.preventDefault();
					break;
				case events.KeyCode.ENTER:
				case events.KeyCode.SPACE: {
					let clickEvent = new cpr.events.CMouseEvent("click");
					clickEvent.nativeEvent = e;
					let processContiue = this.dispatchEvent(clickEvent);
					if (processContiue) {
						this._openFileChooser();
					}
					e.stopPropagation();
					e.preventDefault();
					break;
				}
				case events.KeyCode.TAB: {
					if (this.buttonFocusable == false) {
						break;
					}
					if (e._getMod2Key()) {
						this._focusPrevious(true);
						e.preventDefault();
					} else {
						this._focusNext(true);
						e.preventDefault();
					}
					break;
				}

			}
		}

		private _onmousedown(e: events.CMouseEvent) {
			if (e.defaultPrevented) {
				return;
			}
			let currentTarget = <HTMLElement>e.currentTarget;
			let target: HTMLElement = e.target as HTMLElement;

			// 마우스의 타겟이 컨트롤의 기본 포커스 요소가 아니면 포커스를 설정하지 못하도록 막고 기본 포커스로 설정해야 한다.
			let focusableElement: Element = null; // 기본포커스 엘리먼트 focus() API참고.
			let domTraverser = ufc._traverseFromElement(currentTarget)._find('[tabindex]');
			if (domTraverser) {
				focusableElement = domTraverser._getElement();
			}
			if (focusableElement != target) {
				e.preventDefault();
				if (this.buttonFocusable) {
					if (this.focused == false) {
						super._focusImmediately();
					}
				} else {
					if (focusableElement != document.activeElement) {
						super._focusImmediately();
					}
				}
			}
		}

		private _onclick(e: events.CMouseEvent) {
			if (e.defaultPrevented) {
				return;
			}
			let target = e.target as HTMLDivElement;
			if (target.classList.contains("cl-fileinput-clear")) {
				this._onClearButtonClick(e);
			} else {
				this._openFileChooser();
			}
		}

		// disabled인 경우에도 openFileChooser가 발생하도록 수정
		public override _checkControlStateForEvent(e: events.CEvent = null): boolean {
			if (e && e.option) {
				let isApiCall = e.option.source == "api";
				if (isApiCall) {
					return true;
				}
			}
			if (e.type == events.ValueChangeEventType.BEFORECHANGE) {
				if (!e.targetObject) {
					e._setTargetObject({ files: [] });
				} else if (!e.targetObject.files) {
					e._setTargetObject({ files: [] });
				}
				return true;
			}

			return super._checkControlStateForEvent(e);
		}

		private _ondragover(e: events.CMouseEvent) {
			if (e.defaultPrevented) {
				return;
			}
			e.preventDefault();
			if (this.droppableFile == false) {
				e.dataTransfer.dropEffect = "none";
				return;
			}
			e.dataTransfer.dropEffect = "move";
		}

		private _ondrop(e: events.CMouseEvent) {
			if (e.defaultPrevented) {
				return;
			}
			e.preventDefault();
			if (this.droppableFile == false) {
				return;
			}
			let files = e.dataTransfer.files;
			if (files.length == 0) {
				return;
			}

			this.files = utils.Util.toArray(files) as File[];
		}

		private _onClearButtonClick(e: events.CMouseEvent) {
			this._clearValue(e);
			if (this.disposed || !this.focused) {
				return;
			}
			if (e.target == document.activeElement && this.value == "") {
				super._focusImmediately();
			}
		}
		/* event end */

		/* private method */
		private _getDisplayText() {
			return this.value != null ? this.value : "";
		}
		/**
		 * file과 value 변경에 따라 value-change 이벤트가 발생합니다.
		 */
		private _setFiles(files: File[]) {
			let oldValue: string = this.value;
			files = files.filter(function (each) {
				if (each != null) {
					return true;
				}
				return false;
			})

			let totalLimitSize = this._getTotalLimitSize();
			let eachLimitSize = this._getEachLimitSize();

			let overflowSizeFiles: File[] = [];
			let addedFiles: File[] = [];
			let currentTotalSize = 0;

			for (let i = 0; i < files.length; i++) {
				let each = files[i];
				if (eachLimitSize >= 0 && each.size > eachLimitSize) {
					overflowSizeFiles.push(each);
					continue;
				}

				if (totalLimitSize >= 0 && (currentTotalSize + each.size > totalLimitSize)) {
					overflowSizeFiles.push(each);
					continue;
				}

				currentTotalSize += each.size;
				addedFiles.push(each);
			}

			if (overflowSizeFiles.length > 0) {
				// max size exceed event
				this.dispatchEvent(new cpr.events.CFileUploadEvent(cpr.events.FileUploadEventType.MAXSIZE_EXCEED, { files: overflowSizeFiles }));
				if (addedFiles.length == 0) {
					return;
				}
			}

			files = addedFiles;

			let newValue = this._extractFileNames(files);

			//before-change-event
			let beforeChangeEvent = new cpr.events.CValueChangeEvent(events.ValueChangeEventType.BEFORECHANGE
				, { oldValue: oldValue, newValue: newValue });
			beforeChangeEvent._setTargetObject({ files: files });
			if (!this.dispatchEvent(beforeChangeEvent)) {
				return;
			}
			//set file & value
			this._files = files ?? [];
			this._bindables.set("value", newValue ? newValue : ""); // this.value를 사용하면 값 중복이 체크되어 이벤트가 발생하지 않을 수 있기 때문에 직접 사용함.
			//value-change가 동일한 이름이어도 발생되어야 한다. 파일명이 같아도 내용이 다를 수 있음.
			this.dispatchEvent(new cpr.events.CValueChangeEvent(events.ValueChangeEventType.CHANGE
				, { oldValue: oldValue, newValue: newValue }));

		}

		/**
		 * 파일들의 이름을 구분하여 delimiter로 반환합니다.
		 * @param files 
		 */
		private _extractFileNames(files: File[]): string {
			let value = "";
			for (let i = 0; i < files.length; i++) {
				if (files[i] == null) {
					continue;
				}
				value += i == 0 ? files[i].name : this.delimiter + files[i].name;
			}
			return value;
		}
		private _getEachLimitSize() {
			let eachFileSize: cpr.utils.Size = utils.ParamUtil.parseSize(this.limitSizePerFile);
			let eachUnit: FileUnitType = FileUnitType[eachFileSize.unit.toLowerCase()];
			let eachSize: number = -1;
			if (eachUnit == null) eachUnit = FileUnitType.kb;
			if (eachFileSize != null && eachFileSize.size >= 0) {
				eachSize = eachFileSize.size * eachUnit;
			}
			return eachSize;
		}

		private _getTotalLimitSize() {
			let fileSize: cpr.utils.Size = utils.ParamUtil.parseSize(this.limitFileSize);
			let unit: FileUnitType = FileUnitType[fileSize.unit.toLowerCase()];
			let maxSize: number = -1;
			if (unit == null) unit = FileUnitType.kb;
			if (fileSize != null && fileSize.size >= 0) {
				maxSize = fileSize.size * unit;
			}
			return maxSize;
		}

		/**
		* Clear버튼을 숨깁니다.
		*/
		private _hideClear() {
			this._getRenderer().updateStyle("clear", { display: "none" }, true);
		}

		/**
		 * Clear버튼을 표시합니다.
		 */
		private _showClear() {
			this._getRenderer().updateStyle("clear", { display: "table-cell" }, true)
		}

		/**
		 * 텍스트박스에서만 사용되는 키 이벤트. 초점은 항상 텍스트에 있음
		 * @param e 
		 * @returns 
		 */
		private _clearTextByESC(e: events.CKeyboardEvent) {
			if (this.readOnly || this._isHiddenClearButton()) {
				return;
			}
			this._clearValue(e);
		}

		private _clearValue(e?: events.CEvent): void {
			//clear이벤트 생성
			let clearEvent = new cpr.events.CEvent("clear");
			if (e) {
				clearEvent.nativeEvent = e;
			}
			let processContinue = this.dispatchEvent(clearEvent);
			if (!processContinue) {
				return;
			}

			if (this.value) {
				this._setFiles([]);
			}
		}

		/**
		 * 버튼에서 발생하는 키 이벤트. 초점은 항상 클리어 버튼에 있음.
		 * @param e 
		 * @returns 
		 */
		private _onBtnClearKeydown(e: events.CKeyboardEvent) {
			if (this.readOnly) {
				return;
			}
			let keyCode = e.keyCode;

			if (keyCode == events.KeyCode.SPACE || keyCode == events.KeyCode.ENTER) {
				e.preventDefault();
				this._clearValue(e);
				if (this.disposed) {
					return;
				}
				if (this.value != "") {
					return;
				}
				super._focusImmediately();
			}
		}

		private _openFileChooser(): void {
			utils.FileDialog.INSTANCE.open({ multiple: this.multiple, accept: this.acceptFile }, (files) => {
				if (files.length == 0) {
					this._hideClear();
					return;
				}
				this.files = files;
				if (this.disposed) {
					return;
				}
				this._showClear();
			})
		}

		/* public method */

		/**
		 * 파일 열기 상자를 엽니다. 
		 */
		public openFileChooser(): void {
			let processContinue: boolean = this.dispatchEvent(new events.CMouseEvent("click", { source: "api" }));
			if (processContinue) {
				this._openFileChooser();
			}
		}

		/**
		 * 파일을 업로드 합니다.
		 * 파일이 없는 경우 전송하지 않습니다.
		 * @param submission 파일 업로드에 필요한 submission.
		 */
		public send(submission: cpr.protocols.Submission): void {
			if (submission == null) {
				return;
			}

			let files = this.files;
			// 파일이 없는 경우 전송 방지
			if (!files || files.length === 0) {
				return;
			}

			let paramName = this.id || "file";

			submission.mediaType = protocols.Submission.MEDIA_MULTIPART;
			submission.removeParameters(paramName);

			files.forEach((each: File) => {
				submission.addFileParameter(paramName, each);
			});

			submission.send();
		}

		/**
		* Clear 이벤트를 발생합니다.<br>
		* clear 이벤트에 해당하는 eventlistener의 함수를 수행합니다.
		*/
		public clear(): void {
			if (!this.value) {
				return;
			}
			this._clearValue();

			if (this.disposed || !this.focused) {
				return;
			}
			let activeFocusEntry = this._getActiveFocusEntry();
			if (this._clearBtnFocusEntry == activeFocusEntry && this.value == "") {
				super._focusImmediately();
			}
		}

		public _getFocusEntries(): FocusEntry[] {
			let focusEntries = [this._textFocusEntry];
			let renderer = this._getRenderer();

			if (this.buttonFocusable == false) {
				return focusEntries;
			}
			let clearBtn = renderer.getNamedNode("clear");

			if (clearBtn && !this._isHiddenClearButton()) focusEntries.push(this._clearBtnFocusEntry);

			return focusEntries;
		}

		public _getActiveFocusEntry(): FocusEntry {
			let activeElement = document.activeElement as HTMLElement;
			if (!activeElement) {
				return null;
			}
			let classList = activeElement.classList;
			if (classList.contains(FileInputClassName.clear)) {
				return this._clearBtnFocusEntry;
			} else {
				return this._textFocusEntry;
			}
		}

		override _focusPrevious(includeEntry: boolean = false) {
			if (includeEntry) {
				new FileInputFocusRing(this, this._getActiveFocusEntry())._focusPrevious();
			} else {
				super._focusPrevious(includeEntry);
			}
		}

		override _focusNext(includeEntry: boolean = false) {
			if (includeEntry) {
				new FileInputFocusRing(this, this._getActiveFocusEntry())._focusNext();
			} else {
				super._focusNext(includeEntry);
			}
		}

		public _focusBySelector(selector: string, immediate: boolean = false) {
			if (immediate) {
				this._focusImmediateBySelector(selector);
			} else {
				core.DeferredUpdateManager.INSTANCE._performFocusTask(() => {
					this._focusImmediateBySelector(selector);
				});
			}
		}

		private _focusImmediateBySelector(selector: string) {
			if (this.disposed == false && this.focusable) {
				let node = this._getRenderer().getRootNode();
				if (node) {
					let focusible = node.querySelector(selector) as HTMLElement;
					if (focusible) {
						focusible.focus();
					}
				}
			}
		}

		/**
		 * @override 그리드에서 탭 이동시 이전과 다음에 따라 동작 할 수 있도록 제공
		 * @param forward 
		 */
		public override _focusImmediately(forward: boolean = true): void {
			let focusEntries = this._getFocusEntries() as FileInputFocusEntry[];
			if (forward) {
				focusEntries[0].focusImmediately();
			} else {
				focusEntries[focusEntries.length - 1].focusImmediately();
			}
		}

		public _exportValue(): string | number {
			let ctrlText = this.value

			// 기본 >> text
			return (ctrlText != null) ? "" + ctrlText : "";
		}
	}
}
