namespace cpr.expression {

	export type CompiledExpressionFunction = Function & {
		syntaxError?: Error,
		sortHint?: "asc" | "desc",
		precompiled?: boolean
	};

	export function _asExpression(expressionLike: Expression | Function): Expression {
		return typeof expressionLike == "function"
			? new Expression(expressionLike)
			: expressionLike;
	}


	/**
	 * 표현식을 사용하는 클래스.
	 */
	export class Expression {
		public static _PRECOMPILED_FUNCTION = "precompiled function";

		private _src: expression_string;
		private _functions: CompiledExpressionFunction[];

		/**
		 * 새 표현식 객체를 만듭니다.
		 * @param src 표현식 문자열.
		 */
		constructor(src: expression_string | Function) {
			if (typeof src == "function") {
				this._src = Expression._PRECOMPILED_FUNCTION;
				(src as CompiledExpressionFunction).precompiled = true;
				this._functions = [src];
			} else {
				this._src = src;
			}
		}

		/**
		 * 컴파일 할 소스
		 */
		get src(): expression_string {
			return this._src;
		}
		/**
		 * 컴파일 할 소스를 설정합니다.
		 */
		set src(src: expression_string) {
			let before: string = this.src;
			this._src = src;
			if (before != src) {
				this._functions = null;
			}
		}

		/**
		 * 컴파일된 함수들을 얻습니다.
		 */
		private _getFunctions(): CompiledExpressionFunction[] {
			if (!this._functions) {
				let fnOrFns = ExpressionEngine.INSTANCE.compile(this._src);
				if (fnOrFns instanceof Array) {
					this._functions = fnOrFns;
				} else {
					this._functions = [fnOrFns];
				}
			}
			return this._functions;
		}

		/**
		 * 소스에 컴파일된 함수들을 모두 평가한 결과를 반환합니다.
		 * @param self 
		 */
		public evaluateAll(self: any): any[] {
			let result = this._getFunctions().map(fn => {
				return fn(self);
			});
			return result;
		}

		/**
		 * 소스에 컴파일된 함수 중 첫번째만 평가 결과를 반환합니다.
		 * @param self 
		 */
		public evaluateFirst(self: any): any {
			let result = this._getFunctions().map(fn => {
				return fn(self);
			});
			return result[0];
		}

		/**
		 * 소스에 컴파일된 함수의 평가 결과를 반환합니다. array 또는 object를 반환합니다.
		 * @param self 
		 */
		public evaluate(self: any): any | any[] {
			let result = this._getFunctions().map(fn => {
				return fn(self);
			});
			if (result.length > 1) {
				return result;
			} else {
				return result[0];
			}
		}

		/**
		 * 명시적으로 EvaluationContext를 이용해 익스프레션을 평가합니다.
		 * @param context 평가 문맥.
		 */
		public _evaluateInternal(context: expression.EvaluationContext) {
			return this.evaluate(context)
		}

		/**
		 * 익스프레션을 mapper로 반환합니다.
		 */
		public asMapper(): (e: any) => any {
			let mapper = this._getFunctions()[0];
			return function (it: any) {
				return mapper(it);
			};
		}

		/**
		 * 익스프레션을 필터로 반환합니다.
		 */
		public asFilter(): (e: any) => boolean {
			let filter = this._getFunctions()[0];
			if (this.hasSyntaxError()) {
				return function (it: any) {
					return false;
				};
			}

			return function (it: any) {
				return filter(it) ? true : false;
			};
		}

		/**
		 * 익스프레션 값을 비교합니다.
		 */
		public asComparator(): (a: any, b: any) => number {
			let pluckFunctions = this._getFunctions();
			return (a: any, b: any) => {
				for (let i = 0; i < pluckFunctions.length; i++) {
					let eachFn = pluckFunctions[i];
					let multiplier = 1;
					if (eachFn.sortHint == 'desc') {
						multiplier = -1;
					}

					let pa = eachFn(a);
					let pb = eachFn(b);

					if (pa !== pb) {
						if (pa === null) {
							return 1;
						} else if (pb === null) {
							return -1;
						} else {
							// DecimalType 처리
							if (pa instanceof foundation.DecimalType) {
								let equality: number = pa.compareTo(pb);
								if (equality != null && _.isNaN(equality) == false) {
									if (equality === 0) {
										continue;
									}
									return equality > 0 ? multiplier : -multiplier;
								}
							} else if (pb instanceof foundation.DecimalType) {
								let equality: number = pb.compareTo(pa);
								if (equality != null && _.isNaN(equality) == false) {
									if (equality === 0) {
										continue;
									}
									return equality > 0 ? -multiplier : multiplier;
								}
							}

							if (pb === "" && pa !== "") {
								return multiplier;
							} else if (pa === "" && pb !== "") {
								return -multiplier;
							} else {
								return pa > pb ? multiplier : -multiplier;
							}
						}
					}
				}
				return 0;
			};
		}

		/**
		 * 이 표현식과 다른 표현식들을 AND 조건으로 조합된 표현식을 얻습니다.
		 * @param expressions 
		 */
		public and(...expressions: Expression[]): ComposedExpression {
			let exps: Expression[] = [];
			exps.push(this);
			exps = exps.concat(expressions);
			return new ComposedExpression(ComposeOperator.AND, exps);
		}

		/**
		 * 이 표현식과 boolean을 반환하는 함수들과 AND 조건으로 조합된 표현식을 얻습니다.
		 * @param predicates 
		 * @returns 
		 */
		public _and(...predicates: (Function | Expression)[]): ComposedExpression {
			let exps = [
				this,
				...predicates.map(it => typeof it == "function" ? new Expression(it) : it)
			];
			return new ComposedExpression(ComposeOperator.AND, exps);
		}

		/**
		 * 여러 익스프레션을 지정하여 ComposedExpression을 반환합니다. 반환된 ComposedExpression을 통하여 두개의 필터 중 익스프레션 결과 중 하나 맞는지 등을 확인 할수 있습니다.
		 * @param expressions 
		 */
		public or(...expressions: Expression[]): ComposedExpression {
			let exps: Expression[] = [];
			exps.push(this);
			exps = exps.concat(expressions);
			return new ComposedExpression(ComposeOperator.OR, exps);
		}

		/**
		 * 이 표현식과 boolean을 반환하는 함수들과 OR 조건으로 조합된 표현식을 얻습니다.
		 * @param predicates 
		 * @returns 
		 */
		public _or(...predicates: (Function | Expression)[]): ComposedExpression {
			let exps = [
				this,
				...predicates.map(it => typeof it == "function" ? new Expression(it) : it)
			];
			return new ComposedExpression(ComposeOperator.OR, exps);
		}

		public hasSyntaxError(): boolean {
			return _stream(this._getFunctions())
				.exists(it => (it as CompiledExpressionFunction).syntaxError != null)
		}

		/**
		 * 사전 컴파일된 펑션을 가진 표현식인지를 얻습니다.
		 * @returns 
		 */
		public _isPrecompiledFunction(): boolean {
			if (!this._functions) {
				return false;
			}
			return this._functions[0].precompiled === true;
		}

		toString(): string {
			return this._src;
		}

		valueOf(): string {
			return this._src;
		}
	}
}