/// <reference path="IEventTarget.ts"/>
/// <reference path="EventTable.ts"/>


namespace cpr.events {
	/**
	 * DOM Event 중 Document, Body 등에서만 listener이 가능한 이벤트를 처리하는 EventTarget.
	 * 
	 * @fires cpr.events.CKeyboardEvent#keydown 키를 눌렀을때 body에서 발생하는 이벤트.
	 * 
	 * @fires cpr.events.CEvent#unload 페이지 전체가 해제될 때 발생하는 이벤트. 이 이벤트는 deprecated 되어 pagehide 이벤트를 사용하세요.
	 * 
	 * @fires cpr.events.CPageTransitionEvent#pagehide 페이지가 숨겨지거나 제거될 때 발생하는 이벤트.
	 * 
	 * @fires cpr.events.CEvent#paste 붙여넣기 했을때 body에서 발생하는 이벤트.
	 * 
	 * @fires cpr.events.CMouseEvent#mousemove 마우스를 이동할때 window에서 발생하는 이벤트.
	 * 
	 * @fires cpr.events.CMouseEvent#mouseup 마우스 버튼을 떼었을때 window에서 발생하는 이벤트.
	 * 
	 * @fires cpr.events.CTouchEvent#touchmove 터치 후 이동할때 window에서 발생하는 이벤트.
	 * 
	 * @fires cpr.events.CTouchEvent#touchend 터치를 떼었을때 window에서 발생하는 이벤트.
	 * 
	 * @fires cpr.events.CUIEvent#resize 창 크기 조절했을때 window에서 발생하는 이벤트.
	 * 
	 * @fires cpr.events.CUIEvent#scroll 창의 스크롤을 움직였을때 window에서 발생하는 이벤트.
	 * 
	 */
	export class BodyEventTarget implements IEventTarget {
		private _eventTable: EventTable;
		private _captureEventTable: EventTable;
		private _listenerFunc: EventListener = (e) => this._processEvent(e);
		private _captureListenerFunc: EventListener = (e) => this._processCaptureEvent(e);

		/**
		 * BodyEventTarget의 인스탄스
		 */
		static get INSTANCE(): BodyEventTarget {
			return BODYEVENTTARGET;
		}

		constructor() {
			this._eventTable = new EventTable();
			this._captureEventTable = new EventTable();
			this._init();
		}

		private _init(): void {
			if (document && document.readyState === "complete") {
				window.setTimeout(() => {
					this._setGlobalEventHandler();
				});
			} else {
				window.addEventListener("load", (e: Event) => {
					this._setGlobalEventHandler();
				});
			}
		}

		/**
		 * window와 document.body에 이벤트 핸들러를 등록합니다.<br>
		 * window에 등록해야 이벤트 트리 최상단이기 때문에 캡처링 단계에서 이벤트를 처리할 수 있습니다.(일반 이벤트보다 우선 처리됨)
		 */
		private _setGlobalEventHandler(): void {
			// (Window, HTMLBodyElement)global event로 처리해야만 하는 이벤트를 등록한다.
			if (_isIE()) {
				window.addEventListener("unload", this._listenerFunc);
				window.addEventListener("unload", this._captureListenerFunc, true);
			}

			document.body.addEventListener("paste", this._listenerFunc);
			document.body.addEventListener("paste", this._captureListenerFunc, true);
			document.body.addEventListener("keydown", this._listenerFunc);
			document.body.addEventListener("keydown", this._captureListenerFunc, true);
			window.addEventListener("mousemove", this._listenerFunc);
			window.addEventListener("mousemove", this._captureListenerFunc, true);
			window.addEventListener("mouseup", this._listenerFunc);
			window.addEventListener("mouseup", this._captureListenerFunc, true);
			window.addEventListener("touchmove", this._listenerFunc);

			if (_detectBrowser().supportsPassiveEvent) {
				window.addEventListener("touchmove", this._captureListenerFunc, {
					passive: false,
					capture: true
				});
			} else {
				window.addEventListener("touchmove", this._captureListenerFunc, true);
			}

			window.addEventListener("touchend", this._listenerFunc);
			window.addEventListener("touchend", this._captureListenerFunc, true);

			if (_detectBrowser().isAndroid) {
				window.addEventListener("resize", AndroidResizeHandler._getInstance()._getResizeHandler());
			} else {
				window.addEventListener("resize", _.throttle(this._listenerFunc, 50, { leading: false })); // throttling
				window.addEventListener("resize", this._captureListenerFunc, true);
			}

			window.addEventListener("scroll", this._listenerFunc);
			window.addEventListener("scroll", this._captureListenerFunc, true);
			window.addEventListener("scroll", this._notifyScrollEvent);

			window.addEventListener("dragover", this._listenerFunc);
			window.addEventListener("dragover", this._captureListenerFunc, true);

			// TooltipManager에서 사용 mousedown, mouseover, mouseout, wheel
			window.addEventListener("mousedown", this._listenerFunc);
			window.addEventListener("mousedown", this._captureListenerFunc, true);
			window.addEventListener("mouseover", this._listenerFunc);
			window.addEventListener("mouseover", this._captureListenerFunc, true);
			window.addEventListener("mouseout", this._listenerFunc);
			window.addEventListener("mouseout", this._captureListenerFunc, true);
			window.addEventListener("wheel", this._listenerFunc);
			window.addEventListener("wheel", this._captureListenerFunc, true);
		}

		private _notifyScrollEvent(e: Event): void {
			let eventWrapper: cpr.events.CEvent = cpr.events.wrap(e);
			core.NotificationCenter.INSTANCE.post(core.SystemTopics.SCROLL, eventWrapper, this);
		}

		public _processEvent(e: Event): void {
			let eventWrapper: cpr.events.CEvent = cpr.events.wrap(e);
			this.dispatchEvent(eventWrapper);
		}

		public _processCaptureEvent(e: Event): void {
			let eventWrapper: cpr.events.CEvent = cpr.events.wrap(e);
			// capture 이벤트 핸들러는 이벤트 동작을 원천 차단하는 동작을 수행할 수 있고
			// 버블링에 의한 동작에서 이미 이벤트 필터링을 동작시키기 때문에 필터를 실행하지 않음.
			this._captureEventTable.dispatchEvent(eventWrapper);
		}

		/**
		 * EventType 별 Listener를 추가합니다.<br>
		 * 특정 Event가 발생했을 때 처리하는 Listener를 추가합니다.
		 * <pre><code>
		 * cpr.events.BodyEventTarget.addEventListener("resize", function(e) {
		 * 	// event code...
		 * });
		 * </code></pre>
		 * 
		 * @param type 이벤트 타입.
		 * @param listener 이벤트 리스너.
		 */
		public addEventListener(type: string, listener: (e: CEvent) => void): void {
			this._eventTable.addEventListener(type, listener);
		}

		public _addCaptureEventListener(type: string, listener: (e: CEvent) => void): void {
			this._captureEventTable.addEventListener(type, listener);
		}

		/**
		 * EventType 별 한 번만 실행할 Listener를 추가합니다.<br>
		 * 특정 Event가 발생했을 때 처리하는 Listener를 추가합니다.
		 * 추가된 Listener는 한번 실행된 후 자동으로 삭제됩니다.
		 * 추가된 Listener는 객체가 변경되므로 Listener 삭제 시
		 * addEventListenerOnce 호출 후 리턴되는 객체로 삭제가 가능합니다.
		 * <pre><code>
		 * cpr.events.BodyEventTarget.addEventListenerOnce("resize", function(e) {
		 * 	// event code...
		 * });
		 * </code></pre>
		 * 
		 * @param type 이벤트 타입.
		 * @param listener 이벤트 리스너.
		 * @return 변경된 Listener 객체.
		 */
		public addEventListenerOnce(type: string, listener: (e: cpr.events.CEvent) => void): void {
			let handler: (e: cpr.events.CEvent) => void = (e: cpr.events.CEvent) => {
				listener(e);
				this._eventTable.removeEventListener(type, handler);
			};
			this._eventTable.addEventListener(type, handler);
		}

		public _addCaptureEventListenerOnce(type: string, listener: (e: cpr.events.CEvent) => void): void {
			let handler: (e: cpr.events.CEvent) => void = (e: cpr.events.CEvent) => {
				listener(e);
				this._captureEventTable.removeEventListener(type, handler);
			};
			this._captureEventTable.addEventListener(type, handler);
		}

		/**
		 * EventType 별 Listener를 제거합니다.<br>
		 * <pre><code>cpr.events.BodyEventTarget.removeEventListener('resize', listener);</code></pre>
		 * @param type 이벤트 타입.
		 * @param listener 이벤트 리스너.
		 */
		public removeEventListener(type: string, listener: (e: CEvent) => void): void {
			this._eventTable.removeEventListener(type, listener);
		}

		public _removeCaptureEventListener(type: string, listener: (e: CEvent) => void): void {
			this._captureEventTable.removeEventListener(type, listener);
		}

		/**
		 * EventType의 모든 Listener 들을 제거합니다.<br>
		 * <pre><code>cpr.events.BodyEventTarget.removeEventListeners('resize');</code></pre>
		 * @param type 이벤트 타입.
		 */
		public removeEventListeners(type: string): void {
			this._eventTable.removeEventListeners(type);
		}

		public _removeCaptureEventListeners(type: string): void {
			this._captureEventTable.removeEventListeners(type);
		}

		/**
		 * 모든 이벤트 Listener를 제거합니다.
		 */
		public removeAllEventListeners(): void {
			this._eventTable.removeAllEventListeners();
		}
		public _removeAllCaptureEventListeners(): void {
			this._captureEventTable.removeAllEventListeners();
		}

		/**
		 * 특정 이벤트를 전달합니다.
		 * @param e 이벤트
		 * @return 이벤트 전달 성공 여부.
		 */
		public dispatchEvent(e: CEvent): boolean {
			let processEvent: boolean = events.EventBus.INSTANCE._dispatchEvent(e, this);
			if (processEvent == true) {
				processEvent = this._eventTable.dispatchEvent(e);
			}

			return processEvent;
		}

	}

	// 플랫폼과 같이 생성
	let BODYEVENTTARGET: BodyEventTarget = new BodyEventTarget();
}