/// <reference path="./UIControl.ts" />

namespace cpr.controls {

	/**
	 * HTMLSnippet
	 * 
	 * @firesgroup mouse
	 * @firesgroup contextmenu
	 * @firesgroup bindcontext
	 * @firesgroup keyboard
	 * @firesgroup focus
	 * 
	 * @fires cpr.events.CValueChangeEvent#before-value-change HTMLSnippet의 value를 변경하여 변경된 값이 저장되기 전에 발생하는 이벤트.
	 * 		다음 이벤트로 value-change가 발생합니다.
	 * 		<pre>oldValue: {string} 이전 값</pre>
	 * 		<pre>newValue: {string} 현재 값</pre>
	 * 
	 * @fires cpr.events.CValueChangeEvent#value-change HTMLSnippet의 value를 변경하여 변경된 값이 저장된 후에 발생하는 이벤트.
	 * 		<pre>oldValue: {string} 이전 값</pre>
	 * 		<pre>newValue: {string} 현재 값</pre>
	 * 
	 * @fires cpr.events.CUIEvent#error src에서 HTML 콘텐츠를 가져오지 못하면 발생하는 이벤트.
	 * 
	 * @fires cpr.events.CUIEvent#load src에서 HTML 콘텐츠를 정상적으로 가져오면 발생하는 이벤트.
	 */
	export class HTMLSnippet extends VisibleUIControl implements provider.ValueBindable, gridpart.IGridParticipant {
		public static readonly HTML_CONTENT: string = "html-content";

		private static readonly _AVAILABLE_PROP: string[] = [
			"tabIndex", // AccessableUIControl
			"value", "src", "unselectable" //, "innerHTML"
		];

		private _binder: provider.ValueBinder;
		private _innerHTML: string = null;
		private _valueFirst: boolean = true;
		private _tabindex: number = 0;

		// HTMLSnippet이 Grid 내부에 들어있을 때 getElement 메소드가 동작하게 하기 위해서...
		private _eventTarget: HTMLElement = null;


		constructor(id?: string) {
			super(id);
			this._binder = new provider.ValueBinder(this);

			this._addBindableProperty("src", "").withSetterValidatorWithType(false, "string");
			this._addBindableProperty("exportValue", null).withSetterValidatorWithType(false, "string");
			this._addBindableProperty("unselectable", null).withSetterValidatorWithType(false, "boolean");

			// control initializing
			this._initControl();
		}

		/* control's type overriding */
		override _getType(): ControlType {
			return ControlType.HTMLSNIPPET;
		}

		protected _isConfigurableProperty(propName: string): boolean {
			if (HTMLSnippet._AVAILABLE_PROP.indexOf(propName) != -1) {
				return true;
			}
			return super._isConfigurableProperty(propName);
		}

		/**
		 * 컨트롤의 값을 설정하고, value-change이벤트가 발생됩니다.
		 * @param value 컨트롤의 값.
		 */
		public set value(value: string) {
			this._binder.setValue(value);
			this._valueFirst = true;
		}

		/**
		 * 컨트롤의 값을 반환합니다.
		 * @return 컨트롤의 값.
		 */
		public get value(): string {
			return this._binder.getValue();
		}

		/**
		 * 그리드 엑셀 익스포트시 표현할 값을 설정합니다.
		 * @param exportValue 엑셀 익스포트 값.
		 */
		public set exportValue(exportValue: string) {
			this._bindables.set("exportValue", exportValue);
		}

		/**
		 * 그리드 엑셀 익스포트시 표현할 값을 반환합니다.
		 * @return 엑셀 익스포트 값.
		 */
		public get exportValue(): string {
			return this._bindables.get("exportValue");
		}

		/**
		 * Tab Key를 이용한 컨트롤 포커스 순서를 설정합니다.<br>
		 * HTML의 tabindex를 제어하기 위한 속성입니다.
		 * @param tabindex 컨트롤 포커스 순서.
		 */
		set tabIndex(tabindex: number) {
			if (typeof tabindex === "string") {
				tabindex = parseInt(tabindex);
			}
			let isAllowType = (typeof tabindex === "number" && !isNaN(tabindex)) || tabindex === null;
			if (!isAllowType) {
				return;
			}
			//AppInstance의 focusNext,focusPrevious에서 tabIndex의 타입이 number가 아니면 동작하지 않음.
			if (this._tabindex !== tabindex) {
				this._tabindex = tabindex;
				this.redraw();
			}
		}

		/**
		 * Tab Key를 이용한 컨트롤 포커스 순서를 반환합니다.<br>
		 * HTML의 tabindex를 제어하기 위한 속성입니다.
		 * @return 컨트롤 포커스 순서.
		 */
		get tabIndex(): number {
			return this._tabindex;
		}

		override _isFocusable(): boolean {
			let renderer: ufc.ControlRenderer = this._getRenderer();
			if (!renderer.hasDrawn()) {
				return false;
			}
			let rootNode: HTMLElement = renderer.getRootNode();
			if (!rootNode) {
				return false;
			}

			return _hasTabbableChildNode(rootNode);
		}

		private _receiveHTML(e: events.CSubmissionEvent): void {
			e.preventDefault();
			let submission: protocols.Submission = e.control as protocols.Submission;
			let xhr: XMLHttpRequest = submission.xhr;

			let uiEvent: events.CUIEvent = null;
			if (xhr.status == 200) {
				uiEvent = new events.CUIEvent("load");
			} else {
				uiEvent = new events.CUIEvent("error");
			}
			let processContinue: boolean = this.dispatchEvent(uiEvent);
			if (processContinue === true) {
				let responseText: string = xhr.responseText;
				this._innerHTML = responseText;

				if (this._valueFirst === false) {
					this.redraw();
				} else {
					this._innerHTML = null;
				}
			}
		}

		/**
		 * 컨트롤의 값을 설정합니다.
		 * @param value 컨트롤의 값.
		 */
		public putValue(value: string) {
			this._binder.setValue(value, false);
			this._valueFirst = true;
		}

		/**
		 * HTMLSnippet에서 html을 로드하여 보여줄 경우 html의 url을 입력합니다.
		 * html의 url 주소는 절대 주소 또는 eXBuilder6 프로젝트가 실행되는 base url 기준 상대경로의 입력이 가능합니다.
		 * @param src html 의 url
		 */
		public set src(src: string) {
			this._bindables.set("src", src);
			this._valueFirst = false;
		}

		/**
		 * HTMLSnippet에서 로드할 html의 url이 반환됩니다.
		 */
		public get src(): string {
			return this._bindables.get("src");
		}

		/**
		* @private
		* @readonly
		*/
		public get valueFirst(): boolean {
			return this._valueFirst;
		}

		/**
		 * @private
		 */
		public get innerHTML(): string {
			return this._innerHTML;
		}

		/**
		 * @private
		 */
		public set innerHTML(innerHTML: string) {
			this._innerHTML = innerHTML;
		}

		/**
		 * 텍스트의 선택 불가능 여부를 반환합니다.
		 * @return 텍스트의 선택 불가능 여부.
		 */
		public get unselectable(): boolean {
			return this._bindables.get("unselectable");
			// return (this._unselectable === true || this._unselectable === false) ? this._unselectable : null;
		}

		/**
		 * 텍스트의 선택 불가능 여부를 설정합니다.
		 * @param state 텍스트의 선택 불가능 여부.
		 * [null] : 부모의 선택 모드를 따릅니다. (기존과 동일한 상태)<br>
		 * [true] : 텍스트 선택을 지원하지 않습니다.<br>
		 * [false] : 텍스트 선택을 지원합니다.
		 */
		public set unselectable(state: boolean) {
			this._bindables.set("unselectable", state);
			// this._unselectable = state;
		}

		override redraw(): void {
			super.redraw();
			this._propagateResize();
		}

		private _propagateResize(): void {
			let container: Container = this.getParent();
			if (container) {
				container._applyChildSizeChanging(this);
			}
		}

		_valueDidChange(name: string, oldValue: any, newValue: any) {
			super._valueDidChange(name, oldValue, newValue);
			this._binder._valueDidChange(name, oldValue, newValue);
			switch (name) {
				case "src": {
					if (newValue) {
						let submission: protocols.Submission = new protocols.Submission();
						submission.action = newValue;
						submission.contextPath = ""; // image를 로딩하는 것과 같이 html의 base url을 사용하도록 contextpath 초기화
						submission.responseType = "text";
						submission.addEventListener(events.SubmissionEventType.RECEIVE, (e: events.CSubmissionEvent) => {
							this._receiveHTML(e);
						});
						submission.addEventListener(events.SubmissionEventType.TIMEOUT, (e: events.CSubmissionEvent) => {
							let uiEvent: events.CUIEvent = new events.CUIEvent("error");
							uiEvent.nativeEvent = e.nativeEvent;
							let processContinue: boolean = this.dispatchEvent(uiEvent);
							if (processContinue === true) {
								this._innerHTML = null;
								this.redraw();
							}
						});

						submission.send();
					} else {
						this._innerHTML = null;
						this.redraw();
					}
					break;
				}
				case "unselectable": {
					this.redraw(); break;
				}
			}
		}

		/* Shape */
		protected _getStylerSpec(): UIControlStylerSpec {
			return {
				root: { baseClass: "cl-htmlsnippet" }
			};
		}

		/**
		 * HTMLSnippet의 HTMLElement를 리턴합니다.
		 * 리턴된 HTMLElement는 읽기 전용으로만 사용해야 합니다.
		 * @return HTMLElement
		 */
		public getElement(): HTMLElement {
			if (this.disposed) {
				return null;
			}
			let rootNode: HTMLElement = null;
			if (this._eventTarget) {
				let traverser: ufc.DOMTraverser = ufc._traverseFromElement(this._eventTarget);
				traverser = traverser._closest(".cl-htmlsnippet");
				if (traverser) {
					rootNode = traverser._getElement();
					traverser.dispose();
					traverser = null;
				}
			} else {
				let renderer: ufc.ControlRenderer = this._getRenderer();
				rootNode = renderer.getRootNode();
			}
			return rootNode;
		}

		public override _createShape(): cpr.ufc.ControlShape {
			let inlineTag: ufc.ElementShape = {
				tag: "div",
				style: {
					display: "table-cell",
					height: "100%",
					verticalAlign: "inherit",
					overflow: "hidden"
				},
				classNames: [],
				innerHTML: null
			};

			if (this._valueFirst === true) {
				inlineTag.innerHTML = this.value;
				this._innerHTML = null;
			} else {
				inlineTag.innerHTML = this._innerHTML;
			}

			let tableTag: cpr.ufc.ElementShape = {
				tag: "div",
				style: {
					display: "inline-table",
					width: "100%",
					height: "100%",
					tableLayout: "auto",
					verticalAlign: "inherit"
				},
				children: [inlineTag]
			};

			let shape: cpr.ufc.ControlShape = {
				tag: "div",
				styler: "root",
				classNames: [],
				attr: {
					tabindex: "-1"
				},
				style: {
					overflow: "hidden"
				},
				events: {
					keydown: this._onKeyDown
				},
				eventTargets: [ufc.EventTargetType.UICONTROL],
				children: [tableTag]
			};

			cpr.ufc.ShapeUtil._setTooltipAttr(shape, { owner: this, title: this.tooltip });

			if (this.unselectable === true) {
				shape.classNames.push(ufc.Classes.UNSELECTABLE);
			} else if (this.unselectable === false) {
				shape.classNames.push(ufc.Classes.SELECTABLE);
			}
			return shape;
		}

		override _getAutoSizeAvailability(): layouts.AutoSizeType {
			return layouts.AutoSizeType.both;
		}

		public _convertGridPasteText(text: string): string {
			return text;
		}

		public _getGridViewingText(): string {
			let text: string = "";
			if (this.valueFirst === true) {
				text = this.value;
			}
			return text;
		}

		public _renderGridCellShape(grid: Grid, data: (string | ufc.StyledString), option: gridpart.renderer.IRenderOption): ufc.ControlShape {
			// Grid > HTMLSnippet의 경우 src속성을 지원하지 않음.
			// HTMLSnippet의 shape 구조가 바뀌면 반드시 GridRowManager의 _getHTMLSnippetContentNode 를 그에 맞게 바꾸어줘야 합니다.

			let htmlsnippetShape: ufc.ControlShape = {
				tag: "div",
				classNames: ["cl-control", "cl-htmlsnippet"],
				style: { overflow: "hidden" },
				children: []
			};
			if (option.maxHeight >= 0) {
				htmlsnippetShape.style["height"] = option.maxHeight + "px";
			}

			if (option.hidetext == false) {
				let tableTag: cpr.ufc.ControlShape = {
					tag: "div",
					style: {
						display: "inline-table",
						width: "100%",
						height: "100%",
						tableLayout: "auto",
						verticalAlign: "inherit"
					},
					children: []
				};
				htmlsnippetShape.children.push(tableTag);

				let inlineTag: ufc.ElementShape = {
					tag: "div",
					attr: {},
					style: {
						display: "table-cell",
						height: "100%",
						verticalAlign: "inherit",
						overflow: "hidden"
					},
					innerHTML: null
				};

				if (option.isGhost === true) {
					inlineTag.attr["data-cell-role"] = HTMLSnippet.HTML_CONTENT;
				}

				if (this.valueFirst === true) {
					inlineTag.innerHTML = this.value;
					this.innerHTML = null;
				}
				tableTag.children.push(inlineTag);
			}

			if (this.unselectable === true) {
				htmlsnippetShape.classNames.push(ufc.Classes.UNSELECTABLE);
			} else if (this.unselectable === false) {
				htmlsnippetShape.classNames.push(ufc.Classes.SELECTABLE);
			}
			return htmlsnippetShape;
		}

		private _onKeyDown(e: events.CKeyboardEvent) {
			let keycode: number = e.keyCode;
			if (events.KeyCode.TAB != keycode) {
				// tabkey만 처리
				return;
			}

			// 내부에 포커스링이 이동한 경우에 이벤트 전파 차단.
			// 그외의 경우 앱 인스턴스에서 처리 할 것.
			if (this._traverseFocusInternally(!e.shiftKey)) {
				e.preventDefault();
				e.stopPropagation();
			}
		}

		override focus(forward: boolean = true): void {
			if (this.focusable) {
				let renderer: ufc.ControlRenderer = this._getRenderer();
				if (renderer == null) {
					return;
				}
				if (renderer.hasDrawn() == false) {
					this.redraw();
				}
				core.DeferredUpdateManager.INSTANCE._performFocusTask(
					this._traverseFocusInternally.bind(this, forward)
				);
			}
		}

		private _traverseFocusInternally(forward: boolean): boolean {
			let renderer: ufc.ControlRenderer = this._getRenderer();
			let rootNode: HTMLElement = renderer.getRootNode();
			return _traverseHTMLFocus(rootNode, forward);
		}

		override _checkControlStateForEvent(e: events.CEvent = null): boolean {
			let checked: boolean = super._checkControlStateForEvent(e);
			if (checked && e.type == "click") {
				// targetElement 기준으로 
				this._eventTarget = e.target as HTMLElement;
			}
			return checked;
		}

		public _exportValue(): string | number {
			let exportValue: string = this.exportValue;
			if (exportValue != null) {
				return exportValue;
			} else {
				return (this.value != null) ? "" + this.value : "";
			}
		}

		/**
		 * @private
		 * @param e 
		 */
		override dispatchEvent(e: events.CEvent): boolean {
			try {
				return super.dispatchEvent(e);
			} finally {
				this._eventTarget = null;
			}
		}
	}

}