namespace cpr.controls.gridpart {

	// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/7386
	// CSSStyleDeclaration 과 동작을 통일하기 위해 노멀라이징 추가.
	function _normalizeCSSPropName(name: string) {
		return name.replace(/([a-z])([A-Z])/g, (grp, pre: string, after: string) => {
			return pre + "-" + after.toLowerCase();
		});
	}

	export class GridStyle {
		static readonly TOPSPLIT: string = "cl-grid-topsplit";
		static readonly BOTTOMSPLIT: string = "cl-grid-bottomsplit";
		static readonly LEFTSPLIT: string = "cl-grid-leftsplit";
		static readonly RIGHTSPLIT: string = "cl-grid-rightsplit";
		static readonly CENTERSPLIT: string = "cl-grid-centersplit";
		static readonly NODATAMSGWRAPPER: string = "cl-nodatamsg-wrapper";
		static readonly NODATAMSG: string = "cl-nodatamsg";
		static readonly BLANK: string = "cl-blank";
		static readonly HEADERBAND: string = "cl-grid-header-band";
		static readonly DETAILBAND: string = "cl-grid-detail-band";
		static readonly FOOTERBAND: string = "cl-grid-footer-band";
		static readonly ROW: string = "cl-grid-row";
		static readonly CELL: string = "cl-grid-cell";
		static readonly DEFAULTCELL: string = "cl-default-cell";

		static readonly CONTROL: string = "cl-control";
		static readonly OUTPUT: string = "cl-output";
		// static readonly WRITINGMODEHTB: string = "cl-writingmode-horizontal-tb";
		// static readonly WRITINGMODEVLR: string = "cl-writingmode-vertical-lr";
		// static readonly WRITINGMODEVRL: string = "cl-writingmode-vertical-rl";

		// static readonly CHECKBOXGROUP: string = "cl-checkboxgroup";
		static readonly CHECKBOX: string = "cl-checkbox";
		static readonly CHECKBOXICON: string = "cl-checkbox-icon";

		static readonly RADIOBUTTON: string = "cl-radiobutton";
		static readonly RADIOBUTTONITEM: string = "cl-radiobutton-item";
		static readonly RADIOBUTTONICON: string = "cl-radiobutton-icon";
	}

	/**
	 * @noinstance
	 */
	export class GridStyler {
		private _grid: Grid;
		private _isDisposed = false;
		private _css: CSSStyle;
		private _bindables: bind.BindableProperties;

		/**
		 * @private
		 */
		constructor(grid: Grid, css: CSSStyle = { baseClass: null }) {
			this._grid = grid;
			this._bindables = new bind.BindableProperties(grid, { allowsAnyProperty: true });
			this._css = _defaults(css, {
				customClasses: [],
				style: {},
				// mediaClasses: {},
				// mediaStyle: {}
			});

			this._bindables.add("-cl-class", "");
		}

		/**
		 * 기본 class 명을 반환합니다.
		 * @return 기본 class 명
		 * <a href="cpr.controls.UIControlStyler.html#getBaseClassName">cpr.data.UIControlStyler.getBaseClassName</a>참고
		 */
		public getBaseClassName(): string {
			return this._css.baseClass;
		}

		/**
		 * class를 추가합니다.
		 * @param className class 명
		 */
		public addClass(className: string): void {
			let merged = this._css.customClasses ?? [];

			if (merged.indexOf(className) === -1) {
				merged.push(className);
				this._css.customClasses = merged;

				this._grid.redraw();
			}
		}

		/**
		 * 두 개 이상의 class를 설정합니다.<br>
		 * @param classNames 추가할 class 명들.
		 * 예제: <br>
		 * <code> control.style.setClasses("buttonStyle", "imageStyle");</code><br>
		 * <a href="cpr.controls.UIControlStyler.html#setClasses">cpr.data.UIControlStyler.setClasses</a>참고
		 * 
		 */
		public setClasses(...classNames: string[]): void {
			this._css.customClasses = _.flatten(classNames);
			this._grid.redraw();
		}

		/**
		 * 컨트롤이 가진 class 명을 반환합니다<br>
		 * @return class 명.
		 * <a href="cpr.controls.UIControlStyler.html#getClasses">cpr.data.UIControlStyler.getClasses</a>참고
		 */
		public getClasses(): string[] {
			if (this._bindables.isBinded("-cl-class")) {
				let exp = this._bindables.get("-cl-class") as string;
				if (exp) {
					return exp.split(/\s+/g);
				} else {
					return [];
				}
			}
			return this._css.customClasses ? this._css.customClasses.slice(0) : [];
		}

		/**
		 * 클래스 소유 여부를 확인합니다.
		 * @param className 확인할 클래스.
		 */
		public hasClass(className: string) {
			if (className == null) {
				return false
			}
			let classes = this.getClasses();
			return className.split(/s+/g).filter(it => it.length > 0).every(it => {
				return classes.indexOf(it) !== -1;
			});
		}


		/**
		 * 해당 class를 삭제합니다.<br>
		 * @param className class 명
		 * <a href="cpr.controls.UIControlStyler.html#removeClass">cpr.data.UIControlStyler.removeClass</a>참고
		 */
		public removeClass(className?: string): void {
			let indexToRemove = this._css.customClasses ? this._css.customClasses.indexOf(className) : -1;
			if (indexToRemove !== -1) {
				this._css.customClasses.splice(indexToRemove, 1);

				this._grid.redraw();
			}
		}

		/**
		 * 해당 css property의 값을 반환합니다.<br>
		 * 값이 없을 시 지정된 기본 값으로 반환합니다.
		 * <a href="cpr.controls.UIControlStyler.html#getCSS">cpr.data.UIControlStyler.getCSS</a>참고
		 */
		public getCSS(key: string, defaultValue: string): string {
			let styleValue: string = this.css(key);
			return styleValue == null || styleValue == "" ? defaultValue : styleValue;
		}

		/**
		 * 지정된 모든 CSS 속성들을 JSON 형태로 얻습니다.
		 */
		public css(): { [key: string]: string };

		/**
		 * 특성 CSS 속성 값을 얻습니다.
		 * @param key 값을 얻을 속성 명
		 */
		public css(key: string): string;

		/**
		 * 특정 CSS 속성의 값을 지정합니다.<br>
		 * 컨트롤에서 설정되는 속성은 변경되지 않습니다.
		 * @param key 값을 지정할 CSS 속성명
		 * @param value 지정할 값.
		 */
		public css(key: string, value: string): void;

		/**
		 * 한 번에 여러 CSS 속성들을 지정합니다.<br>
		 * 컨트롤에서 설정되는 속성은 변경되지 않습니다.
		 * @param json 지정할 키와 값들을 가진 JSON 객체.
		 */
		public css(json: { [key: string]: string }): void;

		public css(): any {
			let args = _toArray(arguments);
			switch (args.length) {
				case 0: {
					let result = _mergeObject(this._css.style, this._bindables.resolveAll());
					delete result["-cl-class"]
					return result;
				}

				case 1: {
					if (typeof args[0] == "string") {
						let key = args[0] as string;

						// 바인딩 된 키인 경우.
						if (this._bindables.isBinded(key)) {
							return this._bindables.get(key) || "";
						} else {
							return this._css.style[key] || "";
						}
					} else if (typeof args[0] == "object") {
						Object.keys(args[0]).forEach(key => {
							if (this._bindables.isBinded(key)) {
								this._bindables.destroy(key);
							}
						});
						this._css.style = _assign(this._css.style, args[0]);

						this._grid.redraw();
					} else {
						throw new exceptions.IllegalArgumentException();
					}
					break;
				}

				case 2: {
					let key = args[0] as string;
					let value = args[1] as string;

					if (this._bindables.isBinded(key)) {
						this._bindables.destroy(key);
					}

					if (typeof key != "string" || typeof value != "string") {
						throw new exceptions.IllegalArgumentException();
					}
					this._css.style[key] = value;

					this._grid.redraw();

					break;
				}
			}
		}

		/**
		 * 설정된 style의 해당 property를 제거합니다.
		 * <a href="cpr.controls.UIControlStyler.html#removeStyle">cpr.data.UIControlStyler.removeStyle</a>참고
		 */
		public removeStyle(key: string): void {
			if (this._css.style.hasOwnProperty(key)) {
				delete this._css.style[key];

				this._grid.redraw();
			}
		}

		/**
		 * style의 제거 여부를 반환합니다
		 */
		public get disposed(): boolean {
			return this._isDisposed;
		}

		/**
		 * 스타일에 포함된 객체들을 제거합니다.
		 */
		public dispose(): void {
			if (this._isDisposed) {
				return;
			}
			if (this._bindables) {
				this._bindables.dispose();
				this._bindables = null;
			}
			this._css = null;
			this._isDisposed = true;
		}


		/**
		 * 해당 css 속성을 bind합니다.
		 * @param cssProperty bind할 css 속성 명.
		 */
		public bind(cssProperty: string): bind.IBindFactory {
			return this._bindables.bind(cssProperty);
		}

		/**
		 * 해당 css 속성을 unbind합니다.
		 * @param name unBind할 css 속성 명
		 */
		public unbind(name: string) {
			this._bindables.unbind(name);
		}

		/**
		 * 특정 CSS 속성에 대한 바인딩 정보를 얻습니다.
		 * @param property 바인딩 정보를 얻을 스타일 속성명.
		 * @return 바인딩 정보 객체.
		 */
		public getBindInfo(property: string): bind.BindInfo {
			return this._bindables.getBindableProperty(_normalizeCSSPropName(property))?.getCurrentBindInfo();
		}

		/**
		 * 스타일러의 CSS 클래스 바인딩 정보를 얻습니다.
		 * @return 클래스 바인딩 정보 객체.
		 */
		public getClassBindInfo() {
			return this._bindables.getBindableProperty("-cl-class")?.getCurrentBindInfo();
		}

		bindClass(): bind.IBindFactory {
			return this._bindables.bind("-cl-class");
		}

		unbindClass() {
			this._bindables.unbind("-cl-class");
		}

		/**
		 * bindable css와 일반 설정 css를 구분하여 반환합니다.
		 * @param isBindable 
		 */
		public _getCSS(isBindable: boolean): { [key: string]: string } {
			let result: { [key: string]: string } = null;
			if (isBindable == true) {
				result = _mergeObject(this._bindables.resolveAll());
				delete result["-cl-class"]
			} else {
				result = _mergeObject(this._css.style);
			}
			return result;
		}

	}
}