/// <reference path="../../protocols/ProtocolDataModel.ts" />

namespace cpr.protocols.matrix {
	/**
	 * 매트릭스 모델에 속한 노드의 유형을 나타냅니다.
	 */
	export enum MetaModelFormat {
		/**
		 * 패스 또는 상수를 공급하는 유형을 나타냅니다.
		 */
		simple = "simple",

		/**
		 * 반복 노드를 공급하는 유형을 나타냅니다.
		 */
		array = "array",

		/**
		 * 여러 키와 값을 같는 노드 유형을 나타냅니다.
		 */
		object = "object"
	};

	/**
	 * 매트릭스 모델을 정의하는 각 노드의 기본 단위를 추상화 합니다.
	 */
	export interface MetaModel {
		/** 규격 유형 */
		format: MetaModelFormat,

		/**
		 * 데이터를 가져올 데이터 컨트롤.
		 */
		dataControl?: controls.Control,

		/** 상위 저장소와 참조관계를 가지는지 여부 */
		linked?: boolean,

		/** ("[" + [0-9]+ + "]")? + "@" + columnName 상위노드의 refID를 참조 키로 갖는 DataSet의 행의 특정 컬럼 값을 지정. */
		path?: string
	}

	/**
	 * 매트릭스 모델을 구성 하는 노드들 중 요청을 정의하는 노드를 추상합니다.
	 */
	export interface RequestMetaModel extends MetaModel {
		/**
		 * 전송 범위
		 */
		payload?: "modified" | "all",

		/**
		 * {@link format} 이 "simple" 일 때 number 또는 string 타입이며, "array" 혹은 "object"인 경우 {@link RequestMetaModel}이 됩니다.
		 */
		data?: any;
	}

	/**
	 * 매트릭스 모델을 구성 하는 노드들 중 응답 해석을 정의하는 노드를 추상합니다.
	 */
	export interface ResponseMetaModel extends MetaModel {
		/**
		 * dataControl이 DataSet/DataView에서 응답데이터를 처리할 때 데이터를 모두 지우고 추가할지 기존 데이터를 남기고 추가 할지 여부
		 */
		isAdd?: boolean,

		/** 
		 * {@link format} 이 "simple" 일 때 number 또는 string 타입이며, "array" 혹은 "object"인 경우 {@link RequestMetaModel}이 됩니다.
		 */
		data?: any
	}

	export interface Matrix {
		/**
		 * 요청 생성 메타 모델
		 */
		request?: RequestMetaModel,

		/**
		 * 응답 처리 메타 모델
		 */
		response?: ResponseMetaModel
	}

	/**
	 * @private
	 */
	export interface RequestDataModel {
		[key: string]: RequestMetaModel
	}

	/**
	 * @private
	 */
	export interface ResponseDataModel {
		[key: string]: ResponseMetaModel
	}

	/**
	 * 사용자 정의 요청데이터 정보.
	 */
	export interface CustomRequestData {
		path: string,
		data: string | number | {}
	}

	/**
	 * @private
	 */
	export class MatrixDataModel extends ProtocolDataModel {
		private _matrix: Matrix;
		private _reqAddData: CustomRequestData[];
		private _files: cpr.utils.EntrySet<File>;
		private _datapartName: string = request.MultipartJSONRequestBuilder.JSONREQOBJ_PARAMNAME;
		private _multipartRequest: boolean;


		constructor(matrix?: Matrix) {
			super();
			this._matrix = matrix;
			this._reqAddData = [];
			this._files = new cpr.utils.EntrySet<File>();
		}

		public _setMatrix(matrix: Matrix): void {
			this._matrix = matrix;
		}

		public _getMatrix(): Matrix {
			return this._matrix;
		}

		public _getRequestMatrix(): RequestMetaModel {
			let requestMatrix: RequestMetaModel = null;
			if (this._matrix && this._matrix["request"]) {
				requestMatrix = this._matrix.request;
			}
			return requestMatrix;
		}

		public _addCustomRequestData(path: string, data: string | number | {}): void {
			this._reqAddData[this._reqAddData.length] = { path: path, data: data };
		}
		public _getAllCustomRequestDatas(): CustomRequestData[] {
			return this._reqAddData;
		}
		public _removeAllCustomRequestDatas(): void {
			this._reqAddData.splice(0);
		}

		public _getDataPartName(): string {
			return this._datapartName;
		}
		public _setDataPartName(name: string): void {
			this._datapartName = name;
		}
		public _setMultipartRequest(multipartRequest: boolean): void {
			this._multipartRequest = multipartRequest;
		}
		public _addFileParameter(name: string, file: File): void {
			this._files.push({
				key: name, value: file
			});
		}
		public _getFileParameterNames(): string[] {
			return this._files.getKeys();
		}
		public _getFileParameters(name: string): File[] {
			if (name == null || name == "") {
				return [];
			}
			return this._files.getValues(name);
		}
		public _removeFileParameters(name: string): File[] {
			if (name == null || name == "") {
				return [];
			}
			let values: File[] = this._getFileParameters(name);
			this._files.remove(name);

			return values;
		}
		public _removeAllFileParameters(): void {
			this._files.clear();
		}

		public _getResponseMatrix(): ResponseMetaModel {
			let responseMatrix: ResponseMetaModel = null;
			if (this._matrix && this._matrix["response"]) {
				responseMatrix = this._matrix.response;
			}
			return responseMatrix;
		}

		public getRequestBuilder(submission: AbstractSubmission): RequestBuilder {
			if (this._isMultipartRequest()) {
				return MatrixMultipartRequestBuilder.INSTANCE;
			} else {
				return MatrixRequestBuilder.INSTANCE;
			}
		}

		public getResponseParser(xhr: XMLHttpRequest, contentType: string, defaultContentType: string): ResponseParser {
			contentType = this._responseParserFactory._getContentType(xhr);
			if (contentType) {
				switch (contentType) {
					case Submission.MEDIA_SCRIPT: {
						return this._responseParserFactory._getScriptParser();
					}
					case "attachment": {
						return this._responseParserFactory._getDownloadParser();
					}
				}
			}
			return MatrixResponseParser.INSTANCE;
		}

		public _getContentParser(forceContentType: string, defaultContentType: string): ResponseParser {
			if (forceContentType) {
				switch (forceContentType) {
					case Submission.MEDIA_SCRIPT: {
						return this._responseParserFactory._getScriptParser();
					}
					case "attachment": {
						return this._responseParserFactory._getDownloadParser();
					}
				}
			}
			return MatrixResponseParser.INSTANCE;
		}

		private _isMultipartRequest(): boolean {
			return this._multipartRequest === true || this._files.size() > 0;
		}
	}

}