namespace cpr.exceptions {
	export class CError {
		private _name: string;
		private _message: string;
		private _stack: string;

		constructor(message: string);
		constructor(name: string, message: string);
		constructor() {
			let args: string[] = _toArray(arguments).filter(it => typeof it == "string") as string[];
			let name: string;
			let message: string;
			let fakeError = new Error();
			let stack = fakeError.stack;

			// IE11 이하에서는 예외를 던지는 경우에만 스택이 형성됨.
			if (!stack) {
				try {
					throw fakeError
				} catch (e) {
					stack = e.stack;
				}
			}
			if (stack) {
				// 첫줄 생략.
				let elements = stack.split(/\r\n|\n/);
				elements.splice(0, 1);
				stack = elements.join("\n")
			}

			switch (args.length) {
				case 0: {
					name = "CError";
					message = "No description";
					break;
				}
				case 1: {
					name = "CError";
					message = args[0];
					break;

				}
				case 2: {
					name = args[0];
					message = args[1];
					break;
				}
				default: throw new exceptions.IllegalArgumentException()
			}
			this._name = name;
			this._message = message;
			this._stack = stack;
		}

		/**
		 * 오류 이름
		 */
		public get name(): string {
			return this._name;
		}

		/**
		 * 오류 메시지
		 */
		public get message(): string {
			return this._message;
		}

		/**
		 * 오류 스택
		 */
		public get stack(): string {
			return this._stack;
		}
	}

	export class InvalidAPICallException {
		private _cause: CError;
		private _callContext: object;

		constructor(cause: CError, callContext: object) {
			this._cause = cause;
			this._callContext = callContext;
		}

		public get name(): string {
			return "InvalidAPICallException"
		}

		public get message(): string {
			return this._cause.message;
		}

		public get stack(): string {
			return this._cause.stack;
		}

		public get cause(): CError {
			return this._cause;
		}

		public get callContext(): object {
			return this._callContext;
		}
	}

	export class CancelationException extends CError {
		constructor(message: string = "User did cancel the operation.") {
			super("CancelationException", message)
		}
	}

	export class IllegalArgumentException extends CError {
		constructor(message: string = "The argument is invalid.") {
			super("IllegalArgumentException", message);
		}
	}

	export class DisposeException extends CError {
		constructor(message: string = "Tried to access disposed resource.") {
			super("DisposeException", message);
		}
	}

	export class IllegalStateException extends CError {
		constructor(message: string = "Called with illegal state.") {
			super("IllegalStateException", message);
		}
	}

	export class UnsupportedOperationException extends CError {
		constructor(message: string = "Unsupported operation was invoked.") {
			super("UnsupportedOperationException", message);
		}
	}

	export class NoMoreElementException extends CError {
		constructor(message: string = "No more element is available.") {
			super("NoMoreElementException", message);
		}
	}
}