namespace cpr.controls {

	/**
	 * @private
	 */
	export enum LabelableType {
		input = "input",
		textarea = "textarea",
		div = "div",
		none = "none"
	}
	/**
	 * label for로 연결했을 때 사용하는 프로바이더
	 * @private
	 */
	export class LabelProvider {
		private _labels: Output[] = [];
		private _owner: UIControl;
		private _timer: utils.Timer;
		private _cache: { [key: string]: string } = {};

		constructor(owner: UIControl) {
			this._owner = owner;
			this._timer = new utils.Timer("label-update", () => {
				if (this._owner) this._owner.redraw();
			});
		}

		public update(output: Output): void {
			if (this._owner._getLabelableType() == LabelableType.none || !this._labels) {
				return;
			}
			if (this._labels.indexOf(output) < 0) {
				return;
			}

			let oldText = this._cache[output.uuid] ?? "";
			let fieldLabel = output._getFieldLabel();
			let newText = fieldLabel ? fieldLabel : output.text;
			newText = output.visible ? newText : "";

			if (oldText != newText) {
				this._cache[output.uuid] = newText;
				this._timer.schedule();
			}
		}

		/**
		 * 레이블 역할을 수행할 Output 컨트롤을 추가 지정합니다.
		 * @param control 
		 */
		public addLabel(control: Output) {
			if (!this._labels) {
				this._labels = [control];
				return;
			} else {
				this._labels.push(control);
				// 추가된 후 redraw()하지 않는 이유는 getText에서 렌더링 된 엘리먼트를 찾기 때문에 갱신 의미가 없음. 연경된 아웃풋이 렌더링 되어야 갱신이 필요함.
			}
		}

		/**
		 * 레이블을 제거합니다.
		 * @param control 
		 * @returns 
		 */
		public removeLabel(control: Output) {
			if (!this._labels) {
				return;
			}

			if (_removeFromArray(this._labels, control)) {
				delete this._cache[control.uuid];
				this._owner.redraw(); // 속성을 제거해주는 갱신이 필요함.
			}
		}

		private _findTreeOrderedLabelUUID(condition: (uuid: string) => boolean) {
			return _stream(this._labels)
				// 그려진 
				.filter(it => it._getRenderer().hasDrawn())
				.map(it => it.uuid)
				.filter(condition)
				.head()
		}

		/**
		 * 연결된 레이블들의 텍스트를 반환합니다. 지정된 레이블 중에 첫번째 레이블만 읽도록 합니다.
		 * @returns 
		 */
		public getText(): string {
			let result = "";
			if (_isNullOrEmpty(this._labels)) {
				return result;
			}

			let uuid: string;
			if (this._labels.length > 1) {
				uuid = this._findTreeOrderedLabelUUID((uuid: string) => {
					return this._cache[uuid] ? true : false;
				})
			} else {
				uuid = this._labels[0]?.uuid;
			}
			if (uuid) {
				result = this._cache[uuid] ?? "";
			}
			return result;
		}

		/**
		 * 레이블 설정이 가능한 엘리먼트 ID를 반환합니다.
		 * @returns 
		 */
		public getLabelableElementId(): string {
			let labelableType = this._owner._getLabelableType();
			if ([LabelableType.input, LabelableType.textarea].indexOf(labelableType) == -1) {
				return "";
			}
			return this._owner._getLabelableElementId() ?? "";
		}

		public dispose(): void {
			this._timer.cancel();
			this._timer = null;
			if (this._labels) {
				this._labels = null;
			}
			this._cache = null;
			this._owner = null;
		}
	}

}