namespace cpr.controls.item {
	/**
	 * @private
	 */
	export class TreeItemFilter extends ItemFilter {
		private _treeFilterExpression: cpr.expression.Expression = null;

		/**
		 * 필터가 있는지 유무를 확인합니다.
		 */
		public hasFilter(): boolean {
			return super.hasFilter() || this.treeFilterExpression != null;
		}

		public get treeFilter(): expression_string {
			if (this.treeFilterExpression) {
				return this.treeFilterExpression.src;
			}
			return null;
		}

		public set treeFilter(filterExpression: expression_string) {
			if (filterExpression) {
				this._treeFilterExpression = new expression.Expression(filterExpression);
			} else {
				this._treeFilterExpression = null;
			}
		}

		public get treeFilterExpression(): cpr.expression.Expression {
			return this._treeFilterExpression;
		}

		public set treeFilterExpression(filterExpression: cpr.expression.Expression) {
			this._treeFilterExpression = filterExpression;
		}

		/**
		 * 적용된 필터를 제거합니다.
		 */
		public override clearFilter(): void {
			if (this.treeFilterExpression != null) {
				this._treeFilterExpression = null;
			}
			super.clearFilter();
		}

		public override dispose(): void {
			super.dispose();
			this._treeFilterExpression = null;
		}
	}
}
