
/// <reference path="../EnableUIControl.ts" />

namespace cpr.controls.internal {

	/**
	 * @private
	 */
	export interface RepeatScrollPaneContent {
		ns: string;
		getQName(name: string): string;
		contentNodeName: string;
		dummyContentNodeName: string;
		createContents(start: number, end: number): ufc.ControlShape;
		createDummyContents(dummy?: { item: TreeItem, index: number }): ufc.ControlShape;
		_getComputedItemWidth(items: TreeItem[]): number;
		findRowElement(parentEle: HTMLElement): HTMLElement;
		findRowWrapElement(parentEle: HTMLElement): HTMLElement;
		_isFitContentWidth(): boolean;
	}

	/**
	 * @private
	 */
	export interface ICustomScrollPane extends internal.IVirtualScrollPane {
		_createShape(items: any[], createItem: Function, contentClassNames?: string[], contentAttributes?: {}): cpr.ufc.ControlShape
	}
	/**
	 * @private
	 */
	export class RepeatScrollPane implements IVirtualScrollPane, ICustomScrollPane {

		private _uicontrol: EnableUIControl;
		private _vscrollbar: internal.IVirtualVScrollbar;
		private _hscrollbar: internal.IVirtualHScrollbar;

		private _contentHeight: number = 0;
		private _contentWidth: number = 0;
		private _viewHeight: number = 0;
		private _viewWidth: number = 0;
		private _maxContentTop: number = 0;
		private _maxContentLeft: number = 0;

		private _rowHeight: number = 30;

		private _vScrollTop: number = 0;
		private _vScrollLeft: number = 0;

		private _startRowIndex: number = 0;
		private _endRowIndex: number = 10;

		private _workingData: TreeItem[] = null;
		private _initVScroll: boolean = false;// 리스트 높이가 동적으로 변경될때 스크롤을 숨긴 후 표시하기 위한 플래그

		private _scrollPaneContent: RepeatScrollPaneContent;

		private _scrollIndex: number;
		private _autoSizeType: layouts.AutoSizeType;
		private _focusAssistant: boolean = true;

		constructor(uicontrol: EnableUIControl, scrollPaneContent: RepeatScrollPaneContent, focusAssistant: boolean = true) {
			this._uicontrol = uicontrol;
			this._focusAssistant = focusAssistant;
			if (this._uicontrol._isUseCustomScroll()) {
				this._vscrollbar = new internal.VirtualVScrollbar(this);
				this._hscrollbar = new internal.VirtualHScrollbar(this);
			} else {
				this._vscrollbar = new internal.NativeVScrollbar(this);
				this._hscrollbar = new internal.NativeHScrollbar(this);
			}

			this._scrollPaneContent = scrollPaneContent;
			this._autoSizeType = layouts.AutoSizeType.none;
		}

		public get scrollPageSize() {
			return this._getPageSize();
		}

		public _setAutoSizeType(type: layouts.AutoSizeType) {
			this._autoSizeType = type;
		}

		public _setNameSpace(ns: string) {
			this._scrollPaneContent.ns = ns;
		}

		public _getId() {
			return "lb-" + this._uicontrol.uuid
		}

		public _getItemId(index: number) {
			return "i" + index + "-" + this._uicontrol.uuid;
		}

		_isEnabled(): boolean {
			return this._uicontrol.enabled;
		}
		_getViewportWidth(): number {
			return this._viewWidth;
		}
		_getViewportHeight(): number {
			return this._viewHeight;
		}
		_getContentWidth(): number {
			return this._contentWidth;
		}
		private _setContentWidth(width: number) {
			if (this._contentWidth == width) {
				return;
			}
			this._contentWidth = width;
		}
		_getContentHeight(): number {
			return this._contentHeight;
		}
		private _setContentHeight(height: number) {
			if (this._contentHeight == height) {
				return;
			}
			this._contentHeight = height;
		}
		_getQName(name: string): string {
			return this._scrollPaneContent.getQName(name);
		}
		_setScrollTop(e: events.CUIEvent, scrollTop: number): number {
			if (scrollTop < 0) {
				scrollTop = 0;
			} else if (scrollTop > this._getMaxContentTop()) {
				scrollTop = this._getMaxContentTop();
			}
			if (this._getScrollTop() == scrollTop) {
				return -1;
			}
			if (this._focusAssistant && this._uicontrol.focused) { // 스크롤 했을때 포커스된 엘리먼트가 사라지면서 포커스가 바디로 이동되어 포커스인데도 불구하고 방향키 이동이 안되는 현상 수정.
				this._focusScrollPaneOwner();
			}
			this._renderView(scrollTop);
			this._vScrollTop = scrollTop;

			return scrollTop;
		}
		_getScrollTop(): number {
			return this._vScrollTop;
		}
		_setScrollLeft(e: events.CUIEvent, scrollLeft: number): number {
			let viewportNode: HTMLElement = this._getNode("viewport");
			if (!viewportNode) {
				return -1;
			}
			let currentScrollLeft: number = viewportNode.scrollLeft;
			if (scrollLeft < 0) {
				scrollLeft = 0;
			} else if (scrollLeft > this._getMaxContentLeft()) {
				scrollLeft = this._getMaxContentLeft();
			}

			if (currentScrollLeft == scrollLeft) {
				return -1;
			}
			viewportNode.scrollLeft = scrollLeft;
			this._vScrollLeft = scrollLeft;
			return scrollLeft;
		}

		private _focusScrollPaneOwner() {
			let rootNode = this._getRenderer().getRootNode();
			if (rootNode["setActive"]) { // focus API에서 옵션으로 추가 필요.
				rootNode["setActive"](); // IE10,11에서 스크롤은 이동하지 않도 포커스만 설정됨.
			} else {
				this._uicontrol.focus();
			}
		}

		_onMousedownScroll(e: events.CMouseEvent) {
			e.preventDefault(); // 포커스 방지
			if (this._focusAssistant && this._uicontrol.focused == false) {
				this._focusScrollPaneOwner();
			}
		}
		_getScrollLeft(): number {
			return this._vScrollLeft
		}

		_getRenderer(): ufc.ControlRenderer {
			return this._uicontrol._getRenderer();
		}

		_checkResize(): void {

			let content = this._getNode(this._scrollPaneContent.dummyContentNodeName);
			let rowWrapElement = this._scrollPaneContent.findRowWrapElement(content);
			let rowHeight: number = this._rowHeight;
			if (rowWrapElement) {
				rowHeight = Math.ceil(rowWrapElement.getBoundingClientRect().height);
			}
			// let rowElement = this._scrollPaneContent.findRowElement(content as HTMLElement);
			let vw = this._getContentWidth();
			let rowCount = this._workingData.length;
			let vh = rowCount * rowHeight;
			let isHorizontalAutoSizeType = this._isHorizontalAutoSizeType();
			let isVerticalAutoSizeType = this._isVerticalAutoSizeType();

			let scrollPane = this._getNode("scroll-pane");
			let rect = scrollPane.getBoundingClientRect();
			let viewWidth = isHorizontalAutoSizeType ? vw : rect.width;
			let viewHeight = isVerticalAutoSizeType ? vh : rect.height;
			let reqHScroll = viewWidth < vw;
			let reqVScroll = viewHeight < vh;
			let hScrollWidth = () => { return vw <= viewWidth ? 0 : this._getScrollWidth(false) };
			let vScrollWidth = () => { return vh <= viewHeight ? 0 : this._getScrollWidth(true) };

			if (reqHScroll && isVerticalAutoSizeType == false) {
				viewHeight = viewHeight - hScrollWidth();
				if (viewHeight < vh) {
					viewWidth = viewWidth - vScrollWidth();
				}
			} else if (reqVScroll && isHorizontalAutoSizeType == false) {
				viewWidth = viewWidth - vScrollWidth();
				if (viewWidth < vw) {
					viewHeight = viewHeight - hScrollWidth();
				}
			}

			// 뷰포트의 크기가 변경되면 다시 그린다.
			if (this._getViewportHeight() != viewHeight || this._getViewportWidth() != viewWidth) {
				this._checkInfo({ viewWidth: viewWidth, viewHeight: viewHeight, vw: vw, vh: vh, rowHeight: rowHeight, reqHScroll: reqHScroll, reqVScroll: reqVScroll });
				this._updateContent();
				this._updateScrollbar();
			}

			this._uicontrol.getParent()._applyChildSizeChanging(this._uicontrol);
		}

		public _createShape(): ufc.ControlShape {
			this._workingData = this._scrollPaneContent["_getExpandedItems"]();
			return this._createScrollPane();
		}

		private _createScrollPane() {
			let vScrollWidth = this._getVScrollWidth();

			let dummyContent = this._scrollPaneContent.createDummyContents();
			let content = this._scrollPaneContent.createContents(this._startRowIndex, this._endRowIndex);
			controls.layouts.GridCSSBuilder._forCell()._withColumnStart(1)._withRowStart(1)._commit(content.style);
			let viewport: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: this._uicontrol._isUseCustomScroll() ? ["cl-viewport", "cl-customscrollbar"] : ["cl-viewport"],
				style: {
					position: "relative",
					width: "calc(100% - " + vScrollWidth + "px)",
					overflow: "hidden"
				},
				nodename: this._getQName("viewport"),
				children: [dummyContent, content]
			}

			controls.layouts.GridCSSBuilder._forLayout()._withTemplateColumns(["minmax(min-content, 1fr)"])._withTemplateRows("min-content")._commit(viewport.style);

			let vScrollShape: ufc.ElementShape = this._getRenderer()._getNamedShape(this._getQName("custom-vscroll"));
			let updateVScroll = this._getContentHeight() != (this._getRowHeight() * this._workingData.length);//스크롤바 길이가 갱신되는 경우 새로 생성하도록 한다.
			if (!vScrollShape || updateVScroll || !this._initVScroll) {
				vScrollShape = { // vertical scrollbar
					tag: "div"
					, nodename: this._getQName("custom-vscroll")
					, style: { display: "none" }
				};
				this._initVScroll = true;
			}

			let hScrollBlank: ufc.ElementShape = this._getRenderer()._getNamedShape(this._getQName("custom-hscroll-blank"));
			if (!hScrollBlank) {
				hScrollBlank = {
					tag: "div",
					classNames: ["cl-hscrollbar-blank", ufc.Classes.UNSELECTABLE],
					style: {
						display: "none"
					},
					nodename: this._getQName("custom-hscroll-blank")
				}
			}

			let hScrollShape: ufc.ElementShape = this._getRenderer()._getNamedShape(this._getQName("custom-hscroll"));
			if (!hScrollShape) {
				hScrollShape = { // horizontal scrollbar
					tag: "div"
					, nodename: this._getQName("custom-hscroll")
					, style: { display: "none" }
				};
			}

			let wrap: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: [ufc.Classes.UNSELECTABLE],
				attr: {},
				style: {
					height: "100%",
					width: "100%",
					position: "relative"
				},
				events: {},
				children: [viewport, vScrollShape, hScrollShape, hScrollBlank,
					_createTapLazyTask({
						task: () => {
							this._addDummyContent();
							this._checkInfo();
							this._updateContent();
							this._removeDummyContent();
							this._updateScrollbar();
						}
					})],
				nodename: this._getQName("scroll-pane")
			}

			ufc.ShapeUtil.addMandatoryEventHandler(viewport, "wheel", (e) => this._onWheel(e), true);
			ufc.ShapeUtil.addMandatoryEventHandler(viewport, "touchmove", (e) => this._onTouchMove(e), true);
			ufc.ShapeUtil.addMandatoryEventHandler(viewport, "touchstart", (e) => this._onTouchStart(e), true);
			ufc.ShapeUtil.addMandatoryEventHandler(viewport, "touchend", (e) => this._onTouchEnd(e), true);

			return wrap;
		}

		private _computedListMinWidth(viewport: HTMLElement) {
			let computedStyle = getComputedStyle(viewport);
			let listPadding = parseInt(computedStyle.paddingLeft) || 0;
			listPadding += parseInt(computedStyle.paddingRight) || 0;
			let itemMaxWidth = this._scrollPaneContent._getComputedItemWidth(this._workingData);

			let adjustWidth = 2;
			return itemMaxWidth + listPadding + adjustWidth;
		}

		private _checkInfo(checkedObj?: { viewWidth: number, viewHeight: number, vw: number, vh: number, rowHeight: number, reqHScroll: boolean, reqVScroll: boolean }) {
			let reqVScroll: boolean;
			let reqHScroll: boolean;
			let vh: number;
			let vw: number;

			if (checkedObj != null) {
				reqHScroll = checkedObj.reqHScroll;
				reqVScroll = checkedObj.reqVScroll;
				vw = checkedObj.vw;
				vh = checkedObj.vh;
				this._rowHeight = checkedObj.rowHeight;
				this._viewHeight = checkedObj.viewHeight;
				this._viewWidth = checkedObj.viewWidth;
			} else {
				// 가상 컨텐츠 크기 설정
				let content = this._getNode(this._scrollPaneContent.dummyContentNodeName);
				let rowWrapElement = this._scrollPaneContent.findRowWrapElement(content);
				if (rowWrapElement) {
					let rowHeight = Math.ceil(rowWrapElement.getBoundingClientRect().height);
					if (this._rowHeight != rowHeight) {
						this._rowHeight = rowHeight;
					}
				}

				let maxContentWidth = this._scrollPaneContent._isFitContentWidth() ? 0 : this._computedListMinWidth(this._getNode("viewport"));
				this._setContentWidth(maxContentWidth);
				let rowCount = this._workingData.length;
				this._setContentHeight(rowCount * this._rowHeight);
				let isHorizontalAutoSizeType = this._isHorizontalAutoSizeType();
				let isVerticalAutoSizeType = this._isVerticalAutoSizeType();
				// viewport 크기 설정
				vh = this._getContentHeight();
				vw = this._getContentWidth();
				let viewportNode = this._getNode("scroll-pane");
				// let uicontrolNode = this._getNode(this._scrollPaneContent.ns, false);
				let rect = viewportNode.getBoundingClientRect();
				this._viewWidth = isHorizontalAutoSizeType ? vw : rect.width;
				this._viewHeight = isVerticalAutoSizeType ? vh : rect.height;

				reqHScroll = this._viewWidth < vw;
				reqVScroll = this._viewHeight < vh;

				if (reqHScroll && isVerticalAutoSizeType == false) {
					this._viewHeight = this._viewHeight - this._getHScrollWidth();
					if (this._viewHeight < vh) {
						this._viewWidth = this._viewWidth - this._getVScrollWidth();
					}
				} else if (reqVScroll && isHorizontalAutoSizeType == false) {
					this._viewWidth = this._viewWidth - this._getVScrollWidth();
					if (this._viewWidth < vw) {
						this._viewHeight = this._viewHeight - this._getHScrollWidth();
					}
				}
			}

			// 스크롤 가능 크기 설정
			this._maxContentLeft = Math.max(0, vw - this._viewWidth);
			this._maxContentTop = Math.max(0, vh - this._viewHeight);

			// 스크롤이 없어지면 스크롤의 위치를 0으로 재설정.
			if (reqVScroll == false && this._getScrollTop() > 0) {
				this._vScrollTop = 0;
			}
			if (reqHScroll == false && this._getScrollLeft() > 0) {
				this._vScrollLeft = 0;
			}

			if (reqVScroll) {
				// 포커스 아이템
				if (this._scrollIndex != null) {
					let moveOffset = this._rowHeight * this._scrollIndex; // 이동할 위치
					this._vScrollTop = moveOffset > this._maxContentTop ? this._maxContentTop : moveOffset;
					this._scrollIndex = null;
				}
			}

			// 표시되는 아이템의 범위 설정
			let range = this._calculateRange(this._getScrollTop());
			this._endRowIndex = range.end;
			this._startRowIndex = range.start;
		}

		private _getNode(nodename: string, useQName: boolean = true) {
			if (useQName) {
				return this._getRenderer().getNamedNode(this._getQName(nodename));
			}
			return this._getRenderer().getNamedNode(nodename);
		}

		private _renderView(scrollTop: number) {
			let range = this._calculateRange(scrollTop);
			let oldStart = this._startRowIndex;
			let oldEnd = this._endRowIndex;

			this._startRowIndex = range.start;
			this._endRowIndex = range.end;
			if ((oldStart != this._startRowIndex || oldEnd != this._endRowIndex)) {
				this._updateContent();
			}
		}

		private _calculateRange(scrollTop: number) {
			if (this._autoSizeType == layouts.AutoSizeType.both || this._autoSizeType == layouts.AutoSizeType.height) {
				return { start: 0, end: this._workingData.length };
			}
			let rowHeight = this._getRowHeight();
			let y = Math.ceil(scrollTop);
			let buffer = 0; //영역 밖에 추가로 생성할 크기.
			let top = Math.ceil((y - buffer) / rowHeight);
			let bottom = Math.floor(top + (this._getViewportHeight() / rowHeight));

			let result = { start: 0, end: 0 };
			result.start = Math.max(0, top);
			result.end = Math.min(this._getContentHeight() / rowHeight, bottom);
			return result;
		}

		private _isVerticalAutoSizeType() {
			return this._autoSizeType == layouts.AutoSizeType.both || this._autoSizeType == layouts.AutoSizeType.height;
		}

		private _isHorizontalAutoSizeType() {
			return this._autoSizeType == layouts.AutoSizeType.both || this._autoSizeType == layouts.AutoSizeType.width;
		}
		private _getVScrollWidth() {
			if (this._getContentHeight() <= this._getViewportHeight()) {
				return 0;
			}
			return this._getScrollWidth(true);
		}

		private _getScrollWidth(isVertical: boolean) {
			let scrollbarWidth = 0;
			if (this._uicontrol._isUseCustomScroll()) {
				if (isVertical) {
					scrollbarWidth = ScrollbarUtil._getCustomScrollbarInfo().vWidth;
				} else {
					scrollbarWidth = ScrollbarUtil._getCustomScrollbarInfo().hHeight;
				}
			} else {
				scrollbarWidth = ScrollbarUtil._getNativeScrollWidth();
			}
			return scrollbarWidth;
		}
		private _getHScrollWidth() {
			if (this._getContentWidth() <= this._getViewportWidth()) {
				return 0;
			}
			return this._getScrollWidth(false);
		}

		private _getRowHeight(): number {
			return this._rowHeight;
		}

		private _getMaxContentTop(): number {
			return this._maxContentTop;
		}
		private _getMaxContentLeft(): number {
			return this._maxContentLeft;
		}
		private _getPageSize() {
			return Math.floor(this._getViewportHeight() / this._getRowHeight());
		}

		private _replace(nodename: string, shape: ufc.ControlShape) {
			this._getRenderer().replace(this._getQName(nodename), shape);
		}

		private _updateStyle(nodename: string, style: {}) {
			this._getRenderer().updateStyle(this._getQName(nodename), style, true);
		}

		private _updateClass(nodename: string, removeClasses: string[], addClasses: string[]) {
			this._getRenderer().updateClass(this._getQName(nodename), removeClasses, addClasses);
		}

		private _addDummyContent() {
			this._replace(this._scrollPaneContent.dummyContentNodeName, this._scrollPaneContent.createDummyContents({ item: new TreeItem("dummy", "_dummy", ""), index: 0 }));
		}

		private _removeDummyContent() {
			this._replace(this._scrollPaneContent.dummyContentNodeName, this._scrollPaneContent.createDummyContents())
		}

		private _updateContent() {
			let content = this._scrollPaneContent.createContents(this._startRowIndex, this._endRowIndex);
			controls.layouts.GridCSSBuilder._forCell()._withColumnStart(1)._withRowStart(1)._commit(content.style);
			// 조건에 따라 컨텐츠 너비를 스크롤 할 수 있는 크기로 설정한다.
			let allowAutoSizeType = this._autoSizeType == layouts.AutoSizeType.height || this._autoSizeType == layouts.AutoSizeType.width;
			let fixWidth = this._autoSizeType == layouts.AutoSizeType.none && this._getMaxContentLeft() > 0;
			if ((allowAutoSizeType || fixWidth) && this._scrollPaneContent._isFitContentWidth() == false) {
				content.style = _assign(content.style, { width: this._getContentWidth() + "px" });
			}
			this._replace(this._scrollPaneContent.contentNodeName, content);
		}

		public _updateScrollbar() {

			let vScrollWidth = this._getVScrollWidth();
			let hScrollWidth = this._getHScrollWidth();

			if (this._isHorizontalAutoSizeType()) {
				this._updateStyle("scroll-pane", { "padding-right": vScrollWidth + "px" });
				this._updateStyle("viewport", {
					width: "calc(100% - " + 0 + "px)",
					height: "calc(100% - " + hScrollWidth + "px)"
				});
			} else {
				this._updateStyle("viewport", {
					width: "calc(100% - " + vScrollWidth + "px)",
					height: "calc(100% - " + hScrollWidth + "px)"
				});
			}

			let reqVScroll = this._getMaxContentTop() > 0;
			let reqHScroll = this._getMaxContentLeft() > 0;
			let viewportScrollClasses = [];
			if (reqVScroll) {
				let vScrollShape = this._vscrollbar._createScrollbar(this._getScrollTop(), this._getContentHeight());
				if (reqHScroll) {
					vScrollShape.classNames.push("cl-with-hscrollbar");
				}
				this._replace("custom-vscroll", vScrollShape);
				this._vscrollbar._setScrollTop(this._getScrollTop());
				viewportScrollClasses.push("cl-width-vscrollbar");
			} else {
				let vScrollShape = { // horizontal scrollbar
					tag: "div"
					, nodename: this._getQName("custom-vscroll")
					, style: { display: "none" }
				};
				this._replace("custom-vscroll", vScrollShape);
			}

			if (reqHScroll) {
				let hScrollShape = this._hscrollbar._createScrollbar(this._getScrollLeft(), this._getContentWidth());
				if (reqVScroll) {
					hScrollShape.classNames.push("cl-with-vscrollbar");
				}
				this._setScrollLeft(null, this._getScrollLeft());
				this._replace("custom-hscroll", hScrollShape);
				this._hscrollbar._setScrollLeft(this._getScrollLeft());
				viewportScrollClasses.push("cl-width-hscrollbar");

				this._updateStyle("custom-hscroll-blank", {
					display: "block",
					height: hScrollWidth + "px"
				});
			} else {
				let hScrollShape = { // horizontal scrollbar
					tag: "div"
					, nodename: this._getQName("custom-hscroll")
					, style: { display: "none" }
				};
				this._replace("custom-hscroll", hScrollShape);
				this._updateStyle("custom-hscroll-blank", {
					display: "none"
				});
			}

			this._updateClass("viewport", [], viewportScrollClasses);

		}

		private _setVScrollbarTopOffset(e: events.CUIEvent, offset: number) {
			let scrollTop: number = this._getScrollTop();
			scrollTop += offset;
			return this._setVScrollbarTop(e, scrollTop);
		}

		private _setVScrollbarTop(e: events.CUIEvent, scrollTop: number): boolean {
			let movedScrollTop: number = this._setScrollTop(e, scrollTop);
			if (movedScrollTop == -1) {
				return false;
			}
			this._vscrollbar._setScrollTop(movedScrollTop);
			return true;
		}

		private _setHScrollbarLeftOffset(e: events.CUIEvent, offset: number): boolean {
			let scrollLeft: number = this._getScrollLeft();
			scrollLeft += offset;
			return this._setHScrollbarLeft(e, scrollLeft);
		}

		private _setHScrollbarLeft(e: events.CUIEvent, scrollLeft: number): boolean {
			let movedScrollLeft: number = this._setScrollLeft(e, scrollLeft);
			if (movedScrollLeft == -1) {
				return false;
			}
			this._hscrollbar._setScrollLeft(movedScrollLeft);
			return true;
		}

		/**
		 * content에 wheel 이벤트로 스크롤 위치에 보여질 아이템이 달라지면 redraw 한다.
		 * @param e 
		 */
		private _onWheel(e: events.CWheelEvent) {
			if (e.ctrlKey === true) { // 확대/축소
				return;
			}
			let delta: { x: number, y: number } = internal.ScrollbarUtil._getScrollPaneWheelDelta(e)
			if (delta == null) {
				return;
			}
			if (this._uicontrol["wheelRowCount"] != null) {
				let wheelRowCount = this._uicontrol["wheelRowCount"];
				delta.y = e.deltaY > 0 ? wheelRowCount * this._rowHeight : -wheelRowCount * this._rowHeight;
			}

			let moved: boolean = false;
			if (e.shiftKey) {
				if (this._hscrollbar) {
					moved = this._setHScrollbarLeftOffset(e, delta.x);
				}
			} else {
				if (this._hscrollbar && delta.x != 0) {
					moved = this._setHScrollbarLeftOffset(e, delta.x);
				}
				if (this._vscrollbar && delta.y != 0) {
					moved = this._setVScrollbarTopOffset(e, delta.y) || moved;
				}
			}

			if (moved) {
				e.stopPropagation();
				e.preventDefault();
			}
		}

		private _touchRoller: internal.TouchRoller = internal.newTouchRoller();

		private _onTouchStart(e: events.CTouchEvent) {
			this._touchRoller._touchStart(e,
				this._maxContentTop > 0 ? this._vscrollbar._getScrollTop() : -1,
				this._maxContentLeft > 0 ? this._hscrollbar._getScrollLeft() : -1
			);
		}

		private _onTouchMove(e: events.CTouchEvent): void {
			this._touchRoller._touchMove(e, (scrollTop: number, scrollLeft: number): boolean => {
				let movedY: boolean = scrollTop !== -1 ? this._setVScrollbarTop(e, scrollTop) : false;
				let movedX: boolean = scrollLeft !== -1 ? this._setHScrollbarLeft(e, scrollLeft) : false;

				return movedX || movedY;
			});
		}

		private _onTouchEnd(e: events.CTouchEvent) {
			this._touchRoller._touchEnd(e,
				this._maxContentTop > 0 ? this._vscrollbar._getScrollTop() : -1,
				this._maxContentLeft > 0 ? this._hscrollbar._getScrollLeft() : -1,
				(scrollTop: number, scrollLeft: number): boolean => {
					let movedY: boolean = scrollTop !== -1 ? this._setVScrollbarTop(e, scrollTop) : false;
					let movedX: boolean = scrollLeft !== -1 ? this._setHScrollbarLeft(e, scrollLeft) : false;

					return movedX || movedY;
				}
			);
		}

		/**
		 * 스크롤을 특정 행으로 이동한다.
		 * @param baseRowIndex 
		 * @param scrollIntoViewOptions 
		 * @returns 
		 */
		public scrollIntoView(baseRowIndex: number = 0, scrollIntoViewOptions?: { verticalAlign?: "start" | "center" | "end" | "nearest" }): boolean {
			let scrollTop = this._getScrollTop();
			if (scrollTop == null) {
				return false;
			}
			let rowHeight = this._getRowHeight();
			let viewRowCount = this._endRowIndex - (this._startRowIndex + 1);
			let verticalOption = scrollIntoViewOptions?.verticalAlign ?? "start";
			if (verticalOption == "start") {
				scrollTop = baseRowIndex * rowHeight;
			} else if (verticalOption == "center") {
				scrollTop = (baseRowIndex - Math.floor(viewRowCount / 2)) * rowHeight;
			} else if (verticalOption == "end") {
				scrollTop = (baseRowIndex - viewRowCount) * rowHeight;
			} else if (verticalOption == "nearest") {
				if (baseRowIndex < this._startRowIndex) {
					scrollTop = baseRowIndex * rowHeight;
				}
				else if (baseRowIndex > this._endRowIndex) {
					scrollTop = (baseRowIndex - viewRowCount) * rowHeight;
				}
			}

			if (scrollTop < 0) {
				scrollTop = 0;
			}
			let movedScrollTop = this._setScrollTop(null, scrollTop);
			if (movedScrollTop == -1) {
				return false;
			}
			this._vscrollbar._setScrollTop(movedScrollTop);
			return true;
		}

		/**
		 * 스크롤을 위로 올린다.
		 * @param baseRowIndex 행의 시작위치
		 * @param count 행이 이동할 크기
		 * @param viewport 스크롤을 갖는 HTMLElement
		 */
		public scrollUp(baseRowIndex: number = 0, count: number = 0): boolean {
			let scrollTop = this._getScrollTop();

			if (scrollTop == null) {
				return false;
			}
			let rowHeight = this._getRowHeight();
			let viewportHeight = this._getViewportHeight();
			let rowOffsetTop = baseRowIndex * rowHeight;
			let prevRowOffset = rowOffsetTop == 0 ? 0 : rowOffsetTop - (rowHeight * count);

			let viewOffsetMin = scrollTop;
			let viewOffsetMax = scrollTop + viewportHeight;

			if ((viewOffsetMin > prevRowOffset && viewOffsetMin - viewportHeight <= prevRowOffset)) {//다음 뷰포트로 이동
				scrollTop = scrollTop - (viewOffsetMin - prevRowOffset);
			} else if (viewOffsetMin > prevRowOffset || viewOffsetMax <= prevRowOffset) {// 알수 없응 위치에서 이동
				scrollTop = prevRowOffset;
			}
			if (scrollTop < 0) {
				scrollTop = 0;
			}
			let movedScrollTop = this._setScrollTop(null, scrollTop);
			if (movedScrollTop == -1) {
				return false;
			}
			this._vscrollbar._setScrollTop(movedScrollTop);
			return true;
		}

		/**
		 * 스크롤을 영역 안의 행의 크기만큼 이동한다.
		 * @param baseRowIndex 행의 시작위치
		 */
		public scrollPageUp(baseRowIndex: number = 0): boolean {
			return this.scrollUp(baseRowIndex, this._getPageSize() - 1);
		}

		/**
		 * 스크롤을 아래로 이동한다.
		 * @param baseRowIndex 행의 시작위치
		 * @param count 행이 이동할 크기
		 * @param viewport 스크롤을 갖는 HTMLElement
		 */
		public scrollDown(baseRowIndex: number = 0, count: number = 1): boolean {
			let scrollTop = this._getScrollTop();

			if (scrollTop == null) {
				return false;
			}
			let viewportHeight = this._getViewportHeight();
			let rowHeight = this._getRowHeight();
			let rowOffsetTop = baseRowIndex * rowHeight;
			let nextRowOffset = rowOffsetTop + (rowHeight * count);

			let viewOffsetMin = scrollTop;
			let viewOffsetMax = scrollTop + viewportHeight;

			if ((viewOffsetMax < nextRowOffset && viewOffsetMax + viewportHeight >= nextRowOffset)) {//다음 뷰 영역으로 이동 할때
				scrollTop = scrollTop + (nextRowOffset - viewOffsetMax);

			} else if (viewOffsetMin >= nextRowOffset || viewOffsetMax < nextRowOffset) { //알수 없는 위치에서 이동할때
				scrollTop = nextRowOffset - viewportHeight;
			} else if (viewOffsetMin > rowOffsetTop) {
				scrollTop = rowOffsetTop;
			}

			if (scrollTop < 0) {
				scrollTop = 0;
			}
			let movedScrollTop = this._setScrollTop(null, scrollTop);
			if (movedScrollTop == -1) {
				return false;
			}
			this._vscrollbar._setScrollTop(movedScrollTop);
			return true;

		}

		/**
		 * 스크롤을 영역 안의 행의 크기만큼 이동한다.
		 * @param baseRowIndex 행의 시작 위치
		 */
		public scrollPageDown(baseRowIndex: number): boolean {
			return this.scrollDown(baseRowIndex, this._getPageSize());
		}

		public dispose() {
			this._uicontrol = null;
			this._workingData = null;
			this._vscrollbar = null;
			this._hscrollbar = null;
			this._scrollPaneContent = null;
		}
	}


}