/// <reference path="./ItemListController.ts" />

namespace cpr.controls.item {

	/**
	 * @private
	 */
	export class TreeItemController extends ItemController<TreeItem, TreeItemSetConfig, ComboBoxItemListProvider> implements ITreeItemListView, ITreeItemList, IItemController<TreeItem> {

		/// 트리 전용 메소드
		findTreeByValue(findValue: string, items: TreeItem[]): TreeItem {
			return this._getTreeItemListView().findTreeByValue(findValue, items);
		}
		collapseAllItems(): void {
			return this._getTreeItemListView().collapseAllItems();
		}
		isExpanded(item: TreeItem): boolean {
			return this._getTreeItemListView().isExpanded(item);
		}
		setExpanded(item: TreeItem, state: boolean): void {
			return this._getTreeItemListView().setExpanded(item, state);
		}
		setChecked(sourceItem: TreeItem, state: boolean): boolean {
			return this._getTreeItemListView().setChecked(sourceItem, state);
		}
		getCheckedItems(): TreeItem[] {
			return this._getTreeItemListView().getCheckedItems();
		}
		setCheckedItems(checkedItems: TreeItem[]): void {
			this._getTreeItemListView().setCheckedItems(checkedItems);
		}
		getChildren(item?: TreeItem): TreeItem[] {
			return this._getTreeItemListView().getChildren(item);
		}
		/**
		 * 트리의 아이템들을 트리 구조로 반환합니다.
		 * @returns 
		 */
		getVisibleItemsAsTree(): TreeItem[] {
			return this._getTreeItemListView().getVisibleItemsAsTree();
		}
		getParent(item: TreeItem): TreeItem {
			return this._getTreeItemList().getParent(item);
		}
		hasParent(item: TreeItem): boolean {
			return this._getTreeItemList().hasParent(item);
		}
		hasChild(item: TreeItem): boolean {
			return this._getTreeItemList().hasChild(item);
		}
		getRootItems(): TreeItem[] {
			return this._getTreeItemList().getRootItems();
		}
		/// 트리 전용 메소드 끝

		private _getTreeItemListView(): TreeItemListView {
			return this._getItemListProvider().getTreeItemListView();
		}
		private _getTreeItemList(): TreeItemList {
			return this._getItemListProvider().getTreeItemList();
		}
	}
}