/// <reference path="../events/DOMEventWrapper.ts"/>

namespace cpr.foundation {

	/**
	 * @private
	 */
	export interface DateMaskOwner {
		readOnly: boolean;
		defaultDate: Date;
		defaultSelection: string;
		maxDate: Date;
		minDate: Date
		locale: string;
		_getValue(): string;
		_setValue(value: string): void;
		autoSelect: boolean;
		dispatchEvent(event: cpr.events.CEvent): boolean;
		getParent: () => core.DrawableControl;
		focused: boolean;
		_isShowing: () => boolean;
		spinLoop: boolean;
		isOpened: () => boolean;
		enabledInputMask: boolean;
		maskCharacter: string;
	}
	/**
	 * @private
	 */
	export interface DateMaskDelegate {
		format: () => string;
		displayFormat: () => string;
		getInputElement: () => HTMLInputElement;
	}
	export type DisplayMask = { Y: string, M: string, D: string, H?: string, d: string, h: string, k?: string, m: string, s: string, a: string, A: string, S: string };

	export abstract class AbstractDateMask {
		private static _selectionTokenSeq: number = 0;

		/**
		 * 선택 영역 작업을 DeferredUpdateManager에 예약할 때 쓰는 토큰.
		 * 같은 토큰의 작업은 한 프레임에 마지막 것만 실행되므로 마스크 인스턴스마다 고유해야 한다.
		 */
		private _selectionToken: string;

		protected abstract get _owner(): DateMaskOwner;

		abstract mergeMaskValue(originValue: string, originValueFormat: string): moment.Moment;

		/**
		 * 방향키 위/아래에 의한 세그먼트 스핀을 수행합니다.
		 * 사용자 keydown 이벤트의 preventDefault()를 존중하기 위해 입력 엘리먼트가 아닌
		 * DateInput 루트의 keydown 핸들러에서 호출합니다. release-test-project#11141
		 * @param e 키보드 이벤트
		 * @return 스핀을 처리한 경우 true
		 */
		abstract _spinByKeydown(e: events.CKeyboardEvent): boolean;

		/**
		 * 지금 편집 중인 포맷의 입력 세그먼트가 하나인지 여부를 반환합니다.
		 *
		 * 요일(dddd)과 오전/오후(A)는 사용자가 숫자를 입력하는 세그먼트가 아니므로 세지 않습니다.
		 * 세그먼트가 하나면 다시 입력하는 것이 곧 값 전체를 새로 입력하는 것이므로,
		 * "완성된 값을 편집하는 중에는 autoSkip을 실행하지 않음" 규칙을 적용하지 않습니다. release-test-project#11071
		 * @returns 입력 세그먼트가 하나인지 여부
		 */
		abstract isSingleInputSegmentFormat(): boolean;

		protected get _readOnly(): boolean {
			return this._owner.readOnly;
		}

		protected get _autoSelect(): boolean {
			return this._owner.autoSelect;
		}

		protected get _defaultSelection(): string {
			return this._owner.defaultSelection;
		}

		protected get _spinLoop(): boolean {
			return this._owner.spinLoop;
		}

		protected get _locale(): string {
			return this._owner.locale;
		}

		protected get _enabledInputMask(): boolean {
			return this._owner.enabledInputMask;
		}

		protected get _maskCharacter(): string {
			return this._owner.maskCharacter;
		}

		protected get _minDate(): Date {
			return this._owner.minDate;
		}

		protected get _maxDate(): Date {
			return this._owner.maxDate;
		}

		protected get _defaultDate(): Date {
			return this._owner.defaultDate;
		}

		protected get _focused(): boolean {
			return this._owner.focused;
		}

		/**
		 * 이번 포커스 이탈에서 입력 보정을 이미 수행했는지 여부.
		 * 마스크는 브라우저별 차이(IE는 blur가 다음 틱에 비동기로 발생) 때문에 blur와 focusout
		 * 양쪽에 같은 핸들러를 등록해 두었는데, 두 이벤트가 모두 발생하는 브라우저에서는 한 번의
		 * 포커스 이탈에 핸들러가 두 번 실행된다. 두 실행 사이에는 DateInput._onInputBlur가
		 * _validateValue로 값을 커밋하면서 마스크 버퍼를 이전 값으로 되돌리므로, 두 번째 실행은
		 * 되돌려진 버퍼를 입력란에 다시 써 넣는다. 그러면 사용자가 컨트롤의 blur 이벤트에서
		 * displayingText로 편집 중이던 텍스트를 볼 수 없다. release-test-project#11149
		 */
		private _blurAdjusted: boolean = false;

		/**
		 * 이번 포커스 이탈에서 입력 보정을 수행해야 하는지 여부를 반환합니다.
		 * 먼저 도착한 이벤트에서만 true를 반환하므로 blur와 focusout 중 하나만 발생하는
		 * 브라우저에서도 보정은 한 번 보장됩니다.
		 * @return 보정을 수행해야 하면 true.
		 */
		protected _shouldAdjustOnBlur(): boolean {
			if (this._blurAdjusted) {
				return false;
			}
			this._blurAdjusted = true;
			return true;
		}

		/**
		 * 입력 보정 수행 여부를 초기화합니다. 포커스를 얻는 시점에 호출합니다.
		 */
		protected _resetBlurAdjust(): void {
			this._blurAdjusted = false;
		}

		protected _createMomentForValue(date: string | Date, format?: string, strict: boolean = false): moment.Moment {
			return _createMoment(() => {
				if (date instanceof Date) {
					return moment(date)
				} else {
					return moment(date || null, format, strict);
				}
			});
		}

		protected _normalizeDefaultDateSelection(defaultSelection: string): string {
			if (controls.DefaultDateSelectionType[defaultSelection] == null) {
				return controls.DefaultDateSelectionType.none;
			}
			return defaultSelection;
		}

		protected _getFormatByDefaultDateSelection(defaultSelection: string, formats: string[]): string {
			defaultSelection = this._normalizeDefaultDateSelection(defaultSelection);

			let findDefaultFormat = (formatRegExp: RegExp) => {
				let result = "";
				formats.some((each: string) => {
					if (each.search(formatRegExp) > -1) {
						result = each;
						return true;
					}
					return false;
				});
				return result;
			}
			let format = "";
			switch (defaultSelection) {
				case "year":
					format = findDefaultFormat(/Y+/);
					break;
				case "month":
					format = findDefaultFormat(/M+/);
					break;
				case "day":
					format = findDefaultFormat(/D+/);
					break;
				case "hour":
					format = findDefaultFormat(/H+|h+|k+/);
					break;
				case "minute":
					format = findDefaultFormat(/m+/);
					break;
				case "second":
					format = findDefaultFormat(/s+/);
					break;
				case "millisecond":
					format = findDefaultFormat(/S+/);
					break;
				case "first":
					format = formats[0] ?? "";
					break;
				case "last":
					format = formats[formats.length - 1] ?? "";
					break;
			}
			return format;
		}

		/**
		 * 선택 영역 예약 토큰을 초기화합니다. 생성자에서 호출합니다.
		 * @param name 토큰 이름. 인스턴스 구분을 위한 일련번호가 뒤에 붙는다.
		 */
		protected _initSelectionToken(name: string): void {
			this._selectionToken = name + "-" + (++AbstractDateMask._selectionTokenSeq);
		}

		/**
		 * 선택 영역 작업을 다음 프레임 렌더링 후에 실행하도록 예약합니다.
		 * 같은 프레임에 여러 번 예약하면 마지막 작업만 실행됩니다.
		 * 예약을 취소하는 수단은 두지 않습니다. 취소는 2021년 IE의 autoSkip 잔존 선택(release-test-project#6375)을
		 * 막기 위한 것이었는데, 그 원인이던 숫자 입력 경로의 지연 설정이 release-test-project#10702에서 동기 설정으로
		 * 바뀌어 더는 필요하지 않습니다. 포커스가 다른 곳으로 옮겨진 뒤 실행될 수 있으므로 작업 안에서
		 * document.activeElement를 확인해야 합니다.
		 * @param func 실행할 작업.
		 */
		private _deferSelection(func: () => void): void {
			core.DeferredUpdateManager.INSTANCE._deferExec(this._selectionToken, func);
		}

		/**
		 * 입력 엘리먼트의 선택 영역을 설정합니다.
		 * 레거시 엣지는 포커스 직후 설정한 선택 영역을 끝으로 옮기는 현상이 있어 다음 프레임 렌더링 후로 미루고,
		 * 그 외 브라우저는 즉시 설정합니다. InputBox._setInputFocus와 같은 처리입니다.
		 * 실행 시점에 입력 엘리먼트에 포커스가 없으면 설정하지 않습니다.
		 * @param input 입력 엘리먼트.
		 * @param ss 선택 시작 위치.
		 * @param se 선택 끝 위치.
		 * @param defer true면 브라우저와 무관하게 다음 프레임 렌더링 후에 설정합니다.
		 * 마우스업이나 방향키처럼 브라우저 기본 동작이 핸들러 뒤에 선택 영역을 바꾸는 경우에 사용합니다.
		 */
		protected _setInputSelection(input: HTMLInputElement, ss: number, se: number, defer: boolean = false): void {
			let selectionAction = () => {
				if (document.activeElement === input) {
					input.setSelectionRange(ss, se);
				}
			};
			let isEdgeLegacy = _detectBrowser().name === "edge";
			if (defer || isEdgeLegacy) {
				this._deferSelection(selectionAction);
			} else {
				selectionAction();
			}
		}

		private _meridiem = {};

		private _convertMeridiemToLocaleData(localeData: Locale) {
			if (!localeData) {
				return null;
			}
			return [localeData.dateTime.meridiem.am, localeData.dateTime.meridiem.pm];
		}

		/**
		 * 마스크에서 표시하는 오전/오후 텍스트를 반환합니다.
		 * @param locale 
		 * @returns 
		 */
		public getMeridiems(locale: string): string[] {
			locale = SystemLocale._getValidLocale(locale);
			let meridiem = this._meridiem[locale];
			if (meridiem) {
				return meridiem;
			}
			return this._convertMeridiemToLocaleData(LocaleManager.INSTANCE._findLocaleData(locale) || LocaleManager.INSTANCE._findLocaleData());
		}

		/**
		 * 마스크에서 표시하는 오전/오후 텍스트를 설정합니다.
		 * @param locale 
		 * @param data 
		 */
		public setMeridiems(locale: string, data: string[]) {
			locale = SystemLocale._getValidLocale(locale);
			if (data == null) {
				if (this._meridiem[locale]) {
					delete this._meridiem[locale];
				}
				return;
			}
			this._meridiem[locale] = data;
		}

		protected _createMomentForMask(date: string | Date, format?: string, strict: boolean = false): moment.Moment {
			let meridiems = this.getMeridiems(this._locale);
			let mergeLocaleData: ILocaleDateTime = {};
			if (meridiems) {
				mergeLocaleData["meridiem"] = {
					am: meridiems[0],
					pm: meridiems[1]
				}
			}
			return _createMoment(() => {
				if (date instanceof Date) {
					return moment(date)
				} else {
					return moment(date || null, format, strict);
				}
			}, this._locale, mergeLocaleData);
		}

		private _display = {};

		private _convertDisplayMaskToLocaleData(localeData: Locale) {
			if (!localeData) {
				return null;
			}
			return {
				Y: localeData.dateMaskLabel.year,
				M: localeData.dateMaskLabel.month,
				D: localeData.dateMaskLabel.dayOfMonth,
				d: localeData.dateMaskLabel.dayOfWeek,
				H: localeData.dateMaskLabel.hour,
				h: localeData.dateMaskLabel.hour,
				k: localeData.dateMaskLabel.hour,
				m: localeData.dateMaskLabel.minute,
				s: localeData.dateMaskLabel.second,
				S: localeData.dateMaskLabel.millisecond,
				a: localeData.dateMaskLabel.meridiemLowercase,
				A: localeData.dateMaskLabel.meridiemUppercase
			}
		}

		protected _checkDisplayText(displayText: string) {
			return displayText?.replace(/[0-9]/g, "") ?? "";
		}

		public getDisplays(locale: string): DisplayMask {
			locale = SystemLocale._getValidLocale(locale);
			let display = this._display[locale];
			if (display) {
				return display;
			}
			return this._convertDisplayMaskToLocaleData(LocaleManager.INSTANCE._findLocaleData(locale) || LocaleManager.INSTANCE._findLocaleData());
		}

		public setDisplays(locale: string, data: DisplayMask) {
			locale = SystemLocale._getValidLocale(locale);
			if (data == null) {
				if (this._display[locale]) {
					delete this._display[locale];
				}
				return;
			}
			this._display[locale] = _mergeObject(this._display[locale], data);
		}
	}
}
