///<reference path="../utils/Logger.ts"/>

namespace cpr.controls {

	const POSITIONAL_PROPERTIES = ["left", "top", "right", "bottom", "width", "height", "position", "display"];
	let log = utils.Logger.forTopic("animation")._createBindedLoggerFunction({
		updator: it => log = it
	});

	// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/7386
	// CSSStyleDeclaration 과 동작을 통일하기 위해 노멀라이징 추가.
	function _normalizeCSSPropName(name: string) {
		return name.replace(/([a-z])([A-Z])/g, (grp, pre: string, after: string) => {
			return pre + "-" + after.toLowerCase();
		});
	}

	function _normalizeCSSMap(map: { [key: string]: string }): { [key: string]: string } {
		let normalizedMap = {};
		_.forEach(map, (value, key) => {
			normalizedMap[_normalizeCSSPropName(key)] = value;
		});
		return normalizedMap;
	}


	/**
	 * @private
	 */
	export interface CSSStyle {
		baseClass: string,
		customClasses?: string[], // 사용자 API 또는 디자인시 class를 추가하는 영역
		stateClasses?: string[], // cleopatra 내부에서 컨트롤의 상태에 따라 class를 추가하거나 제거할 수 있는 영역
		style?: { [key: string]: string },

		mediaClasses?: {
			[media: string]: string[]
		},
		mediaStyle?: {
			[media: string]: { [key: string]: string }
		}
	}

	function rejectPosionalProperties(styles: { [key: string]: string }) {
		let result: { [key: string]: string } = {}
		if (styles) {
			Object.keys(styles).forEach(k => {
				if (POSITIONAL_PROPERTIES.indexOf(k) === -1) {
					result[k] = styles[k]
				}
			});
		}
		return result
	}

	interface CSSDiff {
		/**
		 * 값을 덮어 쓰는 CSS 속성 값/키
		 */
		overrides: { [key: string]: string }

		/**
		 * 값이 제거된 CSS 속성 명.
		 */
		keysToRemove: string[]


		transition: string
	}

	function computeRevertState(currentState: { [key: string]: string }, newState: { [key: string]: string }): CSSDiff {
		let result: CSSDiff = {
			overrides: {},
			keysToRemove: [],
			transition: currentState["transition"]
		}

		Object.keys(newState).forEach(key => {
			if (currentState[key]) {
				result.overrides[key] = currentState[key];
			} else {
				result.keysToRemove.push(key)
			}
		})

		return result
	}

	abstract class Animation {
		protected _styler: UIControlStyler
		protected _state: { [key: string]: string }
		protected _duration: number
		protected _timingFunction: string

		constructor(styler: UIControlStyler, state: { [key: string]: string }, duration: number = 0.3, timingFunction: string = animation.TimingFunction.EASE_IN_OUT) {
			this._styler = styler;
			this._state = state;
			this._timingFunction = timingFunction;
			this._duration = duration
		}

		public abstract run(callback: () => void): void;

		public createTransitionStartEvent() {
			return new events.CTransitionEvent("transitionstart", {
				propertyNames: Object.keys(this._state),
				elapsedTime: 0
			});
		}

		public createTransitionEndEvent() {
			return new events.CTransitionEvent("transitionend", {
				propertyNames: Object.keys(this._state),
				elapsedTime: this._duration * 1000
			});
		}

		protected _makeSafeState(state: { [key: string]: string }): { [key: string]: string } {
			let control = this._styler._getOwner();
			if (control.isFloated()) {
				return state;
			} else {
				return rejectPosionalProperties(state);
			}
		}
	}

	class FromAnimation extends Animation {
		public run(callback: () => void): void {
			let owner = this._styler._getOwner();
			if (owner.disposed) {
				return;
			}

			this._state = this._makeSafeState(this._state)
			let currentState = this._styler.css() || {};

			// 애니메이션 종료 상태.
			let restoreState = computeRevertState(currentState, this._state)
			restoreState.overrides["transition"] = `all ${this._timingFunction} ${this._duration}s`;

			this._styler.css(this._state);
			this._styler.css("transition", "none");

			core.DeferredUpdateManager.INSTANCE.asyncExec(() => {
				if (owner.disposed) {
					return;
				}

				// 원래의 상태로 바꾸며 애니메이션 시작.
				this._styler.css(restoreState.overrides);
				restoreState.keysToRemove.forEach(k => {
					this._styler.removeStyle(k);
				});

				window.setTimeout(() => {
					if (owner.disposed) {
						return;
					}

					if (restoreState.transition) {
						this._styler.css("transition", restoreState.transition);
					} else {
						this._styler.removeStyle("transition");
					}
					if (callback) {
						window.setTimeout(callback);
					}
				}, this._duration * 1000);
			});
		}
	}

	class ToAnimation extends Animation {
		public run(callback: () => void): void {
			let owner = this._styler._getOwner();
			if (owner.disposed) {
				return;
			}

			let state = this._makeSafeState(this._state)
			let initialTransition = state["transition"];

			this._styler.css("transition", `all ${this._timingFunction} ${this._duration}s`)
			core.DeferredUpdateManager.INSTANCE.asyncExec(() => {
				if (owner.disposed) {
					return;
				}

				// 애니메이션 시작.
				this._styler.css(state);

				window.setTimeout(() => {
					if (owner.disposed) {
						return;
					}

					if (initialTransition) {
						this._styler.css("transition", initialTransition);
					} else {
						this._styler.removeStyle("transition");
					}
					if (callback) {
						window.setTimeout(callback);
					}
				}, this._duration * 1000);
			});
		}
	}

	class AutoReverseAnimation extends Animation {
		public run(callback: () => void): void {
			let owner = this._styler._getOwner();
			if (owner.disposed) {
				return;
			}

			let state = this._makeSafeState(this._state)
			let currentState = this._styler.css() || {};

			// 애니메이션 종료 상태.
			let restoreState = computeRevertState(currentState, state)

			this._styler.css("transition", `all ${this._timingFunction} ${this._duration}s`)

			core.DeferredUpdateManager.INSTANCE.asyncExec(() => {
				log("애니메이션 시작");
				if (owner.disposed) {
					return;
				}

				window.setTimeout(() => {
					log("애니메이션 중간점 도달");
					if (owner.disposed) {
						return;
					}

					// 원래 상태로 애니메이션.
					let reverseFunction = animation.TimingFunction.getReverseFunction(this._timingFunction)
					this._styler.css("transition", `all ${reverseFunction} ${this._duration}s`)
					this._styler.css(restoreState.overrides)
					restoreState.keysToRemove.forEach(k => {
						this._styler.removeStyle(k);
					});
					// FIXME: 타이밍 함수의 역함수 지정해야 함.

					// 애니메이션 중첩 방지도 필요함.
				}, this._duration * 1000);

				window.setTimeout(() => {
					log("애니메이션 종료")
					if (owner.disposed) {
						return;
					}

					// 트랜지션 원복.
					if (restoreState.transition) {
						this._styler.css("transition", restoreState.transition);
					} else {
						this._styler.removeStyle("transition");
					}
					if (callback) {
						window.setTimeout(callback);
					}
				}, this._duration * 2 * 1000);

				// 애니메이션 시작
				this._styler.css(state);
			});
		}
	}

	function _normalizeLength(exp: string | number, unit?: string, fallback?: number) {
		if (unit == null) {
			unit = ""
		}
		if (fallback == null) {
			fallback = 0;
		}
		switch (typeof exp) {
			case "number": return `${exp}${unit}`;
			case "string": return exp;
			default: return `${fallback}${unit}`;
		}
	}

	/**
	 * CSS 트랜스폼 속성 편집 컨텍스트.
	 * @noninstance
	 */
	export class CSSTransformContext {
		private _styler: UIControlStyler
		private _data: string[] = [];

		/**
		 * @param styler 스타일러.
		 * @private
		 */
		constructor(styler: UIControlStyler) {
			let current = styler.css("transform");
			if (!utils.Util.isNullOrEmpty(current)) {
				this._data = [current];
			} else {
				this._data = [];
			}
			this._styler = styler;
		}

		private _push(segment: string): CSSTransformContext {
			this._data.push(segment);
			this._styler.css("transform", this._data.join(" "));
			return this;
		}

		/**
		 * 축을 이동 시킵니다.
		 * 
		 * @param x x축 이동량. number 형 전달시 px 단위로 처리 됩니다.
		 * @param y y축 이동량. number 형 전달시 px 단위로 처리 됩니다.
		 * @param z z축 이동량. number 형 전달시 px 단위로 처리 됩니다.
		 */
		translate3d(x: string, y: string, z?: string): CSSTransformContext {
			x = _normalizeLength(x, "px");
			y = _normalizeLength(y, "px");
			z = _normalizeLength(z, "px", 0);
			return this._push(`translate3d(${x}, ${y}, ${z})`)
		}

		/**
		 * x축을 기준으로 회전합니다.
		 * @param value 회전값. number 형 전달시 deg 단위로 처리 됩니다.
		 */
		rotateX(value: string): CSSTransformContext {
			value = _normalizeLength(value, "deg");
			return this._push(`rotateX(${value})`)
		}

		/**
		 * y축을 기준으로 회전합니다.
		 * @param value 회전값. number 형 전달시 deg 단위로 처리 됩니다.
		 */
		rotateY(value: string): CSSTransformContext {
			value = _normalizeLength(value, "deg");
			return this._push(`rotateY(${value})`)
		}

		/**
		 * z축을 기준으로 회전합니다.
		 * @param value 회전값. number 형 전달시 deg 단위로 처리 됩니다.
		 */
		rotateZ(value: string): CSSTransformContext {
			value = _normalizeLength(value, "deg");
			return this._push(`rotateZ(${value})`)
		}

		/**
		 * 축 공간을 확대 합니다.
		 * @param x x축의 확대 비율.
		 * @param y y축의 확대 비율.
		 * @param z z축의 확대 비율.
		 */
		scale3d(x: string, y: string, z?: string): CSSTransformContext {
			x = _normalizeLength(x)
			y = _normalizeLength(x)
			x = _normalizeLength(x, null, 1)
			return this._push(`scale3d(${x}, ${y}, ${z})`);
		}

		/**
		 * 트랜스폼을 초기화 합니다.
		 * @param force 이 값이 참이면 스타일시트에 의해 부여된 transform 속성을 무시하고 강제로 "none" 으로 지정합니다.
		 */
		reset(force: boolean = false): CSSTransformContext {
			if (force) {
				this._styler.css("transform", "none")
			}
			else {
				this._styler.removeStyle("transform")
			}
			this._data = [];
			return this;
		}

		/**
		 * 원근감 깊이를 지정합니다.
		 * @param perspective 원근감 깊이. 단위 생략시 px로 처리 됩니다.
		 */
		perspective(perspective: string): CSSTransformContext {
			perspective = _normalizeLength(perspective, "px")
			return this._push(`perspective(${perspective})`);
		}
	}

	/**
	 * @private
	 */
	export interface UIControlStylerSpec {
		// ufc에서 자동 매핑... 
		root: CSSStyle,
		[nodename: string]: CSSStyle /* nodename과 스타일 ufc에서 자동 매핑 */
	}

	/**
	 * UIControlStyler
	 * 컨트롤의 스타일 클래스.
	 * @noinstance
	 */
	export class UIControlStyler implements resources.IDisposable, bind.BindablePropertiesOwner, expression.EvaluationContext {
		private _owner: UIControl;
		private _css: CSSStyle;
		private _subnodes: UIControlStyler[];
		private _isDisposed = false;
		private _nodename: string;
		private _bindables: bind.BindableProperties;
		private _bindContext: bind.BindContext;
		private _animationQueue: Animation[];
		private _isAnimating: boolean = false;

		/**
		 * @param owner 
		 * @param stylerSpec 
		 * @private
		 */
		constructor(owner: UIControl, stylerSpec?: UIControlStylerSpec) {
			this._owner = owner;
			this._bindables = new bind.BindableProperties(this, {
				allowsAnyProperty: true
			});

			this._bindables.add("-cl-class", "");

			if (stylerSpec) {
				this._subnodes = [];
				this._css = _defaults(stylerSpec.root, {
					customClasses: [],
					style: {},
					mediaClasses: {},
					mediaStyle: {}
				});
				// control 공통 class cl-control
				this._css.baseClass = "cl-control " + this._css.baseClass;
				this._nodename = "root";
				for (let nodename in stylerSpec) {
					if (nodename == "root") {
						continue;
					}
					let styler: UIControlStyler = new UIControlStyler(owner);
					styler._nodename = nodename;
					styler._css = _defaults(stylerSpec[nodename], {
						customClasses: [],
						style: {},
						mediaClasses: {},
						mediaStyle: {}
					});
					this[nodename] = styler;
					this._subnodes.push(styler);
				}
			} else {
				this._css = {
					baseClass: "",
					customClasses: [],
					style: {}
				};
			}
		}

		/**
		 * style 명을 반환합니다.
		 * @return style 명
		 */
		get name(): string {
			return this._nodename;
		}

		/**
		 * 기본 class 명을 반환합니다.
		 * @return 기본 class 명
		 */
		public getBaseClassName(): css_class_string {
			return this._css.baseClass;
		}

		/**
		 * class를 추가합니다.
		 * @param className class 명
		 */
		public addClass(className: css_class_string): void {
			let merged = this._css.customClasses || [];

			if (merged.indexOf(className) === -1) {
				merged.push(className);
				this._css.customClasses = merged;

				this._commit();
			}
		}
		public _addStateClass(className: string): void {
			let merged = this._css.stateClasses || [];

			if (merged.indexOf(className) === -1) {
				merged.push(className);
				this._css.stateClasses = merged;

				this._commit();
			}
		}

		/**
		 * 두 개 이상의 class를 설정합니다.<br>
		 * 예제:
		 * <pre><code> control.style.setClasses("buttonStyle", "imageStyle");</code></pre>
		 * @param classNames 추가할 class 명들.
		 */
		public setClasses(...classNames: css_class_string[]): void {
			this._css.customClasses = _.flatten(classNames);
			this._commit();

		}
		public _setStateClasses(...classNames: string[]): void {
			this._css.stateClasses = _.flatten(classNames);

			this._commit();
		}

		/**
		 * 컨트롤이 가진 class 명을 반환합니다.
		 * @return class 명.
		 */
		public getClasses(): css_class_string[] {
			let stateClasses: string[] = this._css.stateClasses ? this._css.stateClasses.slice(0) : [];
			if (this._bindables.isBinded("-cl-class")) {
				let exp = this._bindables.get("-cl-class") as string;
				if (exp) {
					// return exp.split(/\s+/g);
					return _.union(stateClasses, exp.split(/\s+/g));
				} else {
					return stateClasses;
					// return [];
				}
			}
			return _.union(stateClasses, this._css.customClasses ? this._css.customClasses.slice(0) : []);
		}

		/**
		 * 사용자가 설정한 클래스 이름을 반환합니다.
		 * @returns class 이름들
		 */
		public _getCustomClasses(): css_class_string[] {
			if (this._bindables.isBinded("-cl-class")) {
				let exp = this._bindables.get("-cl-class") as string;
				if (exp) {
					return exp.split(/\s+/g);
				} else {
					return [];
				}
			}
			return this._css.customClasses ? this._css.customClasses.slice(0) : [];
		}

		/**
		 *  트랜스폼 편집 문맥을 얻습니다.
		 */
		public get transform(): CSSTransformContext {
			return new CSSTransformContext(this);
		}

		/**
		 * 클래스 소유 여부를 확인합니다.
		 * @param className 확인할 클래스.
		 */
		public hasClass(className: css_class_string) {
			if (className == null) {
				return false
			}
			let classes = this.getClasses();
			return className.split(/\s+/g).filter(it => it.length > 0).every(it => {
				return classes.indexOf(it) !== -1;
			});
		}

		/**
		 * 해당 class를 삭제합니다.
		 * @param className class 명
		 */
		public removeClass(className: css_class_string): void {
			let indexToRemove = this._css.customClasses ? this._css.customClasses.indexOf(className) : -1;
			if (indexToRemove !== -1) {
				this._css.customClasses.splice(indexToRemove, 1);

				this._commit();
			}
		}
		public _removeStateClass(className: string): void {
			let indexToRemove = this._css.stateClasses ? this._css.stateClasses.indexOf(className) : -1;
			if (indexToRemove !== -1) {
				this._css.stateClasses.splice(indexToRemove, 1);

				this._commit();
			}
		}

		/**
		 * 해당 css property의 값을 반환합니다.<br>
		 * 값이 없을 시 지정된 기본 값으로 반환합니다.
		 * @param key css의 property 명
		 * @param defaultValue property에 대한 기본 값.
		 */
		public getCSS(key: string, defaultValue: string): string {
			let styleValue: string = this.css(key);
			return styleValue == null || styleValue == "" ? defaultValue : styleValue;
		}

		/**
		 * 지정된 모든 CSS 속성들을 JSON 형태로 얻습니다.
		 */
		public css(): { [key: string]: string };

		/**
		 * 특성 CSS 속성 값을 얻습니다.
		 * @param key 값을 얻을 속성 명
		 */
		public css(key: string): string;

		/**
		 * 특정 CSS 속성의 값을 지정합니다.<br>
		 * 컨트롤에서 설정되는 속성은 변경되지 않습니다.
		 * @param key 값을 지정할 CSS 속성명
		 * @param value 지정할 값.
		 */
		public css(key: string, value: string): void;

		/**
		 * 한 번에 여러 CSS 속성들을 지정합니다.<br>
		 * 컨트롤에서 설정되는 속성은 변경되지 않습니다.
		 * @param json 지정할 키와 값들을 가진 JSON 객체.
		 */
		public css(json: { [key: string]: string }): void;

		public css(): any {
			let args = _toArray(arguments);
			switch (args.length) {
				case 0: {
					let result = _mergeObject(this._css.style, this._bindables.resolveAll());
					delete result["-cl-class"]
					return result
				}

				case 1: {
					if (typeof args[0] == "string") {
						let key = _normalizeCSSPropName(args[0] as string);

						// 바인딩 된 키인 경우.
						if (this._bindables.isBinded(key)) {
							return this._bindables.get(key) || "";
						} else {
							return this._css.style[key] || "";
						}
					}
					else if (typeof args[0] == "object") {
						// 변경 여부, https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/issues/2195
						let changed = false;
						let newStyles = _normalizeCSSMap(args[0] as { [key: string]: string });

						Object.keys(newStyles).forEach(key => {
							if (this._bindables.isBinded(key)) {
								this._bindables.destroy(key);
								changed = true;
							}
							let eachValue = newStyles[key];
							if (this._css.style[key] != eachValue) {
								this._css.style[key] = eachValue;
								changed = true;
							}
						});
						if (changed) {
							// 변경된 경우에만 피스 렌더러 등록
							this._commit();
						}
					}
					else {
						throw new exceptions.IllegalArgumentException();
					}
					break;
				}

				case 2: {
					let key = _normalizeCSSPropName(args[0] as string);
					let value = args[1] as string;

					// 변경 여부, https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/issues/2195
					let changed = false;
					if (this._bindables.isBinded(key)) {
						this._bindables.destroy(key);
						changed = true;
					}

					if (typeof key != "string" || typeof value != "string") {
						throw new exceptions.IllegalArgumentException();
					}
					if (this._css.style[key] != value) {
						this._css.style[key] = value;
						changed = true;
					}
					if (changed) {
						// 변경된 경우에만 피스 렌더러 등록
						this._commit();
					}
					break;
				}
			}
		}

		/**
		 * 설정된 style의 해당 property를 제거합니다.
		 * @param propertyName property 명
		 */
		public removeStyle(propertyName: string): void {
			let key = _normalizeCSSPropName(propertyName);

			if (this._css.style.hasOwnProperty(key)) {
				delete this._css.style[key];
				this._commit();
			}
		}

		/* media style start */
		/**
		 * media class를 추가합니다.
		 * @param media media 명.
		 * @param className class 명.
		 */
		public addMediaClass(media: string, className: string): void {
			let merged = this._css.mediaClasses[media] || [];

			if (merged.indexOf(className) === -1) {
				merged.push(className);
				this._css.mediaClasses[media] = merged;

				this._commit();
			}
		}

		/**
		 * media에 두 개 이상의 class를 설정합니다.
		 * @param media media명.
		 * @param classNames class명
		 */
		public setMediaClasses(media: string, classNames: string[]): void {
			this._css.mediaClasses[media] = _stream(classNames).uniquify().collect();

			this._commit();
		}

		/**
		 * 컨트롤이 가진 해당 media의 class 명을 반환합니다.
		 * @param media media 명.
		 */
		public getMediaClasses(media: string): string[] {
			return this._css.mediaClasses[media] ? this._css.mediaClasses[media].slice(0) : [];
		}

		/**
		 * 해당 media의 class명을 삭제합니다.
		 * @param media media 명.
		 * @param className class 명.
		 */
		public removeMediaClass(media: string, className?: string): void {
			let indexToRemove = this._css.mediaClasses[media] ? this._css.mediaClasses[media].indexOf(className) : -1;
			if (indexToRemove !== -1) {
				this._css.mediaClasses[media].splice(indexToRemove, 1);

				this._commit();
			}
		}

		/**
		 * 해당 media의 css property를 설정합니다.
		 * @param media media 명.
		 * @param key property 명.
		 * @param defaultValue property에 대한 기본 값.
		 */
		public getMediaCSS(media: string, key: string, defaultValue: string): string {
			let styleValue: string = this.mediaCss(media, key);
			return styleValue == null || styleValue == "" ? defaultValue : styleValue;
		}

		public mediaCss(media: string): { [key: string]: string };
		public mediaCss(media: string, property: string): string;
		public mediaCss(media: string, property: string, value: string): void;
		public mediaCss(media: string, set: { [key: string]: string }): void;
		public mediaCss(): any {
			let args = _toArray(arguments);
			let media: string = args[0] as string;
			switch (args.length) {
				case 1: {
					return this._css.mediaStyle[media] || {};
				}

				case 2: {
					if (typeof args[1] == "string") {
						let key = _normalizeCSSPropName(args[1] as string);
						return this._css.mediaStyle[media] ? this._css.mediaStyle[media][key] || "" : "";
					}
					else if (typeof args[1] == "object") {
						this._css.mediaStyle[media] = _assign(this._css.mediaStyle[media] || {}, _normalizeCSSMap(args[1] as any));
						this._commit();
					}
					else {
						throw new exceptions.IllegalArgumentException();
					}
					break;
				}

				case 3: {
					let key = _normalizeCSSPropName(args[1] as string);
					let value = args[2] as string;
					if (typeof key != "string" || typeof value != "string") {
						throw new exceptions.IllegalArgumentException();
					}
					this._css.mediaStyle[media] = this._css.mediaStyle[media] || {};
					this._css.mediaStyle[media][key] = value;

					this._commit();
					break;
				}
			}
		}

		/**
		 * 설정된 media style의 해당 property를 제거합니다.
		 * @param media media 명.
		 * @param property property 명.
		 */
		public removeMediaStyle(media: string, property: string): void {
			let normalizedName = _normalizeCSSPropName(property);

			if (this._css.mediaStyle[media] && this._css.mediaStyle[media].hasOwnProperty(normalizedName)) {
				delete this._css.mediaStyle[media][normalizedName];

				this._commit();
			}
		}
		/* media style end */

		private _commit(): void {
			if (!this._owner) {
				return;
			}
			this._owner._applyPiece(new ufc.StylerRenderer(this));
		}

		/**
		 * style의 제거 여부를 반환합니다
		 */
		public get disposed(): boolean {
			return this._isDisposed;
		}

		/**
		 * 스타일에 포함된 객체들을 제거합니다.
		 */
		public dispose(): void {
			if (this._isDisposed) {
				return;
			}
			this._css = null;
			this._owner = null;
			if (this._subnodes) {
				this._subnodes.forEach((substyler: UIControlStyler) => {
					substyler.dispose();
				});
				this._subnodes = null;
			}

			this._isDisposed = true;
		}

		/**
		 * 해당 css 속성을 bind합니다.
		 * @param property bind할 css 속성 명.
		 */
		bind(property: string): bind.IBindFactory {
			return this._bindables.bind(_normalizeCSSPropName(property));
		}

		/**
		 * 클래스 바인딩 팩토리를 얻습니다.
		 */
		bindClass(): bind.IBindFactory {
			return this._bindables.bind("-cl-class")
		}

		/**
		 * 클래스 바인딩을 제거합니다.
		 */
		unbindClass() {
			this._bindables.unbind("-cl-class")
		}

		/**
		 * 해당 CSS 속성에 대한 바인딩을 해제 합니다.
		 * @param property 바인딩 해제할 CSS 속성 명.
		 */
		public unbind(property: string) {
			this._bindables.unbind(_normalizeCSSPropName(property));
		}

		/**
		 * 특정 CSS 속성에 대한 바인딩 정보를 얻습니다.
		 * @param property 바인딩 정보를 얻을 스타일 속성명.
		 * @return 바인딩 정보 객체.
		 */
		public getBindInfo(property: string): bind.BindInfo {
			return this._bindables.getBindableProperty(_normalizeCSSPropName(property))?.getCurrentBindInfo();
		}

		/**
		 * 스타일러의 CSS 클래스 바인딩 정보를 얻습니다.
		 * @return 클래스 바인딩 정보 객체.
		 */
		public getClassBindInfo() {
			return this._bindables.getBindableProperty("-cl-class")?.getCurrentBindInfo();
		}

		/**
		 * bind 문맥을 반환합니다.
		 * @return bind 문맥
		 */
		getBindContext(): bind.BindContext {
			return this._bindContext || this._owner.getBindContext();
		}

		_setBindContext(bindContext: bind.BindContext) {
			if (this._bindContext) {
				this._bindContext._setContextOwner(null);
			}
			this._bindContext = bindContext;
			if (this._bindContext) {
				this._bindContext._setContextOwner(this);
			}
		}

		_getExpressionDelegates() {
			return [this._owner]
		}

		public _getOwner() {
			return this._owner;
		}

		private _runAnimationIfNeeded() {
			if (!this._owner || this._owner.disposed || this._isAnimating || !this._animationQueue || this._animationQueue.length === 0) {
				return;
			}
			this._isAnimating = true;
			this._runNextAnimation()
		}

		/**
		 * _runAnimationIfNeeded에 의해서만 호출되어야 합니다. 호출하지 마십시오.
		 */
		private _runNextAnimation() {
			if (!this._owner || this._owner.disposed) {
				return;
			}

			if (!this._animationQueue || this._animationQueue.length === 0) {
				// 애니메이션 큐 종료.
				this._isAnimating = false
				return
			}

			let animation = this._animationQueue.shift()
			this._owner.dispatchEvent(animation.createTransitionStartEvent());
			animation.run(() => {
				if (!this._owner || this._owner.disposed) {
					return;
				}
				this._owner.dispatchEvent(animation.createTransitionEndEvent());
				this._runNextAnimation()
			});
		}

		/**
		 * 주어진 종료 상태로 애니메이션을 시작합니다.
		 * 
		 * @param state 종료 CSS 상태. 위치나 크기등, 레이아웃 요소의 스타일 값은 변경할 수 없습니다.
		 * @param duration 애니메이션의 길이, 단위는 초입니다.
		 * @param timingFunction 애니메이션 타이밍 함수, 사용 가능한 값은, cpr.animation.TimingFunction에 선언되어 있습니다.
		 */
		public animateTo(state: { [key: string]: string }, duration: number = 0.3, timingFunction: string = animation.TimingFunction.EASE_IN_OUT): UIControlStyler {
			if (!this._animationQueue) {
				this._animationQueue = []
			}
			this._animationQueue.push(new ToAnimation(this, state, duration, timingFunction));
			this._runAnimationIfNeeded()
			return this
		}

		/**
		 * 주어진 중간 상태로 애니메이션을 시작합니다.
		 * 중간 상태 진입 후 원래 상태로 돌아오기 까지 애니메이팅 됩니다.
		 * 
		 * @param state 중간 CSS 상태. 위치나 크기등, 레이아웃 요소의 스타일 값은 변경할 수 없습니다.
		 * @param duration 중간 상태에 도달하기 까지의 애니메이션의 길이, 단위는 초입니다.
		 * @param timingFunction 애니메이션 타이밍 함수, 사용 가능한 값은, cpr.animation.TimingFunction에 선언되어 있습니다.
		 */
		public animateAndReverse(state: { [key: string]: string }, duration: number = 0.3, timingFunction: string = animation.TimingFunction.EASE_IN_OUT): UIControlStyler {
			if (!this._animationQueue) {
				this._animationQueue = []
			}
			this._animationQueue.push(new AutoReverseAnimation(this, state, duration, timingFunction));
			this._runAnimationIfNeeded()
			return this
		}

		/**
		 * 주어진 상태로 부터 현재 상태로 애니메이션을 시작합니다.
		 * @param state 시작 CSS 상태. 위치나 크기등, 레이아웃 요소의 스타일 값은 변경할 수 없습니다.
		 * @param duration 애니메이션의 길이, 단위는 초입니다.
		 * @param timingFunction 애니메이션 타이밍 함수, 사용 가능한 값은, cpr.animation.TimingFunction에 선언되어 있습니다.
		 */
		public animateFrom(state: { [key: string]: string }, duration: number = 0.3, timingFunction: string = animation.TimingFunction.EASE_IN_OUT): UIControlStyler {
			if (!this._animationQueue) {
				this._animationQueue = []
			}
			this._animationQueue.push(new FromAnimation(this, state, duration, timingFunction));
			this._runAnimationIfNeeded()
			return this
		}

		/**
		 * bindable css와 일반 설정 css를 구분하여 반환합니다.
		 * @param isBindable 
		 */
		public _getCSS(isBindable: boolean): { [key: string]: string } {
			let result: { [key: string]: string } = null;
			if (isBindable == true) {
				result = _mergeObject(this._bindables.resolveAll());
				delete result["-cl-class"]
			} else {
				result = _mergeObject(this._css.style);
			}
			return result;
		}

		/**
		 * 모든 서브 스타일러 명을 얻습니다.
		 */
		public _getSubStylerNames(): string[] {
			if (!this._subnodes) {
				return [];
			}
			return this._subnodes.map(it => it._nodename);
		}

	}
}