/// <reference path="./DOMEventWrapper.ts" />


namespace cpr.events {
	/**
	 * Date 이벤트 유형
	 */
	export class DateEventType {
		/**
		 * date 클릭시 발생하는 이벤트.
		 */
		public static readonly DATECLICK: string = "date-click";

		public static readonly NAVIGATE: string = "navigate";

		public static readonly BEFORENAVIGATE: string = "before-navigate";
	}

	/**
	 * Date 관련 이벤트에 대한 옵션.
	 */
	export interface CDateEventOptions extends CUIEventOptions {
		/**
		 * Date 이벤트 유형.
		 */
		type?: string;
		/**
		 * 이벤트가 발생한 Date.
		 */
		date: any;
	}

	/**
	 * Date 클릭할 때 발생하는 이벤트.
	 */
	export class CDateEvent extends CMouseEvent {

		/**
		 * Date를 반환합니다.
		 * @return Date
		 */
		public get date(): Date {
			return this._getOption("date");
		}

	}
}