	export enum ScrollIntoViewAlignType {
		/**
		 * 뷰포트의 상단 가장자리에 위치하도록 스크롤 합니다.
		 */
		start = "start",
		/**
		 *  뷰포트의 가운데 위치하도록 스크롤 합니다.
		 */
		center = "center",
		/**
		 * 뷰포트의 하단 가장자리에 위치하도록 스크롤 합니다.
		 */
		end = "end",
		/**
		 * 뷰포트가 가장 가깝게 이동하여 표시할 수 있는 거리만큼만 스크롤합니다. 뷰포트에 이미 표시되어 있는 경우 동작하지 않습니다.
		 */
		nearest = "nearest"
	}

