	type TreeItemCondition = {
		label?: string, value?: string, icon?: string, tooltip?: string,
		parentValue?: string, parentItem?: TreeItem, depth?: number, checked?: boolean
	};

	/**
	 * 아이템 선택상태를 표시할 유형을 설정합니다.
	 */
	export enum SelectionHighlightType {
		/** 부모 아이템을 포함하여 선택 상태를 표시합니다. */
		cascade = "cascade",
		/**
		 * 자신만 선택 상태를 표시합니다.
		 */
		independent = "independent"
	}

