		override _createShape() {
			let rootShape: cpr.ufc.ControlShape = {
				classNames: [ufc.Classes.UNSELECTABLE],
				attr: {
					tabindex: "-1"
				},
				tag: "div",
				styler: "root",
				aria: "root",
				style: {},
				eventTargets: [
					ufc.EventTargetType.UICONTROL,
					ufc.EventTargetType.DROPPABLE
				],
				events: {
					keydown: this._onKeydown,
					click: this._onClick,
					mousedown: this._onMousedown,
					focus: this._onFocus
				},
				children: [],
				nodename: "sidenavigation"
			}

			if (this.readOnly) {
				rootShape.classNames.push(ufc.Classes.READONLY);
			}

			if (!this.enabled) {
				delete rootShape.attr['tabindex'];
				rootShape.classNames.push(ufc.Classes.DISABLED);
			}
			let rootItems = this._getRootItems(true);
			let selectedItem = this.getSelectionLast();
			let selectedValues = [];
			if (selectedItem) {
				let parent = selectedItem.parentItem;
				selectedValues.push(selectedItem.value);
				while (parent != null) {
					selectedValues.push(parent.value);
					parent = parent.parentItem;
				}
			}
			// 가상스크롤
			// if (this.useVirtualScroll) {
			// 	rootShape.children.push(this._createVirtualScrollPane(rootItems, selectedValues));
			// 	rootShape.events["resize"] = this._onResize; // 리사이즈 했을시 트리 아이템을 다시 표시해야 해야함.
			// } else {
			let viewport = this._createViewport(rootItems, selectedValues);
			let wrap = {
				tag: "div",
				classNames: [],
				style: {
					height: "100%",
					position: "relative"
				},
				children: [viewport]

			}
			if (this._isUseCustomScroll()) {
				(this._scroll as internal.ControlScrollPane).createScrollbar(wrap.children, viewport, wrap.children.length);
			} else {
				(this._scroll as internal.NativeScrollPane).createScrollbar(null, null, viewport, -1);
			}
			rootShape.children.push(wrap);
			// }
			cpr.ufc.ShapeUtil._setTooltipAttr(rootShape, { owner: this, title: this.tooltip });

			return rootShape;
		}

