		private _createViewport(rootItems: TreeItem[], selectedValues: string[]): cpr.ufc.ControlShape {
			// if (this._requestAutoOpen && rootItems.length > 0) {
			// 	this._expandByDepth(this.autoOpen, rootItems);
			// 	this._requestAutoOpen = false;
			// }

			let list = this._createList(null, rootItems, selectedValues);
			let shape: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: [],
				attr: {},
				style: {
					height: "100%",
					overflowX: "hidden"
				},
				children: [list],
				nodename: "viewport",
				events: {}
			}
			if (this._isUseCustomScroll()) {
				shape.style["overflow-y"] = "hidden";
			}
			return shape;
		}

		private _createList(parent: TreeItem, items: TreeItem[], selectedValues: string[]): ufc.ControlShape {
			let itemShapes = [];
			let len = items.length;
			items.forEach((each: TreeItem, idx: number) => {
				let node: ufc.ControlShape = {
					tag: "div",
					classNames: [],
					attr: {
						role: "listitem"
					},
					styler: "subtree",
					bindContext: each.toExpressionContext(this),
					children: []
				}
				let itemShape = this._createItem(each, len, idx, selectedValues);
				node.children.push(itemShape);
				if (itemShape.classNames.indexOf(ufc.Classes.FOLDER) > -1) {
					if (itemShape.classNames.indexOf(ufc.Classes.EXPANDED) > -1) {
						node.children.push(this._createList(each, each.children as TreeItem[], selectedValues));
					} else {
						if (parent == null || parent.expanded) {
							node.children.push(this._createList(each, each.children as TreeItem[], selectedValues));
						}
					}
				}
				itemShapes.push(node);
			});
			let list: ufc.ControlShape = {
				tag: "div",
				classNames: ["cl-list"],
				attr: {
					role: "list"
				},
				style: {
				},
				children: itemShapes
			}
			if (len > 0) {
				list.classNames.push(`cl-level-${items[0].depth + 1}`);
			}

			if (parent) {
				let nodename = parent.value + "-list";
				list.nodename = nodename;
				// list.classNames.push("cl-sub");
				// if (this._slidingAnimation.isAnimating() && this._slidingAnimation.isAnimatingNode(nodename)) {
				// 	let listOldShape = this._getRenderer()._getNamedShape(nodename);
				// 	if (listOldShape) {
				// 		list.style = listOldShape.style;
				// 	}
				// } else {
				list.style["display"] = parent.expanded ? "block" : "none";
				// }

			} else {
				// list.classNames.push("cl-list");
				list.style["display"] = "block";
			}
			return list;
		}

		private _createItem(item: TreeItem, size: number, childIndex: number, selectedValues: string[]): ufc.ControlShape {
			let isSelected = selectedValues.indexOf(item.value) > -1;
			let hasChild = item._hasChild();
			let isItemEnabled = this.getItemEnable(item);
			let depth = item.depth;
			let columnIndex = 1;
			let templateColumns = [];
			let children = [];

			// let paddingLeft = this.rootIndent;
			let paddingLeft = 0, rootIndent = 0;
			if (depth > 0) {
				paddingLeft = this.indent > -1 ? (this.indent * depth) + rootIndent : this.indent;
			}
			if (paddingLeft > 0) {
				templateColumns.push(paddingLeft + "px");
				columnIndex++;
			}

			let icon: ufc.ControlShape = {

				tag: "div",
				attr: { "data-name": "icon" },
				style: {},
				classNames: ["cl-icon"]
			}

			if (item.icon != null && item.icon != "") {
				icon.style['background-image'] = _quoteAsCSSURL(item.icon);
			}
			layouts.GridCSSBuilder._forCell()._withColumnStart(columnIndex++)._withRowStart(1)._withVerticalAlign(layouts.GridCellAlign.center)._commit(icon.style);
			templateColumns.push("auto");
			children.push(icon);

			let label = this._computeItemDisplayLabel(item);
			let text: ufc.ControlShape = {
				tag: "div",
				attr: { "data-name": "text" },
				classNames: [ufc.Classes.TEXT],
				style: {
					overflow: "hidden"
				},
				children: ufc.StyledString._asShape(label)
			}
			layouts.GridCSSBuilder._forCell()._withColumnStart(columnIndex++)._withRowStart(1)._withVerticalAlign(layouts.GridCellAlign.center)._commit(text.style);
			templateColumns.push("1fr");
			children.push(text);

			let badgeText = this._binder._getDisplayBadge(item);
			let badge = {
				tag: "div",
				classNames: [ufc.Classes.BADGE],
				attr: { "data-name": "badge" },
				style: {},
				children: ufc.StyledString._asShape(badgeText)
			}
			layouts.GridCSSBuilder._forCell()._withColumnStart(columnIndex++)._withRowStart(1)._withVerticalAlign(layouts.GridCellAlign.center)._commit(badge.style);
			templateColumns.push("min-content");
			children.push(badge);

			if (hasChild) {
				let expandIcon: ufc.ControlShape = {
					tag: "div",
					attr: { "data-name": "expand-icon" },
					classNames: ["cl-expand-icon"],
					style: {},
					children: []
				}
				layouts.GridCSSBuilder._forCell()._withColumnStart(columnIndex++)._withRowStart(1)._withVerticalAlign(layouts.GridCellAlign.center)._commit(expandIcon.style);
				templateColumns.push("auto");
				children.push(expandIcon);
			}

			let itemShape: ufc.ControlShape = {
				tag: "a",
				styler: "item",
				// stylerBindContext: item.toExpressionContext(this),
				bindContext: item.toExpressionContext(this),
				aria: "item",
				// ariaBindContext: item.toExpressionContext(this),
				style: {
					overflow: "hidden",
					position: "relative"
				},
				attr: {
					"data-itemid": item.value,
					"data-role": "menuitem"
				},
				classNames: [hasChild ? ufc.Classes.FOLDER : ufc.Classes.LEAF, `cl-level-${item.depth + 1}`],
				children: children
			}

			cpr.ufc.ShapeUtil._setTooltipAttr(itemShape, { owner: this, title: item.tooltip, id: item.value });
			cpr.ufc.ShapeUtil._setAriaDisabled(itemShape, this.enabled && isItemEnabled);

			layouts.GridCSSBuilder._forLayout()._withTemplateColumns(templateColumns)._withTemplateRows("1fr")._commit(itemShape.style);

			if (this.enabled) {
				if (isItemEnabled) {
					itemShape.attr["tabindex"] = "0";
				} else {
					itemShape.classNames.push(ufc.Classes.DISABLED);
				}
			}

			if (childIndex == 0) {
				itemShape.classNames.push(ufc.Classes.FIRST);
			}
			if (size - 1 == childIndex) {
				itemShape.classNames.push(ufc.Classes.LAST);
			}
			if (hasChild) {

				let isExpanded = item.expanded;
				if (isExpanded) {
					itemShape.classNames.push(ufc.Classes.EXPANDED);
				} else {
					itemShape.classNames.push(ufc.Classes.COLLAPSED);
				}
				itemShape.attr['aria-expanded'] = isExpanded + "";
			}
			if (isSelected) {
				let showSelected = this.selectionHighlightType == SelectionHighlightType.cascade ? true : this.isSelected(item);
				if (showSelected) {
					itemShape.classNames.push(ufc.Classes.SELECTED);
				}
			}
			if (item.checked) {
				itemShape.classNames.push(ufc.Classes.CHECKED);
			}
			return itemShape;
		}

