		public override _checkControlStateForEvent(e: events.CEvent = null): boolean {
			if (super._checkControlStateForEvent(e) == false) {
				return false;
			}

			let rootElement: HTMLElement = <HTMLElement>e.currentTarget;
			let targetElement: HTMLElement = <HTMLElement>e.target;
			let providedList = ["mousedown", "mouseup", "contextmenu",];

			if (providedList.indexOf(e.type) > -1) {
				let targetObject: { item: TreeItem } = { item: null }
				let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(targetElement)._closest("[data-role='menuitem']", rootElement);

				if (domTraverser) {
					let id = domTraverser._getAttribute("data-itemid");
					targetObject.item = this._binder.findTreeItem(id, this._getRootItems());
				}

				e._setTargetObject(targetObject);
			}

			return true;
		}

		private _getRootItems(newCreate: boolean = false) {
			if (!this._rootItems || newCreate) {
				this._rootItems = this._binder.getViewItems();
			}
			return this._rootItems;
		}

		private _getItemByElement(element: HTMLElement): TreeItem {
			let item: TreeItem = null;
			let id: string = element.getAttribute("data-itemid");
			if (id != null) {
				item = this._binder.getDataProvider().getByValue(id) as TreeItem;
			}
			return item;
		}

