		/**
		 * 해당 아이템을 펼칩니다. 펼쳐있는 상태라면 동작하지 않습니다.
		 * @param item 펼쳐질 아이템
		 * @param emitEvent 이벤트(node-open)를 발생시킬지 여부
		 */
		public expandItem(item: TreeItem, emitEvent: boolean = true): void {
			if (!this.isExpanded(item)) {
				this._setExpandedItem(item, true, null, emitEvent);
			}
		}

		/** 
		 * 트리아이템이 expanded 되어 있는지 여부를 반환합니다.
		 * @return 트리 아이템이 expanded 되어 있는지 여부.
		 */
		public isExpanded(item: TreeItem): boolean {
			let open = this._binder.isExpanded(item);
			return open == null ? false : open;
		}

		/**
		 * 해당 아이템을 접습니다. 접혀 있는 상태이면 동작하지 않습니다.
		 * @param item 접혀질 아이템
		 * @param emitEvent 이벤트(node-close)를 발생시킬지 여부
		 */
		public collapseItem(item: TreeItem, emitEvent: boolean = true): void {
			if (this.isExpanded(item)) {
				this._setExpandedItem(item, false, null, emitEvent);
			}
		}

