/// <reference path="./CustomAbstractScrollbar.ts" />


namespace cpr.controls.internal {
	/**
	 * @private
	 */
	export class CustomHScrollbar extends CustomAbstractScrollbar implements IVirtualHScrollbar {
		// content state
		private _maxThumbLeft: number;
		private _maxContentLeft: number;
		private _scrollLeft: number;

		// Scrollbar의 scrolltop과 viewport의 scrolltop 간의 비율
		private _trackViewRatio: number = 1;

		// mousemove state
		private _hscrollMouseMoveStart: boolean = false;
		private _startX: number = 0;

		// touch state
		private _thumbTouchStarted: boolean = false;
		private _thumbTouchStartX: number = -1;

		private _timer: number = null;
		private _holding: boolean = false;
		private _holdHandler;
		private _trackStartX: number = 0;


		constructor(scrollPane: IVirtualScrollPane) {
			super(scrollPane);
			this._scrollLeft = 0;
		}

		public _getHeight(): number {
			return internal.ScrollbarUtil._getCustomScrollbarInfo().hHeight;
		}

		public _setScrollLeft(scrollLeft: number): void {
			this._scrollLeft = scrollLeft;
			if (this._trackViewRatio === -1) {
				// visible = false 일 때
				return;
			}
			let thumbLeft: number = this._convToScrollbarLeft(scrollLeft);
			let newThumbLeft: number = this._checkHorizontalScrollbarRange(thumbLeft);
			this._updateStyle("custom-hscroll-thumb", { left: newThumbLeft + "px" });
			if (thumbLeft != newThumbLeft) {
				this._scrollLeft = this._convToContentScrollLeft(newThumbLeft);
				this._syncToPaneScrollLeft();
			}
		}

		public _getScrollLeft(): number {
			return this._scrollLeft;
		}

		public _createScrollbar(contentScrollLeft: number, contentWidth: number): ufc.ElementShape {
			let arrowLeft: ufc.ElementShape = {
				tag: "div",
				classNames: ["cl-arrow-left"],
				attr: {
				},
				style: {
				},
				mandatoryEvents: {
					mousedown: (e: events.CMouseEvent) => this._onBtnScrollLeft(e),
					mouseleave: (e: events.CMouseEvent) => this._onMouseLeaveHoldTarget(e),
					mouseenter: (e: events.CMouseEvent) => this._onMouseEnterHoldTarget(e)
				},
				children: []
			};
			let track: ufc.ElementShape = this._createTrackShape(contentScrollLeft, contentWidth);
			let arrowRight: ufc.ElementShape = {
				tag: "div",
				classNames: ["cl-arrow-right"],
				attr: {
				},
				style: {
				},
				mandatoryEvents: {
					mousedown: (e: events.CMouseEvent) => this._onBtnScrollRight(e),
					mouseleave: (e: events.CMouseEvent) => this._onMouseLeaveHoldTarget(e),
					mouseenter: (e: events.CMouseEvent) => this._onMouseEnterHoldTarget(e)
				},
				children: []
			};
			let shape: ufc.ElementShape = {
				tag: "div",
				nodename: this._getQName("custom-hscroll"),
				classNames: ["cl-hscrollbar", "cl-unselectable"],
				attr: {
				},
				style: {
				},
				mandatoryEvents: {
					wheel: (e: events.CWheelEvent) => this._onWheel(e),
					mousedown: (e: events.CMouseEvent) => {
						if (this._getScrollPane()._onMousedownScroll) {
							this._getScrollPane()._onMousedownScroll(e);
						}
					}
				},
				children: [arrowLeft, track, arrowRight]
			};
			return shape;
		}
		private _createTrackShape(contentScrollLeft: number, contentWidth: number): ufc.ElementShape {
			let track: ufc.ElementShape = {
				tag: "div",
				nodename: this._getQName("custom-hscroll-track"),
				classNames: ["cl-track"],
				attr: {
				},
				style: {
				},
				mandatoryEvents: {
					mousedown: (e: events.CMouseEvent) => this._onHorizontalTrackDown(e),
					mouseenter: (e: events.CMouseEvent) => this._onMouseEnterHoldTarget(e),
					mouseleave: (e: events.CMouseEvent) => this._onMouseLeaveHoldTarget(e),
					mousemove: (e: events.CMouseEvent) => this._onMouseMoveHoldTarget(e)
				},
				children: [
					_createDrawLazyTask({
						nodename: this._getQName("custom-hscroll-thumb"),
						task: () => {
							let thumbShape: ufc.ElementShape = null;

							let trackWidth: number = this._getTrackWidth();
							if (trackWidth === 0) {
								// visible = false 일 때
								thumbShape = {
									tag: "div",
									nodename: this._getQName("custom-hscroll-thumb"),
									classNames: ["cl-thumb"],
									attr: {},
									style: {},
									children: []
								}
								this._maxThumbLeft = 0;
								this._maxContentLeft = 0;
								this._trackViewRatio = -1;
								this._scrollLeft = contentScrollLeft;
							} else {
								let scrollPane: IVirtualScrollPane = this._getScrollPane();
								let viewportWidth: number = scrollPane._getViewportWidth();

								let viewableRatio: number = viewportWidth / contentWidth;
								let thumbWidth: number = viewableRatio * trackWidth;
								if (thumbWidth > trackWidth) {
									thumbWidth = trackWidth;
								} else if (thumbWidth < this.minThumbSize) {
									thumbWidth = this.minThumbSize;
								}

								this._maxThumbLeft = trackWidth - thumbWidth;
								this._maxContentLeft = contentWidth - viewportWidth;
								if (this._maxContentLeft === 0) {
									this._trackViewRatio = 0;
								} else {
									this._trackViewRatio = this._maxThumbLeft / this._maxContentLeft;
								}

								this._scrollLeft = contentScrollLeft;
								let thumbLeft: number = this._convToScrollbarLeft(contentScrollLeft);
								let newThumbLeft: number = this._checkHorizontalScrollbarRange(thumbLeft);
								if (thumbLeft != newThumbLeft) {
									thumbLeft = newThumbLeft;
									contentScrollLeft = this._convToContentScrollLeft(newThumbLeft);
									this._scrollLeft = contentScrollLeft;
									this._syncToPaneScrollLeft();
								}

								thumbShape = {
									tag: "div",
									nodename: this._getQName("custom-hscroll-thumb"),
									classNames: ["cl-thumb"],
									attr: {
									},
									style: {
										left: thumbLeft + "px",
										width: thumbWidth + "px"
									},
									mandatoryEvents: {
										mousedown: (e: events.CMouseEvent) => this._onHorizontalThumbMouseDown(e),
										touchstart: (e: events.CTouchEvent) => this._onHorizontalThumbTouchStart(e)
									},
									children: []
								};
								if (thumbWidth == trackWidth) {
									this._updateCSS("custom-hscroll", ["cl-noscrollable"], {}, true);
								}
							}

							return thumbShape;
						}
					})
				]
			};
			return track;
		}

		// event handler
		private _onHorizontalThumbMouseDown(e: events.CMouseEvent): void {
			if (this._checkPressedLeftButton(e) == false) {
				return;
			}
			if (this._getScrollPane()._isEnabled() == false) {
				return;
			}

			this._getScrollPane()._checkResize();

			this._hscrollMouseMoveStart = true;
			this._startX = e._getUnscaledClientX();
			this._dragStartThumb();
			// e.stopPropagation(); // track에 전파 막음
		}
		private _onHorizontalThumbMouseMove(e: events.CMouseEvent): void {
			if (this._hscrollMouseMoveStart == false || this._checkPressedLeftButton(e) == false) {
				this._dragEndThumb();
				return;
			}
			if (this._getScrollPane()._isEnabled() == false) {
				return;
			}

			// 타 이벤트 핸들러에서 커스텀스크롤바의 마우스무브 이벤트에 영향을 받지 않도록 이벤트 전파를 막음. ex) DragSource
			e.stopPropagation();
			e.stopImmediatePropagation();

			let deltaX: number = e._getUnscaledClientX() - this._startX;
			if (deltaX == 0) {
				return;
			}
			this._startX = e._getUnscaledClientX();
			this._scrollThumbHorizontal(e, deltaX)
		}
		private _onHorizontalThumbMouseUp(e: events.CMouseEvent): void {
			this._dragEndThumb();
		}
		private _onWheel(e: events.CWheelEvent): void { // wheel은 가로/세로 같이 사용
			if (e.ctrlKey === true) { // 확대/축소
				return;
			}
			this._getScrollPane()._checkResize();

			let delta: { x: number, y: number } = ScrollbarUtil._getScrollPaneWheelDelta(e);
			if (delta == null || delta.x === 0) {
				return;
			}

			// 콘텐트 위에서 굴렸을 때와 같은 규칙으로 이동량을 계산한다.
			let offsetX: number = ScrollbarUtil._toWheelOffset(delta.x, this._getScrollPane()._getViewportWidth());

			if (this._scrollContentHorizontal(e, offsetX)) {
				e.stopPropagation();
			}
			e.preventDefault(); // IE에서는 shift + wheel을 히스토리 이동으로 사용하기 때문에 기본동작을 차단함.
		}
		private _onBtnScrollLeft(e: events.CMouseEvent): void {
			if (this._getScrollPane()._isEnabled() == false) {
				return;
			}

			this._getScrollPane()._checkResize();

			let offset: number = ScrollbarUtil._getIntSize(this._getScrollPane()._getViewportWidth() * 0.2);

			this._holdStart(() => {
				this._repeat(null, () => {
					if (this._holding) {
						this._scrollContentHorizontal(e, -offset);
					}
				})
			});
		}
		private _onBtnScrollRight(e: events.CMouseEvent): void {
			if (this._getScrollPane()._isEnabled() == false) {
				return;
			}

			this._getScrollPane()._checkResize();

			let offset: number = ScrollbarUtil._getIntSize(this._getScrollPane()._getViewportWidth() * 0.2);
			this._holdStart(() => {
				this._repeat(null, () => {
					if (this._holding) {
						this._scrollContentHorizontal(e, offset);
					}
				})
			});
		}
		private _onHorizontalTrackDown(e: events.CMouseEvent): void {
			if (this._checkPressedLeftButton(e) == false) {
				return;
			}
			if (this._getScrollPane()._isEnabled() == false) {
				return;
			}

			let trackNode: HTMLElement = this._getNamedNode("custom-hscroll-track");
			if (e.target !== trackNode) {
				return;
			}
			this._getScrollPane()._checkResize();

			this._trackStartX = e._getUnscaledClientX();
			let offset: number = ScrollbarUtil._getIntSize(this._getScrollPane()._getViewportWidth() * 0.8);
			let thumbNode: HTMLElement = this._getNamedNode("custom-hscroll-thumb");
			if (thumbNode == null) {
				return;
			}
			let isScrollDown: boolean = this._trackStartX > thumbNode.getBoundingClientRect().left;
			this._holdStart(() => {
				this._repeat(null, () => {
					let thumbRect = thumbNode.getBoundingClientRect();
					if (isScrollDown && this._trackStartX > thumbRect.left + thumbRect.width) {
						this._scrollContentHorizontal(e, offset);
					} else if (!isScrollDown && this._trackStartX < thumbRect.left) {
						this._scrollContentHorizontal(e, -offset);
					}
				})
			});
		}
		private _onHorizontalThumbTouchStart(e: events.CTouchEvent): void {
			this._getScrollPane()._checkResize();

			if (this._getScrollPane()._isEnabled() == false) {
				return;
			}

			this._thumbTouchStarted = true;

			var touch: Touch = e.changedTouches[0];
			this._thumbTouchStartX = touch.clientX;
			this._dragStartThumb();
		}
		private _onHorizontalThumbTouchMove(e: events.CTouchEvent): void {
			if (this._thumbTouchStarted == false) {
				return;
			}
			if (e.touches.length !== 1) {
				return;
			}
			if (this._getScrollPane()._isEnabled() == false) {
				return;
			}

			e.preventDefault();
			e.stopPropagation();

			let touch: Touch = e.changedTouches[0];
			let offset: number = touch.clientX - this._thumbTouchStartX;
			if (offset == 0) {
				return;
			}
			this._thumbTouchStartX = touch.clientX;
			this._scrollThumbHorizontal(e, offset);
		}

		private _onHorizontalThumbTouchEnd(e: events.CTouchEvent): void {
			this._thumbTouchStarted = false;
			this._thumbTouchStartX = -1;
		}
		private _dragEventDispatcher = (e: any) => {
			if (this._hscrollMouseMoveStart || this._thumbTouchStarted) {
				if (e.type == "mouseup") {
					this._onHorizontalThumbMouseUp(e);
				} else if (e.type == "touchend") {
					this._onHorizontalThumbTouchEnd(e);
				} else if (e.type == "mousemove") {
					this._onHorizontalThumbMouseMove(e);
				} else if (e.type == "touchmove") {
					this._onHorizontalThumbTouchMove(e);
				}
			} else {
				if (e.type == "mouseup" || e.type == "touchend") {
					this._onMouseUpHoldTarget(e);
				}
			}
		}
		private _onMouseUpHoldTarget(e: MouseEvent) {
			if (!this._holding) {
				return;
			}
			this._holding = false;
			window.clearTimeout(this._timer);
			this._timer = null;
			this._holdEnd();
		}
		private _onMouseMoveHoldTarget(e: events.CMouseEvent) {
			if (this._checkPressedLeftButton(e) == false) {
				this._holdEnd();
				return;
			}
			if (this._holding) {
				this._trackStartX = e._getUnscaledClientX();
			}
		}
		private _onMouseEnterHoldTarget(e: events.CMouseEvent) {
			if (this._holding && this._timer == null) {
				if (this._holdHandler) this._holdHandler();
			}
		}
		private _onMouseLeaveHoldTarget(e: events.CMouseEvent) {
			if (this._holding && this._timer) {
				window.clearTimeout(this._timer);
				this._timer = null;
			}
		}
		// helper
		private _syncToPaneScrollLeft(): void {
			let deferredUpdateManager: core.DeferredUpdateManager = core.DeferredUpdateManager.INSTANCE;
			if (deferredUpdateManager._isRendering()) {
				deferredUpdateManager.asyncExec(this._paneScrollLeftSetter);
			} else {
				this._setPaneScrollLeft();
			}
		}
		private _paneScrollLeftSetter: () => void = () => this._setPaneScrollLeft();
		private _setPaneScrollLeft(): void {
			this._getScrollPane()._setScrollLeft(null, this._scrollLeft);
		}

		private _scrollContentHorizontal(e: events.CUIEvent, offset: number): boolean { // 컨텐트 스크롤탑의 변위를 이용해 컨텐트 스크롤탑과 세로스크롤바의 Thumb의 위치 변경
			let scrollLeft: number = this._getScrollLeft() + offset;
			if (scrollLeft < 0) {
				scrollLeft = 0;
			} else if (scrollLeft > this._maxContentLeft) {
				scrollLeft = this._maxContentLeft;
			}
			scrollLeft = this._getScrollPane()._setScrollLeft(e, scrollLeft);
			if (scrollLeft == -1 || scrollLeft == this._getScrollLeft()) {
				return false;
			}
			this._setScrollLeft(scrollLeft);
			return true;
		}
		private _getTrackWidth(): number {
			let trackNode: HTMLElement = this._getNamedNode("custom-hscroll-track");
			return trackNode.clientWidth;

			// let viewWidth: number = this._getScrollPane()._getViewportWidth();
			// let scrollbarInfo: ScrollbarInfo = ScrollbarUtil._getCustomScrollbarInfo();
			// return viewWidth - scrollbarInfo.hBtnWidth;
		}
		private _scrollThumbHorizontal(e: events.CUIEvent, offset: number): boolean { // 컨텐트 스크롤탑의 변위를 이용해 컨텐트 스크롤탑과 세로스크롤바의 Thumb의 위치 변경
			let contentOffset: number = this._convToContentScrollLeft(offset);
			let moved: boolean = this._scrollContentHorizontal(e, contentOffset);
			return moved;
		}
		private _convToScrollbarLeft(viewportScrollLeft: number): number { // 컨텐트 스크롤탑을 세로스크롤바의 Thumb 위치로 변환
			if (viewportScrollLeft == 0) {
				return viewportScrollLeft;
			}
			let trackLeft: number = viewportScrollLeft * this._trackViewRatio;
			return trackLeft;
		}
		private _convToContentScrollLeft(thumbLeft: number): number { // 세로스크롤바의 Thumb 위치를 컨텐트 스크롤탑으로 변환
			let viewLeft: number = 1 / this._trackViewRatio * thumbLeft;
			return viewLeft;
		}
		private _checkHorizontalScrollbarRange(trackLeft: number): number { // 세로스크롤바의 스크롤탑 레인지 계산
			if (trackLeft <= 0) {
				return 0;
			}
			if (trackLeft > this._maxThumbLeft) {
				trackLeft = this._maxThumbLeft;
			}
			return trackLeft;
		}
		private _dragStartThumb() {
			this._holdStart();
			cpr.events.BodyEventTarget.INSTANCE._addCaptureEventListener("mousemove", this._dragEventDispatcher);
			cpr.events.BodyEventTarget.INSTANCE._addCaptureEventListener("touchmove", this._dragEventDispatcher);
		}
		private _dragEndThumb() {
			this._holdEnd();
			this._hscrollMouseMoveStart = false;
			cpr.events.BodyEventTarget.INSTANCE._removeCaptureEventListener("mousemove", this._dragEventDispatcher);
			cpr.events.BodyEventTarget.INSTANCE._removeCaptureEventListener("touchmove", this._dragEventDispatcher);
		}
		private _holdEnd() {
			this._holding = false;
			this._holdHandler = null;
			this._trackStartX = 0;
			cpr.events.BodyEventTarget.INSTANCE._removeCaptureEventListener("mouseup", this._dragEventDispatcher);
			cpr.events.BodyEventTarget.INSTANCE._removeCaptureEventListener("touchend", this._dragEventDispatcher);
		}
		private _holdStart(handler?: Function) {
			this._holding = true;
			if (handler) {
				this._holdHandler = handler
				handler();
			}
			cpr.events.BodyEventTarget.INSTANCE._addCaptureEventListener("mouseup", this._dragEventDispatcher);
			cpr.events.BodyEventTarget.INSTANCE._addCaptureEventListener("touchend", this._dragEventDispatcher);
		}
		private _repeat(delay: number, handler, option?: any) {

			delay = delay || 500;
			window.clearTimeout(this._timer);
			this._timer = this._delay(() => {
				this._repeat(40, handler);
			}, delay);
			handler(option);
		}
		private _delay(handler, delay: number = 0) {
			return window.setTimeout(handler, delay);
		}
		private _checkPressedLeftButton(e: events.CMouseEvent) {
			let buttons = e.buttons ? e.buttons : e.which;
			return buttons == 1;
		}
	}
}