/// <reference path="../data/IDataRow.ts" />
namespace cpr.data {
	/**
	 * @experimental RELATED DataWindow
	 */
	export class CachedDataRow extends IDataRow implements expression.EvaluationContext {
		private _rowIndex: number;
		private _rowData: (string | number)[];


		constructor(dataWindow: DataCollection, rowIndex: number, rowData: (string | number)[]) {
			super(dataWindow);
			this._rowIndex = rowIndex;
			this._rowData = rowData;
		}

		public _getDataSet(): DataCollection {
			return super._getDataSet();
		}

		public _getRowData(): tabledata.RowData {
			throw new exceptions.UnsupportedOperationException();
		}

		public getIndex(): number {
			return this._rowIndex;
		}

		public getValue(columnName: string): (string | number) {
			let idx: number = this._getDataSet()._getColumnIndex(columnName);
			return idx >= 0 ? this._rowData[idx] : null;
		}

		public getRowData(columntype: header.HeaderType): RowConfigInfo {
			let dataWindow: DataCollection = this._getDataSet();
			return dataWindow.getRowData(this._rowIndex, columntype);
		}

		public _getHeader(columnName: string): header.Header {
			return super._getHeader(columnName);
		}

		public getString(columnName: string): string {
			return utils.Util.toString(this.getValue(columnName));
		}

		public getNumber(columnName: string): number {
			return utils.Util.toNumber(this.getValue(columnName));
		}

		public getBoolean(columnName: string): boolean {
			return utils.Util.toBoolean(this.getValue(columnName));
		}

		public _getDecimal(columnName: string): foundation.DecimalType {
			let header: header.Header = this._getDataSet().getHeader(columnName);
			if (header == null) {
				return null;
			}
			let datatype: tabledata.DataType = header.getDataType();
			let resultValue: foundation.DecimalType = null;
			if (datatype == tabledata.DataType.DECIMAL || datatype == tabledata.DataType.NUMBER) {
				let value: (string | number) = this.getValue(columnName);
				if (value != null && value !== "") {
					resultValue = new foundation.DecimalType(value as number);
				}
			}
			return resultValue;
		}

		public getOriginalValue(columnName: string): any {
			return this.getValue(columnName);
		}

		public getState(): tabledata.RowState {
			return tabledata.RowState.UNCHANGED;
		}

		public getStateString(isAbbreviation: boolean = true): string {
			return DataUtil._getStateString(this.getState(), isAbbreviation);
		}

		public getAttr(attrName: string): string {
			return null;
		}

		public getAttrNames(): string[] {
			return [];
		}

		public getAttrs(): { [attrName: string]: string } {
			return {};
		}

		public _getCtrlAttr(control: controls.Control, attrName: string): any {
			return null;
		}

		/////////////////////////
		// UNSUPPORTED METHODS //
		/////////////////////////
		public setRowData(rowData: RowConfigInfo): boolean {
			throw new exceptions.UnsupportedOperationException("setRowData is not supported");
		}
		public setValue(columnName: string, value: any): boolean {
			throw new exceptions.UnsupportedOperationException("setValue is not supported");
		}
		public setState(state: tabledata.RowState): void {
			throw new exceptions.UnsupportedOperationException("setState is not supported");
		}
		public putValue(columnName: string, value: any): boolean {
			throw new exceptions.UnsupportedOperationException("putValue is not supported");
		}
		public setAttr(attrName: string, attrValue: string): void {
			throw new exceptions.UnsupportedOperationException("setAttr is not supported");
		}
		public _setCtrlAttr(control: controls.Control, attrName: string, attrValue: any): void {
			throw new exceptions.UnsupportedOperationException("_setCtrlAttr is not supported");
		}
		public _deleteCtrlAttr(control: controls.Control, attrName: string): void {
			throw new exceptions.UnsupportedOperationException("_deleteCtrlAttr is not supported");
		}
		public _getRowCtrlAttr(control: controls.Control): tabledata.RowCtrlAttr {
			throw new exceptions.UnsupportedOperationException("_getRowCtrlAttr is not supported");
		}

	}

}