namespace cpr.controls {

	/**
	 * Tree의 접근성을 관리하는 클래스
	 * tree (root), item의 2단계 구조를 제공합니다.
	 * forItem()을 통해 개별 아이템별 설정이 가능합니다.
	 * @noinstance
	 */
	export class TreeAccessibility extends Accessibility {

		public static _getSpec(): AriaSpec {
			return { root: { role: "tree" }, item: { role: "treeitem" } };
		}

		protected override _createAccessibility(name: string, spec: AriaSet): Accessibility {
			switch (name) {
				case "item":
					let a11y = new ItemsAccessibility(this._getOwner(), { root: spec });
					a11y._setName(name);
					return a11y;
				default:
					return super._createAccessibility(name, spec);
			}
		}

		/**
		 * 모든 item 항목에 대한 기본 접근성 설정을 반환합니다.
		 * forItem()을 통해 개별 아이템별 설정이 가능합니다.
		 * @returns item 역할에 대한 ItemsAccessibility
		 */
		public get item(): ItemsAccessibility {
			return this._getSubAccessibility("item") as ItemsAccessibility;
		}

		/**
		 * 특정 Item이 제거될 때 호출되어 캐시를 정리합니다.
		 * @param item 제거될 Item
		 */
		public _removeItem(item: Item): void {
			this.item._removeItemAccessibility(item);
		}

		/**
		 * 모든 Item의 Accessibility 캐시를 제거합니다.
		 */
		public _clearAllItems(): void {
			this.item._clearItemAccessibilities();
		}
	}
}