		public _getAutoFit(): string {
			// return this._gridProperty.autoFit;

			// if (this._initTemp.autoFit != null) {
			// 	let autoFit: string = this._initTemp.autoFit;
			// 	delete this._initTemp.autoFit;
			// 	this._setAutoFit(autoFit);
			// 	return autoFit;
			// } else
			if (this._gridLayout?.columnLayout != null) {
				let autofits: number[] = [];
				this._gridLayout.columnLayout.forEach((item: GridColumnProp, index: number) => {
					if (item.autoFit == true) {
						autofits[autofits.length] = index;
					}
				});
				if (autofits.length == 0) {
					return "none";
				} else if (autofits.length == this._gridLayout.columnLayout.length) {
					return "all";
				} else {
					return autofits.join(", ");
				}
			} else {
				return this._gridProperty.autoFit;
			}
		}
		public _setAutoFit(autoFit: string): void {
			this._gridProperty.autoFit = autoFit;

			if (this._gridLayout?.columnLayout != null) {
				// 로직이 중복됨 TODO 공통화
				let autoFitArr: string[] = [];
				if (autoFit != "none" && autoFit != "all") {
					autoFit = this._checkColumnRange(autoFit);
					autoFitArr = autoFit.match(/\d+/g);
				}
				this._gridLayout.columnLayout.forEach((item: GridColumnProp, index: number) => {
					if (autoFit == "all" || autoFitArr.indexOf("" + index) != -1) {
						item.autoFit = true;
					} else {
						item.autoFit = false;
					}
				});
			} else {
				// this._initTemp.autoFit = autoFit;
			}
		}

