		public _setActivateRowGroup(groupCondition: string, activate: boolean): void {
			if (this._gridLayout["rowGroup"] == null) {
				return;
			}
			if (this._gridLayout["rowGroup"].length == 0) {
				return;
			}

			let length: number = this._gridLayout["rowGroup"].length;
			for (let i = 0; i < length; i++) {
				if (this._gridLayout["rowGroup"][i].groupCondition == groupCondition) {
					this._gridLayout["rowGroup"][i].activate = activate;
					return;
				}
			}
		}
