		public _validationCheckInsert(cellIndex: number, after: boolean): boolean {
			let targetCell: GridHeaderCellProp = null;
			this._gridLayout.header.cellProp.some((cellProp: GridHeaderCellProp) => {
				if (cellProp.constraint.cellIndex == cellIndex) {
					targetCell = cellProp;
					return true;
				}
			})
			if (targetCell == null) {
				return false;
			}

			let result: boolean = true;
			let insertColIndex: number = -1;
			if (after == false) {
				insertColIndex = targetCell.constraint.colIndex;
			} else {
				insertColIndex = (targetCell.constraint.colSpan == null) ? (targetCell.constraint.colIndex + 1) : targetCell.constraint.colIndex + targetCell.constraint.colSpan;
			}

			// header
			let hLength: number = this._gridLayout.header.cellProp.length;
			for (let i = 0; i < hLength; i++) {
				let cellProp: GridHeaderCellProp = this._gridLayout.header.cellProp[i];
				let si: number = cellProp.constraint.colIndex;
				let ei: number = (cellProp.constraint.colSpan == null) ? cellProp.constraint.colIndex + 1 : cellProp.constraint.colIndex + cellProp.constraint.colSpan;
				if (si < insertColIndex && insertColIndex < ei) {
					result = false;
					break;
				}
			}
			if (result == false) { return false; }

			// detail
			let dLength: number = this._gridLayout.detail.cellProp.length;
			for (let i = 0; i < dLength; i++) {
				let cellProp: GridDetailCellProp = this._gridLayout.detail.cellProp[i];
				let si: number = cellProp.constraint.colIndex;
				let ei: number = (cellProp.constraint.colSpan == null) ? cellProp.constraint.colIndex + 1 : cellProp.constraint.colIndex + cellProp.constraint.colSpan;
				if (si < insertColIndex && insertColIndex < ei) {
					result = false;
					break;
				}
			}
			if (result == false) { return false; }

			// footer
			if (this._gridLayout.hasOwnProperty("footer")) {
				let fLength: number = this._gridLayout.footer.cellProp.length;
				for (let i = 0; i < fLength; i++) {
					let cellProp: GridFooterCellProp = this._gridLayout.footer.cellProp[i];
					let si: number = cellProp.constraint.colIndex;
					let ei: number = (cellProp.constraint.colSpan == null) ? cellProp.constraint.colIndex + 1 : cellProp.constraint.colIndex + cellProp.constraint.colSpan;
					if (si < insertColIndex && insertColIndex < ei) {
						result = false;
						break;
					}
				}
				if (result == false) { return false; }
			}
			// rowgroup
			if (this._gridLayout.hasOwnProperty("rowGroup")) {
				this._gridLayout.rowGroup.forEach((rowGroup: GridRowGroupConfig) => {
					if (rowGroup.hasOwnProperty("gheader")) {
						let ghLength: number = rowGroup.gheader.cellProp.length;
						for (let i = 0; i < ghLength; i++) {
							let cellProp: GridFooterCellProp = rowGroup.gheader.cellProp[i];
							let si: number = cellProp.constraint.colIndex;
							let ei: number = (cellProp.constraint.colSpan == null) ? cellProp.constraint.colIndex + 1 : cellProp.constraint.colIndex + cellProp.constraint.colSpan;
							if (si < insertColIndex && insertColIndex < ei) {
								result = false;
								break;
							}
						}
						if (result == false) { return false; }
					}
					if (rowGroup.hasOwnProperty("gfooter")) {
						let gfLength: number = rowGroup.gfooter.cellProp.length;
						for (let i = 0; i < gfLength; i++) {
							let cellProp: GridFooterCellProp = rowGroup.gfooter.cellProp[i];
							let si: number = cellProp.constraint.colIndex;
							let ei: number = (cellProp.constraint.colSpan == null) ? cellProp.constraint.colIndex + 1 : cellProp.constraint.colIndex + cellProp.constraint.colSpan;
							if (si < insertColIndex && insertColIndex < ei) {
								result = false;
								break;
							}
						}
						if (result == false) { return false; }
					}
				})
			}
			return true;
		}

		public _getColIndexByCellIndex(cellIndex: number, after: boolean): number {
			let targetCell: GridHeaderCellProp = null;
			this._gridLayout.header.cellProp.some((cellProp: GridHeaderCellProp) => {
				if (cellProp.constraint.cellIndex == cellIndex) {
					targetCell = cellProp;
					return true;
				}
			})
			if (targetCell == null) {
				return -1;
			}

			let colIndex: number = -1;
			if (after == false) {
				colIndex = targetCell.constraint.colIndex;
			} else {
				colIndex = (targetCell.constraint.colSpan == null) ? (targetCell.constraint.colIndex + 1) : targetCell.constraint.colIndex + targetCell.constraint.colSpan;
			}
			return colIndex;
		}

