		public _getTobeCellWidth(cellIndex: number, oldCellwidth: number, tobeRenderWidth: number, viewportWidth: number, regionColumnLayout: gridpart.GridColumnProp[]): string {
			let totalColumnWidth: number = 0;
			regionColumnLayout.forEach((columnProp: GridColumnProp) => {
				if (columnProp.visible) {
					totalColumnWidth += columnProp.width;
				}
			})
			if (totalColumnWidth - oldCellwidth + tobeRenderWidth >= viewportWidth) {
				// 변경 후 width가 viewport보다 크다면 스크롤이 생기므로 tobeRenderWidth 그대로 반환.
				return tobeRenderWidth + "px";
			}
			return this._colManager._getTobeCellWidth(cellIndex, tobeRenderWidth, regionColumnLayout, viewportWidth);
		}
		/**
		 * @param srcHeaderIndex : 이동할 Header의 index
		 * @param targetHeaderIndex : 이동시킬 대상 Header의 Index
		 * @param before : targetHeader의 앞으로 이동할 지 뒤로 이동할 지
		 */
		public _moveColumn(srcHeaderIndex: number, targetHeaderIndex: number, before: boolean = true): boolean {
			let result: boolean = this._colManager._moveColumn(srcHeaderIndex, targetHeaderIndex, before);
			if (result) {
				this._initRegionRowGroupConfig();
				let autoFit: string = this._getAutoFit();
				if (autoFit != "all" && autoFit != "none") {
					let autoFit: number[] = [];
					this._gridLayout.columnLayout.forEach((columnProp: GridColumnProp, index: number) => {
						if (columnProp.autoFit == true) {
							autoFit[autoFit.length] = index;
						}
					});
					// autofit setter에서 재계산되는걸 방지하기 위해 직접 세팅
					this._gridProperty.autoFit = autoFit.join(",");
				}
			}
			return result;
		}
