/// <reference path="../../../events/IEventTarget.ts"/>


namespace cpr.controls.gridpart.layout {

	/**
	 * GridHeader와 GridFooter를 처리하기 위한 PassiveScrollPane
	 * 브라우저에서 실제 스크롤을 사용했을 때는 레이아웃 계산이 일어나지 않고 바로 그리기로 넘어가서 태그양이 많아도 빨리 그려지는데 반해
	 * 스타일요소(style.top)을 변경하여 가상스크롤을 구현했을 때는 브라우저에서 레이아웃을 재계산하기 때문에 태그양이 많아지면 그만큼 느려짐.
	 * 이 문제를 해결하기 위해서는 실제 스크롤을 만들어 놓고 scrollTop을 조정하는 식의 가상스크롤 적용함.
	 * @private
	 */
	export class PassiveScrollPane extends IScrollPane {
		private _scrollStrategy: PassiveScrollStrategy;


		constructor(region: string, loc: string, context: GridContext, contentView: IGridPartArea, scrollPaneCluster: ScrollPaneCluster) {
			super(region, loc, context, contentView, scrollPaneCluster);

			// header, footer ScrollStrategy
			this._scrollStrategy = new PassiveScrollStrategy(this, this.context);
		}

		public _getViewportWidth(): number {
			return this._scrollStrategy._getViewportWidth();
		}
		public _getViewportHeight(): number {
			return this._scrollStrategy._getViewportHeight();
		}

		public _getMaxScrollTop(): number {
			return this._scrollStrategy._getRenderedMaxScrollTop();
		}
		public _getMaxScrollLeft(): number {
			return this._scrollStrategy._getRenderedMaxScrollLeft();
		}

		/* createShape start */
		public _readyForRedraw(): void {
			this._scrollStrategy._readyForRedraw();
		}
		public _initScrollLeft(scrollLeft: number): void {
			this._scrollStrategy._initScrollLeft(scrollLeft);
		}

		public createShape(): ufc.ControlShape {
			let shape: ufc.ControlShape = this._scrollStrategy._createScrollPane();

			return shape;
		}
		/* createShape end */

		public _handleScrollLeft(scrollEvent: events.CScrollEvent): void {
			this._scrollStrategy._handleScrollLeft(scrollEvent);
		}
		public _handleScrollTop(scrollEvent: events.CScrollEvent): void {
			// DO Nothing
		}

		public _jumpCellIndex(cellIndex: number): void {
			this._scrollStrategy._onJumpCellIndex(cellIndex);
		}

		public _getRenderCellRange(): { start: number, end: number } {
			let wholeRenderingMode: boolean | string = this.context._getWholeRenderingMode();
			if (wholeRenderingMode !== false) {
				let cellRange: { start: number, end: number } = {
					start: 0, end: Number.MAX_VALUE
				};
				return cellRange;
			} else {
				return this._getViewCellRange();
			}

		}

		public _getViewCellRange(): { start: number, end: number } {
			let viewportWidth: number = this._getViewportWidth();
			let scrollLeft: number = this._getBusScrollLeft();
			scrollLeft = scrollLeft < 0 ? 0 : scrollLeft;

			let cellRange: { start: number, end: number } = {
				start: scrollLeft, end: scrollLeft + viewportWidth
			};
			return cellRange;
		}

		public _getVScrollbarWidth(): number {
			return this._scrollStrategy._getVScrollbarWidth();
		}

	}
}