namespace cpr.animation {
	// These values are established by empiricism with tests (tradeoff: performance VS precision)
	var NEWTON_ITERATIONS = 4;
	var NEWTON_MIN_SLOPE = 0.001;
	var SUBDIVISION_PRECISION = 0.0000001;
	var SUBDIVISION_MAX_ITERATIONS = 10;

	var kSplineTableSize = 11;
	var kSampleStepSize = 1.0 / (kSplineTableSize - 1.0);

	var float32ArraySupported = typeof Float32Array === 'function';

	function A(aA1, aA2) { return 1.0 - 3.0 * aA2 + 3.0 * aA1; }
	function B(aA1, aA2) { return 3.0 * aA2 - 6.0 * aA1; }
	function C(aA1) { return 3.0 * aA1; }

	// Returns x(t) given t, x1, and x2, or y(t) given t, y1, and y2.
	function calcBezier(aT, aA1, aA2) { return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT; }

	// Returns dx/dt given t, x1, and x2, or dy/dt given t, y1, and y2.
	function getSlope(aT, aA1, aA2) { return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1); }

	function binarySubdivide(aX, aA, aB, mX1, mX2) {
		var currentX, currentT, i = 0;
		do {
			currentT = aA + (aB - aA) / 2.0;
			currentX = calcBezier(currentT, mX1, mX2) - aX;
			if (currentX > 0.0) {
				aB = currentT;
			} else {
				aA = currentT;
			}
		} while (Math.abs(currentX) > SUBDIVISION_PRECISION && ++i < SUBDIVISION_MAX_ITERATIONS);
		return currentT;
	}

	function newtonRaphsonIterate(aX, aGuessT, mX1, mX2) {
		for (var i = 0; i < NEWTON_ITERATIONS; ++i) {
			var currentSlope = getSlope(aGuessT, mX1, mX2);
			if (currentSlope === 0.0) {
				return aGuessT;
			}
			var currentX = calcBezier(aGuessT, mX1, mX2) - aX;
			aGuessT -= currentX / currentSlope;
		}
		return aGuessT;
	}

	function LinearEasing(x) {
		return x;
	}

	function bezier(mX1, mY1, mX2, mY2) {
		if (!(0 <= mX1 && mX1 <= 1 && 0 <= mX2 && mX2 <= 1)) {
			throw new Error('bezier x values must be in [0, 1] range');
		}

		if (mX1 === mY1 && mX2 === mY2) {
			return LinearEasing;
		}

		// Precompute samples table
		var sampleValues = float32ArraySupported ? new Float32Array(kSplineTableSize) : new Array(kSplineTableSize);
		for (var i = 0; i < kSplineTableSize; ++i) {
			sampleValues[i] = calcBezier(i * kSampleStepSize, mX1, mX2);
		}

		function getTForX(aX) {
			var intervalStart = 0.0;
			var currentSample = 1;
			var lastSample = kSplineTableSize - 1;

			for (; currentSample !== lastSample && sampleValues[currentSample] <= aX; ++currentSample) {
				intervalStart += kSampleStepSize;
			}
			--currentSample;

			// Interpolate to provide an initial guess for t
			var dist = (aX - sampleValues[currentSample]) / (sampleValues[currentSample + 1] - sampleValues[currentSample]);
			var guessForT = intervalStart + dist * kSampleStepSize;

			var initialSlope = getSlope(guessForT, mX1, mX2);
			if (initialSlope >= NEWTON_MIN_SLOPE) {
				return newtonRaphsonIterate(aX, guessForT, mX1, mX2);
			} else if (initialSlope === 0.0) {
				return guessForT;
			} else {
				return binarySubdivide(aX, intervalStart, intervalStart + kSampleStepSize, mX1, mX2);
			}
		}

		return function BezierEasing(x) {
			// Because JavaScript number are imprecise, we should guarantee the extremes are right.
			if (x === 0) {
				return 0;
			}
			if (x === 1) {
				return 1;
			}
			return calcBezier(getTForX(x), mY1, mY2);
		};
	};

	/**
	 * 컨트롤의 일반 속성들을 애니메이션 처리하고자 할 때 사용되는 객체.
	 */
	export class Animator {
		private _tasks: ((time: number) => void)[] = [];
		private _matrix: number[];
		private _duration: number;
		private _startedTime: number;
		private _animationFrameId: number;
		private _timeModifier = (number) => number;
		private _promiseResolve: () => void
		private _done: boolean = false;
		private _stopRequested = false;

		/**
		 * 새로운 애니메이터를 생성합니다.
		 * @param durationInSeconds 애니메이션 길이(단위: 초)
		 * @param timingFunction 타이밍 함수
		 */
		constructor(durationInSeconds = 0.3, timingFunction: string = TimingFunction.EASE_IN_OUT) {
			this._matrix = TimingFunction.toMatrix(timingFunction);
			this._duration = durationInSeconds * 1000;
			this._timeModifier = bezier(this._matrix[0], this._matrix[1], this._matrix[2], this._matrix[3])
		}

		/**
		 * 애니메이션의 길이를 증가 시킵니다.
		 * @param timeToExtendInSeconds 증가시킬 시간(초)
		 */
		public extendDuration(timeToExtendInSeconds: number) {
			this._duration += timeToExtendInSeconds * 1000;
		}

		/**
		 * 애니메이션을 중단합니다.
		 */
		public stop() {
			this._stopRequested = true;
			if (this._animationFrameId) {
				cancelAnimationFrame(this._animationFrameId);
				delete this._animationFrameId;
			}
		}

		/**
		 * 애니메이션의 시작 여부.
		 */
		public get started() {
			return this._startedTime != null;
		}

		/**
		 * 애니메이션의 시작 시각
		 */
		public get startedTime() {
			return this._startedTime;
		}

		/**
		 * 애니메이션의 완료 여부를 얻습니다.
		 */
		public get done() {
			return this._done;
		}

		/**
		 * 각 애니메이션 프레임간에 수행할 작업을 추가합니다.
		 * @param task 작업 함수. 인자로 애니메이션의 진행정도(0에서 1사이의 값)이 전달됩니다.
		 */
		public addTask(task: (time: number) => void) {
			this._tasks.push(task)
		}

		/**
		 * 애니메이션을 시작시킵니다. 애니메이션 종료시 콜백되는 프로미스가 반환됩니다.
		 */
		public run(): Promise<void> {
			if (this._startedTime) {
				return
			}
			this._stopRequested = false;
			this._done = false;
			this._startedTime = new Date().getTime();
			this._animationFrameId = requestAnimationFrame(this._step.bind(this))
			return new Promise((resolve, reject) => {
				this._promiseResolve = resolve
			});
		}

		protected _doStep(originalProgress: number, augmentedProgress: number): void {

		}

		private _step() {
			if (this._stopRequested) {
				this._finish();
				return;
			}

			let elapsed = new Date().getTime() - this._startedTime;
			let originalProgress = elapsed / this._duration;
			let augmentedProgress = this._timeModifier(Math.min(1.0, originalProgress))
			this._doStep(originalProgress, augmentedProgress);

			this._tasks.forEach(t => {
				t(augmentedProgress)
			});

			if (originalProgress < 1) {
				this._animationFrameId = requestAnimationFrame(this._step.bind(this))
			} else {
				this._finish();
			}
		}

		private _finish() {
			if (!this._startedTime) {
				return;
			}

			delete this._animationFrameId;
			delete this._startedTime;
			this._done = true;
			this._promiseResolve()
		}
	}
}

