/*
 * CEvent.targetObject에 대한 명세 입니다.
 */

namespace cpr.events {

	/**
	   * 그리드와 연관된 이벤트가 발생 했을 때, 추가 정보를 제공합니다.
	   */
	export interface GridTargetObject {
		/** 이벤트와 연관된 그리드 로우 */
		row: controls.provider.GridRow

		/** 이벤트와 연관된 그리드 행 인덱스 */
		rowIndex: number

		/** 이벤트와 연관된 그리드 셀 인덱스 */
		cellIndex: number

		/** 이벤트와 연관된 그리드 셀에 연결된 데이터셋 컬럼명 (디테일에서만 사용가능) */
		columnName: string

		/** 
		 * 이벤트가 발생한 그리드 내의 타켓명
		 * header, detail, footer, rowgroup 중 하나 입니다.
		 */
		relativeTargetName: "header" | "detail" | "footer" | "rowgroup"

		/**
		 * 이벤트 발생 시점 기준 그리드에 표시되고 있는 순서상의 행 인덱스 값을 얻습니다.
		 */
		contentRowIndex: number
	}

	/**
	 * 트리아이템과 연관된 이벤트가 발생 했을 때, 추가 정보를 제공합니다.
	 */
	export interface TreeItemTargetObject {
		item: controls.TreeItem
	}

	/**
	 * 트리와 연관된 이벤트가 발생 했을때, 추가 정보를 제공합니다.
	 */
	export interface TreeTargetObject extends TreeItemTargetObject {
		dropPosition?: "after" | "before" | "leaf"
	}

	/**
	 * 링크드리스트박스와 연관된 이벤트가 발생 했을때, 추가 정보를 제공합니다.
	 */
	export interface LinkedListBoxTargetObject extends TreeItemTargetObject {
		dropPosition?: "after" | "before" | "leaf"
	}
	/**
	 * 아이템과 연관된 이벤트가 발생 했을 때, 추가 정보를 제공합니다.
	 */
	export interface ItemTargetObject {
		item: controls.Item
	}

	/**
	 * 리스트박스과 연관된 이벤트가 발생 했을 때, 추가 정보를 제공합니다.
	 */
	export interface ListBoxTargetObject extends ItemTargetObject {
		dropPosition?: "after" | "before" | "leaf"
	}
	/**
	 * 메뉴아이템과 연관된 이벤트가 발생 했을 때, 추가 정보를 제공합니다.
	 */
	export interface MenuItemTargetObject {
		item: controls.MenuItem
	}

	/**
	 * 파일과 관련된 이벤트가 발생 했을 때, 추가 정보를 제공합니다.
	 */
	export interface FileTargetObject {
		/**
		 * 파일 정보
		 */
		files: File[]
	}

	/**
	 * 캘린더와 연관된 이벤트가 발생 했을때, 추가 정보를 제공합니다.
	 */
	export interface CalendarTargetObject {
		/** 
		 * 이벤트가 발생한 영역 
		 * */
		relativeTargetName?: "prevYear" | "nextYear" | "prev" | "next" | "title" | "date" | "footer" | ""
	}

	/**
	 * 탭폴더와 연관된 이벤트가 발생 했을 때, 추가 정보를 제공합니다.
	 */
	export interface TabFolderTargetObject {
		/** 
		 * 이벤트와 연관된 탭 아이템 
		 * */
		item?: controls.TabItem

		/** 
		 * 이벤트가 발생한 영역 
		 * */
		relativeTargetName?: "header" | "body"
	}

	/**
	 * 그리드 cell-resized 이벤트가 발생 했을 때, 추가 정보를 제공합니다.
	 */
	export interface GridCellResizedTargetObject {

		/**
		 * 리사이즈된 cell index.
		 */
		cellIndex: number,

		/**
		 * 변경 전 셀 width.
		 */
		oldHeaderCellWidth: string,

		/**
		 * 변경 후 셀 width.
		 */
		newHeaderCellWidth: string
	}

	/**
	 * 그리드 cell-moved 이벤트가 발생 했을 때, 추가 정보를 제공합니다.
	 */
	export interface GridCellMovedTargetObject {

		/**
		 * 이동한 header cell index.
		 */
		sourceHeaderIndex: number,

		/**
		 * 이동한 영역에 위치한 header cell index.
		 */
		targetHeaderIndex: number,

		/**
		* targetHeaderCell 기준에 이전에 이동시켰는지 여부.
		*/
		before: boolean
	}


	/**
	 * 폼 레이아웃의 리사이즈 경계선에 대한 타겟 오브젝트
	 */
	export interface FormLayoutResizerTargetObject {
		/**
		 * 리사이즈 방향
		 */
		resizeDirection: "column" | "row",

		/**
		 * 리사이즈 경계 앞의 행 또는 컬럼 순서.
		 */
		divisionIndex: number
	}
}