namespace cpr.utils {
	/**
	 * Java의 HashMap과 유사한 맵 객체.
	 * 일반 JSON 객체와 달리, 키로 임의의 객체를 이용할 수 있습니다.
	 */
	export class ObjectMap<KeyType, ValueType> {
		private _keyArray: KeyType[];
		private _valueArray: ValueType[];

		/**
		 * 새로운 객체 맵을 만듭니다.
		 */
		constructor() {
			this._keyArray = [];
			this._valueArray = [];
		}

		/**
		 * 입력된 key의 인덱스를 반환합니다.
		 * @param key 
		 */
		indexOfKey(key: KeyType): number {
			return this._keyArray.indexOf(key);
		}

		/**
		 * 입력된 key를 포함하고 있는지 여부를 반환합니다.
		 * @param key 
		 */
		constainsKey(key: KeyType): boolean {
			return this._keyArray.indexOf(key) !== -1
		}

		/**
		 * 입력된 key의 value를 반환합니다.
		 * @param key 
		 */
		get(key: KeyType): ValueType {
			let index = this._keyArray.indexOf(key);
			if (index === -1) {
				return undefined;
			} else {
				return this._valueArray[index];
			}
		}

		/**
		 * 입력된 index의 key,value객체를 반환합니다.
		 * @param index 
		 */
		getEntry(index: number): { key: KeyType, value: ValueType } {
			return {
				key: this._keyArray[index],
				value: this._valueArray[index]
			};
		}

		/**
		 * key들의 배열을 반환합니다.
		 */
		keys(): KeyType[] {
			return _shallowCopyArray(this._keyArray);
		}

		/**
		 * 입력된 조건을 통해 key를 찾아 반환합니다.
		 * @param finder 
		 */
		findKey(finder: (child: KeyType) => boolean): KeyType {
			return _.find(this._keyArray, finder);
		}

		/**
		 * value들의 배열을 반환합니다.
		 */
		values(): ValueType[] {
			return _shallowCopyArray(this._valueArray);
		}

		/**
		 * 입력된 조건을 통해 value를 찾아 반환합니다.
		 * @param predicate 
		 */
		findValue(predicate: (child: ValueType) => boolean): ValueType {
			return _.find(this._valueArray, predicate);
		}

		/**
		 * key,value를 입력하여 ObjectMap에 추가합니다.
		 * @param key 
		 * @param value 
		 */
		put(key: KeyType, value: ValueType): void {
			if (value === undefined) {
				this.remove(key);
				return;
			}
			let existIndex = this._keyArray.indexOf(key);
			let targetIndex = -1;

			// 이미 존재하는 키 객체
			if (existIndex >= 0) {
				targetIndex = existIndex;
			}
			// 새로운 키 객체
			else {
				this._keyArray[this._keyArray.length] = key;
				targetIndex = this._valueArray.length;
			}

			this._valueArray[targetIndex] = value;
		}

		/**
		 * 입력된 인덱스에 key,value를 ObjectMap에 삽입합니다.
		 * @param index 
		 * @param key 
		 * @param value 
		 */
		insert(index: number, key: KeyType, value: ValueType) {
			index = Math.max(Math.min(this._keyArray.length, index), 0)
			this._keyArray.splice(index, 0, key)
			this._valueArray.splice(index, 0, value)
		}

		/**
		 * ObjectMap에 저장된 크기를 반환합니다.
		 */
		size(): number {
			return this._keyArray.length;
		}

		/**
		 * 입력된 key에 해당되는 정보를 삭제합니다.
		 * @param key 
		 */
		remove(key: KeyType): { key: KeyType, value: ValueType } {
			let index = this._keyArray.indexOf(key);
			if (index >= 0) {
				let rtnValue: { key: KeyType, value: ValueType } = {
					key: this._keyArray[index],
					value: this._valueArray[index]
				};
				this._keyArray.splice(index, 1);
				this._valueArray.splice(index, 1);
				return rtnValue;
			}
			return null;
		}

		/**
		 * 이전 key를 통해 새 key,value를 교체합니다. 편의로 교체된 key,value를 반환합니다.
		 * @param oldKey 
		 * @param newKey 
		 * @param newValue 
		 */
		replace(oldKey: KeyType, newKey: KeyType, newValue: ValueType): { key: KeyType, value: ValueType } {
			let index = this._keyArray.indexOf(oldKey);
			if (index >= 0) {
				let rtnValue: { key: KeyType, value: ValueType } = {
					key: this._keyArray[index],
					value: this._valueArray[index]
				};
				this._keyArray[index] = newKey;
				this._valueArray[index] = newValue;
				return rtnValue;
			}
			return null;
		}

		/**
		 * 모든 key,value를 삭제합니다.
		 */
		removeAll(): void {
			this._keyArray = [];
			this._valueArray = [];
		}

		/**
		 * {key,value}로 된 배열을 반환합니다.
		 */
		toArray(): { key: KeyType, value: ValueType }[] {
			let arrayData: { key: KeyType, value: ValueType }[] = [];
			this.forEach((key: KeyType, value: ValueType, index: number) => {
				arrayData[arrayData.length] = { key: key, value: value };
			});
			return arrayData;
		}

		/**
		 * ObjectMap에 대한 forEach를 실행합니다.
		 * @param func 
		 */
		forEach(func: (key: KeyType, value: ValueType, index: number) => void): void {
			let length: number = this._keyArray.length;
			for (let i: number = 0; i < length; i++) {
				func(this._keyArray[i], this._valueArray[i], i);
			}
		}

		/**
		 * 입력된 조건을 통해 Entry를 찾아 반환합니다.
		 * @private
		 * @param func 
		 */
		findEntry(func: (key: KeyType, value: ValueType, index: number) => boolean): { key: KeyType, value: ValueType } {
			let length: number = this._keyArray.length;
			for (let i: number = 0; i < length; i++) {
				if (func(this._keyArray[i], this._valueArray[i], i)) {
					return {
						key: this._keyArray[i],
						value: this._valueArray[i]
					};
				}
			}
			return null;
		}

		/**
		 * 비어있는지 여부를 반환합니다.
		 */
		isEmpty(): boolean {
			return this._keyArray.length === 0
		}
	}
}