namespace cpr.controls.internal {

	/**
	 * @private
	 */
	export class ControlScrollPane implements resources.IDisposable, IVirtualScrollPane {
		private _uicontrol: controls.UIControl;
		private _ns: string;

		private _viewWidth: number
		private _viewHeight: number;
		private _contentWidth: number;
		private _contentHeight: number;

		private _maxContentTop: number;
		private _maxContentLeft: number;

		//scrollbar
		private _reqVScroll: boolean;
		private _reqHScroll: boolean;
		private _vscrollbar: VirtualVScrollbar;
		private _hscrollbar: VirtualHScrollbar;

		private _disposed: boolean = false;

		// event handler
		private _touchStartHandler = (e: events.CTouchEvent) => this._onContentTouchStart(e);
		private _touchMoveHandler = (e: events.CTouchEvent) => this._onContentTouchMove(e);
		private _touchEndHandler = (e: events.CTouchEvent) => this._onContentTouchEnd(e);
		private _wheelHandler = (e: events.CWheelEvent) => this._onWheel(e);
		private _resizeHandler = (e: events.CWheelEvent) => this._onResize(e);
		private _scrollingHandler = (e: UIEvent) => this._onScroll(e);
		private _inputHandler = (e: events.CKeyboardEvent) => this._onInput(e);

		private _childScrollbars: ControlScrollPane[];

		constructor(uicontrol: controls.UIControl, ns: string) {
			this._uicontrol = uicontrol;
			this._ns = ns;

			this._vscrollbar = new VirtualVScrollbar(this);
			this._hscrollbar = new VirtualHScrollbar(this);
		}

		public get disposed(): boolean {
			return this._disposed;
		}

		public _isEnabled(): boolean {
			if (this._uicontrol instanceof controls.EnableUIControl) {
				return (this._uicontrol as controls.EnableUIControl).enabled;
			}
			return true;
		}
		public _getViewportWidth(): number {
			return this._viewWidth;
		}
		public _getViewportHeight(): number {
			return this._viewHeight;
		}
		public _getContentWidth(): number {
			return this._contentWidth;
		}
		public _getContentHeight(): number {
			return this._contentHeight;
		}
		public _getQName(name: string): string {
			return this._ns + "-" + name;
		}
		public _setScrollTop(e: events.CUIEvent, scrollTop: number): number {
			let containerNode: HTMLElement = this._getContainerNode();
			let currentScrollTop: number = containerNode.scrollTop;
			if (scrollTop < 0) {
				scrollTop = 0;
			} else if (scrollTop > this._getMaxContentTop()) {
				scrollTop = this._getMaxContentTop();
			}
			if (currentScrollTop == scrollTop) {
				return -1;
			}
			containerNode.scrollTop = scrollTop;
			if (containerNode.scrollTop == currentScrollTop) {

				return -1;
			}
			return containerNode.scrollTop;
		}
		public _setScrollLeft(e: events.CUIEvent, scrollLeft: number): number {
			let containerNode: HTMLElement = this._getContainerNode();
			let currentScrollLeft: number = containerNode.scrollLeft;
			if (scrollLeft < 0) {
				scrollLeft = 0;
			} else if (scrollLeft > this._getMaxContentLeft()) {
				scrollLeft = this._getMaxContentLeft();
			}
			if (currentScrollLeft == scrollLeft) {
				return -1;
			}
			containerNode.scrollLeft = scrollLeft;
			if (containerNode.scrollLeft == currentScrollLeft) {

				return -1;
			}
			return containerNode.scrollLeft;
		}

		public _getRenderer(): ufc.ControlRenderer {
			return this._uicontrol._getRenderer();
		}

		/**
		 * 컨텐츠 및 스크롤페인의 크기 변경을 체크하여 변경된 경우 스크롤바를 새로 그림.
		 */
		public _checkResize(): void {
			let container: HTMLElement = this._getContainerNode();
			let containerHeight: number = container.clientHeight;
			let containerWidth: number = container.clientWidth;
			let containerScrollHeight: number = container.scrollHeight;
			let containerScrollWidth: number = container.scrollWidth;
			if (this._viewHeight !== containerHeight
				|| this._viewWidth !== containerWidth
				|| this._contentHeight !== containerScrollHeight
				|| this._contentWidth !== containerScrollWidth) {
				this._computeScrollbar();
			}
		}

		public _setChildScrollbars(scrollbars: ControlScrollPane[]) {
			this._childScrollbars = scrollbars;
		}

		public createScrollbar(sibilings: ufc.ElementShapeContent[]
			, scrollingShape: ufc.ElementShape, idx: number, parentShape?: ufc.ElementShape): ufc.ElementShape {

			ufc.ShapeUtil.addMandatoryEventHandler(scrollingShape, "touchstart", this._touchStartHandler);
			ufc.ShapeUtil.addMandatoryEventHandler(scrollingShape, "touchmove", this._touchMoveHandler);
			ufc.ShapeUtil.addMandatoryEventHandler(scrollingShape, "touchend", this._touchEndHandler);
			ufc.ShapeUtil.addMandatoryEventHandler(scrollingShape, "resize", this._resizeHandler);
			ufc.ShapeUtil.addMandatoryEventHandler(scrollingShape, "scroll", this._scrollingHandler);
			ufc.ShapeUtil.addMandatoryEventHandler(scrollingShape, "input", this._inputHandler);
			let isDisabledPointer = scrollingShape.style["pointer-events"] == "none" && scrollingShape.attr["disabled"] != null;
			if (parentShape && isDisabledPointer) {
				ufc.ShapeUtil.addMandatoryEventHandler(parentShape, "wheel", this._wheelHandler);
			} else {
				ufc.ShapeUtil.addMandatoryEventHandler(scrollingShape, "wheel", this._wheelHandler);
			}
			scrollingShape.classNames.push("cl-customscrollbar");
			// cl-customscrollbar 클래스에서 높이와 너비를 조정하기 때문에 삭제.
			scrollingShape.style = _mergeObject(scrollingShape.style, { height: "100%", width: "100%" });

			if (this._reqVScroll || this._reqHScroll) {
				let customScrollClasses: string[] = ["cl-customscrollbar"];
				let oldContentShape = this._getRenderer()._getNamedShape(this._ns);
				if (oldContentShape != null) {
					let oldClassNames = oldContentShape.classNames;
					let autosizeType = this._uicontrol._getAutoSizingTypeOfConstraint();
					let isVerticalAutoSize = autosizeType == layouts.AutoSizeType.height || autosizeType == layouts.AutoSizeType.both;
					let isHorizontalAutoSize = autosizeType == layouts.AutoSizeType.width || autosizeType == layouts.AutoSizeType.both;

					if (oldClassNames != null && oldClassNames.length > 0) {
						if (oldClassNames.indexOf("cl-with-vscrollbar") !== -1) {
							customScrollClasses[customScrollClasses.length] = "cl-with-vscrollbar";
							if (isHorizontalAutoSize) {
								scrollingShape.style["padding-right"] = ScrollbarUtil._getCustomScrollbarInfo().vWidth + "px";
							} else {
								scrollingShape.style.width = this._createScrollPaneSizeStyle("vertical");
							}
						}
						if (oldClassNames.indexOf("cl-with-hscrollbar") !== -1) {
							customScrollClasses[customScrollClasses.length] = "cl-with-hscrollbar";
							if (isVerticalAutoSize) {
								scrollingShape.style["padding-bottom"] = ScrollbarUtil._getCustomScrollbarInfo().hHeight + "px";
							} else {
								scrollingShape.style.height = this._createScrollPaneSizeStyle("horizontal");
							}
						}
					}
				}
				scrollingShape.classNames = _.union(scrollingShape.classNames, customScrollClasses);
			}

			// 이전 Shape을 보전해야 thumb의 이동 이벤트 상태를 보전할 수 있음(IE : event.buttons ==> 0으로 설정되는 문제)
			let vScrollShape: ufc.ElementShape = this._getRenderer()._getNamedShape(this._getQName("custom-vscroll"));
			if (!vScrollShape) {
				vScrollShape = { // vertical scrollbar
					tag: "div"
					, nodename: this._getQName("custom-vscroll")
					, style: { display: "none" }
				};
			}

			let hScrollShape: ufc.ElementShape = this._getRenderer()._getNamedShape(this._getQName("custom-hscroll"));
			if (!hScrollShape) {
				hScrollShape = { // horizontal scrollbar
					tag: "div"
					, nodename: this._getQName("custom-hscroll")
					, style: { display: "none" }
				};
			}

			sibilings.splice(idx, 0, _createTapLazyTask({
				task: () => {
					this._computeScrollbar();
				}
			}),
				vScrollShape,
				hScrollShape
			);

			return scrollingShape;
		}

		private _notifyResizeToParent() {
			let parent = this._uicontrol.getParent();
			if (parent) {
				parent._applyChildSizeChanging(this._uicontrol);
			}
		}

		private _createScrollPaneSizeStyle(type: "vertical" | "horizontal") {
			switch (type) {
				case "vertical":
					return "calc( 100% - " + ScrollbarUtil._getCustomScrollbarInfo().vWidth + "px )";

				case "horizontal":
					return "calc( 100% - " + ScrollbarUtil._getCustomScrollbarInfo().hHeight + "px )";
			}
		}

		/**
		 * 스크롤을 재계산합니다.
		 */
		public _refresh(): void {
			this._computeScrollbar();
		}

		private _checkReqVscroll(viewportHeight: number, contentHeight: number) {
			return contentHeight - viewportHeight > 2
		}
		private _checkReqHScroll(viewportWidth: number, contentWidth: number) {
			return contentWidth - viewportWidth > 2;
		}
		private _computeScrollbar(): void {
			let contentNode: HTMLElement = this._getContainerNode();
			if (!contentNode) {
				return;
			}
			// 포커스 가능한 viewport인 경우(textarea) 스크롤에 마우스로 스크롤에 포커스 가능하도록 조치
			let focusableContent: boolean = contentNode.getAttribute("tabindex") != null;
			let viewWidth: number = contentNode.clientWidth;
			let viewHeight: number = contentNode.clientHeight;
			let contentWidth: number = contentNode.scrollWidth;
			let contentHeight: number = contentNode.scrollHeight;
			if (viewHeight != this._viewHeight || viewWidth != this._viewWidth) {
				this._notifyResizeToParent();
			}
			this._viewHeight = viewHeight;
			this._viewWidth = viewWidth;
			this._contentHeight = contentHeight;
			this._contentWidth = contentWidth;

			let contentScrollLeft: number = contentNode.scrollLeft;
			let contentScrollTop: number = contentNode.scrollTop;

			let reqVScroll: boolean = this._checkReqVscroll(this._viewHeight, this._contentHeight);
			let reqHScroll: boolean = this._checkReqHScroll(this._viewWidth, this._contentWidth);

			// 추가 보정
			if (reqVScroll != reqHScroll) {
				if (reqVScroll == false) {
					reqVScroll = this._checkReqVscroll(this._viewHeight, this._contentHeight);
				} else {
					reqHScroll = this._checkReqHScroll(this._viewWidth, this._contentWidth);
				}
			}
			let autosizeType = this._uicontrol._getAutoSizingTypeOfConstraint();
			let isVerticalAutoSize = autosizeType == layouts.AutoSizeType.height || autosizeType == layouts.AutoSizeType.both;
			let isHorizontalAutoSize = autosizeType == layouts.AutoSizeType.width || autosizeType == layouts.AutoSizeType.both;

			let scrollPaneClass: string[] = [];
			let scrollPaneStyle: {} = {
				height: "100%",
				width: "100%"
			};
			if (reqVScroll) {
				scrollPaneClass[scrollPaneClass.length] = "cl-with-vscrollbar";
				if (isHorizontalAutoSize) {
					scrollPaneStyle["padding-right"] = ScrollbarUtil._getCustomScrollbarInfo().vWidth + "px";
				} else {
					scrollPaneStyle["width"] = this._createScrollPaneSizeStyle("vertical");
				}
			}
			if (reqHScroll) {
				scrollPaneClass[scrollPaneClass.length] = "cl-with-hscrollbar";
				if (isVerticalAutoSize) {
					scrollPaneStyle["padding-bottom"] = ScrollbarUtil._getCustomScrollbarInfo().hHeight + "px";
				} else {
					scrollPaneStyle["height"] = this._createScrollPaneSizeStyle("horizontal");
				}
			}
			this._updateStyle(this._ns, scrollPaneStyle);
			this._updateClass(this._ns, ["cl-with-vscrollbar", "cl-with-hscrollbar"], scrollPaneClass);

			// 스타일 변경 후 높이/넓이를 새로 가져옴
			if (reqVScroll || reqHScroll) {
				this._viewWidth = contentNode.clientWidth;
				this._viewHeight = contentNode.clientHeight;
			}

			this._maxContentLeft = this._contentWidth - this._viewWidth;
			if (this._maxContentLeft < 0) {
				this._maxContentLeft = 0;
			}
			this._maxContentTop = this._contentHeight - this._viewHeight;
			if (this._maxContentTop < 0) {
				this._maxContentTop = 0;
			}

			let vscrollbarShape: ufc.ElementShape = null;
			if (reqVScroll) {
				vscrollbarShape = this._vscrollbar._createScrollbar(contentScrollTop, contentHeight);
				if (focusableContent) vscrollbarShape.attr["tabindex"] = "-1";
				if (reqHScroll) {
					vscrollbarShape.classNames = _.union([], vscrollbarShape.classNames, ["cl-with-hscrollbar"]);
				}

			} else {
				vscrollbarShape = {
					tag: "div"
					, nodename: this._getQName("custom-vscroll")
					, style: { display: "none" }
				};

			}
			this._replace("custom-vscroll", vscrollbarShape);

			let hscrollbarShape: ufc.ElementShape = null;
			if (reqHScroll) {
				hscrollbarShape = this._hscrollbar._createScrollbar(contentScrollLeft, contentWidth);
				if (focusableContent) hscrollbarShape.attr["tabindex"] = "-1";
				if (reqVScroll) {
					hscrollbarShape.classNames = _.union([], hscrollbarShape.classNames, ["cl-with-vscrollbar"]);
				}

			} else {
				hscrollbarShape = {
					tag: "div"
					, nodename: this._getQName("custom-hscroll")
					, style: { display: "none" }
				};

			}
			this._replace("custom-hscroll", hscrollbarShape);
			// 컨트롤 내부에 커스텀스크롤들이 자식으로 있는 경우 높이나 너비가 달라지면 갱신이 필요하다.
			if (this._reqHScroll != reqHScroll || this._reqVScroll != reqVScroll) {
				if (this._childScrollbars) {
					this._childScrollbars.forEach((scrollPane: ControlScrollPane) => {
						scrollPane._refresh();
					});
				}
			}

			this._reqVScroll = reqVScroll;
			this._reqHScroll = reqHScroll;
		}

		// event handlers
		_onMousedownScroll(e: events.CMouseEvent): void {
			let contentNode = this._getContainerNode();
			let focusableContent = contentNode.getAttribute("tabindex") != null;
			let isIE = _detectBrowser().name == "ie";
			if (!focusableContent && !isIE) {
				return;
			}
			let rootNode = this._uicontrol._getRenderer().getRootNode();
			let domTraverser = ufc._traverseFromElement(contentNode.parentElement);
			domTraverser = domTraverser._closest('[tabindex]', rootNode);
			let focusable = domTraverser != null;
			if (focusable) {
				e.preventDefault();
				cpr.core.DeferredUpdateManager.INSTANCE._performFocusTask(() => {
					if (this.disposed) {
						return;
					}
					domTraverser._focus({ preventScroll: true }).dispose();
				})
			}
		}
		/**
		 * 키 입력했을때 텍스트 길이로 스크롤이 변경되돋록 한다.
		 * @param e 
		 */
		private _onInput(e: events.CKeyboardEvent) {
			this._checkResize();
		}

		/**
		 * 방향키 또는 페이지 키를 눌렀을때 스크롤이 되도록 한다.
		 * @param e 
		 */
		private _onScroll(e: UIEvent): void {
			let contentNode = this._getContainerNode();
			this._checkResize();
			if (this._vscrollbar) {
				this._vscrollbar._setScrollTop(contentNode.scrollTop);
			}
			if (this._hscrollbar) {
				this._hscrollbar._setScrollLeft(contentNode.scrollLeft);
			}
		}
		private _onWheel(e: events.CWheelEvent): void { // wheel은 가로/세로 같이 사용
			this._checkResize();
			let delta: { x: number, y: number } = ScrollbarUtil._getScrollPaneWheelDelta(e);
			if (delta == null) {
				return;
			}
			// 델타를 그대로 사용하되, 뷰포트를 넘지 않도록 상한을 둔다.
			let moved: boolean = false;
			if (e.shiftKey) {
				if (this._hscrollbar) {
					moved = this._setHScrollbarLeftOffset(e, ScrollbarUtil._toWheelOffset(delta.x, this._getViewportWidth()));
				}
			} else {
				if (this._hscrollbar && delta.x != 0) {
					moved = this._setHScrollbarLeftOffset(e, ScrollbarUtil._toWheelOffset(delta.x, this._getViewportWidth()));
				}
				if (this._vscrollbar && delta.y != 0) {
					moved = this._setVScrollbarTopOffset(e, ScrollbarUtil._toWheelOffset(delta.y, this._getViewportHeight())) || moved;
				}
			}
			if (moved) {
				e.stopPropagation();
				e.preventDefault();
			}
		}

		private _touchRoller: internal.TouchRoller = internal.newTouchRoller();

		private _onContentTouchStart(e: events.CTouchEvent): void {
			this._touchRoller._touchStart(e,
				this._maxContentTop > 0 ? this._vscrollbar._getScrollTop() : -1,
				this._maxContentLeft > 0 ? this._hscrollbar._getScrollLeft() : -1
			);
		}

		private _onContentTouchMove(e: events.CTouchEvent): void {
			this._touchRoller._touchMove(e, (scrollTop: number, scrollLeft: number): boolean => {
				let movedY: boolean = scrollTop !== -1 ? this._setVScrollbarTop(e, scrollTop) : false;
				let movedX: boolean = scrollLeft !== -1 ? this._setHScrollbarLeft(e, scrollLeft) : false;

				return movedX || movedY;
			});
		}

		private _onContentTouchEnd(e: events.CTouchEvent): void {
			this._touchRoller._touchEnd(e,
				this._maxContentTop > 0 ? this._vscrollbar._getScrollTop() : -1,
				this._maxContentLeft > 0 ? this._hscrollbar._getScrollLeft() : -1,
				(scrollTop: number, scrollLeft: number): boolean => {
					let movedY: boolean = scrollTop !== -1 ? this._setVScrollbarTop(e, scrollTop) : false;
					let movedX: boolean = scrollLeft !== -1 ? this._setHScrollbarLeft(e, scrollLeft) : false;

					return movedX || movedY;
				}
			);
		}

		private _onResize(e: events.CUIEvent): void {
			this._computeScrollbar();
		}

		// helper methods
		private _setVScrollbarTopOffset(e: events.CUIEvent, offset: number): boolean {
			let containerNode: HTMLElement = this._getContainerNode();
			let scrollTop: number = containerNode.scrollTop;
			scrollTop += offset;
			return this._setVScrollbarTop(e, scrollTop);
		}

		private _setVScrollbarTop(e: events.CUIEvent, scrollTop: number): boolean {
			let movedScrollTop: number = this._setScrollTop(e, scrollTop);
			if (movedScrollTop == -1) {
				return false;
			}
			this._vscrollbar._setScrollTop(movedScrollTop);
			return true;
		}

		private _setHScrollbarLeftOffset(e: events.CUIEvent, offset: number): boolean {
			let containerNode: HTMLElement = this._getContainerNode();
			let scrollLeft: number = containerNode.scrollLeft;
			scrollLeft += offset;
			return this._setHScrollbarLeft(e, scrollLeft);
		}

		private _setHScrollbarLeft(e: events.CUIEvent, scrollLeft: number) {
			let movedScrollLeft: number = this._setScrollLeft(e, scrollLeft);
			if (movedScrollLeft == -1) {
				return false;
			}
			this._hscrollbar._setScrollLeft(movedScrollLeft);
			return true;
		}

		private _getContainerNode(): HTMLElement {
			return this._getRenderer().getNamedNode(this._ns);
		}
		private _getMaxContentTop(): number {
			return this._maxContentTop;
		}
		private _getMaxContentLeft(): number {
			return this._maxContentLeft;
		}
		private _replace(name: string, newShape: ufc.ElementShape): void {
			this._getRenderer().replace(this._getQName(name), newShape);
		}
		private _updateClass(name: string, removeClasses: string[], addClasses: string[]): void {
			this._getRenderer().updateClass(name, removeClasses, addClasses);
		}
		private _updateStyle(name: string, style: { [key: string]: string }) {
			this._getRenderer().updateStyle(name, style, true);
		}

		public dispose() {
			this._uicontrol = null;
			this._vscrollbar = null;
			this._hscrollbar = null;
			this._childScrollbars = null;
			this._disposed = true;

		}
	}
}