		/**
		 * 특정 Row의 상태를 반환합니다.
		 * @return 특정 Row의 상태.<br>
		 * state 종류:<br>
		 * cpr.data.tabledata.RowState.UNCHANGED : 변경되지 않은 상태.<br>
		 * cpr.data.tabledata.RowState.INSERTED : 행이 신규로 추가된 상태.<br>
		 * cpr.data.tabledata.RowState.UPDATED : 행이 수정된 상태.<br>
		 * cpr.data.tabledata.RowState.DELETED : 행이 삭제된 상태.<br>
		 * cpr.data.tabledata.RowState.INSERTDELETED : 행이 추가되었다가 삭제된 상태.
		 */
		public getRowState(index: number): data.tabledata.RowState {
			let gridRow: GridRow = this.getRow(index);
			return (gridRow != null) ? gridRow.getState() : null;
		}

		/**
		 * @private
		 */
		public _clearState(state: data.tabledata.RowState = data.tabledata.RowState.ALL): void {
			let rowIndexObj: { [state: number]: number[] } = this._dataControl.getRowIndicesByState(state);
			let states: string[] = Object.keys(rowIndexObj);
			let rowIndices: number[];
			for (let i = 0; i < states.length; i++) {
				rowIndices = rowIndexObj[states[i]];
				for (let j = 0; j < rowIndices.length; j++) {
					this._setRowState(rowIndices[j], data.tabledata.RowState.UNCHANGED);
				}
			}
		}

