		public _findData(condition: string): GridRow {
			let rowCount: number = this.getRowCount();
			let row: data.IDataRow = this._dataControl.findFirstRow(condition, 0, rowCount - 1);

			return row == null ? null : new GridRow(this._context.getGrid(), row);
		}

		/**
		 * @private
		 */
		public _findDatas(condition: string): GridRow[] {
			let result: GridRow[] = [];
			let rowCount: number = this.getRowCount();
			let rows: data.IDataRow[] = this._dataControl.findAllRow(condition, 0, rowCount - 1);
			if (rows instanceof Array) {
				rows.forEach((row: data.Row) => {
					result[result.length] = new GridRow(this._context.getGrid(), row);
				});
			}
			return result;
		}

