		/**
		 * 데이터셋 변경 유무를 반환합니다.<br>
		 * (inserted, deleted, updated 상태인 row가 있는지 유무)
		 * @return 변경 유무.
		 */
		public isModified(state: data.tabledata.RowState = data.tabledata.RowState.ALL): boolean {
			let result: boolean = false;
			let rowCountObj: { [state: number]: number } = this._dataControl.getRowCountByState(state);
			let states: string[] = Object.keys(rowCountObj);
			let rowCount: number;
			for (let i = 0; i < states.length; i++) {
				rowCount = rowCountObj[states[i]];
				if (rowCount > 0) {
					result = true;
					break;
				}
			}
			return result;
		}

