		/**
		 * @private
		 */
		public _setSelection(selectionUnit: string, selection: number[] | controls.gridpart.selection.CellPosition[]): void {
			// @experimental RELATED DataWindow
			if (this._isWholeDataAccessable() == false) {
				return;
			}

			if (selection == null || (selection != null && selection.length == 0)) {
				return;
			}
			if (selectionUnit == "row") {
				// row selection
				selection = selection as number[];
				let length: number = selection.length;
				for (let i = 0; i < length; i++) {
					this._dataControl._setCtrlAttr(this._context.getGrid(), selection[i], GridCtrlAttribute.GRID_SELECTION, true);
				}
			} else {
				// cell selection
				selection = selection as controls.gridpart.selection.CellPosition[];
				let length: number = selection.length;
				let selectionCellIndex: number;
				let selectionCellIndices: number[];
				for (let i = 0; i < length; i++) {
					this._dataControl._setCtrlAttr(this._context.getGrid(), selection[i].rowIndex, GridCtrlAttribute.GRID_SELECTION, true);

					selectionCellIndex = selection[i].cellIndex;
					selectionCellIndices = this._dataControl._getCtrlAttr(this._context.getGrid(), selection[i].rowIndex, GridCtrlAttribute.GRID_SELECTIONCELLINDICES);
					if (selectionCellIndices != null && selectionCellIndices.length > 0) {
						selectionCellIndices.push(selectionCellIndex);
					} else {
						selectionCellIndices = [selectionCellIndex];
					}
					this._dataControl._setCtrlAttr(this._context.getGrid(), selection[i].rowIndex, GridCtrlAttribute.GRID_SELECTIONCELLINDICES, selectionCellIndices);
				}
			}

		}

