		/**
		 * @private
		 * @param name 
		 * @param oldValue 
		 * @param newValue 
		 */
		_valueDidChange(name: string, oldValue: any, newValue: any, context?: any) {
			// 바인딩 가능한 앱 프로퍼티가 변경된 경우, 앱 프로퍼티 체인지 이벤트 발송
			if (this._appProperties._isBindable(name)) {
				let fireEvent = true;
				let appPropSettingCtx = context as AppPropertySetContext;
				if (appPropSettingCtx?.shouldFireEvent != null) {
					fireEvent = appPropSettingCtx.shouldFireEvent;
				}
				if (fireEvent) {
					this._fireAppPropertyChangeEvent(name, oldValue, newValue);
				}
			}
		}

