namespace cpr.core {
	let log = utils.Logger.forTopic("nc")._createBindedLoggerFunction({
		updator: it => log = it
	});

	const NULL_TARGET = new Object();

	let instance: NotificationCenter;
	class Observer {
		private _topic: string;
		private _target: any;
		private _fn: Function;
		private _expectedSender: any;
		private _disposed: boolean = false;

		constructor(topic: string, expectedSender: Object, target: Object, fn: Function) {
			this._topic = topic;
			this._expectedSender = expectedSender;
			this._target = target;
			this._fn = fn;
		}

		get topic(): string { return this._topic; }
		get target(): object { return this._target; }
		get disposed(): boolean { return this._disposed; }

		invokeIfNeeded(payload: any, sender: any) {
			if (this._disposed) {
				return;
			}

			if (this._expectedSender && this._expectedSender !== sender) {
				return;
			}

			if (typeof this._fn == 'function') {
				this._fn.call(
					this._target === NULL_TARGET
						? null
						: this._target,
					payload,
					sender
				);
			}
		}

		dispose(): boolean {
			if (this._disposed) {
				return false;
			}
			this._disposed = true;
			return true;
		}
	}

	/**
	 * eXBuilder6 플랫폼이 사용하는 NotificationCenter topic입니다.
	 * @noinstance
	 */
	export class SystemTopics {
		/**
		 * 리사이즈.
		 */
		public static RESIZE = "resize";

		/**
		 * 스크롤
		 */
		public static SCROLL = "scroll";

		/**
		 * 안드로이드에서 키보드 열릴 때
		 */
		public static KEYBOARD_OPEN = "keyboard-open";

		/**
		 * 안드로이드에서 키보드 닫힐 때
		 */
		public static KEYBOARD_CLOSE = "keyboard-close";

		/**
		 * 입양
		 */
		public static ADAPT = "adapt";

		/**
		 * 고아
		 */
		public static ORPHAN = "orphan";

		/**
		 * 활성 언어 변경
		 */
		public static LANGUAGE_DID_CHANGE = "language-did-change";

		/**
		 * 활성 지역 변경
		 */
		public static LOCALE_DID_CHANGE = "locale-did-change";
	}

	/**
	 * 글로벌 메시지 큐. Observer를 사용 할 수 있습니다.
	 * @noinstance
	 */
	export class NotificationCenter {
		static get INSTANCE() {
			if (!instance) {
				instance = new NotificationCenter();
			}
			return instance;
		}

		private _observersByTopic: CMap<string, Observer[]> = _createMap();
		private _observersByTarget: CMap<Object, Observer[]> = _createMap();

		private _flushObserversTimeoutId = -1;
		/**
		 * 메시지를 발송합니다.
		 * <pre><code>
		 * cpr.core.NotificationCenter.INSTANCE.post("button-click", {text:"test1"});
		 * </code></pre>
		 * @param topic 주제. subscribe된 topic를 설정해야합니다.
		 * @param payload 메시지 내용. scbscribe의 콜백 함수에서 파라미터로 전달됩니다.
		 * @param sender 메시지 발송자. subscribe에서 expectedSender를 구분하기 위한 값.
		 */
		post(topic: string, payload: any, sender?: any) {
			this._observersByTopic?.get(topic)?.forEach(eachObserver => {
				utils.tryCatch({
					do() {
						eachObserver.invokeIfNeeded(payload, sender);
					},
					_report: true,
					_context: exceptions.ErrorContext.NOTIFICATION_SUBSCRIBER
				});
			});
		}

		/**
		 * 메시지를 구독합니다. 구독이 중복되지 않게 유의하시기 바랍니다.
		 * 동일한 주제에 대해 동일한 타겟이 새로운 구독함수를 등록하는 경우 이전 구독은 해제 됩니다.
		 * <pre><code>
		 * cpr.core.NotificationCenter.INSTANCE.subscribe("button-click", app, function(data){
		 * console.log(this);
		 * console.log(msg);
		 * console.log("click button",data); 
		 * });
		 * </code></pre>
		 * @param topic 구독 주제.
		 * @param target 구독 객체. 이 객체는 구독을 해제하는 식별 객체로도 사용되며, 메시지를 수신할 때 this 문맥으로도 사용됩니다.
		 * @param fn 메시지를 수신할 함수. 콜백함수에서 파라미터로 payload되는 값을 전달 받습니다.
		 * @param expectedSender 특정 발송자의 메시지만 수신하기 위한 객체의 레퍼런스. <code>null</code>인 경우, 모든 발송자에 대해 수신합니다.
		 */
		subscribe(topic: string, target: Object, fn: Function, expectedSender?: any) {
			target ??= NULL_TARGET;

			this.unsubscribe(target, topic); /* 기등록된 subscribe 해제 */

			let newObserver = new Observer(topic, expectedSender, target, fn);

			CMap._ensureValue(this._observersByTopic, topic, () => [])
				.push(newObserver);

			CMap._ensureValue(this._observersByTarget, target, () => [])
				.push(newObserver);
		}

		/**
		 * 모든 주제에 대해 구독을 중단합니다.
		 * @param target 구독을 중단할 구독 객체.
		 */
		unsubcribeAllTopic(target: Object) {
			target ??= NULL_TARGET;

			let observers = this._observersByTarget.get(target);
			if (utils.Util.isNullOrEmpty(observers)) {
				return;
			}

			observers.forEach(it => it.dispose());
			this._observersByTarget.delete(target);

			this._scheduleFlushingObserversByTopic();
		}

		/**
		 * 특정 주제에 대해 구독을 중단합니다.
		 * <pre><code>
		 * cpr.core.NotificationCenter.INSTANCE.unsubscribe(app, "button-click");
		 * </code></pre>
		 * @param target 구독을 중지할 객체.
		 * @param topic 구독을 중단할 주제.
		 */
		unsubscribe(target: Object, topic: string) {
			target ??= NULL_TARGET;

			let observers = this._observersByTarget.get(target);
			if (!observers) {
				return;
			}

			let changed = false;
			let newObservers = observers.filter(eachObserver => {
				if (eachObserver.topic == topic) {
					changed = true;
					eachObserver.dispose();
					return false;
				}
				else {
					return true;
				}
			});

			if (!changed) {
				return;
			}

			if (utils.Util.isNullOrEmpty(newObservers)) {
				this._observersByTarget.delete(target);
			}
			else {
				this._observersByTarget.set(target, newObservers);
			}

			this._scheduleFlushingObserversByTopic();
		}

		/**
		 * 주제별 구독 목록에서 만료된 구독 객체들을 제거합니다.
		 */
		private _flushObserversByTopic() {
			log("만료된 구독 정보를 정리합니다.");
			this._observersByTopic.forEach((observers, topic) => {
				let count = 0;
				let changed = false;
				observers = observers.filter(it => {
					if (it.disposed) {
						changed = true;
						count++;
						return false;
					} else {
						return true;
					}
				});

				if (changed) {
					if (utils.Util.isNullOrEmpty(observers)) {
						delete this._observersByTopic[topic];
					}
					else {
						this, this._observersByTopic.set(topic, observers);
					}
					log(`${topic} 주제에 ${count}개의 구독 객체가 정리되었습니다.`);
				}
			});
		}

		/**
		 * 만료된 구독 객체들을 정리하는 작업을 예약합니다.
		 * 이미 예약된 경우 무시 됩니다.
		 */
		private _scheduleFlushingObserversByTopic() {
			if (this._flushObserversTimeoutId !== -1) {
				return;
			}
			log("만료된 구독 정리 작업이 예약되었습니다.");
			this._flushObserversTimeoutId = setTimeout(() => {
				this._flushObserversTimeoutId = -1;
				this._flushObserversByTopic();
			});
		}
	}
}