namespace cpr.protocols.response {
	/**
	 * @private
	 * Todo:
	 * 파일 용량이 작을 경우 사용.
	 * 용량이 큰 경우는 form + iframe을 이용한 다운로드로 처리해야 함.
	 */
	export class FileDownloadParser extends AbstractResponseParser<AbstractSubmission> {

		constructor() {
			super();
		}

		public override load(submission: AbstractSubmission, xhr: XMLHttpRequest): void {
			if (submission instanceof Submission == false && submission instanceof MatrixSubmission == false) {
				throw new exceptions.IllegalArgumentException("submission must be Submission or MatrixSubmission");
			}
			this._loadSpecific(submission, xhr);
		}

		public override parse(submission: AbstractSubmission, xhr: XMLHttpRequest, doneHandler: () => void): void {
			if (submission instanceof Submission == false && submission instanceof MatrixSubmission == false) {
				throw new exceptions.IllegalArgumentException("submission must be Submission or MatrixSubmission");
			}
			this._parseSpecific(submission, xhr, doneHandler);
		}

		public _parseData(submission: AbstractSubmission, data: {} | string, doneHandler: () => void): void {
			throw new exceptions.UnsupportedOperationException("parseData");
		}

		public _loadSpecific(submission: AbstractSubmission, xhr: XMLHttpRequest): void {
			// do nothing
		}

		public _abortLoading(submission: AbstractSubmission): void {
			// do nothing
		}

		public _parseSpecific(submission: AbstractSubmission, xhr: XMLHttpRequest, doneHandler: () => void): void {
			let filename: string = null;
			let disposition: string = xhr.getResponseHeader('Content-Disposition');
			if (disposition && disposition.indexOf('attachment') !== -1) {
				let filenameRegex: RegExp = /filename[^;=\n]*=((['"]).*?\2|[^;\n]*)/;
				let matches: RegExpExecArray = filenameRegex.exec(disposition);
				if (matches != null && matches[1]) {
					filename = matches[1].replace(/['"]/g, '');
				}
			}
			let type: string = xhr.getResponseHeader('Content-Type');
			let blob: Blob = null;
			if (xhr.responseType == "blob") {
				blob = xhr.response as Blob;
			} else if (xhr.responseType == "arraybuffer") {
				blob = new Blob([xhr.response], { type: type });
			} else {
				// not acceptable
				blob = new Blob([xhr.response], { type: type });
			}

			let browserInfo: utils.BrowserInfo = core.Platform.INSTANCE.browserInfo;

			window.navigator["saveBlob"] = window.navigator["saveBlob"] || window.navigator["msSaveBlob"] || window.navigator["mozSaveBlob"] || window.navigator["webkitSaveBlob"];
			window["saveAs"] = window["saveAs"] || window["webkitSaveAs"] || window["mozSaveAs"] || window["msSaveAs"];

			if (browserInfo.mobile == false && window.navigator["saveBlob"]) {
				// IE workaround for "HTML7007: One or more blob URLs were revoked by closing the blob for which they were created.
				// These URLs will no longer resolve as the data backing the URL has been freed."
				window.navigator["saveBlob"](blob, decodeURIComponent(filename));
			} else if (browserInfo.mobile == false && window["saveAs"]) {
				window["saveAs"](blob, decodeURIComponent(filename));
			} else {
				let url: {
					new(url: string, base?: string): URL;
					prototype: URL;
					createObjectURL(object: any): string;
					revokeObjectURL(url: string): void;
				} = window.URL || window["webkitURL"] || window["mozURL"] || window["msURL"];

				let downloadUrl: string = url.createObjectURL(blob);

				// use HTML5 a[download] attribute to specify filename
				let anchor: HTMLAnchorElement = document.createElement("a");

				// safari doesn't support this yet
				if (typeof anchor.download !== 'undefined' || browserInfo.mobile == false) {
					let anchorId: string = _generateUUID();

					if (typeof anchor.download !== 'undefined') {
						anchor.download = decodeURIComponent(filename);
					} else {
						anchor.target = "_blank";
					}
					anchor.id = anchorId;
					anchor.style.display = "none";
					anchor.href = downloadUrl;

					document.body.appendChild(anchor);
					anchor.click();

					window.setTimeout(() => {
						url.revokeObjectURL(downloadUrl);
						anchor = document.getElementById(anchorId) as HTMLAnchorElement;
						document.body.removeChild(anchor);
					}, 100); // cleanup
				} else {
					// ios safari bug "webkitblobresource error 1"
					anchor = null;
					window.open(downloadUrl, "_blank");

					window.setTimeout(() => {
						url.revokeObjectURL(downloadUrl);
					}, 100); // cleanup

				}
			}

			doneHandler();
		}

	}

}