/// <reference path="AbstractVerticalMenu.ts"/>

namespace cpr.controls.menu {

	/**
	 * @private
	 */
	export class NormalMenu extends AbstractVerticalMenu {
		public direction: MenuDirectionType = MenuDirectionType.ltr;

		constructor(uicontrol: MenuOwner, ns: string, binder: provider.MenuDataBinder, stylerName: { list: string, item: string }) {
			super(uicontrol, ns, binder, stylerName);
		}

		private _createMenu(): cpr.ufc.ControlShape {
			let items = this.getItems();
			let selectedValues: string[] = this._getSelectedValues();
			let width = this._getMenuMinWidth();
			let itemCount = items.length;

			let range = this._getMenuItemRange(itemCount);
			let rangeSize = range.end - range.start;
			items = items.slice(range.start, range.end);
			let visibleButton: boolean = itemCount != rangeSize;

			let upScrollBtn: ufc.ControlShape = {
				tag: "div",
				classNames: ["cl-arrow-up"],
				style: {
					display: visibleButton ? "block" : "none",
					height: this._getButtonHeight() + "px"
				}
			}
			let isFirst = range.start == 0;
			if (visibleButton && isFirst) {
				upScrollBtn.classNames.push(ufc.Classes.DISABLED);
			}

			let downScrollBtn: ufc.ControlShape = {
				tag: "div",
				classNames: ["cl-arrow-down"],
				style: {
					display: visibleButton ? "block" : "none",
					height: this._getButtonHeight() + "px"
				}
			}

			let isLast = range.end == itemCount;
			if (visibleButton && isLast) {
				downScrollBtn.classNames.push(ufc.Classes.DISABLED);
			}

			let children = this._createItems(items, selectedValues);
			children.splice(0, 0, upScrollBtn);
			children.push(downScrollBtn);

			let shape: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: ["cl-sub"],
				attr: {},
				styler: this._getStylerName("list"),
				style: {
					display: "block",
					"min-width": width ? width + "px" : "auto"
				},
				events: {},
				nodename: this._getMenuListNodeName(),
				children: children
			}

			ufc.ShapeUtil.addEventHandler(shape, "touchstart", (e: events.CTouchEvent) => this._ontouchstart(e), true);
			ufc.ShapeUtil.addEventHandler(shape, "wheel", (e: events.CWheelEvent) => this._onMenuMouseWheel(e), true);

			ufc.ShapeUtil.addEventHandler(shape, "click", (e: MouseEvent) => this._onClick(e), true);

			if (this._isHoverTrigger()) {
				ufc.ShapeUtil.addEventHandler(shape, "mouseover", (e: MouseEvent) => this._dispatchHoverRelativeEvent(e), true);
				ufc.ShapeUtil.addEventHandler(shape, "mouseleave", (e: MouseEvent) => this._dispatchHoverRelativeEvent(e), true);
				ufc.ShapeUtil.addEventHandler(shape, "mouseenter", (e: MouseEvent) => this._dispatchHoverRelativeEvent(e), true);
			}

			return shape;
		}

		protected _createShape(): cpr.ufc.ControlShape {
			let shape = this._createMenu();
			shape.children.push(_createTapLazyTask({
				task: () => {
					this._updateBounds();
				}
			}));
			return shape;
		}

		private _createItems(items: MenuItem[], selectedValues: string[]): cpr.ufc.ControlShape[] {
			let itemShapes: cpr.ufc.ControlShape[] = [];
			let lastIdx = items.length - 1;
			items.forEach((item: MenuItem, index) => {

				let isDisabledItem = this._getDataBinder().getItemEnable(item) == false;
				let isSelectedItem = selectedValues.indexOf(item.value) > -1;
				let isHoveredItem = this._isHoveredItem(item);
				let displayLabel = this._getDataBinder()._computeItemDisplayLabel(item);
				let hasChild = item._hasChild();

				let icon = this._createIcon(item);
				let textShape = this._createText(displayLabel);
				let accesskeyTag = item.accessKey ? this._createAccessKey(item) : null;
				let arrow = this._createArrowImage(item);

				let itemShape: cpr.ufc.ControlShape = {
					tag: "div",
					styler: this._getStylerName("item"),
					// stylerBindContext: item.toExpressionContext(this._getUIControl()),
					bindContext: item.toExpressionContext(this._getUIControl()),
					style: {
						display: "table",
						position: "relative",
						width: "100%",
						"table-layout": "auto"
					},
					classNames: [hasChild ? ufc.Classes.FOLDER : ufc.Classes.LEAF],
					attr: {
						"data-itemid": item.value,
						"data-role": "menuitem",
						role: "menuitemradio",
						"aria-label": cpr.ufc.ShapeUtil._getValidAriaLabelAttr(ufc.StyledString._asString(displayLabel)),
						"aria-checked": "false",
						id: this._getMenuItemId(item)
					},
					events: {},
					children: [icon, textShape, accesskeyTag, arrow]
				}
				cpr.ufc.ShapeUtil._setTooltipAttr(itemShape, { owner: this._getUIControl(), title: item.tooltip, id: item.value });
				if (item.accessKey) {
					itemShape.attr["aria-keyshortcuts"] = item.accessKey;
				}
				if (isSelectedItem) {
					itemShape.classNames.push(ufc.Classes.SELECTED);
					itemShape.attr["aria-checked"] = "true";
				}
				ufc.ShapeUtil._setAriaDisabled(itemShape, !isDisabledItem && this._isEnabled() && !this._getUIControl().readOnly);
				if (isDisabledItem || !this._isEnabled()) {
					itemShape.classNames.push(ufc.Classes.DISABLED);
				} else {
					if (isHoveredItem) {
						itemShape.classNames.push(ufc.Classes.HOVER);
					}

					if (hasChild) {
						itemShape.attr['aria-haspopup'] = "true";

						if (isHoveredItem && item.expanded) {
							itemShape.classNames.push(this._getQClass("visible"));
							let menuShape: ufc.ControlShape = {
								tag: "div",
								classNames: [this._getQClass("list-wrapper")],
								attr: {},
								style: {
									width: "0px",
									display: "table-cell"
								},
								children: [this._createSubMenu(item, selectedValues)]
							}
							itemShape.children.push(menuShape);
						}
					}

				}
				if (index == 0) {
					itemShape.classNames.push(ufc.Classes.FIRST);
				}
				if (lastIdx == index) {
					itemShape.classNames.push(ufc.Classes.LAST);
				}
				itemShapes.push(itemShape);
			});

			return itemShapes;
		}

		protected _createSubItems(children: MenuItem[], selectedValues: string[]): cpr.ufc.ControlShape[] {
			let itemShapes: cpr.ufc.ControlShape[] = [];
			let lastIdx = children.length - 1;
			children.forEach((item: MenuItem, index) => {
				let isItemEnabled = this._getDataBinder().getItemEnable(item);
				let isSelectedItem = selectedValues.indexOf(item.value) > -1;
				let isHoveredItem = this._isHoveredItem(item);
				let displayLabel = this._getDataBinder()._computeItemDisplayLabel(item);
				let hasChild = item._hasChild();
				let children: ufc.ControlShape[] = [];

				let iconShape = this._createIcon(item, true);
				children.push(iconShape);

				let textShape = this._createText(displayLabel);
				children.push(textShape);

				if (item.accessKey) {
					let accesskeyShape = this._createAccessKey(item, true);
					children.push(accesskeyShape);
				}

				let arrowShape = this._createArrowImage(item, true);
				children.push(arrowShape);

				let itemShape: cpr.ufc.ControlShape = {
					tag: "div",
					styler: this._getStylerName("item"),
					style: {
						display: "table",
						position: "relative",
						width: "100%"
					},
					classNames: [hasChild ? ufc.Classes.FOLDER : ufc.Classes.LEAF],
					bindContext: item.toExpressionContext(this._getUIControl()),
					attr: {
						"data-role": "menuitem",
						role: "menuitemradio",
						"data-itemid": item.value,
						"aria-label": cpr.ufc.ShapeUtil._getValidAriaLabelAttr(ufc.StyledString._asString(displayLabel)),
						"aria-checked": "false",
						id: this._getMenuItemId(item)
					},
					events: {},
					children: children
				}

				cpr.ufc.ShapeUtil._setTooltipAttr(itemShape, { owner: this._getUIControl(), title: item.tooltip, id: item.value });
				ufc.ShapeUtil._setAriaDisabled(itemShape, isItemEnabled && this._isEnabled() && !this._getUIControl().readOnly);

				if (item.accessKey) {
					itemShape.attr["aria-keyshortcuts"] = item.accessKey;
				}
				if (hasChild) {
					itemShape.attr['aria-haspopup'] = "true";
					itemShape.attr["aria-expanded"] = "false";

					if (isHoveredItem && item.expanded) {
						//value와 parentValue가 같으면 재귀 반복되는 오류 발생
						itemShape.children.push(this._createSubMenu(item, selectedValues));
					}
				}
				if (isSelectedItem) {
					itemShape.attr['aria-checked'] = "true";
					itemShape.classNames.push(ufc.Classes.SELECTED);
				}

				if (isItemEnabled && this._isEnabled()) {
					if (isHoveredItem) {
						itemShape.classNames.push(ufc.Classes.HOVER);
					}
					if (isHoveredItem && hasChild) {
						itemShape.attr["aria-expanded"] = "true";
						itemShape.classNames.push(this._getQClass("visible"));
					}
				} else {
					itemShape.classNames.push(ufc.Classes.DISABLED);
				}
				if (index == 0) {
					itemShape.classNames.push(ufc.Classes.FIRST);
				}
				if (lastIdx == index) {
					itemShape.classNames.push(ufc.Classes.LAST);
				}
				itemShapes.push(itemShape);
			})

			return itemShapes;
		}

		override _transferHoverDownCycle(item: MenuItem) {
			let traversedHover = null;
			if (item._hasChild()) {
				let children = this._getDataBinder().getChildren(item);
				let idx = 0;
				traversedHover = children[idx];

				if (!this._getDataBinder().getItemEnable(traversedHover)) {
					let traverseIndex = this._traverseItemIndex(true, idx, children, idx);
					if (traverseIndex == idx) {
						traversedHover = null;
					} else {
						traversedHover = children[traverseIndex];
					}
				}
				if (!item.expanded) {
					item._setOpen(true);
					this._getUIControl().redraw();
				}
				if (traversedHover) {
					this.setHoveredItem(traversedHover, { updateScroll: true, expand: this._getSelectionTargetType() == MenuSelectionTargetType.all });
				}
			}
			return traversedHover;
		}

		private _getHoveredBarItemNode() {
			let hoveredBarNode = this._getRenderer().getNamedNode("hovered-bar-item");
			return hoveredBarNode;
		}

		protected _updateMenuBounds() {
			let rootNode = this._getRenderer().getNamedNode(this._getQName());
			let rootMenuNode = this._getRenderer().getNamedNode(this.getRootNodeName());
			if (!rootMenuNode || !rootNode) {
				return;
			}
			let hoveredItemNode = this._getHoveredBarItemNode();
			if (!hoveredItemNode) {
				return;
			}
			let rootMenuRect = _getUnscaledClientRect(rootMenuNode);
			let rootSpace = _getComputedSpaceInsets(rootNode, { horizontalMeasurePosition: "reverseBoth", leftOverflow: "altViewport" });
			let rootRect = _getOffsetRectFromViewport(rootNode, false);
			let itemRect = _getOffsetRectFromViewport(hoveredItemNode);
			let width = this._getMenuInfo()?.width ?? rootMenuRect.width;
			let menuRect = new geometry.Rectangle(this.direction == MenuDirectionType.ltr ? rootRect.right : (rootRect.left - rootMenuRect.width), itemRect.top, width, 0);
			let constraint = {
				top: menuRect.top,
				bottom: null,
				left: menuRect.left,
				right: null,
				width: menuRect.width
			}

			if (this.direction == MenuDirectionType.ltr) {
				if (this._viewportRect.right < menuRect.right && rootSpace.left > rootSpace.right) {
					constraint.left = rootRect.left - rootMenuRect.width;
				}
			} else {
				if (this._viewportRect.left > menuRect.left && rootSpace.right > rootSpace.left) {
					constraint.left = rootRect.right;
				}
			}
			let style = _.mapObject(constraint, (val: number | null, key: string) => {
				if (val == null) {
					return "auto";
				}
				return val + "px";
			})
			this._getRenderer().updateStyle(this.getRootNodeName(), style, true);

			this._updateMenuSize(itemRect);
		}

		private _updateMenuSize(parentItemRect: geometry.Rectangle) {
			let rootSubMenuNode = this._getRenderer().getNamedNode(this.getRootNodeName());// 메뉴리스트가 위치하는 래퍼 노드
			let rootSubMenuListNode = this._getMenuListNode(); // 메뉴 아이템이 갖는 리스트노드
			let rootSubMenuListRect = _getOffsetRectFromViewport(rootSubMenuListNode);
			let rootSpace = _getComputedSpaceInsets(rootSubMenuNode, {
				topOverflow: "altViewport",
				overflowConditionHandler: (type, result, rect, viewportRect) => {
					if (type == "top") { return rect.top + parentItemRect.height > viewportRect.bottom }
					return result;
				},
				customVerticalMeasurePosition: (type, rect, viewportRect) => {
					if (type == "top") {
						let bottom = rect.top + parentItemRect.height;
						return bottom < viewportRect.bottom ? bottom - viewportRect.top : viewportRect.height;
					} else if (type == "bottom") {
						return viewportRect.bottom - rect.top;
					}
					return 0;
				}
			});
			let rootSubMenuRect = _getOffsetRectFromViewport(rootSubMenuNode, false);
			let width = this._getMenuInfo()?.width ?? rootSubMenuRect.width;
			let constraint = {
				top: rootSubMenuRect.top,
				right: null,
				left: rootSubMenuRect.left,
				bottom: null,
				width: width
			}

			let computedStyle = getComputedStyle(rootSubMenuListNode);
			let borderTopWidth = _parseFloat(computedStyle.borderBottomWidth);
			let borderBottomWidth = _parseFloat(computedStyle.borderTopWidth);
			//padding
			let paddingTop = _parseFloat(computedStyle.paddingTop);
			let paddingBottom = _parseFloat(computedStyle.paddingBottom);
			let marginTop = _parseFloat(computedStyle.marginTop);
			let marginBottom = _parseFloat(computedStyle.marginBottom);
			let buttonTotalSize = this._getButtonHeight() * 2;

			let listExpandedRect = rootSubMenuListRect.getExpanded(new geometry.Insets(Math.max(marginTop, 0), 0, Math.max(marginBottom, 0), 0));
			let currentHeight = rootSubMenuListNode.offsetHeight;
			let needUpdateMenuTop = false;

			if (listExpandedRect.height > rootSpace.bottom) {
				if (rootSpace.top > rootSpace.bottom) {
					if (listExpandedRect.height > rootSpace.top) { // 메뉴 스크롤이 필요한 경우
						needUpdateMenuTop = true;
						currentHeight = rootSpace.top - (marginTop + marginBottom + borderTopWidth + borderBottomWidth + paddingTop + paddingBottom + buttonTotalSize); // 아이템만 생성될 높이
					} else {
						let isOverflowBottom = rootSubMenuRect.top + parentItemRect.height + paddingBottom > this._viewportRect.bottom;
						if (isOverflowBottom) {
							// 부모 아이템과 텍스트 위치를 맞추기 위해 paddingBottom과 borderBottomWidth를 빼준다.
							constraint.top = this._viewportRect.bottom - (currentHeight + marginTop + marginBottom);
						} else {
							constraint.top = (rootSubMenuRect.top + parentItemRect.height + borderBottomWidth) - (currentHeight - paddingBottom);
						}
					}
				} else { // 메뉴 스크롤이 필요한 경우
					let isOverflowTop = rootSubMenuRect.top - paddingTop < this._viewportRect.top;
					if (isOverflowTop) {
						constraint.top = this._viewportRect.top;
					} else {
						constraint.top = rootSubMenuRect.top - (borderTopWidth + paddingTop); // 부모 아이템과 텍스트 위치를 맞추기 위해 paddingTop과 borderTopWidth를 빼준다.
					}
					currentHeight = rootSpace.bottom - (marginTop + marginBottom + borderTopWidth + borderBottomWidth + paddingTop + paddingBottom + buttonTotalSize); // 아이템만 생성될 높이
				}
				let itemMaxCount = this._computeVisibleMenuItemCount(this._getVisibleItemElements(rootSubMenuListNode), currentHeight);
				let range = this._getMenuItemRange(itemMaxCount);
				this._updateMenuInfo({
					viewRange: range,
					minContentWidth: this._getComputedItemWidth(rootSubMenuNode, this._getMenuItemQuerySelector()),
					width: width
				});
				this._updateMenuContent();

				if (needUpdateMenuTop) {
					let updatedMenuListHeight = rootSubMenuListNode.offsetHeight;
					let isOverflowBottom = rootSubMenuRect.top + parentItemRect.height + paddingBottom > this._viewportRect.bottom;
					if (isOverflowBottom) {
						constraint.top = this._viewportRect.bottom - (updatedMenuListHeight + marginTop + marginBottom);
					} else {
						constraint.top = (rootSubMenuRect.top + parentItemRect.height + borderBottomWidth) - (updatedMenuListHeight - paddingBottom);
					}
				}
			} else {
				let isOverflow = rootSubMenuRect.top < this._viewportRect.top;
				if (isOverflow) {
					constraint.top = this._viewportRect.top;
				} else {
					constraint.top = constraint.top - (borderTopWidth + paddingTop); // 부모 아이템과 텍스트 위치를 맞추기 위해 paddingTop과 borderTopWidth를 빼준다.
				}
			}
			let style = _.mapObject(constraint, (val: number | null, key: string) => {
				if (val == null) {
					return "auto";
				}
				return val + "px";
			})
			this._getRenderer().updateStyle(this.getRootNodeName(), style, true);
		}

		private _updateMenuContent(style: {} = {}) {
			let menuInfo = this._getMenuInfo();
			if (menuInfo) {
				_assign(style, { "min-width": menuInfo.minContentWidth ? menuInfo.minContentWidth + "px" : "0px" });
			}

			let menuShape = this._createMenu();
			_assign(menuShape.style, style);
			this._getRenderer().replace(this._getMenuListNodeName(), menuShape);
		}

		protected _closestMenuElement(childElement: HTMLElement, rootElement: HTMLElement) {
			let domTraverser = ufc._traverseFromElement(childElement)._closest(".cl-menu-list", rootElement);
			return domTraverser ? domTraverser._getElement() : null;
		}

		/* evnet end */

	}//class

}//namespace