namespace cpr {

	/**
	 * zoom 영향받는 정보 참고: https://drafts.csswg.org/css-viewport/#zoom-om
	 * 
	 * zoom 관련 영향을 주는 API 및 속성
	 * HTMLElement.getBoundingClientRect
	 * MouseEvent.clientX
	 * MouseEvent.clientY
	 * MouseEvent.pageX
	 * MouseEvent.pageY
	 * Touch.clientX
	 * Touch.clientY
	 * Touch.pageX
	 * Touch.pageY
	 * 줌이 설정된 부모의 scrollTop, scrollLeft
	 */

	/**
	 * chrome 128버전부터 getBoundingClientRect가 줌을 반영한 값을 반환합니다.
	 * @returns 
	 */
	function checkScaledBoundingClientRect(): boolean {
		let detectBrowser = utils.Util.detectBrowser();
		if (detectBrowser.name == "safari" || detectBrowser.isIOS) {
			// iOS 크롬,safari 그리고 맥 safari에서 unscaled를 반환합니다.
			return false;
		} else if (detectBrowser.name == "chrome") {
			// 안드로이드 크롬, 윈도우 크롬은 버전에 따라 scaled 반영되는 동작이 다릅니다. zoom에 의해 scaled 반영왼 동작은 128이상
			if (detectBrowser.versionNumber > 127) {
				return true;
			} else {
				return false;
			}
		}
		return true;
	}

	/**
	 * 파이어폭스는 설정된 줌값을 가지고 계산하는 경우 실제 표시되는 좌표와 달라지는 현상이 발생
	 * @returns 
	 */
	export function _getZoom() {
		let zoom = core.Platform.INSTANCE.getZoom();
		let detectBrowser = utils.Util.detectBrowser();
		if (zoom != 1 && detectBrowser.name == "firefox") {
			return document.body.getBoundingClientRect().width / document.body.offsetWidth;
		}
		return zoom;
	}

	/**
	 * 뷰포트의 scrollTop, scrollLeft의 값을 unscaled 값으로 반환합니다.
	 * 뷰포트의 스크롤 속성들 window.PageXOffset, window.PageYOffset, documentElement.scrollTop, documentElement.scrollLeft
	 * @param value 
	 * @returns 
	 */
	export function _getUnscaledViewportScroll(value: number) {
		return _getUnscaledClientValue(value);
	}

	/**
	 * mouse event의 clientX,clientY 포인터 또는 pageX,pageY 포인터를 unscaled 값으로 반환합니다.
	 * @param value 
	 * @returns 
	 */
	export function _getUnscaledMouse(point: geometry.Point): geometry.Point;
	/**
	 * mouse event의 clientX,clientY,pageX,pageY의 값을 unscaled로 반환합니다.
	 * @param value 
	 * @returns 
	 */
	export function _getUnscaledMouse(value: number): number;
	export function _getUnscaledMouse(value: any): any {
		let zoom = _getZoom();
		if (zoom == 1) {
			return value;
		}
		if (typeof value == "number") {
			return value * (1 / zoom);
		} else if (value instanceof geometry.Point) {
			return value.scale(1 / zoom);
		}
		return value;
	}

	/**
	 * getBoundingClientRect의 속성 값을 unscaled 값으로 반환합니다.
	 * @param rectPropertyValue 
	 */
	export function _getUnscaledClientValue(value: number) {
		let zoom = _getZoom();
		if (zoom == 1) {
			return value;
		}
		if (checkScaledBoundingClientRect()) {
			return value * (1 / zoom);
		}
		return value;
	}

	/**
	 * 엘리먼트의 getBoundingClientRect를 unscaled 값으로 반환합니다.
	 * @param element 
	 */
	export function _getUnscaledClientRect(element: HTMLElement): geometry.Rectangle;
	/**
	 * getBoundingClientRect로 만든 Rectangle를 unscaled 값으로 반환합니다.
	 * @param rect 
	 * @returns 
	 */
	export function _getUnscaledClientRect(rect: geometry.Rectangle): geometry.Rectangle;

	export function _getUnscaledClientRect(value: any) {
		if (value instanceof HTMLElement) {
			value = geometry.Rectangle.clientBoundsOf(value);
		}
		let zoom = _getZoom();
		if (zoom == 1) {
			return value;
		}
		if (value instanceof geometry.Rectangle && checkScaledBoundingClientRect()) {
			return value.scale(1 / zoom);
		}
		return value;
	}

	/**
	 * zoom이 설정되었을때 동작과 아니었을때 동작을 구분하여 처리합니다.
	 * @param func 
	 * @param fallback 
	 */
	export function _workUnscale(func: (zoom: number) => void, fallback?: () => void) {
		let zoom = _getZoom();
		if (zoom != 1) {
			func(zoom);
		} else if (fallback) {
			fallback();
		}
	}

	/**
	 * 렌더링된 엘리먼트의 클라이언트 너비를 반환합니다. 클라이언트는 보더를 제외한 너비입니다.
	 * @param element 
	 * @returns 
	 */
	export function _getPreciseClientWidth(element: HTMLElement): number {
		if (!element)
			return 0;
		let computedStyle = getComputedStyle(element);
		return _getUnscaledClientRect(element).width - (parseInt(computedStyle.borderLeftWidth) + parseInt(computedStyle.borderRightWidth));
	}

	/**
	 * 렌더링된 엘리먼트의 클라이언트 높이를 반환합니다. 클라이언트는 보더를 제외한 높이입니다.
	 * @param element 
	 * @returns 
	 */
	export function _getPreciseClientHeight(element: HTMLElement): number {
		if (!element)
			return 0;
		let computedStyle = getComputedStyle(element);
		return _getUnscaledClientRect(element).height - (parseInt(computedStyle.borderTopWidth) + parseInt(computedStyle.borderBottomWidth));
	}

}