namespace cpr.controls.provider {

	/**
	 * @private
	 */
	export class ValueBinder implements bind.BindablePropertiesOwner {
		private _owner: UIControl;

		constructor(owner: UIControl) {
			this._owner = owner;

			if (this._shouldConfigureBindablePropertiesOfOwner()) {
				this._bindOwnerProperty("value", null)
					.withSetterTransformer(it => {
						if (typeof it === "boolean" || typeof it === "number") {
							return String(it);
						} else if (typeof it === "string") {
							return it;
						} else {
							return null;
						}
					})
					.withGetterTransformer(it => {
						if (it == null) {
							return null;
						} else {
							return String(it)
						}
					})
			}
		}

		/**
		 * 오너 컨트롤에 새로운 바인드 가능한 속성을 추가합니다.
		 * _shouldConfigureBindablePropertiesOfOwner()이 false를 리턴하는 경우, 널 팩토리가 반환되어 실제 속성이 추가되지 않습니다.
		 * 
		 * @param name 속성명.
		 * @param initValue 초기 값.
		 */
		protected _bindOwnerProperty(name: string, initValue: any): bind.IBindedPropertyFactory {
			if (this._owner && this._shouldConfigureBindablePropertiesOfOwner()) {
				return this._owner._addBindableProperty(name, initValue);
			}
			else {
				return bind.BindedPropertyFactoryImpl.NULL_FACTORY;
			}
		}

		protected _overwriteBindableProperty(name: string, initialValue: any): bind.IBindedPropertyFactory {
			if (this._getBindables().isBindable(name)) {
				this._getBindables().destroy(name);
			} else {
				throw new cpr.exceptions.IllegalArgumentException(`${name}은 기존에 바인드 되어 있지 않으므로 오버라이트 할 수 없습니다.`);
			}
			return this._owner._addBindableProperty(name, initialValue);
		}

		/**
		 * 오너 컨트롤에 대한 바인딩 속성 추가 허용 여부를 반환 합니다.
		 */
		protected _shouldConfigureBindablePropertiesOfOwner(): boolean {
			return true;
		}

		public getOwner(): UIControl {
			return this._owner;
		}

		protected redraw() {
			this._owner.redraw();
		}

		protected _getBindables(): bind.BindableProperties {
			return this._owner._getBindables();
		}

		/**
		 * 컨트롤의 값을 설정하고, value-change 이벤트가 발생됩니다.
		 * @param value 컨트롤의 값.
		 */
		public setValue(value: string, emitEvent: boolean = true): void {
			// BindedProperty가 유효하지 않을 때 처리 중지(바인딩된 컨텍스트의 상태 체크)
			let bindableProp: bind.BindableProperties = this._getBindables();
			let property = bindableProp.getBindableProperty("value");
			if (!property || property._isAvailable() == false) {
				return;
			}

			if (!emitEvent) {
				this._getBindables().set("value", value);
				return;
			}

			let oldValue: string = this.getValue();

			if (oldValue === value) {
				this.redraw();
				return;
			}

			let changeEvent = this.getOwner().dispatchEvent(new cpr.events.CValueChangeEvent(events.ValueChangeEventType.BEFORECHANGE
				, { oldValue: oldValue, newValue: value }));

			if (!changeEvent) {
				this.redraw();
				return;
			}

			if (this._getBindables().set("value", value)) {
				this.getOwner().dispatchEvent(new cpr.events.CValueChangeEvent(events.ValueChangeEventType.CHANGE
					, { oldValue: oldValue, newValue: value }));
			}

		}

		/**
		 * 컨트롤의 값을 반환합니다.
		 * @return 컨트롤의 값.
		 */
		public getValue(): string {
			return this._getBindables().get("value");
		}

		/**
		 * 컨트롤에 보여지는 텍스트를 반환합니다.
		 * @return 화면에 보이는 텍스트.
		 */
		public getText(): string {
			return this.getValue();
		}

		/**
		 * 컨트롤에 보이는 텍스트를 설정합니다.
		 * @param text 화면에 보이는 텍스트.
		 */
		public setText(text: string) {
			this.setValue(text);
		}

		/**
		 * @private
		 * @param propertyName 
		 * @param oldValue 
		 * @param newValue 
		 */
		_valueDidChange(propertyName: string, oldValue: any, newValue: any) {
			switch (propertyName) {
				case "value": {
					this.getOwner().redraw()
					break
				}
			}
		}

		getBindContext() {
			return this._owner.getBindContext();
		}
	}

	/**
	 * @private
	 */
	export class InputValueBinder extends ValueBinder {

		constructor(control: UIControl) {
			super(control);
			if (this._shouldConfigureBindablePropertiesOfOwner()) {
				this._overwriteBindableProperty("value", "")
					.withSetterTransformer(it => {
						if (typeof it === "boolean" || typeof it === "number") {
							return String(it);
						} else if (typeof it === "string") {
							return it;
						} else {
							return null;
						}
					})
					.withGetterTransformer(it => {
						if (it == null) {
							return null;
						} else {
							return String(it)
						}
					});
			}
		}

	}
	/**
	 * @private
	 */
	export class MultiValueBinder extends ValueBinder {
		private _delimiter: string = ",";

		constructor(control: UIControl) {
			super(control);
			this._bindOwnerProperty("multiple", false).withSetterValidatorWithType(false, "boolean");
		}

		/**
		 * 아이템의 다중 선택 여부를 반환합니다.
		 * @return 아이템의 다중 선택 여부.
		 */
		public getMultiple(): boolean {
			return this._getBindables().get("multiple");
		}

		/**
		 * 아이템의 다중 선택 여부를 설정합니다.
		 * @param newMultiple 아이템의 다중 선택 여부.
		 */
		public setMultiple(newMultiple: boolean) {
			this._getBindables().set("multiple", newMultiple);
		}

		/**
		 * 다중 선택 시 컨트롤에 저장되는 값의 배열을 설정하고, value-change이벤트가 발생됩니다.
		 * @param values 컨트롤에 저장되는 값의 배열.
		 * @param emitEvent 이벤트 발송 여부.
		 */
		public setValues(values: string[], emitEvent: boolean = true) {
			this.setValue(values == null || values.length == 0 ? null : values.join(this.getDelimiter()), emitEvent);
		}

		/**
		 * 다중 선택 시 컨트롤에 저장되는 값의 배열을 반환합니다.
		 * @return 컨트롤에 저장되는 값의 배열.
		 */
		public getValues(): string[] {
			let value = this.getValue();
			if (this.getMultiple()) {
				return (value == null) ? [] : value.split(this.getDelimiter());
			}
			return (value == null) ? [] : [value];
		}
		/**
		 * 다중 선택된 값을 지정하거나 가져올 때의 구분자를 반환합니다.
		 * @return 구분자.
		 */
		public getDelimiter(): string {
			return this._delimiter;
		}

		/**
		 * 다중선택된 값을 지정하거나 가져올 때의 구분자를 설정합니다.
		 * @param delimiter 구분자.
		 */
		public setDelimiter(delimiter: string) {
			if (this.getMultiple()) {
				//delimiter를 변경하기 전 value의 배열을 가져옴.
				let oldValues: string[] = this.getValues();
				this._delimiter = delimiter;
				if (oldValues.length > 0) {
					//values에서 join하여 value를 저장.
					this.setValues(oldValues);
				}
				this.getOwner().redraw();
			} else {
				//delimiter를 변경
				this._delimiter = delimiter;
			}
		}

		/**
		 * @private
		 * @param propertyName 
		 * @param oldValue 
		 * @param newValue 
		 */
		_valueDidChange(propertyName: string, oldValue: any, newValue: any) {
			super._valueDidChange(propertyName, oldValue, newValue);
			switch (propertyName) {
				case "multiple": {
					this.getOwner().redraw()
					break
				}
			}
		}

	}
}