		private _switchCheckBoxGroup(control: GridUIControl, grid: Grid, pos: selection.CellPosition, e: events.CMouseEvent): boolean {
			let checkboxgroup: CheckBoxGroup = control as CheckBoxGroup;

			let eventTarget: HTMLElement = <HTMLElement>e.target;
			let rootElement: HTMLElement = <HTMLElement>e.currentTarget;
			let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(eventTarget);

			if (checkboxgroup.clickRegion == ClickRegion.TEXT_FIELD) {
				domTraverser = domTraverser._closest('[data-region="field"]', rootElement);
			} else {
				domTraverser = domTraverser._closest('[data-region="colgroup"]', rootElement);
			}

			if (domTraverser == null) {
				return false;
			}

			domTraverser._closest("[data-region='colgroup']");
			if (domTraverser == null) {
				return false;
			}

			let dataValue: string = domTraverser._getAttribute("data-value");
			let item: Item = checkboxgroup.getItemByValue(dataValue);
			if (item && checkboxgroup.getItemEnable(item) == true) {
				checkboxgroup._toggleItem(item);
				let itemClickEvent = new events.CItemEvent(events.ItemEventType.ITEMCLICK, {
					item: item
				});
				itemClickEvent.nativeEvent = e;
				checkboxgroup.dispatchEvent(itemClickEvent);

				checkboxgroup._setFocusSelector(`[data-region="colgroup"][data-value="${dataValue}"] [data-role='checkbox']`);

				return true;
			}
			return false;
		}

		private _switchRadioButton(control: GridUIControl, grid: Grid, pos: selection.CellPosition, e: events.CMouseEvent): boolean {
			let radiobutton: RadioButton = control as RadioButton;

			let eventTarget: HTMLElement = <HTMLElement>e.target;
			let rootElement: HTMLElement = <HTMLElement>e.currentTarget;
			let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(eventTarget);

			if (radiobutton.clickRegion == ClickRegion.TEXT_FIELD) {
				domTraverser = domTraverser._closest('[data-region="field"]', rootElement);
			} else {
				domTraverser = domTraverser._closest('[data-region="colgroup"]', rootElement);
			}

			if (domTraverser == null) {
				return false;
			}

			domTraverser._closest("[data-region='colgroup']");
			if (domTraverser == null) {
				return false;
			}

			let item: Item = radiobutton.getItemByValue(domTraverser._getAttribute("data-value"));
			if (item && radiobutton.getItemEnable(item) == true) {
				radiobutton._select(item, e);
				let itemClickEvent = new events.CItemEvent(events.ItemEventType.ITEMCLICK, {
					item: item
				});
				itemClickEvent.nativeEvent = e;
				radiobutton.dispatchEvent(itemClickEvent);
				return true;
			}
			return false;
		}

		// 사용자 정의 이벤트 click만 전파
		private _switchButton(control: GridUIControl, grid: Grid, pos: selection.CellPosition, e: events.CMouseEvent): boolean {
			let button: Button = control as Button;

			let eventTarget: HTMLElement = <HTMLElement>e.target;
			let rootElement: HTMLElement = <HTMLElement>e.currentTarget;
			let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(eventTarget);

			domTraverser = domTraverser._closest('[role="button"], [role="link"]', rootElement);
			if (domTraverser == null) {
				return false;
			}

			button._setSoftActivated(true);

			let clickEvent: events.CMouseEvent = new events.CMouseEvent("click");
			clickEvent.nativeEvent = e;
			button.dispatchEvent(clickEvent);

			button._setSoftActivated(false);
			return true;
		}

		private _switchHTMLSnippet(control: GridUIControl, grid: Grid, pos: selection.CellPosition, e: events.CUIEvent): boolean {
			let htmlsnippet: HTMLSnippet = control as HTMLSnippet;

			let clickEvent: events.CMouseEvent = new events.CMouseEvent("click");
			clickEvent.nativeEvent = e;
			htmlsnippet.dispatchEvent(clickEvent);

			return true;
		}

		// Combobox 컨트롤 내에서 기본동작(openList)을 처리하고, 사용자 정의 이벤트 open 전파
		private _switchComboBox(control: GridUIControl, grid: Grid, pos: selection.CellPosition, e: events.CUIEvent): boolean {
			let combobox: ComboBox = control as ComboBox;

			let eventTarget: HTMLElement = <HTMLElement>e.target;
			let rootElement: HTMLElement = <HTMLElement>e.currentTarget;
			let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(eventTarget);

			domTraverser = domTraverser._closest('.cl-combobox', rootElement);
			if (domTraverser == null) {
				return false;
			}

			let clickEvent: events.CMouseEvent = new events.CMouseEvent("click");
			clickEvent.nativeEvent = e;

			let comboboxUuid: string = ufc.NodeUUIDMapper.INSTANCE._getControlNodeID(combobox);
			if (comboboxUuid) {
				let eventHandler: (e: cpr.events.CEvent) => void = cpr.events.EventBus.INSTANCE._getEventHandler(e, comboboxUuid);
				if (eventHandler) {
					eventHandler(clickEvent);
				}
			}

			return true;
		}

		// DateInput 컨트롤 내에서 기본동작(openCalendar)을 처리하고, 사용자 정의 이벤트 open 전파
