/// <reference path="./UIControl.ts" />
/// <reference path="./TextEditor.ts" />
/// <reference path="../foundation/StringMask.ts" />

namespace cpr.controls {

	/**
	 * @private
	 */
	enum MaskEditorClassName {
		clear = "cl-maskeditor-clear"
	}
	/**
	 * MaskEditor
	 * 입력 형식을 지정할 수 있는 컨트롤.
	 * 사용자는 (날짜, 전화번호 등)으로 데이터를 입력하고자하는 고정폭 입력을 보다 쉽게 입력 할 수 있습니다.
	 * 
	 * @firesgroup mouse
	 * @firesgroup contextmenu
	 * @firesgroup bindcontext
	 * @firesgroup keyboard
	 * @firesgroup focus
	 * @firesgroup drop
	 * @firesgroup input
	 * 
	 * 
	 * @fires cpr.events.CValueChangeEvent#before-value-change MaskEditor의 value를 변경하여 변경된 값이 저장되기 전에 발생하는 이벤트.
	 * 다음 이벤트로 value-change가 발생합니다.
	 * <pre>oldValue: {string} 이전 값</pre>
	 * <pre>newValue: {string} 변경될 값</pre>
	 * 
	 * @fires cpr.events.CValueChangeEvent#value-change MaskEditor의 value의 변경된 값이 저장된 후에 발생하는 이벤트.
	 * <pre>oldValue: {string} 이전 값</pre>
	 * <pre>newValue: {string} 변경된 값</pre>
	 * 
	 * @fires cpr.events.CMouseEvent#clear MaskEditor에서 esc키 또는 클리어버튼을 클릭하여 인풋의 값이 Clear될때 발생하는 이벤트.
	 * 
	 * @fires cpr.events.CInputFilterEvent#input-filter 입력상자의 텍스트가 입력될 때 발생하는 이벤트.
	 */
	export class MaskEditor extends TextEditor {
		private static readonly _AVAILABLE_PROP: string[] = [
			"mask", "autoSelect", "imeMode", "inputLetter", "overwrite", "clearButtonImage", "showClearButton", "buttonFocusable", "enabledInputMask", "autoSkip",
			"clearLabelExp", "inputMode", "displayExp"
		];

		private _mask: cpr.foundation.StringMask;
		private _inputMode: InputMode;
		private _imemode: ImeMode = ImeMode.disabled; // active, inactive, disabled 
		private _mouseDownFlag: boolean = false;
		private _buttonFocusable: boolean = false;
		private _autoskip: boolean = false;
		private _edited: boolean = false;
		private _displayExp: expression_string;

		private _clearBtnFocusEntry = new TextInputFocusEntry(this, `.${MaskEditorClassName.clear}`);
		/**
		 * 마스크 에디터를 생성합니다.
		 * @param id 마스크 에디터의 id.
		 */
		constructor(id?: string) {
			super(id);

			//bindable
			this._addBindableProperty("mask", "XXXXXXXXX").withSetterValidatorWithType(false, "string");
			this._addBindableProperty("autoSelect", false).withSetterValidatorWithType(false, "boolean");
			this._addBindableProperty("showClearButton", false).withSetterValidatorWithType(false, "boolean");
			this._addBindableProperty("clearButtonImage", "").withSetterValidatorWithType(false, "string", true).withStringGetterTransformer("");
			this._addBindableProperty("displayExp", "").withSetterValidatorWithType(false, "string");
			// defaults.js에서 사용하는 속성
			this._setInternalProperty("clearLabelExp", "");

			this._inputMode = InputMode.text;
			this._mask = new cpr.foundation.StringMask(this, {
				format: () => { return this.mask },
				formatChange: () => { this._onFormatChange(); },
				computeDisplayText: (text: string) => {
					if (!this.focused && this.displayExp) {
						return this._mask.getFormatter()._mask(this._getValue());
					}
					return text;
				}
			});
			this._mask.addEventListener("fill", (e) => { this._onMaskInputFill(e) });
			this._mask.addEventListener("paste", (e) => { this._onInput(e) }); // 컨트롤에서 이벤트를 감지 할 수 있으면 input 이벤트로 대체 가능 addInternalEvent는 사용자 이벤트에 의해 중단 될 수 있어서 사용할 수 없음
			this._addInternalEventListener(events.InputFilterEventType.INPUTFILTER, this._onInputFilter)
			// control initializing
			this._initControl();
		}

		protected _isConfigurableProperty(propName: string): boolean {
			if (MaskEditor._AVAILABLE_PROP.indexOf(propName) != -1) {
				return true;
			}
			return super._isConfigurableProperty(propName);
		}

		/* Shape */
		protected _getStylerSpec(): UIControlStylerSpec {
			return {
				root: { baseClass: "cl-maskeditor" },
				clear: { baseClass: "cl-maskeditor-clear" }
			};
		}

		/**
		 * 자동 크기 지원 타입을 얻습니다.
		 * 만일 both를 리턴했다면, css height, width 속성에 auto를 사용할 수 있음을 나타냅니다.
		 */
		override _getAutoSizeAvailability(): layouts.AutoSizeType {
			return layouts.AutoSizeType.both;
		}

		override _convertGridPasteText(text: string): string {
			if (text == "") {
				return text;
			}
			let value = text;
			let formatter = this._mask.getFormatter();
			if (formatter) {
				value = formatter.reverseTransform(value);
			}
			return value.length == 0 ? null : value;
		}

		public _getGridViewingText(): string {
			let value: string = this._getValue();
			if (this.displayExp) {
				return this.text;
			}
			let text: string = value == "" ? "" : this.text;
			return text;
		}

		public _renderGridCellShape(grid: Grid, data: (string | ufc.StyledString), option: gridpart.renderer.IRenderOption): ufc.ControlShape {
			let maskEditor: MaskEditor = this as MaskEditor;

			let maskEditorShape: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: ["cl-control", "cl-maskeditor"],
				attr: {},
				style: {},
				children: []
			};
			if (option.maxHeight >= 0) {
				maskEditorShape.style["height"] = option.maxHeight + "px";
			}
			if (option.hidetext == false) {
				let text: string = null;
				let value: string = maskEditor.value;
				if (maskEditor.displayExp) {
					text = maskEditor.text;
				} else {
					text = (value == null || value == "") ? "" : maskEditor.text;
				}
				let textStyle: { classNames?: string[], style?: { [key: string]: string } } = { style: { "line-height": "normal" } };
				let textWrap: ufc.ElementShape = gridpart.renderer.CellRendererFactory._getGridCellTextShape(text, option.maxHeight, textStyle);
				layouts.GridCSSBuilder._forCell()._withColumnStart(1)._withRowStart(1)._commit(textWrap.style);
				maskEditorShape.children = [textWrap];
			}
			layouts.GridCSSBuilder._forLayout()._withVerticalAlign(layouts.GridLayoutAlign.center)._withTemplateColumns("minmax(min-content, 1fr)")._withTemplateRows("1fr")._commit(maskEditorShape.style);
			return maskEditorShape;
		}

		// control's type overriding
		override _getType(): ControlType {
			return ControlType.MASKEDITOR;
		}

		/**
		 * 컨트롤에 포커스를 지정합니다.
		 */
		override focus(forward: boolean = true) {
			if (forward) {
				super.focus();
			} else {
				new TextInputFocusRing(this)._focusLast();
			}
		}

		/**
		 * @override 그리드에서 탭 이동시 이전과 다음에 따라 동작 할 수 있도록 제공
		 * @param forward 
		 */
		public override _focusImmediately(forward: boolean = true): void {
			let focusEntries = this._getFocusEntries() as TextInputFocusEntry[];
			if (forward) {
				focusEntries[0].focusImmediately();
			} else {
				focusEntries[focusEntries.length - 1].focusImmediately();
			}
		}

		/**
		 * @param name 
		 * @param oldValue 
		 * @param newValue 
		 */
		_valueDidChange(name: string, oldValue: any, newValue: any) {
			super._valueDidChange(name, oldValue, newValue);
			switch (name) {
				case "mask":
				case "autoSelect":
				case "showClearButton":
				case "clearButtonImage": {
					this.redraw();
					break;
				}
			}
		}

		// databindableUIControl overriding 
		/**
		 * 컨트롤의 value가 변경된 내용을 기준으로 포맷이 된 text를 반환합니다.
		 * @return display되는 text.
		 */
		public get text(): string {
			let result = this._mask.getFormatter().transform(this._getValue());
			if (this.displayExp) {
				result = ufc.StyledString._asString(this._computeDisplayExpText(result));
			}
			return result;
		}

		/**
		 * maskeditor 내 데이터 유형 별 입력 받을 형식을 반환합니다.
		 * @return maskeditor 내 데이터 유형 별 입력 받을 형식.
		 */
		get mask(): string {
			return this._bindables.get("mask");
		}

		/**
		 * maskeditor 내 데이터 유형 별 입력 받을 형식을 설정합니다.<br>
		 * 형식<br>
		 * * 0: [0-9]<br>
		 * * a: [a-z]<br>
		 * * A: [A-Z]<br>
		 * * z: [a-z0-9]<br>
		 * * Z: [A-Z0-9]<br>
		 * * x: [a-zA-Z]<br>
		 * * X: [a-zA-Z0-9]<br>
		 * * \: escapeChar 포맷문자를 일반 문자로 변경합니다. \x로 작성하면 x가 고정문자가 됩니다.<br>
		 * * *: [0-9a-zA-Z]를 *로 변환하여 보여줍니다. (시크릿 문자)
		 * <br>
		 * <pre><code>
		 * maskeditor.mask = "0000-00A";<br>
		 * maskeditor.mask = "0000\\x0000";<br>
		 * </code></pre>
		 * @param format maskeditor 내 데이터 유형 별 입력 받을 형식.
		 */
		set mask(format: string) {
			this._bindables.set("mask", format);
		}

		private _onFormatChange() {
			this._defaultSelection.state = SelectionState.INIT;
			this._defaultSelection.start = 0;
			this._defaultSelection.end = 0;
			this._initEditingText();
		}

		/**
		 * 포커스 될 시 편집 영역의 데이터 전체 선택 여부를 반환합니다.
		 * @return 포커스 될 시 편집 영역의 데이터 전체 선택 여부.
		 */
		get autoSelect(): boolean {
			return this._bindables.get("autoSelect");
		}

		/**
		 * 포커스 될 시 편집 영역의 데이터 전체 선택 여부를 설정합니다.
		 * @param autoselect 포커스 될 시 편집 영역의 데이터 전체 선택 여부.
		 */
		set autoSelect(autoselect: boolean) {
			this._bindables.set("autoSelect", autoselect);
			if (autoselect === true) {
				this._defaultSelection.state = SelectionState.NONE;
			}
		}

		/**
		 * 다음 컨트롤로 포커스 이동 여부를 반환합니다.
		 * @return 다음 컨트롤로 포커스 이동 여부.
		 */
		get autoSkip(): boolean {
			return this._autoskip;
		}

		/**
		 * 다음 컨트롤로 포커스 이동 여부를 설정합니다.<br>
		 * 마스크에디터의 포맷문자가 채워질 경우 다음 컨트롤로 포커스가 자동으로 이동합니다.<br>
		 * 관련 속성 : [nextControl] nextControl이 정해져 있지 않다면 tabindex 순서로 이동합니다.
		 * @param skip 다음 컨트롤로 포커스 이동 여부.
		 */
		set autoSkip(skip: boolean) {
			this._autoskip = skip;
		}

		/**
		 * 입력된 문자열의 길이를 반환합니다.
		 * @return 입력된 문자열의 길이.
		 */
		get length(): number {
			// reverseTransform 호출 시 _applyFormat()의 side effect로 포매터 상태가 변경되어
			// mask 변경 직후 호출하면 이전 포맷의 화면 텍스트를 새 포맷으로 잘못 해석하는 문제가 있어
			// placeholder 문자 비교로 채워진 슬롯 수를 계산한다.
			let formatter = this._mask.getFormatter();
			let displayText = this.displayingText;
			if (!displayText) return 0;
			let placeholder = formatter._getPlaceholder();
			let placeholderChar = formatter._getPlaceholderChar();
			let count = 0;
			let len = Math.min(displayText.length, placeholder.length);
			for (let i = 0; i < len; i++) {
				if (placeholder.charAt(i) === placeholderChar && displayText.charAt(i) !== placeholderChar) {
					count++;
				}
			}
			return count;
		}

		/**
		 * IE, FireFox 브라우저에서 한영 변환 설정을 반환합니다.
		 * @return 한영 변환 설정
		 */
		get imeMode(): ImeMode {
			return this._imemode;
		}

		/**
		 * IE, FireFox 브라우저에서 키보드 IME에 대한 한영 변환 설정. CSS의 ime-mode속성을 사용합니다. 지원하는 브라우저 버전에 따라 지원이 안될 수 있으니 MDN문서를 확인하시기 바랍니다. <br>
		 * [auto] : 현재 inputbox의 ime 설정에 대해 아무것도 하지않음.
		 * [active] : 기본 값으로 한글을 입력받습니다. <br>
		 * [inactive] : 기본 값으로 영문을 입력받습니다.<br>
		 * [disabled] : 영문만을 입력받습니다.
		 * @param imemode 한영 변환 설정
		 */
		set imeMode(imemode: ImeMode) {
			if (typeof imemode == "string") {
				imemode = imemode.toLowerCase() as any;
			}
			if (!ImeMode[imemode]) {
				imemode = null;
			}
			if (this._imemode == imemode) {
				return;
			}
			this._imemode = imemode;
			this.redraw();
		}

		/**
		 * 브라우저에서 가상키보드를 표시하는 자판의 배열 타입을 반환합니다.
		 */
		get inputMode(): InputMode {
			return this._inputMode;
		}

		/**
		 * 브라우저에서 가상키보드를 표시하는 자판의 배열 타입을 설정합니다.
		 */
		set inputMode(inputMode: InputMode) {
			if (this._inputMode == inputMode) {
				return;
			}
			this._inputMode = inputMode;
			this.redraw();
		}

		/**
		 * 입력시 알파벳문자에 대한 처리 방식 [none, uppercase, lowercase]
		 */
		get inputLetter() {
			return this._mask.inputLetter;
		}

		/**
		 * 입력시 알파벳문자에 대한 처리 방식 [none, uppercase, lowercase]
		 */
		set inputLetter(letter: string) {
			this._mask.inputLetter = letter;
		}

		/**
		 * 입력시 커서 위치의 값을 덮어쓰는 설정. 기본값 false
		 */
		get overwrite() {
			return this._mask.overwrite;
		}
		/**
		 * 입력시 커서 위치의 값을 덮어쓰는 설정. 기본값 false
		 */
		set overwrite(write: boolean) {
			this._mask.overwrite = write;
		}

		/**
		 * clear버튼 이미지를 반환합니다.
		 * @return clear버튼 이미지.
		 */
		get clearButtonImage(): string {
			return this._bindables.get("clearButtonImage");
		}
		/**
		 * clear버튼 이미지를 설정합니다.
		 * @param src clear버튼 이미지.
		 */
		set clearButtonImage(src: string) {
			this._bindables.set("clearButtonImage", src);
		}

		/**
		 * 포커스 상태가 아닐때 보여지는 텍스트에 대한 Expression을 반환합니다.
		 * @return 화면에 보여지는 텍스트의 Expression.
		 */
		get displayExp(): expression_string {
			return this._displayExp;
		}

		/**
		 * 포커스 상태가 아닐때 보여지는 텍스트에 대한 Expression을 설정합니다.
		 * @param expr 화면에 보여지는 텍스트의 Expression.
		 */
		set displayExp(expr: expression_string) {
			if (this._displayExp == expr) {
				return;
			}

			this._displayExp = expr;
			this.redraw();
		}

		/**
		 * 인풋에서 보여지는 HTML Element의 value를 가져옵니다.
		 * {@link displayExp}에서 지원되지 않는 속성입니다.
		 * @return display되는 text.
		 */
		get displayingText(): string {
			return this.displayText;
		}

		/**
		 * 인풋에서 보여지는 HTML Element의 value를 가져옵니다.
		 * {@link displayExp}에서 지원되지 않는 속성입니다.
		 * @return display되는 text.
		 * @deprecated {@link displayingText}을 사용하시기 바랍니다.
		 */
		get displayText(): string {
			return this._getDisplayingText();
		}

		/**
		 * clear버튼의 표시여부를 반환합니다
		 * @return clear버튼 표시여부
		 */
		get showClearButton() {
			return this._bindables.get("showClearButton");
		}

		/**
		 * clear버튼의 표시여부를 설정합니다.
		 * @param showClearButton clear버튼 표시여부설정.
		 */
		set showClearButton(showClearButton: boolean) {
			this._bindables.set("showClearButton", showClearButton)
		}

		/**
		 * 버튼에 포커스를 설정값을 반환합니다.
		 * @return 버튼 포커스 여부
		 */
		get buttonFocusable() {
			return this._buttonFocusable;
		}

		/**
		 * 버튼에 포커스를 설정합니다.
		 * @param focusable 버튼 포커스 여부
		 */
		set buttonFocusable(focusable: boolean) {
			this._buttonFocusable = focusable;
			this.redraw();
		}

		/**
		 * 입력 마스크 기능 활성화 여부를 반환합니다.
		 * @return 활성화 여부
		 */
		get enabledInputMask(): boolean {
			return this._mask.enabledInputMask;
		}

		/**
		 * 입력 마스크 기능 활성화 여부를 설정합니다.
		 * @param enabled 활성화 여부
		 */
		set enabledInputMask(enabled: boolean) {
			if (this._mask.enabledInputMask == enabled) {
				return;
			}
			this._mask.enabledInputMask = enabled;
			this.redraw();
		}

		private _getDisplayingValue(): string {
			return this._reverseTransformDisplayText(this._getValue());
		}

		private _reverseTransformDisplayText(text: string): string {
			if (this.enabledInputMask) {
				return this._mask.getFormatter().reverseTransform(text);
			}
			return text;
		}

		protected override _getInputTagValue(): string {
			let displayText = this._getDisplayText(); //마스크에디터는 우선 호출해야 포맷이 갱신되어짐.
			return this._hasEditingText() ? super._getInputTagValue() : displayText;

		}

		protected override _transformDisplayText(value: string): string | ufc.StyledString {
			if (!this.enabledInputMask) {
				if (this.focused && this.readOnly == false && this._isInputFocused()) {
					return value;
				}
			}
			if (this.focused) {
				return this._mask.getDisplayText(value);
			}
			if (this.displayExp) {
				return this._computeDisplayExpText(value);
			}
			return this._mask.getDisplayText(value);
		}

		/**
		 * 인풋박스가 포커스 받았는지 여부를 반환합니다.
		 * @returns 
		 */
		private _isInputFocused() {
			let node = this._getRenderer().getNamedNode("text");
			if (node) {
				return document.activeElement == node;
			}
			return false;
		}

		protected _useForceSelection() {
			return true;
		}

		protected _getDefaultSelection() {
			if (this._defaultSelection.state == SelectionState.API) {
				return { start: this._defaultSelection.start, end: this._defaultSelection.end };
			}
			return this._mask.getDefaultSelection(this._getDisplayText());
		}

		// Shape 
		public _createShape(): cpr.ufc.ControlShape {
			let children = [];
			let input = this._createInput();
			let grid: ufc.ControlShape = {
				tag: "div",
				style: {
					height: "100%"
				},
				children: [input]
			}
			let templateColumns = [];
			layouts.GridCSSBuilder._forCell()._withVerticalAlign(layouts.GridCellAlign.center)._withColumnStart(1)._withRowStart(1)._commit(input.style);
			templateColumns.push("1fr");
			if (this.showClearButton) {
				let clearButton = this._createClearButton();
				grid.children.push(clearButton);
				templateColumns.push("auto");
				layouts.GridCSSBuilder._forCell()._withVerticalAlign(layouts.GridCellAlign.center)._withColumnStart(2)._withRowStart(1)._commit(clearButton.style);
			}
			layouts.GridCSSBuilder._forLayout()._withVerticalAlign(layouts.GridLayoutAlign.center)._withTemplateColumns(templateColumns)._withTemplateRows("1fr")._commit(grid.style);
			children.push(grid);

			let shape: cpr.ufc.ControlShape = {
				tag: "div",
				attr: {
				},
				styler: "root",
				style: {
					overflow: "hidden"
				},
				eventTargets: [
					ufc.EventTargetType.UICONTROL,
					ufc.EventTargetType.INPUT,
					ufc.EventTargetType.DROPPABLE
				],
				classNames: [],
				events: {
					mousedown: this._onmousedown,
					click: this._onClick,
					keydown: this._onKeyDown,
					focus: this._onFocus,
					blur: this._onBlur,
				},
				children: children
			};

			cpr.ufc.ShapeUtil._setTooltipAttr(shape, { owner: this, title: this.tooltip });

			return shape;
		}

		private _createInput() {
			let input = this._createTextEditor();
			let value = this._getInputTagValue();

			input.aria = "root";
			input.attr['spellcheck'] = "false";
			input.attr['tabindex'] = "0";
			input.attr['autocomplete'] = "off";
			_assign(input.events, {
				focus: this._onInputFocus,
				blur: this._onInputBlur,
				input: this._onInput,
				keydown: this._onInputKeydown,
				dragover: this._onDragover,
				drop: this._onDrop
			});
			input.style["overflow"] = "hidden";
			if (this.inputMode && this.inputMode != InputMode.text) {
				input.attr["inputmode"] = this.inputMode;
			}
			if (this.imeMode) {
				input.style['imeMode'] = this.imeMode;
			}

			cpr.ufc.ShapeUtil._setAriaState(input, { enabled: this.enabled, readOnly: this.readOnly });
			cpr.ufc.ShapeUtil._setInputElementState(input, { enabled: this.enabled, readOnly: this.readOnly });

			input.value = value;
			if (this.readOnly == false) {
				this._mask.wrap(input);
			}
			return input;
		}

		/**
		 * Clear버튼 생성
		 */
		private _createClearButton(): cpr.ufc.ControlShape {
			let button: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: [],
				styler: "clear",
				attr: {
					role: "button",
					"aria-hidden": "true",
					"aria-label": this._getLabel(cpr.I18N.INSTANCE.message(core.PlatformTerms.CLEAR), this._getInternalProperty("clearLabelExp"))
				},
				style: {
					display: "block",
					height: "100%"
				},
				nodename: "clear",
				events: {}
			}
			cpr.ufc.ShapeUtil._setAriaDisabled(button, this.enabled && !this.readOnly);

			if (this.clearButtonImage != "") {
				button.style['background-image'] = _quoteAsCSSURL(this.clearButtonImage);
			}
			let isVisibleButton = this.showClearButton && this._getDisplayingValue() != "" && this.readOnly == false && this.enabled;
			if (isVisibleButton == false) {
				button.style["display"] = "none";
			}

			if (this.enabled) {

				if (this.buttonFocusable) {
					delete button.attr["aria-hidden"];
					button.attr['tabindex'] = "0"; // IE에서 포커스 아웃라인이 -1이면 표시되지 않음.
					button.events["keydown"] = this._onBtnClearKeydown;
				} else {
					button.attr['tabindex'] = "-1";
				}
			}

			return button;
		}

		// private method 
		protected _setSelectionText(start: number, end: number, text: string, insertText: string): void {
			let firstText = text.substr(0, start);
			let endText = text.substr(end, text.length);
			this._setValue(this._mask.getFormatter().reverseTransform(firstText + insertText + endText));//넘버에디터와 마스크 에디터에 대한 텍스트 가공이 필요함.
		}

		// event start 
		private _onBtnClearKeydown(e: events.CKeyboardEvent) {
			if (this.readOnly) {
				return;
			}
			let keyCode = e.keyCode;

			if (keyCode == events.KeyCode.SPACE || keyCode == events.KeyCode.ENTER) {
				e.preventDefault();
				this._clear({ nativeEvent: e });
			};
			if (this.disposed) {
				return;
			}
			if (this._getValue() != "") {
				return;
			}
			super._focusImmediately();
		}

		protected _updateInputValue(): void {
			if (this.disposed) {
				return;
			}
			let inputDom = <HTMLInputElement>this._getRenderer().getNamedNode("text");
			if (!inputDom) {
				return;
			}
			this._mask.getFormatter()._mask(this._getValue()); //update mask 시크릿 포맷은 시크릿 포맷의 값을 업데이트 해야 함.(개선 필요)
			let text = this._getDisplayText();
			if (inputDom.value != text) {
				// safari는 value값을 변경했을때 커서가 끝으로 이동하지 않음.
				// input.value 했을시 Chrome에서는 커서가 맨 앞으로 이동. setAttribute("value",newValue) DOM속성에 값이 표시됨.
				inputDom.value = text;
			}
		}

		/**
		 * 인풋의 값에 따라 클리어 버튼을 표시하거나 숨깁니다.
		 */
		private _updateClearButton(text: string) {
			// 항상 숨김 상태일 경우 return
			if (!this.showClearButton) {
				return;
			}

			let emptyMaskText = ufc.StyledString._asString(this._transformDisplayText(""));
			// 클리어버튼이 표시된 상태에서 값이 없는 경우 또는 클리어버튼이 표시되지 않은 상태에서 값이 있는 경우
			let isEmptyText = text == emptyMaskText;
			if (isEmptyText) {
				this._getRenderer().updateStyle("clear", { display: "none" }, true);
			} else {
				this._getRenderer().updateStyle("clear", { display: "block" }, true);
			}
		}

		private _isHiddenClearButton() {
			let clearNode = this._getRenderer().getNamedNode("clear");
			if (!clearNode) {
				return true;
			}
			return clearNode.style.display == "none";
		}

		private _clearTextByESC(e: events.CKeyboardEvent) {
			if (this.readOnly || this._isHiddenClearButton()) {
				return;
			}
			let clearEvent = new cpr.events.CEvent("clear");
			clearEvent.nativeEvent = e;

			let preventDefault = this.dispatchEvent(clearEvent);
			if (!preventDefault) {
				return;
			}

			let input = e.target as HTMLInputElement;
			input.value = ufc.StyledString._asString(this._transformDisplayText(""));
			this._updateEditingText(input);
			this._updateClearButton(input.value);
			input.setSelectionRange(0, 0);
		}

		private _onClearButtonClick(e: events.CMouseEvent) {
			if (this.readOnly) {
				return;
			}
			let clearEvent = new cpr.events.CEvent("clear");
			clearEvent.nativeEvent = e;

			let preventDefault = this.dispatchEvent(clearEvent);
			if (!preventDefault) {
				return;
			}
			if (this.focused == false) {
				this._setValue("");
			} else {
				let input = <HTMLInputElement>this._getRenderer().getNamedNode("text");
				let isActiveElement = document.activeElement === input;
				if (isActiveElement == false) {//buttonFocusable 일때 클리어 버튼에 포커스 있는 경우
					this._setValue("");
					super._focusImmediately();
				}
				cpr.core.DeferredUpdateManager.INSTANCE.asyncExec(() => {
					if (this.disposed) {
						return;
					}
					if (isActiveElement) {
						// mousedown에서 focus를 input에 설정하는데 focus 이벤트에 비동기로 값 설정에 영향을 받아 click에서 설정하는 값이 무시되는 현상이 발생하여 DeferredUpdateManager 설정함.
						input.value = ufc.StyledString._asString(this._transformDisplayText(""));
						this._updateEditingText(input);
						this._updateClearButton(input.value);
						input.setSelectionRange(0, 0);
					}
				});

			}
		}

		private _onInputFilter(e: events.CInputFilterEvent) {
			this._edited = true;
		}

		private _updateEditingText(input: HTMLInputElement): void {
			if (input.value != this._getDisplayText()) {
				this._edited = true;
			}
		}
		private _onInput(e: events.CUIEvent): void {
			let input: HTMLInputElement = <HTMLInputElement>e.target;

			this._updateEditingText(input);
			this._updateClearButton(input.value);
		}

		private _onMaskInputFill(e: events.CUIEvent) {
			if (this.autoSkip) {
				cpr.core.DeferredUpdateManager.INSTANCE._performFocusTask(() => {
					this.focusNext();
				});
			}
		}

		private _onClick(e: events.CMouseEvent): void {
			let target = <HTMLElement>e.target;
			if (e.defaultPrevented) {
				return;
			}
			if (target == null) {
				return;
			}
			if (target.classList.contains("cl-maskeditor-clear")) {
				this._onClearButtonClick(e);
			}
		}

		private _onmousedown(e: MouseEvent) {
			if (e.defaultPrevented) {
				return;
			}
			let target: HTMLElement = e.target as HTMLElement;
			if (target == e.currentTarget) {
				e.preventDefault();
				super._focusImmediately();
				// this.focus();
			}
			if (target.classList.contains("cl-maskeditor-clear")) {
				//인풋에 포커스를 준다.
				if (!this.focused) {
					super._focusImmediately();
					// this.focus();
				}
				//인풋의 포커스가 빠지지않게 한다.
				e.preventDefault();
			}
		}

		protected _onInputMousedown(e: MouseEvent) {
			super._onInputMousedown(e);
			this._mouseDownFlag = true;
		}

		private _onInputFocus(e: FocusEvent): void {
			// 참고. StringMask 의 focus 이벤트에서 input의 value를 설정하고 있음.
			let input: HTMLInputElement = e.target as HTMLInputElement;

			if (input == null) {
				return;
			}
			if (this._mouseDownFlag) {
				this._mouseDownFlag = false;
				if (!this.autoSelect) {
					return;
				}
			}

			cpr.core.DeferredUpdateManager.INSTANCE.asyncExec(() => {//2018-09-13 Edge에서 포커스 이후 selection이 마지막으로 이동되는 현상 제어.
				if (document.activeElement !== input) {
					return;
				}
				this._checkAutoSelect(input, this.autoSelect);
				if (this._defaultSelection.state != SelectionState.NONE) {
					this._defaultSelection.state = SelectionState.NONE;
				}

			});
		}

		protected override _checkValueChange(oldValue: string, newValue: string): boolean {
			if (this._edited == false) {
				return ufc.StyledString._asString(this._transformDisplayText(newValue)) != ufc.StyledString._asString(this._transformDisplayText(oldValue));
			}
			return super._checkValueChange(oldValue, newValue);
		}

		private _onFocus(e: FocusEvent): void {
			if (this.displayExp && this.showClearButton && this.buttonFocusable) {
				this.redraw();
			}
		}

		private _onBlur(e: FocusEvent): void {
			if (this.displayExp && this.showClearButton && this.buttonFocusable) {
				this.redraw();
			}
		}

		private _onInputBlur(e: events.CFocusEvent): void {
			let input: HTMLInputElement = e.target as HTMLInputElement;
			let newValue: string = input.value;

			this._mouseDownFlag = false;
			if (this._defaultSelection) {
				this._defaultSelection.start = input.selectionStart;
				this._defaultSelection.end = input.selectionEnd;
			}
			if (this.readOnly) {
				return;
			}
			this._updateClearButton(input.value);

			if (this._canUpdateValue()) {
				let data: string;
				if (!this._mask.getFormatter()) {
					data = newValue;
				} else {
					data = this._mask.currentValue; // mask to data
				}
				if (this._checkValueChange(this._getValue(), data)) {
					this._setValue(data);
				}
				this._edited = false;
				this.redraw();// displayExp를 적용하기 위해 redraw 필요
			}
		}

		private _onInputKeydown(e: events.CKeyboardEvent): void {
			if (this.readOnly) {
				return;
			}
			let keyCode = e.keyCode;
			switch (keyCode) {
				case events.KeyCode.ENTER:
					//IE11에서 ENTER키를 통한 change이벤트가 발생 안하여 keydown에서 처리.
					let inputTag: HTMLInputElement = e.target as HTMLInputElement;
					let inputValue: string = inputTag.value;

					let data: string;
					if (!this._mask.getFormatter()) {
						data = inputValue;
					} else if (!this._edited) {
						// 포커스 후 입력 없이 Enter: mask가 외부에서 변경되었더라도 DOM 텍스트가
						// 새 포맷으로 갱신되기 전일 수 있으므로 저장된 값을 정본으로 사용한다.
						data = this._getValue() ?? "";
					} else {
						data = this._mask.getFormatter().reverseTransform(inputValue); // mask to data
					}
					if (this._checkValueChange(this._getValue(), data)) {
						this._setValue(data);
						if (this.autoSkip) {
							cpr.core.DeferredUpdateManager.INSTANCE._performFocusTask(() => {
								if (this.disposed) {
									return;
								}
								this.focusNext();
							});
						}
					}
					this._edited = false;
					this.redraw();
					break;
			}
		}

		private _onKeyDown(e: events.CKeyboardEvent): void {
			if (e.defaultPrevented) {
				return;
			}
			let keyCode = e.keyCode;
			let target = e.target as HTMLElement;
			switch (keyCode) {
				case events.KeyCode.ESC:
					if (target.classList.contains(ufc.Classes.TEXT) == false || this.showClearButton == false) {
						break;
					}
					this._clearTextByESC(e);
					//IE에서 esc입력 시 이전 값으로 되돌아가는 것을 방지
					e.preventDefault();
					break;
				case events.KeyCode.TAB:
					// 그리드에서 컨트롤 내에서 탭이동 제어를 위해 preventDefault()가 필요하여 키보드 이벤트 사용
					if (this.buttonFocusable == false) {
						break;
					}
					if (e._getMod2Key()) {
						this._focusPrevious(true);
						e.preventDefault();
					} else {
						this._focusNext(true);
						e.preventDefault();
					}
					break;
			}
		}
		private _onDrop(e: DragEvent): void {
			if (!this.focused && this.displayExp) {
				e.preventDefault();
			}
		}
		private _onDragover(e: DragEvent): void {
			if (!this.focused && this.displayExp) {
				e.preventDefault();
				e.dataTransfer.dropEffect = "none";
			}
		}

		// event end 
		private _clear(options: { nativeEvent?: Event, emitEvent?: boolean } = {}) {
			options = _defaults(options, { nativeEvent: null, emitEvent: true });
			if (options.emitEvent) {
				//clear이벤트 생성
				let clearEvent = new cpr.events.CEvent("clear");
				if (options.nativeEvent) {
					clearEvent.nativeEvent = options.nativeEvent;
				}
				let preventDefault = this.dispatchEvent(clearEvent);
				if (!preventDefault) {
					return;
				}
			}
			this._setValue("");
		}

		private _computeDisplayExpText(value: string): ufc.StyledString | string {
			let expr = new cpr.expression.Expression(this.displayExp);
			let result: any;
			try {
				let that = this;
				let edo = new cpr.expression.ExpressionDelegateObject(this.type, "displayExp", { text: that._mask.getDisplayText(value) });
				edo.setUnsupportedProperty("displayText", "");
				edo.setUnsupportedProperty("displayingText", "");
				let altProperty = edo.createObject();
				result = expr._evaluateInternal({
					_getExpressionDelegates(): any[] {
						return [altProperty, that, that.getBindContext()];
					}
				});
			} catch (e) {
				result = this._mask.getDisplayText(value);
			}
			return result;
		}

		public override _exportValue(): string | number {
			let ctrlText = (this.text === undefined) ? this.value : this.text;

			// 데이트인풋, 마스크에디터, 아웃풋(string,date) >> text (value가 null이 아닐때)
			return (this.value != null && this.value != "") ? "" + ctrlText : this.displayExp ? ctrlText : "";
		}

		/**
		 * 사용자 정의 패턴을 추가합니다.<br>
		 * <pre><code>maskeditor.addCustomPattern("k", /[a-c]/); //a부터c까지만 입력.</code></pre><br>
		 * @param key 패턴 정의 문자.
		 * @param pattern 패턴에 대한 정규식.
		 */
		public addCustomPattern(key: string, pattern: RegExp): void {
			(<cpr.foundation.StringFormatter>this._mask.getFormatter()).addCustomPattern(key, pattern);
			this.redraw();
		}
		/**
		 * 사용자 정의 패턴을 삭제합니다.
		 * <pre><code>maskeditor.deleteCustomPattern("k");</code></pre><br>
		 * @param key 패턴 정의 문자.
		 */
		public deleteCustomPattern(key): void {
			if (this.getCustomPatterns()[key] == null) {
				return;
			}
			(<cpr.foundation.StringFormatter>this._mask.getFormatter()).deleteCustomPattern(key);
			this.redraw();
		}

		/**
		 * 사용자 정의 패턴을 반환합니다.
		 * @return 사용자 정의 패턴. {key: pattern}
		 */
		public getCustomPatterns(): { [key: string]: { pattern: RegExp } } {
			return (<cpr.foundation.StringFormatter>this._mask.getFormatter()).getCustomPatterns();
		}

		/**
		* 인풋박스의 value를 빈 값으로 설정합니다. <br>
		* clear 이벤트를 발생합니다.
		* @param emitEvent clear이벤트를 발생시킬지 여부
		*/
		public clear(emitEvent: boolean = true): void {
			this._clear({ emitEvent: emitEvent });
		}

		/**
		 * 컨트롤에 포함되어있는 객체들을 제거합니다.
		 */
		public dispose(): void {
			if (this._mask) {
				this._mask.dispose();
				this._mask = null;
			}
			super.dispose();
		}

		override _getFocusEntries(): FocusEntry[] {
			let renderer = this._getRenderer();
			let focusEntries = super._getFocusEntries();
			if (this.buttonFocusable == false) {
				return focusEntries;
			}
			let clearBtn = renderer.getNamedNode("clear");
			if (clearBtn && !this._isHiddenClearButton()) focusEntries.push(this._clearBtnFocusEntry);

			return focusEntries;
		}
		override _getActiveFocusEntry(): FocusEntry {
			let activeElement = document.activeElement as HTMLElement;
			if (!activeElement) {
				return null;
			}
			let classList = activeElement.classList;
			if (classList.contains(MaskEditorClassName.clear)) {
				return this._clearBtnFocusEntry;
			} else {
				return super._getActiveFocusEntry();
			}
		}
	}
}