/// <reference path="./EnableUIControl.ts"/>
/// <reference path="../utils/Logger.ts"/>
namespace cpr.controls {
	let log = utils.Logger.forTopic("embedded")._createBindedLoggerFunction({
		updator: it => log = it
	});

	/**
	 * app안에 app을 내장 할 수 있는 컴포넌트.
	 * 
	 * @firesgroup mouse
	 * @firesgroup contextmenu
	 * @firesgroup bindcontext
	 * @firesgroup keyboard
	 * @firesgroup drop
	 * 
	 * 
	 * @fires cpr.events.CEvent#init 임베디드 앱의 인스턴스가 만들어지고, 데이터 및 컨트롤 구성이 완료된 후 디스패치 되는 이벤트.
	 * @fires cpr.events.CEvent#app-ready 임베디드 앱의 인스턴스와 관련 자원이 준비되는 시점에 디스패치되는 이벤트.
	 * @fires cpr.events.CSelectionEvent#app-change 임베디드 앱의 앱이 교체되거나 지정될때 전파되는 이벤트.
	 * @fires cpr.events.CEvent#load 임베디드 앱의 인스턴스와 관련 자원이 준비되는 시점에 디스패치되는 이벤트.
	 * @fires cpr.events.CEvent#host-change 앱이 다른 부모 앱에 포함되거나 부모 앱으로 부터 이탈할 때 발생하는 이벤트 입니다.
	 * 
	 */
	export class EmbeddedApp extends EnableUIControl {
		private static readonly EMBEDDEDAPP_AVAILABLE_PROP: string[] = [
			"initValue", "returnValue"
		];

		private _embeddedApp: core.App;
		private _embeddedAppInstance: core.AppInstance;

		/**
		 * 실행을 시도중인 앱.
		 */
		private _launchingApp: core.App;
		private _readyListeners: ((e?: events.CEvent) => void)[] = [];

		private _forceRunRequested = false;

		private _tabIndex: number = 0;

		/**
		 * 임베디드 앱을 생성합니다.
		 * @param id 임베디드 앱의 id.
		 * @param app 임베디드 앱 내부에 들어갈 앱.
		 */
		constructor(id?: string, app?: core.App) {
			super(id);
			this._embeddedApp = app;

			this._addBindableProperty("initValue", null);
			this._addBindableProperty("returnValue", null);

			if (this._getType() == ControlType.EMBEDDEDAPP) {
				// control initializing
				this._initControl();
			}
		}

		protected _isConfigurableProperty(propName: string): boolean {
			if (EmbeddedApp.EMBEDDEDAPP_AVAILABLE_PROP.indexOf(propName) != -1) {
				return true;
			}
			return super._isConfigurableProperty(propName);
		}

		protected _getStylerSpec(): UIControlStylerSpec { /* TODO abstract */
			return {
				root: {
					baseClass: "cl-embeddedapp"
				}
			};
		}

		public _getProperty(name: string) {
			if (this._getBindables().isBindable(name)) {
				return this._getBindables().get(name);
			}
			switch (name) {
				case "fieldLabel":
					return this.fieldLabel;
			}
		}

		public _setProperty(name: string, value: any) {
			if (this._getBindables().isBindable(name)) {
				this._getBindables().set(name, value);
				return;
			}
			switch (name) {
				case "fieldLabel":
					this.fieldLabel = value;
					break;
			}
		}

		/**
		 * 임베디드앱 컨트롤은 포커스를 가지지 못하는 컨트롤이므로 focusable 을 false로 주기 위해 _isFocusable 을 오버라이드합니다.
		 */
		protected _isFocusable(): boolean {
			let app = this.getEmbeddedAppInstance();
			if (app?.state !== core.AppInstanceState.RUNNING) {
				return false;
			}
			return new AppFocusRing(app)._isEmpty() === false;
		}

		override focus(forward: boolean = true): void {
			if (!this.isShowing() || !this.enabled) {
				return;
			}

			let app = this.getEmbeddedAppInstance();
			if (app?.state !== core.AppInstanceState.RUNNING) {
				return;
			}

			let internalRing = new AppFocusRing(this.getEmbeddedAppInstance());
			if (forward) {
				internalRing._focusNext();
			} else {
				internalRing._focusPrevious();
			}
		}

		public get tabIndex(): number {
			return this._tabIndex;
		}

		public set tabIndex(tabIndex) {
			this._tabIndex = tabIndex;
			// redraw() 필요 없음. 이 탭 인덱스는 돔으로 노출되지 않음.
		}


		/**
		 * 임베딩 된 앱의 인스턴스가 만들어지고 구성요소를 모두 생성 한 후, init 이벤트 발생 직전에 호출 됩니다.
		 * @param embeddedAppInstance 
		 */
		public _embeddedAppWillInit(embeddedAppInstance: core.AppInstance) {
			if (embeddedAppInstance.app == this.app) {
				if (this._embeddedAppInstance) {
					if (this._embeddedAppInstance.disposed === false) {
						this._embeddedAppInstance.dispose();
					}
				}
				this._embeddedAppInstance = embeddedAppInstance;

				// 컨테이너의 바인드 컨텍스트를 외부와 연결.
				this._embeddedAppInstance.getContainer()._setBindContextualParent(this);
				this.redraw();
			}
			else {
				if (this._embeddedAppInstance) {
					if (this._embeddedAppInstance.disposed === false) {
						this._embeddedAppInstance.dispose();
					}
				}
				this._embeddedApp = embeddedAppInstance.app;
				this._embeddedAppInstance = embeddedAppInstance;
				// 컨테이너의 바인드 컨텍스트를 외부와 연결.
				this._embeddedAppInstance.getContainer()._setBindContextualParent(this);
				this.redraw();
			}
		}

		/**
		 * 앱이 사이클릭되었는지 조사하고, 사이클릭일 경우, 문제를 알리는 앱으로 바꿔치기 합니다.
		 */
		private _detectCyclic() {
			if (!this._embeddedApp || this._embeddedAppInstance) {
				return;
			}
			internal._checkCyclic(this);
		}

		private _isLaunching(): boolean {
			return this._launchingApp != null;
		}

		/**
		 * 임베디드 앱이 화면에 표시중이 아니어서 실행할 필요가 없더라도 강제로 앱을 시작 시킵니다.
		 * 아직 앱이 지정되지 않았다면, 나중에 앱이 지정될 때 강제로 앱이 바로 시작됩니다. 이 동작은 취소할 수 없습니다.
		 * @param callback 앱이 시작된 후의 콜백.
		 */
		public forceRun(callback?: (embeddedApp: EmbeddedApp) => void): Promise<EmbeddedApp> {
			// 앱이 실행중인 경우.
			if (this._embeddedAppInstance) {
				if (callback) {
					callback(this);
				}
				return Promise.resolve(this);
			}
			else {
				if (callback) {
					this.ready(callback);
				}

				// 앱이 지정되어 있는 경우.
				if (this._embeddedApp) {
					this._ensureAppRunning();
				}

				// 아직 앱이 지정되어 있지 않은 경우.
				else {
					this._forceRunRequested = true;
				}

				return new Promise<EmbeddedApp>((resolve, reject) => {
					this.ready((ea) => {
						resolve(ea);
					});
				});
			}
		}

		protected _ensureAppRunning(): void {
			log("임베디드 앱 실행 요청됨.");
			if (!this._embeddedApp) {
				log("설정된 앱이 없기 때문에 기각되었습니다.");
				return;
			}
			if (this._isLaunching()) {
				log(`이미 ${this._launchingApp.id} 앱이 실횅 대기중이기 때문에 기각되었습니다.`);
				return;
			}

			// 이미 실행중인 경우, 실행 할 필요 없음.
			if (this._embeddedAppInstance) {
				log(`이미 실행중인 앱 인스턴스가 존재하기 때문에 기각되었습니다.`);
				return;
			}

			this._launchingApp = this._embeddedApp;
			log(`${this._embeddedApp.id} 앱의 실행 시작 중임을 마킹하였습니다.`)

			let run = () => {
				if (!this._embeddedApp) {
					return;
				}

				// 이미 실행중인 경우, 실행 할 필요 없음.
				if (this._embeddedAppInstance) {
					return;
				}

				this._detectCyclic();
				let appInstance = this._embeddedApp.createNewInstance();

				// 렌더링 도중이라면 다음 틱에, 그 외의 경우 아래 코드가 즉시 실행 됨
				appInstance.run(this, (appInstance: core.AppInstance) => {
					if (this.disposed) {
						return
					}

					if (this._launchingApp === appInstance.app) {
						this._launchingApp = null;
						log("앱이 실행되어 실행대기중인 앱을 언마킹하였습니다.")
					}

					let event = new events.CEvent("host-change");
					appInstance.dispatchEvent(event);

					// 임베디드 앱 인스턴스의 업데이트는 _embeddedAppWillInit 에서 처리 됨.
					if (this._embeddedApp === appInstance.app) {
						let event: events.CEvent = new events.CEvent("app-ready");
						this.dispatchEvent(event);
						this.redraw();
					}
				});
			}

			run();
		}

		/**
		 * 임베디드앱이 시작시 전달받은 값을 반환합니다.
		 * @return 시작 전달받은 값.
		 */
		get initValue(): any {
			return this._bindables.get("initValue");
		}

		/**
		 * 임베디드앱의 시작시 전달할 값을 설정합니다.
		 * @param value 시작시 전달할 값.
		 */
		set initValue(value: any) {
			this._bindables.set("initValue", value);
		}

		/**
		 * 임베디드앱이 반환되는 값을 반환합니다.
		 * @return 반환된 값.
		 */
		get returnValue(): any {
			return this._bindables.get("returnValue");
		}

		/**
		 * 임베디드앱이 반환되는 값을 설정합니다.
		 * @param value 반환할 값.
		 */
		set returnValue(value: any) {
			this._bindables.set("returnValue", value);
		}

		/**
		 * 컨트롤을 포함 여부를 반환합니다.
		 * @param drawable 컨트롤.
		 */
		public _containsDrawble(drawable: core.Drawable): boolean {
			if (this === drawable) {
				return true;
			}
			return this._embeddedAppInstance ? this._embeddedAppInstance.getContainer()._containsDrawble(drawable) : false;
		}

		public _createShape(): cpr.ufc.ControlShape {
			this._ensureAppRunning();
			let result: ufc.ControlShape = {
				tag: "div",
				attr: {
				},
				styler: "root",
				eventTargets: [
					ufc.EventTargetType.UICONTROL,
					ufc.EventTargetType.DROPPABLE
				],
				style: {
					"overflow": "auto"
				},
				children: this._embeddedAppInstance ? [this._embeddedAppInstance.getContainer()._getRenderer()] : []
			}

			// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/4899
			// 임베디드 앱의 클리핑 규칙을 내부 앱 컨테이너가 결정하게 합니다.
			if (this._embeddedAppInstance && this._useClippingRuleOfContent()) {
				let localContainer = this._embeddedAppInstance.getContainer();
				result.style.overflow = localContainer.clipContent ? "hidden" : "visible";
			}

			cpr.ufc.ShapeUtil._setTooltipAttr(result, { owner: this, title: this.tooltip });
			return result;
		}

		/**
		 * 내부 앱 인스턴스의 앱 컨테이너에 지정된 클리핑 룰을 승계할 것인지 여부를 반환합니다.
		 * 예를들어 내부 앱 컨테이너가 스크롤을 허용하지 않지만, 클리핑을 수행하지 않아 overflow: visible 상태가 되었다면,
		 * 임베디드 앱의 셰이프 모델이 다시 스크롤 바를 만드는 것을 방지 합니다.
		 * 
		 * @see https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/4899
		 */
		public _useClippingRuleOfContent(): boolean {
			return true;
		}

		/**
		 * app을 설정합니다. app이 변경된 경우, ready()로 예약된 작업들은 모두 취소됩니다.
		 * @param newApp embedded app.
		 */
		public set app(newApp: cpr.core.App) {
			let oldApp = this._embeddedApp;
			if (oldApp === newApp) {
				return;
			}

			if (oldApp) {
				// 기존 앱이 존재하고 앱이 변경된 경우, ready로 예약된 작업을 모두 취소.
				this._clearReadyListeners();
			}

			this._embeddedApp = newApp;
			if (this._getRenderer() && this._getRenderer().hasDrawn()) {
				// 랜더링 도중 App 이 변경된 경우.
				if (core.DeferredUpdateManager.INSTANCE._isRendering()) {
					let oldInstance = this._embeddedAppInstance;
					this._embeddedAppInstance = null;
					core.DeferredUpdateManager.INSTANCE.asyncExec(() => {
						if (oldInstance) {
							oldInstance.dispose();
						}
						this.redraw();
					})
				}
				else {
					if (this._embeddedAppInstance) {
						this._embeddedAppInstance.dispose();
						this._embeddedAppInstance = null;
					}
					this.redraw();
				}
			}

			let appChangeEvent = new events.CSelectionEvent("app-change", {
				oldSelection: oldApp,
				newSelection: newApp
			});
			this.dispatchEvent(appChangeEvent)

			if (this._forceRunRequested) {
				this._ensureAppRunning();
				this._forceRunRequested = false;
			}

			this.redraw();
		}

		/**
		 * app을 반환합니다.
		 * @return embedded app.
		 */
		public get app(): cpr.core.App {
			return this._embeddedApp;
		}

		protected _getApp(): cpr.core.App {
			return this._embeddedApp;
		}

		/**
		 * Embedded App의 module을 반환합니다.
		 * @return module
		 */
		public get module(): any {
			if (this.getEmbeddedAppInstance()) {
				return this.getEmbeddedAppInstance().getModule();
			} else {
				return null;
			}
		}

		/**
		 * Embedded App Instance를 반환합니다.
		 * @return Embedded App Instance.
		 */
		public getEmbeddedAppInstance(): core.AppInstance {
			return this._embeddedAppInstance;
		}

		override _getType(): ControlType {
			return ControlType.EMBEDDEDAPP;
		}

		/**
		 * App의 property를 설정합니다.
		 * @param propertyName property 명.
		 * @param value property 값.
		 * @param fireEvent property-change 이벤트 전파 여부.
		 */
		public setAppProperty(propertyName: string, value: any, fireEvent: boolean = true) {
			if (!this._embeddedAppInstance) {
				throw new cpr.exceptions.IllegalStateException("Can't set a propery when the app is not running.");
			}
			this._embeddedAppInstance.setAppProperty(propertyName, value, fireEvent);
		}

		/**
		 * 여러 앱 속성들을 한 번에 지정합니다.
		 * @param properties 지정할 속성 JSON 객체.
		 * @param fireEvent property-change 이벤트 전파 여부.
		 */
		public setAppProperties(properties: { [key: string]: any }, fireEvent: boolean = true) {
			Object.keys(properties).forEach(key => {
				this.setAppProperty(key, properties[key], fireEvent);
			});
		}

		/**
		 * 특정 앱 속성의 값을 기본값으로 복귀시킵니다.
		 * @param propertyName 기본값으로 복귀할 앱 속성 명.
		 * @param fireEvent property-change 이벤트 전파 여부.
		 */
		public unsetAppProperty(propertyName: string, fireEvent: boolean = true) {
			if (!this._embeddedAppInstance) {
				throw new cpr.exceptions.IllegalStateException("Can't set a propery when the app is not running.");
			}
			this._embeddedAppInstance.unsetAppProperty(propertyName, fireEvent);
		}

		/**
		 * 기본값을 가진 모든 앱 속성들을 초기값 상태로 되돌립니다.
		 * declareAppProperty() 및 declareBindableAppProperty()로 선언된 모든 앱 속성들의 값을 초기 값으로 되될립니다.
		 * @param fireEvent property-change 이벤트 전파 여부.
		 */
		public unsetAllAppProperties(fireEvent: boolean = true) {
			if (!this._embeddedAppInstance) {
				throw new cpr.exceptions.IllegalStateException("Can't set a propery when the app is not running.");
			}
			this._embeddedAppInstance.unsetAllAppProperties(fireEvent);
		}

		/**
		 * App의 해당 property의 값을 반환합니다.
		 * @param propertyName property 명.
		 * @return property의 값.
		 */
		public getAppProperty(propertyName: string): any {
			if (!this._embeddedAppInstance) {
				throw new cpr.exceptions.IllegalStateException("Can't get a property value when the app is not running.");
			}
			return this._embeddedAppInstance.getAppProperty(propertyName);
		}

		/**
		 * 모든 앱 속성들을 얻습니다.
		 */
		public getAllAppProperties(): { [key: string]: any } {
			if (!this._embeddedAppInstance) {
				throw new cpr.exceptions.IllegalStateException("Can't get a property value when the app is not running.");
			}
			return this._embeddedAppInstance.getAllAppProperties();
		}

		/**
		 * 앱 속성 값을 string 형식으로 얻습니다.
		 * @param propertyName 속성 이름.
		 */
		public getAppPropertyAsString(propertyName: string): string {
			let value = this.getAppProperty(propertyName)
			if (value === null || value === undefined) {
				return value
			} else {
				return String(value)
			}
		}

		/**
		 * 앱 속성 값을 number 형식으로 얻습니다.
		 * @param propertyName 속성 이름.
		 */
		public getAppPropertyAsNumber(propertyName: string): number {
			let value = this.getAppProperty(propertyName)
			return Number(value)
		}

		/**
		 * 앱 속성 값을 boolean 형식으로 얻습니다.
		 * @param propertyName 속성 이름.
		 */
		public getAppPropertyAsBoolean(propertyName: string): boolean {
			let value = this.getAppProperty(propertyName)
			if (typeof value == "string") {
				if (value.match(/true/gi)) {
					return true
				} else {
					return false
				}
			}
			else {
				return Boolean(value)
			}
		}

		/**
		 * App의 method를 가지고 있는지에 대한 여부를 반환합니다.
		 * @param name method 명.
		 * @return method 포함 여부.
		 */
		public hasAppMethod(name: string): boolean {
			if (!this._embeddedAppInstance) {
				return false;
			}
			return this._embeddedAppInstance.hasAppMethod(name);
		}

		/**
		 * App의 method를 호출합니다.
		 * @param name method 명
		 * @param args method 내 파라미터.
		 * @return string|object|number|undefined 호출한 메소드의 결과 반환하며, 반환이 없는 경우 undefined를 반환합니다.
		 */
		public callAppMethod(name: string, ...args: any[]): any {
			if (!this._embeddedAppInstance) {
				throw new cpr.exceptions.IllegalStateException();
			}
			if (!args) {
				args = [];
			}
			args.splice(0, 0, name);
			return this._embeddedAppInstance["callAppMethod"].apply(this._embeddedAppInstance, args);
		}

		/**
		 * 임베딩 된 앱이 준비된 후에 처리할 작업을 등록합니다.
		 * 앱이 이미 실행중인 경우, 곧바로 수행 되며, 앱이 실행중이지 않은 경우, 앱이 준비되어 실행되기 직전에 호출됩니다.
		 * 이 작업이 실행되기전 app이 변경되면, 작업들이 취소됩니다.
		 * 
		 * @param handler 앱이 준비된 후 처리할 작업을 담은 함수.
		 */
		public ready(handler?: (app: EmbeddedApp) => void): Promise<EmbeddedApp> {
			let instance = this.getEmbeddedAppInstance();
			if (instance) {
				if (handler)
					handler(this);
				return Promise.resolve(this);
			}
			else {
				return new Promise<EmbeddedApp>((resolve, reject) => {
					let readyHandler = () => {
						if (handler) {
							handler(this);
						}
						resolve(this);
						if (this._readyListeners) {
							let idx = this._readyListeners.indexOf(readyHandler);
							if (idx !== -1) {
								this._readyListeners.splice(idx, 1);
							}
						}
					}
					this._addReadyListener(readyHandler);
				});
			}
		}

		private _addReadyListener(listener: (e: events.CEvent) => void) {
			this._readyListeners[this._readyListeners.length] = listener;
			this.addEventListenerOnce("app-ready", listener);
		}

		/**
		 * ready 함수로 등록된 대기 태스크들을 모두 제거합니다.
		 */
		private _clearReadyListeners() {
			this._readyListeners.forEach(each => {
				this.removeEventListener("app-ready", each)
			});
			this._readyListeners = [];
		}

		/**
		 * 컨트롤에 포함되어있는 객체들을 제거합니다.
		 */
		dispose(): void {
			this._clearReadyListeners();

			if (this._embeddedAppInstance) {
				this._embeddedAppInstance.dispose();
				this._embeddedAppInstance = null;
			}
			let parent: Container = this.getParent();
			if (parent) {
				parent.removeChild(this, false);
			}
			super.dispose();
		}

		_getAutoSizeAvailability(): layouts.AutoSizeType {
			if (this.app == null || this._embeddedAppInstance == null || this._embeddedAppInstance.getContainer() == null) {
				return layouts.AutoSizeType.none;
			}
			else {
				return this._embeddedAppInstance.getContainer()._getAutoSizeAvailability();
			}
		}

		_onAdapt(newHostAppInstance: core.AppInstance) {
			super._onAdapt(newHostAppInstance);
			let innerAppInstance = this.getEmbeddedAppInstance();
			if (innerAppInstance) {
				let event = new events.CEvent("host-change");
				innerAppInstance.dispatchEvent(event);
			}
		}

		_onOrphan(oldAppInstance: core.AppInstance) {
			super._onOrphan(oldAppInstance);
			let innerAppInstance = this.getEmbeddedAppInstance();
			if (innerAppInstance) {
				let event = new events.CEvent("host-change");
				innerAppInstance.dispatchEvent(event);
			}
		}
	}
}