

namespace cpr.utils {
	/**
	 * EntrySet의 인터페이스 객체. {key: string, value: any }
	 */
	export interface Entry<ValueType> {
		/**
		 * key
		 */
		key: string,
		/**
		 * value
		 */
		value: ValueType
	}
	/**
	 * Object 타입으로 {'key' : "키 이름",'value': "값" }를 관리하는 클래스.
	 */
	export class EntrySet<ValueType> {
		private _entries: cpr.utils.Entry<ValueType>[];


		constructor() {
			this._entries = [];
		}

		/**
		 * 리스트에 값을 넣습니다. Object 타입으로  {'key' : "키 이름",'value': "값" }
		 */
		public push(obj: cpr.utils.Entry<ValueType>): void {
			this._entries.push(obj);
		}

		/**
		 * object 타입을 일괄적으로 넣습니다.
		 */
		public putAll(obj: { [key: string]: any }): void {
			for (let key in obj) {
				let entry: cpr.utils.Entry<ValueType> = {
					key: key, value: obj[key]
				};
				this._entries.push(entry);
			}
		}
		/**
		 * 리스트에 키와 값의 객체를 제거하고 반환합니다.
		 * 
		 */
		public pop(): cpr.utils.Entry<ValueType> {
			let result: cpr.utils.Entry<ValueType> = this._entries.pop();

			return result;
		}

		/**
		 * 해당 인덱스의 {'key':key ,'value':value} 객체로 반환합니다.
		 */
		public get(index: number): cpr.utils.Entry<ValueType> {
			if (this._inRange(index) == true) {
				let entry: cpr.utils.Entry<ValueType> = this._entries[index];
				return entry;
			}
			return null;
		}

		/**
		 * 인덱스에 해당되는 아이템을 제거합니다.
		 */
		public removeByIndex(index: number): boolean {
			if (this._inRange(index) == true) {
				this._entries.splice(index, 1);
				return true;
			}
			return false;
		}

		/**
		 * 키 값에 해당되는 인덱스의 객체를 모두 제거합니다.
		 */
		public remove(key: string): void {
			let newEntries: cpr.utils.Entry<ValueType>[] = this._entries.filter((entry: cpr.utils.Entry<ValueType>) => {
				return entry.key == key ? false : true;

			});
			this._entries = newEntries;
		}

		/**
		 * 리스트의 데이터를 정리합니다.
		 */
		public clear(): void {
			if (this._entries.length > 0) {
				this._entries.splice(0, this._entries.length);
			}
		}

		/**
		 * 해당 키의 인덱스를 반환합니다.
		 */
		public getIndices(key: string): number[] {
			let indices: number[] = [];
			this._entries.forEach((entry: cpr.utils.Entry<ValueType>, index: number) => {
				if (entry.key == key) {
					indices.push(index);
				}
			});

			return indices;
		}

		/**
		 * 키 값들을 반환합니다.
		 */
		public getKeys(): string[] {
			let keys: string[] = [];
			this._entries.forEach((entry: cpr.utils.Entry<ValueType>) => {
				if (keys.indexOf(entry.key) == -1) {
					keys.push(entry.key);
				}
			});

			return keys;
		}

		/**
		 * 키 값에 해당되는 값들을 배열로 반환합니다.
		 */
		public getValues(key: string): any[] {
			let values: any[] = [];
			this._entries.forEach((entry: cpr.utils.Entry<ValueType>) => {
				if (entry.key == key) {
					values.push(entry.value);
				}
			});

			return values;
		}

		/**
		 * 키 값이 있는지 여부를 반환합니다.
		 */
		public hasOwnKey(key: string): boolean {
			for (let idx: number = 0; idx < this._entries.length; idx++) {
				let entry: cpr.utils.Entry<ValueType> = this._entries[idx];
				if (entry.key == key) {
					return true;
				}
			}
			return false;
		}

		/**
		 * 키와 값의 분리자의 페어의 분리자를 텍스트로 합쳐 반환합니다.
		 */
		public join(sep1: string, sep2: string): string {
			let entryText: string[] = [];
			this._entries.forEach((entry: cpr.utils.Entry<ValueType>, index: number) => {
				entryText.push(entry.key + sep1 + entry.value);
			});
			return entryText.join(sep2);
		}

		/**
		 * 리스트의 크기를 반환합니다.
		 * @public
		 */
		public size(): number {
			return this._entries.length;
		}

		/**
		 * 인덱스에 해당되는 key를 가져옵니다.
		 * @public
		 */
		public key(index: number): string {
			if (this._inRange(index) == true) {
				let entry: cpr.utils.Entry<ValueType> = this._entries[index];
				return entry.key;
			}
			return null;
		}

		/**
		 * 인덱스에 해당되는 value를 가져옵니다.
		 * @public
		 */
		public value(index: number): ValueType {
			if (this._inRange(index) == true) {
				let entry: cpr.utils.Entry<ValueType> = this._entries[index];
				return entry.value;
			}
			return null;
		}

		/**
		 * 입력된 EntrySet과 병합합니다.
		 * @param entrySet 
		 */
		public concat(entrySet: EntrySet<ValueType>): EntrySet<ValueType> {
			let newEntrySet: EntrySet<ValueType> = new EntrySet<ValueType>();
			newEntrySet._entries = this._entries.concat(entrySet._entries);
			return newEntrySet;
		}

		private _inRange(index: number): boolean {
			return index < this._entries.length;

		}
	}

}