/// <reference path="../expression/ExpressionEngine.ts" />

namespace cpr {

	interface MessageDataNode {
		[key: string]: string | MessageDataNode
	}

	class Merging {
		private _destination: MessageDataNode;

		constructor(target: MessageDataNode) {
			this._destination = target;
		}

		public _mergeFrom(src: MessageDataNode) {
			this._write(src, this._destination);
		}

		private _write(src: MessageDataNode, destination: MessageDataNode) {
			Object.keys(src).forEach(key => {
				let value = src[key];
				if (typeof value == "string") {
					destination[key] = value;
				}
				else if (typeof value == "object") {
					let child = value as MessageDataNode
					if (typeof destination[key] != "object") {
						destination[key] = {};
					}
					this._write(child, destination[key] as MessageDataNode);
				}
			});
		}
	}

	function _backwardValueForKeyPath(ctx: any, keypath: string[]): any {
		if (typeof ctx != "object" && keypath.length > 0) {
			return null;
		}
		let finger = ctx;
		let segments = keypath.slice();
		while (finger != null && segments.length > 0) {
			let key = segments.join(".");
			let test = finger[key];
			if (test != null) {
				let nextSegment = keypath.slice(segments.length);
				if (nextSegment.length === 0 && typeof test != "object") {
					return test;
				} else {
					let value = _backwardValueForKeyPath(test, nextSegment);
					if (value != null) {
						return value;
					}
				}
			}
			segments.pop();
		}
		return null;
	}

	function valueForKeyPath(ctx: any, keypath: string, fallback: string = null) {
		let segments = keypath.split(".");
		let finger = ctx;
		let result = _backwardValueForKeyPath(finger, segments);
		return result ?? fallback;
	}

	/**
	 * i18n
	 * 다국어 지원.
	 * @noinstance
	 */
	export class I18N {
		private static _INSTANCE: I18N;

		private _parent: I18N;
		private _data: MessageDataNode = {};
		private _currentLanguage: string;
		private _returnKeyInsteadOfMessage: boolean = null;

		/**
		 * @param parent 
		 * @private
		 */
		constructor(parent: I18N = null) {
			this._parent = parent;
		}

		public static get INSTANCE(): I18N {
			if (!this._INSTANCE) {
				let platformI18N = new I18N();

				let data = cpr.core.PlatformTerms._getData();
				Object.keys(data).forEach(lang => {
					let eachData = data[lang];
					platformI18N.setLocaleData(lang, eachData);
				})

				this._INSTANCE = new I18N(platformI18N);
			}
			return this._INSTANCE;
		}

		private _getReturnKeyInsteadOfMessage(): boolean {
			if (this._returnKeyInsteadOfMessage === null) {
				let appConf: core.AppConfig = core.AppConfig.INSTANCE;
				let i18nConf: core.Config = appConf.getEnvConfig();
				if (i18nConf) {
					this._returnKeyInsteadOfMessage = Boolean(i18nConf.getValue("useKeyInsteadOfNullI18NMessage", false));
				} else {
					this._returnKeyInsteadOfMessage = false;
				}
			}
			return this._returnKeyInsteadOfMessage;
		}

		/**
		 * 현재 locale를 반환합니다.
		 * @return locale.
		 */
		get currentLanguage(): string {
			if (this._currentLanguage) {
				return this._currentLanguage
			}
			this._currentLanguage = this._detectBaseLanguage()
			return this._currentLanguage
		}

		/**
		 * 현재 locale를 설정합니다.
		 * @param newLanguage locale.
		 */
		set currentLanguage(newLanguage: string) {
			if (this.isSupportedLanguage(newLanguage) === false) {
				return
			}

			this._currentLanguage = newLanguage

			// 랭귀지 변경 사실 통보.
			cpr.core.NotificationCenter.INSTANCE.post(core.SystemTopics.LANGUAGE_DID_CHANGE, newLanguage, this)
		}

		_detectBaseLanguage(): string {
			let browserLanguage = this.getBrowserLanguage()

			// 브라우저 언어가 지원되는 경우.
			if (this.isSupportedLanguage(browserLanguage)) {
				return browserLanguage
			}

			// 브라우저가 지원되지 않는 경우.
			else {
				return Object.keys(this._data)[0]
			}
		}

		/**
		 * 브라우저가 지원하는 언어를 반환합니다.
		 * @return 브라우저가 지원하는 언어.
		 */
		getBrowserLanguage(): string {
			let exp = (navigator.language || navigator["userLanguage"]) as string
			let langCode = exp.split(/[_-]/g)[0].toLocaleLowerCase()
			return langCode
		}

		/**
		 * 해당 locale의 지원 여부를 반환합니다.
		 * @param langCode locale
		 * @return 지원 여부.
		 */
		isSupportedLanguage(langCode: string): boolean {
			if (!langCode) {
				return false
			}
			return this._data[langCode] != null
		}

		/**
		 * 해당 locale의 data를 설정합니다.
		 * @param langCode locale
		 * @param data locale의 data. { key: message }
		 */
		setLocaleData(langCode: string, data: {}): void {
			this._data[langCode] = data

			let currentLanguage = this._currentLanguage || this._detectBaseLanguage()
			if (langCode == currentLanguage) {
				// 랭귀지 변경 사실 통보.
				cpr.core.NotificationCenter.INSTANCE.post(core.SystemTopics.LANGUAGE_DID_CHANGE, langCode, this)
			}
		}

		/**
		 * 특정 언어의 데이터를 머징 합니다.
		 * @param langCode 추가할 데이터의 언어 코드.
		 * @param data  추가할 언어 데이터.
		 */
		mergeLocaleData(langCode: string, data: {}): void {
			this._data[langCode] = this._data[langCode] || {}
			let target = this._data[langCode] as MessageDataNode;
			new Merging(target)._mergeFrom(data);
			let currentLanguage = this._currentLanguage || this._detectBaseLanguage()
			if (langCode == currentLanguage) {
				// 랭귀지 변경 사실 통보.
				cpr.core.NotificationCenter.INSTANCE.post(core.SystemTopics.LANGUAGE_DID_CHANGE, langCode, this)
			}
		}

		/**
		 * 언어 데이터 노드를 얻습니다.
		 * @param langCode 데이터를 얻을 언어 코드.
		 */
		getLocaleData(langCode?: string): { [key: string]: any } {
			langCode = langCode || this.currentLanguage;
			return this._data[langCode] as any as { [key: string]: any };
		}

		/**
		 * 현재 언어에 맞는 key에 대한 message를 반환합니다.
		 * @param key 다국어 키
		 */
		message(key: string): string
		/**
		 * 현재 언어에 맞는 key에 대한 message를 반환합니다. 치환하는 값이 1개에 대해 문자열을 치환하여 출력합니다.
		 * @param key 다국어 키
		 * @param value 다국어 변수 치환 값
		 */
		message(key: string, value: string): string
		/**
		 * 현재 언어에 맞는 key에 대한 message를 반환합니다. 다국어에서 ${name}으로 지정된 문자열을 치환하여 출력합니다.
		 * @param key 다국어 키
		 * @param locals 다국어 변수 치환 값들
		 */
		message(key: string, locals: { [key: string]: string }): string

		message(key: string, valueOrLocals?: string | { [key: string]: string }): string {
			let template = this._getTemplate(key);
			let messageStr: string = null;

			switch (typeof valueOrLocals) {
				case "object": {
					messageStr = _.template(template, { interpolate: /\$\{(.+?)\}/g, })(valueOrLocals);
					break;
				}
				case "undefined": {
					messageStr = template;
					break;
				}
				default: {
					messageStr = template.replace(/\$\{.*\}/g, valueOrLocals);
				}
			}
			if (this._getReturnKeyInsteadOfMessage() === true) {
				if (messageStr == null) {
					messageStr = key;
				}
			}

			return messageStr;
		}

		private _getTemplate(key: string): string {
			let langNode = this._data[this.currentLanguage]
			let template = valueForKeyPath(langNode, key) as string
			if (template == null && this._parent) {
				// 시스템 로케일이 현재 언어를 지원하는 경우.
				if (this._parent.isSupportedLanguage(this.currentLanguage)) {
					let parentLangNode = this._parent._data[this.currentLanguage]
					template = valueForKeyPath(parentLangNode, key) as string
				}
				// 시스템 로케일이 현재 언어를 지원하지 않는 경우.
				else {
					template = this._parent._getTemplate(key)
				}
			}
			return template;
		}
	}

}