namespace cpr.ufc {

	/**
	 * {@link ElementShape.children} 에 포함될 수 있는 콘텐츠.
	 */
	export type ElementShapeContent = string | ElementShape | ControlRenderer | DrawLazyTask | TapLazyTask;
	/**
	 * ElementShape인지 확인하는 함수.
	 * @param element 
	 * @returns 
	 */
	export function _isElementShape(element: any) {
		if (!element) return false;
		return typeof element === "object" && (element instanceof ControlRenderer || element instanceof DrawLazyTask || element instanceof TapLazyTask) == false;
	}
	/**
	 * UIControl의 HTML 구조를 정의하는 인터페이스.
	 * @private
	 */
	export interface ElementShape {
		/**
		 * 본 Shape을 정의한 UIControl의 인스턴스.
		 * 예) owner : this
		 */
		owner?: core.DrawableControl; /* Instance of UIControl : TODO Removal */

		/**
		 * HTML Tag로 lower case로 기술.
		 * 예) tag : "div"
		 */
		tag?: string;

		/**
		 * 특정 노드의 이름을 지정하여 컨트롤이 그려진 이후 지정된 노드의 이름으로 DOMElement에 접근할 수 있음.
		 * @see cpr.ufc.ControlRenderer#getNamedNode
		 */
		nodename?: node_name;

		/**
		 * 적용할 Styler의 이름 지정
		 */
		styler?: string;
		/**
		 * 최종 UIShape에 반영된 ClassNames : OldShape에서 갱신용으로 사용
		 * TODO uiShape으로 이관 검토
		 */
		shapeClassNames?: string[];
		/**
		 * 최종 UIShape에 반영된 CSS Style : OldShape에서 갱신용으로 사용
		 * TODO uiShape으로 이관 검토
		 */
		shapeCssText?: string;

		/**
		 * 본 Tag에 부여할 css class name.
		 * 각각의 class를 요소로 가지는 string array로 기술.
		 * 예) className : ["className1", "className2"]
		 */
		classNames?: css_class_string[];

		/**
		 * 본 Tag가 가지는 attribute 속성을 정의.
		 * key, value 값을 가지는 map 형태로 정의되며 key와 value는 string으로 정의.
		 * 예) attr : {"data-code" : "code", "data-label" : "label"}
		 */
		attr?: { [key: string]: string };

		/**
		 * Input 계열의 값을 설정해 주기 위한 속성
		 */
		value?: string;

		/**
		 * 본 Tag가 가지는 style 속성을 정의.
		 * key, value 값을 가지는 map 형태로 정의되며 key와 value는 string으로 정의.
		 * HTMLElement에서 허용하는 스타일이 아닌 경우 무시된다.
		 * 예) style : {backgroundColor : "black", margin : "0"}
		 */
		style?: { [key: string]: string };

		/**
		 * 본 Tag가 Listening할 Transient Event를 선언.
		 * 여기에 선언된 Event는 EventSystem에 의해 Control Event로 출판되며, Control에 등록된 Listener가 Dispatch 된다.
		 * 현재 등록가능한 이벤트는 "mouse", "key" 이다.
		 * 예) eventTarget : ["key"]
		 */
		eventTargets?: EventTargetType[]; /* generic event target {mouse|key} */

		/**
		 * UIControl 자체 처리할 HTML Event를 등록.
		 * Handler는 string으로 UIControl의 EventHandler Method 명칭을 기술한다.
		 * UIControl Event Handler Method는 브라우저 Event 클래스 하위 클래스의 인스턴스를 인자로 가져야 한다.
		 * HTMLElement에서 허용하는 Event가 아닌 경우 무시된다.
		 * 예) events: {	click: "onClick" }
		 * 
		 * UIControl 내부 구현 예
		 * <pre><code>
		 * public onClick(e: MouseEvent): void {
		 * ...
		 * }
		 * </code></pre>
		 */
		events?: {
			[key: string]: (string | string[] | Function | Function[])
		};

		/**
		 * UIControl의 _checkControlStateForEvent 를 체크하지 않고
		 * disposed 여부만 체크하여 실행하는 이벤트 핸들러
		 */
		mandatoryEvents?: {
			[key: string]: (string | string[] | Function | Function[])
		};

		/**
		 * EventBus에 attach 된 EventMap
		 */
		_eventMap?: { [eventType: string]: (e: events.CEvent) => void };

		/**
		 * 본 Tag의 하위 Tag를 구성.
		 * 하위 Tag는 string, ControlShape, ControlRenderer가 정의될 수 있다.
		 * UIControl 자체 구성상 하위 Tag가 필요한 경우 ControlShape으로 정의하고
		 * ControlShape을 구성하는 UIControl이 다른 UIControl을 포함하는 경우 포함되는 UIControl의 ControlRenderer를 설정한다.
		 * 
		 * 예) children : ["개요", this._childUIControl.getRenderer()]
		 */
		children?: ElementShapeContent[];
		innerHTML?: string;

		/**
		 * VirtualDOM의 DOM Update 기능을 이용하기 위한 MappingKey
		 */
		key?: string;

		// stylerBindContext?: bind.BindContext;

		/**
		 * SVG를 지원하기 위한 Namespace 필드
		 */
		namespace?: string;

		aria?: string;
		ariaItemUUID?: string;
		// ariaBindContext?: bind.BindContext;

		bindContext?: bind.BindContext; // bindContext 일원화
	}

	/**
	 * UIControl의 HTML 구조를 정의하는 인터페이스.
	 * @private
	 */
	export interface ControlShape extends ElementShape {
		aside?: ElementShape; /* parent control의 aside 영역에 생성될 객체 */
		global?: ElementShape | ControlRenderer; /* document.body 영역에 생성될 객체 */
	}

}