/// <reference path="../../utils/Util.ts" />


namespace cpr.controls.gridpart {

	/* NEW GridLayout */
	/**
	 * @private
	 */
	export interface GridLayout {
		columnLayout: GridColumnProp[],
		header: GridHeaderBandConfig,
		detail: GridDetailBandConfig,
		footer?: GridFooterBandConfig,
		rowGroup?: GridRowGroupConfig[]
	}

	/**
	 * 컬럼 레이아웃 정보.
	 */
	export interface GridColumnProp {
		/**
		 * 컬럼의 너비. (px)
		 */
		width: number,
		/**
		 * 그려질 때마다 갱신되는 실제 그려진 너비. (px)
		 * @private
		 */
		renderedWidth?: number,
		/**
		 * 컬럼 visible 여부.
		 * runtime only
		 * @private
		 */
		visible?: boolean,
		/**
		 * 컬럼 크기 조절 여부.
		 * columnIndex 설정시 runtime only
		 */
		resizable?: boolean,
		/**
		 * autofit 사용 여부
		 * columnIndex 설정시 runtime only
		 */
		autoFit?: boolean
	}

	// export interface GridRowProp {
	// 	/**
	// 	 * 행의 높이. (px)
	// 	 */
	// 	height: number
	// }

	/**
	 * 셀 내부 컨트롤의 constraint 설정.
	 */
	export interface ControlConstraint {
		/**
		 * 셀 내 세로 정렬 방법
		 */
		verticalAlign?: layouts.FormVerticalAlign,
		/**
		 * 셀 내 가로 정렬 방법
		 */
		horizontalAlign?: layouts.FormHorizontalAlign,
		/**
		 * 가로 크기. 가로 정렬방법이 가득 채우기인 경우 무시 됩니다.
		 */
		width?: string,
		/**
		 * 세로 크기. 세로 정렬 방법이 가득 채우기인 경우 무시 됩니다.
		 */
		height?: string
		/**
		 * 컨트롤 상단 간격.
		 */
		topSpacing?: number, // number형, string형 모두 입력 가능.
		/**
		 * 컨트롤 우측 간격.
		 */
		rightSpacing?: number, // number형, string형 모두 입력 가능.
		/**
		 * 컨트롤 하단 간격.
		 */
		bottomSpacing?: number, // number형, string형 모두 입력 가능.
		/**
		 * 컨트롤 좌측 간격.
		 */
		leftSpacing?: number // number형, string형 모두 입력 가능.
	}

	export interface GridCellConstraint {//extends ControlConstraint {
		/**
		 * 행 확장 사이즈.
		 */
		rowSpan?: number,
		/**
		 * 열 확장 사이즈.
		 */
		colSpan?: number,
		/**
		 * 행 인덱스. (0 base)
		 */
		rowIndex: number,
		/**
		 * 열 인덱스. (0 base)
		 */
		colIndex: number,
		/**
		 * 셀 인덱스.
		 * 행, 열 순서대로 인덱스가 부여됩니다.
		 * runtime only
		 */
		cellIndex?: number,
		/**
		 * runtime only
		 */
		ariaColIndex?: number,
		/**
		 * runtime only
		 */
		regionColIndex?: number
	}

	/**
	 * @private
	 */
	interface GridCellRuntimeAttr {
		/**
		 * fieldLabel에 설정한 값만 aria-label로 적용되도록 하는 runtime 내부 속성
		 */
		fieldLabelOnly?: boolean,
		/**
		 * ignoreDefaultFieldLabel 속성을 지원할 지 여부
		 */
		supportFieldLabelOnly?: boolean
	}

	/**
	 * cell의 설정 정보.
	 */
	export interface GridCellProp {
		constraint: GridCellConstraint,
		configurator?: (configurator: config.GridCellConfigurator) => void,
		/**
		 * runtime only
		 * @private
		 */
		configuration?: config.GridCellConfigurator,
		/**
		 * runtime only
		 * @private
		 */
		cellRenderer?: renderer.IGridCellRenderer,
		/**
		 * runtime only
		 * @private
		 */
		_runtimeAttr?: GridCellRuntimeAttr
	}

	/**
	 * @private
	 */
	export interface GridHeaderCellProp extends GridCellProp {
		configurator?: (configurator: config.GridHeaderCellConfigurator) => void,
		/**
		 * runtime only
		 * @private
		 */
		configuration?: config.GridHeaderCellConfigurator,
		/**
		 * runtime only
		 * @private
		 */
		cellRenderer?: renderer.EmbeddedHeaderCellRenderer
	}

	export interface GridDetailCellProp extends GridCellProp {
		configurator?: (configurator: config.GridDetailCellConfigurator) => void,
		/**
		 * runtime only
		 * @private
		 */
		configuration?: config.GridDetailCellConfigurator,
	}

	/**
	 * @private
	 */
	export interface GridFooterCellProp extends GridCellProp {
		configurator?: (configurator: config.GridFooterCellConfigurator) => void,
		/**
		 * runtime only
		 * @private
		 */
		configuration?: config.GridFooterCellConfigurator,
	}

	/**
	 * @private
	 */
	export interface GridGroupHeaderCellProp extends GridCellProp {
		configurator?: (configurator: config.GridGroupHeaderCellConfigurator) => void,
		/**
		 * runtime only
		 * @private
		 */
		configuration?: config.GridGroupHeaderCellConfigurator,
	}

	/**
	 * @private
	 */
	export interface GridBandConfig {
		rows: { rowIndex: number, height: number }[],
		rowHeight?: number,
		cellProp: GridCellProp[],
		bandStyler: GridStyler
		// style: CSSStyle
	}

	/**
	 * @private
	 */
	export interface GridHeaderBandConfig extends GridBandConfig {
		cellProp: GridHeaderCellProp[]
	}

	/**
	 * @private
	 */
	export interface GridDetailBandConfig extends GridBandConfig {
		cellProp: GridDetailCellProp[]
	}

	/**
	 * @private
	 */
	export interface GridFooterBandConfig extends GridBandConfig {
		visible: boolean,
		cellProp: GridFooterCellProp[]
	}

	/**
	 * @private
	 */
	export interface GridRowGroupBandConfig extends GridBandConfig {
		// visible: boolean,
		visibleExpr?: expression.Expression,
		cellProp: GridFooterCellProp[]
	}

	/**
	 * @private
	 */
	export interface GridRegionLayout extends GridBandConfig {
		visible?: boolean,
		columnLayout: GridColumnProp[]
	}

	/**
	 * @private
	 */
	export interface GridRowGroupConfig {
		groupCondition: string,
		activate: boolean,
		startCollapse?: boolean,
		collapseIndex?: number,
		gheader?: GridRowGroupBandConfig,
		gfooter?: GridRowGroupBandConfig
	}

	/**
	 * @private
	 */
	export interface GridRowGroupRendererConfig {
		[groupCondition: string]: {
			gheader?: gridpart.renderer.GridRowGroupRenderer,
			gfooter?: gridpart.renderer.GridRowGroupRenderer
		}
	}

	/**
	 * 그리드 레이아웃.
	 * setColumnLayout, getColumnLayout 에서 사용
	 * 컬럼순서, visible, size, 위치정보 반환.
	 */
	export interface GridColumnLayout {
		/**
		 * 컬럼 레이아웃
		 */
		columnLayout: { width: number, resizable?: boolean, autoFit?: boolean, visible?: boolean }[],
		/**
		 * 헤더 정보
		 */
		header: { cellIndex: number, rowIndex: number, colIndex: number, rowSpan?: number, colSpan?: number, visible: boolean }[],
		/**
		 * 디테일 정보
		 */
		detail: { cellIndex: number, rowIndex: number, colIndex: number, rowSpan?: number, colSpan?: number }[],
		/**
		 * 푸터 정보
		 */
		footer?: { cellIndex: number, rowIndex: number, colIndex: number, rowSpan?: number, colSpan?: number }[],
		/**
		 * 행그룹 정보
		 */
		rowGroup?: {
			groupCondition: string,
			gheader?: { cellIndex: number, rowIndex: number, colIndex: number, rowSpan?: number, colSpan?: number }[],
			gfooter?: { cellIndex: number, rowIndex: number, colIndex: number, rowSpan?: number, colSpan?: number }[]
		}[]
	}
}