namespace cpr.vdom {
	/**
	 * is-thunk.js
	 * @private
	 * @param t 
	 * @returns 
	 */
	export function _isThunk(t: VTreeElement): t is Thunk {
		return t && t.type === "Thunk"
	}

	/**
	 * is-hook.js
	 * @private
	 * @param value 
	 * @returns 
	 */
	export function _isHook(value: any): value is VHook {
		return value && (typeof value.hook === "function" && !value.hasOwnProperty("hook") || typeof value.unhook === "function" && !value.hasOwnProperty("unhook"))
	}

	/**
	 * is-vnode.js
	 * @private
	 * @param x 
	 * @returns 
	 */
	export function _isVNode(x: VTreeElement): x is VNode {
		return x && x.type === "VirtualNode";
	}

	/**
	 * is-vtext.js
	 * @private
	 * @param x 
	 * @returns 
	 */
	export function _isVText(x: VTreeElement): x is VText {
		return x && x.type === "VirtualText";
	}

	/**
	 * 
	 * @private
	 * @param w 
	 * @returns 
	 */
	export function _isWidget(w: VTreeElement): w is Widget {
		return w && w.type === "Widget"
	}

	export function _isVTreeElement(x: any): x is VTreeElement {
		return _isVNode(x) || _isVText(x) || _isWidget(x) || _isThunk(x);
	}
}