/// <reference path="./AbstractDateMask.ts" />
namespace cpr.foundation {

	/**
	 * DateTextMask
	 * `____-__-__` 형태의 가이드라인을 제공하는 마스크 입력 엔진.
	 * `DateInput.inputVariant = 'masked'` 일 때 사용됩니다.
	 * 키보드 타이핑에 최적화되어 있으며, 구분자를 자동으로 건너뜁니다.
	 * @private
	 */
	export class DateTextMask extends AbstractDateMask {

		private _maskOwner: DateMaskOwner;
		private _getValueFormat: () => string;
		private _getDisplayFormat: () => string;
		private _getInputElement: () => HTMLInputElement;
		private _listeners: { [type: string]: Function[] } = {};

		/** 마지막으로 파싱된 포맷 문자열 */
		private _lastFormat: string = null;
		/** 마지막으로 파싱된 로캘 문자열 */
		private _lastLocale: string = null;
		/**
		 * 토큰화된 포맷 정보.
		 * type: 'editable' (Y/M/D/H/h/m/s/S), 'display' (ddd/A/a 등 자동계산), 'separator' (구분자)
		 */
		private _tokens: Array<{ token: string, type: string, displayStart: number, displayLen: number }> = [];
		/**
		 * 마스크 표시 문자열의 각 위치별 문자.
		 * editable 위치: 세그먼트 유형 문자 (Y/M/D 등)
		 * display-only 위치: '\0' (null char, 런타임에 moment 값으로 교체)
		 * separator 위치: 리터럴 문자
		 */
		private _formatChars: string[] = [];
		/** 숫자를 입력하는 위치들의 인덱스 (표시 문자열 기준) */
		private _digitIndices: number[] = [];
		/** 각 숫자 위치의 세그먼트 유형 (Y/M/D/H/h/m/s/S) */
		private _segmentTypes: string[] = [];

		/** 현재 입력된 숫자 버퍼 (숫자 위치별로 하나의 문자, 미입력 시 maskCharacter) */
		private _digitBuffer: string[] = [];

		/** h(12시간) 포맷 사용 시 오전/오후 상태 저장 (스핀으로 변경되지 않음) */
		private _storedMeridiemIndex: number = 0;
		private _mouseDownFlag: boolean = false;
		private _isFirstAutoSelect: boolean = false;
		private _lastSpinMoment: moment.Moment = null;
		private _spinPrepared: boolean = false;

		/** 스핀 여부 (DateMask 호환용, 항상 false) */
		private _spinning: boolean = false;
		/** 드롭 데이터 임시 저장 객체 */
		private _input: InputObject = null;
		/** 드롭 동작 직후의 포커스 우회 플래그 */
		private _dropFocusFlag: boolean = false;
		private _lastSelectionStart: number = null;
		private _lastInputSegmentCompleted: boolean = true;
		/**
		 * 이번 입력으로 autoSkip을 실행해도 되는지 여부. release-test-project#11071
		 */
		private _autoSkipAllowed: boolean = false;
		/**
		 * 이미 완성된 값을 편집하는 중인지 여부.
		 *
		 * 선택 영역을 비우고 입력하면 두 번째 키부터는 값이 미완성으로 보이므로, 키 하나가 아니라
		 * 편집이 끝날 때까지 상태를 유지한다. 포커스 진입·이탈, 전체 선택 입력으로 해제된다.
		 * release-test-project#11071
		 */
		private _editingCompletedValue: boolean = false;

		/**
		 * DateTextMask 를 생성합니다.
		 * @param owner DateInput 인스턴스
		 * @param config 설정
		 */
		constructor(owner: DateMaskOwner, delegate: DateMaskDelegate) {
			super();
			this._maskOwner = owner;
			this._initSelectionToken("datetextmask-selection");
			this._getValueFormat = delegate.format;
			this._getDisplayFormat = delegate.displayFormat;
			this._getInputElement = delegate.getInputElement;
		}

		protected get _owner(): DateMaskOwner {
			return this._maskOwner;
		}

		public get spinning(): boolean {
			return this._spinning;
		}

		public set spinning(spinning: boolean) {
			this._spinning = spinning;
			if (spinning == false) {
				this._spinPrepared = false;
			}
		}

		/**
		 * 미입력 자리에 표시할 문자를 반환합니다.
		 */
		private _getPlaceholderChar(): string {
			let placeholderChar = this._maskCharacter;
			if (typeof placeholderChar != "string" || placeholderChar.length != 1) {
				return "_";
			}
			return placeholderChar;
		}

		/**
		 * 버퍼 값이 미입력 자리인지 여부를 반환합니다.
		 */
		private _isEmptyChar(ch: string): boolean {
			return ch === this._getPlaceholderChar();
		}

		/**
		 * 마스크 입력 방식에서 date-variant 타입(Y/M/D/H/h/k/m/s/S)에 해당하는 글자 여부를 반환합니다.
		 */
		private _isDateSegChar(ch: string): boolean {
			return "YyMDHhkmsS".indexOf(ch) >= 0;
		}

		/**
		 * 현재 설정에 맞는 빈 버퍼를 생성합니다.
		 */
		private _createEmptyBuffer(): string[] {
			let placeholderChar = this._getPlaceholderChar();
			return this._digitIndices.map(function () { return placeholderChar; });
		}

		/**
		 * 현재 마스크 포맷을 반환합니다 (e.g. "YYYY-MM-DD").
		 */
		private _getMaskFormat(): string {
			return this._getDisplayFormat();
		}

		/**
		 * 포맷 문자열을 파싱하여 내부 상태를 초기화합니다.
		 * ALLOW_FORMAT_PATTERN 정규식으로 토큰화하여 editable/display/separator를 구분합니다.
		 * 포맷이 변경된 경우에만 재파싱합니다.
		 */
		private _ensureParsed(): void {
			let fmt = this._getMaskFormat();
			let loc = this._locale;
			if (fmt === this._lastFormat && loc === this._lastLocale) {
				return;
			}
			this._lastFormat = fmt;
			this._lastLocale = loc;

			// DateMaskFormat.ALLOW_FORMAT_PATTERN과 동일한 패턴으로 토큰화
			let ALLOW_PATTERN = "(Y{4}|Y{2}|Y)|(M{2}|M)|(D{2}|D)|(H{2}|H)|(d{4}|d{3}|d{2})|(h{2}|h)|(k{2}|k)|(m{2}|m)|(s{2}|s)|a|A|(S{3}|S{2}|S)";
			let tokenRegExp = new RegExp(ALLOW_PATTERN + "|[\\s\\S]", "g");
			let rawMatches = fmt.match(tokenRegExp) || [];

			// 연속 구분자 병합
			let mergedTokens: string[] = [];
			for (let i = 0; i < rawMatches.length; i++) {
				let t = rawMatches[i];
				let first = t.charAt(0);
				let isEditable = this._isDateSegChar(first);
				let isDisplay = !isEditable && (first === 'd' || first === 'A' || first === 'a');
				if (!isEditable && !isDisplay && mergedTokens.length > 0) {
					let prev = mergedTokens[mergedTokens.length - 1];
					let prevFirst = prev.charAt(0);
					let prevEditable = this._isDateSegChar(prevFirst);
					let prevDisplay = !prevEditable && (prevFirst === 'd' || prevFirst === 'A' || prevFirst === 'a');
					if (!prevEditable && !prevDisplay) {
						mergedTokens[mergedTokens.length - 1] += t;
						continue;
					}
				}
				mergedTokens.push(t);
			}

			// display-only 토큰 렌더링 길이 계산용 레퍼런스 moment (월요일 오전 9시)에 현재 로캘을 반영하여 생성
			let refMm = this._createMomentForMask("2000-01-03T09:00:00", "YYYY-MM-DDTHH:mm:ss", true);

			this._tokens = [];
			this._formatChars = [];
			this._digitIndices = [];
			this._segmentTypes = [];

			let displayPos = 0;
			for (let ti = 0; ti < mergedTokens.length; ti++) {
				let t = mergedTokens[ti];
				let first = t.charAt(0);
				let isEditable = this._isDateSegChar(first);
				let isDisplay = !isEditable && (first === 'd' || first === 'A' || first === 'a');

				if (isEditable) {
					// 편집 가능 세그먼트: 각 문자를 digitIndices에 등록
					let displayLen = t.length;
					for (let ci = 0; ci < t.length; ci++) {
						this._formatChars.push(first);
						this._digitIndices.push(displayPos + ci);
						this._segmentTypes.push(first);
					}
					this._tokens.push({ token: t, type: 'editable', displayStart: displayPos, displayLen: displayLen });
					displayPos += displayLen;
				} else if (isDisplay) {
					// 표시 전용 세그먼트: 요일 3자리, 오전/오후 2자리로 길이를 고정하여 로캘 변경 시 레이아웃 안정성 확보
					let displayLen: number;
					if (first === 'd') {
						displayLen = 3; // 요일 "DOW" 및 영어 약어 "Fri" 등을 완벽히 표현하기 위해 3자리 고정
					} else if (first === 'A' || first === 'a') {
						displayLen = 2; // 오전/오후 "AP" / "ap" 및 "AM" / "PM"을 표현하기 위해 2자리 고정
					} else {
						displayLen = refMm.format(t).length;
					}
					for (let ci = 0; ci < displayLen; ci++) {
						this._formatChars.push('\0'); // display-only 위치 마커
					}
					this._tokens.push({ token: t, type: 'display', displayStart: displayPos, displayLen: displayLen });
					displayPos += displayLen;
				} else {
					// 구분자: 리터럴 그대로 유지
					let displayLen = t.length;
					for (let ci = 0; ci < t.length; ci++) {
						this._formatChars.push(t.charAt(ci));
					}
					this._tokens.push({ token: t, type: 'separator', displayStart: displayPos, displayLen: displayLen });
					displayPos += displayLen;
				}
			}

			// 버퍼 크기가 달라진 경우 재초기화
			if (this._digitBuffer.length !== this._digitIndices.length) {
				this._digitBuffer = this._createEmptyBuffer();
			}
		}

		/**
		 * 현재 버퍼 상태를 마스크 표시 문자열로 반환합니다 (e.g. "2023-__-__").
		 * editable 위치는 버퍼 값으로, display-only 위치는 moment에서 계산한 값으로 채웁니다.
		 */
		public _getBufferDisplayText(): string {
			this._ensureParsed();
			let result = this._formatChars.slice();

			// 1단계: editable 위치를 버퍼 값으로 채움
			let digitIdx = 0;
			for (let i = 0; i < result.length; i++) {
				if (this._isDateSegChar(result[i])) {
					result[i] = this._digitBuffer[digitIdx++];
				}
			}

			// 2단계: display-only 토큰을 moment 계산값으로 렌더링
			let partialMm = this._parseBufferMoment();
			let displays = this.getDisplays(this._locale);
			for (let ti = 0; ti < this._tokens.length; ti++) {
				let tok = this._tokens[ti];
				if (tok.type !== 'display') {
					continue;
				}
				let rendered: string;
				if (partialMm !== null) {
					// 버퍼 완성: 실제 값 표시
					let first = tok.token.charAt(0);
					if (first === 'd') {
						// 인풋 마스크에서는 요일을 항상 영어 고정으로 렌더링 (예: "Fri")
						rendered = partialMm.clone().locale("en").format(tok.token);
					} else if (first === 'a' || first === 'A') {
						// 인풋 마스크에서는 오전/오후를 항상 영어 고정으로 렌더링 (예: "AM", "PM")
						rendered = this._formatMeridiem(tok.token, true);
					} else {
						rendered = partialMm.format(tok.token);
					}
				} else {
					// 버퍼 미완성: DOW / AP 고정 가이드라인 기호 표시
					let first = tok.token.charAt(0);
					if (first === 'd') {
						rendered = "DOW";
					} else if (first === 'A') {
						rendered = "AP";
					} else if (first === 'a') {
						rendered = "ap";
					} else {
						let text = displays ? displays[first] : null;
						rendered = text ? this._checkDisplayText(text) : tok.token;
					}
				}
				while (rendered.length < tok.displayLen) {
					rendered += ' ';
				}
				if (rendered.length > tok.displayLen) {
					rendered = rendered.substring(0, tok.displayLen);
				}
				for (let ci = 0; ci < tok.displayLen; ci++) {
					result[tok.displayStart + ci] = rendered.charAt(ci) || ' ';
				}
			}

			return result.join('');
		}

		/**
		 * 표시 위치(displayPos)에 해당하는 숫자 버퍼 인덱스를 반환합니다.
		 * 구분자 위치인 경우 -1을 반환합니다.
		 */
		private _displayPosToDigitIdx(displayPos: number): number {
			this._ensureParsed();
			for (let i = 0; i < this._digitIndices.length; i++) {
				if (this._digitIndices[i] === displayPos) {
					return i;
				}
			}
			return -1;
		}

		/**
		 * displayPos 위치 이상 중 첫 번째 숫자 버퍼 인덱스를 반환합니다.
		 * 없으면 -1을 반환합니다.
		 */
		private _findNextDigitIdx(displayPos: number): number {
			this._ensureParsed();
			for (let i = 0; i < this._digitIndices.length; i++) {
				if (this._digitIndices[i] >= displayPos) {
					return i;
				}
			}
			return -1;
		}

		/**
		 * displayPos 직전 위치의 숫자 버퍼 인덱스를 반환합니다.
		 * 없으면 -1을 반환합니다.
		 */
		private _findPrevDigitIdx(displayPos: number): number {
			this._ensureParsed();
			for (let i = this._digitIndices.length - 1; i >= 0; i--) {
				if (this._digitIndices[i] < displayPos) {
					return i;
				}
			}
			return -1;
		}

		/**
		 * 입력 엘리먼트의 값과 커서 위치를 갱신합니다.
		 */
		private _updateInputValue(input: HTMLInputElement, cursorPos?: number): void {
			let text = this._getBufferDisplayText();
			if (input.value !== text) {
				input.value = text;
			}
			if (cursorPos !== undefined) {
				input.setSelectionRange(cursorPos, cursorPos);
			}
		}

		/**
		 * 특정 숫자 위치에 입력된 숫자의 유효성을 검사합니다.
		 * 월(MM), 일(DD), 시(HH/hh), 분(mm), 초(ss) 등에 대한 범위 검사를 수행합니다.
		 * @param digit 입력된 숫자 문자
		 * @param digitIdx 숫자 버퍼 인덱스
		 */
		private _isValidDigitForPosition(digit: string, digitIdx: number): boolean {
			this._ensureParsed();
			let segType = this._segmentTypes[digitIdx];
			let d = parseInt(digit, 10);

			// 현재 세그먼트의 시작 인덱스 계산
			let segRange = this._getSegmentBufferRange(digitIdx);
			let segStart = segRange.start;
			let posInSeg = digitIdx - segStart;

			// 이전 자리 버퍼 값
			let prevBuf = posInSeg > 0 ? parseInt(this._digitBuffer[segStart + posInSeg - 1], 10) : -1;

			// 세그먼트 유형별 검사
			if (segType === 'M') {
				// 월 01-12
				if (posInSeg === 0) {
					return d <= 1;
				} else if (posInSeg === 1) {
					if (prevBuf === 0) { return d >= 1; }    // 01-09
					if (prevBuf === 1) { return d <= 2; }    // 10-12
				}
			} else if (segType === 'D') {
				// 일 01-31
				if (posInSeg === 0) {
					return d <= 3;
				} else if (posInSeg === 1) {
					if (prevBuf === 0) { return d >= 1; }    // 01-09
					if (prevBuf === 3) { return d <= 1; }    // 30-31
				}
			} else if (segType === 'H') {
				// 24시간 00-23
				if (posInSeg === 0) { return d <= 2; }
				if (posInSeg === 1 && prevBuf === 2) { return d <= 3; }
			} else if (segType === 'k') {
				// 1-24시간 01-24
				if (posInSeg === 0) { return d <= 2; }
				if (posInSeg === 1) {
					if (prevBuf === 0) { return d >= 1; }    // 01-09
					if (prevBuf === 2) { return d <= 4; }    // 20-24
				}
			} else if (segType === 'h') {
				// 12시간 01-12
				if (posInSeg === 0) { return d <= 1; }
				if (posInSeg === 1) {
					if (prevBuf === 0) { return d >= 1; }
					if (prevBuf === 1) { return d <= 2; }
				}
			} else if (segType === 'm' || segType === 's') {
				// 분/초 00-59
				if (posInSeg === 0) { return d <= 5; }
			}

			// Y, y, S 등: 모든 숫자 허용
			return true;
		}

		/**
		 * 버퍼의 현재 내용을 moment 객체로 파싱합니다.
		 * 미입력 문자가 하나라도 있으면 미완성으로 간주하여 null을 반환합니다.
		 */
		private _parseBufferMoment(): any {
			for (let i = 0; i < this._digitBuffer.length; i++) {
				if (this._isEmptyChar(this._digitBuffer[i])) {
					return null;
				}
			}
			this._ensureParsed();
			let formats: string[] = [];
			let values: string[] = [];
			let bufIdx = 0;
			for (let ti = 0; ti < this._tokens.length; ti++) {
				let tok = this._tokens[ti];
				if (tok.type === 'editable') {
					formats.push(tok.token);
					let tokenVal = '';
					for (let ci = 0; ci < tok.displayLen; ci++) {
						tokenVal += this._digitBuffer[bufIdx++];
					}
					values.push(tokenVal);
				}
			}
			if (this._hasHFormatWithMeridiem()) {
				formats.push("a");
				values.push(this._formatMeridiem("a"));
			}
			let mm = this._createMomentForMask(values.join("/"), formats.join("/"), true);
			return mm.isValid() ? mm : null;
		}

		/**
		 * 세그먼트 유형에 따른 moment 조작 키를 반환합니다.
		 */
		private _getMomentKey(segType: string): string {
			switch (segType) {
				case 'Y': case 'y': return 'years';
				case 'M': return 'months';
				case 'D': return 'days';
				case 'H': case 'h': case 'k': return 'hours';
				case 'm': return 'minutes';
				case 's': return 'seconds';
				case 'S': return 'milliseconds';
				default: return null;
			}
		}

		/**
		 * 세그먼트 유형과 자릿수에 따른 한 번 스핀 시 변경량을 반환합니다.
		 * S(밀리초)는 자릿수에 따라 100/10/1 단위로 동작합니다.
		 */
		private _getMomentCount(segType: string, segLen: number): number {
			if (segType === 'S') {
				return segLen === 1 ? 100 : segLen === 2 ? 10 : 1;
			}
			return 1;
		}

		/**
		 * 세그먼트 유형과 자릿수에 따른 값의 범위를 반환합니다.
		 */
		private _getSegmentRange(segType: string, segLen: number): { min: number; max: number } {
			switch (segType) {
				case 'Y': case 'y': return segLen === 2 ? { min: 0, max: 99 } : { min: 1, max: 9999 };
				case 'M': return { min: 1, max: 12 };
				case 'D': return { min: 1, max: 31 };
				case 'H': return { min: 0, max: 23 };
				case 'h': return { min: 1, max: 12 };
				case 'k': return { min: 1, max: 24 };
				case 'm': return { min: 0, max: 59 };
				case 's': return { min: 0, max: 59 };
				case 'S': return segLen === 1 ? { min: 0, max: 9 } : segLen === 2 ? { min: 0, max: 99 } : { min: 0, max: 999 };
				default: return { min: 0, max: 99 };
			}
		}

		/**
		 * 커서 위치의 세그먼트 값을 상/하로 변경합니다.
		 * spinLoop=false이고 버퍼가 완성된 경우: moment carry-over로 상위 세그먼트도 함께 변경합니다.
		 * spinLoop=true이거나 버퍼 미완성인 경우: 해당 세그먼트만 범위 내 순환합니다.
		 * @param digitIdx 스핀 대상 자릿 버퍼 인덱스
		 * @param increment true면 증가, false면 감소
		 */
		private _spinSegment(digitIdx: number, increment: boolean): void {
			this._ensureParsed();
			let segType = this._segmentTypes[digitIdx];

			// 세그먼트 시작/끝 인덱스 계산
			let segRange = this._getSegmentBufferRange(digitIdx);
			let segStart = segRange.start;
			let segEnd = segRange.end;
			let segLen = segRange.len;

			// spinLoop=false + 버퍼 완성: moment carry-over
			if (!this._spinLoop) {
				let mm = this._parseBufferMoment();
				if (mm !== null) {
					let momentKey = this._getMomentKey(segType);
					let count = this._getMomentCount(segType, segLen);
					if (momentKey) {
						if (increment) {
							let newMm = mm.clone().add(count, momentKey);
							if (!newMm.isAfter(this._maxDate)) {
								this._reset(newMm);
							}
						} else {
							let newMm = mm.clone().subtract(count, momentKey);
							if (!newMm.isBefore(this._minDate)) {
								this._reset(newMm);
							}
						}
						return;
					}
				}
			}

			// spinLoop=true 또는 버퍼 미완성: 해당 세그먼트만 순환
			let hasEmpty = false;
			for (let i = 0; i < this._digitBuffer.length; i++) {
				if (this._isEmptyChar(this._digitBuffer[i])) {
					hasEmpty = true;
					break;
				}
			}
			if (hasEmpty) {
				// 빈 세그먼트는 기본 날짜로 채우고, 미완성 세그먼트는 입력된 값 기준 패딩 적용
				this._fillEmptySegmentsWithDefaultDate();
			}

			let range = this._getSegmentRange(segType, segLen);

			// D 세그먼트인 경우, 현재 버퍼의 연/월로부터 실제 해당 월의 마지막 날을 구합니다 (DateMask와 동일한 방식).
			if (segType === 'D') {
				let yBufIdx = -1, yLen = 0;
				let mBufIdx = -1, mLen = 0;
				let bIdx = 0;
				for (let ti = 0; ti < this._tokens.length; ti++) {
					let tok = this._tokens[ti];
					if (tok.type !== 'editable') {
						continue;
					}
					let first = tok.token.charAt(0);
					if ((first === 'Y' || first === 'y') && yBufIdx < 0) {
						yBufIdx = bIdx;
						yLen = tok.displayLen;
					} else if (first === 'M' && mBufIdx < 0) {
						mBufIdx = bIdx;
						mLen = tok.displayLen;
					}
					bIdx += tok.displayLen;
				}
				if (yBufIdx >= 0 && mBufIdx >= 0) {
					let yStr = '', mStr = '';
					let yOk = true, mOk = true;
					for (let ci = 0; ci < yLen; ci++) {
						if (this._isEmptyChar(this._digitBuffer[yBufIdx + ci])) { yOk = false; break; }
						yStr += this._digitBuffer[yBufIdx + ci];
					}
					for (let ci = 0; ci < mLen; ci++) {
						if (this._isEmptyChar(this._digitBuffer[mBufIdx + ci])) { mOk = false; break; }
						mStr += this._digitBuffer[mBufIdx + ci];
					}
					if (yOk && mOk) {
						let refMm = moment({ year: parseInt(yStr, 10), month: parseInt(mStr, 10) - 1, date: 1 });
						if (refMm.isValid()) {
							range = { min: 1, max: refMm.daysInMonth() };
						}
					}
				}
			}

			let str = '';
			for (let i = segStart; i <= segEnd; i++) {
				str += this._digitBuffer[i];
			}
			let currentVal = parseInt(str, 10);

			let newVal = increment ? currentVal + 1 : currentVal - 1;
			if (newVal > range.max) { newVal = range.min; }
			if (newVal < range.min) { newVal = range.max; }

			let padded = String(newVal);
			while (padded.length < segLen) {
				padded = '0' + padded;
			}

			// 버퍼에 적용 전 이전 값 백업
			let prevBuffer = this._digitBuffer.slice();
			for (let i = 0; i < segLen; i++) {
				this._digitBuffer[segStart + i] = padded.charAt(i);
			}

			// 24시간제 시각이 순환하면 오전/오후 표시를 동기화합니다.
			if (this._hasHFormatWithMeridiem()) {
				this._syncMeridiemFromBuffer();
			}

			// M 세그먼트 변경 후 D 세그먼트를 해당 월의 최대 일수로 클램프
			if (segType === 'M') {
				let yStart = -1, yLen2 = 0, mStart2 = -1, mLen2 = 0, dStart2 = -1, dLen2 = 0;
				for (let i = 0; i < this._segmentTypes.length; i++) {
					let st = this._segmentTypes[i];
					if ((st === 'Y' || st === 'y') && yStart < 0) { yStart = i; }
					if ((st === 'Y' || st === 'y') && yStart >= 0) { yLen2 = i - yStart + 1; }
					if (st === 'M' && mStart2 < 0) { mStart2 = i; }
					if (st === 'M' && mStart2 >= 0) { mLen2 = i - mStart2 + 1; }
					if (st === 'D' && dStart2 < 0) { dStart2 = i; }
					if (st === 'D' && dStart2 >= 0) { dLen2 = i - dStart2 + 1; }
				}
				if (yStart >= 0 && mStart2 >= 0 && dStart2 >= 0) {
					let yStr2 = '', mStr2 = '', dStr2 = '';
					let yOk2 = true, mOk2 = true, dOk2 = true;
					for (let ci = 0; ci < yLen2; ci++) {
						if (this._isEmptyChar(this._digitBuffer[yStart + ci])) { yOk2 = false; break; }
						yStr2 += this._digitBuffer[yStart + ci];
					}
					for (let ci = 0; ci < mLen2; ci++) {
						if (this._isEmptyChar(this._digitBuffer[mStart2 + ci])) { mOk2 = false; break; }
						mStr2 += this._digitBuffer[mStart2 + ci];
					}
					for (let ci = 0; ci < dLen2; ci++) {
						if (this._isEmptyChar(this._digitBuffer[dStart2 + ci])) { dOk2 = false; break; }
						dStr2 += this._digitBuffer[dStart2 + ci];
					}
					if (yOk2 && mOk2 && dOk2) {
						let refMm2 = moment({ year: parseInt(yStr2, 10), month: parseInt(mStr2, 10) - 1, date: 1 });
						if (refMm2.isValid()) {
							let maxDay = refMm2.daysInMonth();
							let dayVal = parseInt(dStr2, 10);
							if (dayVal > maxDay) {
								let clampedDay = String(maxDay);
								while (clampedDay.length < dLen2) { clampedDay = '0' + clampedDay; }
								for (let ci = 0; ci < dLen2; ci++) {
									this._digitBuffer[dStart2 + ci] = clampedDay.charAt(ci);
								}
							}
						}
					}
				}
			}

			// 변경 후 minDate/maxDate 범위를 벗어나면 원상 복구
			let resultMm = this._parseBufferMoment();
			if (resultMm !== null) {
				if (resultMm.isAfter(this._maxDate) || resultMm.isBefore(this._minDate)) {
					this._digitBuffer = prevBuffer;
				}
			}
		}

		/**
		 * 포맷에 시간 editable 토큰과 a/A display 토큰이 함께 있는지 확인합니다.
		 */
		private _hasHFormatWithMeridiem(): boolean {
			this._ensureParsed();
			let hasH = false, hasMeridiem = false;
			for (let ti = 0; ti < this._tokens.length; ti++) {
				let tok = this._tokens[ti];
				let firstChar = tok.token.charAt(0);
				if (tok.type === 'editable' && (firstChar === 'h' || firstChar === 'H' || firstChar === 'k')) { hasH = true; }
				if (tok.type === 'display' && (tok.token === 'a' || tok.token === 'A')) { hasMeridiem = true; }
			}
			return hasH && hasMeridiem;
		}

		/**
		 * 버퍼에서 특정 세그먼트 유형(Y/M/D/H 등)의 첫 번째 버퍼 인덱스를 반환합니다.
		 * 없으면 -1을 반환합니다.
		 */
		private _findSegBufIdx(segType: string): number {
			this._ensureParsed();
			for (let i = 0; i < this._segmentTypes.length; i++) {
				if (this._segmentTypes[i] === segType) {
					return i;
				}
			}
			return -1;
		}

		/**
		 * 표시 위치가 오전/오후(a/A) display-only 토큰 내에 있으면 해당 토큰 정보를 반환합니다.
		 * h(12시간) 포맷과 함께 있을 때만 유효합니다. 해당되지 않으면 null을 반환합니다.
		 */
		private _getMeridiemTokenAtPos(displayPos: number): { displayStart: number, displayLen: number, isUpper: boolean } | null {
			this._ensureParsed();
			for (let ti = 0; ti < this._tokens.length; ti++) {
				let tok = this._tokens[ti];
				if (tok.type === 'display' && (tok.token === 'a' || tok.token === 'A')) {
					if (displayPos >= tok.displayStart && displayPos < tok.displayStart + tok.displayLen) {
						return { displayStart: tok.displayStart, displayLen: tok.displayLen, isUpper: tok.token === 'A' };
					}
				}
			}
			return null;
		}

		/**
		 * 표시 위치가 요일(d/dd/ddd/dddd) display-only 토큰 내에 있으면 해당 토큰 정보를 반환합니다.
		 * 해당되지 않으면 null을 반환합니다.
		 */
		private _getDOWTokenAtPos(displayPos: number): { displayStart: number, displayLen: number } | null {
			this._ensureParsed();
			for (let ti = 0; ti < this._tokens.length; ti++) {
				let tok = this._tokens[ti];
				if (tok.type === 'display' && tok.token.charAt(0) === 'd') {
					if (displayPos >= tok.displayStart && displayPos < tok.displayStart + tok.displayLen) {
						return { displayStart: tok.displayStart, displayLen: tok.displayLen };
					}
				}
			}
			return null;
		}

		/**
		 * digitIdx가 속한 토큰을 기준으로 세그먼트의 버퍼 범위(시작, 끝, 길이)를 계산하여 반환합니다.
		 */
		private _getSegmentBufferRange(digitIdx: number): { start: number, end: number, len: number } {
			this._ensureParsed();
			let displayPos = this._digitIndices[digitIdx];
			let targetToken: any = null;
			for (let i = 0; i < this._tokens.length; i++) {
				let tok = this._tokens[i];
				if (displayPos >= tok.displayStart && displayPos < tok.displayStart + tok.displayLen) {
					targetToken = tok;
					break;
				}
			}
			if (!targetToken) {
				return { start: digitIdx, end: digitIdx, len: 1 };
			}
			let start = -1;
			let end = -1;
			for (let i = 0; i < this._digitIndices.length; i++) {
				let pos = this._digitIndices[i];
				if (pos >= targetToken.displayStart && pos < targetToken.displayStart + targetToken.displayLen) {
					if (start === -1) {
						start = i;
					}
					end = i;
				}
			}
			return { start: start, end: end, len: end - start + 1 };
		}

		/**
		 * 특정 자릿 버퍼 인덱스가 속한 세그먼트의 첫 번째 표시 위치를 반환합니다.
		 */
		private _getSegmentDisplayStart(digitIdx: number): number {
			this._ensureParsed();
			let segRange = this._getSegmentBufferRange(digitIdx);
			return this._digitIndices[segRange.start];
		}

		/**
		 * 특정 자릿 버퍼 인덱스가 속한 세그먼트의 마지막 표시 위치+1을 반환합니다.
		 */
		private _getSegmentDisplayEnd(digitIdx: number): number {
			this._ensureParsed();
			let segRange = this._getSegmentBufferRange(digitIdx);
			return this._digitIndices[segRange.end] + 1;
		}

		private _getKeyCode(e: KeyboardEvent): number {
			return e.keyCode || e.which;
		}

		private _getKey(e: KeyboardEvent): string {
			return e.key || "";
		}

		private _isSpinKey(keyCode: number, key: string): boolean {
			return keyCode == events.KeyCode.UP || keyCode == events.KeyCode.DOWN || key == "ArrowUp" || key == "ArrowDown" || key == "Up" || key == "Down";
		}

		private _isNavigationKey(keyCode: number, key: string): boolean {
			return keyCode == events.KeyCode.LEFT || keyCode == events.KeyCode.RIGHT || keyCode == events.KeyCode.UP || keyCode == events.KeyCode.DOWN ||
				keyCode == events.KeyCode.HOME || keyCode == events.KeyCode.END ||
				key == "ArrowLeft" || key == "ArrowRight" || key == "ArrowUp" || key == "ArrowDown" ||
				key == "Left" || key == "Right" || key == "Up" || key == "Down" ||
				key == "Home" || key == "End";
		}

		private _getClipboardText(e: ClipboardEvent): string {
			let clipboardData = e.clipboardData || window["clipboardData"];
			if (!clipboardData) {
				return "";
			}
			let types = e.clipboardData ? ["text/plain", "Text", "text"] : ["Text", "text", "text/plain"];
			for (let i = 0; i < types.length; i++) {
				try {
					let text = clipboardData.getData(types[i]);
					if (text) {
						return text;
					}
				} catch (ex) {
					// IE11 clipboardData can reject unsupported data formats.
				}
			}
			return "";
		}

		private _clearBySelection(input: HTMLInputElement, ss: number, se: number, isDeleteKey: boolean): void {
			if (ss == 0 && se == input.value.length) {
				this._reset();
				let digitIdx = this._getDefaultSelectionDigitIndex(this._defaultSelection);
				let start = digitIdx >= 0 ? this._getSegmentDisplayStart(digitIdx) : 0;
				this._updateInputValue(input, start);
				return;
			}

			if (ss !== se) {
				for (let i = 0; i < this._digitIndices.length; i++) {
					let pos = this._digitIndices[i];
					if (pos >= ss && pos < se) {
						this._digitBuffer[i] = this._getPlaceholderChar();
					}
				}
				this._updateInputValue(input, ss);
				return;
			}

			let digitIdx: number;
			if (isDeleteKey) {
				digitIdx = this._displayPosToDigitIdx(ss);
				if (digitIdx === -1) {
					digitIdx = this._findNextDigitIdx(ss);
				}
			} else {
				digitIdx = this._findPrevDigitIdx(ss);
			}

			if (digitIdx >= 0) {
				this._digitBuffer[digitIdx] = this._getPlaceholderChar();
				this._updateInputValue(input, this._digitIndices[digitIdx]);
			}
		}

		/**
		 * 키다운 이벤트 핸들러.
		 * 숫자 입력, Backspace, Delete를 처리하고 그 외 키는 차단합니다.
		 * enabledInputMask 활성 시 ArrowUp/ArrowDown으로 세그먼트 값을 증감합니다.
		 */
		private _onKeydown(e: KeyboardEvent): void {
			// 캘린더가 열려있는 경우 처리하지 않음
			if (this._owner.isOpened()) {
				return;
			}

			let input = e.target as HTMLInputElement;
			let key = this._getKey(e);
			let keyCode = this._getKeyCode(e);
			let ss = input.selectionStart;
			let se = input.selectionEnd;

			// 제어키 조합, Tab, 펑션키, 방향키는 기본 동작 허용
			if (e.ctrlKey || e.metaKey || e.altKey) {
				return;
			}
			if (keyCode == events.KeyCode.TAB) {
				return;
			}
			if (keyCode == events.KeyCode.ENTER) {
				this._applyAutoPadding();
				this._syncInputMaskText(input);
				return;
			}
			if (keyCode == events.KeyCode.BACKSPACE || keyCode == events.KeyCode.DELETE) {
				e.preventDefault();
				this._ensureParsed();
				this._clearBySelection(input, ss, se, keyCode == events.KeyCode.DELETE);
				this._onBufferChange(e);
				return;
			}
			if (this._isNavigationKey(keyCode, key) || key.length > 1 && key !== 'Backspace' && key !== 'Delete') {
				// ArrowUp/ArrowDown에 의한 세그먼트 스핀은 DateInput 루트의 keydown 핸들러에서
				// _spinByKeydown()으로 처리한다. 사용자 keydown 이벤트에서 preventDefault()를
				// 호출한 경우 스핀이 동작하지 않아야 하기 때문이다. release-test-project#11141

				// Home, End, 방향키는 기본 동작 허용
				if (this._isNavigationKey(keyCode, key)) {
					return;
				}
				// 나머지 다중 문자 키 (Escape 등)는 처리하지 않음
				return;
			}

			this._ensureParsed();

			// 숫자 키 처리
			if (/^[0-9]$/.test(key)) {
				e.preventDefault();
				let cursorPos = ss;

				this._updateEditingState(ss, se, input.value.length);

				// 선택 영역이 있는 경우 해당 영역의 숫자 위치를 먼저 초기화
				if (ss !== se) {
					for (let i = 0; i < this._digitIndices.length; i++) {
						let pos = this._digitIndices[i];
						if (pos >= ss && pos < se) {
							this._digitBuffer[i] = this._getPlaceholderChar();
						}
					}
					cursorPos = ss;
				}

				// 커서 위치 이상의 첫 번째 숫자 위치를 찾아 입력
				let digitIdx = this._findNextDigitIdx(cursorPos);
				if (digitIdx === -1) {
					return;
				}

				// 유효성 검사
				if (!this._isValidDigitForPosition(key, digitIdx)) {
					return;
				}

				this._digitBuffer[digitIdx] = key;

				// 세그먼트 완결 여부 체크
				let segRange = this._getSegmentBufferRange(digitIdx);
				this._lastInputSegmentCompleted = (digitIdx === segRange.end);

				// 다음 숫자 위치로 커서 이동
				let nextDigitIdx = digitIdx + 1;
				let nextCursorPos: number;
				if (nextDigitIdx < this._digitIndices.length) {
					nextCursorPos = this._digitIndices[nextDigitIdx];
				} else {
					nextCursorPos = this._digitIndices[digitIdx] + 1;
				}

				this._updateInputValue(input, nextCursorPos);
				this._onBufferChange(e);
				return;
			}


			// 그 외 모든 키 차단
			e.preventDefault();
		}

		/**
		 * 방향키 위/아래에 의한 세그먼트 스핀을 수행합니다.
		 *
		 * 입력 엘리먼트가 아닌 DateInput 루트에서 호출됩니다. 루트의 keydown 핸들러는 사용자
		 * 이벤트 다음에 실행되므로, 사용자가 keydown에서 preventDefault()를 호출하면 이 메서드가
		 * 호출되지 않아 스핀이 동작하지 않습니다. release-test-project#11141
		 *
		 * @param e 키보드 이벤트
		 * @return 스핀을 처리한 경우 true
		 */
		public _spinByKeydown(e: events.CKeyboardEvent): boolean {
			// 캘린더가 열려있는 경우 처리하지 않음
			if (this._readOnly || this._owner.isOpened()) {
				return false;
			}
			// 제어키 조합은 기본 동작 허용
			if (e.ctrlKey || e.metaKey || e.altKey) {
				return false;
			}
			let key = this._getKey(e);
			let keyCode = this._getKeyCode(e);
			if (this._isSpinKey(keyCode, key) == false || this._enabledInputMask == false) {
				return false;
			}

			let input = e.target as HTMLInputElement;
			let ss = input.selectionStart;
			let se = input.selectionEnd;

			e.preventDefault();
			this._ensureParsed();
			let increment = keyCode == events.KeyCode.UP || key == "ArrowUp" || key == "Up";

			let currentSS = ss;
			let currentSE = se;
			if (ss === 0 && se === input.value.length) {
				let sel = this._getDefaultSelectionRange(this._defaultSelection);
				currentSS = sel.start;
				currentSE = sel.end;
			}

			// 빈 버퍼인 경우 오늘 날짜로 채워 넣기 (스핀 연산이 가능하도록 준비)
			let isBufferPrepared = false;
			if (this._shouldPrepareSpinBuffer()) {
				this._fillEmptySegmentsWithDefaultDate();
				isBufferPrepared = true;
			}

			let digitIdx = this._displayPosToDigitIdx(currentSS);
			let cursorStart: number;
			let cursorEnd: number;

			// 오전/오후(a/A) 표시 영역: 24시간제가 아닐 때만 토글 허용
			let meridiemToken = digitIdx === -1 ? this._getMeridiemTokenAtPos(currentSS) : null;
			if (meridiemToken !== null) {
				if (!this._has24HourFormatWithMeridiem()) {
					// 빈 값 스핀 등으로 오늘 날짜가 막 채워진 상태에서도 스핀 반응을 주기 위해 즉시 토글 실행
					this._toggleMeridiem();
					this._updateInputValue(input, meridiemToken.displayStart);
					this._onBufferChange(e);
				}
				input.setSelectionRange(meridiemToken.displayStart, meridiemToken.displayStart + meridiemToken.displayLen);
				return true;
			}

			// 요일(ddd) 표시 영역: D 세그먼트를 스핀하고 커서는 ddd 위치 유지
			let dowToken = digitIdx === -1 ? this._getDOWTokenAtPos(currentSS) : null;
			if (dowToken !== null) {
				let dIdx = this._findSegBufIdx('D');
				if (dIdx < 0) {
					return true;
				}
				// 요일 영역에서 빈 버퍼 첫 스핀인 경우에는 값 세팅만 하고 추가 증감 생략 (segment와 동일)
				if (!isBufferPrepared) {
					this._spinSegment(dIdx, increment);
				}
				cursorStart = dowToken.displayStart;
				cursorEnd = dowToken.displayStart + dowToken.displayLen;
			} else {
				if (digitIdx === -1) {
					digitIdx = this._findNextDigitIdx(currentSS);
				}
				if (digitIdx === -1) {
					digitIdx = this._findPrevDigitIdx(currentSS);
				}
				if (digitIdx >= 0) {
					// 일반 세그먼트 빈 버퍼 첫 스핀 시 증감 생략 (segment와 동일)
					if (!isBufferPrepared) {
						this._spinSegment(digitIdx, increment);
					}
					cursorStart = this._getSegmentDisplayStart(digitIdx);
					cursorEnd = this._getSegmentDisplayEnd(digitIdx);
				}
			}

			this._updateInputValue(input, cursorStart);
			input.setSelectionRange(cursorStart, cursorEnd);
			this._onBufferChange(e);
			return true;
		}

		/**
		 * 포커스 이벤트 핸들러.
		 * 현재 버퍼 상태를 표시하고, autoSelect 설정에 따라 선택 영역을 지정합니다.
		 */
		private _onFocus(e: FocusEvent): void {
			this._resetBlurAdjust();
			if (this.spinning || this._input && this._input.from == InputLocation.drop) {
				return;
			}
			let input = e.target as HTMLInputElement;
			this._ensureParsed();
			this._lastInputSegmentCompleted = true;
			this._autoSkipAllowed = false;
			this._editingCompletedValue = false;

			this._syncInputMaskText(input);

			if (this._dropFocusFlag) {
				this._dropFocusFlag = false;
				return;
			}

			if (this._mouseDownFlag) {
				if (this._autoSelect) {
					this._isFirstAutoSelect = true;
				} else {
					this._isFirstAutoSelect = false;
					return;
				}
			}

			let ss: number;
			let se: number;
			if (this._autoSelect) {
				ss = 0;
				se = input.value.length;
			} else {
				let sel = this._getDefaultSelectionRange(this._defaultSelection);
				ss = sel.start;
				se = sel.end;
			}

			this._setInputSelection(input, ss, se);
		}

		/**
		 * 입력 엘리먼트에 현재 버퍼 상태를 표시합니다.
		 */
		private _syncInputMaskText(input: HTMLInputElement): void {
			let text = this._getBufferDisplayText();
			if (input.value !== text) {
				input.value = text;
			}
		}

		/**
		 * 첫 번째 빈 숫자 위치를 반환합니다.
		 */
		private _getFirstEditableCursorPos(): number {
			let firstEmpty = -1;
			for (let i = 0; i < this._digitIndices.length; i++) {
				if (this._isEmptyChar(this._digitBuffer[i])) {
					firstEmpty = i;
					break;
				}
			}
			if (firstEmpty >= 0) {
				return this._digitIndices[firstEmpty];
			}
			return this._digitIndices[this._digitIndices.length - 1] + 1;
		}

		/**
		 * defaultSelection 설정에 맞는 masked 표시 영역을 반환합니다.
		 * none은 특정 세그먼트를 강제하지 않고 기존 masked 기본값인 첫 번째 빈 위치를 사용합니다.
		 */
		public _getDefaultSelectionRange(defaultSelection: string): { start: number, end: number } {
			defaultSelection = this._normalizeDefaultDateSelection(defaultSelection);
			if (defaultSelection == "none") {
				// segment 마스크 동작과 일치하도록 맨 처음 편집 가능 숫자 위치(맨 앞)를 사용
				let pos = this._digitIndices[0] ?? 0;
				return { start: pos, end: pos };
			}

			let formats: string[] = [];
			for (let i = 0; i < this._tokens.length; i++) {
				let token = this._tokens[i];
				if (token.type == "editable") {
					formats.push(token.token);
				}
			}

			let format = this._getFormatByDefaultDateSelection(defaultSelection, formats);
			if (!format) {
				let pos = this._getFirstEditableCursorPos();
				return { start: pos, end: pos };
			}

			for (let i = 0; i < this._tokens.length; i++) {
				let token = this._tokens[i];
				if (token.type == "editable" && token.token == format) {
					return { start: token.displayStart, end: token.displayStart + token.displayLen };
				}
			}

			let pos = this._getFirstEditableCursorPos();
			return { start: pos, end: pos };
		}

		private _getDefaultSelectionDigitIndex(defaultSelection: string): number {
			let range = this._getDefaultSelectionRange(defaultSelection);
			let digitIdx = this._displayPosToDigitIdx(range.start);
			if (digitIdx >= 0) {
				return digitIdx;
			}
			digitIdx = this._findNextDigitIdx(range.start);
			if (digitIdx >= 0) {
				return digitIdx;
			}
			return this._findPrevDigitIdx(range.start);
		}

		private _onMouseDown(e: MouseEvent): void {
			this._mouseDownFlag = true;
		}

		private _onMouseUp(e: MouseEvent): void {
			let input = e.target as HTMLInputElement;
			this._mouseDownFlag = false;
			if (this._isFirstAutoSelect) {
				this._isFirstAutoSelect = false;
				if (this._autoSelect) {
					// 마우스업 기본 동작이 선택 영역을 바꾼 뒤에 설정해야 하므로 브라우저와 무관하게 렌더링 후로 미룬다.
					this._setInputSelection(input, 0, input.value.length, true);
				}
			}
		}

		/**
		 * 블러 이벤트 핸들러.
		 * 실제 값 커밋은 DateInput._onInputBlur에서 처리합니다.
		 */
		private _onBlur(e: FocusEvent): void {
			// DateInput._onInputBlur에서 _validateValue를 통해 값을 커밋
			let input = e.target as HTMLInputElement;
			// blur와 focusout 양쪽에 등록되어 있어 한 번의 포커스 이탈에 두 번 실행될 수 있다.
			// 입력란 반영은 먼저 도착한 이벤트에서 한 번만 수행한다. release-test-project#11149
			if (this._shouldAdjustOnBlur()) {
				this._applyAutoPadding();
				this._syncInputMaskText(input);
			}

			this._mouseDownFlag = false;
			this._isFirstAutoSelect = false;
			this._lastSelectionStart = null;
			this._lastInputSegmentCompleted = true;
			this._autoSkipAllowed = false;
			this._editingCompletedValue = false;
		}

		/**
		 * 붙여넣기 이벤트 핸들러.
		 * 붙여넣은 텍스트에서 숫자를 추출하여 버퍼를 채웁니다.
		 */
		private _onPaste(e: ClipboardEvent): void {
			e.preventDefault();
			let text = this._getClipboardText(e);
			if (!text) {
				return;
			}
			let input = e.target as HTMLInputElement;
			this._applyPasteOrDropText(text, input, e);
		}

		private _onDragOver(e: DragEvent): void {
			if (this._hasWeekdayFormat() || this._hasMeridiemFormat()) {
				if (e.dataTransfer) {
					e.dataTransfer.dropEffect = "none";
				}
				e.preventDefault();
			}
		}

		private _onDrop(e: DragEvent): void {
			if (this._hasWeekdayFormat() || this._hasMeridiemFormat()) {
				e.preventDefault();
				e.stopPropagation();
				return;
			}
			let transferData = e.dataTransfer.getData("text");
			if (!transferData) {
				return;
			}
			let input = e.target as HTMLInputElement;

			this._ensureParsed();
			this._input = new InputObject(input.value, input.selectionStart, input.selectionEnd, InputLocation.drop);
			this._input.setData("transfer", transferData);

			this._dropFocusFlag = true;
			this._dispatchEvent("drop", e);
		}

		/**
		 * beforeinput 이벤트 핸들러.
		 * IME(한글) 등 keydown 단계에서 걸러지지 않는 숫자 외 문자 입력을 사전에 차단합니다.
		 */
		private _onBeforeInput(e: any): void {
			let input = e.target as HTMLInputElement;
			this._lastSelectionStart = input.selectionStart;

			if (this._input && this._input.from == InputLocation.drop) {
				return;
			}
			let char = e.data;
			if (!char) {
				return;
			}

			// 숫자가 아닌 글자 입력 시 브라우저 기본 삽입을 차단합니다.
			if (!/^[0-9]+$/.test(char)) {
				e.preventDefault();
				return;
			}

			// 숫자가 입력된 경우 기본 삽입을 막고 공통 헬퍼를 통해 버퍼 주입 및 캐럿 처리를 실행합니다.
			e.preventDefault();
			this._applyPasteOrDropText(char, input, e);
		}

		private _onInput(e: Event): void {
			let input = e.target as HTMLInputElement;
			if (this._input?.from == InputLocation.drop) {
				let value = input.value;
				let len = this._input.before.text.length;
				let startIndex = -1;
				for (let i = 0; i < len; i++) {
					let char = this._input.before.text.charAt(i);
					if (value.charAt(i) != char) {
						startIndex = i;
						break;
					}
				}
				if (startIndex == -1) {
					startIndex = len;
				}

				let transferText = this._input.getData("transfer");

				// 드롭 전의 텍스트와 역산된 startIndex 기준 커서 상태로 원복 후 공통 대입 처리 실행
				input.value = this._input.before.text;
				input.setSelectionRange(startIndex, startIndex);

				this._input = null; // 처리 완료 상태 전환

				// 드롭 위치의 세그먼트 탐색 및 선택 영역 확장(Snap)
				let digitIdx = this._displayPosToDigitIdx(startIndex);
				if (digitIdx === -1) {
					digitIdx = this._findNextDigitIdx(startIndex);
				}
				if (digitIdx === -1) {
					digitIdx = this._findPrevDigitIdx(startIndex);
				}
				if (digitIdx >= 0) {
					let segStart = this._getSegmentDisplayStart(digitIdx);
					let segEnd = this._getSegmentDisplayEnd(digitIdx);
					input.setSelectionRange(segStart, segEnd);
				}

				this._applyPasteOrDropText(transferText, input, e);
			} else {
				let expectedText = this._getBufferDisplayText();
				if (input.value !== expectedText) {
					input.value = expectedText;
					if (this._lastSelectionStart !== null) {
						this._setInputSelection(input, this._lastSelectionStart, this._lastSelectionStart);
					}
				}
				this._lastSelectionStart = null;
			}
		}

		private _applyPasteOrDropText(text: string, input: HTMLInputElement, e: Event): void {
			this._ensureParsed();
			let digits = text.replace(/[^0-9]/g, '');
			if (!digits) {
				return;
			}
			let ss = input.selectionStart;
			let se = input.selectionEnd;

			this._updateEditingState(ss, se, input.value.length);

			if (ss == 0 && se == input.value.length) {
				let mm = this._createMomentForMask(digits, this._getValueFormat(), true);
				if (mm.isValid()) {
					this._reset(mm);
					let value = this._getBufferDisplayText();
					input.value = value;
					input.setSelectionRange(0, value.length);
					this._lastInputSegmentCompleted = true;
					this._onBufferChange(e as any);
					return;
				}
			}

			let startDigitIdx = this._findNextDigitIdx(ss);
			if (startDigitIdx === -1) {
				startDigitIdx = this._findPrevDigitIdx(ss);
			}

			if (startDigitIdx >= 0) {
				// 선택 영역이 있을 시 해당 영역 초기화
				if (ss !== se) {
					for (let i = 0; i < this._digitIndices.length; i++) {
						let pos = this._digitIndices[i];
						if (pos >= ss && pos < se) {
							this._digitBuffer[i] = this._getPlaceholderChar();
						}
					}
				}

				let digitPos = 0;
				for (let i = startDigitIdx; i < this._digitIndices.length && digitPos < digits.length; i++) {
					let d = digits.charAt(digitPos);
					if (this._isValidDigitForPosition(d, i)) {
						this._digitBuffer[i] = d;
						digitPos++;
					} else {
						let segType = this._segmentTypes[i];
						let segStart = i;
						while (segStart > 0 && this._segmentTypes[segStart - 1] === segType) {
							segStart--;
						}
						let posInSeg = i - segStart;
						if (posInSeg === 1 && ("MDHhkms".indexOf(segType) >= 0)) {
							let backupPrev = this._digitBuffer[segStart];
							this._digitBuffer[segStart] = "0";
							this._digitBuffer[i] = d;
							if (this._isValidDigitForPosition(d, i)) {
								digitPos++;
							} else {
								this._digitBuffer[segStart] = backupPrev;
								this._digitBuffer[i] = this._getPlaceholderChar();
								break;
							}
						} else {
							break;
						}
					}
				}

				let lastInputIdx = startDigitIdx + digitPos - 1;
				let nextCursorPos = this._digitIndices[Math.min(lastInputIdx + 1, this._digitIndices.length - 1)];
				this._updateInputValue(input, nextCursorPos);
				this._lastInputSegmentCompleted = true;
				this._onBufferChange(e as any);
			}
		}

		/**
		 * 버퍼 변경 시 등록된 "input" 리스너를 호출합니다.
		 */
		private _onBufferChange(e: Event): void {
			this._lastSpinMoment = null;
			this._spinPrepared = false;
			this._dispatchEvent("input", e);
		}

		/**
		 * 입력 엘리먼트에 마스크 이벤트 핸들러를 등록합니다.
		 * DateMask.wrap()과 동일한 가상 DOM 방식으로 처리합니다.
		 * @param shape 입력 엘리먼트 가상 DOM 노드
		 */
		public wrap(shape: ufc.ControlShape): void {
			if (shape["events"] === undefined || shape["events"] === null) {
				shape["events"] = {};
			}
			if (this._readOnly) {
				return;
			}
			ufc.ShapeUtil.addEventHandler(shape, "keydown", (e) => this._onKeydown(e), true);
			ufc.ShapeUtil.addEventHandler(shape, "focus", (e) => this._onFocus(e), true);
			// 브라우저에 따라 blur 또는 focusout 한쪽만 오는 경우가 있어 양쪽에 등록한다(IE는 blur가 다음 틱에 비동기로 발생).
			// 둘 다 발생하는 브라우저에서는 핸들러가 두 번 실행되므로, 입력란 반영은 _onBlur 안에서 한 번만 수행한다. release-test-project#11149
			ufc.ShapeUtil.addEventHandler(shape, "blur", (e) => this._onBlur(e), true);
			ufc.ShapeUtil.addEventHandler(shape, "focusout", (e) => this._onBlur(e), true);
			ufc.ShapeUtil.addEventHandler(shape, "mousedown", (e) => this._onMouseDown(e), true);
			ufc.ShapeUtil.addEventHandler(shape, "mouseup", (e) => this._onMouseUp(e), true);
			ufc.ShapeUtil.addEventHandler(shape, "paste", (e) => this._onPaste(e as ClipboardEvent), true);
			ufc.ShapeUtil.addEventHandler(shape, "drop", (e) => this._onDrop(e as DragEvent), true);
			ufc.ShapeUtil.addEventHandler(shape, "dragover", (e) => this._onDragOver(e as DragEvent), true);
			ufc.ShapeUtil.addEventHandler(shape, "beforeinput", (e) => this._onBeforeInput(e), true);
			ufc.ShapeUtil.addEventHandler(shape, "input", (e) => this._onInput(e), true);
		}

		/**
		 * 마스크 내부 상태를 초기화합니다.
		 * @param obj Date 또는 moment 객체. 없으면 빈 상태로 초기화합니다.
		 */
		public _reset(obj?: any): void {
			this._ensureParsed();
			this._lastSpinMoment = null;
			this._spinPrepared = false;
			if (obj == null) {
				this._digitBuffer = this._createEmptyBuffer();
				return;
			}
			let mm: any;
			if (obj instanceof Date) {
				mm = moment(obj);
			} else if (obj && typeof obj.format === 'function') {
				mm = obj;
			} else {
				this._digitBuffer = this._createEmptyBuffer();
				return;
			}

			// 유효하지 않은 날짜인 경우 빈 버퍼 상태로 리턴 처리 (In/In 노출 방지)
			if (!mm || !mm.isValid()) {
				this._digitBuffer = this._createEmptyBuffer();
				return;
			}

			// 토큰 단위로 moment 값을 추출하여 버퍼에 채움
			// (포맷 문자열 길이와 moment 출력 길이가 다를 수 있으므로 문자 단위 매핑 사용 불가)
			let digitPos = 0;
			for (let ti = 0; ti < this._tokens.length; ti++) {
				let tok = this._tokens[ti];
				if (tok.type !== 'editable') {
					continue;
				}
				let formatted = mm.format(tok.token);
				for (let ci = 0; ci < tok.displayLen; ci++) {
					if (digitPos < this._digitBuffer.length) {
						this._digitBuffer[digitPos++] = formatted.charAt(ci) || this._getPlaceholderChar();
					}
				}
			}
			// h(12시간) 포맷과 A/a 표시 토큰이 함께 있으면 오전/오후 상태 저장
			if (this._hasHFormatWithMeridiem()) {
				this._storedMeridiemIndex = this._getMeridiemIndex(mm);
			}
		}

		/**
		 * 빈 마스크 텍스트를 반환합니다 (e.g. "____-__-__").
		 * @param format 사용할 포맷. 없으면 현재 포맷을 사용합니다.
		 */
		public defaultText(format?: string): string {
			let fmt = format !== undefined ? format : this._getMaskFormat();
			// 포맷 토큰화하여 editable→placeholder, display-only→토큰 문자열(플레이스홀더), separator→리터럴
			let ALLOW_PATTERN = "(Y{4}|Y{2}|Y)|(M{2}|M)|(D{2}|D)|(H{2}|H)|(d{4}|d{3}|d{2})|(h{2}|h)|(k{2}|k)|(m{2}|m)|(s{2}|s)|a|A|(S{3}|S{2}|S)";
			let tokenRegExp = new RegExp(ALLOW_PATTERN + "|[\\s\\S]", "g");
			let tokens = fmt.match(tokenRegExp) || [];
			let refMm = this._createMomentForMask("2000-01-03T09:00:00", "YYYY-MM-DDTHH:mm:ss", true);
			let result = '';
			let placeholderChar = this._getPlaceholderChar();
			let displays = this.getDisplays(this._locale);
			for (let i = 0; i < tokens.length; i++) {
				let t = tokens[i];
				let first = t.charAt(0);
				if (this._isDateSegChar(first)) {
					result += t.replace(/./g, placeholderChar);
				} else if (first === 'd' || first === 'A' || first === 'a') {
					let displayText: string;
					let displayLen: number;
					if (first === 'd') {
						displayText = "DOW";
						displayLen = 3;
					} else if (first === 'A') {
						displayText = "AP";
						displayLen = 2;
					} else if (first === 'a') {
						displayText = "ap";
						displayLen = 2;
					} else {
						let text = displays ? displays[first] : null;
						displayText = text ? this._checkDisplayText(text) : t;
						displayLen = refMm.format(t).length;
					}
					let placeholder = displayText;
					while (placeholder.length < displayLen) {
						placeholder += ' ';
					}
					result += placeholder.substring(0, displayLen);
				} else {
					result += t;
				}
			}
			return result;
		}

		/**
		 * moment 객체를 마스크 포맷으로 변환한 표시 문자열을 반환합니다.
		 * @param obj moment 또는 Date 객체
		 */
		public formatDiaplay(obj: any): string {
			let mm: any;
			if (obj instanceof Date) {
				mm = moment(obj);
			} else {
				mm = obj;
			}
			if (!mm || !mm.isValid()) {
				return this.defaultText();
			}
			this._ensureParsed();
			let result = [];
			for (let ti = 0; ti < this._tokens.length; ti++) {
				let tok = this._tokens[ti];
				if (tok.type === 'editable') {
					result.push(mm.format(tok.token));
				} else if (tok.type === 'separator') {
					result.push(tok.token);
				} else {
					result.push(mm.format(tok.token));
				}
			}
			return result.join('');
		}

		/**
		 * 현재 입력 엘리먼트의 값을 파싱하여 moment 객체로 반환합니다.
		 * 완성된 날짜가 아니면 null을 반환합니다.
		 * @param originValue 기존 값 (DateMask 호환 파라미터, 미사용)
		 * @param originValueFormat 기존 값 포맷 (DateMask 호환 파라미터, 미사용)
		 */
		public mergeMaskValue(originValue: string, originValueFormat: string): moment.Moment {
			this._ensureParsed();
			this._applyAutoPadding();

			if (this._lastSpinMoment != null && this._lastSpinMoment.isValid()) {
				let mm = this._lastSpinMoment.clone();
				if (!this.spinning) {
					this._lastSpinMoment = null;
				}
				return mm;
			}

			let inputEl = this._getInputElement();
			if (inputEl) {
				this._syncInputMaskText(inputEl);
				if (inputEl.value == "") {
					return null;
				}
				// d(요일) 포맷은 화면에 항상 3자리 약어(DOW)로 렌더링되므로, 파싱할 때도 ddd로 보정하여 strict 파싱이 성공하도록 합니다.
				let maskFmt = this._getMaskFormat().replace(/d+/g, "ddd");
				// 영문 요일 및 오전오후가 포함되어 있으므로 명시적으로 영어 로캘("en")을 사용하여 파싱
				let mm = _createMoment(() => {
					return moment(inputEl.value, maskFmt, true);
				}, "en");
				if (mm.isValid()) {
					return mm;
				}
			}
			return this._parseBufferMoment();
		}

		public isAutoSkipValid(): boolean {
			// 마지막 입력이 세그먼트를 완결했고, 그 입력 직전 상태가 완성이 아니었어야 한다. release-test-project#11071
			return this._lastInputSegmentCompleted && this._autoSkipAllowed;
		}

		public isSingleInputSegmentFormat(): boolean {
			this._ensureParsed();
			let editableCount = 0;
			for (let i = 0; i < this._tokens.length; i++) {
				if (this._tokens[i].type === 'editable') {
					editableCount++;
				}
			}
			return editableCount === 1;
		}

		/**
		 * 입력을 반영하기 직전에 편집 세션 상태를 기록합니다.
		 *
		 * 이미 완성된 값을 편집하는 중에는 autoSkip을 실행하지 않는다. 전체 선택 입력은 편집이 아니라
		 * 새 값 입력으로 본다. 세그먼트가 하나인 포맷은 다시 입력하는 것이 곧 값 전체를 새로 입력하는 것이므로
		 * 편집으로 보지 않는다. release-test-project#11071
		 * @param ss 입력 직전 선택 시작
		 * @param se 입력 직전 선택 끝
		 * @param textLength 입력 직전 텍스트 길이
		 */
		private _updateEditingState(ss: number, se: number, textLength: number): void {
			let allSelected = ss !== se && ss === 0 && se === textLength;
			if (allSelected || this.isSingleInputSegmentFormat()) {
				this._editingCompletedValue = false;
			} else if (this.isComplete()) {
				this._editingCompletedValue = true;
			}
			this._autoSkipAllowed = !this._editingCompletedValue;
		}

		/**
		 * 입력 가능한 모든 자리가 채워졌는지 여부를 반환합니다.
		 */
		public isComplete(): boolean {
			this._ensureParsed();
			for (let i = 0; i < this._digitBuffer.length; i++) {
				if (this._isEmptyChar(this._digitBuffer[i])) {
					return false;
				}
			}
			return true;
		}

		/**
		 * 입력이 완료된 경우 현재 버퍼 값을 moment 객체로 반환합니다.
		 */
		public getCompletedMoment(): moment.Moment {
			if (!this.isComplete()) {
				return null;
			}
			return this._parseBufferMoment();
		}

		public spin(up: boolean, allSelected: boolean, selectionStart: number, defaultSelection?: string): { value: string, ss: number, se: number } {
			this._ensureParsed();
			let prepared = false;
			if (this._shouldPrepareSpinBuffer()) {
				this._fillEmptySegmentsWithDefaultDate();
				prepared = true;
			}
			let digitIdx: number;
			if (allSelected) {
				digitIdx = this._getDefaultSelectionDigitIndex(defaultSelection ? defaultSelection : this._defaultSelection);
			} else {
				digitIdx = this._displayPosToDigitIdx(selectionStart);
				if (digitIdx < 0) {
					// 1. 오전/오후(a/A) 표시 영역: 24시간제가 아닐 때만 토글 처리
					let meridiemToken = this._getMeridiemTokenAtPos(selectionStart);
					if (meridiemToken !== null) {
						if (!this._has24HourFormatWithMeridiem()) {
							// prepared (빈 상태에서 오늘 날짜 채움) 여부와 상관없이 즉시 토글 적용
							this._toggleMeridiem();
							this._lastSpinMoment = this._parseBufferMoment();
						}
						let ss = meridiemToken.displayStart;
						let se = meridiemToken.displayStart + meridiemToken.displayLen;
						return { value: this._getBufferDisplayText(), ss: ss, se: se };
					}

					// 2. 요일(ddd) 표시 영역: D 세그먼트를 스핀하고 커서는 ddd 위치 유지
					let dowToken = this._getDOWTokenAtPos(selectionStart);
					if (dowToken !== null) {
						let dIdx = this._findSegBufIdx('D');
						if (dIdx >= 0) {
							if (!prepared) {
								this._spinSegment(dIdx, up);
							}
							this._lastSpinMoment = this._parseBufferMoment();
						}
						let ss = dowToken.displayStart;
						let se = dowToken.displayStart + dowToken.displayLen;
						return { value: this._getBufferDisplayText(), ss: ss, se: se };
					}
				}

				if (digitIdx < 0) {
					digitIdx = this._findNextDigitIdx(selectionStart);
				}
				if (digitIdx < 0) {
					digitIdx = this._findPrevDigitIdx(selectionStart);
				}
			}
			if (digitIdx < 0) {
				digitIdx = this._digitIndices.length - 1;
			}

			// 최초 스핀(기본 날짜로 빈 버퍼를 채운 직후)일 때는 값 증감 단계를 생략합니다. (segment와 동일)
			if (!prepared) {
				this._spinSegment(digitIdx, up);
			}
			this._lastSpinMoment = this._parseBufferMoment();
			let ss = this._getSegmentDisplayStart(digitIdx);
			let se = this._getSegmentDisplayEnd(digitIdx);
			return { value: this._getBufferDisplayText(), ss: ss, se: se };
		}

		private _shouldPrepareSpinBuffer(): boolean {
			if (this._spinPrepared) {
				return false;
			}
			if (this._lastSpinMoment != null && this._lastSpinMoment.isValid()) {
				return false;
			}
			return this._parseBufferMoment() == null;
		}

		private _prepareSpinBuffer(): void {
			let ownerValue = this._owner._getValue();
			let mm = this._createMomentForMask(ownerValue, this._getValueFormat(), true);
			if (!mm.isValid()) {
				mm = moment(this._defaultDate);
			}
			if (moment(this._minDate).isSameOrBefore(this._maxDate)) {
				if (mm.isAfter(this._maxDate)) {
					mm = moment(this._maxDate);
				} else if (mm.isBefore(this._minDate)) {
					mm = moment(this._minDate);
				}
			}
			this._reset(mm);
			this._spinPrepared = true;
		}

		/**
		 * 마스크 포맷이 고정 길이인지 여부를 반환합니다.
		 * DateTextMask는 항상 고정 길이입니다 (DateMask 호환).
		 */
		public _isFixedLengthFormat(): boolean {
			return true;
		}

		/**
		 * 요일 포맷 포함 여부를 반환합니다.
		 * DateTextMask는 요일 포맷을 지원하지 않습니다 (DateMask 호환).
		 */
		public _isDayOfWeekFormat(mask: string, strict: boolean): boolean {
			return false;
		}

		/**
		 * 선택 해제 처리 (DateMask 호환).
		 */
		public _deselect(): void {
			let input = this._getInputElement();
			if (input) {
				let ss = input.selectionStart;
				let se = input.selectionEnd;
				if (ss != se) {
					input.setSelectionRange(se, se);
				}
			}
		}

		/**
		 * 이벤트를 등록합니다 (DateMask 호환).
		 */
		public addEventListener(type: string, func: Function): void {
			if (!this._listeners[type]) {
				this._listeners[type] = [];
			}
			this._listeners[type].push(func);
		}

		/**
		 * 이벤트 등록을 해제합니다 (DateMask 호환).
		 */
		public removeEventListener(type: string, func: Function): void {
			if (!this._listeners[type]) {
				return;
			}
			let idx = this._listeners[type].indexOf(func);
			if (idx >= 0) {
				this._listeners[type].splice(idx, 1);
			}
		}

		/**
		 * 마스크에서 사용하는 객체를 정리합니다.
		 */
		public dispose(): void {
			this._listeners = null;
			this._maskOwner = null;
		}

		/**
		 * 등록된 리스너를 호출합니다.
		 */
		private _dispatchEvent(type: string, e?: Event): void {
			if (!this._listeners[type]) {
				return;
			}
			this._listeners[type].forEach(function (fn) { fn(e); });
		}

		private _getMeridiemIndex(mm: moment.Moment): number {
			return mm && mm.isValid() && mm.hour() >= 12 ? 1 : 0;
		}

		/**
		 * 버퍼에 쓰여진 24시간제 시각 데이터에 맞추어 오전/오후 상태 인덱스를 재동기화합니다.
		 */
		private _syncMeridiemFromBuffer(): void {
			let hDigitIdx = this._findSegBufIdx('h');
			if (hDigitIdx < 0) {
				hDigitIdx = this._findSegBufIdx('H');
			}
			if (hDigitIdx < 0) {
				hDigitIdx = this._findSegBufIdx('k');
			}
			if (hDigitIdx < 0) {
				return;
			}
			let segRange = this._getSegmentBufferRange(hDigitIdx);
			let str = '';
			for (let i = segRange.start; i <= segRange.end; i++) {
				if (this._isEmptyChar(this._digitBuffer[i])) {
					return;
				}
				str += this._digitBuffer[i];
			}
			let hour = parseInt(str, 10);
			let segType = this._segmentTypes[hDigitIdx];

			// 24시간제 시각에 맞춰 오전(0) / 오후(1) 인덱스 보정
			if (segType === 'H' || segType === 'k') {
				this._storedMeridiemIndex = (hour >= 12 && hour < 24) ? 1 : 0;
			}
		}

		/**
		 * 마스크 포맷에 H/HH/k/kk(24시간제) editable 토큰과 a/A display 토큰이 함께 있는지 확인합니다.
		 */
		private _has24HourFormatWithMeridiem(): boolean {
			this._ensureParsed();
			let has24H = false, hasMeridiem = false;
			for (let ti = 0; ti < this._tokens.length; ti++) {
				let tok = this._tokens[ti];
				let firstChar = tok.token.charAt(0);
				if (tok.type === 'editable' && (firstChar === 'H' || firstChar === 'k')) { has24H = true; }
				if (tok.type === 'display' && (tok.token === 'a' || tok.token === 'A')) { hasMeridiem = true; }
			}
			return has24H && hasMeridiem;
		}

		/**
		 * 포맷에 d/dd/ddd/dddd(요일) editable/display 토큰이 포함되어 있는지 확인합니다.
		 */
		private _hasWeekdayFormat(): boolean {
			this._ensureParsed();
			for (let ti = 0; ti < this._tokens.length; ti++) {
				let tok = this._tokens[ti];
				if (tok.token.charAt(0) === 'd') {
					return true;
				}
			}
			return false;
		}

		/**
		 * 포맷에 a/A(오전/오후) display 토큰이 포함되어 있는지 확인합니다.
		 */
		private _hasMeridiemFormat(): boolean {
			this._ensureParsed();
			for (let ti = 0; ti < this._tokens.length; ti++) {
				let tok = this._tokens[ti];
				if (tok.token === 'a' || tok.token === 'A') {
					return true;
				}
			}
			return false;
		}

		private _toggleMeridiem(): void {
			this._storedMeridiemIndex = this._storedMeridiemIndex == 0 ? 1 : 0;
		}

		private _formatMeridiem(token: string, englishOnly: boolean = false): string {
			let meridiems = englishOnly ? ["am", "pm"] : (this.getMeridiems(this._locale) || ["am", "pm"]);
			let text = meridiems[this._storedMeridiemIndex] || meridiems[0] || "";
			if (token == "A") {
				text = text.toLocaleUpperCase();
			}
			return text;
		}

		/**
		 * 미완성 세그먼트의 빈자리를 자동으로 채워줍니다 (e.g. "1_" -> "01").
		 */
		private _applyAutoPadding(): void {
			this._ensureParsed();
			let bufIdx = 0;
			for (let ti = 0; ti < this._tokens.length; ti++) {
				let tok = this._tokens[ti];
				if (tok.type !== 'editable') {
					continue;
				}

				// 현재 세그먼트의 버퍼 내 글자들을 추출
				let segChars: string[] = [];
				for (let ci = 0; ci < tok.displayLen; ci++) {
					segChars.push(this._digitBuffer[bufIdx + ci]);
				}

				// 숫자가 최소 한 개 이상 있고, 빈자리(placeholder)도 섞여 있는 경우
				let hasDigit = segChars.some(ch => /^[0-9]$/.test(ch));
				let hasPlaceholder = segChars.some(ch => this._isEmptyChar(ch));

				if (hasDigit && hasPlaceholder) {
					// 숫자만 모아서 추출 (e.g. ["1", "_"] -> "1")
					let digitStr = segChars.filter(ch => /^[0-9]$/.test(ch)).join('');

					// 세그먼트 길이에 맞춰 우측 정렬 후 왼쪽에 '0'을 패딩
					let padded = digitStr;
					while (padded.length < tok.displayLen) {
						padded = '0' + padded;
					}

					// 보정된 값을 다시 버퍼에 대입
					for (let ci = 0; ci < tok.displayLen; ci++) {
						this._digitBuffer[bufIdx + ci] = padded.charAt(ci);
					}
				}

				bufIdx += tok.displayLen;
			}
		}

		/**
		 * 완전히 비어있는 세그먼트들을 오늘 날짜(또는 기본 날짜)의 값으로 채웁니다.
		 * 사용자가 부분 입력한 값은 유지하고 스핀 연산이 가능하도록 버퍼를 완성합니다.
		 */
		private _fillEmptySegmentsWithDefaultDate(): void {
			this._ensureParsed();
			// 먼저 미완성 세그먼트의 0 패딩 처리 실행
			this._applyAutoPadding();

			// 기본 날짜 moment 객체 생성 (기본값 설정 로직 참조)
			let mm = moment(this._defaultDate);
			if (moment(this._minDate).isSameOrBefore(this._maxDate)) {
				if (mm.isAfter(this._maxDate)) {
					mm = moment(this._maxDate);
				} else if (mm.isBefore(this._minDate)) {
					mm = moment(this._minDate);
				}
			}

			let bufIdx = 0;
			for (let ti = 0; ti < this._tokens.length; ti++) {
				let tok = this._tokens[ti];
				if (tok.type !== 'editable') {
					continue;
				}

				// 해당 세그먼트가 전부 비어있는지 확인
				let allEmpty = true;
				for (let ci = 0; ci < tok.displayLen; ci++) {
					if (!this._isEmptyChar(this._digitBuffer[bufIdx + ci])) {
						allEmpty = false;
						break;
					}
				}

				// 아예 비어있는 세그먼트만 기본 날짜 값으로 채움
				if (allEmpty) {
					let formatted = mm.format(tok.token);
					for (let ci = 0; ci < tok.displayLen; ci++) {
						this._digitBuffer[bufIdx + ci] = formatted.charAt(ci) || this._getPlaceholderChar();
					}
				}

				bufIdx += tok.displayLen;
			}
		}
	}
}
