namespace cpr.ufc {
	let log = utils.Logger.forTopic("renderer")._createBindedLoggerFunction({
		updator: it => log = it
	});

	const _UUID_MAPPER = NodeUUIDMapper.INSTANCE;

	/**
	 * 데코레이터 타입.
	 */
	export type ControlShapeDecorator = (controlShape: ControlShape) => ControlShape;

	type UIShapeConvertOptions = {
		/** 자식 {@link UIShape} 공급자. */
		childShapeProvider: (renderer: ControlRenderer, lazyTaskManager: LazyTaskManager) => UIShape,

		/** 레이지 태스크 매니저. 생략 가능. */
		lazyTaskManager?: LazyTaskManager,

		/** 쉐이프의 소유주 */
		owner: core.DrawableControl,

		/** 새로운 쉐이프인지 여부 */
		isNew: boolean,

		/** 레이지 쉐이프인지 여부. */
		isLazy: boolean,

		/** 글로벌 맵 */
		globalMap: CMap<core.DrawableControl, UIShape>,

		/** 어사이드 맵 */
		asideMap: CMap<core.DrawableControl, ElementShape>
	};

	/**
	 * 다음 틱에 노드를 제거합니다.
	 * @param element 제거할 노드.
	 */
	function _removeElementInNextTick(element: HTMLElement) {
		core.DeferredUpdateManager.INSTANCE._asyncExecBefore(() => {
			if (element && element.parentElement) {
				element.parentElement.removeChild(element);
			}
		});
	}

	/**
	 * @private
	 */
	export class ControlRenderer implements resources.IDisposable {
		/**
		 * HTMLElement를 식별할 수 있는 키를 저장할 AttributeName
		 * node uudid
		 **/
		public static readonly _ATTR_UUID: string = "data-ndid";

		/**
		 * Renderer와 연결된 컨트롤의 RootNode 이름.
		 * @see getNamedNode
		 * @see updateStyle
		 * @see insert
		 * @see replace
		 */
		public static readonly _NODE_NAME__CONTROL_ROOT: string = "CONTROL-ROOT-NODE";

		/** 렌더러 소유 컨트롤 */
		protected _control: core.DrawableControl;

		/** 디스포즈 플래그 */
		protected _disposed: boolean = false;

		private _oldControlShape: ControlShape = null; /* TODO oldShape을 UIShape으로 사용하는 방안 검토 */

		/**
		 * 데코레이터 맵
		 */
		private _decorators: CMap<string, ((controlShape: ControlShape) => ControlShape)>;

		/**
		 * 스타일러가 적용중인 노드 배열 맵.
		 */
		private _stylerNodes: { [stylerName: string]: node_name[] } = {};

		private _nodeNameToUUID: CMap<node_name, node_uuid> = _createMap();
		private _uuidToShape: CMap<node_uuid, ElementShape> = _createMap();

		private _removalNodeNameToUUID: CMap<node_name, node_uuid> = _createMap();
		private _newNodeNameToUUID: CMap<node_name, node_uuid> = _createMap();

		/** css text 생성중 메모리상의 중복 문자열일 줄이기 위한 인턴 풀 */
		private _internPool: StringInternPool;

		// shape 요소 중 VirtualScrollPane 이 적용된 nodename과 VirtualScrollPane 객체
		private _virtualScrollPanes: CMap<node_name, controls.internal.VirtualScrollPane> = _createMap();
		private _nativeScrollPanes: CMap<node_name, controls.internal.NativeScrollPane> = _createMap();



		/**
		 * HTMLElement의 타게팅 식별 UUID를 얻습니다.
		 * @param element 식별 아이디를 얻을 노드.
		 * @returns 식별자.
		 */
		public static getTargetUUID(element: HTMLElement): node_uuid {
			return element.getAttribute(ControlRenderer._ATTR_UUID);
		}

		/**
		 * 주어진 HTMLElement를 포함하는 가장 가까운 컨트롤의 UUID를 얻습니다.
		 * @param element 컨트롤을 식별할 노드.
		 */
		public static _getClosestControlUUID(element: HTMLElement): control_uuid {
			let controlUUID = _UUID_MAPPER._findClosestControlUUID(element);
			return controlUUID;
		}

		/**
		 * 주어진 노드로 부터 부모방향으로 {@link _ATTR_UUID}를 가진 첫 노드를 찾아 반환 합니다.
		 * @param element 검색 시작 노드.
		 * @param rootElement 검색 종료 노드.
		 * @returns {@link _ATTR_UUID}를 가진 첫 노드
		 */
		public static findElementHasTargetUUID(element: HTMLElement, rootElement: HTMLElement): HTMLElement {
			let traverser: DOMTraverser = _traverseFromElement(element);
			traverser = traverser._closest(`[${ControlRenderer._ATTR_UUID}]`, rootElement);
			if (traverser) {
				let target: HTMLElement = traverser._getElement();
				traverser.dispose();
				return target;
			}
			return null;
		}

		constructor(control: core.DrawableControl) {
			this._control = control;
			this._decorators = _createMap();
			this._internPool = _createStringInternPool(control instanceof controls.Grid ? 70 : 30);
		}

		public get disposed(): boolean {
			return this._disposed;
		}

		/**
		 * 랜더링된 최상위 노드를 얻습니다.
		 * 이 노드는 컨트롤 Shape의 최상위 노드이거나 레이아웃에 의한 래퍼 노드일 수 있습니다.
		 */
		public _getRenderedRootNode(): HTMLElement {
			if (this.hasDrawn() == false) {
				return null;
			}
			let rootID: string = _UUID_MAPPER._getControlNodeID(this._control as controls.UIControl);
			let domElement: HTMLElement = document.getElementById(rootID);

			return domElement;
		}

		/**
		 * 컨트롤이 작성한 Shape 내에서의 최상위 노드를 얻습니다.
		 */
		public getRootNode(): HTMLElement {
			if (this.hasDrawn() == false) {
				return null;
			}
			let rootID = _UUID_MAPPER._getControlNodeID(this._control as controls.UIControl);
			let node = document.getElementById(rootID);
			if (node) {
				let traverser: DOMTraverser = _traverseFromElement(node);
				traverser = traverser._find(`[${ControlRenderer._ATTR_UUID}='${rootID}']`);
				if (traverser) {
					node = traverser._getElement();
				} else {
					node = null;
				}
			}

			return node;
		}

		/**
		 * 명명된 노드를 얻습니다.
		 * 컨트롤 또는 해당 명칭을 가진 노드가 렌더링된 적이 없으면 null이 반환됩니다.
		 * 
		 * @param nodename 얻으려는 노드의 명칭.
		 */
		public getNamedNode(nodename: string): HTMLElement {
			let targetUUID = this._getNamedNodeUUID(nodename);
			if (typeof targetUUID !== "string") {
				return null;
			}

			let rootID: string = _UUID_MAPPER._getControlNodeID(this._control as controls.UIControl);
			let selector: string = `[${ControlRenderer._ATTR_UUID}="${targetUUID}"]`;

			// 컨트롤 범주 검색
			let htmlElement: HTMLElement = this._searchDOM(rootID, selector);
			if (htmlElement == null) {
				// 글로벌 검주 검색
				rootID = _UUID_MAPPER._getGlobalControlNodeID(this._control as controls.UIControl);
				htmlElement = this._searchDOM(rootID, selector);
			}

			return htmlElement;
		}

		/**
		 * 명명된 노드의 NDID를 얻습니다.
		 * @param nodename 노드의 명칭.
		 */
		public _getNamedNodeUUID(nodename: string): node_uuid {
			if (this.hasDrawn() == false) {
				return null;
			}
			let targetUUID = this._nodeNameToUUID.get(nodename);
			return targetUUID;
		}

		/**
		 * 명명된 노드의 {@link ElementShape}(올드)를 얻습니다. 
		 * @param nodename 노드의 이름.
		 */
		public _getNamedShape(nodename: string): ElementShape {
			if (this.hasDrawn() == false) {
				return null;
			}
			let targetUUID: string = this._nodeNameToUUID.get(nodename);
			if (typeof targetUUID == "string") {
				let oldShape = this._uuidToShape.get(targetUUID);
				return oldShape;
			}
			return null;
		}

		public addLayoutDecorator(decorator: ControlShapeDecorator): void {
			this.addDecorator(controls.layouts.LayoutConstants.DECORATOR_NAME__LAYOUT, decorator);
		}

		public addDecorator(name: string, decorator: ControlShapeDecorator): void {
			this._decorators.set(name, decorator);
		}

		public removeDecorator(name: string): ControlShapeDecorator {
			if (this._decorators.has(name)) {
				let decorator = this._decorators.get(name);
				this._decorators.delete(name);
				return decorator;
			} else {
				return null;
			}
		}

		public removeLayoutDecorator(): ControlShapeDecorator {
			return this.removeDecorator(controls.layouts.LayoutConstants.DECORATOR_NAME__LAYOUT);
		}

		public removeAllDecorators(): void {
			this._decorators.clear();
		}

		public render(pieceRenderer: PieceRenderer): void {
			if (pieceRenderer) {
				pieceRenderer._render(this);
			}
		}

		/**
		 * 대상 컨트롤이 아직 고용되지 않은 UDC 컨트롤의 컨테이너인지 확인 합니다.
		 */
		private _isDangledUDCContainer(): boolean {
			// 컨테이너 여부 체크.
			if (this._control instanceof controls.Container === false) {
				return false;
			}

			let container = this._control as controls.Container;

			// 앱 인스턴스용 컨테이너인지 체크.
			if (container.isAppContainer === false) {
				return false;
			}

			// 호스트가 UDC인지 체크.
			let selfAppInstance = container.getAppInstance();
			let host = selfAppInstance ? selfAppInstance.getHost() : null;
			if (host instanceof controls.UDCBase === false) {
				return false;
			}

			// 호스트의 소속 앱 인스턴스 체크.
			return host.getAppInstance() == null;
		}

		public draw(): void {
			if (this._control == null) {
				return;
			}

			/*
			 * 댕글된 UDC 컨테이너인 경우 그리지 않습니다.
			 * http://scm.exbuilder.co.kr/cleopatra-dev-team/release-test-project/issues/331
			 */
			if (this._isDangledUDCContainer()) {
				return;
			}

			/* Control이 Container의 하위 클래스가 아닌 경우
			 * Parent가 없으면 draw 메소드는 호출될 수 없다.
			 * Parent가 있을 경우 Parent가 그려지기 전에는 개별Control의 draw 메소드는 호출될 수 없다.
			 * 최초 그려질 때는 Container에 의해서만 그려질 수 있다. */
			// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/issues/3898
			// getParent() 대신 getVisualParentControl()로 대체. -- jeeeyul
			let parentControl: core.DrawableControl = this._control.getVisualParentControl();

			// 부모 상태에 따른 그리기 취소
			if (parentControl) {
				if (parentControl.disposed == true
					|| parentControl._getRenderer().hasDrawn() === false
					|| this.hasDrawn() === false) {
					return;
				}
			}

			// 과거 쉐이프를 얻음.
			let oldGlobalMap = _createMap<core.DrawableControl, UIShape>();
			let oldAsideMap = _createMap<core.DrawableControl, ElementShape>();
			let oldShape: UIShape = this._getOldUIShape(oldGlobalMap, oldAsideMap, false);

			// 새로운 쉐이프 구성
			let lazyTaskManager: ufc.LazyTaskManager = ufc._createLazyTaskManager();
			let newGlobalMap = _createMap<core.DrawableControl, UIShape>();
			let newAsideMap = _createMap<core.DrawableControl, ElementShape>();
			let newShape: UIShape = this._createNewUIShape(newGlobalMap, newAsideMap, lazyTaskManager);

			// vdom, innerHTML hybrid(Rule)
			let useVDOM: boolean = true;
			let renderSuccess: boolean = true;

			if (oldShape) {
				log("vdom : " + this._control.type);
				renderSuccess = VDOMRendering.draw(oldShape.attr["id"], newShape, oldShape);
				useVDOM = true;
			} else if (newShape) {
				log("dom : " + this._control.type);
				renderSuccess = HTMLRendering.draw(newShape.attr["id"], newShape, oldShape);
				useVDOM = false;
			}

			// 렌더링 성공 처리
			if (renderSuccess) {
				this._applyGlobalShape(oldGlobalMap, newGlobalMap);
				this._applyAsideShape(oldAsideMap, newAsideMap);

				// lazy shape
				this._doLazyTask(lazyTaskManager, useVDOM);
			}

			// 렌더링 실패 처리.
			else {
				// CASE: rootNode가 없고 oldShape가 있는 경우 그리드에 넘버에디터 넣고 넘버에디터 값 입력 후 엔터 키 누르면 발생.(https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/9932)
				this._oldControlShape = null;
				this._stylerNodes = {};
				this._nodeNameToUUID.clear();
				this._uuidToShape.clear();

				this._clearScrollPanes();

				EventAttacher.detach(this._control.uuid);

				_UUID_MAPPER._disposeControlUUID(this._control as controls.UIControl);
			}
		}

		private _applyGlobalShape(oldGlobalMap: CMap<core.DrawableControl, UIShape>, newGlobalMap: CMap<core.DrawableControl, UIShape>): void {
			if (oldGlobalMap.size > 0 || newGlobalMap.size > 0) {
				let appInstance: core.AppInstance = this._searchRootAppInstance();
				let globalContainerUUID: string = _UUID_MAPPER._getGlobalControlNodeID(appInstance.getContainer());
				if (oldGlobalMap.size > 0) {
					oldGlobalMap.forEach((shape, key) => {
						let newGlobalShape = newGlobalMap.get(key);
						newGlobalMap.delete(key);
						log("vdom global : " + this._control.type);
						let rootId: string = shape.attr["id"];
						if (newGlobalShape) {
							VDOMRendering.draw(rootId, newGlobalShape, shape, globalContainerUUID);
						} else {
							VDOMRendering.draw(rootId, null, shape, globalContainerUUID);
						}
					})

				}
				if (newGlobalMap.size > 0) {
					// 향후 global shape을 특정 element 하위에 위치시킬 필요가 있을 때 구현하여 확장
					newGlobalMap.forEach((shape, key) => {
						log("dom global : " + this._control.type);
						let rootId: string = shape.attr["id"];
						HTMLRendering.draw(rootId, shape, null, globalContainerUUID);
					});
				}
			}
		}

		private _applyAsideShape(oldAsideMap: CMap<core.DrawableControl, ElementShape>, newAsideMap: CMap<core.DrawableControl, ElementShape>): void {
			if (oldAsideMap.size == 0 && newAsideMap.size == 0) {
				return;
			}

			oldAsideMap.forEach((oldShape, key) => {
				let control: controls.UIControl = key as controls.UIControl;
				let container: controls.Container = control instanceof controls.Container ? control : control.getParent();
				let newAsideShape = newAsideMap.get(key);
				newAsideMap.delete(key);

				// 업데이트
				if (newAsideShape) {
					newAsideShape.owner = control;
					container._updateAsideShapeToAppContainer(control, newAsideShape);
				}
				// 삭제
				else {
					container._removeAsideShapeFromAppContainer(control);
				}
			});

			newAsideMap.forEach((newShape, key) => {
				let control: controls.UIControl = key as controls.UIControl;
				let container: controls.Container = control instanceof controls.Container ? control : control.getParent();
				newShape.owner = control;

				container._addAsideShapeToAppContainer(control, newShape);
			});
		}

		/**
		 * DrawLazyTask는 빈 div 노드를 임시로 생성된 후 DrawLazyTask의 노드를 null로 반환하는 경우 노드가 제거됩니다.
		 * 형제 노드가 있는 경우 순서 변경에 의해 형제들이 removeChild, intertChildBefore 가 호출되어 노드에 영향이 발생합니다.
		 * @param lazyTaskManager 
		 * @param isVDOM 
		 */
		private _doLazyTask(lazyTaskManager: ufc.LazyTaskManager, isVDOM: boolean): void {
			lazyTaskManager.runAll((lazyTask) => {
				if (lazyTask instanceof DrawLazyTask) {

					let containerNm: string = lazyTask.nodename;
					let newShape: ElementShape = null;
					utils.tryCatch({
						do: () => {
							newShape = lazyTask.doTask();
						},
						catch: (e) => {
							utils.logError(e);
							newShape = ShapeUtil._getErrorShape(e);
						},
						_report: true,
						_context: exceptions.ErrorContext.RENDERING_FAIL
					});
					if (newShape) {
						newShape["nodename"] = containerNm;
					}
					if (lazyTask.owner == this._control) {
						this._replace(containerNm, newShape, isVDOM);
					} else {
						let shapeOwner: core.DrawableControl = lazyTask.owner;
						let renderer: ControlRenderer = shapeOwner._getRenderer();
						renderer._replace(containerNm, newShape, isVDOM);
					}
				} else if (lazyTask instanceof TapLazyTask) {
					utils.tryCatch({
						do: () => {
							lazyTask.doTask();
						},
						catch: (e) => {
							utils.logError(e);
						},
						_report: true,
						_context: exceptions.ErrorContext.RENDERING_FAIL
					});
				}
			});
		}

		public insert(containerNm: string, index: number, newShape: (ElementShape | ControlRenderer)[]): void {
			let nodeUUID: string = this._nodeNameToUUID.get(containerNm);
			if (!nodeUUID) {
				log(containerNm + " Not Found");
				return;
			}

			let containerElement: HTMLElement = this.getNamedNode(containerNm);
			let targetElement: HTMLElement = containerElement.children.item(index) as HTMLElement;
			let childElements: HTMLElement[] = [];
			let newUIShapes: UIShape[] = [];

			let lazyTaskManager: ufc.LazyTaskManager = ufc._createLazyTaskManager();
			let newGlobalMap = _createMap<core.DrawableControl, UIShape>();
			let newAsideMap = _createMap<core.DrawableControl, ElementShape>();

			for (let idx: number = 0; idx < newShape.length; idx++) {
				let newUIShape: UIShape = null;
				if (newShape[idx] == null) {
					continue;
				} else if (newShape[idx] instanceof ControlRenderer) {
					// ControlRenderer
					newUIShape = (newShape[idx] as ControlRenderer)._getNewUIShape(newGlobalMap, newAsideMap, lazyTaskManager);
				} else {
					this._preProcNodeName();

					// ElementShape
					newUIShape = this._convertToUIShape(newShape[idx] as ElementShape, {
						childShapeProvider: (renderer: ControlRenderer) => renderer._getNewUIShape(newGlobalMap, newAsideMap, lazyTaskManager),
						lazyTaskManager: lazyTaskManager,
						owner: this._control,
						isNew: true,
						isLazy: false,
						globalMap: newGlobalMap,
						asideMap: newAsideMap
					});

					this._postProcNodeName();
				}
				let rootElement: HTMLElement = document.createElement(newUIShape.tag);
				childElements.push(rootElement);
				newUIShapes.push(newUIShape);
			}
			let containerShape = this._uuidToShape.get(nodeUUID);
			if (targetElement) {
				childElements.forEach((htmlTag: HTMLElement) => {
					containerElement.insertBefore(htmlTag, targetElement);
				});
				containerShape.children = containerShape.children.slice(0, index).concat(newShape).concat(containerShape.children.slice(index));
			} else {
				childElements.forEach((htmlTag: HTMLElement) => {
					containerElement.appendChild(htmlTag);
				});
				containerShape.children = containerShape.children.concat(newShape);
			}
			for (let idx: number = 0; idx < childElements.length; idx++) {
				let rootElement: HTMLElement = childElements[idx];
				let newUIShape: UIShape = newUIShapes[idx];
				HTMLRendering.drawElement(rootElement, newUIShape, null);
			}

			this._applyGlobalShape(_createMap<core.DrawableControl, UIShape>(), newGlobalMap);
			this._applyAsideShape(_createMap<core.DrawableControl, ElementShape>(), newAsideMap);

			this._doLazyTask(lazyTaskManager, false);
		}

		public deleteChild(parentNodeName: string, child: ElementShape | ControlRenderer): void {
			let nodeUUID = this._nodeNameToUUID.get(parentNodeName);
			if (!nodeUUID) {
				log(`nodeUUID of ${parentNodeName} is Not Found`);
				return;
			}
			let parentElement: HTMLElement = this.getNamedNode(parentNodeName);
			if (!parentElement) {
				log(`HTMLElement of ${parentNodeName} is Not Found`);
				return;
			}

			let parentShape = this._uuidToShape.get(nodeUUID);
			if (parentShape && parentShape.children) {
				let childIndex: number = parentShape.children.indexOf(child);
				if (childIndex === -1) {
					log(`target Shape is Not Found`);
					return;
				}

				let targetElement: HTMLElement = parentElement.children.item[childIndex];
				if (targetElement) {
					parentElement.removeChild(targetElement);
				} else {
					log(`target HTMLElement is Not Found`);
				}

				parentShape.children.splice(childIndex, 1);

				if (child instanceof ControlRenderer) {
					if (child._control) {
						EventAttacher.detach(child._control.uuid);
					}
				} else { // ElementShape
					// clear eventhandler and nodename ref
					this._clearHandlerAndNodeName(child as ElementShape);
				}
			}
		}
		public delete(nodeName: string): void {
			let nodeUUID = this._nodeNameToUUID.get(nodeName);
			if (!nodeUUID) {
				log(nodeName + " Not Found");
				return;
			}
			let nodeElement: HTMLElement = this.getNamedNode(nodeName);
			if (!nodeElement) {
				log(nodeName + " Not Found");
				return;
			}
			let parentElement: HTMLElement = nodeElement.parentElement;
			parentElement.removeChild(nodeElement);

			let oldShape: ControlShape = this._getOldControlShape();
			let target = this._uuidToShape.get(nodeUUID);
			this._deleteChildShape(oldShape, target);

			// clear eventhandler and nodename ref
			this._clearHandlerAndNodeName(target);
		}

		private _clearHandlerAndNodeName(target: ElementShape): void {
			let nodenames: string[] = [];
			let targetUUIDs: {
				[targetUUID: string]: {
					[eventType: string]: (e: events.CEvent) => void;
				};
			} = {};

			// clear targetShape
			this._collectChildNodeNames(target, nodenames, targetUUIDs);
			for (let idx: number = 0; idx < nodenames.length; idx++) {
				let childNodeName: string = nodenames[idx];
				let childNodeUUID: string = this._nodeNameToUUID.get(childNodeName);
				this._nodeNameToUUID.delete(childNodeName);
				if (childNodeUUID) {
					this._uuidToShape.delete(childNodeUUID);
				}
			}

			// clear eventHandlers
			let eventBus: events.EventBus = events.EventBus.INSTANCE;
			let targetUUID: string[] = _.keys(targetUUIDs);
			for (let idx: number = 0; idx < targetUUID.length; idx++) {
				let tUUID: string = targetUUID[idx];
				let eventMap: { [eventType: string]: (e: events.CEvent) => void; } = targetUUIDs[tUUID];
				eventBus._removeControlShapeHandler(this._control.uuid, tUUID, eventMap);
			}
		}

		private _collectChildNodeNames(target: ElementShape, nodenames: string[], targetUUIDs: {
			[targetUUID: string]: {
				[eventType: string]: (e: events.CEvent) => void;
			};
		}): void {
			if (!target) {
				return;
			}
			if (target.attr) {
				let targetUUID: string = target.attr[ControlRenderer._ATTR_UUID];
				if (targetUUID) {
					let eventMap: { [eventType: string]: (e: events.CEvent) => void } = target._eventMap;
					if (eventMap) {
						targetUUIDs[targetUUID] = eventMap;
					}
				}
			}
			if (target["nodename"]) {
				nodenames[nodenames.length] = target["nodename"];
			}
			if (target.children && target.children.length > 0) {
				for (let idx: number = 0; idx < target.children.length; idx++) {
					let child: ufc.ElementShapeContent = target.children[idx];
					if (_isElementShape(child)) {
						this._collectChildNodeNames(child as ElementShape, nodenames, targetUUIDs);
					}
				}
			}
		}

		private _deleteChildShape(shape: ElementShape, target: ElementShape): boolean {
			if (shape == null) {
				return;
			}
			let children: ufc.ElementShapeContent[] = shape.children;
			if (!children) {
				return;
			}
			let idx: number = children.indexOf(target);
			if (idx > -1) {
				children.splice(idx, 1);
				return true;
			}
			for (idx = 0; idx < children.length; idx++) {
				let child: ufc.ElementShapeContent = children[idx];
				if (typeof child == "string" || child instanceof ControlRenderer) {
					continue;
				}
				let deleted: boolean = this._deleteChildShape(child as ElementShape, target);
				if (deleted == true) {
					return true;
				}
			}
			return false;
		}

		public replace(containerNm: string, newShape: ElementShape): void {
			this._replace(containerNm, newShape, true);
		}

		private _replace(containerNm: string, newShape: ElementShape, isVDOM: boolean): void {
			log(`replace: ${this._control.type} - ${containerNm}`);

			let nodeUUID = this._nodeNameToUUID.get(containerNm);
			if (!nodeUUID) {
				log(containerNm + " Not Found");
				return;
			}
			let targetElement: HTMLElement = this.getNamedNode(containerNm);
			if (!targetElement) {
				log(containerNm + " Not Found");
				return;
			}

			if (newShape) {
				newShape.nodename = containerNm;
			}

			/* replace는 반드시 oldshape과 newShape이 존재해야 하고 elementshape type만 처리 가능 */
			let oldGlobalMap = _createMap<core.DrawableControl, UIShape>();
			let oldAsideMap = _createMap<core.DrawableControl, ElementShape>();
			let oldShape = this._uuidToShape.get(nodeUUID);

			this._preProcNodeName();

			/* oldshape */
			let oldUIShape: UIShape = this._convertToUIShape(oldShape, {
				childShapeProvider: (renderer: ControlRenderer) => renderer._getOldUIShape(oldGlobalMap, oldAsideMap, false),
				lazyTaskManager: null,
				owner: this._control,
				isNew: false,
				isLazy: false,
				globalMap: oldGlobalMap,
				asideMap: oldAsideMap
			});

			/* newShape */
			let lazyTaskManager: ufc.LazyTaskManager = ufc._createLazyTaskManager();
			let newGlobalMap = _createMap<core.DrawableControl, UIShape>();
			let newAsideMap = _createMap<core.DrawableControl, ElementShape>();
			let newUIShape = this._convertToUIShape(newShape, {
				childShapeProvider: (renderer: ControlRenderer) => renderer._getNewUIShape(newGlobalMap, newAsideMap, lazyTaskManager),
				lazyTaskManager: lazyTaskManager,
				owner: this._control,
				isNew: true,
				isLazy: false,
				globalMap: newGlobalMap,
				asideMap: newAsideMap
			});

			this._postProcNodeName();

			if (isVDOM === true) {
				VDOMRendering.drawElement(targetElement, newUIShape, oldUIShape);
			} else {
				HTMLRendering.drawElement(targetElement, newUIShape, oldUIShape);
			}

			for (let attr in oldShape) {
				delete oldShape[attr];
			}
			if (newShape != null) {
				for (let attr in newShape) {
					oldShape[attr] = newShape[attr];
				}
			}
			/*
			 * convertToUIShape을 하는 과정에서 nodename의 id가 새로 발급되고
			 * 새로 발급된 uuid로 nodenamemap에 등록되는데 ControlRenderer의 oldShape에
			 * 붙어있는 shape 객체는 이전에 있던 객체이므로 이전 객체에 새로운 attribute를
			 * 붙이고 새로발급된 uuid에 이전 객체를 등록한다.
			 */
			let newNodeUUID: string = this._nodeNameToUUID.get(containerNm);
			this._uuidToShape.set(newNodeUUID, oldShape);

			this._applyGlobalShape(oldGlobalMap, newGlobalMap);
			this._applyAsideShape(oldAsideMap, newAsideMap);

			this._doLazyTask(lazyTaskManager, isVDOM);
		}

		public removeStyle(nodename: string, styleNames: string[] = []) {
			let node: HTMLElement = null;
			let shape: ElementShape = null;
			if (nodename) {
				// control named node
				node = this.getNamedNode(nodename);
				shape = this._getNamedShape(nodename);
			} else {
				// control root node
				node = this._getRenderedRootNode();
				shape = this._getOldControlShape();
			}

			let style = _shallowCopyObject(shape["style"]);
			for (let each of styleNames) {
				delete style[each];
			}

			this.updateStyle(nodename, style);
		}

		public updateStyle(nodename: string, style: { [key: string]: string }, merge: boolean = false): boolean {
			let node: HTMLElement = null;
			let shape: ElementShape = null;
			if (nodename) {
				// control named node
				node = this.getNamedNode(nodename);
				shape = this._getNamedShape(nodename);
			} else {
				// control root node
				node = this._getRenderedRootNode();
				shape = this._getOldControlShape();
			}

			if (node == null || shape == null) {
				return false;
			}

			if (merge == true) {
				style = _assign(shape["style"], style);
			}
			shape["style"] = style;

			let cssArray: string[] = null;
			// 스타일러 처리
			if (shape.hasOwnProperty("styler")) {
				let stylerName: string = shape.styler;
				let styler: controls.UIControlStyler = null;
				if (stylerName == "root") {
					styler = this._control.style as controls.UIControlStyler;
				} else {
					styler = this._control.style[stylerName] as controls.UIControlStyler;
				}
				let mixedStyle: { classNames: string[], cssText: string[] } = ShapeUtil.mixShapeNStyler(shape, styler, this._control);
				cssArray = mixedStyle.cssText;
			} else {
				cssArray = _createCSSArray(style);
			}

			return ShapeUtil._applyStyle(shape, node, cssArray, this._internPool);
		}

		public updateClass(nodename: string, removalClasses: css_class_string[], additionalClasses: css_class_string[]): string[] {
			let node: HTMLElement = null;
			let shape: ElementShape = null;
			if (nodename) {
				// control named node
				node = this.getNamedNode(nodename);
				shape = this._getNamedShape(nodename);
			} else {
				// control root node
				node = this._getRenderedRootNode();
				shape = this._getOldControlShape();
			}

			if (node == null || shape == null) {
				return null;
			}

			let classNames: css_class_string[] = _.union([], shape["classNames"]);
			let oldClassNames: css_class_string[] = [].concat(classNames);
			if (removalClasses) {
				removalClasses.forEach((className: string) => {
					classNames = _.without(classNames, className);
				});
			}
			classNames = _.union(classNames, additionalClasses);
			shape["classNames"] = classNames;

			let shapeClassNames: css_class_string[] = null;
			// 스타일러 처리
			if (shape.hasOwnProperty("styler")) {
				let stylerName: string = shape.styler;
				let styler: controls.UIControlStyler = null;
				if (stylerName == "root") {
					styler = this._control.style as controls.UIControlStyler;
				} else {
					styler = this._control.style[stylerName] as controls.UIControlStyler;
				}
				let mixedStyle: { classNames: string[], cssText: string[] } = ShapeUtil.mixShapeNStyler(shape, styler, this._control);
				shapeClassNames = mixedStyle.classNames;
			} else {
				shapeClassNames = shape["classNames"];
			}

			// classNames
			ShapeUtil._applyClassNames(shape, node, shapeClassNames);

			return oldClassNames;
		}

		/**
		 * 실제 DOM 및 올드 쉐이프의 스타일을 직접 수정 합니다.
		 * @param nodename 노드명
		 * @param classNames 새로운 클래스 명들.
		 * @param style 새로운 스타일 속성들.
		 * @param merge 머징으로 적용할 것인지 여부.
		 * @returns 변경 발생 여부.
		 */
		public updateCSS(nodename: string, classNames: css_class_string[], style: { [key: string]: string }, merge: boolean = false): boolean {
			let node: HTMLElement = null;
			let shape: ElementShape = null;
			if (nodename) {
				// control named node
				node = this.getNamedNode(nodename);
				shape = this._getNamedShape(nodename);
			} else {
				// control root node
				node = this._getRenderedRootNode();
				shape = this._getOldControlShape();
			}

			if (node == null || shape == null) {
				return false;
			}

			if (merge == true) {
				style = _assign(shape["style"], style);
				classNames = _.union([], shape["classNames"], classNames);
			}
			shape["style"] = style;
			shape["classNames"] = [].concat(classNames);

			let cssArray: string[] = null;
			let shapeClassNames: css_class_string[] = null;
			// 스타일러 처리
			if (shape.hasOwnProperty("styler")) {
				let stylerName: string = shape.styler;
				let styler: controls.UIControlStyler = null;

				if (stylerName == "root") {
					styler = this._control.style;
				} else {
					styler = this._control.style[stylerName];
				}

				let mixedStyle: { classNames: css_class_string[], cssText: string[] } = ShapeUtil.mixShapeNStyler(shape, styler, this._control);
				cssArray = mixedStyle.cssText;
				shapeClassNames = mixedStyle.classNames;
			} else {
				cssArray = _createCSSArray(style);
				shapeClassNames = shape["classNames"];
			}

			// style
			let styleUpdated: boolean = ShapeUtil._applyStyle(shape, node, cssArray, this._internPool);

			// class
			let classUpdated: boolean = ShapeUtil._applyClassNames(shape, node, shapeClassNames);

			return styleUpdated || classUpdated;
		}

		/**
		 * 스타일러의 상태를 올드 쉐이프 및 실제 렌더링된 상태의 노드에 모두 적용합니다.
		 * 
		 * {@link controls.UIControlStyler} 에 변경 사항일 적용 하기 위해 {@link StylerRenderer}에 의해 사용됩니다.
		 * 그 이외에 사용되지 않아야 합니다.
		 * 
		 * @param stylerName 스타일러 이름.
		 * @param styler 스타일러.
		 */
		public _applyStyler(stylerName: string, styler: controls.UIControlStyler): void {
			let nodenames = this._stylerNodes[stylerName];
			if (_isNullOrEmpty(nodenames)) {
				return;
			}

			nodenames.forEach((nodename: string) => {
				let shape = this._getNamedShape(nodename);
				if (!shape) {
					return;
				}

				let node = this.getNamedNode(nodename);
				if (!node) {
					return;
				}

				let mixedStyle: { classNames: string[], cssText: string[] } = ShapeUtil.mixShapeNStyler(shape, styler, this._control);

				// style
				ShapeUtil._applyStyle(shape, node, mixedStyle.cssText, this._internPool);

				// classNames
				ShapeUtil._applyClassNames(shape, node, mixedStyle.classNames);
			});
		}

		/**
		 * 소유 컨트롤의 htmlAttr() 속성 값들을 올드 {@link ElementShape} 및 실제 렌더링된 노드에 반영 합니다.
		 * 
		 * {@link HtmlAttrRenderer}에 의해 HTML Attr 속성이 변경된 경우 트리거 됩니다.
		 * 그 이외에 사용되지 않아야 합니다.
		 * 
		 */
		public _applyHtmlAttr(): void {
			if (this.disposed) {
				return;
			}
			// HTML Node
			let rootNode: HTMLElement = this.getRootNode();
			if (!rootNode) {
				let rootID: string = _UUID_MAPPER._getControlNodeID(this._control as controls.UIControl);
				log("rootNode Not Found. id & ndid : " + rootID);
				return;
			}
			// oldShape
			let rootShape: ElementShape = this._getNamedShape(ControlRenderer._NODE_NAME__CONTROL_ROOT);
			if (!rootShape) {
				let rootID: string = _UUID_MAPPER._getControlNodeID(this._control as controls.UIControl);
				log("rootShape Not Found. id & ndid : " + rootID);
				return;
			}

			// oldShapeAttrs
			let attrs: { [key: string]: string } = null;
			if (rootShape.attr) {
				attrs = rootShape.attr;
			} else {
				attrs = {};
				rootShape.attr = attrs;
			}
			let attrNames: string[] = [];
			for (let attrName in attrs) {
				let attrNm: string = attrName.toLowerCase();
				if (attrNm.indexOf("data-usr-") === 0) {
					attrNames[attrNames.length] = attrNm;
				}
			}

			let htmlAttrs: { [key: string]: string } = this._control.htmlAttr() as { [key: string]: string };
			for (let key in htmlAttrs) {
				let attrName: string = "data-usr-" + key;
				let attrValue: string = htmlAttrs[key];

				rootNode.setAttribute(attrName, attrValue); // DOM 반영

				let encodedName: string = utils.HTMLEncoder.encodeForHTMLAttribute(attrName.toLowerCase());
				attrs[encodedName] = utils.HTMLEncoder.encodeForHTMLAttribute(attrValue); // OldShape 반영

				let idx: number = attrNames.indexOf(encodedName);
				if (idx != -1) {
					attrNames.splice(idx, 1);
				}
			}

			// oldShape에서 삭제
			for (let idx = 0; idx < attrNames.length; idx++) {
				let attrName: string = attrNames[idx];

				rootNode.removeAttribute(attrName); // DOM에서 삭제
				delete attrs[attrName]; // Shape에서 삭제
			}
		}

		/**
		 * 렌더링 되었는지 여부
		 * @returns 
		 */
		public hasDrawn(): boolean {
			return this._oldControlShape == null ? false : true;
		}

		/**
		 * 마지막으로 렌더링된 {@link ControlShape}를 얻습니다.
		 */
		public _getOldControlShape(): ControlShape {
			return this._oldControlShape;
		}

		/**
		 * virtual, native 스크롤 객체들을 dispose하고 모두 제거합니다.
		 */
		private _clearScrollPanes(): void {
			if (this._virtualScrollPanes) {
				CMap._valueStream(this._virtualScrollPanes)
					.filterNull()
					.forEach(eachScrollPane => eachScrollPane.dispose());
				this._virtualScrollPanes.clear();
			}
			if (this._nativeScrollPanes) {
				CMap._valueStream(this._nativeScrollPanes)
					.filterNull()
					.forEach(eachScrollPane => eachScrollPane.dispose());
				this._nativeScrollPanes.clear();
			}
		}

		public dispose(): void {
			if (this.disposed == true) {
				return;
			}

			this._clearScrollPanes();
			this._virtualScrollPanes = null;
			this._nativeScrollPanes = null;

			if (this._control) {
				// remove eventmap
				EventAttacher.detach(this._control.uuid);

				// remove dom element
				let rootID: string = _UUID_MAPPER._getControlNodeID(this._control as controls.UIControl);
				let htmlElement: HTMLElement = document.getElementById(rootID);
				if (htmlElement) {
					_removeElementInNextTick(htmlElement);
				}
				rootID = _UUID_MAPPER._getGlobalControlNodeID(this._control as controls.UIControl);
				htmlElement = document.getElementById(rootID);
				if (htmlElement) {
					_removeElementInNextTick(htmlElement);
				}

				_UUID_MAPPER._disposeControlUUID(this._control as controls.UIControl);
			}
			this._control = null;

			if (this._decorators) {
				this._decorators.clear();
			}
			this._decorators = null;

			this._oldControlShape = null;

			this._stylerNodes = null;
			this._nodeNameToUUID = null;
			this._uuidToShape = null;

			this._removalNodeNameToUUID = null;
			this._newNodeNameToUUID = null;

			if (this._internPool) {
				this._internPool.dispose();
			}
			this._internPool = null;

			this._disposed = true;
		}

		/* helper methods */
		private _getOldUIShape(
			globalMap: CMap<core.DrawableControl, UIShape>,
			asideMap: CMap<core.DrawableControl, ElementShape>,
			isLazy: boolean
		): UIShape {
			if (isLazy === false) {
				this._preProcNodeName();
			}

			let oldControlShape = this._oldControlShape;

			let childGlobalMap = _createMap<core.DrawableControl, UIShape>();
			let childAsideMap = _createMap<core.DrawableControl, ElementShape>();

			let uiShape: UIShape = this._convertToUIShape(oldControlShape, {
				childShapeProvider: (renderer: ControlRenderer) => renderer._getOldUIShape(childGlobalMap, childAsideMap, isLazy),
				lazyTaskManager: null,
				owner: this._control,
				isNew: false,
				isLazy,
				globalMap: childGlobalMap,
				asideMap: childAsideMap
			});

			// global
			if (globalMap) {
				if (oldControlShape && oldControlShape.global) {
					if (oldControlShape.global instanceof ControlRenderer) {
						// ControlRenderer
						let childRenderer: ControlRenderer = oldControlShape.global as ControlRenderer;
						let oldGlobalUIShape: UIShape = childRenderer._getOldUIShape(childGlobalMap, childAsideMap, isLazy);
						if (oldGlobalUIShape) {
							globalMap.set(childRenderer._control, oldGlobalUIShape);
						}
					} else {
						// ElementShape
						let oldGlobalUIShape: UIShape = this._convertToUIShape(oldControlShape.global as ElementShape, {
							childShapeProvider: (renderer: ControlRenderer) => renderer._getOldUIShape(childGlobalMap, childAsideMap, isLazy),
							lazyTaskManager: null,
							owner: this._control,
							isNew: false,
							isLazy,
							globalMap: childGlobalMap,
							asideMap: childAsideMap
						});
						globalMap.set(this._control, oldGlobalUIShape);
					}
				}
				childGlobalMap.forEach((shape, key) => {
					globalMap.set(key, shape);
				});
			}

			// aside
			if (asideMap) {
				if (oldControlShape && oldControlShape.aside) {
					asideMap.set(this._control, oldControlShape.aside);
				}
				childAsideMap.forEach((shape, key) => {
					asideMap.set(key, shape);
				});
			}

			return uiShape;
		}

		/**
		 * Parent에 의해 불려질 때 호출되어야 함.
		 * @param globalMap 
		 * @param lazyTaskManager 
		 */
		private _getNewUIShape(
			globalMap: CMap<core.DrawableControl, UIShape>,
			asideMap: CMap<core.DrawableControl, ElementShape>,
			lazyTaskManager: ufc.LazyTaskManager): UIShape {

			let controlShape = this._getControlShape();
			let uiShape: UIShape = this._processNewUIShape(controlShape, globalMap, asideMap, lazyTaskManager);

			this._postProcNodeName();

			return uiShape;
		}
		/**
		 * 자기자신의 새로운 Shape을 생성할 때 호출되어야 함.
		 * @param globalMap 
		 * @param lazyTaskManager 
		 */
		private _createNewUIShape(globalMap: CMap<core.DrawableControl, UIShape>
			, asideMap: CMap<core.DrawableControl, ElementShape>
			, lazyTaskManager: ufc.LazyTaskManager): UIShape {

			let targetShape: ControlShape = this._getControlShape();
			let uiShape: UIShape = this._processNewUIShape(targetShape, globalMap, asideMap, lazyTaskManager);

			this._postProcNodeName();

			return uiShape;
		}

		private _processNewUIShape(controlShape: ControlShape
			, globalMap: CMap<core.DrawableControl, UIShape>
			, asideMap: CMap<core.DrawableControl, ElementShape>
			, lazyTaskManager: ufc.LazyTaskManager): UIShape {

			/* styler node clear */
			this._stylerNodes = {};

			let childGlobalMap = _createMap<core.DrawableControl, UIShape>();
			let childAsideMap = _createMap<core.DrawableControl, ElementShape>();

			let uiShape: UIShape = this._convertToUIShape(controlShape, {
				childShapeProvider: (renderer: ControlRenderer) => renderer._getNewUIShape(childGlobalMap, childAsideMap, lazyTaskManager),
				lazyTaskManager: lazyTaskManager,
				owner: this._control,
				isNew: true,
				isLazy: false,
				globalMap: childGlobalMap,
				asideMap: childAsideMap
			});

			// global
			if (globalMap) {
				if (controlShape && controlShape.global) {
					if (controlShape.global instanceof ControlRenderer) {
						// ControlRenderer
						let childRenderer: ControlRenderer = controlShape.global as ControlRenderer;
						let newGlobalUIShape: UIShape = childRenderer._getNewUIShape(childGlobalMap, childAsideMap, lazyTaskManager);
						if (newGlobalUIShape) {
							globalMap.set(childRenderer._control, newGlobalUIShape);
						}
					} else {
						// ElementShape
						let globalShape: ElementShape = controlShape.global as ElementShape;
						globalShape.owner = this._control;
						globalShape.attr = _mergeObject(globalShape.attr, {
							id: _UUID_MAPPER._getGlobalControlNodeID(globalShape.owner as controls.UIControl)
						});
						let newGlobalUIShape = this._convertToUIShape(globalShape, {
							childShapeProvider: (renderer: ControlRenderer) => renderer._getNewUIShape(childGlobalMap, childAsideMap, lazyTaskManager),
							lazyTaskManager: lazyTaskManager,
							owner: this._control,
							isNew: true,
							isLazy: false,
							globalMap: childGlobalMap,
							asideMap: childAsideMap
						});
						globalMap.set(this._control, newGlobalUIShape);
					}
				};

				childGlobalMap.forEach((shape, key) => {
					globalMap.set(key, shape);
				});
			}

			// aside
			if (asideMap) {
				if (controlShape && controlShape.aside) {
					asideMap.set(this._control, controlShape.aside);
				}
				childAsideMap.forEach((shape, key) => {
					asideMap.set(key, shape);
				});
			}

			this._oldControlShape = controlShape;
			return uiShape;
		}

		/* 컨트롤 Root Shape의 공통 처리 */
		private _getControlShape(): ControlShape {
			if (this._control == null) {
				return null;
			}
			// clear event delegator
			EventAttacher.detach(this._control.uuid);

			let originalShape: ControlShape = null;
			utils.tryCatch({
				do: () => {
					originalShape = this._control._createControlShape();
				},
				catch: (e: Error) => {
					utils.logError(e);
					originalShape = ShapeUtil._getErrorShape(e);
				},
				_report: true,
				_context: exceptions.ErrorContext.RENDERING_FAIL
			});

			originalShape.owner = this._control;

			// UIControl 처리
			/* root node */
			let controlNodeID: string = _UUID_MAPPER._getControlNodeID(this._control as controls.UIControl);

			originalShape.attr = _mergeObject(
				originalShape.attr,
				{ [ControlRenderer._ATTR_UUID]: controlNodeID }
			);

			/* readonly css classname */
			if (!originalShape.classNames) {
				originalShape.classNames = [];
			}
			if (_getProperty(this._control, "readOnly", false) === true) {
				originalShape.classNames.push(Classes.READONLY);
			}
			/* disabled css classname */
			if (_getProperty(this._control, "enabled", true) === false) {
				originalShape.classNames.push(Classes.DISABLED);
			}
			/* name attribute */
			if (!_isNullOrEmpty(this._control.name)) {
				originalShape.attr.name = this._control.name;
			}

			/* htmlAttr */
			let htmlAttr = this._control.htmlAttr();
			for (let key in htmlAttr) {
				let value = htmlAttr[key];
				let attrName = utils.HTMLEncoder.encodeForHTMLAttribute("data-usr-" + key);
				originalShape.attr[attrName] = utils.HTMLEncoder.encodeForHTMLAttribute(value);
			}

			// accesskey check
			if (_getProperty(this._control, "accessKey", null) !== null) {
				let key: string = (<controls.AccessableUIControl>this._control).accessKey;
				if (key && /^[0-9a-z-A-Z]$/g.test(key) === true) {
					key = key.toLowerCase();
					originalShape.attr = _mergeObject(originalShape.attr, { "data-hotkey": key });
				}
			}

			// 데코레이터 처리. 이후 과정부터 루트 쉐이프가 변경될 수 있음.
			// eg) 버티컬 레이아웃에 포함된 경우 등.
			this._decorators.forEach((decorator) => {
				let newShape = decorator(originalShape);
				if (newShape !== originalShape) {
					if (originalShape.global) { // global shape
						newShape.global = originalShape.global;
						delete originalShape.global;
					}
					if (originalShape.aside) { // aside shape
						newShape.aside = originalShape.aside;
						delete originalShape.aside;
					}
				}
				originalShape = newShape;
			});

			// visible check
			if (this._control instanceof controls.VisibleUIControl) {
				if (this._control.visible === false) {
					originalShape.style = _mergeObject(originalShape.style, {
						display: "none"
					});
				}
			}

			// set rendering point to originalShape.(DOM 패치할 엘리먼트를 찾기 위해 id가 추가되었음)
			originalShape.attr = _mergeObject(originalShape.attr, {
				id: controlNodeID
			});

			return originalShape;
		}

		/**
		 * {@link ElementShape}를 {@link UIShape}로 변환 합니다.
		 * 
		 * @param elementShape 
		 * @param options 변환 옵션
		 */
		private _convertToUIShape(elementShape: ElementShape, options: UIShapeConvertOptions): UIShape {
			let [childShapeProvider, lazyTaskManager, owner, isNew, isLazy, globalMap, asideMap]
				= [options.childShapeProvider, options.lazyTaskManager, options.owner, options.isNew, options.isLazy, options.globalMap, options.asideMap];

			if (elementShape == null || !elementShape.tag) {
				return null;
			}

			owner = elementShape.owner ? elementShape.owner : owner;
			let resultUIShape: UIShape = { tag: elementShape.tag };

			// #6143 : customscrollbar에 의해 controlshape의 스타일이 변경될 수 있어 commonattribute 복사를 children이 만들어진 이후에 처리하도록 변경.
			// this._copyCommonAttributes(controlShape, uiShape, owner, isNew, isLazy);

			// innerHTML이 주어진 경우
			if (elementShape.innerHTML) {
				resultUIShape.innerHTML = elementShape.innerHTML;
			}

			// 자식 처리.
			else if (elementShape.children) {
				let shapeChildren = elementShape.children;
				resultUIShape.children = [];

				for (let i = 0; i < shapeChildren.length; i++) {
					let child = elementShape.children[i];
					if (_isNullOrEmpty(child)) {
						continue;
					}

					// 문자열 콘텐츠
					if (typeof child == "string") {
						resultUIShape.children.push(child as string);
					}

					// ControlRenderer - 자식 컨트롤
					else if (child instanceof ControlRenderer) {
						let renderer: ControlRenderer = child;
						let childShape: UIShape = childShapeProvider(renderer, lazyTaskManager);
						if (childShape) {
							resultUIShape.children.push(childShape);
						}
					}

					// 레이지 태스크
					else if (child instanceof DrawLazyTask) {
						// 비교 비용을 줄이기 위해서 oldShape을 넣었으나 oldShape에 UIControl이 있을 경우 오동작하기 때문에 로직 수정
						// 이전 Shape을 보전하지 않기 때문에 Grid의 스크롤바가 새로 그려지면서 resize 시 포지션이 바뀜.
						let oldShape: ElementShape = null;
						if (child.nodename) {
							let nodeUUID = this._nodeNameToUUID.get(child.nodename);
							if (nodeUUID) {
								oldShape = this._uuidToShape.get(nodeUUID);
							}
						}
						if (lazyTaskManager) {
							if (!child.owner) {
								child.owner = this._control;
							}
							lazyTaskManager.addLazyTask(child);

							// 비교 비용을 줄이기 위해서 oldShape을 넣었으나 oldShape에 UIControl이 있을 경우 오동작하기 때문에 로직 수정
							if (!oldShape) {
								let dummyShape: ElementShape = {
									tag: "div", nodename: child.nodename
								};
								oldShape = dummyShape;
							}
						} else {
							oldShape = null;
						}

						elementShape.children[i] = oldShape;
						child = oldShape;

						// oldShape
						let childShape = this._convertToUIShape(child as ElementShape, {
							childShapeProvider: (renderer: ControlRenderer) => renderer._getOldUIShape(globalMap, asideMap, true),
							lazyTaskManager: null,
							owner,
							isNew: false,
							isLazy: true, // 레이지 태스크로 그려지는 것이므로 true
							globalMap, asideMap
						});

						if (childShape) {
							resultUIShape.children.push(childShape);
						}
					}
					// 탭 레이지 태스크
					else if (child instanceof TapLazyTask) {
						if (lazyTaskManager) {
							lazyTaskManager.addLazyTask(child);
						}
					}
					// 일반 엘리먼트 쉐이프
					else {
						if (isNew) {
							child = this._setCustomScrollbar(elementShape, shapeChildren, child as ElementShape, i);
						}

						let childShape = this._convertToUIShape(child as ElementShape, {
							childShapeProvider,
							lazyTaskManager: lazyTaskManager,
							owner,
							isNew,
							isLazy,
							globalMap,
							asideMap
						});

						if (childShape) {
							resultUIShape.children.push(childShape);
						}
					}
				}
			}

			// #6143 : customscrollbar에 의해 controlshape의 스타일이 변경될 수 있어 commonattribute 복사를 children이 만들어진 이후에 처리하도록 변경.
			this._applyCommonAttributesToUIShape(elementShape, resultUIShape, owner, isNew, isLazy);

			// attach control event
			if (isNew === true) {
				EventAttacher.attach(owner, elementShape, resultUIShape);
			} else {
				EventAttacher._detachEventHandler(owner, elementShape);
			}

			return resultUIShape;
		}

		private _addStylerNode(controlShape: ElementShape): string {
			let stylerName: string = controlShape.styler;
			let stylerNodes: string[] = this._stylerNodes[stylerName];
			if (!stylerNodes) {
				stylerNodes = [];
				this._stylerNodes[stylerName] = stylerNodes;
			}
			let nodename: string = controlShape.nodename;
			if (!nodename) {
				nodename = "__" + stylerName + "@" + stylerNodes.length;
				controlShape.nodename = nodename;
			}
			stylerNodes[stylerNodes.length] = nodename;

			return nodename;
		}

		/**
		 * 
		 * @param elementShape 컨트롤에서 생성한 shape
		 * @param uiShape vdom 패치하기 위한 shape
		 * @param owner shape를 소유한 컨트롤
		 * @param isNew newShape인지 여부. false인 경우 oldShape.
		 * @param isLazy 
		 */
		private _applyCommonAttributesToUIShape(elementShape: ElementShape, uiShape: UIShape, owner: core.DrawableControl, isNew: boolean, isLazy: boolean): void {
			// 이전 쉐이프
			if (isNew == true) {
				if (elementShape.hasOwnProperty("aria")) {
					if (elementShape.aria == "root") {
						let labelProvider = owner._getLabelProvider();
						let text = labelProvider.getText();
						let ariaLabel = ShapeUtil._getValidAriaLabelAttr(text);
						if (ariaLabel) {
							elementShape.attr["aria-label"] = ShapeUtil._getValidAriaLabelAttr(text);
						}
					}
					let resolvedAccessibility = owner.accessibility[elementShape.aria] as controls.Accessibility || owner.accessibility;
					resolvedAccessibility._commitToShape({
						shape: elementShape,
						bindContext: elementShape.bindContext
					})
					if (resolvedAccessibility instanceof controls.ItemsAccessibility) {
						let eachAccessibility = resolvedAccessibility._forUUID(elementShape.ariaItemUUID);
						if (eachAccessibility) {
							eachAccessibility._commitToShape({
								shape: elementShape,
								bindContext: elementShape.bindContext
							});
						}
					}
				}

				// 스타일러가 존재하는 경우.
				if (elementShape.hasOwnProperty("styler")) { /* STYLER */
					let stylerName: string = elementShape.styler;
					let styler: controls.UIControlStyler = null;
					if (stylerName == "root") {
						styler = owner.style as controls.UIControlStyler;
					} else {
						styler = owner.style[stylerName] as controls.UIControlStyler;
					}

					let mixedStyle: { classNames: string[], cssText: string[] } = ShapeUtil.mixShapeNStyler(elementShape, styler, owner);
					this._addStylerNode(elementShape);

					elementShape.shapeClassNames = mixedStyle.classNames;
					uiShape.classNames = mixedStyle.classNames;

					// Cache
					let cssText: string = this._internPool._intern(_joinCSSArray(mixedStyle.cssText));
					elementShape.shapeCssText = cssText;
					uiShape.style = { cssText: cssText };
				}
				// 일반 스타일링 
				else {
					if (elementShape.hasOwnProperty("classNames")) {
						elementShape.classNames = _uniq(elementShape.classNames);
						elementShape.shapeClassNames = elementShape.classNames;

						uiShape.classNames = elementShape.classNames;
					}
					if (elementShape.hasOwnProperty("style")) {
						let cssText: string = _createCSSText(elementShape.style);
						// Cache
						cssText = this._internPool._intern(cssText);
						elementShape.shapeCssText = cssText;
						uiShape.style = { cssText: cssText };
					}
				}
			}
			// 기존 쉐이프가 존재하는 경우
			else {
				if (elementShape.hasOwnProperty("shapeClassNames")) {
					uiShape.classNames = _uniq(elementShape.shapeClassNames);
				}
				if (elementShape.hasOwnProperty("shapeCssText")) {
					uiShape.style = { cssText: elementShape.shapeCssText };
				}

				// remove all old config
				let nodename: string = elementShape.nodename;
				let targetUUID: string = null;
				if (elementShape.attr) {
					targetUUID = elementShape.attr[ControlRenderer._ATTR_UUID];
				}
				if (nodename || targetUUID) {
					if (!targetUUID) {
						targetUUID = this._nodeNameToUUID.get(nodename);
					}
					if (targetUUID) {
						this._uuidToShape.delete(targetUUID);
					}
					if (nodename) {
						let styler: string = elementShape.styler;
						if (styler) {
							let stylerNodeNames: string[] = this._stylerNodes[styler];
							if (stylerNodeNames && stylerNodeNames.length > 0) {
								let nodeNameIdx: number = stylerNodeNames.indexOf(nodename);
								if (nodeNameIdx != -1) {
									stylerNodeNames.splice(nodeNameIdx, 1);
									this._nodeNameToUUID.delete(nodename);
								}
							}
						}
					}
				}
			}

			// cssText가 없을 경우 불필요한 style object를 삭제. 빈 값으로 남아있을 경우 VDOM 처리시 문제 발생(dependencies.js:147 Uncaught TypeError: Cannot set property 'cssText' of undefined).
			if (uiShape.style) {
				if (uiShape.style.cssText == null || uiShape.style.cssText == "") {
					delete uiShape["style"];
				}
			}

			if (elementShape.attr) {
				uiShape.attr = elementShape?.attr;
			}

			if (elementShape.key) {
				uiShape.key = elementShape.key;
			}
			if (elementShape.hasOwnProperty("value")) {
				// DrawLazyTask를 사용할 때 oldShape으로 잠시 치환하는 과정에서 input tag의 value 처리의 오동작 방지
				if (isNew) {
					uiShape.value = elementShape.value;
				} else {
					uiShape.oldvalue = elementShape.value;
				}
			}

			// namespace
			if (elementShape.namespace) {
				uiShape.namespace = elementShape.namespace;
			}

			/* nodename */
			// Lazy Shape 때문에 newShape 생성시점까지 oldShape의 targetShape을 제거할 수 없음
			if (typeof elementShape.nodename == "string") {
				let nodename: string = elementShape.nodename;
				this._processNamedNode(nodename, elementShape, uiShape, isNew, isLazy);
			}

			if (elementShape.attr) { // 각 컨트롤의 RootNode에 NodeName을 부여하여 강제로 UUID를 설정
				let controlRootNodeID: string = _UUID_MAPPER._getControlNodeID(this._control as controls.UIControl);

				if (elementShape.attr[ControlRenderer._ATTR_UUID] == controlRootNodeID) {
					let nodename: string = ControlRenderer._NODE_NAME__CONTROL_ROOT;
					this._processNamedNode(nodename, elementShape, uiShape, isNew, isLazy);
				}
			}
		}

		private _processNamedNode(nodeName: string, controlShape: ElementShape, uiShape: UIShape, isNew: boolean, isLazy: boolean): void {
			let oldNodeUUID = this._nodeNameToUUID.get(nodeName);
			if (oldNodeUUID) {
				// 부분 갱신시 최신화를 위해 이전에 발급된 ID가 있고 그 아이디로 shape이 등록되어있는 경우 삭제한다
				this._uuidToShape.delete(oldNodeUUID);
			}
			let targetUUID = EventAttacher._assignNodeUUID(controlShape, uiShape, oldNodeUUID);
			// FIXME 이런 경우가 있는지 확인해야 한다.
			if (oldNodeUUID && oldNodeUUID != targetUUID) {
				log("동일한 UUID에 대한 중복처리 발생");
			}

			this._nodeNameToUUID.set(nodeName, targetUUID);
			this._uuidToShape.set(targetUUID, controlShape);

			if (isNew || isLazy) {
				this._newNodeNameToUUID.set(nodeName, targetUUID);
			} else {
				this._removalNodeNameToUUID.set(nodeName, targetUUID);
			}
		}

		private _preProcNodeName(): void {
			this._newNodeNameToUUID = _createMap();
			this._removalNodeNameToUUID = _createMap();
		}

		private _postProcNodeName(): void {
			this._removalNodeNameToUUID.forEach((targetUUID, nodename) => {
				if (this._newNodeNameToUUID.has(nodename) === false) {
					this._nodeNameToUUID.delete(nodename);
					this._uuidToShape.delete(targetUUID);
				}
			});

			this._newNodeNameToUUID.clear();
			this._removalNodeNameToUUID.clear();
		}

		private _searchDOM(rootID: string, selector: string): HTMLElement {
			let domElement: HTMLElement = document.getElementById(rootID);
			if (domElement) {
				let domTraverser: DOMTraverser = _traverseFromElement(domElement);
				let selectedTraverser: DOMTraverser = domTraverser._find(selector);
				if (selectedTraverser != null) {
					let htmlElement: HTMLElement = selectedTraverser._getElement();
					selectedTraverser.dispose();
					return htmlElement;
				}
			}
			return null;
		}

		private _searchRootAppInstance(): core.AppInstance {
			let appInstance: core.AppInstance = this._control.getAppInstance();
			return appInstance.getRootAppInstance();
		}

		private _setCustomScrollbar(parentShape: ElementShape, container: ufc.ElementShapeContent[], shape: ElementShape, idx: number): ElementShape {
			let marked: boolean = controls.internal.ScrollbarUtil._isMarkedScrollableContentPane(shape);
			if (marked === false) {
				return shape;
			}
			if (this._control instanceof controls.EnableUIControl == false) {
				return shape;
			}
			if (this._control instanceof controls.Container &&
				(this._control._useBodyScroll() || this._control._isUseCustomScroll() == false)) {
				// 현재 CustomScrollbar 사용여부를 동적으로 결정할 수 없기 때문에 최초 생성된 패턴을 유지하는 방식으로 처리하나
				// 향후 동적으로 결정할 수 있게 될 경우 CustromScrollbar 설정에 따라 이전 ScrollPane을 초기화 해주어야 함.
				let nativeScrollPane = this._nativeScrollPanes.get(shape.nodename);
				if (!nativeScrollPane) {
					nativeScrollPane = new controls.internal.NativeScrollPane(this._control as controls.UIControl, shape.nodename);
					this._nativeScrollPanes.set(shape.nodename, nativeScrollPane);
				}
				shape = nativeScrollPane.createScrollbar(parentShape, container, shape, idx);

				return shape;
			} else if ((this._control as controls.EnableUIControl)._isUseCustomScroll() == false) {
				return shape;
			}

			let parentNodeName: string = parentShape.nodename;
			if (parentNodeName == null) {
				if (parentShape.hasOwnProperty("styler")) {
					// 스타일러가 있을 경우 기존 스타일러 노드의 named node 명명규칙을 따름.
					parentNodeName = this._addStylerNode(parentShape);
				} else {
					parentNodeName = "__" + shape.nodename + "__";
				}
				parentShape.nodename = parentNodeName;
			}

			let virtualScrollPane = this._virtualScrollPanes.get(shape.nodename);
			if (!virtualScrollPane) {
				virtualScrollPane = new controls.internal.VirtualScrollPane(this._control as controls.UIControl, shape.nodename, parentNodeName);
				this._virtualScrollPanes.set(shape.nodename, virtualScrollPane);
			} else {
				virtualScrollPane._setParentNodeName(parentNodeName);
			}

			shape = virtualScrollPane.createScrollbar(parentShape, container, shape, idx);
			return shape;
		}

	}
}