namespace cpr.utils {
	/**
	 * @private
	 */
	export class StringUtil {
		static CANVAS: HTMLCanvasElement = null;

		static insert(text: string, newChar: string, pos: number): string {
			if (pos < text.length) {
				return text.substring(0, pos) + newChar + text.substring(pos);
			} else {
				return text + newChar;
			}
		}

		static deleteStr(text: string, start: number, end: number): string {
			return text.substring(0, start) + text.substring(end);
		}

		static startsWith(text: string, search: string): boolean {
			return text.substring(0, search.length) === search;
		}

		static replaceRange(text: string, replace: string, start: number, end: number): string {
			return text.substring(0, start) + replace + text.substring(end);
		}

		static replaceAt(text: string, replaceChar: string, pos: number) {
			if (pos > text.length - 1) return text;
			return text.substring(0, pos) + replaceChar + text.substring(pos + 1);
		}

		/**
		 * 구두점, 숫자, 알파벳 전각문자를 반각문자로 변환합니다.
		 * @param text 
		 */
		static toHalfWidth(text: string) {
			return text.replace(/[！-～]/g, function (s) { return String.fromCharCode(s.charCodeAt(0) - 0xFEE0) });
		}

		/**
		 * 구두점, 숫자, 알파벳 반각문자를 전각문자로 변환합니다.
		 * @param text 
		 */
		static toFullWidth(text: string) {
			return text.replace(/[!-~]/g, function (s) { return String.fromCharCode(s.charCodeAt(0) + 0xFEE0); });
		}

		/**
		 * 구두점, 숫자, 알파벳 전각문자가 있는지 여부를 반환합니다.
		 * @param text 문자 또는 문자열.
		 */
		static isFullwidth(text: string) {
			return /[！-～]/g.test(text);
		}

		/**
		 * 구두점, 숫자, 알파벳 반각문자가 있는지 여부를 반환합니다.
		 * @param text 문자 또는 문자열.
		 */
		static isHalfWidth(text: string) {
			return /[!-~]/g.test(text);
		}

		/**
		 * 전달받은 문자가 HTML Character Reference 또는 XML Character Reference 인지 여부를 반환합니다.
		 * <pre><code>
		 * StringUtil.isCharRefText("<script> alert('1'); <script>")
		 * return false
		 * 
		 * StringUtil.isCharRefText("&amp;&nbsp;")
		 * return true
		 * </code></pre>
		 * @param text 문자 또는 문자열.
		 */
		static isCharRefText(text: string): boolean {
			return /([&][#0-9a-z]*[;])+/gi.test(text);
		}

		/**
		 * 문자열로된 숫자가 정수일때 true를 반환합니다. float는 false입니다.
		 * @private
		 * @param value 
		 */
		static _isInt(value: string) {
			let regex = /^-?[0-9]+$/;
			return regex.test(value);
		}

		/**
		 * @private
		 * @param text 
		 */
		static _encodeMinimizeForHTML(text: string): string {
			if (!text) {
				return text;
			}
			return text.replace(new RegExp('<', 'g'), '&lt;').replace(new RegExp('>', 'g'), '&gt;');
		}

		/**
		 * ECMA 2015 스타일의 템플릿 함수를 컴파일 합니다.
		 * @param template 템플릿 표현식.
		 */
		static compileTemplate(template: string): (data?: any) => string {
			return _.template(template, {
				interpolate: /\$\{(.+?)\}/g
			});
		}

		/**
		 * 측정할 텍스트의 너비를 측정합니다.
		 * @param text 측정할 텍스트
		 * @param font CSS font (font-style font-variant font-weight font-size/line-height font-family)
		 */
		static measureText(text: string, font: string): number {
			let canvas = StringUtil.CANVAS || (StringUtil.CANVAS = document.createElement("canvas"));
			let context = canvas.getContext("2d");
			context.font = font;
			let textMetrics = context.measureText(text);
			return textMetrics.width;
		}

		static repeat(text: string, howMany: number) {
			if (String.prototype["repeat"]) {
				return text["repeat"](howMany);
			}

			return Array(howMany + 1).join(text);
		}

	}
}