///<reference path="../AccessableUIControl.ts"/>


namespace cpr.controls.media {

	/**
	 * 오디오, 비디오 등의 미디어 계열 컴포넌트의 상위 클래스
	 * 
	 * @fires cpr.events.CEvent#abort 재생이 중단되면 전송됩니다. 예를 들어 미디어가 재생 중이고 처음부터 다시 시작되면이 이벤트가 전송됩니다.
	 * @fires cpr.events.CEvent#canplay 적어도 몇 프레임 동안 미디어를 재생할 수있는 충분한 데이터가있을 때 전송됩니다. 이는 HAVE_ENOUGH_DATA readyState에 해당합니다.
	 * @fires cpr.events.CEvent#durationchange 미디어의 지속 시간이 변경되었음을 나타내는 이벤트. 예를 들어, 미디어에 지속 시간을 알리는 데 충분할 때이 메시지가 전송됩니다.
	 * @fires cpr.events.CEvent#ended 재생이 완료되면 전송됩니다.
	 * @fires cpr.events.CEvent#error 오류가 발생하면 전송됩니다. 요소의 error 속성에는 자세한 정보가 들어 있습니다. 자세한 내용은 HTMLMediaElement.error를 참조하십시오.
	 * @fires cpr.events.CEvent#loadeddata 미디어의 첫 번째 프레임이로드를 완료했습니다.
	 * @fires cpr.events.CEvent#loadmetadata 미디어의 메타 데이터로드가 완료되었습니다. 모든 속성에는 현재 유용한 정보가 포함되어 있습니다.
	 * @fires cpr.events.CEvent#loadstart 미디어로드가 시작되면 전송됩니다.
	 * @fires cpr.events.CEvent#pause 재생 상태가 일시 중지됨 (일시 중지 된 속성이 true)으로 변경되면 전송됩니다.
	 * @fires cpr.events.CEvent#play 재생 상태 또는 자동 재생 속성의 결과로 재생 상태가 더 이상 일시 중지되지 않을 때 전송됩니다.
	 * @fires cpr.events.CEvent#playing 미디어가 재생을 시작하기에 충분한 데이터를 가지고있을 때, 재생 이벤트가 끝난 후, 미디어가 다시 시작될 때, 미디어 검색이 반복 될 때, 검색되기 전에 재생 중이면 미디어가 재생 될 때 전송됩니다.
	 * @fires cpr.events.CEvent#progress 미디어를 다운로드하는 진행 상황을 이해 관계자에게 알리기 위해 주기적으로 전송됩니다. 다운로드 된 미디어의 현재 양에 대한 정보는 미디어 요소의 버퍼링 된 속성에서 사용할 수 있습니다.
	 * @fires cpr.events.CEvent#ratechange 재생 속도가 변경되면 전송됩니다.
	 * @fires cpr.events.CEvent#seeked seek 조작이 완료하면 전송됩니다.
	 * @fires cpr.events.CEvent#seeking seek 조작을 시작하면 전송됩니다.
	 * @fires cpr.events.CEvent#stalled 사용자 에이전트가 미디어 데이터를 가져 오려고하지만 데이터가 갑자기 나타나지 않을 때 전송됩니다.
	 * @fires cpr.events.CEvent#suspend 미디어의 로딩이 일시 중단되면 전송됩니다. 다운로드가 완료되었거나 다른 이유로 인해 일시 중지 되었기 때문에이 문제가 발생할 수 있습니다.
	 * @fires cpr.events.CEvent#timeupdate currentTime 속성으로 변경되면 이벤트가 발생합니다. 
	 * IE,Edge에서 이벤트가 두 번 발생 할 수 있습니다. currentTime을 확인할때 다음과 같은 코드로 이벤트 중복을 예방하시기 바랍니다.
	 * <pre>var oldCurrentTime = null;
	 * function onTimeupdate(){
	 *   if(oldCurrentTime == audio.currentTime){
	 *     return;
	 *   }
	 *   //... 코드 작성
	 *   oldCurrentTime = audio.currentTime;
	 * }</pre>
	 * 
	 * @fires cpr.events.CEvent#volumechange 오디오 볼륨이 변경되면 전송됩니다 (볼륨이 설정되어 있고 음소거 된 속성이 변경된 경우 모두).
	 */
	export abstract class Media extends AccessableUIControl implements controls.provider.ValueBindable {
		private static readonly MEDIA_AVAILABLE_PROP: string[] = [
			"value", "text", "autoplay", "displayControl", "loop",
			"muted", "preload", "currentTime", "playbackRate", "volume", "notSupportMessage", "controlsList"
		];
		/**
		 * HTML 속성으로 명세하여 지정하는 속성들
		 */
		private _properties: { [key: string]: any } = {};
		private _textTracks: media.TextTrack[] = [];

		/**
		 * DOM 객체에 속성으로 지정하는 속성들
		 */
		private _mediaProperties: { [key: string]: any } = {};
		private _binder: provider.ValueBinder;

		constructor(id?: string) {
			super(id);
			this._binder = new provider.ValueBinder(this);

			this._addBindableProperty("notSupportMessage", "").withSetterValidatorWithType(false, "string");
		}

		_getAutoSizeAvailability(): layouts.AutoSizeType {
			return layouts.AutoSizeType.both;
		}

		protected _isConfigurableProperty(propName: string): boolean {
			if (Media.MEDIA_AVAILABLE_PROP.indexOf(propName) != -1) {
				return true;
			}
			return super._isConfigurableProperty(propName);
		}

		/**
		 * 해당 속성을 bind합니다.
		 * @param name bind할 속성 명.
		 * @return bind한 종류를 보여주는 Factory.
		 */
		public override bind(name: string): cpr.bind.IBindFactory {
			if (name == "src") {
				return super.bind("value");
			}
			else {
				return super.bind(name);
			}
		}

		/// SimpleDataBindable Start ////////////////////////////////////////////

		/**
		 * 컨트롤의 값을 설정하고, value-change이벤트가 발생됩니다.
		 * @param value 컨트롤의 값.
		 */
		public set value(value: string) {
			this._binder.setValue(value);
		}

		/**
		 * 컨트롤의 값을 반환합니다.
		 * @return 컨트롤의 값.
		 */
		public get value(): string {
			return this._binder.getValue();
		}

		/**
		 * 컨트롤의 값을 설정합니다.
		 * @param value 컨트롤의 값.
		 */
		public putValue(value: string) {
			this._binder.setValue(value, false);
		}

		/**
		 * 컨트롤에 보여지는 텍스트를 반환합니다.
		 * @return 화면에 보이는 텍스트.
		 */
		public get text(): string {
			return this._binder.getText();
		}

		/**
		 * 컨트롤에 보이는 텍스트를 설정합니다.
		 * @param 화면에 보이는 텍스트.
		 */
		public set text(text: string) {
			this._binder.setText(text);
		}

		_valueDidChange(name: string, oldValue: any, newValue: any) {
			super._valueDidChange(name, oldValue, newValue);
			this._binder._valueDidChange(name, oldValue, newValue);
			switch (name) {
				case "notSupportMessage": {
					this.redraw();
					break;
				}
			}
		}

		/// SimpleDataBindable End ////////////////////////////////////////////////

		private _getMediaProperty(name: string, defaultValue: any) {
			let mediaElement = <HTMLMediaElement>this._getRenderer().getNamedNode("media");
			let result = defaultValue;
			if (this._mediaProperties[name]) {
				result = this._mediaProperties[name];
			} else if (mediaElement) {
				result = mediaElement[name];
			}
			return result;
		}

		private _setMediaProperty(name: string, value: any) {
			let mediaElement = this._getRenderer().getNamedNode("media") as HTMLMediaElement;
			if (!mediaElement) {
				this._mediaProperties[name] = value;
				this.redraw();
			} else {
				utils.tryCatch({
					do: () => {
						mediaElement[name] = value;
					},
					catch: () => {
						this._mediaProperties[name] = value;
					}
				})
			}
		}

		/**
		 * 자동 시작의 여부를 반환합니다.
		 * @return 자동 시작 여부.
		 */
		get autoplay(): boolean {
			if (this._properties['autoplay'] != null) {
				return this._properties['autoplay'];
			}
			return false;
		}

		/**
		 * 자동 시작의 여부를 설정합니다. 브라우저 기본 정책으로 음소거 자동재생이 설정되어 있습니다.
		 * 이 옵션은 브라우저에 정책에 따라 동작되기 때문에 브라우저 또는 맥에서 autoplay에 관련 설정을 해주어야 음소거 없이 동작할 수 있습니다.
		 * 브라우저에서 동작이 안되는 경우 각 브라우저의 autoplay 설정을 참고하시기 바랍니다.
		 * @param value 자동 시작 여부.
		 */
		set autoplay(value: boolean) {
			this._properties['autoplay'] = value;
			this.redraw();
		}

		/**
		 * 브라우저 기본 컨트롤을 보여줄지 여부를 반환합니다.
		 * @return 컨트롤을 보여줄지에 대한 여부.
		 */
		get displayControl(): boolean {
			if (this._properties['controls'] != null) {
				return this._properties['controls'];
			}
			return true;
		}

		/**
		 * 브라우저 기본 컨트롤을 보여줄지 여부를 설정합니다.
		 * @param value 컨트롤을 보여줄지에 대한 여부.
		 */
		set displayControl(value: boolean) {
			this._properties['controls'] = value;
			this.redraw();
		}

		/**
		 * 반복 여부를 반환합니다.
		 * @return 반복 여부.
		 */
		get loop(): boolean {
			return this._getMediaProperty("loop", false);
		}

		/**
		 * 반복 여부를 설정합니다.
		 * @param 반복 여부.
		 */
		set loop(value: boolean) {
			this._setMediaProperty("loop", value);
		}

		/**
		 * 음소거 여부의 값을 가져옵니다.
		 * @return 음소거 여부.
		 */
		get muted(): boolean {
			return this._getMediaProperty("muted", false);
		}

		/**
		 * 음소거 여부를 지정합니다.
		 * @param 음소거 여부.
		 */
		set muted(value: boolean) {
			this._setMediaProperty("muted", value);
		}

		/**
		 * 페이지가 로드 될 때 오디오 / 비디오를 로드할지 여부를 반환합니다.<br>
		 * 기본 값은 'auto'입니다.
		 * @return 페이지 로드 시 컨트롤을 로드할 지 여부.
		 */
		get preload(): string {
			if (this._properties['preload'] != null) {
				return this._properties['preload'];
			}
			return "auto";
		}
		/**
		 * 페이지가 로드 될 때 오디오 / 비디오를 로드할지 여부를 설정합니다.<br>
		 * 기본 값은 'auto'입니다.
		 * [auto] : 사용자가 우선순위를 가지고있지만 필요하다면 전체 비디오가 로드 될 수 있습니다.
		 * [metadata] : 메타데이터를 미리 가져와 로드합니다.
		 * [none] : 최소한의 트래픽을 유지해 비디오가 캐시되지 않고 로드합니다.
		 * @param value 페이지 로드 시 컨트롤을 로드할 지 여부.
		 */
		set preload(value: string) {
			this._properties['preload'] = value;
			this.redraw();
		}

		/**
		 * 현재 재생 중인 시간을 반환합니다.
		 * @return 현재 재생 중인 시간.
		 */
		get currentTime(): number {
			return this._getMediaProperty("currentTime", 0);
		}

		/**
		 * 현재 재생 중인 시간을 지정합니다.
		 * @param value 현재 재생 중인 시간.
		 */
		set currentTime(value: number) {
			if (value < 0) {
				value = 0;
			}
			this._setMediaProperty("currentTime", value);
		}

		/**
		 * 재생 속도의 값을 반환합니다.
		 * @return 재생 속도값.
		 */
		get playbackRate(): number {
			return this._getMediaProperty("playbackRate", 1.0);
		}

		/**
		 * 재생 속도의 값(0.25 에서 4.0)을 설정합니다. Default 1.0
		 * @param value 재생 속도 값.
		 */
		set playbackRate(value: number) {
			if (value < 0) {
				value = 0;
			}
			this._setMediaProperty("playbackRate", value);
		}

		/**
		 * 소리 크기의 값을 반환합니다.
		 * @return 소리 크기값.
		 */
		get volume(): number {
			return this._getMediaProperty("volume", 1);
		}

		/**
		 * 소리 크기 0에서 1 값을 설정합니다. 
		 * @param value 소리 크기값
		 */
		set volume(value: number) {
			if (value < 0) {
				value = 0;
			}
			this._setMediaProperty("volume", value);
		}

		/**
		 * 재생된 구간을 반환합니다.
		 * @return 재생된 구간
		 */
		get played(): TimeRanges {
			return this._getMediaProperty("played", null);
		}

		/**
		 * 정지 되어 있는지 여부를 반환합니다.
		 * @return 정지된 상태에 대한 여부.
		 */
		get paused(): boolean {
			return this._getMediaProperty("paused", true);
		}

		/**
		 * 버퍼로 받은 시간을 TimeRanges 객체로 반환합니다.
		 * @return 버퍼로 받은 구간.
		 */
		get buffered(): TimeRanges {
			return this._getMediaProperty("buffered", null);
		}

		/**
		 * 현재 오디오 / 비디오의 길이를 초 단위로 반환합니다.
		 * @return 오디오 / 비디오의 길이.
		 */
		get duration(): number {
			return this._getMediaProperty("duration", 0);
		}

		/**
		 * 사용자가 현재 오디오 / 비디오에서 검색 중인지 여부를 반환합니다.
		 * @return 오디오 / 비디오에서 검색 중인지에 대한 여부.
		 */
		get seeking(): boolean {
			return this._getMediaProperty("seeking", false);
		}

		/**
		 * 오디오 / 비디오의 검색 가능한 부분을 나타내는 TimeRanges 객체를 반환합니다.
		 * @return 오디오 / 비디오에서 검색 가능한 구간.
		 */
		get seekable(): TimeRanges {
			return this._getMediaProperty("seekable", null);
		}

		/**
		 * 오디오 / 비디오의 현재 준비 상태를 반환합니다.
		 * 0 = HAVE_NOTHING - 오디오 / 비디오 준비 여부 정보 없음 
		 * 1 = HAVE_METADATA - 오디오 / 비디오 용 메타 데이터 준비 됨 
		 * 2 = HAVE_CURRENT_DATA - 현재 재생 위치에 대한 데이터를 사용할 수 있지만 다음 프레임 / 밀리 초 재생할 데이터가 충분하지 않습니다. 
		 * 3 = HAVE_FUTURE_DATA - 현재 및 적어도 다음 프레임의 데이터를 사용할 수 있습니다. 
		 * 4 = HAVE_ENOUGH_DATA - 재생을 시작할 수있는 충분한 데이터
		 * @return 오디오 / 비디오의 현재 준비 상태.
		 */
		get readyState(): number {
			return this._getMediaProperty("readyState", 0);
		}

		/**
		 * 오디오 / 비디오의 현재 네트워크 상태를 반환합니다.
		 * 0 = NETWORK_EMPTY - 오디오 / 비디오가 아직 초기화되지 않았습니다. 
		 * 1 = NETWORK_IDLE - 오디오 / 비디오가 활성화되어 있고 자원을 선택했지만 네트워크를 사용하고 있지 않습니다. 
		 * 2 = NETWORK_LOADING - 브라우저가 데이터를 다운로드 중입니다. 
		 * 3 = NETWORK_NO_SOURCE - 오디오 / 비디오 소스가 없습니다.
		 * @return 오디오 / 비디오의 현재 네트워크 상태.
		 */
		get networkState(): number {
			return this._getMediaProperty("networkState", 0);
		}

		/**
		 * 사용 가능한 TextTrack을 갖는 TextTrackList 객체를 반환합니다.
		 * https://developer.mozilla.org/en-US/docs/Web/API/TextTrack
		 * @return TextTrackList
		 */
		get textTracks(): TextTrackList {
			return this._getMediaProperty("textTracks", null);
		}

		/**
		 * 표시되는 컨트롤의 기능을 제어를 할 수 있는 controlsList 속성을 반환합니다.
		 * HTMLMediaElement의 controlslist속성을 지원하기 위한 속성입니다.
		 * 브라우저별로 지원여부가 다르기 때문에 지원하는 브라우저와 설정가능한 값은 MDN문서를 확인하시기 바랍니다.
		 * @return controlslist 설정 값
		 */
		get controlsList(): string {
			return this._getMediaProperty('controlsList', null);
		}

		/**
		 * 표시되는 컨트롤의 기능을 제어를 할 수 있는 controlsList 속성을 설정합니다.
		 * nodownload, nofullscreen, noremoteplayback 속성 값이 있으며 공백으로 구분하여 설정합니다.<br>
		 * <pre><code>media.controlsList = "nodownload nofullscreen noremoteplayback"</code></pre>
		 * 이 속성을 지원하는 브라우저와 설정 가능한 속성 값에 대한 설명은 MDN문서를 확인하시기 바랍니다.
		 * @param type controlslist 설정 값
		 */
		set controlsList(type: string) {
			this._setMediaProperty('controlsList', type);
		}

		/**
		 * 브라우저가 컨트롤을 지원하지 않을 시 표시하는 메세지를 반환합니다.
		 * @return 메세지.
		 */
		public get notSupportMessage(): string {
			return this._bindables.get("notSupportMessage");
		}
		/**
		 * 브라우저가 컨트롤을 지원하지 않을 시 표시하는 메세지를 설정합니다.
		 * @param notSuppotMessage 메세지.
		 */
		public set notSupportMessage(notSupportMessage: string) {
			this._bindables.set("notSupportMessage", notSupportMessage);
		}

		public override _afterDraw(firstDraw: boolean = false): void {
			super._afterDraw(firstDraw);
			this._updateMediaProperties();
		}

		public _createShape(): ufc.ControlShape {
			let attributes = this._createAttributes();
			let children = this._createTracks();
			let autoSizeType = this._getAutoSizingTypeOfConstraint();
			let style: { [key: string]: string } = { width: "100%", height: "100%" };
			if (autoSizeType == "height") {
				delete style.height;
			} else if (autoSizeType == "width") {
				delete style.width;
			} else if (autoSizeType == "both") {
				style = {};
			}
			if (this.notSupportMessage) {
				children.push({
					tag: "div",
					classNames: [ufc.Classes.TEXT],
					children: [this.notSupportMessage]
				});
			}
			return {
				tag: "audio",
				classNames: ["cl-media"],
				attr: attributes,
				style: style,
				nodename: "media",
				children: children,
				events: {
					canplay: this._oncanplay
				},
				eventTargets: [ufc.EventTargetType.MEDIA]
			};
		}

		private _updateMediaProperties() {
			if (this.disposed) {
				return;
			}
			let mediaElement = this._getRenderer().getNamedNode("media");
			if (!mediaElement) {
				return;
			}
			utils.tryCatch({
				do: () => {
					for (let each in this._mediaProperties) {
						mediaElement[each] = this._mediaProperties[each];
						delete this._mediaProperties[each];
					}
				}
			});
		}

		private _createAttributes() {
			let result = {};
			for (let each in this._properties) {
				if (each == "autoplay" && this._properties[each]) {
					result['autoplay'] = '';
				}
				if (each == "controls" && this._properties[each]) {
					result['controls'] = '';
				}
				if (each == "preload" && this._properties[each]) {
					result['preload'] = this._properties[each];
				}
			}
			if (this.value != null) {
				result['src'] = this.value;
			}
			result['tabindex'] = "0";
			return result;
		}

		private _createTracks() {
			let trackShapes = [];
			for (let each of this._textTracks) {
				let attr = {};
				if (each.src) {
					attr['src'] = each.src;
				}
				if (each.kind) {
					attr['kind'] = each.kind;
				}
				if (each.label) {
					attr['label'] = each.label;
				}
				if (each.srcLang) {
					attr['srclang'] = each.srcLang;
				}
				trackShapes.push({ tag: "track", attr: attr });
			}
			return trackShapes;
		}

		private _oncanplay(e: events.CEvent) {
			this._updateMediaProperties();
		}

		/**
		 * 트랙을 추가합니다.
		 * <pre><code>
		 * var track = new cpr.controls.media.TextTrack("test.mp4");
		 * video.addTrack(track);
		 * </code></pre>
		 * @param track 추가하고자 하는 트랙.
		 */
		public addTextTrack(track: media.TextTrack): void {
			if (!track) {
				return;
			}
			this._textTracks.push(track);
			this.redraw();
		}

		/**
		 * 트랙을 제거합니다.
		 * <pre><code>
		 * var track = new cpr.controls.media.TextTrack("test.mp4");
		 * video.addTrack(track);
		 * video.removeTrack(track);
		 * </code></pre>
		 * @param track 제거하고자 하는 트랙
		 */
		public removeTextTrack(track: media.TextTrack): void {
			let index = this._textTracks.indexOf(track);
			if (index > -1) {
				this._textTracks.splice(index, 1);
			}
		}

		/**
		 * 모든 트랙을 제거합니다.
		 */
		public removeAllTextTracks(): void {
			this._textTracks = [];
		}
		/**
		 * 모든 트랙 정보를 반환합니다.
		 * @return cpr.controls.media.TextTrack[]
		 */
		public getTextTracks(): media.TextTrack[] {
			return this._textTracks.slice();
		}

		/**
		 * 오디오/비디오를 재생합니다.
		 */
		public play(): Promise<void> {
			let video = <HTMLMediaElement>this._getRenderer().getNamedNode("media");
			if (video) {
				return video.play();
			}
		}

		/**
		 * 재생 가능한 타입인지 여부를 반환합니다.
		 * @param type 오디오 / 비디오의 타입.
		 * @return 재생 가능한 타입인지에 대한 여부.
		 */
		public canPlayType(type: string): boolean {
			let video = <HTMLMediaElement>this._getRenderer().getNamedNode("media");
			let result = false;
			if (video) {
				result = video.canPlayType(type) == "" ? false : true;
			}
			return result;
		}

		/**
		 * 오디오 / 비디오 요소를 다시 로드합니다.
		 */
		public load(): void {
			let video = <HTMLMediaElement>this._getRenderer().getNamedNode("media");
			if (video) {
				video.load();
			}
		}
		/**
		 * 재생을 정지합니다.
		 */
		public pause(): void {
			let video = <HTMLMediaElement>this._getRenderer().getNamedNode("media");
			if (video) {
				video.pause();
			}
		}

		/**
		 * 전체화면을 요청합니다. IE11이상 지원합니다.
		 */
		public requestFullscreen(): void {
			let video = this._getRenderer().getNamedNode("media") as any;
			if (!video) {
				return;
			}
			if (video.requestFullscreen) {
				video.requestFullscreen();
			} else if (video.webkitRequestFullScreen) {
				video.webkitRequestFullScreen();
			} else if (video.mozRequestFullScreen) {
				video.mozRequestFullScreen();
			} else if (video.msRequestFullscreen) {
				video.msRequestFullscreen();
			}
		}

		/**
		 * 전체화면을 종료합니다. IE11이상 지원합니다.
		 */
		public exitFullscreen(): void {
			let video = this._getRenderer().getNamedNode("media") as any;
			if (!video) {
				return;
			}
			if (video.requestFullscreen) {
				video.requestFullscreen();
			} else if (video.webkitExitFullscreen) {
				video.webkitExitFullscreen();
			} else if (video.mozCancelFullScreen) {
				video.mozCancelFullScreen();
			} else if (video.msExitFullscreen) {
				video.msExitFullscreen();
			}
		}
	}
}