/// <reference path="./TabFolder.ts" />

namespace cpr.controls {
	/**
	 * MDIFolder
	 * app을 추가 할 수 있는 탭폴더 컴포넌트.
	 * 
	 * @firesgroup bindcontext
	 * @firesgroup drop
	 * 
	 * @fires cpr.events.CMouseEvent#contextmenu 마우스의 컨텍스트메뉴가 호출되는 이벤트. 
	 * TabHeader에만 컨텍스트메뉴를 제공합니다.<br>
	 * 시스템의 컨텍스트 메뉴를 방지 하려면 event.preventDefault()를 작성 해야합니다.<br>
	 * <pre>event.targetObject.item: {cpr.controls.TabItem | null} 마우스 포인터에 위치한 탭아이템을 가져옵니다. 없으면 null입니다.</pre>
	 * 
	 * @fires cpr.events.CSelectionEvent#before-selection-change TabItem을 선택하기 전에 발생하는 이벤트.
	 * 다음 이벤트로 selection-change를 발생합니다.
	 * <pre>oldSelection: {cpr.controls.TabItem} 이전에 선택한 아이템</pre>
	 * <pre>newSelection: {cpr.controls.TabItem} 선택이 변경될 아이템</pre>
	 * 
	 * @fires cpr.events.CSelectionEvent#selection-change TabItem을 선택한 후에 발생하는 이벤트.
	 * <pre>oldSelection: {cpr.controls.TabItem} 이전에 선택한 아이템</pre>
	 * <pre>newSelection: {cpr.controls.TabItem} 선택이 변경된 아이템</pre>
	 * 
	 * @fires cpr.events.CUIEvent#close 탭 아이템을 닫을 때 발생하는 이벤트이며, 사용자가 취소 할 수 있습니다.
	 * <pre>content: {cpr.controls.TabItem} 닫히는 탭아이템</pre>
	 * 
	 * @fires cpr.events.CItemEvent#tabheader-click 탭 헤더를 클릭할때 발생하는 이벤트.
	 * <pre>item: {cpr.controls.TabItem} 클릭한 아이템</pre>
	 * 
	 * @fires cpr.events.CItemEvent#content-init TabItem의 Content가 그려질 준비를 마쳤을 때 호출되는 이벤트로 컨트롤을 그리는 스크립트가 동작한 후 호출됨.
	 * <pre>content: {cpr.controls.TabItem} 해당 컨텐츠의 탭아이템</pre>
	 * 
	 * @fires cpr.events.CItemEvent#content-load TabItem의 Content가 그려지고 브라우저에 표현되기 직전에 호출됨.
	 * <pre>content: {cpr.controls.TabItem} 해당 컨텐츠의 탭아이템</pre>
	 * 
	 * @fires cpr.events.CItemEvent#content-ready TabItem의 Content가 그려질 준비를 마쳤을 때 호출되는 이벤트로 컨트롤을 그리는 스크립트가 동작하기 전에 호출됨.
	 * <pre>content: {cpr.controls.TabItem} 해당 컨텐츠의 탭아이템</pre>
	 */
	export class MDIFolder extends TabFolder {

		/**
		 * MDI 폴더를 생성합니다.
		 * @param id MDI 폴더의 id
		 */
		constructor(id?: string) {
			super(id);

			// control initializing
			this._initControl();
		}

		//TabFolder 속성 사용
		protected override _isConfigurableProperty(propName: string): boolean {
			if (MDIFolder._AVAILABLE_PROP.indexOf(propName) != -1) {
				return true;
			}
			return super._isConfigurableProperty(propName);
		}

		// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/4438
		/**
		 * MDI 폴더에 특정 앱을 로드하고 추가 합니다.
		 * 
		 * @param index 삽입할 탭 인덱스. 0 기준.
		 * @param appId  추가할 app.
		 * @param select 추가할 app의 선택 여부. 기본 값은 true.
		 * @param appLoadCompleteCallback App이 로드된 후 호출되는 TabItem을 인자로 받는 callback 메소드.
		 */
		public insertItemWithApp(index: number, appId: app_id_string, select: boolean = true, appLoadCompleteCallback?: (item: TabItem, app: core.App) => void): TabItem {
			let item = new TabItem();
			item.text = "Loading";
			item.closable = true;

			this.insertTabItem(index, item);
			core.App.load(appId, (app: core.App) => {
				// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/issues/2356
				if (!app) {
					item.text = "Not Found";
					item.content = new controls.Container();
				}
				else {
					item.text = app.title;
					let embeddedApp: EmbeddedApp = new EmbeddedApp(null, app);
					item.content = embeddedApp;

					embeddedApp.addEventListener("app-ready", (e: events.CEvent) => {
						this._appReadyHandler(e, item);
					});
					embeddedApp.addEventListener("init", (e: events.CEvent) => {
						this._appInitHandler(e, item);
					});
					embeddedApp.addEventListener("load", (e: events.CEvent) => {
						this._appLoadHandler(e, item);
					});
				}

				if (appLoadCompleteCallback) {
					appLoadCompleteCallback(item, app);
				}
			});
			if (select) {
				this.setSelectedTabItem(item);
			}
			return item;
		};

		/**
		 * App으로 된 Item을 추가합니다.<br>
		 * App을 추가 후 select 여부를 설정합니다.
		 * 기본 값은 true 입니다.
		 * @param appId  추가할 app.
		 * @param select 추가할 app의 선택 여부. 기본 값은 true.
		 * @param appLoadCompleteCallback App이 준비된 후 호출되는 TabItem을 인자로 받는 callback 메소드.
		 * @return 추가한 Item
		 */
		public addItemWithApp(appId: app_id_string, select: boolean = true, appLoadCompleteCallback?: (item: TabItem, app: core.App) => void): TabItem {
			return this.insertItemWithApp(this._tabItems.length, appId, select, appLoadCompleteCallback);
		}

		/**
		 * App ID로 해당 앱을 포함하는 TabItem을 찾습니다.
		 * 존재하지 않는 경우, null이 반환됩니다.
		 * @param appId 검색할 appId
		 */
		public findItemWithAppID(appId: app_id_string): TabItem {
			let items = this.getTabItems();
			for (let idx = 0; idx < items.length; idx++) {
				let eachItem = items[idx];
				if (eachItem.content instanceof EmbeddedApp) {
					let embeddedApp = eachItem.content as EmbeddedApp
					if (embeddedApp.app && embeddedApp.app.id == appId) {
						return eachItem;
					}
				}
			}
			return null;
		}

		/**
		 * Page로 된 Item을 추가합니다.<br/>
		 * Page를 추가 후 select 여부를 설정합니다.
		 * @param src 추가할 Page의 경로.
		 * @param select 추가할 Page의 선택여부. 기본 값은 true.
		 * @param pageLoadCompleteCallback Page가 준비된 후 호출되는 TabItem을 인자로 받는 callback 메소드.
		 * @return 추가된 Item
		 */
		public addItemWithPage(src: string, select: boolean = true, pageLoadCompleteCallback?: (item: TabItem) => void): TabItem {
			let item = new TabItem();
			item.text = "Loading";
			item.closable = true;

			this.addTabItem(item);

			let embeddedPage: controls.EmbeddedPage = new controls.EmbeddedPage();
			embeddedPage.src = src;
			item.content = embeddedPage;
			if (pageLoadCompleteCallback) {
				embeddedPage.addEventListener("load", (e: events.CEvent) => {
					pageLoadCompleteCallback(item);
				});
			}
			if (select) {
				this.setSelectedTabItem(item);
			}
			return item;
		}

		private _appReadyHandler(e: events.CEvent, item: TabItem): void {
			let closeEvent = new events.CUIEvent("content-ready", {
				content: item
			});
			this.dispatchEvent(closeEvent);
		}

		private _appInitHandler(e: events.CEvent, item: TabItem): void {
			let closeEvent = new events.CUIEvent("content-init", {
				content: item
			});
			this.dispatchEvent(closeEvent);
		}

		private _appLoadHandler(e: events.CEvent, item: TabItem): void {
			let closeEvent = new events.CUIEvent("content-load", {
				content: item
			});
			this.dispatchEvent(closeEvent);
		}

		override _getType(): ControlType {
			return ControlType.MDIFOLDER;
		}

		protected _getStylerSpec(): UIControlStylerSpec {
			let tabfolderStyle: UIControlStylerSpec = super._getStylerSpec();
			tabfolderStyle.root.baseClass = tabfolderStyle.root.baseClass + " cl-mdifolder";

			return tabfolderStyle;
		}

	}
}