namespace cpr.data.tabledata {
	/**
	 * 로우의 상태 값에 대한 key, value
	 */
	export enum RowState {
		/**
		 * 삭제된 로우 커밋 시 삭제 배열에서 제거하기 위한 임시 상태.
		 * @private
		 */
		EMPTIED = 0x001,

		/**
		 * 변경되지 않은 상태.
		 */
		UNCHANGED = 0x001, // 0001

		/**
		 * 행이 신규로 추가된 상태.
		 */
		INSERTED = 0x002, // 0010

		/**
		 * 행이 수정된 상태.
		 */
		UPDATED = 0x004, // 0100

		/**
		 * 행이 삭제된 상태.
		 */
		DELETED = 0x008, // 1000

		/**
		 * 행이 추가되었다가 삭제된 상태.
		 */
		INSERTDELETED = 0x010, // 10000

		/**
		 * MODIFIED는 변경된 상태(INSERTED, UPDATED, DELETED)를 의미합니다.
		 */
		MODIFIED = (INSERTED | UPDATED | DELETED), // 1110

		/**
		 * ALL은 INSERTDELETED를 제외한 모든 상태를 의미합니다.
		 */
		ALL = (MODIFIED | UNCHANGED) // 1111
	}
}