namespace cpr.controls.item {

	/**
	 * @private
	 */
	export class ItemFilter {
		private _filterExpression: cpr.expression.Expression;

		public get filterExpression(): cpr.expression.Expression {
			return this._filterExpression;
		}

		public set filterExpression(filterExpression: cpr.expression.Expression) {
			this._filterExpression = filterExpression;
		}

		/**
		 * 필터가 있는지 유무를 확인합니다.
		 */
		public hasFilter(): boolean {
			return this._filterExpression != null;
		}

		/**
		 * 필터 익스프레션 값을 반환합니다.
		 * @return 필터 익스프레션 값
		 */
		public get filter(): expression_string {
			if (this._filterExpression) {
				return this._filterExpression.src;
			}
			return null;
		}

		/**
		 * 리스트 데이터에 필터를 적용합니다.
		 * @param filterExpression 필터 조건 expression.
		 */
		public set filter(filterExpression: expression_string) {
			if (filterExpression) {
				this._filterExpression = new expression.Expression(filterExpression);
			} else {
				this._filterExpression = null;
			}
		}
		/**
		 * 적용된 필터를 제거합니다.
		 */
		public clearFilter(): void {
			if (this._filterExpression != null) {
				this._filterExpression = null;
			}
		}

		public dispose(): void {
			this._filterExpression = null;
		}
	}
}