namespace cpr.protocols.matrix {


	/**
	 * @private
	 */
	export class MatrixResponseParser implements ResponseParser {
		private static _instance: MatrixResponseParser;

		public static get INSTANCE(): MatrixResponseParser {
			if (!MatrixResponseParser._instance) {
				MatrixResponseParser._instance = new MatrixResponseParser();
			}
			return MatrixResponseParser._instance;
		}


		constructor() {
		}

		public load(submission: MatrixSubmission, xhr: XMLHttpRequest): void {
			// do nothing
		}

		public _abortLoading(submission: AbstractSubmission): void {
			// do nothing
		}

		public parse(submission: MatrixSubmission, xhr: XMLHttpRequest, doneHandler: () => void): void {
			if (submission instanceof MatrixSubmission == false) {
				throw new exceptions.IllegalArgumentException("cpr.protocols.MatrixSubmission");
			}

			// TODO BLOB 처리에 대한 고려
			let response: string = xhr.responseText;
			this._parseData(submission, response, doneHandler);
		}

		public _parseData(submission: MatrixSubmission, response: string, doneHandler: () => void): void {
			let matrixDataModel: MatrixDataModel = submission._getProtocolDataModel() as MatrixDataModel;
			let responseModel: ResponseMetaModel = matrixDataModel._getResponseMatrix();

			let jsonRes: any = null;
			try {
				if (response && response.length > 2) {
					let parser: utils.JSONParser = new utils.JSONParser();
					jsonRes = parser.parse(response);
				} else {
					if (responseModel && responseModel.format === "array") {
						jsonRes = [];
					} else {
						jsonRes = {};
					}
				}
			} catch (e) {
				submission._onError(e);
				return;
			}

			// 응답데이터를 JSONObject로 정상파싱했을 때 RECEIVE_JSON 이벤트 발생.
			let subEvent: events.CSubmissionEvent = submission._createSubmitEvent(events.SubmissionEventType.RECEIVE_JSON, { content: jsonRes });
			let isContinue: boolean = submission.dispatchEvent(subEvent);
			if (isContinue == false) {
				doneHandler();
				return;
			}

			try {
				let dataControls: (data.DataCollection | data.DataMap)[] = [];

				this._initDataControls(responseModel, dataControls, false);

				if (responseModel) {
					let dataControl = responseModel.dataControl as data.DataCollection | data.DataMap;
					let data: number | string | ResponseDataModel = responseModel.data;
					let dataContext: MatrixDataContext = null;
					if (dataControl) {
						dataContext = new MatrixDataContext(dataControl);
					}
					if (data) {
						let childModel: ResponseDataModel = data as ResponseDataModel;
						if (responseModel.format === "array" && Array.isArray(jsonRes)) {
							let dataSet: data.DataSet = dataControl as data.DataSet;
							for (let idx: number = 0; idx < jsonRes.length; idx++) {
								let resData: any = jsonRes[idx];
								let childDataContext: MatrixDataContext = null;

								if (dataSet != null) {
									let row: data.IDataRow = dataSet.pushRowSilently({});
									childDataContext = new MatrixDataContext(row);
								}
								for (let attName in resData) {
									let attSchema: ResponseMetaModel = childModel[attName];
									let resAttValue: any = resData[attName];
									this._parseAttribute(resAttValue, attSchema, childDataContext, dataControls);
								}
							}
						} else {
							for (let attName in childModel) {
								let attSchema: ResponseMetaModel = childModel[attName];
								let resAttValue: any = jsonRes[attName];
								this._parseAttribute(resAttValue, attSchema, dataContext, dataControls);
							}
						}
					}
				}
				for (let idx: number = 0; idx < dataControls.length; idx++) {
					let dataControl: data.DataCollection | data.DataMap = dataControls[idx];
					if (dataControl instanceof data.DataCollection) {
						dataControl.refresh();
					}
					let loadEvent = new events.CDataEvent(cpr.events.DataEventType.LOAD);
					dataControl.dispatchEvent(loadEvent);
				}
			} catch (e) {
				submission._onError(e);
				return;
			}

			if (doneHandler) {
				doneHandler();
			}
		}

		private _parseAttribute(resAttValue: any, attSchema: ResponseMetaModel, dataContext: MatrixDataContext, dataControls: (data.DataCollection | data.DataMap)[]): void {
			if (resAttValue == null) {
				return;
			}
			if (attSchema == null) {
				return;
			}
			let format: MetaModelFormat = attSchema.format;
			let dataControl = attSchema.dataControl as data.DataCollection | data.DataMap;
			let path: string = attSchema.path;
			let resMetaModelData: number | string | ResponseDataModel = attSchema.data;

			switch (format) {
				case "simple": {
					if (dataControl && path) {
						let localDataContext: MatrixDataContext = new MatrixDataContext(dataControl);
						localDataContext._setValue(path, resAttValue);
					} else if (path) {
						if (dataContext) {
							dataContext._setValue(path, resAttValue);
						}
					}
					break;
				}
				case "object": {
					let childDataContext: MatrixDataContext = dataContext;
					let childModel: ResponseDataModel = resMetaModelData as ResponseDataModel;
					if (dataControl) {
						if (dataControl instanceof data.DataMap) {
							// datamap
							childDataContext = new MatrixDataContext(dataControl);
							// 하위 호환성 유지: 응답 데이터가 빈 데이터일 경우 기존 데이터를 유지해야 하므로,
							// 파싱 전 단계에서 명시적으로 초기화를 수행함
							// (원칙적으로는 _initDataControls에서 처리 대상) (#10957 #10941 관련)
							dataControl._resetData(data.DataUtil._getDefaultValue());

							for (let childAttName in childModel) {
								let childAttSchema: MetaModel = childModel[childAttName];
								let childResAttValue: any = resAttValue[childAttName];
								this._parseAttribute(childResAttValue, childAttSchema, childDataContext, dataControls);
							}
						} else {
							// dataset
							let dataSet: data.DataSet = dataControl as data.DataSet; // TODO DataSet filtering 조건이 필요
							let linked: boolean = attSchema.linked;

							// link에 의한 filtering bind(#FIXME 현재는 DataCollection -> DataCollection 만 지원)
							// let oldBindedRowId: string = null;
							let parentRow: data.IDataRow = null;
							if (linked === true && dataContext) {
								// oldBindedRowId = dataSet.getBindedParentRowId();
								// let parentRow: data.IDataRow = dataContext._getRowContext();
								// if (parentRow) {
								// 	dataSet._bindParentRow(parentRow, false);
								// }
								parentRow = dataContext._getRowContext();
							}

							let objectValue: {} = resAttValue as {};
							// let row: data.Row = dataSet.pushRow();
							// let childDataContext: DataContext = new DataContext(row);
							let row: data.IDataRow = dataSet.pushRowSilently({}, parentRow);
							let childDataContext: MatrixDataContext = new MatrixDataContext(row);

							for (let childAttName in childModel) {
								let childAttSchema: MetaModel = childModel[childAttName];
								let childResAttValue: any = objectValue[childAttName];
								this._parseAttribute(childResAttValue, childAttSchema, childDataContext, dataControls);
							}

							// link에 의한 filtering unbind(#FIXME 현재는 DataCollection -> DataCollection 만 지원)
							// if (linked === true && dataContext) {
							// 	dataSet._bindParentRowId(oldBindedRowId, false);
							// }
						}
					} else {
						for (let childAttName in childModel) {
							let childAttSchema: MetaModel = childModel[childAttName];
							let childResAttValue: any = resAttValue[childAttName];
							this._parseAttribute(childResAttValue, childAttSchema, childDataContext, dataControls);
						}
					}
					break;
				}
				case "array": {
					let childModel: ResponseDataModel = resMetaModelData as ResponseDataModel;
					let dataSet: data.DataSet = dataControl as data.DataSet; // TODO DataSet filtering 조건이 필요
					let linked: boolean = attSchema.linked;

					// link에 의한 filtering bind(#FIXME 현재는 DataCollection -> DataCollection 만 지원)
					// let oldBindedRowId: string = null;
					let parentRow: data.IDataRow = null;
					if (linked === true && dataContext) {
						// oldBindedRowId = dataSet.getBindedParentRowId();
						// let parentRow: data.IDataRow = dataContext._getRowContext();
						// if (parentRow) {
						// 	dataSet._bindParentRow(parentRow, false);
						// }
						parentRow = dataContext._getRowContext();
					}

					if (_isArray(resAttValue)) {
						let arrayValue: {}[] = resAttValue as {}[];
						for (let idx: number = 0; idx < arrayValue.length; idx++) {
							let objectValue: {} = arrayValue[idx];

							let childDataContext: MatrixDataContext = null;
							if (dataSet != null) {
								let row: data.IDataRow = dataSet.pushRowSilently({}, parentRow);
								childDataContext = new MatrixDataContext(row);
							}

							for (let childAttName in childModel) {
								let childAttSchema: MetaModel = childModel[childAttName];
								let childResAttValue: any = objectValue[childAttName];
								this._parseAttribute(childResAttValue, childAttSchema, childDataContext, dataControls);
							}
						}
					} else {
						// link에 의한 filtering unbind(#FIXME 현재는 DataCollection -> DataCollection 만 지원)
						// if (linked === true && dataContext) {
						// 	dataSet._bindParentRowId(oldBindedRowId, false);
						// }

						throw new exceptions.IllegalArgumentException("protocol format mismatch : " + resAttValue);
					}

					// link에 의한 filtering unbind(#FIXME 현재는 DataCollection -> DataCollection 만 지원)
					// if (linked === true && dataContext) {
					// 	dataSet._bindParentRowId(oldBindedRowId, false);
					// }

					break;
				}
			}
		}

		private _initDataControls(responseModel: ResponseMetaModel, dataControls: (data.DataCollection | data.DataMap)[], isParentClear: boolean): void {
			if (!responseModel) {
				return;
			}

			let dataControl = responseModel.dataControl as data.DataCollection | data.DataMap;
			let isadd: boolean = responseModel.isAdd === true ? true : false;
			let dataModel: number | string | ResponseDataModel = responseModel.data;

			if (dataControl) {
				if (dataControls.indexOf(dataControl) == -1) {
					dataControls[dataControls.length] = dataControl;
					if (dataControl instanceof data.DataCollection) {
						// DataSet이 clear되거나 상위가 clear 될 때 bindParentRow를 초기화 함
						if (isadd === false) {
							dataControl.clearData(false);
							if (responseModel.linked === true) {
								dataControl.bindParentRow(null);
							}
						} else if (isParentClear === true && responseModel.linked === true) {
							dataControl.bindParentRow(null);
						}
					}
				}
			}

			if (dataModel) {
				let format: MetaModelFormat = responseModel.format;

				if (format == "object" || format == "array") {
					let childModel: ResponseDataModel = dataModel as ResponseDataModel;
					for (let attName in childModel) {
						let attSchema: ResponseMetaModel = childModel[attName];
						this._initDataControls(attSchema, dataControls, isadd === false);
					}
				}
			}
		}
	}
}