		public getSort(): boolean {
			let sortInfo: { colNm: string, asc: boolean, idx: number } = this.context.getGrid()._getMultiSortInfo(this.targetColumnName);
			if (sortInfo != null) {
				return sortInfo.asc;
			}
			return null;
		}

		/**
		 * 해당 헤더 셀이 정렬되도록 합니다. <br>
		 * 그리드 헤더의 정렬 스타일이 적용됩니다.<br>
		 * 데이터셋의 sort와는 별개로 관리됩니다.
		 * 
		 * @param asc 오름차순/내림차순. (true: 오름차순 / false: 내림차순)<br>
		 * 미기입시 기존에 헤더에서 동작하는 순서대로 동작합니다.(오름차순 → 내림차순 → 해제) <br>
		 * 특정 sort를 원하는 경우 해당 asending을 기입해주시면 됩니다.
		 * 
		 * @example
		 * <code>grid.header.getColumn(1).sort()</code><br>
		 * => cellIndex가 1인 헤더 셀을 정렬합니다.<br>
		 * <code>grid.header.getColumn(1).sort(false)</code><br>
		 * => cellIndex가 1인 헤더 셀을 내림차순으로 정렬합니다.<br>
		 */
		public sort(asc?: boolean): void {
			this.context.getGrid()._addMultiSortCondition(this.targetColumnName, asc, this.emptyValueSort);
			this.context.getGrid()._sortMulti();
		}

		/**
		 * 해당 헤더 셀의 정렬을 제거합니다.
		 */
		public clearSort(): void {
			this.context.getGrid()._clearMultiSort(this.targetColumnName);
		}

		/**
		 * 해당 헤더 셀에 적용된 filter 조건식을 반환합니다.
		 * @return filter 조건식.
		 */
		public getFilter(): string[] {
			if (this.targetColumnName == null) {
				return null;
			}

			let filterConditions: data.GridFilterCondition[] = this.context.getGrid()._getGridFilterCondition();
			let length: number = filterConditions.length;
			for (let i = 0; i < length; i++) {
				if (this.targetColumnName == filterConditions[i].colNm) {
					return _stream(filterConditions[i].valueSet).collect();
				}
			}
			return null;
		}

		/**
		 * 해당 헤더 셀이 필터되도록 합니다. <br>
		 * 그리드 헤더의 필터 스타일이 적용됩니다.<br>
		 * 데이터셋의 filter와는 별개로 관리됩니다.
		 * 
		 * @param filterValues 필터링할 값.
		 * 
		 * @example
		 * <code>grid.header.getColumn(1).filter(["A", "B"])</code><br>
		 * => cellIndex가 1인 헤더 셀의 값이 "A"와 "B"인 행만 필터링 합니다.<br>
		 * (값을 비교하는 데이터셋 컬럼은 헤더 셀의 targetColumnName 입니다.)
		 */
		public filter(filterValues: (string | number)[]): void {
			if (filterValues == null || filterValues.length == 0 || this.targetColumnName == null) {
				return;
			}

			let grid: Grid = this.context.getGrid();
			filterValues = filterValues.map((value: (string | number)) => {
				return (typeof value == "number") ? "" + value : value;
			});
			grid._addGridFilterCondition(this.targetColumnName, filterValues as string[]);
			grid._setFilterDialog(grid._getGridFilterCondition());
		}

		/**
		 * 해당 헤더 셀의 필터를 제거합니다.
		 */
		public clearFilter(): void {
			let grid: Grid = this.context.getGrid();
			grid._deleteFilterCondition(this.targetColumnName);

			let filterConditions: data.GridFilterCondition[] = grid.dataProvider._getFilterCondition();

			if (filterConditions.length == 0) {
				grid._clearFilterDialog();
			} else {
				grid._setFilterDialog(filterConditions);
			}
		}

