namespace cpr.protocols.response {

	/**
	 * @private
	 */
	export class BlobResponseHandler {
		private _loadendHandler: (ev: ProgressEvent, stringData: string) => void;
		private _parseErrorHandler: (err: Error) => void;
		private _loaderrorHandler: (ev: ProgressEvent) => void;


		constructor(loadendHandler: (ev: ProgressEvent, stringData: string) => void) {
			this._loadendHandler = loadendHandler;
		}

		public _setLoaderrorHandler(loaderrorHandler: (ev: ProgressEvent) => void): void {
			this._loaderrorHandler = loaderrorHandler;
		}

		public _setParseErrorHandler(parseErrorHandler: (err: Error) => void): void {
			this._parseErrorHandler = parseErrorHandler;
		}

		public _load(blob: Blob): void {
			let fileReader: FileReader = new FileReader();
			fileReader.onloadend = (ev: ProgressEvent) => this._doLoadend(ev, fileReader);
			fileReader.onerror = (ev: ProgressEvent) => this._doError(ev);

			fileReader.readAsArrayBuffer(blob);
		}

		private _doLoadend(ev: ProgressEvent, fileReader: FileReader): void {
			try {
				let readBuffer: ArrayBuffer = fileReader.result as ArrayBuffer;
				let stringView: utils.UTF8StringView = new utils.UTF8StringView(readBuffer);
				let stringData: string = stringView.toString();
				this._loadendHandler(ev, stringData);
			} catch (err) {
				if (this._parseErrorHandler) {
					this._parseErrorHandler(err);
				}
			}
		}

		private _doError(ev: ProgressEvent): void {
			if (this._loaderrorHandler) {
				this._loaderrorHandler(ev);
			}
		}

	}
}