
namespace cpr.data.tabledata {
	/**
	 * @private
	 */
	export class RowCtrlAttr {
		private _attr: { [key: string]: any };

		constructor() {
			this._attr = {};
		}

		_setCtrlAttr(key: string, value: any): void {
			this._attr[key] = value;
		}

		_getCtrlAttr(key: string): any {
			return this._attr[key];
		}

		_deleteCtrlAttr(key: string): any {
			delete this._attr[key];
		}

		_getCtrlAttrNames(): string[] {
			return Object.keys(this._attr);
		}

		_getCtrlAttrs(): { [attrName: string]: string } {
			return _shallowCopy(this._attr);
		}
	}
}