		private _touchRoller: internal.TouchRoller = internal.newTouchRoller();

		// post된 ScrollLeft에 의해 강제 설정된 scrollLeft 값을 보전하여
		// viewport의 scrollLeft 이동에 의해 재차 발생되는 scrollPost를 방지하기 위한 변수
		protected _settedScrollLeft: number = -1;
		protected _settedScrollTop: number = -1;



		constructor(scrollPane: IScrollPane, context: GridContext) {
			this._scrollPane = scrollPane;
			this._context = context;
		}

		/* 내부 사용 Properties start */
		get context(): GridContext {
			return this._context;
		}
		get grid(): Grid {
			return this.context.getGrid();
		}
		get touchRoller(): internal.TouchRoller {
			return this._touchRoller;
		}
		get viewportscrolltop(): number {
			return this._viewportScrollTop;
		}
		set viewportscrolltop(scrollTop: number) {
			this._viewportScrollTop = scrollTop;
		}
		get viewportscrollleft(): number {
			return this._viewportScrollLeft;
		}
		set viewportscrollleft(scrollLeft: number) {
			this._viewportScrollLeft = scrollLeft;
		}
		get rowheight(): number {
			return this.context._getDesignDetailRowHeight();
		}
		public _isEnabled(): boolean {
			return this.grid.enabled;
		}
		/* 내부 사용 Properties end */

		protected _getScrollPane(): IScrollPane {
			return this._scrollPane;
		}

		public _getViewportWidth(): number {
			return this.context._getViewportWidth(this._scrollPane.region, this._scrollPane.location);
		}

		public _getViewportHeight(): number {
			return this.context._getViewportHeight(this._scrollPane.location);
		}

		public abstract _getRenderedMaxScrollTop(): number;
		public abstract _getRenderedMaxScrollLeft(): number;

		public abstract _readyForRedraw(): void;

		public abstract _initScrollTop(scrollTop: number): void;
		public abstract _initScrollLeft(scrollLeft: number): void;

		protected _init(): void {
		}
		public abstract _createScrollPane(): ufc.ControlShape;

		/* EventHandler */
		protected abstract _dispatchScrollEvent(e, axis: events.ScrollAxis): void;

		/* DOM EventHandler start */
		protected abstract _onViewportScroll(e: events.CUIEvent): void;

		protected _adjustViewportScroll(e: events.CEvent, scrollTop: number, scrollLeft: number): events.ScrollAxis {
			let verticalMoved: boolean = false;
			let horizontalMoved: boolean = false;
			if (this.viewportscrolltop != scrollTop) {
				verticalMoved = true;
			}
			if (this.viewportscrollleft != scrollLeft) {
				horizontalMoved = true;
			}
			if (verticalMoved && horizontalMoved) {
				this._scrollPane._postScroll(scrollTop, scrollLeft, e);
				return events.ScrollAxis.both;
			} else if (verticalMoved) {
				this._scrollPane._postScrollTop(scrollTop, e);
				return events.ScrollAxis.y;
			} else if (horizontalMoved) {
				this._scrollPane._postScrollLeft(scrollLeft, e);
				return events.ScrollAxis.x;
			}

			return null;
		}

		/**
		 * IE 이외의 브라우저에서 발생하는 wheel event 처리.
		 * IE의 경우 addEventListener로만 동작하며, 현재 이 기능을 사용함.
		 */
		protected abstract _onDOMWheel(e: events.CWheelEvent): void;

		protected _onTouchStart(e: events.CTouchEvent): void { // 걷어 낼 것
			if (this._isEnabled() == false) {
				return;
			}
			if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) {
				return;
			}
			this.touchRoller._touchStart(e, this.viewportscrolltop, this.viewportscrollleft);
		}
		protected _onTouchMove(e: events.CTouchEvent): void {
			if (e._isOccupied() == true || this._context._isTouchResizing() == true) {
				return;
			}

			let axis: events.ScrollAxis = null;
			this.touchRoller._touchMove(e, (scrollTop: number, scrollLeft: number): boolean => {
				axis = this._adjustScroll(e, scrollTop, scrollLeft);
				if (axis != null) {
					this._dispatchScrollEvent(e, axis); // grid scroll event

					e._setOccupied(true);
					return true;
				}

				return false;
			});

			if (axis == null && this._context.getGrid().overscrollBehavior == OverscrollBehaviorType.NONE) {
				e.preventDefault();
				e._setOccupied(true);
			}
		}
		protected _onTouchEnd(e: events.CTouchEvent): void {
			this.touchRoller._touchEnd(e, this.viewportscrolltop, this.viewportscrollleft,
				(scrollTop: number, scrollLeft: number): boolean => {
					let axis: events.ScrollAxis = this._adjustScroll(e, scrollTop, scrollLeft);
					if (axis != null) {
						this._dispatchScrollEvent(e, axis); // grid scroll event
						return true;
					}
					return false;
				}
			);
		}

		/**
		 * wheel event를 adjust-scroll event로 변경
		 */
		protected abstract _adjustScroll(e: events.CEvent, scrollTop: number, scrollLeft: number): events.ScrollAxis;

		/**
		 * VScroll Horizontal Scroll 이벤트 처리
		 */
		public abstract _handleScrollLeft(e: events.CScrollEvent): void;

		/**
		 * Horizontal Scroll 이벤트를 받아 viewport의 left 위치 변경
		 */
		protected abstract _setHScroll(scrollLeft: number): void;

		protected _syncScrollFunc: Function = () => this._syncScroll();
		protected abstract _syncScroll(): void;
		/* DOM EventHandler end */

