/// <reference path="../utils/StringUtil.ts"/>

namespace cpr.ufc {
	/**
	 * @private
	 */
	export class DOMUIObject {
		private _uiShape: UIShape | string;
		private _valueNodes: { [key: string]: string };
		private _eventListeners: DOMEventAttachementSpec[] = [];

		constructor(uiShape: UIShape | string) {
			this._uiShape = uiShape;
			this._valueNodes = {};
		}

		get htmlText(): string {
			return this._translateToHTML(this._uiShape);
		}

		public getEventListeners(): DOMEventAttachementSpec[] {
			return this._eventListeners;
		}

		public _getValueNodes(): { [key: string]: string } {
			return this._valueNodes;
		}

		get children(): DOMUIObject[] {
			if (typeof this._uiShape == "string") {
				return [];
			}
			let children: DOMUIObject[] = [];
			let uishape: UIShape = this._uiShape as UIShape;
			if (uishape.children && uishape.children.length > 0) {
				uishape.children.forEach((child: string | UIShape) => {
					children.push(new DOMUIObject(child));
				});
			}

			return children;
		}

		/* helper methods */
		private _translateToHTML(uishape: UIShape | string): string {
			if (uishape == null) {
				return "";
			}
			if (typeof uishape == "string") {
				// return encoder.encodeForHTML(uishape as string);
				return utils.HTMLEncoder.encodeForHTML(uishape as string);
			}

			let shape: UIShape = uishape as UIShape;
			let stringbuilder: string[] = [];
			stringbuilder.push("<" + shape.tag + " ");
			// classNames
			if (shape.classNames != null && shape.classNames.length > 0) {
				// stringbuilder.push('class="' + encoder.encodeForHTMLAttribute(shape.classNames.join(" ")) + '" ');
				stringbuilder.push('class="' + utils.HTMLEncoder.encodeForHTMLAttribute(shape.classNames.join(" ")) + '" ');
			}
			// styles
			if (uishape.style && uishape.style.cssText != null && uishape.style.cssText != "") {
				stringbuilder.push('style="');
				// stringbuilder.push(encoder.encodeForHTMLAttribute(uishape.style.cssText));
				stringbuilder.push(utils.HTMLEncoder.encodeForHTMLAttribute(uishape.style.cssText));
				stringbuilder.push('" ');
			}
			// attributes
			if (shape.attr != null) {
				for (let attrName in shape.attr) {
					// stringbuilder.push(encoder.encodeForHTMLAttribute(attrName) + '="');
					stringbuilder.push(utils.HTMLEncoder.encodeForHTMLAttribute(attrName) + '="');
					if (shape.attr[attrName] == "") {
						stringbuilder.push(shape.attr[attrName]);
					} else {
						// stringbuilder.push(encoder.encodeForHTMLAttribute(shape.attr[attrName]));
						stringbuilder.push(utils.HTMLEncoder.encodeForHTMLAttribute(shape.attr[attrName]));
					}
					stringbuilder.push('" ');
				}
			}

			// events : event delegated by xb
			if (shape.events != null) {
				let ndid: string = shape.attr[ControlRenderer._ATTR_UUID];
				let events: DOMEventAttachementMap = {};

				for (let eventType in shape.events) {
					let eventHandler = shape.events[eventType];
					events[eventType] = eventHandler;
				}

				this._eventListeners.push({ ndid: ndid, events: events });
			}

			/**
			 * value properties는 VDOM일 경우 DOM을 접근하여 설정하면
			 * cursor의 위치 및 selection 까지 보장할 수 있음.
			 * innerHTML에서는 보장할 수 없음.(textarea의 text, select 등...) {input, textarea, select}
			 */
			if (shape.tag === "input") {
				if (shape.hasOwnProperty('value')) {/* input value 처리 */
					if (shape["value"] != "") {
						// stringbuilder.push("value='" + encoder.encodeForHTMLAttribute(shape["value"]) + "' ");
						// IE에서 input 태그의 value에 한글이 들어간 값이 설정되면 input 이벤트가 발생하기 때문에 Input 태그에 value로 설정해주어야 함.
						this._valueNodes[shape.attr[ControlRenderer._ATTR_UUID]] = shape["value"];
					}
				}
				stringbuilder.push("/>");
			} else if (shape.tag === "textarea") {
				stringbuilder.push(">");
				if (shape.hasOwnProperty('value')) {/* textarea value 처리 */
					if (shape["value"] != "") {
						// stringbuilder.push(encoder.encodeForHTML(shape["value"]));
						stringbuilder.push(utils.HTMLEncoder.encodeForHTML(shape["value"]));
					}
				}
				stringbuilder.push("</textarea>");
			} else {
				stringbuilder.push(">");
				if (shape.innerHTML != null) {
					// TODO Encoding CHECK
					stringbuilder.push(shape.innerHTML);
				} else
					// children
					if (shape.children != null && shape.children.length > 0) {
						if (shape.children.length == 1 && typeof shape.children[0] == "string") {
							let textnode: string = shape.children[0] as string;
							if (utils.StringUtil.isCharRefText(textnode) == true) {
								stringbuilder.push(utils.StringUtil._encodeMinimizeForHTML(textnode));
							} else {
								// stringbuilder.push(encoder.encodeForHTML(textnode));
								stringbuilder.push(utils.HTMLEncoder.encodeForHTML(textnode));
							}
						} else {
							shape.children.forEach((child: string | UIShape) => {
								stringbuilder.push(this._translateToHTML(child));
							});
						}
					}

				stringbuilder.push("</" + shape.tag + ">");
			}

			return stringbuilder.join("");
		}
	}

	/**
	 * @private
	 */
	export class HTMLRendering {

		/**
		 * 
		 * @param rootId 
		 * @param newShape 
		 * @param oldShape 
		 * @param parentUUID 
		 * @returns 렌더링 성공 여부.
		 */
		public static draw(rootId: string, newShape: UIShape, oldShape: UIShape, parentUUID: string = null): boolean {
			let rootNode: HTMLElement = null;
			if (rootId != null) {
				rootNode = document.getElementById(rootId);
			}

			return HTMLRendering.drawElement(rootNode, newShape, oldShape, parentUUID);
		}

		public static drawElement(rootNode: HTMLElement, newShape: UIShape, oldShape: UIShape, parentUUID: string = null): boolean {
			let domUIObject: DOMUIObject = new DOMUIObject(newShape);
			// 쪼개서 넣을 경우 성능이 더 좋아짐.
			// TODO Container 요소와 Layout 요소를 분리해서 먼저 Container, Layout을 
			let baseElement: HTMLElement = null;

			if (rootNode) {
				baseElement = rootNode.parentElement;

				(rootNode as HTMLDivElement).outerHTML = domUIObject.htmlText;
			} else {
				if (parentUUID) {
					baseElement = document.getElementById(parentUUID);
				}
				if (baseElement == null) {
					if (oldShape) {
						console.error("node not found");
						return false;
					}
					baseElement = document.body;
				}

				let dummyElement: HTMLDivElement = document.createElement("div");
				dummyElement.style.display = "none";
				dummyElement = baseElement.appendChild(dummyElement) as HTMLDivElement;
				dummyElement.outerHTML = domUIObject.htmlText;
			}

			// set input values
			HTMLRendering._attachInputValues(baseElement, domUIObject._getValueNodes());

			// add event listeners
			let eventListeners: {
				ndid: string, events: {
					[eventType: string]: {
						capturing: boolean, handler: (e: Event) => void
					}
				}
			}[] = domUIObject.getEventListeners();
			eventListeners.forEach((item: {
				ndid: string, events: {
					[eventType: string]: {
						capturing: boolean, handler: (e: Event) => void
					}
				}
			}) => {
				let targetElement: HTMLElement = baseElement.querySelector('[data-ndid="' + item.ndid + '"]') as HTMLElement;
				if (targetElement) {
					for (let eventType in item.events) {
						// addEventListener의 성능이 IE에서는 아주 꼬지기 때문에 on[eventName]을 써야 함.VDOMRenderingDelegator.ts 참조.
						// https://jsperf.com/click-vs-addeventlistener/9
						let eventHandler: {
							capturing: boolean, handler: (e: Event) => void
						} = item.events[eventType];

						if (EventAttacher._mustAddEventListener(eventType) == true || eventHandler.capturing === true) {
							targetElement.addEventListener(eventType, eventHandler.handler, eventHandler.capturing);
						} else {
							targetElement["on" + eventType] = eventHandler.handler;
						}
					}
				} else {
					console.log("targetElement not found : " + item.ndid);
				}
			});

			return true;
		}

		private static _attachInputValues(rootNode: HTMLElement, values: { [key: string]: string }): void {
			// IE에서 input 태그의 value에 한글이 들어간 값이 설정되면 input 이벤트가 발생하기 때문에 Input 태그에 value로 설정해주어야 함.
			let inpNDID: string[] = _.keys(values);
			let domTraverser: DOMTraverser = null;
			for (let idx: number = 0; idx < inpNDID.length; idx++) {
				let ndid: string = inpNDID[idx];
				let txtValue: string = values[ndid];
				if (!txtValue) {
					txtValue = "";
				}

				domTraverser = _traverseFromElement(rootNode);
				domTraverser = domTraverser._find(`[${ControlRenderer._ATTR_UUID}="${ndid}"]`);
				if (domTraverser) {
					let inputTag: HTMLInputElement = domTraverser._getElement() as HTMLInputElement;
					if (inputTag.value != txtValue) {
						inputTag.value = txtValue;
					}
				}
			}
		}
	}
}