namespace cpr.utils {
	/**
	 * @private
	 */
	export class StringBuffer {
		private _buffer: string[];
		constructor() {
			this._buffer = [];
		}

		private _toArray(str: string) {
			let index = 0;
			let length = str.length;
			let output = [];

			for (; index < length - 1; ++index) {
				let charCode = str.charCodeAt(index);
				if (charCode >= 0xD800 && charCode <= 0xDBFF) {
					charCode = str.charCodeAt(index + 1);
					if (charCode >= 0xDC00 && charCode <= 0xDFFF) {
						output.push(str.slice(index, index + 2));
						++index;

						if (index == str.length - 1) {
							return output;
						}
						continue;
					}
				}
				output.push(str.charAt(index));
			}
			output.push(str.charAt(index));
			return output;
		}

		/**
		 * 텍스트를 추가합니다.
		 * @param text 
		 */
		public append(text: string[]);
		public append(text: string)
		public append(text: any) {
			if (_isArray(text) == false) {
				text = this._toArray(text);
			}
			this._buffer = this._buffer.concat(text);
			return this;
		}
		/**
		 * 텍스트를 삽입합니다.
		 * @param text 
		 * @param index 
		 */
		public insert(text: string[], index: number);
		public insert(text: string, index: number);
		public insert(text: any, index: number) {
			if (index < 0) {
				throw new exceptions.IllegalArgumentException("index must be 0 or greater.");
			}
			if (_isArray(text) == false) {
				text = this._toArray(text);
			}
			let firstTmp: string[], endTmp: string[];
			if (this._buffer.length < index) {
				firstTmp = this._buffer;
				endTmp = [];
			} else {
				firstTmp = this._buffer.slice(0, index);
				endTmp = this._buffer.slice(index, this._buffer.length);
			}
			this._buffer = firstTmp.concat(text).concat(endTmp);
			return this;
		}

		public getIndexBySelection(selection: number) {
			let text = "";
			let i = 0;
			for (; i < this._buffer.length; i++) {
				if (text.length == selection) {
					return i;
				}
				text += this._buffer[i];
			}
			if (text.length == selection) {
				return i;
			}
			return -1;
		}

		/**
		 * 길이를 반환합니다.
		 */
		public get length() {
			return this._buffer.length;
		}

		/**
		 * 인덱스의 캐릭터를 삭제합니다.
		 * @param index 
		 */
		public deleteCharAt(index: number) {
			this._buffer.splice(index, 1);
		}
		/**
		 * 텍스트를 반환합니다.
		 * @returns 
		 */
		public toString() {
			return this._buffer.join("");
		}
	}
}