/// <reference path="./Scope.ts" />
namespace cpr.core {
	type NestingSearchable = {
		_lookupDrillDownByUUID(uuid: string): Identifiable;
	};

	function isNestingSearchable(obj: any): obj is NestingSearchable {
		return typeof obj?._lookupDrillDownByUUID == "function";
	}

	/**
	 * @private
	 */
	export class ScopeImpl implements Scope {
		private _objectsByID: CMap<string, Identifiable> = _createMap();
		private _objectsByUUID: CMap<string, Identifiable> = _createMap();
		private _parentScope: Scope;


		constructor(parentScope?: Scope) {
			this._parentScope = parentScope;
		}

		/**
		 * 식별 가능한 개체를 등록합니다.
		 * @param object 등록할 객체.
		 */
		register(object: Identifiable) {
			let id = object.id;
			let uuid = object.uuid;
			if (id) {
				// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/7594
				// 동일한 앱이 새로 등록된 경우, 기존 앱 레지스트리에서 정리.
				let existing = this._objectsByID.get(id);
				if (existing) {
					this.unregister(existing);
				}

				this._objectsByID.set(id, object);
			}
			if (uuid) {
				this._objectsByUUID.set(uuid, object);
			}
		}

		/**
		 * 등록된 객체를 제거합니다.
		 * @param object 제거할 객체.
		 */
		unregister(object: Identifiable) {
			let id = object.id;
			let uuid = object.uuid;
			if (id) {
				this._objectsByID.delete(id);
			}
			if (uuid) {
				this._objectsByUUID.delete(uuid);
			}
		}

		/**
		 * ID로 객체를 찾습니다.
		 * @param id 찾을 객체의 ID.
		 */
		lookup(id: string): Identifiable {
			let result = this._objectsByID.get(id);
			if (result == null && this._parentScope != null) {
				result = this._parentScope.lookup(id);
			}
			return result;
		}

		/**
		 * UUID로 객체를 찾습니다.
		 * @param uuid 찾을 객체의 UUID.
		 */
		lookupByUUID(uuid: string): Identifiable {
			let result = this._objectsByUUID.get(uuid);
			if (result == null && this._parentScope != null) {
				result = this._parentScope.lookupByUUID(uuid);
			}
			return result;
		}

		_lookupDrillDownByUUID(uuid: string): Identifiable {
			let result = this._objectsByUUID.get(uuid);
			if (result == null) {
				CMap._valueStream(this._objectsByUUID)
					.exists(item => {
						if (isNestingSearchable(item)) {
							result = item._lookupDrillDownByUUID(uuid);
							if (result) {
								return true;
							}
						}
						return false;
					});
			}
			return result;
		}

		public lookupByPredication(predication: (element: Identifiable) => boolean): Identifiable[] {
			return CMap._valueStream(this._objectsByUUID)
				.filter(predication)
				.collect();
		}

		public _getEntriesByType<T>(type: abstract new (...args: any[]) => T): T[] {
			return CMap._valueStream(this._objectsByUUID)
				.filter(it => it instanceof type)
				.collect() as T[];
		}

		/**
		 * 컨트롤을 가져옵니다.
		 * @return 컨트롤.
		 */
		public getUIControls(): controls.UIControl[] {
			return this._getEntriesByType(controls.UIControl);
		}

		public getDataControls(): cpr.controls.Control[] {
			return CMap._valueStream(this._objectsByID)
				.filterByType(controls.Control)
				.filter(it => _isDataControl(it))
				.collect();
		}
	}
}