


namespace cpr.ufc {
	/**
	 * @private
	 */
	export interface PieceRenderer {
		/**
		 * 다른 피스렌더러를 포함하는지 여부를 얻습니다.
		 * @param other 
		 */
		_contains(other: PieceRenderer): boolean;

		/**
		 * 이 렌더러가 다른 렌더링 요소를 포함하는지 여부를 얻습니다.
		 * @param other 
		 */
		_hasPart(other: core.Drawable): boolean;

		/**
		 * 피스 렌더링을 실행합니다.
		 * @param renderer 피스 소유 컨트롤의 렌더러.
		 */
		_render(renderer: ControlRenderer): void;

		/**
		 * 피스 렌더러가 기각된 경우 콜백 됩니다.
		 */
		_clear?(): void;
	}

	/**
	 * @private
	 */
	export class HtmlAttrRenderer implements PieceRenderer {
		private _attrs: controls.internal.UserAttributes;

		constructor(attrs: controls.internal.UserAttributes) {
			this._attrs = attrs;
		}

		public _contains(other: ufc.PieceRenderer): boolean {
			return this === other || (other instanceof HtmlAttrRenderer && other._attrs === this._attrs);
		}

		public _hasPart(other: core.Drawable): boolean {
			return false;
		}

		public _render(renderer: ufc.ControlRenderer): void {
			renderer._applyHtmlAttr();
		}
	}

	/**
	 * @private
	 */
	export class StylerRenderer implements PieceRenderer {
		private _styler: controls.UIControlStyler;

		constructor(styler: controls.UIControlStyler) {
			this._styler = styler;
		}
		public _contains(other: ufc.PieceRenderer): boolean {
			return this === other || (other instanceof StylerRenderer && other._styler === this._styler);
		}
		public _hasPart(other: core.Drawable): boolean {
			return false;
		}
		public _render(renderer: ufc.ControlRenderer): void {
			renderer._applyStyler(this._styler.name, this._styler);
		}

	}

	/**
	 * @private
	 */
	export class CustomPieceRenderer implements PieceRenderer {
		private _func: (renderer: ufc.ControlRenderer) => void;

		constructor(func: (renderer: ufc.ControlRenderer) => void) {
			this._func = func;
		}
		public _contains(other: ufc.PieceRenderer): boolean {
			return this === other;
		}
		public _hasPart(other: core.Drawable): boolean {
			return false;
		}
		public _render(renderer: ufc.ControlRenderer): void {
			this._func(renderer);
		}

	}


}