/// <reference path="../../../utils/Logger.ts"/>

namespace cpr.core.internal.shim {
	let log = utils.Logger.forTopic("array")._createBindedLoggerFunction({
		updator: it => log = it
	});

	if (Array.prototype["find"] === undefined) {
		Object.defineProperty(Array.prototype, "find", {
			value: function (predicate: (e: any, index?: number, obj?: any[]) => boolean, context?: any) {
				if (context) {
					predicate = predicate.bind(context);
				}
				for (let idx = 0; idx < this.length; idx++) {
					let each = this[idx];
					if (predicate(each)) {
						return each;
					}
				}
				return undefined;
			},
			enumerable: false,
			configurable: false
		});
	}

	if (Array.prototype["findIndex"] === undefined) {
		Object.defineProperty(Array.prototype, "findIndex", {
			value: function (predicate: (e: any, index?: number, obj?: any[]) => boolean, context?: any) {
				if (context) {
					predicate = predicate.bind(context);
				}
				for (let idx = 0; idx < this.length; idx++) {
					let each = this[idx];
					if (predicate(each)) {
						return idx;
					}
				}
				return -1;
			},
			enumerable: false,
			configurable: false
		});
	}

	// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/5344
	function clearFoo(constructorFunction: Function) {
		// ESAPI가 싸지른 똥 치우기
		Object.getOwnPropertyNames(constructorFunction.prototype).forEach(prop => {
			let desc = Object.getOwnPropertyDescriptor(constructorFunction.prototype, prop);
			if (desc.configurable && desc.enumerable && desc.value instanceof Function) {
				Object.defineProperty(constructorFunction.prototype, prop, {
					value: desc.value,
					enumerable: false,
					configurable: false
				});
				log(`${constructorFunction.name}.${prop}을 이너머러블 하지 않도록 수정 하였습니다.`);
			};
		});
	}

	// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/5344
	clearFoo(Array);
	clearFoo(String);
	clearFoo(Object);
}
