/// <reference path="./DOMEventWrapper.ts" />


namespace cpr.events {
	/**
	 * value 변경에 대한 이벤트 유형
	 */
	export class InputFilterEventType {
		/**
		 * 수정 이벤트.
		 */
		public static readonly INPUTFILTER: string = "input-filter";

	}

	/**
	 * value 변경 이벤트에 대한 옵션.
	 */
	export interface CInputFilterEventOptions extends CEventOption {

		/**
		 * 입력된 텍스트
		 */
		text?: string;

	}

	/**
	 * 인풋 박스의 텍스트가 변경될때 발생하는 이벤트.
	 */
	export class CInputFilterEvent extends CUIEvent {

		/**
		 * 입력된 텍스트를 반환합니다.
		 * @return 입력된 텍스트 값.
		 */
		get text(): string {
			return this._getOption("text");
		}

	}

}