/// <reference path="AbstractMenu.ts"/>

namespace cpr.controls.menu {

	/**
	 * @private
	 */
	export interface MenuInfo {
		viewRange: { start: number, end: number };
		minContentWidth: number;
		width?: number;
		scrollTop?: number;
	}

	/**
	 * @private
	 */
	export interface SubMenuInfo {
		parentItem?: MenuItem;
		viewRange?: { start: number, end: number };
		minContentWidth?: number;
		verticalPosition?: "top" | "bottom";
		scrollTop?: number;
	}
	// TODO 메뉴에서 하위 메뉴 참조 하고 하위 메뉴가 하위 메뉴를 참조하는 방식으로 개선하는 방향 필요.(장점 각 객체에서 호버 정보 menuinfo를 관리하기 쉬움)
	/**
	 * @private
	 */
	export abstract class AbstractVerticalMenu extends AbstractMenu {
		private _mouseLeaveTimer: utils.Timer;
		private _beforeMouseoverItem: MenuItem = null;
		private _touchMenuOwnerItem: MenuItem;
		private _touchMoved: boolean;
		protected _touchRoller: internal.TouchRoller = internal.newTouchRoller();

		private _menuInfo: MenuInfo;
		private _touchEventDispatcher = (e: any) => {
			switch (e.type) {
				case "touchmove":
					this._ontouchmove(e);
					break;
				case "touchend":
					this._ontouchend(e);
					break;
			}
		}

		constructor(uicontrol: MenuOwner, ns: string, binder: provider.MenuDataBinder, stylerName: { [name: string]: string, list: string, item: string }) {
			super(uicontrol, ns, binder, stylerName);
			this._mouseLeaveTimer = utils.Timer.create("menu-mouseleave");
		}

		public init() {
			super.init();
			this._touchMenuOwnerItem = null;
			this._removeMenuInfo();
			this._endTouchEvent();
			this.cancelTimeoutEvent(MenuTimeoutEventType.mouseleave);
		}

		protected _getButtonHeight() {
			return 16;
		}

		protected _getMenuListNodeName() {
			return `${this.getRootNodeName()}-"first-menu"`;
		}

		protected _getMenuListNode() {
			return this._getRenderer().getNamedNode(this._getMenuListNodeName());
		}

		protected _createArrowImage(item: MenuItem, useWrapper: boolean = false): ufc.ElementShape {
			let hasChild = item._hasChild();
			let listArrowImage = this._getListArrowImage();
			let shape: ufc.ElementShape = {
				tag: "div",
				classNames: [this._getQClass("arrow")],
				attr: { "aria-hidden": "true" },
				style: {
					display: "table-cell",
					verticalAlign: "middle"
				},
				children: []
			}
			let arrowShape: ufc.ElementShape = shape;
			if (useWrapper) {
				shape.classNames = [this._getQClass("arrow-wrapper")];
				arrowShape = {
					tag: "div",
					classNames: [this._getQClass("arrow")],
					style: {}
				}
				shape.children.push(arrowShape);
			}
			if (listArrowImage != "" && hasChild) {
				arrowShape.style['background-image'] = _quoteAsCSSURL(listArrowImage);
			}
			return shape;
		}

		protected _createIcon(item: MenuItem, useWrapper: boolean = false) {
			let shape: ufc.ElementShape = {
				tag: "div",
				attr: { "aria-hidden": "true" },
				classNames: [this._getQClass("icon")],
				style: {
					display: "table-cell",
					verticalAlign: "middle"
				},
				children: []
			}

			let iconShape: ufc.ElementShape = shape;
			if (useWrapper) {
				shape.classNames = [this._getQClass("icon-wrapper")];
				iconShape = {
					tag: "div",
					style: {},
					classNames: [this._getQClass("icon")],
					children: ["&nbsp;"]
				}
				shape.children.push(iconShape);
			}
			if (item.icon != null && item.icon != "") {
				iconShape.style['background-image'] = _quoteAsCSSURL(item.icon);
			}
			return shape;
		}

		protected _createText(text: ufc.StyledString | string): ufc.ElementShape {
			let textShape: cpr.ufc.ElementShape = {
				tag: "div",
				attr: {
					"aria-hidden": "true" // menuitem 하위에 텍스트 노드가 있으면 서브메뉴로 인식 하기 때문에 숨김 처리
				},
				classNames: [ufc.Classes.TEXT],
				style: {
					display: "table-cell",
					verticalAlign: "middle"
				},
				children: ufc.StyledString._asShape(text)
			};
			return textShape;
		}

		protected _createAccessKey(item: MenuItem, useWrapper: boolean = false): ufc.ElementShape {
			let shape: ufc.ElementShape = {
				tag: "div",
				classNames: [this._getQClass("accesskey"), ufc.Classes.TEXT],
				attr: { "aria-hidden": "true" },
				style: {
					display: "table-cell",
					verticalAlign: "middle"
				},
				children: []
			};
			let accessKeyShape: ufc.ElementShape = shape;
			if (useWrapper) {
				shape.classNames = [this._getQClass("accesskey-wrapper")];
				accessKeyShape = {
					tag: "div",
					style: {},
					classNames: [this._getQClass("accesskey"), ufc.Classes.TEXT],
					children: []
				}
				shape.children.push(accessKeyShape);
			}
			accessKeyShape.children.push(item.accessKey ? "(" + item.accessKey + ")" : "");
			return shape;
		}

		protected _createSubMenu(parentItem: MenuItem, selectedValues: string[]): cpr.ufc.ElementShape {
			let className: string[] = ["cl-sub", ufc.Classes.UNSELECTABLE];
			let range = this._getSubMenuItemRange(parentItem);
			let subMenuIdx = this._convertIndexByParentItem(parentItem);
			let subMenuItems = parentItem.children as MenuItem[];
			let itemCount = subMenuItems.length;
			let rangeSize = range.end - range.start;
			subMenuItems = subMenuItems.slice(range.start, range.end);
			let visibleButton: boolean = itemCount != rangeSize;

			let upScrollBtn: ufc.ElementShape = {
				tag: "div",
				classNames: ["cl-arrow-up"],
				style: {
					display: visibleButton ? "block" : "none",
					height: this._getButtonHeight() + "px"
				}
			}
			let isFirst = range.start == 0;
			if (visibleButton && isFirst) {
				upScrollBtn.classNames.push(ufc.Classes.DISABLED);
			}

			let downScrollBtn: ufc.ElementShape = {
				tag: "div",
				classNames: ["cl-arrow-down"],
				style: {
					display: visibleButton ? "block" : "none",
					height: this._getButtonHeight() + "px"
				}
			}

			let isLast = range.end == itemCount;
			if (visibleButton && isLast) {
				downScrollBtn.classNames.push(ufc.Classes.DISABLED);
			}

			let children = this._createSubItems(subMenuItems, selectedValues);
			children.splice(0, 0, upScrollBtn);
			children.push(downScrollBtn);
			let subMenuShape: cpr.ufc.ElementShape = {
				tag: "div",
				classNames: className,
				attr: {
					role: "menu",
					"data-role": "menu",
					"aria-label": cpr.ufc.ShapeUtil._getValidAriaLabelAttr(ufc.StyledString._asString(this._getDataBinder()._computeItemDisplayLabel(parentItem))),
					"data-parent": parentItem.value
				},
				styler: this._getStylerName("list"),
				style: {
					position: "absolute",
					top: "-1px",
					left: "0px",
					right: "auto",
					"margin-left": "100%",
					"z-index": "1",
					overflow: "visible",
					transform: "none"
				},
				children: children,
				events: {},
				nodename: this._getSubMenuNodeName(this._convertIndexByParentItem(parentItem))
			}

			let width = this._getSubMenuMinWidth(subMenuIdx);
			if (width) {
				subMenuShape.style["min-width"] = width + "px";
			}
			ufc.ShapeUtil.addEventHandler(subMenuShape, "touchstart", (e: events.CTouchEvent) => { this._ontouchstart(e) }, true);
			ufc.ShapeUtil.addEventHandler(subMenuShape, "wheel", (e: events.CWheelEvent) => { this._onSubMenuMouseWheel(e) }, true);

			if (this._isHoverTrigger()) {
				ufc.ShapeUtil.addEventHandler(subMenuShape, "mouseover", (e: MouseEvent) => { this._dispatchHoverRelativeEvent(e) }, true);
				ufc.ShapeUtil.addEventHandler(subMenuShape, "mouseleave", (e: MouseEvent) => { this._dispatchHoverRelativeEvent(e) }, true);
			}
			if (this._getDirection() == MenuDirectionType.rtl) {
				subMenuShape.style['left'] = "auto";
				subMenuShape.style['right'] = "0px";
				subMenuShape.style['margin-right'] = "100%";
				subMenuShape.style['margin-left'] = "auto";
			}

			return subMenuShape;
		}

		protected abstract _createSubItems(children: MenuItem[], selectedValues: string[]): cpr.ufc.ElementShape[];
		/**
		 * 메뉴의 위치를 계산하고 설정합니다.
		 * 서브메뉴는 _updateSubMenuBounds를 참고하세요.
		 */
		protected abstract _updateMenuBounds(): void;

		protected _updateBounds() {
			this._initViewportRect();
			this._updateMenuBounds();
			this._updateSubMenuBounds();
			this._clearViewportRect();
		}

		protected _calculateSpaceForSubmenuInViewport(submenuNode: HTMLElement, data: { rowHeight: number, submenuRect: geometry.Rectangle }) {
			return _getComputedSpaceInsets(submenuNode, {
				customVerticalMeasurePosition: (type, rect, viewportRect) => {
					if (type == "top") {
						return (rect.top + data.rowHeight) - viewportRect.top;
					} else if (type == "bottom") {
						return viewportRect.bottom - rect.top;
					}
					return 0;
				}
			});
		}
		protected _getSubmenuScrollUpElement(submenuNode: HTMLElement) {
			return submenuNode.querySelector(".cl-menu-list > .cl-arrow-up") as HTMLElement;
		}
		protected _getSubmenuScrollDownElement(submenuNode: HTMLElement) {
			return submenuNode.querySelector(".cl-menu-list > .cl-arrow-down") as HTMLElement;
		}

		/**
		 * 서브 메뉴의 위치를 계산하고 설정정합니다.
		 */
		protected _updateSubMenuBounds() {
			let subMenuNodes = this._getAllSubmenuItemNodes();

			subMenuNodes.forEach((submenuNode: HTMLElement, idx: number) => {
				let parentItemElement = ufc._traverseFromElement(submenuNode)._closest(".cl-hover", this._getMenuListNode())?._getElement();
				let submenuRect = _getOffsetRectFromViewport(submenuNode);
				let submenuComputedStyle = getComputedStyle(submenuNode);
				let paddingTop = _parseFloat(submenuComputedStyle.paddingTop);
				let paddingBottom = _parseFloat(submenuComputedStyle.paddingBottom);
				let marginTop = _parseFloat(submenuComputedStyle.marginTop);
				let marginBottom = _parseFloat(submenuComputedStyle.marginBottom);
				let buttonUpElement = this._getSubmenuScrollUpElement(submenuNode);
				let buttonDownElement = this._getSubmenuScrollDownElement(submenuNode);
				let buttonUpHeight: number = !!buttonUpElement ? _parseFloat(buttonUpElement.style.height) : 0;
				let buttonDownHeight: number = !!buttonDownElement ? _parseFloat(buttonDownElement.style.height) : 0;
				let buttonTotalSize = buttonUpHeight + buttonDownHeight;
				let parentItemHeight = parentItemElement?.offsetHeight ?? 0;
				let borderTopWidth = _parseFloat(submenuComputedStyle.borderTopWidth);
				let borderBottomWidth = _parseFloat(submenuComputedStyle.borderBottomWidth);
				// 메뉴와 내비게이션바메뉴에서 차이점이 발생하여 분리
				let rootSpace = this._calculateSpaceForSubmenuInViewport(submenuNode, { rowHeight: parentItemHeight, submenuRect: submenuRect });
				let verticalPosition = this._getSubMenuInfo(idx)?.verticalPosition ?? "bottom";
				// 서브메뉴 인라인 기본값 
				let constraint: { top?: number } = {
					top: 0
				};

				let submenuExpandedRect = submenuRect.getExpanded(new geometry.Insets(Math.max(marginTop, 0), 0, Math.max(marginBottom, 0), 0));
				let currentHeight = submenuRect.height;
				let needUpdateMenuTop = false;
				if (submenuExpandedRect.height > rootSpace.bottom || verticalPosition == "top") {
					if (rootSpace.top > rootSpace.bottom) {
						if (submenuExpandedRect.height > rootSpace.top) { // 메뉴 스크롤이 필요한 경우
							needUpdateMenuTop = true;
							currentHeight = rootSpace.top - (marginTop + marginBottom + borderTopWidth + borderBottomWidth + paddingTop + paddingBottom + buttonTotalSize);
						} else {
							constraint.top = (constraint.top + parentItemHeight + borderBottomWidth) - (currentHeight - paddingBottom);
						}
						verticalPosition = "top";
					} else { // 메뉴 스크롤이 필요한 경우
						constraint.top = constraint.top - (borderTopWidth + paddingTop);
						currentHeight = rootSpace.bottom - (marginTop + marginBottom + borderTopWidth + borderBottomWidth + paddingTop + paddingBottom + buttonTotalSize);
					}
					let itemMaxCount = this._computeVisibleMenuItemCount(this._getVisibleItemElements(submenuNode), currentHeight);
					let parentItem = this._getItemByMenuElement(submenuNode);
					let range = this._getSubMenuItemRange(parentItem, itemMaxCount);
					this._updateSubMenuInfo(idx, {
						parentItem: parentItem,
						viewRange: range,
						minContentWidth: this._getComputedItemWidth(submenuNode, this._getMenuItemQuerySelector()),
						verticalPosition: verticalPosition
					});
					this._updateSubMenuContent(idx, submenuNode);
					// 렌더링된 상태에서 스크롤 버튼의 표시 여부를 알 수 있다
					if (needUpdateMenuTop) {
						let updatedMenuHeight = _getUnscaledClientValue(submenuNode.getBoundingClientRect().height);
						constraint.top = (parentItemHeight + borderBottomWidth) - (updatedMenuHeight - paddingBottom);
					}
				} else {
					constraint.top = constraint.top - (borderTopWidth + paddingTop);
				}

				let style = _.mapObject(constraint, (val: number | null, key: string) => {
					if (val == null) {
						return "auto";
					}
					return val + "px";
				})
				_assign(style, this._checkSubMenuHPosition(submenuNode, this._viewportRect, submenuRect));
				this._getRenderer().updateStyle(this._getSubMenuNodeName(idx), style, true);
			}); //forEach
		}

		protected _checkSubMenuHPosition(submenuNode: HTMLElement, viewportRect: geometry.Rectangle, submenuRect: geometry.Rectangle) {
			let style = {};
			let computedStyle = getComputedStyle(submenuNode);
			let direction = this._getDirection();
			let paddingRight = parseInt(computedStyle.paddingRight);
			let paddingLeft = parseInt(computedStyle.paddingLeft)
			if (direction == "ltr" && paddingRight > 0) {
				style["left"] = paddingRight + "px";
				submenuRect.left += paddingRight;
			} else if (direction == "rtl" && paddingLeft > 0) {
				style["right"] = paddingLeft + "px";
				submenuRect.left -= paddingLeft;
			}
			if (submenuRect.left + submenuRect.width > viewportRect.width) {
				let domTraverser = ufc._traverseFromElement(submenuNode);
				let menuitemnode = domTraverser._parent(this._getMenuItemQuerySelector());
				let menuitemRect = _getUnscaledClientRect(menuitemnode._getElement());
				if ((submenuRect.left - menuitemRect.width) - submenuRect.width > 0) {
					style["left"] = "auto";
					style["right"] = paddingLeft + "px";
					style["margin-right"] = "100%";
					style["margin-left"] = "auto"
				} else {
					style["left"] = paddingRight + "px";
					style["right"] = "auto";
					style["margin-left"] = "100%";
					style["margin-right"] = "auto";
				}
			} else if (submenuRect.left < viewportRect.left) {
				style["left"] = paddingLeft + "px";
				style["right"] = "auto";
				style["margin-left"] = "100%";
				style["margin-right"] = "auto";
			}
			return style;
		}

		protected _updateSubMenuContent(idx: number, menuNode: HTMLElement, style: {} = {}) {
			let subMenuInfo = this._getSubMenuInfo(idx);
			if (subMenuInfo) {
				_assign(style, { "min-width": subMenuInfo.minContentWidth ? subMenuInfo.minContentWidth + "px" : "0px" });
			}

			let parentValue = menuNode.getAttribute("data-parent");
			let parentItem: MenuItem = this._getDataBinder().findTreeItem(parentValue, this.getItems()) as MenuItem;
			let selectedValues = this._getSelectedValues();

			let subMenuShape = this._createSubMenu(parentItem, selectedValues);
			_assign(subMenuShape.style, style);
			this._getRenderer().replace(this._getSubMenuNodeName(idx), subMenuShape);
		}

		protected _getVisibleItemElements(menuListNode: HTMLElement): HTMLElement[] {
			return _toArray(menuListNode.children).filter((node) => { return node.classList.contains("cl-menu-item") }) as HTMLElement[];
		}

		protected _computeVisibleMenuItemCount(menuItemElements: HTMLElement[], height: number): number {
			let allRowsHeight = 0;
			let itemCount = menuItemElements.length;
			menuItemElements.forEach((menuItemElement: HTMLElement) => {
				allRowsHeight += this._getItemHeight(menuItemElement);
				if (allRowsHeight > height) {
					itemCount -= 1;
				}
			})

			return itemCount;
		}

		public _setFocusedItem(item: MenuItem) {
			super._setFocusedItem(item);
			if (item) {
				// 서브 메뉴 정보 삭제
				let index = this._convertIndexByParentItem(item);
				let submenuInfo = this._getSubMenuInfo(index);
				if (submenuInfo && submenuInfo.parentItem.value != item.value) {
					delete this._subMenuInfos[index];
				}
			}
		}

		protected override _setHoveredItem(item: MenuItem, options?: { updateScroll?: boolean; expand?: boolean; }): void {
			super._setHoveredItem(item, options);
			if (item) {
				// 서브 메뉴 정보 삭제
				let index = this._convertIndexByParentItem(item);
				let submenuInfo = this._getSubMenuInfo(index);
				if (submenuInfo && submenuInfo.parentItem.value != item.value) {
					this._removeSubMenuInfo(index);
				}
			}
		}

		private _getSubMenuItemRange(parentItem: MenuItem, rangeSize?: number): { start: number, end: number } {
			let index = this._convertIndexByParentItem(parentItem);
			let subMenuInfo = this._subMenuInfos[index];
			if (subMenuInfo) {
				return { start: subMenuInfo.viewRange.start, end: rangeSize == null ? subMenuInfo.viewRange.end : subMenuInfo.viewRange.start + rangeSize };
			}
			return { start: 0, end: rangeSize ?? parentItem.children.length };
		}

		private _getSubMenuInfo(idx: number): SubMenuInfo {
			return this._subMenuInfos[idx];
		}

		private _removeSubMenuInfo(idx: number, removeTail: boolean = false) {
			if (this._subMenuInfos[idx]) {
				if (removeTail) {
					this._subMenuInfos.splice(idx, Number.MAX_VALUE);
				} else {
					delete this._subMenuInfos[idx];
				}
			}
		}
		protected _getSubMenuMinWidth(idx: number) {
			if (this._subMenuInfos[idx]) {
				return this._subMenuInfos[idx].minContentWidth;
			}
			return null;
		}

		private _updateSubMenuInfo(idx: number, info: SubMenuInfo) {
			let subMenuInfo = this._subMenuInfos[idx];
			if (subMenuInfo) {
				_assign(subMenuInfo, info);
			} else {
				this._subMenuInfos[idx] = _mergeObject(info, { scrollTop: 0 });
			}
		}

		protected _removeMenuInfo() {
			if (!this._menuInfo) {
				return;
			}
			this._menuInfo = null;
			this._getUIControl().redraw();
		}

		protected _getMenuItemRange(rangeSize?: number) {

			if (this._menuInfo) {
				return this._menuInfo.viewRange;
			} else {
				return { start: 0, end: rangeSize == null ? this.getItems().length : rangeSize }
			}
		}

		protected _getMenuMinWidth() {
			if (this._menuInfo) {
				return this._menuInfo.minContentWidth;
			}
			return null;
		}

		protected _getMenuInfo(): MenuInfo {
			return this._menuInfo;
		}

		protected _updateMenuInfo(info: MenuInfo) {
			if (this._menuInfo) {
				_assign(this._menuInfo, info);
			} else {
				this._menuInfo = _mergeObject(info, { scrollTop: 0 });
			}
		}

		protected _updateScrollByHover(currentHover: MenuItem) {
			if (currentHover == null) {
				return;
			}
			let parentItem = this._getParentItem(currentHover);
			let children = this._getGroupItemsByItem(currentHover);
			let findIdx = _.findIndex(children, { value: currentHover.value });
			this._reveal(parentItem, findIdx);
		}

		private _reveal(menuOwnerItem: MenuItem, itemOffset: number) {
			let viewRange: { start: number, end: number };
			if (!menuOwnerItem) {
				viewRange = this._getMenuInfo()?.viewRange;
			} else {
				let submenuIndex = this._convertIndexByParentItem(menuOwnerItem);
				viewRange = this._getSubMenuInfo(submenuIndex)?.viewRange;
			}
			if (!viewRange) {
				return;
			}
			if ((viewRange.start <= itemOffset && viewRange.end > itemOffset) == false) {
				let rangeSize = viewRange.end - viewRange.start;
				let scrollTop: number;
				if (viewRange.end < itemOffset + 1) {
					scrollTop = ((itemOffset + 1) - rangeSize) * this._getRowHeight();
				} else {
					scrollTop = itemOffset * this._getRowHeight();
				}
				this._setScrollTop(menuOwnerItem, scrollTop);
				this._getUIControl().redraw();
			}
		}

		private _getHoveredItemByDepth(depth: number) {
			if (!this.getHoveredItem()) {
				return null;
			}
			let parentItem = this.getHoveredItem();
			while (parentItem != null) {
				if (depth == parentItem.depth) {
					return parentItem;
				}
				parentItem = parentItem.parentItem;
			}
			return null;
		}

		/**
		 * 메뉴 휠
		 * @param e 
		 */
		protected _onSubMenuMouseWheel(e: events.CWheelEvent) {
			if (e._getMod1Key() === true) { // 확대/축소
				return;
			}

			let eventDelta: { x: number, y: number } = internal.ScrollbarUtil._getScrollPaneWheelDelta(e);
			if (eventDelta == null) {
				return;
			}
			let delta = this._getRowHeight();
			let offset: number = eventDelta.y == 0 ? 0 : (eventDelta.y > 0 ? 1 : -1);
			let deltaY: number = delta * offset;
			if (deltaY != 0) {
				this._setScrollTopOffset(this._getMenuOwnerItem(e.currentTarget as HTMLElement), deltaY);
			}
			e.preventDefault();
			e.stopPropagation();
		}

		/**
		 * 메뉴 휠
		 * @param e 
		 */
		protected _onMenuMouseWheel(e: events.CWheelEvent) {
			if (e._getMod1Key() === true) { // 확대/축소
				return;
			}
			let eventDelta: { x: number, y: number } = internal.ScrollbarUtil._getScrollPaneWheelDelta(e);
			if (eventDelta == null) {
				return;
			}
			let delta = this._getRowHeight();
			let offset: number = eventDelta.y == 0 ? 0 : (eventDelta.y > 0 ? 1 : -1);
			let deltaY: number = delta * offset;
			if (deltaY != 0) {
				this._setScrollTopOffset(this._getMenuOwnerItem(e.currentTarget as HTMLElement), deltaY);
			}
			e.preventDefault();
			e.stopPropagation();
		}

		/**
		 * 스크롤 버튼 클릭
		 * @param e 
		 */
		private _onClickScrollBtn(menuNode: HTMLElement, moveDown: boolean) {
			let delta = this._getRowHeight();
			if (!moveDown) {
				delta *= -1;
			}
			this._setScrollTopOffset(this._getMenuOwnerItem(menuNode), delta)
		}

		protected _closestMenuElement(childElement: HTMLElement, rootElement: HTMLElement) {
			let domTraverser = ufc._traverseFromElement(childElement)._closest("[data-role='menu']", rootElement);
			return domTraverser ? domTraverser._getElement() : null;
		}

		/**
		 * 아이템 select와 item-click 이벤트를 전파한다
		 * @param e 
		 */
		protected _onClick(e: MouseEvent | TouchEvent): void {
			let rootElement: HTMLElement = <HTMLElement>e.currentTarget;
			let eventElement: HTMLElement = <HTMLElement>e.target;
			if (eventElement.classList.contains(this._getQClass("list"))) {
				return;
			}
			if (eventElement.classList.contains("cl-arrow-down") || eventElement.classList.contains("cl-arrow-up")) {
				let menuNode = this._closestMenuElement(eventElement, rootElement);
				if (menuNode) {
					let moveDown = eventElement.classList.contains("cl-arrow-down");
					this._onClickScrollBtn(menuNode, moveDown);
				}
				return;
			}

			let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(eventElement)._closest(this._getMenuItemQuerySelector(), rootElement);
			if (domTraverser == null) {
				return;
			}

			let item: MenuItem = this._getItemByElement(domTraverser._getElement());
			if (item == null) {
				throw new cpr.exceptions.CError("The item does not exist.");
			}
			if (!this._getDataBinder().getItemEnable(item)) {
				return;
			}

			if (e.type == "touchend") {
				this._onClickInMobile(item, e as TouchEvent);
			} else {
				this._onClickInPC(item, e as MouseEvent);
			}
		}

		protected _onClickInPC(item: MenuItem, e: MouseEvent) {
			let isSelected = false;
			let isClickTrigger = this._isHoverTrigger() == false;
			let isSelectableChildItem = this._getSelectionTargetType() == MenuSelectionTargetType.leaf;
			if ((isClickTrigger || isSelectableChildItem) && item._hasChild()) {
				if (this._isHoveredItem(item) == false) {
					this.setHoveredItem(item);
				}
			} else {
				isSelected = this._onItemSelect(item, e);
			}
			let itemClickEvent = new cpr.events.CItemEvent(events.ItemEventType.ITEMCLICK, {
				item: item
			});
			itemClickEvent.nativeEvent = e;
			this.dispatchEvent(events.ItemEventType.ITEMCLICK, itemClickEvent);
			if (this.disposed) {
				return;
			}
			if (isSelected) {
				this.init();
				let itemSelectedEvent = new cpr.events.CItemEvent("--internal-item-selected", { item: item });
				itemSelectedEvent.nativeEvent = e;
				this.dispatchEvent("--internal-item-selected", itemSelectedEvent);
			}
		}

		protected _onClickInMobile(item: MenuItem, e: TouchEvent) {

			let isHoveredItem = this._isHoveredItem(item);
			if (item._hasChild() == false || (isHoveredItem && this._getSelectionTargetType() == MenuSelectionTargetType.all)) {
				if (isHoveredItem == false) {
					this.setHoveredItem(item);
				}
				let isSelected = this._onItemSelect(item, e);
				let itemClickEvent = new cpr.events.CItemEvent(events.ItemEventType.ITEMCLICK, {
					item: item
				});
				itemClickEvent.nativeEvent = e;
				this.dispatchEvent(events.ItemEventType.ITEMCLICK, itemClickEvent);
				if (this.disposed) {
					return;
				}
				if (isSelected) {
					this.init();
					let itemSelectedEvent = new cpr.events.CItemEvent("--internal-item-selected", { item: item });
					itemSelectedEvent.nativeEvent = e;
					this.dispatchEvent("--internal-item-selected", itemSelectedEvent);
				}
			} else {
				this.setHoveredItem(item);
				//서브 메뉴 확장하는 터치가 클릭으로 해야 할지 검토 필요.
			}
		}

		protected _getScrollBtn(element: HTMLElement, direction: string) {
			let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(element)._find("cl-arrow-" + direction);
			return domTraverser._getElement();
		}

		/**
		 * 호버된 아이템의 엘리먼트를 모두 반환한다.
		 */
		protected _getAllSubmenuItemNodes(): HTMLElement[] {
			return this._getHoveredItems().map((each: MenuItem, idx: number) => {
				return this._getSubMenuNodeByIndex(idx);
			}).filter(it => it);
		}

		/**
		 * 메뉴를 벗어날때 동작을 체크한다
		 * @param e 
		 */
		private _onMenuMouseLeave(e: MouseEvent) {
			// e.stopPropagation();
			this.cancelTimeoutEvent(MenuTimeoutEventType.mouseleave);
			this._mouseLeaveTimer.init(() => {
				this._mouseLeaveImmediately(e);
			}).schedule(300);

		}

		/**
		 * 아이템에 마우스 호버 동작을 체크한다
		 * expanderTrigger=[hover,click]에 item-mouseover 이벤트를 발생시킵니다.
		 * @param e 
		 */
		private _onMenuMouseOver(e: MouseEvent) {
			// e.stopPropagation();

			this.cancelTimeoutEvent(MenuTimeoutEventType.mouseleave);

			let rootElement = <HTMLElement>e.currentTarget;
			let eventElement = <HTMLElement>e.target;
			let domTravser = ufc._traverseFromElement(eventElement)._closest(this._getMenuItemQuerySelector(), rootElement);
			if (!domTravser) {
				return;
			}

			let item: MenuItem = this._getItemByElement(domTravser._getElement());
			if (item == null) {
				throw new cpr.exceptions.CError("The item does not exist.")
			}
			if (!this._dispatchItemMouseover(item, e) || this._isHoverTrigger() == false) {
				return;
			}
			if (this._isHoveredItem(item) || this._getDataBinder().getItemEnable(item) == false) {
				return;
			}

			this.setHoveredItem(item);
		}

		private _onMenuMouseOut(e: MouseEvent) {
			let rootElement: HTMLElement = <HTMLElement>e.currentTarget;
			let eventElement: HTMLElement = <HTMLElement>e.target;

			let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(eventElement)._closest("[data-role='menuitem']", rootElement);
			if (domTraverser == null) {
				return;
			}
			let relatedDomTraverser = ufc._traverseFromElement(e.relatedTarget as HTMLElement)._closest("[data-role='menuitem']", rootElement);
			if (relatedDomTraverser == null || (relatedDomTraverser != null && domTraverser._getElement() != relatedDomTraverser._getElement())) {
				this._beforeMouseoverItem = null;
			}
		}

		private _onMenuMouseEnter(e: MouseEvent) {
			if (this._beforeMouseoverItem) {
				this._beforeMouseoverItem = null;
			}
			this.dispatchEvent("menu-mouseenter", e);
		}

		private _dispatchItemMouseover(item: MenuItem, e: MouseEvent): boolean {

			if (this._beforeMouseoverItem?._equalsValue(item)) {
				return true;
			}
			if (this._getUIControl()._hasCustomEventListener("item-mouseover") == false) {
				return true;
			}
			this._beforeMouseoverItem = item;
			let itemMouseOverEvent = new events.CItemEvent("item-mouseover", { item: item });
			itemMouseOverEvent.nativeEvent = e;
			return this.dispatchEvent("item-mouseover", itemMouseOverEvent);
		}

		protected _dispatchHoverRelativeEvent(e: MouseEvent) {
			switch (e.type) {
				case "mouseover":
					this._onMenuMouseOver(e);
					break;
				case "mouseout":
					this._onMenuMouseOut(e);
					break;
				case "mouseenter":
					this._onMenuMouseEnter(e);
					break;
				case "mouseleave":
					this._onMenuMouseLeave(e);
					break;
			}
		}

		private _mouseLeaveImmediately(e?: MouseEvent) {
			this._beforeMouseoverItem = null;
			this._clearHoveredItem();
			this.dispatchEvent("menu-mouseleave", e);
		}

		/**
		 * timeout event를 취소합니다.["menu-mouseleave"]
		 * @param name 
		 */
		public cancelTimeoutEvent(name: MenuTimeoutEventType) {
			if (name == MenuTimeoutEventType.mouseleave) {
				this._mouseLeaveTimer.cancel();
			}
		}

		/**
		 * timeout event를 취소하고 즉시 실행합니다.["menu-mouseleave"]
		 * @param name 
		 */
		public executeTimeoutEvent(name: MenuTimeoutEventType) {
			if (name == MenuTimeoutEventType.mouseleave) {
				this._mouseLeaveTimer.scheduleRun();
			}
		}

		private _startTouchEvent() {
			cpr.events.BodyEventTarget.INSTANCE._addCaptureEventListener("touchmove", this._touchEventDispatcher);
			cpr.events.BodyEventTarget.INSTANCE.addEventListener("touchend", this._touchEventDispatcher);
		}

		private _endTouchEvent() {
			cpr.events.BodyEventTarget.INSTANCE._removeCaptureEventListener("touchmove", this._touchEventDispatcher);
			cpr.events.BodyEventTarget.INSTANCE.removeEventListener("touchend", this._touchEventDispatcher);
		}

		private _getViewportHeight(menuListNode: HTMLElement) {
			let itemElements = this._getVisibleItemElements(menuListNode);
			return itemElements.length * this._getRowHeight();
		}

		private _getMaxScrollTop(menuOwnerItem: MenuItem) {
			let count: number;
			if (!menuOwnerItem) {
				let itemElements = this._getVisibleItemElements(this._getMenuListNode());
				count = this.getItems().length - itemElements.length;
			} else {
				let itemElements = this._getVisibleItemElements(this._getSubMenuNodeByIndex(this._convertIndexByParentItem(menuOwnerItem)));
				count = menuOwnerItem.children.length - itemElements.length;
			}
			return count * this._getRowHeight();
		}

		private _getMenuOwnerItem(menuListNode: HTMLElement) {
			let parentValue = menuListNode.getAttribute("data-parent");
			if (!parentValue) {
				return null;
			}
			return this._getDataBinder().getItemByValue(parentValue);
		}

		private _getScrollTop(menuOwnerItem: MenuItem): number {
			if (!menuOwnerItem) {
				return this._getMenuInfo()?.scrollTop ?? 0;
			} else {
				let index = this._convertIndexByParentItem(menuOwnerItem);
				return this._getSubMenuInfo(index)?.scrollTop ?? 0;
			}
		}

		private _getItemHeight(itemElement: HTMLElement) {
			let marginTop = _parseFloat(getComputedStyle(itemElement).marginTop);
			return _getUnscaledClientValue(itemElement.getBoundingClientRect().height) + marginTop;
		}

		/**
		 * 스크롤 하기 위한 가상 높이
		 * @returns 
		 */
		private _getRowHeight() {
			return 30;
		}

		private _setScrollTopOffset(menuOwnerItem: MenuItem, offset: number) {
			let scrollTop = this._getScrollTop(menuOwnerItem);
			scrollTop += offset;
			return this._setScrollTop(menuOwnerItem, scrollTop);
		}

		private _setScrollTop(menuOwnerItem: MenuItem, scrollTop: number): boolean {
			let maxScrollTop = this._getMaxScrollTop(menuOwnerItem);
			if (scrollTop < 0) {
				scrollTop = 0;
			} else if (maxScrollTop < scrollTop) {
				scrollTop = maxScrollTop;
			}
			if (this._getScrollTop(menuOwnerItem) == scrollTop) {
				return false;
			}

			let start = Math.floor(scrollTop / this._getRowHeight());
			let index: number, menuListNode: HTMLElement;
			let menuInfo: { viewRange?: { start: number, end: number }, scrollTop?: number };
			if (!menuOwnerItem) {
				menuInfo = this._getMenuInfo();
				menuListNode = this._getMenuListNode();
			} else {
				index = this._convertIndexByParentItem(menuOwnerItem);
				menuInfo = this._getSubMenuInfo(index);
				menuListNode = this._getSubMenuNodeByIndex(index);
			}

			if (!menuInfo) {
				return true;
			}

			let viewRange: { start: number, end: number } = menuInfo.viewRange;
			menuInfo.scrollTop = scrollTop;

			if (start == viewRange.start) {
				return true;
			}

			let itemCount = this._getViewportHeight(menuListNode) / this._getRowHeight();
			let newViewRange = { start: start, end: start + itemCount };

			if (menuOwnerItem) {
				menuInfo.viewRange = newViewRange;
				let hoverItem = this.getHoveredItem();
				if (hoverItem.depth > menuOwnerItem.depth) {
					let hoveredItem = this._getHoveredItemByDepth(menuOwnerItem.depth);
					this.setHoveredItem(hoveredItem);
				}
			} else {
				menuInfo.viewRange = newViewRange;
				this._clearHoveredItem();
				this._removeAllSubMenuInfo();
			}

			this._getUIControl().redraw();
			return true;
		}

		protected _ontouchstart(e: events.CTouchEvent) {
			let touch = e.touches.length == 1 ? e.touches[0] : null;
			if (touch == null) {
				return;
			}
			this._touchMenuOwnerItem = this._getMenuOwnerItem(e.currentTarget as HTMLElement);
			this._touchMoved = false;
			this._startTouchEvent();
			e.stopPropagation();
			this._touchRoller._touchStart(e, this._getScrollTop(this._touchMenuOwnerItem), 0);
			//prevneDefault를 하면 마우스 이벤트가 발생하지 않는 대신 미세한 차이에도 touchmove가 발생함.
		}

		protected _ontouchmove(e: events.CTouchEvent) {
			let touch = e.touches.length == 1 ? e.touches[0] : null;
			if (touch == null) {
				return;
			}
			this._touchRoller._touchMove(e, (scrollTop: number, scrollLeft: number) => {
				return this._setScrollTop(this._touchMenuOwnerItem, scrollTop);
			});

			this._touchMoved = true;
			e.stopPropagation();
			e.preventDefault();
		}

		private _ontouchend(e: events.CTouchEvent & events.CEvent) {
			// 터치 스크롤 동작
			let scrollTop = this._getMaxScrollTop(this._touchMenuOwnerItem) > 0 ? this._getScrollTop(this._touchMenuOwnerItem) : -1;
			let touchMenuOwner = this._touchMenuOwnerItem;
			this._touchRoller._touchEnd(e, scrollTop, 0, (scrollTop: number, scrollLeft: number) => {
				// _touchEnd가 애니메이션프레임으로 호출되어 함수 호출 시 this._touchMenuOwnerItem 정보가 유지되도록 변수 사용.
				if (!this._touchMenuOwnerItem) {
					return false;
				}
				return this._setScrollTop(touchMenuOwner, scrollTop);
			});
			this._endTouchEvent();

			// 클릭 동작
			if (e.cancelable) e.preventDefault(); // 마우스 이벤트 방지.

			if (e.touches.length > 0 || e.changedTouches.length != 1) {
				return;
			}

			if (this._touchMoved == false) {
				if (this._getUIControl().focused == false) {
					this._getUIControl().focus();
				}
				this._onClick(e);
				e.stopPropagation();
			}
		}

		override dispose(): void {
			if (this._mouseLeaveTimer) {
				this._mouseLeaveTimer.dispose();
				this._mouseLeaveTimer = null;
			}
			if (this._touchMenuOwnerItem) {
				this._touchMenuOwnerItem = null;
			}
			super.dispose();

		}
	}//class
}//namespace
