
namespace cpr.controls.gridpart.column {

	/** 
	 * @private
	 */
	export class GridCellGroup {
		private _detail: GridDetailCellProp[];
		private _columnLayout: GridColumnProp[];


		constructor() {
			this._detail = [];
		}

		get detail(): GridDetailCellProp[] {
			return this._detail;
		}

		get columnLayout(): GridColumnProp[] {
			return this._columnLayout;
		}
		set columnLayout(columnLayout: GridColumnProp[]) {
			this._columnLayout = columnLayout;
		}

		get startColIndex(): number {
			let groupRange: { startColIndex: number, endColIndex: number } = this.groupRange;
			return (groupRange) ? groupRange.startColIndex : -1;
		}
		get endColIndex(): number {
			let groupRange: { startColIndex: number, endColIndex: number } = this.groupRange;
			return (groupRange) ? groupRange.endColIndex : -1;
		}
		get groupRange(): { startColIndex: number, endColIndex: number } {
			let range: { startColIndex: number, endColIndex: number } = null;
			this._detail.forEach((detail: GridDetailCellProp) => {
				let colSpan: number = (detail.constraint.colSpan == null) ? 1 : detail.constraint.colSpan;
				if (range == null) {
					range = { startColIndex: detail.constraint.colIndex, endColIndex: detail.constraint.colIndex + colSpan };
				} else {
					if (detail.constraint.colIndex < range.startColIndex) {
						range.startColIndex = detail.constraint.colIndex;
					}
					if (detail.constraint.colIndex + colSpan > range.endColIndex) {
						range.endColIndex = detail.constraint.colIndex + colSpan;
					}
				}
			});
			return range;
		}

		public _add(cell: GridDetailCellProp): void {
			this._detail.push(cell);
		}

	}

	interface FamilyNode {
		parent: FamilyNode;
		children: FamilyNode[];
		prop: GridHeaderCellProp;
		details?: GridDetailCellProp[];
		footers?: GridFooterCellProp[];
		rowGroups?: GridFooterCellProp[];
	}

	/** 
	 * @private
	 */
	export class GridColumnGroup {
		private _header: GridHeaderCellProp[];
		private _detail: GridDetailCellProp[];
		private _footer: GridFooterCellProp[];

		private _rowgroups: {
			[groupCondition: string]: {
				gheader?: GridFooterCellProp[],
				gfooter?: GridFooterCellProp[]
			}
		};

		// 그룹내 가족관계
		private _headerFamily: { [cellIndex: number]: FamilyNode };

		constructor() {
			this._header = [];
			this._detail = [];
			this._footer = [];
		}

		public _initGenealogy(): void {
			// create genealogy(family tree)
			this._headerFamily = {};

			let headers: GridHeaderCellProp[] = [].concat(this._header);
			let groups: GridFooterCellProp[] = [];
			if (this._rowgroups) {
				let groupConds: string[] = _.keys(this._rowgroups);
				for (let idx: number = 0; idx < groupConds.length; idx++) {
					let rowgroup: {
						gheader?: GridFooterCellProp[],
						gfooter?: GridFooterCellProp[]
					} = this._rowgroups[groupConds[idx]];
					if (rowgroup.gheader && rowgroup.gheader.length > 0) {
						groups = groups.concat(rowgroup.gheader);
					}
					if (rowgroup.gfooter && rowgroup.gfooter.length > 0) {
						groups = groups.concat(rowgroup.gfooter);
					}
				}
			}

			for (let idx: number = 0; idx < headers.length; idx++) {
				let header: GridHeaderCellProp = headers[idx];
				let headerConst: GridCellConstraint = header.constraint;

				let rowIndex: number = headerConst.rowIndex;
				if (rowIndex == 0) {
					headers.splice(idx, 1);
					idx = 0;
					let colIndex: number = headerConst.colIndex;
					let lastRowIndex: number = rowIndex + _getNumber(headerConst, "rowSpan", 1) - 1;
					let lastColIndex: number = colIndex + _getNumber(headerConst, "colSpan", 1) - 1;

					let root: FamilyNode = {
						parent: null,
						children: [],
						prop: header
					};

					let nextRowIndex: number = lastRowIndex + 1;
					let success: boolean = this._getChildHeaderProp(root, nextRowIndex, colIndex, lastColIndex, headers, groups);
					if (success) {
						this._headerFamily[headerConst.cellIndex] = root;
					}
				}
			}
		}

		public _isSibling(cellIdx1: number, cellIdx2: number): boolean {
			let cell1FamilyConfig: FamilyNode = this._headerFamily[cellIdx1];
			let cell2FamilyConfig: FamilyNode = this._headerFamily[cellIdx2];
			if (cell1FamilyConfig == null || cell2FamilyConfig == null) {
				return false;
			}
			let cell1Family: FamilyNode = cell1FamilyConfig.parent;
			let cell2Family: FamilyNode = cell2FamilyConfig.parent;
			if (cell1Family == null || cell2Family == null) {
				return false;
			}
			return cell1Family == cell2Family;
		}

		public _moveSibling(gridColumnLayout: GridColumnProp[], srcCellIdx: number, targetCellIdx: number, before: boolean = false): boolean {
			if (srcCellIdx === targetCellIdx) {
				return false;
			}
			let srcFamilyConfig: FamilyNode = this._headerFamily[srcCellIdx];
			let targetFamilyConfig: FamilyNode = this._headerFamily[targetCellIdx];
			if (srcFamilyConfig == null || targetFamilyConfig == null) {
				return false;
			}
			let siblingFamily: FamilyNode = srcFamilyConfig.parent;
			if (siblingFamily == null) {
				return false;
			}
			let sibling: FamilyNode[] = siblingFamily.children;
			let srcIdx: number = -1;
			let targetIdx: number = -1;
			for (let idx: number = 0; idx < sibling.length; idx++) {
				let child: FamilyNode = sibling[idx];
				let cellIndex: number = child.prop.constraint.cellIndex;
				if (srcCellIdx == cellIndex) {
					srcIdx = idx;
				} else if (targetCellIdx == cellIndex) {
					targetIdx = idx;
				}
			}
			if (targetIdx == -1) {
				return false;
			}

			let startColIndex: number = srcFamilyConfig.prop.constraint.colIndex;
			let startColSpan: number = _getNumber(srcFamilyConfig.prop.constraint, "colSpan", 1);
			let targetColIndex: number = targetFamilyConfig.prop.constraint.colIndex;
			let targetColSpan: number = _getNumber(targetFamilyConfig.prop.constraint, "colSpan", 1);
			let targetIndex: number = before ? targetColIndex : targetColIndex + targetColSpan;

			if (startColIndex < targetColIndex) {
				this._shiftSiblings(sibling.slice(srcIdx + 1, before ? targetIdx : targetIdx + 1), -startColSpan);

				let srcColumnLayout: GridColumnProp[] = [];
				gridColumnLayout.forEach((columnInfo: GridColumnProp, index: number) => {
					if (utils.ParamUtil.isInRange(index, startColIndex, (startColIndex + startColSpan - 1))) {
						srcColumnLayout[srcColumnLayout.length] = columnInfo;
					}
				});
				for (let i = srcColumnLayout.length - 1; i >= 0; i--) {
					gridColumnLayout.splice(targetIndex, 0, srcColumnLayout[i]);
				}
				gridColumnLayout.splice(startColIndex, startColSpan);

			} else {
				this._shiftSiblings(sibling.slice(before ? targetIdx : targetIdx + 1, srcIdx), startColSpan);

				let srcColumnLayout: GridColumnProp[] = gridColumnLayout.splice(startColIndex, startColSpan);

				for (let i = srcColumnLayout.length - 1; i >= 0; i--) {
					gridColumnLayout.splice(targetIndex, 0, srcColumnLayout[i]);
				}
			}

			targetColIndex = targetFamilyConfig.prop.constraint.colIndex;
			targetColSpan = _getNumber(targetFamilyConfig.prop.constraint, "colSpan", 1);

			let moveColIndex: number = (before ? targetColIndex - startColSpan : targetColIndex + targetColSpan) - startColIndex;

			this._shiftFamilyNodeColIndex(srcFamilyConfig, moveColIndex);

			this._initGenealogy();

			return true;
		}

		public _getSiblingSideCellIndexs(cellIndex: number, before: boolean): number[] {
			let familyNode: FamilyNode = this._headerFamily[cellIndex];
			if (familyNode == null) {
				return null;
			}
			let headerConst: GridCellConstraint = familyNode.prop.constraint;
			let cellIndexs: number[] = [headerConst.cellIndex];
			let colIndex: number = headerConst.colIndex;
			let laseColIndex: number = colIndex + _getNumber(headerConst, "colSpan", 1) - 1;

			let children: FamilyNode[] = familyNode.children;
			for (let idx: number = 0; idx < children.length; idx++) {
				let child: FamilyNode = children[idx];
				let childConst: GridCellConstraint = child.prop.constraint;
				let childColIndex: number = childConst.colIndex;
				let childLastColIndex: number = childColIndex + _getNumber(childConst, "colSpan", 1) - 1;

				if ((before == true && colIndex == childColIndex) ||
					(before == false && laseColIndex == childLastColIndex)) {
					cellIndexs[cellIndexs.length] = childConst.cellIndex;
					idx = 0;
					children = child.children;
					if (children == null || children.length == 0) {
						break;
					}
				}
			}

			return cellIndexs;
		}

		private _shiftSiblings(children: FamilyNode[], moveColCnt: number): void {
			if (children == null || children.length == 0) {
				return;
			}

			for (let idx: number = 0; idx < children.length; idx++) {
				let child: FamilyNode = children[idx];
				if (child == null) {
					continue;
				}
				this._shiftFamilyNodeColIndex(child, moveColCnt);
			}
		}

		private _shiftFamilyNodeColIndex(child: FamilyNode, moveColCnt: number): void {
			let moveColIdx = (cellProp: GridCellProp) => {
				cellProp.constraint.colIndex += moveColCnt;
			};

			child.prop.constraint.colIndex += moveColCnt;

			let childHeadFamily: FamilyNode[] = child.children;
			if (childHeadFamily != null && childHeadFamily.length > 0) {
				this._shiftSiblings(childHeadFamily, moveColCnt);
			} else {
				if (child.details) {
					child.details.forEach(moveColIdx);
				}
				if (child.footers) {
					child.footers.forEach(moveColIdx);
				}
				if (child.rowGroups) {
					child.rowGroups.forEach(moveColIdx);
				}
			}
		}

		private _getChildHeaderProp(root: FamilyNode, rIdx: number, cIdx: number, maxCIdx: number
			, headers: GridHeaderCellProp[], groups: GridFooterCellProp[]): boolean {
			let hasChildRow: boolean = false;
			for (let idx: number = 0; idx < headers.length; idx++) {
				let header: GridHeaderCellProp = headers[idx];
				let headerConst: GridCellConstraint = header.constraint;
				let cRowIndex: number = headerConst.rowIndex;
				if (rIdx !== cRowIndex) {
					continue;
				}
				hasChildRow = true;
				let cColIndex: number = headerConst.colIndex;
				let rowSpan: number = _getNumber(headerConst, "rowSpan", 1);
				let colSpan: number = _getNumber(headerConst, "colSpan", 1);
				if (rowSpan < 1 || colSpan < 1) {
					continue;
				}
				let lastRowIndex: number = cRowIndex + rowSpan - 1;
				let lastColIndex: number = cColIndex + colSpan - 1;

				if (this._isOverlapped({ s: cIdx, e: maxCIdx }, { s: cColIndex, e: lastColIndex })) {
					if (this._isContained({ s: cIdx, e: maxCIdx }, { s: cColIndex, e: lastColIndex })) {
						let childNode: FamilyNode = {
							parent: root,
							children: [],
							prop: header
						}
						let nextRowIndex: number = lastRowIndex + 1;
						let success: boolean = this._getChildHeaderProp(childNode, nextRowIndex, cColIndex, lastColIndex, headers, groups);
						if (success) {
							root.children[root.children.length] = childNode;

							this._headerFamily[headerConst.cellIndex] = childNode;
						} else {
							return false;
						}
					} else {
						return false;
					}
				} else {
					continue;
				}
			}
			if (hasChildRow == false) {
				// 마지막 노드
				// detail
				let details: GridDetailCellProp[] = [];
				let success: boolean = this._fillBandProp(details, this._detail, cIdx, maxCIdx);
				if (success) {
					root.details = details;
				} else {
					return false;
				}
				// footer
				if (this._footer != null && this._footer.length > 0) {
					let footers: GridFooterCellProp[] = [];
					success = this._fillBandProp(footers, this._footer, cIdx, maxCIdx);
					if (success) {
						root.footers = footers;
					} else {
						return false;
					}
				}
				// group
				if (groups != null && groups.length > 0) {
					let rowGroups: GridFooterCellProp[] = [];
					success = this._fillBandProp(rowGroups, groups, cIdx, maxCIdx);
					if (success) {
						root.rowGroups = rowGroups;
					} else {
						return false;
					}
				}
			} else {
				root.children.sort((a: FamilyNode, b: FamilyNode) => {
					return a.prop.constraint.colIndex - b.prop.constraint.colIndex;
				});
			}

			return true;
		}

		private _fillBandProp(container: GridCellProp[], searchCells: GridCellProp[], cIdx: number, maxCIdx: number): boolean {
			for (let idx: number = 0; idx < searchCells.length; idx++) {
				let cellProp: GridCellProp = searchCells[idx];
				let cellConst: GridCellConstraint = cellProp.constraint;

				let colIndex: number = cellConst.colIndex;
				let lastColIndex: number = colIndex + _getNumber(cellConst, "colSpan", 1) - 1;

				if (this._isOverlapped({ s: cIdx, e: maxCIdx }, { s: colIndex, e: lastColIndex })) {
					if (this._isContained({ s: cIdx, e: maxCIdx }, { s: colIndex, e: lastColIndex })) {
						container[container.length] = cellProp;
					} else {
						return false;
					}
				}
			}
			return true;
		}

		private _isOverlapped(r1: { s: number, e: number }, r2: { s: number, e: number }): boolean {
			return (r2.s >= r1.s && r2.s <= r1.e) || (r2.e >= r1.s && r2.e <= r1.e);
		}

		private _isContained(r1: { s: number, e: number }, r2: { s: number, e: number }): boolean {
			return r2.s >= r1.s && r2.e <= r1.e;
		}

		get header(): GridHeaderCellProp[] {
			return this._header;
		}
		get detail(): GridDetailCellProp[] {
			return this._detail;
		}
		get footer(): GridFooterCellProp[] {
			return this._footer;
		}
		get rowgroups(): { [groupCondition: string]: { gheader?: GridFooterCellProp[], gfooter?: GridFooterCellProp[] } } {
			return this._rowgroups;
		}

		get startColIndex(): number {
			let groupRange: { startColIndex: number, endColIndex: number } = this.groupRange;
			return (groupRange) ? groupRange.startColIndex : -1;
		}
		get endColIndex(): number {
			let groupRange: { startColIndex: number, endColIndex: number } = this.groupRange;
			return (groupRange) ? groupRange.endColIndex : -1;
		}
		get groupRange(): { startColIndex: number, endColIndex: number } {
			let range: { startColIndex: number, endColIndex: number } = null;
			this._header.forEach((header: GridHeaderCellProp) => {
				let colSpan: number = (header.constraint.colSpan == null) ? 1 : header.constraint.colSpan;
				if (range == null) {
					range = { startColIndex: header.constraint.colIndex, endColIndex: header.constraint.colIndex + colSpan };
				} else {
					if (header.constraint.colIndex < range.startColIndex) {
						range.startColIndex = header.constraint.colIndex;
					}
					if (header.constraint.colIndex + colSpan > range.endColIndex) {
						range.endColIndex = header.constraint.colIndex + colSpan;
					}
				}
			});
			return range;
		}

		public _move(moveCount: number): void {
			[this.header, this.detail, this.footer].forEach((band: GridCellProp[]) => {
				band.forEach((cellprop: GridCellProp) => {
					cellprop.constraint.colIndex += moveCount;
				});
			})

			if (this._rowgroups != null) {
				let groupConditions: string[] = Object.keys(this._rowgroups);
				groupConditions.forEach((groupCondition: string) => {
					let regions: string[] = Object.keys(this._rowgroups[groupCondition]);
					regions.forEach((region: string) => {
						this._rowgroups[groupCondition][region].forEach((cellprop: GridCellProp) => {
							cellprop.constraint.colIndex += moveCount;
						});
					});
				});
			}

		}

		public _addGroupColumn(bandName: string, cellProp: GridCellProp): void {
			if (this._rowgroups == null) {
				this._rowgroups = {};
			}
			let bandInfoMeta: string[] = bandName.split(";");
			let groupCondition: string = bandInfoMeta[1];
			if (this._rowgroups[groupCondition] == null) {
				this._rowgroups[groupCondition] = {};
			}
			let region: string = bandInfoMeta[2];
			if (this._rowgroups[groupCondition][region] == null) {
				this._rowgroups[groupCondition][region] = [];
			}
			this._rowgroups[groupCondition][region].push(cellProp);
		}

	}
}