/// <reference path="./DataBinder.ts" />
/// <reference path="./ListDataBinder.ts" />
/// <reference path="./CalendarDataProvider.ts" />

namespace cpr.controls.provider {
	/**
	 * @private
	 */
	export abstract class AbstractCalendarDataBinder<ItemType extends CalendarItem, ConfigType extends CalendarItemSetConfig, ProviderType extends AbstractCalendarDataProvider<ItemType, ConfigType, any>> extends AbstractListDataBinder<ItemType, ConfigType, ProviderType> {

		constructor(owner: UIControl) {
			super(owner);
		}

		public _removeSelection(item: ItemType, emitEvent: boolean = true): boolean {
			let oldSelection = this.getSelection().concat();
			let newSelection = this.getSelection().concat();
			newSelection.some((each: CalendarItem, idx: number) => {
				if (each.value == item.value) {
					newSelection.splice(idx, 1);
					return true;
				}
				return false;
			});

			if (newSelection.length == oldSelection.length) {
				return true;
			}
			if (emitEvent) {
				let preventDefault = this.getOwner().dispatchEvent(new cpr.events.CSelectionEvent(events.SelectionEventType.BEFORE_ITEM_CHANGE, { oldSelection: oldSelection, newSelection: newSelection }));
				if (!preventDefault) {
					return false;
				}
			}
			if (newSelection.length != oldSelection.length) {
				this.setSelection(newSelection);
			}
			if (emitEvent) {
				this.getOwner().dispatchEvent(new cpr.events.CSelectionEvent(events.SelectionEventType.ITEM_CHANGE, { oldSelection: oldSelection, newSelection: newSelection }));
			}
			return true;
		}

		public _removeSingleSelection(item: ItemType, emitEvent: boolean = true): boolean {
			return this._removeSelection(item, emitEvent);
		}

		public setSelection(selection: ItemType[]) {
			this.getDataProvider().setSelection(selection);
		}

		/**
		 * multiple 일 경우 선택이 계속 쌓인다. 아닌경우 선택을 지우고 선택한다.
		 * @param item 
		 * @param multiple
		 * @param emitEvent 이벤트(before-item-selection-change, item-selection-change)를 발생시킬지 여부.
		 */
		public _select(item: ItemType, multiple: boolean = false, emitEvent: boolean = true): boolean {
			let oldSelection: ItemType[] = this.getSelection();
			let newSelection: ItemType[] = [];

			let isSelectedItem = this.getDataProvider().isSelected(item);

			if (multiple && !isSelectedItem) {
				newSelection = oldSelection.concat();
			}
			newSelection.push(item);

			// getSelection()시 index 순서로 item 나열.
			let me = this;
			newSelection.sort((a: ItemType, b: ItemType) => {
				return me.getIndex(a) > me.getIndex(b) ? 1 : -1;
			});

			if (emitEvent !== false) {
				//before-selection event
				let selectionEvent = new cpr.events.CSelectionEvent(events.SelectionEventType.BEFORE_ITEM_CHANGE
					, { oldSelection: oldSelection, newSelection: newSelection });

				let preventDefault = this.getOwner().dispatchEvent(selectionEvent);
				if (!preventDefault) {
					this.redraw();
					return false;
				}
			}

			//select
			this.getDataProvider().select(item, multiple);

			if (emitEvent !== false) {
				//selection event
				let selectionEvent = new cpr.events.CSelectionEvent(events.SelectionEventType.ITEM_CHANGE, {
					oldSelection: oldSelection,
					newSelection: this.getSelection()
				});

				this.getOwner().dispatchEvent(selectionEvent);
			}
			return true;
		}

		/**
		 * 조건에 맞는 첫 번째 아이템을 찾습니다.
		 * <pre><code>
		 * control.findItem(function(item){
		 *  return moment(item.start).isSame(moment("2020-06-30"));
		 * });
		 * </code></pre>
		 * @param condition 아이템을 찾을 조건.
		 * @return 조건에 맞는 첫 번째 아이템.
		 */
		public findItem(condition: any): ItemType {
			return this.getDataProvider().findItem(condition);
		}

		/**
		 * 조건에 맞는 모든 아이템들을 찾습니다.
		 * <pre><code>
		 * control.findItems(function(item){
		 *  return moment(item.start).isSame(moment("2020-06-30"));
		 * });
		 * </code></pre>
		 * @param condition 아이템을 찾을 조건.
		 * @return 조건에 맞는 모든 아이템의 배열.
		 */
		public findItems(condition: any): ItemType[] {
			return this.getDataProvider().findItems(condition);
		}

		/**
		 * 선택된 아이템을 모두 선택 해제합니다.
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 */
		public clearSelection(emitEvent: boolean = true): void {
			let oldSelection = this.getSelection();
			if (oldSelection.length == 0) {
				return;
			}

			if (emitEvent !== false) {
				//before-selection event
				let preventDefault = this.getOwner().dispatchEvent(new cpr.events.CSelectionEvent(events.SelectionEventType.BEFORE_ITEM_CHANGE
					, { oldSelection: oldSelection, newSelection: [] }));
				if (!preventDefault) {
					return;
				}
			}

			//clear selection
			this.getDataProvider().clearSelection();

			if (emitEvent !== false) {
				//selection-event
				this.getOwner().dispatchEvent(new cpr.events.CSelectionEvent(events.SelectionEventType.ITEM_CHANGE, {
					oldSelection: oldSelection, newSelection: this.getSelection()
				}));
			}
			this.redraw();
		}

	}

	/**
	 * value, label로 구성된 리스트 형태의 데이터를 가지고 바인드가 가능한 컴포넌트의 상위 컨트롤.
	 * @private
	 */
	export class CalendarDataBinder extends AbstractCalendarDataBinder<CalendarItem, CalendarItemSetConfig, CalendarDataProvider> {
		_createDataProvider(): controls.provider.CalendarDataProvider {
			return new controls.provider.CalendarDataProvider(this.getOwner());
		}
	}
}