namespace cpr.core {
	function decodeXMLCharacters(encodedText: string) {
		if (utils.Util.isNullOrEmpty(encodedText)) {
			return encodedText;
		}

		return encodedText
			.replace(/&#x([0-9a-fA-F]+);/g, (match: string, hex: string) => {
				let code = parseInt(hex, 16);
				return String.fromCharCode(code)
			})
			.replace(/&amp;/g, "&")
			.replace(/&gt;/g, ">")
			.replace(/&lt;/g, "<")
			.replace(/&quot;/g, "\"")
			.replace(/&apos;/g, "'")
	}


	/**
	 * cpr.core.XMLParser를 이용하여 파싱할 때 발생하는 이벤트를 처리하기 위한 인터페이스 입니다.
	 * @experimental
	 */
	export interface XMLHandler {
		/**
		 * XML 문서가 시작될 때 콜백 됩니다.
		 */
		startDocument(): void;

		/**
		 * 엘리먼트가 시작될 때 콜백 됩니다.
		 * @param tagName 태그 이름.
		 * @param attributes 속성 배열
		 */
		startElement(tagName: String, attributes: { key: string, value: string }[]): void;

		/**
		 * 엘리먼트가 종료될 때 콜백 됩니다.
		 * @param tagName 태그 이름.
		 */
		endElement(tagName: String): void;

		/**
		 * 텍스트 노드를 만날 때 콜백 됩니다.
		 * @param content 텍스트 콘텐트
		 */
		text(content: string): void;

		/**
		 * 문서가 종료될 때 콜백됩니다.
		 */
		endDocument(): void;
	}

	/**
	 * 이벤트 기반 XML 파서 입니다.
	 * @experimental
	 * @noinstance
	 */
	export class XMLParser {
		/**
		 * XML 파싱 이벤트 기반 핸들러를 이용하여 XML 소스를 파싱 합니다.
		 * @param source XML 소스를 담은 문자열.
		 * @param handler 소스 파싱 이벤트를 처리할 핸들러.
		 * @experimental
		 */
		static parse(source: string, handler: XMLHandler) {
			let nodes = ParseKit.xml.parse(source)
			handler?.startDocument?.call(handler);
			nodes.forEach(e => {
				switch (e.type) {
					case "start-element": {
						e.attributes?.forEach(it => it.value = decodeXMLCharacters(it.value));
						handler?.startElement?.call(handler, e.tagName, e.attributes);
						break;
					}

					case "end-element": {
						handler?.endElement?.call(handler, e.tagName);
						break;
					}

					case "self-close-element": {
						e.attributes?.forEach(it => it.value = decodeXMLCharacters(it.value));
						handler?.startElement?.call(handler, e.tagName, e.attributes);
						handler?.endElement?.call(handler, e.tagName);
						break;
					}
					case "text": {
						if (utils.Util.isNullOrEmpty(e.content.trim())) {
							return;
						}
						let text = decodeXMLCharacters(e.content);
						handler?.text?.call(handler, text);
						break;
					}

					case "cdata": {
						handler?.text?.call(handler, e.content);
						break;
					}

					case "comment": {
						// 아무일 안함.
						break;
					}
				}
			});
			handler?.endDocument?.call(handler);
		}
	}
}