namespace cpr.utils {

	interface URLLike {
		protocol: string;
		username: string;
		password: string;
		hostname: string;
		port: string;
		pathname: string;
		search: string;
		hash: string;
	}

	/**
	 * 
	 * @param url 
	 * @param baseURL 
	 */
	function parseURL(url: string, baseURL?: any): URLLike {
		var m = String(url).replace(/^\s+|\s+$/g, "").match(/^([^:\/?#]+:)?(?:\/\/(?:([^:@\/?#]*)(?::([^:@\/?#]*))?@)?(([^:\/?#]*)(?::(\d*))?))?([^?#]*)(\?[^#]*)?(#[\s\S]*)?/);
		if (!m) {
			throw new RangeError();
		}

		var protocol = m[1] || "";
		var username = m[2] || "";
		var password = m[3] || "";
		var host = m[4] || "";
		var hostname = m[5] || "";
		var port = m[6] || "";
		var pathname = m[7] || "";
		var search = m[8] || "";
		var hash = m[9] || "";
		if (baseURL !== undefined) {
			var base: URL;
			if (baseURL instanceof URL) {
				base = baseURL;
			} else if (baseURL instanceof window.URL) {
				base = new URL(baseURL.href);
			}
			else if (typeof baseURL == "string") {
				base = new URL(baseURL);
			}
			var flag = protocol === "" && host === "" && username === "";
			if (flag && pathname === "" && search === "") {
				search = base.search;
			}
			if (flag && pathname.charAt(0) !== "/") {
				pathname = (pathname !== "" ? (((base.host !== "" || base.username !== "") && base.pathname === "" ? "/" : "") + base.pathname.slice(0, base.pathname.lastIndexOf("/") + 1) + pathname) : base.pathname);
			}
			// dot segments removal
			var output = [];
			pathname.replace(/^(\.\.?(\/|$))+/, "")
				.replace(/\/(\.(\/|$))+/g, "/")
				.replace(/\/\.\.$/, "/../")
				.replace(/\/?[^\/]*/g, (p, ...args: any[]) => {
					if (p === "/..") {
						output.pop();
					} else {
						output.push(p);
					}
					return undefined
				});

			pathname = output.join("").replace(/^\//, pathname.charAt(0) === "/" ? "/" : "");
			if (flag) {
				port = base.port;
				hostname = base.hostname;
				password = base.password;
				username = base.username;
			}
			if (protocol === "") {
				protocol = base.protocol;
			}
		}
		return {
			protocol: protocol,
			username: username,
			password: password,
			hostname: hostname,
			port: port,
			pathname: pathname,
			search: search,
			hash: hash
		}
	}


	interface SearchParamEntry {
		name: string;
		value: string;
	}

	function parseSearch(search: string): SearchParamEntry[] {
		if (search.indexOf("?") !== 0) {
			return [];
		}
		let result: SearchParamEntry[] = [];
		search.substr(1).split("&").forEach(keyValuePair => {
			let pair = keyValuePair.split("=");
			let key = decodeURIComponent(pair[0]);
			let value = decodeURIComponent(pair[1]);
			result.push({
				name: key,
				value: value
			});
		});
		return result;
	}


	class URLSearchParamsImpl implements URLSearchParams {
		private _entries: SearchParamEntry[] = [];
		private _query: { [key: string]: string | string[] }
		private _search: string;

		constructor(search: string = "") {
			this._entries = parseSearch(search ?? "");
		}

		private _invalidate() {
			this._query = null;
			this._search = null;
		}

		append(name: string, value: string): void {
			this._entries.push({
				name: name,
				value: value
			});
			this._invalidate();
		}

		delete(name: string): void {
			this._entries = this._entries.filter(it => it.name != name);
			this._invalidate();
		}

		get(name: string): string {
			let entry = this._entries.find(it => it.name == name);
			return entry ? entry.value : null;
		}

		getAll(name: string): string[] {
			return this._entries.filter(it => it.name == name).map(it => it.value);
		}

		has(name: string): boolean {
			return this._entries.some(it => it.name == name);
		}

		set(name: string, value: string): void {
			let firstIndex = this._entries.findIndex(it => it.name == name);
			if (firstIndex !== -1) {
				this._entries = this._entries.filter(it => it.name != name);
				this._entries.splice(firstIndex, 0, { name: name, value: value })
				this._invalidate();
			}
			else {
				this.append(name, value);
			}
		}

		sort(): void {
			this._entries.sort((a, b) => {
				return a.name.localeCompare(b.name);
			});
			this._invalidate();
		}

		toString(): string {
			return this.search;
		}

		forEach(callbackfn: (value: string, key: string, parent: URLSearchParams) => void): void {
			this._entries.forEach((it) => {
				callbackfn(it.value, it.name, this);
			});
		}

		get search(): string {
			if (this._search == null) {
				if (this._entries.length > 0) {
					this._search = "?" + this._entries.map(it => {
						return `${encodeURIComponent(it.name)}=${encodeURIComponent(it.value)}`;
					}).join("&");
				}
				else {
					this._search = "";
				}
			}
			return this._search;
		}

		set search(newSearch: string) {
			this._search = this.search;
			this._entries = parseSearch(newSearch);
		}

		get query() {
			if (this._query == null) {
				let temp = {};
				this._entries.forEach(eachEntry => {
					let existing = temp[eachEntry.name];
					if (typeof existing == "string") {
						temp[eachEntry.name] = [
							existing,
							eachEntry.value
						];
					}
					else if (existing instanceof Array) {
						existing.push(eachEntry.value);
					} else {
						temp[eachEntry.name] = eachEntry.value;
					}
				});
				this._query = temp;
			}
			return this._query;
		}
	}

	export class URL {
		public protocol: string
		public username: string
		public password: string
		public hostname: string
		public port: string
		public pathname: string
		public hash: string
		private _searchParams: URLSearchParamsImpl;

		/**
		 * 새 URL 객체를 생성합니다.
		 * @param url URL 표현식.
		 * @param baseURL 기준 URL 표현식. 문자열이거나 URL 객체일 수 있습니다.
		 */
		constructor(url: string, baseURL?: any) {
			let info = parseURL(url, baseURL);
			this._searchParams = new URLSearchParamsImpl();
			this.protocol = info.protocol;
			this.username = info.username;
			this.password = info.password;
			this.hostname = info.hostname
			this.port = info.port;
			this.pathname = info.pathname;
			this.search = info.search;
			this.hash = info.hash;
		}

		/**
		 * URL 표현 문자열을 얻습니다.
		 */
		get href(): string {
			return this.protocol + (this.protocol !== "" || this.host !== "" ? "//" : "") + (this.username !== "" ? this.username + (this.password !== "" ? ":" + this.password : "") + "@" : "") + this.host + this.pathname + this.search + this.hash;
		}

		/**
		 * URL href 표현식을 지정합니다.
		 */
		set href(newHref: string) {
			let info = parseURL(newHref);
			this.protocol = info.protocol;
			this.username = info.username;
			this.password = info.password;
			this.hostname = info.hostname
			this.port = info.port;
			this.pathname = info.pathname;
			this.search = info.search;
			this.hash = info.hash;
		}

		/**
		 * 호스트를 얻습니다.
		 */
		get host(): string {
			return [this.hostname, this.port].filter(it => it != null && it.length > 0).join(":");
		}

		/**
		 * 호스트를 지정합니다.
		 */
		set host(newHost: string) {
			let segments = newHost.split(":");
			this.hostname = segments[0] || "";
			this.port = segments[1] || "";
		}

		/**
		 * 서치 파라미터 표현식을 지정합니다.
		 */
		set search(newSearch: string) {
			this._searchParams = new URLSearchParamsImpl(newSearch);
		}

		/**
		 * 서치 파라미터 표현식을 얻습니다.
		 */
		get search(): string {
			return this._searchParams.search;
		}

		/**
		 * 서치 파라미터를 JSON 형식으로 얻습니다.
		 * @deprecated 이 값은 읽기 전용입니다. 편집등의 작업을 수행하려면 {@link searchParams}를 사용하시기 바랍니다.
		 */
		get query(): { [key: string]: string | string[] } {
			return this._searchParams.query;
		}

		/**
		 * origin을 얻습니다.
		 */
		get origin(): string {
			return this.protocol + (this.protocol !== "" || this.host !== "" ? "//" : "") + this.host;
		}

		/**
		 * 서치 파라미터를 탐색하거나 조작할 수 있는 서치 파라미터 객체를 얻습니다.
		 */
		get searchParams(): URLSearchParams {
			return this._searchParams;
		}

		/**
		 * URL 표현식을 얻습니다.
		 */
		toString(): string {
			return this.href;
		}

		/**
		 * URL 사본 객체를 얻습니다.
		 */
		public getCopy(): URL {
			return new URL(this.href);
		}

		/**
		 * 두 URL이 완전히 일치하는지 비교합니다.
		 * @param other 비교할 URL 또는 문자열
		 */
		public equals(other: any) {
			if (other instanceof URL) {
				return this.href == other.href;
			} else if (typeof other == "string") {
				return this.href == other;
			} else {
				return false;
			}
		}

		/**
		 * 두 URL이 의미적으로 일치하는지 비교합니다. 서치 파라미터의 순서가 달라도 내용이 동일하면 같은 URL로 판단합니다.
		 * @param other 비교할 URL 또는 문자열
		 */
		public identicallyEquals(other: any): boolean {
			let otherURL: URL;
			if (other instanceof URL) {
				otherURL = other;
			} else if (typeof other == "string") {
				otherURL = new URL(other);
			} else {
				return false;
			}

			let source = this.getCopy();
			source.searchParams.sort();

			let target = otherURL.getCopy();
			target.searchParams.sort();

			return source.href == target.href;
		}
	}
}