/// <reference path="../expression/ExpressionEngine.ts"/>
/// <reference path="../expression/EvaluationContext.ts"/>
namespace cpr.data {
	export abstract class IDataRow implements expression.EvaluationContext {
		private _dataSet: DataCollection;

		constructor(dataSet: DataCollection) {
			this._dataSet = dataSet;
		}


		/**
		 * @private
		 */
		public _getDataSet(): DataCollection {
			return this._dataSet;
		}

		public abstract _getRowData(): tabledata.RowData;

		/**
		 * 현재 Row의 index를 반환합니다.
		 * @return 현재 row index
		 */
		public abstract getIndex(): number;
		/**
		 * 입력 받은 컬럼명에 해당하는 값을 반환합니다.
		 * @param columnName	값을 가져올 column의 columnName
		 * @return 해당 데이터
		 */
		public abstract getValue(columnName: column_name_string): (string | number | foundation.DecimalType | ufc.StyledString);
		/**
		 * 입력 받은 columnName에 해당되는 데이터를 수정합니다.
		 * @param columnName	수정할 column의 columnName
		 * @return 값 수정 성공 여부
		 */
		public abstract setValue(columnName: column_name_string, value: any): boolean;
		/**
		 * 현재 row의 row data를 { columnName : value } 형식으로 반환합니다.
		 * @return 현재 row의 row data (key: columnName, value: 해당 value형태의 json object).<br>
		 * 	{[columnName: string]: string | number}
		 */
		public abstract getRowData(columntype: header.HeaderType): RowConfigInfo;
		/**
		 * { columnName : value } 형식의 데이터를 받아 현재 row의 데이터를 전체 변경합니다.
		 * @param rowData		수정할 row data { columnName : value, ... } 형식.<br>
		 * 	{[columnName: string]: string | number}
		 */
		public abstract setRowData(rowData: RowConfigInfo): boolean;
		/**
		 * 현재 row의 상태값을 변경합니다.
		 * @param state 변경할 row의 상태값.<br>
		 * state 종류:<br>
		 * cpr.data.tabledata.RowState.UNCHANGED : 변경되지 않은 상태.<br>
		 * cpr.data.tabledata.RowState.INSERTED : 행이 신규로 추가된 상태.<br>
		 * cpr.data.tabledata.RowState.UPDATED : 행이 수정된 상태.<br>
		 * cpr.data.tabledata.RowState.DELETED : 행이 삭제된 상태.<br>
		 * cpr.data.tabledata.RowState.INSERTDELETED : 행이 추가되었다가 삭제된 상태.
		 */
		public abstract setState(state: tabledata.RowState): void; // Grid에 _UPDATE_STATE 이벤트 전파를 위해 원복.

		protected _isExistColumn(columnName: string): boolean {
			return this._dataSet.isExistColumn(columnName);
		}

		protected _getColumnIndex(columnName: string): number {
			return this._getDataSet()._getColumnIndex(columnName);
		}

		public _getHeader(columnName: string): header.Header {
			return this._dataSet.getHeader(columnName);
		}

		/**
		 * 입력 받은 columnName에 해당되는 데이터를 String형으로 반환합니다.
		 * @param columnName	값을 가져올 column의 columnName
		 * @return 해당 데이터의 String형
		 */
		public getString(columnName: column_name_string): string {
			let columnIndex: number = this._getColumnIndex(columnName);
			let rowData: tabledata.RowData = this._getRowData();
			let value = rowData.getValue(columnIndex);
			return utils.Util.toString(value);
		}

		/**
		 * 입력 받은 columnName에 해당되는 데이터를 Number형으로 반환합니다.<br>
		 * 값이 string형이어서 강제로 Number형으로 된경우 NaN이 반환된다.
		 * @param columnName	값을 가져올 column의 columnName
		 * @return 해당 데이터의 Number형
		 */
		public getNumber(columnName: column_name_string): number {
			let columnIndex: number = this._getColumnIndex(columnName);
			let rowData: tabledata.RowData = this._getRowData();
			let value = rowData.getValue(columnIndex);
			return utils.Util.toNumber(value);
		}

		/**
		 * 입력 받은 columnName에 해당되는 데이터를 Boolean형으로 반환합니다.
		 * @param columnName	값을 가져올 column의 columnName
		 * @return 해당 데이터의 Boolean형
		 */
		public getBoolean(columnName: column_name_string): boolean {
			let columnIndex: number = this._getColumnIndex(columnName);
			let rowData: tabledata.RowData = this._getRowData();
			let value = rowData.getValue(columnIndex);
			return utils.Util.toBoolean(value);
		}

		public _getDecimal(columnName: string): foundation.DecimalType {
			if (this._isExistColumn(columnName) == false) {
				return null;
			}
			let resultValue: foundation.DecimalType = null;
			let header: header.Header = this._getDataSet().getHeader(columnName);
			let datatype: tabledata.DataType = header.getDataType();
			if (datatype == tabledata.DataType.DECIMAL || datatype == tabledata.DataType.NUMBER) {
				let rowdata: tabledata.RowData = this._getRowData();
				let columnIndex: number = this._getColumnIndex(columnName);
				let value = rowdata.getValue(columnIndex);
				if (value != null && value !== "" && isNaN(value) == false) {
					resultValue = new foundation.DecimalType(value);
				}
			}
			return resultValue;
		}

		/**
		 * 입력 받은 rowIndex와 columnName에 해당되는 데이터를 Row상태를 변경하지 않고, 값만 변경합니다.
		 * @param columnName	수정할 column의 columnName
		 * @param value			수정할 value 값
		 * @return 값 수정 성공 여부
		 */
		public putValue(columnName: column_name_string, value: any): boolean {
			return DataUtil._putValue(this._getDataSet(), this._getRowData(), this.getIndex(), columnName, value);
		}

		/**
		 * 입력 받은 columnName에 해당되는 원본 데이터를 반환합니다.
		 * @param columnName	값을 가져올 column의 columnName
		 * @return 해당 데이터
		 */
		public getOriginalValue(columnName: column_name_string): any {
			if (this._isExistColumn(columnName) == false) {
				return null;
			}
			let columnIndex: number = this._getColumnIndex(columnName);
			let rowdata: tabledata.RowData = this._getRowData();
			return rowdata._getOriginalValue(columnIndex);
		}

		/**
		 * 현재 row의 상태값을 반환합니다.
		 * @return 현재 row의 상태값.<br>
		 * state 종류:<br>
		 * cpr.data.tabledata.RowState.UNCHANGED : 변경되지 않은 상태.<br>
		 * cpr.data.tabledata.RowState.INSERTED : 행이 신규로 추가된 상태.<br>
		 * cpr.data.tabledata.RowState.UPDATED : 행이 수정된 상태.<br>
		 * cpr.data.tabledata.RowState.DELETED : 행이 삭제된 상태.<br>
		 * cpr.data.tabledata.RowState.INSERTDELETED : 행이 추가되었다가 삭제된 상태.
		 */
		public getState(): tabledata.RowState {
			return this._getRowData().state;
		}

		/**
		 * 현재 row의 상태값을 문자형으로 반환합니다.
		 * @param isAbbreviation 축양형 표현 여부.
		 * @return 현재 row의 상태값 문자.<br>
		 * 	변경되지 않은 상태 : "UC", "UNCHANGED"<br>
		 * 	행이 신규로 추가된 상태 :  "I", "INSERTED"<br>
		 * 	행이 수정된 상태 :  "U", "UPDATED"<br>
		 * 	행이 삭제된 상태 :  "D" , "DELETED"<br>
		 * 	행이 추가되었다가 삭제된 상태 : "ID", "INSERTDELETED"
		 */
		public getStateString(isAbbreviation: boolean = true): string {
			let state: tabledata.RowState = this.getState();
			return DataUtil._getStateString(state, isAbbreviation);
		}

		/**
		 * 현재 row의 특정 속성을 설정합니다.
		 * @param attrName	지정할 속성명
		 * @param attrValue	지정할 속성값
		 */
		public setAttr(attrName: string, attrValue: string): void {
			let rowdata: tabledata.RowData = this._getRowData();
			rowdata._setAttr(attrName, attrValue);
		}

		/**
		 * 현재 row의 특정 속성을 설정합니다.
		 * @param attrName	지정할 속성명
		 * @param attrValue	지정할 속성값
		 */
		public getAttr(attrName: string): string {
			let rowdata: tabledata.RowData = this._getRowData();
			return rowdata._getAttr(attrName);
		}
		/**
		 * 현재 row의 모든 속성명의 배열을 반환합니다.
		 * @return 모든 속성명의 배열
		 */
		public getAttrNames(): string[] {
			let rowdata: tabledata.RowData = this._getRowData();
			return rowdata._getAttrNames();
		}

		/**
		 * 현재 row의 모든 속성에 대한 json object를 반환합니다.
		 * @return \{ [attrName: string]: string } 모든 속성에 대한 key : value 형식의 json object
		 */
		public getAttrs(): { [attrName: string]: string } {
			let rowdata: tabledata.RowData = this._getRowData();
			return rowdata._getAttrs();
		}

		public _getCtrlAttr(control: controls.Control, attrName: string): any {
			let rowdata: tabledata.RowData = this._getRowData();
			return rowdata._getCtrlAttr(control, attrName);
		}

		public _setCtrlAttr(control: controls.Control, attrName: string, attrValue: any): void {
			let rowdata: tabledata.RowData = this._getRowData();
			rowdata._setCtrlAttr(control, attrName, attrValue);
		}

		public _deleteCtrlAttr(control: controls.Control, attrName: string): void {
			let rowdata: tabledata.RowData = this._getRowData();
			rowdata._deleteCtrlAttr(control, attrName);
		}

		public _getRowCtrlAttr(control: controls.Control): tabledata.RowCtrlAttr {
			let rowdata: tabledata.RowData = this._getRowData();
			return rowdata._getRowCtrlAttr(control);
		}

		/**
		 * @private
		 */
		_getExpressionIDLookupProvider() {
			if (this._dataSet) {
				return this._dataSet.getAppInstance();
			} else {
				return null;
			}
		}

		/**
		 * @private
		 */
		_getExpressionDelegates(): any[] {
			return [this._dataSet];
		}

	}
}