namespace cpr.data {

	/**
	 * @private
	 */
	export class ViewTable {
		private _dataCollection: DataCollection;
		private _viewRows: tabledata.RowData[];


		constructor(dataCollection: DataCollection) {
			this._dataCollection = dataCollection;
			this._viewRows = [];
		}

		_reset() {
			this._viewRows = null;
			this._viewRows = [];
		}

		_addRow(orgRowInfo: tabledata.RowData): number {
			let rowIndex: number = this._viewRows.indexOf(orgRowInfo);
			if (rowIndex !== -1) {
				this._viewRows.splice(rowIndex, 1);
			}
			let viewRowIndex: number = this._viewRows.length;
			this._viewRows[viewRowIndex] = orgRowInfo;
			return viewRowIndex;
		}

		_addRowData(newRowInfo: tabledata.RowData): number {
			let viewRowIndex: number = this._viewRows.length;
			this._viewRows[viewRowIndex] = newRowInfo;
			return viewRowIndex;
		}

		_setRows(dataTable: DataTable): number {
			this._viewRows = [].concat(dataTable._getRows());
			return this._viewRows.length;
		}

		_insertRow(orgRowInfo: tabledata.RowData, viewRowIndex: number = this._viewRows.length): number {
			let rowIndex: number = this._viewRows.indexOf(orgRowInfo);
			if (rowIndex !== -1) {
				this._viewRows.splice(rowIndex, 1);
			}
			this._viewRows.splice(viewRowIndex, 0, orgRowInfo);
			return viewRowIndex;
		}

		_deleteRow(rowIndex: number): boolean {
			if (rowIndex < 0 || rowIndex >= this._getRowCount()) {
				return false;
			}
			let rowData: tabledata.RowData = this._viewRows[rowIndex];
			let rowState: tabledata.RowState = rowData.state;

			if (rowState == tabledata.RowState.INSERTED) {
				this._setRowState(rowIndex, tabledata.RowState.INSERTDELETED);

			} else if (rowState == tabledata.RowState.UNCHANGED ||
				rowState == tabledata.RowState.UPDATED) {
				this._setRowState(rowIndex, tabledata.RowState.DELETED);
			}
			return true;
		}

		_realDeleteRow(rowIndex: number): void {
			if (rowIndex < 0 || rowIndex > this._getRowCount()) {
				return;
			}

			this._viewRows.splice(rowIndex, 1);
		}

		_getRowCount(): number {
			return this._viewRows.length;
		}

		_changeRowIndex(sourceIndex: number, targetIndex: number): void {
			// 체크는 한 곳에서만 하면 됨.
			if (sourceIndex < 0 || sourceIndex >= this._getRowCount() ||
				targetIndex < 0 || targetIndex >= this._getRowCount() ||
				sourceIndex == targetIndex) {
				return;
			}
			let sourceRowInfo: tabledata.RowData = this._viewRows[sourceIndex];
			let targetRowInfo: tabledata.RowData = this._viewRows[targetIndex];

			if (sourceRowInfo && targetRowInfo) {
				this._viewRows[sourceIndex] = targetRowInfo;
				this._viewRows[targetIndex] = sourceRowInfo;
			}
		}

		_moveRowIndex(sourceIndex: number, targetIndex: number, after: boolean): void {
			if (sourceIndex < 0 || sourceIndex >= this._getRowCount() ||
				targetIndex < 0 || targetIndex >= this._getRowCount() ||
				sourceIndex == targetIndex) {
				return;
			}
			let sourceRowInfo: tabledata.RowData = this._viewRows[sourceIndex];
			if (targetIndex > sourceIndex) {
				targetIndex -= 1;
			}
			if (after) {
				targetIndex += 1;
			}

			this._viewRows.splice(sourceIndex, 1);
			this._viewRows.splice(targetIndex, 0, sourceRowInfo);
		}

		_getValue(rowIndex: number, columnIndex: number): any {
			let rowData: tabledata.RowData = this._viewRows[rowIndex];
			return rowData.getValue(columnIndex);
		}

		_setValue(rowIndex: number, columnIndex: number, value: any): void {
			let rowData: tabledata.RowData = this._viewRows[rowIndex];
			let header: header.Header = this._dataCollection._getHeaderFromIndex(columnIndex);
			rowData.setValue(header, columnIndex, value);
		}

		_setOriginalValue(rowIndex: number, columnIndex: number, value: any): void {
			let rowData: tabledata.RowData = this._viewRows[rowIndex];
			let header: header.Header = this._dataCollection._getHeaderFromIndex(columnIndex);
			rowData._setOriginalValue(header, columnIndex, value);
		}

		_getOriginalValue(columnIndex: number, rowIndex: number): any {
			let rowData: tabledata.RowData = this._viewRows[rowIndex];
			return rowData._getOriginalValue(columnIndex);
		}

		_getRowData(rowIndex: number): tabledata.RowData {
			return this._viewRows[rowIndex];
		}

		_setRowStateRanged(state: tabledata.RowState, startIndex: number = 0, endIndex: number = (this._getRowCount() - 1)): void {
			if (cpr.utils.ParamUtil.isInRange(startIndex, 0, this._getRowCount() - 1) == false) {
				return;
			}
			if (cpr.utils.ParamUtil.isInRange(endIndex, 0, this._getRowCount() - 1) == false) {
				return;
			}

			for (let i = endIndex; i >= startIndex; i--) {
				let rowData: tabledata.RowData = this._viewRows[i];
				DataUtil._setState(this._dataCollection.dataTable, rowData, state);
			}
		}

		_getRowIndicesByState(state: tabledata.RowState): { [state: number]: number[] } {
			let result: { [state: number]: number[] } = {};
			if (state == null) {
				return result;
			}
			let rowLength: number = this._getRowCount();
			let rowState: tabledata.RowState;
			for (let i = 0; i < rowLength; i++) {
				rowState = this._getRowState(i);

				if (rowState & state) {
					if (result[rowState] == null) {
						result[rowState] = [];
					}
					result[rowState].push(i);
				}
			}
			return result;
		}

		_getRowStatedIndices(state: tabledata.RowState): number[] {
			let result: number[] = [];
			if (state == null) {
				return result;
			}
			let rowLength: number = this._getRowCount();
			for (let i = 0; i < rowLength; i++) {
				let rowState: tabledata.RowState = this._getRowState(i);
				if (rowState & state) {
					result[result.length] = i;
				}
			}
			return result;
		}

		_getRowStatedIndex(state: tabledata.RowState): number {
			if (state == null) {
				return -1;
			}
			let rowLength: number = this._getRowCount();
			for (let i = 0; i < rowLength; i++) {
				let rowState: tabledata.RowState = this._getRowState(i);
				if (rowState & state) {
					return i;
				}
			}
			return -1;
		}

		_getRowCountByState(state: tabledata.RowState): { [state: number]: number } {
			let result: { [state: number]: number } = {};
			if (state == null) {
				return result;
			}
			let rowLength: number = this._getRowCount();
			let rowState: tabledata.RowState;
			let temp: number;

			for (let i = 0; i < rowLength; i++) {
				rowState = this._getRowState(i);

				if (rowState & state) {
					temp = result[rowState];
					if (temp == null) {
						temp = 0;
					}
					temp++;
					result[rowState] = temp;
				}
			}
			return result;
		}

		_getRowStatedCount(state: tabledata.RowState): number {
			let result: number = 0;
			if (state == null) {
				return result;
			}

			let rowLength: number = this._getRowCount();
			for (let i = 0; i < rowLength; i++) {
				let rowState: tabledata.RowState = this._getRowState(i);
				if (rowState & state) {
					result++;
				}
			}
			return result;
		}

		_getRowsAttr(attrName: string): string[] {
			let result: string[] = [];
			let rowLength: number = this._getRowCount();

			for (let i = 0; i < rowLength; i++) {
				result[result.length] = this._getRowAttr(i, attrName);
			}
			return result;
		}

		_setRowsAttr(attrName: string, attrValue: string): void {
			let rowLength: number = this._getRowCount();
			for (let i = 0; i < rowLength; i++) {
				this._setRowAttr(i, attrName, attrValue);
			}
		}

		_getRowAttr(rowIndex: number, attrName: string): string {
			let row: tabledata.RowData = this._viewRows[rowIndex];
			return row._getAttr(attrName);
		}

		_setRowAttr(rowIndex: number, attrName: string, attrValue: string): void {
			let row: tabledata.RowData = this._viewRows[rowIndex];
			row._setAttr(attrName, attrValue);
		}

		_getRowState(rowIndex: number): tabledata.RowState {
			let rowData: tabledata.RowData = this._viewRows[rowIndex];
			return rowData.state;
		}

		_setRowState(rowIndex: number, state: tabledata.RowState): void {
			let rowData: tabledata.RowData = this._viewRows[rowIndex];
			// let beforeState: tabledata.RowState = rowData.getState();
			// rowData._setState(state);
			// rowData._afterStateChange(beforeState, state);
			DataUtil._setState(this._dataCollection.dataTable, rowData, state);
		}

		_getDecimal(rowIndex: number, columnIndex: number): foundation.DecimalType {
			let rowData: tabledata.RowData = this._viewRows[rowIndex];
			let header: header.Header = this._dataCollection._getHeaderFromIndex(columnIndex);
			return rowData._getDecimal(header, columnIndex);
		}


		_doFilter(filterExp: expression.Expression, filterCondition: GridFilterCondition[] = []): void {
			if (filterExp == null && filterCondition.length == 0) {
				return;
			}

			let filter: (it, key, context) => boolean = null;
			if (filterExp != null) {
				filter = filterExp.asFilter();
			}

			this._viewRows = this._viewRows.filter((it: tabledata.RowData, key: number, context: tabledata.RowData[]) => {
				let row: DataRow = new DataRow(this._dataCollection, it);
				let result: boolean = true;

				if (filter != null) {
					result = filter(row, key, context);
				}

				if (filterCondition.length > 0) {
					filterCondition.some((condition: GridFilterCondition) => {
						let value: (string | number | foundation.DecimalType) = row._getExpressionOnlyProperty(condition.colNm);
						let valueStr: string = utils.Util.toString(value);
						if (condition.valueSet.has(valueStr) == false) {
							result = false;
							return true;
						}
					});
				}

				if (result == false) {
					this._dataCollection.dispatchEvent(new events.CDataEvent(cpr.events.DataEventType._FILTERED_SELECTION_ROW, {
						rowData: it as any
					}));
				}
				return result;
			});
		}
		_doLinkedFilter(parentRowId: string): void {
			if (parentRowId != null) {
				this._viewRows = this._viewRows.filter((it: tabledata.RowData, key: number, context: tabledata.RowData[]) => {
					return it._getCategory() == parentRowId;
				});
			}
		}

		_doSort(sortCondition: expression.Expression): void {
			if (sortCondition == null) {
				return;
			}

			let rows: { datarow: IDataRow, index: number }[] = this._viewRows.map((rowData: tabledata.RowData, index: number) => {
				return { "datarow": new DataRow(this._dataCollection, rowData), "index": index };
			});

			let comparator: (a, b) => number = sortCondition.asComparator();
			rows = rows.sort((a: { datarow: IDataRow, index: number }, b: { datarow: IDataRow, index: number }) => {
				let compare: number = comparator(a.datarow, b.datarow);
				if (compare == 0) {
					if (a.index < b.index) {
						return -1;
					} else if (a.index == b.index) {
						return 0;
					}
					return 1;
				}
				return compare;
			});

			this._viewRows = rows.map((row: { datarow: IDataRow, index: number }) => {
				return row.datarow._getRowData();
			});

		}
		_indexOf(rowData: tabledata.RowData): number {
			return this._viewRows.indexOf(rowData);
		}

		public _getCtrlAttr(control: controls.Control, rowIndex: number, attrName: string): any {
			return this._viewRows[rowIndex]._getCtrlAttr(control, attrName);
		}

		public _setCtrlAttr(control: controls.Control, rowIndex: number, attrName: string, attrValue: any): void {
			this._viewRows[rowIndex]._setCtrlAttr(control, attrName, attrValue);
		}

		public _deleteCtrlAttr(control: controls.Control, rowIndex: number, attrName: string): void {
			this._viewRows[rowIndex]._deleteCtrlAttr(control, attrName);
		}

		public _deleteAllCtrlAttr(control: controls.Control): void {
			let length: number = this._viewRows.length;
			for (let i = 0; i < length; i++) {
				this._viewRows[i]._deleteAllCtrlAttr(control);
			}
		}

		public _getCtrlAttrNames(control: controls.Control, rowIndex: number): string[] {
			return this._viewRows[rowIndex]._getCtrlAttrNames(control);
		}

		public _getCtrlAttrs(control: controls.Control, rowIndex: number): { [attrName: string]: string } {
			return this._viewRows[rowIndex]._getCtrlAttrs(control);
		}

		public _getRowCtrlAttr(control: controls.Control, rowIndex: number): tabledata.RowCtrlAttr {
			return this._viewRows[rowIndex]._getRowCtrlAttr(control);
		}

		/**
		 * 
		 * @param rowIndex 
		 * @param conditionExpr 
		 * @return 해당 행이 필터링 되었는지 유무. (해당 행을 찾을 수 없는 경우도 필터링 된걸로 판단하여 true 반환.)
		 */
		_isFilterRow(rowIndex: number, conditionExpr: expression.Expression): boolean {

			let comparator: (it, key, context) => boolean = conditionExpr.asFilter();
			let rowData: tabledata.RowData = this._viewRows[rowIndex];
			if (rowData == null) {
				return true;
			}
			let row: IDataRow = new DataRow(this._dataCollection, rowData);
			return !comparator(row, rowIndex, this._viewRows);
		}

		public _findAllRows(columnIndex: number, columnValues: any[]): number[] {
			let result: number[] = [];
			let rowLength: number = this._getRowCount();
			let header: header.Header = this._dataCollection._getHeaderFromIndex(columnIndex);
			for (let i = 0; i < rowLength; i++) {
				let value: string = this._dataCollection.getString(i, header.getName());
				if (columnValues.indexOf(value) != -1) {
					result[result.length] = i;
				}
			}
			return result;
		}

		public _findAllRowFromVisibleRows(columnIndex: number, columnValues: string[]): number[] {
			let visibleState: tabledata.RowState = (tabledata.RowState.UNCHANGED | tabledata.RowState.INSERTED | tabledata.RowState.UPDATED);

			let result: number[] = [];
			let rowLength: number = this._getRowCount();
			let header: header.Header = this._dataCollection._getHeaderFromIndex(columnIndex);
			for (let i = 0; i < rowLength; i++) {
				let rowState: tabledata.RowState = this._getRowState(i);
				if (rowState & visibleState) {
					let value: string = this._dataCollection.getString(i, header.getName());
					if (columnValues.indexOf(value) != -1) {
						result[result.length] = i;
					}
				}
			}
			return result;
		}
	}
}
