		/**
		 * 현재 활성화된 포커스 엔트리를 반환합니다.
		 * @returns 
		 */
		public _getActiveFocusEntry() {
			if (this._isFocusable()) {
				return this._getActiveFocusEntryByElement(document.activeElement as HTMLElement);
			} else {
				return this._getActiveFocusEntryByTabFocus(this._getTabFocus());
			}
		}

		protected _getActiveFocusEntryByTabFocus(tabFocus: CalendarTabFocus) {
			switch (tabFocus) {
				case CalendarTabFocus.prev: {
					return this._prevFocusEntry;
				}
				case CalendarTabFocus.title: {
					return this._titleFocusEntry;
				}
				case CalendarTabFocus.next: {
					return this._nextFocusEntry;
				}
				case CalendarTabFocus.body: {
					return this._currentFocusEntry;
				}
				case CalendarTabFocus.footer: {
					return this._footerFocusEntry;
				}
			}
			return null;
		}

		protected _getActiveFocusEntryByElement(activeElement: HTMLElement) {
			if (!activeElement) {
				return null;
			}
			let classList = activeElement.classList;

			if (classList.contains(CalendarFocusableClassName.prev)) {
				return this._prevFocusEntry;
			} else if (classList.contains(CalendarFocusableClassName.title)) {
				return this._titleFocusEntry;
			} else if (classList.contains(CalendarFocusableClassName.next)) {
				return this._nextFocusEntry;
			} else if (classList.contains(CalendarFocusableClassName.current) || activeElement.getAttribute("data-current") == "true") {
				return this._currentFocusEntry;
			} else if (classList.contains(CalendarFocusableClassName.footer)) {
				return this._footerFocusEntry;
			}
			return null;
		}

		private _focusImmediateBySelector(selector: string) {
			if (this._isDisposed()) {
				return;
			}
			if (this._isFocusable()) {
				let node = this._owner._getRenderer().getNamedNode("calendarField");
				if (node) {
					let focusible = null;
					if (selector.indexOf(CalendarFocusableClassName.current) > -1) {
						focusible = node.querySelector("[data-current]") as HTMLElement;
					} else {
						focusible = node.querySelector(selector) as HTMLElement;
					}
					if (focusible) {
						focusible.focus();
					}
				}
			} else {
				this._setTabFocusBySelector(selector);
			}
		}

		protected _setTabFocusBySelector(selector: string) {
			if (selector.indexOf(CalendarFocusableClassName.prev) > -1) {
				this._setTabFocus(CalendarTabFocus.prev);
			} else if (selector.indexOf(CalendarFocusableClassName.title) > -1) {
				this._setTabFocus(CalendarTabFocus.title);
			} else if (selector.indexOf(CalendarFocusableClassName.next) > -1) {
				this._setTabFocus(CalendarTabFocus.next);
			} else if (selector.indexOf(CalendarFocusableClassName.current) > -1) {
				this._setTabFocus(CalendarTabFocus.body);
			} else if (selector.indexOf(CalendarFocusableClassName.footer) > -1) {
				this._setTabFocus(CalendarTabFocus.footer);
			}
		}
		public _setFocusNextHandler(focusNextHandler: (activeFocusEntry: FocusEntry, focusEntries: FocusEntry[]) => FocusEntry) {
			if (this._focusNextHandler == focusNextHandler) {
				return;
			}
			this._focusNextHandler = focusNextHandler;
		}

		public _setFocusPreviousHandler(focusPreviousHandler: (activeFocusEntry: FocusEntry, focusEntries: FocusEntry[]) => FocusEntry) {
			if (this._focusPreviousHandler == focusPreviousHandler) {
				return;
			}
			this._focusPreviousHandler = focusPreviousHandler;
		}

		public _focusBySelector(selector: string, immediate: boolean = false) {
			if (immediate) {
				this._focusImmediateBySelector(selector);
			} else {
				core.DeferredUpdateManager.INSTANCE._performFocusTask(() => {
					this._focusImmediateBySelector(selector);
				});
			}
		}

		protected _createHeader() {
			let header: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: [],
				styler: "header",
				style: {},
				children: []
			};
			let templateColumns = [];
			if (this.headerButtons.length > 0) {
				header.children = this._createHeaderContents();
				if (this.headerButtons.indexOf(CalendarHeaderButtonType.title) == -1) {
					header.children.push({
						tag: "div",
						attr: {},
						classNames: [],
						style: {},
						children: ["&nbsp;"]
					})
				}
			}

			header.children.forEach((each: ufc.ElementShape) => {
				if (each.classNames.indexOf(CalendarFocusableClassName.title) > -1) {
					templateColumns.push("1fr");
				} else {
					templateColumns.push("auto");
				}
			})
			layouts.GridCSSBuilder._forLayout()._withTemplateColumns(templateColumns)._withTemplateRows("1fr")._commit(header.style);
			return header;
		}

