		protected _checkDisabledDateExp(date: Date) {
			if (this.enabledDateExp == null) {
				return false;
			}
			return !this._getEnabledDateExp(date);
		}

		protected _getEnabledDateExp(date: Date): boolean {

			let obj: Date & expression.EvaluationContext = moment(date).toDate();
			let expr = new cpr.expression.Expression(this.enabledDateExp);
			let result: boolean = false;
			if (this._containsMinMaxDate(moment(date)) == false) {
				return result;
			}
			let calendarDate = new controls.CalendarDate();
			calendarDate._init(this.owner, date);
			calendarDate.text = this._getDateText(date);
			calendarDate.currentCalendarType = this._getType();
			utils.tryCatch({
				do: () => {
					obj._getExpressionDelegates = () => {
						return [
							new bind.CalendarDateContext(calendarDate, this._owner)
						]
					}

					result = expr.evaluate(obj);
				}
			})
			return result;
		}

