namespace cpr {
	function log(...args: any[]) {
		utils.Logger.forTopic("collection").log(...args);
	};

	/**
	 * {@link NodeList}, {@link HTMLCollection} 및 {@link FileList}등을 나타내는 타입.
	 */
	export type NodeListLike<T> = {
		readonly length: number;
		item(index: number): T | null;
		[index: number]: T;
	};

	/** @internal */
	export namespace NodeListLike {
		export function _isNodeListLike(obj: object & any): obj is NodeListLike<any> {
			if (!obj) {
				return false;
			}

			return typeof obj.item == "function" && typeof obj.length == "number";
		}
	}

	/**
	 * 새 맵을 만듭니다.
	 * @returns 
	 */
	export function _createMap<K, V>(): CMap<K, V> {
		if (_ECMA._collection) {
			return new Map();
		} else {
			return new CShimMap();
		}
	}

	/**
	 * 새 맵을 만듭니다.
	 * @returns 
	 */
	export function _createWeakMap<K extends object, V>(): CWeakMap<K, V> {
		if (_ECMA._collection) {
			return new WeakMap();
		} else {
			return new CShimWeakMap();
		}
	}

	/**
	 * 역탐색이 가능한 맵을 만듭니다.
	 * 이 맵의 키와 값은 모두 유니크 해야 합니다.
	 * 
	 * @returns 맵.
	 * @see CBiMap.inversed
	 */
	export function _createBiMap<K, V>(): CBiMap<K, V> {
		return new BiMapImpl();
	}

	/**
	 * 중복요소가 포함될 수 없는 Set를 만듭니다.
	 * @param initialElements 초기 요소.
	 * @returns 
	 */
	export function _createSet<T>(...initialElements: T[]): CSet<T>
	/**
	 * 중복요소가 포함될 수 없는 Set를 만듭니다.
	 * @param initialElements 초기 요소.
	 * @returns 
	 */
	export function _createSet<T>(initialElements: T[]): CSet<T>
	export function _createSet<T>(...initialElements: T[]): CSet<T> {
		initialElements = initialElements.length == 1 && Array.isArray(initialElements[0]) ? initialElements[0] : initialElements;
		if (_ECMA._collection) {
			let set: CSet<T> = new Set(initialElements);
			if (initialElements.length > 0 && set.size == 0) {
				// IE11에서 new Set([1,2,3])의 배열이 반영되지 않아 직접 추가함.
				initialElements.forEach(e => set.add(e));
			}
			return set;
		} else {
			return _tap(new CShimSet(), set => {
				initialElements.forEach(e => set.add(e));
			});
		}
	}

	/**
	 * 중복요소가 포함될 수 없는 {@link CWeakSet}를 만듭니다.
	 * @param initialElements 초기 요소.
	 * @returns 
	 */
	export function _createWeakSet<T extends object>(...initialElements: T[]): CWeakSet<T>
	/**
	 * 중복요소가 포함될 수 없는 {@link CWeakSet}를 만듭니다.
	 * @param initialElements 초기 요소.
	 * @returns 
	 */
	export function _createWeakSet<T extends object>(initialElements: T[]): CWeakSet<T>
	export function _createWeakSet<T extends object>(...initialElements: T[]): CWeakSet<T> {
		initialElements = initialElements.length == 1 && Array.isArray(initialElements[0]) ? initialElements[0] : initialElements;
		// IE11에서  Map,Set이 있으나 WeakSet이 없음.
		if (_ECMA._collection && typeof WeakSet == "function") {
			return new WeakSet(initialElements);
		} else {
			return _tap(new CShimWeakSet(), set => {
				initialElements.forEach(e => set.add(e));
			});
		}
	}


	/**
	 * 순서를 보장하는 맵을 만듭니다.
	 * 순서 보장이 필요 없는 경우 {@link _createMap}을 대신 사용하십시오. 
	 */
	export function _createOrderedMap<Key, Value>(): COrderedMap<Key, Value> {
		if (_ECMA._collection) {
			return new FastObjectMap();
		}
		else {
			return new utils.ObjectMap();
		}
	}

	/**
	 * Cleopatra 셋 인터페이스 입니다.
	 * ECMA Set를 IE11에서의 작동 범주 내에서 승계 합니다.
	 * @internal
	 */
	export interface CWeakMap<K extends object, V> {
		delete(key: K): boolean;
		get(key: K): V | undefined;
		has(key: K): boolean;
		set(key: K, value: V): this;
	}

	/**
	 * Cleopatra 맵 인터페이스 입니다.
	 * ECMA Map을 IE11에서의 작동 범주 내에서 승계 합니다.
	 * @internal
	 */
	export interface CMap<K, V> {
		forEach(callbackfn: (value: V, key: K, map: CMap<K, V>) => void, thisArg?: any): void;
		get(key: K): V | undefined;
		has(key: K): boolean;
		readonly size: number;
		clear(): void;
		delete(key: K): boolean;
		set(key: K, value: V): this;
	}

	/** @internal */
	export namespace CMap {
		export type Entry<Key, Value> = {
			key: Key,
			value: Value
		};

		/**
		 * 주어진 인자가 {@link CMap} 인터페이스를 준수하는 객체인지 여부를 확인 합니다.
		 * @param e 검사할 객체.
		 * @returns {@link CMap} 인터페이스를 지원하는 객체인지 여부.
		 */
		export function _isCMap(e: any): e is CMap<any, any> {
			if (_ECMA._collection) {
				return e instanceof Map;
			} else {
				return e instanceof CShimMap;
			}
		}

		/**
		 * {@link CMap}을 JSON 형태로 얻습니다. 키의 타입이 string인 경우에만 사용 가능 합니다.
		 * 
		 * @param map JSON으로 변환할 {@link CMap}.
		 * @returns JSON 객체.
		 */
		export function _toJSON<V>(map: CMap<string, V>): { [key: string]: V } {
			if (_ECMA._fromEntries) {
				return Object.fromEntries(map as Map<any, any>)
			} else {
				let result = {};
				map.forEach((value, key) => {
					result[key] = value;
				})
				return result;
			}
		}

		export function _fromJSON<V>(json: { [key: string]: V }): CMap<string, V> {
			let result = _createMap<string, V>();
			Object.keys(Object(json)).forEach(key => {
				result.set(key, json[key]);
			});
			return result;
		}

		/**
		 * 맵의 키 스트림을 얻습니다.
		 * @param map 키 스트림을 얻을 맵.
		 * @returns 해당 맵의 키 스트림.
		 */
		export function _keyStream<Key>(map: CMap<Key, any>): Stream<Key> {
			if (_ECMA._iterable) {
				return _stream((map as Map<Key, any>).keys());
			}
			else {
				let result = [];
				map.forEach((value, key) => {
					result[result.length] = key;
				});
				return _stream(result);
			}
		}

		/**
		 * 맵의 값 스트림을 얻습니다.
		 * @param map 값 스트림을 얻을 맵.
		 * @returns 값 스트림.
		 */
		export function _valueStream<Value>(map: CMap<any, Value>): Stream<Value> {
			if (_ECMA._iterable) {
				return _stream((map as Map<any, Value>).values());
			}
			else {
				let result = [];
				map.forEach((value, key) => {
					result[result.length] = value;
				});
				return _stream(result);
			}
		}

		export function _entryStream<Key, Value>(map: CMap<Key, Value>): Stream<CMap.Entry<Key, Value>> {
			if (_ECMA._iterable) {
				return _stream((map as any as Map<Key, Value>).entries())
					.map(([key, value]) => {
						return { key, value };
					});
			}
			else {
				return _keyStream(map)
					.map(key => {
						return { key, value: map.get(key) }
					});
			}
		}

		export function _ensureValue<Key, Value>(map: CMap<Key, Value>, key: Key, valueFactory: () => Value): Value {
			if (map.has(key)) {
				return map.get(key);
			}
			else {
				let value = valueFactory();
				map.set(key, value);
				return value;
			}
		}
	}

	/**
	 * 바이맵(Bidirectional Map)은 값들과 키들이 고유성을 유지하는 맵입니다. 
	 * 이 제약 조건을 전제로 키와 값이 역전된 뷰를 제공합니다.
	 */
	export interface CBiMap<K, V> extends CMap<K, V> {
		/**
		 * 키와 값이 역전된 뷰를 얻습니다.
		 * 데이터는 원본 바이맵과 공유 됩니다.
		 */
		get inversed(): CBiMap<V, K>;
	}

	/**
	 * Cleopatra Set 인터페이스 입니다.
	 * ECMA Set를 IE11에서의 작동 범주 내에서 승계 합니다.
	 * @internal
	 */
	export interface CSet<T> {
		forEach(callbackfn: (value: T, value2: T, set: CSet<T>) => void, thisArg?: any): void;
		has(value: T): boolean;
		readonly size: number;
		add(value: T): this;
		clear(): void;
		delete(value: T): boolean;
	}

	export interface CWeakSet<T> {
		has(value: T): boolean;
		add(value: T): this;
		delete(value: T): boolean;
	}

	/**
	 * @internal
	 */
	export namespace CSet {
		/**
		 * @internal
		 */
		export function _isCSet(e: any): e is CSet<any> {
			if (_ECMA._collection) {
				return e instanceof Set;
			} else {
				return e instanceof CShimSet;
			}
		}

		export function _shallowCopy<E>(set: CSet<E>): CSet<E> {
			if (_ECMA._iterable) {
				return new Set(set as Set<E>);
			}
			else {
				let result = new CShimSet<E>();
				set.forEach(e => result.add(e));
				return result;
			}
		}
	}

	/**
	 * Cleopatra 순서 보장 맵 인터페이스 입니다.
	 * 기존 ObjectMap과 동일한 인터페이스를 사용합니다.
	 * 
	 * @internal
	 */
	export interface COrderedMap<K, V> {
		indexOfKey(key: K): number;
		constainsKey(key: K): boolean;
		get(key: K): V;
		getEntry(index: number): { key: K; value: V; };
		keys(): K[];
		findKey(finder: (child: K) => boolean): K;
		values(): V[];
		findValue(finder: (child: V) => boolean): V;
		put(key: K, value: V): void;
		insert(index: number, key: K, value: V): void;
		size(): number;
		remove(key: K): { key: K; value: V; };
		replace(oldKey: K, newKey: K, newValue: V): { key: K; value: V; };
		removeAll(): void;
		toArray(): { key: K; value: V; }[];
		forEach(func: (key: K, value: V, index: number) => void): void;
		findEntry(func: (key: K, value: V, index: number) => boolean): { key: K; value: V; };
		isEmpty(): boolean;
	}


	export interface CStack<E> {
		push(element: E): void;
		pop(): E;
		peek(): E;
		isEmpty(): boolean;
	}

	export function _createStack<E>(): CStack<E> {
		return new StackImpl();
	}

	/**
	 * ECMA 네이티브 Set를 사용할 수 없는 경우 사용되는 {@link CSet}입니다.
	 * @internal
	 */
	class CShimSet<T> implements CSet<T> {
		_map: CMap<T, T>;

		constructor() {
			this._map = new CShimMap<T, T>();
		}

		add(value: T): this {
			if (!this._map.has(value)) {
				this._map.set(value, value);
			}

			return this;
		}

		clear(): void {
			this._map.clear();
		}

		delete(value: T): boolean {
			return this._map.delete(value);
		}

		forEach(callbackfn: (value: T, value2: T, set: CSet<T>) => void, thisArg?: any): void {
			this._map.forEach((value, key) => {
				callbackfn(value, key, this);
			});
		}

		has(value: T): boolean {
			return this._map.has(value);
		}

		get size(): number {
			return this._map.size;
		}
	}

	/**
	 * @internal
	 */
	class CShimWeakSet<T extends object> implements CWeakSet<T> {
		_map: CWeakMap<T, boolean>;

		constructor() {
			this._map = new CShimWeakMap();
		}

		add(value: T): this {
			if (!this._map.has(value)) {
				this._map.set(value, true);
			}

			return this;
		}

		delete(value: T): boolean {
			return this._map.delete(value);
		}

		has(value: T): boolean {
			return this._map.has(value);
		}
	}

	/**
	 * 네이티브 맵이 지원되는 환경에서 {@link utils.ObjectMap}이 좀더 효율적으로 작동되도록 합니다.
	 * 
	 * @internal
	 */
	class FastObjectMap<K, V> implements COrderedMap<K, V> {
		private _map: Map<K, V>;
		private _keyOrder: K[];

		constructor() {
			this._map = new Map();
			this._keyOrder = [];
		}

		indexOfKey(key: K): number {
			if (this._map.has(key)) {
				return this._keyOrder.indexOf(key);
			} else {
				return - 1;
			}
		}

		constainsKey(key: K): boolean {
			return this._map.has(key);
		}

		get(key: K): V {
			return this._map.get(key);
		}

		getEntry(index: number): { key: K; value: V; } {
			let key = this._keyOrder[index];
			return {
				key,
				value: this._map.get(key)
			}
		}

		keys(): K[] {
			return _shallowCopyArray(this._keyOrder)
		}

		findKey(finder: (child: K) => boolean): K {
			return this._keyOrder.find(key => finder(key));
		}

		values(): V[] {
			return this._keyOrder.map(key => {
				return this._map.get(key)
			});
		}

		findValue(finder: (child: V) => boolean): V {
			return _stream(this._keyOrder)
				.map(k => this._map.get(k))
				.filter(finder)
				.head();
		}

		put(key: K, value: V): void {
			if (!this._map.has(key)) {
				this._keyOrder.push(key);
			}
			this._map.set(key, value);
		}

		insert(index: number, key: K, value: V): void {
			index = Math.max(Math.min(this._keyOrder.length, index), 0);
			this._keyOrder.splice(index, 0, key);
			this._map.set(key, value);
		}

		size(): number {
			return this._keyOrder.length;
		}

		remove(key: K): { key: K; value: V; } {
			if (this._map.has(key)) {
				let idx = this.indexOfKey(key);

				let value = this._map.get(key);

				this._map.delete(key);
				this._keyOrder.splice(idx, 1);
				return {
					key, value
				};
			}
			else {
				return null;
			}
		}

		replace(oldKey: K, newKey: K, newValue: V): { key: K; value: V; } {
			if (this._map.has(oldKey)) {
				let idx = this.indexOfKey(oldKey);

				this._keyOrder[idx] = newKey
				let oldValue = this._map.get(oldKey);

				this._map.delete(oldKey);
				this._map.set(newKey, newValue);
				return {
					key: oldKey,
					value: oldValue
				};
			}

			else {
				return null;
			}
		}

		removeAll(): void {
			this._keyOrder = [];
			this._map.clear();
		}

		toArray(): { key: K; value: V; }[] {
			return this._keyOrder.map(key => {
				return {
					key,
					value: this._map.get(key)
				};
			});
		}

		forEach(func: (key: K, value: V, index: number) => void): void {
			this._keyOrder.forEach((key, idx) => {
				func(key, this._map.get(key), idx);
			});
		}

		findEntry(func: (key: K, value: V, index: number) => boolean): { key: K; value: V; } {
			let idx = 0;
			return _stream(this._keyOrder)
				.map(key => {
					let mapped = {
						key,
						value: this._map.get(key),
						index: idx
					};
					idx++;
					return mapped;
				})
				.find(e => {
					return func(e.key, e.value, e.index);
				});
		}

		isEmpty(): boolean {
			return this._keyOrder.length === 0;
		}
	}

	/**
	 * @internal
	 */
	class BiMapImpl<K, V> implements CBiMap<K, V> {
		private _oppositeMap: CBiMap<V, K>;

		private _map: CMap<K, V>;
		private _inverseMap: CMap<V, K>;

		constructor(orgin?: BiMapImpl<V, K>) {
			if (orgin) {
				this._oppositeMap = orgin;
				this._map = orgin._inverseMap;
				this._inverseMap = orgin._map;
			}
			else {
				this._map = _createMap();
				this._inverseMap = _createMap();
			}
		}

		get inversed(): CBiMap<V, K> {
			if (!this._oppositeMap) {
				this._oppositeMap = new BiMapImpl(this);
			}
			return this._oppositeMap;
		}

		clear(): void {
			this._map.clear();
			this._inverseMap.clear();
		}

		delete(key: K): boolean {
			if (!this._map.has(key)) {
				return false;
			}
			let value = this._map.get(key);

			this._map.delete(key);
			this._inverseMap.delete(value);
		}

		forEach(callbackfn: (value: V, key: K, map: CMap<K, V>) => void, thisArg?: any): void {
			this._map.forEach(callbackfn);
		}

		get(key: K): V | undefined {
			return this._map.get(key);
		}

		has(key: K): boolean {
			return this._map.has(key);
		}

		set(key: K, value: V): this {
			if (this._map.has(key)) {
				this.delete(key);
			}

			if (this._inverseMap.has(value)) {
				throw new exceptions.IllegalArgumentException(`keys ans values are must be unique in BiMap.`);
			}

			this._map.set(key, value);
			this._inverseMap.set(value, key);
			return this;
		}

		public get size(): number {
			return this._map.size;
		}
	}

	/**
	 * @internal
	 */
	class StackImpl<E> implements CStack<E> {
		_arr: E[] = [];

		push(element: E): void {
			this._arr.push(element);
		}

		pop(): E {
			if (this._arr.length === 0) {
				throw new exceptions.IllegalStateException("No more elements are available.");
			}

			return this._arr.pop();
		}

		peek(): E {
			return this._arr[this._arr.length - 1] ?? null;
		}

		isEmpty(): boolean {
			return this._arr.length === 0;
		}
	}

	// Map 폴리필
	let _struct_uid_count = 0;

	/**
	 * 맵 또는 셋에서 사용할 객체의 식별자를 얻습니다.
	 * @param obj 식별자를 얻을 개체
	 * @returns 식별자
	 */
	function _uid_of(obj: any): string {
		let type = typeof obj;
		if (!!obj && type == "object") {
			if (typeof obj.uuid === "string") {
				return "uuid:" + obj.uuid;
			}

			if (typeof obj['__suid__'] !== 'string') {
				let suid = "suid:" + (_struct_uid_count++).toString(36);
				try {
					Object.defineProperty(obj, '__suid__', {
						value: suid,
						enumerable: false,
						writable: false,
						configurable: false
					});
				} catch (e) {
					obj['__suid__'] = suid;
					console.error(e);
				}
			}
			return obj['__suid__'];
		}
		// 키의 타입이 문자열인 경우 메모리 효율을 위해 그대로 사용한다.
		else if (typeof obj === "string") {
			return obj;
		}
		else {
			return `${type}://${obj}`
		}
	}

	type CShimEntry<K, V> = {
		key?: K,
		value: V
	};

	/**
	 * @internal
	 */
	abstract class CShimMapBase<K, V> {
		protected _entries: { [key: string]: CShimEntry<K, V> };
		protected _size: number = 0;

		constructor() {
			this._entries = {};
		}

		set(key: K, value: V): this {
			let hadKey = this.has(key);
			this._entries[_uid_of(key)] = this._createEntry(key, value);
			if (!hadKey) {
				this._size++;
			}
			return this;
		}

		get(key: K): V {
			if (this.has(key)) {
				return this._entries[_uid_of(key)].value;
			}
		}

		clear(): void {
			this._entries = {};
			this._size = 0;
		}

		delete(key: K): boolean {
			let hasKey = this.has(key);
			if (hasKey) {
				delete this._entries[_uid_of(key)];
				this._size--;
				return true;
			}
			return false;
		}

		has(key: K) {
			return !!this._entries[_uid_of(key)];
		}

		protected abstract _createEntry(key: K, value: V): { key?: K, value: V };

		get size(): number {
			return this._size;
		}
	}

	/**
	 * 이 API를 직접 사용하지 마십시오. {@link _createMap}을 통해 사용되어야 합니다.
	 * @internal
	 */
	class CShimWeakMap<K extends Object, V> extends CShimMapBase<K, V> implements CWeakMap<K, V> {
		set(key: K, value: V): this {
			if (typeof key !== 'object') {
				throw TypeError('Invalid value used as weak map key');
			}
			super.set(key, value);
			return this;
		}

		protected _createEntry(key: K, value: V): { key?: K; value: V; } {
			// 키를 기억 하지 않음.
			return { value };
		}
	}

	/**
	 * @internal
	 */
	class CShimMap<K, V> extends CShimMapBase<K, V> implements CMap<K, V> {
		protected override _createEntry(key: K, value: V): { key?: K, value: V } {
			return { key, value };
		}

		forEach(callback: (v?: V, k?: K, map?: CMap<K, V>) => void, thisArg?: any) {
			for (let suid in this._entries) {
				let key = this._entries[suid].key;
				let value = this._entries[suid].value;
				callback.call(thisArg, value, key, thisArg ?? this);
			}
		}

		clear(): void {
			this._entries = {};
			this._size = 0;
		}
	}
}

