namespace cpr.core {

	let instance: PolicyManager;

	export class PolicyManager {
		public static get INSTANCE(): PolicyManager {
			if (!instance) {
				instance = new PolicyManager();
			}
			return instance;
		}

		private _registry: CMap<string, any>;

		constructor() {
			this._registry = _createMap<string, any>();
		}

		/**
		 * 정책 초기 설정을 수행합니다.
		 * @param options 정책 구성 객체
		 */
		public configure(options: PolicyOptions): void {
			let keys: string[] = Object.keys(options);
			keys.forEach(key => this._registry.set(key, options[key]));
		}

		/**
		 * 
		 * @private
		 */
		public _resolve(key: keyof PolicyOptions, ...args: any[]): any {
			let policy = this._registry.get(key);
			if (typeof policy === 'function') return policy(...args);
			return policy !== undefined ? policy : args[0];
		}

		/**
		 * @private
		 */
		public _isConfigured(key: keyof PolicyOptions): boolean {
			return this._registry.has(key);
		}
	}

}