/// <reference path="../expression/ExpressionEngine.ts"/>
/// <reference path="../utils/ParamUtil.ts"/>
namespace cpr.ufc {
	export interface TextStyle {
		/**
		 * 텍스트에 적용될 CSS 클래스들.
		 */
		classNames?: string[]

		/**
		 * 텍스트에 적용될 인라인 스타일 룰셋.
		 */
		style?: CSSStyleDeclaration
	}

	function _isEmptyOrNullString(text: string) {
		return text == null || text.length == 0;
	}

	function _isEmptyStyle(style: TextStyle) {
		if (style == null) {
			return true;
		}

		if (!utils.Util.isNullOrEmpty(style.classNames)) {
			return false;
		}

		if (style == null) {
			return true;
		}

		let hasExplicitProperty = _stream(Object.keys(style.style)).exists(prop => {
			return utils.Util.isNullOrEmpty(style.style[prop]) === false;
		});

		return !hasExplicitProperty;
	}

	class StyleRange {
		_range: foundation.CharRange;
		_style: TextStyle;

		constructor(range: foundation.CharRange, style: TextStyle) {
			this._range = range;
			this._style = style;
		}

		get range() { return this._range; }
		get textStyle() { return this._style; }

		_getTranslated(delta: number): StyleRange {
			let newRange = new foundation.CharRange(this._range.offset + delta, this._range.length);
			return new StyleRange(newRange, this._style);
		}
	}

	function stringify(obj: any): string {
		switch (typeof obj) {
			case "object": {
				if (obj instanceof StyledString) {
					return obj.toString();
				}
				else if (obj == null) {
					return "";
				}
				else {
					return String(obj);
				}
			}
			case "undefined": return "";
			default: return String(obj);
		}
	}

	/**
	 * 스타일이 적용된 텍스트를 추상화 하는 클래스.
	 */
	export class StyledString {
		/**
		 * 텍스트 표현 대상이 빈 문자열이거나 널인지 여부를 반환합니다.
		 * @param obj 텍스트 데이터. 일반적으로 문자열 또는 StyledString
		 * @returns 빈 문자열이거나 널인지 여부
		 */
		static _isNullOrEmpty(obj: string | StyledString): boolean {
			if (obj == null) {
				return true
			}
			else if (obj instanceof StyledString) {
				return obj.isEmpty();
			}
			else {
				return stringify(obj).length == 0
			}
		}

		/**
		 * 임의의 객체를 일반적인 문자열 형태로 확보합니다.
		 * @param obj 문자열 형태로 얻을 개체.
		 * @returns 해당 개체의 문자열 표현식.
		 */
		static _asString(obj: string | StyledString): string {
			return stringify(obj);
		}

		/**
		 * 주어진 개체를 ufc 텍스트 노드 배열 형태로 확보합니다.
		 * StyledString인 경우, 각 스타일 영역으로 세그먼트화된 셰이프 배열이 반환되며 그 밖의 경우 문자열 배열 형태로 반환 됩니다.
		 * @param obj 텍스트 값을 나타내는 개체.
		 * @returns ufc 텍스트 노드 배열.
		 */
		static _asShape(obj: string | StyledString): (string | ufc.ElementShape)[] {
			if (obj instanceof StyledString) {
				return obj._asShape();
			}
			else {
				return [stringify(obj)].filter(it => {
					return it != null && it.length > 0;
				});
			}
		}

		_plainText: string = "";
		_ranges: StyleRange[] = [];

		/**
		 * 빈 스타일 문자열을 만듭니다.
		 */
		constructor();

		/** 
		 * 초기 텍스트를 가진 스타일 문자열을 만듭니다.
		 * @param plainText 초기 문자열.
		 */
		constructor(plainText: string);

		/**
		 * 텍스트 및 스타일로 문자열을 만듭니다.
		 * @param plainText 텍스트.
		 * @param style 스타일.
		 */
		constructor(plainText: string, style: TextStyle);

		/**
		 * 다른 스타일 문자열의 사본을 만듭니다.
		 * @param styledString 원본 스타일 문자열.
		 */
		constructor(styledString: StyledString);

		constructor(...args: any[]) {
			switch (args.length) {
				case 1:
					this.append(args[0]);
					break;

				case 2:
					this.append(args[0], args[1]);
					break;
			}
		}

		/**
		 * 문자열 앞부분에 문자열을 넣습니다.
		 * @param text 끼워 넣을 문자열.
		 * @param style 해당 문자열에 적용될 스타일.
		 */
		prepend(text: string, style?: TextStyle): StyledString;

		/**
		 * 앞 부분에 다른 스타일 문자열을 끼워 넣습니다.
		 * @param styledString 끼워 넣을 스타일 문자열.
		 */
		prepend(styledString: StyledString): StyledString;
		prepend() {
			let args = _toArray(arguments);
			if (utils.ParamUtil._matchArgs(args, [StyledString])) {
				this._prependStyledString(args[0] as StyledString);
			}
			else {
				this._prependText(String(args[0]), args[1] as TextStyle);
			}
			return this;
		}

		_prependText(text: string, style?: TextStyle) {
			if (_isEmptyOrNullString(text)) {
				return;
			}
			let delta = text.length;
			this._plainText = text + this._plainText;

			this._ranges = this._ranges.map(it => it._getTranslated(delta));

			if (!_isEmptyStyle(style)) {
				let newRange = new StyleRange(new foundation.CharRange(0, text.length), style);
				this._ranges.unshift(newRange);
			}
		}

		_prependStyledString(styledString: StyledString) {
			if (styledString == null || styledString.isEmpty()) {
				return;
			}

			let delta = styledString.toString().length;
			let translatedRanges = this._ranges.map(it => it._getTranslated(delta));
			this._ranges = styledString._ranges.concat(translatedRanges);
			this._plainText = styledString.toString() + this._plainText;
		}

		/**
		 * 끝 부분에 텍스트를 추가합니다.
		 * @param text 추가할 텍스트.
		 * @param style 추가될 부분에 적용될 스타일.
		 */
		append(text: string, style?: TextStyle): StyledString;

		/**
		 * 끝 부분에 다른 스타일 문자열을 추가합니다.
		 * @param styledString 추가할 스타일 문자열.
		 */
		append(styledString: StyledString): StyledString;
		append() {
			let args = _toArray(arguments);

			if (utils.ParamUtil._matchArgs(args, [StyledString])) {
				this._appendStyledString(args[0] as StyledString)
			}
			else {
				this._appendText(String(args[0]), args[1] as TextStyle);
			}

			return this;
		}

		_appendText(text: string, style?: TextStyle) {
			if (_isEmptyOrNullString(text) && _isEmptyStyle(style)) {
				return;
			}

			let offset = this._plainText.length;
			this._plainText += text;

			if (!_isEmptyStyle(style)) {
				let range = new foundation.CharRange(offset, text.length);
				this._ranges.push(new StyleRange(range, style));
			}
		}

		_appendStyledString(styledString: StyledString) {
			if (styledString == null || styledString.isEmpty()) {
				return;
			}
			let delta = this._plainText.length;
			this._ranges = this._ranges.concat(styledString._ranges.map(it => it._getTranslated(delta)));
			this._plainText += styledString.toString();
		}

		toString(): string {
			return this._plainText;
		}

		valueOf(): string {
			return this._plainText;
		}

		/**
		 * @returns 빈 스타일 문자열인지 여부.
		 */
		isEmpty(): boolean {
			return _isEmptyOrNullString(this._plainText) && utils.Util.isNullOrEmpty(this._ranges);
		}

		_asShape(): (string | ufc.ElementShape)[] {
			let result: (string | ufc.ElementShape)[] = [];
			if (this.isEmpty()) {
				return result;
			}

			let knownIndex = 0;
			let consumeTo: (endIndex: number) => string = endIndex => {
				let result = this._plainText.substring(knownIndex, endIndex);
				knownIndex = endIndex;
				return result;
			};
			for (let each of this._ranges) {
				if (knownIndex < each.range.offset) {
					result.push(consumeTo(each.range.offset));
				}

				let shape: ufc.ElementShape = {
					tag: "span",
					children: [consumeTo(each.range.end)]
				};
				if (utils.Util.isNullOrEmpty(each.textStyle.classNames) == false) {
					shape.classNames = each.textStyle.classNames;
				}
				if (each.textStyle.style) {
					shape.style = each.textStyle.style as any;
				}

				result.push(shape);
			}

			if (knownIndex < this._plainText.length) {
				result.push(consumeTo(this._plainText.length));
			}

			return result;
		}

		_asHTML(): string {
			if (this.isEmpty()) {
				return "";
			}
			let result: string[] = [];

			let knownIndex = 0;
			let consumeTo: (endIndex: number) => string = endIndex => {
				let subtext = this._plainText.substring(knownIndex, endIndex);
				knownIndex = endIndex;
				return subtext;
			};
			for (let each of this._ranges) {
				if (knownIndex < each.range.offset) {
					result.push(utils.HTMLEncoder.encodeForHTML(consumeTo(each.range.offset)));
				}

				result.push("<span");
				if (utils.Util.isNullOrEmpty(each.textStyle.classNames) == false) {
					result.push(' class="');
					result.push(utils.HTMLEncoder.encodeForHTMLAttribute(each.textStyle.classNames.join(" ")));
					result.push('"');
				}
				if (each.textStyle.style) {
					let styles = _createCSSArray(each.textStyle.style as any);
					let styleText = _joinCSSArray(styles);
					result.push(' style="');
					result.push(utils.HTMLEncoder.encodeForHTMLAttribute(styleText));
					result.push('"');
				}
				result.push(">");
				result.push(utils.HTMLEncoder.encodeForHTML(consumeTo(each.range.end)));
				result.push("</span>");
			}

			if (knownIndex < this._plainText.length) {
				result.push(utils.HTMLEncoder.encodeForHTML(consumeTo(this._plainText.length)));
			}

			return result.join("");
		}

		/**
		 * 
		 * @returns 스타일 문자열 사본을 얻습니다.
		 */
		getCopy(): StyledString {
			let result = new StyledString();
			result.append(this);
			return result;
		}
	}

	expression.ExpressionEngine.INSTANCE._registerBuiltInFunction("sstr", (text: string, ...rest: any[]) => {
		let textStyle: TextStyle = {
			classNames: [],
			style: {} as CSSStyleDeclaration
		};

		function appendClass(array: any[]) {
			if (array instanceof Array === false) {
				return;
			}

			let newClassNames = array.filter(it => {
				return typeof it == "string";
			}).map((it: string) => {
				return it.split(/\s+/g);
			})
				.reduce((a, b) => a.concat(b.filter(it => a.indexOf(it) === -1))) || [];
			textStyle.classNames = textStyle.classNames.concat(newClassNames);
		}

		rest.forEach((eachParam, idx) => {
			if (typeof eachParam == "string") {
				appendClass([eachParam]);
			}
			else if (eachParam instanceof Array) {
				appendClass(eachParam);
			}
			else if (typeof eachParam == "object" && eachParam != null) {
				Object.keys(eachParam).forEach(key => {
					let value = eachParam[key];
					switch (key) {
						case "classNames":
							appendClass(value)
							break;

						default:
							if (typeof value == "string") {
								textStyle.style[key] = value;
							}
							break;
					}
				})
			}
		});

		return new StyledString(stringify(text), textStyle);
	});

	expression.ExpressionEngine.INSTANCE._registerOperator({
		type: StyledString,
		operator: "+",
		allowedOperandTypes: ["string", "number", "boolean", null],
		reducer(a: any, b: any) {
			if (a instanceof StyledString && b instanceof StyledString) {
				let result = new StyledString();
				result.append(a);
				result.append(b);
				return result;
			}
			else if (a instanceof StyledString) {
				let result = new StyledString();
				result.append(a);
				result.append(stringify(b));
				return result;
			}
			else if (b instanceof StyledString) {
				let result = new StyledString();
				result.append(stringify(a));
				result.append(b);
				return result;
			}
			else {
				// 도달하지 않음.
				return a + b;
			}
		}
	});
}