

namespace cpr.controls.internal {

	/**
	 * @private
	 */
	export class NativeHScrollbar implements IVirtualHScrollbar {
		private _scrollPane: internal.IVirtualScrollPane;
		private _passiveScrollLeft: number = -1;


		constructor(scrollPane: internal.IVirtualScrollPane) {
			this._scrollPane = scrollPane;
		}

		public _getHeight(): number {
			return internal.ScrollbarUtil._getNativeScrollWidth();
		}

		public _getScrollLeft(): number {
			let scrollElement: HTMLElement = this._scrollPane._getRenderer().getNamedNode(this._scrollPane._getQName("hscroll"));
			if (scrollElement) {
				return scrollElement.scrollLeft;
			}
			return -1;
		}

		public _setScrollLeft(scrollLeft: number): void {
			let scrollElement: HTMLElement = this._scrollPane._getRenderer().getNamedNode(this._scrollPane._getQName("hscroll"));
			if (scrollElement && scrollElement.scrollLeft != scrollLeft) {
				scrollElement.scrollLeft = scrollLeft;
			}
			this._passiveScrollLeft = scrollLeft;
		}

		public _createScrollbar(contentScrollLeft: number, contentWidth: number): ufc.ElementShape {
			let hScrollViewPort: ufc.ControlShape = {
				tag: "div",
				attr: {},
				style: {
					width: contentWidth + "px",
					height: "1px"
				},
				innerHTML: "&nbsp;" // mobile safari에서 불특정한 경우에 영역이 할당되지 못하는 문제 때문에 빈값을 넣어 줌
			};

			// IE에서 ScrollBar에 BackgroundColor를 설정했을 때 ScrollBar가 보이지 않아 relative로 감쌈.
			let hScroll: ufc.ControlShape = {
				tag: "div",
				attr: {},
				classNames: [controls.gridpart.GridStyle.BLANK, "cl-hscrollbar"],
				style: {
					"box-sizing": "border-box",
					"overflow-X": "hidden",
					"overflow-Y": "hidden",
					position: "absolute",
					bottom: "0px",
					left: "0px",
					height: ScrollbarUtil._getNativeScrollWidth() + "px"
				},
				children: [{
					tag: "div",
					attr: {},
					nodename: this._scrollPane._getQName("hscroll"),
					classNames: internal.ScrollbarUtil._getScrollPaneClasses(),
					style: {
						"box-sizing": "content-box",
						"overflow-X": "scroll",
						"overflow-Y": "hidden",
						position: "relative",
						width: "100%",
						height: "100%"
					},
					mandatoryEvents: {
						scroll: _.throttle((e: events.CUIEvent) => { this._onVirtualHScroll(e); }, 50, { leading: false }) // throttling 적용
					},
					children: [hScrollViewPort]
				}]
			};

			return hScroll;
		}
		// event handlers
		private _onVirtualHScroll(e: events.CUIEvent): void {
			let target: HTMLElement = <HTMLElement>e.target;
			let scrollLeft: number = target.scrollLeft;

			// Chrome에서 화면 배율을 90%, 125% 등 으로 했을 때(그 이하라도) scrollposition이 소수점으로 넘어옴(20200213)
			if (this._passiveScrollLeft === -1 || gridpart.GridUtil._equalsApproximately(this._passiveScrollLeft, scrollLeft) == false) {
				this._passiveScrollLeft = -1;
				this._scrollPane._setScrollLeft(e, scrollLeft);
			}
		}
	}
}