/// <reference path="./AbstractHorizontalBar.ts" />
namespace cpr.controls.navigation {

	/**
	 * @private
	 */
	export class HorizontalBar extends AbstractHorizontalBar {
		private _menu: menu.IMenu = null;

		constructor(owner: NavigationBar, binder: provider.MenuDataBinder) {
			super(owner, binder)
			this._menu = this._initMenu();
		}

		/* shape */
		public _createShape(): cpr.ufc.ControlShape {

			let rootItems = this._getRootItems(true);
			let selectedValues = [];
			if (this._owner.values.length > 0) {
				let findItem = this._binder.findTreeItem(this._owner.values[0], rootItems) as MenuItem;
				while (findItem) {
					selectedValues.push(findItem.value);
					findItem = findItem.parentItem as MenuItem;
				}
			}

			let prevButton: ufc.ElementShape = this._owner._getRenderer()._getNamedShape(ufc.NodeNames.ITEMS_SCROLL_LEFT);
			if (!prevButton) {
				prevButton = {
					tag: "div",
					classNames: ["cl-navigationbar-prev"],
					style: {
						display: "none",
					},
					nodename: ufc.NodeNames.ITEMS_SCROLL_LEFT
				}
			}

			let bar = this._createBar(rootItems, selectedValues);
			let barWrapper = {
				tag: "div",
				style: {
					overflow: "hidden"
				},
				children: [bar],
				nodename: ufc.NodeNames.ITEMS_SCROLLER
			}

			let nextButton: ufc.ElementShape = this._owner._getRenderer()._getNamedShape(ufc.NodeNames.ITEMS_SCROLL_RIGHT);
			if (!nextButton) {
				nextButton = {
					tag: "div",
					classNames: ["cl-navigationbar-next"],
					style: {
						display: "none",
					},
					nodename: ufc.NodeNames.ITEMS_SCROLL_RIGHT
				}
			}

			let scrollableBarChildren = [];
			let scrollBarColumns = [];
			switch (this._owner.barScrollButtonPosition) {
				case NavigationBarScrollButtonPosition.none:
				case NavigationBarScrollButtonPosition.both: {
					prevButton.classNames.push("cl-position-both");
					nextButton.classNames.push("cl-position-both");
					scrollableBarChildren = [prevButton, barWrapper, nextButton];
					scrollBarColumns = ["auto", "1fr", "auto"];
					break;
				}
				case NavigationBarScrollButtonPosition.left: {
					prevButton.classNames.push("cl-position-left");
					nextButton.classNames.push("cl-position-left");
					scrollableBarChildren = [prevButton, nextButton, barWrapper];
					scrollBarColumns = ["auto", "auto", "1fr"];
					break;
				}
				case NavigationBarScrollButtonPosition.right: {
					prevButton.classNames.push("cl-position-right");
					nextButton.classNames.push("cl-position-right");
					scrollableBarChildren = [barWrapper, prevButton, nextButton];
					scrollBarColumns = ["1fr", "auto", "auto"];
					break;
				}
			}
			scrollableBarChildren.forEach((each: ufc.ElementShape, index) => {
				layouts.GridLayoutCSSBuilder._forCell()._withColumnStart(index + 1)._withRowStart(1)._commit(each.style);
			});

			let global = this._createPopupMenu();

			let scrollableBar: cpr.ufc.ElementShape = {
				tag: "div",
				classNames: [ufc.Classes.UNSELECTABLE],
				attr: {},
				style: {
					height: "100%",
					width: "100%"
				},
				children: scrollableBarChildren.concat([_createTapLazyTask({
					task: () => {
						this._checkScrollBtn()
					}
				})]),
				events: {
					wheel: (e: events.CWheelEvent) => { this._onwheel(e) }
				}
			}

			layouts.GridCSSBuilder._forLayout()._withTemplateColumns(scrollBarColumns)._withTemplateRows("1fr")._commit(scrollableBar.style);

			let shape: cpr.ufc.ControlShape = {
				tag: "div",
				attr: {
					role: "menubar",
					tabindex: "-1"
				},
				classNames: [],
				style: {
					//overflow:hidden하면은 서브 메뉴가 안보임.
					// position: "relative" 컨트롤의 포지션은 레이아웃 매니저가 결정해야 함!
				},
				styler: "root",
				aria: "root",
				eventTargets: [
					ufc.EventTargetType.UICONTROL,
					ufc.EventTargetType.DROPPABLE
				],
				events: {
					keydown: (e: events.CKeyboardEvent) => { this._onkeydown(e) },
					mousedown: (e: events.CMouseEvent) => { this._onmousedown(e) },
					touchstart: (e: events.CTouchEvent) => { this._ontouchstart(e) },
					mouseover: (e: events.CMouseEvent) => { this._onmouseover(e) },
					mouseout: (e: events.CMouseEvent) => { this._onmouseout(e) },
					click: (e: events.CMouseEvent) => { this._onclick(e) },
					resize: (e: events.CUIEvent) => { this._onResize(e) }
				},
				children: [scrollableBar],
				nodename: "navigationbar"
			}

			cpr.ufc.ShapeUtil._setAriaLabelAttr(shape.attr, this._owner._getFieldLabel());
			cpr.ufc.ShapeUtil._setTooltipAttr(shape, { owner: this._owner, title: this._owner.tooltip });

			if (this._getHoveredItem() != null) {
				shape.attr['aria-activedescendant'] = this._getActivedescendant();
			}

			if (global) {
				shape.classNames.push(ufc.Classes.OPENED);
				shape["global"] = global;
			}

			if (this._owner.expandTrigger == ExpandTriggerType.hover) {
				shape.events["mouseenter"] = (e: events.CMouseEvent) => { this._onmouseenter(e) };
				shape.events['mouseleave'] = (e: events.CMouseEvent) => { this._onmouseleave(e) };
			}

			cpr.ufc.ShapeUtil._setAriaDisabled(shape, this._owner.enabled && !this._owner.readOnly);
			if (!this._owner.enabled) {
				delete shape.attr['tabindex'];
			}
			let autoSizeType = this._owner._getAutoSizingTypeOfConstraint();

			if (this._owner.barItemWidths == NavigationBarItemWidths.equal && autoSizeType != layouts.AutoSizeType.both && autoSizeType != layouts.AutoSizeType.width) {
				shape.classNames.push("cl-equalwidths");
			}
			return shape;
		}

		protected _createPopupMenu(): ufc.ElementShape {

			let items = this._getMenuItems();
			if (items.length == 0) {
				return;
			}

			let menu = this._getActiveMenu();
			let submenu = this._createMenu(menu, items);
			let global: ufc.ElementShape = {
				tag: "div",
				// global 설정 시 control 내부로 속할 수 있도록 "cl-control" 클래스를 별도로 추가. 2018.01.08 배소영
				classNames: ["cl-control", "cl-navigationbar-visible", "cl-navigationbar-" + this._owner.menuType, ufc.Classes.BOTTOM],
				style: {
					position: "absolute",
					left: "-1000px",
					top: "-1000px"
				},
				children: [submenu],
				nodename: menu.getRootNodeName(),
				events: {
					mousedown: (e: events.CMouseEvent) => { this._onMenuMousedown(e) },
					blur: (e: events.CFocusEvent) => { this._onblur(e) }
				},
			};
			if (this._isHiddenMenu()) {
				global.style["opacity"] = "0";
				global.style["pointer-events"] = "none";
			}
			return global;
		}

		protected _createBar(items: MenuItem[], selectedValues: string[]): ufc.ElementShape {

			let itemShapes: cpr.ufc.ElementShape[] = [];

			items.forEach((each: MenuItem, index: number) => {

				if (index > 0 && this._owner.barItemSpacing) { // barItemSpacing
					let spacingShape = {
						tag: "div",
						style: {
							"min-width": this._owner.barItemSpacing + "px",
							width: this._owner.barItemSpacing + "px",
							display: "table-cell"
						}
					}
					itemShapes.push(spacingShape);
				}

				let item = this._createItem(each, selectedValues.indexOf(each.value) > -1, index);
				item.style["display"] = "table-cell";
				item.style["vertical-align"] = "middle";
				item.style["overflow"] = "hidden";

				itemShapes.push(item);
			});

			let barShape: cpr.ufc.ElementShape = {
				tag: "div",
				attr: {
					"data-menutype": this._owner.menuType
				},
				classNames: [],
				style: {
					display: "table",
					height: "100%"
				},
				nodename: ufc.NodeNames.ITEMS_PANE,
				styler: "bar",
				children: itemShapes
			}

			return barShape;
		}

		protected _createItem(item: MenuItem, isSelected: boolean, index: number): ufc.ElementShape {
			let isHoveredItem = this._isHoveredItem(item);
			let doOpenItem = this._isOpened(item) == true;
			let hasText = item.accessKey != "" || item.label != "";
			let displayLabel = this._binder._computeItemDisplayLabel(item);
			let isItemEnabled = this._owner.getItemEnable(item);

			let content: cpr.ufc.ElementShape = {
				tag: "div",
				attr: {},
				style: {},
				classNames: ["cl-navigationbar-content"],
				children: []
			};

			let itemShape: cpr.ufc.ElementShape = {
				tag: "div",
				styler: "item",
				style: {},
				bindContext: item.toExpressionContext(this._owner),
				aria: "item",
				classNames: [],
				attr: {
					"data-role": "menuitem",
					role: "menuitem", // 웹표준 검사기에서 aria-expanded를 사용할 수 있는 role로 교체. 스크린 리더는 menuitemradio를 읽지못함.
					"data-itemid": item.value,
					"data-itemidx": index + "",
					id: this._getMenuItemId(item),
					"aria-label": cpr.ufc.ShapeUtil._getValidAriaLabelAttr(ufc.StyledString._asString(displayLabel))
				},
				children: [content],
				nodename: this._getItemNodeName(index)
			}

			cpr.ufc.ShapeUtil._setTooltipAttr(itemShape, { owner: this._owner, title: item.tooltip, id: item.value });
			cpr.ufc.ShapeUtil._setAriaDisabled(itemShape, this._owner.enabled && isItemEnabled && !this._owner.readOnly);

			if (item.icon != null && item.icon != "") {
				let iconShape: cpr.ufc.ElementShape = this._createItemIcon(item);
				iconShape.style["height"] = "auto";
				layouts.FlexCSSBuilder._forCell()._withCellConstraint(0, 0, "auto")._withVerticalAlign(hasText ? layouts.FlexCellAlign.stretch : layouts.FlexCellAlign.baseline)._commit(iconShape.style);
				content.children.push(iconShape);
			}

			let textShape: cpr.ufc.ElementShape = this._createItemText(item);
			layouts.FlexCellCSSBuilder._forCell()._withCellConstraint(1, 1, "auto")._withVerticalAlign(layouts.FlexCellAlign.baseline)._commit(textShape.style);
			content.children.push(textShape);

			if (item.accessKey) {
				let accessKeyShape = this._createItemAccessKey(item);
				layouts.FlexCellCSSBuilder._forCell()._withCellConstraint(0, 0, "auto")._withVerticalAlign(layouts.FlexCellAlign.baseline)._commit(accessKeyShape.style);
				content.children.push(accessKeyShape);
				itemShape.attr["aria-keyshortcuts"] = item.accessKey;
			}

			let hasChild = item._hasChild();
			if (hasChild) {
				itemShape.attr["aria-haspopup"] = "true";
				itemShape.attr["aria-expanded"] = "false";

				let arrowShape: cpr.ufc.ElementShape = this._createItemArrow();
				arrowShape.style["height"] = "auto";
				layouts.FlexCSSBuilder._forCell()._withCellConstraint(0, 0, "auto")._withVerticalAlign(hasText ? layouts.FlexCellAlign.stretch : layouts.FlexCellAlign.baseline)._commit(arrowShape.style);
				content.children.push(arrowShape);
			}

			layouts.FlexCellCSSBuilder._forLayout()._withInlineFlex()._commit(content.style);

			let autoSizeType = this._owner._getAutoSizingTypeOfConstraint();
			if (this._owner.barItemWidths == NavigationBarItemWidths.equal && autoSizeType != layouts.AutoSizeType.both && autoSizeType != layouts.AutoSizeType.width) {
				content.style["width"] = "100%";
			}

			if (isSelected) {
				itemShape.attr["aria-current"] = "page";
				itemShape.classNames.push(ufc.Classes.SELECTED);
			}
			if (isItemEnabled && this._owner.enabled) {
				if (isHoveredItem) {
					itemShape.classNames.push(ufc.Classes.HOVER);
				}
				if (hasChild && doOpenItem) {
					itemShape.attr["aria-expanded"] = "true";
					itemShape.classNames.push("cl-navigationbar-visible");
				}
			} else {
				itemShape.classNames.push(ufc.Classes.DISABLED);
			}

			let isNormalMenuType = this._owner.menuType == NavigationBarMenuType.menu;
			if (doOpenItem && isNormalMenuType) {
				itemShape["nodename"] = "hovered-bar-item"; // 서브메뉴("menu")에서 필요.
			}
			return itemShape;
		}

		protected _createItemText(item: MenuItem): cpr.ufc.ElementShape {
			let text = {
				tag: "div",
				style: {},
				classNames: ["cl-navigationbar-text", ufc.Classes.TEXT],
				attr: { "aria-hidden": "true" },
				children: ufc.StyledString._asShape(this._binder._computeItemDisplayLabel(item))
			}
			return text;
		}

		protected _createItemIcon(item: MenuItem): cpr.ufc.ElementShape {
			let iconShape: cpr.ufc.ElementShape = {
				tag: "div",
				style: {},
				attr: { "aria-hidden": "true" },
				classNames: ["cl-navigationbar-icon"],
				children: ["&nbsp;"]
			}
			iconShape.style['background-image'] = _quoteAsCSSURL(item.icon);
			return iconShape;
		}

		protected _createItemAccessKey(item: MenuItem): ufc.ElementShape {
			return {
				tag: "div",
				classNames: ["cl-navigationbar-accesskey", ufc.Classes.TEXT],
				attr: { "aria-hidden": "true" },
				style: {},
				children: [item.accessKey ? "(" + item.accessKey + ")" : ""]
			}
		}

		protected _createItemArrow(): ufc.ElementShape {
			let arrowIcon: cpr.ufc.ElementShape = {
				tag: "div",
				classNames: ["cl-navigationbar-arrow"],
				attr: { "aria-hidden": "true" },
				style: {},
				children: ["&nbsp;"]
			}
			if (this._owner.barArrowImage != "") {
				arrowIcon.style['background-image'] = _quoteAsCSSURL(this._owner.barArrowImage);
			}
			return arrowIcon;
		}

		//method
		protected _initMenu(): menu.IMenu {
			let menu: menu.IMenu = null;
			switch (this._owner.menuType) {
				case NavigationBarMenuType.menu: {
					menu = new cpr.controls.navigation.Menu(this._owner, "navigationbar", this._binder, { list: "list", item: "listitem" });
					break;
				}
				case NavigationBarMenuType.megamenu: {
					menu = new cpr.controls.navigation.MegaMenu(this._owner, "navigationbar", this._binder, { list: "list", item: "listitem" });
					break;
				}
				case NavigationBarMenuType.fullmenu: {
					menu = new cpr.controls.navigation.FullMenu(this._owner, "navigationbar", this._binder, { list: "list", item: "listitem" });
					break;
				}
			}

			if (menu) {
				menu.addEventListener("--internal-item-select", (e: events.CItemEvent) => { this._onMenuItemSelect(e) });
				menu.addEventListener(events.ItemEventType.ITEMCLICK, (e: events.CItemEvent) => { this._onMenuItemClick(e) });
				menu.addEventListener("--internal-item-selected", (e: events.CItemEvent) => { this._onMenuItemSelected(e) });
				menu.addEventListener("item-mouseover", (e: events.CItemEvent) => { this._onMenuItemMouseOver(e) })
				menu.addEventListener("menu-mouseleave", (e: events.CMouseEvent) => { this._onMenuMouseLeave(e) });
				menu.addEventListener("menu-mouseenter", (e: events.CMouseEvent) => { this._onMenuMouseEnter(e) });
				menu.addEventListener("menu-hidden-mouseleave", (e: events.CMouseEvent) => { this._onMenuHiddenMouseLeave(e) });
			}
			return menu;
		};

		protected _resetMenu() {
			let activeMenu = this._getActiveMenu();
			if (activeMenu) {
				activeMenu.init();
			}
		}

		protected _clearMenu() {
			let activeMenu = this._getActiveMenu();
			if (activeMenu) {
				activeMenu.dispose();
				this._menu = null;
			}
		}

		protected _getMenuItems(): MenuItem[] {
			let doOpenItem = this._getOpenedItem();
			if (doOpenItem == null || !this._isOpened(doOpenItem)) {
				return [];
			}
			return doOpenItem.children as MenuItem[];
		}

		/**
		 * 컨트롤에 포커스를 지정합니다.
		 */
		public focus(forward: boolean = true): boolean {

			if (!this._focusTrigger) this._focusTrigger = { type: "keyboard", forward: forward };
			return false;
		}

		public _focusPrevious(includeEntry?: boolean): boolean {
			return false;
		}

		public _focusNext(includeEntry?: boolean): boolean {
			return false;
		}

		public _onfocus(e: FocusEvent) {
			if (!this._focusTrigger) {
				this._focusTrigger = { type: "keyboard", forward: true }
			}
			if (this._focusTrigger.type == "mousedown" || this._focusTrigger.type == "touchend" || this._focusTrigger.type == "self") {
				this._focusTrigger = null;
				return;
			}
			this._initFocusItem(this._focusTrigger.forward);
			// DOM에 포커스를 주었을때 발생하는 스크롤 동작에 맞추어 redraw 되어야 글로벌 메뉴를 표시하지 않음.
			// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/7223
			this._focusTrigger = null;
		}

		protected _onAccessKey(item: MenuItem, e: events.CKeyboardEvent) {
			this._onItemSelect(item, e, (success: boolean) => {
				let rootItem = this._getTopParentItem(item);
				if (success) {
					if (this._close({ nativeEvent: e })) {
						this._setHoveredItem(rootItem, { preventOpen: true, nativeEvent: e });
					} else if (this._isOpened(rootItem)) {
						this._setHover(item, { nativeEvent: e })
					}
				}
			});
		}

		protected _onMenuItemSelect(e: events.CItemEvent) {
			let item: MenuItem = e.item;
			this._binder._select(item, this._binder.getMultiple());
		}
		protected _onMenuItemClick(e: events.CItemEvent) {
			this._owner.dispatchEvent(e);
		}
		protected _onMenuItemSelected(e: events.CItemEvent) {
			let item = e.item;
			if (this._close({ nativeEvent: e })) {
				this._setHoveredItem(this._getTopParentItem(item), { useSameCheck: false, preventOpen: true, nativeEvent: e, updateScroll: false });
			}
		}

		protected _onMenuMousedown(e: MouseEvent) {
			if (this._owner.focused == false) {
				let rootElement = e.currentTarget as HTMLElement;
				let eventElement = e.target as HTMLElement;
				let domTraverser: ufc.DOMTraverser = ufc._traverseFromElement(eventElement)._closest("[data-role='menuitem']", rootElement);
				let item = null;
				if (domTraverser) {
					item = this._getItemByElement(domTraverser._getElement())
				}
				if (item) {
					this._getActiveMenu().setHoveredItem(item, { updateScroll: false });
				}
				let focusableElement = this._getFocusableElement();
				if (focusableElement) {
					this._focusElement(focusableElement);
				}
			}
			e.preventDefault();
		}

		protected _getActivedescendant() {
			let hoveredItem = this._getHoveredItem();
			if (!hoveredItem) {
				return "";
			}
			let menu = this._getActiveMenu();
			let hoveredSubMenuItem = null;
			if (menu) {
				hoveredSubMenuItem = menu.getHoveredItem();
			}
			if (hoveredSubMenuItem) {
				return this._getMenuItemId(hoveredSubMenuItem);
			} else if (this._getHoveredItem()) {
				return this._getMenuItemId(this._getHoveredItem());
			}
			return "";
		}

		protected _createMenu(menu: menu.IMenu, children: MenuItem[]) {
			menu.setItems(children);
			return menu.createShape();
		}

		protected _getFocusableElement() {
			let domTraverser: ufc.DOMTraverser = ufc._traverseFromControl(this._owner);
			if (domTraverser) {
				domTraverser = domTraverser._find('[tabindex]');
				if (domTraverser) {
					return domTraverser._getElement();
				}
			}
			return null;
		}

		protected _getActiveMenu(): menu.IMenu {
			return this._menu;
		}

		protected _focusElement(ele: HTMLElement) {
			if (ele["setActive"]) {
				ele["setActive"]();// IE에서 포커스시 스크롤 이동 방지
			} else {
				ele.focus();
			}
		}

		/**
		 * 초점이 해제되었을 때 이벤트.
		 * blur > focus 이벤트 순서로 발생한다. relatedTarget는 document.activeElement로 확인한다.
		 * @param e 
		 */
		public override _onblur(e: events.CFocusEvent) {
			super._onblur(e);
			// 현재 브라우저 윈도우가 아닌 다른 윈도우에 초점이 이동되는 경우 자신에게 blur가 발생하고 relatedTarget가 자신으로 된다.
			let relatedTarget: HTMLElement = document.activeElement as HTMLElement; // 이미 포커스 대상에게 설정이 되어 있음
			let isOwnedElement = false;
			this._focusTrigger = null;
			let activeMenu = this._getActiveMenu();

			if (relatedTarget && relatedTarget != e.target) {
				let menuRootNode = activeMenu ? this._owner._getRenderer().getNamedNode(activeMenu.getRootNodeName()) : null;
				let rootNode = this._owner._getRenderer().getRootNode();
				if (rootNode == relatedTarget) {
					this._focusTrigger = { type: "self", forward: true };
				}
				if (rootNode && menuRootNode) {
					isOwnedElement = rootNode.contains(relatedTarget) || menuRootNode.contains(relatedTarget);
				}
			}
			if (!isOwnedElement) {
				// 내비게이션바의 엘리먼트가 아니라면 하위 메뉴를 닫는다.
				this._close({ nativeEvent: e });
				this._clearHoveredItem({ closeMenu: false });
				if (activeMenu) {
					activeMenu.init();
				}
			} else {
				// 하위 메뉴를 닫지 않고 내비게이션바에 포커스를 준다. IE에서 하위메뉴가 스크롤이 있는 경우 초점이 이동되는 현상으로 방지하는 코드.
				let focusableElement = this._getFocusableElement();
				if (focusableElement) {
					this._focusElement(focusableElement);
				}
			}
		}

		protected _initFocusItem(forward: boolean) {
			let hoveredItem = this._getHoveredItem();
			let items = this._getRootItems();

			if (hoveredItem != null || items.length == 0) {
				return;
			}
			let openedItem = this._getOpenedItem();
			if (openedItem) {
				let hoveredItem = this._getActiveMenu().getHoveredItem();
				if (hoveredItem) {
					return;
				}
			}

			let findIndex = -1;
			let delta = 1;
			if (this._owner.tabTraversal) {
				findIndex = forward ? -1 : items.length;
				delta = forward ? 1 : -1;
			}
			let len = items.length;
			let i = findIndex + delta;
			let nextItem = null;
			while (len > i || i < 0) {
				if (this._owner.getItemEnable(items[i])) {
					nextItem = items[i];
					i = len;
				} else {
					i = i + delta;
				}
			}
			this._focusItem(nextItem);
		}

		protected _getHover(): MenuItem {
			let menu = this._getActiveMenu();
			let hover = null;
			if (menu) {
				hover = menu.getHoveredItem();
			}
			let isOpenedMenuHover = hover && this._isOpened(this._getHoveredItem());
			if (!isOpenedMenuHover) {
				return this._getHoveredItem();
			}
			return hover;
		}

		public _setFocusedItem(item: MenuItem, options: { preventScroll: boolean } = { preventScroll: false }) {
			let topParentItem = this._getTopParentItem(item);
			if (options.preventScroll === false) {
				this._updateScrollByHover(topParentItem, this._hoveredItem);
			}
			this._hoveredItem = topParentItem;
			this._setOpen(topParentItem, { emitEvent: false });
			let menu = this._getActiveMenu();
			if (menu) {
				if (item && item.depth > 0) {
					menu.init();
					menu._setFocusedItem(item);
				} else {
					menu.init();
				}
			}
			this._owner.redraw();
		}

		protected _setHover(item: MenuItem, options: { doInitSubMenu?: boolean, useSameCheck?: boolean, nativeEvent?: Event } = {}) {
			_defaults(options, { useSameCheck: false, nativeEvent: null, doInitSubMenu: true });
			if (item == null || item.depth == 0) {
				this._setHoveredItem(item, { doInitSubMenu: options.doInitSubMenu, useSameCheck: options.useSameCheck, nativeEvent: options.nativeEvent });
			} else {
				let rootItem = this._getParent(item, (each) => {
					return each.depth == 0;
				});

				this._setHoveredItem(rootItem, { doInitSubMenu: options.doInitSubMenu, nativeEvent: options.nativeEvent });

				let menu = this._getActiveMenu();
				if (menu) {
					menu.setHoveredItem(item, { updateScroll: true });
				}
			}
		}

		protected _onmouseenter(e: MouseEvent) {
			let hoveredItem = this._getHoveredItem();
			let submenu = null;
			if (hoveredItem) {
				submenu = this._getActiveMenu();
			}
			if (!submenu) {
				return;
			}
			submenu.cancelTimeoutEvent(controls.menu.MenuTimeoutEventType.mouseleave);
			submenu._setHoveredItem(null);
		}

		protected override _navigateBar(e: events.CKeyboardEvent, item: MenuItem): void {
			super._navigateBar(e, item);
			let hoveredItem = this._getHoveredItem();
			let menu: menu.IMenu = null;
			if (hoveredItem) {
				menu = this._getActiveMenu();
			}
			let keyCode = e.keyCode;
			switch (keyCode) {

				case events.KeyCode.ENTER: {
					if (item == null) break;
					this._onItemSelect(item, e, (success: boolean) => {
						if (success) {
							if (this._close({ nativeEvent: e })) {
								this._resetMenu();
							}
						}
					});
					break;
				}
				case events.KeyCode.ESC: {
					if (item == null) break;
					if (item.depth > 0) {
						let traversedHover = menu._transferHoverUpCycle(item);
						if (!traversedHover) {
							this._resetMenu();
						}
					}
					break;
				}
			}
		}
	}
}