namespace cpr.controls.item {
	/**
	 * @private
	 */
	export abstract class AbstractItemListProvider<ControlType extends UIControl, ItemType extends Item, ItemSetConfigType extends ItemSetConfig, FilterType extends ItemFilter> implements BaseItemListProvider<ItemType, ItemSetConfigType> {

		private _itemDataSource: ItemDataSource<ItemSetConfigType>;
		private _itemFilter: any;
		private _owner: ControlType;

		constructor(owner: ControlType) {
			this._owner = owner;
			this._itemFilter = this._createItemFilter();
			this._itemDataSource = new ItemDataSource<ItemSetConfigType>(owner);
		}

		protected _getOwner(): ControlType {
			return this._owner;
		}

		protected _getItemFilter(): FilterType {
			return this._itemFilter;
		}

		/**
		 * 아이템의 데이터 소스를 반환합니다.
		 * @returns 아이템 데이터 소스
		*/
		public getItemDataSource(): ItemDataSource<ItemSetConfigType> {
			return this._itemDataSource;
		}

		protected abstract _createItemFilter(): FilterType

		/**
		 * 드롭다운타입에 따른 활성 아이템 리스트 뷰를 반환합니다.
		 * @returns 
		 */
		public abstract getActiveItemListView(): IItemListView<ItemType>

		/**
		 * 드롭다운타입에 따른 활성 아이템 리스트를 반환합니다.
		 * @returns 
		 */
		public abstract getActiveItemList(): IItemList<ItemType>
		/**
		 * 리소스를 해제합니다.
		 */
		public dispose(): void {
			this._itemDataSource?.dispose();
			this._itemDataSource = null;
			this._itemFilter?.dispose();
			this._itemFilter = null;
			this._owner = null;
		}
	}
}