namespace cpr {
	let UUID_SEQUENCE = 0;

	export function _generateUUID(): string {
		return (UUID_SEQUENCE++).toString(36);
	}

	/**
	 * 대소문자로 구분된 단어(카멜)을 대시로 구분된 단어 형태로 변환 합니다.
	 * eg. border-spacing → borderSpacing
	 * @param camelExp 카멜 표현.
	 * @returns 대시 표현.
	 */
	export function _camelToDash(camelExp: string): string {
		return camelExp.replace(/([a-z])([A-Z])/g, '$1-$2').toLowerCase();
	}

	/**
	 * 대시로 구분된 단어들을 카멜 표현식으로 변형 합니다.
	 * eg. border-spacing → borderSpacing
	 * @param dashExp 대시 표현.
	 * @returns 카멜 표현.
	 */
	export function _dashToCamel(dashExp: string): string {
		return dashExp.toLowerCase().replace(/([-][a-z])/g, (match) => match[1].toUpperCase());
	}


	/**
	 * css selector에서 실행 가능한 유효 문자로 변경하는 메소드.
	 * 일반적으로 셀렉터 내부에 사용된 특수문자를 에스케이프 하는 용도로 사용 합니다.
	 */
	export const _CSSEscape: (ident: string) => string = typeof CSS != "undefined" && typeof CSS.escape == "function"
		// 표준 구현
		? CSS.escape
		// IE용 대체 구현
		// FIXME: 아이디가 숫자로 시작하는 것은 오류가 발생 unicode로 변경이 필요
		: (ident: string) => ident.replace(/([#\[\]\{\}\(\)\.\/])/g, "\\$1")
		;
}