/// <reference path="./OrderedLayout.ts"/>
/// <reference path="../UIControl.ts"/>
/// <reference path="./AutoSizeType.ts"/>

namespace cpr.controls.layouts {
	/**
	 * 
	 */
	export enum VerticalLayoutDistribution {
		leading = "leading",
		trailing = "trailing",
		center = "center",
		fill = "fill"
	}

	export interface VerticalLayoutConstraint extends Constraint {
		/**
		 * 자동 너비를 사용하지 않는 경우 사용할 너비
		 */
		width: string

		/**
		 * 자동 높이를 사용하지 않는 경우 사용할 높이
		 */
		height: string

		/**
		 * 자동 너비 적용시 사용할 최소 너비
		 */
		minWidth?: number

		/**
		 * 자동 높이 적용시 사용할 최소 높이
		 */
		minHeight?: number

		/**
		 * 스크롤 시 컨트롤을 레이아웃 상단에 고정합니다.
		 */
		sticky?: boolean

		/**
		 * 컨트롤 위쪽 간격. 음수인 경우 레이아웃의 spacing 값을 사용합니다.
		 * 0 이상인 경우 레이아웃의 spacing 대신 이 값을 상단 간격으로 사용합니다.
		 * 첫 번째 컨트롤에는 적용되지 않습니다.
		 */
		topSpacing?: number

		/**
		 * sticky 적용 시 이 컨트롤이 레이아웃 상단에서 떨어지는 거리(px).
		 * 음수(기본값 -1)인 경우 레이아웃의 stickyTopOffset 값을 사용합니다.
		 * 0 이상인 경우 레이아웃 값 대신 이 값을 사용합니다. (여러 sticky를 겹치지 않게 수동으로 쌓을 때 활용)
		 */
		stickyTopOffset?: number

		/**
		 * 레이아웃에 남는 세로 공간이 있을 때 이 컨트롤이 추가로 차지할 비율.
		 * 0보다 큰 값을 가진 컨트롤들이 grow 값에 비례하여 남는 공간을 나누어 가지며,
		 * 이때 컨스트레인트의 height는 최소 확보 높이로 동작합니다.
		 * 공간이 부족한 경우 일반 버티컬 레이아웃과 동일하게 동작합니다(스크롤).
		 * 자동 높이(autoSize height/both) 컨트롤과 자동 높이 그룹, IE11에서는 무시됩니다.
		 */
		grow?: number

		/**
		 * 자동 크기 규칙을 얻거나 지정합니다.
		 * <ul>
		 * <li>"none" - 자동 크기를 사용하지 않습니다.</li>
		 * <li>"both" - 가로 세로 모두 자동 크기를 사용합니다.</li>
		 * <li>"width" - 너비만 자동 크기를 사용합니다.</li>
		 * <li>"height" - 높이만 자동 크기를 사용합니다.</li>
		 * </ul>
		 */
		autoSize: AutoSizeType
	}

	const DEFAULT_CONSTRAINT: VerticalLayoutConstraint = {
		width: "150px",
		height: "25px",
		minWidth: 0,
		minHeight: 0,
		sticky: false,
		topSpacing: -1,
		stickyTopOffset: -1,
		grow: 0,
		autoSize: AutoSizeType.none
	}

	/**
	 * 컨트롤들을 세로로 하나씩 차례대로 배치하는 레이아웃.
	 */
	export class VerticalLayout extends OrderedLayout<VerticalLayoutConstraint> {
		/**
		 * 가장 최근 렌더링 시점에 sticky 자식이 존재했는지 여부.
		 * sticky 상태가 전이되면 contentPane 높이를 다시 계산해야 하므로, 부분 렌더링(OCPR/자식 redraw) 대신 전체 재렌더가 필요한지 판단하는 데 사용합니다.
		 */
		private _renderedAsSticky: boolean = false;

		/**
		 * 가장 최근 렌더링 시점에 잉여 공간 배분(grow)이 활성이었는지 여부.
		 * 활성 상태가 전이되면 contentPane의 플렉스 전환을 다시 반영해야 하므로, 부분 렌더링 대신 전체 재렌더가 필요한지 판단하는 데 사용합니다.
		 */
		private _renderedAsGrow: boolean = false;

		/**
		 * 현재 렌더된 sticky 래퍼들(문서 순서). stuck 판정 및 가장자리(cl-first-stuck/cl-last-stuck) 계산에 사용.
		 */
		private _stickyWrappers: HTMLElement[] = [];

		/**
		 * 각 sticky 래퍼의 자연 위치(in-flow) anchor. _stickyWrappers와 같은 인덱스.
		 * `래퍼.top - contentPane.top`(rect 차이)은 자연 위치에선 일정하고 고정되면 그만큼 커지므로,
		 * 관측된 최소값을 자연 anchor로 캐싱해 displacement(= 현재 차이 - anchor)로 stuck을 판정한다.
		 * (offsetTop은 바디 스크롤에서 sticky 요소의 자연 위치를 나타내지 못해 사용하지 않는다.)
		 */
		private _stickyNaturalAnchors: number[] = [];

		/**
		 * stuck 평가를 requestAnimationFrame으로 스로틀하기 위한 핸들. 0이면 예약된 프레임이 없음을 의미.
		 */
		private _stuckRafId: number = 0;

		/**
		 * sticky 자식이 고정될 때 레이아웃 상단에서 떨어지는 거리(px).
		 */
		private _stickyTopOffset: number = 0;

		/**
		 * 새 버티컬 레이아웃을 작성합니다.
		 */
		constructor() {
			super();

			this._bindables.add("distribution", VerticalLayoutDistribution.fill)
				.withGetterTransformer(e => {
					return _isOneOfEnumValue(e, VerticalLayoutDistribution)
						? e
						: VerticalLayoutDistribution.fill;
				});

			["topMargin", "rightMargin", "leftMargin", "bottomMargin"]
				.forEach(prop => {
					this._bindables.add(prop, 0)
						.withNumberGetterTransformer(0);
				});

			this._bindables.add("spacing", 5)
				.withNumberGetterTransformer(0);

			this._bindables.add("maxContentHeight", -1)
				.withNumberGetterTransformer(0);

			this._initLayout();
		}

		protected override _getType(): LayoutType {
			return LayoutType.VERTICAL_LAYOUT;
		}

		public _getDefaultConstraint() {
			return DEFAULT_CONSTRAINT;
		}

		/**
		 * 가로 여백을 지정합니다.
		 * 왼쪽과 오른쪽 모두에 적용됩니다.
		 */
		public set horizontalMargin(horizontalMargin: number) {
			this.leftMargin = horizontalMargin;
			this.rightMargin = horizontalMargin;
		}

		/**
		 * 가로 여백을 얻습니다. 왼쪽 여백과 오른쪽 여백의 평균 값이 반환 됩니다.
		 * @deprecated {@link leftMargin}, {@link rightMargin}을 사용하시기 바랍니다.
		 */
		public get horizontalMargin() {
			return (this.leftMargin + this.rightMargin) / 2;
		}

		/**
		 * 왼쪽 여백을 지정합니다.
		 */
		public set leftMargin(leftMargin: number) {
			this._bindables.set("leftMargin", leftMargin);
		}

		/**
		 * 왼쪽 여백을 얻습니다.
		 */
		public get leftMargin(): number {
			return this._bindables.get("leftMargin");
		}

		/**
		 * 오른쪽 여백을 지정합니다.
		 */
		public set rightMargin(rightMargin: number) {
			this._bindables.set("rightMargin", rightMargin);
		}

		/**
		 * 오른쪽 여백을 얻습니다.
		 */
		public get rightMargin(): number {
			return this._bindables.get("rightMargin");
		}

		/**
		 * 세로 여백을 지정합니다. 상단과 하단에 모두 적용됩니다.
		 */
		public set verticalMargin(verticalMargin: number) {
			this.topMargin = verticalMargin;
			this.bottomMargin = verticalMargin;
		}

		/**
		 * 세로 여백을 얻습니다. 상단과 하단의 평균 여백 값이 반환 됩니다.
		 * @deprecated {@link topMargin}, {@link bottomMargin}을 사용하시기 바랍니다.
		 */
		public get verticalMargin() {
			return (this.topMargin + this.bottomMargin) / 2;
		}

		/**
		 * 상단 여백을 지정합니다.
		 */
		public set topMargin(topMargin: number) {
			this._bindables.set("topMargin", topMargin);
		}

		/**
		 * 상단 여백을 얻습니다.
		 */
		public get topMargin(): number {
			return this._bindables.get("topMargin");
		}

		/**
		 * 하단 여백을 지정합니다.
		 */
		public set bottomMargin(bottomMargin: number) {
			this._bindables.set("bottomMargin", bottomMargin);
		}

		/**
		 * 하단 여백을 얻습니다.
		 */
		public get bottomMargin(): number {
			return this._bindables.get("bottomMargin");
		}

		/**
		 * 컨트롤 배치 규칙을 얻습니다.
		 */
		public get distribution(): VerticalLayoutDistribution {
			return this._bindables.get("distribution");
		}

		/**
		 * 컨트롤을 배치할 규칙을 지정합니다. 값을 지정하지 않으면 기본 값은 "fill" 입니다.
		 * <ul>
		 * <li>leading: 컨트롤을 왼쪽으로 배치합니다.</li>
		 * <li>trailing: 컨트롤을 오른쪽 끝에 배치합니다.</li>
		 * <li>center: 컨트롤을 가운데 배치합니다.</li>
		 * <li>fill: 컨트롤을 가로로 가득 채웁니다.</li>
		 * </ul>
		 */
		public set distribution(newDistribution: VerticalLayoutDistribution) {
			this._bindables.set("distribution", newDistribution);
		}

		/**
		 * 컨트롤 간의 간격을 얻습니다.
		 */
		public get spacing(): number {
			return this._bindables.get("spacing");
		}

		/**
		 * 컨트롤간의 간격을 지정합니다.
		 */
		public set spacing(spacing: number) {
			this._bindables.set("spacing", spacing);
		}

		/**
		 * 컨텐트의 최대 높이를 얻습니다. 음수 인 경우 제약이 없는 것으로 간주합니다.
		 */
		public get maxContentHeight() {
			return this._bindables.get("maxContentHeight");
		}

		/**
		 * 컨텐트의 최대 높이를 지정합니다. 레이아웃을 소유한 컨테이너가 자동 높이를 사용하는 경우에만 적용 됩니다. 음수인 경우 제약이 없는 것으로 간주합니다.
		 */
		public set maxContentHeight(newMaxHeight: number) {
			this._bindables.set("maxContentHeight", newMaxHeight);
		}

		/**
		 * sticky 자식이 고정될 때 레이아웃 상단에서 떨어지는 거리(px)를 얻습니다.
		 */
		public get stickyTopOffset(): number {
			return this._stickyTopOffset;
		}

		/**
		 * sticky 자식이 고정될 때 레이아웃 상단에서 떨어지는 거리(px)를 지정합니다. 기본값은 0입니다.
		 */
		public set stickyTopOffset(offset: number) {
			this._stickyTopOffset = offset || 0;
		}

		protected _doCreateLayoutShape(): cpr.ufc.ControlShape {
			let childControls: UIControl[] = this._owner.getChildren();

			let contentPane: ufc.ElementShape = {
				tag: "div",
				nodename: LayoutConstants.NODE_NAME__CONTENT_PANE,
				classNames: [ufc.Classes.CONTENT_PANE],
				attr: {
					"data-role": "content-pane"
				},
				style: {
					padding: `0px ${this.rightMargin}px 0px ${this.leftMargin}px`,
					width: "100%",
					height: "100%"
				},
				children: []
			};
			if (this._owner.childCombinatorClass) {
				contentPane.classNames.push(this._owner.childCombinatorClass);
			}

			// 버티컬 레이아웃은 가로 스크롤 바를 항상 표시하지 않음.
			let overflowX = this._getOverflowXForNonScroll();

			let overflowY = this._computeOverflowY();

			let layoutNode: ufc.ControlShape = {
				tag: "div",
				nodename: LayoutConstants.NODE_NAME__LAYOUT,
				classNames: [ufc.Classes.LAYOUT],
				attr: {
				},
				style: _mergeObject({
					position: "relative",
					width: "100%",
					height: "100%",
					overflowX: overflowX,
					overflowY: overflowY
				}),
				events: { scroll: this._notifyScrollEvent.bind(this) },
				children: [contentPane]
			};
			if (this._owner.childCombinatorClass) {
				layoutNode.classNames.push(this._owner.childCombinatorClass);
			}

			if (this._ownerHasAutoHeight() && this.maxContentHeight >= 0) {
				layoutNode.style.maxHeight = `${this.maxContentHeight}px`;
			}

			let growActive = this._isGrowActive();
			this._renderedAsGrow = growActive;

			let topMarginStyle: { [key: string]: string } = {
				height: `${this.topMargin}px`
			};
			let bottomMarginStyle: { [key: string]: string } = {
				height: `${this.bottomMargin}px`
			};
			if (growActive) {
				// 마진 노드도 플렉스 아이템이 되므로, 공간 부족 시 줄어들지 않도록 고정한다.
				topMarginStyle = _mergeObject(topMarginStyle, this._createGrowFlexItemStyles());
				bottomMarginStyle = _mergeObject(bottomMarginStyle, this._createGrowFlexItemStyles());
			}

			contentPane.children.push({
				"tag": "div",
				classNames: [ufc.Classes.MARGIN, ufc.Classes.MARGIN_TOP],
				attr: {
					"data-role": "margin"
				},
				style: topMarginStyle
			});
			contentPane.children = contentPane.children.concat(this._applyLayoutShape(childControls))
			contentPane.children.push({
				"tag": "div",
				classNames: [ufc.Classes.MARGIN, ufc.Classes.MARGIN_BOTTOM],
				attr: {
					"data-role": "margin"
				},
				style: bottomMarginStyle
			});

			this._owner._hookLayout(LayoutConstants.NODE_NAME__CONTENT_PANE, contentPane);

			let hasStickyChild = this._hasStickyChild();
			this._renderedAsSticky = hasStickyChild;

			if (this._owner._useBodyScroll()) {
				layoutNode.style.height = "auto";
				layoutNode.style.overflowX = "visible";
				layoutNode.style.overflowY = "visible";
				contentPane.style.height = "auto";
			} else if (contentPane.style["min-width"] || contentPane.style["minWidth"]) {
				// preferred-size에 의해 최소 너비를 갖게 된 경우, 가로 스크롤을 가능하도록 조치.
				layoutNode.style.overflowX = this._computeOverflowX();
			}

			// sticky 자식이 있는 경우, position:sticky의 containing block인 contentPane이 전체 콘텐츠 높이를 갖도록 함.
			// contentPane이 height:100%(뷰포트 높이)이면 sticky가 한 화면 높이까지만 고정되고 이후 스크롤되어 사라지기 때문.
			// 단, 자식의 % 높이는 contentPane의 100% 높이에 의존하므로 sticky가 없을 때는 기존 동작(height:100%)을 유지한다.
			if (!this._owner._useBodyScroll() && hasStickyChild) {
				contentPane.style.height = "auto";
				contentPane.style.minHeight = "100%";
			}

			// 잉여 공간 배분(grow)이 활성인 경우, contentPane을 플렉스 컬럼으로 전환한다.
			// cl- 노드 구조는 그대로 유지되며 스타일만 변경된다. 모든 아이템이 flex-shrink:0을 가지므로
			// 공간이 부족하면 잉여 공간이 0이 되어 CSS만으로 일반 버티컬처럼 동작한다(스크립트 전환 없음).
			if (growActive) {
				FlexCSSBuilder._forLayout()
					._withDirection(FlexDirection.column)
					._commitToShape(contentPane);

				// 바디 스크롤 모드에서는 레이아웃 높이가 콘텐츠를 따르므로(auto) 잉여 공간이 없다.
				// 콘텐츠가 뷰포트보다 짧을 때 가변 영역이 화면을 채우도록 뷰포트 높이를 최소 높이로 확보한다.
				// (html/body에 % 높이 체인이 보장되지 않아 뷰포트 단위를 사용한다. 마진 노드들이 contentPane
				// 안쪽에 있고 패딩은 가로만 있으므로 100vh 계산에 세로 왜곡이 없다. 앱 루트 위에 다른 콘텐츠가
				// 있는 페이지에서는 그만큼 페이지가 뷰포트보다 길어질 수 있다.)
				if (this._owner._useBodyScroll()) {
					contentPane.style.minHeight = "100vh";
				}
			}

			// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/6450
			// 바디스크롤인 경우 마크하지 않아야 합니다.
			if (this.scrollable) {
				internal.ScrollbarUtil._markScrollableContentPane(layoutNode); // CustomScroll Enable
			}

			return layoutNode;
		}

		private _applyLayoutShape(childControls: UIControl[]): (ufc.ControlRenderer | ufc.ControlShape)[] {
			let layoutShape: (ufc.ControlRenderer | ufc.ControlShape)[] = [];

			childControls.forEach((control: UIControl, index: number) => {
				if (control == null || control.disposed == true) {
					return;
				}
				let controlRenderer: ufc.ControlRenderer = control._getRenderer();
				if (controlRenderer == null) {
					return;
				}

				let controlShape: ufc.ControlRenderer = this.applyConstraint(index, control, controlRenderer);

				if (controlShape) {
					layoutShape.push(controlShape);
				}
			});

			return layoutShape;
		}

		private _computeOverflowX() {
			if (!this.scrollable) {
				return this._getOverflowXForNonScroll();
			}
			if (this._ownerHasAutoWidth()) {
				return this._getOverflowXForNonScroll();
			}
			else {
				return "auto";
			}
		}

		private _computeOverflowY() {
			if (!this.scrollable) {
				return this._getOverflowYForNonScroll();
			}
			if (this._ownerHasAutoHeight()) {
				if (this.maxContentHeight >= 0) {
					return "auto";
				} else {
					return this._getOverflowYForNonScroll();
				}
			}
			else {
				return "auto";
			}
		}

		private _computeLayoutStyles(control: UIControl, constraint: VerticalLayoutConstraint): { wrapper: { [key: string]: string }, control: { [key: string]: string } } {
			let wrapperStyles: { [key: string]: string };
			let controlStyles: { [key: string]: string };

			let explicitSize: { width?: string, height?: string } = {};

			// 자동 크기 계산
			switch (constraint.autoSize) {
				case AutoSizeType.both: {
					let size = this._computeAutoSize(control, constraint.width, constraint.height);
					explicitSize.width = size.width;
					explicitSize.height = size.height;
					break;
				}
				case AutoSizeType.width: {
					let size = this._computeAutoSize(control, constraint.width, constraint.height);
					explicitSize.width = size.width;
					explicitSize.height = constraint.height;
					break;
				}
				case AutoSizeType.height: {
					let size = this._computeAutoSize(control, constraint.width, constraint.height);
					explicitSize.width = constraint.width;
					explicitSize.height = size.height;
					break;
				}

				case AutoSizeType.none: {
					explicitSize.width = constraint.width;
					explicitSize.height = constraint.height;
					break;
				}
			}

			switch (this.distribution) {
				// 가득 채움이 아닌 경우 명시적인 너비가 필요함.
				case VerticalLayoutDistribution.leading:
				case VerticalLayoutDistribution.trailing:
				case VerticalLayoutDistribution.center: {
					controlStyles = _assign({
						position: "relative",
						width: explicitSize.width
					}, this._getAnimatingProperties());
					wrapperStyles = _assign({
						position: "relative",
					}, this._getAnimatingProperties());
					break;
				}
				// 가득 채움의 경우
				case VerticalLayoutDistribution.fill: {
					controlStyles = _assign({
						display: "block",
						position: "relative"
					}, this._getAnimatingProperties());

					wrapperStyles = _assign({
						position: "relative",
						width: "100%"
					}, this._getAnimatingProperties());
					break;
				}
			}

			// 높이 처리.
			switch (constraint.autoSize) {
				// 자동 높이인 경우, 컨트롤의 높이가 auto가 되도록 함.
				case AutoSizeType.both:
				case AutoSizeType.height: {
					controlStyles.height = explicitSize.height;
					wrapperStyles.height = "auto";
					break;
				}
				// 자동 높이가 아닌 경우 래퍼의 높이가 지정되고 컨트롤은 100%를 사용함.
				// 아마도 컨스트레인트 높이에 %가 사용된 경우를 위한 것으로 추정 됨.
				default: {
					if (_isPixelValue(explicitSize.height)) {
						controlStyles.height = explicitSize.height;
					}
					wrapperStyles.height = explicitSize.height;
					break;
				}
			}

			// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/6494
			// 최소 너비 처리, 최소 높이는 래퍼 레이아웃 설정에서 처리 됨.
			switch (constraint.autoSize) {
				case AutoSizeType.both:
				case AutoSizeType.width: {
					if (constraint.minWidth > 0) {
						controlStyles.minWidth = `${constraint.minWidth}px`;
					}
					break;
				}
			}

			return {
				wrapper: wrapperStyles,
				control: controlStyles
			}
		}

		public _doDecorateChild(context: LayoutDecorationContext<VerticalLayoutConstraint>): ufc.ControlShape {
			let control = context.childControl;
			let controlShape = context.controlShape;
			let constraint = context.constraint;

			let psudoClasses: string[] = [];
			if (this._getFirstVisibleLayoutChild() === context.childControl) {
				psudoClasses.push(ufc.Classes.FIRST_ROW);
			}
			if (this._getLastVisibleLayoutChild() === context.childControl) {
				psudoClasses.push(ufc.Classes.LAST_ROW);
			}

			controlShape.classNames = (controlShape.classNames || []).concat(psudoClasses);

			// 래퍼 및 컨트롤 노드 스타일 계산.
			let computedStyles = this._computeLayoutStyles(control, constraint);

			// 컨트롤 스타일 반영.
			controlShape.style = _mergeObject(controlShape.style, computedStyles.control);

			// 래퍼 생성.
			let wrapperShape = this.wrap(controlShape, {
				key: control.uuid,
				tag: "div",
				classNames: psudoClasses,
				style: computedStyles.wrapper
			});

			// 첫 줄이 아닌 경우, 스페이싱 추가.
			if (psudoClasses.indexOf(ufc.Classes.FIRST_ROW) === -1) {
				// 컨스트레인트에 상단 간격(topSpacing)이 0 이상으로 지정된 경우 레이아웃의 spacing 대신 사용.
				let topSpacing = constraint.topSpacing >= 0 ? constraint.topSpacing : this.spacing;
				wrapperShape.style = _mergeObject(wrapperShape.style, { marginTop: `${topSpacing}px` });
			}

			// 잉여 공간 배분(grow) 활성 시 래퍼를 플렉스 아이템으로 구성한다.
			// 래퍼의 height가 flex-basis(최소 확보 높이) 역할을 하며, 잉여 공간이 있을 때만 grow 비율로 늘어난다.
			let growActive = this._isGrowActive();
			let growValue = growActive && this._isGrowableConstraint(constraint) ? this._getGrowValue(constraint) : 0;
			if (growActive) {
				wrapperShape.style = _mergeObject(wrapperShape.style, this._createGrowFlexItemStyles(growValue));
			}

			// 스크롤 시 상단 고정. 스크롤 컨테이너(layoutNode)는 네이티브 스크롤을 사용하므로 position:sticky가 동작함.
			// IE11은 position:sticky를 지원하지 않으므로 조용히 무시한다(wrapper는 기존 relative 유지).
			if (constraint.sticky && !_isIE()) {
				// 자식별 stickyTopOffset이 0 이상이면 그 값을, 아니면 레이아웃의 stickyTopOffset을 사용.
				let topOffset = constraint.stickyTopOffset >= 0 ? constraint.stickyTopOffset : this.stickyTopOffset;
				wrapperShape.style = _mergeObject(wrapperShape.style, {
					position: "sticky",
					top: `${topOffset}px`,
					zIndex: "1"
				});
				wrapperShape.classNames = (wrapperShape.classNames || []).concat(ufc.Classes.STICKY);
				controlShape.classNames = (controlShape.classNames || []).concat(ufc.Classes.STICKY);
			}

			// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/6494
			// 최소 높이의 경우 내부 노드들의 높이 관련 속성들의 교란을 피하기 위해 그리드 레이아웃의 minmax 를 이용해 부여 함.
			let rowExpression: string = null;
			switch (constraint.autoSize) {
				case AutoSizeType.height:
				case AutoSizeType.both: {
					// 최소 높이가 지정된 경우.
					if (constraint.minHeight > 0) {
						let minHeight = constraint.minHeight;

						// 버티컬레이아웃의 경우 명시적 높이가 계산된 경우 컨트롤 스타일에 기술 됨.
						if (_isPixelValue(controlShape.style["height"])) {
							// 계산된 높이와 요청된 최소 높이 중 큰 값을 최소 값으로 사용한다.
							// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/6515
							minHeight = Math.max(minHeight, parseFloat(controlShape.style["height"]));
							delete controlShape.style["height"];
						}
						rowExpression = `minmax(${minHeight}px, 1fr)`;
					}
					else {
						rowExpression = "1fr"
					}
					break;
				}

				default: {
					// grow 자식의 경우, 래퍼가 잉여 공간으로 늘어난 만큼 컨트롤이 채우도록 명시 높이를 제거한다.
					// (래퍼는 flex-shrink:0과 height에 의해 최소 높이가 보장되므로 1fr이 곧 래퍼 높이가 된다.)
					if (growValue > 0 && _isPixelValue(controlShape.style["height"])) {
						delete controlShape.style["height"];
					}
					rowExpression = "1fr";
					break;
				}
			}

			switch (this.distribution) {
				case VerticalLayoutDistribution.leading: {
					GridCSSBuilder._forCell()
						._withHorizoltalAlign(GridCellAlign.start)
						._commitToShape(controlShape);

					GridCSSBuilder._forLayout()
						._withTemplateRows(rowExpression)
						._withTemplateColumns("1fr")
						._commitToShape(wrapperShape);
					break;
				}
				case VerticalLayoutDistribution.trailing: {
					GridCSSBuilder._forCell()
						._withHorizoltalAlign(GridCellAlign.end)
						._commitToShape(controlShape);

					GridCSSBuilder._forLayout()
						._withTemplateRows(rowExpression)
						._withTemplateColumns("1fr")
						._commitToShape(wrapperShape);

					break;
				}

				case VerticalLayoutDistribution.center: {

					GridCSSBuilder._forCell()
						._withHorizoltalAlign(GridCellAlign.center)
						._commitToShape(controlShape);

					GridCSSBuilder._forLayout()
						._withTemplateRows(rowExpression)
						._withTemplateColumns("1fr")
						._commitToShape(wrapperShape);

					break;
				}

				case VerticalLayoutDistribution.fill: {
					// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/6121
					// 이곳에서 래퍼내 컨트롤 안쪽의 마진이 외부에 영향을 주지 않도록 끊어주어야 하기 때문에, grid로 처리 함.
					GridCSSBuilder._forCell()
						._withHorizoltalAlign(GridCellAlign.stretch)
						._commitToShape(controlShape);

					GridCSSBuilder._forLayout()
						._withTemplateRows(rowExpression)
						._withTemplateColumns("1fr")
						._commitToShape(wrapperShape);
					// 아무일 안함.
					break;
				}
			}

			return wrapperShape;
		}

		protected applyConstraint(index: number, control: UIControl, controlRenderer: ufc.ControlRenderer): ufc.ControlRenderer {
			controlRenderer.addLayoutDecorator(this._createLayoutDecorator(control));
			return controlRenderer;
		}

		/**
		 * @override
		 */
		public _getSupportedAutoSizeMode() {
			return AutoSizeType.both;
		}

		/**
		 * @override
		 */
		public _getAutoSizeType(constraint: VerticalLayoutConstraint) {
			constraint = _mergeObject(DEFAULT_CONSTRAINT, constraint) as VerticalLayoutConstraint

			switch (this.distribution) {
				// 가득 채우기일 때에는, 가로 자동 너비를 지원 안함.
				case VerticalLayoutDistribution.fill: {
					switch (constraint.autoSize) {
						case layouts.AutoSizeType.both:
						case layouts.AutoSizeType.height: {
							return layouts.AutoSizeType.height;
						}
						default: {
							return layouts.AutoSizeType.none;
						}
					}
				}
				default: {
					return constraint.autoSize;
				}
			}
		}

		/**
		 * @param controls
		 */
		protected _doUpdateControl(controls: UIControl[]): void {
			// sticky 또는 grow가 개입된 경우(현재 있거나 직전 렌더에 있었던 경우) contentPane 구성(높이/플렉스 전환)을
			// 다시 반영하기 위해 전체 레이아웃을 다시 그린다. 두 토글 모두 드물게 발생하므로 부분 최적화를 포기해도 무방하다.
			if (this._hasStickyChild() || this._renderedAsSticky || this._isGrowActive() || this._renderedAsGrow) {
				this._owner.redraw();
				return;
			}
			controls.forEach(it => it.redraw());
		}

		/**
		 * 컨스트레인트의 grow 값을 안전하게 얻는다. 0보다 큰 유한수만 유효하며, 그 외(미지정/NaN/음수)는 0으로 취급한다.
		 */
		private _getGrowValue(constraint: VerticalLayoutConstraint): number {
			let grow = Number(constraint ? constraint.grow : 0);
			return isFinite(grow) && grow > 0 ? grow : 0;
		}

		/**
		 * 주어진 컨스트레인트가 잉여 공간을 배분받을 수 있는지 여부.
		 * 자동 높이(height/both) 자식은 콘텐츠가 높이를 결정해 grow와 논리적으로 충돌하므로 무시한다.
		 */
		private _isGrowableConstraint(constraint: VerticalLayoutConstraint): boolean {
			if (this._getGrowValue(constraint) <= 0) {
				return false;
			}
			return constraint.autoSize != AutoSizeType.height && constraint.autoSize != AutoSizeType.both;
		}

		/**
		 * 유효한 grow 컨스트레인트를 가진 보이는 자식이 하나라도 있는지 여부.
		 * IE11은 플렉스 전환 자체를 하지 않으므로 항상 false를 반환한다(일반 버티컬로 무해하게 동작).
		 */
		private _hasGrowChild(): boolean {
			if (_isIE()) {
				return false;
			}
			return this._owner.getChildren().some(child => {
				if (!this._isVisibleLayoutChild(child)) {
					return false;
				}
				let constraint = this._owner.getConstraint(child) as VerticalLayoutConstraint;
				return constraint != null && this._isGrowableConstraint(constraint);
			});
		}

		/**
		 * 잉여 공간 배분(grow) 렌더링의 활성 여부.
		 * 그룹이 자동 높이인 경우 높이가 콘텐츠에 의해 결정되어 잉여 공간 자체가 없으므로 전부 무시한다.
		 * 자식 데코레이션마다 호출되고 내부에서 전체 자식의 컨스트레인트를 순회하므로, 렌더링 중에는 프레임 캐시를 사용한다.
		 */
		private _isGrowActive(): boolean {
			if (core.DeferredUpdateManager.INSTANCE._isRendering()) {
				return this._getFrameCache().get("grow-active", () => {
					return !this._ownerHasAutoHeight() && this._hasGrowChild();
				});
			}
			return !this._ownerHasAutoHeight() && this._hasGrowChild();
		}

		/**
		 * grow 활성 시 contentPane의 플렉스 아이템(자식 래퍼/마진 노드)에 부여할 스타일을 만든다.
		 * flex-shrink:0으로 공간이 부족할 때 아무것도 줄어들지 않게 하여 기존 블록 흐름과 동일하게
		 * 오버플로우(스크롤)되도록 유지하고, min-height:0으로 플렉스 아이템의 콘텐츠 기반 최소 높이(auto)를
		 * 블록과 동일하게 0으로 되돌린다.
		 * @param grow 0보다 큰 경우 잉여 공간을 이 비율로 배분받는다.
		 */
		private _createGrowFlexItemStyles(grow: number = 0): { [key: string]: string } {
			let styles: { [key: string]: string } = {};
			FlexCSSBuilder._forCell()
				._withCellConstraint(grow, 0, "auto")
				._commit(styles);
			styles["min-height"] = "0";
			return styles;
		}

		/**
		 * sticky 컨스트레인트를 가진 자식이 하나라도 있는지 여부.
		 * IE11은 position:sticky를 지원하지 않으므로 sticky가 적용되지 않으며, contentPane 높이 보정 등 sticky 관련 처리도 하지 않는다(false 반환).
		 */
		private _hasStickyChild(): boolean {
			if (_isIE()) {
				return false;
			}
			return this._owner.getChildren().some(child => {
				if (child == null || child.disposed) {
					return false;
				}
				let constraint = this._owner.getConstraint(child) as VerticalLayoutConstraint;
				return constraint != null && constraint.sticky === true;
			});
		}

		/**
		 * 주어진 자식이 sticky 컨스트레인트를 갖는지 여부.
		 * IE11에서는 sticky가 적용되지 않으므로 항상 false로 간주한다(OCPR 최적화를 불필요하게 포기하지 않도록).
		 */
		private _isStickyChild(child: UIControl, constraint: any, isAdd: boolean): boolean {
			if (_isIE()) {
				return false;
			}
			if (isAdd) {
				return !!(constraint && constraint.sticky);
			}
			let c = this._owner.getConstraint(child) as VerticalLayoutConstraint;
			return !!(c && c.sticky);
		}

		/**
		 * 주어진 자식이 유효한 잉여 공간 배분(grow) 컨스트레인트를 갖는지 여부.
		 * IE11에서는 grow가 적용되지 않으므로 항상 false로 간주한다(OCPR 최적화를 불필요하게 포기하지 않도록).
		 */
		private _isGrowChild(child: UIControl, constraint: any, isAdd: boolean): boolean {
			if (_isIE()) {
				return false;
			}
			if (isAdd) {
				return !!(constraint && this._isGrowableConstraint(constraint));
			}
			let c = this._owner.getConstraint(child) as VerticalLayoutConstraint;
			return !!(c && this._isGrowableConstraint(c));
		}

		/**
		 * @override
		 * sticky/grow 자식의 추가/삭제는 contentPane 구성(높이/플렉스 전환) 및 stuck 옵저버 재구성을 위해
		 * 전체 재렌더가 필요하므로 최적화 렌더링을 포기한다.
		 */
		public _shouldOCPRParticipateChild(child: UIControl, constraint: any, isAdd: boolean) {
			if (this._isStickyChild(child, constraint, isAdd) || this._isGrowChild(child, constraint, isAdd)) {
				return false;
			}
			return super._shouldOCPRParticipateChild(child, constraint, isAdd);
		}

		/**
		 * @override
		 * OCPR(부분 렌더링) 직후, grow 활성 상태가 마지막 전체 렌더 시점과 달라졌으면 전체 재렌더를 예약한다.
		 * (예: 유일한 grow 자식의 visible 토글은 자식 단독 렌더로 처리되어 contentPane의 플렉스 전환을 놓칠 수 있다.)
		 */
		public override _onOCPRFinish(session: OCPRSession) {
			super._onOCPRFinish(session);
			if (session._isRendered() === false) {
				return;
			}
			if (this._renderedAsGrow !== this._isGrowActive()) {
				core.DeferredUpdateManager.INSTANCE.asyncExec(() => {
					if (this._owner && !this._owner.disposed) {
						this._owner.redraw();
					}
				});
			}
		}

		/**
		 * @override
		 * 렌더링 직후, sticky 자식이 실제로 고정(stuck)되는 시점을 감지해 cl-stuck 클래스를 토글하기 위한 스크롤 구독을 구성한다.
		 */
		public override _afterDraw(firstDraw: boolean = false) {
			super._afterDraw(firstDraw);
			this._setupStickyStuckObservers();
		}

		/**
		 * @override
		 * 컨테이너에서 분리(레이아웃 교체 또는 컨테이너 폐기)될 때 stuck 스크롤 구독을 정리한다.
		 */
		public override _onDetached(): void {
			super._onDetached();
			this._teardownStickyStuckObservers();
		}

		/**
		 * 기존 stuck 스크롤 구독 및 예약된 평가 프레임을 정리한다.
		 */
		private _teardownStickyStuckObservers() {
			// 미구독 상태에서도 안전(unsubscribe는 idempotent).
			core.NotificationCenter.INSTANCE.unsubscribe(this, core.SystemTopics.SCROLL);
			if (this._stuckRafId && typeof cancelAnimationFrame !== "undefined") {
				cancelAnimationFrame(this._stuckRafId);
			}
			this._stuckRafId = 0;
			this._stickyWrappers = [];
			this._stickyNaturalAnchors = [];
		}

		/**
		 * 현재 stuck 상태인 sticky 래퍼들 중 문서 순서상 첫째/마지막에 cl-first-stuck/cl-last-stuck을 부여한다.
		 * (여러 sticky가 동시에 고정되었을 때 가장자리만 스타일링할 수 있도록 함. stuck이 하나면 둘 다 부여됨.)
		 */
		private _updateStuckEdges() {
			let stuck = this._stickyWrappers.filter(w => w.classList && w.classList.contains(ufc.Classes.STUCK));
			this._stickyWrappers.forEach(w => {
				this._applyStuckClass(w, ufc.Classes.FIRST_STUCK, false);
				this._applyStuckClass(w, ufc.Classes.LAST_STUCK, false);
			});
			if (stuck.length > 0) {
				this._applyStuckClass(stuck[0], ufc.Classes.FIRST_STUCK, true);
				this._applyStuckClass(stuck[stuck.length - 1], ufc.Classes.LAST_STUCK, true);
			}
		}

		/**
		 * stuck 계열 클래스(cl-stuck/cl-first-stuck/cl-last-stuck)를 sticky 래퍼와 그 안의 컨트롤 노드에 동시에 토글한다.
		 * cl-sticky가 래퍼와 컨트롤 양쪽에 부여되는 것과 동일하게, 고정 상태도 컨트롤에서 직접 스타일링할 수 있도록 한다.
		 * (컨트롤은 wrap()에 의해 래퍼의 직계 자식이다.)
		 */
		private _applyStuckClass(wrapper: HTMLElement, className: string, on: boolean) {
			let nodes: HTMLElement[] = [wrapper];
			let control = wrapper.firstElementChild as HTMLElement;
			if (control) {
				nodes.push(control);
			}
			nodes.forEach(node => {
				if (node.classList) {
					if (on) {
						node.classList.add(className);
					} else {
						node.classList.remove(className);
					}
				}
			});
		}

		/**
		 * sticky 자식 래퍼들의 고정(stuck) 여부를 스크롤 시 연속 평가하기 위해 프레임워크의 스크롤 통지를 구독한다.
		 * 네이티브 DOM 'scroll' 이벤트는 프레임워크가 가로채(stopPropagation) 외부 리스너에 도달하지 않는 경우가 있어 사용하지 않고,
		 * 바디/일반 스크롤을 모두 post하는 NotificationCenter SCROLL 통지를 구독한다(reveal 등 프레임워크 스크롤 처리와 동일 계열).
		 * 실제 판정은 requestAnimationFrame으로 스로틀해 {@link _evaluateStuck}에서 수행한다.
		 * 센티널을 사용하지 않으므로 contentPane의 자식 구성을 변경하지 않는다(OCPR 인덱스 안전).
		 * IE11은 position:sticky 자체가 비활성이므로 구독하지 않는다.
		 */
		private _setupStickyStuckObservers() {
			this._teardownStickyStuckObservers();

			if (_isIE()) {
				return;
			}

			let contentPane = this._getContentPaneNode();
			if (!contentPane) {
				return;
			}

			// sticky 래퍼는 contentPane의 직계 자식이다. (cl-sticky는 내부 컨트롤에도 부여되므로 직계 자식만 선별)
			let stickyWrappers: HTMLElement[] = [];
			for (let i = 0; i < contentPane.children.length; i++) {
				let node = contentPane.children[i] as HTMLElement;
				if (node.classList && node.classList.contains(ufc.Classes.STICKY)) {
					stickyWrappers.push(node);
				}
			}

			if (stickyWrappers.length === 0) {
				return;
			}

			this._stickyWrappers = stickyWrappers;
			this._stickyNaturalAnchors = [];

			// 스크롤마다 rAF 1프레임으로 스로틀해 평가한다(통지 처리 내 레이아웃 측정 비용 최소화).
			core.NotificationCenter.INSTANCE.subscribe(core.SystemTopics.SCROLL, this, () => {
				if (this._stuckRafId) {
					return;
				}
				this._stuckRafId = requestAnimationFrame(() => {
					this._stuckRafId = 0;
					this._evaluateStuck();
				});
			});

			// 렌더 직후 초기 상태(스크롤 0 등)를 반영한다.
			this._evaluateStuck();
		}

		/**
		 * 현재 sticky 래퍼들이 자연 위치(in-flow)보다 위로 밀려 실제 고정된 상태인지 평가해 cl-stuck을 토글한다.
		 *
		 * 각 래퍼의 `래퍼.top - contentPane.top`(둘 다 viewport 기준 rect.top) 차이는,
		 * - 자연 위치(흐름)에선 contentPane이 함께 스크롤되므로 일정한 값(= 자연 anchor)을 유지하고,
		 * - 실제 고정(pin)되면 래퍼만 제자리에 머물러 contentPane이 위로 빠진 만큼 차이가 커진다.
		 * 따라서 관측된 최소 차이를 자연 anchor로 캐싱하고, (현재 차이 - anchor)가 양수일 때만 stuck으로 본다.
		 * 이 방식은 바디/일반 스크롤, 고정 오프셋 값과 무관하게 일관되며(offsetTop의 sticky 왜곡 회피),
		 * 정지/자연 위치(예: 고정 오프셋 0 + 스크롤 0)에선 차이가 anchor와 같아 stuck을 부여하지 않고,
		 * 하단 이탈 시에도 자연 위치로 복귀해 자동 해제된다.
		 */
		private _evaluateStuck() {
			if (this._stickyWrappers.length === 0) {
				return;
			}
			let contentPane = this._getContentPaneNode();
			if (!contentPane) {
				return;
			}
			let contentTop = contentPane.getBoundingClientRect().top;
			this._stickyWrappers.forEach((wrapper, i) => {
				if (!wrapper.classList) {
					return;
				}
				let diff = wrapper.getBoundingClientRect().top - contentTop;
				let anchor = this._stickyNaturalAnchors[i];
				// 관측된 최소 차이를 자연 anchor로 캐싱(흐름 상태의 차이가 곧 자연 anchor이며, 고정 시에만 커진다).
				if (anchor == null || diff < anchor) {
					anchor = diff;
					this._stickyNaturalAnchors[i] = anchor;
				}
				let stuck = diff - anchor > 0.5;
				this._applyStuckClass(wrapper, ufc.Classes.STUCK, stuck);
			});
			// 전체 sticky 래퍼 기준으로 stuck 가장자리(first/last)를 갱신.
			this._updateStuckEdges();
		}

		/**
		 * @override
		 */
		protected _compareConstraint(a: VerticalLayoutConstraint, b: VerticalLayoutConstraint): boolean {
			return a.width == b.width
				&& a.height == b.height
				&& a.autoSize == b.autoSize
				&& a.sticky == b.sticky
				&& a.topSpacing == b.topSpacing
				&& a.stickyTopOffset == b.stickyTopOffset
				&& a.grow == b.grow;
		}

		/**
		 * @override
		 */
		public _supportsBodyScroll(): boolean {
			// 버티컬 레이아웃은 바디 스크롤을 지원합니다.
			return true;
		}

		/**
		 * @override
		 */
		public _applyBodyScrollToContainerShape(shape: ufc.ControlShape) {
			_assign(shape.style, {
				height: "auto",
				minHeight: "100%"
			});
		};

		_getRenderedLayoutInfo(): RenderedLayoutInfo {
			return {
				layoutNodeName: LayoutConstants.NODE_NAME__LAYOUT,
				scrollingNodeName: LayoutConstants.NODE_NAME__LAYOUT,
				contentPaneNodeName: LayoutConstants.NODE_NAME__CONTENT_PANE,
				offsetIndexForChildren: 1,
			}
		}

		getInsertionReference(location: geometry.Point): OrderedInsertionReference {
			let orderedChildren = this._getOrderedChildren();

			if (utils.Util.isNullOrEmpty(orderedChildren)) {
				return {
					index: 0,
					previousSibiling: null,
					nextSibiling: null
				};
			}

			let allChildren = this._getOwner().getChildren();

			let nextSibiling = orderedChildren.find(it => {
				return it.getActualRect().center.y > location.y;
			});

			let orderedIndex = nextSibiling ? orderedChildren.indexOf(nextSibiling) : orderedChildren.length;
			let insertIndex = nextSibiling ? allChildren.indexOf(nextSibiling) : allChildren.length;
			return {
				index: insertIndex,
				previousSibiling: orderedIndex > 0 ? orderedChildren[orderedIndex - 1] : null,
				nextSibiling: nextSibiling
			};
		}

		protected override _normalizeConstraint(constraint: VerticalLayoutConstraint): VerticalLayoutConstraint {
			["width", "height"].filter(prop => {
				return typeof constraint?.[prop] == "number"
			}).forEach(prop => {
				constraint[prop] = `${constraint[prop]}px`
			});
			return constraint;
		}
	}
}