namespace cpr {
	/**
	 * 날짜 및 시간에 대한 지역 정보입니다.
	 * @private
	 */
	export interface ILocaleLongDateFormat {
		/**
		 * 8:30 PM
		 */
		LT: string,
		/**
		 * 8:30:25 PM
		 */
		LTS: string,
		/**
		 * 09/04/1986
		 */
		L: string,
		/**
		 * September 4, 1986
		 */
		LL: string,
		/**
		 * Septermber 4, 1986 8:30 PM
		 */
		LLL: string,
		/**
		 * Thursday, September 4, 1986 8:30 PM
		 */
		LLLL: string
	}

	/**
	 * 날짜 및 시간에 대한 지역 정보입니다.
	 * @private
	 * @see https://momentjs.com/docs/#/i18n/
	 */
	export interface ILocaleDateTime {

		/**
		 * 요일
		 * ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
		 */
		weekdays?: string[]
		/**
		 * 요일 축약
		 * ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
		 */
		weekdaysShort?: string[]
		/**
		 * 요일 최소
		 * ['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa']
		 */
		weekdaysMin?: string[]
		/**
		 * 월 이름
		 * ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
		 */
		months?: string[]
		/**
		 * 월 이름 축약
		 * ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
		 */
		monthsShort?: string[]
		/**
		 * 지역에서 일반적으로 표시되는 포맷
		 */
		longDateFormat?: ILocaleLongDateFormat
		/**
		 * 오전, 오후에 대한 정보
		 */
		meridiem?: ILocaleMeridiem
		/**
		 * 주의 시작 요일
		 * 0: Sunday, 1: Monday, ..., 6: Saturday
		 */
		firstDayOfWeek?: number
	}
	/**
	 * 오전, 오후에 대한 정보입니다.
	 * @private
	 */
	export interface ILocaleMeridiem {
		am: string
		pm: string
	}

	/**
	 * @noinstance
	 * @private
	 */
	export class LocaleDateTime extends SubLocale implements ILocaleDateTime {
		private _longDateFormat: LocaleLongDateFormat;
		private _meridiem: LocaleMeridiem;

		constructor(owner: LocalePropertyProvider) {
			super(owner);
			this._longDateFormat = new LocaleLongDateFormat(this);
			this._meridiem = new LocaleMeridiem(this);
		}

		public _convertMomentLocaleData(mergeLocaleData: ILocaleDateTime = {}): moment.LocaleSpecification {
			return this._delegateLocale((locale: string) => {
				let momentLocale = _getAvailableMomentLocale(locale);
				if (momentLocale) {
					let am = mergeLocaleData.meridiem?.am ?? this.meridiem.am;
					let pm = mergeLocaleData.meridiem?.pm ?? this.meridiem.pm;
					return {
						parentLocale: momentLocale,
						months: mergeLocaleData.months ?? this.months,
						monthsShort: mergeLocaleData.monthsShort ?? this.monthsShort,
						weekdays: mergeLocaleData.weekdays ?? this.weekdays,
						weekdaysShort: mergeLocaleData.weekdaysShort ?? this.weekdaysShort,
						weekdaysMin: mergeLocaleData.weekdaysMin ?? this.weekdaysMin,
						week: {
							dow: mergeLocaleData?.firstDayOfWeek ?? this.firstDayOfWeek
						},
						longDateFormat: {
							LT: mergeLocaleData.longDateFormat?.LT ?? this.longDateFormat.LT,
							LTS: mergeLocaleData.longDateFormat?.LTS ?? this.longDateFormat.LTS,
							L: mergeLocaleData.longDateFormat?.L ?? this.longDateFormat.L,
							LL: mergeLocaleData.longDateFormat?.LL ?? this.longDateFormat.LL,
							LLL: mergeLocaleData.longDateFormat?.LLL ?? this.longDateFormat.LLL,
							LLLL: mergeLocaleData.longDateFormat?.LLLL ?? this.longDateFormat.LLLL
						},
						isPM: (input: string) => {
							return input.toLowerCase().indexOf(pm) > -1;
						},
						meridiemParse: new RegExp(am + "|" + pm),
						meridiem: (hour: number, minute: number, isLower: boolean) => {
							return hour < 12 ? am : pm;
						}
					}
				}
				return null;
			});
		}

		public get firstDayOfWeek(): number {
			return this._getProperty(localeData => localeData.dateTime?.firstDayOfWeek);
		}
		public get longDateFormat(): ILocaleLongDateFormat {
			return this._longDateFormat;
		}
		public get meridiem(): ILocaleMeridiem {
			return this._meridiem;
		}
		public get weekdays(): string[] {
			return this._getProperty(localeData => localeData.dateTime?.weekdays);
		}
		public get weekdaysShort(): string[] {
			return this._getProperty(localeData => localeData.dateTime?.weekdaysShort);
		}
		public get weekdaysMin(): string[] {
			return this._getProperty(localeData => localeData.dateTime?.weekdaysMin);
		}
		public get months(): string[] {
			return this._getProperty(localeData => localeData.dateTime?.months);
		}
		public get monthsShort(): string[] {
			return this._getProperty(localeData => localeData.dateTime?.monthsShort);
		}
	}

	/**
	 * @noinstance
	 * @private
	 */
	export class LocaleLongDateFormat extends SubLocale implements ILocaleLongDateFormat {
		public get LT(): string {
			return this._getProperty(localeData => localeData.dateTime?.longDateFormat?.LT);
		}
		public get LTS(): string {
			return this._getProperty(localeData => localeData.dateTime?.longDateFormat?.LTS);
		}
		public get L(): string {
			return this._getProperty(localeData => localeData.dateTime?.longDateFormat?.L);
		}
		public get LL(): string {
			return this._getProperty(localeData => localeData.dateTime?.longDateFormat?.LL);
		}
		public get LLL(): string {
			return this._getProperty(localeData => localeData.dateTime?.longDateFormat?.LLL);
		}
		public get LLLL(): string {
			return this._getProperty(localeData => localeData.dateTime?.longDateFormat?.LLLL);
		}

	}

	/**
	 * @noinstance
	 * @private
	 */
	export class LocaleMeridiem extends SubLocale implements ILocaleMeridiem {
		public get am(): string {
			return this._getProperty(localeData => localeData.dateTime?.meridiem?.am);
		}
		public get pm(): string {
			return this._getProperty(localeData => localeData.dateTime?.meridiem?.pm);
		}
	}

}