/// <reference path="./TreeDataProvider.ts" />
namespace cpr.controls.provider {
	/**
	 * @private
	 */
	export abstract class AbstractTreeDataBinder<ItemType extends TreeItem, ConfigType extends TreeItemSetConfig, ProviderType extends AbstractTreeDataProvider<ItemType, ConfigType, any>> extends AbstractListDataBinder<ItemType, ConfigType, ProviderType> {

		constructor(owner: UIControl) {
			super(owner);
		}

		/**
		 * multiple일 경우 선택이 쌓인다. 아닌경우는 하나만 선택되도록 한다.
		 * @param item 선택할 아이템
		 * @param multiple true인경우 선택된 아이템이 쌓인다. false인 경우 선택된 모든 아이템을 지우고 하나를 선택한다.
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 * @override
		 */
		public _select(item: ItemType, multiple: boolean = false, emitEvent: boolean = true, forceSelect: boolean = false): boolean {
			let oldSelection = this.getSelection();
			let newSelection: ItemType[] = [];
			if (item == null) {
				return false;
			}

			if (forceSelect == false && this.isSelectedByValue(item.value) == true) {
				return true;
			}

			if (multiple) {
				let hasParent = this.getDataProvider().getParent(item) != null && item.value != item.parentValue;
				if (_.findIndex(oldSelection, { value: item.parentValue }) > -1 || !hasParent) {
					let parentItem: ItemType = item;
					while (parentItem != null) {
						newSelection.push(parentItem);
						parentItem = this.getDataProvider().getParent(parentItem);
					}
					newSelection = newSelection.reverse();
				} else {
					newSelection.push(item);
				}
			} else {
				newSelection.push(item);
			}

			if (forceSelect == false && this.getDataProvider().isSelected(item)) {
				this.redraw();
				return true;
			}

			if (emitEvent !== false) {
				//before-selection event 
				let selectionEvent = new cpr.events.CSelectionEvent(events.SelectionEventType.BEFORECHANGE
					, { oldSelection: oldSelection, newSelection: newSelection });

				let preventDefault = this.getOwner().dispatchEvent(selectionEvent);
				if (!preventDefault) {
					this.redraw();
					return false;
				}
			}

			//select
			//multiple == true 일 경우 parent를 선택해야만 children이 선택됩니다.
			if (!multiple) {
				// clearSelection에서 value를 null로 설정하여 value-change이벤트가 발생
				this.getDataProvider().clearSelection();
				if (this.getDataProvider().disposed) {
					return;
				}
				this.getDataProvider().select(item, multiple);
			} else {
				this.getDataProvider().deepRemoveSelectionByParent(item);
				let values = this.getValues();
				if (values.indexOf(item.value) !== -1) {
					return true;
				}
				if (this.getDataProvider().getParent(item) == null || values.indexOf(item.parentValue) == -1) {
					values = [];
				}
				values.push(item.value)
				this.setValues(values);
			}

			if (this.getDataProvider().disposed) {
				return;
			}

			if (emitEvent !== false) {
				//selection event
				let selectionEvent = new cpr.events.CSelectionEvent(events.SelectionEventType.CHANGE, {
					oldSelection: oldSelection, newSelection: this.getSelection()
				});

				this.getOwner().dispatchEvent(selectionEvent);
			}
			return true;
		}


		/**
		 * 
		 * @param item 
		 * @param emitEvent 
		 * @override
		 */
		public _removeSelection(item: ItemType, emitEvent: boolean = true): boolean {
			let oldSelection = this.getSelection();
			let newSelection = oldSelection.concat();

			let index = _.findIndex(oldSelection, { value: item.value });
			if (oldSelection.length > 0 && index > -1) {
				newSelection = newSelection.splice(index, newSelection.length - (index + 1));
				if (this.getMultiple() == true) {
				} else {
					newSelection = [];
				}
			} else {
				return true;
			}

			if (emitEvent === false) {
				this.getDataProvider().deepRemoveSelection(item);
				return true;
			}

			//before-selection event
			let selectionEvent = new cpr.events.CSelectionEvent(events.SelectionEventType.BEFORECHANGE
				, { oldSelection: oldSelection, newSelection: newSelection });
			if (event != null) {
				selectionEvent.nativeEvent = event;
			}

			let preventDefault = this.getOwner().dispatchEvent(selectionEvent);
			if (!preventDefault) {
				return false;
			}

			//remove selection
			this.getDataProvider().deepRemoveSelection(item);

			//selection event
			selectionEvent = new cpr.events.CSelectionEvent(events.SelectionEventType.CHANGE, {
				oldSelection: oldSelection, newSelection: this.getSelection()
			});
			if (event != null) {
				selectionEvent.nativeEvent = event;
			}
			this.getOwner().dispatchEvent(selectionEvent);
			return true;
		}


		public _selectChildren(select: boolean, children: ItemType[]): void {
			if (select) {
				this.getDataProvider().selectItems(children, true);
			} else {
				this.getDataProvider().deleteSelection(children);
			}
		}

		/**
		 * 해당되는 아이템을 제거합니다.
		 * @param obj 아이템 또는 인덱스
		 * @override
		 */
		public deleteItem(obj: ItemType | number): void {
			let item: ItemType;
			if (obj instanceof Item) {
				item = obj;
			} else {
				item = this.getItem(obj);
			}
			if (!item) {
				return;
			}
			let visibleDeletedItem = this.getDataProvider().getVisibleDeletedItem();
			let canDeselection = visibleDeletedItem && !item.row;
			if (visibleDeletedItem == false || canDeselection) {
				this.getDataProvider().deleteSelection([item]);
			}
			this.getDataProvider().deleteItem(item);
			this.redraw();
		}

		/**
		 * value에 해당되는 아이템을 제거합니다.
		 * @param value 아이템의 value
		 */
		public deleteItemByValue(value: string): void {
			let visibleDeletedItem = this.getDataProvider().getVisibleDeletedItem();
			let item = this.getDataProvider().getByValue(value, false);
			let canDeselection = visibleDeletedItem && !item.row;
			if (visibleDeletedItem == false || canDeselection) {
				this.getDataProvider().deleteSelectionByValue(value);
			}
			if (item != null) {
				this.getDataProvider().deleteItem(item);
			}
			this.redraw();
		}

		/**
		 * 아이템의 자식이 있는지 유무를 반환합니다.
		 * @param item 아이템.
		 * @return 아이템 자식이 있는지 유무.
		 */
		public hasChild(item: ItemType): boolean {
			return this.getDataProvider().hasChild(item);
		}

		/**
		 * 아이템의 자식들을 배열로 반환합니다. null을 넣으면 root의 자식들을 반환합니다.
		 * @param item null | item.
		 * @return 아이템 자식들의 배열.
		 */
		public getChildren(item?: ItemType): ItemType[] {
			return this.getDataProvider().getChildren(item);
		}

		/**
		 * 해당되는 아이템을 선택합니다.<br>
		 * 선택된 아이템의 value는 컨트롤의 value로 지정됩니다.<br>
		 * 존재하지 않는 아이템인 경우 아이템 선택이 안 되고 해당 value가 지정되지 않습니다.
		 * @param obj 선택하고자 하는 아이템.
		 * @param recursive 부모 아이템 선택 여부.
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 * @override
		 */
		public selectItem(obj: ItemType | number, recursive: boolean = false, emitEvent: boolean = true): void {
			let item: ItemType;
			if (obj instanceof Item) {
				item = obj;
			} else {
				item = this.getDataProvider().get(obj);
			}
			if (item == null) {
				return;
			}
			if (recursive) {
				let values = this.getValues();
				if (values.length > 0 && values[values.length - 1] == item.value) {
					return;
				}
				let parent = this.getDataProvider().getParent(item);
				let result = [item];
				while (parent != null) {
					result.push(parent);
					parent = this.getDataProvider().getParent(parent);
				}
				result.reverse();
				this._selectItems(result, emitEvent);
			} else {
				this._select(item, this.getMultiple(), emitEvent);
			}
			this.redraw();
		}

		/**
		 * Label에 해당되는 아이템을 선택합니다.<br>
		 * 선택된 아이템의 value는 컨트롤의 value로 지정됩니다.<br>
		 * 존재하지 않는 아이템인 경우 아이템 선택이 안 되고 해당 value가 지정되지 않습니다.
		 * @param label 아이템의 label.
		 * @param recursive 부모 아이템 선택 여부.
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 * @override
		 */
		public selectItemByLabel(label: string, recursive: boolean = false, emitEvent: boolean = true): void {
			let item = this.getDataProvider().getByLabel(label);
			if (item == null) {
				return;
			}
			this.selectItem(item, recursive, emitEvent);
		}

		/**
		 * value에 해당되는 아이템을 선택합니다.<br>
		 * value로 아이템을 선택하고 value를 지정합니다.<br>
		 * 존재하지 않는 아이템인 경우 아이템 선택이 안 되고 value가 지정되지 않습니다.
		 * @param value 아이템의 value.
		 * @param recursive 부모 선택 여부.
		 * @param emitEvent 이벤트(before-selection-change, selection-change)를 발생시킬지 여부.
		 * @override
		 */
		public selectItemByValue(value: string, recursive: boolean = false, emitEvent: boolean = true): void {
			let item: ItemType = this.getDataProvider().getByValue(value);
			if (item == null) {
				return;
			}
			this.selectItem(item, recursive, emitEvent);
		}

		public findTreeItem(findValue: string, items: ItemType[]): ItemType {
			return this.getDataProvider().findTreeItem((each: ItemType) => each.value == findValue, items);
		}

		public findTreeItemByUUID(uuid: string, items: ItemType[]): ItemType {
			return this.getDataProvider().findTreeItem((each: ItemType) => each._getUUID() == uuid, items);
		}

		public _collapseAllItems() {
			this.getDataProvider().collapseAllItems();
		}

		public setTreeFilter(filterExp: expression_string) {
			if (this.getDataProvider().getTreeFilter() != filterExp) {
				this.getDataProvider().setTreeFilter(filterExp);
				this.redraw();
			}
		}

		public getTreeFilter(): expression_string {
			return this.getDataProvider().getTreeFilter();
		}

		public updateItem(targetItem: ItemType, sourceItem: ItemType) {
			this.getDataProvider().update(targetItem, sourceItem);
		}

		public isExpanded(item: ItemType) {
			return this.getDataProvider().isExpanded(item);
		}

		public setExpanded(item: ItemType, state: boolean) {
			this.getDataProvider().setExpanded(item, state);
		}
		/**
		 * 아이템의 체크를 설정합니다.
		 * @param item 
		 * @param state 
		 */
		public setChecked(item: ItemType, state: boolean): void {
			if (item.checked == state) {
				return;
			}
			if (this.getDataProvider().setChecked(item, state)) {
				this.redraw();
			}
		}

		public getCheckedItems(): ItemType[] {
			return this.getDataProvider().getCheckedItems();
		}

		/**
		 * 아이템들을 모두 체크하고 설정 성공 여부를 반환합니다.
		 * @param items 
		 */
		public setCheckedItems(items: ItemType[]) {
			return this.getDataProvider().setCheckedItems(items);
		}

		public _toExpandedItemArray(items: TreeItem[]) {
			let result = [];
			items.forEach((each: TreeItem) => {
				result[result.length] = each;

				if (each._hasChild() && each.expanded) {
					result = result.concat(this._toExpandedItemArray(each.children));
				}
			});
			return result;
		}

	}//AbstractTreeDataBinder

	/**
	 * value, label, parentValue로 구성된 트리 형태의 데이터를 가지고 바인드가 가능한 컴포넌트의 상위 컨트롤.
	 * @private
	 */
	export class TreeDataBinder extends AbstractTreeDataBinder<TreeItem, TreeItemSetConfig, TreeDataProvider> {
		_createDataProvider(): controls.provider.TreeDataProvider {
			return new controls.provider.TreeDataProvider(this.getOwner());
		}
	}
}