/// <reference path="../IGridPart.ts"/>
/// <reference path="./ScrollPane.ts"/>


namespace cpr.controls.gridpart.layout {

	/**
	 * @private
	 */
	export interface PanePosition {
		top?: string,
		left?: string,
		right?: string,
		width?: string,
		bottom?: string,
		height?: string
	}

	/**
	 * @private
	 */
	export class TablePane {
		private _region: string;
		private _context: GridContext; // to access structure

		private _header: { control: GridHeader, constraints: GridBandConstraint };
		private _topDetail: { control: GridDetail, constraints: GridBandConstraint };
		private _middleDetail: { control: GridDetail, constraints: GridBandConstraint };
		private _bottomDetail: { control: GridDetail, constraints: GridBandConstraint };
		private _footer: { control: GridFooter, constraints: GridBandConstraint };

		private _headerScrollPane: PassiveScrollPane;
		private _topDetailScrollPane: ScrollPane;
		private _middleDetailScrollPane: ScrollPane;
		private _bottomDetailScrollPane: ScrollPane;
		private _footerScrollPane: PassiveScrollPane;

		private _position: PanePosition;


		constructor(region: string, context: GridContext) {
			this._region = region;
			this._context = context;
		}

		public _init(tableInfos: { band: IGridPart, constraints: GridBandConstraint }[], scrollPaneCluster: ScrollPaneCluster): void {
			this._header = null;
			this._topDetail = null;
			this._middleDetail = null;
			this._bottomDetail = null;
			this._footer = null;

			this._headerScrollPane = null;
			this._topDetailScrollPane = null;
			this._middleDetailScrollPane = null;
			this._bottomDetailScrollPane = null;
			this._footerScrollPane = null;

			if (tableInfos == null) {
				return;
			}

			tableInfos.forEach((tableInfo: { band: AbstractGridPart, constraints: GridBandConstraint }) => {
				switch (tableInfo.constraints.vloc) {
					case GRIDREGION.HEADER: {
						this._header = { control: tableInfo.band as GridHeader, constraints: tableInfo.constraints };
						this._headerScrollPane = new PassiveScrollPane(this._region, GRIDREGION.HEADER, this._context, this._header.control, scrollPaneCluster);
						break;
					}
					case GRIDREGION.TOP: {
						this._topDetail = { control: tableInfo.band as GridDetail, constraints: tableInfo.constraints };
						this._topDetailScrollPane = new ScrollPane(this._region, GRIDREGION.TOP, this._context, this._topDetail.control, scrollPaneCluster);
						break;
					}
					case GRIDREGION.MIDDLE: {
						this._middleDetail = { control: tableInfo.band as GridDetail, constraints: tableInfo.constraints };
						this._middleDetailScrollPane = new ScrollPane(this._region, GRIDREGION.MIDDLE, this._context, this._middleDetail.control, scrollPaneCluster);
						break;
					}
					case GRIDREGION.BOTTOM: {
						this._bottomDetail = { control: tableInfo.band as GridDetail, constraints: tableInfo.constraints };
						this._bottomDetailScrollPane = new ScrollPane(this._region, GRIDREGION.BOTTOM, this._context, this._bottomDetail.control, scrollPaneCluster);
						break;
					}
					case GRIDREGION.FOOTER: {
						this._footer = { control: tableInfo.band as GridFooter, constraints: tableInfo.constraints };
						this._footerScrollPane = new PassiveScrollPane(this._region, GRIDREGION.FOOTER, this._context, this._footer.control, scrollPaneCluster);
						break;
					}
				}
			});
		}

		set position(position: PanePosition) {
			this._position = position;
		}

		public _getScrollPane(loc: string): ScrollPane {
			switch (loc) {
				case GRIDREGION.TOP:
					return this._topDetailScrollPane;
				case GRIDREGION.MIDDLE:
					return this._middleDetailScrollPane;
				case GRIDREGION.BOTTOM:
					return this._bottomDetailScrollPane;
			}
			return null;
		}

		public _jumpPage(movePageEvent: events.CUIEvent): void {
			// 내부 이벤트
			if (this._topDetailScrollPane) {
				this._topDetailScrollPane._jumpPage(movePageEvent);
			}
			if (this._middleDetailScrollPane) {
				this._middleDetailScrollPane._jumpPage(movePageEvent);
			}
			if (this._bottomDetailScrollPane) {
				this._bottomDetailScrollPane._jumpPage(movePageEvent);
			}
		}

		public _jumpCellIndex(cellIndex: number): void {
			if (this._middleDetailScrollPane) {
				this._middleDetailScrollPane._jumpCellIndex(cellIndex);
			} else if (this._topDetailScrollPane) {
				this._topDetailScrollPane._jumpCellIndex(cellIndex);
			} else if (this._bottomDetailScrollPane) {
				this._bottomDetailScrollPane._jumpCellIndex(cellIndex);
			}
		}

		public _jumpRowGroupCell(groupCondition: string, vloc: string, cellIndex: number): void {
			if (this._middleDetailScrollPane) {
				this._middleDetailScrollPane._jumpRowGroupCellIndex(groupCondition, vloc, cellIndex);
			} else if (this._topDetailScrollPane) {
				this._topDetailScrollPane._jumpRowGroupCellIndex(groupCondition, vloc, cellIndex);
			} else if (this._bottomDetailScrollPane) {
				this._bottomDetailScrollPane._jumpRowGroupCellIndex(groupCondition, vloc, cellIndex);
			}
		}

		public _jumpHeaderCell(headerCellIndex: number): void {
			if (this._headerScrollPane) {
				this._headerScrollPane._jumpCellIndex(headerCellIndex);
			}
		}

		public _jumpFooterCell(footerCellIndex: number): void {
			if (this._footerScrollPane) {
				this._footerScrollPane._jumpCellIndex(footerCellIndex);
			}
		}

		public _readyForRedraw(): void {
			[this._headerScrollPane
				, this._topDetailScrollPane
				, this._middleDetailScrollPane
				, this._bottomDetailScrollPane
				, this._footerScrollPane].forEach((scrollPane: ScrollPane) => {
					if (scrollPane) {
						scrollPane._readyForRedraw();
					}
				});
		}
		public _initScrollTop(scrollTop: number): void {
			[this._topDetailScrollPane
				, this._middleDetailScrollPane
				, this._bottomDetailScrollPane].forEach((scrollPane: ScrollPane) => {
					if (scrollPane) {
						scrollPane._initScrollTop(scrollTop);
					}
				});
		}
		public _initScrollLeft(scrollLeft: number): void {
			[this._headerScrollPane
				, this._topDetailScrollPane
				, this._middleDetailScrollPane
				, this._bottomDetailScrollPane
				, this._footerScrollPane].forEach((scrollPane: ScrollPane) => {
					if (scrollPane) {
						scrollPane._initScrollLeft(scrollLeft);
					}
				});
		}

		public createShape(): ufc.ControlShape {
			let headerHeight: number = this._context._getDesignHeaderRowHeight();
			let topDetailHeight: number = (this._topDetail && this._context.isEnabledPart(GRIDREGION.TOP) === true) ? this._context.topSplitHeight : 0;
			let bottomDetailHeight: number = (this._context.isEnabledPart(GRIDREGION.BOTTOM) === true) ? this._context.bottomSplitHeight : 0;
			let footerHeight: number = (this._context.isEnabledPart(GRIDREGION.FOOTER) === true) ? this._context._getDesignFooterRowHeight() : 0;

			let contentChildren: ufc.ControlShape[] = [];

			// header
			contentChildren.push(this._wrapContentView(GRIDREGION.HEADER, "header", this._headerScrollPane, {
				top: "0px",
				height: headerHeight + "px"
			}, [GridStyle.HEADERBAND]));

			// topdetail
			if (this._context.isEnabledPart(GRIDREGION.TOP) === true) {
				contentChildren.push(this._wrapContentView(GRIDREGION.TOP, "detail", this._topDetailScrollPane, {
					top: headerHeight + "px",
					height: topDetailHeight + "px"
				}, [GridStyle.DETAILBAND, GridStyle.TOPSPLIT]));
			}

			// bottomdetail
			let bottomDetailShape: ufc.ControlShape = null;
			if (this._context.isEnabledPart(GRIDREGION.BOTTOM) === true) {
				bottomDetailShape = this._wrapContentView(GRIDREGION.BOTTOM, "detail", this._bottomDetailScrollPane, {
					bottom: footerHeight + "px",
					height: bottomDetailHeight + "px"
				}, [GridStyle.DETAILBAND, GridStyle.BOTTOMSPLIT]);
			}

			// footer
			let footerShape: ufc.ControlShape = null;
			if (this._context.isEnabledPart(GRIDREGION.FOOTER) === true) {
				footerShape = this._wrapContentView(GRIDREGION.FOOTER, "footer", this._footerScrollPane, {
					bottom: "0px",
					height: footerHeight + "px"
				}, [GridStyle.FOOTERBAND]);
			}

			// middledetail
			let middleDetailPosition: PanePosition = { top: headerHeight + topDetailHeight + "px" };
			middleDetailPosition.bottom = footerHeight + bottomDetailHeight + "px"
			contentChildren.push(this._wrapContentView(GRIDREGION.MIDDLE, "detail", this._middleDetailScrollPane, middleDetailPosition, [GridStyle.DETAILBAND]));
			if (bottomDetailShape) {
				contentChildren.push(bottomDetailShape);
			}
			if (footerShape) {
				contentChildren.push(footerShape);
			}

			// content shape
			let contentShape: ufc.ControlShape = {
				tag: "div",
				classNames: [],
				attr: {
					role: GRIDROLE.GROUP,
					"data-role": GRIDROLE.GROUP,
					"data-region": this._region
				},
				style: _assign({
					boxSizing: "border-box",
					position: "absolute"
				}, this._position),
				children: contentChildren
			};
			if (this._region == GRIDREGION.LEFT) {
				contentShape.classNames.push(GridStyle.LEFTSPLIT);
			} else if (this._region == GRIDREGION.RIGHT) {
				contentShape.classNames.push(GridStyle.RIGHTSPLIT);
			} else if (this._region == GRIDREGION.CENTER) {
				contentShape.classNames.push(GridStyle.CENTERSPLIT);
			}

			return contentShape;
		}

		public _hasContent(): boolean {
			return this._header != null && this._middleDetail != null;
		}

		private _wrapContentView(location: string, stylerName: string, scrollPane: IScrollPane, position: PanePosition, classNames: string[]): cpr.ufc.ControlShape {
			let shape: ufc.ControlShape = {
				tag: "div",
				style: {
					position: "absolute",
					left: "0px",
					right: "0px",
					display: "block"
				},
				styler: stylerName,
				nodename: this._region + "-" + location,
				children: []
			};
			if (scrollPane) {
				shape.children[0] = _createDrawLazyTask({
					nodename: scrollPane.nodename,
					task: () => {
						return scrollPane.createShape();
					}
				});
			}
			shape.style = _mergeObject(position, shape.style);
			if (classNames != null && classNames.length > 0) {
				shape.classNames = classNames;
			}

			return shape;
		}

		public _getWidth(): number {
			if (this._hasContent()) {
				return this._header.control._getWidth();
			}
			return 0;
		}

	}
}