/// <reference path="./IGridCellRenderer.ts"/>


namespace cpr.controls.gridpart.renderer {

	/**
	 * @private
	 */
	export class DefaultCellRenderer extends AbstractGridCellRenderer {
		private _cellRenderer: (grid: Grid, uiControl: GridUIControl, data: (string | number | foundation.DecimalType | ufc.StyledString), option: IRenderOption) => ufc.ControlShape;


		constructor(cellprop: GridCellProp /* GridDetailCellProp */, grid: Grid) {
			super(cellprop, grid);
		}

		private get detailprop(): GridDetailCellProp {
			return this.prop as GridDetailCellProp;
		}

		protected _init(): void {
			let uicontrol: GridUIControl = this.detailprop.configuration.control;
			if (uicontrol == null) {
				this._cellRenderer = CellRendererFactory._getRenderer(uicontrol);
			}
		}

		public createCellShape(gridRow: provider.GridRow | provider.GridRowGroup, option: IRenderOption): ufc.ControlShape | ufc.ControlRenderer {
			if (option && option.editingrow == true) {
				return this._createEditingShape(gridRow as provider.GridRow, option);
			} else {
				return this._createViewingShape(gridRow as provider.GridRow, option);
			}
		}

		/**
		 * 그리드 셀의 편집(Editing) 모드 모양(Shape)을 생성합니다.
		 * 내부적으로 개별 단일 책임을 가진 프라이빗 헬퍼 메서드들을 호출하여 렌더링 과정을 조율합니다.
		 * 
		 * @param gridRow 그리드 행 데이터 객체
		 * @param option 렌더링 옵션 객체
		 * @returns 생성된 컨트롤 쉐이프 또는 렌더러 객체
		 */
		private _createEditingShape(gridRow: provider.GridRow, option: IRenderOption): ufc.ControlShape | ufc.ControlRenderer {
			let { uicontrol, controlConstraint } = this._resolveControlAndConstraint();

			let controlShape: ufc.ControlShape | ufc.ControlRenderer = null;
			if (uicontrol) {
				controlShape = this._decorateEditingControl(uicontrol, controlConstraint, option);
			} else {
				controlShape = this._renderDefaultEditingCell(gridRow, option);
			}
			return controlShape;
		}

		/**
		 * 편집 모드 UI 컨트롤에 데코레이터를 추가하고 그리드 셀 장식을 수행합니다.
		 * 
		 * @param uicontrol UI 컨트롤 객체
		 * @param controlConstraint 컨트롤 배치 제약조건
		 * @param option 렌더링 옵션 객체
		 * @returns 데코레이터가 추가된 컨트롤 렌더러 객체
		 */
		private _decorateEditingControl(uicontrol: GridUIControl, controlConstraint: ControlConstraint, option: IRenderOption): ufc.ControlRenderer {
			let EDITCELLSTYLE: { [key: string]: string } = {
				position: "relative", width: "100%", height: "100%", "min-width": "100%", "min-height": "100%"
			};

			let controlRenderer: ufc.ControlRenderer = uicontrol._getRenderer();
			controlRenderer.addDecorator("grid-cell-decorator", (controlShape: ufc.ControlShape) => {
				// Grid Cell이 리얼 컨트롤을 포함하는지 여부를 마킹
				// Event 처리시 사용
				if (!controlShape.attr) {
					controlShape.attr = {};
				}
				controlShape.attr["data-widget"] = "true";

				let cellVisible: boolean = this.detailprop.configuration.visible;
				let cellEnabled: boolean = this.detailprop.configuration.enabled;
				let styles: { [key: string]: string } = { height: GridContext._getCellMaxHeight(option.height) + "px" };
				let classNames: string[] = controlShape.classNames.concat(GridContext.CLS_CTRL_INHERIT);
				if (cellVisible === false) {
					styles["display"] = "none";
				}
				if (cellEnabled === false) {
					classNames.push(ufc.Classes.DISABLED);
				}
				controlShape.style = _assign(EDITCELLSTYLE, controlShape.style, styles);
				controlShape.classNames = _uniq(classNames);

				GridUtil._setControlPosition(controlShape, controlConstraint);
				if (option.height == -1) {
					// height == -1 인 경우 autoRowHeight 계산을 위한 dom 입니다.
					// autoRowHeihgt시 올바른 dom의 높이를 가져오기위해 position을 변경합니다.
					controlShape.style["position"] = "relative";
				}

				return controlShape;
			});

			return controlRenderer;
		}

		/**
		 * UI 컨트롤이 없는 기본(Default) 편집용 셀을 렌더링합니다.
		 * 
		 * @param gridRow 그리드 행 데이터 객체
		 * @param option 렌더링 옵션 객체
		 * @returns 기본 셀 렌더러 결과 쉐이프
		 */
		private _renderDefaultEditingCell(gridRow: provider.GridRow, option: IRenderOption): ufc.ControlShape {
			let columnName: string = this.detailprop.configuration.columnName;
			let controlShape: ufc.ControlShape = this._cellRenderer(this.grid, null, gridRow.getString(columnName), option);
			if (controlShape) {
				let cellVisible: boolean = this.detailprop.configuration.visible;
				if (cellVisible === false && !option.isGhost) {
					controlShape.style["display"] = "none";
				}

			}
			return controlShape;
		}

		/**
		 * 그리드 셀의 뷰(Viewing) 모드 모양(Shape)을 생성합니다.
		 * 내부적으로 개별 단일 책임을 가진 프라이빗 헬퍼 메서드들을 호출하여 렌더링 과정을 조율합니다.
		 * 
		 * @param gridRow 그리드 행 데이터 객체
		 * @param option 렌더링 옵션 객체
		 * @returns 생성된 컨트롤 쉐이프(ufc.ControlShape) 객체
		 */
		private _createViewingShape(gridRow: provider.GridRow, option: IRenderOption): ufc.ControlShape {
			let { uicontrol, controlConstraint } = this._resolveControlAndConstraint();

			// 컨트롤 유무에 따른 전 처리
			this._preprocessControlSize(uicontrol, controlConstraint, option);

			// columnName, altColumnName, data 설정
			let { data, isBindingChanged } = this._resolveCellData(uicontrol, option, gridRow);

			let controlShape = this._renderControlShape(uicontrol, data, option);

			this._restoreBinding(uicontrol, isBindingChanged);

			// 컨트롤 유무에 따른 후 처리
			this._postprocessControlShape(controlShape, uicontrol, controlConstraint, gridRow, option);

			return controlShape;
		}

		/**
		 * 조건부 컨트롤(Conditional Control) 여부를 판단하여, 셀에 해당하는 실제 UI 컨트롤 및 그 제약조건(Constraint)을 해석합니다.
		 * 
		 * @returns 해석된 UI 컨트롤 및 제약조건 객체
		 */
		private _resolveControlAndConstraint(): { uicontrol: GridUIControl, controlConstraint: ControlConstraint } {
			let uicontrol: GridUIControl = null;
			let controlConstraint: ControlConstraint = null;
			if (this.detailprop.configuration._isConditionalControl()) {
				let conditionalId = this.detailprop.configuration._getConditionalResult();
				uicontrol = this.detailprop.configuration._getConditionalControl(conditionalId);
				controlConstraint = this.detailprop.configuration._getConditionalControlConstraint(conditionalId);
			} else {
				uicontrol = this.detailprop.configuration.control;
				controlConstraint = this.detailprop.configuration.controlConstraint;
			}
			return { uicontrol, controlConstraint };
		}

		/**
		 * UI 컨트롤의 제약조건(Constraint) 크기에 맞춰 렌더링 옵션의 높이 설정을 전처리합니다.
		 * 컨트롤의 높이가 100%가 아닌 고정값 등인 경우, 해당 값으로 렌더 옵션의 높이 및 최대 높이를 갱신합니다.
		 * 
		 * @param uicontrol UI 컨트롤 객체
		 * @param controlConstraint 컨트롤 배치 제약조건
		 * @param option 렌더링 옵션 객체
		 */
		private _preprocessControlSize(uicontrol: GridUIControl, controlConstraint: ControlConstraint, option: IRenderOption): void {
			if (uicontrol) {
				let controlSize: { width: string, height: string } = GridUtil._getControlSize(controlConstraint);
				if (controlSize.height != "100%") {
					let height: utils.Size = utils.ParamUtil.parseSize(controlSize.height);
					option.height = height.size;
					option.maxHeight = height.size;
				}
			}
		}

		/**
		 * 그리드 행에서 셀 데이터(값)를 해석하고, 대체 컬럼명이 지정되어 있을 경우 임시로 바인딩을 변경합니다.
		 * 
		 * @param uicontrol UI 컨트롤 객체
		 * @param option 렌더링 옵션 객체
		 * @param gridRow 그리드 행 데이터 객체
		 * @returns 해석된 데이터 및 바인딩 임시 변경 여부 플래그
		 */
		private _resolveCellData(uicontrol: GridUIControl, option: IRenderOption, gridRow: provider.GridRow): { data: (string | number | foundation.DecimalType | ufc.StyledString), isBindingChanged: boolean } {
			let columnName: string = option.altColumnName == null ? this.detailprop.configuration.columnName : option.altColumnName;
			let data: (string | number | foundation.DecimalType | ufc.StyledString) = columnName ? gridRow.getValue(columnName) : null;
			let isBindingChanged: boolean = false;
			if (option.altColumnName && uicontrol?.getBindInfo("value") != null) {
				uicontrol.bind("value").toDataColumn(option.altColumnName);
				isBindingChanged = true;
			}
			return { data, isBindingChanged };
		}

		/**
		 * 셀에 배치된 UI 컨트롤 유무에 따라, 해당 데이터를 그리드 셀 모양으로 렌더링합니다.
		 * UI 컨트롤이 있는 경우 해당 컨트롤의 렌더러를 활용하고, 없을 경우 디폴트 렌더러를 사용합니다.
		 * 
		 * @param uicontrol UI 컨트롤 객체
		 * @param data 렌더링할 데이터
		 * @param option 렌더링 옵션 객체
		 * @returns 생성된 컨트롤 쉐이프(ufc.ControlShape)
		 */
		private _renderControlShape(uicontrol: GridUIControl, data: (string | number | foundation.DecimalType | ufc.StyledString), option: IRenderOption): ufc.ControlShape {
			let controlShape: ufc.ControlShape = null;
			if (uicontrol) {
				if (!(data instanceof ufc.StyledString)) {
					data = utils.Util.toString(data);
				}
				controlShape = uicontrol._renderGridCellShape(this.grid, data, option);
			} else { // default cell
				controlShape = this._cellRenderer(this.grid, uicontrol, data, option);
			}
			return controlShape;
		}

		/**
		 * 대체 컬럼명 처리를 위해 임시 변경했던 컨트롤의 데이터 바인딩 정보를 원래의 컬럼명으로 복구합니다.
		 * 
		 * @param uicontrol UI 컨트롤 객체
		 * @param isBindingChanged 바인딩 임시 변경 여부 플래그
		 */
		private _restoreBinding(uicontrol: GridUIControl, isBindingChanged: boolean): void {
			if (isBindingChanged && uicontrol) {
				uicontrol.bind("value").toDataColumn(this.detailprop.configuration.columnName);
			}
		}

		/**
		 * 렌더링이 완료된 컨트롤 쉐이프(ControlShape) 객체에 대해 클래스명(classNames), 스타일(CSS style),
		 * 보더(Border), 표시 여부(visible), 활성화 여부(enabled), 레이아웃 위치, 툴팁 속성 등을 후처리 적용합니다.
		 * 
		 * @param controlShape 후처리할 컨트롤 쉐이프 객체
		 * @param uicontrol UI 컨트롤 객체
		 * @param controlConstraint 컨트롤 배치 제약조건
		 * @param gridRow 그리드 행 데이터 객체
		 * @param option 렌더링 옵션 객체
		 */
		private _postprocessControlShape(controlShape: ufc.ControlShape, uicontrol: GridUIControl, controlConstraint: ControlConstraint, gridRow: provider.GridRow, option: IRenderOption): void {
			let cellVisible: boolean = this.detailprop.configuration.visible;
			let cellEnabled: boolean = this.detailprop.configuration.enabled;

			if (uicontrol && controlShape) {
				let attr: { [key: string]: string } = {};

				controlShape.attr = _mergeObject(controlShape.attr, attr);

				// classnames
				controlShape.classNames = _uniq((controlShape.classNames || []).concat(uicontrol.style.getClasses()).concat(GridContext.CLS_CTRL_INHERIT));
				if (controlShape.classNames.indexOf(ufc.Classes.FOCUS) != -1) {
					controlShape.classNames.splice(controlShape.classNames.indexOf(ufc.Classes.FOCUS), 1);
				}
				if (uicontrol instanceof EnableUIControl && uicontrol.readOnly === true) {
					controlShape.classNames.push(ufc.Classes.READONLY);
				}
				if (uicontrol instanceof EnableUIControl && (uicontrol.enabled === false || cellEnabled === false)) {
					controlShape.classNames.push(ufc.Classes.DISABLED);
				}
				// style
				let verticalAlign: string = controlConstraint["verticalAlign"];
				if (option.height > -1 && verticalAlign == "fill") {
					let maxHeight: number = (option.hideborder === true) ? option.height : GridContext._getCellMaxHeight(option.height);
					controlShape.style = _mergeObject(uicontrol.style.css(), controlShape.style, {
						"max-height": maxHeight + "px",
						width: "100%"
					});
				} else {
					controlShape.style = _mergeObject(uicontrol.style.css(), controlShape.style, {
						width: "100%"
					});
				}
				if ((uicontrol.visible == false || cellVisible === false) && !option.isGhost) {
					controlShape.style["display"] = "none";
				}

				if (option && option.hideborder) {
					controlShape.style["border-bottom"] = "none";
				}
				if (option && option.isFirst === false) {
					controlShape.style["border-top"] = "none";
				}

				GridUtil._setControlPosition(controlShape, controlConstraint);
				if (option.height == -1) {
					// height == -1 인 경우 autoRowHeight 계산을 위한 dom 입니다.
					// autoRowHeihgt시 올바른 dom의 높이를 가져오기위해 position을 변경합니다.
					controlShape.style["position"] = "relative";
				}

				ufc.ShapeUtil._setTooltipAttr(controlShape, { owner: uicontrol, title: uicontrol.tooltip, id: `d-${gridRow.getIndex()}` });

			} else if (controlShape) {
				if (cellVisible === false && !option.isGhost) {
					controlShape.style["display"] = "none";
				}
			}
		}

	}
}