

namespace cpr.controls.internal {


	/**
	 * @private
	 */
	export abstract class CustomAbstractScrollbar {
		private static readonly _AVAILABLE_PROP: string[] = [
			"minThumbSize"
		];
		private _scrollPane: IVirtualScrollPane;
		private _minThumbSize: number = 5;

		constructor(scrollPane: IVirtualScrollPane) {
			this._scrollPane = scrollPane;
			this._initScroll();
		}

		public get minThumbSize() {
			return this._minThumbSize;
		}

		public set minThumbSize(size: number) {
			this._minThumbSize = size;
		}

		protected _getDefaultConfiguration() {
			return cpr.core.AppConfig.INSTANCE.getControlConfig("customscroll")
		}

		protected _initScroll(): void {
			let config: core.Config = this._getDefaultConfiguration();
			if (config) {
				this._applyConfig(config);
			}
		}

		protected _applyConfig(config: core.Config): void {
			this._configureProperties(config);
		}

		protected _configureProperties(config: core.Config) {
			let jsonConfig: {} = config.toJSON();
			for (let propName in jsonConfig) {
				if (this._isConfigurableProperty(propName)) {
					let propValue: any = jsonConfig[propName];
					if (propValue != null) {
						this[propName] = propValue;
					}
				}
			}
		}

		protected _isConfigurableProperty(propName: string): boolean {
			if (CustomAbstractScrollbar._AVAILABLE_PROP.indexOf(propName) != -1) {
				return true;
			}
			if (propName == "style") {
				return false;
			}
			return false;
		}

		protected _getScrollPane(): IVirtualScrollPane {
			return this._scrollPane;
		}

		protected _isEnabled(): boolean {
			return this._scrollPane._isEnabled();
		}

		protected _getQName(localName: string): string {
			return this._scrollPane._getQName(localName);
		}

		protected _getNamedNode(localName: string): HTMLElement {
			return this._scrollPane._getRenderer().getNamedNode(this._getQName(localName));
		}

		protected _updateStyle(localName: string, style: any): void {
			this._scrollPane._getRenderer().updateStyle(this._getQName(localName), style, true);
		}

		protected _updateCSS(name: string, classNames: string[], style: any, merge: boolean): void {
			this._scrollPane._getRenderer().updateCSS(this._getQName(name), classNames, style, merge);
		}

	}

}