///<reference path="./UIControl.ts"/>

namespace cpr.controls {
	export abstract class VisibleUIControl extends UIControl {

		constructor(id?: string) {
			super(id);

			this._addBindableProperty("tooltip", null)
				.withGetterTransformer((text: string) => {
					if (text == null) {
						return "";
					} else {
						return text;
					}
				})
				.withSetterValidatorWithType(false, "string");
			this._addBindableProperty("visible", true).withSetterValidatorWithType(false, "boolean");

		}

		protected override _isConfigurableProperty(propName: string): boolean {
			if (propName == "visible" || propName == "tooltip") {
				return true;
			}
			return super._isConfigurableProperty(propName);
		}

		/**
		 * css visibility를 제어하기 위한 style 속성을 설정합니다.
		 * @param visible 화면에 보이는 여부.
		 */
		public set visible(visible: boolean) {
			this._bindables.set("visible", visible);
		}

		/**
		 * css visibility를 제어하기 위한 style 속성을 반환합니다.
		 * @return 화면에 보이는 여부.
		 */
		public get visible(): boolean {
			return this._bindables.get("visible");
		}

		/**
		 * 컨트롤에 대한 설명을 설정합니다.<br>
		 * 마우스 오버 시 동작합니다.
		 * @param 컨트롤에 대한 설명.
		 */
		public set tooltip(tooltip: string) {
			this._bindables.set("tooltip", tooltip);
		}

		/**
		 * 컨트롤에 대한 설명을 반환합니다.<br>
		 * 마우스 오버 시 동작합니다.
		 * @return 컨트롤에 대한 설명.
		 */
		public get tooltip(): string {
			return this._bindables.get("tooltip");
		}

		/**
		 * 해당 속성 값이 변동된 후에 수행되는 api입니다.
		 * @param name 속성 명
		 * @param oldValue 이전 속성 값.
		 * @param newValue 현재 속성 값.
		 */
		public override _valueDidChange(prop: string, oldValue: any, newValue: any): void {
			super._valueDidChange(prop, oldValue, newValue);

			switch (prop) {
				case "visible": {
					let parent = this.getParent();
					if (parent != null) {
						parent._applyChildSizeChanging(this);

						// 가시성이 바뀌면 레이아웃의 첫/마지막 자식 판정이 달라질 수 있다.
						// 이 컨트롤만 다시 그리면 직전에 가장자리였던 형제에 유틸리티 클래스가 남으므로
						// 레이아웃에 알려 보정할 기회를 준다. release-test-project#10339
						let layout = parent.getLayout();
						if (layout && layout._onChildLayoutParticipationChanged) {
							// 플롯된 자식은 가시성과 무관하게 레이아웃 흐름에 참여하지 않는다.
							let constraint = parent.getConstraint(this);
							let wasParticipating = oldValue === true
								&& constraint != null
								&& !layouts._isManualConstraint(constraint);
							layout._onChildLayoutParticipationChanged(this, wasParticipating);
						}
					}
				}
				case "tooltip": {
					this.redraw();
					break;
				}
			}
		}

	}
}