namespace cpr.controls {
	const _MAX_ARIA_LABEL_LENGTH: number = 256;

	function _normalizeKey(key: string) {
		key = key.toLowerCase();
		if (key == "role" || key.indexOf("aria-") > -1) {
			return key;
		}

		else {
			return `aria-${key}`;
		}
	}

	export type AriaValue = string | Accessibility;
	export interface AriaSet {
		role?: string
		label?: string
		[key: string]: AriaValue
	}

	/**
	 * @private
	 */
	export interface AriaSpec {
		root: AriaSet;
		[key: string]: AriaSet;
	}

	/**
	 * @private
	 */
	export enum AriaRequestType {
		/**
		 * 참조 노출 요청
		 */
		EXPOSE_REF = "EXPOSE_REF",
		/**
		 * 참조 해제 요청
		 */
		UNEXPOSE_REF = "UNEXPOSE_REF"
	}

	/**
	 * @noinstance
	 */
	export class Accessibility implements bind.BindablePropertiesOwner, expression.EvaluationContext {
		private _owner: UIControl;
		private _ariaSet: AriaSet;
		private _bindables: bind.BindableProperties;
		private _bindContext: bind.BindContext;
		private _subAccessibility: CMap<string, Accessibility>;
		private _name: string;

		constructor(owner: UIControl, spec: AriaSpec) {
			this._owner = owner;
			this._ariaSet = spec.root;
			this._name = "root";
			this._bindables = new bind.BindableProperties(this, {
				allowsAnyProperty: true
			});

			Object.keys(spec).filter(it => it != "root").forEach(each => {
				this._addSubAccessibility(each, this._createAccessibility(each, spec[each]));
			});
		}

		/**
		 * 이름을 설정합니다.
		 * @param name 
		 */
		public _setName(name: string): void {
			this._name = name;
		}

		/**
		 * 이름을 얻습니다.
		 * @returns 
		 */
		public _getName(): string {
			return this._name;
		}

		protected _getAriaSet(): AriaSet {
			return this._ariaSet;
		}

		protected _getSubAccessibility(name: string): Accessibility {
			return this._subAccessibility?.get(name);
		}

		private _addSubAccessibility(name: string, accessibility: Accessibility): void {
			if (!this._subAccessibility) {
				this._subAccessibility = _createMap<string, Accessibility>();
			}
			if (!this.hasOwnProperty(name)) {
				this[name] = accessibility;
			}
			this._subAccessibility.set(name, accessibility);
		}

		protected _createAccessibility(name: string, spec: AriaSet): Accessibility {
			let accessibility = new Accessibility(this._owner, { root: spec });
			accessibility._setName(name);
			return accessibility;
		}

		private _getAriaValue(property: string): AriaValue {
			return this._ariaSet[property];
		}

		private _setAriaValue(property: string, value: AriaValue): void {
			if (this._ariaSet[property] instanceof Accessibility) {
				let oldAccessibility = this._ariaSet[property] as Accessibility;
				oldAccessibility._requestAriaRef(AriaRequestType.UNEXPOSE_REF);
			}
			if (value instanceof Accessibility) {
				value._requestAriaRef(AriaRequestType.EXPOSE_REF);
			}
			this._ariaSet[property] = value;
		}
		/**
		 * 해당 ARIA 속성 값을 얻습니다.
		 * @param property 값을 얻을 ARIA 속성 명. "aria-" 접두어는 생략할 수 있습니다.
		 * @return 해당 ARIA 속성 값.
		 */
		public aria(property: string): string

		/**
		 * 특정 ARIA 속성값을 지정합니다.
		 * @param property 값을 지정할 ARIA 속성 명. "aria-" 접두어는 생략할 수 있습니다.
		 * @param value 지정할 속성 값.
		 */
		public aria(property: string, value: string): void;
		/**
		 * 특정 ARIA 속성값을 지정합니다.
		 * Accessibility 객체를 지정할 경우 해당 객체의 참조 ID가 속성 값으로 사용됩니다.
		 * aria-labelledby, aria-describedby 등과 같이 다른 요소를 참조하는 속성에 Accessibility 객체를 지정할 수 있습니다.
		 * @param property 값을 지정할 ARIA 속성 명. "aria-" 접두어는 생략할 수 있습니다.
		 * @param value 지정할 속성 값.
		 */
		public aria(property: string, value: Accessibility): void;
		/**
		 * 특정 ARIA 속성값을 지정합니다.
		 * 배열을 지정할 경우 각 요소의 값이 속성 값으로 사용됩니다.
		 * aria-labelledby, aria-describedby 등 여러 요소를 참조할 수 있는 속성에 사용됩니다. Accessibility 객체가 포함된 배열의 경우 각 객체의 참조 ID가 사용됩니다.
		 * @param property 값을 지정할 ARIA 속성 명. "aria-" 접두어는 생략할 수 있습니다.
		 * @param value 지정할 속성 값 배열.
		 */
		public aria(property: string, value: Accessibility[]): void;

		/**
		 * 지정된 모든 ARIA 속성들을 JSON 형태로 얻습니다.
		 */
		public aria(): AriaSet;

		/**
		 * 한 번에 여러 ARIA 속성들을 지정합니다.
		 * @param set 지정할 속성명 키와 값들을 가진 JSON 객체.
		 */
		public aria(set: AriaSet): void;

		public aria(...args: any[]): any {
			switch (args.length) {
				case 0: {
					let bindedAllProperties = _.pick(
						this._bindables.resolveAll(),
						(val: any, key: string) => {
							return this._bindables.isBinded(key)
						}
					);
					let result = _mergeObject(this._ariaSet, _.mapObject(bindedAllProperties, (val: any) => { return val || "" }));
					return result;
				}
				case 1: {
					switch (typeof args[0]) {
						case "string": {
							let key = _normalizeKey(args[0]);

							if (this._bindables.isBinded(key)) {
								return this._bindables.get(key) ?? "";
							}
							else {
								return this._getAriaValue(key) ?? "";
							}
						}
						case "object": {
							let changed = false;
							let newAriaSet = args[0] as AriaSet;

							Object.keys(newAriaSet).forEach(originKey => {
								let key = _normalizeKey(originKey);

								if (this._bindables.isBinded(key)) {
									this._bindables.destroy(key);
									changed = true;
								}
								let eachValue = newAriaSet[originKey];
								if (this._getAriaValue(key) != eachValue) {
									this._setAriaValue(key, eachValue);
									changed = true;
								}
							});
							if (changed) {
								this._owner?.redraw();
								if (this._owner?.getParent()?.type == "grid") {
									this._owner.getParent().redraw();
								}
							}
							break;
						}

						default: {
							throw new exceptions.IllegalArgumentException();
						}
					}
					break;
				}
				case 2: {
					let key = _normalizeKey(args[0]);
					let newValue = args[1] as any;
					let changed = false;

					if (this._bindables.isBinded(key)) {
						this._bindables.destroy(key);
						changed = true;
					}
					if (this._getAriaValue(key) != newValue) {
						this._setAriaValue(key, newValue);
						changed = true;
					}

					if (changed) {
						this._owner?.redraw();
						if (this._owner?.getParent()?.type == "grid") {
							this._owner.getParent().redraw();
						}
					}
					break;
				}
			}
		}

		/**
		 * 오버라이드해서 참조 객체를 생성합니다.
		 * @returns 
		 */
		protected _createAriaRef(): { [key: string]: any } {
			return null;
		}

		private _requestAriaRef(message: AriaRequestType) {
			if (this._owner === null || this._owner.disposed) {
				return;
			}
			let ref = this._createAriaRef();
			this._owner._requestAriaRef({ uuid: this._owner.uuid, message: message }, ref);
		}

		private _getAriaDomId(): string {
			if (this._owner === null || this._owner.disposed) {
				return null;
			}
			let ref = this._createAriaRef();
			return this._owner._getAriaDOMId(ref);
		}

		/**
		 * Shape에 반영할 정규화된 AriaSet을 반환합니다.
		 * AriaReference는 Element의 ID로 변환되며, null 또는 빈 문자열 값은 제외됩니다.
		 * @returns 
		 */
		private _getNormalizedAriaSet() {
			let ariaSet = this.aria();
			if (ariaSet["aria-label"] != null) { // 숫자 0이 될 수 있어 null 체크함
				let ariaLabel = "" + ariaSet["aria-label"]; // decimal, number를 문자열로 변경 필요.
				ariaSet["aria-label"] = ariaLabel.substring(0, _MAX_ARIA_LABEL_LENGTH);
			}
			let resolvedAriaSet = _.mapObject(ariaSet, (val: any) => { return val instanceof Accessibility ? val._getAriaDomId() : val });
			return _.pick(resolvedAriaSet, (val: any) => { return val != null && val.length > 0 });
		}

		public _commitToShape(options: {
			bindContext?: bind.BindContext,
			shape: ufc.ElementShape
		}) {
			if (options.bindContext) {
				this._setBindContext(options.bindContext)
			}
			options.shape.attr = _mergeObject(options.shape.attr, this._getNormalizedAriaSet());
			this._setBindContext(null);
		}

		/**
		 * 설정된 접근성 속성을 제거 합니다.
		 * @param propertyName property 명
		 */
		public removeAria(propertyName: string): void {
			let key = _normalizeKey(propertyName);

			if (this._ariaSet.hasOwnProperty(key)) {
				delete this._ariaSet[key];
				this._owner?.redraw();
				if (this._owner?.getParent()?.type == "grid") {
					this._owner.getParent().redraw();
				}
			}
		}

		/**
		 * 특정 ARIA 속성에 바인딩 합니다.
		 * @param propertyName 바인딩할 속성 명. "aria-" 접두어는 생략할 수 있습니다.
		 * @returns 해당 속성에 대한 바인딩 팩토리.
		 */
		public bind(propertyName: string): bind.IBindFactory {
			return this._bindables.bind(_normalizeKey(propertyName));
		}

		/**
		 * 특정 ARIA 속성에 대한 바인딩을 해제 합니다.
		 * @param propertyName 바인딩을 해제할 속성명. "aria-" 접두어는 생략할 수 있습니다.
		 */
		public unbind(propertyName: string): void {
			this._bindables.unbind(_normalizeKey(propertyName));
		}

		getBindContext(): bind.BindContext {
			return this._bindContext ?? this._owner?.getBindContext();
		}

		/**
		 * 바인딩 가능한 속성인지 확인합니다.
		 * @param propertyName 속성 명
		 * @return 확인 여부.
		 */
		public _isBindable(propertyName: string): boolean {
			return this._bindables.isBindable(_normalizeKey(propertyName))
		}

		/**
		 * 컨트롤의 바인드 속성 정보를 반환합니다.
		 * @param propertyName bind된 속성 명.
		 * @return BindInfo 속성
		 */
		public _getBindInfo(propertyName: string): bind.BindInfo {
			let property = this._bindables.getBindableProperty(_normalizeKey(propertyName));
			if (!property) {
				return null;
			}
			return property.getCurrentBindInfo();
		}

		/**
		 * 질의된 속성이 바인딩 가능 하며, 유효한 값을 얻을 수 있도록 바인딩이 구성되어 있는지 여부를 반환합니다.
		 * 바인딩이 구성되지 않고 단순 값이 지정된 경우에도 유효값을 얻을 수 있도록 구성된 것으로 취급됩니다.
		 * 
		 * 예를 들어 DataSet에 존재하지 않는 행인덱스에 대한 바인딩 등이 유효하지 않은 바인딩 입니다.
		 * @param propertyName 바인딩의 유효성 여부를 체크할 속성 명.
		 */
		public _isAvailableBinding(propertyName: string): boolean {
			let bindedProperty: bind.BindableProperty = this._bindables.getBindableProperty(_normalizeKey(propertyName));
			if (!bindedProperty) {
				return false;
			}
			let isActive: boolean = (bindedProperty.getDelegate() != null) ? bindedProperty.getDelegate().isActive() : true;
			return isActive && bindedProperty._isAvailable();
		}

		_setBindContext(ctx: bind.BindContext) {
			this._bindContext?._setContextOwner(null);
			this._bindContext = ctx;
			ctx?._setContextOwner(this);
		}

		_bindDidChange(property: string, oldInfo: bind.BindInfo, newInfo: bind.BindInfo): void {
			this._owner?.redraw();
			if (this._owner?.getParent()?.type == "grid") {
				this._owner.getParent().redraw();
			}
		}

		_getExpressionDelegates() {
			return [this._owner]
		}

		public _getOwner() {
			return this._owner;
		}

		public dispose(): void {
			this._bindables.dispose();
			this._bindContext?._setContextOwner(null);
			this._bindContext = null;
			this._owner = null;
			if (this._ariaSet) {
				Object.keys(this._ariaSet).forEach((key) => {
					let val = this._ariaSet[key];
					if (val instanceof Accessibility) {
						val._requestAriaRef(AriaRequestType.UNEXPOSE_REF);
					}
				});
			}
			this._ariaSet = null;
			this._subAccessibility?.forEach((each) => {
				each.dispose();
			});
			this._subAccessibility?.clear();
			this._subAccessibility = null;

		}
	}
}