namespace cpr.animation {
	/**
	 * @enum
	 * 애니메이션의 동작을 나타내는 타이밍 함수.
	 */
	export class TimingFunction {
		/**
		 * 균일한 속도로 작동하는 애니메이션 타이밍 함수 입니다.
		 */
		static LINEAR = "linear"



		/**
		 *  느리게 시작하여 점점 빨라지는 애니메이션 타이밍 함수 입니다.
		 */
		static EASE_IN = "ease-in"

		/**
		 * 빠르게 시작하여 점점 느려지는 애니메이션 타이밍 함수입니다.
		 */
		static EASE_OUT = "ease-out"

		/**
		 * 느리게 시작하여 점점 빨라졌다 다시 느려지는 애니미에션 타이밍 함수입니다.
		 */
		static EASE_IN_OUT = "ease-in-out"



		/**
		 * 느리게 시작하여 점점 빨라지는 애니메이션 타이밍 함수 입니다. EASE_IN 보다 속도 변경이 더 강조 됩니다.
		 */
		static EASE_IN_CUBIC = "cubic-bezier(0.55, 0.055, 0.675, 0.19)";

		/**
		 * 빠르게 시작하여 점점 느려지는 애니메이션 타이밍 함수입니다. EASE_OUT 보다 속도 변경이 더 강조 됩니다.
		 */
		static EASE_OUT_CUBIC = "cubic-bezier(0.215, 0.61, 0.355, 1)";

		/**
		 * 느리게 시작하여 점점 빨라졌다 다시 느려지는 애니미에션 타이밍 함수입니다. EASE_IN_OUT 보가 속도 변경이 더 강조 됩니다.
		 */
		static EASE_IN_OUT_CUBIC = "cubic-bezier(0.645, 0.045, 0.355, 1)";



		/**
		 *  반대 방향으로 살짝 이동한 뒤 점점 빨라지는 애니메이션 타이밍 함수 입니다.
		 */
		static EASE_IN_BACK = "cubic-bezier(0.6, -0.28, 0.735, 0.045)";

		/**
		 *  점점 빨라져 목적지점을 초과한 뒤 다시 돌아오는 애니메이션 타이밍 함수 입니다.
		 */
		static EASE_OUT_BACK = "cubic-bezier(0.175, 0.885, 0.32, 1.275)";

		/**
		 * 반대 방향으로 살짝 이동한 뒤, 점점 빨라져 목적지점을 초과한 뒤 다시 돌아오는 애니메이션 타이밍 함수 입니다.
		 */
		static EASE_IN_OUT_BACK = "cubic-bezier(0.68, -0.55, 0.265, 1.55)";

		/**
		 * 주어진 애니메이션 함수의 시작과 끝이 뒤바뀐 타이밍 함수 이름을 얻습니다.
		 * @param timingFunction 반대 타이밍 함수를 얻을 함수 명.
		 */
		public static getReverseFunction(timingFunction: string) {
			switch (timingFunction) {
				case this.EASE_IN: return this.EASE_OUT
				case this.EASE_OUT: return this.EASE_IN

				case this.EASE_IN_CUBIC: return this.EASE_OUT_CUBIC;
				case this.EASE_OUT_CUBIC: return this.EASE_IN_CUBIC;

				case this.EASE_IN_BACK: return this.EASE_OUT_BACK;
				case this.EASE_OUT_BACK: return this.EASE_IN_BACK;

				default: {
					return timingFunction
				}
			}
		}

		/**
		 * 주어진 타이밍 함수 이름을 사용하여 베지어 곡선 매트릭스 성분을 얻습니다.
		 * @param timingFunction 타이밍 함수 이름.
		 */
		public static toMatrix(timingFunction: string) {
			switch (timingFunction) {
				case TimingFunction.LINEAR: return [0, 0, 1, 1];
				case TimingFunction.EASE_IN: return [0.42, 0, 1, 1];
				case TimingFunction.EASE_OUT: return [0, 0, 0.58, 1];
				case TimingFunction.EASE_IN_OUT: return [0.42, 0, 0.58, 1];
				case TimingFunction.EASE_IN_CUBIC: return [0.55, 0.055, 0.675, 0.19];
				case TimingFunction.EASE_OUT_CUBIC: return [0.215, 0.61, 0.355, 1];
				case TimingFunction.EASE_IN_OUT_CUBIC: return [0.645, 0.045, 0.355, 1];
				case TimingFunction.EASE_IN_BACK: return [0.6, -0.28, 0.735, 0.045];
				case TimingFunction.EASE_OUT_BACK: return [0.175, 0.885, 0.32, 1.275];
				case TimingFunction.EASE_IN_OUT_BACK: return [0.68, -0.55, 0.265, 1.55];
				default: throw new exceptions.IllegalArgumentException()
			}
		}
	}
}