		private _unionWithBounds(x: number, y: number, width: number, height: number): Rectangle {
			let right = Math.max(this.right, x + width);
			let bottom = Math.max(this.bottom, y + height);
			this.x = Math.min(this.x, x);
			this.y = Math.min(this.y, y);
			this.width = right - this.x;
			this.height = bottom - this.y;
			return this;
		}

		private _unionWithLocation(x: number, y: number): Rectangle {
			if (x < this.x) {
				this.width += (this.x - x);
				this.x = x;
			} else {
				let right = this.x + this.width;
				if (x >= right) {
					right = x + 1;
					this.width = right - this.x;
				}
			}
			if (y < this.y) {
				this.height += (this.y - y);
				this.y = y;
			} else {
				let bottom = this.y + this.height;
				if (y >= bottom) {
					bottom = y + 1;
					this.height = bottom - this.y;
				}
			}
			return this;
		}

