/// <reference path="../../expression/EvaluationContext.ts" />
namespace cpr.controls.gridpart {
	/**
	 * 그리드에서 filterdialog-open 이벤트에서 사용자가 데이터를 정렬할 수 있도록 제공하기 위한 클래스
	 */
	export interface IDataRows {
		/**
		 * 필터 팝업에 보여질 데이터를 정렬합니다.
		 * 
		 * @example
		 * 그리드의 filterdialog-open 이벤트에서 e.data로 접근하여 그리드 헤더셀에 적용된 sort를 필터팝업에 적용하고 싶은 경우.
		 * =>  e.data.sort(grid.header.header.getSortCondition())
		 * 
		 * @param condition 정렬 조건. (ex. column1, column2 desc)
		 */
		sort(condition: expression_string): void;
	}
	/**
	 * 데이터셋 행배열을 관리하는 클래스입니다. <br>
	 * 현재는 sort기능만 제공하고 있습니다.
	 */
	export class DataRows implements IDataRows {
		private _dataSet: data.DataCollection;
		private _dataRowList: data.IDataRow[];

		constructor(dataSet: data.DataCollection, dataRowList: data.IDataRow[]) {
			this._dataSet = dataSet;
			if (dataRowList == null) {
				this._dataRowList = [];
			} else {
				this._dataRowList = dataRowList;
			}
		}

		/**
		 * 입력한 정렬 조건으로 데이터를 정렬합니다.
		 * @param condition		정렬 조건.
		 */
		public sort(condition: string): void {
			let rows: { datarow: data.DataRow, index: number }[] = this._dataRowList.map((dataRow: data.DataRow, index: number) => {
				return { "datarow": dataRow, "index": index };
			});

			if (condition != null && condition != "") {
				let sortExpr: expression.Expression = new expression.Expression(condition);
				let comparator: (a, b) => number = sortExpr.asComparator();
				rows = rows.sort((a: { datarow: data.DataRow, index: number }, b: { datarow: data.DataRow, index: number }) => {
					let compare: number = comparator(a.datarow, b.datarow);
					if (compare == 0) {
						if (a.index < b.index) {
							return -1;
						} else if (a.index == b.index) {
							return 0;
						}
						return 1;
					}
					return compare;
				});
			}


			this._dataRowList = rows.map((row: { datarow: data.DataRow, index: number }) => {
				return row.datarow;
			});
		}

		public _getSize(): number {
			return this._dataRowList.length;
		}

		public _getDataRow(idx: number): data.IDataRow {
			return this._dataRowList[idx];
		}

		/**
		 * string -> string, decimal -> string, number -> number
		 * @param columnName 
		 */
		public _getValues(columnName: string): any[] {
			let values: any[] = [];
			let rowCount: number = this._dataRowList.length;
			let header: data.header.Header = this._dataSet.getHeader(columnName);

			if (header._isExpressionHeader()) { // expression header일 경우
				let exprHeader: data.header.ExpressionHeader = header as data.header.ExpressionHeader;
				let func: Function = exprHeader.getFunction();
				if (func != null) {
					for (let i = 0; i < rowCount; i++) {
						let dataRow: data.IDataRow = this._dataRowList[i];
						values[values.length] = func(dataRow);
					}
				}
			} else { // 일반 header 일 경우
				let dataType: data.tabledata.DataType = header.getDataType();
				if (dataType == data.tabledata.DataType.DECIMAL) {
					for (let i = 0; i < rowCount; i++) {
						let decimalValue: (string | number | foundation.DecimalType | ufc.StyledString) = this._dataRowList[i].getValue(columnName);
						values[values.length] = decimalValue.toString();
					}
				} else {
					for (let i = 0; i < rowCount; i++) {
						values[values.length] = this._dataRowList[i].getValue(columnName);
					}
				}
			}

			return values;
		}

	}

}