namespace cpr.controls.layouts {
	/**
	 * 자동 크기 적용 방법.
	 */
	export enum AutoSizeType {
		/** 자동 크기를 사용하지 않습니다. */
		none = "none",

		/** 가로 세로 모두 자동 크기를 사용합니다. */
		both = "both",

		/** 너비만 자동 크기를 사용합니다. */
		width = "width",

		/** 높이만 자동 크기를 사용합니다. */
		height = "height"
	}

	export function _hasAutoWidth(type: AutoSizeType): boolean {
		switch (type) {
			case AutoSizeType.both:
			case AutoSizeType.width:
				return true;

			default:
				return false;
		}
	}

	export function _hasAutoHeight(type: AutoSizeType): boolean {
		switch (type) {
			case AutoSizeType.both:
			case AutoSizeType.height:
				return true;

			default:
				return false;
		}
	}
}