namespace cpr {
	function _createSpreadCopyFunction(): (sources: object) => object {
		return new Function("obj", `
			return { ...obj};
		`) as (sources: object) => object;
	}

	/**
	 * 배열의 얕은 복제본을 얻습니다.
	 * @param source 원본 배열.
	 */
	export function _shallowCopy<T extends any>(source: T[]): T[];
	/**
	 * 일반 객체의 얕은 복제본을 얻습니다.
	 * @param source 원본 객체.
	 */
	export function _shallowCopy<T extends object>(source: T): T;
	/**
	 * {@link CSet}의 얕은 복제본을 얻습니다.
	 * @param source 원본 {@link CSet}.
	 */
	export function _shallowCopy<T>(source: CSet<T>): CSet<T>;
	export function _shallowCopy(src: any): any {
		switch (typeof src) {
			case "object":
				if (src == null)
					return src;
				else if (_isArray(src)) {
					return _shallowCopyArray(src);
				}
				else if (CSet._isCSet(src)) {
					return CSet._shallowCopy(src);
				}
				else
					return _shallowCopyObject(src);
			default:
				return src;
		}
	}

	/**
	 * 객체의 얕은 사본을 만듭니다.
	 * 입력 객체는 플레인 객체이어야 합니다.
	 * @param src 원본 객체.
	 * @returns 사본 객체.
	 * @see _isPlainObject
	 */
	export const _shallowCopyObject: <T extends object>(src: T) => T = _ECMA._spreadOperator
		? _createSpreadCopyFunction()
		: (source: object) => _assign({}, source)
		;

	/**
	 * 배열을 복제 합니다.
	 * @param array 복제할 배열.
	 * @param copyPredicate 배열의 하위요소들에 대하여 깊은 복제를 적용 할 것이지 여부를 평가하는 함수. 
	 * 이 평가 함수가 true 반환한 경우에만 배열 요소들도 깊은 복제가 일어납니다. false를 반환하면 같은 값을 사용하게 됩니다.
	 * 생략한 경우 일반 JSON 객체만 복제를 허용 합니다.
	 * 
	 * @see _isPlainObject
	 */
	export function _deepCopy<T>(array: T[], copyPredicate?: (value: object) => boolean): T[];

	/**
	 * JSON 객체를 복제 합니다.
	 * Object가 아닌 클래스의 인스턴스 객체는 복제 할 수 없습니다.
	 * @param obj 복제할 Object, 일반적으로 JSON.
	 * @param copyPredicate 객체의 하위요소들에 대하여 깊은 복제를 적용 할 것이지 여부를 평가하는 함수. 
	 * 이 평가 함수가 true 반환한 경우에만 속성 값들도 깊은 복제가 일어납니다. false를 반환하면 같은 값을 사용하게 됩니다.
	 * 생략한 경우 일반 JSON 객체만 복제를 허용 합니다.
	 * 
	 * @see _isPlainObject
	 */
	export function _deepCopy<T extends object>(obj: T, copyPredicate?: (value: object) => boolean): T;

	/**
	 * 셋을 복사 합니다.
	 * @param set 복제할 셋.
	 * @param copyPredicate 셋의 하위요소들에 대하여 깊은 복제를 적용 할 것이지 여부를 평가하는 함수. 
	 * 이 평가 함수가 true 반환한 경우에만 요소들도 깊은 복제가 일어납니다. false를 반환하면 같은 값을 사용하게 됩니다.
	 * 생략한 경우 일반 JSON 객체만 복제를 허용 합니다.
	 * 
	 * @see _isPlainObject
	 */
	export function _deepCopy<T>(set: CSet<T>, copyPredicate?: (value: object) => boolean): CSet<T>;
	export function _deepCopy(obj: object, copyPredicate: (value: object) => boolean = e => _isPlainObject(e)): any {
		switch (typeof obj) {
			case "object": {
				// 널
				if (obj === null) {
					return null;
				}

				// 배열 복제
				else if (_isArray(obj)) {
					return _deepCopyArray(obj, copyPredicate);
				}

				// 셋 복제
				else if (CSet._isCSet(obj)) {
					return _deepCopySet(obj, copyPredicate);
				}

				// 일반 객체 복제
				else if (_isPlainObject(obj)) {
					return _deepCopyObject(obj, copyPredicate);
				}

				// 기타 다른 객체
				else {
					if (copyPredicate(obj)) {
						throw new exceptions.IllegalArgumentException("Given object could not be deep copy.")
					} else {
						return obj;
					}
				}
			}

			default:
				return obj;
		}
	}

	/**
	 * 
	 * @param obj 복제할 객체. 이 객체는 반드시 PlainObject여야 합니다. {@link _isPlainObject} 를 참조 하십시오.
	 * @param copyPredicate 셋의 하위요소들에 대하여 깊은 복제를 적용 할 것이지 여부를 평가하는 함수. 
	 * 이 평가 함수가 true 반환한 경우에만 요소들도 깊은 복제가 일어납니다. false를 반환하면 같은 값을 사용하게 됩니다.
	 * 생략한 경우 일반 JSON 객체만 복제를 허용 합니다.
	 * @returns 복제된 사본.
	 */
	export function _deepCopyObject<T extends object>(obj: T, copyPredicate: (value: object) => boolean = e => _isPlainObject(e)): T {
		if (!obj) {
			return obj;
		}

		return _tap({}, result => {
			Object.getOwnPropertyNames(obj).forEach(key => {
				let value = obj[key];
				result[key] = !!value && typeof value == "object" && copyPredicate(value)
					? _deepCopy(value, copyPredicate)
					: value
			});
		}) as T;
	}

	/**
	 * 배열을 복제 합니다.
	 * @param array 복제할 배열.
	 * @param copyPredicate 배열의 하위요소들에 대하여 깊은 복제를 적용 할 것이지 여부를 평가하는 함수. 
	 * 이 평가 함수가 true 반환한 경우에만 배열 요소들도 깊은 복제가 일어납니다. false를 반환하면 같은 값을 사용하게 됩니다.
	 * 생략한 경우 일반 JSON 객체만 복제를 허용 합니다.
	 */
	export function _deepCopyArray<T>(array: T[], copyPredicate: (value: object) => boolean = e => _isPlainObject(e)): T[] {
		if (!_isArray(array)) {
			return array;
		}

		return array.map(e => {
			return !!e && typeof e == "object" && copyPredicate(e)
				? _deepCopy(e as any, copyPredicate)
				: e;
		}) as T[];
	}

	/**
	 * 셋을 복사 합니다.
	 * @param set 복제할 셋.
	 * @param copyPredicate 셋의 하위요소들에 대하여 깊은 복제를 적용 할 것이지 여부를 평가하는 함수. 
	 * 이 평가 함수가 true 반환한 경우에만 요소들도 깊은 복제가 일어납니다. false를 반환하면 같은 값을 사용하게 됩니다.
	 * 생략한 경우 일반 JSON 객체만 복제를 허용 합니다.
	 * 
	 * @see _isPlainObject
	 */
	export function _deepCopySet<T>(set: CSet<T>, copyPredicate: (value: object) => boolean = e => _isPlainObject(e)): CSet<T> {
		if (CSet._isCSet(set) === false) {
			return set;
		}

		return _tap(_createSet(), newSet => {
			set.forEach(e => {
				newSet.add(
					!!e && typeof e == "object" && copyPredicate(e)
						? _deepCopy(e, copyPredicate)
						: e
				);
			})
		});
	}
}