/// <reference path="./PropertyDelegate.ts"/>

namespace cpr.bind {
	/**
	 * @nonapi
	 */
	export class SimpleDelegate extends PropertyDelegate {
		private _value: any;

		constructor(initialValue: any = null) {
			super()
			this._value = initialValue;
		}

		override get() {
			return this._value;
		}

		override set(newValue: any) {
			this._value = newValue;
		}

		override isActive() {
			return true;
		}

		override _isAvailable() {
			return true;
		}

		override getBindInfo() {
			return null;
		}

		override dispose() {

		}
	}
}