namespace cpr.geometry {
	/**
	 * 좌표 시스템
	 */
	export enum LocationCooridnate {
		/**
		 * 페이지 좌표계
		 */
		page = "page",

		/**
		 * 브라우저 스크롤 뷰 포트 바운딩 좌표계
		 */
		client = "client",

		/**
		 * 오프셋 좌표계
		 */
		offset = "offset",

		/**
		 * 스크린 좌표계
		 */
		screen = "screen"
	}

	/**
	 * 2차원 데카르트 좌표계 시스템 내에서의 한 지점을 추상화 합니다.
	 */
	export class Point implements Transposable {
		/**
		 * x좌표
		 */
		x: number;
		/**
		 * y좌표
		 */
		y: number;

		/**
		 * 새 위치 객체를 만듭니다.
		 * @param x x좌표 값.
		 * @param y y좌표 값.
		 */
		constructor(x: number, y: number) {
			this.x = x;
			this.y = y;
		}

		/**
		 * 이벤트로부터 Point를 얻습니다.
		 * @param e 
		 * @param coordinate 좌표계
		 */
		static fromEvent(e: UIEvent, coordinate: LocationCooridnate = LocationCooridnate.page) {
			if (_isTouchEvent(e)) {
				return this.fromTouch(e.touches.item(0), coordinate);
			}
			switch (coordinate) {
				case "page":
					return new Point(e["pageX"], e["pageY"]);

				case "client":
					return new Point(e["clientX"], e["clientY"]);

				case "offset":
					return new Point(e["offsetX"], e["offsetY"]);

				case "screen":
					return new Point(e["screenX"], e["screenY"]);

				default: throw new exceptions.IllegalArgumentException();
			}
		}

		/**
		 * 터치 이벤트로부터 Point를 얻습니다.
		 * @param e 
		 */
		static fromTouch(e: Touch, coordinate: LocationCooridnate = LocationCooridnate.page) {
			switch (coordinate) {
				case "page":
					return new Point(e["pageX"], e["pageY"]);

				case "client":
					return new Point(e["clientX"], e["clientY"]);

				case "offset":
					return new Point(e["offsetX"], e["offsetY"]);

				case "screen":
					return new Point(e["screenX"], e["screenY"]);

				default: throw new exceptions.IllegalArgumentException();
			}
		}

		/**
		 * 다른 포인트와 값이 같은지 비교합니다.
		 * @param other 다른 포인트.
		 * @param tolerance 허용 오차.
		 */
		public equals(other: Point, tolerance = 0): boolean {
			if (!other) {
				return false;
			}
			if (tolerance <= 0) {
				return this === other || this.x === other.x && this.y === other.y;
			}
			else {
				return this.getDistance(other) <= tolerance;
			}
		}

		/**
		 * 사본 객체를 얻습니다.
		 */
		public getCopy(): Point {
			return new Point(this.x, this.y);
		}

		/**
		 * 다른 지점과의 차이를 얻습니다.
		 * @param p 차이을 얻을 다른 지점.
		 */
		public getDifference(p: Point) {
			return new Dimension(this.x - p.x, this.y - p.y);
		}

		/**
		 * 다른 점까지의 거리를 얻습니다.
		 * @param p 거리를 구할 다른 점.
		 */
		public getDistance(p: Point) {
			let dx = p.x - this.x;
			let dy = p.y - this.y;
			return Math.sqrt(dx * dx + dy * dy);
		}

		/**
		 * x축과 y축을 반전 시킵니다.
		 */
		public transpose(): this {
			let temp = this.x;
			this.x = this.y;
			this.y = temp;
			return this;
		}

		/**
		 * 축이 반전된 사본을 얻습니다.
		 */
		public getTransposed(): Point {
			return this.getCopy().transpose();
		}

		/**
		 * 원점을 기준으로 반전 시킵니다.
		 */
		public negate(): Point {
			this.x = -this.x;
			this.y = -this.y;
			return this;
		}

		/**
		 * 원점을 기준으로 반전된 좌표의 사본을 얻습니다.
		 */
		public getNegated(): Point {
			return this.getCopy().negate();
		}

		/**
		 * 원점을 기준으로 스케일을 적용 시킵니다.
		 * @param xFactor x축 스케일
		 * @param yFactor y축 스케일, 생략시 x축 스케일 값이 사용됩니다.
		 */
		public scale(xFactor: number, yFactor: number = undefined) {
			if (typeof (yFactor) === "undefined") {
				yFactor = xFactor;
			}

			this.x = this.x * xFactor;
			this.y = this.y * yFactor;
			return this;
		}

		/**
		 * 스케일 된 사본 객체를 얻습니다.
		 * @param xFactor x축 스케일
		 * @param yFactor y축 스케일, 생략시 y축 스케일 값이 사용됩니다.
		 */
		public getScaled(xFactor: number, yFactor: number = undefined) {
			return this.getCopy().scale(xFactor, yFactor);
		}

		/**
		 * 이 좌표를 주어진 값 만큼 축 이동 합니다.
		 * @param delta 이동량
		 */
		public translate(delta: Dimension): Point;

		/**
		 * 이 좌표를 주어진 값 만큼 축 이동 합니다.
		 * @param delta 이동량
		 */
		public translate(delta: Point): Point;

		/**
		 * 이 좌표를 주어진 값 만큼 축 이동 합니다.
		 * @param dx x축 이동량.
		 * @param dy y축 이동량.
		 */
		public translate(dx: number, dy: number): Point;
		public translate(): Point {
			let args = _toArray(arguments);
			let dx = Number.NaN;
			let dy = Number.NaN;

			switch (args.length) {
				case 1: {
					let first = args[0];
					if (first instanceof Point) {
						dx = first.x;
						dy = first.y;
					} else if (first instanceof Dimension) {
						dx = first.width;
						dy = first.height;
					}
					break;
				}

				case 2: {
					if (typeof args[0] == "number" && typeof args[1] == "number") {
						dx = args[0];
						dy = args[1];
					}
					break;
				}
			}

			if (isNaN(dx) || isNaN(dy)) {
				throw new exceptions.IllegalArgumentException();
			}

			this.x += dx;
			this.y += dy;

			return this;
		}


		/**
		 * Dimension 객체의 width,height를 합하여 위치 값을 변경합니다.
		 * @param d 
		 * @deprecated {@link translate}를 사용하시기 바랍니다.
		 */
		public translateByDimension(d: Dimension): Point {
			this.x += d.width;
			this.y += d.height;
			return this;
		}

		/**
		 * Point 객체의 x,y를 합하여 위치 값을 변경합니다.
		 * @param d 
		 * @deprecated {@link translate}를 사용하시기 바랍니다.
		 */
		public translateByPoint(d: Point): Point {
			this.x += d.x;
			this.y += d.y;
			return this;
		}

		/**
		 * 축이 이동된 사본을 얻습니다.
		 * @param delta 축 이동량.
		 */
		public getTranslated(delta: Point): Point

		/**
		 * 축이 이동된 사본을 얻습니다.
		 * @param delta 축 이동량.
		 */
		public getTranslated(delta: Dimension): Point

		/**
		 * 축이 이동된 사본을 얻습니다.
		 * @param dx x축 이동량.
		 * @param dy y축 이동량.
		 */
		public getTranslated(dx: number, dy: number): Point;
		public getTranslated(): Point {
			let args = _toArray(arguments);
			let copy = this.getCopy();
			copy.translate.apply(copy, args);
			return copy;
		}

		/**
		 * Dimension 객체를 통해 변경된 새로운 객체를 반환합니다.
		 * @param d 
		 * @deprecated {@link getTranslated}를 사용하시기 바랍니다.
		 */
		public getTranslatedByDimension(d: Dimension): Point {
			return this.getCopy().translateByDimension(d);
		}

		/**
		 * Point 객체를 통해 변경된 새로운 객체를 반환합니다.
		 * @param d 
		 * @deprecated {@link getTranslated}를 사용하시기 바랍니다.
		 */
		public getTranslatedByPoint(d: Point): Point {
			return this.getCopy().translateByPoint(d);
		}
	}
}