/// <reference path="../Submission.ts"/>


namespace cpr.protocols.request {
	/**
	 * @private
	 * MultipartRequestBuilder는 RequestEncoder에 의한 ContentType 변경을 지원하지 않음.
	 */
	export class MultipartRequestBuilder extends URLEncodedRequestBuilder {
		public static _assembleMultipartEncodingResult(formData: FormData, encodingResult: EncodingResult): FormData {
			let key: string = encodingResult.key;
			let value: {} | string = encodingResult.content;

			if (key == null && utils.ParamUtil.isJSON(value)) {
				let keys: string[] = Object.keys(value);
				keys.forEach((k: string) => {
					let v: any = value[k];
					let jsonstring: string = this._getJsonString(v);
					formData.append(k, jsonstring);
				});
			} else {
				let jsonstring: string = this._getJsonString(value);
				formData.append(key, jsonstring);
			}

			return formData;
		}

		constructor() {
			super();
		}

		public getContentType(): string {
			// multipart 인 경우 boundary 가 추가되어 자동으로 입력됨.
			return null;
		}

		protected _buildSpecific(submission: Submission): any {
			if (Submission._HASBODY_METHOD.indexOf(submission.method) === -1) {
				console.warn("Submission(\"" + submission.id + "\") method has been changed to POST. \"" + Submission.MEDIA_MULTIPART + "\" media types can not use " + submission.method.toUpperCase() + " method. Available methods [" + Submission._HASBODY_METHOD.join(",").toUpperCase() + "]");
				submission.method = Submission.METHOD_POST;
			}

			// Basic Support : Chrome 7.0, Edge (yes), Firefox 4.0, IE 10, Opera 12, Safari 5
			let formData: FormData = new FormData();

			// files
			let fileParamNames: string[] = submission.getFileParameterNames();
			fileParamNames.forEach((name: string) => {
				let values: File[] = submission.getFileParameters(name);
				values.forEach((value: File) => {
					if (value && value.name) {
						formData.append(name, value, value.name); // IE11
					} else {
						formData.append(name, value); // IE10
					}
				});
			});

			let requestEncoderSpec: RequestEncoderSpec = submission._getRequestEncoder();
			if (requestEncoderSpec && requestEncoderSpec.encoder) {
				let requestString: string = null;

				if (requestEncoderSpec.usingBuildData) {
					requestString = this._buildRequestString(submission);
				}

				let returnValue: Promise<EncodingResult> | EncodingResult = requestEncoderSpec.encoder(submission, requestString);
				if (returnValue instanceof Promise) {
					return returnValue.then((encodingResult: EncodingResult) => {
						return MultipartRequestBuilder._assembleMultipartEncodingResult(formData, encodingResult);
					});
				} else {
					return MultipartRequestBuilder._assembleMultipartEncodingResult(formData, returnValue);
				}
			} else {
				this._buildFormDataRequest(submission, formData);

				return formData;
			}
		}

		private _buildFormDataRequest(submission: Submission, formData: FormData): void {
			// check requestObject
			let requestObject: Object = submission.getRequestObject();
			if (requestObject != null) {
				let jsonstring: string = JSON.stringify(requestObject);

				formData.append(AbstractRequestBuilder.REQOBJ_PARAMNAME, jsonstring);
			}

			// parameters
			let paramNames: string[] = submission.getParameterNames();
			paramNames.forEach((name: string) => {
				let values: string[] = submission.getParameters(name);
				values.forEach((value: string) => {
					formData.append(name, value);
				});
			});

			// datamap/dataset
			let requestDataCount: number = submission.getRequestDataCount();
			for (let idx: number = 0; idx < requestDataCount; idx++) {
				let requestData: RequestData = submission.getRequestData(idx);
				let alias: string = this._getRequestAlias(requestData);
				if (requestData.data instanceof data.DataSet) {
					let dataSet: data.DataSet = requestData.data as data.DataSet;
					this._buildDataSetFormData(submission, dataSet, alias, formData, requestData.payload);
				} else {
					let dataMap: data.DataMap = requestData.data as data.DataMap;
					this._buildDataMapFormData(submission, dataMap, alias, formData);
				}
			}
		}

		private _buildDataSetFormData(submission: Submission, dataSet: data.DataSet, alias: string, formData: FormData, payload: PayloadType): void {
			let dataDelimiter: string = super._createDataDelimiter();

			this._loadPayload(submission, dataSet, payload, (rowdata: data.RowConfigInfo, additionalParam: { [key: string]: string }, stateText: string) => {
				for (let columnName in rowdata) {
					let name: string = dataDelimiter + columnName;
					let value: string | number | boolean = rowdata[columnName];
					if (value == null) {
						value = "";
					}
					if (typeof value === "number" || typeof value === "boolean") {
						value = String(value);
					}
					formData.append(name, value);
				}

				this._applyFormAdditionalParam(formData, additionalParam, dataDelimiter);

				let statName: string = dataDelimiter + "sts"; // 공통화
				formData.append(statName, stateText);
			});

			formData.append(super._getDataDelimiterParamName(), dataDelimiter);

			if (alias) {
				formData.append(dataDelimiter, alias);
			}
			formData.append(dataDelimiter + "tp", "ds"); // parameter group type
		}

		private _buildDataMapFormData(submission: Submission, dataMap: data.DataMap, alias: string, formData: FormData): void {
			let columnNames: string[] = dataMap.getColumnNames();
			let dataDelimiter: string = super._createDataDelimiter(); // DataMap 별로 생성
			columnNames.forEach((columnName: string) => {
				let name: string = dataDelimiter + columnName;
				let value: string = dataMap.getString(columnName);
				if (value == null) {
					value = "";
				}
				formData.append(name, value);
			});

			this._applyFormAdditionalParam(formData, submission._handleDataMap(dataMap), dataDelimiter);

			formData.append(super._getDataDelimiterParamName(), dataDelimiter);

			if (alias) {
				formData.append(dataDelimiter, alias);
			}
			formData.append(dataDelimiter + "tp", "dm"); // parameter group type
		}

		private _applyFormAdditionalParam(formData: FormData, additionalParam: { [key: string]: string }, dataDelimiter: string): void {
			if (additionalParam) {
				for (let key in additionalParam) {
					let name: string = dataDelimiter + key;
					let value: string = additionalParam[key];
					if (value == null) {
						value = "";
					}
					formData.append(name, value);
				}
			}
		}

	}


}