	export interface CGridEventOptions extends CEventOption {
		/** 
		 * 이벤트가 발생한 GridRow 객체.
		 */
		row?: controls.provider.GridRow;
		/** 
		 * 이벤트가 발생한 행의 data row index.
		 */
		rowIndex?: number;
		/** 
		 * 이벤트가 발생한 행의 view row index.
		 */
		viewRowIndex?: number;
		/** 
		 *현재 클릭한 GridRowGroup 객체. (rowgroup-click, rowgroup-dblclick 이벤트에서 사용)
		 */
		rowgroup?: controls.provider.GridRowGroup;
		/** 
		 * 이벤트가 발생한 cell index.
		 */
		cellIndex?: number;
		/** 
		 * 이벤트가 발생한 cell의 columnName.
		 */
		columnName?: string;
		/** 
		 * 이전에 선택 또는 편집되어 행 정보.<br>
		 * (인덱스 배열 또는 cellPosition 배열 또는 GridRow객체)
		 */
		oldSelection?: any;
		/** 
		 * 현재 선택 또는 편집한 행 정보.<br>
		 * (인덱스 배열 또는 cellPosition 배열 또는 GridRow객체)
		 */
		newSelection?: any;
		/** 
		 * 편집 중인 데이터에 대한 반영 여부.<br>
		 * (before-editrow-change 이벤트에서 사용)
		 */
		isCommit?: boolean;
		/**
		 * 변경되기 전 값.
		 */
		oldValue?: any;
		/** 
		 * 현재 값.
		 */
		newValue?: any;
		/** 
		 * 이벤트를 통해 전달되는 데이터 .
		 */
		data?: any;
		/**
		 * 이벤트가 발생한 그리드 내의 타겟명.<br>
		 * header, detail, footer, rowgroup
		 */
		relativeTargetName?: "header" | "detail" | "footer" | "rowgroup";
		/**
		 * 이벤트가 발생한 그리드 그룹의 밴드명.<br>
		 * gheader, gfooter
		 */
		groupBandName?: "gheader" | "gfooter";
		/**
		 * 이벤트가 발생한 디테일 셀이 실제 그려진 사이즈.
		 */
		cellBoundingRect?: geometry.Rectangle;
	}

	/**
	 * Grid 내부 변경 시 발생하는 이벤트.
	 * 사용하는 이벤트 : 
	 * row-check, row-uncheck, header-check, header-uncheck, 
	 * insert, before-insert, delete, before-delete, filterdialog-open, filterdialog-close, cell-moved
	 */
	export class CGridEvent extends CEvent {

		constructor(type: string, options?: CGridEventOptions) {
			super(type, options);

			if (options != null) {
				this._setTargetObject(options);
			}
		}

		/**
		 * GridRow 객체를 반환합니다.
		 * @readonly
		 */
		get row(): cpr.controls.provider.GridRow {
			return this._getOption("row");
		}

		/**
		 * Grid data기준의 rowIndex를 반환합니다.
		 * @readonly
		 */
		get rowIndex(): number {
			return this._getOption("rowIndex");
		}

		/**
		 * Cell index를 반환합니다.
		 * @readonly
		 */
		get cellIndex(): number {
			return this._getOption("cellIndex");
		}

		/**
		 * 이벤트가 발생한 컬럼명을 반환합니다.
		 * @readonly
		 */
		get columnName(): string {
			return this._getOption("columnName");
		}

		/**
		 * 이벤트를 통해 전달되는 데이터를 반환합니다.
		 */
		get data(): any {
			// "before-cell-resized", "cell-resized", "before-cell-moved", "cell-moved", "filterdialog-open" 이벤트에서 사용
			return this._getOption("data");
		}

		/**
		 * 이벤트를 통해 전달되는 데이터를 세팅합니다.
		 */
		set data(value: any) {
			// "before-cell-resized", "cell-resized", "before-cell-moved", "cell-moved", "filterdialog-open" 이벤트에서 사용
			this._setOption("data", value);
		}

		/**
		 * 이벤트가 발생한 그리드 내의 타겟명을 반환합니다.
		 * @readonly
		 */
		get relativeTargetName(): "header" | "detail" | "footer" | "rowgroup" {
			return this._getOption("relativeTargetName");
		}

	}

