	/**
	 * Grid 내부 Clipboard 이벤트
	 * 사용하는 이벤트 : copy, before-paste, paste
	 */
	export class CGridClipboardEvent extends CGridEvent {

		// 데이터 수정(할당) 여부를 체크할 프라이빗 플래그 변수 선언
		private _dataModified: boolean = false;

		constructor(type: string, options?: CGridEventOptions) {
			super(type, options);
		}

		/**
		 * 이벤트를 통해 전달되는 데이터를 반환합니다.<br>
		 * 반환값은 문자열(string)형태의 클립보드 텍스트 입니다.<br>
		 * 붙여넣기(paste)시 복사된 텍스트 내에 줄바꿈 문자가 포함된 경우, 단일 문자열인 `data` 속성만으로는 각 행/열의 구분과 셀 내부의 줄바꿈을 정확히 식별하기 어렵습니다.<br>
		 * 이 경우에는 {@link getTableData} 메소드를 사용하여 2차원 배열 형태로 파싱된 원본 데이터를 반환받는 것을 권장합니다.
		 * @returns 이벤트를 통해 전달되는 데이터 (문자열 형태의 클립보드 텍스트)
		 */
		override get data(): any {
			return this._getOption("data");
		}

		/**
		 * 이벤트를 통해 전달되는 데이터를 설정합니다.<br>
		 * 설정값은 문자열(string) 또는 문자열 2차원 배열(string[][]) 모두 가능합니다.
		 * @param value 데이터로 설정할 문자열 또는 문자열 2차원 배열
		 */
		override set data(value: any) {
			this._dataModified = true;
			this._setOption("data", value);
		}

		/**
		 * 데이터(e.data)가 명시적으로 수정(할당)되었는지 여부를 반환합니다.
		 * @private
		 */
		public _isDataModified(): boolean {
			return this._dataModified;
		}

		/**
		 * 붙여넣기(paste)될 원본 데이터를 이차원 배열 형태(string[][])로 반환합니다.<br>
		 * 각 요소는 셀에 복사될 문자열 데이터입니다.
		 * @returns 원본 테이블 데이터
		 * @readonly
		 */
		public getTableData(): string[][] {
			return this._getOption("tableData");
		}

	}
