

namespace cpr.protocols.request {

	/**
	 * @private
	 */
	export class DefaultRequestBuilderFactory implements RequestBuilderFactory {
		private static _instance: DefaultRequestBuilderFactory;

		public static get INSTANCE(): DefaultRequestBuilderFactory {
			if (!DefaultRequestBuilderFactory._instance) {
				DefaultRequestBuilderFactory._instance = new DefaultRequestBuilderFactory();
			}
			return DefaultRequestBuilderFactory._instance;
		}


		private _builderMap: { [key: string]: RequestBuilder };
		private _defaultBuilder: RequestBuilder; /* Singleton */
		private _filedownloadBuilder: FormRequestBuilder; /* Singleton */


		constructor() {
			this._init();
		}

		public getRequestBuilder(submission: AbstractSubmission): RequestBuilder {
			if (ResponseType[submission.responseType] == ResponseType.filedownload) {
				return this._filedownloadBuilder; /* TODO refactoring */
			}

			let requestBuilder: RequestBuilder = this._builderMap[submission.mediaType];
			if (requestBuilder) {
				return requestBuilder;
			}

			return this._defaultBuilder;
		}

		private _init(): void {
			this._builderMap = {};

			this._builderMap[Submission.MEDIA_URLENCODED] = new URLEncodedRequestBuilder();
			this._builderMap[Submission.MEDIA_URLENCODED_SIMPLE] = new URLEncodedSimpleRequestBuilder();
			this._builderMap[Submission.MEDIA_URLENCODED_MASS] = new URLEncodedMassRequestBuilder();
			this._builderMap[Submission.MEDIA_JSON] = new JSONRequestBuilder();
			this._builderMap[Submission.MEDIA_JSON_MASS] = new JSONMassRequestBuilder();
			this._builderMap[Submission.MEDIA_MULTIPART_JSON] = new MultipartJSONRequestBuilder();
			this._builderMap[Submission.MEDIA_MULTIPART] = new MultipartRequestBuilder();
			this._builderMap[Submission.MEDIA_MULTIPART_SIMPLE] = new MultipartSimpleRequestBuilder();

			this._defaultBuilder = this._builderMap[Submission.MEDIA_URLENCODED];
			this._filedownloadBuilder = new FormRequestBuilder(); /* TODO refactoring */
		}


	}

}