// /// <reference path="./CEvent.ts"/>
/// <reference path="./DOMEventWrapper.ts" />


namespace cpr.events {
	/**
	 * DataSet 이벤트 유형.
	 */
	export class DataEventType {
		/**
		 * build 메소드에 의해 데이터 구조가 재구성될 때 발생하는 이벤트.<br>
		 * 초기 생성시에도 발생합니다.
		 */
		static LOAD: string = "load";
		/**
		 * 로우가 추가되는 경우 발생하는 이벤트. <br>
		 * 발생 메소드 : addRow, addRowData, insertRow, insertRowData
		 */
		static INSERT: string = "insert";
		/**
		 * 로우가 추가되기 전에 발생하는 이벤트. <br>
		 * 발생 메소드 : addRow, addRowData, insertRow, insertRowData
		 */
		static BEFORE_INSERT: string = "before-insert";
		/**
		 * 로우가 삭제되는 경우 발생하는 이벤트.<br>
		 * 발생 메소드 : deleteRow
		 */
		static DELETE: string = "delete";
		/**
		 * 로우가 삭제되기 전에 발생하는 이벤트.<br>
		 * 발생 메소드 : deleteRow
		 */
		static BEFORE_DELETE: string = "before-delete";
		/**
		 * 로우가 업데이트되는 경우 발생하는 이벤트. <br>
		 * 발생 메소드 : setValue, updateRow
		 */
		static UPDATE: string = "update";
		/**
		 * 로우가 업데이트되기 전에 발생하는 이벤트. <br>
		 * 발생 메소드 : setValue, updateRow
		 */
		static BEFORE_UPDATE: string = "before-update";
		/**
		 * 정렬시 발생하는 이벤트.<br>
		 * 발생 메소드 : setSort, setSortExpr, clearSort
		 */
		static SORT: string = "sort";
		/**
		 * 필터시 발생하는 이벤트.<br>
		 * 발생 메소드 : setFilter, setFilterExpr, clearFilter
		 */
		static FILTER: string = "filter";
		/**
		 * 데이터 정보를 제거하는 경우 발생하는 이벤트.<br>
		 * 발생 메소드 : clear, (특정조건)build
		 * build 메소드 사용시 파라미터 isAdd=false 이거나 DataSet.alterColumnLayout="server" 일 때 이벤트가 발생합니다.
		 */
		static CLEAR: string = "clear";

		// 내부
		/**
		 * 데이터셋 이벤트 type
		 * @private
		 */
		static _ROWSTATE_CHANGE: string = "rowstate-change";
		/**
		 * 데이터셋 이벤트 type
		 * @private
		 */
		static _ROWLAYOUT_CHANGE: string = "rowlayout-change";
		/**
		 * 데이터셋 이벤트 type
		 * @private
		 */
		static _INSERT_ORG_ROW: string = "insert-org-row";
		/**
		 * 데이터셋 이벤트 type
		 * @private
		 */
		static _COMMIT: string = "commit";
		/**
		 * 데이터셋 이벤트 type
		 * @private
		 */
		static _REVERT: string = "revert";
		/**
		 * 데이터셋 이벤트 type
		 * @private
		 */
		static _REVERT_ROW: string = "revert-row";
		/**
		 * 데이터셋 이벤트 type
		 * @private
		 */
		static _FILTERED_SELECTION_ROW: string = "filtered-selection-row";
		/**
		 * 데이터셋 이벤트 type
		 * @private
		 */
		static _UPDATE_STATE: string = "state-update";
		/**
		 * 데이터셋 이벤트 type
		 * @private
		 */
		static _REAL_DELETE: string = "real-delete";
		/**
		 * 데이터셋 이벤트 type
		 * @private
		 */
		static _PUSH_ROW: string = "push-row";
		/**
		 * 데이터셋 이벤트 type
		 * @private
		 */
		static _CHANGE_LINKEDROW: string = "change-linkedrow";

		/**
		 * internal 이벤트의 경우 DataSet-DataView 연결시 후처리를 위해 연관된 데이터 객체에 모두 전파가 필요한 경우 사용됩니다.  
		 * 일반 사용자 이벤트의 경우 이벤트를 발생시킨 데이터 객체에만 이벤트를 전파하고, 연결된 타 데이터 객체에는 전파하지 않습니다.
		 */
		static _I_INSERT: string = "internal-insert";
		static _I_UPDATE: string = "internal-update";
		static _I_DELETE: string = "internal-delete";
		static _I_SORT: string = "internal-sort";
		static _I_FILTER: string = "internal-filter";
		static _I_CLEAR: string = "internal-clear";
		static _I_CLEAR_DATA: string = "internal-cleardata";
	}

	interface CDataEventOptions extends CEventOption {
		row?: cpr.data.Row;		// INSERTED / UPDATED event
		baseRow?: cpr.data.Row;	// INSERTED event (insertRow, insertRowData 시에만)
		beforeValue?: any;		// UPDATED event
		currentValue?: any;		// UPDATED event
		columnName?: string;	// UPDATED event (setValue 와 같은 단일 수정시에만 추가됨)

		/** @private */
		beforeRowData?: cpr.data.tabledata.RowData;
		/** @private */
		rowData?: cpr.data.tabledata.RowData;
		/** @private */
		beforeState?: cpr.data.tabledata.RowState;
		/** @private */
		currentState?: cpr.data.tabledata.RowState;
	}

	/**
	 * @noinstance
	 * DataSet 이벤트.
	 * DataSet의 변화 시 이벤트가 발생합니다.
	 */
	export class CDataEvent extends CEvent {

		/**
		 * @private
		 */
		constructor(type: string, options?: CDataEventOptions) {
			super(type, options);
		}

		/** 
		 * 로우 객체를 반환합니다.
		 * @readonly 
		 */
		get row(): cpr.data.Row {
			return this._getOption("row");
		}

		/** 
		 * insertRow시 insert에 기준이 된row 반환.
		 * @readonly 
		 */
		get baseRow(): cpr.data.Row {
			return this._getOption("baseRow");
		}

		/** 
		 * 변경되기 전 값을 반환합니다.
		 * @readonly 
		 */
		get beforeValue(): any {
			return this._getOption("beforeValue");
		}

		/** 
		 * 현재 값을 반환합니다.
		 * @readonly 
		 */
		get currentValue(): any {
			return this._getOption("currentValue");
		}

		/** 
		 * 컬럼 이름을 반환합니다.
		 * @readonly 
		 */
		get columnName(): string {
			return this._getOption("columnName");
		}

		/** 
		 * @private
		 * */
		get beforeRowData(): cpr.data.tabledata.RowData {
			return this._getOption("beforeRowData");
		}

		/** 
		 * @private
		 */
		get rowData(): cpr.data.tabledata.RowData {
			return this._getOption("rowData");
		}

		/** 
		 * @private 
		 */
		get beforeState(): cpr.data.tabledata.RowState {
			return this._getOption("beforeState");
		}

		/** 
		 * @private
		 */
		get currentState(): cpr.data.tabledata.RowState {
			return this._getOption("currentState");
		}
	}
}