namespace cpr.utils {
	/**
	 * @private
	 */
	export type Future<T> = {
		isDone(): boolean
		isCompletedExceptionally(): boolean;
		complete(result: T): void
		completeExceptionally(error: any): void
		asPromise(): Promise<T>
		get(): T
	}

	/**
	 * @private
	 */
	export class CompletableFuture<T> implements Future<T>{
		/**
		 * 이미 완료된 퓨쳐를 만듭니다.
		 * @param value 완료 결과 값.
		 * @returns 퓨쳐.
		 */
		public static createCompletedFuture<T>(value: T): Future<T> {
			let result = new CompletableFuture<T>();
			result.complete(value);
			return result;
		}

		_promise: Promise<T>;
		_resolve: (result: T) => void;
		_reject: (error: any) => void;
		_isCompleted: boolean = false;
		_isCompletedExceptionally: boolean = false;
		_resolvedValue: T = null;


		constructor() {
			this._promise = new Promise((resolve, reject) => {
				this._resolve = resolve;
				this._reject = reject;
			});
		}

		complete(result: T): void {
			if (this._isCompleted) {
				throw new exceptions.IllegalStateException();
			}

			this._isCompleted = true;
			this._resolvedValue = result;
			this._resolve(result);
		}

		completeExceptionally(error: any): void {
			if (this._isCompleted) {
				throw new exceptions.IllegalStateException();
			}
			this._isCompleted = true;
			this._isCompletedExceptionally = true;
			this._reject(error);
		}

		isCompletedExceptionally(): boolean {
			return this._isCompletedExceptionally;
		}

		isDone(): boolean {
			return this._isCompleted;
		}

		asPromise(): Promise<T> {
			return this._promise;
		}

		get(): T {
			if (this._isCompleted && !this._isCompletedExceptionally) {
				return this._resolvedValue;
			} else {
				return null;
			}
		}

	}
}