namespace cpr {
	// https://bpceee.github.io/posts/5
	const _TABBABLE_SELECTOR = [
		'input:not([tabindex^="-"]):not([disabled])',
		'select:not([tabindex^="-"]):not([disabled])',
		'textarea:not([tabindex^="-"]):not([disabled])',
		'button:not([tabindex^="-"]):not([disabled])',
		'a[href]:not([tabindex^="-"]):not([disabled])',
		'[tabindex]:not([tabindex^="-"]):not([disabled])',
		'iframe:not([tabindex^="-"]):not([disabled])'
	].join(", ");

	const _matchSelectorImpl = HTMLElement.prototype.matches
		?? HTMLElement.prototype["msMatchesSelector"]
		?? HTMLElement.prototype["webkitMatchesSelector"]
		;

	/**
	 * 노드가 셀렉터를 만족하는지 여부를 체크 합니다.
	 * @param element  검사할 노드.
	 * @param selector 평가할 셀렉터.
	 */
	export function _matchesSelector(element: Element, selector: string): boolean {
		return _matchSelectorImpl.call(element, selector);
	}

	/**
	 * 모든 부모 노드에 대한 스트림을 얻습니다.
	 * 가까운 노드 부터 출발 합니다.
	 * @param node 부모 노드들을 얻을 노드.
	 * @param includeSelf 스트림에 자기 자신을 포함시킬 것인지 여부.
	 */
	export function _getAllParentNodeStream(node: Node, includeSelf: boolean): Stream<Node> {
		return _createDynamicStream(node, includeSelf, (node: Node) => node.parentNode);
	}

	/**
	 * SVG는 IE에서 parentElement를 지원하지 않는 문제를 위한 구현.
	 * @param element 
	 * @returns 
	 */
	export function _getParentElement(element: Node): HTMLElement {
		let parentNode: Node = element;
		while (true) {
			parentNode = parentNode.parentNode;
			if (parentNode == null) {
				break;
			}
			if (parentNode.nodeType === Node.ELEMENT_NODE) {
				break;
			}
		}
		return parentNode as HTMLElement;
	}
	/**
	 * 내부 콘텐트 액세스가 가능한 iframe인지 여부를 평가 합니다.
	 * 일반적으로 CORS가 아닌지 확인하기 위한 용도로 사용됩니다.
	 * 
	 * @param iframe 액세스 가능 여부를 평가할 iframe.
	 * @returns 평가 가능 여부.
	 */
	export function _isSameOriginIFrame(iframe: HTMLIFrameElement) {
		let capturedError = null;
		try {
			iframe.contentWindow.document
		} catch (e) {
			capturedError = e;
		}
		return capturedError == null;
	}

	/**
	 * 탭키를 통해 포커스를 소유할 수 있는 노드들을 얻습니다.
	 * @param scope 노느들을 검색할 범주 노드.
	 */
	export function _getTabbableNodes(scope: HTMLElement): HTMLElement[] {
		return _stream(scope.querySelectorAll(_TABBABLE_SELECTOR))
			.castAs(HTMLElement)
			// 렌더링 중이 아닌 것을 걸러 냄.
			.filter(it => it.offsetParent != null)
			.sortBy(true, (a, b) => {
				let tabIndexA = a.tabIndex;
				let tabIndexB = b.tabIndex;
				if (tabIndexA === 0 && tabIndexB > 0) {
					return 1;
				}
				else if (tabIndexA > 0 && tabIndexB === 0) {
					return -1;
				}

				let gap = tabIndexA - tabIndexB;
				return gap;
			})
			.collect();
	}

	/**
	 * 주어진 HTML 루트 요소 내에서 현재 포커스를 소유한 노드로 부터 다음 포커스 노드를 찾아 포커스를 전이 합니다.
	 * 다음 포커스 노드가 주어진 스코프를 벗어날 수 없습니다.
	 * 
	 * 이 메소드는 플랫폼과 무관하게 HTML 기본 동작을 묘사하기 위해 제공됩니다.
	 * 어댑터 이외의 용도로 사용될 가능성이 낮습니다.
	 * 
	 * @param scope 포커스 순환 범주 노드.
	 * @param forward 포커스 순환 방향. <code>true</code>인 경우 정방향.
	 * @returns 포커스 전이 성공 여부.
	 */
	export function _traverseHTMLFocus(scope: HTMLElement, forward: boolean): boolean {
		let nodes = _getTabbableNodes(scope);
		if (!nodes || nodes.length === 0) {
			return false;
		}

		if (!forward) {
			nodes = nodes.reverse();
		}

		let activeElement = document.activeElement;

		if (activeElement !== scope && scope.contains(activeElement)) {
			let currentIdx = nodes.indexOf(document.activeElement as HTMLElement);
			if (currentIdx >= 0 && currentIdx < nodes.length - 1) {
				_giveFocus(nodes[currentIdx + 1], forward);
				return true;
			}
		} else {
			if (nodes.length > 0) {
				_giveFocus(nodes[0], forward);
				return true;
			}
		}

		return false;
	}


	/**
	 * 주어진 노드 내부에 탭으로 포커스 전이 가능한 노드들이 존재하는지 여부를 반환 합니다.
	 * @param scope 범주 노드.
	 * @returns 턉을 통한 포커스 전이 가능한 노드가 포함되어 있는지 여부.
	 */
	export function _hasTabbableChildNode(scope: HTMLElement) {
		if (!scope) {
			return;
		}
		let nodes = _toArray(scope.querySelectorAll(_TABBABLE_SELECTOR)) as HTMLElement[];
		return nodes.some(it => it.offsetParent != null);
	}

	/**
	 * 특정 노드를 포커스합니다.
	 * 만일 해당 노드가 내부 문맥을 갖는 경우, 내부 문맥 내에서 포커스 전이를 시도합니다.
	 * @param element 포커스를 부여할 노드.
	 * @param forward 포커스가 전이되어 온 방향.
	 */
	function _giveFocus(element: HTMLElement, forward: boolean) {
		let tagName = element?.tagName?.toUpperCase();

		switch (tagName) {
			case "":
			case null:
				/* 아무일 안함 */
				break;

			case "IFRAME":
				let iframe = element as HTMLIFrameElement;

				// CORS가 아닌 경우.
				if (_isSameOriginIFrame(iframe)) {
					if (!_traverseHTMLFocus(iframe.contentWindow.document.body, forward)) {
						iframe.contentWindow.focus();
					}
				}
				else {
					iframe.contentWindow.focus();
				}
				break;

			default:
				element.focus();
				break;
		}
	}

	/**
	 * document.activeElement를 반환합니다.
	 * 
	 * IE에서 iframe 내 focus가 있는 element가 제거 되는 경우
	 * document.activeElement가 올바르지 않은 값(empty object)을 반환하여 추가되었습니다. (#10020, #10032, #10246)
	 */
	export function _getActiveElement(targetDocument: Document): HTMLElement {
		targetDocument = targetDocument ?? document;
		let activeElement: HTMLElement = targetDocument.activeElement as HTMLElement;
		if (activeElement instanceof Element) {
			return activeElement;
		}
		return targetDocument.body;
	}
}