/// <reference path="../events/DOMEventWrapper.ts"/>
/// <reference path="../ufc/ShapeUtil.ts"/>

namespace cpr.foundation {

	/**
	 * @private
	 */
	export enum InputLocation {
		paste = "paste",
		keydown = "keydown",
		keydownIME = "keydownIME",
		drop = "drop",
		selfdrop = "selfdrop",
		beforeinput = "beforeinput",
		cut = "cut",
		drag = "drag",
		input = "input",
		copy = "copy"
	}
	/**
	 * transfer: 드롭 시 드래그한 데이터
	 * canSelectionDrop: 드롭 시 선택된 영역에 드롭이 가능한지 여부
	 * draginfo: 드롭 시 드래그한 데이터
	 * isRemovedDragSelection: 드래그한 데이터가 삭제된 경우(IE에서 드래그한 데이터가 삭제된 경우)
	 * beforeinputData: beforeinput 시점의 삽입 될 데이터
	 * inputType: 드롭 시 드래그한 인풋타입(IE에서 미지원하는 타입 때문에 사용)
	 */
	type InputObjectDataType = "transfer" | 'canSelectionDrop' | 'draginfo' | 'isRemovedDragSelection' | 'beforeinputData' | 'inputType';
	/**
	 * @private
	 */
	export class InputObject {
		private _before: { text: string, ss: number, se: number }
		private _text: string;
		private _ss: number;
		private _se: number;
		private _processed: boolean = false;
		private _from: InputLocation;
		private _applied: boolean = false;

		private _data: { [key: string]: any };

		constructor(text: string, ss: number, se: number, from: InputLocation = InputLocation.keydown) {
			this._text = text;
			this._ss = ss;
			this._se = se;
			this._before = { text: text, ss: ss, se: se };
			this._from = from;
			this._data = {};
		}

		public isChanged() {
			return this._text !== this._before.text;
		}

		public isApplied() {
			return this._applied;
		}

		public setData(name: InputObjectDataType, value: any) {
			this._data[name] = value;
		}

		public getData(name: InputObjectDataType) {
			return this._data[name];
		}

		public removeData(name: string) {
			delete this._data[name];
		}

		public apply(input: HTMLInputElement, callback?: () => void) {
			input.value = this._text;
			this._applied = true;
			callback?.();
			if (_detectBrowser().name == "ie" && document.activeElement != input) {
				return;
			}
			input.setSelectionRange(this._ss, this._se);
		}

		public customApply(customApplyFunc: (text: string, selectionStart: number, selectionEnd: number) => void, callback?: () => void) {
			customApplyFunc(this.text, this.selectionStart, this.selectionEnd);
			this._applied = true;
			callback?.();
		}

		public processed(data: { text: string, ss: number, se: number }) {
			this._processed = true;
			if (_.isEqual({ text: this._text, ss: this._ss, se: this._se }, data)) {
				return;
			}
			this._text = data.text;
			this._ss = data.ss;
			this._se = data.se;
		}

		public isProcessed() {
			return this._processed;
		}

		public get text() {
			return this._text;
		}

		public get selectionStart() {
			return this._ss;
		}

		public get selectionEnd() {
			return this._se;
		}

		public get from(): InputLocation {
			return this._from;
		}

		public get before() {
			return _shallowCopyObject(this._before);
		}
	}

	/**
	 * @private
	 */
	export interface ValueOwner {
		_getValue(): string;
		_setValue(value: string): void;
		readOnly: boolean;
		focused: boolean;
		getParent: () => core.DrawableControl;
		dispatchEvent(e: cpr.events.CEvent): boolean;
	}
	/**
	 * @private
	 */
	export interface AbstractMaskDelegate {
		computeDisplayText?(text: string): string;
	}
	/**
	 * @private
	 */
	export abstract class AbstractMask {

		// global
		static SKIPCODE: number[] = [
			events.KeyCode.TAB,
			events.KeyCode.ENTER,
			events.KeyCode.SHIFT,
			events.KeyCode.CTRL,
			events.KeyCode.ALT,
			events.KeyCode.PAUSE,
			events.KeyCode.CAPSLOCK,
			events.KeyCode.IME, // 한/영
			events.KeyCode.END,
			events.KeyCode.HOME,
			events.KeyCode.LEFT,
			events.KeyCode.UP,
			events.KeyCode.RIGHT,
			events.KeyCode.DOWN,
			events.KeyCode.META, // win(left)
			events.KeyCode.NUMLOCK,
			events.KeyCode.SCROLLLOC
		];

		static BLOCKCODE: number[] = [
			events.KeyCode.CHINESE, // 한자
			events.KeyCode.PAGEUP,
			events.KeyCode.PAGEDOWN,
			events.KeyCode.INSERT
		];

		// local
		protected _owner: ValueOwner;
		protected _formatter: AbstractFormatter;
		protected _input: InputObject;
		private _listeners: { [key: string]: Function[] } = {};
		protected _currentInputValue: string = null;
		private _delegate: AbstractMaskDelegate;

		constructor(owner: ValueOwner, delegate?: AbstractMaskDelegate) {
			this._owner = owner;
			this._delegate = delegate;
		}
		public abstract getFormatter(): any;
		// protected abstract _beforePasteEvent(input: HTMLInputElement, e: ClipboardEvent);
		protected abstract _pasteEvent(input: HTMLInputElement, pasteValue: string, inputValue: string, e: ClipboardEvent);
		protected abstract _cutEvent(input: HTMLInputElement, e: ClipboardEvent);
		protected abstract _inputEvent(input: HTMLInputElement, e: events.CUIEvent);
		protected abstract _beforeinputEvent(input: HTMLInputElement, e: events.CUIEvent);
		protected abstract _keydownEvent(input: HTMLInputElement, e: KeyboardEvent, keychar: string);
		protected abstract _keydownEventIMEProcess(input: HTMLInputElement, e: KeyboardEvent);
		protected abstract _focusEvent(input: HTMLInputElement, e: FocusEvent);
		protected abstract _blurEvent(input: HTMLInputElement, e: UIEvent);

		protected _computeDisplayText(text: string): string {
			if (this._delegate?.computeDisplayText) {
				return this._delegate.computeDisplayText(text);
			}
			return text;
		}

		/**
		 * readonly 포맷을 반환합니다.
		 */
		public get format() {
			return this._formatter._getFormat();
		}

		public wrap(shape: ufc.ControlShape): void {
			// shape redefine
			if (shape == null) {
				return;
			}

			if (shape["events"] == undefined || shape["events"] == null) {
				shape["events"] = {};
			}
			this._currentInputValue = shape.value ?? null;
			if (this._owner.readOnly) {
				return;
			}
			ufc.ShapeUtil.addEventHandler(shape, "blur", (e) => this._onblur(e), true); /* IE에서는 blur 가 다음틱에 동작하여 비동기적이고 Chrome에서는 focusout은 동작안함 */
			ufc.ShapeUtil.addEventHandler(shape, "paste", (e) => this._onpaste(e), true);
			ufc.ShapeUtil.addEventHandler(shape, "cut", (e) => this._oncut(e), true);
			ufc.ShapeUtil.addEventHandler(shape, "focus", (e) => this._onfocus(e), true);

			ufc.ShapeUtil.addEventHandler(shape, "keydown", (e) => this._onkeydown(e), true);
			ufc.ShapeUtil.addEventHandler(shape, "beforeinput", (e) => this._onbeforeinput(e), true);
			ufc.ShapeUtil.addEventHandler(shape, "input", (e) => this._oninput(e), true);
			ufc.ShapeUtil.addEventHandler(shape, "drop", (e) => this._ondrop(e), true);
			ufc.ShapeUtil.addEventHandler(shape, "dragstart", (e) => this._ondrag(e), true);
			ufc.ShapeUtil.addEventHandler(shape, "dragend", (e) => this._ondragend(e), true);
		}

		public getDisplayText(value: string): string {
			let formattedData: string = null;
			if (value == null || value == "") {
				formattedData = this._formatter._getPlaceholder();
			} else {
				formattedData = this._formatter.transform(value);
			}
			return formattedData;
		}

		/**
		 * 이벤트를 전달 합니다.
		 * @param e 이벤트(현재는 마우스 이벤트)
		 */
		protected _dispatchEvent(type: string, e?: Event): boolean {
			let dispatchEvent = true;

			if (!this._listeners[type]) {
				return dispatchEvent;
			}

			this._listeners[type].forEach((each: Function) => {
				each(e);
			});
			if (e) {
				dispatchEvent = !e.defaultPrevented;
			}
			return dispatchEvent;
		}

		/**
		 * @private
		 * @param type 
		 * @param func 
		 */
		public addEventListener(type: string, func: Function) {
			if (!this._listeners[type]) {
				this._listeners[type] = [];
			}
			this._listeners[type].push(func);
		}

		/**
		 * @private
		 * @param type 
		 * @param func 
		 */
		public removeEventListener(type, func) {
			if (!this._listeners[type]) {
				return;
			}
			let idx = this._listeners[type].indexOf(func);
			if (idx > -1) {
				this._listeners[type].splice(idx, 1);
			}
		}

		/**
		 * @private
		 * @param type 
		 */
		public removeAllEventListener(type) {
			if (!this._listeners[type]) {
				return;
			}
			this._listeners[type] = [];
		}

		// event handlers
		protected _ondrop(e: DragEvent) {
			if (e.defaultPrevented) {
				return;
			}
			let input = e.target as HTMLInputElement;
			let isSelfDrop = this._input && this._input.from == InputLocation.drag && this._input.isProcessed() == false && (e as events.CMouseEvent)._getMod4Key() == false;
			let dragInfo = this._input;
			let value = this._computeDisplayText(input.value);
			let canSelectionDrop = true;
			let ss = input.selectionStart;
			let se = input.selectionEnd;
			if (!isSelfDrop) {
				canSelectionDrop = value == input.value;
				ss = canSelectionDrop ? input.selectionStart : value.length;
				se = canSelectionDrop ? input.selectionEnd : value.length;
			}
			this._input = new InputObject(value, ss, se, isSelfDrop ? InputLocation.selfdrop : InputLocation.drop);
			if (isSelfDrop) {
				this._input.setData("draginfo", dragInfo);
				this._input.setData("inputType", "deleteByDrag");
			}
			this._input.setData("canSelectionDrop", canSelectionDrop);
			this._input.setData("transfer", e.dataTransfer.getData("text"));
		}

		private _ondrag(e: DragEvent) {
			let input = e.target as HTMLInputElement;
			this._input = new InputObject(input.value, input.selectionStart, input.selectionEnd, InputLocation.drag);
			this._input.setData("transfer", e.dataTransfer.getData("text"));
		}

		protected _ondragend(e: DragEvent) {
			let input = <HTMLInputElement>e.target;
			window.setTimeout(() => {
				let inputLocation = this._input ? this._input.from : null;
				this._input = null;
				if (this._isDisposed() || this._owner.focused) {
					return;
				}
				//Edge에서 deleteByDrag을 체크할수 있는 이곳밖에 없음. 값이 변경되는 시점이 dragend 이후 발생.
				if (inputLocation == InputLocation.drag) {
					let value = this._formatter.reverseTransform(input.value);
					this._owner._setValue(value);
				}
			})
		}

		private _onblur(e: UIEvent): void {
			let inputTag: HTMLInputElement = e.target as HTMLInputElement;
			this._blurEvent(inputTag, e);
		}

		private _onpaste(e: ClipboardEvent): void {
			if (e.defaultPrevented) {
				return;
			}
			let clipboardData = e.clipboardData || window["clipboardData"];
			if (!clipboardData) {
				e.preventDefault();
				return;
			}
			let input: HTMLInputElement = e.target as HTMLInputElement;
			let value = input.value;
			let ss = input.selectionStart;
			let se = input.selectionEnd;
			this._input = new InputObject(value, ss, se, InputLocation.paste);
			let pasteValue = clipboardData.getData("text") as string;
			let inputValue: string = this._computePastedInputValue(value, pasteValue, ss, se);

			e.preventDefault();
			window.setTimeout(() => {
				this._pasteEvent(input, pasteValue, inputValue, e);

				this._dispatchPasteInputEvent(e);
			});
		}

		/**
		 * 붙여넣기 값을 선택 영역에 합성한 텍스트를 반환합니다.
		 * @param value 붙여넣기 전 인풋의 값
		 * @param pasteValue 붙여넣기 값
		 * @param ss 붙여넣기 전 셀렉션 시작 위치
		 * @param se 붙여넣기 전 셀렉션 종료 위치
		 */
		protected _computePastedInputValue(value: string, pasteValue: string, ss: number, se: number): string {
			if (ss != se) {
				return utils.StringUtil.replaceRange(value, pasteValue, ss, se);
			}
			return utils.StringUtil.insert(value, pasteValue, ss);
		}

		/**
		 * 붙여넣기 처리 후 컨트롤에 input 이벤트를 전파합니다.
		 * @param e 붙여넣기가 발생한 이벤트
		 */
		protected _dispatchPasteInputEvent(e: Event) {
			let inputEvent = new events.CKeyboardEvent("input");
			inputEvent.nativeEvent = e;
			this._dispatchEvent("paste", inputEvent);
			this._owner.dispatchEvent(inputEvent);
		}

		/**
		 * 안드로이드에서 클립보드 붙여넣기는 paste 이벤트가 아닌 클립보드에 저장된 내용의 입력(insertText)으로 동작합니다.
		 * 입력과 붙여넣기를 구분 할 수 없어 1개의 문자인 경우 입력, 2개 이상의 문자인 경우 붙여넣기로 간주합니다.
		 * @param e beforeinput 또는 input 이벤트
		 */
		protected _isAndroidClipboardPaste(e: events.CUIEvent): boolean {
			if (!e.inputType || !_detectBrowser().isAndroid) {
				return false;
			}
			let data = this._getPastedData(e);
			return !!data && data.length > 1 && e.inputType == "insertText";
		}

		/**
		 * 입력 이벤트로 전달된 데이터를 반환합니다.
		 * inputType이 insertFromPaste인 경우 data가 없고 dataTransfer로 전달됩니다.
		 * @param e beforeinput 또는 input 이벤트
		 */
		protected _getPastedData(e: events.CUIEvent): string {
			if (e.data) {
				return e.data;
			}
			let dataTransfer: DataTransfer = e.nativeEvent?.["dataTransfer"];
			return dataTransfer ? dataTransfer.getData("text") : null;
		}

		/**
		 * 인풋에 이미 적용이 끝난 입력 정보가 남아 있으면 현재 인풋 상태로 다시 만듭니다.
		 * 삼성 브라우저는 키보드의 클립보드 버튼으로 붙여넣기 시 keydown이 발생하지 않아 입력 정보가 초기화되지 않습니다.
		 * 적용이 끝난 입력 정보가 남아 있으면 다음 붙여넣기가 처리되지 못하고 이전 값으로 되돌아갑니다.
		 * @param input 인풋 엘리먼트
		 */
		protected _resetAppliedInput(input: HTMLInputElement, from: InputLocation = InputLocation.beforeinput) {
			if (!this._input?.isApplied()) { // 입력 정보가 없거나 아직 적용되지 않은 경우는 유지한다.
				return;
			}
			this._input = new InputObject(input.value, input.selectionStart, input.selectionEnd, from);
		}

		/**
		 * 안드로이드의 클립보드 붙여넣기를 paste 이벤트와 동일하게 처리합니다.
		 * 처리한 경우 호출한 곳에서 기본 동작(입력)을 취소해야 합니다.
		 * @param input 인풋 엘리먼트
		 * @param e beforeinput 이벤트
		 * @returns 붙여넣기로 처리한 경우 true
		 */
		protected _checkAndroidClipboardPaste(input: HTMLInputElement, e: events.CUIEvent): boolean {
			if (!this._isAndroidClipboardPaste(e)) {
				return false;
			}
			let pasteValue = this._getPastedData(e);
			// 앞선 이벤트(deleteContentBackward)에서 입력이 처리된 경우 인풋의 값이 붙여넣기 이전 상태가 아닐 수 있어
			// 처리 전 값을 기준으로 붙여넣기 값을 합성한다.
			let before = this._input?.isProcessed() ? this._input.before : null;
			let value = before ? before.text : input.value;
			let ss = before ? before.ss : input.selectionStart;
			let se = before ? before.se : input.selectionEnd;
			let inputValue = this._computePastedInputValue(value, pasteValue, ss, se);

			let pasteInput = new InputObject(value, ss, se, InputLocation.paste);
			this._input = pasteInput;
			this._pasteEvent(input, pasteValue, inputValue, e);

			// 안드로이드 크롬에서는 beforeinput의 preventDefault()가 동작하지 않는 버전이 있어
			// input 이벤트에서 붙여넣기 결과가 다시 설정되도록 처리 결과를 기억한다.
			let text = input.value;
			pasteInput.processed({ text: text, ss: text.length, se: text.length });
			this._currentInputValue = text;

			window.setTimeout(() => {
				if (this._isDisposed() || pasteInput.isApplied()) { // input 이벤트에서 처리되어 이벤트가 이미 전파된 경우
					return;
				}
				// 입력이 취소되어 input 이벤트가 발생하지 않은 경우. 안드로이드는 IME가 입력 상태를 다시 반영하여
				// beforeinput에서 설정한 값이 유지되지 않을 수 있어 붙여넣기 결과를 다시 설정한다.
				pasteInput.apply(input, () => { this._currentInputValue = input.value });
				this._dispatchPasteInputEvent(e);
			});
			return true;
		}

		private _onfocus(e: FocusEvent): void {
			let inputTag: HTMLInputElement = e.target as HTMLInputElement;
			this._focusEvent(inputTag, e);
			this._currentInputValue = inputTag.value;
		}

		protected _transformInputValue(value: string) {
			return this._formatter.transform(value)
		}

		protected _checkInsertFromDrop(e: events.CUIEvent) {
			let inputType = e["inputType"];
			let result: boolean = false;
			if (inputType) {
				result = "insertFromDrop" == inputType;
			} else {
				result = this._isDropping();
			}
			if (this._input && this._input.from == InputLocation.selfdrop) {
				if (this._input.getData("inputType") == "deleteByDrag") {
					this._input.setData("inputType", null);
					result = false;
				}
			}
			return result;
		}

		protected _isDropping() {
			return this._input && (this._input.from == InputLocation.drop || this._input.from == InputLocation.selfdrop);
		}

		protected _checkDeleteByDrag(e: events.CUIEvent) {
			if (this._isDropping()) {
				return false;
			}
			let inputType = e["inputType"];
			if (inputType) {
				return "deleteByDrag" == inputType;
			}
			return (this._input && this._input.from == InputLocation.drag);
		}
		protected _checkDragInputValue(inputValue: string) {
			return inputValue;
		}
		protected _checkDropInputValue(inputValue: string) {
			return this._computeDisplayText(inputValue);
		}
		/**
		 * IME 입력을 받은 텍스트중에 전각문자를 제거
		 * @param e 
		 */
		protected _oninput(e: events.CUIEvent) {
			let inputbox = e.target as HTMLInputElement;
			let isInsertFromDrop = this._checkInsertFromDrop(e);
			let isDeleteByDrag = this._checkDeleteByDrag(e);
			if (isInsertFromDrop || isDeleteByDrag) {
				let inputValue: string;
				if (isInsertFromDrop) {
					inputValue = this._checkDropInputValue(inputbox.value);
				} else {
					inputValue = this._checkDragInputValue(inputbox.value);
				}
				let value = this._formatter.reverseTransform(inputValue);

				this._owner._setValue(value);

				let text = this._transformInputValue(value);
				this._input.processed({ text: text, ss: text.length, se: text.length });

			}

			// 삼성 브라우저는 키보드의 클립보드 버튼으로 붙여넣기 시 keydown이 발생하지 않아 입력 정보가 초기화되지 않는다.
			// 적용이 끝난 입력 정보로는 이전 값이 다시 설정되어 연속 붙여넣기가 처리되지 않는다.
			this._resetAppliedInput(inputbox, InputLocation.input);

			// 삼성 브라우저는 키보드의 클립보드 버튼으로 붙여넣기 시 keydown이 발생하지 않아 입력 정보가 없을 수 있다.
			if (this._input?.isProcessed()) { //keydown에서 작업한 값 설정
				this._input.apply(inputbox, () => { this._currentInputValue = inputbox.value });

				if (!this._input.isChanged()) { // 이전 값과 동일하면 사용자 이벤트 input이 전파되지 않도록 차단
					e.stopPropagation();
				}
				return;
			}

			this._inputEvent(inputbox, e);
		}

		private _oncut(e: ClipboardEvent) {
			let input = <HTMLInputElement>e.target;
			let ss = input.selectionStart;
			let se = input.selectionEnd;
			let value = input.value;
			this._input = new InputObject(value, ss, se, InputLocation.cut);

			this._cutEvent(input, e);
		}

		protected _isIgnoreInputType(inputType: string) {
			let ignoreCases = ["deleteByDrag", "insertFromDrop", "deleteByCut", "insertFromPaste"];
			if (ignoreCases.indexOf(inputType) > -1) {
				return true;
			}
			return false;
		}

		private _onbeforeinput(e: cpr.events.CUIEvent) {
			let inputbox = e.target as HTMLInputElement;
			if (!this._input) {
				this._input = new InputObject(inputbox.value, inputbox.selectionStart, inputbox.selectionEnd, InputLocation.beforeinput);
			}

			this._beforeinputEvent(inputbox, e);
		}

		private _onkeydown(e: events.CKeyboardEvent): void {
			let keychar: string = e.key;
			let keycode: number = e.keyCode;
			let inputTag: HTMLInputElement = e.target as HTMLInputElement;
			if (_isSamsungBrowser()) {
				if (keycode === 0 &&
					(keychar === undefined || keychar === "Unidentified") &&
					(!e.code || e.code === "") &&
					!e.isComposing &&
					!e.altKey && !e.ctrlKey && !e.metaKey) { // ghostKeyEvent: 삼성 브라우저에서 클립보드 버튼을 누르면 발생하는 이벤트
					return;
				}
			}
			// alt, ctrl check
			if (e._getMod3Key() || keycode == null) {
				return;
			}
			if (keycode == events.KeyCode.CTRL) { // https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/9168
				if (this._input && this._input.from == InputLocation.keydownIME) {
					this._input = new InputObject(inputTag.value, inputTag.selectionStart, inputTag.selectionEnd, InputLocation.keydownIME);
				}
				return;
			} else if (e.ctrlKey) { // metaKey는 맥의 커맨드키, 윈도우는 윈도우키
				if (!e._getMod2Key()) {
					if (keycode == events.KeyCode.Z) { //윈도우 undo
						this._beforeUndoEvent(e);
					} else if (keycode == events.KeyCode.Y) { //윈도우 redo
						this._beforeRedoEvent(e);
					} else if (keycode == events.KeyCode.C) {
						this._beforeCopyEvent(e);
					}
				}
				return;
			} else if (e.metaKey) {
				let isMacOS = _detectBrowser().os.indexOf("OS X") > -1;
				if (isMacOS) {
					if (!e._getMod2Key() && keycode == events.KeyCode.Z) {//맥OS undo
						this._beforeUndoEvent(e);
					} else if (e._getMod2Key() && keycode == events.KeyCode.Z) {//맥OS redo
						this._beforeRedoEvent(e);
					}
				}
				return;
			}
			// skip check
			if (AbstractMask.SKIPCODE.indexOf(keycode) != -1) {
				return;
			}

			// block check
			if (AbstractMask.BLOCKCODE.indexOf(keycode) != -1) {
				if (this._owner && this._owner.getParent() instanceof cpr.controls.Grid) {
					return;
				}
				e.preventDefault();
				return;
			}
			this._input = null;
			// https://developer.mozilla.org/en-US/docs/Web/API/KeyboardEvent/key/Key_Values
			let numericKeypadKey = { "Decimal": ".", "Multiply": "*", "Add": "+", "Divide": "/", "Subtract": "-", "Spacebar": " " };
			if (numericKeypadKey[keychar]) {
				keychar = numericKeypadKey[keychar];
			}

			// noise check
			// https://w3c.github.io/uievents/#determine-keydown-keyup-keyCode
			// If an Input Method Editor is processing key input and the event is keydown, return 229
			// ascii code 전각 문자의 경우도 229로 넘어옴
			// ios에서는 IMEKey가 확인이 안되어 입력되는 현상이 있음. 사파리에서는 IME문자를 키코드에서 0으로 표시함.
			if (keycode == events.KeyCode.IME_INPUT || keycode == 0) { // Input Method Editor
				this._input = new InputObject(inputTag.value, inputTag.selectionStart, inputTag.selectionEnd, InputLocation.keydownIME);

				this._keydownEventIMEProcess(inputTag, e);
				return;
			}
			// 펑션키 체크가 IME보가 우선으로하면 걸러지기 때문에 IME 체크가 우선으로 되어야 한다
			let isFunctionKey = keychar.length > 1; // ProcessKey
			let passKeycodes = [events.KeyCode.BACKSPACE, events.KeyCode.DELETE];
			if (isFunctionKey && passKeycodes.indexOf(keycode) == -1) {
				// 걸러지지 않은 기능키 필터링	
				return;
			}
			this._input = new InputObject(inputTag.value, inputTag.selectionStart, inputTag.selectionEnd);
			keychar = this._convertWhiteSpace(keychar, keycode);
			this._keydownEvent(inputTag, e, keychar);
		}

		private _beforeUndoEvent(e: KeyboardEvent) {
			e.preventDefault();
		}
		private _beforeRedoEvent(e: KeyboardEvent) {
			e.preventDefault();
		}
		protected _beforeCopyEvent(e: KeyboardEvent) {
			// override
		}

		// helper methods
		private _convertWhiteSpace(keychar: string, keycode: number): string {
			let converted: string = null;
			switch (keycode) {
				case events.KeyCode.TAB:
					converted = "\t";
					break;
				case events.KeyCode.ENTER:
					converted = "\n";
					break;
				case events.KeyCode.SPACE:
					converted = " ";
					break;
				default:
					converted = keychar;
			}
			return converted;
		}

		protected _isDisposed() {
			return this._owner == null;
		}

		public dispose(): void {
			this._owner = null;
			this._formatter = null;
			this._listeners = null;
		}

	}

}