/// <reference path="./EnableUIControl.ts" />
/// <reference path="../utils/Util.ts" />

namespace cpr.controls {
	const isIE = ["ie", "edge"].indexOf(_detectBrowser().name) !== -1;
	/**
	 * 뷰포트 Rectangle의 반환 옵션
	 */
	export type ViewportRectOptions = {
		/**
		 * 이 값이 true이면, zoom 속성에 영향을 받아 값이 달라 질 수 있습니다. false인 경우 zoom 속성에 영향을 받지 않습니다.
		 */
		scaled?: boolean
	};

	/**
	 * 스크롤 영역의 끝에 도달했을 때 부모의 스크롤 동작을 정의합니다.
	 */
	export enum OverscrollBehaviorType {
		/**
		 * 스크롤 영역의 끝에 도달했을 때 부모로 스크롤 동작을 위임합니다.
		 */
		AUTO = "auto",

		/**
		 * 스크롤 영역의 끝에 도달했을 때 부모에게 전파하지 않습니다.
		 */
		NONE = "none"
	}

	let _preferNativeScroll: boolean = undefined;

	function preferNativeScroll(): boolean {
		if (_preferNativeScroll === undefined) {
			let appConf: core.AppConfig = core.AppConfig.INSTANCE;
			let envConfig: core.Config = appConf.getEnvConfig();
			let nativeScroll = envConfig.getValue("preferNativeScroll", true);
			if (typeof nativeScroll != "boolean") {
				_preferNativeScroll = true
			} else {
				_preferNativeScroll = nativeScroll;
			}

		}

		return _preferNativeScroll;
	}

	class AsideShape implements resources.IDisposable {
		private _owner: UIControl;
		private _shape: ufc.ElementShape;
		private _disposed: boolean;


		constructor(owner: UIControl, shape: ufc.ElementShape) {
			this._owner = owner;
			this._shape = shape;
			this._disposed = false;

			this._shape.nodename = this._getNodename();
		}

		public dispose(): void {
			this._owner = null;
			this._shape = null;
			this._disposed = true;
		}

		public get disposed() {
			return this._disposed;
		}

		public _getOwner(): UIControl {
			return this._owner;
		}

		public _getNodename(): string {
			return "aside-" + this._owner.uuid;
		}

		public _getShape(): ufc.ElementShape {
			return _shallowCopyObject(this._shape);
		}

		public _setShape(shape: ufc.ElementShape): void {
			this._shape = shape;

			this._shape.nodename = this._getNodename();
		}

		public _css(key: string, value: string): void {
			if (value == null) {
				if (this._shape.style) {
					delete this._shape.style[key];
				}
			} else {
				if (!this._shape.style) {
					this._shape.style = {};
				}
				this._shape.style[key] = value;
			}
		}
	}

	/**
	 * Aside 영역 전체를 새로 그림.
	 */
	class AsideRedrawRenderer implements ufc.PieceRenderer {
		private _owner: Container;
		private _asideContentsOrder: (UIControl | AsideShape)[];

		constructor(owner: Container, asideContentsOrder: (UIControl | AsideShape)[]) {
			this._owner = owner;
			this._asideContentsOrder = asideContentsOrder;
		}
		public _contains(other: ufc.PieceRenderer): boolean {
			if (other == null) {
				return false;
			}
			if (other instanceof AsideRedrawRenderer ||
				other instanceof AsideReorderRenderer ||
				other instanceof AsideControlAppender) {
				return true;
			}
			return false;
		}
		public _hasPart(other: core.Drawable): boolean {
			if (other instanceof UIControl === false) {
				return false;
			}
			return this._asideContentsOrder.indexOf(other as UIControl) !== -1;
		}
		public _render(renderer: ufc.ControlRenderer): void {
			renderer.replace("aside", this._owner._createAsideShape());
		}
		public _clear(): void {
			this._owner = null;
		}
	}

	/**
	 * Aside 영역 컨텐츠의 순서만 변경.
	 * 전체 Aside 영역 컨텐츠의 z-index 만 변경.
	 */
	class AsideReorderRenderer implements ufc.PieceRenderer {
		private _asideContentsOrder: (UIControl | AsideShape)[];

		constructor(asideContentsOrder: (UIControl | AsideShape)[]) {
			this._asideContentsOrder = asideContentsOrder;
		}
		public _contains(other: ufc.PieceRenderer): boolean {
			if (other == null) {
				return false;
			}
			if (other instanceof AsideReorderRenderer) {
				return true;
			}
			return false;
		}
		public _hasPart(other: core.Drawable): boolean {
			return false;
		}
		public _render(renderer: ufc.ControlRenderer): void {
			for (let idx: number = 0; idx < this._asideContentsOrder.length; idx++) {
				let each: UIControl | AsideShape = this._asideContentsOrder[idx];
				if (each instanceof UIControl) {
					let renderer: ufc.ControlRenderer = each._getRenderer();
					renderer.updateStyle(null, { "z-index": String(idx + 1) }, true);
				} else {
					// AsideShape
					let asideShape: AsideShape = each as AsideShape;
					asideShape._css("z-index", String(idx + 1));
					renderer.replace(asideShape._getNodename(), asideShape._getShape());
				}
			}
		}
		public _clear(): void {
			this._asideContentsOrder = null;
		}

	}

	/**
	 * Aside 영역에 UIControl을 추가.
	 */
	class AsideControlAppender implements ufc.PieceRenderer {
		private _control: UIControl;
		private _asideContents: COrderedMap<UIControl | AsideShape, layouts.ManualConstraint>;

		constructor(control: UIControl, asideContents: COrderedMap<UIControl | AsideShape, layouts.ManualConstraint>) {
			this._control = control;
			this._asideContents = asideContents;
		}
		public _contains(other: ufc.PieceRenderer): boolean {
			if (other == null) {
				return false;
			}
			if (other instanceof AsideControlAppender && other._control === this._control) {
				return true;
			}

			return false;
		}
		public _hasPart(other: core.Drawable): boolean {
			return other === this._control;
		}
		public _render(renderer: ufc.ControlRenderer): void {
			let newCtrlIdx: number = this._asideContents.indexOfKey(this._control);
			if (newCtrlIdx !== -1) {
				renderer.insert("aside", newCtrlIdx, [this._control._getRenderer()]);
			}
		}
		public _clear(): void {
			this._control = null;
			this._asideContents = null;
		}

	}
	class GlobalAsideControlAppender implements ufc.PieceRenderer {
		private _control: UIControl;
		private _globalAsideContents: UIControl[];

		constructor(control: UIControl, globalAsideContents: UIControl[]) {
			this._control = control;
			this._globalAsideContents = globalAsideContents;
		}

		_contains(other: ufc.PieceRenderer): boolean {
			if (other == null) {
				return false;
			}
			if (other instanceof GlobalAsideControlAppender && other._control === this._control) {
				return true;
			}

			return false;
		}

		_hasPart(other: core.Drawable): boolean {
			return other === this._control;
		}
		_render(renderer: ufc.ControlRenderer): void {
			let newCtrlIdx: number = this._globalAsideContents.indexOf(this._control);
			if (newCtrlIdx !== -1) {
				renderer.insert("global", newCtrlIdx, [this._control._getRenderer()]);
			}
		}
		_clear(): void {
			this._control = null;
			this._globalAsideContents = null;
		}

	}

	/**
	 * Container / Group
	 * 컨트롤들의 집합을 만들 수 있는 컨트롤.
	 * 
	 * @firesgroup mouse
	 * @firesgroup contextmenu
	 * @firesgroup bindcontext
	 * @firesgroup keyboard
	 * @firesgroup drop
	 * @firesgroup focus-in-out
	 * 
	 * @fires cpr.events.CUIEvent#before-draw 그룹 컨텐츠가 그려지기 직전에 호출되는 이벤트 입니다.
	 * 내부 컨텐츠를 동적으로 구성하기위한 용도로만 사용됩니다.
	 * 
	 */
	export class Container extends EnableUIControl {
		private static readonly CONTAINER_AVAILABLE_PROP: string[] = [
			"childCombinatorClass", "clipContent"
		];
		private _layout: layouts.Layout<any> = null;
		private _children: COrderedMap<UIControl, layouts.Constraint>;

		private _appContainer: boolean = false;

		private _asideContents: COrderedMap<UIControl | AsideShape, layouts.ManualConstraint>;
		private _asideContentsOrder: (UIControl | AsideShape)[];

		private _globalAsideContents: UIControl[];

		private _clipContent: boolean = true;
		private _childCombinatorClass: string = null;
		private _ocpr: OptimizedChildrenPieceRender = null;

		private _overscrollBehaviorType: OverscrollBehaviorType = OverscrollBehaviorType.AUTO;


		/**
		 * 그룹을 생성합니다.
		 * @param id 그룹의 id
		 */
		constructor(id?: string) {
			super(id);
			this._children = _createOrderedMap<UIControl, layouts.Constraint>();

			this._asideContents = _createOrderedMap<UIControl | AsideShape, layouts.ManualConstraint>();
			this._asideContentsOrder = [];

			this.setLayout(new layouts.XYLayout());

			if (this._getType() == ControlType.CONTAINER) {
				// control initializing
				this._initControl();
			}
		}

		protected override _isConfigurableProperty(propName: string): boolean {
			if (Container.CONTAINER_AVAILABLE_PROP.indexOf(propName) != -1) {
				return true;
			}
			return super._isConfigurableProperty(propName);
		}

		private _getOCPR(): OptimizedChildrenPieceRender {
			if (this._ocpr == null) {
				this._ocpr = new OptimizedChildrenPieceRender(this);
			}
			return this._ocpr;
		}


		public override _checkControlStateForEvent(e?: events.CEvent): boolean {
			if (super._checkControlStateForEvent(e) === false) {
				return false;
			}

			if (events._isPointingEvent(e)) {
				let layout = this.getLayout();
				if (layouts._isTargetObjectProvidingLayout(layout)) {
					let targetObject = layout._computeTargetObject(e);
					if (targetObject) {
						e._setTargetObject(targetObject);
					}
				}
			}

			return true;
		}

		/**
		 * 브라우저의 기본 뷰포트를 이용하여 스크롤을 수행할 것인지의 여부를 얻습니다.
		 */
		public _useBodyScroll(): boolean {
			/**
			 * 내부 레이아웃의 스크롤 대신 브라우저의 최상위 뷰포트 스크롤 적용 여부를 계산합니다.
			 * 
			 * 참고사항:
			 *  - window.scroll 이벤트 발생시, BodyEventTarget에 의하여 스크롤 이벤트가 전파됩니다.
			 */

			// appconfig 에서 사용하지 않는 경우.
			if (!preferNativeScroll()) {
				return false;
			}

			// 루트 앱만 최상위 뷰포트를 사용가능.
			let app = this.getAppInstance();
			if (!app || app.isRootAppInstance() === false) {
				return false;
			}

			if (app.getContainer() !== this) {
				return false;
			}

			let layout = this.getLayout();
			if (!layout) {
				return false;
			} else {
				// 현재 버티컬 및 플로 레이아웃만 지원.
				return layout._supportsBodyScroll();
			}
		}

		/**
		 * layout을 설정합니다.
		 * @param layout layout
		 */
		public setLayout(layout: layouts.Layout<any>): void {
			// 레이아웃 교체 시 이전 레이아웃이 보유한 자원을 정리할 기회를 준다.
			if (this._layout !== layout) {
				this._layout?._onDetached();
			}
			this._layout = layout;
			this._layout._setOwner(this);
			this.redraw();
		}

		/**
		 * layout을 반환합니다.
		 * @return {layouts.Layout} layout
		 */
		public getLayout(): layouts.Layout<any> {
			return this._layout;
		}

		/**
		 * AppContainer 여부를 리턴합니다.
		 * @return AppContainer가 맞는지 여부.
		 */
		public get isAppContainer(): boolean {
			return this._appContainer;
		}

		/**
		 * 직계 자식을 선택하기 위한 컴비네이터용 클래스를 얻습니다.
		 */
		public get childCombinatorClass() {
			return this._childCombinatorClass;
		}

		/**
		 * 직계 자식을 선택하기 위한 컴비네이터용 클래스를 지정합니다.
		 */
		public set childCombinatorClass(childCombinatorClass: string) {
			if (this._childCombinatorClass == childCombinatorClass) {
				return
			}
			this._childCombinatorClass = childCombinatorClass;
			this.redraw();
		}

		/**
		 * AppInstance에서 본 Container가 AppContainer인지 여부를 설정하기 위한 내부 메소드입니다.
		 * @param appContainer
		 */
		public _setIsAppContainer(appContainer: boolean): void {
			this._appContainer = appContainer;
		}

		/**
		 * 클리핑 적용 여부를 얻습니다.
		 */
		public get clipContent() {
			return this._clipContent;
		}

		/**
		 * 자식 컨트롤이 이 컨테이너 영역을 벗어난 경우 클리핑 적용 여부를 지정합니다.
		 * 스크롤 바를 표시할 수 있도록 구성된 레이아웃을 가진 경우 이 속성은 무시됩니다.
		 */
		public set clipContent(clipContent: boolean) {
			if (this._clipContent === clipContent) {
				return;
			}
			this._clipContent = clipContent;
			this.redraw();
		}

		/**
		 * 마우스 휠 또는 터치 이벤트에 의해 스크롤 영역의 끝에 도달했을 때 부모의 스크롤 동작을 정의한 값을 리턴합니다.
		 * 기본 값은 AUTO로 부모에게 스크롤 동작을 위임합니다.
		 */
		public get overscrollBehavior(): OverscrollBehaviorType {
			return this._overscrollBehaviorType;
		}

		/**
		 * 마우스 휠 또는 터치 이벤트에 의해 스크롤 영역의 끝에 도달했을 때 부모의 스크롤 동작을 정의한 값을 설정합니다.
		 * 
		 * OverscrollBehaviorType.AUTO : 부모에게 스크롤 동작을 위임합니다.
		 * OverscrollBehaviorType.NONE : 부모로의 전파를 차단합니다.
		 */
		public set overscrollBehavior(type: OverscrollBehaviorType) {
			this._overscrollBehaviorType = type;
		}

		/**
		 * 컨트롤을 포함 여부를 반환합니다.
		 * @param drawable 컨트롤.
		 * @return 컨트롤을 포함하는지에 대한 여부.
		 */
		public override _containsDrawble(drawable: core.Drawable): boolean {
			if (super._containsDrawble(drawable) === true) {
				return true;
			}
			// children
			if (this._contains(this._children.keys(), drawable)) {
				return true;
			}

			// aside
			if (this._contains(this._getAsideControls(), drawable)) {
				return true;
			}

			//global
			if (this._contains(this._globalAsideContents, drawable)) {
				return true;
			}

			return false;
		}
		private _contains(controls: UIControl[], drawable: core.Drawable): boolean {
			if (controls && controls.length > 0) {
				if (controls.indexOf(drawable as UIControl) > -1) {
					return true;
				}
				for (let childidx: number = 0; childidx < controls.length; childidx++) {
					let child: UIControl = controls[childidx];
					if (child._containsDrawble(drawable) == true) {
						return true;
					}
				}
			}
			return false;
		}

		public _getShowingStateOfChild(child: UIControl): ShowingState {
			let selfState = this._getShowingState();
			switch (selfState) {
				// 부모가 숨겨졌어
				case ShowingState.HIDDEN:
					return ShowingState.HIDDEN;

				// 부모가 강제로 렌더링
				case ShowingState.FORCED_SHOWING:
				case ShowingState.SHOWING: {
					let isLayoutChild: boolean = this.getChildren().indexOf(child) !== -1;
					if (isLayoutChild) {
						return this._layout._isShowingChild(child)
							? selfState
							: ShowingState.HIDDEN
					}
					else if (this._getAsideControls().indexOf(child) !== -1) {
						return selfState;
					}
					else if (this._getGlobalAsideControls().indexOf(child) !== -1) {
						return selfState;
					}
					else {
						return ShowingState.HIDDEN;
					}
				}
			}
		}

		public override _getShowingState(): ShowingState {
			if (!this.visible) {
				return ShowingState.HIDDEN;
			}

			if (this.isAppContainer) {
				let app = this.getAppInstance();
				let host = app.getHost();
				// 임베디드 앱 내지 UDC인 경우, 호스트가 가시성을 결정한다.
				if (host) {
					return host._getShowingState();
				}

				// 루트 앱 컨테이너라면 항상 표시중이다.
				else {
					return ShowingState.SHOWING;
				}
			}
			else {
				return super._getShowingState();
			}
		}

		/**
		 * 컨트롤을 이 컨테이너에 추가합니다.<br>
		 * 컨테이너의 레이아웃이 반응형 레이아웃이라면 반드시 미디어 쿼리를 지정해야합니다.
		 * @param child 추가할 컨트롤.
		 * @param constraint 레이아웃 특성. 레이아웃 특성은 컨테이너에 지정된 레이아웃이 지정하는 형식이어야 합니다.
		 */
		public addChild(child: UIControl, constraint: layouts.Constraint = {}): void {
			if (!child) {
				throw new cpr.exceptions.IllegalArgumentException()
			}

			// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/issues/2195
			// 이미 자식이라면 컨스트레인트만 교체 함.
			if (this.getLastChild() === child) {
				let oldConstraint = this.getConstraint(child);
				// fixes https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/4609
				// 맨 마지막 자식이 매뉴얼 컨스트레인트로 대치된 경우.
				if (layouts._isManualConstraint(oldConstraint) == layouts._isManualConstraint(constraint)) {
					this.replaceConstraint(child, constraint);
					return;
				}
			}

			let usePieceRenderer = this._getOCPR()._insert(this.getChildrenCount(), child, constraint);
			// 피스 렌더러가 최적화를 포기한 경우에만 리드로우
			if (!usePieceRenderer) {
				this.redraw();
			}

			this._addChild(child, constraint);
			this._scheduleChildSizeChanging();
		}

		/**
		 * 컨테이너의 마지막으로 포함되며, 레이아웃에 영향을 받지 않습니다. 컨트롤을 삭제 하려면 Container.removeChild 이용하기 바랍니다.
		 * @param child 플로팅할 컨트롤
		 * @param styles 표시될 컨트롤의 위치를 설명하는 스타일 혹은 cpr.geometry.Rectangle 객체.
		 */
		public floatControl(child: UIControl, styles: { [key: string]: string } = {}) {
			if (styles instanceof geometry.Rectangle) {
				styles = {
					"left": `${styles.left}px`,
					"top": `${styles.top}px`,
					"width": `${styles.width}px`,
					"height": `${styles.height}px`
				};
			}

			if (child.getParent() === this) {
				let childConstraint = this.getConstraint(child);

				// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/issues/2195
				// 이미 마지막으로 플롯된 컨트롤인 경우. 스타일만 변형하고 종료.
				if (layouts._isManualConstraint(childConstraint) && this.getLastChild() === child) {
					this.replaceConstraint(child, layouts._newManualConstraint(styles));
					this._checkStandaloneModalStatus();
					return;
				}
			}

			this.addChild(child, layouts._newManualConstraint(styles));
			this._checkStandaloneModalStatus(child);
			this._scheduleChildSizeChanging();
		}

		/**
		 * 컨테이너의 자식의 순서를 변경합니다. 순서를 변경하여 컨트롤 간에 겹쳤을때 보이는 우선 순위를 결정할 수 있습니다.
		 * @param child 컨테이너의 자식 컨트롤
		 * @param newIndex 새로운 인덱스.
		 * @param isFutureIndex 새로운 인덱스가 컨트롤 재배치 이후 상태의 자식의 인덱스인지 여부. 
		 * 이 값이 <code>false</code>이면 새로운 인덱스는 현재 상태를 기준으로 해석됩니다.
		 * 이 값이 <code>true</code>인 경우 새로운 인덱스는 메소드 실행 후의 인덱스로 해석됩니다.
		 */
		public reorderChild(child: UIControl, newIndex: number, isFutureIndex: boolean = false) {
			if (newIndex < 0) {
				throw new exceptions.IllegalArgumentException('An index must be greater or equals than 0.');
			}

			let oldIndex = this._children.keys().indexOf(child);

			if (!isFutureIndex && newIndex > oldIndex) {
				newIndex--;
			}
			newIndex = Math.min(Math.max(0, newIndex), this._children.size() - 1);
			if (oldIndex === -1 || oldIndex === newIndex) {
				return
			}

			let constraint = this.getConstraint(child);
			this._children.remove(child);
			this._children.insert(newIndex, child, constraint);

			this.redraw();
			this._scheduleChildSizeChanging();
		}

		/**
		 * 자식 컨트롤을 특정 인덱스에 추가합니다.
		 * @param index 자식을 추가할 인덱스
		 * @param child 자식 컨트롤.
		 * @param constraint 자식 컨트롤의 레이아웃 특성.
		 */
		public insertChild(index: number, child: UIControl, constraint: layouts.Constraint = {}): void {
			if (index < 0) {
				throw new exceptions.IllegalArgumentException('An index must be greater or equals than 0.');
			}

			let oldIndex = this._children.keys().indexOf(child);

			// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/issues/2195
			// 이미 같은 위치인 경우, 
			if (oldIndex === index) {
				this.replaceConstraint(child, constraint);
				return;
			}

			if (oldIndex !== -1) {
				if (index > oldIndex) {
					index--;
				}
				this._children.remove(child);
				this._children.insert(index, child, constraint);
				this._checkStandaloneModalStatus(child);
				this.redraw();

				return;
			}

			let oldParent = child.getParent();
			if (oldParent) {
				oldParent.removeChild(child)
			}

			let usePieceRenderer = this._getOCPR()._insert(index, child, constraint);
			// 피스렌더러가 최적화를 포기한 경우에만 리드로우.
			if (!usePieceRenderer) {
				this.redraw();
			}

			child._setParent(this);
			this._children.insert(index, child, constraint);
			this._checkStandaloneModalStatus(child);

			this._scheduleChildSizeChanging();
		}

		protected _addChild(child: UIControl, constraint: layouts.Constraint = {}): void {
			let oldParent = child.getParent();
			if (oldParent) {
				oldParent.removeChild(child)
			}
			this._children.put(child, constraint);
			child._setParent(this);
			this._checkStandaloneModalStatus(child);
		}

		/**
		 * 기존 자식 컨트롤을 새로운 컨트롤로 대체 합니다.
		 * 만약 주어진 기존 컨트롤이 존재하지 않는다면 아무런 일도 하지 않습니다.
		 * @param oldChild 제거될 기존 컨트롤.
		 * @param newChild 대체할 컨트롤.
		 * @param constraints 레이아웃 특성.
		 * @return 새로운 컨트롤 정보. 기존 컨트롤이 존재하지 않아 교체 작업이 일어나지 않았다면 <code>null</code>를 반환 합니다.
		 */
		public replaceChild(oldChild: UIControl, newChild: UIControl, constraints: layouts.Constraint = {}): { key: UIControl, value: layouts.Constraint } {
			let newEntry: { key: UIControl, value: layouts.Constraint } = this._children.replace(oldChild, newChild, constraints);
			if (newEntry) {
				newEntry.key._setParent(null);
				newChild._setParent(this);

				this.redraw();

				this._scheduleChildSizeChanging();
			}
			return newEntry;
		}

		public _isChild(child: UIControl): boolean {
			return this._children.keys().indexOf(child) != -1;
		}

		public _checkStandaloneModalStatus(triggerCtrl?: UIControl): void {
			if (triggerCtrl && !(triggerCtrl instanceof Dialog)) {
				return;
			}
			this.getLayout()._updateModalInert();
		}

		/**
		 * 컨테이너 내의 직계 자식 컨트롤을 ID를 통해 얻습니다.
		 * @param childId 얻을 자식 컨트롤의 ID.
		 * @return 직계 자식 컨트롤 중 주어진 ID와 일치하는 컨트롤. 존재하지 않는 경우 <code>null</code>를 반환 합니다.
		 */
		public getChild(childId: string): UIControl {
			return this._children.findKey((it) => it.id == childId);
		}

		/**
		 * 컨트롤의 레이아웃 특성을 업데이트 합니다.
		 * 기지정된 레이아웃 특성과 신규로 주어진 특성들이 병합됩니다.
		 *
		 * @param child 레이아웃 특성을 업데이트 할 컨트롤.
		 * @param overridingConstraint 추가 또는 변경할 레이아웃 특성.
		 * @return 업데이트 이후 기지정된 레이아웃 특성으로부터 변동사항이 존재하는 지 여부.
		 */
		public updateConstraint(child: UIControl, overridingConstraint: layouts.Constraint): boolean {
			if (this._layout == null) {
				return false;
			}

			if (this._children.keys().indexOf(child) == -1) {
				return false;
			}

			let oldConstraint: layouts.Constraint = this._children.get(child);
			if (oldConstraint == null) {
				oldConstraint = {};
			}

			// 변경 여부.
			let changed = false;

			// 오버라이딩 시작
			for (let key in overridingConstraint) {
				if (oldConstraint[key] != overridingConstraint[key]) {
					oldConstraint[key] = overridingConstraint[key];
					changed = true;
				}
			}

			// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/issues/2195
			// 변경된 속성 없음.
			if (!changed) {
				return false;
			}

			this._layout._updateControl([child]);
			this._scheduleChildSizeChanging();

			return true;
		}

		/**
		 * 컨트롤의 레이아웃 특성을 교체합니다.
		 * @param child 레이아웃 특성을 변경할 컨트롤.
		 * @param newConstraint 새로운 레이아웃 특성. 
		 * 레이아웃 특성은 컨트롤이 소속된 {@link cpr.controls.Container}의 레이아웃이 지원하는 형식이어야 합니다.
		 * @return 기지정된 레이아웃 특성과 변경점이 존재하는지 여부.
		 */
		public replaceConstraint(child: UIControl, newConstraint: layouts.Constraint): boolean {
			if (this._children.keys().indexOf(child) == -1) {
				return false;
			}

			if (this._layout == null) {
				return false;
			}

			let oldConstraint = this._children.get(child);

			// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/issues/2195
			// 컨스트레인트가 동일한 경우 무시.
			if (this._layout._areSameConstraint(oldConstraint, newConstraint)) {
				return false;
			}

			this._children.put(child, newConstraint);
			this._layout._updateControl([child]);

			// 플롯(수동 컨스트레인트) 여부가 바뀌면 레이아웃 흐름에 참여하는 자식 집합이 달라져
			// 첫/마지막 자식 판정도 달라진다. _updateControl 은 변경된 자식만 다시 그리므로
			// 직전에 가장자리였던 형제에 유틸리티 클래스가 남는다. 레이아웃에 알려 보정할 기회를 준다.
			// release-test-project#11189
			//
			// 컨스트레인트가 흐름 배치용인지 여부. 판정 기준은 레이아웃의 _isVisibleLayoutChild 와 같다.
			let allowsFlow = (constraint: layouts.Constraint) => {
				return constraint != null && !layouts._isManualConstraint(constraint);
			};
			if (allowsFlow(oldConstraint) !== allowsFlow(newConstraint)
				&& this._layout._onChildLayoutParticipationChanged) {
				this._layout._onChildLayoutParticipationChanged(child, allowsFlow(oldConstraint) && child.visible);
			}

			this._scheduleChildSizeChanging();

			return true;
		}

		/**
		 * 해당 컨트롤의 레이아웃 특성을 얻습니다.
		 * @param child 레이아웃 특성을 얻을 자식 컨트롤.
		 * @return {layouts.Constraint} 해당 자식 컨트롤의 레이아웃 특성.
		 */
		public getConstraint(child: UIControl): layouts.Constraint {
			return _deepCopyObject(this._children.get(child));
		}

		/**
		 * 모든 자식 컨트롤들을 얻습니다.
		 * @return 자식 컨트롤 배열.
		 */
		public getChildren(): UIControl[] {
			return [].concat(this._children.keys());
		}

		public _getAsideControls(): UIControl[] {
			return this._asideContentsOrder.filter((content: UIControl | AsideShape) => {
				return content instanceof UIControl;
			}) as UIControl[];
		}

		public _getGlobalAsideControls(): UIControl[] {
			return this._globalAsideContents ?? [];
		}

		/**
		 * 첫 번째 자식 컨트롤을 얻습니다.
		 * @return 첫번째 자식 컨트롤.
		 */
		public getFirstChild(): UIControl {
			let children = this.getChildren();
			return children[0];
		}

		/**
		 * 마지막 자식을 컨트롤을 얻습니다.
		 * @return 마지막 자식 컨트롤.
		 */
		public getLastChild(): UIControl {
			let children = this.getChildren();
			return children[children.length - 1];
		}

		// 화면에 보여지고 있는 하위 컨트롤 목록을 리턴한다.
		// TabKey를 이용한 포커스 이동을 위한 컨트롤 목록을 조회한다.
		public _getShowingChildren(): UIControl[] {
			if (this.visible == false) {
				return [];
			}
			return [].concat(this._getAsideControls()).concat(this.getChildren());
		}

		/**
		 * 이 컨테이너에 포함된 모든 자식 컨트롤 및 하위 컨테이너에 포함된 모든 컨트롤들을 재귀적으로 얻습니다.
		 * 임베디드 앱 및 UDC 등의 내부 요소는 반환 결과에 포함되지 않습니다.
		 * @param includeSelf 반환 값에 자기자신을 포함할 지 여부.
		 * @deprecated 오타로 잘못 제공된 API입니다. 대신 {@link getAllRecursiveChildren}를 사용하시기 바랍니다.
		 */
		public getAllRecusiveChildren(includeSelf: boolean = false): UIControl[] {
			return this.getAllRecursiveChildren(includeSelf);
		}

		/**
		 * 이 컨테이너에 포함된 모든 자식 컨트롤 및 하위 컨테이너에 포함된 모든 컨트롤들을 재귀적으로 얻습니다.
		 * 임베디드 앱 및 UDC 등의 내부 요소는 반환 결과에 포함되지 않습니다.
		 * @param includeSelf 반환 값에 자기자신을 포함할 지 여부.
		 */
		public getAllRecursiveChildren(includeSelf: boolean = false): UIControl[] {
			return this._getAllChildren(includeSelf, false)
				.collect();
		}

		/**
		 * 하위 컨트롤의 개수를 반환합니다.
		 * @return 하위 컨트롤의 개수
		 */
		public getChildrenCount(): number {
			return this._children.size();
		}

		/**
		 * 해당 컨트롤을 제거합니다.
		 * @param childControl 제거하려는 컨트롤.
		 * @param shouldDispose 컨트롤 객체 제거 유무.
		 */
		public removeChild(childControl: UIControl, shouldDispose = false): void {
			let knownIndex: number = this._children.indexOfKey(childControl);
			if (knownIndex !== -1) {
				// 피스 렌더러가 최적화를 포기한 경우에만 리드로우
				if (!this._getOCPR()._delete(childControl, knownIndex)) {
					this.redraw();
				}

				this._removeChild(childControl, shouldDispose);

				this._removeAllAsideShape(childControl);

				this._scheduleChildSizeChanging();
			}
			else {
				this._removeAsideControl(childControl, shouldDispose);
			}
		}

		protected _removeChild(childControl: UIControl, shouldDispose = false): boolean {
			let entry: { key: UIControl, value: layouts.Constraint } = this._children.remove(childControl);
			if (entry != null) {
				childControl._setParent(null);
				if (shouldDispose == true) {
					entry.key.dispose();
				}

				this._checkStandaloneModalStatus(childControl);

				return true;
			}
			return false;
		}

		/**
		 * 모든 하위 컨트롤을 제거 합니다.
		 * @param shouldDispose 컨트롤 객체 제거 유무.
		 */
		public removeAllChildren(shouldDispose: boolean = false): void { //<----------------------------------- 자체 구현
			// aside shapes
			let childShape: AsideShape[] = this._asideContentsOrder.filter((item: UIControl | AsideShape) => {
				return item instanceof AsideShape;
			}) as AsideShape[];
			for (let idx: number = 0; idx < childShape.length; idx++) {
				let asideShape: AsideShape = childShape[idx];
				asideShape.dispose();
			}
			// child & aside controls
			let childControls: UIControl[] = _.union([], this._children.keys(), this._getAsideControls());
			let appContainer: Container = this._getAppContainerParent();
			childControls.forEach((item: UIControl) => {
				if (appContainer) {
					this._removeAsideShape(appContainer, item);
				}
				item._setParent(null);
				if (shouldDispose) {
					item.dispose();
				}
			});
			this._children.removeAll();
			this._asideContents.removeAll();
			this._asideContentsOrder.splice(0, this._asideContentsOrder.length);

			this._checkStandaloneModalStatus();

			this.redraw();
			this._scheduleChildSizeChanging();
		}

		public _getChildrenInfo(): COrderedMap<UIControl, layouts.Constraint> {
			return this._children;
		}

		////////////////////////// aside begin //////////////////////////
		public _addGlobalAsideControl(newControl: UIControl) {
			if (!newControl) {
				throw new exceptions.IllegalArgumentException();
			}
			let isRoot = this.getAppInstance().isRootAppInstance();
			if (!isRoot || !this.isAppContainer) {
				// 글로벌에 사용자가 컨트롤 추가가 필요하다면 루트앱 컨테이너에서 글로벌을 설정하는데 다른 컨테이너에서 이 API를 호출할 수 있어야 하는지 검토가 필요함.
				return;
			}
			if (!this._globalAsideContents) {
				this._globalAsideContents = [];
			}

			let existingIndex = this._globalAsideContents.indexOf(newControl);

			if (existingIndex !== -1) {
				newControl.redraw();
				return;
			}

			// 이전 부모 제거.
			let oldParent = newControl.getParent();
			if (oldParent) {
				oldParent.removeChild(newControl);
			}
			newControl._setParent(this);

			this._globalAsideContents[this._globalAsideContents.length] = newControl;

			super._applyPiece(new GlobalAsideControlAppender(newControl, this._globalAsideContents));
		}

		public _removeGlobalAsideControl(control: UIControl, shouldDispose: boolean = false) {
			let isRoot = this.getAppInstance().isRootAppInstance();
			if (!isRoot || !this.isAppContainer) {
				// 글로벌에 사용자가 컨트롤 추가가 필요하다면 루트앱 컨테이너에서 글로벌을 설정하는데 다른 컨테이너에서 이 API를 호출할 수 있어야 하는지 검토가 필요함.
				return;
			}
			let index = this._getGlobalAsideControls().indexOf(control);
			if (index == -1) {
				return;
			}
			let removed = this._globalAsideContents.splice(index, 1);
			if (removed != null) {
				let renderer: ufc.ControlRenderer = control._getRenderer();
				let controlRenderer: ufc.ControlRenderer = this._getRenderer();
				controlRenderer.deleteChild("global", renderer);

				control._setParent(null);

				if (shouldDispose === true) {
					control.dispose();
				}

				return true;
			}
			return false;
		}

		private _removeAllGlobalAsideControls(shouldDispose: boolean = false) {
			this._getGlobalAsideControls().forEach((control: UIControl) => {
				control._setParent(null);
				if (shouldDispose) {
					control.dispose();
				}
			})
			this._globalAsideContents = null;
		}

		/**
		 * aside uicontrol을 추가합니다.
		 * @param newControl 추가할 aside uicontrol
		 */
		public _addAsideControl(newControl: UIControl, styles: { [key: string]: string }): void {
			if (!newControl) {
				throw new exceptions.IllegalArgumentException();
			}
			let constraint = layouts._newManualConstraint(styles);
			this._asideContents.put(newControl, constraint);

			let existingIndex = this._asideContentsOrder.indexOf(newControl);

			// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/issues/2195
			// 이미 마지막 플롯된 컨트롤이라면 아무일도 안해야 합니다.
			if (existingIndex !== -1 && existingIndex === this._asideContentsOrder.length - 1) {
				// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/7104
				newControl.redraw();
				return;
			}

			// 이미 부모인 경우.
			if (existingIndex !== -1) {
				this._asideContentsOrder.splice(existingIndex, 1);
				this._asideContentsOrder[this._asideContentsOrder.length] = newControl;

				this._reorderAsideContents();
			}
			else {
				// 이전 부모 제거.
				let oldParent = newControl.getParent();
				if (oldParent) {
					oldParent.removeChild(newControl);
				}
				newControl._setParent(this);

				// 어사이드 컨트롤 데코레이터 추가.
				newControl._getRenderer().addLayoutDecorator(shape => {
					let constraint = this._getAsideControlConstraint(newControl);
					let isRoot = this.getAppInstance().isRootAppInstance();

					let asideStyle: { [key: string]: string } = {};
					asideStyle["position"] = isRoot ? "fixed" : "absolute";
					asideStyle["z-index"] = String(this._asideContentsOrder.indexOf(newControl) + 1);

					if (newControl instanceof Dialog) {
						if (newControl.modal) {
							let dialogShape = _createTreeStream(shape, true, (e: ufc.ControlShape) => {
								return e.children;
							}).find((e: ufc.ElementShape) => e.styler == "root") as ufc.ElementShape;
							dialogShape.style = _mergeObject(dialogShape.style, constraint.styles);
							shape.style = _mergeObject(shape.style, asideStyle);
						} else {
							shape.style = _mergeObject(shape.style, asideStyle, constraint.styles);
						}
					} else {
						shape.style = _mergeObject(shape.style, asideStyle, constraint.styles);
					}

					return shape;
				});

				this._asideContentsOrder[this._asideContentsOrder.length] = newControl;

				// insert aside control...
				super._applyPiece(new AsideControlAppender(newControl, this._asideContents));
			}
		}

		public _updateFloatControlConstraint(floatControl: UIControl, overridingConstraint: layouts.ManualConstraint, nodename?: string) {
			if (this._layout == null) {
				return false;
			}

			if (this._children.indexOfKey(floatControl) == -1) {
				return false;
			}

			let oldConstraint = this._children.get(floatControl) as layouts.ManualConstraint;
			if (oldConstraint == null) {
				oldConstraint = layouts._newManualConstraint({});
			}

			let changed = false;

			for (let key in overridingConstraint.styles) {
				if (oldConstraint.styles[key] != overridingConstraint.styles[key]) {
					oldConstraint.styles[key] = overridingConstraint.styles[key];
					changed = true;
				}
			}
			if (!changed) {
				return false;
			}
			floatControl._applyPiece(new ufc.CustomPieceRenderer((renderer: ufc.ControlRenderer) => {
				if (!renderer) {
					return;
				}
				let constraint = this.getConstraint(floatControl) as layouts.ManualConstraint;
				renderer.updateStyle(nodename, constraint.styles, true);
			}));

			return true;
		}

		public _replaceAsideControlConstraint(asideControl: UIControl, newConstraint: layouts.ManualConstraint, nodename?: string) {
			if (this._asideContents.indexOfKey(asideControl) == -1) {
				return false;
			}

			if (this._layout == null) {
				return false;
			}

			let oldConstraint = this._asideContents.get(asideControl);

			if (this._layout._areSameConstraint(oldConstraint, newConstraint)) {
				return false;
			}
			this._asideContents.put(asideControl, newConstraint);

			asideControl._applyPiece(new ufc.CustomPieceRenderer((renderer: ufc.ControlRenderer) => {
				if (!renderer) {
					return;
				}
				let constraint = this._getAsideControlConstraint(asideControl);
				renderer.updateStyle(nodename, constraint.styles, true); // https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/10191
			}));

			return true;
		}

		public _updateAsideControlConstraint(asideControl: UIControl, overridingConstraint: layouts.ManualConstraint, nodename?: string) {
			if (this._layout == null) {
				return false;
			}

			if (this._asideContents.indexOfKey(asideControl) == -1) {
				return false;
			}

			let oldConstraint: layouts.ManualConstraint = this._asideContents.get(asideControl);
			if (oldConstraint == null) {
				oldConstraint = layouts._newManualConstraint({});
			}

			let changed = false;

			for (let key in overridingConstraint.styles) {
				if (oldConstraint.styles[key] != overridingConstraint.styles[key]) {
					oldConstraint.styles[key] = overridingConstraint.styles[key];
					changed = true;
				}
			}
			if (!changed) {
				return false;
			}
			asideControl._applyPiece(new ufc.CustomPieceRenderer((renderer: ufc.ControlRenderer) => {
				if (!renderer) {
					return;
				}
				let constraint = this._getAsideControlConstraint(asideControl);
				renderer.updateStyle(nodename, constraint.styles, true);
			}));

			return true;
		}

		public _getAsideControlConstraint(asideControl: UIControl): layouts.ManualConstraint {
			return this._asideContents.get(asideControl);
		}

		/**
		 * AsideControl의 순서를 가장 마지막으로 내려 브라우저에서 가장 위에 보이도록 합니다.
		 * @param asideControl 
		 */
		public _bringAsideControlToTop(asideControl: UIControl): void {
			if (!asideControl) {
				throw new exceptions.IllegalArgumentException();
			}
			if (this.disposed || asideControl.disposed) {
				return;
			}

			let asideContentsIdx: number = this._asideContentsOrder.indexOf(asideControl);
			if (asideContentsIdx === -1) {
				return;
			}
			if (this._asideContentsOrder[this._asideContentsOrder.length - 1] == asideControl) {
				return;
			}

			this._asideContentsOrder.splice(asideContentsIdx, 1);
			this._asideContentsOrder[this._asideContentsOrder.length] = asideControl;

			this._reorderAsideContents();
		}

		private _reorderAsideContents(): void {
			this._applyPiece(new AsideReorderRenderer(this._asideContentsOrder));
		}

		/**
		 * aside uicontrol을 제거합니다.
		 * @param childControl 제거할 aside uicontrol
		 * @param shouldDispose 제거한 aside uicontrol을 dispose 할지 여부
		 */
		public _removeAsideControl(childControl: UIControl, shouldDispose = false): boolean {
			let removed = this._asideContents.remove(childControl);
			if (removed != null) {
				this._removeAllAsideShape(childControl);
				let asideViewControlIdx: number = this._asideContentsOrder.indexOf(childControl);
				this._asideContentsOrder.splice(asideViewControlIdx, 1);
				childControl._setParent(null);

				let renderer: ufc.ControlRenderer = childControl._getRenderer();
				if (renderer && renderer.disposed == false) {
					renderer.removeLayoutDecorator();
				}
				let controlRenderer: ufc.ControlRenderer = this._getRenderer();
				controlRenderer.deleteChild("aside", renderer);

				if (shouldDispose === true) {
					childControl.dispose();
				}
				this._reorderAsideContents();

				if (childControl instanceof Dialog) {
					this._checkStandaloneModalStatus();
				}

				return true;
			}
			return false;
		}

		private _removeAllAsideShape(owner: UIControl): void {
			this._removeAsideShape(this, owner);
			let appContainer: Container = this._getAppContainerParent();
			if (this !== appContainer) {
				this._removeAsideShape(appContainer, owner);
			}
		}

		/**
		 * 컨테이너에 스크롤이 포함된 경우, 해당 위치로 스크롤합니다.
		 * @param left 스크롤 할 x 좌표.
		 * @param top 스크롤 할 y 좌표.
		 * @param duration 스크롤 애니메이션의 길이. 단위는 초입니다.
		 * @param timingFunction 애니메이션을 사용할 경우에 적용될 타이밍 함수.
		 */
		public scrollTo(left: number, top: number, duration = 0, timingFunction = animation.TimingFunction.EASE_IN_OUT) {
			this.getLayout()._scrollTo(left, top, duration, timingFunction);
		}

		/**
		 * 컨테이너에 스크롤이 포함된 경우, 특정 자식을 표시할 수 있도록 스크롤 합니다.
		 * @param child 표시할 자식 컨트롤.
		 * @param duration 스크롤 애니메이션의 길이. (단위: 초)
		 * @param timingFunction 애니메이션을 사용할 경우 적용될 타이밍 함수.
		 */
		public reveal(child: UIControl, duration = 0.3, timingFunction = animation.TimingFunction.EASE_IN_OUT) {
			this.getLayout()._reveal(child, duration, timingFunction);
		}

		/**
		 * 스크롤의 위치를 조정합니다.
		 * @param leftDelta 가로 스크롤 이동 값
		 * @param topDelta 세로 스크롤 이동 값
		 * @param duration 애니메이션 동작 시간.(단위: 초) default=0
		 * @param timingFunction 타이밍 함수. default=animation.TimingFunction.EASE_IN_OUT
		 */
		public adjustScroll(leftDelta: number, topDelta: number, duration = 0, timingFunction = animation.TimingFunction.EASE_IN_OUT) {
			this.getLayout()._adjustScroll(leftDelta, topDelta, duration, timingFunction);
		}

		/**
		 * 컨테이너 안에서 표시중인 스크롤 뷰포트 영역을 얻습니다.
		 */
		public getViewPortRect(options?: ViewportRectOptions): geometry.Rectangle {
			return this.getLayout()._getViewPortRect(options);
		}

		protected _getActualRect(options?: ActualRectOptions): geometry.Rectangle {
			if (this._useBodyScroll()) {
				let result = this.getViewPortRect({ scaled: options.scaled });
				result.top = 0;
				return result;
			} else {
				return super._getActualRect(options);
			}
		}

		// fixes https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/4431
		/**
		 * 브라우저 뷰포트 바운즈 객체를 바탕으로 이 컨테이너에 대한 상대 좌표로 변환합니다.
		 * @param actualRect 상대 좌표를 얻을 Rectangle 객체.
		 */
		public makeRelativeRect(actualRect: geometry.Rectangle): geometry.Rectangle {
			if (!this._getRenderer().hasDrawn()) {
				return new geometry.Rectangle(0, 0, 0, 0);
			}

			return actualRect.getCopy()
				.translateByDimension(this._computeRelativertizeDelta());
		}

		// fixes https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/4431
		/**
		 * 브라우저 뷰포트 기준 좌표를 이 컨테이너에 대한 상대 좌표로 변환합니다.
		 * @param actualLocation 변환할 좌표
		 */
		public makeRelativePoint(actualLocation: geometry.Point): geometry.Point {
			if (!this._getRenderer().hasDrawn()) {
				return new geometry.Point(0, 0)
			}

			return actualLocation.getCopy()
				.translateByDimension(this._computeRelativertizeDelta());
		}

		private _computeRelativertizeDelta(): geometry.Dimension {
			let selfBounds = super.getActualRect(false)

			let scrollDelta = this._useBodyScroll() ? new geometry.Point(0, 0) : this.getViewPortRect().topLeft;
			let layoutNode = this._layout?._getLayoutNode();

			let layoutBounds = _getUnscaledClientRect(geometry.Rectangle.clientBoundsOf(layoutNode));
			let diff = selfBounds.topLeft.getDifference(layoutBounds.topLeft);

			return new geometry.Dimension(-selfBounds.x, -selfBounds.y)
				.add(scrollDelta)
				.add(diff);
		}

		/**
		 * 전체 자식 영역을 얻습니다.
		 */
		public getContentPaneRect(): geometry.Rectangle {
			return this.getLayout()._getContentPaneRect();
		}

		/**
		 * 모든 aside uicontrol을 제거합니다.
		 * @param shouldDispose 제거한 aside uicontrol을 dispose 할지 여부
		 */
		public _removeAllAsideControls(shouldDispose: boolean = false): void {
			let asideControls: UIControl[] = this._getAsideControls();
			for (let idx: number = 0; idx < asideControls.length; idx++) {
				let asideControl: UIControl = asideControls[idx];
				this._asideContents.remove(asideControl);
				let orderIdx: number = this._asideContentsOrder.indexOf(asideControl);
				this._asideContentsOrder.splice(orderIdx, 1);
				this._removeAllAsideShape(asideControl);
			}

			if (shouldDispose == true) {
				asideControls.forEach((control: UIControl) => {
					control._setParent(null);
					if (shouldDispose == true) {
						control.dispose();
					}
				});
			} else {
				asideControls.forEach((control: UIControl) => {
					control._setParent(null);
					let renderer: ufc.ControlRenderer = control._getRenderer();
					if (renderer && renderer.disposed == false) {
						renderer.removeLayoutDecorator();
					}
				});
			}
			this._redrawAside();
		}

		/**
		 * Container의 aside 영역을 새로 그립니다.
		 */
		private _redrawAside(): void {
			this._applyPiece(new AsideRedrawRenderer(this, this._asideContentsOrder));
		}
		////////////////////////// aside finish //////////////////////////

		/**
		 * 컨트롤의 포함하는 객체들을 제거합니다.
		 */
		public override dispose(): void {
			// 레이아웃에는 dispose 인터페이스가 없으므로, 컨테이너 폐기 시 레이아웃이 보유한 자원을 정리하도록 통지한다.
			this._layout?._onDetached();
			this.removeAllChildren(true);
			this._removeAllGlobalAsideControls(true);
			super.dispose(); // super의 dispose 호출은 최 하단에서
		}

		protected override _getStylerSpec(): UIControlStylerSpec { /* TODO abstract */
			return {
				root: {
					baseClass: "cl-container"
				}
			};
		}

		public override _createShape(): ufc.ControlShape {
			this._ocpr = null;
			let shape: ufc.ControlShape = {
				tag: "div",
				attr: {},
				styler: "root",
				aria: "root",
				style: {
					overflow: this._clipContent ? "hidden" : "visible"
				},
				events: {
				},
				eventTargets: [
					ufc.EventTargetType.UICONTROL,
					ufc.EventTargetType.DROPPABLE
				],
				children: [
					this._layout._createLayoutShape()
				]
			};
			if (this.isAppContainer) {
				shape.style["z-index"] = "0";
			}

			cpr.ufc.ShapeUtil._setTooltipAttr(shape, { owner: this, title: this.tooltip });

			// container에 application의 role 부여 가능
			if (this.isAppContainer == true) {
				let appInstance: core.AppInstance = this.getAppInstance();
				shape.attr["data-app"] = appInstance.uuid;

				if (appInstance) {
					if (appInstance.isRootAppInstance() == true) {
						// root app
						shape.attr["data-role"] = "application";
						shape.eventTargets.splice(0, shape.eventTargets.length, ufc.EventTargetType.APPLICATION);
						events.EventBus.INSTANCE._setBrowserEventHandler(this, {
							"window-scroll": (ev: events.CUIEvent) => {
								if (this._useBodyScroll()) {
									this.dispatchEvent(ev);
								}
							}
						});
						shape.global = this._createGlobalAsideShape(appInstance);
					} else if (appInstance.isEmbeddedAppInstance() == true) {
						// embeddedapp
						shape.eventTargets.push(ufc.EventTargetType.EMBEDDED_APPLICATION);
					}
				}
				shape.children[shape.children.length] = this._createAsideShape();
			}

			if (this._useBodyScroll()) {
				// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/7934
				// 바디 스크롤인 경우, 클리핑 여부와 상관 없이 항상 콘텐트를 뷰포트 스크롤을 통해 볼 수 있어야 함.
				shape.style.overflow = "visible"
				this.getLayout()._applyBodyScrollToContainerShape(shape);
			}

			return shape;
		}

		/**
		 * 레이아웃의 일부 요소를 제어할 수 있는 훅.
		 * @param nodename 레이아웃 내 노드 명.
		 * @param shape 쉐이프 노드.
		 */
		public _hookLayout(nodename: string, shape: ufc.ElementShape) {
			switch (nodename) {
				case layouts.LayoutConstants.NODE_NAME__CONTENT_PANE: {
					if (this._appContainer) {
						let prefSize = this.getAppInstance().getPreferredSize();

						if (prefSize) {
							shape.style = shape.style || {};
							if (prefSize.width > 0) {
								shape.style["min-width"] = `${prefSize.width}px`;
							}
							if (prefSize.height > 0) {
								shape.style["min-height"] = `${prefSize.height}px`;
							}
						}
					}
					break;
				}
			}
		}

		public _createGlobalAsideShape(appInstance: core.AppInstance): ufc.ElementShape {
			let shape: ufc.ElementShape = {
				tag: "div",
				classNames: [ufc.Classes.GLOBAL_ASIDE_LAYER],
				attr: {
					"data-role": "application",
					"data-app": appInstance.uuid
				},
				eventTargets: [ufc.EventTargetType.APPLICATION],
				style: {
					"z-index": "2"
				},
				nodename: 'global',
				children: []
			};

			this._getGlobalAsideControls().forEach((control: UIControl) => {
				shape.children[shape.children.length] = control._getRenderer();
			})

			return shape;
		}

		public _createAsideShape(): ufc.ElementShape {
			let shape: ufc.ElementShape = {
				tag: "div",
				classNames: [ufc.Classes.ASIDE_LAYER],
				attr: {
				},
				nodename: "aside",
				style: {
					"z-index": "1"
				},
				children: []
			};

			let asideControls: (UIControl | AsideShape)[] = this._asideContents.keys();
			asideControls.forEach((control: UIControl | AsideShape) => {
				let index = this._asideContentsOrder.indexOf(control);
				if (control instanceof UIControl) {
					shape.children[shape.children.length] = control._getRenderer();
				} else {
					let asideShape: AsideShape = control as AsideShape;
					asideShape._css("z-index", String(index + 1));
					shape.children[shape.children.length] = asideShape._getShape();
				}
			});

			return shape;
		}

		public override _getType(): ControlType {
			return ControlType.CONTAINER;
		}
		public override _getLabelableType(): LabelableType {
			return LabelableType.div;
		}

		protected _setTabindex(tabindex: number): void {
			// default로 Container는 Focus를 가지지 않음.
		}
		protected _getTabindex(): number {
			// default로 Container는 Focus를 가지지 않음.
			return -1;
		}

		/* Methods Support App */
		public override _accept(visitor: (control: UIControl) => boolean): void {
			if (visitor(this) ?? true) {
				this._children.keys().forEach(it => it._accept(visitor));
				this._getAsideControls().forEach(it => it._accept(visitor));
				this._getGlobalAsideControls().forEach(it => it._accept(visitor));
			}
		}

		/**
		 * @override
		 * 해당 appInstance를 입양합니다.
		 * @param appInstance 입양할 app
		 */
		public override _onAdapt(appInstance: core.AppInstance): void {
			super._onAdapt(appInstance);
			this._children.keys().forEach(it => it._onAdapt(appInstance));

			this._getAsideControls().forEach(it => it._onAdapt(appInstance));

			this._getGlobalAsideControls().forEach(it => it._onAdapt(appInstance));
		}

		/**
		 * 해당 appInstance를 파양합니다.
		 * @param oldAppInstance 파양할 app
		 */
		public override _onOrphan(appInstance: core.AppInstance): void {
			super._onOrphan(appInstance);
			this._children.keys().forEach(it => it._onOrphan(appInstance));

			this._getAsideControls().forEach(it => it._onOrphan(appInstance));

			this._getGlobalAsideControls().forEach(it => it._onOrphan(appInstance));
		}

		public _isAsideChild(control: UIControl) {
			return this._asideContents.keys().indexOf(control) !== -1;
		}

		// @override
		protected override _isFocusable(): boolean {
			return false;
		}

		public override _getAutoSizeAvailability(): layouts.AutoSizeType {
			if (this._layout) {
				return this._layout._getSupportedAutoSizeMode();
			}

			return layouts.AutoSizeType.none;
		}

		public override _getAutoSizingTypeOfConstraint(): layouts.AutoSizeType {
			if (this._appContainer && this.getAppInstance()) {
				let host = this.getAppInstance().getHost();
				if (host) {
					// 임베디드 앱 또는 UDC인 경우, 호스트 컨트롤 쪽에 계산을 위임.
					return host._getAutoSizingTypeOfConstraint();
				}
			}
			return super._getAutoSizingTypeOfConstraint();
		}

		public override _redrawAndPropagteResizeToSibilings(): void {
			if (this.isAppContainer) {
				let host = this.getAppInstance().getHost();
				if (host) {
					// 임베디드 앱 또는 UDC인 경우, 호스트 컨트롤의 컨스트레인트를 업데이트.
					host._redrawAndPropagteResizeToSibilings();
				}
			}
			else {
				super._redrawAndPropagteResizeToSibilings();
			}
		}

		public override _afterDraw(firstDraw: boolean = false): void {
			super._afterDraw(firstDraw);
			if (this._layout) {
				this._layout._afterDraw(firstDraw);
			}
		}

		// chlid의 크기가 변경되었을 때 내부이벤트(-child-size-changed-)를 발생시켜 후 처리를 할 수 있는 기회를 줌
		// 현재 가상 스크롤바의 높이 재계산에 이용
		private _childSizeChangeEventScheduled = false;
		public _applyChildSizeChanging(child: UIControl): void {
			if (this.disposed || this._childSizeChangeEventScheduled || !child) {
				return;
			}
			this._scheduleChildSizeChanging();
		}
		private _scheduleChildSizeChanging(): void {
			if (this.disposed || this._childSizeChangeEventScheduled) {
				return;
			}
			this._childSizeChangeEventScheduled = true;
			this._propagateChangedSize();

			let redrawScheduled: boolean = core.DeferredUpdateManager.INSTANCE._isDirtyControl(this);
			core.DeferredUpdateManager.INSTANCE._asyncExecLast(() => {
				this._childSizeChangeEventScheduled = false;
				if (this.disposed) {
					return;
				}
				if (redrawScheduled === false) {
					let eventObj: events.CUIEvent = new events.CUIEvent("-child-size-changed-");
					this.dispatchEvent(eventObj);
				}
			});
		}

		private _propagateChangedSize(): void {
			let autoSizeType: layouts.AutoSizeType = this._getAutoSizingTypeOfConstraint();
			if (autoSizeType && autoSizeType != layouts.AutoSizeType.none) {
				let container: Container = this.getParent();
				if (!container) {
					let host = this.getAppInstance().getHost();
					if (host) {
						container = host.getParent();
					}
				}
				if (container) {
					container._applyChildSizeChanging(this);
				}
			}
		}

		public override redraw(): void {
			// UDC나 임베디드 앱의 루트 컨텐트라면 클리핑 및 스크롤 업데이트를 위해 호스트도 함께 새로 그립니다.
			// https://gitlab.exbuilder.co.kr/cleopatra-dev-team/release-test-project/-/issues/4899
			if (this.isAppContainer && this.getAppInstance() && this.getAppInstance().getHost()) {
				let host = this.getAppInstance().getHost();
				if (host._useClippingRuleOfContent()) {
					this.getAppInstance().getHost().redraw();
					return;
				}
			}
			super.redraw()
		}

		// asideshape controlrenderer api
		public _addAsideShapeToAppContainer(owner: UIControl, shape: ufc.ElementShape): void {
			let appContainer: Container = this._getAppContainerParent();
			if (appContainer) {
				this._addAsideShape(appContainer, owner, shape);
			}
		}
		public _updateAsideShapeToAppContainer(owner: UIControl, shape: ufc.ElementShape): void {
			let appContainer: Container = this._getAppContainerParent();
			if (appContainer) {
				this._updateAsideShape(appContainer, owner, shape);
			}
		}
		public _removeAsideShapeFromAppContainer(owner: UIControl): boolean {
			let appContainer: Container = this._getAppContainerParent();
			if (appContainer) {
				return this._removeAsideShape(appContainer, owner);
			}
			return false;
		}
		public _getAppContainerParent(): Container {
			let parent: Container = this;
			for (; parent != null && parent.isAppContainer == false;) {
				parent = parent.getParent();
			}
			return parent != null && parent.isAppContainer ? parent : null;
		}
		private _addAsideShape(appContainer: Container, owner: UIControl, shape: ufc.ElementShape): void {
			if (!owner || !shape) {
				throw new exceptions.IllegalArgumentException();
			}
			if (appContainer._containsDrawble(owner) == false) {
				throw new exceptions.IllegalArgumentException();
			}

			let asideShape: AsideShape = new AsideShape(owner, shape);
			appContainer._asideContents.put(asideShape, layouts._newManualConstraint());
			appContainer._asideContentsOrder[appContainer._asideContentsOrder.length] = asideShape;

			let renderer: ufc.ControlRenderer = appContainer._getRenderer();
			renderer.insert("aside", appContainer._asideContentsOrder.length - 1, [asideShape._getShape()]); // sync
		}

		private _updateAsideShape(appContainer: Container, owner: UIControl, shape: ufc.ElementShape): void {
			if (!owner || !shape) {
				throw new exceptions.IllegalArgumentException();
			}
			if (appContainer._containsDrawble(owner) == false) {
				throw new exceptions.IllegalArgumentException();
			}

			let existingIdx: number = -1;
			let exists: boolean = appContainer._asideContentsOrder.some((item: UIControl | AsideShape, idx: number) => {
				if (item instanceof AsideShape) {
					if (item._getOwner() == owner) {
						existingIdx = idx;
						return true;
					} else {
						return false;
					}
				}
				return false;
			});

			if (!exists) {
				throw new exceptions.IllegalArgumentException("asideshape not found : " + owner);
			}

			let asideShape: AsideShape = appContainer._asideContentsOrder[existingIdx] as AsideShape;
			asideShape._setShape(shape);

			let renderer: ufc.ControlRenderer = appContainer._getRenderer();
			renderer.replace(asideShape._getNodename(), asideShape._getShape()); // sync

		}
		private _removeAsideShape(appContainer: Container, owner: UIControl): boolean {
			if (appContainer == null || appContainer.disposed) {
				return false;
			}
			let existingIdx: number = -1;
			let exists: boolean = appContainer._asideContentsOrder.some((item: UIControl | AsideShape, idx: number) => {
				if (item instanceof AsideShape) {
					if (item._getOwner() == owner) {
						existingIdx = idx;
						return true;
					} else {
						return false;
					}
				}
				return false;
			});
			if (exists) {
				let asideShape: AsideShape = appContainer._asideContentsOrder[existingIdx] as AsideShape;
				let asideNodeName: string = asideShape._getNodename();

				let renderer: ufc.ControlRenderer = appContainer._getRenderer();
				renderer.delete(asideNodeName); // sync

				appContainer._asideContentsOrder.splice(existingIdx, 1);
				appContainer._asideContents.remove(asideShape);

				asideShape.dispose();

				appContainer._reorderAsideContents();

				return true;
			}

			return false;
		}
	}

}