namespace cpr.expression {
	/**
	 * 표현식 대리자 객체를 생성합니다.
	 * @private
	 */
	export class ExpressionDelegateObject {
		private _props: {} = {};
		private _expressionPropertyName: string;
		private _controlType: string;

		constructor(controlType: string, expressionPropertyName: string, props: {} = {}) {
			_assign(this._props, props);
			this._expressionPropertyName = expressionPropertyName;
			this._controlType = controlType;
		}

		public getProperty(propName: string): any {
			return this._props[propName];
		}

		public setProperty(propName: string, value: any): void {
			this._props[propName] = value;
		}

		public hasProperty(propName: string): boolean {
			return this._props.hasOwnProperty(propName);
		}

		public setUnsupportedProperty(propName: string, value: any): void {
			let expressionPropertyName = this._expressionPropertyName;
			let controlType = this._controlType;
			Object.defineProperty(this._props, propName, {
				get: function () {
					console.error(`UnsupportedOperationException: '${propName}' property is not supported in '${expressionPropertyName}' of '${controlType}'.`);
					return value;
				}
			});
		}

		public removeProperty(propName: string): void {
			delete this._props[propName];
		}

		public createObject(): {} {
			return this._props;
		}
	}
}