namespace cpr.utils {
	/**
	 * 중복 계산을 방지할 수 있는 레이지 캐시 객체.
	 * @private
	 */
	export class LazyCache {
		private _cache: { [key: string]: any } = {};
		private _noValueSet: { [key: string]: boolean } = {};

		/**
		 * 주어진 계산 키에 대해 사전 계산된 결과가 있다면 캐시된 값을 리턴하고, 그렇지 않은 경우, 주어진 계산을 수행하여 결과를 
		 * @param key 계산의 키.
		 * @param provider 계산을 수행하고 결과를 반환하는 함수.
		 */
		public get<ReturnType>(key: string, provider: () => ReturnType): ReturnType {
			if (this._noValueSet[key]) {
				return null;
			}

			let existingValue = this._cache[key];
			if (existingValue == null) {
				existingValue = provider();
				if (existingValue != null) {
					this._cache[key] = existingValue;
				} else {
					this._noValueSet[key] = true;
				}
			}

			return existingValue as ReturnType;
		}

		public invalidateAll() {
			this._cache = {};
			this._noValueSet = {};
		}
	}
}