/// <reference path="./provider/DataBindable.ts"/>

namespace cpr.controls {
	/**
	 * 컨트롤 방향에 대한 유형.
	 */
	type SliderOrientationType = "horizontal" | "vertical";

	/**
	 * 방향에 따른 0의 시작 기준
	 */
	type SliderDirectionType = "forward" | "backward";

	/**
	 * 슬라이더 레이블 표시유형.
	 */
	type SliderLabelDisplayType = "auto" | "show" | "hide";

	/**
	 * 슬라이더 label 정렬
	 */
	export enum LabelAlign {
		/** 슬라이더가 가로 방향일 때 handle의 위에 label이 배치 됩니다. 세로 방향 일 때는 handle의 왼쪽에 label이 배치됩니다. */
		leading = "leading",

		/** 슬라이더가 가로 방향일 때 handle의 아래에 label이 배치 됩니다. 세로 방향 일 때는 handle의 오른쪽에 label이 배치됩니다. */
		trailing = "trailing"
	}

	/**
	 * @private
	 */
	class SliderHandleManager {
		private _handles: SliderHandle[] = [];
		private _owner: Slider;

		constructor(owner: Slider) {
			this._owner = owner;
			this.addHandle();
		}

		public _getOwner() {
			return this._owner;
		}

		public getValue(index: number): number {
			let values = this.getValues();
			let min = this._getMin();
			let max = this._getMax();
			let value = values[index];
			let numberValue: number;
			if (value == null) {
				numberValue = (index == 0 ? min : max);
			} else {
				numberValue = utils.StringUtil._isInt(value) ? parseInt(value) : parseFloat(value);
				if (isNaN(numberValue)) {
					numberValue = index == 0 ? min : max;
				}
				numberValue = min > numberValue ? min : (max < numberValue ? max : numberValue);
			}
			return numberValue;
		}

		public getText(): string {
			let result = [];
			// 값의 순서가 다른 경우에 대한 검증 필요.
			this.validateHandle();
			this.getHandles().forEach((each: SliderHandle) => {
				result.push(ufc.StyledString._asString(each._computeDisplayText()));
			});
			return result.join(this._getDelimiter());
		}

		public getHandles() {
			return this._handles.slice();
		}

		public addHandle() {
			let handle = new SliderHandle(this._handles.length, this);
			this._handles[this._handles.length] = handle;
		}

		public removeHandle(handle: SliderHandle) {
			let index = this._handles.indexOf(handle);
			if (index > -1) {
				this._handles.splice(index, 1);
			}
		}

		/**
		 * handle이 소유한 마지막 인덱스를 가진 것을 삭제합니다.
		 */
		public removeLastHandle() {
			let indexedHandles = _.sortBy(this._handles, (handle: SliderHandle) => { return handle.index });
			let handle = indexedHandles[indexedHandles.length - 1];
			let lastIndex = this._handles.indexOf(handle);
			if (lastIndex > -1) {
				this._handles.splice(lastIndex, 1);
			}
		}

		public getLocation(index: number) {
			let value = this.getValue(index);
			let min = this._getMin();
			let max = this._getMax();
			return this._toPercentage([min, max], value);
		}

		public moveHandle(locations: number[], index: number, to: number, lookForward: boolean, lookBackward: boolean, round: boolean = true) {
			let movePosition = this._checkHandlePosition(locations, index, to, lookForward, lookBackward, round);
			let movedValue = this._isPercentage([this._getMin(), this._getMax()], movePosition);
			let result = [];
			this._handles.forEach((each: SliderHandle, idx: number) => {
				if (index == idx) {
					result.push(movedValue.toFixed(2));
				} else {
					result.push(each.value.toFixed(2));
				}
			});
			this._setValue(result.join(this._getDelimiter()));
		}

		public validateHandle() {
			// 값에 따라 핸들 순서 조정.
			this._handles = _.sortBy(this._handles, (handle: SliderHandle) => { return handle.value });
		}

		private _getMin(): number {
			return this._owner.min;
		}
		private _getMax(): number {
			return this._owner.max;
		}
		private _getDelimiter(): string {
			return this._owner.delimiter;
		}
		private _setValue(value: string) {
			this._owner.value = value;
		}
		public getValues(): string[] {
			let value = this._owner.value;
			if (value) {
				return value.split(this._owner.delimiter);
			}
			return [];
		}

		private _checkHandlePosition(locations: number[], handleNumber: number, to: number, lookForward: boolean, lookBackward: boolean, round: boolean) {
			if (this._handles.length > 1) {
				if (lookBackward && handleNumber > 0) {
					to = Math.max(to, locations[handleNumber - 1]);
				}
				if (lookForward && handleNumber < this._handles.length - 1) {
					to = Math.min(to, locations[handleNumber + 1]);
				}
			}
			let value = this._isPercentage([this._getMin(), this._getMax()], to);
			// step에 의한 value 이동 보정
			to = this._getStep(value, round);
			// 위치의 최소/최대 크기 체크
			to = this._limit(to);
			return to;
		}

		private _limit(perc: number) {
			return Math.max(Math.min(perc, 100), 0);
		}

		private _getStep(value: number, round: boolean) {
			let min = this._getMin();
			let max = this._getMax();
			let step = this._owner.step;
			if (value == max || value == min) {
				return this._toPercentage([min, max], value);
			}
			let r = round ? Math.round(value / step) : value / step;
			let a = r * step;
			a = this._toPercentage([min, max], a);
			return a;
		}

		/**
		 * 퍼센트 값이 범위에서 얼마인지 계산한다. 
		 * @param range [0]min [1]max
		 * @param perc 
		 * @return value를 반환한다.
		 */
		private _isPercentage(range: number[], perc: number): number {
			return ((perc * (range[1] - range[0])) / 100) + range[0];
		}
		/**
		 * 범위에서 값을 퍼센트로 계산한다.
		 * @param range [0]min [1]max
		 * @param value 
		 */
		private _toPercentage(range: number[], value: number): number {
			return this._fromPercentage(range, range[0] < 0 ? value + Math.abs(range[0]) : value - range[0]);
		}
		/**
		 * 범위에서 값이 몇 퍼센트인지 계산한다.
		 * @param range [0]min [1]max
		 * @param value 
		 */
		private _fromPercentage(range: number[], value: number): number {
			return (value * 100) / (range[1] - range[0]);
		}

		public dispose() {
			this._owner = null;
			this._handles = null;
		}
	}

	/**
	 * @private
	 */
	export class SliderHandle implements bind.BindablePropertiesOwner, expression.EvaluationContext {
		private _index: number;
		private _manager: SliderHandleManager;
		public enabled: boolean = true;

		constructor(index: number, manager: SliderHandleManager) {
			this._index = index;
			this._manager = manager;
		}

		public get index(): number {
			return this._index;
		}

		public get value(): number {
			return this._manager.getValue(this._index);
		}

		public get length(): number {
			return this._manager.getHandles().length;
		}

		public _getCount(): number {
			return this.length;
		}

		public _getLocation() {
			return this._manager.getLocation(this._index);
		}

		public _computeDisplayText(): string | ufc.StyledString {
			let expression = this._manager._getOwner()._getLabelExpObj();
			if (!expression) {
				return this.value.toFixed(2) + "";
			}

			return expression.evaluate({
				_getExpressionDelegates: () => {
					return [
						this.getBindContext()
					]
				}
			});
		}

		/**
		 * bind 문맥을 반환합니다.
		 * @return bind 문맥
		 */
		getBindContext(): bind.BindContext {
			let owner = this._manager._getOwner();
			if (owner) {
				return new bind.SliderHandleContext(this, owner);
			} else {
				return new bind.SliderHandleContext(this, null);
			}
		}
		_getExpressionDelegates(): any[] {
			let owner = this._manager._getOwner();
			if (owner) {
				return [owner]
			}
			return [];
		}
	}

	/**
	 * Slider
	 * 범위 조절이 하는 슬라이더.
	 * 
	 * @firesgroup mouse
	 * @firesgroup contextmenu
	 * @firesgroup bindcontext
	 * @firesgroup keyboard
	 * @firesgroup focus
	 * @firesgroup drop
	 * 
	 * 
	 * @fires cpr.events.CValueChangeEvent#before-value-change 값이 변경되기 전에 발생하는 이벤트.
	 * 다음 이벤트로 value-change가 발생합니다.
	 * <pre>oldValue: {string} 이전 값</pre>
	 * <pre>newValue: {string} 변경될 값</pre>
	 * 
	 * @fires cpr.events.CValueChangeEvent#value-change 값이 변경된 후에 발생하는 이벤트.
	 * <pre>oldValue: {string} 이전 값</pre>
	 * <pre>newValue: {string} 변경된 값</pre>
	 */
	export class Slider extends AccessableUIControl implements provider.ValueBindable, gridpart.IGridParticipant {
		private static readonly _AVAILABLE_PROP: string[] = [
			"value", "text", "delimiter", "step", "max", "min", "direction", "orientation",
			"range"
		];
		// 2020-08-26 value를 설정했을때 컨트롤에서 값을 변경하지 않아야 한다.
		// 2020-08-26 value가 최대값, 최소값을 넘어도 값을 변경하지 않아야 한다.(보여주는것은 최소값, 최대값으로 위치)
		// https://refreshless.com/nouislider/ 을 참고하여 만들었음.
		// default value
		private _binder: provider.ValueBinder;
		private _manager: SliderHandleManager;
		private _delimiter: string = ",";
		private _range: boolean = false;
		private _orientation: SliderOrientationType = "horizontal";
		private _direction: SliderDirectionType = "forward";
		private _labelExp: expression_string;
		private _labelExpObj: expression.Expression;
		private _labelDisplay: SliderLabelDisplayType = "hide";
		private _labelAlign: LabelAlign = LabelAlign.leading;

		private _displayLabelIndex: number = -1;
		private _isMoving: boolean = false;
		private _dragData: { handleIndex: number, position: number, locations: number[] } = { handleIndex: 0, position: 0, locations: [] };

		private _mouseEventDispatcher = (e: events.CMouseEvent) => {
			if (e.type == "mousemove" || e.type == "touchmove") {
				this._eventMove(e);
			} else if (e.type == "mouseup" || e.type == "touchend") {
				this._eventEnd(e);
			}
		}
		/**
		 * 슬라이더를 생성합니다.
		 * @param id 슬라이더의 id
		 */
		constructor(id?: string) {
			super(id);
			this._binder = new provider.ValueBinder(this);
			this._manager = new SliderHandleManager(this);
			this._addBindableProperty("max", 100).withSetterValidatorWithType(false, "number");
			this._addBindableProperty("min", 0).withSetterValidatorWithType(false, "number");
			this._addBindableProperty("step", 1).withSetterValidatorWithType(false, "number");

			// control initializing
			this._initControl();

		}

		protected _isConfigurableProperty(propName: string): boolean {
			if (Slider._AVAILABLE_PROP.indexOf(propName) != -1) {
				return true;
			}
			return super._isConfigurableProperty(propName);
		}

		/* Shape */
		protected _getStylerSpec(): UIControlStylerSpec {
			return {
				root: { baseClass: "cl-slider" },
				handle: { baseClass: "cl-slider-handle" },
				range: { baseClass: "cl-slider-range" },
				bar: { baseClass: "cl-slider-bar" },
				label: { baseClass: "cl-slider-label" }
			};
		}

		/**
		 * 자동 크기 지원 타입을 얻습니다.
		 * 만일 both를 리턴했다면, css height, width 속성에 auto를 사용할 수 있음을 나타냅니다.
		 */
		public _getAutoSizeAvailability(): layouts.AutoSizeType {
			return layouts.AutoSizeType.both;
		}

		public _convertGridPasteText(text: string): string {
			return text;
		}

		public _getGridViewingText(): string {
			let value: string = this.value;
			let text: string = (value == null || value == "") ? "" : this.text;
			return text;
		}

		public _renderGridCellShape(grid: Grid, data: (string | ufc.StyledString), option: gridpart.renderer.IRenderOption): ufc.ControlShape {
			let slider: Slider = this as Slider;

			let isHorizontal = slider._isHorizontal();
			let sliderShape: ufc.ControlShape = {
				tag: "div",
				classNames: ["cl-control", "cl-slider", ufc.Classes.UNSELECTABLE, isHorizontal ? "cl-horizontal" : "cl-vertical"],
				attr: {},
				style: {
					"touch-action": "manipulation"
				},
				children: []
			};
			if (option.maxHeight >= 0) {
				sliderShape.style["height"] = option.maxHeight + "px";
			}

			let barShape: ufc.ElementShape = {
				tag: "div",
				classNames: ["cl-slider-bar", isHorizontal ? "cl-horizontal" : "cl-vertical"],
				style: {},
				children: []
			};
			gridpart.GridUtil._applyControlStyler(barShape, slider.style["bar"], null);		//apply styler
			sliderShape.children.push(barShape);

			slider._validateHandle();

			let handles = slider._getHandles();
			let min = handles.length > 1 ? handles[0]._getLocation() + "%" : "0%";
			let max = (100 - handles[handles.length - 1]._getLocation()) + "%";
			let rangeShape: cpr.ufc.ElementShape = {
				tag: "div",
				classNames: ["cl-slider-range"],
				style: {},
				styler: "range",
				nodename: "range"
			}
			gridpart.GridUtil._applyControlStyler(rangeShape, slider.style["range"], null);		//apply styler

			let isForward: boolean = slider._isForward();
			switch (slider.orientation) {
				case "horizontal": {
					if (isForward) {
						rangeShape.style["left"] = min;
						rangeShape.style["right"] = max;
					} else {
						rangeShape.style["left"] = max;
						rangeShape.style["right"] = min;
					}
					break;
				}

				case "vertical": {
					if (isForward) {
						rangeShape.style["top"] = max;
						rangeShape.style["bottom"] = min;
					} else {
						rangeShape.style["top"] = min;
						rangeShape.style["bottom"] = max;
					}
					break;
				}

			}
			barShape.children.push(rangeShape);
			for (let i = 0; i < handles.length; i++) {
				let handle = handles[i];

				let handleShape: cpr.ufc.ElementShape = {
					tag: "div",
					classNames: ["cl-slider-handle", isHorizontal ? "cl-horizontal" : "cl-vertical"],
					style: {},
					attr: {
						"data-handle": i + "",
						role: "slider"
					},
					nodename: "handle-" + i,
					children: []
				}
				gridpart.GridUtil._applyControlStyler(handleShape, slider.style["handle"], null);		//apply styler
				cpr.ufc.ShapeUtil._setTooltipAttr(handleShape, { owner: slider, title: slider.tooltip || handle.value.toFixed(2), id: "sld-" + option.vrowIndex + "-" + option.cellIndex });
				cpr.ufc.ShapeUtil._setAriaDisabled(handleShape, slider.enabled && !slider.readOnly);
				gridpart.GridUtil._setAria(handleShape, "valuenow", handle.value + "");
				gridpart.GridUtil._setAria(handleShape, "valuemax", slider.max + "");
				gridpart.GridUtil._setAria(handleShape, "valuemin", slider.min + "");
				if (slider.range) {
					if (i == 0) {
						gridpart.GridUtil._setAria(handleShape, "valuemax", slider._getHandleValue(i + 1) + "");
					} else if (i == 1) {
						gridpart.GridUtil._setAria(handleShape, "valuemin", slider._getHandleValue(i - 1) + "");
					}
				}

				let location: number = handle._getLocation();
				if (slider._isForward()) {
					isHorizontal ? handleShape.style["left"] = location + "%" : handleShape.style["top"] = (100 - location) + "%";
				} else {
					isHorizontal ? handleShape.style["left"] = (100 - location) + "%" : handleShape.style["top"] = location + "%";
				}

				barShape.children.push(handleShape);
			}

			return sliderShape;
		}

		/* control's type overriding */
		override _getType(): ControlType {
			return ControlType.SLIDER;
		}
		override _getLabelableType(): LabelableType {
			return LabelableType.div;
		}

		protected _isEditable(): boolean {
			return (this.isAvailableBinding("value") == true);
		}

		/**
		 * @param name 
		 * @param oldValue 
		 * @param newValue 
		 */
		_valueDidChange(name: string, oldValue: any, newValue: any) {
			super._valueDidChange(name, oldValue, newValue);
			this._binder._valueDidChange(name, oldValue, newValue);
			switch (name) {
				case "max":
				case "min":
				case "step": {
					this.redraw(); break;
				}
			}
		}

		/* property */

		/// SimpleDataBindable Start ////////////////////////////////////////////
		/**
		 * 컨트롤의 값을 설정하고, value-change이벤트가 발생됩니다.
		 * @param value 컨트롤의 값.
		 */
		public set value(value: string) {
			if (typeof value == "string") {
				this._binder.setValue(this._checkValue(value));
			} else {
				this._binder.setValue(value);
			}
		}

		private _checkValue(value: string) {
			let values = value.split(this.delimiter);
			let validateValues = []
			values.forEach((each: string) => {

				let numberValue: number;
				if (utils.StringUtil._isInt(each)) {
					numberValue = parseInt(each);
				} else {
					numberValue = parseFloat(each);
				}
				if (isNaN(numberValue)) {
					validateValues.push(each);
				} else {
					let newNumberValue = Math.max(this.min, Math.min(this.max, numberValue));
					if (newNumberValue == numberValue) {
						validateValues.push(each);
					} else {
						validateValues.push(String(newNumberValue));
					}
				}
			});
			return validateValues.join(this.delimiter);
		}

		/**
		 * 컨트롤의 값을 반환합니다.
		 * @return 컨트롤의 값.
		 */
		public get value(): string {
			return this._binder.getValue();
		}

		/**
		 * 슬라이더의 값을 숫자 형식으로 얻습니다. range 모드일 때는 IllegalStateException 예외가 발생합니다.
		 */
		public get numberValue(): number {
			if (this.range) {
				throw new exceptions.IllegalStateException("Ranged slider doesn't support number value.")
			}
			return parseFloat(this.value ?? "0");
		}

		/**
		 * 슬라이더의 값을 숫자 형식으로 지정합니다. range 모드일 때는 IllegalStateException 예외가 발생합니다.
		 */
		public set numberValue(newNumber: number) {
			if (this.range) {
				throw new exceptions.IllegalStateException("Ranged slider doesn't support number value.")
			}
			newNumber = Math.max(this.min, Math.min(this.max, newNumber));
			this.value = String(newNumber)
		}

		/**
		 * 컨트롤의 값을 설정합니다.
		 * @param value 
		 */
		public putValue(value: string) {
			if (typeof value == "string") {
				this._binder.setValue(this._checkValue(value), false);
			} else {
				this._binder.setValue(value, false);
			}
		}

		/**
		 * 컨트롤에 보여지는 텍스트를 반환합니다.
		 * @return 화면에 보이는 텍스트.
		 */
		public get text(): string {
			return this._manager.getText();
		}

		/**
		 * 컨트롤에 보이는 텍스트를 설정합니다.
		 * @param 화면에 보이는 텍스트.
		 */
		public set text(text: string) {
			this._binder.setText(text);
		}

		/// SimpleDataBindable End ////////////////////////////////////////////////

		/**
		 * 다중 선택된 값을 지정하거나 가져올 때의 구분자를 반환합니다.
		 * @return 구분자.
		 */
		public get delimiter(): string {
			return this._delimiter;
		}

		/**
		 * 다중선택된 값을 지정하거나 가져올 때의 구분자를 설정합니다.
		 * @param delimiter 구분자.
		 */
		public set delimiter(delimiter: string) {
			if (this._delimiter == delimiter) {
				return;
			}
			let oldValues = this._manager.getValues();
			this._delimiter = delimiter;
			if (oldValues.length > 1) {
				this.value = oldValues.join(this._delimiter);
			}
			this.redraw();
		}

		/**
		 * 증가 값을 반환합니다.
		 * @return 증가 값
		 */
		public get step(): number {
			return this._bindables.get("step");
		}

		/**
		 * 증가 값을 설정합니다.
		 * @param step 증가 값
		 */
		public set step(step: number) {
			this._bindables.set("step", step);
		}

		/**
		 * 최대로 입력 가능한 값을 반환합니다.
		 * @return 최댓값
		 */
		public get max(): number {
			return this._bindables.get("max");
		}

		/**
		 * 최댓값을 설정합니다.
		 * @param value 최댓값.
		 */
		public set max(max: number) {
			this._bindables.set("max", max);
		}

		/**
		 * 최소로 입력 가능한 값을 반환합니다.
		 * @return 최솟값
		 */
		public get min(): number {
			return this._bindables.get("min");
		}
		/**
		 * 최소로 입력 가능한 값을 설정합니다.
		 * @param min 최솟값
		 */
		public set min(min: number) {
			this._bindables.set("min", min);
		}

		/**
		 * Slider의 이동방향을 반환합니다.
		 * @return Slider 이동방향 형식
		 */
		public get direction(): SliderDirectionType {
			return this._direction;
		}

		/**
		 * Slider의 이동방향을 설정합니다.<br>
		 * [forward] : 순방향 <br>
		 * [backward] : 역방향 <br>
		 * @param direction Slider 방향설정 값
		 */
		public set direction(direction: SliderDirectionType) {
			if (this._direction == direction) {
				return;
			}
			this._direction = direction;
			this.redraw();
		}

		/**
		 * Slider의 방향을 설정합니다.<br>
		 * [horizontal] : 가로 방향 <br>
		 * [vertical] : 세로 방향 <br>
		 * @param ort Slider의 방향.
		 */
		public set orientation(ort: SliderOrientationType) {
			if (this._orientation == ort) {
				return;
			}
			this._orientation = ort;
			this.redraw();
		}

		/**
		 * Slider의 방향을 반환합니다.,
		 * @return Slider의 방향.
		 */
		public get orientation(): SliderOrientationType {
			return this._orientation;
		}

		/**
		 * 값의 범위를 조정하는 모드 적용 여부를 반환합니다.
		 * @return 모드 적용 여부.
		 */
		public get range(): boolean {
			return this._range;
		}
		/**
		 * 값의 범위를 조정하는 모드 적용 여부를 설정합니다.
		 * @param range 모드 적용 여부.
		 */
		public set range(range: boolean) {
			if (this._range == range) {
				return;
			}
			this._range = range;
			let handles = this._manager.getHandles();
			if (range) {
				if (handles.length == 1) {
					this._manager.addHandle();
				}
			} else {
				if (handles.length > 1) {
					for (let i = 1; i < handles.length; i++) {
						this._manager.removeLastHandle();
					}
				}
			}
			// 값의 순서가 다를 경우 검증 필요.
			this._manager.validateHandle();
			this.redraw();
		}

		_getLabelExpObj(): expression.Expression {
			let src = this._labelExp;

			if (utils.Util.isNullOrEmpty(src)) {
				return null;
			}

			if (this._labelExpObj?.src == src) {
				return this._labelExpObj;
			}

			this._labelExpObj = new cpr.expression.Expression(src);
			return this._labelExpObj;
		}

		/**
		  * 슬라이더 핸들의 레이블 정렬을 반환합니다.
		  */
		get labelAlign(): LabelAlign {
			return this._labelAlign;
		}

		/**
		 * 슬라이더 핸들의 레이블 정렬을 설정합니다.
		 * <ul>
		 * <li>leading: 슬라이더가 가로 방향일 때 handle의 위에 label이 배치 됩니다. 세로 방향 일 때는 handle의 왼쪽에 label이 배치됩니다.</li>
		 * <li>trailing: 슬라이더가 가로 방향일 때 handle의 아래에 label이 배치 됩니다. 세로 방향 일 때는 handle의 오른쪽에 label이 배치됩니다.</li>
		 * </ul>
		 */
		set labelAlign(newAlignMode: LabelAlign) {
			if (this._labelAlign == newAlignMode) {
				return;
			}
			this._labelAlign = newAlignMode;
			this.redraw();
		}

		/**
		 * 슬라이더 핸들 레이블의 표현식을 반환합니다.
		 */
		public get labelExp(): expression_string {
			return this._labelExp;
		}

		/**
		 * 슬라이더 핸들 레이블의 표현식을 설정합니다.
		 */
		public set labelExp(expression: expression_string) {
			if (this._labelExp == expression) {
				return;
			}
			this._labelExp = expression;
			this.redraw();
		}

		/**
		 * 슬라이더 핸들 레이블의 표시 방법을 반환합니다.
		 */
		public get labelDisplay(): SliderLabelDisplayType {
			return this._labelDisplay;
		}

		/**
		 * 슬라이더 핸들 레이블의 표시 방법을 설정합니다.<br>
		 * 그리드에서는 해당 속성이 적용되지 않습니다.
		 */
		public set labelDisplay(display: SliderLabelDisplayType) {
			if (this._labelDisplay == display) {
				return;
			}
			this._labelDisplay = display;
			this.redraw();
		}

		public _createShape(): cpr.ufc.ControlShape {
			let isHorizontal = this._isHorizontal();
			let bar: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: [isHorizontal ? "cl-horizontal" : "cl-vertical"],
				styler: "bar",
				style: {},
				children: [],
				nodename: "sliderbar",
				events: {}
			}

			// 데이터셋에서 직접 변경되었을때 순서 검증 필요.
			this._manager.validateHandle();

			bar.children.push(this._createRange());
			let handles = this._manager.getHandles();
			for (let i = 0; i < handles.length; i++) {
				let handle = handles[i];
				bar.children.push(this._createHandle(i, handle));
			}

			let shape: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: [
					ufc.Classes.UNSELECTABLE, isHorizontal ? "cl-horizontal" : "cl-vertical"
				],
				attr: {},
				styler: "root",
				style: {
					"touch-action": "manipulation",
					overflow: this.labelDisplay != "hide" ? "visible" : "hidden"
				},
				events: {},
				eventTargets: [
					ufc.EventTargetType.UICONTROL,
					ufc.EventTargetType.DROPPABLE
				],
				children: [bar]
			};

			if (!this.enabled) {
				delete shape.attr['tabindex'];
			}

			if (this.readOnly) {
				delete bar["events"];
				if (this.labelDisplay == "auto") {
					shape.events = { keydown: this._onKeydown };
				}
			} else {
				shape.events = {
					touchstart: this._onMouseDown,
					mousedown: this._onMouseDown,
					mouseup: this._onMouseUp,
					keydown: this._onKeydown
				}
			}

			return shape;
		}

		private _createLabel(handle: SliderHandle): ufc.ElementShape {
			let text: ufc.ElementShape = {
				tag: "div",
				children: ufc.StyledString._asShape(handle._computeDisplayText()),
				style: {
					overflow: "hidden"
				}
			}
			let needDisplay = true;
			if (this.labelDisplay == "auto" && this._displayLabelIndex != handle.index) {
				needDisplay = false;
			}
			let child = {
				tag: "div",
				classNames: [ufc.Classes.UNSELECTABLE, this._labelAlign == LabelAlign.leading ? "cl-leading" : "cl-trailing"],
				styler: "label",
				bindContext: new bind.SliderHandleContext(handle, this),
				attr: {
					"data-handle": handle.index + "",
				},
				style: {
					position: "absolute",
					display: needDisplay ? "block" : "none",
					"z-index": "1"
				},
				nodename: "handle-label-" + handle.index,
				children: [text],
				events: {

				}
			}

			if (this.readOnly) {
				delete child['events'];
			}
			return child;
		}

		private _createHandle(index: number, handle: SliderHandle) {
			let isHorizontal = this._isHorizontal();
			let shape: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: [isHorizontal ? "cl-horizontal" : "cl-vertical"],
				styler: "handle",
				style: {},
				attr: {
					"data-handle": index + "",
					tabindex: "0",
					role: "slider",
					"aria-valuenow": handle.value + "",
					"aria-valuemax": this.max + "",
					"aria-valuemin": this.min + ""
				},
				nodename: "handle-" + index,
				children: [],
				events: {}
			}

			cpr.ufc.ShapeUtil._setAriaLabelAttr(shape.attr, this._getFieldLabel());
			cpr.ufc.ShapeUtil._setTooltipAttr(shape, { owner: this, title: this.tooltip || handle.value.toFixed(2) });
			cpr.ufc.ShapeUtil._setAriaDisabled(shape, this.enabled && !this.readOnly);
			if (this.range) {
				if (index == 0) {
					shape.attr["aria-valuemax"] = this._manager.getValue(index + 1) + "";
				} else if (index == 1) {
					shape.attr["aria-valuemin"] = this._manager.getValue(index - 1) + "";
				}
			}
			if (!this.enabled) {
				delete shape.attr['tabindex'];
			}

			let location: number = handle._getLocation();
			if (this._isForward()) {
				isHorizontal ? shape.style["left"] = location + "%" : shape.style["top"] = (100 - location) + "%";
			} else {
				isHorizontal ? shape.style["left"] = (100 - location) + "%" : shape.style["top"] = location + "%";
			}
			if (this.readOnly) {
				shape.events = {};
			}
			if (!this.enabled) {
				delete shape.attr['tabindex'];
			}
			let labelDisplay = this.labelDisplay != "hide" && this.getParent() instanceof cpr.controls.Grid == false;
			if (labelDisplay) {
				shape.children.push(this._createLabel(handle));
				if (this.labelDisplay == "auto") {
					shape.events["focus"] = this._onFocusHandle;
					shape.events["blur"] = this._onBlurHandle;
					shape.events['mouseover'] = this._dispatchHoverRelativeEvent;
					shape.events["mouseenter"] = this._dispatchHoverRelativeEvent;
					shape.events['mouseleave'] = this._dispatchHoverRelativeEvent;

				}
			}
			return shape;
		}

		private _dispatchHoverRelativeEvent(e: events.CMouseEvent) {
			switch (e.type) {
				case "mouseover":
					this._onmouseover(e);
					break;
				case "mouseenter":
					this._onmouseenter(e);
					break;
				case "mouseleave":
					this._onmouseleave(e);
					break;
			}
		}

		private _onmouseover(e: MouseEvent) {
			let target = e.target as HTMLElement;
			let index = parseInt(target.getAttribute("data-handle"));
			this._displayLabelIndex = index;
			this.redraw();
		}

		private _onmouseenter(e: MouseEvent) {
			let target = e.target as HTMLElement;
			let index = parseInt(target.getAttribute("data-handle"));
			this._displayLabelIndex = index;
			this.redraw();
		}

		private _onmouseleave(e: MouseEvent) {
			this._displayLabelIndex = -1;
			this.redraw();
		}

		private _onFocusHandle(e: FocusEvent) {
			let target = e.target as HTMLElement;
			// 마우스로 인한 포커스인 경우 
			if (target.classList.contains("cl-slider-tap") == false) {
				let index = parseInt(target.getAttribute("data-handle"));
				this._displayLabelIndex = index;
				this.redraw();
			}
		}

		private _onBlurHandle(e: FocusEvent) {
			this._displayLabelIndex = -1;
			this.redraw();
		}

		private _createRange() {
			let handles = this._manager.getHandles();
			let min = handles.length > 1 ? handles[0]._getLocation() + "%" : "0%";
			let max = (100 - handles[handles.length - 1]._getLocation()) + "%";
			let shape: cpr.ufc.ControlShape = {
				tag: "div",
				classNames: ["cl-slider-range"],
				style: {},
				styler: "range",
				nodename: "range"
			}

			let isForward: boolean = this._isForward();
			switch (this.orientation) {
				case "horizontal": {
					if (isForward) {
						shape.style["left"] = min;
						shape.style["right"] = max;
					} else {
						shape.style["left"] = max;
						shape.style["right"] = min;
					}
					break;
				}

				case "vertical": {
					if (isForward) {
						shape.style["top"] = max;
						shape.style["bottom"] = min;
					} else {
						shape.style["top"] = min;
						shape.style["bottom"] = max;
					}
					break;
				}

			}
			return shape;
		}

		public _isHorizontal() {
			return this.orientation === "horizontal";
		}

		public _isForward() {
			return this.direction === "forward";
		}

		public override _focusImmediately(forward: boolean = true): void {
			if (this.disposed === false && this.focusable === true) {
				let node = null;
				if (forward) {
					node = this._getRenderer().getNamedNode("handle-0");
				} else {
					let handles = this._manager.getHandles();
					node = this._getRenderer().getNamedNode("handle-" + (handles.length - 1));
				}
				if (node) {
					node.focus();
				}
			}
		}


		/**
		 * 
		 * http://demos.telerik.com/kendo-ui/slider/keyboard-navigation 추가해야될 키 참고
		 * 키보드로 핸들을 이동하는 이벤트
		 * @param e 
		 */
		private _eventKey(e: events.CKeyboardEvent, handleIndex: number) {
			let allowKeys = [events.KeyCode.LEFT, events.KeyCode.DOWN, events.KeyCode.RIGHT, events.KeyCode.UP];
			if (allowKeys.indexOf(e.keyCode) == -1 || e._getMod1Key() || e._getMod3Key()) {
				return;
			}
			let locations = [];
			let handles = this._manager.getHandles();
			for (let handle of handles) {
				locations.push(handle._getLocation());
			}

			let value = handles[handleIndex].value;
			let upward = true;

			let subtraction: number = Math.max(Math.min((Math.ceil(value / this.step) - 1) * this.step, this.max), this.min);
			let addition: number = Math.max(Math.min((Math.ceil(value / this.step) + 1) * this.step, this.max), this.min);
			let isForward = this._isForward();
			switch (e.keyCode) {
				case events.KeyCode.LEFT:
				case events.KeyCode.DOWN:
					if (this.range) {
						if (isForward) {
							value = subtraction;
							upward = false;
						} else {
							if (handleIndex == 1) {
								value = addition;
							} else if (value < handles[1].value) {
								value = addition;
							}
						}
					} else {
						value = isForward ? subtraction : addition;
						upward = false;
					}
					e.preventDefault();//부모의 스크롤 방지
					break;
				case events.KeyCode.RIGHT:
				case events.KeyCode.UP:
					if (this.range) {
						if (isForward) {
							value = addition;
						} else {
							if (handleIndex == 0) {
								value = subtraction;
							} else {
								if (value > handles[0].value) {
									value = subtraction;
								}
							}
						}
					} else {
						value = isForward ? addition : subtraction;
					}
					e.preventDefault();//부모의 스크롤 방지
					break;
			}

			let to = this._toPercentage([this.min, this.max], value);

			this._manager.moveHandle(locations, handleIndex, to, upward, !upward);
		}

		private _onKeydown(e: events.CKeyboardEvent): void {
			if (e.defaultPrevented) {
				return;
			}
			let target = <HTMLElement>e.target;
			switch (e.keyCode) {
				case events.KeyCode.TAB: {
					let forward = !e._getMod2Key();
					let renderer = this._getRenderer();
					let handleIndex = parseInt(target.getAttribute("data-handle"));
					if (isNaN(handleIndex)) {
						handleIndex = 0;
					}
					if (forward) {
						// 종료 핸들
						let nextHandleIndex = handleIndex + 1;
						let nextHandle = <HTMLElement>renderer.getNamedNode("handle-" + nextHandleIndex);
						if (nextHandle) {
							nextHandle.focus();
							e.preventDefault();
						}
					}
					else {
						let prevHandleIndex = handleIndex - 1;
						if (prevHandleIndex === 0) {
							this._focusImmediately();
							e.preventDefault();
						} else if (prevHandleIndex > 0) {
							let nextHandle = <HTMLElement>renderer.getNamedNode("handle-" + prevHandleIndex);
							if (nextHandle) {
								nextHandle.focus();
								e.preventDefault();
							}
						}
					}
					break;
				}
				case events.KeyCode.DOWN:
				case events.KeyCode.UP:
				case events.KeyCode.LEFT:
				case events.KeyCode.RIGHT: {
					if (this.readOnly) {
						break;
					}
					let renderer = this._getRenderer();
					let handleIndex = parseInt(target.getAttribute("data-handle"));
					if (isNaN(handleIndex)) {
						handleIndex = 0;
						let startHandle = <HTMLElement>renderer.getNamedNode("handle-" + handleIndex);
						startHandle.focus();
					}
					this._eventKey(e, handleIndex);

					break;
				}
			}
		}

		private _onMouseUp(e: MouseEvent): void {
			_setAllowGlobalSelection(true);
		}

		private _onMouseDown(e: events.CMouseEvent): void {
			let target = <HTMLElement>e.target;
			if (e.defaultPrevented) {
				return;
			}
			if ((target.classList.contains("cl-slider-bar") || target.classList.contains("cl-slider-range"))) {
				this._eventTap(e);
			}
			else if (target.classList.contains("cl-slider-handle")) {
				this._eventStart(e);
			} else if (target.classList.contains("cl-slider-label") || target.parentElement.classList.contains("cl-slider-label")) {
				this._onLabelMouseDown(e);
			}

			_setAllowGlobalSelection(false);
		}

		private _onLabelMouseDown(e: events.CMouseEvent): void {
			let target = <HTMLElement>e.target;
			if (!target.classList.contains("cl-slider-label")) {
				target = target.parentElement;
			}
			let index = parseInt(target.getAttribute("data-handle"));
			if (!this.focused) {
				this.focus(index == 0);
			} else {
				this._focusImmediately(index == 0);
			}
			this._eventStartByLabel(e);
		}

		/**
		 * 슬라이더바를 클릭하여 핸들을 이동하는 이벤트
		 * @param e 
		 */
		private _eventTap(e: events.CMouseEvent) {
			let target = <HTMLElement>e.target;
			if ((target.classList.contains("cl-slider-bar") || target.classList.contains("cl-slider-range")) == false) {
				return;
			}
			let locations = [];
			let handles = this._manager.getHandles();
			for (let handle of handles) {
				locations.push(handle._getLocation());
			}
			let position: number;
			let isHorizontal = this._isHorizontal();
			if (e.type.indexOf("touch") > -1) {
				position = isHorizontal ? _getUnscaledMouse(e["touches"][0].pageX as number) : _getUnscaledMouse(e["touches"][0].pageY as number);
			} else {
				// 맥의 사파리에서 확대시 스크롤이 생겨 위치를 잘못 가져오는 문제로 pageX로 수정. 2019-07-30
				position = isHorizontal ? e._getUnscaledPageX() : e._getUnscaledPageY();
			}
			let proposal = this._calcPointToPercentage(position);

			let handleNumber = this._getClosestHandle(proposal);

			e.preventDefault();
			this.focus(handleNumber == 0);

			if (handleNumber == -1) {
				return;
			}
			let isForward = handles[handleNumber]._getLocation() < proposal;
			let isBackWard = handles[handleNumber]._getLocation() > proposal;
			this._manager.moveHandle(locations, handleNumber, proposal, isForward, isBackWard);
			if (this.disposed) {
				return;
			}
			if (this.labelDisplay != "hide") {
				this.style["label"]._addStateClass("cl-slider-tap");
			}
			//애니메이션 스타일 추가
			this.style["handle"]._addStateClass("cl-slider-tap");
			// 핸들과 레인지에 적용하는 위치가 다름.
			let rangeNode = this._getRenderer().getNamedNode("range");
			rangeNode.classList.add("cl-slider-tap");

			window.setTimeout(() => {
				this.style["handle"]._removeStateClass("cl-slider-tap");
				this.style["label"]._removeStateClass("cl-slider-tap");
				if (rangeNode) {
					rangeNode.classList.remove("cl-slider-tap");
				}
			}, 300);

			if (e.type.indexOf("touch") == -1) {
				this._eventStart(e);
			}
			this.redraw();
		}

		/**
		 * 위치의 퍼센트 값이 가까운 위치의 핸들을 찾는다. 없는 경우 -1을 반환한다.
		 * @param proposal 
		 */
		private _getClosestHandle(proposal: number) {
			let closest = 100;
			let handleNumber = -1;
			let handles = this._manager.getHandles();


			// range이고 첫번째 핸들과 두번째 핸들의 위치가 같은 경우
			if (this.range && handles[0]._getLocation() == handles[1]._getLocation()) {
				if (proposal > handles[1]._getLocation()) {
					handleNumber = 1;
				} else {
					handleNumber = 0;
				}
			} else {
				handles.forEach(function (handle, index) {

					// 조정 불가 설정인 경우 무시한다.
					if (handle.enabled == false) {
						return handleNumber;
					}

					let pos = Math.abs(handle._getLocation() - proposal);

					if (pos < closest) {
						handleNumber = index;
						closest = pos;
					}
				});
			}

			return handleNumber;
		}

		/**
		 * 슬라이더 핸들 드래그 이벤트 시작.
		 * @param e 
		 */
		private _eventStart(e: events.CMouseEvent) {
			let isHorizontal = this._isHorizontal();
			if (e.type.indexOf("touch") > -1) {
				this._dragData.position = isHorizontal ? _getUnscaledMouse(e["touches"][0].pageX as number) : _getUnscaledMouse(e["touches"][0].pageY as number);
				e.stopPropagation();
			} else {
				this._dragData.position = isHorizontal ? e._getUnscaledPageX() : e._getUnscaledPageY();
			}
			if (this._isMoving) {
				this._dragEnd();
			}
			this._isMoving = true;
			let handles = this._manager.getHandles();
			let proposal = this._calcPointToPercentage(this._dragData.position);
			this._dragData.handleIndex = this._getClosestHandle(proposal);
			for (let handle of handles) {
				this._dragData.locations.push(handle._getLocation());
			}
			this._dragStart();

		}

		/**
		 * 슬라이더 레이블 드래그 이벤트 시작.
		 * @param e 
		 */
		private _eventStartByLabel(e: events.CMouseEvent) {
			let target = <HTMLElement>e.target;
			if (!target.classList.contains("cl-slider-label")) {
				target = target.parentElement;
			}
			this._dragData.handleIndex = parseInt(target.getAttribute("data-handle"));
			let isHorizontal = this._isHorizontal();
			if (e.type.indexOf("touch") > -1) {
				this._dragData.position = isHorizontal ? _getUnscaledMouse(e["touches"][0].pageX as number) : _getUnscaledMouse(e["touches"][0].pageY as number);
			} else {
				this._dragData.position = isHorizontal ? e._getUnscaledPageX() : e._getUnscaledPageY();
			}
			if (this._isMoving) {
				this._dragEnd();
			}
			this._isMoving = true;
			let handles = this._manager.getHandles();
			for (let handle of handles) {
				this._dragData.locations.push(handle._getLocation());
			}
			this._dragStart();

		}

		/**
		 * 슬라이더의 핸들을 드래그 중 이벤트
		 * @param e 
		 */
		private _eventMove(e: events.CMouseEvent) {
			if (this._isMoving == false) {
				return;
			}
			let mouseButton = e.buttons != null ? e.buttons : e.which;
			let rootEle = this._getRenderer().getRootNode();
			if ((e.type == "mousemove" && mouseButton == 0) || (e.type == "touchmove" && e["touches"].length > 1) || !rootEle) {
				this._eventEnd(e);
				return;
			}
			let isHorizontal: boolean = this._isHorizontal();
			let isForward: boolean = this._isForward();
			let currentPosition: number;
			if (e.type.indexOf("touch") > -1) {
				currentPosition = isHorizontal ? _getUnscaledMouse(e["touches"][0].pageX as number) : _getUnscaledMouse(e["touches"][0].pageY as number);
				e.preventDefault();
				e.stopPropagation();
			} else {
				currentPosition = isHorizontal ? e._getUnscaledPageX() : e._getUnscaledPageY();
			}
			let movement = (isHorizontal ? -1 : 1) * (isForward ? -1 : 1) * (currentPosition - this._dragData.position);
			let proposal = (movement * 100) / this._baseSize();
			//이동 할 위치
			let to = this._dragData.locations[this._dragData.handleIndex] + proposal;
			this._manager.moveHandle(this._dragData.locations, this._dragData.handleIndex, to, movement > 0, movement < 0);
			if (this.labelDisplay == "auto") {
				this._displayLabelIndex = this._dragData.handleIndex;
			}
		}

		/**
		 * 슬라이더 핸들 드래그 이벤트 종료
		 * @param e 
		 */
		private _eventEnd(e: events.CMouseEvent) {
			this._dragEnd();
			e.preventDefault();

			if (this._isMoving == false) {
				return;
			}

			this._isMoving = false;
			this._dragData = { handleIndex: 0, position: 0, locations: [] };
			if (this.labelDisplay == "auto") {
				this._displayLabelIndex = -1;
				this.redraw();
			}
		}

		private _dragEnd() {
			cpr.events.BodyEventTarget.INSTANCE.removeEventListener("mousemove", this._mouseEventDispatcher);
			cpr.events.BodyEventTarget.INSTANCE.removeEventListener("mouseup", this._mouseEventDispatcher);
			document.body.removeEventListener("touchmove", this._mouseEventDispatcher);
			cpr.events.BodyEventTarget.INSTANCE.removeEventListener("touchend", this._mouseEventDispatcher);
		}

		private _dragStart() {
			cpr.events.BodyEventTarget.INSTANCE.addEventListener("mousemove", this._mouseEventDispatcher);
			cpr.events.BodyEventTarget.INSTANCE.addEventListener("mouseup", this._mouseEventDispatcher);
			if (core.Platform.INSTANCE.browserInfo.supportsPassiveEvent) {
				document.body.addEventListener("touchmove", this._mouseEventDispatcher, { passive: false });
			} else {
				document.body.addEventListener("touchmove", this._mouseEventDispatcher);
			}
			cpr.events.BodyEventTarget.INSTANCE.addEventListener("touchend", this._mouseEventDispatcher);
		}

		/**
		 * 슬라이더바의 크기에 따른 마우스 포인터의 위치를 퍼센트로 계산하여 반환한다. 바에 마우스 포인터를 클릭하는 경우 사용.
		 * @param calcPoint 
		 */
		private _calcPointToPercentage(calcPoint: number): number {
			let sliderbarElement = this._getRenderer().getNamedNode("sliderbar");
			let offset = this.orientation == "horizontal" ? _getOffsetRectFromViewport(sliderbarElement).left : _getOffsetRectFromViewport(sliderbarElement).top;
			let location: number = calcPoint - offset;
			let proposal: number = (location * 100) / this._baseSize();
			if (this._isHorizontal()) {
				return this._isForward() ? proposal : 100 - proposal;
			} else {
				return this._isForward() ? 100 - proposal : proposal;
			}
		}
		/**
		 * 슬라이더바의 크기를 반환한다.
		 */
		private _baseSize() {
			let element = this._getRenderer().getNamedNode("sliderbar");
			let rect = geometry.Rectangle.offsetBoundsOf(element);
			return this._isHorizontal() ? rect.width : rect.height;
		}

		/**
		 * 범위에서 값을 퍼센트로 계산한다.
		 * @param range [0]min [1]max
		 * @param value 
		 */
		private _toPercentage(range: number[], value: number): number {
			return this._fromPercentage(range, range[0] < 0 ? value + Math.abs(range[0]) : value - range[0]);
		}
		/**
		 * 범위에서 값이 몇 퍼센트인지 계산한다.
		 * @param range [0]min [1]max
		 * @param value 
		 */
		private _fromPercentage(range: number[], value: number): number {
			return (value * 100) / (range[1] - range[0]);
		}

		private _useBodyScroll() {
			return this.getAppInstance().getRootAppInstance().getContainer()._useBodyScroll();
		}

		public _exportValue(): string | number {
			let ctrlText = (this.text === undefined) ? this.value : this.text;

			// 기본 >> text
			return (ctrlText != null) ? "" + ctrlText : "";
		}

		/**
		 * 컨트롤의 포함하는 객체들을 제거합니다.
		 */
		public dispose(): void {
			this._dragEnd();
			if (this._manager != null) {
				this._manager.dispose();
				this._manager = null;
			}
			super.dispose();

		}

		/**
		 * SliderHandleManager 
		 */
		public _validateHandle(): void {
			this._manager.validateHandle();
		}

		public _getHandles() {
			return this._manager.getHandles();
		}

		public _getHandleValue(index: number) {
			return this._manager.getValue(index);
		}

	}
}
