/// <reference path="../../../expression/Expression.ts" />

namespace cpr.controls.gridpart.config {
	let _DEFAULT_SUPPRESSIBLE_EXPR: expression.Expression = new expression.Expression("true");

	type column_type_string = "normal" | "checkbox" | "rowindex" | "radio";
	export class GridDetailCellConfigurator extends GridCellConfigurator {
		private _columnType: column_type_string = "normal";
		private _columnName: column_name_string;
		private _mergeToIndexExpr: expression.Expression;
		private _mergedColumnName: column_name_string;
		private _keepMerged: boolean;
		private _suppressible: boolean;
		private _suppressibleExpr: expression.Expression;
		private _suppressRef: number;

		// 조건부 컨트롤
		private _controlConditionExp: expression_string;
		private _controls: { [conditionalId: string]: GridUIControl };
		private _constraints: { [conditionalId: string]: ControlConstraint };



		constructor(grid: Grid) {
			super(grid);

			this._bindables.add("enabled", true).withSetterValidatorWithType(false, "boolean");
			this._bindables.add("visible", true).withSetterValidatorWithType(false, "boolean");
		}

		/**
		 * 기본 컬럼일 경우 column의 종류를 설정합니다.
		 * @param columnType 컬럼의 종류.
		 */
		set columnType(columnType: column_type_string) {
			this._columnType = columnType;
		}

		/**
		 * 기본 컬럼일 경우 column의 종류를 반환합니다.
		 * @return 컬럼의 종류.
		 */
		get columnType(): column_type_string {
			return this._columnType;
		}

		/**
		 * 셀에 연결할 데이터셋 컬럼명을 설정합니다.
		 * @param columnName 데이터셋 컬럼명.
		 */
		set columnName(columnName: column_name_string) {
			this._columnName = columnName;
		}

		/**
		 * 셀에 연결할 데이터셋 컬럼명을 반환합니다.
		 * @return 데이터셋 컬럼명.
		 */
		get columnName(): column_name_string {
			return this._columnName;
		}

		/**
		 * 병합할 셀의 인덱스를 리턴하는 표현식을 설정합니다.
		 * 설정되지 않거나 자기자신의 인덱스를 리턴할 경우 병합하지 않습니다.
		 * 셀병합은 자동높이를 지원하지 않습니다.
		 * @param mergeToIndexExpr 병합할 셀의 인덱스를 리턴하는 표현식
		 */
		set mergeToIndexExpr(mergeToIndexExpr: expression_string) {
			if (mergeToIndexExpr) {
				if (this._mergeToIndexExpr == null || this._mergeToIndexExpr.src != mergeToIndexExpr) {
					this._mergeToIndexExpr = new expression.Expression(mergeToIndexExpr);
				}
			} else {
				this._mergeToIndexExpr = null;
			}
		}

		/**
		 * 병합할 셀의 인덱스를 리턴하는 표현식을 반환합니다.
		 * 설정되지 않거나 자기자신의 인덱스를 리턴할 경우 병합하지 않습니다.
		 * 셀병합은 자동높이를 지원하지 않습니다.
		 * @return 병합할 셀의 인덱스를 리턴하는 표현식
		 */
		get mergeToIndexExpr(): expression_string {
			return this._mergeToIndexExpr ? this._mergeToIndexExpr.src : null;
		}
		public _getMergeToIndexExpr(): expression.Expression {
			return this._mergeToIndexExpr;
		}

		/**
		 * 셀이 병합될 경우 표현할 DataSet의 컬럼명을 설정합니다.
		 * 셀이 병합되지 않을 경우 columnName 속성에 설정된 컬럼의 값이 표현됩니다.
		 * 셀병합은 자동높이를 지원하지 않습니다.
		 * @param mergedColumnName 병합된 셀에 연결할 DataSet의 컬럼명
		 */
		set mergedColumnName(mergedColumnName: column_name_string) {
			this._mergedColumnName = mergedColumnName;
		}

		/**
		 * 셀이 병합될 경우 표현할 DataSet의 컬럼명을 반환합니다.
		 * 셀이 병합되지 않을 경우 columnName 속성에 설정된 컬럼의 값이 표현됩니다.
		 * 셀병합은 자동높이를 지원하지 않습니다.
		 * @return 병합된 셀에 연결할 DataSet의 컬럼명
		 */
		get mergedColumnName(): column_name_string {
			return this._mergedColumnName;
		}

		/**
		 * 병합된 셀에 편집모드 진입시 적용된 병합 상태를 유지할지 여부를 설정합니다.
		 * @param keepMerged 병합 상태를 유지할지 여부.
		 */
		set keepMerged(keepMerged: boolean) {
			this._keepMerged = keepMerged;
		}

		/**
		 * 병합된 셀에 편집모드 진입시 적용된 병합 상태를 유지할지 여부를 반환합니다.
		 * @return 병합 상태를 유지할지 여부.
		 */
		get keepMerged(): boolean {
			return this._keepMerged;
		}

		public _isMergeableCell(): boolean {
			return (this.mergeToIndexExpr != null && this._isConditionalControl() == false);
		}

		/**
		 * 바로 직전 로우의 값과 일치하는 셀은 텍스트를 숨기도록 할지 여부를 설정합니다.
		 * (셀 병합 효과 제공)
		 * @param suppressible 텍스트를 숨기도록 할지 여부.
		 */
		set suppressible(suppressible: boolean) {
			this._suppressible = suppressible;
		}

		/**
		 * 바로 직전 로우의 값과 일치하는 셀은 텍스트를 숨기도록 할지 여부를 설정값을 반환합니다.
		 * (셀 병합 효과 제공)
		 * @return 텍스트를 숨기도록 할지 여부.
		 */
		get suppressible(): boolean {
			return this._suppressible;
		}

		/**
		 * suppressible이 true일 셀에서 실제 suppress를 수행할지 여부를 리턴하는 expression식.
		 * 표현식 실행결과 반환되는 값이 true일 때는 suppress를 실행하고 false이면 suppress에서 제외합니다.
		 * suppressible이 true일 때만 유효한 속성으로 설정되지 않았을 때는 기본적으로 suppress를 실행합니다.
		 * @param suppressibleExpr suppress 수행여부를 리턴하는 표현식
		 */
		set suppressibleExpr(suppressibleExpr: expression_string) {
			if (suppressibleExpr) {
				if (this._suppressibleExpr == null || this._suppressibleExpr.src != suppressibleExpr) {
					this._suppressibleExpr = new expression.Expression(suppressibleExpr);
				}
			} else {
				this._suppressibleExpr = null;
			}
		}

		/**
		 * suppressible이 true일 셀에서 실제 suppress를 수행할지 여부를 리턴하는 expression식을 리턴합니다.
		 * 표현식 실행결과 반환되는 값이 true일 때는 suppress를 실행하고 false이면 suppress에서 제외합니다.
		 * suppressible이 true일 때만 유효한 속성으로 설정되지 않았을 때는 기본적으로 suppress를 실행합니다.
		 * @return suppress 수행여부를 리턴하는 표현식
		 */
		get suppressibleExpr(): expression_string {
			return this._suppressibleExpr ? this._suppressibleExpr.src : null;
		}
		public _getSuppressibleExpr(): expression.Expression {
			return this._suppressibleExpr == null ? _DEFAULT_SUPPRESSIBLE_EXPR : this._suppressibleExpr;
		}

		/**
		 * suppressible (셀 텍스트 숨김) 효과에 영향을 줄 다른 컬럼 인덱스를 설정합니다.<br>
		 * (관련 속성 : [suppressible] suppressible=true일 때 유효한 속성입니다.)
		 * 
		 * @example
		 * A 컬럼: suppressible = true,
		 * B 컬럼: suppressible = true, suppressRef = 0 일 때,
		 * B 컬럼의 셀병합 효과에 A컬럼의 셀병합 라인도 같이 적용됩니다.
		 */
		set suppressRef(suppressRef: number) {
			this._suppressRef = suppressRef;
		}

		/**
		 * suppressible (셀 텍스트 숨김) 효과에 영향을 줄 다른 컬럼 인덱스 설정값을 반환합니다.<br>
		 * (관련 속성 : [suppressible] suppressible=true일 때 유효한 속성입니다.)
		 * 
		 * @example
		 * A 컬럼: suppressible = true,
		 * B 컬럼: suppressible = true, suppressRef = 0 일 때,
		 * B 컬럼의 셀병합 효과에 A컬럼의 셀병합 라인도 같이 적용됩니다.
		 */
		get suppressRef(): number {
			return this._suppressRef;
		}

		public _isSuppressibleCell(): boolean {
			return (this.suppressible == true && this.columnType == "normal" && this._isConditionalControl() == false);
		}

		/* custom cell start */

		/**
		 * 조건부 컨트롤 배치에 대한 표현식을 설정합니다.
		 * @param expr 조건부 컨트롤 배치에 대한 표현식
		 * @experimental
		 */
		set controlConditionExp(expr: expression_string) {
			this._controlConditionExp = expr;
		}

		/**
		 * 조건부 컨트롤 배치에 대한 표현식을 반환합니다.
		 * @returns 조건부 컨트롤 배치에 대한 표현식
		 * @experimental
		 */
		get controlConditionExp(): expression_string {
			return this._controlConditionExp;
		}

		/**
		 * 조건부 컨트롤 배치시 셀에 배치될 컨트롤들을 설정합니다.
		 * @param controls 조건부 컨트롤 배치시 셀에 배치될 컨트롤들
		 * @experimental
		 */
		set factory(controls: { [conditionalId: string]: GridUIControl }) {
			if (this._controls == null) {
				this._controls = {};
			}
			let conditionalIds = Object.keys(controls);
			conditionalIds.forEach((conditionalId: string) => {
				this._addConditionalControl(conditionalId, controls[conditionalId]);
			})
		}

		/**
		 * 조건부 컨트롤 배치시 셀에 배치될 컨트롤들을 반환합니다.
		 * @param controls 조건부 컨트롤 배치시 셀에 배치될 컨트롤들
		 * @experimental
		 */
		get factory(): { [conditionalId: string]: GridUIControl } {
			return this._controls;
		}

		/**
		 * 조건부 컨트롤 배치시 셀에 배치된 컨트롤들의 constraint를 설정합니다.
		 * @param constraints 컨트롤들의 constraint
		 * @experimental
		 */
		set controlConstraints(constraints: { [conditionalId: string]: ControlConstraint }) {
			this._constraints = constraints;
		}

		/**
		 * 조건부 컨트롤 배치시 셀에 배치된 컨트롤들의 constraint를 반환합니다.
		 * @returns 컨트롤들의 constraint
		 * @experimental
		 */
		get controlConstraints(): { [conditionalId: string]: ControlConstraint } {
			return this._constraints;
		}

		/**
		 * 컨트롤의 활성화 여부를 설정합니다.
		 * @param enable 컨트롤의 활성화 여부.
		 */
		set enabled(enabled: boolean) {
			this._bindables.set("enabled", enabled);
		}

		/**
		 * 컨트롤의 활성화 여부를 반환합니다.
		 * @return 컨트롤의 활성화 여부.
		 */
		get enabled(): boolean {
			return this._bindables.get("enabled");
		}

		/**
		 * css visibility를 제어하기 위한 style 속성을 설정합니다.
		 * @param visible 화면에 보이는 여부.
		 */
		set visible(visible: boolean) {
			this._bindables.set("visible", visible);
		}

		/**
		 * css visibility를 제어하기 위한 style 속성을 반환합니다.
		 * @return 화면에 보이는 여부.
		 */
		get visible(): boolean {
			return this._bindables.get("visible");
		}

		public _getConditionalResult(): any {
			if (this._controlConditionExp == null) {
				return null;
			}
			let result: any;
			utils.tryCatch({
				do: () => {
					let exp = new cpr.expression.Expression(this._controlConditionExp);
					let bindContext: bind.GridEmbeddedContext = this.grid.getBindContext() as bind.GridEmbeddedContext;
					result = exp.evaluate(bindContext);
				},
				catch: (e: Error) => {
					console.error(e);
					result = cpr.expression.ERROR_VALUE
				},
				_report: true,
				_context: exceptions.ErrorContext.EXPRESSION
			});
			return result;
		}

		private _addConditionalControl(id: string, control: GridUIControl) {
			if (this._getConditionalControl(id) != null) {
				console.error("이미 등록된 컨트롤 타입입니다.")
			}
			this._controls[id] = control;
		}

		public _getConditionalControl(id: string): GridUIControl {
			return this._controls?.[id];
		}

		public _getConditionalIds(): string[] {
			return Object.keys(this._controls);
		}

		public _getConditionalControls(): GridUIControl[] {
			let conditionalIds: string[] = this._getConditionalIds();
			let controls: GridUIControl[] = conditionalIds.map((id: string) => {
				return this._controls[id];
			})
			return controls;
		}

		public _addConditionalControlConstraint(id: string, constraint: ControlConstraint) {
			if (this._constraints == null) {
				this._constraints = {};
			}
			this._constraints[id] = constraint;
		}

		public _getConditionalControlConstraint(id: string): ControlConstraint {
			return this._constraints?.[id];
		}

		public _isConditionalControl(): boolean { // TODO: 기준 필요
			return !utils.Util.isNullOrEmpty(this.controlConditionExp) && (this._controls != null) && this.columnType == "normal";
		}

		/* custom cell end */
	}
}