namespace cpr.controls.internal {
	let log = utils.Logger.forTopic("ndnd")._createBindedLoggerFunction({
		updator: it => log = it
	});

	/**
	 * 드래그 문맥을 추상화 하는 객체입니다.
	 * @noinstance
	 */
	export class NodeDragContext {
		private _source: NodeDragSource;
		private _knownPointerLocation: PointerLocation;
		private _cachedDelta: geometry.Dimension;
		private _allowDefault: boolean = false;

		constructor(source: NodeDragSource) {
			this._source = source;
		}

		/**
		 * 드래그가 시작된 시점의 포인터 위치를 얻습니다.
		 */
		public get dragStartLocation(): geometry.Point {
			return this._source._getDragStartLocation().clientLocation;
		}

		/**
		 * 드래그 소스를 얻습니다.
		 */
		public get source(): NodeDragSource {
			return this._source;
		}

		/**
		 * 활성화된 드랍 타겟 객체를 얻습니다. 마우스 포인터 아래에 적합한 드랍타겟이 존재하지 않는 경우, <code>null</code>이 반환 됩니다.
		 */
		public get target(): NodeDropTarget {
			return this._source._getActiveDropTarget();
		}

		/**
		 * 총 드래그의 이동량을 얻습니다. 마우스 버튼이 다운된 시점을 기준으로 합니다.
		 */
		public get dragDelta(): geometry.Dimension {
			let pointerLocation = this._source._getPointerLocation();
			if (this._cachedDelta && pointerLocation.equals(this._knownPointerLocation)) {
				return this._cachedDelta;
			}
			this._knownPointerLocation = pointerLocation;
			_workUnscale((zoom) => {
				let scale = 1 / zoom;
				this._cachedDelta = pointerLocation.pageLocation.getScaled(scale).getDifference(this._source._getDragStartLocation().pageLocation.getScaled(scale));
			}, () => {
				this._cachedDelta = pointerLocation.pageLocation.getDifference(this._source._getDragStartLocation().pageLocation);
			});
			return this._cachedDelta;
		}

		/**
		 * 드래그 앤 드랍으로 전달 될 데이터를 얻습니다.
		 */
		public get data(): any {
			return this._source._getData();
		}

		/**
		 * 드래그 앤 드랍으로 전달 될 데이터를 지정 합니다..
		 * @param data 전달할 데이터.
		 */
		public set data(newData: any) {
			this.source._setData(newData);
		}

		/**
		 * 현재 표시중인 커서를 얻습니다.
		 */
		public get cursor(): string {
			return this._source._resolveCursor();
		}

		/**
		 * 표시할 커서를 지정합니다.
		 * DropContext에서 다른 커서를 지정할 경우, 해당 커서가 더 우선 합니다.
		 */
		public set cursor(newCursor: string) {
			this._source._setExplictCursor(newCursor);
		}

		/**
		 * Shift 키가 눌려 있는지 여부를 얻습니다.
		 */
		public get shiftKey(): boolean {
			return this._source._getKeyStates().shiftKey;
		}

		/**
		 * Alt 키가 눌려 있는지 여부를 얻습니다.
		 */
		public get altKey(): boolean {
			return this._source._getKeyStates().altKey;
		}

		/**
		 * Control 키가 눌려 있는지 여부를 얻습니다.
		 */
		public get ctrlKey(): boolean {
			return this._source._getKeyStates().ctrlKey;
		}

		/**
		 * 메타 키가 눌려 있는지 여부를 얻습니다.
		 */
		public get metaKey(): boolean {
			return this._source._getKeyStates().metaKey;
		}

		/**
		 * 드래그 소스의 데이터 타입을 지정합니다.
		 */
		public set dataType(newKind: string) {
			this._source.dataType = newKind;
		}

		/**
		 * 드래그 소스의 데이터 타입을 얻습니다.
		 */
		public get dataType(): string {
			return this._source.dataType;
		}

		/**
		 * 
		 * 드래그 동작을 취소합니다.
		 */
		public cancel(): void {
			this._source._cancel();
		}

		/**
		 * 터치 혹은 마우스에 대한 브라우저 기본 동작 허용 여부를 지정합니다.
		 * @deprecated 이 동작은 더 이상 지원되지 않습니다. 브라우저 기본 동작을 위임하려면 {@link cancel}을 사용하시기 바랍니다.
		 */
		public set allowDefault(allow: boolean) {
			this._allowDefault = allow;
		}

		/**
		 * 터치 혹은 마우스에 대한 브라우저 기본 동작 허용 여부를 얻습니다.
		 * @deprecated 이 동작은 더 이상 지원되지 않습니다. 브라우저 기본 동작을 위임하려면 {@link cancel}을 사용하시기 바랍니다.
		 */
		public get allowDefault(): boolean {
			return this._allowDefault;
		}
	}
}