namespace cpr {
	/**
	 * 입력으로 하여 계산 결과를 얻고 한계 수량 만큼 캐시를 지원하는 구조체를 생성 합니다.
	 * @param limit  캐시의 보존 수.
	 * @param resultFactory 입력이 캐시에 존재하지 않는 경우, 입력으로부터 계산 결과를 반환하는 함수.
	 * @returns 캐시 구조체.
	 */
	export function _createLimitedCache<Input, Result>(limit: number, resultFactory: (input: Input) => Result) {
		return new CacheImpl(limit, resultFactory);
	}

	export function _createUnlimitedCache<Input, Result>(resultFactory: (input: Input) => Result) {
		return new CacheImpl(-1, resultFactory);
	}

	/**
	 * 크기 제한을 갖는 캐시 구조체.
	 * 크기 제한에 도달한 경우 사용한지 오래된 항목 부터 제거 됩니다.
	 */
	export type LimitedCache<Input, Result> = {
		/**
		 * 캐시로 부터 값을 얻거나 새로 계산하여 얻습니다.
		 * 새로 계산된 경우 캐시에 추가됩니다.
		 * 캐시 히트를 통해 값을 얻은 경우 해당 캐시가 더 오래 살아 남을 수 있도록 캐시의 삭제큐의 가장 마지막 으로 이동합니다.
		 * @param input 
		 */
		get(input: Input): Result;
	}

	type CacheEntry<K, P> = {
		key: K,
		value: P,
		prev?: CacheEntry<K, P>,
		next?: CacheEntry<K, P>
	}

	function _unlink(entry: CacheEntry<any, any>) {
		if (entry.prev?.next === entry) {
			entry.prev.next = null;
		}
		if (entry.next?.prev == entry) {
			entry.next.prev = null;
		}
		entry.next = entry.prev = null;
	}

	class CacheImpl<Input, Result> implements LimitedCache<Input, Result> {
		_map: CMap<Input, CacheEntry<Input, Result>>;
		_first: CacheEntry<Input, Result>;
		_last: CacheEntry<Input, Result>;
		_facotry: (input: Input) => Result;
		_capacity: number = -1;
		_size: number = 0;

		constructor(limit: number, resultFactory: (input: Input) => Result) {
			this._capacity = limit;
			this._map = _createMap();
			this._facotry = resultFactory;
		}

		get size(): number {
			return this._size;
		}

		isEmpty(): boolean {
			return this._size === 0;
		}

		get(input: Input): Result {
			let entry = this._map.get(input);
			if (entry) {
				this._renew(entry);
				return entry.value;
			}

			return this._add(input, this._facotry(input));
		}

		private _add(input: Input, result: Result): Result {
			switch (this._size) {
				case 0:
					this._first = this._last = {
						key: input,
						value: result,
						prev: null,
						next: null
					};
					break;

				case 1:
					this._first.next = this._last = {
						key: input,
						value: result,
						prev: this._first,
						next: null
					}
					break;

				default: {
					this._last.next = {
						key: input,
						value: result,
						prev: this._last,
						next: null
					};
					this._last = this._last.next;
					break;
				}
			}

			this._map.set(input, this._last);
			this._size++;
			while (this._capacity > 0 && this._size > this._capacity) {
				this._deleteOldestCache();
			}

			return result;
		}

		private _renew(entry: CacheEntry<Input, Result>) {
			if (!entry || entry === this._last) {
				return;
			}

			if (entry.prev) {
				entry.prev.next = entry.next;
			}
			if (entry.next) {
				entry.next.prev = entry.prev;
			}
			if (entry === this._first) {
				this._first = entry.next;
			}

			this._last.next = entry;
			entry.prev = this._last;
			entry.next = null;

			this._last = entry;
		}

		private _deleteOldestCache(): void {
			if (this._size > 0) {
				let oldFirst = this._first;

				this._map.delete(this._first.key);
				this._size--;

				if (this._size === 0) {
					this._first = this._last = null;
				} else {
					this._first = this._first.next;
				}

				// 릭 방지를 위해 연결 고리를 끊음.
				_unlink(oldFirst);
			}
		}
	}
}