namespace cpr.controls.navigation {

	/**
	 * @private
	 */
	export class Menu extends menu.AbstractVerticalMenu {

		private _createMenu(): cpr.ufc.ElementShape {
			let items = this.getItems();
			let selectedValues: string[] = this._getSelectedValues();
			let parentItem = items[0].parentItem;

			let itemCount = items.length;

			let range = this._getMenuItemRange(itemCount);
			let rangeSize = range.end - range.start;
			items = items.slice(range.start, range.end);
			let visibleScrollButton: boolean = itemCount != rangeSize;

			let upScrollBtn: ufc.ElementShape = {
				tag: "div",
				classNames: ["cl-arrow-up"],
				style: {
					display: visibleScrollButton ? "block" : "none",
					height: this._getButtonHeight() + "px"
				}
			}
			let isFirst = range.start == 0;
			if (visibleScrollButton && isFirst) {
				upScrollBtn.classNames.push(ufc.Classes.DISABLED);
			}

			let downScrollBtn: ufc.ElementShape = {
				tag: "div",
				classNames: ["cl-arrow-down"],
				style: {
					display: visibleScrollButton ? "block" : "none",
					height: this._getButtonHeight() + "px"
				}
			}

			let isLast = range.end == itemCount;
			if (visibleScrollButton && isLast) {
				downScrollBtn.classNames.push(ufc.Classes.DISABLED);
			}

			let children = this._createItems(items, selectedValues);
			children.splice(0, 0, upScrollBtn);
			children.push(downScrollBtn);

			let shape: cpr.ufc.ElementShape = {
				tag: "div",
				classNames: [ufc.Classes.UNSELECTABLE],
				attr: {
					"data-role": "menu",
					role: "menu",
					"aria-label": cpr.ufc.ShapeUtil._getValidAriaLabelAttr(ufc.StyledString._asString(this._getDataBinder()._computeItemDisplayLabel(parentItem)))
				},
				styler: this._getStylerName("list"),
				aria: this._getStylerName("list"),
				style: {
					position: "absolute",
					overflow: "visible"
				},
				nodename: this._getMenuListNodeName(),
				children: children
			}

			let width = this._getMenuMinWidth();
			if (width) {
				shape.style["min-width"] = width + "px";
			}
			ufc.ShapeUtil.addEventHandler(shape, "touchstart", (e: events.CTouchEvent) => { this._ontouchstart(e) }, true);
			ufc.ShapeUtil.addEventHandler(shape, "wheel", (e: events.CWheelEvent) => { this._onMenuMouseWheel(e) }, true);
			ufc.ShapeUtil.addEventHandler(shape, "click", (e: MouseEvent) => { this._onClick(e) }, true);
			ufc.ShapeUtil.addEventHandler(shape, "mouseover", (e: MouseEvent) => { this._dispatchHoverRelativeEvent(e) }, true);
			ufc.ShapeUtil.addEventHandler(shape, "mouseout", (e: MouseEvent) => { this._dispatchHoverRelativeEvent(e) }, true);

			if (this._isHoverTrigger()) {
				ufc.ShapeUtil.addEventHandler(shape, "mouseleave", (e: MouseEvent) => { this._dispatchHoverRelativeEvent(e) }, true);
				ufc.ShapeUtil.addEventHandler(shape, "mouseenter", (e: MouseEvent) => { this._dispatchHoverRelativeEvent(e) }, true);
			}

			return shape;
		}

		protected _createShape(): cpr.ufc.ElementShape {
			let shape = this._createMenu();
			if (this.getVisible()) {
				shape.children.push(_createTapLazyTask({
					task: () => {
						this._updateBounds();
					}
				}));
			}

			return shape;
		}

		private _createItem(item: MenuItem, selectedValues: string[]) {
			let isItemEnabled = this._getDataBinder().getItemEnable(item);
			let isSelectedItem = selectedValues.indexOf(item.value) > -1;
			let isHoveredItem = this._isHoveredItem(item);
			let displayLabel = this._getDataBinder()._computeItemDisplayLabel(item);
			let hasChild = item._hasChild();

			let icon = this._createIcon(item, true);
			let textShape = this._createText(displayLabel);
			let accesskeyTag = item.accessKey ? this._createAccessKey(item, true) : null;
			let arrow = this._createArrowImage(item, true);

			let shape: cpr.ufc.ElementShape = {
				tag: "div",
				styler: this._getStylerName("item"),
				bindContext: item.toExpressionContext(this._getUIControl()),
				style: {
					display: "table",
					position: "relative",
					width: "100%",
					"table-layout": "auto"
				},
				aria: this._getStylerName("item"),
				classNames: [hasChild ? ufc.Classes.FOLDER : ufc.Classes.LEAF],
				attr: {
					"data-role": "menuitem",
					role: "menuitem",
					"data-itemid": item.value,
					"aria-label": cpr.ufc.ShapeUtil._getValidAriaLabelAttr(ufc.StyledString._asString(displayLabel)),
					id: this._getMenuItemId(item)
				},
				events: {},
				children: [icon, textShape, accesskeyTag, arrow]
			}
			cpr.ufc.ShapeUtil._setTooltipAttr(shape, { owner: this._getUIControl(), title: item.tooltip, id: item.value });

			if (item.accessKey) {
				shape.attr["aria-keyshortcuts"] = item.accessKey;
			}
			if (isSelectedItem) {
				shape.attr["aria-current"] = "page";
				shape.classNames.push(ufc.Classes.SELECTED);
			}
			let subMenu = null;
			ufc.ShapeUtil._setAriaDisabled(shape, isItemEnabled && this._isEnabled() && !this._getUIControl().readOnly);
			if (isItemEnabled && this._isEnabled()) {
				if (isHoveredItem) {
					shape.classNames.push(ufc.Classes.HOVER);
				}

				if (hasChild) {
					shape.attr["aria-haspopup"] = "true";
					shape.attr["aria-expanded"] = "false";

					if (isHoveredItem) {
						shape.attr["aria-expanded"] = "true";

						shape.classNames.push(this._getQClass("visible"));
						subMenu = this._createSubMenu(item, selectedValues);
					}
				}
			} else {
				shape.classNames.push(ufc.Classes.DISABLED);
			}

			if (subMenu) {
				shape.children.push(subMenu);
			}
			return shape;
		}

		private _createItems(items: MenuItem[], selectedValues: string[]): cpr.ufc.ElementShape[] {
			let itemShapes: cpr.ufc.ElementShape[] = [];
			items.forEach((item: MenuItem) => {
				itemShapes.push(this._createItem(item, selectedValues))
			});

			return itemShapes;
		}

		protected _createSubItems(children: MenuItem[], selectedValues: string[]) {
			return this._createItems(children, selectedValues);
		}

		private _getHoveredBarItemNode() {
			let hoveredBarNode = this._getRenderer().getNamedNode("hovered-bar-item");
			return hoveredBarNode;
		}

		protected _updateMenuBounds() {
			let rootNode = this._getRenderer().getNamedNode(this._getQName());
			let rootMenuListNode = this._getMenuListNode();
			if (!rootMenuListNode || !rootNode) {
				return;
			}
			let rootItemNode = this._getHoveredBarItemNode();
			if (!rootItemNode) {
				return;
			}
			let rootRect = _getOffsetRectFromViewport(rootNode);
			let rootItemRect = _getOffsetRectFromViewport(rootItemNode);
			let viewportRect = _getVisualViewportRect();
			let rootSpace = _getComputedSpaceInsets(rootNode, { verticalMargin: 10 });
			// 메뉴의 위치를 내비게이션바의 아이템에 표시될 기본 위치로 좌표 수정.
			let rootMenuListRect = _getOffsetRectFromViewport(rootMenuListNode, false);
			rootMenuListRect.translate(1000, 1000);
			rootMenuListRect.translate(rootItemRect.left, rootRect.top + rootRect.height);

			let rootMenuRect = new geometry.Rectangle(); // 메뉴를 감싸는 래퍼
			rootMenuRect.left = rootItemRect.left < 0 ? rootItemRect.left + Math.abs(rootMenuListRect.left) : rootItemRect.left;
			rootMenuRect.top = rootRect.top + rootRect.height;
			rootMenuRect.width = rootItemRect.width; // 메뉴 리스트를 중앙 정렬이 가능하도록 부모 아이템의 너비 사용

			if (viewportRect.width < rootMenuListRect.width) {// 윈도우 너비보다 메뉴아이템이 클 경우
				rootMenuRect.left = rootMenuRect.left - (rootMenuListRect.left - viewportRect.left);
				rootMenuRect.width = viewportRect.right - rootMenuRect.left;
			} else if ((rootMenuListRect.left + rootMenuListRect.width) > viewportRect.right) { // 메뉴아이템이 오른쪽으로 넘어가 잘려보이는 경우
				rootMenuRect.left = Math.floor(rootMenuRect.left + (viewportRect.right - rootMenuListRect.right)); // 오른쪽으로 조금이라도 넘어가면 스크롤 발생하는 문제가 있기 때문에 소수점을 제거한다.
				rootMenuRect.width = viewportRect.right - rootMenuRect.left;
			}

			let rootMenuClassList = [ufc.Classes.BOTTOM];
			let rootClassList = [ufc.Classes.OPENED_BOTTOM];
			let menuItemNode: HTMLElement = rootMenuListNode.querySelector(this._getMenuItemQuerySelector());
			let menuItemHeight = menuItemNode?.offsetHeight || 0;

			if (rootMenuListRect.height > rootSpace.bottom && Math.floor(rootSpace.top / menuItemHeight) - Math.floor(rootSpace.bottom / menuItemHeight) > 1) {
				// 내비게이션바 중심으로 위쪽이 공간이 많은 경우
				rootMenuRect.top = rootRect.top - rootMenuListRect.height;
				rootMenuClassList = [ufc.Classes.TOP];
				rootClassList = [ufc.Classes.OPENED_TOP];
			} else {
				if (this._useBodyScroll()) {
					if (viewportRect.top > rootMenuRect.top) { // 뷰포트 시작 위치보다 작은 경우
						rootMenuRect.top = viewportRect.top;
					}
				} else {
					if (0 > rootMenuRect.top) {
						rootMenuRect.top = 0;
					}
				}
			}
			let constraint = {
				top: rootMenuRect.top,
				bottom: null,
				left: rootMenuRect.left,
				right: null,
				width: rootMenuRect.width
			}
			if (this.getVisible()) {
				this._getRenderer().updateClass(this._getQName(), [], rootClassList);
			}

			this._getRenderer().updateClass(this.getRootNodeName(), [ufc.Classes.BOTTOM], rootMenuClassList);
			let style = _.mapObject(constraint, (val: number | null, key: string) => {
				if (val == null) {
					return "auto";
				}
				return val + "px";
			})
			this._getRenderer().updateStyle(this.getRootNodeName(), style, true);
			this._updateMenuSize(rootRect, rootSpace, rootMenuClassList.indexOf(ufc.Classes.BOTTOM) > -1);
		}

		protected _getVisibleItemElements(menuListNode: HTMLElement): HTMLElement[] {
			return _toArray(menuListNode.children).filter((node) => { return node.classList.contains("cl-navigationbar-listitem") }) as HTMLElement[];
		}

		protected _updateMenuSize(rootRect: geometry.Rectangle, rootSpace: geometry.Insets, opendedBottom: boolean) {
			let rootMenuListNode = this._getMenuListNode();
			let rootMenuNode = this._getRenderer().getNamedNode(this.getRootNodeName());
			let buttonTotalSize = this._getButtonHeight() * 2;
			let constraint: { top?: number } = {}
			let menuListComputedStyle = getComputedStyle(rootMenuListNode);
			let menuComputedStyle = getComputedStyle(rootMenuNode);
			let menuListBorderSize = _parseFloat(menuListComputedStyle.borderTopWidth) + _parseFloat(menuListComputedStyle.borderBottomWidth);
			// padding
			let menuListPaddingSize = _parseFloat(menuListComputedStyle.paddingTop) + _parseFloat(menuListComputedStyle.paddingBottom);
			//margin
			let menuTopSpaceSize = _parseFloat(menuComputedStyle.marginTop) + _parseFloat(menuComputedStyle.paddingTop);
			let menuListMarginSize = _parseFloat(menuListComputedStyle.marginTop) + _parseFloat(menuListComputedStyle.marginBottom);

			let currentHeight = rootMenuListNode.offsetHeight;
			if (opendedBottom) {
				if (rootMenuListNode.offsetHeight + menuTopSpaceSize > rootSpace.bottom) {
					currentHeight = rootSpace.bottom - (menuTopSpaceSize + buttonTotalSize + menuListPaddingSize + menuListMarginSize + menuListBorderSize);
				}
			} else {
				if (rootMenuListNode.offsetHeight + menuTopSpaceSize > rootSpace.top) {
					currentHeight = rootSpace.top - (menuTopSpaceSize + buttonTotalSize + menuListPaddingSize + menuListMarginSize + menuListBorderSize);
					constraint.top = rootSpace.top - (menuTopSpaceSize + currentHeight + menuListPaddingSize + menuListMarginSize + menuListBorderSize + buttonTotalSize);
				}
			}

			let itemCount = this._computeVisibleMenuItemCount(this._getVisibleItemElements(rootMenuListNode), currentHeight);

			this._updateMenuInfo({
				viewRange: this._getMenuItemRange(itemCount),
				// overflow=visible이기 때문에 너비를 축소할 수 없어 뷰포트 너비보다 긴 텍스트의 메뉴는 정상적으로 표시할 방법이 없음.
				minContentWidth: this._getComputedItemWidth(rootMenuListNode, this._getMenuItemQuerySelector())
			});
			this._updateMenuContent();

			// 컨텐츠 크기 변경후 상단에 표시되어야할 경우
			if (opendedBottom == false) {
				constraint.top = rootRect.top - (rootMenuListNode.offsetHeight + menuTopSpaceSize + menuListMarginSize);
			}

			let style = _.mapObject(constraint, (val: number | null, key: string) => {
				if (val == null) {
					return "auto";
				}
				return val + "px";
			})

			this._getRenderer().updateStyle(this.getRootNodeName(), style, true);
		}

		protected override _getSubmenuScrollDownElement(submenuNode: HTMLElement): HTMLElement {
			return submenuNode.querySelector(".cl-navigationbar-list > .cl-arrow-down");
		}

		protected override _getSubmenuScrollUpElement(submenuNode: HTMLElement): HTMLElement {
			return submenuNode.querySelector(".cl-navigationbar-list > .cl-arrow-up");
		}

		protected override _calculateSpaceForSubmenuInViewport(ele: HTMLElement, data: { rowHeight: number, marginTop: number, submenuRect: geometry.Rectangle }): geometry.Insets {
			let space = super._calculateSpaceForSubmenuInViewport(ele, data);
			let isBottom = this._getRenderer().getNamedNode(this.getRootNodeName())?.classList.contains(ufc.Classes.BOTTOM);
			let rootClientRect = _getUnscaledClientRect(this._getRenderer().getNamedNode(this._getQName()));
			// 내비게이션바를 넘어가지 않도록 한다.
			if (isBottom) {
				space.top -= rootClientRect.top + rootClientRect.height;
			} else {
				space.bottom = this._viewportRect.top + rootClientRect.top - data.submenuRect.top;
			}
			return space;
		}

		private _updateMenuContent(style: {} = {}) {
			let menuInfo = this._getMenuInfo();
			if (menuInfo) {
				_assign(style, { "min-width": menuInfo.minContentWidth ? menuInfo.minContentWidth + "px" : "0px" });
			}

			let menuShape = this._createMenu();
			_assign(menuShape.style, style);
			this._getRenderer().replace(this._getMenuListNodeName(), menuShape);
		}

		protected _checkSubMenuHPosition(submenuNode: HTMLElement, viewportRect: geometry.Rectangle, submenuRect: geometry.Rectangle) {
			let style = {};
			let computedStyle = getComputedStyle(submenuNode);
			let paddingRight = parseInt(computedStyle.paddingRight);
			let paddingLeft = parseInt(computedStyle.paddingLeft)
			if (paddingRight > 0) {
				style["left"] = paddingRight + "px";
				submenuRect.left += paddingRight;
			} else if (paddingLeft > 0) {
				style["right"] = paddingLeft + "px";
				submenuRect.left -= paddingLeft;
			}
			if (submenuRect.right > viewportRect.right) { // overflow right
				let domTraverser = ufc._traverseFromElement(submenuNode)?._parent(this._getMenuItemQuerySelector());
				let menuItemRect = _getUnscaledClientRect(domTraverser?._getElement());
				let leftSpace = submenuRect.left - menuItemRect.width
				let rightSpace = viewportRect.right - submenuRect.left;
				let overflowLeft = (submenuRect.left - menuItemRect.width) - submenuRect.width < 0;
				if (overflowLeft) {
					if (leftSpace > rightSpace) {
						style["left"] = "auto";
						style["right"] = paddingLeft + "px";
						style["margin-right"] = "100%";
						style["margin-left"] = "auto"
					} else {
						style["left"] = paddingRight + "px";
						style["right"] = "auto";
						style["margin-left"] = "100%";
						style["margin-right"] = "auto";
					}
				} else {
					style["left"] = "auto";
					style["right"] = paddingRight + "px";
					style["margin-right"] = "100%";
					style["margin-left"] = "auto"
				}
			} else if (submenuRect.left < viewportRect.left) { // overflow left
				style["left"] = paddingLeft + "px";
				style["right"] = "auto";
				style["margin-left"] = "100%";
				style["margin-right"] = "auto";
			}
			return style;
		}

		protected override _onClickInPC(item: MenuItem, e: MouseEvent) {

			if (this._isHoveredItem(item) == false) {
				this.setHoveredItem(item);
			}
			let ignoreSelect = !this._isHoverTrigger() && item._hasChild();
			let itemSelected = false;
			if (!ignoreSelect) {
				itemSelected = this._onItemSelect(item, e);
			}
			let itemClickEvent = new cpr.events.CItemEvent(events.ItemEventType.ITEMCLICK, {
				item: item
			});
			itemClickEvent.nativeEvent = e;
			this.dispatchEvent(events.ItemEventType.ITEMCLICK, itemClickEvent);

			if (itemSelected) {
				let itemSelectedEvent = new cpr.events.CItemEvent("--internal-item-selected", {
					item: item
				})
				this.dispatchEvent("--internal-item-selected", itemSelectedEvent);
			}
		}

		/**
		 * 내비게이션바 동작에 맞추어 override 됨.
		 * @param item 
		 * @param e 
		 */
		protected override _onClickInMobile(item: MenuItem, e: TouchEvent) {
			let isHoveredItem = this._isHoveredItem(item);
			let isSelected = false;
			if (item._hasChild() == false || isHoveredItem) {
				if (isHoveredItem == false) {
					this.setHoveredItem(item);
				}
				isSelected = this._onItemSelect(item, e);
				let itemClickEvent = new cpr.events.CItemEvent(events.ItemEventType.ITEMCLICK, {
					item: item
				});
				itemClickEvent.nativeEvent = e;
				this.dispatchEvent(events.ItemEventType.ITEMCLICK, itemClickEvent);
				if (isSelected) {
					this.init();
					let itemSelectedEvent = new cpr.events.CItemEvent("--internal-item-selected", {
						item: item
					})
					itemSelectedEvent.nativeEvent = e;
					this.dispatchEvent("--internal-item-selected", itemSelectedEvent);
				}
			} else {
				this.setHoveredItem(item);
			}
		}
		/* evnet end */

	}//class

}//class