

namespace cpr.protocols.response {
	/**
	 * @private
	 */
	export class JSONResponseParser extends AbstractResponseParser<Submission> {

		constructor() {
			super();
		}

		public _loadSpecific(submission: Submission, xhr: XMLHttpRequest): void {
			// do nothing
		}

		public _abortLoading(submission: AbstractSubmission): void {
			// do nothing
		}

		public _parseSpecific(submission: Submission, xhr: XMLHttpRequest, doneHandler: () => void): void {
			let responseType: string = xhr.responseType;
			if (responseType == "blob") {
				let parser: stream.JSONBlobSAJParser = new stream.JSONBlobSAJParser();
				parser._setCallback((obj: {}) => {
					this._parseData(submission, obj, doneHandler);
				});
				parser._setErrorCallback((err: any) => {
					submission._onError(err);
				});
				parser._parse(xhr.response as Blob);
			} else {
				let response: string = xhr.responseText;
				this._parseData(submission, response, doneHandler);
			}
		}

		public _parseData(submission: Submission, stringData: {} | string, doneHandler: () => void): void {
			let jsonRes: any = null;
			if (stringData) {
				if (typeof stringData == "string") {
					try {
						if (stringData.length > 2) {
							jsonRes = JSON.parse(stringData);
						} else {
							jsonRes = {};
						}
					} catch (e) {
						submission._onError(e);
						return;
					}
				} else {
					jsonRes = stringData;
				}

				// 응답데이터를 JSONObject로 정상파싱했을 때 RECEIVE_JSON 이벤트 발생.
				let subEvent: events.CSubmissionEvent = submission._createSubmitEvent(events.SubmissionEventType.RECEIVE_JSON, { content: jsonRes });
				let isContinue: boolean = submission.dispatchEvent(subEvent);
				if (isContinue == false) {
					doneHandler();
					return;
				}
			} else {
				jsonRes = {};
			}

			// 서버로 부터 전달받은 메타데이터 처리
			if (jsonRes[Submission.METADATA_KEY]) {
				submission._setMetadata(jsonRes[Submission.METADATA_KEY]);
				delete jsonRes[Submission.METADATA_KEY];
			}

			let responseDataCount: number = submission.getResponseDataCount();
			if (responseDataCount == 0) {
				this._setMiscData(submission, jsonRes);
				doneHandler();
				return;
			}
			for (let idx: number = 0; idx < responseDataCount; idx++) {
				let responseData: ResponseData = submission.getResponseData(idx);
				let resDataCtrl: data.DataSet | data.DataMap = responseData.data;
				let dataAlias: string = responseData.alias;
				if (dataAlias == null || dataAlias == "") {
					dataAlias = resDataCtrl.id;
				}
				if (dataAlias) {
					let resData: any = jsonRes[dataAlias];
					if (resData) {
						if (resDataCtrl instanceof data.DataSet) {
							let resDataSet: data.DataSet = resDataCtrl as data.DataSet;
							let isadd: boolean = responseData.isadd === true ? true : false;
							resDataSet.build(resData, isadd);
						} else {
							let resDataMap: data.DataMap = resDataCtrl as data.DataMap;
							resDataMap.build(resData);
						}
					}
				}
			}

			this._setMiscData(submission, jsonRes);

			doneHandler();
		}

		private _setMiscData(submission: Submission, jsonRes: any): void {
			let miscKeys: string[] = _.keys(jsonRes);
			miscKeys.forEach((keyName: string) => {
				let value = jsonRes[keyName];
				if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") {
					submission._setMiscResData(keyName, value); // string, number, boolean 만 지원
				}
			});
		}

	}
}