namespace cpr.ufc {

	/**
	 * @private
	 */
	export interface LazyTask<R> {
		/**
		 * 태스크 실행 메서드.
		 */
		doTask: () => R;
	}

	/**
	 * DrawLazyTask는 UIControl의 ElementShape을 지연 생성하기 위한 LazyTask 구현체입니다.
	 * DOM이 렌더링 후 DOM을 교체해야 하는 경우에 사용됩니다.
	 * {@link create} 메서드를 통해 생성합니다.
	 * @private
	 */
	export class DrawLazyTask implements LazyTask<ufc.ElementShape> {
		owner?: core.DrawableControl;
		nodename: string;
		private _task: () => ufc.ElementShape;

		constructor(nodename: string, task: () => ufc.ElementShape, owner?: core.DrawableControl) {
			this.nodename = nodename;
			this._task = task;
			this.owner = owner;
		}

		doTask(): ufc.ElementShape {
			return this._task();
		}
	}

	/**
	 * TapLazyTask는 UIControl의 ElementShape을 지연 생성하기 위한 LazyTask 구현체입니다.
	 * DOM이 렌더링 후 단순 작업을 수행해야 하는 경우에 사용됩니다.
	 * {@link create} 메서드를 통해 생성합니다.
	 * @private
	 */
	export class TapLazyTask implements LazyTask<void> {
		private _task: () => void;

		constructor(task: () => void) {
			this._task = task;
		}

		doTask(): void {
			this._task();
		}
	}

	/**
	 * @private
	 */
	export class LazyTaskManager {
		private _lazyTasks: LazyTask<any>[];

		constructor() {
			this._lazyTasks = [];
		}

		public addLazyTask(task: LazyTask<any>): void {
			this._lazyTasks.push(task);
		}

		public runAll(run: (lazyTask: LazyTask<any>) => void): void {
			for (let lazyTask of this._lazyTasks) {
				run(lazyTask);
			}
			this._lazyTasks = [];
		}

	}

	export function _createLazyTaskManager(): LazyTaskManager {
		return new LazyTaskManager();
	}

	export type LazyTaskType = DrawLazyTask | TapLazyTask;
}