namespace cpr {
	const _OBJECT_PROTO = Object.prototype;

	export const _eq = typeof Object.is == "function"
		? Object.is
		: function (value: any, other: any): boolean {
			return value === other || (value !== value && other !== other);
		};

	function _isObject(obj: any): obj is Function | object {
		let type = typeof obj;
		return (type == "object" && !!obj) || type == "function";
	}

	function _createNativeSpreadMergeFunction(): (...sources: object[]) => object {
		return new Function(`
			var a = arguments;
			switch (a.length) {
				case 0: return {};
				case 1: return { ...a[0]};
				case 2: return { ...a[0], ...a[1] };
				case 3: return { ...a[0], ...a[1], ...a[2] };
				case 4: return { ...a[0], ...a[1], ...a[2], ...a[3] };
				case 5: return { ...a[0], ...a[1], ...a[2], ...a[3], ...a[4] };
				case 6: return { ...a[0], ...a[1], ...a[2], ...a[3], ...a[4], ...a[5] };
				case 7: return { ...a[0], ...a[1], ...a[2], ...a[3], ...a[4], ...a[5], ...a[6] };
				default: return Array.prototype.slice.call(a).reduce(function (a, b) { return { ...a, ...b } });
			}
		`) as (...sources: object[]) => object;
	}

	/**
	 * 소스 객체들의 특성을 특정 객체에 복사해 넣습니다.
	 * @param target 속성들을 지정할 대상 객체.
	 * @param sources 속성들을 공급할 소스 객체들. 우측 객체가 더 높은 우선 순위를 갖습니다.
	 * @returns 대상 객체.
	 */
	export const _assign: (target: object, ...sources: any[]) => any = _ECMA._assign
		? Object.assign
		: function (target: object) {
			let length = arguments.length;
			if (length < 2 || target == null) return target;
			for (let index = 1; index < length; index++) {
				let source = arguments[index];
				let keys = _isObject(source) ? Object.keys(source) : [];
				let l = keys.length;
				for (let i = 0; i < l; i++) {
					let key = keys[i];
					target[key] = source[key];
				}
			}
			return target;
		};

	/**
	 * 주어진 소스 객체들을 합쳐 단일 객체로 만듭니다.
	 * 속성은 마지막에 주어진 객체의 속성이 우선 순위를 갖습니다.
	 * 
	 * 아무런 객체도 주어지지 않은 경우에 빈 object를 반환하며, 하나의 객체만 주어진 경우에도 사본이 반환됩니다.
	 * 합칠 객체에 null이나 undefiend가 포함된 경우 무시 됩니다.
	 * 
	 * @param sources 합칠 객체들. 
	 * 
	 *  @see https://www.measurethat.net/Benchmarks/Show/9286/0/objectassign-vs-spread-vs-extend
	 */
	export const _mergeObject: (...sources: any[]) => any = _ECMA._spreadOperator
		? _createNativeSpreadMergeFunction()
		: (...sources: any[]) => _assign({}, ...sources)
		;

	/**
	 * 대상 객체에 속성이 존재하지 않는 경우 소스 객체의 속성을 넣습니다.
	 * {@link target}을 제외하고 왼쪽에 있을 수록 우선순위를 가집니다.
	 * 
	 * @param target 값을 넣을 대상 객체.
	 * @param sources 기본값 공급 소스 객체들.
	 */
	export function _defaults(target: object, ...sources: any[]): object & any {
		target = Object(target);
		sources.forEach(source => {
			if (source != null) {
				source = Object(source);
				for (const key in source) {
					const existingValue = target[key];
					if (existingValue === undefined || (_eq(existingValue, _OBJECT_PROTO[key]) && !target.hasOwnProperty(key))) {
						target[key] = source[key];
					}
				}
			}
		});
		return target;
	}

	/**
	 * 속성 값을 가져옵니다.
	 * @param obj 객체
	 * @param prop 속성 이름
	 * @param defaultValue 
	 */
	export function _getProperty<S extends object, K = keyof S>(obj: S, prop: K, defaultValue: any): any {
		if (!obj) {
			return defaultValue;
		}
		let propName = prop as string;

		if (obj.hasOwnProperty(propName)) {
			return obj[propName];
		}

		let propValue: any = obj[propName];
		if (propValue !== undefined) {
			return propValue;
		}

		return defaultValue;
	}


	/**
	 * default getter
	 * @param obj 
	 * @param key 
	 * @param defaultValue 
	 * @returns 
	 */
	export function _getNumber<S, K extends keyof S>(obj: S, key: K, defaultValue: number): number {
		if (obj == null || obj[key as string] == null) {
			return defaultValue;
		}
		let val: number = obj[key as string];
		return val == null ? defaultValue : val;
	}

	/**
	 * 주어진 객체가 new Object() 또는 {} 형태로 만들어진 단순 객체인지 여부를 반환합니다.
	 * Object 이외의 클래스의 인스턴스인 경우, 프로토 타입 체인을 가진 경우 false를 반환 합니다.
	 * 
	 * @param obj 단순 객체인지를 확인할 객체.
	 * @returns 단순 객체 여부.
	 */
	export function _isPlainObject(obj: any): obj is Object & object {
		return typeof obj === "object" && (obj as Object).constructor === Object && Object.getPrototypeOf(obj) === Object.prototype;
	}

	export function _objectEntryStream(obj: object): Stream<CMap.Entry<string, any>> {
		return _stream(Object.keys(obj))
			.map(key => {
				return {
					key,
					value: obj[key]
				};
			});
	}

	/**
	 * 객체의 속성들의 값들을 얻습니다.
	 */
	export const _values: (obj: object) => any[] = typeof Object["values"] === "function"
		? Object["values"]
		: (obj: object) => {
			return _stream(Object.keys(obj))
				.map(key => obj[key])
				.collect();
		}
}