namespace cpr {
	/**
	 * 여러 함수를 합쳐 하나의 함수를 만듭니다. 모든 입력함수가 true를 반환하는 경우 true를 반환하는 함수가 됩니다.
	 * @param fns 하나로 합칠 함수.
	 * @returns 합쳐진 함수.
	 */
	export function _fn_and(...fns: ((...args: any[]) => boolean)[]): (...args: any[]) => boolean {
		return (...args: any[]) => {
			return _stream(fns)
				.forall(fn => {
					if (fn.call(null, args)) {
						return true;
					} else {
						return false;
					}
				});
		}
	};

	/**
	 * 여러 함수를 합쳐 하나의 함수를 만듭니다. 입력 함수중 하나라도 true를 반환하는 경우 true를 반환하는 함수가 됩니다.
	 * @param fns 하나로 합칠 함수.
	 * @returns 합쳐진 함수.
	 */
	export function _fn_or(...fns: ((...args: any[]) => boolean)[]): (...args: any[]) => boolean {
		return (...args: any[]) => {
			return _stream(fns)
				.exists(fn => {
					if (fn.call(null, args)) {
						return true;
					} else {
						return false;
					}
				});
		}
	}
}