/// <reference path="./Header.ts"/>
namespace cpr.data.header {
	export class DataHeader extends Header {

		constructor(name: string, datatype: tabledata.DataType, defaultValue?: (string | number)) {
			if (tabledata.DataType.getAll().indexOf(datatype as string) < 0) {
				datatype = tabledata.DataType.STRING;
			}
			super(name, datatype, HeaderType.ORIGINAL_COLUMN, defaultValue);
		}

	}
}