namespace cpr.controls {

	/**
	 * 툴팁 영역에 표시되는 툴팁 객체
	 * @private
	 */
	export class TooltipArea extends Container {
		private _tooltip: controls.UIControl;
		private _styles: { [key: string]: string } = {};
		private _classNames: string[] = [];
		private _visibleTooltip: boolean = false;

		protected _isFocusable(): boolean {
			return false;
		}

		public _createShape(): ufc.ControlShape {
			let shape: ufc.ElementShape = {
				tag: "div",
				classNames: [ufc.Classes.TOOLTIP_ASIDE_LAYER],
				attr: {
					"aria-hidden": "true"
				},
				style: {
					"z-index": "1"
				},
				children: []
			};
			if (this._tooltip) {
				let tooltip: ufc.ElementShape = {
					tag: "div",
					attr: {
						role: "tooltip",
						id: this._getTooltipDOMUUID(),
						"data-role": "tooltip"
					},
					classNames: ["cl-tooltip"],
					nodename: "tooltip",
					style: {
						position: "absolute",
						"z-index": "2", // 내비게이션바의 서브메뉴에 z-index가 있어 1의 값으로는 위로 나올 수 없음.
						"box-sizing": "border-box",
						"pointer-events": "none",
						opacity: "0"
					},
					children: [this._tooltip._getRenderer()]
				}
				if (this._visibleTooltip) {
					delete tooltip.style["opacity"];
					delete tooltip.style["pointer-events"];
				}
				_assign(tooltip.style, this._styles);
				tooltip.classNames = tooltip.classNames.concat(this._classNames);
				shape.children[shape.children.length] = tooltip;
			}
			return shape;
		}
		/**
		 * 툴팁을 보여주는지 여부를 반환합니다.
		 * @returns 
		 */
		public _isShowingTooltip(): boolean {
			return this._visibleTooltip;
		}

		/**
		 * 툴팁의 DOM id를 반환합니다.
		 * @returns 
		 */
		private _getTooltipDOMUUID(): string {
			return ufc.NodeUUIDMapper.INSTANCE._createPartialUUID(this, "tooltip");
		}
		/**
		 * 툴팁이 표시되는 위치와 크기를 반환합니다.
		 * @returns 
		 */
		public _getTootipUnscaledActualRect(): geometry.Rectangle {
			let rect: geometry.Rectangle = new geometry.Rectangle();

			if (this.disposed === true) {
				return rect;
			}
			let renderer: ufc.ControlRenderer = this._getRenderer();
			if (renderer == null || renderer.hasDrawn() == false) {
				return rect;
			}
			let targetNode: HTMLElement = renderer.getNamedNode("tooltip");
			if (!targetNode) {
				return rect;
			}

			let domRect: ClientRect = targetNode.getBoundingClientRect();
			if (domRect) {
				rect.width = domRect.width;
				rect.height = domRect.height;
				rect.left = domRect.left;
				rect.top = domRect.top;
			}
			return _getUnscaledClientRect(rect);
		}

		public _getType(): ControlType {
			return ControlType.TOOLTIPAREA;
		}

		/**
		 * 툴팁에 대한 정보를 지웁니다.
		 * @returns 
		 */
		public _clearTooltip(): void {
			if (!this._tooltip) {
				return;
			}
			this.removeChild(this._tooltip);
			this._visibleTooltip = false;
			this._styles = {};
			this._classNames = [];
			this._tooltip = null;
			this.redraw();
		}
		/**
		 * 툴팁을 표시합니다.
		 */
		public _showTooltip(): void {
			this._visibleTooltip = true;
			this.redraw();
		}
		/**
		 * 툴팁을 숨깁니다.
		 */
		public _hiddenTooltip(): void {
			this._visibleTooltip = false;
			this.redraw();
		}
		/**
		 * 툴팁 UIControl을 반환합니다.
		 * @returns 
		 */
		public _getTooltip(): UIControl {
			return this._tooltip;
		}

		/**
		 * 툴팁 UIControl을 설정합니다.
		 * @param tooltip 
		 */
		public _setTooltip(tooltip: controls.UIControl): void {
			if (this._tooltip) {
				this.removeChild(this._tooltip);
			}
			this._tooltip = tooltip;
			this.addChild(tooltip);
		}

		/**
		 * 툴팁의 스타일을 업데이트합니다.
		 * @param styles 
		 */
		public _updateTooltipStyle(styles: { [key: string]: string }): void {
			this._styles = styles;
			this.redraw();
		}
		/**
		 * 툴팁의 클래스를 업데이트합니다.
		 * @param classNames 
		 */
		public _updateTooltipClasses(classNames: string[] = []): void {
			this._classNames = classNames;
			this.redraw();
		}
	}
}
